INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2353}/[H2357]', 'inflected', 'heb', 'חוּר', '["chûwr"]', '["and/ white cloth"]', '["n-m"]', 'white linen white.', 'from 2357;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5850}/[H5849]', 'inflected', 'heb', 'עֲטָרָה', '["ʻăṭârâh"]', '["and/ a crown of"]', '["n-f"]', 'a crown crown.', 'from 5849;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H8509>', 'inflected', 'heb', 'ותכריך', '["ve./takh.Rikh"]', '["and/ a robe of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6670A}/[H6670]', 'lemma', 'heb', 'צָהַל', '["tsâhal"]', '["cry aloud","it shouted for joy","they neigh","they will cry aloud"]', '["v"]', 'to gleam, i.e. (figuratively) be cheerful; by transference to sound clear (of various animal or human expressions) bellow, cry aloud (out), lift up, neigh, rejoice, make to shine, shout.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0219A}/[H216]', 'lemma', 'heb', 'אוֹרָה', '["ʼôwrâh"]', '["light","lights"]', '["n-f"]', 'luminousness, i.e. (figuratively) prosperity; also a plant (as being bright) herb, light.', 'feminine of 216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8342}/[H7797]', 'inflected', 'heb', 'שָׂשׂוֹן', '["sâsôwn"]', '["and/ joy"]', '["n-m"]', 'cheerfulness; specifically, welcome gladness, joy, mirth, rejoicing.', 'or שָׂשֹׂן; from 7797;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3366}/[H3365]', 'inflected', 'heb', 'יְקָר', '["yᵉqâr"]', '["and/ honor","and/ precious thing[s]"]', '["n-m"]', 'value, i.e. (concretely) wealth; abstractly, costliness, dignity honour, precious (things), price.', 'from 3365;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3054}/[H3061]', 'lemma', 'heb', 'יָהַד', '["yâhad"]', '["[were] becoming Jews"]', '["v"]', 'to Judaize, i.e. become Jewish become Jews.', 'denominative from a form corresponding to 3061;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7980}/[H7980]', 'inflected', 'heb', 'שָׁלַט', '["shâlaṭ"]', '["to/ domineer"]', '["v"]', 'to dominate, i.e. govern; by implication, to permit (bear, have) rule, have dominion, give (have) power.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8130}/H9038/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["among/ [those who] hated/ them","over/ [those who] hated/ them"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1245}/[H1245]', 'inflected', 'heb', 'בָּקַשׁ', '["bâqash"]', '["on/ those seeking"]', '["v"]', 'to search out (by any method, specifically in worship or prayer); by implication, to strive after ask, beg, beseech, desire, enquire, get, make inquisition, procure, (make) request, require, seek (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7451C}/H9028/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["<of> harm/ their","calamity/ their"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6343}/H9028/[H6342]', 'inflected', 'heb', 'פַּחַד', '["pachad"]', '["dread of/ them"]', '["n-m"]', 'a (sudden) alarm (properly, the object feared, by implication, the feeling) dread(-ful), fear, (thing) great (fear, -ly feared), terror.', 'from 6342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0323}/[H323]', 'inflected', 'heb', 'אֲחַשְׁדַּרְפַּן', '["ʼăchashdarpan"]', '["and/ the/ satraps"]', '["n-m"]', 'a satrap or governor of a main province (of Persia) lieutenant.', 'of Persian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6213J}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["and/ [the] doers of"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1004P}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["[was] in/ [the] house of","in/ [the] house of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8089}/H9023/[H8085]', 'inflected', 'heb', 'שֹׁמַע', '["shômaʻ"]', '["and/ [the] report of/ him"]', '["n-m"]', 'a report fame.', 'from 8085;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1431}\/[H1434]', 'inflected', 'heb', 'גָּדַל', '["gâdal"]', '["and/ becoming great"]', '["v"]', 'to be (causatively make) large (in various senses, as in body, mind, estate or honor, also in pride) advance, boast, bring up, exceed, excellent, be(-come, do, give, make, wax), great(-er, come to... estate, things), grow(up), increase, lift up, magnify(-ifical), be much set by, nourish (up), pass, promote, proudly (spoken), tower.', 'a primitive root; properly, to twist (compare 1434), i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2027}/[H2026]', 'inflected', 'heb', 'הֶרֶג', '["hereg"]', '["and/ slaughter"]', '["n-m"]', 'slaughter be slain, slaughter.', 'from 2026;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0012}/[H6]', 'inflected', 'heb', 'אַבְדָן', '["ʼabdân"]', '["and/ destruction"]', '["n-m"]', 'a perishing destruction.', 'from 6;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7800}/[H7799]', 'inflected', 'heb', 'שׁוּשַׁן', '["Shûwshan"]', '["and/ in/ Susa"]', '["n-pr-loc"]', 'Shushan, a place in Persia Shushan.', 'the same as 7799;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0006}/[H6]', 'inflected', 'heb', 'אָבַד', '["ʼâbad"]', '["and/ destroying","and/ they destroyed","and/ they have destroyed","and/ they may perish","and/ you may perish","so/ he may destroy","so/ it may destroy","so/ they may perish"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6577}/[H6577]', 'lemma', 'heb', 'פַּרְשַׁנְדָּתָא', '["Parshandâthâʼ"]', '["Parshandatha"]', '["n-pr-m"]', 'Parshandatha, a son of Haman Parshandatha.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1813}/[H1811]', 'lemma', 'heb', 'דַּלְפוֹן', '["Dalphôwn"]', '["Dalphon"]', '["n-pr-m"]', 'Dalphon, a son of Haman Dalphon.', 'from 1811; dripping;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0630}/[H630]', 'lemma', 'heb', 'אַסְפָּתָא', '["ʼAçpâthâʼ"]', '["Aspatha"]', '["n-pr-m"]', 'Aspatha, a son of Haman Aspatha.', 'of Persian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6334}/[H6334]', 'lemma', 'heb', 'פּוֹרָתָא', '["Pôwrâthâʼ"]', '["Poratha"]', '["n-pr-m"]', 'Poratha, a son of Haman Poratha.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0118}/[H118]', 'lemma', 'heb', 'אֲדַלְיָא', '["ʼĂdalyâʼ"]', '["Adalia"]', '["n-pr-m"]', 'Adalja, a son of Haman Adalia.', 'of Persian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0743}/[H743]', 'lemma', 'heb', 'אֲרִידָתָא', '["ʼĂrîydâthâʼ"]', '["Aridatha"]', '["n-pr-m"]', 'Aridatha, a son of Haman Aridatha.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6534}/[H6534]', 'lemma', 'heb', 'פַּרְמַשְׁתָּא', '["Parmashtâʼ"]', '["Parmashta"]', '["n-pr-m"]', 'Parmashta, a son of Haman Parmasta.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0747}/[H747]', 'lemma', 'heb', 'אֲרִיסַי', '["ʼĂrîyçay"]', '["Arisai"]', '["n-pr-m"]', 'Arisai, a son of Haman Arisai.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0742}/[H742]', 'lemma', 'heb', 'אֲרִידַי', '["ʼĂrîyday"]', '["Aridai"]', '["n-pr-m"]', 'Aridai, a son of Haman Aridai.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2055>', 'opaque', 'heb', 'וַיְזָתָא', '["Vayzâthâʼ"]', '["Vaizatha"]', '["n-pr-m"]', 'Vajezatha, a son of Haman Vajezatha.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2026}/[H2026]', 'inflected', 'heb', 'הָרַג', '["hârag"]', '["those/ killed"]', '["v"]', 'to smite with deadly intent destroy, out of hand, kill, murder(-er), put to (death), make (slaughter), slay(-er), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7605}/[H7604]', 'inflected', 'heb', 'שְׁאָר', '["shᵉʼâr"]', '["in/ [the] rest of"]', '["n-m"]', 'a remainder × other, remnant, residue, rest.', 'from 7604;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5118}/[H5117]', 'inflected', 'heb', 'נוּחַ', '["nûwach"]', '["and/ they had rest"]', '["n-m"]', 'quiet rest(-ed, -ing place).', 'or נוֹחַ; from 5117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6519}/[H6518]', 'inflected', 'heb', 'פְּרָזָה', '["pᵉrâzâh"]', '["the/ open regions"]', '["n-f"]', 'an open country (unwalled) town (without walls), unwalled village.', 'from the same as 6518;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4916B}/[H7971]', 'inflected', 'heb', 'מִשְׁלוֹחַ', '["mishlôwach"]', '["and/ [the] sending of"]', '["n-m"]', 'a sending out, i.e. (abstractly) presentation (favorable), or seizure (unfavorable); also (concretely) a place of dismissal, or a business to be discharged to lay, to put, sending (forth), to set.', 'or מִשְׁלֹחַ; also מִשְׁלָח; from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7350}/[H7368]', 'inflected', 'heb', 'רָחוֹק', '["râchôwq"]', '["and/ <the>/ far","and/ the/ [nations] far off"]', '["a"]', 'remote, literally or figuratively, of place or time; specifically, precious; often used adverbially (with preposition) (a-) far (abroad, off), long ago, of old, space, great while to come.', 'or רָחֹק; from 7368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2320G}/[H2318]', 'inflected', 'heb', 'חֹדֶשׁ', '["chôdesh"]', '["and/ the/ month"]', '["n-m"]', 'the new moon; by implication, a month month(-ly), new moon.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3015}/[H3013]', 'inflected', 'heb', 'יָגוֹן', '["yâgôwn"]', '["from/ sorrow"]', '["n-m"]', 'affliction grief, sorrow.', 'from 3013;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0060}/[H56]', 'inflected', 'heb', 'אֵבֶל', '["ʼêbel"]', '["and/ from/ mourning"]', '["n-m"]', 'lamentation mourning.', 'from 56;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4979}/[H4976]', 'inflected', 'heb', 'מַתָּנָה', '["mattânâh"]', '["and/ gifts"]', '["n-f"]', 'a present; specifically (in a good sense), a sacrificial offering, (in a bad sense) a bribe gift.', 'feminine of 4976;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0034}/[H14]', 'inflected', 'heb', 'אֶבְיוֹן', '["ʼebyôwn"]', '["[belonged] to the/ needy [person]","for the/ needy [person]","to <the>/ needy [people]","to the/ needy [people]","to the/ needy [person]"]', '["a-m"]', 'destitute beggar, needy, poor (man).', 'from 14, in the sense of want (especially in feeling);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0006}/H9038/[H6]', 'inflected', 'heb', 'אָבַד', '["ʼâbad"]', '["and/ to/ destroy/ them"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0935G}/H9044/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ when/ came/ it","and/ when/ comes/ it"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6332}/[H6331]', 'inflected', 'heb', 'פּוּר', '["Pûwr"]', '["the/ Pur","the/ Purim"]', '["n-m"]', 'a lot (as by means of a broken piece) Pur, Purim.', 'also (plural) פּוּרִים; or פֻּרִים; from 6331;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0107}/[H104]', 'inflected', 'heb', 'אִגֶּרֶת', '["ʼiggereth"]', '["the/ letter"]', '["n-f"]', 'an epistle letter.', 'feminine of 104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2233H}/H9028/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["offspring/ their"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3867A}/[H3867]', 'inflected', 'heb', 'לָוָה', '["lâvâh"]', '["who/ <he> has joined himself","who/ join themselves","who/ joined themselves"]', '["v"]', 'properly, to twine, i.e. (by implication) to unite, to remain; also to borrow (as a form of obligation) or (caus.) to lend abide with, borrow(-er), cleave, join (self), lend(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H2165}/H9028/[H2163]', 'inflected', 'heb', 'זְמָן', '["zᵉmân"]', '["and/ according to/ appointed time/ their"]', '["n-m"]', 'an appointed occasion season, time.', 'from 2163;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2143}/H9028/[H2142]', 'inflected', 'heb', 'זֵכֶר', '["zêker"]', '["and/ remembrance/ their"]', '["n-m"]', 'a memento, abstractly recollection (rarely if ever); by implication, commemoration memorial, memory, remembrance, scent.', 'or זֶכֶר; from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5486}/[H5486]', 'lemma', 'heb', 'סוּף', '["çûwph"]', '["I will bring to an end","it will cease","they come to an end","they will come to an end"]', '["v"]', 'to snatch away, i.e. terminate consume, have an end, perish, × be utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2233H}/H9028\/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["from/ offspring/ their"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8633}/[H8630]', 'lemma', 'heb', 'תֹּקֶף', '["tôqeph"]', '["authority"]', '["n-m"]', 'might or (figuratively) positiveness authority, power, strength.', 'from 8630;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0571H}/[H539]', 'inflected', 'heb', 'אֶמֶת', '["ʼemeth"]', '["and/ [was] truth","and/ truth"]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2165}/H9028/[H2163]', 'inflected', 'heb', 'זְמָן', '["zᵉmân"]', '["at/ appointed times/ their"]', '["n-m"]', 'an appointed occasion season, time.', 'from 2163;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0635}/[H635]', 'inflected', 'heb', 'אֶסְתֵּר', '["ʼEçtêr"]', '["and/ Esther"]', '["n-pr-f"]', 'Ester, the Jewish heroine Esther.', 'of Persian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6685}/[H6684]', 'inflected', 'heb', 'צוֹם', '["tsôwm"]', '["the/ fasts"]', '["n-m"]', 'a fast fast(-ing).', 'or צֹם; from 6684;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2201}/H9028/[H2199]', 'inflected', 'heb', 'זַעַק', '["zaʻaq"]', '["and/ cry of distress/ their"]', '["n-f"]', 'a shriek or outcry cry(-ing).', 'and (feminine) זְעָקָהxlit zᵉâqâh corrected to zᵉʻâqâh; from 2199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3982}/[H559]', 'inflected', 'heb', 'מַאֲמַר', '["maʼămar"]', '["and/ [the] command of"]', '["n-m"]', 'something (authoritatively) said, i.e. an edict commandment, decree.', 'from 559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5612A}\/[H9]', 'inflected', 'heb', 'סֵפֶר', '["çêpher"]', '["in the/ book"]', '["n-m"]', 'properly, writing (the art or a document); by implication, a book bill, book, evidence, × learn(-ed) (-ing), letter, register, scroll.', 'or (feminine) סִפְרָה; (Psalm 56:8 (9)), from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0339}/[H183]', 'inflected', 'heb', 'אִי', '["ʼîy"]', '["and/ [the] islands","and/ [the] islands of"]', '["n-m"]', 'properly, a habitable spot (as desirable); dry land, a coast, an island country, isle, island.', 'from 183;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8633}/H9023/[H8630]', 'inflected', 'heb', 'תֹּקֶף', '["tôqeph"]', '["power/ his"]', '["n-m"]', 'might or (figuratively) positiveness authority, power, strength.', 'from 8630;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6575}/[H6567]', 'inflected', 'heb', 'פָּרָשָׁה', '["pârâshâh"]', '["and/ [the] full account of"]', '["n-f"]', 'exposition declaration, sum.', 'from 6567;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4074H}/[H4074]', 'lemma', 'heb', 'מָדַי', '["Mâday"]', '["Media","O Media"]', '["n-pr-m n-pr-loc"]', 'Madai, a country of central Asia Madai, Medes, Media.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6539>', 'inflected', 'heb', 'ופרס', '["u./fa.Ras"]', '["and/ Persia"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5780J}/[H5779]', 'lemma', 'heb', 'עוּץ', '["ʻÛwts"]', '["Uz"]', '["n-pr-m n-pr-loc"]', 'Uts, a son of Aram, also a Seirite, and the regions settled by them. Uz.', 'apparently from 5779; consultation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0347}/[H340]', 'lemma', 'heb', 'אִיּוֹב', '["ʼÎyôwb"]', '["Job","O Job","[was] Job"]', '["n-pr-m"]', 'Ijob, the patriarch famous for his patience Job.', 'from 340; hated (i.e. persecuted);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3373}/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["and/ [one] fearing","and/ fearing"]', '["a"]', 'fearing; morally, reverent afraid, fear (-ful).', 'from 3372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7451B}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["from/ evil"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7854}/[H7853]', 'inflected', 'heb', 'שָׂטָן', '["sâṭân"]', '["O/ accuser","the/ accuser","the/ adversary"]', '["n-m"]', 'an opponent; especially (with the article prefixed) Satan, the arch-enemy of good adversary, Satan, withstand.', 'from 7853;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7751A}/[H7751]', 'inflected', 'heb', 'שׁוּט', '["shûwṭ"]', '["from/ roving about"]', '["v"]', 'properly, to push forth; (but used only figuratively) to lash, i.e. (the sea with oars) to row; by implication, to travel go (about, through, to and fro), mariner, rower, run to and fro.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1980I}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ from/ going about"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7760K}/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["¿/ have you set"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H2600}/[H2580]', 'inflected', 'heb', 'חִנָּם', '["chinnâm"]', '["¿/ in vain"]', '["adv"]', 'gratis, i.e. devoid of cost, reason or advantage without a cause (cost, wages), causeless, to cost nothing, free(-ly), innocent, for nothing (nought, in vain.', 'from 2580;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7753}/[H7753]', 'lemma', 'heb', 'שׂוּךְ', '["sûwk"]', '["[am] about to fence up","have you put a hedge"]', '["v"]', 'to entwine, i.e. shut in (for formation, protection or restraint) fence, (make an) hedge (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4735}/H9023/[H7069]', 'inflected', 'heb', 'מִקְנֶה', '["miqneh"]', '["and/ livestock/ his"]', '["n-m"]', 'something bought, i.e. property, but only live stock; abstractly, acquisition cattle, flock, herd, possession, purchase, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0860}/[H386]', 'inflected', 'heb', 'אָתוֹן', '["ʼâthôwn"]', '["and/ the/ female donkeys"]', '["n-f"]', 'a female donkey (from its docility) (she) ass.', 'probably from the same as 386 (in the sense of patience);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4422}/H9012/[H4422]', 'inflected', 'heb', 'מָלַט', '["mâlaṭ"]', '["and/ I have escaped/ !"]', '["v"]', 'properly, to be smooth, i.e. (by implication) to escape (as if by slipperiness); causatively, to release or rescue; specifically, to bring forth young, emit sparks deliver (self), escape, lay, leap out, let alone, let go, preserve, save, × speedily, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5288}/[H5287]', 'inflected', 'heb', 'נַעַר', '["naʻar"]', '["and/ <on> the/ servants"]', '["n-m"]', '(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man).', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1494}/[H1468]', 'inflected', 'heb', 'גָּזַז', '["gazâz"]', '["and/ he shaved"]', '["v"]', 'to cut off; specifically to shear a flock or shave the hair; figuratively to destroy an enemy cut off (down), poll, shave, (sheep-) shear(-er).', 'a primitive root (akin to 1468);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6174}/[H6191]', 'inflected', 'heb', 'עָרוֹם', '["ʻârôwm"]', '["and/ naked"]', '["a"]', 'nude, either partially or totally naked.', 'or עָרֹם; from 6191 (in its original sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8604}/[H8602]', 'lemma', 'heb', 'תִּפְלָה', '["tiphlâh"]', '["offensiveness","unseemliness"]', '["n-f"]', 'frivolity folly, foolishly.', 'from the same as 8602;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5750}/H9043/[H5749]', 'inflected', 'heb', 'עוֹד', '["ʻôwd"]', '["and/ still/ he"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8538}/H9023/[H8537]', 'inflected', 'heb', 'תֻּמָּה', '["tummâh"]', '["on/ integrity/ his"]', '["n-f"]', 'innocence integrity.', 'feminine of 8537;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5496}/H9030/[H7898]', 'inflected', 'heb', 'סוּת', '["çûwth"]', '["and/ you incited/ me"]', '["v"]', 'properly, to prick, i.e. (figuratively) stimulate; by implication, to seduce entice, move, persuade, provoke, remove, set on, stir up, take away.', 'perhaps denominative from 7898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1104}/H9033/[H1104]', 'inflected', 'heb', 'בָּלַע', '["bâlaʻ"]', '["to/ ruin/ him"]', '["v"]', 'to make away with (specifically by swallowing); generally, to destroy cover, destroy, devour, eat up, be at end, spend up, swallow down (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0199}/[H194]', 'lemma', 'heb', 'אוּלָם', '["ʼûwlâm"]', '["but"]', '["adv"]', 'however or on the contrary as for, but, howbeit, in very deed, surely, truly, wherefore.', 'apparently a variation of 194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1623}/[H1623]', 'inflected', 'heb', 'גָּרַד', '["gârad"]', '["to/ scrape himself"]', '["v"]', 'to abrade scrape.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0665>', 'inflected', 'heb', 'האפר', '["ha./''E.fer"]', '["<the>/ ash[es]","the/ ash[es]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8538}/H9021/[H8537]', 'inflected', 'heb', 'תֻּמָּה', '["tummâh"]', '["on/ integrity/ your"]', '["n-f"]', 'innocence integrity.', 'feminine of 8537;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8193G}/H9023\/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["with/ lips/ his"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0464H}/[H410]', 'lemma', 'heb', 'אֱלִיפַז', '["ʼĔlîyphaz"]', '["Eliphaz"]', '["n-pr-m"]', 'Eliphaz, the name of one of Job''s friends, and of a son of Esau Eliphaz.', 'from 410 and 6337; God of gold;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1085>', 'inflected', 'heb', 'ובלדד', '["u./vil.Dad"]', '["and/ Bildad"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7747}/[H7744]', 'inflected', 'heb', 'שׁוּחִי', '["Shûwchîy"]', '["the/ Shuhite"]', '["a"]', 'a Shuchite or descendant of Shuach Shuhite.', 'patronymic from 7744;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6691}/[H6852]', 'inflected', 'heb', 'צוֹפַר', '["Tsôwphar"]', '["and/ Zophar"]', '["n-pr-m"]', 'Tsophar, a friend of Job Zophar.', 'from 6852; departing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5284}/[H5279]', 'inflected', 'heb', 'נַעֲמָתִי', '["Naʻămâthîy"]', '["the/ Naamathite"]', '["a"]', 'a Naamathite, or inhabitant of Naamah Naamathite.', 'patrial from a place corresponding in name (but not identical) with 5279;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5162G}/H9033/[H5162]', 'inflected', 'heb', 'נָחַם', '["nâcham"]', '["and/ to/ comfort/ him"]', '["v"]', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0776H>', 'inflected', 'heb', 'לארץ', '["La./''a.retz","la./''A.retz"]', '["<to> the/ ground","of the/ earth","to the/ earth","to the/ ground"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3511}/[H3510]', 'inflected', 'heb', 'כְּאֵב', '["kᵉʼêb"]', '["the/ pain"]', '["n-m"]', 'suffering (physical or mental), adversity grief, pain, sorrow.', 'from 3510;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3915}/[H3883]', 'inflected', 'heb', 'לַיִל', '["layil"]', '["and/ the/ night"]', '["n-m"]', 'properly, a twist (away of the light), i.e. night; figuratively, adversity (mid-)night (season).', 'or (Isaiah 21:11) לֵיל; also לַיְלָה; from the same as 3883;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5105}/[H5102]', 'lemma', 'heb', 'נְהָרָה', '["nᵉhârâh"]', '["daylight"]', '["n-f"]', 'daylight light.', 'from 5102 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6757}/[H6738]', 'inflected', 'heb', 'צַלְמָוֶת', '["tsalmâveth"]', '["and/ deep darkness"]', '["n-m"]', 'shade of death, i.e. the grave (figuratively, calamity) shadow of death.', 'from 6738 and 4194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6053}/[H6051]', 'lemma', 'heb', 'עֲנָנָה', '["ʻănânâh"]', '["cloud"]', '["n-f"]', 'cloudiness cloud.', 'feminine of 6051;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1204}/H9033/[H1204]', 'inflected', 'heb', 'בָּעַת', '["bâʻath"]', '["let them terrify/ it","they terrify/ him"]', '["v"]', 'to fear affright, be (make) afraid, terrify, trouble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3650}/[H3648]', 'lemma', 'heb', 'כִּמְרִיר', '["kimrîyr"]', '["[the] darkness<es> of"]', '["n-m"]', 'obscuration (as if from shrinkage of light), i.e. an eclipse (only in plural) blackness.', 'redupl. from 3648;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0652}/[H651]', 'lemma', 'heb', 'אֹפֶל', '["ʼôphel"]', '["darkness","gloom","gloom of"]', '["n-m"]', 'dusk darkness, obscurity, privily.', 'from the same as 651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2302}/[H2302]', 'lemma', 'heb', 'חָדָה', '["châdâh"]', '["it rejoice"]', '["v"]', 'to rejoice make glad, be joined, rejoice.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1565}/[H1563]', 'lemma', 'heb', 'גַּלְמוּד', '["galmûwd"]', '["[is] barren","barren"]', '["a"]', 'sterile (as wrapped up too hard); figuratively, desolate desolate, solitary.', 'probably by prolonged from 1563;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7445}/[H7442]', 'lemma', 'heb', 'רְנָנָה', '["rᵉnânâh"]', '["[the] cry of joy of","a cry of joy","cries of joy"]', '["n-f"]', 'a shout (for joy) joyful (voice), singing, triumphing.', 'from 7442;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6264}/[H6257]', 'inflected', 'heb', 'עָתִיד', '["ʻâthîyd"]', '["the/ [ones] ready"]', '["a"]', 'prepared; by implication, skilful; feminine plural the future; also treasure things that shall come, ready, treasures.', 'from 6257;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3882}/[H3867]', 'lemma', 'heb', 'לִוְיָתָן', '["livyâthân"]', '["Leviathan"]', '["n-m"]', 'a wreathed animal, i.e. a serpent (especially the crocodile or some other large sea-monster); figuratively, the constellation of the dragon; also as a symbol of Babylon leviathan, mourning.', 'from 3867;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2821}/[H2821]', 'lemma', 'heb', 'חָשַׁךְ', '["châshak"]', '["[is] making dark","he makes dark","he will bring darkness","it grows dark","it has become dark","it is [too] dark","it is dark","it will be dark","it will become dark","let them grow dark","may they grow dim","they have grown dim"]', '["v"]', 'to be dark (as withholding light); transitively, to darken be black, be (make) dark, darken, cause darkness, be dim, hide.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5399}/H9023/[H5398]', 'inflected', 'heb', 'נֶשֶׁף', '["nesheph"]', '["twilight/ its"]', '["n-m"]', 'properly, a breeze, i.e. (by implication) dusk (when the evening breeze prevails) dark, dawning of the day (morning), night, twilight.', 'from 5398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6079}/[H5774]', 'inflected', 'heb', 'עַפְעַף', '["ʻaphʻaph"]', '["on/ [the] eyelids of"]', '["n-m"]', 'an eyelash (as fluttering); figuratively, morning ray dawning, eye-lid.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7837}/[H7836]', 'lemma', 'heb', 'שַׁחַר', '["shachar"]', '["<of> dawn","[the] dawn","dawn"]', '["n-m"]', 'dawn (literal, figurative or adverbial) day(-spring), early, light, morning, whence riseth.', 'from 7836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0990H>/H9020', 'opaque', 'heb', 'בֶּטֶן', '["beṭen"]', '["womb/ my"]', '["n-f"]', 'the belly, especially the womb; also the bosom or body of anything belly, body, as they be born, within, womb.', 'from an unused root probably meaning to be hollow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1478}/[H1478]', 'inflected', 'heb', 'גָּוַע', '["gâvaʻ"]', '["and/ I may expire","and/ I may expire?","and/ [have been] about to die","and/ they may expire"]', '["v"]', 'to breathe out, i.e. (by implication) expire die, be dead, give up the ghost, perish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4390}/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["those/ [who] fill","those/ [who] filled"]', '["v"]', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly.', 'or מָלָא; (Esther 7:5), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5309}/[H5307]', 'inflected', 'heb', 'נֶפֶל', '["nephel"]', '["like/ a miscarriage"]', '["n-m"]', 'something fallen, i.e. an abortion untimely birth.', 'or נֵפֶל; from 5307;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5768}/[H5763]', 'inflected', 'heb', 'עוֹלֵל', '["ʻôwlêl"]', '["like/ children"]', '["n-m"]', 'a suckling babe, (young) child, infant, little one.', 'or עֹלָל; from 5763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7267}/[H7264]', 'lemma', 'heb', 'רֹגֶז', '["rôgez"]', '["turmoil"]', '["n-m"]', 'commotion, restlessness (of a horse), crash (of thunder), disquiet, anger fear, noise, rage, trouble(-ing), wrath.', 'from 7264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3019}/[H3021]', 'lemma', 'heb', 'יָגִיעַ', '["yâgîyaʻ"]', '["weary [ones] of"]', '["a"]', 'tired weary.', 'from 3021;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7599}/[H7599]', 'lemma', 'heb', 'שָׁאַן', '["shâʼan"]', '["it has been at ease","they are at ease"]', '["v"]', 'to loll, i.e. be peaceful be at ease, be quiet, rest. See also 1052.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H0113>/H9023', 'inflected', 'heb', 'מאדניו', '["me./''a.do.Na/v"]', '["from/ master<s>/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6001A}/[H5998]', 'inflected', 'heb', 'עָמֵל', '["ʻâmêl"]', '["to/ a sufferer"]', '["n-m a"]', 'toiling; concretely, a laborer; figuratively, sorrowful that laboureth, that is a misery, had taken (labour), wicked, workman.', 'from 5998;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2416E}/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["and/ life"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2442}/[H2707]', 'inflected', 'heb', 'חָכָה', '["châkâh"]', '["[is] the/ [one who] waits","those/ [who] long"]', '["v"]', 'properly, to adhere to; hence, to await long, tarry, wait.', 'a primitive root (apparently akin to 2707 through the idea of piercing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2658}/H9033/[H2658]', 'inflected', 'heb', 'חָפַר', '["châphar"]', '["and/ he has dug/ it","and/ they dug for/ it"]', '["v"]', 'properly, to pry into; by implication, to delve, to explore dig, paw, search out, seek.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4301}/[H2934]', 'inflected', 'heb', 'מַטְמוֹן', '["maṭmôwn"]', '["more than/ hidden treasures"]', '["n-m"]', 'a secret storehouse; hence, a secreted valuable (buried); generally money hidden riches, (hid) treasure(-s).', 'or מַטְמֹן; or מַטְמֻן; from 2934;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8056}/[H8055]', 'inflected', 'heb', 'שָׂמֵחַ', '["sâmêach"]', '["the/ [ones] joyful","the/ joyful [people]"]', '["a"]', 'blithe or gleeful (be) glad, joyful, (making) merry((-hearted), -ily), rejoice(-ing).', 'from 8055;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1524A}/[H1523]', 'lemma', 'heb', 'גִּיל', '["gîyl"]', '["rejoicing"]', '["n-m"]', 'a revolution (of time, i.e. an age); also joy × exceedingly, gladness, × greatly, joy, rejoice(-ing), sort.', 'from 1523;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5526A}/[H5526]', 'inflected', 'heb', 'סָכַךְ', '["çâkak"]', '["and/ he has made inaccessible","and/ he shut off"]', '["v"]', 'properly, to entwine as a screen; by implication, to fence in, cover over, (figuratively) protect cover, defence, defend, hedge in, join together, set, shut up.', 'or שָׂכַךְ; (Exodus 33:22), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0585}/H9020/[H584]', 'inflected', 'heb', 'אֲנָחָה', '["ʼănâchâh"]', '["groaning/ my","groaning<s>/ my"]', '["n-f"]', 'sighing groaning, mourn, sigh.', 'from 584;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7581}/H9020/[H7580]', 'inflected', 'heb', 'שְׁאָגָה', '["shᵉʼâgâh"]', '["cries of distress/ my","cry of distress/ my"]', '["n-f"]', 'a rumbling or moan roaring.', 'from 7580;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0857}/H9030/[H225]', 'inflected', 'heb', 'אָתָה', '["ʼâthâh"]', '["and/ it came to/ me"]', '["v"]', 'to arrive (be-, things to) come (upon), bring.', 'or אָתָא; a primitive root (collateral to 225 contraction);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7951}/[H7951]', 'lemma', 'heb', 'שָׁלָה', '["shâlâh"]', '["I am at ease","are they at ease?","may they be at ease","they are at ease","they are at peace"]', '["v"]', 'to be tranquil, i.e. secure or successful be happy, prosper, be in safety.', 'or שָׁלַו; (Job 3:26), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7267}\/[H7264]', 'inflected', 'heb', 'רֹגֶז', '["rôgez"]', '["turmoil"]', '["n-m"]', 'commotion, restlessness (of a horse), crash (of thunder), disquiet, anger fear, noise, rage, trouble(-ing), wrath.', 'from 7264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3811}/[H3811]', 'lemma', 'heb', 'לָאָה', '["lâʼâh"]', '["I am weary","I had wearied myself","[is] to make weary","he is weary","it has made weary","it has wearied itself","they are weary","will you be impatient?","you have become weary","you will make weary"]', '["v"]', 'to tire; (figuratively) to be (or make) disgusted faint, grieve, lothe, (be, make) weary (selves).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4405}/[H4448]', 'inflected', 'heb', 'מִלָּה', '["millâh"]', '["<in>/ words","by/ words","with/ words"]', '["n-f"]', 'a word; collectively, a discourse; figuratively, a topic answer, by-word, matter, any thing (what) to say, to speak(-ing), speak, talking, word.', 'from 4448 (plural masculine as if from מִלֶּה;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7504}/[H7503]', 'lemma', 'heb', 'רָפֶה', '["râpheh"]', '["slack"]', '["a"]', 'slack (in body or mind) weak. raphah, Raphah. See 7497, 7498. riphah. See 7383.', 'from 7503;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965I}/H9013/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["they raised/ !"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4405}/H9021/[H4448]', 'inflected', 'heb', 'מִלָּה', '["millâh"]', '["words/ your"]', '["n-f"]', 'a word; collectively, a discourse; figuratively, a topic answer, by-word, matter, any thing (what) to say, to speak(-ing), speak, talking, word.', 'from 4448 (plural masculine as if from מִלֶּה;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1290}/[H1288]', 'inflected', 'heb', 'בֶּרֶךְ', '["berek"]', '["and/ knees"]', '["n-f"]', 'a knee knee.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5704}/H9031/[H5703]', 'inflected', 'heb', 'עַד', '["ʻad"]', '["to/ you"]', '["prep"]', 'as far (or long, or much) as, whether of space (even unto) or time (during, while, until) or degree (equally with) against, and, as, at, before, by (that), even (to), for(-asmuch as), (hither-) to, how long, into, as long (much) as, (so) that, till, toward, until, when, while, ( as) yet.', 'properly, the same as 5703 (used as a preposition, adverb or conjunction; especially with a preposition);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3374}/H9021/[H3373]', 'inflected', 'heb', 'יִרְאָה', '["yirʼâh"]', '["[is] fear/ your"]', '["n-f"]', 'fear (also used as infinitive); morally, reverence × dreadful, × exceedingly, fear(-fulness).', 'feminine of 3373;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3690}/H9021/[H3689]', 'inflected', 'heb', 'כִּסְלָה', '["kiçlâh"]', '["confidence/ your"]', '["n-f"]', 'in a good sense, trust; in a bad one, silliness confidence, folly.', 'feminine of 3689;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8615B}/H9021/[H6960]', 'inflected', 'heb', 'תִּקְוָה', '["tiqvâh"]', '["hope/ your"]', '["n-f"]', 'literally a cord (as an attachment); figuratively, expectancy expectation(-ted), hope, live, thing that I long for.', 'from 6960; (compare 6961)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8537}/[H8552]', 'inflected', 'heb', 'תֹּם', '["tôm"]', '["and/ [the] integrity of"]', '["n-m"]', 'completeness; figuratively, prosperity; usually (morally) innocence full, integrity, perfect(-ion), simplicity, upright(-ly, -ness), at a venture. See 8550.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0375}/[H335]', 'inflected', 'heb', 'אֵיפֹה', '["ʼêyphôh"]', '["and/ where?"]', '["adv"]', 'what place?; also (of time) when?; or (of means) how? what manner, where.', 'from 335 and 6311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0205G>', 'opaque', 'heb', 'אָוֶן', '["ʼâven"]', '["<of> wickedness","[are] wickedness","evil","wickedness"]', '["n-m"]', 'strictly nothingness; also trouble, vanity, wickedness; specifically an idol affliction, evil, false, idol, iniquity, mischief, mourners(-ing), naught, sorrow, unjust, unrighteous, vain, vanity, wicked(-ness). Compare 369.', 'from an unused root perhaps meaning properly, to pant (hence, to exert oneself, usually in vain; to come to naught);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2232}/[H2232]', 'inflected', 'heb', 'זָרַע', '["zâraʻ"]', '["and/ [one who] sows","and/ sowers of"]', '["v"]', 'to sow; figuratively, to disseminate, plant, fructify bear, conceive seed, set with sow(-er), yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7114B}/H9033/[H7114]', 'inflected', 'heb', 'קָצַר', '["qâtsar"]', '["they harvest/ it"]', '["v"]', 'to dock off, i.e. curtail (transitive or intransitive, literal or figurative); especially to harvest (grass or grain) × at all, cut down, much discouraged, grieve, harvestman, lothe, mourn, reap(-er), (be, wax) short(-en, -er), straiten, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H7307H}/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["and/ from/ [the] breath of"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7581}/[H7580]', 'lemma', 'heb', 'שְׁאָגָה', '["shᵉʼâgâh"]', '["[the] roaring of","roaring"]', '["n-f"]', 'a rumbling or moan roaring.', 'from 7580;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6963A>', 'inflected', 'heb', 'וקול', '["va./Kol","ve./Kol"]', '["and/ [the] sound of","and/ [the] voice","and/ a sound of","and/ a voice"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7826>', 'opaque', 'heb', 'שַׁחַל', '["shachal"]', '["a lion"]', '["n-m"]', 'a lion (from his characteristic roar) (fierce) lion.', 'from an unused root probably meaning to roar;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5421}/[H5422]', 'lemma', 'heb', 'נָתַע', '["nâthaʻ"]', '["they are broken out"]', '["v"]', 'to tear out break.', 'for 5422;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3918}/[H3888]', 'lemma', 'heb', 'לַיִשׁ', '["layish"]', '["a lion"]', '["n-m"]', 'a lion (from his destructive blows) (old) lion.', 'from 3888 in the sense of crushing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3833C>', 'opaque', 'heb', 'לָבִיא', '["lâbîyʼ"]', '["a lion","lioness"]', '["n"]', 'a lion (properly, a lioness as the fiercer (although not a roarer;)) (great, old, stout) lion, lioness, young (lion).', 'or (Ezekiel 19:2) לְבִיָּא; irregular masculine plural לְבָאִים; irregular feminine plural לְבָאוֹת; from an unused root meaning to roar; compare 738');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0241G}/H9020/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["ear/ my","ears/ my"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8102>', 'opaque', 'heb', 'שֶׁמֶץ', '["shemets"]', '["a whisper","a whisper of"]', '["n-m"]', 'an inkling a little.', 'from an unused root meaning to emit a sound;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5587B}/[H5586]', 'inflected', 'heb', 'סָעִף', '["çâʻiph"]', '["in/ disquieting thoughts"]', '["n-f"]', 'divided (in mind), i.e. (abstractly) a sentiment opinion.', 'or שָׂעִף; from 5586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2384}/[H2372]', 'inflected', 'heb', 'חִזָּיוֹן', '["chizzâyôwn"]', '["from/ visions of"]', '["n-m"]', 'a revelation, expectation by dream vision.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5307G}/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["when/ fall","when/ falls","when/ fell"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7122H}/H9030/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["it happened to/ me"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7461A}/[H7460]', 'inflected', 'heb', 'רַעַד', '["raʻad"]', '["and/ trembling"]', '["n-m n-f"]', 'a shudder trembling.', 'or (feminine) רְעָדָהxlit rᵉâdâh corrected to rᵉʻâdâh; from 7460;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2498}/[H2498]', 'lemma', 'heb', 'חָלַף', '["châlaph"]', '["[which] it sprouts up","he will pass by","it has passed away","it passed over","it swept on","it will pass away","it will show newness","it will sprout afresh","let them renew","they have overstepped","they have passed on","they will renew","we will substitute"]', '["v"]', 'properly, to slide by, i.e. (by implication) to hasten away, pass on, spring up, pierce or change abolish, alter, change, cut off, go on forward, grow up, be over, pass (away, on, through), renew, sprout, strike through.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5568}/[H5568]', 'lemma', 'heb', 'סָמַר', '["çâmar"]', '["it made bristle","it trembles"]', '["v"]', 'to be erect, i.e. bristle as hair stand up, tremble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8185}/[H8181]', 'lemma', 'heb', 'שַׂעֲרָה', '["saʻărâh"]', '["[the] hair of"]', '["n-f"]', 'hairiness hair.', 'feminine of 8181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1320}/H9020/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["[is] flesh/ my","body/ my","flesh/ my"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0582}/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["¿/ a person"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0433}/[H410]', 'inflected', 'heb', 'אֱלוֹהַּ', '["ʼĕlôwahh"]', '["from/ God"]', '["n-m"]', 'a deity or the Deity God, god. See 430.', 'rarely (shortened) אֱלֹהַּ; probably prolonged (emphatic) from 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6213H}/H9033/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["from/ maker/ his"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H4397H>/H9023', 'inflected', 'heb', 'ובמלאכיו', '["u./ve./mal.''a.Kha/v"]', '["and/ against/ messengers/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8417}/[H1984]', 'lemma', 'heb', 'תׇּהֳלָה', '["tohŏlâh"]', '["error"]', '["n-f"]', 'braggadocio, i.e. (by implication) fatuity folly.', 'feminine of an unused noun (apparently from 1984) meaning bluster;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2563A}/[H2560]', 'lemma', 'heb', 'חֹמֶר', '["chômer"]', '["clay"]', '["n-m"]', 'properly, a bubbling up, i.e. of water, a wave; of earth, mire or clay (cement); also a heap; hence, a chomer or dry measure clay, heap, homer, mire, motion.', 'from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3247H}/H9028/[H3245]', 'inflected', 'heb', 'יְסוֹד', '["yᵉçôwd"]', '["foundation/ their"]', '["n-f"]', 'a foundation (literally or figuratively) bottom, foundation, repairing', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1792}/H9038/[H1794]', 'inflected', 'heb', 'דָּכָא', '["dâkâʼ"]', '["people crush/ them"]', '["v"]', 'to crumble; transitively, to bruise (literally or figuratively) beat to pieces, break (in pieces), bruise, contrite, crush, destroy, humble, oppress, smite.', 'a primitive root (compare 1794);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6211A}/[H6244]', 'lemma', 'heb', 'עָשׁ', '["ʻâsh"]', '["a moth","moth"]', '["n"]', 'a moth moth. See also 5906.', 'from 6244;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1242}/[H1239]', 'inflected', 'heb', 'בֹּקֶר', '["bôqer"]', '["from/ morning"]', '["n-m"]', 'properly, dawn (as the break of day); generally, morning ( ) day, early, morning, morrow.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5331}/[H5329]', 'inflected', 'heb', 'נֶצַח', '["netsach"]', '["to/ perpetuity","to/ perpetuity of"]', '["n-m"]', 'properly, a goal, i.e. the bright object at a distance travelled towards; hence (figuratively), splendor, or (subjectively) truthfulness, or (objectively) confidence; but usually (adverbially), continually (i.e. to the most distant point of view) alway(-s), constantly, end, ( n-) ever(more), perpetual, strength, victory.', 'or נֵצַח; from 5329;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3499B}/H9028/[H3498]', 'inflected', 'heb', 'יֶתֶר', '["yether"]', '["tent cord/ their"]', '["n-m"]', 'properly, an overhanging, i.e. (by implication) an excess, superiority, remainder; also a small rope (as hanging free) abundant, cord, exceeding, excellancy(-ent), what they leave, that hath left, plentifully, remnant, residue, rest, string, with.', 'from 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6918G}/[H6942]', 'inflected', 'heb', 'קָדוֹשׁ', '["qâdôwsh"]', '["from/ [the] holy [one] of","of/ [the] holy [ones]"]', '["a"]', 'sacred (ceremonially or morally); (as noun) God (by eminence), an angel, a saint, a sanctuary holy (One), saint.', 'or קָדֹשׁ; from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0191>', 'inflected', 'heb', 'לאויל', '["Le./''e.vil","le./''e.Vil"]', '["<to>/ a fool","for/ a fool"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3708B}/[H3707]', 'lemma', 'heb', 'כַּעַס', '["kaʻaç"]', '["vexation"]', '["n-m"]', 'vexation anger, angry, grief, indignation, provocation, provoking, × sore, sorrow, spite, wrath.', 'or (in Job) כַּעַשׂ; from 3707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6601B}/[H6601]', 'inflected', 'heb', 'פָּתָה', '["pâthâh"]', '["and/ a simple [one]"]', '["v"]', 'to open, i.e. be (causatively, make) roomy; usually figuratively (in a mental or moral sense) to be (causatively, make) simple or (in a sinister way) delude allure, deceive, enlarge, entice, flatter, persuade, silly (one).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0191>', 'opaque', 'heb', 'אֱוִיל', '["ʼĕvîyl"]', '["[is] a fool","a fool","fool","fools"]', '["a-m"]', '(figuratively) silly fool(-ish) (man).', 'from an unused root (meaning to be perverse);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8327}/[H8327]', 'lemma', 'heb', 'שָׁרַשׁ', '["shârash"]', '["it has taken root","it will root up","it will take root","let them be rooted up","taking root","they have taken root"]', '["v"]', 'to root, i.e. strike into the soil, or (by implication) to pluck from it (take, cause to take) root (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6895}/[H6895]', 'inflected', 'heb', 'קָבַב', '["qâbab"]', '["and/ I cursed"]', '["v"]', 'to scoop out, i.e. (figuratively) to malign or execrate (i.e. stab with words) × at all, curse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3468}/[H3467]', 'inflected', 'heb', 'יֶשַׁע', '["yeshaʻ"]', '["from/ safety"]', '["n-m"]', 'liberty, deliverance, prosperity safety, salvation, saving.', 'or יֵשַׁע; from 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1792}/[H1794]', 'inflected', 'heb', 'דָּכָא', '["dâkâʼ"]', '["so/ he may crush","so/ they may be crushed"]', '["v"]', 'to crumble; transitively, to bruise (literally or figuratively) beat to pieces, break (in pieces), bruise, contrite, crush, destroy, humble, oppress, smite.', 'a primitive root (compare 1794);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H6791>', 'inflected', 'heb', 'מצנים', '["mi./tzi.Nim"]', '["from/ thorns"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7602A}/[H7602]', 'inflected', 'heb', 'שָׁאַף', '["shâʼaph"]', '["and/ it is eager for"]', '["v"]', 'to inhale eagerly; figuratively, to cover; by implication, to be angry; also to hasten desire (earnestly), devour, haste, pant, snuff up, swallow up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6782}/[H6777]', 'lemma', 'heb', 'צַמִּים', '["tsammîym"]', '["a snare"]', '["n-m"]', 'a noose (as fastening); figuratively, destruction robber.', 'from the same as 6777;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0127G}/[H119]', 'inflected', 'heb', 'אֲדָמָה', '["ʼădâmâh"]', '["and/ from/ [the] ground"]', '["n-f"]', 'soil (from its general redness) country, earth, ground, husband(-man) (-ry), land.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5999}/[H5998]', 'inflected', 'heb', 'עָמָל', '["ʻâmâl"]', '["to/ trouble"]', '["n"]', 'toil, i.e. wearing effort; hence, worry, whether of body or mind grievance(-vousness), iniquity, labour, mischief, miserable(-sery), pain(-ful), perverseness, sorrow, toil, travail, trouble, wearisome, wickedness.', 'from 5998;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1121I}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ [the] children of","and/ [the] son of","and/ [the] sons of","and/ a son of","and/ sons of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1700}/H9020/[H1697]', 'inflected', 'heb', 'דִּבְרָה', '["dibrâh"]', '["plea/ my"]', '["n-m"]', 'a reason, suit or style cause, end, estate, order, regard.', 'feminine of 1697;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4791}/[H7311]', 'inflected', 'heb', 'מָרוֹם', '["mârôwm"]', '["to the/ height","to the/ height[s]","to/ a high place"]', '["n-m"]', 'altitude, i.e. concretely (an elevated place), abstractly (elevation, figuratively (elation), or adverbially (aloft) (far) above, dignity, haughty, height, (most, on) high (one, place), loftily, upward.', 'from 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6937}/[H6937]', 'inflected', 'heb', 'קָדַר', '["qâdar"]', '["and/ mourners"]', '["v"]', 'to be ashy, i.e. dark-colored; by implication, to mourn (in sackcloth or sordid garments) be black(-ish), be (make) dark(-en), × heavily, (cause to) mourn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3468}/[H3467]', 'lemma', 'heb', 'יֶשַׁע', '["yeshaʻ"]', '["<the> salvation of","safety","salvation"]', '["n-m"]', 'liberty, deliverance, prosperity safety, salvation, saving.', 'or יֵשַׁע; from 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8454>', 'opaque', 'heb', 'תּוּשִׁיָּה', '["tûwshîyâh"]', '["sound wisdom","success"]', '["n-f"]', 'support or (by implication) ability, i.e. (direct) help, (in purpose) an undertaking, (intellectual) understanding enterprise, that which (thing as it) is, substance, (sound) wisdom, working.', 'or תֻּשִׁיָּה; from an unused root probably meaning to substantiate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6191}/H9048/[H6191]', 'inflected', 'heb', 'עָרַם', '["ʻâram"]', '["when/ are crafty/ they"]', '["v"]', 'properly, to be (or make) bare; but used only in the derivative sense (through the idea perhaps of smoothness) to be cunning (usually in a bad sense) × very, beware, take crafty (counsel), be prudent, deal subtilly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H3915}/[H3883]', 'inflected', 'heb', 'לַיִל', '["layil"]', '["and/ like <the>/ night"]', '["n-m"]', 'properly, a twist (away of the light), i.e. night; figuratively, adversity (mid-)night (season).', 'or (Isaiah 21:11) לֵיל; also לַיְלָה; from the same as 3883;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1800}/[H1809]', 'inflected', 'heb', 'דַּל', '["dal"]', '["for the/ poor [person]","to <the>/ poor [person]"]', '["a"]', 'properly, dangling, i.e. (by implication) weak or thin lean, needy, poor (man), weaker.', 'from 1809;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5766B}/[H5765]', 'inflected', 'heb', 'עֶוֶל', '["ʻevel"]', '["and/ injustice","and/ unrighteousness"]', '["n-m"]', '(moral) evil iniquity, perverseness, unjust(-ly), unrighteousness(-ly); wicked(-ness).', 'or עָוֶל; and (feminine) עַוְלָה; or עוֹלָה; or עֹלָה; from 5765;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3198}/H9033/[H3198]', 'inflected', 'heb', 'יָכַח', '["yâkach"]', '["[whom] he reproves/ him"]', '["v"]', 'to be right (i.e. correct); reciprocal, to argue; causatively, to decide, justify or convict appoint, argue, chasten, convince, correct(-ion), daysman, dispute, judge, maintain, plead, reason (together), rebuke, reprove(-r), surely, in any wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4148G}/[H3256]', 'inflected', 'heb', 'מוּסָר', '["mûwçâr"]', '["and/ [the] discipline of"]', '["n-m"]', 'properly, chastisement; figuratively, reproof, warning or instruction; also restraint bond, chastening(-eth), chastisement, check, correction, discipline, doctrine, instruction, rebuke.', 'from 3256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2280}/[H2280]', 'inflected', 'heb', 'חָבַשׁ', '["châbash"]', '["and/ [he is] binding up","and/ he may bind up"]', '["v"]', 'to wrap firmly (especially a turban, compress, or saddle); figuratively, to stop, to rule bind (up), gird about, govern, healer, put, saddle, wrap about.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6299}/H9031/[H6299]', 'inflected', 'heb', 'פָּדָה', '["pâdâh"]', '["I ransomed/ you","he will ransom/ you"]', '["v"]', 'to sever, i.e. ransom; generally to release, preserve × at all, deliver, × by any means, ransom, (that are to be, let be) redeem(-ed), rescue, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7701}/[H7736]', 'inflected', 'heb', 'שֹׁד', '["shôd"]', '["from/ [the] devastation","from/ [the] devastation of","from/ destruction"]', '["n-m"]', 'violence, ravage desolation, destruction, oppression, robbery, spoil(-ed, -er, -ing), wasting.', 'or שׁוֹד; (Job 5:21), from 7736;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7701}/[H7736]', 'inflected', 'heb', 'שֹׁד', '["shôd"]', '["to/ destruction"]', '["n-m"]', 'violence, ravage desolation, destruction, oppression, robbery, spoil(-ed, -er, -ing), wasting.', 'or שׁוֹד; (Job 5:21), from 7736;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3720}/[H3719]', 'inflected', 'heb', 'כָּפָן', '["kâphân"]', '["and/ to/ famine"]', '["n-m"]', 'hunger (as making to stoop with emptiness and pain) famine.', 'from 3719;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H2416C}/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["and/ from/ [the] animal[s] of"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5116A}/H9021/[H5115]', 'inflected', 'heb', 'נָוֶה', '["nâveh"]', '["estate/ your"]', '["n"]', '(adjectively) at home; hence (by implication of satisfaction) lovely; also (noun) a home, of God (temple), men (residence), flocks (pasture), or wild animals (den) comely, dwelling (place), fold, habitation, pleasant place, sheepcote, stable, tarried.', 'or (feminine) נָוָה; from 5115;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6631}/H9021/[H3318]', 'inflected', 'heb', 'צֶאֱצָא', '["tseʼĕtsâʼ"]', '["and/ descendants/ your"]', '["n-m"]', 'issue, i.e. produce, children that which cometh forth (out), offspring.', 'from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H6212>', 'inflected', 'heb', 'כעשב', '["Kha./''e.sev","ka./''E.sev","ke./''E.sev"]', '["[will be] like/ [the] vegetation of","like <the>/ vegetation","like/ [the] vegetation of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3624>', 'inflected', 'heb', 'בכלח', '["ve./Khe.lach"]', '["in/ full strength"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5927H}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["as/ goes up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2713}/H9034/[H2713]', 'inflected', 'heb', 'חָקַר', '["châqar"]', '["he examined/ it","we have examined/ it"]', '["v"]', 'properly, to penetrate; hence, to examine intimately find out, (make) search (out), seek (out), sound, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3708B}/H9020/[H3707]', 'inflected', 'heb', 'כַּעַס', '["kaʻaç"]', '["grief/ my"]', '["n-m"]', 'vexation anger, angry, grief, indignation, provocation, provoking, × sore, sorrow, spite, wrath.', 'or (in Job) כַּעַשׂ; from 3707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1942}/H9020/[H1933]', 'inflected', 'heb', 'הַוָּה', '["havvâh"]', '["and/ destruction/ my"]', '["n-f"]', 'by implication, of falling); desire; also ruin calamity, iniquity, mischief, mischievous (thing), naughtiness, naughty, noisome, perverse thing, substance, very wickedness.', 'from 1933 (in the sense of eagerly coveting and rushing upon;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3976}/[H239]', 'inflected', 'heb', 'מֹאזֵן', '["môʼzên"]', '["in/ [the] balances","in/ balances of","on/ scales","with/ balances of","with/ scales"]', '["n-m"]', '(only in the dual) a pair of scales balances.', 'from 239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2344}/[H2342]', 'inflected', 'heb', 'חוֹל', '["chôwl"]', '["more than/ [the] sand of","more than/ sand"]', '["n-m"]', 'sand (as round or whirling particles) sand.', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3886B}/[H3886]', 'lemma', 'heb', 'לוּעַ', '["lûwaʻ"]', '["they have been rash"]', '["v"]', 'to gulp; figuratively, to be rash swallow down (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2534}/H9028/[H3179]', 'inflected', 'heb', 'חֵמָה', '["chêmâh"]', '["poison/ their"]', '["n-f"]', 'heat; figuratively, anger, poison (from its fever) anger, bottles, hot displeasure, furious(-ly, -ry), heat, indignation, poison, rage, wrath(-ful). See 2529.', 'or (Daniel 11:44) חֵמָא; from 3179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1161}/[H1204]', 'lemma', 'heb', 'בִּעוּתִים', '["biʻûwthîym"]', '["[the] terrors of"]', '["n-m"]', 'alarms terrors.', 'masculine plural from 1204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6186A}/H9030/[H6186]', 'inflected', 'heb', 'עָרַךְ', '["ʻârak"]', '["they are arranged against/ me"]', '["v"]', 'to set in a row, i.e. arrange, put in order (in a very wide variety of applications) put (set) (the battle, self) in array, compare, direct, equal, esteem, estimate, expert (in war), furnish, handle, join (battle), ordain, (lay, put, reckon up, set) (in) order, prepare, tax, value.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5101}/[H5101]', 'inflected', 'heb', 'נָהַק', '["nâhaq"]', '["¿/ does it bray"]', '["v"]', 'to bray (as an ass), scream (from hunger) bray.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1600}/[H1600]', 'lemma', 'heb', 'גָּעָה', '["gâʻâh"]', '["does it low"]', '["v"]', 'to bellow (as cattle) low.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1098}/H9023/[H1101]', 'inflected', 'heb', 'בְּלִיל', '["bᵉlîyl"]', '["fodder/ its"]', '["n-m"]', 'mixed, i.e. (specifically) feed (for cattle) corn, fodder, provender.', 'from 1101;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8602A>', 'opaque', 'heb', 'תָּפֵל', '["tâphêl"]', '["tasteless [food]"]', '["a"]', 'plaster (as gummy) or slime; (figuratively) frivolity foolish things, unsavoury, untempered.', 'from an unused root meaning to smear;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2940}/[H2938]', 'lemma', 'heb', 'טַעַם', '["ṭaʻam"]', '["<of> discernment","discernment","taste"]', '["n-m"]', 'properly, a taste, i.e. (figuratively) perception; by implication, intelligence; transitively, a mandate advice, behaviour, decree, discretion, judgment, reason, taste, understanding.', 'from 2938;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7388}/[H7325]', 'inflected', 'heb', 'רִיר', '["rîyr"]', '["in/ [the] slime of"]', '["n-m"]', 'saliva; by resemblance, broth spittle, white (of an egg).', 'from 7325;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2495}/[H2492]', 'lemma', 'heb', 'חַלָּמוּת', '["challâmûwth"]', '["purslane"]', '["n-m"]', 'probably purslain egg.', 'from 2492 (in the sense of insipidity);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1741}/[H1739]', 'inflected', 'heb', 'דְּוַי', '["dᵉvay"]', '["[are] like/ [the] illness of"]', '["n-m"]', 'sickness; figuratively, loathing languishing, sorrowful.', 'from 1739;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8615B}/H9020/[H6960]', 'inflected', 'heb', 'תִּקְוָה', '["tiqvâh"]', '["and/ hope/ my"]', '["n-f"]', 'literally a cord (as an attachment); figuratively, expectancy expectation(-ted), hope, live, thing that I long for.', 'from 6960; (compare 6961)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2974}/[H2973]', 'inflected', 'heb', 'יָאַל', '["yâʼal"]', '["and/ may he be willing"]', '["v"]', 'properly, to yield, especially assent; hence (pos.) to undertake as an act of volition assay, begin, be content, please, take upon, × willingly, would.', 'a primitive root (probably rather the same as 2973 through the idea of mental weakness);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1792}/H9030/[H1794]', 'inflected', 'heb', 'דָּכָא', '["dâkâʼ"]', '["and/ may he crush/ me","and/ will you crush?/ me"]', '["v"]', 'to crumble; transitively, to bruise (literally or figuratively) beat to pieces, break (in pieces), bruise, contrite, crush, destroy, humble, oppress, smite.', 'a primitive root (compare 1794);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5425B}/[H5425]', 'lemma', 'heb', 'נָתַר', '["nâthar"]', '["[is] setting free","may he loosen","to unfasten"]', '["v"]', 'to jump, i.e. be violently agitated; causatively, to terrify, shake off, untie drive asunder, leap, (let) loose, × make, move, undo.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1214G}/H9030/[H1214]', 'inflected', 'heb', 'בָּצַע', '["bâtsaʻ"]', '["and/ may he cut off/ me"]', '["v"]', 'to break off, i.e. (usually) plunder; figuratively, to finish, or (intransitively) stop (be) covet(-ous), cut (off), finish, fulfill, gain (greedily), get, be given to (covetousness), greedy, perform, be wounded.', 'a primitive root');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5165}/H9020/[H5162]', 'inflected', 'heb', 'נֶחָמָה', '["nechâmâh"]', '["[is] comfort/ my","comfort/ my"]', '["n-f"]', 'consolation comfort.', 'from 5162;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5539}/[H5539]', 'inflected', 'heb', 'סָלַד', '["çâlad"]', '["and/ may I jump"]', '["v"]', 'probably to leap (with joy), i.e. exult harden self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2427B}/[H2342]', 'inflected', 'heb', 'חִיל', '["chîyl"]', '["in/ anguish"]', '["n-m"]', 'a throe (expectant of childbirth) pain, pang, sorrow.', 'and (feminine) חִילָה; from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3176H}/[H3176]', 'lemma', 'heb', 'יָחַל', '["yâchal"]', '["I have hoped","I hope","I will hope","I will wait","hope","she waited","wait","we hope"]', '["v"]', 'to wait; by implication, to be patient, hope (cause to, have, make to) hope, be pained, stay, tarry, trust, wait.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7093}/H9020/[H7112]', 'inflected', 'heb', 'קֵץ', '["qêts"]', '["[is] end/ my","end/ my"]', '["n-m"]', 'an extremity; adverbially (with prepositional prefix) after after, (utmost) border, end, (in-) finite, × process.', 'contracted from 7112;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5153}/[H5172]', 'lemma', 'heb', 'נָחוּשׁ', '["nâchûwsh"]', '["bronze"]', '["a"]', 'coppery, i.e. (figuratively) hard of brass.', 'apparently passive participle of 5172 (perhaps in the sense of ringing), i.e. bell-metal; or from the red color of the throat of a serpent (5175, as denominative) when hissing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5833}/H9020/[H5828]', 'inflected', 'heb', 'עֶזְרָה', '["ʻezrâh"]', '["[are] help/ my","[is] help/ my","help/ my"]', '["n-f"]', 'aid help(-ed, -er).', 'or עֶזְרָת; (Psalm 60:11 (13); Psalm 108:12 (13)), feminine of 5828;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H8454>', 'inflected', 'heb', 'ותושיה', '["ve./tu.shi.Yah"]', '["and/ sound wisdom","and/ success"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4523}/[H4549]', 'inflected', 'heb', 'מָס', '["mâç"]', '["[belongs] to <the>/ despairing [person]"]', '["a"]', 'fainting, i.e. (figuratively) disconsolate is afflicted.', 'from 4549;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3374}/[H3373]', 'inflected', 'heb', 'יִרְאָה', '["yirʼâh"]', '["and/ [the] fear of","and/ fear"]', '["n-f"]', 'fear (also used as infinitive); morally, reverence × dreadful, × exceedingly, fear(-fulness).', 'feminine of 3373;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0650}/[H622]', 'inflected', 'heb', 'אָפִיק', '["ʼâphîyq"]', '["like/ a stream-bed of","like/ stream-beds"]', '["n-m"]', 'properly, containing, i.e. a tube; also a bed or valley of a stream; also a strong thing or a hero brook, channel, mighty, river, scale, stream, strong piece.', 'from 622;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6937}/[H6937]', 'inflected', 'heb', 'קָדַר', '["qâdar"]', '["that/ are dark"]', '["v"]', 'to be ashy, i.e. dark-colored; by implication, to mourn (in sackcloth or sordid garments) be black(-ish), be (make) dark(-en), × heavily, (cause to) mourn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7140}/[H7139]', 'lemma', 'heb', 'קֶרַח', '["qerach"]', '["ice"]', '["n-m"]', 'ice (as if bald, i.e. smooth); hence, hail; by resemblance, rock crystal crystal, frost, ice.', 'or קֹרַח; from 7139;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7950}/[H7949]', 'lemma', 'heb', 'שֶׁלֶג', '["sheleg"]', '["[the] snow of","snow"]', '["n-m"]', 'snow (probably from its whiteness) snow(-y).', 'from 7949;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2215}/[H2215]', 'lemma', 'heb', 'זָרַב', '["zârab"]', '["[when] they flow"]', '["v"]', 'to flow away wax warm.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6789}/[H6789]', 'lemma', 'heb', 'צָמַת', '["tsâmath"]', '["I have been destroyed","I will destroy","they are silenced","they destroyed","you destroy","you will destroy"]', '["v"]', 'to extirpate (literally or figuratively) consume, cut off, destroy, vanish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2552}/H9023/[H2552]', 'inflected', 'heb', 'חָמַם', '["châmam"]', '["in/ heat/ its"]', '["v"]', 'to be hot (literally or figuratively) enflame self, get (have) heat, be (wax) hot, (be, wax) warm (self, at).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1846}/[H1846]', 'lemma', 'heb', 'דָּעַךְ', '["dâʻak"]', '["is it extinguished","it is extinguished","it will be extinguished","they are dried up","they were extinguished"]', '["v"]', 'to be extinguished; figuratively, to expire or be dried up be extinct, consumed, put out, quenched.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4725}/H9028/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["from/ place/ their"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3943}/[H3943]', 'lemma', 'heb', 'לָפַת', '["lâphath"]', '["they twist"]', '["v"]', 'properly, to bend, i.e. (by implication) to clasp; also (reflexively) to turn around or aside take hold, turn aside (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870L}/H9028/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["own way/ their","path/ their","way/ their"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H8414>', 'inflected', 'heb', 'בתהו', '["be./To.hu","va./To.hu"]', '["in the/ wasteland","in/ a wasteland","with <the>/ emptiness"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8485H}/[H8485]', 'lemma', 'heb', 'תֵּימָא', '["Têymâʼ"]', '["Tema"]', '["n-pr-m n-pr-loc"]', 'Tema, a son of Ishmael, and the region settled by him Tema.', 'or תֵּמָא; probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1979}/[H1978]', 'lemma', 'heb', 'הֲלִיכָה', '["hălîykâh"]', '["[the] processions of","[the] travelers of","[the] ways of","ways of"]', '["n-f"]', 'a walking; by implication, a procession or march, a caravan company, going, walk, way.', 'feminine of 1978;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5704}/H9034/[H5703]', 'inflected', 'heb', 'עַד', '["ʻad"]', '["to/ it"]', '["prep"]', 'as far (or long, or much) as, whether of space (even unto) or time (during, while, until) or degree (equally with) against, and, as, at, before, by (that), even (to), for(-asmuch as), (hither-) to, how long, into, as long (much) as, (so) that, till, toward, until, when, while, ( as) yet.', 'properly, the same as 5703 (used as a preposition, adverb or conjunction; especially with a preposition);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2659}/[H2658]', 'inflected', 'heb', 'חָפֵר', '["châphêr"]', '["and/ it will be abashed","and/ they were disappointed","and/ they will be abashed"]', '["v"]', 'to blush; figuratively, to be ashamed, disappointed; causatively, to shame, reproach be ashamed, be confounded, be brought to confusion (unto shame), come (be put to) shame, bring reproach.', 'a primitive root (perhaps rather the same as 2658 through the idea of detection);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2866}/[H2865]', 'lemma', 'heb', 'חֲתַת', '["chăthath"]', '["a terror"]', '["n-m"]', 'dismay casting down.', 'from 2865;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H3581B>/H9026', 'inflected', 'heb', 'ומכחכם', '["u./mi./ko.cha./Khem"]', '["and/ from/ wealth/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7809}/[H7809]', 'lemma', 'heb', 'שָׁחַד', '["shâchad"]', '["give a reward"]', '["v"]', 'to donate, i.e. bribe hire, give a reward.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4422}/H9030/[H4422]', 'inflected', 'heb', 'מָלַט', '["mâlaṭ"]', '["and/ rescue/ me"]', '["v"]', 'properly, to be smooth, i.e. (by implication) to escape (as if by slipperiness); causatively, to release or rescue; specifically, to bring forth young, emit sparks deliver (self), escape, lay, leap out, let alone, let go, preserve, save, × speedily, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6184}/[H6206]', 'lemma', 'heb', 'עָרִיץ', '["ʻârîyts"]', '["[the] ruthless person","a ruthless [person]","ruthless","ruthless [ones] of","ruthless [people]"]', '["a"]', 'fearful, i.e. powerful or tyrannical mighty, oppressor, in great power, strong, terrible, violent.', 'from 6206;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6299}/H9030/[H6299]', 'inflected', 'heb', 'פָּדָה', '["pâdâh"]', '["ransom/ me","redeem/ me","you will ransom/ me"]', '["v"]', 'to sever, i.e. ransom; generally to release, preserve × at all, deliver, × by any means, ransom, (that are to be, let be) redeem(-ed), rescue, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3384B}/H9030/[H3384]', 'inflected', 'heb', 'יָרָה', '["yârâh"]', '["instruct/ me","teach/ me","you have taught/ me"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3476}/[H3474]', 'lemma', 'heb', 'יֹשֶׁר', '["yôsher"]', '["[are] [the] uprightness of","uprightness"]', '["n-m"]', 'the right equity, meet, right, upright(-ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9005/{H3198}/[H3198]', 'inflected', 'heb', 'יָכַח', '["yâkach"]', '["¿/ to/ reprove"]', '["v"]', 'to be right (i.e. correct); reciprocal, to argue; causatively, to decide, justify or convict appoint, argue, chasten, convince, correct(-ion), daysman, dispute, judge, maintain, plead, reason (together), rebuke, reprove(-r), surely, in any wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4405}/[H4448]', 'lemma', 'heb', 'מִלָּה', '["millâh"]', '["[are] words","[is] a word","[the] words","words"]', '["n-f"]', 'a word; collectively, a discourse; figuratively, a topic answer, by-word, matter, any thing (what) to say, to speak(-ing), speak, talking, word.', 'from 4448 (plural masculine as if from מִלֶּה;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7307H}/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["and/ to/ wind"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2976}/[H2976]', 'lemma', 'heb', 'יָאַשׁ', '["yâʼash"]', '["[one who] despairs","despairing"]', '["v"]', 'to desist, i.e. (figuratively) to despond (cause to) despair, one that is desperate, be no hope.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3739A}/[H3738]', 'inflected', 'heb', 'כָּרָה', '["kârâh"]', '["and/ you may bargain"]', '["v"]', 'to purchase buy, prepare.', 'usually assigned as a primitive root, but probably only a special application of 3738 (through the common idea of planning implied in a bargain);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7453}/H9026/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["friend/ your"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6664G}/H9020/[H6663]', 'inflected', 'heb', 'צֶדֶק', '["tsedeq"]', '["righteousness/ my"]', '["n-m"]', 'the right (natural, moral or legal); also (abstractly) equity or (figuratively) prosperity × even, (× that which is altogether) just(-ice), (un-)right(-eous) (cause, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3956G}/H9020/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["on/ tongue/ my","with/ tongue/ my"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2441}/H9020/[H2596]', 'inflected', 'heb', 'חֵךְ', '["chêk"]', '["palate/ my"]', '["n-m"]', 'properly, the palate or inside of the mouth; hence, the mouth itself (as the organ of speech, taste and kissing) (roof of the) mouth, taste.', 'probably from 2596 in the sense of tasting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1942}/[H1933]', 'lemma', 'heb', 'הַוָּה', '["havvâh"]', '["[is] destruction<s>","[the] craving of","destruction<s>"]', '["n-f"]', 'by implication, of falling); desire; also ruin calamity, iniquity, mischief, mischievous (thing), naughtiness, naughty, noisome, perverse thing, substance, very wickedness.', 'from 1933 (in the sense of eagerly coveting and rushing upon;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/<H3117G>', 'inflected', 'heb', 'וכימי', '["ve./khi./Mei","vi/kh./Yom"]', '["and/ like/ [the] day","and/ like/ [the] days of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5650}/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["as the/ servant","like/ [the] servant of","like/ a slave","like/ slaves"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7602A}/[H7602]', 'lemma', 'heb', 'שָׁאַף', '["shâʼaph"]', '["[is] panting","[who] he pants for","it sniffs","they have panted for","you long for"]', '["v"]', 'to inhale eagerly; figuratively, to cover; by implication, to be angry; also to hasten desire (earnestly), devour, haste, pant, snuff up, swallow up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H7916}/[H7936]', 'inflected', 'heb', 'שָׂכִיר', '["sâkîyr"]', '["and/ like/ a hired laborer"]', '["a"]', 'a man at wages by the day or year hired (man, servant), hireling.', 'from 7936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7723H}/[H7722]', 'lemma', 'heb', 'שָׁוְא', '["shâvᵉʼ"]', '["[is] futility","emptiness","falsehood","nothingness","vanity","worthlessness"]', '["n-m"]', 'evil (as destructive), literally (ruin) or morally (especially guile); figuratively idolatry (as false, subjective), uselessness (as deceptive, objective; also adverbially, in vain) false(-ly), lie, lying, vain, vanity.', 'or שַׁו; from the same as 7722 in the sense of desolating;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5076}/[H5074]', 'lemma', 'heb', 'נָדֻד', '["nâdud"]', '["restlessness<es>"]', '["n-m"]', 'properly, tossed; abstractly, a rolling (on the bed) tossing to and fro.', 'passive participle of 5074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5399}/[H5398]', 'lemma', 'heb', 'נֶשֶׁף', '["nesheph"]', '["[the] twilight of","twilight"]', '["n-m"]', 'properly, a breeze, i.e. (by implication) dusk (when the evening breeze prevails) dark, dawning of the day (morning), night, twilight.', 'from 5398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7415}/[H7426]', 'lemma', 'heb', 'רִמָּה', '["rimmâh"]', '["a maggot","maggot[s]"]', '["n-f"]', 'a maggot (as rapidly bred), literally or figuratively worm.', 'from 7426 in the sense of breeding (compare 7311);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1487>', 'inflected', 'heb', 'וגוש', '["ve./gish"]', '["and/ clod[s] of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5785}/H9020/[H5783]', 'inflected', 'heb', 'עוֹר', '["ʻôwr"]', '["skin/ my"]', '["n-m"]', 'skin (as naked); by implication, hide, leather hide, leather, skin.', 'from 5783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7280C}/[H7280]', 'lemma', 'heb', 'רָגַע', '["râgaʻ"]', '["it has hardened"]', '["v"]', 'properly, to toss violently and suddenly (the sea with waves, the skin with boils); figuratively (in a favorable manner) to settle, i.e. quiet; specifically, to wink (from the motion of the eye-lids) break, divide, find ease, be a moment, (cause, give, make to) rest, make suddenly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3988B}/[H3988]', 'inflected', 'heb', 'מָאַס', '["mâʼaç"]', '["and/ it has run"]', '["v"]', 'to spurn; also (intransitively) to disappear abhor, cast away (off), contemn, despise, disdain, (become) loathe(some), melt away, refuse, reject, reprobate, × utterly, vile person.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0708}/[H707]', 'lemma', 'heb', 'אֶרֶג', '["ʼereg"]', '["a weaver''s shuttle"]', '["n-m"]', 'a weaving; a braid; also a shuttle beam, weaver''s shuttle.', 'from 707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0657A}/[H656]', 'inflected', 'heb', 'אֶפֶס', '["ʼepheç"]', '["for/ nothing","with/ not"]', '["n-m"]', 'cessation, i.e. an end (especially of the earth); often used adverb, no further; also the ankle (in the dual), as being the extremity of the leg or foot ankle, but (only), end, howbeit, less than nothing, nevertheless (where), no, none (beside), not (any, -withstanding), thing of nought, save(-ing), there, uttermost part, want, without (cause).', 'from 656; (sometimes like 6466)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7789}/H9030/[H7789]', 'inflected', 'heb', 'שׁוּר', '["shûwr"]', '["it will observe/ me"]', '["v"]', 'to spy out, i.e. (generally) survey, (for evil) lurk for, (for good) care for behold, lay wait, look, observe, perceive, regard, see.', 'a primitive root (identical with through the idea of going round for inspection);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0369}/H9040/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["and/ there not [will be]/ me"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4751}/[H4843]', 'inflected', 'heb', 'מַר', '["mar"]', '["in/ [the] bitterness of","with/ bitterness of"]', '["a-m"]', 'bitter (literally or figuratively); also (as noun) bitterness, or (adverbially) bitterly angry, bitter(-ly, -ness), chafed, discontented, × great, heavy.', 'or (feminine) מָרָה; from 4843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/<H3220G>', 'inflected', 'heb', 'הים', '["ha/yam"]', '["¿/ [the] sea"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8577N}/[H8565]', 'lemma', 'heb', 'תַּנִּין', '["tannîyn"]', '["O sea monsters","[the] sea monster","sea monsters"]', '["n-m"]', 'a marine or land monster, i.e. sea-serpent or jackal dragon, sea-monster, serpent, whale.', 'or תַּנִּים; (Ezekiel 29:3), intensive from the same as 8565;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6210>/H9020', 'opaque', 'heb', 'עֶרֶשׂ', '["ʻeres"]', '["couch/ my"]', '["n-f"]', 'a couch (properly, with a canopy) bed(-stead), couch.', 'from an unused root meaning perhaps to arch;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7879}/H9020/[H7878]', 'inflected', 'heb', 'שִׂיחַ', '["sîyach"]', '["in/ complaint/ my"]', '["n-m"]', 'a contemplation; by implication, an utterance babbling, communication, complaint, meditation, prayer, talk.', 'from 7878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4904}/H9020/[H7901]', 'inflected', 'heb', 'מִשְׁכָּב', '["mishkâb"]', '["bed/ my"]', '["n-m"]', 'a bed (figuratively, a bier); abstractly, sleep; by euphemism, carnal intercourse bed(-chamber), couch, lieth (lying) with.', 'from 7901;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2865}/H9030/[H2865]', 'inflected', 'heb', 'חָתַת', '["châthath"]', '["and/ you will dismay/ me"]', '["v"]', 'properly, to prostrate; hence, to break down, either (literally) by violence, or (figuratively) by confusion and fear abolish, affright, be (make) afraid, amaze, beat down, discourage, (cause to) dismay, go down, scare, terrify.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H2384}/[H2372]', 'inflected', 'heb', 'חִזָּיוֹן', '["chizzâyôwn"]', '["and/ from/ visions"]', '["n-m"]', 'a revelation, expectation by dream vision.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4267}/[H2614]', 'lemma', 'heb', 'מַחֲנַק', '["machănaq"]', '["strangling"]', '["n-m"]', 'choking strangling.', 'from 2614;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1892}/[H1891]', 'lemma', 'heb', 'הֶבֶל', '["hebel"]', '["[are] a breath","[are] futility","[is] a breath","[is] futility","[was] futility","a breath","futilities","futility","futility of","vanities of","vanity"]', '["n-m"]', 'emptiness or vanity; figuratively, something transitory and unsatisfactory; often used as an adverb × altogether, vain, vanity.', 'or (rarely in the abs.) הֲבֵל; from 1891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6485I}/H9033/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["and/ you have visited/ him"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7281}/[H7280]', 'inflected', 'heb', 'רֶגַע', '["regaʻ"]', '["to/ moments"]', '["n-m"]', 'a wink (of the eyes), i.e. a very short space of time instant, moment, space, suddenly.', 'from 7280.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0974}/H9033/[H974]', 'inflected', 'heb', 'בָּחַן', '["bâchan"]', '["you test/ him"]', '["v"]', 'to test (especially metals); generally and figuratively, to investigate examine, prove, tempt, try (trial).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7503}/H9030/[H7503]', 'inflected', 'heb', 'רָפָה', '["râphâh"]', '["will you let alone?/ me"]', '["v"]', 'to slacken (in many applications, literal or figurative) abate, cease, consume, draw (toward evening), fail, (be) faint, be (wax) feeble, forsake, idle, leave, let alone (go, down), (be) slack, stay, be still, be slothful, (be) weak(-en). See 7495.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1104}/H9040/[H1104]', 'inflected', 'heb', 'בָּלַע', '["bâlaʻ"]', '["swallow/ I"]', '["v"]', 'to make away with (specifically by swallowing); generally, to destroy cover, destroy, devour, eat up, be at end, spend up, swallow down (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7536}/H9020/[H7556]', 'inflected', 'heb', 'רֹק', '["rôq"]', '["spittle/ my"]', '["n-m"]', 'spittle spit(-ting, -tle).', 'from 7556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4645}/[H6293]', 'inflected', 'heb', 'מִפְגָּע', '["miphgâʻ"]', '["to/ a target"]', '["n-m"]', 'an object of attack mark.', 'from 6293;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5674C}/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["and/ put away","so/ may you take away?"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7836}/H9030/[H7836]', 'inflected', 'heb', 'שָׁחַר', '["shâchar"]', '["and/ you will look for/ me"]', '["v"]', 'properly, to dawn, i.e. (figuratively) be (up) early at any task (with the implication of earnestness); by extension, to search for (with painstaking) (do something) betimes, enquire early, rise (seek) betimes, seek diligently) early, in the morning).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0369}/H9040\/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["and/ there not [will be]/ me"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1085>', 'opaque', 'heb', 'בִּלְדַּד', '["Bildad"]', '["Bildad"]', '["n-pr-m"]', 'Bildad, one of Job''s friends Bildad.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3524}/[H3527]', 'lemma', 'heb', 'כַּבִּיר', '["kabbîyr"]', '["[is] mighty","[the] mighty [one]","[those] old","mighty","mighty [ones]","much"]', '["a"]', 'vast, whether in extent (figuratively, of power, mighty; of time, aged), or in number, many feeble, mighty, most, much, strong, valiant.', 'from 3527;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0410G}/[H352]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["¿/ God"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5791}/[H5791]', 'lemma', 'heb', 'עָוַת', '["ʻâvath"]', '["[something] bent","does he pervert","he makes crooked","he perverts"]', '["v"]', 'to wrest bow self, (make) crooked., falsifying, overthrow, deal perversely, pervert, subvert, turn upside down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7971H}/H9038/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["and/ he sent/ them","and/ you set free/ them"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7836}/[H7836]', 'lemma', 'heb', 'שָׁחַר', '["shâchar"]', '["[one who] seeks diligently","seeking","you will seek"]', '["v"]', 'properly, to dawn, i.e. (figuratively) be (up) early at any task (with the implication of earnestness); by extension, to search for (with painstaking) (do something) betimes, enquire early, rise (seek) betimes, seek diligently) early, in the morning).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6664G}/H9021/[H6663]', 'inflected', 'heb', 'צֶדֶק', '["tsedeq"]', '["righteousness of/ your","righteousness/ your"]', '["n-m"]', 'the right (natural, moral or legal); also (abstractly) equity or (figuratively) prosperity × even, (× that which is altogether) just(-ice), (un-)right(-eous) (cause, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7225G}/H9021/[H7218]', 'inflected', 'heb', 'רֵאשִׁית', '["rêʼshîyth"]', '["beginning/ your"]', '["n-f"]', 'the first, in place, time, order or rank (specifically, a firstfruit) beginning, chief(-est), first(-fruits, part, time), principal thing.', 'from the same as 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0319}/H9021/[H310]', 'inflected', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["and/ future/ your"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7685B}/[H7685]', 'lemma', 'heb', 'שָׂגָה', '["sâgâh"]', '["he will grow","it will grow","they increase"]', '["v"]', 'to enlarge (especially upward, also figuratively) grow (up), increase.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3559K}/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["and/ give attention"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2714}/[H2713]', 'inflected', 'heb', 'חֵקֶר', '["chêqer"]', '["to/ [the] searching of"]', '["n-m"]', 'examination, enumeration, deliberation finding out, number, (un-) search(-able, -ed, out, -ing).', 'from 2713;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H3820A}/H9028/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["and/ from/ heart/ their"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H1342}/[H1342]', 'inflected', 'heb', 'גָּאָה', '["gâʼâh"]', '["¿/ will it grow tall"]', '["v"]', 'to mount up; hence, in general, to rise, (figuratively) be majestic gloriously, grow up, increase, be risen, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1207}/[H1206]', 'lemma', 'heb', 'בִּצָּה', '["bitstsâh"]', '["marsh"]', '["n-f"]', 'a swamp fen, mire(-ry place).', 'intensive from 1206;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7685A}/[H7685]', 'lemma', 'heb', 'שָׂגָה', '["sâgâh"]', '["will it grow?"]', '["v"]', 'to enlarge (especially upward, also figuratively) grow (up), increase.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0260}/[H260]', 'lemma', 'heb', 'אָחוּ', '["ʼâchûw"]', '["reed[s]"]', '["n-m"]', 'a bulrush or any marshy grass (particularly that along the Nile) flag, meadow.', 'of uncertain (perhaps Egyptian) derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0003}/H9023/[H24]', 'inflected', 'heb', 'אֵב', '["ʼêb"]', '["[is] in/ greenness/ its"]', '["n-m"]', 'a green plant greenness, fruit.', 'from the same as 24;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6998}/[H6998]', 'lemma', 'heb', 'קָטַף', '["qâṭaph"]', '["I will pluck off","it is plucked off","it plucked off"]', '["v"]', 'to strip off crop off, cut down (up), pluck.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8615B}/[H6960]', 'inflected', 'heb', 'תִּקְוָה', '["tiqvâh"]', '["and/ [the] hope of","and/ a hope"]', '["n-f"]', 'literally a cord (as an attachment); figuratively, expectancy expectation(-ted), hope, live, thing that I long for.', 'from 6960; (compare 6961)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2611}/[H2610]', 'lemma', 'heb', 'חָנֵף', '["chânêph"]', '["[is] godless","[the] godless","a godless [person]","godless","godless [people]"]', '["a"]', 'soiled (i.e. with sin), impious hypocrite(-ical).', 'from 2610;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6990}/[H6990]', 'lemma', 'heb', 'קָטַט', '["qâṭaṭ"]', '["it snaps"]', '["v"]', 'to clip off, i.e. (figuratively) destroy be cut off.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3689}/H9023/[H3688]', 'inflected', 'heb', 'כֶּסֶל', '["keçel"]', '["confidence/ his"]', '["n-m"]', 'properly, fatness, i.e. by implication (literally) the loin (as the seat of the leaf fat) or (generally) the viscera; also (figuratively) silliness or (in a good sense) trust confidence, flank, folly, hope, loin.', 'from 3688;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5908>', 'opaque', 'heb', 'עַכָּבִישׁ', '["ʻakkâbîysh"]', '["a spider"]', '["n-m"]', 'a spider (as weaving a network) spider.', 'probably from an unused root in the literal sense of entangling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4009}/H9023/[H982]', 'inflected', 'heb', 'מִבְטָח', '["mibṭâch"]', '["trust/ his"]', '["n-m"]', 'properly, a refuge, i.e. (objective) security, or (subjective) assurance confidence, hope, sure, trust.', 'from 982;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7373}/[H7372]', 'lemma', 'heb', 'רָטֹב', '["râṭôb"]', '["[is] a fresh [plant]"]', '["a"]', 'moist (with sap) green.', 'from 7372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1593}/H9023/[H1588]', 'inflected', 'heb', 'גַּנָּה', '["gannâh"]', '["garden/ its"]', '["n-f"]', 'a garden garden.', 'feminine of 1588;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3127}/H9023/[H3126]', 'inflected', 'heb', 'יוֹנֶקֶת', '["yôwneqeth"]', '["young shoot[s]/ his","young shoot[s]/ its","young shoots/ its"]', '["n-f"]', 'a sprout (tender) branch, young twig.', 'feminine of 3126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8328}/H9023/[H8327]', 'inflected', 'heb', 'שֶׁרֶשׁ', '["sheresh"]', '["root/ its","roots/ his","roots/ its"]', '["n-m"]', 'a root (literally or figuratively) bottom, deep, heel, root.', 'from 8327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5440}/[H5440]', 'lemma', 'heb', 'סָבַךְ', '["çâbak"]', '["they are interwoven"]', '["v"]', 'to entwine fold together, wrap.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1104}/H9033/[H1104]', 'inflected', 'heb', 'בָּלַע', '["bâlaʻ"]', '["he swallows up/ it","it swallows/ him","someone will swallow/ it","they will swallow/ it","we have swallowed/ him"]', '["v"]', 'to make away with (specifically by swallowing); generally, to destroy cover, destroy, devour, eat up, be at end, spend up, swallow down (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4885}/[H7797]', 'lemma', 'heb', 'מָשׂוֹשׂ', '["mâsôws"]', '["[is] [the] joy of","[the] gaiety of","[the] joy of","a joy","a joy of","exultation","joy","rejoicing"]', '["n-m"]', 'delight, concretely (the cause or object) or abstractly (the feeling) joy, mirth, rejoice.', 'from 7797;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6083}/[H6080]', 'inflected', 'heb', 'עָפָר', '["ʻâphâr"]', '["and/ from/ [the] dust"]', '["n-m"]', 'dust (as powdered or gray); hence, clay, earth, mud ashes, dust, earth, ground, morter, powder, rubbish.', 'from 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7814}/[H7832]', 'lemma', 'heb', 'שְׂחוֹק', '["sᵉchôwq"]', '["[is] a laughingstock","[the] laughter of","a laughingstock","laughter"]', '["n-m"]', 'laughter (in merriment or defiance) derision, laughter(-ed to scorn, -ing), mocked, sport.', 'or שְׂחֹק; from 7832;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8193G}/H9021/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["and/ lips/ your","and/ own lips/ your"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1322}/[H954]', 'lemma', 'heb', 'בֹּשֶׁת', '["bôsheth"]', '["[the] shame of","shame"]', '["n-f"]', 'shame (the feeling and the condition, as well as its cause); by implication (specifically) an idol ashamed, confusion, greatly, (put to) shame(-ful thing).', 'from 954;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0369}/H9043\/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["there not [is]/ he","there not [will be]/ it"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0533}/[H553]', 'inflected', 'heb', 'אַמִּיץ', '["ʼammîyts"]', '["and/ [the] [person] strong","and/ a strong [one]","and/ a strong [one] of","and/ strong of"]', '["a"]', 'strong or (abstractly) strength courageous, mighty, strong (one).', 'or (shortened) אַמִּץ; from 553;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6275}/[H6275]', 'inflected', 'heb', 'עָתַק', '["ʻâthaq"]', '["the/ [one who] removes"]', '["v"]', 'to remove (intransitive or transitive) figuratively, to grow old; specifically, to transcribe copy out, leave off, become (wax) old, remove.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2015}/H9038/[H2015]', 'inflected', 'heb', 'הָפַךְ', '["hâphak"]', '["he overturns/ them"]', '["v"]', 'to turn about or over; by implication, to change, overturn, return, pervert × become, change, come, be converted, give, make (a bed), overthrow (-turn), perverse, retire, tumble, turn (again, aside, back, to the contrary, every way).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7264}/[H7264]', 'inflected', 'heb', 'רָגַז', '["râgaz"]', '["the/ [one who] shakes"]', '["v"]', 'to quiver (with any violent emotion, especially anger or fear) be afraid, stand in awe, disquiet, fall out, fret, move, provoke, quake, rage, shake, tremble, trouble, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4725}/H9024/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["from/ place/ its"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5982G}/H9024/[H5975]', 'inflected', 'heb', 'עַמּוּד', '["ʻammûwd"]', '["and/ pillars/ its"]', '["n-m"]', 'a column (as standing); also a stand, i.e. platform × apiece, pillar.', 'or עַמֻּד; from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6426}/H9013/[H6426]', 'inflected', 'heb', 'פָּלַץ', '["pâlats"]', '["they tremble/ !"]', '["v"]', 'properly, perhaps to rend, i.e. (by implication) to quiver tremble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H2775A>', 'inflected', 'heb', 'לחרס', '["La./che.res"]', '["to the/ sun"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5906}/[H5789]', 'lemma', 'heb', 'עַיִשׁ', '["ʻAyish"]', '["[the] Bear"]', '["n-f"]', 'the constellation of the Great Bear (perhaps from its migration through the heavens) Arcturus.', 'or עָשׁ; from 5789;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3685G}/[H3684]', 'lemma', 'heb', 'כְּסִיל', '["Kᵉçîyl"]', '["Orion"]', '["n-m"]', 'any notable constellation; specifically Orion (as if a burly one) constellation, Orion.', 'the same as 3684;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3598}/[H3558]', 'inflected', 'heb', 'כִּימָה', '["Kîymâh"]', '["and/ Pleiades"]', '["n-f"]', 'a cluster of stars, i.e. the Pleiades Pleiades, seven stars.', 'from the same as 3558;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2315}/[H2314]', 'inflected', 'heb', 'חֶדֶר', '["cheder"]', '["and/ [the] chambers of"]', '["n-m"]', 'an apartment (usually literal) ((bed) inner) chamber, innermost(-ward) part, parlour, south, × within.', 'from 2314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2862}/[H2862]', 'lemma', 'heb', 'חָתַף', '["châthaph"]', '["he will snatch away"]', '["v"]', 'to clutch take away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7817}/[H7817]', 'lemma', 'heb', 'שָׁחַח', '["shâchach"]', '["I am bent over","I bowed","are you bowed down","by bowing down","he is bowed down","he will lay low","it is bowed down","it will be humbled","they bow","they have bowed down","they lay prostrate","they will crouch"]', '["v"]', 'to sink or depress (reflexive or causative) bend, bow (down), bring (cast) down, couch, humble self, be (bring) low, stoop.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7294}/[H7293]', 'lemma', 'heb', 'רַהַב', '["Rahab"]', '["Rahab"]', '["n-m"]', 'Rahab (i.e. boaster), an epithet of Egypt Rahab.', 'the same as 7293;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8199}/H9030/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["to/ judge/ my"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6030B}/H9030/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["and/ he answered/ me","and/ you answered/ me"]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8183}/[H8178]', 'inflected', 'heb', 'שְׂעָרָה', '["sᵉʻârâh"]', '["with/ a storm"]', '["n-f"]', 'a hurricane storm, tempest.', 'feminine of 8178;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7779}/H9030/[H7779]', 'inflected', 'heb', 'שׁוּף', '["shûwph"]', '["he crushes/ me","it will crush/ me"]', '["v"]', 'properly, to gape, i.e. snap at; figuratively, to overwhelm break, bruise, cover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6482}/H9020/[H6481]', 'inflected', 'heb', 'פֶּצַע', '["petsaʻ"]', '["wounds/ my"]', '["n-m"]', 'a wound wound(-ing).', 'from 6481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414K}/H9030/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["he permits/ me"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7307H}/H9020/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["breath/ my"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7646}/H9030/[H7646]', 'inflected', 'heb', 'שָׂבַע', '["sâbaʻ"]', '["he has surfeited/ me","he surfeits/ me"]', '["v"]', 'to sate, i.e. fill to satisfaction (literally or figuratively) have enough, fill (full, self, with), be (to the) full (of), have plenty of, be satiate, satisfy (with), suffice, be weary of.', 'or שָׂבֵעַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4472}/[H4843]', 'lemma', 'heb', 'מַמְרֹר', '["mamrôr"]', '["bitter things"]', '["n-m"]', 'a bitterness, i.e. (figuratively) calamity bitterness.', 'from 4843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3581B>', 'inflected', 'heb', 'לכח', '["le./Kho.ach"]', '["to/ power"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4941H}/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["for <the>/ judgment","for <the>/ justice","for/ justice","to <the>/ judgment","to <the>/ justice","to/ justice"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3259}/H9030/[H3259]', 'inflected', 'heb', 'יָעַד', '["yâʻad"]', '["will he summon/ me"]', '["v"]', 'to fix upon (by agreement or appointment); by implication, to meet (at a stated time), to summon (to trial), to direct (in a certain quarter or position), to engage (for marriage) agree,(maxke an) appoint(-ment, a time), assemble (selves), betroth, gather (selves, together), meet (together), set (a time).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7561}/H9030/[H7561]', 'inflected', 'heb', 'רָשַׁע', '["râshaʻ"]', '["it will condemn as guilty/ me","will he condemn as guilty/ me","will you condemn as guilty?/ me","you condemn as guilty/ me"]', '["v"]', 'to be (causatively, do or declare) wrong; by implication, to disturb, violate condemn, make trouble, vex, be (commit, deal, depart, do) wicked(-ly, -ness).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6140}/H9030/[H6140]', 'inflected', 'heb', 'עָקַשׁ', '["ʻâqash"]', '["and/ it declared guilty/ me"]', '["v"]', 'to knot or distort; figuratively, to pervert (act or declare perverse) make crooked, (prove, that is) perverse(-rt).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7752}/[H7751]', 'lemma', 'heb', 'שׁוֹט', '["shôwṭ"]', '["a scourge","a whip"]', '["n-m"]', 'a lash (literally or figuratively) scourge, whip.', 'from 7751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4531A}/[H5254]', 'inflected', 'heb', 'מַסָּה', '["maççâh"]', '["<to>/ [the] despair of"]', '["n-f"]', 'a testing, of men (judicial) or of God (querulous) temptation, trial.', 'from 5254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8199}/H9034/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["judges/ its"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3117G>/H9020', 'inflected', 'heb', 'וימי', '["ve./ya.Ma/i"]', '["and/ days/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0016}/[H14]', 'lemma', 'heb', 'אֵבֶה', '["ʼêbeh"]', '["reed"]', '["n-m"]', 'the papyrus swift.', 'from 14 (in the sense of bending toward);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2907}/[H2907]', 'lemma', 'heb', 'טוּשׂ', '["ṭûws"]', '["[which] it rushes"]', '["v"]', 'to pounce as a bird of prey haste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1082}/[H1082]', 'inflected', 'heb', 'בָּלַג', '["bâlag"]', '["and/ I will be cheerful","so/ I may be cheerful","so/ let me be cheerful"]', '["v"]', 'to break off or loose (in a favorable or unfavorable sense), i.e. desist (from grief) or invade (with destruction) comfort, (recover) strength(-en).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6094}/H9020/[H6087]', 'inflected', 'heb', 'עַצֶּבֶת', '["ʻatstsebeth"]', '["pains/ my"]', '["n-f"]', 'a idol; also, a pain or wound sorrow, wound.', 'from 6087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5352}/H9030/[H5352]', 'inflected', 'heb', 'נָקָה', '["nâqâh"]', '["acquit/ me","you will acquit/ me"]', '["v"]', 'to be (or make) clean (literally or figuratively); by implication (in an adverse sense) to be bare, i.e. extirpated acquit × at all, × altogether, be blameless, cleanse, (be) clear(-ing), cut off, be desolate, be free, be (hold) guiltless, be (hold) innocent, × by no means, be quit, be (leave) unpunished, × utterly, × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2141}/[H2135]', 'inflected', 'heb', 'זָכַךְ', '["zâkak"]', '["and/ I cleansed"]', '["v"]', 'to be transparent or clean (phys. or morally) be (make) clean, be pure(-r).', 'a primitive root (compare 2135);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1253}/[H1252]', 'inflected', 'heb', 'בֹּר', '["bôr"]', '["with/ potash"]', '["n-m"]', 'vegetable lye (from its cleansing); used as a soap for washing, or a flux for metals × never so, purely.', 'the same as 1252;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7845H}/[H7743]', 'inflected', 'heb', 'שַׁחַת', '["shachath"]', '["in <the>/ pit","in/ [the] pit"]', '["n-f"]', 'a pit (especially as a trap); figuratively, destruction corruption, destruction, ditch, grave, pit.', 'from 7743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2881}/H9030/[H2881]', 'inflected', 'heb', 'טָבַל', '["ṭâbal"]', '["you will dip/ me"]', '["v"]', 'to dip, to immerse dip, plunge.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8581}/H9030/[H8581]', 'inflected', 'heb', 'תַּעָב', '["taʻâb"]', '["and/ they will abhor/ me"]', '["v"]', 'to loathe, i.e. (morally) detest (make to be) abhor(-red), (be, commit more, do) abominable(-y), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8008}/H9020/[H8071]', 'inflected', 'heb', 'שַׂלְמָה', '["salmâh"]', '["own clothes/ my"]', '["n-f"]', 'a dress clothes, garment, raiment.', 'transp. for 8071;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7626G>/H9023', 'opaque', 'heb', 'שֵׁבֶט', '["shêbeṭ"]', '["rod/ his"]', '["n-m"]', 'a scion, i.e. (literally) a stick (for punishing, writing, fighting, ruling, walking, etc.) or (figuratively) a clan × correction, dart, rod, sceptre, staff, tribe.', 'from an unused root probably meaning to branch off;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0367}/H9023/[H366]', 'inflected', 'heb', 'אֵימָה', '["ʼêymâh"]', '["and/ dread/ his"]', '["n-f"]', 'fright; concrete, an idol (as a bugbear) dread, fear, horror, idol, terrible, terror.', 'or (shortened) אֵמָה; from the same as 366;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3372G}/H9033/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["I will fear/ him"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5354}/[H5354]', 'lemma', 'heb', 'נָקַט', '["nâqaṭ"]', '["it loathes"]', '["v"]', 'to loathe weary.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7378}/H9030/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["do you contend with/ me"]', '["v"]', 'properly, to toss, i.e. grapple; mostly figuratively, to wrangle, i.e. hold a controversy; (by implication) to defend adversary, chide, complain, contend, debate, × ever, × lay wait, plead, rebuke, strive, × thoroughly.', 'or רוּב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3709G}/H9021/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["hand/ your","hands/ your","palms/ your"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9004/<H3117G>', 'inflected', 'heb', 'הכימי', '["ha./khi./Mei"]', '["¿/ like/ [the] days of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8141}/H9021/[H8138]', 'inflected', 'heb', 'שָׁנֶה', '["shâneh"]', '["[are] years/ your","years/ your"]', '["n-f"]', 'a year (as a revolution of time) whole age, × long, old, year(× -ly).', '(in plural or (feminine) שָׁנָה; from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H3117I>', 'inflected', 'heb', 'כימי', '["Ki./mei"]', '["like/ [the] days of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5771G}/H9020/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["<to>/ iniquity/ my","for/ iniquity/ my"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2403B}/H9020/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["and/ for/ sin/ my"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1847}/H9021/[H3045]', 'inflected', 'heb', 'דַּעַת', '["daʻath"]', '["knowledge/ your"]', '["n"]', 'knowledge cunning, (ig-) norantly, know(-ledge), (un-) awares (wittingly).', 'from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6087B}/H9030/[H6087]', 'inflected', 'heb', 'עָצַב', '["ʻâtsab"]', '["they formed/ me"]', '["v"]', 'properly, to carve, i.e. fabricate or fashion; hence (in a bad sense) to worry, pain or anger displease, grieve, hurt, make, be sorry, vex, worship, wrest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6213H}/H9030/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["and/ they made/ me"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1104}/H9030/[H1104]', 'inflected', 'heb', 'בָּלַע', '["bâlaʻ"]', '["and/ you have swallowed/ me"]', '["v"]', 'to make away with (specifically by swallowing); generally, to destroy cover, destroy, devour, eat up, be at end, spend up, swallow down (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2563A}/[H2560]', 'inflected', 'heb', 'חֹמֶר', '["chômer"]', '["like <the>/ clay","like the/ clay","like/ [the] clay of","like/ [the] mud of"]', '["n-m"]', 'properly, a bubbling up, i.e. of water, a wave; of earth, mire or clay (cement); also a heap; hence, a chomer or dry measure clay, heap, homer, mire, motion.', 'from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213H}/H9030/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["I made for/ myself","[the one who] made/ me","he made/ me","it has made/ me","maker<s>/ my","they made/ me","you made/ me"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2461}/[H2459]', 'inflected', 'heb', 'חָלָב', '["châlâb"]', '["like <the>/ milk"]', '["n-m"]', 'milk (as the richness of kine) cheese, milk, sucking.', 'from the same as 2459;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5413}/H9030/[H5413]', 'inflected', 'heb', 'נָתַךְ', '["nâthak"]', '["did you pour out/ me"]', '["v"]', 'to flow forth (literally or figuratively); by implication, to liquify drop, gather (together), melt, pour (forth, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H1385}/[H1384]', 'inflected', 'heb', 'גְּבִנָה', '["gᵉbinâh"]', '["and/ like <the>/ cheese"]', '["n-f"]', 'curdled milk cheese.', 'feminine from the same as 1384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7087A}/H9030/[H7087]', 'inflected', 'heb', 'קָפָא', '["qâphâʼ"]', '["did you curdle?/ me"]', '["v n-m"]', 'to shrink, i.e. thicken (as unracked wine, curdled milk, clouded sky, frozen water) congeal, curdle, dark, settle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3847}/H9030/[H3847]', 'inflected', 'heb', 'לָבַשׁ', '["lâbash"]', '["did you clothe?/ me","he has clothed/ me"]', '["v"]', 'properly, wrap around, i.e. (by implication) to put on a garment or clothe (oneself, or another), literally or figuratively (in) apparel, arm, array (self), clothe (self), come upon, put (on, upon), wear.', 'or לָבֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6106G}/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["and/ with/ bones"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1517}/[H1464]', 'inflected', 'heb', 'גִּיד', '["gîyd"]', '["and/ [was] a sinew of","and/ sinews"]', '["n-m"]', 'a thong (as compressing); by analogy, a tendon sinew.', 'probably from 1464;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5526F}/H9030/[H5526]', 'inflected', 'heb', 'סָכַךְ', '["çâkak"]', '["did you weave together?/ me"]', '["v"]', 'properly, to entwine as a screen; by implication, to fence in, cover over, (figuratively) protect cover, defence, defend, hedge in, join together, set, shut up.', 'or שָׂכַךְ; (Exodus 33:22), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6486}/H9021/[H6485]', 'inflected', 'heb', 'פְּקֻדָּה', '["pᵉquddâh"]', '["and/ care/ your"]', '["n-f"]', 'visitation (in many senses, chiefly official) account, (that have the) charge, custody, that which...laid up, numbers, office(-r), ordering, oversight, prison, reckoning, visitation.', 'feminine passive participle of 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6845}/[H6845]', 'lemma', 'heb', 'צָפַן', '["tsâphan"]', '["I have hidden","I have treasured up","[is] stored up","[which] I have stored up","[which] they have been stored up","have they been stored up","he hides","he stores up","it has been concealed","let us lie hidden","they lie hidden","they store up","you have kept","you have stored up","you hid","you will treasure"]', '["v"]', 'to hide (by covering over); by implication, to hoard or reserve; figuratively to deny; specifically (favorably) to protect, (unfavorably) to lurk esteem, hide(-den one, self), lay up, lurk (be set) privily, (keep) secret(-ly, place).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8104I}/H9030/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["and/ you will watch/ me"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5771G}/H9020/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["and/ from/ iniquity/ my"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0480}/[H421]', 'lemma', 'heb', 'אַלְלַי', '["ʼalᵉlay"]', '["woe!"]', '["inj"]', 'alas! woe.', 'by reduplication from 421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7036}/[H7034]', 'lemma', 'heb', 'קָלוֹן', '["qâlôwn"]', '["[will be] [the] disgrace of","shame"]', '["n-m"]', 'disgrace; (by implication) the pudenda confusion, dishonour, ignominy, reproach, shame.', 'from 7034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7202}/[H7200]', 'inflected', 'heb', 'רָאֶה', '["râʼeh"]', '["and/ see"]', '["a"]', 'seeing, i.e. experiencing see.', 'from 7200;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1342}/[H1342]', 'inflected', 'heb', 'גָּאָה', '["gâʼâh"]', '["so/ it may rise up"]', '["v"]', 'to mount up; hence, in general, to rise, (figuratively) be majestic gloriously, grow up, increase, be risen, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H7826>', 'inflected', 'heb', 'כשחל', '["ka./Sha.chal","kha./Sha.chal"]', '["[will be] like <the>/ lion","like <the>/ lion"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6679A}/H9030/[H6718]', 'inflected', 'heb', 'צוּד', '["tsûwd"]', '["they hunted/ me","you hunt/ me"]', '["v"]', 'to lie alongside (i.e. in wait); by implication, to catch an animal (figuratively, men); to victual (for a journey) chase, hunt, sore, take (provision).', 'a primitive root; also denominative from 6718');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2318}/[H2318]', 'lemma', 'heb', 'חָדַשׁ', '["châdash"]', '["it renews itself","renew","you renew"]', '["v"]', 'to be new; causatively, to rebuild renew, repair.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5707}/H9021/[H5749]', 'inflected', 'heb', 'עֵד', '["ʻêd"]', '["witnesses/ your"]', '["n-m"]', 'concretely, a witness; abstractly, testimony; specifically, a recorder, i.e. prince witness.', 'contracted from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5048}/H9030/[H5046]', 'inflected', 'heb', 'נֶגֶד', '["neged"]', '["[are] before/ me","[is] before/ me","before/ me"]', '["prep"]', 'a front, i.e. part opposite; specifically a counterpart, or mate; usually (adverbial, especially with preposition) over against or before about, (over) against, × aloof, × far (off), × from, over, presence, × other side, sight, × to view.', 'from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3708B}/H9021/[H3707]', 'inflected', 'heb', 'כַּעַס', '["kaʻaç"]', '["vexation/ your"]', '["n-m"]', 'vexation anger, angry, grief, indignation, provocation, provoking, × sore, sorrow, spite, wrath.', 'or (in Job) כַּעַשׂ; from 3707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3318M}/H9030/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["did you bring out/ me"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2986}/[H2986]', 'lemma', 'heb', 'יָבַל', '["yâbal"]', '["I was brought","[which] it is led","he will be borne","it is brought","it is carried","it will be brought","it will be carried","let them bring","she is brought","they are brought","they are brought forth","they will bring"]', '["v"]', 'properly, to flow; causatively, to bring (especially with pomp) bring (forth), carry, lead (forth).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7896H}/[H7896]', 'inflected', 'heb', 'שִׁית', '["shîyth"]', '["and/ put"]', '["v"]', 'to place (in a very wide application) apply, appoint, array, bring, consider, lay (up), let alone, × look, make, mark, put (on), regard, set, shew, be stayed, × take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5890}/[H5774]', 'lemma', 'heb', 'עֵיפָה', '["ʻêyphâh"]', '["darkness"]', '["n-f"]', 'obscurity (as if from covering) darkness.', 'feminine from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6757}/[H6738]', 'lemma', 'heb', 'צַלְמָוֶת', '["tsalmâveth"]', '["[is] deep darkness","deep darkness"]', '["n-m"]', 'shade of death, i.e. the grave (figuratively, calamity) shadow of death.', 'from 6738 and 4194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5468>', 'opaque', 'heb', 'סֶדֶר', '["çeder"]', '["order<s>"]', '["n-m"]', 'order order.', 'from an unused root meaning to arrange;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3313}/[H3313]', 'inflected', 'heb', 'יָפַע', '["yâphaʻ"]', '["and/ he makes shine forth","and/ it shone forth"]', '["v"]', 'to shine be light, shew self, (cause to) shine (forth).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0652}\/[H651]', 'inflected', 'heb', 'אֹפֶל', '["ʼôphel"]', '["gloom"]', '["n-m"]', 'dusk darkness, obscurity, privily.', 'from the same as 651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6691}/[H6852]', 'lemma', 'heb', 'צוֹפַר', '["Tsôwphar"]', '["Zophar"]', '["n-pr-m"]', 'Tsophar, a friend of Job Zophar.', 'from 6852; departing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7230}/[H7231]', 'inflected', 'heb', 'רֹב', '["rôb"]', '["¿/ a multitude of"]', '["n-m"]', 'abundance (in any respect) abundance(-antly), all, × common (sort), excellent, great(-ly, -ness, number), huge, be increased, long, many, more in number, most, much, multitude, plenty(-ifully), × very (age).', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0907}/H9021/[H908]', 'inflected', 'heb', 'בַּד', '["bad"]', '["empty boasts/ your"]', '["n-m"]', 'a brag or lie; also a liar liar, lie.', 'from 908;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1249}/[H1305]', 'inflected', 'heb', 'בַּר', '["bar"]', '["and/ a [person] pure of","and/ clean"]', '["a"]', 'beloved; also pure, empty choice, clean, clear, pure.', 'from 1305 (in its various senses);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6605A}/[H6605]', 'inflected', 'heb', 'פָּתַח', '["pâthach"]', '["and/ he may open","so/ we may open"]', '["v"]', 'to open wide (literally or figuratively); specifically, to loosen, begin, plough, carve appear, break forth, draw (out), let go free, (en-) grave(-n), loose (self), (be, be set) open(-ing), put off, ungird, unstop, have vent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8193G}/H9023/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["lips/ his"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8587}/[H5956]', 'lemma', 'heb', 'תַּעֲלֻמָּה', '["taʻălummâh"]', '["[the] secrets of"]', '["n-f"]', 'a secret thing that is hid, secret.', 'from 5956;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3718}/[H3717]', 'lemma', 'heb', 'כֶּפֶל', '["kephel"]', '["double"]', '["n-m"]', 'a duplicate double.', 'from 3717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H8454>', 'inflected', 'heb', 'לתושיה', '["le./Tu.shi.Yah"]', '["[belongs] to/ sound wisdom"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5382}/[H5382]', 'lemma', 'heb', 'נָשָׁה', '["nâshâh"]', '["I have forgotten","he will cause to forget"]', '["v"]', 'to forget; figuratively, to neglect; causatively, to remit, remove forget, deprive, exact.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5771H}/H9021/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["some of/ iniquity/ your"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H2714}/[H2713]', 'inflected', 'heb', 'חֵקֶר', '["chêqer"]', '["¿/ [the] searching of"]', '["n-m"]', 'examination, enumeration, deliberation finding out, number, (un-) search(-able, -ed, out, -ing).', 'from 2713;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1363}/[H1361]', 'lemma', 'heb', 'גֹּבַהּ', '["gôbahh"]', '["[the] height of","[the] heights of","a height","haughtiness of"]', '["n-m"]', 'elation, grandeur, arrogance excellency, haughty, height, high, loftiness, pride.', 'from 1361;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7585}/[H7592]', 'inflected', 'heb', 'שְׁאוֹל', '["shᵉʼôwl"]', '["from/ Sheol","more than/ Sheol"]', '["n-f"]', 'hades or the world of the dead (as if a subterranean retreat), including its accessories and inmates grave, hell, pit.', 'or שְׁאֹל; from 7592;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4055}/H9024/[H4058]', 'inflected', 'heb', 'מַד', '["mad"]', '["measure/ its"]', '["n-m"]', 'properly, extent, i.e. height; also a measure; by implication, a vesture (as measured); also a carpet armour, clothes, garment, judgment, measure, raiment, stature.', 'or מֵד; from 4058;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3823A}/[H3823]', 'lemma', 'heb', 'לָבַב', '["lâbab"]', '["he will become intelligent"]', '["v"]', 'properly, to be enclosed (as if with fat); by implication (as denominative from 3824); to unheart; i.e. (in a good sense) transport (with love), or (in a bad sense) stultify; to make cakes make cakes, ravish, be wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7368}/H9033/[H7368]', 'inflected', 'heb', 'רָחַק', '["râchaq"]', '["put far away/ it"]', '["v"]', 'to widen (in any direction), i.e. (intransitively) recede or (transitively) remove (literally or figuratively, of place or relation) (a-, be, cast, drive, get, go, keep (self), put, remove, be too, (wander), withdraw) far (away, off), loose, × refrain, very, (be) a good way (off).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H3971B>', 'inflected', 'heb', 'ממום', '["mi./Mum"]', '["from/ blemish"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3332J}/[H3332]', 'lemma', 'heb', 'יָצַק', '["yâtsaq"]', '["[is] hard","firmly established","molten"]', '["v"]', 'properly, to pour out (transitive or intransitive); by implication, to melt or cast as metal; by extension, to place firmly, to stiffen or grow hard cast, cleave fast, be (as) firm, grow, be hard, lay out, molten, overflow, pour (out), run out, set down, stedfast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6672A}/[H6671]', 'inflected', 'heb', 'צֹהַר', '["tsôhar"]', '["and/ more than/ noon<s>"]', '["n-m"]', 'a light (i.e. window); dual double light, i.e. noon midday, noon(-day, -tide), window.', 'from 6671;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2465>', 'opaque', 'heb', 'חֶלֶד', '["cheled"]', '["[is] lifespan","[the] world","lifespan"]', '["n-m"]', 'life (as a fleeting portion of time); hence, the world (as transient) age, short time, world.', 'from an unused root apparently meaning to glide swiftly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5774B}/[H5775]', 'lemma', 'heb', 'עוּף', '["ʻûwph"]', '["it will be dark"]', '["v n-f"]', 'to fly; also (by implication of dimness) to faint (from the darkness of swooning) brandish, be (wax) faint, flee away, fly (away), × set, shine forth, weary.', 'a primitive root; to cover (with wings or obscurity); hence (as denominative from 5775)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1242}/[H1239]', 'inflected', 'heb', 'בֹּקֶר', '["bôqer"]', '["like the/ morning"]', '["n-m"]', 'properly, dawn (as the break of day); generally, morning ( ) day, early, morning, morrow.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440L}/H9021/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["face/ your"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4498}/[H5127]', 'inflected', 'heb', 'מָנוֹס', '["mânôwç"]', '["and/ a place of escape","and/ flight"]', '["n-m"]', 'a retreat (literally or figuratively); abstractly, a fleeing × apace, escape, way to flee, flight, refuge.', 'from 5127;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4480A}/H9038/[H4482]', 'inflected', 'heb', 'מִן', '["min"]', '["from/ them"]', '["prep"]', 'properly, a part of; hence (prepositionally), from or out of in many senses above, after, among, at, because of, by (reason of), from (among), in, × neither, × nor, (out) of, over, since, × then, through, × whether, with.', 'or מִנִּי; or מִנֵּי; (constructive plural) (Isaiah 30:11); for 4482;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8615B}/H9028/[H6960]', 'inflected', 'heb', 'תִּקְוָה', '["tiqvâh"]', '["and/ hope/ their"]', '["n-f"]', 'literally a cord (as an attachment); figuratively, expectancy expectation(-ted), hope, live, thing that I long for.', 'from 6960; (compare 6961)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4646}/[H5301]', 'lemma', 'heb', 'מַפָּח', '["mappâch"]', '["[will be] a gasp of"]', '["n-m"]', 'a breathing out (of life), i.e. expiring giving up.', 'from 5301;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315H}\/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["life"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3644G}/H9036/[H3651]', 'inflected', 'heb', 'כְּמוֹ', '["kᵉmôw"]', '["like/ you"]', '["prt"]', 'as, thus, so according to, (such) as (it were, well as), in comparison of, like (as, to, unto), thus, when, worth.', 'or כָּמוֹ; a form of the prefix k, but used separately [compare 3651];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0433}/[H410]', 'inflected', 'heb', 'אֱלוֹהַּ', '["ʼĕlôwahh"]', '["[are] for/ God","to/ God"]', '["n-m"]', 'a deity or the Deity God, god. See 430.', 'rarely (shortened) אֱלֹהַּ; probably prolonged (emphatic) from 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H6365>', 'inflected', 'heb', 'לפיד', '["la./Pid"]', '["[belongs] to <the>/ disaster"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0937}/[H936]', 'lemma', 'heb', 'בּוּז', '["bûwz"]', '["contempt"]', '["n-m"]', 'disrespect contempt(-uously), despised, shamed.', 'from 936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6248}/[H6245]', 'inflected', 'heb', 'עַשְׁתּוּת', '["ʻashtûwth"]', '["to/ [the] thought of"]', '["n-f"]', 'cogitation thought.', 'from 6245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7600}/[H7599]', 'lemma', 'heb', 'שַׁאֲנָן', '["shaʼănân"]', '["O carefree [women]","[one] at ease","carefree","undisturbed"]', '["a"]', 'secure; in a bad sense, haughty that is at ease, quiet, tumult. Compare 7946.', 'from 7599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3559B}/[H3559]', 'lemma', 'heb', 'כּוּן', '["kûwn"]', '["a push"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4571}/[H4571]', 'inflected', 'heb', 'מָעַד', '["mâʻad"]', '["[belongs] to/ [those who] are sliding of"]', '["v"]', 'to waver make to shake, slide, slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7703}/[H7703]', 'inflected', 'heb', 'שָׁדַד', '["shâdad"]', '["of/ destroyers","to/ devastate"]', '["v"]', 'properly, to be burly, i.e. (figuratively) powerful (passively, impregnable); by implication, to ravage dead, destroy(-er), oppress, robber, spoil(-er), × utterly, (lay) waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0987}/[H982]', 'inflected', 'heb', 'בַּטֻּחוֹת', '["baṭṭuchôwth"]', '["and/ securiti<es>"]', '["n-f"]', 'security secure.', 'feminine plural from 982;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7264}/[H7264]', 'inflected', 'heb', 'רָגַז', '["râgaz"]', '["[belong] to/ provokers of"]', '["v"]', 'to quiver (with any violent emotion, especially anger or fear) be afraid, stand in awe, disquiet, fall out, fret, move, provoke, quake, rage, shake, tremble, trouble, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3384B}/H9031/[H3384]', 'inflected', 'heb', 'יָרָה', '["yârâh"]', '["and/ I will teach/ you","and/ let it teach/ you","so/ it may teach/ you"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2441}/[H2596]', 'inflected', 'heb', 'חֵךְ', '["chêk"]', '["and/ [the] palate","and/ a palate"]', '["n-m"]', 'properly, the palate or inside of the mouth; hence, the mouth itself (as the organ of speech, taste and kissing) (roof of the) mouth, taste.', 'probably from 2596 in the sense of tasting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3453}/[H3486]', 'inflected', 'heb', 'יָשִׁישׁ', '["yâshîysh"]', '["[is] with/ aged [people]"]', '["a"]', 'an old man (very) aged (man), ancient, very old.', 'from 3486;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117H>', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["days"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3001}/[H3001]', 'inflected', 'heb', 'יָבֵשׁ', '["yâbêsh"]', '["and/ it may be withered","and/ they became dry","so/ they may be dry"]', '["v"]', 'to be ashamed, confused or disappointed; also (as failing) to dry up (as water) or wither (as herbage) be ashamed, clean, be confounded, (make) dry (up), (do) shame(-fully), × utterly, wither (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7686}/[H7686]', 'inflected', 'heb', 'שָׁגָה', '["shâgâh"]', '["and/ [one who] leads astray"]', '["v"]', 'to stray (causatively, mislead), usually (figuratively) to mistake, especially (morally) to transgress; by extension (through the idea of intoxication) to reel, (figuratively) be enraptured (cause to) go astray, deceive, err, be ravished, sin through ignorance, (let, make to) wander.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7758}/[H7997]', 'lemma', 'heb', 'שׁוֹלָל', '["shôwlâl"]', '["barefoot"]', '["a"]', 'nude (especially bare-foot); by implication, captive spoiled, stripped.', 'or שֵׁילָל; (Micah 1:8), from 7997;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1984C}/[H1984]', 'lemma', 'heb', 'הָלַל', '["hâlal"]', '["boasters","he makes look foolish","they are acting like mad people","they will act like mad people","you boast"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4148I}/[H3256]', 'lemma', 'heb', 'מוּסָר', '["mûwçâr"]', '["[the] chastening of","[the] correction of"]', '["n-m"]', 'properly, chastisement; figuratively, reproof, warning or instruction; also restraint bond, chastening(-eth), chastisement, check, correction, discipline, doctrine, instruction, rebuke.', 'from 3256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0232}/[H246]', 'lemma', 'heb', 'אֵזוֹר', '["ʼêzôwr"]', '["[the] waistband of","a loincloth","a loincloth of","a waistband"]', '["n-m"]', 'something girt; a belt, also a band girdle.', 'from 246;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0386>', 'inflected', 'heb', 'ואתנים', '["ve./''e.ta.Nim"]', '["and/ [people] long established"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5557}/[H5557]', 'lemma', 'heb', 'סָלַף', '["çâlaph"]', '["[he is] subverting","he overturns","it subverts"]', '["v"]', 'properly, to wrench, i.e. (figuratively) to subvert overthrow, pervert.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2940}/[H2938]', 'inflected', 'heb', 'טַעַם', '["ṭaʻam"]', '["and/ [the] discernment of"]', '["n-m"]', 'properly, a taste, i.e. (figuratively) perception; by implication, intelligence; transitively, a mandate advice, behaviour, decree, discretion, judgment, reason, taste, understanding.', 'from 2938;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4206B}/[H2118]', 'inflected', 'heb', 'מָזִיחַ', '["mâzîyach"]', '["and/ [the] belt of"]', '["n-m"]', 'a belt (as movable) girdle, strength.', 'or מֵזַח; from 2118;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7679}/[H7679]', 'lemma', 'heb', 'שָׂגָא', '["sâgâʼ"]', '["[he is] making great","you will magnify"]', '["v"]', 'to grow, i.e. (causatively) to enlarge, (figuratively) laud increase, magnify.', '; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7910}/[H7937]', 'inflected', 'heb', 'שִׁכּוֹר', '["shikkôwr"]', '["like <the>/ drunkard"]', '["a"]', 'intoxicated, as a state or a habit drunk(-ard, -en, -en man).', 'or שִׁכֹּר; from 7937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1847}/H9026/[H3045]', 'inflected', 'heb', 'דַּעַת', '["daʻath"]', '["like/ knowledge/ your"]', '["n"]', 'knowledge cunning, (ig-) norantly, know(-ledge), (un-) awares (wittingly).', 'from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2950}/[H2950]', 'lemma', 'heb', 'טָפַל', '["ṭâphal"]', '["[are] smearers of","they have smeared"]', '["v"]', 'properly, to stick on as a patch; figuratively, to impute falsely forge(-r), sew up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2790B}/H9013/[H2790]', 'inflected', 'heb', 'חָרַשׁ', '["chârash"]', '["you will be silent/ !"]', '["v"]', 'to scratch, i.e. (by implication) to engrave, plough; hence (from the use of tools) to fabricate (of any material); figuratively, to devise (in a bad sense); hence (from the idea of secrecy) to be silent, to let alone; hence (by implication) to be deaf (as an accompaniment of dumbness) × altogether, cease, conceal, be deaf, devise, ear, graven, imagine, leave off speaking, hold peace, plow(-er, man), be quiet, rest, practise secretly, keep silence, be silent, speak not a word, be still, hold tongue, worker.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2451}/[H2449]', 'inflected', 'heb', 'חׇכְמָה', '["chokmâh"]', '["<into>/ wisdom","of <the>/ wisdom","to <the>/ wisdom"]', '["n-f"]', 'wisdom (in a good sense) skilful, wisdom, wisely, wit.', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8433B}/H9020/[H3198]', 'inflected', 'heb', 'תּוֹכֵחָה', '["tôwkêchâh"]', '["argument/ my","complaint/ my","rebuke/ my"]', '["n-f"]', 'chastisement; figuratively (by words) correction, refutation, proof (even in defence) argument, × chastened, correction, reasoning, rebuke, reproof, × be (often) reproved.', 'and תּוֹכַחַת; from 3198;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7379}/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["and/ [the] contentions of","and/ [the] lawsuit of","and/ a case at law","and/ a case at law of","and/ strife"]', '["n-m"]', 'a contest (personal or legal) adversary, cause, chiding, contend(-tion), controversy, multitude (from the margin), pleading, strife, strive(-ing), suit.', 'or רִב; from 7378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8193G}/H9020/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["lips/ my"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9005/{H0410G}/[H352]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["¿/ <the> for/ God","¿/ to/ God"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7423A}/[H7411]', 'lemma', 'heb', 'רְמִיָּה', '["rᵉmîyâh"]', '["<of> deceit","[is] deceit","deceit","slackness"]', '["n-f"]', 'remissness, treachery deceit(-ful, -fully), false, guile, idle, slack, slothful.', 'from 7411;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H6440N}/H9023/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["¿/ face/ his"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375Q}/H9013/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["will you lift up/ !","you will lift up/ !"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2048B}/[H2048]', 'inflected', 'heb', 'הָתַל', '["hâthal"]', '["as/ deceives"]', '["v"]', 'to deride; by implication, to cheat deal deceitfully, deceive, mock.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7613}/H9023/[H5375]', 'inflected', 'heb', 'שְׂאֵת', '["sᵉʼêth"]', '["majesty/ his"]', '["n-f"]', 'an elevation or leprous scab; figuratively, elation or cheerfulness; exaltation in rank or character be accepted, dignity, excellency, highness, raise up self, rising.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6343}/H9023/[H6342]', 'inflected', 'heb', 'פַּחַד', '["pachad"]', '["and/ dread/ his"]', '["n-m"]', 'a (sudden) alarm (properly, the object feared, by implication, the feeling) dread(-ful), fear, (thing) great (fear, -ly feared), terror.', 'from 6342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2146}/H9026/[H2142]', 'inflected', 'heb', 'זִכְרוֹן', '["zikrôwn"]', '["memorials/ your"]', '["n-m"]', 'a memento (or memorable thing, day or writing) memorial, record.', 'from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H1354>', 'inflected', 'heb', 'לגבי', '["le./ga.bei"]', '["[are] <to>/ defenses of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1354>/H9026', 'opaque', 'heb', 'גַב', '["gab"]', '["defenses/ your"]', '["n"]', 'the back (as rounded); by analogy, the top or rim, a boss, a vault, arch of eye, bulwarks, etc. back, body, boss, eminent (higher) place, (eye) brows, nave, ring.', 'from an unused root meaning to hollow or curve; (compare 1460 and 1479)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8127G}/H9020/[H8150]', 'inflected', 'heb', 'שֵׁן', '["shên"]', '["in/ teeth/ my"]', '["n-f"]', 'a tooth (as sharp); specifically ivory; figuratively, a cliff crag, × forefront, ivory, × sharp, tooth.', 'from 8150; compare 8143');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5315H}/H9020/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["and/ life/ my"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6991}/H9030/[H6991]', 'inflected', 'heb', 'קָטַל', '["qâṭal"]', '["he will kill/ me"]', '["v"]', 'properly, to cut off, i.e. (figuratively) put to death kill, slay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4405}/H9020/[H4448]', 'inflected', 'heb', 'מִלָּה', '["millâh"]', '["speech/ my","words/ my"]', '["n-f"]', 'a word; collectively, a discourse; figuratively, a topic answer, by-word, matter, any thing (what) to say, to speak(-ing), speak, talking, word.', 'from 4448 (plural masculine as if from מִלֶּה;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0262}/H9020/[H2331]', 'inflected', 'heb', 'אַחְוָה', '["ʼachvâh"]', '["and/ declaration/ my"]', '["n-f"]', 'an utterance declaration.', 'from 2331 (in the sense of 2324);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0241G}/H9026/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["[be] in/ ears/ your","in/ ears/ your","with/ own ears/ your"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6440H}/H9021/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["from/ before/ you","from/ presence/ your"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0367}/H9021/[H366]', 'inflected', 'heb', 'אֵימָה', '["ʼêymâh"]', '["and/ dread/ your"]', '["n-f"]', 'fright; concrete, an idol (as a bugbear) dread, fear, horror, idol, terrible, terror.', 'or (shortened) אֵמָה; from the same as 366;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7725M}/H9030/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ respond to/ me"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2403B}/H9020/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["and/ sin/ my"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2803J}/H9030/[H2803]', 'inflected', 'heb', 'חָשַׁב', '["châshab"]', '["and/ do you consider?/ me"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5929}/[H5927]', 'inflected', 'heb', 'עָלֶה', '["ʻâleh"]', '["¿/ a leaf"]', '["n-m"]', 'a leaf (as coming up on a tree); collectively, foliage branch, leaf.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3423G}/H9030/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["and/ you cause to inherit/ me"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5271A}/H9020/[H5288]', 'inflected', 'heb', 'נָעוּר', '["nâʻûwr"]', '["youth<s>/ my"]', '["n-m n-f"]', '(only in plural collective or emphatic form) youth, the state (juvenility) or the persons (young people) childhood, youth.', 'or נָעֻר; and (feminine) נְעֻרָה; properly, passive participle from 5288 as denominative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H5465>', 'inflected', 'heb', 'בסד', '["ba./Sad"]', '["in the/ stock[s]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8104I}/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["and/ [one who] keeps","and/ [those who] watch of","so/ you may watch"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0734}/H9020/[H732]', 'inflected', 'heb', 'אֹרַח', '["ʼôrach"]', '["paths/ my","way/ my"]', '["n-m"]', 'a well-trodden road (literally or figuratively); also a caravan manner, path, race, rank, traveller, troop, (by-, high-) way.', 'from 732;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2707}/[H2707]', 'lemma', 'heb', 'חָקָה', '["châqâh"]', '["[was] carved","a carved [thing]","you make a mark"]', '["v"]', 'to carve; by implication, to delineate; also to entrench carved work, portrayed, set a print.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7538}/[H7537]', 'inflected', 'heb', 'רָקָב', '["râqâb"]', '["like/ rottenness"]', '["n-m"]', 'decay (by caries) rottenness (thing).', 'from 7537;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0899B}/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["like <the>/ garment","like/ a garment"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6731A}/[H6692]', 'inflected', 'heb', 'צִיץ', '["tsîyts"]', '["[is] like/ [the] flower of","like/ [the] flower of","like/ a flower"]', '["n-m"]', 'properly, glistening, i.e. a burnished plate; also a flower (as bright colored); a wing (as gleaming in the air) blossom, flower, plate, wing.', 'or צִץ; from 6692;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5243A}/[H5243]', 'inflected', 'heb', 'נָמַל', '["nâmal"]', '["and/ he withered"]', '["v"]', 'to become clipped or (specifically) circumcised (branch to) be cut down (off), circumcise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2931}/[H2930]', 'inflected', 'heb', 'טָמֵא', '["ṭâmêʼ"]', '["from/ an unclean [thing]"]', '["a"]', 'foul in a religious sense defiled, infamous, polluted(-tion), unclean.', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2706I}/H9023/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["limit/ its","limits/ his"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6086H}/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["for <the>/ a tree","to <the>/ wood"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3127}/H9023/[H3126]', 'inflected', 'heb', 'יוֹנֶקֶת', '["yôwneqeth"]', '["and/ young shoot[s]/ its"]', '["n-f"]', 'a sprout (tender) branch, young twig.', 'feminine of 3126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6083}/[H6080]', 'inflected', 'heb', 'עָפָר', '["ʻâphâr"]', '["and/ in the/ dust"]', '["n-m"]', 'dust (as powdered or gray); hence, clay, earth, mud ashes, dust, earth, ground, morter, powder, rubbish.', 'from 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1503>/H9023', 'opaque', 'heb', 'גֶּזַע', '["gezaʻ"]', '["stump/ its"]', '["n-m"]', 'the trunk or stump of a tree (as felled or as planted) stem, stock.', 'from an unused root meaning to cut down (trees);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7381}/[H7306]', 'inflected', 'heb', 'רֵיחַ', '["rêyach"]', '["from/ [the] scent of"]', '["n-m"]', 'odor (as if blown) savour, scent, smell.', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7105B}/[H7114]', 'lemma', 'heb', 'קָצִיר', '["qâtsîyr"]', '["shoot[s]"]', '["n-m"]', 'severed, i.e. harvest (as reaped), the crop, the time, the reaper, or figuratively; also a limb (of a tree, or simply foliage) bough, branch, harvest (man).', 'from 7114;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5194}/[H5193]', 'lemma', 'heb', 'נֶטַע', '["neṭaʻ"]', '["[is] [the] plantation of","a plant","plantations of"]', '["n-m"]', 'a plant; collectively, a plantation; abstractly, a planting plant.', 'from 5193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1397}/[H1396]', 'inflected', 'heb', 'גֶּבֶר', '["geber"]', '["and/ a man"]', '["n-m"]', 'properly, a valiant man or warrior; generally, a person simply every one, man, × mighty.', 'from 1396;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8142}/H9028/[H3462]', 'inflected', 'heb', 'שֵׁנָה', '["shênâh"]', '["from/ sleep/ their"]', '["n-f"]', 'sleep sleep.', 'or שֵׁנָא; (Psalm 127:2), from 3462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7585}/[H7592]', 'inflected', 'heb', 'שְׁאוֹל', '["shᵉʼôwl"]', '["in/ Sheol"]', '["n-f"]', 'hades or the world of the dead (as if a subterranean retreat), including its accessories and inmates grave, hell, pit.', 'or שְׁאֹל; from 7592;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6845}/H9030/[H6845]', 'inflected', 'heb', 'צָפַן', '["tsâphan"]', '["he will conceal/ me","you will hide/ me"]', '["v"]', 'to hide (by covering over); by implication, to hoard or reserve; figuratively to deny; specifically (favorably) to protect, (unfavorably) to lurk esteem, hide(-den one, self), lay up, lurk (be set) privily, (keep) secret(-ly, place).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5641}/H9030/[H5641]', 'inflected', 'heb', 'סָתַר', '["çâthar"]', '["he concealed/ me","he will hide/ me","you will conceal/ me","you will hide/ me"]', '["v"]', 'to hide (by covering), literally or figuratively be absent, keep close, conceal, hide (self), (keep) secret, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2142}/H9030/[H2145]', 'inflected', 'heb', 'זָכַר', '["zâkar"]', '["and/ you will remember/ me"]', '["v"]', 'properly, to mark (so as to be recognized), i.e. to remember; by implication, to mention; to be male × burn (incense), × earnestly, be male, (make) mention (of), be mindful, recount, record(-er), remember, make to be remembered, bring (call, come, keep, put) to (in) remembrance, × still, think on, × well.', 'a primitive root; also as denominative from 2145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6635I}/H9020/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["service/ my"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2487}/H9020/[H2498]', 'inflected', 'heb', 'חֲלִיפָה', '["chălîyphâh"]', '["relief/ my"]', '["n-f"]', 'alternation change, course.', 'from 2498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4639G}/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["for/ [the] work of","to/ [the] products of","to/ [the] work of"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2950}/[H2950]', 'inflected', 'heb', 'טָפַל', '["ṭâphal"]', '["and/ you have smeared"]', '["v"]', 'properly, to stick on as a patch; figuratively, to impute falsely forge(-r), sew up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6697H}/[H6696]', 'inflected', 'heb', 'צוּר', '["tsûwr"]', '["and/ O rock","and/ [the] rock of","and/ a rock"]', '["n-m"]', 'properly, a cliff (or sharp rock, as compressed); generally, a rock or boulder; figuratively, a refuge; also an edge (as precipitous) edge, × (mighty) God (one), rock, × sharp, stone, × strength, × strong. See also 1049.', 'or צֻר; from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6275}/[H6275]', 'lemma', 'heb', 'עָתַק', '["ʻâthaq"]', '["it has grown weak","it moves","they copied","they grow old","they have moved away"]', '["v"]', 'to remove (intransitive or transitive) figuratively, to grow old; specifically, to transcribe copy out, leave off, become (wax) old, remove.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7833}/[H7833]', 'lemma', 'heb', 'שָׁחַק', '["shâchaq"]', '["they rub away"]', '["v"]', 'to comminate (by trituration or attrition) beat, wear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5599A}/H9024/[H5596]', 'inflected', 'heb', 'סָפִיחַ', '["çâphîyach"]', '["overflowings/ its"]', '["n-m"]', 'something (spontaneously) falling off, i.e. a self-sown crop; figuratively, a freshet (such) things as (which) grow (of themselves), which groweth of its own accord (itself).', 'from 5596;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8630}/H9033/[H8630]', 'inflected', 'heb', 'תָּקַף', '["tâqaph"]', '["it overpowers/ him","someone will overpower/ him","you overpower/ him"]', '["v"]', 'to overpower prevail (against).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6819}/[H6819]', 'inflected', 'heb', 'צָעַר', '["tsâʻar"]', '["and/ they may be insignificant"]', '["v"]', 'to be small, i.e. (figuratively) ignoble be brought low, little one, be small.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5315I}/H9023/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["and/ [that which] self/ his","and/ life/ his","and/ self/ his"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0056}\/[H56]', 'inflected', 'heb', 'אָבַל', '["ʼâbal"]', '["it mourns"]', '["v"]', 'to bewail lament, mourn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H2450}/[H2449]', 'inflected', 'heb', 'חָכָם', '["châkâm"]', '["¿/ a wise [person]"]', '["a"]', 'wise, (i.e. intelligent, skilful or artful) cunning (man), subtil, (un-), wise((hearted), man).', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0990G>/H9023', 'opaque', 'heb', 'בֶּטֶן', '["beṭen"]', '["belly/ his","belly/ its"]', '["n-f"]', 'the belly, especially the womb; also the bosom or body of anything belly, body, as they be born, within, womb.', 'from an unused root probably meaning to be hollow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1697H}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["in/ words","with/ a word"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4405}/[H4448]', 'inflected', 'heb', 'מִלָּה', '["millâh"]', '["and/ words"]', '["n-f"]', 'a word; collectively, a discourse; figuratively, a topic answer, by-word, matter, any thing (what) to say, to speak(-ing), speak, talking, word.', 'from 4448 (plural masculine as if from מִלֶּה;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1639}/[H1639]', 'inflected', 'heb', 'גָּרַע', '["gâraʻ"]', '["and/ you may restrain?","so/ you may diminish"]', '["v"]', 'to scrape off; by implication, to shave, remove, lessen, withhold abate, clip, (di-) minish, do (take) away, keep back, restrain, make small, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7881}/[H7879]', 'lemma', 'heb', 'שִׂיחָה', '["sîychâh"]', '["[are] a meditation","meditation"]', '["n-f"]', 'reflection; by extension, devotion meditation, prayer.', 'feminine of 7879;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0502}/[H502]', 'lemma', 'heb', 'אָלַף', '["ʼâlaph"]', '["it teaches","you should learn"]', '["v"]', 'hence, to learn (and causatively to teach) learn, teach, utter.', 'a primitive root, to associate with;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5771G}/H9021/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["iniquities/ your","iniquity/ your"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7561}/H9031/[H7561]', 'inflected', 'heb', 'רָשַׁע', '["râshaʻ"]', '["it condemns as guilty/ you"]', '["v"]', 'to be (causatively, do or declare) wrong; by implication, to disturb, violate condemn, make trouble, vex, be (commit, deal, depart, do) wicked(-ly, -ness).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7223G}/[H7221]', 'inflected', 'heb', 'רִאשׁוֹן', '["riʼshôwn"]', '["¿/ first"]', '["a"]', 'first, in place, time or rank (as adjective or noun) ancestor, (that were) before(-time), beginning, eldest, first, fore(-father) (-most), former (thing), of old time, past.', 'or רִאשֹׁן; from 7221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2342H}/[H2342]', 'lemma', 'heb', 'חוּל', '["chûwl"]', '["I was brought forth","[the] giving birth of","it brings forth","were you brought forth?"]', '["v"]', 'properly, to twist or whirl (in a circular or spiral manner), i.e. (specifically) to dance, to writhe in pain (especially of parturition) or fear; figuratively, to wait, to pervert bear, (make to) bring forth, (make to) calve, dance, drive away, fall grievously (with pain), fear, form, great, grieve, (be) grievous, hope, look, make, be in pain, be much (sore) pained, rest, shake, shapen, (be) sorrow(-ful), stay, tarry, travail (with pain), tremble, trust, wait carefully (patiently), be wounded.', 'or חִיל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9003/{H5475}/[H3245]', 'inflected', 'heb', 'סוֹד', '["çôwd"]', '["¿/ in/ [the] council of"]', '["n-m"]', 'a session, i.e. company of persons (in close deliberation); by implication, intimacy, consultation, a secret assembly, consel, inward, secret (counsel).', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7867}/[H7867]', 'lemma', 'heb', 'שִׂיב', '["sîyb"]', '["[the] gray haired"]', '["v"]', 'properly, to become aged, i.e. (by implication) to grow gray (be) grayheaded.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3453}/[H3486]', 'lemma', 'heb', 'יָשִׁישׁ', '["yâshîysh"]', '["[are] aged","[the] aged"]', '["a"]', 'an old man (very) aged (man), ancient, very old.', 'from 3486;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8575}/[H5162]', 'lemma', 'heb', 'תַּנְחוּם', '["tanchûwm"]', '["[are] [the] consolations of","consolations"]', '["n"]', 'compassion, solace comfort, consolation.', 'or תַּנְחֻם; and (feminine) תַּנְחוּמָה; from 5162;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7335}/H9013/[H7335]', 'inflected', 'heb', 'רָזַם', '["râzam"]', '["do they flash/ !"]', '["v"]', 'to twinkle the eye (in mockery) wink.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3318O}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ you will bring out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2135}/[H2141]', 'lemma', 'heb', 'זָכָה', '["zâkâh"]', '["I have kept pure","cleanse yourselves","he will be pure","will he be pure","will he keep pure","you will be pure"]', '["v"]', 'to be translucent; figuratively, to be innocent be (make) clean, cleanse, be clear, count pure.', 'a primitive root (compare 2141);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6918G}/H9023/[H6942]', 'inflected', 'heb', 'קָדוֹשׁ', '["qâdôwsh"]', '["in/ holy [ones]/ his"]', '["a"]', 'sacred (ceremonially or morally); (as noun) God (by eminence), an angel, a saint, a sanctuary holy (One), saint.', 'or קָדֹשׁ; from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2141}/[H2135]', 'lemma', 'heb', 'זָכַךְ', '["zâkak"]', '["they are pure","they were bright"]', '["v"]', 'to be transparent or clean (phys. or morally) be (make) clean, be pure(-r).', 'a primitive root (compare 2135);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0444}/[H444]', 'inflected', 'heb', 'אָלַח', '["ʼâlach"]', '["and/ [one who] is corrupt"]', '["v"]', 'to muddle, i.e. (figuratively and intransitive) to turn (morally) corrupt become filthy.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2331}/H9031/[H2324]', 'inflected', 'heb', 'חָוָה', '["châvâh"]', '["I will tell/ you"]', '["v"]', 'properly, to live; by implication (intensively) to declare or show show.', 'a primitive root; (compare 2324, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2342I}/[H2342]', 'lemma', 'heb', 'חוּל', '["chûwl"]', '["I have been in labor","[is] writhing in pain","it will writhe in agony","people will be in anguish","she has been in labor","she is in labor","she was in labor","surely <writhe in agony>","they writhed","they writhed in agony","we were in labor","writhe in pain"]', '["v"]', 'properly, to twist or whirl (in a circular or spiral manner), i.e. (specifically) to dance, to writhe in pain (especially of parturition) or fear; figuratively, to wait, to pervert bear, (make to) bring forth, (make to) calve, dance, drive away, fall grievously (with pain), fear, form, great, grieve, (be) grievous, hope, look, make, be in pain, be much (sore) pained, rest, shake, shapen, (be) sorrow(-ful), stay, tarry, travail (with pain), tremble, trust, wait carefully (patiently), be wounded.', 'or חִיל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6184}/[H6206]', 'inflected', 'heb', 'עָרִיץ', '["ʻârîyts"]', '["for <the>/ ruthless [person]"]', '["a"]', 'fearful, i.e. powerful or tyrannical mighty, oppressor, in great power, strong, terrible, violent.', 'from 6206;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935G}/H9033/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["he will come to/ him","it will come to/ him","may it come to/ him","you must cause to go/ it"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6822}/[H6822]', 'inflected', 'heb', 'צָפָה', '["tsâphâh"]', '["and/ [is] watched","and/ watch","so/ I may watch"]', '["v"]', 'properly, to lean forward, i.e. to peer into the distance; by implication, to observe, await behold, espy, look up (well), wait for, (keep the) watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4691}/[H4690]', 'inflected', 'heb', 'מְצוּקָה', '["mᵉtsûwqâh"]', '["and/ distress"]', '["n-f"]', 'narrowness, i.e. (figuratively) trouble anguish, distress.', 'or מְצֻקָה; feminine of 4690;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3593>', 'inflected', 'heb', 'לכידור', '["la./ki.Dor"]', '["for <the>/ battle"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4043}/H9023/[H1598]', 'inflected', 'heb', 'מָגֵן', '["mâgên"]', '["shields/ his"]', '["n-m"]', 'a shield (i.e. the small one or buckler); figuratively, a protector; also the scaly hide of the crocodile × armed, buckler, defence, ruler, scale, shield.', 'also (in plural) feminine מְגִנָּה; from 1598;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2459>/H9023', 'inflected', 'heb', 'בחלבו', '["be./chel.B/o"]', '["with/ fat/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6371>', 'opaque', 'heb', 'פִּימָה', '["pîymâh"]', '["fat"]', '["n-f"]', 'obesity collops.', 'probably from an unused root meaning to be plump;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3689}/[H3688]', 'lemma', 'heb', 'כֶּסֶל', '["keçel"]', '["loins","stupidity"]', '["n-m"]', 'properly, fatness, i.e. by implication (literally) the loin (as the seat of the leaf fat) or (generally) the viscera; also (figuratively) silliness or (in a good sense) trust confidence, flank, folly, hope, loin.', 'from 3688;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6257}/[H6257]', 'lemma', 'heb', 'עָתַד', '["ʻâthad"]', '["they are destined"]', '["v"]', 'to prepare make fit, be ready to become.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1530G}/[H1556]', 'inflected', 'heb', 'גַּל', '["gal"]', '["<into>/ heaps of stones","for/ heaps of stones","into <the>/ heap","into/ heaps of stones"]', '["n-m"]', 'something rolled, i.e. a heap of stone or dung (plural ruins), by analogy, a spring of water (plural waves) billow, heap, spring, wave.', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4512}/H9028/[H5239]', 'inflected', 'heb', 'מִנְלֶה', '["minleh"]', '["property/ their"]', '["n-m"]', 'completion, i.e. (in produce) wealth perfection.', 'from 5239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7957}/[H3851]', 'lemma', 'heb', 'שַׁלְהֶבֶת', '["shalhebeth"]', '["a flame","flame"]', '["n-f"]', 'a flare of fire (flaming) flame.', 'from the same as 3851 with sibilant prefix;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5493H}/[H5493]', 'inflected', 'heb', 'סוּר', '["çûwr"]', '["and/ [is] turning aside","and/ [one who] turned aside","and/ turn aside","so/ he may depart"]', '["v"]', 'to turn off (literally or figuratively) be(-head), bring, call back, decline, depart, eschew, get (you), go (aside), × grievous, lay away (by), leave undone, be past, pluck away, put (away, down), rebel, remove (to and fro), revolt, × be sour, take (away, off), turn (aside, away, in), withdraw, be without.', 'or שׂוּר; (Hosea 9:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7723H}/[H7722]', 'inflected', 'heb', 'שָׁוְא', '["shâvᵉʼ"]', '["in <the>/ worthlessness"]', '["n-m"]', 'evil (as destructive), literally (ruin) or morally (especially guile); figuratively idolatry (as false, subjective), uselessness (as deceptive, objective; also adverbially, in vain) false(-ly), lie, lying, vain, vanity.', 'or שַׁו; from the same as 7722 in the sense of desolating;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8545}/H9023/[H4171]', 'inflected', 'heb', 'תְּמוּרָה', '["tᵉmûwrâh"]', '["recompense/ his","trading/ his"]', '["n-f"]', 'barter, compensation (ex-) change(-ing), recompense, restitution.', 'from 4171;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3712}/H9023/[H3709]', 'inflected', 'heb', 'כִּפָּה', '["kippâh"]', '["and/ palm branch/ his"]', '["n-f"]', 'a leaf of a palmtree branch.', 'feminine of 3709;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7488A>', 'opaque', 'heb', 'רַעֲנָן', '["raʻănân"]', '["it will grow luxuriant"]', '["v a"]', 'verdant; by analogy, new; figuratively, prosperous green, flourishing.', 'from an unused root meaning to be green;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2554}/[H2554]', 'lemma', 'heb', 'חָמַס', '["châmaç"]', '["[is] doing wrong to","he will wrong","they do violence to","they have done violence to","they have suffered violence","you do violence","you treat violently"]', '["v"]', 'to be violent; by implication, to maltreat make bare, shake off, violate, do violence, take away violently, wrong, imagine wrongfully.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H1612>', 'inflected', 'heb', 'כגפן', '["ka./Ge.fen","ke./Ge.fen","kha./Ga.fen","kha./Ge.fen"]', '["[will be] like/ a vine","like <the>/ vine"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1154>/H9023', 'opaque', 'heb', 'בֶּסֶר', '["beçer"]', '["unripe grape[s]/ his"]', '["n-m"]', 'an immature grape unripe grape.', 'from an unused root meaning to be sour;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H2132H>', 'inflected', 'heb', 'כזית', '["ka./Za.yit","ke./Za.yit","kha./Za.yit"]', '["[am] like/ an olive tree","like <the>/ olive tree"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5328}/H9023/[H5322]', 'inflected', 'heb', 'נִצָּה', '["nitstsâh"]', '["blossom/ his"]', '["n-f"]', 'a blossom flower.', 'feminine of 5322;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0990H>/H9028', 'inflected', 'heb', 'ובטנם', '["u./vit.Na/m"]', '["and/ belly/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4820}\/[H7411]', 'inflected', 'heb', 'מִרְמָה', '["mirmâh"]', '["deceit"]', '["n-f"]', 'fraud craft, deceit(-ful, -fully), false, feigned, guile, subtilly, treachery.', 'from 7411 in the sense of deceiving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7093}/[H7112]', 'inflected', 'heb', 'קֵץ', '["qêts"]', '["¿/ [does] an end"]', '["n-m"]', 'an extremity; adverbially (with prepositional prefix) after after, (utmost) border, end, (in-) finite, × process.', 'contracted from 7112;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4834}/H9031/[H4834]', 'inflected', 'heb', 'מָרַץ', '["mârats"]', '["is it making sick/ you"]', '["v"]', 'properly, to press, i.e. (figuratively) to be pungent or vehement; to irritate embolden, be forcible, grievous, sore.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5128}/[H5128]', 'inflected', 'heb', 'נוּעַ', '["nûwaʻ"]', '["and/ I will shake","and/ really <wander>","and/ they may trembled"]', '["v"]', 'to waver, in a great variety of applications, literally and figuratively (as subjoined) continually, fugitive, × make, to (go) up and down, be gone away, (be) move(-able, -d), be promoted, reel, remove, scatter, set, shake, sift, stagger, to and fro, be vagabond, wag, (make) wander (up and down).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1119}/[H1119]', 'lemma', 'heb', 'בְּמוֹ', '["bᵉmôw"]', '["in","with"]', '["prep"]', 'in, with, by, etc. for, in into, through.', 'prolongation for prepositional prefix;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0553}/H9036/[H553]', 'inflected', 'heb', 'אָמַץ', '["ʼâmats"]', '["I will strengthen/ you"]', '["v"]', 'to be alert, physically (on foot) or mentally (in courage) confirm, be courageous (of good courage, stedfastly minded, strong, stronger), establish, fortify, harden, increase, prevail, strengthen (self), make strong (obstinate, speed).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5205}/[H5110]', 'inflected', 'heb', 'נִיד', '["nîyd"]', '["and/ [the] condolence of"]', '["n-m"]', 'motion (of the lips in speech) moving.', 'from 5110;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3511}/H9020/[H3510]', 'inflected', 'heb', 'כְּאֵב', '["kᵉʼêb"]', '["pain/ my"]', '["n-m"]', 'suffering (physical or mental), adversity grief, pain, sorrow.', 'from 3510;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3811}/H9030/[H3811]', 'inflected', 'heb', 'לָאָה', '["lâʼâh"]', '["he has made weary/ me"]', '["v"]', 'to tire; (figuratively) to be (or make) disgusted faint, grieve, lothe, (be, make) weary (selves).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8074G}/[H8074]', 'lemma', 'heb', 'שָׁמֵם', '["shâmêm"]', '["I will make desolate [you]","[are] desolate","[the] desolate [places]","[the] desolate [places] of","a desolate [woman]","desolate","desolate [things]","desolated","desolating","it had been desolated","it has been made desolate","it was desolate","it was made desolate","made desolate","they are desolate","they have been desolated","they have been made desolate","they have devastated","to desolate","will you destroy yourself","you have devastated"]', '["v"]', 'to stun (or intransitively, grow numb), i.e. devastate or (figuratively) stupefy (both usually in a passive sense) make amazed, be astonied, (be an) astonish(-ment), (be, bring into, unto, lay, lie, make) desolate(-ion, places), be destitute, destroy (self), (lay, lie, make) waste, wonder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5712}/H9020/[H5707]', 'inflected', 'heb', 'עֵדָה', '["ʻêdâh"]', '["company/ my"]', '["n-f"]', 'a stated assemblage (specifically, a concourse, or generally, a family or crowd) assembly, company, congregation, multitude, people, swarm. Compare 5713.', 'feminine of 5707 in the original sense of fixture;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7059}/H9030/[H7059]', 'inflected', 'heb', 'קָמַט', '["qâmaṭ"]', '["and/ you have seized/ me"]', '["v"]', 'to pluck, i.e. destroy cut down, fill with wrinkles.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3585}/H9020/[H3584]', 'inflected', 'heb', 'כַּחַשׁ', '["kachash"]', '["leanness/ my"]', '["n-m"]', 'literally a failure of flesh, i.e. emaciation; figuratively, hypocrisy leanness, lies, lying.', 'from 3584;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6440H}/H9020/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["in/ face/ my"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7852}/H9030/[H7852]', 'inflected', 'heb', 'שָׂטַם', '["sâṭam"]', '["and/ it has assailed/ me"]', '["v"]', 'properly, to lurk for, i.e. persecute hate, oppose self against.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2786}/[H2786]', 'lemma', 'heb', 'חָרַק', '["châraq"]', '["he has gnashed","he will gnash","they gnashed"]', '["v"]', 'to grate the teeth gnash.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8127G}/H9023/[H8150]', 'inflected', 'heb', 'שֵׁן', '["shên"]', '["with/ teeth/ his"]', '["n-f"]', 'a tooth (as sharp); specifically ivory; figuratively, a cliff crag, × forefront, ivory, × sharp, tooth.', 'from 8150; compare 8143');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6862C}/H9020/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["opponent/ my","opponents/ my"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6473}/[H6473]', 'lemma', 'heb', 'פָּעַר', '["pâʻar"]', '["I opened wide","people have opened wide","they opened wide"]', '["v"]', 'to yawn, i.e. open wide (literally or figuratively) gape, open (wide).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2781}/[H2778]', 'inflected', 'heb', 'חֶרְפָּה', '["cherpâh"]', '["in/ scorn"]', '["n-f"]', 'contumely, disgrace, the pudenda rebuke, reproach(-fully), shame.', 'from 2778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3895H>/H9020', 'opaque', 'heb', 'לְחִי', '["lᵉchîy"]', '["cheeks/ my"]', '["n-m"]', 'the cheek (from its fleshiness); hence, the jaw-bone cheek (bone), jaw (bone).', 'from an unused root meaning to be soft;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4390}/H9013/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["they mass themselves/ !","they will be filled/ !"]', '["v"]', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly.', 'or מָלָא; (Esther 7:5), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5760}/[H5765]', 'lemma', 'heb', 'עֲוִיל', '["ʻăvîyl"]', '["an unjust one"]', '["n-m"]', 'perverse (morally) ungodly.', 'from 5765;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3399B}/H9030/[H3399]', 'inflected', 'heb', 'יָרַט', '["yâraṭ"]', '["he casts/ me"]', '["v"]', 'to precipitate or hurl (rush) headlong; (intransitively) to be rash be perverse, turn over.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7961}/[H7951]', 'lemma', 'heb', 'שָׁלֵו', '["shâlêv"]', '["at ease","quiet"]', '["a"]', 'tranquil; (in a bad sense) careless; abstractly, security (being) at ease, peaceable, (in) prosper(-ity), quiet(-ness), wealthy.', 'or שָׁלֵיו; feminine שְׁלֵוָה; from 7951;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6565A}/H9030/[H6565]', 'inflected', 'heb', 'פָּרַר', '["pârar"]', '["and/ he smashed/ me"]', '["v"]', 'to break up (usually figuratively), i.e. to violate, frustrate × any ways, break (asunder), cast off, cause to cease, × clean, defeat, disannul, disappoint, dissolve, divide, make of none effect, fail, frustrate, bring (come) to nought, × utterly, make void.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6203}/H9020/[H6202]', 'inflected', 'heb', 'עֹרֶף', '["ʻôreph"]', '["on/ neck/ my"]', '["n-m"]', 'the nape or back of the neck (as declining); hence, the back generally (whether literal or figurative) back ((stiff-) neck((-ed).', 'from 6202;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6327D}/H9030/[H6327]', 'inflected', 'heb', 'פּוּץ', '["pûwts"]', '["and/ he shattered/ me"]', '["v"]', 'to dash in pieces, literally or figuratively (especially to disperse) break (dash, shake) in (to) pieces, cast (abroad), disperse (selves), drive, retire, scatter (abroad), spread abroad.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6965I}/H9030/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["and/ he set up/ me"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7228}/H9023/[H7232]', 'inflected', 'heb', 'רַב', '["rab"]', '["archers/ his"]', '["n-m"]', 'an archer archer.', 'by contraction from 7232; (or perhaps the same as 7227)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6398}/[H6398]', 'lemma', 'heb', 'פָּלַח', '["pâlach"]', '["[one who] plows","he splits open","it will pierce","they cleave open"]', '["v"]', 'to slice, i.e. break open or pierce bring forth, cleave, cut, shred, strike through.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3629}/H9020/[H3627]', 'inflected', 'heb', 'כִּלְיָה', '["kilyâh"]', '["kidneys/ my"]', '["n-f"]', 'a kidney (as an essential organ); figuratively, the mind (as the interior self) kidneys, reins.', 'feminine of 3627 (only in the plural);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4845}/H9020/[H4843]', 'inflected', 'heb', 'מְרֵרָה', '["mᵉrêrâh"]', '["gall/ my"]', '["n-f"]', 'bile (from its bitterness) gall.', 'from 4843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6555}/H9030/[H6555]', 'inflected', 'heb', 'פָּרַץ', '["pârats"]', '["he breaks through/ me"]', '["v"]', 'to break out (in many applications, direct and indirect, literal and figurative) × abroad, (make a) breach, break (away, down, -er, forth, in, up), burst out, come (spread) abroad, compel, disperse, grow, increase, open, press, scatter, urge.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1368}/[H1397]', 'inflected', 'heb', 'גִּבּוֹר', '["gibbôwr"]', '["[will be] like/ a warrior","like <the>/ warrior","like/ a mighty [man]","like/ a warrior","like/ warriors"]', '["a"]', 'powerful; by implication, warrior, tyrant champion, chief, × excel, giant, man, mighty (man, one), strong (man), valiant man.', 'or גִּבֹּר; (shortened) intensive from the same as 1397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8609}/[H8609]', 'lemma', 'heb', 'תָּפַר', '["tâphar"]', '["I have sewed"]', '["v"]', 'to sew (women that) sew (together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1539>/H9020', 'opaque', 'heb', 'גֶּלֶד', '["geled"]', '["skin/ my"]', '["n-m"]', 'the (human) skin (as smooth) skin.', 'from an unused root probably meaning to polish;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5953D}/[H5953]', 'inflected', 'heb', 'עָלַל', '["ʻâlal"]', '["and/ I have inserted"]', '["v"]', 'to effect thoroughly; specifically, to glean (also figuratively); by implication (in a bad sense) to overdo, i.e. maltreat, be saucy to, pain, impose (also literal) abuse, affect, × child, defile, do, glean, mock, practise, thoroughly, work (wonderfully).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2560C}/[H2564]', 'lemma', 'heb', 'חָמַר', '["châmar"]', '["they are reddened"]', '["v"]', 'properly, to boil up; hence, to ferment (with scum); to glow (with redness); to smear with pitch daub, befoul, be red, trouble.', 'a primitive root; also as denominative (from 2564)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6079}/H9020/[H5774]', 'inflected', 'heb', 'עַפְעַף', '["ʻaphʻaph"]', '["eyelids/ my"]', '["n-m"]', 'an eyelash (as fluttering); figuratively, morning ray dawning, eye-lid.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8605}/H9020/[H6419]', 'inflected', 'heb', 'תְּפִלָּה', '["tᵉphillâh"]', '["and/ prayer/ my"]', '["n-f"]', 'intercession, supplication; by implication, a hymn prayer.', 'from 6419;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2201}/H9020/[H2199]', 'inflected', 'heb', 'זַעַק', '["zaʻaq"]', '["to/ outcry/ my"]', '["n-f"]', 'a shriek or outcry cry(-ing).', 'and (feminine) זְעָקָהxlit zᵉâqâh corrected to zᵉʻâqâh; from 2199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5707}/H9020/[H5749]', 'inflected', 'heb', 'עֵד', '["ʻêd"]', '["[are] witnesses/ my","witness/ my"]', '["n-m"]', 'concretely, a witness; abstractly, testimony; specifically, a recorder, i.e. prince witness.', 'contracted from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7717>/H9020', 'inflected', 'heb', 'ושהדי', '["ve./sa.ha.D/i"]', '["and/ witness/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4791}/[H7311]', 'inflected', 'heb', 'מָרוֹם', '["mârôwm"]', '["[is] in <the>/ high places","in <the>/ high places","in the/ height[s]","in the/ heights","on the/ height","on the/ high places","on/ [the] height of"]', '["n-m"]', 'altitude, i.e. concretely (an elevated place), abstractly (elevation, figuratively (elation), or adverbially (aloft) (far) above, dignity, haughty, height, (most, on) high (one, place), loftily, upward.', 'from 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3887}/H9030/[H3887]', 'inflected', 'heb', 'לוּץ', '["lûwts"]', '["[are] scoffing at/ me","they have mocked/ me"]', '["v"]', 'properly, to make mouths at, i.e. to scoff; hence (from the effort to pronounce a foreign language) to interpret, or (generally) intercede ambassador, have in derision, interpreter, make a mock, mocker, scorn(-er, -ful), teacher.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7453}/H9020/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["[is] friend/ my","companions/ my","friends/ my","neighbor/ my"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1811}/[H1811]', 'lemma', 'heb', 'דָּלַף', '["dâlaph"]', '["it has wept","it leaks","it weeps"]', '["v"]', 'to drip; by implication, to weep drop through, melt, pour out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0857}/[H225]', 'lemma', 'heb', 'אָתָה', '["ʼâthâh"]', '["bring","bring [them]","come","it comes","it will arrive","it will come","they come","they will come","we have come"]', '["v"]', 'to arrive (be-, things to) come (upon), bring.', 'or אָתָא; a primitive root (collateral to 225 contraction);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0734}/[H732]', 'inflected', 'heb', 'אֹרַח', '["ʼôrach"]', '["and/ [the] path of","and/ [the] paths of","and/ a way"]', '["n-m"]', 'a well-trodden road (literally or figuratively); also a caravan manner, path, race, rank, traveller, troop, (by-, high-) way.', 'from 732;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2193}/[H2193]', 'lemma', 'heb', 'זָעַךְ', '["zâʻak"]', '["they are extinguished"]', '["v"]', 'to extinguish be extinct.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2049}/[H2048]', 'lemma', 'heb', 'הָתֹל', '["hâthôl"]', '["mockeries"]', '["n-m"]', 'a derision mocker.', 'from 2048 (only in plural collectively);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4784}/H9048/[H4784]', 'inflected', 'heb', 'מָרָה', '["mârâh"]', '["and/ on/ rebelling/ they"]', '["v"]', 'to be (causatively, make) bitter (or unpleasant); (figuratively) to rebel (or resist; causatively, to provoke) bitter, change, be disobedient, disobey, grievously, provocation, provoke(-ing), (be) rebel (against, -lious).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7760H}/H9012/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["make/ !","put/ !"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6148}/H9030/[H6148]', 'inflected', 'heb', 'עָרַב', '["ʻârab"]', '["stand surety for/ me"]', '["v"]', 'to braid, i.e. intermix; technically, to traffic (as if by barter); also or give to be security (as a kind of exchange) engage, (inter-) meddle (with), mingle (self), mortgage, occupy, give pledges, be(-come, put in) surety, undertake.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3027I}/H9020/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["to/ hand/ my"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7922}/[H7919]', 'inflected', 'heb', 'שֶׂכֶל', '["sekel"]', '["from/ understanding"]', '["n-m"]', 'intelligence; by implication, success discretion, knowledge, policy, prudence, sense, understanding, wisdom, wise.', 'or שֵׂכֶל; from 7919;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2506A}/[H2505]', 'inflected', 'heb', 'חֵלֶק', '["chêleq"]', '["for/ a share"]', '["n-m"]', 'properly, smoothness (of the tongue); also an allotment flattery, inheritance, part, × partake, portion.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3322}/H9030/[H3322]', 'inflected', 'heb', 'יָצַג', '["yâtsag"]', '["and/ he has set/ me"]', '["v"]', 'to place permanently establish, leave, make, present, put, set, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4914}/[H4911]', 'inflected', 'heb', 'מְשֹׁל', '["mᵉshôl"]', '["to/ use a proverb"]', '["n-m"]', 'a satire byword.', 'from 4911;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8611}/[H8608]', 'inflected', 'heb', 'תֹּפֶת', '["tôpheth"]', '["and/ a spitting"]', '["n-f"]', 'a smiting, i.e. (figuratively) contempt tabret.', 'from the base of 8608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3708B}/[H3707]', 'inflected', 'heb', 'כַּעַס', '["kaʻaç"]', '["from/ grief"]', '["n-m"]', 'vexation anger, angry, grief, indignation, provocation, provoking, × sore, sorrow, spite, wrath.', 'or (in Job) כַּעַשׂ; from 3707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3338}/H9020/[H3335]', 'inflected', 'heb', 'יָצֻר', '["yâtsur"]', '["and/ members/ my"]', '["n-m"]', 'structure, i.e. limb or part member.ql', 'passive participle of 3335;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0555}/[H553]', 'lemma', 'heb', 'אֹמֶץ', '["ʼômets"]', '["strength"]', '["n-m"]', 'strength stronger.', 'from 553;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2154}/H9020/[H2161]', 'inflected', 'heb', 'זִמָּה', '["zimmâh"]', '["plans/ my"]', '["n-f"]', 'a plan, especially a bad one heinous crime, lewd(-ly, -ness), mischief, purpose, thought, wicked (device, mind, -ness).', 'or זַמָּה; from 2161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4180}/[H3423]', 'lemma', 'heb', 'מוֹרָשׁ', '["môwrâsh"]', '["[the] wishes of"]', '["n-m"]', 'a possession; figuratively, delight possession, thought.', 'from 3423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7502}/[H7502]', 'lemma', 'heb', 'רָפַד', '["râphad"]', '["I have spread out","it spreads out"]', '["v"]', 'to spread (a bed); by implication, to refresh comfort, make (a bed), spread.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7845H}/[H7743]', 'inflected', 'heb', 'שַׁחַת', '["shachath"]', '["to the/ pit"]', '["n-f"]', 'a pit (especially as a trap); figuratively, destruction corruption, destruction, ditch, grave, pit.', 'from 7743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0269}/H9020/[H251]', 'inflected', 'heb', 'אָחוֹת', '["ʼâchôwth"]', '["and/ sister/ my"]', '["n-f"]', 'a sister (used very widely [like 251number 250, corrected to 251], literally and figuratively) (an-) other, sister, together.', 'irregular feminine of 251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7415}/[H7426]', 'inflected', 'heb', 'רִמָּה', '["rimmâh"]', '["to the/ maggot"]', '["n-f"]', 'a maggot (as rapidly bred), literally or figuratively worm.', 'from 7426 in the sense of breeding (compare 7311);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8615B}/H9020/[H6960]', 'inflected', 'heb', 'תִּקְוָה', '["tiqvâh"]', '["[are] hope/ my","[is] hope/ my","hope/ my"]', '["n-f"]', 'literally a cord (as an attachment); figuratively, expectancy expectation(-ted), hope, live, thing that I long for.', 'from 6960; (compare 6961)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7789}/H9034/[H7789]', 'inflected', 'heb', 'שׁוּר', '["shûwr"]', '["anyone perceives/ it","he observes/ it","will he observe/ it"]', '["v"]', 'to spy out, i.e. (generally) survey, (for evil) lurk for, (for good) care for behold, lay wait, look, observe, perceive, regard, see.', 'a primitive root (identical with through the idea of going round for inspection);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5181}\/[H5181]', 'inflected', 'heb', 'נָחַת', '["nâchath"]', '["will we descend"]', '["v"]', 'to sink, i.e. descend; causatively, to press or lead down be broken, (cause to) come down, enter, go down, press sore, settle, stick fast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7760A}/H9013/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["will you make/ !","you will set/ !"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7078>', 'opaque', 'heb', 'קֶנֶץ', '["qenets"]', '["ends"]', '["n-m"]', 'perversion end.', 'from an unused root probably meaning to wrench;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4405}/[H4448]', 'inflected', 'heb', 'מִלָּה', '["millâh"]', '["<into>/ a word","of/ words"]', '["n-f"]', 'a word; collectively, a discourse; figuratively, a topic answer, by-word, matter, any thing (what) to say, to speak(-ing), speak, talking, word.', 'from 4448 (plural masculine as if from מִלֶּה;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H0929>', 'inflected', 'heb', 'כבהמות', '["ka./be.he.Mah","ka./be.he.Mot","kha./be.he.Mah"]', '["like <the>/ cattle","like <the>/ livestock","like the/ animals"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2933}/[H2930]', 'lemma', 'heb', 'טָמָה', '["ṭâmâh"]', '["are we considered stupid?"]', '["v"]', 'to be impure in a religious sense be defiled, be reputed vile.', 'a collateral form of 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869H}/H9026/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ view/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H4616}/H9031/[H6030]', 'inflected', 'heb', 'מַעַן', '["maʻan"]', '["¿/ for sake/ your"]', '["prt"]', 'properly, heed, i.e. purpose; used only adverbially, on account of (as a motive or an aim), teleologically, in order that because of, to the end (intent) that, for (to,... ''s sake), lest, that, to.', 'from 6030;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6275}/[H6275]', 'inflected', 'heb', 'עָתַק', '["ʻâthaq"]', '["so/ it may move?"]', '["v"]', 'to remove (intransitive or transitive) figuratively, to grow old; specifically, to transcribe copy out, leave off, become (wax) old, remove.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7632}/[H7616]', 'lemma', 'heb', 'שָׁבִיב', '["shâbîyb"]', '["[the] flame of"]', '["n-m"]', 'flame (as split into tongues) spark.', 'from the same as 7616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5216A}/H9023/[H5214]', 'inflected', 'heb', 'נִיר', '["nîyr"]', '["and/ lamp/ his"]', '["n-m"]', 'a lamp (i.e. the burner) or light (literally or figuratively) candle, lamp, light.', 'or נִר; also נֵיר; or נֵר; or (feminine) נֵרָה; from a primitive root (see 5214; 5135) properly, meaning to glisten;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3334}/[H3334]', 'lemma', 'heb', 'יָצַר', '["yâtsar"]', '["anyone will hinder","it will be distress","they are restricted","you will be [too] cramped"]', '["v"]', 'to press (intransitive), i.e. be narrow; figuratively, be in distress be distressed, be narrow, be straitened (in straits), be vexed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7568}/[H3423]', 'inflected', 'heb', 'רֶשֶׁת', '["resheth"]', '["in/ [the] net","in/ a net"]', '["n-f"]', 'a net (as catching animals) net(-work).', 'from 3423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6341A}/[H6351]', 'lemma', 'heb', 'פַּח', '["pach"]', '["<the> bird-trap of","[the] trap","a bird-trap","a snare","a trap","a trap of","snares"]', '["n-m"]', 'a (metallic) sheet (as pounded thin); also a spring net (as spread out like a lamina) gin, (thin) plate, snare.', 'from 6351;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2256M}/H9023/[H2254]', 'inflected', 'heb', 'חֶבֶל', '["chebel"]', '["rope/ his","ropes/ its"]', '["n-m"]', 'a rope (as twisted), especially a measuring line; by implication, a district or inheritance (as measured); or a noose (as of cords); figuratively, a company (as if tied together); a throe (especially of parturition); also ruin band, coast, company, cord, country, destruction, line, lot, pain, pang, portion, region, rope, snare, sorrow, tackling.', 'or חֵבֶל; from 2254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4434}/H9023/[H3920]', 'inflected', 'heb', 'מַלְכֹּדֶת', '["malkôdeth"]', '["and/ trap/ his"]', '["n-f"]', 'a snare trap.', 'from 3920;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5410A>', 'opaque', 'heb', 'נָתִיב', '["nâthîyb"]', '["[the] path","a path","a pathway"]', '["n-m"]', 'a (beaten) track path(-way), × travel(-ler), way.', 'or (feminine) נְתִיבָה; or נְתִבָה; (Jeremiah 6:16), from an unused root meaning to tramp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1091}/[H1089]', 'lemma', 'heb', 'בַּלָּהָה', '["ballâhâh"]', '["[the] terrors of","sudden terror","sudden terror<s>","terrors"]', '["n-f"]', 'alarm; hence, destruction terror, trouble.', 'from 1089;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6327A}/H9033/[H6327]', 'inflected', 'heb', 'פּוּץ', '["pûwts"]', '["and/ they scatter/ him"]', '["v"]', 'to dash in pieces, literally or figuratively (especially to disperse) break (dash, shake) in (to) pieces, cast (abroad), disperse (selves), drive, retire, scatter (abroad), spread abroad.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0343}/[H181]', 'inflected', 'heb', 'אֵיד', '["ʼêyd"]', '["and/ disaster"]', '["n-m"]', 'oppression; by implication misfortune, ruin calamity, destruction.', 'from the same as 181 (in the sense of bending down);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6761}/H9023/[H6760]', 'inflected', 'heb', 'צֶלַע', '["tselaʻ"]', '["for/ stumbling/ his"]', '["n-m"]', 'a limping or full (figuratively) adversity, halt(-ing).', 'from 6760;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0168G}/H9023/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["from/ tent/ his"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6805}/H9033/[H6805]', 'inflected', 'heb', 'צָעַד', '["tsâʻad"]', '["and/ it makes march/ him"]', '["v"]', 'to pace, i.e. step regularly; (upward) to mount; (along) to march; (down and causatively) to hurl bring, go, march (through), run over.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4605}/[H5927]', 'inflected', 'heb', 'מַעַל', '["maʻal"]', '["and/ <from>/ above","and/ [was] from/ above"]', '["adv"]', 'properly,the upper part, used only adverbially with prefix upward, above, overhead, from the top, etc. above, exceeding(-ly), forward, on (× very) high, over, up(-on, -ward), very.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5243A}/[H5243]', 'lemma', 'heb', 'נָמַל', '["nâmal"]', '["it withers","they will wither","they wither"]', '["v"]', 'to become clipped or (specifically) circumcised (branch to) be cut down (off), circumcise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7105B}/H9023/[H7114]', 'inflected', 'heb', 'קָצִיר', '["qâtsîyr"]', '["branch[es]/ his"]', '["n-m"]', 'severed, i.e. harvest (as reaped), the crop, the time, the reaper, or figuratively; also a limb (of a tree, or simply foliage) bough, branch, harvest (man).', 'from 7114;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2143}/H9023/[H2142]', 'inflected', 'heb', 'זֵכֶר', '["zêker"]', '["[is] memorial/ his","memorial/ its","memory/ his"]', '["n-m"]', 'a memento, abstractly recollection (rarely if ever); by implication, commemoration memorial, memory, remembrance, scent.', 'or זֶכֶר; from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0216}/[H215]', 'inflected', 'heb', 'אוֹר', '["ʼôwr"]', '["from/ light"]', '["n-f"]', 'illumination or (concrete) luminary (in every sense, including lightning, happiness, etc.) bright, clear, day, light (-ning), morning, sun.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H8398}/[H2986]', 'inflected', 'heb', 'תֵּבֵל', '["têbêl"]', '["and/ from/ [the] world"]', '["n-f"]', 'the earth (as moist and therefore inhabited); by extension, the globe; by implication, its inhabitants; specifically, a particular land, as Babylonia, Palestine habitable part, world.', 'from 2986;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5074}/H9033/[H5074]', 'inflected', 'heb', 'נָדַד', '["nâdad"]', '["they chase away/ him"]', '["v"]', 'properly, to wave to and fro (rarely to flap up and down); figuratively, to rove, flee, or (causatively) to drive away chase (away), × could not, depart, flee (× apace, away), (re-) move, thrust away, wander (abroad, -er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5209}/[H5125]', 'lemma', 'heb', 'נִין', '["nîyn"]', '["posterity"]', '["n-m"]', 'progeny son.', 'from 5125;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5220>', 'opaque', 'heb', 'נֶכֶד', '["neked"]', '["progeny"]', '["n-m"]', 'offspring nephew, son''s son.', 'from an unused root meaning to propagate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4033}/H9023/[H1481]', 'inflected', 'heb', 'מָגוּר', '["mâgûwr"]', '["in/ sojourning-places/ his"]', '["n-m"]', 'a temporary abode; by extension, a permanent residence dwelling, pilgrimage, where sojourn, be a stranger. Compare 4032.', 'or מָגֻר; from 1481 in the sense of lodging;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117L>/H9023', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["day/ his"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6931G}/[H6930]', 'inflected', 'heb', 'קַדְמוֹנִי', '["qadmôwnîy"]', '["and/ [those] before"]', '["a"]', '(of time) anterior or (of place) oriental ancient, they that went before, east, (thing of) old.', 'or קַדְמֹנִי; from 6930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8178A}/[H8175]', 'lemma', 'heb', 'שַׂעַר', '["saʻar"]', '["a shudder","shuddering"]', '["n-m"]', 'a terror affrighted, × horribly, × sore, storm. See 8181.', 'from 8175;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5767}/[H5765]', 'lemma', 'heb', 'עַוָּל', '["ʻavvâl"]', '["[the] unrighteous","an evil-doer","an unrighteous person"]', '["n-m"]', 'evil (morally) unjust, unrighteous, wicked.', 'intensive from 5765;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0410G}\/[H352]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["God"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3013}/H9013/[H3013]', 'inflected', 'heb', 'יָגָה', '["yâgâh"]', '["will you torment/ !"]', '["v"]', 'to grieve afflict, cause grief, grieve, sorrowful, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3637}/H9030/[H3637]', 'inflected', 'heb', 'כָּלַם', '["kâlam"]', '["you have insulted/ me"]', '["v"]', 'properly, to wound; but only figuratively, to taunt or insult be (make) ashamed, blush, be confounded, be put to confusion, hurt, reproach, (do, put to) shame.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1970}/[H1970]', 'lemma', 'heb', 'הָכַר', '["hâkar"]', '["you have ill-treated"]', '["v"]', 'to injure make self strange.', 'a primitive root; apparently');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4879>/H9020', 'opaque', 'heb', 'מְשׁוּגָה', '["mᵉshûwgâh"]', '["error/ my"]', '["n-f"]', 'mistake error.', 'from an unused root meaning to stray;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5791}/H9030/[H5791]', 'inflected', 'heb', 'עָוַת', '["ʻâvath"]', '["he has wronged/ me","they have subverted/ me"]', '["v"]', 'to wrest bow self, (make) crooked., falsifying, overthrow, deal perversely, pervert, subvert, turn upside down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4685B}/H9023/[H6679]', 'inflected', 'heb', 'מָצוֹד', '["mâtsôwd"]', '["and/ net/ his"]', '["n-m"]', 'a net (for capturing animals or fishes); a fastness or (beseiging) tower bulwark, hold, munition, net, snare.', 'or (feminine) מְצוֹדָה; or מצֹדָה; from 6679; also (by interchange for 4679)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7768}/[H7768]', 'lemma', 'heb', 'שָׁוַע', '["shâvaʻ"]', '["I cried for help","I cry for help","I cry out for help","[who] cried for help","[who] cries for help","have I cried for help","it cries for help","they cried for help","they cry for help","they will cry for help","you will cry for help"]', '["v"]', 'properly, to be free; but used only causatively and reflexively, to halloo (for help, i.e. freedom from some trouble) cry (aloud, out), shout.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1443}/[H1443]', 'lemma', 'heb', 'גָּדַר', '["gâdar"]', '["[one who] walls up","[who will] build","he has walled up"]', '["v"]', 'to wall in or around close up, fence up, hedge, inclose, make up (a wall), mason, repairer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5410B>/H9020', 'opaque', 'heb', 'נָתִיב', '["nâthîyb"]', '["paths/ my","pathway/ my"]', '["n-m"]', 'a (beaten) track path(-way), × travel(-ler), way.', 'or (feminine) נְתִיבָה; or נְתִבָה; (Jeremiah 6:16), from an unused root meaning to tramp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5422}/H9030/[H5422]', 'inflected', 'heb', 'נָתַץ', '["nâthats"]', '["he has torn down/ me"]', '["v"]', 'to tear down beat down, break down (out), cast down, destroy, overthrow, pull down, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6086H}/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["like <the>/ a tree","like <the>/ tree","like/ a tree"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2803J}/H9030/[H2803]', 'inflected', 'heb', 'חָשַׁב', '["châshab"]', '["and/ he has considered/ me"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6862C}/H9023/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["like/ foes/ his"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1416}/H9023/[H1413]', 'inflected', 'heb', 'גְּדוּד', '["gᵉdûwd"]', '["troops/ his"]', '["n-m"]', 'a crowd (especially of soldiers) army, band (of men), company, troop (of robbers).', 'from 1413;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5549}/[H5549]', 'inflected', 'heb', 'סָלַל', '["çâlal"]', '["and/ they have piled up"]', '["v"]', 'to mound up (especially a turnpike); figurative, to exalt; reflexively, to oppose (as by a dam) cast up, exalt (self), extol, make plain, raise up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870K}/H9028/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["way/ their"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0168G}/H9020/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["<to>/ tent/ my"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3045}/H9030/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["and/ acquaintances/ my","and/ make known to/ me"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7138}/H9020/[H7126]', 'inflected', 'heb', 'קָרוֹב', '["qârôwb"]', '["kindred/ my"]', '["a"]', 'near (in place, kindred or time) allied, approach, at hand, any of kin, kinsfold(-sman), (that is) near (of kin), neighbour, (that is) next, (them that come) nigh (at hand), more ready, short(-ly).', 'or קָרֹב; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3045}/H9020/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["and/ acquaintance/ my","and/ acquaintances/ my"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7911}/H9030/[H7911]', 'inflected', 'heb', 'שָׁכַח', '["shâkach"]', '["have you forgotten/ me","he has forgotten/ me","they forgot/ me","they have forgotten/ me","will you forget/ me"]', '["v"]', 'to mislay, i.e. to be oblivious of, from want of memory or attention × at all, (cause to) forget.', 'or שָׁכֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0519}/H9020/[H519]', 'inflected', 'heb', 'אָמָה', '["ʼâmâh"]', '["and/ female servant/ my","and/ female servants/ my"]', '["n-f"]', 'a maid-servant or female slave (hand-) bondmaid(-woman), maid(-servant).', 'apparently a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2114A}/[H2114]', 'inflected', 'heb', 'זוּר', '["zûwr"]', '["for the/ stranger","to <the>/ strangers","to/ a stranger","to/ strangers"]', '["v"]', 'to turn aside (especially for lodging); hence to be a foreigner, strange, profane; specifically (active participle) to commit adultery (come from) another (man, place), fanner, go away, (e-) strange(-r, thing, woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2803J}/H9030/[H2803]', 'inflected', 'heb', 'חָשַׁב', '["châshab"]', '["he considers/ me","they consider/ me"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2114B}/[H2114]', 'lemma', 'heb', 'זוּר', '["zûwr"]', '["it is loathsome"]', '["v"]', 'to turn aside (especially for lodging); hence to be a foreigner, strange, profane; specifically (active participle) to commit adultery (come from) another (man, place), fanner, go away, (e-) strange(-r, thing, woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2603B}/[H2583]', 'inflected', 'heb', 'חָנַן', '["chânan"]', '["and/ I am repulsive"]', '["v"]', 'properly, to bend or stoop in kindness to an inferior; to favor, bestow; causatively to implore (i.e. move to favor by petition) beseech, × fair, (be, find, shew) favour(-able), be (deal, give, grant (gracious(-ly), intreat, (be) merciful, have (shew) mercy (on, upon), have pity upon, pray, make supplication, × very.', 'a primitive root (compare 2583);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5759}/[H5764]', 'lemma', 'heb', 'עֲוִיל', '["ʻăvîyl"]', '["young boys"]', '["n-m"]', 'a babe young child, little one.', 'from 5764;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8581}/H9030/[H8581]', 'inflected', 'heb', 'תַּעָב', '["taʻâb"]', '["they abhor/ me"]', '["v"]', 'to loathe, i.e. (morally) detest (make to be) abhor(-red), (be, commit more, do) abominable(-y), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5475}/H9020/[H3245]', 'inflected', 'heb', 'סוֹד', '["çôwd"]', '["council/ my"]', '["n-m"]', 'a session, i.e. company of persons (in close deliberation); by implication, intimacy, consultation, a secret assembly, consel, inward, secret (counsel).', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5785}/H9020/[H5783]', 'inflected', 'heb', 'עוֹר', '["ʻôwr"]', '["on/ skin/ my"]', '["n-m"]', 'skin (as naked); by implication, hide, leather hide, leather, skin.', 'from 5783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1320}/H9020/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["and/ on/ flesh/ my"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8127G}/H9020/[H8150]', 'inflected', 'heb', 'שֵׁן', '["shên"]', '["teeth/ my"]', '["n-f"]', 'a tooth (as sharp); specifically ivory; figuratively, a cliff crag, × forefront, ivory, × sharp, tooth.', 'from 8150; compare 8143');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7291}/H9030/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["[those who] harass/ me","are you persecuting/ me","persecutors/ my","pursuers/ my","they have harassed/ me","they will pursue/ me"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1320}/H9020/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["and/ from/ flesh/ my"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3789}/H9013/[H3789]', 'inflected', 'heb', 'כָּתַב', '["kâthab"]', '["and/ they will be written down/ !"]', '["v"]', 'to grave, by implication, to write (describe, inscribe, prescribe, subscribe) describe, record, prescribe, subscribe, write(-ing, -ten).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5842}/[H5860]', 'inflected', 'heb', 'עֵט', '["ʻêṭ"]', '["with/ a stylus of"]', '["n-m"]', 'a stylus or marking stick pen.', 'from 5860 (contracted) in the sense of swooping, i.e. side-long stroke;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5777}/[H6080]', 'inflected', 'heb', 'עוֹפֶרֶת', '["ʻôwphereth"]', '["and/ lead"]', '["n-m"]', 'lead (from its dusty color) lead.', 'or עֹפֶרֶת; feminine participle active of 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2672}/H9013/[H2672]', 'inflected', 'heb', 'חָצַב', '["châtsab"]', '["they will be engraved/ !"]', '["v"]', 'to cut or carve (wood, stone or other material); by implication, to hew, split, square, quarry, engrave cut, dig, divide, grave, hew (out, -er), made, mason.', 'or חָצֵב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1350A}/H9020/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["vindicator/ my"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0314}/[H309]', 'inflected', 'heb', 'אַחֲרוֹן', '["ʼachărôwn"]', '["and/ last"]', '["a"]', 'hinder; generally, late or last; specifically (as facing the east) western after (-ward), to come, following, hind(-er, -ermost, -most), last, latter, rereward, ut(ter) most.', 'or (shortened) אַחֲרֹן; from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5362A}/[H5362]', 'lemma', 'heb', 'נָקַף', '["nâqaph"]', '["people have struck off"]', '["v"]', 'to strike with more or less violence (beat, fell, corrode); by implication (of attack) to knock together, i.e. surround or circulate compass (about, -ing), cut down, destroy, go round (about), inclose, round.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8328}/[H8327]', 'inflected', 'heb', 'שֶׁרֶשׁ', '["sheresh"]', '["and/ [the] root of","and/ [the] roots of"]', '["n-m"]', 'a root (literally or figuratively) bottom, deep, heel, root.', 'from 8327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H1779}\/[H1777]', 'inflected', 'heb', 'דִּין', '["dîyn"]', '["that/ a judgment"]', '["n-m"]', 'judgement (the suit, justice, sentence or tribunal); by implication also strife cause, judgement, plea, strife.', 'or (Job 19:29) דּוּן; from 1777;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5587B}/H9020/[H5586]', 'inflected', 'heb', 'סָעִף', '["çâʻiph"]', '["disquieting thoughts/ my"]', '["n-f"]', 'divided (in mind), i.e. (abstractly) a sentiment opinion.', 'or שָׂעִף; from 5586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725M}/H9030/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["respond to/ me","they make respond/ me"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2363A}/H9040/[H2363]', 'inflected', 'heb', 'חוּשׁ', '["chûwsh"]', '["to agitate/ I"]', '["v"]', 'to hurry; figuratively, to be eager with excitement or enjoyment (make) haste(-n), ready.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3639}/H9020/[H3637]', 'inflected', 'heb', 'כְּלִמָּה', '["kᵉlimmâh"]', '["ignominy/ my","insult/ my"]', '["n-f"]', 'disgrace confusion, dishonour, reproach, shame.', 'from 3637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0998}/H9020/[H995]', 'inflected', 'heb', 'בִּינָה', '["bîynâh"]', '["from/ understanding/ my"]', '["n-f"]', 'understanding knowledge, meaning, × perfectly, understanding, wisdom.', 'from 995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5703}/[H5710]', 'lemma', 'heb', 'עַד', '["ʻad"]', '["antiquity","perpetuity","until"]', '["n-m"]', 'properly, a (peremptory) terminus, i.e. (by implication) duration, in the sense of advance or perpetuity (substantially as a noun, either with or without a preposition) eternity, ever(-lasting, -more), old, perpetually, world without end.', 'from 5710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7863}/H9023/[H7721]', 'inflected', 'heb', 'שִׂיא', '["sîyʼ"]', '["loftiness/ his"]', '["n-m"]', 'elevation excellency.', 'from the same as 7721 by permutation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5645}/[H5743]', 'inflected', 'heb', 'עָב', '["ʻâb"]', '["to the/ cloud[s]"]', '["n-m"]', 'properly, an envelope, i.e. darkness (or density, 2 Chronicles 4:17); specifically, a (scud) cloud; also a copse clay, (thick) cloud, × thick, thicket. Compare 5672.', '(masculine and feminine); from 5743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1561}/H9023/[H1557]', 'inflected', 'heb', 'גֵּלֶל', '["gêlel"]', '["like/ own dung/ his"]', '["n-m"]', 'dung (plural balls of dung) dung.', 'a variation of 1557;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2472}/[H2492]', 'inflected', 'heb', 'חֲלוֹם', '["chălôwm"]', '["like/ a dream"]', '["n-m"]', 'a dream dream(-er).', 'or (shortened) חֲלֹם; from 2492;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5074}/[H5074]', 'inflected', 'heb', 'נָדַד', '["nâdad"]', '["and/ he may be chased away"]', '["v"]', 'properly, to wave to and fro (rarely to flap up and down); figuratively, to rove, flee, or (causatively) to drive away chase (away), × could not, depart, flee (× apace, away), (re-) move, thrust away, wander (abroad, -er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2384}/[H2372]', 'inflected', 'heb', 'חִזָּיוֹן', '["chizzâyôwn"]', '["like/ a vision of"]', '["n-m"]', 'a revelation, expectation by dream vision.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7805}/H9033/[H7805]', 'inflected', 'heb', 'שָׁזַף', '["shâzaph"]', '["it catches sight of/ it","it caught sight of/ him"]', '["v"]', 'to tan (by sunburning); figuratively (as if by a piercing ray) to scan look up, see.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5934}/H9023/[H5956]', 'inflected', 'heb', 'עָלוּם', '["ʻâlûwm"]', '["youth<s>/ his","youthful vigor<s>/ his"]', '["n-m"]', '(only in plural as abstract) adolescence; figuratively, vigor youth.', 'passive participle of 5956 in the denominative sense of 5958;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4985}/[H4985]', 'lemma', 'heb', 'מָתַק', '["mâthaq"]', '["it is sweet","they are sweet","they will be sweet","we made sweet"]', '["v"]', 'to suck, by implication, to relish, or (intransitively) be sweet be (made, × take) sweet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3582}/H9034/[H3582]', 'inflected', 'heb', 'כָּחַד', '["kâchad"]', '["he hides/ it"]', '["v"]', 'to secrete, by act or word; hence (intensively) to destroy conceal, cut down (off), desolate, hide.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5800C}/H9034/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["he lets loose/ it"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4513}/H9034/[H4513]', 'inflected', 'heb', 'מָנַע', '["mânaʻ"]', '["and/ he withholds/ it"]', '["v"]', 'to debar (negatively or positively) from benefit or injury deny, keep (back), refrain, restrain, withhold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2441}/H9023/[H2596]', 'inflected', 'heb', 'חֵךְ', '["chêk"]', '["mouth/ his","palate/ its"]', '["n-m"]', 'properly, the palate or inside of the mouth; hence, the mouth itself (as the organ of speech, taste and kissing) (roof of the) mouth, taste.', 'probably from 2596 in the sense of tasting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6958}/H9033/[H6958]', 'inflected', 'heb', 'קוֹא', '["qôwʼ"]', '["and/ he has vomited up/ it","and/ you will vomit up/ it"]', '["v"]', 'to vomit spue (out), vomit (out, up, up again).', 'or קָיָה; (Jeremiah 25:27), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0660}/[H659]', 'lemma', 'heb', 'אֶפְעֶה', '["ʼephʻeh"]', '["a snake","a viper","viper"]', '["n-m"]', 'an asp or other venomous serpent viper.', 'from 659 (in the sense of hissing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6390}/[H6385]', 'inflected', 'heb', 'פְּלַגָּה', '["pᵉlaggâh"]', '["on/ streams"]', '["n-f"]', 'a runlet, i.e. gully division, river.', 'from 6385;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3022}/[H3021]', 'lemma', 'heb', 'יָגָע', '["yâgâʻ"]', '["[the] gain"]', '["n-m"]', 'earnings (as the product of toil) that which he laboured for.', 'from 3021;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2428H}/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["according to/ [the] wealth of"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5965}/[H5965]', 'lemma', 'heb', 'עָלַס', '["ʻâlaç"]', '["he will rejoice","it flaps joyously","let us delight ourselves"]', '["v"]', 'to leap for joy, i.e. exult, wave joyously × peacock, rejoice, solace self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2530A}/H9023/[H2530]', 'inflected', 'heb', 'חָמַד', '["châmad"]', '["among/ desired [things]/ his"]', '["v"]', 'to delight in beauty, greatly beloved, covet, delectable thing, (× great) delight, desire, goodly, lust, (be) pleasant (thing), precious (thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0398}/H9043/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["to/ devour/ he"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2342B}/[H2342]', 'lemma', 'heb', 'חוּל', '["chûwl"]', '["it will endure","they endure"]', '["v"]', 'properly, to twist or whirl (in a circular or spiral manner), i.e. (specifically) to dance, to writhe in pain (especially of parturition) or fear; figuratively, to wait, to pervert bear, (make to) bring forth, (make to) calve, dance, drive away, fall grievously (with pain), fear, form, great, grieve, (be) grievous, hope, look, make, be in pain, be much (sore) pained, rest, shake, shapen, (be) sorrow(-ful), stay, tarry, travail (with pain), tremble, trust, wait carefully (patiently), be wounded.', 'or חִיל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2898}/H9023/[H2895]', 'inflected', 'heb', 'טוּב', '["ṭûwb"]', '["[will be] goodness/ its","goodness/ his","prosperity/ his"]', '["n-m"]', 'good (as a noun), in the widest sense, especially goodness (superlative concretely, the best), beauty, gladness, welfare fair, gladness, good(-ness, thing, -s), joy, go well with.', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4390}/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["when/ is full"]', '["v"]', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly.', 'or מָלָא; (Esther 7:5), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5607B}/H9023/[H5606]', 'inflected', 'heb', 'סֵפֶק', '["çêpheq"]', '["sufficiency/ his"]', '["n-m"]', 'chastisement; also satiety stroke, sufficiency.', 'or שֶׂפֶק; (Job 20:22; Job 36:18), from 5606;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4305}/[H4305]', 'inflected', 'heb', 'מָטַר', '["mâṭar"]', '["and/ he will send rain"]', '["v"]', 'to rain (cause to) rain (upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3894}/H9023/[H3898]', 'inflected', 'heb', 'לָחוּם', '["lâchûwm"]', '["in/ bowel[s]/ his"]', '["n-m"]', 'properly, eaten, i.e. food; also flesh, i.e. body while...is eating, flesh.', 'or לָחֻם; passive participle of 3898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5402}/[H5401]', 'inflected', 'heb', 'נֶשֶׁק', '["nesheq"]', '["from/ a weapon of"]', '["n-m"]', 'military equipment, i.e. (collectively) arms (offensive or defensive), or (concretely) an arsenal armed men, armour(-y), battle, harness, weapon.', 'or נֵשֶׁק; from 5401;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1465}/[H1460]', 'inflected', 'heb', 'גֵּוָה', '["gêvâh"]', '["from/ [the] back"]', '["n-f"]', 'the back, i.e. (by extension) the person body.', 'feminine of 1460;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4846}/H9023/[H4843]', 'inflected', 'heb', 'מְרֹרָה', '["mᵉrôrâh"]', '["from/ gall-bladder/ his"]', '["n-f"]', 'properly, bitterness; concretely, a bitter thing; specifically bile; also venom (of a serpent) bitter (thing), gall.', 'or מְרוֹרָה; from 4843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6845}/H9023/[H6845]', 'inflected', 'heb', 'צָפַן', '["tsâphan"]', '["for/ treasured [things]/ his"]', '["v"]', 'to hide (by covering over); by implication, to hoard or reserve; figuratively to deny; specifically (favorably) to protect, (unfavorably) to lurk esteem, hide(-den one, self), lay up, lurk (be set) privily, (keep) secret(-ly, place).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5301}/[H5301]', 'lemma', 'heb', 'נָפַח', '["nâphach"]', '["I have caused to breathe out","[who] blows","blown upon","it has been fanned","it has panted"]', '["v"]', 'to puff, in various applications (literally, to inflate, blow hard, scatter, kindle, expire; figuratively, to disesteem) blow, breath, give up, cause to lose (life), seething, snuff.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5064}/[H5064]', 'lemma', 'heb', 'נָגַר', '["nâgar"]', '["it has poured itself","it was stretched out","poured out","torrents"]', '["v"]', 'to flow; figuratively, to stretch out; causatively, to pour out or down; figuratively, to deliver over fall, flow away, pour down (out), run, shed, spilt, trickle down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0561}/H9023/[H559]', 'inflected', 'heb', 'אֵמֶר', '["ʼêmer"]', '["decree/ his","words/ his"]', '["n-m"]', 'something said answer, × appointed unto him, saying, speech, word.', 'from 559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0410G}\/[H352]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["from/ God"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8575}/H9026/[H5162]', 'inflected', 'heb', 'תַּנְחוּם', '["tanchûwm"]', '["consolations/ your"]', '["n"]', 'compassion, solace comfort, consolation.', 'or תַּנְחֻם; and (feminine) תַּנְחוּמָה; from 5162;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375H}/H9030/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["bear with/ me","he will carry away/ me"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1696G}/H9040/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["have spoken/ I","speak/ I"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7307J}/H9020/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["spirit/ my"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8074H}/[H8074]', 'inflected', 'heb', 'שָׁמֵם', '["shâmêm"]', '["and/ I may be appalled","and/ be appalled"]', '["v"]', 'to stun (or intransitively, grow numb), i.e. devastate or (figuratively) stupefy (both usually in a passive sense) make amazed, be astonied, (be an) astonish(-ment), (be, bring into, unto, lay, lie, make) desolate(-ion, places), be destitute, destroy (self), (lay, lie, make) waste, wonder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6427}/[H6426]', 'lemma', 'heb', 'פַּלָּצוּת', '["pallâtsûwth"]', '["shuddering"]', '["n-f"]', 'affright fearfulness, horror, trembling.', 'from 6426;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6440H}/H9028/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<to>/ before/ them"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6631}/H9028/[H3318]', 'inflected', 'heb', 'צֶאֱצָא', '["tseʼĕtsâʼ"]', '["and/ descendants/ their"]', '["n-m"]', 'issue, i.e. produce, children that which cometh forth (out), offspring.', 'from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6403}/[H6403]', 'lemma', 'heb', 'פָּלַט', '["pâlaṭ"]', '["deliver","it calves","you will bring to safety"]', '["v"]', 'to slip out, i.e. escape; causatively, to deliver calve, carry away safe, deliver, (cause to) escape.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6510}/H9023/[H6499]', 'inflected', 'heb', 'פָּרָה', '["pârâh"]', '["cow/ his"]', '["n-f"]', 'a heifer cow, heifer, kine.', 'feminine of 6499;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5759}/H9028/[H5764]', 'inflected', 'heb', 'עֲוִיל', '["ʻăvîyl"]', '["young boys/ their"]', '["n-m"]', 'a babe young child, little one.', 'from 5764;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3206}/H9028/[H3205]', 'inflected', 'heb', 'יֶלֶד', '["yeled"]', '["and/ children/ their"]', '["n-m"]', 'something born, i.e. a lad or offspring boy, child, fruit, son, young man (one).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7540}/H9013/[H7540]', 'inflected', 'heb', 'רָקַד', '["râqad"]', '["they leap about/ !"]', '["v"]', 'properly, to stamp, i.e. to spring about (wildly or for joy) dance, jump, leap, skip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8596}/[H8608]', 'inflected', 'heb', 'תֹּף', '["tôph"]', '["according to/ tambourine"]', '["n-m"]', 'a tambourine tabret, timbrel.', 'from 8608 contracted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5748}/[H5689]', 'lemma', 'heb', 'עוּגָב', '["ʻûwgâb"]', '["a flute"]', '["n-m"]', 'a reed-instrument of music organ.', 'or עֻגָּב; from 5689 in the original sense of breathing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7281}/[H7280]', 'inflected', 'heb', 'רֶגַע', '["regaʻ"]', '["and/ in/ a moment"]', '["n-m"]', 'a wink (of the eyes), i.e. a very short space of time instant, moment, space, suddenly.', 'from 7280.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1847}/[H3045]', 'inflected', 'heb', 'דַּעַת', '["daʻath"]', '["and/ [the] knowledge of","and/ knowledge","and/ knowledge of"]', '["n"]', 'knowledge cunning, (ig-) norantly, know(-ledge), (un-) awares (wittingly).', 'from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2898}/H9028/[H2895]', 'inflected', 'heb', 'טוּב', '["ṭûwb"]', '["prosperity/ their"]', '["n-m"]', 'good (as a noun), in the widest sense, especially goodness (superlative concretely, the best), beauty, gladness, welfare fair, gladness, good(-ness, thing, -s), joy, go well with.', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2256B}/[H2254]', 'lemma', 'heb', 'חֶבֶל', '["chebel"]', '["[the] pains of","labor-pain[s]","labor-pains","pain<s>"]', '["n-m"]', 'a rope (as twisted), especially a measuring line; by implication, a district or inheritance (as measured); or a noose (as of cords); figuratively, a company (as if tied together); a throe (especially of parturition); also ruin band, coast, company, cord, country, destruction, line, lot, pain, pang, portion, region, rope, snare, sorrow, tackling.', 'or חֵבֶל; from 2254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8401}/[H1129]', 'inflected', 'heb', 'תֶּבֶן', '["teben"]', '["like/ straw"]', '["n-m"]', 'properly, material, i.e. (specifically) refuse haum or stalks of grain (as chopped in threshing and used for fodder) chaff, straw, stubble.', 'probably from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H4671}/[H4160]', 'inflected', 'heb', 'מֹץ', '["môts"]', '["and/ like/ chaff"]', '["n-m"]', 'chaff (as pressed out, i.e. winnowed or (rather) threshed loose) chaff.', 'or מוֹץ; (Zephaniah 2:2), from 4160;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1589}/H9033/[H1589]', 'inflected', 'heb', 'גָּנַב', '["gânab"]', '["[which] it has stolen/ it","it steals away/ him"]', '["v"]', 'to thieve (literally or figuratively); by implication, to deceive carry away, × indeed, secretly bring, steal (away), get by stealth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5492A}/[H5486]', 'lemma', 'heb', 'סוּפָה', '["çûwphâh"]', '["a storm-wind"]', '["n-f n-pr-loc"]', 'a hurricane Red Sea, storm, tempest, whirlwind, Red sea.', 'from 5486;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0205G>/H9023', 'opaque', 'heb', 'אָוֶן', '["ʼâven"]', '["wickedness/ his"]', '["n-m"]', 'strictly nothingness; also trouble, vanity, wickedness; specifically an idol affliction, evil, false, idol, iniquity, mischief, mourners(-ing), naught, sorrow, unjust, unrighteous, vain, vanity, wicked(-ness). Compare 369.', 'from an unused root perhaps meaning properly, to pant (hence, to exert oneself, usually in vain; to come to naught);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3589}/H9023/[H3589]', 'inflected', 'heb', 'כִּיד', '["kîyd"]', '["destruction/ his"]', '["n-m"]', 'a crushing; figuratively, calamity destruction.', 'from a primitive root meaning to strike;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H2534}/[H3179]', 'inflected', 'heb', 'חֵמָה', '["chêmâh"]', '["and/ from/ [the] rage of"]', '["n-f"]', 'heat; figuratively, anger, poison (from its fever) anger, bottles, hot displeasure, furious(-ly, -ry), heat, indignation, poison, rage, wrath(-ful). See 2529.', 'or (Daniel 11:44) חֵמָא; from 3179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2686A}/[H2673]', 'lemma', 'heb', 'חָצַץ', '["châtsats"]', '["dividing","they have been cut off"]', '["v"]', 'properly, to chop into, pierce or sever; hence, to curtail, to distribute (into ranks); to shoot an arrow archer, × bands, cut off in the midst.', 'a primitive root (compare 2673); also as denominative from 2671');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8537}/H9023/[H8552]', 'inflected', 'heb', 'תֹּם', '["tôm"]', '["completeness/ his"]', '["n-m"]', 'completeness; figuratively, prosperity; usually (morally) innocence full, integrity, perfect(-ion), simplicity, upright(-ly, -ness), at a venture. See 8550.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7946}/[H7600]', 'lemma', 'heb', 'שַׁלְאֲנָן', '["shalʼănân"]', '["[is] at ease"]', '["a"]', 'tranquil being at ease.', 'for 7600;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5845>/H9023', 'opaque', 'heb', 'עֲטִין', '["ʻăṭîyn"]', '["pails/ his"]', '["n-m"]', 'a receptacle (for milk, i.e. pail; figuratively, breast) breast.', 'from an unused root meaning apparently to contain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4221}/[H4220]', 'inflected', 'heb', 'מֹחַ', '["môach"]', '["and/ [the] marrow of"]', '["n-m"]', 'fat, i.e. marrow marrow.', 'from the same as 4220;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2896C}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["in the/ good","on/ [the] good thing[s] of"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4284}/H9026/[H2803]', 'inflected', 'heb', 'מַחֲשָׁבָה', '["machăshâbâh"]', '["[are] thoughts/ your","thoughts/ your"]', '["n-f"]', 'a contrivance, i.e. (concretely) a texture, machine, or (abstractly) intention, plan (whether bad, a plot; or good, advice) cunning (work), curious work, device(-sed), imagination, invented, means, purpose, thought.', 'or מַחֲשֶׁבֶת; from 2803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4209}/[H2161]', 'inflected', 'heb', 'מְזִמָּה', '["mᵉzimmâh"]', '["and/ [the] schemes","and/ discretion"]', '["n-f"]', 'a plan, usually evil (machination), sometimes good (sagacity) (wicked) device, discretion, intent, witty invention, lewdness, mischievous (device), thought, wickedly.', 'from 2161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0226H}/H9028/[H225]', 'inflected', 'heb', 'אוֹת', '["ʼôwth"]', '["and/ signs/ their"]', '["n-f"]', 'a signal (literally or figuratively), as a flag, beacon, monument, omen, prodigy, evidence, etc. mark, miracle, (en-) sign, token.', 'probably from 225 (in the sense of appearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0343}/[H181]', 'lemma', 'heb', 'אֵיד', '["ʼêyd"]', '["<the> calamity of","[does] calamity","[the] disaster of","calamity"]', '["n-m"]', 'oppression; by implication misfortune, ruin calamity, destruction.', 'from the same as 181 (in the sense of bending down);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5678}/[H5676]', 'lemma', 'heb', 'עֶבְרָה', '["ʻebrâh"]', '["[is] fury","[the] furi<es> of","[the] fury of","furi<es>","fury"]', '["n-f"]', 'an outburst of passion anger, rage, wrath.', 'feminine of 5676;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1430B>', 'opaque', 'heb', 'גָּדִישׁ', '["gâdîysh"]', '["a tomb"]', '["n-m"]', 'a stack of sheaves; by analogy, a tomb shock (stack) (of corn), tomb.', 'from an unused root (meaning to heap up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7263>', 'opaque', 'heb', 'רֶגֶב', '["regeb"]', '["[the] clods of"]', '["n-m"]', 'a lump of clay clod.', 'from an unused root meaning to pile together;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6440G}/H9023/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["and/ <to>/ before/ him","and/ <to>/ before/ it"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8666}/H9026/[H7725]', 'inflected', 'heb', 'תְּשׁוּבָה', '["tᵉshûwbâh"]', '["and/ answers/ your"]', '["n-f"]', 'a recurrence (of time or place); a reply (as returned) answer, be expired, return.', 'or תְּשֻׁבָה; from 7725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4604}\/[H4603]', 'inflected', 'heb', 'מַעַל', '["maʻal"]', '["unfaithfulness"]', '["n-m"]', 'treachery, i.e. sin falsehood, grievously, sore, transgression, trespass, × very.', 'from 4603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7706}/[H7703]', 'inflected', 'heb', 'שַׁדַּי', '["Shadday"]', '["[belong] to/ [the] Almighty"]', '["n-m"]', 'the Almighty Almighty.', 'from 7703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9006/{H3374}/H9021/[H3373]', 'inflected', 'heb', 'יִרְאָה', '["yirʼâh"]', '["¿/ from/ fear/ your"]', '["n-f"]', 'fear (also used as infinitive); morally, reverence × dreadful, × exceedingly, fear(-fulness).', 'feminine of 3373;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3198}/H9031/[H3198]', 'inflected', 'heb', 'יָכַח', '["yâkach"]', '["I rebuke/ you","I will rebuke/ you","does he reprove/ you"]', '["v"]', 'to be right (i.e. correct); reciprocal, to argue; causatively, to decide, justify or convict appoint, argue, chasten, convince, correct(-ion), daysman, dispute, judge, maintain, plead, reason (together), rebuke, reprove(-r), surely, in any wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7451I}/H9021/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["[is] evil/ your"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5771G}/H9021/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["[belongs] to/ iniquities/ your"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H7457}/[H7456]', 'inflected', 'heb', 'רָעֵב', '["râʻêb"]', '["and/ from/ [the] hungry"]', '["a"]', 'hungry (more or less intensely) hunger bitten, hungry.', 'from 7456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2220}/[H2232]', 'inflected', 'heb', 'זְרוֹעַ', '["zᵉrôwaʻ"]', '["and/ [the] arm of","and/ [the] arms of","and/ [the] forces of","and/ an arm","and/ forces"]', '["n-f"]', 'the arm (as stretched out), or (of animals) the foreleg; figuratively, force arm, help, mighty, power, shoulder, strength.', 'or (shortened) זְרֹעַ; and (feminine) זְרוֹעָה; or זְרֹעָה; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1792}/[H1794]', 'lemma', 'heb', 'דָּכָא', '["dâkâʼ"]', '["[was] crushed","contrite [people]","crushed","he has crushed","it has been crushed","they crush","they have been made contrite","you crush","you crushed"]', '["v"]', 'to crumble; transitively, to bruise (literally or figuratively) beat to pieces, break (in pieces), bruise, contrite, crush, destroy, humble, oppress, smite.', 'a primitive root (compare 1794);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5439G}/H9031/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["[are] around/ you","[is] around/ you","around/ you"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0926}/H9031/[H926]', 'inflected', 'heb', 'בָּהַל', '["bâhal"]', '["and/ it terrifies/ you"]', '["v"]', 'to tremble inwardly (or palpitate), i.e. (figuratively) be (causative, make) (suddenly) alarmed or agitated; by implication to hasten anxiously be (make) affrighted (afraid, amazed, dismayed, rash), (be, get, make) haste(-n, -y, -ily), (give) speedy(-ily), thrust out, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8229}/[H8228]', 'inflected', 'heb', 'שִׁפְעָה', '["shiphʻâh"]', '["and/ abundance of","and/ an abundance of"]', '["n-f"]', 'copiousness abundance, company, multitude.', 'feminine of 8228;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3680}/H9031/[H3680]', 'inflected', 'heb', 'כָּסָה', '["kâçâh"]', '["I have covered/ you","it covers/ you","it will cover/ you","will you cover?/ yourself"]', '["v"]', 'properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H1157}/[H5704]', 'inflected', 'heb', 'בְּעַד', '["bᵉʻad"]', '["¿/ through"]', '["prep"]', 'in up to or over against; generally at, beside, among, behind, for, etc. about, at by (means of), for, over, through, up (-on), within.', 'from 5704 with prepositional prefix;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6205}/[H6201]', 'lemma', 'heb', 'עֲרָפֶל', '["ʻărâphel"]', '["thick darkness"]', '["n-m"]', 'gloom (as of a lowering sky) (gross, thick) dark (cloud, -ness).', 'probably from 6201;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2329}/[H2328]', 'inflected', 'heb', 'חוּג', '["chûwg"]', '["and/ [the] circle of"]', '["n-m"]', 'a circle circle, circuit, compass.', 'from 2328;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0734}/[H732]', 'inflected', 'heb', 'אֹרַח', '["ʼôrach"]', '["¿/ a path of"]', '["n-m"]', 'a well-trodden road (literally or figuratively); also a caravan manner, path, race, rank, traveller, troop, (by-, high-) way.', 'from 732;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7059}/[H7059]', 'lemma', 'heb', 'קָמַט', '["qâmaṭ"]', '["they were snatched away"]', '["v"]', 'to pluck, i.e. destroy cut down, fill with wrinkles.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7009}/H9025/[H6965]', 'inflected', 'heb', 'קִים', '["qîym"]', '["adversary/ our"]', '["n-m"]', 'an opponent (as rising against one), i.e. (collectively) enemies substance.', 'from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7999B}/[H7999]', 'inflected', 'heb', 'שָׁלַם', '["shâlam"]', '["and/ be at peace"]', '["v"]', 'to be safe (in mind, body or estate); figuratively, to be (causatively, make) completed; by implication, to be friendly; by extension, to reciprocate (in various applications) make amends, (make an) end, finish, full, give again, make good, (re-) pay (again), (make) (to) (be at) peace(-able), that is perfect, perform, (make) prosper(-ous), recompense, render, requite, make restitution, restore, reward, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935G}/H9031/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["it will come to/ you"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0168G}/H9021/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["from/ tent/ your"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1220}/[H1219]', 'lemma', 'heb', 'בֶּצֶר', '["betser"]', '["gold"]', '["n-m"]', 'strictly a clipping, i.e. gold (as dug out) gold defence.', 'from 1219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6697H}/[H6696]', 'inflected', 'heb', 'צוּר', '["tsûwr"]', '["and/ among/ [the] rock[s] of"]', '["n-m"]', 'properly, a cliff (or sharp rock, as compressed); generally, a rock or boulder; figuratively, a refuge; also an edge (as precipitous) edge, × (mighty) God (one), rock, × sharp, stone, × strength, × strong. See also 1049.', 'or צֻר; from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1220}/H9021/[H1219]', 'inflected', 'heb', 'בֶּצֶר', '["betser"]', '["gold<s>/ your"]', '["n-m"]', 'strictly a clipping, i.e. gold (as dug out) gold defence.', 'from 1219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8443}/[H3286]', 'lemma', 'heb', 'תּוֹעָפָה', '["tôwʻâphâh"]', '["heaps"]', '["n-f"]', '(only in plural collective) weariness, i.e. (by implication) toil (treasure so obtained) or speed plenty, strength.', 'from 3286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6026}/[H6026]', 'lemma', 'heb', 'עָנַג', '["ʻânag"]', '["are you making fun","will he take delight","you will take delight"]', '["v"]', 'to be soft or pliable, i.e. (figuratively) effeminate or luxurious delicate(-ness), (have) delight (self), sport self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8085G}/H9031/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["and/ he will hear/ you"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1504}/[H1504]', 'inflected', 'heb', 'גָּזַר', '["gâzar"]', '["and/ you may decide"]', '["v"]', 'to cut down or off; (figuratively) to destroy, divide, exclude, or decide cut down (off), decree, divide, snatch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0562}/[H561]', 'lemma', 'heb', 'אֹמֶר', '["ʼômer"]', '["[is] speech","a matter","a word","speech"]', '["n-m"]', 'promise, speech, thing, word.', 'the same as 561');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1466}/[H1465]', 'lemma', 'heb', 'גֵּוָה', '["gêvâh"]', '["pride","up!"]', '["n-f"]', 'exaltation; (figuratively) arrogance lifting up, pride.', 'the same as 1465;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7807}/[H7817]', 'inflected', 'heb', 'שַׁח', '["shach"]', '["and/ [the] lowly of"]', '["a"]', 'sunk, i.e. downcast humble.', 'from 7817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0336}/[H335]', 'lemma', 'heb', 'אִי', '["ʼîy"]', '["not"]', '["adv"]', 'not island (Job 22:30).', 'probably identical with 335 (through the idea of a query);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1252}/[H1305]', 'inflected', 'heb', 'בֹּר', '["bôr"]', '["by/ [the] cleanness of"]', '["n-m"]', 'purity cleanness, pureness.', 'from 1305;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3709G}/H9021\/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["hands/ your"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4672}/H9033/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["and/ I will find/ him"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8499}/H9023/[H3559]', 'inflected', 'heb', 'תְּכוּנָה', '["tᵉkûwnâh"]', '["place/ his"]', '["n-f"]', 'something arranged or fixed, i.e. a place seat.', 'from 3559; or probably identical with 8498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6310G}/H9020/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["and/ mouth/ my"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8433B}/[H3198]', 'lemma', 'heb', 'תּוֹכֵחָה', '["tôwkêchâh"]', '["<of> correction of","[are] arguments","arguments","correction","rebuke","rebukes","rebukes of"]', '["n-f"]', 'chastisement; figuratively (by words) correction, refutation, proof (even in defence) argument, × chastened, correction, reasoning, rebuke, reproof, × be (often) reproved.', 'and תּוֹכַחַת; from 3198;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9003/{H7230}/[H7231]', 'inflected', 'heb', 'רֹב', '["rôb"]', '["¿/ with/ greatness of"]', '["n-m"]', 'abundance (in any respect) abundance(-antly), all, × common (sort), excellent, great(-ly, -ness, number), huge, be increased, long, many, more in number, most, much, multitude, plenty(-ifully), × very (age).', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6403}/[H6403]', 'inflected', 'heb', 'פָּלַט', '["pâlaṭ"]', '["and/ I will deliver","so/ it may carry [it] off"]', '["v"]', 'to slip out, i.e. escape; causatively, to deliver calve, carry away safe, deliver, (cause to) escape.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8199}/H9030/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["from/ judge/ my"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6924I}/[H6923]', 'lemma', 'heb', 'קֶדֶם', '["qedem"]', '["forward"]', '["n-m adv"]', 'the front, of place (absolutely, the fore part, relatively the East) or time (antiquity); often used adverbially (before, anciently, eastward) aforetime, ancient (time), before, east (end, part, side, -ward), eternal, × ever(-lasting), forward, old, past. Compare 6926.', 'or קֵדְמָה; from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6213A}/H9043/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["when/ acts/ he"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5848A}/[H5848]', 'lemma', 'heb', 'עָטַף', '["ʻâṭaph"]', '["he turns"]', '["v"]', 'to shroud, i.e. clothe (whether transitive or reflex.); hence (from the idea of darkness) to languish cover (over), fail, faint, feebler, hide self, be overwhelmed, swoon.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0974}/H9030/[H974]', 'inflected', 'heb', 'בָּחַן', '["bâchan"]', '["he has tested/ me","test/ me","they tested/ me"]', '["v"]', 'to test (especially metals); generally and figuratively, to investigate examine, prove, tempt, try (trial).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0838A}/H9023/[H833]', 'inflected', 'heb', 'אָשֻׁר', '["ʼâshur"]', '["on/ step/ his"]', '["n-f"]', 'a step going, step.', 'or אַשֻּׁר; from 833 in the sense of going;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2706H}/H9020/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["more than/ portion/ my"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725I}/H9033/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["will he turn back/ him"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2706H}/H9020/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["allotment/ my","decree/ my"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6342}/[H6342]', 'inflected', 'heb', 'פָּחַד', '["pâchad"]', '["and/ I may be in dread"]', '["v"]', 'to be startled (by a sudden alarm); hence, to fear in general be afraid, stand in awe, (be in) fear, make to shake.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0926}/H9030/[H926]', 'inflected', 'heb', 'בָּהַל', '["bâhal"]', '["he has terrified/ me"]', '["v"]', 'to tremble inwardly (or palpitate), i.e. (figuratively) be (causative, make) (suddenly) alarmed or agitated; by implication to hasten anxiously be (make) affrighted (afraid, amazed, dismayed, rash), (be, get, make) haste(-n, -y, -ily), (give) speedy(-ily), thrust out, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6440H}/H9020/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["and/ from/ before/ me","and/ from/ face/ my"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7706}/[H7703]', 'inflected', 'heb', 'שַׁדַּי', '["Shadday"]', '["[which] from/ [the] Almighty","from/ [the] Almighty"]', '["n-m"]', 'the Almighty Almighty.', 'from 7703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6467}/H9028/[H6466]', 'inflected', 'heb', 'פֹּעַל', '["pôʻal"]', '["in/ work/ their"]', '["n-m"]', 'an act or work (concretely) act, deed, do, getting, maker, work.', 'from 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2964}/[H2963]', 'inflected', 'heb', 'טֶרֶף', '["ṭereph"]', '["for <the>/ food","for the/ prey"]', '["n-m"]', 'something torn, i.e. a fragment, e.g. a fresh leaf, prey, food leaf, meat, prey, spoil.', 'from 2963;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3953}/[H3953]', 'lemma', 'heb', 'לָקַשׁ', '["lâqash"]', '["they glean"]', '["v"]', 'to gather the after crop gather.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7135}/[H7119]', 'inflected', 'heb', 'קָרָה', '["qârâh"]', '["in the/ coldness"]', '["n-f"]', 'coolness cold.', 'feminine of 7119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2230}/[H2229]', 'inflected', 'heb', 'זֶרֶם', '["zerem"]', '["from/ [the] rain of","from/ [the] storm","from/ rainstorm"]', '["n-m"]', 'a gush of water flood, overflowing, shower, storm, tempest.', 'from 2229;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7372}/[H7372]', 'lemma', 'heb', 'רָטַב', '["râṭab"]', '["they are wet"]', '["v"]', 'to be moist be wet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1097}/[H1086]', 'inflected', 'heb', 'בְּלִי', '["bᵉlîy"]', '["and/ because/ not"]', '["np"]', 'properly, failure, i.e. nothing or destruction; usually (with preposition) without, not yet, because not, as long as, etc. corruption, ig(norantly), for lack of, where no...is, so that no, none, not, un(awares), without.', 'from 1086;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4268}/[H2620]', 'lemma', 'heb', 'מַחֲסֶה', '["machăçeh"]', '["[are] a refuge","[is] a refuge","[the] refuge of","a refuge","a shelter","shelter"]', '["n-m"]', 'a shelter (literally or figuratively) hope, (place of) refuge, shelter, trust.', 'or מַחְסֶה; from 2620;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7699B}/[H7736]', 'inflected', 'heb', 'שַׁד', '["shad"]', '["from/ [the] breast","from/ [the] breast of"]', '["n-m"]', 'the breast of a woman or animal (as bulging) breast, pap, teat.', 'or שֹׁד; probably from 7736 (in its original sense) contracted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7791A}/H9028/[H7788]', 'inflected', 'heb', 'שׁוּר', '["shûwr"]', '["rows/ their"]', '["n-m"]', 'a wall (as going about) wall.', 'from 7788;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6671}/[H3323]', 'lemma', 'heb', 'צָהַר', '["tsâhar"]', '["they press out oil"]', '["v"]', 'to press out oil make oil.', 'a primitive root; to glisten; used only as denominative from 3323,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5008}/[H5008]', 'lemma', 'heb', 'נָאַק', '["nâʼaq"]', '["they groan"]', '["v"]', 'to groan groan.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2491H}/[H2490]', 'lemma', 'heb', 'חָלָל', '["châlâl"]', '["[one] fatally wounded","[the] fatally wounded","[those] fatally wounded","slain [ones]"]', '["n-m"]', 'pierced (especially to death); figuratively, polluted kill, profane, slain (man), × slew, (deadly) wounded.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0433}/[H410]', 'inflected', 'heb', 'אֱלוֹהַּ', '["ʼĕlôwahh"]', '["and/ God"]', '["n-m"]', 'a deity or the Deity God, god. See 430.', 'rarely (shortened) אֱלֹהַּ; probably prolonged (emphatic) from 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4775}/[H4775]', 'inflected', 'heb', 'מָרַד', '["mârad"]', '["among/ [those who] rebel against"]', '["v"]', 'to rebel rebel(-lious).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H5410B>/H9023', 'inflected', 'heb', 'בנתיבתיו', '["bi/n.ti.vo.Ta/v"]', '["in/ paths/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6991}/[H6991]', 'lemma', 'heb', 'קָטַל', '["qâṭal"]', '["he kills","you will kill"]', '["v"]', 'properly, to cut off, i.e. (figuratively) put to death kill, slay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1590}/[H1589]', 'inflected', 'heb', 'גַּנָּב', '["gannâb"]', '["like <the>/ thief"]', '["n-m"]', 'a stealer thief.', 'from 1589;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5643A}/[H5641]', 'inflected', 'heb', 'סֵתֶר', '["çêther"]', '["and/ [the] shelter","and/ a shelter of","and/ covering of"]', '["n-m"]', 'a cover (in a good or a bad, a literal or a figurative sense) backbiting, covering, covert, × disguise(-th), hiding place, privily, protection, secret(-ly, place).', 'or (feminine) סִתְרָה; (Deuteronomy 32:38), from 5641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2864}/[H2864]', 'lemma', 'heb', 'חָתַר', '["châthar"]', '["I dug","dig","he digs into","they will dig"]', '["v"]', 'to force a passage, as by burglary; figuratively, with oars dig (through), row.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2513A}/H9028/[H2506]', 'inflected', 'heb', 'חֶלְקָה', '["chelqâh"]', '["portion/ their"]', '["n-f"]', 'properly, smoothness; figuratively, flattery; also an allotment field, flattering(-ry), ground, parcel, part, piece of land (ground), plat, portion, slippery place, smooth (thing).', 'feminine of 2506;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6723>', 'opaque', 'heb', 'צִיָּה', '["tsîyâh"]', '["a desert","a dry region","drought","dry"]', '["n-f"]', 'aridity; concretely, a desert barren, drought, dry (land, place), solitary place, wilderness.', 'from an unused root meaning to parch;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7911}/H9033/[H7911]', 'inflected', 'heb', 'שָׁכַח', '["shâkach"]', '["it forgets/ him"]', '["v"]', 'to mislay, i.e. to be oblivious of, from want of memory or attention × at all, (cause to) forget.', 'or שָׁכֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4985}/H9033/[H4985]', 'inflected', 'heb', 'מָתַק', '["mâthaq"]', '["it sucks on/ him"]', '["v"]', 'to suck, by implication, to relish, or (intransitively) be sweet be (made, × take) sweet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4355}/[H4355]', 'inflected', 'heb', 'מָכַךְ', '["mâkak"]', '["and/ they are brought low","and/ they sank"]', '["v"]', 'to tumble (in ruins); figuratively, to perish be brought low, decay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7092}/H9013/[H7092]', 'inflected', 'heb', 'קָפַץ', '["qâphats"]', '["they are contracted/ !"]', '["v"]', 'to draw together, i.e. close; by implication, to leap (by contracting the limbs); specifically, to die (from gathering up the feet) shut (up), skip, stop, take out of the way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/<H7218A>', 'inflected', 'heb', 'וכראש', '["u./khe./Rosh"]', '["and/ like/ a head of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3576}/H9030/[H3576]', 'inflected', 'heb', 'כָּזַב', '["kâzab"]', '["will he prove a liar/ me"]', '["v"]', 'to lie (i.e. deceive), literally or figuratively fail, (be found a, make a) liar, lie, lying, be in vain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7760J}/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ will he make?"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0408}/[H3808]', 'inflected', 'heb', 'אַל', '["ʼal"]', '["into/ nothing"]', '["adv"]', 'not (the qualified negation, used as a deprecative); once (Job 24:25) as a noun, nothing nay, neither, + never, no, nor, not, nothing (worth), rather than.', 'a negative particle (akin to 3808);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4405}/H9020\/[H4448]', 'inflected', 'heb', 'מִלָּה', '["millâh"]', '["speech/ my"]', '["n-f"]', 'a word; collectively, a discourse; figuratively, a topic answer, by-word, matter, any thing (what) to say, to speak(-ing), speak, talking, word.', 'from 4448 (plural masculine as if from מִלֶּה;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4791}/H9023/[H7311]', 'inflected', 'heb', 'מָרוֹם', '["mârôwm"]', '["in/ heights/ his"]', '["n-m"]', 'altitude, i.e. concretely (an elevated place), abstractly (elevation, figuratively (elation), or adverbially (aloft) (far) above, dignity, haughty, height, (most, on) high (one, place), loftily, upward.', 'from 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1416}/H9023/[H1413]', 'inflected', 'heb', 'גְּדוּד', '["gᵉdûwd"]', '["to/ troops/ his"]', '["n-m"]', 'a crowd (especially of soldiers) army, band (of men), company, troop (of robbers).', 'from 1413;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0216}/H9023/[H215]', 'inflected', 'heb', 'אוֹר', '["ʼôwr"]', '["light/ his","light/ its"]', '["n-f"]', 'illumination or (concrete) luminary (in every sense, including lightning, happiness, etc.) bright, clear, day, light (-ning), morning, sun.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3394}/[H3391]', 'lemma', 'heb', 'יָרֵחַ', '["yârêach"]', '["[the] moon","moon"]', '["n-m"]', 'the moon moon. Yrechow. See 3405.', 'from the same as 3391;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0166}/[H166]', 'lemma', 'heb', 'אָהַל', '["ʼâhal"]', '["it is clear"]', '["v"]', 'to be clear shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3556}/[H3522]', 'inflected', 'heb', 'כּוֹכָב', '["kôwkâb"]', '["and/ [the] stars","and/ stars"]', '["n-m"]', 'a star (as round or as shining); figuratively, a prince star(-gazer).', 'probably from the same as 3522 (in the sense of rolling) or 3554 (in the sense of blazing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8438B}\/[H3216]', 'inflected', 'heb', 'תּוֹלָע', '["tôwlâʻ"]', '["a worm"]', '["n-m n-f"]', 'a maggot (as voracious); specifically (often with ellipsis of 8144) the crimson-grub, but used only (in this connection) of the color from it, and cloths dyed therewith crimson, scarlet, worm.', 'and (feminine) תּוֹלֵעָה; or תּוֹלַעַת; or תֹּלַעַת; from 3216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5397}/[H5395]', 'inflected', 'heb', 'נְשָׁמָה', '["nᵉshâmâh"]', '["and/ [the] breath of","and/ breath","and/ breaths"]', '["n-f"]', 'a puff, i.e. wind, angry or vital breath, divine inspiration, intellect. or (concretely) an animal blast, (that) breath(-eth), inspiration, soul, spirit.', 'from 5395;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7496}/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["the/ shades"]', '["n-m"]', 'properly, lax, i.e. (figuratively) a ghost (as dead; in plural only) dead, deceased.', 'from 7495 in the sense of 7503;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7931}/H9038/[H7901]', 'inflected', 'heb', 'שָׁכַן', '["shâkan"]', '["and/ [those which] dwell in/ them"]', '["v"]', 'to reside or permanently stay (literally or figuratively) abide, continue, (cause to, make to) dwell(-er), have habitation, inhabit, lay, place, (cause to) remain, rest, set (up).', 'a primitive root (apparently akin (by transmission) to 7901 through the idea of lodging; compare 5531, 7925);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0011}/[H6]', 'inflected', 'heb', 'אֲבַדּוֹן', '["ʼăbaddôwn"]', '["[belongs] to <the>/ Abaddon"]', '["n-pr-loc"]', 'abstract, a perishing; concrete, Hades destruction.', 'intensive from 6;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5645}/H9023/[H5743]', 'inflected', 'heb', 'עָב', '["ʻâb"]', '["in/ clouds/ his"]', '["n-m"]', 'properly, an envelope, i.e. darkness (or density, 2 Chronicles 4:17); specifically, a (scud) cloud; also a copse clay, (thick) cloud, × thick, thicket. Compare 5672.', '(masculine and feminine); from 5743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6576}/[H6567]', 'lemma', 'heb', 'פַּרְשֵׁז', '["parshêz"]', '["he spreads"]', '["v"]', 'to expand spread.', 'a root apparently formed by compounding 6567 and that of 6518 (compare 6574);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6051}/H9023/[H6049]', 'inflected', 'heb', 'עָנָן', '["ʻânân"]', '["cloud/ his"]', '["n-m"]', 'a cloud (as covering the sky), i.e. the nimbus or thunder-cloud cloud(-y).', 'from 6049;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2706I}/[H2710]', 'lemma', 'heb', 'חֹק', '["chôq"]', '["a boundary","a decree of","a limit","limit"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2328}/[H2287]', 'lemma', 'heb', 'חוּג', '["chûwg"]', '["he has drawn a circle"]', '["v"]', 'to describe a circle compass.', 'a primitive root (compare 2287);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7322}/[H7322]', 'lemma', 'heb', 'רוּף', '["rûwph"]', '["they shake"]', '["v"]', 'properly, to triturate (in a mortar), i.e. (figuratively) to agitate (by concussion) tremble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8539}/[H8539]', 'inflected', 'heb', 'תָּמַהּ', '["tâmahh"]', '["and/ be astounded","and/ they may be astonished"]', '["v"]', 'to be in consternation be amazed, be astonished, marvel(-lously), wonder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1606}/H9023/[H1605]', 'inflected', 'heb', 'גְּעָרָה', '["gᵉʻârâh"]', '["from/ rebuke/ his"]', '["n-f"]', 'a chiding rebuke(-ing), reproof.', 'from 1605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7280A}/[H7280]', 'lemma', 'heb', 'רָגַע', '["râgaʻ"]', '["I will act in a moment","I will grant rest","[who] stirs up","he stirred up"]', '["v"]', 'properly, to toss violently and suddenly (the sea with waves, the skin with boils); figuratively (in a favorable manner) to settle, i.e. quiet; specifically, to wink (from the motion of the eye-lids) break, divide, find ease, be a moment, (cause, give, make to) rest, make suddenly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8394}/H9023/[H995]', 'inflected', 'heb', 'תָּבוּן', '["tâbûwn"]', '["and/ by/ understanding/ his"]', '["n-m"]', 'intelligence; by implication, an argument; by extension, caprice discretion, reason, skilfulness, understanding, wisdom.', 'and (feminine) תְּבוּנָה; or תּוֹבֻנָה; from 995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7307H}/H9023/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["by/ wind/ his"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8235}/[H8231]', 'lemma', 'heb', 'שִׁפְרָה', '["shiphrâh"]', '["[are] clearness"]', '["n-f"]', 'brightness garnish.', 'from 8231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2490A}/[H2470]', 'lemma', 'heb', 'חָלַל', '["châlal"]', '["[was] pierced","[who] pierced","[who] wounds","it pierced","pierced of","someone has pierced"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1281}/[H1272]', 'lemma', 'heb', 'בָּרִיחַ', '["bârîyach"]', '["[as] fugitives","fleeing"]', '["n-m"]', 'a fugitive, i.e. the serpent (as fleeing), and the constellation by that name crooked, noble, piercing.', 'or בָּרִחַ; (shortened) from 1272;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7482}/[H7481]', 'inflected', 'heb', 'רַעַם', '["raʻam"]', '["and/ [the] thunder of"]', '["n-m"]', 'a peal of thunder thunder.', 'from 7481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0995}\/[H995]', 'inflected', 'heb', 'בִּין', '["bîyn"]', '["[was one] giving understanding","will he understand"]', '["v"]', 'to separate mentally (or distinguish), i.e.(generally) understand attend, consider, be cunning, diligently, direct, discern, eloquent, feel, inform, instruct, have intelligence, know, look well to, mark, perceive, be prudent, regard, (can) skill(-full), teach, think, (cause, make to, get, give, have) understand(-ing), view, (deal) wise(-ly, man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4941H}/H9020/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["judgment/ my","justice/ my","right/ my"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5397}/H9020/[H5395]', 'inflected', 'heb', 'נְשָׁמָה', '["nᵉshâmâh"]', '["breath/ my"]', '["n-f"]', 'a puff, i.e. wind, angry or vital breath, divine inspiration, intellect. or (concretely) an animal blast, (that) breath(-eth), inspiration, soul, spirit.', 'from 5395;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0639H}/H9020/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["[is] in/ nostril[s]/ my","in/ nose/ my"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3956G}/H9020/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["and/ tongue/ my"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1897}/[H1901]', 'lemma', 'heb', 'הָגָה', '["hâgâh"]', '["I have meditated","I meditate","I moan","certainly <to moan>","do they devise?","he meditates","he will groan","it considers","it growls","it mutters","it plots","it utters","it will meditate on","it will utter","they devise","they make a sound","we moan","you will groan"]', '["v"]', 'to murmur (in pleasure or anger); by implication, to ponder imagine, meditate, mourn, mutter, roar, × sore, speak, study, talk, utter.', 'a primitive root (compare 1901);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8538}/H9020/[H8537]', 'inflected', 'heb', 'תֻּמָּה', '["tummâh"]', '["integrity/ my"]', '["n-f"]', 'innocence integrity.', 'feminine of 8537;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H3117G>/H9020', 'inflected', 'heb', 'מימי', '["mi./ya.Ma/i"]', '["any of/ days/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6965J}/H9030/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["and/ [one who] raises himself against/ me"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5767}/[H5765]', 'inflected', 'heb', 'עַוָּל', '["ʻavvâl"]', '["like/ an evil-doer"]', '["n-m"]', 'evil (morally) unjust, unrighteous, wicked.', 'intensive from 5765;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1214G}/[H1214]', 'lemma', 'heb', 'בָּצַע', '["bâtsaʻ"]', '["he will cut off"]', '["v"]', 'to break off, i.e. (usually) plunder; figuratively, to finish, or (intransitively) stop (be) covet(-ous), cut (off), finish, fulfill, gain (greedily), get, be given to (covetousness), greedy, perform, be wounded.', 'a primitive root');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7953}/[H5394]', 'lemma', 'heb', 'שָׁלָה', '["shâlâh"]', '["he will take away"]', '["v"]', 'to draw out or off, i.e. remove (the soul by death) take away.', 'a primitive root (rather cognate (by contraction) to the base of 5394, 7997 and their congeners through the idea of extracting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H6818}/H9023/[H6817]', 'inflected', 'heb', 'צַעֲקָה', '["tsaʻăqâh"]', '["¿/ cry/ his"]', '["n-f"]', 'a shriek cry(-ing).', 'from 6817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1891}/[H1891]', 'lemma', 'heb', 'הָבַל', '["hâbal"]', '["[are] deluding","do you act in vain","you put vain hope"]', '["v"]', 'to be vain in act, word, or expectation; specifically to lead astray be (become, make) vain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3926}/[H3926]', 'lemma', 'heb', 'לְמוֹ', '["lᵉmôw"]', '["for","to"]', '["prep"]', 'to or for at, for, to, upon.', 'a prolonged and separable form of the prepositional prefix;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6631}/H9023/[H3318]', 'inflected', 'heb', 'צֶאֱצָא', '["tseʼĕtsâʼ"]', '["and/ descendants/ his"]', '["n-m"]', 'issue, i.e. produce, children that which cometh forth (out), offspring.', 'from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8300}/H9023/[H8277]', 'inflected', 'heb', 'שָׂרִיד', '["sârîyd"]', '["survivors/ his"]', '["n-m"]', 'a survivor × alive, left, remain(-ing), remnant, rest.', 'from 8277;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0490}/H9023/[H488]', 'inflected', 'heb', 'אַלְמָנָה', '["ʼalmânâh"]', '["and/ widows/ his","and/ widows/ its"]', '["n-f"]', 'a widow; also a desolate place desolate house (palace), widow.', 'feminine of 488;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6651}/[H6651]', 'lemma', 'heb', 'צָבַר', '["tsâbar"]', '["he heaps up","he will heap up"]', '["v"]', 'to aggregate gather (together), heap (up), lay up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H2563A}/[H2560]', 'inflected', 'heb', 'חֹמֶר', '["chômer"]', '["and/ like <the>/ clay"]', '["n-m"]', 'properly, a bubbling up, i.e. of water, a wave; of earth, mire or clay (cement); also a heap; hence, a chomer or dry measure clay, heap, homer, mire, motion.', 'from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4403}/[H3847]', 'lemma', 'heb', 'מַלְבּוּשׁ', '["malbûwsh"]', '["clothing"]', '["n-m"]', 'a garment, or (collectively) clothing apparel, raiment, vestment.', 'or מַלְבֻּשׁ; from 3847;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6211A}/[H6244]', 'inflected', 'heb', 'עָשׁ', '["ʻâsh"]', '["[am] like <the>/ moth","like <the>/ moth"]', '["n"]', 'a moth moth. See also 5906.', 'from 6244;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H5521}/[H5520]', 'inflected', 'heb', 'סֻכָּה', '["çukkâh"]', '["and/ like/ a shelter"]', '["n-f"]', 'a hut or lair booth, cottage, covert, pavilion, tabernacle, tent.', 'feminine of 5520;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5381}/H9033/[H5381]', 'inflected', 'heb', 'נָשַׂג', '["nâsag"]', '["[one who] reaches/ it","it overtakes/ him"]', '["v"]', 'to reach (literally or figuratively) ability, be able, attain (unto), (be able to, can) get, lay at, put, reach, remove, wax rich, × surely, (over-) take (hold of, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8175B}/H9033/[H8175]', 'inflected', 'heb', 'שָׂעַר', '["sâʻar"]', '["and/ it will whirl away/ him"]', '["v"]', 'to storm; by implication, to shiver, i.e. fear be (horribly) afraid, fear, hurl as a storm, be tempestuous, come like (take away as with) a whirlwind.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5606A}/[H5606]', 'lemma', 'heb', 'סָפַק', '["çâphaq"]', '["I slapped","he claps","slap","someone will clap","they clap hands","they have clapped"]', '["v"]', 'to clap the hands (in token of compact, derision, grief, indignation, or punishment); by implication of satisfaction, to be enough; by implication of excess, to vomit clap, smite, strike, suffice, wallow.', 'or שָׂפַק; (1 Kings 20:10; Job 27:23; Isaiah 2:6), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8319}/[H8319]', 'inflected', 'heb', 'שָׁרַק', '["shâraq"]', '["and/ he may hiss","so/ he may hiss"]', '["v"]', 'properly, to be shrill, i.e. to whistle or hiss (as a call or in scorn) hiss.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6694}/[H6694]', 'lemma', 'heb', 'צוּק', '["tsûwq"]', '["it poured out","someone pours out"]', '["v"]', 'to pour out, i.e. (figuratively) smelt, utter be molten, pour.', 'a primitive root (identical with through the idea of narrowness (of orifice));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2822}/[H2821]', 'inflected', 'heb', 'חֹשֶׁךְ', '["chôshek"]', '["into/ darkness","to the/ darkness"]', '["n-m"]', 'the dark; hence (literally) darkness; figuratively, misery, destruction, death, ignorance, sorrow, wickedness dark(-ness), night, obscurity.', 'from 2821;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7911}/[H7911]', 'inflected', 'heb', 'שָׁכַח', '["shâkach"]', '["<the>/ forgotten"]', '["v"]', 'to mislay, i.e. to be oblivious of, from want of memory or attention × at all, (cause to) forget.', 'or שָׁכֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1809}/[H1802]', 'lemma', 'heb', 'דָּלַל', '["dâlal"]', '["I had become low","I have become low","it will become low","they are cast down","they hang down","they will be low","we have become low"]', '["v"]', 'to slacken or be feeble; figuratively, to be oppressed bring low, dry up, be emptied, be not equal, fail, be impoverished, be made thin.', 'a primitive root (compare 1802);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8478G}/H9034/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["and/ under/ it"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5861}/[H5860]', 'lemma', 'heb', 'עַיִט', '["ʻayiṭ"]', '["a bird of prey"]', '["n-m"]', 'a hawk or other bird of prey bird, fowl, ravenous (bird).', 'from 5860;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0344}/[H337]', 'lemma', 'heb', 'אַיָּה', '["ʼayâh"]', '["a hawk"]', '["n-f"]', 'the screamer, i.e. a hawk kite, vulture.', 'perhaps from 337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7830>', 'opaque', 'heb', 'שַׁחַץ', '["shachats"]', '["pride"]', '["n-m"]', 'haughtiness (as evinced by the attitude) × lion, pride.', 'from an unused root apparently meaning to strut;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5710A}/[H5710]', 'lemma', 'heb', 'עָדָה', '["ʻâdâh"]', '["[one who] removes","it passes by"]', '["v"]', 'to advance, i.e. pass on or continue; causatively, to remove; specifically, to bedeck (i.e. bring an ornament upon) adorn, deck (self), pass by, take away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2496}/[H2492]', 'inflected', 'heb', 'חַלָּמִישׁ', '["challâmîysh"]', '["on the/ flint"]', '["n-m"]', 'flint flint(-y), rock.', 'probably from 2492 (in the sense of hardness);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8328}/[H8327]', 'inflected', 'heb', 'שֶׁרֶשׁ', '["sheresh"]', '["from/ [the] root","from/ [the] root of"]', '["n-m"]', 'a root (literally or figuratively) bottom, deep, heel, root.', 'from 8327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1065}/[H1058]', 'inflected', 'heb', 'בְּכִי', '["Bᵉkîy"]', '["from/ weeping","more than/ [the] weeping of"]', '["n-m"]', 'a weeping; by analogy, a dripping overflowing, × sore, (continual) weeping, wept.', 'from 1058;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8587}/H9024/[H5956]', 'inflected', 'heb', 'תַּעֲלֻמָּה', '["taʻălummâh"]', '["and/ secret/ her"]', '["n-f"]', 'a secret thing that is hid, secret.', 'from 5956;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0216}\/[H215]', 'inflected', 'heb', 'אוֹר', '["ʼôwr"]', '["light"]', '["n-f"]', 'illumination or (concrete) luminary (in every sense, including lightning, happiness, etc.) bright, clear, day, light (-ning), morning, sun.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2451}/[H2449]', 'inflected', 'heb', 'חׇכְמָה', '["chokmâh"]', '["and/ <the>/ wisdom"]', '["n-f"]', 'wisdom (in a good sense) skilful, wisdom, wisely, wit.', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6187}/H9024/[H6186]', 'inflected', 'heb', 'עֵרֶךְ', '["ʻêrek"]', '["valuation/ its"]', '["n-m"]', 'a pile, equipment, estimate equal, estimation, (things that are set in) order, price, proportion, × set at, suit, taxation, × valuest.', 'from 6186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3220G>', 'inflected', 'heb', 'וים', '["ve./Yam"]', '["and/ [the] sea","and/ sea"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5458}/[H5462]', 'lemma', 'heb', 'סְגוֹר', '["çᵉgôwr"]', '["[the] cavity of","fine gold"]', '["n-m"]', 'properly, shut up, i.e. the breast (as enclosing the heart); also gold (as generally shut up safely) caul, gold.', 'from 5462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4242>/H9024', 'opaque', 'heb', 'מְחִיר', '["mᵉchîyr"]', '["price/ its"]', '["n-m"]', 'price, payment, wages gain, hire, price, sold, worth.', 'from an unused root meaning to buy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5541B}/[H5541]', 'lemma', 'heb', 'סָלָה', '["çâlâh"]', '["it will be paid"]', '["v"]', 'to hang up, i.e. weigh, or (figuratively) contemn tread down (under foot), value.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3800}/[H3799]', 'inflected', 'heb', 'כֶּתֶם', '["kethem"]', '["in/ [the] gold of","in/ gold","with/ [the] gold of"]', '["n-m"]', 'properly, something carved out, i.e. ore; hence, gold (pure as originally mined) ((most) fine, pure) gold(-en wedge).', 'from 3799;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7718>', 'inflected', 'heb', 'בשהם', '["be./Sho.ham"]', '["in/ onyx"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5601}/[H5608]', 'inflected', 'heb', 'סַפִּיר', '["çappîyr"]', '["and/ sapphire"]', '["n-m"]', 'a gem (perhaps used for scratching other substances), probably the sapphire sapphire.', 'from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6186A}/H9034/[H6186]', 'inflected', 'heb', 'עָרַךְ', '["ʻârak"]', '["it will be comparable to/ it"]', '["v"]', 'to set in a row, i.e. arrange, put in order (in a very wide variety of applications) put (set) (the battle, self) in array, compare, direct, equal, esteem, estimate, expert (in war), furnish, handle, join (battle), ordain, (lay, put, reckon up, set) (in) order, prepare, tax, value.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2137}/[H2135]', 'inflected', 'heb', 'זְכוּכִית', '["zᵉkûwkîyth"]', '["and/ glass"]', '["n-f"]', 'properly, transparency, i.e. glass crystal.', 'from 2135;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8545}/H9024/[H4171]', 'inflected', 'heb', 'תְּמוּרָה', '["tᵉmûwrâh"]', '["and/ [is] exchange/ its"]', '["n-f"]', 'barter, compensation (ex-) change(-ing), recompense, restitution.', 'from 4171;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6337}/[H6338]', 'lemma', 'heb', 'פָּז', '["pâz"]', '["pure gold"]', '["n-m"]', 'pure (gold); hence, gold itself (as refined) fine (pure) gold.', 'from 6338;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7215}/[H7213]', 'lemma', 'heb', 'רָאמָה', '["râʼmâh"]', '["corals"]', '["n-f"]', 'something high in value, i.e. perhaps coral coral.', 'from 7213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1378>', 'inflected', 'heb', 'וגביש', '["Ve./ga.vish"]', '["and/ crystal"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4901}/[H4900]', 'inflected', 'heb', 'מֶשֶׁךְ', '["meshek"]', '["and/ [the] price of"]', '["n-m"]', 'a sowing; also a possession precious, price.', 'from 4900;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6443}/[H6434]', 'inflected', 'heb', 'פָּנִין', '["pânîyn"]', '["[is] more than/ pearls","more than/ corals","more than/ jewels"]', '["n-m"]', 'probably a pearl (as round) ruby.', 'or פָּנִי; from the same as 6434;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5541B}\/[H5541]', 'inflected', 'heb', 'סָלָה', '["çâlâh"]', '["it will be paid"]', '["v"]', 'to hang up, i.e. weigh, or (figuratively) contemn tread down (under foot), value.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5775}/[H5774]', 'inflected', 'heb', 'עוֹף', '["ʻôwph"]', '["and/ from/ [the] bird[s] of","and/ more than/ [the] bird[s] of"]', '["n-m"]', 'a bird (as covered with feathers, or rather as covering with wings), often collectively bird, that flieth, flying, fowl.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0011}/[H6]', 'lemma', 'heb', 'אֲבַדּוֹן', '["ʼăbaddôwn"]', '["Abaddon"]', '["n-pr-loc"]', 'abstract, a perishing; concrete, Hades destruction.', 'intensive from 6;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4194}/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["and/ death"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8088B}/H9024/[H8085]', 'inflected', 'heb', 'שֵׁמַע', '["shêmaʻ"]', '["report/ its"]', '["n-m"]', 'something heard, i.e. a sound, rumor, announcement; abstractly, audience bruit, fame, hear(-ing), loud, report, speech, tidings.', 'from 8085;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870J}/H9024/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["way/ its"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7098}/[H7097]', 'inflected', 'heb', 'קָצָה', '["qâtsâh"]', '["to/ [the] ends of"]', '["n"]', 'a termination coast, corner, (selv-) edge, lowest, (uttermost) participle', 'feminine of 7097; (used like 7097)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6213H}/H9043/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["when/ made/ he"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1870L}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["and/ [the] way of","and/ a path"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H2385>', 'inflected', 'heb', 'לחזיז', '["la./cha.Ziz"]', '["for/ [the] storm of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5608A}/H9034/[H5608]', 'inflected', 'heb', 'סָפַר', '["çâphar"]', '["and/ he recounted/ it"]', '["v n-m"]', 'properly, to score with a mark as a tally or record, i.e. (by implication) to inscribe, and also to enumerate; intensively, to recount, i.e. celebrate commune, (ac-) count; declare, number, penknife, reckon, scribe, shew forth, speak, talk, tell (out), writer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3559H}/H9034/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["he established/ it","he will establish/ it"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0998}\/[H995]', 'inflected', 'heb', 'בִּינָה', '["bîynâh"]', '["[is] understanding"]', '["n-f"]', 'understanding knowledge, meaning, × perfectly, understanding, wisdom.', 'from 995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414Q}/H9030/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["will he give/ me"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H3391>', 'inflected', 'heb', 'כירחי', '["khe./yar.chei"]', '["like/ months of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1984A}/H9043/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["when/ made shine/ he"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5216A}/H9023/[H5214]', 'inflected', 'heb', 'נִיר', '["nîyr"]', '["lamp/ his"]', '["n-m"]', 'a lamp (i.e. the burner) or light (literally or figuratively) candle, lamp, light.', 'or נִר; also נֵיר; or נֵר; or (feminine) נֵרָה; from a primitive root (see 5214; 5135) properly, meaning to glisten;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0216}/H9023/[H215]', 'inflected', 'heb', 'אוֹר', '["ʼôwr"]', '["to/ light/ his"]', '["n-f"]', 'illumination or (concrete) luminary (in every sense, including lightning, happiness, etc.) bright, clear, day, light (-ning), morning, sun.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2779}/H9020/[H2778]', 'inflected', 'heb', 'חֹרֶף', '["chôreph"]', '["prime/ my"]', '["n-m"]', 'properly, the crop gathered, i.e. (by implication) the autumn (and winter) season; figuratively, ripeness of age cold, winter (-house), youth.', 'from 2778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5475}/[H3245]', 'inflected', 'heb', 'סוֹד', '["çôwd"]', '["in/ [the] assembly of","in/ [the] council of","in/ [the] intimacy of"]', '["n-m"]', 'a session, i.e. company of persons (in close deliberation); by implication, intimacy, consultation, a secret assembly, consel, inward, secret (counsel).', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0168G}/H9020/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["tent/ my","tents/ my"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7364}/[H7364]', 'inflected', 'heb', 'רָחַץ', '["râchats"]', '["when/ bathed"]', '["v"]', 'to lave (the whole or a part of a thing) bathe (self), wash (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1978}/H9020/[H1980]', 'inflected', 'heb', 'הָלִיךְ', '["hâlîyk"]', '["steps/ my"]', '["n-m"]', 'a walk, i.e. (by implication) a step step.', 'from 1980;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2529B}/[H2346]', 'inflected', 'heb', 'חֶמְאָה', '["chemʼâh"]', '["in/ curd<s>"]', '["n-f"]', 'curdled milk or cheese butter.', 'or (shortened) חֵמָה; from the same root as 2346;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6388}/[H6385]', 'lemma', 'heb', 'פֶּלֶג', '["peleg"]', '["[is] streams of","[the] stream of","streams","streams of"]', '["n-m"]', 'a rill (i.e. small channel of water, as in irrigation) river, stream.', 'from 6385;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7176}/[H7136]', 'lemma', 'heb', 'קֶרֶת', '["qereth"]', '["[the] town","a town"]', '["n-f"]', 'a city city.', 'from 7136 in the sense of building;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4186}/H9020/[H3427]', 'inflected', 'heb', 'מוֹשָׁב', '["môwshâb"]', '["seat/ my"]', '["n-m"]', 'a seat; figuratively, a site; abstractly, a session; by extension an abode (the place or the time); by implication, population assembly, dwell in, dwelling(-place), wherein (that) dwelt (in), inhabited place, seat, sitting, situation, sojourning.', 'or מֹשָׁב; from 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3453}/[H3486]', 'inflected', 'heb', 'יָשִׁישׁ', '["yâshîysh"]', '["and/ old [men]"]', '["a"]', 'an old man (very) aged (man), ancient, very old.', 'from 3486;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6310G}/H9028/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["to/ mouth/ their"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3956G}/H9028/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["and/ tongue/ their"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2441}/H9028/[H2596]', 'inflected', 'heb', 'חֵךְ', '["chêk"]', '["to/ palate/ their"]', '["n-m"]', 'properly, the palate or inside of the mouth; hence, the mouth itself (as the organ of speech, taste and kissing) (roof of the) mouth, taste.', 'probably from 2596 in the sense of tasting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0833}/H9030/[H833]', 'inflected', 'heb', 'אָשַׁר', '["ʼâshar"]', '["and/ it called blessed/ me"]', '["v"]', 'to be straight (used in the widest sense, especially to be level, right, happy); figuratively, to go forward, be honest, prosper (call, be) bless(-ed, happy), go, guide, lead, relieve.', 'or אָשֵׁר; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5749B}/H9030/[H5749]', 'inflected', 'heb', 'עוּד', '["ʻûwd"]', '["and/ it bore witness to/ me"]', '["v"]', 'to duplicate or repeat; by implication, to protest, testify (as by reiteration); intensively, to encompass, restore (as a sort of reduplication) admonish, charge, earnestly, lift up, protest, call (take) to record, relieve, rob, solemnly, stand upright, testify, give warning, (bear, call to, give, take to) witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3847}/H9030/[H3847]', 'inflected', 'heb', 'לָבַשׁ', '["lâbash"]', '["and/ it clothed/ me"]', '["v"]', 'properly, wrap around, i.e. (by implication) to put on a garment or clothe (oneself, or another), literally or figuratively (in) apparel, arm, array (self), clothe (self), come upon, put (on, upon), wear.', 'or לָבֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4598}/[H4603]', 'inflected', 'heb', 'מְעִיל', '["mᵉʻîyl"]', '["[was] like/ a robe","like <the>/ robe"]', '["n-m"]', 'a robe (i.e. upper and outer garment) cloke, coat, mantle, robe.', 'from 4603 in the sense of covering;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6797}/[H6801]', 'inflected', 'heb', 'צָנִיף', '["tsânîyph"]', '["and/ a headdress of","and/ a turban"]', '["n-m"]', 'a head-dress (i.e. piece of cloth wrapped around) diadem, hood, mitre.', 'or צָנוֹף; or (feminine) צָנִיפָה; from 6801;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5787}/[H5786]', 'inflected', 'heb', 'עִוֵּר', '["ʻivvêr"]', '["to the/ blind"]', '["a"]', 'blind (literally or figuratively) blind (men, people).', 'intensive from 5786;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6455}/[H6452]', 'inflected', 'heb', 'פִּסֵּחַ', '["piççêach"]', '["to the/ lame"]', '["a"]', 'lame lame.', 'from 6452;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2713}/H9033/[H2713]', 'inflected', 'heb', 'חָקַר', '["châqar"]', '["I investigated/ it","he examines thoroughly/ him"]', '["v"]', 'properly, to penetrate; hence, to examine intimately find out, (make) search (out), seek (out), sound, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7665}/H9012/[H7665]', 'inflected', 'heb', 'שָׁבַר', '["shâbar"]', '["and/ I broke/ !"]', '["v"]', 'to burst (literally or figuratively) break (down, off, in pieces, up), broken (-hearted), bring to the birth, crush, destroy, hurt, quench, × quite, tear, view (by mistake for 7663).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4973}/[H3216]', 'lemma', 'heb', 'מְתַלְּעָה', '["mᵉthallᵉʻâh"]', '["[the] jaws of"]', '["n-f"]', 'properly, a biter, i.e. a tooth cheek (jaw) tooth, jaw.', 'contr. from 3216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H8127G}/H9023/[H8150]', 'inflected', 'heb', 'שֵׁן', '["shên"]', '["and/ from/ teeth/ his"]', '["n-f"]', 'a tooth (as sharp); specifically ivory; figuratively, a cliff crag, × forefront, ivory, × sharp, tooth.', 'from 8150; compare 8143');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7064}/H9020/[H7077]', 'inflected', 'heb', 'קֵן', '["qên"]', '["nest/ my"]', '["n-m"]', 'a nest (as fixed), sometimes including the nestlings; figuratively, a chamber or dwelling nest, room.', 'contracted from 7077;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8328}/H9020/[H8327]', 'inflected', 'heb', 'שֶׁרֶשׁ', '["sheresh"]', '["root/ my"]', '["n-m"]', 'a root (literally or figuratively) bottom, deep, heel, root.', 'from 8327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2919}/[H2926]', 'inflected', 'heb', 'טַל', '["ṭal"]', '["and/ dew"]', '["n-m"]', 'dew (as covering vegetation) dew.', 'from 2926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7105B}/H9020/[H7114]', 'inflected', 'heb', 'קָצִיר', '["qâtsîyr"]', '["on/ branch[es]/ my"]', '["n-m"]', 'severed, i.e. harvest (as reaped), the crop, the time, the reaper, or figuratively; also a limb (of a tree, or simply foliage) bough, branch, harvest (man).', 'from 7114;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7198}/H9020/[H7185]', 'inflected', 'heb', 'קֶשֶׁת', '["qesheth"]', '["and/ bow/ my"]', '["n-f"]', 'a bow, for shooting (hence, figuratively, strength) or the iris × arch(-er), arrow, bow(-man, -shot).', 'from 7185 in the original sense (of 6983) of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3176G}/[H3176]', 'inflected', 'heb', 'יָחַל', '["yâchal"]', '["and/ they waited"]', '["v"]', 'to wait; by implication, to be patient, hope (cause to, have, make to) hope, be pained, stay, tarry, trust, wait.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1826H}/[H1724]', 'inflected', 'heb', 'דָּמַם', '["dâmam"]', '["and/ I have made quiet","and/ be silent","and/ let him be silent","and/ they may be silent"]', '["v"]', 'to be dumb; by implication, to be astonished, to stop; also to perish cease, be cut down (off), forbear, hold peace, quiet self, rest, be silent, keep (put to) silence, be (stand) still, tarry, wait.', 'a primitive root (compare 1724, 1820);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6098}/H9020/[H3289]', 'inflected', 'heb', 'עֵצָה', '["ʻêtsâh"]', '["advice/ my","counsel/ my","purpose/ my"]', '["n-f"]', 'advice; by implication, plan; also prudence advice, advisement, counsel([-lor]), purpose.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6310G}/H9028/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["and/ mouth/ their"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4456}/[H3953]', 'inflected', 'heb', 'מַלְקוֹשׁ', '["malqôwsh"]', '["for/ spring rain"]', '["n-m"]', 'the spring rain; figuratively, eloquence latter rain.', 'from 3953; (compare 3954)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0216}/[H215]', 'inflected', 'heb', 'אוֹר', '["ʼôwr"]', '["and/ [the] light of","and/ a light","and/ light"]', '["n-f"]', 'illumination or (concrete) luminary (in every sense, including lightning, happiness, etc.) bright, clear, day, light (-ning), morning, sun.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5307G}/H9013/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["they made fall/ !"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1416}/[H1413]', 'inflected', 'heb', 'גְּדוּד', '["gᵉdûwd"]', '["among the/ troop[s]"]', '["n-m"]', 'a crowd (especially of soldiers) army, band (of men), company, troop (of robbers).', 'from 1413;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3117H>', 'inflected', 'heb', 'לימים', '["le./Ya.Mim","le./ya.Mim"]', '["to/ days"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7896G}/[H7896]', 'inflected', 'heb', 'שִׁית', '["shîyth"]', '["to/ put"]', '["v"]', 'to place (in a very wide application) apply, appoint, array, bring, consider, lay (up), let alone, × look, make, mark, put (on), regard, set, shew, be stayed, × take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3624>', 'opaque', 'heb', 'כֶּלַח', '["kelach"]', '["vigor"]', '["n-m"]', 'maturity full (old) age.', 'from an unused root meaning to be complete;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2639}/[H2637]', 'inflected', 'heb', 'חֶסֶר', '["cheçer"]', '["in/ poverty"]', '["n-m"]', 'lack; hence, destitution poverty, want.', 'from 2637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3720}/[H3719]', 'inflected', 'heb', 'כָּפָן', '["kâphân"]', '["and/ in/ hunger"]', '["n-m"]', 'hunger (as making to stoop with emptiness and pain) famine.', 'from 3719;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6207}/[H6207]', 'inflected', 'heb', 'עָרַק', '["ʻâraq"]', '["the/ [ones who] gnaw"]', '["v"]', 'to gnaw, i.e. (figuratively) eat (by hyberbole); also (participle) a pain fleeing, sinew.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7722B>', 'opaque', 'heb', 'שׁוֹא', '["shôwʼ"]', '["destruction","devastation","ruin"]', '["n-m n-f"]', 'a tempest; by implication, devastation desolate(-ion), destroy, destruction, storm, wasteness.', 'or (feminine) שׁוֹאָה; or שֹׁאָה; from an unused root meaning to rush over;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4875}/[H7722]', 'inflected', 'heb', 'מְשׁוֹאָה', '["mᵉshôwʼâh"]', '["and/ desolation"]', '["n-f"]', '(a) ruin, abstractly (the act) or concretely (the wreck) desolation, waste.', 'or מְשֹׁאָה; from the same as 7722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6998}/[H6998]', 'inflected', 'heb', 'קָטַף', '["qâṭaph"]', '["those/ [who] pluck off"]', '["v"]', 'to strip off crop off, cut down (up), pluck.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4408}/[H4414]', 'lemma', 'heb', 'מַלּוּחַ', '["mallûwach"]', '["mallow"]', '["n-m"]', 'sea-purslain (from its saltness) mallows.', 'from 4414;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3899G}/H9028/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["[for] food/ their","food/ their"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1460B}/[H1342]', 'lemma', 'heb', 'גֵּו', '["gêv"]', '["[the] community"]', '["n-m"]', 'the back; by analogy, the middle among, back, body.', 'from 1342 (corresponding to 1354);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6178}/[H6206]', 'inflected', 'heb', 'עָרוּץ', '["ʻârûwts"]', '["on/ [the] slope of"]', '["a"]', 'feared, i.e. (concretely) a horrible place or chasm cliffs.', 'passive participle of 6206;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3710}/[H3721]', 'inflected', 'heb', 'כֵּף', '["kêph"]', '["and/ rocks"]', '["n-m"]', 'a hollow rock rock.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5101}/[H5101]', 'lemma', 'heb', 'נָהַק', '["nâhaq"]', '["they bray"]', '["v"]', 'to bray (as an ass), scream (from hunger) bray.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2738>', 'opaque', 'heb', 'חָרוּל', '["chârûwl"]', '["nettle[s]","nettles"]', '["n-m"]', 'properly, pointed, i.e. a bramble or other thorny weed nettle.', 'or (shortened) חָרֻל; apparently, a passive participle of an unused root probably meaning to be prickly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5596A}/[H5596]', 'lemma', 'heb', 'סָפַח', '["çâphach"]', '["[you are] pouring out","they are joined together"]', '["v"]', 'properly, to scrape out, but in certain peculiar senses (of removal or association) abiding, gather together, cleave, smite with the scab.', 'or שָׂפַח; (Isaiah 3:17), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5217}/[H5217]', 'lemma', 'heb', 'נָכָא', '["nâkâʼ"]', '["they have been scourged"]', '["v"]', 'to smite, i.e. drive away be viler.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5058}/H9028/[H5059]', 'inflected', 'heb', 'נְגִינָה', '["nᵉgîynâh"]', '["taunt song/ their"]', '["n-f"]', 'properly, instrumental music; by implication, a stringed instrument; by extension, a poem set to music; specifically, an epigram stringed instrument, musick, Neginoth (plural), song.', 'or נְגִינַת; (Psalm 61:title), from 5059;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7536}/[H7556]', 'lemma', 'heb', 'רֹק', '["rôq"]', '["spittle"]', '["n-m"]', 'spittle spit(-ting, -tle).', 'from 7556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3499B}/H9020/[H3498]', 'inflected', 'heb', 'יֶתֶר', '["yether"]', '["string/ my"]', '["n-m"]', 'properly, an overhanging, i.e. (by implication) an excess, superiority, remainder; also a small rope (as hanging free) abundant, cord, exceeding, excellancy(-ent), what they leave, that hath left, plentifully, remnant, residue, rest, string, with.', 'from 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6031B}/H9030/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["and/ he has afflicted/ me"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7448>', 'inflected', 'heb', 'ורסן', '["va./Re.sen","ve./Re.sen"]', '["and/ [the] halter","and/ a halter","and/ halter"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6440H}/H9020/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["from/ before/ me"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6526}/[H6524]', 'lemma', 'heb', 'פִּרְחַח', '["pirchach"]', '["a brood"]', '["n-m"]', 'progeny, i.e. a brood youth.', 'from 6524;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5420}/[H5420]', 'lemma', 'heb', 'נָתַס', '["nâthâç"]', '["they have torn down"]', '["v"]', 'to tear up mar.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1942}/H9020/[H1933]', 'inflected', 'heb', 'הַוָּה', '["havvâh"]', '["to/ destruction/ my"]', '["n-f"]', 'by implication, of falling); desire; also ruin calamity, iniquity, mischief, mischievous (thing), naughtiness, naughty, noisome, perverse thing, substance, very wickedness.', 'from 1933 (in the sense of eagerly coveting and rushing upon;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7307H}/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["like the/ wind","like/ a wind of"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5082}/H9020/[H5081]', 'inflected', 'heb', 'נְדִיבָה', '["nᵉdîybâh"]', '["dignity/ my"]', '["n-f"]', 'properly, nobility, i.e. reputation soul.', 'feminine of 5081;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H5645}/[H5743]', 'inflected', 'heb', 'עָב', '["ʻâb"]', '["and/ like/ a cloud"]', '["n-m"]', 'properly, an envelope, i.e. darkness (or density, 2 Chronicles 4:17); specifically, a (scud) cloud; also a copse clay, (thick) cloud, × thick, thicket. Compare 5672.', '(masculine and feminine); from 5743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3444}/H9020/[H3467]', 'inflected', 'heb', 'יְשׁוּעָה', '["yᵉshûwʻâh"]', '["[is] salvation/ my","prosperity/ my","salvation/ my"]', '["n-f"]', 'something saved, i.e. (abstractly) deliverance; hence, aid, victory, prosperity deliverance, health, help(-ing), salvation, save, saving (health), welfare.', 'feminine passive participle of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6207}/H9030/[H6207]', 'inflected', 'heb', 'עָרַק', '["ʻâraq"]', '["and/ gnawing [pains]/ my"]', '["v"]', 'to gnaw, i.e. (figuratively) eat (by hyberbole); also (participle) a pain fleeing, sinew.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7901H}/H9013/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["they rest/ !"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3830}/H9020/[H3847]', 'inflected', 'heb', 'לְבוּשׁ', '["lᵉbûwsh"]', '["clothing/ my"]', '["n-m"]', 'a garment (literally or figuratively); by implication (euphemistically) a wife apparel, clothed with, clothing, garment, raiment, vestment, vesture.', 'or לְבֻשׁ; from 3847;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6310H}/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["like/ [the] mouth of"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3801>/H9020', 'opaque', 'heb', 'כְּתֹנֶת', '["kᵉthôneth"]', '["tunic/ my"]', '["n-f"]', 'a shirt coat, garment, robe.', 'or כֻּתֹּנֶת; from an unused root meaning to cover (compare 3802);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0247}/H9030/[H247]', 'inflected', 'heb', 'אָזַר', '["ʼâzar"]', '["he girds about/ me"]', '["v"]', 'to belt bind (compass) about, gird (up, with).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3384A}/H9030/[H3384]', 'inflected', 'heb', 'יָרָה', '["yârâh"]', '["he has thrown/ me"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4911A}/[H4912]', 'inflected', 'heb', 'מָשַׁל', '["mâshal"]', '["and/ I have become like","and/ I will be equal"]', '["v"]', 'to liken, i.e. (transitively) to use figurative language (an allegory, adage, song or the like); intransitively, to resemble be(-come) like, compare, use (as a) proverb, speak (in proverbs), utter.', 'denominative from 4912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0393>', 'inflected', 'heb', 'לאכזר', '["le./''akh.Zar"]', '["[has become] <into>/ cruel","into/ [one] cruel"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6108}/[H6105]', 'inflected', 'heb', 'עֹצֶם', '["ʻôtsem"]', '["with/ [the] might of"]', '["n-m"]', 'power; hence, body might, strong, substance.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7852}/H9030/[H7852]', 'inflected', 'heb', 'שָׂטַם', '["sâṭam"]', '["they are hostile to/ me","you are hostile to/ me"]', '["v"]', 'properly, to lurk for, i.e. persecute hate, oppose self against.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375G}/H9030/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["it lifted up/ me","pick up/ me","you have picked up/ me","you lift up/ me"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7392}/H9030/[H7392]', 'inflected', 'heb', 'רָכַב', '["râkab"]', '["you make ride/ me"]', '["v"]', 'to ride (on an animal or in a vehicle); causatively, to place upon (for riding or generally), to despatch bring (on (horse-) back), carry, get (oneself) up, on (horse-) back, put, (cause to, make to) ride (in a chariot, on, -r), set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4127}/H9030/[H4127]', 'inflected', 'heb', 'מוּג', '["mûwg"]', '["and/ you dissolve/ me"]', '["v"]', 'to melt, i.e. literally (to soften, flow down, disappear), or figuratively (to fear, faint) consume, dissolve, (be) faint(-hearted), melt (away), make soft.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5856}/[H5753]', 'inflected', 'heb', 'עִי', '["ʻîy"]', '["on/ a heap of ruins"]', '["n-m"]', 'a ruin (as if overturned) heap.', 'from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6365>/H9023', 'inflected', 'heb', 'בפידו', '["be./fi.D/o"]', '["in/ disaster/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7769}/[H7768]', 'lemma', 'heb', 'שׁוּעַ', '["shûwaʻ"]', '["a cry for help"]', '["n-m"]', 'a halloo cry, riches.', 'from 7768;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7186}/[H7185]', 'inflected', 'heb', 'קָשֶׁה', '["qâsheh"]', '["for/ [the] hard of"]', '["a"]', 'severe (in various applications) churlish, cruel, grievous, hard((-hearted), thing), heavy, impudent, obstinate, prevailed, rough(-ly), sore, sorrowful, stiff(necked), stubborn, in trouble.', 'from 7185;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5701}/[H5701]', 'lemma', 'heb', 'עָגַם', '["ʻâgam"]', '["was it grieved?"]', '["v"]', 'to be sad grieve.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3176H}/[H3176]', 'inflected', 'heb', 'יָחַל', '["yâchal"]', '["and/ I waited"]', '["v"]', 'to wait; by implication, to be patient, hope (cause to, have, make to) hope, be pained, stay, tarry, trust, wait.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4578>/H9020', 'opaque', 'heb', 'מֵעֶה', '["mêʻeh"]', '["inward parts/ my"]', '["n-m"]', 'used only in plural the intestines, or (collectively) the abdomen, figuratively, sympathy; by implication, a vest; by extension the stomach, the uterus (or of men, the seat of generation), the heart (figuratively) belly, bowels, × heart, womb.', 'from an unused root probably meaning to be soft;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7570}/[H7570]', 'lemma', 'heb', 'רָתַח', '["râthach"]', '["it makes boil","make boil","they have been made to boil"]', '["v"]', 'to boil boil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2535}/[H2525]', 'lemma', 'heb', 'חַמָּה', '["chammâh"]', '["sun"]', '["n-f"]', 'heat; by implication, the sun heat, sun.', 'from 2525;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8577A}/[H8565]', 'inflected', 'heb', 'תַּנִּין', '["tannîyn"]', '["for/ jackals of","of/ jackals"]', '["n-m"]', 'a marine or land monster, i.e. sea-serpent or jackal dragon, sea-monster, serpent, whale.', 'or תַּנִּים; (Ezekiel 29:3), intensive from the same as 8565;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7453}/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["and/ [the] neighbor of","and/ a companion","and/ a friend"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3284}/[H3283]', 'lemma', 'heb', 'יַעֲנָה', '["yaʻănâh"]', '["an ostrich"]', '["n-f"]', 'owl.', 'feminine of 3283, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7835}/[H7836]', 'lemma', 'heb', 'שָׁחַר', '["shâchar"]', '["it has become black"]', '["v"]', 'to be dim or dark (in color) be black.', 'a primitive root (identical with 7836 through the idea of the duskiness of early dawn);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6106G}/H9020/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["and/ bone/ my","and/ bones/ my"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2787}/[H2787]', 'lemma', 'heb', 'חָרַר', '["chârar"]', '["it has become parched","it has burned","it is charred","it puffs","let them be charred","they have been burned","they have diminished"]', '["v"]', 'to glow, i.e. literally (to melt, burn, dry up) or figuratively (to show or incite passion) be angry, burn, dry, kindle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3658>/H9020', 'opaque', 'heb', 'כִּנּוֹר', '["kinnôwr"]', '["harp/ my"]', '["n-m"]', 'a harp harp.', 'from a unused root meaning to twang;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5748}/H9020/[H5689]', 'inflected', 'heb', 'עוּגָב', '["ʻûwgâb"]', '["and/ flute/ my"]', '["n-m"]', 'a reed-instrument of music organ.', 'or עֻגָּב; from 5689 in the original sense of breathing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5869A}/H9020/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["to/ eyes/ my"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5767}/[H5765]', 'inflected', 'heb', 'עַוָּל', '["ʻavvâl"]', '["[belong] to/ an evil-doer"]', '["n-m"]', 'evil (morally) unjust, unrighteous, wicked.', 'intensive from 5765;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5235}/[H5234]', 'inflected', 'heb', 'נֶכֶר', '["neker"]', '["and/ misfortune"]', '["n-m"]', 'something strange, i.e. unexpected calamity strange.', 'or נֹכֶר; from 5234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6466}/[H6466]', 'inflected', 'heb', 'פָּעַל', '["pâʻal"]', '["for/ [those who] do","to/ [those who] do"]', '["v"]', 'to do or make (systematically and habitually), especially to practise commit, (evil-) do(-er), make(-r), ordain, work(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8254}/H9030/[H8254]', 'inflected', 'heb', 'שָׁקַל', '["shâqal"]', '["let him weigh/ me"]', '["v"]', 'to suspend or poise (especially in trade) pay, receive(-r), spend, × throughly, weigh.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0838B}/H9020/[H833]', 'inflected', 'heb', 'אָשֻׁר', '["ʼâshur"]', '["step/ my"]', '["n-f"]', 'a step going, step.', 'or אַשֻּׁר; from 833 in the sense of going;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3709G}/H9020/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["and/ to/ hands/ my"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3971A>\', 'opaque', 'heb', 'מאוּם', '["mʼûwm"]', '["a blemish"]', '["n-m"]', 'a blemish (physically or morally) blemish, blot, spot.', 'usually מוּם; as if passive participle from an unused root probably meaning to stain');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0312}/[H309]', 'inflected', 'heb', 'אַחֵר', '["ʼachêr"]', '["and/ another"]', '["a"]', 'properly, hinder; generally, next, other, etc. (an-) other man, following, next, strange.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6631}/H9020/[H3318]', 'inflected', 'heb', 'צֶאֱצָא', '["tseʼĕtsâʼ"]', '["and/ produce<s>/ my"]', '["n-m"]', 'issue, i.e. produce, children that which cometh forth (out), offspring.', 'from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3766}/H9013/[H3766]', 'inflected', 'heb', 'כָּרַע', '["kâraʻ"]', '["let them bow down/ !"]', '["v"]', 'to bend the knee; by implication, to sink, to prostrate bow (down, self), bring down (low), cast down, couch, fall, feeble, kneeling, sink, smite (stoop) down, subdue, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8393}/H9020/[H935]', 'inflected', 'heb', 'תְּבוּאָה', '["tᵉbûwʼâh"]', '["produce/ my"]', '["n-f"]', 'income, i.e. produce (literally or figuratively) fruit, gain, increase, revenue.', 'from 935;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7379}/H9028/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["in/ complaint/ their"]', '["n-m"]', 'a contest (personal or legal) adversary, cause, chiding, contend(-tion), controversy, multitude (from the margin), pleading, strife, strive(-ing), suit.', 'or רִב; from 7378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725M}/H9033/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["I will respond to/ him","will I respond to/ him"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0990H>', 'inflected', 'heb', 'בבטן', '["Va./be.ten","ba./Be.ten","be./Ve.ten","va./Be.ten"]', '["in the/ belly","in the/ womb","in/ [the] womb of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3559I}/H9033/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["and/ did prepare us?/ he"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7358}/[H7355]', 'inflected', 'heb', 'רֶחֶם', '["rechem"]', '["in the/ womb"]', '["n-m"]', 'the womb matrix, womb.', 'from 7355; (compare 7356)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2656}/[H2654]', 'inflected', 'heb', 'חֵפֶץ', '["chêphets"]', '["any of/ [the] desire of"]', '["n-m"]', 'pleasure; hence (abstractly) desire; concretely, a valuable thing; hence (by extension) a matter (as something in mind) acceptable, delight(-some), desire, things desired, matter, pleasant(-ure), purpose, willingly.', 'from 2654;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6595A}/H9020/[H6626]', 'inflected', 'heb', 'פַּת', '["path"]', '["morsel of bread/ my"]', '["n-f"]', 'a bit meat, morsel, piece.', 'from 6626;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1431}/H9030/[H1434]', 'inflected', 'heb', 'גָּדַל', '["gâdal"]', '["he grew up with/ me"]', '["v"]', 'to be (causatively make) large (in various senses, as in body, mind, estate or honor, also in pride) advance, boast, bring up, exceed, excellent, be(-come, do, give, make, wax), great(-er, come to... estate, things), grow(up), increase, lift up, magnify(-ifical), be much set by, nourish (up), pass, promote, proudly (spoken), tower.', 'a primitive root; properly, to twist (compare 1434), i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0001G}/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["like/ a father"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H0990H>', 'inflected', 'heb', 'ומבטן', '["u./mi./Be.ten"]', '["and/ from/ [the] womb of","and/ from/ womb"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5148}/H9034/[H5148]', 'inflected', 'heb', 'נָחָה', '["nâchâh"]', '["I guided/ her"]', '["v"]', 'to guide; by implication, to transport (into exile, or as colonists) bestow, bring, govern, guide, lead (forth), put, straiten.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2504}/H9023/[H2502]', 'inflected', 'heb', 'חָלָץ', '["châlâts"]', '["loins/ his","loins/ its"]', '["n-f"]', 'the loins (as the seat of vigor) loins, reins.', 'from 2502 (in the sense of strength); only in the dual;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1488}/[H1494]', 'inflected', 'heb', 'גֵּז', '["gêz"]', '["and/ from/ [the] fleece of"]', '["n-m"]', 'a fleece (as shorn); also mown grass fleece, mowing, mown grass.', 'from 1494;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3532>/H9020', 'opaque', 'heb', 'כֶּבֶשׂ', '["kebes"]', '["lambs/ my"]', '["n-m"]', 'a ram (just old enough to butt) lamb, sheep.', 'from an unused root meaning to dominate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3802>/H9020', 'opaque', 'heb', 'כָּתֵף', '["kâthêph"]', '["shoulder/ my"]', '["n-f"]', 'the shoulder (proper, i.e. upper end of the arm; as being the spot where the garments hang); figuratively, side-piece or lateral projection of anything arm, corner, shoulder(-piece), side, undersetter.', 'from an unused root meaning to clothe;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7929}/H9011/[H7926]', 'inflected', 'heb', 'שִׁכְמָה', '["shikmâh"]', '["from/ its shoulder/ <towards>"]', '["n-f"]', 'the shoulderbone shoulder blade.', 'feminine of 7926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0248}/H9020/[H2220]', 'inflected', 'heb', 'אֶזְרוֹעַ', '["ʼezrôwaʻ"]', '["and/ arm/ my"]', '["n-f"]', 'the arm arm.', 'a variation for 2220;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7070J}/H9024/[H7069]', 'inflected', 'heb', 'קָנֶה', '["qâneh"]', '["from/ arm/ its"]', '["n-m"]', 'a reed (as erect); by resemblance a rod (especially for measuring), shaft, tube, stem, the radius (of the arm), beam (of a steelyard) balance, bone, branch, calamus, cane, reed, × spearman, stalk.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H7613}/H9023/[H5375]', 'inflected', 'heb', 'שְׂאֵת', '["sᵉʼêth"]', '["and/ from/ majesty/ his"]', '["n-f"]', 'an elevation or leprous scab; figuratively, elation or cheerfulness; exaltation in rank or character be accepted, dignity, excellency, highness, raise up self, rising.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3689}/H9020/[H3688]', 'inflected', 'heb', 'כֶּסֶל', '["keçel"]', '["confidence/ my","loins/ my"]', '["n-m"]', 'properly, fatness, i.e. by implication (literally) the loin (as the seat of the leaf fat) or (generally) the viscera; also (figuratively) silliness or (in a good sense) trust confidence, flank, folly, hope, loin.', 'from 3688;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3800}/[H3799]', 'inflected', 'heb', 'כֶּתֶם', '["kethem"]', '["and/ to <the>/ pure gold"]', '["n-m"]', 'properly, something carved out, i.e. ore; hence, gold (pure as originally mined) ((most) fine, pure) gold(-en wedge).', 'from 3799;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4009}/H9020/[H982]', 'inflected', 'heb', 'מִבְטָח', '["mibṭâch"]', '["confidence/ my","security/ my"]', '["n-m"]', 'properly, a refuge, i.e. (objective) security, or (subjective) assurance confidence, hope, sure, trust.', 'from 982;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2428H}/H9020/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["wealth/ my"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1984A}/[H1984]', 'lemma', 'heb', 'הָלַל', '["hâlal"]', '["it flashes forth","it shone","they will flash forth"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6601B}/[H6601]', 'inflected', 'heb', 'פָּתָה', '["pâthâh"]', '["and/ I was deceived","and/ it was gullible"]', '["v"]', 'to open, i.e. be (causatively, make) roomy; usually figuratively (in a mental or moral sense) to be (causatively, make) simple or (in a sinister way) delude allure, deceive, enlarge, entice, flatter, persuade, silly (one).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6310G}/H9020/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["<to>/ mouth/ my","for/ mouth/ my","to/ mouth/ my"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6416}/[H6414]', 'lemma', 'heb', 'פְּלִילִי', '["pᵉlîylîy"]', '["calling for judgment"]', '["a"]', 'judicial judge.', 'from 6414;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6365>', 'inflected', 'heb', 'בפיד', '["be./Fid"]', '["in/ [the] disaster of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1817C}/H9020/[H1802]', 'inflected', 'heb', 'דֶּלֶת', '["deleth"]', '["doors/ my"]', '["n-m n-f"]', 'something swinging, i.e. the valve of a door door (two-leaved), gate, leaf, lid. (Psalm 141:3).', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0734}/[H732]', 'inflected', 'heb', 'אֹרַח', '["ʼôrach"]', '["to the/ path"]', '["n-m"]', 'a well-trodden road (literally or figuratively); also a caravan manner, path, race, rank, traveller, troop, (by-, high-) way.', 'from 732;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0121G}/[H120]', 'inflected', 'heb', 'אָדָם', '["ʼÂdâm"]', '["like/ Adam"]', '["n-pr-m"]', 'Adam the name of the first man, also of a place in Palestine Adam.', 'the same as 120;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2934}/[H2934]', 'inflected', 'heb', 'טָמַן', '["ṭâman"]', '["by/ hiding","to/ hide"]', '["v"]', 'to hide (by covering over) hide, lay privily, in secret.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2243}/H9020/[H2245]', 'inflected', 'heb', 'חֹב', '["chôb"]', '["in/ bosom/ my"]', '["n-m"]', 'properly, a cherisher, i.e. the bosom bosom.', 'by contraction from 2245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0937}/[H936]', 'inflected', 'heb', 'בּוּז', '["bûwz"]', '["and/ [the] contempt of","and/ contempt"]', '["n-m"]', 'disrespect contempt(-uously), despised, shamed.', 'from 936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2865}/H9030/[H2865]', 'inflected', 'heb', 'חָתַת', '["châthath"]', '["it caused to be dismayed/ me"]', '["v"]', 'properly, to prostrate; hence, to break down, either (literally) by violence, or (figuratively) by confusion and fear abolish, affright, be (make) afraid, amaze, beat down, discourage, (cause to) dismay, go down, scare, terrify.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8420}/H9020/[H8427]', 'inflected', 'heb', 'תָּו', '["tâv"]', '["mark/ my"]', '["n-m"]', 'a mark; by implication, a signature desire, mark.', 'from 8427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7926}/H9020/[H7925]', 'inflected', 'heb', 'שְׁכֶם', '["shᵉkem"]', '["shoulder/ my"]', '["n-m"]', 'the neck (between the shoulders) as the place of burdens; figuratively, the spur of a hill back, × consent, portion, shoulder.', 'from 7925;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6029}/H9033/[H6029]', 'inflected', 'heb', 'עָנַד', '["ʻânad"]', '["I will tie on/ it"]', '["v"]', 'to lace fast bind, tie.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5046}/H9033/[H5046]', 'inflected', 'heb', 'נָגַד', '["nâgad"]', '["I will tell to/ him"]', '["v"]', 'properly, to front, i.e. stand boldly out opposite; by implication (causatively), to manifest; figuratively, to announce (always by word of mouth to one present); specifically, to expose, predict, explain, praise bewray, × certainly, certify, declare(-ing), denounce, expound, × fully, messenger, plainly, profess, rehearse, report, shew (forth), speak, × surely, tell, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7126G}/H9033/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["I will approach/ him"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3162A}/[H3161]', 'inflected', 'heb', 'יַחַד', '["yachad"]', '["and/ together"]', '["n-m"]', 'properly, a unit, i.e. (adverb) unitedly alike, at all (once), both, likewise, only, (al-) together, withal.', 'from 3161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8525>/H9024', 'opaque', 'heb', 'תֶּלֶם', '["telem"]', '["furrows/ its"]', '["n-m"]', 'a bank or terrace furrow, ridge.', 'from an unused root meaning to accumulate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1058}/H9013/[H1058]', 'inflected', 'heb', 'בָּכָה', '["bâkâh"]', '["they weep/ !","they wept/ !"]', '["v"]', 'to weep; generally to bemoan × at all, bewail, complain, make lamentation, × more, mourn, × sore, × with tears, weep.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1167G}/H9024/[H1166]', 'inflected', 'heb', 'בַּעַל', '["baʻal"]', '["owners/ its"]', '["n-m"]', 'a master; hence, a husband, or (figuratively) owner (often used with another noun in modifications of this latter sense) archer, babbler, bird, captain, chief man, confederate, have to do, dreamer, those to whom it is due, furious, those that are given to it, great, hairy, he that hath it, have, horseman, husband, lord, man, married, master, person, sworn, they of.', 'from 1166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2336>', 'opaque', 'heb', 'חוֹחַ', '["chôwach"]', '["thorn[s]"]', '["n-m"]', 'a thorn; by analogy, a ring for the nose bramble, thistle, thorn.', 'from an unused root apparently meaning to pierce;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8478H}/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["and/ in place of"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0890}/[H889]', 'lemma', 'heb', 'בׇּאְשָׁה', '["boʼshâh"]', '["foul weed[s]"]', '["n-f"]', 'stink-weed or any other noxious or useless plant cockle.', 'feminine of 889;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0347}\/[H340]', 'inflected', 'heb', 'אִיּוֹב', '["ʼÎyôwb"]', '["Job"]', '["n-pr-m"]', 'Ijob, the patriarch famous for his patience Job.', 'from 340; hated (i.e. persecuted);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6030B}/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["from/ answering"]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869A}/H9023\/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ own eyes/ his"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0453K}/[H410]', 'lemma', 'heb', 'אֱלִיהוּ', '["ʼĔlîyhûw"]', '["Elihu"]', '["n-pr-m"]', 'Elihu, the name of one of Job''s friends, and of three Israelites Elihu.', 'or (fully) אֱלִיהוּא; from 410 and 1931; God of him;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1292}/[H1288]', 'lemma', 'heb', 'בָּרַכְאֵל', '["Bârakʼêl"]', '["Barakel"]', '["n-pr-m"]', 'Barakel, the father of one of Job''s friends Barachel.', 'from 1288 and 410, God has blessed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0940}/[H938]', 'inflected', 'heb', 'בּוּזִי', '["Bûwzîy"]', '["the/ Buzite"]', '["a"]', 'a Buzite or descendant of Buz Buzite.', 'patronymic from 938;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7410I}/[H7311]', 'lemma', 'heb', 'רָם', '["Râm"]', '["Ram"]', '["n-pr-m"]', 'Ram, the name of an Arabian and of an Israelite Ram. See also 1027.', 'active participle of 7311; high;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0347}/[H340]', 'inflected', 'heb', 'אִיּוֹב', '["ʼÎyôwb"]', '["on/ Job"]', '["n-pr-m"]', 'Ijob, the patriarch famous for his patience Job.', 'from 340; hated (i.e. persecuted);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6663}/H9043/[H6663]', 'inflected', 'heb', 'צָדַק', '["tsâdaq"]', '["justified/ he"]', '["v"]', 'to be (causatively, make) right (in a moral or forensic sense) cleanse, clear self, (be, do) just(-ice, -ify, -ify self), (be turn to) righteous(-ness).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4617}/[H6030]', 'lemma', 'heb', 'מַעֲנֶה', '["maʻăneh"]', '["[the] answer of","[was] an answer","[will be] an answer of","an answer"]', '["n-m"]', 'a reply (favorable or contradictory) answer, × himself.', 'from 6030;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0453K}/[H410]', 'inflected', 'heb', 'אֱלִיהוּ', '["ʼĔlîyhûw"]', '["and/ Elihu"]', '["n-pr-m"]', 'Elihu, the name of one of Job''s friends, and of three Israelites Elihu.', 'or (fully) אֱלִיהוּא; from 410 and 1931; God of him;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0639G}/H9023\/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["anger/ his"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2119B}/[H2119]', 'lemma', 'heb', 'זָחַל', '["zâchal"]', '["I was anxious"]', '["v"]', 'to crawl; by implication, to fear be afraid, serpent, worm.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2331}/[H2324]', 'inflected', 'heb', 'חָוָה', '["châvâh"]', '["from/ telling"]', '["v"]', 'properly, to live; by implication (intensively) to declare or show show.', 'a primitive root; (compare 2324, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1843}/H9020/[H3045]', 'inflected', 'heb', 'דֵּעַ', '["dêaʻ"]', '["knowledge/ my"]', '["n-m"]', 'knowledge knowledge, opinion.', 'from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0995}/H9038/[H995]', 'inflected', 'heb', 'בִּין', '["bîyn"]', '["[which] it gives understanding/ them"]', '["v"]', 'to separate mentally (or distinguish), i.e.(generally) understand attend, consider, be cunning, diligently, direct, discern, eloquent, feel, inform, instruct, have intelligence, know, look well to, mark, perceive, be prudent, regard, (can) skill(-full), teach, think, (cause, make to, get, give, have) understand(-ing), view, (deal) wise(-ly, man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2205H}/[H2204]', 'inflected', 'heb', 'זָקֵן', '["zâqên"]', '["and/ an old [person]","and/ old [men]","and/ old [people]","and/ old [person]","and/ old [women]"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8085G}/H9012/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["hear/ !","listen/ !"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2331}/[H2324]', 'lemma', 'heb', 'חָוָה', '["châvâh"]', '["I will tell","it shows forth"]', '["v"]', 'properly, to live; by implication (intensively) to declare or show show.', 'a primitive root; (compare 2324, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1697G}/H9026/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["for/ words/ your"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8394}/H9026/[H995]', 'inflected', 'heb', 'תָּבוּן', '["tâbûwn"]', '["understanding<s>/ your"]', '["n-m"]', 'intelligence; by implication, an argument; by extension, caprice discretion, reason, skilfulness, understanding, wisdom.', 'and (feminine) תְּבוּנָה; or תּוֹבֻנָה; from 995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2713}/H9013/[H2713]', 'inflected', 'heb', 'חָקַר', '["châqar"]', '["you searched for/ !"]', '["v"]', 'properly, to penetrate; hence, to examine intimately find out, (make) search (out), seek (out), sound, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5704}/H9036/[H5703]', 'inflected', 'heb', 'עַד', '["ʻad"]', '["and/ to/ you"]', '["prep"]', 'as far (or long, or much) as, whether of space (even unto) or time (during, while, until) or degree (equally with) against, and, as, at, before, by (that), even (to), for(-asmuch as), (hither-) to, how long, into, as long (much) as, (so) that, till, toward, until, when, while, ( as) yet.', 'properly, the same as 5703 (used as a preposition, adverb or conjunction; especially with a preposition);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0347}/[H340]', 'inflected', 'heb', 'אִיּוֹב', '["ʼÎyôwb"]', '["<to>/ Job","[belonged] to/ Job"]', '["n-pr-m"]', 'Ijob, the patriarch famous for his patience Job.', 'from 340; hated (i.e. persecuted);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4480A}/H9036/[H4482]', 'inflected', 'heb', 'מִן', '["min"]', '["any of/ you"]', '["prep"]', 'properly, a part of; hence (prepositionally), from or out of in many senses above, after, among, at, because of, by (reason of), from (among), in, × neither, × nor, (out) of, over, since, × then, through, × whether, with.', 'or מִנִּי; or מִנֵּי; (constructive plural) (Isaiah 30:11); for 4482;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5086}/H9033/[H5086]', 'inflected', 'heb', 'נָדַף', '["nâdaph"]', '["it drives about/ it","let him drive about/ him"]', '["v"]', 'to shove asunder, i.e. disperse drive (away, to and fro), thrust down, shaken, tossed to and fro.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0561}/H9026/[H559]', 'inflected', 'heb', 'אֵמֶר', '["ʼêmer"]', '["and/ with/ words/ your"]', '["n-m"]', 'something said answer, × appointed unto him, saying, speech, word.', 'from 559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2506A}/H9020/[H2505]', 'inflected', 'heb', 'חֵלֶק', '["chêleq"]', '["[is] portion/ my","part/ my","portion/ my","possession/ my","reward/ my"]', '["n-m"]', 'properly, smoothness (of the tongue); also an allotment flattery, inheritance, part, × partake, portion.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6693}/H9030/[H6693]', 'inflected', 'heb', 'צוּק', '["tsûwq"]', '["it has constrained/ me"]', '["v"]', 'to compress, i.e. (figuratively) oppress, distress constrain, distress, lie sore, (op-) press(-or), straiten.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0990J>/H9020', 'opaque', 'heb', 'בֶּטֶן', '["beṭen"]', '["belly/ my"]', '["n-f"]', 'the belly, especially the womb; also the bosom or body of anything belly, body, as they be born, within, womb.', 'from an unused root probably meaning to be hollow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0990G>/H9020', 'opaque', 'heb', 'בֶּטֶן', '["beṭen"]', '["belly/ my"]', '["n-f"]', 'the belly, especially the womb; also the bosom or body of anything belly, body, as they be born, within, womb.', 'from an unused root probably meaning to be hollow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H3196>', 'inflected', 'heb', 'כיין', '["ke./Ya.yin","ke./Yein"]', '["[is] like/ wine","[will be] like/ [the] wine of","like/ [the] wine of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0178}/[H1]', 'inflected', 'heb', 'אוֹב', '["ʼôwb"]', '["like/ a necromancer","like/ wineskins"]', '["n-m"]', 'properly, a mumble, i.e. a water-skin (from its hollow sound); hence a necromancer (ventriloquist, as from a jar) bottle, familiar spirit.', 'from the same as 1 (apparently through the idea of prattling a father''s name);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7304}/[H7306]', 'inflected', 'heb', 'רָוַח', '["râvach"]', '["and/ it may be relieved"]', '["v"]', 'properly, to breathe freely, i.e. revive; by implication, to have ample room be refreshed, large.', 'a primitive root (identical with 7306);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6030B}/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["and/ [one who] answers","and/ it testifies","so/ I may answer"]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3655}/[H3655]', 'lemma', 'heb', 'כָּנָה', '["kânâh"]', '["I will use flattery"]', '["v"]', 'to address by an additional name; hence, to eulogize give flattering titles, surname (himself).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2441}/H9020/[H2596]', 'inflected', 'heb', 'חֵךְ', '["chêk"]', '["on/ palate/ my"]', '["n-m"]', 'properly, the palate or inside of the mouth; hence, the mouth itself (as the organ of speech, taste and kissing) (roof of the) mouth, taste.', 'probably from 2596 in the sense of tasting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0561}/H9020/[H559]', 'inflected', 'heb', 'אֵמֶר', '["ʼêmer"]', '["words/ my"]', '["n-m"]', 'something said answer, × appointed unto him, saying, speech, word.', 'from 559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2421}/H9030/[H2331]', 'inflected', 'heb', 'חָיָה', '["châyâh"]', '["it gives life/ me","it has preserved alive/ me","preserve alive/ me","you have preserved alive/ me","you preserve alive/ me","you preserved alive/ me","you will preserve alive/ me"]', '["v"]', 'to live, whether literally or figuratively; causatively, to revive keep (leave, make) alive, × certainly, give (promise) life, (let, suffer to) live, nourish up, preserve (alive), quicken, recover, repair, restore (to life), revive, (× God) save (alive, life, lives), × surely, be whole.', 'a primitive root (compare 2331, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6186A}/H9012/[H6186]', 'inflected', 'heb', 'עָרַךְ', '["ʻârak"]', '["arrange/ !"]', '["v"]', 'to set in a row, i.e. arrange, put in order (in a very wide variety of applications) put (set) (the battle, self) in array, compare, direct, equal, esteem, estimate, expert (in war), furnish, handle, join (battle), ordain, (lay, put, reckon up, set) (in) order, prepare, tax, value.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3320}/H9012/[H3320]', 'inflected', 'heb', 'יָצַב', '["yâtsab"]', '["take your stand/ !"]', '["v"]', 'to place (any thing so as to stay); reflexively, to station, offer, continue present selves, remaining, resort, set (selves), (be able to, can, with-) stand (fast, forth, -ing, still, up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6310K}/H9021/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["[am] like/ mouth/ your"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2563A}/[H2560]', 'inflected', 'heb', 'חֹמֶר', '["chômer"]', '["from/ clay"]', '["n-m"]', 'properly, a bubbling up, i.e. of water, a wave; of earth, mire or clay (cement); also a heap; hence, a chomer or dry measure clay, heap, homer, mire, motion.', 'from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7169}/[H7169]', 'lemma', 'heb', 'קָרַץ', '["qârats"]', '["I was nipped off","[he is] winking","[one who] purses","[one who] winks","let them wink"]', '["v"]', 'to pinch, i.e. (partially) to bite the lips, blink the eyes (as a gesture of malice), or (fully) to squeeze off (a piece of clay in order to mould a vessel from it) form, move, wink.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0405}/H9020/[H404]', 'inflected', 'heb', 'אֶכֶף', '["ʼekeph"]', '["and/ pressure/ my"]', '["n-m"]', 'a load; by implication, a stroke (others dignity) hand.', 'from 404;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2643}/[H2653]', 'lemma', 'heb', 'חַף', '["chaph"]', '["[am] innocent"]', '["a"]', 'pure innocent.', 'from 2653 (in the moral sense of covered from soil);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8569}/[H5106]', 'lemma', 'heb', 'תְּנוּאָה', '["tᵉnûwʼâh"]', '["occasions"]', '["n-f"]', 'alienation; by implication, enmity breach of promise, occasion.', 'from 5106;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2384}/[H2372]', 'lemma', 'heb', 'חִזָּיוֹן', '["chizzâyôwn"]', '["a vision of","vision"]', '["n-m"]', 'a revelation, expectation by dream vision.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8572}/[H5123]', 'inflected', 'heb', 'תְּנוּמָה', '["tᵉnûwmâh"]', '["in/ slumber<s>"]', '["n-f"]', 'drowsiness, i.e. sleep slumber(-ing).', 'from 5123;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4561}/H9028/[H3256]', 'inflected', 'heb', 'מֹסָר', '["môçâr"]', '["and/ with/ discipline/ their"]', '["n-m"]', 'admonition instruction.', 'from 3256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1466}/[H1465]', 'inflected', 'heb', 'גֵּוָה', '["gêvâh"]', '["and/ pride"]', '["n-f"]', 'exaltation; (figuratively) arrogance lifting up, pride.', 'the same as 1465;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1397}/[H1396]', 'inflected', 'heb', 'גֶּבֶר', '["geber"]', '["from/ a man"]', '["n-m"]', 'properly, a valiant man or warrior; generally, a person simply every one, man, × mighty.', 'from 1396;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7845G}/[H7743]', 'lemma', 'heb', 'שַׁחַת', '["shachath"]', '["[the] pit"]', '["n-f"]', 'a pit (especially as a trap); figuratively, destruction corruption, destruction, ditch, grave, pit.', 'from 7743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2416C}/H9023/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["and/ animal[s]/ its","and/ life/ his"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7973}/[H7971]', 'inflected', 'heb', 'שֶׁלַח', '["shelach"]', '["by <the>/ missile","by/ a missile"]', '["n-m"]', 'a missile of attack, i.e. spear; also (figuratively) a shoot of growth; i.e. branch dart, plant, × put off, sword, weapon.', 'from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4341}/[H3510]', 'inflected', 'heb', 'מַכְאֹב', '["makʼôb"]', '["with/ pain"]', '["n-m"]', 'anguish or (figuratively) affliction grief, pain, sorrow.', 'sometimes מַכְאוֹב; also (feminine Isaiah 53:3) מַכְאֹבָה; from 3510;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2092}/H9033/[H2092]', 'inflected', 'heb', 'זָהַם', '["zâham"]', '["and/ it loathes/ it"]', '["v"]', 'to be rancid, i.e. (transitively) to loathe abhor.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2416C}/H9023/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["life/ his"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5315L}/H9023/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["and/ self/ his","and/ throat/ his"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7210}/[H7200]', 'inflected', 'heb', 'רֳאִי', '["rŏʼîy"]', '["from/ sight"]', '["n-m"]', 'sight, whether abstractly (vision) or concretely (a spectacle) gazingstock, look to, (that) see(-th).', 'from 7200;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8192}/[H8192]', 'inflected', 'heb', 'שָׁפָה', '["shâphâh"]', '["and/ they are laid bare"]', '["v"]', 'to abrade, i.e. bare high, stick out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3887}/[H3887]', 'lemma', 'heb', 'לוּץ', '["lûwts"]', '["[is] a mocker","[is] mocker","[the] mocker","a mediator","a mocker","he mocks","mockers","scorners","you show yourself a mocker"]', '["v"]', 'properly, to make mouths at, i.e. to scoff; hence (from the effort to pronounce a foreign language) to interpret, or (generally) intercede ambassador, have in derision, interpreter, make a mock, mocker, scorn(-er, -ful), teacher.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3476}/H9023/[H3474]', 'inflected', 'heb', 'יֹשֶׁר', '["yôsher"]', '["uprightness/ his"]', '["n-m"]', 'the right equity, meet, right, upright(-ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2603A}/H9033/[H2583]', 'inflected', 'heb', 'חָנַן', '["chânan"]', '["and/ he showed favor to/ him"]', '["v"]', 'properly, to bend or stoop in kindness to an inferior; to favor, bestow; causatively to implore (i.e. move to favor by petition) beseech, × fair, (be, find, shew) favour(-able), be (deal, give, grant (gracious(-ly), intreat, (be) merciful, have (shew) mercy (on, upon), have pity upon, pray, make supplication, × very.', 'a primitive root (compare 2583);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6308}/H9033/[H6308]', 'inflected', 'heb', 'פָּדַע', '["pâdaʻ"]', '["deliver/ him"]', '["v"]', 'to retrieve deliver.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7375}/[H7373]', 'lemma', 'heb', 'רֻטֲפַשׁ', '["ruṭăphash"]', '["it grows fresh"]', '["v"]', 'to be rejuvenated be fresh.', 'a root compounded from 7373 and 2954;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5290}/[H5287]', 'inflected', 'heb', 'נֹעַר', '["nôʻar"]', '["from/ youth","more than/ youth"]', '["n-m"]', '(abstractly) boyhood child, youth.', 'from 5287; (compare 5288)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7521}/H9033/[H7521]', 'inflected', 'heb', 'רָצָה', '["râtsâh"]', '["and/ he accepted/ him"]', '["v"]', 'to be pleased with; specifically, to satisfy a debt (be) accept(-able), accomplish, set affection, approve, consent with, delight (self), enjoy, (be, have a) favour(-able), like, observe, pardon, (be, have, take) please(-ure), reconcile self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7789}/[H7789]', 'lemma', 'heb', 'שׁוּר', '["shûwr"]', '["I will watch","he watches"]', '["v"]', 'to spy out, i.e. (generally) survey, (for evil) lurk for, (for good) care for behold, lay wait, look, observe, perceive, regard, see.', 'a primitive root (identical with through the idea of going round for inspection);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5753A}/[H5753]', 'lemma', 'heb', 'עָוָה', '["ʻâvâh"]', '["I am bent down","I am bent over","I have perverted","they have perverted"]', '["v"]', 'to crook, literally or figuratively do amiss, bow down, make crooked, commit iniquity, pervert, (do) perverse(-ly), trouble, × turn, do wickedly, do wrong.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7845G}/[H7743]', 'inflected', 'heb', 'שַׁחַת', '["shachath"]', '["in the/ pit"]', '["n-f"]', 'a pit (especially as a trap); figuratively, destruction corruption, destruction, ditch, grave, pit.', 'from 7743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0216}/[H215]', 'inflected', 'heb', 'אוֹר', '["ʼôwr"]', '["[is] in/ [the] light of","at/ [the] light","by/ [the] light of","in/ [the] light of","on the/ light"]', '["n-f"]', 'illumination or (concrete) luminary (in every sense, including lightning, happiness, etc.) bright, clear, day, light (-ning), morning, sun.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7200K}/[H7200]', 'lemma', 'heb', 'רָאָה', '["râʼâh"]', '["he saw","it will look","see"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6663}/H9031/[H6663]', 'inflected', 'heb', 'צָדַק', '["tsâdaq"]', '["to justify/ you"]', '["v"]', 'to be (causatively, make) right (in a moral or forensic sense) cleanse, clear self, (be, do) just(-ice, -ify, -ify self), (be turn to) righteous(-ness).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0502}/H9031/[H502]', 'inflected', 'heb', 'אָלַף', '["ʼâlaph"]', '["and/ I will teach/ you"]', '["v"]', 'hence, to learn (and causatively to teach) learn, teach, utter.', 'a primitive root, to associate with;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2451}\/[H2449]', 'inflected', 'heb', 'חׇכְמָה', '["chokmâh"]', '["wisdom"]', '["n-f"]', 'wisdom (in a good sense) skilful, wisdom, wisely, wit.', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0996H}/H9035/[H995]', 'inflected', 'heb', 'בֵּין', '["bêyn"]', '["between/ ourselves"]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0605}/[H605]', 'lemma', 'heb', 'אָנַשׁ', '["ʼânash"]', '["[is] incurable","incurable"]', '["v"]', 'to be frail, feeble, or (figuratively) melancholy desperate(-ly wicked), incurable, sick, woeful.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0347}/[H340]', 'inflected', 'heb', 'אִיּוֹב', '["ʼÎyôwb"]', '["like/ Job"]', '["n-pr-m"]', 'Ijob, the patriarch famous for his patience Job.', 'from 340; hated (i.e. persecuted);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3933}/[H3932]', 'lemma', 'heb', 'לַעַג', '["laʻag"]', '["mockery"]', '["n-m"]', 'derision, scoffing derision, scorn (-ing).', 'from 3932;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0732}/[H732]', 'inflected', 'heb', 'אָרַח', '["ʼârach"]', '["and/ he travels"]', '["v"]', 'to travel go, wayfaring (man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2274}/[H2267]', 'inflected', 'heb', 'חֶבְרָה', '["chebrâh"]', '["for/ company"]', '["n-f"]', 'association company.', 'feminine of 2267;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7521}/H9043/[H7521]', 'inflected', 'heb', 'רָצָה', '["râtsâh"]', '["when/ is pleased/ he"]', '["v"]', 'to be pleased with; specifically, to satisfy a debt (be) accept(-able), accomplish, set affection, approve, consent with, delight (self), enjoy, (be, have a) favour(-able), like, observe, pardon, (be, have, take) please(-ure), reconcile self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7562}/[H7561]', 'inflected', 'heb', 'רֶשַׁע', '["reshaʻ"]', '["from/ wickedness"]', '["n-m"]', 'a wrong (especially moral) iniquity, wicked(-ness).', 'from 7561;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5766A}/[H5765]', 'inflected', 'heb', 'עֶוֶל', '["ʻevel"]', '["from/ injustice","from/ unrighteousness"]', '["n-m"]', '(moral) evil iniquity, perverseness, unjust(-ly), unrighteousness(-ly); wicked(-ness).', 'or עָוֶל; and (feminine) עַוְלָה; or עוֹלָה; or עֹלָה; from 5765;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0734}/[H732]', 'inflected', 'heb', 'אֹרַח', '["ʼôrach"]', '["and/ according to/ [the] way of"]', '["n-m"]', 'a well-trodden road (literally or figuratively); also a caravan manner, path, race, rank, traveller, troop, (by-, high-) way.', 'from 732;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5397}/H9023/[H5395]', 'inflected', 'heb', 'נְשָׁמָה', '["nᵉshâmâh"]', '["and/ breath/ his"]', '["n-f"]', 'a puff, i.e. wind, angry or vital breath, divine inspiration, intellect. or (concretely) an animal blast, (that) breath(-eth), inspiration, soul, spirit.', 'from 5395;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0559}/[H559]', 'inflected', 'heb', 'אָמַר', '["ʼâmar"]', '["¿/ [is it] said","¿/ does it say","¿/ has anyone said","¿/ really <to say>","¿/ to say"]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7771A}/[H7768]', 'lemma', 'heb', 'שׁוֹעַ', '["shôwaʻ"]', '["a rich person","eminent person"]', '["n-m"]', 'a noble, i.e. liberal, opulent; also (as noun in the derived sense) a halloo bountiful, crying, rich.', 'from 7768 in the original sense of freedom;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2676}/[H2673]', 'inflected', 'heb', 'חָצוֹת', '["châtsôwth"]', '["and/ [the] middle of"]', '["n-f"]', 'the middle (of the night) mid(-night).', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1607}/[H1607]', 'lemma', 'heb', 'גָּעַשׁ', '["gâʻash"]', '["they are shaken","they surge"]', '["v"]', 'to agitate violently move, shake, toss, trouble.', 'a primitive root');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6806}/H9023/[H6804]', 'inflected', 'heb', 'צַעַד', '["tsaʻad"]', '["step[s]/ his","steps/ his"]', '["n-m"]', 'a pace or regular step pace, step.', 'from 6804;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5641}/[H5641]', 'inflected', 'heb', 'סָתַר', '["çâthar"]', '["to/ hide","to/ hide themselves"]', '["v"]', 'to hide (by covering), literally or figuratively be absent, keep close, conceal, hide (self), (keep) secret, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7489B}/[H7489]', 'lemma', 'heb', 'רָעַע', '["râʻaʻ"]', '["be bad","he breaks","it has been broken","utterly <broken>"]', '["v"]', 'properly, to spoil (literally, by breaking to pieces); figuratively, to make (or be) good for nothing, i.e. bad (physically, socially or morally) afflict, associate selves (by mistake for 7462), break (down, in pieces), displease, (be, bring, do) evil (doer, entreat, man), show self friendly (by mistake for 7462), do harm, (do) hurt, (behave self, deal) ill, × indeed, do mischief, punish, still, vex, (do) wicked (doer, -ly), be (deal, do) worse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4566}/H9028/[H5647]', 'inflected', 'heb', 'מַעְבָּד', '["maʻbâd"]', '["deeds/ their"]', '["n-m"]', 'an act work.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5606A}/H9038/[H5606]', 'inflected', 'heb', 'סָפַק', '["çâphaq"]', '["he slaps/ them"]', '["v"]', 'to clap the hands (in token of compact, derision, grief, indignation, or punishment); by implication of satisfaction, to be enough; by implication of excess, to vomit clap, smite, strike, suffice, wallow.', 'or שָׂפַק; (1 Kings 20:10; Job 27:23; Isaiah 2:6), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6818}/[H6817]', 'inflected', 'heb', 'צַעֲקָה', '["tsaʻăqâh"]', '["and/ [the] outcry of"]', '["n-f"]', 'a shriek cry(-ing).', 'from 6817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5641}/[H5641]', 'inflected', 'heb', 'סָתַר', '["çâthar"]', '["and/ he may hide","and/ he will hide","then/ I may hide myself"]', '["v"]', 'to hide (by covering), literally or figuratively be absent, keep close, conceal, hide (self), (keep) secret, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4170}/[H3369]', 'inflected', 'heb', 'מוֹקֵשׁ', '["môwqêsh"]', '["from/ [the] snares of","from/ snares of"]', '["n-m"]', 'a noose (for catching animals) (literally or figuratively); by implication, a hook (for the nose) be ensnared, gin, (is) snare(-d), trap.', 'or מֹקֵשׁ; from 3369;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1107}/[H1077]', 'lemma', 'heb', 'בִּלְעֲדֵי', '["bilʻădêy"]', '["apart from"]', '["prt"]', 'except, without, besides beside, not (in), save, without.', 'or בַּלְעֲדֵי; constructive plural from 1077 and 5703, not till, i.e. (as preposition or adverb)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9006/{H5973B}/H9031/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["¿/ from/ with <the>/ you"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1847}/[H3045]', 'inflected', 'heb', 'דַּעַת', '["daʻath"]', '["with/ knowledge"]', '["n"]', 'knowledge cunning, (ig-) norantly, know(-ledge), (un-) awares (wittingly).', 'from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7919A}/[H7919]', 'inflected', 'heb', 'שָׂכַל', '["sâkal"]', '["[are] with/ insight"]', '["v"]', 'to be (causatively, make or act) circumspect and hence, intelligent consider, expert, instruct, prosper, (deal) prudent(-ly), (give) skill(-ful), have good success, teach, (have, make to) understand(-ing), wisdom, (be, behave self, consider, make) wise(-ly), guide wittingly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0015}/[H14]', 'lemma', 'heb', 'אָבֶה', '["ʼâbeh"]', '["would that!"]', '["n-f"]', 'longing desire.', 'from 14;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0410G}\/[H352]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["to <the>/ God"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2403B}/H9020/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["from/ sin/ my"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725G}/H9031/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["I will respond to/ you"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7789}/[H7789]', 'inflected', 'heb', 'שׁוּר', '["shûwr"]', '["and/ observe"]', '["v"]', 'to spy out, i.e. (generally) survey, (for evil) lurk for, (for good) care for behold, lay wait, look, observe, perceive, regard, see.', 'a primitive root (identical with through the idea of going round for inspection);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6588}/H9021/[H6586]', 'inflected', 'heb', 'פֶּשַׁע', '["peshaʻ"]', '["transgressions/ your"]', '["n-m"]', 'a revolt (national, moral or religious) rebellion, sin, transgression, trespass.', 'from 6586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7562}/H9021/[H7561]', 'inflected', 'heb', 'רֶשַׁע', '["reshaʻ"]', '["wickedness/ your"]', '["n-m"]', 'a wrong (especially moral) iniquity, wicked(-ness).', 'from 7561;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6666}/H9021/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["righteousness/ your","righteousness<es>/ your"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6217}/[H6231]', 'lemma', 'heb', 'עָשׁוּק', '["ʻâshûwq"]', '["oppression<s>"]', '["n-m"]', 'used in plural masculine as abstractly, tyranny oppressed(-ion). [Doubtful.]', 'or עָשֻׁק; passive participle of 6231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2220}/[H2232]', 'inflected', 'heb', 'זְרוֹעַ', '["zᵉrôwaʻ"]', '["from/ [the] arm of"]', '["n-f"]', 'the arm (as stretched out), or (of animals) the foreleg; figuratively, force arm, help, mighty, power, shoulder, strength.', 'or (shortened) זְרֹעַ; and (feminine) זְרוֹעָה; or זְרֹעָה; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0502}/H9035/[H502]', 'inflected', 'heb', 'אָלַף', '["ʼâlaph"]', '["[who] teaches/ us"]', '["v"]', 'hence, to learn (and causatively to teach) learn, teach, utter.', 'a primitive root, to associate with;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H0929>', 'inflected', 'heb', 'מבהמות', '["mi./ba.ha.Mot"]', '["more than/ [the] animals of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2449}/H9035/[H2449]', 'inflected', 'heb', 'חָכַם', '["châkam"]', '["he makes wise/ us"]', '["v"]', 'to be wise (in mind, word or act) × exceeding, teach wisdom, be (make self, shew self) wise, deal (never so) wisely, make wiser.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2342K}/[H2342]', 'inflected', 'heb', 'חוּל', '["chûwl"]', '["and/ wait longingly","so/ you may wait"]', '["v"]', 'properly, to twist or whirl (in a circular or spiral manner), i.e. (specifically) to dance, to writhe in pain (especially of parturition) or fear; figuratively, to wait, to pervert bear, (make to) bring forth, (make to) calve, dance, drive away, fall grievously (with pain), fear, form, great, grieve, (be) grievous, hope, look, make, be in pain, be much (sore) pained, rest, shake, shapen, (be) sorrow(-ful), stay, tarry, travail (with pain), tremble, trust, wait carefully (patiently), be wounded.', 'or חִיל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6485H}/[H6485]', 'lemma', 'heb', 'פָּקַד', '["pâqad"]', '["I visited [judgment]","I will visit","I will visit [judgment]","[am] about to visit [judgment]","he will punish","he will visit [judgment]","it has punished","it will be visited","someone should injure","they will be visited","will I punish","will I visit"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6580>', 'inflected', 'heb', 'בפש', '["ba./Pash"]', '["in <the>/ folly"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0347}/[H340]', 'inflected', 'heb', 'אִיּוֹב', '["ʼÎyôwb"]', '["and/ Job"]', '["n-pr-m"]', 'Ijob, the patriarch famous for his patience Job.', 'from 340; hated (i.e. persecuted);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3527}\/[H3527]', 'inflected', 'heb', 'כָּבַר', '["kâbar"]', '["he multiplies"]', '["v"]', 'properly, to plait together, i.e. (figuratively) to augment (especially in number or quantity, to accumulate) in abundance, multiply.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2191>', 'opaque', 'heb', 'זְעֵיר', '["zᵉʻêyr"]', '["a little"]', '["n-m"]', 'small little.', 'from an unused root (akin (by permutation) to 6819), meaning to dwindle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2331}/H9031/[H2324]', 'inflected', 'heb', 'חָוָה', '["châvâh"]', '["so/ I may show/ you"]', '["v"]', 'properly, to live; by implication (intensively) to declare or show show.', 'a primitive root; (compare 2324, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6466}/H9030/[H6466]', 'inflected', 'heb', 'פָּעַל', '["pâʻal"]', '["and/ to/ maker/ my"]', '["v"]', 'to do or make (systematically and habitually), especially to practise commit, (evil-) do(-er), make(-r), ordain, work(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6662}/[H6663]', 'inflected', 'heb', 'צַדִּיק', '["tsaddîyq"]', '["from/ [the] righteous"]', '["a"]', 'just just, lawful, righteous (man).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2131B}/[H2187]', 'inflected', 'heb', 'זִיקָה', '["zîyqâh"]', '["in <the>/ fetters","with/ fetters"]', '["n-m"]', 'properly, what leaps forth, i.e. flash of fire, or a burning arrow; also (from the original sense of the root) a bond chain, fetter, firebrand, spark.', '(Isaiah 50:11) (feminine); and זִק; or זֵק; from 2187;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3920}/H9013/[H3920]', 'inflected', 'heb', 'לָכַד', '["lâkad"]', '["they are caught/ !"]', '["v"]', 'to catch (in a net, trap or pit); generally, to capture or occupy; also to choose (by lot); figuratively, to cohere × at all, catch (self), be frozen, be holden, stick together, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6467}/H9028/[H6466]', 'inflected', 'heb', 'פֹּעַל', '["pôʻal"]', '["work/ their"]', '["n-m"]', 'an act or work (concretely) act, deed, do, getting, maker, work.', 'from 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6588}/H9028/[H6586]', 'inflected', 'heb', 'פֶּשַׁע', '["peshaʻ"]', '["and/ transgressions/ their"]', '["n-m"]', 'a revolt (national, moral or religious) rebellion, sin, transgression, trespass.', 'from 6586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4148H}/[H3256]', 'inflected', 'heb', 'מוּסָר', '["mûwçâr"]', '["for <the>/ correction","to <the>/ discipline"]', '["n-m"]', 'properly, chastisement; figuratively, reproof, warning or instruction; also restraint bond, chastening(-eth), chastisement, check, correction, discipline, doctrine, instruction, rebuke.', 'from 3256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725G}/H9013/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["they return/ !","they will return/ !","they will turn away/ !"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H0205G>', 'inflected', 'heb', 'מאון', '["me./''A.ven"]', '["from/ wickedness"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8141}/H9028/[H8138]', 'inflected', 'heb', 'שָׁנֶה', '["shâneh"]', '["and/ years/ their"]', '["n-f"]', 'a year (as a revolution of time) whole age, × long, old, year(× -ly).', '(in plural or (feminine) שָׁנָה; from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5273A}/[H5276]', 'inflected', 'heb', 'נָעִים', '["nâʻîym"]', '["in <the>/ pleasant [places]","in <the>/ pleasant [things]"]', '["a"]', 'delightful (objective or subjective, literal or figurative) pleasant(-ure), sweet.', 'from 5276;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1097}/[H1086]', 'inflected', 'heb', 'בְּלִי', '["bᵉlîy"]', '["like/ not"]', '["np"]', 'properly, failure, i.e. nothing or destruction; usually (with preposition) without, not yet, because not, as long as, etc. corruption, ig(norantly), for lack of, where no...is, so that no, none, not, un(awares), without.', 'from 1086;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2611}/[H2610]', 'inflected', 'heb', 'חָנֵף', '["chânêph"]', '["and/ [people] godless of"]', '["a"]', 'soiled (i.e. with sin), impious hypocrite(-ical).', 'from 2610;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0631}/H9038/[H631]', 'inflected', 'heb', 'אָסַר', '["ʼâçar"]', '["he has bound/ them"]', '["v"]', 'to yoke or hitch; by analogy, to fasten in any sense, to join battle bind, fast, gird, harness, hold, keep, make ready, order, prepare, prison(-er), put in bonds, set in array, tie.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5290}/[H5287]', 'inflected', 'heb', 'נֹעַר', '["nôʻar"]', '["in <the>/ youth"]', '["n-m"]', '(abstractly) boyhood child, youth.', 'from 5287; (compare 5288)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2416C}/H9028/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["and/ life/ their"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6945}/[H6942]', 'inflected', 'heb', 'קָדֵשׁ', '["qâdêsh"]', '["among the/ temple prostitutes"]', '["n-m"]', 'a (quasi) sacred person, i.e. (technically) a (male) devotee (by prostitution) to licentious idolatry sodomite, unclean.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6040}/H9023/[H6031]', 'inflected', 'heb', 'עֳנִי', '["ʻŏnîy"]', '["by/ affliction/ his"]', '["n-m"]', 'depression, i.e. misery afflicted(-ion), trouble.', 'from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3906}/[H3905]', 'inflected', 'heb', 'לַחַץ', '["lachats"]', '["by <the>/ oppression","in/ [the] oppression of"]', '["n-m"]', 'distress affliction, oppression.', 'from 3905;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6310J}/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["from/ [the] mouth of"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7338}/[H7337]', 'lemma', 'heb', 'רַחַב', '["rachab"]', '["[the] broad spaces of","a broad place"]', '["n-m"]', 'a width breadth, broad place.', 'from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4164}/[H3332]', 'lemma', 'heb', 'מוּצַק', '["mûwtsaq"]', '["constraint","distress"]', '["n-m"]', 'narrowness; figuratively, distress anguish, is straitened, straitness.', 'or מוּצָק; from 3332;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5183A}/[H5182]', 'inflected', 'heb', 'נַחַת', '["Nachath"]', '["and/ [the] quietness of","and/ rest"]', '["n"]', 'a descent, i.e. imposition, unfavorable (punishment) or favorable (food); restfulness lighting down, quiet(-ness), to rest, be set on.', 'from 5182; also (intransitively; perhaps from 5117)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1880}/[H1878]', 'lemma', 'heb', 'דֶּשֶׁן', '["deshen"]', '["fatness"]', '["n-m"]', 'the fat; abstractly fatness, i.e. (figuratively) abundance; specifically the (fatty) ashes of sacrifices ashes, fatness.', 'from 1878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5607A}/[H5606]', 'inflected', 'heb', 'סֵפֶק', '["çêpheq"]', '["in/ mockery"]', '["n-m"]', 'chastisement; also satiety stroke, sufficiency.', 'or שֶׂפֶק; (Job 20:22; Job 36:18), from 5606;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5186}/H9031/[H5186]', 'inflected', 'heb', 'נָטָה', '["nâṭâh"]', '["it turn aside/ you"]', '["v"]', 'to stretch or spread out; by implication, to bend away (including moral deflection); used in a great variety of application (as follows) afternoon, apply, bow (down, -ing), carry aside, decline, deliver, extend, go down, be gone, incline, intend, lay, let down, offer, outstretched, overthrown, pervert, pitch, prolong, put away, shew, spread (out), stretch (forth, out), take (aside), turn (aside, away), wrest, cause to yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H6186A}/[H6186]', 'inflected', 'heb', 'עָרַךְ', '["ʻârak"]', '["¿/ will it set in order"]', '["v"]', 'to set in a row, i.e. arrange, put in order (in a very wide variety of applications) put (set) (the battle, self) in array, compare, direct, equal, esteem, estimate, expert (in war), furnish, handle, join (battle), ordain, (lay, put, reckon up, set) (in) order, prepare, tax, value.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7769}/H9021/[H7768]', 'inflected', 'heb', 'שׁוּעַ', '["shûwaʻ"]', '["opulence/ your"]', '["n-m"]', 'a halloo cry, riches.', 'from 7768;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3981}/[H553]', 'lemma', 'heb', 'מַאֲמָץ', '["maʼămâts"]', '["[the] efforts of"]', '["n-m"]', 'strength, i.e. (plural) resources force.', 'from 553;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4175}/[H3384]', 'lemma', 'heb', 'מוֹרֶה', '["môwreh"]', '["[is] a teacher","early rain"]', '["n-m"]', 'an archer; also teacher or teaching; also the early rain (early) rain.', 'from 3384; (see 3138)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7689}/[H7679]', 'lemma', 'heb', 'שַׂגִּיא', '["saggîyʼ"]', '["[is] exalted","exalted of"]', '["a"]', '(superlatively) mighty excellent, great.', 'from 7679;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5198A}/[H5197]', 'lemma', 'heb', 'נָטָף', '["nâṭâph"]', '["drops of"]', '["n-m"]', 'a drop; specifically, an aromatic gum (probably stacte) drop, stacte.', 'from 5197;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0108}/H9023/[H181]', 'inflected', 'heb', 'אֵד', '["ʼêd"]', '["to/ mist/ its"]', '["n-m"]', 'a fog mist, vapor.', 'from the same as 181 (in the sense of enveloping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7491}/[H7491]', 'lemma', 'heb', 'רָעַף', '["râʻaph"]', '["drip down","they drip","they dripped"]', '["v"]', 'to drip distil, drop (down).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4666}/[H6566]', 'lemma', 'heb', 'מִפְרָשׂ', '["miphrâs"]', '["[the] spreading out<s> of"]', '["n-m"]', 'an expansion that which...spreadest forth, spreading.', 'from 6566;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8663}/[H7722]', 'lemma', 'heb', 'תְּשֻׁאָה', '["tᵉshuʼâh"]', '["[the] crashes of","[the] shouting<s> of","noises","shouting<s>"]', '["n-f"]', 'a crashing or loud clamor crying, noise, shouting, stir.', 'from 7722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5521}/H9023/[H5520]', 'inflected', 'heb', 'סֻכָּה', '["çukkâh"]', '["canopy/ his","pavilion/ his"]', '["n-f"]', 'a hut or lair booth, cottage, covert, pavilion, tabernacle, tent.', 'feminine of 5520;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4342}/[H3527]', 'inflected', 'heb', 'מַכְבִּיר', '["makbîyr"]', '["to/ abundance"]', '["v"]', 'plenty abundance.', 'transitive participle of 3527;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6293}/[H6293]', 'inflected', 'heb', 'פָּגַע', '["pâgaʻ"]', '["in/ an assailant"]', '["v"]', 'to impinge, by accident or violence, or (figuratively) by importunity come (betwixt), cause to entreat, fall (upon), make intercession, intercessor, intreat, lay, light (upon), meet (together), pray, reach, run.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7452}/H9023/[H7321]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["roar/ his"]', '["n"]', 'a crash (of thunder), noise (of war), shout (of joy) × aloud, noise, shouted.', 'from 7321;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5425A}/[H5425]', 'inflected', 'heb', 'נָתַר', '["nâthar"]', '["so/ it may leap"]', '["v"]', 'to jump, i.e. be violently agitated; causatively, to terrify, shake off, untie drive asunder, leap, (let) loose, × make, move, undo.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7267}/[H7264]', 'inflected', 'heb', 'רֹגֶז', '["rôgez"]', '["in/ wrath","to/ [the] raging of"]', '["n-m"]', 'commotion, restlessness (of a horse), crash (of thunder), disquiet, anger fear, noise, rage, trouble(-ing), wrath.', 'from 7264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1899}/[H1897]', 'inflected', 'heb', 'הֶגֶה', '["hegeh"]', '["and/ [the] rumbling","and/ moaning"]', '["n-m"]', 'a muttering (in sighing, thought, or as thunder) mourning, sound, tale.', 'from 1897;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8281}/H9033/[H8281]', 'inflected', 'heb', 'שָׁרָה', '["shârâh"]', '["he lets loose/ it"]', '["v"]', 'to free direct.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0216}/H9023/[H215]', 'inflected', 'heb', 'אוֹר', '["ʼôwr"]', '["and/ light/ his"]', '["n-f"]', 'illumination or (concrete) luminary (in every sense, including lightning, happiness, etc.) bright, clear, day, light (-ning), morning, sun.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1347}/H9023/[H1342]', 'inflected', 'heb', 'גָּאוֹן', '["gâʼôwn"]', '["majesty/ his"]', '["n-m"]', 'the same as 1346 arrogancy, excellency(-lent), majesty, pomp, pride, proud, swelling.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6117}/H9038/[H6119]', 'inflected', 'heb', 'עָקַב', '["ʻâqab"]', '["he holds back/ them"]', '["v"]', 'to seize by the heel; figuratively, to circumvent (as if tripping up the heels); also to restrain (as if holding by the heel) take by the heel, stay, supplant, × utterly.', 'a primitive root; properly, to swell out or up; used only as denominative from 6119,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7950}/[H7949]', 'inflected', 'heb', 'שֶׁלֶג', '["sheleg"]', '["to the/ snow"]', '["n-m"]', 'snow (probably from its whiteness) snow(-y).', 'from 7949;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1933A}/[H183]', 'lemma', 'heb', 'הָוָא', '["hâvâʼ"]', '["fall"]', '["v"]', 'to be (in the sense of existence) be, × have.', 'or הָוָה; a primitive root (compare 183, 1961) supposed to mean properly, to breathe;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1653}/[H1652]', 'inflected', 'heb', 'גֶּשֶׁם', '["geshem"]', '["and/ [is] rain","and/ [the] shower of","and/ rain"]', '["n-m"]', 'a shower rain, shower.', 'from 1652;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5797}/H9023/[H5810]', 'inflected', 'heb', 'עֹז', '["ʻôz"]', '["strength/ his"]', '["n-m"]', 'strength in various applications (force, security, majesty, praise) boldness, loud, might, power, strength, strong.', 'or (fully) עוֹז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0695}/[H693]', 'lemma', 'heb', 'אֶרֶב', '["ʼereb"]', '["a lair","lying-in-wait"]', '["n-m"]', 'ambuscade den, lie in wait.', 'from 693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4585}/H9024/[H4583]', 'inflected', 'heb', 'מְעוֹנָה', '["mᵉʻôwnâh"]', '["and/ in/ dens/ its"]', '["n-f"]', 'den, habitation, (dwelling) place, refuge.', 'or מְעֹנָה; feminine of 4583, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4215}/[H2219]', 'inflected', 'heb', 'מְזָרֶה', '["mᵉzâreh"]', '["and/ from/ [the] scattering winds"]', '["n-m"]', 'properly, a scatterer, i.e. the north wind (as dispersing clouds; only in plural) north.', 'apparently from 2219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7135}/[H7119]', 'lemma', 'heb', 'קָרָה', '["qârâh"]', '["coldness"]', '["n-f"]', 'coolness cold.', 'feminine of 7119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4164}/[H3332]', 'inflected', 'heb', 'מוּצַק', '["mûwtsaq"]', '["[is] <in>/ constraint"]', '["n-m"]', 'narrowness; figuratively, distress anguish, is straitened, straitness.', 'or מוּצָק; from 3332;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7377}/[H7301]', 'inflected', 'heb', 'רִי', '["rîy"]', '["with/ moisture"]', '["n-m"]', 'irrigation, i.e. a shower watering.', 'from 7301;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2959}/[H2959]', 'lemma', 'heb', 'טָרַח', '["ṭârach"]', '["he burdens"]', '["v"]', 'to overburden weary.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8458}/H9023/[H2254]', 'inflected', 'heb', 'תַּחְבֻּלָה', '["tachbulâh"]', '["by/ guidance<s>/ his"]', '["n-f"]', '(only in plural) properly, steerage (as a management of ropes), i.e. (figuratively) guidance or (by implication) a plan good advice, (wise) counsels.', 'or תַּחְבּוּלָה; from 2254 as denominative from 2256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6466}/H9048/[H6466]', 'inflected', 'heb', 'פָּעַל', '["pâʻal"]', '["to/ do/ they"]', '["v"]', 'to do or make (systematically and habitually), especially to practise commit, (evil-) do(-er), make(-r), ordain, work(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H7626G>', 'inflected', 'heb', 'לשבט', '["le./She.vet"]', '["for/ a rod"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7760H}/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["when/ appoints"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4657>', 'opaque', 'heb', 'מִפְלָשׂ', '["miphlâs"]', '["[the] balancing<s> of"]', '["n-m"]', 'a poising balancing.', 'from an unused root meaning to balance;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4652}/[H6381]', 'lemma', 'heb', 'מִפְלָאָה', '["miphlâʼâh"]', '["[the] wondrous works of"]', '["n-f"]', 'a miracle wondrous work.', 'from 6381;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1843}/[H3045]', 'lemma', 'heb', 'דֵּעַ', '["dêaʻ"]', '["knowledge<s>"]', '["n-m"]', 'knowledge knowledge, opinion.', 'from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8252}/[H8252]', 'inflected', 'heb', 'שָׁקַט', '["shâqaṭ"]', '["in/ being quiet","when/ is still"]', '["v"]', 'to repose (usually figurative) appease, idleness, (at, be at, be in, give) quiet(-ness), (be at, be in, give, have, take) rest, settle, be still.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H1864>', 'inflected', 'heb', 'מדרום', '["mi./da.Rom"]', '["from/ [the] south"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7554}/[H7554]', 'lemma', 'heb', 'רָקַע', '["râqaʻ"]', '["[who] spread out","beaten","will you spread out?"]', '["v"]', 'to pound the earth (as a sign of passion); by analogy to expand (by hammering); by implication, to overlay (with thin sheets of metal) beat, make broad, spread abroad (forth, over, out, into plates), stamp, stretch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7834}/[H7833]', 'inflected', 'heb', 'שַׁחַק', '["shachaq"]', '["<to>/ clouds"]', '["n-m"]', 'a powder (as beaten small); by analogy, a thin vapor; by extension, the firmament cloud, small dust, heaven, sky.', 'from 7833;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7209}/[H7200]', 'inflected', 'heb', 'רְאִי', '["rᵉʼîy"]', '["like/ a mirror"]', '["n-m"]', 'a mirror (as seen) looking glass.', 'from 7200;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5608A}/[H5608]', 'inflected', 'heb', 'סָפַר', '["çâphar"]', '["¿/ will it be recounted"]', '["v n-m"]', 'properly, to score with a mark as a tally or record, i.e. (by implication) to inscribe, and also to enumerate; intensively, to recount, i.e. celebrate commune, (ac-) count; declare, number, penknife, reckon, scribe, shew forth, speak, talk, tell (out), writer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0925>', 'opaque', 'heb', 'בָּהִיר', '["bâhîyr"]', '["[is] brilliant"]', '["a"]', 'shining bright.', 'from an unused root (meaning to be bright);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7834}/[H7833]', 'inflected', 'heb', 'שַׁחַק', '["shachaq"]', '["[is] in the/ clouds","in the/ cloud[s]","in the/ clouds"]', '["n-m"]', 'a powder (as beaten small); by analogy, a thin vapor; by extension, the firmament cloud, small dust, heaven, sky.', 'from 7833;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3372H}/H9033/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["they fear/ him"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3820A}\/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["heart"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5591B}/[H5590]', 'inflected', 'heb', 'סַעַר', '["çaʻar"]', '["the/ tempest"]', '["n-m"]', 'a hurricane storm(-y), tempest, whirlwind.', 'or (feminine) סְעָרָה; from 5590;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1397}/[H1396]', 'inflected', 'heb', 'גֶּבֶר', '["geber"]', '["like/ a man"]', '["n-m"]', 'properly, a valiant man or warrior; generally, a person simply every one, man, × mighty.', 'from 1396;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2504}/H9021/[H2502]', 'inflected', 'heb', 'חָלָץ', '["châlâts"]', '["loins/ your"]', '["n-f"]', 'the loins (as the seat of vigor) loins, reins.', 'from 2502 (in the sense of strength); only in the dual;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7592}/H9031/[H7592]', 'inflected', 'heb', 'שָׁאַל', '["shâʼal"]', '["and/ I will ask/ you"]', '["v"]', 'to inquire; by implication, to request; by extension, to demand ask (counsel, on), beg, borrow, lay to charge, consult, demand, desire, × earnestly, enquire, greet, obtain leave, lend, pray, request, require, salute, × straitly, × surely, wish.', 'or שָׁאֵל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3245}/H9040/[H3245]', 'inflected', 'heb', 'יָסַד', '["yâçad"]', '["when/ founded/ I"]', '["v"]', 'to set (literally or figuratively); intensively, to found; reflexively, to sit down together, i.e. settle, consult appoint, take counsel, establish, (lay the, lay for a) found(-ation), instruct, lay, ordain, set, × sure.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4461}/H9024/[H4058]', 'inflected', 'heb', 'מֵמַד', '["mêmad"]', '["measurements/ its"]', '["n-m"]', 'a measure measure.', 'from 4058;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6438H}/H9024/[H6434]', 'inflected', 'heb', 'פִּנָּה', '["pinnâh"]', '["corner/ her","corner/ its"]', '["n-f"]', 'an angle; by implication, a pinnacle; figuratively, a chieftain bulwark, chief, corner, stay, tower.', 'feminine of 6434;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7442B}/[H7442]', 'inflected', 'heb', 'רָנַן', '["rânan"]', '["when/ sang"]', '["v"]', 'properly, to creak (or emit a stridulous sound), i.e. to shout (usually for joy) aloud for joy, cry out, be joyful (greatly, make to) rejoice, (cause to) shout (for joy), (cause to) sing (aloud, for joy, out), triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1518}/H9043/[H1518]', 'inflected', 'heb', 'גִּיחַ', '["gîyach"]', '["when/ burst forth/ it"]', '["v"]', 'to gush forth (as water), generally to issue break forth, labor to bring forth, come forth, draw up, take out.', 'or (shortened) גֹּחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7760A}/H9040/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["when/ made/ I","when/ set/ I"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2854}/H9023/[H2853]', 'inflected', 'heb', 'חֲתֻלָּה', '["chăthullâh"]', '["swaddling-band/ its"]', '["n-f"]', 'a swathing cloth (figuratively) swaddling band.', 'from 2853;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2706I}/H9020/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["boundary/ my"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1347}/[H1342]', 'inflected', 'heb', 'גָּאוֹן', '["gâʼôwn"]', '["by/ [the] majesty of","by/ [the] pride of","in/ [the] majesty of","in/ [the] pride of","in/ [the] thicket of"]', '["n-m"]', 'the same as 1346 arrogancy, excellency(-lent), majesty, pomp, pride, proud, swelling.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1530H}/H9021/[H1556]', 'inflected', 'heb', 'גַּל', '["gal"]', '["waves/ your"]', '["n-m"]', 'something rolled, i.e. a heap of stone or dung (plural ruins), by analogy, a spring of water (plural waves) billow, heap, spring, wave.', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9006/<H3117G>/H9021', 'inflected', 'heb', 'המימיך', '["He./mi./ya.mei./kha"]', '["¿/ from/ days/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2563C}/[H2560]', 'inflected', 'heb', 'חֹמֶר', '["chômer"]', '["like/ [the] clay of"]', '["n-m"]', 'properly, a bubbling up, i.e. of water, a wave; of earth, mire or clay (cement); also a heap; hence, a chomer or dry measure clay, heap, homer, mire, motion.', 'from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4513}/[H4513]', 'inflected', 'heb', 'מָנַע', '["mânaʻ"]', '["so/ it may be withheld"]', '["v"]', 'to debar (negatively or positively) from benefit or injury deny, keep (back), refrain, restrain, withhold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0216}/H9028/[H215]', 'inflected', 'heb', 'אוֹר', '["ʼôwr"]', '["[was] light/ their","light/ their"]', '["n-f"]', 'illumination or (concrete) luminary (in every sense, including lightning, happiness, etc.) bright, clear, day, light (-ning), morning, sun.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5033>', 'opaque', 'heb', 'נֵבֶךְ', '["nêbek"]', '["[the] springs of"]', '["n-m"]', 'a fountain spring.', 'from an unused root meaning to burst forth;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2714}/[H2713]', 'inflected', 'heb', 'חֵקֶר', '["chêqer"]', '["and/ in/ [the] depth of"]', '["n-m"]', 'examination, enumeration, deliberation finding out, number, (un-) search(-able, -ed, out, -ing).', 'from 2713;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7128}/[H7126]', 'lemma', 'heb', 'קְרָב', '["qᵉrâb"]', '["[which] wars","battle","war"]', '["n-m"]', 'hostile encounter battle, war.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7858}/[H7857]', 'inflected', 'heb', 'שֶׁטֶף', '["sheṭeph"]', '["for the/ flood","to/ a flood of"]', '["n-m"]', 'a deluge (literally or figuratively) flood, outrageous, overflowing.', 'or שֵׁטֶף; from 7857;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1870K}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["and/ [the] direction of","and/ a path","and/ a way"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4305}/[H4305]', 'inflected', 'heb', 'מָטַר', '["mâṭar"]', '["to/ send rain"]', '["v"]', 'to rain (cause to) rain (upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6779}/[H6779]', 'inflected', 'heb', 'צָמַח', '["tsâmach"]', '["and/ to/ cause to sprout"]', '["v"]', 'to sprout (transitive or intransitive, literal or figurative) bear, bring forth, (cause to, make to) bud (forth), (cause to, make to) grow (again, up), (cause to) spring (forth, up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0096>', 'opaque', 'heb', 'אֶגֶל', '["ʼegel"]', '["[the] drops of"]', '["n-m"]', 'a reservoir drop.', 'from an unused root (meaning to flow down or together as drops);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7140}/[H7139]', 'inflected', 'heb', 'קֶרַח', '["qerach"]', '["<the>/ frost","the/ ice"]', '["n-m"]', 'ice (as if bald, i.e. smooth); hence, hail; by resemblance, rock crystal crystal, frost, ice.', 'or קֹרַח; from 7139;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3713B}/[H3722]', 'inflected', 'heb', 'כְּפוֹר', '["kᵉphôwr"]', '["and/ [the] frost of"]', '["n-m"]', 'properly, a cover, i.e. (by implication) a tankard (or covered goblet); also white frost (as covering the ground) bason, hoar(-y) frost.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6440J}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["and/ [the] surface of"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7194}/[H7194]', 'inflected', 'heb', 'קָשַׁר', '["qâshar"]', '["¿/ will you bind","¿/ will you bind on"]', '["v"]', 'to tie, physically (gird, confine, compact) or mentally (in love, league) bind (up), (make a) conspire(-acy, -ator), join together, knit, stronger, work (treason).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3598}/[H3558]', 'lemma', 'heb', 'כִּימָה', '["Kîymâh"]', '["Pleiades"]', '["n-f"]', 'a cluster of stars, i.e. the Pleiades Pleiades, seven stars.', 'from the same as 3558;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4189}/[H4900]', 'lemma', 'heb', 'מוֹשְׁכָה', '["môwshᵉkâh"]', '["[the] chains of"]', '["n-f"]', 'something drawing, i.e. (figuratively) a cord band.', 'act participle feminine of 4900;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3318H}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["¿/ will you lead out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4216}/[H5144]', 'lemma', 'heb', 'מַזָּרָה', '["mazzârâh"]', '["[the] constellations"]', '["n-f"]', 'some noted constellation (only in the plural), perhaps collectively, the zodiac Mazzoroth. Compare 4208.', 'apparently from 5144 in the sense of distinction;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5906}/[H5789]', 'inflected', 'heb', 'עַיִשׁ', '["ʻAyish"]', '["and/ [the] Bear"]', '["n-f"]', 'the constellation of the Great Bear (perhaps from its migration through the heavens) Arcturus.', 'or עָשׁ; from 5789;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4896}/H9023/[H7860]', 'inflected', 'heb', 'מִשְׁטָר', '["mishṭâr"]', '["rule/ its"]', '["n-m"]', 'jurisdiction dominion.', 'from 7860;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7311A}/[H7311]', 'inflected', 'heb', 'רוּם', '["rûwm"]', '["¿/ will you lift up"]', '["v"]', 'to be high actively, to rise or raise (in various applications, literally or figuratively) bring up, exalt (self), extol, give, go up, haughty, heave (up), (be, lift up on, make on, set up on, too) high(-er, one), hold up, levy, lift(-er) up, (be) lofty, (× a-) loud, mount up, offer (up), presumptuously, (be) promote(-ion), proud, set up, tall(-er), take (away, off, up), breed worms.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7971G}/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["¿/ will you send forth"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2910}/[H2909]', 'inflected', 'heb', 'טֻחָה', '["ṭuchâh"]', '["in the/ covered places","in the/ inner parts"]', '["n-f"]', '(in the plural only) the kidneys (as being covered); hence (figuratively) the inmost thought inward parts.', 'from 2909 (or 2902) in the sense of overlaying;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7907}/[H7906]', 'inflected', 'heb', 'שֶׂכְוִי', '["sekvîy"]', '["to the/ heart"]', '["n-m"]', 'observant, i.e. (concretely) the mind heart.', 'from the same as 7906;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3332G}/[H3332]', 'inflected', 'heb', 'יָצַק', '["yâtsaq"]', '["when/ flows"]', '["v"]', 'properly, to pour out (transitive or intransitive); by implication, to melt or cast as metal; by extension, to place firmly, to stiffen or grow hard cast, cleave fast, be (as) firm, grow, be hard, lay out, molten, overflow, pour (out), run out, set down, stedfast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4165}/[H5694]', 'inflected', 'heb', 'מוּצָק', '["mûwtsâq"]', '["into <the>/ lump"]', '["n-m"]', 'properly, fusion, i.e. literally, a casting (of metal); figuratively, a mass (of clay) casting, hardness.', 'from 5694;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7263>', 'inflected', 'heb', 'ורגבים', '["u./re.ga.Vim"]', '["and/ [the] clods"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H6679A}/[H6718]', 'inflected', 'heb', 'צוּד', '["tsûwd"]', '["¿/ will you hunt"]', '["v"]', 'to lie alongside (i.e. in wait); by implication, to catch an animal (figuratively, men); to victual (for a journey) chase, hunt, sore, take (provision).', 'a primitive root; also denominative from 6718');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3833C>', 'inflected', 'heb', 'ללביא', '["le./la.Vi''"]', '["for/ a lion"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4585}/[H4583]', 'inflected', 'heb', 'מְעוֹנָה', '["mᵉʻôwnâh"]', '["in <the>/ dens"]', '["n-f"]', 'den, habitation, (dwelling) place, refuge.', 'or מְעֹנָה; feminine of 4583, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6158}/[H6150]', 'inflected', 'heb', 'עֹרֵב', '["ʻôrêb"]', '["for the/ raven"]', '["n-m"]', 'a raven (from its dusky hue) raven.', 'or עוֹרֵב; from 6150;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6718B}/H9023/[H6679]', 'inflected', 'heb', 'צַיִד', '["tsayid"]', '["food-supply/ its"]', '["n-m"]', 'the chase; also game (thus taken) × catcheth, food, × hunter, (that which he took in) hunting, venison, victuals.', 'from a form of 6679 and meaning the same;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1097}/[H1086]', 'inflected', 'heb', 'בְּלִי', '["bᵉlîy"]', '["for/ not","to/ not"]', '["np"]', 'properly, failure, i.e. nothing or destruction; usually (with preposition) without, not yet, because not, as long as, etc. corruption, ig(norantly), for lack of, where no...is, so that no, none, not, un(awares), without.', 'from 1086;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3277H}/[H3276]', 'lemma', 'heb', 'יָעֵל', '["yâʻêl"]', '["mountain goats of"]', '["n-m"]', 'an ibex (as climbing) wild goat.', 'from 3276;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3205}/H9049/[H3205]', 'inflected', 'heb', 'יָלַד', '["yâlad"]', '["bringing forth/ they"]', '["v"]', 'to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2256B}/H9028/[H2254]', 'inflected', 'heb', 'חֶבֶל', '["chebel"]', '["labor-pains/ their"]', '["n-m"]', 'a rope (as twisted), especially a measuring line; by implication, a district or inheritance (as measured); or a noose (as of cords); figuratively, a company (as if tied together); a throe (especially of parturition); also ruin band, coast, company, cord, country, destruction, line, lot, pain, pang, portion, region, rope, snare, sorrow, tackling.', 'or חֵבֶל; from 2254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2492A}/[H2492]', 'lemma', 'heb', 'חָלַם', '["châlam"]', '["they become strong"]', '["v"]', 'properly, to bind firmly, i.e. (by implication) to be (causatively to make) plump; also (through the figurative sense of dumbness) to dream (cause to) dream(-er), be in good liking, recover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1250B}/[H1305]', 'inflected', 'heb', 'בָּר', '["bâr"]', '["in the/ open"]', '["n-m"]', 'grain of any kind (even while standing in the field); by extension the open country corn, wheat.', 'or בַּר; from 1305 (in the sense of winnowing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4147}/[H3256]', 'inflected', 'heb', 'מוֹסֵר', '["môwçêr"]', '["and/ [the] fetters of"]', '["n-m"]', 'properly, chastisement, i.e. (by implication) a halter; figuratively, restraint band, bond.', 'also (in plural) feminine מוֹסֵרָה; or מֹסְרָה; from 3256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6171}/[H6166]', 'lemma', 'heb', 'עָרוֹד', '["ʻârôwd"]', '["[the] wild ass"]', '["n-m"]', 'an onager (from his lonesome habits) wild ass.', 'from the same as 6166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4908}/H9023/[H7931]', 'inflected', 'heb', 'מִשְׁכָּן', '["mishkân"]', '["and/ dwelling-places/ its","and/ dwellings/ its"]', '["n-m"]', 'a residence (including a shepherd''s hut, the lair of animals, figuratively, the grave; also the Temple); specifically, the Tabernacle (properly, its wooden walls) dwelleth, dwelling (place), habitation, tabernacle, tent.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4420}/[H4414]', 'lemma', 'heb', 'מְלֵחָה', '["mᵉlêchâh"]', '["[the] saltiness","saltiness"]', '["n-f"]', 'properly, salted (i.e. land), i.e. a desert barren land(-ness), salt (land).', 'from 4414 (in its denominative sense); understood as land (776)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1995A}/[H1993]', 'inflected', 'heb', 'הָמוֹן', '["hâmôwn"]', '["to/ [the] tumult of"]', '["n-m"]', 'a noise, tumult, crowd; also disquietude, wealth abundance, company, many, multitude, multiply, noise, riches, rumbling, sounding, store, tumult.', 'or הָמֹן; (Ezekiel 5:7), from 1993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4829}/H9023/[H7462]', 'inflected', 'heb', 'מִרְעֶה', '["mirʻeh"]', '["pasture/ its"]', '["n-m"]', 'pasture (the place or the act); also the haunt of wild animals feeding place, pasture.', 'from 7462 in the sense of feeding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3387}/[H3417]', 'lemma', 'heb', 'יָרוֹק', '["yârôwq"]', '["green plant"]', '["n-m"]', 'green, i.e. an herb green thing.', 'from 3417;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0014}/[H14]', 'inflected', 'heb', 'אָבָה', '["ʼâbâh"]', '["¿/ is it willing"]', '["v"]', 'to breathe after, i.e. (figuratively) to be acquiescent consent, rest content will, be willing.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0018}/H9021/[H75]', 'inflected', 'heb', 'אֵבוּס', '["ʼêbûwç"]', '["feeding trough/ your"]', '["n-m"]', 'a manger or stall crib.', 'from 75;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H8525>', 'inflected', 'heb', 'בתלם', '["be./Te.lem"]', '["in/ a furrow"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5688}/H9023/[H5687]', 'inflected', 'heb', 'עֲבֹת', '["ʻăbôth"]', '["rope/ its"]', '["n"]', 'something intwined, i.e. a string, wreath or foliage band, cord, rope, thick bough (branch), wreathen (chain).', 'or עֲבוֹת; or (feminine) עֲבֹתָה; the same as 5687;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7702}/[H7702]', 'lemma', 'heb', 'שָׂדַד', '["sâdad"]', '["it will harrow","will it harrow"]', '["v"]', 'to abrade, i.e. harrow a field break clods, harrow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0982}/[H982]', 'inflected', 'heb', 'בָּטַח', '["bâṭach"]', '["¿/ will you trust"]', '["v"]', 'properly, to hie for refuge (but not so precipitately as 2620); figuratively, to trust, be confident or sure be bold (confident, secure, sure), careless (one, woman), put confidence, (make to) hope, (put, make to) trust.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5800A}/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["and/ I will leave","and/ [one who] forsakes [them]","and/ [those who] forsake","and/ forsake","and/ forsaken","and/ it has abandoned","so/ you may leave?"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0539}/[H541]', 'inflected', 'heb', 'אָמַן', '["ʼâman"]', '["¿/ will you trust"]', '["v"]', 'properly, to build up or support; to foster as a parent or nurse; figuratively to render (or be) firm or faithful, to trust or believe, to be permanent or quiet; morally to be true or certain; hence, assurance, believe, bring up, establish, fail, be faithful (of long continuance, stedfast, sure, surely, trusty, verified), nurse, (-ing father), (put), trust, turn to the right.', 'a primitive root; (Isaiah 30:21; interchangeable with 541, to go to the right hand)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1637>/H9021', 'inflected', 'heb', 'וגרנך', '["ve./ga.re.ne./Kha"]', '["and/ threshing floor/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7443}/[H7442]', 'lemma', 'heb', 'רֶנֶן', '["renen"]', '["ostriches"]', '["n-m"]', 'an ostrich (from its wail) × goodly.', 'from 7442;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0084}/[H83]', 'lemma', 'heb', 'אֶבְרָה', '["ʼebrâh"]', '["a pinion"]', '["n-f"]', 'feather, wing.', 'feminine of 83');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2624}/[H2623]', 'lemma', 'heb', 'חֲסִידָה', '["chăçîydâh"]', '["[the] stork","a stork"]', '["n-f"]', 'the kind (maternal) bird, i.e. a stork × feather, stork.', 'feminine of 2623;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5133}/[H5327]', 'inflected', 'heb', 'נוֹצָה', '["nôwtsâh"]', '["and/ plumage"]', '["n-f"]', 'a pinion (or wing feather); often (collectively) plumage feather(-s), ostrich.', 'or נֹצָה; feminine active participle of 5327 in the sense of flying;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1000}/H9024/[H948]', 'inflected', 'heb', 'בֵּיצָה', '["bêytsâh"]', '["eggs/ its"]', '["n-f"]', 'an egg (from its whiteness) egg.', 'from the same as 948;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2115}/H9034/[H6695]', 'inflected', 'heb', 'זוּר', '["zûwr"]', '["it will crush/ it"]', '["v"]', 'to press together, tighten close, rush, thrust together.', 'a primitive root (compare 6695);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1758}/H9034/[H1758]', 'inflected', 'heb', 'דּוּשׁ', '["dûwsh"]', '["it will trample/ it"]', '["v"]', 'to trample or thresh break, tear, thresh, tread out (down), at grass (Jeremiah 50:11, by mistake for 1877).', 'or דּוֹשׁ; or דִּישׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7188}/[H7188]', 'lemma', 'heb', 'קָשַׁח', '["qâshach"]', '["do you harden?","it treats roughly"]', '["v"]', 'to be (causatively, make) unfeeling harden.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121H}/H9024/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["young/ its"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3018}/H9024/[H3021]', 'inflected', 'heb', 'יְגִיעַ', '["yᵉgîyaʻ"]', '["labor/ its","property/ its"]', '["n-m"]', 'toil; hence, a work, produce, property (as the result of labor) labour, work.', 'from 3021;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5382}/H9034/[H5382]', 'inflected', 'heb', 'נָשָׁה', '["nâshâh"]', '["he has made forget/ it"]', '["v"]', 'to forget; figuratively, to neglect; causatively, to remit, remove forget, deprive, exact.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0998}/[H995]', 'inflected', 'heb', 'בִּינָה', '["bîynâh"]', '["in <the>/ understanding"]', '["n-f"]', 'understanding knowledge, meaning, × perfectly, understanding, wisdom.', 'from 995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4754}/[H4754]', 'lemma', 'heb', 'מָרָא', '["mârâʼ"]', '["[the] filthy [one]","it flaps"]', '["v"]', 'to rebel; hence (through the idea of maltreating) to whip, i.e. lash (self with wings, as the ostrich in running) be filthy, lift up self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7392}/H9023/[H7392]', 'inflected', 'heb', 'רָכַב', '["râkab"]', '["and/ to/ rider/ its"]', '["v"]', 'to ride (on an animal or in a vehicle); causatively, to place upon (for riding or generally), to despatch bring (on (horse-) back), carry, get (oneself) up, on (horse-) back, put, (cause to, make to) ride (in a chariot, on, -r), set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5414G}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["¿/ do you give","¿/ will I give"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3847}/[H3847]', 'inflected', 'heb', 'לָבַשׁ', '["lâbash"]', '["¿/ do you clothe"]', '["v"]', 'properly, wrap around, i.e. (by implication) to put on a garment or clothe (oneself, or another), literally or figuratively (in) apparel, arm, array (self), clothe (self), come upon, put (on, upon), wear.', 'or לָבֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7483}/[H7482]', 'lemma', 'heb', 'רַעְמָה', '["raʻmâh"]', '["a mane"]', '["n-f"]', 'the mane of a horse (as quivering in the wind) thunder.', 'feminine of 7482;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7493}/H9033/[H7493]', 'inflected', 'heb', 'רָעַשׁ', '["râʻash"]', '["¿/ do you make leap/ it"]', '["v"]', 'to undulate (as the earth, the sky, etc.; also a field of grain), particularly through fear; specifically, to spring (as a locust) make afraid, (re-) move, quake, (make to) shake, (make to) tremble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5170A>/H9023', 'opaque', 'heb', 'נַחַר', '["nachar"]', '["snorting/ its"]', '["n-m"]', 'a snorting nostrils, snorting.', 'and (feminine) נַחֲרָה; from an unused root meaning to snort or snore;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7797}/[H7797]', 'inflected', 'heb', 'שׂוּשׂ', '["sûws"]', '["and/ may they rejoice","so/ it may rejoices"]', '["v"]', 'to be bright, i.e. cheerful be glad, × greatly, joy, make mirth, rejoice.', 'or שִׂישׂ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6343}/[H6342]', 'inflected', 'heb', 'פַּחַד', '["pachad"]', '["to/ fear"]', '["n-m"]', 'a (sudden) alarm (properly, the object feared, by implication, the feeling) dread(-ful), fear, (thing) great (fear, -ly feared), terror.', 'from 6342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7439}/[H7439]', 'lemma', 'heb', 'רָנָה', '["rânâh"]', '["it rattles"]', '["v"]', 'to whiz rattle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0827}/[H825]', 'lemma', 'heb', 'אַשְׁפָּה', '["ʼashpâh"]', '["a quiver"]', '["n-f"]', 'a quiver or arrow-case quiver.', 'perhaps (feminine) from the same as 825 (in the sense of covering);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3851}/[H3851]', 'lemma', 'heb', 'לַהַב', '["lahab"]', '["[the] blade of","flames"]', '["n-m"]', 'a flash; figuratively, a sharply polished blade or point of a weapon blade, bright, flame, glittering.', 'from an usused root meaning to gleam;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7267}/[H7264]', 'inflected', 'heb', 'רֹגֶז', '["rôgez"]', '["and/ excitement"]', '["n-m"]', 'commotion, restlessness (of a horse), crash (of thunder), disquiet, anger fear, noise, rage, trouble(-ing), wrath.', 'from 7264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1572}/[H1572]', 'lemma', 'heb', 'גָּמָא', '["gâmâʼ"]', '["it swallows"]', '["v"]', 'to absorb swallow, drink.', 'a primitive root (literally or figuratively) to absorb');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H1767>', 'inflected', 'heb', 'בדי', '["be./Dei","be./dei"]', '["for/ [the] sufficiency of","in/ [the] sufficiency of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1889}/[H1887]', 'lemma', 'heb', 'הֶאָח', '["heʼâch"]', '["aha!"]', '["inj"]', 'aha! ah, aha, ha.', 'from 1887 and 253;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H7350}/[H7368]', 'inflected', 'heb', 'רָחוֹק', '["râchôwq"]', '["and/ from/ a distance"]', '["a"]', 'remote, literally or figuratively, of place or time; specifically, precious; often used adverbially (with preposition) (a-) far (abroad, off), long ago, of old, space, great while to come.', 'or רָחֹק; from 7368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7482}/[H7481]', 'lemma', 'heb', 'רַעַם', '["raʻam"]', '["[the] thunder of","thunder"]', '["n-m"]', 'a peal of thunder thunder.', 'from 7481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9006/{H0998}/H9021/[H995]', 'inflected', 'heb', 'בִּינָה', '["bîynâh"]', '["¿/ from/ understanding/ your"]', '["n-f"]', 'understanding knowledge, meaning, × perfectly, understanding, wisdom.', 'from 995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0082}/[H82]', 'lemma', 'heb', 'אָבַר', '["ʼâbar"]', '["does it soar"]', '["v"]', 'to soar fly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5322B}/[H5340]', 'lemma', 'heb', 'נֵץ', '["nêts"]', '["a falcon"]', '["n-m"]', 'a flower (from its brilliancy); also a hawk (from it flashing speed) blossom, hawk.', 'from 5340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8486}/[H3225]', 'inflected', 'heb', 'תֵּימָן', '["têymân"]', '["to/ [the] south"]', '["n-f"]', 'the south (as being on the right hand of a person facing the east) south (side, -ward, wind).', 'or תֵּמָן; denominative from 3225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4686B}/[H4685]', 'inflected', 'heb', 'מָצוּד', '["mâtsûwd"]', '["and/ a stronghold"]', '["n-f"]', 'a net, or (abstractly) capture; also a fastness castle, defense, fort(-ress), (strong) hold, be hunted, net, snare, strong place.', 'or (feminine) מְצוּדָה; or מְצֻדָה; for 4685;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0667}/H9023/[H6524]', 'inflected', 'heb', 'אֶפְרֹחַ', '["ʼephrôach"]', '["and/ young ones/ its"]', '["n-m"]', 'the brood of a bird young (one).', 'from 6524 (in the sense of bursting the shell);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5966}/[H5966]', 'lemma', 'heb', 'עָלַע', '["ʻâlaʻ"]', '["they drink"]', '["v"]', 'to sip up suck up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3250}/[H3256]', 'lemma', 'heb', 'יִסּוֹר', '["yiççôwr"]', '["a faultfinder"]', '["n-m"]', 'a reprover instruct.', 'from 3256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6030B}/H9034\/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["it will answer/ it","let him answer/ him"]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725M}/H9031/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["will I respond to/ you"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3254G}\/[H3254]', 'inflected', 'heb', 'יָסַף', '["yâçaph"]', '["I will repeat"]', '["v"]', 'to add or augment (often adverbial, to continue to do a thing) add, × again, × any more, × cease, × come more, conceive again, continue, exceed, × further, × gather together, get more, give more-over, × henceforth, increase (more and more), join, × longer (bring, do, make, much, put), × (the, much, yet) more (and more), proceed (further), prolong, put, be (strong-) er, × yet, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5591B}/[H5590]', 'lemma', 'heb', 'סַעַר', '["çaʻar"]', '["[the] storm","[the] storm of","a storm","a tempest","storm","tempests"]', '["n-m"]', 'a hurricane storm(-y), tempest, whirlwind.', 'or (feminine) סְעָרָה; from 5590;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5710B}/[H5710]', 'lemma', 'heb', 'עָדָה', '["ʻâdâh"]', '["[who] she adorns herself","deck yourself","you ornament yourself","you will ornament yourself"]', '["v"]', 'to advance, i.e. pass on or continue; causatively, to remove; specifically, to bedeck (i.e. bring an ornament upon) adorn, deck (self), pass by, take away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1363}/[H1361]', 'inflected', 'heb', 'גֹּבַהּ', '["gôbahh"]', '["and/ [the] height","and/ dignity","and/ height"]', '["n-m"]', 'elation, grandeur, arrogance excellency, haughty, height, high, loftiness, pride.', 'from 1361;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1935>', 'inflected', 'heb', 'והוד', '["ve./Hod"]', '["and/ glory"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1343}/[H1342]', 'lemma', 'heb', 'גֵּאֶה', '["gêʼeh"]', '["proud","proud [people]","proud [person]","proud [thing]"]', '["a"]', 'lofty; figuratively, arrogant proud.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8213}/H9033/[H8213]', 'inflected', 'heb', 'שָׁפֵל', '["shâphêl"]', '["and/ bring low/ him"]', '["v"]', 'to depress or sink (especially figuratively, to humiliate, intransitive or transitive) abase, bring (cast, put) down, debase, humble (self), be (bring, lay, make, put) low(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3665}/H9033/[H3665]', 'inflected', 'heb', 'כָּנַע', '["kânaʻ"]', '["humble/ him"]', '["v"]', 'properly, to bend the knee; hence, to humiliate, vanquish bring down (low), into subjection, under, humble (self), subdue.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1915}/[H1854]', 'inflected', 'heb', 'הָדַךְ', '["hâdak"]', '["and/ tread down"]', '["v"]', 'to crush with the foot tread down.', 'a primitive root (compare 1854);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2934}/H9038/[H2934]', 'inflected', 'heb', 'טָמַן', '["ṭâman"]', '["hide/ them"]', '["v"]', 'to hide (by covering over) hide, lay privily, in secret.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2934}/[H2934]', 'inflected', 'heb', 'טָמַן', '["ṭâman"]', '["in the/ hidden [place]"]', '["v"]', 'to hide (by covering over) hide, lay privily, in secret.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0930}/[H929]', 'lemma', 'heb', 'בְּהֵמוֹת', '["bᵉhêmôwth"]', '["Behemoth"]', '["n-m"]', 'a water-ox, i.e. the hippopotamus or Nile-horse Behemoth.', 'in form a plural or 929, but really a singular of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1241}/[H1239]', 'inflected', 'heb', 'בָּקָר', '["bâqâr"]', '["like <the>/ ox","like the/ ox"]', '["n-m"]', 'a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0202}/H9023/[H205]', 'inflected', 'heb', 'אוֹן', '["ʼôwn"]', '["and/ power/ its"]', '["n-m"]', 'ability, power, (figuratively) wealth force, goods, might, strength, substance.', 'probably from the same as 205 (in the sense of effort, but successful);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8306}/[H8324]', 'inflected', 'heb', 'שָׁרִיר', '["shârîyr"]', '["in/ [the] muscles of"]', '["n-m"]', 'a cord, i.e. (by analogy) sinew navel.', 'from 8324 in the original sense as in 8270 (compare 8326);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2654B}/[H2654]', 'lemma', 'heb', 'חָפֵץ', '["châphêts"]', '["it stiffens"]', '["v"]', 'properly, to incline to; by implication (literally but rarely) to bend; figuratively, to be pleased with, desire × any at all, (have, take) delight, desire, favour, like, move, be (well) pleased, have pleasure, will, would.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2180}/H9023/[H2179]', 'inflected', 'heb', 'זָנָב', '["zânâb"]', '["tail/ its"]', '["n-m"]', 'the tail (literally or figuratively) tail.', 'from 2179 (in the original sense of flapping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6344}/H9023/[H6343]', 'inflected', 'heb', 'פַּחַד', '["pachad"]', '["thighs/ its"]', '["n-m"]', 'a testicle (as a cause of shame akin to fear) stone.', 'the same as 6343;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8276}/[H8276]', 'lemma', 'heb', 'שָׂרַג', '["sârag"]', '["they are intertwined","they are woven together"]', '["v"]', 'to intwine wrap together, wreath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1634}/H9023/[H1633]', 'inflected', 'heb', 'גֶּרֶם', '["gerem"]', '["limbs/ its"]', '["n-m"]', 'a bone (as the skeleton of the body); hence, self, i.e. (figuratively) very bone, strong, top.', 'from 1633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4300}/[H2904]', 'inflected', 'heb', 'מְטִיל', '["mᵉṭîyl"]', '["[are] like/ a rod of"]', '["n-m"]', 'an iron bar (as forged) bar.', 'from 2904 in the sense of hammering out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6213H}/H9033/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["the/ [one who] made/ it"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0944}/[H2981]', 'lemma', 'heb', 'בּוּל', '["bûwl"]', '["[the] beast[s] of"]', '["n-m"]', 'produce (of the earth, etc.) food, stock.', 'for 2981;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6628>', 'opaque', 'heb', 'צֶאֶל', '["tseʼel"]', '["thorny lotus plants"]', '["n-m"]', 'the lotus tree shady tree.', 'from an unused root meaning to be slender;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7070H}/[H7069]', 'lemma', 'heb', 'קָנֶה', '["qâneh"]', '["[the] reed of","[the] reed[s]","a reed","calamus","reed","reed[s]"]', '["n-m"]', 'a reed (as erect); by resemblance a rod (especially for measuring), shaft, tube, stem, the radius (of the arm), beam (of a steelyard) balance, bone, branch, calamus, cane, reed, × spearman, stalk.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1207}/[H1206]', 'inflected', 'heb', 'בִּצָּה', '["bitstsâh"]', '["and/ swamp"]', '["n-f"]', 'a swamp fen, mire(-ry place).', 'intensive from 1206;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5526B}/H9033/[H5526]', 'inflected', 'heb', 'סָכַךְ', '["çâkak"]', '["they cover/ it"]', '["v"]', 'properly, to entwine as a screen; by implication, to fence in, cover over, (figuratively) protect cover, defence, defend, hedge in, join together, set, shut up.', 'or שָׂכַךְ; (Exodus 33:22), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6752}/H9023/[H6751]', 'inflected', 'heb', 'צֵלֶל', '["tsêlel"]', '["shade/ its"]', '["n-m"]', 'shade shadow.', 'from 6751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6155H}/[H6148]', 'lemma', 'heb', 'עָרָב', '["ʻârâb"]', '["[the] poplars of","poplars"]', '["n-f"]', 'a willow (from the use of osiers as wattles) willow.', 'from 6148;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4170}/[H3369]', 'inflected', 'heb', 'מוֹקֵשׁ', '["môwqêsh"]', '["with/ snares"]', '["n-m"]', 'a noose (for catching animals) (literally or figuratively); by implication, a hook (for the nose) be ensnared, gin, (is) snare(-d), trap.', 'or מֹקֵשׁ; from 3369;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0639H}/[H599]', 'lemma', 'heb', 'אַף', '["ʼaph"]', '["a nose"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2443}/[H2442]', 'inflected', 'heb', 'חַכָּה', '["chakkâh"]', '["with/ a fish hook"]', '["n-f"]', 'a hook (as adhering) angle, hook.', 'probably from 2442;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2256M}/[H2254]', 'inflected', 'heb', 'חֶבֶל', '["chebel"]', '["and/ by/ [the] cords of","and/ with/ a cord"]', '["n-m"]', 'a rope (as twisted), especially a measuring line; by implication, a district or inheritance (as measured); or a noose (as of cords); figuratively, a company (as if tied together); a throe (especially of parturition); also ruin band, coast, company, cord, country, destruction, line, lot, pain, pang, portion, region, rope, snare, sorrow, tackling.', 'or חֵבֶל; from 2254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8257}/[H8257]', 'lemma', 'heb', 'שָׁקַע', '["shâqaʻ"]', '["I will make settle","it will sink","will you hold down?"]', '["v"]', 'to subside; by implication, to be overflowed, cease; causatively, to abate, subdue make deep, let down, drown, quench, sink.', '(abbreviated Amos 8:8); a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7760H}/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["¿/ will you put"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0100}/[H98]', 'lemma', 'heb', 'אַגְמוֹן', '["ʼagmôwn"]', '["a cord"]', '["n-m"]', 'a rush (as growing there); collectively a rope of rushes bulrush, caldron, hook, rush.', 'from the same as 98; a marshy pool (others from a different root, a kettle); by implication');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3895H>/H9023', 'opaque', 'heb', 'לְחִי', '["lᵉchîy"]', '["cheeks/ his","jaw/ its"]', '["n-m"]', 'the cheek (from its fleshiness); hence, the jaw-bone cheek (bone), jaw (bone).', 'from an unused root meaning to be soft;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7235A}/[H7235]', 'inflected', 'heb', 'רָבָה', '["râbâh"]', '["¿/ will it multiply"]', '["v"]', 'to increase (in whatever respect) (bring in) abundance (× -antly), archer (by mistake for 7232), be in authority, bring up, × continue, enlarge, excel, exceeding(-ly), be full of, (be, make) great(-er, -ly, × -ness), grow up, heap, increase, be long, (be, give, have, make, use) many (a time), (any, be, give, give the, have) more (in number), (ask, be, be so, gather, over, take, yield) much (greater, more), (make to) multiply, nourish, plenty(-eous), × process (of time), sore, store, thoroughly, very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3772H}/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["¿/ will it make"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7832}/[H7832]', 'inflected', 'heb', 'שָׂחַק', '["sâchaq"]', '["¿/ will you play"]', '["v"]', 'to laugh (in pleasure or detraction); by implication, to play deride, have in derision, laugh, make merry, mock(-er), play, rejoice, (laugh to) scorn, be in (make) sport.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6833}/[H6852]', 'inflected', 'heb', 'צִפּוֹר', '["tsippôwr"]', '["like <the>/ bird","like/ a bird","like/ birds"]', '["n-f"]', 'a little bird (as hopping) bird, fowl, sparrow.', 'or צִפֹּר; from 6852;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7194}/H9033/[H7194]', 'inflected', 'heb', 'קָשַׁר', '["qâshar"]', '["and/ will you bind?/ it"]', '["v"]', 'to tie, physically (gird, confine, compact) or mentally (in love, league) bind (up), (make a) conspire(-acy, -ator), join together, knit, stronger, work (treason).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5291}/H9021/[H5288]', 'inflected', 'heb', 'נַעֲרָה', '["naʻărâh"]', '["for/ girls/ your","of/ maids/ your"]', '["n-f"]', 'a girl (from infancy to adolescence) damsel, maid(-en), young (woman).', 'feminine of 5288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2271}/[H2266]', 'lemma', 'heb', 'חַבָּר', '["chabbâr"]', '["partners"]', '["n-m"]', 'a partner companion.', 'from 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2673}/H9033/[H2086]', 'inflected', 'heb', 'חָצָה', '["châtsâh"]', '["will they divide?/ it"]', '["v"]', 'to cut or split in two; to halve divide, × live out half, reach to the midst, participle', 'a primitive root (compare 2086));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3669B}/[H3667]', 'lemma', 'heb', 'כְּנַעַנִי', '["Kᵉnaʻanîy"]', '["a Canaanite","merchants"]', '["n-m"]', 'a Kenaanite or inhabitant of Kenaan; by implication, a pedlar (the Canaanites standing for their neighbors the Ishmaelites, who conducted mercantile caravans) Canaanite, merchant, trafficker.', 'patrial from 3667;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H4390}/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["¿/ will you fill"]', '["v"]', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly.', 'or מָלָא; (Esther 7:5), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7905}/[H7900]', 'inflected', 'heb', 'שֻׂכָּה', '["sukkâh"]', '["with/ harpoons"]', '["n-f"]', 'a dart (as pointed like a thorn) barbed iron.', 'feminine of 7900 in the sense of 7899;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6767B}/[H6750]', 'inflected', 'heb', 'צְלָצַל', '["tsᵉlâtsal"]', '["and/ with/ a spear of"]', '["n-m"]', 'a clatter, i.e. (abstractly) whirring (of wings); (concretely) a cricket; also a harpoon (as rattling),a cymbal (as clanging) cymbal, locust, shadowing, spear.', 'from 6750 reduplicated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8431}/H9023/[H3176]', 'inflected', 'heb', 'תּוֹחֶלֶת', '["tôwcheleth"]', '["hope/ his"]', '["n-f"]', 'expectation hope.', 'from 3176;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2904}/[H2904]', 'lemma', 'heb', 'טוּל', '["ṭûwl"]', '["everyone is thrown down","have they been thrown out","he threw","he will be thrown down","it is thrown"]', '["v"]', 'to pitch over or reel; hence (transitively) to cast down or out carry away, (utterly) cast (down, forth, out), send out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5782}/H9033/[H5782]', 'inflected', 'heb', 'עוּר', '["ʻûwr"]', '["I have stirred up/ him","he will rouse/ it"]', '["v"]', 'to wake (literally or figuratively) (a-) wake(-n, up), lift up (self), × master, raise (up), stir up (self).', 'a primitive root (rather identical with through the idea of opening the eyes);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0907}/H9023/[H908]', 'inflected', 'heb', 'בַּד', '["bad"]', '["bars/ his","empty boasts/ its","limbs/ its"]', '["n-m"]', 'a brag or lie; also a liar liar, lie.', 'from 908;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2433}/[H2580]', 'inflected', 'heb', 'חִין', '["chîyn"]', '["and/ [the] grace of"]', '["n-m"]', 'beauty comely.', 'another form for 2580;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3718}/[H3717]', 'inflected', 'heb', 'כֶּפֶל', '["kephel"]', '["in/ [the] doubling of"]', '["n-m"]', 'a duplicate double.', 'from 3717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7448>/H9023', 'opaque', 'heb', 'רֶסֶן', '["reçen"]', '["halter/ its"]', '["n-m"]', 'a halter (as restraining); by implication, the jaw bridle.', 'from an unused root meaning to curb;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8127G}/H9023/[H8150]', 'inflected', 'heb', 'שֵׁן', '["shên"]', '["teeth/ his","teeth/ its"]', '["n-f"]', 'a tooth (as sharp); specifically ivory; figuratively, a cliff crag, × forefront, ivory, × sharp, tooth.', 'from 8150; compare 8143');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1346}/[H1342]', 'lemma', 'heb', 'גַּאֲוָה', '["gaʼăvâh"]', '["<of> pride","[the] pride of","pride"]', '["n-f"]', 'arrogance or majesty; by implication, (concretely) ornament excellency, haughtiness, highness, pride, proudly, swelling.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5846>/H9023', 'opaque', 'heb', 'עֲטִישָׁה', '["ʻăṭîyshâh"]', '["sneezing<s>/ its"]', '["n-f"]', 'sneezing sneezing.', 'from an unused root meaning to sneeze;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6079}/[H5774]', 'inflected', 'heb', 'עַפְעַף', '["ʻaphʻaph"]', '["[are] like/ [the] eyelids of"]', '["n-m"]', 'an eyelash (as fluttering); figuratively, morning ray dawning, eye-lid.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3590}/[H3589]', 'lemma', 'heb', 'כִידוֹד', '["kîydôwd"]', '["sparks of"]', '["n-m"]', 'properly, something struck off, i.e. a spark (as struck) spark.', 'from the same as 3589 (compare 3539);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5156}/H9023/[H5170]', 'inflected', 'heb', 'נְחִיר', '["nᵉchîyr"]', '["from/ nostrils/ its"]', '["n-m"]', 'a nostril (dual) nostrils.', 'from the same as 5170;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1731}/[H1730]', 'inflected', 'heb', 'דּוּד', '["dûwd"]', '["like/ a pot"]', '["n-m"]', 'a pot (for boiling); also (by resemblance of shape) a basket basket, caldron, kettle, (seething) pot.', 'from the same as 1730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0100}/[H98]', 'inflected', 'heb', 'אַגְמוֹן', '["ʼagmôwn"]', '["and/ bulrush","and/ bulrush[es]"]', '["n-m"]', 'a rush (as growing there); collectively a rope of rushes bulrush, caldron, hook, rush.', 'from the same as 98; a marshy pool (others from a different root, a kettle); by implication');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3857}/[H3857]', 'lemma', 'heb', 'לָהַט', '["lâhaṭ"]', '["[those that] devour","[which] it sets ablaze","flaming","it burned up","it kindles"]', '["v"]', 'properly, to lick, i.e. (by implication) to blaze burn (up), set on fire, flaming, kindle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3851}/[H3851]', 'inflected', 'heb', 'לַהַב', '["lahab"]', '["and/ a flame","and/ a flame of"]', '["n-m"]', 'a flash; figuratively, a sharply polished blade or point of a weapon blade, bright, flame, glittering.', 'from an usused root meaning to gleam;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6677A}/H9023/[H6696]', 'inflected', 'heb', 'צַוָּאר', '["tsavvâʼr"]', '["in/ neck/ its"]', '["n-m"]', 'the back of the neck (as that on which burdens are bound) neck.', 'or צַוָּר; (Nehemiah 3:5), or צַוָּרֹןlemma צַוָּרן missing vowel, corrected to צַוָּרֹן; (Song of Solomon 4:9), or (feminine) צַוָּארָה; (Micah 2:3), intensively from 6696 in the sense of binding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1750}/[H1750]', 'lemma', 'heb', 'דּוּץ', '["dûwts"]', '["it leaps"]', '["v"]', 'to leap be turned.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1670}/[H1669]', 'lemma', 'heb', 'דְּאָבָה', '["dᵉʼâbâh"]', '["dismay"]', '["n-f"]', 'properly, pining; by analogy, fear sorrow.', 'from 1669;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4651}/[H5307]', 'lemma', 'heb', 'מַפָּל', '["mappâl"]', '["[the] hanging parts of"]', '["n-m"]', 'a falling off, i.e. chaff; also something pendulous, i.e. a flap flake, refuse.', 'from 5307;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3332J}/[H3332]', 'inflected', 'heb', 'יָצַק', '["yâtsaq"]', '["and/ hard"]', '["v"]', 'properly, to pour out (transitive or intransitive); by implication, to melt or cast as metal; by extension, to place firmly, to stiffen or grow hard cast, cleave fast, be (as) firm, grow, be hard, lay out, molten, overflow, pour (out), run out, set down, stedfast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6400}/[H6398]', 'inflected', 'heb', 'פֶּלַח', '["pelach"]', '["[is] like/ [the] slice of","like/ a mill-stone"]', '["n-f"]', 'a slice piece.', 'from 6398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7613}/H9023/[H5375]', 'inflected', 'heb', 'שְׂאֵת', '["sᵉʼêth"]', '["from/ loftiness/ his","from/ uprising/ its"]', '["n-f"]', 'an elevation or leprous scab; figuratively, elation or cheerfulness; exaltation in rank or character be accepted, dignity, excellency, highness, raise up self, rising.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7667}/[H7665]', 'inflected', 'heb', 'שֶׁבֶר', '["sheber"]', '["from/ crashing<s>"]', '["n-m"]', 'a fracture, figuratively, ruin; specifically, a solution (of a dream) affliction, breach, breaking, broken(-footed, -handed), bruise, crashing, destruction, hurt, interpretation, vexation.', 'or שֵׁבֶר; from 7665;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4551B}/[H5265]', 'lemma', 'heb', 'מַסָּע', '["maççâʻ"]', '["a dart"]', '["n-m"]', 'a missile (spear or arrow); also a quarry (whence stones are, as it were, ejected) before it was brought, dart.', 'from 5265 in the sense of projecting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8302A}/[H8281]', 'inflected', 'heb', 'שִׁרְיוֹן', '["shiryôwn"]', '["and/ a javelin"]', '["n-m n-f"]', 'a corslet (as if twisted) breastplate, coat of mail, habergeon, harness. See 5630.', 'or שִׁרְיֹן; and שִׁרְיָן; also (feminine) שִׁרְיָה; and שִׁרְיֹנָה; from 8281 in the original sense of turning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7539}/[H7538]', 'lemma', 'heb', 'רִקָּבוֹן', '["riqqâbôwn"]', '["rottenness"]', '["n-m"]', 'decay (by caries) rotten.', 'from 7538;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1272}/H9033/[H1272]', 'inflected', 'heb', 'בָּרַח', '["bârach"]', '["it makes flee/ it"]', '["v"]', 'to bolt, i.e. figuratively, to flee suddenly chase (away); drive away, fain, flee (away), put to flight, make haste, reach, run away, shoot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7179}/[H7197]', 'inflected', 'heb', 'קַשׁ', '["qash"]', '["[will become] <into>/ stubble","into/ chaff"]', '["n-m"]', 'straw (as dry) stubble.', 'from 7197;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8455>', 'opaque', 'heb', 'תּוֹתָח', '["tôwthâch"]', '["a club"]', '["n-m"]', 'a club darts.', 'from an unused root meaning to smite;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7494}/[H7493]', 'inflected', 'heb', 'רַעַשׁ', '["raʻash"]', '["to/ [the] shaking of"]', '["n-m"]', 'vibration, bounding, uproar commotion, confused noise, earthquake, fierceness, quaking, rattling, rushing, shaking.', 'from 7493;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3591}/[H3589]', 'lemma', 'heb', 'כִּידוֹן', '["kîydôwn"]', '["a javelin"]', '["n-m"]', 'properly, something to strike with, i.e. a dart lance, shield, spear, target.', 'from the same as 3589; (perhaps smaller than 2595)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2303}/[H2300]', 'lemma', 'heb', 'חַדּוּד', '["chaddûwd"]', '["[are] sharp points of"]', '["a"]', 'a point sharp.', 'from 2300;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2916>', 'opaque', 'heb', 'טִיט', '["ṭîyṭ"]', '["clay","mud"]', '["n-m"]', 'mud or clay; figuratively, calamity clay, dirt, mire.', 'from an unused root meaning apparently to be sticky (rather perhaps a demonstrative); from 2894, through the idea of dirt to be swept away);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5518A}/[H5518]', 'inflected', 'heb', 'סִיר', '["çîyr"]', '["like <the>/ pot"]', '["n-m"]', 'a pot; also a thorn (as springing up rapidly); by implication, a hook caldron, fishhook, pan, (wash-)pot, thorn.', 'or (feminine) סִירָה; or סִרָה; (Jeremiah 52:18), from a primitive root meaning to boil up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4688}/[H6683]', 'lemma', 'heb', 'מְצוֹלָה', '["mᵉtsôwlâh"]', '["[the] deep","[the] depths of","depth"]', '["n-f"]', 'a deep place (of water or mud) bottom, deep, depth.', 'or מְצֹלָה; also מְצוּלָה; or מְצֻלָה; from the same as 6683;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4841}/[H4840]', 'inflected', 'heb', 'מֶרְקָחָה', '["merqâchâh"]', '["like <the>/ pot of ointment"]', '["n-f"]', 'abstractly, a seasoning (with spicery); concretely, an unguentkettle (for preparing spiced oil) pot of ointment, × well.', 'feminine of 4840;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7872}/[H7869]', 'inflected', 'heb', 'שֵׂיבָה', '["sêybâh"]', '["to/ grey hair"]', '["n-f"]', 'old age (be) gray (grey hoar,-y) hairs (head,-ed), old age.', 'feminine of 7869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4915A}/H9023/[H4910]', 'inflected', 'heb', 'מֹשֶׁל', '["môshel"]', '["likeness/ its"]', '["n-m"]', 'empire; a parallel dominion, like.', '(1) from 4910; (2) from 4911;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2844A}/[H2865]', 'lemma', 'heb', 'חַת', '["chath"]', '["fear"]', '["n-m"]', 'concretely, crushed; also afraid; abstractly, terror broken, dismayed, dread, fear.', 'from 2865;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7830>\', 'opaque', 'heb', 'שַׁחַץ', '["shachats"]', '["pride"]', '["n-m"]', 'haughtiness (as evinced by the attitude) × lion, pride.', 'from an unused root apparently meaning to strut;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4209}/[H2161]', 'lemma', 'heb', 'מְזִמָּה', '["mᵉzimmâh"]', '["[the] purposes of","a purpose","a scheme","discretion","evil devices","plots"]', '["n-f"]', 'a plan, usually evil (machination), sometimes good (sagacity) (wicked) device, discretion, intent, witty invention, lewdness, mischievous (device), thought, wickedly.', 'from 2161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8088B}/[H8085]', 'inflected', 'heb', 'שֵׁמַע', '["shêmaʻ"]', '["to/ [the] hearing of"]', '["n-m"]', 'something heard, i.e. a sound, rumor, announcement; abstractly, audience bruit, fame, hear(-ing), loud, report, speech, tidings.', 'from 8085;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0665>\', 'inflected', 'heb', 'ואפר פ', '["va./''E.fer"]', '["and/ ash[es]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7622}/[H7617]', 'lemma', 'heb', 'שְׁבוּת', '["shᵉbûwth"]', '["[the] captivity of"]', '["n-f"]', 'exile, concretely, prisoners; figuratively, a former state of prosperity captive(-ity).', 'or שְׁבִית; from 7617;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6419}/H9043/[H6419]', 'inflected', 'heb', 'פָּלַל', '["pâlal"]', '["when/ prayed/ he"]', '["v"]', 'to judge (officially or mentally); by extension, to intercede, pray intreat, judge(-ment), (make) pray(-er, -ing), make supplication.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5110}/[H5110]', 'inflected', 'heb', 'נוּד', '["nûwd"]', '["and/ it will sway","and/ they showed sympathy"]', '["v"]', 'to nod, i.e. waver; figuratively, to wander, flee, disappear; also (from shaking the head in sympathy), to console, deplore, or (from tossing the head in scorn) taunt bemoan, flee, get, mourn, make to move, take pity, remove, shake, skip for joy, be sorry, vagabond, way, wandering.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7225G}/H9023/[H7218]', 'inflected', 'heb', 'רֵאשִׁית', '["rêʼshîyth"]', '["more than/ beginning/ his","more than/ beginning/ its"]', '["n-f"]', 'the first, in place, time, order or rank (specifically, a firstfruit) beginning, chief(-est), first(-fruits, part, time), principal thing.', 'from the same as 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7658}/[H7651]', 'lemma', 'heb', 'שִׁבְעָנָה', '["shibʻânâh"]', '["seven"]', '["n"]', 'seven seven.', 'prolonged for the masculine of 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3224}/[H3117]', 'lemma', 'heb', 'יְמִימָה', '["Yᵉmîymâh"]', '["Jemimah"]', '["n-pr-f"]', 'Jemimah, one of Job''s daughters Jemimah.', 'perhaps from the same as 3117; properly, warm, i.e. affectionate; hence, dove (compare 3123);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7103}/[H7102]', 'lemma', 'heb', 'קְצִיעָה', '["Qᵉtsîyʻâh"]', '["Keziah"]', '["n-pr-m"]', 'Ketsiah, a daughter of Job Kezia.', 'the same as 7102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7163}/[H7161]', 'lemma', 'heb', 'קֶרֶן הַפּוּךְ', '["qeren hap-pûwk"]', '["Happuch","Keren-"]', '["n-pr-f"]', 'Keren-hap-Puk, one of Job''s daughters Keren-happuch.', 'from 7161 and 6320; horn of cosmetic;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0251G}/H9028\/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["brothers/ their"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4186}/[H3427]', 'inflected', 'heb', 'מוֹשָׁב', '["môwshâb"]', '["and/ in/ [the] seat of"]', '["n-m"]', 'a seat; figuratively, a site; abstractly, a session; by extension an abode (the place or the time); by implication, population assembly, dwell in, dwelling(-place), wherein (that) dwelt (in), inhabited place, seat, sitting, situation, sojourning.', 'or מֹשָׁב; from 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8451}/H9023/[H3384]', 'inflected', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["and/ in/ law/ his"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8362}/[H8362]', 'lemma', 'heb', 'שָׁתַל', '["shâthal"]', '["[is] planted","[it is] planted","[they are] planted","[was] planted","planted"]', '["v"]', 'to transplant plant.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5929}/H9023/[H5927]', 'inflected', 'heb', 'עָלֶה', '["ʻâleh"]', '["and/ leafage/ its"]', '["n-m"]', 'a leaf (as coming up on a tree); collectively, foliage branch, leaf.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4671}/[H4160]', 'inflected', 'heb', 'מֹץ', '["môts"]', '["[they are] like the/ chaff","like <the>/ chaff","like/ chaff","like/ chaff of"]', '["n-m"]', 'chaff (as pressed out, i.e. winnowed or (rather) threshed loose) chaff.', 'or מוֹץ; (Zephaniah 2:2), from 4160;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7283}/[H7283]', 'lemma', 'heb', 'רָגַשׁ', '["râgash"]', '["do they plot"]', '["v"]', 'to be tumultuous rage.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7385}/[H7324]', 'lemma', 'heb', 'רִיק', '["rîyq"]', '["emptiness","vanity"]', '["n-m"]', 'emptiness; figuratively, a worthless thing; adverbially, in vain empty, to no purpose, (in) vain (thing), vanity.', 'from 7324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7336}/[H7336]', 'inflected', 'heb', 'רָזַן', '["râzan"]', '["and/ rulers"]', '["v"]', 'probably to be heavy, i.e. (figuratively) honorable prince, ruler.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4147}/H9028/[H3256]', 'inflected', 'heb', 'מוֹסֵר', '["môwçêr"]', '["fetters/ their"]', '["n-m"]', 'properly, chastisement, i.e. (by implication) a halter; figuratively, restraint band, bond.', 'also (in plural) feminine מוֹסֵרָה; or מֹסְרָה; from 3256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5688}/H9028/[H5687]', 'inflected', 'heb', 'עֲבֹת', '["ʻăbôth"]', '["ropes/ their"]', '["n"]', 'something intwined, i.e. a string, wreath or foliage band, cord, rope, thick bough (branch), wreathen (chain).', 'or עֲבוֹת; or (feminine) עֲבֹתָה; the same as 5687;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2740}/H9023/[H2734]', 'inflected', 'heb', 'חָרוֹן', '["chârôwn"]', '["and/ in/ fury/ his"]', '["n-m"]', 'a burning of anger sore displeasure, fierce(-ness), fury, (fierce) wrath(-ful).', 'or (shortened) חָרֹן; from 2734;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0926}/H9038/[H926]', 'inflected', 'heb', 'בָּהַל', '["bâhal"]', '["he terrifies/ them","you will terrify/ them"]', '["v"]', 'to tremble inwardly (or palpitate), i.e. (figuratively) be (causative, make) (suddenly) alarmed or agitated; by implication to hasten anxiously be (make) affrighted (afraid, amazed, dismayed, rash), (be, get, make) haste(-n, -y, -ily), (give) speedy(-ily), thrust out, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5258B}/[H5258]', 'lemma', 'heb', 'נָסַךְ', '["nâçak"]', '["I have installed","I was installed"]', '["v"]', 'to pour out, especially a libation, or to cast (metal); by analogy, to anoint a king cover, melt, offer, (cause to) pour (out), set (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0272}/H9021/[H270]', 'inflected', 'heb', 'אֲחֻזָּה', '["ʼăchuzzâh"]', '["and/ possession/ your"]', '["n-f"]', 'something seized, i.e. a possession (especially of land) possession.', 'feminine passive participle from 270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7489B}/H9038/[H7489]', 'inflected', 'heb', 'רָעַע', '["râʻaʻ"]', '["you will break/ them"]', '["v"]', 'properly, to spoil (literally, by breaking to pieces); figuratively, to make (or be) good for nothing, i.e. bad (physically, socially or morally) afflict, associate selves (by mistake for 7462), break (down, in pieces), displease, (be, bring, do) evil (doer, entreat, man), show self friendly (by mistake for 7462), do harm, (do) hurt, (behave self, deal) ill, × indeed, do mischief, punish, still, vex, (do) wicked (doer, -ly), be (deal, do) worse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3627}/[H3615]', 'inflected', 'heb', 'כְּלִי', '["kᵉlîy"]', '["like/ a vessel","like/ a vessel of","like/ baggage<s> of"]', '["n-m"]', 'something prepared, i.e. any apparatus (as an implement, utensil, dress, vessel or weapon) armour(-bearer), artillery, bag, carriage, furnish, furniture, instrument, jewel, that is made of, × one from another, that which pertaineth, pot, psaltery, sack, stuff, thing, tool, vessel, ware, weapon, whatsoever.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5310A}/H9038/[H5310]', 'inflected', 'heb', 'נָפַץ', '["nâphats"]', '["you will smash/ them"]', '["v"]', 'to dash to pieces, or scatter be beaten in sunder, break (in pieces), broken, dash (in pieces), cause to be discharged, dispersed, be overspread, scatter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7461B}/[H7460]', 'inflected', 'heb', 'רַעַד', '["raʻad"]', '["with/ trembling"]', '["n-m n-f"]', 'a shudder trembling.', 'or (feminine) רְעָדָהxlit rᵉâdâh corrected to rᵉʻâdâh; from 7460;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4210}/[H2167]', 'lemma', 'heb', 'מִזְמוֹר', '["mizmôwr"]', '["a psalm"]', '["n-m"]', 'properly, instrumental music; by implication, a poem set to notes psalm.', 'from 2167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5315G}/H9020/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["[belongs] to/ self/ my","for/ self/ my","of/ self/ my","to/ self/ my"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5542}/[H5541]', 'lemma', 'heb', 'סֶלָה', '["çelâh"]', '["Selah"]', '["v"]', 'suspension (of music), i.e. pause Selah.', 'from 5541;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3462}/H9012/[H3462]', 'inflected', 'heb', 'יָשֵׁן', '["yâshên"]', '["and/ I slept/ !"]', '["v"]', 'properly, to be slack or languid, i.e. (by implication) sleep (figuratively, to die); also to grow old, stale or inveterate old (store), remain long, (make to) sleep.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5564}/H9030/[H5564]', 'inflected', 'heb', 'סָמַךְ', '["çâmak"]', '["he sustains/ me","it sustained/ me","sustain/ me","you will sustain/ me"]', '["v"]', 'to prop (literally or figuratively); reflexively, to lean upon or take hold of (in a favorable or unfavorable sense) bear up, establish, (up-) hold, lay, lean, lie hard, put, rest self, set self, stand fast, stay (self), sustain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5058}/[H5059]', 'inflected', 'heb', 'נְגִינָה', '["nᵉgîynâh"]', '["with/ stringed instruments"]', '["n-f"]', 'properly, instrumental music; by implication, a stringed instrument; by extension, a poem set to music; specifically, an epigram stringed instrument, musick, Neginoth (plural), song.', 'or נְגִינַת; (Psalm 61:title), from 5059;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7121G}/H9040/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["when/ call/ I"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8605}/H9020/[H6419]', 'inflected', 'heb', 'תְּפִלָּה', '["tᵉphillâh"]', '["prayer/ my"]', '["n-f"]', 'intercession, supplication; by implication, a hymn prayer.', 'from 6419;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3639}/[H3637]', 'inflected', 'heb', 'כְּלִמָּה', '["kᵉlimmâh"]', '["<into>/ ignominy","[become] <into>/ ignominy"]', '["n-f"]', 'disgrace confusion, dishonour, reproach, shame.', 'from 3637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0157G}/H9013/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["will you love?/ !"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3824}/H9026/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["in/ heart/ your"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4904}/H9026/[H7901]', 'inflected', 'heb', 'מִשְׁכָּב', '["mishkâb"]', '["bed/ your"]', '["n-m"]', 'a bed (figuratively, a bier); abstractly, sleep; by euphemism, carnal intercourse bed(-chamber), couch, lieth (lying) with.', 'from 7901;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375Q}/H9012/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["lift up/ !"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3820A}/H9020/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["[was] in/ heart/ my","in/ heart/ my"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1715}/H9028/[H1711]', 'inflected', 'heb', 'דָּגָן', '["dâgân"]', '["<of> [when] grain/ their","grain/ their"]', '["n-m"]', 'properly, increase, i.e. grain corn (floor), wheat.', 'from 1711;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8492}/H9028/[H3423]', 'inflected', 'heb', 'תִּירוֹשׁ', '["tîyrôwsh"]', '["and/ new wine/ their"]', '["n-m"]', 'must or fresh grape-juice (as just squeezed out); by implication (rarely) fermented wine (new, sweet) wine.', 'or תִּירֹשׁ; from 3423 in the sense of expulsion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3462}/[H3462]', 'inflected', 'heb', 'יָשֵׁן', '["yâshên"]', '["and/ I may sleep"]', '["v"]', 'properly, to be slack or languid, i.e. (by implication) sleep (figuratively, to die); also to grow old, stale or inveterate old (store), remain long, (make to) sleep.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3427}/H9030/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["he has caused to dwell/ me","you caused to dwell/ me"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5155}/[H2485]', 'inflected', 'heb', 'נְחִילָה', '["nᵉchîylâh"]', '["the/ flutes"]', '["n-f"]', 'a flute (plural) Nehiloth.', 'probably denominative from 2485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0995}/H9012/[H995]', 'inflected', 'heb', 'בִּין', '["bîyn"]', '["consider/ !"]', '["v"]', 'to separate mentally (or distinguish), i.e.(generally) understand attend, consider, be cunning, diligently, direct, discern, eloquent, feel, inform, instruct, have intelligence, know, look well to, mark, perceive, be prudent, regard, (can) skill(-full), teach, think, (cause, make to, get, give, have) understand(-ing), view, (deal) wise(-ly, man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1901>/H9020', 'opaque', 'heb', 'הָגִיג', '["hâgîyg"]', '["sighing/ my"]', '["n-m"]', 'properly, a murmur, i.e. complaint meditation, musing.', 'from an unused root akin to 1897;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7181}/H9012/[H7181]', 'inflected', 'heb', 'קָשַׁב', '["qâshab"]', '["be attentive/ !","pay attention to/ !","pay attention/ !"]', '["v"]', 'to prick up the ears, i.e. hearken attend, (cause to) hear(-ken), give heed, incline, mark (well), regard.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7773}/H9020/[H7768]', 'inflected', 'heb', 'שֶׁוַע', '["shevaʻ"]', '["cry for help/ my"]', '["v"]', 'a halloo cry.', 'from 7768;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0430G}/H9020/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["and/ God/ my"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1481A}/H9031/[H1481]', 'inflected', 'heb', 'גּוּר', '["gûwr"]', '["it sojourns with/ you"]', '["v"]', 'properly, to turn aside from the road (for a lodging or any other purpose), i.e. sojourn (as a guest); also to shrink, fear (as in a strange place); also to gather for hostility (as afraid) abide, assemble, be afraid, dwell, fear, gather (together), inhabitant, remain, sojourn, stand in awe, (be) stranger, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4820}/[H7411]', 'inflected', 'heb', 'מִרְמָה', '["mirmâh"]', '["and/ deceit","and/ deceit<s>"]', '["n-f"]', 'fraud craft, deceit(-ful, -fully), false, feigned, guile, subtilly, treachery.', 'from 7411 in the sense of deceiving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3374}/H9021/[H3373]', 'inflected', 'heb', 'יִרְאָה', '["yirʼâh"]', '["in/ fear/ your"]', '["n-f"]', 'fear (also used as infinitive); morally, reverence × dreadful, × exceedingly, fear(-fulness).', 'feminine of 3373;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8324}/H9020/[H8324]', 'inflected', 'heb', 'שָׁרַר', '["shârar"]', '["enemies/ my"]', '["n-m"]', 'to be hostile (only active participle an opponent) enemy.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7130H}/H9028/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["inner being/ their"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1627}/H9028/[H1641]', 'inflected', 'heb', 'גָּרוֹן', '["gârôwn"]', '["throat/ their"]', '["n-m"]', 'the throat (as roughened by swallowing) × aloud, mouth, neck, throat.', 'or (shortened) גָּרֹן; from 1641; (compare 1621)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3956G}/H9028/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["tongue/ their"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2505B}/H9013/[H2505]', 'inflected', 'heb', 'חָלַק', '["châlaq"]', '["they speak flattery/ !"]', '["v"]', 'to be smooth (figuratively); by implication (as smooth stones were used for lots) to apportion or separate deal, distribute, divide, flatter, give, (have, im-) part(-ner), take away a portion, receive, separate self, (be) smooth(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0816}/H9038/[H816]', 'inflected', 'heb', 'אָשַׁם', '["ʼâsham"]', '["hold guilty/ them"]', '["v"]', 'to be guilty; by implication to be punished or perish × certainly, be(-come, made) desolate, destroy, × greatly, be(-come, found, hold) guilty, offend (acknowledge offence), trespass.', 'or אָשֵׁם; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4156}/H9028/[H3289]', 'inflected', 'heb', 'מוֹעֵצָה', '["môwʻêtsâh"]', '["from/ own schemes/ their","from/ schemes/ their"]', '["n-f"]', 'a purpose counsel, device.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5080}/H9038/[H5080]', 'inflected', 'heb', 'נָדַח', '["nâdach"]', '["I banished/ them","I have banished/ them","I will banish/ them","banish/ them","he had banished/ them","you have banished/ them"]', '["v"]', 'to push off; used in a great variety of applications, literally and figuratively (to expel, mislead, strike, inflict, etc.) banish, bring, cast down (out), chase, compel, draw away, drive (away, out, quite), fetch a stroke, force, go away, outcast, thrust away (out), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5970}/[H5970]', 'inflected', 'heb', 'עָלַץ', '["ʻâlats"]', '["and/ I will exult","and/ let them exult"]', '["v"]', 'to jump for joy, i.e. exult be joyful, rejoice, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6793C}/[H6791]', 'inflected', 'heb', 'צִנָּה', '["tsinnâh"]', '["like <the>/ shield"]', '["n-f"]', 'a hook (as pointed); also a (large) shield (as if guarding by prickliness); also cold (as piercing) buckler, cold, hook, shield, target.', 'feminine of 6791;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5849A}/H9033/[H5849]', 'inflected', 'heb', 'עָטַר', '["ʻâṭar"]', '["you surround/ him"]', '["v"]', 'to encircle (for attack or protection); especially to crown (literally or figuratively) compass, crown.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0639G}/H9021/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["in/ anger/ your"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3198}/H9030/[H3198]', 'inflected', 'heb', 'יָכַח', '["yâkach"]', '["you rebuke/ me"]', '["v"]', 'to be right (i.e. correct); reciprocal, to argue; causatively, to decide, justify or convict appoint, argue, chasten, convince, correct(-ion), daysman, dispute, judge, maintain, plead, reason (together), rebuke, reprove(-r), surely, in any wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2534}/H9021/[H3179]', 'inflected', 'heb', 'חֵמָה', '["chêmâh"]', '["in/ wrath/ your"]', '["n-f"]', 'heat; figuratively, anger, poison (from its fever) anger, bottles, hot displeasure, furious(-ly, -ry), heat, indignation, poison, rage, wrath(-ful). See 2529.', 'or (Daniel 11:44) חֵמָא; from 3179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3256}/H9030/[H3256]', 'inflected', 'heb', 'יָסַר', '["yâçar"]', '["correct/ me","he has disciplined/ me","may you chasten/ me","they have instructed/ me","you discipline/ me","you have disciplined/ me"]', '["v"]', 'to chastise, literally (with blows) or figuratively (with words); hence, to instruct bind, chasten, chastise, correct, instruct, punish, reform, reprove, sore, teach.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0536}/[H535]', 'lemma', 'heb', 'אֻמְלַל', '["ʼumlal"]', '["[am] frail"]', '["a"]', 'sick weak.', 'from 535;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7495}/H9030/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["heal/ me"]', '["v"]', 'properly, to mend (by stitching), i.e. (figuratively) to cure cure, (cause to) heal, physician, repair, × thoroughly, make whole. See 7503.', 'or רָפָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5315G}/H9020/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["and/ self/ my"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2502A}/H9012/[H2502]', 'inflected', 'heb', 'חָלַץ', '["châlats"]', '["rescue/ !"]', '["v"]', 'to pull off; hence (intensively) to strip, (reflex.) to depart; by implication, to deliver, equip (for fight); present, strengthen arm (self), (go, ready) armed (× man, soldier), deliver, draw out, make fat, loose, (ready) prepared, put off, take away, withdraw self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2143}/H9021/[H2142]', 'inflected', 'heb', 'זֵכֶר', '["zêker"]', '["[is] remembrance of/ you","remembrance/ your"]', '["n-m"]', 'a memento, abstractly recollection (rarely if ever); by implication, commemoration memorial, memory, remembrance, scent.', 'or זֶכֶר; from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0585}/H9020/[H584]', 'inflected', 'heb', 'אֲנָחָה', '["ʼănâchâh"]', '["by/ groaning/ my","with/ groaning/ my"]', '["n-f"]', 'sighing groaning, mourn, sigh.', 'from 584;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7811}/[H7811]', 'lemma', 'heb', 'שָׂחָה', '["sâchâh"]', '["I make swim"]', '["v"]', 'to swim; causatively, to inundate (make to) swim.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4296}/H9020/[H5186]', 'inflected', 'heb', 'מִטָּה', '["miṭṭâh"]', '["bed/ my"]', '["n-f"]', 'a bed (as extended) for sleeping or eating; by analogy, a sofa, litter or bier bed(-chamber), bier.', 'from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1832}/H9020/[H1831]', 'inflected', 'heb', 'דִּמְעָה', '["dimʻâh"]', '["with/ tear[s]/ my"]', '["n-f"]', 'weeping tears.', 'feminine of 1831;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6244}/[H6244]', 'lemma', 'heb', 'עָשֵׁשׁ', '["ʻâshêsh"]', '["it has wasted away","they have wasted away"]', '["v"]', 'probably to shrink, i.e. fail be consumed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6887D}/H9030/[H6887]', 'inflected', 'heb', 'צָרַר', '["tsârar"]', '["opposer/ my","opposers/ my","people have opposed/ me"]', '["v"]', 'to cramp, literally or figuratively, transitive or intransitive adversary, (be in) afflict(-ion), beseige, bind (up), (be in, bring) distress, enemy, narrower, oppress, pangs, shut up, be in a strait (trouble), vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1065}/H9020/[H1058]', 'inflected', 'heb', 'בְּכִי', '["Bᵉkîy"]', '["weeping/ my"]', '["n-m"]', 'a weeping; by analogy, a dripping overflowing, × sore, (continual) weeping, wept.', 'from 1058;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8467}/H9020/[H2603]', 'inflected', 'heb', 'תְּחִנָּה', '["tᵉchinnâh"]', '["supplication/ my"]', '["n-f"]', 'graciousness; causatively, entreaty favour, grace, supplication.', 'from 2603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7692G}/[H7686]', 'lemma', 'heb', 'שִׁגָּיוֹן', '["shiggâyôwn"]', '["a Shiggaion"]', '["n-pr-m"]', 'properly, aberration, i.e. (technically) a dithyramb or rambling poem Shiggaion, Shigionoth.', 'or שִׁגָּיֹנָה; from 7686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3568B>', 'opaque', 'heb', 'כּוּשׁ', '["Kûwsh"]', '["Cush"]', '["n-pr-m n-pr-loc"]', 'Cush (or Ethiopia), the name of a son of Ham, and of his territory; also of an Israelite Chush, Cush, Ethiopia.', 'probably of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7999B}/H9030/[H7999]', 'inflected', 'heb', 'שָׁלַם', '["shâlam"]', '["[one who] is at peace with/ me"]', '["v"]', 'to be safe (in mind, body or estate); figuratively, to be (causatively, make) completed; by implication, to be friendly; by extension, to reciprocate (in various applications) make amends, (make an) end, finish, full, give again, make good, (re-) pay (again), (make) (to) (be at) peace(-able), that is perfect, perform, (make) prosper(-ous), recompense, render, requite, make restitution, restore, reward, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2502A}/H9012/[H2502]', 'inflected', 'heb', 'חָלַץ', '["châlats"]', '["and/ I have rescued/ !"]', '["v"]', 'to pull off; hence (intensively) to strip, (reflex.) to depart; by implication, to deliver, equip (for fight); present, strengthen arm (self), (go, ready) armed (× man, soldier), deliver, draw out, make fat, loose, (ready) prepared, put off, take away, withdraw self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5381}/[H5381]', 'inflected', 'heb', 'נָשַׂג', '["nâsag"]', '["and/ may he overtake [it]"]', '["v"]', 'to reach (literally or figuratively) ability, be able, attain (unto), (be able to, can) get, lay at, put, reach, remove, wax rich, × surely, (over-) take (hold of, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7429}/[H7429]', 'inflected', 'heb', 'רָמַס', '["râmaç"]', '["and/ he may trample","and/ it tramples"]', '["v"]', 'to tread upon (as a potter, in walking or abusively) oppressor, stamp upon, trample (under feet), tread (down, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3519}/H9020/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["and/ glory/ my","and/ honor/ my"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5678}/[H5676]', 'inflected', 'heb', 'עֶבְרָה', '["ʻebrâh"]', '["by/ [the] wrath of","in/ [the] overflowing of","in/ [the] wrath of","in/ wrath","on/ [the] furi<es> of"]', '["n-f"]', 'an outburst of passion anger, rage, wrath.', 'feminine of 5676;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5782}/H9012/[H5782]', 'inflected', 'heb', 'עוּר', '["ʻûwr"]', '["and/ awake/ !"]', '["v"]', 'to wake (literally or figuratively) (a-) wake(-n, up), lift up (self), × master, raise (up), stir up (self).', 'a primitive root (rather identical with through the idea of opening the eyes);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5712}/[H5707]', 'inflected', 'heb', 'עֵדָה', '["ʻêdâh"]', '["and/ [the] congregation","and/ a company of","and/ an assembly of"]', '["n-f"]', 'a stated assemblage (specifically, a concourse, or generally, a family or crowd) assembly, company, congregation, multitude, people, swarm. Compare 5713.', 'feminine of 5707 in the original sense of fixture;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5437G}/H9031/[H5437]', 'inflected', 'heb', 'סָבַב', '["çâbab"]', '["may it surround/ you"]', '["v"]', 'to revolve, surround, or border; used in various applications, literally and figuratively bring, cast, fetch, lead, make, walk, × whirl, × round about, be about on every side, apply, avoid, beset (about), besiege, bring again, carry (about), change, cause to come about, × circuit, (fetch a) compass (about, round), drive, environ, × on every side, beset (close, come, compass, go, stand) round about, inclose, remove, return, set, sit down, turn (self) (about, aside, away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8199}/H9030/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["vindicate/ me"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6664G}/H9020/[H6663]', 'inflected', 'heb', 'צֶדֶק', '["tsedeq"]', '["according to/ righteousness/ my"]', '["n-m"]', 'the right (natural, moral or legal); also (abstractly) equity or (figuratively) prosperity × even, (× that which is altogether) just(-ice), (un-)right(-eous) (cause, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H8537}/H9020/[H8552]', 'inflected', 'heb', 'תֹּם', '["tôm"]', '["and/ according to/ integrity/ my"]', '["n-m"]', 'completeness; figuratively, prosperity; usually (morally) innocence full, integrity, perfect(-ion), simplicity, upright(-ly, -ness), at a venture. See 8550.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1584}/[H1584]', 'lemma', 'heb', 'גָּמַר', '["gâmar"]', '["[who] avenges","has it come to an end?","he has come to an end","he will avenge","may it come to an end"]', '["v"]', 'to end (in the sense of completion or failure) cease, come to an end, fail, perfect, perform.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3559H}/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["and/ may you establish","so/ it may be established","so/ they may be established"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3826}/[H3820]', 'lemma', 'heb', 'לִבָּה', '["libbâh"]', '["[the] hearts of","hearts"]', '["n-f"]', 'the heart heart.', 'feminine of 3820;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3629}/[H3627]', 'inflected', 'heb', 'כִּלְיָה', '["kilyâh"]', '["and/ kidneys"]', '["n-f"]', 'a kidney (as an essential organ); figuratively, the mind (as the interior self) kidneys, reins.', 'feminine of 3627 (only in the plural);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3559A}/H9034/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["and/ he has prepared/ it"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2671}/H9023/[H2686]', 'inflected', 'heb', 'חֵץ', '["chêts"]', '["arrow/ his","arrows/ his","arrows/ its"]', '["n-m"]', 'properly, a piercer, i.e. an arrow; by implication, a wound; figuratively, (of God) thunder-bolt; the shaft of a spear archer, arrow, dart, shaft, staff, wound.', 'from 2686; also by interchange for 6086');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1814}/[H1814]', 'inflected', 'heb', 'דָּלַק', '["dâlaq"]', '["into/ burning [things]"]', '["v"]', 'to flame (literally or figuratively) burning, chase, inflame, kindle, persecute(-or), pursue hotly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2254C}/[H2254]', 'lemma', 'heb', 'חָבַל', '["châbal"]', '["he is in labor with","she was in labor"]', '["v"]', 'to wind tightly (as a rope), i.e. to bind; specifically, by a pledge; figuratively, to pervert, destroy; also to writhe in pain (especially of parturition) × at all, band, bring forth, (deal) corrupt(-ly), destroy, offend, lay to (take a) pledge, spoil, travail, × very, withhold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5999}/H9023/[H5998]', 'inflected', 'heb', 'עָמָל', '["ʻâmâl"]', '["mischief/ his","toil/ his"]', '["n"]', 'toil, i.e. wearing effort; hence, worry, whether of body or mind grievance(-vousness), iniquity, labour, mischief, miserable(-sery), pain(-ful), perverseness, sorrow, toil, travail, trouble, wearisome, wickedness.', 'from 5998;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2555}/H9023/[H2554]', 'inflected', 'heb', 'חָמָס', '["châmâç"]', '["violence/ his"]', '["n-m"]', 'violence; by implication, wrong; by metonymy unjust gain cruel(-ty), damage, false, injustice, × oppressor, unrighteous, violence (against, done), violent (dealing), wrong.', 'from 2554;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6664G}/H9023/[H6663]', 'inflected', 'heb', 'צֶדֶק', '["tsedeq"]', '["according to/ righteousness/ his"]', '["n-m"]', 'the right (natural, moral or legal); also (abstractly) equity or (figuratively) prosperity × even, (× that which is altogether) just(-ice), (un-)right(-eous) (cause, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2167}/[H2168]', 'inflected', 'heb', 'זָמַר', '["zâmar"]', '["and/ I will sing praise to","and/ I will sing praises","and/ make music","and/ we will sing praises","so/ they may sing praises"]', '["v"]', 'properly, to touch the strings or parts of a musical instrument, i.e. play upon it; to make music, accompanied by the voice; hence to celebrate in song and music give praise, sing forth praises, psalms.', 'a primitive root (perhaps identical with 2168 through the idea of striking with the fingers);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1665}/[H1663]', 'inflected', 'heb', 'גִּתִּית', '["Gittîyth"]', '["the/ Gittith"]', '["n-f"]', 'a Gittite harp Gittith.', 'feminine of 1663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1935>/H9021', 'opaque', 'heb', 'הוֹד', '["hôwd"]', '["splendor/ your","vigor/ your"]', '["n-m"]', 'grandeur (i.e. an imposing form and appearance) beauty, comeliness, excellency, glorious, glory, goodly, honour, majesty.', 'from an unused root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5768}/[H5763]', 'lemma', 'heb', 'עוֹלֵל', '["ʻôwlêl"]', '["child","child[ren]","children","children of"]', '["n-m"]', 'a suckling babe, (young) child, infant, little one.', 'or עֹלָל; from 5763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3243J}/[H3243]', 'inflected', 'heb', 'יָנַק', '["yânaq"]', '["and/ suckling-child","and/ suckling-children"]', '["v"]', 'to suck; causatively, to give milk milch, nurse(-ing mother), (give, make to) suck(-ing child, -ling).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7673A}/[H7673]', 'inflected', 'heb', 'שָׁבַת', '["shâbath"]', '["to/ put an end to"]', '["v"]', 'to repose, i.e. desist from exertion; used in many implied relations (causative, figurative or specific) (cause to, let, make to) cease, celebrate, cause (make) to fail, keep (sabbath), suffer to be lacking, leave, put away (down), (make to) rest, rid, still, take away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0676}/H9021/[H6648]', 'inflected', 'heb', 'אֶצְבַּע', '["ʼetsbaʻ"]', '["fingers/ your"]', '["n-f"]', 'something to sieze with, i.e. a finger; by analogy, a toe finger, toe.', 'from the same as 6648 (in the sense of grasping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3559I}/[H3559]', 'lemma', 'heb', 'כּוּן', '["kûwn"]', '["[he] established","[who] established","may it be established","you have established"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2142}/H9033/[H2145]', 'inflected', 'heb', 'זָכַר', '["zâkar"]', '["I remember/ him","I will remember/ him","you will remember/ him"]', '["v"]', 'properly, to mark (so as to be recognized), i.e. to remember; by implication, to mention; to be male × burn (incense), × earnestly, be male, (make) mention (of), be mindful, recount, record(-er), remember, make to be remembered, bring (call, come, keep, put) to (in) remembrance, × still, think on, × well.', 'a primitive root; also as denominative from 2145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6485I}/H9033/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["you will pay attention to/ him"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2637}/H9033/[H2637]', 'inflected', 'heb', 'חָסֵר', '["châçêr"]', '["and/ you have made lack/ him"]', '["v"]', 'to lack; by implication, to fail, want, lessen be abated, bereave, decrease, (cause to) fail, (have) lack, make lower, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5849B}/H9033/[H5849]', 'inflected', 'heb', 'עָטַר', '["ʻâṭar"]', '["you crown/ him"]', '["v"]', 'to encircle (for attack or protection); especially to crown (literally or figuratively) compass, crown.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4910}/H9033/[H4910]', 'inflected', 'heb', 'מָשַׁל', '["mâshal"]', '["rulers/ its","you make rule/ him"]', '["v"]', 'to rule (have, make to have) dominion, governor, × indeed, reign, (bear, cause to, have) rule(-ing, -r), have power.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6792}/[H6629]', 'lemma', 'heb', 'צֹנֵא', '["tsônêʼ"]', '["sheep"]', '["n-m"]', 'a flock sheep.', 'or צֹנֶה; for 6629;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0504}/[H502]', 'inflected', 'heb', 'אֶלֶף', '["ʼeleph"]', '["and/ cattle<s>"]', '["n-m"]', 'a family; also (from the sense of yoking or taming) an ox or cow family, kine, oxen.', 'from 502;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1709H}/[H1711]', 'inflected', 'heb', 'דָּג', '["dâg"]', '["and/ [the] fish of","and/ [the] fish<es> of"]', '["n-m"]', 'a fish (often used collectively) fish.', 'or (fully) דָּאג; (Nehemiah 13:16), from 1711; a fish (as prolific); or perhaps rather from 1672 (as timid); but still better from 1672 (in the sense of squirming, i.e. moving by the vibratory action of the tail);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4192}/[H4191]', 'lemma', 'heb', 'מוּת', '["Mûwth"]', '["labben"]', '["n-m"]', '''To die for the son'', probably the title of a popular song death, Muthlabben.', '(Psalm 48:14) or מוּת לַבֵּן; from 4191 and 1121 with the preposition and article interposed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1779}/H9020/[H1777]', 'inflected', 'heb', 'דִּין', '["dîyn"]', '["and/ cause/ my"]', '["n-m"]', 'judgement (the suit, justice, sentence or tribunal); by implication also strife cause, judgement, plea, strife.', 'or (Job 19:29) דּוּן; from 1777;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5428}/[H5428]', 'lemma', 'heb', 'נָתַשׁ', '["nâthash"]', '["I will pluck [them] up","I will pluck [you] up","I will pluck up","[am] about to pluck up","are they plucked up","it will be plucked up","plucking up","they will be plucked up","you have plucked up"]', '["v"]', 'to tear away destroy, forsake, pluck (out, up, by the roots), pull up, root out (up), × utterly. s', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4339}/[H3474]', 'inflected', 'heb', 'מֵישָׁר', '["mêyshâr"]', '["with/ smoothness<es>","with/ uprightness<es>"]', '["n-m"]', 'evenness, i.e. (figuratively) prosperity or concord; also straightness, i.e. (figuratively) rectitude (only in plural with singular sense; often adverbially) agreement, aright, that are equal, equity, (things that are) right(-eously, things), sweetly, upright(-ly, -ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4869A}/[H7682]', 'lemma', 'heb', 'מִשְׂגָּב', '["misgâb"]', '["[is] a refuge","[the] refuge of","a refuge"]', '["n-m n-pr-loc"]', 'properly, a cliff (or other lofty or inaccessible place); abstractly, altitude; figuratively, a refuge; Misgab, a place in Moab defence, high fort (tower), refuge, Misgab.', 'from 7682;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H1790>', 'inflected', 'heb', 'לדך', '["la./Dakh"]', '["for the/ oppressed"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6869A}/[H6862]', 'lemma', 'heb', 'צָרָה', '["tsârâh"]', '["trouble"]', '["n-f"]', 'tightness (i.e. figuratively, trouble); transitively, a female rival adversary, adversity, affliction, anguish, distress, tribulation, trouble.', 'feminine of 6862;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1875}/H9031/[H1875]', 'inflected', 'heb', 'דָּרַשׁ', '["dârash"]', '["I seek/ you","[those who] seek/ you"]', '["v"]', 'properly, to tread or frequent; usually to follow (for pursuit or search); by implication, to seek or ask; specifically to worship ask, × at all, care for, × diligently, inquire, make inquisition, (necro-) mancer, question, require, search, seek (for, out), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1523}/[H1523]', 'lemma', 'heb', 'גִּיל', '["gîyl"]', '["I will rejoice","certainly <to rejoice>","he exults","he rejoices","he will be glad","it may be glad","it may rejoice","it rejoice","it will rejoice","let him rejoice","let it be glad","let them be glad","let them rejoice","let us be glad","let us rejoice","may it rejoice","people are glad","rejoice","they exult","they will be glad","they will rejoice","they will tremble","you will be glad"]', '["v"]', 'properly, to spin round (under the influence of any violent emotion), i.e. usually rejoice, or (as cringing) fear be glad, joy, be joyful, rejoice.', 'or (by permutation) גּוּל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6467}/[H6466]', 'inflected', 'heb', 'פֹּעַל', '["pôʻal"]', '["by/ [the] work of"]', '["n-m"]', 'an act or work (concretely) act, deed, do, getting, maker, work.', 'from 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1902G}/[H1897]', 'lemma', 'heb', 'הִגָּיוֹן', '["higgâyôwn"]', '["Higgaion"]', '["n-m"]', 'a murmuring sound, i.e. a musical notation (probably similar to the modern affettuoso to indicate solemnity of movement); by implication, a machination device, Higgaion, meditation, solemn sound.', 'intensive from 1897;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7585}/H9011/[H7592]', 'inflected', 'heb', 'שְׁאוֹל', '["shᵉʼôwl"]', '["to/ Sheol/ <towards>"]', '["n-f"]', 'hades or the world of the dead (as if a subterranean retreat), including its accessories and inmates grave, hell, pit.', 'or שְׁאֹל; from 7592;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7913}/[H7911]', 'lemma', 'heb', 'שָׁכֵחַ', '["shâkêach"]', '["forgetful of"]', '["a"]', 'oblivious forget.', 'from 7911;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5810}/[H5810]', 'lemma', 'heb', 'עָזַז', '["ʻâzaz"]', '["he makes strong","he was strong","he will prevail","it gives strength","it is strong","it prevail","she has made firm"]', '["v"]', 'to be stout (literally or figuratively) harden, impudent, prevail, strengthen (self), be strong.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7896I}/H9012/[H7896]', 'inflected', 'heb', 'שִׁית', '["shîyth"]', '["appoint/ !"]', '["v"]', 'to place (in a very wide application) apply, appoint, array, bring, consider, lay (up), let alone, × look, make, mark, put (on), regard, set, shew, be stayed, × take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4172B}/[H3372]', 'lemma', 'heb', 'מוֹרָא', '["môwrâʼ"]', '["terror"]', '["n-m"]', 'fear; by implication, a fearful thing or deed dread, (that ought to be) fear(-ed), terribleness, terror.', 'or מֹרָא; or מוֹרָהxlit môrâh corrected to môwrâh; (Psalm 9:20), from 3372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7350}/[H7368]', 'inflected', 'heb', 'רָחוֹק', '["râchôwq"]', '["at/ a distance"]', '["a"]', 'remote, literally or figuratively, of place or time; specifically, precious; often used adverbially (with preposition) (a-) far (abroad, off), long ago, of old, space, great while to come.', 'or רָחֹק; from 7368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1346}/[H1342]', 'inflected', 'heb', 'גַּאֲוָה', '["gaʼăvâh"]', '["in/ [the] pride of","with/ pride"]', '["n-f"]', 'arrogance or majesty; by implication, (concretely) ornament excellency, haughtiness, highness, pride, proudly, swelling.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4209}/[H2161]', 'inflected', 'heb', 'מְזִמָּה', '["mᵉzimmâh"]', '["by/ schemes"]', '["n-f"]', 'a plan, usually evil (machination), sometimes good (sagacity) (wicked) device, discretion, intent, witty invention, lewdness, mischievous (device), thought, wickedly.', 'from 2161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1214I}/[H1214]', 'inflected', 'heb', 'בָּצַע', '["bâtsaʻ"]', '["and/ [one] greedy for unjust gain"]', '["v"]', 'to break off, i.e. (usually) plunder; figuratively, to finish, or (intransitively) stop (be) covet(-ous), cut (off), finish, fulfill, gain (greedily), get, be given to (covetousness), greedy, perform, be wounded.', 'a primitive root');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1363}/[H1361]', 'inflected', 'heb', 'גֹּבַהּ', '["gôbahh"]', '["[was] like/ [the] height of","according to/ [the] haughtiness of"]', '["n-m"]', 'elation, grandeur, arrogance excellency, haughty, height, high, loftiness, pride.', 'from 1361;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4209}/H9023/[H2161]', 'inflected', 'heb', 'מְזִמָּה', '["mᵉzimmâh"]', '["purpose/ his","thoughts/ his"]', '["n-f"]', 'a plan, usually evil (machination), sometimes good (sagacity) (wicked) device, discretion, intent, witty invention, lewdness, mischievous (device), thought, wickedly.', 'from 2161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5048}/H9033/[H5046]', 'inflected', 'heb', 'נֶגֶד', '["neged"]', '["from/ before/ him"]', '["prep"]', 'a front, i.e. part opposite; specifically a counterpart, or mate; usually (adverbial, especially with preposition) over against or before about, (over) against, × aloof, × far (off), × from, over, presence, × other side, sight, × to view.', 'from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6887D}/H9033/[H6887]', 'inflected', 'heb', 'צָרַר', '["tsârar"]', '["opposers/ his"]', '["v"]', 'to cramp, literally or figuratively, transitive or intransitive adversary, (be in) afflict(-ion), beseige, bind (up), (be in, bring) distress, enemy, narrower, oppress, pangs, shut up, be in a strait (trouble), vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6315}/[H6315]', 'lemma', 'heb', 'פּוּחַ', '["pûwach"]', '["I will blow","[one who] he pants","[who] he breathes out","he breathes out","make breathe","they inflame"]', '["v"]', 'to puff, i.e. blow with the breath or air; hence, to fan (as a breeze), to utter, to kindle (a fire), to scoff blow (upon), break, puff, bring into a snare, speak, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8496}/[H8432]', 'inflected', 'heb', 'תֹּךְ', '["tôk"]', '["and/ oppression"]', '["n-m"]', 'oppression deceit, fraud.', 'or תּוֹך; (Psalm 72:14), from the same base as 8432 (in the sense of cutting to pieces);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3993}/[H693]', 'inflected', 'heb', 'מַאֲרָב', '["maʼărâb"]', '["in/ an ambush of"]', '["n-m"]', 'an ambuscade lie in ambush, ambushment, lurking place, lying in wait.', 'from 693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4565}/[H5641]', 'inflected', 'heb', 'מִסְתָּר', '["miçtâr"]', '["in <the>/ hiding place","in <the>/ hiding places","in <the>/ secret places","in the/ secret place","in/ hiding places","in/ secret places"]', '["n-m"]', 'properly, a concealer, i.e. a covert secret(-ly, place).', 'from 5641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H2489>', 'inflected', 'heb', 'לחלכה', '["le./che.le.Khah"]', '["for/ an unfortunate person"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5520}/H9023/[H5526]', 'inflected', 'heb', 'סֹךְ', '["çôk"]', '["in/ lair/ its","in/ refuge/ his"]', '["n-m"]', 'a hut (as of entwined boughs); also a lair covert, den, pavilion, tabernacle.', 'from 5526;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2414}/[H2414]', 'inflected', 'heb', 'חָטַף', '["châṭaph"]', '["to/ seize"]', '["v"]', 'to clutch; hence, to seize as a prisoner catch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2414}/[H2414]', 'lemma', 'heb', 'חָטַף', '["châṭaph"]', '["he seizes"]', '["v"]', 'to clutch; hence, to seize as a prisoner catch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4900}/H9043/[H4900]', 'inflected', 'heb', 'מָשַׁךְ', '["mâshak"]', '["when/ drags [him] away/ he"]', '["v"]', 'to draw, used in a great variety of applications (including to sow, to sound, to prolong, to develop, to march, to remove, to delay, to be tall, etc.) draw (along, out), continue, defer, extend, forbear, × give, handle, make (pro-, sound) long, × sow, scatter, stretch out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7568}/H9023/[H3423]', 'inflected', 'heb', 'רֶשֶׁת', '["resheth"]', '["in/ net/ his"]', '["n-f"]', 'a net (as catching animals) net(-work).', 'from 3423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1794}/[H1790]', 'lemma', 'heb', 'דָּכָה', '["dâkâh"]', '["[which] you have crushed","he is crushed"]', '["v"]', 'to collapse (phys. or mentally) break (sore), contrite, crouch.', 'a primitive root (compare 1790, 1792);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6099}/H9023/[H6105]', 'inflected', 'heb', 'עָצוּם', '["ʻâtsûwm"]', '["among/ mighty [ones]/ his"]', '["a"]', 'powerful (specifically, a paw); by implication, numerous feeble, great, mighty, must, strong.', 'or עָצֻם; passive participle of 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2428A}/ /{H3512B}/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["an army/ /of disheartened [people]"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3708A}/[H3707]', 'inflected', 'heb', 'כַּעַס', '["kaʻaç"]', '["and/ [is] vexation","and/ [the] provocation of","and/ anger","and/ vexation"]', '["n-m"]', 'vexation anger, angry, grief, indignation, provocation, provoking, × sore, sorrow, spite, wrath.', 'or (in Job) כַּעַשׂ; from 3707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2489>', 'opaque', 'heb', 'חֵלְכָא', '["chêlᵉkâʼ"]', '["an unfortunate person"]', '["a"]', 'a wretch, i.e. unfortunate poor.', 'or חֵלְכָה; apparently from an unused root probably meaning to be dark or (figuratively) unhappy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1790>', 'inflected', 'heb', 'ודך', '["va./Dakh"]', '["and/ [the] oppressed"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6206}/[H6206]', 'inflected', 'heb', 'עָרַץ', '["ʻârats"]', '["to/ terrify"]', '["v"]', 'to awe or (intransitive) to dread; hence, to harass be affrighted (afraid, dread, feared, terrified), break, dread, fear, oppress, prevail, shake terribly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2022G}/H9026/[H2042]', 'inflected', 'heb', 'הַר', '["har"]', '["mountain/ your"]', '["n-m"]', 'a mountain or range of hills (sometimes used figuratively) hill (country), mount(-ain), × promotion.', 'a shortened form of 2042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1869}/H9013/[H1869]', 'inflected', 'heb', 'דָּרַךְ', '["dârak"]', '["they bend/ !"]', '["v"]', 'to tread; by implication, to walk; also to string a bow (by treading on it in bending) archer, bend, come, draw, go (over), guide, lead (forth), thresh, tread (down), walk.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2671}/H9028/[H2686]', 'inflected', 'heb', 'חֵץ', '["chêts"]', '["arrow/ their"]', '["n-m"]', 'properly, a piercer, i.e. an arrow; by implication, a wound; figuratively, (of God) thunder-bolt; the shaft of a spear archer, arrow, dart, shaft, staff, wound.', 'from 2686; also by interchange for 6086');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3477G}/[H3474]', 'inflected', 'heb', 'יָשָׁר', '["yâshâr"]', '["for <the>/ upright [people]","for the/ upright [people]","to/ [people] upright of"]', '["a"]', 'straight (literally or figuratively) convenient, equity, Jasher, just, meet(-est), pleased well right(-eous), straight, (most) upright(-ly, -ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8356}/[H7896]', 'inflected', 'heb', 'שָׁתָה', '["shâthâh"]', '["the/ foundations"]', '["n-m"]', 'a basis, i.e. (figuratively) political or moral support foundation, purpose.', 'from 7896;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2040}/H9013/[H2040]', 'inflected', 'heb', 'הָרַס', '["hâraç"]', '["they will be torn down/ !"]', '["v"]', 'to pull down or in pieces, break, destroy beat down, break (down, through), destroy, overthrow, pluck down, pull down, ruin, throw down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6079}/H9023/[H5774]', 'inflected', 'heb', 'עַפְעַף', '["ʻaphʻaph"]', '["eyelids/ his"]', '["n-m"]', 'an eyelash (as fluttering); figuratively, morning ray dawning, eye-lid.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1614}/[H1613]', 'inflected', 'heb', 'גׇּפְרִית', '["gophrîyth"]', '["and/ sulfur"]', '["n-f"]', 'properly, cypress-resin; by analogy, sulphur (as equally inflammable) brimstone.', 'probably feminine of 1613;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2152}/[H2196]', 'lemma', 'heb', 'זַלְעָפָה', '["zalʻâphâh"]', '["[the] burning heat of","burning heat","burning indignation"]', '["n-f"]', 'a glow (of wind or anger); also a famine (as consuming) horrible, horror, terrible.', 'or זִלְעָפָהxlit zilʻâphâph corrected to zilʻâphâh; from 2196;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3563A>/H9028', 'opaque', 'heb', 'כּוֹס', '["kôwç"]', '["cup/ their"]', '["n-f"]', 'a cup (as a container), often figuratively, a lot (as if a potion); also some unclean bird, probably an owl (perhaps from the cup-like cavity of its eye) cup, (small) owl. Compare 3599.', 'from an unused root meaning to hold together;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6461}/[H6461]', 'lemma', 'heb', 'פָּסַס', '["pâçaç"]', '["they have vanished"]', '["v"]', 'probably to disperse, i.e. (intransitive) disappear cease.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3956G}/H9025/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["<to>/ tongues/ our"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8193G}/H9025/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["lips/ our"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0603}/[H602]', 'inflected', 'heb', 'אֲנָקָה', '["ʼănâqâh"]', '["from/ [the] groaning of"]', '["n-f"]', 'shrieking crying out, groaning, sighing.', 'from 602;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3468}/[H3467]', 'inflected', 'heb', 'יֶשַׁע', '["yeshaʻ"]', '["in/ [the] safety","on/ [the] salvation of"]', '["n-m"]', 'liberty, deliverance, prosperity safety, salvation, saving.', 'or יֵשַׁע; from 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5948}/[H5953]', 'inflected', 'heb', 'עֲלִיל', '["ʻălîyl"]', '["in/ a crucible"]', '["n-m"]', 'probably a crucible (as working over the metal) furnace.', 'from 5953 in the sense of completing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8104H}/H9038/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["it preserves/ them","you will keep/ them"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980I}/H9013/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["they go/ !","they walk about/ !","they walk/ !","they will walk/ !"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7311A}/[H7311]', 'inflected', 'heb', 'רוּם', '["rûwm"]', '["as/ lifts","like/ [those who] lift","when/ is exalted"]', '["v"]', 'to be high actively, to rise or raise (in various applications, literally or figuratively) bring up, exalt (self), extol, give, go up, haughty, heave (up), (be, lift up on, make on, set up on, too) high(-er, one), hold up, levy, lift(-er) up, (be) lofty, (× a-) loud, mount up, offer (up), presumptuously, (be) promote(-ion), proud, set up, tall(-er), take (away, off, up), breed worms.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2149}/[H2151]', 'lemma', 'heb', 'זֻלּוּת', '["zullûwth"]', '["vileness"]', '["n-m"]', 'properly, a shaking, i.e. perhaps a tempest vilest.', 'from 2151;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5315G}/H9020/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["in/ soul/ my"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3015}/[H3013]', 'lemma', 'heb', 'יָגוֹן', '["yâgôwn"]', '["sorrow"]', '["n-m"]', 'affliction grief, sorrow.', 'from 3013;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5027}/H9012/[H5027]', 'inflected', 'heb', 'נָבַט', '["nâbaṭ"]', '["look at/ !","look/ !","pay attention/ !"]', '["v"]', 'to scan, i.e. look intently at; by implication, to regard with pleasure, favor or care (cause to) behold, consider, look (down), regard, have respect, see.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0215}/H9012/[H215]', 'inflected', 'heb', 'אוֹר', '["ʼôwr"]', '["give light to/ !","make shine/ !"]', '["v"]', 'to be (causative, make) luminous (literally and metaphorically) × break of day, glorious, kindle, (be, en-, give, show) light (-en, -ened), set on fire, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3201}/H9033/[H3201]', 'inflected', 'heb', 'יָכֹל', '["yâkôl"]', '["I have prevailed over/ him"]', '["v"]', 'to be able, literally (can, could) or morally (may, might) be able, any at all (ways), attain, can (away with, (-not)), could, endure, might, overcome, have power, prevail, still, suffer.', 'or (fuller) יָכוֹל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0444}/[H444]', 'lemma', 'heb', 'אָלַח', '["ʼâlach"]', '["they are corrupt"]', '["v"]', 'to muddle, i.e. (figuratively and intransitive) to turn (morally) corrupt become filthy.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4268}/H9023/[H2620]', 'inflected', 'heb', 'מַחֲסֶה', '["machăçeh"]', '["[is] refuge/ his"]', '["n-m"]', 'a shelter (literally or figuratively) hope, (place of) refuge, shelter, trust.', 'or מַחְסֶה; from 2620;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6726}/[H6725]', 'inflected', 'heb', 'צִיּוֹן', '["Tsîyôwn"]', '["[will be] from/ Zion","from/ Zion"]', '["n-pr-loc"]', 'Tsijon (as a permanent capital), a mountain of Jerusalem Zion.', 'the same (regularly) as 6725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7725H}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["when/ restored","when/ turns back"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6466}/[H6466]', 'inflected', 'heb', 'פָּעַל', '["pâʻal"]', '["and/ [one who] does","and/ [those who] do"]', '["v"]', 'to do or make (systematically and habitually), especially to practise commit, (evil-) do(-er), make(-r), ordain, work(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2781}/[H2778]', 'inflected', 'heb', 'חֶרְפָּה', '["cherpâh"]', '["and/ [the] reproach of","and/ [the] reproaches of","and/ reproach"]', '["n-f"]', 'contumely, disgrace, the pudenda rebuke, reproach(-fully), shame.', 'from 2778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4387}/[H3799]', 'lemma', 'heb', 'מִכְתָּם', '["miktâm"]', '["a miktam"]', '["n-m"]', 'an engraving, i.e. (techn.) a poem Michtam.', 'from 3799;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2896C}/H9020/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["good/ my"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6918H}/[H6942]', 'inflected', 'heb', 'קָדוֹשׁ', '["qâdôwsh"]', '["to/ [the] holy [ones]"]', '["a"]', 'sacred (ceremonially or morally); (as noun) God (by eminence), an angel, a saint, a sanctuary holy (One), saint.', 'or קָדֹשׁ; from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0117}/[H142]', 'inflected', 'heb', 'אַדִּיר', '["ʼaddîyr"]', '["and/ [the] majestic [ones]"]', '["a"]', 'wide or (generally) large; figuratively, powerful excellent, famous, gallant, glorious, goodly, lordly, mighty(-ier one), noble, principal, worthy.', 'from 142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6094}/H9028/[H6087]', 'inflected', 'heb', 'עַצֶּבֶת', '["ʻatstsebeth"]', '["sorrows/ their"]', '["n-f"]', 'a idol; also, a pain or wound sorrow, wound.', 'from 6087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5262}/H9028/[H5258]', 'inflected', 'heb', 'נֶסֶךְ', '["neçek"]', '["drink offerings/ their"]', '["n-m"]', 'a libation; also a cast idol cover, drink offering, molten image.', 'or נֵסֶךְ; from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1077}/[H1086]', 'inflected', 'heb', 'בַּל', '["bal"]', '["and/ not"]', '["adv"]', 'properly, a failure; by implication nothing; usually (adverb) not at all; also lest lest, neither, no, none (that...), not (any), nothing.', 'from 1086;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3563A>/H9020', 'inflected', 'heb', 'וכוסי', '["ve./kho.S/i"]', '["and/ cup/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1486>/H9020', 'opaque', 'heb', 'גּוֹרָל', '["gôwrâl"]', '["lot/ my"]', '["n-m"]', 'properly, a pebble, i.e. a lot (small stones being used for that purpose); figuratively, a portion or destiny (as if determined by lot) lot.', 'or (shortened) גֹּרָל; from an unused root meaning to be rough (as stone);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8231}/[H8231]', 'lemma', 'heb', 'שָׁפַר', '["shâphar"]', '["it is beautiful"]', '["v"]', 'to glisten, i.e. (figuratively) be (causatively, make) fair × goodly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3289}/H9030/[H3289]', 'inflected', 'heb', 'יָעַץ', '["yâʻats"]', '["he has counseled/ me"]', '["v"]', 'to advise; reflexively, to deliberate or resolve advertise, take advise, advise (well), consult, (give, take) counsel(-lor), determine, devise, guide, purpose.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3225G}/H9020/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["[he is] from/ right [hand]/ my"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1523}/[H1523]', 'inflected', 'heb', 'גִּיל', '["gîyl"]', '["and/ I will be glad","and/ it rejoiced","and/ they were glad"]', '["v"]', 'properly, to spin round (under the influence of any violent emotion), i.e. usually rejoice, or (as cringing) fear be glad, joy, be joyful, rejoice.', 'or (by permutation) גּוּל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7585}/[H7592]', 'inflected', 'heb', 'שְׁאוֹל', '["shᵉʼôwl"]', '["for/ Sheol","to/ Sheol"]', '["n-f"]', 'hades or the world of the dead (as if a subterranean retreat), including its accessories and inmates grave, hell, pit.', 'or שְׁאֹל; from 7592;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7648}/[H7646]', 'lemma', 'heb', 'שֹׂבַע', '["sôbaʻ"]', '["abundance of"]', '["n-m"]', 'satisfaction (of food or [figuratively] joy) fill, full(-ness), satisfying, be satisfied.', 'from 7646;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5273A}/[H5276]', 'lemma', 'heb', 'נָעִים', '["nâʻîym"]', '["[is] pleasant","[it is] pleasant","[will be] pleasant","pleasant","pleasant [things]"]', '["a"]', 'delightful (objective or subjective, literal or figurative) pleasant(-ure), sweet.', 'from 5276;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3225G}/H9021/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["[are] at/ right [hand]/ your","by/ right [hand]/ your"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7440}/H9020/[H7442]', 'inflected', 'heb', 'רִנָּה', '["rinnâh"]', '["cry of entreaty/ my"]', '["n-f"]', 'properly, a creaking (or shrill sound), i.e. shout (of joy or grief) cry, gladness, joy, proclamation, rejoicing, shouting, sing(-ing), triumph.', 'from 7442;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4339}/[H3474]', 'lemma', 'heb', 'מֵישָׁר', '["mêyshâr"]', '["[is] level paths","[will be] uprightness<es>","uprightness<es>"]', '["n-m"]', 'evenness, i.e. (figuratively) prosperity or concord; also straightness, i.e. (figuratively) rectitude (only in plural with singular sense; often adverbially) agreement, aright, that are equal, equity, (things that are) right(-eously, things), sweetly, upright(-ly, -ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6884}/H9030/[H6884]', 'inflected', 'heb', 'צָרַף', '["tsâraph"]', '["you have tested/ me"]', '["v"]', 'to fuse (metal), i.e. refine (literally or figuratively) cast, (re-) fine(-er), founder, goldsmith, melt, pure, purge away, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6468}/[H6466]', 'inflected', 'heb', 'פְּעֻלָּה', '["pᵉʻullâh"]', '["to/ [the] deeds of"]', '["n-f"]', '(abstractly) work labour, reward, wages, work.', 'feminine passive participle of 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6530}/[H6555]', 'lemma', 'heb', 'פְּרִיץ', '["pᵉrîyts"]', '["[the] violent ones of","robbers","violent","violent person[s]"]', '["n-m"]', 'violent, i.e. a tyrant destroyer, ravenous, robber.', 'from 6555;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0838A}/H9020/[H833]', 'inflected', 'heb', 'אָשֻׁר', '["ʼâshur"]', '["steps/ my"]', '["n-f"]', 'a step going, step.', 'or אַשֻּׁר; from 833 in the sense of going;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4570}/H9021/[H5696]', 'inflected', 'heb', 'מַעְגָּל', '["maʻgâl"]', '["in/ tracks/ your"]', '["n-m"]', 'a track (literally or figuratively); also a rampart (as circular) going, path, trench, way(-side).', 'or feminine מַעְגָּלָה; from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6965J}/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["from/ [those who] rise up"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7703}/H9030/[H7703]', 'inflected', 'heb', 'שָׁדַד', '["shâdad"]', '["they have assailed/ me"]', '["v"]', 'properly, to be burly, i.e. (figuratively) powerful (passively, impregnable); by implication, to ravage dead, destroy(-er), oppress, robber, spoil(-er), × utterly, (lay) waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1348}/[H1342]', 'inflected', 'heb', 'גֵּאוּת', '["gêʼûwth"]', '["over/ [the] swelling of","with/ pride"]', '["n-f"]', 'the same as 1346 excellent things, lifting up, majesty, pride, proudly, raging.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0838B}/H9025/[H833]', 'inflected', 'heb', 'אָשֻׁר', '["ʼâshur"]', '["steps/ our"]', '["n-f"]', 'a step going, step.', 'or אַשֻּׁר; from 833 in the sense of going;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5437H}/H9035/[H5437]', 'inflected', 'heb', 'סָבַב', '["çâbab"]', '["they have surrounded/ us"]', '["v"]', 'to revolve, surround, or border; used in various applications, literally and figuratively bring, cast, fetch, lead, make, walk, × whirl, × round about, be about on every side, apply, avoid, beset (about), besiege, bring again, carry (about), change, cause to come about, × circuit, (fetch a) compass (about, round), drive, environ, × on every side, beset (close, come, compass, go, stand) round about, inclose, remove, return, set, sit down, turn (self) (about, aside, away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1825}/H9023/[H1819]', 'inflected', 'heb', 'דִּמְיוֹן', '["dimyôwn"]', '["likeness/ his"]', '["n-m"]', 'resemblance × like.', 'from 1819;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2963}/[H2963]', 'inflected', 'heb', 'טָרַף', '["ṭâraph"]', '["to/ tear","to/ tear to pieces"]', '["v"]', 'to pluck off or pull to pieces; causatively to supply with food (as in morsels) catch, × without doubt, feed, ravin, rend in pieces, × surely, tear (in pieces).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H3715A}/[H3722]', 'inflected', 'heb', 'כְּפִיר', '["kᵉphîyr"]', '["and/ like <the>/ young lion","and/ like/ a young lion"]', '["n-m"]', 'a village (as covered in by walls); also a young lion (perhaps as covered with a mane) (young) lion, village. Compare 3723.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6923}/H9012/[H6923]', 'inflected', 'heb', 'קָדַם', '["qâdam"]', '["confront/ !"]', '["v"]', 'to project (one self), i.e. precede; hence, to anticipate, hasten, meet (usually for help) come (go, (flee)) before, disappoint, meet, prevent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3766}/H9033/[H3766]', 'inflected', 'heb', 'כָּרַע', '["kâraʻ"]', '["make bow down/ him"]', '["v"]', 'to bend the knee; by implication, to sink, to prostrate bow (down, self), bring down (low), cast down, couch, fall, feeble, kneeling, sink, smite (stoop) down, subdue, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6403}/H9012/[H6403]', 'inflected', 'heb', 'פָּלַט', '["pâlaṭ"]', '["deliver/ !"]', '["v"]', 'to slip out, i.e. escape; causatively, to deliver calve, carry away safe, deliver, (cause to) escape.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4962}/[H4970]', 'inflected', 'heb', 'מַת', '["math"]', '["from/ men"]', '["n-m"]', 'properly, an adult (as of full length); by implication, a man (only in the plural) few, × friends, men, persons, × small.', 'from the same as 4970;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H2465>', 'inflected', 'heb', 'מחלד', '["me./Che.led"]', '["from/ [the] world"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6845}/H9021/[H6845]', 'inflected', 'heb', 'צָפַן', '["tsâphan"]', '["and/ treasured [thing]/ your"]', '["v"]', 'to hide (by covering over); by implication, to hoard or reserve; figuratively to deny; specifically (favorably) to protect, (unfavorably) to lurk esteem, hide(-den one, self), lay up, lurk (be set) privily, (keep) secret(-ly, place).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0990H>/H9028', 'opaque', 'heb', 'בֶּטֶן', '["beṭen"]', '["belly/ their"]', '["n-f"]', 'the belly, especially the womb; also the bosom or body of anything belly, body, as they be born, within, womb.', 'from an unused root probably meaning to be hollow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3499A}/H9028/[H3498]', 'inflected', 'heb', 'יֶתֶר', '["yether"]', '["abundance/ their"]', '["n-m"]', 'properly, an overhanging, i.e. (by implication) an excess, superiority, remainder; also a small rope (as hanging free) abundant, cord, exceeding, excellancy(-ent), what they leave, that hath left, plentifully, remnant, residue, rest, string, with.', 'from 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5768}/H9028/[H5763]', 'inflected', 'heb', 'עוֹלֵל', '["ʻôwlêl"]', '["to/ children/ their"]', '["n-m"]', 'a suckling babe, (young) child, infant, little one.', 'or עֹלָל; from 5763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6974}/[H3364]', 'inflected', 'heb', 'קוּץ', '["qûwts"]', '["when/ awake"]', '["v"]', 'to awake (literally or figuratively) arise, (be) (a-) wake, watch.', 'a primitive root (identical with through the idea of abruptness in starting up from sleep (compare 3364));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8544}/H9021/[H4327]', 'inflected', 'heb', 'תְּמוּנָה', '["tᵉmûwnâh"]', '["likeness/ your"]', '["n-f"]', 'something portioned (i.e. fashioned) out, as a shape, i.e. (indefinitely) phantom, or (specifically) embodiment, or (figuratively) manifestation (of favor) image, likeness, similitude.', 'or תְּמֻנָה; from 4327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7355}/H9031/[H7355]', 'inflected', 'heb', 'רָחַם', '["râcham"]', '["I love/ you"]', '["v"]', 'to fondle; by implication, to love, especially to compassionate have compassion (on, upon), love, (find, have, obtain, shew) mercy(-iful, on, upon), (have) pity, Ruhamah, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2391}/H9020/[H2388]', 'inflected', 'heb', 'חֵזֶק', '["chêzeq"]', '["strength/ my"]', '["n-m"]', 'help strength.', 'from 2388;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5158A}/[H5157]', 'inflected', 'heb', 'נַחַל', '["nachal"]', '["and/ [the] river of","and/ [the] torrents of","and/ a torrent","and/ torrents"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4144}/[H3245]', 'inflected', 'heb', 'מוֹסָד', '["môwçâd"]', '["and/ [the] foundations of"]', '["n-m"]', 'a foundation foundation.', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1675}/[H1675]', 'inflected', 'heb', 'דָּאָה', '["dâʼâh"]', '["and/ he soared"]', '["v"]', 'to dart, i.e. fly rapidly fly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5643A}/H9023/[H5641]', 'inflected', 'heb', 'סֵתֶר', '["çêther"]', '["covering/ his"]', '["n-m"]', 'a cover (in a good or a bad, a literal or a figurative sense) backbiting, covering, covert, × disguise(-th), hiding place, privily, protection, secret(-ly, place).', 'or (feminine) סִתְרָה; (Deuteronomy 32:38), from 5641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2824}/[H2821]', 'lemma', 'heb', 'חֶשְׁכָה', '["cheshkâh"]', '["darkness of"]', '["n-f"]', 'darkness dark.', 'from 2821;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5645}/H9023/[H5743]', 'inflected', 'heb', 'עָב', '["ʻâb"]', '["dark clouds/ his"]', '["n-m"]', 'properly, an envelope, i.e. darkness (or density, 2 Chronicles 4:17); specifically, a (scud) cloud; also a copse clay, (thick) cloud, × thick, thicket. Compare 5672.', '(masculine and feminine); from 5743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1513>', 'inflected', 'heb', 'וגחלי', '["ve./ga.cha.lei"]', '["and/ coals of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7232}/[H7231]', 'lemma', 'heb', 'רָבַב', '["râbab"]', '["he shot"]', '["v"]', 'to shoot an arrow shoot.', 'a primitive root (rather identical with 7231 through the idea of projection);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1606}/H9021/[H1605]', 'inflected', 'heb', 'גְּעָרָה', '["gᵉʻârâh"]', '["from/ rebuke/ your"]', '["n-f"]', 'a chiding rebuke(-ing), reproof.', 'from 1605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H8130}/H9030/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["and/ from/ [those who] hate/ me"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4937A}/[H8172]', 'inflected', 'heb', 'מִשְׁעֵן', '["mishʻên"]', '["<into>/ a support"]', '["n-m"]', 'a support (concretely), i.e. (figuratively) a protector or sustenance stay.', 'or מִשְׁעָן; from 8172;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869H}/H9023/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["eyes/ his"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1399}/[H1396]', 'lemma', 'heb', 'גְּבַר', '["gᵉbar"]', '["a man"]', '["n-m"]', 'a person man.', 'from 1396; the same as 1397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0430G}/H9020/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["and/ by/ God/ my"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0247}/H9030/[H247]', 'inflected', 'heb', 'אָזַר', '["ʼâzar"]', '["[is] the/ [one who] has girded/ me"]', '["v"]', 'to belt bind (compass) about, gird (up, with).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3225G}/H9021/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["and/ right [hand]/ your"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5582}/H9030/[H5582]', 'inflected', 'heb', 'סָעַד', '["çâʻad"]', '["it has supported/ me","it supported/ me","uphold/ me"]', '["v"]', 'to support (mostly figurative) comfort, establish, hold up, refresh self, strengthen, be upholden.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6037}/H9021/[H6035]', 'inflected', 'heb', 'עַנְוָה', '["ʻanvâh"]', '["and/ humility/ your"]', '["n-f"]', 'mildness (royal); also (concretely) oppressed gentleness, meekness.', 'feminine of 6035;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5381}/H9038/[H5381]', 'inflected', 'heb', 'נָשַׂג', '["nâsag"]', '["and/ I overtook/ them"]', '["v"]', 'to reach (literally or figuratively) ability, be able, attain (unto), (be able to, can) get, lay at, put, reach, remove, wax rich, × surely, (over-) take (hold of, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4272}/H9038/[H4272]', 'inflected', 'heb', 'מָחַץ', '["mâchats"]', '["I shattered/ them"]', '["v"]', 'to dash asunder; by implication, to crush, smash or violently plunge; figuratively, to subdue or destroy dip, pierce (through), smite (through), strike through, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965B}/H9030/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["[those who] rose against/ me"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8130}/H9030/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["and/ [those who] hated/ me"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6789}/H9038/[H6789]', 'inflected', 'heb', 'צָמַת', '["tsâmath"]', '["I destroyed/ them","destroy/ them","he will destroy/ them"]', '["v"]', 'to extirpate (literally or figuratively) consume, cut off, destroy, vanish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7324}/H9038/[H7324]', 'inflected', 'heb', 'רוּק', '["rûwq"]', '["I poured out/ them"]', '["v"]', 'to pour out (literally or figuratively), i.e. empty × arm, cast out, draw (out), (make) empty, pour forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6403}/H9030/[H6403]', 'inflected', 'heb', 'פָּלַט', '["pâlaṭ"]', '["[he has] delivered/ me","deliver/ me","you delivered/ me","you will deliver/ me"]', '["v"]', 'to slip out, i.e. escape; causatively, to deliver calve, carry away safe, deliver, (cause to) escape.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2727}/[H2727]', 'inflected', 'heb', 'חָרַג', '["chârag"]', '["and/ they may come trembling"]', '["v"]', 'properly, to leap suddenly, i.e. (by implication) to be dismayed be afraid.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5042}/[H5042]', 'lemma', 'heb', 'נָבַע', '["nâbaʻ"]', '["I will pour forth","I will pour out","flowing","it ferments","it pours forth","may they pour forth","they pour forth","they will pour forth"]', '["v"]', 'to gush forth; figuratively, to utter (good or bad words); specifically, to emit (a foul odor) belch out, flowing, pour out, send forth, utter (abundantly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3915}/[H3883]', 'inflected', 'heb', 'לַיִל', '["layil"]', '["to/ night"]', '["n-m"]', 'properly, a twist (away of the light), i.e. night; figuratively, adversity (mid-)night (season).', 'or (Isaiah 21:11) לֵיל; also לַיְלָה; from the same as 3883;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6957B}/H9028/[H6960]', 'inflected', 'heb', 'קַו', '["qav"]', '["line/ their"]', '["n-m"]', 'a cord (as connecting), especially for measuring; figuratively, a rule; also a rim, a musical string or accord line. Compare 6978.', 'or קָו; from 6960 (compare 6961);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7097A}/[H7096]', 'inflected', 'heb', 'קָצֶה', '["qâtseh"]', '["and/ at/ [the] end of"]', '["n-m"]', 'an extremity × after, border, brim, brink, edge, end, (in-) finite, frontier, outmost coast, quarter, shore, (out-) side, × some, ut(-ter-) most (part).', 'or (negative only) קֵצֶה; from 7096; (used in a great variety of applications and idioms; compare 7093)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4405}/H9028/[H4448]', 'inflected', 'heb', 'מִלָּה', '["millâh"]', '["words/ their"]', '["n-f"]', 'a word; collectively, a discourse; figuratively, a topic answer, by-word, matter, any thing (what) to say, to speak(-ing), speak, talking, word.', 'from 4448 (plural masculine as if from מִלֶּה;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2860}/[H2859]', 'inflected', 'heb', 'חָתָן', '["châthân"]', '["[is] like/ a bridegroom","like <the>/ bridegroom"]', '["n-m"]', 'a relative by marriage (especially through the bride); figuratively, a circumcised child (as a species of religious espousal) bridegroom, husband, son in law.', 'from 2859;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2646}/H9023/[H2645]', 'inflected', 'heb', 'חֻפָּה', '["chuppâh"]', '["from/ chamber/ his"]', '["n-f"]', 'a canopy chamber, closet, defence.', 'from 2645;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4161}/H9023/[H3318]', 'inflected', 'heb', 'מוֹצָא', '["môwtsâʼ"]', '["going forth/ his","going forth/ its"]', '["n-m"]', 'a going forth, i.e. (the act) an egress, or (the place) an exit; hence, a source or product; specifically, dawn, the rising of the sun (the East), exportation, utterance, a gate, a fountain, a mine, a meadow (as producing grass) brought out, bud, that which came out, east, going forth, goings out, that which (thing that) is gone out, outgoing, proceeded out, spring, vein, (water-) course (springs).', 'or מֹצָאxlit môtsâ corrected to môtsâʼ; from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8622}/H9023/[H5362]', 'inflected', 'heb', 'תְּקוּפָה', '["tᵉqûwphâh"]', '["and/ circuit/ its"]', '["n-f"]', 'a revolution, i.e. (of the sun) course, (of time) lapse circuit, come about, end.', 'or תְּקֻפָה; from 5362;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7098}/H9028/[H7097]', 'inflected', 'heb', 'קָצָה', '["qâtsâh"]', '["ends/ their"]', '["n"]', 'a termination coast, corner, (selv-) edge, lowest, (uttermost) participle', 'feminine of 7097; (used like 7097)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2535}/H9023/[H2525]', 'inflected', 'heb', 'חַמָּה', '["chammâh"]', '["from/ heat/ its"]', '["n-f"]', 'heat; by implication, the sun heat, sun.', 'from 2525;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5715}/[H5707]', 'lemma', 'heb', 'עֵדוּת', '["ʻêdûwth"]', '["[the] testimony of","a testimony","eduth"]', '["n-f"]', 'testimony testimony, witness.', 'feminine of 5707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6612A}/[H6601]', 'lemma', 'heb', 'פְּתִי', '["pᵉthîy"]', '["<of> a simple person","O naive people","[is] naive","a naive person","foolish things","naive people","simple people"]', '["a n-f"]', 'silly (i.e. seducible) foolish, simple(-icity, one).', 'or פֶּתִי; or פְּתָאִי; from 6601;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6490}/[H6485]', 'lemma', 'heb', 'פִּקּוּד', '["piqqûwd"]', '["[the] precepts of"]', '["n-m"]', 'properly, appointed, i.e. a mandate (of God; plural only, collectively, for the Law) commandment, precept, statute.', 'or פִּקֻּד; from 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1249}/[H1305]', 'lemma', 'heb', 'בַּר', '["bar"]', '["[is] a pure [daughter]","[is] clean","pure"]', '["a"]', 'beloved; also pure, empty choice, clean, clear, pure.', 'from 1305 (in its various senses);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2530A}/[H2530]', 'inflected', 'heb', 'חָמַד', '["châmad"]', '["those/ desirable"]', '["v"]', 'to delight in beauty, greatly beloved, covet, delectable thing, (× great) delight, desire, goodly, lust, (be) pleasant (thing), precious (thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6337}/[H6338]', 'inflected', 'heb', 'פָּז', '["pâz"]', '["and/ more than/ pure gold"]', '["n-m"]', 'pure (gold); hence, gold itself (as refined) fine (pure) gold.', 'from 6338;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4966}/[H4985]', 'inflected', 'heb', 'מָתוֹק', '["mâthôwq"]', '["and/ [is] sweet","and/ sweet"]', '["a"]', 'sweet sweet(-er, -ness).', 'or מָתוּק; from 4985;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5317}/[H5130]', 'inflected', 'heb', 'נֹפֶת', '["nôpheth"]', '["and/ [the] honey of","and/ honey from [the] comb"]', '["n-m"]', 'a dripping i.e. of honey (from the comb) honeycomb.', 'from 5130 in the sense of shaking to pieces;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6688}/[H6687]', 'lemma', 'heb', 'צוּף', '["tsûwph"]', '["[are] a honeycomb of","honeycombs"]', '["n-m"]', 'comb of honey (from dripping) honeycomb.', 'from 6687;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2094B}/[H2094]', 'lemma', 'heb', 'זָהַר', '["zâhar"]', '["[is] warned","be warned","he had taken warning","he has been warned","he took warning","it was warned","you have warned"]', '["v"]', 'to gleam; figuratively, to enlighten (by caution) admonish, shine, teach, (give) warn(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8104G}/H9038/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["[is] in/ keeping/ them"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7691}/[H7686]', 'lemma', 'heb', 'שְׁגִיאָה', '["shᵉgîyʼâh"]', '["errors"]', '["n-f"]', 'a moral mistake error.', 'from 7686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5641}/[H5641]', 'inflected', 'heb', 'סָתַר', '["çâthar"]', '["from/ hidden [sins]"]', '["v"]', 'to hide (by covering), literally or figuratively be absent, keep close, conceal, hide (self), (keep) secret, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2086}/[H2102]', 'inflected', 'heb', 'זֵד', '["zêd"]', '["from/ presumptuous [sins]"]', '["n-m"]', 'arrogant presumptuous, proud.', 'from 2102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6588}/[H6586]', 'inflected', 'heb', 'פֶּשַׁע', '["peshaʻ"]', '["from/ [the] transgression of","from/ transgression"]', '["n-m"]', 'a revolt (national, moral or religious) rebellion, sin, transgression, trespass.', 'from 6586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1902H}/[H1897]', 'inflected', 'heb', 'הִגָּיוֹן', '["higgâyôwn"]', '["and/ [the] meditation of"]', '["n-m"]', 'a murmuring sound, i.e. a musical notation (probably similar to the modern affettuoso to indicate solemnity of movement); by implication, a machination device, Higgaion, meditation, solemn sound.', 'intensive from 1897;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1350A}/H9020/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["and/ redeemer/ my"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7682}/H9031/[H7682]', 'inflected', 'heb', 'שָׂגַב', '["sâgab"]', '["may it set on high/ you"]', '["v"]', 'to be (causatively, make) lofty, especially inaccessible; by implication, safe, strong; used literally and figuratively defend, exalt, be excellent, (be, set on) high, lofty, be safe, set up (on high), be too strong.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6726}/[H6725]', 'inflected', 'heb', 'צִיּוֹן', '["Tsîyôwn"]', '["and/ from/ Zion"]', '["n-pr-loc"]', 'Tsijon (as a permanent capital), a mountain of Jerusalem Zion.', 'the same (regularly) as 6725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5582}/H9031/[H5582]', 'inflected', 'heb', 'סָעַד', '["çâʻad"]', '["may he support/ you"]', '["v"]', 'to support (mostly figurative) comfort, establish, hold up, refresh self, strengthen, be upholden.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5930A}/H9021/[H5927]', 'inflected', 'heb', 'עֹלָה', '["ʻôlâh"]', '["and/ burnt offering/ your","and/ burnt offerings/ your"]', '["n-f"]', 'a step or (collectively, stairs, as ascending); usually a holocaust (as going up in smoke) ascent, burnt offering (sacrifice), go up to. See also 5766.', 'or עוֹלָה; feminine active participle of 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1878}/H9012/[H1880]', 'inflected', 'heb', 'דָּשֵׁן', '["dâshên"]', '["may he accept/ !"]', '["v"]', 'to be fat; transitively, to fatten (or regard as fat); specifically to anoint; figuratively, to satisfy; to remove (fat) ashes (of sacrifices) accept, anoint, take away the (receive) ashes (from), make (wax) fat.', 'a primitive root; also denominatively (from 1880)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3824}/H9021/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["according to/ heart/ your"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6098}/H9021/[H3289]', 'inflected', 'heb', 'עֵצָה', '["ʻêtsâh"]', '["plan/ your"]', '["n-f"]', 'advice; by implication, plan; also prudence advice, advisement, counsel([-lor]), purpose.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1713B}/[H1713]', 'lemma', 'heb', 'דָּגַל', '["dâgal"]', '["we will raise a banner"]', '["v"]', 'to flaunt, i.e. raise a flag; figuratively, to be conspicuous (set up, with) banners, chiefest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4862}/H9021/[H7592]', 'inflected', 'heb', 'מִשְׁאָלָה', '["mishʼâlâh"]', '["requests/ your"]', '["n-f"]', 'a request desire, petition.', 'from 7592;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1369}/[H1368]', 'inflected', 'heb', 'גְּבוּרָה', '["gᵉbûwrâh"]', '["by/ strength<s>","for/ strength","in/ [the] strength of","in/ strength","with/ [the] mighty deeds of","with/ might"]', '["n-f"]', 'force (literally or figuratively); by implication, valor, victory force, mastery, might, mighty (act, power), power, strength.', 'feminine passive participle from the same as 1368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5749A}/[H5749]', 'inflected', 'heb', 'עוּד', '["ʻûwd"]', '["and/ we have kept upright"]', '["v"]', 'to duplicate or repeat; by implication, to protest, testify (as by reiteration); intensively, to encompass, restore (as a sort of reduplication) admonish, charge, earnestly, lift up, protest, call (take) to record, relieve, rob, solemnly, stand upright, testify, give warning, (bear, call to, give, take to) witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3444}/H9021/[H3467]', 'inflected', 'heb', 'יְשׁוּעָה', '["yᵉshûwʻâh"]', '["and/ in/ deliverance/ your"]', '["n-f"]', 'something saved, i.e. (abstractly) deliverance; hence, aid, victory, prosperity deliverance, health, help(-ing), salvation, save, saving (health), welfare.', 'feminine passive participle of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0782}/[H781]', 'inflected', 'heb', 'אֲרֶשֶׁת', '["ʼăresheth"]', '["and/ [the] request of"]', '["n-f"]', 'a longing for request.', 'from 781 (in the sense of desiring to possess);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6923}/H9033/[H6923]', 'inflected', 'heb', 'קָדַם', '["qâdam"]', '["you meet/ him"]', '["v"]', 'to project (one self), i.e. precede; hence, to anticipate, hasten, meet (usually for help) come (go, (flee)) before, disappoint, meet, prevent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H7218A>/H9023', 'inflected', 'heb', 'לראשו', '["le./ro.Sh/o"]', '["to/ head/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2302}/H9033/[H2302]', 'inflected', 'heb', 'חָדָה', '["châdâh"]', '["you make rejoice/ him"]', '["v"]', 'to rejoice make glad, be joined, rejoice.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2617A}/[H2616]', 'inflected', 'heb', 'חֶסֶד', '["cheçed"]', '["and/ in/ [the] covenant loyalty of","and/ in/ covenant loyalty","and/ in/ covenant loyalty of"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7896G}/H9038/[H7896]', 'inflected', 'heb', 'שִׁית', '["shîyth"]', '["make/ them","you will make/ them"]', '["v"]', 'to place (in a very wide application) apply, appoint, array, bring, consider, lay (up), let alone, × look, make, mark, put (on), regard, set, shew, be stayed, × take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8574H}/[H5216]', 'inflected', 'heb', 'תַּנּוּר', '["tannûwr"]', '["like <the>/ furnace","like <the>/ oven","like/ a furnace of","like/ an oven"]', '["n-m"]', 'a fire-pot furnace, oven.', 'from 5216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0398}/H9038/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["and/ I will devour/ them","and/ it will consume/ them"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4340}/H9021/[H3498]', 'inflected', 'heb', 'מֵיתָר', '["mêythâr"]', '["on/ bowstrings/ your"]', '["n-m"]', 'a cord (of a tent); or the string (of a bow) cord, string.', 'from 3498; (compare 3499)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7311A}/H9012/[H7311]', 'inflected', 'heb', 'רוּם', '["rûwm"]', '["be exalted/ !","lift up/ !","rise up/ !"]', '["v"]', 'to be high actively, to rise or raise (in various applications, literally or figuratively) bring up, exalt (self), extol, give, go up, haughty, heave (up), (be, lift up on, make on, set up on, too) high(-er, one), hold up, levy, lift(-er) up, (be) lofty, (× a-) loud, mount up, offer (up), presumptuously, (be) promote(-ion), proud, set up, tall(-er), take (away, off, up), breed worms.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1369}/H9021/[H1368]', 'inflected', 'heb', 'גְּבוּרָה', '["gᵉbûwrâh"]', '["might/ your"]', '["n-f"]', 'force (literally or figuratively); by implication, valor, victory force, mastery, might, mighty (act, power), power, strength.', 'feminine passive participle from the same as 1368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3444}/H9020/[H3467]', 'inflected', 'heb', 'יְשׁוּעָה', '["yᵉshûwʻâh"]', '["from/ deliverance/ my"]', '["n-f"]', 'something saved, i.e. (abstractly) deliverance; hence, aid, victory, prosperity deliverance, health, help(-ing), salvation, save, saving (health), welfare.', 'feminine passive participle of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1747}/[H1820]', 'lemma', 'heb', 'דּוּמִיָּה', '["dûwmîyâh"]', '["repose","silence"]', '["n-f"]', 'stillness; adverbially, silently; abstractly quiet, trust silence, silent, waiteth.', 'from 1820;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6403}/H9038/[H6403]', 'inflected', 'heb', 'פָּלַט', '["pâlaṭ"]', '["and/ he delivered/ them","and/ you delivered/ them"]', '["v"]', 'to slip out, i.e. escape; causatively, to deliver calve, carry away safe, deliver, (cause to) escape.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6403}/H9033/[H6403]', 'inflected', 'heb', 'פָּלַט', '["pâlaṭ"]', '["let him rescue/ him"]', '["v"]', 'to slip out, i.e. escape; causatively, to deliver calve, carry away safe, deliver, (cause to) escape.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1518}/H9030/[H1518]', 'inflected', 'heb', 'גִּיחַ', '["gîyach"]', '["[were] drawing forth/ me"]', '["v"]', 'to gush forth (as water), generally to issue break forth, labor to bring forth, come forth, draw up, take out.', 'or (shortened) גֹּחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0982}/H9030/[H982]', 'inflected', 'heb', 'בָּטַח', '["bâṭach"]', '["[were] making trust/ me"]', '["v"]', 'properly, to hie for refuge (but not so precipitately as 2620); figuratively, to trust, be confident or sure be bold (confident, secure, sure), careless (one, woman), put confidence, (make to) hope, (put, make to) trust.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0047G}/[H46]', 'lemma', 'heb', 'אַבִּיר', '["ʼabbîyr"]', '["mighty [bulls]","mighty [bulls] of"]', '["a-m"]', 'angel, bull, chiefest, mighty (one), stout(-hearted), strong (one), valiant.', 'for 46');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3803}/H9030/[H3803]', 'inflected', 'heb', 'כָּתַר', '["kâthar"]', '["they have encircled/ me"]', '["v"]', 'to enclose; hence (in a friendly sense) to crown, (in a hostile one) to besiege; also to wait (as restraining oneself) beset round, compass about, be crowned, inclose round, suffer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7580}/[H7580]', 'inflected', 'heb', 'שָׁאַג', '["shâʼag"]', '["and/ roaring"]', '["v"]', 'to rumble or moan × mightily, roar.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H1749>', 'inflected', 'heb', 'כדונג', '["ka./do.Nag"]', '["like <the>/ wax"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2789}/[H2775]', 'inflected', 'heb', 'חֶרֶשׂ', '["cheres"]', '["like <the>/ earthenware"]', '["n-m"]', 'a piece of pottery earth(-en), (pot-) sherd, stone.', 'a collateral form mediating between 2775 and 2791;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4455B}/H9020/[H3947]', 'inflected', 'heb', 'מַלְקוֹחַ', '["malqôwach"]', '["jaws/ my"]', '["n-m"]', 'transitively (in dual) the jaws (as taking food); intransitively, spoil [and captives] (as taken) booty, jaws, prey.', 'from 3947;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6083}/[H6080]', 'inflected', 'heb', 'עָפָר', '["ʻâphâr"]', '["and/ to/ [the] dust of"]', '["n-m"]', 'dust (as powdered or gray); hence, clay, earth, mud ashes, dust, earth, ground, morter, powder, rubbish.', 'from 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8239}/H9030/[H8239]', 'inflected', 'heb', 'שָׁפַת', '["shâphath"]', '["you put/ me"]', '["v"]', 'to locate, i.e. (generally) hang on or (figuratively) establish, reduce bring, ordain, set on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5362B}/H9030/[H5362]', 'inflected', 'heb', 'נָקַף', '["nâqaph"]', '["they have encircled/ me"]', '["v"]', 'to strike with more or less violence (beat, fell, corrode); by implication (of attack) to knock together, i.e. surround or circulate compass (about, -ing), cut down, destroy, go round (about), inclose, round.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7272}/H9020/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["and/ feet/ my"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0360}/H9020/[H353]', 'inflected', 'heb', 'אֱיָלוּת', '["ʼĕyâlûwth"]', '["O strength/ my"]', '["n-f"]', 'power; by implication, protection strength.', 'feminine of 353;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5833}/H9020/[H5828]', 'inflected', 'heb', 'עֶזְרָה', '["ʻezrâh"]', '["to/ help/ my"]', '["n-f"]', 'aid help(-ed, -er).', 'or עֶזְרָת; (Psalm 60:11 (13); Psalm 108:12 (13)), feminine of 5828;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5337}/H9012/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["deliver/ !"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3173}/H9020/[H3161]', 'inflected', 'heb', 'יָחִיד', '["yâchîyd"]', '["only [life]/ my"]', '["a"]', 'properly, united, i.e. sole; by implication, beloved; also lonely; (feminine) the life (as not to be replaced) darling, desolate, only (child, son), solitary.', 'from 3161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H7161A}/[H7160]', 'inflected', 'heb', 'קֶרֶן', '["qeren"]', '["and/ from/ [the] horns of"]', '["n-f n-pr-loc"]', 'a horn (as projecting); by implication, a flask, cornet; by resemblance. an elephant''s tooth (i.e. ivory), a corner (of the altar), a peak (of a mountain), a ray (of light); figuratively, power × hill, horn.', 'from 7160;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1984B}/H9031/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["I praise/ you","I will praise/ you","it praises/ you","may he praise/ you","they praise/ you","they praised/ you"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1984B}/H9033/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["I will praise/ him","let them praise/ him","may they praise/ him","praise/ him"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3513G}/H9033/[H3513]', 'inflected', 'heb', 'כָּבַד', '["kâbad"]', '["honor/ him"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1481C}/[H1481]', 'inflected', 'heb', 'גּוּר', '["gûwr"]', '["and/ be afraid"]', '["v"]', 'properly, to turn aside from the road (for a lodging or any other purpose), i.e. sojourn (as a guest); also to shrink, fear (as in a strange place); also to gather for hostility (as afraid) abide, assemble, be afraid, dwell, fear, gather (together), inhabitant, remain, sojourn, stand in awe, (be) stranger, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6039}/[H6031]', 'lemma', 'heb', 'עֱנוּת', '["ʻĕnûwth"]', '["[the] affliction of"]', '["n-f"]', 'affliction affliction.', 'from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7768}/H9043/[H7768]', 'inflected', 'heb', 'שָׁוַע', '["shâvaʻ"]', '["and/ when/ cried for help/ he"]', '["v"]', 'properly, to be free; but used only causatively and reflexively, to halloo (for help, i.e. freedom from some trouble) cry (aloud, out), shout.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8416}/H9020/[H1984]', 'inflected', 'heb', 'תְּהִלָּה', '["tᵉhillâh"]', '["[are] praise/ my","praise/ my"]', '["n-f"]', 'laudation; specifically (concretely) a hymn praise.', 'from 1984;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3373}/H9023/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["[those] fearing/ him"]', '["a"]', 'fearing; morally, reverent afraid, fear (-ful).', 'from 3372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1879}/[H1878]', 'lemma', 'heb', 'דָּשֵׁן', '["dâshên"]', '["[the] fat [people] of","fat"]', '["a"]', 'fat; figuratively, rich, fertile fat.', 'from 1878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4999}/[H4998]', 'inflected', 'heb', 'נָאָה', '["nâʼâh"]', '["in/ pastures of"]', '["n-f"]', 'a home; figuratively, a pasture habitation, house, pasture, pleasant place.', 'from 4998;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7257}/H9030/[H7257]', 'inflected', 'heb', 'רָבַץ', '["râbats"]', '["he makes lie down/ me"]', '["v"]', 'to crouch (on all four legs folded, like a recumbent animal); by implication, to recline, repose, brood, lurk, imbed crouch (down), fall down, make a fold, lay, (cause to, make to) lie (down), make to rest, sit.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5095}/H9030/[H5095]', 'inflected', 'heb', 'נָהַל', '["nâhal"]', '["he leads/ me"]', '["v"]', 'properly, to run with a sparkle, i.e. flow; hence (transitively), to conduct, and (by inference) to protect, sustain carry, feed, guide, lead (gently, on).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7626G>/H9021', 'opaque', 'heb', 'שֵׁבֶט', '["shêbeṭ"]', '["rod/ your"]', '["n-m"]', 'a scion, i.e. (literally) a stick (for punishing, writing, fighting, ruling, walking, etc.) or (figuratively) a clan × correction, dart, rod, sceptre, staff, tribe.', 'from an unused root probably meaning to branch off;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4938B}/H9021/[H4937]', 'inflected', 'heb', 'מִשְׁעֵנָה', '["mishʻênâh"]', '["and/ staff/ your"]', '["n-f"]', 'support (abstractly), i.e. (figuratively) sustenance or (concretely) a walking-stick staff.', 'or מִשְׁעֶנֶת; feminine of 4937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1878}/[H1880]', 'lemma', 'heb', 'דָּשֵׁן', '["dâshên"]', '["he will be made fat","it fattens","it has fattened itself","it will be fattened","it will be made fat","you have refreshed"]', '["v"]', 'to be fat; transitively, to fatten (or regard as fat); specifically to anoint; figuratively, to satisfy; to remove (fat) ashes (of sacrifices) accept, anoint, take away the (receive) ashes (from), make (wax) fat.', 'a primitive root; also denominatively (from 1880)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3563A>/H9020', 'opaque', 'heb', 'כּוֹס', '["kôwç"]', '["cup/ my"]', '["n-f"]', 'a cup (as a container), often figuratively, a lot (as if a potion); also some unclean bird, probably an owl (perhaps from the cup-like cavity of its eye) cup, (small) owl. Compare 3599.', 'from an unused root meaning to hold together;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7310}/[H7301]', 'lemma', 'heb', 'רְוָיָה', '["rᵉvâyâh"]', '["[is] saturation"]', '["n-f"]', 'satisfaction runneth over, wealthy.', 'from 7301;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0753}/[H748]', 'inflected', 'heb', 'אֹרֶךְ', '["ʼôrek"]', '["for/ length of"]', '["n-m"]', 'length forever, length, long.', 'from 748;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375O}/[H5375]', 'lemma', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["I lift up","[are] lifting up","[will be] lifting","he has lifted up","let us lift up","lift up","they lift up","you lift up"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7723G}/[H7722]', 'inflected', 'heb', 'שָׁוְא', '["shâvᵉʼ"]', '["to <the>/ falsehood"]', '["n-m"]', 'evil (as destructive), literally (ruin) or morally (especially guile); figuratively idolatry (as false, subjective), uselessness (as deceptive, objective; also adverbially, in vain) false(-ly), lie, lying, vain, vanity.', 'or שַׁו; from the same as 7722 in the sense of desolating;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4820}/[H7411]', 'inflected', 'heb', 'מִרְמָה', '["mirmâh"]', '["to/ deceit"]', '["n-f"]', 'fraud craft, deceit(-ful, -fully), false, feigned, guile, subtilly, treachery.', 'from 7411 in the sense of deceiving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3468}/H9023/[H3467]', 'inflected', 'heb', 'יֶשַׁע', '["yeshaʻ"]', '["salvation/ his"]', '["n-m"]', 'liberty, deliverance, prosperity safety, salvation, saving.', 'or יֵשַׁע; from 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5808}/[H5810]', 'lemma', 'heb', 'עִזּוּז', '["ʻizzûwz"]', '["strong"]', '["a"]', 'forcible; collectively and concretely, an army power, strong.', 'from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5375P}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ I may lift up","and/ lift up"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6960A}/H9031/[H6960]', 'inflected', 'heb', 'קָוָה', '["qâvâh"]', '["I have waited for/ you","[those who] wait for/ you","we have waited for/ you"]', '["v"]', 'to bind together (perhaps by twisting), i.e. collect; (figuratively) to expect gather (together), look, patiently, tarry, wait (for, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0898}/[H898]', 'inflected', 'heb', 'בָּגַד', '["bâgad"]', '["the/ traitor","those/ [who] act treacherously"]', '["v"]', 'to cover (with a garment); figuratively, to act covertly; by implication, to pillage deal deceitfully (treacherously, unfaithfully), offend, transgress(-or), (depart), treacherous (dealer, -ly, man), unfaithful(-ly, man), × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0734}/H9021/[H732]', 'inflected', 'heb', 'אֹרַח', '["ʼôrach"]', '["path/ your","paths/ your"]', '["n-m"]', 'a well-trodden road (literally or figuratively); also a caravan manner, path, race, rank, traveller, troop, (by-, high-) way.', 'from 732;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3925G}/H9030/[H3925]', 'inflected', 'heb', 'לָמַד', '["lâmad"]', '["[who] she taught/ me","teach/ me","teachers/ my","you have taught/ me","you teach/ me"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1869}/H9030/[H1869]', 'inflected', 'heb', 'דָּרַךְ', '["dârak"]', '["he makes tread/ me","lead/ me"]', '["v"]', 'to tread; by implication, to walk; also to string a bow (by treading on it in bending) archer, bend, come, draw, go (over), guide, lead (forth), thresh, tread (down), walk.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0571H}/H9021/[H539]', 'inflected', 'heb', 'אֶמֶת', '["ʼemeth"]', '["in/ truth/ your","to/ faithfulness/ your"]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3925G}/H9030/[H3925]', 'inflected', 'heb', 'לָמַד', '["lâmad"]', '["and/ teach/ me"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7356B}/H9021/[H7355]', 'inflected', 'heb', 'רַחַם', '["racham"]', '["compassion<s>/ your"]', '["n-f"]', 'compassion (in the plural); by extension, the womb (as cherishing the fetus); by implication, a maiden bowels, compassion, damsel, tender love, (great, tender) mercy, pity, womb.', 'from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2617A}/H9021/[H2616]', 'inflected', 'heb', 'חֶסֶד', '["cheçed"]', '["and/ covenant loyalti<es>/ your"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6588}/H9020/[H6586]', 'inflected', 'heb', 'פֶּשַׁע', '["peshaʻ"]', '["and/ transgressions/ my"]', '["n-m"]', 'a revolt (national, moral or religious) rebellion, sin, transgression, trespass.', 'from 6586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2617A}/H9021/[H2616]', 'inflected', 'heb', 'חֶסֶד', '["cheçed"]', '["according to/ covenant loyalty/ your"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2898}/H9021/[H2895]', 'inflected', 'heb', 'טוּב', '["ṭûwb"]', '["[is] goodness/ your","goodness/ your"]', '["n-m"]', 'good (as a noun), in the widest sense, especially goodness (superlative concretely, the best), beauty, gladness, welfare fair, gladness, good(-ness, thing, -s), joy, go well with.', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4941H}/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["by <the>/ judgment","by/ justice","in <the>/ judgment","in <the>/ justice","in/ justice","with/ justice"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5341}/[H5341]', 'inflected', 'heb', 'נָצַר', '["nâtsar"]', '["to/ [those who] keep","to/ guard"]', '["v"]', 'to guard, in a good sense (to protect, maintain, obey, etc.) or a bad one (to conceal, etc.) besieged, hidden thing, keep(-er, -ing), monument, observe, preserve(-r), subtil, watcher(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5475}/[H3245]', 'lemma', 'heb', 'סוֹד', '["çôwd"]', '["[is] counsel","[the] counsel of","[the] gathering of","a secret","counsel","secret counsel"]', '["n-m"]', 'a session, i.e. company of persons (in close deliberation); by implication, intimacy, consultation, a secret assembly, consel, inward, secret (counsel).', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3373}/H9023/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["<to>/ [those] fearing/ him","[belongs] to/ [those] fearing/ him","to/ [those] fearing/ him"]', '["a"]', 'fearing; morally, reverent afraid, fear (-ful).', 'from 3372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1285}/H9023/[H1262]', 'inflected', 'heb', 'בְּרִית', '["bᵉrîyth"]', '["and/ covenant/ his"]', '["n-f"]', 'a compact (because made by passing between pieces of flesh) confederacy, (con-) feder(-ate), covenant, league.', 'from 1262 (in the sense of cutting [like 1254]);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3045}/H9038/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["to/ make known to/ them","to/ make known/ them"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7568}/[H3423]', 'inflected', 'heb', 'רֶשֶׁת', '["resheth"]', '["from/ [the] net"]', '["n-f"]', 'a net (as catching animals) net(-work).', 'from 3423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2603A}/H9030/[H2583]', 'inflected', 'heb', 'חָנַן', '["chânan"]', '["and/ show favor to/ me"]', '["v"]', 'properly, to bend or stoop in kindness to an inferior; to favor, bestow; causatively to implore (i.e. move to favor by petition) beseech, × fair, (be, find, shew) favour(-able), be (deal, give, grant (gracious(-ly), intreat, (be) merciful, have (shew) mercy (on, upon), have pity upon, pray, make supplication, × very.', 'a primitive root (compare 2583);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6041}/[H6031]', 'inflected', 'heb', 'עָנִי', '["ʻânîy"]', '["and/ [the] poor","and/ afflicted","and/ poor [people]"]', '["a"]', 'depressed, in mind or circumstances afflicted, humble, lowly, needy, poor.', 'from 6031; (practically the same as 6035, although the margin constantly disputes this, making 6035 subjective and objective);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4691}/H9020/[H4690]', 'inflected', 'heb', 'מְצוּקָה', '["mᵉtsûwqâh"]', '["from/ distresses/ my"]', '["n-f"]', 'narrowness, i.e. (figuratively) trouble anguish, distress.', 'or מְצֻקָה; feminine of 4690;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3318H}/H9030/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["deliver/ me","he will bring out/ me","you will bring out/ me"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5999}/H9020/[H5998]', 'inflected', 'heb', 'עָמָל', '["ʻâmâl"]', '["and/ trouble/ my"]', '["n"]', 'toil, i.e. wearing effort; hence, worry, whether of body or mind grievance(-vousness), iniquity, labour, mischief, miserable(-sery), pain(-ful), perverseness, sorrow, toil, travail, trouble, wearisome, wickedness.', 'from 5998;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5375I}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ forgive"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8135}/[H8130]', 'inflected', 'heb', 'שִׂנְאָה', '["sinʼâh"]', '["and/ hatred","and/ hatred of"]', '["n-f"]', 'hate exceedingly, hate(-ful, -red).', 'from 8130;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8104H}/H9012/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["preserve/ !"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8537}/[H8552]', 'lemma', 'heb', 'תֹּם', '["tôm"]', '["integrity","integrity of"]', '["n-m"]', 'completeness; figuratively, prosperity; usually (morally) innocence full, integrity, perfect(-ion), simplicity, upright(-ly, -ness), at a venture. See 8550.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3476}/[H3474]', 'inflected', 'heb', 'יֹשֶׁר', '["yôsher"]', '["and/ uprightness"]', '["n-m"]', 'the right equity, meet, right, upright(-ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5341}/H9030/[H5341]', 'inflected', 'heb', 'נָצַר', '["nâtsar"]', '["may they preserve/ me","they preserve/ me","you will preserve/ me"]', '["v"]', 'to guard, in a good sense (to protect, maintain, obey, etc.) or a bad one (to conceal, etc.) besieged, hidden thing, keep(-er, -ing), monument, observe, preserve(-r), subtil, watcher(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6869B}/H9023/[H6862]', 'inflected', 'heb', 'צָרָה', '["tsârâh"]', '["troubles/ his","troubles/ its"]', '["n-f"]', 'tightness (i.e. figuratively, trouble); transitively, a female rival adversary, adversity, affliction, anguish, distress, tribulation, trouble.', 'feminine of 6862;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8537}/H9020/[H8552]', 'inflected', 'heb', 'תֹּם', '["tôm"]', '["in/ integrity/ my"]', '["n-m"]', 'completeness; figuratively, prosperity; usually (morally) innocence full, integrity, perfect(-ion), simplicity, upright(-ly, -ness), at a venture. See 8550.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5254H}/H9030/[H5254]', 'inflected', 'heb', 'נָסָה', '["nâçâh"]', '["and/ put to [the] test/ me"]', '["v"]', 'to test; by implication, to attempt adventure, assay, prove, tempt, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6884}/H9012/[H6884]', 'inflected', 'heb', 'צָרַף', '["tsâraph"]', '["test/ !"]', '["v"]', 'to fuse (metal), i.e. refine (literally or figuratively) cast, (re-) fine(-er), founder, goldsmith, melt, pure, purge away, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0571G}/H9021/[H539]', 'inflected', 'heb', 'אֶמֶת', '["ʼemeth"]', '["in/ faithfulness/ your"]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5356A}/[H5352]', 'inflected', 'heb', 'נִקָּיוֹן', '["niqqâyôwn"]', '["in/ innocence"]', '["n-m"]', 'clearness (literally or figuratively) cleanness, innocency.', 'or נִקָּיֹן; from 5352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5608A}/[H5608]', 'inflected', 'heb', 'סָפַר', '["çâphar"]', '["and/ to/ recount"]', '["v n-m"]', 'properly, to score with a mark as a tally or record, i.e. (by implication) to inscribe, and also to enumerate; intensively, to recount, i.e. celebrate commune, (ac-) count; declare, number, penknife, reckon, scribe, shew forth, speak, talk, tell (out), writer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3225G}/H9028/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["and/ right [hand]/ their"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4721}/[H6950]', 'inflected', 'heb', 'מַקְהֵל', '["maqhêl"]', '["in/ assemblies"]', '["n-m"]', 'an assembly congregation.', 'or (feminine) מַקְהֵלָה; from 6950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0216}/H9020/[H215]', 'inflected', 'heb', 'אוֹר', '["ʼôwr"]', '["[is] light/ my"]', '["n-f"]', 'illumination or (concrete) luminary (in every sense, including lightning, happiness, etc.) bright, clear, day, light (-ning), morning, sun.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3468}/H9020/[H3467]', 'inflected', 'heb', 'יֶשַׁע', '["yeshaʻ"]', '["and/ salvation/ my"]', '["n-m"]', 'liberty, deliverance, prosperity safety, salvation, saving.', 'or יֵשַׁע; from 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4310}/[H4100]', 'inflected', 'heb', 'מִי', '["mîy"]', '["from/ whom?","more than/ whom?"]', '["i"]', 'who? (occasionally, by a peculiar idiom, of things); also (indefinitely) whoever; often used in oblique construction with prefix or suffix any (man), × he, × him, O that! what, which, who(-m, -se, -soever), would to God.', 'an interrogative pronoun of persons, as 4100 is of things,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4581}/[H5810]', 'lemma', 'heb', 'מָעוֹז', '["mâʻôwz"]', '["[is] [the] protection of","[is] [the] refuge of","[is] a refuge","[the] refuge of","[the] stronghold of","a refuge","refuge","strongholds"]', '["n-m"]', 'a fortified place; figuratively, a defence force, fort(-ress), rock, strength(-en), (× most) strong (hold).', '(also מָעוּז ); or מָעֹז (also מָעֻז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3427}/H9040/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["sitting/ my","to dwell/ I"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2372}/[H2372]', 'inflected', 'heb', 'חָזָה', '["châzâh"]', '["to/ look"]', '["v"]', 'to gaze at; mentally to perceive, contemplate (with pleasure); specifically, to have a vision of behold, look, prophesy, provide, see.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5278}/[H5276]', 'inflected', 'heb', 'נֹעַם', '["nôʻam"]', '["on/ [the] kindness of"]', '["n-m"]', 'agreeableness, i.e. delight, suitableness, splendor or grace beauty, pleasant(-ness).', 'from 5276;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1239}/[H1239]', 'inflected', 'heb', 'בָּקַר', '["bâqar"]', '["and/ to/ inquire"]', '["v"]', 'properly, to plough, or (generally) break forth, i.e. (figuratively) to inspect, admire, care for, consider (make) inquire (-ry), (make) search, seek out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1964G}/H9023/[H3201]', 'inflected', 'heb', 'הֵיכָל', '["hêykâl"]', '["in/ temple/ his"]', '["n-m"]', 'a large public building, such as a palace or temple palace, temple.', 'probably from 3201 (in the sense of capacity);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6030B}/H9030/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["and/ answer/ me"]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0622}/H9030/[H622]', 'inflected', 'heb', 'אָסַף', '["ʼâçaph"]', '["he will receive/ me"]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5148}/H9030/[H5148]', 'inflected', 'heb', 'נָחָה', '["nâchâh"]', '["and/ lead/ me"]', '["v"]', 'to guide; by implication, to transport (into exile, or as colonists) bestow, bring, govern, guide, lead (forth), put, straiten.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0734}/[H732]', 'inflected', 'heb', 'אֹרַח', '["ʼôrach"]', '["<in>/ [the] path of","[is] in/ [the] path of","in/ [the] path","in/ [the] path of","in/ a path of"]', '["n-m"]', 'a well-trodden road (literally or figuratively); also a caravan manner, path, race, rank, traveller, troop, (by-, high-) way.', 'from 732;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4334}/[H3474]', 'lemma', 'heb', 'מִישׁוֹר', '["mîyshôwr"]', '["level ground","uprightness"]', '["n-m"]', 'a level, i.e. a plain (often used (with the article prefix) as a proper name of certain districts); figuratively, concord; also straightness, i.e. (figuratively) justice (sometimes adverbially, justly) equity, even place, plain, right(-eously), (made) straight, uprightness.', 'or מִישֹׁר; from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5315L}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["in/ [the] desire of","in/ [the] will of"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3307}/[H3306]', 'inflected', 'heb', 'יָפֵחַ', '["yâphêach"]', '["and/ a witness of"]', '["a"]', 'properly, puffing, i.e. (figuratively) meditating such as breathe out.', 'from 3306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2898}/[H2895]', 'inflected', 'heb', 'טוּב', '["ṭûwb"]', '["by/ [the] goodness of","in/ [the] prosperity of","on/ [the] good thing[s] of","on/ [the] goodness of"]', '["n-m"]', 'good (as a noun), in the widest sense, especially goodness (superlative concretely, the best), beauty, gladness, welfare fair, gladness, good(-ness, thing, -s), joy, go well with.', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6960A}/[H6960]', 'inflected', 'heb', 'קָוָה', '["qâvâh"]', '["and/ I may wait for","and/ [those who] wait for","and/ wait","so/ we may wait eagerly"]', '["v"]', 'to bind together (perhaps by twisting), i.e. collect; (figuratively) to expect gather (together), look, patiently, tarry, wait (for, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8469}/H9020/[H2603]', 'inflected', 'heb', 'תַּחֲנוּן', '["tachănûwn"]', '["supplications/ my"]', '["n-m"]', 'earnest prayer intreaty, supplication.', 'or (feminine) תַּחֲנוּנָה; from 2603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7768}/H9040/[H7768]', 'inflected', 'heb', 'שָׁוַע', '["shâvaʻ"]', '["when/ cried for help/ I","when/ cry for help/ I"]', '["v"]', 'properly, to be free; but used only causatively and reflexively, to halloo (for help, i.e. freedom from some trouble) cry (aloud, out), shout.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5375P}/H9040/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["when/ lift up/ I"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4900}/H9030/[H4900]', 'inflected', 'heb', 'מָשַׁךְ', '["mâshak"]', '["draw/ me","you drag away/ me"]', '["v"]', 'to draw, used in a great variety of applications (including to sow, to sound, to prolong, to develop, to march, to remove, to delay, to be tall, etc.) draw (along, out), continue, defer, extend, forbear, × give, handle, make (pro-, sound) long, × sow, scatter, stretch out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7453}/H9028/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["neighbors/ their"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6467}/H9028/[H6466]', 'inflected', 'heb', 'פֹּעַל', '["pôʻal"]', '["according to/ deed[s]/ their","according to/ work/ their"]', '["n-m"]', 'an act or work (concretely) act, deed, do, getting, maker, work.', 'from 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H7455}/[H7489]', 'inflected', 'heb', 'רֹעַ', '["rôaʻ"]', '["and/ according to/ [the] wickedness of"]', '["n-m"]', 'badness (as marring), physically or morally × be so bad, badness, (× be so) evil, naughtiness, sadness, sorrow, wickedness.', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4611}/H9028/[H5953]', 'inflected', 'heb', 'מַעֲלָל', '["maʻălâl"]', '["deeds/ their"]', '["n-m"]', 'an act (good or bad) doing, endeavour, invention, work.', 'from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1576}/H9028/[H1580]', 'inflected', 'heb', 'גְּמוּל', '["gᵉmûwl"]', '["recompense/ their"]', '["n-m"]', 'treatment, i.e. an act (of good or ill); by implication, service or requital as hast served, benefit, desert, deserving, that which he hath given, recompense, reward.', 'from 1580;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1129}/H9038/[H1129]', 'inflected', 'heb', 'בָּנָה', '["bânâh"]', '["he will rebuild/ them"]', '["v"]', 'to build (literally and figuratively) (begin to) build(-er), obtain children, make, repair, set (up), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4043}/H9020/[H1598]', 'inflected', 'heb', 'מָגֵן', '["mâgên"]', '["and/ shield/ my"]', '["n-m"]', 'a shield (i.e. the small one or buckler); figuratively, a protector; also the scaly hide of the crocodile × armed, buckler, defence, ruler, scale, shield.', 'also (in plural) feminine מְגִנָּה; from 1598;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5937}/[H5937]', 'inflected', 'heb', 'עָלַז', '["ʻâlaz"]', '["and/ I rejoiced","and/ it exulted"]', '["v"]', 'to jump for joy, i.e. exult be joyful, rejoice, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H7892A}/H9020/[H7891]', 'inflected', 'heb', 'שִׁיר', '["shîyr"]', '["and/ from/ song/ my"]', '["n-m n-f"]', 'a song; abstractly, singing musical(-ick), × sing(-er, -ing), song.', 'or feminine שִׁירָה; from 7891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3034}/H9033/[H3027]', 'inflected', 'heb', 'יָדָה', '["yâdâh"]', '["I will give thanks to/ him"]', '["v"]', 'physically, to throw (a stone, an arrow) at or away; especially to revere or worship (with extended hands); intensively, to bemoan (by wringing the hands) cast (out), (make) confess(-ion), praise, shoot, (give) thank(-ful, -s, -sgiving).', 'a primitive root; used only as denominative from 3027; literally, to use (i.e. hold out) the hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4581}/[H5810]', 'inflected', 'heb', 'מָעוֹז', '["mâʻôwz"]', '["and/ [is] [the] refuge of"]', '["n-m"]', 'a fortified place; figuratively, a defence force, fort(-ress), rock, strength(-en), (× most) strong (hold).', '(also מָעוּז ); or מָעֹז (also מָעֻז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7462B}/H9038/[H7462]', 'inflected', 'heb', 'רָעָה', '["râʻâh"]', '["and/ shepherd/ them"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5375H}/H9038/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ carry/ them"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1926}/[H1921]', 'inflected', 'heb', 'הָדָר', '["hâdâr"]', '["[is] with <the>/ majesty","in/ majesti<es> of"]', '["n-m"]', 'magnificence, i.e. ornament or splendor beauty, comeliness, excellency, glorious, glory, goodly, honour, majesty.', 'from 1921;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7540}/H9038/[H7540]', 'inflected', 'heb', 'רָקַד', '["râqad"]', '["and/ he made skip/ them"]', '["v"]', 'properly, to stamp, i.e. to spring about (wildly or for joy) dance, jump, leap, skip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8303}/[H8302]', 'inflected', 'heb', 'שִׁרְיוֹן', '["Shiryôwn"]', '["and/ Sirion"]', '["n-pr-loc"]', 'Shirjon or Sirjon, a peak of the Lebanon Sirion.', 'and שִׂרְיֹן; the same as 8302 (i.e. sheeted with snow);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2834}/[H2834]', 'inflected', 'heb', 'חָשַׂף', '["châsaph"]', '["and/ it stripped bare"]', '["v"]', 'to strip off, i.e. generally to make naked (for exertion or in disgrace), to drain away or bail up (a liquid) make bare, clean, discover, draw out, take, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1964G}/H9023/[H3201]', 'inflected', 'heb', 'הֵיכָל', '["hêykâl"]', '["and/ in/ temple/ his"]', '["n-m"]', 'a large public building, such as a palace or temple palace, temple.', 'probably from 3201 (in the sense of capacity);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1802}/H9030/[H1809]', 'inflected', 'heb', 'דָּלָה', '["dâlâh"]', '["you have drawn up/ me"]', '["v"]', 'properly, to dangle, i.e. to let down a bucket (for drawing out water); figuratively, to deliver draw (out), × enough, lift up.', 'a primitive root (compare 1809);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7495}/H9030/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["and/ you healed/ me"]', '["v"]', 'properly, to mend (by stitching), i.e. (figuratively) to cure cure, (cause to) heal, physician, repair, × thoroughly, make whole. See 7503.', 'or רָפָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3381}/H9040/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["from/ going down/ my"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2143}/[H2142]', 'inflected', 'heb', 'זֵכֶר', '["zêker"]', '["<into>/ a memory of","to/ [the] remembrance of"]', '["n-m"]', 'a memento, abstractly recollection (rarely if ever); by implication, commemoration memorial, memory, remembrance, scent.', 'or זֶכֶר; from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7522}/H9023/[H7521]', 'inflected', 'heb', 'רָצוֹן', '["râtsôwn"]', '["[is] in/ favor/ his"]', '["n-m"]', 'delight (especially as shown) (be) acceptable(-ance, -ed), delight, desire, favour, (good) pleasure, (own, self, voluntary) will, as...(what) would.', 'or רָצֹן; from 7521;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7440}/[H7442]', 'lemma', 'heb', 'רִנָּה', '["rinnâh"]', '["a cry of entreaty","a shout of joy"]', '["n-f"]', 'properly, a creaking (or shrill sound), i.e. shout (of joy or grief) cry, gladness, joy, proclamation, rejoicing, shouting, sing(-ing), triumph.', 'from 7442;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7959}/H9020/[H7951]', 'inflected', 'heb', 'שֶׁלֶו', '["shelev"]', '["in/ prosperity/ my"]', '["n-m"]', 'security prosperity.', 'from 7951;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5769I}/[H5956]', 'inflected', 'heb', 'עוֹלָם', '["ʻôwlâm"]', '["for/ ever"]', '["n-m"]', 'properly, concealed, i.e. the vanishing point; generally, time out of mind (past or future), i.e. (practically) eternity; frequentatively, adverbial (especially with prepositional prefix) always alway(-s), ancient (time), any more, continuance, eternal, (for, (n-)) ever(-lasting, -more, of old), lasting, long (time), (of) old (time), perpetual, at any time, (beginning of the) world ( without end). Compare 5331, 5703.', 'or עֹלָם; from 5956;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7522}/H9021/[H7521]', 'inflected', 'heb', 'רָצוֹן', '["râtsôwn"]', '["in/ favor/ your"]', '["n-m"]', 'delight (especially as shown) (be) acceptable(-ance, -ed), delight, desire, favour, (good) pleasure, (own, self, voluntary) will, as...(what) would.', 'or רָצֹן; from 7521;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H2042>/H9020', 'inflected', 'heb', 'להררי', '["le./ha.R/i"]', '["to/ mountain/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1818}/H9020/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["in/ blood/ my"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3381}/H9040/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["in/ going down/ my","when/ brought down/ I"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3034}/H9031/[H3027]', 'inflected', 'heb', 'יָדָה', '["yâdâh"]', '["¿/ will it give thanks to/ you"]', '["v"]', 'physically, to throw (a stone, an arrow) at or away; especially to revere or worship (with extended hands); intensively, to bemoan (by wringing the hands) cast (out), (make) confess(-ion), praise, shoot, (give) thank(-ful, -s, -sgiving).', 'a primitive root; used only as denominative from 3027; literally, to use (i.e. hold out) the hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5046}/[H5046]', 'inflected', 'heb', 'נָגַד', '["nâgad"]', '["¿/ will it declare"]', '["v"]', 'properly, to front, i.e. stand boldly out opposite; by implication (causatively), to manifest; figuratively, to announce (always by word of mouth to one present); specifically, to expose, predict, explain, praise bewray, × certainly, certify, declare(-ing), denounce, expound, × fully, messenger, plainly, profess, rehearse, report, shew (forth), speak, × surely, tell, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0571G}/H9021/[H539]', 'inflected', 'heb', 'אֶמֶת', '["ʼemeth"]', '["faithfulness/ your"]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4553}/H9020/[H5594]', 'inflected', 'heb', 'מִסְפֵּד', '["miçpêd"]', '["wailing/ my"]', '["n-m"]', 'a lamentation lamentation, one mourneth, mourning, wailing.', 'from 5594;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4234}/[H2342]', 'inflected', 'heb', 'מָחוֹל', '["mâchôwl"]', '["into/ dancing"]', '["n-m"]', 'a (round) dance dance(-cing).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8242}/H9020/[H8264]', 'inflected', 'heb', 'שַׂק', '["saq"]', '["sackcloth/ my"]', '["n-m"]', 'properly, a mesh (as allowing a liquid to run through), i.e. coarse loose cloth or sacking (used in mourning and for bagging); hence, a bag (for grain, etc.) sack(-cloth, -clothes).', 'from 8264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2167}/H9031/[H2168]', 'inflected', 'heb', 'זָמַר', '["zâmar"]', '["I will sing praises to/ you","it may sing praises to/ you"]', '["v"]', 'properly, to touch the strings or parts of a musical instrument, i.e. play upon it; to make music, accompanied by the voice; hence to celebrate in song and music give praise, sing forth praises, psalms.', 'a primitive root (perhaps identical with 2168 through the idea of striking with the fingers);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1826H}/[H1724]', 'lemma', 'heb', 'דָּמַם', '["dâmam"]', '["be silent","he will be silent","it may be silent","may they be silent","they are silent","they will be silenced","you will be silent"]', '["v"]', 'to be dumb; by implication, to be astonished, to stop; also to perish cease, be cut down (off), forbear, hold peace, quiet self, rest, be silent, keep (put to) silence, be (stand) still, tarry, wait.', 'a primitive root (compare 1724, 1820);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6697H}/[H6696]', 'inflected', 'heb', 'צוּר', '["tsûwr"]', '["<into>/ [the] rock of","<into>/ a rock","<into>/ a rock of","to/ [the] rock of"]', '["n-m"]', 'properly, a cliff (or sharp rock, as compressed); generally, a rock or boulder; figuratively, a refuge; also an edge (as precipitous) edge, × (mighty) God (one), rock, × sharp, stone, × strength, × strong. See also 1049.', 'or צֻר; from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3467}/H9030/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["[is] to/ save/ me","to/ save/ me"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5095}/H9030/[H5095]', 'inflected', 'heb', 'נָהַל', '["nâhal"]', '["and/ you lead/ me"]', '["v"]', 'properly, to run with a sparkle, i.e. flow; hence (transitively), to conduct, and (by inference) to protect, sustain carry, feed, guide, lead (gently, on).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6869B}/[H6862]', 'inflected', 'heb', 'צָרָה', '["tsârâh"]', '["<in>/ [the] troubles of","in <the>/ trouble","in/ trouble","in/ troubles"]', '["n-f"]', 'tightness (i.e. figuratively, trouble); transitively, a female rival adversary, adversity, affliction, anguish, distress, tribulation, trouble.', 'feminine of 6862;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4800}/[H7337]', 'inflected', 'heb', 'מֶרְחָב', '["merchâb"]', '["in <the>/ roomy place"]', '["n-m"]', 'enlargement, either literally (an open space, usually in a good sense), or figuratively (liberty) breadth, large place (room).', 'from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3708A}/[H3707]', 'inflected', 'heb', 'כַּעַס', '["kaʻaç"]', '["with/ grief"]', '["n-m"]', 'vexation anger, angry, grief, indignation, provocation, provoking, × sore, sorrow, spite, wrath.', 'or (in Job) כַּעַשׂ; from 3707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0990J>/H9020', 'inflected', 'heb', 'ובטני', '["u./vit.N/i"]', '["and/ belly/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8141}/H9020/[H8138]', 'inflected', 'heb', 'שָׁנֶה', '["shâneh"]', '["and/ years/ my"]', '["n-f"]', 'a year (as a revolution of time) whole age, × long, old, year(× -ly).', '(in plural or (feminine) שָׁנָה; from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0585}/[H584]', 'inflected', 'heb', 'אֲנָחָה', '["ʼănâchâh"]', '["with/ groaning"]', '["n-f"]', 'sighing groaning, mourn, sigh.', 'from 584;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5771G}/H9020/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["by/ iniquity/ my"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7934}/H9020/[H7931]', 'inflected', 'heb', 'שָׁכֵן', '["shâkên"]', '["and/ to/ neighbors/ my"]', '["a"]', 'a resident; by extension, a fellow-citizen inhabitant, neighbour, nigh.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3045}/H9020/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["to/ acquaintances/ my"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3820A}/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["from/ [the] heart"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4032}/[H1481]', 'lemma', 'heb', 'מָגוֹר', '["mâgôwr"]', '["terror"]', '["n-m"]', 'a fright (objective or subjective) fear, terror. Compare 4036.', 'or (Lamentations 2:22) מָגוּר; from 1481 in the sense of fearing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3245}/H9048/[H3245]', 'inflected', 'heb', 'יָסַד', '["yâçad"]', '["when/ they seated/ themselves"]', '["v"]', 'to set (literally or figuratively); intensively, to found; reflexively, to sit down together, i.e. settle, consult appoint, take counsel, establish, (lay the, lay for a) found(-ation), instruct, lay, ordain, set, × sure.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6256}/H9020/[H5703]', 'inflected', 'heb', 'עֵת', '["ʻêth"]', '["times/ my"]', '["n-f"]', 'time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when.', 'from 5703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H7291}/H9030/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["and/ from/ pursuers/ my"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3373}/H9021/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["for/ [those] fearing/ you"]', '["a"]', 'fearing; morally, reverent afraid, fear (-ful).', 'from 3372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5641}/H9038/[H5641]', 'inflected', 'heb', 'סָתַר', '["çâthar"]', '["you hide/ them"]', '["v"]', 'to hide (by covering), literally or figuratively be absent, keep close, conceal, hide (self), (keep) secret, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7407}/[H7405]', 'inflected', 'heb', 'רֹכֶס', '["rôkeç"]', '["from/ [the] conspiracies of"]', '["n-m"]', 'a snare (as of tied meshes) pride.', 'from 7405;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6845}/H9038/[H6845]', 'inflected', 'heb', 'צָפַן', '["tsâphan"]', '["you hide/ them"]', '["v"]', 'to hide (by covering over); by implication, to hoard or reserve; figuratively to deny; specifically (favorably) to protect, (unfavorably) to lurk esteem, hide(-den one, self), lay up, lurk (be set) privily, (keep) secret(-ly, place).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2648}/H9040/[H2648]', 'inflected', 'heb', 'חָפַז', '["châphaz"]', '["when/ was hastening/ I"]', '["v"]', 'properly, to start up suddenly, i.e. (by implication) to hasten away, to fear (make) haste (away), tremble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1629}/[H1629]', 'lemma', 'heb', 'גָּרַז', '["gâraz"]', '["I have been cut off"]', '["v"]', 'to cut off cut off.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869H}/H9021/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["eyes/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3176H}/[H3176]', 'inflected', 'heb', 'יָחַל', '["yâchal"]', '["those/ [who] hope","those/ [who] wait"]', '["v"]', 'to wait; by implication, to be patient, hope (cause to, have, make to) hope, be pained, stay, tarry, trust, wait.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4905}/[H7919]', 'lemma', 'heb', 'מַשְׂכִּיל', '["maskîyl"]', '["a poem"]', '["n-m"]', 'instructive, i.e. a didactic poem Maschil.', 'from 7919;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7307G}/H9023/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["by/ spirit/ his","in/ spirit/ his","over/ spirit/ his"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7581}/H9020/[H7580]', 'inflected', 'heb', 'שְׁאָגָה', '["shᵉʼâgâh"]', '["in/ cry of distress/ my"]', '["n-f"]', 'a rumbling or moan roaring.', 'from 7580;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3955>/H9020', 'opaque', 'heb', 'לְשַׁד', '["lᵉshad"]', '["juice/ my"]', '["n-m"]', '(figuratively) vigor; also a sweet or fat cake fresh, moisture.', 'from an unused root of uncertain meaning; apparently juice, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2725}/[H2717]', 'inflected', 'heb', 'חֲרָבוֹן', '["chărâbôwn"]', '["by/ [the] dry heat<s> of"]', '["n-m"]', 'parching heat drought.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5771G}/H9020/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["and/ iniquity/ my"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6862B}/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["from/ distress"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7438}/[H7442]', 'lemma', 'heb', 'רֹן', '["rôn"]', '["shouts of"]', '["n-m"]', 'a shout (of deliverance) song.', 'from 7442;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6405}/[H6403]', 'lemma', 'heb', 'פַּלֵּט', '["pallêṭ"]', '["deliverance; [surely]"]', '["n-m"]', 'escape deliverance, escape.', 'from 6403;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7919A}/H9031/[H7919]', 'inflected', 'heb', 'שָׂכַל', '["sâkal"]', '["I will instruct/ you"]', '["v"]', 'to be (causatively, make or act) circumspect and hence, intelligent consider, expert, instruct, prosper, (deal) prudent(-ly), (give) skill(-ful), have good success, teach, (have, make to) understand(-ing), wisdom, (be, behave self, consider, make) wise(-ly), guide wittingly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6505}/[H6504]', 'inflected', 'heb', 'פֶּרֶד', '["pered"]', '["like/ a mule"]', '["n-m"]', 'a mule (perhaps from his lonely habits) mule.', 'from 6504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H4964>', 'inflected', 'heb', 'במתג', '["be./me.teg"]', '["with/ bridle"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1102}/[H1102]', 'inflected', 'heb', 'בָּלַם', '["bâlam"]', '["to/ restrain"]', '["v"]', 'to muzzle be held in.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4341}/[H3510]', 'lemma', 'heb', 'מַכְאֹב', '["makʼôb"]', '["[are] pains","[is] pain","[the] pain of","pain","pains"]', '["n-m"]', 'anguish or (figuratively) affliction grief, pain, sorrow.', 'sometimes מַכְאוֹב; also (feminine Isaiah 53:3) מַכְאֹבָה; from 3510;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0982}/[H982]', 'inflected', 'heb', 'בָּטַח', '["bâṭach"]', '["and/ the/ [one who] trusts","and/ those/ [who] trust"]', '["v"]', 'properly, to hie for refuge (but not so precipitately as 2620); figuratively, to trust, be confident or sure be bold (confident, secure, sure), careless (one, woman), put confidence, (make to) hope, (put, make to) trust.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7442B}/[H7442]', 'inflected', 'heb', 'רָנַן', '["rânan"]', '["and/ cry out","and/ shout for joy","and/ shouting for joy","and/ sing for joy","and/ they may sing for joy","so/ I may sing for joy","so/ it may shout for joy","so/ let us shout for joy"]', '["v"]', 'properly, to creak (or emit a stridulous sound), i.e. to shout (usually for joy) aloud for joy, cry out, be joyful (greatly, make to) rejoice, (cause to) shout (for joy), (cause to) sing (aloud, for joy, out), triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5000}/[H4998]', 'lemma', 'heb', 'נָאוֶה', '["nâʼveh"]', '["[is] fitting","[is] lovely","[is] suitable","lovely"]', '["a"]', 'suitable, or beautiful becometh, comely, seemly.', 'from 4998 or 5116;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5067}/[H5110]', 'inflected', 'heb', 'נֵד', '["nêd"]', '["like <the>/ heap"]', '["n-m"]', 'a mound, i.e. wave heap.', 'from 5110 in the sense of piling up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6331}/[H6331]', 'lemma', 'heb', 'פּוּר', '["pûwr"]', '["I will break off","he broke","he makes ineffectual"]', '["v"]', 'to crush break, bring to nought, × utterly take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7688}/[H7688]', 'lemma', 'heb', 'שָׁגַח', '["shâgach"]', '["[is] gazing","he looks","they will stare"]', '["v"]', 'to peep, i.e. glance sharply at look (narrowly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3335G}/[H3334]', 'inflected', 'heb', 'יָצַר', '["yâtsar"]', '["the/ [one who] forms"]', '["v"]', 'to mould into a form; especially as a potter; figuratively, to determine (i.e. form a resolution) × earthen, fashion, form, frame, make(-r), potter, purpose.', 'probably identical with 3334 (through the squeezing into shape); (compare 3331);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4639K}/H9028/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["deeds/ their"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8668G}/[H7768]', 'inflected', 'heb', 'תְּשׁוּעָה', '["tᵉshûwʻâh"]', '["for/ [the] salvation of","for/ victory"]', '["n-f"]', 'rescue (literal or figurative, persons, national or spiritual) deliverance, help, safety, salvation, victory.', 'or תְּשֻׁעָה; from 7768 in the sense of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2428G}/H9023/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["strength/ its"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3176H}/[H3176]', 'inflected', 'heb', 'יָחַל', '["yâchal"]', '["to <the>/ [those who] hope"]', '["v"]', 'to wait; by implication, to be patient, hope (cause to, have, make to) hope, be pained, stay, tarry, trust, wait.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2617A}/H9023/[H2616]', 'inflected', 'heb', 'חֶסֶד', '["cheçed"]', '["for/ covenant loyalty/ his"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2421}/H9038/[H2331]', 'inflected', 'heb', 'חָיָה', '["châyâh"]', '["and/ to/ preserve alive/ them"]', '["v"]', 'to live, whether literally or figuratively; causatively, to revive keep (leave, make) alive, × certainly, give (promise) life, (let, suffer to) live, nourish up, preserve (alive), quicken, recover, repair, restore (to life), revive, (× God) save (alive, life, lives), × surely, be whole.', 'a primitive root (compare 2331, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315G}/H9025/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["desire/ our","self/ our"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5828}/H9025/[H5826]', 'inflected', 'heb', 'עֵזֶר', '["ʻêzer"]', '["[is] help/ our","help/ our"]', '["n-m"]', 'aid help.', 'from 5826;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4043}/H9025/[H1598]', 'inflected', 'heb', 'מָגֵן', '["mâgên"]', '["and/ shield/ our"]', '["n-m"]', 'a shield (i.e. the small one or buckler); figuratively, a protector; also the scaly hide of the crocodile × armed, buckler, defence, ruler, scale, shield.', 'also (in plural) feminine מְגִנָּה; from 1598;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3820A}/H9025/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["heart/ our"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8138A}/H9043/[H8138]', 'inflected', 'heb', 'שָׁנָה', '["shânâh"]', '["when/ changed/ he"]', '["v"]', 'to fold, i.e. duplicate (literally or figuratively); by implication, to transmute (transitive or intransitive) do (speak, strike) again, alter, double, (be given to) change, disguise, (be) diverse, pervert, prefer, repeat, return, do the second time.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0040I}/[H1]', 'lemma', 'heb', 'אֲבִימֶלֶךְ', '["ʼĂbîymelek"]', '["Abimelech"]', '["n-pr-m"]', 'Abimelek, the name of two Philistine kings and of two Israelites Abimelech.', 'from 1 and 4428; father of (the) king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8416}/H9023/[H1984]', 'inflected', 'heb', 'תְּהִלָּה', '["tᵉhillâh"]', '["praise/ his"]', '["n-f"]', 'laudation; specifically (concretely) a hymn praise.', 'from 1984;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4034}/H9020/[H4032]', 'inflected', 'heb', 'מְגוֹרַה', '["mᵉgôwrah"]', '["fears/ my"]', '["n-f"]', 'affright fear.', 'feminine of 4032;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5102B}/[H5102]', 'inflected', 'heb', 'נָהַר', '["nâhar"]', '["and/ they are radiant","and/ you will be radiant"]', '["v"]', 'to sparkle, i.e. (figuratively) be cheerful; hence (from the sheen of a running stream) to flow, i.e. (figuratively) assemble flow (together), be lightened.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2659}/[H2658]', 'lemma', 'heb', 'חָפֵר', '["châphêr"]', '["it has displayed shame","she will be abashed","they are abashed","they be abashed","you will display shame"]', '["v"]', 'to blush; figuratively, to be ashamed, disappointed; causatively, to shame, reproach be ashamed, be confounded, be brought to confusion (unto shame), come (be put to) shame, bring reproach.', 'a primitive root (perhaps rather the same as 2658 through the idea of detection);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2502A}/H9038/[H2502]', 'inflected', 'heb', 'חָלַץ', '["châlats"]', '["and/ he rescued/ them"]', '["v"]', 'to pull off; hence (intensively) to strip, (reflex.) to depart; by implication, to deliver, equip (for fight); present, strengthen arm (self), (go, ready) armed (× man, soldier), deliver, draw out, make fat, loose, (ready) prepared, put off, take away, withdraw self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7456}/[H7456]', 'inflected', 'heb', 'רָעֵב', '["râʻêb"]', '["and/ they are hungry"]', '["v"]', 'to hunger (suffer to) famish, (be, have, suffer, suffer to) hunger(-ry).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3925G}/H9036/[H3925]', 'inflected', 'heb', 'לָמַד', '["lâmad"]', '["I will teach/ you"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3956G}/H9021/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["tongue/ your"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7451H}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["from/ evil"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7291}/H9033/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["and/ pursue/ it"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0241G}/H9023/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["and/ ears/ his","and/ ears/ its"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6213A}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["[is] on/ [those who] do"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5337}/H9038/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["he delivered/ them","he delivers/ them","it delivers/ them"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1793A}/[H1792]', 'lemma', 'heb', 'דַּכָּא', '["dakkâʼ"]', '["[people] crushed of","a [person] contrite"]', '["a n-m"]', 'crushed (literally powder, or figuratively, contrite) contrite, destruction.', 'from 1792;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H3605}/H9028/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["and/ from/ all of/ them"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8130}/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["and/ [one who] hates","and/ [those who] hate","and/ hated"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7378}/H9012/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["conduct/ !","contend/ !"]', '["v"]', 'properly, to toss, i.e. grapple; mostly figuratively, to wrangle, i.e. hold a controversy; (by implication) to defend adversary, chide, complain, contend, debate, × ever, × lay wait, plead, rebuke, strive, × thoroughly.', 'or רוּב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3401}/H9020/[H7378]', 'inflected', 'heb', 'יָרִיב', '["yârîyb"]', '["opponents/ my"]', '["n-m"]', 'literally he will contend; properly, adjective contentious; used as noun, an adversary that content(-eth), that strive.', 'from 7378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3898A}/H9030/[H3898]', 'inflected', 'heb', 'לָחַם', '["lâcham"]', '["[those who] fight with/ me"]', '["v"]', 'to feed on; figuratively, to consume; by implication, to battle (as destruction) devour, eat, × ever, fight(-ing), overcome, prevail, (make) war(-ring).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6965B}/H9012/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["and/ arise/ !"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5833}/H9020/[H5828]', 'inflected', 'heb', 'עֶזְרָה', '["ʻezrâh"]', '["<in>/ help/ my"]', '["n-f"]', 'aid help(-ed, -er).', 'or עֶזְרָת; (Psalm 60:11 (13); Psalm 108:12 (13)), feminine of 5828;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7324}/[H7324]', 'inflected', 'heb', 'רוּק', '["rûwq"]', '["and/ draw out"]', '["v"]', 'to pour out (literally or figuratively), i.e. empty × arm, cast out, draw (out), (make) empty, pour forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3444}/H9022/[H3467]', 'inflected', 'heb', 'יְשׁוּעָה', '["yᵉshûwʻâh"]', '["[am] salvation/ your"]', '["n-f"]', 'something saved, i.e. (abstractly) deliverance; hence, aid, victory, prosperity deliverance, health, help(-ing), salvation, save, saving (health), welfare.', 'feminine passive participle of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5472}/[H5472]', 'lemma', 'heb', 'סוּג', '["çûwg"]', '["I have turned back","[one] backslidden of","[they will be] turned back","he turns back","it had turned back","may they be turned back","they have turned","they will be turned back","we will turn back"]', '["v"]', 'properly, to flinch, i.e. (by implication) to go back, literally (to retreat) or figuratively (to apostatize) backslider, drive, go back, turn (away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2659}/[H2658]', 'inflected', 'heb', 'חָפֵר', '["châphêr"]', '["and/ [who] causes shame","and/ he may act shamefully","and/ may they be abashed","and/ she is abashed","and/ they may be abashed","and/ you may be abashed"]', '["v"]', 'to blush; figuratively, to be ashamed, disappointed; causatively, to shame, reproach be ashamed, be confounded, be brought to confusion (unto shame), come (be put to) shame, bring reproach.', 'a primitive root (perhaps rather the same as 2658 through the idea of detection);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7451I}/H9020/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["<of> harm/ my"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1760A}/[H1760]', 'lemma', 'heb', 'דָּחָה', '["dâchâh"]', '["certainly <to push>","he is pushed down","pushing","they were pushed down"]', '["v"]', 'to push down chase, drive away (on), overthrow, outcast, × sore, thrust, totter.', 'or דָּחַח; (Jeremiah 23:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2519}/[H2505]', 'inflected', 'heb', 'חֲלַקְלַקָּה', '["chălaqlaqqâh"]', '["and/ slippery places"]', '["n-f"]', 'properly, something very smooth; i.e. a treacherous spot; figuratively, blandishment flattery, slippery.', 'by reduplication from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7845H}/[H7743]', 'lemma', 'heb', 'שַׁחַת', '["shachath"]', '["[the] pit of","a pit"]', '["n-f"]', 'a pit (especially as a trap); figuratively, destruction corruption, destruction, ditch, grave, pit.', 'from 7743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7568}/H9028/[H3423]', 'inflected', 'heb', 'רֶשֶׁת', '["resheth"]', '["net/ their"]', '["n-f"]', 'a net (as catching animals) net(-work).', 'from 3423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5315H}/H9020/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["for/ life/ my","for/ self/ my"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7568}/H9023/[H3423]', 'inflected', 'heb', 'רֶשֶׁת', '["resheth"]', '["and/ net/ his"]', '["n-f"]', 'a net (as catching animals) net(-work).', 'from 3423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7722B>', 'inflected', 'heb', 'בשואה', '["be./sho.''Ah"]', '["in/ destruction"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3444}/H9023/[H3467]', 'inflected', 'heb', 'יְשׁוּעָה', '["yᵉshûwʻâh"]', '["in/ salvation/ his"]', '["n-f"]', 'something saved, i.e. (abstractly) deliverance; hence, aid, victory, prosperity deliverance, health, help(-ing), salvation, save, saving (health), welfare.', 'feminine passive participle of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2389}/[H2388]', 'inflected', 'heb', 'חָזָק', '["châzâq"]', '["from/ a person [too] strong"]', '["a"]', 'strong (usu. in a bad sense, hard, bold, violent) harder, hottest, impudent, loud, mighty, sore, stiff(-hearted), strong(-er).', 'from 2388;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1497}/H9033/[H1497]', 'inflected', 'heb', 'גָּזַל', '["gâzal"]', '["from/ [one who] robs/ him"]', '["v"]', 'to pluck off; specifically to flay, strip or rob catch, consume, exercise (robbery), pluck (off), rob, spoil, take away (by force, violence), tear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7999A}/H9030/[H7999]', 'inflected', 'heb', 'שָׁלַם', '["shâlam"]', '["they repay/ me","you make an end of/ me"]', '["v"]', 'to be safe (in mind, body or estate); figuratively, to be (causatively, make) completed; by implication, to be friendly; by extension, to reciprocate (in various applications) make amends, (make an) end, finish, full, give again, make good, (re-) pay (again), (make) (to) (be at) peace(-able), that is perfect, perform, (make) prosper(-ous), recompense, render, requite, make restitution, restore, reward, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7908}/[H7921]', 'lemma', 'heb', 'שְׁכוֹל', '["shᵉkôwl"]', '["bereavement","childlessness"]', '["n-m"]', 'bereavement loss of children, spoiling.', 'infinitive of 7921;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2470H}/H9048/[H2342]', 'inflected', 'heb', 'חָלָה', '["châlâh"]', '["when/ were sick/ they"]', '["v"]', 'properly, to be rubbed or worn; hence (figuratively) to be weak, sick, afflicted; or (causatively) to grieve, make sick; also to stroke (in flattering), entreat beseech, (be) diseased, (put to) grief, be grieved, (be) grievous, infirmity, intreat, lay to, put to pain, × pray, make prayer, be (fall, make) sick, sore, be sorry, make suit (× supplication), woman in travail, be (become) weak, be wounded.', 'a primitive root (compare 2342, 2470, 2490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2436G>/H9020', 'opaque', 'heb', 'חֵיק', '["chêyq"]', '["bosom/ my"]', '["n-m"]', 'the bosom (literally or figuratively) bosom, bottom, lap, midst, within.', 'or חֵק; and חוֹק; from an unused root, apparently meaning to inclose;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7453}/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["like/ a friend"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0251G}/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["like/ a brother"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0057}/[H56]', 'inflected', 'heb', 'אָבֵל', '["ʼâbêl"]', '["like/ a mourner of"]', '["a"]', 'lamenting mourn(-er, -ing).', 'from 56;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6761}/H9020/[H6760]', 'inflected', 'heb', 'צֶלַע', '["tselaʻ"]', '["and/ at/ stumbling/ my"]', '["n-m"]', 'a limping or full (figuratively) adversity, halt(-ing).', 'from 6760;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5222}/[H5221]', 'lemma', 'heb', 'נֵכֶה', '["nêkeh"]', '["smitten [people]"]', '["a"]', 'a smiter, i.e. (figuratively) traducer abject.', 'from 5221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2611}/[H2610]', 'inflected', 'heb', 'חָנֵף', '["chânêph"]', '["<in>/ godless [ones] of"]', '["a"]', 'soiled (i.e. with sin), impious hypocrite(-ical).', 'from 2610;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3934}/[H3932]', 'lemma', 'heb', 'לָעֵג', '["lâʻêg"]', '["mockers of"]', '["a"]', 'a buffoon; also a foreigner mocker, stammering.', 'from 3932;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H7722A>/H9028', 'inflected', 'heb', 'משאיהם', '["mi./sho.''ei./Hem"]', '["from/ ravages/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3715A}/[H3722]', 'inflected', 'heb', 'כְּפִיר', '["kᵉphîyr"]', '["from/ young lions"]', '["n-m"]', 'a village (as covered in by walls); also a young lion (perhaps as covered with a mane) (young) lion, village. Compare 3723.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7282}/[H7280]', 'lemma', 'heb', 'רָגֵעַ', '["râgêaʻ"]', '["[the] quiet [people] of"]', '["a"]', 'restful, i.e. peaceable that are quiet.', 'from 7280;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2803G}/H9013/[H2803]', 'inflected', 'heb', 'חָשַׁב', '["châshab"]', '["they plan/ !"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5782}/H9012/[H5782]', 'inflected', 'heb', 'עוּר', '["ʻûwr"]', '["awake/ !","stir up/ !","wake up/ !"]', '["v"]', 'to wake (literally or figuratively) (a-) wake(-n, up), lift up (self), × master, raise (up), stir up (self).', 'a primitive root (rather identical with through the idea of opening the eyes);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6974}/H9012/[H3364]', 'inflected', 'heb', 'קוּץ', '["qûwts"]', '["and/ awake/ !"]', '["v"]', 'to awake (literally or figuratively) arise, (be) (a-) wake, watch.', 'a primitive root (identical with through the idea of abruptness in starting up from sleep (compare 3364));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4941G}/H9020/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["for/ judgment/ my"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7379}/H9020/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["for/ cause/ my"]', '["n-m"]', 'a contest (personal or legal) adversary, cause, chiding, contend(-tion), controversy, multitude (from the margin), pleading, strife, strive(-ing), suit.', 'or רִב; from 7378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6664G}/H9021/[H6663]', 'inflected', 'heb', 'צֶדֶק', '["tsedeq"]', '["according to/ righteousness/ your"]', '["n-m"]', 'the right (natural, moral or legal); also (abstractly) equity or (figuratively) prosperity × even, (× that which is altogether) just(-ice), (un-)right(-eous) (cause, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7451C}/H9020/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["<of> harm/ my","distress/ my","harm/ my"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3639}/[H3637]', 'inflected', 'heb', 'כְּלִמָּה', '["kᵉlimmâh"]', '["and/ ignominy"]', '["n-f"]', 'disgrace confusion, dishonour, reproach, shame.', 'from 3637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1431}/[H1434]', 'inflected', 'heb', 'גָּדַל', '["gâdal"]', '["who/ magnify themselves"]', '["v"]', 'to be (causatively make) large (in various senses, as in body, mind, estate or honor, also in pride) advance, boast, bring up, exceed, excellent, be(-come, do, give, make, wax), great(-er, come to... estate, things), grow(up), increase, lift up, magnify(-ifical), be much set by, nourish (up), pass, promote, proudly (spoken), tower.', 'a primitive root; properly, to twist (compare 1434), i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2505B}/[H2505]', 'lemma', 'heb', 'חָלַק', '["châlaq"]', '["[who] flatters","a smoother of","he flatters","it is slippery","she makes smooth","they were smooth"]', '["v"]', 'to be smooth (figuratively); by implication (as smooth stones were used for lots) to apportion or separate deal, distribute, divide, flatter, give, (have, im-) part(-ner), take away a portion, receive, separate self, (be) smooth(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8130}/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["to/ hate","to/ hate [it]"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/H9009/<H8064>', 'inflected', 'heb', 'בהשמים', '["be./ha./sha.Ma.yim"]', '["[is] in/ the/ heavens"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0530}/H9021/[H529]', 'inflected', 'heb', 'אֱמוּנָה', '["ʼĕmûwnâh"]', '["faithfulness/ your"]', '["n-f"]', 'literally firmness; figuratively security; morally fidelity faith(-ful, -ly, -ness, (man)), set office, stability, steady, truly, truth, verily.', 'or (shortened) אֱמֻנָה; feminine of 529;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H2042>', 'inflected', 'heb', 'כהררי', '["ke./ha.rei"]', '["[is] like/ [the] mountains of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2620}/H9013/[H982]', 'inflected', 'heb', 'חָסָה', '["châçâh"]', '["they take refuge/ !"]', '["v"]', 'to flee for protection; figuratively, to confide in have hope, make refuge, (put) trust.', 'a primitive root; (compare 982)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7301}/H9013/[H7301]', 'inflected', 'heb', 'רָוָה', '["râvâh"]', '["they take their fill/ !"]', '["v"]', 'to slake the thirst (occasionally of other appetites) bathe, make drunk, (take the) fill, satiate, (abundantly) satisfy, soak, water (abundantly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1880}/[H1878]', 'inflected', 'heb', 'דֶּשֶׁן', '["deshen"]', '["from/ [the] fatness of"]', '["n-m"]', 'the fat; abstractly fatness, i.e. (figuratively) abundance; specifically the (fatty) ashes of sacrifices ashes, fatness.', 'from 1878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5730A}/H9021/[H5727]', 'inflected', 'heb', 'עֵדֶן', '["ʻêden"]', '["delights/ your"]', '["n-m"]', 'pleasure delicate, delight, pleasure. See also 1040.', 'or (feminine) עֶדְנָה; from 5727;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8248H}/H9038/[H8248]', 'inflected', 'heb', 'שָׁקָה', '["shâqâh"]', '["you give to drink/ them"]', '["v"]', 'to quaff, i.e. (causatively) to irrigate or furnish a potion to cause to (give, give to, let, make to) drink, drown, moisten, water. See 7937, 8354.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0216}/H9021/[H215]', 'inflected', 'heb', 'אוֹר', '["ʼôwr"]', '["in/ light/ your"]', '["n-f"]', 'illumination or (concrete) luminary (in every sense, including lightning, happiness, etc.) bright, clear, day, light (-ning), morning, sun.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3045}/H9031/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["to/ [those who] know/ you","to/ make known to/ you"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6666}/H9021/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["and/ righteousness/ your"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935G}/H9030/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["it come to/ me","let them come to/ me"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5110}/H9030/[H5110]', 'inflected', 'heb', 'נוּד', '["nûwd"]', '["it make wander/ me"]', '["v"]', 'to nod, i.e. waver; figuratively, to wander, flee, disappear; also (from shaking the head in sympathy), to console, deplore, or (from tossing the head in scorn) taunt bemoan, flee, get, mourn, make to move, take pity, remove, shake, skip for joy, be sorry, vagabond, way, wandering.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7489A}/[H7489]', 'inflected', 'heb', 'רָעַע', '["râʻaʻ"]', '["by <the>/ evil-doers","in the/ evil-doers"]', '["v"]', 'properly, to spoil (literally, by breaking to pieces); figuratively, to make (or be) good for nothing, i.e. bad (physically, socially or morally) afflict, associate selves (by mistake for 7462), break (down, in pieces), displease, (be, bring, do) evil (doer, entreat, man), show self friendly (by mistake for 7462), do harm, (do) hurt, (behave self, deal) ill, × indeed, do mischief, punish, still, vex, (do) wicked (doer, -ly), be (deal, do) worse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2682A}/[H2681]', 'inflected', 'heb', 'חָצִיר', '["châtsîyr"]', '["[are] like <the>/ grass","like <the>/ grass","like/ [the] grass of"]', '["n-m"]', 'grass; also a leek (collectively) grass, hay, herb, leek.', 'perhaps originally the same as 2681, from the greenness of a courtyard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H3418}/[H3417]', 'inflected', 'heb', 'יֶרֶק', '["yereq"]', '["and/ like/ [the] greenery of"]', '["n-m"]', 'properly, pallor, i.e. hence, the yellowish green of young and sickly vegetation; concretely, verdure, i.e. grass or vegetation grass, green (thing).', 'from 3417 (in the sense of vacuity of color);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5034B}/H9013/[H5034]', 'inflected', 'heb', 'נָבֵל', '["nâbêl"]', '["they will fade/ !"]', '["v"]', 'to wilt; generally, to fall away, fail, faint; figuratively, to be foolish or (morally) wicked; causatively, to despise, disgrace disgrace, dishounour, lightly esteem, fade (away, -ing), fall (down, -ling, off), do foolishly, come to nought, × surely, make vile, wither.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7462C}/[H7462]', 'inflected', 'heb', 'רָעָה', '["râʻâh"]', '["and/ [one who] associates with","and/ graze"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6026}/[H6026]', 'inflected', 'heb', 'עָנַג', '["ʻânag"]', '["and/ take delight","so/ it may take delight"]', '["v"]', 'to be soft or pliable, i.e. (figuratively) effeminate or luxurious delicate(-ness), (have) delight (self), sport self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4862}/[H7592]', 'lemma', 'heb', 'מִשְׁאָלָה', '["mishʼâlâh"]', '["[the] requests of"]', '["n-f"]', 'a request desire, petition.', 'from 7592;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0216}/[H215]', 'inflected', 'heb', 'אוֹר', '["ʼôwr"]', '["[is] like/ a light of","like the/ light","like/ [the] light of"]', '["n-f"]', 'illumination or (concrete) luminary (in every sense, including lightning, happiness, etc.) bright, clear, day, light (-ning), morning, sun.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4941H}/H9021/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["and/ justice/ your"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6672A}/[H6671]', 'inflected', 'heb', 'צֹהַר', '["tsôhar"]', '["[will be] like the/ noon<s>","like the/ noontide<s>"]', '["n-m"]', 'a light (i.e. window); dual double light, i.e. noon midday, noon(-day, -tide), window.', 'from 6671;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6743B}/[H6743]', 'inflected', 'heb', 'צָלַח', '["tsâlach"]', '["in/ [one who] makes prosperous"]', '["v"]', 'to push forward, in various senses (literal or figurative, transitive or intransitive) break out, come (mightily), go over, be good, be meet, be profitable, (cause to, effect, make to, send) prosper(-ity, -ous, -ously).', 'or צָלֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0639G}/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["from/ anger"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3772I}/H9013/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["they will be cut off/ !"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6035}/[H6041]', 'inflected', 'heb', 'עָנָו', '["ʻânâv"]', '["and/ humble [people]"]', '["n-m"]', 'depressed (figuratively), in mind (gentle) or circumstances (needy, especially saintly) humble, lowly, meek, poor. Compare 6041.', 'or (by intermixture with 6041) עָנָיו; from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6026}/[H6026]', 'inflected', 'heb', 'עָנַג', '["ʻânag"]', '["and/ they will take delight","and/ you will take delight"]', '["v"]', 'to be soft or pliable, i.e. (figuratively) effeminate or luxurious delicate(-ness), (have) delight (self), sport self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6662}/[H6663]', 'inflected', 'heb', 'צַדִּיק', '["tsaddîyq"]', '["[belongs] to the/ righteous","[belongs] to the/ righteous [one]","for <the>/ righteous [person]","for the/ righteous","for the/ righteous [person]","of the/ righteous","to <the>/ righteous [person]","to the/ righteous","to the/ righteous [person]","to/ a righteous [person]"]', '["a"]', 'just just, lawful, righteous (man).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2786}/[H2786]', 'inflected', 'heb', 'חָרַק', '["châraq"]', '["and/ [is] gnashing"]', '["v"]', 'to grate the teeth gnash.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7198}/H9028/[H7185]', 'inflected', 'heb', 'קֶשֶׁת', '["qesheth"]', '["bow of/ their","bow/ their","bows/ their"]', '["n-f"]', 'a bow, for shooting (hence, figuratively, strength) or the iris × arch(-er), arrow, bow(-man, -shot).', 'from 7185 in the original sense (of 6983) of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2873}/[H2873]', 'inflected', 'heb', 'טָבַח', '["ṭâbach"]', '["to/ slaughter"]', '["v"]', 'to slaughter (animals or men) kill, (make) slaughter, slay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1995A}/[H1993]', 'inflected', 'heb', 'הָמוֹן', '["hâmôwn"]', '["more than/ [the] wealth of"]', '["n-m"]', 'a noise, tumult, crowd; also disquietude, wealth abundance, company, many, multitude, multiply, noise, riches, rumbling, sounding, store, tumult.', 'or הָמֹן; (Ezekiel 5:7), from 1993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5564}/[H5564]', 'inflected', 'heb', 'סָמַךְ', '["çâmak"]', '["and/ [is] sustaining"]', '["v"]', 'to prop (literally or figuratively); reflexively, to lean upon or take hold of (in a favorable or unfavorable sense) bear up, establish, (up-) hold, lay, lean, lie hard, put, rest self, set self, stand fast, stay (self), sustain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5159}/H9028/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["and/ inheritance/ their"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3368}/[H3365]', 'inflected', 'heb', 'יָקָר', '["yâqâr"]', '["[will be] like/ a splendid [thing] of"]', '["a"]', 'valuable (objectively or subjectively) brightness, clear, costly, excellent, fat, honourable women, precious, reputation.', 'from 3365;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3733B}/[H3769]', 'lemma', 'heb', 'כַּר', '["kar"]', '["[the] pastures","pasture","pastures"]', '["n-m"]', 'a ram (as full-grown and fat), including a battering-ram (as butting); hence, a meadow (as for sheep); also a pad or camel''s saddle (as puffed out) captain, furniture, lamb, (large) pasture, ram. See also 1033, 3746.', 'from 3769 in the sense of plumpness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6227}/[H6225]', 'inflected', 'heb', 'עָשָׁן', '["ʻâshân"]', '["in <the>/ smoke","in/ smoke"]', '["n-m"]', 'smoke, literally or figuratively (vapor, dust, anger) smoke(-ing).', 'from 6225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1288}/H9023/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["blessed [ones]/ his"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7043}/H9023/[H7043]', 'inflected', 'heb', 'קָלַל', '["qâlal"]', '["and/ cursed [ones]/ his"]', '["v"]', 'to be (causatively, make) light, literally (swift, small, sharp, etc.) or figuratively (easy, trifling, vile, etc.) abate, make bright, bring into contempt, (ac-) curse, despise, (be) ease(-y, -ier), (be a, make, make somewhat, move, seem a, set) light(-en, -er, -ly, -ly afflict, -ly esteem, thing), × slight(-ly), be swift(-er), (be, be more, make, re-) vile, whet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4703}/[H6805]', 'lemma', 'heb', 'מִצְעָד', '["mitsʻâd"]', '["[the] steps of"]', '["n-m"]', 'a step; figuratively, companionship going, step.', 'from 6805;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3867B}/[H3867]', 'inflected', 'heb', 'לָוָה', '["lâvâh"]', '["and/ [he is] lending","and/ [who] lends"]', '["v"]', 'properly, to twine, i.e. (by implication) to unite, to remain; also to borrow (as a form of obligation) or (caus.) to lend abide with, borrow(-er), cleave, join (self), lend(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3956G}/H9023/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["and/ tongue/ his","and/ tongue/ its"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0838A}/H9023/[H833]', 'inflected', 'heb', 'אָשֻׁר', '["ʼâshur"]', '["steps/ his"]', '["n-f"]', 'a step going, step.', 'or אַשֻּׁר; from 833 in the sense of going;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7561}/H9033/[H7561]', 'inflected', 'heb', 'רָשַׁע', '["râshaʻ"]', '["he will condemn as guilty/ him"]', '["v"]', 'to be (causatively, do or declare) wrong; by implication, to disturb, violate condemn, make trouble, vex, be (commit, deal, depart, do) wicked(-ly, -ness).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8199}/H9043/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["when/ is judged/ he"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7311A}/H9031/[H7311]', 'inflected', 'heb', 'רוּם', '["rûwm"]', '["and/ he will exalt/ you","and/ she will exalt/ you"]', '["v"]', 'to be high actively, to rise or raise (in various applications, literally or figuratively) bring up, exalt (self), extol, give, go up, haughty, heave (up), (be, lift up on, make on, set up on, too) high(-er, one), hold up, levy, lift(-er) up, (be) lofty, (× a-) loud, mount up, offer (up), presumptuously, (be) promote(-ion), proud, set up, tall(-er), take (away, off, up), breed worms.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6586}/[H6586]', 'inflected', 'heb', 'פָּשַׁע', '["pâshaʻ"]', '["and/ a rebel","and/ transgress","and/ transgressors"]', '["v"]', 'to break away (from just authority), i.e. trespass, apostatize, quarrel offend, rebel, revolt, transgress(-ion, -or).', 'a primitive root (identical with through the idea of expansion);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8668G}/[H7768]', 'inflected', 'heb', 'תְּשׁוּעָה', '["tᵉshûwʻâh"]', '["and/ [the] salvation of"]', '["n-f"]', 'rescue (literal or figurative, persons, national or spiritual) deliverance, help, safety, salvation, victory.', 'or תְּשֻׁעָה; from 7768 in the sense of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4581}/H9028/[H5810]', 'inflected', 'heb', 'מָעוֹז', '["mâʻôwz"]', '["place of refuge/ their","stronghold/ their"]', '["n-m"]', 'a fortified place; figuratively, a defence force, fort(-ress), rock, strength(-en), (× most) strong (hold).', '(also מָעוּז ); or מָעֹז (also מָעֻז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5826}/H9038/[H5826]', 'inflected', 'heb', 'עָזַר', '["ʻâzar"]', '["and/ he helped/ them"]', '["v"]', 'to surround, i.e. protect or aid help, succour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6403}/H9038/[H6403]', 'inflected', 'heb', 'פָּלַט', '["pâlaṭ"]', '["he delivers/ them"]', '["v"]', 'to slip out, i.e. escape; causatively, to deliver calve, carry away safe, deliver, (cause to) escape.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7110A}/H9021/[H7107]', 'inflected', 'heb', 'קֶצֶף', '["qetseph"]', '["in/ anger/ your"]', '["n-m"]', 'a splinter (as chipped off); figuratively, rage or strife foam, indignation, × sore, wrath.', 'from 7107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2534}/H9021/[H3179]', 'inflected', 'heb', 'חֵמָה', '["chêmâh"]', '["and/ by/ rage/ your","and/ in/ wrath/ your"]', '["n-f"]', 'heat; figuratively, anger, poison (from its fever) anger, bottles, hot displeasure, furious(-ly, -ry), heat, indignation, poison, rage, wrath(-ful). See 2529.', 'or (Daniel 11:44) חֵמָא; from 3179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2671}/H9021/[H2686]', 'inflected', 'heb', 'חֵץ', '["chêts"]', '["arrows/ your"]', '["n-m"]', 'properly, a piercer, i.e. an arrow; by implication, a wound; figuratively, (of God) thunder-bolt; the shaft of a spear archer, arrow, dart, shaft, staff, wound.', 'from 2686; also by interchange for 6086');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1320}/H9020/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["in/ flesh/ my"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2195}/H9021/[H2194]', 'inflected', 'heb', 'זַעַם', '["zaʻam"]', '["indignation/ your"]', '["n-m"]', 'strictly froth at the mouth, i.e. (figuratively) fury (especially of God''s displeasure with sin) angry, indignation, rage.', 'from 2194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6106G}/H9020/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["in/ bones/ my"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4853A}/[H5375]', 'inflected', 'heb', 'מַשָּׂא', '["massâʼ"]', '["like/ a burden"]', '["n-m n-pr-m"]', 'a burden; specifically, tribute, or (abstractly) porterage; figuratively, an utterance, chiefly a doom, especially singing; mental, desire burden, carry away, prophecy, × they set, song, tribute.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2250}/H9020/[H2266]', 'inflected', 'heb', 'חַבּוּרָה', '["chabbûwrâh"]', '["wounds/ my"]', '["n-f"]', 'properly, bound (with stripes), i.e. a weal (or black-and-blue mark itself) blueness, bruise, hurt, stripe, wound.', 'or חַבֻּרָה; or חֲבֻרָה; from 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0200}/H9020/[H191]', 'inflected', 'heb', 'אִוֶּלֶת', '["ʼivveleth"]', '["folly/ my"]', '["n-f"]', 'silliness folly, foolishly(-ness).', 'from the same as 191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6313}/[H6313]', 'lemma', 'heb', 'פּוּג', '["pûwg"]', '["I am numb","it grew numb","it grows numb"]', '["v"]', 'to be sluggish cease, be feeble, faint, be slacked.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1794}/[H1790]', 'inflected', 'heb', 'דָּכָה', '["dâkâh"]', '["and/ I am crushed","and/ crushed"]', '["v"]', 'to collapse (phys. or mentally) break (sore), contrite, crouch.', 'a primitive root (compare 1790, 1792);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5100}/[H5099]', 'inflected', 'heb', 'נְהָמָה', '["nᵉhâmâh"]', '["from/ [the] groaning of"]', '["n-f"]', 'snarling disquietness, roaring.', 'feminine of 5099;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8378}/H9020/[H183]', 'inflected', 'heb', 'תַּאֲוָה', '["taʼăvâh"]', '["desire/ my"]', '["n-f"]', 'a longing; by implication, a delight (subjectively, satisfaction, objectively, a charm) dainty, desire, × exceedingly, × greedily, lust(ing), pleasant. See also 6914.', 'from 183 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0585}/H9020/[H584]', 'inflected', 'heb', 'אֲנָחָה', '["ʼănâchâh"]', '["and/ sighing/ my"]', '["n-f"]', 'sighing groaning, mourn, sigh.', 'from 584;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0157H}/H9030/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["friend/ my","friends/ my"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7453}/H9020/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["and/ companions/ my","and/ friends/ my"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5061}/H9020/[H5060]', 'inflected', 'heb', 'נֶגַע', '["negaʻ"]', '["plague/ my"]', '["n-m"]', 'a blow (figuratively, infliction); also (by implication) a spot (concretely, a leprous person or dress) plague, sore, stricken, stripe, stroke, wound.', 'from 5060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7138}/H9020/[H7126]', 'inflected', 'heb', 'קָרוֹב', '["qârôwb"]', '["and/ kinsmen/ my"]', '["a"]', 'near (in place, kindred or time) allied, approach, at hand, any of kin, kinsfold(-sman), (that is) near (of kin), neighbour, (that is) next, (them that come) nigh (at hand), more ready, short(-ly).', 'or קָרֹב; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5367}/[H5367]', 'inflected', 'heb', 'נָקַשׁ', '["nâqash"]', '["and/ they set traps"]', '["v"]', 'to entrap (with a noose), literally or figuratively catch (lay a) snare.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2795}/[H2790]', 'inflected', 'heb', 'חֵרֵשׁ', '["chêrêsh"]', '["[am] like/ a deaf [person]"]', '["a"]', 'deaf (whether literally or spiritual) deaf.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0483}/[H481]', 'inflected', 'heb', 'אִלֵּם', '["ʼillêm"]', '["and/ like/ a dumb [person]"]', '["a"]', 'speechless dumb (man).', 'from 481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4131}/[H4131]', 'inflected', 'heb', 'מוֹט', '["môwṭ"]', '["when/ slips"]', '["v"]', 'to waver; by implication, to slip, shake, fall be carried, cast, be out of course, be fallen in decay, × exceedingly, fall(-ing down), be (re-) moved, be ready, shake, slide, slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6761}/[H6760]', 'inflected', 'heb', 'צֶלַע', '["tselaʻ"]', '["for/ stumbling"]', '["n-m"]', 'a limping or full (figuratively) adversity, halt(-ing).', 'from 6760;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4341}/H9020/[H3510]', 'inflected', 'heb', 'מַכְאֹב', '["makʼôb"]', '["and/ pain/ my"]', '["n-m"]', 'anguish or (figuratively) affliction grief, pain, sorrow.', 'sometimes מַכְאוֹב; also (feminine Isaiah 53:3) מַכְאֹבָה; from 3510;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1672}/[H1672]', 'lemma', 'heb', 'דָּאַג', '["dâʼag"]', '["I am anxious","[am] dreading","[are] anxious","did you dread","it will be anxious"]', '["v"]', 'be anxious be afraid (careful, sorry), sorrow, take thought.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7231}/[H7241]', 'inflected', 'heb', 'רָבַב', '["râbab"]', '["and/ they are many"]', '["v"]', 'properly, to cast together , i.e. increase, especially in number; to multiply by the myriad increase, be many(-ifold), be more, multiply, ten thousands.', 'a primitive root; (compare 7241); also as denominative from 7233;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7853}/H9030/[H7853]', 'inflected', 'heb', 'שָׂטַן', '["sâṭan"]', '["accusers/ my","they accuse/ me"]', '["v"]', 'to attack, (figuratively) accuse (be an) adversary, resist.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7291}/H9040/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["pursuing/ my"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8668G}/H9020/[H7768]', 'inflected', 'heb', 'תְּשׁוּעָה', '["tᵉshûwʻâh"]', '["salvation/ my"]', '["n-f"]', 'rescue (literal or figurative, persons, national or spiritual) deliverance, help, safety, salvation, victory.', 'or תְּשֻׁעָה; from 7768 in the sense of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4269}/[H2629]', 'lemma', 'heb', 'מַחְסוֹם', '["machçôwm"]', '["a muzzle"]', '["n-m"]', 'a muzzle bridle.', 'from 2629;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2896B}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["from/ good","more than/ good"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3511}/H9020/[H3510]', 'inflected', 'heb', 'כְּאֵב', '["kᵉʼêb"]', '["and/ pain/ my"]', '["n-m"]', 'suffering (physical or mental), adversity grief, pain, sorrow.', 'from 3510;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H1901>/H9020', 'inflected', 'heb', 'בהגיגי', '["ba./ha.gi.G/i"]', '["in/ sighing/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2310}/[H2308]', 'lemma', 'heb', 'חָדֵל', '["châdêl"]', '["fleeting"]', '["a"]', 'vacant, i.e. ceasing or destitute he that forbeareth, frail, rejected.', 'from 2308;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H2465>/H9020', 'inflected', 'heb', 'וחלדי', '["ve./chel.D/i"]', '["and/ lifespan/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0369}/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["[are] as/ nothing","[is] like/ nothing","as/ nothing","like/ nothing"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1993}/H9013/[H1949]', 'inflected', 'heb', 'הָמָה', '["hâmâh"]', '["people are in turmoil/ !","they are in an uproar/ !","they roar/ !"]', '["v"]', 'to make a loud sound (like English ''hum''); by implication, to be in great commotion or tumult, to rage, war, moan, clamor clamorous, concourse, cry aloud, be disquieted, loud, mourn, be moved, make a noise, rage, roar, sound, be troubled, make in tumult, tumultuous, be in an uproar.', 'a primitive root (compare 1949);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0622}/H9038/[H622]', 'inflected', 'heb', 'אָסַף', '["ʼâçaph"]', '["[will be] gathering/ them"]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8431}/H9020/[H3176]', 'inflected', 'heb', 'תּוֹחֶלֶת', '["tôwcheleth"]', '["hope/ my"]', '["n-f"]', 'expectation hope.', 'from 3176;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5061}/H9021/[H5060]', 'inflected', 'heb', 'נֶגַע', '["negaʻ"]', '["plague/ your"]', '["n-m"]', 'a blow (figuratively, infliction); also (by implication) a spot (concretely, a leprous person or dress) plague, sore, stricken, stripe, stroke, wound.', 'from 5060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8409}/[H1624]', 'inflected', 'heb', 'תִּגְרָה', '["tigrâh"]', '["from/ [the] hostility of"]', '["n-f"]', 'strife, i.e. infliction blow.', 'from 1624;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8433B}/[H3198]', 'inflected', 'heb', 'תּוֹכֵחָה', '["tôwkêchâh"]', '["with/ rebukes","with/ rebukes of"]', '["n-f"]', 'chastisement; figuratively (by words) correction, refutation, proof (even in defence) argument, × chastened, correction, reasoning, rebuke, reproof, × be (often) reproved.', 'and תּוֹכַחַת; from 3198;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4529}/[H4529]', 'inflected', 'heb', 'מָסָה', '["mâçâh"]', '["and/ you have melted"]', '["v"]', 'to dissolve make to consume away, (make to) melt, water.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2530A}/H9023/[H2530]', 'inflected', 'heb', 'חָמַד', '["châmad"]', '["desired [thing]/ his"]', '["v"]', 'to delight in beauty, greatly beloved, covet, delectable thing, (× great) delight, desire, goodly, lust, (be) pleasant (thing), precious (thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1832}/H9020/[H1831]', 'inflected', 'heb', 'דִּמְעָה', '["dimʻâh"]', '["tear[s]/ my"]', '["n-f"]', 'weeping tears.', 'feminine of 1831;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7775}/H9020/[H7773]', 'inflected', 'heb', 'שַׁוְעָה', '["shavʻâh"]', '["cry for help/ my"]', '["n-f"]', 'a hallooing crying.', 'feminine of 7773;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5927H}/H9030/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["and/ he brought up/ me"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7588}/[H7582]', 'lemma', 'heb', 'שָׁאוֹן', '["shâʼôwn"]', '["[is] a noise","[the] uproar of","an uproar","an uproar of","roaring","uproar"]', '["n-m"]', 'uproar (as of rushing); by implication, destruction × horrible, noise, pomp, rushing, tumult (× -uous).', 'from 7582;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H2916>', 'inflected', 'heb', 'מטיט', '["Mi./tit","mi./Tit"]', '["from/ [the] mud","from/ [the] mud of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3121}/[H3196]', 'inflected', 'heb', 'יָוֵן', '["yâvên"]', '["the/ mire"]', '["n-m"]', 'properly, dregs (as effervescing); hence, mud mire, miry.', 'from the same as 3196;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7295}/[H7292]', 'lemma', 'heb', 'רָהָב', '["râhâb"]', '["proud people"]', '["a"]', 'insolent proud.', 'from 7292;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7750}/[H7750]', 'inflected', 'heb', 'שׂוּט', '["sûwṭ"]', '["and/ [those who] fall away of"]', '["v"]', 'to detrude, i.e. (intransitively and figuratively) become derelict (wrongly practise; namely, idolatry) turn aside to.', 'or (by permutation) סוּט; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4284}/H9021/[H2803]', 'inflected', 'heb', 'מַחֲשָׁבָה', '["machăshâbâh"]', '["and/ plans/ your"]', '["n-f"]', 'a contrivance, i.e. (concretely) a texture, machine, or (abstractly) intention, plan (whether bad, a plot; or good, advice) cunning (work), curious work, device(-sed), imagination, invented, means, purpose, thought.', 'or מַחֲשֶׁבֶת; from 2803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5608A}/[H5608]', 'inflected', 'heb', 'סָפַר', '["çâphar"]', '["for/ recounting"]', '["v n-m"]', 'properly, to score with a mark as a tally or record, i.e. (by implication) to inscribe, and also to enumerate; intensively, to recount, i.e. celebrate commune, (ac-) count; declare, number, penknife, reckon, scribe, shew forth, speak, talk, tell (out), writer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2401}/[H2399]', 'inflected', 'heb', 'חֲטָאָה', '["chăṭâʼâh"]', '["and/ sin offering"]', '["n-f"]', 'an offence, or a sacrifice for it sin (offering).', 'feminine of 2399;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4039}/[H1556]', 'inflected', 'heb', 'מְגִלָּה', '["mᵉgillâh"]', '["in the/ scroll","in/ [the] scroll of"]', '["n-f"]', 'a roll roll, volume.', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7522}/H9021/[H7521]', 'inflected', 'heb', 'רָצוֹן', '["râtsôwn"]', '["will/ your"]', '["n-m"]', 'delight (especially as shown) (be) acceptable(-ance, -ed), delight, desire, favour, (good) pleasure, (own, self, voluntary) will, as...(what) would.', 'or רָצֹן; from 7521;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8668G}/H9021/[H7768]', 'inflected', 'heb', 'תְּשׁוּעָה', '["tᵉshûwʻâh"]', '["and/ salvation/ your"]', '["n-f"]', 'rescue (literal or figurative, persons, national or spiritual) deliverance, help, safety, salvation, victory.', 'or תְּשֻׁעָה; from 7768 in the sense of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0571G}/H9021/[H539]', 'inflected', 'heb', 'אֶמֶת', '["ʼemeth"]', '["and/ faithfulness/ your"]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0661}/[H661]', 'lemma', 'heb', 'אָפַף', '["ʼâphaph"]', '["they have surrounded"]', '["v"]', 'to surround compass.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5381}/H9030/[H5381]', 'inflected', 'heb', 'נָשַׂג', '["nâsag"]', '["they have overtaken/ me"]', '["v"]', 'to reach (literally or figuratively) ability, be able, attain (unto), (be able to, can) get, lay at, put, reach, remove, wax rich, × surely, (over-) take (hold of, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5337}/H9030/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["to/ deliver/ me"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5595}/H9034/[H5595]', 'inflected', 'heb', 'סָפָה', '["çâphâh"]', '["to/ snatch away/ it"]', '["v"]', 'properly, to scrape (literally, to shave; but usually figuratively) together (i.e. to accumulate or increase) or away (i.e. to scatter, remove, or ruin; intransitively, to perish) add, augment, consume, destroy, heap, join, perish, put.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1322}/H9028/[H954]', 'inflected', 'heb', 'בֹּשֶׁת', '["bôsheth"]', '["shame/ their"]', '["n-f"]', 'shame (the feeling and the condition, as well as its cause); by implication (specifically) an idol ashamed, confusion, greatly, (put to) shame(-ful thing).', 'from 954;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1245}/H9031/[H1245]', 'inflected', 'heb', 'בָּקַשׁ', '["bâqash"]', '["[those who] seek/ you"]', '["v"]', 'to search out (by any method, specifically in worship or prayer); by implication, to strive after ask, beg, beseech, desire, enquire, get, make inquisition, procure, (make) request, require, seek (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8668G}/H9021/[H7768]', 'inflected', 'heb', 'תְּשׁוּעָה', '["tᵉshûwʻâh"]', '["<of> salvation/ your","salvation/ your"]', '["n-f"]', 'rescue (literal or figurative, persons, national or spiritual) deliverance, help, safety, salvation, victory.', 'or תְּשֻׁעָה; from 7768 in the sense of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4422}/H9033/[H4422]', 'inflected', 'heb', 'מָלַט', '["mâlaṭ"]', '["he will deliver/ him"]', '["v"]', 'properly, to be smooth, i.e. (by implication) to escape (as if by slipperiness); causatively, to release or rescue; specifically, to bring forth young, emit sparks deliver (self), escape, lay, leap out, let alone, let go, preserve, save, × speedily, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8104H}/H9033/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["he will keep/ him"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2421}/H9033/[H2331]', 'inflected', 'heb', 'חָיָה', '["châyâh"]', '["and/ he will preserve alive/ him"]', '["v"]', 'to live, whether literally or figuratively; causatively, to revive keep (leave, make) alive, × certainly, give (promise) life, (let, suffer to) live, nourish up, preserve (alive), quicken, recover, repair, restore (to life), revive, (× God) save (alive, life, lives), × surely, be whole.', 'a primitive root (compare 2331, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0833}/[H833]', 'inflected', 'heb', 'אָשַׁר', '["ʼâshar"]', '["and/ he will be called blessed","and/ they will call blessed"]', '["v"]', 'to be straight (used in the widest sense, especially to be level, right, happy); figuratively, to go forward, be honest, prosper (call, be) bless(-ed, happy), go, guide, lead, relieve.', 'or אָשֵׁר; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5582}/H9033/[H5582]', 'inflected', 'heb', 'סָעַד', '["çâʻad"]', '["he will sustain/ him"]', '["v"]', 'to support (mostly figurative) comfort, establish, hold up, refresh self, strengthen, be upholden.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1741}/[H1739]', 'lemma', 'heb', 'דְּוַי', '["dᵉvay"]', '["illness"]', '["n-m"]', 'sickness; figuratively, loathing languishing, sorrowful.', 'from 1739;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7495}/H9012/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["heal/ !","repair/ !"]', '["v"]', 'properly, to mend (by stitching), i.e. (figuratively) to cure cure, (cause to) heal, physician, repair, × thoroughly, make whole. See 7503.', 'or רָפָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H2351>', 'inflected', 'heb', 'לחוץ', '["la./Chutz"]', '["[was] to the/ outside","to the/ outside"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7965J}/H9020/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["peace/ my"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6965H}/H9030/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["and/ raise up/ me"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5324}/H9030/[H5324]', 'inflected', 'heb', 'נָצַב', '["nâtsab"]', '["and/ he has set up/ me","and/ you have set/ me"]', '["v"]', 'to station, in various applications (literally or figuratively) appointed, deputy, erect, establish, × Huzzah (by mistake for a proper name), lay, officer, pillar, present, rear up, set (over, up), settle, sharpen, establish, (make to) stand(-ing, still, up, upright), best state.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H5769G}/[H5956]', 'inflected', 'heb', 'עוֹלָם', '["ʻôwlâm"]', '["from/ <the>/ antiquity"]', '["n-m"]', 'properly, concealed, i.e. the vanishing point; generally, time out of mind (past or future), i.e. (practically) eternity; frequentatively, adverbial (especially with prepositional prefix) always alway(-s), ancient (time), any more, continuance, eternal, (for, (n-)) ever(-lasting, -more, of old), lasting, long (time), (of) old (time), perpetual, at any time, (beginning of the) world ( without end). Compare 5331, 5703.', 'or עֹלָם; from 5956;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0543}/[H539]', 'inflected', 'heb', 'אָמֵן', '["ʼâmên"]', '["and/ amen"]', '["adv"]', 'sure; abstract, faithfulness; adverb, truly Amen, so be it, truth.', 'from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0354}/[H352]', 'inflected', 'heb', 'אַיָּל', '["ʼayâl"]', '["like <the>/ deer","like/ a deer","like/ deer"]', '["n-m"]', 'a stag or male deer hart.', 'an intensive form of 352 (in the sense of ram);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6165}/[H6165]', 'lemma', 'heb', 'עָרַג', '["ʻârag"]', '["[which] it pants","it pants"]', '["v"]', 'to long for cry, pant.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8210G}/[H8210]', 'inflected', 'heb', 'שָׁפַךְ', '["shâphak"]', '["and/ I will pour out"]', '["v"]', 'to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5519}/[H5526]', 'inflected', 'heb', 'סָךְ', '["çâk"]', '["with the/ crowd"]', '["n-m"]', 'properly, a thicket of men, i.e. a crowd multitude.', 'from 5526;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1718}/H9038/[H1718]', 'inflected', 'heb', 'דָּדָה', '["dâdâh"]', '["I led/ them"]', '["v"]', 'to walk gently go (softly, with).', 'a doubtful root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1993}/[H1949]', 'inflected', 'heb', 'הָמָה', '["hâmâh"]', '["and/ they roar","and/ they roared","and/ they will roar","and/ were you in turmoil?"]', '["v"]', 'to make a loud sound (like English ''hum''); by implication, to be in great commotion or tumult, to rage, war, moan, clamor clamorous, concourse, cry aloud, be disquieted, loud, mourn, be moved, make a noise, rage, roar, sound, be troubled, make in tumult, tumultuous, be in an uproar.', 'a primitive root (compare 1949);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2142}/H9031/[H2145]', 'inflected', 'heb', 'זָכַר', '["zâkar"]', '["I have remembered/ you","I will remember/ you","they remember/ you"]', '["v"]', 'properly, to mark (so as to be recognized), i.e. to remember; by implication, to mention; to be male × burn (incense), × earnestly, be male, (make) mention (of), be mindful, recount, record(-er), remember, make to be remembered, bring (call, come, keep, put) to (in) remembrance, × still, think on, × well.', 'a primitive root; also as denominative from 2145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2769}/[H2768]', 'inflected', 'heb', 'חֶרְמוֹנִים', '["Chermôwnîym"]', '["and/ Hermon<s>"]', '["n-pr-m"]', 'Hermons, i.e. its peaks the Hermonites.', 'plural of 2768;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4706}/[H4705]', 'lemma', 'heb', 'מִצְעָר', '["Mitsʻâr"]', '["Mizar"]', '["n-pr-loc"]', 'Mitsar, a peak of Lebanon Mizar.', 'the same as 4705;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6794>/H9021', 'opaque', 'heb', 'צִנּוּר', '["tsinnûwr"]', '["waterfalls/ your"]', '["n-m"]', 'a culvert gutter, water-spout.', 'from an unused root perhaps meaning to be hollow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4867}/H9021/[H7665]', 'inflected', 'heb', 'מִשְׁבָּר', '["mishbâr"]', '["breakers/ your"]', '["n-m"]', 'a breaker (of the sea) billow, wave.', 'from 7665;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1530H}/H9021/[H1556]', 'inflected', 'heb', 'גַּל', '["gal"]', '["and/ waves/ your"]', '["n-m"]', 'something rolled, i.e. a heap of stone or dung (plural ruins), by analogy, a spring of water (plural waves) billow, heap, spring, wave.', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7524}/[H7523]', 'inflected', 'heb', 'רֶצַח', '["retsach"]', '["for/ shattering","with/ a shattering"]', '["n-m"]', 'a crushing; specifically, a murder-cry slaughter, sword.', 'from 7523;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2778A}/H9030/[H2779]', 'inflected', 'heb', 'חָרַף', '["châraph"]', '["[one who] taunts/ me","[the] [one who] taunts/ me","he taunts/ me","they have taunted/ me","they taunted/ me"]', '["v"]', 'to pull off, i.e. (by implication) to expose (as by stripping); specifically, to betroth (as if a surrender); figuratively, to carp at, i.e. defame; to spend the winter betroth, blaspheme, defy, jeopard, rail, reproach, upbraid.', 'a primitive root; also denominative (from 2779)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440L}/H9020/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["face/ my"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7378}/H9012/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["and/ conduct/ !"]', '["v"]', 'properly, to toss, i.e. grapple; mostly figuratively, to wrangle, i.e. hold a controversy; (by implication) to defend adversary, chide, complain, contend, debate, × ever, × lay wait, plead, rebuke, strive, × thoroughly.', 'or רוּב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2186A}/H9030/[H2186]', 'inflected', 'heb', 'זָנַח', '["zânach"]', '["have you rejected/ me"]', '["v"]', 'reject, forsake, fail cast away (off), remove far away (off).', 'a primitive root meaning to push aside, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0216}/H9021/[H215]', 'inflected', 'heb', 'אוֹר', '["ʼôwr"]', '["light/ your"]', '["n-f"]', 'illumination or (concrete) luminary (in every sense, including lightning, happiness, etc.) bright, clear, day, light (-ning), morning, sun.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0571H}/H9021/[H539]', 'inflected', 'heb', 'אֶמֶת', '["ʼemeth"]', '["and/ truth/ your"]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1524A}/H9020/[H1523]', 'inflected', 'heb', 'גִּיל', '["gîyl"]', '["rejoicing/ my"]', '["n-m"]', 'a revolution (of time, i.e. an age); also joy × exceedingly, gladness, × greatly, joy, rejoice(-ing), sort.', 'from 1523;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3034}/H9031/[H3027]', 'inflected', 'heb', 'יָדָה', '["yâdâh"]', '["and/ I will give thanks to/ you","and/ people praise/ you"]', '["v"]', 'physically, to throw (a stone, an arrow) at or away; especially to revere or worship (with extended hands); intensively, to bemoan (by wringing the hands) cast (out), (make) confess(-ion), praise, shoot, (give) thank(-ful, -s, -sgiving).', 'a primitive root; used only as denominative from 3027; literally, to use (i.e. hold out) the hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5193}/H9038/[H5193]', 'inflected', 'heb', 'נָטַע', '["nâṭaʻ"]', '["and/ I will plant/ them","and/ you planted/ them"]', '["v"]', 'properly, to strike in, i.e. fix; specifically, to plant (literally or figuratively) fastened, plant(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2220}/H9028/[H2232]', 'inflected', 'heb', 'זְרוֹעַ', '["zᵉrôwaʻ"]', '["and/ arm/ their"]', '["n-f"]', 'the arm (as stretched out), or (of animals) the foreleg; figuratively, force arm, help, mighty, power, shoulder, strength.', 'or (shortened) זְרֹעַ; and (feminine) זְרוֹעָה; or זְרֹעָה; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7521}/H9038/[H7521]', 'inflected', 'heb', 'רָצָה', '["râtsâh"]', '["I will accept/ them","[will be] accepting/ them","he has accepted/ them","he is pleased with/ them","you took pleasure in/ them"]', '["v"]', 'to be pleased with; specifically, to satisfy a debt (be) accept(-able), accomplish, set affection, approve, consent with, delight (self), enjoy, (be, have a) favour(-able), like, observe, pardon, (be, have, take) please(-ure), reconcile self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0947}/[H947]', 'lemma', 'heb', 'בּוּס', '["bûwç"]', '["he will tread down","it treads down","kicking about","they have trodden down","treading down","trodden down","we tread down"]', '["v"]', 'to trample (literally or figuratively) loath, tread (down, under (foot)), be polluted.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965B}/H9035/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["[those who] rise up against/ us"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7198}/H9020/[H7185]', 'inflected', 'heb', 'קֶשֶׁת', '["qesheth"]', '["in/ bow/ my"]', '["n-f"]', 'a bow, for shooting (hence, figuratively, strength) or the iris × arch(-er), arrow, bow(-man, -shot).', 'from 7185 in the original sense (of 6983) of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6862C}/H9025/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["from/ foes/ our"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8130}/H9035/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["and/ [those who] hate/ us"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8034}/H9021/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["and/ name/ your"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3637}/H9035/[H3637]', 'inflected', 'heb', 'כָּלַם', '["kâlam"]', '["and/ you have humiliated/ us"]', '["v"]', 'properly, to wound; but only figuratively, to taunt or insult be (make) ashamed, blush, be confounded, be put to confusion, hurt, reproach, (do, put to) shame.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6635A}/H9025/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["with/ armies/ our"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725G}/H9035/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["you have made turn back/ us"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414I}/H9035/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["you have made/ us"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2219}/H9035/[H2114]', 'inflected', 'heb', 'זָרָה', '["zârâh"]', '["you have scattered/ us"]', '["v"]', 'to toss about; by implication, to diffuse, winnow cast away, compass, disperse, fan, scatter (away), spread, strew, winnow.', 'a primitive root (compare 2114);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1952}/[H1951]', 'lemma', 'heb', 'הוֹן', '["hôwn"]', '["[the] wealth of","enough","wealth"]', '["n-m"]', 'wealth; by implication, enough enough, for nought, riches, substance, wealth.', 'from the same as 1951 in the sense of 202;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H4242>/H9028', 'inflected', 'heb', 'במחיריהם', '["bi/m.chi.rei./Hem"]', '["by/ price<s>/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7760A}/H9035/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["you have made/ us","you make/ us"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7934}/H9025/[H7931]', 'inflected', 'heb', 'שָׁכֵן', '["shâkên"]', '["to/ neighbors/ our"]', '["a"]', 'a resident; by extension, a fellow-citizen inhabitant, neighbour, nigh.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7047}/[H7046]', 'inflected', 'heb', 'קֶלֶס', '["qeleç"]', '["and/ derision"]', '["n-m"]', 'a laughing-stock derision.', 'from 7046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5439G}/H9035/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["to/ [those] around/ us"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4493}/[H5110]', 'lemma', 'heb', 'מָנוֹד', '["mânôwd"]', '["a shaking of"]', '["n-m"]', 'a nodding or toss (of the head in derision) shaking.', 'from 5110');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1322}/[H954]', 'inflected', 'heb', 'בֹּשֶׁת', '["bôsheth"]', '["and/ [the] shame of"]', '["n-f"]', 'shame (the feeling and the condition, as well as its cause); by implication (specifically) an idol ashamed, confusion, greatly, (put to) shame(-ful thing).', 'from 954;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3680}/H9030/[H3680]', 'inflected', 'heb', 'כָּסָה', '["kâçâh"]', '["it has covered/ me"]', '["v"]', 'properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935G}/H9035/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["it has come to/ us","it will come to/ us"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7911}/H9031/[H7911]', 'inflected', 'heb', 'שָׁכַח', '["shâkach"]', '["we had forgotten/ you"]', '["v"]', 'to mislay, i.e. to be oblivious of, from want of memory or attention × at all, (cause to) forget.', 'or שָׁכֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1285}/H9021/[H1262]', 'inflected', 'heb', 'בְּרִית', '["bᵉrîyth"]', '["with/ covenant/ your"]', '["n-f"]', 'a compact (because made by passing between pieces of flesh) confederacy, (con-) feder(-ate), covenant, league.', 'from 1262 (in the sense of cutting [like 1254]);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0838A}/H9025/[H833]', 'inflected', 'heb', 'אָשֻׁר', '["ʼâshur"]', '["steps/ our"]', '["n-f"]', 'a step going, step.', 'or אַשֻּׁר; from 833 in the sense of going;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1794}/H9035/[H1790]', 'inflected', 'heb', 'דָּכָה', '["dâkâh"]', '["you have crushed/ us"]', '["v"]', 'to collapse (phys. or mentally) break (sore), contrite, crouch.', 'a primitive root (compare 1790, 1792);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8577A}/[H8565]', 'lemma', 'heb', 'תַּנִּין', '["tannîyn"]', '["jackals"]', '["n-m"]', 'a marine or land monster, i.e. sea-serpent or jackal dragon, sea-monster, serpent, whale.', 'or תַּנִּים; (Ezekiel 29:3), intensive from the same as 8565;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6757}/[H6738]', 'inflected', 'heb', 'צַלְמָוֶת', '["tsalmâveth"]', '["with/ deep darkness"]', '["n-m"]', 'shade of death, i.e. the grave (figuratively, calamity) shadow of death.', 'from 6738 and 4194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3709G}/H9025/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["hands/ our"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2878}/[H2874]', 'lemma', 'heb', 'טִבְחָה', '["ṭibchâh"]', '["slaughter"]', '["n-f"]', 'flesh, slaughter.', 'feminine of 2874 and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6974}/H9012/[H3364]', 'inflected', 'heb', 'קוּץ', '["qûwts"]', '["awake/ !","wake up/ !"]', '["v"]', 'to awake (literally or figuratively) arise, (be) (a-) wake, watch.', 'a primitive root (identical with through the idea of abruptness in starting up from sleep (compare 3364));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3906}/H9025/[H3905]', 'inflected', 'heb', 'לַחַץ', '["lachats"]', '["and/ oppression/ our"]', '["n-m"]', 'distress affliction, oppression.', 'from 3905;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7743}/[H7743]', 'lemma', 'heb', 'שׁוּחַ', '["shûwach"]', '["it has sunk down","she sank down"]', '["v"]', 'to sink, literally or figuratively bow down, incline, humble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0990G>/H9025', 'opaque', 'heb', 'בֶּטֶן', '["beṭen"]', '["belly/ our"]', '["n-f"]', 'the belly, especially the womb; also the bosom or body of anything belly, body, as they be born, within, womb.', 'from an unused root probably meaning to be hollow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5833}/[H5828]', 'lemma', 'heb', 'עֶזְרָה', '["ʻezrâh"]', '["<to> a help","[had been] <to> a help","[the] help of","a help","help"]', '["n-f"]', 'aid help(-ed, -er).', 'or עֶזְרָת; (Psalm 60:11 (13); Psalm 108:12 (13)), feminine of 5828;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6299}/H9035/[H6299]', 'inflected', 'heb', 'פָּדָה', '["pâdâh"]', '["and/ redeem/ us"]', '["v"]', 'to sever, i.e. ransom; generally to release, preserve × at all, deliver, × by any means, ransom, (that are to be, let be) redeem(-ed), rescue, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3039B}/[H1730]', 'lemma', 'heb', 'יְדִיד', '["yᵉdîyd"]', '["love<s>"]', '["a n-f"]', 'loved amiable, (well-) beloved, loves.', 'from the same as 1730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7370}/[H7370]', 'lemma', 'heb', 'רָחַשׁ', '["râchash"]', '["it is aroused"]', '["v"]', 'to gush indite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4639K}/H9020/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["work<s>/ my"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5842}/[H5860]', 'lemma', 'heb', 'עֵט', '["ʻêṭ"]', '["[is] a stylus of","a stylus of"]', '["n-m"]', 'a stylus or marking stick pen.', 'from 5860 (contracted) in the sense of swooping, i.e. side-long stroke;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3302}/[H3302]', 'lemma', 'heb', 'יָפָה', '["yâphâh"]', '["they are beautiful","you are beautiful","you are handsome","you beautify yourself"]', '["v"]', 'properly, to be bright, i.e. (by implication) beautiful be beautiful, be (make self) fair(-r), deck.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1926}/H9021/[H1921]', 'inflected', 'heb', 'הָדָר', '["hâdâr"]', '["and/ majesty/ your"]', '["n-m"]', 'magnificence, i.e. ornament or splendor beauty, comeliness, excellency, glorious, glory, goodly, honour, majesty.', 'from 1921;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6037}/[H6035]', 'inflected', 'heb', 'עַנְוָה', '["ʻanvâh"]', '["and/ humility"]', '["n-f"]', 'mildness (royal); also (concretely) oppressed gentleness, meekness.', 'feminine of 6035;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8342}/[H7797]', 'lemma', 'heb', 'שָׂשׂוֹן', '["sâsôwn"]', '["[are] [the] joy of","[the] joy of","joy"]', '["n-m"]', 'cheerfulness; specifically, welcome gladness, joy, mirth, rejoicing.', 'or שָׂשֹׂן; from 7797;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2270}/H9021/[H2266]', 'inflected', 'heb', 'חָבֵר', '["châbêr"]', '["more than/ companions/ your"]', '["n-m"]', 'an associate companion, fellow, knit together.', 'from 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0174>', 'inflected', 'heb', 'ואהלות', '["va./''a.ha.Lot"]', '["and/ aloes"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7102}/[H7106]', 'lemma', 'heb', 'קְצִיעָה', '["qᵉtsîyʻâh"]', '["cassia<s>"]', '["n-f"]', 'cassia (as peeled; plural the bark) cassia.', 'from 7106;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4482>', 'opaque', 'heb', 'מֵן', '["mên"]', '["stringed instrument"]', '["n-m"]', 'a part; hence, a musical chord (as parted into strings) in [the same] (Psalm 68:23), stringed instrument (Psalm 150:4), whereby (Psalm 45:8 [defective plural]).', 'from an unused root meaning to apportion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8055}/H9031/[H8055]', 'inflected', 'heb', 'שָׂמַח', '["sâmach"]', '["they have made glad/ you"]', '["v"]', 'probably to brighten up, i.e. (figuratively) be (causatively, make) blithe or gleesome cheer up, be (make) glad, (have, make) joy(-ful), be (make) merry, (cause to, make to) rejoice, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3368}/H9021/[H3365]', 'inflected', 'heb', 'יָקָר', '["yâqâr"]', '["[are] among/ noble [women]/ your"]', '["a"]', 'valuable (objectively or subjectively) brightness, clear, costly, excellent, fat, honourable women, precious, reputation.', 'from 3365;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7694}/[H7693]', 'lemma', 'heb', 'שֵׁגָל', '["shêgâl"]', '["a queen-consort"]', '["n-f"]', 'a queen (from cohabitation) queen.', 'from 7693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3225G}/H9021/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["to/ right [hand]/ your"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0241G}/H9022/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["ear/ your","ears/ your"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7911}/[H7911]', 'inflected', 'heb', 'שָׁכַח', '["shâkach"]', '["and/ forget","and/ he may forget","and/ they may be forgotten"]', '["v"]', 'to mislay, i.e. to be oblivious of, from want of memory or attention × at all, (cause to) forget.', 'or שָׁכֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0183}/[H183]', 'inflected', 'heb', 'אָוָה', '["ʼâvâh"]', '["so/ may he desire"]', '["v"]', 'to wish for covet, (greatly) desire, be desirous, long, lust (after).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3308}/H9022/[H3302]', 'inflected', 'heb', 'יֳפִי', '["yŏphîy"]', '["beauty/ your"]', '["n-m"]', 'beauty beauty.', 'from 3302;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0113>/H9022', 'opaque', 'heb', 'אָדוֹן', '["ʼâdôwn"]', '["[is] lord<s>/ your","lord<s>/ your"]', '["n-m"]', 'sovereign, i.e. controller (human or divine) lord, master, owner. Compare also names beginning with ''Adoni-''.', 'or (shortened) אָדֹן; from an unused root (meaning to rule);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440L}/H9022/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["face/ your"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3520A}/[H3513]', 'lemma', 'heb', 'כְּבוּדָּה', '["kᵉbûwddâh"]', '["glorious"]', '["n-f"]', 'weightiness, i.e. magnificence, wealth carriage, all glorious, stately.', 'irregular feminine passive participle of 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4865}/[H7660]', 'inflected', 'heb', 'מִשְׁבְּצָה', '["mishbᵉtsâh"]', '["[is] from/ settings of"]', '["n-f"]', 'a brocade; by analogy, a (reticulated) setting of a gem ouch, wrought.', 'from 7660;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3830}/H9024/[H3847]', 'inflected', 'heb', 'לְבוּשׁ', '["lᵉbûwsh"]', '["clothing/ her"]', '["n-m"]', 'a garment (literally or figuratively); by implication (euphemistically) a wife apparel, clothed with, clothing, garment, raiment, vestment, vesture.', 'or לְבֻשׁ; from 3847;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7553}/[H7551]', 'inflected', 'heb', 'רִקְמָה', '["riqmâh"]', '["to/ embroidered robes"]', '["n-f"]', 'variegation of color; specifically, embroidery broidered (work), divers colours, (raiment of) needlework (on both sides).', 'from 7551;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7464}/H9024/[H7453]', 'inflected', 'heb', 'רֵעָה', '["rêʻâh"]', '["[female] companions/ her"]', '["n-f"]', 'a female associate companion, fellow.', 'feminine of 7453;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1524A}/[H1523]', 'inflected', 'heb', 'גִּיל', '["gîyl"]', '["and/ rejoicing"]', '["n-m"]', 'a revolution (of time, i.e. an age); also joy × exceedingly, gladness, × greatly, joy, rejoice(-ing), sort.', 'from 1523;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4171}/[H4171]', 'inflected', 'heb', 'מוּר', '["mûwr"]', '["when/ changes"]', '["v"]', 'to alter; by implication, to barter, to dispose of × at all, (ex-) change, remove.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4131}/[H4131]', 'inflected', 'heb', 'מוֹט', '["môwṭ"]', '["and/ when/ shake"]', '["v"]', 'to waver; by implication, to slip, shake, fall be carried, cast, be out of course, be fallen in decay, × exceedingly, fall(-ing down), be (re-) moved, be ready, shake, slide, slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2560A}/[H2564]', 'lemma', 'heb', 'חָמַר', '["châmar"]', '["it is foaming","they are in turmoil","they will foam"]', '["v"]', 'properly, to boil up; hence, to ferment (with scum); to glow (with redness); to smear with pitch daub, befoul, be red, trouble.', 'a primitive root; also as denominative (from 2564)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1346}/H9023/[H1342]', 'inflected', 'heb', 'גַּאֲוָה', '["gaʼăvâh"]', '["at/ swelling/ its"]', '["n-f"]', 'arrogance or majesty; by implication, (concretely) ornament excellency, haughtiness, highness, pride, proudly, swelling.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6388}/H9023/[H6385]', 'inflected', 'heb', 'פֶּלֶג', '["peleg"]', '["streams/ its"]', '["n-m"]', 'a rill (i.e. small channel of water, as in irrigation) river, stream.', 'from 6385;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5826}/H9034/[H5826]', 'inflected', 'heb', 'עָזַר', '["ʻâzar"]', '["he will help/ it","helpers/ its"]', '["v"]', 'to surround, i.e. protect or aid help, succour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4659B}/[H6466]', 'lemma', 'heb', 'מִפְעָל', '["miphʻâl"]', '["[the] works of"]', '["n-m"]', 'a performance work.', 'or (feminine) מִפְעָלָה; from 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8047G}/[H8074]', 'lemma', 'heb', 'שַׁמָּה', '["shammâh"]', '["desolation","desolations"]', '["n-f"]', 'ruin; by implication, consternation astonishment, desolate(-ion), waste, wonderful thing.', 'from 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1696H}/[H1696]', 'lemma', 'heb', 'דָבַר', '["dâbar"]', '["he subdues"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478G}/H9035/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["under/ us"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7272}/H9025/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["feet/ our","foot/ our"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5131}/[H5130]', 'lemma', 'heb', 'נוֹף', '["nôwph"]', '["height"]', '["n-m"]', 'elevation situation. Compare 5297.', 'from 5130;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6828H}/[H6845]', 'lemma', 'heb', 'צָפוֹן', '["tsâphôwn"]', '["Zaphon"]', '["n-f"]', 'properly, hidden, i.e. dark; used only of the north as a quarter (gloomy and unknown) north(-ern, side, -ward, wind).', 'or צָפֹן; from 6845;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0759G>/H9024', 'inflected', 'heb', 'בארמנותיה', '["be./''ar.me.no.Tei./ha"]', '["[is] in/ fortresses/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4869A}/[H7682]', 'inflected', 'heb', 'מִשְׂגָּב', '["misgâb"]', '["<into>/ a refuge","to/ a refuge"]', '["n-m n-pr-loc"]', 'properly, a cliff (or other lofty or inaccessible place); abstractly, altitude; figuratively, a refuge; Misgab, a place in Moab defence, high fort (tower), refuge, Misgab.', 'from 7682;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8539}/[H8539]', 'lemma', 'heb', 'תָּמַהּ', '["tâmahh"]', '["be astonished","they were astonished","they will be astounded","they will look in astonishment"]', '["v"]', 'to be in consternation be amazed, be astonished, marvel(-lously), wonder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7461B}/[H7460]', 'lemma', 'heb', 'רַעַד', '["raʻad"]', '["trembling"]', '["n-m n-f"]', 'a shudder trembling.', 'or (feminine) רְעָדָהxlit rᵉâdâh corrected to rᵉʻâdâh; from 7460;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3205}/[H3205]', 'inflected', 'heb', 'יָלַד', '["yâlad"]', '["like <the>/ [woman] giving birth"]', '["v"]', 'to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1964G}/H9021/[H3201]', 'inflected', 'heb', 'הֵיכָל', '["hêykâl"]', '["temple/ your"]', '["n-m"]', 'a large public building, such as a palace or temple palace, temple.', 'probably from 3201 (in the sense of capacity);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8034}/H9021/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["like/ name/ your"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7099}/[H7096]', 'lemma', 'heb', 'קֶצֶו', '["qetsev"]', '["[the] boundaries of","[the] ends of"]', '["n-m"]', 'a limit end, edge, uttermost participle', 'and (feminine) קִצְוָה; from 7096; (used like 7097, but with less variety)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5362B}/H9034/[H5362]', 'inflected', 'heb', 'נָקַף', '["nâqaph"]', '["and/ go round/ it"]', '["v"]', 'to strike with more or less violence (beat, fell, corrode); by implication (of attack) to knock together, i.e. surround or circulate compass (about, -ing), cut down, destroy, go round (about), inclose, round.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4026M}/H9024/[H1431]', 'inflected', 'heb', 'מִגְדָּל', '["migdâl"]', '["towers/ its"]', '["n-m"]', 'a tower (from its size or height); by analogy, a rostrum; figuratively, a (pyramidal) bed of flowers castle, flower, tower. Compare the names following.', 'also (in plural) feminine מִגְדָּלָה; from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2430}/H9024/[H2428]', 'inflected', 'heb', 'חֵילָה', '["chêylâh"]', '["to/ rampart/ its"]', '["n-f"]', 'an intrenchment bulwark.', 'feminine of 2428;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6448}/[H6448]', 'lemma', 'heb', 'פָּסַג', '["pâçag"]', '["walk through"]', '["v"]', 'to cut up, i.e. (figuratively) contemplate consider.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5090A}/H9035/[H5090]', 'inflected', 'heb', 'נָהַג', '["nâhag"]', '["he will guide/ us"]', '["v"]', 'to drive forth (a person, an animal or chariot), i.e. lead, carry away; reflexively, to proceed (i.e. impel or guide oneself); also (from the panting induced by effort), to sigh acquaint, bring (away), carry away, drive (away), lead (away, forth), (be) guide, lead (away, forth).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1900}/[H1897]', 'inflected', 'heb', 'הָגוּת', '["hâgûwth"]', '["and/ [the] meditation of"]', '["n-f"]', 'musing meditation.', 'from 1897;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6119}/H9020/[H6117]', 'inflected', 'heb', 'עָקֵב', '["ʻâqêb"]', '["heels/ my"]', '["n-m"]', 'a heel (as protuberant); hence, a track; figuratively, the rear (of an army) heel, (horse-) hoof, last, lier in wait (by mistake for 6120), (foot-) step.', 'or (feminine) עִקְּבָה; from 6117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6239}/H9028/[H6238]', 'inflected', 'heb', 'עֹשֶׁר', '["ʻôsher"]', '["rich[es]/ their","wealth/ their"]', '["n-m"]', 'wealth × far (richer), riches.', 'from 6238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0251I}/[H251]', 'lemma', 'heb', 'אָח', '["ʼâch"]', '["a brother","brothers"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3724A}/H9023/[H3722]', 'inflected', 'heb', 'כֹּפֶר', '["kôpher"]', '["ransom/ his"]', '["n-m"]', 'properly, a cover, i.e. (literally) a village (as covered in); (specifically) bitumen (as used for coating), and the henna plant (as used for dyeing); figuratively, a redemption-price bribe, camphire, pitch, ransom, satisfaction, sum of money, village.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3365}/[H3365]', 'inflected', 'heb', 'יָקַר', '["yâqar"]', '["and/ may <it> be precious","so/ it may be costly"]', '["v"]', 'properly, apparently, to be heavy, i.e. (figuratively) valuable; causatively, to make rare (figuratively, to inhibit) be (make) precious, be prized, be set by, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7845G}/[H7743]', 'inflected', 'heb', 'שַׁחַת', '["shachath"]', '["the/ pit"]', '["n-f"]', 'a pit (especially as a trap); figuratively, destruction corruption, destruction, ditch, grave, pit.', 'from 7743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3684}/[H3688]', 'lemma', 'heb', 'כְּסִיל', '["kᵉçîyl"]', '["[is] a fool","a fool","fools"]', '["n-m"]', 'properly, fat, i.e. (figuratively) stupid or silly fool(-ish).', 'from 3688;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1198}/[H1197]', 'inflected', 'heb', 'בַּעַר', '["baʻar"]', '["and/ a stupid [person]"]', '["n-m"]', 'properly, foot (as consumed); i.e. (by exten.) of cattle brutishness; (concretely) stupid brutish (person), foolish.', 'from 1197;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4908}/H9028/[H7931]', 'inflected', 'heb', 'מִשְׁכָּן', '["mishkân"]', '["dwelling places/ their","dwellings/ their"]', '["n-m"]', 'a residence (including a shepherd''s hut, the lair of animals, figuratively, the grave; also the Temple); specifically, the Tabernacle (properly, its wooden walls) dwelleth, dwelling (place), habitation, tabernacle, tent.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3366}/[H3365]', 'inflected', 'heb', 'יְקָר', '["yᵉqâr"]', '["in/ honor","with/ honor"]', '["n-m"]', 'value, i.e. (concretely) wealth; abstractly, costliness, dignity honour, precious (things), price.', 'from 3365;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4911A}/[H4912]', 'lemma', 'heb', 'מָשַׁל', '["mâshal"]', '["he is like","you have become like"]', '["v"]', 'to liken, i.e. (transitively) to use figurative language (an allegory, adage, song or the like); intransitively, to resemble be(-come) like, compare, use (as a) proverb, speak (in proverbs), utter.', 'denominative from 4912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1820}/[H1820]', 'lemma', 'heb', 'דָּמָה', '["dâmâh"]', '["I am destroyed","[which] they are destroyed","[will] be destroyed","certainly <to be destroyed>","he will be destroyed","it was destroyed","it will be destroyed","it will be silent","it will cease","they cease","they have been destroyed","you will be destroyed"]', '["v"]', 'to be dumb or silent; hence, to fail or perish; trans. to destroy cease, be cut down (off), destroy, be brought to silence, be undone, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6310I}/H9028/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["in/ mouth/ their"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8371}/[H8371]', 'lemma', 'heb', 'שָׁתַת', '["shâthath"]', '["they have been appointed","they set"]', '["v"]', 'to place, i.e. array; reflex. to lie be laid, set. t', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7462B}/H9038/[H7462]', 'inflected', 'heb', 'רָעָה', '["râʻâh"]', '["he will pasture/ them","it will feed/ them","it will shepherd/ them"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6697H}/H9028/[H6696]', 'inflected', 'heb', 'צוּר', '["tsûwr"]', '["and/ form/ their"]', '["n-m"]', 'properly, a cliff (or sharp rock, as compressed); generally, a rock or boulder; figuratively, a refuge; also an edge (as precipitous) edge, × (mighty) God (one), rock, × sharp, stone, × strength, × strong. See also 1049.', 'or צֻר; from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1086}/[H1086]', 'inflected', 'heb', 'בָּלָה', '["bâlâh"]', '["[is] for/ [the] consuming of"]', '["v"]', 'to fail; by implication to wear out, decay (causatively, consume, spend) consume, enjoy long, become (make, wax) old, spend, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2073}/[H2082]', 'inflected', 'heb', 'זְבוּל', '["zᵉbûwl"]', '["from/ [the] lofty abode of","from/ lofty abode"]', '["n-m"]', 'a residence dwell in, dwelling, habitation.', 'or זְבֻל; from 2082;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3947H}/H9030/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["he will take/ me","you will take/ me"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3996}/H9023/[H935]', 'inflected', 'heb', 'מָבוֹא', '["mâbôwʼ"]', '["setting/ its"]', '["n-m"]', 'an entrance (the place or the act); specifically sunset or the west; also (adverb with preposition) towards by which came, as cometh, in coming, as men enter into, entering, entrance into, entry, where goeth, going down, westward. Compare 4126.', 'from 935; (with or without 8121)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4359}/[H3634]', 'lemma', 'heb', 'מִכְלָל', '["miklâl"]', '["perfection of"]', '["n-m"]', 'perfection (of beauty) perfection.', 'from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3308}/[H3302]', 'lemma', 'heb', 'יֳפִי', '["yŏphîy"]', '["[the] beauty of","beauty"]', '["n-m"]', 'beauty beauty.', 'from 3302;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5439G}/H9033/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["and/ around/ him"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8175B}/[H8175]', 'lemma', 'heb', 'שָׂעַר', '["sâʻar"]', '["it is tempestuous"]', '["v"]', 'to storm; by implication, to shiver, i.e. fear be (horribly) afraid, fear, hurl as a storm, be tempestuous, come like (take away as with) a whirlwind.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5920H}/[H5927]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["<from>/ above"]', '["n-m"]', 'properly, the top; specifically, the Highest (i.e. God); also (adverb) aloft, to Jehovah above, high, most High.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1777}/[H1777]', 'inflected', 'heb', 'דִּין', '["dîyn"]', '["to/ contend","to/ judge"]', '["v"]', 'to rule; by implication to judge (as umpire); also to strive (as at law) contend contend execute (judgment) judge minister judgment plead (the cause) at strife strive.', 'or (Genesis 6:3) דּוּן; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2623}/H9020/[H2616]', 'inflected', 'heb', 'חָסִיד', '["châçîyd"]', '["O faithful [people]/ my"]', '["a"]', 'properly, kind, i.e. (religiously) pious (a saint) godly (man), good, holy (one), merciful, saint, (un-) godly.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6664G}/H9023/[H6663]', 'inflected', 'heb', 'צֶדֶק', '["tsedeq"]', '["righteousness/ his"]', '["n-m"]', 'the right (natural, moral or legal); also (abstractly) equity or (figuratively) prosperity × even, (× that which is altogether) just(-ice), (un-)right(-eous) (cause, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1004B}/H9021/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["from/ household/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4356}/H9021/[H3607]', 'inflected', 'heb', 'מִכְלָאָה', '["miklâʼâh"]', '["from/ folds/ your"]', '["n-m"]', 'a pen (for flocks) (sheep-)fold. Compare 4357.', 'or מִכְלָה; from 3607;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2042>', 'inflected', 'heb', 'בהררי', '["be./ha.rei"]', '["[is] among/ [the] mountains of","on/ hills of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H2123A>', 'inflected', 'heb', 'וזיז', '["ve./Ziz"]', '["and/ moving creature[s] of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7456}/[H7456]', 'lemma', 'heb', 'רָעֵב', '["râʻêb"]', '["I will be hungry","he allows to hunger","he is hungry","he will be hungry","it will be hungry","they will be hungry","we will be hungry","you will be hungry"]', '["v"]', 'to hunger (suffer to) famish, (be, have, suffer, suffer to) hunger(-ry).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5945B}/[H5927]', 'inflected', 'heb', 'עֶלְיוֹן', '["ʻelyôwn"]', '["<to>/ [the] Most High","to/ [the] Most High"]', '["n-m a"]', 'an elevation, i.e. (adj.) lofty (compar.); as title, the Supreme (Most, on) high(-er, -est), upper(-most).', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7121G}/H9030/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["and/ call out to/ me"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2502A}/H9031/[H2502]', 'inflected', 'heb', 'חָלַץ', '["châlats"]', '["I will rescue/ you"]', '["v"]', 'to pull off; hence (intensively) to strip, (reflex.) to depart; by implication, to deliver, equip (for fight); present, strengthen arm (self), (go, ready) armed (× man, soldier), deliver, draw out, make fat, loose, (ready) prepared, put off, take away, withdraw self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3513G}/H9030/[H3513]', 'inflected', 'heb', 'כָּבַד', '["kâbad"]', '["and/ you will honor/ me"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7563}/[H7561]', 'inflected', 'heb', 'רָשָׁע', '["râshâʻ"]', '["and/ to the/ wicked","and/ to the/ wicked [people]","and/ to/ [the] wicked [people] of"]', '["a"]', 'morally wrong; concretely, an (actively) bad person condemned, guilty, ungodly, wicked (man), that did wrong.', 'from 7561;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1590}/[H1589]', 'lemma', 'heb', 'גַּנָּב', '["gannâb"]', '["a thief","thieves"]', '["n-m"]', 'a stealer thief.', 'from 1589;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3956G}/H9021/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["and/ tongue/ your"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0251G}/H9021/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["on/ brother/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1848>', 'opaque', 'heb', 'דׇּפִי', '["dophîy"]', '["a fault"]', '["n-m"]', 'a stumbling-block slanderest.', 'from an unused root (meaning to push over);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2790B}/[H2790]', 'inflected', 'heb', 'חָרַשׁ', '["chârash"]', '["and/ I kept silent"]', '["v"]', 'to scratch, i.e. (by implication) to engrave, plough; hence (from the use of tools) to fabricate (of any material); figuratively, to devise (in a bad sense); hence (from the idea of secrecy) to be silent, to let alone; hence (by implication) to be deaf (as an accompaniment of dumbness) × altogether, cease, conceal, be deaf, devise, ear, graven, imagine, leave off speaking, hold peace, plow(-er, man), be quiet, rest, practise secretly, keep silence, be silent, speak not a word, be still, hold tongue, worker.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6186A}/[H6186]', 'inflected', 'heb', 'עָרַךְ', '["ʻârak"]', '["and/ I will arrange"]', '["v"]', 'to set in a row, i.e. arrange, put in order (in a very wide variety of applications) put (set) (the battle, self) in array, compare, direct, equal, esteem, estimate, expert (in war), furnish, handle, join (battle), ordain, (lay, put, reckon up, set) (in) order, prepare, tax, value.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3526H}/H9030/[H3526]', 'inflected', 'heb', 'כָּבַס', '["kâbaç"]', '["wash/ me","you will wash/ me"]', '["v"]', 'to trample; hence, to wash (properly, by stamping with the feet), whether literal (including the fulling process) or figurative fuller, wash(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H2403B}/H9020/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["and/ from/ sin/ my"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2891}/H9030/[H2891]', 'inflected', 'heb', 'טָהֵר', '["ṭâhêr"]', '["cleanse/ me"]', '["v"]', 'to be pure (physical sound, clear, unadulterated; Levitically, uncontaminated; morally, innocent or holy) be (make, make self, pronounce) clean, cleanse (self), purge, purify(-ier, self).', 'a primitive root; properly, to be bright; i.e. (by implication)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7451H}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["and/ the/ evil"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1696I}/H9041/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["when/ speaking/ you"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8199}/H9041/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["when/ judging/ you"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2399}/[H2398]', 'inflected', 'heb', 'חֵטְא', '["chêṭᵉʼ"]', '["and/ in/ sin"]', '["n-m"]', 'a crime or its penalty fault, × grievously, offence, (punishment of) sin.', 'from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3179}/H9030/[H3179]', 'inflected', 'heb', 'יָחַם', '["yâcham"]', '["she conceived/ me"]', '["v"]', 'probably to be hot; figuratively, to conceive get heat, be hot, conceive, be warm.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5640A}/[H5640]', 'inflected', 'heb', 'סָתַם', '["çâtham"]', '["and/ in/ a [place] kept secret"]', '["v"]', 'to stop up; by implication, to repair; figuratively, to keep secret closed up, hidden, secret, shut out (up), stop.', 'or שָׂתַם; (Numbers 24:15), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2398}/H9030/[H2398]', 'inflected', 'heb', 'חָטָא', '["châṭâʼ"]', '["you will cleanse from sin/ me"]', '["v"]', 'properly, to miss; hence (figuratively and generally) to sin; by inference, to forfeit, lack, expiate, repent, (causatively) lead astray, condemn bear the blame, cleanse, commit (sin), by fault, harm he hath done, loss, miss, (make) offend(-er), offer for sin, purge, purify (self), make reconciliation, (cause, make) sin(-ful, -ness), trespass.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0231}/[H231]', 'inflected', 'heb', 'אֵזוֹב', '["ʼêzôwb"]', '["with/ hyssop"]', '["n-m"]', 'hyssop hyssop.', 'probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H7950}/[H7949]', 'inflected', 'heb', 'שֶׁלֶג', '["sheleg"]', '["and/ more than/ snow"]', '["n-m"]', 'snow (probably from its whiteness) snow(-y).', 'from 7949;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3835A}/[H3843]', 'lemma', 'heb', 'לָבַן', '["lâban"]', '["I will become white","they will become white"]', '["v"]', 'to be (or become) white; to make bricks make brick, be (made, make) white(-r).', 'a primitive root; also as denominative from 3843');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2399}/H9020/[H2398]', 'inflected', 'heb', 'חֵטְא', '["chêṭᵉʼ"]', '["from/ sins/ my"]', '["n-m"]', 'a crime or its penalty fault, × grievously, offence, (punishment of) sin.', 'from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7993}/H9030/[H7993]', 'inflected', 'heb', 'שָׁלַךְ', '["shâlak"]', '["you cast away/ me","you cast/ me"]', '["v"]', 'to throw out, down or away (literally or figuratively) adventure, cast (away, down, forth, off, out), hurl, pluck, throw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3190}/H9012/[H3190]', 'inflected', 'heb', 'יָטַב', '["yâṭab"]', '["do good to/ !","do good/ !"]', '["v"]', 'to be (causative) make well, literally (sound, beautiful) or figuratively (happy, successful, right) be accepted, amend, use aright, benefit, be (make) better, seem best, make cheerful, be comely, be content, diligent(-ly), dress, earnestly, find favour, give, be glad, do (be, make) good(-ness), be (make) merry, please ( well), shew more (kindness), skilfully, × very small, surely, make sweet, thoroughly, tire, trim, very, be (can, deal, entreat, go, have) well (said, seen).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8593}/[H6168]', 'inflected', 'heb', 'תַּעַר', '["taʻar"]', '["like/ a razor"]', '["n"]', 'a knife or razor (as making bare); also a scabbard (as being bare, i.e. empty) (pen-) knife, razor, scabbard, shave, sheath.', 'from 6168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1105}/[H1104]', 'lemma', 'heb', 'בֶּלַע', '["belaʻ"]', '["swallowing"]', '["n-m"]', 'a gulp; figuratively, destruction devouring, that which he hath swallowed up.', 'from 1104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5422}/H9031/[H5422]', 'inflected', 'heb', 'נָתַץ', '["nâthats"]', '["he will tear down/ you"]', '["v"]', 'to tear down beat down, break down (out), cast down, destroy, overthrow, pull down, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2846}/H9031/[H2846]', 'inflected', 'heb', 'חָתָה', '["châthâh"]', '["he will snatch up/ you"]', '["v"]', 'to lay hold of; especially to pick up fire heap, take (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5255}/H9031/[H5255]', 'inflected', 'heb', 'נָסַח', '["nâçach"]', '["and/ he will tear away/ you"]', '["v"]', 'to tear away destroy, pluck, root.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8327}/H9031/[H8327]', 'inflected', 'heb', 'שָׁרַשׁ', '["shârash"]', '["and/ he will root up/ you"]', '["v"]', 'to root, i.e. strike into the soil, or (by implication) to pluck from it (take, cause to take) root (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4581}/H9023/[H5810]', 'inflected', 'heb', 'מָעוֹז', '["mâʻôwz"]', '["refuge/ his","stronghold/ his"]', '["n-m"]', 'a fortified place; figuratively, a defence force, fort(-ress), rock, strength(-en), (× most) strong (hold).', '(also מָעוּז ); or מָעֹז (also מָעֻז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1942}/H9023/[H1933]', 'inflected', 'heb', 'הַוָּה', '["havvâh"]', '["in/ destruction/ his"]', '["n-f"]', 'by implication, of falling); desire; also ruin calamity, iniquity, mischief, mischievous (thing), naughtiness, naughty, noisome, perverse thing, substance, very wickedness.', 'from 1933 (in the sense of eagerly coveting and rushing upon;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2617A}/[H2616]', 'inflected', 'heb', 'חֶסֶד', '["cheçed"]', '["by <the>/ loyalty","by/ loyalty","in <the>/ covenant loyalty","in/ [the] covenant loyalty of"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4257}/[H2470]', 'lemma', 'heb', 'מַחֲלַת', '["machălath"]', '["Machalath","Mahalath"]', '["n-f"]', '''Machalath'', probably the title (initial word) of a popular song Mahalath.', 'from 2470; sickness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2583}/H9031/[H2603]', 'inflected', 'heb', 'חָנָה', '["chânâh"]', '["[one who] encamped against/ you"]', '["v"]', 'properly, to incline; by implication, to decline (of the slanting rays of evening); specifically, to pitch a tent; generally to encamp (for abode or siege) abide (in tents), camp, dwell, encamp, grow to an end, lie, pitch (tent), rest in tent.', 'a primitive root (compare 2603);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1369}/H9021/[H1368]', 'inflected', 'heb', 'גְּבוּרָה', '["gᵉbûwrâh"]', '["and/ by/ strength/ your"]', '["n-f"]', 'force (literally or figuratively); by implication, valor, victory force, mastery, might, mighty (act, power), power, strength.', 'feminine passive participle from the same as 1368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0561}/[H559]', 'inflected', 'heb', 'אֵמֶר', '["ʼêmer"]', '["to/ [the] words of","to/ words of"]', '["n-m"]', 'something said answer, × appointed unto him, saying, speech, word.', 'from 559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6184}/[H6206]', 'inflected', 'heb', 'עָרִיץ', '["ʻârîyts"]', '["and/ ruthless [people]"]', '["a"]', 'fearful, i.e. powerful or tyrannical mighty, oppressor, in great power, strong, terrible, violent.', 'from 6206;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5564}/[H5564]', 'inflected', 'heb', 'סָמַךְ', '["çâmak"]', '["[is] <in>/ [those who] sustain"]', '["v"]', 'to prop (literally or figuratively); reflexively, to lean upon or take hold of (in a favorable or unfavorable sense) bear up, establish, (up-) hold, lay, lean, lie hard, put, rest self, set self, stand fast, stay (self), sustain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8324}/H9020/[H8324]', 'inflected', 'heb', 'שָׁרַר', '["shârar"]', '["to/ enemies/ my"]', '["n-m"]', 'to be hostile (only active participle an opponent) enemy.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0341}/H9020/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["and/ on/ enemies/ my"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8467}/H9020/[H2603]', 'inflected', 'heb', 'תְּחִנָּה', '["tᵉchinnâh"]', '["from/ supplication/ my"]', '["n-f"]', 'graciousness; causatively, entreaty favour, grace, supplication.', 'from 2603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1949}/[H2000]', 'inflected', 'heb', 'הוּם', '["hûwm"]', '["and/ I am distraught"]', '["v"]', 'to make an uproar, or agitate greatly destroy, move, make a noise, put, ring again.', 'a primitive root (compare 2000);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6125}/[H5781]', 'lemma', 'heb', 'עָקָה', '["ʻâqâh"]', '["[the] pressure of"]', '["n-f"]', 'constraint oppression.', 'from 5781;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0639G}/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["and/ in/ anger"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0367}/[H366]', 'inflected', 'heb', 'אֵימָה', '["ʼêymâh"]', '["and/ [the] terrors of"]', '["n-f"]', 'fright; concrete, an idol (as a bugbear) dread, fear, horror, idol, terrible, terror.', 'or (shortened) אֵמָה; from the same as 366;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3680}/H9030/[H3680]', 'inflected', 'heb', 'כָּסָה', '["kâçâh"]', '["and/ it has covered/ me"]', '["v"]', 'properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0083}/[H82]', 'lemma', 'heb', 'אֵבֶר', '["ʼêber"]', '["wing[s]"]', '["n-m"]', 'a pinion (long-) wing(-ed).', 'from 82;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3123}/[H3196]', 'inflected', 'heb', 'יוֹנָה', '["yôwnâh"]', '["[are] like/ doves","like <the>/ dove","like/ [the] doves of","like/ a dove"]', '["n-f"]', 'a dove (apparently from the warmth of their mating) dove, pigeon.', 'probably from the same as 3196;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4655}/[H6403]', 'lemma', 'heb', 'מִפְלָט', '["miphlâṭ"]', '["a place of escape"]', '["n-m"]', 'an escape escape.', 'from 6403;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7307H}/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["from/ a wind"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5584}/[H5584]', 'lemma', 'heb', 'סָעָה', '["çâʻâh"]', '["rushing"]', '["v"]', 'to rush storm.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5591A}/[H5590]', 'inflected', 'heb', 'סַעַר', '["çaʻar"]', '["from/ a storm"]', '["n-m"]', 'a hurricane storm(-y), tempest, whirlwind.', 'or (feminine) סְעָרָה; from 5590;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3956H}/H9028/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["tongue/ their"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5437H}/H9034/[H5437]', 'inflected', 'heb', 'סָבַב', '["çâbab"]', '["they go around/ it"]', '["v"]', 'to revolve, surround, or border; used in various applications, literally and figuratively bring, cast, fetch, lead, make, walk, × whirl, × round about, be about on every side, apply, avoid, beset (about), besiege, bring again, carry (about), change, cause to come about, × circuit, (fetch a) compass (about, round), drive, environ, × on every side, beset (close, come, compass, go, stand) round about, inclose, remove, return, set, sit down, turn (self) (about, aside, away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2346G>/H9024', 'opaque', 'heb', 'חוֹמָה', '["chôwmâh"]', '["walls/ its"]', '["n-f"]', 'a wall of protection wall, walled.', 'feminine active participle of an unused root apparently meaning to join;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5999}/[H5998]', 'inflected', 'heb', 'עָמָל', '["ʻâmâl"]', '["and/ [the] labor of","and/ mischief","and/ trouble"]', '["n"]', 'toil, i.e. wearing effort; hence, worry, whether of body or mind grievance(-vousness), iniquity, labour, mischief, miserable(-sery), pain(-ful), perverseness, sorrow, toil, travail, trouble, wearisome, wickedness.', 'from 5998;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7339}/H9024/[H7337]', 'inflected', 'heb', 'רְחֹב', '["rᵉchôb"]', '["from/ public square/ its"]', '["n-f"]', 'a width, i.e. (concretely) avenue or area broad place (way), street. See also 1050.', 'or רְחוֹב; from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8496}/[H8432]', 'lemma', 'heb', 'תֹּךְ', '["tôk"]', '["oppression","oppression<s>"]', '["n-m"]', 'oppression deceit, fraud.', 'or תּוֹך; (Psalm 72:14), from the same base as 8432 (in the sense of cutting to pieces);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5375H}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ I may endure"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6187}/H9020/[H6186]', 'inflected', 'heb', 'עֵרֶךְ', '["ʻêrek"]', '["according to/ value/ my"]', '["n-m"]', 'a pile, equipment, estimate equal, estimation, (things that are set in) order, price, proportion, × set at, suit, taxation, × valuest.', 'from 6186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0441A}/H9020/[H502]', 'inflected', 'heb', 'אַלּוּף', '["ʼallûwph"]', '["close friend/ my"]', '["a-m"]', 'familiar; a friend, also gentle; hence, a bullock (as being tame; applied, although masculine, to a cow); and so, a chieftain (as notable, like neat cattle) captain, duke, (chief) friend, governor, guide, ox.', 'or (shortened) אַלֻּף; from 502;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7285A}/[H7283]', 'inflected', 'heb', 'רֶגֶשׁ', '["regesh"]', '["in/ a crowd"]', '["n-m n-f"]', 'a tumultuous crowd company, insurrection.', 'or (feminine) רִגְשָׁה; from 7283;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5377}/ /{H4194}/[H5377]', 'inflected', 'heb', 'נָשָׁא', '["nâshâʼ"]', '["may it deceive/ /death"]', '["v"]', 'to lead astray, i.e. (mentally) to delude, or (morally) to seduce beguile, deceive, × greatly, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4033}/H9028/[H1481]', 'inflected', 'heb', 'מָגוּר', '["mâgûwr"]', '["[are] in/ sojourning-place/ their"]', '["n-m"]', 'a temporary abode; by extension, a permanent residence dwelling, pilgrimage, where sojourn, be a stranger. Compare 4032.', 'or מָגֻר; from 1481 in the sense of lodging;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7130H}/H9028/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["in/ inner being/ their"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6672A}/[H6671]', 'inflected', 'heb', 'צֹהַר', '["tsôhar"]', '["and/ noon<s>"]', '["n-m"]', 'a light (i.e. window); dual double light, i.e. noon midday, noon(-day, -tide), window.', 'from 6671;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1993}/[H1949]', 'inflected', 'heb', 'הָמָה', '["hâmâh"]', '["and/ I may murmur","so/ I may murmur"]', '["v"]', 'to make a loud sound (like English ''hum''); by implication, to be in great commotion or tumult, to rage, war, moan, clamor clamorous, concourse, cry aloud, be disquieted, loud, mourn, be moved, make a noise, rage, roar, sound, be troubled, make in tumult, tumultuous, be in an uproar.', 'a primitive root (compare 1949);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7128}/[H7126]', 'inflected', 'heb', 'קְרָב', '["qᵉrâb"]', '["from/ battle"]', '["n-m"]', 'hostile encounter battle, war.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6031B}/H9038/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["and/ he will answer/ them"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7965J}/H9023/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["on/ allies/ his"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4260}/[H2529]', 'lemma', 'heb', 'מַחֲמָאָה', '["machămâʼâh"]', '["[the] creamy things of"]', '["n-f"]', 'something buttery (i.e. unctuous and pleasant), as (figuratively) flattery × than butter.', 'a denominative from 2529;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7128}/[H7126]', 'inflected', 'heb', 'קְרָב', '["qᵉrâb"]', '["and/ [was] war"]', '["n-m"]', 'hostile encounter battle, war.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6609}/[H6605]', 'lemma', 'heb', 'פְּתִחָה', '["pᵉthichâh"]', '["[were] drawn swords"]', '["n-f"]', 'something opened, i.e. a drawn sword drawn sword.', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3053}/H9021/[H3051]', 'inflected', 'heb', 'יְהָב', '["yᵉhâb"]', '["burden/ your"]', '["n-m"]', 'properly, what is given (by Providence), i.e. a lot burden.', 'from 3051;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3381}/H9038/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["I will bring down/ them","you will bring down/ them"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3128}/[H3123]', 'lemma', 'heb', 'יוֹנַת אֵלֶם רְחֹקִים', '["yôwnath ʼêlem rᵉchôqîym"]', '["elem-","rechokim","yonath-"]', '["n"]', 'dove of (the) silence (i.e. dumb Israel) of (i.e. among) distances (i.e. strangers); the title of a ditty (used for a name of its melody) Jonath-elem-rechokim.', 'from 3123 and 482 and the plural of 7350;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0270}/[H270]', 'inflected', 'heb', 'אָחַז', '["ʼâchaz"]', '["when/ seized"]', '["v"]', 'to seize (often with the accessory idea of holding in possession) be affrighted, bar, (catch, lay, take) hold (back), come upon, fasten, handle, portion, (get, have or take) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7602B}/H9030/[H7602]', 'inflected', 'heb', 'שָׁאַף', '["shâʼaph"]', '["[one who] crushes/ me","he has crushed/ me"]', '["v"]', 'to inhale eagerly; figuratively, to cover; by implication, to be angry; also to hasten desire (earnestly), devour, haste, pant, snuff up, swallow up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3905}/H9030/[H3905]', 'inflected', 'heb', 'לָחַץ', '["lâchats"]', '["he oppresses/ me"]', '["v"]', 'properly, to press, i.e. (figuratively) to distress afflict, crush, force, hold fast, oppress(-or), thrust self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7602B}/[H7602]', 'lemma', 'heb', 'שָׁאַף', '["shâʼaph"]', '["they have crushed [me]"]', '["v"]', 'to inhale eagerly; figuratively, to cover; by implication, to be angry; also to hasten desire (earnestly), devour, haste, pant, snuff up, swallow up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4284}/H9028/[H2803]', 'inflected', 'heb', 'מַחֲשָׁבָה', '["machăshâbâh"]', '["own schemes/ their","own thoughts/ their","plans/ their","thoughts/ their"]', '["n-f"]', 'a contrivance, i.e. (concretely) a texture, machine, or (abstractly) intention, plan (whether bad, a plot; or good, advice) cunning (work), curious work, device(-sed), imagination, invented, means, purpose, thought.', 'or מַחֲשֶׁבֶת; from 2803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1481B}/[H1481]', 'lemma', 'heb', 'גּוּר', '["gûwr"]', '["[is] quarreling","anyone will quarrel","certainly <to quarrel>","they stir up trouble"]', '["v"]', 'properly, to turn aside from the road (for a lodging or any other purpose), i.e. sojourn (as a guest); also to shrink, fear (as in a strange place); also to gather for hostility (as afraid) abide, assemble, be afraid, dwell, fear, gather (together), inhabitant, remain, sojourn, stand in awe, (be) stranger, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5112}/H9020/[H5110]', 'inflected', 'heb', 'נוֹד', '["nôwd"]', '["wandering/ my"]', '["n-m"]', 'exile wandering.', '(only defective נֹד ); from 5110;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H4997>/H9021', 'inflected', 'heb', 'בנאדך', '["ve./no.De./kha"]', '["in/ skin-bottle/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5612B}/H9021/[H9]', 'inflected', 'heb', 'סֵפֶר', '["çêpher"]', '["[is it] in/ scroll/ your"]', '["n-m"]', 'properly, writing (the art or a document); by implication, a book bill, book, evidence, × learn(-ed) (-ing), letter, register, scroll.', 'or (feminine) סִפְרָה; (Psalm 56:8 (9)), from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1762}/[H1760]', 'inflected', 'heb', 'דְּחִי', '["dᵉchîy"]', '["from/ stumbling"]', '["n-m"]', 'a push, i.e. (by implication) a fall falling.', 'from 1760;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0516}/[H408]', 'lemma', 'heb', 'אַל תַּשְׁחֵת', '["ʼAl tashchêth"]', '["al-","tashcheth"]', '["n-m"]', '''Thou must not destroy''; probably the opening words to a popular song Al-taschith.', 'from 408 and 7843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6738}/[H6751]', 'inflected', 'heb', 'צֵל', '["tsêl"]', '["and/ in/ [the] shadow of","and/ with/ [the] shadow of"]', '["n-m"]', 'shade, whether literal or figurative defence, shade(-ow).', 'from 6751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3833A>', 'opaque', 'heb', 'לָבִיא', '["lâbîyʼ"]', '["lions"]', '["n"]', 'a lion (properly, a lioness as the fiercer (although not a roarer;)) (great, old, stout) lion, lioness, young (lion).', 'or (Ezekiel 19:2) לְבִיָּא; irregular masculine plural לְבָאִים; irregular feminine plural לְבָאוֹת; from an unused root meaning to roar; compare 738');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2299}/[H2300]', 'lemma', 'heb', 'חַד', '["chad"]', '["sharp"]', '["a"]', 'sharp sharp.', 'from 2300;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6471}/H9020/[H6470]', 'inflected', 'heb', 'פַּעַם', '["paʻam"]', '["for/ feet/ my"]', '["n-f"]', 'a stroke, literally or figuratively (in various applications, as follow) anvil, corner, foot(-step), going, (hundred-) fold, × now, (this) once, order, rank, step, thrice, (often-), second, this, two) time(-s), twice, wheel.', 'or (feminine) פַּעֲמָה; from 6470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3721}/[H3721]', 'lemma', 'heb', 'כָּפַף', '["kâphaph"]', '["[those who] are bent down","it bent down","will I bend myself down?"]', '["v"]', 'to curve bow down (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7882}/[H7745]', 'lemma', 'heb', 'שִׁיחָה', '["shîychâh"]', '["a pit","pits"]', '["n-f"]', 'a pit-fall pit.', 'for 7745;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5035B}/[H5034]', 'inflected', 'heb', 'נֶבֶל', '["nebel"]', '["O/ lyre","the/ lyre"]', '["n-m"]', 'a skin-bag for liquids (from collapsing when empty); hence, a vase (as similar in shape when full); also a lyre (as having a body of like form) bottle, pitcher, psaltery, vessel, viol.', 'or נֵבֶל; from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0482}/[H481]', 'lemma', 'heb', 'אֵלֶם', '["ʼêlem"]', '["silence"]', '["a-m"]', 'silence (i.e. mute justice) congregation. Compare 3128.', 'from 481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1696I}/H9013/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["do you speak/ !"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6466}/H9013/[H6466]', 'inflected', 'heb', 'פָּעַל', '["pâʻal"]', '["you do/ !"]', '["v"]', 'to do or make (systematically and habitually), especially to practise commit, (evil-) do(-er), make(-r), ordain, work(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6424}/H9013/[H6424]', 'inflected', 'heb', 'פָּלַס', '["pâlaç"]', '["you weigh out/ !"]', '["v"]', 'properly, to roll flat, i.e. prepare (a road); also to revolve, i.e. weigh (mentally) make, ponder, weigh.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1823}/[H1819]', 'inflected', 'heb', 'דְּמוּת', '["dᵉmûwth"]', '["[is] like/ [the] likeness of","like/ [the] likeness of"]', '["n-f"]', 'resemblance; concretely, model, shape; adverbially, like fashion, like (-ness, as), manner, similitude.', 'from 1819;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4459}/[H4973]', 'lemma', 'heb', 'מַלְתָּעָה', '["maltâʻâh"]', '["[the] teeth of"]', '["n-f"]', 'a grinder, i.e. back tooth great tooth.', 'transp. for 4973;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3988B}/[H3988]', 'lemma', 'heb', 'מָאַס', '["mâʼaç"]', '["may they flow"]', '["v"]', 'to spurn; also (intransitively) to disappear abhor, cast away (off), contemn, despise, disdain, (become) loathe(some), melt away, refuse, reject, reprobate, × utterly, vile person.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7642}/[H7640]', 'lemma', 'heb', 'שַׁבְלוּל', '["shablûwl"]', '["a snail"]', '["n-m"]', 'a snail (as if floating in its own slime) snail.', 'from the same as 7640;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8557}/[H4529]', 'lemma', 'heb', 'תֶּמֶס', '["temeç"]', '["[which] melting away"]', '["n-m"]', 'liquefaction, i.e. disappearance melt.', 'from 4529;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5309}/[H5307]', 'lemma', 'heb', 'נֶפֶל', '["nephel"]', '["a miscarriage of"]', '["n-m"]', 'something fallen, i.e. an abortion untimely birth.', 'or נֵפֶל; from 5307;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5518A}/H9026/[H5518]', 'inflected', 'heb', 'סִיר', '["çîyr"]', '["pots/ your"]', '["n-m"]', 'a pot; also a thorn (as springing up rapidly); by implication, a hook caldron, fishhook, pan, (wash-)pot, thorn.', 'or (feminine) סִירָה; or סִרָה; (Jeremiah 52:18), from a primitive root meaning to boil up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0329H>', 'opaque', 'heb', 'אָטָד', '["ʼâṭâd"]', '["a thorn bush"]', '["n-m"]', 'a thorn-tree (especially the buckthorn) Atad, bramble, thorn.', 'from an unused root probably meaning to pierce or make fast;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8175B}/H9033/[H8175]', 'inflected', 'heb', 'שָׂעַר', '["sâʻar"]', '["he will blow away/ it"]', '["v"]', 'to storm; by implication, to shiver, i.e. fear be (horribly) afraid, fear, hurl as a storm, be tempestuous, come like (take away as with) a whirlwind.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6965J}/H9030/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["from/ [those who] rise up against/ me"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7682}/H9030/[H7682]', 'inflected', 'heb', 'שָׂגַב', '["sâgab"]', '["may it set on high/ me","may you set on high/ me"]', '["v"]', 'to be (causatively, make) lofty, especially inaccessible; by implication, safe, strong; used literally and figuratively defend, exalt, be excellent, (be, set on) high, lofty, be safe, set up (on high), be too strong.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6466}/[H6466]', 'inflected', 'heb', 'פָּעַל', '["pâʻal"]', '["from/ [those who] do"]', '["v"]', 'to do or make (systematically and habitually), especially to practise commit, (evil-) do(-er), make(-r), ordain, work(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0582}/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["and/ from/ men of"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7323G}/H9013/[H7323]', 'inflected', 'heb', 'רוּץ', '["rûwts"]', '["they run/ !"]', '["v"]', 'to run (for whatever reason, especially to rush) break down, divide speedily, footman, guard, bring hastily, (make) run (away, through), post.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6485H}/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["to/ punish","to/ visit"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H3611>', 'inflected', 'heb', 'ככלב', '["Ke./khe.lev","kha./Ka.lev"]', '["like <the>/ dog","like/ a dog"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5042}/H9013/[H5042]', 'inflected', 'heb', 'נָבַע', '["nâbaʻ"]', '["they pour forth/ !"]', '["v"]', 'to gush forth; figuratively, to utter (good or bad words); specifically, to emit (a foul odor) belch out, flowing, pour out, send forth, utter (abundantly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8193G}/H9028/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["[are] on/ lips/ their"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8324}/H9020/[H8324]', 'inflected', 'heb', 'שָׁרַר', '["shârar"]', '["on/ enemies/ my"]', '["n-m"]', 'to be hostile (only active participle an opponent) enemy.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5128}/H9038/[H5128]', 'inflected', 'heb', 'נוּעַ', '["nûwaʻ"]', '["make wander about/ them"]', '["v"]', 'to waver, in a great variety of applications, literally and figuratively (as subjoined) continually, fugitive, × make, to (go) up and down, be gone away, (be) move(-able, -d), be promoted, reel, remove, scatter, set, shake, sift, stagger, to and fro, be vagabond, wag, (make) wander (up and down).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2428G}/H9021/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["by/ strength/ your"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3381}/H9038/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["and/ bring down/ them"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4043}/H9025/[H1598]', 'inflected', 'heb', 'מָגֵן', '["mâgên"]', '["O shield/ our","shield/ our"]', '["n-m"]', 'a shield (i.e. the small one or buckler); figuratively, a protector; also the scaly hide of the crocodile × armed, buckler, defence, ruler, scale, shield.', 'also (in plural) feminine מְגִנָּה; from 1598;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8193G}/H9028/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["lips/ their"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1347}/H9028/[H1342]', 'inflected', 'heb', 'גָּאוֹן', '["gâʼôwn"]', '["in/ pride/ their"]', '["n-m"]', 'the same as 1346 arrogancy, excellency(-lent), majesty, pomp, pride, proud, swelling.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0423}/[H422]', 'inflected', 'heb', 'אָלָה', '["ʼâlâh"]', '["and/ from/ a curse"]', '["n-f"]', 'an imprecation curse, cursing, execration, oath, swearing.', 'from 422;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H3585}/[H3584]', 'inflected', 'heb', 'כַּחַשׁ', '["kachash"]', '["and/ from/ lying"]', '["n-m"]', 'literally a failure of flesh, i.e. emaciation; figuratively, hypocrisy leanness, lies, lying.', 'from 3584;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0657A}/[H656]', 'inflected', 'heb', 'אֶפֶס', '["ʼepheç"]', '["to/ [the] ends of"]', '["n-m"]', 'cessation, i.e. an end (especially of the earth); often used adverb, no further; also the ankle (in the dual), as being the extremity of the leg or foot ankle, but (only), end, howbeit, less than nothing, nevertheless (where), no, none (beside), not (any, -withstanding), thing of nought, save(-ing), there, uttermost part, want, without (cause).', 'from 656; (sometimes like 6466)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5128}/H9013/[H5128]', 'inflected', 'heb', 'נוּעַ', '["nûwaʻ"]', '["they make wander about/ !","they shake/ !"]', '["v"]', 'to waver, in a great variety of applications, literally and figuratively (as subjoined) continually, fugitive, × make, to (go) up and down, be gone away, (be) move(-able, -d), be promoted, reel, remove, scatter, set, shake, sift, stagger, to and fro, be vagabond, wag, (make) wander (up and down).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6887C}/[H6887]', 'lemma', 'heb', 'צָרַר', '["tsârar"]', '["[when] it is distress","in labor"]', '["v"]', 'to cramp, literally or figuratively, transitive or intransitive adversary, (be in) afflict(-ion), beseige, bind (up), (be in, bring) distress, enemy, narrower, oppress, pangs, shut up, be in a strait (trouble), vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5327A}/H9043/[H5327]', 'inflected', 'heb', 'נָצָה', '["nâtsâh"]', '["when/ struggled with/ he"]', '["v"]', 'properly, to go forth, i.e. (by implication) to be expelled, and (consequently) desolate; causatively, to lay waste; also (specifically), to quarrel be laid waste, runinous, strive (together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0763H}/[H758]', 'lemma', 'heb', 'אֲרַם נַהֲרַיִם', '["ʼĂram Nahărayim"]', '["Aram","Naharaim"]', '["n-pr-loc"]', 'Aram of (the) two rivers (Euphrates and Tigris) or Mesopotamia Aram-naharaim, Mesopotamia.', 'from 758 and the dual of 5104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0760}/[H758]', 'lemma', 'heb', 'אֲרַם צוֹבָה', '["ʼĂram Tsôwbâh"]', '["Aram","Zobah"]', '["n-pr-loc"]', 'Aram of Tsoba (or Coele-Syria) Aram-zobah.', 'from 758 and 6678;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2186A}/H9035/[H2186]', 'inflected', 'heb', 'זָנַח', '["zânach"]', '["have you rejected/ us","you have rejected/ us"]', '["v"]', 'reject, forsake, fail cast away (off), remove far away (off).', 'a primitive root meaning to push aside, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6555}/H9035/[H6555]', 'inflected', 'heb', 'פָּרַץ', '["pârats"]', '["you have broken out against/ us"]', '["v"]', 'to break out (in many applications, direct and indirect, literal and figurative) × abroad, (make a) breach, break (away, down, -er, forth, in, up), burst out, come (spread) abroad, compel, disperse, grow, increase, open, press, scatter, urge.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6480}/H9034/[H6480]', 'inflected', 'heb', 'פָּצַם', '["pâtsam"]', '["you have split open/ it"]', '["v"]', 'to rend (by earthquake) break.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7667}/H9024/[H7665]', 'inflected', 'heb', 'שֶׁבֶר', '["sheber"]', '["breaking/ its","fractures/ its"]', '["n-m"]', 'a fracture, figuratively, ruin; specifically, a solution (of a dream) affliction, breach, breaking, broken(-footed, -handed), bruise, crashing, destruction, hurt, interpretation, vexation.', 'or שֵׁבֶר; from 7665;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8248H}/H9035/[H8248]', 'inflected', 'heb', 'שָׁקָה', '["shâqâh"]', '["you have made drink/ us"]', '["v"]', 'to quaff, i.e. (causatively) to irrigate or furnish a potion to cause to (give, give to, let, make to) drink, drown, moisten, water. See 7937, 8354.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8653}/[H7477]', 'lemma', 'heb', 'תַּרְעֵלָה', '["tarʻêlâh"]', '["staggering"]', '["n-f"]', 'reeling astonishment, trembling.', 'from 7477;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5264}/[H5251]', 'inflected', 'heb', 'נָסַס', '["nâçaç"]', '["for/ displaying"]', '["v"]', 'to raise a beacon lift up as an ensign.', 'a primitive root; to gleam from afar, i.e. to be conspicuous as a signal; or rather perhaps a denominative from 5251 (and identical with 5263, through the idea of a flag as fluttering in the wind);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7189A>', 'opaque', 'heb', 'קֹשֶׁט', '["qôsheṭ"]', '["[the] bow"]', '["n-m"]', 'equity (as evenly weighed), i.e. reality truth.', 'or קֹשְׁטְ; from an unused root meaning to balance;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2502A}/H9013/[H2502]', 'inflected', 'heb', 'חָלַץ', '["châlats"]', '["they may be rescued/ !"]', '["v"]', 'to pull off; hence (intensively) to strip, (reflex.) to depart; by implication, to deliver, equip (for fight); present, strengthen arm (self), (go, ready) armed (× man, soldier), deliver, draw out, make fat, loose, (ready) prepared, put off, take away, withdraw self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3039A}/H9021/[H1730]', 'inflected', 'heb', 'יְדִיד', '["yᵉdîyd"]', '["beloved [ones]/ your"]', '["a n-f"]', 'loved amiable, (well-) beloved, loves.', 'from the same as 1730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6944G}/H9023/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["by/ holiness/ his","in/ holiness/ his","in/ sanctuary/ his"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6010R}/[H6009]', 'inflected', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["and/ [the] Valley of","and/ [the] valleys"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4058}/[H4058]', 'lemma', 'heb', 'מָדַד', '["mâdad"]', '["I will measure off","has he measured","he measured","he measured [it]","it will be measured","they will be measured","you will measure"]', '["v"]', 'properly, to stretch; by implication, to measure (as if by stretching a line); figuratively, to be extended measure, mete, stretch self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218H>/H9020', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["head/ my"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2710}/H9030/[H2710]', 'inflected', 'heb', 'חָקַק', '["châqaq"]', '["[is] commander''s staff/ my"]', '["v"]', 'properly, to hack, i.e. engrave (Judges 5:14, to be a scribe simply); by implication, to enact (laws being cut in stone or metal tablets in primitive times) or (gen.) prescribe appoint, decree, governor, grave, lawgiver, note, pourtray, print, set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7366}/H9020/[H7364]', 'inflected', 'heb', 'רַחַץ', '["rachats"]', '["washing/ my"]', '["n-m"]', 'a bath wash(-pot).', 'from 7364;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5275}/H9020/[H5274]', 'inflected', 'heb', 'נַעַל', '["naʻal"]', '["sandal/ my"]', '["n-f"]', 'properly, a sandal tongue; by extension a sandal or slipper (sometimes as a symbol of occupancy, a refusal to marry, or of something valueless) dryshod, (pair of) shoe((-latchet), -s).', 'or (feminine) נַעֲלָה; from 5274;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2986}/H9030/[H2986]', 'inflected', 'heb', 'יָבַל', '["yâbal"]', '["will he bring/ me"]', '["v"]', 'properly, to flow; causatively, to bring (especially with pomp) bring (forth), carry, lead (forth).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6862C}/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["from/ [the] foe"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7723H}/[H7722]', 'inflected', 'heb', 'שָׁוְא', '["shâvᵉʼ"]', '["and/ [is] worthlessness"]', '["n-m"]', 'evil (as destructive), literally (ruin) or morally (especially guile); figuratively idolatry (as false, subjective), uselessness (as deceptive, objective; also adverbially, in vain) false(-ly), lie, lying, vain, vanity.', 'or שַׁו; from the same as 7722 in the sense of desolating;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5058}/[H5059]', 'lemma', 'heb', 'נְגִינָה', '["nᵉgîynâh"]', '["a stringed instrument"]', '["n-f"]', 'properly, instrumental music; by implication, a stringed instrument; by extension, a poem set to music; specifically, an epigram stringed instrument, musick, Neginoth (plural), song.', 'or נְגִינַת; (Psalm 61:title), from 5059;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5848C}/[H5848]', 'inflected', 'heb', 'עָטַף', '["ʻâṭaph"]', '["because/ faint","when/ fainted away","when/ faints away","when/ grows faint"]', '["v"]', 'to shroud, i.e. clothe (whether transitive or reflex.); hence (from the idea of darkness) to languish cover (over), fail, faint, feebler, hide self, be overwhelmed, swoon.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5088}/H9020/[H5087]', 'inflected', 'heb', 'נֶדֶר', '["neder"]', '["to/ vows/ my"]', '["n-m"]', 'a promise (to God); also (concretely) a thing promised vow(-ed).', 'or נֵדֶר; from 5087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7999A}/H9030/[H7999]', 'inflected', 'heb', 'שָׁלַם', '["shâlam"]', '["to/ pay/ I"]', '["v"]', 'to be safe (in mind, body or estate); figuratively, to be (causatively, make) completed; by implication, to be friendly; by extension, to reciprocate (in various applications) make amends, (make an) end, finish, full, give again, make good, (re-) pay (again), (make) (to) (be at) peace(-able), that is perfect, perform, (make) prosper(-ous), recompense, render, requite, make restitution, restore, reward, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3444}/H9020/[H3467]', 'inflected', 'heb', 'יְשׁוּעָה', '["yᵉshûwʻâh"]', '["and/ salvation/ my"]', '["n-f"]', 'something saved, i.e. (abstractly) deliverance; hence, aid, victory, prosperity deliverance, health, help(-ing), salvation, save, saving (health), welfare.', 'feminine passive participle of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2050}/[H2050]', 'lemma', 'heb', 'הָתַת', '["hâthath"]', '["will you attack"]', '["v"]', 'properly, to break in upon, i.e. to assail imagine mischief.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7023}/[H6979]', 'inflected', 'heb', 'קִיר', '["qîyr"]', '["like/ a wall"]', '["n-m"]', 'a wall (as built in a trench) mason, side, town, × very, wall.', 'or קִר; (Isaiah 22:5), or (feminine) קִירָה; from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1760A}/[H1760]', 'inflected', 'heb', 'דָּחָה', '["dâchâh"]', '["<the>/ pushed down"]', '["v"]', 'to push down chase, drive away (on), overthrow, outcast, × sore, thrust, totter.', 'or דָּחַח; (Jeremiah 23:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7130H}/H9028/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["and/ in/ inner being/ their"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4268}/H9020/[H2620]', 'inflected', 'heb', 'מַחֲסֶה', '["machăçeh"]', '["[are] refuge of/ my","[are] refuge/ my","refuge/ my","shelter/ my"]', '["n-m"]', 'a shelter (literally or figuratively) hope, (place of) refuge, shelter, trust.', 'or מַחְסֶה; from 2620;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1892}/[H1891]', 'inflected', 'heb', 'הֶבֶל', '["hebel"]', '["[are] more than/ a breath","from/ vanity"]', '["n-m"]', 'emptiness or vanity; figuratively, something transitory and unsatisfactory; often used as an adverb × altogether, vain, vanity.', 'or (rarely in the abs.) הֲבֵל; from 1891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6233}/[H6231]', 'inflected', 'heb', 'עֹשֶׁק', '["ʻôsheq"]', '["by <the>/ oppression","in/ extortion","in/ oppression","with <the>/ oppression"]', '["n-m"]', 'injury, fraud, (subjectively) distress, (concretely) unjust gain cruelly, extortion, oppression, thing (deceitfully gotten).', 'from 6231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1498}/[H1497]', 'inflected', 'heb', 'גָּזֵל', '["gâzêl"]', '["and/ in/ robbery"]', '["n-m"]', 'robbery, or (concretely) plunder robbery, thing taken away by violence.', 'from 1497;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5107}/[H5107]', 'lemma', 'heb', 'נוּב', '["nûwb"]', '["it will bear fruit","it will cause to thrive"]', '["v"]', 'to germinate, i.e. (figuratively) to (causatively, make) flourish; also (of words), to utter bring forth (fruit), make cheerful, increase.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7836}/H9031/[H7836]', 'inflected', 'heb', 'שָׁחַר', '["shâchar"]', '["I am seeking earnestly/ you","I will seek/ you"]', '["v"]', 'properly, to dawn, i.e. (figuratively) be (up) early at any task (with the implication of earnestness); by extension, to search for (with painstaking) (do something) betimes, enquire early, rise (seek) betimes, seek diligently) early, in the morning).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3642}/[H3642]', 'lemma', 'heb', 'כָּמַהּ', '["kâmahh"]', '["it longs"]', '["v"]', 'to pine after long.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2372}/H9031/[H2372]', 'inflected', 'heb', 'חָזָה', '["châzâh"]', '["I have seen/ you"]', '["v"]', 'to gaze at; mentally to perceive, contemplate (with pleasure); specifically, to have a vision of behold, look, prophesy, provide, see.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3519}/H9021/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["and/ glory/ your"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2416E}/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["more than/ life"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7623B}/H9031/[H7623]', 'inflected', 'heb', 'שָׁבַח', '["shâbach"]', '["they will extol/ you"]', '["v"]', 'properly, to address in a loud tone, i.e. (specifically) loud; figuratively, to pacify (as if by words) commend, glory, keep in, praise, still, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1880}/[H1878]', 'inflected', 'heb', 'דֶּשֶׁן', '["deshen"]', '["and/ fatness"]', '["n-m"]', 'the fat; abstractly fatness, i.e. (figuratively) abundance; specifically the (fatty) ashes of sacrifices ashes, fatness.', 'from 1878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8193G}/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["and/ [the] lips of","and/ lips of"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H7722B>', 'inflected', 'heb', 'לשואה', '["Le./sho.''ah"]', '["to/ destruction"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5064}/H9033/[H5064]', 'inflected', 'heb', 'נָגַר', '["nâgar"]', '["people will pour/ him"]', '["v"]', 'to flow; figuratively, to stretch out; causatively, to pour out or down; figuratively, to deliver over fall, flow away, pour down (out), run, shed, spilt, trickle down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7650}/[H7651]', 'inflected', 'heb', 'שָׁבַע', '["shâbaʻ"]', '["<the>/ [one who] swears an oath","the/ [one who] swears an oath","those/ [who] swear","those/ [who] swear an oath"]', '["v"]', 'to seven oneself, i.e. swear (as if by repeating a declaration seven times) adjure, charge (by an oath, with an oath), feed to the full (by mistake for 7646), take an oath, × straitly, (cause to, make to) swear.', 'a primitive root; properly to be complete, but used only as a denominative from 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5534}/[H5534]', 'lemma', 'heb', 'סָכַר', '["çâkar"]', '["it will be shut up"]', '["v"]', 'to shut up; by implication, to surrender stop, give over. See also 5462, 7936.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5475}/[H3245]', 'inflected', 'heb', 'סוֹד', '["çôwd"]', '["from/ [the] secret counsel of"]', '["n-m"]', 'a session, i.e. company of persons (in close deliberation); by implication, intimacy, consultation, a secret assembly, consel, inward, secret (counsel).', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7285B}/[H7283]', 'inflected', 'heb', 'רֶגֶשׁ', '["regesh"]', '["from/ [the] unrest of"]', '["n-m n-f"]', 'a tumultuous crowd company, insurrection.', 'or (feminine) רִגְשָׁה; from 7283;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2719}/[H2717]', 'inflected', 'heb', 'חֶרֶב', '["chereb"]', '["like <the>/ sword","like/ [the] sword of","like/ a sword","like/ a sword of"]', '["n-f"]', 'drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3384A}/H9033/[H3384]', 'inflected', 'heb', 'יָרָה', '["yârâh"]', '["they shoot at/ him"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2665}/[H2664]', 'lemma', 'heb', 'חֵפֶשׂ', '["chêphes"]', '["a plot"]', '["n-m"]', 'something covert, i.e. a trick search.', 'from 2664;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7130H}/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["and/ [the] inner being of"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4347}/H9028/[H5221]', 'inflected', 'heb', 'מַכָּה', '["makkâh"]', '["wounds/ their"]', '["n-f"]', 'a blow (in 2 Chronicles 2:10, of the flail); by implication, a wound; figuratively, carnage, also pestilence beaten, blow, plague, slaughter, smote, × sore, stripe, stroke, wound(-ed).', 'or (masculine) מַכֶּה; (plural only) from 5221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3782}/H9033/[H3782]', 'inflected', 'heb', 'כָּשַׁל', '["kâshal"]', '["and/ they caused to stumble/ him"]', '["v"]', 'to totter or waver (through weakness of the legs, especially the ankle); by implication, to falter, stumble, faint or fall bereave (from the margin), cast down, be decayed, (cause to) fail, (cause, make to) fall (down, -ing), feeble, be (the) ruin(-ed, of), (be) overthrown, (cause to) stumble, × utterly, be weak.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2620}/[H982]', 'inflected', 'heb', 'חָסָה', '["châçâh"]', '["and/ he will take refuge","and/ they will take refuge"]', '["v"]', 'to flee for protection; figuratively, to confide in have hope, make refuge, (put) trust.', 'a primitive root; (compare 982)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1984H}/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["and/ let them boast","and/ they may boast"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6726}/[H6725]', 'inflected', 'heb', 'צִיּוֹן', '["Tsîyôwn"]', '["<in>/ Zion","in/ Zion","on/ Zion"]', '["n-pr-loc"]', 'Tsijon (as a permanent capital), a mountain of Jerusalem Zion.', 'the same (regularly) as 6725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6588}/H9025/[H6586]', 'inflected', 'heb', 'פֶּשַׁע', '["peshaʻ"]', '["transgressions/ our"]', '["n-m"]', 'a revolt (national, moral or religious) rebellion, sin, transgression, trespass.', 'from 6586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3722A}/H9038/[H3722]', 'inflected', 'heb', 'כָּפַר', '["kâphar"]', '["you atone for/ them"]', '["v"]', 'to cover (specifically with bitumen); figuratively, to expiate or condone, to placate or cancel appease, make (an atonement, cleanse, disannul, forgive, be merciful, pacify, pardon, purge (away), put off, (make) reconcile(-liation).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2691A}/H9021/[H2690]', 'inflected', 'heb', 'חָצֵר', '["châtsêr"]', '["courts/ your"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4009}/[H982]', 'lemma', 'heb', 'מִבְטָח', '["mibṭâch"]', '["[the] trust of","confidence of","security"]', '["n-m"]', 'properly, a refuge, i.e. (objective) security, or (subjective) assurance confidence, hope, sure, trust.', 'from 982;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7623A}/[H7623]', 'lemma', 'heb', 'שָׁבַח', '["shâbach"]', '["[who] calms"]', '["v"]', 'properly, to address in a loud tone, i.e. (specifically) loud; figuratively, to pacify (as if by words) commend, glory, keep in, praise, still, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1530H}/H9028/[H1556]', 'inflected', 'heb', 'גַּל', '["gal"]', '["waves/ their"]', '["n-m"]', 'something rolled, i.e. a heap of stone or dung (plural ruins), by analogy, a spring of water (plural waves) billow, heap, spring, wave.', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1995A}/[H1993]', 'inflected', 'heb', 'הָמוֹן', '["hâmôwn"]', '["and/ [the] abundance of","and/ [the] tumult of"]', '["n-m"]', 'a noise, tumult, crowd; also disquietude, wealth abundance, company, many, multitude, multiply, noise, riches, rumbling, sounding, store, tumult.', 'or הָמֹן; (Ezekiel 5:7), from 1993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7117}/[H7096]', 'lemma', 'heb', 'קְצָת', '["qᵉtsâth"]', '["[the] ends"]', '["n-f"]', 'a termination (literally or figuratively); also (by implication) a portion; adverbially (with prepositional prefix) after end, part, × some.', 'from 7096;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0226G}/H9021/[H225]', 'inflected', 'heb', 'אוֹת', '["ʼôwth"]', '["from/ signs/ your"]', '["n-f"]', 'a signal (literally or figuratively), as a flag, beacon, monument, omen, prodigy, evidence, etc. mark, miracle, (en-) sign, token.', 'probably from 225 (in the sense of appearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6153}/[H6150]', 'inflected', 'heb', 'עֶרֶב', '["ʻereb"]', '["and/ evening"]', '["n-m"]', 'dusk day, even(-ing, tide), night.', 'from 6150;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7783}/H9034/[H7783]', 'inflected', 'heb', 'שׁוּק', '["shûwq"]', '["and/ you made overflow/ it"]', '["v"]', 'to run after or over, i.e. overflow overflow, water.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6238}/H9034/[H6238]', 'inflected', 'heb', 'עָשַׁר', '["ʻâshar"]', '["you make rich/ it"]', '["v"]', 'properly, to accumulate; chiefly (specifically) to grow (causatively, make) rich be(-come, en-, make, make self, wax) rich, make (1 Kings 22:48 marg). See 6240.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3559A}/H9034/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["you prepare/ it"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7301}/[H7301]', 'lemma', 'heb', 'רָוָה', '["râvâh"]', '["I give water to","[surely] watering","it has drunk its fill","it has given water to","let us take our fill of"]', '["v"]', 'to slake the thirst (occasionally of other appetites) bathe, make drunk, (take the) fill, satiate, (abundantly) satisfy, soak, water (abundantly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1417}/H9024/[H1413]', 'inflected', 'heb', 'גְּדוּד', '["gᵉdûwd"]', '["ridges/ its"]', '["n"]', 'a furrow (as cut) furrow.', 'or גְּדֻדָה; (feminine) from 1413;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7241}/[H7231]', 'inflected', 'heb', 'רָבִיב', '["râbîyb"]', '["with/ copious showers"]', '["n-m"]', 'a rain (as an accumulation of drops) shower.', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4127}/H9034/[H4127]', 'inflected', 'heb', 'מוּג', '["mûwg"]', '["you soften/ it"]', '["v"]', 'to melt, i.e. literally (to soften, flow down, disappear), or figuratively (to fear, faint) consume, dissolve, (be) faint(-hearted), melt (away), make soft.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6780}/H9024/[H6779]', 'inflected', 'heb', 'צֶמַח', '["tsemach"]', '["growth/ its"]', '["n-m"]', 'a sprout (usually concrete), literal or figurative branch, bud, that which (where) grew (upon), spring(-ing).', 'from 6779;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5849B}/[H5849]', 'lemma', 'heb', 'עָטַר', '["ʻâṭar"]', '["you crown"]', '["v"]', 'to encircle (for attack or protection); especially to crown (literally or figuratively) compass, crown.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2896C}/H9021/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["goodness/ your"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4570}/H9021/[H5696]', 'inflected', 'heb', 'מַעְגָּל', '["maʻgâl"]', '["and/ tracks/ your"]', '["n-m"]', 'a track (literally or figuratively); also a rampart (as circular) going, path, trench, way(-side).', 'or feminine מַעְגָּלָה; from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7491}/H9013/[H7491]', 'inflected', 'heb', 'רָעַף', '["râʻaph"]', '["they drip/ !"]', '["v"]', 'to drip distil, drop (down).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4999}/[H4998]', 'lemma', 'heb', 'נָאָה', '["nâʼâh"]', '["[the] pastures of","[the] settlements of","settlements of"]', '["n-f"]', 'a home; figuratively, a pasture habitation, house, pasture, pleasant place.', 'from 4998;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5848B}/[H5848]', 'lemma', 'heb', 'עָטַף', '["ʻâṭaph"]', '["it covers","they cover themselves"]', '["v"]', 'to shroud, i.e. clothe (whether transitive or reflex.); hence (from the idea of darkness) to languish cover (over), fail, faint, feebler, hide self, be overwhelmed, swoon.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4639K}/H9021/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["[are] deeds/ your","deeds/ your"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5637}/[H5637]', 'inflected', 'heb', 'סָרַר', '["çârar"]', '["the/ rebellious [people]"]', '["v"]', 'to turn away, i.e. (morally) be refractory × away, backsliding, rebellious, revolter(-ing), slide back, stubborn, withdrew.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7760H}/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["<the>/ [who] placed","[is] the/ [one who] put"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4132}/[H4131]', 'inflected', 'heb', 'מוֹט', '["môwṭ"]', '["to <the>/ slip"]', '["n-m"]', 'a wavering, i.e. fall; by implication, a pole (as shaking); hence, a yoke (as essentially a bent pole) bar, be moved, staff, yoke.', 'from 4131;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0974}/H9035/[H974]', 'inflected', 'heb', 'בָּחַן', '["bâchan"]', '["you have tested/ us"]', '["v"]', 'to test (especially metals); generally and figuratively, to investigate examine, prove, tempt, try (trial).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6884}/H9035/[H6884]', 'inflected', 'heb', 'צָרַף', '["tsâraph"]', '["you have refined/ us"]', '["v"]', 'to fuse (metal), i.e. refine (literally or figuratively) cast, (re-) fine(-er), founder, goldsmith, melt, pure, purge away, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6884}/[H6884]', 'inflected', 'heb', 'צָרַף', '["tsâraph"]', '["as/ refine","as/ refines"]', '["v"]', 'to fuse (metal), i.e. refine (literally or figuratively) cast, (re-) fine(-er), founder, goldsmith, melt, pure, purge away, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4686A}/[H4685]', 'inflected', 'heb', 'מָצוּד', '["mâtsûwd"]', '["in the/ net"]', '["n-f"]', 'a net, or (abstractly) capture; also a fastness castle, defense, fort(-ress), (strong) hold, be hunted, net, snare, strong place.', 'or (feminine) מְצוּדָה; or מְצֻדָה; for 4685;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4157}/[H5781]', 'lemma', 'heb', 'מוּעָקָה', '["mûwʻâqâh"]', '["affliction"]', '["n-f"]', 'pressure, i.e. (figuratively) distress affliction.', 'from 5781;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H7218A>/H9025', 'inflected', 'heb', 'לראשנו', '["le./Ro.She./nu"]', '["to/ head/ our"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7310}/[H7301]', 'inflected', 'heb', 'רְוָיָה', '["rᵉvâyâh"]', '["to <the>/ superfluity"]', '["n-f"]', 'satisfaction runneth over, wealthy.', 'from 7301;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4220}/[H4229]', 'lemma', 'heb', 'מֵחַ', '["mêach"]', '["fatlings"]', '["n-m"]', 'fat; figuratively, rich fatling (one).', 'from 4229 in the sense of greasing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7318}/[H7426]', 'inflected', 'heb', 'רוֹמָם', '["rôwmâm"]', '["and/ exaltation"]', '["n-m"]', 'exaltation, i.e. (figuratively and specifically) praise be extolled.', 'from 7426;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1288}/H9035/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["and/ may he bless/ us"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3444}/H9021/[H3467]', 'inflected', 'heb', 'יְשׁוּעָה', '["yᵉshûwʻâh"]', '["<of> salvation/ your","salvation/ your"]', '["n-f"]', 'something saved, i.e. (abstractly) deliverance; hence, aid, victory, prosperity deliverance, health, help(-ing), salvation, save, saving (health), welfare.', 'feminine passive participle of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1288}/H9035/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["he will bless/ us"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5086}/[H5086]', 'inflected', 'heb', 'נָדַף', '["nâdaph"]', '["as/ is driven about"]', '["v"]', 'to shove asunder, i.e. disperse drive (away, to and fro), thrust down, shaken, tossed to and fro.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4549}/[H4549]', 'inflected', 'heb', 'מָסַס', '["mâçaç"]', '["as/ melts","as/ wastes away"]', '["v"]', 'to liquefy; figuratively, to waste (with disease), to faint (with fatigue, fear or grief) discourage, faint, be loosed, melt (away), refuse, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1749>', 'opaque', 'heb', 'דּוֹנַג', '["dôwnag"]', '["wax"]', '["n-m"]', 'wax; wax.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3050}/[H3068]', 'inflected', 'heb', 'יָהּ', '["Yâhh"]', '["[is] <in>/ Yahweh"]', '["n-pr"]', 'Jah, the sacred name Jah, the Lord, most vehement. Compare names in ''-iah,'' ''-jah.''', 'contraction for 3068, and meaning the same;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5937}/[H5937]', 'inflected', 'heb', 'עָלַז', '["ʻâlaz"]', '["and/ exult","so/ they may rejoice"]', '["v"]', 'to jump for joy, i.e. exult be joyful, rejoice, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1781}/[H1777]', 'inflected', 'heb', 'דַּיָּן', '["dayân"]', '["and/ a judge of"]', '["n-m"]', 'a judge or advocate judge.', 'from 1777;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4583}/[H5772]', 'inflected', 'heb', 'מָעוֹן', '["mâʻôwn"]', '["in/ [the] dwelling place of"]', '["n-m"]', 'an abode, of God (the Tabernacle or the Temple), men (their home) or animals (their lair); hence, a retreat (asylum) den, dwelling((-) place), habitation.', 'or מָעִין; (1 Chronicles 4:41), from the same as 5772;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3574}/[H3787]', 'inflected', 'heb', 'כּוֹשָׁרָה', '["kôwshârâh"]', '["in <the>/ prosperiti<es>"]', '["n-f"]', 'prosperity; in plural freedom × chain.', 'from 3787;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6707}/[H6706]', 'lemma', 'heb', 'צְחִיחָה', '["tsᵉchîychâh"]', '["a parched land"]', '["n-f"]', 'a parched region, i.e. the desert dry land.', 'feminine of 6706;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3452H}/[H3456]', 'inflected', 'heb', 'יְשִׁימוֹן', '["yᵉshîymôwn"]', '["in/ a desolate place","in/ a desolate place of"]', '["n-m"]', 'a desolation desert, Jeshimon, solitary, wilderness.', 'from 3456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5130A}/[H5130]', 'lemma', 'heb', 'נוּף', '["nûwph"]', '["I have sprinkled","you spread abroad"]', '["v"]', 'to quiver (i.e. vibrate up and down, or rock to and fro); used in a great variety of applications (including sprinkling, beckoning, rubbing, bastinadoing, sawing, waving, etc.) lift up, move, offer, perfume, send, shake, sift, strike, wave.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3811}/[H3811]', 'inflected', 'heb', 'לָאָה', '["lâʼâh"]', '["<and>/ weary"]', '["v"]', 'to tire; (figuratively) to be (or make) disgusted faint, grieve, lothe, (be, make) weary (selves).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3559I}/H9034/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["he established/ it","you established/ it"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2416D}/H9021/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["community/ your"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2896C}/H9021/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["in/ goodness/ your"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5074}/H9013/[H5074]', 'inflected', 'heb', 'נָדַד', '["nâdad"]', '["they flee/ !"]', '["v"]', 'properly, to wave to and fro (rarely to flap up and down); figuratively, to rove, flee, or (causatively) to drive away chase (away), × could not, depart, flee (× apace, away), (re-) move, thrust away, wander (abroad, -er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5116B}/[H5115]', 'inflected', 'heb', 'נָוֶה', '["nâveh"]', '["and/ [the] beautiful woman of"]', '["n"]', '(adjectively) at home; hence (by implication of satisfaction) lovely; also (noun) a home, of God (temple), men (residence), flocks (pasture), or wild animals (den) comely, dwelling (place), fold, habitation, pleasant place, sheepcote, stable, tarried.', 'or (feminine) נָוָה; from 5115;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8240A}/[H8239]', 'lemma', 'heb', 'שָׁפָת', '["shâphâth"]', '["[two] saddlebags"]', '["n-m"]', 'a (double) stall (for cattle); also a (two-pronged) hook (for flaying animals on) hook, pot.', 'from 8239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0084}/H9024/[H83]', 'inflected', 'heb', 'אֶבְרָה', '["ʼebrâh"]', '["and/ pinions/ its"]', '["n-f"]', 'feather, wing.', 'feminine of 83');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3422}/[H3418]', 'inflected', 'heb', 'יְרַקְרַק', '["yᵉraqraq"]', '["with/ greenish of"]', '["a"]', 'yellowishness greenish, yellow.', 'from the same as 3418;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2742D}/[H2782]', 'lemma', 'heb', 'חֲרוּץ', '["chărûwts"]', '["gold"]', '["a"]', 'properly, incised or (active) incisive; hence (as noun masculine or feminine) a trench (as dug), gold (as mined), a threshing-sledge (having sharp teeth); (figuratively) determination; also eager decision, diligent, (fine) gold, pointed things, sharp, threshing instrument, wall.', 'or חָרֻץ; passive participle of 2782;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6566}/[H6566]', 'inflected', 'heb', 'פָּרַשׂ', '["pâras"]', '["when/ scatters"]', '["v"]', 'to break apart, disperse, etc. break, chop in pieces, lay open, scatter, spread (abroad, forth, selves, out), stretch (forth, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7949}/[H7950]', 'lemma', 'heb', 'שָׁלַג', '["shâlag"]', '["let it snow"]', '["v"]', 'to be snow-white (with the linen clothing of the slain) be as snow.', 'a primitive root; properly, meaning to be white; used only as denominative from 7950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6756A}/[H6754]', 'inflected', 'heb', 'צַלְמוֹן', '["Tsalmôwn"]', '["on/ Zalmon"]', '["n-pr-m n-pr-loc"]', 'Tsalmon, the name of a place in Palestine and of an Israelite Zalmon.', 'from 6754; shady;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1386}/[H1384]', 'lemma', 'heb', 'גַּבְנֹן', '["gabnôn"]', '["peaks"]', '["n-m"]', 'a hump or peak of hills high.', 'from the same as 1384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7520}/H9013/[H7520]', 'inflected', 'heb', 'רָצַד', '["râtsad"]', '["do you watch with envy/ !"]', '["v"]', 'probably to look askant, i.e. (figuratively) be jealous leap.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3427}/H9033/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["to/ dwell in/ he"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8136}/[H8132]', 'lemma', 'heb', 'שִׁנְאָן', '["shinʼân"]', '["repetition[s]"]', '["n-m"]', 'change, i.e. repetition × angels.', 'from 8132;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3444}/H9025/[H3467]', 'inflected', 'heb', 'יְשׁוּעָה', '["yᵉshûwʻâh"]', '["salvation/ our"]', '["n-f"]', 'something saved, i.e. (abstractly) deliverance; hence, aid, victory, prosperity deliverance, health, help(-ing), salvation, save, saving (health), welfare.', 'feminine passive participle of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4190}/[H3467]', 'inflected', 'heb', 'מוֹשָׁעָה', '["môwshâʻâh"]', '["of/ saving acts"]', '["n-f"]', 'deliverance salvation.', 'from 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3069}/[H3068]', 'inflected', 'heb', 'יְהֹוִה', '["Yᵉhôvih"]', '["and/ [belong] to/ Yahweh"]', '["n-pr"]', 'God.', 'a variation of 3068 [used after 136, and pronounced by Jews as 430, in order to prevent the repetition of the same sound, since they elsewhere pronounce 3068 as 136]');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0817}/H9023/[H816]', 'inflected', 'heb', 'אָשָׁם', '["ʼâshâm"]', '["in/ guilt<s>/ his"]', '["n-m"]', 'guilt; by implication, a fault; also a sin-offering guiltiness, (offering for) sin, trespass (offering).', 'from 816;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4688}/[H6683]', 'inflected', 'heb', 'מְצוֹלָה', '["mᵉtsôwlâh"]', '["from/ [the] depths of"]', '["n-f"]', 'a deep place (of water or mud) bottom, deep, depth.', 'or מְצֹלָה; also מְצוּלָה; or מְצֻלָה; from the same as 6683;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3611>/H9021', 'opaque', 'heb', 'כֶּלֶב', '["keleb"]', '["dogs/ your"]', '["n-m"]', 'a dog; hence (by euphemism) a male prostitute dog.', 'from an unused root means. to yelp, or else to attack;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4480B}/H9023/[H4482]', 'inflected', 'heb', 'מִן', '["min"]', '["portion/ its"]', '["prep"]', 'properly, a part of; hence (prepositionally), from or out of in many senses above, after, among, at, because of, by (reason of), from (among), in, × neither, × nor, (out) of, over, since, × then, through, × whether, with.', 'or מִנִּי; or מִנֵּי; (constructive plural) (Isaiah 30:11); for 4482;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1979}/H9021/[H1978]', 'inflected', 'heb', 'הֲלִיכָה', '["hălîykâh"]', '["processions/ your"]', '["n-f"]', 'a walking; by implication, a procession or march, a caravan company, going, walk, way.', 'feminine of 1978;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5959}/[H5958]', 'lemma', 'heb', 'עַלְמָה', '["ʻalmâh"]', '["young women"]', '["n-f"]', 'a lass (as veiled or private) damsel, maid, virgin.', 'feminine of 5958;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8608}/[H8608]', 'lemma', 'heb', 'תָּפַף', '["tâphaph"]', '["playing tambourines"]', '["v"]', 'to drum, i.e. play (as) on the tambourine taber, play with timbrels.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7287A}/H9038/[H7287]', 'inflected', 'heb', 'רָדָה', '["râdâh"]', '["[is] ruling/ them"]', '["v"]', 'to tread down, i.e. subjugate; specifically, to crumble off (come to, make to) have dominion, prevail against, reign, (bear, make to) rule,(-r, over), take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7277}/H9028/[H7276]', 'inflected', 'heb', 'רִגְמָה', '["rigmâh"]', '["heaps of stones/ their"]', '["n-f"]', 'a pile (of stones), i.e. (figuratively) a throng council.', 'feminine of the same as 7276;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5810}/H9012/[H5810]', 'inflected', 'heb', 'עָזַז', '["ʻâzaz"]', '["be strong/ !"]', '["v"]', 'to be stout (literally or figuratively) harden, impudent, prevail, strengthen (self), be strong.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1964G}/H9021/[H3201]', 'inflected', 'heb', 'הֵיכָל', '["hêykâl"]', '["from/ temple/ your"]', '["n-m"]', 'a large public building, such as a palace or temple palace, temple.', 'probably from 3201 (in the sense of capacity);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7862}/[H7737]', 'lemma', 'heb', 'שַׁי', '["shay"]', '["a gift"]', '["n-m"]', 'a gift (as available) present.', 'probably from 7737;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5695}/[H5696]', 'inflected', 'heb', 'עֵגֶל', '["ʻêgel"]', '["with/ calves","with/ calves of"]', '["n-m"]', 'a (male) calf (as frisking round), especially one nearly grown (i.e. a steer) bullock, calf.', 'from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7511}/[H7511]', 'lemma', 'heb', 'רָפַס', '["râphaç"]', '["humble yourself","trampling"]', '["v"]', 'to trample, i.e. prostrate humble self, submit self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7518}/[H7533]', 'inflected', 'heb', 'רַץ', '["rats"]', '["on/ pieces of"]', '["n-m"]', 'a fragment piece.', 'contracted from 7533;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0967}/[H967]', 'lemma', 'heb', 'בָּזַר', '["bâzar"]', '["he has scattered","he will scatter"]', '["v"]', 'to disperse scatter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2831>', 'opaque', 'heb', 'חַשְׁמַן', '["chashman"]', '["envoys"]', '["n-m"]', 'wealthy princes.', 'from an unused root (probably meaning firm or capacious in resources); apparently');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1346}/H9023/[H1342]', 'inflected', 'heb', 'גַּאֲוָה', '["gaʼăvâh"]', '["haughtiness/ its","majesty/ his"]', '["n-f"]', 'arrogance or majesty; by implication, (concretely) ornament excellency, haughtiness, highness, pride, proudly, swelling.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4720}/H9021/[H6942]', 'inflected', 'heb', 'מִקְדָּשׁ', '["miqdâsh"]', '["from/ sanctuari<es>/ your"]', '["n-m"]', 'a consecrated thing or place, especially, a palace, sanctuary (whether of Jehovah or of idols) or asylum chapel, hallowed part, holy place, sanctuary.', 'or מִקְּדָשׁ; (Exodus 15:17), from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8592}/[H6105]', 'inflected', 'heb', 'תַּעֲצֻמָה', '["taʻătsumâh"]', '["and/ power<s>"]', '["n-f"]', 'might (plural collective) power.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315N}/[H5314]', 'lemma', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["[the] neck"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3121}/[H3196]', 'inflected', 'heb', 'יָוֵן', '["yâvên"]', '["in/ mire of"]', '["n-m"]', 'properly, dregs (as effervescing); hence, mud mire, miry.', 'from the same as 3196;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4613}/[H5975]', 'lemma', 'heb', 'מׇעֳמָד', '["moʻŏmâd"]', '["[is] a foothold"]', '["n-m"]', 'literally a foothold standing.', 'from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4615}/[H6009]', 'inflected', 'heb', 'מַעֲמָק', '["maʻămâq"]', '["in/ [the] depths of","in/ depths of"]', '["n-m"]', 'a deep deep, depth.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7641A}/[H7640]', 'inflected', 'heb', 'שִׁבֹּל', '["shibbôl"]', '["and/ a flood"]', '["n-f"]', 'a stream (as flowing); also an ear of grain (as growing out); by analogy, a branch branch, channel, ear (of corn), (water-)flood, Shibboleth. Compare 5451.', 'or (feminine) שִׁבֹּלֶת; from the same as 7640;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7857}/H9030/[H7857]', 'inflected', 'heb', 'שָׁטַף', '["shâṭaph"]', '["it has overflowed/ me","it overflow/ me"]', '["v"]', 'to gush; by implication, to inundate, cleanse; by analogy, to gallop, conquer drown, (over-) flow(-whelm, rinse, run, rush, (throughly) wash (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7121I}/H9040/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["by/ calling out/ my"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1627}/H9020/[H1641]', 'inflected', 'heb', 'גָּרוֹן', '["gârôwn"]', '["throat/ my"]', '["n-m"]', 'the throat (as roughened by swallowing) × aloud, mouth, neck, throat.', 'or (shortened) גָּרֹן; from 1641; (compare 1621)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0430G}/H9020/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["for/ God/ my","to/ God/ my"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6789}/H9030/[H6789]', 'inflected', 'heb', 'צָמַת', '["tsâmath"]', '["[those who] destroy/ me","it has destroyed/ me","they have destroyed/ me"]', '["v"]', 'to extirpate (literally or figuratively) consume, cut off, destroy, vanish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0200}/H9020/[H191]', 'inflected', 'heb', 'אִוֶּלֶת', '["ʼivveleth"]', '["<to>/ folly/ my"]', '["n-f"]', 'silliness folly, foolishly(-ness).', 'from the same as 191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0819}/H9020/[H817]', 'inflected', 'heb', 'אַשְׁמָה', '["ʼashmâh"]', '["and/ guilt<s>/ my"]', '["n-f"]', 'guiltiness, a fault, the presentation of a sin-offering offend, sin, (cause of) trespass(-ing, offering).', 'feminine of 817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3639}/[H3637]', 'lemma', 'heb', 'כְּלִמָּה', '["kᵉlimmâh"]', '["[the] insult of","[the] insult[s] of","ignomini[es]","ignominy","ignominy of"]', '["n-f"]', 'disgrace confusion, dishonour, reproach, shame.', 'from 3637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5237}/[H5235]', 'inflected', 'heb', 'נׇכְרִי', '["nokrîy"]', '["and/ a foreigner","and/ foreigners"]', '["a"]', 'strange, in a variety of degrees and applications (foreign, non-relative, adulterous, different, wonderful) alien, foreigner, outlandish, strange(-r, woman).', 'from 5235 (second form);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004Q}/H9021/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["house/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2778A}/H9031/[H2779]', 'inflected', 'heb', 'חָרַף', '["châraph"]', '["[those who] reproach/ you","they reproached/ you"]', '["v"]', 'to pull off, i.e. (by implication) to expose (as by stripping); specifically, to betroth (as if a surrender); figuratively, to carp at, i.e. defame; to spend the winter betroth, blaspheme, defy, jeopard, rail, reproach, upbraid.', 'a primitive root; also denominative (from 2779)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2781}/[H2778]', 'inflected', 'heb', 'חֶרְפָּה', '["cherpâh"]', '["<into>/ a reproach","<into>/ reproach<es>","[have become] <into>/ a reproach","into/ a reproach","to/ reproaches"]', '["n-f"]', 'contumely, disgrace, the pudenda rebuke, reproach(-fully), shame.', 'from 2778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414I}/H9012/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I made/ !"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5058}/[H5059]', 'inflected', 'heb', 'נְגִינָה', '["nᵉgîynâh"]', '["and/ taunt songs of"]', '["n-f"]', 'properly, instrumental music; by implication, a stringed instrument; by extension, a poem set to music; specifically, an epigram stringed instrument, musick, Neginoth (plural), song.', 'or נְגִינַת; (Psalm 61:title), from 5059;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4615}/[H6009]', 'inflected', 'heb', 'מַעֲמָק', '["maʻămâq"]', '["and/ from/ depths of"]', '["n-m"]', 'a deep deep, depth.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7641A}/[H7640]', 'lemma', 'heb', 'שִׁבֹּל', '["shibbôl"]', '["a flood of"]', '["n-f"]', 'a stream (as flowing); also an ear of grain (as growing out); by analogy, a branch branch, channel, ear (of corn), (water-)flood, Shibboleth. Compare 5451.', 'or (feminine) שִׁבֹּלֶת; from the same as 7640;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1104}/H9030/[H1104]', 'inflected', 'heb', 'בָּלַע', '["bâlaʻ"]', '["he swallowed/ me","it swallow up/ me"]', '["v"]', 'to make away with (specifically by swallowing); generally, to destroy cover, destroy, devour, eat up, be at end, spend up, swallow down (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0332}/[H332]', 'lemma', 'heb', 'אָטַר', '["ʼâṭar"]', '["it close"]', '["v"]', 'to close up shut.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7126G}/H9012/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["draw near/ !"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1322}/H9020/[H954]', 'inflected', 'heb', 'בֹּשֶׁת', '["bôsheth"]', '["and/ shame/ my"]', '["n-f"]', 'shame (the feeling and the condition, as well as its cause); by implication (specifically) an idol ashamed, confusion, greatly, (put to) shame(-ful thing).', 'from 954;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3639}/H9020/[H3637]', 'inflected', 'heb', 'כְּלִמָּה', '["kᵉlimmâh"]', '["and/ ignominy/ my"]', '["n-f"]', 'disgrace confusion, dishonour, reproach, shame.', 'from 3637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5136}/H9012/[H5136]', 'inflected', 'heb', 'נוּשׁ', '["nûwsh"]', '["and/ I have become sick/ !"]', '["v"]', 'to be sick, i.e. (figuratively) distressed be full of heaviness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6960A}/[H6960]', 'inflected', 'heb', 'קָוָה', '["qâvâh"]', '["and/ I waited","and/ I will wait eagerly","and/ he waited","and/ you will wait"]', '["v"]', 'to bind together (perhaps by twisting), i.e. collect; (figuratively) to expect gather (together), look, patiently, tarry, wait (for, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5162G}/[H5162]', 'inflected', 'heb', 'נָחַם', '["nâcham"]', '["and/ for <the>/ comforters"]', '["v"]', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1267}/H9020/[H1262]', 'inflected', 'heb', 'בָּרוּת', '["bârûwth"]', '["in/ food/ my"]', '["n-f"]', 'food meat.', 'from 1262;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6772}/H9020/[H6770]', 'inflected', 'heb', 'צָמָא', '["tsâmâʼ"]', '["and/ for/ thirst/ my"]', '["n-m"]', 'thirst (literally or figuratively) thirst(-y).', 'from 6770;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7979}/H9028/[H7971]', 'inflected', 'heb', 'שֻׁלְחָן', '["shulchân"]', '["table/ their"]', '["n-m"]', 'a table (as spread out); by implication, a meal table.', 'from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4975>/H9028', 'inflected', 'heb', 'ומתניהם', '["u./ma.te.Nei./hem"]', '["and/ loins/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2491H}/H9021/[H2490]', 'inflected', 'heb', 'חָלָל', '["châlâl"]', '["fatally wounded [ones]/ your"]', '["n-m"]', 'pierced (especially to death); figuratively, polluted kill, profane, slain (man), × slew, (deadly) wounded.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5771I}/H9028/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["iniquity/ their"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5612H}/[H9]', 'inflected', 'heb', 'סֵפֶר', '["çêpher"]', '["from/ [the] scroll of"]', '["n-m"]', 'properly, writing (the art or a document); by implication, a book bill, book, evidence, × learn(-ed) (-ing), letter, register, scroll.', 'or (feminine) סִפְרָה; (Psalm 56:8 (9)), from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3510}/[H3510]', 'inflected', 'heb', 'כָּאַב', '["kâʼab"]', '["and/ [am] in pain"]', '["v"]', 'properly, to feel pain; by implication, to grieve; figuratively, to spoil grieving, mar, have pain, make sad (sore), (be) sorrowful.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1431}/H9033/[H1434]', 'inflected', 'heb', 'גָּדַל', '["gâdal"]', '["and/ I will magnify/ him"]', '["v"]', 'to be (causatively make) large (in various senses, as in body, mind, estate or honor, also in pride) advance, boast, bring up, exceed, excellent, be(-come, do, give, make, wax), great(-er, come to... estate, things), grow(up), increase, lift up, magnify(-ifical), be much set by, nourish (up), pass, promote, proudly (spoken), tower.', 'a primitive root; properly, to twist (compare 1434), i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8426}/[H3034]', 'inflected', 'heb', 'תּוֹדָה', '["tôwdâh"]', '["with/ thanksgiving"]', '["n-f"]', 'properly, an extension of the hand, i.e. (by implication) avowal, or (usually) adoration; specifically, a choir of worshippers confession, (sacrifice of) praise, thanks(-giving, offering).', 'from 3034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0615}/H9023/[H631]', 'inflected', 'heb', 'אָסִיר', '["ʼâçîyr"]', '["prisoners/ his"]', '["n-m"]', 'bound, i.e. a captive (those which are) bound, prisoner.', 'from 631;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5828}/H9020/[H5826]', 'inflected', 'heb', 'עֵזֶר', '["ʻêzer"]', '["[are] help/ my","help/ my"]', '["n-m"]', 'aid help.', 'from 5826;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5765}/[H5765]', 'lemma', 'heb', 'עֲוַל', '["ʻăval"]', '["[the] wrongdoer","he acts unjustly"]', '["v"]', 'to distort (morally) deal unjustly, unrighteous.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2556C}/[H2556]', 'inflected', 'heb', 'חָמֵץ', '["châmêts"]', '["and/ [the] ruthless"]', '["v"]', 'to be pungent; i.e. in taste (sour, i.e. literally fermented, or figuratively, harsh), in color (dazzling) cruel (man), dyed, be grieved, leavened.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H4578>', 'inflected', 'heb', 'ממעי', '["mi./me.''Ei"]', '["from/ [the] inward parts of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1491}/H9030/[H1468]', 'inflected', 'heb', 'גָּזָה', '["gâzâh"]', '["[were [the] one who] cut off/ me"]', '["v"]', 'to cut off, i.e. portion out take.', 'a primitive root (akin to 1468);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3615J}/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["when/ fails"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8610}/H9033/[H8610]', 'inflected', 'heb', 'תָּפַשׂ', '["tâphas"]', '["and/ seize/ him"]', '["v"]', 'to manipulate, i.e. seize; chiefly to capture, wield, specifically, to overlay; figuratively, to use unwarrantably catch, handle, (lay, take) hold (on, over), stop, × surely, surprise, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7853}/[H7853]', 'lemma', 'heb', 'שָׂטַן', '["sâṭan"]', '["[the] accusers of"]', '["v"]', 'to attack, (figuratively) accuse (be an) adversary, resist.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5615}/[H5608]', 'lemma', 'heb', 'סְפֹרָה', '["çᵉphôrâh"]', '["numbers"]', '["n-f"]', 'a numeration number.', 'from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7872}/[H7869]', 'inflected', 'heb', 'שֵׂיבָה', '["sêybâh"]', '["and/ grey hair"]', '["n-f"]', 'old age (be) gray (grey hoar,-y) hairs (head,-ed), old age.', 'feminine of 7869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5927H}/H9030/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["you lift up/ me","you will bring up/ me"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1420}/H9020/[H1419]', 'inflected', 'heb', 'גְּדוּלָה', '["gᵉdûwlâh"]', '["greatness/ my"]', '["n-f"]', 'greatness; (concretely) mighty acts dignity, great things(-ness), majesty.', 'or גְּדֻלָּה; (shortened) or (less accurately) גְּדוּלָּה; feminine of 1419;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4941H}/H9021/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["judgments/ your"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6041}/H9021/[H6031]', 'inflected', 'heb', 'עָנִי', '["ʻânîy"]', '["and/ poor [people]/ your"]', '["a"]', 'depressed, in mind or circumstances afflicted, humble, lowly, needy, poor.', 'from 6031; (practically the same as 6035, although the margin constantly disputes this, making 6035 subjective and objective);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1389I}/[H1387]', 'inflected', 'heb', 'גִּבְעָה', '["gibʻâh"]', '["and/ hill","and/ hills"]', '["n-f"]', 'a hillock hill, little hill.', 'feminine from the same as 1387;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6666}/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["by/ righteousness","in/ righteousness","with/ righteousness"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6440H}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["and/ <to>/ before"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7241}/[H7231]', 'inflected', 'heb', 'רָבִיב', '["râbîyb"]', '["like/ copious showers"]', '["n-m"]', 'a rain (as an accumulation of drops) shower.', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2222B>', 'opaque', 'heb', 'זַרְזִיף', '["zarzîyph"]', '["dropping of"]', '["v n-m"]', 'a pouring rain water.', 'by reduplication from an unused root meaning to flow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5104G}/[H5102]', 'inflected', 'heb', 'נָהָר', '["nâhâr"]', '["and/ from/ [the] river"]', '["n-m"]', 'a stream (including the sea; expectation the Nile, Euphrates, etc.); figuratively, prosperity flood, river.', 'from 5102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6728}/[H6723]', 'lemma', 'heb', 'צִיִּי', '["tsîyîy"]', '["desert-dwellers"]', '["n-m"]', 'a desert-dweller, i.e. nomad or wild beast wild beast of the desert, that dwell in (inhabiting) the wilderness.', 'from the same as 6723;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0341}/H9023/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["and/ enemies/ his"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5434H>', 'inflected', 'heb', 'וסבא', '["u./se.Va''"]', '["and/ Seba"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0814}/[H7939]', 'lemma', 'heb', 'אֶשְׁכָּר', '["ʼeshkâr"]', '["a gift"]', '["n-m"]', 'a gratuity gift, present.', 'for 7939;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8496}/[H8432]', 'inflected', 'heb', 'תֹּךְ', '["tôk"]', '["from/ oppression"]', '["n-m"]', 'oppression deceit, fraud.', 'or תּוֹך; (Psalm 72:14), from the same base as 8432 (in the sense of cutting to pieces);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H2555}/[H2554]', 'inflected', 'heb', 'חָמָס', '["châmâç"]', '["and/ from/ violence"]', '["n-m"]', 'violence; by implication, wrong; by metonymy unjust gain cruel(-ty), damage, false, injustice, × oppressor, unrighteous, violence (against, done), violent (dealing), wrong.', 'from 2554;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6451}/[H6461]', 'lemma', 'heb', 'פִּסָּה', '["piççâh"]', '["an abundance of"]', '["n-f"]', 'expansion, i.e. abundance handful.', 'from 6461;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3844G}/[H3825]', 'inflected', 'heb', 'לְבָנוֹן', '["Lᵉbânôwn"]', '["[is] like <the>/ Lebanon","like <the>/ Lebanon"]', '["n-pr-loc"]', 'Lebanon, a mountain range in Palestine Lebanon.', 'from 3825; (the) white mountain (from its snow);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6692A}/[H6692]', 'inflected', 'heb', 'צוּץ', '["tsûwts"]', '["and/ may people blossom"]', '["v"]', 'to twinkle, i.e. glance; by analogy, to blossom (figuratively, flourish) bloom, blossom, flourish, shew self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5125}/[H5125]', 'lemma', 'heb', 'נוּן', '["nûwn"]', '["may it increase"]', '["v"]', 'to resprout, i.e. propagate by shoots; figuratively, to be perpetual be continued.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0833}/H9033/[H833]', 'inflected', 'heb', 'אָשַׁר', '["ʼâshar"]', '["may they call blessed/ him"]', '["v"]', 'to be straight (used in the widest sense, especially to be level, right, happy); figuratively, to go forward, be honest, prosper (call, be) bless(-ed, happy), go, guide, lead, relieve.', 'or אָשֵׁר; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1249}/[H1305]', 'inflected', 'heb', 'בַּר', '["bar"]', '["to/ [people] pure of"]', '["a"]', 'beloved; also pure, empty choice, clean, clear, pure.', 'from 1305 (in its various senses);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8210J}/[H8210]', 'lemma', 'heb', 'שָׁפַךְ', '["shâphak"]', '["they had been poured out","they lie scattered"]', '["v"]', 'to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1984C}/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["of the/ boasters"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2784>', 'opaque', 'heb', 'חַרְצֻבָּה', '["chartsubbâh"]', '["[are] pangs","[the] bonds of"]', '["n-f"]', 'a fetter; figuratively, a pain band.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4194}/H9028/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["to/ death/ their"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0193A>/H9028', 'opaque', 'heb', 'אוּל', '["ʼûwl"]', '["body/ their"]', '["n-m"]', 'the body (as being rolled together); also powerful mighty, strength.', 'from an unused root meaning to twist, i.e. (by implication) be strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6059}/H9038/[H6060]', 'inflected', 'heb', 'עָנַק', '["ʻânaq"]', '["[it is] a necklace/ [for] them"]', '["v"]', 'to collar, i.e. adorn with a necklace; figuratively, to fit out with supplies compass about as a chain, furnish, liberally.', 'a primitive root; properly, to choke; used only as denominative from 6060,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7897}/[H7896]', 'lemma', 'heb', 'שִׁית', '["shîyth"]', '["[the] garment of","a garment of"]', '["n-m"]', 'a dress (as put on) attire.', 'from 7896;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4167}/[H4167]', 'lemma', 'heb', 'מוּק', '["mûwq"]', '["they mock"]', '["v"]', 'to jeer, i.e. (intens.) blaspheme be corrupt.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6233}/[H6231]', 'lemma', 'heb', 'עֹשֶׁק', '["ʻôsheq"]', '["[is] oppression","extortion","oppression","oppression of"]', '["n-m"]', 'injury, fraud, (subjectively) distress, (concretely) unjust gain cruelly, extortion, oppression, thing (deceitfully gotten).', 'from 6231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5945B}/[H5927]', 'inflected', 'heb', 'עֶלְיוֹן', '["ʻelyôwn"]', '["with/ [the] Most High"]', '["n-m a"]', 'an elevation, i.e. (adj.) lofty (compar.); as title, the Supreme (Most, on) high(-er, -est), upper(-most).', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8433B}/H9020/[H3198]', 'inflected', 'heb', 'תּוֹכֵחָה', '["tôwkêchâh"]', '["and/ rebuke/ my"]', '["n-f"]', 'chastisement; figuratively (by words) correction, refutation, proof (even in defence) argument, × chastened, correction, reasoning, rebuke, reproof, × be (often) reproved.', 'and תּוֹכַחַת; from 3198;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2803J}/H9012/[H2803]', 'inflected', 'heb', 'חָשַׁב', '["châshab"]', '["and/ I thought/ !"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2513B}/[H2506]', 'inflected', 'heb', 'חֶלְקָה', '["chelqâh"]', '["on/ slippery [places]"]', '["n-f"]', 'properly, smoothness; figuratively, flattery; also an allotment field, flattering(-ry), ground, parcel, part, piece of land (ground), plat, portion, slippery place, smooth (thing).', 'feminine of 2506;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5307G}/H9038/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["let someone make fall/ them","you make fall/ them"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4876}/[H4875]', 'inflected', 'heb', 'מַשּׁוּאָה', '["mashshûwʼâh"]', '["to/ [the] ruins of","to/ deceptions"]', '["n-f"]', 'ruin desolation, destruction.', 'or מַשֻּׁאָה; for 4875;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6974}/[H3364]', 'inflected', 'heb', 'קוּץ', '["qûwts"]', '["from/ when awakes"]', '["v"]', 'to awake (literally or figuratively) arise, (be) (a-) wake, watch.', 'a primitive root (identical with through the idea of abruptness in starting up from sleep (compare 3364));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5782}/[H5782]', 'inflected', 'heb', 'עוּר', '["ʻûwr"]', '["when/ waken"]', '["v"]', 'to wake (literally or figuratively) (a-) wake(-n, up), lift up (self), × master, raise (up), stir up (self).', 'a primitive root (rather identical with through the idea of opening the eyes);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6754>/H9028', 'opaque', 'heb', 'צֶלֶם', '["tselem"]', '["image/ their"]', '["n-m"]', 'a phantom, i.e. (figuratively) illusion, resemblance; hence, a representative figure, especially an idol image, vain shew.', 'from an unused root meaning to shade;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3629}/H9020/[H3627]', 'inflected', 'heb', 'כִּלְיָה', '["kilyâh"]', '["and/ kidneys/ my"]', '["n-f"]', 'a kidney (as an essential organ); figuratively, the mind (as the interior self) kidneys, reins.', 'feminine of 3627 (only in the plural);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1198}/[H1197]', 'lemma', 'heb', 'בַּעַר', '["baʻar"]', '["[am] stupid","[is] stupid","[was] stupid","stupid"]', '["n-m"]', 'properly, foot (as consumed); i.e. (by exten.) of cattle brutishness; (concretely) stupid brutish (person), foolish.', 'from 1197;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3225G}/H9020/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["right [hand]/ my","right/ my"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6098}/H9021/[H3289]', 'inflected', 'heb', 'עֵצָה', '["ʻêtsâh"]', '["with/ counsel/ your"]', '["n-f"]', 'advice; by implication, plan; also prudence advice, advisement, counsel([-lor]), purpose.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7607}/H9020/[H7604]', 'inflected', 'heb', 'שְׁאֵר', '["shᵉʼêr"]', '["flesh/ my"]', '["n-m"]', 'flesh (as swelling out), as living or for food; generally food of any kind; figuratively, kindred by blood body, flesh, food, (near) kin(-sman, -swoman), near (nigh) (of kin).', 'from 7604;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3824}/H9020/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["and/ heart/ my"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2506A}/H9020/[H2505]', 'inflected', 'heb', 'חֵלֶק', '["chêleq"]', '["and/ portion/ my"]', '["n-m"]', 'properly, smoothness (of the tongue); also an allotment flattery, inheritance, part, × partake, portion.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7369}/H9021/[H7368]', 'inflected', 'heb', 'רָחֵק', '["râchêq"]', '["[people] far from/ you"]', '["a"]', 'remote that are far.', 'from 7368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7132}/[H7126]', 'lemma', 'heb', 'קְרָבָה', '["qᵉrâbâh"]', '["[the] approach of"]', '["n-f"]', 'approach approaching, draw near.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0136}/[H113]', 'inflected', 'heb', 'אֲדֹנָי', '["ʼĂdônây"]', '["in/ [the] Lord"]', '["n-m"]', 'the Lord (used as a proper name of God only) (my) Lord.', 'an emphatic form of 113;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4830}/H9021/[H7462]', 'inflected', 'heb', 'מִרְעִית', '["mirʻîyth"]', '["pasture/ your"]', '["n-f"]', 'pasturage; concretely, a flock flock, pasture.', 'from 7462 in the sense of feeding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6471}/H9021/[H6470]', 'inflected', 'heb', 'פַּעַם', '["paʻam"]', '["footsteps/ your"]', '["n-f"]', 'a stroke, literally or figuratively (in various applications, as follow) anvil, corner, foot(-step), going, (hundred-) fold, × now, (this) once, order, rank, step, thrice, (often-), second, this, two) time(-s), twice, wheel.', 'or (feminine) פַּעֲמָה; from 6470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4150I}/H9021/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["appointed place/ your"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0226H}/H9028/[H225]', 'inflected', 'heb', 'אוֹת', '["ʼôwth"]', '["signs/ their"]', '["n-f"]', 'a signal (literally or figuratively), as a flag, beacon, monument, omen, prodigy, evidence, etc. mark, miracle, (en-) sign, token.', 'probably from 225 (in the sense of appearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0935P}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["like/ [one who] brings"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7134}/[H6923]', 'lemma', 'heb', 'קַרְדֹּם', '["qardôm"]', '["axes"]', '["n-m"]', 'an axe ax.', 'perhaps from 6923 in the sense of striking upon;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6603}/H9024/[H6605]', 'inflected', 'heb', 'פִּתּוּחַ', '["pittûwach"]', '["engraving/ its","engravings/ its"]', '["n-m"]', 'sculpture (in low or high relief or even intaglio) carved (work) (are, en-) grave(-ing, -n).', 'or פִּתֻּחַ ; passive participle of 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3781}/[H3782]', 'inflected', 'heb', 'כַּשִּׁיל', '["kashshîyl"]', '["with/ axe[s]"]', '["n-m"]', 'properly, a feller, i.e. an axe ax.', 'from 3782;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3597>', 'inflected', 'heb', 'וכילפת', '["ve./khei.la.Pot"]', '["and/ crowbars"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1986}/H9013/[H1986]', 'inflected', 'heb', 'הָלַם', '["hâlam"]', '["they struck/ !"]', '["v"]', 'to strike down; by implication, to hammer, stamp, conquer, disband beat (down), break (down), overcome, smite (with the hammer).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4720}/H9021/[H6942]', 'inflected', 'heb', 'מִקְדָּשׁ', '["miqdâsh"]', '["sanctuaries/ your","sanctuary/ your"]', '["n-m"]', 'a consecrated thing or place, especially, a palace, sanctuary (whether of Jehovah or of idols) or asylum chapel, hallowed part, holy place, sanctuary.', 'or מִקְּדָשׁ; (Exodus 15:17), from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3238}/H9038/[H3238]', 'inflected', 'heb', 'יָנָה', '["yânâh"]', '["let us oppress/ them"]', '["v"]', 'to rage or be violent; by implication, to suppress, to maltreat destroy, (thrust out by) oppress(-ing, -ion, -or), proud, vex, do violence.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0226G}/H9025/[H225]', 'inflected', 'heb', 'אוֹת', '["ʼôwth"]', '["signs/ our"]', '["n-f"]', 'a signal (literally or figuratively), as a flag, beacon, monument, omen, prodigy, evidence, etc. mark, miracle, (en-) sign, token.', 'probably from 225 (in the sense of appearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6565B}/[H6565]', 'lemma', 'heb', 'פָּרַר', '["pârar"]', '["it has been split through","utterly <split>","you divided"]', '["v"]', 'to break up (usually figuratively), i.e. to violate, frustrate × any ways, break (asunder), cast off, cause to cease, × clean, defeat, disannul, disappoint, dissolve, divide, make of none effect, fail, frustrate, bring (come) to nought, × utterly, make void.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5971L}/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["to/ a people"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6728}/[H6723]', 'inflected', 'heb', 'צִיִּי', '["tsîyîy"]', '["to/ desert-dwellers"]', '["n-m"]', 'a desert-dweller, i.e. nomad or wild beast wild beast of the desert, that dwell in (inhabiting) the wilderness.', 'from the same as 6723;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H8121>', 'inflected', 'heb', 'ושמש', '["va./Sha.mesh"]', '["and/ [the] sun","and/ sun"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3335G}/H9038/[H3334]', 'inflected', 'heb', 'יָצַר', '["yâtsar"]', '["you formed/ them"]', '["v"]', 'to mould into a form; especially as a potter; figuratively, to determine (i.e. form a resolution) × earthen, fashion, form, frame, make(-r), potter, purpose.', 'probably identical with 3334 (through the squeezing into shape); (compare 3331);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2416C}/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["for <the>/ animal[s]","to the/ animal[s]","to/ [the] animal[s] of","to/ an animal"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8449}/H9021/[H8447]', 'inflected', 'heb', 'תּוֹר', '["tôwr"]', '["turtle-dove/ your"]', '["n-f"]', 'a ring-dove, often (figuratively) as a term of endearment (turtle) dove.', 'or תֹּר; probably the same as 8447;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2416D}/[H2421]', 'lemma', 'heb', 'חַי', '["chay"]', '["[the] life of"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6041}/H9021/[H6031]', 'inflected', 'heb', 'עָנִי', '["ʻânîy"]', '["poor [people]/ your"]', '["a"]', 'depressed, in mind or circumstances afflicted, humble, lowly, needy, poor.', 'from 6031; (practically the same as 6035, although the margin constantly disputes this, making 6035 subjective and objective);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4285}/[H2821]', 'lemma', 'heb', 'מַחְשָׁךְ', '["machshâk"]', '["[the] dark place","[the] dark places of","darkness"]', '["n-m"]', 'darkness; concretely, a dark place dark(-ness, place).', 'from 2821;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1790>', 'opaque', 'heb', 'דַּךְ', '["dak"]', '["[the] oppressed"]', '["a"]', 'crushed, i.e. (figuratively) injured afflicted, oppressed.', 'from an unused root (compare 1794);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7379}/H9021/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["case/ your","own case/ your","strife/ your"]', '["n-m"]', 'a contest (personal or legal) adversary, cause, chiding, contend(-tion), controversy, multitude (from the margin), pleading, strife, strive(-ing), suit.', 'or רִב; from 7378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2781}/H9021/[H2778]', 'inflected', 'heb', 'חֶרְפָּה', '["cherpâh"]', '["reproach/ your"]', '["n-f"]', 'contumely, disgrace, the pudenda rebuke, reproach(-fully), shame.', 'from 2778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7138}/[H7126]', 'inflected', 'heb', 'קָרוֹב', '["qârôwb"]', '["and/ [is] near"]', '["a"]', 'near (in place, kindred or time) allied, approach, at hand, any of kin, kinsfold(-sman), (that is) near (of kin), neighbour, (that is) next, (them that come) nigh (at hand), more ready, short(-ly).', 'or קָרֹב; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1984C}/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["to the/ boasters"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7161A}/H9026/[H7160]', 'inflected', 'heb', 'קֶרֶן', '["qeren"]', '["horn/ your"]', '["n-f n-pr-loc"]', 'a horn (as projecting); by implication, a flask, cornet; by resemblance. an elephant''s tooth (i.e. ivory), a corner (of the altar), a peak (of a mountain), a ray (of light); figuratively, power × hill, horn.', 'from 7160;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4161}/[H3318]', 'inflected', 'heb', 'מוֹצָא', '["môwtsâʼ"]', '["[is] from/ [the] going out"]', '["n-m"]', 'a going forth, i.e. (the act) an egress, or (the place) an exit; hence, a source or product; specifically, dawn, the rising of the sun (the East), exportation, utterance, a gate, a fountain, a mine, a meadow (as producing grass) brought out, bud, that which came out, east, going forth, goings out, that which (thing that) is gone out, outgoing, proceeded out, spring, vein, (water-) course (springs).', 'or מֹצָאxlit môtsâ corrected to môtsâʼ; from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4628}/[H6150]', 'inflected', 'heb', 'מַעֲרָב', '["maʻărâb"]', '["and/ from/ [the] setting place","and/ from/ [the] west","and/ from/ west"]', '["n-m"]', 'the west (as a region of the evening sun) west.', 'or (feminine) מַעֲרָבָה; from 6150, in the sense of shading;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4538}/[H4537]', 'lemma', 'heb', 'מֶסֶךְ', '["meçek"]', '["spiced drink"]', '["n-m"]', 'a mixture, i.e. of wine with spices mixture.', 'from 4537;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5064}/[H5064]', 'inflected', 'heb', 'נָגַר', '["nâgar"]', '["and/ I will pour down","and/ he has poured out","and/ you poured"]', '["v"]', 'to flow; figuratively, to stretch out; causatively, to pour out or down; figuratively, to deliver over fall, flow away, pour down (out), run, shed, spilt, trickle down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8105}/H9024/[H8104]', 'inflected', 'heb', 'שֶׁמֶר', '["shemer"]', '["dregs/ its"]', '["n-m"]', 'something preserved, i.e. the settlings (plural only) of wine dregs, (wines on the) lees.', 'from 8104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8004}/[H8003]', 'inflected', 'heb', 'שָׁלֵם', '["Shâlêm"]', '["in/ Salem"]', '["n-pr-loc"]', 'Shalem, an early name of Jerusalem Salem.', 'the same as 8003; peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5520}/H9023/[H5526]', 'inflected', 'heb', 'סֹךְ', '["çôk"]', '["lair/ his"]', '["n-m"]', 'a hut (as of entwined boughs); also a lair covert, den, pavilion, tabernacle.', 'from 5526;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4585}/H9023/[H4583]', 'inflected', 'heb', 'מְעוֹנָה', '["mᵉʻôwnâh"]', '["and/ den/ his"]', '["n-f"]', 'den, habitation, (dwelling) place, refuge.', 'or מְעֹנָה; feminine of 4583, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7997B}/[H7997]', 'lemma', 'heb', 'שָׁלַל', '["shâlal"]', '["[was] plundered","they were plundered","you have plundered"]', '["v"]', 'to drop or strip; by implication, to plunder let fall, make self a prey, × of purpose, (make a, (take)) spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5123}/[H5123]', 'lemma', 'heb', 'נוּם', '["nûwm"]', '["anyone will slumber","he slumber","he will slumber","they slumbered"]', '["v"]', 'to slumber (from drowsiness) sleep, slumber.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8142}/H9028/[H3462]', 'inflected', 'heb', 'שֵׁנָה', '["shênâh"]', '["sleep/ their"]', '["n-f"]', 'sleep sleep.', 'or שֵׁנָא; (Psalm 127:2), from 3462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6965B}/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["when/ arise","when/ arose"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4172A}/[H3372]', 'inflected', 'heb', 'מוֹרָא', '["môwrâʼ"]', '["to the/ awesome one"]', '["n-m"]', 'fear; by implication, a fearful thing or deed dread, (that ought to be) fear(-ed), terribleness, terror.', 'or מֹרָא; or מוֹרָהxlit môrâh corrected to môwrâh; (Psalm 9:20), from 3372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6817}/[H6817]', 'inflected', 'heb', 'צָעַק', '["tsâʻaq"]', '["and/ I will cry out","and/ cry out"]', '["v"]', 'to shriek; (by implication) to proclaim (an assembly) × at all, call together, cry (out), gather (selves) (together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5848C}/[H5848]', 'inflected', 'heb', 'עָטַף', '["ʻâṭaph"]', '["for/ it may faint away"]', '["v"]', 'to shroud, i.e. clothe (whether transitive or reflex.); hence (from the idea of darkness) to languish cover (over), fail, faint, feebler, hide self, be overwhelmed, swoon.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8109}/[H8104]', 'lemma', 'heb', 'שְׁמֻרָה', '["shᵉmurâh"]', '["[the] eyelids of"]', '["n-f"]', 'something guarded, i.e. an eye-lid waking.', 'feminine of passive participle of 8104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6470}/[H6470]', 'lemma', 'heb', 'פָּעַם', '["pâʻam"]', '["I was troubled"]', '["v"]', 'to tap, i.e. beat regularly; hence (generally) to impel or agitate move, trouble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5058}/H9020/[H5059]', 'inflected', 'heb', 'נְגִינָה', '["nᵉgîynâh"]', '["song/ my"]', '["n-f"]', 'properly, instrumental music; by implication, a stringed instrument; by extension, a poem set to music; specifically, an epigram stringed instrument, musick, Neginoth (plural), song.', 'or נְגִינַת; (Psalm 61:title), from 5059;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9005/{H5769G}/[H5956]', 'inflected', 'heb', 'עוֹלָם', '["ʻôwlâm"]', '["¿/ to/ forever"]', '["n-m"]', 'properly, concealed, i.e. the vanishing point; generally, time out of mind (past or future), i.e. (practically) eternity; frequentatively, adverbial (especially with prepositional prefix) always alway(-s), ancient (time), any more, continuance, eternal, (for, (n-)) ever(-lasting, -more, of old), lasting, long (time), (of) old (time), perpetual, at any time, (beginning of the) world ( without end). Compare 5331, 5703.', 'or עֹלָם; from 5956;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7521}/[H7521]', 'inflected', 'heb', 'רָצָה', '["râtsâh"]', '["to/ show favor"]', '["v"]', 'to be pleased with; specifically, to satisfy a debt (be) accept(-able), accomplish, set affection, approve, consent with, delight (self), enjoy, (be, have a) favour(-able), like, observe, pardon, (be, have, take) please(-ure), reconcile self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0656}/[H656]', 'inflected', 'heb', 'אָפֵס', '["ʼâphêç"]', '["¿/ has it come to an end"]', '["v"]', 'to disappear, i.e. cease be clean gone (at an end, brought to nought), fail.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7911}/[H7911]', 'inflected', 'heb', 'שָׁכַח', '["shâkach"]', '["¿/ has he forgotten","¿/ have you forgotten","¿/ will she forget"]', '["v"]', 'to mislay, i.e. to be oblivious of, from want of memory or attention × at all, (cause to) forget.', 'or שָׁכֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2470I}/H9040/[H2342]', 'inflected', 'heb', 'חָלָה', '["châlâh"]', '["[is] wounding/ my"]', '["v"]', 'properly, to be rubbed or worn; hence (figuratively) to be weak, sick, afflicted; or (causatively) to grieve, make sick; also to stroke (in flattering), entreat beseech, (be) diseased, (put to) grief, be grieved, (be) grievous, infirmity, intreat, lay to, put to pain, × pray, make prayer, be (fall, make) sick, sore, be sorry, make suit (× supplication), woman in travail, be (become) weak, be wounded.', 'a primitive root (compare 2342, 2470, 2490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6382}/H9021/[H6381]', 'inflected', 'heb', 'פֶּלֶא', '["peleʼ"]', '["wonder[s]/ your"]', '["n-m"]', 'a miracle marvellous thing, wonder(-ful, -fully).', 'from 6381;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6467}/H9021/[H6466]', 'inflected', 'heb', 'פֹּעַל', '["pôʻal"]', '["deed/ your","deed[s]/ your","work/ your"]', '["n-m"]', 'an act or work (concretely) act, deed, do, getting, maker, work.', 'from 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5949}/H9021/[H5953]', 'inflected', 'heb', 'עֲלִילָה', '["ʻălîylâh"]', '["and/ on/ deeds/ your"]', '["n-f"]', 'an exploit (of God), or a performance (of man, often in a bad sense); by implication, an opportunity act(-ion), deed, doing, invention, occasion, work.', 'or עֲלִלָה; from 5953 in the sense of effecting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2229}/[H2229]', 'lemma', 'heb', 'זָרַם', '["zâram"]', '["they poured forth"]', '["v"]', 'to gush (as water) carry away as with a flood, pour out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7482}/H9021/[H7481]', 'inflected', 'heb', 'רַעַם', '["raʻam"]', '["thunder/ your"]', '["n-m"]', 'a peal of thunder thunder.', 'from 7481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1534}/[H1556]', 'inflected', 'heb', 'גַּלְגַּל', '["galgal"]', '["[was] in the/ whirlwind"]', '["n-m"]', 'a wheel; by analogy, a whirlwind; also dust (as whirled) heaven, rolling thing, wheel.', 'by reduplication from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7635}/H9021/[H7640]', 'inflected', 'heb', 'שָׁבִיל', '["shâbîyl"]', '["and/ path/ your"]', '["n-m"]', 'a track or passage-way (as if flowing along) path.', 'from the same as 7640;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6119}/H9021/[H6117]', 'inflected', 'heb', 'עָקֵב', '["ʻâqêb"]', '["and/ footprints/ your"]', '["n-m"]', 'a heel (as protuberant); hence, a track; figuratively, the rear (of an army) heel, (horse-) hoof, last, lier in wait (by mistake for 6120), (foot-) step.', 'or (feminine) עִקְּבָה; from 6117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8451}/H9020/[H3384]', 'inflected', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["[which] law/ my","instruction/ my","law/ my","laws/ my"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0241G}/H9026/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["ear/ your"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4912}/[H4910]', 'inflected', 'heb', 'מָשָׁל', '["mâshâl"]', '["in/ a parable"]', '["n-m"]', 'properly, a pithy maxim, usually of metaphorical nature; hence, a simile (as an adage, poem, discourse) byword, like, parable, proverb.', 'apparently from 4910 in some original sense of superiority in mental action;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1121A}/H9028/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["from/ descendants/ their"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5807}/H9023/[H5810]', 'inflected', 'heb', 'עֱזוּז', '["ʻĕzûwz"]', '["and/ might/ his"]', '["n-m"]', 'forcibleness might, strength.', 'from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6381}/H9023/[H6381]', 'inflected', 'heb', 'פָּלָא', '["pâlâʼ"]', '["and/ wonders/ his"]', '["v"]', 'properly, perhaps to separate, i.e. distinguish (literally or figuratively); by implication, to be (causatively, make) great, difficult, wonderful accomplish, (arise...too, be too) hard, hidden, things too high, (be, do, do a, shew) marvelous(-ly, -els, things, work), miracles, perform, separate, make singular, (be, great, make) wonderful(-ers, -ly, things, works), wondrous (things, works, -ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3689}/H9028/[H3688]', 'inflected', 'heb', 'כֶּסֶל', '["keçel"]', '["confidence/ their"]', '["n-m"]', 'properly, fatness, i.e. by implication (literally) the loin (as the seat of the leaf fat) or (generally) the viscera; also (figuratively) silliness or (in a good sense) trust confidence, flank, folly, hope, loin.', 'from 3688;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0001G}/H9028/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["like/ ancestors/ their"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8415}/[H1949]', 'inflected', 'heb', 'תְּהוֹם', '["tᵉhôwm"]', '["like/ deeps"]', '["n"]', 'an abyss (as a surging mass of water), especially the deep (the main sea or the subterranean watersupply) deep (place), depth.', 'or תְּהֹם; (usually feminine) from 1949;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5104H}/[H5102]', 'inflected', 'heb', 'נָהָר', '["nâhâr"]', '["like <the>/ river","like <the>/ rivers","like/ a river"]', '["n-m"]', 'a stream (including the sea; expectation the Nile, Euphrates, etc.); figuratively, prosperity flood, river.', 'from 5102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4784}/[H4784]', 'inflected', 'heb', 'מָרָה', '["mârâh"]', '["by/ rebelling against","to/ rebel toward"]', '["v"]', 'to be (causatively, make) bitter (or unpleasant); (figuratively) to rebel (or resist; causatively, to provoke) bitter, change, be disobedient, disobey, grievously, provocation, provoke(-ing), (be) rebel (against, -lious).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6723>', 'inflected', 'heb', 'בציות', '["ba./tzi.Yah","ba./tzi.Yot"]', '["in the/ dry region","in the/ dry regions"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5315L}/H9028/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["[will be] for/ self/ their","for/ selves/ their","to/ desire/ their"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2100G}/[H2100]', 'inflected', 'heb', 'זוּב', '["zûwb"]', '["and/ they flowed out"]', '["v"]', 'to flow freely (as water), i.e. (specifically) to have a (sexual) flux; figuratively, to waste away; also to overflow flow, gush out, have a (running) issue, pine away, run.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5400}/[H5400]', 'lemma', 'heb', 'נָשַׂק', '["nâsaq"]', '["he kindles a fire","it was kindled"]', '["v"]', 'to catch fire burn, kindle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0047J}/[H46]', 'lemma', 'heb', 'אַבִּיר', '["ʼabbîyr"]', '["mighty [ones]"]', '["a-m"]', 'angel, bull, chiefest, mighty (one), stout(-hearted), strong (one), valiant.', 'for 46');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5797}/H9023/[H5810]', 'inflected', 'heb', 'עֹז', '["ʻôz"]', '["by/ strength/ his"]', '["n-m"]', 'strength in various applications (force, security, majesty, praise) boldness, loud, might, power, strength, strong.', 'or (fully) עוֹז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4908}/H9023/[H7931]', 'inflected', 'heb', 'מִשְׁכָּן', '["mishkân"]', '["<to>/ dwelling<s>/ his","to/ dwelling place<s>/ his"]', '["n-m"]', 'a residence (including a shepherd''s hut, the lair of animals, figuratively, the grave; also the Temple); specifically, the Tabernacle (properly, its wooden walls) dwelleth, dwelling (place), habitation, tabernacle, tent.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8378}/H9028/[H183]', 'inflected', 'heb', 'תַּאֲוָה', '["taʼăvâh"]', '["and/ desire/ their"]', '["n-f"]', 'a longing; by implication, a delight (subjectively, satisfaction, objectively, a charm) dainty, desire, × exceedingly, × greedily, lust(ing), pleasant. See also 6914.', 'from 183 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8378}/H9028/[H183]', 'inflected', 'heb', 'תַּאֲוָה', '["taʼăvâh"]', '["from/ desire/ their"]', '["n-f"]', 'a longing; by implication, a delight (subjectively, satisfaction, objectively, a charm) dainty, desire, × exceedingly, × greedily, lust(ing), pleasant. See also 6914.', 'from 183 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4924B}/H9028/[H8080]', 'inflected', 'heb', 'מַשְׁמָן', '["mashmân"]', '["among/ vigorous ones/ their"]', '["n-m"]', 'fat, i.e. (literally and abstractly) fatness; but usually (figuratively and concretely) a rich dish, a fertile field, a robust man fat (one, -ness, -test, -test place).', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0970}/[H977]', 'inflected', 'heb', 'בָּחוּר', '["bâchûwr"]', '["and/ [the] young men of","and/ young men"]', '["n-m"]', 'properly, selected, i.e. a youth (often collective) (choice) young (man), chosen, × hole.', 'or בָּחֻר; participle passive of 977;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6381}/H9023/[H6381]', 'inflected', 'heb', 'פָּלָא', '["pâlâʼ"]', '["in/ wonders/ his"]', '["v"]', 'properly, perhaps to separate, i.e. distinguish (literally or figuratively); by implication, to be (causatively, make) great, difficult, wonderful accomplish, (arise...too, be too) hard, hidden, things too high, (be, do, do a, shew) marvelous(-ly, -els, things, work), miracles, perform, separate, make singular, (be, great, make) wonderful(-ers, -ly, things, works), wondrous (things, works, -ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1892}/[H1891]', 'inflected', 'heb', 'הֶבֶל', '["hebel"]', '["among/ [the] vanities of","by/ vanities of","in <the>/ futility"]', '["n-m"]', 'emptiness or vanity; figuratively, something transitory and unsatisfactory; often used as an adverb × altogether, vain, vanity.', 'or (rarely in the abs.) הֲבֵל; from 1891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0928}/[H926]', 'inflected', 'heb', 'בֶּהָלָה', '["behâlâh"]', '["in <the>/ sudden terror"]', '["n-f"]', 'panic, destruction terror, trouble.', 'from 926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1875}/H9033/[H1875]', 'inflected', 'heb', 'דָּרַשׁ', '["dârash"]', '["and/ they sought/ him"]', '["v"]', 'properly, to tread or frequent; usually to follow (for pursuit or search); by implication, to seek or ask; specifically to worship ask, × at all, care for, × diligently, inquire, make inquisition, (necro-) mancer, question, require, search, seek (for, out), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7836}/[H7836]', 'inflected', 'heb', 'שָׁחַר', '["shâchar"]', '["and/ they sought earnestly"]', '["v"]', 'properly, to dawn, i.e. (figuratively) be (up) early at any task (with the implication of earnestness); by extension, to search for (with painstaking) (do something) betimes, enquire early, rise (seek) betimes, seek diligently) early, in the morning).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0410J}/[H352]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["and/ God"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1350A}/H9028/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["[was] redeemer/ their","redeemer/ their"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6601B}/H9033/[H6601]', 'inflected', 'heb', 'פָּתָה', '["pâthâh"]', '["and/ they deceived/ him"]', '["v"]', 'to open, i.e. be (causatively, make) roomy; usually figuratively (in a mental or moral sense) to be (causatively, make) simple or (in a sinister way) delude allure, deceive, enlarge, entice, flatter, persuade, silly (one).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3956G}/H9028/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["and/ with/ tongue/ their"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3820A}/H9028/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["and/ heart/ their"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1285}/H9023/[H1262]', 'inflected', 'heb', 'בְּרִית', '["bᵉrîyth"]', '["in/ covenant/ his"]', '["n-f"]', 'a compact (because made by passing between pieces of flesh) confederacy, (con-) feder(-ate), covenant, league.', 'from 1262 (in the sense of cutting [like 1254]);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7725O}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["to/ repent","to/ return","to/ turn away","to/ turn back"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2534}/H9023/[H3179]', 'inflected', 'heb', 'חֵמָה', '["chêmâh"]', '["anger/ his","rage/ his"]', '["n-f"]', 'heat; figuratively, anger, poison (from its fever) anger, bottles, hot displeasure, furious(-ly, -ry), heat, indignation, poison, rage, wrath(-ful). See 2529.', 'or (Daniel 11:44) חֵמָא; from 3179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4784}/H9033/[H4784]', 'inflected', 'heb', 'מָרָה', '["mârâh"]', '["they rebelled against/ him"]', '["v"]', 'to be (causatively, make) bitter (or unpleasant); (figuratively) to rebel (or resist; causatively, to provoke) bitter, change, be disobedient, disobey, grievously, provocation, provoke(-ing), (be) rebel (against, -lious).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6918G}/[H6942]', 'inflected', 'heb', 'קָדוֹשׁ', '["qâdôwsh"]', '["and/ [is] holy","and/ [the] holy [one]","and/ [the] holy [one] of","and/ a holy [place]"]', '["a"]', 'sacred (ceremonially or morally); (as noun) God (by eminence), an angel, a saint, a sanctuary holy (One), saint.', 'or קָדֹשׁ; from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8428}/[H8427]', 'lemma', 'heb', 'תָּוָה', '["tâvâh"]', '["they pained"]', '["v"]', 'to grieve limit (by confusion with 8427).', 'a primitive root (or perhaps identical with 8427 through a similar idea from scraping to pieces);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6299}/H9038/[H6299]', 'inflected', 'heb', 'פָּדָה', '["pâdâh"]', '["I have redeemed/ them","I will redeem/ them","he ransomed/ them","will I ransom?/ them"]', '["v"]', 'to sever, i.e. ransom; generally to release, preserve × at all, deliver, × by any means, ransom, (that are to be, let be) redeem(-ed), rescue, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4159}/H9023/[H3302]', 'inflected', 'heb', 'מוֹפֵת', '["môwphêth"]', '["and/ wonders/ his"]', '["n-m"]', 'a miracle; by implication, a token or omen miracle, sign, wonder(-ed at).', 'or מֹפֵת; from 3302 in the sense of conspicuousness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2975H}/H9028/[H2975]', 'inflected', 'heb', 'יְאֹר', '["yᵉʼôr"]', '["canals/ their"]', '["n-m"]', 'a channel, e.g. a fosse, canal, shaft; specifically the Nile, as the one river of Egypt, including its collateral trenches; also the Tigris, as the main river of Assyria brook, flood, river, stream.', 'of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5140}/H9028/[H5140]', 'inflected', 'heb', 'נָזַל', '["nâzal"]', '["and/ streams/ their"]', '["v"]', 'to drip, or shed by trickling distil, drop, flood, (cause to) flow(-ing), gush out, melt, pour (down), running water, stream.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8354}/H9013/[H8354]', 'inflected', 'heb', 'שָׁתָה', '["shâthâh"]', '["they drank/ !"]', '["v"]', 'to imbibe (literally or figuratively) × assuredly, banquet, × certainly, drink(-er, -ing), drunk (× -ard), surely. (Prop. intensive of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6854}/[H6852]', 'inflected', 'heb', 'צְפַרְדֵּעַ', '["tsᵉphardêaʻ"]', '["and/ frog[s]"]', '["n-f"]', 'a marsh-leaper, i.e. frog frog.', 'from 6852 and a word elsewhere unused meaning a swamp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7843}/H9038/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["and/ it ruined/ them"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2625}/[H2628]', 'inflected', 'heb', 'חָסִיל', '["châçîyl"]', '["to the/ locust"]', '["n-m"]', 'the ravager, i.e. a locust caterpillar.', 'from 2628;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2981}/H9028/[H2986]', 'inflected', 'heb', 'יְבוּל', '["yᵉbûwl"]', '["produce/ their"]', '["n-m"]', 'produce, i.e. a crop or (figuratively) wealth fruit, increase.', 'from 2986;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3018}/H9028/[H3021]', 'inflected', 'heb', 'יְגִיעַ', '["yᵉgîyaʻ"]', '["and/ [the] result of toil/ their"]', '["n-m"]', 'toil; hence, a work, produce, property (as the result of labor) labour, work.', 'from 3021;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0697}/[H7235]', 'inflected', 'heb', 'אַרְבֶּה', '["ʼarbeh"]', '["[belongs] to the/ locust","to the/ locust"]', '["n-m"]', 'a locust (from its rapid increase) grasshopper, locust.', 'from 7235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1259}/[H1258]', 'inflected', 'heb', 'בָּרָד', '["bârâd"]', '["with <the>/ hail"]', '["n-m"]', 'hail hail(stones).', 'from 1258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H8256>/H9028', 'inflected', 'heb', 'ושקמותם', '["ve./shik.mo.Ta/m"]', '["and/ sycamore-fig trees/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2602>', 'inflected', 'heb', 'בחנמל', '["Ba./cha.na.Mal"]', '["with <the>/ a flood"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1259}/[H1258]', 'inflected', 'heb', 'בָּרָד', '["bârâd"]', '["to <the>/ hail"]', '["n-m"]', 'hail hail(stones).', 'from 1258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7565}/[H8313]', 'inflected', 'heb', 'רֶשֶׁף', '["resheph"]', '["to <the>/ lightning bolts"]', '["n-m"]', 'a live coal; by analogy lightning; figuratively, an arrow, (as flashing through the air); specifically, fever arrow, (burning) coal, burning heat, spark, hot thunderbolt.', 'from 8313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2195}/[H2194]', 'inflected', 'heb', 'זַעַם', '["zaʻam"]', '["and/ indignation"]', '["n-m"]', 'strictly froth at the mouth, i.e. (figuratively) fury (especially of God''s displeasure with sin) angry, indignation, rage.', 'from 2194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4917}/[H4916]', 'lemma', 'heb', 'מִשְׁלַחַת', '["mishlachath"]', '["[is] discharge","a band of"]', '["n-f"]', 'a mission, i.e. (abstractly and favorable) release, or (concretely and unfavorable) an army discharge, sending.', 'feminine of 4916;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6424}/[H6424]', 'lemma', 'heb', 'פָּלַס', '["pâlaç"]', '["[he is] making level","he made level","make level","she should make level","you make level"]', '["v"]', 'properly, to roll flat, i.e. prepare (a road); also to revolve, i.e. weigh (mentally) make, ponder, weigh.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0639G}/H9023/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["for/ anger/ his"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1698}/[H1696]', 'inflected', 'heb', 'דֶּבֶר', '["deber"]', '["to the/ pestilence"]', '["n-m"]', 'a pestilence murrain, pestilence, plague.', 'from 1696 (in the sense of destroying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0202}/[H205]', 'lemma', 'heb', 'אוֹן', '["ʼôwn"]', '["[is] power<s>","manly vigor<s>","strength<s>","wealth"]', '["n-m"]', 'ability, power, (figuratively) wealth force, goods, might, strength, substance.', 'probably from the same as 205 (in the sense of effort, but successful);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5090A}/H9038/[H5090]', 'inflected', 'heb', 'נָהַג', '["nâhag"]', '["and/ he led/ them"]', '["v"]', 'to drive forth (a person, an animal or chariot), i.e. lead, carry away; reflexively, to proceed (i.e. impel or guide oneself); also (from the panting induced by effort), to sigh acquaint, bring (away), carry away, drive (away), lead (away, forth), (be) guide, lead (away, forth).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5739}/[H5737]', 'inflected', 'heb', 'עֵדֶר', '["ʻêder"]', '["[are] like/ [the] flock of","[is] like/ [the] flock of","like <the>/ flock","like/ a flock"]', '["n-m"]', 'an arrangement, i.e. muster (of animals) drove, flock, herd.', 'from 5737;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5307I}/H9038/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["and/ he made fall/ them"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5472}/[H5472]', 'inflected', 'heb', 'סוּג', '["çûwg"]', '["and/ they turned back"]', '["v"]', 'properly, to flinch, i.e. (by implication) to go back, literally (to retreat) or figuratively (to apostatize) backslider, drive, go back, turn (away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7198}/[H7185]', 'inflected', 'heb', 'קֶשֶׁת', '["qesheth"]', '["like/ a bow of"]', '["n-f"]', 'a bow, for shooting (hence, figuratively, strength) or the iris × arch(-er), arrow, bow(-man, -shot).', 'from 7185 in the original sense (of 6983) of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3707}/H9033/[H3707]', 'inflected', 'heb', 'כַּעַס', '["kaʻaç"]', '["and/ they provoked to anger/ him"]', '["v"]', 'to trouble; by implication, to grieve, rage, be indignant be angry, be grieved, take indignation, provoke (to anger, unto wrath), have sorrow, vex, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H1116>/H9028', 'inflected', 'heb', 'בבמותם', '["be./va.mo.Ta/m"]', '["by/ high places/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6456}/H9028/[H6458]', 'inflected', 'heb', 'פְּסִיל', '["pᵉçîyl"]', '["and/ by/ idols/ their"]', '["n-m"]', 'an idol carved (graven) image, quarry.', 'from 6458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7628A}/[H7618]', 'inflected', 'heb', 'שְׁבִי', '["shᵉbîy"]', '["[are] for <the>/ captivity","to <the>/ captivity"]', '["n-m"]', 'exiled; captured; as noun, exile (abstractly or concretely and collectively); by extension, booty captive(-ity), prisoners, × take away, that was taken.', 'from 7618;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8597}/H9023/[H6286]', 'inflected', 'heb', 'תִּפְאָרָה', '["tiphʼârâh"]', '["and/ glory/ his","and/ splendor/ his"]', '["n-f"]', 'ornament (abstractly or concretely, literally or figuratively) beauty(-iful), bravery, comely, fair, glory(-ious), honour, majesty.', 'or תִּפְאֶרֶת; from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5159}/H9023/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["and/ with/ inheritance/ his"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5674B}/[H5674]', 'lemma', 'heb', 'עָבַר', '["ʻâbar"]', '["[who] becomes angry","he was furious","you have been furious"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0970}/H9023/[H977]', 'inflected', 'heb', 'בָּחוּר', '["bâchûwr"]', '["young men/ its"]', '["n-m"]', 'properly, selected, i.e. a youth (often collective) (choice) young (man), chosen, × hole.', 'or בָּחֻר; participle passive of 977;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1330>/H9023', 'inflected', 'heb', 'ובתולתיו', '["u./ve.tu.lo.Ta/v"]', '["and/ young women/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3463}/[H3462]', 'inflected', 'heb', 'יָשֵׁן', '["yâshên"]', '["like/ a sleeper"]', '["a"]', 'sleepy asleep, (one out of) sleep(-eth, -ing), slept.', 'from 3462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7442A}/[H7442]', 'lemma', 'heb', 'רָנַן', '["rânan"]', '["he cries aloud","overcome"]', '["v"]', 'properly, to creak (or emit a stridulous sound), i.e. to shout (usually for joy) aloud for joy, cry out, be joyful (greatly, make to) rejoice, (cause to) shout (for joy), (cause to) sing (aloud, for joy, out), triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H7626H>', 'inflected', 'heb', 'ובשבט', '["u./ve./She.vet"]', '["and/ <in>/ [the] tribe of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4356}/[H3607]', 'inflected', 'heb', 'מִכְלָאָה', '["miklâʼâh"]', '["from/ [the] fold","from/ [the] folds of"]', '["n-m"]', 'a pen (for flocks) (sheep-)fold. Compare 4357.', 'or מִכְלָה; from 3607;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3478}/[H8280]', 'inflected', 'heb', 'יִשְׂרָאֵל', '["Yisrâʼêl"]', '["and/ <in>/ Israel","and/ by/ Israel","and/ in/ Israel"]', '["n-pr-m"]', 'he will rule as God; Jisraël, a symbolical name of Jacob; also (typically) of his posterity Israel.', 'from 8280 and 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7462B}/H9038/[H7462]', 'inflected', 'heb', 'רָעָה', '["râʻâh"]', '["and/ I will shepherd/ them","and/ he shepherded/ them","and/ they will shepherd/ them"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8537}/[H8552]', 'inflected', 'heb', 'תֹּם', '["tôm"]', '["according to/ [the] integrity of"]', '["n-m"]', 'completeness; figuratively, prosperity; usually (morally) innocence full, integrity, perfect(-ion), simplicity, upright(-ly, -ness), at a venture. See 8550.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5856}/[H5753]', 'inflected', 'heb', 'עִי', '["ʻîy"]', '["into/ [the] heap of ruins of","into/ heaps of ruins"]', '["n-m"]', 'a ruin (as if overturned) heap.', 'from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7068}/H9021/[H7065]', 'inflected', 'heb', 'קִנְאָה', '["qinʼâh"]', '["[are] zeal/ your","jealousy/ your"]', '["n-f"]', 'jealousy or envy envy(-ied), jealousy, × sake, zeal.', 'from 7065;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2534}/H9021/[H3179]', 'inflected', 'heb', 'חֵמָה', '["chêmâh"]', '["anger/ your","rage/ your"]', '["n-f"]', 'heat; figuratively, anger, poison (from its fever) anger, bottles, hot displeasure, furious(-ly, -ry), heat, indignation, poison, rage, wrath(-ful). See 2529.', 'or (Daniel 11:44) חֵמָא; from 3179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6923}/H9035/[H6923]', 'inflected', 'heb', 'קָדַם', '["qâdam"]', '["may they come to meet/ us"]', '["v"]', 'to project (one self), i.e. precede; hence, to anticipate, hasten, meet (usually for help) come (go, (flee)) before, disappoint, meet, prevent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5869A}/H9025/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["to/ eyes/ our"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8210G}/[H8210]', 'inflected', 'heb', 'שָׁפַךְ', '["shâphak"]', '["<the>/ poured out"]', '["v"]', 'to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0603}/[H602]', 'lemma', 'heb', 'אֲנָקָה', '["ʼănâqâh"]', '["[the] groaning of"]', '["n-f"]', 'shrieking crying out, groaning, sighing.', 'from 602;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8546}/[H4191]', 'lemma', 'heb', 'תְּמוּתָה', '["tᵉmûwthâh"]', '["death"]', '["n-f"]', 'execution (as a doom) death, die.', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2436I>/H9028', 'opaque', 'heb', 'חֵיק', '["chêyq"]', '["bosom/ their"]', '["n-m"]', 'the bosom (literally or figuratively) bosom, bottom, lap, midst, within.', 'or חֵק; and חוֹק; from an unused root, apparently meaning to inclose;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3313}/H9012/[H3313]', 'inflected', 'heb', 'יָפַע', '["yâphaʻ"]', '["shine forth/ !"]', '["v"]', 'to shine be light, shew self, (cause to) shine (forth).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725H}/H9035/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["cause to return/ us","restore/ us"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0215}/[H215]', 'inflected', 'heb', 'אוֹר', '["ʼôwr"]', '["and/ [which] shines","and/ make shine"]', '["v"]', 'to be (causative, make) luminous (literally and metaphorically) × break of day, glorious, kindle, (be, en-, give, show) light (-en, -ened), set on fire, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8605}/[H6419]', 'inflected', 'heb', 'תְּפִלָּה', '["tᵉphillâh"]', '["at/ [the] prayer of","in <the>/ prayer"]', '["n-f"]', 'intercession, supplication; by implication, a hymn prayer.', 'from 6419;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1832}/[H1831]', 'lemma', 'heb', 'דִּמְעָה', '["dimʻâh"]', '["[the] tear[s] of","tear[s]"]', '["n-f"]', 'weeping tears.', 'feminine of 1831;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1832}/[H1831]', 'inflected', 'heb', 'דִּמְעָה', '["dimʻâh"]', '["<in>/ tears","by <the>/ tears","with/ tear[s]"]', '["n-f"]', 'weeping tears.', 'feminine of 1831;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7991A}/[H7969]', 'lemma', 'heb', 'שָׁלִישׁ', '["shâlîysh"]', '["a third of a measure"]', '["n-m"]', 'a triple, i.e. (as a musical instrument) a triangle (or perhaps rather three-stringed lute); also (as an indefinite, great quantity) a three-fold measure (perhaps a treble ephah); also (as an officer) a general of the third rank (upward, i.e. the highest) captain, instrument of musick, (great) lord, (great) measure, prince, three (from the margin).', 'or שָׁלוֹשׁ; (1 Chronicles 11:11; 1 Chronicles 12:18), or שָׁלֹשׁ; (2 Samuel 23:13), from 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4066}/[H1777]', 'lemma', 'heb', 'מָדוֹן', '["mâdôwn"]', '["a contention","contention","strife"]', '["n-m"]', 'a contest or quarrel brawling, contention(-ous), discord, strife. Compare 4079, 4090.', 'from 1777;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5193}/H9034/[H5193]', 'inflected', 'heb', 'נָטַע', '["nâṭaʻ"]', '["and/ you planted/ it"]', '["v"]', 'properly, to strike in, i.e. fix; specifically, to plant (literally or figuratively) fastened, plant(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8327}/[H8327]', 'inflected', 'heb', 'שָׁרַשׁ', '["shârash"]', '["and/ it took root"]', '["v"]', 'to root, i.e. strike into the soil, or (by implication) to pluck from it (take, cause to take) root (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8328}/H9024/[H8327]', 'inflected', 'heb', 'שֶׁרֶשׁ', '["sheresh"]', '["roots/ her","roots/ its"]', '["n-m"]', 'a root (literally or figuratively) bottom, deep, heel, root.', 'from 8327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6738}/H9024/[H6751]', 'inflected', 'heb', 'צֵל', '["tsêl"]', '["shade/ its"]', '["n-m"]', 'shade, whether literal or figurative defence, shade(-ow).', 'from 6751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6057>/H9024', 'inflected', 'heb', 'וענפיה', '["va./''a.na.Fei./ha"]', '["and/ branches/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7105B}/H9024/[H7114]', 'inflected', 'heb', 'קָצִיר', '["qâtsîyr"]', '["branch[es]/ its"]', '["n-m"]', 'severed, i.e. harvest (as reaped), the crop, the time, the reaper, or figuratively; also a limb (of a tree, or simply foliage) bough, branch, harvest (man).', 'from 7114;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3127}/H9024/[H3126]', 'inflected', 'heb', 'יוֹנֶקֶת', '["yôwneqeth"]', '["young shoots/ its"]', '["n-f"]', 'a sprout (tender) branch, young twig.', 'feminine of 3126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1447}/H9024/[H1443]', 'inflected', 'heb', 'גָּדֵר', '["gâdêr"]', '["wall/ her","walls/ its"]', '["n-m"]', 'a circumvallation; by implication, an inclosure fence, hedge, wall.', 'from 1443;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0717}/H9034/[H717]', 'inflected', 'heb', 'אָרָה', '["ʼârâh"]', '["and/ they have plucked/ it"]', '["v"]', 'to pluck gather, pluck.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3765}/H9034/[H3697]', 'inflected', 'heb', 'כִּרְסֵם', '["kirçêm"]', '["it eats away/ it"]', '["v"]', 'to lay waste waste.', 'from 3697;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2386>', 'opaque', 'heb', 'חֲזִיר', '["chăzîyr"]', '["a pig","wild boar"]', '["n-m"]', 'a hog (perhaps as penned) boar, swine.', 'from an unused root probably meaning to inclose;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H3293A>', 'inflected', 'heb', 'מיער', '["mi./Ya.''ar"]', '["from/ [the] forest","from/ a forest"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7462B}/H9034/[H7462]', 'inflected', 'heb', 'רָעָה', '["râʻâh"]', '["I will shepherd/ it","it grazes on/ it"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6485I}/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["and/ attend to"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3657}/[H3661]', 'inflected', 'heb', 'כַּנָּה', '["kannâh"]', '["and/ [the] root"]', '["n-f"]', 'a plant (as set) × vineyard.', 'from 3661;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3683}/[H3683]', 'lemma', 'heb', 'כָּסַח', '["kâçach"]', '["[it is] cut down","cut down"]', '["v"]', 'to cut off cut down (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1606}/[H1605]', 'inflected', 'heb', 'גְּעָרָה', '["gᵉʻârâh"]', '["from/ [the] rebuke of"]', '["n-f"]', 'a chiding rebuke(-ing), reproof.', 'from 1605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5797}/H9025/[H5810]', 'inflected', 'heb', 'עֹז', '["ʻôz"]', '["strength/ our"]', '["n-m"]', 'strength in various applications (force, security, majesty, praise) boldness, loud, might, power, strength, strong.', 'or (fully) עוֹז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2172}/[H2167]', 'lemma', 'heb', 'זִמְרָה', '["zimrâh"]', '["music"]', '["n-f"]', 'a musical piece or song to be accompanied by an instrument melody, psalm.', 'from 2167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5414M}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ beat"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8596}/[H8608]', 'lemma', 'heb', 'תֹּף', '["tôph"]', '["a tambourine","tambourine","tambourines"]', '["n-m"]', 'a tambourine tabret, timbrel.', 'from 8608 contracted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5273B}/[H5276]', 'lemma', 'heb', 'נָעִים', '["nâʻîym"]', '["pleasant"]', '["a"]', 'delightful (objective or subjective, literal or figurative) pleasant(-ure), sweet.', 'from 5276;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3677}/[H3680]', 'inflected', 'heb', 'כֶּסֶא', '["keçeʼ"]', '["at the/ full moon"]', '["n-m"]', 'properly, fulness or the full moon, i.e. its festival (time) appointed.', 'or כֶּסֶה; apparently from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2282}/H9025/[H2287]', 'inflected', 'heb', 'חַג', '["chag"]', '["festival/ our"]', '["n-m"]', 'a festival, or a victim therefor (solemn) feast (day), sacrifice, solemnity.', 'or חָג; from 2287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3084}/[H3130]', 'inflected', 'heb', 'יְהוֹסֵף', '["Yᵉhôwçêph"]', '["in/ Joseph"]', '["n-pr-m"]', 'Jehoseph (i.e. Joseph), a son of Jacob Joseph.', 'a fuller form of 3130;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5447}/[H5445]', 'inflected', 'heb', 'סֵבֶל', '["çêbel"]', '["from/ a burden"]', '["n-m"]', 'a load (literally or figuratively) burden, charge.', 'from 5445;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1731}/[H1730]', 'inflected', 'heb', 'דּוּד', '["dûwd"]', '["from/ a basket"]', '["n-m"]', 'a pot (for boiling); also (by resemblance of shape) a basket basket, caldron, kettle, (seething) pot.', 'from the same as 1730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2502A}/H9031/[H2502]', 'inflected', 'heb', 'חָלַץ', '["châlats"]', '["and/ I rescued/ you"]', '["v"]', 'to pull off; hence (intensively) to strip, (reflex.) to depart; by implication, to deliver, equip (for fight); present, strengthen arm (self), (go, ready) armed (× man, soldier), deliver, draw out, make fat, loose, (ready) prepared, put off, take away, withdraw self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0974}/H9031/[H974]', 'inflected', 'heb', 'בָּחַן', '["bâchan"]', '["I tested/ you"]', '["v"]', 'to test (especially metals); generally and figuratively, to investigate examine, prove, tempt, try (trial).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5927H}/H9031/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["who/ brought up/ you"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4390}/H9033/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["and/ I will fill/ it"]', '["v"]', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly.', 'or מָלָא; (Esther 7:5), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4156}/H9028/[H3289]', 'inflected', 'heb', 'מוֹעֵצָה', '["môwʻêtsâh"]', '["in/ own schemes/ their","in/ schemes/ their"]', '["n-f"]', 'a purpose counsel, device.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6256}/H9028/[H5703]', 'inflected', 'heb', 'עֵת', '["ʻêth"]', '["time/ their"]', '["n-f"]', 'time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when.', 'from 5703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6697H}/[H6696]', 'inflected', 'heb', 'צוּר', '["tsûwr"]', '["and/ from/ a rock"]', '["n-m"]', 'properly, a cliff (or sharp rock, as compressed); generally, a rock or boulder; figuratively, a refuge; also an edge (as precipitous) edge, × (mighty) God (one), rock, × sharp, stone, × strength, × strong. See also 1049.', 'or צֻר; from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7646}/H9031/[H7646]', 'inflected', 'heb', 'שָׂבַע', '["sâbaʻ"]', '["I will satisfy/ you","he should be surfeited with/ you"]', '["v"]', 'to sate, i.e. fill to satisfaction (literally or figuratively) have enough, fill (full, self, with), be (to the) full (of), have plenty of, be satiate, satisfy (with), suffice, be weary of.', 'or שָׂבֵעַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6440N}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["and/ [the] face of"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7326}/[H7326]', 'inflected', 'heb', 'רוּשׁ', '["rûwsh"]', '["and/ [the] poor","and/ a poor [person]"]', '["v"]', 'to be destitute lack, needy, (make self) poor (man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2825}/[H2821]', 'inflected', 'heb', 'חֲשֵׁכָה', '["chăshêkâh"]', '["in/ darkness"]', '["n-f"]', 'darkness; figuratively, misery darkness.', 'or חֲשֵׁיכָהxlit chăshêkâh corrected to chăshêykâh; from 2821;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0120G}/[H119]', 'inflected', 'heb', 'אָדָם', '["ʼâdâm"]', '["like/ humankind"]', '["n-m"]', 'ruddy i.e. a human being (an individual or the species, mankind, etc.) × another, hypocrite, common sort, × low, man (mean, of low degree), person.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0259}/[H258]', 'inflected', 'heb', 'אֶחָד', '["ʼechâd"]', '["and/ like/ one of"]', '["a"]', 'properly, united, i.e. one; or (as an ordinal) first a, alike, alone, altogether, and, any(-thing), apiece, a certain, (dai-) ly, each (one), eleven, every, few, first, highway, a man, once, one, only, other, some, together,', 'a numeral from 258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8199}/H9012/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["judge/ !"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1824}/[H1820]', 'lemma', 'heb', 'דְּמִי', '["dᵉmîy"]', '["rest","silence"]', '["n-m"]', 'quiet cutting off, rest, silence.', 'or דֳּמִי; from 1820;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8130}/H9031/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["and/ [those who] hate/ you"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6845}/H9021/[H6845]', 'inflected', 'heb', 'צָפַן', '["tsâphan"]', '["treasured [ones]/ your"]', '["v"]', 'to hide (by covering over); by implication, to hoard or reserve; figuratively to deny; specifically (favorably) to protect, (unfavorably) to lurk esteem, hide(-den one, self), lay up, lurk (be set) privily, (keep) secret(-ly, place).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3582}/H9038/[H3582]', 'inflected', 'heb', 'כָּחַד', '["kâchad"]', '["and/ let us annihilate/ them"]', '["v"]', 'to secrete, by act or word; hence (intensively) to destroy conceal, cut down (off), desolate, hide.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3459}/[H3458]', 'inflected', 'heb', 'יִשְׁמָעֵאלִי', '["Yishmâʻêʼlîy"]', '["and/ [the] Ishmaelites"]', '["a"]', 'a Jishmaelite or descendant of Jishmael Ishmaelite.', 'patronymically from 3458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1905}/[H1904]', 'inflected', 'heb', 'הַגְרִי', '["Hagrîy"]', '["and/ [the] Hagrites"]', '["n-pr"]', 'a Hagrite or member of a certain Arabian clan Hagarene, Hagarite, Haggeri.', 'or (prolonged) הַגְרִיאxlit Hagrîʼ corrected to Hagrîyʼ; perhaps patronymically from 1904;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1381}/[H1380]', 'lemma', 'heb', 'גְּבָל', '["Gᵉbâl"]', '["Gebal"]', '["n-pr-loc"]', 'Gebal, a region in Idumaea Gebal.', 'the same as 1380;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5983}/[H5971]', 'inflected', 'heb', 'עַמּוֹן', '["ʻAmmôwn"]', '["and/ Ammon"]', '["n-pr-m"]', 'Ammon, a son of Lot; also his posterity and their country Ammon, Ammonites.', 'from 5971; tribal, i.e. inbred;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4080H}/[H4079]', 'inflected', 'heb', 'מִדְיָן', '["Midyân"]', '["like/ Midian"]', '["n-pr-m n-pr-loc"]', 'Midjan, a son of Abraham; also his country and (collectively) his descendants Midian, Midianite.', 'the same as 4079;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H5516G>', 'inflected', 'heb', 'כסיסרא', '["ke./si.se.Ra''"]', '["like/ Sisera"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2985H}/[H995]', 'inflected', 'heb', 'יָבִין', '["Yâbîyn"]', '["like/ Jabin"]', '["n-pr-m"]', 'Jabin, the name of two Canaanitish kings Jabin.', 'from 995; intelligent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1828>', 'opaque', 'heb', 'דֹּמֶן', '["dômen"]', '["dung"]', '["n-m"]', 'manure dung.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0127G}/[H119]', 'inflected', 'heb', 'אֲדָמָה', '["ʼădâmâh"]', '["for the/ ground","to/ [the] land of"]', '["n-f"]', 'soil (from its general redness) country, earth, ground, husband(-man) (-ry), land.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5081H}/H9028/[H5068]', 'inflected', 'heb', 'נָדִיב', '["nâdîyb"]', '["noble [people]/ their"]', '["a"]', 'properly, voluntary, i.e. generous; hence, magnanimous; as noun, a grandee (sometimes a tyrant) free, liberal (things), noble, prince, willing (hearted).', 'from 5068;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6159}/[H6158]', 'inflected', 'heb', 'עֹרֵב', '["ʻÔrêb"]', '["like/ Oreb"]', '["n-pr-m n-pr-loc"]', 'Oreb, the name of a Midianite and of the cliff near the Jordan Oreb.', 'or עוֹרֵב; the same as 6158;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H2062}/[H2061]', 'inflected', 'heb', 'זְאֵב', '["Zᵉʼêb"]', '["and/ like/ Zeeb"]', '["n-pr-m"]', 'Zeeb, a Midianitish prince Zeeb.', 'the same as 2061;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H2078}/[H2077]', 'inflected', 'heb', 'זֶבַח', '["Zebach"]', '["and/ like/ Zebah"]', '["n-pr-m"]', 'Zebach, a Midianitish prince Zebah.', 'the same as 2077; sacrifice;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H6759}/[H6738]', 'inflected', 'heb', 'צַלְמֻנָּע', '["Tsalmunnâʻ"]', '["and/ like/ Zalmunna"]', '["n-pr-m"]', 'Tsalmunna, a Midianite Zalmunna.', 'from 6738 and 4513; shade has been denied;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5257B}/H9028/[H5258]', 'inflected', 'heb', 'נְסִיךְ', '["nᵉçîyk"]', '["princes/ their"]', '["n-m"]', 'properly, something poured out, i.e. a libation; also a molten image; by implication, a prince (as anointed) drink offering, duke, prince(-ipal).', 'from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1534}/[H1556]', 'inflected', 'heb', 'גַּלְגַּל', '["galgal"]', '["like <the>/ whirling dust"]', '["n-m"]', 'a wheel; by analogy, a whirlwind; also dust (as whirled) heaven, rolling thing, wheel.', 'by reduplication from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H3852}/[H3851]', 'inflected', 'heb', 'לֶהָבָה', '["lehâbâh"]', '["and/ like/ a flame"]', '["n-f"]', 'flame(-ming), head (of a spear).', 'or לַהֶבֶת; feminine of 3851, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5591A}/H9021/[H5590]', 'inflected', 'heb', 'סַעַר', '["çaʻar"]', '["with/ storm/ your"]', '["n-m"]', 'a hurricane storm(-y), tempest, whirlwind.', 'or (feminine) סְעָרָה; from 5590;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5492A}/H9021/[H5486]', 'inflected', 'heb', 'סוּפָה', '["çûwphâh"]', '["and/ with/ storm-wind/ your"]', '["n-f n-pr-loc"]', 'a hurricane Red Sea, storm, tempest, whirlwind, Red sea.', 'from 5486;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1866}/[H1865]', 'inflected', 'heb', 'דְּרוֹר', '["dᵉrôwr"]', '["and/ a swallow"]', '["n-f"]', 'the swift, a kind of swallow swallow.', 'the same as 1865, applied to a bird;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0667}/H9024/[H6524]', 'inflected', 'heb', 'אֶפְרֹחַ', '["ʼephrôach"]', '["young ones/ its"]', '["n-m"]', 'the brood of a bird young (one).', 'from 6524 (in the sense of bursting the shell);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6010L}/[H6009]', 'inflected', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["in/ [the] valley of"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1056}/[H1058]', 'inflected', 'heb', 'בָּכָא', '["Bâkâʼ"]', '["<the>/ Baca"]', '["n-pr-loc"]', 'Baca, a valley in Palestine Baca.', 'from 1058, weeping;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2428G}/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["from/ strength"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5027}/[H5027]', 'inflected', 'heb', 'נָבַט', '["nâbaṭ"]', '["and/ I may look","and/ I will pay attention","and/ I will pay attention to","and/ look","and/ pay attention to","and/ to look","so/ let me pay attention to"]', '["v"]', 'to scan, i.e. look intently at; by implication, to regard with pleasure, favor or care (cause to) behold, consider, look (down), regard, have respect, see.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2691A}/H9021/[H2690]', 'inflected', 'heb', 'חָצֵר', '["châtsêr"]', '["in/ courts/ your"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5605}/[H5592]', 'lemma', 'heb', 'סָפַף', '["çâphaph"]', '["to stand at [the] threshold"]', '["v"]', 'to wait at the threshold be a doorkeeper.', 'a primitive root; properly, to snatch away, i.e. terminate; but used only as denominative from 5592 (in the sense of a vestibule),');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1752}/[H1752]', 'inflected', 'heb', 'דּוּר', '["dûwr"]', '["more than/ dwelling"]', '["v"]', 'properly, to gyrate (or move in a circle), i.e. to remain dwell.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5678}/H9021/[H5676]', 'inflected', 'heb', 'עֶבְרָה', '["ʻebrâh"]', '["[is] fury/ your","fury/ your"]', '["n-f"]', 'an outburst of passion anger, rage, wrath.', 'feminine of 5676;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725J}/H9035/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["restore/ us"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6565A}/[H6565]', 'inflected', 'heb', 'פָּרַר', '["pârar"]', '["and/ break","and/ it may fail","so/ it may be frustrated"]', '["v"]', 'to break up (usually figuratively), i.e. to violate, frustrate × any ways, break (asunder), cast off, cause to cease, × clean, defeat, disannul, disappoint, dissolve, divide, make of none effect, fail, frustrate, bring (come) to nought, × utterly, make void.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3708A}/H9021/[H3707]', 'inflected', 'heb', 'כַּעַס', '["kaʻaç"]', '["anger/ your"]', '["n-m"]', 'vexation anger, angry, grief, indignation, provocation, provoking, × sore, sorrow, spite, wrath.', 'or (in Job) כַּעַשׂ; from 3707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3468}/H9021/[H3467]', 'inflected', 'heb', 'יֶשַׁע', '["yeshaʻ"]', '["and/ salvation/ your"]', '["n-m"]', 'liberty, deliverance, prosperity safety, salvation, saving.', 'or יֵשַׁע; from 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3690}/[H3689]', 'inflected', 'heb', 'כִּסְלָה', '["kiçlâh"]', '["to/ folly"]', '["n-f"]', 'in a good sense, trust; in a bad one, silliness confidence, folly.', 'feminine of 3689;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0776G>/H9025', 'inflected', 'heb', 'בארצנו', '["be./''ar.Tze./nu","ve./''ar.Tze./nu"]', '["in/ land/ our"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0776G>/H9025', 'inflected', 'heb', 'וארצנו', '["ve./''ar.Tze./nu"]', '["and/ land/ our"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1870K}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["into <the>/ road","to/ [the] way of"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5546}/[H5545]', 'inflected', 'heb', 'סַלָּח', '["çallâch"]', '["and/ ready to forgive"]', '["a"]', 'placable ready to forgive.', 'from 5545;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7181}/H9012/[H7181]', 'inflected', 'heb', 'קָשַׁב', '["qâshab"]', '["and/ pay attention/ !"]', '["v"]', 'to prick up the ears, i.e. hearken attend, (cause to) hear(-ken), give heed, incline, mark (well), regard.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2086}/[H2102]', 'lemma', 'heb', 'זֵד', '["zêd"]', '["arrogant [people]","proud"]', '["n-m"]', 'arrogant presumptuous, proud.', 'from 2102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0954}/[H954]', 'inflected', 'heb', 'בּוּשׁ', '["bûwsh"]', '["and/ be ashamed","and/ it may be ashamed","and/ they may be ashamed","and/ they were ashamed","so/ they may be ashamed"]', '["v"]', 'properly, to pale, i.e. by implication to be ashamed; also (by implication) to be disappointed or delayed (be, make, bring to, cause, put to, with, a-) shamed(-d), be (put to) confounded(-fusion), become dry, delay, be long.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5826}/H9030/[H5826]', 'inflected', 'heb', 'עָזַר', '["ʻâzar"]', '["he helped/ me","help/ me","may they help/ me","you have helped/ me"]', '["v"]', 'to surround, i.e. protect or aid help, succour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5162G}/H9030/[H5162]', 'inflected', 'heb', 'נָחַם', '["nâcham"]', '["and/ may you comfort/ me","and/ you have comforted/ me"]', '["v"]', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3248}/H9023/[H3246]', 'inflected', 'heb', 'יְסוּדָה', '["yᵉçûwdâh"]', '["foundation/ his"]', '["n-f"]', 'a foundation foundation.', 'feminine of 3246;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7293}/[H7292]', 'lemma', 'heb', 'רַהַב', '["rahab"]', '["Rahab"]', '["n-m"]', 'bluster(-er) proud, strength.', 'from 7292,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0894}/[H1101]', 'inflected', 'heb', 'בָּבֶל', '["Bâbel"]', '["and/ Babylon"]', '["n-pr-loc"]', 'Babel (i.e. Babylon), including Babylonia and the Babylonian empire Babel, Babylon.', 'from 1101; confusion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6865}/[H6864]', 'inflected', 'heb', 'צֹר', '["Tsôr"]', '["and/ Tyre"]', '["n-pr-loc"]', 'Tsor, a place in Palestine Tyre, Tyrus.', 'or צוֹר; the same as 6864; a rock;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6726}/[H6725]', 'inflected', 'heb', 'צִיּוֹן', '["Tsîyôwn"]', '["and/ for/ Zion","and/ of/ Zion"]', '["n-pr-loc"]', 'Tsijon (as a permanent capital), a mountain of Jerusalem Zion.', 'the same (regularly) as 6725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2490B}/[H2470]', 'inflected', 'heb', 'חָלַל', '["châlal"]', '["like/ pipers"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4599}/H9020/[H5869]', 'inflected', 'heb', 'מַעְיָן', '["maʻyân"]', '["springs/ my"]', '["n-m"]', 'a fountain (also collectively), figuratively, a source (of satisfaction) fountain, spring, well.', 'or מַעְיְנוֹ; (Psalm 114:8), or (feminine) מַעְיָנָה; from 5869 (as a denominative in the sense of a spring);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6030C}/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["to/ sing"]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1968G}/[H539]', 'inflected', 'heb', 'הֵימָן', '["Hêymân"]', '["of/ Heman"]', '["n-pr-m"]', 'Heman, the name of at least two Israelites Heman.', 'probably from 539; faithful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7440}/H9020/[H7442]', 'inflected', 'heb', 'רִנָּה', '["rinnâh"]', '["to/ cry of entreaty/ my"]', '["n-f"]', 'properly, a creaking (or shrill sound), i.e. shout (of joy or grief) cry, gladness, joy, proclamation, rejoicing, shouting, sing(-ing), triumph.', 'from 7442;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2416E}/H9020/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["and/ life/ my"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0353}/[H352]', 'lemma', 'heb', 'אֱיָל', '["ʼĕyâl"]', '["[is] strength"]', '["n-m"]', 'strength strength.', 'a variation of 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2142}/H9038/[H2145]', 'inflected', 'heb', 'זָכַר', '["zâkar"]', '["you remember/ them"]', '["v"]', 'properly, to mark (so as to be recognized), i.e. to remember; by implication, to mention; to be male × burn (incense), × earnestly, be male, (make) mention (of), be mindful, recount, record(-er), remember, make to be remembered, bring (call, come, keep, put) to (in) remembrance, × still, think on, × well.', 'a primitive root; also as denominative from 2145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7896H}/H9030/[H7896]', 'inflected', 'heb', 'שִׁית', '["shîyth"]', '["you have put/ me"]', '["v"]', 'to place (in a very wide application) apply, appoint, array, bring, consider, lay (up), let alone, × look, make, mark, put (on), regard, set, shew, be stayed, × take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4285}/[H2821]', 'inflected', 'heb', 'מַחְשָׁךְ', '["machshâk"]', '["in/ [the] dark places","in/ a dark place","in/ dark places"]', '["n-m"]', 'darkness; concretely, a dark place dark(-ness, place).', 'from 2821;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3045}/H9020/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["acquaintances/ my"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7896G}/H9030/[H7896]', 'inflected', 'heb', 'שִׁית', '["shîyth"]', '["you have made/ me"]', '["v"]', 'to place (in a very wide application) apply, appoint, array, bring, consider, lay (up), let alone, × look, make, mark, put (on), regard, set, shew, be stayed, × take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1669}/[H1669]', 'lemma', 'heb', 'דָּאַב', '["dâʼab"]', '["[who] it has become faint","it is faint"]', '["v"]', 'to pine mourn, sorrow(-ful).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9005/{H4191}/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["¿/ for the/ dead"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7496}/[H7495]', 'lemma', 'heb', 'רָפָא', '["râphâʼ"]', '["[the] shades","shades"]', '["n-m"]', 'properly, lax, i.e. (figuratively) a ghost (as dead; in plural only) dead, deceased.', 'from 7495 in the sense of 7503;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0011}/[H6]', 'inflected', 'heb', 'אֲבַדּוֹן', '["ʼăbaddôwn"]', '["in <the>/ Abaddon"]', '["n-pr-loc"]', 'abstract, a perishing; concrete, Hades destruction.', 'intensive from 6;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5388}/[H5382]', 'lemma', 'heb', 'נְשִׁיָּה', '["nᵉshîyâh"]', '["forgetting"]', '["n-f"]', 'oblivion forgetfulness.', 'from 5382;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6923}/H9031/[H6923]', 'inflected', 'heb', 'קָדַם', '["qâdam"]', '["it comes to meet/ you"]', '["v"]', 'to project (one self), i.e. precede; hence, to anticipate, hasten, meet (usually for help) come (go, (flee)) before, disappoint, meet, prevent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0367}/H9021/[H366]', 'inflected', 'heb', 'אֵימָה', '["ʼêymâh"]', '["terrors/ your"]', '["n-f"]', 'fright; concrete, an idol (as a bugbear) dread, fear, horror, idol, terrible, terror.', 'or (shortened) אֵמָה; from the same as 366;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6323}/[H6323]', 'lemma', 'heb', 'פּוּן', '["pûwn"]', '["I am perplexed"]', '["v"]', 'meaning to turn, i.e. be perplexed be distracted.', 'a primitive root');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1161}/H9021/[H1204]', 'inflected', 'heb', 'בִּעוּתִים', '["biʻûwthîym"]', '["terrors/ your"]', '["n-m"]', 'alarms terrors.', 'masculine plural from 1204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0387G}/[H386]', 'inflected', 'heb', 'אֵיתָן', '["ʼÊythân"]', '["of/ Ethan"]', '["n-pr-m"]', 'Ethan, the name of four Israelites Ethan.', 'the same as 386; permanent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0972}/H9020/[H977]', 'inflected', 'heb', 'בָּחִיר', '["bâchîyr"]', '["to/ chosen one/ my","to/ chosen ones/ my"]', '["n-m"]', 'select choose, chosen one, elect.', 'from 977;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2626}/[H2630]', 'lemma', 'heb', 'חֲסִין', '["chăçîyn"]', '["[is] mighty"]', '["a"]', 'properly, firm, i.e. (by implication) mighty strong.', 'from 2630;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0530}/H9021/[H529]', 'inflected', 'heb', 'אֱמוּנָה', '["ʼĕmûwnâh"]', '["and/ faithfulness/ your"]', '["n-f"]', 'literally firmness; figuratively security; morally fidelity faith(-ful, -ly, -ness, (man)), set office, stability, steady, truly, truth, verily.', 'or (shortened) אֱמֻנָה; feminine of 529;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5375G}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["when/ rise up"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1530H}/H9023/[H1556]', 'inflected', 'heb', 'גַּל', '["gal"]', '["waves/ its"]', '["n-m"]', 'something rolled, i.e. a heap of stone or dung (plural ruins), by analogy, a spring of water (plural waves) billow, heap, spring, wave.', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7623A}/H9038/[H7623]', 'inflected', 'heb', 'שָׁבַח', '["shâbach"]', '["you calm/ them"]', '["v"]', 'properly, to address in a loud tone, i.e. (specifically) loud; figuratively, to pacify (as if by words) commend, glory, keep in, praise, still, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2491A}/[H2490]', 'inflected', 'heb', 'חָלָל', '["châlâl"]', '["like <the>/ [one] slain"]', '["n-m"]', 'pierced (especially to death); figuratively, polluted kill, profane, slain (man), × slew, (deadly) wounded.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3245}/H9038/[H3245]', 'inflected', 'heb', 'יָסַד', '["yâçad"]', '["you founded/ them","you have established/ them"]', '["v"]', 'to set (literally or figuratively); intensively, to found; reflexively, to sit down together, i.e. settle, consult appoint, take counsel, establish, (lay the, lay for a) found(-ation), instruct, lay, ordain, set, × sure.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3225H}/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["and/ [the] south"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2768}/[H2763]', 'inflected', 'heb', 'חֶרְמוֹן', '["Chermôwn"]', '["and/ Hermon"]', '["n-pr-m"]', 'Chermon, a mount of Palestine Hermon.', 'from 2763; abrupt;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1523}/H9013/[H1523]', 'inflected', 'heb', 'גִּיל', '["gîyl"]', '["they rejoice/ !"]', '["v"]', 'properly, to spin round (under the influence of any violent emotion), i.e. usually rejoice, or (as cringing) fear be glad, joy, be joyful, rejoice.', 'or (by permutation) גּוּל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6666}/H9021/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["and/ in/ righteousness/ your"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5797}/H9028/[H5810]', 'inflected', 'heb', 'עֹז', '["ʻôz"]', '["strength/ their"]', '["n-m"]', 'strength in various applications (force, security, majesty, praise) boldness, loud, might, power, strength, strong.', 'or (fully) עוֹז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7522}/H9021/[H7521]', 'inflected', 'heb', 'רָצוֹן', '["râtsôwn"]', '["and/ in/ favor/ your"]', '["n-m"]', 'delight (especially as shown) (be) acceptable(-ance, -ed), delight, desire, favour, (good) pleasure, (own, self, voluntary) will, as...(what) would.', 'or רָצֹן; from 7521;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7161A}/H9025/[H7160]', 'inflected', 'heb', 'קֶרֶן', '["qeren"]', '["horn/ our"]', '["n-f n-pr-loc"]', 'a horn (as projecting); by implication, a flask, cornet; by resemblance. an elephant''s tooth (i.e. ivory), a corner (of the altar), a peak (of a mountain), a ray (of light); figuratively, power × hill, horn.', 'from 7160;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6918G}/[H6942]', 'inflected', 'heb', 'קָדוֹשׁ', '["qâdôwsh"]', '["and/ [belongs] to/ [the] holy [one] of","and/ to/ [the] holy [one] of"]', '["a"]', 'sacred (ceremonially or morally); (as noun) God (by eminence), an angel, a saint, a sanctuary holy (One), saint.', 'or קָדֹשׁ; from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2623}/H9021/[H2616]', 'inflected', 'heb', 'חָסִיד', '["châçîyd"]', '["to/ faithful [people]/ your"]', '["a"]', 'properly, kind, i.e. (religiously) pious (a saint) godly (man), good, holy (one), merciful, saint, (un-) godly.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0553}/H9033/[H553]', 'inflected', 'heb', 'אָמַץ', '["ʼâmats"]', '["it will strengthen/ him"]', '["v"]', 'to be alert, physically (on foot) or mentally (in courage) confirm, be courageous (of good courage, stedfastly minded, strong, stronger), establish, fortify, harden, increase, prevail, strengthen (self), make strong (obstinate, speed).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0530}/H9020/[H529]', 'inflected', 'heb', 'אֱמוּנָה', '["ʼĕmûwnâh"]', '["and/ faithfulness/ my"]', '["n-f"]', 'literally firmness; figuratively security; morally fidelity faith(-ful, -ly, -ness, (man)), set office, stability, steady, truly, truth, verily.', 'or (shortened) אֱמֻנָה; feminine of 529;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8034}/H9020/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["and/ in/ name/ my"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5104H}/[H5102]', 'inflected', 'heb', 'נָהָר', '["nâhâr"]', '["and/ in the/ rivers","and/ on the/ rivers"]', '["n-m"]', 'a stream (including the sea; expectation the Nile, Euphrates, etc.); figuratively, prosperity flood, river.', 'from 5102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7121G}/H9030/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["he called/ me","he will call out to/ me","they will call to/ me"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414I}/H9033/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["I made/ him","I will make/ him","I will make/ it"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1285}/H9020/[H1262]', 'inflected', 'heb', 'בְּרִית', '["bᵉrîyth"]', '["and/ covenant/ my"]', '["n-f"]', 'a compact (because made by passing between pieces of flesh) confederacy, (con-) feder(-ate), covenant, league.', 'from 1262 (in the sense of cutting [like 1254]);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4941G}/H9020/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["and/ in/ judgments/ my"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0530}/H9020/[H529]', 'inflected', 'heb', 'אֱמוּנָה', '["ʼĕmûwnâh"]', '["with/ faithfulness/ my"]', '["n-f"]', 'literally firmness; figuratively security; morally fidelity faith(-ful, -ly, -ness, (man)), set office, stability, steady, truly, truth, verily.', 'or (shortened) אֱמֻנָה; feminine of 529;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6944G}/H9020/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["by/ holiness/ my"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H8121>', 'inflected', 'heb', 'כשמש', '["kha./She.mesh"]', '["like the/ sun"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3394}/[H3391]', 'inflected', 'heb', 'יָרֵחַ', '["yârêach"]', '["like/ [the] moon"]', '["n-m"]', 'the moon moon. Yrechow. See 3405.', 'from the same as 3391;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5010}/[H5010]', 'lemma', 'heb', 'נָאַר', '["nâʼar"]', '["he has repudiated","you have repudiated"]', '["v"]', 'to reject abhor, make void.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5145H}/H9023/[H5144]', 'inflected', 'heb', 'נֶזֶר', '["nezer"]', '["crown/ his"]', '["n-m"]', 'properly, something set apart, i.e. (abstractly) dedication (of a priet or Nazirite); hence (concretely) unshorn locks; also (by implication) a chaplet (especially of royalty) consecration, crown, hair, separation.', 'or נֵזֶר; from 5144;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1448}/H9023/[H1447]', 'inflected', 'heb', 'גְּדֵרָה', '["gᵉdêrâh"]', '["walls/ his"]', '["n-f"]', 'inclosure (especially for flocks) (sheep-) cote (fold) hedge, wall.', 'feminine of 1447;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4013}/H9023/[H1219]', 'inflected', 'heb', 'מִבְצָר', '["mibtsâr"]', '["fortifications/ its","strongholds/ his"]', '["n-m"]', 'a fortification, castle, or fortified city; figuratively, a defender (de-, most) fenced, fortress, (most) strong (hold).', 'also (in plural) feminine (Daniel 11:l5) מִבְצָרָה; from 1219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4288}/[H2846]', 'lemma', 'heb', 'מְחִתָּה', '["mᵉchittâh"]', '["[is the] ruin of","[is] destruction","[is] ruin","[the] ruin of","a ruin","ruin"]', '["n-f"]', 'properly, a dissolution; concretely, a ruin, or (abstractly) consternation destruction, dismaying, ruin, terror.', 'from 2846;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8155}/H9033/[H8155]', 'inflected', 'heb', 'שָׁסַס', '["shâçaç"]', '["they have plundered/ him"]', '["v"]', 'to plunder rifle, spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7934}/H9023/[H7931]', 'inflected', 'heb', 'שָׁכֵן', '["shâkên"]', '["to/ neighbors/ his"]', '["a"]', 'a resident; by extension, a fellow-citizen inhabitant, neighbour, nigh.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2892B}/H9023/[H2891]', 'inflected', 'heb', 'טֹהַר', '["ṭôhar"]', '["from/ luster/ his"]', '["n-m"]', 'literally brightness; ceremonially purification clearness, glory, purifying.', 'from 2891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4048}/[H4048]', 'lemma', 'heb', 'מָגַר', '["mâgar"]', '["thrown","you have thrown"]', '["v"]', 'to yield up; intensively, to precipitate cast down, terror.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0955}/[H954]', 'lemma', 'heb', 'בּוּשָׁה', '["bûwshâh"]', '["shame"]', '["n-f"]', 'shame shame.', 'feminine participle passive of 954;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0530}/H9021/[H529]', 'inflected', 'heb', 'אֱמוּנָה', '["ʼĕmûwnâh"]', '["in/ faithfulness/ your"]', '["n-f"]', 'literally firmness; figuratively security; morally fidelity faith(-ful, -ly, -ness, (man)), set office, stability, steady, truly, truth, verily.', 'or (shortened) אֱמֻנָה; feminine of 529;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375H}/H9040/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["bearing/ my"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2342H}/[H2342]', 'inflected', 'heb', 'חוּל', '["chûwl"]', '["and/ you brought forth"]', '["v"]', 'properly, to twist or whirl (in a circular or spiral manner), i.e. (specifically) to dance, to writhe in pain (especially of parturition) or fear; figuratively, to wait, to pervert bear, (make to) bring forth, (make to) calve, dance, drive away, fall grievously (with pain), fear, form, great, grieve, (be) grievous, hope, look, make, be in pain, be much (sore) pained, rest, shake, shapen, (be) sorrow(-ful), stay, tarry, travail (with pain), tremble, trust, wait carefully (patiently), be wounded.', 'or חִיל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8398}/[H2986]', 'inflected', 'heb', 'תֵּבֵל', '["têbêl"]', '["and/ [the] world"]', '["n-f"]', 'the earth (as moist and therefore inhabited); by extension, the globe; by implication, its inhabitants; specifically, a particular land, as Babylonia, Palestine habitable part, world.', 'from 2986;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5769G}/[H5956]', 'inflected', 'heb', 'עוֹלָם', '["ʻôwlâm"]', '["and/ from/ antiquity"]', '["n-m"]', 'properly, concealed, i.e. the vanishing point; generally, time out of mind (past or future), i.e. (practically) eternity; frequentatively, adverbial (especially with prepositional prefix) always alway(-s), ancient (time), any more, continuance, eternal, (for, (n-)) ever(-lasting, -more, of old), lasting, long (time), (of) old (time), perpetual, at any time, (beginning of the) world ( without end). Compare 5331, 5703.', 'or עֹלָם; from 5956;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1793B}/[H1792]', 'lemma', 'heb', 'דַּכָּא', '["dakkâʼ"]', '["crushed matter"]', '["a n-m"]', 'crushed (literally powder, or figuratively, contrite) contrite, destruction.', 'from 1792;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0821}/[H8104]', 'inflected', 'heb', 'אַשְׁמֻרָה', '["ʼashmurâh"]', '["and/ a watch"]', '["n-f"]', 'a night watch watch.', 'or אַשׁמוּרָה; or אַשׁמֹרֶת; (feminine) from 8104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2229}/H9038/[H2229]', 'inflected', 'heb', 'זָרַם', '["zâram"]', '["you flood/ them"]', '["v"]', 'to gush (as water) carry away as with a flood, pour out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6692A}/[H6692]', 'lemma', 'heb', 'צוּץ', '["tsûwts"]', '["he flourishes","it flourishes","it has blossomed","it will blossom","it will shine"]', '["v"]', 'to twinkle, i.e. glance; by analogy, to blossom (figuratively, flourish) bloom, blossom, flourish, shew self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5956}/H9025/[H5956]', 'inflected', 'heb', 'עָלַם', '["ʻâlam"]', '["concealed [sins]/ our"]', '["v"]', 'to veil from sight, i.e. conceal (literally or figuratively) × any ways, blind, dissembler, hide (self), secret (thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5678}/H9021/[H5676]', 'inflected', 'heb', 'עֶבְרָה', '["ʻebrâh"]', '["in/ fury/ your"]', '["n-f"]', 'an outburst of passion anger, rage, wrath.', 'feminine of 5676;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8141}/H9025/[H8138]', 'inflected', 'heb', 'שָׁנֶה', '["shâneh"]', '["years/ our"]', '["n-f"]', 'a year (as a revolution of time) whole age, × long, old, year(× -ly).', '(in plural or (feminine) שָׁנָה; from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1899}/[H1897]', 'lemma', 'heb', 'הֶגֶה', '["hegeh"]', '["a sigh"]', '["n-m"]', 'a muttering (in sighing, thought, or as thunder) mourning, sound, tale.', 'from 1897;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7296}/H9028/[H7292]', 'inflected', 'heb', 'רֹהָב', '["rôhâb"]', '["and/ pride/ their"]', '["n-m"]', 'pride strength.', 'from 7292;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0205H>', 'inflected', 'heb', 'ואון', '["va./''A.ven"]', '["and/ trouble"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1468}/[H1494]', 'lemma', 'heb', 'גּוּז', '["gûwz"]', '["it passes away"]', '["v"]', 'properly, to shear off; but used only in the (figuratively) sense of passing rapidly bring, cut off.', 'a primitive root (compare 1494);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2440}/[H2439]', 'lemma', 'heb', 'חִישׁ', '["chîysh"]', '["quickly"]', '["adv"]', 'properly, a hurry; hence (adverb) quickly soon.', 'from 2439;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5774A}/H9012/[H5775]', 'inflected', 'heb', 'עוּף', '["ʻûwph"]', '["and/ we flew away/ !"]', '["v n-f"]', 'to fly; also (by implication of dimness) to faint (from the darkness of swooning) brandish, be (wax) faint, flee away, fly (away), × set, shine forth, weary.', 'a primitive root; to cover (with wings or obscurity); hence (as denominative from 5775)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H3374}/H9021/[H3373]', 'inflected', 'heb', 'יִרְאָה', '["yirʼâh"]', '["and/ [is] like/ fear/ your"]', '["n-f"]', 'fear (also used as infinitive); morally, reverence × dreadful, × exceedingly, fear(-fulness).', 'feminine of 3373;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5162G}/[H5162]', 'inflected', 'heb', 'נָחַם', '["nâcham"]', '["and/ have compassion"]', '["v"]', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7646}/H9035/[H7646]', 'inflected', 'heb', 'שָׂבַע', '["sâbaʻ"]', '["satisfy/ us"]', '["v"]', 'to sate, i.e. fill to satisfaction (literally or figuratively) have enough, fill (full, self, with), be (to the) full (of), have plenty of, be satiate, satisfy (with), suffice, be weary of.', 'or שָׂבֵעַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8055}/H9035/[H8055]', 'inflected', 'heb', 'שָׂמַח', '["sâmach"]', '["make rejoice/ us"]', '["v"]', 'probably to brighten up, i.e. (figuratively) be (causatively, make) blithe or gleesome cheer up, be (make) glad, (have, make) joy(-ful), be (make) merry, (cause to, make to) rejoice, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6031B}/H9035/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["<of> [which] you afflicted/ us"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5278}/[H5276]', 'lemma', 'heb', 'נֹעַם', '["nôʻam"]', '["Favor","[the] kindness of","kindness"]', '["n-m"]', 'agreeableness, i.e. delight, suitableness, splendor or grace beauty, pleasant(-ness).', 'from 5276;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3559H}/H9012/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["establish/ !"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6341A}/[H6351]', 'inflected', 'heb', 'פַּח', '["pach"]', '["from/ [the] snare of","from/ a snare of"]', '["n-m"]', 'a (metallic) sheet (as pounded thin); also a spring net (as spread out like a lamina) gin, (thin) plate, snare.', 'from 6351;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3353}/[H3369]', 'lemma', 'heb', 'יָקוּשׁ', '["yâqûwsh"]', '["a fowler","fowlers"]', '["n-m"]', 'properly, entangled, i.e. by implication (intransitively) a snare, or (transitive) a snarer fowler, snare.', 'passive participle of 3369;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1698}/[H1696]', 'inflected', 'heb', 'דֶּבֶר', '["deber"]', '["from/ a plague","from/ a plague of"]', '["n-m"]', 'a pestilence murrain, pestilence, plague.', 'from 1696 (in the sense of destroying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0084}/H9023/[H83]', 'inflected', 'heb', 'אֶבְרָה', '["ʼebrâh"]', '["with/ pinion/ his"]', '["n-f"]', 'feather, wing.', 'feminine of 83');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5507}/[H5503]', 'inflected', 'heb', 'סֹחֵרָה', '["çôchêrâh"]', '["and/ a wall"]', '["n-f"]', 'something surrounding the person, i.e. a shield buckler.', 'properly, active participle feminine of 5503;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0571G}/H9023/[H539]', 'inflected', 'heb', 'אֶמֶת', '["ʼemeth"]', '["faithfulness/ his"]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2671}/[H2686]', 'inflected', 'heb', 'חֵץ', '["chêts"]', '["from/ an arrow"]', '["n-m"]', 'properly, a piercer, i.e. an arrow; by implication, a wound; figuratively, (of God) thunder-bolt; the shaft of a spear archer, arrow, dart, shaft, staff, wound.', 'from 2686; also by interchange for 6086');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0652}/[H651]', 'inflected', 'heb', 'אֹפֶל', '["ʼôphel"]', '["[which] in the/ darkness"]', '["n-m"]', 'dusk darkness, obscurity, privily.', 'from the same as 651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H6986>', 'inflected', 'heb', 'מקטב', '["mi./Ke.tev"]', '["from/ destruction"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7736}/[H7736]', 'lemma', 'heb', 'שׁוּד', '["shûwd"]', '["[which] it will devastate"]', '["v"]', 'properly, to swell up, i.e. figuratively (by implication of insolence) to devastate waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6672A}/[H6671]', 'lemma', 'heb', 'צֹהַר', '["tsôhar"]', '["[the] noon<s>","noon<s>"]', '["n-m"]', 'a light (i.e. window); dual double light, i.e. noon midday, noon(-day, -tide), window.', 'from 6671;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H6654>/H9021', 'inflected', 'heb', 'מצדך', '["mi./tzi.de./Kha"]', '["from/ side/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7233}/[H7231]', 'inflected', 'heb', 'רְבָבָה', '["rᵉbâbâh"]', '["and/ ten thousand"]', '["n-f"]', 'abundance (in number), i.e. (specifically) a myriad (whether definite or indefinite) many, million, × multiply, ten thousand.', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3225G}/H9021/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["from/ right [hand]/ your"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8011}/[H7966]', 'inflected', 'heb', 'שִׁלֻּמָה', '["shillumâh"]', '["and/ [the] retribution of"]', '["n-f"]', 'retribution recompense.', 'feminine of 7966;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4583}/H9021/[H5772]', 'inflected', 'heb', 'מָעוֹן', '["mâʻôwn"]', '["dwelling place/ your"]', '["n-m"]', 'an abode, of God (the Tabernacle or the Temple), men (their home) or animals (their lair); hence, a retreat (asylum) den, dwelling((-) place), habitation.', 'or מָעִין; (1 Chronicles 4:41), from the same as 5772;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5061}/[H5060]', 'inflected', 'heb', 'נֶגַע', '["negaʻ"]', '["and/ plague"]', '["n-m"]', 'a blow (figuratively, infliction); also (by implication) a spot (concretely, a leprous person or dress) plague, sore, stricken, stripe, stroke, wound.', 'from 5060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375G}/H9031/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["they will lift up/ you"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6620>', 'inflected', 'heb', 'ופתן', '["va./Fe.ten"]', '["and/ a cobra"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7429}/[H7429]', 'lemma', 'heb', 'רָמַס', '["râmaç"]', '["[the] trampler","[who] he tramples","he will trample","they will be trampled","to trample","you are trampling","you will trample"]', '["v"]', 'to tread upon (as a potter, in walking or abusively) oppressor, stamp upon, trample (under feet), tread (down, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8577M}/[H8565]', 'inflected', 'heb', 'תַּנִּין', '["tannîyn"]', '["and/ a serpent"]', '["n-m"]', 'a marine or land monster, i.e. sea-serpent or jackal dragon, sea-monster, serpent, whale.', 'or תַּנִּים; (Ezekiel 29:3), intensive from the same as 8565;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6403}/H9033/[H6403]', 'inflected', 'heb', 'פָּלַט', '["pâlaṭ"]', '["and/ I will deliver/ him"]', '["v"]', 'to slip out, i.e. escape; causatively, to deliver calve, carry away safe, deliver, (cause to) escape.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7682}/H9033/[H7682]', 'inflected', 'heb', 'שָׂגַב', '["sâgab"]', '["I will set on high/ him"]', '["v"]', 'to be (causatively, make) lofty, especially inaccessible; by implication, safe, strong; used literally and figuratively defend, exalt, be excellent, (be, set on) high, lofty, be safe, set up (on high), be too strong.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6030B}/H9033/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["and/ I will answer/ him"]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2502A}/H9033/[H2502]', 'inflected', 'heb', 'חָלַץ', '["châlats"]', '["I will rescue/ him"]', '["v"]', 'to pull off; hence (intensively) to strip, (reflex.) to depart; by implication, to deliver, equip (for fight); present, strengthen arm (self), (go, ready) armed (× man, soldier), deliver, draw out, make fat, loose, (ready) prepared, put off, take away, withdraw self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3513G}/H9033/[H3513]', 'inflected', 'heb', 'כָּבַד', '["kâbad"]', '["and/ I will honor/ him","and/ [is] honoring/ him"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7646}/H9033/[H7646]', 'inflected', 'heb', 'שָׂבַע', '["sâbaʻ"]', '["I will satisfy/ him","you should be surfeited with/ it"]', '["v"]', 'to sate, i.e. fill to satisfaction (literally or figuratively) have enough, fill (full, self, with), be (to the) full (of), have plenty of, be satiate, satisfy (with), suffice, be weary of.', 'or שָׂבֵעַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3444}/H9020/[H3467]', 'inflected', 'heb', 'יְשׁוּעָה', '["yᵉshûwʻâh"]', '["on/ salvation/ my"]', '["n-f"]', 'something saved, i.e. (abstractly) deliverance; hence, aid, victory, prosperity deliverance, health, help(-ing), salvation, save, saving (health), welfare.', 'feminine passive participle of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2167}/[H2168]', 'inflected', 'heb', 'זָמַר', '["zâmar"]', '["and/ to/ sing praises"]', '["v"]', 'properly, to touch the strings or parts of a musical instrument, i.e. play upon it; to make music, accompanied by the voice; hence to celebrate in song and music give praise, sing forth praises, psalms.', 'a primitive root (perhaps identical with 2168 through the idea of striking with the fingers);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1902H}/[H1897]', 'lemma', 'heb', 'הִגָּיוֹן', '["higgâyôwn"]', '["a melody"]', '["n-m"]', 'a murmuring sound, i.e. a musical notation (probably similar to the modern affettuoso to indicate solemnity of movement); by implication, a machination device, Higgaion, meditation, solemn sound.', 'intensive from 1897;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8055}/H9030/[H8055]', 'inflected', 'heb', 'שָׂמַח', '["sâmach"]', '["you have made rejoice/ me"]', '["v"]', 'probably to brighten up, i.e. (figuratively) be (causatively, make) blithe or gleesome cheer up, be (make) glad, (have, make) joy(-ful), be (make) merry, (cause to, make to) rejoice, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6467}/H9021/[H6466]', 'inflected', 'heb', 'פֹּעַל', '["pôʻal"]', '["by/ deed[s]/ your"]', '["n-m"]', 'an act or work (concretely) act, deed, do, getting, maker, work.', 'from 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6009}/[H6009]', 'lemma', 'heb', 'עָמַק', '["ʻâmaq"]', '["make deep","someone has made [it] deep","they are deep","they have made deep"]', '["v"]', 'to be (causatively, make) deep (literally or figuratively) (be, have, make, seek) deep(-ly), depth, be profound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4284}/H9021/[H2803]', 'inflected', 'heb', 'מַחֲשָׁבָה', '["machăshâbâh"]', '["plans/ your","thoughts/ your"]', '["n-f"]', 'a contrivance, i.e. (concretely) a texture, machine, or (abstractly) intention, plan (whether bad, a plot; or good, advice) cunning (work), curious work, device(-sed), imagination, invented, means, purpose, thought.', 'or מַחֲשֶׁבֶת; from 2803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3684}/[H3688]', 'inflected', 'heb', 'כְּסִיל', '["kᵉçîyl"]', '["and/ O fools","and/ a fool","and/ fools"]', '["n-m"]', 'properly, fat, i.e. (figuratively) stupid or silly fool(-ish).', 'from 3688;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6524A}/[H6524]', 'inflected', 'heb', 'פָּרַח', '["pârach"]', '["when/ flourish"]', '["v"]', 'to break forth as a bud, i.e. bloom; generally, to spread; specifically, to fly (as extending the wings); figuratively, to flourish × abroad, × abundantly, blossom, break forth (out), bud, flourish, make fly, grow, spread, spring (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7214}/[H7213]', 'inflected', 'heb', 'רְאֵם', '["rᵉʼêm"]', '["like/ a wild ox"]', '["n-m"]', 'a wild bull (from its conspicuousness) unicorn.', 'or רְאֵיםlemma רְאיֵם second vowel, corrected to רְאֵים; or רֵים; or רֵם; from 7213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7790}/H9020/[H7889]', 'inflected', 'heb', 'שׁוּר', '["shûwr"]', '["on/ enemies/ my"]', '["n-m"]', 'a foe (as lying in wait) enemy.', 'from 7889;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6965J}/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["in <the>/ [those who] rise up","when/ rose up"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H8558>', 'inflected', 'heb', 'כתמר', '["ka./ta.Mar"]', '["like <the>/ palm tree"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5107}/H9013/[H5107]', 'inflected', 'heb', 'נוּב', '["nûwb"]', '["they will bear fruit/ !"]', '["v"]', 'to germinate, i.e. (figuratively) to (causatively, make) flourish; also (of words), to utter bring forth (fruit), make cheerful, increase.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7488B>', 'inflected', 'heb', 'ורעננים', '["ve./ra.''a.na.Nim"]', '["and/ fresh"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1348}/[H1342]', 'lemma', 'heb', 'גֵּאוּת', '["gêʼûwth"]', '["<the> pride of","[the] majesty of","a rising up of","majesty"]', '["n-f"]', 'the same as 1346 excellent things, lifting up, majesty, pride, proudly, raging.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1796}/H9028/[H1794]', 'inflected', 'heb', 'דֳּכִי', '["dŏkîy"]', '["pounding/ their"]', '["n-m"]', 'a dashing of surf wave.', 'from 1794;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5713B}/H9021/[H5707]', 'inflected', 'heb', 'עֵדָה', '["ʻêdâh"]', '["<of> testimonies/ your","testimonies/ your"]', '["n-f"]', 'testimony testimony, witness. Compare 5712.', 'feminine of 5707 in its techn. sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4998}/[H4998]', 'lemma', 'heb', 'נָאָה', '["nâʼâh"]', '["it is befitting","they are beautiful"]', '["v"]', 'properly, to be at home, i.e. (by implication) to be pleasant (or suitable), i.e. beautiful be beautiful, become, be comely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1576}/[H1580]', 'lemma', 'heb', 'גְּמוּל', '["gᵉmûwl"]', '["[the] dealing of","[the] recompense of","recompense"]', '["n-m"]', 'treatment, i.e. an act (of good or ill); by implication, service or requital as hast served, benefit, desert, deserving, that which he hath given, recompense, reward.', 'from 1580;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5193}/[H5193]', 'inflected', 'heb', 'נָטַע', '["nâṭaʻ"]', '["¿/ [the] planter of"]', '["v"]', 'properly, to strike in, i.e. fix; specifically, to plant (literally or figuratively) fastened, plant(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3256}/[H3256]', 'inflected', 'heb', 'יָסַר', '["yâçar"]', '["¿/ [the] discipliner of"]', '["v"]', 'to chastise, literally (with blows) or figuratively (with words); hence, to instruct bind, chasten, chastise, correct, instruct, punish, reform, reprove, sore, teach.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3925G}/[H3925]', 'inflected', 'heb', 'לָמַד', '["lâmad"]', '["the/ [one who] teaches","who/ trains"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3256}/H9033/[H3256]', 'inflected', 'heb', 'יָסַר', '["yâçar"]', '["she instructed/ him","you discipline/ him"]', '["v"]', 'to chastise, literally (with blows) or figuratively (with words); hence, to instruct bind, chasten, chastise, correct, instruct, punish, reform, reprove, sore, teach.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H8451}/H9021/[H3384]', 'inflected', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["and/ from/ law/ your"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3925G}/H9033/[H3925]', 'inflected', 'heb', 'לָמַד', '["lâmad"]', '["you teach/ him"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8252}/[H8252]', 'inflected', 'heb', 'שָׁקַט', '["shâqaṭ"]', '["to/ give quiet"]', '["v"]', 'to repose (usually figurative) appease, idleness, (at, be at, be in, give) quiet(-ness), (be at, be in, give, have, take) rest, settle, be still.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1745>', 'opaque', 'heb', 'דּוּמָה', '["dûwmâh"]', '["silence"]', '["n-f"]', 'silence; figuratively, death silence.', 'from an unused root meaning to be dumb (compare 1820);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8312}/H9020/[H5587]', 'inflected', 'heb', 'שַׂרְעַף', '["sarʻaph"]', '["disquieting thoughts/ my"]', '["n-m"]', 'cogitation thought.', 'for 5587;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7130H}/H9020/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["in/ inner being/ my"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8575}/H9021/[H5162]', 'inflected', 'heb', 'תַּנְחוּם', '["tanchûwm"]', '["consolations/ your"]', '["n"]', 'compassion, solace comfort, consolation.', 'or תַּנְחֻם; and (feminine) תַּנְחוּמָה; from 5162;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8173B}/[H8173]', 'lemma', 'heb', 'שָׁעַע', '["shâʻaʻ"]', '["I delight","I will delight myself","they delighted","you will be fondled"]', '["v"]', '(in a good acceptation) to look upon (with complacency), i.e. fondle, please or amuse (self); (in a bad one) to look about (in dismay), i.e. stare cry (out) (by confusion with 7768), dandle, delight (self), play, shut.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H2266}/H9031/[H2266]', 'inflected', 'heb', 'חָבַר', '["châbar"]', '["¿/ will it be joined to/ you"]', '["v"]', 'to join (literally or figuratively); specifically (by means of spells) to fascinate charm(-er), be compact, couple (together), have fellowship with, heap up, join (self, together), league.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3335I}/[H3334]', 'lemma', 'heb', 'יָצַר', '["yâtsar"]', '["I have planned","[am] about to fashion","[which] fashions"]', '["v"]', 'to mould into a form; especially as a potter; figuratively, to determine (i.e. form a resolution) × earthen, fashion, form, frame, make(-r), potter, purpose.', 'probably identical with 3334 (through the squeezing into shape); (compare 3331);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0205G>/H9028', 'opaque', 'heb', 'אָוֶן', '["ʼâven"]', '["wickedness/ their"]', '["n-m"]', 'strictly nothingness; also trouble, vanity, wickedness; specifically an idol affliction, evil, false, idol, iniquity, mischief, mourners(-ing), naught, sorrow, unjust, unrighteous, vain, vanity, wicked(-ness). Compare 369.', 'from an unused root perhaps meaning properly, to pant (hence, to exert oneself, usually in vain; to come to naught);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7451I}/H9028/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["and/ in/ evil/ their"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2158}/[H2167]', 'inflected', 'heb', 'זָמִיר', '["zâmîyr"]', '["with/ songs"]', '["n-m"]', 'a song to be accompanied with instrumental music psalm(-ist), singing, song.', 'or זָמִר; and (feminine) זְמִרָה; from 2167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4278}/[H2713]', 'lemma', 'heb', 'מֶחְקָר', '["mechqâr"]', '["[the] depths of"]', '["n-m"]', 'properly, scrutinized, i.e. (by implication) a recess deep place.', 'from 2713;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8443}/[H3286]', 'inflected', 'heb', 'תּוֹעָפָה', '["tôwʻâphâh"]', '["and/ [the] peaks of"]', '["n-f"]', '(only in plural collective) weariness, i.e. (by implication) toil (treasure so obtained) or speed plenty, strength.', 'from 3286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3006}/[H3004]', 'inflected', 'heb', 'יַבֶּשֶׁת', '["yabbesheth"]', '["and/ [the] dry land"]', '["n-f"]', 'dry ground dry land.', 'a variation of 3004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3766}/[H3766]', 'inflected', 'heb', 'כָּרַע', '["kâraʻ"]', '["and/ let us kneel down"]', '["v"]', 'to bend the knee; by implication, to sink, to prostrate bow (down, self), bring down (low), cast down, couch, fall, feeble, kneeling, sink, smite (stoop) down, subdue, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213H}/H9035/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["he made/ us","maker/ our"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4830}/H9023/[H7462]', 'inflected', 'heb', 'מִרְעִית', '["mirʻîyth"]', '["pasture/ his"]', '["n-f"]', 'pasturage; concretely, a flock flock, pasture.', 'from 7462 in the sense of feeding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4809G}/[H4808]', 'inflected', 'heb', 'מְרִיבָה', '["Mᵉrîybâh"]', '["like/ Meribah"]', '["n-pr-loc"]', 'Meribah, the name of two places in the Desert Meribah.', 'the same as 4808;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5254G}/H9030/[H5254]', 'inflected', 'heb', 'נָסָה', '["nâçâh"]', '["they put to [the] test/ me"]', '["v"]', 'to test; by implication, to attempt adventure, assay, prove, tempt, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6467}/H9020/[H6466]', 'inflected', 'heb', 'פֹּעַל', '["pôʻal"]', '["work/ my"]', '["n-m"]', 'an act or work (concretely) act, deed, do, getting, maker, work.', 'from 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6962}/[H6962]', 'lemma', 'heb', 'קוּט', '["qûwṭ"]', '["I loathed","do I loathe?"]', '["v"]', 'properly, to cut off, i.e. (figuratively) detest begrieved, loathe self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935G}/H9013/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["they will go/ !"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4496H}/H9020/[H4495]', 'inflected', 'heb', 'מְנוּחָה', '["mᵉnûwchâh"]', '["[is] resting place/ my","rest/ my"]', '["n-f"]', 'repose or (adverbially) peacefully; figuratively, consolation (specifically, matrimony); hence (concretely) an abode comfortable, ease, quiet, rest(-ing place), still.', 'or מְנֻחָה; feminine of 4495;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8597}/[H6286]', 'inflected', 'heb', 'תִּפְאָרָה', '["tiphʼârâh"]', '["and/ [are the] honor of","and/ [the] splendor of","and/ splendor"]', '["n-f"]', 'ornament (abstractly or concretely, literally or figuratively) beauty(-iful), bravery, comely, fair, glory(-ious), honour, majesty.', 'or תִּפְאֶרֶת; from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4720}/H9023/[H6942]', 'inflected', 'heb', 'מִקְדָּשׁ', '["miqdâsh"]', '["[are] in/ sanctuary/ his"]', '["n-m"]', 'a consecrated thing or place, especially, a palace, sanctuary (whether of Jehovah or of idols) or asylum chapel, hallowed part, holy place, sanctuary.', 'or מִקְּדָשׁ; (Exodus 15:17), from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2691A}/H9023/[H2690]', 'inflected', 'heb', 'חָצֵר', '["châtsêr"]', '["to/ courts/ his"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0530}/H9023/[H529]', 'inflected', 'heb', 'אֱמוּנָה', '["ʼĕmûwnâh"]', '["by/ faithfulness/ his","in/ faithfulness/ his"]', '["n-f"]', 'literally firmness; figuratively security; morally fidelity faith(-ful, -ly, -ness, (man)), set office, stability, steady, truly, truth, verily.', 'or (shortened) אֱמֻנָה; feminine of 529;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3857}/[H3857]', 'inflected', 'heb', 'לָהַט', '["lâhaṭ"]', '["and/ it may burn up"]', '["v"]', 'properly, to lick, i.e. (by implication) to blaze burn (up), set on fire, flaming, kindle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1300B}/H9023/[H1299]', 'inflected', 'heb', 'בָּרָק', '["bârâq"]', '["lightning flashes/ his"]', '["n-m"]', 'lightning; by analogy, a gleam; concretely, a flashing sword bright, glitter(-ing sword), lightning.', 'from 1299;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1984H}/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["those/ [who] boast","who/ [-ever] boasts"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0457}/[H408]', 'inflected', 'heb', 'אֱלִיל', '["ʼĕlîyl"]', '["in <the>/ worthless idols"]', '["a-m"]', 'good for nothing, by analogy vain or vanity; specifically an idol idol, no value, thing of nought.', 'apparently from 408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3477G}/[H3474]', 'inflected', 'heb', 'יָשָׁר', '["yâshâr"]', '["and/ for/ [people] upright of","and/ to/ [people] upright"]', '["a"]', 'straight (literally or figuratively) convenient, equity, Jasher, just, meet(-est), pleased well right(-eous), straight, (most) upright(-ly, -ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0530}/H9023/[H529]', 'inflected', 'heb', 'אֱמוּנָה', '["ʼĕmûwnâh"]', '["and/ faithfulness/ his"]', '["n-f"]', 'literally firmness; figuratively security; morally fidelity faith(-ful, -ly, -ness, (man)), set office, stability, steady, truly, truth, verily.', 'or (shortened) אֱמֻנָה; feminine of 529;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6476}/[H6476]', 'lemma', 'heb', 'פָּצַח', '["pâtsach"]', '["break forth","people have broken forth","they have broken in pieces","they will break forth"]', '["v"]', 'to break out (in joyful sound) break (forth, forth into joy), make a loud noise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4222}/[H4222]', 'lemma', 'heb', 'מָחָא', '["mâchâʼ"]', '["let them clap","they will clap"]', '["v"]', 'to rub or strike the hands together (in exultation) clap.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5120}/[H5120]', 'lemma', 'heb', 'נוּט', '["nûwṭ"]', '["let it quake"]', '["v"]', 'to quake be moved.', NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H1916>', 'inflected', 'heb', 'להדם', '["la./ha.Dom"]', '["to/ [the] footstool of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3548}/H9023/[H3547]', 'inflected', 'heb', 'כֹּהֵן', '["kôhên"]', '["[were] among/ priests/ his"]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7121G}/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["[was] among/ [those who] call on"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5713B}/H9023/[H5707]', 'inflected', 'heb', 'עֵדָה', '["ʻêdâh"]', '["<of> testimonies/ his","testimonies/ his"]', '["n-f"]', 'testimony testimony, witness. Compare 5712.', 'feminine of 5707 in its techn. sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5949}/H9028/[H5953]', 'inflected', 'heb', 'עֲלִילָה', '["ʻălîylâh"]', '["deeds/ their","practices/ their"]', '["n-f"]', 'an exploit (of God), or a performance (of man, often in a bad sense); by implication, an opportunity act(-ion), deed, doing, invention, occasion, work.', 'or עֲלִלָה; from 5953 in the sense of effecting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8426}/[H3034]', 'inflected', 'heb', 'תּוֹדָה', '["tôwdâh"]', '["for/ thanksgiving"]', '["n-f"]', 'properly, an extension of the hand, i.e. (by implication) avowal, or (usually) adoration; specifically, a choir of worshippers confession, (sacrifice of) praise, thanks(-giving, offering).', 'from 3034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7445}/[H7442]', 'inflected', 'heb', 'רְנָנָה', '["rᵉnânâh"]', '["with/ cries of joy"]', '["n-f"]', 'a shout (for joy) joyful (voice), singing, triumphing.', 'from 7442;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2691A}/H9023/[H2690]', 'inflected', 'heb', 'חָצֵר', '["châtsêr"]', '["courts/ his"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8416}/[H1984]', 'inflected', 'heb', 'תְּהִלָּה', '["tᵉhillâh"]', '["with/ praise"]', '["n-f"]', 'laudation; specifically (concretely) a hymn praise.', 'from 1984;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7846}/[H7750]', 'lemma', 'heb', 'שֵׂט', '["sêṭ"]', '["rebels","swerving deeds"]', '["n-m"]', 'a departure from right, i.e. sin revolter, that turn aside.', 'or סֵט; from 7750;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3960}/[H3956]', 'lemma', 'heb', 'לָשַׁן', '["lâshan"]', '["[one who] slanders","you slander"]', '["v"]', 'to wag the tongue, i.e. to calumniate accuse, slander.', 'a primitive root; properly, to lick; but used only as a denominative from 3956;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869H}/[H5869]', 'lemma', 'heb', 'עַיִן', '["ʻayin"]', '["eyes","eyes of"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869H}/H9020/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["eyes/ my"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0539}/[H541]', 'inflected', 'heb', 'אָמַן', '["ʼâman"]', '["[will be] on/ [the] faithful [people] of"]', '["v"]', 'properly, to build up or support; to foster as a parent or nurse; figuratively to render (or be) firm or faithful, to trust or believe, to be permanent or quiet; morally to be true or certain; hence, assurance, believe, bring up, establish, fail, be faithful (of long continuance, stedfast, sure, surely, trusty, verified), nurse, (-ing father), (put), trust, turn to the right.', 'a primitive root; (Isaiah 30:21; interchangeable with 541, to go to the right hand)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8334}/H9030/[H8334]', 'inflected', 'heb', 'שָׁרַת', '["shârath"]', '["he will serve/ me","servants/ my"]', '["v"]', 'to attend as a menial or worshipper; figuratively, to contribute to minister (unto), (do) serve(-ant, -ice, -itor), wait on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5848C}/[H5848]', 'lemma', 'heb', 'עָטַף', '["ʻâṭaph"]', '["he grows faint","it was fainting away","it will grow faint"]', '["v"]', 'to shroud, i.e. clothe (whether transitive or reflex.); hence (from the idea of darkness) to languish cover (over), fail, faint, feebler, hide self, be overwhelmed, swoon.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4168}/[H3344]', 'lemma', 'heb', 'מוֹקֵד', '["môwqêd"]', '["a hearth","hearths of"]', '["n-m"]', 'a fire or fuel; abstractly, a conflagration burning, hearth.', 'from 3344;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0398}/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["from/ eating"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1320}/H9020/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["to/ flesh/ my"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6893}/[H6958]', 'inflected', 'heb', 'קָאַת', '["qâʼath"]', '["<to>/ a desert owl of"]', '["n-f"]', 'probably the pelican (from vomiting) cormorant.', 'from 6958;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H3563B>', 'inflected', 'heb', 'ככוס', '["ke./Khos"]', '["like/ an owl of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0909}/[H909]', 'lemma', 'heb', 'בָּדַד', '["bâdad"]', '["[is] an isolated [one]","isolated"]', '["v"]', 'to divide, i.e. (reflex.) be solitary alone.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1984I}/H9030/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["[those who] mock/ me"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3899H}/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["[will be] like/ bread of","like <the>/ food"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8249}/H9020/[H8248]', 'inflected', 'heb', 'שִׁקֻּו', '["shiqquv"]', '["and/ drinks/ my"]', '["n-m"]', '(plural collective) a draught drink.', 'from 8248;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4537}/[H4537]', 'lemma', 'heb', 'מָסַךְ', '["mâçak"]', '["I have mixed","[which] I have mixed","he has mixed","she has mixed"]', '["v"]', 'to mix, especially wine (with spices) mingle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7110A}/H9021/[H7107]', 'inflected', 'heb', 'קֶצֶף', '["qetseph"]', '["and/ wrath/ your"]', '["n-m"]', 'a splinter (as chipped off); figuratively, rage or strife foam, indignation, × sore, wrath.', 'from 7107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7993}/H9030/[H7993]', 'inflected', 'heb', 'שָׁלַךְ', '["shâlak"]', '["and/ you have thrown away/ me","and/ you have thrown/ me"]', '["v"]', 'to throw out, down or away (literally or figuratively) adventure, cast (away, down, forth, off, out), hurl, pluck, throw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2143}/H9021/[H2142]', 'inflected', 'heb', 'זֵכֶר', '["zêker"]', '["and/ remembrance of/ you"]', '["n-m"]', 'a memento, abstractly recollection (rarely if ever); by implication, commemoration memorial, memory, remembrance, scent.', 'or זֶכֶר; from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2603A}/H9034/[H2583]', 'inflected', 'heb', 'חָנַן', '["chânan"]', '["to/ show favor to/ it"]', '["v"]', 'properly, to bend or stoop in kindness to an inferior; to favor, bestow; causatively to implore (i.e. move to favor by petition) beseech, × fair, (be, find, shew) favour(-able), be (deal, give, grant (gracious(-ly), intreat, (be) merciful, have (shew) mercy (on, upon), have pity upon, pray, make supplication, × very.', 'a primitive root (compare 2583);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3519}/H9023/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["in/ glory/ his","in/ splendor/ its"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6199}/[H6209]', 'inflected', 'heb', 'עַרעָר', '["ʻarʻâr"]', '["the/ destitute person"]', '["a"]', 'naked, i.e. (figuratively) poor destitute. See also 6176.', 'from 6209;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6605A}/[H6605]', 'inflected', 'heb', 'פָּתַח', '["pâthach"]', '["to/ be let loose","to/ open","to/ set free"]', '["v"]', 'to open wide (literally or figuratively); specifically, to loosen, begin, plough, carve appear, break forth, draw (out), let go free, (en-) grave(-n), loose (self), (be, be set) open(-ing), put off, ungird, unstop, have vent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8416}/H9023/[H1984]', 'inflected', 'heb', 'תְּהִלָּה', '["tᵉhillâh"]', '["and/ praise/ his"]', '["n-f"]', 'laudation; specifically (concretely) a hymn praise.', 'from 1984;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6908}/[H6908]', 'inflected', 'heb', 'קָבַץ', '["qâbats"]', '["when/ gather"]', '["v"]', 'to grasp, i.e. collect assemble (selves), gather (bring) (together, selves together, up), heap, resort, × surely, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3830}/[H3847]', 'inflected', 'heb', 'לְבוּשׁ', '["lᵉbûwsh"]', '["like <the>/ clothing"]', '["n-m"]', 'a garment (literally or figuratively); by implication (euphemistically) a wife apparel, clothed with, clothing, garment, raiment, vestment, vesture.', 'or לְבֻשׁ; from 3847;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2498}/H9038/[H2498]', 'inflected', 'heb', 'חָלַף', '["châlaph"]', '["you will change/ them"]', '["v"]', 'properly, to slide by, i.e. (by implication) to hasten away, pass on, spring up, pierce or change abolish, alter, change, cut off, go on forward, grow up, be over, pass (away, on, through), renew, sprout, strike through.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8141}/H9021/[H8138]', 'inflected', 'heb', 'שָׁנֶה', '["shâneh"]', '["and/ years/ your"]', '["n-f"]', 'a year (as a revolution of time) whole age, × long, old, year(× -ly).', '(in plural or (feminine) שָׁנָה; from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7130G}/H9020/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["inward parts/ my"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1576}/H9023/[H1580]', 'inflected', 'heb', 'גְּמוּל', '["gᵉmûwl"]', '["benefits/ his"]', '["n-m"]', 'treatment, i.e. an act (of good or ill); by implication, service or requital as hast served, benefit, desert, deserving, that which he hath given, recompense, reward.', 'from 1580;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5545}/[H5545]', 'inflected', 'heb', 'סָלַח', '["çâlach"]', '["who/ forgives"]', '["v"]', 'to forgive forgive, pardon, spare.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5771G}/H9022/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["iniquity/ your"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8463}/H9022/[H2456]', 'inflected', 'heb', 'תַּחֲלוּא', '["tachălûwʼ"]', '["diseases/ your"]', '["n-m"]', 'a malady disease, × grievous, (that are) sick(-ness).', 'or תַּחֲלֻא; from 2456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7845G}/[H7743]', 'inflected', 'heb', 'שַׁחַת', '["shachath"]', '["from/ [the] pit","from/ [the] pit of","from/ a pit"]', '["n-f"]', 'a pit (especially as a trap); figuratively, destruction corruption, destruction, ditch, grave, pit.', 'from 7743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2416E}/H9022/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["life/ your"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5849B}/H9032/[H5849]', 'inflected', 'heb', 'עָטַר', '["ʻâṭar"]', '["who/ crowns/ you"]', '["v"]', 'to encircle (for attack or protection); especially to crown (literally or figuratively) compass, crown.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7356B}/[H7355]', 'inflected', 'heb', 'רַחַם', '["racham"]', '["and/ [the] compassion<s> of","and/ compassion<s>"]', '["n-f"]', 'compassion (in the plural); by extension, the womb (as cherishing the fetus); by implication, a maiden bowels, compassion, damsel, tender love, (great, tender) mercy, pity, womb.', 'from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7646}/[H7646]', 'inflected', 'heb', 'שָׂבַע', '["sâbaʻ"]', '["who/ satisfies"]', '["v"]', 'to sate, i.e. fill to satisfaction (literally or figuratively) have enough, fill (full, self, with), be (to the) full (of), have plenty of, be satiate, satisfy (with), suffice, be weary of.', 'or שָׂבֵעַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5716}/H9022/[H5710]', 'inflected', 'heb', 'עֲדִי', '["ʻădîy"]', '["ornament[s]/ your"]', '["n-m"]', 'finery; generally an outfit; specifically, a headstall × excellent, mouth, ornament.', 'from 5710 in the sense of trappings;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5271A}/H9022/[H5288]', 'inflected', 'heb', 'נָעוּר', '["nâʻûwr"]', '["youth<s>/ your"]', '["n-m n-f"]', '(only in plural collective or emphatic form) youth, the state (juvenility) or the persons (young people) childhood, youth.', 'or נָעֻר; and (feminine) נְעֻרָה; properly, passive participle from 5288 as denominative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2399}/H9025/[H2398]', 'inflected', 'heb', 'חֵטְא', '["chêṭᵉʼ"]', '["according to/ sins/ our"]', '["n-m"]', 'a crime or its penalty fault, × grievously, offence, (punishment of) sin.', 'from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5771G}/H9025/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["according to/ iniquities/ our"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1361}/[H1361]', 'inflected', 'heb', 'גָּבַהּ', '["gâbahh"]', '["as/ is high"]', '["v"]', 'to soar, i.e. be lofty; figuratively, to be haughty exalt, be haughty, be (make) high(-er), lift up, mount up, be proud, raise up great height, upward.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7368}/[H7368]', 'inflected', 'heb', 'רָחַק', '["râchaq"]', '["as/ is far away"]', '["v"]', 'to widen (in any direction), i.e. (intransitively) recede or (transitively) remove (literally or figuratively, of place or relation) (a-, be, cast, drive, get, go, keep (self), put, remove, be too, (wander), withdraw) far (away, off), loose, × refrain, very, (be) a good way (off).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4628}/[H6150]', 'inflected', 'heb', 'מַעֲרָב', '["maʻărâb"]', '["from/ [the] setting place","from/ west"]', '["n-m"]', 'the west (as a region of the evening sun) west.', 'or (feminine) מַעֲרָבָה; from 6150, in the sense of shading;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7355}/[H7355]', 'inflected', 'heb', 'רָחַם', '["râcham"]', '["as/ has compassion"]', '["v"]', 'to fondle; by implication, to love, especially to compassionate have compassion (on, upon), love, (find, have, obtain, shew) mercy(-iful, on, upon), (have) pity, Ruhamah, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3336}/H9025/[H3335]', 'inflected', 'heb', 'יֵצֶר', '["yêtser"]', '["form/ our"]', '["n-m"]', 'a form; figuratively, conception (i.e. purpose) frame, thing framed, imagination, mind, work.', 'from 3335;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6666}/H9023/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["and/ own righteousness/ his","and/ righteousness/ his"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6490}/H9023/[H6485]', 'inflected', 'heb', 'פִּקּוּד', '["piqqûwd"]', '["<of> precepts/ his","precepts/ his"]', '["n-m"]', 'properly, appointed, i.e. a mandate (of God; plural only, collectively, for the Law) commandment, precept, statute.', 'or פִּקֻּד; from 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4438}/H9023/[H4427]', 'inflected', 'heb', 'מַלְכוּת', '["malkûwth"]', '["and/ kingdom/ his"]', '["n-f"]', 'a rule; concretely, a dominion empire, kingdom, realm, reign, royal.', 'or מַלְכֻת; or (in plural) מַלְכֻיָּה; from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8008}/[H8071]', 'inflected', 'heb', 'שַׂלְמָה', '["salmâh"]', '["like <the>/ garment"]', '["n-f"]', 'a dress clothes, garment, raiment.', 'transp. for 8071;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3407}/[H3415]', 'inflected', 'heb', 'יְרִיעָה', '["yᵉrîyʻâh"]', '["like <the>/ tent curtain","like/ [the] tent curtains of"]', '["n-f"]', 'a hanging (as tremulous) curtain.', 'from 3415;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7136B}/[H7136]', 'inflected', 'heb', 'קָרָה', '["qârâh"]', '["the/ [one who] makes beams for"]', '["v"]', 'to light upon (chiefly by accident); causatively, to bring about; specifically, to impose timbers (for roof or floor) appoint, lay (make) beams, befall, bring, come (to pass unto), floor, (hap) was, happen (unto), meet, send good speed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5944}/H9023/[H5927]', 'inflected', 'heb', 'עֲלִיָּה', '["ʻălîyâh"]', '["upper rooms/ his"]', '["n-f"]', 'something lofty, i.e. a stair-way; also a second-story room (or even one on the roof); figuratively, the sky ascent, (upper) chamber, going up, loft, parlour.', 'feminine from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7760A}/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["the/ [one who] makes","who/ <she> made"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7398}/H9023/[H7392]', 'inflected', 'heb', 'רְכוּב', '["rᵉkûwb"]', '["chariot/ his"]', '["n-m"]', 'a vehicle (as ridden on) chariot.', 'from passive participle of 7392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4349}/H9024/[H3559]', 'inflected', 'heb', 'מָכוֹן', '["mâkôwn"]', '["foundations/ its"]', '["n-m"]', 'properly, a fixture, i.e. a basis; generally a place, especially as an abode foundation, habitation, (dwelling-, settled) place.', 'from 3559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1606}/H9021/[H1605]', 'inflected', 'heb', 'גְּעָרָה', '["gᵉʻârâh"]', '["rebuke/ your"]', '["n-f"]', 'a chiding rebuke(-ing), reproof.', 'from 1605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5127}/H9013/[H5127]', 'inflected', 'heb', 'נוּס', '["nûwç"]', '["they fled/ !","you will flee/ !"]', '["v"]', 'to flit, i.e. vanish away (subside, escape; causatively, chase, impel, deliver) × abate, away, be displayed, (make to) flee (away, -ing), put to flight, × hide, lift up a standard.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2648}/H9013/[H2648]', 'inflected', 'heb', 'חָפַז', '["châphaz"]', '["they hurried away/ !"]', '["v"]', 'properly, to start up suddenly, i.e. (by implication) to hasten away, to fear (make) haste (away), tremble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5674A}/H9013/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["they will pass/ !"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725J}/H9013/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["they will return/ !"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6772}/H9028/[H6770]', 'inflected', 'heb', 'צָמָא', '["tsâmâʼ"]', '["thirst/ their"]', '["n-m"]', 'thirst (literally or figuratively) thirst(-y).', 'from 6770;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0996H}/[H995]', 'inflected', 'heb', 'בֵּין', '["bêyn"]', '["from/ between"]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6073>', 'opaque', 'heb', 'עֳפֶא', '["ʻŏpheʼ"]', '["foliage"]', '["n-m"]', 'a bough (as covering the tree) branch.', 'from an unused root meaning to cover;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5944}/H9023/[H5927]', 'inflected', 'heb', 'עֲלִיָּה', '["ʻălîyâh"]', '["from/ upper rooms/ his"]', '["n-f"]', 'something lofty, i.e. a stair-way; also a second-story room (or even one on the roof); figuratively, the sky ascent, (upper) chamber, going up, loft, parlour.', 'feminine from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6212>', 'inflected', 'heb', 'ועשב', '["Ve./''e.sev","ve./''E.sev"]', '["and/ [the] vegetation of","and/ vegetation"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6670B}/[H6670]', 'inflected', 'heb', 'צָהַל', '["tsâhal"]', '["to/ make shine"]', '["v"]', 'to gleam, i.e. (figuratively) be cheerful; by transference to sound clear (of various animal or human expressions) bellow, cry aloud (out), lift up, neigh, rejoice, make to shine, shout.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7077}/[H7064]', 'lemma', 'heb', 'קָנַן', '["qânan"]', '["[which] it makes a nest","[who is] nested","it will make a nest","they made nests","they make nests"]', '["v"]', 'to nestle, i.e. build or occupy as a nest make...nest.', 'a primitive root; to erect; but used only as denominative from 7064;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3277H}/[H3276]', 'inflected', 'heb', 'יָעֵל', '["yâʻêl"]', '["[belong] to the/ mountain goats"]', '["n-m"]', 'an ibex (as climbing) wild goat.', 'from 3276;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8227A}/[H8226]', 'inflected', 'heb', 'שָׁפָן', '["shâphân"]', '["for the/ rock badgers"]', '["n-m n-pr-m"]', 'a species of rock-rabbit (from its hiding), i.e. probably the hyrax coney.', 'from 8226;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3715A}/[H3722]', 'inflected', 'heb', 'כְּפִיר', '["kᵉphîyr"]', '["the/ young lions"]', '["n-m"]', 'a village (as covered in by walls); also a young lion (perhaps as covered with a mane) (young) lion, village. Compare 3723.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0622}/H9013/[H622]', 'inflected', 'heb', 'אָסַף', '["ʼâçaph"]', '["they gather/ !"]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4585}/H9028/[H4583]', 'inflected', 'heb', 'מְעוֹנָה', '["mᵉʻôwnâh"]', '["dens/ their"]', '["n-f"]', 'den, habitation, (dwelling) place, refuge.', 'or מְעֹנָה; feminine of 4583, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7257}/H9013/[H7257]', 'inflected', 'heb', 'רָבַץ', '["râbats"]', '["they lie down/ !","they will lie down/ !"]', '["v"]', 'to crouch (on all four legs folded, like a recumbent animal); by implication, to recline, repose, brood, lurk, imbed crouch (down), fall down, make a fold, lay, (cause to, make to) lie (down), make to rest, sit.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6467}/H9023/[H6466]', 'inflected', 'heb', 'פֹּעַל', '["pôʻal"]', '["to/ work/ his"]', '["n-m"]', 'an act or work (concretely) act, deed, do, getting, maker, work.', 'from 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5656I}/H9023/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["and/ to/ labor/ his"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7075}/H9021/[H7069]', 'inflected', 'heb', 'קִנְיָן', '["qinyân"]', '["acquisition/ your","creature[s]/ your"]', '["n-m"]', 'creation, i.e. (concretely) creatures; also acquisition, purchase, wealth getting, goods, × with money, riches, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7832}/[H7832]', 'inflected', 'heb', 'שָׂחַק', '["sâchaq"]', '["to/ laugh","to/ play"]', '["v"]', 'to laugh (in pleasure or detraction); by implication, to play deride, have in derision, laugh, make merry, mock(-er), play, rejoice, (laugh to) scorn, be in (make) sport.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7663B}/H9013/[H7663]', 'inflected', 'heb', 'שָׂבַר', '["sâbar"]', '["they wait/ !"]', '["v"]', 'to scrutinize; by implication (of watching) to expect (with hope and patience) hope, tarry, view, wait.', 'erroneously שָׁבַר; (Nehemiah 2:13,15), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3950}/H9013/[H3950]', 'inflected', 'heb', 'לָקַט', '["lâqaṭ"]', '["they gather/ !"]', '["v"]', 'properly, to pick up, i.e. (generally) to gather; specifically, to glean gather (up), glean.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7646}/H9013/[H7646]', 'inflected', 'heb', 'שָׂבַע', '["sâbaʻ"]', '["they are satisfied/ !"]', '["v"]', 'to sate, i.e. fill to satisfaction (literally or figuratively) have enough, fill (full, self, with), be (to the) full (of), have plenty of, be satiate, satisfy (with), suffice, be weary of.', 'or שָׂבֵעַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0926}/H9013/[H926]', 'inflected', 'heb', 'בָּהַל', '["bâhal"]', '["they are terrified/ !"]', '["v"]', 'to tremble inwardly (or palpitate), i.e. (figuratively) be (causative, make) (suddenly) alarmed or agitated; by implication to hasten anxiously be (make) affrighted (afraid, amazed, dismayed, rash), (be, get, make) haste(-n, -y, -ily), (give) speedy(-ily), thrust out, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7307H}/H9028/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["breath/ their"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1478}/H9013/[H1478]', 'inflected', 'heb', 'גָּוַע', '["gâvaʻ"]', '["they die/ !"]', '["v"]', 'to breathe out, i.e. (by implication) expire die, be dead, give up the ghost, perish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1254A}/H9013/[H1254]', 'inflected', 'heb', 'בָּרָא', '["bârâʼ"]', '["they are created/ !"]', '["v"]', '(absolutely) to create; (qualified) to cut down (a wood), select, feed (as formative processes) choose, create (creator), cut down, dispatch, do, make (fat).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4639G}/H9023/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["in/ work<s>/ his","in/ works/ his"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5027}/[H5027]', 'inflected', 'heb', 'נָבַט', '["nâbaṭ"]', '["the/ [one who] looks"]', '["v"]', 'to scan, i.e. look intently at; by implication, to regard with pleasure, favor or care (cause to) behold, consider, look (down), regard, have respect, see.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7460}/[H7460]', 'inflected', 'heb', 'רָעַד', '["râʻad"]', '["and/ it trembled"]', '["v"]', 'to shudder (more or less violently) tremble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6225}/[H6225]', 'inflected', 'heb', 'עָשַׁן', '["ʻâshan"]', '["so/ they may smoke"]', '["v"]', 'to smoke, whether literal or figurative be angry (be on a) smoke.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5750}/H9020/[H5749]', 'inflected', 'heb', 'עוֹד', '["ʻôwd"]', '["in/ duration/ my"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6149}/[H6148]', 'lemma', 'heb', 'עָרֵב', '["ʻârêb"]', '["<it> is pleasing","it was pleasing","may it be pleasing","they are pleasing","they will be pleasing","you were pleasing"]', '["v"]', 'to be agreeable be pleasant(-ing), take pleasure in, be sweet.', 'a primitive root (rather identical with 6148 through the idea of close association);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3446}/[H7831]', 'inflected', 'heb', 'יִשְׂחָק', '["Yischâq"]', '["to/ Isaac"]', '["n-pr-m"]', 'Jischak, the heir of Abraham Isaac. Compare 3327.', 'from 7831; he will laugh;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4467}/[H4427]', 'inflected', 'heb', 'מַמְלָכָה', '["mamlâkâh"]', '["from/ a kingdom"]', '["n-f"]', 'dominion, i.e. (abstractly) the estate (rule) or (concretely) the country (realm) kingdom, king''s, reign, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5030}/H9020/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["and/ to/ prophets/ my"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3525>', 'inflected', 'heb', 'בכבלי', '["be./khav.Lei","va./Ke.vel"]', '["with <the>/ shackle[s]","with/ shackles of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315N}/H9023/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["neck/ his"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6884}/H9033/[H6884]', 'inflected', 'heb', 'צָרַף', '["tsâraph"]', '["it tested/ him"]', '["v"]', 'to fuse (metal), i.e. refine (literally or figuratively) cast, (re-) fine(-er), founder, goldsmith, melt, pure, purge away, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5425B}/H9033/[H5425]', 'inflected', 'heb', 'נָתַר', '["nâthar"]', '["and/ he set free/ him"]', '["v"]', 'to jump, i.e. be violently agitated; causatively, to terrify, shake off, untie drive asunder, leap, (let) loose, × make, move, undo.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6605A}/H9033/[H6605]', 'inflected', 'heb', 'פָּתַח', '["pâthach"]', '["and/ he set free/ him"]', '["v"]', 'to open wide (literally or figuratively); specifically, to loosen, begin, plough, carve appear, break forth, draw (out), let go free, (en-) grave(-n), loose (self), (be, be set) open(-ing), put off, ungird, unstop, have vent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5315L}/H9023/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["in/ will/ his"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6105A}/H9033/[H6106]', 'inflected', 'heb', 'עָצַם', '["ʻâtsam"]', '["and/ he made strong/ it"]', '["v"]', 'to bind fast, i.e. close (the eyes); intransitively, to be (causatively, make) powerful or numerous; to crunch the bones break the bones, close, be great, be increased, be (wax) mighty(-ier), be more, shut, be(-come, make) strong(-er).', 'a primitive root; also denominatively (from 6106)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5230}/[H5230]', 'inflected', 'heb', 'נָכַל', '["nâkal"]', '["to/ deal deceptively"]', '["v"]', 'to defraud, i.e. act treacherously beguile, conspire, deceiver, deal subtilly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1710}/H9028/[H1709]', 'inflected', 'heb', 'דָּגָה', '["dâgâh"]', '["fish/ their"]', '["n-f"]', 'fish.', 'feminine of 1709, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1653}/H9028/[H1652]', 'inflected', 'heb', 'גֶּשֶׁם', '["geshem"]', '["rains/ their"]', '["n-m"]', 'a shower rain, shower.', 'from 1652;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8384}/H9028/[H8384]', 'inflected', 'heb', 'תְּאֵן', '["tᵉʼên"]', '["and/ fig tree[s]/ their"]', '["n-f"]', 'the fig (tree or fruit) fig (tree).', 'or (in the singular, feminine) תְּאֵנָה; perhaps of foreign derivation');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3218>', 'inflected', 'heb', 'וילק', '["ve./Ye.lek"]', '["and/ locust[s]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0202}/H9028/[H205]', 'inflected', 'heb', 'אוֹן', '["ʼôwn"]', '["manly vigor/ their"]', '["n-m"]', 'ability, power, (figuratively) wealth force, goods, might, strength, substance.', 'probably from the same as 205 (in the sense of effort, but successful);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7626H>/H9023', 'inflected', 'heb', 'בשבטיו', '["bi/sh.va.Ta/v"]', '["among/ tribes/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7646}/H9038/[H7646]', 'inflected', 'heb', 'שָׂבַע', '["sâbaʻ"]', '["he satisfied/ them"]', '["v"]', 'to sate, i.e. fill to satisfaction (literally or figuratively) have enough, fill (full, self, with), be (to the) full (of), have plenty of, be satiate, satisfy (with), suffice, be weary of.', 'or שָׂבֵעַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8342}/[H7797]', 'inflected', 'heb', 'שָׂשׂוֹן', '["sâsôwn"]', '["with/ joy"]', '["n-m"]', 'cheerfulness; specifically, welcome gladness, joy, mirth, rejoicing.', 'or שָׂשֹׂן; from 7797;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8451}/H9023/[H3384]', 'inflected', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["and/ laws/ his"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1984B}/{H3050}/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["praise/ Yahweh"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7522}/[H7521]', 'inflected', 'heb', 'רָצוֹן', '["râtsôwn"]', '["with/ [the] favor of"]', '["n-m"]', 'delight (especially as shown) (be) acceptable(-ance, -ed), delight, desire, favour, (good) pleasure, (own, self, voluntary) will, as...(what) would.', 'or רָצֹן; from 7521;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6485I}/H9030/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["visit/ me"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7200K}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["to/ look"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0972}/H9021/[H977]', 'inflected', 'heb', 'בָּחִיר', '["bâchîyr"]', '["chosen ones/ your"]', '["n-m"]', 'select choose, chosen one, elect.', 'from 977;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8055}/[H8055]', 'inflected', 'heb', 'שָׂמַח', '["sâmach"]', '["to/ rejoice"]', '["v"]', 'probably to brighten up, i.e. (figuratively) be (causatively, make) blithe or gleesome cheer up, be (make) glad, (have, make) joy(-ful), be (make) merry, (cause to, make to) rejoice, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1471A}/H9021/[H1465]', 'inflected', 'heb', 'גּוֹי', '["gôwy"]', '["nation/ your"]', '["n-m n-pr-m"]', 'a foreign nation; hence, a Gentile; also (figuratively) a troop of animals, or a flight of locusts Gentile, heathen, nation, people.', 'rarely (shortened) גֹּי; apparently from the same root as 1465 (in the sense of massing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1984H}/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["to/ boast"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2717A}/[H2717]', 'inflected', 'heb', 'חָרַב', '["chârab"]', '["and/ I will dry up","and/ it dried up","and/ they will become dry"]', '["v"]', 'to parch (through drought) i.e. (by analogy,) to desolate, destroy, kill decay, (be) desolate, destroy(-er), (be) dry (up), slay, × surely, (lay, lie, make) waste.', 'or חֲרֵב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1980J}/H9038/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ he led/ them"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8415}/[H1949]', 'inflected', 'heb', 'תְּהוֹם', '["tᵉhôwm"]', '["in the/ deeps"]', '["n"]', 'an abyss (as a surging mass of water), especially the deep (the main sea or the subterranean watersupply) deep (place), depth.', 'or תְּהֹם; (usually feminine) from 1949;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4057B}/[H1696]', 'inflected', 'heb', 'מִדְבָּר', '["midbâr"]', '["like <the>/ wilderness","like the/ wilderness"]', '["n-m"]', 'a pasture (i.e. open field, whither cattle are driven); by implication, a desert; also speech (including its organs) desert, south, speech, wilderness.', 'from 1696 in the sense of driving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1350A}/H9038/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["and/ he redeemed/ them"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6098}/H9023/[H3289]', 'inflected', 'heb', 'עֵצָה', '["ʻêtsâh"]', '["for/ counsel/ his"]', '["n-f"]', 'advice; by implication, plan; also prudence advice, advisement, counsel([-lor]), purpose.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7596}/H9028/[H7592]', 'inflected', 'heb', 'שְׁאֵלָה', '["shᵉʼêlâh"]', '["petition/ their"]', '["n-f"]', 'a petition; by implication, a loan loan, petition, request.', 'or שֵׁלָה; (1 Samuel 1:17), from 7592;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7332}/[H7329]', 'lemma', 'heb', 'רָזוֹן', '["râzôwn"]', '["a wasting disease","leanness","scantness"]', '["n-m"]', 'thinness leanness, × scant.', 'from 7329;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5315I}/H9028/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["on/ self/ their"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0048G}/[H1]', 'lemma', 'heb', 'אֲבִירָם', '["ʼĂbîyrâm"]', '["Abiram"]', '["n-pr-m"]', 'Abiram, the name of two Israelites Abiram.', 'from 1 and 7311; father of height (i.e. lofty);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5712}/H9028/[H5707]', 'inflected', 'heb', 'עֵדָה', '["ʻêdâh"]', '["among/ company/ their"]', '["n-f"]', 'a stated assemblage (specifically, a concourse, or generally, a family or crowd) assembly, company, congregation, multitude, people, swarm. Compare 5713.', 'feminine of 5707 in the original sense of fixture;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4541A}/[H5258]', 'inflected', 'heb', 'מַסֵּכָה', '["maççêkâh"]', '["to/ a molten image"]', '["n-f"]', 'properly, a pouring over, i.e. fusion of metal (especially a cast image); by implication, a libation, i.e. league; concretely a coverlet (as if poured out) covering, molten (image), vail.', 'from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4171}/[H4171]', 'inflected', 'heb', 'מוּר', '["mûwr"]', '["and/ they exchanged"]', '["v"]', 'to alter; by implication, to barter, to dispose of × at all, (ex-) change, remove.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3519}/H9028/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["glory/ their","own honor/ their"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8403}/[H1129]', 'inflected', 'heb', 'תַּבְנִית', '["tabnîyth"]', '["for/ an image of"]', '["n-f"]', 'structure; by implication, a model, resemblance figure, form, likeness, pattern, similitude.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3467}/H9038/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["I will save/ them","deliverer/ their","he saved/ them","it saved/ them"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6556}/[H6555]', 'inflected', 'heb', 'פֶּרֶץ', '["perets"]', '["in the/ breach","in the/ breaches"]', '["n-m"]', 'a break (literally or figuratively) breach, breaking forth (in), × forth, gap.', 'from 6555;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7843}/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["from/ destroying"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1697J}/H9023/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["<to>/ word/ his"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2219}/H9038/[H2114]', 'inflected', 'heb', 'זָרָה', '["zârâh"]', '["and/ to/ scatter/ them"]', '["v"]', 'to toss about; by implication, to diffuse, winnow cast away, compass, disperse, fan, scatter (away), spread, strew, winnow.', 'a primitive root (compare 2114);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4611}/H9028/[H5953]', 'inflected', 'heb', 'מַעֲלָל', '["maʻălâl"]', '["by/ deeds/ their"]', '["n-m"]', 'an act (good or bad) doing, endeavour, invention, work.', 'from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6666}/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["<to>/ righteousness","for/ righteousness","to/ righteousness"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0981}/[H981]', 'inflected', 'heb', 'בָּטָא', '["bâṭâʼ"]', '["and/ he spoke rashly"]', '["v"]', 'to babble; hence, to vociferate angrily pronounce, speak (unadvisedly).', 'or בָּטָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8193G}/H9023/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["on/ lips/ his","with/ lips/ his"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6091}/[H6087]', 'inflected', 'heb', 'עָצָב', '["ʻâtsâb"]', '["to <the>/ idols","to/ [the] idols of"]', '["n-m"]', 'an (idolatrous) image idol, image.', 'from 6087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2610}/[H2610]', 'inflected', 'heb', 'חָנֵף', '["chânêph"]', '["and/ it was polluted","and/ you have polluted"]', '["v"]', 'to soil, especially in a moral sense corrupt, defile, × greatly, pollute, profane.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4639K}/H9028/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["by/ works/ their"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8130}/H9038/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["I hate/ them","I hated/ them","[those who] hated/ them"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3905}/H9038/[H3905]', 'inflected', 'heb', 'לָחַץ', '["lâchats"]', '["and/ they oppressed/ them"]', '["v"]', 'properly, to press, i.e. (figuratively) to distress afflict, crush, force, hold fast, oppress(-or), thrust self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7440}/H9028/[H7442]', 'inflected', 'heb', 'רִנָּה', '["rinnâh"]', '["cry of entreaty/ their","shout of joy/ their"]', '["n-f"]', 'properly, a creaking (or shrill sound), i.e. shout (of joy or grief) cry, gladness, joy, proclamation, rejoicing, shouting, sing(-ing), triumph.', 'from 7442;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1350A}/H9038/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["he has redeemed/ them","he redeemed/ them","will I redeem?/ them"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H3220G>', 'inflected', 'heb', 'ומים', '["u./mi./Yam"]', '["and/ from/ [the] sea"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6771}/[H6770]', 'lemma', 'heb', 'צָמֵא', '["tsâmêʼ"]', '["[the] thirsty","thirsty","thirsty [ground]","thirsty [one]"]', '["a"]', 'thirsty (literally or figuratively) (that) thirst(-eth, -y).', 'from 6770;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4691}/H9028/[H4690]', 'inflected', 'heb', 'מְצוּקָה', '["mᵉtsûwqâh"]', '["from/ troubles/ their"]', '["n-f"]', 'narrowness, i.e. (figuratively) trouble anguish, distress.', 'or מְצֻקָה; feminine of 4690;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1869}/H9038/[H1869]', 'inflected', 'heb', 'דָּרַךְ', '["dârak"]', '["and/ he led/ them"]', '["v"]', 'to tread; by implication, to walk; also to string a bow (by treading on it in bending) archer, bend, come, draw, go (over), guide, lead (forth), thresh, tread (down), walk.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8264}/[H8264]', 'lemma', 'heb', 'שָׁקַק', '["shâqaq"]', '["[is] longing","[someone will be] rushing","longing","rushing"]', '["v"]', 'to course (like a beast of prey); by implication, to seek greedily have appetite, justle one against another, long, range, run (to and fro).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2822}/[H2821]', 'inflected', 'heb', 'חֹשֶׁךְ', '["chôshek"]', '["from/ darkness"]', '["n-m"]', 'the dark; hence (literally) darkness; figuratively, misery, destruction, death, ignorance, sorrow, wickedness dark(-ness), night, obscurity.', 'from 2821;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4147}/H9028/[H3256]', 'inflected', 'heb', 'מוֹסֵר', '["môwçêr"]', '["and/ fetters/ their"]', '["n-m"]', 'properly, chastisement, i.e. (by implication) a halter; figuratively, restraint band, bond.', 'also (in plural) feminine מוֹסֵרָה; or מֹסְרָה; from 3256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5771G}/H9028/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["and/ from/ iniquities/ their"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7495}/H9038/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["and/ he healed/ them"]', '["v"]', 'properly, to mend (by stitching), i.e. (figuratively) to cure cure, (cause to) heal, physician, repair, × thoroughly, make whole. See 7503.', 'or רָפָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7825}/H9028/[H7812]', 'inflected', 'heb', 'שְׁחִית', '["shᵉchîyth"]', '["from/ pits/ their"]', '["n-f"]', 'a pit-fall (literally or figuratively) destruction, pit.', 'from 7812;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5927K}/[H5927]', 'lemma', 'heb', 'עָלָה', '["ʻâlâh"]', '["they went up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2451}/H9028/[H2449]', 'inflected', 'heb', 'חׇכְמָה', '["chokmâh"]', '["skill/ their","wisdom/ their"]', '["n-f"]', 'wisdom (in a good sense) skilful, wisdom, wisely, wit.', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4691}/H9028/[H4690]', 'inflected', 'heb', 'מְצוּקָה', '["mᵉtsûwqâh"]', '["and/ from/ troubles/ their"]', '["n-f"]', 'narrowness, i.e. (figuratively) trouble anguish, distress.', 'or מְצֻקָה; feminine of 4690;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1827}/[H1826]', 'inflected', 'heb', 'דְּמָמָה', '["dᵉmâmâh"]', '["into/ a calm"]', '["n-f"]', 'quiet calm, silence, still.', 'feminine from 1826;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2814}/[H2814]', 'inflected', 'heb', 'חָשָׁה', '["châshâh"]', '["and/ they were still"]', '["v"]', 'to hush or keep quiet hold peace, keep silence, be silent, (be) still.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8367}/[H8367]', 'lemma', 'heb', 'שָׁתַק', '["shâthaq"]', '["it becomes quiet","they were quiet"]', '["v"]', 'to subside be calm, cease, be quiet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4231>', 'opaque', 'heb', 'מָחוֹז', '["mâchôwz"]', '["[the] harbor of"]', '["n-m"]', 'a harbor (as shut in by the shore) haven.', 'from an unused root meaning to enclose;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2656}/H9028/[H2654]', 'inflected', 'heb', 'חֵפֶץ', '["chêphets"]', '["[those] delighting in/ them","desire/ their"]', '["n-m"]', 'pleasure; hence (abstractly) desire; concretely, a valuable thing; hence (by extension) a matter (as something in mind) acceptable, delight(-some), desire, things desired, matter, pleasant(-ure), purpose, willingly.', 'from 2654;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6774}/[H6771]', 'inflected', 'heb', 'צִמָּאוֹן', '["tsimmâʼôwn"]', '["into/ thirsty ground"]', '["n-m"]', 'a thirsty place, i.e. desert drought, dry ground, thirsty land.', 'from 6771;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4420}/[H4414]', 'inflected', 'heb', 'מְלֵחָה', '["mᵉlêchâh"]', '["into/ saltiness"]', '["n-f"]', 'properly, salted (i.e. land), i.e. a desert barren land(-ness), salt (land).', 'from 4414 (in its denominative sense); understood as land (776)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0098>', 'inflected', 'heb', 'לאגם', '["la./''a.Gam","la./''a.gam"]', '["<into>/ a pool","<into>/ a pool of","into/ a pool of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4161}/[H3318]', 'inflected', 'heb', 'מוֹצָא', '["môwtsâʼ"]', '["<into>/ springs of","into/ springs of"]', '["n-m"]', 'a going forth, i.e. (the act) an egress, or (the place) an exit; hence, a source or product; specifically, dawn, the rising of the sun (the East), exportation, utterance, a gate, a fountain, a mine, a meadow (as producing grass) brought out, bud, that which came out, east, going forth, goings out, that which (thing that) is gone out, outgoing, proceeded out, spring, vein, (water-) course (springs).', 'or מֹצָאxlit môtsâ corrected to môtsâʼ; from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0929>/H9028', 'inflected', 'heb', 'ובהמתם', '["u./ve.hem.Ta/m"]', '["and/ cattle/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7817}/[H7817]', 'inflected', 'heb', 'שָׁחַח', '["shâchach"]', '["and/ he has been humbled","and/ it will be humbled","and/ they were bowed down"]', '["v"]', 'to sink or depress (reflexive or causative) bend, bow (down), bring (cast) down, couch, humble self, be (bring) low, stoop.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6115}/[H6113]', 'inflected', 'heb', 'עֹצֶר', '["ʻôtser"]', '["from/ [the] pressure of","from/ oppression"]', '["n-m"]', 'closure; also constraint × barren, oppression, × prison.', 'from 6113;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3015}/[H3013]', 'inflected', 'heb', 'יָגוֹן', '["yâgôwn"]', '["and/ sorrow"]', '["n-m"]', 'affliction grief, sorrow.', 'from 3013;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7682}/[H7682]', 'inflected', 'heb', 'שָׂגַב', '["sâgab"]', '["and/ he is set on high","and/ he set on high","and/ he will be exalted"]', '["v"]', 'to be (causatively, make) lofty, especially inaccessible; by implication, safe, strong; used literally and figuratively defend, exalt, be excellent, (be, set on) high, lofty, be safe, set up (on high), be too strong.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8104J}/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["and/ let him observe"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2167}/H9031/[H2168]', 'inflected', 'heb', 'זָמַר', '["zâmar"]', '["and/ I will sing praises to/ you"]', '["v"]', 'properly, to touch the strings or parts of a musical instrument, i.e. play upon it; to make music, accompanied by the voice; hence to celebrate in song and music give praise, sing forth praises, psalms.', 'a primitive root (perhaps identical with 2168 through the idea of striking with the fingers);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6310G}/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["and/ [the] mouth of","and/ a mouth","and/ a mouth of"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3898A}/H9030/[H3898]', 'inflected', 'heb', 'לָחַם', '["lâcham"]', '["and/ they have fought against/ me"]', '["v"]', 'to feed on; figuratively, to consume; by implication, to battle (as destruction) devour, eat, × ever, fight(-ing), overcome, prevail, (make) war(-ring).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0160}/H9020/[H158]', 'inflected', 'heb', 'אַהֲבָה', '["ʼahăbâh"]', '["love/ my"]', '["n-f"]', 'love.', 'feminine of 158 and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7854}/[H7853]', 'inflected', 'heb', 'שָׂטָן', '["sâṭân"]', '["and/ an accuser"]', '["n-m"]', 'an opponent; especially (with the article prefixed) Satan, the arch-enemy of good adversary, Satan, withstand.', 'from 7853;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2401}/[H2399]', 'inflected', 'heb', 'חֲטָאָה', '["chăṭâʼâh"]', '["<into>/ sin"]', '["n-f"]', 'an offence, or a sacrifice for it sin (offering).', 'feminine of 2399;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6486}/H9023/[H6485]', 'inflected', 'heb', 'פְּקֻדָּה', '["pᵉquddâh"]', '["office/ his"]', '["n-f"]', 'visitation (in many senses, chiefly official) account, (that have the) charge, custody, that which...laid up, numbers, office(-r), ordering, oversight, prison, reckoning, visitation.', 'feminine passive participle of 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2723}/H9028/[H2721]', 'inflected', 'heb', 'חׇרְבָּה', '["chorbâh"]', '["away from/ ruins/ their"]', '["n-f"]', 'properly, drought, i.e. (by implication) a desolation decayed place, desolate (place, -tion), destruction, (laid) waste (place).', 'feminine of 2721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3018}/H9023/[H3021]', 'inflected', 'heb', 'יְגִיעַ', '["yᵉgîyaʻ"]', '["property/ his"]', '["n-m"]', 'toil; hence, a work, produce, property (as the result of labor) labour, work.', 'from 3021;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3490>/H9023', 'inflected', 'heb', 'ליתומיו', '["li./to.Ma/v"]', '["to/ fatherless children/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0319}/H9023/[H310]', 'inflected', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["end/ its","posterity/ his"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3772I}/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["and/ may he cut off"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3512A}/[H3512]', 'inflected', 'heb', 'כָּאָה', '["kâʼâh"]', '["and/ disheartened of"]', '["v a"]', 'to despond; causatively, to deject broken, be grieved, make sad.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0935G}/H9033/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ it came to/ him"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1293}/[H1288]', 'inflected', 'heb', 'בְּרָכָה', '["Bᵉrâkâh"]', '["by/ [the] blessing of","in/ blessing"]', '["n-f"]', 'benediction; by implication prosperity blessing, liberal, pool, present.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7368}/[H7368]', 'inflected', 'heb', 'רָחַק', '["râchaq"]', '["and/ he will send far away","and/ it was far","and/ they will be far away"]', '["v"]', 'to widen (in any direction), i.e. (intransitively) recede or (transitively) remove (literally or figuratively, of place or relation) (a-, be, cast, drive, get, go, keep (self), put, remove, be too, (wander), withdraw) far (away, off), loose, × refrain, very, (be) a good way (off).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4055}/H9023/[H4058]', 'inflected', 'heb', 'מַד', '["mad"]', '["like/ garment/ his"]', '["n-m"]', 'properly, extent, i.e. height; also a measure; by implication, a vesture (as measured); also a carpet armour, clothes, garment, judgment, measure, raiment, stature.', 'or מֵד; from 4058;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7130H}/H9023/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["in/ inward part[s]/ his"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H8081}/[H8080]', 'inflected', 'heb', 'שֶׁמֶן', '["shemen"]', '["and/ like <the>/ oil"]', '["n-m"]', 'grease, especially liquid (as from the olive, often perfumed); figuratively, richness anointing, × fat (things), × fruitful, oil(-ed), ointment, olive, pine.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6106G}/H9023/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["in/ bones/ his"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4206A}/[H2118]', 'inflected', 'heb', 'מָזִיחַ', '["mâzîyach"]', '["and/ to/ a waistband"]', '["n-m"]', 'a belt (as movable) girdle, strength.', 'or מֵזַח; from 2118;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2296}/H9034/[H2296]', 'inflected', 'heb', 'חָגַר', '["châgar"]', '["he girds on/ it"]', '["v"]', 'to gird on (as a belt, armor, etc.) be able to put on, be afraid, appointed, gird, restrain, × on every side.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1696G}/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["and/ those/ [who] speak"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5186}/H9043/[H5186]', 'inflected', 'heb', 'נָטָה', '["nâṭâh"]', '["when/ stretches out/ it"]', '["v"]', 'to stretch or spread out; by implication, to bend away (including moral deflection); used in a great variety of application (as follows) afternoon, apply, bow (down, -ing), carry aside, decline, deliver, extend, go down, be gone, incline, intend, lay, let down, offer, outstretched, overthrown, pervert, pitch, prolong, put away, shew, spread (out), stretch (forth, out), take (aside), turn (aside, away), wrest, cause to yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6685}/[H6684]', 'inflected', 'heb', 'צוֹם', '["tsôwm"]', '["from/ fasting"]', '["n-m"]', 'a fast fast(-ing).', 'or צֹם; from 6684;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5844A}/[H5844]', 'inflected', 'heb', 'עָטָה', '["ʻâṭâh"]', '["and/ may they be wrapped"]', '["v"]', 'to wrap, i.e. cover, veil, clothe, or roll array self, be clad, (put a) cover (-ing, self), fill, put on, × surely, turn aside.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3225G}/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["to/ [the] right [hand] of"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8199}/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["from/ [those who] judge"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3225G}/H9020/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["to/ right [hand]/ my"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1916>', 'opaque', 'heb', 'הֲדֹם', '["hădôm"]', '["[is] [the] footstool of","[the] footstool of","a footstool"]', '["n-m"]', 'a footstool (foot-) stool.', 'from an unused root meaning to stamp upon;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2428G}/H9021/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["strength/ your"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4891}/[H7836]', 'lemma', 'heb', 'מִשְׁחָר', '["mishchâr"]', '["dawn"]', '["n-m"]', 'dawn morning.', 'from 7836 in the sense of day breaking;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3208}/H9021/[H3206]', 'inflected', 'heb', 'יַלְדוּת', '["yaldûwth"]', '["youth/ your"]', '["n-f"]', 'boyhood (or girlhood) childhood, youth.', 'abstractly from 3206;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1700}/[H1697]', 'lemma', 'heb', 'דִּבְרָה', '["dibrâh"]', '["[the] cause of","[the] manner of","cause of","reason"]', '["n-m"]', 'a reason, suit or style cause, end, estate, order, regard.', 'feminine of 1697;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6381}/H9023/[H6381]', 'inflected', 'heb', 'פָּלָא', '["pâlâʼ"]', '["of/ wonders/ his"]', '["v"]', 'properly, perhaps to separate, i.e. distinguish (literally or figuratively); by implication, to be (causatively, make) great, difficult, wonderful accomplish, (arise...too, be too) hard, hidden, things too high, (be, do, do a, shew) marvelous(-ly, -els, things, work), miracles, perform, separate, make singular, (be, great, make) wonderful(-ers, -ly, things, works), wondrous (things, works, -ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213A}/H9038/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["[those who] do/ them","[which] I will do/ them","it did/ them"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4687}/H9023/[H6680]', 'inflected', 'heb', 'מִצְוָה', '["mitsvâh"]', '["in/ commandments/ his"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8052}/[H8074]', 'inflected', 'heb', 'שְׁמוּעָה', '["shᵉmûwʻâh"]', '["from/ new[s]"]', '["n-f"]', 'something heard, i.e. an announcement bruit, doctrine, fame, mentioned, news, report, rumor, tidings.', 'feminine passive participle of 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6862C}/H9023/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["on/ foes/ his"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3519}/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["in/ honor","in/ splendor"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1361}/[H1361]', 'inflected', 'heb', 'גָּבַהּ', '["gâbahh"]', '["who/ is making high"]', '["v"]', 'to soar, i.e. be lofty; figuratively, to be haughty exalt, be haughty, be (make) high(-er), lift up, mount up, be proud, raise up great height, upward.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8213}/[H8213]', 'inflected', 'heb', 'שָׁפֵל', '["shâphêl"]', '["who/ is making low"]', '["v"]', 'to depress or sink (especially figuratively, to humiliate, intransitive or transitive) abase, bring (cast, put) down, debase, humble (self), be (bring, lay, make, put) low(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3937}/[H3937]', 'lemma', 'heb', 'לָעַז', '["lâʻaz"]', '["speaking a foreign language"]', '["v"]', 'to speak in a foreign tongue strange language.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6944G}/H9023/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["<into>/ sanctuary/ his"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0268}/[H299]', 'inflected', 'heb', 'אָחוֹר', '["ʼâchôwr"]', '["<to>/ backwards","to/ afterwards","to/ backwards"]', '["n-m"]', 'the hinder part; hence (adverb) behind, backward; also (as facing north) the West after(-ward), back (part, -side, -ward), hereafter, (be-) hind(-er part), time to come, without.', 'or (shortened) אָחֹר ; from 299;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0352A}/[H193]', 'inflected', 'heb', 'אַיִל', '["ʼayil"]', '["like/ rams"]', '["n-m"]', 'properly, strength; hence, anything strong; specifically a chief (politically); also a ram (from his strength); a pilaster (as a strong support); an oak or other strong tree mighty (man), lintel, oak, post, ram, tree.', 'from the same as 193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1121H}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["like/ young ones of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0098>', 'opaque', 'heb', 'אֲגַם', '["ʼăgam"]', '["a pool of"]', '["n-m"]', 'a marsh; hence a rush (as growing in swamps); hence a stockade of reeds pond, pool, standing (water).', 'from an unused root (meaning to collect as water);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2496}/[H2492]', 'lemma', 'heb', 'חַלָּמִישׁ', '["challâmîysh"]', '["flint"]', '["n-m"]', 'flint flint(-y), rock.', 'probably from 2492 (in the sense of hardness);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4599}/H9023/[H5869]', 'inflected', 'heb', 'מַעְיָן', '["maʻyân"]', '["into/ spring of/ his"]', '["n-m"]', 'a fountain (also collectively), figuratively, a source (of satisfaction) fountain, spring, well.', 'or מַעְיְנוֹ; (Psalm 114:8), or (feminine) מַעְיָנָה; from 5869 (as a denominative in the sense of a spring);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0430G}/H9025/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["and/ God/ our"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4184}/H9013/[H4184]', 'inflected', 'heb', 'מוּשׁ', '["mûwsh"]', '["they feel/ !"]', '["v"]', 'to touch feel, handle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1627}/H9028/[H1641]', 'inflected', 'heb', 'גָּרוֹן', '["gârôwn"]', '["[be] in/ throat/ their","with/ throat/ their"]', '["n-m"]', 'the throat (as roughened by swallowing) × aloud, mouth, neck, throat.', 'or (shortened) גָּרֹן; from 1641; (compare 1621)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5828}/H9028/[H5826]', 'inflected', 'heb', 'עֵזֶר', '["ʻêzer"]', '["[is] help/ their"]', '["n-m"]', 'aid help.', 'from 5826;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4043}/H9028/[H1598]', 'inflected', 'heb', 'מָגֵן', '["mâgên"]', '["and/ shield/ their"]', '["n-m"]', 'a shield (i.e. the small one or buckler); figuratively, a protector; also the scaly hide of the crocodile × armed, buckler, defence, ruler, scale, shield.', 'also (in plural) feminine מְגִנָּה; from 1598;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2142}/H9035/[H2145]', 'inflected', 'heb', 'זָכַר', '["zâkar"]', '["he has remembered/ us"]', '["v"]', 'properly, to mark (so as to be recognized), i.e. to remember; by implication, to mention; to be male × burn (incense), × earnestly, be male, (make) mention (of), be mindful, recount, record(-er), remember, make to be remembered, bring (call, come, keep, put) to (in) remembrance, × still, think on, × well.', 'a primitive root; also as denominative from 2145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H3117G>/H9020', 'inflected', 'heb', 'ובימי', '["u./ve./ya.Ma/i"]', '["and/ in/ days/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4712}/[H6869]', 'inflected', 'heb', 'מֵצַר', '["mêtsar"]', '["and/ [the] distresses of"]', '["n-m"]', 'something tight, i.e. (figuratively) trouble distress, pain, strait.', 'from 6869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4422}/H9012/[H4422]', 'inflected', 'heb', 'מָלַט', '["mâlaṭ"]', '["deliver/ !"]', '["v"]', 'properly, to be smooth, i.e. (by implication) to escape (as if by slipperiness); causatively, to release or rescue; specifically, to bring forth young, emit sparks deliver (self), escape, lay, leap out, let alone, let go, preserve, save, × speedily, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4496H}/H9022/[H4495]', 'inflected', 'heb', 'מְנוּחָה', '["mᵉnûwchâh"]', '["to/ resting place<s>/ your"]', '["n-f"]', 'repose or (adverbially) peacefully; figuratively, consolation (specifically, matrimony); hence (concretely) an abode comfortable, ease, quiet, rest(-ing place), still.', 'or מְנֻחָה; feminine of 4495;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8408}/H9023/[H1580]', 'inflected', 'heb', 'תַּגְמוּל', '["tagmûwl"]', '["benefits/ his"]', '["n-m"]', 'a bestowment benefit.', 'from 1580;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5048}/H9011/[H5046]', 'inflected', 'heb', 'נֶגֶד', '["neged"]', '["before/ <towards>"]', '["prep"]', 'a front, i.e. part opposite; specifically a counterpart, or mate; usually (adverbial, especially with preposition) over against or before about, (over) against, × aloof, × far (off), × from, over, presence, × other side, sight, × to view.', 'from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4194}/H9011/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["the/ death/ <towards>"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2623}/H9023/[H2616]', 'inflected', 'heb', 'חָסִיד', '["châçîyd"]', '["of/ faithful [people]/ his"]', '["a"]', 'properly, kind, i.e. (religiously) pious (a saint) godly (man), good, holy (one), merciful, saint, (un-) godly.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4147}/H9020/[H3256]', 'inflected', 'heb', 'מוֹסֵר', '["môwçêr"]', '["<to>/ fetters/ my"]', '["n-m"]', 'properly, chastisement, i.e. (by implication) a halter; figuratively, restraint band, bond.', 'also (in plural) feminine מוֹסֵרָה; or מֹסְרָה; from 3256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H8432>/H9022', 'inflected', 'heb', 'בתוככי', '["be./To.Khe./khi","be./to.Khe./khi","be./to.Khe/kh","ve./to.Khe/kh"]', '["[was] in/ [the] midst of/ you","in/ [the] midst of/ you","in/ midst of/ you"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7623B}/H9033/[H7623]', 'inflected', 'heb', 'שָׁבַח', '["shâbach"]', '["extol/ him"]', '["v"]', 'properly, to address in a loud tone, i.e. (specifically) loud; figuratively, to pacify (as if by words) commend, glory, keep in, praise, still, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0523}/[H517]', 'inflected', 'heb', 'אֻמַּה', '["ʼummah"]', '["the/ peoples"]', '["n-f"]', 'a collection, i.e. community of persons nation, people.', 'from the same as 517;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4712}/[H6869]', 'inflected', 'heb', 'מֵצַר', '["mêtsar"]', '["the/ distress"]', '["n-m"]', 'something tight, i.e. (figuratively) trouble distress, pain, strait.', 'from 6869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5826}/H9030/[H5826]', 'inflected', 'heb', 'עָזַר', '["ʻâzar"]', '["<in>/ helper<s>/ my"]', '["v"]', 'to surround, i.e. protect or aid help, succour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8130}/H9030/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["on/ [those who] hate/ me"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0982}/[H982]', 'inflected', 'heb', 'בָּטַח', '["bâṭach"]', '["more than/ to trust"]', '["v"]', 'properly, to hie for refuge (but not so precipitately as 2620); figuratively, to trust, be confident or sure be bold (confident, secure, sure), careless (one, woman), put confidence, (make to) hope, (put, make to) trust.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5081H}/[H5068]', 'inflected', 'heb', 'נָדִיב', '["nâdîyb"]', '["in/ noble [people]"]', '["a"]', 'properly, voluntary, i.e. generous; hence, magnanimous; as noun, a grandee (sometimes a tyrant) free, liberal (things), noble, prince, willing (hearted).', 'from 5068;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4135A}/H9038/[H4135]', 'inflected', 'heb', 'מוּל', '["mûwl"]', '["I fended off/ them"]', '["v"]', 'to cut short, i.e. curtail (specifically the prepuce, i.e. to circumcise); by implication, to blunt; figuratively, to destroy circumcise(-ing), selves), cut down (in pieces), destroy, × must needs.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1682}/[H1696]', 'inflected', 'heb', 'דְּבוֹרָה', '["dᵉbôwrâh"]', '["like/ bees"]', '["n-f"]', 'the bee (from its systematic instincts) bee.', 'or (shortened) דְּבֹרָה; from 1696 (in the sense of orderly motion);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1760A}/H9030/[H1760]', 'inflected', 'heb', 'דָּחָה', '["dâchâh"]', '["you pushed/ me"]', '["v"]', 'to push down chase, drive away (on), overthrow, outcast, × sore, thrust, totter.', 'or דָּחַח; (Jeremiah 23:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3444}/[H3467]', 'inflected', 'heb', 'יְשׁוּעָה', '["yᵉshûwʻâh"]', '["and/ salvation"]', '["n-f"]', 'something saved, i.e. (abstractly) deliverance; hence, aid, victory, prosperity deliverance, health, help(-ing), salvation, save, saving (health), welfare.', 'feminine passive participle of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4194}/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["and/ to <the>/ death"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869A}/H9025/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ view/ our"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6743B}/H9012/[H6743]', 'inflected', 'heb', 'צָלַח', '["tsâlach"]', '["grant success/ !"]', '["v"]', 'to push forward, in various senses (literal or figurative, transitive or intransitive) break out, come (mightily), go over, be good, be meet, be profitable, (cause to, effect, make to, send) prosper(-ity, -ous, -ously).', 'or צָלֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1288}/H9036/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["we bless/ you"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6490}/H9021/[H6485]', 'inflected', 'heb', 'פִּקּוּד', '["piqqûwd"]', '["<of> precepts/ your","precepts/ your"]', '["n-m"]', 'properly, appointed, i.e. a mandate (of God; plural only, collectively, for the Law) commandment, precept, statute.', 'or פִּקֻּד; from 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2706G}/H9021/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["decrees/ your"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5027}/H9040/[H5027]', 'inflected', 'heb', 'נָבַט', '["nâbaṭ"]', '["when/ look/ I"]', '["v"]', 'to scan, i.e. look intently at; by implication, to regard with pleasure, favor or care (cause to) behold, consider, look (down), regard, have respect, see.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3925H}/H9040/[H3925]', 'inflected', 'heb', 'לָמַד', '["lâmad"]', '["when/ learn/ I"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0734}/H9023/[H732]', 'inflected', 'heb', 'אֹרַח', '["ʼôrach"]', '["path/ his","ways/ his"]', '["n-m"]', 'a well-trodden road (literally or figuratively); also a caravan manner, path, race, rank, traveller, troop, (by-, high-) way.', 'from 732;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7686}/H9030/[H7686]', 'inflected', 'heb', 'שָׁגָה', '["shâgâh"]', '["you allow to stray/ me"]', '["v"]', 'to stray (causatively, mislead), usually (figuratively) to mistake, especially (morally) to transgress; by extension (through the idea of intoxication) to reel, (figuratively) be enraptured (cause to) go astray, deceive, err, be ravished, sin through ignorance, (let, make to) wander.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8193G}/H9020/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["with/ lips/ my"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6490}/H9021/[H6485]', 'inflected', 'heb', 'פִּקּוּד', '["piqqûwd"]', '["on/ precepts/ your"]', '["n-m"]', 'properly, appointed, i.e. a mandate (of God; plural only, collectively, for the Law) commandment, precept, statute.', 'or פִּקֻּד; from 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2708}/H9021/[H2706]', 'inflected', 'heb', 'חֻקָּה', '["chuqqâh"]', '["in/ statutes/ your"]', '["n-f"]', 'appointed, custom, manner, ordinance, site, statute.', 'feminine of 2706, and meaning substantially the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8451}/H9021/[H3384]', 'inflected', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["from/ law/ your"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1638}/[H1638]', 'lemma', 'heb', 'גָּרַס', '["gâraç"]', '["it is crushed"]', '["v"]', 'to crush; also (intransitively and figuratively) to dissolve break.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8375}/[H8374]', 'inflected', 'heb', 'תַּאֲבָה', '["taʼăbâh"]', '["for/ longing"]', '["n-f"]', 'desire longing.', 'from 8374 (compare 15);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7686}/[H7686]', 'inflected', 'heb', 'שָׁגָה', '["shâgâh"]', '["who/ go astray"]', '["v"]', 'to stray (causatively, mislead), usually (figuratively) to mistake, especially (morally) to transgress; by extension (through the idea of intoxication) to reel, (figuratively) be enraptured (cause to) go astray, deceive, err, be ravished, sin through ignorance, (let, make to) wander.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2706G}/H9021/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["for/ decrees/ your","in/ decrees/ your","on/ decrees/ your"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8191}/H9020/[H8173]', 'inflected', 'heb', 'שַׁעְשֻׁעַ', '["shaʻshuaʻ"]', '["[are] delight<s>/ my","[had been] delight<s>/ my","[is] delight<s>/ my"]', '["n-m"]', 'enjoyment delight, pleasure.', 'from 8173;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0995}/H9030/[H995]', 'inflected', 'heb', 'בִּין', '["bîyn"]', '["give understanding of/ me","give understanding/ me"]', '["v"]', 'to separate mentally (or distinguish), i.e.(generally) understand attend, consider, be cunning, diligently, direct, discern, eloquent, feel, inform, instruct, have intelligence, know, look well to, mark, perceive, be prudent, regard, (can) skill(-full), teach, think, (cause, make to, get, give, have) understand(-ing), view, (deal) wise(-ly, man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7878}/[H7878]', 'inflected', 'heb', 'שִׂיחַ', '["sîyach"]', '["and/ I will meditate","so/ let me meditate"]', '["v"]', 'to ponder, i.e. (by implication) converse (with oneself, and hence, aloud) or (transitively) utter commune, complain, declare, meditate, muse, pray, speak, talk (with).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6381}/H9021/[H6381]', 'inflected', 'heb', 'פָּלָא', '["pâlâʼ"]', '["on/ wonders/ your"]', '["v"]', 'properly, perhaps to separate, i.e. distinguish (literally or figuratively); by implication, to be (causatively, make) great, difficult, wonderful accomplish, (arise...too, be too) hard, hidden, things too high, (be, do, do a, shew) marvelous(-ly, -els, things, work), miracles, perform, separate, make singular, (be, great, make) wonderful(-ers, -ly, things, works), wondrous (things, works, -ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8424}/[H3013]', 'inflected', 'heb', 'תּוּגָה', '["tûwgâh"]', '["from/ grief"]', '["n-f"]', 'depression (of spirits); concretely a grief heaviness, sorrow.', 'from 3013;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965I}/H9030/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["strengthen/ me"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5715}/H9021/[H5707]', 'inflected', 'heb', 'עֵדוּת', '["ʻêdûwth"]', '["to/ testimonies/ your"]', '["n-f"]', 'testimony testimony, witness.', 'feminine of 5707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0954}/H9030/[H954]', 'inflected', 'heb', 'בּוּשׁ', '["bûwsh"]', '["you put to shame/ me"]', '["v"]', 'properly, to pale, i.e. by implication to be ashamed; also (by implication) to be disappointed or delayed (be, make, bring to, cause, put to, with, a-) shamed(-d), be (put to) confounded(-fusion), become dry, delay, be long.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5341}/H9034/[H5341]', 'inflected', 'heb', 'נָצַר', '["nâtsar"]', '["so/ I may observe/ it"]', '["v"]', 'to guard, in a good sense (to protect, maintain, obey, etc.) or a bad one (to conceal, etc.) besieged, hidden thing, keep(-er, -ing), monument, observe, preserve(-r), subtil, watcher(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5341}/[H5341]', 'inflected', 'heb', 'נָצַר', '["nâtsar"]', '["and/ [one who] guards","and/ [the] preserved [ones] of","and/ guarded of","and/ let me observe","and/ secret [things]","so/ let me observe"]', '["v"]', 'to guard, in a good sense (to protect, maintain, obey, etc.) or a bad one (to conceal, etc.) besieged, hidden thing, keep(-er, -ing), monument, observe, preserve(-r), subtil, watcher(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8104G}/H9034/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["so/ I may keep/ it"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H5410A>', 'inflected', 'heb', 'בנתיב', '["bi/n.Tiv"]', '["in/ [the] path of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3374}/H9021/[H3373]', 'inflected', 'heb', 'יִרְאָה', '["yirʼâh"]', '["[is] for/ fear/ your"]', '["n-f"]', 'fear (also used as infinitive); morally, reverence × dreadful, × exceedingly, fear(-fulness).', 'feminine of 3373;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8373}/[H8373]', 'lemma', 'heb', 'תָּאַב', '["tâʼab"]', '["I long"]', '["v"]', 'to desire long.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6490}/H9021/[H6485]', 'inflected', 'heb', 'פִּקּוּד', '["piqqûwd"]', '["for/ precepts/ your"]', '["n-m"]', 'properly, appointed, i.e. a mandate (of God; plural only, collectively, for the Law) commandment, precept, statute.', 'or פִּקֻּד; from 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0935G}/H9030/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ may they come to/ me"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0565A}/H9021/[H561]', 'inflected', 'heb', 'אִמְרָה', '["ʼimrâh"]', '["according to/ word/ your"]', '["n-f"]', 'commandment, speech, word.', 'or אֶמְרָה; feminine of 561, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1697G}/H9021/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["in/ word/ your","on/ words/ your"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6310G}/H9020/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["from/ mouth/ my"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4941G}/H9021/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["for/ judgments/ your"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7342H}/[H7337]', 'inflected', 'heb', 'רָחָב', '["râchâb"]', '["in the/ broad place"]', '["a"]', 'roomy, in any (or every) direction, literally or figuratively broad, large, at liberty, proud, wide.', 'from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5713B}/H9021/[H5707]', 'inflected', 'heb', 'עֵדָה', '["ʻêdâh"]', '["in/ testimonies/ your"]', '["n-f"]', 'testimony testimony, witness. Compare 5712.', 'feminine of 5707 in its techn. sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8173B}/[H8173]', 'inflected', 'heb', 'שָׁעַע', '["shâʻaʻ"]', '["and/ I may delight myself"]', '["v"]', '(in a good acceptation) to look upon (with complacency), i.e. fondle, please or amuse (self); (in a bad one) to look about (in dismay), i.e. stare cry (out) (by confusion with 7768), dandle, delight (self), play, shut.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4687}/H9021/[H6680]', 'inflected', 'heb', 'מִצְוָה', '["mitsvâh"]', '["in/ commandments/ your"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3176H}/H9030/[H3176]', 'inflected', 'heb', 'יָחַל', '["yâchal"]', '["you have made hope/ me"]', '["v"]', 'to wait; by implication, to be patient, hope (cause to, have, make to) hope, be pained, stay, tarry, trust, wait.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8104G}/H9012/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["and/ I have kept/ !"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5749A}/H9030/[H5749]', 'inflected', 'heb', 'עוּד', '["ʻûwd"]', '["they have surrounded/ me"]', '["v"]', 'to duplicate or repeat; by implication, to protest, testify (as by reiteration); intensively, to encompass, restore (as a sort of reduplication) admonish, charge, earnestly, lift up, protest, call (take) to record, relieve, rob, solemnly, stand upright, testify, give warning, (bear, call to, give, take to) witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2676}/[H2673]', 'lemma', 'heb', 'חָצוֹת', '["châtsôwth"]', '["[the] middle of"]', '["n-f"]', 'the middle (of the night) mid(-night).', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2270}/[H2266]', 'lemma', 'heb', 'חָבֵר', '["châbêr"]', '["[am] a companion","[is] a companion","companions"]', '["n-m"]', 'an associate companion, fellow, knit together.', 'from 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3372H}/H9031/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["awesome [deeds]/ your","they fear/ you","will he fear/ you"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2954}/[H2954]', 'lemma', 'heb', 'טָפַשׁ', '["ṭâphash"]', '["it is insensitive"]', '["v"]', 'properly, apparently to be thick; figuratively, to be stupid be fat.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3559I}/H9030/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["and/ they prepared/ me"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3925H}/[H3925]', 'inflected', 'heb', 'לָמַד', '["lâmad"]', '["so/ let me learn"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3373}/H9021/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["[those] fearing/ you"]', '["a"]', 'fearing; morally, reverent afraid, fear (-ful).', 'from 3372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1697M}/H9021/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["for/ word/ your"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0530}/[H529]', 'inflected', 'heb', 'אֱמוּנָה', '["ʼĕmûwnâh"]', '["and/ faithfulness"]', '["n-f"]', 'literally firmness; figuratively security; morally fidelity faith(-ful, -ly, -ness, (man)), set office, stability, steady, truly, truth, verily.', 'or (shortened) אֱמֻנָה; feminine of 529;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5162G}/H9030/[H5162]', 'inflected', 'heb', 'נָחַם', '["nâcham"]', '["to/ comfort/ me"]', '["v"]', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8668G}/H9021/[H7768]', 'inflected', 'heb', 'תְּשׁוּעָה', '["tᵉshûwʻâh"]', '["for/ salvation/ your"]', '["n-f"]', 'rescue (literal or figurative, persons, national or spiritual) deliverance, help, safety, salvation, victory.', 'or תְּשֻׁעָה; from 7768 in the sense of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1697G}/H9021/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["for/ word/ your"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0565A}/H9021/[H561]', 'inflected', 'heb', 'אִמְרָה', '["ʼimrâh"]', '["for/ word/ your","to/ word/ your"]', '["n-f"]', 'commandment, speech, word.', 'or אֶמְרָה; feminine of 561, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H4997>', 'inflected', 'heb', 'כנאד', '["ke./Nod"]', '["like/ a skin-bottle"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7008}/[H6999]', 'inflected', 'heb', 'קִיטוֹר', '["qîyṭôwr"]', '["in/ smoke"]', '["n-m"]', 'a fume, i.e. cloud smoke, vapour.', 'or קִיטֹר; from 6999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7291}/H9030/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["in/ [those who] harass/ me"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8451}/H9021/[H3384]', 'inflected', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["[are] according to/ law/ your"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3615G}/H9030/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["they have made an end of/ me"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4941I}/H9021/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["for/ judgments/ your"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0006}/H9030/[H6]', 'inflected', 'heb', 'אָבַד', '["ʼâbad"]', '["to/ destroy/ me"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8502}/[H3615]', 'lemma', 'heb', 'תִּכְלָה', '["tiklâh"]', '["perfection"]', '["n-f"]', 'completeness perfection.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7881}/H9020/[H7879]', 'inflected', 'heb', 'שִׂיחָה', '["sîychâh"]', '["[is] meditation/ my"]', '["n-f"]', 'reflection; by extension, devotion meditation, prayer.', 'feminine of 7879;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2449}/H9030/[H2449]', 'inflected', 'heb', 'חָכַם', '["châkam"]', '["it makes wise/ me"]', '["v"]', 'to be wise (in mind, word or act) × exceeding, teach wisdom, be (make self, shew self) wise, deal (never so) wisely, make wiser.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2205H}/[H2204]', 'inflected', 'heb', 'זָקֵן', '["zâqên"]', '["more than/ old [people]"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4941G}/H9021/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["from/ judgments/ your"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4452}/[H4452]', 'lemma', 'heb', 'מָלַץ', '["mâlats"]', '["they are smooth"]', '["v"]', 'to be smooth, i.e. (figuratively) pleasant be sweet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2441}/H9020/[H2596]', 'inflected', 'heb', 'חֵךְ', '["chêk"]', '["to/ palate/ my"]', '["n-m"]', 'properly, the palate or inside of the mouth; hence, the mouth itself (as the organ of speech, taste and kissing) (roof of the) mouth, taste.', 'probably from 2596 in the sense of tasting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6490}/H9021/[H6485]', 'inflected', 'heb', 'פִּקּוּד', '["piqqûwd"]', '["from/ precepts/ your"]', '["n-m"]', 'properly, appointed, i.e. a mandate (of God; plural only, collectively, for the Law) commandment, precept, statute.', 'or פִּקֻּד; from 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H5410B>/H9020', 'inflected', 'heb', 'לנתיבתי', '["li/n.ti.va.T/i"]', '["for/ pathway/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6965I}/H9012/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["and/ I have confirmed/ !"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4941G}/H9021/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["and/ judgments/ your"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6490}/H9021/[H6485]', 'inflected', 'heb', 'פִּקּוּד', '["piqqûwd"]', '["and/ from/ precepts/ your"]', '["n-m"]', 'properly, appointed, i.e. a mandate (of God; plural only, collectively, for the Law) commandment, precept, statute.', 'or פִּקֻּד; from 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5588}/[H5586]', 'lemma', 'heb', 'סֵעֵף', '["çêʻêph"]', '["half-hearted people"]', '["a"]', 'divided (in mind), i.e. (concretely) a skeptic thought.', 'from 5586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5643A}/H9020/[H5641]', 'inflected', 'heb', 'סֵתֶר', '["çêther"]', '["[are] hiding place/ my"]', '["n-m"]', 'a cover (in a good or a bad, a literal or a figurative sense) backbiting, covering, covert, × disguise(-th), hiding place, privily, protection, secret(-ly, place).', 'or (feminine) סִתְרָה; (Deuteronomy 32:38), from 5641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7664}/H9020/[H7663]', 'inflected', 'heb', 'שֵׂבֶר', '["sêber"]', '["from/ hope/ my"]', '["n-m"]', 'expectation hope.', 'from 7663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8159}/[H8159]', 'inflected', 'heb', 'שָׁעָה', '["shâʻâh"]', '["and/ I may have regard","and/ let us fear"]', '["v"]', 'to gaze at or about (properly, for help); by implication, to inspect, consider, compassionate, be nonplussed (as looking around in amazement) or bewildered depart, be dim, be dismayed, look (away), regard, have respect, spare, turn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5541A}/[H5541]', 'lemma', 'heb', 'סָלָה', '["çâlâh"]', '["he has thrown away","you reject"]', '["v"]', 'to hang up, i.e. weigh, or (figuratively) contemn tread down (under foot), value.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2706G}/H9021/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["from/ decrees/ your"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8649B}/H9028/[H7411]', 'inflected', 'heb', 'תׇּרְמָה', '["tormâh"]', '["deceitfulness/ their"]', '["n-f"]', 'fraud deceit(-ful), privily.', 'and תַּרְמוּת; or תַּרְמִית; from 7411;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5509}/[H5472]', 'lemma', 'heb', 'סִיג', '["çîyg"]', '["dross<es>"]', '["n-m"]', 'scoria dross.', 'or סוּג; (Ezekiel 22:18), from 5472 in the sense of refuse;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6343}/H9021/[H6342]', 'inflected', 'heb', 'פַּחַד', '["pachad"]', '["from/ dread of/ you"]', '["n-m"]', 'a (sudden) alarm (properly, the object feared, by implication, the feeling) dread(-ful), fear, (thing) great (fear, -ly feared), terror.', 'from 6342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4941G}/H9021/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["and/ from/ judgments/ your"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5117}/H9030/[H5117]', 'inflected', 'heb', 'נוּחַ', '["nûwach"]', '["you will abandon/ me"]', '["v"]', 'to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6231}/H9030/[H6229]', 'inflected', 'heb', 'עָשַׁק', '["ʻâshaq"]', '["to/ oppressors/ my"]', '["v"]', 'to press upon, i.e. oppress, defraud, violate, overflow get deceitfully, deceive, defraud, drink up, (use) oppress(-ion), -or), do violence (wrong).', 'a primitive root (compare 6229);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6231}/H9030/[H6229]', 'inflected', 'heb', 'עָשַׁק', '["ʻâshaq"]', '["they oppress/ me"]', '["v"]', 'to press upon, i.e. oppress, defraud, violate, overflow get deceitfully, deceive, defraud, drink up, (use) oppress(-ion), -or), do violence (wrong).', 'a primitive root (compare 6229);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0565A}/[H561]', 'inflected', 'heb', 'אִמְרָה', '["ʼimrâh"]', '["and/ for/ [the] word of"]', '["n-f"]', 'commandment, speech, word.', 'or אֶמְרָה; feminine of 561, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5341}/H9038/[H5341]', 'inflected', 'heb', 'נָצַר', '["nâtsar"]', '["it observes/ them"]', '["v"]', 'to guard, in a good sense (to protect, maintain, obey, etc.) or a bad one (to conceal, etc.) besieged, hidden thing, keep(-er, -ing), monument, observe, preserve(-r), subtil, watcher(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6608}/[H6605]', 'lemma', 'heb', 'פֵּתַח', '["pêthach"]', '["[the] opening of"]', '["n-m"]', 'opening (figuratively) i.e. disclosure entrance.', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7602A}/H9012/[H7602]', 'inflected', 'heb', 'שָׁאַף', '["shâʼaph"]', '["and/ I panted/ !"]', '["v"]', 'to inhale eagerly; figuratively, to cover; by implication, to be angry; also to hasten desire (earnestly), devour, haste, pant, snuff up, swallow up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2968}/[H2968]', 'lemma', 'heb', 'יָאַב', '["yâʼab"]', '["I longed"]', '["v"]', 'to desire long.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0565A}/H9021/[H561]', 'inflected', 'heb', 'אִמְרָה', '["ʼimrâh"]', '["by/ word/ your","on/ word/ your"]', '["n-f"]', 'commandment, speech, word.', 'or אֶמְרָה; feminine of 561, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6233}/[H6231]', 'inflected', 'heb', 'עֹשֶׁק', '["ʻôsheq"]', '["from/ oppression","from/ oppression of"]', '["n-m"]', 'injury, fraud, (subjectively) distress, (concretely) unjust gain cruelly, extortion, oppression, thing (deceitfully gotten).', 'from 6231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4689}/[H6693]', 'inflected', 'heb', 'מָצוֹק', '["mâtsôwq"]', '["and/ anguish"]', '["n-m"]', 'a narrow place, i.e. (abstractly and figuratively) confinement or disability anguish, distress, straitness.', 'from 6693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7768}/H9012/[H7768]', 'inflected', 'heb', 'שָׁוַע', '["shâvaʻ"]', '["and/ I cried for help/ !"]', '["v"]', 'properly, to be free; but used only causatively and reflexively, to halloo (for help, i.e. freedom from some trouble) cry (aloud, out), shout.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0821}/[H8104]', 'lemma', 'heb', 'אַשְׁמֻרָה', '["ʼashmurâh"]', '["[the] night-watches"]', '["n-f"]', 'a night watch watch.', 'or אַשׁמוּרָה; or אַשׁמֹרֶת; (feminine) from 8104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7878}/[H7878]', 'inflected', 'heb', 'שִׂיחַ', '["sîyach"]', '["to/ meditate"]', '["v"]', 'to ponder, i.e. (by implication) converse (with oneself, and hence, aloud) or (transitively) utter commune, complain, declare, meditate, muse, pray, speak, talk (with).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4941H}/H9021/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["according to/ judgments/ your"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5713B}/H9021/[H5707]', 'inflected', 'heb', 'עֵדָה', '["ʻêdâh"]', '["from/ testimonies/ your"]', '["n-f"]', 'testimony testimony, witness. Compare 5712.', 'feminine of 5707 in its techn. sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2502A}/H9030/[H2502]', 'inflected', 'heb', 'חָלַץ', '["châlats"]', '["and/ rescue/ me"]', '["v"]', 'to pull off; hence (intensively) to strip, (reflex.) to depart; by implication, to deliver, equip (for fight); present, strengthen arm (self), (go, ready) armed (× man, soldier), deliver, draw out, make fat, loose, (ready) prepared, put off, take away, withdraw self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1350A}/H9030/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["and/ redeem/ me"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4941G}/H9021/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["according to/ judgments/ your"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6862C}/H9020/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["and/ foes/ my"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5715}/H9021/[H5707]', 'inflected', 'heb', 'עֵדוּת', '["ʻêdûwth"]', '["from/ testimonies/ your"]', '["n-f"]', 'testimony testimony, witness.', 'feminine of 5707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6962}/H9012/[H6962]', 'inflected', 'heb', 'קוּט', '["qûwṭ"]', '["and/ I felt disgust/ !"]', '["v"]', 'properly, to cut off, i.e. (figuratively) detest begrieved, loathe self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5769G}/[H5956]', 'inflected', 'heb', 'עוֹלָם', '["ʻôwlâm"]', '["and/ [is] for/ ever"]', '["n-m"]', 'properly, concealed, i.e. the vanishing point; generally, time out of mind (past or future), i.e. (practically) eternity; frequentatively, adverbial (especially with prepositional prefix) always alway(-s), ancient (time), any more, continuance, eternal, (for, (n-)) ever(-lasting, -more, of old), lasting, long (time), (of) old (time), perpetual, at any time, (beginning of the) world ( without end). Compare 5331, 5703.', 'or עֹלָם; from 5956;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1697G}/H9021/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["and/ from/ word/ your"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4672}/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["like/ [one who] brings out","like/ [one who] finds"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4687}/H9021/[H6680]', 'inflected', 'heb', 'מִצְוָה', '["mitsvâh"]', '["and/ commandments/ your"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0157G}/H9038/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["and/ I have loved/ them"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5713B}/H9021/[H5707]', 'inflected', 'heb', 'עֵדָה', '["ʻêdâh"]', '["and/ testimonies/ your"]', '["n-f"]', 'testimony testimony, witness. Compare 5712.', 'feminine of 5707 in its techn. sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1984B}/H9031/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["so/ it may praise/ you"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7716}/[H7582]', 'inflected', 'heb', 'שֶׂה', '["seh"]', '["like <the>/ sheep","like/ a sheep"]', '["n-m"]', 'a member of a flock, i.e. a sheep or goat (lesser, small) cattle, ewe, goat, lamb, sheep. Compare 2089.', 'or שֵׂי; probably from 7582 through the idea of pushing out to graze;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6869B}/H9011/[H6862]', 'inflected', 'heb', 'צָרָה', '["tsârâh"]', '["in <the>/ distress/ <towards>"]', '["n-f"]', 'tightness (i.e. figuratively, trouble); transitively, a female rival adversary, adversity, affliction, anguish, distress, tribulation, trouble.', 'feminine of 6862;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8193G}/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["from/ a lip of"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3956G}/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["from/ a tongue"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0190}/[H188]', 'lemma', 'heb', 'אוֹיָה', '["ʼôwyâh"]', '["woe!"]', '["inj"]', 'woe.', 'feminine of 188');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4902H}/[H4901]', 'lemma', 'heb', 'מֶשֶׁךְ', '["Meshek"]', '["Meshech"]', '["n-pr-m"]', 'Meshek, a son of Japheth, and the people descended from him Mesech, Meshech.', 'the same in form as 4901, but probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6938}/[H6937]', 'lemma', 'heb', 'קֵדָר', '["Qêdâr"]', '["Kedar"]', '["n-pr"]', 'Kedar, a son of Ishmael; also (collectively) Bedouin (as his descendants or representatives) Kedar.', 'from 6937; dusky (of the skin or the tent);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4609B}/[H4608]', 'inflected', 'heb', 'מַעֲלָה', '["maʻălâh"]', '["of the/ ascents"]', '["n-f"]', 'elevation, i.e. the act (literally, a journey to a higher place, figuratively, a thought arising), or (concretely) the condition (literally, a step or grade-mark, figuratively, a superiority of station); specifically a climactic progression (in certain Psalms) things that come up, (high) degree, deal, go up, stair, step, story.', 'feminine of 4608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8104H}/H9031/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["[is] protector/ your","he will protect/ you","protector/ your"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6738}/H9021/[H6751]', 'inflected', 'heb', 'צֵל', '["tsêl"]', '["[is] shade/ your"]', '["n-m"]', 'shade, whether literal or figurative defence, shade(-ow).', 'from 6751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8179G}/H9022/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["in/ gates/ your"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5892B}/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["like <the>/ cities","like the/ cities","like/ a city"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H2266}/[H2266]', 'inflected', 'heb', 'חָבַר', '["châbar"]', '["that/ <it> was joined together"]', '["v"]', 'to join (literally or figuratively); specifically (by means of spells) to fascinate charm(-er), be compact, couple (together), have fellowship with, heap up, join (self, together), league.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H8033G}/[H834]', 'inflected', 'heb', 'שָׁם', '["shâm"]', '["where/ there"]', '["adv"]', 'there (transferring to time) then; often thither, or thence in it, thence, there (-in, of, out), thither, whither.', 'a primitive particle (rather from the relative pronoun, 834);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2426}/H9022/[H2428]', 'inflected', 'heb', 'חֵיל', '["chêyl"]', '["in/ rampart/ your"]', '["n-m"]', 'an army; also (by analogy,) an intrenchment army, bulwark, host, poor, rampart, trench, wall.', 'or (shortened) חֵל; a collateral form of 2428;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7962}/[H7951]', 'lemma', 'heb', 'שַׁלְוָה', '["shalvâh"]', '["ease"]', '["n-f"]', 'security (genuine or false) abundance, peace(-ably), prosperity, quietness.', 'from 7951;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0759H>/H9022', 'inflected', 'heb', 'בארמנותיך', '["be./''ar.me.no.Ta.yi/kh"]', '["in/ fortresses/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5869A}/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["like/ [the] eyes of"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H2603A}/H9035/[H2583]', 'inflected', 'heb', 'חָנַן', '["chânan"]', '["that/ he will show favor to/ us"]', '["v"]', 'properly, to bend or stoop in kindness to an inferior; to favor, bestow; causatively to implore (i.e. move to favor by petition) beseech, × fair, (be, find, shew) favour(-able), be (deal, give, grant (gracious(-ly), intreat, (be) merciful, have (shew) mercy (on, upon), have pity upon, pray, make supplication, × very.', 'a primitive root (compare 2583);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3933}/[H3932]', 'inflected', 'heb', 'לַעַג', '["laʻag"]', '["the/ mockery of"]', '["n-m"]', 'derision, scoffing derision, scorn (-ing).', 'from 3932;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7600}/[H7599]', 'inflected', 'heb', 'שַׁאֲנָן', '["shaʼănân"]', '["<the>/ at ease","<the>/ self-confident [people]","the/ [people] at ease"]', '["a"]', 'secure; in a bad sense, haughty that is at ease, quiet, tumult. Compare 7946.', 'from 7599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0937}/[H936]', 'inflected', 'heb', 'בּוּז', '["bûwz"]', '["the/ contempt"]', '["n-m"]', 'disrespect contempt(-uously), despised, shamed.', 'from 936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1343}/ /{H3238}/[H1342]', 'inflected', 'heb', 'גֵּאֶה', '["gêʼeh"]', '["of/ arrogant/ /opressors"]', '["a"]', 'lofty; figuratively, arrogant proud.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H1961}/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["<that>/ it has been","[is] which/ <it> will be","[that] which/ <it> has been","[that] which/ <they> will be","that/ <it> is","that/ <it> will be","that/ he was","that/ they will be","that/ will it be","who/ <he> was","who/ <he> will be","who/ <they> were","who/ <they> will be"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0233}/[H227]', 'lemma', 'heb', 'אֲזַי', '["ʼăzay"]', '["then"]', '["adv"]', 'at that time then.', 'probably from 227;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2734}/[H2787]', 'inflected', 'heb', 'חָרָה', '["chârâh"]', '["when/ burned"]', '["v"]', 'to glow or grow warm; figuratively (usually) to blaze up, of anger, zeal, jealousy be angry, burn, be displeased, × earnestly, fret self, grieve, be (wax) hot, be incensed, kindle, × very, be wroth. See 8474.', 'a primitive root (compare 2787);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7857}/H9035/[H7857]', 'inflected', 'heb', 'שָׁטַף', '["shâṭaph"]', '["they had overflowed/ us"]', '["v"]', 'to gush; by implication, to inundate, cleanse; by analogy, to gallop, conquer drown, (over-) flow(-whelm, rinse, run, rush, (throughly) wash (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5158A}/H9011/[H5157]', 'inflected', 'heb', 'נַחַל', '["nachal"]', '["a torrent/ <towards>"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2121}/[H2102]', 'inflected', 'heb', 'זֵידוֹן', '["zêydôwn"]', '["<the>/ raging"]', '["a"]', 'boiling of water, i.e. wave proud.', 'from 2102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H3808}/[H3808]', 'inflected', 'heb', 'לֹא', '["lôʼ"]', '["that/ not","who/ not"]', '["adv"]', 'not (the simple or abs. negation); by implication, no; often used with other particles × before, or else, ere, except, ig(-norant), much, less, nay, neither, never, no((-ne), -r, (-thing)), (× as though...,(can-), for) not (out of), of nought, otherwise, out of, surely, as truly as, of a truth, verily, for want, whether, without.', 'or לוֹא; or לֹה; (Deuteronomy 3:11), a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414G}/H9035/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["he has given/ us"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8127G}/H9028/[H8150]', 'inflected', 'heb', 'שֵׁן', '["shên"]', '["to/ teeth/ their"]', '["n-f"]', 'a tooth (as sharp); specifically ivory; figuratively, a cliff crag, × forefront, ivory, × sharp, tooth.', 'from 8150; compare 8143');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6341A}/[H6351]', 'inflected', 'heb', 'פַּח', '["pach"]', '["the/ snare"]', '["n-m"]', 'a (metallic) sheet (as pounded thin); also a spring net (as spread out like a lamina) gin, (thin) plate, snare.', 'from 6351;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2022G}/[H2042]', 'inflected', 'heb', 'הַר', '["har"]', '["[are] like/ [the] mountain of","like/ [the] mountain of"]', '["n-m"]', 'a mountain or range of hills (sometimes used figuratively) hill (country), mount(-ain), × promotion.', 'a shortened form of 2042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7562}/[H7561]', 'inflected', 'heb', 'רֶשַׁע', '["reshaʻ"]', '["<the>/ wickedness"]', '["n-m"]', 'a wrong (especially moral) iniquity, wicked(-ness).', 'from 7561;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5766B}/[H5765]', 'inflected', 'heb', 'עֶוֶל', '["ʻevel"]', '["by/ injustice","in/ injustice","with/ injustice"]', '["n-m"]', '(moral) evil iniquity, perverseness, unjust(-ly), unrighteousness(-ly); wicked(-ness).', 'or עָוֶל; and (feminine) עַוְלָה; or עוֹלָה; or עֹלָה; from 5765;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3826}/H9028/[H3820]', 'inflected', 'heb', 'לִבָּה', '["libbâh"]', '["in/ hearts/ their"]', '["n-f"]', 'the heart heart.', 'feminine of 3820;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5186}/[H5186]', 'inflected', 'heb', 'נָטָה', '["nâṭâh"]', '["and/ those/ [who] turn aside"]', '["v"]', 'to stretch or spread out; by implication, to bend away (including moral deflection); used in a great variety of application (as follows) afternoon, apply, bow (down, -ing), carry aside, decline, deliver, extend, go down, be gone, incline, intend, lay, let down, offer, outstretched, overthrown, pervert, pitch, prolong, put away, shew, spread (out), stretch (forth, out), take (aside), turn (aside, away), wrest, cause to yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6128}/H9028/[H6127]', 'inflected', 'heb', 'עֲקַלְקַל', '["ʻăqalqal"]', '["twisting [ways]/ their"]', '["a"]', 'winding by(-way), crooked way.', 'from 6127;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980G}/H9038/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["he will lead away/ them"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0205G>', 'inflected', 'heb', 'האון', '["ha./''A.ven"]', '["<of the>/ wickedness"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7870}/[H7725]', 'lemma', 'heb', 'שִׁיבָה', '["shîybâh"]', '["[the] restoration of"]', '["n-m"]', 'a return (of property) captivity.', 'by permutation from 7725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2492B}/[H2492]', 'inflected', 'heb', 'חָלַם', '["châlam"]', '["like/ [those who] dream"]', '["v"]', 'properly, to bind firmly, i.e. (by implication) to be (causatively to make) plump; also (through the figurative sense of dumbness) to dream (cause to) dream(-er), be in good liking, recover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6310G}/H9025/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["mouth/ our"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3956G}/H9025/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["and/ tongue/ our"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7622}/H9025/[H7617]', 'inflected', 'heb', 'שְׁבוּת', '["shᵉbûwth"]', '["captivity/ our"]', '["n-f"]', 'exile, concretely, prisoners; figuratively, a former state of prosperity captive(-ity).', 'or שְׁבִית; from 7617;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2232}/[H2232]', 'inflected', 'heb', 'זָרַע', '["zâraʻ"]', '["those/ [who] sow"]', '["v"]', 'to sow; figuratively, to disseminate, plant, fructify bear, conceive seed, set with sow(-er), yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4901}/[H4900]', 'lemma', 'heb', 'מֶשֶׁךְ', '["meshek"]', '["<the> bag of"]', '["n-m"]', 'a sowing; also a possession precious, price.', 'from 4900;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0485}/H9023/[H481]', 'inflected', 'heb', 'אֲלֻמָּה', '["ʼălummâh"]', '["sheaves/ his"]', '["n-f"]', 'something bound; a sheaf sheaf.', 'or (masculine) אָלֻם; passive participle of 481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5998}/[H5998]', 'lemma', 'heb', 'עָמַל', '["ʻâmal"]', '["he toiled","he toils","it labors","they have toiled","you had toiled"]', '["v"]', 'to toil, i.e. work severely and with irksomeness (take) labour (in).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6089A}/[H6087]', 'inflected', 'heb', 'עֶצֶב', '["ʻetseb"]', '["<the>/ labors"]', '["n-m"]', 'an earthen vessel; usually (painful) toil; also a pang (whether of body or mind) grievous, idol, labor, sorrow.', 'from 6087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3039A}/H9023/[H1730]', 'inflected', 'heb', 'יְדִיד', '["yᵉdîyd"]', '["to/ beloved [one]/ his"]', '["a n-f"]', 'loved amiable, (well-) beloved, loves.', 'from the same as 1730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2671}/[H2686]', 'inflected', 'heb', 'חֵץ', '["chêts"]', '["like/ arrows"]', '["n-m"]', 'properly, a piercer, i.e. an arrow; by implication, a wound; figuratively, (of God) thunder-bolt; the shaft of a spear archer, arrow, dart, shaft, staff, wound.', 'from 2686; also by interchange for 6086');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5271A}/[H5288]', 'inflected', 'heb', 'נָעוּר', '["nâʻûwr"]', '["<the>/ youth<s>"]', '["n-m n-f"]', '(only in plural collective or emphatic form) youth, the state (juvenility) or the persons (young people) childhood, youth.', 'or נָעֻר; and (feminine) נְעֻרָה; properly, passive participle from 5288 as denominative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0827}/H9023/[H825]', 'inflected', 'heb', 'אַשְׁפָּה', '["ʼashpâh"]', '["quiver/ his","quiver/ its"]', '["n-f"]', 'a quiver or arrow-case quiver.', 'perhaps (feminine) from the same as 825 (in the sense of covering);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8363}/[H8362]', 'inflected', 'heb', 'שְׁתִל', '["shᵉthil"]', '["[will be] like/ shoots of"]', '["n-m"]', 'a sprig (as if transplanted), i.e. sucker plant.', 'from 8362;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7979}/H9021/[H7971]', 'inflected', 'heb', 'שֻׁלְחָן', '["shulchân"]', '["<to>/ table/ your"]', '["n-m"]', 'a table (as spread out); by implication, a meal table.', 'from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1354>/H9020', 'opaque', 'heb', 'גַב', '["gab"]', '["back/ my"]', '["n"]', 'the back (as rounded); by analogy, the top or rim, a boss, a vault, arch of eye, bulwarks, etc. back, body, boss, eminent (higher) place, (eye) brows, nave, ring.', 'from an unused root meaning to hollow or curve; (compare 1460 and 1479)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4618}/H9028/[H6031]', 'inflected', 'heb', 'מַעֲנָה', '["maʻănâh"]', '["<to>/ furrows/ their"]', '["n-f"]', 'a furrow acre, furrow.', 'from 6031, in the sense of depression or tilling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5472}/[H5472]', 'inflected', 'heb', 'סוּג', '["çûwg"]', '["and/ they may be turned back"]', '["v"]', 'properly, to flinch, i.e. (by implication) to go back, literally (to retreat) or figuratively (to apostatize) backslider, drive, go back, turn (away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H6927}/[H6923]', 'inflected', 'heb', 'קַדְמָה', '["qadmâh"]', '["that/ before"]', '["n-f"]', 'priority (in time); also used adverbially (before) afore, antiquity, former (old) estate.', 'from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H2683>/H9023', 'inflected', 'heb', 'וחצנו', '["ve./chitz.N/o"]', '["and/ bosom/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6014A}/[H6016]', 'lemma', 'heb', 'עָמַר', '["ʻâmar"]', '["[one who] binds sheaves"]', '["v"]', 'properly, apparently to heap; figuratively, to chastise (as if piling blows); to gather grain bind sheaves, make merchandise of.', 'a primitive root; specifically (as denominative from 6016)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4615}/[H6009]', 'inflected', 'heb', 'מַעֲמָק', '["maʻămâq"]', '["from/ [the] depths"]', '["n-m"]', 'a deep deep, depth.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5547}/[H5545]', 'inflected', 'heb', 'סְלִיחָה', '["çᵉlîychâh"]', '["<the>/ forgiveness"]', '["n-f"]', 'pardon forgiveness, pardon.', 'from 5545;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1697G}/H9023/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["and/ for/ word/ his"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6381}/[H6381]', 'inflected', 'heb', 'פָּלָא', '["pâlâʼ"]', '["and/ in/ [things too] difficult"]', '["v"]', 'properly, perhaps to separate, i.e. distinguish (literally or figuratively); by implication, to be (causatively, make) great, difficult, wonderful accomplish, (arise...too, be too) hard, hidden, things too high, (be, do, do a, shew) marvelous(-ly, -els, things, work), miracles, perform, separate, make singular, (be, great, make) wonderful(-ers, -ly, things, works), wondrous (things, works, -ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1580}/[H1580]', 'inflected', 'heb', 'גָּמַל', '["gâmal"]', '["[is] like the/ weaned [child]","like/ a weaned [child]"]', '["v"]', 'to treat a person (well or ill), i.e. benefit or requite; by implication (of toil), to ripen, i.e. (specifically) to wean bestow on, deal bountifully, do (good), recompense, requite, reward, ripen, serve, mean, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0046}/[H82]', 'inflected', 'heb', 'אָבִיר', '["ʼâbîyr"]', '["for/ [the] mighty one of","to/ [the] mighty one of"]', '["a-m"]', 'mighty (spoken of God) mighty (one).', 'from 82;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0168H}/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["in/ [the] tent of"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8153}/[H3462]', 'lemma', 'heb', 'שְׁנָת', '["shᵉnâth"]', '["sleep"]', '["n-f"]', 'sleep sleep.', 'from 3462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6079}/H9020/[H5774]', 'inflected', 'heb', 'עַפְעַף', '["ʻaphʻaph"]', '["to/ eyelids/ my"]', '["n-m"]', 'an eyelash (as fluttering); figuratively, morning ray dawning, eye-lid.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8572}/[H5123]', 'lemma', 'heb', 'תְּנוּמָה', '["tᵉnûwmâh"]', '["slumber","slumber<s>"]', '["n-f"]', 'drowsiness, i.e. sleep slumber(-ing).', 'from 5123;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3293G>', 'opaque', 'heb', 'יַעַר', '["yaʻar"]', '["Jaar"]', '["n-m"]', 'a copse of bushes; hence, a forest; hence, honey in the comb (as hived in trees) (honey-) comb, forest, wood.', 'from an unused root probably meaning to thicken with verdure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4496H}/H9021/[H4495]', 'inflected', 'heb', 'מְנוּחָה', '["mᵉnûwchâh"]', '["to/ resting place/ your"]', '["n-f"]', 'repose or (adverbially) peacefully; figuratively, consolation (specifically, matrimony); hence (concretely) an abode comfortable, ease, quiet, rest(-ing place), still.', 'or מְנֻחָה; feminine of 4495;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0990J>/H9021', 'opaque', 'heb', 'בֶּטֶן', '["beṭen"]', '["belly/ your"]', '["n-f"]', 'the belly, especially the womb; also the bosom or body of anything belly, body, as they be born, within, womb.', 'from an unused root probably meaning to be hollow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5713B}/H9020/[H5707]', 'inflected', 'heb', 'עֵדָה', '["ʻêdâh"]', '["and/ testimonies/ my"]', '["n-f"]', 'testimony testimony, witness. Compare 5712.', 'feminine of 5707 in its techn. sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2097}/[H2088]', 'lemma', 'heb', 'זוֹ', '["zôw"]', '["this","which"]', '["d"]', 'this or that that, this.', 'for 2088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0183}/H9034/[H183]', 'inflected', 'heb', 'אָוָה', '["ʼâvâh"]', '["I have desired/ it","he has desired/ it"]', '["v"]', 'to wish for covet, (greatly) desire, be desirous, long, lust (after).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4186}/[H3427]', 'inflected', 'heb', 'מוֹשָׁב', '["môwshâb"]', '["for/ dwelling place","to/ a dwelling place"]', '["n-m"]', 'a seat; figuratively, a site; abstractly, a session; by extension an abode (the place or the time); by implication, population assembly, dwell in, dwelling(-place), wherein (that) dwelt (in), inhabited place, seat, sitting, situation, sojourning.', 'or מֹשָׁב; from 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6718B}/H9024/[H6679]', 'inflected', 'heb', 'צַיִד', '["tsayid"]', '["provision[s]/ its"]', '["n-m"]', 'the chase; also game (thus taken) × catcheth, food, × hunter, (that which he took in) hunting, venison, victuals.', 'from a form of 6679 and meaning the same;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0034}/H9024/[H14]', 'inflected', 'heb', 'אֶבְיוֹן', '["ʼebyôwn"]', '["needy [people]/ its"]', '["a-m"]', 'destitute beggar, needy, poor (man).', 'from 14, in the sense of want (especially in feeling);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3548}/H9024/[H3547]', 'inflected', 'heb', 'כֹּהֵן', '["kôhên"]', '["and/ priests/ its"]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2623}/H9024/[H2616]', 'inflected', 'heb', 'חָסִיד', '["châçîyd"]', '["and/ faithful [people]/ its"]', '["a"]', 'properly, kind, i.e. (religiously) pious (a saint) godly (man), good, holy (one), merciful, saint, (un-) godly.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4899}/H9020/[H4886]', 'inflected', 'heb', 'מָשִׁיחַ', '["mâshîyach"]', '["for/ anointed/ my"]', '["n-m"]', 'anointed; usually a consecrated person (as a king, priest, or saint); specifically, the Messiah anointed, Messiah.', 'from 4886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8081}/[H8080]', 'inflected', 'heb', 'שֶׁמֶן', '["shemen"]', '["like <the>/ oil","like the/ oil"]', '["n-m"]', 'grease, especially liquid (as from the olive, often perfumed); figuratively, richness anointing, × fat (things), × fruitful, oil(-ed), ointment, olive, pine.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2206}/[H2204]', 'lemma', 'heb', 'זָקָן', '["zâqân"]', '["[the] beard of","beard"]', '["n-m"]', 'the beard (as indicating age) beard.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H3381}/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["that/ [is] running down"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4060A}/H9023/[H4055]', 'inflected', 'heb', 'מִדָּה', '["middâh"]', '["robes/ his"]', '["n-f"]', 'properly, extension, i.e. height or breadth; also a measure (including its standard); hence a portion (as measured) or a vestment; specifically, tribute (as measured) garment, measure(-ing, meteyard, piece, size, (great) stature, tribute, wide.', 'feminine of 4055;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H5975G}/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["who/ [are] standing"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8034}/H9023/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["to/ name/ his"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H5459>/H9023', 'inflected', 'heb', 'לסגלתו', '["li/s.gu.la.T/o"]', '["to/ possession/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5387B}/[H5375]', 'lemma', 'heb', 'נָשִׂיא', '["nâsîyʼ"]', '["clouds"]', '["n-m"]', 'properly, an exalted one, i.e. a king or sheik; also a rising mist captain, chief, cloud, governor, prince, ruler, vapour.', 'or נָשִׂא; from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0214}/H9023/[H686]', 'inflected', 'heb', 'אוֹצָר', '["ʼôwtsâr"]', '["from/ storehouses/ his"]', '["n-m"]', 'a depository armory, cellar, garner, store(-house), treasure(-house) (-y).', 'from 686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H5221}/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["who/ <he> struck down"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6091}/[H6087]', 'lemma', 'heb', 'עָצָב', '["ʻâtsâb"]', '["[the] idols of","idols"]', '["n-m"]', 'an (idolatrous) image idol, image.', 'from 6087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7554}/[H7554]', 'inflected', 'heb', 'רָקַע', '["râqaʻ"]', '["to/ [one who] spread out"]', '["v"]', 'to pound the earth (as a sign of passion); by analogy to expand (by hammering); by implication, to overlay (with thin sheets of metal) beat, make broad, spread abroad (forth, over, out, into plates), stamp, stretch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1060}/H9028/[H1069]', 'inflected', 'heb', 'בְּכוֹר', '["bᵉkôwr"]', '["<in>/ firstborn<s>/ their"]', '["n-m"]', 'first-born; hence, chief eldest (son), firstborn(-ling).', 'from 1069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1504}/[H1504]', 'inflected', 'heb', 'גָּזַר', '["gâzar"]', '["to/ [one who] cut"]', '["v"]', 'to cut down or off; (figuratively) to destroy, divide, exclude, or decide cut down (off), decree, divide, snatch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1506}/[H1504]', 'inflected', 'heb', 'גֶּזֶר', '["gezer"]', '["into/ pieces"]', '["n-m"]', 'something cut off; a portion part, piece.', 'from 1504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1980J}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["to/ [one who] led"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/H9003/{H8216}/H9025/[H8213]', 'inflected', 'heb', 'שֶׁפֶל', '["shephel"]', '["who/ in/ low condition/ our"]', '["n-m"]', 'an humble rank low estate (place).', 'from 8213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6561}/H9035/[H6561]', 'inflected', 'heb', 'פָּרַק', '["pâraq"]', '["and/ he rescued/ us"]', '["v"]', 'to break off or crunch; figuratively, to deliver break (off), deliver, redeem, rend (in pieces), tear in pieces.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2142}/H9045/[H2145]', 'inflected', 'heb', 'זָכַר', '["zâkar"]', '["when/ remembered/ we"]', '["v"]', 'properly, to mark (so as to be recognized), i.e. to remember; by implication, to mention; to be male × burn (incense), × earnestly, be male, (make) mention (of), be mindful, recount, record(-er), remember, make to be remembered, bring (call, come, keep, put) to (in) remembrance, × still, think on, × well.', 'a primitive root; also as denominative from 2145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3658>/H9025', 'opaque', 'heb', 'כִּנּוֹר', '["kinnôwr"]', '["harps/ our"]', '["n-m"]', 'a harp harp.', 'from a unused root meaning to twang;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7592}/H9035/[H7592]', 'inflected', 'heb', 'שָׁאַל', '["shâʼal"]', '["they asked/ us"]', '["v"]', 'to inquire; by implication, to request; by extension, to demand ask (counsel, on), beg, borrow, lay to charge, consult, demand, desire, × earnestly, enquire, greet, obtain leave, lend, pray, request, require, salute, × straitly, × surely, wish.', 'or שָׁאֵל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7617}/H9035/[H7617]', 'inflected', 'heb', 'שָׁבָה', '["shâbâh"]', '["captors/ our"]', '["v"]', 'to transport into captivity (bring away, carry, carry away, lead, lead away, take) captive(-s), drive (take) away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8437}/H9025/[H3213]', 'inflected', 'heb', 'תּוֹלָל', '["tôwlâl"]', '["and/ mockers/ our"]', '["n-m"]', 'causing to howl, i.e. an oppressor that wasted.', 'from 3213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7892A}/[H7891]', 'inflected', 'heb', 'שִׁיר', '["shîyr"]', '["one of/ [the] song[s] of"]', '["n-m n-f"]', 'a song; abstractly, singing musical(-ick), × sing(-er, -ing), song.', 'or feminine שִׁירָה; from 7891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7911}/H9032/[H7911]', 'inflected', 'heb', 'שָׁכַח', '["shâkach"]', '["I will forget/ you","they have forgotten/ you"]', '["v"]', 'to mislay, i.e. to be oblivious of, from want of memory or attention × at all, (cause to) forget.', 'or שָׁכֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2142}/H9032/[H2145]', 'inflected', 'heb', 'זָכַר', '["zâkar"]', '["I will remember/ you"]', '["v"]', 'properly, to mark (so as to be recognized), i.e. to remember; by implication, to mention; to be male × burn (incense), × earnestly, be male, (make) mention (of), be mindful, recount, record(-er), remember, make to be remembered, bring (call, come, keep, put) to (in) remembrance, × still, think on, × well.', 'a primitive root; also as denominative from 2145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8057}/H9020/[H8056]', 'inflected', 'heb', 'שִׂמְחָה', '["simchâh"]', '["joy/ my"]', '["n-f"]', 'blithesomeness or glee, (religious or festival) × exceeding(-ly), gladness, joy(-fulness), mirth, pleasure, rejoice(-ing).', 'from 8056;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3247H}/[H3245]', 'inflected', 'heb', 'יְסוֹד', '["yᵉçôwd"]', '["the/ foundation"]', '["n-f"]', 'a foundation (literally or figuratively) bottom, foundation, repairing', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7703}/[H7703]', 'inflected', 'heb', 'שָׁדַד', '["shâdad"]', '["that/ is about to be destroyed","the/ destroyer","the/ destroyers"]', '["v"]', 'properly, to be burly, i.e. (figuratively) powerful (passively, impregnable); by implication, to ravage dead, destroy(-er), oppress, robber, spoil(-er), × utterly, (lay) waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H7999A}/[H7999]', 'inflected', 'heb', 'שָׁלַם', '["shâlam"]', '["[is one] who/ he will repay"]', '["v"]', 'to be safe (in mind, body or estate); figuratively, to be (causatively, make) completed; by implication, to be friendly; by extension, to reciprocate (in various applications) make amends, (make an) end, finish, full, give again, make good, (re-) pay (again), (make) (to) (be at) peace(-able), that is perfect, perform, (make) prosper(-ous), recompense, render, requite, make restitution, restore, reward, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1576}/H9022/[H1580]', 'inflected', 'heb', 'גְּמוּל', '["gᵉmûwl"]', '["dealing/ your"]', '["n-m"]', 'treatment, i.e. an act (of good or ill); by implication, service or requital as hast served, benefit, desert, deserving, that which he hath given, recompense, reward.', 'from 1580;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H1580}/[H1580]', 'inflected', 'heb', 'גָּמַל', '["gâmal"]', '["that/ you dealt"]', '["v"]', 'to treat a person (well or ill), i.e. benefit or requite; by implication (of toil), to ripen, i.e. (specifically) to wean bestow on, deal bountifully, do (good), recompense, requite, reward, ripen, serve, mean, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H0270}/[H270]', 'inflected', 'heb', 'אָחַז', '["ʼâchaz"]', '["[is one] who/ he will seize","that/ [are] caught"]', '["v"]', 'to seize (often with the accessory idea of holding in possession) be affrighted, bar, (catch, lay, take) hold (back), come upon, fasten, handle, portion, (get, have or take) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5310A}/[H5310]', 'inflected', 'heb', 'נָפַץ', '["nâphats"]', '["and/ I smash","and/ he will smash"]', '["v"]', 'to dash to pieces, or scatter be beaten in sunder, break (in pieces), broken, dash (in pieces), cause to be discharged, dispersed, be overspread, scatter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5768}/H9022/[H5763]', 'inflected', 'heb', 'עוֹלֵל', '["ʻôwlêl"]', '["children/ your"]', '["n-m"]', 'a suckling babe, (young) child, infant, little one.', 'or עֹלָל; from 5763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7292}/H9030/[H7292]', 'inflected', 'heb', 'רָהַב', '["râhab"]', '["they have confused/ me","you made bold/ me"]', '["v"]', 'to urge severely, i.e. (figuratively) importune, embolden, capture, act insolently overcome, behave self proudly, make sure, strengthen.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1364}/[H1361]', 'inflected', 'heb', 'גָּבֹהַּ', '["gâbôahh"]', '["and/ [the] proud","and/ high [ones]","and/ tall of"]', '["a"]', 'elevated (or elated), powerful, arrogant haughty, height, high(-er), lofty, proud, × exceeding proudly.', 'or גָּבוֹהַּ; (fully) from 1361;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4801}/[H7368]', 'inflected', 'heb', 'מֶרְחָק', '["merchâq"]', '["[which] from/ a distance","from/ a distance"]', '["n-m"]', 'remoteness, i.e. (concretely) a distant place; often (adverbially) from afar (a-, dwell in, very) far (country, off). See also 1023.', '; from 7368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2713}/H9030/[H2713]', 'inflected', 'heb', 'חָקַר', '["châqar"]', '["examine/ me","you have examined/ me"]', '["v"]', 'properly, to penetrate; hence, to examine intimately find out, (make) search (out), seek (out), sound, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6965B}/H9040/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["and/ standing/ my"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7454}/H9020/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["<to>/ thought[s]/ my"]', '["n-m"]', 'a thought (as association of ideas) thought.', 'from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0732}/H9040/[H732]', 'inflected', 'heb', 'אָרַח', '["ʼârach"]', '["traveling/ I"]', '["v"]', 'to travel go, wayfaring (man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7252}/H9040/[H7250]', 'inflected', 'heb', 'רֶבַע', '["rebaʻ"]', '["and/ lying down/ my"]', '["v"]', 'prostration (for sleep) lying down.', 'from 7250;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6924H}/[H6923]', 'inflected', 'heb', 'קֶדֶם', '["qedem"]', '["and/ front"]', '["n-m adv"]', 'the front, of place (absolutely, the fore part, relatively the East) or time (antiquity); often used adverbially (before, anciently, eastward) aforetime, ancient (time), before, east (end, part, side, -ward), eternal, × ever(-lasting), forward, old, past. Compare 6926.', 'or קֵדְמָה; from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6696A}/H9030/[H6696]', 'inflected', 'heb', 'צוּר', '["tsûwr"]', '["you enclose/ me"]', '["v"]', 'to cramp, i.e. confine (in many applications, literally and figuratively, formative or hostile) adversary, assault, beset, besiege, bind (up), cast, distress, fashion, fortify, inclose, lay siege, put up in bags.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6383}/[H6381]', 'lemma', 'heb', 'פִּלְאִי', '["pilʼîy"]', '["[is too] wonderful"]', '["a"]', 'remarkable secret, wonderful.', 'or פָּלִיא; from 6381;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7307G}/H9021/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["from/ spirit/ your"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5266}/[H5266]', 'lemma', 'heb', 'נָסַק', '["nâçaq"]', '["I will ascend"]', '["v"]', 'to go up ascend.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3331}/[H3331]', 'inflected', 'heb', 'יַצַע', '["yatsaʻ"]', '["and/ I will spread as a bed"]', '["v"]', 'to strew as a surface make (one''s) bed, × lie, spread.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0270}/H9030/[H270]', 'inflected', 'heb', 'אָחַז', '["ʼâchaz"]', '["and/ it will grasp/ me"]', '["v"]', 'to seize (often with the accessory idea of holding in possession) be affrighted, bar, (catch, lay, take) hold (back), come upon, fasten, handle, portion, (get, have or take) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2825}/[H2821]', 'inflected', 'heb', 'חֲשֵׁכָה', '["chăshêkâh"]', '["as <the>/ darkness"]', '["n-f"]', 'darkness; figuratively, misery darkness.', 'or חֲשֵׁיכָהxlit chăshêkâh corrected to chăshêykâh; from 2821;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0219A}/[H216]', 'inflected', 'heb', 'אוֹרָה', '["ʼôwrâh"]', '["as the/ light"]', '["n-f"]', 'luminousness, i.e. (figuratively) prosperity; also a plant (as being bright) herb, light.', 'feminine of 216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5526C}/H9030/[H5526]', 'inflected', 'heb', 'סָכַךְ', '["çâkak"]', '["you wove together/ me"]', '["v"]', 'properly, to entwine as a screen; by implication, to fence in, cover over, (figuratively) protect cover, defence, defend, hedge in, join together, set, shut up.', 'or שָׂכַךְ; (Exodus 33:22), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6108}/H9020/[H6105]', 'inflected', 'heb', 'עֹצֶם', '["ʻôtsem"]', '["bone[s]/ my"]', '["n-m"]', 'power; hence, body might, strong, substance.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1564}/H9020/[H1563]', 'inflected', 'heb', 'גֹּלֶם', '["gôlem"]', '["shapeless form/ my"]', '["n-m"]', 'a wrapped (and unformed mass, i.e. as the embryo) substance yet being unperfect.', 'from 1563;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5612H}/H9021/[H9]', 'inflected', 'heb', 'סֵפֶר', '["çêpher"]', '["scroll/ your"]', '["n-m"]', 'properly, writing (the art or a document); by implication, a book bill, book, evidence, × learn(-ed) (-ing), letter, register, scroll.', 'or (feminine) סִפְרָה; (Psalm 56:8 (9)), from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7454}/H9021/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["thoughts/ your"]', '["n-m"]', 'a thought (as association of ideas) thought.', 'from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218K>/H9028', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["sum<s>/ their"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5750}/H9040/[H5749]', 'inflected', 'heb', 'עוֹד', '["ʻôwd"]', '["and/ still/ I"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4209}/[H2161]', 'inflected', 'heb', 'מְזִמָּה', '["mᵉzimmâh"]', '["to/ wickedness"]', '["n-f"]', 'a plan, usually evil (machination), sometimes good (sagacity) (wicked) device, discretion, intent, witty invention, lewdness, mischievous (device), thought, wickedly.', 'from 2161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8618}/H9031/[H6965]', 'inflected', 'heb', 'תְּקוֹמֵם', '["tᵉqôwmêm"]', '["and/ <in>/ rebels/ your"]', '["v"]', 'an opponent rise up against.', 'from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6090A}/[H6089]', 'lemma', 'heb', 'עֹצֶב', '["ʻôtseb"]', '["an idol"]', '["n-m"]', 'an idol (as fashioned); also pain (bodily or mental) idol, sorrow, × wicked.', 'a variation of 6089;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5919>', 'opaque', 'heb', 'עַכְשׁוּב', '["ʻakshûwb"]', '["a viper"]', '["n-m"]', 'an asp (from lurking coiled up) adder.', 'probably from an unused root meaning to coil;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1760A}/[H1760]', 'inflected', 'heb', 'דָּחָה', '["dâchâh"]', '["to/ trip up"]', '["v"]', 'to push down chase, drive away (on), overthrow, outcast, × sore, thrust, totter.', 'or דָּחַח; (Jeremiah 23:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4570}/[H5696]', 'lemma', 'heb', 'מַעְגָּל', '["maʻgâl"]', '["[the] track of","a track","course of"]', '["n-m"]', 'a track (literally or figuratively); also a rampart (as circular) going, path, trench, way(-side).', 'or feminine מַעְגָּלָה; from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3970}/[H183]', 'lemma', 'heb', 'מַאֲוַי', '["maʼăvay"]', '["[the] desires of"]', '["n-m"]', 'a desire desire.', 'from 183;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2162}/H9023/[H2161]', 'inflected', 'heb', 'זָמָם', '["zâmâm"]', '["plot/ his"]', '["n-m"]', 'a plot wicked device.', 'from 2161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6329}/[H6328]', 'lemma', 'heb', 'פּוּק', '["pûwq"]', '["[who] he obtains","he obtains","providing","you promote"]', '["v"]', 'to issue, i.e. furnish; causatively, to secure; figuratively, to succeed afford, draw out, further, get, obtain.', 'a primitive root [rather identical with 6328 through the idea of dropping out; compare 5312];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4524}/H9020/[H5437]', 'inflected', 'heb', 'מֵסַב', '["mêçab"]', '["surroundings/ my"]', '["n-m"]', 'a divan (as enclosing the room); abstractly (adverbial) around that compass about, (place) round about, at table.', 'plural masculine מְסִבִּים; or feminine מְסִבּוֹת; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H4113>', 'inflected', 'heb', 'במהמרות', '["be./ma.ha.mo.Rot"]', '["in/ pits"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6679A}/H9033/[H6718]', 'inflected', 'heb', 'צוּד', '["tsûwd"]', '["let it hunt/ him"]', '["v"]', 'to lie alongside (i.e. in wait); by implication, to catch an animal (figuratively, men); to victual (for a journey) chase, hunt, sore, take (provision).', 'a primitive root; also denominative from 6718');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4073}/[H1765]', 'inflected', 'heb', 'מְדַחְפָה', '["mᵉdachphâh"]', '["for/ blows"]', '["n-f"]', 'a push, i.e. ruin overthrow.', 'from 1765;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7896G}/H9012/[H7896]', 'inflected', 'heb', 'שִׁית', '["shîyth"]', '["set/ !"]', '["v"]', 'to place (in a very wide application) apply, appoint, array, bring, consider, lay (up), let alone, × look, make, mark, put (on), regard, set, shew, be stayed, × take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8108}/[H8104]', 'lemma', 'heb', 'שׇׁמְרָה', '["shomrâh"]', '["a guard"]', '["n-f"]', 'watchfulness watch.', 'feminine of an unused noun from 8104 meaning a guard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5341}/H9012/[H5341]', 'inflected', 'heb', 'נָצַר', '["nâtsar"]', '["keep watch/ !"]', '["v"]', 'to guard, in a good sense (to protect, maintain, obey, etc.) or a bad one (to conceal, etc.) besieged, hidden thing, keep(-er, -ing), monument, observe, preserve(-r), subtil, watcher(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1817A}/[H1802]', 'lemma', 'heb', 'דֶּלֶת', '["deleth"]', '["[the] door of"]', '["n-m n-f"]', 'something swinging, i.e. the valve of a door door (two-leaved), gate, leaf, lid. (Psalm 141:3).', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5953A}/[H5953]', 'inflected', 'heb', 'עָלַל', '["ʻâlal"]', '["to/ practice"]', '["v"]', 'to effect thoroughly; specifically, to glean (also figuratively); by implication (in a bad sense) to overdo, i.e. maltreat, be saucy to, pain, impose (also literal) abuse, affect, × child, defile, do, glean, mock, practise, thoroughly, work (wonderfully).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7562}/[H7561]', 'inflected', 'heb', 'רֶשַׁע', '["reshaʻ"]', '["by/ wickedness","in/ wickedness"]', '["n-m"]', 'a wrong (especially moral) iniquity, wicked(-ness).', 'from 7561;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3898B}/[H3898]', 'lemma', 'heb', 'לָחַם', '["lâcham"]', '["I will eat","eat","they eat","you eat"]', '["v"]', 'to feed on; figuratively, to consume; by implication, to battle (as destruction) devour, eat, × ever, fight(-ing), overcome, prevail, (make) war(-ring).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4516}/H9028/[H5276]', 'inflected', 'heb', 'מַנְעַם', '["manʻam"]', '["in/ delicacies/ their"]', '["n-m"]', 'a delicacy dainty.', 'from 5276;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1986}/H9030/[H1986]', 'inflected', 'heb', 'הָלַם', '["hâlam"]', '["let him strike/ me","they beat/ me"]', '["v"]', 'to strike down; by implication, to hammer, stamp, conquer, disband beat (down), break (down), overcome, smite (with the hammer).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3198}/H9030/[H3198]', 'inflected', 'heb', 'יָכַח', '["yâkach"]', '["and/ let him rebuke/ me"]', '["v"]', 'to be right (i.e. correct); reciprocal, to argue; causatively, to decide, justify or convict appoint, argue, chasten, convince, correct(-ion), daysman, dispute, judge, maintain, plead, reason (together), rebuke, reprove(-r), surely, in any wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7451I}/H9028/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["[is] on/ evil deeds/ their","by/ evil/ their"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027P}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["at/ [the] hands of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6106G}/H9025/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["bones/ our"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4170}/[H3369]', 'inflected', 'heb', 'מוֹקֵשׁ', '["môwqêsh"]', '["and/ [is] a snare","and/ [the] snares of"]', '["n-m"]', 'a noose (for catching animals) (literally or figuratively); by implication, a hook (for the nose) be ensnared, gin, (is) snare(-d), trap.', 'or מֹקֵשׁ; from 3369;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4364B}/H9023/[H3648]', 'inflected', 'heb', 'מַכְמָר', '["makmâr"]', '["in/ own nets/ his"]', '["n-m"]', 'a (hunter''s) net (as dark from concealment) net.', 'or מִכְמֹר; from 3648 in the sense of blackening by heat;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4498}/[H5127]', 'lemma', 'heb', 'מָנוֹס', '["mânôwç"]', '["a place of escape"]', '["n-m"]', 'a retreat (literally or figuratively); abstractly, a fleeing × apace, escape, way to flee, flight, refuge.', 'from 5127;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7291}/H9030/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["from/ [those who] harass/ me"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3318H}/H9012/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["bring out/ !"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4525}/[H5462]', 'inflected', 'heb', 'מַסְגֵּר', '["maçgêr"]', '["from/ prison"]', '["n-m"]', 'a fastener, i.e. (of a person) a smith, (of a thing) a prison prison, smith.', 'from 5462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2416C}/H9020/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["life/ my"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5848C}/[H5848]', 'inflected', 'heb', 'עָטַף', '["ʻâṭaph"]', '["and/ it has fainted away"]', '["v"]', 'to shroud, i.e. clothe (whether transitive or reflex.); hence (from the idea of darkness) to languish cover (over), fail, faint, feebler, hide self, be overwhelmed, swoon.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H8432>/H9030', 'inflected', 'heb', 'בתוכי', '["be./to.Kh/i"]', '["in/ [the] midst of/ me"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6869B}/[H6862]', 'inflected', 'heb', 'צָרָה', '["tsârâh"]', '["from/ distress","from/ trouble","from/ troubles"]', '["n-f"]', 'tightness (i.e. figuratively, trouble); transitively, a female rival adversary, adversity, affliction, anguish, distress, tribulation, trouble.', 'feminine of 6862;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2617A}/H9021/[H2616]', 'inflected', 'heb', 'חֶסֶד', '["cheçed"]', '["and/ in/ covenant loyalty/ your"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7128}/[H7126]', 'inflected', 'heb', 'קְרָב', '["qᵉrâb"]', '["for <the>/ war"]', '["n-m"]', 'hostile encounter battle, war.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0676}/H9020/[H6648]', 'inflected', 'heb', 'אֶצְבַּע', '["ʼetsbaʻ"]', '["fingers/ my"]', '["n-f"]', 'something to sieze with, i.e. a finger; by analogy, a toe finger, toe.', 'from the same as 6648 (in the sense of grasping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7286}/[H7286]', 'inflected', 'heb', 'רָדַד', '["râdad"]', '["the/ [one who] subdues"]', '["v"]', 'to tread in pieces, i.e. (figuratively) to conquer, or (specifically) to overlay spend, spread, subdue.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3045}/H9033/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["and/ you have considered/ him"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2803J}/H9033/[H2803]', 'inflected', 'heb', 'חָשַׁב', '["châshab"]', '["and/ you have regarded/ him"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1892}/[H1891]', 'inflected', 'heb', 'הֶבֶל', '["hebel"]', '["to <the>/ breath"]', '["n-m"]', 'emptiness or vanity; figuratively, something transitory and unsatisfactory; often used as an adverb × altogether, vain, vanity.', 'or (rarely in the abs.) הֲבֵל; from 1891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1299}/[H1299]', 'lemma', 'heb', 'בָּרַק', '["bâraq"]', '["flash"]', '["v"]', 'to lighten (lightning) cast forth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2000}/H9038/[H1949]', 'inflected', 'heb', 'הָמַם', '["hâmam"]', '["and/ you will rout/ them"]', '["v"]', 'properly, to put in commotion; by implication, to disturb, drive, destroy break, consume, crush, destroy, discomfit, trouble, vex.', 'a primitive root (compare 1949, 1993);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6475}/H9030/[H6475]', 'inflected', 'heb', 'פָּצָה', '["pâtsâh"]', '["set free/ me"]', '["v"]', 'to rend, i.e. open (especially the mouth) deliver, gape, open, rid, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6475}/[H6475]', 'inflected', 'heb', 'פָּצָה', '["pâtsâh"]', '["who/ sets free"]', '["v"]', 'to rend, i.e. open (especially the mouth) deliver, gape, open, rid, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5195}/[H5193]', 'inflected', 'heb', 'נָטִיעַ', '["nâṭîyaʻ"]', '["[will be] like/ plants"]', '["n-m"]', 'a plant plant.', 'from 5193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5271A}/H9028/[H5288]', 'inflected', 'heb', 'נָעוּר', '["nâʻûwr"]', '["in/ youth<s>/ their"]', '["n-m n-f"]', '(only in plural collective or emphatic form) youth, the state (juvenility) or the persons (young people) childhood, youth.', 'or נָעֻר; and (feminine) נְעֻרָה; properly, passive participle from 5288 as denominative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2106}/[H2099]', 'inflected', 'heb', 'זָוִית', '["zâvîyth"]', '["[will be] like/ corners","like/ [the] corners of"]', '["n-f"]', 'an angle (as projecting), i.e. (by implication) a corner-column (or anta) corner(stone).', 'apparently from the same root as 2099 (in the sense of prominence);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4200>/H9025', 'opaque', 'heb', 'מֶזֶו', '["mezev"]', '["granaries/ our"]', '["n-m"]', 'a granary garner.', 'probably from an unused root meaning to gather in;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2177}/[H2109]', 'inflected', 'heb', 'זַן', '["zan"]', '["from/ kind"]', '["n-m"]', 'properly, nourished (or fully developed), i.e. a form or sort divers kinds, × all manner of store.', 'from 2109;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2177}/[H2109]', 'lemma', 'heb', 'זַן', '["zan"]', '["kind"]', '["n-m"]', 'properly, nourished (or fully developed), i.e. a form or sort divers kinds, × all manner of store.', 'from 2109;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6629G>/H9025', 'opaque', 'heb', 'צֹאן', '["tsôʼn"]', '["flocks/ our"]', '["n-f"]', 'a collective name for a flock (of sheep or goats); also figuratively (of men) (small) cattle, flock ( -s), lamb ( -s), sheep(-cote, -fold, -shearer, -herds).', 'or צאוֹן; (Psalm 144:13), from an unused root meaning to migrate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0503}/[H505]', 'lemma', 'heb', 'אָלַף', '["ʼâlaph"]', '["[will be] producing thousands"]', '["v"]', 'causative, to make a thousandfold bring forth thousands.', 'denominative from 505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2351>/H9025', 'inflected', 'heb', 'בחוצותינו', '["be./chu.tzo.Tei./nu"]', '["in/ open places/ our"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0441A}/H9025/[H502]', 'inflected', 'heb', 'אַלּוּף', '["ʼallûwph"]', '["cattle[s]/ our"]', '["a-m"]', 'familiar; a friend, also gentle; hence, a bullock (as being tame; applied, although masculine, to a cow); and so, a chieftain (as notable, like neat cattle) captain, duke, (chief) friend, governor, guide, ox.', 'or (shortened) אַלֻּף; from 502;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5445}/[H5445]', 'lemma', 'heb', 'סָבַל', '["çâbal"]', '["I will carry","[will be] loaded","he will bear","we have borne"]', '["v"]', 'to carry (literally or figuratively), or (reflexively) be burdensome; specifically, to be gravid bear, be a burden, carry, strong to labour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6682}/[H6681]', 'lemma', 'heb', 'צְוָחָה', '["tsᵉvâchâh"]', '["[will be] an outcry","an outcry"]', '["n-f"]', 'a screech (of anguish) cry(-ing).', 'from 6681;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7339}/H9025/[H7337]', 'inflected', 'heb', 'רְחֹב', '["rᵉchôb"]', '["in/ open places/ our"]', '["n-f"]', 'a width, i.e. (concretely) avenue or area broad place (way), street. See also 1050.', 'or רְחוֹב; from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H3602}/[H3541]', 'inflected', 'heb', 'כָּכָה', '["kâkâh"]', '["that/ thus"]', '["adv"]', 'just so, referring to the previous or following context after that (this) manner, this matter, (even) so, in such a case, thus.', 'from 3541;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H3068G}/[H1961]', 'inflected', 'heb', 'יְהֹוָה', '["Yᵉhôvâh"]', '["that/ Yahweh"]', '["n-pr"]', '(the) self-Existent or Eternal; Jeho-vah, Jewish national name of God Jehovah, the Lord. Compare 3050, 3069.', 'from 1961;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1420}/H9023/[H1419]', 'inflected', 'heb', 'גְּדוּלָה', '["gᵉdûwlâh"]', '["and/ to/ greatness/ his"]', '["n-f"]', 'greatness; (concretely) mighty acts dignity, great things(-ness), majesty.', 'or גְּדֻלָּה; (shortened) or (less accurately) גְּדוּלָּה; feminine of 1419;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7623B}/[H7623]', 'lemma', 'heb', 'שָׁבַח', '["shâbach"]', '["extol","it will extol"]', '["v"]', 'properly, to address in a loud tone, i.e. (specifically) loud; figuratively, to pacify (as if by words) commend, glory, keep in, praise, still, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1369}/H9021/[H1368]', 'inflected', 'heb', 'גְּבוּרָה', '["gᵉbûwrâh"]', '["and/ might/ your","and/ mighty deeds/ your"]', '["n-f"]', 'force (literally or figuratively); by implication, valor, victory force, mastery, might, mighty (act, power), power, strength.', 'feminine passive participle from the same as 1368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5807}/[H5810]', 'inflected', 'heb', 'עֱזוּז', '["ʻĕzûwz"]', '["and/ [the] fierceness of","and/ [the] might of"]', '["n-m"]', 'forcibleness might, strength.', 'from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1420}/H9021/[H1419]', 'inflected', 'heb', 'גְּדוּלָה', '["gᵉdûwlâh"]', '["and/ greatness/ your"]', '["n-f"]', 'greatness; (concretely) mighty acts dignity, great things(-ness), majesty.', 'or גְּדֻלָּה; (shortened) or (less accurately) גְּדוּלָּה; feminine of 1419;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5608A}/H9034/[H5608]', 'inflected', 'heb', 'סָפַר', '["çâphar"]', '["I will recount/ it"]', '["v n-m"]', 'properly, to score with a mark as a tally or record, i.e. (by implication) to inscribe, and also to enumerate; intensively, to recount, i.e. celebrate commune, (ac-) count; declare, number, penknife, reckon, scribe, shew forth, speak, talk, tell (out), writer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7356B}/H9023/[H7355]', 'inflected', 'heb', 'רַחַם', '["racham"]', '["and/ compassion<s>/ his"]', '["n-f"]', 'compassion (in the plural); by extension, the womb (as cherishing the fetus); by implication, a maiden bowels, compassion, damsel, tender love, (great, tender) mercy, pity, womb.', 'from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4475}/H9021/[H4474]', 'inflected', 'heb', 'מֶמְשָׁלָה', '["memshâlâh"]', '["and/ authority/ your","and/ dominion/ your"]', '["n-f"]', 'rule; also (concretely in plural) a realm or a ruler dominion, government, power, to rule.', 'feminine of 4474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2623}/[H2616]', 'inflected', 'heb', 'חָסִיד', '["châçîyd"]', '["and/ faithful"]', '["a"]', 'properly, kind, i.e. (religiously) pious (a saint) godly (man), good, holy (one), merciful, saint, (un-) godly.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2210}/[H2210]', 'inflected', 'heb', 'זָקַף', '["zâqaph"]', '["and/ [is] raising up"]', '["v"]', 'to life, i.e. (figuratively) comfort raise (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3721}/[H3721]', 'inflected', 'heb', 'כָּפַף', '["kâphaph"]', '["those/ [who] are bent down"]', '["v"]', 'to curve bow down (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7121G}/H9033/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["I called/ him","I have summoned/ him","[those who] call out to/ him","anyone will call/ him","call on/ him","he calls/ him","they call on/ him","they call out to/ him"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0571H}/[H539]', 'inflected', 'heb', 'אֶמֶת', '["ʼemeth"]', '["in/ faithfulness","in/ truth"]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H0369}/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["whom/ not"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7307H}/H9023/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["breath/ his","wind/ his"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0127G}/H9023/[H119]', 'inflected', 'heb', 'אֲדָמָה', '["ʼădâmâh"]', '["to/ earth/ his"]', '["n-f"]', 'soil (from its general redness) country, earth, ground, husband(-man) (-ry), land.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6250}/H9023/[H6245]', 'inflected', 'heb', 'עֶשְׁתֹּנָה', '["ʻeshtônâh"]', '["plans/ his"]', '["n-f"]', 'thinking thought.', 'from 6245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H0410G}/[H352]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["[is one] whom/ [the] God of"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5828}/H9023/[H5826]', 'inflected', 'heb', 'עֵזֶר', '["ʻêzer"]', '["[is] <in>/ help/ his"]', '["n-m"]', 'aid help.', 'from 5826;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7664}/H9023/[H7663]', 'inflected', 'heb', 'שֵׂבֶר', '["sêber"]', '["hope/ his"]', '["n-m"]', 'expectation hope.', 'from 7663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6231}/[H6229]', 'inflected', 'heb', 'עָשַׁק', '["ʻâshaq"]', '["for the/ oppressed","to/ defraud"]', '["v"]', 'to press upon, i.e. oppress, defraud, violate, overflow get deceitfully, deceive, defraud, drink up, (use) oppress(-ion), -or), do violence (wrong).', 'a primitive root (compare 6229);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7457}/[H7456]', 'inflected', 'heb', 'רָעֵב', '["râʻêb"]', '["for the/ hungry [person]","to the/ hungry [people]","to the/ hungry [person]","to/ [the] hungry"]', '["a"]', 'hungry (more or less intensely) hunger bitten, hungry.', 'from 7456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2210}/[H2210]', 'lemma', 'heb', 'זָקַף', '["zâqaph"]', '["[is] raising up"]', '["v"]', 'to life, i.e. (figuratively) comfort raise (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5749A}/[H5749]', 'lemma', 'heb', 'עוּד', '["ʻûwd"]', '["[is] relieving","he helps up"]', '["v"]', 'to duplicate or repeat; by implication, to protest, testify (as by reiteration); intensively, to encompass, restore (as a sort of reduplication) admonish, charge, earnestly, lift up, protest, call (take) to record, relieve, rob, solemnly, stand upright, testify, give warning, (bear, call to, give, take to) witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1870G}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["and/ [are] a way of","and/ [the] way of","and/ a way"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430G}/H9022/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["God/ your"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6094}/H9028/[H6087]', 'inflected', 'heb', 'עַצֶּבֶת', '["ʻatstsebeth"]', '["<to>/ wounds/ their"]', '["n-f"]', 'a idol; also, a pain or wound sorrow, wound.', 'from 6087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3556}/[H3522]', 'inflected', 'heb', 'כּוֹכָב', '["kôwkâb"]', '["<to>/ [the] stars of","of the/ stars"]', '["n-m"]', 'a star (as round or as shining); figuratively, a prince star(-gazer).', 'probably from the same as 3522 (in the sense of rolling) or 3554 (in the sense of blazing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8394}/H9023/[H995]', 'inflected', 'heb', 'תָּבוּן', '["tâbûwn"]', '["to/ understanding/ his"]', '["n-m"]', 'intelligence; by implication, an argument; by extension, caprice discretion, reason, skilfulness, understanding, wisdom.', 'and (feminine) תְּבוּנָה; or תּוֹבֻנָה; from 995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3899G}/H9024/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["food/ her","food/ its"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7785}/[H7783]', 'inflected', 'heb', 'שׁוֹק', '["shôwq"]', '["in/ [the] legs of"]', '["n-f"]', 'the (lower) leg (as a runner) hip, leg, shoulder, thigh.', 'from 7783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8179G}/H9022/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["gates/ your"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7130G}/H9022/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["[is] in/ midst/ your","in/ inner being/ your","in/ midst/ your"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1366G}/H9022/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["border/ your","territories/ your","territory/ your"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7646}/H9032/[H7646]', 'inflected', 'heb', 'שָׂבַע', '["sâbaʻ"]', '["he satisfies/ you"]', '["v"]', 'to sate, i.e. fill to satisfaction (literally or figuratively) have enough, fill (full, self, with), be (to the) full (of), have plenty of, be satiate, satisfy (with), suffice, be weary of.', 'or שָׂבֵעַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0565A}/H9023/[H561]', 'inflected', 'heb', 'אִמְרָה', '["ʼimrâh"]', '["word/ his"]', '["n-f"]', 'commandment, speech, word.', 'or אֶמְרָה; feminine of 561, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H6785>', 'inflected', 'heb', 'כצמר', '["ka./Tza.mer","ka./Tze.mer"]', '["like <the>/ wool"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3713B}/[H3722]', 'lemma', 'heb', 'כְּפוֹר', '["kᵉphôwr"]', '["frost"]', '["n-m"]', 'properly, a cover, i.e. (by implication) a tankard (or covered goblet); also white frost (as covering the ground) bason, hoar(-y) frost.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H0665>', 'inflected', 'heb', 'כאפר', '["ka./''E.fer"]', '["like <the>/ ash[es]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7140}/H9023/[H7139]', 'inflected', 'heb', 'קֶרַח', '["qerach"]', '["ice/ his"]', '["n-m"]', 'ice (as if bald, i.e. smooth); hence, hail; by resemblance, rock crystal crystal, frost, ice.', 'or קֹרַח; from 7139;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6595A}/[H6626]', 'inflected', 'heb', 'פַּת', '["path"]', '["like/ crumbs"]', '["n-f"]', 'a bit meat, morsel, piece.', 'from 6626;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7135}/H9023/[H7119]', 'inflected', 'heb', 'קָרָה', '["qârâh"]', '["coldness/ his"]', '["n-f"]', 'coolness cold.', 'feminine of 7119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4529}/H9038/[H4529]', 'inflected', 'heb', 'מָסָה', '["mâçâh"]', '["and/ he melts/ them"]', '["v"]', 'to dissolve make to consume away, (make to) melt, water.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5380}/[H5380]', 'lemma', 'heb', 'נָשַׁב', '["nâshab"]', '["he makes blow","it blows"]', '["v"]', 'to blow; by implication, to disperse (cause to) blow, drive away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1254A}/[H1254]', 'inflected', 'heb', 'בָּרָא', '["bârâʼ"]', '["and/ [one who] created","and/ [who] creates","and/ they were created","and/ they will cut down"]', '["v"]', '(absolutely) to create; (qualified) to cut down (a wood), select, feed (as formative processes) choose, create (creator), cut down, dispatch, do, make (fat).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7008}/[H6999]', 'inflected', 'heb', 'קִיטוֹר', '["qîyṭôwr"]', '["and/ smoke"]', '["n-m"]', 'a fume, i.e. cloud smoke, vapour.', 'or קִיטֹר; from 6999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1935>/H9023', 'opaque', 'heb', 'הוֹד', '["hôwd"]', '["majesty/ his","splendor/ his","splendor/ its"]', '["n-m"]', 'grandeur (i.e. an imposing form and appearance) beauty, comeliness, excellency, glorious, glory, goodly, honour, majesty.', 'from an unused root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6213H}/H9033/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["in/ maker<s>/ its"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4234}/[H2342]', 'inflected', 'heb', 'מָחוֹל', '["mâchôwl"]', '["in/ [the] dancing of","with/ dancing"]', '["n-m"]', 'a (round) dance dance(-cing).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3444}/[H3467]', 'inflected', 'heb', 'יְשׁוּעָה', '["yᵉshûwʻâh"]', '["with/ salvation"]', '["n-f"]', 'something saved, i.e. (abstractly) deliverance; hence, aid, victory, prosperity deliverance, health, help(-ing), salvation, save, saving (health), welfare.', 'feminine passive participle of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4904}/H9028/[H7901]', 'inflected', 'heb', 'מִשְׁכָּב', '["mishkâb"]', '["bed/ their","beds/ their"]', '["n-m"]', 'a bed (figuratively, a bier); abstractly, sleep; by euphemism, carnal intercourse bed(-chamber), couch, lieth (lying) with.', 'from 7901;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7318}/[H7426]', 'lemma', 'heb', 'רוֹמָם', '["rôwmâm"]', '["[the] praises of"]', '["n-m"]', 'exaltation, i.e. (figuratively and specifically) praise be extolled.', 'from 7426;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6374}/[H6366]', 'lemma', 'heb', 'פִּיפִיָּה', '["pîyphîyâh"]', '["teeth"]', '["n-f"]', 'an edge or tooth tooth, × two-edged.', 'for 6366;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8433A}/[H3198]', 'lemma', 'heb', 'תּוֹכֵחָה', '["tôwkêchâh"]', '["punishment<s>","rebuke"]', '["n-f"]', 'chastisement; figuratively (by words) correction, refutation, proof (even in defence) argument, × chastened, correction, reasoning, rebuke, reproof, × be (often) reproved.', 'and תּוֹכַחַת; from 3198;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3513G}/H9038/[H3513]', 'inflected', 'heb', 'כָּבַד', '["kâbad"]', '["and/ honored [people]/ their"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8629}/[H8628]', 'inflected', 'heb', 'תֵּקַע', '["têqaʻ"]', '["with/ a blast of"]', '["n-m"]', 'a blast of a trumpet sound.', 'from 8628;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4234}/[H2342]', 'inflected', 'heb', 'מָחוֹל', '["mâchôwl"]', '["and/ dancing"]', '["n-m"]', 'a (round) dance dance(-cing).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H4482>', 'inflected', 'heb', 'במנים', '["be./mi.Nim"]', '["with/ stringed instruments"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6767D}/[H6750]', 'inflected', 'heb', 'צְלָצַל', '["tsᵉlâtsal"]', '["with/ cymbals of"]', '["n-m"]', 'a clatter, i.e. (abstractly) whirring (of wings); (concretely) a cricket; also a harpoon (as rattling),a cymbal (as clanging) cymbal, locust, shadowing, spear.', 'from 6750 reduplicated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8088A}/[H8085]', 'lemma', 'heb', 'שֵׁמַע', '["shêmaʻ"]', '["sound"]', '["n-m"]', 'something heard, i.e. a sound, rumor, announcement; abstractly, audience bruit, fame, hear(-ing), loud, report, speech, tidings.', 'from 8085;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4148H}/[H3256]', 'inflected', 'heb', 'מוּסָר', '["mûwçâr"]', '["and/ discipline"]', '["n-m"]', 'properly, chastisement; figuratively, reproof, warning or instruction; also restraint bond, chastening(-eth), chastisement, check, correction, discipline, doctrine, instruction, rebuke.', 'from 3256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4148H}/[H3256]', 'lemma', 'heb', 'מוּסָר', '["mûwçâr"]', '["[is the] correction of","[the] correction of","correction","correction of","instruction"]', '["n-m"]', 'properly, chastisement; figuratively, reproof, warning or instruction; also restraint bond, chastening(-eth), chastisement, check, correction, discipline, doctrine, instruction, rebuke.', 'from 3256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6612A}/[H6601]', 'inflected', 'heb', 'פְּתִי', '["pᵉthîy"]', '["to/ naive people"]', '["a n-f"]', 'silly (i.e. seducible) foolish, simple(-icity, one).', 'or פֶּתִי; or פְּתָאִי; from 6601;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6195}/[H6193]', 'lemma', 'heb', 'עׇרְמָה', '["ʻormâh"]', '["prudence"]', '["n-f"]', 'trickery; or (in a good sense) discretion guile, prudence, subtilty, wilily, wisdom.', 'feminine of 6193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3948}/[H3947]', 'lemma', 'heb', 'לֶקַח', '["leqach"]', '["insight","instruction","teaching"]', '["n-m"]', 'properly, something received, i.e. (mentally) instruction (whether on the part of the teacher or hearer); also (in an active and sinister sense) inveiglement doctrine, learning, fair speech.', 'from 3947;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8458}/[H2254]', 'lemma', 'heb', 'תַּחְבֻּלָה', '["tachbulâh"]', '["[are] wise directions","[the] counsel of","wise directions"]', '["n-f"]', '(only in plural) properly, steerage (as a management of ropes), i.e. (figuratively) guidance or (by implication) a plan good advice, (wise) counsels.', 'or תַּחְבּוּלָה; from 2254 as denominative from 2256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4426}/[H3887]', 'inflected', 'heb', 'מְלִיצָה', '["mᵉlîytsâh"]', '["and/ a mocking song","and/ an enigma"]', '["n-f"]', 'an aphorism; also a satire interpretation, taunting.', 'from 3887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2420}/H9028/[H2330]', 'inflected', 'heb', 'חִידָה', '["chîydâh"]', '["and/ parables/ their"]', '["n-f"]', 'a puzzle, hence, a trick, conundrum, sententious maxim dark saying (sentence, speech), hard question, proverb, riddle.', 'from 2330;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0936}\/[H936]', 'inflected', 'heb', 'בּוּז', '["bûwz"]', '["they despise"]', '["v"]', 'to disrespect contemn, despise, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3880}/[H3867]', 'lemma', 'heb', 'לִוְיָה', '["livyâh"]', '["[will be] a wreath of","a wreath of"]', '["n-f"]', 'something attached, i.e. a wreath ornament.', 'from 3867;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H7218A>/H9021', 'inflected', 'heb', 'לראשך', '["Le./ro.she./kha","le./ro.She./kha"]', '["for/ head/ your","to/ head/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6060B}/[H6059]', 'inflected', 'heb', 'עָנָק', '["ʻânâq"]', '["and/ necklaces"]', '["n-m"]', 'a necklace (as if strangling) chain.', 'from 6059;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1621}/H9021/[H1641]', 'inflected', 'heb', 'גַּרְגְּרוֹת', '["gargᵉrôwth"]', '["for/ neck/ your"]', '["n-f"]', 'the throat (as used in rumination) neck.', 'feminine plural from 1641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6601B}/H9031/[H6601]', 'inflected', 'heb', 'פָּתָה', '["pâthâh"]', '["they will entice/ you"]', '["v"]', 'to open, i.e. be (causatively, make) roomy; usually figuratively (in a mental or moral sense) to be (causatively, make) simple or (in a sinister way) delude allure, deceive, enlarge, entice, flatter, persuade, silly (one).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5355A}/[H5352]', 'inflected', 'heb', 'נָקִי', '["nâqîy"]', '["for/ an innocent [one]"]', '["a"]', 'innocent blameless, clean, clear, exempted, free, guiltless, innocent, quit.', 'or נָקִיא; (Joel 4:19; Jonah 1:14), from 5352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7585}/[H7592]', 'inflected', 'heb', 'שְׁאוֹל', '["shᵉʼôwl"]', '["like/ Sheol"]', '["n-f"]', 'hades or the world of the dead (as if a subterranean retreat), including its accessories and inmates grave, hell, pit.', 'or שְׁאֹל; from 7592;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8549I}/[H8552]', 'inflected', 'heb', 'תָּמִים', '["tâmîym"]', '["and/ complete"]', '["a"]', 'entire (literally, figuratively or morally); also (as noun) integrity, truth without blemish, complete, full, perfect, sincerely (-ity), sound, without spot, undefiled, upright(-ly), whole.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3381}/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["like/ [those who] go down of"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1486>/H9021', 'opaque', 'heb', 'גּוֹרָל', '["gôwrâl"]', '["lot/ your"]', '["n-m"]', 'properly, a pebble, i.e. a lot (small stones being used for that purpose); figuratively, a portion or destiny (as if determined by lot) lot.', 'or (shortened) גֹּרָל; from an unused root meaning to be rough (as stone);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3599}/[H3563]', 'lemma', 'heb', 'כִּיס', '["kîyç"]', '["[the] bag","a bag"]', '["n-m"]', 'a cup; also a bag for money or weights bag, cup, purse.', 'a form for 3563;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3605}/H9025/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["[belong] to/ all of/ us","to/ all of/ us"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H5410B>/H9028', 'inflected', 'heb', 'מנתיבתם', '["mi./ne.ti.va.Ta/m"]', '["from/ pathway/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8210H}/[H8210]', 'inflected', 'heb', 'שָׁפַךְ', '["shâphak"]', '["to/ shed","to/ shed [it]"]', '["v"]', 'to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1818}/H9028/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["for/ own blood/ their"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5315H}/H9028/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["for/ own life/ their"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1214I}/[H1214]', 'lemma', 'heb', 'בָּצַע', '["bâtsaʻ"]', '["[is] gaining","[one who] gains","[one who] gains unjustly","he has fulfilled","to make unjust gain"]', '["v"]', 'to break off, i.e. (usually) plunder; figuratively, to finish, or (intransitively) stop (be) covet(-ous), cut (off), finish, fulfill, gain (greedily), get, be given to (covetousness), greedy, perform, be wounded.', 'a primitive root');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6612B}/[H6601]', 'lemma', 'heb', 'פְּתִי', '["pᵉthîy"]', '["naivete"]', '["a n-f"]', 'silly (i.e. seducible) foolish, simple(-icity, one).', 'or פֶּתִי; or פְּתָאִי; from 6601;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3887}/[H3887]', 'inflected', 'heb', 'לוּץ', '["lûwts"]', '["and/ a mocker","and/ mockers"]', '["v"]', 'properly, to make mouths at, i.e. to scoff; hence (from the effort to pronounce a foreign language) to interpret, or (generally) intercede ambassador, have in derision, interpreter, make a mock, mocker, scorn(-er, -ful), teacher.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3944}/[H3887]', 'lemma', 'heb', 'לָצוֹן', '["lâtsôwn"]', '["mockery"]', '["n-m"]', 'derision scornful(-ning).', 'from 3887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8433B}/H9020/[H3198]', 'inflected', 'heb', 'תּוֹכֵחָה', '["tôwkêchâh"]', '["to/ rebuke/ my"]', '["n-f"]', 'chastisement; figuratively (by words) correction, refutation, proof (even in defence) argument, × chastened, correction, reasoning, rebuke, reproof, × be (often) reproved.', 'and תּוֹכַחַת; from 3198;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0343}/H9026/[H181]', 'inflected', 'heb', 'אֵיד', '["ʼêyd"]', '["at/ calamity/ your"]', '["n-m"]', 'oppression; by implication misfortune, ruin calamity, destruction.', 'from the same as 181 (in the sense of bending down);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H7722B>', 'inflected', 'heb', 'כשואה', '["ka./sho.''Ah","khe./sha.''a.vah"]', '["like <the>/ storm","like/ devastation"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0343}/H9026/[H181]', 'inflected', 'heb', 'אֵיד', '["ʼêyd"]', '["and/ calamity/ your"]', '["n-m"]', 'oppression; by implication misfortune, ruin calamity, destruction.', 'from the same as 181 (in the sense of bending down);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5492A}/[H5486]', 'inflected', 'heb', 'סוּפָה', '["çûwphâh"]', '["like <the>/ storm-wind","like/ a storm-wind","like/ storm-winds"]', '["n-f n-pr-loc"]', 'a hurricane Red Sea, storm, tempest, whirlwind, Red sea.', 'from 5486;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6695B}/[H6693]', 'inflected', 'heb', 'צוֹק', '["tsôwq"]', '["and/ distress"]', '["n-m n-f"]', 'a strait, i.e. (figuratively) distress anguish, × troublous.', 'or (feminine) צוּקָה; from 6693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7836}/H9030/[H7836]', 'inflected', 'heb', 'שָׁחַר', '["shâchar"]', '["they will earnestly seek/ me","they will seek earnestly/ me"]', '["v"]', 'properly, to dawn, i.e. (figuratively) be (up) early at any task (with the implication of earnestness); by extension, to search for (with painstaking) (do something) betimes, enquire early, rise (seek) betimes, seek diligently) early, in the morning).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6098}/H9020/[H3289]', 'inflected', 'heb', 'עֵצָה', '["ʻêtsâh"]', '["to/ advice/ my"]', '["n-f"]', 'advice; by implication, plan; also prudence advice, advisement, counsel([-lor]), purpose.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4156}/H9028/[H3289]', 'inflected', 'heb', 'מוֹעֵצָה', '["môwʻêtsâh"]', '["and/ from/ own schemes/ their"]', '["n-f"]', 'a purpose counsel, device.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4878}/[H7725]', 'lemma', 'heb', 'מְשׁוּבָה', '["mᵉshûwbâh"]', '["O apostate one","[the] apostate one","[the] waywardness of","apostasy"]', '["n-f"]', 'apostasy backsliding, turning away.', 'or מְשֻׁבָה; from 7725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7962}/[H7951]', 'inflected', 'heb', 'שַׁלְוָה', '["shalvâh"]', '["and/ [the] ease of","and/ ease of","and/ quietness"]', '["n-f"]', 'security (genuine or false) abundance, peace(-ably), prosperity, quietness.', 'from 7951;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7599}/[H7599]', 'inflected', 'heb', 'שָׁאַן', '["shâʼan"]', '["and/ he will be at ease"]', '["v"]', 'to loll, i.e. be peaceful be at ease, be quiet, rest. See also 1052.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8394}/[H995]', 'inflected', 'heb', 'תָּבוּן', '["tâbûwn"]', '["to <the>/ understanding"]', '["n-m"]', 'intelligence; by implication, an argument; by extension, caprice discretion, reason, skilfulness, understanding, wisdom.', 'and (feminine) תְּבוּנָה; or תּוֹבֻנָה; from 995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0998}/[H995]', 'inflected', 'heb', 'בִּינָה', '["bîynâh"]', '["to <the>/ discernment"]', '["n-f"]', 'understanding knowledge, meaning, × perfectly, understanding, wisdom.', 'from 995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3701G}/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["like <the>/ silver"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H4301}/[H2934]', 'inflected', 'heb', 'מַטְמוֹן', '["maṭmôwn"]', '["and/ like <the>/ treasures"]', '["n-m"]', 'a secret storehouse; hence, a secreted valuable (buried); generally money hidden riches, (hid) treasure(-s).', 'or מַטְמֹן; or מַטְמֻן; from 2934;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2664}/H9034/[H2664]', 'inflected', 'heb', 'חָפַשׂ', '["châphas"]', '["you will search for/ it"]', '["v"]', 'to seek; causatively, to conceal oneself (i.e. let be sought), or mask change, (make) diligent (search), disquise self, hide, search (for, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3820A}/H9021/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["in/ heart/ your"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5315G}/H9021/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["for/ self/ your","to/ self/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5341}/H9031/[H5341]', 'inflected', 'heb', 'נָצַר', '["nâtsar"]', '["it will preserve/ you"]', '["v"]', 'to guard, in a good sense (to protect, maintain, obey, etc.) or a bad one (to conceal, etc.) besieged, hidden thing, keep(-er, -ing), monument, observe, preserve(-r), subtil, watcher(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1870G}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["from/ [the] way of","from/ a way"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H0376I>', 'inflected', 'heb', 'מאיש', '["me./''Ish"]', '["from/ anyone","more than/ anyone","more than/ someone"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5800A}/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["<the>/ forsaken","those/ [who] leave","who/ leaves"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8419}/[H2015]', 'inflected', 'heb', 'תַּהְפֻּכָה', '["tahpukâh"]', '["in/ perverse things of"]', '["n-f"]', 'a perversity or fraud (very) froward(-ness, thing), perverse thing.', 'from 2015;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0734}/H9028/[H732]', 'inflected', 'heb', 'אֹרַח', '["ʼôrach"]', '["paths/ their"]', '["n-m"]', 'a well-trodden road (literally or figuratively); also a caravan manner, path, race, rank, traveller, troop, (by-, high-) way.', 'from 732;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3868}/[H3867]', 'inflected', 'heb', 'לוּז', '["lûwz"]', '["and/ [the] [one who] is crooked of","and/ [who are] crooked","and/ a crooked [thing]"]', '["v"]', 'to turn aside , i.e. (literally) to depart, (figuratively) be perverse depart, froward, perverse(-ness).', 'a primitive root; (compare 3867, 3874 and 3885)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4570}/H9028/[H5696]', 'inflected', 'heb', 'מַעְגָּל', '["maʻgâl"]', '["in/ tracks/ their","on/ tracks/ their"]', '["n-m"]', 'a track (literally or figuratively); also a rampart (as circular) going, path, trench, way(-side).', 'or feminine מַעְגָּלָה; from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5237}/[H5235]', 'inflected', 'heb', 'נׇכְרִי', '["nokrîy"]', '["from/ a foreign [woman]"]', '["a"]', 'strange, in a variety of degrees and applications (foreign, non-relative, adulterous, different, wonderful) alien, foreigner, outlandish, strange(-r, woman).', 'from 5235 (second form);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0441A}/[H502]', 'lemma', 'heb', 'אַלּוּף', '["ʼallûwph"]', '["[the] close friend of","[were] [the] close friend of","a close friend","a tame one","close friends"]', '["a-m"]', 'familiar; a friend, also gentle; hence, a bullock (as being tame; applied, although masculine, to a cow); and so, a chieftain (as notable, like neat cattle) captain, duke, (chief) friend, governor, guide, ox.', 'or (shortened) אַלֻּף; from 502;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5271A}/H9024/[H5288]', 'inflected', 'heb', 'נָעוּר', '["nâʻûwr"]', '["youth<s>/ her"]', '["n-m n-f"]', '(only in plural collective or emphatic form) youth, the state (juvenility) or the persons (young people) childhood, youth.', 'or נָעֻר; and (feminine) נְעֻרָה; properly, passive participle from 5288 as denominative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430G}/H9024/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["God/ her","God/ its"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4570}/H9024/[H5696]', 'inflected', 'heb', 'מַעְגָּל', '["maʻgâl"]', '["tracks/ her"]', '["n-m"]', 'a track (literally or figuratively); also a rampart (as circular) going, path, trench, way(-side).', 'or feminine מַעְגָּלָה; from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935G}/H9034/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["I have brought/ it","I will bring/ it","[those who] go to/ her"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8549H}/[H8552]', 'inflected', 'heb', 'תָּמִים', '["tâmîym"]', '["and/ blameless [people]"]', '["a"]', 'entire (literally, figuratively or morally); also (as noun) integrity, truth without blemish, complete, full, perfect, sincerely (-ity), sound, without spot, undefiled, upright(-ly), whole.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0898}/[H898]', 'inflected', 'heb', 'בָּגַד', '["bâgad"]', '["and/ [the] traitor","and/ treacherous [people]"]', '["v"]', 'to cover (with a garment); figuratively, to act covertly; by implication, to pillage deal deceitfully (treacherously, unfaithfully), offend, transgress(-or), (depart), treacherous (dealer, -ly, man), unfaithful(-ly, man), × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5255}/[H5255]', 'lemma', 'heb', 'נָסַח', '["nâçach"]', '["he tears down","they will be torn away"]', '["v"]', 'to tear away destroy, pluck, root.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7194}/H9038/[H7194]', 'inflected', 'heb', 'קָשַׁר', '["qâshar"]', '["bind/ them"]', '["v"]', 'to tie, physically (gird, confine, compact) or mentally (in love, league) bind (up), (make a) conspire(-acy, -ator), join together, knit, stronger, work (treason).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1621}/H9021/[H1641]', 'inflected', 'heb', 'גַּרְגְּרוֹת', '["gargᵉrôwth"]', '["necks/ your"]', '["n-f"]', 'the throat (as used in rumination) neck.', 'feminine plural from 1641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3789}/H9038/[H3789]', 'inflected', 'heb', 'כָּתַב', '["kâthab"]', '["write/ them"]', '["v"]', 'to grave, by implication, to write (describe, inscribe, prescribe, subscribe) describe, record, prescribe, subscribe, write(-ing, -ten).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7922}/[H7919]', 'inflected', 'heb', 'שֶׂכֶל', '["sekel"]', '["and/ insight"]', '["n-m"]', 'intelligence; by implication, success discretion, knowledge, policy, prudence, sense, understanding, wisdom, wise.', 'or שֵׂכֶל; from 7919;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0120G}\/[H119]', 'inflected', 'heb', 'אָדָם', '["ʼâdâm"]', '["and/ humankind"]', '["n-m"]', 'ruddy i.e. a human being (an individual or the species, mankind, etc.) × another, hypocrite, common sort, × low, man (mean, of low degree), person.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0998}/H9021/[H995]', 'inflected', 'heb', 'בִּינָה', '["bîynâh"]', '["own understanding/ your"]', '["n-f"]', 'understanding knowledge, meaning, × perfectly, understanding, wisdom.', 'from 995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7500}/[H7495]', 'lemma', 'heb', 'רִפְאוּת', '["riphʼûwth"]', '["healing"]', '["n-f"]', 'a cure health.', 'from 7495;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8270}/H9021/[H8324]', 'inflected', 'heb', 'שֹׁר', '["shôr"]', '["to/ navel/ your"]', '["n-m"]', 'a string (as twisted ), i.e. (specifically) the umbilical cord (also figuratively, as the centre of strength) navel.', 'from 8324; (compare 8306)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8250}/[H8248]', 'inflected', 'heb', 'שִׁקּוּי', '["shiqqûwy"]', '["and/ refreshment"]', '["n-m"]', 'a beverage; moisture, i.e. (figuratively) refreshment drink, marrow.', 'from 8248;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6106G}/H9021/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["to/ bones/ your"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1952}/H9021/[H1951]', 'inflected', 'heb', 'הוֹן', '["hôwn"]', '["from/ wealth/ your"]', '["n-m"]', 'wealth; by implication, enough enough, for nought, riches, substance, wealth.', 'from the same as 1951 in the sense of 202;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H7225G}/[H7218]', 'inflected', 'heb', 'רֵאשִׁית', '["rêʼshîyth"]', '["and/ from/ [the] first of"]', '["n-f"]', 'the first, in place, time, order or rank (specifically, a firstfruit) beginning, chief(-est), first(-fruits, part, time), principal thing.', 'from the same as 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0618>/H9021', 'opaque', 'heb', 'אָסָם', '["ʼâçâm"]', '["storehouses/ your"]', '["n-m"]', 'a storehouse (only in the plural) barn, storehouse.', 'from an unused root meaning to heap together;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3342>/H9021', 'opaque', 'heb', 'יֶקֶב', '["yeqeb"]', '["wine vats/ your"]', '["n-m"]', 'a trough (as dug out); specifically, a wine-vat (whether the lower one, into which the juice drains; or the upper, in which the grapes are crushed) fats, presses, press-fat, wine(-press).', 'from an unused root meaning to excavate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8433B}/H9023/[H3198]', 'inflected', 'heb', 'תּוֹכֵחָה', '["tôwkêchâh"]', '["<in>/ rebuke/ his"]', '["n-f"]', 'chastisement; figuratively (by words) correction, refutation, proof (even in defence) argument, × chastened, correction, reasoning, rebuke, reproof, × be (often) reproved.', 'and תּוֹכַחַת; from 3198;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0001G}/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["and/ like/ a father"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5504}/H9024/[H5503]', 'inflected', 'heb', 'סַחַר', '["çachar"]', '["profit/ her","profit/ its"]', '["n-m"]', 'profit (from trade) merchandise.', 'from 5503;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5504}/[H5503]', 'inflected', 'heb', 'סַחַר', '["çachar"]', '["more than/ [the] profit of"]', '["n-m"]', 'profit (from trade) merchandise.', 'from 5503;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H2742D}/[H2782]', 'inflected', 'heb', 'חֲרוּץ', '["chărûwts"]', '["and/ more than/ gold"]', '["a"]', 'properly, incised or (active) incisive; hence (as noun masculine or feminine) a trench (as dug), gold (as mined), a threshing-sledge (having sharp teeth); (figuratively) determination; also eager decision, diligent, (fine) gold, pointed things, sharp, threshing instrument, wall.', 'or חָרֻץ; passive participle of 2782;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3225G}/H9024/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["[is] in/ right [hand]/ her"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8040G}/H9024/[H8071]', 'inflected', 'heb', 'שְׂמֹאול', '["sᵉmôʼwl"]', '["[are] in/ left [hand]/ her"]', '["n-m"]', 'properly, dark (as enveloped), i.e. the north; hence (by orientation), the left hand left (hand, side).', 'or שְׂמֹאל; a primitive word (rather perhaps from the same as 8071 (by insertion of the aleph) through the idea of wrapping up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870G}/H9024/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["ways/ her","ways/ its"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5410B>/H9024', 'opaque', 'heb', 'נָתִיב', '["nâthîyb"]', '["pathways/ her"]', '["n-m"]', 'a (beaten) track path(-way), × travel(-ler), way.', 'or (feminine) נְתִיבָה; or נְתִבָה; (Jeremiah 6:16), from an unused root meaning to tramp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2388H}/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["to <the>/ [those who] take hold","to/ take hold"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8551}/H9034/[H8551]', 'inflected', 'heb', 'תָּמַךְ', '["tâmak"]', '["and/ [those who] hold fast to/ her"]', '["v"]', 'to sustain; by implication, to obtain, keep fast; figuratively, to help, follow close (take, up-) hold (up), maintain, retain, stay (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0833}\/[H833]', 'inflected', 'heb', 'אָשַׁר', '["ʼâshar"]', '["[are] called blessed"]', '["v"]', 'to be straight (used in the widest sense, especially to be level, right, happy); figuratively, to go forward, be honest, prosper (call, be) bless(-ed, happy), go, guide, lead, relieve.', 'or אָשֵׁר; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1847}/H9023/[H3045]', 'inflected', 'heb', 'דַּעַת', '["daʻath"]', '["by/ knowledge/ his"]', '["n"]', 'knowledge cunning, (ig-) norantly, know(-ledge), (un-) awares (wittingly).', 'from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7834}/[H7833]', 'inflected', 'heb', 'שַׁחַק', '["shachaq"]', '["and/ clouds"]', '["n-m"]', 'a powder (as beaten small); by analogy, a thin vapor; by extension, the firmament cloud, small dust, heaven, sky.', 'from 7833;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3868}/[H3867]', 'lemma', 'heb', 'לוּז', '["lûwz"]', '["a crooked [person]","let them depart","they depart"]', '["v"]', 'to turn aside , i.e. (literally) to depart, (figuratively) be perverse depart, froward, perverse(-ness).', 'a primitive root; (compare 3867, 3874 and 3885)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5869H}/H9021/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["from/ eyes/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2580}/[H2603]', 'inflected', 'heb', 'חֵן', '["chên"]', '["and/ grace"]', '["n-m"]', 'graciousness, i.e. subjective (kindness, favor) or objective (beauty) favour, grace(-ious), pleasant, precious, (well-) favoured.', 'from 2603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6149}/[H6148]', 'inflected', 'heb', 'עָרֵב', '["ʻârêb"]', '["and/ it will be pleasing"]', '["v"]', 'to be agreeable be pleasant(-ing), take pleasure in, be sweet.', 'a primitive root (rather identical with 6148 through the idea of close association);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8142}/H9021/[H3462]', 'inflected', 'heb', 'שֵׁנָה', '["shênâh"]', '["sleep/ your"]', '["n-f"]', 'sleep sleep.', 'or שֵׁנָא; (Psalm 127:2), from 3462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H7722B>', 'inflected', 'heb', 'ומשאת', '["u./mi./sho.''At"]', '["and/ from/ [the] devastation of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3689}/H9021/[H3688]', 'inflected', 'heb', 'כֶּסֶל', '["keçel"]', '["<in>/ confidence/ your"]', '["n-m"]', 'properly, fatness, i.e. by implication (literally) the loin (as the seat of the leaf fat) or (generally) the viscera; also (figuratively) silliness or (in a good sense) trust confidence, flank, folly, hope, loin.', 'from 3688;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3921}/[H3920]', 'inflected', 'heb', 'לֶכֶד', '["leked"]', '["from/ capture"]', '["n-m"]', 'something to capture with, i.e. a noose being taken.', 'from 3920;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1167I}/H9023/[H1166]', 'inflected', 'heb', 'בַּעַל', '["baʻal"]', '["from/ owners/ its"]', '["n-m"]', 'a master; hence, a husband, or (figuratively) owner (often used with another noun in modifications of this latter sense) archer, babbler, bird, captain, chief man, confederate, have to do, dreamer, those to whom it is due, furious, those that are given to it, great, hairy, he that hath it, have, horseman, husband, lord, man, married, master, person, sworn, they of.', 'from 1166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5475}/H9023/[H3245]', 'inflected', 'heb', 'סוֹד', '["çôwd"]', '["intimacy/ his","secret counsel/ his"]', '["n-m"]', 'a session, i.e. company of persons (in close deliberation); by implication, intimacy, consultation, a secret assembly, consel, inward, secret (counsel).', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3994}/[H779]', 'lemma', 'heb', 'מְאֵרָה', '["mᵉʼêrâh"]', '["[the] curse of","curses"]', '["n-f"]', 'an execration curse.', 'from 779;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5116A}/[H5115]', 'inflected', 'heb', 'נָוֶה', '["nâveh"]', '["and/ [the] habitation of"]', '["n"]', '(adjectively) at home; hence (by implication of satisfaction) lovely; also (noun) a home, of God (temple), men (residence), flocks (pasture), or wild animals (den) comely, dwelling (place), fold, habitation, pleasant place, sheepcote, stable, tarried.', 'or (feminine) נָוָה; from 5115;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3887}/[H3887]', 'inflected', 'heb', 'לוּץ', '["lûwts"]', '["<to the>/ mockers","for <the>/ mockers"]', '["v"]', 'properly, to make mouths at, i.e. to scoff; hence (from the effort to pronounce a foreign language) to interpret, or (generally) intercede ambassador, have in derision, interpreter, make a mock, mocker, scorn(-er, -ful), teacher.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6035}/[H6041]', 'inflected', 'heb', 'עָנָו', '["ʻânâv"]', '["and/ to/ humble [people]"]', '["n-m"]', 'depressed (figuratively), in mind (gentle) or circumstances (needy, especially saintly) humble, lowly, meek, poor. Compare 6041.', 'or (by intermixture with 6041) עָנָיו; from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7036}\/[H7034]', 'inflected', 'heb', 'קָלוֹן', '["qâlôwn"]', '["shame"]', '["n-m"]', 'disgrace; (by implication) the pudenda confusion, dishonour, ignominy, reproach, shame.', 'from 7034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7181}/[H7181]', 'inflected', 'heb', 'קָשַׁב', '["qâshab"]', '["and/ be attentive","and/ pay attention"]', '["v"]', 'to prick up the ears, i.e. hearken attend, (cause to) hear(-ken), give heed, incline, mark (well), regard.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3173}/[H3161]', 'inflected', 'heb', 'יָחִיד', '["yâchîyd"]', '["and/ only [child]"]', '["a"]', 'properly, united, i.e. sole; by implication, beloved; also lonely; (feminine) the life (as not to be replaced) darling, desolate, only (child, son), solitary.', 'from 3161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3384B}/H9030/[H3384]', 'inflected', 'heb', 'יָרָה', '["yârâh"]', '["and/ he taught/ me"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0561}/[H559]', 'inflected', 'heb', 'אֵמֶר', '["ʼêmer"]', '["from/ [the] utterances of","from/ words of"]', '["n-m"]', 'something said answer, × appointed unto him, saying, speech, word.', 'from 559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5800A}/H9034/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["leave/ it","you abandon/ her"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8104G}/H9031/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["and/ she will keep/ you"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5341}/H9031/[H5341]', 'inflected', 'heb', 'נָצַר', '["nâtsar"]', '["and/ I may watch over/ you","and/ I will watch over/ you","and/ she will guard/ you"]', '["v"]', 'to guard, in a good sense (to protect, maintain, obey, etc.) or a bad one (to conceal, etc.) besieged, hidden thing, keep(-er, -ing), monument, observe, preserve(-r), subtil, watcher(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5549}/H9034/[H5549]', 'inflected', 'heb', 'סָלַל', '["çâlal"]', '["esteem/ her","pile up/ it"]', '["v"]', 'to mound up (especially a turnpike); figurative, to exalt; reflexively, to oppose (as by a dam) cast up, exalt (self), extol, make plain, raise up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2263}/H9034/[H2263]', 'inflected', 'heb', 'חָבַק', '["châbaq"]', '["you will embrace/ her"]', '["v"]', 'to clasp (the hands or in embrace) embrace, fold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4042}/H9031/[H4043]', 'inflected', 'heb', 'מָגַן', '["mâgan"]', '["she will give/ you","will I deliver up?/ you"]', '["v"]', 'properly, to shield; encompass with; figuratively, to rescue, to hand safely over (i.e. surrender) deliver.', 'a denominative from 4043;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3947H}/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["and/ receive","and/ take","so/ it may receive"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1869}/H9031/[H1869]', 'inflected', 'heb', 'דָּרַךְ', '["dârak"]', '["I led/ you","[who] leads/ you"]', '["v"]', 'to tread; by implication, to walk; also to string a bow (by treading on it in bending) archer, bend, come, draw, go (over), guide, lead (forth), thresh, tread (down), walk.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1980I}/H9041/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["when/ walking about/ you","when/ walking/ you"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6806}/H9021/[H6804]', 'inflected', 'heb', 'צַעַד', '["tsaʻad"]', '["step[s]/ your"]', '["n-m"]', 'a pace or regular step pace, step.', 'from 6804;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4148H}/[H3256]', 'inflected', 'heb', 'מוּסָר', '["mûwçâr"]', '["on <the>/ discipline"]', '["n-m"]', 'properly, chastisement; figuratively, reproof, warning or instruction; also restraint bond, chastening(-eth), chastisement, check, correction, discipline, doctrine, instruction, rebuke.', 'from 3256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5341}/H9034/[H5341]', 'inflected', 'heb', 'נָצַר', '["nâtsar"]', '["I guard/ it","[am] keeper/ its","keep/ her"]', '["v"]', 'to guard, in a good sense (to protect, maintain, obey, etc.) or a bad one (to conceal, etc.) besieged, hidden thing, keep(-er, -ing), monument, observe, preserve(-r), subtil, watcher(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0833}/[H833]', 'lemma', 'heb', 'אָשַׁר', '["ʼâshar"]', '["[are] calling blessed","[the] guides","set right","you advance"]', '["v"]', 'to be straight (used in the widest sense, especially to be level, right, happy); figuratively, to go forward, be honest, prosper (call, be) bless(-ed, happy), go, guide, lead, relieve.', 'or אָשֵׁר; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5051}/[H5050]', 'lemma', 'heb', 'נֹגַהּ', '["nôgahh"]', '["[the] brightness of","brightness"]', '["n-f"]', 'brilliancy (literally or figuratively) bright(-ness), light, (clear) shining.', 'from 5050;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0653}/[H651]', 'inflected', 'heb', 'אֲפֵלָה', '["ʼăphêlâh"]', '["[is] like <the>/ darkness"]', '["n-f"]', 'duskiness, figuratively, misfortune; concrete, concealment dark, darkness, gloominess, × thick.', 'feminine of 651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3782}\/[H3782]', 'inflected', 'heb', 'כָּשַׁל', '["kâshal"]', '["are they stumbling"]', '["v"]', 'to totter or waver (through weakness of the legs, especially the ankle); by implication, to falter, stumble, faint or fall bereave (from the margin), cast down, be decayed, (cause to) fail, (cause, make to) fall (down, -ing), feeble, be (the) ruin(-ed, of), (be) overthrown, (cause to) stumble, × utterly, be weak.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1697G}/H9020/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["to/ words/ my"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0561}/H9020/[H559]', 'inflected', 'heb', 'אֵמֶר', '["ʼêmer"]', '["to/ utterances/ my"]', '["n-m"]', 'something said answer, × appointed unto him, saying, speech, word.', 'from 559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8104G}/H9038/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["keep/ them"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4672}/H9038/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["to/ [those who] find/ them"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6143}/[H6141]', 'lemma', 'heb', 'עִקְּשׁוּת', '["ʻiqqᵉshûwth"]', '["crookedness of"]', '["n-f"]', 'perversity × froward.', 'from 6141;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3891}/[H3868]', 'inflected', 'heb', 'לְזוּת', '["lᵉzûwth"]', '["and/ deviousness of"]', '["n-f"]', 'perverseness perverse.', 'from 3868;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6079}/H9021/[H5774]', 'inflected', 'heb', 'עַפְעַף', '["ʻaphʻaph"]', '["and/ eyelids/ your"]', '["n-m"]', 'an eyelash (as fluttering); figuratively, morning ray dawning, eye-lid.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2451}/H9020/[H2449]', 'inflected', 'heb', 'חׇכְמָה', '["chokmâh"]', '["to/ wisdom/ my"]', '["n-f"]', 'wisdom (in a good sense) skilful, wisdom, wisely, wit.', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8394}/H9020/[H995]', 'inflected', 'heb', 'תָּבוּן', '["tâbûwn"]', '["to/ understanding/ my"]', '["n-m"]', 'intelligence; by implication, an argument; by extension, caprice discretion, reason, skilfulness, understanding, wisdom.', 'and (feminine) תְּבוּנָה; or תּוֹבֻנָה; from 995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5317}/[H5130]', 'lemma', 'heb', 'נֹפֶת', '["nôpheth"]', '["honey"]', '["n-m"]', 'a dripping i.e. of honey (from the comb) honeycomb.', 'from 5130 in the sense of shaking to pieces;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2509}/[H2505]', 'inflected', 'heb', 'חָלָק', '["châlâq"]', '["and/ [is] smooth"]', '["a"]', 'smooth (especially of tongue) flattering, smooth.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2441}/H9024/[H2596]', 'inflected', 'heb', 'חֵךְ', '["chêk"]', '["mouth/ her"]', '["n-m"]', 'properly, the palate or inside of the mouth; hence, the mouth itself (as the organ of speech, taste and kissing) (roof of the) mouth, taste.', 'probably from 2596 in the sense of tasting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0319}/H9024/[H310]', 'inflected', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["and/ end/ her","and/ end/ its"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H3939>', 'inflected', 'heb', 'כלענה', '["kha./la.''a.Nah"]', '["like <the>/ wormwood"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6806}/H9024/[H6804]', 'inflected', 'heb', 'צַעַד', '["tsaʻad"]', '["steps/ her"]', '["n-m"]', 'a pace or regular step pace, step.', 'from 6804;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0394}/[H393]', 'inflected', 'heb', 'אַכְזָרִי', '["ʼakzârîy"]', '["to/ a cruel [person]"]', '["a"]', 'terrible cruel (one).', 'from 393;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6089A}/H9021/[H6087]', 'inflected', 'heb', 'עֶצֶב', '["ʻetseb"]', '["and/ labor/ your"]', '["n-m"]', 'an earthen vessel; usually (painful) toil; also a pang (whether of body or mind) grievous, idol, labor, sorrow.', 'from 6087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5098}/[H5098]', 'inflected', 'heb', 'נָהַם', '["nâham"]', '["and/ you will groan"]', '["v"]', 'to growl mourn, roar(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3615H}/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["when/ wastes away"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7607}/H9021/[H7604]', 'inflected', 'heb', 'שְׁאֵר', '["shᵉʼêr"]', '["and/ body/ your"]', '["n-m"]', 'flesh (as swelling out), as living or for food; generally food of any kind; figuratively, kindred by blood body, flesh, food, (near) kin(-sman, -swoman), near (nigh) (of kin).', 'from 7604;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8433B}/[H3198]', 'inflected', 'heb', 'תּוֹכֵחָה', '["tôwkêchâh"]', '["and/ rebuke"]', '["n-f"]', 'chastisement; figuratively (by words) correction, refutation, proof (even in defence) argument, × chastened, correction, reasoning, rebuke, reproof, × be (often) reproved.', 'and תּוֹכַחַת; from 3198;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4175}/H9020/[H3384]', 'inflected', 'heb', 'מוֹרֶה', '["môwreh"]', '["instructor/ my"]', '["n-m"]', 'an archer; also teacher or teaching; also the early rain (early) rain.', 'from 3384; (see 3138)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3925G}/H9030/[H3925]', 'inflected', 'heb', 'לָמַד', '["lâmad"]', '["and/ to/ teachers/ my"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0953A}/H9021/[H952]', 'inflected', 'heb', 'בּוֹר', '["bôwr"]', '["from/ own cistern/ your"]', '["n-m"]', 'a pit hole (especially one used as a cistern or a prison) cistern, dungeon, fountain, pit, well.', 'from 952 (in the sense of 877);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5140}/[H5140]', 'inflected', 'heb', 'נָזַל', '["nâzal"]', '["and/ flowing","and/ streams"]', '["v"]', 'to drip, or shed by trickling distil, drop, flood, (cause to) flow(-ing), gush out, melt, pour (down), running water, stream.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0875}/H9021/[H874]', 'inflected', 'heb', 'בְּאֵר', '["bᵉʼêr"]', '["own well/ your"]', '["n-f"]', 'a pit; especially a well pit, well.', 'from 874;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6327C}/[H6327]', 'lemma', 'heb', 'פּוּץ', '["pûwts"]', '["they will overflow","will they overflow?"]', '["v"]', 'to dash in pieces, literally or figuratively (especially to disperse) break (dash, shake) in (to) pieces, cast (abroad), disperse (selves), drive, retire, scatter (abroad), spread abroad.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4599}/H9021/[H5869]', 'inflected', 'heb', 'מַעְיָן', '["maʻyân"]', '["springs/ your"]', '["n-m"]', 'a fountain (also collectively), figuratively, a source (of satisfaction) fountain, spring, well.', 'or מַעְיְנוֹ; (Psalm 114:8), or (feminine) מַעְיָנָה; from 5869 (as a denominative in the sense of a spring);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4726}/H9021/[H6979]', 'inflected', 'heb', 'מָקוֹר', '["mâqôwr"]', '["spring/ your"]', '["n-m"]', 'properly, something dug, i.e. a (general) source (of water, even when naturally flowing; also of tears, blood (by euphemism, of the female pudenda); figuratively, of happiness, wisdom, progeny) fountain, issue, spring, well(-spring).', 'or מָקֹר; from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5271A}/H9021/[H5288]', 'inflected', 'heb', 'נָעוּר', '["nâʻûwr"]', '["youth<s>/ your"]', '["n-m n-f"]', '(only in plural collective or emphatic form) youth, the state (juvenility) or the persons (young people) childhood, youth.', 'or נָעֻר; and (feminine) נְעֻרָה; properly, passive participle from 5288 as denominative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0158}/[H157]', 'lemma', 'heb', 'אַהַב', '["ʼahab"]', '["lovers","loves"]', '["n-m"]', 'affection (in a good or a bad sense) love(-r).', 'from 157;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3280}/[H3277]', 'inflected', 'heb', 'יַעֲלָה', '["yaʻălâh"]', '["and/ a goat of"]', '["n-f"]', 'roe.', 'feminine of 3277');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1717}/H9024/[H1730]', 'inflected', 'heb', 'דַּד', '["dad"]', '["breasts/ her"]', '["n-m"]', 'the breast (as the seat of love, or from its shape) breast, teat.', 'apparently from the same as 1730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7301}/H9031/[H7301]', 'inflected', 'heb', 'רָוָה', '["râvâh"]', '["may they satisfy/ you"]', '["v"]', 'to slake the thirst (occasionally of other appetites) bathe, make drunk, (take the) fill, satiate, (abundantly) satisfy, soak, water (abundantly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0160}/H9024/[H158]', 'inflected', 'heb', 'אַהֲבָה', '["ʼahăbâh"]', '["by/ love/ her"]', '["n-f"]', 'love.', 'feminine of 158 and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2263}/[H2263]', 'inflected', 'heb', 'חָבַק', '["châbaq"]', '["<so>/ may you embrace?"]', '["v"]', 'to clasp (the hands or in embrace) embrace, fold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2436G>', 'opaque', 'heb', 'חֵיק', '["chêyq"]', '["[the] bosom of"]', '["n-m"]', 'the bosom (literally or figuratively) bosom, bottom, lap, midst, within.', 'or חֵק; and חוֹק; from an unused root, apparently meaning to inclose;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4570}/H9023/[H5696]', 'inflected', 'heb', 'מַעְגָּל', '["maʻgâl"]', '["tracks/ his"]', '["n-m"]', 'a track (literally or figuratively); also a rampart (as circular) going, path, trench, way(-side).', 'or feminine מַעְגָּלָה; from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0369}/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["for/ not","when/ there not","with/ not"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0200}/H9023/[H191]', 'inflected', 'heb', 'אִוֶּלֶת', '["ʼivveleth"]', '["foolishness/ his"]', '["n-f"]', 'silliness folly, foolishly(-ness).', 'from the same as 191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7686}\/[H7686]', 'inflected', 'heb', 'שָׁגָה', '["shâgâh"]', '["he will go astray"]', '["v"]', 'to stray (causatively, mislead), usually (figuratively) to mistake, especially (morally) to transgress; by extension (through the idea of intoxication) to reel, (figuratively) be enraptured (cause to) go astray, deceive, err, be ravished, sin through ignorance, (let, make to) wander.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0561}/[H559]', 'inflected', 'heb', 'אֵמֶר', '["ʼêmer"]', '["by/ [the] words of","with/ words of"]', '["n-m"]', 'something said answer, × appointed unto him, saying, speech, word.', 'from 559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7292}/[H7292]', 'inflected', 'heb', 'רָהַב', '["râhab"]', '["and/ importune"]', '["v"]', 'to urge severely, i.e. (figuratively) importune, embolden, capture, act insolently overcome, behave self proudly, make sure, strengthen.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5869A}/H9021/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["to/ eyes/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8572}/[H5123]', 'inflected', 'heb', 'תְּנוּמָה', '["tᵉnûwmâh"]', '["and/ slumber"]', '["n-f"]', 'drowsiness, i.e. sleep slumber(-ing).', 'from 5123;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6079}/H9021/[H5774]', 'inflected', 'heb', 'עַפְעַף', '["ʻaphʻaph"]', '["to/ eyelids/ your"]', '["n-m"]', 'an eyelash (as fluttering); figuratively, morning ray dawning, eye-lid.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H6833}/[H6852]', 'inflected', 'heb', 'צִפּוֹר', '["tsippôwr"]', '["and/ like <the>/ birds","and/ like/ a bird"]', '["n-f"]', 'a little bird (as hopping) bird, fowl, sparrow.', 'or צִפֹּר; from 6852;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3353}\/[H3369]', 'inflected', 'heb', 'יָקוּשׁ', '["yâqûwsh"]', '["a fowler"]', '["n-m"]', 'properly, entangled, i.e. by implication (intransitively) a snare, or (transitive) a snarer fowler, snare.', 'passive participle of 3369;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5244}/[H5243]', 'lemma', 'heb', 'נְמָלָה', '["nᵉmâlâh"]', '["an ant"]', '["n-f"]', 'an ant (probably from its almost bisected form) ant.', 'feminine from 5243;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6102}/[H6101]', 'lemma', 'heb', 'עָצֵל', '["ʻâtsêl"]', '["O sluggard","a sluggard","lazy"]', '["a"]', 'indolent slothful, sluggard.', 'from 6101;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2449}/[H2449]', 'inflected', 'heb', 'חָכַם', '["châkam"]', '["and/ act wisely","and/ be wise","and/ become wise","so/ he may be wise"]', '["v"]', 'to be wise (in mind, word or act) × exceeding, teach wisdom, be (make self, shew self) wise, deal (never so) wisely, make wiser.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7019}/[H6972]', 'inflected', 'heb', 'קַיִץ', '["qayits"]', '["in the/ summer"]', '["n-m"]', 'harvest (as the crop), whether the product (grain or fruit) or the (dry) season summer (fruit, house).', 'from 6972;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3899H}/H9024/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["food/ its"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7105A}/[H7114]', 'inflected', 'heb', 'קָצִיר', '["qâtsîyr"]', '["at the/ harvest"]', '["n-m"]', 'severed, i.e. harvest (as reaped), the crop, the time, the reaper, or figuratively; also a limb (of a tree, or simply foliage) bough, branch, harvest (man).', 'from 7114;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3978}/H9024/[H398]', 'inflected', 'heb', 'מַאֲכָל', '["maʼăkâl"]', '["food/ its"]', '["n-m"]', 'an eatable (includ. provender, flesh and fruit) food, fruit, (bake-)meat(-s), victual.', 'from 398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8142}/H9021/[H3462]', 'inflected', 'heb', 'שֵׁנָה', '["shênâh"]', '["from/ sleep/ your"]', '["n-f"]', 'sleep sleep.', 'or שֵׁנָא; (Psalm 127:2), from 3462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2264}/[H2263]', 'lemma', 'heb', 'חִבֻּק', '["chibbuq"]', '["folding of"]', '["n-m"]', 'a clasping of the hands (in idleness) fold.', 'from 2263;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7901H}/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["to/ rest"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1980N}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["like/ a traveler"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7389A}/H9021/[H7326]', 'inflected', 'heb', 'רֵישׁ', '["rêysh"]', '["poverty/ your"]', '["n-m"]', 'poverty poverty.', 'or רֵאשׁ; or רִישׁ; from 7326;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4270}/H9021/[H2637]', 'inflected', 'heb', 'מַחְסוֹר', '["machçôwr"]', '["and/ lack/ your","and/ poverti<es>/ your"]', '["n-m"]', 'deficiency; hence, impoverishment lack, need, penury, poor, poverty, want.', 'or מַחְסֹר; from 2637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4043}\/[H1598]', 'inflected', 'heb', 'מָגֵן', '["mâgên"]', '["a shield","shield"]', '["n-m"]', 'a shield (i.e. the small one or buckler); figuratively, a protector; also the scaly hide of the crocodile × armed, buckler, defence, ruler, scale, shield.', 'also (in plural) feminine מְגִנָּה; from 1598;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4448B}/[H4448]', 'lemma', 'heb', 'מָלַל', '["mâlal"]', '["[he is] scraping"]', '["v"]', 'to speak (mostly poetical) or say say, speak, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4079}/[H4066]', 'lemma', 'heb', 'מִדְיָן', '["midyân"]', '["[the] contentions of","contentions"]', '["n-m"]', 'brawling, contention(-ous).', 'a variation for 4066');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0343}/H9023/[H181]', 'inflected', 'heb', 'אֵיד', '["ʼêyd"]', '["disaster/ his"]', '["n-m"]', 'oppression; by implication misfortune, ruin calamity, destruction.', 'from the same as 181 (in the sense of bending down);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6621>', 'opaque', 'heb', 'פֶּתַע', '["pethaʻ"]', '["an instant","suddenly"]', '["n-m"]', 'a wink, i.e. moment (used only [with or without preposition] adverbially, quickly or unexpectedly) at an instant, suddenly, × very.', 'from an unused root meaning to open (the eyes); (compare 6597)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4832}\/[H7495]', 'inflected', 'heb', 'מַרְפֵּא', '["marpêʼ"]', '["[will be] healing"]', '["n-m"]', 'properly, curative, i.e. literally (concretely) a medicine, or (abstractly) a cure; figuratively (concretely) deliverance, or (abstractly) placidity (in-)cure(-able), healing(-lth), remedy, sound, wholesome, yielding.', 'from 7495;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4090}/[H4066]', 'lemma', 'heb', 'מְדָן', '["mᵉdân"]', '["contentions"]', '["n-m"]', 'discord, strife.', 'a form of 4066');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0251G}\/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["brothers"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6029}/H9038/[H6029]', 'inflected', 'heb', 'עָנַד', '["ʻânad"]', '["tie/ them"]', '["v"]', 'to lace fast bind, tie.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7901G}/H9041/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["when/ lying down/ you"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6974}/[H3364]', 'inflected', 'heb', 'קוּץ', '["qûwts"]', '["and/ he awakes","and/ you will awake"]', '["v"]', 'to awake (literally or figuratively) arise, (be) (a-) wake, watch.', 'a primitive root (identical with through the idea of abruptness in starting up from sleep (compare 3364));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7878}/H9031/[H7878]', 'inflected', 'heb', 'שִׂיחַ', '["sîyach"]', '["it will speak to/ you"]', '["v"]', 'to ponder, i.e. (by implication) converse (with oneself, and hence, aloud) or (transitively) utter commune, complain, declare, meditate, muse, pray, speak, talk (with).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2513B}/[H2506]', 'inflected', 'heb', 'חֶלְקָה', '["chelqâh"]', '["from/ smoothness of"]', '["n-f"]', 'properly, smoothness; figuratively, flattery; also an allotment field, flattering(-ry), ground, parcel, part, piece of land (ground), plat, portion, slippery place, smooth (thing).', 'feminine of 2506;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6079}/H9024/[H5774]', 'inflected', 'heb', 'עַפְעַף', '["ʻaphʻaph"]', '["with/ eyelids/ her"]', '["n-m"]', 'an eyelash (as fluttering); figuratively, morning ray dawning, eye-lid.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6679A}\/[H6718]', 'inflected', 'heb', 'צוּד', '["tsûwd"]', '["she hunts"]', '["v"]', 'to lie alongside (i.e. in wait); by implication, to catch an animal (figuratively, men); to victual (for a journey) chase, hunt, sore, take (provision).', 'a primitive root; also denominative from 6718');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H2846}/[H2846]', 'inflected', 'heb', 'חָתָה', '["châthâh"]', '["¿/ will he snatch up"]', '["v"]', 'to lay hold of; especially to pick up fire heap, take (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2436I>/H9023', 'inflected', 'heb', 'בחיקו', '["be./chei.K/o"]', '["in/ bosom/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1513>', 'inflected', 'heb', 'הגחלים', '["ha./ge.cha.Lim"]', '["<the>/ burning coals"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3554}/[H3554]', 'lemma', 'heb', 'כָּוָה', '["kâvâh"]', '["will they be scorched","you will be burned"]', '["v"]', 'properly, to prick or penetrate; hence, to blister (as smarting or eating into) burn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0936}/[H936]', 'lemma', 'heb', 'בּוּז', '["bûwz"]', '["[one who] despises","certainly <to despise>","has he despised","he will despise","people despise","people will despise","you despise"]', '["v"]', 'to disrespect contemn, despise, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1590}/[H1589]', 'inflected', 'heb', 'גַּנָּב', '["gannâb"]', '["<to> the/ thief"]', '["n-m"]', 'a stealer thief.', 'from 1589;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7036}/[H7034]', 'inflected', 'heb', 'קָלוֹן', '["qâlôwn"]', '["and/ shame"]', '["n-m"]', 'disgrace; (by implication) the pudenda confusion, dishonour, ignominy, reproach, shame.', 'from 7034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2781}/H9023/[H2778]', 'inflected', 'heb', 'חֶרְפָּה', '["cherpâh"]', '["and/ reproach/ his"]', '["n-f"]', 'contumely, disgrace, the pudenda rebuke, reproach(-fully), shame.', 'from 2778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7810}\/[H7809]', 'inflected', 'heb', 'שַׁחַד', '["shachad"]', '["a bribe"]', '["n-m"]', 'a donation (venal or redemptive) bribe(-ry), gift, present, reward.', 'from 7809;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4129}/[H3045]', 'inflected', 'heb', 'מוֹדַע', '["môwdaʻ"]', '["and/ a relative"]', '["n-m"]', 'an acquaintance kinswoman.', 'or rather מֹדָע; from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0822>/H9020', 'opaque', 'heb', 'אֶשְׁנָב', '["ʼeshnâb"]', '["lattice/ my"]', '["n-m"]', 'a latticed window casement, lattice.', 'apparently from an unused root (probably meaning to leave interstices);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6612A}/[H6601]', 'inflected', 'heb', 'פְּתִי', '["pᵉthîy"]', '["among the/ naive people"]', '["a n-f"]', 'silly (i.e. seducible) foolish, simple(-icity, one).', 'or פֶּתִי; or פְּתָאִי; from 6601;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7784}/[H7783]', 'inflected', 'heb', 'שׁוּק', '["shûwq"]', '["in the/ street","in the/ streets","on the/ street"]', '["n-m"]', 'a street (as run over) street.', 'from 7783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0380}/[H376]', 'inflected', 'heb', 'אִישׁוֹן', '["ʼîyshôwn"]', '["in/ [the] middle of","in/ a time of"]', '["n-m"]', 'the little man of the eye; the pupil or ball; hence, the middle (of night) apple (of the eye), black, obscure.', 'diminutive from 376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0653}/[H651]', 'inflected', 'heb', 'אֲפֵלָה', '["ʼăphêlâh"]', '["and/ darkness","and/ gloom"]', '["n-f"]', 'duskiness, figuratively, misfortune; concrete, concealment dark, darkness, gloominess, × thick.', 'feminine of 651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5637}/[H5637]', 'inflected', 'heb', 'סָרַר', '["çârar"]', '["and/ rebellious"]', '["v"]', 'to turn away, i.e. (morally) be refractory × away, backsliding, rebellious, revolter(-ing), slide back, stubborn, withdrew.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1004B}/H9024/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["in/ house/ her"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0681}/[H680]', 'inflected', 'heb', 'אֵצֶל', '["ʼêtsel"]', '["and/ beside"]', '["n-m"]', 'a side; (as a preposition) near at, (hard) by, (from) (beside), near (unto), toward, with. See also 1018.', 'from 680 (in the sense of joining);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7836}/[H7836]', 'inflected', 'heb', 'שָׁחַר', '["shâchar"]', '["to/ seek"]', '["v"]', 'properly, to dawn, i.e. (figuratively) be (up) early at any task (with the implication of earnestness); by extension, to search for (with painstaking) (do something) betimes, enquire early, rise (seek) betimes, seek diligently) early, in the morning).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4765}/[H7234]', 'lemma', 'heb', 'מַרְבַד', '["marbad"]', '["coverings"]', '["n-m"]', 'a coverlet covering of tapestry.', 'from 7234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7234}/[H7234]', 'lemma', 'heb', 'רָבַד', '["râbad"]', '["I have spread"]', '["v"]', 'to spread deck.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2405}/[H2404]', 'lemma', 'heb', 'חֲטֻבָה', '["chăṭubâh"]', '["colored fabrics"]', '["n-f"]', 'properly, a carving; hence, a tapestry (as figured) carved.', 'feminine passive participle of 2404;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0330>', 'opaque', 'heb', 'אֵטוּן', '["ʼêṭûwn"]', '["linen of"]', '["n-m"]', 'properly, twisted (yarn), i.e. tapestry fine linen.', 'from an unused root (probably meaning to bind);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0174>', 'opaque', 'heb', 'אֲהָלִים', '["ʼăhâlîym"]', '["aloes"]', '["n-m"]', 'aloe wood (i.e. sticks) (tree of lign-) aloes.', 'or (feminine) אֲהָלוֹת (only used thus in the plural); of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1730H>', 'opaque', 'heb', 'דּוֹד', '["dôwd"]', '["love<s>"]', '["n-m"]', '(figuratively) to love; by implication, a love-token, lover, friend; specifically an uncle (well-) beloved, father''s brother, love, uncle.', 'or (shortened) דֹּד; from an unused root meaning properly, to boil, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0159}/[H156]', 'inflected', 'heb', 'אֹהַב', '["ʼôhab"]', '["with/ love<s>"]', '["n-m"]', 'love.', 'from 156; meaning the same as 158');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3677}/[H3680]', 'inflected', 'heb', 'כֶּסֶא', '["keçeʼ"]', '["the/ full moon"]', '["n-m"]', 'properly, fulness or the full moon, i.e. its festival (time) appointed.', 'or כֶּסֶה; apparently from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5186}/H9033/[H5186]', 'inflected', 'heb', 'נָטָה', '["nâṭâh"]', '["he turns/ it","it has turned aside/ him","she turns/ him"]', '["v"]', 'to stretch or spread out; by implication, to bend away (including moral deflection); used in a great variety of application (as follows) afternoon, apply, bow (down, -ing), carry aside, decline, deliver, extend, go down, be gone, incline, intend, lay, let down, offer, outstretched, overthrown, pervert, pitch, prolong, put away, shew, spread (out), stretch (forth, out), take (aside), turn (aside, away), wrest, cause to yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3948}/H9024/[H3947]', 'inflected', 'heb', 'לֶקַח', '["leqach"]', '["persuasiveness/ her"]', '["n-m"]', 'properly, something received, i.e. (mentally) instruction (whether on the part of the teacher or hearer); also (in an active and sinister sense) inveiglement doctrine, learning, fair speech.', 'from 3947;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2506B}/[H2505]', 'inflected', 'heb', 'חֵלֶק', '["chêleq"]', '["with/ [the] seductiveness of"]', '["n-m"]', 'properly, smoothness (of the tongue); also an allotment flattery, inheritance, part, × partake, portion.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8193H}/H9024/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["lips/ her"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7794}/[H7788]', 'inflected', 'heb', 'שׁוֹר', '["shôwr"]', '["like/ an ox"]', '["n-m"]', 'a bullock (as a traveller) bull(-ock), cow, ox, wall (by mistake for 7791).', 'from 7788;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H5914}/[H5913]', 'inflected', 'heb', 'עֶכֶס', '["ʻekeç"]', '["and/ like/ an anklet"]', '["n-m"]', 'a fetter; hence, an anklet stocks, tinkling ornament.', 'from 5913;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3516}/H9023/[H3515]', 'inflected', 'heb', 'כָּבֵד', '["kâbêd"]', '["liver/ his"]', '["n-f"]', 'the liver (as the heaviest of the viscera) liver.', 'the same as 3515;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4116A}/[H4116]', 'inflected', 'heb', 'מָהַר', '["mâhar"]', '["as/ hurries"]', '["v"]', 'properly, to be liquid or flow easily, i.e. (by implication); to hurry (in a good or a bad sense); often used (with another verb) adverbially, promptly be carried headlong, fearful, (cause to make, in, make) haste(-n, -ily), (be) hasty, (fetch, make ready) × quickly, rash, × shortly, (be so) × soon, make speed, × speedily, × straightway, × suddenly, swift.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H5410B>/H9024', 'inflected', 'heb', 'בנתיבותיה', '["bi/n.ti.vo.Tei./ha"]', '["in/ pathways/ her"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2026}/H9024/[H2026]', 'inflected', 'heb', 'הָרַג', '["hârag"]', '["killed [men]/ her"]', '["v"]', 'to smite with deadly intent destroy, out of hand, kill, murder(-er), put to (death), make (slaughter), slay(-er), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4194}\/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["death"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6963A>/H9020', 'inflected', 'heb', 'וקולי', '["ve./ko.L/i"]', '["and/ voice/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4669}/[H6605]', 'inflected', 'heb', 'מִפְתָּח', '["miphtâch"]', '["and/ [the] utterance of"]', '["n-m"]', 'an aperture, i.e. (figuratively) utterance opening.', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8441}/[H8581]', 'inflected', 'heb', 'תּוֹעֵבַה', '["tôwʻêbah"]', '["and/ [is] an abomination","and/ [is] an abomination of","and/ an abomination"]', '["n-f"]', 'properly, something disgusting (morally), i.e. (as noun) an abhorrence; especially idolatry or (concretely) an idol abominable (custom, thing), abomination.', 'or תֹּעֵבַה; feminine active participle of 8581;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6141}/[H6140]', 'inflected', 'heb', 'עִקֵּשׁ', '["ʻiqqêsh"]', '["and/ a distorted [thing]"]', '["a"]', 'distorted; hence, false crooked, froward, perverse.', 'from 6140;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5228}/[H5226]', 'lemma', 'heb', 'נָכֹחַ', '["nâkôach"]', '["[are] right","right"]', '["a"]', 'straightforward, i.e. (figuratively), equitable, correct, or (abstractly), integrity plain, right, uprightness.', 'from the same as 5226;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4148H}/H9020/[H3256]', 'inflected', 'heb', 'מוּסָר', '["mûwçâr"]', '["discipline/ my"]', '["n-m"]', 'properly, chastisement; figuratively, reproof, warning or instruction; also restraint bond, chastening(-eth), chastisement, check, correction, discipline, doctrine, instruction, rebuke.', 'from 3256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2742D}/[H2782]', 'inflected', 'heb', 'חֲרוּץ', '["chărûwts"]', '["more than/ gold"]', '["a"]', 'properly, incised or (active) incisive; hence (as noun masculine or feminine) a trench (as dug), gold (as mined), a threshing-sledge (having sharp teeth); (figuratively) determination; also eager decision, diligent, (fine) gold, pointed things, sharp, threshing instrument, wall.', 'or חָרֻץ; passive participle of 2782;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1344}/[H1342]', 'lemma', 'heb', 'גֵּאָה', '["gêʼâh"]', '["pride"]', '["n-f"]', 'arrogance pride.', 'feminine from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1347}/[H1342]', 'inflected', 'heb', 'גָּאוֹן', '["gâʼôwn"]', '["and/ arrogance"]', '["n-m"]', 'the same as 1346 arrogancy, excellency(-lent), majesty, pomp, pride, proud, swelling.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6310I}/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["and/ a mouth of"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5081H}/[H5068]', 'inflected', 'heb', 'נָדִיב', '["nâdîyb"]', '["and/ a noble [person]","and/ noble [people]"]', '["a"]', 'properly, voluntary, i.e. generous; hence, magnanimous; as noun, a grandee (sometimes a tyrant) free, liberal (things), noble, prince, willing (hearted).', 'from 5068;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7836}/H9030/[H7836]', 'inflected', 'heb', 'שָׁחַר', '["shâchar"]', '["and/ [those who] earnestly seek/ me"]', '["v"]', 'properly, to dawn, i.e. (figuratively) be (up) early at any task (with the implication of earnestness); by extension, to search for (with painstaking) (do something) betimes, enquire early, rise (seek) betimes, seek diligently) early, in the morning).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6276}/[H6275]', 'lemma', 'heb', 'עָתֵק', '["ʻâthêq"]', '["enduring"]', '["a"]', 'antique, i.e. valued durable.', 'from 6275;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6529}/H9020/[H6509]', 'inflected', 'heb', 'פְּרִי', '["pᵉrîy"]', '["fruit/ my"]', '["n-m"]', 'fruit (literally or figuratively) bough, (first-)fruit(-ful), reward.', 'from 6509;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8393}/H9020/[H935]', 'inflected', 'heb', 'תְּבוּאָה', '["tᵉbûwʼâh"]', '["and/ gain/ my"]', '["n-f"]', 'income, i.e. produce (literally or figuratively) fruit, gain, increase, revenue.', 'from 935;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3701G}/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["from/ silver","more than/ silver"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0214}/H9028/[H686]', 'inflected', 'heb', 'אוֹצָר', '["ʼôwtsâr"]', '["and/ treasuries/ their"]', '["n-m"]', 'a depository armory, cellar, garner, store(-house), treasure(-house) (-y).', 'from 686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4390}\/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["I fill"]', '["v"]', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly.', 'or מָלָא; (Esther 7:5), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7069}/H9030/[H7069]', 'inflected', 'heb', 'קָנָה', '["qânâh"]', '["he created/ me","he sold/ me"]', '["v"]', 'to erect, i.e. create; by extension, to procure, especially by purchase (causatively, sell); by implication to own attain, buy(-er), teach to keep cattle, get, provoke to jealousy, possess(-or), purchase, recover, redeem, × surely, × verily.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4659A}/H9023/[H6466]', 'inflected', 'heb', 'מִפְעָל', '["miphʻâl"]', '["works/ his"]', '["n-m"]', 'a performance work.', 'or (feminine) מִפְעָלָה; from 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H7218J>', 'inflected', 'heb', 'מראש', '["me./Rosh","me./roSh"]', '["from/ [the] beginning","from/ beginning"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3513I}/[H3513]', 'lemma', 'heb', 'כָּבַד', '["kâbad"]', '["abounding of"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7218J>', 'inflected', 'heb', 'וראש', '["ve./Rosh"]', '["and/ [the] first of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3559H}/H9043/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["when/ established/ he"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2710}/H9043/[H2710]', 'inflected', 'heb', 'חָקַק', '["châqaq"]', '["when/ marked out/ he"]', '["v"]', 'properly, to hack, i.e. engrave (Judges 5:14, to be a scribe simply); by implication, to enact (laws being cut in stone or metal tablets in primitive times) or (gen.) prescribe appoint, decree, governor, grave, lawgiver, note, pourtray, print, set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2329}/[H2328]', 'lemma', 'heb', 'חוּג', '["chûwg"]', '["[the] circle of","a circle"]', '["n-m"]', 'a circle circle, circuit, compass.', 'from 2328;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0553}/H9043/[H553]', 'inflected', 'heb', 'אָמַץ', '["ʼâmats"]', '["when/ made firm/ he"]', '["v"]', 'to be alert, physically (on foot) or mentally (in courage) confirm, be courageous (of good courage, stedfastly minded, strong, stronger), establish, fortify, harden, increase, prevail, strengthen (self), make strong (obstinate, speed).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5810}/[H5810]', 'inflected', 'heb', 'עָזַז', '["ʻâzaz"]', '["when/ became strong"]', '["v"]', 'to be stout (literally or figuratively) harden, impudent, prevail, strengthen (self), be strong.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7760L}/H9043/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["when/ set/ he"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0525}/[H539]', 'lemma', 'heb', 'אָמוֹן', '["ʼâmôwn"]', '["an artisan"]', '["n-m"]', 'skilled, i.e. an architect one brought up.', 'from 539, probably in the sense of training; like 542');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8191}/[H8173]', 'lemma', 'heb', 'שַׁעְשֻׁעַ', '["shaʻshuaʻ"]', '["delight<s>"]', '["n-m"]', 'enjoyment delight, pleasure.', 'from 8173;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8398}/[H2986]', 'inflected', 'heb', 'תֵּבֵל', '["têbêl"]', '["in/ [the] world of"]', '["n-f"]', 'the earth (as moist and therefore inhabited); by extension, the globe; by implication, its inhabitants; specifically, a particular land, as Babylonia, Palestine habitable part, world.', 'from 2986;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8191}/H9020/[H8173]', 'inflected', 'heb', 'שַׁעְשֻׁעַ', '["shaʻshuaʻ"]', '["and/ delight<s>/ my"]', '["n-m"]', 'enjoyment delight, pleasure.', 'from 8173;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0120G}\/[H119]', 'inflected', 'heb', 'אָדָם', '["ʼâdâm"]', '["anyone","humankind"]', '["n-m"]', 'ruddy i.e. a human being (an individual or the species, mankind, etc.) × another, hypocrite, common sort, × low, man (mean, of low degree), person.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8245}/[H8245]', 'inflected', 'heb', 'שָׁקַד', '["shâqad"]', '["by/ keeping watch"]', '["v"]', 'to be alert, i.e. sleepless; hence to be on the lookout (whether for good or ill) hasten, remain, wake, watch (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8104I}/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["by/ watching","to/ keep"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6607}/H9020/[H6605]', 'inflected', 'heb', 'פֶּתַח', '["pethach"]', '["doorways/ my"]', '["n-m"]', 'an opening (literally), i.e. door (gate) or entrance way door, entering (in), entrance (-ry), gate, opening, place.', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6329}/[H6328]', 'inflected', 'heb', 'פּוּק', '["pûwq"]', '["and/ he obtained"]', '["v"]', 'to issue, i.e. furnish; causatively, to secure; figuratively, to succeed afford, draw out, further, get, obtain.', 'a primitive root [rather identical with 6328 through the idea of dropping out; compare 5312];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2398}/H9030/[H2398]', 'inflected', 'heb', 'חָטָא', '["châṭâʼ"]', '["and/ [one who] misses/ me"]', '["v"]', 'properly, to miss; hence (figuratively and generally) to sin; by inference, to forfeit, lack, expiate, repent, (causatively) lead astray, condemn bear the blame, cleanse, commit (sin), by fault, harm he hath done, loss, miss, (make) offend(-er), offer for sin, purge, purify (self), make reconciliation, (cause, make) sin(-ful, -ness), trespass.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2874}/H9024/[H2873]', 'inflected', 'heb', 'טֶבַח', '["ṭebach"]', '["slaughtering/ her"]', '["n-m"]', 'properly, something slaughtered; hence, a beast (or meat, as butchered); abstractly butchery (or concretely, a place of slaughter) × beast, slaughter, × slay, × sore.', 'from 2873;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3196>/H9024', 'opaque', 'heb', 'יַיִן', '["yayin"]', '["wine/ her"]', '["n-m"]', 'wine (as fermented); by implication, intoxication banqueting, wine, wine(-bibber).', 'from an unused root meaning to effervesce;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7979}/H9024/[H7971]', 'inflected', 'heb', 'שֻׁלְחָן', '["shulchân"]', '["table/ her"]', '["n-m"]', 'a table (as spread out); by implication, a meal table.', 'from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1610>', 'opaque', 'heb', 'גַּף', '["gaph"]', '["[the] elevations of"]', '["n-m"]', 'the back; by extension the body or self highest places, himself.', 'from an unused root meaning to arch;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3899H}/H9020/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["in/ food/ my"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0833}/[H833]', 'inflected', 'heb', 'אָשַׁר', '["ʼâshar"]', '["and/ advance","and/ guide"]', '["v"]', 'to be straight (used in the widest sense, especially to be level, right, happy); figuratively, to go forward, be honest, prosper (call, be) bless(-ed, happy), go, guide, lead, relieve.', 'or אָשֵׁר; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3971B>/H9023', 'opaque', 'heb', 'מאוּם', '["mʼûwm"]', '["defect/ his"]', '["n-m"]', 'a blemish (physically or morally) blemish, blot, spot.', 'usually מוּם; as if passive participle from an unused root probably meaning to stain');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0157G}/H9031/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["and/ he will love/ you"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3948}\/[H3947]', 'inflected', 'heb', 'לֶקַח', '["leqach"]', '["insight"]', '["n-m"]', 'properly, something received, i.e. (mentally) instruction (whether on the part of the teacher or hearer); also (in an active and sinister sense) inveiglement doctrine, learning, fair speech.', 'from 3947;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8462}/[H2490]', 'lemma', 'heb', 'תְּחִלָּה', '["tᵉchillâh"]', '["[is the] beginning of","[the] beginning","[the] beginning of"]', '["n-f"]', 'a commencement; relatively original (adverb, -ly) begin(-ning), first (time).', 'from 2490 in the sense of opening;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3887}/[H3887]', 'inflected', 'heb', 'לוּץ', '["lûwts"]', '["and/ you mock"]', '["v"]', 'properly, to make mouths at, i.e. to scoff; hence (from the effort to pronounce a foreign language) to interpret, or (generally) intercede ambassador, have in derision, interpreter, make a mock, mocker, scorn(-er, -ful), teacher.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3687}/[H3684]', 'lemma', 'heb', 'כְּסִילוּת', '["kᵉçîylûwth"]', '["folly"]', '["n-f"]', 'silliness foolish.', 'from 3684;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6615}/[H6612]', 'lemma', 'heb', 'פְּתַיּוּת', '["pᵉthayûwth"]', '["naivete"]', '["n-f"]', 'silliness (i.e. seducibility) simple.', 'from 6612;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3678I}/[H3680]', 'lemma', 'heb', 'כִּסֵּא', '["kiççêʼ"]', '["a seat"]', '["n-m"]', 'properly, covered, i.e. a throne (as canopied) seat, stool, throne.', 'or כִּסֵּה; from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3474}/[H3474]', 'inflected', 'heb', 'יָשַׁר', '["yâshar"]', '["those/ [who] make straight"]', '["v"]', 'to be straight or even; figuratively, to be (causatively, to make) right, pleasant, prosperous direct, fit, seem good (meet), please (will), be (esteem, go) right (on), bring (look, make, take the) straight (way), be upright(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6012}/[H6009]', 'inflected', 'heb', 'עָמֵק', '["ʻâmêq"]', '["[are] in/ [the] depths of"]', '["a"]', 'deep (literally or figuratively) deeper, depth, strange.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7121G}/H9024\/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["invited [ones]/ her"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8424}/[H3013]', 'lemma', 'heb', 'תּוּגָה', '["tûwgâh"]', '["[is] [the] grief of","[may be] grief"]', '["n-f"]', 'depression (of spirits); concretely a grief heaviness, sorrow.', 'from 3013;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1942}/[H1933]', 'inflected', 'heb', 'הַוָּה', '["havvâh"]', '["and/ [the] craving of"]', '["n-f"]', 'by implication, of falling); desire; also ruin calamity, iniquity, mischief, mischievous (thing), naughtiness, naughty, noisome, perverse thing, substance, very wickedness.', 'from 1933 (in the sense of eagerly coveting and rushing upon;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1920}/[H1920]', 'lemma', 'heb', 'הָדַף', '["hâdaph"]', '["he rejects","you push"]', '["v"]', 'to push away or down cast away (out), drive, expel, thrust (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7423B}/[H7411]', 'lemma', 'heb', 'רְמִיָּה', '["rᵉmîyâh"]', '["idleness","laxness","slackness"]', '["n-f"]', 'remissness, treachery deceit(-ful, -fully), false, guile, idle, slack, slothful.', 'from 7411;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7537}/[H7537]', 'lemma', 'heb', 'רָקַב', '["râqab"]', '["it will rot"]', '["v"]', 'to decay (as by worm-eating) rot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0191>', 'inflected', 'heb', 'ואוילים', '["ve./''e.Vil","ve./''e.vi.Lim"]', '["and/ a fool of","and/ fools"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3832}/[H3832]', 'lemma', 'heb', 'לָבַט', '["lâbaṭ"]', '["he will be ruined","it will be ruined"]', '["v"]', 'to overthrow; intransposed, to fall fall.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6140}/[H6140]', 'inflected', 'heb', 'עָקַשׁ', '["ʻâqash"]', '["and/ [one who] is crooked of","and/ [one who] perverts"]', '["v"]', 'to knot or distort; figuratively, to pervert (act or declare perverse) make crooked, (prove, that is) perverse(-rt).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6094}/[H6087]', 'lemma', 'heb', 'עַצֶּבֶת', '["ʻatstsebeth"]', '["sorrow"]', '["n-f"]', 'a idol; also, a pain or wound sorrow, wound.', 'from 6087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7626G>', 'inflected', 'heb', 'ושבט', '["ve./She.vet"]', '["and/ [the] rod of","and/ [the] scepter of","and/ a rod"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1460A}/[H1342]', 'inflected', 'heb', 'גֵּו', '["gêv"]', '["[is] for/ [the] back of","for/ [the] back of"]', '["n-m"]', 'the back; by analogy, the middle among, back, body.', 'from 1342 (corresponding to 1354);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7389A}/H9028/[H7326]', 'inflected', 'heb', 'רֵישׁ', '["rêysh"]', '["poverty/ their"]', '["n-m"]', 'poverty poverty.', 'or רֵאשׁ; or רִישׁ; from 7326;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5800H}/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["and/ [one who] neglects"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3318O}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ [one who] spreads"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2820}/[H2821]', 'inflected', 'heb', 'חָשַׂךְ', '["châsak"]', '["and/ [one who] restrains","and/ [one who] withholds"]', '["v"]', 'to restrain or (reflex.) refrain; by implication, to refuse, spare, preserve; to observe assuage, × darken, forbear, hinder, hold back, keep (back), punish, refrain, reserve, spare, withhold.', 'a primitive root; also interchangeable with 2821');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2638}/[H2637]', 'inflected', 'heb', 'חָסֵר', '["châçêr"]', '["by/ lack of"]', '["a"]', 'lacking; hence, without destitute, fail, lack, have need, void, want.', 'from 2637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6089A}/[H6087]', 'lemma', 'heb', 'עֶצֶב', '["ʻetseb"]', '["hard labor","hurt","sorrow"]', '["n-m"]', 'an earthen vessel; usually (painful) toil; also a pang (whether of body or mind) grievous, idol, labor, sorrow.', 'from 6087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7814}/[H7832]', 'inflected', 'heb', 'שְׂחוֹק', '["sᵉchôwq"]', '["[is] like/ sport"]', '["n-m"]', 'laughter (in merriment or defiance) derision, laughter(-ed to scorn, -ing), mocked, sport.', 'or שְׂחֹק; from 7832;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3684}/[H3688]', 'inflected', 'heb', 'כְּסִיל', '["kᵉçîyl"]', '["[belongs] to/ a fool","for/ a fool","to/ a fool"]', '["n-m"]', 'properly, fat, i.e. (figuratively) stupid or silly fool(-ish).', 'from 3688;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4034}/[H4032]', 'lemma', 'heb', 'מְגוֹרַה', '["mᵉgôwrah"]', '["[the] fear of"]', '["n-f"]', 'affright fear.', 'feminine of 4032;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8378}/[H183]', 'inflected', 'heb', 'תַּאֲוָה', '["taʼăvâh"]', '["and/ [the] desire of"]', '["n-f"]', 'a longing; by implication, a delight (subjectively, satisfaction, objectively, a charm) dainty, desire, × exceedingly, × greedily, lust(ing), pleasant. See also 6914.', 'from 183 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2558}/[H2556]', 'inflected', 'heb', 'חֹמֶץ', '["chômets"]', '["like <the>/ vinegar"]', '["n-m"]', 'vinegar vinegar.', 'from 2556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8127G}/[H8150]', 'inflected', 'heb', 'שֵׁן', '["shên"]', '["to the/ teeth"]', '["n-f"]', 'a tooth (as sharp); specifically ivory; figuratively, a cliff crag, × forefront, ivory, × sharp, tooth.', 'from 8150; compare 8143');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H6227}/[H6225]', 'inflected', 'heb', 'עָשָׁן', '["ʻâshân"]', '["and/ like <the>/ smoke","and/ like/ smoke"]', '["n-m"]', 'smoke, literally or figuratively (vapor, dust, anger) smoke(-ing).', 'from 6225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6102}/[H6101]', 'inflected', 'heb', 'עָצֵל', '["ʻâtsêl"]', '["the/ sluggard"]', '["a"]', 'indolent slothful, sluggard.', 'from 6101;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8431}/[H3176]', 'lemma', 'heb', 'תּוֹחֶלֶת', '["tôwcheleth"]', '["[the] hope of","hope"]', '["n-f"]', 'expectation hope.', 'from 3176;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8537}/[H8552]', 'inflected', 'heb', 'תֹּם', '["tôm"]', '["for <the>/ integrity"]', '["n-m"]', 'completeness; figuratively, prosperity; usually (morally) innocence full, integrity, perfect(-ion), simplicity, upright(-ly, -ness), at a venture. See 8550.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4288}/[H2846]', 'inflected', 'heb', 'מְחִתָּה', '["mᵉchittâh"]', '["and/ destruction","and/ terror"]', '["n-f"]', 'properly, a dissolution; concretely, a ruin, or (abstractly) consternation destruction, dismaying, ruin, terror.', 'from 2846;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3956G}/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["and/ [the] tongue of","and/ a tongue","and/ a tongue of"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2087}/[H2102]', 'lemma', 'heb', 'זָדוֹן', '["zâdôwn"]', '["O arrogance","[the] arrogance of","[the] presumption of","arrogance","pride"]', '["n-m"]', 'arrogance presumptuously, pride, proud (man).', 'from 2102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6800B}/[H6800]', 'lemma', 'heb', 'צָנַע', '["tsânaʻ"]', '["modest [people]"]', '["v"]', 'to humiliate humbly, lowly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8538}/[H8537]', 'lemma', 'heb', 'תֻּמָּה', '["tummâh"]', '["[the] integrity of"]', '["n-f"]', 'innocence integrity.', 'feminine of 8537;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5558}/[H5557]', 'inflected', 'heb', 'סֶלֶף', '["çeleph"]', '["and/ [the] crookedness of","and/ perverseness"]', '["n-m"]', 'distortion, i.e. (figuratively) viciousness perverseness.', 'from 5557;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7703}/H9038/[H7703]', 'inflected', 'heb', 'שָׁדַד', '["shâdad"]', '["it destroys/ them","it will devastate/ them"]', '["v"]', 'properly, to be burly, i.e. (figuratively) powerful (passively, impregnable); by implication, to ravage dead, destroy(-er), oppress, robber, spoil(-er), × utterly, (lay) waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7564}/H9023/[H7562]', 'inflected', 'heb', 'רִשְׁעָה', '["rishʻâh"]', '["and/ by/ wickedness/ his"]', '["n-f"]', 'wrong (especially moral) fault, wickedly(-ness).', 'feminine of 7562;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1942}/[H1933]', 'inflected', 'heb', 'הַוָּה', '["havvâh"]', '["and/ by/ [the] craving of"]', '["n-f"]', 'by implication, of falling); desire; also ruin calamity, iniquity, mischief, mischievous (thing), naughtiness, naughty, noisome, perverse thing, substance, very wickedness.', 'from 1933 (in the sense of eagerly coveting and rushing upon;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8431}/[H3176]', 'inflected', 'heb', 'תּוֹחֶלֶת', '["tôwcheleth"]', '["and/ [the] hope of"]', '["n-f"]', 'expectation hope.', 'from 3176;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0006}/[H6]', 'inflected', 'heb', 'אָבַד', '["ʼâbad"]', '["and/ when/ perish"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6310G}/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["and/ by/ [the] mouth of"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8668H}/[H7768]', 'inflected', 'heb', 'תְּשׁוּעָה', '["tᵉshûwʻâh"]', '["and/ victory"]', '["n-f"]', 'rescue (literal or figurative, persons, national or spiritual) deliverance, help, safety, salvation, victory.', 'or תְּשֻׁעָה; from 7768 in the sense of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5916}/[H5916]', 'inflected', 'heb', 'עָכַר', '["ʻâkar"]', '["and/ [is] troubling"]', '["v"]', 'properly, to roil water; figuratively, to disturb or affict trouble, stir.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0394}/[H393]', 'lemma', 'heb', 'אַכְזָרִי', '["ʼakzârîy"]', '["[is] cruel","[will be] cruel","a cruel [day]","a cruel [one]","a cruel [person]","cruel"]', '["a"]', 'terrible cruel (one).', 'from 393;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7938}/[H7936]', 'lemma', 'heb', 'שֶׂכֶר', '["seker"]', '["wage[s]","wage[s] of"]', '["n-m"]', 'wages reward, sluices.', 'from 7936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4194}/H9023/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["[is] to/ own death/ his"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7522}/H9023/[H7521]', 'inflected', 'heb', 'רָצוֹן', '["râtsôwn"]', '["and/ [are] pleasure/ his","and/ favor/ his"]', '["n-m"]', 'delight (especially as shown) (be) acceptable(-ance, -ed), delight, desire, favour, (good) pleasure, (own, self, voluntary) will, as...(what) would.', 'or רָצֹן; from 7521;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3027V}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["to/ hand"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0639H}/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["in/ [the] nose of"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3476}/[H3474]', 'inflected', 'heb', 'יֹשֶׁר', '["yôsher"]', '["from/ uprightness"]', '["n-m"]', 'the right equity, meet, right, upright(-ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4270}/[H2637]', 'inflected', 'heb', 'מַחְסוֹר', '["machçôwr"]', '["to/ poverty"]', '["n-m"]', 'deficiency; hence, impoverishment lack, need, penury, poor, poverty, want.', 'or מַחְסֹר; from 2637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7301}/[H7301]', 'inflected', 'heb', 'רָוָה', '["râvâh"]', '["and/ [one who] gives water"]', '["v"]', 'to slake the thirst (occasionally of other appetites) bathe, make drunk, (take the) fill, satiate, (abundantly) satisfy, soak, water (abundantly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1293}/[H1288]', 'inflected', 'heb', 'בְּרָכָה', '["Bᵉrâkâh"]', '["and/ a blessing"]', '["n-f"]', 'benediction; by implication prosperity blessing, liberal, pool, present.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6239}/H9023/[H6238]', 'inflected', 'heb', 'עֹשֶׁר', '["ʻôsher"]', '["by/ wealth/ his","in/ rich[es]/ his","in/ wealth/ his"]', '["n-m"]', 'wealth × far (richer), riches.', 'from 6238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H5929}/[H5927]', 'inflected', 'heb', 'עָלֶה', '["ʻâleh"]', '["and/ like <the>/ leaf"]', '["n-m"]', 'a leaf (as coming up on a tree); collectively, foliage branch, leaf.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H7538}/[H7537]', 'inflected', 'heb', 'רָקָב', '["râqâb"]', '["and/ [is] like/ rottenness","and/ like <the>/ rottenness"]', '["n-m"]', 'decay (by caries) rottenness (thing).', 'from 7537;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7922}/H9023/[H7919]', 'inflected', 'heb', 'שֶׂכֶל', '["sekel"]', '["insight/ his","prudence/ his"]', '["n-m"]', 'intelligence; by implication, success discretion, knowledge, policy, prudence, sense, understanding, wisdom, wise.', 'or שֵׂכֶל; from 7919;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5753A}/[H5753]', 'inflected', 'heb', 'עָוָה', '["ʻâvâh"]', '["and/ a [person] perverted of"]', '["v"]', 'to crook, literally or figuratively do amiss, bow down, make crooked, commit iniquity, pervert, (do) perverse(-ly), trouble, × turn, do wickedly, do wrong.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3513G}/[H3513]', 'inflected', 'heb', 'כָּבַד', '["kâbad"]', '["more than/ [one who] honors himself"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4685B}/[H6679]', 'lemma', 'heb', 'מָצוֹד', '["mâtsôwd"]', '["[is] snares","a net of"]', '["n-m"]', 'a net (for capturing animals or fishes); a fastness or (beseiging) tower bulwark, hold, munition, net, snare.', 'or (feminine) מְצוֹדָה; or מצֹדָה; from 6679; also (by interchange for 4679)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6588}/[H6586]', 'inflected', 'heb', 'פֶּשַׁע', '["peshaʻ"]', '["[is] for/ [the] transgression of","[is] in/ [the] transgression of","by/ [the] transgression of","in/ transgression"]', '["n-m"]', 'a revolt (national, moral or religious) rebellion, sin, transgression, trespass.', 'from 6586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1576}/[H1580]', 'inflected', 'heb', 'גְּמוּל', '["gᵉmûwl"]', '["and/ [the] dealing of"]', '["n-m"]', 'treatment, i.e. an act (of good or ill); by implication, service or requital as hast served, benefit, desert, deserving, that which he hath given, recompense, reward.', 'from 1580;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6098}/[H3289]', 'inflected', 'heb', 'עֵצָה', '["ʻêtsâh"]', '["to/ advice"]', '["n-f"]', 'advice; by implication, plan; also prudence advice, advisement, counsel([-lor]), purpose.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3708A}/H9023/[H3707]', 'inflected', 'heb', 'כַּעַס', '["kaʻaç"]', '["anger/ his"]', '["n-m"]', 'vexation anger, angry, grief, indignation, provocation, provoking, × sore, sorrow, spite, wrath.', 'or (in Job) כַּעַשׂ; from 3707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3680}/[H3680]', 'inflected', 'heb', 'כָּסָה', '["kâçâh"]', '["and/ [one who] conceals","and/ they may cover themselves"]', '["v"]', 'properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4094}/[H1856]', 'inflected', 'heb', 'מַדְקָרָה', '["madqârâh"]', '["like/ thrusts of"]', '["n-f"]', 'a wound piercing.', 'from 1856;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3289}/[H3289]', 'inflected', 'heb', 'יָעַץ', '["yâʻats"]', '["and/ [belongs] to/ counselors of"]', '["v"]', 'to advise; reflexively, to deliberate or resolve advertise, take advise, advise (well), consult, (give, take) counsel(-lor), determine, devise, guide, purpose.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0200}/[H191]', 'lemma', 'heb', 'אִוֶּלֶת', '["ʼivveleth"]', '["[is] folly","[is] foolishness","[the] folly of","foolishness"]', '["n-f"]', 'silliness folly, foolishly(-ness).', 'from the same as 191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7423B}/[H7411]', 'inflected', 'heb', 'רְמִיָּה', '["rᵉmîyâh"]', '["and/ idleness"]', '["n-f"]', 'remissness, treachery deceit(-ful, -fully), false, guile, idle, slack, slothful.', 'from 7411;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1674}/[H1672]', 'lemma', 'heb', 'דְּאָגָה', '["dᵉʼâgâh"]', '["anxiety"]', '["n-f"]', 'anxiety care(-fulness), fear, heaviness, sorrow.', 'from 1672;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7812}/H9034/[H7812]', 'inflected', 'heb', 'שָׁחָה', '["shâchâh"]', '["it bows down/ it"]', '["v"]', 'to depress, i.e. prostrate (especially reflexive, in homage to royalty or God) bow (self) down, crouch, fall down (flat), humbly beseech, do (make) obeisance, do reverence, make to stoop, worship.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8055}/H9034/[H8055]', 'inflected', 'heb', 'שָׂמַח', '["sâmach"]', '["it makes glad/ it"]', '["v"]', 'probably to brighten up, i.e. (figuratively) be (causatively, make) blithe or gleesome cheer up, be (make) glad, (have, make) joy(-ful), be (make) merry, (cause to, make to) rejoice, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8582}/H9038/[H8582]', 'inflected', 'heb', 'תָּעָה', '["tâʻâh"]', '["it misleads/ them","they have caused to wander/ them"]', '["v"]', 'to vacillate, i.e. reel or stray (literally or figuratively); also causative of both (cause to) go astray, deceive, dissemble, (cause to, make to) err, pant, seduce, (make to) stagger, (cause to) wander, be out of the way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2760}/[H2760]', 'lemma', 'heb', 'חָרַךְ', '["chârak"]', '["he roasts"]', '["v"]', 'to braid (i.e. to entangle or snare) or catch (game) in a net roast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6718A}/H9023/[H6679]', 'inflected', 'heb', 'צַיִד', '["tsayid"]', '["game/ his"]', '["n-m"]', 'the chase; also game (thus taken) × catcheth, food, × hunter, (that which he took in) hunting, venison, victuals.', 'from a form of 6679 and meaning the same;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1952}/[H1951]', 'inflected', 'heb', 'הוֹן', '["hôwn"]', '["and/ [the] wealth of","and/ wealth"]', '["n-m"]', 'wealth; by implication, enough enough, for nought, riches, substance, wealth.', 'from the same as 1951 in the sense of 202;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1606}/[H1605]', 'lemma', 'heb', 'גְּעָרָה', '["gᵉʻârâh"]', '["[the] rebuke of","[the] threat of","a rebuke","a threat"]', '["n-f"]', 'a chiding rebuke(-ing), reproof.', 'from 1605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5315L}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["and/ [the] appetite of"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6589}/[H6589]', 'lemma', 'heb', 'פָּשַׂק', '["pâsaq"]', '["[one who] opens"]', '["v"]', 'to dispart (the feet or lips), i.e. become licentious open (wide).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7564}/[H7562]', 'inflected', 'heb', 'רִשְׁעָה', '["rishʻâh"]', '["and/ [the] wickedness of","and/ wickedness"]', '["n-f"]', 'wrong (especially moral) fault, wickedly(-ness).', 'feminine of 7562;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4683}/[H5327]', 'lemma', 'heb', 'מַצָּה', '["matstsâh"]', '["contention"]', '["n-f"]', 'a quarrel contention, debate, strife.', 'from 5327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6735A}/[H6696]', 'inflected', 'heb', 'צִיר', '["tsîyr"]', '["and/ an envoy","and/ an envoy of"]', '["n-m"]', 'a hinge (as pressed in turning); also a throe (as a phys. or mental pressure); also a herald or errand-doer (as constrained by the principal) ambassador, hinge, messenger, pain, pang, sorrow. Compare 6736.', 'from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7389A}/[H7326]', 'lemma', 'heb', 'רֵישׁ', '["rêysh"]', '["poverty"]', '["n-m"]', 'poverty poverty.', 'or רֵאשׁ; or רִישׁ; from 7326;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5315G}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["to the/ soul","to/ a person","to/ anyone"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6845}/[H6845]', 'inflected', 'heb', 'צָפַן', '["tsâphan"]', '["and/ [is] stored up"]', '["v"]', 'to hide (by covering over); by implication, to hoard or reserve; figuratively to deny; specifically (favorably) to protect, (unfavorably) to lurk esteem, hide(-den one, self), lay up, lurk (be set) privily, (keep) secret(-ly, place).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5215}/[H5214]', 'lemma', 'heb', 'נִיר', '["nîyr"]', '["[the] unplowed ground of","unplowed ground"]', '["n-m"]', 'properly, plowing, i.e. (concretely) freshly plowed land fallow ground, plowing, tillage.', 'or נִר; from 5214;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0157G}/H9033/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["and/ [one who] loves/ him"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7836}/H9033/[H7836]', 'inflected', 'heb', 'שָׁחַר', '["shâchar"]', '["he seeks early/ him"]', '["v"]', 'properly, to dawn, i.e. (figuratively) be (up) early at any task (with the implication of earnestness); by extension, to search for (with painstaking) (do something) betimes, enquire early, rise (seek) betimes, seek diligently) early, in the morning).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0990G>', 'inflected', 'heb', 'ובטן', '["u./Ve.ten"]', '["and/ [the] belly of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2637}\/[H2637]', 'inflected', 'heb', 'חָסֵר', '["châçêr"]', '["it is lacking"]', '["v"]', 'to lack; by implication, to fail, want, lessen be abated, bereave, decrease, (cause to) fail, (have) lack, make lower, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0200}/[H191]', 'inflected', 'heb', 'אִוֶּלֶת', '["ʼivveleth"]', '["and/ [the] foolishness of","and/ a foolish woman"]', '["n-f"]', 'silliness folly, foolishly(-ness).', 'from the same as 191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2040}/H9033/[H2040]', 'inflected', 'heb', 'הָרַס', '["hâraç"]', '["she tears down/ it"]', '["v"]', 'to pull down or in pieces, break, destroy beat down, break (down, through), destroy, overthrow, pluck down, pull down, ruin, throw down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3476}/H9023/[H3474]', 'inflected', 'heb', 'יֹשֶׁר', '["yôsher"]', '["in/ uprightness/ his"]', '["n-m"]', 'the right equity, meet, right, upright(-ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0959}/H9033/[H959]', 'inflected', 'heb', 'בָּזָה', '["bâzâh"]', '["[is] despising/ him"]', '["v"]', 'to disesteem despise, disdain, contemn(-ptible), think to scorn, vile person.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2415>', 'opaque', 'heb', 'חֹטֵר', '["chôṭêr"]', '["a shoot","a shoot of"]', '["n-m"]', 'a twig rod.', 'from an unused root of uncertain signification;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0504}/[H502]', 'lemma', 'heb', 'אֶלֶף', '["ʼeleph"]', '["[are] cattle<s>"]', '["n-m"]', 'a family; also (from the sense of yoking or taming) an ox or cow family, kine, oxen.', 'from 502;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0018}/[H75]', 'lemma', 'heb', 'אֵבוּס', '["ʼêbûwç"]', '["[the] feeding trough","[the] feeding trough of"]', '["n-m"]', 'a manger or stall crib.', 'from 75;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6315}/[H6315]', 'inflected', 'heb', 'פּוּחַ', '["pûwach"]', '["and/ he may breathe out","and/ it will pant","so/ he may breathe out"]', '["v"]', 'to puff, i.e. blow with the breath or air; hence, to fan (as a breeze), to utter, to kindle (a fire), to scoff blow (upon), break, puff, bring into a snare, speak, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4787}/[H4786]', 'lemma', 'heb', 'מׇרָּה', '["morrâh"]', '["[the] bitterness of"]', '["n-f"]', 'trouble bitterness.', 'a form of 4786;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8057}/H9023/[H8056]', 'inflected', 'heb', 'שִׂמְחָה', '["simchâh"]', '["and/ in/ joy/ its"]', '["n-f"]', 'blithesomeness or glee, (religious or festival) × exceeding(-ly), gladness, joy(-fulness), mirth, pleasure, rejoice(-ing).', 'from 8056;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7814}/[H7832]', 'inflected', 'heb', 'שְׂחוֹק', '["sᵉchôwq"]', '["in/ laughter"]', '["n-m"]', 'laughter (in merriment or defiance) derision, laughter(-ed to scorn, -ing), mocked, sport.', 'or שְׂחֹק; from 7832;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1870G}/H9023/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["from/ way/ his","from/ ways/ his","of/ ways/ his"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5921A}/H9033/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["and/ from/ with <the>/ himself"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6175}/[H6191]', 'inflected', 'heb', 'עָרוּם', '["ʻârûwm"]', '["and/ a sensible [person]","and/ sensible [people]"]', '["a"]', 'cunning (usually in a bad sense) crafty, prudent, subtil.', 'passive participle of 6191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0838A}/H9023/[H833]', 'inflected', 'heb', 'אָשֻׁר', '["ʼâshur"]', '["<to>/ step/ his"]', '["n-f"]', 'a step going, step.', 'or אַשֻּׁר; from 833 in the sense of going;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5674H}/[H5674]', 'lemma', 'heb', 'עָבַר', '["ʻâbar"]', '["[is] arrogant"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0157H}/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["and/ [those who] love"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2603A}/[H2583]', 'inflected', 'heb', 'חָנַן', '["chânan"]', '["and/ [one who] shows favor to"]', '["v"]', 'properly, to bend or stoop in kindness to an inferior; to favor, bestow; causatively to implore (i.e. move to favor by petition) beseech, × fair, (be, find, shew) favour(-able), be (deal, give, grant (gracious(-ly), intreat, (be) merciful, have (shew) mercy (on, upon), have pity upon, pray, make supplication, × very.', 'a primitive root (compare 2583);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0835}/H9043/[H833]', 'inflected', 'heb', 'אֶשֶׁר', '["ʼesher"]', '["how blessed [is]/ he"]', '["n-m"]', 'happiness; only in masculine plural construction as interjection, how happy! blessed, happy.', 'from 833;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4195}/[H3498]', 'lemma', 'heb', 'מוֹתָר', '["môwthâr"]', '["profit"]', '["n-m"]', 'literally gain; figuratively, superiority plenteousness, preeminence, profit.', 'from 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1697M}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["and/ a word of","and/ word of"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1927}/[H1926]', 'lemma', 'heb', 'הֲדָרָה', '["hădârâh"]', '["[the] glory of"]', '["n-f"]', 'decoration beauty, honour.', 'feminine of 1926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0657A}/[H656]', 'inflected', 'heb', 'אֶפֶס', '["ʼepheç"]', '["and/ by/ not","and/ in/ not"]', '["n-m"]', 'cessation, i.e. an end (especially of the earth); often used adverb, no further; also the ankle (in the dual), as being the extremity of the leg or foot ankle, but (only), end, howbeit, less than nothing, nevertheless (where), no, none (beside), not (any, -withstanding), thing of nought, save(-ing), there, uttermost part, want, without (cause).', 'from 656; (sometimes like 6466)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7333}/[H7336]', 'lemma', 'heb', 'רָזוֹן', '["râzôwn"]', '["a ruler"]', '["n-m"]', 'a dignitary prince.', 'from 7336;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7116}/[H7114]', 'inflected', 'heb', 'קָצֵר', '["qâtsêr"]', '["and/ [a person] short of"]', '["a"]', 'short (whether in size, number, life, strength or temper) few, hasty, small, soon.', 'from 7114;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7538}/[H7537]', 'inflected', 'heb', 'רָקָב', '["râqâb"]', '["and/ [is] rottenness of"]', '["n-m"]', 'decay (by caries) rottenness (thing).', 'from 7537;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7451I}/H9023/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["by/ wickedness/ his","in/ evil/ his"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2620}/[H982]', 'inflected', 'heb', 'חָסָה', '["châçâh"]', '["and/ [is] seeking refuge"]', '["v"]', 'to flee for protection; figuratively, to confide in have hope, make refuge, (put) trust.', 'a primitive root; (compare 982)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7130G}/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["and/ in/ [the] inward part[s] of"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2617B}/[H2616]', 'inflected', 'heb', 'חֶסֶד', '["cheçed"]', '["and/ [is] a shame"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5678}/H9023/[H5676]', 'inflected', 'heb', 'עֶבְרָה', '["ʻebrâh"]', '["and/ arrogance/ its","and/ fury/ his"]', '["n-f"]', 'an outburst of passion anger, rage, wrath.', 'feminine of 5676;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2633}/[H2630]', 'lemma', 'heb', 'חֹסֶן', '["chôçen"]', '["[the] wealth of","treasure","wealth","wealth of"]', '["n-m"]', 'wealth riches, strength, treasure.', 'from 2630;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8393}/[H935]', 'inflected', 'heb', 'תְּבוּאָה', '["tᵉbûwʼâh"]', '["and/ with/ [the] income of"]', '["n-f"]', 'income, i.e. produce (literally or figuratively) fruit, gain, increase, revenue.', 'from 935;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8605}/[H6419]', 'inflected', 'heb', 'תְּפִלָּה', '["tᵉphillâh"]', '["and/ [is the] prayer of","and/ [the] prayer of","and/ a prayer"]', '["n-f"]', 'intercession, supplication; by implication, a hymn prayer.', 'from 6419;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0011}/[H6]', 'inflected', 'heb', 'אֲבַדּוֹן', '["ʼăbaddôwn"]', '["and/ Abaddon"]', '["n-pr-loc"]', 'abstract, a perishing; concrete, Hades destruction.', 'intensive from 6;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6094}/[H6087]', 'inflected', 'heb', 'עַצֶּבֶת', '["ʻatstsebeth"]', '["and/ by/ sorrow of"]', '["n-f"]', 'a idol; also, a pain or wound sorrow, wound.', 'from 6087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5218B}/[H5217]', 'lemma', 'heb', 'נָכֵא', '["nâkêʼ"]', '["[is] stricken","stricken"]', '["a"]', 'smitten, i.e. (figuratively) afflicted broken, stricken, wounded.', 'or נָכָא; from 5217;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4103}/[H1949]', 'inflected', 'heb', 'מְהוּמָה', '["mᵉhûwmâh"]', '["and/ turmoil"]', '["n-f"]', 'confusion or uproar destruction, discomfiture, trouble, tumult, vexation, vexed.', 'from 1949;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0160}/[H158]', 'inflected', 'heb', 'אַהֲבָה', '["ʼahăbâh"]', '["and/ a love of","and/ love"]', '["n-f"]', 'love.', 'feminine of 158 and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0750}/[H748]', 'inflected', 'heb', 'אָרֵךְ', '["ʼârêk"]', '["and/ a [person] long of"]', '["a"]', 'long long(-suffering, -winged), patient, slow (to anger).', 'from 748;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4881A}/[H7753]', 'inflected', 'heb', 'מְשׂוּכָה', '["mᵉsûwkâh"]', '["[is] like/ a hedge of"]', '["n-f"]', 'a hedge hedge.', 'or מְשֻׂכָה; from 7753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2312>', 'opaque', 'heb', 'חֵדֶק', '["chêdeq"]', '["thorn[s]"]', '["n-m"]', 'a prickly plant brier, thorn.', 'from an unused root meaning to sting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2638}/[H2637]', 'inflected', 'heb', 'חָסֵר', '["châçêr"]', '["to/ [one] lacking of"]', '["a"]', 'lacking; hence, without destitute, fail, lack, have need, void, want.', 'from 2637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4617}/[H6030]', 'inflected', 'heb', 'מַעֲנֶה', '["maʻăneh"]', '["in/ [the] answer of"]', '["n-m"]', 'a reply (favorable or contradictory) answer, × himself.', 'from 6030;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5324}/[H5324]', 'inflected', 'heb', 'נָצַב', '["nâtsab"]', '["and/ he will establish"]', '["v"]', 'to station, in various applications (literally or figuratively) appointed, deputy, erect, establish, × Huzzah (by mistake for a proper name), lay, officer, pillar, present, rear up, set (over, up), settle, sharpen, establish, (make to) stand(-ing, still, up, upright), best state.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6038}/[H6035]', 'lemma', 'heb', 'עֲנָוָה', '["ʻănâvâh"]', '["humility"]', '["n-f"]', 'condescension, human and subjective (modesty), or divine and objective (clemency) gentleness, humility, meekness.', 'from 6035;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4633}/[H6186]', 'lemma', 'heb', 'מַעֲרָךְ', '["maʻărâk"]', '["[the] plans of"]', '["n-m"]', 'an arrangement, i.e. (figuratively) mental disposition preparation.', 'from 6186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H3068G}/[H1961]', 'inflected', 'heb', 'יְהֹוָה', '["Yᵉhôvâh"]', '["and/ [is] from/ Yahweh"]', '["n-pr"]', '(the) self-Existent or Eternal; Jeho-vah, Jewish national name of God Jehovah, the Lord. Compare 3050, 3069.', 'from 1961;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8505}/[H8505]', 'inflected', 'heb', 'תָּכַן', '["tâkan"]', '["and/ [is] weighing"]', '["v"]', 'to balance, i.e. measure out (by weight or dimension); figuratively to arrange, equalize, through the idea of levelling (ment, estimate, test) bear up, direct, be (un-)equal, mete, ponder, tell, weigh.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4617}/H9023/[H6030]', 'inflected', 'heb', 'מַעֲנֶה', '["maʻăneh"]', '["for <the>/ purpose/ its"]', '["n-m"]', 'a reply (favorable or contradictory) answer, × himself.', 'from 6030;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027V}/[H3027]', 'lemma', 'heb', 'יָד', '["yâd"]', '["hand"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3374}/[H3373]', 'inflected', 'heb', 'יִרְאָה', '["yirʼâh"]', '["and/ [is] by/ [the] fear of"]', '["n-f"]', 'fear (also used as infinitive); morally, reverence × dreadful, × exceedingly, fear(-fulness).', 'feminine of 3373;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7521}/[H7521]', 'inflected', 'heb', 'רָצָה', '["râtsâh"]', '["when/ is pleased with"]', '["v"]', 'to be pleased with; specifically, to satisfy a debt (be) accept(-able), accomplish, set affection, approve, consent with, delight (self), enjoy, (be, have a) favour(-able), like, observe, pardon, (be, have, take) please(-ure), reconcile self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6425}/[H6424]', 'lemma', 'heb', 'פֶּלֶס', '["peleç"]', '["a balance"]', '["n-m"]', 'a balance scales, weight.', 'from 6424;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3976}/[H239]', 'inflected', 'heb', 'מֹאזֵן', '["môʼzên"]', '["and/ balances of","and/ scales of"]', '["n-m"]', '(only in the dual) a pair of scales balances.', 'from 239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3722A}/H9034/[H3722]', 'inflected', 'heb', 'כָּפַר', '["kâphar"]', '["he covers/ it","to cover/ it"]', '["v"]', 'to cover (specifically with bitumen); figuratively, to expiate or condone, to placate or cancel appease, make (an atonement, cleanse, disannul, forgive, be merciful, pacify, pardon, purge (away), put off, (make) reconcile(-liation).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5645}/[H5743]', 'inflected', 'heb', 'עָב', '["ʻâb"]', '["[is] like/ a cloud of","like <the>/ cloud","like <the>/ dark cloud","like/ a cloud of"]', '["n-m"]', 'properly, an envelope, i.e. darkness (or density, 2 Chronicles 4:17); specifically, a (scud) cloud; also a copse clay, (thick) cloud, × thick, thicket. Compare 5672.', '(masculine and feminine); from 5743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4456}/[H3953]', 'lemma', 'heb', 'מַלְקוֹשׁ', '["malqôwsh"]', '["spring rain"]', '["n-m"]', 'the spring rain; figuratively, eloquence latter rain.', 'from 3953; (compare 3954)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7069}/[H7069]', 'inflected', 'heb', 'קָנָה', '["qânâh"]', '["and/ to acquire"]', '["v"]', 'to erect, i.e. create; by extension, to procure, especially by purchase (causatively, sell); by implication to own attain, buy(-er), teach to keep cattle, get, provoke to jealousy, possess(-or), purchase, recover, redeem, × surely, × verily.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3783}/[H3782]', 'lemma', 'heb', 'כִּשָּׁלוֹן', '["kishshâlôwn"]', '["stumbling"]', '["n-m"]', 'properly, a tottering, i.e. ruin fall.', 'from 3782;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4986}/[H4985]', 'inflected', 'heb', 'מֶתֶק', '["metheq"]', '["and/ [the] sweetness of","and/ sweetness of"]', '["n-m"]', 'figuratively, pleasantness (of discourse) sweetness.', 'from 4985;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1167J}/H9023/[H1166]', 'inflected', 'heb', 'בַּעַל', '["baʻal"]', '["owners/ its"]', '["n-m"]', 'a master; hence, a husband, or (figuratively) owner (often used with another noun in modifications of this latter sense) archer, babbler, bird, captain, chief man, confederate, have to do, dreamer, those to whom it is due, furious, those that are given to it, great, hairy, he that hath it, have, horseman, husband, lord, man, married, master, person, sworn, they of.', 'from 1166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4832}/[H7495]', 'inflected', 'heb', 'מַרְפֵּא', '["marpêʼ"]', '["and/ healing"]', '["n-m"]', 'properly, curative, i.e. literally (concretely) a medicine, or (abstractly) a cure; figuratively (concretely) deliverance, or (abstractly) placidity (in-)cure(-able), healing(-lth), remedy, sound, wholesome, yielding.', 'from 7495;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6106I}/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["to the/ bone[s]"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0404}/[H404]', 'lemma', 'heb', 'אָכַף', '["ʼâkaph"]', '["it presses"]', '["v"]', 'to urge crave.', 'a primitive root; apparently meaning to curve (as with a burden);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8193H}/H9023/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["lip/ his","lips/ his"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6867A}/[H6866]', 'lemma', 'heb', 'צָרֶבֶת', '["tsârebeth"]', '["scorching"]', '["a n-f"]', 'conflagration (of fire or disease) burning, inflammation.', 'from 6866;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7279}/[H7279]', 'inflected', 'heb', 'רָגַן', '["râgan"]', '["and/ a slanderer","and/ murmurers"]', '["v"]', 'to grumble, i.e. rebel murmur.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6095}/[H6095]', 'lemma', 'heb', 'עָצָה', '["ʻâtsâh"]', '["[one who] shuts"]', '["v"]', 'properly, to fasten (or make firm), i.e. to close (the eyes) shut.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2803I}/[H2803]', 'inflected', 'heb', 'חָשַׁב', '["châshab"]', '["to/ devise"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1368}/[H1397]', 'inflected', 'heb', 'גִּבּוֹר', '["gibbôwr"]', '["from/ a warrior","more than/ a warrior","some of/ [the] warriors of"]', '["a"]', 'powerful; by implication, warrior, tyrant champion, chief, × excel, giant, man, mighty (man, one), strong (man), valiant man.', 'or גִּבֹּר; (shortened) intensive from the same as 1397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3920}/[H3920]', 'inflected', 'heb', 'לָכַד', '["lâkad"]', '["more than/ [one who] captures"]', '["v"]', 'to catch (in a net, trap or pit); generally, to capture or occupy; also to choose (by lot); figuratively, to cohere × at all, catch (self), be frozen, be holden, stick together, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2436I>', 'inflected', 'heb', 'בחיק', '["Ba./cheik"]', '["in the/ bosom"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2720A}/[H2717]', 'lemma', 'heb', 'חָרֵב', '["chârêb"]', '["dry"]', '["a"]', 'parched or ruined desolate, dry, waste.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4715}/[H6884]', 'lemma', 'heb', 'מִצְרֵף', '["mitsrêph"]', '["a crucible"]', '["n-m"]', 'a crucible fining pot.', 'from 6884;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3564>', 'inflected', 'heb', 'וכור', '["ve./Khur"]', '["and/ a smelting furnace"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7326}/[H7326]', 'inflected', 'heb', 'רוּשׁ', '["rûwsh"]', '["<to> the/ poor [person]","to the/ poor"]', '["v"]', 'to be destitute lack, needy, (make self) poor (man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0343}/[H181]', 'inflected', 'heb', 'אֵיד', '["ʼêyd"]', '["for/ calamity"]', '["n-m"]', 'oppression; by implication misfortune, ruin calamity, destruction.', 'from the same as 181 (in the sense of bending down);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5036}/[H5034]', 'inflected', 'heb', 'נָבָל', '["nâbâl"]', '["for/ a fool","to/ a fool"]', '["a"]', 'stupid; wicked (especially impious) fool(-ish, -ish man, -ish woman), vile person.', 'from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5081H}/[H5068]', 'inflected', 'heb', 'נָדִיב', '["nâdîyb"]', '["for/ a noble [person]"]', '["a"]', 'properly, voluntary, i.e. generous; hence, magnanimous; as noun, a grandee (sometimes a tyrant) free, liberal (things), noble, prince, willing (hearted).', 'from 5068;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8138B}/[H8138]', 'inflected', 'heb', 'שָׁנָה', '["shânâh"]', '["and/ [one who] repeats"]', '["v"]', 'to fold, i.e. duplicate (literally or figuratively); by implication, to transmute (transitive or intransitive) do (speak, strike) again, alter, double, (be given to) change, disguise, (be) diverse, pervert, prefer, repeat, return, do the second time.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0995}/[H995]', 'inflected', 'heb', 'בִּין', '["bîyn"]', '["in/ [one who] understands"]', '["v"]', 'to separate mentally (or distinguish), i.e.(generally) understand attend, consider, be cunning, diligently, direct, discern, eloquent, feel, inform, instruct, have intelligence, know, look well to, mark, perceive, be prudent, regard, (can) skill(-full), teach, think, (cause, make to, get, give, have) understand(-ing), view, (deal) wise(-ly, man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0200}/H9023/[H191]', 'inflected', 'heb', 'אִוֶּלֶת', '["ʼivveleth"]', '["<in>/ foolishness/ his","in/ foolishness/ his"]', '["n-f"]', 'silliness folly, foolishly(-ness).', 'from the same as 191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1566}/[H1566]', 'lemma', 'heb', 'גָּלַע', '["gâlaʻ"]', '["he bursts out","it has broken out"]', '["v"]', 'to be obstinate (inter-) meddle (with).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7453}/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["[is] the/ friend","the/ friend"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6869B}/[H6862]', 'inflected', 'heb', 'צָרָה', '["tsârâh"]', '["for/ adversity"]', '["n-f"]', 'tightness (i.e. figuratively, trouble); transitively, a female rival adversary, adversity, affliction, anguish, distress, tribulation, trouble.', 'feminine of 6862;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6161}/[H6048]', 'lemma', 'heb', 'עֲרֻבָּה', '["ʻărubbâh"]', '["a pledge"]', '["n-f"]', 'something given as security, i.e. (literally) a token (of safety) or (metaphorically) a bondsman pledge, surety.', 'feminine passive participle of 6048 in the sense of a bargain or exchange;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6607}/H9023/[H6605]', 'inflected', 'heb', 'פֶּתַח', '["pethach"]', '["entrance/ his"]', '["n-m"]', 'an opening (literally), i.e. door (gate) or entrance way door, entering (in), entrance (-ry), gate, opening, place.', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8424}/[H3013]', 'inflected', 'heb', 'תּוּגָה', '["tûwgâh"]', '["to/ grief"]', '["n-f"]', 'depression (of spirits); concretely a grief heaviness, sorrow.', 'from 3013;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1456}/[H1455]', 'lemma', 'heb', 'גֵּהָה', '["gêhâh"]', '["healing"]', '["n-f"]', 'a cure medicine.', 'from 1455;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H2436J>', 'inflected', 'heb', 'מחיק', '["Me./cheik"]', '["from/ [the] bosom"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4470>', 'inflected', 'heb', 'וממר', '["u./Me.mer"]', '["and/ bitterness"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3205}/H9033/[H3205]', 'inflected', 'heb', 'יָלַד', '["yâlad"]', '["to/ [the] [one who] bore/ him"]', '["v"]', 'to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8378}/[H183]', 'inflected', 'heb', 'תַּאֲוָה', '["taʼăvâh"]', '["<to>/ desire"]', '["n-f"]', 'a longing; by implication, a delight (subjectively, satisfaction, objectively, a charm) dainty, desire, × exceedingly, × greedily, lust(ing), pleasant. See also 6914.', 'from 183 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1540H}/[H1540]', 'inflected', 'heb', 'גָּלָה', '["gâlâh"]', '["because/ were uncovered","in/ revealing itself"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7379}/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["in/ strife"]', '["n-m"]', 'a contest (personal or legal) adversary, cause, chiding, contend(-tion), controversy, multitude (from the margin), pleading, strife, strive(-ing), suit.', 'or רִב; from 7378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6310G}/H9023/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["and/ mouth/ his"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4112}/[H1986]', 'inflected', 'heb', 'מַהֲלֻמָּה', '["mahălummâh"]', '["for/ blows"]', '["n-f"]', 'a blow stripe, stroke.', 'from 1986;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8193G}/H9023/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["and/ lips/ his"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7279}/[H7279]', 'lemma', 'heb', 'רָגַן', '["râgan"]', '["a slanderer"]', '["v"]', 'to grumble, i.e. rebel murmur.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3859}/[H3859]', 'inflected', 'heb', 'לָהַם', '["lâham"]', '["[are] like/ delicacies"]', '["v"]', 'properly, to burn in, i.e. (figuratively) to rankle wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0990J>', 'opaque', 'heb', 'בֶּטֶן', '["beṭen"]', '["[the] belly"]', '["n-f"]', 'the belly, especially the womb; also the bosom or body of anything belly, body, as they be born, within, womb.', 'from an unused root probably meaning to be hollow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1167K}/[H1166]', 'inflected', 'heb', 'בַּעַל', '["baʻal"]', '["for/ [the] master of","of/ a master of"]', '["n-m"]', 'a master; hence, a husband, or (figuratively) owner (often used with another noun in modifications of this latter sense) archer, babbler, bird, captain, chief man, confederate, have to do, dreamer, those to whom it is due, furious, those that are given to it, great, hairy, he that hath it, have, horseman, husband, lord, man, married, master, person, sworn, they of.', 'from 1166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4889}/[H7843]', 'lemma', 'heb', 'מַשְׁחִית', '["mashchîyth"]', '["a destroyer","destruction"]', '["n-m"]', 'destructive, i.e. (as noun) destruction, literally (specifically a snare) or figuratively (corruption) corruption, (to) destroy(-ing), destruction, trap, × utterly.', 'from 7843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/<H2346G>', 'inflected', 'heb', 'וכחומה', '["u./khe./cho.Mah"]', '["and/ like/ a wall"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4906}/H9023/[H7906]', 'inflected', 'heb', 'מַשְׂכִּית', '["maskîyth"]', '["in/ own imagination/ his"]', '["n-f"]', 'a figure (carved on stone, the wall, or any object); figuratively, imagination conceit, image(-ry), picture, × wish.', 'from the same as 7906;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4245A}/H9023/[H2470]', 'inflected', 'heb', 'מַחֲלֶה', '["machăleh"]', '["sickness/ his"]', '["n-m"]', 'sickness disease, infirmity, sickness.', 'or (feminine) מַחֲלָה; from 2470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375H}/H9034/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["will he bear/ it"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4976}/[H5414]', 'lemma', 'heb', 'מַתָּן', '["mattân"]', '["[the] gift of","a gift","gift"]', '["n-m"]', 'a present gift, to give, reward.', 'from 5414;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2713}/H9033/[H2713]', 'inflected', 'heb', 'חָקַר', '["châqar"]', '["and/ he will examine/ him"]', '["v"]', 'properly, to penetrate; hence, to examine intimately find out, (make) search (out), seek (out), sound, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4079}/[H4066]', 'inflected', 'heb', 'מִדְיָן', '["midyân"]', '["and/ contentions"]', '["n-m"]', 'brawling, contention(-ous).', 'a variation for 4066');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1280}/[H1272]', 'inflected', 'heb', 'בְּרִיחַ', '["bᵉrîyach"]', '["[are] like/ [the] bar of"]', '["n-m"]', 'a bolt bar, fugitive.', 'from 1272;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0759H>', 'opaque', 'heb', 'אַרְמוֹן', '["ʼarmôwn"]', '["[the] fortresses","[the] fortresses of","a fortress","a fortress of"]', '["n-m"]', 'a citadel (from its height) castle, palace. Compare 2038.', 'from an unused root (meaning to be elevated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0157G}/H9034/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["and/ [those who] love/ it"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6223}/[H6238]', 'inflected', 'heb', 'עָשִׁיר', '["ʻâshîyr"]', '["and/ a rich [person]","and/ rich [people]"]', '["n-m"]', 'rich, whether literal or figurative (noble) rich (man).', 'from 6238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7489B}/[H7489]', 'inflected', 'heb', 'רָעַע', '["râʻaʻ"]', '["[is] to/ be broken"]', '["v"]', 'properly, to spoil (literally, by breaking to pieces); figuratively, to make (or be) good for nothing, i.e. bad (physically, socially or morally) afflict, associate selves (by mistake for 7462), break (down, in pieces), displease, (be, bring, do) evil (doer, entreat, man), show self friendly (by mistake for 7462), do harm, (do) hurt, (behave self, deal) ill, × indeed, do mischief, punish, still, vex, (do) wicked (doer, -ly), be (deal, do) worse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0157H}/[H157]', 'lemma', 'heb', 'אָהַב', '["ʼâhab"]', '["[is one who] loves","[one who] loves"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8537}/H9023/[H8552]', 'inflected', 'heb', 'תֹּם', '["tôm"]', '["in/ integrity/ his"]', '["n-m"]', 'completeness; figuratively, prosperity; usually (morally) innocence full, integrity, perfect(-ion), simplicity, upright(-ly, -ness), at a venture. See 8550.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6141}/[H6140]', 'inflected', 'heb', 'עִקֵּשׁ', '["ʻiqqêsh"]', '["more than/ [the] [person] perverse","more than/ [the] [person] perverse of"]', '["a"]', 'distorted; hence, false crooked, froward, perverse.', 'from 6140;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0213}/[H213]', 'inflected', 'heb', 'אוּץ', '["ʼûwts"]', '["and/ [one who] hastens"]', '["v"]', 'to press; (by implication) to be close, hurry, withdraw (make) haste(-n, -y), labor, be narrow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0006}\/[H6]', 'inflected', 'heb', 'אָבַד', '["ʼâbad"]', '["he will perish"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8588}/[H6026]', 'lemma', 'heb', 'תַּעֲנוּג', '["taʻănûwg"]', '["luxury"]', '["n-m"]', 'luxury delicate, delight, pleasant.', 'or תַּעֲנֻג; and (feminine) תַּעֲנֻגָה; from 6026;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8269}/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["over/ princes"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5099}/[H5098]', 'lemma', 'heb', 'נַהַם', '["naham"]', '["[is] a roaring"]', '["n-m"]', 'a snarl roaring.', 'from 5098;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3715A}/[H3722]', 'inflected', 'heb', 'כְּפִיר', '["kᵉphîyr"]', '["like <the>/ young lion","like <the>/ young lions","like/ a young lion"]', '["n-m"]', 'a village (as covered in by walls); also a young lion (perhaps as covered with a mane) (young) lion, village. Compare 3723.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2197}/[H2196]', 'lemma', 'heb', 'זַעַף', '["zaʻaph"]', '["[the] indignation of","[the] rage of"]', '["n-m"]', 'anger indignation, rage(-ing), wrath.', 'from 2196;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H2919}/[H2926]', 'inflected', 'heb', 'טַל', '["ṭal"]', '["and/ [is] like/ dew","and/ like <the>/ dew"]', '["n-m"]', 'dew (as covering vegetation) dew.', 'from 2926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1812}/[H1811]', 'inflected', 'heb', 'דֶּלֶף', '["deleph"]', '["and/ [are] a dripping"]', '["n-m"]', 'a dripping dropping.', 'from 1811;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2956}/[H2956]', 'lemma', 'heb', 'טָרַד', '["ṭârad"]', '["continuous"]', '["v"]', 'to drive on; figuratively, to follow close continual.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6103}/[H6102]', 'lemma', 'heb', 'עַצְלָה', '["ʻatslâh"]', '["laziness"]', '["n-f"]', '(as abstractly) indolence slothfulness.', 'feminine of 6102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1576}/H9023/[H1580]', 'inflected', 'heb', 'גְּמוּל', '["gᵉmûwl"]', '["and/ recompense/ his"]', '["n-m"]', 'treatment, i.e. an act (of good or ill); by implication, service or requital as hast served, benefit, desert, deserving, that which he hath given, recompense, reward.', 'from 1580;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6901}/[H6901]', 'inflected', 'heb', 'קָבַל', '["qâbal"]', '["and/ accept"]', '["v"]', 'to admit, i.e. take (literally or figuratively) choose, (take) hold, receive, (under-) take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6747}/[H6743]', 'inflected', 'heb', 'צַלַּחַת', '["tsallachath"]', '["in the/ dish"]', '["n-f"]', 'something advanced or deep, i.e. a bowl; figuratively, the bosom bosom, dish.', 'from 6743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725G}/H9034/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["he brings back/ it"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6612A}/[H6601]', 'inflected', 'heb', 'פְּתִי', '["pᵉthîy"]', '["and/ a naive person","and/ naive people"]', '["a n-f"]', 'silly (i.e. seducible) foolish, simple(-icity, one).', 'or פֶּתִי; or פְּתָאִי; from 6601;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7686}/[H7686]', 'inflected', 'heb', 'שָׁגָה', '["shâgâh"]', '["to/ stray"]', '["v"]', 'to stray (causatively, mislead), usually (figuratively) to mistake, especially (morally) to transgress; by extension (through the idea of intoxication) to reel, (figuratively) be enraptured (cause to) go astray, deceive, err, be ravished, sin through ignorance, (let, make to) wander.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4112}/[H1986]', 'inflected', 'heb', 'מַהֲלֻמָּה', '["mahălummâh"]', '["and/ blows"]', '["n-f"]', 'a blow stripe, stroke.', 'from 1986;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5674B}/H9033/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["[one who] infuriates/ him"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7674}/[H7673]', 'lemma', 'heb', 'שֶׁבֶת', '["shebeth"]', '["a sitting still","cessation"]', '["n-f"]', 'rest, interruption, cessation cease, sit still, loss of time.', 'from 7673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2779}/[H2778]', 'inflected', 'heb', 'חֹרֶף', '["chôreph"]', '["from/ winter"]', '["n-m"]', 'properly, the crop gathered, i.e. (by implication) the autumn (and winter) season; figuratively, ripeness of age cold, winter (-house), youth.', 'from 2778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1802}/H9034/[H1809]', 'inflected', 'heb', 'דָּלָה', '["dâlâh"]', '["he draws out/ it"]', '["v"]', 'properly, to dangle, i.e. to let down a bucket (for drawing out water); figuratively, to deliver draw (out), × enough, lift up.', 'a primitive root (compare 1809);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4611}/H9023/[H5953]', 'inflected', 'heb', 'מַעֲלָל', '["maʻălâl"]', '["by/ deeds/ his"]', '["n-m"]', 'an act (good or bad) doing, endeavour, invention, work.', 'from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0235}/[H235]', 'inflected', 'heb', 'אָזַל', '["ʼâzal"]', '["and/ [he is] going away"]', '["v"]', 'to go away, hence, to disappear fail, gad about, go to and fro (but in Ezekiel 27:19 the word is rendered by many ''from Uzal,'' by others ''yarn''), be gone (spent).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6443}/[H6434]', 'lemma', 'heb', 'פָּנִין', '["pânîyn"]', '["jewels"]', '["n-m"]', 'probably a pearl (as round) ruby.', 'or פָּנִי; from the same as 6434;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2254A}/H9033/[H2254]', 'inflected', 'heb', 'חָבַל', '["châbal"]', '["hold in pledge/ it"]', '["v"]', 'to wind tightly (as a rope), i.e. to bind; specifically, by a pledge; figuratively, to pervert, destroy; also to writhe in pain (especially of parturition) × at all, band, bring forth, (deal) corrupt(-ly), destroy, offend, lay to (take a) pledge, spoil, travail, × very, withhold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6156}/[H6149]', 'lemma', 'heb', 'עָרֵב', '["ʻârêb"]', '["[is] sweet"]', '["a"]', 'pleasant sweet.', 'from 6149;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2687}/[H2671]', 'lemma', 'heb', 'חָצָץ', '["châtsâts"]', '["gravel"]', '["n-m"]', 'properly, something cutting; hence, gravel (as grit); an arrow arrow, gravel (stone).', 'from 2687; also like 2671');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8458}/[H2254]', 'inflected', 'heb', 'תַּחְבֻּלָה', '["tachbulâh"]', '["and/ by/ wise directions"]', '["n-f"]', '(only in plural) properly, steerage (as a management of ropes), i.e. (figuratively) guidance or (by implication) a plan good advice, (wise) counsels.', 'or תַּחְבּוּלָה; from 2254 as denominative from 2256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6601A}/[H6601]', 'inflected', 'heb', 'פָּתָה', '["pâthâh"]', '["and/ to/ [one who] opens"]', '["v"]', 'to open, i.e. be (causatively, make) roomy; usually figuratively (in a mental or moral sense) to be (causatively, make) simple or (in a sinister way) delude allure, deceive, enlarge, entice, flatter, persuade, silly (one).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3216}/[H3216]', 'lemma', 'heb', 'יָלַע', '["yâlaʻ"]', '["he may say rashly"]', '["v"]', 'to blurt or utter inconsiderately devour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0990G>', 'opaque', 'heb', 'בֶּטֶן', '["beṭen"]', '["[the] belly"]', '["n-f"]', 'the belly, especially the womb; also the bosom or body of anything belly, body, as they be born, within, womb.', 'from an unused root probably meaning to be hollow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5582}/[H5582]', 'inflected', 'heb', 'סָעַד', '["çâʻad"]', '["and/ he sustains"]', '["v"]', 'to support (mostly figurative) comfort, establish, hold up, refresh self, strengthen, be upholden.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3581B>/H9028', 'opaque', 'heb', 'כֹּחַ', '["kôach"]', '["[is] strength/ their"]', '["n-m"]', 'vigor, literally (force, in a good or a bad sense) or figuratively (capacity, means, produce); also (from its hardiness) a large lizard ability, able, chameleon, force, fruits, might, power(-ful), strength, substance, wealth.', 'or (Daniel 11:6) כּוֹחַ; from an unused root meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8562}/[H4838]', 'lemma', 'heb', 'תַּמְרוּק', '["tamrûwq"]', '["[are] a cleansing"]', '["n-m"]', 'properly, a scouring, i.e. soap or perfumery for the bath; figuratively, a detergent × cleanse, (thing for) purification(-fying).', 'or תַּמְרֻק; or תַּמְרִיק; from 4838;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7451H}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["<in>/ evil"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4347}/[H5221]', 'inflected', 'heb', 'מַכָּה', '["makkâh"]', '["and/ blows","and/ wound[s]"]', '["n-f"]', 'a blow (in 2 Chronicles 2:10, of the flail); by implication, a wound; figuratively, carnage, also pestilence beaten, blow, plague, slaughter, smote, × sore, stripe, stroke, wound(-ed).', 'or (masculine) מַכֶּה; (plural only) from 5221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7312}/[H7311]', 'lemma', 'heb', 'רוּם', '["rûwm"]', '["[the] haughtiness of","[the] pride of","haughtiness of"]', '["n-m"]', '(literally) elevation or (figuratively) elation haughtiness, height, × high.', 'or רֻם; from 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7342I}/[H7337]', 'inflected', 'heb', 'רָחָב', '["râchâb"]', '["and/ a [person] arrogant of"]', '["a"]', 'roomy, in any (or every) direction, literally or figuratively broad, large, at liberty, proud, wide.', 'from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4195}/[H3498]', 'inflected', 'heb', 'מוֹתָר', '["môwthâr"]', '["to/ advantage"]', '["n-m"]', 'literally gain; figuratively, superiority plenteousness, preeminence, profit.', 'from 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3956G}/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["by/ a tongue of","with the/ tongue"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7701}/[H7736]', 'lemma', 'heb', 'שֹׁד', '["shôd"]', '["[the] devastation of","[the] violence of","devastation","violence"]', '["n-m"]', 'violence, ravage desolation, destruction, oppression, robbery, spoil(-ed, -er, -ing), wasting.', 'or שׁוֹד; (Job 5:21), from 7736;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1641}/H9038/[H1641]', 'inflected', 'heb', 'גָּרַר', '["gârar"]', '["it will drag away/ them"]', '["v"]', 'to drag off roughly; by implication, to bring up the cud (i.e. ruminate); by analogy, to saw catch, chew, × continuing, destroy, saw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2019}/[H2015]', 'lemma', 'heb', 'הֲפַכְפַּךְ', '["hăphakpak"]', '["[is] crooked"]', '["a"]', 'very perverse froward.', 'by reduplication from 2015;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2054>', 'opaque', 'heb', 'וָזָר', '["vâzâr"]', '["guilty"]', '["n-m"]', 'crime × strange.', 'presumed to be from an unused root meaning to bear guilt;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2134}/[H2141]', 'inflected', 'heb', 'זַךְ', '["zak"]', '["and/ a pure [person]"]', '["a"]', 'clear clean, pure.', 'from 2141;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2269}/[H2266]', 'lemma', 'arc', 'חֲבַר', '["chăbar"]', '["an association of","association"]', '["n-m"]', 'an associate companion, fellow.', '(Aramaic) from a root corresponding to 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6064}/[H6064]', 'inflected', 'heb', 'עָנַשׁ', '["ʻânash"]', '["when/ punish"]', '["v"]', 'properly, to urge; by implication, to inflict a penalty, specifically, to fine amerce, condemn, punish, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7919A}/[H7919]', 'inflected', 'heb', 'שָׂכַל', '["sâkal"]', '["and/ when/ instruct"]', '["v"]', 'to be (causatively, make or act) circumspect and hence, intelligent consider, expert, instruct, prosper, (deal) prudent(-ly), (give) skill(-ful), have good success, teach, (have, make to) understand(-ing), wisdom, (be, behave self, consider, make) wise(-ly), guide wittingly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2201}/[H2199]', 'inflected', 'heb', 'זַעַק', '["zaʻaq"]', '["from/ [the] cry of","from/ [the] cry of distress of","more than/ [the] cry of"]', '["n-f"]', 'a shriek or outcry cry(-ing).', 'and (feminine) זְעָקָהxlit zᵉâqâh corrected to zᵉʻâqâh; from 2199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3711}/[H3711]', 'lemma', 'heb', 'כָּפָה', '["kâphâh"]', '["it subdues"]', '["v"]', 'properly, to bend, i.e. (figuratively) to tame or subdue pacify.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2436J>', 'inflected', 'heb', 'בחק', '["ba./Chek"]', '["in the/ bosom"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5116A}/[H5115]', 'inflected', 'heb', 'נָוֶה', '["nâveh"]', '["[are] in/ [the] habitation of","in/ a habitation of","in/ pastureland"]', '["n"]', '(adjectively) at home; hence (by implication of satisfaction) lovely; also (noun) a home, of God (temple), men (residence), flocks (pasture), or wild animals (den) comely, dwelling (place), fold, habitation, pleasant place, sheepcote, stable, tarried.', 'or (feminine) נָוָה; from 5115;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4009}/H9024/[H982]', 'inflected', 'heb', 'מִבְטָח', '["mibṭâch"]', '["trust/ its"]', '["n-m"]', 'properly, a refuge, i.e. (objective) security, or (subjective) assurance confidence, hope, sure, trust.', 'from 982;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3093}/[H2022]', 'lemma', 'heb', 'יָהִיר', '["yâhîyr"]', '["arrogant"]', '["a"]', 'elated; hence, arrogant haughty, proud.', 'probably from the same as 2022;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2154}/[H2161]', 'inflected', 'heb', 'זִמָּה', '["zimmâh"]', '["in/ wickedness"]', '["n-f"]', 'a plan, especially a bad one heinous crime, lewd(-ly, -ness), mischief, purpose, thought, wicked (device, mind, -ness).', 'or זַמָּה; from 2161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6239}/[H6238]', 'inflected', 'heb', 'עֹשֶׁר', '["ʻôsher"]', '["more than/ wealth"]', '["n-m"]', 'wealth × far (richer), riches.', 'from 6238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H2091>', 'inflected', 'heb', 'ומזהב', '["u./mi./za.Hav"]', '["and/ more than/ gold"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6791>', 'opaque', 'heb', 'צֵן', '["tsên"]', '["thorns"]', '["n-m"]', 'a thorn; hence, a cactus-hedge thorn.', 'from an unused root meaning to be prickly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2596}/[H2614]', 'lemma', 'heb', 'חָנַךְ', '["chânak"]', '["train"]', '["v"]', 'properly, to narrow; figuratively, to initiate or discipline dedicate, train up.', 'a primitive root; (compare 2614)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7326}/[H7326]', 'inflected', 'heb', 'רוּשׁ', '["rûwsh"]', '["over/ poor [people]"]', '["v"]', 'to be destitute lack, needy, (make self) poor (man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5678}/H9023/[H5676]', 'inflected', 'heb', 'עֶבְרָה', '["ʻebrâh"]', '["arrogance/ its","fury/ his"]', '["n-f"]', 'an outburst of passion anger, rage, wrath.', 'feminine of 5676;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3899H}/H9023/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["some of/ food/ his"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7673A}/[H7673]', 'inflected', 'heb', 'שָׁבַת', '["shâbath"]', '["so/ <it> may cease"]', '["v"]', 'to repose, i.e. desist from exertion; used in many implied relations (causative, figurative or specific) (cause to, let, make to) cease, celebrate, cause (make) to fail, keep (sabbath), suffer to be lacking, leave, put away (down), (make to) rest, rid, still, take away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5557}/[H5557]', 'inflected', 'heb', 'סָלַף', '["çâlaph"]', '["and/ he has subverted"]', '["v"]', 'properly, to wrench, i.e. (figuratively) to subvert overthrow, pervert.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7745}/[H7743]', 'lemma', 'heb', 'שׁוּחָה', '["shûwchâh"]', '["[is] a pit","a pit"]', '["n-f"]', 'a chasm ditch, pit.', 'from 7743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7368}/H9034/[H7368]', 'inflected', 'heb', 'רָחַק', '["râchaq"]', '["it will put far away/ it"]', '["v"]', 'to widen (in any direction), i.e. (intransitively) recede or (transitively) remove (literally or figuratively, of place or relation) (a-, be, cast, drive, get, go, keep (self), put, remove, be too, (wander), withdraw) far (away, off), loose, × refrain, very, (be) a good way (off).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1847}/H9020/[H3045]', 'inflected', 'heb', 'דַּעַת', '["daʻath"]', '["to/ knowledge/ my"]', '["n"]', 'knowledge cunning, (ig-) norantly, know(-ledge), (un-) awares (wittingly).', 'from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0990J>/H9021', 'inflected', 'heb', 'בבטנך', '["be./vit.Ne./kha"]', '["in/ belly/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4009}/H9021/[H982]', 'inflected', 'heb', 'מִבְטָח', '["mibṭâch"]', '["trust/ your"]', '["n-m"]', 'properly, a refuge, i.e. (objective) security, or (subjective) assurance confidence, hope, sure, trust.', 'from 982;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7991C}/[H7969]', 'lemma', 'heb', 'שָׁלִישׁ', '["shâlîysh"]', '["icers","officers"]', '["n-m"]', 'a triple, i.e. (as a musical instrument) a triangle (or perhaps rather three-stringed lute); also (as an indefinite, great quantity) a three-fold measure (perhaps a treble ephah); also (as an officer) a general of the third rank (upward, i.e. the highest) captain, instrument of musick, (great) lord, (great) measure, prince, three (from the margin).', 'or שָׁלוֹשׁ; (1 Chronicles 11:11; 1 Chronicles 12:18), or שָׁלֹשׁ; (2 Samuel 23:13), from 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4156}/[H3289]', 'inflected', 'heb', 'מוֹעֵצָה', '["môwʻêtsâh"]', '["<in>/ counsels","in/ counsels"]', '["n-f"]', 'a purpose counsel, device.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7189B>', 'opaque', 'heb', 'קֹשֶׁט', '["qôsheṭ"]', '["[the] truth of"]', '["n-m"]', 'equity (as evenly weighed), i.e. reality truth.', 'or קֹשְׁטְ; from an unused root meaning to balance;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7971G}/H9031\/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["to/ [those who] sent/ you"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7379}/H9028/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["case/ their"]', '["n-m"]', 'a contest (personal or legal) adversary, cause, chiding, contend(-tion), controversy, multitude (from the margin), pleading, strife, strive(-ing), suit.', 'or רִב; from 7378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6906}/[H6906]', 'inflected', 'heb', 'קָבַע', '["qâbaʻ"]', '["and/ he will rob"]', '["v"]', 'to cover, i.e. (figuratively) defraud rob, spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6906}/H9038/[H6906]', 'inflected', 'heb', 'קָבַע', '["qâbaʻ"]', '["[those who] rob/ them"]', '["v"]', 'to cover, i.e. (figuratively) defraud rob, spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7462C}/[H7462]', 'lemma', 'heb', 'רָעָה', '["râʻâh"]', '["they will graze","you associate"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5315I}/H9021/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["for/ self/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8628}/[H8628]', 'inflected', 'heb', 'תָּקַע', '["tâqaʻ"]', '["among/ [those who] strike"]', '["v"]', 'to clatter, i.e. slap (the hands together), clang (an instrument); by analogy, to drive (a nail or tent-pin, a dart, etc.); by implication, to become bondsman by handclasping) blow (a trumpet), cast, clap, fasten, pitch (tent), smite, sound, strike, × suretiship, thrust.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6148}/[H6148]', 'inflected', 'heb', 'עָרַב', '["ʻârab"]', '["among <the>/ [those who] stand surety for"]', '["v"]', 'to braid, i.e. intermix; technically, to traffic (as if by barter); also or give to be security (as a kind of exchange) engage, (inter-) meddle (with), mingle (self), mortgage, occupy, give pledges, be(-come, put in) surety, undertake.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7999A}/[H7999]', 'inflected', 'heb', 'שָׁלַם', '["shâlam"]', '["to/ pay"]', '["v"]', 'to be safe (in mind, body or estate); figuratively, to be (causatively, make) completed; by implication, to be friendly; by extension, to reciprocate (in various applications) make amends, (make an) end, finish, full, give again, make good, (re-) pay (again), (make) (to) (be at) peace(-able), that is perfect, perform, (make) prosper(-ous), recompense, render, requite, make restitution, restore, reward, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8478G}/H9031/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["from/ under/ you"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2823}\/[H2821]', 'inflected', 'heb', 'חָשֹׁךְ', '["châshôk"]', '["insignificant [people]"]', '["a"]', 'dark (figuratively, i.e. obscure) meaning', 'from 2821;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3898B}/[H3898]', 'inflected', 'heb', 'לָחַם', '["lâcham"]', '["to/ eat"]', '["v"]', 'to feed on; figuratively, to consume; by implication, to battle (as destruction) devour, eat, × ever, fight(-ing), overcome, prevail, (make) war(-ring).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7915}/[H7906]', 'lemma', 'heb', 'שַׂכִּין', '["sakkîyn"]', '["a knife"]', '["n-m"]', 'a knife (as pointed or edged) knife.', 'intensive perhaps from the same as 7906 in the sense of 7753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3930}/H9021/[H3886]', 'inflected', 'heb', 'לֹעַ', '["lôaʻ"]', '["in/ throat/ your"]', '["n-m"]', 'the gullet throat.', 'from 3886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4303}/H9023/[H2938]', 'inflected', 'heb', 'מַטְעַם', '["maṭʻam"]', '["for/ dainties/ his"]', '["n-m"]', 'a delicacy dainty (meat), savoury meat.', 'or (feminine) מַטְעַמָּה; from 2938;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6238}/[H6238]', 'inflected', 'heb', 'עָשַׁר', '["ʻâshar"]', '["to/ gain riches"]', '["v"]', 'properly, to accumulate; chiefly (specifically) to grow (causatively, make) rich be(-come, en-, make, make self, wax) rich, make (1 Kings 22:48 marg). See 6240.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0998}/H9021/[H995]', 'inflected', 'heb', 'בִּינָה', '["bîynâh"]', '["from/ understanding/ your"]', '["n-f"]', 'understanding knowledge, meaning, × perfectly, understanding, wisdom.', 'from 995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5774A}/[H5775]', 'inflected', 'heb', 'עוּף', '["ʻûwph"]', '["¿/ do you cause to fly"]', '["v n-f"]', 'to fly; also (by implication of dimness) to faint (from the darkness of swooning) brandish, be (wax) faint, flee away, fly (away), × set, shine forth, weary.', 'a primitive root; to cover (with wings or obscurity); hence (as denominative from 5775)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8176}/[H8179]', 'lemma', 'heb', 'שָׁעַר', '["shâʻar"]', '["he calculates"]', '["v"]', 'to act as gatekeeper; (figuratively) to estimate think.', 'a primitive root; to split or open, i.e. (literally, but only as denominative from 8179); compare see 7778');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5315G}/H9023/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["in/ self/ his"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3820A}/H9023/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["and/ heart/ his","and/ heart/ its"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6595A}/H9021/[H6626]', 'inflected', 'heb', 'פַּת', '["path"]', '["morsel/ your"]', '["n-f"]', 'a bit meat, morsel, piece.', 'from 6626;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6958}/H9034/[H6958]', 'inflected', 'heb', 'קוֹא', '["qôwʼ"]', '["you will vomit up/ it"]', '["v"]', 'to vomit spue (out), vomit (out, up, up again).', 'or קָיָה; (Jeremiah 25:27), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5273A}/[H5276]', 'inflected', 'heb', 'נָעִים', '["nâʻîym"]', '["<the>/ pleasant"]', '["a"]', 'delightful (objective or subjective, literal or figurative) pleasant(-ure), sweet.', 'from 5276;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7922}/[H7919]', 'inflected', 'heb', 'שֶׂכֶל', '["sekel"]', '["<to>/ [the] insight of"]', '["n-m"]', 'intelligence; by implication, success discretion, knowledge, policy, prudence, sense, understanding, wisdom, wise.', 'or שֵׂכֶל; from 7919;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5315G}/H9023/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["and/ life/ his"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2400}/[H2398]', 'inflected', 'heb', 'חַטָּא', '["chaṭṭâʼ"]', '["<in>/ sinners"]', '["n-m"]', 'a criminal, or one accounted guilty offender, sinful, sinner.', 'intensively from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8615B}/H9021/[H6960]', 'inflected', 'heb', 'תִּקְוָה', '["tiqvâh"]', '["and/ hope/ your"]', '["n-f"]', 'literally a cord (as an attachment); figuratively, expectancy expectation(-ted), hope, live, thing that I long for.', 'from 6960; (compare 6961)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5433A}/[H5433]', 'inflected', 'heb', 'סָבָא', '["çâbâʼ"]', '["among/ drunkards of"]', '["v"]', 'to quaff to satiety, i.e. become tipsy drunkard, fill self, Sabean, (wine-) bibber.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2151B}/[H2107]', 'inflected', 'heb', 'זָלַל', '["zâlal"]', '["among/ gluttons of"]', '["v"]', 'to shake (as in the wind), i.e. to quake; figuratively, to be loose morally, worthless or prodigal blow down, glutton, riotous (eater), vile.', 'a primitive root (compare 2107);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5433A}/[H5433]', 'lemma', 'heb', 'סָבָא', '["çâbâʼ"]', '["a drunkard"]', '["v"]', 'to quaff to satiety, i.e. become tipsy drunkard, fill self, Sabean, (wine-) bibber.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2151B}/[H2107]', 'inflected', 'heb', 'זָלַל', '["zâlal"]', '["and/ a glutton"]', '["v"]', 'to shake (as in the wind), i.e. to quake; figuratively, to be loose morally, worthless or prodigal blow down, glutton, riotous (eater), vile.', 'a primitive root (compare 2107);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7168}/[H7167]', 'inflected', 'heb', 'קֶרַע', '["qeraʻ"]', '["and/ rags"]', '["n-m"]', 'a rag piece, rag.', 'from 7167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5124}/[H5123]', 'lemma', 'heb', 'נוּמָה', '["nûwmâh"]', '["drowsiness"]', '["n-f"]', 'sleepiness drowsiness.', 'from 5123;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8055}/[H8055]', 'inflected', 'heb', 'שָׂמַח', '["sâmach"]', '["in/ him"]', '["v"]', 'probably to brighten up, i.e. (figuratively) be (causatively, make) blithe or gleesome cheer up, be (make) glad, (have, make) joy(-ful), be (make) merry, (cause to, make to) rejoice, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0875}/[H874]', 'inflected', 'heb', 'בְּאֵר', '["bᵉʼêr"]', '["and/ [is] a well"]', '["n-f"]', 'a pit; especially a well pit, well.', 'from 874;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2863}/[H2862]', 'inflected', 'heb', 'חֶתֶף', '["chetheph"]', '["like/ a robber"]', '["n-m"]', 'properly, rapine; figuratively, robbery prey.', 'from 2862;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0017}/[H14]', 'lemma', 'heb', 'אֲבוֹי', '["ʼăbôwy"]', '["woe!"]', '["inj"]', 'want sorrow.', 'from 14 (in the sense of desiring);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2448}/[H2447]', 'lemma', 'heb', 'חַכְלִלוּת', '["chaklilûwth"]', '["dullness of"]', '["a"]', 'flash (of the eyes); in a bad sense, blearedness redness.', 'from 2447;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0309}/[H309]', 'inflected', 'heb', 'אָחַר', '["ʼâchar"]', '["to <the>/ [those who] delay"]', '["v"]', 'to loiter (i.e. be behind); by implication to procrastinate continue, defer, delay, hinder, be late (slack), stay (there), tarry (longer).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4469}/[H4537]', 'lemma', 'heb', 'מַמְסָךְ', '["mamçâk"]', '["mixed wine"]', '["n-m"]', 'mixture, i.e. (specifically) wine mixed (with water or spices) drink-offering, mixed wine.', 'from 4537;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3563A>', 'inflected', 'heb', 'בכוס', '["ba./kis"]', '["in the/ cup"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5175}/[H5172]', 'inflected', 'heb', 'נָחָשׁ', '["nâchâsh"]', '["[is] like <the>/ snake","like <the>/ snake","like/ a snake"]', '["n-m"]', 'a snake (from its hiss) serpent.', 'from 5172;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/<H6848B>', 'inflected', 'heb', 'וכצפעני', '["u./khe./tzif.''o.Ni"]', '["and/ like/ a viper"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6567B}/[H6567]', 'lemma', 'heb', 'פָּרָשׁ', '["pârâsh"]', '["it will sting"]', '["v"]', 'to separate, literally (to disperse) or figuratively (to specify); also (by implication) to wound scatter, declare, distinctly, shew, sting.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7901G}/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["like/ [one who] lies down"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H7901G}/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["and/ like/ [one who] lies down"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2260}/[H2254]', 'lemma', 'heb', 'חִבֵּל', '["chibbêl"]', '["a mast"]', '["n-m"]', 'a mast mast.', 'from 2254 (in the sense of furnished with ropes);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5273A}/[H5276]', 'inflected', 'heb', 'נָעִים', '["nâʻîym"]', '["and/ pleasant"]', '["a"]', 'delightful (objective or subjective, literal or figurative) pleasant(-ure), sweet.', 'from 5276;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5797}/[H5810]', 'inflected', 'heb', 'עֹז', '["ʻôz"]', '["[who is] in <the>/ strength","by/ [the] strength of","with/ strength"]', '["n-m"]', 'strength in various applications (force, security, majesty, praise) boldness, loud, might, power, strength, strong.', 'or (fully) עוֹז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8458}/[H2254]', 'inflected', 'heb', 'תַּחְבֻּלָה', '["tachbulâh"]', '["by/ wise directions"]', '["n-f"]', '(only in plural) properly, steerage (as a management of ropes), i.e. (figuratively) guidance or (by implication) a plan good advice, (wise) counsels.', 'or תַּחְבּוּלָה; from 2254 as denominative from 2256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4131}/[H4131]', 'inflected', 'heb', 'מוֹט', '["môwṭ"]', '["and/ [those who] are staggering"]', '["v"]', 'to waver; by implication, to slip, shake, fall be carried, cast, be out of course, be fallen in decay, × exceedingly, fall(-ing down), be (re-) moved, be ready, shake, slide, slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2027}/[H2026]', 'inflected', 'heb', 'הֶרֶג', '["hereg"]', '["to the/ slaughter"]', '["n-m"]', 'slaughter be slain, slaughter.', 'from 2026;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6467}/H9023/[H6466]', 'inflected', 'heb', 'פֹּעַל', '["pôʻal"]', '["according to/ deed/ his","according to/ work/ his"]', '["n-m"]', 'an act or work (concretely) act, deed, do, getting, maker, work.', 'from 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2441}/H9021/[H2596]', 'inflected', 'heb', 'חֵךְ', '["chêk"]', '["mouth/ your","palate/ your"]', '["n-m"]', 'properly, the palate or inside of the mouth; hence, the mouth itself (as the organ of speech, taste and kissing) (roof of the) mouth, taste.', 'probably from 2596 in the sense of tasting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3045}/H9012/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["know/ !"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3772I}\/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["it will be cut down","it will be cut off","may they be cut off"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5116A}/[H5115]', 'inflected', 'heb', 'נָוֶה', '["nâveh"]', '["<into>/ a pasture of","into/ a pasture of","to/ [the] habitation of"]', '["n"]', '(adjectively) at home; hence (by implication of satisfaction) lovely; also (noun) a home, of God (temple), men (residence), flocks (pasture), or wild animals (den) comely, dwelling (place), fold, habitation, pleasant place, sheepcote, stable, tarried.', 'or (feminine) נָוָה; from 5115;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7258}/H9023/[H7257]', 'inflected', 'heb', 'רֵבֶץ', '["rêbets"]', '["resting place/ his"]', '["n-m"]', 'a couch or place of repose where each lay, lie down in, resting place.', 'from 7257;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3782}/H9043/[H3782]', 'inflected', 'heb', 'כָּשַׁל', '["kâshal"]', '["and/ when/ stumbles/ he"]', '["v"]', 'to totter or waver (through weakness of the legs, especially the ankle); by implication, to falter, stumble, faint or fall bereave (from the margin), cast down, be decayed, (cause to) fail, (cause, make to) fall (down, -ing), feeble, be (the) ruin(-ed, of), (be) overthrown, (cause to) stumble, × utterly, be weak.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7563}/[H7561]', 'inflected', 'heb', 'רָשָׁע', '["râshâʻ"]', '["of <the>/ wicked [people]"]', '["a"]', 'morally wrong; concretely, an (actively) bad person condemned, guilty, ungodly, wicked (man), that did wrong.', 'from 7561;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7451H}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["to the/ evil [person]"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6365>', 'inflected', 'heb', 'ופיד', '["u./Fid"]', '["and/ [the] disaster of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2194}/H9033/[H2194]', 'inflected', 'heb', 'זָעַם', '["zâʻam"]', '["they will denounce/ him"]', '["v"]', 'properly, to foam at the mouth, i.e. to be enraged abhor, abominable, (be) angry, defy, (have) indignation.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3198}/[H3198]', 'inflected', 'heb', 'יָכַח', '["yâkach"]', '["and/ for the/ [one who] adjudicates","and/ for the/ [ones who] rebuke [them]"]', '["v"]', 'to be right (i.e. correct); reciprocal, to argue; causatively, to decide, justify or convict appoint, argue, chasten, convince, correct(-ion), daysman, dispute, judge, maintain, plead, reason (together), rebuke, reprove(-r), surely, in any wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6257}/H9034/[H6257]', 'inflected', 'heb', 'עָתַד', '["ʻâthad"]', '["and/ make ready/ it"]', '["v"]', 'to prepare make fit, be ready to become.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004B}/H9021\/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["house/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9008/{H6601A}/[H6601]', 'inflected', 'heb', 'פָּתָה', '["pâthâh"]', '["and/ ¿/ will you deceive"]', '["v"]', 'to open, i.e. be (causatively, make) roomy; usually figuratively (in a mental or moral sense) to be (causatively, make) simple or (in a sinister way) delude allure, deceive, enlarge, entice, flatter, persuade, silly (one).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7063}/[H7057]', 'lemma', 'heb', 'קִמָּשׁוֹן', '["qimmâshôwn"]', '["thorns"]', '["n-m"]', 'a prickly plant thorn.', 'from the same as 7057;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440J}/H9023/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["face/ its","surface<s>/ its"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1444}/[H1443]', 'inflected', 'heb', 'גֶּדֶר', '["geder"]', '["and/ [the] wall of"]', '["n-m"]', 'a circumvallation wall.', 'from 1443;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7312}/[H7311]', 'inflected', 'heb', 'רוּם', '["rûwm"]', '["for <the>/ height"]', '["n-m"]', '(literally) elevation or (figuratively) elation haughtiness, height, × high.', 'or רֻם; from 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6011}/[H6009]', 'inflected', 'heb', 'עֹמֶק', '["ʻômeq"]', '["for <the>/ depth"]', '["n-m"]', 'depth depth.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1898}/[H1898]', 'lemma', 'heb', 'הָגָה', '["hâgâh"]', '["he drove out","remove"]', '["v"]', 'to remove stay, stay away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8213}/H9031/[H8213]', 'inflected', 'heb', 'שָׁפֵל', '["shâphêl"]', '["than/ to set low/ you"]', '["v"]', 'to depress or sink (especially figuratively, to humiliate, intransitive or transitive) abase, bring (cast, put) down, debase, humble (self), be (bring, lay, make, put) low(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0319}/H9024/[H310]', 'inflected', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["at/ end/ its"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3637}/[H3637]', 'inflected', 'heb', 'כָּלַם', '["kâlam"]', '["when/ puts to shame"]', '["v"]', 'properly, to wound; but only figuratively, to taunt or insult be (make) ashamed, blush, be confounded, be put to confusion, hurt, reproach, (do, put to) shame.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5475}/[H3245]', 'inflected', 'heb', 'סוֹד', '["çôwd"]', '["and/ [the] secret of"]', '["n-m"]', 'a session, i.e. company of persons (in close deliberation); by implication, intimacy, consultation, a secret assembly, consel, inward, secret (counsel).', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2616B}/H9031/[H2616]', 'inflected', 'heb', 'חָסַד', '["châçad"]', '["he should bring shame/ you"]', '["v"]', 'properly, perhaps to bow (the neck only [compare 2603] in courtesy to an equal), i.e. to be kind; also (by euphemistically [compare 1288], but rarely) to reprove shew self merciful, put to shame.', 'a primitive root');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1681}/H9021/[H1680]', 'inflected', 'heb', 'דִּבָּה', '["dibbâh"]', '["and/ evil report/ your"]', '["n-f"]', 'slander defaming, evil report, infamy, slander.', 'from 1680 (in the sense of furtive motion);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8598}/[H5301]', 'lemma', 'heb', 'תַּפּוּחַ', '["tappûwach"]', '["apples of"]', '["n-m"]', 'an apple (from its fragrance), i.e. the fruit or the tree (probably includ. others of the pome order, as the quince, the orange, etc.) apple (tree). See also 1054.', 'from 5301;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4906}/[H7906]', 'inflected', 'heb', 'מַשְׂכִּית', '["maskîyth"]', '["in/ settings of"]', '["n-f"]', 'a figure (carved on stone, the wall, or any object); figuratively, imagination conceit, image(-ry), picture, × wish.', 'from the same as 7906;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0655>/H9023', 'opaque', 'heb', 'אֹפֶן', '["ʼôphen"]', '["proper times/ its"]', '["n-m"]', 'a turn, i.e. a season fitly.', 'from an unused root meaning to revolve;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2481}/[H2470]', 'inflected', 'heb', 'חֲלִי', '["chălîy"]', '["and/ an ornament of"]', '["n-m"]', 'a trinket (as polished) jewel, ornament.', 'from 2470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3800}/[H3799]', 'lemma', 'heb', 'כֶּתֶם', '["kethem"]', '["[is] gold of","pure gold"]', '["n-m"]', 'properly, something carved out, i.e. ore; hence, gold (pure as originally mined) ((most) fine, pure) gold(-en wedge).', 'from 3799;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6793B}/[H6791]', 'inflected', 'heb', 'צִנָּה', '["tsinnâh"]', '["[is] like/ [the] cold of"]', '["n-f"]', 'a hook (as pointed); also a (large) shield (as if guarding by prickliness); also cold (as piercing) buckler, cold, hook, shield, target.', 'feminine of 6791;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6735A}/[H6696]', 'lemma', 'heb', 'צִיר', '["tsîyr"]', '["an envoy","envoys"]', '["n-m"]', 'a hinge (as pressed in turning); also a throe (as a phys. or mental pressure); also a herald or errand-doer (as constrained by the principal) ambassador, hinge, messenger, pain, pang, sorrow. Compare 6736.', 'from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725H}\/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["he will restore"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4991}/[H4976]', 'inflected', 'heb', 'מַתָּת', '["mattâth"]', '["in/ a gift of"]', '["n-f"]', 'a present gift.', 'feminine of 4976 abbreviated form;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1767>/H9021', 'opaque', 'heb', 'דַּי', '["day"]', '["sufficiency/ your"]', '["prep"]', 'enough (as noun or adverb), used chiefly with preposition in phrases able, according to, after (ability), among, as (oft as), (more than) enough, from, in, since, (much as is) sufficient(-ly), too much, very, when.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8130}/H9031/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["and/ he will hate/ you"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4650}/[H6327]', 'lemma', 'heb', 'מֵפִיץ', '["mêphîyts"]', '["a war-club"]', '["n-m"]', 'a breaker, i.e. mallet maul.', 'from 6327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7465}/[H7455]', 'lemma', 'heb', 'רֹעָה', '["rôʻâh"]', '["broken"]', '["v"]', 'breakage broken, utterly.', 'for 7455;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5427}/[H5425]', 'lemma', 'heb', 'נֶתֶר', '["nether"]', '["soda"]', '["n-m"]', 'mineral potash (so called from effervescing with acid) nitre.', 'from 5425;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7451A}\/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["sad"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2846}/[H2846]', 'lemma', 'heb', 'חָתָה', '["châthâh"]', '["[will] snatch up"]', '["v"]', 'to lay hold of; especially to pick up fire heap, take (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7119>', 'opaque', 'heb', 'קַר', '["qar"]', '["cool"]', '["a"]', 'cool; figuratively, quiet cold, excellent (from the margin).', 'contracted from an unused root meaning to chill;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8052}/[H8074]', 'inflected', 'heb', 'שְׁמוּעָה', '["shᵉmûwʻâh"]', '["and/ a report","and/ report","and/ reports"]', '["n-f"]', 'something heard, i.e. an announcement bruit, doctrine, fame, mentioned, news, report, rumor, tidings.', 'feminine passive participle of 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4801}/[H7368]', 'lemma', 'heb', 'מֶרְחָק', '["merchâq"]', '["[the] distant places of","distance","distance<s>","distances"]', '["n-m"]', 'remoteness, i.e. (concretely) a distant place; often (adverbially) from afar (a-, dwell in, very) far (country, off). See also 1023.', '; from 7368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7515}/[H7515]', 'lemma', 'heb', 'רָפַשׂ', '["râphas"]', '["fouled"]', '["v"]', 'to trample, i.e. roil water foul, trouble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4726}/[H6979]', 'inflected', 'heb', 'מָקוֹר', '["mâqôwr"]', '["and/ a fountain"]', '["n-m"]', 'properly, something dug, i.e. a (general) source (of water, even when naturally flowing; also of tears, blood (by euphemism, of the female pudenda); figuratively, of happiness, wisdom, progeny) fountain, issue, spring, well(-spring).', 'or מָקֹר; from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2714}/[H2713]', 'inflected', 'heb', 'חֵקֶר', '["chêqer"]', '["and/ [the] search of"]', '["n-m"]', 'examination, enumeration, deliberation finding out, number, (un-) search(-able, -ed, out, -ing).', 'from 2713;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4623}/[H6113]', 'lemma', 'heb', 'מַעְצָר', '["maʻtsâr"]', '["control"]', '["n-m"]', 'subjectively, control rule.', 'from 6113;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7307J}/H9023/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["[belongs] to/ spirit/ his"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H4306}/[H4305]', 'inflected', 'heb', 'מָטַר', '["mâṭar"]', '["and/ like <the>/ rain"]', '["n-m"]', 'rain rain.', 'from 4305;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1866}/[H1865]', 'inflected', 'heb', 'דְּרוֹר', '["dᵉrôwr"]', '["like <the>/ swallow"]', '["n-f"]', 'the swift, a kind of swallow swallow.', 'the same as 1865, applied to a bird;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5774A}/[H5775]', 'inflected', 'heb', 'עוּף', '["ʻûwph"]', '["for/ flying"]', '["v n-f"]', 'to fly; also (by implication of dimness) to faint (from the darkness of swooning) brandish, be (wax) faint, flee away, fly (away), × set, shine forth, weary.', 'a primitive root; to cover (with wings or obscurity); hence (as denominative from 5775)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4964>', 'opaque', 'heb', 'מֶתֶג', '["metheg"]', '["a bridle"]', '["n-m"]', 'a bit bit, bridle.', 'from an unused root meaning to curb;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0200}/H9023/[H191]', 'inflected', 'heb', 'אִוֶּלֶת', '["ʼivveleth"]', '["according to/ foolishness/ his"]', '["n-f"]', 'silliness folly, foolishly(-ness).', 'from the same as 191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6455}/[H6452]', 'inflected', 'heb', 'פִּסֵּחַ', '["piççêach"]', '["from/ a lame [person]"]', '["a"]', 'lame lame.', 'from 6452;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4912}/[H4910]', 'inflected', 'heb', 'מָשָׁל', '["mâshâl"]', '["and/ a proverb"]', '["n-m"]', 'properly, a pithy maxim, usually of metaphorical nature; hence, a simile (as an adage, poem, discourse) byword, like, parable, proverb.', 'apparently from 4910 in some original sense of superiority in mental action;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6887B}/[H6887]', 'inflected', 'heb', 'צָרַר', '["tsârar"]', '["as/ ties"]', '["v"]', 'to cramp, literally or figuratively, transitive or intransitive adversary, (be in) afflict(-ion), beseige, bind (up), (be in, bring) distress, enemy, narrower, oppress, pangs, shut up, be in a strait (trouble), vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4773}/[H7275]', 'inflected', 'heb', 'מַרְגֵּמָה', '["margêmâh"]', '["in/ a sling"]', '["n-f"]', 'a stone-heap sling.', 'from 7275;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7228}/[H7232]', 'lemma', 'heb', 'רַב', '["rab"]', '["an archer","archers"]', '["n-m"]', 'an archer archer.', 'by contraction from 7232; (or perhaps the same as 7227)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7936B}/[H3739]', 'inflected', 'heb', 'שָׂכַר', '["sâkar"]', '["and/ [one who] hires"]', '["v"]', 'to hire earn wages, hire (out self), reward, × surely.', 'or (by permutation) סָכַר; (Ezra 4:5), a primitive root (apparently akin (by prosthesis) to 3739 through the idea of temporary purchase; compare 7937);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6892A}/H9023/[H6958]', 'inflected', 'heb', 'קֵא', '["qêʼ"]', '["own vomit/ its"]', '["n-m"]', 'vomit vomit.', 'or קִיא; from 6958;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6735B}/H9024/[H6696]', 'inflected', 'heb', 'צִיר', '["tsîyr"]', '["hinge[s]/ its"]', '["n-m"]', 'a hinge (as pressed in turning); also a throe (as a phys. or mental pressure); also a herald or errand-doer (as constrained by the principal) ambassador, hinge, messenger, pain, pang, sorrow. Compare 6736.', 'from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6102}/[H6101]', 'inflected', 'heb', 'עָצֵל', '["ʻâtsêl"]', '["and/ a sluggard"]', '["a"]', 'indolent slothful, sluggard.', 'from 6101;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3856B}/[H3856]', 'inflected', 'heb', 'לָהַהּ', '["lâhahh"]', '["like/ a madman"]', '["v"]', 'to be rabid (figuratively, insane); also (from the exhaustion of frenzy) to languish faint, mad.', 'a primitive root meaning properly, to burn, i.e. (by implication)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2131A}/[H2187]', 'lemma', 'heb', 'זִיקָה', '["zîyqâh"]', '["<of> firebrands","burning arrows"]', '["n-m"]', 'properly, what leaps forth, i.e. flash of fire, or a burning arrow; also (from the original sense of the root) a bond chain, fetter, firebrand, spark.', '(Isaiah 50:11) (feminine); and זִק; or זֵק; from 2187;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0369}/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["and/ with/ not"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6352>', 'opaque', 'heb', 'פֶּחָם', '["pechâm"]', '["charcoal"]', '["n-m"]', 'a coal, whether charred or live coals.', 'perhaps from an unused root probably meaning to be black;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H1513>', 'inflected', 'heb', 'לגחלים', '["Le./ge.cha.lim"]', '["to/ burning coals"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0784}/[H784]', 'inflected', 'heb', 'אֵשׁ', '["ʼêsh"]', '["<into>/ a fire","[belonged] to the/ fire","for the/ fire","into/ a fire","to the/ fire","to/ fire"]', '["n-f"]', 'fire (literally or figuratively) burning, fiery, fire, flaming, hot.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2787}/[H2787]', 'inflected', 'heb', 'חָרַר', '["chârar"]', '["to/ kindling"]', '["v"]', 'to glow, i.e. literally (to melt, burn, dry up) or figuratively (to show or incite passion) be angry, burn, dry, kindle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7379}\/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["strife"]', '["n-m"]', 'a contest (personal or legal) adversary, cause, chiding, contend(-tion), controversy, multitude (from the margin), pleading, strife, strive(-ing), suit.', 'or רִב; from 7378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4860}/[H5377]', 'inflected', 'heb', 'מַשָּׁאוֹן', '["mashshâʼôwn"]', '["with/ deception"]', '["n-m"]', 'dissimulation deceit.', 'from 5377;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7451I}/H9023/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["wickedness/ his"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1556}/[H1556]', 'inflected', 'heb', 'גָּלַל', '["gâlal"]', '["and/ [one who] rolls","and/ it may roll on"]', '["v"]', 'to roll (literally or figuratively) commit, remove, roll (away, down, together), run down, seek occasion, trust, wallow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1790>/H9023', 'opaque', 'heb', 'דַּךְ', '["dak"]', '["crushed [people]/ its"]', '["a"]', 'crushed, i.e. (figuratively) injured afflicted, oppressed.', 'from an unused root (compare 1794);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4072}/[H1760]', 'lemma', 'heb', 'מִדְחֶה', '["midcheh"]', '["stumbling"]', '["n-m"]', 'overthrow ruin.', 'from 1760;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3514}/[H3513]', 'lemma', 'heb', 'כֹּבֶד', '["kôbed"]', '["[the] heaviness of","[the] weight of"]', '["n-m"]', 'weight, multitude, vehemence grievousness, heavy, great number.', 'from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5192}/[H5190]', 'inflected', 'heb', 'נֵטֶל', '["nêṭel"]', '["and/ [the] weight of"]', '["n-m"]', 'a burden weighty.', '; from 5190;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2344}/[H2342]', 'inflected', 'heb', 'חוֹל', '["chôwl"]', '["<the>/ sand"]', '["n-m"]', 'sand (as round or whirling particles) sand.', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8147}/H9028/[H8145]', 'inflected', 'heb', 'שְׁנַיִם', '["shᵉnayim"]', '["more than/ both of/ them"]', '["n"]', 'two; also (as ordinal) twofold both, couple, double, second, twain, twelfth, twelve, twenty (sixscore) thousand, twice, two.', 'dual of 8145; feminine שְׁתַּיִם;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0395}/[H394]', 'lemma', 'heb', 'אַכְזְרִיּוּת', '["ʼakzᵉrîyûwth"]', '["[the] cruelty of"]', '["n-f"]', 'fierceness cruel.', 'from 394;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7858}/[H7857]', 'inflected', 'heb', 'שֶׁטֶף', '["sheṭeph"]', '["and/ [the] flood of"]', '["n-m"]', 'a deluge (literally or figuratively) flood, outrageous, overflowing.', 'or שֵׁטֶף; from 7857;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6280}/[H6280]', 'inflected', 'heb', 'עָתַר', '["ʻâthar"]', '["and/ [are] abundant"]', '["v"]', 'to be (causatively, make) abundant deceitful, multiply.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5390}/[H5401]', 'lemma', 'heb', 'נְשִׁיקָה', '["nᵉshîyqâh"]', '["[the] kisses of"]', '["n-f"]', 'a kiss kiss.', 'from 5401;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7064}/H9024/[H7077]', 'inflected', 'heb', 'קֵן', '["qên"]', '["nest/ its"]', '["n-m"]', 'a nest (as fixed), sometimes including the nestlings; figuratively, a chamber or dwelling nest, room.', 'contracted from 7077;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0343}/H9021/[H181]', 'inflected', 'heb', 'אֵיד', '["ʼêyd"]', '["calamity/ your"]', '["n-m"]', 'oppression; by implication misfortune, ruin calamity, destruction.', 'from the same as 181 (in the sense of bending down);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7934}/[H7931]', 'lemma', 'heb', 'שָׁכֵן', '["shâkên"]', '["[the] inhabitant[s] of","a neighbor","an inhabitant"]', '["a"]', 'a resident; by extension, a fellow-citizen inhabitant, neighbour, nigh.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1812}/[H1811]', 'lemma', 'heb', 'דֶּלֶף', '["deleph"]', '["a dripping"]', '["n-m"]', 'a dripping dropping.', 'from 1811;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5464}/[H5462]', 'lemma', 'heb', 'סַגְרִיד', '["çagrîyd"]', '["persistent rain"]', '["n-m"]', 'a pouring rain very rainy.', 'probably from 5462 in the sense of sweeping away;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6845}/H9034/[H6845]', 'inflected', 'heb', 'צָפַן', '["tsâphan"]', '["[those who] hide/ her"]', '["v"]', 'to hide (by covering over); by implication, to hoard or reserve; figuratively to deny; specifically (favorably) to protect, (unfavorably) to lurk esteem, hide(-den one, self), lay up, lurk (be set) privily, (keep) secret(-ly, place).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7122H}/[H7122]', 'lemma', 'heb', 'קָרָא', '["qârâʼ"]', '["it meets"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2300B}/[H2300]', 'lemma', 'heb', 'חָדַד', '["châdad"]', '["he sharpens","it grows sharp"]', '["v"]', 'to be (causatively, make) sharp or (figuratively) severe be fierce, sharpen.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0010}/H9023/[H9]', 'inflected', 'heb', 'אֲבַדֹּה', '["ʼăbaddôh"]', '["and/ destruction/ its"]', '["n-f"]', 'a perishing destruction.', 'the same as 9, miswritten for 11;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4110}/H9023/[H1984]', 'inflected', 'heb', 'מַהֲלָל', '["mahălâl"]', '["praise/ his"]', '["n-m"]', 'fame praise.', 'from 1984;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3806}/[H3806]', 'lemma', 'heb', 'כָּתַשׁ', '["kâthash"]', '["you will pound"]', '["v"]', 'to butt or pound bray.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0191>', 'inflected', 'heb', 'האויל', '["ha./''e.Vil"]', '["the/ fool"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4388}/[H3806]', 'inflected', 'heb', 'מַכְתֵּשׁ', '["maktêsh"]', '["in <the>/ mortar"]', '["n-m"]', 'a mortar; by analogy, a socket (of a tooth) hollow place, mortar.', 'from 3806;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5940}/[H5927]', 'inflected', 'heb', 'עֱלִי', '["ʻĕlîy"]', '["with the/ pestle"]', '["n-m"]', 'a pestle (as lifted) pestle.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0200}/H9023\/[H191]', 'inflected', 'heb', 'אִוֶּלֶת', '["ʼivveleth"]', '["foolishness/ his"]', '["n-f"]', 'silliness folly, foolishly(-ness).', 'from the same as 191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5739}/[H5737]', 'inflected', 'heb', 'עֵדֶר', '["ʻêder"]', '["for/ flocks","to/ [the] herds"]', '["n-m"]', 'an arrangement, i.e. muster (of animals) drove, flock, herd.', 'from 5737;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3830}/H9021/[H3847]', 'inflected', 'heb', 'לְבוּשׁ', '["lᵉbûwsh"]', '["[are] for/ clothing/ your","[belong] to/ clothing/ your"]', '["n-m"]', 'a garment (literally or figuratively); by implication (euphemistically) a wife apparel, clothed with, clothing, garment, raiment, vestment, vesture.', 'or לְבֻשׁ; from 3847;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1767>', 'inflected', 'heb', 'ודי', '["ve./Dei"]', '["and/ a sufficiency of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3899G}/H9021/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["for/ food/ your"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3899G}/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["<into>/ food","for/ [the] food of"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8269}/H9024/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["officials/ its","princes/ her","princes/ its"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0120G}/[H119]', 'inflected', 'heb', 'אָדָם', '["ʼâdâm"]', '["and/ among <the>/ humankind","and/ by/ a person"]', '["n-m"]', 'ruddy i.e. a human being (an individual or the species, mankind, etc.) × another, hypocrite, common sort, × low, man (mean, of low degree), person.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6231}/[H6229]', 'inflected', 'heb', 'עָשַׁק', '["ʻâshaq"]', '["and/ [who] oppresses"]', '["v"]', 'to press upon, i.e. oppress, defraud, violate, overflow get deceitfully, deceive, defraud, drink up, (use) oppress(-ion), -or), do violence (wrong).', 'a primitive root (compare 6229);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5502}/[H5502]', 'lemma', 'heb', 'סָחַף', '["çâchaph"]', '["[which] washes away","will he be prostrated"]', '["v"]', 'to scrape off sweep (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1952}/H9023/[H1951]', 'inflected', 'heb', 'הוֹן', '["hôwn"]', '["wealth/ his"]', '["n-m"]', 'wealth; by implication, enough enough, for nought, riches, substance, wealth.', 'from the same as 1951 in the sense of 202;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6908}/H9033/[H6908]', 'inflected', 'heb', 'קָבַץ', '["qâbats"]', '["he gathers/ it","he will gather/ it"]', '["v"]', 'to grasp, i.e. collect assemble (selves), gather (bring) (together, selves together, up), heap, resort, × surely, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8085G}/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["for/ hearing","from/ hearing"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8605}/H9023/[H6419]', 'inflected', 'heb', 'תְּפִלָּה', '["tᵉphillâh"]', '["prayer/ his"]', '["n-f"]', 'intercession, supplication; by implication, a hymn prayer.', 'from 6419;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7816}/H9023/[H7812]', 'inflected', 'heb', 'שְׁחוּת', '["shᵉchûwth"]', '["in/ own pit/ his"]', '["n-f"]', 'pit pit.', 'from 7812;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5970}/[H5970]', 'inflected', 'heb', 'עָלַץ', '["ʻâlats"]', '["when/ rejoice"]', '["v"]', 'to jump for joy, i.e. exult be joyful, rejoice, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6965B}/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["and/ when/ arise"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6588}/H9023/[H6586]', 'inflected', 'heb', 'פֶּשַׁע', '["peshaʻ"]', '["transgression/ his","transgression/ its","transgressions/ his"]', '["n-m"]', 'a revolt (national, moral or religious) rebellion, sin, transgression, trespass.', 'from 6586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7185}/[H7185]', 'inflected', 'heb', 'קָשָׁה', '["qâshâh"]', '["and/ [one who] hardens"]', '["v"]', 'properly, to be dense, i.e. tough or severe (in various applications) be cruel, be fiercer, make grievous, be ((ask a), be in, have, seem, would) hard(-en, (labour), -ly, thing), be sore, (be, make) stiff(-en, (-necked)).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5098}/[H5098]', 'lemma', 'heb', 'נָהַם', '["nâham"]', '["roaring"]', '["v"]', 'to growl mourn, roar(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1677}/[H1680]', 'inflected', 'heb', 'דֹּב', '["dôb"]', '["and/ a bear","and/ bear"]', '["n"]', 'the bear (as slow) bear.', 'or (fully) דּוֹב; from 1680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4642}/[H6231]', 'lemma', 'heb', 'מַעֲשַׁקָּה', '["maʻăshaqqâh"]', '["extortion<s>"]', '["n-f"]', 'oppression oppression, × oppressor.', 'from 6231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7389B}/[H7326]', 'lemma', 'heb', 'רֵישׁ', '["rêysh"]', '["poverty"]', '["n-m"]', 'poverty poverty.', 'or רֵאשׁ; or רִישׁ; from 7326;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1952}/[H1951]', 'inflected', 'heb', 'הוֹן', '["hôwn"]', '["to <the>/ wealth"]', '["n-m"]', 'wealth; by implication, enough enough, for nought, riches, substance, wealth.', 'from the same as 1951 in the sense of 202;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2639}/[H2637]', 'lemma', 'heb', 'חֶסֶר', '["cheçer"]', '["poverty"]', '["n-m"]', 'lack; hence, destitution poverty, want.', 'from 2637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0310B}/H9030/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["after/ me"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2505B}/[H2505]', 'inflected', 'heb', 'חָלַק', '["châlaq"]', '["more than/ [one who] makes smooth"]', '["v"]', 'to be smooth (figuratively); by implication (as smooth stones were used for lots) to apportion or separate deal, distribute, divide, flatter, give, (have, im-) part(-ner), take away a portion, receive, separate self, (be) smooth(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7342I}/[H7337]', 'lemma', 'heb', 'רָחָב', '["râchâb"]', '["a [person] arrogant of"]', '["a"]', 'roomy, in any (or every) direction, literally or figuratively broad, large, at liberty, proud, wide.', 'from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0006}/H9048/[H6]', 'inflected', 'heb', 'אָבַד', '["ʼâbad"]', '["and/ when/ perish/ they"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7235A}/[H7235]', 'inflected', 'heb', 'רָבָה', '["râbâh"]', '["when/ increase","when/ increases"]', '["v"]', 'to increase (in whatever respect) (bring in) abundance (× -antly), archer (by mistake for 7232), be in authority, bring up, × continue, enlarge, excel, exceeding(-ly), be full of, (be, make) great(-er, -ly, × -ness), grow up, heap, increase, be long, (be, give, have, make, use) many (a time), (any, be, give, give the, have) more (in number), (ask, be, be so, gather, over, take, yield) much (greater, more), (make to) multiply, nourish, plenty(-eous), × process (of time), sore, store, thoroughly, very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4910}/[H4910]', 'inflected', 'heb', 'מָשַׁל', '["mâshal"]', '["and/ when/ rules"]', '["v"]', 'to rule (have, make to have) dominion, governor, × indeed, reign, (bear, cause to, have) rule(-ing, -r), have power.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0584}/[H584]', 'lemma', 'heb', 'אָנַח', '["ʼânach"]', '["<she> has groaned","[are] groaning","[was] groaning","groan","groaning","it sighs","they have groaned","you will groan"]', '["v"]', 'to sigh groan, mourn, sigh.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2040}/H9034/[H2040]', 'inflected', 'heb', 'הָרַס', '["hâraç"]', '["he breaks down/ it"]', '["v"]', 'to pull down or in pieces, break, destroy beat down, break (down, through), destroy, overthrow, pluck down, pull down, ruin, throw down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5183A}/[H5182]', 'lemma', 'heb', 'נַחַת', '["Nachath"]', '["[is] rest","quietness","rest"]', '["n"]', 'a descent, i.e. imposition, unfavorable (punishment) or favorable (food); restfulness lighting down, quiet(-ness), to rest, be set on.', 'from 5182; also (intransitively; perhaps from 5117)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7307J}/H9023/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["spirit/ his"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0268}/[H299]', 'inflected', 'heb', 'אָחוֹר', '["ʼâchôwr"]', '["in/ backwards"]', '["n-m"]', 'the hinder part; hence (adverb) behind, backward; also (as facing north) the West after(-ward), back (part, -side, -ward), hereafter, (be-) hind(-er part), time to come, without.', 'or (shortened) אָחֹר ; from 299;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7623A}/H9034/[H7623]', 'inflected', 'heb', 'שָׁבַח', '["shâbach"]', '["he calms/ it"]', '["v"]', 'properly, to address in a loud tone, i.e. (specifically) loud; figuratively, to pacify (as if by words) commend, glory, keep in, praise, still, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4658}/H9028/[H5307]', 'inflected', 'heb', 'מַפֶּלֶת', '["mappeleth"]', '["on/ overthrow/ their"]', '["n-f"]', 'fall, i.e. decadence; concretely, a ruin; specifically a carcase carcase, fall, ruin.', 'from 5307;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5117}/H9031/[H5117]', 'inflected', 'heb', 'נוּחַ', '["nûwach"]', '["so/ he may give rest/ you"]', '["v"]', 'to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5315G}/H9021\/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["to/ self/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6445}/[H6445]', 'lemma', 'heb', 'פָּנַק', '["pânaq"]', '["[one who] pampers"]', '["v"]', 'to enervate bring up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4497}/[H5125]', 'lemma', 'heb', 'מָנוֹן', '["mânôwn"]', '["trouble"]', '["n-m"]', 'a continuator, i.e. heir son.', 'from 5125;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1167I}/[H1166]', 'inflected', 'heb', 'בַּעַל', '["baʻal"]', '["and/ a master of","and/ an owner"]', '["n-m"]', 'a master; hence, a husband, or (figuratively) owner (often used with another noun in modifications of this latter sense) archer, babbler, bird, captain, chief man, confederate, have to do, dreamer, those to whom it is due, furious, those that are given to it, great, hairy, he that hath it, have, horseman, husband, lord, man, married, master, person, sworn, they of.', 'from 1166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8213}/H9033/[H8213]', 'inflected', 'heb', 'שָׁפֵל', '["shâphêl"]', '["it will bring low/ him"]', '["v"]', 'to depress or sink (especially figuratively, to humiliate, intransitive or transitive) abase, bring (cast, put) down, debase, humble (self), be (bring, lay, make, put) low(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870G}\/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["way"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0094}/[H103]', 'lemma', 'heb', 'אָגוּר', '["ʼÂgûwr"]', '["Agur"]', '["n-pr-m"]', 'Agur, a fanciful name for Solomon Agur.', 'passive participle of 103; gathered (i.e. received among the sages);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3348>', 'opaque', 'heb', 'יָקֶה', '["Yâqeh"]', '["Jakeh"]', '["n-pr-m"]', 'Jakeh, a symbolical name (for Solomon) Jakeh.', 'from an unused root probably meaning to obey; obedient;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0384H}/[H837]', 'inflected', 'heb', 'אִיתִיאֵל', '["ʼÎythîyʼêl"]', '["to/ Ithiel"]', '["n-pr-m"]', 'Ithiel, the name of an Israelite, also of a symbolical person Ithiel.', 'perhaps from 837 and 410; God has arrived;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0401}/[H398]', 'inflected', 'heb', 'אֻכָל', '["ʼUkâl"]', '["and/ Ukal"]', '["n-pr-m"]', 'Ucal, a fancy name Ucal.', 'or אֻכָּל; apparently from 398; devoured;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2651>/H9023', 'inflected', 'heb', 'בחפניו', '["be./cha.fe.Na/v"]', '["in/ hands/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3576}\/[H3576]', 'inflected', 'heb', 'כָּזַב', '["kâzab"]', '["and/ you will be proved a liar"]', '["v"]', 'to lie (i.e. deceive), literally or figuratively fail, (be found a, make a) liar, lie, lying, be in vain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2963}/H9030/[H2963]', 'inflected', 'heb', 'טָרַף', '["ṭâraph"]', '["let devour/ me"]', '["v"]', 'to pluck off or pull to pieces; causatively to supply with food (as in morsels) catch, × without doubt, feed, ravin, rend in pieces, × surely, tear (in pieces).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430G}/H9020\/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["God/ my","[is] God/ my"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7043}/H9031/[H7043]', 'inflected', 'heb', 'קָלַל', '["qâlal"]', '["cursing/ you","he should curse/ you"]', '["v"]', 'to be (causatively, make) light, literally (swift, small, sharp, etc.) or figuratively (easy, trifling, vile, etc.) abate, make bright, bring into contempt, (ac-) curse, despise, (be) ease(-y, -ier), (be a, make, make somewhat, move, seem a, set) light(-en, -er, -ly, -ly afflict, -ly esteem, thing), × slight(-ly), be swift(-er), (be, be more, make, re-) vile, whet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6675}/H9023/[H6674]', 'inflected', 'heb', 'צוֹאָה', '["tsôwʼâh"]', '["and/ from/ excrement/ its"]', '["n-f"]', 'excrement; generally, dirt; figuratively, pollution dung, filth(-iness). Marg. for 2716.', 'or צֹאָה ; feminine of 6674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6079}/H9023/[H5774]', 'inflected', 'heb', 'עַפְעַף', '["ʻaphʻaph"]', '["and/ eyelids/ its"]', '["n-m"]', 'an eyelash (as fluttering); figuratively, morning ray dawning, eye-lid.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3979}/[H398]', 'inflected', 'heb', 'מַאֲכֶלֶת', '["maʼăkeleth"]', '["and/ [are] knives"]', '["n-f"]', 'something to eat with, i.e. a knife knife.', 'from 398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4973}/H9023/[H3216]', 'inflected', 'heb', 'מְתַלְּעָה', '["mᵉthallᵉʻâh"]', '["jaw bones/ its"]', '["n-f"]', 'properly, a biter, i.e. a tooth cheek (jaw) tooth, jaw.', 'contr. from 3216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0120G}\/[H119]', 'inflected', 'heb', 'אָדָם', '["ʼâdâm"]', '["from/ humankind"]', '["n-m"]', 'ruddy i.e. a human being (an individual or the species, mankind, etc.) × another, hypocrite, common sort, × low, man (mean, of low degree), person.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H5936>', 'inflected', 'heb', 'לעלוקה', '["la./''a.lu.Kah"]', '["[belong] to/ a leech"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6115}/[H6113]', 'inflected', 'heb', 'עֹצֶר', '["ʻôtser"]', '["and/ barrenness of"]', '["n-m"]', 'closure; also constraint × barren, oppression, × prison.', 'from 6113;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0936}/[H936]', 'inflected', 'heb', 'בּוּז', '["bûwz"]', '["so/ it may despise"]', '["v"]', 'to disrespect contemn, despise, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3349}/[H3348]', 'inflected', 'heb', 'יִקָּהָה', '["yiqqâhâh"]', '["<to>/ obedience of"]', '["n-f"]', 'obedience gathering, to obey.', 'from the same as 3348;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5365}/H9034/[H5365]', 'inflected', 'heb', 'נָקַר', '["nâqar"]', '["they will pluck out/ it"]', '["v"]', 'to bore (penetrate, quarry) dig, pick out, pierce, put (thrust) out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5404>\', 'opaque', 'heb', 'נֶשֶׁר', '["nesher"]', '["an eagle"]', '["n-m"]', 'the eagle (or other large bird of prey) eagle.', 'from an unused root meaning to lacerate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5959}/[H5958]', 'inflected', 'heb', 'עַלְמָה', '["ʻalmâh"]', '["with/ a young woman"]', '["n-f"]', 'a lass (as veiled or private) damsel, maid, virgin.', 'feminine of 5958;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0205G>\', 'opaque', 'heb', 'אָוֶן', '["ʼâven"]', '["wickedness"]', '["n-m"]', 'strictly nothingness; also trouble, vanity, wickedness; specifically an idol affliction, evil, false, idol, iniquity, mischief, mourners(-ing), naught, sorrow, unjust, unrighteous, vain, vanity, wicked(-ness). Compare 369.', 'from an unused root perhaps meaning properly, to pant (hence, to exert oneself, usually in vain; to come to naught);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5036}/[H5034]', 'inflected', 'heb', 'נָבָל', '["nâbâl"]', '["and/ a fool"]', '["a"]', 'stupid; wicked (especially impious) fool(-ish, -ish man, -ish woman), vile person.', 'from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1404}/H9024\/[H1376]', 'inflected', 'heb', 'גְּבֶרֶת', '["gᵉbereth"]', '["mistress/ her"]', '["n-f"]', 'mistress lady, mistress.', 'feminine of 1376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5244}/[H5243]', 'inflected', 'heb', 'נְמָלָה', '["nᵉmâlâh"]', '["the/ ants"]', '["n-f"]', 'an ant (probably from its almost bisected form) ant.', 'feminine from 5243;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8227A}/[H8226]', 'lemma', 'heb', 'שָׁפָן', '["shâphân"]', '["rock badgers"]', '["n-m n-pr-m"]', 'a species of rock-rabbit (from its hiding), i.e. probably the hyrax coney.', 'from 8226;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8079}/[H8074]', 'lemma', 'heb', 'שְׂמָמִית', '["sᵉmâmîyth"]', '["a lizard"]', '["n-f"]', 'a lizard (from the superstition of its noxiousness) spider.', 'probably from 8074 (in the sense of poisoning);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2223}/[H2115]', 'lemma', 'heb', 'זַרְזִיר', '["zarzîyr"]', '["a rooster of"]', '["n-m"]', 'properly, tightly girt, i.e. probably a racer, or some fleet animal (as being slender in the waist) greyhound.', 'by reduplication from 2115;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8495>', 'opaque', 'heb', 'תַּיִשׁ', '["tayish"]', '["a male goat"]', '["n-m"]', 'a buck or he-goat (as given to butting) he goat.', 'from an unused root meaning to butt;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0510}/[H408]', 'lemma', 'heb', 'אַלְקוּם', '["ʼalqûwm"]', '["a band of soldiers"]', '["n-m"]', 'a non-rising (i.e. resistlessness) no rising up.', 'probably from 408 and 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5034A}/[H5034]', 'lemma', 'heb', 'נָבֵל', '["nâbêl"]', '["[is] treating with contempt","you have been foolish","you treat with contempt"]', '["v"]', 'to wilt; generally, to fall away, fail, faint; figuratively, to be foolish or (morally) wicked; causatively, to despise, disgrace disgrace, dishounour, lightly esteem, fade (away, -ing), fall (down, -ling, off), do foolishly, come to nought, × surely, make vile, wither.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5375L}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["by/ exalting yourself"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4330}/[H4160]', 'lemma', 'heb', 'מִיץ', '["mîyts"]', '["squeezing of"]', '["n-m"]', 'pressure churning, forcing, wringing.', 'from 4160;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4330}/[H4160]', 'inflected', 'heb', 'מִיץ', '["mîyts"]', '["and/ squeezing of"]', '["n-m"]', 'pressure churning, forcing, wringing.', 'from 4160;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3927}/[H3926]', 'lemma', 'heb', 'לְמוּאֵל', '["Lᵉmûwʼêl"]', '["Lemuel","O Lemuel"]', '["n-pr-m"]', 'Lemuel or Lemoel, a symbolic name of Solomon Lemuel.', 'or לְמוֹאֵל; from 3926 and 410; (belonging) to God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1870G}/H9021/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["and/ ways/ your"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7336}/[H7336]', 'inflected', 'heb', 'רָזַן', '["râzan"]', '["and/ for/ rulers"]', '["v"]', 'probably to be heavy, i.e. (figuratively) honorable prince, ruler.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8138A}/[H8138]', 'inflected', 'heb', 'שָׁנָה', '["shânâh"]', '["and/ he may change"]', '["v"]', 'to fold, i.e. duplicate (literally or figuratively); by implication, to transmute (transitive or intransitive) do (speak, strike) again, alter, double, (be given to) change, disguise, (be) diverse, pervert, prefer, repeat, return, do the second time.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7389B}/H9023/[H7326]', 'inflected', 'heb', 'רֵישׁ', '["rêysh"]', '["poverty/ his"]', '["n-m"]', 'poverty poverty.', 'or רֵאשׁ; or רִישׁ; from 7326;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5999}/H9023/[H5998]', 'inflected', 'heb', 'עָמָל', '["ʻâmâl"]', '["and/ trouble/ his"]', '["n"]', 'toil, i.e. wearing effort; hence, worry, whether of body or mind grievance(-vousness), iniquity, labour, mischief, miserable(-sery), pain(-ful), perverseness, sorrow, toil, travail, trouble, wearisome, wickedness.', 'from 5998;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0483}/[H481]', 'inflected', 'heb', 'אִלֵּם', '["ʼillêm"]', '["for/ [the] dumb"]', '["a"]', 'speechless dumb (man).', 'from 481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2475}/[H2498]', 'lemma', 'heb', 'חֲלוֹף', '["chălôwph"]', '["passing away"]', '["n-m"]', 'properly, surviving; by implication (collectively) orphans × destruction.', 'from 2498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1777}/[H1777]', 'inflected', 'heb', 'דִּין', '["dîyn"]', '["and/ plead [the] cause of"]', '["v"]', 'to rule; by implication to judge (as umpire); also to strive (as at law) contend contend execute (judgment) judge minister judgment plead (the cause) at strife strive.', 'or (Genesis 6:3) דּוּן; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0034}\/[H14]', 'inflected', 'heb', 'אֶבְיוֹן', '["ʼebyôwn"]', '["and/ [the] needy"]', '["a-m"]', 'destitute beggar, needy, poor (man).', 'from 14, in the sense of want (especially in feeling);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4377}/H9024/[H4376]', 'inflected', 'heb', 'מֶכֶר', '["meker"]', '["price/ her"]', '["n-m"]', 'merchandise; also value pay, price, ware.', 'from 4376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2416E}/H9024/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["life/ her"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2656}/[H2654]', 'inflected', 'heb', 'חֵפֶץ', '["chêphets"]', '["in/ [the] delight of"]', '["n-m"]', 'pleasure; hence (abstractly) desire; concretely, a valuable thing; hence (by extension) a matter (as something in mind) acceptable, delight(-some), desire, things desired, matter, pleasant(-ure), purpose, willingly.', 'from 2654;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0591}/[H590]', 'inflected', 'heb', 'אֳנִיָּה', '["ʼŏnîyâh"]', '["like/ [the] ships of"]', '["n-f"]', 'a ship ship(-men).', 'feminine of 590;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1004M}/H9024/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["for/ household/ her","to/ household/ her"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5291}/H9024/[H5288]', 'inflected', 'heb', 'נַעֲרָה', '["naʻărâh"]', '["to/ female servants/ her"]', '["n-f"]', 'a girl (from infancy to adolescence) damsel, maid(-en), young (woman).', 'feminine of 5288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3947K}/H9033/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["and/ she took/ it"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4975>/H9024', 'opaque', 'heb', 'מֹתֶן', '["môthen"]', '["loins/ her"]', '["n-m"]', 'properly, the waist or small of the back; only in plural the loins greyhound, loins, side.', 'from an unused root meaning to be slender;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2220}/H9024/[H2232]', 'inflected', 'heb', 'זְרוֹעַ', '["zᵉrôwaʻ"]', '["arms/ her"]', '["n-f"]', 'the arm (as stretched out), or (of animals) the foreleg; figuratively, force arm, help, mighty, power, shoulder, strength.', 'or (shortened) זְרֹעַ; and (feminine) זְרוֹעָה; or זְרֹעָה; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3601}/[H3787]', 'inflected', 'heb', 'כִּישׁוֹר', '["kîyshôwr"]', '["on the/ distaff"]', '["n-m"]', 'literally a director, i.e. the spindle or shank of a distaff, by which it is twirled spindle.', 'from 3787; compare 6418');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3709G}/H9024/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["and/ palms/ her"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7950}/[H7949]', 'inflected', 'heb', 'שֶׁלֶג', '["sheleg"]', '["from/ snow","more than/ snow"]', '["n-m"]', 'snow (probably from its whiteness) snow(-y).', 'from 7949;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3427}/H9043/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["when/ sits/ he"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3669B}/[H3667]', 'inflected', 'heb', 'כְּנַעַנִי', '["Kᵉnaʻanîy"]', '["to the/ merchants"]', '["n-m"]', 'a Kenaanite or inhabitant of Kenaan; by implication, a pedlar (the Canaanites standing for their neighbors the Ishmaelites, who conducted mercantile caravans) Canaanite, merchant, trafficker.', 'patrial from 3667;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3956G}/H9024/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["tongue/ her"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6104}/[H6101]', 'lemma', 'heb', 'עַצְלוּת', '["ʻatslûwth"]', '["laziness"]', '["n-f"]', 'indolence idleness.', 'from 6101;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0833}/H9034/[H833]', 'inflected', 'heb', 'אָשַׁר', '["ʼâshar"]', '["and/ they called blessed/ her"]', '["v"]', 'to be straight (used in the widest sense, especially to be level, right, happy); figuratively, to go forward, be honest, prosper (call, be) bless(-ed, happy), go, guide, lead, relieve.', 'or אָשֵׁר; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1984B}/H9034/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["and/ he praised/ her"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2580}/[H2603]', 'inflected', 'heb', 'חֵן', '["chên"]', '["<the>/ grace"]', '["n-m"]', 'graciousness, i.e. subjective (kindness, favor) or objective (beauty) favour, grace(-ious), pleasant, precious, (well-) favoured.', 'from 2603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1892}/[H1891]', 'inflected', 'heb', 'הֶבֶל', '["hebel"]', '["and/ [is] vanity","and/ futilities","and/ futility"]', '["n-m"]', 'emptiness or vanity; figuratively, something transitory and unsatisfactory; often used as an adverb × altogether, vain, vanity.', 'or (rarely in the abs.) הֲבֵל; from 1891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3308}/[H3302]', 'inflected', 'heb', 'יֳפִי', '["yŏphîy"]', '["<the>/ beauty"]', '["n-m"]', 'beauty beauty.', 'from 3302;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1984B}/H9034/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["and/ let them praise/ her"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4639G}/H9024/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["work/ her"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6953}/[H6950]', 'lemma', 'heb', 'קֹהֶלֶת', '["qôheleth"]', '["Teacher"]', '["n-m"]', 'a (female) assembler (i.e. lecturer); abstractly, preaching (used as a ''nom de plume'', Koheleth) preacher.', 'feminine of active participle from 6950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3504}/[H3498]', 'lemma', 'heb', 'יִתְרוֹן', '["yithrôwn"]', '["[is the] profit","[is] [the] profit of","[is] advantage","[is] profit","[was] profit","profit"]', '["n-m"]', 'preeminence, gain better, excellency(-leth), profit(-able).', 'from 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H5998}/[H5998]', 'inflected', 'heb', 'עָמַל', '["ʻâmal"]', '["that/ I had toiled","that/ I have toiled","that/ he toils","that/ he will toil","that/ someone will toil"]', '["v"]', 'to toil, i.e. work severely and with irksomeness (take) labour (in).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1864>', 'opaque', 'heb', 'דָּרוֹם', '["dârôwm"]', '["[the] south"]', '["n-m"]', 'the south; poet. the south wind south.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5437G}/[H5437]', 'inflected', 'heb', 'סָבַב', '["çâbab"]', '["and/ [it is] circling"]', '["v"]', 'to revolve, surround, or border; used in various applications, literally and figuratively bring, cast, fetch, lead, make, walk, × whirl, × round about, be about on every side, apply, avoid, beset (about), besiege, bring again, carry (about), change, cause to come about, × circuit, (fetch a) compass (about, round), drive, environ, × on every side, beset (close, come, compass, go, stand) round about, inclose, remove, return, set, sit down, turn (self) (about, aside, away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/H9009/{H5158A}/[H5157]', 'inflected', 'heb', 'נַחַל', '["nachal"]', '["<of> where/ the/ rivers"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H6213A}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["[is] which/ <it> will be done","that/ <it> was done","that/ <they> had done","that/ <they> have been done","which/ <it> has been done"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H0559}/[H559]', 'inflected', 'heb', 'אָמַר', '["ʼâmar"]', '["that/ anyone will say","that/ people said"]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3528}/[H3527]', 'lemma', 'heb', 'כְּבָר', '["kᵉbâr"]', '["[has been] already","already"]', '["adv"]', 'properly, extent of time, i.e. a great while; hence, long ago, formerly, hitherto already, (seeing that which), now.', 'from 3527;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5769J}/[H5956]', 'inflected', 'heb', 'עוֹלָם', '["ʻôwlâm"]', '["to/ ancient times"]', '["n-m"]', 'properly, concealed, i.e. the vanishing point; generally, time out of mind (past or future), i.e. (practically) eternity; frequentatively, adverbial (especially with prepositional prefix) always alway(-s), ancient (time), any more, continuance, eternal, (for, (n-)) ever(-lasting, -more, of old), lasting, long (time), (of) old (time), perpetual, at any time, (beginning of the) world ( without end). Compare 5331, 5703.', 'or עֹלָם; from 5956;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9005/{H6440G}/H9025/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["from/ to/ before/ us"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7223H}/[H7221]', 'inflected', 'heb', 'רִאשׁוֹן', '["riʼshôwn"]', '["of the/ former [things]"]', '["a"]', 'first, in place, time or rank (as adjective or noun) ancestor, (that were) before(-time), beginning, eldest, first, fore(-father) (-most), former (thing), of old time, past.', 'or רִאשֹׁן; from 7221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0314}\/[H309]', 'inflected', 'heb', 'אַחֲרוֹן', '["ʼachărôwn"]', '["to the/ later [time]"]', '["a"]', 'hinder; generally, late or last; specifically (as facing the east) western after (-ward), to come, following, hind(-er, -ermost, -most), last, latter, rereward, ut(ter) most.', 'or (shortened) אַחֲרֹן; from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8446}/[H8446]', 'inflected', 'heb', 'תּוּר', '["tûwr"]', '["and/ to/ discover","and/ to/ examine"]', '["v"]', 'to meander (causatively, guide) about, especially for trade or reconnoitring chap(-man), sent to descry, be excellent, merchant(-man), search (out), seek, (e-) spy (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6045}/[H6031]', 'lemma', 'heb', 'עִנְיָן', '["ʻinyân"]', '["[is] a task of","a task","business"]', '["n-m"]', 'ado, i.e. (generally) employment or (specifically) an affair business, travail.', 'from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6031A}/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["to/ be busy"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7469}/[H7462]', 'inflected', 'heb', 'רְעוּת', '["rᵉʻûwth"]', '["and/ striving of"]', '["n-m"]', 'a feeding upon, i.e. grasping after vexation.', 'probably from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8626}/[H8626]', 'inflected', 'heb', 'תָּקַן', '["tâqan"]', '["to/ become straight","to/ straighten"]', '["v"]', 'to equalize, i.e. straighten (intransitive or transitive); figuratively, to compose set in order, make straight.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2642}/[H2637]', 'inflected', 'heb', 'חֶסְרוֹן', '["cheçrôwn"]', '["and/ something missing"]', '["n-m"]', 'deficiency wanting.', 'from 2637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414H}/H9012/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I gave/ !","and/ I put/ !","and/ I set/ !"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1947}/[H1984]', 'lemma', 'heb', 'הוֹלֵלָה', '["hôwlêlâh"]', '["madness"]', '["n-f"]', 'folly madness.', 'feminine active participle of 1984;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5531A}/[H5528]', 'inflected', 'heb', 'סִכְלוּת', '["çiklûwth"]', '["and/ folly"]', '["n-f"]', 'silliness folly, foolishness.', 'or שִׂכְלוּת; (Ecclesiastes 1:17), from 5528;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/<H1571>', 'inflected', 'heb', 'שגם', '["she./gam"]', '["that/ also"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7475}/[H7462]', 'lemma', 'heb', 'רַעְיוֹן', '["raʻyôwn"]', '["[is] a striving of"]', '["n-m"]', 'desire vexation.', 'from 7462 in the sense of 7469;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7200K}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ look"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7814}/[H7832]', 'inflected', 'heb', 'שְׂחוֹק', '["sᵉchôwq"]', '["<into>/ a laughing stock","for/ laughter","of/ laughter"]', '["n-m"]', 'laughter (in merriment or defiance) derision, laughter(-ed to scorn, -ing), mocked, sport.', 'or שְׂחֹק; from 7832;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1984I}/[H1984]', 'lemma', 'heb', 'הָלַל', '["hâlal"]', '["[it is] folly","it will make look foolish"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4900}/[H4900]', 'inflected', 'heb', 'מָשַׁךְ', '["mâshak"]', '["to/ gratify"]', '["v"]', 'to draw, used in a great variety of applications (including to sow, to sound, to prolong, to develop, to march, to remove, to delay, to be tall, etc.) draw (along, out), continue, defer, extend, forbear, × give, handle, make (pro-, sound) long, × sow, scatter, stretch out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0270}/[H270]', 'inflected', 'heb', 'אָחַז', '["ʼâchaz"]', '["and/ to/ take hold"]', '["v"]', 'to seize (often with the accessory idea of holding in possession) be affrighted, bar, (catch, lay, take) hold (back), come upon, fasten, handle, portion, (get, have or take) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5531B}/[H5528]', 'inflected', 'heb', 'סִכְלוּת', '["çiklûwth"]', '["on/ folly"]', '["n-f"]', 'silliness folly, foolishness.', 'or שִׂכְלוּת; (Ecclesiastes 1:17), from 5528;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4639G}/H9020/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["works/ my"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1593}/[H1588]', 'lemma', 'heb', 'גַּנָּה', '["gannâh"]', '["gardens"]', '["n-f"]', 'a garden garden.', 'feminine of 1588;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6508>', 'inflected', 'heb', 'ופרדסים', '["u./far.de.Sim"]', '["and/ parks"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5459>', 'inflected', 'heb', 'וסגלת', '["u./se.gu.Lat"]', '["and/ treasure of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4082}/[H1777]', 'inflected', 'heb', 'מְדִינָה', '["mᵉdîynâh"]', '["and/ <the>/ provinces"]', '["n-f"]', 'properly, a judgeship, i.e. jurisdiction; by implication, a district (as ruled by a judge); generally, a region (× every) province.', 'from 1777;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8588}/[H6026]', 'inflected', 'heb', 'תַּעֲנוּג', '["taʻănûwg"]', '["and/ [the] delights of"]', '["n-m"]', 'luxury delicate, delight, pleasant.', 'or תַּעֲנֻג; and (feminine) תַּעֲנֻגָה; from 6026;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7705}/[H7703]', 'lemma', 'heb', 'שִׁדָּה', '["shiddâh"]', '["breast"]', '["n-f"]', 'a wife (as mistress of the house) × all sorts, musical instrument.', 'from 7703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7705}/[H7703]', 'inflected', 'heb', 'שִׁדָּה', '["shiddâh"]', '["and/ breasts"]', '["n-f"]', 'a wife (as mistress of the house) × all sorts, musical instrument.', 'from 7703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2451}/H9020/[H2449]', 'inflected', 'heb', 'חׇכְמָה', '["chokmâh"]', '["wisdom/ my"]', '["n-f"]', 'wisdom (in a good sense) skilful, wisdom, wisely, wit.', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5999}/[H5998]', 'inflected', 'heb', 'עָמָל', '["ʻâmâl"]', '["and/ on the/ toil"]', '["n"]', 'toil, i.e. wearing effort; hence, worry, whether of body or mind grievance(-vousness), iniquity, labour, mischief, miserable(-sery), pain(-ful), perverseness, sorrow, toil, travail, trouble, wearisome, wickedness.', 'from 5998;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7200H}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["to/ consider"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1947}/[H1984]', 'inflected', 'heb', 'הוֹלֵלָה', '["hôwlêlâh"]', '["and/ madness"]', '["n-f"]', 'folly madness.', 'feminine active participle of 1984;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5531B}/[H5528]', 'inflected', 'heb', 'סִכְלוּת', '["çiklûwth"]', '["and/ folly"]', '["n-f"]', 'silliness folly, foolishness.', 'or שִׂכְלוּת; (Ecclesiastes 1:17), from 5528;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H0935G}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["[that] which/ <he> came","that/ <it> has come","who/ <he >will come"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/<H3426>', 'inflected', 'heb', 'שיש', '["shei./Yesh"]', '["that/ there"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5531B}/[H5528]', 'inflected', 'heb', 'סִכְלוּת', '["çiklûwth"]', '["<the>/ folly"]', '["n-f"]', 'silliness folly, foolishness.', 'or שִׂכְלוּת; (Ecclesiastes 1:17), from 5528;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3504}/[H3498]', 'inflected', 'heb', 'יִתְרוֹן', '["yithrôwn"]', '["like/ [the] advantage of"]', '["n-m"]', 'preeminence, gain better, excellency(-leth), profit(-able).', 'from 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3684}/[H3688]', 'inflected', 'heb', 'כְּסִיל', '["kᵉçîyl"]', '["and/ the/ fool"]', '["n-m"]', 'properly, fat, i.e. (figuratively) stupid or silly fool(-ish).', 'from 3688;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H4745}/[H7136]', 'inflected', 'heb', 'מִקְרֶה', '["miqreh"]', '["that/ fate"]', '["n-m"]', 'something met with, i.e. an accident or fortune something befallen, befalleth, chance, event, hap(-peneth).', 'from 7136;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4745}/[H7136]', 'inflected', 'heb', 'מִקְרֶה', '["miqreh"]', '["like/ [the] fate of"]', '["n-m"]', 'something met with, i.e. an accident or fortune something befallen, befalleth, chance, event, hap(-peneth).', 'from 7136;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3684}/[H3688]', 'inflected', 'heb', 'כְּסִיל', '["kᵉçîyl"]', '["<the>/ fools","the/ fool","the/ fools"]', '["n-m"]', 'properly, fat, i.e. (figuratively) stupid or silly fool(-ish).', 'from 3688;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7136A}/H9030/[H7136]', 'inflected', 'heb', 'קָרָה', '["qârâh"]', '["it will happen to/ me"]', '["v"]', 'to light upon (chiefly by accident); causatively, to bring about; specifically, to impose timbers (for roof or floor) appoint, lay (make) beams, befall, bring, come (to pass unto), floor, (hap) was, happen (unto), meet, send good speed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/H9007/{H3528}/[H3527]', 'inflected', 'heb', 'כְּבָר', '["kᵉbâr"]', '["in/ that/ already"]', '["adv"]', 'properly, extent of time, i.e. a great while; hence, long ago, formerly, hitherto already, (seeing that which), now.', 'from 3527;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H0589}/[H595]', 'inflected', 'heb', 'אֲנִי', '["ʼănîy"]', '["that/ I","who/ I"]', '["p"]', 'I I, (as for) me, mine, myself, we, × which, × who.', 'contracted from 595;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6001B}/[H5998]', 'lemma', 'heb', 'עָמֵל', '["ʻâmêl"]', '["[are] a laborer","[is] a laborer","[was] a laborer","a laborer"]', '["n-m a"]', 'toiling; concretely, a laborer; figuratively, sorrowful that laboureth, that is a misery, had taken (labour), wicked, workman.', 'from 5998;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H5117}/H9033/[H5117]', 'inflected', 'heb', 'נוּחַ', '["nûwach"]', '["that/ I will leave/ it"]', '["v"]', 'to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5530}/[H5528]', 'lemma', 'heb', 'סָכָל', '["çâkâl"]', '["[is] a fool","a fool","fool","fools"]', '["n-m"]', 'silly fool(-ish), sottish.', 'from 5528;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7980}/[H7980]', 'inflected', 'heb', 'שָׁלַט', '["shâlaṭ"]', '["so/ he may have power"]', '["v"]', 'to dominate, i.e. govern; by implication, to permit (bear, have) rule, have dominion, give (have) power.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9007/{H2449}/[H2449]', 'inflected', 'heb', 'חָכַם', '["châkam"]', '["and/ that/ I worked skillfully"]', '["v"]', 'to be wise (in mind, word or act) × exceeding, teach wisdom, be (make self, shew self) wise, deal (never so) wisely, make wiser.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2976}/[H2976]', 'inflected', 'heb', 'יָאַשׁ', '["yâʼash"]', '["to/ make despair"]', '["v"]', 'to desist, i.e. (figuratively) to despond (cause to) despair, one that is desperate, be no hope.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5999}/[H5998]', 'inflected', 'heb', 'עָמָל', '["ʻâmâl"]', '["the/ toil"]', '["n"]', 'toil, i.e. wearing effort; hence, worry, whether of body or mind grievance(-vousness), iniquity, labour, mischief, miserable(-sery), pain(-ful), perverseness, sorrow, toil, travail, trouble, wearisome, wickedness.', 'from 5998;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H5999}/H9023/[H5998]', 'inflected', 'heb', 'עָמָל', '["ʻâmâl"]', '["who/ toil/ his"]', '["n"]', 'toil, i.e. wearing effort; hence, worry, whether of body or mind grievance(-vousness), iniquity, labour, mischief, miserable(-sery), pain(-ful), perverseness, sorrow, toil, travail, trouble, wearisome, wickedness.', 'from 5998;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3788}/[H3787]', 'inflected', 'heb', 'כִּשְׁרוֹן', '["kishrôwn"]', '["and/ with/ skill"]', '["n-m"]', 'success, advantage equity, good, right.', 'from 3787;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0120G}/[H119]', 'inflected', 'heb', 'אָדָם', '["ʼâdâm"]', '["and/ to/ a person"]', '["n-m"]', 'ruddy i.e. a human being (an individual or the species, mankind, etc.) × another, hypocrite, common sort, × low, man (mean, of low degree), person.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414H}/H9033/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["he will give/ it"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2506A}/H9023/[H2505]', 'inflected', 'heb', 'חֵלֶק', '["chêleq"]', '["[is] portion/ his","portion/ his"]', '["n-m"]', 'properly, smoothness (of the tongue); also an allotment flattery, inheritance, part, × partake, portion.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7475}/[H7462]', 'inflected', 'heb', 'רַעְיוֹן', '["raʻyôwn"]', '["and/ in/ [the] striving of"]', '["n-m"]', 'desire vexation.', 'from 7462 in the sense of 7469;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H1931}/[H1931]', 'inflected', 'heb', 'הוּא', '["hûwʼ"]', '["that/ he"]', '["p"]', 'he (she or it); only expressed when emphatic or without a verb; also (intensively) self, or (especially with the article) the same; sometimes (as demonstrative) this or that; occasionally (instead of copula) as or are he, as for her, him(-self), it, the same, she (herself), such, that (...it), these, they, this, those, which (is), who.', 'of which the feminine (beyond the Pentateuch) is הִיא; he a primitive word, the third person pronoun singular;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6045}/H9023/[H6031]', 'inflected', 'heb', 'עִנְיָן', '["ʻinyân"]', '["task/ his"]', '["n-m"]', 'ado, i.e. (generally) employment or (specifically) an affair business, travail.', 'from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H0398}/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["that/ he will eat"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7200K}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ he will see","and/ he will show"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5999}/H9023/[H5998]', 'inflected', 'heb', 'עָמָל', '["ʻâmâl"]', '["in/ toil/ his"]', '["n"]', 'toil, i.e. wearing effort; hence, worry, whether of body or mind grievance(-vousness), iniquity, labour, mischief, miserable(-sery), pain(-ful), perverseness, sorrow, toil, travail, trouble, wearisome, wickedness.', 'from 5998;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2363B}/[H2363]', 'lemma', 'heb', 'חוּשׁ', '["chûwsh"]', '["will he enjoy"]', '["v"]', 'to hurry; figuratively, to be eager with excitement or enjoyment (make) haste(-n), ready.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H2896A}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["who/ [is] good"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2398}/[H2398]', 'inflected', 'heb', 'חָטָא', '["châṭâʼ"]', '["and/ to the/ sinner"]', '["v"]', 'properly, to miss; hence (figuratively and generally) to sin; by inference, to forfeit, lack, expiate, repent, (causatively) lead astray, condemn bear the blame, cleanse, commit (sin), by fault, harm he hath done, loss, miss, (make) offend(-er), offer for sin, purge, purify (self), make reconciliation, (cause, make) sin(-ful, -ness), trespass.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3664}/[H3664]', 'inflected', 'heb', 'כָּנַס', '["kânaç"]', '["and/ to/ collect"]', '["v"]', 'to collect; hence, to enfold gather (together), heap up, wrap self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6256}/[H5703]', 'inflected', 'heb', 'עֵת', '["ʻêth"]', '["and/ [it is] time","and/ [will be] a time of","and/ a time","and/ a time of","and/ an appropriate time","and/ an time"]', '["n-f"]', 'time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when.', 'from 5703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5193}/[H5193]', 'inflected', 'heb', 'נָטַע', '["nâṭaʻ"]', '["to/ plant"]', '["v"]', 'properly, to strike in, i.e. fix; specifically, to plant (literally or figuratively) fastened, plant(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6131A}/[H6131]', 'inflected', 'heb', 'עָקַר', '["ʻâqar"]', '["to/ pluck up"]', '["v"]', 'to pluck up (especially by the roots); specifically, to hamstring; figuratively, to exterminate dig down, hough, pluck up, root up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6555}/[H6555]', 'inflected', 'heb', 'פָּרַץ', '["pârats"]', '["to/ break down"]', '["v"]', 'to break out (in many applications, direct and indirect, literal and figurative) × abroad, (make a) breach, break (away, down, -er, forth, in, up), burst out, come (spread) abroad, compel, disperse, grow, increase, open, press, scatter, urge.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5594}/[H5594]', 'lemma', 'heb', 'סָפַד', '["çâphad"]', '["I will lament","mourn","mourning","people will mourn","they will be mourned","they will mourn","to mourn","you must lament"]', '["v"]', 'properly, to tear the hair and beat the breasts (as Orientals do in grief); generally to lament; by implication, to wail lament, mourn(-er), wail.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7993}/[H7993]', 'inflected', 'heb', 'שָׁלַךְ', '["shâlak"]', '["to/ throw away"]', '["v"]', 'to throw out, down or away (literally or figuratively) adventure, cast (away, down, forth, off, out), hurl, pluck, throw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2263}/[H2263]', 'inflected', 'heb', 'חָבַק', '["châbaq"]', '["to/ embrace"]', '["v"]', 'to clasp (the hands or in embrace) embrace, fold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7368}/[H7368]', 'inflected', 'heb', 'רָחַק', '["râchaq"]', '["to/ be far"]', '["v"]', 'to widen (in any direction), i.e. (intransitively) recede or (transitively) remove (literally or figuratively, of place or relation) (a-, be, cast, drive, get, go, keep (self), put, remove, be too, (wander), withdraw) far (away, off), loose, × refrain, very, (be) a good way (off).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2263}/[H2263]', 'inflected', 'heb', 'חָבַק', '["châbaq"]', '["from/ embracing"]', '["v"]', 'to clasp (the hands or in embrace) embrace, fold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7167}/[H7167]', 'inflected', 'heb', 'קָרַע', '["qâraʻ"]', '["to/ tear"]', '["v"]', 'to rend, literally or figuratively (revile, paint the eyes, as if enlarging them) cut out, rend, × surely, tear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8609}/[H8609]', 'inflected', 'heb', 'תָּפַר', '["tâphar"]', '["to/ [women who] sew","to/ sew"]', '["v"]', 'to sew (women that) sew (together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2814}/[H2814]', 'inflected', 'heb', 'חָשָׁה', '["châshâh"]', '["to/ be silent"]', '["v"]', 'to hush or keep quiet hold peace, keep silence, be silent, (be) still.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6045}/[H6031]', 'inflected', 'heb', 'עִנְיָן', '["ʻinyân"]', '["the/ task"]', '["n-m"]', 'ado, i.e. (generally) employment or (specifically) an affair business, travail.', 'from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5490}/[H5486]', 'lemma', 'heb', 'סוֹף', '["çôwph"]', '["[is] [the] end of","[the] end of","end"]', '["n-m"]', 'a termination conclusion, end, hinder participle', 'from 5486;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4480A}/H9033/[H4482]', 'inflected', 'heb', 'מִן', '["min"]', '["and/ from/ him","and/ from/ it"]', '["prep"]', 'properly, a part of; hence (prepositionally), from or out of in many senses above, after, among, at, because of, by (reason of), from (among), in, × neither, × nor, (out) of, over, since, × then, through, × whether, with.', 'or מִנִּי; or מִנֵּי; (constructive plural) (Isaiah 30:11); for 4482;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1639}/[H1639]', 'inflected', 'heb', 'גָּרַע', '["gâraʻ"]', '["to/ take away"]', '["v"]', 'to scrape off; by implication, to shave, remove, lessen, withhold abate, clip, (di-) minish, do (take) away, keep back, restrain, make small, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H3372H}/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["that/ people will fear"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4941H}/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["<the>/ justice"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6664G}/[H6663]', 'inflected', 'heb', 'צֶדֶק', '["tsedeq"]', '["<the>/ righteousness"]', '["n-m"]', 'the right (natural, moral or legal); also (abstractly) equity or (figuratively) prosperity × even, (× that which is altogether) just(-ice), (un-)right(-eous) (cause, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1305}/H9038/[H1305]', 'inflected', 'heb', 'בָּרַר', '["bârar"]', '["to/ test/ them"]', '["v"]', 'to clarify (i.e. brighten), examine, select make bright, choice, chosen, cleanse (be clean), clearly, polished, (shew self) pure(-ify), purge (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7200G}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ to/ see"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H1992}/[H1931]', 'inflected', 'heb', 'הֵם', '["hêm"]', '["that/ they","who/ they"]', '["p"]', 'they (only used when emphatic) it, like, × (how, so) many (soever, more as) they (be), (the) same, × so, × such, their, them, these, they, those, which, who, whom, withal, ye.', 'or (prolonged) הֵמָּה; masculine plural from 1931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4745}/[H7136]', 'inflected', 'heb', 'מִקְרֶה', '["miqreh"]', '["and/ [the] fate of","and/ fate"]', '["n-m"]', 'something met with, i.e. an accident or fortune something befallen, befalleth, chance, event, hap(-peneth).', 'from 7136;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4195}/[H3498]', 'inflected', 'heb', 'מוֹתָר', '["môwthâr"]', '["and/ [the] advantage of"]', '["n-m"]', 'literally gain; figuratively, superiority plenteousness, preeminence, profit.', 'from 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3605}/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["and/ <the>/ everything"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6217}/[H6231]', 'inflected', 'heb', 'עָשׁוּק', '["ʻâshûwq"]', '["the/ oppressed","the/ oppression<s>"]', '["n-m"]', 'used in plural masculine as abstractly, tyranny oppressed(-ion). [Doubtful.]', 'or עָשֻׁק; passive participle of 6231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H3027I}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ [was] from/ [the] hand of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6231}/H9038/[H6229]', 'inflected', 'heb', 'עָשַׁק', '["ʻâshaq"]', '["oppressors/ their"]', '["v"]', 'to press upon, i.e. oppress, defraud, violate, overflow get deceitfully, deceive, defraud, drink up, (use) oppress(-ion), -or), do violence (wrong).', 'a primitive root (compare 6229);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7623B}/[H7623]', 'inflected', 'heb', 'שָׁבַח', '["shâbach"]', '["and/ I congratulated"]', '["v"]', 'properly, to address in a loud tone, i.e. (specifically) loud; figuratively, to pacify (as if by words) commend, glory, keep in, praise, still, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H3528}/[H3527]', 'inflected', 'heb', 'כְּבָר', '["kᵉbâr"]', '["who/ already"]', '["adv"]', 'properly, extent of time, i.e. a great while; hence, long ago, formerly, hitherto already, (seeing that which), now.', 'from 3527;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5728}/H9011/[H5704]', 'inflected', 'heb', 'עֲדֶן', '["ʻăden"]', '["still/ <towards>"]', '["adv"]', 'till now yet.', 'or עֲדֶנָּה; from 5704 and 2004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5728}/[H5704]', 'lemma', 'heb', 'עֲדֶן', '["ʻăden"]', '["still"]', '["adv"]', 'till now yet.', 'or עֲדֶנָּה; from 5704 and 2004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3788}/[H3787]', 'lemma', 'heb', 'כִּשְׁרוֹן', '["kishrôwn"]', '["[the] skill of","profit"]', '["n-m"]', 'success, advantage equity, good, right.', 'from 3787;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4393}/[H4390]', 'inflected', 'heb', 'מְלֹא', '["mᵉlôʼ"]', '["more than/ [the] fullness of"]', '["n-m"]', 'fulness (literally or figuratively) × all along, × all that is (there-) in, fill, (× that whereof...was) full, fulness, (hand-) full, multitude.', 'rarely מְלוֹא; or מְלוֹ; (Ezekiel 41:8), from 4390;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2651>', 'opaque', 'heb', 'חֹפֶן', '["chôphen"]', '["[the] cupped hands of","two hands"]', '["n-m"]', 'a fist (only in the dual) fists, (both) hands, hand(-ful).', 'from an unused root of uncertain signification;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2896C}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["from/ good"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6045}/[H6031]', 'inflected', 'heb', 'עִנְיָן', '["ʻinyân"]', '["and/ [is] a task of"]', '["n-m"]', 'ado, i.e. (generally) employment or (specifically) an affair business, travail.', 'from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5999}/H9028/[H5998]', 'inflected', 'heb', 'עָמָל', '["ʻâmâl"]', '["for/ toil/ their"]', '["n"]', 'toil, i.e. wearing effort; hence, worry, whether of body or mind grievance(-vousness), iniquity, labour, mischief, miserable(-sery), pain(-ful), perverseness, sorrow, toil, travail, trouble, wearisome, wickedness.', 'from 5998;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2270}/H9023/[H2266]', 'inflected', 'heb', 'חָבֵר', '["châbêr"]', '["associates/ its","companion/ his","companions/ his"]', '["n-m"]', 'an associate companion, fellow, knit together.', 'from 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0337}/H9033/[H188]', 'inflected', 'heb', 'אִי', '["ʼîy"]', '["and/ woe! to/ <the>/ him"]', '["inj"]', 'alas! woe.', 'short from 188;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H5307G}/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["where/ it falls","who/ <he> will fall down"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6965H}/H9033/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["to/ raise/ him"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0259}/[H258]', 'inflected', 'heb', 'אֶחָד', '["ʼechâd"]', '["and/ <to>/ one","and/ to/ one [person]"]', '["a"]', 'properly, united, i.e. one; or (as an ordinal) first a, alike, alone, altogether, and, any(-thing), apiece, a certain, (dai-) ly, each (one), eleven, every, few, first, highway, a man, once, one, only, other, some, together,', 'a numeral from 258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H2339>', 'inflected', 'heb', 'והחוט', '["ve./ha./Chut"]', '["and/ the/ thread"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8027}/[H7969]', 'inflected', 'heb', 'שָׁלַשׁ', '["shâlash"]', '["<the>/ threefold"]', '["v"]', 'to be (causatively, make) triplicate (by restoration, in portions, strands, days or years) do the third time, (divide into, stay) three (days, -fold, parts, years old).', 'a primitive root perhaps originally to intensify, i.e. treble; but apparently used only as denominative from 7969,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4120}/[H4118]', 'inflected', 'heb', 'מְהֵרָה', '["mᵉhêrâh"]', '["<in>/ quickly"]', '["n-f"]', 'properly, a hurry; hence (adverbially) promptly hastily, quickly, shortly, soon, make (with) speed(-ily), swiftly.', 'feminine of 4118;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4542}/[H5531]', 'lemma', 'heb', 'מִסְכֵּן', '["miçkên"]', '["poor"]', '["a"]', 'indigent poor (man).', 'from 5531;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4428G}/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["away from/ [the] king of","more than/ a king"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2094B}/[H2094]', 'inflected', 'heb', 'זָהַר', '["zâhar"]', '["to/ be warned","to/ warn"]', '["v"]', 'to gleam; figuratively, to enlighten (by caution) admonish, shine, teach, (give) warn(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7475}/[H7462]', 'inflected', 'heb', 'רַעְיוֹן', '["raʻyôwn"]', '["and/ a striving of"]', '["n-m"]', 'desire vexation.', 'from 7462 in the sense of 7469;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3684}/[H3688]', 'inflected', 'heb', 'כְּסִיל', '["kᵉçîyl"]', '["among <the>/ fools","in <the>/ fools"]', '["n-m"]', 'properly, fat, i.e. (figuratively) stupid or silly fool(-ish).', 'from 3688;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9007/{H5087}/[H5087]', 'inflected', 'heb', 'נָדַר', '["nâdar"]', '["more than/ what/ you will vow"]', '["v"]', 'to promise (pos., to do or give something to God) (make a) vow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2254B}/[H2254]', 'inflected', 'heb', 'חָבַל', '["châbal"]', '["and/ he will destroy","and/ it will be broken"]', '["v"]', 'to wind tightly (as a rope), i.e. to bind; specifically, by a pledge; figuratively, to pervert, destroy; also to writhe in pain (especially of parturition) × at all, band, bring forth, (deal) corrupt(-ly), destroy, offend, lay to (take a) pledge, spoil, travail, × very, withhold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1498}/[H1497]', 'inflected', 'heb', 'גָּזֵל', '["gâzêl"]', '["and/ robbery of"]', '["n-m"]', 'robbery, or (concretely) plunder robbery, thing taken away by violence.', 'from 1497;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2656}/[H2654]', 'inflected', 'heb', 'חֵפֶץ', '["chêphets"]', '["the/ matter"]', '["n-m"]', 'pleasure; hence (abstractly) desire; concretely, a valuable thing; hence (by extension) a matter (as something in mind) acceptable, delight(-some), desire, things desired, matter, pleasant(-ure), purpose, willingly.', 'from 2654;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3504}/[H3498]', 'inflected', 'heb', 'יִתְרוֹן', '["yithrôwn"]', '["and/ [is] advantage","and/ [the] advantage of","and/ [the] profit of"]', '["n-m"]', 'preeminence, gain better, excellency(-leth), profit(-able).', 'from 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1995A}/[H1993]', 'inflected', 'heb', 'הָמוֹן', '["hâmôwn"]', '["<in> <the>/ wealth","with/ [the] tumult of"]', '["n-m"]', 'a noise, tumult, crowd; also disquietude, wealth abundance, company, many, multitude, multiply, noise, riches, rumbling, sounding, store, tumult.', 'or הָמֹן; (Ezekiel 5:7), from 1993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1167G}/H9024/[H1166]', 'inflected', 'heb', 'בַּעַל', '["baʻal"]', '["[belongs] to/ owner<s>/ its"]', '["n-m"]', 'a master; hence, a husband, or (figuratively) owner (often used with another noun in modifications of this latter sense) archer, babbler, bird, captain, chief man, confederate, have to do, dreamer, those to whom it is due, furious, those that are given to it, great, hairy, he that hath it, have, horseman, husband, lord, man, married, master, person, sworn, they of.', 'from 1166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7212}/[H7200]', 'lemma', 'heb', 'רְאִית', '["rᵉʼîyth"]', '["[the] sight of"]', '["n-f"]', 'sight beholding.', 'from 7200a;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5647I}/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["the/ laborer"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7647}/[H7646]', 'inflected', 'heb', 'שָׂבָע', '["sâbâʻ"]', '["and/ the/ plenty"]', '["n-m"]', 'copiousness abundance, plenteous(-ness, -ly).', 'from 7646;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3462}/[H3462]', 'inflected', 'heb', 'יָשֵׁן', '["yâshên"]', '["to/ sleep"]', '["v"]', 'properly, to be slack or languid, i.e. (by implication) sleep (figuratively, to die); also to grow old, stale or inveterate old (store), remain long, (make to) sleep.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7451C}/H9023/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["to/ harm/ his"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6045}/[H6031]', 'inflected', 'heb', 'עִנְיָן', '["ʻinyân"]', '["in/ a business of"]', '["n-m"]', 'ado, i.e. (generally) employment or (specifically) an affair business, travail.', 'from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/H9007/{H0935G}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["when/ he/ came"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H1980J}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["that/ he may take"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5980}/[H6004]', 'lemma', 'heb', 'עֻמָּה', '["ʻummâh"]', '["exactly as"]', '["n-f"]', 'conjunction, i.e. society; mostly adverb or preposition (with prepositional prefix), near, beside, along with (over) against, at, beside, hard by, in points.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2483}/H9023/[H2470]', 'inflected', 'heb', 'חֳלִי', '["chŏlîy"]', '["and/ sickness/ his"]', '["n-m"]', 'malady, anxiety, calamity disease, grief, (is) sick(-ness).', 'from 2470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7200K}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ to/ see"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7980}/H9033/[H7980]', 'inflected', 'heb', 'שָׁלַט', '["shâlaṭ"]', '["and/ he has given power/ him"]', '["v"]', 'to dominate, i.e. govern; by implication, to permit (bear, have) rule, have dominion, give (have) power.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5375H}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ to/ bear","and/ to/ receive"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8055}/[H8055]', 'inflected', 'heb', 'שָׂמַח', '["sâmach"]', '["and/ to/ be happy","and/ to/ rejoice"]', '["v"]', 'probably to brighten up, i.e. (figuratively) be (causatively, make) blithe or gleesome cheer up, be (make) glad, (have, make) joy(-ful), be (make) merry, (cause to, make to) rejoice, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5315I}/H9023/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["to/ appetite/ his"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7980}/H9033/[H7980]', 'inflected', 'heb', 'שָׁלַט', '["shâlaṭ"]', '["he gives power/ him"]', '["v"]', 'to dominate, i.e. govern; by implication, to permit (bear, have) rule, have dominion, give (have) power.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5309}/[H5307]', 'inflected', 'heb', 'נֶפֶל', '["nephel"]', '["the/ miscarriage"]', '["n-m"]', 'something fallen, i.e. an abortion untimely birth.', 'or נֵפֶל; from 5307;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2822}/[H2821]', 'inflected', 'heb', 'חֹשֶׁךְ', '["chôshek"]', '["and/ in <the>/ darkness"]', '["n-m"]', 'the dark; hence (literally) darkness; figuratively, misery, destruction, death, ignorance, sorrow, wickedness dark(-ness), night, obscurity.', 'from 2821;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2896C}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["and/ good"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6310G}/H9023/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["[is] for/ mouth/ his"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5315L}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["the/ appetite"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1980I}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["from/ walking","more than/ going"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H8623}/[H8630]', 'inflected', 'heb', 'תַּקִּיף', '["taqqîyph"]', '["[one] who/ [is] mighty"]', '["a"]', 'powerful mightier.', 'from 8630;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1892}/H9023/[H1891]', 'inflected', 'heb', 'הֶבֶל', '["hebel"]', '["futility/ his"]', '["n-m"]', 'emptiness or vanity; figuratively, something transitory and unsatisfactory; often used as an adverb × altogether, vain, vanity.', 'or (rarely in the abs.) הֲבֵל; from 1891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6213A}/H9038/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["and/ he spends/ them"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2416A}/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["and/ the/ living person"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7814}/[H7832]', 'inflected', 'heb', 'שְׂחוֹק', '["sᵉchôwq"]', '["more than/ laughter"]', '["n-m"]', 'laughter (in merriment or defiance) derision, laughter(-ed to scorn, -ing), mocked, sport.', 'or שְׂחֹק; from 7832;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7455}/[H7489]', 'inflected', 'heb', 'רֹעַ', '["rôaʻ"]', '["by/ sadness of"]', '["n-m"]', 'badness (as marring), physically or morally × be so bad, badness, (× be so) evil, naughtiness, sadness, sorrow, wickedness.', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H6963H>', 'inflected', 'heb', 'כקול', '["ke./Kol","ke./kOl","ke./kol","khe./Kol"]', '["[was] like/ [the] sound of","like/ [the] sound of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5518B}/[H5518]', 'inflected', 'heb', 'סִיר', '["çîyr"]', '["<the>/ thorns"]', '["n-m"]', 'a pot; also a thorn (as springing up rapidly); by implication, a hook caldron, fishhook, pan, (wash-)pot, thorn.', 'or (feminine) סִירָה; or סִרָה; (Jeremiah 52:18), from a primitive root meaning to boil up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1364}/[H1361]', 'inflected', 'heb', 'גָּבֹהַּ', '["gâbôahh"]', '["from/ a high [place]","more than/ a [person] proud of"]', '["a"]', 'elevated (or elated), powerful, arrogant haughty, height, high(-er), lofty, proud, × exceeding proudly.', 'or גָּבוֹהַּ; (fully) from 1361;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7307J}/H9021/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["in/ spirit/ your"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2436G>', 'inflected', 'heb', 'בחיק', '["be./Cheik"]', '["in/ [the] bosom of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/H9009/<H3117G>', 'inflected', 'heb', 'שהימים', '["she./hai./ya.mim"]', '["that/ the/ days"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3148}/[H3498]', 'inflected', 'heb', 'יוֹתֵר', '["yôwthêr"]', '["and/ [is] an advantage","and/ besides","and/ excess"]', '["n-m"]', 'properly, redundant; hence, over and above, as adjective, noun, adverb or conjunction better, more(-over), over, profit.', 'active participle of 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1167J}/H9024/[H1166]', 'inflected', 'heb', 'בַּעַל', '["baʻal"]', '["owners/ its"]', '["n-m"]', 'a master; hence, a husband, or (figuratively) owner (often used with another noun in modifications of this latter sense) archer, babbler, bird, captain, chief man, confederate, have to do, dreamer, those to whom it is due, furious, those that are given to it, great, hairy, he that hath it, have, horseman, husband, lord, man, married, master, person, sworn, they of.', 'from 1166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5791}/H9033/[H5791]', 'inflected', 'heb', 'עָוַת', '["ʻâvath"]', '["he has bent/ it"]', '["v"]', 'to wrest bow self, (make) crooked., falsifying, overthrow, deal perversely, pervert, subvert, turn upside down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1892}/H9020/[H1891]', 'inflected', 'heb', 'הֶבֶל', '["hebel"]', '["futility/ my"]', '["n-m"]', 'emptiness or vanity; figuratively, something transitory and unsatisfactory; often used as an adverb × altogether, vain, vanity.', 'or (rarely in the abs.) הֲבֵל; from 1891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6664G}/H9023/[H6663]', 'inflected', 'heb', 'צֶדֶק', '["tsedeq"]', '["in/ righteousness/ his"]', '["n-m"]', 'the right (natural, moral or legal); also (abstractly) equity or (figuratively) prosperity × even, (× that which is altogether) just(-ice), (un-)right(-eous) (cause, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6256}/H9021/[H5703]', 'inflected', 'heb', 'עֵת', '["ʻêth"]', '["time/ your","times/ your"]', '["n-f"]', 'time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when.', 'from 5703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7989}/[H7980]', 'lemma', 'heb', 'שַׁלִּיט', '["shallîyṭ"]', '["having mastery","rulers"]', '["a"]', 'potent; concretely, a prince or warrior governor, mighty, that hath power, ruler.', 'from 7980;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2808}/[H2803]', 'inflected', 'heb', 'חֶשְׁבּוֹן', '["cheshbôwn"]', '["and/ an explanation","and/ explanation"]', '["n-m"]', 'properly, contrivance; by implication, intelligence account, device, reason.', 'from 2803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5531B}/[H5528]', 'inflected', 'heb', 'סִכְלוּת', '["çiklûwth"]', '["and/ the/ folly"]', '["n-f"]', 'silliness folly, foolishness.', 'or שִׂכְלוּת; (Ecclesiastes 1:17), from 5528;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2764B}/[H2763]', 'inflected', 'heb', 'חֵרֶם', '["chêrem"]', '["and/ [is] nets"]', '["n-m"]', 'physical (as shutting in) a net (either literally or figuratively); usually a doomed object; abstractly extermination (ac-) curse(-d, -d thing), dedicated thing, things which should have been utterly destroyed, (appointed to) utter destruction, devoted (thing), net.', 'or (Zechariah 14:11) חֶרֶם; from 2763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0612}/[H631]', 'lemma', 'heb', 'אֵסוּר', '["ʼêçûwr"]', '["[are] fetters"]', '["n-m"]', 'a bond (especially manacles of a prisoner) band, prison.', 'from 631;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2808}/[H2803]', 'lemma', 'heb', 'חֶשְׁבּוֹן', '["cheshbôwn"]', '["an explanation"]', '["n-m"]', 'properly, contrivance; by implication, intelligence account, device, reason.', 'from 2803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/H9009/{H2450}/[H2449]', 'inflected', 'heb', 'חָכָם', '["châkâm"]', '["[is] like/ the/ wise [person]"]', '["a"]', 'wise, (i.e. intelligent, skilful or artful) cunning (man), subtil, (un-), wise((hearted), man).', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6592}/[H6591]', 'lemma', 'heb', 'פֵּשֶׁר', '["pêsher"]', '["[the] interpretation of"]', '["n-m"]', 'interpretation.', 'corresponding to 6591');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8132}/[H8132]', 'lemma', 'heb', 'שָׁנָא', '["shânâʼ"]', '["it is changed"]', '["v"]', 'to alter change.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7983}/[H7980]', 'lemma', 'heb', 'שִׁלְטוֹן', '["shilṭôwn"]', '["[is] mastery"]', '["n-m"]', 'a potentate power.', 'from 7980;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3607}/[H3607]', 'inflected', 'heb', 'כָּלָא', '["kâlâʼ"]', '["to/ restrain"]', '["v"]', 'to restrict, by act (hold back or in) or word (prohibit) finish, forbid, keep (back), refrain, restrain, retain, shut up, be stayed, withhold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4725}/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["and/ from/ a place of"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0748}/[H748]', 'inflected', 'heb', 'אָרַךְ', '["ʼârak"]', '["and/ [he is] prolonging"]', '["v"]', 'to be (causative, make) long (literally or figuratively) defer, draw out, lengthen, (be, become, make, pro-) long, (out-, over-) live, tarry (long).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3373}/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["of/ [those] fearing","to/ [those] fearing"]', '["a"]', 'fearing; morally, reverent afraid, fear (-ful).', 'from 3372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H5060}/[H5060]', 'inflected', 'heb', 'נָגַע', '["nâgaʻ"]', '["[to] whom/ [it is] happening"]', '["v"]', 'properly, to touch, i.e. lay the hand upon (for any purpose; euphemistically, to lie with a woman); by implication, to reach (figuratively, to arrive, acquire); violently, to strike (punish, defeat, destroy, etc.) beat, (× be able to) bring (down), cast, come (nigh), draw near (nigh), get up, happen, join, near, plague, reach (up), smite, strike, touch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7623B}/[H7623]', 'inflected', 'heb', 'שָׁבַח', '["shâbach"]', '["and/ I commend"]', '["v"]', 'properly, to address in a loud tone, i.e. (specifically) loud; figuratively, to pacify (as if by words) commend, glory, keep in, praise, still, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3867A}/H9033/[H3867]', 'inflected', 'heb', 'לָוָה', '["lâvâh"]', '["it will accompany/ him"]', '["v"]', 'properly, to twine, i.e. (by implication) to unite, to remain; also to borrow (as a form of obligation) or (caus.) to lend abide with, borrow(-er), cleave, join (self), lend(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H9007}/H9005', 'inflected', 'heb', 'בשל', '["Be./she/l"]', '["in/ that/ <to>"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0952}/[H952]', 'inflected', 'heb', 'בּוּר', '["bûwr"]', '["and/ to/ make clear"]', '["v"]', 'to bore, i.e. (figuratively) examine declare.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2450}/[H2449]', 'inflected', 'heb', 'חָכָם', '["châkâm"]', '["and/ the/ wise"]', '["a"]', 'wise, (i.e. intelligent, skilful or artful) cunning (man), subtil, (un-), wise((hearted), man).', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5652}/H9028/[H5647]', 'inflected', 'heb', 'עֲבָד', '["ʻăbâd"]', '["and/ deeds/ their"]', '["n-m"]', 'a deed work.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7451H}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["and/ to the/ evil"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2889}/[H2891]', 'inflected', 'heb', 'טָהוֹר', '["ṭâhôwr"]', '["and/ to the/ clean"]', '["a"]', 'pure (in a physical, chemical, ceremonial or moral sense) clean, fair, pure(-ness).', 'or טָהֹר; from 2891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2931}/[H2930]', 'inflected', 'heb', 'טָמֵא', '["ṭâmêʼ"]', '["and/ to the/ unclean"]', '["a"]', 'foul in a religious sense defiled, infamous, polluted(-tion), unclean.', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2398}/[H2398]', 'inflected', 'heb', 'חָטָא', '["châṭâʼ"]', '["as the/ sinner"]', '["v"]', 'properly, to miss; hence (figuratively and generally) to sin; by inference, to forfeit, lack, expiate, repent, (causatively) lead astray, condemn bear the blame, cleanse, commit (sin), by fault, harm he hath done, loss, miss, (make) offend(-er), offer for sin, purge, purify (self), make reconciliation, (cause, make) sin(-ful, -ness), trespass.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0986}/[H982]', 'lemma', 'heb', 'בִּטָּחוֹן', '["biṭṭâchôwn"]', '["[is] hope"]', '["n-m"]', 'trust confidence, hope.', 'from 982;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H4191}/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["that/ they will die"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0160}/H9028/[H158]', 'inflected', 'heb', 'אַהֲבָה', '["ʼahăbâh"]', '["love/ their","to love/ them"]', '["n-f"]', 'love.', 'feminine of 158 and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8135}/H9028/[H8130]', 'inflected', 'heb', 'שִׂנְאָה', '["sinʼâh"]', '["hatred/ their"]', '["n-f"]', 'hate exceedingly, hate(-ful, -red).', 'from 8130;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7068}/H9028/[H7065]', 'inflected', 'heb', 'קִנְאָה', '["qinʼâh"]', '["envy/ their"]', '["n-f"]', 'jealousy or envy envy(-ied), jealousy, × sake, zeal.', 'from 7065;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3196>/H9021', 'opaque', 'heb', 'יַיִן', '["yayin"]', '["wine/ your"]', '["n-m"]', 'wine (as fermented); by implication, intoxication banqueting, wine, wine(-bibber).', 'from an unused root meaning to effervesce;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1892}/H9021/[H1891]', 'inflected', 'heb', 'הֶבֶל', '["hebel"]', '["futility/ your"]', '["n-m"]', 'emptiness or vanity; figuratively, something transitory and unsatisfactory; often used as an adverb × altogether, vain, vanity.', 'or (rarely in the abs.) הֲבֵל; from 1891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5999}/H9021/[H5998]', 'inflected', 'heb', 'עָמָל', '["ʻâmâl"]', '["and/ in/ toil/ your"]', '["n"]', 'toil, i.e. wearing effort; hence, worry, whether of body or mind grievance(-vousness), iniquity, labour, mischief, miserable(-sery), pain(-ful), perverseness, sorrow, toil, travail, trouble, wearisome, wickedness.', 'from 5998;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7031}/[H7043]', 'inflected', 'heb', 'קַל', '["qal"]', '["[belongs] to the/ swift"]', '["a"]', 'light; (by implication) rapid (also adverbial) light, swift(-ly).', 'contracted from 7043;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4793}/[H7323]', 'inflected', 'heb', 'מֵרוֹץ', '["mêrôwts"]', '["the/ race"]', '["n-m"]', 'a run (the trial of speed) race.', 'from 7323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6294}/[H6293]', 'inflected', 'heb', 'פֶּגַע', '["pegaʻ"]', '["and/ chance"]', '["n-m"]', 'impact (casual) chance, occurent.', 'from 6293;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6256}/H9023/[H5703]', 'inflected', 'heb', 'עֵת', '["ʻêth"]', '["time/ his"]', '["n-f"]', 'time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when.', 'from 5703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1709H}/[H1711]', 'inflected', 'heb', 'דָּג', '["dâg"]', '["like <the>/ fish<es>","like/ [the] fish of"]', '["n-m"]', 'a fish (often used collectively) fish.', 'or (fully) דָּאג; (Nehemiah 13:16), from 1711; a fish (as prolific); or perhaps rather from 1672 (as timid); but still better from 1672 (in the sense of squirming, i.e. moving by the vibratory action of the tail);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4685C}/[H6679]', 'inflected', 'heb', 'מָצוֹד', '["mâtsôwd"]', '["in/ a net"]', '["n-m"]', 'a net (for capturing animals or fishes); a fastness or (beseiging) tower bulwark, hold, munition, net, snare.', 'or (feminine) מְצוֹדָה; or מצֹדָה; from 6679; also (by interchange for 4679)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6341A}/[H6351]', 'inflected', 'heb', 'פַּח', '["pach"]', '["in <the>/ snare"]', '["n-m"]', 'a (metallic) sheet (as pounded thin); also a spring net (as spread out like a lamina) gin, (thin) plate, snare.', 'from 6351;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/H9007/{H5307G}/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["when/ that/ <it> falls"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4685A}/[H6679]', 'lemma', 'heb', 'מָצוֹד', '["mâtsôwd"]', '["siege works"]', '["n-m"]', 'a net (for capturing animals or fishes); a fastness or (beseiging) tower bulwark, hold, munition, net, snare.', 'or (feminine) מְצוֹדָה; or מצֹדָה; from 6679; also (by interchange for 4679)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2451}/H9023/[H2449]', 'inflected', 'heb', 'חׇכְמָה', '["chokmâh"]', '["by/ wisdom/ his","in/ wisdom/ his"]', '["n-f"]', 'wisdom (in a good sense) skilful, wisdom, wisely, wit.', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4542}/[H5531]', 'inflected', 'heb', 'מִסְכֵּן', '["miçkên"]', '["<the>/ poor","the/ poor [person]"]', '["a"]', 'indigent poor (man).', 'from 5531;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1369}/[H1368]', 'inflected', 'heb', 'גְּבוּרָה', '["gᵉbûwrâh"]', '["more than/ strength"]', '["n-f"]', 'force (literally or figuratively); by implication, valor, victory force, mastery, might, mighty (act, power), power, strength.', 'feminine passive participle from the same as 1368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5183A}/[H5182]', 'inflected', 'heb', 'נַחַת', '["Nachath"]', '["in/ quietness"]', '["n"]', 'a descent, i.e. imposition, unfavorable (punishment) or favorable (food); restfulness lighting down, quiet(-ness), to rest, be set on.', 'from 5182; also (intransitively; perhaps from 5117)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2070>', 'opaque', 'heb', 'זְבוּב', '["zᵉbûwb"]', '["flies of"]', '["n-m"]', 'a fly (especially one of a stinging nature) fly.', 'from an unused root (meaning to flit);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5531B}/[H5528]', 'lemma', 'heb', 'סִכְלוּת', '["çiklûwth"]', '["[is] folly","folly"]', '["n-f"]', 'silliness folly, foolishness.', 'or שִׂכְלוּת; (Ecclesiastes 1:17), from 5528;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8040G}/H9023/[H8071]', 'inflected', 'heb', 'שְׂמֹאול', '["sᵉmôʼwl"]', '["[is] to/ left [hand]/ his","and/ left/ his"]', '["n-m"]', 'properly, dark (as enveloped), i.e. the north; hence (by orientation), the left hand left (hand, side).', 'or שְׂמֹאל; a primitive word (rather perhaps from the same as 8071 (by insertion of the aleph) through the idea of wrapping up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/H9007/{H5530}/[H5528]', 'inflected', 'heb', 'סָכָל', '["çâkâl"]', '["like/ when/ a fool"]', '["n-m"]', 'silly fool(-ish), sottish.', 'from 5528;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7684}/[H7683]', 'inflected', 'heb', 'שְׁגָגָה', '["shᵉgâgâh"]', '["like/ an inadvertence"]', '["n-f"]', 'a mistake or inadvertent transgression error, ignorance, at unawares; unwittingly.', 'from 7683;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H3318G}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["that/ [is] going forth"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5529}/[H5528]', 'inflected', 'heb', 'סֶכֶל', '["çekel"]', '["<the>/ folly"]', '["n-m"]', 'silliness; concretely and collectively, dolts folly.', 'from 5528;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8216}/[H8213]', 'inflected', 'heb', 'שֶׁפֶל', '["shephel"]', '["in the/ low place"]', '["n-m"]', 'an humble rank low estate (place).', 'from 8213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1475>', 'opaque', 'heb', 'גּוּמָּץ', '["gûwmmâts"]', '["a pit"]', '["n-m"]', 'a pit pit.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6555}/[H6555]', 'inflected', 'heb', 'פָּרַץ', '["pârats"]', '["and/ [one who] breaks through"]', '["v"]', 'to break out (in many applications, direct and indirect, literal and figurative) × abroad, (make a) breach, break (away, down, -er, forth, in, up), burst out, come (spread) abroad, compel, disperse, grow, increase, open, press, scatter, urge.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5391A}/H9033/[H5391]', 'inflected', 'heb', 'נָשַׁךְ', '["nâshak"]', '["it will bite/ him"]', '["v"]', 'to strike with a sting (as a serpent); figuratively, to oppress with interest on a loan bite, lend upon usury.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5533A}/[H7915]', 'lemma', 'heb', 'סָכַן', '["çâkan"]', '["he will be endangered"]', '["v"]', 'properly, to cut, i.e. damage; also to grow (causatively, make) poor endanger, impoverish.', 'probably a denominative from 7915;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6949}/[H6949]', 'lemma', 'heb', 'קָהָה', '["qâhâh"]', '["it is blunt","they are blunt","they will be blunt"]', '["v"]', 'to be dull be set on edge, be blunt.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2428G}/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["and/ strength<s>"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3787}/[H3787]', 'lemma', 'heb', 'כָּשֵׁר', '["kâshêr"]', '["to give success","will it succeed"]', '["v"]', 'by implication, to be acceptable; also to succeed or prosper direct, be right, prosper.', 'a primitive root properly, to be straight or right;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3908}/[H3907]', 'lemma', 'heb', 'לַחַשׁ', '["lachash"]', '["[is] a charm","a whisper","charming"]', '["n-m"]', 'properly, a whisper, i.e. by implication, (in a good sense) a private prayer, (in a bad one) an incantation; concretely, an amulet charmed, earring, enchantment, orator, prayer.', 'from 3907;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3956G}/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["the/ tongue"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0319}/[H310]', 'inflected', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["and/ [the] end of"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1948}/[H1984]', 'lemma', 'heb', 'הוֹלֵלוּת', '["hôwlêlûwth"]', '["[is] madness"]', '["n-f"]', 'folly madness.', 'from active participle of 1984;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5530}/[H5528]', 'inflected', 'heb', 'סָכָל', '["çâkâl"]', '["and/ the/ fool"]', '["n-m"]', 'silly fool(-ish), sottish.', 'from 5528;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3021}/H9033/[H3021]', 'inflected', 'heb', 'יָגַע', '["yâgaʻ"]', '["it wearies/ him"]', '["v"]', 'properly, to gasp; hence, to be exhausted, to tire, to toil faint, (make to) labour, (be) weary.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1980M}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["to/ walk"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0337}/[H188]', 'lemma', 'heb', 'אִי', '["ʼîy"]', '["woe!"]', '["inj"]', 'alas! woe.', 'short from 188;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H4428G}/H9022/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["that/ king/ your"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8269}/H9022/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["and/ princes/ your"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0835}/H9032/[H833]', 'inflected', 'heb', 'אֶשֶׁר', '["ʼesher"]', '["how blessed [are]/ you"]', '["n-m"]', 'happiness; only in masculine plural construction as interjection, how happy! blessed, happy.', 'from 833;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8358}/[H8354]', 'inflected', 'heb', 'שְׁתִי', '["shᵉthîy"]', '["for <the>/ drinking"]', '["n-m"]', 'intoxicaion drunkenness.', 'from 8354;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6103}/[H6102]', 'inflected', 'heb', 'עַצְלָה', '["ʻatslâh"]', '["in/ laziness<es>"]', '["n-f"]', '(as abstractly) indolence slothfulness.', 'feminine of 6102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4355}/[H4355]', 'lemma', 'heb', 'מָכַךְ', '["mâkak"]', '["it sinks"]', '["v"]', 'to tumble (in ruins); figuratively, to perish be brought low, decay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4746}/[H7136]', 'inflected', 'heb', 'מְקָרֶה', '["mᵉqâreh"]', '["the/ rafter[s]"]', '["n-m"]', 'properly, something meeting, i.e. a frame (of timbers) building.', 'from 7136;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8220}/[H8213]', 'inflected', 'heb', 'שִׁפְלוּת', '["shiphlûwth"]', '["and/ in/ lowering of"]', '["n-f"]', 'remissness idleness.', 'from 8213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4093}/H9021/[H3045]', 'inflected', 'heb', 'מַדָּע', '["maddâʻ"]', '["in/ mind/ your"]', '["n-m"]', 'intelligence or consciousness knowledge, science, thought.', 'or מַדַּע; from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5645}/[H5743]', 'inflected', 'heb', 'עָב', '["ʻâb"]', '["the/ clouds"]', '["n-m"]', 'properly, an envelope, i.e. darkness (or density, 2 Chronicles 4:17); specifically, a (scud) cloud; also a copse clay, (thick) cloud, × thick, thicket. Compare 5672.', '(masculine and feminine); from 5743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H1864>', 'inflected', 'heb', 'בדרום', '["ba./da.Rom"]', '["at the/ south"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6828G}/[H6845]', 'inflected', 'heb', 'צָפוֹן', '["tsâphôwn"]', '["at the/ north"]', '["n-f"]', 'properly, hidden, i.e. dark; used only of the north as a quarter (gloomy and unknown) north(-ern, side, -ward, wind).', 'or צָפֹן; from 6845;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6106G}/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["like/ bones"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4392}/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["<the>/ full","the/ full [woman]","which/ [are] full"]', '["a"]', 'full (literally or figuratively) or filling (literally); also (concretely) fulness; adverbially, fully × she that was with child, fill(-ed, -ed with), full(-ly), multitude, as is worth.', 'from 4390;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3605}/H9028/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["in/ all of/ them"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2142}/[H2145]', 'inflected', 'heb', 'זָכַר', '["zâkar"]', '["and/ he may remember","and/ remember"]', '["v"]', 'properly, to mark (so as to be recognized), i.e. to remember; by implication, to mention; to be male × burn (incense), × earnestly, be male, (make) mention (of), be mindful, recount, record(-er), remember, make to be remembered, bring (call, come, keep, put) to (in) remembrance, × still, think on, × well.', 'a primitive root; also as denominative from 2145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3208}/H9021/[H3206]', 'inflected', 'heb', 'יַלְדוּת', '["yaldûwth"]', '["in/ youth/ your"]', '["n-f"]', 'boyhood (or girlhood) childhood, youth.', 'abstractly from 3206;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3190}/H9031/[H3190]', 'inflected', 'heb', 'יָטַב', '["yâṭab"]', '["and/ let it make good/ you"]', '["v"]', 'to be (causative) make well, literally (sound, beautiful) or figuratively (happy, successful, right) be accepted, amend, use aright, benefit, be (make) better, seem best, make cheerful, be comely, be content, diligent(-ly), dress, earnestly, find favour, give, be glad, do (be, make) good(-ness), be (make) merry, please ( well), shew more (kindness), skilfully, × very small, surely, make sweet, thoroughly, tire, trim, very, be (can, deal, entreat, go, have) well (said, seen).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0979}/H9021/[H970]', 'inflected', 'heb', 'בְּחֻרוֹת', '["bᵉchurôwth"]', '["youth<s>/ your"]', '["n-f"]', 'youth (collectively and abstractly) young men, youth.', 'or בְּחוּרוֹת; feminine plural of 970; also (masculine plural) בְּחֻרִים;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4758}/[H7200]', 'inflected', 'heb', 'מַרְאֶה', '["marʼeh"]', '["and/ in/ [the] sight of"]', '["n-m"]', 'a view (the act of seeing); also an appearance (the thing seen), whether (real) a shape (especially if handsome, comeliness; often plural the looks), or (mental) a vision × apparently, appearance(-reth), × as soon as beautiful(-ly), countenance, fair, favoured, form, goodly, to look (up) on (to), look(-eth), pattern, to see, seem, sight, visage, vision.', 'from 7200a;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1320}/H9021/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["from/ flesh/ your"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3208}/[H3206]', 'inflected', 'heb', 'יַלְדוּת', '["yaldûwth"]', '["<the>/ youth"]', '["n-f"]', 'boyhood (or girlhood) childhood, youth.', 'abstractly from 3206;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7839}/[H7836]', 'inflected', 'heb', 'שַׁחֲרוּת', '["shachărûwth"]', '["and/ the/ black hair"]', '["n-f"]', 'a dawning, i.e. (figuratively) juvenescence youth.', 'from 7836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1254A}/H9031/[H1254]', 'inflected', 'heb', 'בָּרָא', '["bârâʼ"]', '["[who] created/ you","creator<s>/ your"]', '["v"]', '(absolutely) to create; (qualified) to cut down (a wood), select, feed (as formative processes) choose, create (creator), cut down, dispatch, do, make (fat).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0216}/[H215]', 'inflected', 'heb', 'אוֹר', '["ʼôwr"]', '["and/ the/ light"]', '["n-f"]', 'illumination or (concrete) luminary (in every sense, including lightning, happiness, etc.) bright, clear, day, light (-ning), morning, sun.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3556}/[H3522]', 'inflected', 'heb', 'כּוֹכָב', '["kôwkâb"]', '["and/ the/ stars"]', '["n-m"]', 'a star (as round or as shining); figuratively, a prince star(-gazer).', 'probably from the same as 3522 (in the sense of rolling) or 3554 (in the sense of blazing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H2111}/[H2111]', 'inflected', 'heb', 'זוּעַ', '["zûwaʻ"]', '["when/ they will tremble"]', '["v"]', 'properly, to shake off, i.e. (figuratively) to agitate (as with fear) move, tremble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5791}/[H5791]', 'inflected', 'heb', 'עָוַת', '["ʻâvath"]', '["and/ they will bend themselves"]', '["v"]', 'to wrest bow self, (make) crooked., falsifying, overthrow, deal perversely, pervert, subvert, turn upside down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0988}/[H988]', 'inflected', 'heb', 'בָּטֵל', '["bâṭêl"]', '["and/ they will cease"]', '["v"]', 'to desist from labor cease.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2912}/[H2912]', 'inflected', 'heb', 'טָחַן', '["ṭâchan"]', '["the/ [female] grinders"]', '["v"]', 'to grind meal; hence, to be a concubine (that being their employment) grind(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0699}/[H693]', 'inflected', 'heb', 'אֲרֻבָּה', '["ʼărubbâh"]', '["in the/ windows"]', '["n-f"]', 'a lattice; (by implication) a window, dovecot (because of the pigeon-holes), chimney (with its apertures for smoke), sluice (with openings for water) chimney, window.', 'feminine participle passive of 693 (as if for lurking);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8213}/[H8213]', 'inflected', 'heb', 'שָׁפֵל', '["shâphêl"]', '["when/ becomes low"]', '["v"]', 'to depress or sink (especially figuratively, to humiliate, intransitive or transitive) abase, bring (cast, put) down, debase, humble (self), be (bring, lay, make, put) low(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2913}/[H2912]', 'inflected', 'heb', 'טַחֲנָה', '["ṭachănâh"]', '["the/ grinding mill"]', '["n-f"]', 'a hand mill; hence (figuratively) chewing grinding.', 'from 2912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7817}/[H7817]', 'inflected', 'heb', 'שָׁחַח', '["shâchach"]', '["and/ they may be reduced"]', '["v"]', 'to sink or depress (reflexive or causative) bend, bow (down), bring (cast) down, couch, humble self, be (bring) low, stoop.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2849}/[H2844]', 'inflected', 'heb', 'חַתְחַת', '["chathchath"]', '["and/ terrors"]', '["n-m"]', 'terror fear.', 'from 2844;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5006}/[H5006]', 'inflected', 'heb', 'נָאַץ', '["nâʼats"]', '["and/ it may blossom"]', '["v"]', 'to scorn; or (in Ecclesiastes 12:5), by interchange for 5132, to bloom abhor, (give occasion to) blaspheme, contemn, despise, flourish, × great, provoke.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8247}/[H8245]', 'inflected', 'heb', 'שָׁקֵד', '["shâqêd"]', '["the/ almond tree"]', '["n-m"]', 'the almond (tree or nut; as being the earliest in bloom) almond (tree).', 'from 8245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5445}/[H5445]', 'inflected', 'heb', 'סָבַל', '["çâbal"]', '["so/ it may drag itself along"]', '["v"]', 'to carry (literally or figuratively), or (reflexively) be burdensome; specifically, to be gravid bear, be a burden, carry, strong to labour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0035}/[H14]', 'inflected', 'heb', 'אֲבִיּוֹנָה', '["ʼăbîyôwnâh"]', '["the/ caper-berry"]', '["n-f"]', 'provocative of desire; the caper berry (from its stimulative taste) desire.', 'from 14;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5769G}/H9023/[H5956]', 'inflected', 'heb', 'עוֹלָם', '["ʻôwlâm"]', '["perpetuity/ its"]', '["n-m"]', 'properly, concealed, i.e. the vanishing point; generally, time out of mind (past or future), i.e. (practically) eternity; frequentatively, adverbial (especially with prepositional prefix) always alway(-s), ancient (time), any more, continuance, eternal, (for, (n-)) ever(-lasting, -more, of old), lasting, long (time), (of) old (time), perpetual, at any time, (beginning of the) world ( without end). Compare 5331, 5703.', 'or עֹלָם; from 5956;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5594}/[H5594]', 'inflected', 'heb', 'סָפַד', '["çâphad"]', '["the/ mourners"]', '["v"]', 'properly, to tear the hair and beat the breasts (as Orientals do in grief); generally to lament; by implication, to wail lament, mourn(-er), wail.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7576}/[H7576]', 'lemma', 'heb', 'רָתַק', '["râthaq"]', '["it will be snapped"]', '["v"]', 'to fasten bind.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4002}/[H5042]', 'inflected', 'heb', 'מַבּוּעַ', '["mabbûwaʻ"]', '["the/ water spring"]', '["n-m"]', 'a fountain fountain, spring.', 'from 5042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1534}/[H1556]', 'inflected', 'heb', 'גַּלְגַּל', '["galgal"]', '["the/ [water] wheel","the/ wheel"]', '["n-m"]', 'a wheel; by analogy, a whirlwind; also dust (as whirled) heaven, rolling thing, wheel.', 'by reduplication from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/H9007/{H1961}/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["like/ which/ it was"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7307G}/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["and/ the/ spirit"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6953}/[H6950]', 'inflected', 'heb', 'קֹהֶלֶת', '["qôheleth"]', '["the/ Teacher"]', '["n-m"]', 'a (female) assembler (i.e. lecturer); abstractly, preaching (used as a ''nom de plume'', Koheleth) preacher.', 'feminine of active participle from 6950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0239}/[H238]', 'inflected', 'heb', 'אָזַן', '["ʼâzan"]', '["and/ he weighed"]', '["v"]', 'to weigh, i.e. (figuratively) ponder give good heed.', 'a primitive root (rather identical with 238 through the idea of scales as if two ears);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8626}/[H8626]', 'lemma', 'heb', 'תָּקַן', '["tâqan"]', '["he arranged in order"]', '["v"]', 'to equalize, i.e. straighten (intransitive or transitive); figuratively, to compose set in order, make straight.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H1861B>', 'inflected', 'heb', 'כדרבנות', '["ka./Da.re.vo.Not"]', '["[are] like <the>/ goads"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H4930}/[H4548]', 'inflected', 'heb', 'מַשְׂמְרָה', '["masmᵉrâh"]', '["and/ [are] like/ nails"]', '["n-f"]', 'a peg nail.', 'for 4548 fem.;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0627}/[H624]', 'lemma', 'heb', 'אֲסֻפָּה', '["ʼăçuppâh"]', '["collections"]', '["n-f"]', 'a collection of (learned) men (only in the plural) assembly.', 'feminine of 624;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7462B}/[H7462]', 'inflected', 'heb', 'רָעָה', '["râʻâh"]', '["from/ a shepherd","from/ shepherding"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3854>', 'inflected', 'heb', 'ולהג', '["ve./La.hag"]', '["and/ study"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3024}/[H3019]', 'lemma', 'heb', 'יְגִעָה', '["yᵉgiʻâh"]', '["[is] weariness of"]', '["n-f"]', 'fatigue weariness.', 'feminine of 3019;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5401A}/H9030/[H5400]', 'inflected', 'heb', 'נָשַׁק', '["nâshaq"]', '["let him kiss/ me"]', '["v"]', 'to kiss, literally or figuratively (touch); also (as a mode of attachment), to equip with weapons armed (men), rule, kiss, that touched.', 'a primitive root (identical with 5400, through the idea of fastening up; compare 2388, 2836);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5390}/[H5401]', 'inflected', 'heb', 'נְשִׁיקָה', '["nᵉshîyqâh"]', '["from/ [the] kisses of"]', '["n-f"]', 'a kiss kiss.', 'from 5401;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1730H>/H9021', 'opaque', 'heb', 'דּוֹד', '["dôwd"]', '["love<s>/ your"]', '["n-m"]', '(figuratively) to love; by implication, a love-token, lover, friend; specifically an uncle (well-) beloved, father''s brother, love, uncle.', 'or (shortened) דֹּד; from an unused root meaning properly, to boil, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8081}/H9021/[H8080]', 'inflected', 'heb', 'שֶׁמֶן', '["shemen"]', '["oils/ your"]', '["n-m"]', 'grease, especially liquid (as from the olive, often perfumed); figuratively, richness anointing, × fat (things), × fruitful, oil(-ed), ointment, olive, pine.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2315}/H9023/[H2314]', 'inflected', 'heb', 'חֶדֶר', '["cheder"]', '["chambers/ his"]', '["n-m"]', 'an apartment (usually literal) ((bed) inner) chamber, innermost(-ward) part, parlour, south, × within.', 'from 2314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0157G}/H9031\/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["they love/ you"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5000}/[H4998]', 'inflected', 'heb', 'נָאוֶה', '["nâʼveh"]', '["and/ lovely"]', '["a"]', 'suitable, or beautiful becometh, comely, seemly.', 'from 4998 or 5116;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0168G}/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["like <the>/ tent","like/ [the] tent of","like/ [the] tents of"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7840}/[H7835]', 'lemma', 'heb', 'שְׁחַרְחֹרֶת', '["shᵉcharchôreth"]', '["[am] blackish"]', '["a"]', 'swarthy black.', 'from 7835;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H7805}/H9030/[H7805]', 'inflected', 'heb', 'שָׁזַף', '["shâzaph"]', '["[on] whom/ <it> has looked on/ me"]', '["v"]', 'to tan (by sunburning); figuratively (as if by a piercing ray) to scan look up, see.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/H9005/{H9030}', 'inflected', 'heb', 'שלי', '["she./L/i"]', '["which/ [belongs] to/ me"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H0157G}/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["[O] whom/ it loves","whom/ it loves"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/H9005/{H4100}/[H4100]', 'inflected', 'heb', 'מָה', '["mâh"]', '["which/ to/ why?"]', '["i"]', 'properly, interrogative what? (including how? why? when?); but also exclamation, what! (including how!), or indefinitely what (including whatever, and even relatively, that which); often used with prefixes in various adverbial or conjunctive senses how (long, oft, (-soever)), (no-) thing, what (end, good, purpose, thing), whereby(-fore, -in, -to, -with), (for) why.', 'or מַה; or מָ; or מַ; also מֶה; a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5844A}/[H5844]', 'inflected', 'heb', 'עָטָה', '["ʻâṭâh"]', '["like/ a veiled [woman]"]', '["v"]', 'to wrap, i.e. cover, veil, clothe, or roll array self, be clad, (put a) cover (-ing, self), fill, put on, × surely, turn aside.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2270}/H9021/[H2266]', 'inflected', 'heb', 'חָבֵר', '["châbêr"]', '["companions/ your"]', '["n-m"]', 'an associate companion, fellow, knit together.', 'from 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3303}/[H3302]', 'inflected', 'heb', 'יָפֶה', '["yâpheh"]', '["<the>/ beautiful","O/ beautiful [one]"]', '["a"]', 'beautiful (literally or figuratively) beautiful, beauty, comely, fair(-est, one), goodly, pleasant, well.', 'from 3302;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7462B}/[H7462]', 'inflected', 'heb', 'רָעָה', '["râʻâh"]', '["and/ a shepherd","and/ pasture","and/ shepherds"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1429}/H9022/[H1423]', 'inflected', 'heb', 'גְּדִיָּה', '["gᵉdîyâh"]', '["young goats/ your"]', '["n-f"]', 'a young female goat kid.', 'feminine of 1423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7462B}\/[H7462]', 'inflected', 'heb', 'רָעָה', '["râʻâh"]', '["the/ shepherds"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5484}/H9020/[H5483]', 'inflected', 'heb', 'סוּסָה', '["çûwçâh"]', '["to/ mare/ my"]', '["n-f"]', 'a mare company of horses.', 'feminine of 5483;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1819}/H9032/[H1819]', 'inflected', 'heb', 'דָּמָה', '["dâmâh"]', '["I liken/ you"]', '["v"]', 'to compare; by implication, to resemble, liken, consider compare, devise, (be) like(-n), mean, think, use similitudes.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7474}/H9020/[H7453]', 'inflected', 'heb', 'רַעְיָה', '["raʻyâh"]', '["O friend/ my","friend/ my"]', '["n-f"]', 'a female associate fellow, love.', 'feminine of 7453;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3895H>/H9022', 'opaque', 'heb', 'לְחִי', '["lᵉchîy"]', '["cheeks/ your"]', '["n-m"]', 'the cheek (from its fleshiness); hence, the jaw-bone cheek (bone), jaw (bone).', 'from an unused root meaning to be soft;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8447}/[H8446]', 'inflected', 'heb', 'תּוֹר', '["tôwr"]', '["with <the>/ strings of jewels"]', '["n-m"]', 'a succession, i.e. a string or (abstractly) order border, row, turn.', 'or תֹּר; from 8446;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6677A}/H9022/[H6696]', 'inflected', 'heb', 'צַוָּאר', '["tsavvâʼr"]', '["neck/ your"]', '["n-m"]', 'the back of the neck (as that on which burdens are bound) neck.', 'or צַוָּר; (Nehemiah 3:5), or צַוָּרֹןlemma צַוָּרן missing vowel, corrected to צַוָּרֹן; (Song of Solomon 4:9), or (feminine) צַוָּארָה; (Micah 2:3), intensively from 6696 in the sense of binding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2737>', 'inflected', 'heb', 'בחרוזים', '["ba./cha.ru.Zim"]', '["with <the>/ strings of beads"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5351}/[H5348]', 'lemma', 'heb', 'נְקֻדָּה', '["nᵉquddâh"]', '["<the> beads of"]', '["n-f"]', 'a boss stud.', 'feminine of 5348;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/H9009/{H4428G}/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["that/ the/ king"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4524}/H9023/[H5437]', 'inflected', 'heb', 'מֵסַב', '["mêçab"]', '["[was] at/ table/ his"]', '["n-m"]', 'a divan (as enclosing the room); abstractly (adverbial) around that compass about, (place) round about, at table.', 'plural masculine מְסִבִּים; or feminine מְסִבּוֹת; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5373>/H9020', 'opaque', 'heb', 'נֵרְדְּ', '["nêrd"]', '["nard/ my"]', '["n-m"]', 'nard, an aromatic spikenard.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7381}/H9023/[H7306]', 'inflected', 'heb', 'רֵיחַ', '["rêyach"]', '["odor/ its"]', '["n-m"]', 'odor (as if blown) savour, scent, smell.', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1730G>/H9020', 'opaque', 'heb', 'דּוֹד', '["dôwd"]', '["O lover/ my","[is] lover/ my","lover/ my"]', '["n-m"]', '(figuratively) to love; by implication, a love-token, lover, friend; specifically an uncle (well-) beloved, father''s brother, love, uncle.', 'or (shortened) דֹּד; from an unused root meaning properly, to boil, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7699A}/H9020/[H7736]', 'inflected', 'heb', 'שַׁד', '["shad"]', '["breasts/ my"]', '["n-m"]', 'the breast of a woman or animal (as bulging) breast, pap, teat.', 'or שֹׁד; probably from 7736 (in its original sense) contracted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3724C}/[H3722]', 'inflected', 'heb', 'כֹּפֶר', '["kôpher"]', '["<the>/ henna blossom"]', '["n-m"]', 'properly, a cover, i.e. (literally) a village (as covered in); (specifically) bitumen (as used for coating), and the henna plant (as used for dyeing); figuratively, a redemption-price bribe, camphire, pitch, ransom, satisfaction, sum of money, village.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2005}/H9042/[H2005]', 'inflected', 'heb', 'הֵן', '["hên"]', '["here/ you"]', '["prt"]', 'lo!; also (as expressing surprise) if behold, if, lo, though.', 'a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6210>/H9025', 'opaque', 'heb', 'עֶרֶשׂ', '["ʻeres"]', '["bed/ our"]', '["n-f"]', 'a couch (properly, with a canopy) bed(-stead), couch.', 'from an unused root meaning perhaps to arch;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7351}/H9025/[H7298]', 'inflected', 'heb', 'רְחִיט', '["rᵉchîyṭ"]', '["rafters/ our"]', '["n-m"]', 'a panel (as resembling a trough) rafter.', 'from the same as 7298;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1266}/[H1265]', 'lemma', 'heb', 'בְּרוֹת', '["bᵉrôwth"]', '["[are] cypress<es>"]', '["n-m"]', 'the cypress (or some elastic tree) fir.', 'a variation of 1265;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2261>', 'opaque', 'heb', 'חֲבַצֶּלֶת', '["chăbatstseleth"]', '["[am] [the] crocus of"]', '["n-f"]', 'probably meadow-saffron rose.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8289I}/[H3474]', 'inflected', 'heb', 'שָׁרוֹן', '["Shârôwn"]', '["<the>/ Sharon"]', '["n-pr"]', 'Sharon, the name of a place in Palestine Lasharon, Sharon.', 'probably abridged from 3474; plain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7799}/[H7797]', 'inflected', 'heb', 'שׁוּשַׁן', '["shûwshan"]', '["like <the>/ lily","like/ a lily"]', '["n-m"]', 'a lily (from its whiteness), as a flower of architectural ornament; also a (straight) trumpet (from the tubular shape) lily, Shoshannim.', 'or שׁוֹשָׁן; or שֹׁשָׁן; and (feminine) שׁוֹשַׁנָּה; from 7797;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8598}/[H5301]', 'inflected', 'heb', 'תַּפּוּחַ', '["tappûwach"]', '["like <the>/ apples","like/ an apple tree"]', '["n-m"]', 'an apple (from its fragrance), i.e. the fruit or the tree (probably includ. others of the pome order, as the quince, the orange, etc.) apple (tree). See also 1054.', 'from 5301;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6738}/H9023/[H6751]', 'inflected', 'heb', 'צֵל', '["tsêl"]', '["in/ shade/ his","in/ shade/ its","in/ shadow/ his"]', '["n-m"]', 'shade, whether literal or figurative defence, shade(-ow).', 'from 6751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6529}/H9023/[H6509]', 'inflected', 'heb', 'פְּרִי', '["pᵉrîy"]', '["and/ fruit/ his","and/ fruit/ its"]', '["n-m"]', 'fruit (literally or figuratively) bough, (first-)fruit(-ful), reward.', 'from 6509;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1714}/H9023/[H1713]', 'inflected', 'heb', 'דֶּגֶל', '["degel"]', '["and/ standard/ his"]', '["n-m"]', 'a flag banner, standard.', 'from 1713;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0809}/[H808]', 'inflected', 'heb', 'אֲשִׁישָׁה', '["ʼăshîyshâh"]', '["with <the>/ raisin-cakes"]', '["n-f"]', 'something closely pressed together, i.e. a cake of raisins or other comfits flagon.', 'feminine of 808;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7502}/H9030/[H7502]', 'inflected', 'heb', 'רָפַד', '["râphad"]', '["refresh/ me"]', '["v"]', 'to spread (a bed); by implication, to refresh comfort, make (a bed), spread.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8598}/[H5301]', 'inflected', 'heb', 'תַּפּוּחַ', '["tappûwach"]', '["with <the>/ apples"]', '["n-m"]', 'an apple (from its fragrance), i.e. the fruit or the tree (probably includ. others of the pome order, as the quince, the orange, etc.) apple (tree). See also 1054.', 'from 5301;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3225G}/H9023/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["and/ right [hand]/ his"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2263}/H9030/[H2263]', 'inflected', 'heb', 'חָבַק', '["châbaq"]', '["it embraces/ me"]', '["v"]', 'to clasp (the hands or in embrace) embrace, fold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6643B}/[H6638]', 'inflected', 'heb', 'צְבִי', '["tsᵉbîy"]', '["by/ gazelles"]', '["n-m"]', 'splendor (as conspicuous) beautiful(-ty), glorious (-ry), goodly, pleasant, roe(-buck).', 'from 6638 in the sense of prominence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0355}/[H354]', 'inflected', 'heb', 'אַיָּלָה', '["ʼayâlâh"]', '["by/ [the] does of"]', '["n-f"]', 'a doe or female deer hind.', 'feminine of 354;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0160}/[H158]', 'inflected', 'heb', 'אַהֲבָה', '["ʼahăbâh"]', '["<the>/ love"]', '["n-f"]', 'love.', 'feminine of 158 and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H2654A}\/[H2654]', 'inflected', 'heb', 'חָפֵץ', '["châphêts"]', '["that/ it will please"]', '["v"]', 'properly, to incline to; by implication (literally but rarely) to bend; figuratively, to be pleased with, desire × any at all, (have, take) delight, desire, favour, like, move, be (well) pleased, have pleasure, will, would.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6643B}/[H6638]', 'inflected', 'heb', 'צְבִי', '["tsᵉbîy"]', '["<to>/ a gazelle"]', '["n-m"]', 'splendor (as conspicuous) beautiful(-ty), glorious (-ry), goodly, pleasant, roe(-buck).', 'from 6638 in the sense of prominence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6082}/[H6080]', 'inflected', 'heb', 'עֹפֶר', '["ʻôpher"]', '["<to>/ [the] fawn of"]', '["n-m"]', 'a fawn (from the dusty color) young roe (hart).', 'from 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3796>/H9025', 'opaque', 'heb', 'כֹּתֶל', '["kôthel"]', '["wall/ our"]', '["n-m"]', 'a wall (as gathering inmates) wall.', 'from an unused root meaning to compact;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6692B}/[H6692]', 'lemma', 'heb', 'צוּץ', '["tsûwts"]', '["[is] peering"]', '["v"]', 'to twinkle, i.e. glance; by analogy, to blossom (figuratively, flourish) bloom, blossom, flourish, shew self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2762}/[H2760]', 'inflected', 'heb', 'חֶרֶךְ', '["cherek"]', '["the/ lattices"]', '["n-m"]', 'properly, a net, i.e. (by analogy) lattice lattice.', 'from 2760;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3303}/H9020/[H3302]', 'inflected', 'heb', 'יָפֶה', '["yâpheh"]', '["beautiful [one]/ my"]', '["a"]', 'beautiful (literally or figuratively) beautiful, beauty, comely, fair(-est, one), goodly, pleasant, well.', 'from 3302;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5638>', 'inflected', 'heb', 'הסתיו', '["ha./se.tav"]', '["the/ winter"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5339}/[H5322]', 'inflected', 'heb', 'נִצָּן', '["nitstsân"]', '["the/ blossoms"]', '["n-m"]', 'a blossom flower.', 'from 5322;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2159}/[H2168]', 'inflected', 'heb', 'זָמִיר', '["zâmîyr"]', '["<the>/ pruning"]', '["n-m"]', 'a twig (as pruned) branch.', 'from 2168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2590A}/[H2590]', 'lemma', 'heb', 'חָנַט', '["chânaṭ"]', '["it has ripened"]', '["v"]', 'to spice; by implication, to embalm; also to ripen embalm, put forth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6291>/H9024', 'opaque', 'heb', 'פַּג', '["pag"]', '["early figs/ its"]', '["n-m"]', 'crude; an unripe fig green figuratively', 'from an unused root meaning to be torpid, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H1612>', 'inflected', 'heb', 'והגפנים', '["ve./ha./ge.fa.Nim"]', '["and/ the/ vines"]', NULL, NULL, NULL);
