INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3123}/H9020/[H3196]', 'inflected', 'heb', 'יוֹנָה', '["yôwnâh"]', '["O dove/ my","dove/ my"]', '["n-f"]', 'a dove (apparently from the warmth of their mating) dove, pigeon.', 'probably from the same as 3196;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2288>', 'inflected', 'heb', 'בחגוי', '["be./chag.Vei","ve./chag.vei"]', '["in/ [the] clefts of","in/ clefts of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H4095>', 'inflected', 'heb', 'המדרגות', '["ha./mad.re.Gah","ha./mad.re.Got"]', '["the/ steep place","the/ steep places"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4758}/H9022/[H7200]', 'inflected', 'heb', 'מַרְאֶה', '["marʼeh"]', '["form/ your"]', '["n-m"]', 'a view (the act of seeing); also an appearance (the thing seen), whether (real) a shape (especially if handsome, comeliness; often plural the looks), or (mental) a vision × apparently, appearance(-reth), × as soon as beautiful(-ly), countenance, fair, favoured, form, goodly, to look (up) on (to), look(-eth), pattern, to see, seem, sight, visage, vision.', 'from 7200a;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6963A>/H9022', 'opaque', 'heb', 'קוֹל', '["qôwl"]', '["voice/ your"]', '["n-m"]', 'a voice or sound aloud, bleating, crackling, cry ( out), fame, lightness, lowing, noise, hold peace, (pro-) claim, proclamation, sing, sound, spark, thunder(-ing), voice, yell.', 'or קֹל; from an unused root meaning to call aloud;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4758}/H9022/[H7200]', 'inflected', 'heb', 'מַרְאֶה', '["marʼeh"]', '["and/ form/ your"]', '["n-m"]', 'a view (the act of seeing); also an appearance (the thing seen), whether (real) a shape (especially if handsome, comeliness; often plural the looks), or (mental) a vision × apparently, appearance(-reth), × as soon as beautiful(-ly), countenance, fair, favoured, form, goodly, to look (up) on (to), look(-eth), pattern, to see, seem, sight, visage, vision.', 'from 7200a;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5000}\/[H4998]', 'inflected', 'heb', 'נָאוֶה', '["nâʼveh"]', '["[is] lovely"]', '["a"]', 'suitable, or beautiful becometh, comely, seemly.', 'from 4998 or 5116;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7799}/[H7797]', 'inflected', 'heb', 'שׁוּשַׁן', '["shûwshan"]', '["among the/ lilies","with <the>/ lilies"]', '["n-m"]', 'a lily (from its whiteness), as a flower of architectural ornament; also a (straight) trumpet (from the tubular shape) lily, Shoshannim.', 'or שׁוֹשָׁן; or שֹׁשָׁן; and (feminine) שׁוֹשַׁנָּה; from 7797;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H6315}/[H6315]', 'inflected', 'heb', 'פּוּחַ', '["pûwach"]', '["that/ <it> will breathe"]', '["v"]', 'to puff, i.e. blow with the breath or air; hence, to fan (as a breeze), to utter, to kindle (a fire), to scoff blow (upon), break, puff, bring into a snare, speak, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6752}/[H6751]', 'inflected', 'heb', 'צֵלֶל', '["tsêlel"]', '["the/ shadows"]', '["n-m"]', 'shade shadow.', 'from 6751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1336}\/[H1335]', 'inflected', 'heb', 'בֶּתֶר', '["Bether"]', '["ravine[s]"]', '["n-pr-m"]', 'Bether, a (craggy) place in Palestine Bether.', 'the same as 1335;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H5674A}/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["that/ I had passed away"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H4672}/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["that/ I found"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0270}/H9033/[H270]', 'inflected', 'heb', 'אָחַז', '["ʼâchaz"]', '["I grasped/ him"]', '["v"]', 'to seize (often with the accessory idea of holding in possession) be affrighted, bar, (catch, lay, take) hold (back), come upon, fasten, handle, portion, (get, have or take) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7503}/H9033/[H7503]', 'inflected', 'heb', 'רָפָה', '["râphâh"]', '["I let go/ him"]', '["v"]', 'to slacken (in many applications, literal or figurative) abate, cease, consume, draw (toward evening), fail, (be) faint, be (wax) feeble, forsake, idle, leave, let alone (go, down), (be) slack, stay, be still, be slothful, (be) weak(-en). See 7495.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H0935P}/H9033/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["that/ I had brought/ him"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8490}/[H8558]', 'inflected', 'heb', 'תִּימָרָה', '["tîymârâh"]', '["like/ columns of"]', '["n-f"]', 'a column, i.e. cloud pillar.', 'or תִּמָרָה; from the same as 8558;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6999I}/[H6999]', 'lemma', 'heb', 'קָטַר', '["qâṭar"]', '["[who is] perfumed of"]', '["v n-m n-f"]', 'to smoke, i.e. turn into fragrance by fire (especially as an act of worship) burn (incense, sacrifice) (upon), (altar for) incense, kindle, offer (incense, a sacrifice).', 'a primitive root (identical with through the idea of fumigation in a close place and perhaps thus driving out the occupants);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0081}/[H80]', 'lemma', 'heb', 'אֲבָקָה', '["ʼăbâqâh"]', '["[the] scent-powder of"]', '["n-f"]', 'powder.', 'feminine of 80');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7402}/[H7402]', 'lemma', 'heb', 'רָכַל', '["râkal"]', '["[the] trader","[the] traders of","a trader","traders"]', '["v"]', 'to travel for trading (spice) merchant.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/H9005/{H8010}/[H7965]', 'inflected', 'heb', 'שְׁלֹמֹה', '["Shᵉlômôh"]', '["which/ [belongs] to/ Solomon"]', '["n-pr-m"]', 'Shelomah, David''s successor Solomon.', 'from 7965; peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3915}\/[H3883]', 'inflected', 'heb', 'לַיִל', '["layil"]', '["in the/ nights"]', '["n-m"]', 'properly, a twist (away of the light), i.e. night; figuratively, adversity (mid-)night (season).', 'or (Isaiah 21:11) לֵיל; also לַיְלָה; from the same as 3883;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0668}/[H668]', 'lemma', 'heb', 'אַפִּרְיוֹן', '["ʼappiryôwn"]', '["a litter"]', '["n-m"]', 'a palanquin chariot.', 'probably of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6086G}/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["from/ [the] wood<s>","from/ [the] wood<s> of"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7507}/H9023/[H7502]', 'inflected', 'heb', 'רְפִידָה', '["rᵉphîydâh"]', '["back/ its"]', '["n-f"]', 'a railing (as spread along) bottom.', 'from 7502;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4817}/H9023/[H7392]', 'inflected', 'heb', 'מֶרְכָּב', '["merkâb"]', '["seat/ its"]', '["n-m"]', 'a chariot; also a seat (in a vehicle) chariot, covering, saddle.', 'from 7392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7528}/[H7529]', 'lemma', 'heb', 'רָצַף', '["râtsaph"]', '["[was] fitted out"]', '["v"]', 'to tessellate, i.e. embroider (as if with bright stones) pave.', 'a denominative from 7529;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5850}/[H5849]', 'inflected', 'heb', 'עֲטָרָה', '["ʻăṭârâh"]', '["on the/ crown"]', '["n-f"]', 'a crown crown.', 'from 5849;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H5849B}/[H5849]', 'inflected', 'heb', 'עָטַר', '["ʻâṭar"]', '["that/ <she> crowned"]', '["v"]', 'to encircle (for attack or protection); especially to crown (literally or figuratively) compass, crown.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2861}/H9023/[H2859]', 'inflected', 'heb', 'חֲתֻנָּה', '["chăthunnâh"]', '["wedding/ his"]', '["n-f"]', 'a wedding espousal.', 'from 2859;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3820A}/H9023\/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["heart/ his"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1157}/[H5704]', 'inflected', 'heb', 'בְּעַד', '["bᵉʻad"]', '["from/ behind"]', '["prep"]', 'in up to or over against; generally at, beside, among, behind, for, etc. about, at by (means of), for, over, through, up (-on), within.', 'from 5704 with prepositional prefix;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H6777>/H9022', 'inflected', 'heb', 'לצמתך', '["le./tza.ma.Te/kh"]', '["to/ veil/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8181}/H9022/[H8175]', 'inflected', 'heb', 'שֵׂעָר', '["sêʻâr"]', '["hair/ your"]', '["n-m"]', 'hair (as if tossed or bristling) hair(-y), × rough.', 'or שַׂעַר; (Isaiah 7:20), from 8175 in the sense of dishevelling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H1570}/[H1570]', 'inflected', 'heb', 'גָּלַשׁ', '["gâlash"]', '["that/ <they> have descended","that/ they have descended"]', '["v"]', 'probably to caper (as a goat) appear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8127G}/H9022/[H8150]', 'inflected', 'heb', 'שֵׁן', '["shên"]', '["teeth/ your"]', '["n-f"]', 'a tooth (as sharp); specifically ivory; figuratively, a cliff crag, × forefront, ivory, × sharp, tooth.', 'from 8150; compare 8143');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7094}/[H7094]', 'inflected', 'heb', 'קָצַב', '["qâtsab"]', '["<the>/ shorn [ewes]"]', '["v"]', 'to clip, or (generally) chop cut down, shorn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H5927G}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["that/ <they> have come up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7367}/[H7366]', 'inflected', 'heb', 'רַחְצָה', '["rachtsâh"]', '["the/ washing"]', '["n-f"]', 'a bathing place washing.', 'feminine of 7366;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H3605}/H9028/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["that/ all of/ them"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8382}/[H8380]', 'lemma', 'heb', 'תָּאַם', '["tâʼam"]', '["[are] bearing twins"]', '["v"]', 'to be (causatively, make) twinned, i.e. (figuratively) duplicate or (architectural) jointed coupled (together), bear twins.', 'a primitive root; to be complete; but used only as denominative from 8380,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7909}/[H7921]', 'inflected', 'heb', 'שַׁכּוּל', '["shakkûwl"]', '["and/ [is one] deprived of offspring"]', '["a"]', 'bereaved barren, bereaved (robbed) of children (whelps).', 'or שַׁכֻּל; from 7921;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8193G}/H9022/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["lips/ your"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4057A}/H9022/[H1696]', 'inflected', 'heb', 'מִדְבָּר', '["midbâr"]', '["and/ mouth/ your"]', '["n-m"]', 'a pasture (i.e. open field, whither cattle are driven); by implication, a desert; also speech (including its organs) desert, south, speech, wilderness.', 'from 1696 in the sense of driving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7541}/H9022/[H7534]', 'inflected', 'heb', 'רַקָּה', '["raqqâh"]', '["temple/ your"]', '["n-f"]', 'properly, thinness, i.e. the side of the head temple.', 'feminine of 7534;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4026M}/[H1431]', 'inflected', 'heb', 'מִגְדָּל', '["migdâl"]', '["[are] like <the>/ towers","[is] like/ [the] tower of"]', '["n-m"]', 'a tower (from its size or height); by analogy, a rostrum; figuratively, a (pyramidal) bed of flowers castle, flower, tower. Compare the names following.', 'also (in plural) feminine מִגְדָּלָה; from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H8530>', 'inflected', 'heb', 'לתלפיות', '["le./tal.pi.Yot"]', '["to/ layers"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7699A}/H9022/[H7736]', 'inflected', 'heb', 'שַׁד', '["shad"]', '["breasts/ your"]', '["n-m"]', 'the breast of a woman or animal (as bulging) breast, pap, teat.', 'or שֹׁד; probably from 7736 (in its original sense) contracted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6082}/[H6080]', 'lemma', 'heb', 'עֹפֶר', '["ʻôpher"]', '["fawns"]', '["n-m"]', 'a fawn (from the dusty color) young roe (hart).', 'from 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6646}/[H6643]', 'lemma', 'heb', 'צְבִיָּה', '["tsᵉbîyâh"]', '["a gazelle"]', '["n-f"]', 'a female gazelle roe.', 'feminine of 6643;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3605}/H9022/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["all of/ you"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3971B>', 'inflected', 'heb', 'ומום', '["u./Mum"]', '["and/ [is] blemish"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3844G}/[H3825]', 'inflected', 'heb', 'לְבָנוֹן', '["Lᵉbânôwn"]', '["from/ Lebanon"]', '["n-pr-loc"]', 'Lebanon, a mountain range in Palestine Lebanon.', 'from 3825; (the) white mountain (from its snow);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3618G}/[H3634]', 'lemma', 'heb', 'כַּלָּה', '["kallâh"]', '["O bride","a bride","bride"]', '["n-f"]', 'a bride (as if perfect); hence, a son''s wife bride, daughter-in-law, spouse.', 'from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7788}/[H7788]', 'lemma', 'heb', 'שׁוּר', '["shûwr"]', '["you will come down"]', '["v"]', 'properly, to turn, i.e. travel about (as a harlot or a merchant) go, singular See also 7891.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0549G}/[H548]', 'lemma', 'heb', 'אֲמָנָה', '["ʼĂmânâh"]', '["Amana"]', '["n-pr-loc"]', 'Amanah, a mountain near Damascus Amana.', 'the same as 548;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4585}/[H4583]', 'inflected', 'heb', 'מְעוֹנָה', '["mᵉʻôwnâh"]', '["from/ [the] dens of"]', '["n-f"]', 'den, habitation, (dwelling) place, refuge.', 'or מְעֹנָה; feminine of 4583, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5246>', 'opaque', 'heb', 'נָמֵר', '["nâmêr"]', '["a leopard","leopards"]', '["n-m"]', 'a leopard (from its stripes) leopard.', 'from an unused root meaning properly, to filtrate, i.e. be limpid (comp 5247 and 5249); and thus to spot or stain as if by dripping;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3823A}/H9030/[H3823]', 'inflected', 'heb', 'לָבַב', '["lâbab"]', '["you have stolen heart/ my"]', '["v"]', 'properly, to be enclosed (as if with fat); by implication (as denominative from 3824); to unheart; i.e. (in a good sense) transport (with love), or (in a bad sense) stultify; to make cakes make cakes, ravish, be wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5869A}/H9022/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["from/ eyes/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6060B}/[H6059]', 'lemma', 'heb', 'עָנָק', '["ʻânâq"]', '["necklace"]', '["n-m"]', 'a necklace (as if strangling) chain.', 'from 6059;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6677B}/H9022/[H6696]', 'inflected', 'heb', 'צַוָּאר', '["tsavvâʼr"]', '["from/ necklaces/ your"]', '["n-m"]', 'the back of the neck (as that on which burdens are bound) neck.', 'or צַוָּר; (Nehemiah 3:5), or צַוָּרֹןlemma צַוָּרן missing vowel, corrected to צַוָּרֹן; (Song of Solomon 4:9), or (feminine) צַוָּארָה; (Micah 2:3), intensively from 6696 in the sense of binding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1730H>/H9022', 'opaque', 'heb', 'דּוֹד', '["dôwd"]', '["love<s>/ your"]', '["n-m"]', '(figuratively) to love; by implication, a love-token, lover, friend; specifically an uncle (well-) beloved, father''s brother, love, uncle.', 'or (shortened) דֹּד; from an unused root meaning properly, to boil, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7381}/[H7306]', 'inflected', 'heb', 'רֵיחַ', '["rêyach"]', '["and/ [the] odor of","and/ fragrance"]', '["n-m"]', 'odor (as if blown) savour, scent, smell.', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8081}/H9022/[H8080]', 'inflected', 'heb', 'שֶׁמֶן', '["shemen"]', '["oils/ your"]', '["n-m"]', 'grease, especially liquid (as from the olive, often perfumed); figuratively, richness anointing, × fat (things), × fruitful, oil(-ed), ointment, olive, pine.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3956G}/H9022/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["tongue/ your"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8008}/H9022/[H8071]', 'inflected', 'heb', 'שַׂלְמָה', '["salmâh"]', '["garments/ your"]', '["n-f"]', 'a dress clothes, garment, raiment.', 'transp. for 8071;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3844G}\/[H3825]', 'inflected', 'heb', 'לְבָנוֹן', '["Lᵉbânôwn"]', '["Lebanon"]', '["n-pr-loc"]', 'Lebanon, a mountain range in Palestine Lebanon.', 'from 3825; (the) white mountain (from its snow);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1530H}/[H1556]', 'lemma', 'heb', 'גַּל', '["gal"]', '["a spring","waves"]', '["n-m"]', 'something rolled, i.e. a heap of stone or dung (plural ruins), by analogy, a spring of water (plural waves) billow, heap, spring, wave.', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7973}/H9022/[H7971]', 'inflected', 'heb', 'שֶׁלַח', '["shelach"]', '["shoots/ your"]', '["n-m"]', 'a missile of attack, i.e. spear; also (figuratively) a shoot of growth; i.e. branch dart, plant, × put off, sword, weapon.', 'from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6508>', 'opaque', 'heb', 'פַּרְדֵּס', '["pardêç"]', '["[are] a garden of"]', '["n-m"]', 'a park forest, orchard.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4022>', 'opaque', 'heb', 'מֶגֶד', '["meged"]', '["choice things","choice<s>"]', '["n-m"]', 'properly, a distinguished thing; hence something valuable, as a product or fruit pleasant, precious fruit (thing).', 'from an unused root probably meaning to be eminent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3724C}/[H3722]', 'lemma', 'heb', 'כֹּפֶר', '["kôpher"]', '["henna plants"]', '["n-m"]', 'properly, a cover, i.e. (literally) a village (as covered in); (specifically) bitumen (as used for coating), and the henna plant (as used for dyeing); figuratively, a redemption-price bribe, camphire, pitch, ransom, satisfaction, sum of money, village.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5373>', 'opaque', 'heb', 'נֵרְדְּ', '["nêrd"]', '["nard","nard plants"]', '["n-m"]', 'nard, an aromatic spikenard.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3750>', 'inflected', 'heb', 'וכרכם', '["ve./khar.Kom"]', '["and/ saffron"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7070L}/[H7069]', 'lemma', 'heb', 'קָנֶה', '["qâneh"]', '["calamus"]', '["n-m"]', 'a reed (as erect); by resemblance a rod (especially for measuring), shaft, tube, stem, the radius (of the arm), beam (of a steelyard) balance, bone, branch, calamus, cane, reed, × spearman, stalk.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1588M}/H9020/[H1598]', 'inflected', 'heb', 'גַּן', '["gan"]', '["garden/ my"]', '["n"]', 'a garden (as fenced) garden.', 'from 1598;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1314}/H9023/[H1313]', 'inflected', 'heb', 'בֶּשֶׂם', '["besem"]', '["spices/ its"]', '["n-m"]', 'fragrance; by implication, spicery; also the balsam plant smell, spice, sweet (odour).', 'or בֹּשֶׂם; from the same as 1313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1588M}/H9023/[H1598]', 'inflected', 'heb', 'גַּן', '["gan"]', '["to/ garden/ his"]', '["n"]', 'a garden (as fenced) garden.', 'from 1598;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4022>/H9023', 'opaque', 'heb', 'מֶגֶד', '["meged"]', '["choice<s>/ its"]', '["n-m"]', 'properly, a distinguished thing; hence something valuable, as a product or fruit pleasant, precious fruit (thing).', 'from an unused root probably meaning to be eminent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1588M}/H9020/[H1598]', 'inflected', 'heb', 'גַּן', '["gan"]', '["to/ garden/ my"]', '["n"]', 'a garden (as fenced) garden.', 'from 1598;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0717}/[H717]', 'lemma', 'heb', 'אָרָה', '["ʼârâh"]', '["I have gathered"]', '["v"]', 'to pluck gather, pluck.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4753}/H9020/[H4843]', 'inflected', 'heb', 'מֹר', '["môr"]', '["myrrh/ my"]', '["n-m"]', 'myrrh (as distilling in drops, and also as bitter) myrrh.', 'or מוֹר; from 4843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1313>/H9020', 'opaque', 'heb', 'בָּשָׂם', '["bâsâm"]', '["spice/ my"]', '["n-m"]', 'the balsam plant spice.', 'from an unused root meaning to be fragrant; (compare 5561)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3293B>/H9020', 'opaque', 'heb', 'יַעַר', '["yaʻar"]', '["honeycomb/ my"]', '["n-m"]', 'a copse of bushes; hence, a forest; hence, honey in the comb (as hived in trees) (honey-) comb, forest, wood.', 'from an unused root probably meaning to thicken with verdure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1706>/H9020', 'opaque', 'heb', 'דְּבַשׁ', '["dᵉbash"]', '["honey/ my"]', '["n-m"]', 'honey (from its stickiness); by analogy, syrup honey(-comb).', 'from an unused root meaning to be gummy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3196>/H9020', 'opaque', 'heb', 'יַיִן', '["yayin"]', '["wine/ my"]', '["n-m"]', 'wine (as fermented); by implication, intoxication banqueting, wine, wine(-bibber).', 'from an unused root meaning to effervesce;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2461}/H9020/[H2459]', 'inflected', 'heb', 'חָלָב', '["châlâb"]', '["milk/ my"]', '["n-m"]', 'milk (as the richness of kine) cheese, milk, sucking.', 'from the same as 2459;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7937}/[H7937]', 'inflected', 'heb', 'שָׁכַר', '["shâkar"]', '["and/ O drunken [one]","and/ become drunk"]', '["v"]', 'to become tipsy; in a qualified sense, to satiate with a stimulating drink or (figuratively) influence (be filled with) drink (abundantly), (be, make) drunk(-en), be merry. (Superlative of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1730H>\', 'opaque', 'heb', 'דּוֹד', '["dôwd"]', '["O lovers"]', '["n-m"]', '(figuratively) to love; by implication, a love-token, lover, friend; specifically an uncle (well-) beloved, father''s brother, love, uncle.', 'or (shortened) דֹּד; from an unused root meaning properly, to boil, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8535}/H9020/[H8552]', 'inflected', 'heb', 'תָּם', '["tâm"]', '["perfect [one]/ my"]', '["a"]', 'complete; usually (morally) pious; specifically, gentle, dear coupled together, perfect, plain, undefiled, upright.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/<H7218A>/H9020', 'inflected', 'heb', 'שראשי', '["she./ro.Sh/i"]', '["that/ head/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6977}/H9020/[H6972]', 'inflected', 'heb', 'קְוֻצָּה', '["qᵉvutstsâh"]', '["locks/ my"]', '["n-f"]', 'a forelock (as shorn) lock.', 'feminine passive participle of 6972 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7447A}/[H7450]', 'lemma', 'heb', 'רָסִיס', '["râçîyç"]', '["dewdrops of"]', '["n-m"]', 'properly, dripping to pieces, i.e. a ruin; also a dew-drop breach, drop.', 'from 7450;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3847}/H9034/[H3847]', 'inflected', 'heb', 'לָבַשׁ', '["lâbash"]', '["will I put on/ it"]', '["v"]', 'properly, wrap around, i.e. (by implication) to put on a garment or clothe (oneself, or another), literally or figuratively (in) apparel, arm, array (self), clothe (self), come upon, put (on, upon), wear.', 'or לָבֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2936}/H9038/[H2936]', 'inflected', 'heb', 'טָנַף', '["ṭânaph"]', '["will I dirty/ them"]', '["v"]', 'to soil defile.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4578>/H9020', 'inflected', 'heb', 'ומעי', '["u./me.''A/i"]', '["and/ inward parts/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H1730G>/H9020', 'inflected', 'heb', 'לדודי', '["le./do.D/i"]', '["[belong] to/ lover/ my","for/ lover/ my","to/ lover/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0676}/H9020/[H6648]', 'inflected', 'heb', 'אֶצְבַּע', '["ʼetsbaʻ"]', '["and/ fingers/ my"]', '["n-f"]', 'something to sieze with, i.e. a finger; by analogy, a toe finger, toe.', 'from the same as 6648 (in the sense of grasping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4514}/[H5274]', 'inflected', 'heb', 'מַנְעוּל', '["manʻûwl"]', '["the/ bolt"]', '["n-m"]', 'a bolt lock.', 'or מַנְעֻל; from 5274;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1730G>/H9020', 'inflected', 'heb', 'ודודי', '["ve./do.D/i"]', '["and/ lover/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2559}/[H2559]', 'lemma', 'heb', 'חָמַק', '["châmaq"]', '["he had turned away"]', '["v"]', 'properly, to wrap; hence, to depart (i.e. turn about) go about, withdraw self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3318P}/[H3318]', 'lemma', 'heb', 'יָצָא', '["yâtsâʼ"]', '["certainly [if] <to go out>","it went out","you will go out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6481}/H9030/[H6481]', 'inflected', 'heb', 'פָּצַע', '["pâtsaʻ"]', '["they bruised/ me"]', '["v"]', 'to split, i.e. wound wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7289}/H9020/[H7286]', 'inflected', 'heb', 'רָדִיד', '["râdîyd"]', '["garment/ my"]', '["n-m"]', 'a veil (as expanded) vail, veil.', 'from 7286 in the sense of spreading;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H2470H}/[H2342]', 'inflected', 'heb', 'חָלָה', '["châlâh"]', '["that/ [am] weak of"]', '["v"]', 'properly, to be rubbed or worn; hence (figuratively) to be weak, sick, afflicted; or (causatively) to grieve, make sick; also to stroke (in flattering), entreat beseech, (be) diseased, (put to) grief, be grieved, (be) grievous, infirmity, intreat, lay to, put to pain, × pray, make prayer, be (fall, make) sick, sore, be sorry, make suit (× supplication), woman in travail, be (become) weak, be wounded.', 'a primitive root (compare 2342, 2470, 2490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1730G>/H9022', 'opaque', 'heb', 'דּוֹד', '["dôwd"]', '["[is] lover/ your","lover/ your"]', '["n-m"]', '(figuratively) to love; by implication, a love-token, lover, friend; specifically an uncle (well-) beloved, father''s brother, love, uncle.', 'or (shortened) דֹּד; from an unused root meaning properly, to boil, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H1730G>', 'inflected', 'heb', 'מדוד', '["mi./Dod"]', '["more than/ a lover"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6703}/[H6705]', 'lemma', 'heb', 'צַח', '["tsach"]', '["[is] dazzling","clearly","dazzling","scorching"]', '["a"]', 'dazzling, i.e. sunny, bright, (figuratively) evident clear, dry, plainly, white.', 'from 6705;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0122A}/[H119]', 'inflected', 'heb', 'אָדֹם', '["ʼâdôm"]', '["and/ ruddy"]', '["a n-m"]', 'rosy red, ruddy.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1713A}/[H1713]', 'lemma', 'heb', 'דָּגַל', '["dâgal"]', '["[is] conspicuous"]', '["v"]', 'to flaunt, i.e. raise a flag; figuratively, to be conspicuous (set up, with) banners, chiefest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6977}/H9023/[H6972]', 'inflected', 'heb', 'קְוֻצָּה', '["qᵉvutstsâh"]', '["locks/ his"]', '["n-f"]', 'a forelock (as shorn) lock.', 'feminine passive participle of 6972 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8534}/[H8524]', 'lemma', 'heb', 'תַּלְתַּל', '["taltal"]', '["[are] curls"]', '["n-f"]', 'a trailing bough (as pendulous) bushy.', 'by reduplication, from 8524 through the idea of vibration;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6158}/[H6150]', 'inflected', 'heb', 'עֹרֵב', '["ʻôrêb"]', '["like <the>/ raven"]', '["n-m"]', 'a raven (from its dusky hue) raven.', 'or עוֹרֵב; from 6150;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4402}/[H4390]', 'lemma', 'heb', 'מִלֵּאת', '["millêʼth"]', '["fullness"]', '["n-f"]', 'fulness, i.e. (concretely) a plump socket (of the eye) × fitly.', 'from 4390;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6170}/[H6165]', 'inflected', 'heb', 'עֲרוּגָה', '["ʻărûwgâh"]', '["[are] like/ [the] bed of"]', '["n-f"]', 'something piled up (as if (figuratively) raised by mental aspiration), i.e. a paterre bed, furrow.', 'or עֲרֻגָה; feminine passive participle of 6165;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4840}/[H7543]', 'lemma', 'heb', 'מֶרְקָח', '["merqâch"]', '["aromatic herbs"]', '["n-m"]', 'a spicy herb × sweet.', 'from 7543;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8658}/[H8659]', 'inflected', 'heb', 'תַּרְשִׁישׁ', '["tarshîysh"]', '["with <the>/ chrysolite"]', '["n-m"]', 'a gem, perhaps the topaz beryl.', 'probably of foreign derivation (compare 8659);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6247}/[H6245]', 'lemma', 'heb', 'עֶשֶׁת', '["ʻesheth"]', '["[are] a plate of"]', '["n-m"]', 'a fabric bright.', 'from 6245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5968}/[H5968]', 'lemma', 'heb', 'עָלַף', '["ʻâlaph"]', '["covered","they have become faint","they will become faint"]', '["v"]', 'to veil or cover; figuratively, to be languid faint, overlaid, wrap self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7785}/H9023/[H7783]', 'inflected', 'heb', 'שׁוֹק', '["shôwq"]', '["legs/ his"]', '["n-f"]', 'the (lower) leg (as a runner) hip, leg, shoulder, thigh.', 'from 7783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1245}/H9033/[H1245]', 'inflected', 'heb', 'בָּקַשׁ', '["bâqash"]', '["so/ we may seek/ him"]', '["v"]', 'to search out (by any method, specifically in worship or prayer); by implication, to strive after ask, beg, beseech, desire, enquire, get, make inquisition, procure, (make) request, require, seek (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6170}/[H6165]', 'inflected', 'heb', 'עֲרוּגָה', '["ʻărûwgâh"]', '["to/ [the] beds of"]', '["n-f"]', 'something piled up (as if (figuratively) raised by mental aspiration), i.e. a paterre bed, furrow.', 'or עֲרֻגָה; feminine passive participle of 6165;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3950}/[H3950]', 'inflected', 'heb', 'לָקַט', '["lâqaṭ"]', '["and/ to/ gather"]', '["v"]', 'properly, to pick up, i.e. (generally) to gather; specifically, to glean gather (up), glean.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7799}\/[H7797]', 'inflected', 'heb', 'שׁוּשַׁן', '["shûwshan"]', '["among the/ lilies"]', '["n-m"]', 'a lily (from its whiteness), as a flower of architectural ornament; also a (straight) trumpet (from the tubular shape) lily, Shoshannim.', 'or שׁוֹשָׁן; or שֹׁשָׁן; and (feminine) שׁוֹשַׁנָּה; from 7797;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8656H}/[H7521]', 'inflected', 'heb', 'תִּרְצָה', '["Tirtsâh"]', '["like/ Tirzah"]', '["n-pr-f"]', 'Tirtsah, a place in Palestine; also an Israelitess Tirzah.', 'from 7521; delightsomeness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3389}/[H3390]', 'inflected', 'heb', 'יְרוּשָׁלִַ͏ם', '["Yᵉrûwshâlaim"]', '["like/ Jerusalem"]', '["n-pr-loc"]', 'Jerushalaim or Jerushalem, the capital city of Palestine Jerusalem.', 'rarely יְרוּשָׁלַיִם; a dual (in allusion to its two main hills (the true pointing, at least of the former reading, seems to be that of 3390)); probably from (the passive participle of) 3384 and 7999; founded peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0366>', 'opaque', 'heb', 'אָיֹם', '["ʼâyôm"]', '["[is] terrifying","majestic"]', '["a"]', 'frightful terrible.', 'from an unused root (meaning to frighten);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1713B}/[H1713]', 'inflected', 'heb', 'דָּגַל', '["dâgal"]', '["like <the>/ hosts with banners"]', '["v"]', 'to flaunt, i.e. raise a flag; figuratively, to be conspicuous (set up, with) banners, chiefest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5437J}/[H5437]', 'lemma', 'heb', 'סָבַב', '["çâbab"]', '["[am] about to turn round","turn"]', '["v"]', 'to revolve, surround, or border; used in various applications, literally and figuratively bring, cast, fetch, lead, make, walk, × whirl, × round about, be about on every side, apply, avoid, beset (about), besiege, bring again, carry (about), change, cause to come about, × circuit, (fetch a) compass (about, round), drive, environ, × on every side, beset (close, come, compass, go, stand) round about, inclose, remove, return, set, sit down, turn (self) (about, aside, away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5048}/H9030/[H5046]', 'inflected', 'heb', 'נֶגֶד', '["neged"]', '["from/ before/ me"]', '["prep"]', 'a front, i.e. part opposite; specifically a counterpart, or mate; usually (adverbial, especially with preposition) over against or before about, (over) against, × aloof, × far (off), × from, over, presence, × other side, sight, × to view.', 'from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H7353>', 'inflected', 'heb', 'הרחלים', '["ha./re.che.Lim"]', '["<the>/ ewes"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4436H}/[H4428]', 'lemma', 'heb', 'מַלְכָּה', '["malkâh"]', '["queens"]', '["n-f"]', 'a queen queen.', 'feminine of 4428;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5959}/[H5958]', 'inflected', 'heb', 'עַלְמָה', '["ʻalmâh"]', '["and/ young women"]', '["n-f"]', 'a lass (as veiled or private) damsel, maid, virgin.', 'feminine of 5958;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0517}/H9024/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["of/ mother/ her"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3205}/H9034/[H3205]', 'inflected', 'heb', 'יָלַד', '["yâlad"]', '["of/ [the] [one who] bore/ her"]', '["v"]', 'to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1984B}/H9034\/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["and/ they praised/ her"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3842}/[H3835]', 'inflected', 'heb', 'לְבָנָה', '["lᵉbânâh"]', '["like the/ full moon"]', '["n-f"]', 'properly, (the) white, i.e. the moon moon. See also 3838.', 'from 3835;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2535}/[H2525]', 'inflected', 'heb', 'חַמָּה', '["chammâh"]', '["like the/ sun"]', '["n-f"]', 'heat; by implication, the sun heat, sun.', 'from 2525;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1713B}\/[H1713]', 'inflected', 'heb', 'דָּגַל', '["dâgal"]', '["like <the>/ hosts with banners"]', '["v"]', 'to flaunt, i.e. raise a flag; figuratively, to be conspicuous (set up, with) banners, chiefest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0093}/[H93]', 'lemma', 'heb', 'אֱגוֹז', '["ʼĕgôwz"]', '["nut[s]"]', '["n-m"]', 'a nut nut.', 'prob of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0003}/[H24]', 'inflected', 'heb', 'אֵב', '["ʼêb"]', '["on/ [the] green shoots of"]', '["n-m"]', 'a green plant greenness, fruit.', 'from the same as 24;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H6524A}/[H6524]', 'inflected', 'heb', 'פָּרַח', '["pârach"]', '["¿/ had it budded"]', '["v"]', 'to break forth as a bud, i.e. bloom; generally, to spread; specifically, to fly (as extending the wings); figuratively, to flourish × abroad, × abundantly, blossom, break forth (out), bud, flourish, make fly, grow, spread, spring (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5132B}/[H5132]', 'lemma', 'heb', 'נוּץ', '["nûwts"]', '["had they bloomed?","they have bloomed"]', '["v"]', 'properly, to flash; also, to fly away (from the quickness of motion) flee away, bud (forth).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5971A}/H9014/{H5081H}/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["people of/-/prince"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7759}/[H7999]', 'inflected', 'heb', 'שׁוּלַמִּית', '["Shûwlammîyth"]', '["O/ Shulammite [woman]"]', '["a"]', 'peaceful (with the article always prefixed, making it a pet name); the Shulammith, an epithet of Solomon''s queen Shulamite.', 'from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2372}/[H2372]', 'inflected', 'heb', 'חָזָה', '["châzâh"]', '["and/ let it look","so/ we may look"]', '["v"]', 'to gaze at; mentally to perceive, contemplate (with pleasure); specifically, to have a vision of behold, look, prophesy, provide, see.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7759}/[H7999]', 'inflected', 'heb', 'שׁוּלַמִּית', '["Shûwlammîyth"]', '["on the/ Shulammite [woman]"]', '["a"]', 'peaceful (with the article always prefixed, making it a pet name); the Shulammith, an epithet of Solomon''s queen Shulamite.', 'from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4246}/[H4234]', 'inflected', 'heb', 'מְחֹלָה', '["mᵉchôlâh"]', '["like/ [the] dance of"]', '["n-f"]', 'a dance company, dances(-cing).', 'feminine of 4234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6471}/H9022/[H6470]', 'inflected', 'heb', 'פַּעַם', '["paʻam"]', '["feet/ your"]', '["n-f"]', 'a stroke, literally or figuratively (in various applications, as follow) anvil, corner, foot(-step), going, (hundred-) fold, × now, (this) once, order, rank, step, thrice, (often-), second, this, two) time(-s), twice, wheel.', 'or (feminine) פַּעֲמָה; from 6470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5275}/[H5274]', 'inflected', 'heb', 'נַעַל', '["naʻal"]', '["in <the>/ sandals"]', '["n-f"]', 'properly, a sandal tongue; by extension a sandal or slipper (sometimes as a symbol of occupancy, a refusal to marry, or of something valueless) dryshod, (pair of) shoe((-latchet), -s).', 'or (feminine) נַעֲלָה; from 5274;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2542}/[H2559]', 'lemma', 'heb', 'חַמּוּק', '["chammûwq"]', '["[the] curves of"]', '["n-m"]', 'a wrapping, i.e. drawers joints.', 'from 2559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2481}/[H2470]', 'lemma', 'heb', 'חֲלִי', '["chălîy"]', '["jewels"]', '["n-m"]', 'a trinket (as polished) jewel, ornament.', 'from 2470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0542}/[H539]', 'lemma', 'heb', 'אָמָן', '["ʼâmân"]', '["a master-craftsman"]', '["n-m"]', 'an expert cunning workman.', 'from 539 (in the sense of training);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8326}/H9022/[H8324]', 'inflected', 'heb', 'שֹׁרֶר', '["shôrer"]', '["navel/ your"]', '["n-m"]', 'the umbilical cord, i.e. (by extension) a bodice navel.', 'from 8324 in the sense of twisting (compare 8270);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0101}/[H5059]', 'lemma', 'heb', 'אַגָּן', '["ʼaggân"]', '["[is] [the] bowl of"]', '["n-m"]', 'a bowl (as pounded out hollow) basin, cup, goblet.', 'probably from 5059;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5469>', 'inflected', 'heb', 'הסהר', '["ha./Sa.har"]', '["<the>/ roundness"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H4197>', 'inflected', 'heb', 'המזג', '["ha./Ma.zeg"]', '["<the>/ mixed wine"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0990G>/H9022', 'opaque', 'heb', 'בֶּטֶן', '["beṭen"]', '["belly/ your"]', '["n-f"]', 'the belly, especially the womb; also the bosom or body of anything belly, body, as they be born, within, womb.', 'from an unused root probably meaning to be hollow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5473}/[H5472]', 'lemma', 'heb', 'סוּג', '["çûwg"]', '["fenced around"]', '["v"]', 'to hem in, i.e. bind set about.', 'a primitive root (probably rather identical with 5472 through the idea of shrinking from a hedge; compare 7735);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1337}/[H1323]', 'lemma', 'heb', 'בַּת רַבִּים', '["Bath Rabbîym"]', '["Bath-","Rabbim"]', '["n-pr-loc"]', 'the daughter (i.e. city) of Rabbah Bath-rabbim.', 'from 1323 and a masculine plural from 7227;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0639H}/H9022/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["nose/ your"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218A>/H9022', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["head/ your"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3760G}/[H3759]', 'inflected', 'heb', 'כַּרְמֶל', '["Karmel"]', '["[is] like <the>/ Carmel"]', '["n-pr-loc"]', 'Karmel, the name of a hill and of a town in Palestine Carmel, fruitful (plentiful) field, (place).', 'the same as 3759;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1803A}/[H1802]', 'inflected', 'heb', 'דַּלָּה', '["dallâh"]', '["and/ [the] hair of"]', '["n-f"]', 'properly, something dangling, i.e. a loose thread or hair; figuratively, indigent hair, pining sickness, poor(-est sort).', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H0713>', 'inflected', 'heb', 'כארגמן', '["ka./''ar.ga.Man"]', '["[is] like <the>/ purple wool"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7298B>', 'inflected', 'heb', 'ברהטים', '["ba./re.ha.Tim"]', '["by the/ tresses"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8588}/[H6026]', 'inflected', 'heb', 'תַּעֲנוּג', '["taʻănûwg"]', '["with <the>/ delights"]', '["n-m"]', 'luxury delicate, delight, pleasant.', 'or תַּעֲנֻג; and (feminine) תַּעֲנֻגָה; from 6026;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6967}/H9022/[H6965]', 'inflected', 'heb', 'קוֹמָה', '["qôwmâh"]', '["stature/ your"]', '["n-f"]', 'height × along, height, high, stature, tall.', 'from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H8558>', 'inflected', 'heb', 'לתמר', '["le./ta.Mar"]', '["<to>/ a palm tree"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7699A}/H9022/[H7736]', 'inflected', 'heb', 'שַׁד', '["shad"]', '["and/ breasts/ your"]', '["n-m"]', 'the breast of a woman or animal (as bulging) breast, pap, teat.', 'or שֹׁד; probably from 7736 (in its original sense) contracted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0811}/[H810]', 'inflected', 'heb', 'אֶשְׁכּוֹל', '["ʼeshkôwl"]', '["<to>/ clusters"]', '["n-m"]', 'a bunch of grapes or other fruit cluster (of grapes).', 'or אֶשְׁכֹּל; probably prolonged from 810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H8558>', 'inflected', 'heb', 'בתמר', '["ve./ta.Mar"]', '["on/ [the] palm tree"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H5577>/H9023', 'inflected', 'heb', 'בסנסניו', '["be./san.si.Na/v"]', '["on/ fruit-stalks/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0811}/[H810]', 'inflected', 'heb', 'אֶשְׁכּוֹל', '["ʼeshkôwl"]', '["like/ [the] clusters of"]', '["n-m"]', 'a bunch of grapes or other fruit cluster (of grapes).', 'or אֶשְׁכֹּל; probably prolonged from 810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2441}/H9022/[H2596]', 'inflected', 'heb', 'חֵךְ', '["chêk"]', '["and/ mouth/ your"]', '["n-m"]', 'properly, the palate or inside of the mouth; hence, the mouth itself (as the organ of speech, taste and kissing) (roof of the) mouth, taste.', 'probably from 2596 in the sense of tasting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4339}/[H3474]', 'inflected', 'heb', 'מֵישָׁר', '["mêyshâr"]', '["to/ smoothness<es>"]', '["n-m"]', 'evenness, i.e. (figuratively) prosperity or concord; also straightness, i.e. (figuratively) rectitude (only in plural with singular sense; often adverbially) agreement, aright, that are equal, equity, (things that are) right(-eously, things), sweetly, upright(-ly, -ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1680}/[H1679]', 'lemma', 'heb', 'דָּבַב', '["dâbab"]', '["[which] flows gently"]', '["v"]', 'to move slowly, i.e. glide cause to speak.', 'a primitive root (compare 1679);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8669}/H9023\/[H7783]', 'inflected', 'heb', 'תְּשׁוּקָה', '["tᵉshûwqâh"]', '["desire/ his"]', '["n-f"]', 'a longing desire.', 'from 7783 in the original sense of stretching out after;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3723H}/[H3722]', 'inflected', 'heb', 'כָּפָר', '["kâphâr"]', '["in the/ villages"]', '["n-m"]', 'a village (as protected by walls) village. Compare 3715.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3754>', 'inflected', 'heb', 'לכרמים', '["la./ke.ra.Mim"]', '["to the/ vineyards"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5563>', 'inflected', 'heb', 'הסמדר', '["ha./se.ma.Dar"]', '["the/ blossom"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1730H>/H9020', 'opaque', 'heb', 'דּוֹד', '["dôwd"]', '["beloved/ my","love<s>/ my"]', '["n-m"]', '(figuratively) to love; by implication, a love-token, lover, friend; specifically an uncle (well-) beloved, father''s brother, love, uncle.', 'or (shortened) דֹּד; from an unused root meaning properly, to boil, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1736}/[H1731]', 'inflected', 'heb', 'דּוּדַי', '["dûwday"]', '["the/ mandrakes"]', '["n-m"]', 'a boiler or basket; also the mandrake (as an aphrodisiac) basket, mandrake.', 'from 1731;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6607}/H9025/[H6605]', 'inflected', 'heb', 'פֶּתַח', '["pethach"]', '["doorway<s>/ our"]', '["n-m"]', 'an opening (literally), i.e. door (gate) or entrance way door, entering (in), entrance (-ry), gate, opening, place.', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414H}/H9031/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["I appointed/ you","will he give/ you"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5401A}/H9031/[H5400]', 'inflected', 'heb', 'נָשַׁק', '["nâshaq"]', '["I will kiss/ you"]', '["v"]', 'to kiss, literally or figuratively (touch); also (as a mode of attachment), to equip with weapons armed (men), rule, kiss, that touched.', 'a primitive root (identical with 5400, through the idea of fastening up; compare 2388, 2836);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8248H}/H9031/[H8248]', 'inflected', 'heb', 'שָׁקָה', '["shâqâh"]', '["I will give to drink/ you"]', '["v"]', 'to quaff, i.e. (causatively) to irrigate or furnish a potion to cause to (give, give to, let, make to) drink, drown, moisten, water. See 7937, 8354.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7544}/[H7543]', 'inflected', 'heb', 'רֶקַח', '["reqach"]', '["<the>/ spice"]', '["n-m"]', 'properly, perfumery, i.e. (by implication) spicery (for flavor) spiced.', 'from 7543;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6071}/[H6072]', 'inflected', 'heb', 'עָסִיס', '["ʻâçîyç"]', '["some of/ [the] juice of"]', '["n-m"]', 'must or fresh grape-juice (as just trodden out) juice, new (sweet) wine.', 'from 6072;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7416}/H9020/[H7426]', 'inflected', 'heb', 'רִמּוֹן', '["rimmôwn"]', '["pomegranate/ my"]', '["n-m"]', 'a pomegranate, the tree (from its upright growth) or the fruit (also an artificial ornament) pomegranate.', 'or רִמֹּן; from 7426;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7514}/[H7514]', 'lemma', 'heb', 'רָפַק', '["râphaq"]', '["leaning herself"]', '["v"]', 'to recline lean.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1730G>/H9024', 'opaque', 'heb', 'דּוֹד', '["dôwd"]', '["lover/ her"]', '["n-m"]', '(figuratively) to love; by implication, a love-token, lover, friend; specifically an uncle (well-) beloved, father''s brother, love, uncle.', 'or (shortened) דֹּד; from an unused root meaning properly, to boil, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8598}/[H5301]', 'inflected', 'heb', 'תַּפּוּחַ', '["tappûwach"]', '["the/ apple tree"]', '["n-m"]', 'an apple (from its fragrance), i.e. the fruit or the tree (probably includ. others of the pome order, as the quince, the orange, etc.) apple (tree). See also 1054.', 'from 5301;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5782}/H9031/[H5782]', 'inflected', 'heb', 'עוּר', '["ʻûwr"]', '["I aroused/ you"]', '["v"]', 'to wake (literally or figuratively) (a-) wake(-n, up), lift up (self), × master, raise (up), stir up (self).', 'a primitive root (rather identical with through the idea of opening the eyes);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2254C}/H9031/[H2254]', 'inflected', 'heb', 'חָבַל', '["châbal"]', '["she was in labor with/ you"]', '["v"]', 'to wind tightly (as a rope), i.e. to bind; specifically, by a pledge; figuratively, to pervert, destroy; also to writhe in pain (especially of parturition) × at all, band, bring forth, (deal) corrupt(-ly), destroy, offend, lay to (take a) pledge, spoil, travail, × very, withhold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2368}/[H2856]', 'inflected', 'heb', 'חוֹתָם', '["chôwthâm"]', '["like <the>/ seal","like <the>/ signet-ring"]', '["n-m"]', 'a signature-ring seal, signet.', 'or חֹתָם; from 2856;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7565}/H9024/[H8313]', 'inflected', 'heb', 'רֶשֶׁף', '["resheph"]', '["flashes/ its"]', '["n-m"]', 'a live coal; by analogy lightning; figuratively, an arrow, (as flashing through the air); specifically, fever arrow, (burning) coal, burning heat, spark, hot thunderbolt.', 'from 8313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7957}/{H3050}/[H3851]', 'inflected', 'heb', 'שַׁלְהֶבֶת', '["shalhebeth"]', '["a flame of/ [the] Lord"]', '["n-f"]', 'a flare of fire (flaming) flame.', 'from the same as 3851 with sibilant prefix;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3518}/[H3518]', 'inflected', 'heb', 'כָּבָה', '["kâbâh"]', '["to/ extinguish"]', '["v"]', 'to expire or (causatively) to extinguish (fire, light, anger) go (put) out, quench.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7857}/H9034/[H7857]', 'inflected', 'heb', 'שָׁטַף', '["shâṭaph"]', '["they will overflow/ it"]', '["v"]', 'to gush; by implication, to inundate, cleanse; by analogy, to gallop, conquer drown, (over-) flow(-whelm, rinse, run, rush, (throughly) wash (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7699A}/[H7736]', 'inflected', 'heb', 'שַׁד', '["shad"]', '["and/ breasts"]', '["n-m"]', 'the breast of a woman or animal (as bulging) breast, pap, teat.', 'or שֹׁד; probably from 7736 (in its original sense) contracted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0269}/H9025/[H251]', 'inflected', 'heb', 'אָחוֹת', '["ʼâchôwth"]', '["for/ sister/ our"]', '["n-f"]', 'a sister (used very widely [like 251number 250, corrected to 251], literally and figuratively) (an-) other, sister, together.', 'irregular feminine of 251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H1696G}/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["when/ it will be spoken"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2918}/[H2905]', 'lemma', 'heb', 'טִירָה', '["ṭîyrâh"]', '["a battlement of"]', '["n-f"]', 'a wall; hence, a fortress or a hamlet (goodly) castle, habitation, palace, row.', 'feminine of (an equivalent to) 2905;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7699A}/H9020/[H7736]', 'inflected', 'heb', 'שַׁד', '["shad"]', '["and/ breasts/ my"]', '["n-m"]', 'the breast of a woman or animal (as bulging) breast, pap, teat.', 'or שֹׁד; probably from 7736 (in its original sense) contracted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1174}/[H1167]', 'inflected', 'heb', 'בַּעַל הָמוֹן', '["Baʻal Hâmôwn"]', '["at/ Baal-"]', '["n-pr-loc"]', 'Baal-Hamon, a place in Palestine Baal-hamon.', 'from 1167 and 1995; possessor of a multitude;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1174}/[H1167]', 'lemma', 'heb', 'בַּעַל הָמוֹן', '["Baʻal Hâmôwn"]', '["Hamon"]', '["n-pr-loc"]', 'Baal-Hamon, a place in Palestine Baal-hamon.', 'from 1167 and 1995; possessor of a multitude;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5201}/[H5201]', 'inflected', 'heb', 'נָטַר', '["nâṭar"]', '["[belong] to/ [those who] keep","to <the>/ [those who] keep"]', '["v"]', 'to guard; figuratively, to cherish (anger) bear grudge, keep(-er), reserve.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6529}/H9023/[H6509]', 'inflected', 'heb', 'פְּרִי', '["pᵉrîy"]', '["for/ fruit/ its"]', '["n-m"]', 'fruit (literally or figuratively) bough, (first-)fruit(-ful), reward.', 'from 6509;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H6963A>/H9022', 'inflected', 'heb', 'לקולך', '["le./ko.Le/kh"]', '["for/ voice/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1819}/[H1819]', 'inflected', 'heb', 'דָּמָה', '["dâmâh"]', '["and/ be like","and/ we may be alike"]', '["v"]', 'to compare; by implication, to resemble, liken, consider compare, devise, (be) like(-n), mean, think, use similitudes.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0238}/[H241]', 'inflected', 'heb', 'אָזַן', '["ʼâzan"]', '["and/ give ear"]', '["v"]', 'to broaden out the ear (with the hand), i.e. (by implication) to listen give (perceive by the) ear, hear(-ken). See 239.', 'a primitive root; probably to expand; but used only as a denominative from 241;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1742}/[H1739]', 'lemma', 'heb', 'דַּוָּי', '["davvây"]', '["[is] faint"]', '["a"]', 'sick; figuratively, troubled faint.', 'from 1739;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2250}/[H2266]', 'inflected', 'heb', 'חַבּוּרָה', '["chabbûwrâh"]', '["and/ welt[s]"]', '["n-f"]', 'properly, bound (with stripes), i.e. a weal (or black-and-blue mark itself) blueness, bruise, hurt, stripe, wound.', 'or חַבֻּרָה; or חֲבֻרָה; from 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2115}/[H6695]', 'lemma', 'heb', 'זוּר', '["zûwr"]', '["they have been pressed out"]', '["v"]', 'to press together, tighten close, rush, thrust together.', 'a primitive root (compare 6695);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5048}/H9036/[H5046]', 'inflected', 'heb', 'נֶגֶד', '["neged"]', '["to/ before/ you"]', '["prep"]', 'a front, i.e. part opposite; specifically a counterpart, or mate; usually (adverbial, especially with preposition) over against or before about, (over) against, × aloof, × far (off), × from, over, presence, × other side, sight, × to view.', 'from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8077A}/[H8076]', 'inflected', 'heb', 'שְׁמָמָה', '["shᵉmâmâh"]', '["and/ a desolation","and/ a waste","and/ desolation"]', '["n-f"]', 'devastation; figuratively, astonishment (laid, × most) desolate(-ion), waste.', 'or שִׁמָמָה; feminine of 8076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5521}/[H5520]', 'inflected', 'heb', 'סֻכָּה', '["çukkâh"]', '["like/ a shelter"]', '["n-f"]', 'a hut or lair booth, cottage, covert, pavilion, tabernacle, tent.', 'feminine of 5520;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4412}/[H3885]', 'inflected', 'heb', 'מְלוּנָה', '["mᵉlûwnâh"]', '["like <the>/ hut","like/ a watchman''s hut"]', '["n-f"]', 'a hut, a hammock cottage, lodge.', 'feminine from 3885;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4750}/[H7180]', 'inflected', 'heb', 'מִקְשָׁה', '["miqshâh"]', '["in/ a cucumber field"]', '["n-f"]', 'literally a cucumbered field, i.e. a cucumber patch garden of cucumbers.', 'denominative from 7180;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H5467>', 'inflected', 'heb', 'כסדם', '["ki/s.Dom"]', '["like/ Sodom"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6017}/[H6014]', 'inflected', 'heb', 'עֲמֹרָה', '["ʻĂmôrâh"]', '["<to>/ Gomorrah"]', '["n-pr-loc"]', 'Amorah, a place in Palestine Gomorrah.', 'from 6014; a (ruined) heap;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1819}\/[H1819]', 'inflected', 'heb', 'דָּמָה', '["dâmâh"]', '["we were like"]', '["v"]', 'to compare; by implication, to resemble, liken, consider compare, devise, (be) like(-n), mean, think, use similitudes.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4806}/[H4754]', 'lemma', 'heb', 'מְרִיא', '["mᵉrîyʼ"]', '["fatlings","fatlings of"]', '["n-m"]', 'stall-fed; often (as noun) a beeve fat (fed) beast (cattle, -ling).', 'from 4754 in the sense of grossness, through the idea of domineering (compare 4756);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3027I}/H9026/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["from/ hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2691A}/H9020/[H2690]', 'inflected', 'heb', 'חָצֵר', '["châtsêr"]', '["courts/ my"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7676}/[H7673]', 'inflected', 'heb', 'שַׁבָּת', '["shabbâth"]', '["and/ sabbath"]', '["n"]', 'intermission, i.e (specifically) the Sabbath ( every) sabbath.', 'intensive from 7673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6116}/[H6113]', 'inflected', 'heb', 'עֲצָרָה', '["ʻătsârâh"]', '["and/ solemn assembli[es]"]', '["n-f"]', 'an assembly, especially on a festival or holiday (solemn) assembly (meeting).', 'or עֲצֶרֶת; from 6113;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2320H}/H9026/[H2318]', 'inflected', 'heb', 'חֹדֶשׁ', '["chôdesh"]', '["new moons/ your"]', '["n-m"]', 'the new moon; by implication, a month month(-ly), new moon.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4150H}/H9026/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["and/ appointed feasts/ your"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2960}/[H2959]', 'inflected', 'heb', 'טֹרַח', '["ṭôrach"]', '["<into>/ a burden"]', '["n-m"]', 'a burden cumbrance, trouble.', 'from 2959;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6566}/H9046/[H6566]', 'inflected', 'heb', 'פָּרַשׂ', '["pâras"]', '["and/ when/ spread out/ you"]', '["v"]', 'to break apart, disperse, etc. break, chop in pieces, lay open, scatter, spread (abroad, forth, selves, out), stretch (forth, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3709G}/H9026/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["hands/ your"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4611}/H9026/[H5953]', 'inflected', 'heb', 'מַעֲלָל', '["maʻălâl"]', '["deeds/ your"]', '["n-m"]', 'an act (good or bad) doing, endeavour, invention, work.', 'from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2541}/[H2556]', 'lemma', 'heb', 'חָמוֹץ', '["châmôwts"]', '["[the] oppressor"]', '["n-m"]', 'properly, violent; by implication, a robber oppressed.', 'from 2556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0490}\/[H488]', 'inflected', 'heb', 'אַלְמָנָה', '["ʼalmânâh"]', '["[the] widow"]', '["n-f"]', 'a widow; also a desolate place desolate house (palace), widow.', 'feminine of 488;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2399}/H9026/[H2398]', 'inflected', 'heb', 'חֵטְא', '["chêṭᵉʼ"]', '["sins/ your"]', '["n-m"]', 'a crime or its penalty fault, × grievously, offence, (punishment of) sin.', 'from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H8144>', 'inflected', 'heb', 'כשנים', '["ka./sha.Nim"]', '["like <the>/ scarlet"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8438A}/[H3216]', 'inflected', 'heb', 'תּוֹלָע', '["tôwlâʻ"]', '["like <the>/ crimson"]', '["n-m n-f"]', 'a maggot (as voracious); specifically (often with ellipsis of 8144) the crimson-grub, but used only (in this connection) of the color from it, and cloths dyed therewith crimson, scarlet, worm.', 'and (feminine) תּוֹלֵעָה; or תּוֹלַעַת; or תֹּלַעַת; from 3216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3701G}/H9022/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["silver/ your"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5509}/[H5472]', 'inflected', 'heb', 'סִיג', '["çîyg"]', '["<into>/ dross","<into>/ dross<es>"]', '["n-m"]', 'scoria dross.', 'or סוּג; (Ezekiel 22:18), from 5472 in the sense of refuse;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5435}/H9022/[H5433]', 'inflected', 'heb', 'סֹבֶא', '["çôbeʼ"]', '["drink/ your"]', '["n-m"]', 'potation, concretely (wine), or abstractly (carousal) drink, drunken, wine.', 'from 5433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4107}/[H4107]', 'lemma', 'heb', 'מָהַל', '["mâhal"]', '["[has been] mixed"]', '["v"]', 'properly, to cut down or reduce, i.e. by implication, to adulterate mixed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8269}/H9022/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["leaders/ your"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2270}/[H2266]', 'inflected', 'heb', 'חָבֵר', '["châbêr"]', '["and/ companions of"]', '["n-m"]', 'an associate companion, fellow, knit together.', 'from 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8021}/[H7999]', 'lemma', 'heb', 'שַׁלְמֹן', '["shalmôn"]', '["rewards"]', '["n-m"]', 'a bribe reward.', 'from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6862C}/H9020/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["from/ foes/ my"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6884}/[H6884]', 'inflected', 'heb', 'צָרַף', '["tsâraph"]', '["and/ a metalsmith","so/ I may refine","so/ they may be refined"]', '["v"]', 'to fuse (metal), i.e. refine (literally or figuratively) cast, (re-) fine(-er), founder, goldsmith, melt, pure, purge away, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1253}/[H1252]', 'inflected', 'heb', 'בֹּר', '["bôr"]', '["like <the>/ potash"]', '["n-m"]', 'vegetable lye (from its cleansing); used as a soap for washing, or a flux for metals × never so, purely.', 'the same as 1252;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5509}/H9022/[H5472]', 'inflected', 'heb', 'סִיג', '["çîyg"]', '["dross<es>/ your"]', '["n-m"]', 'scoria dross.', 'or סוּג; (Ezekiel 22:18), from 5472 in the sense of refuse;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0913}/H9022/[H914]', 'inflected', 'heb', 'בְּדִיל', '["bᵉdîyl"]', '["slag<s>/ your"]', '["n-m"]', 'alloy (because removed by smelting); by analogy, tin plummet, tin.', 'from 914;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8199}/H9032/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["judges/ your","they have judged/ you"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3289}/H9032/[H3289]', 'inflected', 'heb', 'יָעַץ', '["yâʻats"]', '["and/ counselors/ your"]', '["v"]', 'to advise; reflexively, to deliberate or resolve advertise, take advise, advise (well), consult, (give, take) counsel(-lor), determine, devise, guide, purpose.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/H9003/{H8462}/[H2490]', 'inflected', 'heb', 'תְּחִלָּה', '["tᵉchillâh"]', '["as/ at the/ beginning"]', '["n-f"]', 'a commencement; relatively original (adverb, -ly) begin(-ning), first (time).', 'from 2490 in the sense of opening;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7725O}/H9034/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ repentant [ones]/ its"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7667}/[H7665]', 'inflected', 'heb', 'שֶׁבֶר', '["sheber"]', '["and/ a crashing","and/ a crushing of","and/ destruction"]', '["n-m"]', 'a fracture, figuratively, ruin; specifically, a solution (of a dream) affliction, breach, breaking, broken(-footed, -handed), bruise, crashing, destruction, hurt, interpretation, vexation.', 'or שֵׁבֶר; from 7665;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0352D}/[H193]', 'inflected', 'heb', 'אַיִל', '["ʼayil"]', '["from/ [the] oaks"]', '["n-m"]', 'properly, strength; hence, anything strong; specifically a chief (politically); also a ram (from his strength); a pilaster (as a strong support); an oak or other strong tree mighty (man), lintel, oak, post, ram, tree.', 'from the same as 193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H1593}/[H1588]', 'inflected', 'heb', 'גַּנָּה', '["gannâh"]', '["from/ the/ gardens"]', '["n-f"]', 'a garden garden.', 'feminine of 1588;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0424}/[H352]', 'inflected', 'heb', 'אֵלָה', '["ʼêlâh"]', '["like <the>/ terebinth","like/ an oak"]', '["n-f"]', 'an oak or other strong tree elm, oak, teil-tree.', 'feminine of 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5929}/H9024/[H5927]', 'inflected', 'heb', 'עָלֶה', '["ʻâleh"]', '["<of> leafage/ its"]', '["n-m"]', 'a leaf (as coming up on a tree); collectively, foliage branch, leaf.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H1593}/[H1588]', 'inflected', 'heb', 'גַּנָּה', '["gannâh"]', '["and/ like/ a garden"]', '["n-f"]', 'a garden garden.', 'feminine of 1588;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2634}/[H2630]', 'inflected', 'heb', 'חָסֹן', '["châçôn"]', '["the/ strong [person]"]', '["a"]', 'powerful strong.', 'from 2630;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5296}/[H5287]', 'inflected', 'heb', 'נְעֹרֶת', '["nᵉʻôreth"]', '["<into>/ tow"]', '["n-f"]', 'something shaken out, i.e. tow (as the refuse of flax) tow.', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6467}/H9023/[H6466]', 'inflected', 'heb', 'פֹּעַל', '["pôʻal"]', '["and/ wage[s]/ his","and/ work/ his"]', '["n-m"]', 'an act or work (concretely) act, deed, do, getting, maker, work.', 'from 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5213}/[H5340]', 'inflected', 'heb', 'נִיצוֹץ', '["nîytsôwts"]', '["<into>/ a spark"]', '["n-m"]', 'a spark spark.', 'from 5340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5375G}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ it will be lifted up","and/ lift up","and/ lifted up","and/ take up","and/ they may take up"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5102A}/[H5102]', 'inflected', 'heb', 'נָהַר', '["nâhar"]', '["and/ they will be radiant","and/ they will stream"]', '["v"]', 'to sparkle, i.e. (figuratively) be cheerful; hence (from the sheen of a running stream) to flow, i.e. (figuratively) assemble flow (together), be lightened.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0734}/H9023/[H732]', 'inflected', 'heb', 'אֹרַח', '["ʼôrach"]', '["in/ paths/ his"]', '["n-m"]', 'a well-trodden road (literally or figuratively); also a caravan manner, path, race, rank, traveller, troop, (by-, high-) way.', 'from 732;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0855>', 'inflected', 'heb', 'לאתים', '["le./''i.Tim"]', '["<into>/ plowshares","into/ plowshares"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2595}/H9028/[H2583]', 'inflected', 'heb', 'חֲנִית', '["chănîyth"]', '["and/ spears/ their"]', '["n-f"]', 'a lance (for thrusting, like pitching a tent) javelin, spear.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4211}/[H2168]', 'inflected', 'heb', 'מַזְמֵרָה', '["mazmêrâh"]', '["<into>/ pruning knives","into/ pruning knives"]', '["n-f"]', 'a pruning-knife pruning-hook.', 'from 2168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6049B}/[H6051]', 'inflected', 'heb', 'עָנַן', '["ʻânan"]', '["and/ soothsayers"]', '["v"]', 'figuratively, to act covertly, i.e. practise magic × bring, enchanter, Meonemin, observe(-r of) times, soothsayer, sorcerer.', 'a primitive root; to cover; used only as a denominative from 6051, to cloud over;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6430G}/[H6429]', 'inflected', 'heb', 'פְּלִשְׁתִּי', '["Pᵉlishtîy"]', '["like the/ Philistines"]', '["a"]', 'a Pelishtite or inhabitant of Pelesheth Philistine.', 'patrial from 6429;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3206}/[H3205]', 'inflected', 'heb', 'יֶלֶד', '["yeled"]', '["and/ with/ [the] children of"]', '["n-m"]', 'something born, i.e. a lad or offspring boy, child, fruit, son, young man (one).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7097B}/[H7096]', 'lemma', 'heb', 'קָצֶה', '["qâtseh"]', '["[is] an end"]', '["n-m"]', 'an extremity × after, border, brim, brink, edge, end, (in-) finite, frontier, outmost coast, quarter, shore, (out-) side, × some, ut(-ter-) most (part).', 'or (negative only) קֵצֶה; from 7096; (used in a great variety of applications and idioms; compare 7093)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0214}/H9023/[H686]', 'inflected', 'heb', 'אוֹצָר', '["ʼôwtsâr"]', '["to/ treasures/ its"]', '["n-m"]', 'a depository armory, cellar, garner, store(-house), treasure(-house) (-y).', 'from 686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4818}/H9023/[H4817]', 'inflected', 'heb', 'מֶרְכָּבָה', '["merkâbâh"]', '["to/ chariots/ its"]', '["n-f"]', 'a chariot chariot. See also 1024.', 'feminine of 4817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8213}/[H8213]', 'inflected', 'heb', 'שָׁפֵל', '["shâphêl"]', '["and/ he has become low","and/ he will bring low","and/ it will become low","and/ you showed abasement","and/ you will become low"]', '["v"]', 'to depress or sink (especially figuratively, to humiliate, intransitive or transitive) abase, bring (cast, put) down, debase, humble (self), be (bring, lay, make, put) low(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2934}/[H2934]', 'inflected', 'heb', 'טָמַן', '["ṭâman"]', '["and/ hide yourself"]', '["v"]', 'to hide (by covering over) hide, lay privily, in secret.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1926}/[H1921]', 'inflected', 'heb', 'הָדָר', '["hâdâr"]', '["and/ from/ [the] splendor of"]', '["n-m"]', 'magnificence, i.e. ornament or splendor beauty, comeliness, excellency, glorious, glory, goodly, honour, majesty.', 'from 1921;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1365}/[H1361]', 'lemma', 'heb', 'גַּבְהוּת', '["gabhûwth"]', '["[the] haughtiness of","haughtiness of"]', '["n-m"]', 'pride loftiness, lofty.', 'from 1361;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8213}/[H8213]', 'inflected', 'heb', 'שָׁפֵל', '["shâphêl"]', '["and/ [it will be] low"]', '["v"]', 'to depress or sink (especially figuratively, to humiliate, intransitive or transitive) abase, bring (cast, put) down, debase, humble (self), be (bring, lay, make, put) low(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5375G}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ which/ are lifted up"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0437}/[H436]', 'lemma', 'heb', 'אַלּוֹן', '["ʼallôwn"]', '["O oaks of","[the] oaks of","oak","oaks"]', '["n-m"]', 'oak.', 'a variation of 436');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5375G}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["that/ are lifted up"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7914}/[H7906]', 'lemma', 'heb', 'שְׂכִיָּה', '["sᵉkîyâh"]', '["[the] ships of"]', '["n-f"]', 'a conspicuous object picture.', 'feminine from the same as 7906;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2532A}/[H2531]', 'inflected', 'heb', 'חֶמְדָּה', '["chemdâh"]', '["<the>/ desire"]', '["n-f"]', 'delight desire, goodly, pleasant, precious.', 'feminine of 2531;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0457}/[H408]', 'inflected', 'heb', 'אֱלִיל', '["ʼĕlîyl"]', '["and/ the/ idols"]', '["a-m"]', 'good for nothing, by analogy vain or vanity; specifically an idol idol, no value, thing of nought.', 'apparently from 408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4247}/[H2490]', 'inflected', 'heb', 'מְחִלָּה', '["mᵉchillâh"]', '["and/ in/ holes of"]', '["n-f"]', 'a cavern (as if excavated) cave.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6965B}/H9043/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["when/ arises/ he"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2091>/H9023', 'opaque', 'heb', 'זָהָב', '["zâhâb"]', '["gold/ his","gold/ its"]', '["n-m"]', 'gold, figuratively, something gold-colored (i.e. yellow), as oil, a clear sky gold(-en), fair weather.', 'from an unused root meaning to shimmer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2661}/[H2658]', 'inflected', 'heb', 'חֲפֹר', '["chăphôr"]', '["to/ [the] digging of"]', '["n-f"]', 'a burrower, i.e. probably a rat mole.', 'from 2658; a hole; only in connection with 6512, which ought rather to be joined as one word, thus חַפַרְפֵּרָה; by reduplication from 2658;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6512}/[H6331]', 'lemma', 'heb', 'פֵּרָה', '["pêrâh"]', '["moles"]', '["n-f"]', 'a hole (as broken, i.e. dug) + mole. Compare 2661.', 'from 6331;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H5847>', 'inflected', 'heb', 'ולעטלפים', '["ve./la./''a.ta.le.Fim"]', '["and/ to the/ bats"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5585}/[H5586]', 'inflected', 'heb', 'סָעִיף', '["çâʻîyph"]', '["and/ in/ [the] clefts of"]', '["n-m"]', 'a fissure (of rocks); also a bough (as subdivided) (outmost) branch, clift, top.', 'from 5586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H3063G}/[H3034]', 'inflected', 'heb', 'יְהוּדָה', '["Yᵉhûwdâh"]', '["and/ from/ Judah"]', '["n-pr-m"]', 'Jehudah (or Judah), the name of five Israelites; also of the tribe descended from the first, and of its territory Judah.', 'from 3034; celebrated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4937B}/[H8172]', 'lemma', 'heb', 'מִשְׁעֵן', '["mishʻên"]', '["support"]', '["n-m"]', 'a support (concretely), i.e. (figuratively) a protector or sustenance stay.', 'or מִשְׁעָן; from 8172;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4938A}/[H4937]', 'inflected', 'heb', 'מִשְׁעֵנָה', '["mishʻênâh"]', '["and/ support"]', '["n-f"]', 'support (abstractly), i.e. (figuratively) sustenance or (concretely) a walking-stick staff.', 'or מִשְׁעֶנֶת; feminine of 4937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7080}/[H7080]', 'inflected', 'heb', 'קָסַם', '["qâçam"]', '["and/ [they are] divining","and/ diviner","and/ diviners"]', '["v"]', 'properly, to distribute, i.e. determine by lot or magical scroll; by implication, to divine divine(-r, -ation), prudent, soothsayer, use (divination).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2791B}/[H2790]', 'lemma', 'heb', 'חֶרֶשׁ', '["cheresh"]', '["magic arts"]', '["adv"]', 'magical craft; also silence cunning, secretly.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8269}/H9028/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["leaders/ their","officials/ their"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8586}/[H5953]', 'inflected', 'heb', 'תַּעֲלוּל', '["taʻălûwl"]', '["and/ wantonness<es>"]', '["n-m"]', 'caprice (as a fit coming on), i.e. vexation; concretely a tyrant babe, delusion.', 'from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5065}/[H5065]', 'inflected', 'heb', 'נָגַשׂ', '["nâgas"]', '["and/ it will oppress"]', '["v"]', 'to drive (an animal, a workman, a debtor, an army); by implication, to tax, harass, tyrannize distress, driver, exact(-or), oppress(-or), × raiser of taxes, taskmaster.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7292}/[H7292]', 'lemma', 'heb', 'רָהַב', '["râhab"]', '["they will act insolently"]', '["v"]', 'to urge severely, i.e. (figuratively) importune, embolden, capture, act insolently overcome, behave self proudly, make sure, strengthen.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2205G}/[H2204]', 'inflected', 'heb', 'זָקֵן', '["zâqên"]', '["in the/ old [person]"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7034}/[H7034]', 'inflected', 'heb', 'קָלָה', '["qâlâh"]', '["and/ the/ lightly esteemed"]', '["v"]', 'to be light (as implied in rapid motion), but figuratively, only (be [causatively, hold] in contempt) base, contemn, despise, lightly esteem, set light, seem vile.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3513G}/[H3513]', 'inflected', 'heb', 'כָּבַד', '["kâbad"]', '["in the/ honored"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4384}/[H3782]', 'inflected', 'heb', 'מַכְשֵׁלָה', '["makshêlâh"]', '["and/ the/ heap of ruins","and/ the/ stumbling-blocks"]', '["n-f"]', 'a stumbling-block, but only figuratively (fall, enticement [idol]) ruin, stumbling-block.', 'feminine from 3782;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1004B}/H9020/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ in/ house/ my"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4611}/H9028/[H5953]', 'inflected', 'heb', 'מַעֲלָל', '["maʻălâl"]', '["and/ deeds/ their"]', '["n-m"]', 'an act (good or bad) doing, endeavour, invention, work.', 'from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1971}/[H5234]', 'lemma', 'heb', 'הַכָּרָה', '["hakkârâh"]', '["[the] expression of"]', '["n-f"]', 'respect, i.e. partiality shew.', 'from 5234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5315I}/H9028/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["to/ self/ their"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5953C}/[H5953]', 'lemma', 'heb', 'עָלַל', '["ʻâlal"]', '["[is] acting like children"]', '["v"]', 'to effect thoroughly; specifically, to glean (also figuratively); by implication (in a bad sense) to overdo, i.e. maltreat, be saucy to, pain, impose (also literal) abuse, affect, × child, defile, do, glean, mock, practise, thoroughly, work (wonderfully).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0833}/H9031/[H833]', 'inflected', 'heb', 'אָשַׁר', '["ʼâshar"]', '["guides/ your"]', '["v"]', 'to be straight (used in the widest sense, especially to be level, right, happy); figuratively, to go forward, be honest, prosper (call, be) bless(-ed, happy), go, guide, lead, relieve.', 'or אָשֵׁר; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1104}\/[H1104]', 'inflected', 'heb', 'בָּלַע', '["bâlaʻ"]', '["they have confused"]', '["v"]', 'to make away with (specifically by swallowing); generally, to destroy cover, destroy, devour, eat up, be at end, spend up, swallow down (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1500}/[H1498]', 'lemma', 'heb', 'גְּזֵלָה', '["gᵉzêlâh"]', '["[the] plunder of","robberies","robbery"]', '["n-f"]', 'that (he had robbed) (which he took violently away), spoil, violence.', 'feminine of 1498 and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4100}/H9014/H9005/H9046/[H4100]', 'inflected', 'heb', 'מָה', '["mâh"]', '["what/-/[is] to/ you?"]', '["i"]', 'properly, interrogative what? (including how? why? when?); but also exclamation, what! (including how!), or indefinitely what (including whatever, and even relatively, that which); often used with prefixes in various adverbial or conjunctive senses how (long, oft, (-soever)), (no-) thing, what (end, good, purpose, thing), whereby(-fore, -in, -to, -with), (for) why.', 'or מַה; or מָ; or מַ; also מֶה; a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6635B}\/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["hosts","of hosts"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1627}/[H1641]', 'lemma', 'heb', 'גָּרוֹן', '["gârôwn"]', '["of neck"]', '["n-m"]', 'the throat (as roughened by swallowing) × aloud, mouth, neck, throat.', 'or (shortened) גָּרֹן; from 1641; (compare 1621)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8265}/[H8265]', 'inflected', 'heb', 'שָׂקַר', '["sâqar"]', '["and/ making seductive glances"]', '["v"]', 'to ogle, i.e. blink coquettishly wanton.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2952}/[H2952]', 'inflected', 'heb', 'טָפַף', '["ṭâphaph"]', '["and/ mincing along"]', '["v"]', 'to trip (with short steps) coquettishly mince.', 'a primitive root; apparently');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7272}/H9028/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["and/ on/ feet/ their"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5913}/[H5914]', 'lemma', 'heb', 'עָכַס', '["ʻâkaç"]', '["they tinkle with anklets"]', '["v"]', 'to put on anklets make a tinkling ornament.', 'a primitive root; properly, to tie, specifically, with fetters; but used only as denominative from 5914;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5596B}/[H5596]', 'inflected', 'heb', 'סָפַח', '["çâphach"]', '["and/ he will make scabby"]', '["v"]', 'properly, to scrape out, but in certain peculiar senses (of removal or association) abiding, gather together, cleave, smite with the scab.', 'or שָׂפַח; (Isaiah 3:17), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6596>/H9029', 'opaque', 'heb', 'פֹּת', '["pôth"]', '["forehead/ their"]', '["n-f"]', 'a hole, i.e. hinge or the female pudenda hinge, secret participle', 'or פֹּתָה; (Ezekiel 13:19), from an unused root meaning to open;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6168}\/[H6168]', 'inflected', 'heb', 'עָרָה', '["ʻârâh"]', '["he will lay bare"]', '["v"]', 'to be (causatively, make) bare; hence, to empty, pour out, demolish leave destitute, discover, empty, make naked, pour (out), rase, spread self, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5914}/[H5913]', 'inflected', 'heb', 'עֶכֶס', '["ʻekeç"]', '["the/ anklets"]', '["n-m"]', 'a fetter; hence, an anklet stocks, tinkling ornament.', 'from 5913;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H7636>', 'inflected', 'heb', 'והשביסים', '["ve./ha./she.vi.Sim"]', '["and/ the/ amulets"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7720}/[H5469]', 'inflected', 'heb', 'שַׂהֲרֹן', '["sahărôn"]', '["and/ the/ ornaments"]', '["n-m"]', 'a round pendant for the neck ornament, round tire like the moon.', 'from the same as 5469;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5188}/[H5197]', 'inflected', 'heb', 'נְטִיפָה', '["nᵉṭîyphâh"]', '["the/ pendants"]', '["n-f"]', 'a pendant for the ears (especially of pearls) chain, collar.', 'from 5197;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8285}/[H8324]', 'inflected', 'heb', 'שֵׁרָה', '["shêrâh"]', '["and/ the/ bracelets"]', '["n-f"]', 'a wrist-band (as compact or clasping) bracelet.', 'from 8324 in its original sense of pressing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7479}/[H7478]', 'inflected', 'heb', 'רַעֲלָה', '["raʻălâh"]', '["and/ the/ veils"]', '["n-f"]', 'a long veil (as fluttering) muffler.', 'feminine of 7478;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6287}/[H6286]', 'inflected', 'heb', 'פְּאֵר', '["pᵉʼêr"]', '["the/ head-dresses"]', '["n-m"]', 'an embellishment, i.e. fancy head-dress beauty, bonnet, goodly, ornament, tire.', 'from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6807B}/[H6806]', 'inflected', 'heb', 'צְעָדָה', '["tsᵉʻâdâh"]', '["and/ the/ ankle chains"]', '["n-f"]', 'a march; (concretely) an (ornamental) ankle-chain going, ornament of the legs.', 'feminine of 6806;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7196}/[H7194]', 'inflected', 'heb', 'קִשֻּׁר', '["qishshur"]', '["and/ the/ sashes"]', '["n-m"]', 'an (ornamental) girdle (for women) attire, headband.', 'from 7194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3908}/[H3907]', 'inflected', 'heb', 'לַחַשׁ', '["lachash"]', '["and/ the/ amulets"]', '["n-m"]', 'properly, a whisper, i.e. by implication, (in a good sense) a private prayer, (in a bad one) an incantation; concretely, an amulet charmed, earring, enchantment, orator, prayer.', 'from 3907;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0639H}/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["the/ nose"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4254}/[H2502]', 'inflected', 'heb', 'מַחֲלָצָה', '["machălâtsâh"]', '["the/ robes"]', '["n-f"]', 'a mantle (as easily drawn off) changeable suit of apparel, change of raiment.', 'from 2502;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4595}/[H5848]', 'inflected', 'heb', 'מַעֲטָפָה', '["maʻăṭâphâh"]', '["and/ the/ over-tunics"]', '["n-f"]', 'a cloak mantle.', 'from 5848;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4304}/[H2946]', 'inflected', 'heb', 'מִטְפַּחַת', '["miṭpachath"]', '["and/ the/ cloaks"]', '["n-f"]', 'a wide cloak (for a woman) vail, wimple.', 'from 2946;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2754}/[H2747]', 'inflected', 'heb', 'חָרִיט', '["chârîyṭ"]', '["and/ the/ purses"]', '["n-m"]', 'properly, cut out (or hollow), i.e. (by implication) a pocket bag, crisping pin.', 'or חָרִט; from the same as 2747;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1549}/[H1540]', 'inflected', 'heb', 'גִּלָּיוֹן', '["gillâyôwn"]', '["and/ the/ mirrors"]', '["n-m"]', 'a tablet for writing (as bare); by analogy, a mirror (as a plate) glass, roll.', 'or גִּלְיוֹן; from 1540;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H5466>', 'inflected', 'heb', 'והסדינים', '["ve./ha./se.di.Nim"]', '["and/ the/ linen garments"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6797}/[H6801]', 'inflected', 'heb', 'צָנִיף', '["tsânîyph"]', '["and/ the/ headdresses"]', '["n-m"]', 'a head-dress (i.e. piece of cloth wrapped around) diadem, hood, mitre.', 'or צָנוֹף; or (feminine) צָנִיפָה; from 6801;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7289}/[H7286]', 'inflected', 'heb', 'רָדִיד', '["râdîyd"]', '["and/ the/ shawls"]', '["n-m"]', 'a veil (as expanded) vail, veil.', 'from 7286 in the sense of spreading;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4716}/[H4743]', 'lemma', 'heb', 'מַק', '["maq"]', '["rottenness"]', '["n-m"]', 'properly, a melting, i.e. putridity rottenness, stink.', 'from 4743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5364}/[H5362]', 'lemma', 'heb', 'נִקְפָּה', '["niqpâh"]', '["a rope"]', '["n-f"]', 'probably a rope (as encircling) rent.', 'from 5362;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4748}/[H7185]', 'lemma', 'heb', 'מִקְשֶׁה', '["miqsheh"]', '["well-set hair"]', '["n-m"]', 'something turned (rounded), i.e. a curl (of tresses) × well (set) hair.', 'from 7185 in the sense of knotting up round and hard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6614>', 'opaque', 'heb', 'פְּתִיגִיל', '["pᵉthîygîyl"]', '["a robe"]', '["n-m"]', 'probably a figured mantle for holidays stomacher.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4228}/[H2296]', 'lemma', 'heb', 'מַחֲגֹרֶת', '["machăgôreth"]', '["a girding of"]', '["n-f"]', 'a girdle girding.', 'from 2296;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3587}/[H3554]', 'lemma', 'heb', 'כִּי', '["kîy"]', '["branding"]', '["n-m"]', 'a brand or scar burning.', 'from 3554;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4962}/H9022/[H4970]', 'inflected', 'heb', 'מַת', '["math"]', '["men/ your"]', '["n-m"]', 'properly, an adult (as of full length); by implication, a man (only in the plural) few, × friends, men, persons, × small.', 'from the same as 4970;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1369}/H9022/[H1368]', 'inflected', 'heb', 'גְּבוּרָה', '["gᵉbûwrâh"]', '["and/ strength/ your"]', '["n-f"]', 'force (literally or figuratively); by implication, valor, victory force, mastery, might, mighty (act, power), power, strength.', 'feminine passive participle from the same as 1368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0578}/[H578]', 'inflected', 'heb', 'אָנָה', '["ʼânâh"]', '["and/ they will lament"]', '["v"]', 'to groan lament, mourn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6607}/H9024/[H6605]', 'inflected', 'heb', 'פֶּתַח', '["pethach"]', '["gates/ its"]', '["n-m"]', 'an opening (literally), i.e. door (gate) or entrance way door, entering (in), entrance (-ry), gate, opening, place.', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8071}/H9025/[H5566]', 'inflected', 'heb', 'שִׂמְלָה', '["simlâh"]', '["and/ own clothing/ our"]', '["n-f"]', 'a dress, especially a mantle apparel, cloth(-es, -ing), garment, raiment. Compare 8008.', 'perhaps by permutation for the feminine of 5566 (through the idea of a cover assuming the shape of the object beneath);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2781}/H9025\/[H2778]', 'inflected', 'heb', 'חֶרְפָּה', '["cherpâh"]', '["reproach/ our"]', '["n-f"]', 'contumely, disgrace, the pudenda rebuke, reproach(-fully), shame.', 'from 2778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6780}/[H6779]', 'lemma', 'heb', 'צֶמַח', '["tsemach"]', '["[is] Branch","[the] branch of","a branch","a branch of","branch","growth"]', '["n-m"]', 'a sprout (usually concrete), literal or figurative branch, bud, that which (where) grew (upon), spring(-ing).', 'from 6779;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6643A}/[H6638]', 'inflected', 'heb', 'צְבִי', '["tsᵉbîy"]', '["<into>/ beauty"]', '["n-m"]', 'splendor (as conspicuous) beautiful(-ty), glorious (-ry), goodly, pleasant, roe(-buck).', 'from 6638 in the sense of prominence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3519}/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["and/ <into>/ glory"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1347}/[H1342]', 'inflected', 'heb', 'גָּאוֹן', '["gâʼôwn"]', '["<into>/ an exaltation of","<into>/ exaltation","into/ pride"]', '["n-m"]', 'the same as 1346 arrogancy, excellency(-lent), majesty, pomp, pride, proud, swelling.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6675}/[H6674]', 'lemma', 'heb', 'צוֹאָה', '["tsôwʼâh"]', '["[the] excrement of","filth"]', '["n-f"]', 'excrement; generally, dirt; figuratively, pollution dung, filth(-iness). Marg. for 2716.', 'or צֹאָה ; feminine of 6674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7130G}/H9024/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["from/ midst/ its"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7307G}/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["and/ by/ a spirit of"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4744}/H9024/[H7121]', 'inflected', 'heb', 'מִקְרָא', '["miqrâʼ"]', '["convocations/ its"]', '["n-m"]', 'something called out, i.e. a public meeting (the act, the persons, or the place); also a rehearsal assembly, calling, convocation, reading.', 'from 7121;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6227}/[H6225]', 'inflected', 'heb', 'עָשָׁן', '["ʻâshân"]', '["and/ smoke"]', '["n-m"]', 'smoke, literally or figuratively (vapor, dust, anger) smoke(-ing).', 'from 6225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5051}/[H5050]', 'inflected', 'heb', 'נֹגַהּ', '["nôgahh"]', '["and/ brightness","and/ brightness of"]', '["n-f"]', 'brilliancy (literally or figuratively) bright(-ness), light, (clear) shining.', 'from 5050;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2646}/[H2645]', 'lemma', 'heb', 'חֻפָּה', '["chuppâh"]', '["a canopy"]', '["n-f"]', 'a canopy chamber, closet, defence.', 'from 2645;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5521}/[H5520]', 'inflected', 'heb', 'סֻכָּה', '["çukkâh"]', '["and/ a shelter"]', '["n-f"]', 'a hut or lair booth, cottage, covert, pavilion, tabernacle, tent.', 'feminine of 5520;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2721A}/[H2719]', 'inflected', 'heb', 'חֹרֶב', '["chôreb"]', '["from/ [the] heat","from/ heat"]', '["n-m"]', 'drought or desolation desolation, drought, dry, heat, × utterly, waste.', 'a collaterally form of 2719;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4268}/[H2620]', 'inflected', 'heb', 'מַחֲסֶה', '["machăçeh"]', '["and/ for/ refuge"]', '["n-m"]', 'a shelter (literally or figuratively) hope, (place of) refuge, shelter, trust.', 'or מַחְסֶה; from 2620;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4563}/[H5641]', 'inflected', 'heb', 'מִסְתּוֹר', '["miçtôwr"]', '["and/ for/ shelter"]', '["n-m"]', 'a refuge covert.', 'from 5641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4306}\/[H4305]', 'inflected', 'heb', 'מָטַר', '["mâṭar"]', '["and/ from/ [the] rain"]', '["n-m"]', 'rain rain.', 'from 4305;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3039A}/H9020/[H1730]', 'inflected', 'heb', 'יְדִיד', '["yᵉdîyd"]', '["to/ beloved [one]/ my"]', '["a n-f"]', 'loved amiable, (well-) beloved, loves.', 'from the same as 1730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7892B}/[H7891]', 'lemma', 'heb', 'שִׁיר', '["shîyr"]', '["a song of"]', '["n-m n-f"]', 'a song; abstractly, singing musical(-ick), × sing(-er, -ing), song.', 'or feminine שִׁירָה; from 7891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3754>/H9023', 'inflected', 'heb', 'לכרמו', '["le./khar.M/o"]', '["of/ vineyard/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5823}/H9033/[H5823]', 'inflected', 'heb', 'עָזַק', '["ʻâzaq"]', '["and/ he dug/ it"]', '["v"]', 'to grub over fence about.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8321A}/[H8319]', 'lemma', 'heb', 'שֹׂרֵק', '["sôrêq"]', '["a choice vine"]', '["n-m"]', 'a vine stock (properly, one yielding purple grapes, the richest variety) choice(-st, noble) wine. Compare 8291.', 'or שׂוֹרֵק; and (feminine) שֹׂרֵקָה; from 8319 in the sense of redness (compare 8320);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0891}/[H889]', 'lemma', 'heb', 'בְּאֻשִׁים', '["bᵉʼushîym"]', '["wild grapes"]', '["n-m"]', 'poison-berries wild grapes.', 'plural of 889;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3754>/H9020', 'inflected', 'heb', 'לכרמי', '["le./khar.M/i"]', '["for/ vineyard/ my","to/ vineyard/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4881B}/H9023/[H7753]', 'inflected', 'heb', 'מְשׂוּכָה', '["mᵉsûwkâh"]', '["hedge/ its"]', '["n-f"]', 'a hedge hedge.', 'or מְשֻׂכָה; from 7753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1197H}/[H1198]', 'inflected', 'heb', 'בָּעַר', '["bâʻar"]', '["<into>/ grazing"]', '["v"]', 'to kindle, i.e. consume (by fire or by eating); to be (-come) brutish be brutish, bring (put, take) away, burn, (cause to) eat (up), feed, heat, kindle, set (on fire), waste.', 'a primitive root; also as denominative from 1198');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1447}/H9023/[H1443]', 'inflected', 'heb', 'גָּדֵר', '["gâdêr"]', '["wall/ its"]', '["n-m"]', 'a circumvallation; by implication, an inclosure fence, hedge, wall.', 'from 1443;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4823}/[H7429]', 'inflected', 'heb', 'מִרְמָס', '["mirmâç"]', '["<into>/ a trampling place"]', '["n-m"]', 'abasement (the act or the thing) tread (down) -ing, (to be) trodden (down) under foot.', 'from 7429;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1326}/[H1327]', 'lemma', 'heb', 'בָּתָה', '["bâthâh"]', '["a desolation"]', '["n-f"]', 'desolation waste.', 'probably an orthographical variation for 1327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5737B}/[H5737]', 'lemma', 'heb', 'עֲדַר', '["ʻădar"]', '["it will be hoed"]', '["v"]', 'to arrange, as a battle, a vineyard (to hoe); hence, to muster and so to miss (or find wanting) dig, fail, keep (rank), lack.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8068}/[H8104]', 'lemma', 'heb', 'שָׁמִיר', '["shâmîyr"]', '["flint","thorn[s]"]', '["n-m"]', 'a thorn; also (from its keenness for scratching) a gem, probably the diamond adamant (stone), brier, diamond.', 'from 8104 in the original sense of pricking;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7898}/[H7896]', 'inflected', 'heb', 'שַׁיִת', '["shayith"]', '["and/ bush[es]"]', '["n-m"]', 'scrub or trash, i.e. wild growth of weeds or briers (as if put on the field) thorns.', 'from 7896;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4305}/[H4305]', 'inflected', 'heb', 'מָטַר', '["mâṭar"]', '["from/ raining"]', '["v"]', 'to rain (cause to) rain (upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8191}/H9023/[H8173]', 'inflected', 'heb', 'שַׁעְשֻׁעַ', '["shaʻshuaʻ"]', '["delight<s>/ his"]', '["n-m"]', 'enjoyment delight, pleasure.', 'from 8173;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4939}/[H5596]', 'lemma', 'heb', 'מִשְׂפָּח', '["mispâch"]', '["bloodshed"]', '["n-m"]', 'slaughter oppression.', 'from 5596;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6818}\/[H6817]', 'inflected', 'heb', 'צַעֲקָה', '["tsaʻăqâh"]', '["an outcry"]', '["n-f"]', 'a shriek cry(-ing).', 'from 6817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0369}/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["[are] from/ nothing","from/ not","from/ there not"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2233G}/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["and/ [the] seed of","and/ seed","and/ seed of"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0374}\/[H374]', 'inflected', 'heb', 'אֵיפָה', '["ʼêyphâh"]', '["an ephah"]', '["n-f"]', 'an ephah or measure for grain; hence, a measure in general ephah, (divers) measure(-s).', 'or (shortened) אֵפָה ; of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1814}/H9038/[H1814]', 'inflected', 'heb', 'דָּלַק', '["dâlaq"]', '["it inflames/ them"]', '["v"]', 'to flame (literally or figuratively) burning, chase, inflame, kindle, persecute(-or), pursue hotly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4960}/H9028/[H8354]', 'inflected', 'heb', 'מִשְׁתֶּה', '["mishteh"]', '["drink/ their","feast/ their"]', '["n-m"]', 'drink, by implication, drinking (the act); also (by implication) a banquet or (generally) feast banquet, drank, drink, feast((-ed), -ing).', 'from 8354;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3519}/H9023/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["and/ glory/ his","and/ honor/ its"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1995A}/H9023/[H1993]', 'inflected', 'heb', 'הָמוֹן', '["hâmôwn"]', '["and/ multitude/ its"]', '["n-m"]', 'a noise, tumult, crowd; also disquietude, wealth abundance, company, many, multitude, multiply, noise, riches, rumbling, sounding, store, tumult.', 'or הָמֹן; (Ezekiel 5:7), from 1993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6704>', 'opaque', 'heb', 'צִחֶה', '["tsicheh"]', '["[will be] parched of"]', '["a"]', 'parched dried up.', 'from an unused root meaning to glow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6772}/[H6770]', 'lemma', 'heb', 'צָמָא', '["tsâmâʼ"]', '["a thirst","thirst"]', '["n-m"]', 'thirst (literally or figuratively) thirst(-y).', 'from 6770;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315L}/H9024/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["throat/ its"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6473}/[H6473]', 'inflected', 'heb', 'פָּעַר', '["pâʻar"]', '["and/ it will open wide"]', '["v"]', 'to yawn, i.e. open wide (literally or figuratively) gape, open (wide).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1926}/H9024/[H1921]', 'inflected', 'heb', 'הָדָר', '["hâdâr"]', '["splendor/ her","splendor/ its"]', '["n-m"]', 'magnificence, i.e. ornament or splendor beauty, comeliness, excellency, glorious, glory, goodly, honour, majesty.', 'from 1921;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1995A}/H9024/[H1993]', 'inflected', 'heb', 'הָמוֹן', '["hâmôwn"]', '["and/ multitude/ its"]', '["n-m"]', 'a noise, tumult, crowd; also disquietude, wealth abundance, company, many, multitude, multiply, noise, riches, rumbling, sounding, store, tumult.', 'or הָמֹן; (Ezekiel 5:7), from 1993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7588}/H9024/[H7582]', 'inflected', 'heb', 'שָׁאוֹן', '["shâʼôwn"]', '["and/ uproar/ its"]', '["n-m"]', 'uproar (as of rushing); by implication, destruction × horrible, noise, pomp, rushing, tumult (× -uous).', 'from 7582;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5938}/[H5937]', 'inflected', 'heb', 'עָלֵז', '["ʻâlêz"]', '["and/ [one] exulting"]', '["a"]', 'exultant that rejoiceth.', 'from 5937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0410G}/[H352]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["and/ <the>/ God"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1699A}/H9028/[H1696]', 'inflected', 'heb', 'דֹּבֶר', '["dôber"]', '["like/ own pasture/ their"]', '["n-m"]', 'a pasture (from its arrangement of the flock) fold, manner.', 'from 1696 (in its original sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2723}/[H2721]', 'inflected', 'heb', 'חׇרְבָּה', '["chorbâh"]', '["and/ [the] ruins of","and/ a ruin"]', '["n-f"]', 'properly, drought, i.e. (by implication) a desolation decayed place, desolate (place, -tion), destruction, (laid) waste (place).', 'feminine of 2721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7723G}/[H7722]', 'inflected', 'heb', 'שָׁוְא', '["shâvᵉʼ"]', '["<the>/ emptiness","<the>/ worthlessness"]', '["n-m"]', 'evil (as destructive), literally (ruin) or morally (especially guile); figuratively idolatry (as false, subjective), uselessness (as deceptive, objective; also adverbially, in vain) false(-ly), lie, lying, vain, vanity.', 'or שַׁו; from the same as 7722 in the sense of desolating;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H5688}/[H5687]', 'inflected', 'heb', 'עֲבֹת', '["ʻăbôth"]', '["and/ like/ [the] rope of"]', '["n"]', 'something intwined, i.e. a string, wreath or foliage band, cord, rope, thick bough (branch), wreathen (chain).', 'or עֲבוֹת; or (feminine) עֲבֹתָה; the same as 5687;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2403A}/[H2398]', 'lemma', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["sin"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3045}\/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["so/ we may know"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2896B}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["and/ of <the>/ good"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4966}/[H4985]', 'inflected', 'heb', 'מָתוֹק', '["mâthôwq"]', '["into/ sweet"]', '["a"]', 'sweet sweet(-er, -ness).', 'or מָתוּק; from 4985;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4751}\/[H4843]', 'inflected', 'heb', 'מַר', '["mar"]', '["into/ bitter"]', '["a-m"]', 'bitter (literally or figuratively); also (as noun) bitterness, or (adverbially) bitterly angry, bitter(-ly, -ness), chafed, discontented, × great, heavy.', 'or (feminine) מָרָה; from 4843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4537}/[H4537]', 'inflected', 'heb', 'מָסַךְ', '["mâçak"]', '["for/ mixing"]', '["v"]', 'to mix, especially wine (with spices) mingle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0398}/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["as/ consumes"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2842}/[H7179]', 'inflected', 'heb', 'חָשַׁשׁ', '["châshash"]', '["and/ dry grass"]', '["n-m"]', 'dry grass chaff.', 'by variation for 7179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4716}/[H4743]', 'inflected', 'heb', 'מַק', '["maq"]', '["like <the>/ rottenness"]', '["n-m"]', 'properly, a melting, i.e. putridity rottenness, stink.', 'from 4743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6525}/H9028/[H6524]', 'inflected', 'heb', 'פֶּרַח', '["perach"]', '["and/ blossom/ their"]', '["n-m"]', 'a calyx (natural or artificial); generally, bloom blossom, bud, flower.', 'from 6524;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0080}/[H79]', 'inflected', 'heb', 'אָבָק', '["ʼâbâq"]', '["like <the>/ dust","like/ dust"]', '["n-m"]', 'light particles (as volatile) (small) dust, powder.', 'from root of 79;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5478}/[H5477]', 'inflected', 'heb', 'סוּחָה', '["çûwchâh"]', '["like <the>/ offal"]', '["n-f"]', 'something swept away, i.e. filth torn.', 'from the same as 5477;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5483M>/H9023', 'opaque', 'heb', 'סוּס', '["çûwç"]', '["horses/ his","horses/ its"]', '["n-m"]', 'a horse (as leaping); also a swallow (from its rapid flight) crane, horse (-back, -hoof). Compare 6571.', 'or סֻס; from an unused root meaning to skip (properly, for joy);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6862D}/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["like <the>/ flint"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1534}/H9023/[H1556]', 'inflected', 'heb', 'גַּלְגַּל', '["galgal"]', '["and/ wheels/ its"]', '["n-m"]', 'a wheel; by analogy, a whirlwind; also dust (as whirled) heaven, rolling thing, wheel.', 'by reduplication from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5098}/[H5098]', 'inflected', 'heb', 'נָהַם', '["nâham"]', '["and/ it may growl","so/ it may growl"]', '["v"]', 'to growl mourn, roar(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5100}/[H5099]', 'inflected', 'heb', 'נְהָמָה', '["nᵉhâmâh"]', '["like/ [the] growling of"]', '["n-f"]', 'snarling disquietness, roaring.', 'feminine of 5099;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6183}/H9024\/[H6201]', 'inflected', 'heb', 'עָרִיף', '["ʻârîyph"]', '["by/ clouds/ its"]', '["n-m"]', 'the sky (as drooping at the horizon) heaven.', 'from 6201;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7757>/H9023', 'inflected', 'heb', 'ושוליו', '["ve./shu.La/v"]', '["and/ [the] skirts of robe/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8314B}/[H8313]', 'lemma', 'heb', 'שָׂרָף', '["sârâph"]', '["seraphim"]', '["n-m"]', 'burning, i.e. (figuratively) poisonous (serpent); specifically, a saraph or symbolical creature (from their copper color) fiery (serpent), seraph.', 'from 8313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0520B}/[H517]', 'lemma', 'heb', 'אַמָּה', '["ʼammâh"]', '["[the] foundations of"]', '["n-f"]', 'properly, a mother (i.e. unit of measure, or the fore-arm (below the elbow), i.e. a cubit; also a door-base (as a bond of the entrance) cubit, + hundred (by exchange for 3967), measure, post.', 'prolonged from 517;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H6963A>', 'inflected', 'heb', 'מקול', '["mi./Kol"]', '["from/ [the] voice of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1004Q}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ the/ house"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8314B}/[H8313]', 'inflected', 'heb', 'שָׂרָף', '["sârâph"]', '["the/ seraphim"]', '["n-m"]', 'burning, i.e. (figuratively) poisonous (serpent); specifically, a saraph or symbolical creature (from their copper color) fiery (serpent), seraph.', 'from 8313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7531B}/[H7529]', 'lemma', 'heb', 'רִצְפָּה', '["ritspâh"]', '["a live coal"]', '["n-f"]', 'a hot stone; also a tessellated pavement live coal, pavement.', 'feminine of 7529;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4457}/[H3947]', 'inflected', 'heb', 'מֶלְקָח', '["melqâch"]', '["[which] with/ tongs"]', '["n-m"]', '(only in dual) tweezers snuffers, tongs.', 'or מַלְקָח; from 3947;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5771H}/H9021/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["iniquity/ your"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2403B}/H9021/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["and/ sin/ your","and/ sins/ your"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8173A}/[H8173]', 'lemma', 'heb', 'שָׁעַע', '["shâʻaʻ"]', '["blind yourselves","seal over"]', '["v"]', '(in a good acceptation) to look upon (with complacency), i.e. fondle, please or amuse (self); (in a bad one) to look about (in dismay), i.e. stare cry (out) (by confusion with 7768), dandle, delight (self), play, shut.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0241G}/H9023/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["and/ with/ ears/ its"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3824}/H9023/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["and/ heart/ his","and/ heart/ its"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7582}/[H7582]', 'lemma', 'heb', 'שָׁאָה', '["shâʼâh"]', '["it will be devastated","they have lain desolate"]', '["v"]', 'to rush; by implication, to desolate be desolate, (make a) rush(-ing), (lay) waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5805}/[H5800]', 'inflected', 'heb', 'עֲזוּבָה', '["ʻăzûwbâh"]', '["the/ abandoned [land]"]', '["n-f"]', 'desertion (of inhabitants) forsaking.', 'feminine passive participle of 5800;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0437}/[H436]', 'inflected', 'heb', 'אַלּוֹן', '["ʼallôwn"]', '["and/ like <the>/ oak"]', '["n-m"]', 'oak.', 'a variation of 436');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7995}/[H7993]', 'inflected', 'heb', 'שַׁלֶּכֶת', '["shalleketh"]', '["in/ [the] felling"]', '["n-f"]', 'a felling (of trees) when cast.', 'from 7993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4678}/H9024\/[H5324]', 'inflected', 'heb', 'מַצֶּבֶת', '["matstsebeth"]', '["stump/ its"]', '["n-f"]', 'something stationary, i.e. a monumental stone; also the stock of a tree pillar, substance.', 'from 5324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3824}/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["and/ [the] heart of"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5128}/[H5128]', 'inflected', 'heb', 'נוּעַ', '["nûwaʻ"]', '["as/ shake"]', '["v"]', 'to waver, in a great variety of applications, literally and figuratively (as subjoined) continually, fugitive, × make, to (go) up and down, be gone away, (be) move(-able, -d), be promoted, reel, remove, scatter, set, shake, sift, stagger, to and fro, be vagabond, wag, (make) wander (up and down).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7610}/[H7605]', 'inflected', 'heb', 'שְׁאָר יָשׁוּב', '["Shᵉʼâr Yâshûwb"]', '["and/ Shear-"]', '["n-pr-m"]', 'Shear-Jashub, the symbolic name of one of Isaiah''s sons Shear-jashub.', 'from 7605 and 7725; a remnant will return;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7610}/[H7605]', 'lemma', 'heb', 'שְׁאָר יָשׁוּב', '["Shᵉʼâr Yâshûwb"]', '["jashub"]', '["n-pr-m"]', 'Shear-Jashub, the symbolic name of one of Isaiah''s sons Shear-jashub.', 'from 7605 and 7725; a remnant will return;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3824}/H9021/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["and/ heart/ your"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0181>', 'inflected', 'heb', 'האודים', '["ha./''u.Dim"]', '["<the>/ pieces of firewood"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6226}/[H6225]', 'inflected', 'heb', 'עָשֵׁן', '["ʻâshên"]', '["<the>/ smoking"]', '["a"]', 'smoky smoking.', 'from 6225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6973}/H9034/[H6962]', 'inflected', 'heb', 'קוּץ', '["qûwts"]', '["and/ let us demolish/ it"]', '["v"]', 'to be (causatively, make) disgusted or anxious abhor, be distressed, be grieved, loathe, vex, be weary.', 'a primitive root (identical with through the idea of severing oneself from (compare 6962));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1234}/H9034/[H1234]', 'inflected', 'heb', 'בָּקַע', '["bâqaʻ"]', '["and/ let us break into/ it"]', '["v"]', 'to cleave; generally, to rend, break, rip or open make a breach, break forth (into, out, in pieces, through, up), be ready to burst, cleave (asunder), cut out, divide, hatch, rend (asunder), rip up, tear, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4427A}/[H4427]', 'inflected', 'heb', 'מָלַךְ', '["mâlak"]', '["and/ let us make king"]', '["v"]', 'to reign; inceptively, to ascend the throne; causatively, to induct into royalty; hence (by implication) to take counsel consult, × indeed, be (make, set a, set up) king, be (make) queen, (begin to, make to) reign(-ing), rule, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2870B}\/[H2895]', 'inflected', 'heb', 'טָבְאֵל', '["ṭâbᵉʼêl"]', '["Tabeel"]', '["n-pr-m"]', 'Tabeel, the name of a Syrian and of a Persian Tabeal, Tabeel.', 'from 2895 and 410; pleasing (to) God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5750}/[H5749]', 'inflected', 'heb', 'עוֹד', '["ʻôwd"]', '["and/ in/ yet"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0539}\/[H541]', 'inflected', 'heb', 'אָמַן', '["ʼâman"]', '["they are reliable","you will be established"]', '["v"]', 'properly, to build up or support; to foster as a parent or nurse; figuratively to render (or be) firm or faithful, to trust or believe, to be permanent or quiet; morally to be true or certain; hence, assurance, believe, bring up, establish, fail, be faithful (of long continuance, stedfast, sure, surely, trusty, verified), nurse, (-ing father), (put), trust, turn to the right.', 'a primitive root; (Isaiah 30:21; interchangeable with 541, to go to the right hand)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6005}/[H5973]', 'lemma', 'heb', 'עִמָּנוּאֵל', '["ʻImmânûwʼêl"]', '["-el","Immanu-","O Immanu-"]', '["n-pr-m"]', 'Immanuel, a type name of Isaiah''s son Immanuel.', 'from 5973 and with a pronominal suffix inserted; with us (is) God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3045}/H9033/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["to/ knowing/ his"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8319}/[H8319]', 'lemma', 'heb', 'שָׁרַק', '["shâraq"]', '["I will whistle","he will hiss","he will whistle","they have hissed"]', '["v"]', 'properly, to be shrill, i.e. to whistle or hiss (as a call or in scorn) hiss.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H2070>', 'inflected', 'heb', 'לזבוב', '["la./ze.Vuv"]', '["for the/ fly"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1682}/[H1696]', 'inflected', 'heb', 'דְּבוֹרָה', '["dᵉbôwrâh"]', '["and/ for the/ bee"]', '["n-f"]', 'the bee (from its systematic instincts) bee.', 'or (shortened) דְּבֹרָה; from 1696 (in the sense of orderly motion);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1327>', 'inflected', 'heb', 'הבתות', '["ha./ba.Tot"]', '["the/ cliffs"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H5357>', 'inflected', 'heb', 'ובנקיקי', '["u./vi/n.ki.Kei"]', '["and/ in/ [the] clefts of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5285>', 'inflected', 'heb', 'הנעצוצים', '["ha./Na.''a.tzu.Tzim","ha./na.''a.Tzutz"]', '["the/ thornbush","the/ thornbushes"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5097}/[H5095]', 'inflected', 'heb', 'נַהֲלֹל', '["nahălôl"]', '["the/ watering-places"]', '["n-m"]', 'pasture bush.', 'from 5095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8593}/[H6168]', 'inflected', 'heb', 'תַּעַר', '["taʻar"]', '["with/ [the] knife of","with/ a razor"]', '["n"]', 'a knife or razor (as making bare); also a scabbard (as being bare, i.e. empty) (pen-) knife, razor, scabbard, shave, sheath.', 'from 6168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7917}/[H7916]', 'inflected', 'heb', 'שְׂכִירָה', '["sᵉkîyrâh"]', '["<the>/ hired"]', '["a"]', 'a hiring that is hired.', 'feminine of 7916;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7272}/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["the/ feet"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8068}/[H8104]', 'inflected', 'heb', 'שָׁמִיר', '["shâmîyr"]', '["<into> the/ thorn[s]"]', '["n-m"]', 'a thorn; also (from its keenness for scratching) a gem, probably the diamond adamant (stone), brier, diamond.', 'from 8104 in the original sense of pricking;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7898}/[H7896]', 'inflected', 'heb', 'שַׁיִת', '["shayith"]', '["and/ <into> the>/ bush[es]"]', '["n-m"]', 'scrub or trash, i.e. wild growth of weeds or briers (as if put on the field) thorns.', 'from 7896;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7198}/[H7185]', 'inflected', 'heb', 'קֶשֶׁת', '["qesheth"]', '["and/ with <the>/ bow"]', '["n-f"]', 'a bow, for shooting (hence, figuratively, strength) or the iris × arch(-er), arrow, bow(-man, -shot).', 'from 7185 in the original sense (of 6983) of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4576}/[H5737]', 'inflected', 'heb', 'מַעְדֵּר', '["maʻdêr"]', '["with the/ hoe"]', '["n-m"]', 'a (weeding) hoe mattock.', 'from 5737;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5737B}/H9013/[H5737]', 'inflected', 'heb', 'עֲדַר', '["ʻădar"]', '["they were hoed/ !"]', '["v"]', 'to arrange, as a battle, a vineyard (to hoe); hence, to muster and so to miss (or find wanting) dig, fail, keep (rank), lack.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4916A}/[H7971]', 'inflected', 'heb', 'מִשְׁלוֹחַ', '["mishlôwach"]', '["<into>/ pastureland of"]', '["n-m"]', 'a sending out, i.e. (abstractly) presentation (favorable), or seizure (unfavorable); also (concretely) a place of dismissal, or a business to be discharged to lay, to put, sending (forth), to set.', 'or מִשְׁלֹחַ; also מִשְׁלָח; from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4823}/[H7429]', 'inflected', 'heb', 'מִרְמָס', '["mirmâç"]', '["and/ <into>/ a trampling place of"]', '["n-m"]', 'abasement (the act or the thing) tread (down) -ing, (to be) trodden (down) under foot.', 'from 7429;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7716}\/[H7582]', 'inflected', 'heb', 'שֶׂה', '["seh"]', '["sheep"]', '["n-m"]', 'a member of a flock, i.e. a sheep or goat (lesser, small) cattle, ewe, goat, lamb, sheep. Compare 2089.', 'or שֵׂי; probably from 7582 through the idea of pushing out to graze;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1549}/[H1540]', 'lemma', 'heb', 'גִּלָּיוֹן', '["gillâyôwn"]', '["a tablet"]', '["n-m"]', 'a tablet for writing (as bare); by analogy, a mirror (as a plate) glass, roll.', 'or גִּלְיוֹן; from 1540;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4122}/[H4118]', 'inflected', 'heb', 'מַהֵר שָׁלָל חָשׁ בַּז', '["Mahêr Shâlâl Châsh Baz"]', '["<to>/ Maher-"]', '["n-pr-m"]', 'Maher-Shalal-Chash-Baz; the symbolical name of the son of Isaiah Maher-sha-lal-bash-baz.', 'from 4118 and 7998 and 2363 and 957; hasting (is he (the enemy) to the) booty, swift (to the) prey;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4122}/[H4118]', 'lemma', 'heb', 'מַהֵר שָׁלָל חָשׁ בַּז', '["Mahêr Shâlâl Châsh Baz"]', '["Baz","Hash-","Maher-","Shalal-"]', '["n-pr-m"]', 'Maher-Shalal-Chash-Baz; the symbolical name of the son of Isaiah Maher-sha-lal-bash-baz.', 'from 4118 and 7998 and 2363 and 957; hasting (is he (the enemy) to the) booty, swift (to the) prey;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2148z}', 'inflected', 'heb', 'זכריהו', '["ze.khar.Ya.hu"]', '["Zechariah"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3000}/[H1288]', 'lemma', 'heb', 'יְבֶרֶכְיָהוּ', '["Yᵉberekyâhûw"]', '["Jeberekiah"]', '["n-pr-m"]', 'Jeberekjah, an Israelite Jeberechiah.', 'from 1288 and 3050; blessed of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7975B}/[H7974]', 'inflected', 'heb', 'שִׁלֹחַ', '["Shilôach"]', '["<the>/ Shiloah"]', '["n-pr-loc"]', 'Shiloach, a fountain of Jerusalem Shiloah, Siloah.', 'or (in imitation of 7974) שֶׁלַח; (Nehemiah 3:15), from 7971; rill;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4885}/[H7797]', 'inflected', 'heb', 'מָשׂוֹשׂ', '["mâsôws"]', '["and/ [the] joy of","and/ rejoicing"]', '["n-m"]', 'delight, concretely (the cause or object) or abstractly (the feeling) joy, mirth, rejoice.', 'from 7797;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6099}/[H6105]', 'inflected', 'heb', 'עָצוּם', '["ʻâtsûwm"]', '["<the>/ mighty"]', '["a"]', 'powerful (specifically, a paw); by implication, numerous feeble, great, mighty, must, strong.', 'or עָצֻם; passive participle of 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7227A}/[H7231]', 'inflected', 'heb', 'רַב', '["rab"]', '["and/ <the>/ many"]', '["a n-m"]', 'abundant (in quantity, size, age, number, rank, quality) (in) abound(-undance, -ant, -antly), captain, elder, enough, exceedingly, full, great(-ly, man, one), increase, long (enough, (time)), (do, have) many(-ifold, things, a time), (ship-)master, mighty, more, (too, very) much, multiply(-tude), officer, often(-times), plenteous, populous, prince, process (of time), suffice(-lent).', 'by contracted from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0650}/H9023/[H622]', 'inflected', 'heb', 'אָפִיק', '["ʼâphîyq"]', '["channels/ its"]', '["n-m"]', 'properly, containing, i.e. a tube; also a bed or valley of a stream; also a strong thing or a hero brook, channel, mighty, river, scale, stream, strong piece.', 'from 622;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4298}/[H5186]', 'lemma', 'heb', 'מֻטָּה', '["muṭṭâh"]', '["[the] spreading<s> of"]', '["n-f"]', 'expansion stretching out.', 'from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6005}\/[H5973]', 'inflected', 'heb', 'עִמָּנוּאֵל', '["ʻImmânûwʼêl"]', '["-el"]', '["n-pr-m"]', 'Immanuel, a type name of Isaiah''s son Immanuel.', 'from 5973 and with a pronominal suffix inserted; with us (is) God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2865}/[H2865]', 'inflected', 'heb', 'חָתַת', '["châthath"]', '["and/ be shattered"]', '["v"]', 'properly, to prostrate; hence, to break down, either (literally) by violence, or (figuratively) by confusion and fear abolish, affright, be (make) afraid, amaze, beat down, discourage, (cause to) dismay, go down, scare, terrify.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2393}/[H2391]', 'inflected', 'heb', 'חֶזְקָה', '["chezqâh"]', '["according to/ [the] strength of"]', '["n-f"]', 'prevailing power strength(-en self), (was) strong.', 'feminine of 2391;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3256}/H9030/[H3256]', 'inflected', 'heb', 'יָסַר', '["yâçar"]', '["and/ he will instruct/ me"]', '["v"]', 'to chastise, literally (with blows) or figuratively (with words); hence, to instruct bind, chasten, chastise, correct, instruct, punish, reform, reprove, sore, teach.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4172A}/H9023/[H3372]', 'inflected', 'heb', 'מוֹרָא', '["môwrâʼ"]', '["fear/ its"]', '["n-m"]', 'fear; by implication, a fearful thing or deed dread, (that ought to be) fear(-ed), terribleness, terror.', 'or מֹרָא; or מוֹרָהxlit môrâh corrected to môwrâh; (Psalm 9:20), from 3372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4172A}/H9026/[H3372]', 'inflected', 'heb', 'מוֹרָא', '["môwrâʼ"]', '["[will be] fear/ your"]', '["n-m"]', 'fear; by implication, a fearful thing or deed dread, (that ought to be) fear(-ed), terribleness, terror.', 'or מֹרָא; or מוֹרָהxlit môrâh corrected to môwrâh; (Psalm 9:20), from 3372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6206}/H9036/[H6206]', 'inflected', 'heb', 'עָרַץ', '["ʻârats"]', '["[the] [one whom] regard with awe/ you"]', '["v"]', 'to awe or (intransitive) to dread; hence, to harass be affrighted (afraid, dread, feared, terrified), break, dread, fear, oppress, prevail, shake terribly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6697H}/[H6696]', 'inflected', 'heb', 'צוּר', '["tsûwr"]', '["and/ <into>/ a rock of"]', '["n-m"]', 'properly, a cliff (or sharp rock, as compressed); generally, a rock or boulder; figuratively, a refuge; also an edge (as precipitous) edge, × (mighty) God (one), rock, × sharp, stone, × strength, × strong. See also 1049.', 'or צֻר; from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3369}/[H3369]', 'inflected', 'heb', 'יָקֹשׁ', '["yâqôsh"]', '["and/ they will be ensnared"]', '["v"]', 'to ensnare (literally or figuratively) fowler (lay a) snare.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3920}\/[H3920]', 'inflected', 'heb', 'לָכַד', '["lâkad"]', '["and/ they will be captured"]', '["v"]', 'to catch (in a net, trap or pit); generally, to capture or occupy; also to choose (by lot); figuratively, to cohere × at all, catch (self), be frozen, be holden, stick together, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8584}/[H5749]', 'lemma', 'heb', 'תְּעוּדָה', '["tᵉʻûwdâh"]', '["[the] testimony"]', '["n-f"]', 'attestation, i.e. a precept, usage testimony.', 'from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3928}/H9020/[H3925]', 'inflected', 'heb', 'לִמּוּד', '["limmûwd"]', '["among/ disciples/ my"]', '["a"]', 'instructed accustomed, disciple, learned, taught, used.', 'or לִמֻּד; from 3925;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6726}\/[H6725]', 'inflected', 'heb', 'צִיּוֹן', '["Tsîyôwn"]', '["Zion"]', '["n-pr-loc"]', 'Tsijon (as a permanent capital), a mountain of Jerusalem Zion.', 'the same (regularly) as 6725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6850}/[H6850]', 'inflected', 'heb', 'צָפַף', '["tsâphaph"]', '["who/ whisper"]', '["v"]', 'to coo or chirp (as a bird) chatter, peep, whisper.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1897}/[H1901]', 'inflected', 'heb', 'הָגָה', '["hâgâh"]', '["and/ who/ mutter"]', '["v"]', 'to murmur (in pleasure or anger); by implication, to ponder imagine, meditate, mourn, mutter, roar, × sore, speak, study, talk, utter.', 'a primitive root (compare 1901);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8584}/[H5749]', 'inflected', 'heb', 'תְּעוּדָה', '["tᵉʻûwdâh"]', '["and/ to/ [the] testimony"]', '["n-f"]', 'attestation, i.e. a precept, usage testimony.', 'from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4428G}/H9023/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["<in>/ king/ its"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0430G}/H9023/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["and/ <in>/ God/ its"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2825}/[H2821]', 'inflected', 'heb', 'חֲשֵׁכָה', '["chăshêkâh"]', '["and/ darkness"]', '["n-f"]', 'darkness; figuratively, misery darkness.', 'or חֲשֵׁיכָהxlit chăshêkâh corrected to chăshêykâh; from 2821;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4588}/[H5774]', 'lemma', 'heb', 'מָעוּף', '["mâʻûwph"]', '["gloom of"]', '["n-m"]', 'darkness dimness.', 'from 5774 in the sense of covering with shade (compare 4155);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6695B}/[H6693]', 'lemma', 'heb', 'צוֹק', '["tsôwq"]', '["distress"]', '["n-m n-f"]', 'a strait, i.e. (figuratively) distress anguish, × troublous.', 'or (feminine) צוּקָה; from 6693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4155}/[H5774]', 'lemma', 'heb', 'מוּעָף', '["mûwʻâph"]', '["gloom"]', '["n-m"]', 'properly, covered, i.e. dark; abstractly, obscurity, i.e. distress dimness.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0776G>/H9011', 'inflected', 'heb', 'וארצה', '["ve./''Ar.tza/h"]', '["and/ [the] land of/ <towards>"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1551}/[H1550]', 'lemma', 'heb', 'גָּלִיל', '["Gâlîyl"]', '["Galilee of"]', '["n-pr-loc"]', 'Galil (as a special circuit) in the North of Palestine Galilee.', 'or (prolonged) גָּלִילָה; the same as 1550; a circle (with the article);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8057}/[H8056]', 'inflected', 'heb', 'שִׂמְחָה', '["simchâh"]', '["like/ [the] rejoicing"]', '["n-f"]', 'blithesomeness or glee, (religious or festival) × exceeding(-ly), gladness, joy(-fulness), mirth, pleasure, rejoice(-ing).', 'from 8056;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2505A}/H9048/[H2505]', 'inflected', 'heb', 'חָלַק', '["châlaq"]', '["when/ divide/ they"]', '["v"]', 'to be smooth (figuratively); by implication (as smooth stones were used for lots) to apportion or separate deal, distribute, divide, flatter, give, (have, im-) part(-ner), take away a portion, receive, separate self, (be) smooth(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5448}/H9023/[H5445]', 'inflected', 'heb', 'סֹבֶל', '["çôbel"]', '["burden/ its"]', '["n-m"]', 'load (figuratively) burden.', '(only in the form סֻבָּל; from 5445;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5430}/[H5431]', 'lemma', 'heb', 'סְאוֹן', '["çᵉʼôwn"]', '["boot"]', '["n-m"]', 'perhaps a military boot (as a protection from mud) battle.', 'from 5431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5431}/[H5430]', 'lemma', 'heb', 'סָאַן', '["çâʼan"]', '["[which] marches"]', '["v"]', 'to shoe, i.e. (active participle) a soldier shod warrior.', 'a primitive root; to be miry; used only as denominative from 5430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3980}/[H398]', 'lemma', 'heb', 'מַאֲכֹלֶת', '["maʼăkôleth"]', '["fuel of"]', '["n-f"]', 'something eaten (by fire), i.e. fuel fuel.', 'from 398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4951}/[H8280]', 'inflected', 'heb', 'מִשְׂרָה', '["misrâh"]', '["the/ dominion"]', '["n-f"]', 'empire government.', 'from 8280;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0001G}/{H5703}/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["father of/ perpetuity"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4766}/[H7235]', 'inflected', 'heb', 'מַרְבֶה', '["marbeh"]', '["to/ [the] increase of"]', '["n-m"]', 'properly, increasing; as noun, greatness, or (adverbially) greatly great, increase.', 'from 7235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3559H}/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["to/ establish","to/ prepare"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5582}/H9034/[H5582]', 'inflected', 'heb', 'סָעַד', '["çâʻad"]', '["and/ to/ sustain/ it"]', '["v"]', 'to support (mostly figurative) comfort, establish, hold up, refresh self, strengthen, be upholden.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1433}/[H1431]', 'inflected', 'heb', 'גֹּדֶל', '["gôdel"]', '["and/ in/ greatness","and/ with/ greatness of"]', '["n-m"]', 'magnitude (literally or figuratively) greatness, stout(-ness).', 'from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1496}/[H1491]', 'inflected', 'heb', 'גָּזִית', '["gâzîyth"]', '["and/ hewn [stone]"]', '["n-f"]', 'something cut, i.e. dressed stone hewed, hewn stone, wrought.', 'from 1491;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8256>', 'opaque', 'heb', 'שִׁקְמָה', '["shiqmâh"]', '["sycamores"]', '["n-f"]', 'a sycamore (usually the tree) sycamore (fruit, tree).', 'or (feminine) שִׁקְמָה; of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0268}/[H299]', 'inflected', 'heb', 'אָחוֹר', '["ʼâchôwr"]', '["from/ [the] west"]', '["n-m"]', 'the hinder part; hence (adverb) behind, backward; also (as facing north) the West after(-ward), back (part, -side, -ward), hereafter, (be-) hind(-er part), time to come, without.', 'or (shortened) אָחֹר ; from 299;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5221}/H9033/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["the/ [one who] struck/ it"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1875}\/[H1875]', 'inflected', 'heb', 'דָּרַשׁ', '["dârash"]', '["I will require","they have sought"]', '["v"]', 'properly, to tread or frequent; usually to follow (for pursuit or search); by implication, to seek or ask; specifically to worship ask, × at all, care for, × diligently, inquire, make inquisition, (necro-) mancer, question, require, search, seek (for, out), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2180}/[H2179]', 'inflected', 'heb', 'זָנָב', '["zânâb"]', '["and/ tail"]', '["n-m"]', 'the tail (literally or figuratively) tail.', 'from 2179 (in the original sense of flapping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3712}/[H3709]', 'lemma', 'heb', 'כִּפָּה', '["kippâh"]', '["palm branch"]', '["n-f"]', 'a leaf of a palmtree branch.', 'feminine of 3709;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0833}/H9023/[H833]', 'inflected', 'heb', 'אָשַׁר', '["ʼâshar"]', '["and/ [those who] were guided by/ him"]', '["v"]', 'to be straight (used in the widest sense, especially to be level, right, happy); figuratively, to go forward, be honest, prosper (call, be) bless(-ed, happy), go, guide, lead, relieve.', 'or אָשֵׁר; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3490>/H9023', 'opaque', 'heb', 'יָתוֹם', '["yâthôwm"]', '["fatherless ones/ its"]', '["n-m"]', 'a bereaved person fatherless (child), orphan.', 'from an unused root meaning to be lonely;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0490}/H9023/[H488]', 'inflected', 'heb', 'אַלְמָנָה', '["ʼalmânâh"]', '["widows/ its"]', '["n-f"]', 'a widow; also a desolate place desolate house (palace), widow.', 'feminine of 488;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7564}/[H7562]', 'lemma', 'heb', 'רִשְׁעָה', '["rishʻâh"]', '["<of> wickedness","wickedness"]', '["n-f"]', 'wrong (especially moral) fault, wickedly(-ness).', 'feminine of 7562;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0055}/[H55]', 'inflected', 'heb', 'אָבַךְ', '["ʼâbak"]', '["and/ they have swirled"]', '["v"]', 'probably to coil upward mount up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6272}/[H6272]', 'lemma', 'heb', 'עָתַם', '["ʻâtham"]', '["it has been scorched"]', '["v"]', 'probably to glow, i.e. (figuratively) be desolated be darkened.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3980}/[H398]', 'inflected', 'heb', 'מַאֲכֹלֶת', '["maʼăkôleth"]', '["like/ fuel of"]', '["n-f"]', 'something eaten (by fire), i.e. fuel fuel.', 'from 398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5186}\/[H5186]', 'inflected', 'heb', 'נָטָה', '["nâṭâh"]', '["[is] stretched out"]', '["v"]', 'to stretch or spread out; by implication, to bend away (including moral deflection); used in a great variety of application (as follows) afternoon, apply, bow (down, -ing), carry aside, decline, deliver, extend, go down, be gone, incline, intend, lay, let down, offer, outstretched, overthrown, pervert, pitch, prolong, put away, shew, spread (out), stretch (forth, out), take (aside), turn (aside, away), wrest, cause to yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2710}/[H2710]', 'inflected', 'heb', 'חָקַק', '["châqaq"]', '["those/ [who] decree"]', '["v"]', 'properly, to hack, i.e. engrave (Judges 5:14, to be a scribe simply); by implication, to enact (laws being cut in stone or metal tablets in primitive times) or (gen.) prescribe appoint, decree, governor, grave, lawgiver, note, pourtray, print, set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1779}/[H1777]', 'inflected', 'heb', 'דִּין', '["dîyn"]', '["from/ judgment"]', '["n-m"]', 'judgement (the suit, justice, sentence or tribunal); by implication also strife cause, judgement, plea, strife.', 'or (Job 19:29) דּוּן; from 1777;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1497}/[H1497]', 'inflected', 'heb', 'גָּזַל', '["gâzal"]', '["and/ to/ take away"]', '["v"]', 'to pluck off; specifically to flay, strip or rob catch, consume, exercise (robbery), pluck (off), rob, spoil, take away (by force, violence), tear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H7722B>', 'inflected', 'heb', 'ולשואה', '["u./le./sho.''Ah"]', '["and/ to/ [the] devastation"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3519}/H9026/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["abundance/ your"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8478I}/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["and/ under"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2195}/H9020/[H2194]', 'inflected', 'heb', 'זַעַם', '["zaʻam"]', '["indignation/ my"]', '["n-m"]', 'strictly froth at the mouth, i.e. (figuratively) fury (especially of God''s displeasure with sin) angry, indignation, rage.', 'from 2194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5678}/H9020/[H5676]', 'inflected', 'heb', 'עֶבְרָה', '["ʻebrâh"]', '["wrath/ my"]', '["n-f"]', 'an outburst of passion anger, rage, wrath.', 'feminine of 5676;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7997B}/[H7997]', 'inflected', 'heb', 'שָׁלַל', '["shâlal"]', '["to/ plunder"]', '["v"]', 'to drop or strip; by implication, to plunder let fall, make self a prey, × of purpose, (make a, (take)) spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0962}/[H962]', 'inflected', 'heb', 'בָּזַז', '["bâzaz"]', '["and/ to/ take as spoil"]', '["v"]', 'to plunder catch, gather, (take) for a prey, rob(-ber), spoil, take (away, spoil), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0957}/[H962]', 'lemma', 'heb', 'בַּז', '["baz"]', '["spoil"]', '["n-m"]', 'plunder booty, prey, spoil(-ed).', 'from 962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7760A}/H9033/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ to/ make/ it"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4823}/[H7429]', 'lemma', 'heb', 'מִרְמָס', '["mirmâç"]', '["[the] trampling place of","a trampling place","trampling"]', '["n-m"]', 'abasement (the act or the thing) tread (down) -ing, (to be) trodden (down) under foot.', 'from 7429;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3772I}/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["and/ to/ cut off"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8269}/H9020/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["[are] commanders/ my"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3751}/[H3751]', 'inflected', 'heb', 'כַּרְכְּמִישׁ', '["Karkᵉmîysh"]', '["like/ Carchemish"]', '["n-pr-loc"]', 'Karkemish, a place in Syria Carchemish.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3641B}/[H3641]', 'lemma', 'heb', 'כַּלְנֶה', '["Kalneh"]', '["Calneh","[is] Calneh"]', '["n-pr-loc"]', 'Calneh or Calno, a place in the Assyrian empire Calneh, Calno. Compare 3656.', 'or כַּלְנֵה; also כַּלְנוֹ; of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0774}/[H7502]', 'inflected', 'heb', 'אַרְפָּד', '["ʼArpâd"]', '["like/ Arpad"]', '["n-pr-loc"]', 'Arpad, a place in Syria Arpad, Arphad.', 'from 7502; spread out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H1834>', 'inflected', 'heb', 'כדמשק', '["khe./da.Me.sek"]', '["like/ Damascus"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H8111}/[H8104]', 'inflected', 'heb', 'שֹׁמְרוֹן', '["Shômᵉrôwn"]', '["and/ from/ Samaria","and/ more than/ Samaria"]', '["n-pr-loc"]', 'Shomeron, a place in Palestine Samaria.', 'from the active participle of 8104; watch-station;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0457}/H9024/[H408]', 'inflected', 'heb', 'אֱלִיל', '["ʼĕlîyl"]', '["and/ to/ idols/ its"]', '["a-m"]', 'good for nothing, by analogy vain or vanity; specifically an idol idol, no value, thing of nought.', 'apparently from 408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6091}/H9024\/[H6087]', 'inflected', 'heb', 'עָצָב', '["ʻâtsâb"]', '["and/ to/ images/ its"]', '["n-m"]', 'an (idolatrous) image idol, image.', 'from 6087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1214H}/[H1214]', 'lemma', 'heb', 'בָּצַע', '["bâtsaʻ"]', '["he will finish","they will finish [it]"]', '["v"]', 'to break off, i.e. (usually) plunder; figuratively, to finish, or (intransitively) stop (be) covet(-ous), cut (off), finish, fulfill, gain (greedily), get, be given to (covetousness), greedy, perform, be wounded.', 'a primitive root');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2451}/H9020/[H2449]', 'inflected', 'heb', 'חׇכְמָה', '["chokmâh"]', '["and/ by/ skill/ my"]', '["n-f"]', 'wisdom (in a good sense) skilful, wisdom, wisely, wit.', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6259}/H9028/[H6257]', 'inflected', 'heb', 'עָתוּד', '["ʻâthûwd"]', '["and/ provisions/ their"]', '["a"]', 'prepared ready.', 'passive participle of 6257;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0047G}/[H46]', 'inflected', 'heb', 'אַבִּיר', '["ʼabbîyr"]', '["like/ a mighty [man]"]', '["a-m"]', 'angel, bull, chiefest, mighty (one), stout(-hearted), strong (one), valiant.', 'for 46');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7064}/[H7077]', 'inflected', 'heb', 'קֵן', '["qên"]', '["like <the>/ nest"]', '["n-m"]', 'a nest (as fixed), sometimes including the nestlings; figuratively, a chamber or dwelling nest, room.', 'contracted from 7077;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2428H}/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["<to>/ [the] wealth of"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0622}/[H622]', 'inflected', 'heb', 'אָסַף', '["ʼâçaph"]', '["and/ as/ gathers"]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6475}/[H6475]', 'inflected', 'heb', 'פָּצָה', '["pâtsâh"]', '["and/ opening"]', '["v"]', 'to rend, i.e. open (especially the mouth) deliver, gape, open, rid, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6850}/[H6850]', 'inflected', 'heb', 'צָפַף', '["tsâphaph"]', '["and/ chirping"]', '["v"]', 'to coo or chirp (as a bird) chatter, peep, whisper.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H6286A}/[H6288]', 'inflected', 'heb', 'פָּאַר', '["pâʼar"]', '["¿/ does it glorify itself"]', '["v"]', 'to gleam, i.e. (causatively) embellish; figuratively, to boast; also to explain (i.e. make clear) oneself; to shake a tree beautify, boast self, go over the boughs, glorify (self), glory, vaunt self.', 'a primitive root; also denominative from 6288,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1631}/[H1629]', 'inflected', 'heb', 'גַּרְזֶן', '["garzen"]', '["the/ axe"]', '["n-m"]', 'an axe ax.', 'from 1629;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2672}/[H2672]', 'inflected', 'heb', 'חָצַב', '["châtsab"]', '["the/ [one who] cuts","who/ cut in pieces"]', '["v"]', 'to cut or carve (wood, stone or other material); by implication, to hew, split, square, quarry, engrave cut, dig, divide, grave, hew (out, -er), made, mason.', 'or חָצֵב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H4883>', 'inflected', 'heb', 'המשור', '["ha./ma.sOr"]', '["the/ saw"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5130B}/[H5130]', 'inflected', 'heb', 'נוּף', '["nûwph"]', '["as/ wields"]', '["v"]', 'to quiver (i.e. vibrate up and down, or rock to and fro); used in a great variety of applications (including sprinkling, beckoning, rubbing, bastinadoing, sawing, waving, etc.) lift up, move, offer, perfume, send, shake, sift, strike, wave.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7311A}/H9033/[H7311]', 'inflected', 'heb', 'רוּם', '["rûwm"]', '["[those who] lift/ it","it raised up/ it"]', '["v"]', 'to be high actively, to rise or raise (in various applications, literally or figuratively) bring up, exalt (self), extol, give, go up, haughty, heave (up), (be, lift up on, make on, set up on, too) high(-er, one), hold up, levy, lift(-er) up, (be) lofty, (× a-) loud, mount up, offer (up), presumptuously, (be) promote(-ion), proud, set up, tall(-er), take (away, off, up), breed worms.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4924B}/H9023/[H8080]', 'inflected', 'heb', 'מַשְׁמָן', '["mashmân"]', '["on/ fat ones/ his"]', '["n-m"]', 'fat, i.e. (literally and abstractly) fatness; but usually (figuratively and concretely) a rich dish, a fertile field, a robust man fat (one, -ness, -test, -test place).', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3350}/[H3344]', 'lemma', 'heb', 'יְקוֹד', '["yᵉqôwd"]', '["a burning"]', '["n-m"]', 'a burning burning.', 'from 3344;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3350}/[H3344]', 'inflected', 'heb', 'יְקוֹד', '["yᵉqôwd"]', '["like/ [the] burning of"]', '["n-m"]', 'a burning burning.', 'from 3344;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6918G}/H9023/[H6942]', 'inflected', 'heb', 'קָדוֹשׁ', '["qâdôwsh"]', '["and/ holy [one]/ its"]', '["a"]', 'sacred (ceremonially or morally); (as noun) God (by eminence), an angel, a saint, a sanctuary holy (One), saint.', 'or קָדֹשׁ; from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3852}/[H3851]', 'inflected', 'heb', 'לֶהָבָה', '["lehâbâh"]', '["<into>/ a flame"]', '["n-f"]', 'flame(-ming), head (of a spear).', 'or לַהֶבֶת; feminine of 3851, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7898}/H9023/[H7896]', 'inflected', 'heb', 'שַׁיִת', '["shayith"]', '["bush[es]/ his"]', '["n-m"]', 'scrub or trash, i.e. wild growth of weeds or briers (as if put on the field) thorns.', 'from 7896;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8068}/H9023/[H8104]', 'inflected', 'heb', 'שָׁמִיר', '["shâmîyr"]', '["and/ thorn[s]/ his"]', '["n-m"]', 'a thorn; also (from its keenness for scratching) a gem, probably the diamond adamant (stone), brier, diamond.', 'from 8104 in the original sense of pricking;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3293A>/H9023', 'opaque', 'heb', 'יַעַר', '["yaʻar"]', '["forest/ his"]', '["n-m"]', 'a copse of bushes; hence, a forest; hence, honey in the comb (as hived in trees) (honey-) comb, forest, wood.', 'from an unused root probably meaning to thicken with verdure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3759}/H9023/[H3754]', 'inflected', 'heb', 'כַּרְמֶל', '["karmel"]', '["and/ orchard/ his"]', '["n-m"]', 'a planted field (garden, orchard, vineyard or park); by implication, garden produce full (green) ears (of corn), fruitful field (place), plentiful (field).', 'from 3754;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5315G}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["from/ breath"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5263}/[H5263]', 'lemma', 'heb', 'נָסַס', '["nâçaç"]', '["[one who] is sick"]', '["v"]', 'to wane, i.e. be sick faint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3789}/H9038\/[H3789]', 'inflected', 'heb', 'כָּתַב', '["kâthab"]', '["he will record/ them"]', '["v"]', 'to grave, by implication, to write (describe, inscribe, prescribe, subscribe) describe, record, prescribe, subscribe, write(-ing, -ten).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8172}/[H8172]', 'inflected', 'heb', 'שָׁעַן', '["shâʻan"]', '["to/ depend"]', '["v"]', 'to support one''s self lean, lie, rely, rest (on, self), stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3631}/[H3615]', 'lemma', 'heb', 'כִּלָּיוֹן', '["killâyôwn"]', '["annihilation"]', '["n-m"]', 'pining, destruction consumption, failing.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2782}/[H2782]', 'inflected', 'heb', 'חָרַץ', '["chârats"]', '["and/ [what] has been decided"]', '["v"]', 'properly, to point sharply, i.e. (literally) to wound; figuratively, to be alert, to decide bestir self, decide, decree, determine, maim, move.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0804G}/[H833]', 'inflected', 'heb', 'אַשּׁוּר', '["ʼAshshûwr"]', '["from/ Assyria"]', '["n-pr-m n-pr-loc"]', 'Ashshur, the second son of Shem; also his descendants and the country occupied by them (i.e. Assyria), its region and its empire Asshur, Assur, Assyria, Assyrians. See 838.', 'or אַשֻּׁר; apparently from 833 (in the sense of successful);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4294G}/H9023/[H5186]', 'inflected', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["and/ staff/ his","and/ staff/ its"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4213}/[H2191]', 'lemma', 'heb', 'מִזְעָר', '["mizʻâr"]', '["a little","smallness"]', '["n-m"]', 'fewness; by implication, as superlative diminutiveness few, × very.', 'from the same as 2191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2195}/[H2194]', 'lemma', 'heb', 'זַעַם', '["zaʻam"]', '["indignation"]', '["n-m"]', 'strictly froth at the mouth, i.e. (figuratively) fury (especially of God''s displeasure with sin) angry, indignation, rage.', 'from 2194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0639G}/H9020/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["and/ anger/ my"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8399}/H9028/[H1086]', 'inflected', 'heb', 'תַּבְלִית', '["tablîyth"]', '["destruction/ their"]', '["n-f"]', 'consumption destruction.', 'from 1086;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4347}/[H5221]', 'inflected', 'heb', 'מַכָּה', '["makkâh"]', '["like/ [the] defeat of"]', '["n-f"]', 'a blow (in 2 Chronicles 2:10, of the flail); by implication, a wound; figuratively, carnage, also pestilence beaten, blow, plague, slaughter, smote, × sore, stripe, stroke, wound(-ed).', 'or (masculine) מַכֶּה; (plural only) from 5221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5375R}/H9033/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ he will raise/ it"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7926}/H9021/[H7925]', 'inflected', 'heb', 'שְׁכֶם', '["shᵉkem"]', '["shoulder/ your"]', '["n-m"]', 'the neck (between the shoulders) as the place of burdens; figuratively, the spur of a hill back, × consent, portion, shoulder.', 'from 7925;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5923}/H9023/[H5953]', 'inflected', 'heb', 'עֹל', '["ʻôl"]', '["and/ yoke/ its"]', '["n-m"]', 'a yoke (as imposed on the neck), literally or figuratively yoke.', 'or עוֹל; from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5857G}/[H5856]', 'lemma', 'heb', 'עַי', '["ʻAy"]', '["Aiath"]', '["n-pr-loc"]', 'Ai, Aja or Ajath, a place in Palestine Ai, Aija, Aijath, Hai.', 'or (feminine) עַיָּא; (Nehemiah 11:31), or עַיָּת; (Isaiah 10:28), for 5856;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4363}/[H3647]', 'inflected', 'heb', 'מִכְמָס', '["Mikmâç"]', '["to/ Micmash"]', '["n-pr-loc"]', 'Mikmas or Mikmash, a place in Palestine Mikmas, Mikmash.', '(Ezra 2:2 or מִכְמָשׁ; or מִכְמַשׁ; (Nehemiah 11:31), from 3647; hidden;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6485L}/[H6485]', 'lemma', 'heb', 'פָּקַד', '["pâqad"]', '["I have been caused to miss","he deposits","they had deposited"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1554}/[H1530]', 'lemma', 'heb', 'גַּלִּים', '["Gallîym"]', '["Gallim"]', '["n-pr-loc"]', 'Gallim, a place in Palestine Gallim.', 'plural of 1530; springs;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3919C}/[H3918]', 'lemma', 'heb', 'לַיִשׁ', '["Layish"]', '["O Laishah"]', '["n-pr-m n-pr-loc"]', 'Laish, the name of two places in Palestine Laish. Compare 3889.', 'the same as 3918;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4088}/[H4087]', 'lemma', 'heb', 'מַדְמֵנָה', '["Madmênâh"]', '["Madmenah"]', '["n-pr-loc"]', 'Madmenah, a place in Palestine Madmenah.', 'the same as 4087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1374}/[H1356]', 'inflected', 'heb', 'גֵּבִים', '["Gêbîym"]', '["<the>/ Gebim"]', '["n-pr-loc"]', 'Gebim, a place in Palestine Gebim.', 'plural of 1356; cisterns;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5586}/[H5585]', 'lemma', 'heb', 'סָעַף', '["çâʻaph"]', '["[is] about to lop off"]', '["v"]', 'to disbranch (a tree) top.', 'a primitive root; properly, to divide up; but used only as denominative from 5585,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6288B}/[H6286]', 'lemma', 'heb', 'פְּאֹרָה', '["pᵉʼôrâh"]', '["bough[s]"]', '["n-f"]', 'properly, ornamentation, i.e. (plural) foliage (including the limbs) as bright green bough, branch, sprig.', 'or פֹּרָאה; or פֻּארָה; from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4637}/[H6206]', 'inflected', 'heb', 'מַעֲרָצָה', '["maʻărâtsâh"]', '["with/ a crash"]', '["n-f"]', 'violence terror.', 'from 6206;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6967}/[H6965]', 'inflected', 'heb', 'קוֹמָה', '["qôwmâh"]', '["<the>/ height"]', '["n-f"]', 'height × along, height, high, stature, tall.', 'from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1364}/[H1361]', 'inflected', 'heb', 'גָּבֹהַּ', '["gâbôahh"]', '["and/ the/ exalted","and/ the/ high [one]","and/ the/ tall [ones]"]', '["a"]', 'elevated (or elated), powerful, arrogant haughty, height, high(-er), lofty, proud, × exceeding proudly.', 'or גָּבוֹהַּ; (fully) from 1361;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5362A}/[H5362]', 'inflected', 'heb', 'נָקַף', '["nâqaph"]', '["and/ he will cut down"]', '["v"]', 'to strike with more or less violence (beat, fell, corrode); by implication (of attack) to knock together, i.e. surround or circulate compass (about, -ing), cut down, destroy, go round (about), inclose, round.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5442}/[H5440]', 'lemma', 'heb', 'סְבָךְ', '["çᵉbâk"]', '["[the] thickets of"]', '["n-m"]', 'a copse thick(-et).', 'from 5440,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0117}/[H142]', 'inflected', 'heb', 'אַדִּיר', '["ʼaddîyr"]', '["by/ a mighty [one]"]', '["a"]', 'wide or (generally) large; figuratively, powerful excellent, famous, gallant, glorious, goodly, lordly, mighty(-ier one), noble, principal, worthy.', 'from 142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5307J}\/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["it will fall","they will fall"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H1503>', 'inflected', 'heb', 'מגזע', '["mi./Ge.za''"]', '["from/ [the] rootstock of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5342}/[H5341]', 'inflected', 'heb', 'נֵצֶר', '["nêtser"]', '["and/ a branch"]', '["n-m"]', 'a shoot; figuratively, a descendant branch.', 'from 5341 in the sense of greenness as a striking color;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8328}/H9023/[H8327]', 'inflected', 'heb', 'שֶׁרֶשׁ', '["sheresh"]', '["from/ roots/ his"]', '["n-m"]', 'a root (literally or figuratively) bottom, deep, heel, root.', 'from 8327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7306}/H9043/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["and/ delighting/ he"]', '["v"]', 'properly, to blow, i.e. breathe; only (literally) to smell or (by implication, perceive (figuratively, to anticipate, enjoy) accept, smell, × touch, make of quick understanding.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4926}/[H8085]', 'inflected', 'heb', 'מִשְׁמָע', '["mishmâʻ"]', '["to/ [the] hearing of"]', '["n-m"]', 'a report hearing.', 'from 8085;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6035}/[H6041]', 'inflected', 'heb', 'עָנָו', '["ʻânâv"]', '["for/ [the] humble [people] of"]', '["n-m"]', 'depressed (figuratively), in mind (gentle) or circumstances (needy, especially saintly) humble, lowly, meek, poor. Compare 6041.', 'or (by intermixture with 6041) עָנָיו; from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0530}/[H529]', 'inflected', 'heb', 'אֱמוּנָה', '["ʼĕmûwnâh"]', '["and/ <the>/ faithfulness"]', '["n-f"]', 'literally firmness; figuratively security; morally fidelity faith(-ful, -ly, -ness, (man)), set office, stability, steady, truly, truth, verily.', 'or (shortened) אֱמֻנָה; feminine of 529;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5246>', 'inflected', 'heb', 'ונמר', '["ve./na.Mer"]', '["and/ a leopard","and/ leopard"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3715A}/[H3722]', 'inflected', 'heb', 'כְּפִיר', '["kᵉphîyr"]', '["and/ young lion"]', '["n-m"]', 'a village (as covered in by walls); also a young lion (perhaps as covered with a mane) (young) lion, village. Compare 3723.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6510}/[H6499]', 'inflected', 'heb', 'פָּרָה', '["pârâh"]', '["and/ cow"]', '["n-f"]', 'a heifer cow, heifer, kine.', 'feminine of 6499;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0738B}/[H717]', 'inflected', 'heb', 'אֲרִי', '["ʼărîy"]', '["and/ [the] lion"]', '["n-m"]', 'a lion (young) lion, pierce (from the margin).', 'or (prolonged) אַרְיֵה; from 717 (in the sense of violence);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8173B}/[H8173]', 'inflected', 'heb', 'שָׁעַע', '["shâʻaʻ"]', '["and/ he will play"]', '["v"]', '(in a good acceptation) to look upon (with complacency), i.e. fondle, please or amuse (self); (in a bad one) to look about (in dismay), i.e. stare cry (out) (by confusion with 7768), dandle, delight (self), play, shut.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2352>', 'opaque', 'heb', 'חוּר', '["chûwr"]', '["[the] hole of"]', '["n-m"]', 'the crevice of a serpent; the cell of a prison hole.', 'or (shortened) חֻר; from an unused root probably meaning to bore;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3975}/[H215]', 'lemma', 'heb', 'מְאוּרָה', '["mᵉʼûwrâh"]', '["[the] nest of"]', '["n-f"]', 'something lighted, i.e. an aperture; by implication, a crevice or hole (of a serpent) den.', 'feminine passive participle of 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6848B>', 'opaque', 'heb', 'צֶפַע', '["tsephaʻ"]', '["a viper","vipers"]', '["n-m"]', 'a viper (as thrusting out the tongue, i.e. hissing) adder, cockatrice.', 'from an unused root meaning to extrude;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1911}/[H3034]', 'lemma', 'heb', 'הָדָה', '["hâdâh"]', '["he will put out"]', '["v"]', 'to stretch forth the hand put.', 'a primitive root (compare 3034);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3680}\/[H3680]', 'inflected', 'heb', 'כָּסָה', '["kâçâh"]', '["[which] cover","to be covered"]', '["v"]', 'properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4496H}/H9023/[H4495]', 'inflected', 'heb', 'מְנוּחָה', '["mᵉnûwchâh"]', '["[is] resting place/ its","resting place/ his"]', '["n-f"]', 'repose or (adverbially) peacefully; figuratively, consolation (specifically, matrimony); hence (concretely) an abode comfortable, ease, quiet, rest(-ing place), still.', 'or מְנֻחָה; feminine of 4495;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3519}\/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["glory"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4714G}/[H4693]', 'inflected', 'heb', 'מִצְרַיִם', '["Mitsrayim"]', '["and/ from/ Egypt"]', '["n-pr"]', 'Mitsrajim, i.e. Upper and Lower Egypt Egypt, Egyptians, Mizraim.', 'dual of 4693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6624}/[H6624]', 'inflected', 'heb', 'פַּתְרוֹס', '["Pathrôwç"]', '["and/ from/ Pathros"]', '["n-pr-loc"]', 'Pathros, a part of Egypt Pathros.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H3568A>', 'inflected', 'heb', 'ומכוש', '["u./mi./Kush"]', '["and/ from/ Cush"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5867A}/[H5956]', 'inflected', 'heb', 'עֵילָם', '["ʻÊylâm"]', '["and/ from/ Elam"]', '["n-pr-m n-pr-loc"]', 'Elam, a son of Shem and his descendants, with their country; also of six Israelites Elam.', 'or עוֹלָם; (Ezra 10:2; Jeremiah 49:36), probably from 5956; hidden, i.e. distant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H8152}/[H8152]', 'inflected', 'heb', 'שִׁנְעָר', '["Shinʻâr"]', '["and/ from/ Shinar"]', '["n-pr-loc"]', 'Shinar, a plain in Babylonia Shinar.', 'probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0339}/[H183]', 'inflected', 'heb', 'אִי', '["ʼîy"]', '["and/ from/ [the] islands of"]', '["n-m"]', 'properly, a habitable spot (as desirable); dry land, a coast, an island country, isle, island.', 'from 183;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5310B}/[H5310]', 'inflected', 'heb', 'נָפַץ', '["nâphats"]', '["and/ [the] scattered [women] of"]', '["v"]', 'to dash to pieces, or scatter be beaten in sunder, break (in pieces), broken, dash (in pieces), cause to be discharged, dispersed, be overspread, scatter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0702}/[H7251]', 'inflected', 'heb', 'אַרְבַּע', '["ʼarbaʻ"]', '["from/ [the] four","from/ four"]', '["n"]', 'four four.', 'masculine אַרְבָּעָה; from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6887D}/[H6887]', 'inflected', 'heb', 'צָרַר', '["tsârar"]', '["and/ [the] opposing of"]', '["v"]', 'to cramp, literally or figuratively, transitive or intransitive adversary, (be in) afflict(-ion), beseige, bind (up), (be in, bring) distress, enemy, narrower, oppress, pangs, shut up, be in a strait (trouble), vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4916B}/[H7971]', 'lemma', 'heb', 'מִשְׁלוֹחַ', '["mishlôwach"]', '["[will be] [the] stretching out of"]', '["n-m"]', 'a sending out, i.e. (abstractly) presentation (favorable), or seizure (unfavorable); also (concretely) a place of dismissal, or a business to be discharged to lay, to put, sending (forth), to set.', 'or מִשְׁלֹחַ; also מִשְׁלָח; from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4928}/H9028/[H4926]', 'inflected', 'heb', 'מִשְׁמַעַת', '["mishmaʻath"]', '["[will be] subjects/ their"]', '["n-f"]', 'audience, i.e. the royal court; also obedience, i.e. (concretely) a subject bidding, guard, obey.', 'feminine of 4926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4714I}/[H4693]', 'lemma', 'heb', 'מִצְרַיִם', '["Mitsrayim"]', '["Egypt"]', '["n-pr"]', 'Mitsrajim, i.e. Upper and Lower Egypt Egypt, Egyptians, Mizraim.', 'dual of 4693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5868B}/[H5868]', 'inflected', 'heb', 'עֲיָם', '["ʻăyâm"]', '["with/ [the] heat of"]', '["n-m n-f"]', 'probably meaning strength mighty.', 'of doubtful origin and authenticity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7605}/[H7604]', 'inflected', 'heb', 'שְׁאָר', '["shᵉʼâr"]', '["for/ [the] remnant of","to/ [the] remnant of"]', '["n-m"]', 'a remainder × other, remnant, residue, rest.', 'from 7604;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5927G}/H9043/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["went up/ it"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4599}/[H5869]', 'inflected', 'heb', 'מַעְיָן', '["maʻyân"]', '["from/ [the] springs of"]', '["n-m"]', 'a fountain (also collectively), figuratively, a source (of satisfaction) fountain, spring, well.', 'or מַעְיְנוֹ; (Psalm 114:8), or (feminine) מַעְיָנָה; from 5869 (as a denominative in the sense of a spring);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4853B}/[H5375]', 'lemma', 'heb', 'מַשָּׂא', '["massâʼ"]', '["[is] [the] burden of","[the] burden of","[the] oracle","[the] oracle of","burden","oracles of"]', '["n-m n-pr-m"]', 'a burden; specifically, tribute, or (abstractly) porterage; figuratively, an utterance, chiefly a doom, especially singing; mental, desire burden, carry away, prophecy, × they set, song, tribute.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8192}/[H8192]', 'lemma', 'heb', 'שָׁפָה', '["shâphâh"]', '["swept bare"]', '["v"]', 'to abrade, i.e. bare high, stick out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6942G}/H9020/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["to/ consecrated [ones]/ my"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1368}/H9020/[H1397]', 'inflected', 'heb', 'גִּבּוֹר', '["gibbôwr"]', '["warriors/ my"]', '["a"]', 'powerful; by implication, warrior, tyrant champion, chief, × excel, giant, man, mighty (man, one), strong (man), valiant man.', 'or גִּבֹּר; (shortened) intensive from the same as 1397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0639G}/H9020/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["to/ anger/ my"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5947}/[H5937]', 'lemma', 'heb', 'עַלִּיז', '["ʻallîyz"]', '["[the] exultant [ones] of","jubilant","jubilant [city]","jubilant [people]"]', '["a"]', 'exultant joyous, (that) rejoice(-ing)', 'from 5937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1346}/H9020/[H1342]', 'inflected', 'heb', 'גַּאֲוָה', '["gaʼăvâh"]', '["pride/ my"]', '["n-f"]', 'arrogance or majesty; by implication, (concretely) ornament excellency, haughtiness, highness, pride, proudly, swelling.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2195}/H9023/[H2194]', 'inflected', 'heb', 'זַעַם', '["zaʻam"]', '["indignation/ his"]', '["n-m"]', 'strictly froth at the mouth, i.e. (figuratively) fury (especially of God''s displeasure with sin) angry, indignation, rage.', 'from 2194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2254B}/[H2254]', 'inflected', 'heb', 'חָבַל', '["châbal"]', '["to/ destroy","to/ ruin"]', '["v"]', 'to wind tightly (as a rope), i.e. to bind; specifically, by a pledge; figuratively, to pervert, destroy; also to writhe in pain (especially of parturition) × at all, band, bring forth, (deal) corrupt(-ly), destroy, offend, lay to (take a) pledge, spoil, travail, × very, withhold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3213}/[H3213]', 'lemma', 'heb', 'יָלַל', '["yâlal"]', '["I will wail","it is wailing","it will wail","they wail","they will wail","wail","you will wail"]', '["v"]', 'to howl (with a wailing tone) or yell (with a boisterous one) (make to) howl, be howling.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7701}/[H7736]', 'inflected', 'heb', 'שֹׁד', '["shôd"]', '["like/ [the] devastation of","like/ devastation"]', '["n-m"]', 'violence, ravage desolation, destruction, oppression, robbery, spoil(-ed, -er, -ing), wasting.', 'or שׁוֹד; (Job 5:21), from 7736;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6735C}/[H6696]', 'lemma', 'heb', 'צִיר', '["tsîyr"]', '["pangs"]', '["n-m"]', 'a hinge (as pressed in turning); also a throe (as a phys. or mental pressure); also a herald or errand-doer (as constrained by the principal) ambassador, hinge, messenger, pain, pang, sorrow. Compare 6736.', 'from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2256B}/[H2254]', 'inflected', 'heb', 'חֶבֶל', '["chebel"]', '["and/ pains"]', '["n-m"]', 'a rope (as twisted), especially a measuring line; by implication, a district or inheritance (as measured); or a noose (as of cords); figuratively, a company (as if tied together); a throe (especially of parturition); also ruin band, coast, company, cord, country, destruction, line, lot, pain, pang, portion, region, rope, snare, sorrow, tackling.', 'or חֵבֶל; from 2254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0270}/H9013/[H270]', 'inflected', 'heb', 'אָחַז', '["ʼâchaz"]', '["they will seize [them]/ !"]', '["v"]', 'to seize (often with the accessory idea of holding in possession) be affrighted, bar, (catch, lay, take) hold (back), come upon, fasten, handle, portion, (get, have or take) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2342I}/H9013/[H2342]', 'inflected', 'heb', 'חוּל', '["chûwl"]', '["they will be in anguish/ !"]', '["v"]', 'properly, to twist or whirl (in a circular or spiral manner), i.e. (specifically) to dance, to writhe in pain (especially of parturition) or fear; figuratively, to wait, to pervert bear, (make to) bring forth, (make to) calve, dance, drive away, fall grievously (with pain), fear, form, great, grieve, (be) grievous, hope, look, make, be in pain, be much (sore) pained, rest, shake, shapen, (be) sorrow(-ful), stay, tarry, travail (with pain), tremble, trust, wait carefully (patiently), be wounded.', 'or חִיל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5678}/[H5676]', 'inflected', 'heb', 'עֶבְרָה', '["ʻebrâh"]', '["and/ wrath"]', '["n-f"]', 'an outburst of passion anger, rage, wrath.', 'feminine of 5676;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2400}/H9024/[H2398]', 'inflected', 'heb', 'חַטָּא', '["chaṭṭâʼ"]', '["and/ sinners/ its"]', '["n-m"]', 'a criminal, or one accounted guilty offender, sinful, sinner.', 'intensively from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3685H}/H9028/[H3684]', 'inflected', 'heb', 'כְּסִיל', '["Kᵉçîyl"]', '["and/ constellations/ their"]', '["n-m"]', 'any notable constellation; specifically Orion (as if a burly one) constellation, Orion.', 'the same as 3684;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3318K}/H9043/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["when/ goes forth/ it"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1346}/[H1342]', 'inflected', 'heb', 'גַּאֲוָה', '["gaʼăvâh"]', '["and/ [the] haughtiness of"]', '["n-f"]', 'arrogance or majesty; by implication, (concretely) ornament excellency, haughtiness, highness, pride, proudly, swelling.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6337}/[H6338]', 'inflected', 'heb', 'פָּז', '["pâz"]', '["more than/ pure gold"]', '["n-m"]', 'pure (gold); hence, gold itself (as refined) fine (pure) gold.', 'from 6338;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3800}/[H3799]', 'inflected', 'heb', 'כֶּתֶם', '["kethem"]', '["more than/ [the] gold of"]', '["n-m"]', 'properly, something carved out, i.e. ore; hence, gold (pure as originally mined) ((most) fine, pure) gold(-en wedge).', 'from 3799;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7493}/[H7493]', 'inflected', 'heb', 'רָעַשׁ', '["râʻash"]', '["and/ it may shake","so/ they may shake"]', '["v"]', 'to undulate (as the earth, the sky, etc.; also a field of grain), particularly through fear; specifically, to spring (as a locust) make afraid, (re-) move, quake, (make to) shake, (make to) tremble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/<H6629G>', 'inflected', 'heb', 'וכצאן', '["u./khe./Tzon"]', '["and/ like/ sheep"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1856}/[H1856]', 'lemma', 'heb', 'דָּקַר', '["dâqar"]', '["he will be pierced through","pierced through","they have pierced through"]', '["v"]', 'to stab; by analogy, to starve; figuratively, to revile pierce, strike (thrust) through, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5595}/[H5595]', 'inflected', 'heb', 'סָפָה', '["çâphâh"]', '["<the>/ [one who] is captured"]', '["v"]', 'properly, to scrape (literally, to shave; but usually figuratively) together (i.e. to accumulate or increase) or away (i.e. to scatter, remove, or ruin; intransitively, to perish) add, augment, consume, destroy, heap, join, perish, put.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8155}/[H8155]', 'lemma', 'heb', 'שָׁסַס', '["shâçaç"]', '["they will be plundered"]', '["v"]', 'to plunder rifle, spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6643A}/[H6638]', 'lemma', 'heb', 'צְבִי', '["tsᵉbîy"]', '["[is] beauty","[the] beauty of","beauties of","beauty","beauty of","splendor"]', '["n-m"]', 'splendor (as conspicuous) beautiful(-ty), glorious (-ry), goodly, pleasant, roe(-buck).', 'from 6638 in the sense of prominence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0167}/[H168]', 'lemma', 'heb', 'אָהַל', '["ʼâhal"]', '["he will pitch a tent"]', '["v"]', 'to tent pitch (remove) a tent.', 'a denominative from 168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6163A}/[H6152]', 'lemma', 'heb', 'עֲרָבִי', '["ʻĂrâbîy"]', '["an Arab"]', '["n a"]', 'an Arabian or inhabitant of Arab (i.e. Arabia) Arabian.', 'or עַרְבִי; patrial from 6152;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0255}/[H253]', 'lemma', 'heb', 'אֹחַ', '["ʼôach"]', '["jackals"]', '["n-m"]', 'a howler or lonesome wild animal doleful creature.', 'probably from 253;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8163C}/[H8175]', 'inflected', 'heb', 'שָׂעִיר', '["sâʻîyr"]', '["and/ goat","and/ goats"]', '["a n-m"]', 'shaggy; as noun, a he-goat; by analogy, a faun devil, goat, hairy, kid, rough, satyr.', 'or שָׂעִר; from 8175;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6030A}/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["and/ it will sing"]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0338}/[H337]', 'lemma', 'heb', 'אִי', '["ʼîy"]', '["hyenas"]', '["n-m"]', 'a howler (used only in the plural), i.e. any solitary wild creature wild beast of the islands.', 'probably identical with 337 (through the idea of a doleful sound);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0490}/H9023/[H488]', 'inflected', 'heb', 'אַלְמָנָה', '["ʼalmânâh"]', '["in/ palaces/ its"]', '["n-f"]', 'a widow; also a desolate place desolate house (palace), widow.', 'feminine of 488;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8577A}/[H8565]', 'inflected', 'heb', 'תַּנִּין', '["tannîyn"]', '["and/ jackals"]', '["n-m"]', 'a marine or land monster, i.e. sea-serpent or jackal dragon, sea-monster, serpent, whale.', 'or תַּנִּים; (Ezekiel 29:3), intensive from the same as 8565;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6027}/[H6026]', 'lemma', 'heb', 'עֹנֶג', '["ʻôneg"]', '["a delight","delight"]', '["n-m"]', 'luxury delight, pleasant.', 'from 6026;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6256}/H9024/[H5703]', 'inflected', 'heb', 'עֵת', '["ʻêth"]', '["time/ its"]', '["n-f"]', 'time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when.', 'from 5703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3117G>/H9024', 'inflected', 'heb', 'וימיה', '["ve./ya.Mei./ha"]', '["and/ days/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5596A}/[H5596]', 'inflected', 'heb', 'סָפַח', '["çâphach"]', '["and/ they will attach themselves"]', '["v"]', 'properly, to scrape out, but in certain peculiar senses (of removal or association) abiding, gather together, cleave, smite with the scab.', 'or שָׂפַח; (Isaiah 3:17), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5157}/H9038/[H5157]', 'inflected', 'heb', 'נָחַל', '["nâchal"]', '["and/ they will receive as an inheritance/ them"]', '["v"]', 'to inherit (as a (figurative) mode of descent), or (generally) to occupy; causatively, to bequeath, or (generally) distribute, instate divide, have (inheritance), take as a heritage, (cause to, give to, make to) inherit, (distribute for, divide (for, for an, by), give for, have, leave for, take (for)) inheritance, (have in, cause to, be made to) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7617}/H9038/[H7617]', 'inflected', 'heb', 'שָׁבָה', '["shâbâh"]', '["<to>/ captors/ their"]', '["v"]', 'to transport into captivity (bring away, carry, carry away, lead, lead away, take) captive(-s), drive (take) away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5065}/H9038\/[H5065]', 'inflected', 'heb', 'נָגַשׂ', '["nâgas"]', '["over/ oppressors/ their"]', '["v"]', 'to drive (an animal, a workman, a debtor, an army); by implication, to tax, harass, tyrannize distress, driver, exact(-or), oppress(-or), × raiser of taxes, taskmaster.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6090A}/H9021/[H6089]', 'inflected', 'heb', 'עֹצֶב', '["ʻôtseb"]', '["from/ pain/ your"]', '["n-m"]', 'an idol (as fashioned); also pain (bodily or mental) idol, sorrow, × wicked.', 'a variation of 6089;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H7267}/H9021/[H7264]', 'inflected', 'heb', 'רֹגֶז', '["rôgez"]', '["and/ from/ turmoil/ your"]', '["n-m"]', 'commotion, restlessness (of a horse), crash (of thunder), disquiet, anger fear, noise, rage, trouble(-ing), wrath.', 'from 7264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4912}/[H4910]', 'inflected', 'heb', 'מָשָׁל', '["mâshâl"]', '["[is] the/ proverb","the/ proverb","the/ saying"]', '["n-m"]', 'properly, a pithy maxim, usually of metaphorical nature; hence, a simile (as an adage, poem, discourse) byword, like, parable, proverb.', 'apparently from 4910 in some original sense of superiority in mental action;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4062}/[H1722]', 'lemma', 'heb', 'מַדְהֵבָה', '["madhêbâh"]', '["raging"]', '["n-f"]', 'goldmaking, i.e. exactness golden city.', 'perhaps from the equivalent of 1722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4783}/[H7291]', 'lemma', 'heb', 'מֻרְדָּף', '["murdâph"]', '["persecution"]', '["n-m"]', 'persecuted persecuted.', 'from 7291;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3772G}/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["the/ [wood] cutter"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3678G}/H9028/[H3680]', 'inflected', 'heb', 'כִּסֵּא', '["kiççêʼ"]', '["from/ thrones/ their"]', '["n-m"]', 'properly, covered, i.e. a throne (as canopied) seat, stool, throne.', 'or כִּסֵּה; from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2470A}/[H2342]', 'lemma', 'heb', 'חָלָה', '["châlâh"]', '["they have wearied themselves","you became weak","you have been made weak"]', '["v"]', 'properly, to be rubbed or worn; hence (figuratively) to be weak, sick, afflicted; or (causatively) to grieve, make sick; also to stroke (in flattering), entreat beseech, (be) diseased, (put to) grief, be grieved, (be) grievous, infirmity, intreat, lay to, put to pain, × pray, make prayer, be (fall, make) sick, sore, be sorry, make suit (× supplication), woman in travail, be (become) weak, be wounded.', 'a primitive root (compare 2342, 2470, 2490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1998}/[H1993]', 'lemma', 'heb', 'הֶמְיָה', '["hemyâh"]', '["[the] sound of"]', '["n-f"]', 'sound noise.', 'from 1993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5035B}/H9021/[H5034]', 'inflected', 'heb', 'נֶבֶל', '["nebel"]', '["lyres/ your"]', '["n-m"]', 'a skin-bag for liquids (from collapsing when empty); hence, a vase (as similar in shape when full); also a lyre (as having a body of like form) bottle, pitcher, psaltery, vessel, viol.', 'or נֵבֶל; from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4374}/H9021/[H3680]', 'inflected', 'heb', 'מְכַסֶּה', '["mᵉkaççeh"]', '["and/ coverings/ your"]', '["n-m"]', 'a covering, i.e. garment; specifically, a coverlet (for a bed), an awning (from the sun); also the omentum (as covering the intestines) clothing, to cover, that which covereth.', 'from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1966}/[H1984]', 'lemma', 'heb', 'הֵילֵל', '["hêylêl"]', '["O shining one"]', '["n-m"]', 'the morning-star lucifer.', 'from 1984 (in the sense of brightness);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2522}/[H2522]', 'lemma', 'heb', 'חָלַשׁ', '["châlash"]', '["O defeater"]', '["v"]', 'to prostrate; by implication, to overthrow, decay discomfit, waste away, weaken.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6913}/H9021/[H6912]', 'inflected', 'heb', 'קֶבֶר', '["qeber"]', '["from/ tomb/ your"]', '["n-m"]', 'a sepulchre burying place, grave, sepulchre.', 'or (feminine) קִבְרָה; from 6912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5342}/[H5341]', 'inflected', 'heb', 'נֵצֶר', '["nêtser"]', '["like/ a branch"]', '["n-m"]', 'a shoot; figuratively, a descendant branch.', 'from 5341 in the sense of greenness as a striking color;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2944}/[H2944]', 'lemma', 'heb', 'טָעַן', '["ṭâʻan"]', '["[who were] pierced of"]', '["v"]', 'to stab thrust through.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6297}/[H6296]', 'inflected', 'heb', 'פֶּגֶר', '["peger"]', '["like/ a corpse"]', '["n-m"]', 'a carcase (as limp), whether of man or beast; figuratively, an idolatrous image carcase, corpse, dead body.', 'from 6296;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6900}/[H6912]', 'inflected', 'heb', 'קְבוּרָה', '["qᵉbûwrâh"]', '["in/ burial"]', '["n-f"]', 'sepulture; (concretely) a sepulchre burial, burying place, grave, sepulchre.', 'or קְבֻרָה; feminine passive participle of 6912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4293}/[H2873]', 'lemma', 'heb', 'מַטְבֵּחַ', '["maṭbêach"]', '["a place of slaughter"]', '["n-m"]', 'slaughter slaughter.', 'from 2873;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5771H}/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["in/ [the] iniquity of"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5209}/[H5125]', 'inflected', 'heb', 'נִין', '["nîyn"]', '["and/ posterity"]', '["n-m"]', 'progeny son.', 'from 5125;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5220>', 'inflected', 'heb', 'ונכד', '["va./Ne.khed"]', '["and/ progeny"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4180}/[H3423]', 'inflected', 'heb', 'מוֹרָשׁ', '["môwrâsh"]', '["<into>/ a possession of"]', '["n-m"]', 'a possession; figuratively, delight possession, thought.', 'from 3423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7090}/[H7088]', 'lemma', 'heb', 'קִפּוֹד', '["qippôwd"]', '["hedgehog","hedgehog[s]"]', '["n-m"]', 'a species of bird, perhaps the bittern (from its contracted form) bittern.', 'or קִפֹּדlemma קִכֹּד kaf, corrected to קִפֹּד; from 7088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0098>', 'inflected', 'heb', 'ואגמים', '["va./''a.ga.Mim","ve./''ag.mei"]', '["and/ pools","and/ reed-pools of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2894}/H9034/[H2894]', 'inflected', 'heb', 'טוּא', '["ṭûwʼ"]', '["and/ I will sweep away/ it"]', '["v"]', 'to sweep away sweep.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4292}/[H2916]', 'inflected', 'heb', 'מַטְאֲטֵא', '["maṭʼăṭêʼ"]', '["with/ a broom of"]', '["n-m"]', 'a broom (as removing dirt (compare English ''to dust'', i.e. remove dust)) besom.', 'apparently a denominative from 2916;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2022G}/H9020/[H2042]', 'inflected', 'heb', 'הַר', '["har"]', '["mountains/ my"]', '["n-m"]', 'a mountain or range of hills (sometimes used figuratively) hill (country), mount(-ain), × promotion.', 'a shortened form of 2042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0947}/H9033/[H947]', 'inflected', 'heb', 'בּוּס', '["bûwç"]', '["I will tread down/ it"]', '["v"]', 'to trample (literally or figuratively) loath, tread (down, under (foot)), be polluted.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5448}/H9023/[H5445]', 'inflected', 'heb', 'סֹבֶל', '["çôbel"]', '["and/ burden/ its"]', '["n-m"]', 'load (figuratively) burden.', '(only in the form סֻבָּל; from 5445;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3289}/[H3289]', 'inflected', 'heb', 'יָעַץ', '["yâʻats"]', '["which/ is planned"]', '["v"]', 'to advise; reflexively, to deliberate or resolve advertise, take advise, advise (well), consult, (give, take) counsel(-lor), determine, devise, guide, purpose.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725I}/H9034\/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["will he revoke/ it","will he turn back/ it"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5221}/H9032/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["I have struck down/ you","I struck/ you","[the] [one who] struck/ you"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6848A>', 'opaque', 'heb', 'צֶפַע', '["tsephaʻ"]', '["a viper"]', '["n-m"]', 'a viper (as thrusting out the tongue, i.e. hissing) adder, cockatrice.', 'from an unused root meaning to extrude;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8328}/H9022/[H8327]', 'inflected', 'heb', 'שֶׁרֶשׁ', '["sheresh"]', '["root/ your"]', '["n-m"]', 'a root (literally or figuratively) bottom, deep, heel, root.', 'from 8327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7611}/H9022/[H7604]', 'inflected', 'heb', 'שְׁאֵרִית', '["shᵉʼêrîyth"]', '["and/ remnant/ your"]', '["n-f"]', 'a remainder or residual (surviving, final) portion that had escaped, be left, posterity, remain(-der), remnant, residue, rest.', 'from 7604;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4151}/H9023/[H3259]', 'inflected', 'heb', 'מוֹעָד', '["môwʻâd"]', '["among/ ranks/ its"]', '["n-m"]', 'properly, an assembly figuratively, a troop appointed time.', 'from 3259; (as in 4150);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7024A}/[H7023]', 'lemma', 'heb', 'קִיר', '["Qîyr"]', '["Kir of"]', '["n-pr-loc"]', 'Kir, a place in Assyrian; also one in Moab Kir. Compare 7025.', 'the same as 7023; fortress;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1065}/[H1058]', 'inflected', 'heb', 'בְּכִי', '["Bᵉkîy"]', '["for/ weeping"]', '["n-m"]', 'a weeping; by analogy, a dripping overflowing, × sore, (continual) weeping, wept.', 'from 1058;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2351>/H9023', 'inflected', 'heb', 'בחוצתיו', '["be./chu.tzo.Ta/v"]', '["in/ streets/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1406}/H9024/[H1342]', 'inflected', 'heb', 'גָּג', '["gâg"]', '["roofs/ its"]', '["n-m"]', 'a roof; by analogy, the top of an altar roof (of the house), (house) top (of the house).', 'probably by reduplication from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7339}/H9024/[H7337]', 'inflected', 'heb', 'רְחֹב', '["rᵉchôb"]', '["and/ in/ open places/ its"]', '["n-f"]', 'a width, i.e. (concretely) avenue or area broad place (way), street. See also 1050.', 'or רְחוֹב; from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3096>', 'opaque', 'heb', 'יַהַץ', '["Yahats"]', '["Jahaz"]', '["n-pr-loc"]', 'Jahats or Jahtsah, a place East of the Jordan Jahaz, Jahazah, Jahzah.', 'or יַהְצָה; or (feminine) יַהְצָה; from an unused root meaning to stamp; perhaps threshing-floor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1281}/H9024/[H1272]', 'inflected', 'heb', 'בָּרִיחַ', '["bârîyach"]', '["fugitives/ its"]', '["n-m"]', 'a fugitive, i.e. the serpent (as fleeing), and the constellation by that name crooked, noble, piercing.', 'or בָּרִחַ; (shortened) from 1272;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5697B}/[H5695]', 'lemma', 'heb', 'עֶגְלָה', '["ʻeglâh"]', '["Eglath"]', '["n-f"]', 'a (female) calf, especially one nearly grown (i.e. a heifer) calf, cow, heifer.', 'feminine of 5695;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3872}/[H3871]', 'inflected', 'heb', 'לוּחִית', '["Lûwchîyth"]', '["<the>/ Luhith"]', '["n-pr-loc"]', 'Luchith, a place East of the Jordan Luhith.', 'or לֻחוֹת; (Jeremiah 48:5), from the same as 3871; floored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5249}/[H5247]', 'lemma', 'heb', 'נִמְרִים', '["Nimrîym"]', '["Nimrim"]', '["n-pr-loc"]', 'Nimrim, a place East of the Jordan Nimrim. Compare 1039.', 'plural of a masculine corresponding to 5247; clear waters;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4923}/[H8074]', 'lemma', 'heb', 'מְשַׁמָּה', '["mᵉshammâh"]', '["wastes"]', '["n-f"]', 'a waste or amazement astonishment, desolate.', 'from 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3502}/[H3499]', 'lemma', 'heb', 'יִתְרָה', '["yithrâh"]', '["[the] wealth"]', '["n-f"]', 'properly, excellence, i.e. (by implication) wealth abundance, riches.', 'feminine of 3499;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6486}/H9028/[H6485]', 'inflected', 'heb', 'פְּקֻדָּה', '["pᵉquddâh"]', '["and/ store/ their"]', '["n-f"]', 'visitation (in many senses, chiefly official) account, (that have the) charge, custody, that which...laid up, numbers, office(-r), ordering, oversight, prison, reckoning, visitation.', 'feminine passive participle of 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5158G}/[H5157]', 'lemma', 'heb', 'נַחַל', '["nachal"]', '["[the] wadi of"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6155G}/[H6148]', 'inflected', 'heb', 'עָרָב', '["ʻârâb"]', '["the/ poplars"]', '["n-f"]', 'a willow (from the use of osiers as wattles) willow.', 'from 6148;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2201}/[H2199]', 'inflected', 'heb', 'זַעַק', '["zaʻaq"]', '["the/ cry"]', '["n-f"]', 'a shriek or outcry cry(-ing).', 'and (feminine) זְעָקָהxlit zᵉâqâh corrected to zᵉʻâqâh; from 2199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0097}/[H96]', 'lemma', 'heb', 'אֶגְלַיִם', '["ʼEglayim"]', '["Eglaim"]', '["n-pr-loc"]', 'Eglajim, a place in Moab Eglaim.', 'dual of 96.; a double pond;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3215}/H9024/[H3214]', 'inflected', 'heb', 'יְלָלָה', '["yᵉlâlâh"]', '["wailing/ its"]', '["n-f"]', 'a howling a howling.', 'feminine of 3214');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0879}/[H875]', 'inflected', 'heb', 'בְּאֵר אֵלִים', '["Bᵉʼêr ʼÊlîym"]', '["and/ Beer"]', '["n-pr-loc"]', 'Beer-Elim, a place in the Desert Beer-elim.', 'from 875 and the plural of 410; well of heroes;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0879}/[H875]', 'lemma', 'heb', 'בְּאֵר אֵלִים', '["Bᵉʼêr ʼÊlîym"]', '["Elim"]', '["n-pr-loc"]', 'Beer-Elim, a place in the Desert Beer-elim.', 'from 875 and the plural of 410; well of heroes;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1775}/[H1769]', 'lemma', 'heb', 'דִּימוֹן', '["Dîymôwn"]', '["Dimon"]', '["n-pr-loc"]', 'Dimon, a place in Palestine Dimon.', 'perhaps for 1769;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7611}/[H7604]', 'inflected', 'heb', 'שְׁאֵרִית', '["shᵉʼêrîyth"]', '["and/ for/ [the] remainder of"]', '["n-f"]', 'a remainder or residual (surviving, final) portion that had escaped, be left, posterity, remain(-der), remnant, residue, rest.', 'from 7604;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5554}/[H5553]', 'inflected', 'heb', 'סֶלַע', '["Çelaʻ"]', '["from/ Sela"]', '["n-pr-loc"]', 'Sela, the rock-city of Idumaea rock, Sela(-h).', 'the same as 5553;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5775}/[H5774]', 'inflected', 'heb', 'עוֹף', '["ʻôwph"]', '["like <the>/ bird","like/ [the] bird[s] of","like/ a bird"]', '["n-m"]', 'a bird (as covered with feathers, or rather as covering with wings), often collectively bird, that flieth, flying, fowl.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0769}/[H7442]', 'inflected', 'heb', 'אַרְנוֹן', '["ʼArnôwn"]', '["of/ Arnon"]', '["n-pr-loc"]', 'the Arnon, a river east of the Jordan, also its territory Arnon.', 'or אַרְנֹןlemma אַרְנן missing vowel, corrected to אַרְנֹן; from 7442; a brawling stream;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6415}/[H6414]', 'lemma', 'heb', 'פְּלִילָה', '["pᵉlîylâh"]', '["a decision"]', '["n-f"]', 'justice judgment.', 'feminine of 6414;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3915}/[H3883]', 'inflected', 'heb', 'לַיִל', '["layil"]', '["like <the>/ night","like/ a night of"]', '["n-m"]', 'properly, a twist (away of the light), i.e. night; figuratively, adversity (mid-)night (season).', 'or (Isaiah 21:11) לֵיל; also לַיְלָה; from the same as 3883;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6738}/H9022/[H6751]', 'inflected', 'heb', 'צֵל', '["tsêl"]', '["shade/ your"]', '["n-m"]', 'shade, whether literal or figurative defence, shade(-ow).', 'from 6751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5080}/H9030/[H5080]', 'inflected', 'heb', 'נָדַח', '["nâdach"]', '["outcasts/ my"]', '["v"]', 'to push off; used in a great variety of applications, literally and figuratively (to expel, mislead, strike, inflict, etc.) banish, bring, cast down (out), chase, compel, draw away, drive (away, out, quite), fetch a stroke, force, go away, outcast, thrust away (out), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4160}/[H4160]', 'inflected', 'heb', 'מוּץ', '["mûwts"]', '["the/ oppressor"]', '["n-m"]', 'to press, i.e. (figuratively) to oppress extortioner.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4106}/[H4116]', 'inflected', 'heb', 'מָהִיר', '["mâhîyr"]', '["and/ [one] prompt of"]', '["a"]', 'quick; hence, skilful diligent, hasty, ready.', 'or מָהִר; from 4116;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1341}/[H1343]', 'lemma', 'heb', 'גֵּא', '["gêʼ"]', '["proud"]', '["a"]', 'haughty proud.', 'for 1343;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1347}/H9023/[H1342]', 'inflected', 'heb', 'גָּאוֹן', '["gâʼôwn"]', '["and/ pride/ its"]', '["n-m"]', 'the same as 1346 arrogancy, excellency(-lent), majesty, pomp, pride, proud, swelling.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0907}/H9023\/[H908]', 'inflected', 'heb', 'בַּד', '["bad"]', '["empty boasts/ its"]', '["n-m"]', 'a brag or lie; also a liar liar, lie.', 'from 908;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0809}/[H808]', 'inflected', 'heb', 'אֲשִׁישָׁה', '["ʼăshîyshâh"]', '["for/ [the] raisin-cakes of"]', '["n-f"]', 'something closely pressed together, i.e. a cake of raisins or other comfits flagon.', 'feminine of 808;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5218A}/[H5217]', 'lemma', 'heb', 'נָכֵא', '["nâkêʼ"]', '["stricken people"]', '["a"]', 'smitten, i.e. (figuratively) afflicted broken, stricken, wounded.', 'or נָכָא; from 5217;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7709}/[H7704]', 'lemma', 'heb', 'שְׁדֵמָה', '["shᵉdêmâh"]', '["[the] fields of"]', '["n-f"]', 'a cultivated field blasted, field.', 'apparently from 7704;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8291}/H9024/[H8321]', 'inflected', 'heb', 'שָׂרוּק', '["sârûwq"]', '["choice grapes/ its"]', '["n-m"]', 'a grapevine principal plant. See 8320, 8321.', 'passive participle from the same as 8321;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7976}/H9024/[H7964]', 'inflected', 'heb', 'שִׁלֻּחָה', '["shilluchâh"]', '["shoots/ its"]', '["n-f"]', 'a shoot branch.', 'feminine of 7964;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7301}/H9032/[H7301]', 'inflected', 'heb', 'רָוָה', '["râvâh"]', '["I water abundantly/ you"]', '["v"]', 'to slake the thirst (occasionally of other appetites) bathe, make drunk, (take the) fill, satiate, (abundantly) satisfy, soak, water (abundantly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7019}/H9022/[H6972]', 'inflected', 'heb', 'קַיִץ', '["qayits"]', '["summer fruit/ your"]', '["n-m"]', 'harvest (as the crop), whether the product (grain or fruit) or the (dry) season summer (fruit, house).', 'from 6972;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7105A}/H9022/[H7114]', 'inflected', 'heb', 'קָצִיר', '["qâtsîyr"]', '["harvest/ your"]', '["n-m"]', 'severed, i.e. harvest (as reaped), the crop, the time, the reaper, or figuratively; also a limb (of a tree, or simply foliage) bough, branch, harvest (man).', 'from 7114;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1959>', 'opaque', 'heb', 'הֵידָד', '["hêydâd"]', '["a shout","shouting"]', '["n-m"]', 'acclamation shout(-ing).', 'from an unused root (meaning to shout);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3759}/[H3754]', 'inflected', 'heb', 'כַּרְמֶל', '["karmel"]', '["the/ garden-land","the/ orchard"]', '["n-m"]', 'a planted field (garden, orchard, vineyard or park); by implication, garden produce full (green) ears (of corn), fruitful field (place), plentiful (field).', 'from 3754;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1869}/[H1869]', 'inflected', 'heb', 'דָּרַךְ', '["dârak"]', '["the/ [one] bending","the/ treader"]', '["v"]', 'to tread; by implication, to walk; also to string a bow (by treading on it in bending) archer, bend, come, draw, go (over), guide, lead (forth), thresh, tread (down), walk.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H3658>', 'inflected', 'heb', 'ככנור', '["ka./ki.Nor"]', '["like <the>/ harp"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7130H}/H9020/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["and/ inner being/ my"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7025}/[H7023]', 'inflected', 'heb', 'קִיר חֶרֶשׂ', '["Qîyr Cheres"]', '["for/ Kir"]', '["n-pr-loc"]', 'Kir-Cheres or Kir-Chareseth, a place in Moab Kir-haraseth, Kir-hareseth, Kirharesh, Kir-heres.', 'or (feminine of the latter word) קִיר חֲרֶשֶׂת; from 7023 and 2789; fortress of earthenware;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3524}\/[H3527]', 'inflected', 'heb', 'כַּבִּיר', '["kabbîyr"]', '["[will be] mighty"]', '["a"]', 'vast, whether in extent (figuratively, of power, mighty; of time, aged), or in number, many feeble, mighty, most, much, strong, valiant.', 'from 3527;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4596}/[H5753]', 'lemma', 'heb', 'מְעִי', '["mᵉʻîy"]', '["a ruin of"]', '["n-m"]', 'a pile of rubbish (as contorted), i.e. a ruin heap.', 'from 5753; (compare 5856)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4654A}/[H5307]', 'lemma', 'heb', 'מַפָּלָה', '["mappâlâh"]', '["a ruin"]', '["n-f"]', 'something fallen, i.e. a ruin ruin(-ous).', 'or מַפֵּלָה; from 5307;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3519}/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["like the/ glory","like/ [the] glory of"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4924B}/[H8080]', 'inflected', 'heb', 'מַשְׁמָן', '["mashmân"]', '["and/ [the] fatness of"]', '["n-m"]', 'fat, i.e. (literally and abstractly) fatness; but usually (figuratively and concretely) a rich dish, a fertile field, a robust man fat (one, -ness, -test, -test place).', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7329}/[H7329]', 'lemma', 'heb', 'רָזָה', '["râzâh"]', '["he will make lean","it will be made lean"]', '["v"]', 'to emaciate, i.e. make (become) thin (literally or figuratively) famish, wax lean.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0622}/[H622]', 'inflected', 'heb', 'אָסַף', '["ʼâçaph"]', '["like/ [the] gathering of"]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3950}/[H3950]', 'inflected', 'heb', 'לָקַט', '["lâqaṭ"]', '["like/ [one who] gathers"]', '["v"]', 'properly, to pick up, i.e. (generally) to gather; specifically, to glean gather (up), glean.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5363}/[H5362]', 'inflected', 'heb', 'נֹקֶף', '["nôqeph"]', '["like/ [the] beating of"]', '["n-m"]', 'a threshing (of olives) shaking.', 'from 5362;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1620}/[H1641]', 'lemma', 'heb', 'גַּרְגַּר', '["gargar"]', '["olives"]', '["n-m"]', 'a berry (as if a pellet of rumination) berry.', 'by reduplication from 1641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0534}/[H559]', 'lemma', 'heb', 'אָמִיר', '["ʼâmîyr"]', '["[the] tree-top"]', '["n-m"]', 'a summit (of a tree or mountain) bough, branch.', 'apparently from 559 (in the sense of self-exaltation);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5585}/H9024/[H5586]', 'inflected', 'heb', 'סָעִיף', '["çâʻîyph"]', '["on/ branches/ its"]', '["n-m"]', 'a fissure (of rocks); also a bough (as subdivided) (outmost) branch, clift, top.', 'from 5586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5800A}/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["like/ [the] forsaken [place] of"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2793H}/[H2790]', 'inflected', 'heb', 'חֹרֶשׁ', '["chôresh"]', '["the/ forest"]', '["n-m"]', 'a forest (perhaps as furnishing the material for fabric) bough, forest, shroud, wood.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0534}/[H559]', 'inflected', 'heb', 'אָמִיר', '["ʼâmîyr"]', '["and/ the/ tree-top"]', '["n-m"]', 'a summit (of a tree or mountain) bough, branch.', 'apparently from 559 (in the sense of self-exaltation);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3468}/H9022/[H3467]', 'inflected', 'heb', 'יֶשַׁע', '["yeshaʻ"]', '["salvation/ your"]', '["n-m"]', 'liberty, deliverance, prosperity safety, salvation, saving.', 'or יֵשַׁע; from 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4581}/H9022/[H5810]', 'inflected', 'heb', 'מָעוֹז', '["mâʻôwz"]', '["refuge/ your"]', '["n-m"]', 'a fortified place; figuratively, a defence force, fort(-ress), rock, strength(-en), (× most) strong (hold).', '(also מָעוּז ); or מָעֹז (also מָעֻז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5282}/[H5276]', 'lemma', 'heb', 'נַעֲמָן', '["naʻămân"]', '["pleasantness<es>"]', '["n-m"]', 'pleasantness (plural as concrete) pleasant.', 'from 5276;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2156}/[H2168]', 'inflected', 'heb', 'זְמוֹרָה', '["zᵉmôwrâh"]', '["and/ [the] vine branch of"]', '["n"]', 'a twig (as pruned) vine, branch, slip.', 'or זְמֹרָה (feminine); and זְמֹר (masculine); from 2168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2232}/H9033/[H2232]', 'inflected', 'heb', 'זָרַע', '["zâraʻ"]', '["you sow/ it"]', '["v"]', 'to sow; figuratively, to disseminate, plant, fructify bear, conceive seed, set with sow(-er), yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5194}/H9022/[H5193]', 'inflected', 'heb', 'נֶטַע', '["neṭaʻ"]', '["planting/ your"]', '["n-m"]', 'a plant; collectively, a plantation; abstractly, a planting plant.', 'from 5193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7735}/[H7735]', 'lemma', 'heb', 'שׂוּג', '["sûwg"]', '["you cause to grow"]', '["v"]', 'to hedge in make to grow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2233G}/H9022/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["seed/ your"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3511}/[H3510]', 'inflected', 'heb', 'כְּאֵב', '["kᵉʼêb"]', '["and/ pain"]', '["n-m"]', 'suffering (physical or mental), adversity grief, pain, sorrow.', 'from 3510;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0605}\/[H605]', 'inflected', 'heb', 'אָנַשׁ', '["ʼânash"]', '["incurable"]', '["v"]', 'to be frail, feeble, or (figuratively) melancholy desperate(-ly wicked), incurable, sick, woeful.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1993}/[H1949]', 'inflected', 'heb', 'הָמָה', '["hâmâh"]', '["as/ roar"]', '["v"]', 'to make a loud sound (like English ''hum''); by implication, to be in great commotion or tumult, to rage, war, moan, clamor clamorous, concourse, cry aloud, be disquieted, loud, mourn, be moved, make a noise, rage, roar, sound, be troubled, make in tumult, tumultuous, be in an uproar.', 'a primitive root (compare 1949);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7588}/[H7582]', 'inflected', 'heb', 'שָׁאוֹן', '["shâʼôwn"]', '["and/ [the] uproar of"]', '["n-m"]', 'uproar (as of rushing); by implication, destruction × horrible, noise, pomp, rushing, tumult (× -uous).', 'from 7582;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7588}/[H7582]', 'inflected', 'heb', 'שָׁאוֹן', '["shâʼôwn"]', '["like/ [the] uproar of"]', '["n-m"]', 'uproar (as of rushing); by implication, destruction × horrible, noise, pomp, rushing, tumult (× -uous).', 'from 7582;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7582}/H9013/[H7582]', 'inflected', 'heb', 'שָׁאָה', '["shâʼâh"]', '["they are in an uproar/ !"]', '["v"]', 'to rush; by implication, to desolate be desolate, (make a) rush(-ing), (lay) waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H1534}/[H1556]', 'inflected', 'heb', 'גַּלְגַּל', '["galgal"]', '["and/ like/ whirling dust"]', '["n-m"]', 'a wheel; by analogy, a whirlwind; also dust (as whirled) heaven, rolling thing, wheel.', 'by reduplication from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8154}/H9035/[H8154]', 'inflected', 'heb', 'שָׁסָה', '["shâçâh"]', '["[those who] plunder/ us"]', '["v"]', 'to plunder destroyer, rob, spoil(-er).', 'or שָׁשָׂה; (Isaiah 10:13), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0962}/H9035\/[H962]', 'inflected', 'heb', 'בָּזַז', '["bâzaz"]', '["of/ [those who] despoil/ us"]', '["v"]', 'to plunder catch, gather, (take) for a prey, rob(-ber), spoil, take (away, spoil), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6767A}/[H6750]', 'lemma', 'heb', 'צְלָצַל', '["tsᵉlâtsal"]', '["whirring of"]', '["n-m"]', 'a clatter, i.e. (abstractly) whirring (of wings); (concretely) a cricket; also a harpoon (as rattling),a cymbal (as clanging) cymbal, locust, shadowing, spear.', 'from 6750 reduplicated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5104H}/[H5102]', 'inflected', 'heb', 'נָהָר', '["nâhâr"]', '["of/ [the] rivers of"]', '["n-m"]', 'a stream (including the sea; expectation the Nile, Euphrates, etc.); figuratively, prosperity flood, river.', 'from 5102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4803}/[H4803]', 'inflected', 'heb', 'מָרַט', '["mâraṭ"]', '["and/ smooth skinned"]', '["v"]', 'to polish; by implication, to make bald (the head), to gall (the shoulder); also, to sharpen bright, furbish, (have his) hair (be) fallen off, peeled, pluck off (hair).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6978}/[H6957]', 'lemma', 'heb', 'קַו־קַו', '["qav-qav"]', '["strength","strength of"]', '["n-m"]', 'stalwart × meted out.', 'from 6957 (in the sense of a fastening);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4001}/[H947]', 'inflected', 'heb', 'מְבוּסָה', '["mᵉbûwçâh"]', '["and/ trampling"]', '["n-f"]', 'a trampling treading (trodden) down (under foot).', 'from 947;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0958}/[H958]', 'lemma', 'heb', 'בָּזָא', '["bâzâʼ"]', '["they divide"]', '["v"]', 'probably to cleave spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5375G}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["when/ lifts up"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H8628}/[H8628]', 'inflected', 'heb', 'תָּקַע', '["tâqaʻ"]', '["and/ just as/ sounds"]', '["v"]', 'to clatter, i.e. slap (the hands together), clang (an instrument); by analogy, to drive (a nail or tent-pin, a dart, etc.); by implication, to become bondsman by handclasping) blow (a trumpet), cast, clap, fasten, pitch (tent), smite, sound, strike, × suretiship, thrust.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8085G}\/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["I have heard","it will be heard","they listened","you will hear [it]"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4349}/H9020/[H3559]', 'inflected', 'heb', 'מָכוֹן', '["mâkôwn"]', '["in/ place/ my"]', '["n-m"]', 'properly, a fixture, i.e. a basis; generally a place, especially as an abode foundation, habitation, (dwelling-, settled) place.', 'from 3559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2527}/[H2552]', 'inflected', 'heb', 'חֹם', '["chôm"]', '["in/ [the] heat of"]', '["n-m"]', 'heat heat, to be hot (warm).', 'from 2552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8552}/[H8552]', 'inflected', 'heb', 'תָּמַם', '["tâmam"]', '["when/ are completed","when/ is finished"]', '["v"]', 'to complete, in a good or a bad sense, literal, or figurative, transitive or intransitive accomplish, cease, be clean (pass-) ed, consume, have done, (come to an, have an, make an) end, fail, come to the full, be all gone, × be all here, be (make) perfect, be spent, sum, be (shew self) upright, be wasted, whole.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1155}/[H1154]', 'inflected', 'heb', 'בֹּסֶר', '["bôçer"]', '["and/ unripe grape[s]"]', '["n-m"]', 'sour grape.', 'from the same as 1154');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5328}/[H5322]', 'lemma', 'heb', 'נִצָּה', '["nitstsâh"]', '["blossom"]', '["n-f"]', 'a blossom flower.', 'feminine of 5322;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2150}/[H2151]', 'inflected', 'heb', 'זַלְזַל', '["zalzal"]', '["the/ shoots"]', '["n-m"]', 'tremulous, i.e. a twig sprig.', 'by reduplication from 2151;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4211}/[H2168]', 'inflected', 'heb', 'מַזְמֵרָה', '["mazmêrâh"]', '["with <the>/ pruning knives"]', '["n-f"]', 'a pruning-knife pruning-hook.', 'from 2168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5189}/[H5203]', 'inflected', 'heb', 'נְטִישָׁה', '["nᵉṭîyshâh"]', '["the/ tendrils"]', '["n-f"]', 'a tendril (as an offshoot) battlement, branch, plant.', 'from 5203;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8456}/[H8456]', 'lemma', 'heb', 'תָּזַז', '["tâzaz"]', '["he will cut away"]', '["v"]', 'to lop off cut down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5861}/[H5860]', 'inflected', 'heb', 'עַיִט', '["ʻayiṭ"]', '["to/ bird[s] of prey of"]', '["n-m"]', 'a hawk or other bird of prey bird, fowl, ravenous (bird).', 'from 5860;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6972}/[H7019]', 'inflected', 'heb', 'קוּץ', '["qûwts"]', '["and/ it will pass [the] summer"]', '["n-m"]', 'to spend the harvest season summer.', 'a primitive root; to clip off; used only as denominative from 7019;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2778B}/[H2779]', 'lemma', 'heb', 'חָרַף', '["châraph"]', '["it will pass [the] winter"]', '["v"]', 'to pull off, i.e. (by implication) to expose (as by stripping); specifically, to betroth (as if a surrender); figuratively, to carp at, i.e. defame; to spend the winter betroth, blaspheme, defy, jeopard, rail, reproach, upbraid.', 'a primitive root; also denominative (from 2779)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5971A}/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["and/ from/ a people","and/ from/ peoples"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4467}/[H4427]', 'inflected', 'heb', 'מַמְלָכָה', '["mamlâkâh"]', '["[are] on the/ kingdom","against/ kingdom"]', '["n-f"]', 'dominion, i.e. (abstractly) the estate (rule) or (concretely) the country (realm) kingdom, king''s, reign, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1238B}/[H1238]', 'inflected', 'heb', 'בָּקַק', '["bâqaq"]', '["and/ I will make void","and/ it will be disturbed"]', '["v"]', 'to pour out, i.e. to empty, figuratively, to depopulate; by analogy, to spread out (as a fruitful vine) (make) empty (out), fail, × utterly, make void.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6098}/H9023/[H3289]', 'inflected', 'heb', 'עֵצָה', '["ʻêtsâh"]', '["and/ plan/ its"]', '["n-f"]', 'advice; by implication, plan; also prudence advice, advisement, counsel([-lor]), purpose.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0328A>', 'inflected', 'heb', 'האטים', '["ha./''i.Tim"]', '["the/ mutterer"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5405}/[H5405]', 'inflected', 'heb', 'נָשַׁת', '["nâshath"]', '["and/ they will be dried up"]', '["v"]', 'properly, to eliminate, i.e. (intransitively) to dry up fail.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/<H3220G>', 'inflected', 'heb', 'מהים', '["me./hai./Yam"]', '["from/ the/ sea"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2186B}/[H2186]', 'inflected', 'heb', 'זָנַח', '["zânach"]', '["and/ they will stink"]', '["v"]', 'reject, forsake, fail cast away (off), remove far away (off).', 'a primitive root meaning to push aside, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2975G}/[H2975]', 'lemma', 'heb', 'יְאֹר', '["yᵉʼôr"]', '["[the] River","[the] canals of","canals"]', '["n-m"]', 'a channel, e.g. a fosse, canal, shaft; specifically the Nile, as the one river of Egypt, including its collateral trenches; also the Tigris, as the main river of Assyria brook, flood, river, stream.', 'of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5488H}/[H5488]', 'inflected', 'heb', 'סוּף', '["çûwph"]', '["and/ rush[es]"]', '["n-m"]', 'a reed, especially the papyrus flag, Red (sea), weed. Compare 5489.', 'probably of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7060}/[H7060]', 'lemma', 'heb', 'קָמַל', '["qâmal"]', '["it has withered","they will wither"]', '["v"]', 'to wither hew down, wither.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6169}/[H6168]', 'lemma', 'heb', 'עָרָה', '["ʻârâh"]', '["reeds"]', '["n-f"]', 'a naked (i.e. level) plot paper reed.', 'feminine from 6168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4218}/[H2232]', 'lemma', 'heb', 'מִזְרָע', '["mizrâʻ"]', '["[the] sown land of"]', '["n-m"]', 'a planted field thing sown.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1771}/[H1770]', 'inflected', 'heb', 'דַּיָּג', '["dayâg"]', '["the/ fishermen"]', '["n-m"]', 'a fisherman fisher.', 'from 1770;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2443}/[H2442]', 'lemma', 'heb', 'חַכָּה', '["chakkâh"]', '["a fish hook"]', '["n-f"]', 'a hook (as adhering) angle, hook.', 'probably from 2442;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6566}/[H6566]', 'inflected', 'heb', 'פָּרַשׂ', '["pâras"]', '["and/ [those who] spread out","and/ they have chopped [them] up","so/ he may spread out"]', '["v"]', 'to break apart, disperse, etc. break, chop in pieces, lay open, scatter, spread (abroad, forth, selves, out), stretch (forth, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4365B}/[H4364]', 'lemma', 'heb', 'מִכְמֶרֶת', '["mikmereth"]', '["<of> a fishing net"]', '["n-f"]', 'a (fisher''s) net drag, net.', 'or מִכְמֹרֶת; feminine of 4364;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8305}/[H8321]', 'lemma', 'heb', 'שְׂרִיקָה', '["sᵉrîyqâh"]', '["combed"]', '["a"]', 'hetchelling (or combing flax), i.e. (concretely) tow (by extension, linen cloth) fine.', 'from the same as 8321 in the original sense of piercing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2355}/[H2353]', 'lemma', 'heb', 'חוֹר', '["chôwr"]', '["white cloth"]', '["n-m"]', 'white linen network. Compare 2715.', 'the same as 2353;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8356}/H9024/[H7896]', 'inflected', 'heb', 'שָׁתָה', '["shâthâh"]', '["foundations/ its"]', '["n-m"]', 'a basis, i.e. (figuratively) political or moral support foundation, purpose.', 'from 7896;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0099}/[H98]', 'lemma', 'heb', 'אָגֵם', '["ʼâgêm"]', '["[will be] grieved of"]', '["a"]', 'figuratively, sad pond.', 'probably from the same as 98 (in the sense of stagnant water);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0335}/H9048/[H370]', 'inflected', 'heb', 'אַי', '["ʼay"]', '["where [are]?/ they"]', '["adv"]', 'where? hence how? how, what, whence, where, whether, which (way).', 'perhaps from 370;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5297}/[H4644]', 'lemma', 'heb', 'נֹף', '["Nôph"]', '["Memphis"]', '["n-pr-loc"]', 'Noph, the capital of Upper Egypt Noph.', 'a variation of 4644;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7626H>/H9024', 'opaque', 'heb', 'שֵׁבֶט', '["shêbeṭ"]', '["tribes/ its"]', '["n-m"]', 'a scion, i.e. (literally) a stick (for punishing, writing, fighting, ruling, walking, etc.) or (figuratively) a clan × correction, dart, rod, sceptre, staff, tribe.', 'from an unused root probably meaning to branch off;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5773}/[H5753]', 'lemma', 'heb', 'עַוְעֶה', '["ʻavʻeh"]', '["confusion<s>"]', '["n-m"]', 'perversity × perverse.', 'from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8582}/[H8582]', 'inflected', 'heb', 'תָּעָה', '["tâʻâh"]', '["as/ is made to stagger"]', '["v"]', 'to vacillate, i.e. reel or stray (literally or figuratively); also causative of both (cause to) go astray, deceive, dissemble, (cause to, make to) err, pant, seduce, (make to) stagger, (cause to) wander, be out of the way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6892B}/H9023/[H6958]', 'inflected', 'heb', 'קֵא', '["qêʼ"]', '["in/ vomit/ his","in/ vomit/ its"]', '["n-m"]', 'vomit vomit.', 'or קִיא; from 6958;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0100}\/[H98]', 'inflected', 'heb', 'אַגְמוֹן', '["ʼagmôwn"]', '["and/ bulrush"]', '["n-m"]', 'a rush (as growing there); collectively a rope of rushes bulrush, caldron, hook, rush.', 'from the same as 98; a marshy pool (others from a different root, a kettle); by implication');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H2283>', 'inflected', 'heb', 'לחגא', '["le./cha.Ga''"]', '["<into>/ an object of terror"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7650}/[H7651]', 'inflected', 'heb', 'שָׁבַע', '["shâbaʻ"]', '["and/ swearing an oath","and/ will you swear?"]', '["v"]', 'to seven oneself, i.e. swear (as if by repeating a declaration seven times) adjure, charge (by an oath, with an oath), feed to the full (by mistake for 7646), take an oath, × straitly, (cause to, make to) swear.', 'a primitive root; properly to be complete, but used only as a denominative from 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5892G}/[H5782]', 'lemma', 'heb', 'עִיר', '["ʻîyr"]', '["[the] city"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2041}/[H2040]', 'inflected', 'heb', 'הֶרֶס', '["hereç"]', '["of <the>/ Destruction"]', '["n-m"]', 'demolition destruction.', 'from 2040;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0259}\/[H258]', 'inflected', 'heb', 'אֶחָד', '["ʼechâd"]', '["of/ one"]', '["a"]', 'properly, united, i.e. one; or (as an ordinal) first a, alike, alone, altogether, and, any(-thing), apiece, a certain, (dai-) ly, each (one), eleven, every, few, first, highway, a man, once, one, only, other, some, together,', 'a numeral from 258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1366G}/H9024/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["border/ its","territory/ its"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5707}/[H5749]', 'inflected', 'heb', 'עֵד', '["ʻêd"]', '["and/ <into>/ a witness"]', '["n-m"]', 'concretely, a witness; abstractly, testimony; specifically, a recorder, i.e. prince witness.', 'contracted from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7495}/H9038/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["and/ I will heal/ them","and/ he will heal/ them"]', '["v"]', 'properly, to mend (by stitching), i.e. (figuratively) to cure cure, (cause to) heal, physician, repair, × thoroughly, make whole. See 7503.', 'or רָפָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0804G}/[H833]', 'inflected', 'heb', 'אַשּׁוּר', '["ʼAshshûwr"]', '["in/ Assyria"]', '["n-pr-m n-pr-loc"]', 'Ashshur, the second son of Shem; also his descendants and the country occupied by them (i.e. Assyria), its region and its empire Asshur, Assur, Assyria, Assyrians. See 838.', 'or אַשֻּׁר; apparently from 833 (in the sense of successful);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0804G}/[H833]', 'inflected', 'heb', 'אַשּׁוּר', '["ʼAshshûwr"]', '["and/ to/ Assyria"]', '["n-pr-m n-pr-loc"]', 'Ashshur, the second son of Shem; also his descendants and the country occupied by them (i.e. Assyria), its region and its empire Asshur, Assur, Assyria, Assyrians. See 838.', 'or אַשֻּׁר; apparently from 833 (in the sense of successful);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5159}/H9020/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["and/ inheritance/ my"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5623}/[H5623]', 'lemma', 'heb', 'סַרְגּוֹן', '["Çargôwn"]', '["Sargon"]', '["n-pr-m"]', 'Sargon, an Assyrian king Sargon.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3182>\', 'inflected', 'heb', 'ויחף ס', '["ve./ya.Chef"]', '["and/ barefoot"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3182>', 'inflected', 'heb', 'ויחף', '["ve./ya.Chef"]', '["and/ barefoot"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1546}/[H1540]', 'lemma', 'heb', 'גָּלוּת', '["gâlûwth"]', '["[the] exile[s] of","exile"]', '["n-f"]', 'captivity; concretely, exiles (collectively) (they that are carried away) captives(-ity).', 'feminine from 1540;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2834}/[H2834]', 'inflected', 'heb', 'חָשַׂף', '["châsaph"]', '["and/ [ones] uncovered of"]', '["v"]', 'to strip off, i.e. generally to make naked (for exertion or in disgrace), to drain away or bail up (a liquid) make bare, clean, discover, draw out, take, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8357}/[H7896]', 'lemma', 'heb', 'שֵׁתָה', '["shêthâh"]', '["buttock"]', '["n-m"]', 'the seat (of the person) buttock.', 'from 7896;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H3568A>', 'inflected', 'heb', 'מכוש', '["mi./Kush"]', '["from/ Cush"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4007}/H9028/[H5027]', 'inflected', 'heb', 'מַבָּט', '["mabbâṭ"]', '["hope/ their"]', '["n-m"]', 'something expected, i.e. (abstractly) expectation expectation.', 'or מֶבָּט; from 5027;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8597}/H9028/[H6286]', 'inflected', 'heb', 'תִּפְאָרָה', '["tiphʼârâh"]', '["boasting/ their","splendor/ their"]', '["n-f"]', 'ornament (abstractly or concretely, literally or figuratively) beauty(-iful), bravery, comely, fair, glory(-ious), honour, majesty.', 'or תִּפְאֶרֶת; from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0339}/[H183]', 'inflected', 'heb', 'אִי', '["ʼîy"]', '["the/ coast","the/ coastland","the/ islands"]', '["n-m"]', 'properly, a habitable spot (as desirable); dry land, a coast, an island country, isle, island.', 'from 183;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4007}/H9025/[H5027]', 'inflected', 'heb', 'מַבָּט', '["mabbâṭ"]', '["hope/ our"]', '["n-m"]', 'something expected, i.e. (abstractly) expectation expectation.', 'or מֶבָּט; from 5027;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2498}/[H2498]', 'inflected', 'heb', 'חָלַף', '["châlaph"]', '["to/ sweep on"]', '["v"]', 'properly, to slide by, i.e. (by implication) to hasten away, pass on, spring up, pierce or change abolish, alter, change, cut off, go on forward, grow up, be over, pass (away, on, through), renew, sprout, strike through.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2380}/[H2372]', 'lemma', 'heb', 'חָזוּת', '["châzûwth"]', '["[the] vision of","a vision","conspicuousness"]', '["n-f"]', 'a look; hence (figuratively) striking appearance, revelation, or (by implication) compact agreement, notable (one), vision.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7703}/[H7703]', 'inflected', 'heb', 'שָׁדַד', '["shâdad"]', '["and/ the/ destroyer"]', '["v"]', 'properly, to be burly, i.e. (figuratively) powerful (passively, impregnable); by implication, to ravage dead, destroy(-er), oppress, robber, spoil(-er), × utterly, (lay) waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0585}/H9024/[H584]', 'inflected', 'heb', 'אֲנָחָה', '["ʼănâchâh"]', '["groaning/ its"]', '["n-f"]', 'sighing groaning, mourn, sigh.', 'from 584;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4975>/H9020', 'opaque', 'heb', 'מֹתֶן', '["môthen"]', '["loins/ my"]', '["n-m"]', 'properly, the waist or small of the back; only in plural the loins greyhound, loins, side.', 'from an unused root meaning to be slender;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2479}/[H2478]', 'lemma', 'heb', 'חַלְחָלָה', '["chalchâlâh"]', '["anguish"]', '["n-f"]', 'writhing (in childbirth); by implication, terror (great, much) pain.', 'feminine from the same as 2478;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6735C}/[H6696]', 'inflected', 'heb', 'צִיר', '["tsîyr"]', '["like/ [the] pangs of"]', '["n-m"]', 'a hinge (as pressed in turning); also a throe (as a phys. or mental pressure); also a herald or errand-doer (as constrained by the principal) ambassador, hinge, messenger, pain, pang, sorrow. Compare 6736.', 'from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2837}/H9020/[H2836]', 'inflected', 'heb', 'חֵשֶׁק', '["chêsheq"]', '["desire/ my"]', '["n-m"]', 'delight desire, pleasure.', 'from 2836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6844}/[H6822]', 'inflected', 'heb', 'צָפִית', '["tsâphîyth"]', '["the/ rug"]', '["n-f"]', 'a sentry watchtower.', 'from 6822;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7181}/[H7181]', 'inflected', 'heb', 'קָשַׁב', '["qâshab"]', '["and/ he paid attention","and/ he will pay attention"]', '["v"]', 'to prick up the ears, i.e. hearken attend, (cause to) hear(-ken), give heed, incline, mark (well), regard.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4707}/[H6822]', 'lemma', 'heb', 'מִצְפֶּה', '["mitspeh"]', '["a watchtower"]', '["n-m"]', 'an observatory, especially for military purposes watch tower.', 'from 6822;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4098}/H9020/[H1758]', 'inflected', 'heb', 'מְדֻשָּׁה', '["mᵉdushshâh"]', '["O threshed one/ my"]', '["n-f"]', 'a threshing, i.e. (concretely and figuratively) down-trodden people threshing.', 'from 1758;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1637>/H9020', 'opaque', 'heb', 'גֹּרֶן', '["gôren"]', '["threshing floor/ my"]', '["n-m"]', 'a threshing-floor (as made even); by analogy, any open area (barn, corn, threshing-) floor, (threshing-, void) place.', 'from an unused root meaning to smooth;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1746H}/[H1745]', 'lemma', 'heb', 'דּוּמָה', '["Dûwmâh"]', '["Dumah"]', '["n-pr-m n-pr-loc"]', 'Dumah, a tribe and region of Arabia Dumah.', 'the same as 1745;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3915}/[H3883]', 'inflected', 'heb', 'לַיִל', '["layil"]', '["[is] from/ [the] night"]', '["n-m"]', 'properly, a twist (away of the light), i.e. night; figuratively, adversity (mid-)night (season).', 'or (Isaiah 21:11) לֵיל; also לַיְלָה; from the same as 3883;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1158}/H9013/[H1158]', 'inflected', 'heb', 'בָּעָה', '["bâʻâh"]', '["you will enquire/ !"]', '["v"]', 'to gush over, i.e. to swell; (figuratively) to desire earnestly; by implication to ask cause, inquire, seek up, swell out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1158}/[H1158]', 'lemma', 'heb', 'בָּעָה', '["bâʻâh"]', '["bulging","enquire","it boils","they will be searched out"]', '["v"]', 'to gush over, i.e. to swell; (figuratively) to desire earnestly; by implication to ask cause, inquire, seek up, swell out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0857}\/[H225]', 'inflected', 'heb', 'אָתָה', '["ʼâthâh"]', '["come"]', '["v"]', 'to arrive (be-, things to) come (upon), bring.', 'or אָתָא; a primitive root (collateral to 225 contraction);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6152A}/[H6150]', 'inflected', 'heb', 'עֲרָב', '["ʻĂrâb"]', '["in/ Arabia","on/ Arabia"]', '["n-m"]', 'Arab (i.e. Arabia), a country East of Palestine Arabia.', 'or עֲרַב; from 6150 in the figurative sense of sterility;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1720}/[H1719]', 'lemma', 'heb', 'דְּדָנִים', '["Dᵉdânîym"]', '["Dedanites"]', '["a"]', 'Dedanites, the descendants or inhabitants of Dedan Dedanim.', 'plural of 1719 (as patrial);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3899H}/H9023/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["with/ bread/ his"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6440G}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["and/ from/ before"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1406}/[H1342]', 'inflected', 'heb', 'גָּג', '["gâg"]', '["to the/ roofs"]', '["n-m"]', 'a roof; by analogy, the top of an altar roof (of the house), (house) top (of the house).', 'probably by reduplication from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2491A}/H9022/[H2490]', 'inflected', 'heb', 'חָלָל', '["châlâl"]', '["slain [ones]/ your"]', '["n-m"]', 'pierced (especially to death); figuratively, polluted kill, profane, slain (man), × slew, (deadly) wounded.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7101}/H9022/[H7096]', 'inflected', 'heb', 'קָצִין', '["qâtsîyn"]', '["rulers/ your"]', '["n-m"]', 'a magistrate (as deciding) or other leader captain, guide, prince, ruler. Compare 6278.', 'from 7096 in the sense of determining;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7198}/[H7185]', 'inflected', 'heb', 'קֶשֶׁת', '["qesheth"]', '["from/ a bow"]', '["n-f"]', 'a bow, for shooting (hence, figuratively, strength) or the iris × arch(-er), arrow, bow(-man, -shot).', 'from 7185 in the original sense (of 6983) of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4672}/H9032/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["found [ones]/ your"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3998}/[H943]', 'inflected', 'heb', 'מְבוּכָה', '["mᵉbûwkâh"]', '["and/ confusion"]', '["n-f"]', 'perplexity perplexity.', 'from 943;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6979C}/[H7023]', 'lemma', 'heb', 'קוּר', '["qûwr"]', '["a breaking down of"]', '["v"]', 'to trench; by implication, to throw forth; to wall up, whether literal (to build a wall) or figurative (to estop) break down, cast out, destroy, dig.', 'a primitive root; also denominative from 7023');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7771B}/[H7768]', 'inflected', 'heb', 'שׁוֹעַ', '["shôwaʻ"]', '["and/ a crying out"]', '["n-m"]', 'a noble, i.e. liberal, opulent; also (as noun in the derived sense) a halloo bountiful, crying, rich.', 'from 7768 in the original sense of freedom;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5867A}/[H5956]', 'inflected', 'heb', 'עֵילָם', '["ʻÊylâm"]', '["and/ Elam"]', '["n-pr-m n-pr-loc"]', 'Elam, a son of Shem and his descendants, with their country; also of six Israelites Elam.', 'or עוֹלָם; (Ezra 10:2; Jeremiah 49:36), probably from 5956; hidden, i.e. distant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7024B}/[H7023]', 'inflected', 'heb', 'קִיר', '["Qîyr"]', '["and/ Kir"]', '["n-pr-loc"]', 'Kir, a place in Assyrian; also one in Moab Kir. Compare 7025.', 'the same as 7023; fortress;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6010R}/H9022/[H6009]', 'inflected', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["valley/ your","valleys/ your"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6571B}/[H6567]', 'inflected', 'heb', 'פָּרָשׁ', '["pârâsh"]', '["and/ the/ horsemen"]', '["n-m"]', 'a steed (as stretched out to a vehicle, not single nor for mounting ); also (by implication) a driver (in a chariot), i.e. (collectively) cavalry horseman.', 'from 6567; (compare 5483)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004J}/[H1129]', 'lemma', 'heb', 'בַּיִת', '["bayith"]', '["[the] House of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3293I>', 'inflected', 'heb', 'היער', '["hai./Ya.''ar"]', '["the/ Forest"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1233}/[H1234]', 'lemma', 'heb', 'בְּקִיעַ', '["bᵉqîyaʻ"]', '["[the] breaches of","rubble<s>"]', '["n-m"]', 'a fissure breach, cleft.', 'from 1234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1219}/[H1210]', 'inflected', 'heb', 'בָּצַר', '["bâtsar"]', '["to/ fortify"]', '["v"]', 'to gather grapes; also to be isolated (i.e. inaccessible by height or fortification) cut off, (de-) fenced, fortify, (grape) gather(-er), mighty things, restrain, strong, wall (up), withhold.', 'a primitive root; to clip off; specifically (as denominative from 1210)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4724}/[H4723]', 'inflected', 'heb', 'מִקְוָה', '["miqvâh"]', '["and/ a reservoir"]', '["n-f"]', 'a collection, i.e. (of water) a reservoir ditch.', 'feminine of 4723;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3465H}/[H3462]', 'inflected', 'heb', 'יָשָׁן', '["yâshân"]', '["<the>/ old"]', '["a"]', 'old old.', 'from 3462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213H}/H9034/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["[the] [one who] made/ it","[who] made/ it"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3335I}/H9034/[H3334]', 'inflected', 'heb', 'יָצַר', '["yâtsar"]', '["and/ [the] [one who] planned/ it"]', '["v"]', 'to mould into a form; especially as a potter; figuratively, to determine (i.e. form a resolution) × earthen, fashion, form, frame, make(-r), potter, purpose.', 'probably identical with 3334 (through the squeezing into shape); (compare 3331);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4553}/[H5594]', 'inflected', 'heb', 'מִסְפֵּד', '["miçpêd"]', '["and/ for/ wailing"]', '["n-m"]', 'a lamentation lamentation, one mourneth, mourning, wailing.', 'from 5594;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7144}/[H7139]', 'inflected', 'heb', 'קׇרְחָה', '["qorchâh"]', '["and/ for/ baldness"]', '["n-f"]', 'baldness bald(-ness), × utterly.', 'or קׇרְחָא; (Ezekiel 27:31), from 7139;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2296}/[H2296]', 'inflected', 'heb', 'חָגַר', '["châgar"]', '["and/ for/ girding of"]', '["v"]', 'to gird on (as a belt, armor, etc.) be able to put on, be afraid, appointed, gird, restrain, × on every side.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5532}/[H5532]', 'inflected', 'heb', 'סָכַן', '["çâkan"]', '["the/ steward"]', '["v"]', 'to be familiar with; by implication, to minister to, be serviceable to, to cherish, be customary acquaint (self), be advantage, × ever, (be, (un-)) profit(-able), treasurer, be wont.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7644>', 'opaque', 'heb', 'שֶׁבְנָא', '["Shebnâʼ"]', '["Shebna"]', '["n-pr-m"]', 'Shebna or Shebnah, an Israelite Shebna, Shebnah.', 'or שֶׁבְנָה; from an unused root meaning to grow; growth;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2904}/H9031/[H2904]', 'inflected', 'heb', 'טוּל', '["ṭûwl"]', '["I will throw/ you","[is] about to hurl away/ you"]', '["v"]', 'to pitch over or reel; hence (transitively) to cast down or out carry away, (utterly) cast (down, forth, out), send out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2925}/[H2904]', 'lemma', 'heb', 'טַלְטֵלָה', '["ṭalṭêlâh"]', '["hurling"]', '["n-f"]', 'overthrow or rejection captivity.', 'from 2904;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5844B}/H9031/[H5844]', 'inflected', 'heb', 'עָטָה', '["ʻâṭâh"]', '["and/ [is] about to grasp/ you"]', '["v"]', 'to wrap, i.e. cover, veil, clothe, or roll array self, be clad, (put a) cover (-ing, self), fill, put on, × surely, turn aside.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5844B}/[H5844]', 'lemma', 'heb', 'עָטָה', '["ʻâṭâh"]', '["completely <to grasp>"]', '["v"]', 'to wrap, i.e. cover, veil, clothe, or roll array self, be clad, (put a) cover (-ing, self), fill, put on, × surely, turn aside.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6801}/H9031/[H6801]', 'inflected', 'heb', 'צָנַף', '["tsânaph"]', '["he will wind up/ you"]', '["v"]', 'to wrap, i.e. roll or dress be attired, × surely, violently turn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6802}/[H6801]', 'lemma', 'heb', 'צְנֵפָה', '["tsᵉnêphâh"]', '["a winding"]', '["n-f"]', 'a ball × toss.', 'from 6801;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1754B}/[H1752]', 'lemma', 'heb', 'דּוּר', '["dûwr"]', '["a ball"]', '["n-m"]', 'a circle, ball or pile ball, turn, round about.', 'from 1752;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1920}/H9031/[H1920]', 'inflected', 'heb', 'הָדַף', '["hâdaph"]', '["and/ I will push/ you"]', '["v"]', 'to push away or down cast away (out), drive, expel, thrust (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4673}/H9021/[H5324]', 'inflected', 'heb', 'מַצָּב', '["matstsâb"]', '["from/ office/ your"]', '["n-m"]', 'a fixed spot; figuratively, an office, a military post garrison, station, place where...stood.', 'from 5324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4612}/H9021/[H5975]', 'inflected', 'heb', 'מַעֲמָד', '["maʻămâd"]', '["and/ from/ post/ your"]', '["n-m"]', '(figuratively) a position attendance, office, place, state.', 'from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2040}/H9031/[H2040]', 'inflected', 'heb', 'הָרַס', '["hâraç"]', '["he will tear down/ you"]', '["v"]', 'to pull down or in pieces, break, destroy beat down, break (down, through), destroy, overthrow, pluck down, pull down, ruin, throw down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0471G}/[H410]', 'inflected', 'heb', 'אֶלְיָקִים', '["ʼElyâqîym"]', '["<to>/ Eliakim"]', '["n-pr-m"]', 'Eljakim, the name of four Israelites Eliakim.', 'from 410 and 6965; God of raising;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3847}/H9033/[H3847]', 'inflected', 'heb', 'לָבַשׁ', '["lâbash"]', '["and/ I will clothe/ him","and/ they clothed/ him"]', '["v"]', 'properly, wrap around, i.e. (by implication) to put on a garment or clothe (oneself, or another), literally or figuratively (in) apparel, arm, array (self), clothe (self), come upon, put (on, upon), wear.', 'or לָבֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3801>/H9021', 'opaque', 'heb', 'כְּתֹנֶת', '["kᵉthôneth"]', '["tunic/ your"]', '["n-f"]', 'a shirt coat, garment, robe.', 'or כֻּתֹּנֶת; from an unused root meaning to cover (compare 3802);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0073>/H9021', 'inflected', 'heb', 'ואבנטך', '["ve./''av.ne.te./Kha"]', '["and/ sash/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4668}/[H6605]', 'lemma', 'heb', 'מַפְתֵּחַ', '["maphtêach"]', '["[the] key of"]', '["n-m"]', 'an opener, i.e. a key key.', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6631}/[H3318]', 'inflected', 'heb', 'צֶאֱצָא', '["tseʼĕtsâʼ"]', '["the/ descendants"]', '["n-m"]', 'issue, i.e. produce, children that which cometh forth (out), offspring.', 'from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6849}/[H6848]', 'inflected', 'heb', 'צְפִעָה', '["tsᵉphiʻâh"]', '["and/ the/ offshoot<s>"]', '["n-f"]', 'an outcast thing issue.', 'feminine from the same as 6848;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0101}/[H5059]', 'inflected', 'heb', 'אַגָּן', '["ʼaggân"]', '["the/ bowls"]', '["n-m"]', 'a bowl (as pounded out hollow) basin, cup, goblet.', 'probably from 5059;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5035A}/[H5034]', 'inflected', 'heb', 'נֶבֶל', '["nebel"]', '["the/ jars"]', '["n-m"]', 'a skin-bag for liquids (from collapsing when empty); hence, a vase (as similar in shape when full); also a lyre (as having a body of like form) bottle, pitcher, psaltery, vessel, viol.', 'or נֵבֶל; from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8628}/[H8628]', 'inflected', 'heb', 'תָּקַע', '["tâqaʻ"]', '["that/ was driven"]', '["v"]', 'to clatter, i.e. slap (the hands together), clang (an instrument); by analogy, to drive (a nail or tent-pin, a dart, etc.); by implication, to become bondsman by handclasping) blow (a trumpet), cast, clap, fasten, pitch (tent), smite, sound, strike, × suretiship, thrust.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1826B}/[H1724]', 'lemma', 'heb', 'דָּמַם', '["dâmam"]', '["be silent"]', '["v"]', 'to be dumb; by implication, to be astonished, to stop; also to perish cease, be cut down (off), forbear, hold peace, quiet self, rest, be silent, keep (put to) silence, be (stand) still, tarry, wait.', 'a primitive root (compare 1724, 1820);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4390}/H9032/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["I will fill/ you","they have filled/ you"]', '["v"]', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly.', 'or מָלָא; (Esther 7:5), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7883G}/[H7835]', 'lemma', 'heb', 'שִׁיחוֹר', '["Shîychôwr"]', '["Shihor"]', '["n-pr-f"]', 'Shichor, a stream of Egypt Shihor, Sihor.', 'or שִׁחוֹר; or שִׁחֹר; probably from 7835; dark, i.e. turbid;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5504}/[H5503]', 'lemma', 'heb', 'סַחַר', '["çachar"]', '["[the] traffic of"]', '["n-m"]', 'profit (from trade) merchandise.', 'from 5503;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8088B}/[H8085]', 'inflected', 'heb', 'שֵׁמַע', '["shêmaʻ"]', '["according to/ a report","like/ [the] report of"]', '["n-m"]', 'something heard, i.e. a sound, rumor, announcement; abstractly, audience bruit, fame, hear(-ing), loud, report, speech, tidings.', 'from 8085;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8659H}/H9011/[H8658]', 'inflected', 'heb', 'תַּרְשִׁישׁ', '["Tarshîysh"]', '["Tarshish/ towards"]', '["n-pr-m n-pr-loc"]', 'Tarshish, a place on the Mediterranean, hence, the ephithet of a merchant vessel (as if for or from that port); also the name of a Persian and of an Israelite Tarshish, Tharshish.', 'probably the same as 8658 (as the region of the stone, or the reverse);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6927}/H9024/[H6923]', 'inflected', 'heb', 'קַדְמָה', '["qadmâh"]', '["beginning/ its"]', '["n-f"]', 'priority (in time); also used adverbially (before) afore, antiquity, former (old) estate.', 'from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2986}/H9034/[H2986]', 'inflected', 'heb', 'יָבַל', '["yâbal"]', '["[which] they have carried/ it"]', '["v"]', 'properly, to flow; causatively, to bring (especially with pomp) bring (forth), carry, lead (forth).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5849B}/[H5849]', 'inflected', 'heb', 'עָטַר', '["ʻâṭar"]', '["which/ bestows crowns"]', '["v"]', 'to encircle (for attack or protection); especially to crown (literally or figuratively) compass, crown.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5503}/H9024/[H5503]', 'inflected', 'heb', 'סָחַר', '["çâchar"]', '["traders/ its"]', '["v"]', 'to travel round (specifically as a pedlar); intensively, to palpitate go about, merchant(-man), occupy with, pant, trade, traffick.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3667B}/H9024/[H3665]', 'inflected', 'heb', 'כְּנַעַן', '["Kᵉnaʻan"]', '["merchants/ its"]', '["n-pr-m n-pr-loc n-m"]', 'Kenaan, a son a Ham; also the country inhabited by him Canaan, merchant, traffick.', 'from 3665; humiliated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3289}/H9034/[H3289]', 'inflected', 'heb', 'יָעַץ', '["yâʻats"]', '["he planned/ it"]', '["v"]', 'to advise; reflexively, to deliberate or resolve advertise, take advise, advise (well), consult, (give, take) counsel(-lor), determine, devise, guide, purpose.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0776G>/H9022', 'opaque', 'heb', 'אֶרֶץ', '["ʼerets"]', '["land/ your"]', '["n-f"]', 'the earth (at large, or partitively a land) × common, country, earth, field, ground, land, × natins, way, + wilderness, world.', 'from an unused root probably meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2975G}/[H2975]', 'inflected', 'heb', 'יְאֹר', '["yᵉʼôr"]', '["[who] like the/ River","like the/ River","like the/ light","like/ [the] River"]', '["n-m"]', 'a channel, e.g. a fosse, canal, shaft; specifically the Nile, as the one river of Egypt, including its collateral trenches; also the Tigris, as the main river of Assyria brook, flood, river, stream.', 'of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4206A}/[H2118]', 'lemma', 'heb', 'מָזִיחַ', '["mâzîyach"]', '["[is] a restraint"]', '["n-m"]', 'a belt (as movable) girdle, strength.', 'or מֵזַח; from 2118;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4581}/H9024/[H5810]', 'inflected', 'heb', 'מָעוֹז', '["mâʻôwz"]', '["strongholds/ its"]', '["n-m"]', 'a fortified place; figuratively, a defence force, fort(-ress), rock, strength(-en), (× most) strong (hold).', '(also מָעוּז ); or מָעֹז (also מָעֻז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5937}/[H5937]', 'inflected', 'heb', 'עָלַז', '["ʻâlaz"]', '["to/ exult"]', '["v"]', 'to jump for joy, i.e. exult be joyful, rejoice, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6231}/[H6229]', 'inflected', 'heb', 'עָשַׁק', '["ʻâshaq"]', '["O/ oppressed [one]","who/ oppress"]', '["v"]', 'to press upon, i.e. oppress, defraud, violate, overflow get deceitfully, deceive, defraud, drink up, (use) oppress(-ion), -or), do violence (wrong).', 'a primitive root (compare 6229);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0971}/H9023/[H975]', 'inflected', 'heb', 'בַּחִין', '["bachîyn"]', '["siege-towers/ its"]', '["n-m"]', 'a watch-tower of besiegers tower.', 'another form of 975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6209}/[H6209]', 'lemma', 'heb', 'עָרַר', '["ʻârar"]', '["it will be demolished","they stripped bare","utterly <demolish>"]', '["v"]', 'to bare; figuratively, to demolish make bare, break, raise up (perhaps by clerical error for raze), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7760A}/H9034/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["I have set/ it","I will make/ it","he has made/ it","it made/ it"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4654B}/[H5307]', 'inflected', 'heb', 'מַפָּלָה', '["mappâlâh"]', '["<into>/ a ruin","into/ a ruin"]', '["n-f"]', 'something fallen, i.e. a ruin ruin(-ous).', 'or מַפֵּלָה; from 5307;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4581}/H9027\/[H5810]', 'inflected', 'heb', 'מָעוֹז', '["mâʻôwz"]', '["stronghold/ your"]', '["n-m"]', 'a fortified place; figuratively, a defence force, fort(-ress), rock, strength(-en), (× most) strong (hold).', '(also מָעוּז ); or מָעֹז (also מָעֻז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6865}/[H6864]', 'inflected', 'heb', 'צֹר', '["Tsôr"]', '["to/ Tyre"]', '["n-pr-loc"]', 'Tsor, a place in Palestine Tyre, Tyrus.', 'or צוֹר; the same as 6864; a rock;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7892B}/[H7891]', 'inflected', 'heb', 'שִׁיר', '["shîyr"]', '["like/ [the] song of"]', '["n-m n-f"]', 'a song; abstractly, singing musical(-ick), × sing(-er, -ing), song.', 'or feminine שִׁירָה; from 7891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0868}/H9024/[H866]', 'inflected', 'heb', 'אֶתְנַן', '["ʼethnan"]', '["to/ hire/ its"]', '["n-m"]', 'a gift (as the price of harlotry or idolatry) hire, reward.', 'the same as 866;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0868}/H9024/[H866]', 'inflected', 'heb', 'אֶתְנַן', '["ʼethnan"]', '["and/ hire/ its"]', '["n-m"]', 'a gift (as the price of harlotry or idolatry) hire, reward.', 'the same as 866;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2630}/[H2630]', 'lemma', 'heb', 'חָסַן', '["châçan"]', '["it will be hoarded"]', '["v"]', 'properly, to (be) compact; by implication, to hoard lay up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7654}/[H7648]', 'inflected', 'heb', 'שׇׂבְעָה', '["sobʻâh"]', '["to/ satiety"]', '["n-f"]', 'satiety (to have) enough, × till...be full, (un-) satiable, satisfy, × sufficiently.', 'feminine of 7648;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4374}/[H3680]', 'inflected', 'heb', 'מְכַסֶּה', '["mᵉkaççeh"]', '["and/ for/ covering"]', '["n-m"]', 'a covering, i.e. garment; specifically, a coverlet (for a bed), an awning (from the sun); also the omentum (as covering the intestines) clothing, to cover, that which covereth.', 'from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6266}\/[H6275]', 'inflected', 'heb', 'עָתִיק', '["ʻâthîyq"]', '["magnificent"]', '["a"]', 'properly, antique, i.e. venerable or splendid durable.', 'from 6275;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1238B}/[H1238]', 'lemma', 'heb', 'בָּקַק', '["bâqaq"]', '["[is] about to lay waste","certainly <to be laid waste>","it will be laid waste"]', '["v"]', 'to pour out, i.e. to empty, figuratively, to depopulate; by analogy, to spread out (as a fruitful vine) (make) empty (out), fail, × utterly, make void.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1110}/H9034/[H1110]', 'inflected', 'heb', 'בָּלַק', '["bâlaq"]', '["and/ [is] about to devastate/ it"]', '["v"]', 'to annihilate (make) waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5753A}/[H5753]', 'inflected', 'heb', 'עָוָה', '["ʻâvâh"]', '["and/ he will twist"]', '["v"]', 'to crook, literally or figuratively do amiss, bow down, make crooked, commit iniquity, pervert, (do) perverse(-ly), trouble, × turn, do wickedly, do wrong.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440J}/H9024/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["surface/ its"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3548}/[H3547]', 'inflected', 'heb', 'כֹּהֵן', '["kôhên"]', '["as the/ priest"]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H0113>/H9023', 'inflected', 'heb', 'כאדניו', '["ka./do.Na/v"]', '["as/ master<s>/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H8198>', 'inflected', 'heb', 'כשפחה', '["ka./shif.Chah"]', '["as the/ maidservant"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1404}/H9024/[H1376]', 'inflected', 'heb', 'גְּבֶרֶת', '["gᵉbereth"]', '["as <the>/ mistress/ her"]', '["n-f"]', 'mistress lady, mistress.', 'feminine of 1376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7069}/[H7069]', 'inflected', 'heb', 'קָנָה', '["qânâh"]', '["as the/ buyer"]', '["v"]', 'to erect, i.e. create; by extension, to procure, especially by purchase (causatively, sell); by implication to own attain, buy(-er), teach to keep cattle, get, provoke to jealousy, possess(-or), purchase, recover, redeem, × surely, × verily.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4376}/[H4376]', 'inflected', 'heb', 'מָכַר', '["mâkar"]', '["as the/ seller"]', '["v"]', 'to sell, literally (as merchandise, a daughter in marriage, into slavery), or figuratively (to surrender) × at all, sell (away, -er, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3867B}/[H3867]', 'inflected', 'heb', 'לָוָה', '["lâvâh"]', '["as the/ borrower","as the/ lender"]', '["v"]', 'properly, to twine, i.e. (by implication) to unite, to remain; also to borrow (as a form of obligation) or (caus.) to lend abide with, borrow(-er), cleave, join (self), lend(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8354}/H9033/[H8354]', 'inflected', 'heb', 'שָׁתָה', '["shâthâh"]', '["to/ [those who] drink/ it"]', '["v"]', 'to imbibe (literally or figuratively) × assuredly, banquet, × certainly, drink(-er, -ing), drunk (× -ard), surely. (Prop. intensive of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6150}/[H6148]', 'lemma', 'heb', 'עָרַב', '["ʻârab"]', '["it has become evening"]', '["v"]', 'to grow dusky at sundown be darkened, (toward) evening.', 'a primitive root (rather identical with 6148 through the idea of covering with a texture);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7591}/[H7582]', 'inflected', 'heb', 'שְׁאִיָּה', '["shᵉʼîyâh"]', '["and/ ruin"]', '["n-f"]', 'desolation destruction.', 'from 7582;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5955}/[H5953]', 'inflected', 'heb', 'עֹלֵלָה', '["ʻôlêlâh"]', '["like/ gleanings","like/ gleanings of"]', '["n-f"]', 'only in plural gleanings; by extension gleaning-time (gleaning) (of the) grapes, grapegleanings.', 'feminine active participle of 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0217B}/[H215]', 'inflected', 'heb', 'אוּר', '["ʼûwr"]', '["in the/ east"]', '["n-m"]', 'flame; hence (in the plural) the East (as being the region of light) fire, light. See also 224.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0339}/[H183]', 'inflected', 'heb', 'אִי', '["ʼîy"]', '["in the/ islands","in/ [the] islands of"]', '["n-m"]', 'properly, a habitable spot (as desirable); dry land, a coast, an island country, isle, island.', 'from 183;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3671}/[H3670]', 'inflected', 'heb', 'כָּנָף', '["kânâph"]', '["from/ [the] extremity of"]', '["n-f"]', 'an edge or extremity; specifically (of a bird or army) a wing, (of a garment or bedclothing) a flap, (of the earth) a quarter, (of a building) a pinnacle bird, border, corner, end, feather(-ed), × flying, (one an-) other, overspreading, × quarters, skirt, × sort, uttermost part, wing(-ed).', 'from 3670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7334}/[H7329]', 'lemma', 'heb', 'רָזִי', '["râzîy"]', '["leanness"]', '["n-m"]', 'thinness leanness.', 'from 7329;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0899A}/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["and/ treachery"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6354>', 'inflected', 'heb', 'ופחת', '["va./Fa.chat"]', '["and/ a pit","and/ pit"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6341A}/[H6351]', 'inflected', 'heb', 'פַּח', '["pach"]', '["and/ snare","and/ snares"]', '["n-m"]', 'a (metallic) sheet (as pounded thin); also a spring net (as spread out like a lamina) gin, (thin) plate, snare.', 'from 6351;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6343}/[H6342]', 'inflected', 'heb', 'פַּחַד', '["pachad"]', '["the/ dread","the/ terror"]', '["n-m"]', 'a (sudden) alarm (properly, the object feared, by implication, the feeling) dread(-ful), fear, (thing) great (fear, -ly feared), terror.', 'from 6342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5927G}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["and/ the/ [one who] climbs up","and/ the/ [one who] goes up","and/ the/ [thing which] comes up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6588}/H9024/[H6586]', 'inflected', 'heb', 'פֶּשַׁע', '["peshaʻ"]', '["transgression/ its","transgressions/ her"]', '["n-m"]', 'a revolt (national, moral or religious) rebellion, sin, transgression, trespass.', 'from 6586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965B}\/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["to rise"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4791}/[H7311]', 'inflected', 'heb', 'מָרוֹם', '["mârôwm"]', '["the/ height"]', '["n-m"]', 'altitude, i.e. concretely (an elevated place), abstractly (elevation, figuratively (elation), or adverbially (aloft) (far) above, dignity, haughty, height, (most, on) high (one, place), loftily, upward.', 'from 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0626}/[H622]', 'lemma', 'heb', 'אֲסֵפָה', '["ʼăçêphâh"]', '["a gathering"]', '["n-f"]', 'a collection of people (only adverbial) × together.', 'from 622;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4525}/[H5462]', 'lemma', 'heb', 'מַסְגֵּר', '["maçgêr"]', '["a prison"]', '["n-m"]', 'a fastener, i.e. (of a person) a smith, (of a thing) a prison prison, smith.', 'from 5462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H7230}/[H7231]', 'inflected', 'heb', 'רֹב', '["rôb"]', '["and/ from/ an abundance of"]', '["n-m"]', 'abundance (in any respect) abundance(-antly), all, × common (sort), excellent, great(-ly, -ness, number), huge, be increased, long, many, more in number, most, much, multitude, plenty(-ifully), × very (age).', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3842}/[H3835]', 'inflected', 'heb', 'לְבָנָה', '["lᵉbânâh"]', '["the/ moon"]', '["n-f"]', 'properly, (the) white, i.e. the moon moon. See also 3838.', 'from 3835;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2535}/[H2525]', 'inflected', 'heb', 'חַמָּה', '["chammâh"]', '["the/ sun"]', '["n-f"]', 'heat; by implication, the sun heat, sun.', 'from 2525;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2205G}/H9023/[H2204]', 'inflected', 'heb', 'זָקֵן', '["zâqên"]', '["elders/ his"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0544}/[H539]', 'lemma', 'heb', 'אֹמֶן', '["ʼômen"]', '["faithfulness"]', '["n-m"]', 'verity truth.', 'from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2230}/[H2229]', 'inflected', 'heb', 'זֶרֶם', '["zerem"]', '["[is] like/ a rainstorm of","like/ a storm of"]', '["n-m"]', 'a gush of water flood, overflowing, shower, storm, tempest.', 'from 2229;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2721A}/[H2719]', 'inflected', 'heb', 'חֹרֶב', '["chôreb"]', '["like/ heat"]', '["n-m"]', 'drought or desolation desolation, drought, dry, heat, × utterly, waste.', 'a collaterally form of 2719;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6724}/[H6723]', 'inflected', 'heb', 'צִיוֹן', '["tsîyôwn"]', '["in/ a dry land"]', '["n-m"]', 'a desert dry place.', 'from the same as 6723;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6031B}\/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["he will quieten"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8105}/[H8104]', 'lemma', 'heb', 'שֶׁמֶר', '["shemer"]', '["old wine<s>"]', '["n-m"]', 'something preserved, i.e. the settlings (plural only) of wine dregs, (wines on the) lees.', 'from 8104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4229C}/[H4229]', 'lemma', 'heb', 'מָחָה', '["mâchâh"]', '["full of marrow"]', '["v"]', 'properly, to stroke or rub; by implication, to erase; also to smooth (as if with oil), i.e. grease or make fat; also to touch, i.e. reach to abolish, blot out, destroy, full of marrow, put out, reach unto, × utterly, wipe (away, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3875}/[H3874]', 'inflected', 'heb', 'לוֹט', '["lôwṭ"]', '["the/ covering"]', '["n-m"]', 'a veil covering.', 'from 3874;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3874}/[H3874]', 'inflected', 'heb', 'לוּט', '["lûwṭ"]', '["which/ covers"]', '["v"]', 'to wrap up cast, wrap.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4541B}/[H5258]', 'inflected', 'heb', 'מַסֵּכָה', '["maççêkâh"]', '["and/ the/ blanket","and/ the/ woven stuff"]', '["n-f"]', 'properly, a pouring over, i.e. fusion of metal (especially a cast image); by implication, a libation, i.e. league; concretely a coverlet (as if poured out) covering, molten (image), vail.', 'from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5259}/[H5258]', 'inflected', 'heb', 'נָסַךְ', '["nâçak"]', '["which/ is woven"]', '["v"]', 'to interweave, i.e. (figuratively) to overspread that is spread.', 'a primitive root (probably identical with 5258 through the idea of fusion);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1758}/[H1758]', 'inflected', 'heb', 'דּוּשׁ', '["dûwsh"]', '["as/ is trampled down"]', '["v"]', 'to trample or thresh break, tear, thresh, tread out (down), at grass (Jeremiah 50:11, by mistake for 1877).', 'or דּוֹשׁ; or דִּישׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4963}/[H8401]', 'lemma', 'heb', 'מַתְבֵּן', '["mathbên"]', '["a heap of straw"]', '["n-m"]', 'straw in the heap straw.', 'denominative from 8401;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4087}/[H1828]', 'lemma', 'heb', 'מַדְמֵנָה', '["madmênâh"]', '["a dung hill"]', '["n-f"]', 'a dunghill dunghill.', 'feminine from the same as 1828;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7811}/[H7811]', 'inflected', 'heb', 'שָׂחָה', '["sâchâh"]', '["<the>/ swimmer"]', '["v"]', 'to swim; causatively, to inundate (make to) swim.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7811}/[H7811]', 'inflected', 'heb', 'שָׂחָה', '["sâchâh"]', '["to/ swim"]', '["v"]', 'to swim; causatively, to inundate (make to) swim.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0698}/[H696]', 'lemma', 'heb', 'אׇרֳבָה', '["ʼorŏbâh"]', '["[the] tricks of"]', '["n-f"]', 'ambuscades spoils.', 'feminine of 696 (only in the plural);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4013}/[H1219]', 'inflected', 'heb', 'מִבְצָר', '["mibtsâr"]', '["and/ [the] fortification of"]', '["n-m"]', 'a fortification, castle, or fortified city; figuratively, a defender (de-, most) fenced, fortress, (most) strong (hold).', 'also (in plural) feminine (Daniel 11:l5) מִבְצָרָה; from 1219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6083}\/[H6080]', 'inflected', 'heb', 'עָפָר', '["ʻâphâr"]', '["[the] dust"]', '["n-m"]', 'dust (as powdered or gray); hence, clay, earth, mud ashes, dust, earth, ground, morter, powder, rubbish.', 'from 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2426}/[H2428]', 'inflected', 'heb', 'חֵיל', '["chêyl"]', '["and/ a rampart"]', '["n-m"]', 'an army; also (by analogy,) an intrenchment army, bulwark, host, poor, rampart, trench, wall.', 'or (shortened) חֵל; a collateral form of 2428;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8213}/H9034/[H8213]', 'inflected', 'heb', 'שָׁפֵל', '["shâphêl"]', '["he will bring low/ it"]', '["v"]', 'to depress or sink (especially figuratively, to humiliate, intransitive or transitive) abase, bring (cast, put) down, debase, humble (self), be (bring, lay, make, put) low(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5060}/H9034/[H5060]', 'inflected', 'heb', 'נָגַע', '["nâgaʻ"]', '["he will make touch/ it"]', '["v"]', 'properly, to touch, i.e. lay the hand upon (for any purpose; euphemistically, to lie with a woman); by implication, to reach (figuratively, to arrive, acquire); violently, to strike (punish, defeat, destroy, etc.) beat, (× be able to) bring (down), cast, come (nigh), draw near (nigh), get up, happen, join, near, plague, reach (up), smite, strike, touch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7429}/H9034/[H7429]', 'inflected', 'heb', 'רָמַס', '["râmaç"]', '["it will trample/ it"]', '["v"]', 'to tread upon (as a potter, in walking or abusively) oppressor, stamp upon, trample (under feet), tread (down, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2143}/H9021/[H2142]', 'inflected', 'heb', 'זֵכֶר', '["zêker"]', '["and/ for/ memory/ your"]', '["n-m"]', 'a memento, abstractly recollection (rarely if ever); by implication, commemoration memorial, memory, remembrance, scent.', 'or זֶכֶר; from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0183}/H9031/[H183]', 'inflected', 'heb', 'אָוָה', '["ʼâvâh"]', '["I have desired/ you"]', '["v"]', 'to wish for covet, (greatly) desire, be desirous, long, lust (after).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5229}/[H5228]', 'lemma', 'heb', 'נְכֹחָה', '["nᵉkôchâh"]', '["straightforwardness","straightforwardness<es>"]', '["a-f"]', 'properly, straightforwardness, i.e. (figuratively) integrity, or (concretely) a truth equity, right (thing), uprightness.', 'feminine of 5228;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2372}/H9013/[H2372]', 'inflected', 'heb', 'חָזָה', '["châzâh"]', '["they behold/ !"]', '["v"]', 'to gaze at; mentally to perceive, contemplate (with pleasure); specifically, to have a vision of behold, look, prophesy, provide, see.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0398}/H9038\/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["it will consume/ them"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4639K}/H9025/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["works/ our"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1166H}/H9035/[H1167]', 'inflected', 'heb', 'בָּעַל', '["bâʻal"]', '["they have ruled over/ us"]', '["v"]', 'to be master; hence, to marry have dominion (over), be husband, marry(-ried, × wife).', 'a primitive root; also as denominative from 1167');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6485I}/H9031/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["people sought/ you"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6694}/H9013/[H6694]', 'inflected', 'heb', 'צוּק', '["tsûwq"]', '["they poured out/ !"]', '["v"]', 'to pour out, i.e. (figuratively) smelt, utter be molten, pour.', 'a primitive root (identical with through the idea of narrowness (of orifice));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4148G}/H9021/[H3256]', 'inflected', 'heb', 'מוּסָר', '["mûwçâr"]', '["chastening/ your"]', '["n-m"]', 'properly, chastisement; figuratively, reproof, warning or instruction; also restraint bond, chastening(-eth), chastisement, check, correction, discipline, doctrine, instruction, rebuke.', 'from 3256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2256B}/H9024/[H2254]', 'inflected', 'heb', 'חֶבֶל', '["chebel"]', '["in/ labor-pains/ her"]', '["n-m"]', 'a rope (as twisted), especially a measuring line; by implication, a district or inheritance (as measured); or a noose (as of cords); figuratively, a company (as if tied together); a throe (especially of parturition); also ruin band, coast, company, cord, country, destruction, line, lot, pain, pang, portion, region, rope, snare, sorrow, tackling.', 'or חֵבֶל; from 2254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6440I}/H9021/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<from>/ because of/ you"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5038}/H9020/[H5034]', 'inflected', 'heb', 'נְבֵלָה', '["nᵉbêlâh"]', '["corpse/ my"]', '["n-f"]', 'a flabby thing, i.e. a carcase or carrion (human or bestial, often collectively); figuratively, an idol (dead) body, (dead) carcase, dead of itself, which died, (beast) that (which) dieth of itself.', 'from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2919}/H9021/[H2926]', 'inflected', 'heb', 'טַל', '["ṭal"]', '["dew/ your"]', '["n-m"]', 'dew (as covering vegetation) dew.', 'from 2926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5307H}\/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["it will make fall"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2315}/H9021/[H2314]', 'inflected', 'heb', 'חֶדֶר', '["cheder"]', '["in/ rooms/ your"]', '["n-m"]', 'an apartment (usually literal) ((bed) inner) chamber, innermost(-ward) part, parlour, south, × within.', 'from 2314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1817B}/H9021/[H1802]', 'inflected', 'heb', 'דֶּלֶת', '["deleth"]', '["door/ your"]', '["n-m n-f"]', 'something swinging, i.e. the valve of a door door (two-leaved), gate, leaf, lid. (Psalm 141:3).', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2247}/[H2245]', 'lemma', 'heb', 'חָבָה', '["châbâh"]', '["hide"]', '["v"]', 'to secrete hide (self).', 'a primitive root (compare 2245);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2026}/H9024\/[H2026]', 'inflected', 'heb', 'הָרַג', '["hârag"]', '["slain [ones]/ its"]', '["v"]', 'to smite with deadly intent destroy, out of hand, kill, murder(-er), put to (death), make (slaughter), slay(-er), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2719}/H9023/[H2717]', 'inflected', 'heb', 'חֶרֶב', '["chereb"]', '["with/ sword/ his","with/ swords/ his"]', '["n-f"]', 'drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2389}/[H2388]', 'inflected', 'heb', 'חָזָק', '["châzâq"]', '["and/ <the>/ mighty"]', '["a"]', 'strong (usu. in a bad sense, hard, bold, violent) harder, hottest, impudent, loud, mighty, sore, stiff(-hearted), strong(-er).', 'from 2388;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6129}/[H6127]', 'lemma', 'heb', 'עֲקַלָּתוֹן', '["ʻăqallâthôwn"]', '["twisting"]', '["a"]', 'tortuous crooked.', 'from 6127;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2531}/[H2530]', 'lemma', 'heb', 'חֶמֶד', '["chemed"]', '["delight","desire"]', '["n-m"]', 'delight desirable, pleasant.', 'from 2530;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8248G}/H9034/[H8248]', 'inflected', 'heb', 'שָׁקָה', '["shâqâh"]', '["I water/ it"]', '["v"]', 'to quaff, i.e. (causatively) to irrigate or furnish a potion to cause to (give, give to, let, make to) drink, drown, moisten, water. See 7937, 8354.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7898}/[H7896]', 'lemma', 'heb', 'שַׁיִת', '["shayith"]', '["bush[es]"]', '["n-m"]', 'scrub or trash, i.e. wild growth of weeds or briers (as if put on the field) thorns.', 'from 7896;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6585}/[H6585]', 'lemma', 'heb', 'פָּשַׂע', '["pâsaʻ"]', '["I will march"]', '["v"]', 'to stride (from spreading the legs), i.e. rush upon go.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6702}/H9034/[H6702]', 'inflected', 'heb', 'צוּת', '["tsûwth"]', '["I will burn/ it"]', '["v"]', 'to blaze burn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4581}/H9020/[H5810]', 'inflected', 'heb', 'מָעוֹז', '["mâʻôwz"]', '["on/ protection/ my"]', '["n-m"]', 'a fortified place; figuratively, a defence force, fort(-ress), rock, strength(-en), (× most) strong (hold).', '(also מָעוּז ); or מָעֹז (also מָעֻז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6524A}/[H6524]', 'inflected', 'heb', 'פָּרַח', '["pârach"]', '["and/ I make sprout","and/ it sprouts up","and/ it will bud"]', '["v"]', 'to break forth as a bud, i.e. bloom; generally, to spread; specifically, to fly (as extending the wings); figuratively, to flourish × abroad, × abundantly, blossom, break forth (out), bud, flourish, make fly, grow, spread, spring (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8570}\/[H5107]', 'inflected', 'heb', 'תְּנוּבָה', '["tᵉnûwbâh"]', '["fruit"]', '["n-f"]', 'produce fruit, increase.', 'from 5107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9004/{H4347}/[H5221]', 'inflected', 'heb', 'מַכָּה', '["makkâh"]', '["¿/ like/ [the] striking? of"]', '["n-f"]', 'a blow (in 2 Chronicles 2:10, of the flail); by implication, a wound; figuratively, carnage, also pestilence beaten, blow, plague, slaughter, smote, × sore, stripe, stroke, wound(-ed).', 'or (masculine) מַכֶּה; (plural only) from 5221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2027}/[H2026]', 'inflected', 'heb', 'הֶרֶג', '["hereg"]', '["like/ [the] slaughter of"]', '["n-m"]', 'slaughter be slain, slaughter.', 'from 2026;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2026}/H9023/[H2026]', 'inflected', 'heb', 'הָרַג', '["hârag"]', '["slain [ones]/ its"]', '["v"]', 'to smite with deadly intent destroy, out of hand, kill, murder(-er), put to (death), make (slaughter), slay(-er), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5432}/[H5429]', 'inflected', 'heb', 'סַאסְּאָה', '["çaʼçᵉʼâh"]', '["by/ startling"]', '["v"]', 'measurement, i.e. moderation measure.', 'for 5429;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7971M}/H9034/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["by/ sending away/ it"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7378}/H9034/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["you will conduct a case with/ it"]', '["v"]', 'properly, to toss, i.e. grapple; mostly figuratively, to wrangle, i.e. hold a controversy; (by implication) to defend adversary, chide, complain, contend, debate, × ever, × lay wait, plead, rebuke, strive, × thoroughly.', 'or רוּב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7760A}/H9043/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["when/ makes/ he"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1615}/[H3564]', 'lemma', 'heb', 'גִּר', '["gir"]', '["chalk"]', '["n-m"]', 'lime (from being burned in a kiln) chalk(-stone).', 'perhaps from 3564;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5310A}/[H5310]', 'lemma', 'heb', 'נָפַץ', '["nâphats"]', '["pulverized","smashed","they will smash","to smash"]', '["v"]', 'to dash to pieces, or scatter be beaten in sunder, break (in pieces), broken, dash (in pieces), cause to be discharged, dispersed, be overspread, scatter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2553}/[H2535]', 'inflected', 'heb', 'חַמָּן', '["chammân"]', '["and/ incense altars"]', '["n-m"]', 'a sun-pillar idol, image.', 'from 2535;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5585}/H9024/[H5586]', 'inflected', 'heb', 'סָעִיף', '["çâʻîyph"]', '["branches/ its"]', '["n-m"]', 'a fissure (of rocks); also a bough (as subdivided) (outmost) branch, clift, top.', 'from 5586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3001}/[H3001]', 'inflected', 'heb', 'יָבֵשׁ', '["yâbêsh"]', '["when/ dry up"]', '["v"]', 'to be ashamed, confused or disappointed; also (as failing) to dry up (as water) or wither (as herbage) be ashamed, clean, be confounded, (make) dry (up), (do) shame(-fully), × utterly, wither (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7355}/H9033/[H7355]', 'inflected', 'heb', 'רָחַם', '["râcham"]', '["I will have compassion on/ him","he will have compassion on/ it"]', '["v"]', 'to fondle; by implication, to love, especially to compassionate have compassion (on, upon), love, (find, have, obtain, shew) mercy(-iful, on, upon), (have) pity, Ruhamah, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3335G}/H9033/[H3334]', 'inflected', 'heb', 'יָצַר', '["yâtsar"]', '["and/ [the] [one who] formed/ it"]', '["v"]', 'to mould into a form; especially as a potter; figuratively, to determine (i.e. form a resolution) × earthen, fashion, form, frame, make(-r), potter, purpose.', 'probably identical with 3334 (through the squeezing into shape); (compare 3331);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2603A}/H9033\/[H2583]', 'inflected', 'heb', 'חָנַן', '["chânan"]', '["he will show favor to/ it"]', '["v"]', 'properly, to bend or stoop in kindness to an inferior; to favor, bestow; causatively to implore (i.e. move to favor by petition) beseech, × fair, (be, find, shew) favour(-able), be (deal, give, grant (gracious(-ly), intreat, (be) merciful, have (shew) mercy (on, upon), have pity upon, pray, make supplication, × very.', 'a primitive root (compare 2583);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7641G}/[H7640]', 'inflected', 'heb', 'שִׁבֹּל', '["shibbôl"]', '["from/ [the] flowing stream of"]', '["n-f"]', 'a stream (as flowing); also an ear of grain (as growing out); by analogy, a branch branch, channel, ear (of corn), (water-)flood, Shibboleth. Compare 5451.', 'or (feminine) שִׁבֹּלֶת; from the same as 7640;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5080}/[H5080]', 'inflected', 'heb', 'נָדַח', '["nâdach"]', '["and/ the/ [one who is] outcast","and/ the/ outcast [person]","and/ the/ outcasts"]', '["v"]', 'to push off; used in a great variety of applications, literally and figuratively (to expel, mislead, strike, inflict, etc.) banish, bring, cast down (out), chase, compel, draw away, drive (away, out, quite), fetch a stroke, force, go away, outcast, thrust away (out), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6731A}/[H6692]', 'inflected', 'heb', 'צִיץ', '["tsîyts"]', '["and/ a flower"]', '["n-m"]', 'properly, glistening, i.e. a burnished plate; also a flower (as bright colored); a wing (as gleaming in the air) blossom, flower, plate, wing.', 'or צִץ; from 6692;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8597}/H9023/[H6286]', 'inflected', 'heb', 'תִּפְאָרָה', '["tiphʼârâh"]', '["splendor/ his","splendor/ its"]', '["n-f"]', 'ornament (abstractly or concretely, literally or figuratively) beauty(-iful), bravery, comely, fair, glory(-ious), honour, majesty.', 'or תִּפְאֶרֶת; from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8178B}/[H8175]', 'lemma', 'heb', 'שַׂעַר', '["saʻar"]', '["a tempest of"]', '["n-m"]', 'a terror affrighted, × horribly, × sore, storm. See 8181.', 'from 8175;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6986>', 'opaque', 'heb', 'קֶטֶב', '["qeṭeb"]', '["destruction"]', '["n-m"]', 'ruin destroying, destruction.', 'from an unused root meaning to cut off;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6733}/[H6731]', 'lemma', 'heb', 'צִיצָה', '["tsîytsâh"]', '["a flower"]', '["n-m"]', 'a flower flower.', 'feminine of 6731;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1063}/[H1061]', 'inflected', 'heb', 'בִּכּוּרָה', '["bikkûwrâh"]', '["like/ an early fig","like/ early fig[s]"]', '["n-f"]', 'the early fig firstripe (fruit).', 'feminine of 1061;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5750}/H9044/[H5749]', 'inflected', 'heb', 'עוֹד', '["ʻôwd"]', '["while/ still/ it"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1104}/H9034\/[H1104]', 'inflected', 'heb', 'בָּלַע', '["bâlaʻ"]', '["he will swallow/ it"]', '["v"]', 'to make away with (specifically by swallowing); generally, to destroy cover, destroy, devour, eat up, be at end, spend up, swallow down (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5850}/[H5849]', 'inflected', 'heb', 'עֲטָרָה', '["ʻăṭârâh"]', '["<into>/ a crown of"]', '["n-f"]', 'a crown crown.', 'from 5849;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6843}/[H6842]', 'inflected', 'heb', 'צְפִירָה', '["tsᵉphîyrâh"]', '["and/ <into>/ a diadem of"]', '["n-f"]', 'a crown (as encircling the head); also a turn of affairs (i.e. mishap) diadem, morning.', 'feminine formed like 6842;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7307G}/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["and/ <into>/ a spirit of"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1369}/[H1368]', 'inflected', 'heb', 'גְּבוּרָה', '["gᵉbûwrâh"]', '["and/ <into>/ strength"]', '["n-f"]', 'force (literally or figuratively); by implication, valor, victory force, mastery, might, mighty (act, power), power, strength.', 'feminine passive participle from the same as 1368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8179G}/H9011\/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["[the] gate/ towards"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7941}/[H7937]', 'inflected', 'heb', 'שֵׁכָר', '["shêkâr"]', '["with <the>/ strong drink"]', '["n-m"]', 'an intoxicant, i.e. intensely alcoholic liquor strong drink, drunkard, strong wine.', 'from 7937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7941}/[H7937]', 'inflected', 'heb', 'שֵׁכָר', '["shêkâr"]', '["<the>/ strong drink"]', '["n-m"]', 'an intoxicant, i.e. intensely alcoholic liquor strong drink, drunkard, strong wine.', 'from 7937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7203B}/[H7200]', 'inflected', 'heb', 'רֹאֶה', '["rôʼeh"]', '["in the/ vision"]', '["n-m"]', 'a seer (as often rendered); but also (abstractly) a vision vision.', 'active participle of 7200;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6328}/[H6328]', 'lemma', 'heb', 'פּוּק', '["pûwq"]', '["it will wobble","they tottered"]', '["v"]', 'to waver stumble, move.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6417}/[H6416]', 'lemma', 'heb', 'פְּלִילִיָּה', '["pᵉlîylîyâh"]', '["decision"]', '["n-f"]', 'judicature judgment.', 'feminine of 6416;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6892B}/[H6958]', 'lemma', 'heb', 'קֵא', '["qêʼ"]', '["vomit"]', '["n-m"]', 'vomit vomit.', 'or קִיא; from 6958;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4725}\/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["room"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2461}/[H2459]', 'inflected', 'heb', 'חָלָב', '["châlâb"]', '["from/ milk","more than/ milk"]', '["n-m"]', 'milk (as the richness of kine) cheese, milk, sucking.', 'from the same as 2459;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7699A}/[H7736]', 'inflected', 'heb', 'שַׁד', '["shad"]', '["from/ breasts"]', '["n-m"]', 'the breast of a woman or animal (as bulging) breast, pap, teat.', 'or שֹׁד; probably from 7736 (in its original sense) contracted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6673}/[H6680]', 'lemma', 'heb', 'צַו', '["tsav"]', '["a command","command"]', '["n-m"]', 'an injunction commandment, precept.', 'or צָו; from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6673}/[H6680]', 'inflected', 'heb', 'צַו', '["tsav"]', '["to/ [the] command"]', '["n-m"]', 'an injunction commandment, precept.', 'or צָו; from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6957A}/[H6960]', 'lemma', 'heb', 'קַו', '["qav"]', '["line"]', '["n-m"]', 'a cord (as connecting), especially for measuring; figuratively, a rule; also a rim, a musical string or accord line. Compare 6978.', 'or קָו; from 6960 (compare 6961);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6957A}/[H6960]', 'inflected', 'heb', 'קַו', '["qav"]', '["to/ [the] line"]', '["n-m"]', 'a cord (as connecting), especially for measuring; figuratively, a rule; also a rim, a musical string or accord line. Compare 6978.', 'or קָו; from 6960 (compare 6961);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3934}/[H3932]', 'inflected', 'heb', 'לָעֵג', '["lâʻêg"]', '["by/ stammerings of"]', '["a"]', 'a buffoon; also a foreigner mocker, stammering.', 'from 3932;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3956H}/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["and/ by/ a tongue"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5889}/[H5888]', 'inflected', 'heb', 'עָיֵף', '["ʻâyêph"]', '["for/ a weary [animal]","to the/ weary"]', '["a"]', 'languid faint, thirsty, weary.', 'from 5888;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4774}/[H7280]', 'inflected', 'heb', 'מַרְגֵּעָה', '["margêʻâh"]', '["[is] the/ place of rest"]', '["n-f"]', 'rest refreshing.', 'from 7280;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4268}/H9025/[H2620]', 'inflected', 'heb', 'מַחֲסֶה', '["machăçeh"]', '["refuge/ our"]', '["n-m"]', 'a shelter (literally or figuratively) hope, (place of) refuge, shelter, trust.', 'or מַחְסֶה; from 2620;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8267}/[H8266]', 'inflected', 'heb', 'שֶׁקֶר', '["sheqer"]', '["and/ in <the>/ deception"]', '["n-m"]', 'an untruth; by implication, a sham (often adverbial) without a cause, deceit(-ful), false(-hood, -ly), feignedly, liar, lie, lying, vain (thing), wrongfully.', 'from 8266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5641}\/[H5641]', 'inflected', 'heb', 'סָתַר', '["çâthar"]', '["it will hide itself","we have hidden ourselves"]', '["v"]', 'to hide (by covering), literally or figuratively be absent, keep close, conceal, hide (self), (keep) secret, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0976}/[H974]', 'lemma', 'heb', 'בֹּחַן', '["bôchan"]', '["testing"]', '["n-m"]', 'trial tried.', 'from 974;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6957B}/[H6960]', 'inflected', 'heb', 'קַו', '["qav"]', '["<into>/ a measuring-line"]', '["n-m"]', 'a cord (as connecting), especially for measuring; figuratively, a rule; also a rim, a musical string or accord line. Compare 6978.', 'or קָו; from 6960 (compare 6961);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4949}/[H4948]', 'inflected', 'heb', 'מִשְׁקֶלֶת', '["mishqeleth"]', '["<into>/ a leveling tool"]', '["n-f"]', 'a weight, i.e. a plummet (with line attached) plummet.', 'or מִשְׁקֹלֶת; feminine of 4948 or 4947;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3261}/[H3261]', 'inflected', 'heb', 'יָעָה', '["yâʻâh"]', '["and/ it will sweep away"]', '["v"]', 'to brush aside sweep away.', 'a primitive root; apparently');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1285}/H9026/[H1262]', 'inflected', 'heb', 'בְּרִית', '["bᵉrîyth"]', '["covenant/ your"]', '["n-f"]', 'a compact (because made by passing between pieces of flesh) confederacy, (con-) feder(-ate), covenant, league.', 'from 1262 (in the sense of cutting [like 1254]);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2380}/H9026/[H2372]', 'inflected', 'heb', 'חָזוּת', '["châzûwth"]', '["and/ agreement/ your"]', '["n-f"]', 'a look; hence (figuratively) striking appearance, revelation, or (by implication) compact agreement, notable (one), vision.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2113}/[H2111]', 'lemma', 'heb', 'זְוָעָה', '["zᵉvâʻâh"]', '["terror"]', '["n-f"]', 'agitation, fear be removed, trouble, vexation. Compare 2189.', 'from 2111;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4702}/[H3331]', 'inflected', 'heb', 'מַצָּע', '["matstsâʻ"]', '["the/ bed"]', '["n-m"]', 'a couch bed.', 'from 3331;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8311}/[H8311]', 'inflected', 'heb', 'שָׂרַע', '["sâraʻ"]', '["for/ stretching oneself"]', '["v"]', 'to prolong, i.e. (reflex) be deformed by excess of members stretch out self, (have any) superfluous thing.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3664}/[H3664]', 'inflected', 'heb', 'כָּנַס', '["kânaç"]', '["when/ wraps oneself up"]', '["v"]', 'to collect; hence, to enfold gather (together), heap up, wrap self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6559}/[H6556]', 'lemma', 'heb', 'פְּרָצִים', '["pᵉrâtsîym"]', '["Perazim"]', '["n-pr-loc"]', 'Peratsim, a mountain in Palestine Perazim.', 'plural of 6556; breaks;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6010R}/[H6009]', 'inflected', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["like/ a valley"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5647I}/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["and/ to/ work"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5656I}/H9023/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["work/ his"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4147}/H9026/[H3256]', 'inflected', 'heb', 'מוֹסֵר', '["môwçêr"]', '["fetters/ your"]', '["n-m"]', 'properly, chastisement, i.e. (by implication) a halter; figuratively, restraint band, bond.', 'also (in plural) feminine מוֹסֵרָה; or מֹסְרָה; from 3256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3605}/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["¿/ all"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2790A}/[H2790]', 'inflected', 'heb', 'חָרַשׁ', '["chârash"]', '["the/ plowman"]', '["v"]', 'to scratch, i.e. (by implication) to engrave, plough; hence (from the use of tools) to fabricate (of any material); figuratively, to devise (in a bad sense); hence (from the idea of secrecy) to be silent, to let alone; hence (by implication) to be deaf (as an accompaniment of dumbness) × altogether, cease, conceal, be deaf, devise, ear, graven, imagine, leave off speaking, hold peace, plow(-er, man), be quiet, rest, practise secretly, keep silence, be silent, speak not a word, be still, hold tongue, worker.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2232}/[H2232]', 'inflected', 'heb', 'זָרַע', '["zâraʻ"]', '["to the/ sower","to/ sow"]', '["v"]', 'to sow; figuratively, to disseminate, plant, fructify bear, conceive seed, set with sow(-er), yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7702}/[H7702]', 'inflected', 'heb', 'שָׂדַד', '["sâdad"]', '["and/ he may harrow?"]', '["v"]', 'to abrade, i.e. harrow a field break clods, harrow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7100>', 'opaque', 'heb', 'קֶצַח', '["qetsach"]', '["black cumin"]', '["n-m"]', 'fennel-flower (from its pungency) fitches.', 'from an unused root apparently meaning to incise;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3646>', 'inflected', 'heb', 'וכמן', '["ve./kha.Mon"]', '["and/ cumin"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7795}/[H7786]', 'lemma', 'heb', 'שׂוֹרָה', '["sôwrâh"]', '["a row"]', '["n-f"]', 'properly, a ring, i.e. (by analogy) a row (adverbially) principal.', 'from 7786 in the primitive sense of 5493;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5567}/[H5567]', 'lemma', 'heb', 'סָמַן', '["çâman"]', '["an appointed [place]"]', '["v"]', 'to designate appointed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3698}/[H3697]', 'inflected', 'heb', 'כֻּסֶּמֶת', '["kuççemeth"]', '["and/ spelt","and/ spelt<s>"]', '["n-f"]', 'spelt (from its bristliness as if just shorn) fitches, rie.', 'from 3697;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1367}/H9023/[H1366]', 'inflected', 'heb', 'גְּבוּלָה', '["gᵉbûwlâh"]', '["territory/ its"]', '["n-f"]', 'a boundary, region border, bound, coast, landmark. place.', 'or גְּבֻלָה; (shortened) feminine of 1366;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3256}/H9033/[H3256]', 'inflected', 'heb', 'יָסַר', '["yâçar"]', '["and/ he instructs/ him"]', '["v"]', 'to chastise, literally (with blows) or figuratively (with words); hence, to instruct bind, chasten, chastise, correct, instruct, punish, reform, reprove, sore, teach.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2742A}/[H2782]', 'inflected', 'heb', 'חֲרוּץ', '["chărûwts"]', '["with <the>/ threshing sledge","with/ [the] threshing sledges of"]', '["a"]', 'properly, incised or (active) incisive; hence (as noun masculine or feminine) a trench (as dug), gold (as mined), a threshing-sledge (having sharp teeth); (figuratively) determination; also eager decision, diligent, (fine) gold, pointed things, sharp, threshing instrument, wall.', 'or חָרֻץ; passive participle of 2782;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0212>', 'inflected', 'heb', 'ואופן', '["ve./''o.Fan"]', '["and/ a wheel","and/ a wheel of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3646>', 'opaque', 'heb', 'כַּמֹּן', '["kammôn"]', '["cumin"]', '["n-m"]', '''cummin'' (from its use as a condiment) cummin.', 'from an unused root meaning to store up or preserve;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4294J}/[H5186]', 'inflected', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["with <the>/ staff"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1758}/H9033/[H1758]', 'inflected', 'heb', 'דּוּשׁ', '["dûwsh"]', '["anyone threshes/ it"]', '["v"]', 'to trample or thresh break, tear, thresh, tread out (down), at grass (Jeremiah 50:11, by mistake for 1877).', 'or דּוֹשׁ; or דִּישׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1536}/[H1534]', 'lemma', 'heb', 'גִּלְגָּל', '["gilgâl"]', '["[the] wheel of"]', '["n-m"]', 'wheel.', 'a variation of 1534');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5699}/H9023/[H5696]', 'inflected', 'heb', 'עֲגָלָה', '["ʻăgâlâh"]', '["cart/ his"]', '["n-f"]', 'something revolving, i.e. a wheeled vehicle cart, chariot, wagon', 'from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6571A}/H9023/[H6567]', 'inflected', 'heb', 'פָּרָשׁ', '["pârâsh"]', '["and/ horses/ his"]', '["n-m"]', 'a steed (as stretched out to a vehicle, not single nor for mounting ); also (by implication) a driver (in a chariot), i.e. (collectively) cavalry horseman.', 'from 6567; (compare 5483)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1854}/H9033/[H1915]', 'inflected', 'heb', 'דָּקַק', '["dâqaq"]', '["he crushes/ it"]', '["v"]', 'to crush (or intransitively) crumble beat in pieces (small), bruise, make dust, (into) × powder, (be, very) small, stamp (small).', 'a primitive root (compare 1915);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8454>\', 'opaque', 'heb', 'תּוּשִׁיָּה', '["tûwshîyâh"]', '["sound wisdom"]', '["n-f"]', 'support or (by implication) ability, i.e. (direct) help, (in purpose) an undertaking, (intellectual) understanding enterprise, that which (thing as it) is, substance, (sound) wisdom, working.', 'or תֻּשִׁיָּה; from an unused root probably meaning to substantiate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0740H}/[H739]', 'lemma', 'heb', 'אֲרִיאֵל', '["ʼĂrîyʼêl"]', '["Ariel"]', '["n-pr"]', 'Ariel, a symbolical name for Jerusalem, also the name of an Israelite Ariel.', 'the same as 739;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6693}/[H6693]', 'inflected', 'heb', 'צוּק', '["tsûwq"]', '["and/ I will bring distress"]', '["v"]', 'to compress, i.e. (figuratively) oppress, distress constrain, distress, lie sore, (op-) press(-or), straiten.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0740H}/[H739]', 'inflected', 'heb', 'אֲרִיאֵל', '["ʼĂrîyʼêl"]', '["to/ Ariel"]', '["n-pr"]', 'Ariel, a symbolical name for Jerusalem, also the name of an Israelite Ariel.', 'the same as 739;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8386}/[H578]', 'lemma', 'heb', 'תַּאֲנִיָּה', '["taʼănîyâh"]', '["mourning"]', '["n-f"]', 'lamentation heaviness, mourning.', 'from 578;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0592}/[H578]', 'inflected', 'heb', 'אֲנִיָּה', '["ʼănîyâh"]', '["and/ lamentation"]', '["n-f"]', 'groaning lamentation, sorrow.', 'from 578;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0740H}/[H739]', 'inflected', 'heb', 'אֲרִיאֵל', '["ʼĂrîyʼêl"]', '["like/ Ariel"]', '["n-pr"]', 'Ariel, a symbolical name for Jerusalem, also the name of an Israelite Ariel.', 'the same as 739;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1754A}/[H1752]', 'inflected', 'heb', 'דּוּר', '["dûwr"]', '["like <the>/ circle"]', '["n-m"]', 'a circle, ball or pile ball, turn, round about.', 'from 1752;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4674}/[H5324]', 'lemma', 'heb', 'מֻצָּב', '["mutstsâb"]', '["siege-works"]', '["n-m"]', 'a station, i.e. military post mount.', 'from 5324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0565A}/H9022/[H561]', 'inflected', 'heb', 'אִמְרָה', '["ʼimrâh"]', '["utterance/ your"]', '["n-f"]', 'commandment, speech, word.', 'or אֶמְרָה; feminine of 561, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6850}/[H6850]', 'lemma', 'heb', 'צָפַף', '["tsâphaph"]', '["I chirp","it will whisper"]', '["v"]', 'to coo or chirp (as a bird) chatter, peep, whisper.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2114A}/H9022/[H2114]', 'inflected', 'heb', 'זוּר', '["zûwr"]', '["strangers/ your"]', '["v"]', 'to turn aside (especially for lodging); hence to be a foreigner, strange, profane; specifically (active participle) to commit adultery (come from) another (man, place), fanner, go away, (e-) strange(-r, thing, woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H6621>', 'inflected', 'heb', 'לפתע', '["le./Fe.ta''"]', '["to/ suddenness"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7482}/[H7481]', 'inflected', 'heb', 'רַעַם', '["raʻam"]', '["with/ thunder"]', '["n-m"]', 'a peal of thunder thunder.', 'from 7481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7494}/[H7493]', 'inflected', 'heb', 'רַעַשׁ', '["raʻash"]', '["and/ with/ earthquake"]', '["n-m"]', 'vibration, bounding, uproar commotion, confused noise, earthquake, fierceness, quaking, rattling, rushing, shaking.', 'from 7493;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5591B}/[H5590]', 'inflected', 'heb', 'סַעַר', '["çaʻar"]', '["and/ a tempest"]', '["n-m"]', 'a hurricane storm(-y), tempest, whirlwind.', 'or (feminine) סְעָרָה; from 5590;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6633}/H9034/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["[those who] wage war against/ it"]', '["v"]', 'to mass (an army or servants) assemble, fight, perform, muster, wait upon, war.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4685D}/H9024/[H6679]', 'inflected', 'heb', 'מָצוֹד', '["mâtsôwd"]', '["and/ stronghold/ its"]', '["n-m"]', 'a net (for capturing animals or fishes); a fastness or (beseiging) tower bulwark, hold, munition, net, snare.', 'or (feminine) מְצוֹדָה; or מצֹדָה; from 6679; also (by interchange for 4679)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6693}/[H6693]', 'inflected', 'heb', 'צוּק', '["tsûwq"]', '["and/ those/ [who] bring distress"]', '["v"]', 'to compress, i.e. (figuratively) oppress, distress constrain, distress, lie sore, (op-) press(-or), straiten.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7457}/[H7456]', 'inflected', 'heb', 'רָעֵב', '["râʻêb"]', '["the/ hungry [person]"]', '["a"]', 'hungry (more or less intensely) hunger bitten, hungry.', 'from 7456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8173A}/[H8173]', 'inflected', 'heb', 'שָׁעַע', '["shâʻaʻ"]', '["and/ be blind"]', '["v"]', '(in a good acceptation) to look upon (with complacency), i.e. fondle, please or amuse (self); (in a bad one) to look about (in dismay), i.e. stare cry (out) (by confusion with 7768), dandle, delight (self), play, shut.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6105B}/[H6106]', 'inflected', 'heb', 'עָצַם', '["ʻâtsam"]', '["and/ he has shut"]', '["v"]', 'to bind fast, i.e. close (the eyes); intransitively, to be (causatively, make) powerful or numerous; to crunch the bones break the bones, close, be great, be increased, be (wax) mighty(-ier), be more, shut, be(-come, make) strong(-er).', 'a primitive root; also denominatively (from 6106)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5612I}/[H9]', 'lemma', 'heb', 'סֵפֶר', '["çêpher"]', '["writing"]', '["n-m"]', 'properly, writing (the art or a document); by implication, a book bill, book, evidence, × learn(-ed) (-ing), letter, register, scroll.', 'or (feminine) סִפְרָה; (Psalm 56:8 (9)), from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5612I}\/[H9]', 'inflected', 'heb', 'סֵפֶר', '["çêpher"]', '["writing"]', '["n-m"]', 'properly, writing (the art or a document); by implication, a book bill, book, evidence, × learn(-ed) (-ing), letter, register, scroll.', 'or (feminine) סִפְרָה; (Psalm 56:8 (9)), from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8193G}/H9023/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["and/ with/ lips/ its"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3374}/H9028/[H3373]', 'inflected', 'heb', 'יִרְאָה', '["yirʼâh"]', '["fear/ their"]', '["n-f"]', 'fear (also used as infinitive); morally, reverence × dreadful, × exceedingly, fear(-fulness).', 'feminine of 3373;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6382}/[H6381]', 'inflected', 'heb', 'פֶּלֶא', '["peleʼ"]', '["and/ a wonder"]', '["n-m"]', 'a miracle marvellous thing, wonder(-ful, -fully).', 'from 6381;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6009}/[H6009]', 'inflected', 'heb', 'עָמַק', '["ʻâmaq"]', '["those/ [who] make deep"]', '["v"]', 'to be (causatively, make) deep (literally or figuratively) (be, have, make, seek) deep(-ly), depth, be profound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2017}/H9026/[H2015]', 'inflected', 'heb', 'הֹפֶךְ', '["hôphek"]', '["perversity/ your"]', '["n-m"]', 'an upset, i.e. (abstract) perversity turning of things upside down.', 'from 2015;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6213H}/H9033/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["to/ [the] [one who] made/ it"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3336}/[H3335]', 'inflected', 'heb', 'יֵצֶר', '["yêtser"]', '["and/ a pot"]', '["n-m"]', 'a form; figuratively, conception (i.e. purpose) frame, thing framed, imagination, mind, work.', 'from 3335;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3335G}/H9033/[H3334]', 'inflected', 'heb', 'יָצַר', '["yâtsar"]', '["to/ [the one who] forms/ it","to/ potter/ its"]', '["v"]', 'to mould into a form; especially as a potter; figuratively, to determine (i.e. form a resolution) × earthen, fashion, form, frame, make(-r), potter, purpose.', 'probably identical with 3334 (through the squeezing into shape); (compare 3331);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3759}/[H3754]', 'inflected', 'heb', 'כַּרְמֶל', '["karmel"]', '["<into> <the>/ orchard","into <the>/ orchard"]', '["n-m"]', 'a planted field (garden, orchard, vineyard or park); by implication, garden produce full (green) ears (of corn), fruitful field (place), plentiful (field).', 'from 3754;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3759}/[H3754]', 'inflected', 'heb', 'כַּרְמֶל', '["karmel"]', '["and/ the/ orchard"]', '["n-m"]', 'a planted field (garden, orchard, vineyard or park); by implication, garden produce full (green) ears (of corn), fruitful field (place), plentiful (field).', 'from 3754;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3293A>', 'inflected', 'heb', 'ליער', '["la/i.Ya.''ar","le./Ya.''ar"]', '["into/ a thicket","to <the>/ forest","to/ [the] forest of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2795}/[H2790]', 'inflected', 'heb', 'חֵרֵשׁ', '["chêrêsh"]', '["O/ deaf [people]","the/ deaf [people]"]', '["a"]', 'deaf (whether literally or spiritual) deaf.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0652}/[H651]', 'inflected', 'heb', 'אֹפֶל', '["ʼôphel"]', '["and/ from/ gloom"]', '["n-m"]', 'dusk darkness, obscurity, privily.', 'from the same as 651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H2822}/[H2821]', 'inflected', 'heb', 'חֹשֶׁךְ', '["chôshek"]', '["and/ from/ darkness"]', '["n-m"]', 'the dark; hence (literally) darkness; figuratively, misery, destruction, death, ignorance, sorrow, wickedness dark(-ness), night, obscurity.', 'from 2821;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6918G}/[H6942]', 'inflected', 'heb', 'קָדוֹשׁ', '["qâdôwsh"]', '["in/ [the] holy [one] of"]', '["a"]', 'sacred (ceremonially or morally); (as noun) God (by eminence), an angel, a saint, a sanctuary holy (One), saint.', 'or קָדֹשׁ; from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6983}/H9013/[H3369]', 'inflected', 'heb', 'קוֹשׁ', '["qôwsh"]', '["they lay a trap/ !"]', '["v"]', 'to set a trap lay a snare.', 'a primitive root; to bend; used only as denominative for 3369,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6662}\/[H6663]', 'inflected', 'heb', 'צַדִּיק', '["tsaddîyq"]', '["[the] righteous [person]","righteous [people]"]', '["a"]', 'just just, lawful, righteous (man).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2357}/[H2357]', 'lemma', 'heb', 'חָוַר', '["châvar"]', '["they will grow pale"]', '["v"]', 'to blanch (as with shame) wax pale.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5258A}/[H5258]', 'inflected', 'heb', 'נָסַךְ', '["nâçak"]', '["and/ by/ pouring out","and/ to/ pour out"]', '["v"]', 'to pour out, especially a libation, or to cast (metal); by analogy, to anoint a king cover, melt, offer, (cause to) pour (out), set (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6310I}/H9020/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["and/ mouth/ my"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5756}/[H5756]', 'inflected', 'heb', 'עוּז', '["ʻûwz"]', '["to/ take refuge"]', '["v"]', 'to be strong; causatively, to strengthen, i.e. (figuratively) to save (by flight) gather (self, self to flee), retire.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4581}/[H5810]', 'inflected', 'heb', 'מָעוֹז', '["mâʻôwz"]', '["in/ [the] refuge of","in/ [the] stronghold of"]', '["n-m"]', 'a fortified place; figuratively, a defence force, fort(-ress), rock, strength(-en), (× most) strong (hold).', '(also מָעוּז ); or מָעֹז (also מָעֻז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2620}/[H982]', 'inflected', 'heb', 'חָסָה', '["châçâh"]', '["and/ to/ seek refuge"]', '["v"]', 'to flee for protection; figuratively, to confide in have hope, make refuge, (put) trust.', 'a primitive root; (compare 982)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1322}/[H954]', 'inflected', 'heb', 'בֹּשֶׁת', '["bôsheth"]', '["<into>/ shame","for/ shame","to <the>/ shame","to the/ shameful thing"]', '["n-f"]', 'shame (the feeling and the condition, as well as its cause); by implication (specifically) an idol ashamed, confusion, greatly, (put to) shame(-ful thing).', 'from 954;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2622}/[H2620]', 'inflected', 'heb', 'חָסוּת', '["châçûwth"]', '["and/ the/ refuge"]', '["n-f"]', 'confidence trust.', 'from 2620;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6814}/[H6814]', 'inflected', 'heb', 'צֹעַן', '["Tsôʻan"]', '["in/ Zoan"]', '["n-pr-loc"]', 'Tsoän, a place in Egypt Zoan.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4397G>/H9023', 'inflected', 'heb', 'ומלאכיו', '["u./mal.''a.Kha/v"]', '["and/ messengers/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2609}/[H2609]', 'lemma', 'heb', 'חָנֵס', '["Chânêç"]', '["Hanes"]', '["n-pr-loc"]', 'Chanes, a place in Egypt Hanes.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5828}/[H5826]', 'inflected', 'heb', 'עֵזֶר', '["ʻêzer"]', '["for/ help"]', '["n-m"]', 'aid help.', 'from 5826;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3276}/[H3276]', 'inflected', 'heb', 'יָעַל', '["yâʻal"]', '["to/ confer profit","to/ profit"]', '["v"]', 'properly, to ascend; figuratively, to be valuable (objectively; useful, subjectively; benefited) × at all, set forward, can do good, (be, have) profit, (able).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2781}\/[H2778]', 'inflected', 'heb', 'חֶרְפָּה', '["cherpâh"]', '["for/ reproach"]', '["n-f"]', 'contumely, disgrace, the pudenda rebuke, reproach(-fully), shame.', 'from 2778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3918}/[H3888]', 'inflected', 'heb', 'לַיִשׁ', '["layish"]', '["and/ lion"]', '["n-m"]', 'a lion (from his destructive blows) (old) lion.', 'from 3888 in the sense of crushing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8314A}/[H8313]', 'inflected', 'heb', 'שָׂרָף', '["sârâph"]', '["and/ serpent"]', '["n-m"]', 'burning, i.e. (figuratively) poisonous (serpent); specifically, a saraph or symbolical creature (from their copper color) fiery (serpent), seraph.', 'from 8313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1707}/[H1706]', 'lemma', 'heb', 'דַּבֶּשֶׁת', '["dabbesheth"]', '["[the] hump of"]', '["n-f"]', 'a sticky mass, i.e. the hump of a camel hunch (of a camel).', 'intensive from the same as 1706;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0214}/H9028/[H686]', 'inflected', 'heb', 'אוֹצָר', '["ʼôwtsâr"]', '["treasures/ their"]', '["n-m"]', 'a depository armory, cellar, garner, store(-house), treasure(-house) (-y).', 'from 686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7385}/[H7324]', 'inflected', 'heb', 'רִיק', '["rîyq"]', '["and/ vanity"]', '["n-m"]', 'emptiness; figuratively, a worthless thing; adverbially, in vain empty, to no purpose, (in) vain (thing), vanity.', 'from 7324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3789}/H9034/[H3789]', 'inflected', 'heb', 'כָּתַב', '["kâthab"]', '["I will write/ it","write/ it"]', '["v"]', 'to grave, by implication, to write (describe, inscribe, prescribe, subscribe) describe, record, prescribe, subscribe, write(-ing, -ten).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2710}/H9034/[H2710]', 'inflected', 'heb', 'חָקַק', '["châqaq"]', '["inscribe/ it"]', '["v"]', 'properly, to hack, i.e. engrave (Judges 5:14, to be a scribe simply); by implication, to enact (laws being cut in stone or metal tablets in primitive times) or (gen.) prescribe appoint, decree, governor, grave, lawgiver, note, pourtray, print, set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3586}/[H3584]', 'lemma', 'heb', 'כֶּחָשׁ', '["kechâsh"]', '["lying"]', '["a"]', 'faithless lying.', 'from 3584;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7203A}/[H7200]', 'inflected', 'heb', 'רֹאֶה', '["rôʼeh"]', '["to the/ seers"]', '["n-m"]', 'a seer (as often rendered); but also (abstractly) a vision vision.', 'active participle of 7200;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2374}/[H2372]', 'inflected', 'heb', 'חֹזֶה', '["chôzeh"]', '["and/ to the/ seers"]', '["n-m"]', 'a beholder in vision; also a compact (as looked upon with approval) agreement, prophet, see that, seer, (star-) gazer.', 'active participle of 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4123}/[H2048]', 'lemma', 'heb', 'מַהֲתַלָּה', '["mahăthallâh"]', '["deception<s>"]', '["n-f"]', 'a delusion deceit.', 'from 2048;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3988A}/H9046/[H3988]', 'inflected', 'heb', 'מָאַס', '["mâʼaç"]', '["have rejected/ you"]', '["v"]', 'to spurn; also (intransitively) to disappear abhor, cast away (off), contemn, despise, disdain, (become) loathe(some), melt away, refuse, reject, reprobate, × utterly, vile person.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7665}/H9034/[H7665]', 'inflected', 'heb', 'שָׁבַר', '["shâbar"]', '["and/ someone will break/ it"]', '["v"]', 'to burst (literally or figuratively) break (down, off, in pieces, up), broken (-hearted), bring to the birth, crush, destroy, hurt, quench, × quite, tear, view (by mistake for 7663).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7667}/[H7665]', 'inflected', 'heb', 'שֶׁבֶר', '["sheber"]', '["like/ [the] breaking of"]', '["n-m"]', 'a fracture, figuratively, ruin; specifically, a solution (of a dream) affliction, breach, breaking, broken(-footed, -handed), bruise, crashing, destruction, hurt, interpretation, vexation.', 'or שֵׁבֶר; from 7665;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4386}/H9023/[H3807]', 'inflected', 'heb', 'מְכִתָּה', '["mᵉkittâh"]', '["among/ fragment[s]/ its"]', '["n-m"]', 'a fracture bursting.', 'from 3807;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2846}/[H2846]', 'inflected', 'heb', 'חָתָה', '["châthâh"]', '["to/ snatch up"]', '["v"]', 'to lay hold of; especially to pick up fire heap, take (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3344}/[H3344]', 'inflected', 'heb', 'יָקַד', '["yâqad"]', '["from/ a fireplace"]', '["v"]', 'to burn (be) burn(-ing), × from the hearth, kindle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2834}/[H2834]', 'inflected', 'heb', 'חָשַׂף', '["châsaph"]', '["and/ to/ scoop"]', '["v"]', 'to strip off, i.e. generally to make naked (for exertion or in disgrace), to drain away or bail up (a liquid) make bare, clean, discover, draw out, take, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H1360>\', 'inflected', 'heb', 'מגבא פ', '["mi./Ge.ve''"]', '["from/ a cistern"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7729}/[H7725]', 'inflected', 'heb', 'שׁוּבָה', '["shûwbâh"]', '["in/ returning"]', '["n-f"]', 'a return returning.', 'from 7725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0985}/[H984]', 'inflected', 'heb', 'בִּטְחָה', '["biṭchâh"]', '["and/ in/ trusting"]', '["n-f"]', 'trust confidence.', 'feminine of 984;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1369}/H9026/[H1368]', 'inflected', 'heb', 'גְּבוּרָה', '["gᵉbûwrâh"]', '["strength/ your"]', '["n-f"]', 'force (literally or figuratively); by implication, valor, victory force, mastery, might, mighty (act, power), power, strength.', 'feminine passive participle from the same as 1368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7291}/H9036/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["[those who] pursue/ you"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8650}/[H766]', 'inflected', 'heb', 'תֹּרֶן', '["tôren"]', '["like <the>/ flagstaff"]', '["n-m"]', 'a pole (as a mast or flagstaff) beacon, mast.', 'probably for 766;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H5251H}/[H5264]', 'inflected', 'heb', 'נֵס', '["nêç"]', '["and/ like <the>/ standard"]', '["n-m"]', 'a flag; also a sail; by implication, a flagstaff; generally a signal; figuratively, a token banner, pole, sail, (en-) sign, standard.', 'from 5264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2603A}/H9036/[H2583]', 'inflected', 'heb', 'חָנַן', '["chânan"]', '["to/ show favor to/ you"]', '["v"]', 'properly, to bend or stoop in kindness to an inferior; to favor, bestow; causatively to implore (i.e. move to favor by petition) beseech, × fair, (be, find, shew) favour(-able), be (deal, give, grant (gracious(-ly), intreat, (be) merciful, have (shew) mercy (on, upon), have pity upon, pray, make supplication, × very.', 'a primitive root (compare 2583);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7355}/H9036/[H7355]', 'inflected', 'heb', 'רָחַם', '["râcham"]', '["to/ have compassion on/ you"]', '["v"]', 'to fondle; by implication, to love, especially to compassionate have compassion (on, upon), love, (find, have, obtain, shew) mercy(-iful, on, upon), (have) pity, Ruhamah, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2199}/H9041/[H2199]', 'inflected', 'heb', 'זָעַק', '["zâʻaq"]', '["crying out/ you"]', '["v"]', 'to shriek (from anguish or danger); by analogy, (as a herald) to announce or convene publicly assemble, call (together), (make a) cry (out), come with such a company, gather (together), cause to be proclaimed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3670}/[H3670]', 'lemma', 'heb', 'כָּנַף', '["kânaph"]', '["he will hide himself"]', '["v"]', 'properly, to project laterally, i.e. probably (reflexive) to withdraw be removed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4175}/H9021/[H3384]', 'inflected', 'heb', 'מוֹרֶה', '["môwreh"]', '["teachers/ your"]', '["n-m"]', 'an archer; also teacher or teaching; also the early rain (early) rain.', 'from 3384; (see 3138)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0310A}/H9031/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["from/ behind/ you"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0541}/[H3225]', 'lemma', 'heb', 'אָמַן', '["ʼâman"]', '["you will go to [the] right"]', '["v"]', 'to take the right hand road turn to the right. See 539.', 'denominative from 3225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8041}/[H8040]', 'lemma', 'heb', 'שָׂמַאל', '["sâmaʼl"]', '["go to [the] left","you will go to [the] left"]', '["v"]', 'to use the left hand or pass in that direction (go, turn) (on the, to the) left.', 'a primitive root (denominative from 8040);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0642}/[H646]', 'lemma', 'heb', 'אֵפֻדָּה', '["ʼêphuddâh"]', '["[the] sheathing of"]', '["n-f"]', 'a girding on (of the ephod); hence, generally, a plating (of metal) ephod, ornament.', 'feminine of 646;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2091>/H9021', 'opaque', 'heb', 'זָהָב', '["zâhâb"]', '["gold/ your"]', '["n-m"]', 'gold, figuratively, something gold-colored (i.e. yellow), as oil, a clear sky gold(-en), fair weather.', 'from an unused root meaning to shimmer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2219}/H9038/[H2114]', 'inflected', 'heb', 'זָרָה', '["zârâh"]', '["you will throw away/ them","you will winnow/ them"]', '["v"]', 'to toss about; by implication, to diffuse, winnow cast away, compass, disperse, fan, scatter (away), spread, strew, winnow.', 'a primitive root (compare 2114);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6627}/[H3318]', 'lemma', 'heb', 'צָאָה', '["tsâʼâh"]', '["[the] excrement of","filth"]', '["n-f"]', 'issue, i.e. (human) excrement that (which) cometh from (out).', 'from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8082}/[H8080]', 'inflected', 'heb', 'שָׁמֵן', '["shâmên"]', '["and/ fat"]', '["a"]', 'greasy, i.e. gross; figuratively, rich fat, lusty, plenteous.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0504}/[H502]', 'inflected', 'heb', 'אֶלֶף', '["ʼeleph"]', '["and/ the/ cattle<s>"]', '["n-m"]', 'a family; also (from the sense of yoking or taming) an ox or cow family, kine, oxen.', 'from 502;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5895}/[H5782]', 'inflected', 'heb', 'עַיִר', '["ʻayir"]', '["and/ the/ donkeys"]', '["n-m"]', 'properly, a young ass (as just broken to a load); hence an ass-colt (ass) colt, foal, young ass.', 'from 5782 in the sense of raising (i.e. bearing a burden);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1098}/[H1101]', 'lemma', 'heb', 'בְּלִיל', '["bᵉlîyl"]', '["fodder"]', '["n-m"]', 'mixed, i.e. (specifically) feed (for cattle) corn, fodder, provender.', 'from 1101;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2548}/[H2556]', 'lemma', 'heb', 'חָמִיץ', '["châmîyts"]', '["salted"]', '["a"]', 'seasoned, i.e. salt provender clean.', 'from 2556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7371}/[H7306]', 'inflected', 'heb', 'רַחַת', '["rachath"]', '["with the/ shovel"]', '["n-f"]', 'a winnowing-fork (as blowing the chaff away) shovel.', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4214}/[H2219]', 'inflected', 'heb', 'מִזְרֶה', '["mizreh"]', '["and/ with the/ pitchfork"]', '["n-m"]', 'a winnowing shovel (as scattering the chaff) fan.', 'from 2219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2988}/[H2986]', 'lemma', 'heb', 'יָבָל', '["yâbâl"]', '["watercourses of"]', '["n-m"]', 'a stream (water-) course, stream.', 'from 2986;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2027}/[H2026]', 'lemma', 'heb', 'הֶרֶג', '["hereg"]', '["a slaughter","slaughter"]', '["n-m"]', 'slaughter be slain, slaughter.', 'from 2026;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4273}/[H4272]', 'inflected', 'heb', 'מַחַץ', '["machats"]', '["and/ [the] wound of"]', '["n-m"]', 'a contusion stroke.', 'from 4272;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4347}/H9023/[H5221]', 'inflected', 'heb', 'מַכָּה', '["makkâh"]', '["blow/ his"]', '["n-f"]', 'a blow (in 2 Chronicles 2:10, of the flail); by implication, a wound; figuratively, carnage, also pestilence beaten, blow, plague, slaughter, smote, × sore, stripe, stroke, wound(-ed).', 'or (masculine) מַכֶּה; (plural only) from 5221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3514}/[H3513]', 'inflected', 'heb', 'כֹּבֶד', '["kôbed"]', '["and/ [is] heaviness of"]', '["n-m"]', 'weight, multitude, vehemence grievousness, heavy, great number.', 'from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4858}/[H5375]', 'lemma', 'heb', 'מַשָּׂאָה', '["massâʼâh"]', '["lifting up"]', '["n-f"]', 'a conflagration (from the rising of smoke) burden.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7307H}/H9023/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["and/ breath/ his"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5158A}/[H5157]', 'inflected', 'heb', 'נַחַל', '["nachal"]', '["[is] like/ a torrent","like <the>/ river","like/ a torrent of","like/ a wadi"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5299A}/[H5130]', 'inflected', 'heb', 'נָפָה', '["nâphâh"]', '["in/ a sieve of"]', '["n-f"]', 'a sieve border, coast, region, sieve.', 'from 5130 in the sense of lifting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1980G}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["like <the>/ [one who] walks"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5183B}/[H5182]', 'inflected', 'heb', 'נַחַת', '["Nachath"]', '["and/ [the] lowering of"]', '["n"]', 'a descent, i.e. imposition, unfavorable (punishment) or favorable (food); restfulness lighting down, quiet(-ness), to rest, be set on.', 'from 5182; also (intransitively; perhaps from 5117)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5311}/[H5310]', 'lemma', 'heb', 'נֶפֶץ', '["nephets"]', '["a driving storm"]', '["n-m"]', 'a storm (as dispersing) scattering.', 'from 5310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2230}/[H2229]', 'inflected', 'heb', 'זֶרֶם', '["zerem"]', '["and/ a rainstorm"]', '["n-m"]', 'a gush of water flood, overflowing, shower, storm, tempest.', 'from 2229;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4145}/[H4143]', 'lemma', 'heb', 'מוּסָדָה', '["mûwçâdâh"]', '["[the] foundations of","appointment"]', '["n-f"]', 'a foundation; figuratively, an appointment foundation, grounded. Compare 4328.', 'feminine of 4143;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8613}/[H8612]', 'lemma', 'heb', 'תׇּפְתֶּה', '["Tophteh"]', '["a place of burning"]', '["n-pr-loc"]', 'Tophteh, a place of cremation Tophet.', 'probably a form of 8612;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4071}/H9024/[H1752]', 'inflected', 'heb', 'מְדוּרָה', '["mᵉdûwrâh"]', '["wood pile/ its"]', '["n-f"]', 'a pile of fuel pile (for fire).', 'or מְדֻרָה; from 1752 in the sense of accumulation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5483M>/H9028', 'inflected', 'heb', 'וסוסיהם', '["ve./su.sei./Hem"]', '["and/ horses/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3615H}/H9013\/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["they will come to an end/ !"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3715A}/[H3722]', 'inflected', 'heb', 'כְּפִיר', '["kᵉphîyr"]', '["and/ the/ young lion"]', '["n-m"]', 'a village (as covered in by walls); also a young lion (perhaps as covered with a mane) (young) lion, village. Compare 3723.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2964}/H9023/[H2963]', 'inflected', 'heb', 'טֶרֶף', '["ṭereph"]', '["prey/ its"]', '["n-m"]', 'something torn, i.e. a fragment, e.g. a fresh leaf, prey, food leaf, meat, prey, spoil.', 'from 2963;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H6963A>/H9028', 'inflected', 'heb', 'מקולם', '["mi./ko.La/m"]', '["from/ voice/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1995A}/H9028/[H1993]', 'inflected', 'heb', 'הָמוֹן', '["hâmôwn"]', '["and/ from/ tumult/ their"]', '["n-m"]', 'a noise, tumult, crowd; also disquietude, wealth abundance, company, many, multitude, multiply, noise, riches, rumbling, sounding, store, tumult.', 'or הָמֹן; (Ezekiel 5:7), from 1993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1389I}/H9024/[H1387]', 'inflected', 'heb', 'גִּבְעָה', '["gibʻâh"]', '["hill/ its"]', '["n-f"]', 'a hillock hill, little hill.', 'feminine from the same as 1387;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1598}/[H1598]', 'lemma', 'heb', 'גָּנַן', '["gânan"]', '["he will defend","he will defend [it]"]', '["v"]', 'to hedge about, i.e. (generally) protect defend.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3988A}/H9013/[H3988]', 'inflected', 'heb', 'מָאַס', '["mâʼaç"]', '["they will reject/ !"]', '["v"]', 'to spurn; also (intransitively) to disappear abhor, cast away (off), contemn, despise, disdain, (become) loathe(some), melt away, refuse, reject, reprobate, × utterly, vile person.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0457}/[H408]', 'inflected', 'heb', 'אֱלִיל', '["ʼĕlîyl"]', '["and/ [the] idols of","and/ an idol"]', '["a-m"]', 'good for nothing, by analogy vain or vanity; specifically an idol idol, no value, thing of nought.', 'apparently from 408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0970}/H9023/[H977]', 'inflected', 'heb', 'בָּחוּר', '["bâchûwr"]', '["and/ young men/ its"]', '["n-m"]', 'properly, selected, i.e. a youth (often collective) (choice) young (man), chosen, × hole.', 'or בָּחֻר; participle passive of 977;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5553H>/H9023', 'inflected', 'heb', 'וסלעו', '["ve./sal.''/O"]', '["and/ rock/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4032}/[H1481]', 'inflected', 'heb', 'מָגוֹר', '["mâgôwr"]', '["from/ terror"]', '["n-m"]', 'a fright (objective or subjective) fear, terror. Compare 4036.', 'or (Lamentations 2:22) מָגוּר; from 1481 in the sense of fearing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5251H}/[H5264]', 'inflected', 'heb', 'נֵס', '["nêç"]', '["from/ a standard"]', '["n-m"]', 'a flag; also a sail; by implication, a flagstaff; generally a signal; figuratively, a token banner, pole, sail, (en-) sign, standard.', 'from 5264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0217A}/[H215]', 'lemma', 'heb', 'אוּר', '["ʼûwr"]', '["a fire","fire"]', '["n-m"]', 'flame; hence (in the plural) the East (as being the region of light) fire, light. See also 224.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8574H}/[H5216]', 'inflected', 'heb', 'תַּנּוּר', '["tannûwr"]', '["and/ an oven"]', '["n-m"]', 'a fire-pot furnace, oven.', 'from 5216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6664G}/[H6663]', 'inflected', 'heb', 'צֶדֶק', '["tsedeq"]', '["for/ righteousness"]', '["n-m"]', 'the right (natural, moral or legal); also (abstractly) equity or (figuratively) prosperity × even, (× that which is altogether) just(-ice), (un-)right(-eous) (cause, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4224A}/[H2244]', 'inflected', 'heb', 'מַחֲבֵא', '["machăbêʼ"]', '["like/ a hiding place of"]', '["n-m"]', 'a refuge hiding (lurking) place.', 'or מַחֲבֹא; from 2244;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2230}/[H2229]', 'lemma', 'heb', 'זֶרֶם', '["zerem"]', '["a downpour of","a rainstorm"]', '["n-m"]', 'a gush of water flood, overflowing, shower, storm, tempest.', 'from 2229;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6388}/[H6385]', 'inflected', 'heb', 'פֶּלֶג', '["peleg"]', '["like/ streams of"]', '["n-m"]', 'a rill (i.e. small channel of water, as in irrigation) river, stream.', 'from 6385;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1847}/[H3045]', 'inflected', 'heb', 'דַּעַת', '["daʻath"]', '["<to>/ knowledge"]', '["n"]', 'knowledge cunning, (ig-) norantly, know(-ledge), (un-) awares (wittingly).', 'from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5926>', 'opaque', 'heb', 'עִלֵּג', '["ʻillêg"]', '["stammerers"]', '["a"]', 'stuttering stammerer.', 'from an unused root meaning to stutter;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3596}/[H3557]', 'inflected', 'heb', 'כִּילַי', '["kîylay"]', '["and/ of/ a scoundrel"]', '["n-m"]', 'niggardly churl.', 'or כֵּלַי; from 3557 in the sense of withholding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2612}/[H2610]', 'lemma', 'heb', 'חֹנֶף', '["chôneph"]', '["godlessness"]', '["n-m"]', 'moral filth, i.e. wickedness hypocrisy.', 'from 2610;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1696G}/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["and/ by/ speaking"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7324}/[H7324]', 'inflected', 'heb', 'רוּק', '["rûwq"]', '["by/ keeping empty"]', '["v"]', 'to pour out (literally or figuratively), i.e. empty × arm, cast out, draw (out), (make) empty, pour forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4945B}/[H8248]', 'inflected', 'heb', 'מַשְׁקֶה', '["mashqeh"]', '["and/ drink"]', '["n-m"]', 'properly, causing to drink, i.e. a butler; by implication (intransitively), drink (itself); figuratively, a well-watered region butler(-ship), cupbearer, drink(-ing), fat pasture, watered.', 'from 8248;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3596}/[H3557]', 'inflected', 'heb', 'כִּילַי', '["kîylay"]', '["and/ a scoundrel"]', '["n-m"]', 'niggardly churl.', 'or כֵּלַי; from 3557 in the sense of withholding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1696G}/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["and/ when/ speaks"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965I}\/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["he stands","to stand"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0625}/[H622]', 'lemma', 'heb', 'אֹסֶף', '["ʼôçeph"]', '["<the> gathering of","[the] gathering"]', '["n-m"]', 'a collection (of fruits) gathering.', 'from 622;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6209}/[H6209]', 'inflected', 'heb', 'עָרַר', '["ʻârar"]', '["and/ strip yourself"]', '["v"]', 'to bare; figuratively, to demolish make bare, break, raise up (perhaps by clerical error for raze), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2504}/[H2502]', 'lemma', 'heb', 'חָלָץ', '["châlâts"]', '["loins"]', '["n-f"]', 'the loins (as the seat of vigor) loins, reins.', 'from 2502 (in the sense of strength); only in the dual;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6076A}/[H6075]', 'lemma', 'heb', 'עֹפֶל', '["ʻôphel"]', '["O hill of","[the] hill"]', '["n-m"]', 'a tumor; also a mound, i.e. fortress emerod, fort, strong hold, tower.', 'from 6075;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0975}/[H974]', 'inflected', 'heb', 'בַּחַן', '["bachan"]', '["and/ [the] watchtower"]', '["n-m"]', 'a watch-tower tower.', 'from 974 (in the sense of keeping a look-out);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3759}/[H3754]', 'inflected', 'heb', 'כַּרְמֶל', '["karmel"]', '["in the/ orchard"]', '["n-m"]', 'a planted field (garden, orchard, vineyard or park); by implication, garden produce full (green) ears (of corn), fruitful field (place), plentiful (field).', 'from 3754;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6666}/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["<the>/ righteousness"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5656I}/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["and/ [the] labor of"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0983}/[H982]', 'inflected', 'heb', 'בֶּטַח', '["beṭach"]', '["and/ security"]', '["n-m"]', 'properly, a place of refuge; abstract, safety, both the fact (security) and the feeling (trust); often (adverb with or without preposition) safely assurance, boldly, (without) care(-less), confidence, hope, safe(-ly, -ty), secure, surely.', 'from 982;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4496H}/[H4495]', 'inflected', 'heb', 'מְנוּחָה', '["mᵉnûwchâh"]', '["and/ in/ resting places"]', '["n-f"]', 'repose or (adverbially) peacefully; figuratively, consolation (specifically, matrimony); hence (concretely) an abode comfortable, ease, quiet, rest(-ing place), still.', 'or מְנֻחָה; feminine of 4495;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1258}/[H1258]', 'inflected', 'heb', 'בָּרַד', '["bârad"]', '["and/ it will hail"]', '["v"]', 'to hail hail.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8218}/[H8216]', 'inflected', 'heb', 'שִׁפְלָה', '["shiphlâh"]', '["and/ with <the>/ lowness"]', '["n-f"]', 'depression low place.', 'feminine of 8216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0835}/H9036/[H833]', 'inflected', 'heb', 'אֶשֶׁר', '["ʼesher"]', '["how blessed [are]!/ you"]', '["n-m"]', 'happiness; only in masculine plural construction as interjection, how happy! blessed, happy.', 'from 833;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2543}\/[H2560]', 'inflected', 'heb', 'חֲמוֹר', '["chămôwr"]', '["and/ the/ donkey"]', '["n-m"]', 'a male ass (from its dun red) (he) ass.', 'or (shortened) חֲמֹר; from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8552}/H9041/[H8552]', 'inflected', 'heb', 'תָּמַם', '["tâmam"]', '["when/ finishing/ you"]', '["v"]', 'to complete, in a good or a bad sense, literal, or figurative, transitive or intransitive accomplish, cease, be clean (pass-) ed, consume, have done, (come to an, have an, make an) end, fail, come to the full, be all gone, × be all here, be (make) perfect, be spent, sum, be (shew self) upright, be wasted, whole.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5239}/H9041/[H5239]', 'inflected', 'heb', 'נָלָה', '["nâlâh"]', '["when/ completing/ you"]', '["v"]', 'to complete make an end.', 'apparently a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0898}/[H898]', 'inflected', 'heb', 'בָּגַד', '["bâgad"]', '["to/ deal treacherously"]', '["v"]', 'to cover (with a garment); figuratively, to act covertly; by implication, to pillage deal deceitfully (treacherously, unfaithfully), offend, transgress(-or), (depart), treacherous (dealer, -ly, man), unfaithful(-ly, man), × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H9031}\', 'inflected', 'heb', 'בך ס', '["Va/kh"]', '["with <the>/ you"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2220}/H9028/[H2232]', 'inflected', 'heb', 'זְרוֹעַ', '["zᵉrôwaʻ"]', '["arms/ their","strength/ their"]', '["n-f"]', 'the arm (as stretched out), or (of animals) the foreleg; figuratively, force arm, help, mighty, power, shoulder, strength.', 'or (shortened) זְרֹעַ; and (feminine) זְרוֹעָה; or זְרֹעָה; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7427}/H9021/[H7426]', 'inflected', 'heb', 'רֹמֵמֻת', '["rômêmuth"]', '["from/ arising/ your"]', '["n-f"]', 'exaltation lifting up of self.', 'from the active participle of 7426;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7998}/H9026/[H7997]', 'inflected', 'heb', 'שָׁלָל', '["shâlâl"]', '["plunder/ your"]', '["n-m"]', 'booty prey, spoil.', 'from 7997;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2625}/[H2628]', 'inflected', 'heb', 'חָסִיל', '["châçîyl"]', '["<the>/ locust[s]"]', '["n-m"]', 'the ravager, i.e. a locust caterpillar.', 'from 2628;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4944}/[H8264]', 'inflected', 'heb', 'מַשָּׁק', '["mashshâq"]', '["like/ [the] rushing of"]', '["n-m"]', 'a traversing, i.e. rapid motion running to and fro.', 'from 8264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1357}/[H1461]', 'lemma', 'heb', 'גֵּב', '["gêb"]', '["locusts"]', '["n-m"]', 'a locust (from its cutting) locust.', 'probably from 1461 (compare 1462);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0214}/H9023\/[H686]', 'inflected', 'heb', 'אוֹצָר', '["ʼôwtsâr"]', '["[will be] treasure/ his"]', '["n-m"]', 'a depository armory, cellar, garner, store(-house), treasure(-house) (-y).', 'from 686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0691}/H9028/[H739]', 'inflected', 'heb', 'אֶרְאֵל', '["ʼerʼêl"]', '["valiant one/ their"]', '["n-m"]', 'a hero (collectively) valiant one.', 'probably for 739;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6160G}/[H6150]', 'inflected', 'heb', 'עֲרָבָה', '["ʻărâbâh"]', '["like <the>/ desert plain","like the/ Arabah"]', '["n-f"]', 'a desert; especially (with the article prefix) the (generally) sterile valley of the Jordan and its continuation to the Red Sea Arabah, champaign, desert, evening, heaven, plain, wilderness. See also 1026.', 'from 6150 (in the sense of sterility);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3760G}/[H3759]', 'inflected', 'heb', 'כַּרְמֶל', '["Karmel"]', '["and/ Carmel"]', '["n-pr-loc"]', 'Karmel, the name of a hill and of a town in Palestine Carmel, fruitful (plentiful) field, (place).', 'the same as 3759;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2842}/[H7179]', 'lemma', 'heb', 'חָשַׁשׁ', '["châshash"]', '["dry grass"]', '["n-m"]', 'dry grass chaff.', 'by variation for 7179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7307H}/H9026/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["breath/ your"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0398}/H9036/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["[which] it will consume/ you"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4955}/[H8313]', 'lemma', 'heb', 'מִשְׂרָפָה', '["misrâphâh"]', '["burnings of"]', '["n-f"]', 'combustion, i.e. cremation (of a corpse), or calcination (of lime) burning.', 'from 8313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7875}/[H7874]', 'lemma', 'heb', 'שִׂיד', '["sîyd"]', '["lime"]', '["n-m"]', 'lime (as boiling when slacked) lime, plaister.', 'from 7874;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3341}\/[H3341]', 'inflected', 'heb', 'יָצַת', '["yâtsath"]', '["they will be kindled"]', '["v"]', 'to burn or set on fire; figuratively, to desolate burn (up), be desolate, set (on) fire (fire), kindle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1369}/H9020/[H1368]', 'inflected', 'heb', 'גְּבוּרָה', '["gᵉbûwrâh"]', '["might/ my","strength/ my"]', '["n-f"]', 'force (literally or figuratively); by implication, valor, victory force, mastery, might, mighty (act, power), power, strength.', 'feminine passive participle from the same as 1368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1215}/[H1214]', 'inflected', 'heb', 'בֶּצַע', '["betsaʻ"]', '["<in>/ unjust gain of"]', '["n-m"]', 'plunder; by extension, gain (usually unjust) covetousness, (dishonest) gain, lucre, profit.', 'from 1214;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8551}/[H8551]', 'inflected', 'heb', 'תָּמַךְ', '["tâmak"]', '["from/ taking hold"]', '["v"]', 'to sustain; by implication, to obtain, keep fast; figuratively, to help, follow close (take, up-) hold (up), maintain, retain, stay (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7810}/[H7809]', 'inflected', 'heb', 'שַׁחַד', '["shachad"]', '["for/ a bribe","on <the>/ bribe"]', '["n-m"]', 'a donation (venal or redemptive) bribe(-ry), gift, present, reward.', 'from 7809;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6105B}/[H6106]', 'inflected', 'heb', 'עָצַם', '["ʻâtsam"]', '["and/ [one who] shuts"]', '["v"]', 'to bind fast, i.e. close (the eyes); intransitively, to be (causatively, make) powerful or numerous; to crunch the bones break the bones, close, be great, be increased, be (wax) mighty(-ier), be more, shut, be(-come, make) strong(-er).', 'a primitive root; also denominatively (from 6106)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4679}/[H6679]', 'lemma', 'heb', 'מְצַד', '["mᵉtsad"]', '["[will be] strongholds of"]', '["n-f"]', 'a fastness (as a covert of ambush) castle, fort, (strong) hold, munition.', 'or מְצָד; or (feminine) מְצָדָה; from 6679;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4869A}/H9023/[H7682]', 'inflected', 'heb', 'מִשְׂגָּב', '["misgâb"]', '["refuge/ his"]', '["n-m n-pr-loc"]', 'properly, a cliff (or other lofty or inaccessible place); abstractly, altitude; figuratively, a refuge; Misgab, a place in Moab defence, high fort (tower), refuge, Misgab.', 'from 7682;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3899H}/H9023/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["food/ his"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3308}/H9023/[H3302]', 'inflected', 'heb', 'יֳפִי', '["yŏphîy"]', '["in/ beauty/ his","in/ beauty/ its"]', '["n-m"]', 'beauty beauty.', 'from 3302;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3267}/[H3267]', 'lemma', 'heb', 'יָעַז', '["yâʻaz"]', '["barbarous"]', '["v"]', 'to be bold or obstinate fierce.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6012}/[H6009]', 'lemma', 'heb', 'עָמֵק', '["ʻâmêq"]', '["[too] unintelligible of","deep of"]', '["a"]', 'deep (literally or figuratively) deeper, depth, strange.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8085J}/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["for/ hearing"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4150H}/H9025/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["appointed feast/ our"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6813}/[H6813]', 'lemma', 'heb', 'צָעַן', '["tsâʻan"]', '["anyone will pack up"]', '["v"]', 'to load up (beasts), i.e. to migrate be taken down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7885}/[H7751]', 'lemma', 'heb', 'שַׁיִט', '["shayiṭ"]', '["rowing"]', '["n-m"]', 'an oar; a scourge (figuratively) oar, scourge.', 'from 7751; also (compare 7752)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5674A}/H9033/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["[whom] it has passed over/ him","he will pass along/ it","it will pass along/ it","it will pass over/ it","they will pass over/ it"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8199}/H9035/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["[is] judge/ our","judges/ our","they judged/ us"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2710}/H9035/[H2710]', 'inflected', 'heb', 'חָקַק', '["châqaq"]', '["[is] commander/ our"]', '["v"]', 'properly, to hack, i.e. engrave (Judges 5:14, to be a scribe simply); by implication, to enact (laws being cut in stone or metal tablets in primitive times) or (gen.) prescribe appoint, decree, governor, grave, lawgiver, note, pourtray, print, set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2256M}/H9022/[H2254]', 'inflected', 'heb', 'חֶבֶל', '["chebel"]', '["ropes/ your"]', '["n-m"]', 'a rope (as twisted), especially a measuring line; by implication, a district or inheritance (as measured); or a noose (as of cords); figuratively, a company (as if tied together); a throe (especially of parturition); also ruin band, coast, company, cord, country, destruction, line, lot, pain, pang, portion, region, rope, snare, sorrow, tackling.', 'or חֵבֶל; from 2254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8650}/H9028/[H766]', 'inflected', 'heb', 'תֹּרֶן', '["tôren"]', '["mast/ their"]', '["n-m"]', 'a pole (as a mast or flagstaff) beacon, mast.', 'probably for 766;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4766}/[H7235]', 'lemma', 'heb', 'מַרְבֶה', '["marbeh"]', '["in abundance"]', '["n-m"]', 'properly, increasing; as noun, greatness, or (adverbially) greatly great, increase.', 'from 7235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6631}/H9024/[H3318]', 'inflected', 'heb', 'צֶאֱצָא', '["tseʼĕtsâʼ"]', '["produce<s>/ its"]', '["n-m"]', 'issue, i.e. produce, children that which cometh forth (out), offspring.', 'from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2874}/[H2873]', 'inflected', 'heb', 'טֶבַח', '["ṭebach"]', '["[which] to the/ slaughter","for/ slaughter","for/ slaughtering","to <the>/ slaughter","to the/ slaughter"]', '["n-m"]', 'properly, something slaughtered; hence, a beast (or meat, as butchered); abstractly butchery (or concretely, a place of slaughter) × beast, slaughter, × slay, × sore.', 'from 2873;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2491A}/H9028/[H2490]', 'inflected', 'heb', 'חָלָל', '["châlâl"]', '["and/ slain [ones]/ their"]', '["n-m"]', 'pierced (especially to death); figuratively, polluted kill, profane, slain (man), × slew, (deadly) wounded.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6297}/H9028/[H6296]', 'inflected', 'heb', 'פֶּגֶר', '["peger"]', '["and/ corpses/ their"]', '["n-m"]', 'a carcase (as limp), whether of man or beast; figuratively, an idolatrous image carcase, corpse, dead body.', 'from 6296;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0889}/H9028/[H877]', 'inflected', 'heb', 'בְּאֹשׁ', '["bᵉʼôsh"]', '["stench/ their"]', '["n-m"]', 'a stench stink.', 'from 877;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1818}/H9028/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["from/ blood/ their"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4743}/[H4743]', 'inflected', 'heb', 'מָקַק', '["mâqaq"]', '["and/ they will rot away","and/ they will waste away","and/ you will waste away"]', '["v"]', 'to melt; figuratively, to flow, dwindle, vanish consume away, be corrupt, dissolve, pine away.', ''' a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5612A}/[H9]', 'inflected', 'heb', 'סֵפֶר', '["çêpher"]', '["like <the>/ scroll"]', '["n-m"]', 'properly, writing (the art or a document); by implication, a book bill, book, evidence, × learn(-ed) (-ing), letter, register, scroll.', 'or (feminine) סִפְרָה; (Psalm 56:8 (9)), from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5034B}/[H5034]', 'inflected', 'heb', 'נָבֵל', '["nâbêl"]', '["as/ withers"]', '["v"]', 'to wilt; generally, to fall away, fail, faint; figuratively, to be foolish or (morally) wicked; causatively, to despise, disgrace disgrace, dishounour, lightly esteem, fade (away, -ing), fall (down, -ling, off), do foolishly, come to nought, × surely, make vile, wither.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H5034B}/[H5034]', 'inflected', 'heb', 'נָבֵל', '["nâbêl"]', '["and/ like/ withered fruit"]', '["v"]', 'to wilt; generally, to fall away, fail, faint; figuratively, to be foolish or (morally) wicked; causatively, to despise, disgrace disgrace, dishounour, lightly esteem, fade (away, -ing), fall (down, -ling, off), do foolishly, come to nought, × surely, make vile, wither.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8384}/[H8384]', 'inflected', 'heb', 'תְּאֵן', '["tᵉʼên"]', '["from/ a fig tree"]', '["n-f"]', 'the fig (tree or fruit) fig (tree).', 'or (in the singular, feminine) תְּאֵנָה; perhaps of foreign derivation');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1224G}/[H1223]', 'inflected', 'heb', 'בׇּצְרָה', '["Botsrâh"]', '["in/ Bozrah"]', '["n-pr-loc"]', 'Botsrah, a place in Edom Bozrah.', 'the same as 1223;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2874}/[H2873]', 'inflected', 'heb', 'טֶבַח', '["ṭebach"]', '["and/ a slaughter"]', '["n-m"]', 'properly, something slaughtered; hence, a beast (or meat, as butchered); abstractly butchery (or concretely, a place of slaughter) × beast, slaughter, × slay, × sore.', 'from 2873;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7301}/[H7301]', 'inflected', 'heb', 'רָוָה', '["râvâh"]', '["and/ I will satisfy","and/ it will drink its fill","and/ it will take its fill"]', '["v"]', 'to slake the thirst (occasionally of other appetites) bathe, make drunk, (take the) fill, satiate, (abundantly) satisfy, soak, water (abundantly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6083}/H9028/[H6080]', 'inflected', 'heb', 'עָפָר', '["ʻâphâr"]', '["and/ dust/ their"]', '["n-m"]', 'dust (as powdered or gray); hence, clay, earth, mud ashes, dust, earth, ground, morter, powder, rubbish.', 'from 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7966}/[H7999]', 'lemma', 'heb', 'שִׁלּוּם', '["shillûwm"]', '["retribution<s>"]', '["n-m"]', 'a requital, i.e. (secure) retribution, (venal) a fee recompense, reward.', 'or שִׁלֻּם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7379}/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["for/ [the] cause of","for/ strife"]', '["n-m"]', 'a contest (personal or legal) adversary, cause, chiding, contend(-tion), controversy, multitude (from the margin), pleading, strife, strive(-ing), suit.', 'or רִב; from 7378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5158A}/H9024/[H5157]', 'inflected', 'heb', 'נַחַל', '["nachal"]', '["torrents/ its"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H2203>', 'inflected', 'heb', 'לזפת', '["le./Ze.fet"]', '["<into>/ pitch","into/ pitch"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6083}/H9024/[H6080]', 'inflected', 'heb', 'עָפָר', '["ʻâphâr"]', '["and/ dust/ its"]', '["n-m"]', 'dust (as powdered or gray); hence, clay, earth, mud ashes, dust, earth, ground, morter, powder, rubbish.', 'from 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1614}/[H1613]', 'inflected', 'heb', 'גׇּפְרִית', '["gophrîyth"]', '["into/ sulfur"]', '["n-f"]', 'properly, cypress-resin; by analogy, sulphur (as equally inflammable) brimstone.', 'probably feminine of 1613;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6227}/H9024/[H6225]', 'inflected', 'heb', 'עָשָׁן', '["ʻâshân"]', '["smoke/ its"]', '["n-m"]', 'smoke, literally or figuratively (vapor, dust, anger) smoke(-ing).', 'from 6225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3423G}/H9034/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["and/ they will take possession of/ it"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6893}/[H6958]', 'lemma', 'heb', 'קָאַת', '["qâʼath"]', '["desert owl"]', '["n-f"]', 'probably the pelican (from vomiting) cormorant.', 'from 6958;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7090}/[H7088]', 'inflected', 'heb', 'קִפּוֹד', '["qippôwd"]', '["and/ hedgehog"]', '["n-m"]', 'a species of bird, perhaps the bittern (from its contracted form) bittern.', 'or קִפֹּדlemma קִכֹּד kaf, corrected to קִפֹּד; from 7088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3244}/[H5398]', 'inflected', 'heb', 'יַנְשׁוּף', '["yanshûwph"]', '["and/ great owl"]', '["n-m"]', 'an unclean (acquatic) bird; probably the heron (perhaps from its blowing cry, or because the nightheron is meant) (great) owl.s', 'or יַנְשׁוֹף; apparently from 5398; (compare 5399)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6158}/[H6150]', 'inflected', 'heb', 'עֹרֵב', '["ʻôrêb"]', '["and/ raven"]', '["n-m"]', 'a raven (from its dusky hue) raven.', 'or עוֹרֵב; from 6150;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0922>', 'opaque', 'heb', 'בֹּהוּ', '["bôhûw"]', '["emptiness"]', '["n-m"]', 'a vacuity, i.e. (superficially) an undistinguishable ruin emptiness, void.', 'from an unused root (meaning to be empty);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2715}/H9024/[H2787]', 'inflected', 'heb', 'חֹר', '["chôr"]', '["nobles/ its"]', '["n-m"]', 'properly, white or pure (from the cleansing or shining power of fire); hence (figuratively) noble (in rank) noble.', 'or (fully) חוֹר; from 2787; (compare 2751)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0759H>/H9024', 'opaque', 'heb', 'אַרְמוֹן', '["ʼarmôwn"]', '["fortresses/ its"]', '["n-m"]', 'a citadel (from its height) castle, palace. Compare 2038.', 'from an unused root (meaning to be elevated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5518B}/[H5518]', 'lemma', 'heb', 'סִיר', '["çîyr"]', '["thorns"]', '["n-m"]', 'a pot; also a thorn (as springing up rapidly); by implication, a hook caldron, fishhook, pan, (wash-)pot, thorn.', 'or (feminine) סִירָה; or סִרָה; (Jeremiah 52:18), from a primitive root meaning to boil up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7057>', 'opaque', 'heb', 'קִמּוֹשׁ', '["qimmôwsh"]', '["nettle[s]"]', '["n-m"]', 'a prickly plant nettle. Compare 7063.', 'or קִימוֹשׁ; from an unused root meaning to sting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H2336>', 'inflected', 'heb', 'וחוח', '["va./Cho.ach"]', '["and/ thornbush[es]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4013}/H9024/[H1219]', 'inflected', 'heb', 'מִבְצָר', '["mibtsâr"]', '["[will be] on/ fortifications/ its"]', '["n-m"]', 'a fortification, castle, or fortified city; figuratively, a defender (de-, most) fenced, fortress, (most) strong (hold).', 'also (in plural) feminine (Daniel 11:l5) מִבְצָרָה; from 1219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2681}/[H2691]', 'lemma', 'heb', 'חָצִיר', '["châtsîyr"]', '["grass"]', '["n-m"]', 'a court or abode court.', 'a collateral form of 2691;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3917}/[H3915]', 'lemma', 'heb', 'לִילִית', '["lîylîyth"]', '["[the] night-creature"]', '["n-f"]', 'a night spectre screech owl.', 'from 3915;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7091>', 'opaque', 'heb', 'קִפּוֹז', '["qippôwz"]', '["owl[s]"]', '["n-m"]', 'spring forward; an arrow-snake (as darting on its prey) great owl.', 'from an unused root meaning to contract, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1716}/[H1716]', 'inflected', 'heb', 'דָּגַר', '["dâgar"]', '["and/ it will gather a brood"]', '["v"]', 'to brood over eggs or young gather, sit.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6738}/H9024/[H6751]', 'inflected', 'heb', 'צֵל', '["tsêl"]', '["in/ shadow/ its"]', '["n-m"]', 'shade, whether literal or figurative defence, shade(-ow).', 'from 6751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1772}/[H1675]', 'lemma', 'heb', 'דַּיָּה', '["dayâh"]', '["black kites"]', '["n-f"]', 'a falcon (from its rapid flight) vulture.', 'intensive from 1675;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7121J}/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["and/ read"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7307G}/H9023/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["and/ spirit/ his"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6908}/H9039/[H6908]', 'inflected', 'heb', 'קָבַץ', '["qâbats"]', '["it will gather/ them"]', '["v"]', 'to grasp, i.e. collect assemble (selves), gather (bring) (together, selves together, up), heap, resort, × surely, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2505A}/H9034/[H2505]', 'inflected', 'heb', 'חָלַק', '["châlaq"]', '["it has distributed/ it"]', '["v"]', 'to be smooth (figuratively); by implication (as smooth stones were used for lots) to apportion or separate deal, distribute, divide, flatter, give, (have, im-) part(-ner), take away a portion, receive, separate self, (be) smooth(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6957B}/[H6960]', 'inflected', 'heb', 'קַו', '["qav"]', '["by the/ measuring-line"]', '["n-m"]', 'a cord (as connecting), especially for measuring; figuratively, a rule; also a rim, a musical string or accord line. Compare 6978.', 'or קָו; from 6960 (compare 6961);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3423G}/H9034/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["they will possess/ it"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7797}/H9013/[H7797]', 'inflected', 'heb', 'שׂוּשׂ', '["sûws"]', '["they will rejoice/ !"]', '["v"]', 'to be bright, i.e. cheerful be glad, × greatly, joy, make mirth, rejoice.', 'or שִׂישׂ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6723>', 'inflected', 'heb', 'וציה', '["ve./tzi.Yah"]', '["and/ [the] dry region"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6524A}/[H6524]', 'inflected', 'heb', 'פָּרַח', '["pârach"]', '["so/ it may bud","so/ they may blossom"]', '["v"]', 'to break forth as a bud, i.e. bloom; generally, to spread; specifically, to fly (as extending the wings); figuratively, to flourish × abroad, × abundantly, blossom, break forth (out), bud, flourish, make fly, grow, spread, spring (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H2261>', 'inflected', 'heb', 'כחבצלת', '["ka./cha.va.Tza.let"]', '["like/ a crocus"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1525}/[H1524]', 'lemma', 'heb', 'גִּילָה', '["gîylâh"]', '["gladness"]', '["n-f"]', 'joy joy, rejoicing.', 'or גִּילַת; feminine of 1524;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3760G}/[H3759]', 'inflected', 'heb', 'כַּרְמֶל', '["Karmel"]', '["<the>/ Carmel"]', '["n-pr-loc"]', 'Karmel, the name of a hill and of a town in Palestine Carmel, fruitful (plentiful) field, (place).', 'the same as 3759;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8289I}/[H3474]', 'inflected', 'heb', 'שָׁרוֹן', '["Shârôwn"]', '["and/ <the>/ Sharon"]', '["n-pr"]', 'Sharon, the name of a place in Palestine Lasharon, Sharon.', 'probably abridged from 3474; plain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3467}/H9036/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["and/ he may deliver/ you"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H8273>', 'inflected', 'heb', 'השרב', '["ha./sha.Rav"]', '["the/ parched ground"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4002}/[H5042]', 'inflected', 'heb', 'מַבּוּעַ', '["mabbûwaʻ"]', '["<into>/ springs of"]', '["n-m"]', 'a fountain fountain, spring.', 'from 5042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7258}/H9024/[H7257]', 'inflected', 'heb', 'רֵבֶץ', '["rêbets"]', '["resting place/ its"]', '["n-m"]', 'a couch or place of repose where each lay, lie down in, resting place.', 'from 7257;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7070H}/[H7069]', 'inflected', 'heb', 'קָנֶה', '["qâneh"]', '["<into>/ reed[s]"]', '["n-m"]', 'a reed (as erect); by resemblance a rod (especially for measuring), shaft, tube, stem, the radius (of the arm), beam (of a steelyard) balance, bone, branch, calamus, cane, reed, × spearman, stalk.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1573}/[H1572]', 'inflected', 'heb', 'גֹּמֶא', '["gômeʼ"]', '["and/ papyrus"]', '["n-m"]', 'properly, an absorbent, i.e. the bulrush (from its porosity); specifically the papyrus (bul-) rush.', 'from 1572;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4547}/[H5549]', 'lemma', 'heb', 'מַסְלוּל', '["maçlûwl"]', '["a highway"]', '["n-m"]', 'a thoroughfare (as turnpiked) highway.', 'from 5549;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1870H}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["and/ [the] way of"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6944I}/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["<the>/ holiness"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6530}/[H6555]', 'inflected', 'heb', 'פְּרִיץ', '["pᵉrîyts"]', '["and/ a violent one of"]', '["n-m"]', 'violent, i.e. a tyrant destroyer, ravenous, robber.', 'from 6555;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5927G}/H9034/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["it will go up on/ it"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0585}\/[H584]', 'inflected', 'heb', 'אֲנָחָה', '["ʼănâchâh"]', '["and/ sighing"]', '["n-f"]', 'sighing groaning, mourn, sigh.', 'from 584;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0413}/[H413]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["¿/ to"]', '["prep"]', 'near, with or among; often in general, to about, according to, after, against, among, as for, at, because(-fore, -side), both...and, by, concerning, for, from, × hath, in(-to), near, (out) of, over, through, to(-ward), under, unto, upon, whether, with(-in).', '(but only used in the shortened constructive form אֶל ); a primitive particle; properly, denoting motion towards, but occasionally used of a quiescent position, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2396G}\/[H2388]', 'inflected', 'heb', 'חִזְקִיָּה', '["Chizqîyâh"]', '["Hezekiah"]', '["n-pr-m"]', 'Chizkijah, a king of Judah, also the name of two other Israelites Hezekiah, Hizkiah, Hizkijah. Compare 3169.', 'or חִזְקִיָּהוּ; also יְחִזְקִיָּה; or יְחִזְקִיָּהוּ; from 2388 and 3050; strengthened of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7262}\/[H7227]', 'inflected', 'heb', 'רַבְשָׁקֵה', '["Rabshâqêh"]', '["commander"]', '["n-m"]', 'Rabshakeh, a Babylonian official Rabshakeh.', 'from 7227 and 8248; chief butler;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5414L}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ they have put"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7709}/[H7704]', 'inflected', 'heb', 'שְׁדֵמָה', '["shᵉdêmâh"]', '["and/ a field","and/ fields"]', '["n-f"]', 'a cultivated field blasted, field.', 'apparently from 7704;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5650}/H9020\/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["servant/ my"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8272G}/[H8272]', 'inflected', 'heb', 'שַׁרְאֶצֶר', '["Sharʼetser"]', '["and/ Sharezer"]', '["n-pr-m"]', 'Sharetser, the name of an Assyrian and an Israelite Sharezer.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1004M}/H9021/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["for/ house/ your","to/ household/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H8121>', 'inflected', 'heb', 'בשמש', '["ba./She.mesh"]', '["with the/ sun"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3381}\/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["it had gone down"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2470H}/H9043/[H2342]', 'inflected', 'heb', 'חָלָה', '["châlâh"]', '["when/ was sick/ he"]', '["v"]', 'properly, to be rubbed or worn; hence (figuratively) to be weak, sick, afflicted; or (causatively) to grieve, make sick; also to stroke (in flattering), entreat beseech, (be) diseased, (put to) grief, be grieved, (be) grievous, infirmity, intreat, lay to, put to pain, × pray, make prayer, be (fall, make) sick, sore, be sorry, make suit (× supplication), woman in travail, be (become) weak, be wounded.', 'a primitive root (compare 2342, 2470, 2490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2483}/H9023/[H2470]', 'inflected', 'heb', 'חֳלִי', '["chŏlîy"]', '["from/ sickness/ his"]', '["n-m"]', 'malady, anxiety, calamity disease, grief, (is) sick(-ness).', 'from 2470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1824}/[H1820]', 'inflected', 'heb', 'דְּמִי', '["dᵉmîy"]', '["in/ [the] half of"]', '["n-m"]', 'quiet cutting off, rest, silence.', 'or דֳּמִי; from 1820;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8141}/H9020/[H8138]', 'inflected', 'heb', 'שָׁנֶה', '["shâneh"]', '["years/ my"]', '["n-f"]', 'a year (as a revolution of time) whole age, × long, old, year(× -ly).', '(in plural or (feminine) שָׁנָה; from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2309}/[H2308]', 'lemma', 'heb', 'חֶדֶל', '["chedel"]', '["cessation"]', '["n-m"]', 'rest, i.e. the state of the dead world.', 'from 2308;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1755}/H9020/[H1752]', 'inflected', 'heb', 'דּוֹר', '["dôwr"]', '["dwelling-place/ my"]', '["n-m"]', 'properly, a revolution of time, i.e. an age or generation; also a dwelling age, × evermore, generation, (n-) ever, posterity.', 'or (shortened) דֹּר; from 1752;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1540K}/[H1540]', 'inflected', 'heb', 'גָּלָה', '["gâlâh"]', '["and/ go into exile","and/ it has been removed"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7088}/[H7088]', 'lemma', 'heb', 'קָפַד', '["qâphad"]', '["I have rolled up"]', '["v"]', 'to contract, i.e. roll together cut off.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0707}/[H707]', 'inflected', 'heb', 'אָרַג', '["ʼârag"]', '["like <the>/ weaver"]', '["v"]', 'to plait or weave weaver(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1803A}/[H1802]', 'inflected', 'heb', 'דַּלָּה', '["dallâh"]', '["from/ [the] loom"]', '["n-f"]', 'properly, something dangling, i.e. a loose thread or hair; figuratively, indigent hair, pining sickness, poor(-est sort).', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1214G}/H9030/[H1214]', 'inflected', 'heb', 'בָּצַע', '["bâtsaʻ"]', '["he cuts off/ me"]', '["v"]', 'to break off, i.e. (usually) plunder; figuratively, to finish, or (intransitively) stop (be) covet(-ous), cut (off), finish, fulfill, gain (greedily), get, be given to (covetousness), greedy, perform, be wounded.', 'a primitive root');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H5483A>', 'inflected', 'heb', 'כסוס', '["ke./Sus"]', '["like/ a swallow"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5693>', 'opaque', 'heb', 'עָגוּר', '["ʻâgûwr"]', '["a crane"]', '["n-m"]', 'probably the swallow swallow.', 'passive part (but with active sense) of an unused root meaning to twitter;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6234}/[H6233]', 'lemma', 'heb', 'עׇשְׁקָה', '["ʻoshqâh"]', '["oppression"]', '["n-f"]', 'anguish oppressed.', 'feminine of 6233;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1718}/[H1718]', 'lemma', 'heb', 'דָּדָה', '["dâdâh"]', '["I will walk deliberately"]', '["v"]', 'to walk gently go (softly, with).', 'a doubtful root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2492A}/H9030/[H2492]', 'inflected', 'heb', 'חָלַם', '["châlam"]', '["and/ may you restore to health/ me"]', '["v"]', 'properly, to bind firmly, i.e. (by implication) to be (causatively to make) plump; also (through the figurative sense of dumbness) to dream (cause to) dream(-er), be in good liking, recover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2421}/H9030/[H2331]', 'inflected', 'heb', 'חָיָה', '["châyâh"]', '["and/ preserve alive/ me"]', '["v"]', 'to live, whether literally or figuratively; causatively, to revive keep (leave, make) alive, × certainly, give (promise) life, (let, suffer to) live, nourish up, preserve (alive), quicken, recover, repair, restore (to life), revive, (× God) save (alive, life, lives), × surely, be whole.', 'a primitive root (compare 2331, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1460A}/H9021/[H1342]', 'inflected', 'heb', 'גֵּו', '["gêv"]', '["back/ your"]', '["n-m"]', 'the back; by analogy, the middle among, back, body.', 'from 1342 (corresponding to 1354);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5058}/H9020/[H5059]', 'inflected', 'heb', 'נְגִינָה', '["nᵉgîynâh"]', '["and/ songs/ my"]', '["n-f"]', 'properly, instrumental music; by implication, a stringed instrument; by extension, a poem set to music; specifically, an epigram stringed instrument, musick, Neginoth (plural), song.', 'or נְגִינַת; (Psalm 61:title), from 5059;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2416E}/H9025/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["lives/ our"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4799}/[H4799]', 'inflected', 'heb', 'מָרַח', '["mârach"]', '["and/ let them rub [it]"]', '["v"]', 'properly, to soften by rubbing or pressure; hence (medicinally) to apply as an emollient lay for a plaister.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4757}/[H4757]', 'lemma', 'heb', 'מְרֹאדַךְ בַּלְאָדָן', '["Mᵉrôʼdak Balʼâdân"]', '["Baladan","Merodach-"]', '["n-pr-m"]', 'Merodak-Baladan, a Babylonian king Merodach-baladan. Compare 4781.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1004P}/H9021/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["[is] in/ house/ your","in/ house/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1004P}/H9020/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["[is] in/ house/ my"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1121A}/H9021/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ some of/ own descendants/ your"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3117G>/H9020\', 'inflected', 'heb', 'בימי פ', '["be./ya.Ma/i"]', '["in/ days/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6635H}/H9024/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["service/ its"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2403B}/H9024\/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["sins/ its"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6121B}/[H6117]', 'inflected', 'heb', 'עָקֹב', '["ʻâqôb"]', '["the/ steep [place]"]', '["a"]', '(transitive) fraudulent or (intransitive) tracked crooked, deceitful, polluted.', 'from 6117; in the original sense, a knoll (as swelling up); in the denominative sense');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4334}/[H3474]', 'inflected', 'heb', 'מִישׁוֹר', '["mîyshôwr"]', '["<into>/ level ground"]', '["n-m"]', 'a level, i.e. a plain (often used (with the article prefix) as a proper name of certain districts); figuratively, concord; also straightness, i.e. (figuratively) justice (sometimes adverbially, justly) equity, even place, plain, right(-eously), (made) straight, uprightness.', 'or מִישֹׁר; from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7406}/[H7405]', 'inflected', 'heb', 'רֶכֶס', '["rekeç"]', '["and/ the/ rough places"]', '["n-m"]', 'a mountain ridge (as of tied summits) rough place.', 'from 7405;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1237K}/[H1234]', 'inflected', 'heb', 'בִּקְעָה', '["biqʻâh"]', '["<into>/ a plain"]', '["n-f"]', 'properly, a split, i.e. a wide level valley between mountains plain, valley.', 'from 1234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2389}/[H2388]', 'inflected', 'heb', 'חָזָק', '["châzâq"]', '["<in>/ a strong [one]"]', '["a"]', 'strong (usu. in a bad sense, hard, bold, violent) harder, hottest, impudent, loud, mighty, sore, stiff(-hearted), strong(-er).', 'from 2388;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6468}/H9023/[H6466]', 'inflected', 'heb', 'פְּעֻלָּה', '["pᵉʻullâh"]', '["and/ recompense/ his"]', '["n-f"]', '(abstractly) work labour, reward, wages, work.', 'feminine passive participle of 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7462B}/[H7462]', 'inflected', 'heb', 'רָעָה', '["râʻâh"]', '["like/ a shepherd"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5739}/H9023/[H5737]', 'inflected', 'heb', 'עֵדֶר', '["ʻêder"]', '["flock/ his"]', '["n-m"]', 'an arrangement, i.e. muster (of animals) drove, flock, herd.', 'from 5737;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2220}/H9023/[H2232]', 'inflected', 'heb', 'זְרוֹעַ', '["zᵉrôwaʻ"]', '["in/ arm[s]/ his"]', '["n-f"]', 'the arm (as stretched out), or (of animals) the foreleg; figuratively, force arm, help, mighty, power, shoulder, strength.', 'or (shortened) זְרֹעַ; and (feminine) זְרוֹעָה; or זְרֹעָה; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2922}/[H2921]', 'lemma', 'heb', 'טְלָא', '["ṭᵉlâʼ"]', '["lambs"]', '["n-m"]', 'a lamb lamb.', 'apparently from 2921 in the (orig.) sense of covering (for protection); (compare 2924)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5095}\/[H5095]', 'inflected', 'heb', 'נָהַל', '["nâhal"]', '["he will lead"]', '["v"]', 'properly, to run with a sparkle, i.e. flow; hence (transitively), to conduct, and (by inference) to protect, sustain carry, feed, guide, lead (gently, on).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H8168>/H9023', 'inflected', 'heb', 'בשעלו', '["be./sho.''o.L/o"]', '["in/ [the] hollow of hand/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2239}/[H2219]', 'inflected', 'heb', 'זֶרֶת', '["zereth"]', '["with <the>/ span"]', '["n-f"]', 'the spread of the fingers, i.e. a span span.', 'from 2219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7991A}/[H7969]', 'inflected', 'heb', 'שָׁלִישׁ', '["shâlîysh"]', '["in <the>/ third of a measure"]', '["n-m"]', 'a triple, i.e. (as a musical instrument) a triangle (or perhaps rather three-stringed lute); also (as an indefinite, great quantity) a three-fold measure (perhaps a treble ephah); also (as an officer) a general of the third rank (upward, i.e. the highest) captain, instrument of musick, (great) lord, (great) measure, prince, three (from the margin).', 'or שָׁלוֹשׁ; (1 Chronicles 11:11; 1 Chronicles 12:18), or שָׁלֹשׁ; (2 Samuel 23:13), from 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6425}/[H6424]', 'inflected', 'heb', 'פֶּלֶס', '["peleç"]', '["with <the>/ balance"]', '["n-m"]', 'a balance scales, weight.', 'from 6424;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0995}/H9033/[H995]', 'inflected', 'heb', 'בִּין', '["bîyn"]', '["and/ did he give understanding?/ him"]', '["v"]', 'to separate mentally (or distinguish), i.e.(generally) understand attend, consider, be cunning, diligently, direct, discern, eloquent, feel, inform, instruct, have intelligence, know, look well to, mark, perceive, be prudent, regard, (can) skill(-full), teach, think, (cause, make to, get, give, have) understand(-ing), view, (deal) wise(-ly, man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3925G}/H9033/[H3925]', 'inflected', 'heb', 'לָמַד', '["lâmad"]', '["and/ did he teach?/ him"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4752}/[H4843]', 'inflected', 'heb', 'מַר', '["mar"]', '["like/ a drop"]', '["n-m"]', 'a drop drop.', 'from 4843 in its original sense of distillation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1805}/[H1802]', 'inflected', 'heb', 'דְּלִי', '["dᵉlîy"]', '["from/ a bucket"]', '["n-m"]', 'a pail or jar (for drawing water) bucket.', 'or דֳּלִי; from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H7834}/[H7833]', 'inflected', 'heb', 'שַׁחַק', '["shachaq"]', '["and/ like/ [the] dust of"]', '["n-m"]', 'a powder (as beaten small); by analogy, a thin vapor; by extension, the firmament cloud, small dust, heaven, sky.', 'from 7833;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1851}/[H1854]', 'inflected', 'heb', 'דַּק', '["daq"]', '["like <the>/ fine [dust]"]', '["a"]', 'crushed, i.e. (by implication) small or thin dwarf, lean(-fleshed), very little thing, small, thin.', 'from 1854;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3844G}/[H3825]', 'inflected', 'heb', 'לְבָנוֹן', '["Lᵉbânôwn"]', '["and/ Lebanon"]', '["n-pr-loc"]', 'Lebanon, a mountain range in Palestine Lebanon.', 'from 3825; (the) white mountain (from its snow);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0657A}/[H656]', 'inflected', 'heb', 'אֶפֶס', '["ʼepheç"]', '["from/ [the] ends of","from/ nothingness"]', '["n-m"]', 'cessation, i.e. an end (especially of the earth); often used adverb, no further; also the ankle (in the dual), as being the extremity of the leg or foot ankle, but (only), end, howbeit, less than nothing, nevertheless (where), no, none (beside), not (any, -withstanding), thing of nought, save(-ing), there, uttermost part, want, without (cause).', 'from 656; (sometimes like 6466)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H8414>', 'inflected', 'heb', 'ותהו', '["va./To.hu"]', '["and/ emptiness"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1819}/H9013/[H1819]', 'inflected', 'heb', 'דָּמָה', '["dâmâh"]', '["will you liken/ !"]', '["v"]', 'to compare; by implication, to resemble, liken, consider compare, devise, (be) like(-n), mean, think, use similitudes.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7554}/H9033/[H7554]', 'inflected', 'heb', 'רָקַע', '["râqaʻ"]', '["he will overlay/ it"]', '["v"]', 'to pound the earth (as a sign of passion); by analogy to expand (by hammering); by implication, to overlay (with thin sheets of metal) beat, make broad, spread abroad (forth, over, out, into plates), stamp, stretch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7577}/[H7576]', 'inflected', 'heb', 'רְתֻקָה', '["rᵉthuqâh"]', '["and/ chains of"]', '["n-f"]', 'something fastened, i.e. a chain chain.', 'feminine passive participle of 7576;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5533B}/[H7915]', 'inflected', 'heb', 'סָכַן', '["çâkan"]', '["the/ impoverished [person]"]', '["v"]', 'properly, to cut, i.e. damage; also to grow (causatively, make) poor endanger, impoverish.', 'probably a denominative from 7915;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3427}/H9024/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["and/ inhabitants/ its"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1852}/[H1854]', 'inflected', 'heb', 'דֹּק', '["dôq"]', '["like <the>/ curtain"]', '["n-m"]', 'something crumbling, i.e. fine (as a thin cloth) curtain.', 'from 1854;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4969}/H9038/[H4969]', 'inflected', 'heb', 'מָתַח', '["mâthach"]', '["and/ he spread out/ them"]', '["v"]', 'to stretch out spread out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5414I}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["the/ [one who] appoints","who/ made"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H8414>', 'inflected', 'heb', 'כתהו', '["ka./To.hu"]', '["like <the>/ nothingness"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1503>/H9028', 'opaque', 'heb', 'גֶּזַע', '["gezaʻ"]', '["rootstock/ their"]', '["n-m"]', 'the trunk or stump of a tree (as felled or as planted) stem, stock.', 'from an unused root meaning to cut down (trees);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375H}/H9038\/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["it carries off/ them"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1819}/H9030/[H1819]', 'inflected', 'heb', 'דָּמָה', '["dâmâh"]', '["will you liken/ me"]', '["v"]', 'to compare; by implication, to resemble, liken, consider compare, devise, (be) like(-n), mean, think, use similitudes.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7737A}/[H7737]', 'inflected', 'heb', 'שָׁוָה', '["shâvâh"]', '["and/ I may be equal?","and/ you may make [me] equal?"]', '["v"]', 'properly, to level, i.e. equalize; figuratively, to resemble; by implication, to adjust (i.e. counterbalance, be suitable, compose, place, yield, etc.) avail, behave, bring forth, compare, countervail, (be, make) equal, lay, be (make, a-) like, make plain, profit, reckon.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5737C}\/[H5737]', 'inflected', 'heb', 'עֲדַר', '["ʻădar"]', '["it is missing"]', '["v"]', 'to arrange, as a battle, a vineyard (to hoe); hence, to muster and so to miss (or find wanting) dig, fail, keep (rank), lack.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0430G}/H9020/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["and/ from/ God/ my"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3286}/[H3286]', 'lemma', 'heb', 'יָעַף', '["yâʻaph"]', '["he grows weary","they grow weary","they will grow weary","wearied"]', '["v"]', 'to tire (as if from wearisome flight) faint, cause to fly, (be) weary (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3287}/[H3286]', 'inflected', 'heb', 'יָעֵף', '["yâʻêph"]', '["to the/ weary [person]"]', '["a"]', 'fatigued; figuratively, exhausted faint, weary.', 'from 3286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0369}/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["and/ to/ [those who] there not"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6109}/[H6108]', 'lemma', 'heb', 'עׇצְמָה', '["ʻotsmâh"]', '["strength"]', '["n-f"]', 'powerfulness; by extension, numerousness abundance, strength.', 'feminine of 6108;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3286}/[H3286]', 'inflected', 'heb', 'יָעַף', '["yâʻaph"]', '["and/ they may grow weary"]', '["v"]', 'to tire (as if from wearisome flight) faint, cause to fly, (be) weary (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3021}/[H3021]', 'inflected', 'heb', 'יָגַע', '["yâgaʻ"]', '["and/ they may labor","so/ they may become weary","so/ they may labor"]', '["v"]', 'properly, to gasp; hence, to be exhausted, to tire, to toil faint, (make to) labour, (be) weary.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3286}\/[H3286]', 'inflected', 'heb', 'יָעַף', '["yâʻaph"]', '["they will grow weary"]', '["v"]', 'to tire (as if from wearisome flight) faint, cause to fly, (be) weary (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0857}/H9013/[H225]', 'inflected', 'heb', 'אָתָה', '["ʼâthâh"]', '["and/ they have come/ !"]', '["v"]', 'to arrive (be-, things to) come (upon), bring.', 'or אָתָא; a primitive root (collateral to 225 contraction);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6360>', 'opaque', 'heb', 'פַּטִּישׁ', '["paṭṭîysh"]', '["[the] hammer of","a hammer"]', '["n-m"]', 'a hammer hammer.', 'intensively from an unused root meaning to pound;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1694}/[H1692]', 'inflected', 'heb', 'דֶּבֶק', '["debeq"]', '["of the/ soldering"]', '["n-m"]', 'a joint; by implication, solder joint, solder.', 'from 1692;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2388G}/H9033/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["and/ he strengthened/ it"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4548}/[H5568]', 'inflected', 'heb', 'מַסְמֵר', '["maçmêr"]', '["with/ nails"]', '["n-f"]', 'a peg (as bristling from the surface) nail.', 'or מִסְמֵר; also (feminine) מַסְמְרָה; or מִסְמְרָה; or even מַשְׂמְרָה; (Ecclesiastes 12:11), from 5568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4131}\/[H4131]', 'inflected', 'heb', 'מוֹט', '["môwṭ"]', '["it will be shaken"]', '["v"]', 'to waver; by implication, to slip, shake, fall be carried, cast, be out of course, be fallen in decay, × exceedingly, fall(-ing down), be (re-) moved, be ready, shake, slide, slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0977}/H9031/[H977]', 'inflected', 'heb', 'בָּחַר', '["bâchar"]', '["I have chosen/ you"]', '["v"]', 'properly, to try, i.e. (by implication) select acceptable, appoint, choose (choice), excellent, join, be rather, require.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2388J}/H9031/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["I took hold of/ you"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0678}/H9024/[H680]', 'inflected', 'heb', 'אָצִיל', '["ʼâtsîyl"]', '["and/ from/ remotest parts/ its"]', '["n-m"]', 'an extremity (Isaiah 41:9), also a noble chief man, noble.', 'from 680 (in its secondary sense of separation);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3988A}/H9031/[H3988]', 'inflected', 'heb', 'מָאַס', '["mâʼaç"]', '["I have rejected/ you"]', '["v"]', 'to spurn; also (intransitively) to disappear abhor, cast away (off), contemn, despise, disdain, (become) loathe(some), melt away, refuse, reject, reprobate, × utterly, vile person.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0553}/H9031/[H553]', 'inflected', 'heb', 'אָמַץ', '["ʼâmats"]', '["I have strengthened/ you"]', '["v"]', 'to be alert, physically (on foot) or mentally (in courage) confirm, be courageous (of good courage, stedfastly minded, strong, stronger), establish, fortify, harden, increase, prevail, strengthen (self), make strong (obstinate, speed).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8551}/H9031/[H8551]', 'inflected', 'heb', 'תָּמַךְ', '["tâmak"]', '["I have supported/ you"]', '["v"]', 'to sustain; by implication, to obtain, keep fast; figuratively, to help, follow close (take, up-) hold (up), maintain, retain, stay (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3225G}/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["with/ [the] right [hand] of"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2734}/[H2787]', 'inflected', 'heb', 'חָרָה', '["chârâh"]', '["those/ [who] are angry"]', '["v"]', 'to glow or grow warm; figuratively (usually) to blaze up, of anger, zeal, jealousy be angry, burn, be displeased, × earnestly, fret self, grieve, be (wax) hot, be incensed, kindle, × very, be wroth. See 8474.', 'a primitive root (compare 2787);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1245}/H9038/[H1245]', 'inflected', 'heb', 'בָּקַשׁ', '["bâqash"]', '["you will seek/ them"]', '["v"]', 'to search out (by any method, specifically in worship or prayer); by implication, to strive after ask, beg, beseech, desire, enquire, get, make inquisition, procure, (make) request, require, seek (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4695}/H9021/[H5327]', 'inflected', 'heb', 'מַצּוּת', '["matstsûwth"]', '["strife/ your"]', '["n-f"]', 'a quarrel that contended.', 'from 5327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0657A}/[H656]', 'inflected', 'heb', 'אֶפֶס', '["ʼepheç"]', '["and/ as/ nothing"]', '["n-m"]', 'cessation, i.e. an end (especially of the earth); often used adverb, no further; also the ankle (in the dual), as being the extremity of the leg or foot ankle, but (only), end, howbeit, less than nothing, nevertheless (where), no, none (beside), not (any, -withstanding), thing of nought, save(-ing), there, uttermost part, want, without (cause).', 'from 656; (sometimes like 6466)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5826}/H9031\/[H5826]', 'inflected', 'heb', 'עָזַר', '["ʻâzar"]', '["I will help/ you"]', '["v"]', 'to surround, i.e. protect or aid help, succour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5826}/H9032/[H5826]', 'inflected', 'heb', 'עָזַר', '["ʻâzar"]', '["I will help/ you"]', '["v"]', 'to surround, i.e. protect or aid help, succour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1350A}/H9022/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["and/ [is] redeemer/ your","and/ redeemer/ your"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7760A}/H9032/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["I should make/ you","I will make/ you"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H4173>', 'inflected', 'heb', 'למורג', '["le./mo.Rag"]', '["<into>/ a threshing-sledge"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1984H}\/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["they will boast","you will boast"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0034}/[H14]', 'inflected', 'heb', 'אֶבְיוֹן', '["ʼebyôwn"]', '["and/ the/ needy [people]"]', '["a-m"]', 'destitute beggar, needy, poor (man).', 'from 14, in the sense of want (especially in feeling);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5405}/[H5405]', 'lemma', 'heb', 'נָשַׁת', '["nâshath"]', '["it is dry","it will be dry"]', '["v"]', 'properly, to eliminate, i.e. (intransitively) to dry up fail.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1918>', 'inflected', 'heb', 'והדס', '["va./ha.Das"]', '["and/ myrtle tree[s]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8410}/[H1725]', 'lemma', 'heb', 'תִּדְהָר', '["tidhâr"]', '["elm","elm[s]"]', '["n-m"]', 'enduring; a species of hard-wood or lasting tree (perhaps oak) pine (tree).', 'apparently from 1725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8391}/[H833]', 'inflected', 'heb', 'תְּאַשּׁוּר', '["tᵉʼashshûwr"]', '["and/ box tree","and/ box tree[s]"]', '["n-f"]', 'a species of cedar (from its erectness) box (tree).', 'from 833;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7760K}/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["so/ I may set","so/ let us take [them]","so/ they may set"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7919A}/[H7919]', 'inflected', 'heb', 'שָׂכַל', '["sâkal"]', '["and/ [those who] have insight of","and/ having insight","and/ insight","and/ you will understand","so/ they may have insight"]', '["v"]', 'to be (causatively, make or act) circumspect and hence, intelligent consider, expert, instruct, prosper, (deal) prudent(-ly), (give) skill(-ful), have good success, teach, (have, make to) understand(-ing), wisdom, (be, behave self, consider, make) wise(-ly), guide wittingly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1254A}/H9034\/[H1254]', 'inflected', 'heb', 'בָּרָא', '["bârâʼ"]', '["he has created/ it"]', '["v"]', '(absolutely) to create; (qualified) to cut down (a wood), select, feed (as formative processes) choose, create (creator), cut down, dispatch, do, make (fat).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7379}/H9026/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["case/ your"]', '["n-m"]', 'a contest (personal or legal) adversary, cause, chiding, contend(-tion), controversy, multitude (from the margin), pleading, strife, strive(-ing), suit.', 'or רִב; from 7378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6110}/H9026/[H6099]', 'inflected', 'heb', 'עַצֻּמָה', '["ʻatstsumâh"]', '["arguments/ your"]', '["n-f"]', 'a bulwark, i.e. (figuratively) argument strong.', 'feminine of 6099;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0319}/H9029/[H310]', 'inflected', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["end/ their"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0857}/[H225]', 'inflected', 'heb', 'אָתָה', '["ʼâthâh"]', '["the/ [things] coming","the/ coming [things]"]', '["v"]', 'to arrive (be-, things to) come (upon), bring.', 'or אָתָא; a primitive root (collateral to 225 contraction);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7200L}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["so/ let us see"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6467}/H9026/[H6466]', 'inflected', 'heb', 'פֹּעַל', '["pôʻal"]', '["and/ work/ your"]', '["n-m"]', 'an act or work (concretely) act, deed, do, getting, maker, work.', 'from 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H0659>', 'inflected', 'heb', 'מאפע', '["me./''A.fa''"]', '["[is] from/ something worthless"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5461>', 'opaque', 'heb', 'סָגָן', '["çâgân"]', '["officials"]', '["n-m"]', 'a præfect of a province prince, ruler.', 'from an unused root meaning to superintend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0561}/H9026/[H559]', 'inflected', 'heb', 'אֵמֶר', '["ʼêmer"]', '["words/ your"]', '["n-m"]', 'something said answer, × appointed unto him, saying, speech, word.', 'from 559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6726}/[H6725]', 'inflected', 'heb', 'צִיּוֹן', '["Tsîyôwn"]', '["for/ Zion","to/ Zion"]', '["n-pr-loc"]', 'Tsijon (as a permanent capital), a mountain of Jerusalem Zion.', 'the same (regularly) as 6725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7592}/H9038/[H7592]', 'inflected', 'heb', 'שָׁאַל', '["shâʼal"]', '["and/ I will ask/ them"]', '["v"]', 'to inquire; by implication, to request; by extension, to demand ask (counsel, on), beg, borrow, lay to charge, consult, demand, desire, × earnestly, enquire, greet, obtain leave, lend, pray, request, require, salute, × straitly, × surely, wish.', 'or שָׁאֵל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5262}/H9028\/[H5258]', 'inflected', 'heb', 'נֶסֶךְ', '["neçek"]', '["molten images/ their"]', '["n-m"]', 'a libation; also a cast idol cover, drink offering, molten image.', 'or נֵסֶךְ; from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0972}/H9020/[H977]', 'inflected', 'heb', 'בָּחִיר', '["bâchîyr"]', '["chosen one/ my","chosen ones/ my"]', '["n-m"]', 'select choose, chosen one, elect.', 'from 977;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6594}/[H6593]', 'inflected', 'heb', 'פִּשְׁתָּה', '["pishtâh"]', '["and/ a wick"]', '["n-f"]', 'flax; by implication, a wick flax, tow.', 'feminine of 6593;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3518}/H9034/[H3518]', 'inflected', 'heb', 'כָּבָה', '["kâbâh"]', '["he will extinguish/ it"]', '["v"]', 'to expire or (causatively) to extinguish (fire, light, anger) go (put) out, quench.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0571G}/[H539]', 'inflected', 'heb', 'אֶמֶת', '["ʼemeth"]', '["to/ faithfulness"]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8451}/H9023/[H3384]', 'inflected', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["and/ for/ instruction/ his"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3176H}\/[H3176]', 'inflected', 'heb', 'יָחַל', '["yâchal"]', '["I will wait","they will wait"]', '["v"]', 'to wait; by implication, to be patient, hope (cause to, have, make to) hope, be pained, stay, tarry, trust, wait.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5186}/H9038/[H5186]', 'inflected', 'heb', 'נָטָה', '["nâṭâh"]', '["and/ [who] stretched out/ them"]', '["v"]', 'to stretch or spread out; by implication, to bend away (including moral deflection); used in a great variety of application (as follows) afternoon, apply, bow (down, -ing), carry aside, decline, deliver, extend, go down, be gone, incline, intend, lay, let down, offer, outstretched, overthrown, pervert, pitch, prolong, put away, shew, spread (out), stretch (forth, out), take (aside), turn (aside, away), wrest, cause to yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6631}/H9024/[H3318]', 'inflected', 'heb', 'צֶאֱצָא', '["tseʼĕtsâʼ"]', '["and/ produce<s>/ its"]', '["n-m"]', 'issue, i.e. produce, children that which cometh forth (out), offspring.', 'from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5414G}/H9031/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I may make/ you","and/ I will make/ you"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6491}/[H6491]', 'inflected', 'heb', 'פָּקַח', '["pâqach"]', '["to/ open"]', '["v"]', 'to open (the senses, especially the eyes); figuratively, to be observant open.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8416}/H9020/[H1984]', 'inflected', 'heb', 'תְּהִלָּה', '["tᵉhillâh"]', '["and/ praise/ my"]', '["n-f"]', 'laudation; specifically (concretely) a hymn praise.', 'from 1984;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6456}/[H6458]', 'inflected', 'heb', 'פְּסִיל', '["pᵉçîyl"]', '["to <the>/ images"]', '["n-m"]', 'an idol carved (graven) image, quarry.', 'from 6458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2319H}/[H2318]', 'inflected', 'heb', 'חָדָשׁ', '["châdâsh"]', '["and/ new [things]"]', '["a"]', 'new fresh, new thing.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3427}/H9028/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["and/ inhabitants/ their"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5554}/[H5553]', 'lemma', 'heb', 'סֶלַע', '["Çelaʻ"]', '["Sela"]', '["n-pr-loc"]', 'Sela, the rock-city of Idumaea rock, Sela(-h).', 'the same as 5553;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6681}/[H6681]', 'lemma', 'heb', 'צָוַח', '["tsâvach"]', '["let them cry aloud"]', '["v"]', 'to screech (exultingly) shout.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6873}/[H6873]', 'lemma', 'heb', 'צָרַח', '["tsârach"]', '["[is] shouting out","he will raise a battle-shout"]', '["v"]', 'to be clear (in tone, i.e. shrill), i.e. to whoop cry, roar.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1396}\/[H1396]', 'inflected', 'heb', 'גָּבַר', '["gâbar"]', '["he will prevail"]', '["v"]', 'to be strong; by implication, to prevail, act insolently exceed, confirm, be great, be mighty, prevail, put to more (strength), strengthen, be stronger, be valiant.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0662}/[H662]', 'lemma', 'heb', 'אָפַק', '["ʼâphaq"]', '["I have restrained myself","they have restrained themselves","will you restrain yourself"]', '["v"]', 'to contain, i.e. (reflex.) abstain force (oneself), restrain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6463}/[H6463]', 'lemma', 'heb', 'פָּעָה', '["pâʻâh"]', '["I groan"]', '["v"]', 'to scream cry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5395}/[H5395]', 'lemma', 'heb', 'נָשַׁם', '["nâsham"]', '["I puff"]', '["v"]', 'properly, to blow away, i.e. destroy destroy.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7602A}/[H7602]', 'inflected', 'heb', 'שָׁאַף', '["shâʼaph"]', '["and/ I may pant"]', '["v"]', 'to inhale eagerly; figuratively, to cover; by implication, to be angry; also to hasten desire (earnestly), devour, haste, pant, snuff up, swallow up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6212>/H9028', 'opaque', 'heb', 'עֶשֶׂב', '["ʻeseb"]', '["vegetation/ their"]', '["n-m"]', 'grass (or any tender shoot) grass, herb.', 'from an unused root meaning to glisten (or be green);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0339}/[H183]', 'inflected', 'heb', 'אִי', '["ʼîy"]', '["<into> <the>/ islands","to the/ islands","to/ [the] coastlands"]', '["n-m"]', 'properly, a habitable spot (as desirable); dry land, a coast, an island country, isle, island.', 'from 183;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H5410B>', 'inflected', 'heb', 'בנתיבות', '["bi/n.ti.Vot"]', '["by/ paths"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1869}/H9038/[H1869]', 'inflected', 'heb', 'דָּרַךְ', '["dârak"]', '["I will guide/ them"]', '["v"]', 'to tread; by implication, to walk; also to string a bow (by treading on it in bending) archer, bend, come, draw, go (over), guide, lead (forth), thresh, tread (down), walk.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4625}/[H6140]', 'inflected', 'heb', 'מַעֲקָשׁ', '["maʻăqâsh"]', '["and/ rough places"]', '["n-m"]', 'a crook (in a road) crooked thing.', 'from 6140;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6459}/[H6458]', 'inflected', 'heb', 'פֶּסֶל', '["peçel"]', '["in <the>/ idol"]', '["n-m"]', 'an idol carved (graven) image.', 'from 6458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5787}/[H5786]', 'inflected', 'heb', 'עִוֵּר', '["ʻivvêr"]', '["and/ O/ blind [people]"]', '["a"]', 'blind (literally or figuratively) blind (men, people).', 'intensive from 5786;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2795}/[H2790]', 'inflected', 'heb', 'חֵרֵשׁ', '["chêrêsh"]', '["and/ deaf","and/ deaf [people]"]', '["a"]', 'deaf (whether literally or spiritual) deaf.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H4397G>/H9020', 'inflected', 'heb', 'כמלאכי', '["ke./mal.''a.Kh/i"]', '["like/ messenger/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7999B}/[H7999]', 'inflected', 'heb', 'שָׁלַם', '["shâlam"]', '["like/ [one] in a covenant"]', '["v"]', 'to be safe (in mind, body or estate); figuratively, to be (causatively, make) completed; by implication, to be friendly; by extension, to reciprocate (in various applications) make amends, (make an) end, finish, full, give again, make good, (re-) pay (again), (make) (to) (be at) peace(-able), that is perfect, perform, (make) prosper(-ous), recompense, render, requite, make restitution, restore, reward, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5787}/[H5786]', 'inflected', 'heb', 'עִוֵּר', '["ʻivvêr"]', '["and/ blind"]', '["a"]', 'blind (literally or figuratively) blind (men, people).', 'intensive from 5786;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0142}/[H142]', 'inflected', 'heb', 'אָדַר', '["ʼâdar"]', '["so/ he may make [it] glorious"]', '["v"]', 'to expand, i.e. be great or (figuratively) magnificent (become) glorious, honourable.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8154}/[H8154]', 'inflected', 'heb', 'שָׁסָה', '["shâçâh"]', '["and/ plundered"]', '["v"]', 'to plunder destroyer, rob, spoil(-er).', 'or שָׁשָׂה; (Isaiah 10:13), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6351}/[H6341]', 'lemma', 'heb', 'פָּחַח', '["pâchach"]', '["they are trapped"]', '["v"]', 'to spread a net be snared.', 'a primitive root; to batter out; but used only as denominative from 6341,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2352>', 'inflected', 'heb', 'בחורים', '["ba./chu.Rim"]', '["in <the>/ holes"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4933}/[H8155]', 'lemma', 'heb', 'מְשִׁסָּה', '["mᵉshiççâh"]', '["plunder"]', '["n-f"]', 'plunder booty, spoil.', 'from 8155;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4933}/[H8155]', 'inflected', 'heb', 'מְשִׁסָּה', '["mᵉshiççâh"]', '["<into>/ plunder","<into>/ plunder<s>","to/ plunder"]', '["n-f"]', 'plunder booty, spoil.', 'from 8155;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8451}/H9023/[H3384]', 'inflected', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["in/ laws/ his","to/ law/ his"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3857}/H9033/[H3857]', 'inflected', 'heb', 'לָהַט', '["lâhaṭ"]', '["and/ it set ablaze/ it"]', '["v"]', 'properly, to lick, i.e. (by implication) to blaze burn (up), set on fire, flaming, kindle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3335G}/H9031/[H3334]', 'inflected', 'heb', 'יָצַר', '["yâtsar"]', '["and/ [the one who] formed/ you","and/ [who] formed/ you"]', '["v"]', 'to mould into a form; especially as a potter; figuratively, to determine (i.e. form a resolution) × earthen, fashion, form, frame, make(-r), potter, purpose.', 'probably identical with 3334 (through the squeezing into shape); (compare 3331);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1350A}/H9031/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["I have redeemed/ you"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7857}/H9031/[H7857]', 'inflected', 'heb', 'שָׁטַף', '["shâṭaph"]', '["they will overflow/ you"]', '["v"]', 'to gush; by implication, to inundate, cleanse; by analogy, to gallop, conquer drown, (over-) flow(-whelm, rinse, run, rush, (throughly) wash (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3467}/H9031/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["[am] about to save/ you","deliverer/ your","they will save/ you"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3724A}/H9021/[H3722]', 'inflected', 'heb', 'כֹּפֶר', '["kôpher"]', '["ransom/ your"]', '["n-m"]', 'properly, a cover, i.e. (literally) a village (as covered in); (specifically) bitumen (as used for coating), and the henna plant (as used for dyeing); figuratively, a redemption-price bribe, camphire, pitch, ransom, satisfaction, sum of money, village.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6828G}/[H6845]', 'inflected', 'heb', 'צָפוֹן', '["tsâphôwn"]', '["[were] to the/ north","to the/ north"]', '["n-f"]', 'properly, hidden, i.e. dark; used only of the north as a quarter (gloomy and unknown) north(-ern, side, -ward, wind).', 'or צָפֹן; from 6845;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8486}/[H3225]', 'inflected', 'heb', 'תֵּימָן', '["têymân"]', '["and/ to/ [the] south"]', '["n-f"]', 'the south (as being on the right hand of a person facing the east) south (side, -ward, wind).', 'or תֵּמָן; denominative from 3225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1323G}/H9020/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["and/ daughters/ my"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7121H}/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["<the>/ [one who] is called","those/ [who] are called"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3519}/H9020/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["and/ [whom] for/ glory/ my"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1254A}/H9033/[H1254]', 'inflected', 'heb', 'בָּרָא', '["bârâʼ"]', '["I created/ him"]', '["v"]', '(absolutely) to create; (qualified) to cut down (a wood), select, feed (as formative processes) choose, create (creator), cut down, dispatch, do, make (fat).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3335G}/H9033/[H3334]', 'inflected', 'heb', 'יָצַר', '["yâtsar"]', '["[one who] formed/ it","[the one who] formed/ him","[whom] I formed/ him","he forms/ it"]', '["v"]', 'to mould into a form; especially as a potter; figuratively, to determine (i.e. form a resolution) × earthen, fashion, form, frame, make(-r), potter, purpose.', 'probably identical with 3334 (through the squeezing into shape); (compare 3331);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7223H}/[H7221]', 'inflected', 'heb', 'רִאשׁוֹן', '["riʼshôwn"]', '["and/ former [things]"]', '["a"]', 'first, in place, time or rank (as adjective or noun) ancestor, (that were) before(-time), beginning, eldest, first, fore(-father) (-most), former (thing), of old time, past.', 'or רִאשֹׁן; from 7221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5707}/H9028/[H5749]', 'inflected', 'heb', 'עֵד', '["ʻêd"]', '["witnesses/ their"]', '["n-m"]', 'concretely, a witness; abstractly, testimony; specifically, a recorder, i.e. prince witness.', 'contracted from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6663}/[H6663]', 'inflected', 'heb', 'צָדַק', '["tsâdaq"]', '["and/ [those who] turn to righteousness","so/ they may be justified"]', '["v"]', 'to be (causatively, make) right (in a moral or forensic sense) cleanse, clear self, (be, do) just(-ice, -ify, -ify self), (be turn to) righteous(-ness).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0310A}/H9030/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["and/ after/ me"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1107}/H9030/[H1077]', 'inflected', 'heb', 'בִּלְעֲדֵי', '["bilʻădêy"]', '["<from>/ except/ me"]', '["prt"]', 'except, without, besides beside, not (in), save, without.', 'or בַּלְעֲדֵי; constructive plural from 1077 and 5703, not till, i.e. (as preposition or adverb)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1350A}/H9026/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["redeemer/ your"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6918G}/H9026/[H6942]', 'inflected', 'heb', 'קָדוֹשׁ', '["qâdôwsh"]', '["holy [one]/ your"]', '["a"]', 'sacred (ceremonially or morally); (as noun) God (by eminence), an angel, a saint, a sanctuary holy (One), saint.', 'or קָדֹשׁ; from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4428G}/H9026\/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["king/ your"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5808}/[H5810]', 'inflected', 'heb', 'עִזּוּז', '["ʻizzûwz"]', '["and/ a strong [one]"]', '["a"]', 'forcible; collectively and concretely, an army power, strong.', 'from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6594}/[H6593]', 'inflected', 'heb', 'פִּשְׁתָּה', '["pishtâh"]', '["like <the>/ wick"]', '["n-f"]', 'flax; by implication, a wick flax, tow.', 'feminine of 6593;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6931H}/[H6930]', 'inflected', 'heb', 'קַדְמוֹנִי', '["qadmôwnîy"]', '["and/ ancient [things]"]', '["a"]', '(of time) anterior or (of place) oriental ancient, they that went before, east, (thing of) old.', 'or קַדְמֹנִי; from 6930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8248H}/[H8248]', 'inflected', 'heb', 'שָׁקָה', '["shâqâh"]', '["to/ give drink to"]', '["v"]', 'to quaff, i.e. (causatively) to irrigate or furnish a potion to cause to (give, give to, let, make to) drink, drown, moisten, water. See 7937, 8354.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5608A}\/[H5608]', 'inflected', 'heb', 'סָפַר', '["çâphar"]', '["they will recount"]', '["v n-m"]', 'properly, to score with a mark as a tally or record, i.e. (by implication) to inscribe, and also to enumerate; intensively, to recount, i.e. celebrate commune, (ac-) count; declare, number, penknife, reckon, scribe, shew forth, speak, talk, tell (out), writer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2077}/H9021/[H2076]', 'inflected', 'heb', 'זֶבַח', '["zebach"]', '["and/ sacrifices/ your"]', '["n-m"]', 'properly, a slaughter, i.e. the flesh of an animal; by implication, a sacrifice (the victim or the act) offer(-ing), sacrifice.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5647J}/H9031/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["I have burdened/ you"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H4503G>', 'inflected', 'heb', 'במנחה', '["be./min.Chah"]', '["with/ offering[s]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3021}/H9031/[H3021]', 'inflected', 'heb', 'יָגַע', '["yâgaʻ"]', '["I have made weary/ you"]', '["v"]', 'properly, to gasp; hence, to be exhausted, to tire, to toil faint, (make to) labour, (be) weary.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3828}/[H3836]', 'inflected', 'heb', 'לְבוֹנָה', '["lᵉbôwnâh"]', '["with/ frankincense"]', '["n-f"]', 'frankincense (from its whiteness or perhaps that of its smoke) (frank-) incense.', 'or לְבֹנָה; from 3836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7301}/H9030/[H7301]', 'inflected', 'heb', 'רָוָה', '["râvâh"]', '["he has made drink/ me","you have satisfied/ me"]', '["v"]', 'to slake the thirst (occasionally of other appetites) bathe, make drunk, (take the) fill, satiate, (abundantly) satisfy, soak, water (abundantly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5647J}/H9030/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["you have burdened/ me"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2403B}/H9021/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["with/ sins/ your"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3021}/H9030/[H3021]', 'inflected', 'heb', 'יָגַע', '["yâgaʻ"]', '["you have made weary/ me"]', '["v"]', 'properly, to gasp; hence, to be exhausted, to tire, to toil faint, (make to) labour, (be) weary.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5771G}/H9021\/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["with/ iniquities/ your"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3887}/H9031/[H3887]', 'inflected', 'heb', 'לוּץ', '["lûwts"]', '["and/ spokesmen/ your"]', '["v"]', 'properly, to make mouths at, i.e. to scoff; hence (from the effort to pronounce a foreign language) to interpret, or (generally) intercede ambassador, have in derision, interpreter, make a mock, mocker, scorn(-er, -ful), teacher.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1421}\/[H1422]', 'inflected', 'heb', 'גִּדּוּף', '["giddûwph"]', '["to/ reviling words"]', '["n-m"]', 'vilification reproach, reviling.', 'or (shortened) גִּדֻּף; and (feminine) גִּדּוּפָהxlit giddûphâh corrected to giddûwphâh; or גִּדֻּפָה; from 1422;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3484}/[H3474]', 'inflected', 'heb', 'יְשֻׁרוּן', '["Yᵉshurûwn"]', '["and/ Jeshurun"]', '["n-pr-m"]', 'Jeshurun, a symbolic name for Israel Jeshurun.', 'from 3474; upright;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3004}/[H3001]', 'lemma', 'heb', 'יַבָּשָׁה', '["yabbâshâh"]', '["dry ground"]', '["n-f"]', 'dry ground dry (ground, land).', 'from 3001;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1293}/H9020/[H1288]', 'inflected', 'heb', 'בְּרָכָה', '["Bᵉrâkâh"]', '["and/ blessing/ my"]', '["n-f"]', 'benediction; by implication prosperity blessing, liberal, pool, present.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6631}/H9021/[H3318]', 'inflected', 'heb', 'צֶאֱצָא', '["tseʼĕtsâʼ"]', '["descendants/ your"]', '["n-m"]', 'issue, i.e. produce, children that which cometh forth (out), offspring.', 'from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0996H}/[H995]', 'inflected', 'heb', 'בֵּין', '["bêyn"]', '["in/ between"]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6155H}/[H6148]', 'inflected', 'heb', 'עָרָב', '["ʻârâb"]', '["like/ poplars"]', '["n-f"]', 'a willow (from the use of osiers as wattles) willow.', 'from 6148;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3655}\/[H3655]', 'inflected', 'heb', 'כָּנָה', '["kânâh"]', '["he will name"]', '["v"]', 'to address by an additional name; hence, to eulogize give flattering titles, surname (himself).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1350A}/H9023/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["and/ redeemer/ its"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1107}/H9030/[H1077]', 'inflected', 'heb', 'בִּלְעֲדֵי', '["bilʻădêy"]', '["and/ <from>/ except/ me"]', '["prt"]', 'except, without, besides beside, not (in), save, without.', 'or בַּלְעֲדֵי; constructive plural from 1077 and 5703, not till, i.e. (as preposition or adverb)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5046}/H9034/[H5046]', 'inflected', 'heb', 'נָגַד', '["nâgad"]', '["and/ let him declare/ it","so/ he may declare/ it"]', '["v"]', 'properly, to front, i.e. stand boldly out opposite; by implication (causatively), to manifest; figuratively, to announce (always by word of mouth to one present); specifically, to expose, predict, explain, praise bewray, × certainly, certify, declare(-ing), denounce, expound, × fully, messenger, plainly, profess, rehearse, report, shew (forth), speak, × surely, tell, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6186A}/H9034/[H6186]', 'inflected', 'heb', 'עָרַךְ', '["ʻârak"]', '["and/ let him recount in order/ it"]', '["v"]', 'to set in a row, i.e. arrange, put in order (in a very wide variety of applications) put (set) (the battle, self) in array, compare, direct, equal, esteem, estimate, expert (in war), furnish, handle, join (battle), ordain, (lay, put, reckon up, set) (in) order, prepare, tax, value.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7760L}/H9040/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["from/ when established/ I"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0857}/[H225]', 'inflected', 'heb', 'אָתָה', '["ʼâthâh"]', '["and/ [the] coming [things]"]', '["v"]', 'to arrive (be-, things to) come (upon), bring.', 'or אָתָא; a primitive root (collateral to 225 contraction);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7297}/[H7297]', 'lemma', 'heb', 'רָהָה', '["râhâh"]', '["you fear"]', '["v"]', 'to fear be afraid.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8085I}/H9031/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["I proclaimed to/ you","I will proclaim to/ you","did I proclaim to/ you"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2530A}/H9028/[H2530]', 'inflected', 'heb', 'חָמַד', '["châmad"]', '["and/ desired [things]/ their"]', '["v"]', 'to delight in beauty, greatly beloved, covet, delectable thing, (× great) delight, desire, goodly, lust, (be) pleasant (thing), precious (thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5707}/H9028/[H5749]', 'inflected', 'heb', 'עֵד', '["ʻêd"]', '["and/ witnesses/ their"]', '["n-m"]', 'concretely, a witness; abstractly, testimony; specifically, a recorder, i.e. prince witness.', 'contracted from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4621>', 'opaque', 'heb', 'מַעֲצָד', '["maʻătsâd"]', '["a tool"]', '["n-m"]', 'an axe ax, tongs.', 'from an unused root meaning to hew;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6466}/[H6466]', 'inflected', 'heb', 'פָּעַל', '["pâʻal"]', '["and/ he works [it]"]', '["v"]', 'to do or make (systematically and habitually), especially to practise commit, (evil-) do(-er), make(-r), ordain, work(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6352>', 'inflected', 'heb', 'בפחם', '["ba./pe.Cham"]', '["on the/ coal[s]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4717}/[H5344]', 'inflected', 'heb', 'מַקָּבָה', '["maqqâbâh"]', '["and/ with <the>/ hammers","and/ with/ hammers"]', '["n-f"]', 'properly, a perforatrix, i.e. a hammer (as piercing) hammer.', 'from 5344;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6466}/H9033/[H6466]', 'inflected', 'heb', 'פָּעַל', '["pâʻal"]', '["and/ he worked/ it"]', '["v"]', 'to do or make (systematically and habitually), especially to practise commit, (evil-) do(-er), make(-r), ordain, work(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3286}/[H3286]', 'inflected', 'heb', 'יָעַף', '["yâʻaph"]', '["and/ he grew weary","and/ they will grow weary"]', '["v"]', 'to tire (as if from wearisome flight) faint, cause to fly, (be) weary (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8388B}/H9033/[H8388]', 'inflected', 'heb', 'תָּאַר', '["tâʼar"]', '["he outlines/ it"]', '["v"]', 'to delineate; reflex. to extend be drawn, mark out, (Rimmon-) methoar (by union with 7417).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8279}/[H8277]', 'inflected', 'heb', 'שֶׂרֶד', '["sered"]', '["with <the>/ marker"]', '["n-m"]', 'a (carpenter''s) scribing-awl (for pricking or scratching measurements) line.', 'from 8277;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4741}/[H7106]', 'inflected', 'heb', 'מַקְצֻעָה', '["maqtsuʻâh"]', '["with <the>/ scraping tools"]', '["n-f"]', 'a scraper, i.e. a carving chisel plane.', 'from 7106;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4230}/[H2328]', 'inflected', 'heb', 'מְחוּגָה', '["mᵉchûwgâh"]', '["and/ with <the>/ compass"]', '["n-f"]', 'an instrument for marking a circle, i.e. compasses compass.', 'from 2328;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8403}/[H1129]', 'inflected', 'heb', 'תַּבְנִית', '["tabnîyth"]', '["like/ [the] form of"]', '["n-f"]', 'structure; by implication, a model, resemblance figure, form, likeness, pattern, similitude.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8597}/[H6286]', 'inflected', 'heb', 'תִּפְאָרָה', '["tiphʼârâh"]', '["like/ [the] beauty of"]', '["n-f"]', 'ornament (abstractly or concretely, literally or figuratively) beauty(-iful), bravery, comely, fair, glory(-ious), honour, majesty.', 'or תִּפְאֶרֶת; from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8645}/[H7329]', 'lemma', 'heb', 'תִּרְזָה', '["tirzâh"]', '["a cypress"]', '["n-f"]', 'a species of tree (apparently from its slenderness), perhaps the cypress cypress.', 'probably from 7329;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0437}/[H436]', 'inflected', 'heb', 'אַלּוֹן', '["ʼallôwn"]', '["and/ an oak"]', '["n-m"]', 'oak.', 'a variation of 436');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0766}/[H765]', 'lemma', 'heb', 'אֹרֶן', '["ʼôren"]', '["laurel"]', '["n-m"]', 'the ash tree (from its toughness) ash.', 'from the same as 765 (in the sense of strength);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5456}/[H5456]', 'inflected', 'heb', 'סָגַד', '["çâgad"]', '["and/ he prostrated himself"]', '["v"]', 'to prostrate oneself (in homage) fall down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6740}/[H6740]', 'lemma', 'heb', 'צָלָה', '["tsâlâh"]', '["I roasted","he roasts"]', '["v"]', 'to roast roast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7611}/H9023/[H7604]', 'inflected', 'heb', 'שְׁאֵרִית', '["shᵉʼêrîyth"]', '["and/ [the] remainder of/ it"]', '["n-f"]', 'a remainder or residual (surviving, final) portion that had escaped, be left, posterity, remain(-der), remnant, residue, rest.', 'from 7604;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6459}/H9023/[H6458]', 'inflected', 'heb', 'פֶּסֶל', '["peçel"]', '["<into>/ idol/ his"]', '["n-m"]', 'an idol carved (graven) image.', 'from 6458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5456}/[H5456]', 'lemma', 'heb', 'סָגַד', '["çâgad"]', '["he prostrates himself","they prostrate themselves","will I prostrate myself?"]', '["v"]', 'to prostrate oneself (in homage) fall down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5456}/[H5456]', 'inflected', 'heb', 'סָגַד', '["çâgad"]', '["to/ it"]', '["v"]', 'to prostrate oneself (in homage) fall down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0410K}/H9020/[H352]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["[are] god/ my"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2902B}/[H2902]', 'lemma', 'heb', 'טוּחַ', '["ṭûwach"]', '["it is besmeared"]', '["v"]', 'to smear, especially with lime daub, overlay, plaister, smut.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7919A}/[H7919]', 'inflected', 'heb', 'שָׂכַל', '["sâkal"]', '["from/ having insight"]', '["v"]', 'to be (causatively, make or act) circumspect and hence, intelligent consider, expert, instruct, prosper, (deal) prudent(-ly), (give) skill(-ful), have good success, teach, (have, make to) understand(-ing), wisdom, (be, behave self, consider, make) wise(-ly), guide wittingly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725N}/[H7725]', 'lemma', 'heb', 'שׁוּב', '["shûwb"]', '["I bring back","bring [it] back","he brings"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1513>/H9023', 'opaque', 'heb', 'גֶּחֶל', '["gechel"]', '["coals/ its"]', '["n-f"]', 'an ember (burning) coal.', 'or (feminine) גַּחֶלֶת; from an unused root meaning to glow or kindle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3499A}/H9023/[H3498]', 'inflected', 'heb', 'יֶתֶר', '["yether"]', '["and/ [the] remainder of/ it"]', '["n-m"]', 'properly, an overhanging, i.e. (by implication) an excess, superiority, remainder; also a small rope (as hanging free) abundant, cord, exceeding, excellancy(-ent), what they leave, that hath left, plentifully, remnant, residue, rest, string, with.', 'from 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8441}/[H8581]', 'inflected', 'heb', 'תּוֹעֵבַה', '["tôwʻêbah"]', '["<into>/ an abomination","into/ an abomination"]', '["n-f"]', 'properly, something disgusting (morally), i.e. (as noun) an abhorrence; especially idolatry or (concretely) an idol abominable (custom, thing), abomination.', 'or תֹּעֵבַה; feminine active participle of 8581;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0944}/[H2981]', 'inflected', 'heb', 'בּוּל', '["bûwl"]', '["to/ a product of"]', '["n-m"]', 'produce (of the earth, etc.) food, stock.', 'for 2981;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3225G}/H9020\/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["in/ right [hand]/ my"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3335G}/H9031/[H3334]', 'inflected', 'heb', 'יָצַר', '["yâtsar"]', '["I formed/ you"]', '["v"]', 'to mould into a form; especially as a potter; figuratively, to determine (i.e. form a resolution) × earthen, fashion, form, frame, make(-r), potter, purpose.', 'probably identical with 3334 (through the squeezing into shape); (compare 3331);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H6051}/[H6049]', 'inflected', 'heb', 'עָנָן', '["ʻânân"]', '["and/ like <the>/ cloud"]', '["n-m"]', 'a cloud (as covering the sky), i.e. the nimbus or thunder-cloud cloud(-y).', 'from 6049;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6286A}\/[H6288]', 'inflected', 'heb', 'פָּאַר', '["pâʼar"]', '["he will get glory for himself"]', '["v"]', 'to gleam, i.e. (causatively) embellish; figuratively, to boast; also to explain (i.e. make clear) oneself; to shake a tree beautify, boast self, go over the boughs, glorify (self), glory, vaunt self.', 'a primitive root; also denominative from 6288,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1350A}/H9021/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["redeemer/ your"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0907}/[H908]', 'lemma', 'heb', 'בַּד', '["bad"]', '["empty talkers"]', '["n-m"]', 'a brag or lie; also a liar liar, lie.', 'from 908;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1847}/H9028/[H3045]', 'inflected', 'heb', 'דַּעַת', '["daʻath"]', '["and/ knowledge/ their"]', '["n"]', 'knowledge cunning, (ig-) norantly, know(-ledge), (un-) awares (wittingly).', 'from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5892B}/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["and/ of/ [the] cities of","and/ to the/ cities"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2723}/H9024/[H2721]', 'inflected', 'heb', 'חׇרְבָּה', '["chorbâh"]', '["and/ ruins/ its"]', '["n-f"]', 'properly, drought, i.e. (by implication) a desolation decayed place, desolate (place, -tion), destruction, (laid) waste (place).', 'feminine of 2721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H6683>', 'inflected', 'heb', 'לצולה', '["la./tzu.Lah"]', '["to the/ ocean-deep"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5104H}/H9022/[H5102]', 'inflected', 'heb', 'נָהָר', '["nâhâr"]', '["and/ rivers/ your"]', '["n-m"]', 'a stream (including the sea; expectation the Nile, Euphrates, etc.); figuratively, prosperity flood, river.', 'from 5102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3245}\/[H3245]', 'inflected', 'heb', 'יָסַד', '["yâçad"]', '["let it be refounded"]', '["v"]', 'to set (literally or figuratively); intensively, to found; reflexively, to sit down together, i.e. settle, consult appoint, take counsel, establish, (lay the, lay for a) found(-ation), instruct, lay, ordain, set, × sure.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7286}/[H7286]', 'inflected', 'heb', 'רָדַד', '["râdad"]', '["to/ subdue"]', '["v"]', 'to tread in pieces, i.e. (figuratively) to conquer, or (specifically) to overlay spend, spread, subdue.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4975>', 'inflected', 'heb', 'ומתני', '["u./ma.te.Nei"]', '["and/ [the] loins of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1921}/[H1921]', 'inflected', 'heb', 'הָדַר', '["hâdar"]', '["and/ [the] mountainous land<s>"]', '["v"]', 'to swell up (literally or figuratively, active or passive); by implication, to favor or honour, be high or proud countenance, crooked place, glorious, honour, put forth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4301}/[H2934]', 'inflected', 'heb', 'מַטְמוֹן', '["maṭmôwn"]', '["and/ hidden treasures of"]', '["n-m"]', 'a secret storehouse; hence, a secreted valuable (buried); generally money hidden riches, (hid) treasure(-s).', 'or מַטְמֹן; or מַטְמֻן; from 2934;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4565}/[H5641]', 'lemma', 'heb', 'מִסְתָּר', '["miçtâr"]', '["secret places"]', '["n-m"]', 'properly, a concealer, i.e. a covert secret(-ly, place).', 'from 5641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3655}/H9031/[H3655]', 'inflected', 'heb', 'כָּנָה', '["kânâh"]', '["I will give a title/ you"]', '["v"]', 'to address by an additional name; hence, to eulogize give flattering titles, surname (himself).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2108}/H9030/[H2107]', 'inflected', 'heb', 'זוּלָה', '["zûwlâh"]', '["besides/ me"]', '["n-f"]', 'probably scattering, i.e. removal; used adverbially, except beside, but, only, save.', 'from 2107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0247}/H9031/[H247]', 'inflected', 'heb', 'אָזַר', '["ʼâzar"]', '["I will gird/ you"]', '["v"]', 'to belt bind (compass) about, gird (up, with).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4628}/H9024/[H6150]', 'inflected', 'heb', 'מַעֲרָב', '["maʻărâb"]', '["and/ from/ setting place/ its"]', '["n-m"]', 'the west (as a region of the evening sun) west.', 'or (feminine) מַעֲרָבָה; from 6150, in the sense of shading;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6509}/[H6509]', 'inflected', 'heb', 'פָּרָה', '["pârâh"]', '["so/ they may bear fruit"]', '["v"]', 'to bear fruit (literally or figuratively) bear, bring forth (fruit), (be, cause to be, make) fruitful, grow, increase.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1254A}/H9033\/[H1254]', 'inflected', 'heb', 'בָּרָא', '["bârâʼ"]', '["I have created/ it"]', '["v"]', '(absolutely) to create; (qualified) to cut down (a wood), select, feed (as formative processes) choose, create (creator), cut down, dispatch, do, make (fat).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6467}/H9021/[H6466]', 'inflected', 'heb', 'פֹּעַל', '["pôʻal"]', '["and/ work/ your"]', '["n-m"]', 'an act or work (concretely) act, deed, do, getting, maker, work.', 'from 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2342I}/H9013\/[H2342]', 'inflected', 'heb', 'חוּל', '["chûwl"]', '["are you in labor with/ !"]', '["v"]', 'properly, to twist or whirl (in a circular or spiral manner), i.e. (specifically) to dance, to writhe in pain (especially of parturition) or fear; figuratively, to wait, to pervert bear, (make to) bring forth, (make to) calve, dance, drive away, fall grievously (with pain), fear, form, great, grieve, (be) grievous, hope, look, make, be in pain, be much (sore) pained, rest, shake, shapen, (be) sorrow(-ful), stay, tarry, travail (with pain), tremble, trust, wait carefully (patiently), be wounded.', 'or חִיל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5892B}/H9020/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["cities/ my","city/ my"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1546}/H9020/[H1540]', 'inflected', 'heb', 'גָּלוּת', '["gâlûwth"]', '["and/ exile[s]/ my"]', '["n-f"]', 'captivity; concretely, exiles (collectively) (they that are carried away) captives(-ity).', 'feminine from 1540;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5504}/[H5503]', 'inflected', 'heb', 'סַחַר', '["çachar"]', '["and/ [the] traffic of"]', '["n-m"]', 'profit (from trade) merchandise.', 'from 5503;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5436}/[H5434]', 'inflected', 'heb', 'סְבָאִי', '["Çᵉbâʼîy"]', '["and/ [the] Sabeans"]', '["n"]', 'a Sebaite, or inhabitant of Seba Sabean.', 'patrial from 5434;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0413}/H9032/[H413]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["and/ to/ you"]', '["prep"]', 'near, with or among; often in general, to about, according to, after, against, among, as for, at, because(-fore, -side), both...and, by, concerning, for, from, × hath, in(-to), near, (out) of, over, through, to(-ward), under, unto, upon, whether, with(-in).', '(but only used in the shortened constructive form אֶל ); a primitive particle; properly, denoting motion towards, but occasionally used of a quiescent position, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3639}/[H3637]', 'inflected', 'heb', 'כְּלִמָּה', '["kᵉlimmâh"]', '["in <the>/ ignominy"]', '["n-f"]', 'disgrace confusion, dishonour, reproach, shame.', 'from 3637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6736}/[H6735]', 'lemma', 'heb', 'צִיר', '["tsîyr"]', '["images"]', '["n-m"]', 'a form (of beauty; as if pressed out, i.e. carved); hence, an (idolatrous) image beauty, idol.', 'the same as 6735;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5703}\/[H5710]', 'inflected', 'heb', 'עַד', '["ʻad"]', '["perpetuity"]', '["n-m"]', 'properly, a (peremptory) terminus, i.e. (by implication) duration, in the sense of advance or perpetuity (substantially as a noun, either with or without a preposition) eternity, ever(-lasting, -more), old, perpetually, world without end.', 'from 5710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6213H}/H9034/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["and/ [who] made/ it"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1254A}/H9034/[H1254]', 'inflected', 'heb', 'בָּרָא', '["bârâʼ"]', '["he created/ it"]', '["v"]', '(absolutely) to create; (qualified) to cut down (a wood), select, feed (as formative processes) choose, create (creator), cut down, dispatch, do, make (fat).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3335G}/H9034/[H3334]', 'inflected', 'heb', 'יָצַר', '["yâtsar"]', '["he formed/ it"]', '["v"]', 'to mould into a form; especially as a potter; figuratively, to determine (i.e. form a resolution) × earthen, fashion, form, frame, make(-r), potter, purpose.', 'probably identical with 3334 (through the squeezing into shape); (compare 3331);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1245}/H9030/[H1245]', 'inflected', 'heb', 'בָּקַשׁ', '["bâqash"]', '["seek/ me","they had sought/ me"]', '["v"]', 'to search out (by any method, specifically in worship or prayer); by implication, to strive after ask, beg, beseech, desire, enquire, get, make inquisition, procure, (make) request, require, seek (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6459}/H9028/[H6458]', 'inflected', 'heb', 'פֶּסֶל', '["peçel"]', '["idol/ their"]', '["n-m"]', 'an idol carved (graven) image.', 'from 6458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5066H}/[H5066]', 'inflected', 'heb', 'נָגַשׁ', '["nâgash"]', '["and/ [one who] brings near","and/ bring near"]', '["v"]', 'to be or come (causatively, bring) near (for any purpose); euphemistically, to lie with a woman; as an enemy, to attack; religious to worship; causatively, to present; figuratively, to adduce an argument; by reversal, to stand back (make to) approach (nigh), bring (forth, hither, near), (cause to) come (hither, near, nigh), give place, go hard (up), (be, draw, go) near (nigh), offer, overtake, present, put, stand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5046}/H9034/[H5046]', 'inflected', 'heb', 'נָגַד', '["nâgad"]', '["did he declare?/ it"]', '["v"]', 'properly, to front, i.e. stand boldly out opposite; by implication (causatively), to manifest; figuratively, to announce (always by word of mouth to one present); specifically, to expose, predict, explain, praise bewray, × certainly, certify, declare(-ing), denounce, expound, × fully, messenger, plainly, profess, rehearse, report, shew (forth), speak, × surely, tell, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5704}/H9033/[H5703]', 'inflected', 'heb', 'עַד', '["ʻad"]', '["to/ him"]', '["prep"]', 'as far (or long, or much) as, whether of space (even unto) or time (during, while, until) or degree (equally with) against, and, as, at, before, by (that), even (to), for(-asmuch as), (hither-) to, how long, into, as long (much) as, (so) that, till, toward, until, when, while, ( as) yet.', 'properly, the same as 5703 (used as a preposition, adverb or conjunction; especially with a preposition);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1078}/[H1168]', 'lemma', 'heb', 'בֵּל', '["Bêl"]', '["Bel"]', '["n-pr-m"]', 'Bel, the Baal of the Babylonians Bel.', 'by contraction for 1168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7164}/[H7165]', 'lemma', 'heb', 'קָרַס', '["qâraç"]', '["[is] stooping low","they have stooped low"]', '["v"]', 'to hunch, i.e. be hump-backed stoop.', 'a primitive root; properly, to protrude; used only as denominative from 7165 (for alliteration with 7167),');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5015B}/[H5015]', 'lemma', 'heb', 'נְבוֹ', '["Nᵉbôw"]', '["Nebo"]', '["n-pr-m n-pr-loc"]', 'Nebo, the name of a Babylonian deity, also of a mountain in Moab, and of a place in Palestine Nebo.', 'probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5385}/H9026/[H5375]', 'inflected', 'heb', 'נְשׂוּאָה', '["nᵉsûwʼâh"]', '["burdens/ your"]', '["n-f"]', 'something borne, i.e. a load carriage.', 'or rather, נְשֻׂאָה; feminine. passive participle of 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5315I}/H9028/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["and/ self/ their"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6006}/[H6006]', 'inflected', 'heb', 'עָמַס', '["ʻâmaç"]', '["who/ have been carried"]', '["v"]', 'to load, i.e. impose a burden (or figuratively, infliction) be borne, (heavy) burden (self), lade, load, put.', 'or עָמַשׂ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4422}\/[H4422]', 'inflected', 'heb', 'מָלַט', '["mâlaṭ"]', '["and/ I may rescue"]', '["v"]', 'properly, to be smooth, i.e. (by implication) to escape (as if by slipperiness); causatively, to release or rescue; specifically, to bring forth young, emit sparks deliver (self), escape, lay, leap out, let alone, let go, preserve, save, × speedily, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4911A}/H9030/[H4912]', 'inflected', 'heb', 'מָשַׁל', '["mâshal"]', '["and/ will you compare?/ me"]', '["v"]', 'to liken, i.e. (transitively) to use figurative language (an allegory, adage, song or the like); intransitively, to resemble be(-come) like, compare, use (as a) proverb, speak (in proverbs), utter.', 'denominative from 4912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2107}/[H2151]', 'inflected', 'heb', 'זוּל', '["zûwl"]', '["those/ [who] pour out"]', '["v"]', 'probably to shake out, i.e. (by implication) to scatter profusely; figuratively, to treat lightly lavish, despise.', 'a primitive root (compare 2151);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3599}/[H3563]', 'inflected', 'heb', 'כִּיס', '["kîyç"]', '["from/ a bag"]', '["n-m"]', 'a cup; also a bag for money or weights bag, cup, purse.', 'a form for 3563;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7070K}/[H7069]', 'inflected', 'heb', 'קָנֶה', '["qâneh"]', '["on <the>/ scale[s]"]', '["n-m"]', 'a reed (as erect); by resemblance a rod (especially for measuring), shaft, tube, stem, the radius (of the arm), beam (of a steelyard) balance, bone, branch, calamus, cane, reed, × spearman, stalk.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6213H}/H9033/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["and/ he makes/ it"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375G}/H9033/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["they lift up/ it"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5445}/H9033/[H5445]', 'inflected', 'heb', 'סָבַל', '["çâbal"]', '["they carry/ it"]', '["v"]', 'to carry (literally or figuratively), or (reflexively) be burdensome; specifically, to be gravid bear, be a burden, carry, strong to labour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5117}/H9033/[H5117]', 'inflected', 'heb', 'נוּחַ', '["nûwach"]', '["and/ they set down/ it"]', '["v"]', 'to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6869B}/H9023/[H6862]', 'inflected', 'heb', 'צָרָה', '["tsârâh"]', '["from/ trouble/ his"]', '["n-f"]', 'tightness (i.e. figuratively, trouble); transitively, a female rival adversary, adversity, affliction, anguish, distress, tribulation, trouble.', 'feminine of 6862;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3467}/H9033\/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["it delivers/ him"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0377}/[H376]', 'inflected', 'heb', 'אִישׁ', '["ʼîysh"]', '["and/ pluck up courage"]', '["v"]', 'to be a man, i.e. act in a manly way show (one) self a man.', 'denominative from 376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6924H}/[H6923]', 'inflected', 'heb', 'קֶדֶם', '["qedem"]', '["and/ from/ antiquity"]', '["n-m adv"]', 'the front, of place (absolutely, the fore part, relatively the East) or time (antiquity); often used adverbially (before, anciently, eastward) aforetime, ancient (time), before, east (end, part, side, -ward), eternal, × ever(-lasting), forward, old, past. Compare 6926.', 'or קֵדְמָה; from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213A}/H9034\/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["I will accomplish/ it"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6666}/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["from/ righteousness"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8668G}/H9020/[H7768]', 'inflected', 'heb', 'תְּשׁוּעָה', '["tᵉshûwʻâh"]', '["and/ salvation/ my"]', '["n-f"]', 'rescue (literal or figurative, persons, national or spiritual) deliverance, help, safety, salvation, victory.', 'or תְּשֻׁעָה; from 7768 in the sense of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8597}/H9020\/[H6286]', 'inflected', 'heb', 'תִּפְאָרָה', '["tiphʼârâh"]', '["splendor/ my"]', '["n-f"]', 'ornament (abstractly or concretely, literally or figuratively) beauty(-iful), bravery, comely, fair, glory(-ious), honour, majesty.', 'or תִּפְאֶרֶת; from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6028}/[H6026]', 'inflected', 'heb', 'עָנֹג', '["ʻânôg"]', '["and/ delicate"]', '["a"]', 'luxurious delicate.', 'from 6026;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2912}/[H2912]', 'inflected', 'heb', 'טָחַן', '["ṭâchan"]', '["and/ grind"]', '["v"]', 'to grind meal; hence, to be a concubine (that being their employment) grind(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6777>/H9022', 'opaque', 'heb', 'צַמָּה', '["tsammâh"]', '["veil/ your"]', '["n-f"]', 'a veil locks.', 'from an unused root meaning to fasten on;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2834}/[H2834]', 'lemma', 'heb', 'חָשַׂף', '["châsaph"]', '["I will strip bare","I will strip off","[will be ] bared","he has bared","strip off"]', '["v"]', 'to strip off, i.e. generally to make naked (for exertion or in disgrace), to drain away or bail up (a liquid) make bare, clean, discover, draw out, take, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7640>', 'opaque', 'heb', 'שֹׁבֶל', '["shôbel"]', '["a skirt"]', '["n-m"]', 'a lady''s train (as trailing after her) leg.', 'from an unused root meaning to flow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6172}/H9022/[H6168]', 'inflected', 'heb', 'עֶרְוָה', '["ʻervâh"]', '["nakedness/ your"]', '["n-f"]', 'nudity, literally (especially the pudenda) or figuratively (disgrace, blemish) nakedness, shame, unclean(-ness).', 'from 6168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2781}/H9022/[H2778]', 'inflected', 'heb', 'חֶרְפָּה', '["cherpâh"]', '["reproach/ your"]', '["n-f"]', 'contumely, disgrace, the pudenda rebuke, reproach(-fully), shame.', 'from 2778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1350A}/H9025/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["[is] redeemer/ our","redeemer/ our"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1748}/[H1826]', 'lemma', 'heb', 'דּוּמָם', '["dûwmâm"]', '["silence","silently"]', '["n-m"]', 'still; adverbially, silently dumb, silent, quietly wait.', 'from 1826;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1404}/[H1376]', 'lemma', 'heb', 'גְּבֶרֶת', '["gᵉbereth"]', '["a queen","queen of"]', '["n-f"]', 'mistress lady, mistress.', 'feminine of 1376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5923}/H9022/[H5953]', 'inflected', 'heb', 'עֹל', '["ʻôl"]', '["yoke/ your"]', '["n-m"]', 'a yoke (as imposed on the neck), literally or figuratively yoke.', 'or עוֹל; from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0319}/H9024\/[H310]', 'inflected', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["outcome/ its"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5719}/[H5727]', 'lemma', 'heb', 'עָדִין', '["ʻâdîyn"]', '["O voluptuous [woman]"]', '["a"]', 'voluptuous given to pleasures.', 'from 5727;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3824}/H9024/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["in/ heart/ her","in/ heart/ its"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0657A}/H9040/[H656]', 'inflected', 'heb', 'אֶפֶס', '["ʼepheç"]', '["and/ only/ I"]', '["n-m"]', 'cessation, i.e. an end (especially of the earth); often used adverb, no further; also the ankle (in the dual), as being the extremity of the leg or foot ankle, but (only), end, howbeit, less than nothing, nevertheless (where), no, none (beside), not (any, -withstanding), thing of nought, save(-ing), there, uttermost part, want, without (cause).', 'from 656; (sometimes like 6466)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0489}/[H481]', 'inflected', 'heb', 'אַלְמֹן', '["ʼalmôn"]', '["and/ widowhood"]', '["n-m"]', 'bereavement widowhood.', 'from 481 as in 488;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8537}/H9028/[H8552]', 'inflected', 'heb', 'תֹּם', '["tôm"]', '["according to/ completeness/ their"]', '["n-m"]', 'completeness; figuratively, prosperity; usually (morally) innocence full, integrity, perfect(-ion), simplicity, upright(-ly, -ness), at a venture. See 8550.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3785}/H9022/[H3784]', 'inflected', 'heb', 'כֶּשֶׁף', '["kesheph"]', '["sorceries/ your"]', '["n-m"]', 'magic sorcery, witchcraft.', 'from 3784;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6109}/[H6108]', 'inflected', 'heb', 'עׇצְמָה', '["ʻotsmâh"]', '["in/ [the] power of"]', '["n-f"]', 'powerfulness; by extension, numerousness abundance, strength.', 'feminine of 6108;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2267}/H9022/[H2266]', 'inflected', 'heb', 'חֶבֶר', '["cheber"]', '["spells/ your"]', '["n-m"]', 'a society; also a spell charmer(-ing), company, enchantment, × wide.', 'from 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7451I}/H9022/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["in/ evil/ your"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2451}/H9022/[H2449]', 'inflected', 'heb', 'חׇכְמָה', '["chokmâh"]', '["wisdom/ your"]', '["n-f"]', 'wisdom (in a good sense) skilful, wisdom, wisely, wit.', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1847}/H9022/[H3045]', 'inflected', 'heb', 'דַּעַת', '["daʻath"]', '["and/ knowledge/ your"]', '["n"]', 'knowledge cunning, (ig-) norantly, know(-ledge), (un-) awares (wittingly).', 'from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725I}/H9032/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["it has led away/ you"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3820A}/H9022/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["in/ heart/ your"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7837}/H9024/[H7836]', 'inflected', 'heb', 'שַׁחַר', '["shachar"]', '["to charm away/ it"]', '["n-m"]', 'dawn (literal, figurative or adverbial) day(-spring), early, light, morning, whence riseth.', 'from 7836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1943}/[H1942]', 'lemma', 'heb', 'הֹוָה', '["hôvâh"]', '["disaster"]', '["n-f"]', 'ruin mischief.', 'another form for 1942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2267}/H9022/[H2266]', 'inflected', 'heb', 'חֶבֶר', '["cheber"]', '["in/ spells/ your"]', '["n-m"]', 'a society; also a spell charmer(-ing), company, enchantment, × wide.', 'from 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5271A}/H9022/[H5288]', 'inflected', 'heb', 'נָעוּר', '["nâʻûwr"]', '["since/ youth<s>/ your"]', '["n-m n-f"]', '(only in plural collective or emphatic form) youth, the state (juvenility) or the persons (young people) childhood, youth.', 'or נָעֻר; and (feminine) נְעֻרָה; properly, passive participle from 5288 as denominative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6098}/H9022/[H3289]', 'inflected', 'heb', 'עֵצָה', '["ʻêtsâh"]', '["counsels/ your"]', '["n-f"]', 'advice; by implication, plan; also prudence advice, advisement, counsel([-lor]), purpose.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3467}/H9032/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["and/ let them deliver/ you"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1895}/[H1895]', 'lemma', 'heb', 'הָבַר', '["hâbar"]', '["[those who] divide"]', '["v"]', 'to be a horoscopist (astro-) loger.', 'a primitive root of uncertain (perhaps foreign) derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2372}/[H2372]', 'inflected', 'heb', 'חָזָה', '["châzâh"]', '["those/ [who] look","who/ see"]', '["v"]', 'to gaze at; mentally to perceive, contemplate (with pleasure); specifically, to have a vision of behold, look, prophesy, provide, see.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3556}/[H3522]', 'inflected', 'heb', 'כּוֹכָב', '["kôwkâb"]', '["on the/ stars"]', '["n-m"]', 'a star (as round or as shining); figuratively, a prince star(-gazer).', 'probably from the same as 3522 (in the sense of rolling) or 3554 (in the sense of blazing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2552}/H9038/[H2552]', 'inflected', 'heb', 'חָמַם', '["châmam"]', '["to/ warm/ them"]', '["v"]', 'to be hot (literally or figuratively) enflame self, get (have) heat, be (wax) hot, (be, wax) warm (self, at).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5503}/H9022/[H5503]', 'inflected', 'heb', 'סָחַר', '["çâchar"]', '["[was] trader/ your","traders/ your"]', '["v"]', 'to travel round (specifically as a pedlar); intensively, to palpitate go about, merchant(-man), occupy with, pant, trade, traffick.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5676H}/H9023/[H5674]', 'inflected', 'heb', 'עֵבֶר', '["ʻêber"]', '["to/ side/ his"]', '["n-m"]', 'properly, a region across; but used only adverbially (with or without a preposition) on the opposite side (especially of the Jordan; ususally meaning the east) × against, beyond, by, × from, over, passage, quarter, (other, this) side, straight.', 'from 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3467}/H9032\/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["[is] a deliverer for/ you"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4325G}/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["and/ from/ [the] waters of"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0430G}/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["and/ <in>/ [the] God of"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8034}/H9023\/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["name/ his"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6310G}/H9020/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["and/ from/ mouth/ my"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8085I}/H9038/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["and/ I proclaimed/ them"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3045}/H9040/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["for/ knew/ I"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4696>/H9021', 'inflected', 'heb', 'ומצחך', '["u./mitz.cha./Kha"]', '["and/ forehead/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6090B}/H9020/[H6089]', 'inflected', 'heb', 'עֹצֶב', '["ʻôtseb"]', '["idol/ my"]', '["n-m"]', 'an idol (as fashioned); also pain (bodily or mental) idol, sorrow, × wicked.', 'a variation of 6089;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6459}/H9020/[H6458]', 'inflected', 'heb', 'פֶּסֶל', '["peçel"]', '["and/ carved image/ my"]', '["n-m"]', 'an idol carved (graven) image.', 'from 6458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5262}/H9020/[H5258]', 'inflected', 'heb', 'נֶסֶךְ', '["neçek"]', '["and/ molten image/ my"]', '["n-m"]', 'a libation; also a cast idol cover, drink offering, molten image.', 'or נֵסֶךְ; from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8085G}/H9038/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["you had heard of/ them"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3045}/H9039/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["I knew/ them"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2413}/[H2413]', 'lemma', 'heb', 'חָטַם', '["châṭam"]', '["I will restrain myself"]', '["v"]', 'to stop refrain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3772I}/H9031/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["to cut off/ you"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6884}/H9031/[H6884]', 'inflected', 'heb', 'צָרַף', '["tsâraph"]', '["I have refined/ you"]', '["v"]', 'to fuse (metal), i.e. refine (literally or figuratively) cast, (re-) fine(-er), founder, goldsmith, melt, pure, purge away, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3564>', 'inflected', 'heb', 'בכור', '["be./Khur"]', '["in/ a furnace of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414G}\/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["I will give","you will be given"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7121G}/H9020/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["called [one]/ my"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3225G}/H9020/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["and/ right [hand]/ my"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2946}/[H2947]', 'lemma', 'heb', 'טָפַח', '["ṭâphach"]', '["I had given birth","it spread out"]', '["v"]', 'to flatten out or extend (as a tent); figuratively, to nurse a child (as promotive of growth); span, swaddle.', 'a primitive root; or perhaps a denominative from 2947, from dandling on the palms');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1961}/H9044/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["happened/ it"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7307G}/H9023\/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["and/ spirit/ his"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3925G}/H9031/[H3925]', 'inflected', 'heb', 'לָמַד', '["lâmad"]', '["[who] teaches/ you"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4687}/H9020/[H6680]', 'inflected', 'heb', 'מִצְוָה', '["mitsvâh"]', '["to/ commandments/ my"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7965G}/H9021/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["peace/ your"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1530H}/[H1556]', 'inflected', 'heb', 'גַּל', '["gal"]', '["like/ [the] waves of"]', '["n-m"]', 'something rolled, i.e. a heap of stone or dung (plural ruins), by analogy, a spring of water (plural waves) billow, heap, spring, wave.', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6631}/[H3318]', 'inflected', 'heb', 'צֶאֱצָא', '["tseʼĕtsâʼ"]', '["and/ [the] descendants of"]', '["n-m"]', 'issue, i.e. produce, children that which cometh forth (out), offspring.', 'from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4579}/H9023/[H4578]', 'inflected', 'heb', 'מֵעָה', '["mêʻâh"]', '["like/ grains/ its"]', '["n-f"]', 'the belly, i.e. (figuratively) interior gravel.', 'feminine of 4578;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3778}/[H3777]', 'inflected', 'heb', 'כַּשְׂדִּי', '["Kasdîy"]', '["from/ [the] Chaldeans"]', '["n-pr-loc n-pr-m"]', 'a Kasdite, or descendant of Kesed; by implication, a Chaldaean (as if so descended); also an astrologer (as if proverbial of that people Chaldeans, Chaldees, inhabitants of Chaldea.', '(occasionally with enclitic) כַּשְׂדִּימָה; towards the Kasdites into Chaldea), patronymically from 3777 (only in the plural);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2723}/[H2721]', 'inflected', 'heb', 'חׇרְבָּה', '["chorbâh"]', '["[are] in the/ waste places","[when] in/ [the] waste places","among/ ruins"]', '["n-f"]', 'properly, drought, i.e. (by implication) a desolation decayed place, desolate (place, -tion), destruction, (laid) waste (place).', 'feminine of 2721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980J}/H9038/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["[who] caused to walk/ them","he led/ them"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7563}\/[H7561]', 'inflected', 'heb', 'רָשָׁע', '["râshâʻ"]', '["[belongs] to <the>/ wicked [people]"]', '["a"]', 'morally wrong; concretely, an (actively) bad person condemned, guilty, ungodly, wicked (man), that did wrong.', 'from 7561;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2244}/H9030/[H2245]', 'inflected', 'heb', 'חָבָא', '["châbâʼ"]', '["he hid/ me"]', '["v"]', 'to secrete × held, hide (self), do secretly.', 'a primitive root (compare 2245);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2671}/[H2686]', 'inflected', 'heb', 'חֵץ', '["chêts"]', '["<into>/ an arrow"]', '["n-m"]', 'properly, a piercer, i.e. an arrow; by implication, a wound; figuratively, (of God) thunder-bolt; the shaft of a spear archer, arrow, dart, shaft, staff, wound.', 'from 2686; also by interchange for 6086');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0827}/H9023/[H825]', 'inflected', 'heb', 'אַשְׁפָּה', '["ʼashpâh"]', '["in/ quiver/ his"]', '["n-f"]', 'a quiver or arrow-case quiver.', 'perhaps (feminine) from the same as 825 (in the sense of covering);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H8414>', 'inflected', 'heb', 'לתהו', '["le./To.hu"]', '["to/ nothingness"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6468}/H9020/[H6466]', 'inflected', 'heb', 'פְּעֻלָּה', '["pᵉʻullâh"]', '["and/ recompense/ my"]', '["n-f"]', '(abstractly) work labour, reward, wages, work.', 'feminine passive participle of 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3335G}/H9030/[H3334]', 'inflected', 'heb', 'יָצַר', '["yâtsar"]', '["[who] formed/ me"]', '["v"]', 'to mould into a form; especially as a potter; figuratively, to determine (i.e. form a resolution) × earthen, fashion, form, frame, make(-r), potter, purpose.', 'probably identical with 3334 (through the squeezing into shape); (compare 3331);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1961}/H9041/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["for/ being/ you"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6918G}/H9023/[H6942]', 'inflected', 'heb', 'קָדוֹשׁ', '["qâdôwsh"]', '["holy [one]/ its"]', '["a"]', 'sacred (ceremonially or morally); (as noun) God (by eminence), an angel, a saint, a sanctuary holy (One), saint.', 'or קָדֹשׁ; from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8581}/[H8581]', 'inflected', 'heb', 'תַּעָב', '["taʻâb"]', '["to/ [one who] abhors"]', '["v"]', 'to loathe, i.e. (morally) detest (make to be) abhor(-red), (be, commit more, do) abominable(-y), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0977}/H9031/[H977]', 'inflected', 'heb', 'בָּחַר', '["bâchar"]', '["and/ he has chosen/ you"]', '["v"]', 'properly, to try, i.e. (by implication) select acceptable, appoint, choose (choice), excellent, join, be rather, require.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4830}/H9028/[H7462]', 'inflected', 'heb', 'מִרְעִית', '["mirʻîyth"]', '["flock/ their","pasture/ their"]', '["n-f"]', 'pasturage; concretely, a flock flock, pasture.', 'from 7462 in the sense of feeding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8273>', 'opaque', 'heb', 'שָׁרָב', '["shârâb"]', '["burning heat"]', '["n-m"]', 'quivering glow (of the air), especially the mirage heat, parched ground.', 'from an unused root meaning to glare;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7355}/H9038/[H7355]', 'inflected', 'heb', 'רָחַם', '["râcham"]', '["I have compassion on/ them","[one who] has compassion on/ them"]', '["v"]', 'to fondle; by implication, to love, especially to compassionate have compassion (on, upon), love, (find, have, obtain, shew) mercy(-iful, on, upon), (have) pity, Ruhamah, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5090A}/H9038/[H5090]', 'inflected', 'heb', 'נָהַג', '["nâhag"]', '["he will guide/ them"]', '["v"]', 'to drive forth (a person, an animal or chariot), i.e. lead, carry away; reflexively, to proceed (i.e. impel or guide oneself); also (from the panting induced by effort), to sigh acquaint, bring (away), carry away, drive (away), lead (away, forth), (be) guide, lead (away, forth).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4002}/[H5042]', 'lemma', 'heb', 'מַבּוּעַ', '["mabbûwaʻ"]', '["springs of"]', '["n-m"]', 'a fountain fountain, spring.', 'from 5042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5095}/H9038/[H5095]', 'inflected', 'heb', 'נָהַל', '["nâhal"]', '["he will lead/ them"]', '["v"]', 'properly, to run with a sparkle, i.e. flow; hence (transitively), to conduct, and (by inference) to protect, sustain carry, feed, guide, lead (gently, on).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4546}/H9020/[H5549]', 'inflected', 'heb', 'מְסִלָּה', '["mᵉçillâh"]', '["and/ highways/ my"]', '["n-f"]', 'a thoroughfare (as turnpiked), literally or figuratively; specifically a viaduct, a staircase causeway, course, highway, path, terrace.', 'from 5549;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7311A}/H9013/[H7311]', 'inflected', 'heb', 'רוּם', '["rûwm"]', '["they will be lifted up/ !"]', '["v"]', 'to be high actively, to rise or raise (in various applications, literally or figuratively) bring up, exalt (self), extol, give, go up, haughty, heave (up), (be, lift up on, make on, set up on, too) high(-er, one), hold up, levy, lift(-er) up, (be) lofty, (× a-) loud, mount up, offer (up), presumptuously, (be) promote(-ion), proud, set up, tall(-er), take (away, off, up), breed worms.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5515}/[H5515]', 'lemma', 'heb', 'סִינִים', '["Çîynîym"]', '["Sinim"]', '["a"]', 'Sinim, a distant Oriental region Sinim.', 'plural of an otherwise unknown name;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6476}/[H6476]', 'inflected', 'heb', 'פָּצַח', '["pâtsach"]', '["and/ break forth"]', '["v"]', 'to break out (in joyful sound) break (forth, forth into joy), make a loud noise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6041}/H9023/[H6031]', 'inflected', 'heb', 'עָנִי', '["ʻânîy"]', '["and/ afflicted [people]/ his"]', '["a"]', 'depressed, in mind or circumstances afflicted, humble, lowly, needy, poor.', 'from 6031; (practically the same as 6035, although the margin constantly disputes this, making 6035 subjective and objective);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7355}\/[H7355]', 'inflected', 'heb', 'רָחַם', '["râcham"]', '["he has compassion on"]', '["v"]', 'to fondle; by implication, to love, especially to compassionate have compassion (on, upon), love, (find, have, obtain, shew) mercy(-iful, on, upon), (have) pity, Ruhamah, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5764}/H9024/[H5763]', 'inflected', 'heb', 'עוּל', '["ʻûwl"]', '["sucking child/ her"]', '["n-m"]', 'a babe sucking child, infant.', 'from 5763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7355}/[H7355]', 'inflected', 'heb', 'רָחַם', '["râcham"]', '["from/ having compassion on"]', '["v"]', 'to fondle; by implication, to love, especially to compassionate have compassion (on, upon), love, (find, have, obtain, shew) mercy(-iful, on, upon), (have) pity, Ruhamah, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2710}/H9032/[H2710]', 'inflected', 'heb', 'חָקַק', '["châqaq"]', '["I have inscribed/ you"]', '["v"]', 'properly, to hack, i.e. engrave (Judges 5:14, to be a scribe simply); by implication, to enact (laws being cut in stone or metal tablets in primitive times) or (gen.) prescribe appoint, decree, governor, grave, lawgiver, note, pourtray, print, set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2346G>/H9022', 'opaque', 'heb', 'חוֹמָה', '["chôwmâh"]', '["walls/ your"]', '["n-f"]', 'a wall of protection wall, walled.', 'feminine active participle of an unused root apparently meaning to join;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2040}/H9032/[H2040]', 'inflected', 'heb', 'הָרַס', '["hâraç"]', '["[those who] tear down/ you"]', '["v"]', 'to pull down or in pieces, break, destroy beat down, break (down, through), destroy, overthrow, pluck down, pull down, ruin, throw down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2717B}/H9032/[H2717]', 'inflected', 'heb', 'חָרַב', '["chârab"]', '["and/ [those who] make desolate/ you"]', '["v"]', 'to parch (through drought) i.e. (by analogy,) to desolate, destroy, kill decay, (be) desolate, destroy(-er), (be) dry (up), slay, × surely, (lay, lie, make) waste.', 'or חֲרֵב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5716}/[H5710]', 'inflected', 'heb', 'עֲדִי', '["ʻădîy"]', '["like <the>/ ornament[s]"]', '["n-m"]', 'finery; generally an outfit; specifically, a headstall × excellent, mouth, ornament.', 'from 5710 in the sense of trappings;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7194}/H9038/[H7194]', 'inflected', 'heb', 'קָשַׁר', '["qâshar"]', '["and/ you will tie on/ them"]', '["v"]', 'to tie, physically (gird, confine, compact) or mentally (in love, league) bind (up), (make a) conspire(-acy, -ator), join together, knit, stronger, work (treason).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3618G}/[H3634]', 'inflected', 'heb', 'כַּלָּה', '["kallâh"]', '["like <the>/ bride"]', '["n-f"]', 'a bride (as if perfect); hence, a son''s wife bride, daughter-in-law, spouse.', 'from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2723}/H9022/[H2721]', 'inflected', 'heb', 'חׇרְבָּה', '["chorbâh"]', '["waste places/ your"]', '["n-f"]', 'properly, drought, i.e. (by implication) a desolation decayed place, desolate (place, -tion), destruction, (laid) waste (place).', 'feminine of 2721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8074G}/H9022/[H8074]', 'inflected', 'heb', 'שָׁמֵם', '["shâmêm"]', '["and/ desolate [places]/ your"]', '["v"]', 'to stun (or intransitively, grow numb), i.e. devastate or (figuratively) stupefy (both usually in a passive sense) make amazed, be astonied, (be an) astonish(-ment), (be, bring into, unto, lay, lie, make) desolate(-ion, places), be destitute, destroy (self), (lay, lie, make) waste, wonder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2035}/H9022/[H2040]', 'inflected', 'heb', 'הֲרִיסוּת', '["hărîyçûwth"]', '["destruction/ your"]', '["n-f"]', 'demolition destruction.', 'from 2040;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1104}/H9032/[H1104]', 'inflected', 'heb', 'בָּלַע', '["bâlaʻ"]', '["[those who] swallowed up/ you"]', '["v"]', 'to make away with (specifically by swallowing); generally, to destroy cover, destroy, devour, eat up, be at end, spend up, swallow down (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0241G}/H9022/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["in/ ears/ your"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7923}/H9022/[H7921]', 'inflected', 'heb', 'שִׁכֻּלִים', '["shikkulîym"]', '["bereavement<s>/ your"]', '["n-m"]', 'childlessness (by continued bereavements) to have after loss of others.', 'plural from 7921;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3824}/H9022/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["in/ heart/ your"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1565}/[H1563]', 'inflected', 'heb', 'גַּלְמוּד', '["galmûwd"]', '["and/ barren"]', '["a"]', 'sterile (as wrapped up too hard); figuratively, desolate desolate, solitary.', 'probably by prolonged from 1563;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1992}\/[H1931]', 'inflected', 'heb', 'הֵם', '["hêm"]', '["[are] they","they"]', '["p"]', 'they (only used when emphatic) it, like, × (how, so) many (soever, more as) they (be), (the) same, × so, × such, their, them, these, they, those, which, who, whom, withal, ye.', 'or (prolonged) הֵמָּה; masculine plural from 1931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5251H}/H9020/[H5264]', 'inflected', 'heb', 'נֵס', '["nêç"]', '["standard/ my"]', '["n-m"]', 'a flag; also a sail; by implication, a flagstaff; generally a signal; figuratively, a token banner, pole, sail, (en-) sign, standard.', 'from 5264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2684}/[H2683]', 'inflected', 'heb', 'חֹצֶן', '["chôtsen"]', '["in/ a bosom"]', '["n-m"]', 'arm, lap.', 'a collateral form of 2683, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1323G}/H9022/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["and/ daughters/ your"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0539}/H9032/[H541]', 'inflected', 'heb', 'אָמַן', '["ʼâman"]', '["foster-fathers/ your"]', '["v"]', 'properly, to build up or support; to foster as a parent or nurse; figuratively to render (or be) firm or faithful, to trust or believe, to be permanent or quiet; morally to be true or certain; hence, assurance, believe, bring up, establish, fail, be faithful (of long continuance, stedfast, sure, surely, trusty, verified), nurse, (-ing father), (put), trust, turn to the right.', 'a primitive root; (Isaiah 30:21; interchangeable with 541, to go to the right hand)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8282}/H9028/[H8269]', 'inflected', 'heb', 'שָׂרָה', '["sârâh"]', '["and/ princesses/ their"]', '["n-f"]', 'a mistress, i.e. female noble lady, princess, queen.', 'feminine of 8269;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3243I}/H9022/[H3243]', 'inflected', 'heb', 'יָנַק', '["yânaq"]', '["suckling-nurses/ your"]', '["v"]', 'to suck; causatively, to give milk milch, nurse(-ing mother), (give, make to) suck(-ing child, -ling).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6960A}/H9030\/[H6960]', 'inflected', 'heb', 'קָוָה', '["qâvâh"]', '["[those who] wait for/ me"]', '["v"]', 'to bind together (perhaps by twisting), i.e. collect; (figuratively) to expect gather (together), look, patiently, tarry, wait (for, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3947G}/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["¿/ is it taken","¿/ will it be taken"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4455A}/[H3947]', 'inflected', 'heb', 'מַלְקוֹחַ', '["malqôwach"]', '["and/ [the] booty of"]', '["n-m"]', 'transitively (in dual) the jaws (as taking food); intransitively, spoil [and captives] (as taken) booty, jaws, prey.', 'from 3947;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3401}/H9022/[H7378]', 'inflected', 'heb', 'יָרִיב', '["yârîyb"]', '["opponent/ your"]', '["n-m"]', 'literally he will contend; properly, adjective contentious; used as noun, an adversary that content(-eth), that strive.', 'from 7378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3238}/H9032/[H3238]', 'inflected', 'heb', 'יָנָה', '["yânâh"]', '["[those who] maltreat/ you"]', '["v"]', 'to rage or be violent; by implication, to suppress, to maltreat destroy, (thrust out by) oppress(-ing, -ion, -or), proud, vex, do violence.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H6071}/[H6072]', 'inflected', 'heb', 'עָסִיס', '["ʻâçîyç"]', '["and/ like <the>/ sweet wine"]', '["n-m"]', 'must or fresh grape-juice (as just trodden out) juice, new (sweet) wine.', 'from 6072;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0517}/H9026/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["mother/ your"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5383}/H9030/[H5382]', 'inflected', 'heb', 'נָשָׁה', '["nâshâh"]', '["[is one] of/ creditors/ my"]', '["v"]', 'to lend or (by reciprocity) borrow on security or interest creditor, exact, extortioner, lend, usurer, lend on (taker on) usury.', 'a primitive root (rather identical with 5382, in the sense of 5378);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5771G}/H9026/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["for/ iniquities/ your","in/ iniquities/ your"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6588}/H9026/[H6586]', 'inflected', 'heb', 'פֶּשַׁע', '["peshaʻ"]', '["and/ for/ transgressions/ your"]', '["n-m"]', 'a revolt (national, moral or religious) rebellion, sin, transgression, trespass.', 'from 6586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7971I}/[H7971]', 'lemma', 'heb', 'שָׁלַח', '["shâlach"]', '["he will send away","sending away","she was sent away"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7114A}/[H7114]', 'inflected', 'heb', 'קָצַר', '["qâtsar"]', '["¿/ is it short","¿/ really <to be short>"]', '["v"]', 'to dock off, i.e. curtail (transitive or intransitive, literal or figurative); especially to harvest (grass or grain) × at all, cut down, much discouraged, grieve, harvestman, lothe, mourn, reap(-er), (be, wax) short(-en, -er), straiten, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6304}/[H6929]', 'inflected', 'heb', 'פְּדוּת', '["pᵉdûwth"]', '["for/ ransom"]', '["n-f"]', 'distinction; also deliverance division, redeem, redemption.', 'or פְּדֻת; from 6929;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1606}/H9020/[H1605]', 'inflected', 'heb', 'גְּעָרָה', '["gᵉʻârâh"]', '["by/ rebuke/ my"]', '["n-f"]', 'a chiding rebuke(-ing), reproof.', 'from 1605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6940}/[H6937]', 'lemma', 'heb', 'קַדְרוּת', '["qadrûwth"]', '["darkness"]', '["n-f"]', 'duskiness blackness.', 'from 6937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8242}/[H8264]', 'inflected', 'heb', 'שַׂק', '["saq"]', '["and/ sackcloth"]', '["n-m"]', 'properly, a mesh (as allowing a liquid to run through), i.e. coarse loose cloth or sacking (used in mourning and for bagging); hence, a bag (for grain, etc.) sack(-cloth, -clothes).', 'from 8264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3682}/H9028\/[H3680]', 'inflected', 'heb', 'כְּסוּת', '["kᵉçûwth"]', '["covering/ their"]', '["n-f"]', 'a cover (garment); figuratively, a veiling covering, raiment, vesture.', 'from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3928}/[H3925]', 'lemma', 'heb', 'לִמּוּד', '["limmûwd"]', '["O [those] trained","[will be] taught of","accustomed to","disciples"]', '["a"]', 'instructed accustomed, disciple, learned, taught, used.', 'or לִמֻּד; from 3925;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5790}/[H5789]', 'inflected', 'heb', 'עוּת', '["ʻûwth"]', '["to/ help"]', '["v"]', 'to hasten, i.e. succor speak in season.', 'for 5789;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3287}/[H3286]', 'lemma', 'heb', 'יָעֵף', '["yâʻêph"]', '["[the] weary"]', '["a"]', 'fatigued; figuratively, exhausted faint, weary.', 'from 3286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3928}/[H3925]', 'inflected', 'heb', 'לִמּוּד', '["limmûwd"]', '["like <the>/ disciples"]', '["a"]', 'instructed accustomed, disciple, learned, taught, used.', 'or לִמֻּד; from 3925;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1460A}/H9020/[H1342]', 'inflected', 'heb', 'גֵּו', '["gêv"]', '["back/ my"]', '["n-m"]', 'the back; by analogy, the middle among, back, body.', 'from 1342 (corresponding to 1354);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3895H>/H9020', 'inflected', 'heb', 'ולחיי', '["u./le.cha.Ya/i"]', '["and/ cheeks/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4803}/[H4803]', 'inflected', 'heb', 'מָרַט', '["mâraṭ"]', '["to/ [those who] made [them] bare","to/ polish [it]"]', '["v"]', 'to polish; by implication, to make bald (the head), to gall (the shoulder); also, to sharpen bright, furbish, (have his) hair (be) fallen off, peeled, pluck off (hair).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3639}/[H3637]', 'inflected', 'heb', 'כְּלִמָּה', '["kᵉlimmâh"]', '["from/ insults"]', '["n-f"]', 'disgrace confusion, dishonour, reproach, shame.', 'from 3637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7536}/[H7556]', 'inflected', 'heb', 'רֹק', '["rôq"]', '["and/ spittle"]', '["n-m"]', 'spittle spit(-ting, -tle).', 'from 7556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2496}/[H2492]', 'inflected', 'heb', 'חַלָּמִישׁ', '["challâmîysh"]', '["like <the>/ flint"]', '["n-m"]', 'flint flint(-y), rock.', 'probably from 2492 (in the sense of hardness);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6663}/H9030/[H6663]', 'inflected', 'heb', 'צָדַק', '["tsâdaq"]', '["[the one who] justifies/ me"]', '["v"]', 'to be (causatively, make) right (in a moral or forensic sense) cleanse, clear self, (be, do) just(-ice, -ify, -ify self), (be turn to) righteous(-ness).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0430G}/H9023/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["on/ God/ his"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0217A}/[H215]', 'inflected', 'heb', 'אוּר', '["ʼûwr"]', '["by/ [the] light of","in the/ fire"]', '["n-m"]', 'flame; hence (in the plural) the East (as being the region of light) fire, light. See also 224.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0784}/H9026/[H784]', 'inflected', 'heb', 'אֵשׁ', '["ʼêsh"]', '["fire/ your"]', '["n-f"]', 'fire (literally or figuratively) burning, fiery, fire, flaming, hot.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2131A}/[H2187]', 'inflected', 'heb', 'זִיקָה', '["zîyqâh"]', '["and/ with/ [the] firebrands"]', '["n-m"]', 'properly, what leaps forth, i.e. flash of fire, or a burning arrow; also (from the original sense of the root) a bond chain, fetter, firebrand, spark.', '(Isaiah 50:11) (feminine); and זִק; or זֵק; from 2187;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4620}/[H6087]', 'inflected', 'heb', 'מַעֲצֵבָה', '["maʻătsêbâh"]', '["to/ pain"]', '["n-f"]', 'anguish sorrow.', 'from 6087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7901G}/H9013\/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["you will lie down/ !"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4718B}/[H5344]', 'lemma', 'heb', 'מַקֶּבֶת', '["maqqebeth"]', '["[the] excavation of"]', '["n-f"]', 'properly, a perforator, i.e. a hammer (as piercing); also (intransitively) a perforation, i.e. a quarry hammer, hole.', 'from 5344;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2342H}/H9036/[H2342]', 'inflected', 'heb', 'חוּל', '["chûwl"]', '["[who] she gave birth to/ you"]', '["v"]', 'properly, to twist or whirl (in a circular or spiral manner), i.e. (specifically) to dance, to writhe in pain (especially of parturition) or fear; figuratively, to wait, to pervert bear, (make to) bring forth, (make to) calve, dance, drive away, fall grievously (with pain), fear, form, great, grieve, (be) grievous, hope, look, make, be in pain, be much (sore) pained, rest, shake, shapen, (be) sorrow(-ful), stay, tarry, travail (with pain), tremble, trust, wait carefully (patiently), be wounded.', 'or חִיל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1288}/H9033/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["and/ I blessed/ him"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7235A}/H9033\/[H7235]', 'inflected', 'heb', 'רָבָה', '["râbâh"]', '["and/ I multiplied/ him"]', '["v"]', 'to increase (in whatever respect) (bring in) abundance (× -antly), archer (by mistake for 7232), be in authority, bring up, × continue, enlarge, excel, exceeding(-ly), be full of, (be, make) great(-er, -ly, × -ness), grow up, heap, increase, be long, (be, give, have, make, use) many (a time), (any, be, give, give the, have) more (in number), (ask, be, be so, gather, over, take, yield) much (greater, more), (make to) multiply, nourish, plenty(-eous), × process (of time), sore, store, thoroughly, very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2723}/H9024/[H2721]', 'inflected', 'heb', 'חׇרְבָּה', '["chorbâh"]', '["waste places/ its"]', '["n-f"]', 'properly, drought, i.e. (by implication) a desolation decayed place, desolate (place, -tion), destruction, (laid) waste (place).', 'feminine of 2721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4057B}/H9024/[H1696]', 'inflected', 'heb', 'מִדְבָּר', '["midbâr"]', '["wilderness/ its"]', '["n-m"]', 'a pasture (i.e. open field, whither cattle are driven); by implication, a desert; also speech (including its organs) desert, south, speech, wilderness.', 'from 1696 in the sense of driving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5731B}/[H5730]', 'inflected', 'heb', 'עֵדֶן', '["ʻÊden"]', '["like/ Eden"]', '["n-pr-m n-pr-loc"]', 'Eden, the region of Adam''s home Eden.', 'the same as 5730 (masculine);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6160L}/H9024/[H6150]', 'inflected', 'heb', 'עֲרָבָה', '["ʻărâbâh"]', '["and/ desert plain/ its"]', '["n-f"]', 'a desert; especially (with the article prefix) the (generally) sterile valley of the Jordan and its continuation to the Red Sea Arabah, champaign, desert, evening, heaven, plain, wilderness. See also 1026.', 'from 6150 (in the sense of sterility);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2172}\/[H2167]', 'inflected', 'heb', 'זִמְרָה', '["zimrâh"]', '["music"]', '["n-f"]', 'a musical piece or song to be accompanied by an instrument melody, psalm.', 'from 2167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3816>/H9020', 'inflected', 'heb', 'ולאומי', '["u./le.''u.M/i"]', '["and/ O nation/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4941H}/H9020/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["and/ justice/ my"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2220}/H9020/[H2232]', 'inflected', 'heb', 'זְרוֹעַ', '["zᵉrôwaʻ"]', '["and/ arms/ my"]', '["n-f"]', 'the arm (as stretched out), or (of animals) the foreleg; figuratively, force arm, help, mighty, power, shoulder, strength.', 'or (shortened) זְרֹעַ; and (feminine) זְרוֹעָה; or זְרֹעָה; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3176H}/H9013/[H3176]', 'inflected', 'heb', 'יָחַל', '["yâchal"]', '["they will hope/ !"]', '["v"]', 'to wait; by implication, to be patient, hope (cause to, have, make to) hope, be pained, stay, tarry, trust, wait.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4414A}/[H4417]', 'lemma', 'heb', 'מָלַח', '["mâlach"]', '["they will be dispersed"]', '["v"]', 'properly, to rub to pieces or pulverize; intransitively, to disappear as dust; also to salt whether internally (to season with salt) or externally (to rub with salt) × at all, salt, season, temper together, vanish away.', 'a primitive root; also as denominative from 4417');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6666}/H9020/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["and/ righteousness/ my"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2865}\/[H2865]', 'inflected', 'heb', 'חָתַת', '["châthath"]', '["it will be broken"]', '["v"]', 'properly, to prostrate; hence, to break down, either (literally) by violence, or (figuratively) by confusion and fear abolish, affright, be (make) afraid, amaze, beat down, discourage, (cause to) dismay, go down, scare, terrify.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1421}/H9028/[H1422]', 'inflected', 'heb', 'גִּדּוּף', '["giddûwph"]', '["and/ from/ reviling words/ their"]', '["n-m"]', 'vilification reproach, reviling.', 'or (shortened) גִּדֻּף; and (feminine) גִּדּוּפָהxlit giddûphâh corrected to giddûwphâh; or גִּדֻּפָה; from 1422;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/<H6785>', 'inflected', 'heb', 'וכצמר', '["ve./kha./Tze.mer"]', '["and/ like <the>/ wool"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5580}/[H5483]', 'lemma', 'heb', 'סָס', '["çâç"]', '["clothes-moth"]', '["n-m"]', 'a moth (from the agility of the fly) moth.', 'from the same as 5483;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2717A}/[H2717]', 'inflected', 'heb', 'חָרַב', '["chârab"]', '["who/ dried up"]', '["v"]', 'to parch (through drought) i.e. (by analogy,) to desolate, destroy, kill decay, (be) desolate, destroy(-er), (be) dry (up), slay, × surely, (lay, lie, make) waste.', 'or חֲרֵב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4615}/[H6009]', 'lemma', 'heb', 'מַעֲמָק', '["maʻămâq"]', '["[the] depths of"]', '["n-m"]', 'a deep deep, depth.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5381}/H9013/[H5381]', 'inflected', 'heb', 'נָשַׂג', '["nâsag"]', '["they will overtake [them]/ !"]', '["v"]', 'to reach (literally or figuratively) ability, be able, attain (unto), (be able to, can) get, lay at, put, reach, remove, wax rich, × surely, (over-) take (hold of, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5162G}/H9036/[H5162]', 'inflected', 'heb', 'נָחַם', '["nâcham"]', '["I will comfort/ you","[who] comforts/ you"]', '["v"]', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6693}/[H6693]', 'inflected', 'heb', 'צוּק', '["tsûwq"]', '["the/ oppressor"]', '["v"]', 'to compress, i.e. (figuratively) oppress, distress constrain, distress, lie sore, (op-) press(-or), straiten.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6808}/[H6808]', 'lemma', 'heb', 'צָעָה', '["tsâʻâh"]', '["[have been] lying down","[is] stooping","[one who] stoops","[those who] tip"]', '["v"]', 'to tip over (for the purpose of spilling or pouring out), i.e. (figuratively) depopulate; by implication, to imprison or conquer; (reflexive) to lie down (for coitus) captive exile, travelling, (cause to) wander(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7845G}/[H7743]', 'inflected', 'heb', 'שַׁחַת', '["shachath"]', '["to the/ pit"]', '["n-f"]', 'a pit (especially as a trap); figuratively, destruction corruption, destruction, ditch, grave, pit.', 'from 7743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3245}/[H3245]', 'inflected', 'heb', 'יָסַד', '["yâçad"]', '["and/ to/ found"]', '["v"]', 'to set (literally or figuratively); intensively, to found; reflexively, to sit down together, i.e. settle, consult appoint, take counsel, establish, (lay the, lay for a) found(-ation), instruct, lay, ordain, set, × sure.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0859A}\/[H859]', 'inflected', 'heb', 'אַתָּה', '["ʼattâh"]', '["you"]', '["p"]', 'thou and thee, or (plural) ye and you thee, thou, ye, you.', 'or (shortened); אַתָּ; or אַת; feminine (irregular) sometimes אַתִּי; plural masculine אַתֶּם; feminine אַתֶּן; or אַתֵּנָהlemma אתֵּנָה missing vowel, corrected to אַתֵּנָה; or אַתֵּנָּה; a primitive pronoun of the second person;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6907}/[H6906]', 'lemma', 'heb', 'קֻבַּעַת', '["qubbaʻath"]', '["[the] bowl of"]', '["n-f"]', 'a goblet (as deep like a cover) dregs.', 'from 6906;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8653}/[H7477]', 'inflected', 'heb', 'תַּרְעֵלָה', '["tarʻêlâh"]', '["<the>/ staggering"]', '["n-f"]', 'reeling astonishment, trembling.', 'from 7477;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7122I}/H9032/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["[have] happened to/ you"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7701}/[H7736]', 'inflected', 'heb', 'שֹׁד', '["shôd"]', '["the/ devastation"]', '["n-m"]', 'violence, ravage desolation, destruction, oppression, robbery, spoil(-ed, -er, -ing), wasting.', 'or שׁוֹד; (Job 5:21), from 7736;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7667}/[H7665]', 'inflected', 'heb', 'שֶׁבֶר', '["sheber"]', '["and/ <the>/ brokenness","and/ the/ destruction"]', '["n-m"]', 'a fracture, figuratively, ruin; specifically, a solution (of a dream) affliction, breach, breaking, broken(-footed, -handed), bruise, crashing, destruction, hurt, interpretation, vexation.', 'or שֵׁבֶר; from 7665;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2719}/[H2717]', 'inflected', 'heb', 'חֶרֶב', '["chereb"]', '["and/ the/ sword"]', '["n-f"]', 'drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5162G}/H9032/[H5162]', 'inflected', 'heb', 'נָחַם', '["nâcham"]', '["do I comfort/ you"]', '["v"]', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8377}/[H8376]', 'inflected', 'heb', 'תְּאוֹ', '["tᵉʼôw"]', '["like/ an antelope of"]', '["n-m"]', 'a species of antelope (probably from the white stripe on the cheek) wild bull (ox).', 'and תּוֹא; (the original form), from 8376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4364A}/[H3648]', 'lemma', 'heb', 'מַכְמָר', '["makmâr"]', '["a net"]', '["n-m"]', 'a (hunter''s) net (as dark from concealment) net.', 'or מִכְמֹר; from 3648 in the sense of blackening by heat;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H3196>\', 'inflected', 'heb', 'מיין ס', '["mi./Ya.yin"]', '["from/ wine"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8354}/H9034/[H8354]', 'inflected', 'heb', 'שָׁתָה', '["shâthâh"]', '["to/ drink/ it"]', '["v"]', 'to imbibe (literally or figuratively) × assuredly, banquet, × certainly, drink(-er, -ing), drunk (× -ard), surely. (Prop. intensive of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3013}/H9032/[H3013]', 'inflected', 'heb', 'יָגָה', '["yâgâh"]', '["[those who] torment/ you"]', '["v"]', 'to grieve afflict, cause grief, grieve, sorrowful, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5315I}/H9022/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["to/ self/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H0776H>', 'inflected', 'heb', 'כארץ', '["kha./''A.retz"]', '["like the/ ground"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1460A}/H9022/[H1342]', 'inflected', 'heb', 'גֵּו', '["gêv"]', '["back/ your"]', '["n-m"]', 'the back; by analogy, the middle among, back, body.', 'from 1342 (corresponding to 1354);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/<H2351>', 'inflected', 'heb', 'וכחוץ', '["ve./kha./Chutz"]', '["and/ like the/ street"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5674A}\/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["for <the>/ [those who] pass over"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5797}/H9022/[H5810]', 'inflected', 'heb', 'עֹז', '["ʻôz"]', '["strength/ your"]', '["n-m"]', 'strength in various applications (force, security, majesty, praise) boldness, loud, might, power, strength, strong.', 'or (fully) עוֹז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8597}/H9022/[H6286]', 'inflected', 'heb', 'תִּפְאָרָה', '["tiphʼârâh"]', '["beauty/ your"]', '["n-f"]', 'ornament (abstractly or concretely, literally or figuratively) beauty(-iful), bravery, comely, fair, glory(-ious), honour, majesty.', 'or תִּפְאֶרֶת; from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4147}/[H3256]', 'lemma', 'heb', 'מוֹסֵר', '["môwçêr"]', '["[the] fetters of","fetters"]', '["n-m"]', 'properly, chastisement, i.e. (by implication) a halter; figuratively, restraint band, bond.', 'also (in plural) feminine מוֹסֵרָה; or מֹסְרָה; from 3256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7628B}/[H7618]', 'lemma', 'heb', 'שְׁבִי', '["shᵉbîy"]', '["O captive [one]"]', '["n-m"]', 'exiled; captured; as noun, exile (abstractly or concretely and collectively); by extension, booty captive(-ity), prisoners, × take away, that was taken.', 'from 7618;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0804G}/[H833]', 'inflected', 'heb', 'אַשּׁוּר', '["ʼAshshûwr"]', '["and/ Assyria"]', '["n-pr-m n-pr-loc"]', 'Ashshur, the second son of Shem; also his descendants and the country occupied by them (i.e. Assyria), its region and its empire Asshur, Assur, Assyria, Assyrians. See 838.', 'or אַשֻּׁר; apparently from 833 (in the sense of successful);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6231}/H9033/[H6229]', 'inflected', 'heb', 'עָשַׁק', '["ʻâshaq"]', '["it oppressed/ it"]', '["v"]', 'to press upon, i.e. oppress, defraud, violate, overflow get deceitfully, deceive, defraud, drink up, (use) oppress(-ion), -or), do violence (wrong).', 'a primitive root (compare 6229);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H8548>', 'inflected', 'heb', 'ותמיד', '["ve./ta.Mid"]', '["and/ continually"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6822}/H9032/[H6822]', 'inflected', 'heb', 'צָפָה', '["tsâphâh"]', '["watchmen/ your"]', '["v"]', 'properly, to lean forward, i.e. to peer into the distance; by implication, to observe, await behold, espy, look up (well), wait for, (keep the) watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H8432>/H9024', 'inflected', 'heb', 'מתוכה', '["mi./to.Kha/h"]', '["from/ [the] midst of/ it"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4499}/[H4498]', 'inflected', 'heb', 'מְנוּסָה', '["mᵉnûwçâh"]', '["and/ in/ flight"]', '["n-f"]', 'retreat fleeing, flight.', 'or מְנֻסָה; feminine of 4498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0622}/H9036/[H622]', 'inflected', 'heb', 'אָסַף', '["ʼâçaph"]', '["and/ [will be] rearguard/ your"]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4893A}/[H7843]', 'lemma', 'heb', 'מִשְׁחָת', '["mishchâth"]', '["[was] a disfigurement"]', '["n-m"]', 'disfigurement corruption, marred.', 'or מׇשְׁחָת; from 7843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8389}/H9023/[H8388]', 'inflected', 'heb', 'תֹּאַר', '["tôʼar"]', '["and/ form/ his"]', '["n-m"]', 'outline, i.e. figure or appearance beautiful, × comely, countenance, fair, × favoured, form, × goodly, × resemble, visage.', 'from 8388;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5137B}/[H5137]', 'lemma', 'heb', 'נָזָה', '["nâzâh"]', '["he will startle"]', '["v"]', 'to spirt, i.e. besprinkle (especially in expiation) sprinkle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8052}/H9025/[H8074]', 'inflected', 'heb', 'שְׁמוּעָה', '["shᵉmûwʻâh"]', '["<to>/ report/ our"]', '["n-f"]', 'something heard, i.e. an announcement bruit, doctrine, fame, mentioned, news, report, rumor, tidings.', 'feminine passive participle of 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3126}/[H3243]', 'inflected', 'heb', 'יוֹנֵק', '["yôwnêq"]', '["like <the>/ shoot"]', '["n-m"]', 'a sucker; hence, a twig (of a tree felled and sprouting) tender plant.', 'active participle of 3243;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H8328}/[H8327]', 'inflected', 'heb', 'שֶׁרֶשׁ', '["sheresh"]', '["and/ like <the>/ root"]', '["n-m"]', 'a root (literally or figuratively) bottom, deep, heel, root.', 'from 8327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2530A}/H9033/[H2530]', 'inflected', 'heb', 'חָמַד', '["châmad"]', '["and/ we will desire/ him"]', '["v"]', 'to delight in beauty, greatly beloved, covet, delectable thing, (× great) delight, desire, goodly, lust, (be) pleasant (thing), precious (thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2310}/[H2308]', 'inflected', 'heb', 'חָדֵל', '["châdêl"]', '["and/ rejected of"]', '["a"]', 'vacant, i.e. ceasing or destitute he that forbeareth, frail, rejected.', 'from 2308;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H4564}/[H5641]', 'inflected', 'heb', 'מַסְתֵּר', '["maçtêr"]', '["and/ like/ a hiding of"]', '["n-m"]', 'properly, a hider, i.e. (abstractly) a hiding, i.e. aversion hid.', 'from 5641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2803H}/H9033/[H2803]', 'inflected', 'heb', 'חָשַׁב', '["châshab"]', '["we valued/ him"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2483}/H9025/[H2470]', 'inflected', 'heb', 'חֳלִי', '["chŏlîy"]', '["sicknesses/ our"]', '["n-m"]', 'malady, anxiety, calamity disease, grief, (is) sick(-ness).', 'from 2470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4341}/H9025/[H3510]', 'inflected', 'heb', 'מַכְאֹב', '["makʼôb"]', '["and/ pains/ our"]', '["n-m"]', 'anguish or (figuratively) affliction grief, pain, sorrow.', 'sometimes מַכְאוֹב; also (feminine Isaiah 53:3) מַכְאֹבָה; from 3510;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5445}/H9038/[H5445]', 'inflected', 'heb', 'סָבַל', '["çâbal"]', '["he carried/ them"]', '["v"]', 'to carry (literally or figuratively), or (reflexively) be burdensome; specifically, to be gravid bear, be a burden, carry, strong to labour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2803J}/H9033/[H2803]', 'inflected', 'heb', 'חָשַׁב', '["châshab"]', '["we considered/ him"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6588}/H9025/[H6586]', 'inflected', 'heb', 'פֶּשַׁע', '["peshaʻ"]', '["from/ transgressions/ our"]', '["n-m"]', 'a revolt (national, moral or religious) rebellion, sin, transgression, trespass.', 'from 6586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7965G}/H9025/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["peace/ our"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2250}/H9023/[H2266]', 'inflected', 'heb', 'חַבּוּרָה', '["chabbûwrâh"]', '["and/ by/ wound[s]/ his"]', '["n-f"]', 'properly, bound (with stripes), i.e. a weal (or black-and-blue mark itself) blueness, bruise, hurt, stripe, wound.', 'or חַבֻּרָה; or חֲבֻרָה; from 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1870G}/H9023/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["to/ own way/ his"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/<H7353>', 'inflected', 'heb', 'וכרחל', '["u./khe./ra.Chel"]', '["and/ like/ a ewe"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1494}/H9034/[H1468]', 'inflected', 'heb', 'גָּזַז', '["gazâz"]', '["shearers/ its"]', '["v"]', 'to cut off; specifically to shear a flock or shave the hair; figuratively to destroy an enemy cut off (down), poll, shave, (sheep-) shear(-er).', 'a primitive root (akin to 1468);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4941G}/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["and/ from/ judgment"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1755}/H9023/[H1752]', 'inflected', 'heb', 'דּוֹר', '["dôwr"]', '["generation/ his"]', '["n-m"]', 'properly, a revolution of time, i.e. an age or generation; also a dwelling age, × evermore, generation, (n-) ever, posterity.', 'or (shortened) דֹּר; from 1752;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1792}/H9033/[H1794]', 'inflected', 'heb', 'דָּכָא', '["dâkâʼ"]', '["to crush/ him"]', '["v"]', 'to crumble; transitively, to bruise (literally or figuratively) beat to pieces, break (in pieces), bruise, contrite, crush, destroy, humble, oppress, smite.', 'a primitive root (compare 1794);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2656}/[H2654]', 'inflected', 'heb', 'חֵפֶץ', '["chêphets"]', '["and/ [the] pleasure of"]', '["n-m"]', 'pleasure; hence (abstractly) desire; concretely, a valuable thing; hence (by extension) a matter (as something in mind) acceptable, delight(-some), desire, things desired, matter, pleasant(-ure), purpose, willingly.', 'from 2654;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5999}/[H5998]', 'inflected', 'heb', 'עָמָל', '["ʻâmâl"]', '["from/ [the] labor of"]', '["n"]', 'toil, i.e. wearing effort; hence, worry, whether of body or mind grievance(-vousness), iniquity, labour, mischief, miserable(-sery), pain(-ful), perverseness, sorrow, toil, travail, trouble, wearisome, wickedness.', 'from 5998;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5771G}/H9028/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["and/ iniquities/ their"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6586}/[H6586]', 'inflected', 'heb', 'פָּשַׁע', '["pâshaʻ"]', '["and/ for the/ transgressors"]', '["v"]', 'to break away (from just authority), i.e. trespass, apostatize, quarrel offend, rebel, revolt, transgress(-ion, -or).', 'a primitive root (identical with through the idea of expansion);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6293}\/[H6293]', 'inflected', 'heb', 'פָּגַע', '["pâgaʻ"]', '["he will make entreaty"]', '["v"]', 'to impinge, by accident or violence, or (figuratively) by importunity come (betwixt), cause to entreat, fall (upon), make intercession, intercessor, intreat, lay, light (upon), meet (together), pray, reach, run.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6670A}/[H6670]', 'inflected', 'heb', 'צָהַל', '["tsâhal"]', '["and/ cry aloud","and/ shout for joy","so/ you may neigh"]', '["v"]', 'to gleam, i.e. (figuratively) be cheerful; by transference to sound clear (of various animal or human expressions) bellow, cry aloud (out), lift up, neigh, rejoice, make to shine, shout.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0168G}/H9022/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["tent/ your"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3407}/[H3415]', 'inflected', 'heb', 'יְרִיעָה', '["yᵉrîyʻâh"]', '["and/ [the] tent curtains of"]', '["n-f"]', 'a hanging (as tremulous) curtain.', 'from 3415;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4908}/H9022/[H7931]', 'inflected', 'heb', 'מִשְׁכָּן', '["mishkân"]', '["dwellings/ your"]', '["n-m"]', 'a residence (including a shepherd''s hut, the lair of animals, figuratively, the grave; also the Temple); specifically, the Tabernacle (properly, its wooden walls) dwelleth, dwelling (place), habitation, tabernacle, tent.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4340}/H9022/[H3498]', 'inflected', 'heb', 'מֵיתָר', '["mêythâr"]', '["tent cords/ your"]', '["n-m"]', 'a cord (of a tent); or the string (of a bow) cord, string.', 'from 3498; (compare 3499)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3489>/H9022', 'inflected', 'heb', 'ויתדתיך', '["vi./te.do.Ta.yi/kh"]', '["and/ tent pegs/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2233H}/H9022/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["and/ offspring/ your"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5934}/H9022/[H5956]', 'inflected', 'heb', 'עָלוּם', '["ʻâlûwm"]', '["youth<s>/ your"]', '["n-m"]', '(only in plural as abstract) adolescence; figuratively, vigor youth.', 'passive participle of 5956 in the denominative sense of 5958;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0491}/H9022/[H488]', 'inflected', 'heb', 'אַלְמָנוּת', '["ʼalmânûwth"]', '["widowhood/ your"]', '["n-f"]', 'concrete, a widow; abstract, widowhood widow, widowhood.', 'feminine of 488;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1166I}/H9032/[H1167]', 'inflected', 'heb', 'בָּעַל', '["bâʻal"]', '["husband<s>/ your","they will marry/ you"]', '["v"]', 'to be master; hence, to marry have dominion (over), be husband, marry(-ried, × wife).', 'a primitive root; also as denominative from 1167');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213H}/H9032/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["[is] maker<s>/ your"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0802H}/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["like/ a wife"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6087A}/[H6087]', 'inflected', 'heb', 'עָצַב', '["ʻâtsab"]', '["and/ grieved of","and/ they grieved"]', '["v"]', 'properly, to carve, i.e. fabricate or fashion; hence (in a bad sense) to worry, pain or anger displease, grieve, hurt, make, be sorry, vex, worship, wrest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7121G}/H9032/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["he will call/ you"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5271A}/[H5288]', 'lemma', 'heb', 'נָעוּר', '["nâʻûwr"]', '["youth<s>"]', '["n-m n-f"]', '(only in plural collective or emphatic form) youth, the state (juvenility) or the persons (young people) childhood, youth.', 'or נָעֻר; and (feminine) נְעֻרָה; properly, passive participle from 5288 as denominative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7281}/[H7280]', 'inflected', 'heb', 'רֶגַע', '["regaʻ"]', '["for/ a moment"]', '["n-m"]', 'a wink (of the eyes), i.e. a very short space of time instant, moment, space, suddenly.', 'from 7280.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5800A}/H9032/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["I abandoned/ you"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7356B}/[H7355]', 'inflected', 'heb', 'רַחַם', '["racham"]', '["and/ in/ compassion<s>"]', '["n-f"]', 'compassion (in the plural); by extension, the womb (as cherishing the fetus); by implication, a maiden bowels, compassion, damsel, tender love, (great, tender) mercy, pity, womb.', 'from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6908}/H9032/[H6908]', 'inflected', 'heb', 'קָבַץ', '["qâbats"]', '["I will gather/ you"]', '["v"]', 'to grasp, i.e. collect assemble (selves), gather (bring) (together, selves together, up), heap, resort, × surely, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8241}/[H7857]', 'inflected', 'heb', 'שֶׁצֶף', '["shetseph"]', '["in/ a flood of"]', '["n-m"]', 'an outburst (of anger) little.', 'from 7857 (for alliteration with 7110);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7355}/H9032/[H7355]', 'inflected', 'heb', 'רָחַם', '["râcham"]', '["I have had compassion on/ you","I will have compassion on/ you","[one who] has compassion on/ you"]', '["v"]', 'to fondle; by implication, to love, especially to compassionate have compassion (on, upon), love, (find, have, obtain, shew) mercy(-iful, on, upon), (have) pity, Ruhamah, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1350A}/H9022/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["redeemer/ your"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7107}/[H7107]', 'inflected', 'heb', 'קָצַף', '["qâtsaph"]', '["from/ being angry"]', '["v"]', 'to crack off, i.e. (figuratively) burst out in rage (be) anger(-ry), displease, fret self, (provoke to) wrath (come), be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1605}/[H1605]', 'inflected', 'heb', 'גָּעַר', '["gâʻar"]', '["and/ from/ rebuking"]', '["v"]', 'to chide corrupt, rebuke, reprove.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1389I}/[H1387]', 'inflected', 'heb', 'גִּבְעָה', '["gibʻâh"]', '["and/ the/ hills"]', '["n-f"]', 'a hillock hill, little hill.', 'feminine from the same as 1387;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0854}/H9032/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["from/ with <the>/ you"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7965G}/H9020/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["peace/ my"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5590}/[H5590]', 'lemma', 'heb', 'סָעַר', '["çâʻar"]', '["[which] it is storm-driven","it is storm tossed","they storm"]', '["v"]', 'to rush upon; by implication, to toss (transitive or intransitive, literal or figurative) be (toss with) tempest(-uous), be sore, troubled, come out as a (drive with the, scatter with a) whirlwind.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0068G}/H9022/[H1129]', 'inflected', 'heb', 'אֶבֶן', '["ʼeben"]', '["stones/ your"]', '["n-f"]', 'a stone carbuncle, mason, plummet, (chalk-, hail-, head-, sling-) stone(-ny), (divers) weight(-s).', 'from the root of 1129 through the meaning to build;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3245}/H9032/[H3245]', 'inflected', 'heb', 'יָסַד', '["yâçad"]', '["and/ I will refound/ you"]', '["v"]', 'to set (literally or figuratively); intensively, to found; reflexively, to sit down together, i.e. settle, consult appoint, take counsel, establish, (lay the, lay for a) found(-ation), instruct, lay, ordain, set, × sure.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5601}/[H5608]', 'inflected', 'heb', 'סַפִּיר', '["çappîyr"]', '["with <the>/ sapphires"]', '["n-m"]', 'a gem (perhaps used for scratching other substances), probably the sapphire sapphire.', 'from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3539}/[H3537]', 'lemma', 'heb', 'כַּדְכֹּד', '["kadkôd"]', '["ruby"]', '["n-m"]', 'a sparkling gem, probably the ruby agate.', 'from the same as 3537 in the sense of striking fire from a metal forged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8121>/H9022', 'opaque', 'heb', 'שֶׁמֶשׁ', '["shemesh"]', '["battlements/ your","sun/ your"]', '["n"]', 'the sun; by implication, the east; figuratively, a ray, i.e. (architectural) a notched battlement east side(-ward), sun (rising), west(-ward), window. See also 1053.', 'from an unused root meaning to be brilliant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8179G}/H9022/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["and/ gates/ your"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0688}/[H6916]', 'lemma', 'heb', 'אֶקְדָּח', '["ʼeqdâch"]', '["beryl"]', '["n-m"]', 'burning, i.e. a carbuncle or other fiery gem carbuncle.', 'from 6916;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4288}/[H2846]', 'inflected', 'heb', 'מְחִתָּה', '["mᵉchittâh"]', '["and/ from/ terror"]', '["n-f"]', 'properly, a dissolution; concretely, a ruin, or (abstractly) consternation destruction, dismaying, ruin, terror.', 'from 2846;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0853}/H9030/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["from/ <obj.>/ me"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3318M}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ [who] produces"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4639G}/H9023/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["for/ work/ its"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6666}/H9028/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["and/ righteousness/ their"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3808}/[H3808]', 'inflected', 'heb', 'לֹא', '["lôʼ"]', '["and/ with/ not"]', '["adv"]', 'not (the simple or abs. negation); by implication, no; often used with other particles × before, or else, ere, except, ig(-norant), much, less, nay, neither, never, no((-ne), -r, (-thing)), (× as though...,(can-), for) not (out of), of nought, otherwise, out of, surely, as truly as, of a truth, verily, for want, whether, without.', 'or לוֹא; or לֹה; (Deuteronomy 3:11), a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3018}/H9026/[H3021]', 'inflected', 'heb', 'יְגִיעַ', '["yᵉgîyaʻ"]', '["and/ toil/ your"]', '["n-m"]', 'toil; hence, a work, produce, property (as the result of labor) labour, work.', 'from 3021;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1880}/[H1878]', 'inflected', 'heb', 'דֶּשֶׁן', '["deshen"]', '["in <the>/ fatness"]', '["n-m"]', 'the fat; abstractly fatness, i.e. (figuratively) abundance; specifically the (fatty) ashes of sacrifices ashes, fatness.', 'from 1878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6286A}/H9031\/[H6288]', 'inflected', 'heb', 'פָּאַר', '["pâʼar"]', '["he has glorified/ you"]', '["v"]', 'to gleam, i.e. (causatively) embellish; figuratively, to boast; also to explain (i.e. make clear) oneself; to shake a tree beautify, boast self, go over the boughs, glorify (self), glory, vaunt self.', 'a primitive root; also denominative from 6288,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4672}/H9043/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["when/ he lets be found/ himself"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7355}/H9033/[H7355]', 'inflected', 'heb', 'רָחַם', '["râcham"]', '["so/ he may have compassion on/ him"]', '["v"]', 'to fondle; by implication, to love, especially to compassionate have compassion (on, upon), love, (find, have, obtain, shew) mercy(-iful, on, upon), (have) pity, Ruhamah, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4284}/H9020/[H2803]', 'inflected', 'heb', 'מַחֲשָׁבָה', '["machăshâbâh"]', '["thoughts/ my"]', '["n-f"]', 'a contrivance, i.e. (concretely) a texture, machine, or (abstractly) intention, plan (whether bad, a plot; or good, advice) cunning (work), curious work, device(-sed), imagination, invented, means, purpose, thought.', 'or מַחֲשֶׁבֶת; from 2803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870G}/H9026/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["[are] ways/ your","ways/ your"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4284}/H9020/[H2803]', 'inflected', 'heb', 'מַחֲשָׁבָה', '["machăshâbâh"]', '["and/ thoughts/ my"]', '["n-f"]', 'a contrivance, i.e. (concretely) a texture, machine, or (abstractly) intention, plan (whether bad, a plot; or good, advice) cunning (work), curious work, device(-sed), imagination, invented, means, purpose, thought.', 'or מַחֲשֶׁבֶת; from 2803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4284}/H9026/[H2803]', 'inflected', 'heb', 'מַחֲשָׁבָה', '["machăshâbâh"]', '["more than/ thoughts/ your"]', '["n-f"]', 'a contrivance, i.e. (concretely) a texture, machine, or (abstractly) intention, plan (whether bad, a plot; or good, advice) cunning (work), curious work, device(-sed), imagination, invented, means, purpose, thought.', 'or מַחֲשֶׁבֶת; from 2803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7950}/[H7949]', 'inflected', 'heb', 'שֶׁלֶג', '["sheleg"]', '["and/ the/ snow"]', '["n-m"]', 'snow (probably from its whiteness) snow(-y).', 'from 7949;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3205}/H9034/[H3205]', 'inflected', 'heb', 'יָלַד', '["yâlad"]', '["and/ it has caused to bring forth/ it"]', '["v"]', 'to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6779}/H9034/[H6779]', 'inflected', 'heb', 'צָמַח', '["tsâmach"]', '["and/ it has made sprout/ it"]', '["v"]', 'to sprout (transitive or intransitive, literal or figurative) bear, bring forth, (cause to, make to) bud (forth), (cause to, make to) grow (again, up), (cause to) spring (forth, up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7965G}/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["and/ in/ peace"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2986}/H9013/[H2986]', 'inflected', 'heb', 'יָבַל', '["yâbal"]', '["they will bring/ !","you will be led/ !"]', '["v"]', 'properly, to flow; causatively, to bring (especially with pomp) bring (forth), carry, lead (forth).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5636}/[H5635]', 'inflected', 'heb', 'סַרְפָּד', '["çarpâd"]', '["the/ nettle"]', '["n-m"]', 'a nettle (as stinging like a burn) brier.', 'from 5635;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1540H}/[H1540]', 'inflected', 'heb', 'גָּלָה', '["gâlâh"]', '["to/ be revealed"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2490H}/H9033/[H2470]', 'inflected', 'heb', 'חָלַל', '["châlal"]', '["from/ profaning/ it"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7451H}\/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["evil"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0914}/H9030/[H914]', 'inflected', 'heb', 'בָּדַל', '["bâdal"]', '["he will separate/ me"]', '["v"]', 'to divide (in variation senses literally or figuratively, separate, distinguish, differ, select, etc.) (make, put) difference, divide (asunder), (make) separate (self, -ation), sever (out), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3002}\/[H3001]', 'inflected', 'heb', 'יָבֵשׁ', '["yâbêsh"]', '["dry"]', '["a"]', 'dry dried (away), dry.', 'from 3001;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H5631>', 'inflected', 'heb', 'לסריסים', '["la./sa.ri.Sim"]', '["to the/ eunuchs"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1285}/H9020/[H1262]', 'inflected', 'heb', 'בְּרִית', '["bᵉrîyth"]', '["on/ covenant/ my"]', '["n-f"]', 'a compact (because made by passing between pieces of flesh) confederacy, (con-) feder(-ate), covenant, league.', 'from 1262 (in the sense of cutting [like 1254]);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H2346G>/H9020', 'inflected', 'heb', 'ובחומתי', '["u./ve./cho.mo.Ta/i"]', '["and/ in/ walls/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027M}/[H3027]', 'lemma', 'heb', 'יָד', '["yâd"]', '["a monument"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1323G}/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["and/ more than/ daughters"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8055}/H9038/[H8055]', 'inflected', 'heb', 'שָׂמַח', '["sâmach"]', '["and/ I will make glad/ them","and/ I will make rejoice/ them"]', '["v"]', 'probably to brighten up, i.e. (figuratively) be (causatively, make) blithe or gleesome cheer up, be (make) glad, (have, make) joy(-ful), be (make) merry, (cause to, make to) rejoice, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2077}/H9028/[H2076]', 'inflected', 'heb', 'זֶבַח', '["zebach"]', '["and/ sacrifices/ their"]', '["n-m"]', 'properly, a slaughter, i.e. the flesh of an animal; by implication, a sacrifice (the victim or the act) offer(-ing), sacrifice.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004Q}/H9020/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["house/ my"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6908}/H9033/[H6908]', 'inflected', 'heb', 'קָבַץ', '["qâbats"]', '["to/ gathered [ones]/ its"]', '["v"]', 'to grasp, i.e. collect assemble (selves), gather (bring) (together, selves together, up), heap, resort, × surely, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3293A>\', 'inflected', 'heb', 'ביער ס', '["ba/i.Ya.''ar"]', '["in the/ forest"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6822}/H9033/[H6822]', 'inflected', 'heb', 'צָפָה', '["tsâphâh"]', '["watchmen/ its"]', '["v"]', 'properly, to lean forward, i.e. to peer into the distance; by implication, to observe, await behold, espy, look up (well), wait for, (keep the) watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5024}/[H5024]', 'inflected', 'heb', 'נָבַח', '["nâbach"]', '["to/ bark"]', '["v"]', 'to bark (as a dog) bark.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1957}/[H2372]', 'lemma', 'heb', 'הָזָה', '["hâzâh"]', '["[they] dream"]', '["v"]', 'to dream sleep.', 'a primitive root (compare 2372);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5123}/[H5123]', 'inflected', 'heb', 'נוּם', '["nûwm"]', '["<of>/ to slumber"]', '["v"]', 'to slumber (from drowsiness) sleep, slumber.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H3611>', 'inflected', 'heb', 'והכלבים', '["ve./ha./ke.la.Vim"]', '["and/ the/ dogs"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7654}/[H7648]', 'lemma', 'heb', 'שׇׂבְעָה', '["sobʻâh"]', '["satiety"]', '["n-f"]', 'satiety (to have) enough, × till...be full, (un-) satiable, satisfy, × sufficiently.', 'feminine of 7648;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1870G}/H9028/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["to/ own way/ their"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1215}/H9023/[H1214]', 'inflected', 'heb', 'בֶּצַע', '["betsaʻ"]', '["to/ own unjust gain/ his"]', '["n-m"]', 'plunder; by extension, gain (usually unjust) covetousness, (dishonest) gain, lucre, profit.', 'from 1214;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7097A}/H9023/[H7096]', 'inflected', 'heb', 'קָצֶה', '["qâtseh"]', '["from/ border/ its","from/ end/ his"]', '["n-m"]', 'an extremity × after, border, brim, brink, edge, end, (in-) finite, frontier, outmost coast, quarter, shore, (out-) side, × some, ut(-ter-) most (part).', 'or (negative only) קֵצֶה; from 7096; (used in a great variety of applications and idioms; compare 7093)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5433A}/[H5433]', 'inflected', 'heb', 'סָבָא', '["çâbâʼ"]', '["and/ let us drink"]', '["v"]', 'to quaff to satiety, i.e. become tipsy drunkard, fill self, Sabean, (wine-) bibber.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5228}/H9023/[H5226]', 'inflected', 'heb', 'נָכֹחַ', '["nâkôach"]', '["uprightness/ his"]', '["a"]', 'straightforward, i.e. (figuratively), equitable, correct, or (abstractly), integrity plain, right, uprightness.', 'from the same as 5226;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2552}/[H2552]', 'inflected', 'heb', 'חָמַם', '["châmam"]', '["who/ inflame yourselves"]', '["v"]', 'to be hot (literally or figuratively) enflame self, get (have) heat, be (wax) hot, (be, wax) warm (self, at).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0352D}/[H193]', 'inflected', 'heb', 'אַיִל', '["ʼayil"]', '["among the/ oaks"]', '["n-m"]', 'properly, strength; hence, anything strong; specifically a chief (politically); also a ram (from his strength); a pilaster (as a strong support); an oak or other strong tree mighty (man), lintel, oak, post, ram, tree.', 'from the same as 193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2511}/[H2505]', 'inflected', 'heb', 'חַלָּק', '["challâq"]', '["[is] among/ [the] smooth [stones] of"]', '["n-m"]', 'smooth smooth.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2506A}/H9022/[H2505]', 'inflected', 'heb', 'חֵלֶק', '["chêleq"]', '["portion/ your"]', '["n-m"]', 'properly, smoothness (of the tongue); also an allotment flattery, inheritance, part, × partake, portion.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1486>/H9022', 'opaque', 'heb', 'גּוֹרָל', '["gôwrâl"]', '["[are] allotted portion/ your","[is] lot/ your"]', '["n-m"]', 'properly, a pebble, i.e. a lot (small stones being used for that purpose); figuratively, a portion or destiny (as if determined by lot) lot.', 'or (shortened) גֹּרָל; from an unused root meaning to be rough (as stone);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4904}/H9022/[H7901]', 'inflected', 'heb', 'מִשְׁכָּב', '["mishkâb"]', '["bed/ your"]', '["n-m"]', 'a bed (figuratively, a bier); abstractly, sleep; by euphemism, carnal intercourse bed(-chamber), couch, lieth (lying) with.', 'from 7901;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2146}/H9022/[H2142]', 'inflected', 'heb', 'זִכְרוֹן', '["zikrôwn"]', '["memorial/ your"]', '["n-m"]', 'a memento (or memorable thing, day or writing) memorial, record.', 'from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027N}/[H3027]', 'lemma', 'heb', 'יָד', '["yâd"]', '["a hand"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7788}/[H7788]', 'inflected', 'heb', 'שׁוּר', '["shûwr"]', '["and/ you journeyed"]', '["v"]', 'properly, to turn, i.e. travel about (as a harlot or a merchant) go, singular See also 7891.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7547}/H9022/[H7543]', 'inflected', 'heb', 'רַקֻּחַ', '["raqquach"]', '["perfumes/ your"]', '["n-m"]', 'a scented substance perfume.', 'from 7543;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6735A}/H9022/[H6696]', 'inflected', 'heb', 'צִיר', '["tsîyr"]', '["envoys/ your"]', '["n-m"]', 'a hinge (as pressed in turning); also a throe (as a phys. or mental pressure); also a herald or errand-doer (as constrained by the principal) ambassador, hinge, messenger, pain, pang, sorrow. Compare 6736.', 'from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870L}/H9022/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["conduct/ your","journey/ your","way/ your"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027H}/H9022/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5769J}/[H5956]', 'inflected', 'heb', 'עוֹלָם', '["ʻôwlâm"]', '["and/ from/ long ago"]', '["n-m"]', 'properly, concealed, i.e. the vanishing point; generally, time out of mind (past or future), i.e. (practically) eternity; frequentatively, adverbial (especially with prepositional prefix) always alway(-s), ancient (time), any more, continuance, eternal, (for, (n-)) ever(-lasting, -more, of old), lasting, long (time), (of) old (time), perpetual, at any time, (beginning of the) world ( without end). Compare 5331, 5703.', 'or עֹלָם; from 5956;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6666}/H9022/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["righteousness/ your"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4639K}/H9022/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["deeds/ your"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3276}/H9032/[H3276]', 'inflected', 'heb', 'יָעַל', '["yâʻal"]', '["they will benefit/ you"]', '["v"]', 'properly, to ascend; figuratively, to be valuable (objectively; useful, subjectively; benefited) × at all, set forward, can do good, (be, have) profit, (able).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2199}/H9042/[H2199]', 'inflected', 'heb', 'זָעַק', '["zâʻaq"]', '["when/ cry out/ you"]', '["v"]', 'to shriek (from anguish or danger); by analogy, (as a herald) to announce or convene publicly assemble, call (together), (make a) cry (out), come with such a company, gather (together), cause to be proclaimed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5337}/H9032/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["let them deliver/ you"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6899}/H9022/[H6908]', 'inflected', 'heb', 'קִבּוּץ', '["qibbûwts"]', '["collection<s>/ your"]', '["n-m"]', 'a throng company.', 'from 6908;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2620}/[H982]', 'inflected', 'heb', 'חָסָה', '["châçâh"]', '["and/ the/ [one who] takes refuge"]', '["v"]', 'to flee for protection; figuratively, to confide in have hope, make refuge, (put) trust.', 'a primitive root; (compare 982)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3423G}/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["so/ he may possess"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5971A}/H9020\/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["people/ my"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1215}/H9023/[H1214]', 'inflected', 'heb', 'בֶּצַע', '["betsaʻ"]', '["unjust gain/ his"]', '["n-m"]', 'plunder; by extension, gain (usually unjust) covetousness, (dishonest) gain, lucre, profit.', 'from 1214;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5221}/H9033/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["and/ I struck/ him","and/ let us attack/ him"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7107}/[H7107]', 'inflected', 'heb', 'קָצַף', '["qâtsaph"]', '["and/ I may be angry"]', '["v"]', 'to crack off, i.e. (figuratively) burst out in rage (be) anger(-ry), displease, fret self, (provoke to) wrath (come), be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7726}/[H7725]', 'lemma', 'heb', 'שׁוֹבָב', '["shôwbâb"]', '["apostate","backsliding"]', '["a"]', 'apostate, i.e. idolatrous backsliding, frowardly, turn away (from margin).', 'from 7725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7495}/H9033/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["and/ I will heal/ him"]', '["v"]', 'properly, to mend (by stitching), i.e. (figuratively) to cure cure, (cause to) heal, physician, repair, × thoroughly, make whole. See 7503.', 'or רָפָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5148}/H9033/[H5148]', 'inflected', 'heb', 'נָחָה', '["nâchâh"]', '["and/ I will lead/ him"]', '["v"]', 'to guide; by implication, to transport (into exile, or as colonists) bestow, bring, govern, guide, lead (forth), put, straiten.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5150}/[H5162]', 'lemma', 'heb', 'נִחוּם', '["nichûwm"]', '["comfort<s>"]', '["n-m"]', 'properly, consoled; abstractly, solace comfort(-able), repenting.', 'or נִחֻם; from 5162;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0057}/H9023/[H56]', 'inflected', 'heb', 'אָבֵל', '["ʼâbêl"]', '["and/ to/ mourners/ his"]', '["a"]', 'lamenting mourn(-er, -ing).', 'from 56;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5108B}/[H5107]', 'lemma', 'heb', 'נוֹב', '["nôwb"]', '["[the] fruit"]', '["n-m"]', 'produce, literally or figuratively fruit.', 'or נֵיב; from 5107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7350}/[H7368]', 'inflected', 'heb', 'רָחוֹק', '["râchôwq"]', '["to <the>/ distant [person]"]', '["a"]', 'remote, literally or figuratively, of place or time; specifically, precious; often used adverbially (with preposition) (a-) far (abroad, off), long ago, of old, space, great while to come.', 'or רָחֹק; from 7368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7138}/[H7126]', 'inflected', 'heb', 'קָרוֹב', '["qârôwb"]', '["and/ to <the>/ near [person]"]', '["a"]', 'near (in place, kindred or time) allied, approach, at hand, any of kin, kinsfold(-sman), (that is) near (of kin), neighbour, (that is) next, (them that come) nigh (at hand), more ready, short(-ly).', 'or קָרֹב; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7495}/H9033/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["and/ I will heal/ him"]', '["v"]', 'properly, to mend (by stitching), i.e. (figuratively) to cure cure, (cause to) heal, physician, repair, × thoroughly, make whole. See 7503.', 'or רָפָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7563}/[H7561]', 'inflected', 'heb', 'רָשָׁע', '["râshâʻ"]', '["and/ the/ wicked [people]","and/ the/ wicked [person]"]', '["a"]', 'morally wrong; concretely, an (actively) bad person condemned, guilty, ungodly, wicked (man), that did wrong.', 'from 7561;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H3220G>', 'inflected', 'heb', 'כים', '["ka/i.Yam"]', '["[are] like the/ sea","[is] like the/ sea","[will be] like the/ sea","like the/ sea"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7516}/[H7515]', 'lemma', 'heb', 'רֶפֶשׁ', '["rephesh"]', '["mire"]', '["n-m"]', 'mud (as roiled) mire.', 'from 7515;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H2916>', 'inflected', 'heb', 'וטיט', '["va./Tit"]', '["and/ mud"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1627}/[H1641]', 'inflected', 'heb', 'גָּרוֹן', '["gârôwn"]', '["with/ a throat"]', '["n-m"]', 'the throat (as roughened by swallowing) × aloud, mouth, neck, throat.', 'or (shortened) גָּרֹן; from 1641; (compare 1621)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7782}/[H8231]', 'inflected', 'heb', 'שׁוֹפָר', '["shôwphâr"]', '["like <the>/ trumpet"]', '["n-m"]', 'a cornet (as giving a clear sound) or curved horn cornet, trumpet.', 'or שֹׁפָר; from 8231 in the original sense of incising;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1875}/H9013/[H1875]', 'inflected', 'heb', 'דָּרַשׁ', '["dârash"]', '["they seek/ !"]', '["v"]', 'properly, to tread or frequent; usually to follow (for pursuit or search); by implication, to seek or ask; specifically to worship ask, × at all, care for, × diligently, inquire, make inquisition, (necro-) mancer, question, require, search, seek (for, out), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2654A}/H9013/[H2654]', 'inflected', 'heb', 'חָפֵץ', '["châphêts"]', '["they desire/ !"]', '["v"]', 'properly, to incline to; by implication (literally but rarely) to bend; figuratively, to be pleased with, desire × any at all, (have, take) delight, desire, favour, like, move, be (well) pleased, have pleasure, will, would.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6685}/H9026/[H6684]', 'inflected', 'heb', 'צוֹם', '["tsôwm"]', '["fasting/ your"]', '["n-m"]', 'a fast fast(-ing).', 'or צֹם; from 6684;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6092}/H9026/[H6087]', 'inflected', 'heb', 'עָצֵב', '["ʻâtsêb"]', '["laborers/ your"]', '["n-m"]', 'a (hired) workman labour.', 'from 6087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4683}/[H5327]', 'inflected', 'heb', 'מַצָּה', '["matstsâh"]', '["and/ contention"]', '["n-f"]', 'a quarrel contention, debate, strife.', 'from 5327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5221}/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["and/ to/ strike"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9004/{H2088}/[H2088]', 'inflected', 'heb', 'זֶה', '["zeh"]', '["¿/ like/ this"]', '["d"]', 'the masculine demonstrative pronoun, this or that he, × hence, × here, it(-self), × now, × of him, the one...the other, × than the other, (× out of) the (self) same, such (a one) that, these, this (hath, man), on this side...on that side, × thus, very, which. Compare 2063, 2090, 2097, 2098.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0977}/H9033/[H977]', 'inflected', 'heb', 'בָּחַר', '["bâchar"]', '["[which] I choose/ it"]', '["v"]', 'properly, to try, i.e. (by implication) select acceptable, appoint, choose (choice), excellent, join, be rather, require.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9005/{H3721}/[H3721]', 'inflected', 'heb', 'כָּפַף', '["kâphaph"]', '["¿/ to/ bend down"]', '["v"]', 'to curve bow down (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0100}/[H98]', 'inflected', 'heb', 'אַגְמוֹן', '["ʼagmôwn"]', '["like/ a bulrush"]', '["n-m"]', 'a rush (as growing there); collectively a rope of rushes bulrush, caldron, hook, rush.', 'from the same as 98; a marshy pool (others from a different root, a kettle); by implication');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9005/{H2088}/[H2088]', 'inflected', 'heb', 'זֶה', '["zeh"]', '["¿/ <the> <to>/ this"]', '["d"]', 'the masculine demonstrative pronoun, this or that he, × hence, × here, it(-self), × now, × of him, the one...the other, × than the other, (× out of) the (self) same, such (a one) that, these, this (hath, man), on this side...on that side, × thus, very, which. Compare 2063, 2090, 2097, 2098.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4788}/[H7300]', 'lemma', 'heb', 'מָרוּד', '["mârûwd"]', '["homeless people"]', '["n-m"]', 'an outcast; (abstractly) destitution cast out, misery.', 'from 7300 in the sense of maltreatment;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1320}/H9021/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["and/ from/ own flesh/ your"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7837}/[H7836]', 'inflected', 'heb', 'שַׁחַר', '["shachar"]', '["like the/ dawn","like/ [the] dawn"]', '["n-m"]', 'dawn (literal, figurative or adverbial) day(-spring), early, light, morning, whence riseth.', 'from 7836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0724}/H9021/[H748]', 'inflected', 'heb', 'אֲרוּכָה', '["ʼărûwkâh"]', '["and/ healing/ your"]', '["n-f"]', 'wholeness (literally or figuratively) health, made up, perfected.', 'or אֲרֻכָה; feminine passive participle of 748 (in the sense of restoring to soundness);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H8432>/H9021', 'inflected', 'heb', 'מתוכך', '["mi./tokh./Kha"]', '["from/ [the] midst of/ you","from/ among/ you"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6329}/[H6328]', 'inflected', 'heb', 'פּוּק', '["pûwq"]', '["and/ you will offer"]', '["v"]', 'to issue, i.e. furnish; causatively, to secure; figuratively, to succeed afford, draw out, further, get, obtain.', 'a primitive root [rather identical with 6328 through the idea of dropping out; compare 5312];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0653}/H9021/[H651]', 'inflected', 'heb', 'אֲפֵלָה', '["ʼăphêlâh"]', '["and/ gloom/ your"]', '["n-f"]', 'duskiness, figuratively, misfortune; concrete, concealment dark, darkness, gloominess, × thick.', 'feminine of 651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5148}/H9031/[H5148]', 'inflected', 'heb', 'נָחָה', '["nâchâh"]', '["and/ he will lead/ you"]', '["v"]', 'to guide; by implication, to transport (into exile, or as colonists) bestow, bring, govern, guide, lead (forth), put, straiten.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6710}/[H6705]', 'inflected', 'heb', 'צַחְצָחָה', '["tsachtsâchâh"]', '["in/ arid regions"]', '["n-f"]', 'a dry place, i.e. desert drought.', 'from 6705;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6106G}/H9021/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["and/ bones/ your"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7302}/[H7301]', 'lemma', 'heb', 'רָוֶה', '["râveh"]', '["watered"]', '["a"]', 'sated (with drink) drunkenness, watered.', 'from 7301;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H4161}/[H3318]', 'inflected', 'heb', 'מוֹצָא', '["môwtsâʼ"]', '["and/ like/ a spring of"]', '["n-m"]', 'a going forth, i.e. (the act) an egress, or (the place) an exit; hence, a source or product; specifically, dawn, the rising of the sun (the East), exportation, utterance, a gate, a fountain, a mine, a meadow (as producing grass) brought out, bud, that which came out, east, going forth, goings out, that which (thing that) is gone out, outgoing, proceeded out, spring, vein, (water-) course (springs).', 'or מֹצָאxlit môtsâ corrected to môtsâʼ; from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7676}/[H7673]', 'inflected', 'heb', 'שַׁבָּת', '["shabbâth"]', '["from/ [the] sabbath"]', '["n"]', 'intermission, i.e (specifically) the Sabbath ( every) sabbath.', 'intensive from 7673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6918G}/[H6942]', 'inflected', 'heb', 'קָדוֹשׁ', '["qâdôwsh"]', '["<to>/ [the] holy [day] of"]', '["a"]', 'sacred (ceremonially or morally); (as noun) God (by eminence), an angel, a saint, a sanctuary holy (One), saint.', 'or קָדֹשׁ; from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3513G}/H9033/[H3513]', 'inflected', 'heb', 'כָּבַד', '["kâbad"]', '["and/ you will honor/ it"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4672}/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["from/ finding"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7392}/H9031/[H7392]', 'inflected', 'heb', 'רָכַב', '["râkab"]', '["and/ I will make ride/ you"]', '["v"]', 'to ride (on an animal or in a vehicle); causatively, to place upon (for riding or generally), to despatch bring (on (horse-) back), carry, get (oneself) up, on (horse-) back, put, (cause to, make to) ride (in a chariot, on, -r), set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3467}/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["for/ saving"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0996G}/[H995]', 'inflected', 'heb', 'בֵּין', '["bêyn"]', '["and/ between"]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2403B}/H9026/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["and/ sins/ your"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1351}/[H1350]', 'lemma', 'heb', 'גָּאַל', '["gâʼal"]', '["I have defiled","[is] defiled","defiled","he defiled himself","he will defile himself","they are defiled","they were defiled"]', '["v"]', 'to soil or (figuratively) desecrate defile, pollute, stain.', 'a primitive root, (rather identified with 1350, through the idea of freeing, i.e. repudiating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0676}/H9026/[H6648]', 'inflected', 'heb', 'אֶצְבַּע', '["ʼetsbaʻ"]', '["and/ fingers/ your"]', '["n-f"]', 'something to sieze with, i.e. a finger; by analogy, a toe finger, toe.', 'from the same as 6648 (in the sense of grasping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8193G}/H9026/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["lips/ your"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3956G}/H9026/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["tongue/ your"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6980}/[H6979]', 'inflected', 'heb', 'קוּר', '["qûwr"]', '["and/ webs of"]', '["n-m"]', '(only plural) trenches, i.e. a web (as if so formed) web.', 'from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1000}/H9028/[H948]', 'inflected', 'heb', 'בֵּיצָה', '["bêytsâh"]', '["any of/ eggs/ their"]', '["n-f"]', 'an egg (from its whiteness) egg.', 'from the same as 948;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2116}/[H2115]', 'inflected', 'heb', 'זוּרֶה', '["zûwreh"]', '["and/ the/ pressed [egg]"]', '["n-m"]', 'trodden on that which is crushed.', 'from 2115;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6980}/H9028/[H6979]', 'inflected', 'heb', 'קוּר', '["qûwr"]', '["webs/ their"]', '["n-m"]', '(only plural) trenches, i.e. a web (as if so formed) web.', 'from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0899B}/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["<into>/ clothing"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4639G}/H9028/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["with/ products/ their"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4639G}/H9028/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["products/ their"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3709G}/H9028/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["[is] in/ hands/ their","[is] in/ palms/ their"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4546}/H9028/[H5549]', 'inflected', 'heb', 'מְסִלָּה', '["mᵉçillâh"]', '["[are] on/ highways/ their"]', '["n-f"]', 'a thoroughfare (as turnpiked), literally or figuratively; specifically a viaduct, a staircase causeway, course, highway, path, terrace.', 'from 5549;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5410B>/H9028', 'opaque', 'heb', 'נָתִיב', '["nâthîyb"]', '["paths/ their"]', '["n-m"]', 'a (beaten) track path(-way), × travel(-ler), way.', 'or (feminine) נְתִיבָה; or נְתִבָה; (Jeremiah 6:16), from an unused root meaning to tramp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6140}/[H6140]', 'lemma', 'heb', 'עָקַשׁ', '["ʻâqash"]', '["they have made crooked","they make crooked"]', '["v"]', 'to knot or distort; figuratively, to pervert (act or declare perverse) make crooked, (prove, that is) perverse(-rt).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5381}/H9035/[H5381]', 'inflected', 'heb', 'נָשַׂג', '["nâsag"]', '["it reaches/ us"]', '["v"]', 'to reach (literally or figuratively) ability, be able, attain (unto), (be able to, can) get, lay at, put, reach, remove, wax rich, × surely, (over-) take (hold of, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5054}/[H5051]', 'inflected', 'heb', 'נְגֹהָה', '["nᵉgôhâh"]', '["for/ gleams of light"]', '["n-f"]', 'splendor brightness.', 'feminine of 5051;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1659}/[H1659]', 'lemma', 'heb', 'גָּשַׁשׁ', '["gâshash"]', '["we grope","we grope for"]', '["v"]', 'to feel about grope.', 'a primitive root; apparently');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5787}/[H5786]', 'inflected', 'heb', 'עִוֵּר', '["ʻivvêr"]', '["like <the>/ blind [people]"]', '["a"]', 'blind (literally or figuratively) blind (men, people).', 'intensive from 5786;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0369}/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["and/ like/ there not"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5399}/[H5398]', 'inflected', 'heb', 'נֶשֶׁף', '["nesheph"]', '["like the/ twilight"]', '["n-m"]', 'properly, a breeze, i.e. (by implication) dusk (when the evening breeze prevails) dark, dawning of the day (morning), night, twilight.', 'from 5398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0820}/[H8081]', 'inflected', 'heb', 'אַשְׁמָן', '["ʼashmân"]', '["among the/ fat people"]', '["n-m"]', 'a fat field desolate place.', 'probably from 8081;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H3123}/[H3196]', 'inflected', 'heb', 'יוֹנָה', '["yôwnâh"]', '["and/ like <the>/ doves","and/ like/ a dove"]', '["n-f"]', 'a dove (apparently from the warmth of their mating) dove, pigeon.', 'probably from the same as 3196;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2403B}/H9025/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["and/ sins/ our"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5771G}/H9025/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["and/ iniquities/ our"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5253}/[H5253]', 'inflected', 'heb', 'נָסַג', '["nâçag"]', '["and/ we have turned back","and/ you will carry away"]', '["v"]', 'to retreat departing away, remove, take (hold), turn away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5627}/[H5493]', 'inflected', 'heb', 'סָרָה', '["çârâh"]', '["and/ rebellion"]', '["n-f"]', 'apostasy, crime; figuratively, remission × continual, rebellion, revolt(-ed), turn away, wrong.', 'from 5493;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1897}/[H1901]', 'inflected', 'heb', 'הָגָה', '["hâgâh"]', '["and/ we have uttered"]', '["v"]', 'to murmur (in pleasure or anger); by implication, to ponder imagine, meditate, mourn, mutter, roar, × sore, speak, study, talk, utter.', 'a primitive root (compare 1901);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5253}/[H5253]', 'inflected', 'heb', 'נָסַג', '["nâçag"]', '["and/ it has been driven back"]', '["v"]', 'to retreat departing away, remove, take (hold), turn away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5229}/[H5228]', 'inflected', 'heb', 'נְכֹחָה', '["nᵉkôchâh"]', '["and/ honesty"]', '["a-f"]', 'properly, straightforwardness, i.e. (figuratively) integrity, or (concretely) a truth equity, right (thing), uprightness.', 'feminine of 5228;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0571H}/[H539]', 'inflected', 'heb', 'אֶמֶת', '["ʼemeth"]', '["<the>/ truth"]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8302B}/[H8281]', 'inflected', 'heb', 'שִׁרְיוֹן', '["shiryôwn"]', '["like <the>/ body armor"]', '["n-m n-f"]', 'a corslet (as if twisted) breastplate, coat of mail, habergeon, harness. See 5630.', 'or שִׁרְיֹן; and שִׁרְיָן; also (feminine) שִׁרְיָה; and שִׁרְיֹנָה; from 8281 in the original sense of turning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8516}/[H3847]', 'lemma', 'heb', 'תַּלְבֹּשֶׁת', '["talbôsheth"]', '["clothing"]', '["n-f"]', 'a garment clothing.', 'from 3847;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5844A}/[H5844]', 'inflected', 'heb', 'עָטָה', '["ʻâṭâh"]', '["and/ he will delouse","and/ he wrapped himself","and/ they will cover"]', '["v"]', 'to wrap, i.e. cover, veil, clothe, or roll array self, be clad, (put a) cover (-ing, self), fill, put on, × surely, turn aside.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1578}/[H1576]', 'lemma', 'heb', 'גְּמוּלָה', '["gᵉmûwlâh"]', '["deeds","recompense<s>"]', '["n-f"]', 'meaning the same deed, recompense, such a reward.', 'feminine of 1576;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0341}/H9023/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["to/ enemies/ his"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4217H}/[H2224]', 'inflected', 'heb', 'מִזְרָח', '["mizrâch"]', '["and/ from/ [the] rising of"]', '["n-m"]', 'sunrise, i.e. the east east (side, -ward), (sun-) rising (of the sun).', 'from 2224;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7725O}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ to/ [those who] repent of"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6310G}/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["and/ from/ [the] mouth of"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0216}/H9022/[H215]', 'inflected', 'heb', 'אוֹר', '["ʼôwr"]', '["light/ your"]', '["n-f"]', 'illumination or (concrete) luminary (in every sense, including lightning, happiness, etc.) bright, clear, day, light (-ning), morning, sun.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5921A}/H9032/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["and/ on/ you"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0216}/H9022/[H215]', 'inflected', 'heb', 'אוֹר', '["ʼôwr"]', '["to/ light/ your"]', '["n-f"]', 'illumination or (concrete) luminary (in every sense, including lightning, happiness, etc.) bright, clear, day, light (-ning), morning, sun.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5051}/[H5050]', 'inflected', 'heb', 'נֹגַהּ', '["nôgahh"]', '["to/ [the] brightness of","to/ brightness"]', '["n-f"]', 'brilliancy (literally or figuratively) bright(-ness), light, (clear) shining.', 'from 5050;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2225}/H9022/[H2224]', 'inflected', 'heb', 'זֶרַח', '["zerach"]', '["dawn/ your"]', '["n-m"]', 'a rising of light rising.', 'from 2224;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3680}/H9032/[H3680]', 'inflected', 'heb', 'כָּסָה', '["kâçâh"]', '["it will cover/ you"]', '["v"]', 'properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1070}/[H1069]', 'lemma', 'heb', 'בֶּכֶר', '["beker"]', '["[the] young camels of"]', '["n-m"]', 'a young camel dromedary.', 'from 1069 (in the sense of youth);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5891J}/[H5890]', 'inflected', 'heb', 'עֵיפָה', '["ʻÊyphâh"]', '["and/ Ephah"]', '["n-pr-m n-pr-f"]', 'Ephah, the name of a son of Midian, and of the region settled by him; also of an Israelite and of an Israelitess Ephah.', 'the same as 5890;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H7614J>', 'inflected', 'heb', 'משבא', '["mi./she.Va''"]', '["[which] from/ Sheba","from/ Sheba"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8334}/H9032/[H8334]', 'inflected', 'heb', 'שָׁרַת', '["shârath"]', '["they will serve/ you"]', '["v"]', 'to attend as a menial or worshipper; figuratively, to contribute to minister (unto), (do) serve(-ant, -ice, -itor), wait on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1004Q}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ [the] house of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8597}/H9020/[H6286]', 'inflected', 'heb', 'תִּפְאָרָה', '["tiphʼârâh"]', '["splendor/ my"]', '["n-f"]', 'ornament (abstractly or concretely, literally or figuratively) beauty(-iful), bravery, comely, fair, glory(-ious), honour, majesty.', 'or תִּפְאֶרֶת; from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0699}/H9028/[H693]', 'inflected', 'heb', 'אֲרֻבָּה', '["ʼărubbâh"]', '["openings/ their"]', '["n-f"]', 'a lattice; (by implication) a window, dovecot (because of the pigeon-holes), chimney (with its apertures for smoke), sluice (with openings for water) chimney, window.', 'feminine participle passive of 693 (as if for lurking);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0591}/[H590]', 'inflected', 'heb', 'אֳנִיָּה', '["ʼŏnîyâh"]', '["and/ [the] ships of"]', '["n-f"]', 'a ship ship(-men).', 'feminine of 590;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H2091>/H9028', 'inflected', 'heb', 'וזהבם', '["u./ze.ha.Va/m"]', '["and/ gold/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6286A}/H9031/[H6288]', 'inflected', 'heb', 'פָּאַר', '["pâʼar"]', '["he has glorified/ you"]', '["v"]', 'to gleam, i.e. (causatively) embellish; figuratively, to boast; also to explain (i.e. make clear) oneself; to shake a tree beautify, boast self, go over the boughs, glorify (self), glory, vaunt self.', 'a primitive root; also denominative from 6288,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4428G}/H9028/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["and/ kings/ their"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7110A}/H9020/[H7107]', 'inflected', 'heb', 'קֶצֶף', '["qetseph"]', '["in/ wrath/ my"]', '["n-m"]', 'a splinter (as chipped off); figuratively, rage or strife foam, indignation, × sore, wrath.', 'from 7107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7522}/H9020/[H7521]', 'inflected', 'heb', 'רָצוֹן', '["râtsôwn"]', '["and/ in/ favor/ my"]', '["n-m"]', 'delight (especially as shown) (be) acceptable(-ance, -ed), delight, desire, favour, (good) pleasure, (own, self, voluntary) will, as...(what) would.', 'or רָצֹן; from 7521;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5647G}/H9032/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["they will serve/ you"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1471A}/[H1465]', 'inflected', 'heb', 'גּוֹי', '["gôwy"]', '["and/ the/ nation","and/ the/ nations"]', '["n-m n-pr-m"]', 'a foreign nation; hence, a Gentile; also (figuratively) a troop of animals, or a flight of locusts Gentile, heathen, nation, people.', 'rarely (shortened) גֹּי; apparently from the same root as 1465 (in the sense of massing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6031B}/H9032/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["[those who] afflicted/ you"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5006}/H9032/[H5006]', 'inflected', 'heb', 'נָאַץ', '["nâʼats"]', '["[those who] despised/ you"]', '["v"]', 'to scorn; or (in Ecclesiastes 12:5), by interchange for 5132, to bloom abhor, (give occasion to) blaspheme, contemn, despise, flourish, × great, provoke.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5892I}/[H5782]', 'lemma', 'heb', 'עִיר', '["ʻîyr"]', '["[the] city of"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3068I}/[H1961]', 'lemma', 'heb', 'יְהֹוָה', '["Yᵉhôvâh"]', '["Yahweh"]', '["n-pr"]', '(the) self-Existent or Eternal; Jeho-vah, Jewish national name of God Jehovah, the Lord. Compare 3050, 3069.', 'from 1961;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1961}/H9042/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["being/ you"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7760A}/H9032/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ I will make/ you"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3243G}/[H3243]', 'inflected', 'heb', 'יָנַק', '["yânaq"]', '["and/ you will suck"]', '["v"]', 'to suck; causatively, to give milk milch, nurse(-ing mother), (give, make to) suck(-ing child, -ling).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7699B}/[H7736]', 'inflected', 'heb', 'שַׁד', '["shad"]', '["and/ [the] breast of"]', '["n-m"]', 'the breast of a woman or animal (as bulging) breast, pap, teat.', 'or שֹׁד; probably from 7736 (in its original sense) contracted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6486}/H9022/[H6485]', 'inflected', 'heb', 'פְּקֻדָּה', '["pᵉquddâh"]', '["overseer[s]/ your"]', '["n-f"]', 'visitation (in many senses, chiefly official) account, (that have the) charge, custody, that which...laid up, numbers, office(-r), ordering, oversight, prison, reckoning, visitation.', 'feminine passive participle of 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5065}/H9032/[H5065]', 'inflected', 'heb', 'נָגַשׂ', '["nâgas"]', '["and/ taskmasters/ your"]', '["v"]', 'to drive (an animal, a workman, a debtor, an army); by implication, to tax, harass, tyrannize distress, driver, exact(-or), oppress(-or), × raiser of taxes, taskmaster.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0776G>/H9022', 'inflected', 'heb', 'בארצך', '["be./''ar.Tze/kh"]', '["in/ land/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1366G}/H9022/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["in/ territories/ your"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5051}/[H5050]', 'inflected', 'heb', 'נֹגַהּ', '["nôgahh"]', '["and/ for/ brightness"]', '["n-f"]', 'brilliancy (literally or figuratively) bright(-ness), light, (clear) shining.', 'from 5050;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8597}/H9022/[H6286]', 'inflected', 'heb', 'תִּפְאָרָה', '["tiphʼârâh"]', '["<into>/ splendor/ your"]', '["n-f"]', 'ornament (abstractly or concretely, literally or figuratively) beauty(-iful), bravery, comely, fair, glory(-ious), honour, majesty.', 'or תִּפְאֶרֶת; from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3394}/H9022/[H3391]', 'inflected', 'heb', 'יָרֵחַ', '["yârêach"]', '["and/ moon/ your"]', '["n-m"]', 'the moon moon. Yrechow. See 3405.', 'from the same as 3391;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0060}/H9022/[H56]', 'inflected', 'heb', 'אֵבֶל', '["ʼêbel"]', '["mourning/ your"]', '["n-m"]', 'lamentation mourning.', 'from 56;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5971A}/H9022/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["and/ people/ your"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5342}/[H5341]', 'lemma', 'heb', 'נֵצֶר', '["nêtser"]', '["[the] shoot of"]', '["n-m"]', 'a shoot; figuratively, a descendant branch.', 'from 5341 in the sense of greenness as a striking color;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4302}/H9020/[H5193]', 'inflected', 'heb', 'מַטָּע', '["maṭṭâʻ"]', '["planting<s>/ my"]', '["n-m"]', 'something planted, i.e. the place (a garden or vineyard), or the thing (a plant, figuratively or men); by implication, the act, planting plant(-ation, -ing).', 'from 5193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6256}/H9024/[H5703]', 'inflected', 'heb', 'עֵת', '["ʻêth"]', '["at/ appropriate time/ its"]', '["n-f"]', 'time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when.', 'from 5703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2363A}/H9034\/[H2363]', 'inflected', 'heb', 'חוּשׁ', '["chûwsh"]', '["I will hasten/ it"]', '["v"]', 'to hurry; figuratively, to be eager with excitement or enjoyment (make) haste(-n), ready.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2280}/[H2280]', 'inflected', 'heb', 'חָבַשׁ', '["châbash"]', '["to/ bind up"]', '["v"]', 'to wrap firmly (especially a turban, compress, or saddle); figuratively, to stop, to rule bind (up), gird about, govern, healer, put, saddle, wrap about.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7617}/[H7617]', 'inflected', 'heb', 'שָׁבָה', '["shâbâh"]', '["to/ captives"]', '["v"]', 'to transport into captivity (bring away, carry, carry away, lead, lead away, take) captive(-s), drive (take) away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0631}/[H631]', 'inflected', 'heb', 'אָסַר', '["ʼâçar"]', '["and/ to/ prisoners"]', '["v"]', 'to yoke or hitch; by analogy, to fasten in any sense, to join battle bind, fast, gird, harness, hold, keep, make ready, order, prepare, prison(-er), put in bonds, set in array, tie.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6495}/[H6491]', 'lemma', 'heb', 'פְּקַח־קוֹחַ', '["pᵉqach-qôwach"]', '["-lease","re-"]', '["n-m"]', 'opening (of a dungeon), i.e. jail-delivery (figuratively, salvation for sin) opening of the prison.', 'from 6491 redoubled;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0057}/[H56]', 'inflected', 'heb', 'אָבֵל', '["ʼâbêl"]', '["to/ [the] mourners of"]', '["a"]', 'lamenting mourn(-er, -ing).', 'from 56;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4594}/[H5844]', 'lemma', 'heb', 'מַעֲטֶה', '["maʻăṭeh"]', '["a mantle of"]', '["n-m"]', 'a vestment garment.', 'from 5844;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0352D}/[H193]', 'lemma', 'heb', 'אַיִל', '["ʼayil"]', '["[the] oaks of"]', '["n-m"]', 'properly, strength; hence, anything strong; specifically a chief (politically); also a ram (from his strength); a pilaster (as a strong support); an oak or other strong tree mighty (man), lintel, oak, post, ram, tree.', 'from the same as 193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4302}/[H5193]', 'lemma', 'heb', 'מַטָּע', '["maṭṭâʻ"]', '["[the] planting of","a planting place"]', '["n-m"]', 'something planted, i.e. the place (a garden or vineyard), or the thing (a plant, figuratively or men); by implication, the act, planting plant(-ation, -ing).', 'from 5193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2721B}/[H2719]', 'lemma', 'heb', 'חֹרֶב', '["chôreb"]', '["desolation","destruction","devastation"]', '["n-m"]', 'drought or desolation desolation, drought, dry, heat, × utterly, waste.', 'a collaterally form of 2719;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0406>/H9026', 'opaque', 'heb', 'אִכָּר', '["ʼikkâr"]', '["[will be] farmers/ your"]', '["n-m"]', 'a farmer husbandman, ploughman.', 'from an unused root meaning to dig;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3755}/H9026/[H3754]', 'inflected', 'heb', 'כֹּרֵם', '["kôrêm"]', '["and/ vinedressers/ your"]', '["v"]', 'a vinedresser vine dresser (as one or two words).', 'active participle of an imaginary denominative from 3754;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3519}/H9028/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["and/ in/ abundance/ their"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3235}/[H3235]', 'lemma', 'heb', 'יָמַר', '["yâmar"]', '["you will boast"]', '["v"]', 'to exchange; by implication, to change places boast selves, change.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1322}/H9026/[H954]', 'inflected', 'heb', 'בֹּשֶׁת', '["bôsheth"]', '["shame/ your"]', '["n-f"]', 'shame (the feeling and the condition, as well as its cause); by implication (specifically) an idol ashamed, confusion, greatly, (put to) shame(-ful thing).', 'from 954;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1498}/[H1497]', 'lemma', 'heb', 'גָּזֵל', '["gâzêl"]', '["robbery","robbery of"]', '["n-m"]', 'robbery, or (concretely) plunder robbery, thing taken away by violence.', 'from 1497;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6468}/H9028/[H6466]', 'inflected', 'heb', 'פְּעֻלָּה', '["pᵉʻullâh"]', '["recompense/ their","work/ their"]', '["n-f"]', '(abstractly) work labour, reward, wages, work.', 'feminine passive participle of 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5234A}/H9038/[H5234]', 'inflected', 'heb', 'נָכַר', '["nâkar"]', '["they will recognize/ them"]', '["v"]', 'properly, to scrutinize, i.e. look intently at; hence (with recognition implied), to acknowledge, be acquainted with, care for, respect, revere, or (with suspicion implied), to disregard, ignore, be strange toward, reject, resign, dissimulate (as if ignorant or disowning) acknowledge, × could, deliver, discern, dissemble, estrange, feign self to be another, know, take knowledge (notice), perceive, regard, (have) respect, behave (make) self strange(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3271}/H9030/[H3271]', 'inflected', 'heb', 'יָעַט', '["yâʻaṭ"]', '["he has covered/ me"]', '["v"]', 'to clothe cover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H3618G}/[H3634]', 'inflected', 'heb', 'כַּלָּה', '["kallâh"]', '["and/ like <the>/ bride"]', '["n-f"]', 'a bride (as if perfect); hence, a son''s wife bride, daughter-in-law, spouse.', 'from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2221}/H9024/[H2232]', 'inflected', 'heb', 'זֵרוּעַ', '["zêrûwaʻ"]', '["[which] things sown in/ it"]', '["n-m"]', 'something sown, i.e. a plant sowing, thing that is sown.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5051}/[H5050]', 'inflected', 'heb', 'נֹגַהּ', '["nôgahh"]', '["like <the>/ brightness"]', '["n-f"]', 'brilliancy (literally or figuratively) bright(-ness), light, (clear) shining.', 'from 5050;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6664G}/H9024/[H6663]', 'inflected', 'heb', 'צֶדֶק', '["tsedeq"]', '["righteousness/ its"]', '["n-m"]', 'the right (natural, moral or legal); also (abstractly) equity or (figuratively) prosperity × even, (× that which is altogether) just(-ice), (un-)right(-eous) (cause, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3444}/H9024/[H3467]', 'inflected', 'heb', 'יְשׁוּעָה', '["yᵉshûwʻâh"]', '["and/ salvation/ its"]', '["n-f"]', 'something saved, i.e. (abstractly) deliverance; hence, aid, victory, prosperity deliverance, health, help(-ing), salvation, save, saving (health), welfare.', 'feminine passive participle of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H3940>', 'inflected', 'heb', 'כלפידי', '["ke./la.Pi.dei","ke./la.Pid"]', '["[were] like/ torches of","like/ a torch"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6664G}/H9022/[H6663]', 'inflected', 'heb', 'צֶדֶק', '["tsedeq"]', '["righteousness/ your"]', '["n-m"]', 'the right (natural, moral or legal); also (abstractly) equity or (figuratively) prosperity × even, (× that which is altogether) just(-ice), (un-)right(-eous) (cause, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3519}/H9022/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["glory/ your"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5344A}/H9033/[H5344]', 'inflected', 'heb', 'נָקַב', '["nâqab"]', '["it will designate/ it"]', '["v"]', 'to puncture, literally (to perforate, with more or less violence) or figuratively (to specify, designate, libel) appoint, blaspheme, bore, curse, express, with holes, name, pierce, strike through.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5800G}/[H5800]', 'lemma', 'heb', 'עָזַב', '["ʻâzab"]', '["abandoned"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H0776G>/H9022', 'inflected', 'heb', 'ולארצך', '["u./le./''ar.Tze/kh","u./le./''ar.tze/Kh"]', '["and/ of/ land/ your","and/ to/ land/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8077G}/[H8076]', 'lemma', 'heb', 'שְׁמָמָה', '["shᵉmâmâh"]', '["desolation"]', '["n-f"]', 'devastation; figuratively, astonishment (laid, × most) desolate(-ion), waste.', 'or שִׁמָמָה; feminine of 8076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2657H}/[H2656]', 'lemma', 'heb', 'חֶפְצִי בָּהּ', '["Chephtsîy bâhh"]', '["-bah","Hephzi-"]', '["n-pr-f"]', 'Cheptsi-bah, a fanciful name for Palestine Hephzi-bah.', 'from 2656 with suffixes; my delight (is) in her;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1166G}/[H1167]', 'lemma', 'heb', 'בָּעַל', '["bâʻal"]', '["married"]', '["v"]', 'to be master; hence, to marry have dominion (over), be husband, marry(-ried, × wife).', 'a primitive root; also as denominative from 1167');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0776G>/H9022', 'inflected', 'heb', 'וארצך', '["ve./''ar.Tze/kh"]', '["and/ land/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1715}/H9022/[H1711]', 'inflected', 'heb', 'דָּגָן', '["dâgân"]', '["grain/ your"]', '["n-m"]', 'properly, increase, i.e. grain corn (floor), wheat.', 'from 1711;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0341}/H9022/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["to/ enemies/ your"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8492}/H9022/[H3423]', 'inflected', 'heb', 'תִּירוֹשׁ', '["tîyrôwsh"]', '["new wine/ your"]', '["n-m"]', 'must or fresh grape-juice (as just squeezed out); by implication (rarely) fermented wine (new, sweet) wine.', 'or תִּירֹשׁ; from 3423 in the sense of expulsion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0622}/H9033/[H622]', 'inflected', 'heb', 'אָסַף', '["ʼâçaph"]', '["[those who] gather/ it"]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6908}/H9033/[H6908]', 'inflected', 'heb', 'קָבַץ', '["qâbats"]', '["and/ [those who] gather/ it"]', '["v"]', 'to grasp, i.e. collect assemble (selves), gather (bring) (together, selves together, up), heap, resort, × surely, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8354}/H9033/[H8354]', 'inflected', 'heb', 'שָׁתָה', '["shâthâh"]', '["they will drink/ it"]', '["v"]', 'to imbibe (literally or figuratively) × assuredly, banquet, × certainly, drink(-er, -ing), drunk (× -ard), surely. (Prop. intensive of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6944G}/H9020\/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["holiness/ my"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5800A}\/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["it has been forsaken"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2556B}/[H2556]', 'lemma', 'heb', 'חָמֵץ', '["châmêts"]', '["red of"]', '["v"]', 'to be pungent; i.e. in taste (sour, i.e. literally fermented, or figuratively, harsh), in color (dazzling) cruel (man), dyed, be grieved, leavened.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3830}/H9023/[H3847]', 'inflected', 'heb', 'לְבוּשׁ', '["lᵉbûwsh"]', '["in/ clothing/ his"]', '["n-m"]', 'a garment (literally or figuratively); by implication (euphemistically) a wife apparel, clothed with, clothing, garment, raiment, vestment, vesture.', 'or לְבֻשׁ; from 3847;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0899B}/H9021/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["and/ [are] garments?/ your"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1869}/[H1869]', 'inflected', 'heb', 'דָּרַךְ', '["dârak"]', '["like/ [one who] treads","like/ [those who] tread"]', '["v"]', 'to tread; by implication, to walk; also to string a bow (by treading on it in bending) archer, bend, come, draw, go (over), guide, lead (forth), thresh, tread (down), walk.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6333}/[H6331]', 'lemma', 'heb', 'פּוּרָה', '["pûwrâh"]', '["[the] winepress","a winepress"]', '["n-f"]', 'a wine-press (as crushing the grapes) winepress.', 'from 6331;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1869}/H9038/[H1869]', 'inflected', 'heb', 'דָּרַךְ', '["dârak"]', '["and/ I trod/ them"]', '["v"]', 'to tread; by implication, to walk; also to string a bow (by treading on it in bending) archer, bend, come, draw, go (over), guide, lead (forth), thresh, tread (down), walk.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7429}/H9038/[H7429]', 'inflected', 'heb', 'רָמַס', '["râmaç"]', '["and/ I trampled/ them"]', '["v"]', 'to tread upon (as a potter, in walking or abusively) oppressor, stamp upon, trample (under feet), tread (down, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2534}/H9020/[H3179]', 'inflected', 'heb', 'חֵמָה', '["chêmâh"]', '["in/ rage/ my"]', '["n-f"]', 'heat; figuratively, anger, poison (from its fever) anger, bottles, hot displeasure, furious(-ly, -ry), heat, indignation, poison, rage, wrath(-ful). See 2529.', 'or (Daniel 11:44) חֵמָא; from 3179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5332}/H9028/[H5331]', 'inflected', 'heb', 'נֵצַח', '["Nêtsach"]', '["blood/ their"]', '["n-m"]', 'juice of the grape (as blood red) blood, strength.', 'probably identical with 5331, through the idea of brilliancy of color;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4403}/H9020/[H3847]', 'inflected', 'heb', 'מַלְבּוּשׁ', '["malbûwsh"]', '["clothes/ my"]', '["n-m"]', 'a garment, or (collectively) clothing apparel, raiment, vestment.', 'or מַלְבֻּשׁ; from 3847;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1350B}/H9020/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["redemption<s>/ my"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2534}/H9020/[H3179]', 'inflected', 'heb', 'חֵמָה', '["chêmâh"]', '["and/ rage/ my"]', '["n-f"]', 'heat; figuratively, anger, poison (from its fever) anger, bottles, hot displeasure, furious(-ly, -ry), heat, indignation, poison, rage, wrath(-ful). See 2529.', 'or (Daniel 11:44) חֵמָא; from 3179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0947}/[H947]', 'inflected', 'heb', 'בּוּס', '["bûwç"]', '["and/ I may tread down"]', '["v"]', 'to trample (literally or figuratively) loath, tread (down, under (foot)), be polluted.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7937}/H9038/[H7937]', 'inflected', 'heb', 'שָׁכַר', '["shâkar"]', '["and/ I made drunk/ them"]', '["v"]', 'to become tipsy; in a qualified sense, to satiate with a stimulating drink or (figuratively) influence (be filled with) drink (abundantly), (be, make) drunk(-en), be merry. (Superlative of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5332}/H9028\/[H5331]', 'inflected', 'heb', 'נֵצַח', '["Nêtsach"]', '["blood/ their"]', '["n-m"]', 'juice of the grape (as blood red) blood, strength.', 'probably identical with 5331, through the idea of brilliancy of color;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1580}/H9035/[H1580]', 'inflected', 'heb', 'גָּמַל', '["gâmal"]', '["he has dealt out to/ us"]', '["v"]', 'to treat a person (well or ill), i.e. benefit or requite; by implication (of toil), to ripen, i.e. (specifically) to wean bestow on, deal bountifully, do (good), recompense, requite, reward, ripen, serve, mean, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1580}/H9038/[H1580]', 'inflected', 'heb', 'גָּמַל', '["gâmal"]', '["he has dealt out to/ them"]', '["v"]', 'to treat a person (well or ill), i.e. benefit or requite; by implication (of toil), to ripen, i.e. (specifically) to wean bestow on, deal bountifully, do (good), recompense, requite, reward, ripen, serve, mean, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7356B}/H9023/[H7355]', 'inflected', 'heb', 'רַחַם', '["racham"]', '["according to/ compassion<s>/ his"]', '["n-f"]', 'compassion (in the plural); by extension, the womb (as cherishing the fetus); by implication, a maiden bowels, compassion, damsel, tender love, (great, tender) mercy, pity, womb.', 'from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H7230}/[H7231]', 'inflected', 'heb', 'רֹב', '["rôb"]', '["and/ according to/ [the] greatness of"]', '["n-m"]', 'abundance (in any respect) abundance(-antly), all, × common (sort), excellent, great(-ly, -ness, number), huge, be increased, long, many, more in number, most, much, multitude, plenty(-ifully), × very (age).', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2551}/H9023/[H2550]', 'inflected', 'heb', 'חֶמְלָה', '["chemlâh"]', '["and/ in/ mercy/ his"]', '["n-f"]', 'commiseration merciful, pity.', 'from 2550;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5190}/H9038/[H5190]', 'inflected', 'heb', 'נָטַל', '["nâṭal"]', '["and/ he lifted up/ them"]', '["v"]', 'to lift; by implication, to impose bear, offer, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5927G}/H9038/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["[is] who/ brought up/ them"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5117}/H9033/[H5117]', 'inflected', 'heb', 'נוּחַ', '["nûwach"]', '["it gave rest/ it"]', '["v"]', 'to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8597}/H9021/[H6286]', 'inflected', 'heb', 'תִּפְאָרָה', '["tiphʼârâh"]', '["and/ splendor/ your"]', '["n-f"]', 'ornament (abstractly or concretely, literally or figuratively) beauty(-iful), bravery, comely, fair, glory(-ious), honour, majesty.', 'or תִּפְאֶרֶת; from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7356B}/H9021/[H7355]', 'inflected', 'heb', 'רַחַם', '["racham"]', '["and/ compassion<s>/ your"]', '["n-f"]', 'compassion (in the plural); by extension, the womb (as cherishing the fetus); by implication, a maiden bowels, compassion, damsel, tender love, (great, tender) mercy, pity, womb.', 'from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5234A}/H9035/[H5234]', 'inflected', 'heb', 'נָכַר', '["nâkar"]', '["he acknowledges/ us"]', '["v"]', 'properly, to scrutinize, i.e. look intently at; hence (with recognition implied), to acknowledge, be acquainted with, care for, respect, revere, or (with suspicion implied), to disregard, ignore, be strange toward, reject, resign, dissimulate (as if ignorant or disowning) acknowledge, × could, deliver, discern, dissemble, estrange, feign self to be another, know, take knowledge (notice), perceive, regard, (have) respect, behave (make) self strange(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8582}/H9035/[H8582]', 'inflected', 'heb', 'תָּעָה', '["tâʻâh"]', '["do you make wander/ us"]', '["v"]', 'to vacillate, i.e. reel or stray (literally or figuratively); also causative of both (cause to) go astray, deceive, dissemble, (cause to, make to) err, pant, seduce, (make to) stagger, (cause to) wander, be out of the way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1870G}/H9021/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["from/ ways/ your"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3374}/H9021/[H3373]', 'inflected', 'heb', 'יִרְאָה', '["yirʼâh"]', '["from/ fear of/ you"]', '["n-f"]', 'fear (also used as infinitive); morally, reverence × dreadful, × exceedingly, fear(-fulness).', 'feminine of 3373;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4705}/[H6819]', 'inflected', 'heb', 'מִצְעָר', '["mitsʻâr"]', '["for <the>/ little while"]', '["n-m"]', 'petty (in size or number); adverbially, a short (time) little one (while), small.', 'from 6819;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2151A}/[H2107]', 'lemma', 'heb', 'זָלַל', '["zâlal"]', '["they shook"]', '["v"]', 'to shake (as in the wind), i.e. to quake; figuratively, to be loose morally, worthless or prodigal blow down, glutton, riotous (eater), vile.', 'a primitive root (compare 2107);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6919}/[H6919]', 'inflected', 'heb', 'קָדַח', '["qâdach"]', '["as/ kindles"]', '["v"]', 'to inflame burn, kindle.', 'a primitive root to inflame');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2003>', 'opaque', 'heb', 'הָמָס', '["hâmâç"]', '["brushwood<s>"]', '["n-m"]', 'a dry twig or brushwood melting.', 'from an unused root apparently meaning to crackle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6862C}/H9021/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["to/ opponents/ your"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6213A}/H9041/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["when/ doing/ you"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2442}/[H2707]', 'inflected', 'heb', 'חָכָה', '["châkâh"]', '["for/ [one who] waits"]', '["v"]', 'properly, to adhere to; hence, to await long, tarry, wait.', 'a primitive root (apparently akin to 2707 through the idea of piercing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2931}/[H2930]', 'inflected', 'heb', 'טָמֵא', '["ṭâmêʼ"]', '["like <the>/ unclean [person]"]', '["a"]', 'foul in a religious sense defiled, infamous, polluted(-tion), unclean.', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0899B}/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["and/ [are] like/ a garment of"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5708>', 'opaque', 'heb', 'עֵד', '["ʻêd"]', '["menstruation<s>"]', '["n-f"]', 'the menstrual flux (as periodical); by implication (in plural) soiling filthy.', 'from an unused root meaning to set a period (compare 5710, 5749);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6666}/H9025/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["righteousness<es>/ our"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5034B}/[H5034]', 'inflected', 'heb', 'נָבֵל', '["nâbêl"]', '["and/ we have withered"]', '["v"]', 'to wilt; generally, to fall away, fail, faint; figuratively, to be foolish or (morally) wicked; causatively, to despise, disgrace disgrace, dishounour, lightly esteem, fade (away, -ing), fall (down, -ling, off), do foolishly, come to nought, × surely, make vile, wither.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5929}/[H5927]', 'inflected', 'heb', 'עָלֶה', '["ʻâleh"]', '["like <the>/ leafage"]', '["n-m"]', 'a leaf (as coming up on a tree); collectively, foliage branch, leaf.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375H}/H9035/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["they carry off/ us"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4127}/H9035/[H4127]', 'inflected', 'heb', 'מוּג', '["mûwg"]', '["and/ you have melted/ us"]', '["v"]', 'to melt, i.e. literally (to soften, flow down, disappear), or figuratively (to fear, faint) consume, dissolve, (be) faint(-hearted), melt (away), make soft.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2563A}/[H2560]', 'inflected', 'heb', 'חֹמֶר', '["chômer"]', '["[are] the/ clay"]', '["n-m"]', 'properly, a bubbling up, i.e. of water, a wave; of earth, mire or clay (cement); also a heap; hence, a chomer or dry measure clay, heap, homer, mire, motion.', 'from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3335H}/H9035/[H3334]', 'inflected', 'heb', 'יָצַר', '["yâtsar"]', '["[are] [the] [one who] formed/ us"]', '["v"]', 'to mould into a form; especially as a potter; figuratively, to determine (i.e. form a resolution) × earthen, fashion, form, frame, make(-r), potter, purpose.', 'probably identical with 3334 (through the squeezing into shape); (compare 3331);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6944G}/H9025/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["holiness/ our"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8597}/H9025/[H6286]', 'inflected', 'heb', 'תִּפְאָרָה', '["tiphʼârâh"]', '["and/ splendor/ our"]', '["n-f"]', 'ornament (abstractly or concretely, literally or figuratively) beauty(-iful), bravery, comely, fair, glory(-ious), honour, majesty.', 'or תִּפְאֶרֶת; from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4261}/H9025/[H2530]', 'inflected', 'heb', 'מַחְמָד', '["machmâd"]', '["pleasant things/ our"]', '["n-m"]', 'delightful; hence, a delight, i.e. object of affection or desire beloved, desire, goodly, lovely, pleasant (thing).', 'from 2530;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2723}/[H2721]', 'inflected', 'heb', 'חׇרְבָּה', '["chorbâh"]', '["<into>/ a desolation","<into>/ a ruin","<into>/ ruins of","into/ a ruin","to/ [the] ruins of"]', '["n-f"]', 'properly, drought, i.e. (by implication) a desolation decayed place, desolate (place, -tion), destruction, (laid) waste (place).', 'feminine of 2721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6031B}/H9035/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["and/ will you afflict?/ us"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3707}/[H3707]', 'inflected', 'heb', 'כַּעַס', '["kaʻaç"]', '["who/ provoke to anger"]', '["v"]', 'to trouble; by implication, to grieve, rage, be indignant be angry, be grieved, take indignation, provoke (to anger, unto wrath), have sorrow, vex, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1593}/[H1588]', 'inflected', 'heb', 'גַּנָּה', '["gannâh"]', '["in <the>/ gardens"]', '["n-f"]', 'a garden garden.', 'feminine of 1588;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5341}/[H5341]', 'inflected', 'heb', 'נָצַר', '["nâtsar"]', '["and/ in <the>/ secret places"]', '["v"]', 'to guard, in a good sense (to protect, maintain, obey, etc.) or a bad one (to conceal, etc.) besieged, hidden thing, keep(-er, -ing), monument, observe, preserve(-r), subtil, watcher(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4839}/[H4838]', 'inflected', 'heb', 'מָרָק', '["mârâq"]', '["and/ broth of"]', '["n-m"]', 'soup (as if a rinsing) broth. See also 6564.', 'from 4838;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6942G}/H9031/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["I am set apart from/ you"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2436I>/H9028\', 'opaque', 'heb', 'חֵיק', '["chêyq"]', '["bosom/ their"]', '["n-m"]', 'the bosom (literally or figuratively) bosom, bottom, lap, midst, within.', 'or חֵק; and חוֹק; from an unused root, apparently meaning to inclose;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0811}/[H810]', 'inflected', 'heb', 'אֶשְׁכּוֹל', '["ʼeshkôwl"]', '["in the/ cluster of grapes"]', '["n-m"]', 'a bunch of grapes or other fruit cluster (of grapes).', 'or אֶשְׁכֹּל; probably prolonged from 810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6010G}/[H6009]', 'inflected', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["and/ [the] valley of"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7258}/[H7257]', 'inflected', 'heb', 'רֵבֶץ', '["rêbets"]', '["<into>/ a resting place of"]', '["n-m"]', 'a couch or place of repose where each lay, lie down in, resting place.', 'from 7257;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1875}/H9030/[H1875]', 'inflected', 'heb', 'דָּרַשׁ', '["dârash"]', '["seek/ me","they have sought/ me","you will seek/ me"]', '["v"]', 'properly, to tread or frequent; usually to follow (for pursuit or search); by implication, to seek or ask; specifically to worship ask, × at all, care for, × diligently, inquire, make inquisition, (necro-) mancer, question, require, search, seek (for, out), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7913}/[H7911]', 'inflected', 'heb', 'שָׁכֵחַ', '["shâkêach"]', '["<the>/ forgetting"]', '["a"]', 'oblivious forget.', 'from 7911;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1408}/[H1409]', 'inflected', 'heb', 'גַּד', '["Gad"]', '["for <the>/ Fortune"]', '["n-pr-m"]', 'Fortune, a Babylonian deity that troop.', 'a variation of 1409;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4390}/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["and/ who/ fill"]', '["v"]', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly.', 'or מָלָא; (Esther 7:5), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4507}/[H4487]', 'inflected', 'heb', 'מְנִי', '["Mᵉnîy"]', '["for <the>/ Destiny"]', '["n-pr-m"]', 'the Apportioner, i.e. Fate (as an idol) number.', 'from 4487;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3605}/H9026/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["and/ all of/ you"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3511}/[H3510]', 'inflected', 'heb', 'כְּאֵב', '["kᵉʼêb"]', '["from/ pain of"]', '["n-m"]', 'suffering (physical or mental), adversity grief, pain, sorrow.', 'from 3510;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H7667}/[H7665]', 'inflected', 'heb', 'שֶׁבֶר', '["sheber"]', '["and/ from/ brokenness of"]', '["n-m"]', 'a fracture, figuratively, ruin; specifically, a solution (of a dream) affliction, breach, breaking, broken(-footed, -handed), bruise, crashing, destruction, hurt, interpretation, vexation.', 'or שֵׁבֶר; from 7665;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8034}/H9026/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["name/ your"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7621}/[H7650]', 'inflected', 'heb', 'שְׁבוּעָה', '["shᵉbûwʻâh"]', '["to/ a curse"]', '["n-f"]', 'properly, something sworn, i.e. an oath curse, oath, × sworn.', 'feminine passive participle of 7650;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4191}/H9031/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["and/ he will put to death/ you"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1288}/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["the/ [one who] blesses himself"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7650}/[H7651]', 'inflected', 'heb', 'שָׁבַע', '["shâbaʻ"]', '["and/ the/ [one who] swears an oath","and/ those/ [who] swear an oath"]', '["v"]', 'to seven oneself, i.e. swear (as if by repeating a declaration seven times) adjure, charge (by an oath, with an oath), feed to the full (by mistake for 7646), take an oath, × straitly, (cause to, make to) swear.', 'a primitive root; properly to be complete, but used only as a denominative from 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5971A}/H9024/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["and/ people/ its"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7797}/[H7797]', 'inflected', 'heb', 'שׂוּשׂ', '["sûws"]', '["and/ I will rejoice","and/ it will exult"]', '["v"]', 'to be bright, i.e. cheerful be glad, × greatly, joy, make mirth, rejoice.', 'or שִׂישׂ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5764}/[H5763]', 'lemma', 'heb', 'עוּל', '["ʻûwl"]', '["a sucking child of"]', '["n-m"]', 'a babe sucking child, infant.', 'from 5763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2398}/[H2398]', 'inflected', 'heb', 'חָטָא', '["châṭâʼ"]', '["and/ the/ [one who] misses"]', '["v"]', 'properly, to miss; hence (figuratively and generally) to sin; by inference, to forfeit, lack, expiate, repent, (causatively) lead astray, condemn bear the blame, cleanse, commit (sin), by fault, harm he hath done, loss, miss, (make) offend(-er), offer for sin, purge, purify (self), make reconciliation, (cause, make) sin(-ful, -ness), trespass.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0928}/[H926]', 'inflected', 'heb', 'בֶּהָלָה', '["behâlâh"]', '["for <the>/ sudden terror"]', '["n-f"]', 'panic, destruction terror, trouble.', 'from 926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2924}/[H2922]', 'inflected', 'heb', 'טָלֶה', '["ṭâleh"]', '["and/ lamb"]', '["n-m"]', 'a lamb lamb.', 'by variation for 2922;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5175}/[H5172]', 'inflected', 'heb', 'נָחָשׁ', '["nâchâsh"]', '["and/ a snake"]', '["n-m"]', 'a snake (from its hiss) serpent.', 'from 5172;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5223}/[H5223]', 'inflected', 'heb', 'נָכֶה', '["nâkeh"]', '["and/ a [person] stricken of"]', '["a"]', 'smitten, i.e. (literally) maimed, or (figuratively) dejected contrite, lame.', NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6202}/[H6203]', 'lemma', 'heb', 'עָרַף', '["ʻâraph"]', '["[one who] breaks [the] neck of","he will break"]', '["v"]', 'to break the neck; hence (figuratively) to destroy that is beheaded, break down, break (cut off, strike off) neck.', 'a primitive root (identical with through the idea of slopping); properly, to bend downward; but used only as a denominative from 6203,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1870G}/H9028/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["<in>/ own ways/ their","by/ conduct/ their"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8251}/H9028/[H8262]', 'inflected', 'heb', 'שִׁקּוּץ', '["shiqqûwts"]', '["and/ <in>/ detestable things/ their","and/ by/ abominations/ their"]', '["n-m"]', 'disgusting, i.e. filthy; especially idolatrous or (concretely) an idol abominable filth (idol, -ation), detestable (thing).', 'or שִׁקֻּץ; from 8262;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8586}/H9028/[H5953]', 'inflected', 'heb', 'תַּעֲלוּל', '["taʻălûwl"]', '["<in>/ punishments/ their"]', '["n-m"]', 'caprice (as a fit coming on), i.e. vexation; concretely a tyrant babe, delusion.', 'from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4035}/H9028/[H4032]', 'inflected', 'heb', 'מְגוּרָה', '["mᵉgûwrâh"]', '["and/ fears/ their"]', '["n-f"]', 'a fright; also a granary barn, fear.', 'feminine of 4032 or of 4033;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2730}/[H2729]', 'inflected', 'heb', 'חָרֵד', '["chârêd"]', '["O/ [people] trembling"]', '["a"]', 'fearful; also reverential afraid, trembling.', 'from 2729;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5077B}/H9036/[H5077]', 'inflected', 'heb', 'נָדָה', '["nâdâh"]', '["[who] exclude/ you"]', '["v"]', 'properly, to toss; figuratively, to exclude, i.e. banish, postpone, prohibit cast out, drive, put far away.', 'or נָדָא; (2 Kings 17:21), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8057}/H9026/[H8056]', 'inflected', 'heb', 'שִׂמְחָה', '["simchâh"]', '["on/ joy/ your"]', '["n-f"]', 'blithesomeness or glee, (religious or festival) × exceeding(-ly), gladness, joy(-fulness), mirth, pleasure, rejoice(-ing).', 'from 8056;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H2342I}/[H2342]', 'inflected', 'heb', 'חוּל', '["chûwl"]', '["¿/ will it be brought forth"]', '["v"]', 'properly, to twist or whirl (in a circular or spiral manner), i.e. (specifically) to dance, to writhe in pain (especially of parturition) or fear; figuratively, to wait, to pervert bear, (make to) bring forth, (make to) calve, dance, drive away, fall grievously (with pain), fear, form, great, grieve, (be) grievous, hope, look, make, be in pain, be much (sore) pained, rest, shake, shapen, (be) sorrow(-ful), stay, tarry, travail (with pain), tremble, trust, wait carefully (patiently), be wounded.', 'or חִיל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0589}/[H595]', 'inflected', 'heb', 'אֲנִי', '["ʼănîy"]', '["¿/ I"]', '["p"]', 'I I, (as for) me, mine, myself, we, × which, × who.', 'contracted from 595;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430G}/H9022\/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["God/ your"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0056}/[H56]', 'inflected', 'heb', 'אָבַל', '["ʼâbal"]', '["those/ [who] mourn"]', '["v"]', 'to bewail lament, mourn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8575}/H9024/[H5162]', 'inflected', 'heb', 'תַּנְחוּם', '["tanchûwm"]', '["consolations/ its"]', '["n"]', 'compassion, solace comfort, consolation.', 'or תַּנְחֻם; and (feminine) תַּנְחוּמָה; from 5162;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4711}/[H4711]', 'lemma', 'heb', 'מָצַץ', '["mâtsats"]', '["you may suck"]', '["v"]', 'to suck milk.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H2123B>', 'inflected', 'heb', 'מזיז', '["mi./Ziz"]', '["from/ [the] nipple of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3519}/H9024\/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["abundance/ its"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H5158A}/[H5157]', 'inflected', 'heb', 'נַחַל', '["nachal"]', '["and/ like/ a torrent"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5162G}/H9033/[H5162]', 'inflected', 'heb', 'נָחַם', '["nâcham"]', '["she comforts/ him"]', '["v"]', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6106G}/H9026/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["and/ bones/ your"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1877}/[H1876]', 'inflected', 'heb', 'דֶּשֶׁא', '["desheʼ"]', '["like <the>/ grass"]', '["n-m"]', 'a sprout; by analogy, grass (tender) grass, green, (tender) herb.', 'from 1876;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2194}/[H2194]', 'inflected', 'heb', 'זָעַם', '["zâʻam"]', '["and/ he will be indignant","and/ he will direct indignation"]', '["v"]', 'properly, to foam at the mouth, i.e. to be enraged abhor, abominable, (be) angry, defy, (have) indignation.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H5492A}/[H5486]', 'inflected', 'heb', 'סוּפָה', '["çûwphâh"]', '["and/ [will be] like the/ storm-wind","and/ like the/ storm-wind"]', '["n-f n-pr-loc"]', 'a hurricane Red Sea, storm, tempest, whirlwind, Red sea.', 'from 5486;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1606}/H9023/[H1605]', 'inflected', 'heb', 'גְּעָרָה', '["gᵉʻârâh"]', '["and/ rebuke/ his"]', '["n-f"]', 'a chiding rebuke(-ing), reproof.', 'from 1605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2719}/H9023/[H2717]', 'inflected', 'heb', 'חֶרֶב', '["chereb"]', '["and/ by/ sword/ his"]', '["n-f"]', 'drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2891}/[H2891]', 'inflected', 'heb', 'טָהֵר', '["ṭâhêr"]', '["and/ who/ purify themselves"]', '["v"]', 'to be pure (physical sound, clear, unadulterated; Levitically, uncontaminated; morally, innocent or holy) be (make, make self, pronounce) clean, cleanse (self), purge, purify(-ier, self).', 'a primitive root; properly, to be bright; i.e. (by implication)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1593}/[H1588]', 'inflected', 'heb', 'גַּנָּה', '["gannâh"]', '["the/ gardens"]', '["n-f"]', 'a garden garden.', 'feminine of 1588;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8263}/[H8262]', 'inflected', 'heb', 'שֶׁקֶץ', '["sheqets"]', '["and/ the/ detestable thing"]', '["n-m"]', 'filth, i.e. (figuratively and specifically) an idolatrous object abominable(-tion).', 'from 8262;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4284}/H9028/[H2803]', 'inflected', 'heb', 'מַחֲשָׁבָה', '["machăshâbâh"]', '["and/ thoughts/ their"]', '["n-f"]', 'a contrivance, i.e. (concretely) a texture, machine, or (abstractly) intention, plan (whether bad, a plot; or good, advice) cunning (work), curious work, device(-sed), imagination, invented, means, purpose, thought.', 'or מַחֲשֶׁבֶת; from 2803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3956H}/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["and/ the/ languages"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6322H>', 'opaque', 'heb', 'פּוּל', '["Pûwl"]', '["Pul"]', '["n-pr-m"]', 'Pul, the name of an Assyrian king and of an Ethiopian tribe Pul.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8422H}/[H8422]', 'lemma', 'heb', 'תּוּבַל', '["Tûwbal"]', '["Tubal"]', '["n-pr-m"]', 'Tubal, a postdiluvian patriarch and his posterity Tubal.', 'or תֻּבַל; probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3120H}/[H3196]', 'inflected', 'heb', 'יָוָן', '["Yâvân"]', '["and/ Javan"]', '["n-pr-m n-pr-loc"]', 'Javan, the name of a son of Joktan, and of the race (Ionians, i.e. Greeks) descended from him, with their territory; also of a place in Arabia Javan.', 'probably from the same as 3196; effervescing (i.e. hot and active);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8088B}/H9020/[H8085]', 'inflected', 'heb', 'שֵׁמַע', '["shêmaʻ"]', '["report/ my"]', '["n-m"]', 'something heard, i.e. a sound, rumor, announcement; abstractly, audience bruit, fame, hear(-ing), loud, report, speech, tidings.', 'from 8085;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1471G}/[H1465]', 'inflected', 'heb', 'גּוֹי', '["gôwy"]', '["among the/ nations"]', '["n-m n-pr-m"]', 'a foreign nation; hence, a Gentile; also (figuratively) a troop of animals, or a flight of locusts Gentile, heathen, nation, people.', 'rarely (shortened) גֹּי; apparently from the same root as 1465 (in the sense of massing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7393G}/[H7392]', 'inflected', 'heb', 'רֶכֶב', '["rekeb"]', '["and/ in <the>/ chariot[s]","and/ with/ chariotry"]', '["n-m"]', 'a vehicle; by implication, a team; by extension, cavalry; by analogy a rider, i.e. the upper millstone chariot, (upper) millstone, multitude (from the margin), wagon.', 'from 7392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H6632A>', 'inflected', 'heb', 'ובצבים', '["u./va./tza.Bim"]', '["and/ in <the>/ wagons"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3753}/[H3769]', 'inflected', 'heb', 'כַּרְכָּרָה', '["karkârâh"]', '["and/ on <the>/ camels"]', '["n-f"]', 'a dromedary (from its rapid motion as if dancing) swift beast.', 'from 3769;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8034}/H9026/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["and/ name/ your"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2320H}/H9023/[H2318]', 'inflected', 'heb', 'חֹדֶשׁ', '["chôdesh"]', '["in/ new moon/ its"]', '["n-m"]', 'the new moon; by implication, a month month(-ly), new moon.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H1767>', 'inflected', 'heb', 'ומדי', '["u./mi./Dei"]', '["and/ as/ often as"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6297}/[H6296]', 'inflected', 'heb', 'פֶּגֶר', '["peger"]', '["on/ [the] corpses of"]', '["n-m"]', 'a carcase (as limp), whether of man or beast; figuratively, an idolatrous image carcase, corpse, dead body.', 'from 6296;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6586}/[H6586]', 'inflected', 'heb', 'פָּשַׁע', '["pâshaʻ"]', '["the/ rebels","who/ rebelled"]', '["v"]', 'to break away (from just authority), i.e. trespass, apostatize, quarrel offend, rebel, revolt, transgress(-ion, -or).', 'a primitive root (identical with through the idea of expansion);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8438B}/H9028/[H3216]', 'inflected', 'heb', 'תּוֹלָע', '["tôwlâʻ"]', '["worm/ their"]', '["n-m n-f"]', 'a maggot (as voracious); specifically (often with ellipsis of 8144) the crimson-grub, but used only (in this connection) of the color from it, and cloths dyed therewith crimson, scarlet, worm.', 'and (feminine) תּוֹלֵעָה; or תּוֹלַעַת; or תֹּלַעַת; from 3216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0784}/H9028/[H784]', 'inflected', 'heb', 'אֵשׁ', '["ʼêsh"]', '["and/ fire/ their"]', '["n-f"]', 'fire (literally or figuratively) burning, fiery, fire, flaming, hot.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1860>', 'opaque', 'heb', 'דְּרָאוֹן', '["dᵉrâʼôwn"]', '["an abhorrence"]', '["n-m"]', 'an object of aversion abhorring, contempt.', 'or דֵּרָאוֹן; from an unused root (meaning to repulse);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2518M}/[H2506]', 'lemma', 'heb', 'חִלְקִיָּה', '["Chilqîyâh"]', '["Hilkiah"]', '["n-pr-m"]', 'Chilhijah, the name of eight Israelites Hillkiah.', 'or חִלְקִיָּהוּ; from 2506 and 3050; portion of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6068G}/[H6067]', 'inflected', 'heb', 'עֲנָתוֹת', '["ʻĂnâthôwth"]', '["[is] at/ Anathoth","[was] at/ Anathoth","[were] at/ Anathoth"]', '["n-pr-m n-pr-loc"]', 'Anathoth, the name of two Israelites, also of a place in Pal Anathoth.', 'plural of 6067;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6667H}/[H6664]', 'inflected', 'heb', 'צִדְקִיָּה', '["Tsidqîyâh"]', '["of/ Zedekiah"]', '["n-pr-m"]', 'Tsidkijah, the name of six Israelites Zedekiah, Zidkijah.', 'or צִדְקִיָּהוּ; from 6664 and 3050; right of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6942H}/H9031/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["I set apart/ you"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0595}\/[H595]', 'inflected', 'heb', 'אָנֹכִי', '["ʼânôkîy"]', '["I"]', '["p"]', 'I I, me, × which.', 'sometimes, אָנֹכִי; a primitive pronoun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6485J}/H9031/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["I appoint/ you"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5428}/[H5428]', 'inflected', 'heb', 'נָתַשׁ', '["nâthash"]', '["to/ pluck up"]', '["v"]', 'to tear away destroy, forsake, pluck (out, up, by the roots), pull up, root out (up), × utterly. s', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5422}/[H5422]', 'inflected', 'heb', 'נָתַץ', '["nâthats"]', '["and/ to/ pull down"]', '["v"]', 'to tear down beat down, break down (out), cast down, destroy, overthrow, pull down, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2040}/[H2040]', 'inflected', 'heb', 'הָרַס', '["hâraç"]', '["and/ to/ tear down"]', '["v"]', 'to pull down or in pieces, break, destroy beat down, break (down, through), destroy, overthrow, pluck down, pull down, ruin, throw down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5193}\/[H5193]', 'inflected', 'heb', 'נָטַע', '["nâṭaʻ"]', '["and/ to/ plant"]', '["v"]', 'properly, to strike in, i.e. fix; specifically, to plant (literally or figuratively) fastened, plant(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6440G}/H9023/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["and/ face/ its"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7451I}/H9028/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["evil/ their","wickedness/ their"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2865}/H9031/[H2865]', 'inflected', 'heb', 'חָתַת', '["châthath"]', '["I should make dismayed/ you"]', '["v"]', 'properly, to prostrate; hence, to break down, either (literally) by violence, or (figuratively) by confusion and fear abolish, affright, be (make) afraid, amaze, beat down, discourage, (cause to) dismay, go down, scare, terrify.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5982G}/[H5975]', 'inflected', 'heb', 'עַמּוּד', '["ʻammûwd"]', '["and/ into/ a pillar of"]', '["n-m"]', 'a column (as standing); also a stand, i.e. platform × apiece, pillar.', 'or עַמֻּד; from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8269}/H9024/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["to/ officials/ its"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3548}/H9024/[H3547]', 'inflected', 'heb', 'כֹּהֵן', '["kôhên"]', '["to/ priests/ its"]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5337}/H9031\/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["to/ deliver/ you"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3623}/H9022/[H3618]', 'inflected', 'heb', 'כְּלוּלָה', '["kᵉlûwlâh"]', '["betrothal<s>/ your"]', '["n-f"]', 'bridehood (only in the plural) espousal.', 'denominative passive participle from 3618;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980N}/H9042/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["walking/ you"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1980J}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["who/ led"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7745}/[H7743]', 'inflected', 'heb', 'שׁוּחָה', '["shûwchâh"]', '["and/ pit"]', '["n-f"]', 'a chasm ditch, pit.', 'from 7743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2898}/H9024/[H2895]', 'inflected', 'heb', 'טוּב', '["ṭûwb"]', '["and/ good thing[s]/ its"]', '["n-m"]', 'good (as a noun), in the widest sense, especially goodness (superlative concretely, the best), beauty, gladness, welfare fair, gladness, good(-ness, thing, -s), joy, go well with.', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8610}/[H8610]', 'inflected', 'heb', 'תָּפַשׂ', '["tâphas"]', '["and/ [one who] wields","and/ [the] handler of","and/ [those who] handled"]', '["v"]', 'to manipulate, i.e. seize; chiefly to capture, wield, specifically, to overlay; figuratively, to use unwarrantably catch, handle, (lay, take) hold (on, over), stop, × surely, surprise, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7462B}/[H7462]', 'inflected', 'heb', 'רָעָה', '["râʻâh"]', '["and/ the/ shepherds"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1168A}/[H1167]', 'inflected', 'heb', 'בַּעַל', '["Baʻal"]', '["by <the>/ Baal","for <the>/ Baal"]', '["n-pr-m n-pr-loc"]', 'Baal, a Phoenician deity Baal, (plural) Baalim.', 'the same as 1167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3235}/[H3235]', 'inflected', 'heb', 'יָמַר', '["yâmar"]', '["¿/ has it exchanged"]', '["v"]', 'to exchange; by implication, to change places boast selves, change.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8175A}/[H8175]', 'inflected', 'heb', 'שָׂעַר', '["sâʻar"]', '["and/ shudder"]', '["v"]', 'to storm; by implication, to shiver, i.e. fear be (horribly) afraid, fear, hurl as a storm, be tempestuous, come like (take away as with) a whirlwind.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0877}/[H874]', 'lemma', 'heb', 'בֹּאר', '["bôʼr"]', '["cisterns"]', '["n-m"]', 'a cistern cistern.', 'from 874;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5650}/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["¿/ a slave"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8471}/[H8471]', 'inflected', 'heb', 'תַּחְפַּנְחֵס', '["Tachpanchêç"]', '["and/ Tahpanhes"]', '["n-pr-loc"]', 'Tachpanches, Techaphneches or Tachpenes, a place in Egypt Tahapanes, Tahpanhes, Tehaphnehes.', 'or תְּחַפְנְחֵס; (Ezekiel 30:18), or תַּחְפְּנֵס; (Jeremiah 2:16), of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7462B}/H9032/[H7462]', 'inflected', 'heb', 'רָעָה', '["râʻâh"]', '["they will graze/ you"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5800A}/H9042/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["by forsaking/ you","forsaking/ you"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980J}/H9032/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["[one who] led/ you"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3256}/H9032/[H3256]', 'inflected', 'heb', 'יָסַר', '["yâçar"]', '["it will punish/ you"]', '["v"]', 'to chastise, literally (with blows) or figuratively (with words); hence, to instruct bind, chasten, chastise, correct, instruct, punish, reform, reprove, sore, teach.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7451I}/H9022/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["wickedness/ your"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4878}/H9022/[H7725]', 'inflected', 'heb', 'מְשׁוּבָה', '["mᵉshûwbâh"]', '["and/ apostasies/ your"]', '["n-f"]', 'apostasy backsliding, turning away.', 'or מְשֻׁבָה; from 7725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3198}/H9032/[H3198]', 'inflected', 'heb', 'יָכַח', '["yâkach"]', '["they will rebuke/ you"]', '["v"]', 'to be right (i.e. correct); reciprocal, to argue; causatively, to decide, justify or convict appoint, argue, chasten, convince, correct(-ion), daysman, dispute, judge, maintain, plead, reason (together), rebuke, reprove(-r), surely, in any wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6345}/H9020/[H6343]', 'inflected', 'heb', 'פַּחְדָּה', '["pachdâh"]', '["awe of/ me"]', '["n-f"]', 'alarm (i.e. awe) fear.', 'feminine of 6343;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4147}/H9022/[H3256]', 'inflected', 'heb', 'מוֹסֵר', '["môwçêr"]', '["fetters/ your"]', '["n-m"]', 'properly, chastisement, i.e. (by implication) a halter; figuratively, restraint band, bond.', 'also (in plural) feminine מוֹסֵרָה; or מֹסְרָה; from 3256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5193}/H9032/[H5193]', 'inflected', 'heb', 'נָטַע', '["nâṭaʻ"]', '["I had planted/ you"]', '["v"]', 'properly, to strike in, i.e. fix; specifically, to plant (literally or figuratively) fastened, plant(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5494}/[H5493]', 'lemma', 'heb', 'סוּר', '["çûwr"]', '["[the] degenerate [ones] of"]', '["n-m"]', 'turned off, i.e. deteriorated degenerate.', 'probably passive participle of 5493;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5427}/[H5425]', 'inflected', 'heb', 'נֶתֶר', '["nether"]', '["with <the>/ soda"]', '["n-m"]', 'mineral potash (so called from effervescing with acid) nitre.', 'from 5425;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1287}/[H1253]', 'lemma', 'heb', 'בֹּרִית', '["bôrîyth"]', '["soap"]', '["n-f"]', 'vegetable alkali sope.', 'feminine of 1253;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3799}/[H3799]', 'lemma', 'heb', 'כָּתַם', '["kâtham"]', '["[is] stained"]', '["v"]', 'properly, to carve or engrave, i.e. (by implication) to inscribe indelibly mark.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5771H}/H9022/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["iniquity/ your"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1072}/[H1070]', 'lemma', 'heb', 'בִּכְרָה', '["bikrâh"]', '["a young camel"]', '["n-f"]', 'a young she-camel dromedary.', 'feminine of 1070;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8308}/[H8308]', 'lemma', 'heb', 'שָׂרַךְ', '["sârak"]', '["entwining"]', '["v"]', 'to interlace traverse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870L}/H9024/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["paths/ its"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0185}/[H183]', 'inflected', 'heb', 'אַוָּה', '["ʼavvâh"]', '["in/ [the] lust of"]', '["n-f"]', 'longing desire, lust after, pleasure.', 'from 183;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8385A}/H9024/[H579]', 'inflected', 'heb', 'תַּאֲנָה', '["taʼănâh"]', '["heat/ its"]', '["n-f"]', 'an opportunity or (subjectively) purpose occasion.', 'or תֹּאֲנָה; from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2320G}/H9024/[H2318]', 'inflected', 'heb', 'חֹדֶשׁ', '["chôdesh"]', '["in/ month/ its"]', '["n-m"]', 'the new moon; by implication, a month month(-ly), new moon.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H3182>', 'inflected', 'heb', 'מיחף', '["mi./ya.Chef"]', '["from/ barefoot"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1627}/H9022/[H1641]', 'inflected', 'heb', 'גָּרוֹן', '["gârôwn"]', '["and/ throat/ your"]', '["n-m"]', 'the throat (as roughened by swallowing) × aloud, mouth, neck, throat.', 'or (shortened) גָּרֹן; from 1641; (compare 1621)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6773}/[H6772]', 'inflected', 'heb', 'צִמְאָה', '["tsimʼâh"]', '["from/ thirst"]', '["n-f"]', 'thirst (figuratively, of libidinousnes) thirst.', 'feminine of 6772;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1322}/[H954]', 'inflected', 'heb', 'בֹּשֶׁת', '["bôsheth"]', '["like/ [the] shame of"]', '["n-f"]', 'shame (the feeling and the condition, as well as its cause); by implication (specifically) an idol ashamed, confusion, greatly, (put to) shame(-ful thing).', 'from 954;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3548}/H9028/[H3547]', 'inflected', 'heb', 'כֹּהֵן', '["kôhên"]', '["and/ priests/ their"]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5030}/H9028/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["and/ prophets/ their"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3205}/H9035/[H3205]', 'inflected', 'heb', 'יָלַד', '["yâlad"]', '["you gave birth to/ us"]', '["v"]', 'to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2719}/H9026/[H2717]', 'inflected', 'heb', 'חֶרֶב', '["chereb"]', '["sword/ your"]', '["n-f"]', 'drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H4057B}/[H1696]', 'inflected', 'heb', 'מִדְבָּר', '["midbâr"]', '["¿/ a wilderness"]', '["n-m"]', 'a pasture (i.e. open field, whither cattle are driven); by implication, a desert; also speech (including its organs) desert, south, speech, wilderness.', 'from 1696 in the sense of driving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3991}/[H3990]', 'lemma', 'heb', 'מַאְפֵלְיָה', '["maʼphêlᵉyâh"]', '["darkness"]', '["n-f"]', 'opaqueness darkness.', 'prolonged feminine of 3990;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5716}/H9024/[H5710]', 'inflected', 'heb', 'עֲדִי', '["ʻădîy"]', '["ornament[s]/ her"]', '["n-m"]', 'finery; generally an outfit; specifically, a headstall × excellent, mouth, ornament.', 'from 5710 in the sense of trappings;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7196}/H9024/[H7194]', 'inflected', 'heb', 'קִשֻּׁר', '["qishshur"]', '["sashes/ her"]', '["n-m"]', 'an (ornamental) girdle (for women) attire, headband.', 'from 7194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870G}/H9022/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["[has been] way/ your","conduct/ your","way/ your","ways/ your"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3671}/H9022/[H3670]', 'inflected', 'heb', 'כָּנָף', '["kânâph"]', '["on/ skirts/ your"]', '["n-f"]', 'an edge or extremity; specifically (of a bird or army) a wing, (of a garment or bedclothing) a flap, (of the earth) a quarter, (of a building) a pinnacle bird, border, corner, end, feather(-ed), × flying, (one an-) other, overspreading, × quarters, skirt, × sort, uttermost part, wing(-ed).', 'from 3670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0559}/H9042/[H559]', 'inflected', 'heb', 'אָמַר', '["ʼâmar"]', '["said/ you","saying/ you"]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8138A}/[H8138]', 'inflected', 'heb', 'שָׁנָה', '["shânâh"]', '["to/ change"]', '["v"]', 'to fold, i.e. duplicate (literally or figuratively); by implication, to transmute (transitive or intransitive) do (speak, strike) again, alter, double, (be given to) change, disguise, (be) diverse, pervert, prefer, repeat, return, do the second time.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3027G}/H9022/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ hands/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4009}/H9022/[H982]', 'inflected', 'heb', 'מִבְטָח', '["mibṭâch"]', '["<in>/ objects of confidence/ your"]', '["n-m"]', 'properly, a refuge, i.e. (objective) security, or (subjective) assurance confidence, hope, sure, trust.', 'from 982;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6163A}/[H6152]', 'inflected', 'heb', 'עֲרָבִי', '["ʻĂrâbîy"]', '["like/ an Arab"]', '["n a"]', 'an Arabian or inhabitant of Arab (i.e. Arabia) Arabian.', 'or עַרְבִי; patrial from 6152;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2184}/H9022/[H2181]', 'inflected', 'heb', 'זְנוּת', '["zᵉnûwth"]', '["by/ prostitution/ your"]', '["n-f"]', 'adultery, i.e. (figuratively) infidelity, idolatry whoredom.', 'from 2181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7451C}/H9022/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["and/ by/ wickedness/ your"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4513}/[H4513]', 'inflected', 'heb', 'מָנַע', '["mânaʻ"]', '["and/ I withheld","and/ they have been withheld"]', '["v"]', 'to debar (negatively or positively) from benefit or injury deny, keep (back), refrain, restrain, withhold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7241}/[H7231]', 'lemma', 'heb', 'רָבִיב', '["râbîyb"]', '["copious showers"]', '["n-m"]', 'a rain (as an accumulation of drops) shower.', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4696>', 'inflected', 'heb', 'ומצח', '["u./Me.tzach"]', '["and/ [the] forehead of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5201}/[H5201]', 'inflected', 'heb', 'נָטַר', '["nâṭar"]', '["¿/ will he maintain"]', '["v"]', 'to guard; figuratively, to cherish (anger) bear grudge, keep(-er), reserve.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3201}\/[H3201]', 'inflected', 'heb', 'יָכֹל', '["yâkôl"]', '["and/ you were able"]', '["v"]', 'to be able, literally (can, could) or morally (may, might) be able, any at all (ways), attain, can (away with, (-not)), could, endure, might, overcome, have power, prevail, still, suffer.', 'or (fuller) יָכוֹל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213A}/H9044/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["doing/ it","has done/ she"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0901}/[H898]', 'lemma', 'heb', 'בָּגוֹד', '["bâgôwd"]', '["treacherous"]', '["a"]', 'treacherous treacherous.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3748}/H9024/[H3772]', 'inflected', 'heb', 'כְּרִיתוּת', '["kᵉrîythûwth"]', '["divorce<s>/ her"]', '["n-f"]', 'a cutting (of the matrimonial bond), i.e. divorce divorce(-ment).', 'from 3772;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H6963B>', 'inflected', 'heb', 'מקל', '["mi./Kol"]', '["from/ [the] lightness of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2184}/H9024/[H2181]', 'inflected', 'heb', 'זְנוּת', '["zᵉnûwth"]', '["prostitution/ her"]', '["n-f"]', 'adultery, i.e. (figuratively) infidelity, idolatry whoredom.', 'from 2181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5003}/[H5003]', 'inflected', 'heb', 'נָאַף', '["nâʼaph"]', '["and/ she committed adultery","and/ they committed adultery"]', '["v"]', 'to commit adultery; figuratively, to apostatize adulterer(-ess), commit(-ing) adultery, woman that breaketh wedlock.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8267}/[H8266]', 'inflected', 'heb', 'שֶׁקֶר', '["sheqer"]', '["in <the>/ falsehood","with <the>/ falsehood","with/ deception","with/ falsehood"]', '["n-m"]', 'an untruth; by implication, a sham (often adverbial) without a cause, deceit(-ful), false(-hood, -ly), feignedly, liar, lie, lying, vain (thing), wrongfully.', 'from 8266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0898}/[H898]', 'inflected', 'heb', 'בָּגַד', '["bâgad"]', '["more than/ [the] treacherous [one]"]', '["v"]', 'to cover (with a garment); figuratively, to act covertly; by implication, to pillage deal deceitfully (treacherously, unfaithfully), offend, transgress(-or), (depart), treacherous (dealer, -ly, man), unfaithful(-ly, man), × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5307K}/[H5307]', 'lemma', 'heb', 'נָפַל', '["nâphal"]', '["I will make fall"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440M}/H9020/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["face/ my"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6340}/[H6340]', 'inflected', 'heb', 'פָּזַר', '["pâzar"]', '["and/ you have scattered"]', '["v"]', 'to scatter, whether in enmity or bounty disperse, scatter (abroad).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H6963A>/H9020', 'inflected', 'heb', 'ובקולי', '["u./ve./ko.L/i"]', '["and/ to/ voice/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3820A}/H9020/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["according to/ own heart/ my"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6960B}/[H6960]', 'inflected', 'heb', 'קָוָה', '["qâvâh"]', '["and/ they will be collected"]', '["v"]', 'to bind together (perhaps by twisting), i.e. collect; (figuratively) to expect gather (together), look, patiently, tarry, wait (for, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8307}/[H8324]', 'lemma', 'heb', 'שְׁרִירוּת', '["shᵉrîyrûwth"]', '["[the] stubbornness of"]', '["n-f"]', 'obstinacy imagination, lust.', 'from 8324 in the sense of twisted, i.e. firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7451H}\/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["<the>/ evil"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7896G}/H9032/[H7896]', 'inflected', 'heb', 'שִׁית', '["shîyth"]', '["I will set/ you"]', '["v"]', 'to place (in a very wide application) apply, appoint, array, bring, consider, lay (up), let alone, × look, make, mark, put (on), regard, set, shew, be stayed, × take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0310A}/H9030/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["and/ from/ after/ me"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7453}/H9024/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["from/ companion/ her"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4878}/H9026/[H7725]', 'inflected', 'heb', 'מְשׁוּבָה', '["mᵉshûwbâh"]', '["apostasies/ your"]', '["n-f"]', 'apostasy backsliding, turning away.', 'or מְשֻׁבָה; from 7725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1322}/[H954]', 'inflected', 'heb', 'בֹּשֶׁת', '["bôsheth"]', '["and/ the/ shameful thing"]', '["n-f"]', 'shame (the feeling and the condition, as well as its cause); by implication (specifically) an idol ashamed, confusion, greatly, (put to) shame(-ful thing).', 'from 954;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1322}/H9025/[H954]', 'inflected', 'heb', 'בֹּשֶׁת', '["bôsheth"]', '["in/ shame/ our"]', '["n-f"]', 'shame (the feeling and the condition, as well as its cause); by implication (specifically) an idol ashamed, confusion, greatly, (put to) shame(-ful thing).', 'from 954;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3680}/H9035/[H3680]', 'inflected', 'heb', 'כָּסָה', '["kâçâh"]', '["and/ let it cover/ us"]', '["v"]', 'properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3639}/H9025/[H3637]', 'inflected', 'heb', 'כְּלִמָּה', '["kᵉlimmâh"]', '["disgrace/ our"]', '["n-f"]', 'disgrace confusion, dishonour, reproach, shame.', 'from 3637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8251}/H9021/[H8262]', 'inflected', 'heb', 'שִׁקּוּץ', '["shiqqûwts"]', '["detestable things/ your"]', '["n-m"]', 'disgusting, i.e. filthy; especially idolatrous or (concretely) an idol abominable filth (idol, -ation), detestable (thing).', 'or שִׁקֻּץ; from 8262;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5214}/[H5216]', 'lemma', 'heb', 'נִיר', '["nîyr"]', '["plow"]', '["v"]', 'to till the soil break up.', 'a root probably identical with that of 5216, through the idea of the gleam of a fresh furrow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6726}/H9011/[H6725]', 'inflected', 'heb', 'צִיּוֹן', '["Tsîyôwn"]', '["Zion/ towards"]', '["n-pr-loc"]', 'Tsijon (as a permanent capital), a mountain of Jerusalem Zion.', 'the same (regularly) as 6725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5441}/H9023/[H5440]', 'inflected', 'heb', 'סֹבֶךְ', '["çôbek"]', '["from/ thicket/ its"]', '["n-m"]', 'a copse thicket.', 'from 5440;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7843}/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["and/ a destroyer of","and/ destroy [them]","and/ let us destroy"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5892B}/H9022/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["cities/ your"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3213}/[H3213]', 'inflected', 'heb', 'יָלַל', '["yâlal"]', '["and/ I will wail","and/ wail"]', '["v"]', 'to howl (with a wailing tone) or yell (with a boisterous one) (make to) howl, be howling.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4480A}/H9035\/[H4482]', 'inflected', 'heb', 'מִן', '["min"]', '["from/ us"]', '["prep"]', 'properly, a part of; hence (prepositionally), from or out of in many senses above, after, among, at, because of, by (reason of), from (among), in, × neither, × nor, (out) of, over, since, × then, through, × whether, with.', 'or מִנִּי; or מִנֵּי; (constructive plural) (Isaiah 30:11); for 4482;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2219}/[H2114]', 'inflected', 'heb', 'זָרָה', '["zârâh"]', '["to/ winnow"]', '["v"]', 'to toss about; by implication, to diffuse, winnow cast away, compass, disperse, fan, scatter (away), spread, strew, winnow.', 'a primitive root (compare 2114);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1305}/[H1305]', 'inflected', 'heb', 'בָּרַר', '["bârar"]', '["to/ cleanse"]', '["v"]', 'to clarify (i.e. brighten), examine, select make bright, choice, chosen, cleanse (be clean), clearly, polished, (shew self) pure(-ify), purge (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6051}/[H6049]', 'inflected', 'heb', 'עָנָן', '["ʻânân"]', '["[is] like/ a cloud of","like <the>/ cloud","like/ a cloud of","like/ clouds"]', '["n-m"]', 'a cloud (as covering the sky), i.e. the nimbus or thunder-cloud cloud(-y).', 'from 6049;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0205G>/H9022', 'opaque', 'heb', 'אָוֶן', '["ʼâven"]', '["wickedness/ your"]', '["n-m"]', 'strictly nothingness; also trouble, vanity, wickedness; specifically an idol affliction, evil, false, idol, iniquity, mischief, mourners(-ing), naught, sorrow, unjust, unrighteous, vain, vanity, wicked(-ness). Compare 369.', 'from an unused root perhaps meaning properly, to pant (hence, to exert oneself, usually in vain; to come to naught);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8085I}/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["and/ [is] proclaiming","and/ make a proclamation","so/ they may cause to hear"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0669J}/[H672]', 'lemma', 'heb', 'אֶפְרַיִם', '["ʼEphrayim"]', '["Ephraim"]', '["n-pr-m"]', 'Ephrajim, a son of Joseph; also the tribe descended from him, and its territory Ephraim, Ephraimites.', 'dual of masculine form of 672; double fruit;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8104H}/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["like/ [those who] guard"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4611}/H9022/[H5953]', 'inflected', 'heb', 'מַעֲלָל', '["maʻălâl"]', '["and/ deeds/ your"]', '["n-m"]', 'an act (good or bad) doing, endeavour, invention, work.', 'from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7451C}/H9022/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["[is] wickedness/ your","wickedness/ your"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3820A}/H9022\/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["heart/ your"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3407}/H9020/[H3415]', 'inflected', 'heb', 'יְרִיעָה', '["yᵉrîyʻâh"]', '["tent curtains/ my"]', '["n-f"]', 'a hanging (as tremulous) curtain.', 'from 3415;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7782}\/[H8231]', 'inflected', 'heb', 'שׁוֹפָר', '["shôwphâr"]', '["a trumpet"]', '["n-m"]', 'a cornet (as giving a clear sound) or curved horn cornet, trumpet.', 'or שֹׁפָר; from 8231 in the original sense of incising;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3190}/[H3190]', 'inflected', 'heb', 'יָטַב', '["yâṭab"]', '["and/ to/ do good"]', '["v"]', 'to be (causative) make well, literally (sound, beautiful) or figuratively (happy, successful, right) be accepted, amend, use aright, benefit, be (make) better, seem best, make cheerful, be comely, be content, diligent(-ly), dress, earnestly, find favour, give, be glad, do (be, make) good(-ness), be (make) merry, please ( well), shew more (kindness), skilfully, × very small, surely, make sweet, thoroughly, tire, trim, very, be (can, deal, entreat, go, have) well (said, seen).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3617}/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["and/ complete destruction"]', '["n-f"]', 'a completion; adverb, completely; also destruction altogether, (be, utterly) consume(-d), consummation(-ption), was determined, (full, utter) end, riddance.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6937}/[H6937]', 'inflected', 'heb', 'קָדַר', '["qâdar"]', '["and/ I made mourn","and/ I will darken","and/ it will be dark","and/ they will be dark"]', '["v"]', 'to be ashy, i.e. dark-colored; by implication, to mourn (in sackcloth or sordid garments) be black(-ish), be (make) dark(-en), × heavily, (cause to) mourn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7411A}/[H7411]', 'inflected', 'heb', 'רָמָה', '["râmâh"]', '["and/ a shooter of"]', '["v"]', 'to hurl; specifically, to shoot; figuratively, to delude or betray (as if causing to fall) beguile, betray, (bow-) man, carry, deceive, throw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3710}/[H3721]', 'inflected', 'heb', 'כֵּף', '["kêph"]', '["and/ on the/ rocks"]', '["n-m"]', 'a hollow rock rock.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5689}/[H5689]', 'lemma', 'heb', 'עֲגַב', '["ʻăgab"]', '["lovers","she had lusted","she lusted","she lusted after"]', '["v"]', 'to breathe after, i.e. to love (sensually) dote, lover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2470I}/[H2342]', 'inflected', 'heb', 'חָלָה', '["châlâh"]', '["like/ a sick [woman]"]', '["v"]', 'properly, to be rubbed or worn; hence (figuratively) to be weak, sick, afflicted; or (causatively) to grieve, make sick; also to stroke (in flattering), entreat beseech, (be) diseased, (put to) grief, be grieved, (be) grievous, infirmity, intreat, lay to, put to pain, × pray, make prayer, be (fall, make) sick, sore, be sorry, make suit (× supplication), woman in travail, be (become) weak, be wounded.', 'a primitive root (compare 2342, 2470, 2490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1069}/[H1061]', 'inflected', 'heb', 'בָּכַר', '["bâkar"]', '["like/ a [woman] bearing a first child"]', '["v"]', 'to give the birthright make firstborn, be firstling, bring forth first child (new fruit).', 'a primitive root; properly, to burst the womb, i.e. (causatively) bear or make early fruit (of woman or tree); also (as denominative from 1061)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3306}/[H3306]', 'lemma', 'heb', 'יָפַח', '["yâphach"]', '["she is gasping for breath"]', '["v"]', 'properly, to breathe hard, i.e. (by implication) to sigh bewail self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5888}/[H5888]', 'lemma', 'heb', 'עָיֵף', '["ʻâyêph"]', '["it is weary"]', '["v"]', 'to languish be wearied.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2026}\/[H2026]', 'inflected', 'heb', 'הָרַג', '["hârag"]', '["to/ murderers"]', '["v"]', 'to smite with deadly intent destroy, out of hand, kill, murder(-er), put to (death), make (slaughter), slay(-er), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7339}/H9024/[H7337]', 'inflected', 'heb', 'רְחֹב', '["rᵉchôb"]', '["in/ open places/ its"]', '["n-f"]', 'a width, i.e. (concretely) avenue or area broad place (way), street. See also 1050.', 'or רְחוֹב; from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0530}/[H529]', 'inflected', 'heb', 'אֱמוּנָה', '["ʼĕmûwnâh"]', '["to/ faithfulness"]', '["n-f"]', 'literally firmness; figuratively security; morally fidelity faith(-ful, -ly, -ness, (man)), set office, stability, steady, truly, truth, verily.', 'or (shortened) אֱמֻנָה; feminine of 529;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4878}/H9028/[H7725]', 'inflected', 'heb', 'מְשׁוּבָה', '["mᵉshûwbâh"]', '["apostasies/ their","apostasy/ their"]', '["n-f"]', 'apostasy backsliding, turning away.', 'or מְשֻׁבָה; from 7725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2109A}/[H2109]', 'lemma', 'heb', 'זוּן', '["zûwn"]', '["well fed"]', '["v"]', 'perhaps properly, to be plump, i.e. (transitively) to nourish feed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7904}/[H7904]', 'lemma', 'heb', 'שָׁכָה', '["shâkâh"]', '["lustful"]', '["v"]', 'to roam (through lust) in the morning (by mistake for 7925).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315I}/H9020\/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["self/ my"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8284}/H9024/[H7791]', 'inflected', 'heb', 'שָׁרָה', '["shârâh"]', '["among/ vine rows/ its"]', '["n-f"]', 'a fortification (literally or figuratively) sing (by mistake for 7891), wall.', 'probably feminine of 7791;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5189}/H9024/[H5203]', 'inflected', 'heb', 'נְטִישָׁה', '["nᵉṭîyshâh"]', '["vine tendrils/ its"]', '["n-f"]', 'a tendril (as an offshoot) battlement, branch, plant.', 'from 5203;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1699B}/[H1696]', 'inflected', 'heb', 'דֹּבֶר', '["dôber"]', '["and/ the/ word"]', '["n-m"]', 'a pasture (from its arrangement of the flock) fold, manner.', 'from 1696 (in its original sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1696G}/H9046/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["have spoken/ you"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6913}/[H6912]', 'inflected', 'heb', 'קֶבֶר', '["qeber"]', '["[is] like/ a grave"]', '["n-m"]', 'a sepulchre burying place, grave, sepulchre.', 'or (feminine) קִבְרָה; from 6912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3899G}/H9021/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["and/ food/ your"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1612>/H9021', 'opaque', 'heb', 'גֶּפֶן', '["gephen"]', '["vine[s]/ your"]', '["n-m"]', 'a vine (as twining), especially the grape vine, tree.', 'from an unused root meaning to bend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8384}/H9021/[H8384]', 'inflected', 'heb', 'תְּאֵן', '["tᵉʼên"]', '["and/ fig tree[s]/ your"]', '["n-f"]', 'the fig (tree or fruit) fig (tree).', 'or (in the singular, feminine) תְּאֵנָה; perhaps of foreign derivation');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7567}/[H7567]', 'lemma', 'heb', 'רָשַׁשׁ', '["râshash"]', '["it will shatter","we have been shattered"]', '["v"]', 'to demolish impoverish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4013}/H9021/[H1219]', 'inflected', 'heb', 'מִבְצָר', '["mibtsâr"]', '["fortifications/ your","fortresses/ your"]', '["n-m"]', 'a fortification, castle, or fortified city; figuratively, a defender (de-, most) fenced, fortress, (most) strong (hold).', 'also (in plural) feminine (Daniel 11:l5) מִבְצָרָה; from 1219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8085I}/H9034/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["and/ proclaim/ it"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0853}/H9030/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["¿/ <obj.>/ me"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2344}/[H2342]', 'lemma', 'heb', 'חוֹל', '["chôwl"]', '["[the] sand","[the] sand of"]', '["n-m"]', 'sand (as round or whirling particles) sand.', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3619}/[H3611]', 'inflected', 'heb', 'כְּלוּב', '["kᵉlûwb"]', '["like/ a cage"]', '["n-m"]', 'a bird-trap (as furnished with a clap-stick or treadle to spring it); hence, a basket (as resembling a wicker cage) basket, cage.', 'from the same as 3611;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6238}/[H6238]', 'inflected', 'heb', 'עָשַׁר', '["ʻâshar"]', '["and/ they have gained riches"]', '["v"]', 'properly, to accumulate; chiefly (specifically) to grow (causatively, make) rich be(-come, en-, make, make self, wax) rich, make (1 Kings 22:48 marg). See 6240.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6245A}/[H6245]', 'lemma', 'heb', 'עָשַׁת', '["ʻâshath"]', '["they have become smooth"]', '["v"]', 'probably to be sleek, i.e. glossy; hence (through the idea of polishing) to excogitate (as if forming in the mind) shine, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8047H}/[H8074]', 'lemma', 'heb', 'שַׁמָּה', '["shammâh"]', '["a horror","an atrocious event","desolation","horror"]', '["n-f"]', 'ruin; by implication, consternation astonishment, desolate(-ion), waste, wonderful thing.', 'from 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8186A}/[H8176]', 'inflected', 'heb', 'שַׁעֲרוּרָה', '["shaʻărûwrâh"]', '["and/ a horrible [thing]"]', '["n-f"]', 'something fearful horrible thing.', 'or שַׁעֲרִירִיָּה; or שַׁעֲרֻרִת; feminine from 8176 in the sense of 8175;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0319}/H9024/[H310]', 'inflected', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["to/ end/ its"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8620}/[H8619]', 'inflected', 'heb', 'תְּקוֹעַ', '["Tᵉqôwaʻ"]', '["and/ in/ Tekoa"]', '["n-pr-m n-pr-loc"]', 'Tekoa, a place in Palestine Tekoa, Tekoah.', 'a form of 8619;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5000}/[H4998]', 'inflected', 'heb', 'נָאוֶה', '["nâʼveh"]', '["the/ beautiful [one]"]', '["a"]', 'suitable, or beautiful becometh, comely, seemly.', 'from 4998 or 5116;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6026}/[H6026]', 'inflected', 'heb', 'עָנַג', '["ʻânag"]', '["and/ the/ dainty [one]"]', '["v"]', 'to be soft or pliable, i.e. (figuratively) effeminate or luxurious delicate(-ness), (have) delight (self), sport self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5739}/H9028/[H5737]', 'inflected', 'heb', 'עֵדֶר', '["ʻêder"]', '["and/ flocks/ their"]', '["n-m"]', 'an arrangement, i.e. muster (of animals) drove, flock, herd.', 'from 5737;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027M}/H9023/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ his"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6942J}/[H6942]', 'lemma', 'heb', 'קָדַשׁ', '["qâdash"]', '["consecrate"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5927J}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["so/ we may go up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6752}/[H6751]', 'lemma', 'heb', 'צֵלֶל', '["tsêlel"]', '["[the] shadows of"]', '["n-m"]', 'shade shadow.', 'from 6751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0759H>/H9024\', 'opaque', 'heb', 'אַרְמוֹן', '["ʼarmôwn"]', '["fortresses/ his","fortresses/ its"]', '["n-m"]', 'a citadel (from its height) castle, palace. Compare 2038.', 'from an unused root (meaning to be elevated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6097}/[H6086]', 'lemma', 'heb', 'עֵצָה', '["ʻêtsâh"]', '["wood"]', '["n-f"]', 'timber trees.', 'feminine of 6086;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8210I}/[H8210]', 'inflected', 'heb', 'שָׁפַךְ', '["shâphak"]', '["and/ pour out","so/ he may pour out"]', '["v"]', 'to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6979B}/[H7023]', 'inflected', 'heb', 'קוּר', '["qûwr"]', '["as/ keeps cool"]', '["v"]', 'to trench; by implication, to throw forth; to wall up, whether literal (to build a wall) or figurative (to estop) break down, cast out, destroy, dig.', 'a primitive root; also denominative from 7023');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4325G}/H9024/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["water/ its","waters/ its"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6979B}/[H7023]', 'lemma', 'heb', 'קוּר', '["qûwr"]', '["it has kept cool"]', '["v"]', 'to trench; by implication, to throw forth; to wall up, whether literal (to build a wall) or figurative (to estop) break down, cast out, destroy, dig.', 'a primitive root; also denominative from 7023');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7451I}/H9024/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["evil/ its"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7701}/[H7736]', 'inflected', 'heb', 'שֹׁד', '["shôd"]', '["and/ [the] devastation of","and/ devastation","and/ havoc","and/ violence"]', '["n-m"]', 'violence, ravage desolation, destruction, oppression, robbery, spoil(-ed, -er, -ing), wasting.', 'or שׁוֹד; (Job 5:21), from 7736;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3363}/[H3363]', 'lemma', 'heb', 'יָקַע', '["yâqaʻ"]', '["it should be alienated"]', '["v"]', 'properly, to sever oneself, i.e. (by implication) to be dislocated; figuratively, to abandon; causatively, to impale (and thus allow to drop to pieces by rotting) be alienated, depart, hang (up), be out of joint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3427}\/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["[was] remaining","anyone dwells","inhabitant","it is inhabited"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1219}/[H1210]', 'inflected', 'heb', 'בָּצַר', '["bâtsar"]', '["like/ a grape gatherer"]', '["v"]', 'to gather grapes; also to be isolated (i.e. inaccessible by height or fortification) cut off, (de-) fenced, fortify, (grape) gather(-er), mighty things, restrain, strong, wall (up), withhold.', 'a primitive root; to clip off; specifically (as denominative from 1210)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5552}/[H5541]', 'lemma', 'heb', 'סַלְסִלָּה', '["çalçillâh"]', '["branches"]', '["n-f"]', 'a twig (as pendulous) basket.', 'from 5541;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5437J}/[H5437]', 'inflected', 'heb', 'סָבַב', '["çâbab"]', '["and/ they will be turned over"]', '["v"]', 'to revolve, surround, or border; used in various applications, literally and figuratively bring, cast, fetch, lead, make, walk, × whirl, × round about, be about on every side, apply, avoid, beset (about), besiege, bring again, carry (about), change, cause to come about, × circuit, (fetch a) compass (about, round), drive, environ, × on every side, beset (close, come, compass, go, stand) round about, inclose, remove, return, set, sit down, turn (self) (about, aside, away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6996A}/H9028/[H6962]', 'inflected', 'heb', 'קָטָן', '["qâṭân"]', '["from/ little/ their"]', '["a"]', 'abbreviated, i.e. diminutive, literally (in quantity, size or number) or figuratively (in age or importance) least, less(-er), little (one), small(-est, one, quantity, thing), young(-er, -est).', 'or קָטֹן; from 6962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1419A}/H9028/[H1431]', 'inflected', 'heb', 'גָּדוֹל', '["gâdôwl"]', '["great/ their"]', '["a n-pr-m"]', 'great (in any sense); hence, older; also insolent aloud, elder(-est), exceeding(-ly), far, (man of) great (man, matter, thing,-er,-ness), high, long, loud, mighty, more, much, noble, proud thing, × sore, (×) very.', 'or גָּדֹל; (shortened) from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5030}/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["and/ from/ prophet"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5307J}/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["among <the>/ [those who] fall","when/ fall"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6485H}/H9038/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["[when] I have visited/ them"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H5410B>', 'inflected', 'heb', 'לנתבות', '["li/n.ti.Vot"]', '["of/ paths of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4771}/[H7280]', 'lemma', 'heb', 'מַרְגּוֹעַ', '["margôwaʻ"]', '["rest"]', '["n-m"]', 'a resting place rest.', 'from 7280;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5315G}/H9026/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["for/ self/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H9030}\', 'inflected', 'heb', 'לי ס', '["L/i"]', '["of/ me","to <the>/ me","to/ me"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0006}\/[H6]', 'inflected', 'heb', 'אָבַד', '["ʼâbad"]', '["and/ they will perish"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2388H}/H9035/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["it took hold of/ us"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1870K}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["and/ on the/ road"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6428}/[H6428]', 'inflected', 'heb', 'פָּלַשׁ', '["pâlash"]', '["and/ roll","and/ roll in ashes"]', '["v"]', 'to roll (in dust) roll (wallow) self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0665>', 'inflected', 'heb', 'באפר', '["ba./''E.fer","va./''E.fer"]', '["in <the>/ ash[es]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8563}/[H4843]', 'lemma', 'heb', 'תַּמְרוּר', '["tamrûwr"]', '["bitterness<es>"]', '["n-m"]', 'bitterness (plural as collective) × most bitter(-ly).', 'from 4843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0969}/[H974]', 'lemma', 'heb', 'בָּחוֹן', '["bâchôwn"]', '["an assayer"]', '["n-m"]', 'an assayer or metals tower.', 'from 974;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0974}/[H974]', 'inflected', 'heb', 'בָּחַן', '["bâchan"]', '["and/ you test","and/ you will test"]', '["v"]', 'to test (especially metals); generally and figuratively, to investigate examine, prove, tempt, try (trial).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4647}/[H5301]', 'lemma', 'heb', 'מַפֻּחַ', '["mappuach"]', '["[the] bellow[s]"]', '["n-m"]', 'the bellows (i.e. blower) of a forge bellows.', 'from 5301;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0784}/ /{H8535}/[H784]', 'inflected', 'heb', 'אֵשׁ', '["ʼêsh"]', '["from/ a fire/ /it is complete"]', '["n-f"]', 'fire (literally or figuratively) burning, fiery, fire, flaming, hot.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5777}/[H6080]', 'lemma', 'heb', 'עוֹפֶרֶת', '["ʻôwphereth"]', '["lead"]', '["n-m"]', 'lead (from its dusty color) lead.', 'or עֹפֶרֶת; feminine participle active of 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4611}/H9026/[H5953]', 'inflected', 'heb', 'מַעֲלָל', '["maʻălâl"]', '["and/ deeds/ your"]', '["n-m"]', 'an act (good or bad) doing, endeavour, invention, work.', 'from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8267}/[H8266]', 'inflected', 'heb', 'שֶׁקֶר', '["sheqer"]', '["<of the>/ falsehood","<the>/ deception"]', '["n-m"]', 'an untruth; by implication, a sham (often adverbial) without a cause, deceit(-ful), false(-hood, -ly), feignedly, liar, lie, lying, vain (thing), wrongfully.', 'from 8266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H1589}/[H1589]', 'inflected', 'heb', 'גָּנַב', '["gânab"]', '["¿/ will you steal"]', '["v"]', 'to thieve (literally or figuratively); by implication, to deceive carry away, × indeed, secretly bring, steal (away), get by stealth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5003}/[H5003]', 'inflected', 'heb', 'נָאַף', '["nâʼaph"]', '["and/ [who] commits adultery","and/ committing adultery","and/ will you commit adultery?"]', '["v"]', 'to commit adultery; figuratively, to apostatize adulterer(-ess), commit(-ing) adultery, woman that breaketh wedlock.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H4631}/[H5783]', 'inflected', 'heb', 'מְעָרָה', '["mᵉʻârâh"]', '["¿/ a den of"]', '["n-f"]', 'a cavern (as dark) cave, den, hole.', 'from 5783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213A}/H9046/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["did/ you"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4725}/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["and/ to the/ place"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0001G}/H9026/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["and/ to/ ancestors/ your"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7887}/[H7886]', 'inflected', 'heb', 'שִׁילֹה', '["Shîylôh"]', '["to/ Shiloh"]', '["n-pr-loc"]', 'Shiloh, a place in Palestine Shiloh.', 'or שִׁלֹה; or שִׁילוֹ; or שִׁלוֹ; from the same as 7886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0369}/H9041/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["¿/ [are] not/ you"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H2351>', 'inflected', 'heb', 'ובחצות', '["u./ve./chu.Tzot"]', '["and/ in/ [the] streets of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0001G}/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["and/ the/ fathers","and/ the/ parents"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1217}/[H1216]', 'lemma', 'heb', 'בָּצֵק', '["bâtsêq"]', '["[the] dough","dough"]', '["n-m"]', 'dough (as swelling by fermentation) dough, flour.', 'from 1216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3561}/[H3559]', 'lemma', 'heb', 'כַּוָּן', '["kavvân"]', '["cakes"]', '["n-m"]', 'something prepared, i.e. a sacrificial wafer cake.', 'from 3559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4446}/[H4427]', 'inflected', 'heb', 'מְלֶכֶת', '["mᵉleketh"]', '["for/ [the] queen of","to/ [the] queen of"]', '["n-f"]', 'a queen queen.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5258A}/[H5258]', 'inflected', 'heb', 'נָסַךְ', '["nâçak"]', '["and/ they are pouring out","and/ they poured out","and/ to pour out"]', '["v"]', 'to pour out, especially a libation, or to cast (metal); by analogy, to anoint a king cover, melt, offer, (cause to) pour (out), set (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440L}/H9028\/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["faces/ their"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3318H}/H9040/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["brought out/ I"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0530}/[H529]', 'inflected', 'heb', 'אֱמוּנָה', '["ʼĕmûwnâh"]', '["<the>/ faithfulness"]', '["n-f"]', 'literally firmness; figuratively security; morally fidelity faith(-ful, -ly, -ness, (man)), set office, stability, steady, truly, truth, verily.', 'or (shortened) אֱמֻנָה; feminine of 529;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6310G}/H9028\/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["from/ mouth/ their"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5145I}/H9022/[H5144]', 'inflected', 'heb', 'נֶזֶר', '["nezer"]', '["hair/ your"]', '["n-m"]', 'properly, something set apart, i.e. (abstractly) dedication (of a priet or Nazirite); hence (concretely) unshorn locks; also (by implication) a chaplet (especially of royalty) consecration, crown, hair, separation.', 'or נֵזֶר; from 5144;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7015}/[H6969]', 'lemma', 'heb', 'קִינָה', '["qîynâh"]', '["[is] a lamentation","a lamentation","lamentation","lamentations"]', '["n-f"]', 'a dirge (as accompanied by beating the breasts or on instruments) lamentation.', 'from 6969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2930A}/H9033/[H2930]', 'inflected', 'heb', 'טָמֵא', '["ṭâmêʼ"]', '["to/ make unclean/ it"]', '["v"]', 'to be foul, especially in a ceremial or moral sense (contaminated) defile (self), pollute (self), be (make, make self, pronounce) unclean, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8313}/[H8313]', 'inflected', 'heb', 'שָׂרַף', '["sâraph"]', '["to/ burn"]', '["v"]', 'to be (causatively, set) on fire (cause to, make a) burn((-ing), up) kindle, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3820A}/H9020\/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["heart/ my"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1516Q}/[H1466]', 'inflected', 'heb', 'גַּיְא', '["gayʼ"]', '["and/ [the] valley of"]', '["n"]', 'a gorge (from its lofty sides; hence, narrow, but not a gully or winter-torrent) valley.', 'or (shortened) גַּי; probably (by transmutation) from the same root as 1466 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1516S}/[H1466]', 'lemma', 'heb', 'גַּיְא', '["gayʼ"]', '["[the] valley of"]', '["n"]', 'a gorge (from its lofty sides; hence, narrow, but not a gully or winter-torrent) valley.', 'or (shortened) גַּי; probably (by transmutation) from the same root as 1466 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2028G}/[H2027]', 'inflected', 'heb', 'הֲרֵגָה', '["hărêgâh"]', '["<the>/ slaughter"]', '["n-f"]', 'slaughter slaughter.', 'feminine of 2027;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8612}/[H8611]', 'inflected', 'heb', 'תֹּפֶת', '["Tôpheth"]', '["in/ Topheth"]', '["n-pr-loc"]', 'Topheth, a place near Jerusalem Tophet, Topheth.', 'the same as 8611;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6913}/H9028/[H6912]', 'inflected', 'heb', 'קֶבֶר', '["qeber"]', '["from/ graves/ their"]', '["n-m"]', 'a sepulchre burying place, grave, sepulchre.', 'or (feminine) קִבְרָה; from 6912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7849}/H9038/[H7849]', 'inflected', 'heb', 'שָׁטַח', '["shâṭach"]', '["and/ they will spread out/ them"]', '["v"]', 'to expand all abroad, enlarge, spread, stretch out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0157G}/H9038/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["I will love/ them","they loved/ them"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1875}/H9038/[H1875]', 'inflected', 'heb', 'דָּרַשׁ', '["dârash"]', '["they consulted/ them"]', '["v"]', 'properly, to tread or frequent; usually to follow (for pursuit or search); by implication, to seek or ask; specifically to worship ask, × at all, care for, × diligently, inquire, make inquisition, (necro-) mancer, question, require, search, seek (for, out), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H1828>', 'inflected', 'heb', 'לדמן', '["le./Do.men"]', '["<into>/ dung"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5307G}/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["¿/ do people fall","¿/ does it fall"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8649B}/[H7411]', 'inflected', 'heb', 'תׇּרְמָה', '["tormâh"]', '["on <the>/ deceitfulness"]', '["n-f"]', 'fraud deceit(-ful), privily.', 'and תַּרְמוּת; or תַּרְמִית; from 7411;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4794}/H9028/[H4793]', 'inflected', 'heb', 'מְרוּצָה', '["mᵉrûwtsâh"]', '["in/ own course/ their"]', '["n-f"]', 'a race (the act), whether the manner or the progress course, running. Compare 4835.', 'or מְרֻצָה; feminine of 4793;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4150G}/H9024/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["appointed times/ its"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5483A>', 'inflected', 'heb', 'וסיס', '["ve./sus"]', '["and/ a swift"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5693>', 'inflected', 'heb', 'ועגור', '["ve./''a.Gur"]', '["and/ a crane"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5486}/H9038/[H5486]', 'inflected', 'heb', 'סוּף', '["çûwph"]', '["I will make an end of/ them"]', '["v"]', 'to snatch away, i.e. terminate consume, have an end, perish, × be utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H1612>', 'inflected', 'heb', 'בגפנים', '["ba./Ge.fen","ba./ge.fa.Nim"]', '["on the/ vine","on the/ vines"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8384}/[H8384]', 'inflected', 'heb', 'תְּאֵן', '["tᵉʼên"]', '["on the/ fig tree","on/ a fig tree"]', '["n-f"]', 'the fig (tree or fruit) fig (tree).', 'or (in the singular, feminine) תְּאֵנָה; perhaps of foreign derivation');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5929}/[H5927]', 'inflected', 'heb', 'עָלֶה', '["ʻâleh"]', '["and/ the/ leafage"]', '["n-m"]', 'a leaf (as coming up on a tree); collectively, foliage branch, leaf.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5674A}/H9038/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["they will pass away/ them"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1826I}/[H1724]', 'inflected', 'heb', 'דָּמַם', '["dâmam"]', '["so/ we may perish"]', '["v"]', 'to be dumb; by implication, to be astonished, to stop; also to perish cease, be cut down (off), forbear, hold peace, quiet self, rest, be silent, keep (put to) silence, be (stand) still, tarry, wait.', 'a primitive root (compare 1724, 1820);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1826I}/H9035/[H1724]', 'inflected', 'heb', 'דָּמַם', '["dâmam"]', '["he has silenced/ us"]', '["v"]', 'to be dumb; by implication, to be astonished, to stop; also to perish cease, be cut down (off), forbear, hold peace, quiet self, rest, be silent, keep (put to) silence, be (stand) still, tarry, wait.', 'a primitive root (compare 1724, 1820);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8248H}/H9035/[H8248]', 'inflected', 'heb', 'שָׁקָה', '["shâqâh"]', '["and/ he has given to drink/ us"]', '["v"]', 'to quaff, i.e. (causatively) to irrigate or furnish a potion to cause to (give, give to, let, make to) drink, drown, moisten, water. See 7937, 8354.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1205}/[H1204]', 'lemma', 'heb', 'בְּעָתָה', '["bᵉʻâthâh"]', '["terror"]', '["n-f"]', 'fear trouble.', 'from 1204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5170B>', 'opaque', 'heb', 'נַחַר', '["nachar"]', '["[the] snorting of"]', '["n-m"]', 'a snorting nostrils, snorting.', 'and (feminine) נַחֲרָה; from an unused root meaning to snort or snore;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4684}/[H6670]', 'lemma', 'heb', 'מַצְהָלָה', '["matshâlâh"]', '["[the] neighings of"]', '["n-f"]', 'a whinnying (through impatience for battle or lust) neighing.', 'from 6670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4010}/H9020/[H1082]', 'inflected', 'heb', 'מַבְלִיגִית', '["mablîygîyth"]', '["cheerfulness/ my"]', '["n-f"]', 'desistance (or rather desolation) comfort self.', 'from 1082;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3068G}/[H1961]', 'inflected', 'heb', 'יְהֹוָה', '["Yᵉhôvâh"]', '["¿/ [is] Yahweh"]', '["n-pr"]', '(the) self-Existent or Eternal; Jeho-vah, Jewish national name of God Jehovah, the Lord. Compare 3050, 3069.', 'from 1961;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6456}/H9028/[H6458]', 'inflected', 'heb', 'פְּסִיל', '["pᵉçîyl"]', '["by/ idols/ their"]', '["n-m"]', 'an idol carved (graven) image, quarry.', 'from 6458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2388H}/H9030/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["it has taken hold of/ me"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/<H6875>', 'inflected', 'heb', 'הצרי', '["ha./tzo.Ri"]', '["¿/ balm"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0732}/[H732]', 'lemma', 'heb', 'אָרַח', '["ʼârach"]', '["travelers"]', '["v"]', 'to travel go, wayfaring (man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6117}/[H6119]', 'lemma', 'heb', 'עָקַב', '["ʻâqab"]', '["certainly <to cheat>","he cheats","he took by [the] heel"]', '["v"]', 'to seize by the heel; figuratively, to circumvent (as if tripping up the heels); also to restrain (as if holding by the heel) take by the heel, stay, supplant, × utterly.', 'a primitive root; properly, to swell out or up; used only as denominative from 6119,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6884}/H9038/[H6884]', 'inflected', 'heb', 'צָרַף', '["tsâraph"]', '["[am] about to refine/ them"]', '["v"]', 'to fuse (metal), i.e. refine (literally or figuratively) cast, (re-) fine(-er), founder, goldsmith, melt, pure, purge away, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0974}/H9038/[H974]', 'inflected', 'heb', 'בָּחַן', '["bâchan"]', '["and/ I will test/ them"]', '["v"]', 'to test (especially metals); generally and figuratively, to investigate examine, prove, tempt, try (trial).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0696}/H9023/[H695]', 'inflected', 'heb', 'אֹרֶב', '["ʼôreb"]', '["ambush/ his"]', '["n-m"]', 'wait.', 'the same as 695');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5092}/[H5091]', 'inflected', 'heb', 'נְהִי', '["nᵉhîy"]', '["and/ wailing"]', '["n-m"]', 'an elegy lamentation, wailing.', 'from 5091;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414Q}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I will make"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5674A}\/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["[one who] passes by"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5800A}/H9048/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["have forsaken/ they"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3939>', 'opaque', 'heb', 'לַעֲנָה', '["laʻănâh"]', '["wormwood"]', '["n-f"]', 'wormwood (regarded as poisonous, and therefore accursed) hemlock, wormwood.', 'from an unused root supposed to mean to curse;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3615H}/H9040/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["have made an end of/ I"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0853}/H9038\/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["<obj.>/ them"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6969}/[H6969]', 'inflected', 'heb', 'קוּן', '["qûwn"]', '["<to> the/ wailing [women]"]', '["v"]', 'to strike a musical note, i.e. chant or wail (at a funeral) lament, mourning woman.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5092}/[H5091]', 'lemma', 'heb', 'נְהִי', '["nᵉhîy"]', '["<of> lamentation","a mourning song","a wailing","wailing"]', '["n-m"]', 'an elegy lamentation, wailing.', 'from 5091;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6079}/H9025/[H5774]', 'inflected', 'heb', 'עַפְעַף', '["ʻaphʻaph"]', '["and/ eyelids/ our"]', '["n-m"]', 'an eyelash (as fluttering); figuratively, morning ray dawning, eye-lid.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4908}/H9025\/[H7931]', 'inflected', 'heb', 'מִשְׁכָּן', '["mishkân"]', '["dwellings/ our"]', '["n-m"]', 'a residence (including a shepherd''s hut, the lair of animals, figuratively, the grave; also the Temple); specifically, the Tabernacle (properly, its wooden walls) dwelleth, dwelling (place), habitation, tabernacle, tent.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0802I}/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["and/ every woman"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2474}/H9025/[H2474]', 'inflected', 'heb', 'חַלּוֹן', '["challôwn"]', '["in/ windows/ our"]', '["n"]', 'a window (as perforated) window.', NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0759G>/H9025', 'inflected', 'heb', 'בארמנותינו', '["be./''ar.me.no.Tei./nu"]', '["in/ fortresses/ our","on/ fortresses/ our"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H5995}/[H6014]', 'inflected', 'heb', 'עָמִיר', '["ʻâmîyr"]', '["and/ like/ cut grain"]', '["n-m"]', 'a bunch of grain handful, sheaf.', 'from 6014;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0622}\/[H622]', 'inflected', 'heb', 'אָסַף', '["ʼâçaph"]', '["[will be one who] gathers"]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6190H}/[H6189]', 'inflected', 'heb', 'עׇרְלָה', '["ʻorlâh"]', '["in/ a foreskin"]', '["n-f"]', 'the prepuce foreskin, uncircumcised.', 'feminine of 6189;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0226G}/[H225]', 'inflected', 'heb', 'אוֹת', '["ʼôwth"]', '["and/ from/ [the] signs of"]', '["n-f"]', 'a signal (literally or figuratively), as a flag, beacon, monument, omen, prodigy, evidence, etc. mark, miracle, (en-) sign, token.', 'probably from 225 (in the sense of appearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3772G}/H9033/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["someone has cut down/ it"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H4621>', 'inflected', 'heb', 'במעצד', '["Ba./ma.''a.Tzad"]', '["with <the>/ tool"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3302}/H9033/[H3302]', 'inflected', 'heb', 'יָפָה', '["yâphâh"]', '["he beautifies/ it"]', '["v"]', 'properly, to be bright, i.e. (by implication) beautiful be beautiful, be (make self) fair(-r), deck.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2388H}/H9038/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["they make strong/ them"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8560}/[H8558]', 'inflected', 'heb', 'תֹּמֶר', '["tômer"]', '["[are] like/ a scarecrow of"]', '["n-m"]', 'a palm trunk palm tree.', 'from the same root as 8558;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4750}/[H7180]', 'lemma', 'heb', 'מִקְשָׁה', '["miqshâh"]', '["a cucumber field"]', '["n-f"]', 'literally a cucumbered field, i.e. a cucumber patch garden of cucumbers.', 'denominative from 7180;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2969}/[H2969]', 'lemma', 'heb', 'יָאָה', '["yâʼâh"]', '["it is befitting"]', '["v"]', 'to be suitable appertain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4438}/H9028/[H4427]', 'inflected', 'heb', 'מַלְכוּת', '["malkûwth"]', '["kingdom/ their","reign/ their"]', '["n-f"]', 'a rule; concretely, a dominion empire, kingdom, realm, reign, royal.', 'or מַלְכֻת; or (in plural) מַלְכֻיָּה; from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3688}/[H3688]', 'inflected', 'heb', 'כָּסַל', '["kâçal"]', '["and/ they may be foolish"]', '["v"]', 'properly, to be fat, i.e. (figuratively) silly be foolish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8659H}/[H8658]', 'inflected', 'heb', 'תַּרְשִׁישׁ', '["Tarshîysh"]', '["from/ Tarshish"]', '["n-pr-m n-pr-loc"]', 'Tarshish, a place on the Mediterranean, hence, the ephithet of a merchant vessel (as if for or from that port); also the name of a Persian and of an Israelite Tarshish, Tharshish.', 'probably the same as 8658 (as the region of the stone, or the reverse);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0210}/[H211]', 'inflected', 'heb', 'אוּפָז', '["ʼÛwphâz"]', '["from/ Uphaz"]', '["n-pr-loc"]', 'Uphaz, a famous gold region Uphaz.', 'perhaps a corruption of 211;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3830}/H9028/[H3847]', 'inflected', 'heb', 'לְבוּשׁ', '["lᵉbûwsh"]', '["clothing/ their"]', '["n-m"]', 'a garment (literally or figuratively); by implication (euphemistically) a wife apparel, clothed with, clothing, garment, raiment, vestment, vesture.', 'or לְבֻשׁ; from 3847;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7110A}/H9023/[H7107]', 'inflected', 'heb', 'קֶצֶף', '["qetseph"]', '["from/ wrath/ his"]', '["n-m"]', 'a splinter (as chipped off); figuratively, rage or strife foam, indignation, × sore, wrath.', 'from 7107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2195}/H9023\/[H2194]', 'inflected', 'heb', 'זַעַם', '["zaʻam"]', '["indignation/ his"]', '["n-m"]', 'strictly froth at the mouth, i.e. (figuratively) fury (especially of God''s displeasure with sin) angry, indignation, rage.', 'from 2194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1836}/[H1791]', 'inflected', 'arc', 'דֵּן', '["dên"]', '["like/ this"]', '["d"]', 'this (afore-) time, after this manner, here (-after), one...another, such, there(-fore), these, this (matter), thus, where(-fore), which.', '(Aramaic) an orthographical variation of 1791;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0778}/H9010/[H772]', 'inflected', 'arc', 'אֲרַק', '["ʼăraq"]', '["and/ earth/ the"]', '["n-f"]', 'the earth earth.', '(Aramaic) by transmutation for 772;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0007}/[H6]', 'lemma', 'arc', 'אֲבַד', '["ʼăbad"]', '["may they perish","they will destroy","you destroy"]', '["v"]', 'destroy, perish.', '(Aramaic) corresponding to 6');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0772I}/H9010/[H776]', 'inflected', 'arc', 'אֲרַע', '["ʼăraʻ"]', '["from/ earth/ the"]', '["n-m"]', 'the earth; by implication (figuratively) low earth, interior.', '(Aramaic) corresponding to 776;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8460}/[H8478]', 'lemma', 'arc', 'תְּחוֹת', '["tᵉchôwth"]', '["under"]', '["prep"]', 'beneath under.', '(Aramaic) or תּחֹת; (Aramaic), corresponding to 8478;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0429}\/[H428]', 'inflected', 'arc', 'אֵלֶּה', '["ʼêlleh"]', '["these"]', '["d"]', 'these.', '(Aramaic) corresponding to 428');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414M}/H9043/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["giving forth/ he"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1847}/[H3045]', 'inflected', 'heb', 'דַּעַת', '["daʻath"]', '["from/ knowledge"]', '["n"]', 'knowledge cunning, (ig-) norantly, know(-ledge), (un-) awares (wittingly).', 'from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6459}/[H6458]', 'inflected', 'heb', 'פֶּסֶל', '["peçel"]', '["from/ [the] idol"]', '["n-m"]', 'an idol carved (graven) image.', 'from 6458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8595}/[H8591]', 'lemma', 'heb', 'תַּעְתֻּעַ', '["taʻtuaʻ"]', '["mockery"]', '["n-m"]', 'a fraud error.', 'from 8591;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3666}/H9022/[H3665]', 'inflected', 'heb', 'כִּנְעָה', '["kinʻâh"]', '["bundle/ your"]', '["n-f"]', 'a package wares.', 'from 3665 in the sense of folding (compare 3664);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4692}\/[H6696]', 'inflected', 'heb', 'מָצוֹר', '["mâtsôwr"]', '["in the/ siege"]', '["n-m"]', 'something hemming in, i.e. (objectively) a mound (of besiegers), (abstractly) a siege, (figuratively) distress; or (subjectively) a fastness besieged, bulwark, defence, fenced, fortress, siege, strong (hold), tower.', 'or מָצוּר; from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7667}/H9020/[H7665]', 'inflected', 'heb', 'שֶׁבֶר', '["sheber"]', '["fracture/ my"]', '["n-m"]', 'a fracture, figuratively, ruin; specifically, a solution (of a dream) affliction, breach, breaking, broken(-footed, -handed), bruise, crashing, destruction, hurt, interpretation, vexation.', 'or שֵׁבֶר; from 7665;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4347}/H9020/[H5221]', 'inflected', 'heb', 'מַכָּה', '["makkâh"]', '["wound/ my"]', '["n-f"]', 'a blow (in 2 Chronicles 2:10, of the flail); by implication, a wound; figuratively, carnage, also pestilence beaten, blow, plague, slaughter, smote, × sore, stripe, stroke, wound(-ed).', 'or (masculine) מַכֶּה; (plural only) from 5221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5375H}/H9033/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ I will endure/ it"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4340}/H9020/[H3498]', 'inflected', 'heb', 'מֵיתָר', '["mêythâr"]', '["tent cords/ my"]', '["n-m"]', 'a cord (of a tent); or the string (of a bow) cord, string.', 'from 3498; (compare 3499)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3318G}/H9030/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["they have gone out from/ me"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6327A}\/[H6327]', 'inflected', 'heb', 'פּוּץ', '["pûwts"]', '["it has been scattered"]', '["v"]', 'to dash in pieces, literally or figuratively (especially to disperse) break (dash, shake) in (to) pieces, cast (abroad), disperse (selves), drive, retire, scatter (abroad), spread abroad.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7494}/[H7493]', 'inflected', 'heb', 'רַעַשׁ', '["raʻash"]', '["and/ a din"]', '["n-m"]', 'vibration, bounding, uproar commotion, confused noise, earthquake, fierceness, quaking, rattling, rushing, shaking.', 'from 7493;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8577A}\/[H8565]', 'inflected', 'heb', 'תַּנִּין', '["tannîyn"]', '["jackals"]', '["n-m"]', 'a marine or land monster, i.e. sea-serpent or jackal dragon, sea-monster, serpent, whale.', 'or תַּנִּים; (Ezekiel 29:3), intensive from the same as 8565;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4591}/H9030/[H4591]', 'inflected', 'heb', 'מָעַט', '["mâʻaṭ"]', '["you should diminish/ me"]', '["v"]', 'properly, to pare off, i.e. lessen; intransitively, to be (or causatively, to make) small or few (or figuratively, ineffective) suffer to decrease, diminish, (be, × borrow a, give, make) few (in number, -ness), gather least (little), be (seem) little, (× give the) less, be minished, bring to nothing.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3615H}/H9033/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["and/ it will destroy/ it","and/ they have made an end of/ him"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8074G}\/[H8074]', 'inflected', 'heb', 'שָׁמֵם', '["shâmêm"]', '["[one who] is desolate","they have devastated"]', '["v"]', 'to stun (or intransitively, grow numb), i.e. devastate or (figuratively) stupefy (both usually in a passive sense) make amazed, be astonied, (be an) astonish(-ment), (be, bring into, unto, lay, lie, make) desolate(-ion, places), be destitute, destroy (self), (lay, lie, make) waste, wonder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0001G}/H9026/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["<in>/ ancestors/ your"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3427}/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["and/ among/ [the] inhabitants of","and/ on/ [the] inhabitants of"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1168A}\/[H1167]', 'inflected', 'heb', 'בַּעַל', '["Baʻal"]', '["to <the>/ Baal"]', '["n-pr-m n-pr-loc"]', 'Baal, a Phoenician deity Baal, (plural) Baalim.', 'the same as 1167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7451C}/H9028\/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["calamity/ their"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4209}/H9011/[H2161]', 'inflected', 'heb', 'מְזִמָּה', '["mᵉzimmâh"]', '["<the>/ plan/ <towards>"]', '["n-f"]', 'a plan, usually evil (machination), sometimes good (sagacity) (wicked) device, discretion, intent, witty invention, lewdness, mischievous (device), thought, wickedly.', 'from 2161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8034}/H9022/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["name/ your"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1999>', 'opaque', 'heb', 'הֲמֻלָּה', '["hămullâh"]', '["a rainstorm"]', '["n-f"]', 'a sound speech, tumult.', 'or (too fully) הֲמוּלָּה; (Jeremiah 11:16), feminine passive participle of an unused root meaning to rush (as rain with a windy roar);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7489B}/[H7489]', 'inflected', 'heb', 'רָעַע', '["râʻaʻ"]', '["and/ they are bad"]', '["v"]', 'properly, to spoil (literally, by breaking to pieces); figuratively, to make (or be) good for nothing, i.e. bad (physically, socially or morally) afflict, associate selves (by mistake for 7462), break (down, in pieces), displease, (be, bring, do) evil (doer, entreat, man), show self friendly (by mistake for 7462), do harm, (do) hurt, (behave self, deal) ill, × indeed, do mischief, punish, still, vex, (do) wicked (doer, -ly), be (deal, do) worse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1808}/H9023/[H1802]', 'inflected', 'heb', 'דָּלִיָּה', '["dâlîyâh"]', '["branches/ its"]', '["n-f"]', 'something dangling, i.e. a bough branch.', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5193}/[H5193]', 'inflected', 'heb', 'נָטַע', '["nâṭaʻ"]', '["who/ planted"]', '["v"]', 'properly, to strike in, i.e. fix; specifically, to plant (literally or figuratively) fastened, plant(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H3532>', 'inflected', 'heb', 'ככבש', '["ke./Khe.ves"]', '["[had been] like/ a lamb","like/ a lamb"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3772I}/H9033/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["and/ let us cut off/ him"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5360}/H9021/[H5359]', 'inflected', 'heb', 'נְקָמָה', '["nᵉqâmâh"]', '["vengeance/ your"]', '["n-f"]', 'avengement, whether the act or the passion avenge, revenge(-ing), vengeance.', 'feminine of 5359;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7379}/H9020\/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["case/ my"]', '["n-m"]', 'a contest (personal or legal) adversary, cause, chiding, contend(-tion), controversy, multitude (from the margin), pleading, strife, strive(-ing), suit.', 'or רִב; from 7378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027G}/H9025\/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["by/ hand/ our"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6486}/H9028\/[H6485]', 'inflected', 'heb', 'פְּקֻדָּה', '["pᵉquddâh"]', '["punishment/ their"]', '["n-f"]', 'visitation (in many senses, chiefly official) account, (that have the) charge, custody, that which...laid up, numbers, office(-r), ordering, oversight, prison, reckoning, visitation.', 'feminine passive participle of 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0899A}/[H898]', 'lemma', 'heb', 'בֶּגֶד', '["beged"]', '["treachery"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5193}/H9038/[H5193]', 'inflected', 'heb', 'נָטַע', '["nâṭaʻ"]', '["you have planted/ them"]', '["v"]', 'properly, to strike in, i.e. fix; specifically, to plant (literally or figuratively) fastened, plant(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3629}/H9028/[H3627]', 'inflected', 'heb', 'כִּלְיָה', '["kilyâh"]', '["from/ kidneys/ their"]', '["n-f"]', 'a kidney (as an essential organ); figuratively, the mind (as the interior self) kidneys, reins.', 'feminine of 3627 (only in the plural);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5423}/H9038/[H5423]', 'inflected', 'heb', 'נָתַק', '["nâthaq"]', '["drag away/ them"]', '["v"]', 'to tear off break (off), burst, draw (away), lift up, pluck (away, off), pull (out), root out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2878}/[H2874]', 'inflected', 'heb', 'טִבְחָה', '["ṭibchâh"]', '["to/ slaughter"]', '["n-f"]', 'flesh, slaughter.', 'feminine of 2874 and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6942J}/H9038/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["and/ set apart/ them"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2028H}\/[H2027]', 'inflected', 'heb', 'הֲרֵגָה', '["hărêgâh"]', '["slaughter"]', '["n-f"]', 'slaughter slaughter.', 'feminine of 2027;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0319}/H9025/[H310]', 'inflected', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["end/ our"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3811}/H9031/[H3811]', 'inflected', 'heb', 'לָאָה', '["lâʼâh"]', '["and/ they have made weary/ you"]', '["v"]', 'to tire; (figuratively) to be (or make) disgusted faint, grieve, lothe, (be, make) weary (selves).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8474}/[H2734]', 'lemma', 'heb', 'תַּחָרָה', '["tachârâh"]', '["[are] competing","will you compete"]', '["v"]', 'to vie with a rival close, contend.', 'a facitious root from 2734 through the idea of the heat of jealousy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2896C}\/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["good things"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3033}/[H3039]', 'lemma', 'heb', 'יְדִדוּת', '["yᵉdidûwth"]', '["[the] beloved one of"]', '["n-f"]', 'properly, affection; concretely, a darling object dearly beloved.', 'from 3039;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0341}/H9024/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["enemies/ her"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5861}/[H5860]', 'inflected', 'heb', 'עַיִט', '["ʻayiṭ"]', '["that/ [are] bird[s] of prey?","¿/ a bird of prey"]', '["n-m"]', 'a hawk or other bird of prey bird, fowl, ravenous (bird).', 'from 5860;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6641}/[H6648]', 'lemma', 'heb', 'צָבוּעַ', '["tsâbûwaʻ"]', '["speckled"]', '["a"]', 'dyed (in stripes), i.e. the hyena speckled.', 'passive participle of the same as 6648;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2513A}/H9020/[H2506]', 'inflected', 'heb', 'חֶלְקָה', '["chelqâh"]', '["portion/ my"]', '["n-f"]', 'properly, smoothness; figuratively, flattery; also an allotment field, flattering(-ry), ground, parcel, part, piece of land (ground), plat, portion, slippery place, smooth (thing).', 'feminine of 2506;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2532A}/H9020/[H2531]', 'inflected', 'heb', 'חֶמְדָּה', '["chemdâh"]', '["desire/ my"]', '["n-f"]', 'delight desire, goodly, pleasant, precious.', 'feminine of 2531;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8076}/[H8074]', 'inflected', 'heb', 'שָׁמֵם', '["shâmêm"]', '["into/ a desolation"]', '["a"]', 'ruined desolate.', 'from 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1320}\/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["flesh"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8393}/H9026/[H935]', 'inflected', 'heb', 'תְּבוּאָה', '["tᵉbûwʼâh"]', '["from/ produce<s>/ your"]', '["n-f"]', 'income, i.e. produce (literally or figuratively) fruit, gain, increase, revenue.', 'from 935;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7934}/H9020/[H7931]', 'inflected', 'heb', 'שָׁכֵן', '["shâkên"]', '["neighbors/ my"]', '["a"]', 'a resident; by extension, a fellow-citizen inhabitant, neighbour, nigh.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5428}/H9038/[H5428]', 'inflected', 'heb', 'נָתַשׁ', '["nâthash"]', '["[am] about to pluck up/ them"]', '["v"]', 'to tear away destroy, forsake, pluck (out, up, by the roots), pull up, root out (up), × utterly. s', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5428}/H9040/[H5428]', 'inflected', 'heb', 'נָתַשׁ', '["nâthash"]', '["have plucked up/ I"]', '["v"]', 'to tear away destroy, forsake, pluck (out, up, by the roots), pull up, root out (up), × utterly. s', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7725J}/H9038/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ I will bring back/ them"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0232}/[H246]', 'inflected', 'heb', 'אֵזוֹר', '["ʼêzôwr"]', '["<the>/ loincloth","the/ loincloth"]', '["n-m"]', 'something girt; a belt, also a band girdle.', 'from 246;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4975>/H9020\', 'opaque', 'heb', 'מֹתֶן', '["môthen"]', '["loins/ my"]', '["n-m"]', 'properly, the waist or small of the back; only in plural the loins greyhound, loins, side.', 'from an unused root meaning to be slender;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6578>/H9011', 'opaque', 'heb', 'פְּרָת', '["Pᵉrâth"]', '["Perath/ towards"]', '["n-pr-m"]', 'Perath (i.e. Euphrates), a river of the East Euphrates.', 'from an unused root meaning to break forth; rushing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2934}/H9033/[H2934]', 'inflected', 'heb', 'טָמַן', '["ṭâman"]', '["and/ hide/ it"]', '["v"]', 'to hide (by covering over) hide, lay privily, in secret.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H5357>', 'inflected', 'heb', 'בנקיק', '["bi/n.Kik"]', '["in/ [the] cleft of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6578>', 'inflected', 'heb', 'בפרת', '["bi/f.Rat"]', '["at/ Perath"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2934}/H9033/[H2934]', 'inflected', 'heb', 'טָמַן', '["ṭâman"]', '["to/ hide/ it"]', '["v"]', 'to hide (by covering over) hide, lay privily, in secret.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2934}/H9033/[H2934]', 'inflected', 'heb', 'טָמַן', '["ṭâman"]', '["I had hidden/ it"]', '["v"]', 'to hide (by covering over) hide, lay privily, in secret.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3987}/[H3985]', 'inflected', 'heb', 'מֵאֵן', '["mêʼên"]', '["who/ are refusing"]', '["a"]', 'refractory refuse.', 'from 3985;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0232}/[H246]', 'inflected', 'heb', 'אֵזוֹר', '["ʼêzôwr"]', '["like the/ loincloth"]', '["n-m"]', 'something girt; a belt, also a band girdle.', 'from 246;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8416}/[H1984]', 'inflected', 'heb', 'תְּהִלָּה', '["tᵉhillâh"]', '["and/ <into>/ praise"]', '["n-f"]', 'laudation; specifically (concretely) a hymn praise.', 'from 1984;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7943}/[H7937]', 'lemma', 'heb', 'שִׁכָּרוֹן', '["shikkârôwn"]', '["drunkenness"]', '["n-m"]', 'intoxication (be) drunken(-ness).', 'from 7937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7843}/H9038\/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["from/ destroying/ them"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6757}/[H6738]', 'inflected', 'heb', 'צַלְמָוֶת', '["tsalmâveth"]', '["into/ deep darkness"]', '["n-m"]', 'shade of death, i.e. the grave (figuratively, calamity) shadow of death.', 'from 6738 and 4194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6205}/[H6201]', 'inflected', 'heb', 'עֲרָפֶל', '["ʻărâphel"]', '["into/ thick darkness"]', '["n-m"]', 'gloom (as of a lowering sky) (gross, thick) dark (cloud, -ness).', 'probably from 6201;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1830}/[H1830]', 'inflected', 'heb', 'דָּמַע', '["dâmaʻ"]', '["and/ utterly <to weep>"]', '["v"]', 'to weep × sore, weep.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1830}/[H1830]', 'lemma', 'heb', 'דָּמַע', '["dâmaʻ"]', '["it will weep"]', '["v"]', 'to weep × sore, weep.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1377}/[H1376]', 'inflected', 'heb', 'גְּבִירָה', '["gᵉbîyrâh"]', '["and/ to the/ queen-mother"]', '["n-f"]', 'a mistress queen.', 'feminine of 1376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4761}/H9026/[H7218]', 'inflected', 'heb', 'מַרְאָשָׁה', '["marʼâshâh"]', '["[the] place of head/ your"]', '["n-f"]', 'properly, headship, i.e. (plural for collective) dominion principality.', 'denominative from 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8597}/H9026/[H6286]', 'inflected', 'heb', 'תִּפְאָרָה', '["tiphʼârâh"]', '["splendor/ your"]', '["n-f"]', 'ornament (abstractly or concretely, literally or figuratively) beauty(-iful), bravery, comely, fair, glory(-ious), honour, majesty.', 'or תִּפְאֶרֶת; from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7965L}\/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["completeness<es>"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0270}/H9032/[H270]', 'inflected', 'heb', 'אָחַז', '["ʼâchaz"]', '["will they seize/ you"]', '["v"]', 'to seize (often with the accessory idea of holding in possession) be affrighted, bar, (catch, lay, take) hold (back), come upon, fasten, handle, portion, (get, have or take) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7122I}/H9030/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["have they happened to/ me"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7757>/H9022', 'opaque', 'heb', 'שׁוּל', '["shûwl"]', '["skirts/ your"]', '["n-m"]', 'a skirt; by implication, a bottom edge hem, skirt, train.', 'from an unused root meaning to hang down;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6119}/H9022/[H6117]', 'inflected', 'heb', 'עָקֵב', '["ʻâqêb"]', '["heels/ your"]', '["n-m"]', 'a heel (as protuberant); hence, a track; figuratively, the rear (of an army) heel, (horse-) hoof, last, lier in wait (by mistake for 6120), (foot-) step.', 'or (feminine) עִקְּבָה; from 6117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H2015}/[H2015]', 'inflected', 'heb', 'הָפַךְ', '["hâphak"]', '["¿/ will he change"]', '["v"]', 'to turn about or over; by implication, to change, overturn, return, pervert × become, change, come, be converted, give, make (a bed), overthrow (-turn), perverse, retire, tumble, turn (again, aside, back, to the contrary, every way).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2272}/H9023/[H2266]', 'inflected', 'heb', 'חֲבַרְבֻּרָה', '["chăbarburâh"]', '["spots/ its"]', '["n-f"]', 'a streak (like a line), as on the tiger spot.', 'by reduplication from 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4055}/H9022/[H4058]', 'inflected', 'heb', 'מַד', '["mad"]', '["measure<s>/ your"]', '["n-m"]', 'properly, extent, i.e. height; also a measure; by implication, a vesture (as measured); also a carpet armour, clothes, garment, judgment, measure, raiment, stature.', 'or מֵד; from 4058;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440H}/H9022/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["[is] face/ your","face/ your"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7036}/H9022/[H7034]', 'inflected', 'heb', 'קָלוֹן', '["qâlôwn"]', '["shame/ your"]', '["n-m"]', 'disgrace; (by implication) the pudenda confusion, dishonour, ignominy, reproach, shame.', 'from 7034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5004}/H9022/[H5003]', 'inflected', 'heb', 'נִאֻף', '["niʼuph"]', '["adulteri<es>/ your"]', '["n-m"]', 'adultery adultery.', 'from 5003;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4684}/H9022/[H6670]', 'inflected', 'heb', 'מַצְהָלָה', '["matshâlâh"]', '["and/ neighings/ your"]', '["n-f"]', 'a whinnying (through impatience for battle or lust) neighing.', 'from 6670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2184}/H9022/[H2181]', 'inflected', 'heb', 'זְנוּת', '["zᵉnûwth"]', '["prostitution/ your"]', '["n-f"]', 'adultery, i.e. (figuratively) infidelity, idolatry whoredom.', 'from 2181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8251}/H9022/[H8262]', 'inflected', 'heb', 'שִׁקּוּץ', '["shiqqûwts"]', '["detestable things/ your"]', '["n-m"]', 'disgusting, i.e. filthy; especially idolatrous or (concretely) an idol abominable filth (idol, -ation), detestable (thing).', 'or שִׁקֻּץ; from 8262;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1226}/[H1219]', 'inflected', 'heb', 'בַּצֹּרֶת', '["batstsôreth"]', '["the/ droughts"]', '["n-f"]', 'restraint (of rain), i.e. drought dearth, drought.', 'feminine intensive from 1219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6682}/[H6681]', 'inflected', 'heb', 'צְוָחָה', '["tsᵉvâchâh"]', '["and/ [the] outcry of"]', '["n-f"]', 'a screech (of anguish) cry(-ing).', 'from 6681;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6810}/H9028/[H6819]', 'inflected', 'heb', 'צָעִיר', '["tsâʻîyr"]', '["servants/ their"]', '["a"]', 'little; (in number) few; (in age) young, (in value) ignoble least, little (one), small (one), young(-er, -est).', 'or צָעוֹר; from 6819;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6501}/[H6500]', 'inflected', 'heb', 'פֶּרֶא', '["pereʼ"]', '["and/ wild donkeys"]', '["n-m"]', 'the onager wild (ass).', 'or פֶּרֶה; (Jeremiah 2:24), from 6500 in the secondary sense of running wild;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8577A}/[H8565]', 'inflected', 'heb', 'תַּנִּין', '["tannîyn"]', '["like <the>/ jackals"]', '["n-m"]', 'a marine or land monster, i.e. sea-serpent or jackal dragon, sea-monster, serpent, whale.', 'or תַּנִּים; (Ezekiel 29:3), intensive from the same as 8565;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4878}/H9025/[H7725]', 'inflected', 'heb', 'מְשׁוּבָה', '["mᵉshûwbâh"]', '["apostasies/ our"]', '["n-f"]', 'apostasy backsliding, turning away.', 'or מְשֻׁבָה; from 7725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0732}/[H732]', 'inflected', 'heb', 'אָרַח', '["ʼârach"]', '["and/ like/ a traveler"]', '["v"]', 'to travel go, wayfaring (man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1724}/[H1740]', 'lemma', 'heb', 'דָּהַם', '["dâham"]', '["astounded"]', '["v"]', 'to be dumb, i.e. (figuratively) dumbfounded astonished.', 'a primitive root (compare 1740);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5117}/H9035\/[H5117]', 'inflected', 'heb', 'נוּחַ', '["nûwach"]', '["you abandon/ us"]', '["v"]', 'to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6485H}/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["so/ he may punish"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2403B}/H9028\/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["sins/ their"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7458}/[H7456]', 'inflected', 'heb', 'רָעָב', '["râʻâb"]', '["and/ by <the>/ famine","and/ by the/ famine","and/ with <the>/ famine"]', '["n-m"]', 'hunger (more or less extensive) dearth, famine, famished, hunger.', 'from 7456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1698}/[H1696]', 'inflected', 'heb', 'דֶּבֶר', '["deber"]', '["and/ by <the>/ pestilence","and/ with <the>/ pestilence"]', '["n-m"]', 'a pestilence murrain, pestilence, plague.', 'from 1696 (in the sense of destroying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8649B}/[H7411]', 'inflected', 'heb', 'תׇּרְמָה', '["tormâh"]', '["and/ [the] deceitfulness of"]', '["n-f"]', 'fraud deceit(-ful), privily.', 'and תַּרְמוּת; or תַּרְמִית; from 7411;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8463}/[H2456]', 'lemma', 'heb', 'תַּחֲלוּא', '["tachălûwʼ"]', '["diseases","diseases of"]', '["n-m"]', 'a malady disease, × grievous, (that are) sick(-ness).', 'or תַּחֲלֻא; from 2456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3988A}/[H3988]', 'inflected', 'heb', 'מָאַס', '["mâʼaç"]', '["¿/ really <to reject>"]', '["v"]', 'to spurn; also (intransitively) to disappear abhor, cast away (off), contemn, despise, disdain, (become) loathe(some), melt away, refuse, reject, reprobate, × utterly, vile person.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5221}/H9035/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["have you struck/ us"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6256}/[H5703]', 'inflected', 'heb', 'עֵת', '["ʻêth"]', '["and/ for/ a time of","and/ of/ times"]', '["n-f"]', 'time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when.', 'from 5703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7562}/H9025/[H7561]', 'inflected', 'heb', 'רֶשַׁע', '["reshaʻ"]', '["wickedness/ our"]', '["n-m"]', 'a wrong (especially moral) iniquity, wicked(-ness).', 'from 7561;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1652}/[H1652]', 'lemma', 'heb', 'גָּשַׁם', '["gâsham"]', '["[those who] send rain"]', '["v"]', 'to shower violently (cause to) rain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5498}/[H5498]', 'inflected', 'heb', 'סָחַב', '["çâchab"]', '["to/ drag away"]', '["v"]', 'to trail along draw (out), tear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7843}/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["and/ to/ destroy"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7843}/H9032/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["and/ I have destroyed/ you"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4214}/[H2219]', 'inflected', 'heb', 'מִזְרֶה', '["mizreh"]', '["with/ a winnowing scoop"]', '["n-m"]', 'a winnowing shovel (as scattering the chaff) fan.', 'from 2219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5892A}/[H5782]', 'lemma', 'heb', 'עִיר', '["ʻîyr"]', '["anguish"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0928}/[H926]', 'inflected', 'heb', 'בֶּהָלָה', '["behâlâh"]', '["and/ sudden terror"]', '["n-f"]', 'panic, destruction terror, trouble.', 'from 926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8121>/H9024', 'opaque', 'heb', 'שֶׁמֶשׁ', '["shemesh"]', '["sun/ her"]', '["n"]', 'the sun; by implication, the east; figuratively, a ray, i.e. (architectural) a notched battlement east side(-ward), sun (rising), west(-ward), window. See also 1053.', 'from an unused root meaning to be brilliant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7611}/H9028/[H7604]', 'inflected', 'heb', 'שְׁאֵרִית', '["shᵉʼêrîyth"]', '["and/ remnant/ their"]', '["n-f"]', 'a remainder or residual (surviving, final) portion that had escaped, be left, posterity, remain(-der), remnant, residue, rest.', 'from 7604;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3205}/H9030/[H3205]', 'inflected', 'heb', 'יָלַד', '["yâlad"]', '["she bore/ me","you gave birth to/ me"]', '["v"]', 'to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7043}/H9030\/[H7043]', 'inflected', 'heb', 'קָלַל', '["qâlal"]', '["[are] cursing/ me"]', '["v"]', 'to be (causatively, make) light, literally (swift, small, sharp, etc.) or figuratively (easy, trifling, vile, etc.) abate, make bright, bring into contempt, (ac-) curse, despise, (be) ease(-y, -ier), (be a, make, make somewhat, move, seem a, set) light(-en, -er, -ly, -ly afflict, -ly esteem, thing), × slight(-ly), be swift(-er), (be, be more, make, re-) vile, whet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8281}/H9031/[H8281]', 'inflected', 'heb', 'שָׁרָה', '["shârâh"]', '["I will set free/ you"]', '["v"]', 'to free direct.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7489B}/[H7489]', 'inflected', 'heb', 'רָעַע', '["râʻaʻ"]', '["¿/ will it break"]', '["v"]', 'properly, to spoil (literally, by breaking to pieces); figuratively, to make (or be) good for nothing, i.e. bad (physically, socially or morally) afflict, associate selves (by mistake for 7462), break (down, in pieces), displease, (be, bring, do) evil (doer, entreat, man), show self friendly (by mistake for 7462), do harm, (do) hurt, (behave self, deal) ill, × indeed, do mischief, punish, still, vex, (do) wicked (doer, -ly), be (deal, do) worse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2428H}/H9021/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["wealth/ your"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0214}/H9021/[H686]', 'inflected', 'heb', 'אוֹצָר', '["ʼôwtsâr"]', '["and/ treasures/ your"]', '["n-m"]', 'a depository armory, cellar, garner, store(-house), treasure(-house) (-y).', 'from 686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3344}\/[H3344]', 'inflected', 'heb', 'יָקַד', '["yâqad"]', '["it will burn"]', '["v"]', 'to burn (be) burn(-ing), × from the hearth, kindle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6485I}/H9030/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["and/ visit/ me"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0750}/[H748]', 'inflected', 'heb', 'אָרֵךְ', '["ʼârêk"]', '["to/ [the] length of"]', '["a"]', 'long long(-suffering, -winged), patient, slow (to anger).', 'from 748;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8342}/[H7797]', 'inflected', 'heb', 'שָׂשׂוֹן', '["sâsôwn"]', '["<into>/ a joy","<into>/ joy","into/ joy"]', '["n-m"]', 'cheerfulness; specifically, welcome gladness, joy, mirth, rejoicing.', 'or שָׂשֹׂן; from 7797;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4390}/H9030\/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["you filled/ me"]', '["v"]', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly.', 'or מָלָא; (Esther 7:5), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4347}/H9020/[H5221]', 'inflected', 'heb', 'מַכָּה', '["makkâh"]', '["and/ wound/ my"]', '["n-f"]', 'a blow (in 2 Chronicles 2:10, of the flail); by implication, a wound; figuratively, carnage, also pestilence beaten, blow, plague, slaughter, smote, × sore, stripe, stroke, wound(-ed).', 'or (masculine) מַכֶּה; (plural only) from 5221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0391}/[H3576]', 'lemma', 'heb', 'אַכְזָב', '["ʼakzâb"]', '["a deceitful thing"]', '["a"]', 'falsehood; by implication treachery liar, lie.', 'from 3576;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7725H}/H9031/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ I will restore/ you"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2151B}/[H2107]', 'inflected', 'heb', 'זָלַל', '["zâlal"]', '["from/ [the] worthless"]', '["v"]', 'to shake (as in the wind), i.e. to quake; figuratively, to be loose morally, worthless or prodigal blow down, glutton, riotous (eater), vile.', 'a primitive root (compare 2107);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6310G}/H9020/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["like/ mouth/ my"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3467}/H9031/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["to/ save/ you"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5337}/H9031/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["and/ to/ deliver/ you"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5337}/H9031/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["and/ I will deliver/ you"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6184}\/[H6206]', 'inflected', 'heb', 'עָרִיץ', '["ʻârîyts"]', '["ruthless [people]"]', '["a"]', 'fearful, i.e. powerful or tyrannical mighty, oppressor, in great power, strong, terrible, violent.', 'from 6206;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0517}/H9028/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["mother/ their","mothers/ their"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4463}/[H4191]', 'lemma', 'heb', 'מָמוֹת', '["mâmôwth"]', '["[the] death<s> of","deaths of"]', '["n-m"]', 'a mortal disease; concretely, a corpse death.', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0776H>\', 'inflected', 'heb', 'הארץ ס', '["ha./''A.retz"]', '["the/ earth"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4798}/[H4797]', 'lemma', 'heb', 'מַרְזֵחַ', '["marzêach"]', '["mourning"]', '["n-m"]', 'a cry, i.e. (of grief) a lamentation mourning.', 'formed like 4797;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7356B}/[H7355]', 'inflected', 'heb', 'רַחַם', '["racham"]', '["<the>/ compassion<s>"]', '["n-f"]', 'compassion (in the plural); by extension, the womb (as cherishing the fetus); by implication, a maiden bowels, compassion, damsel, tender love, (great, tender) mercy, pity, womb.', 'from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8354}\/[H8354]', 'inflected', 'heb', 'שָׁתָה', '["shâthâh"]', '["and/ to/ drink"]', '["v"]', 'to imbibe (literally or figuratively) × assuredly, banquet, × certainly, drink(-er, -ing), drunk (× -ard), surely. (Prop. intensive of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5869A}/H9026/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["to/ eyes/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H3117G>/H9026', 'inflected', 'heb', 'ובימיכם', '["u./vi./mei./Khem"]', '["and/ in/ days/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0001G}/H9026/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["more than/ ancestors/ your"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2005}/H9046/[H2005]', 'inflected', 'heb', 'הֵן', '["hên"]', '["and/ here/ you"]', '["prt"]', 'lo!; also (as expressing surprise) if behold, if, lo, though.', 'a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0001G}/H9026/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["and/ ancestors/ your"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2594}\/[H2603]', 'inflected', 'heb', 'חֲנִינָה', '["chănîynâh"]', '["favor"]', '["n-f"]', 'graciousness favour.', 'from 2603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1771}/[H1770]', 'inflected', 'heb', 'דַּיָּג', '["dayâg"]', '["for/ fishermen"]', '["n-m"]', 'a fisherman fisher.', 'from 1770;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1770}/H9038/[H1709]', 'inflected', 'heb', 'דִּיג', '["dîyg"]', '["and/ they will fish out/ them"]', '["v"]', 'to fish fish.', 'denominative from 1709;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6719}/[H6718]', 'lemma', 'heb', 'צַיָּד', '["tsayâd"]', '["hunters"]', '["n-m"]', 'a huntsman hunter.', 'from the same as 6718;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6679A}/H9038/[H6718]', 'inflected', 'heb', 'צוּד', '["tsûwd"]', '["and/ they will hunt/ them"]', '["v"]', 'to lie alongside (i.e. in wait); by implication, to catch an animal (figuratively, men); to victual (for a journey) chase, hunt, sore, take (provision).', 'a primitive root; also denominative from 6718');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H5357>', 'inflected', 'heb', 'ומנקיקי', '["u./mi./ne.ki.Kei"]', '["and/ from/ [the] clefts of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9005/{H6440L}/H9020/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["from/ to/ before/ me"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2490H}/H9048/[H2470]', 'inflected', 'heb', 'חָלַל', '["châlal"]', '["have profaned/ they"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8441}/H9028/[H8581]', 'inflected', 'heb', 'תּוֹעֵבַה', '["tôwʻêbah"]', '["and/ abominations/ their"]', '["n-f"]', 'properly, something disgusting (morally), i.e. (as noun) an abhorrence; especially idolatry or (concretely) an idol abominable (custom, thing), abomination.', 'or תֹּעֵבַה; feminine active participle of 8581;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5159}/H9020\/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["inheritance/ my"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4581}/H9020/[H5810]', 'inflected', 'heb', 'מָעוֹז', '["mâʻôwz"]', '["and/ stronghold/ my"]', '["n-m"]', 'a fortified place; figuratively, a defence force, fort(-ress), rock, strength(-en), (× most) strong (hold).', '(also מָעוּז ); or מָעֹז (also מָעֻז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H6213H}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["¿/ will he make"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6856}/[H6852]', 'inflected', 'heb', 'צִפֹּרֶן', '["tsippôren"]', '["with/ a point of"]', '["n-m"]', 'properly, a claw, i.e. (human) nail; also the point of a style (or pen, tipped with adamant) nail, point.', 'from 6852 (in the denominative sense (from 6833) of scratching);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7161A}/[H7160]', 'inflected', 'heb', 'קֶרֶן', '["qeren"]', '["and/ to/ [the] horns of"]', '["n-f n-pr-loc"]', 'a horn (as projecting); by implication, a flask, cornet; by resemblance. an elephant''s tooth (i.e. ivory), a corner (of the altar), a peak (of a mountain), a ray (of light); figuratively, power × hill, horn.', 'from 7160;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4196}/H9026/[H2076]', 'inflected', 'heb', 'מִזְבֵּחַ', '["mizbêach"]', '["altars/ your"]', '["n-m"]', 'an altar altar.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2142}/[H2145]', 'inflected', 'heb', 'זָכַר', '["zâkar"]', '["when/ remember"]', '["v"]', 'properly, to mark (so as to be recognized), i.e. to remember; by implication, to mention; to be male × burn (incense), × earnestly, be male, (make) mention (of), be mindful, recount, record(-er), remember, make to be remembered, bring (call, come, keep, put) to (in) remembrance, × still, think on, × well.', 'a primitive root; also as denominative from 2145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2042>/H9020', 'opaque', 'heb', 'הָרָר', '["hârâr"]', '["mountain/ my"]', '["n-m"]', 'a mountain hill, mount(-ain).', 'from an unused root meaning to loom up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0214}/H9021/[H686]', 'inflected', 'heb', 'אוֹצָר', '["ʼôwtsâr"]', '["treasures/ your"]', '["n-m"]', 'a depository armory, cellar, garner, store(-house), treasure(-house) (-y).', 'from 686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8058}/[H8058]', 'inflected', 'heb', 'שָׁמַט', '["shâmaṭ"]', '["and/ you will let fall"]', '["v"]', 'to fling down; incipiently to jostle; figuratively, to let alone, desist, remit discontinue, overthrow, release, let rest, shake, stumble, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5159}/H9021/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["from/ inheritance/ your"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6176}/[H6209]', 'inflected', 'heb', 'עֲרוֹעֵר', '["ʻărôwʻêr"]', '["like/ a bush","like/ a juniper bush"]', '["n-m"]', 'a juniper (from its nudity of situation) health.', 'or עַרְעָר; from 6209 reduplicated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2788}/[H2787]', 'lemma', 'heb', 'חָרֵר', '["chârêr"]', '["parched places"]', '["n-m"]', 'arid parched place.', 'from 2787;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3105}/[H2986]', 'lemma', 'heb', 'יוּבַל', '["yûwbal"]', '["a stream"]', '["n-m"]', 'a stream river.', 'from 2986;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5929}/H9023/[H5927]', 'inflected', 'heb', 'עָלֶה', '["ʻâleh"]', '["leafage/ its"]', '["n-m"]', 'a leaf (as coming up on a tree); collectively, foliage branch, leaf.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1226}/[H1219]', 'lemma', 'heb', 'בַּצֹּרֶת', '["batstsôreth"]', '["drought"]', '["n-f"]', 'restraint (of rain), i.e. drought dearth, drought.', 'feminine intensive from 1219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6213H}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["for/ doing","from/ producing"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6121A}/[H6117]', 'lemma', 'heb', 'עָקֹב', '["ʻâqôb"]', '["[is] deceitful","tracked"]', '["a"]', '(transitive) fraudulent or (intransitive) tracked crooked, deceitful, polluted.', 'from 6117; in the original sense, a knoll (as swelling up); in the denominative sense');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3820A}/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["the/ heart"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0605}/[H605]', 'inflected', 'heb', 'אָנַשׁ', '["ʼânash"]', '["and/ [is] incurable"]', '["v"]', 'to be frail, feeble, or (figuratively) melancholy desperate(-ly wicked), incurable, sick, woeful.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1870G}/H9023/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["according to/ ways/ his"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6529}/[H6509]', 'inflected', 'heb', 'פְּרִי', '["pᵉrîy"]', '["according to/ [the] fruit of"]', '["n-m"]', 'fruit (literally or figuratively) bough, (first-)fruit(-ful), reward.', 'from 6509;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4611}/H9023\/[H5953]', 'inflected', 'heb', 'מַעֲלָל', '["maʻălâl"]', '["deeds/ his"]', '["n-m"]', 'an act (good or bad) doing, endeavour, invention, work.', 'from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7124}/[H7121]', 'lemma', 'heb', 'קֹרֵא', '["qôrêʼ"]', '["a partridge"]', '["n-m"]', 'a caller, i.e. partridge (from its cry) partridge. See also 6981.', 'properly, active participle of 7121;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1716}/[H1716]', 'lemma', 'heb', 'דָּגַר', '["dâgar"]', '["[which] it gathers a brood"]', '["v"]', 'to brood over eggs or young gather, sit.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0319}/H9023/[H310]', 'inflected', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["and/ at/ end/ his"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7223G}/[H7221]', 'inflected', 'heb', 'רִאשׁוֹן', '["riʼshôwn"]', '["from/ first [time]"]', '["a"]', 'first, in place, time or rank (as adjective or noun) ancestor, (that were) before(-time), beginning, eldest, first, fore(-father) (-most), former (thing), of old time, past.', 'or רִאשֹׁן; from 7221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4720}/H9025/[H6942]', 'inflected', 'heb', 'מִקְדָּשׁ', '["miqdâsh"]', '["sanctuary/ our"]', '["n-m"]', 'a consecrated thing or place, especially, a palace, sanctuary (whether of Jehovah or of idols) or asylum chapel, hallowed part, holy place, sanctuary.', 'or מִקְּדָשׁ; (Exodus 15:17), from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5494}/H9020/[H5493]', 'inflected', 'heb', 'סוּר', '["çûwr"]', '["and/ disloyal [ones]/ my"]', '["n-m"]', 'turned off, i.e. deteriorated degenerate.', 'probably passive participle of 5493;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4288}/[H2846]', 'inflected', 'heb', 'מְחִתָּה', '["mᵉchittâh"]', '["<into>/ an object of terror"]', '["n-f"]', 'properly, a dissolution; concretely, a ruin, or (abstractly) consternation destruction, dismaying, ruin, terror.', 'from 2846;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7670}/[H7665]', 'lemma', 'heb', 'שִׁבְרוֹן', '["shibrôwn"]', '["destruction"]', '["n-m"]', 'rupture, i.e. a pang; figuratively, ruin breaking, destruction.', 'from 7665;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7665}/H9038\/[H7665]', 'inflected', 'heb', 'שָׁבַר', '["shâbar"]', '["destroy/ them"]', '["v"]', 'to burst (literally or figuratively) break (down, off, in pieces, up), broken (-hearted), bring to the birth, crush, destroy, hurt, quench, × quite, tear, view (by mistake for 7663).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5971H}/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["the/ people"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5315H}/H9026/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["<in>/ selves/ your","to/ lives/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6942G}/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["and/ to/ set apart as holy"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H5483M>', 'inflected', 'heb', 'ובסוסים', '["u./va./su.Sim"]', '["and/ on <the>/ horses"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8269}/H9028/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["and/ officials/ their"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5439G}/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["and/ from/ round about"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8179G}/H9024/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["in/ gates/ its"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2009}/H9014/{H1931}/[H2005]', 'inflected', 'heb', 'הִנֵּה', '["hinnêh"]', '["and/ there!/-/he"]', '["dp"]', 'lo! behold, lo, see.', 'prolongation for 2005;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9004/{H3335H}/[H3334]', 'inflected', 'heb', 'יָצַר', '["yâtsar"]', '["¿/ like the/ potter"]', '["v"]', 'to mould into a form; especially as a potter; figuratively, to determine (i.e. form a resolution) × earthen, fashion, form, frame, make(-r), potter, purpose.', 'probably identical with 3334 (through the squeezing into shape); (compare 3331);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7451I}/H9023/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["from/ evil/ his","from/ evil/ its"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7281}/[H7280]', 'inflected', 'heb', 'רֶגַע', '["regaʻ"]', '["and/ a moment"]', '["n-m"]', 'a wink (of the eyes), i.e. a very short space of time instant, moment, space, suddenly.', 'from 7280.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5193}/[H5193]', 'inflected', 'heb', 'נָטַע', '["nâṭaʻ"]', '["and/ to/ plant"]', '["v"]', 'properly, to strike in, i.e. fix; specifically, to plant (literally or figuratively) fastened, plant(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2803I}/[H2803]', 'inflected', 'heb', 'חָשַׁב', '["châshab"]', '["and/ [am] about to plan","so/ let us plan"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4284}/H9025/[H2803]', 'inflected', 'heb', 'מַחֲשָׁבָה', '["machăshâbâh"]', '["own plans/ our"]', '["n-f"]', 'a contrivance, i.e. (concretely) a texture, machine, or (abstractly) intention, plan (whether bad, a plot; or good, advice) cunning (work), curious work, device(-sed), imagination, invented, means, purpose, thought.', 'or מַחֲשֶׁבֶת; from 2803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8186B}/[H8176]', 'lemma', 'heb', 'שַׁעֲרוּרָה', '["shaʻărûwrâh"]', '["a horrible [thing]"]', '["n-f"]', 'something fearful horrible thing.', 'or שַׁעֲרִירִיָּה; or שַׁעֲרֻרִת; feminine from 8176 in the sense of 8175;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5800A}/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["¿/ does it leave"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7704A>', 'opaque', 'heb', 'שָׂדֶה', '["sâdeh"]', '["[the] field"]', '["n-m"]', 'a field (as flat) country, field, ground, land, soil, × wild.', 'or שָׂדַי; from an unused root meaning to spread out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3782}/H9038/[H3782]', 'inflected', 'heb', 'כָּשַׁל', '["kâshal"]', '["and/ they have caused to stumble/ them"]', '["v"]', 'to totter or waver (through weakness of the legs, especially the ankle); by implication, to falter, stumble, faint or fall bereave (from the margin), cast down, be decayed, (cause to) fail, (cause, make to) fall (down, -ing), feeble, be (the) ruin(-ed, of), (be) overthrown, (cause to) stumble, × utterly, be weak.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1870K}/H9028/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["in/ ways/ their"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7635}/[H7640]', 'lemma', 'heb', 'שָׁבִיל', '["shâbîyl"]', '["paths of"]', '["n-m"]', 'a track or passage-way (as if flowing along) path.', 'from the same as 7640;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0343}/H9028\/[H181]', 'inflected', 'heb', 'אֵיד', '["ʼêyd"]', '["disaster/ their"]', '["n-m"]', 'oppression; by implication misfortune, ruin calamity, destruction.', 'from the same as 181 (in the sense of bending down);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3548}/[H3547]', 'inflected', 'heb', 'כֹּהֵן', '["kôhên"]', '["from/ [the] priest","from/ a priest"]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2450}/[H2449]', 'inflected', 'heb', 'חָכָם', '["châkâm"]', '["from/ [the] wise"]', '["a"]', 'wise, (i.e. intelligent, skilful or artful) cunning (man), subtil, (un-), wise((hearted), man).', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7999A}/[H7999]', 'inflected', 'heb', 'שָׁלַם', '["shâlam"]', '["¿/ will it be repaid"]', '["v"]', 'to be safe (in mind, body or estate); figuratively, to be (causatively, make) completed; by implication, to be friendly; by extension, to reciprocate (in various applications) make amends, (make an) end, finish, full, give again, make good, (re-) pay (again), (make) (to) (be at) peace(-able), that is perfect, perform, (make) prosper(-ous), recompense, render, requite, make restitution, restore, reward, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5975G}/H9040/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["standing/ my"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5064}/H9038/[H5064]', 'inflected', 'heb', 'נָגַר', '["nâgar"]', '["and/ pour/ them"]', '["v"]', 'to flow; figuratively, to stretch out; causatively, to pour out or down; figuratively, to deliver over fall, flow away, pour down (out), run, shed, spilt, trickle down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1004B}/H9028/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["from/ houses/ their"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3920}/H9030/[H3920]', 'inflected', 'heb', 'לָכַד', '["lâkad"]', '["to/ capture/ me"]', '["v"]', 'to catch (in a net, trap or pit); generally, to capture or occupy; also to choose (by lot); figuratively, to cohere × at all, catch (self), be frozen, be holden, stick together, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1228}/[H1238]', 'lemma', 'heb', 'בַּקְבֻּק', '["baqbuq"]', '["a bottle of"]', '["n-m"]', 'a bottle (from the gurgling in emptying) bottle, cruse.', 'from 1238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H2205G}/[H2204]', 'inflected', 'heb', 'זָקֵן', '["zâqên"]', '["and/ some of/ [the] elders of"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2777}/[H2775]', 'inflected', 'heb', 'חַרְסוּת', '["charçûwth"]', '["the/ potsherd"]', '["n-f"]', 'a potsherd, i.e. (by implication) a pottery; the name of a gate at Jerusalem east.', 'from 2775 (apparently in the sense of a red tile used for scraping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1516R}/[H1466]', 'inflected', 'heb', 'גַּיְא', '["gayʼ"]', '["and/ [the] valley of"]', '["n"]', 'a gorge (from its lofty sides; hence, narrow, but not a gully or winter-torrent) valley.', 'or (shortened) גַּי; probably (by transmutation) from the same root as 1466 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5307J}/H9038/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["and/ I will make fall/ them"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4347}/H9024/[H5221]', 'inflected', 'heb', 'מַכָּה', '["makkâh"]', '["wounds/ its"]', '["n-f"]', 'a blow (in 2 Chronicles 2:10, of the flail); by implication, a wound; figuratively, carnage, also pestilence beaten, blow, plague, slaughter, smote, × sore, stripe, stroke, wound(-ed).', 'or (masculine) מַכֶּה; (plural only) from 5221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1228}/[H1238]', 'inflected', 'heb', 'בַּקְבֻּק', '["baqbuq"]', '["the/ bottle"]', '["n-m"]', 'a bottle (from the gurgling in emptying) bottle, cruse.', 'from 1238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8612}/[H8611]', 'inflected', 'heb', 'תֹּפֶת', '["Tôpheth"]', '["and/ in/ Topheth"]', '["n-pr-loc"]', 'Topheth, a place near Jerusalem Tophet, Topheth.', 'the same as 8611;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3427}/H9023/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["and/ to/ inhabitants/ its"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5414I}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ to/ make"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8612}/[H8611]', 'inflected', 'heb', 'תֹּפֶת', '["Tôpheth"]', '["like/ Topheth"]', '["n-pr-loc"]', 'Topheth, a place near Jerusalem Tophet, Topheth.', 'the same as 8611;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4725}/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["like/ [the] place of"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1406}/H9028/[H1342]', 'inflected', 'heb', 'גָּג', '["gâg"]', '["roofs/ their"]', '["n-m"]', 'a roof; by analogy, the top of an altar roof (of the house), (house) top (of the house).', 'probably by reduplication from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0312}\/[H309]', 'inflected', 'heb', 'אַחֵר', '["ʼachêr"]', '["other"]', '["a"]', 'properly, hinder; generally, next, other, etc. (an-) other man, following, next, strange.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H8612}/[H8611]', 'inflected', 'heb', 'תֹּפֶת', '["Tôpheth"]', '["from/ <the>/ Topheth"]', '["n-pr-loc"]', 'Topheth, a place near Jerusalem Tophet, Topheth.', 'the same as 8611;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5012}/[H5012]', 'inflected', 'heb', 'נָבָא', '["nâbâʼ"]', '["to/ prophesy"]', '["v"]', 'to prophesy, i.e. speak (or sing) by inspiration (in prediction or simple discourse) prophesy(-ing), make self a prophet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6583I}/[H6582]', 'lemma', 'heb', 'פַּשְׁחוּר', '["Pashchûwr"]', '["O Pashhur","Pashhur"]', '["n-pr-m"]', 'Pashchur, the name of four Israelites Pashur.', 'probably from 6582; liberation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1144L}/[H1121]', 'lemma', 'heb', 'בִּנְיָמִין', '["Binyâmîyn"]', '["Benjamin"]', '["n-pr-m"]', 'Binjamin, youngest son of Jacob; also the tribe descended from him, and its territory Benjamin.', 'from 1121 and 3225; son of (the) right hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4036}/[H4032]', 'lemma', 'heb', 'מָגוֹר מִסָּבִיב', '["Mâgôwr miç-Çâbîyb"]', '["Terror"]', '["n-pr-m"]', 'Magor-mis-Sabib, a symbolic name of Pashur Magormissabib.', 'from 4032 and 5439 with the preposition inserted; affright from around;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4036}\/[H4032]', 'inflected', 'heb', 'מָגוֹר מִסָּבִיב', '["Mâgôwr miç-Çâbîyb"]', '["from/ around"]', '["n-pr-m"]', 'Magor-mis-Sabib, a symbolic name of Pashur Magormissabib.', 'from 4032 and 5439 with the preposition inserted; affright from around;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4032}/[H1481]', 'inflected', 'heb', 'מָגוֹר', '["mâgôwr"]', '["into/ a terror"]', '["n-m"]', 'a fright (objective or subjective) fear, terror. Compare 4036.', 'or (Lamentations 2:22) מָגוּר; from 1481 in the sense of fearing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5869H}/H9021/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["and/ eyes/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3366}/H9024/[H3365]', 'inflected', 'heb', 'יְקָר', '["yᵉqâr"]', '["precious thing/ its"]', '["n-m"]', 'value, i.e. (concretely) wealth; abstractly, costliness, dignity honour, precious (things), price.', 'from 3365;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0962}/H9038/[H962]', 'inflected', 'heb', 'בָּזַז', '["bâzaz"]', '["and/ they will plunder/ them"]', '["v"]', 'to plunder catch, gather, (take) for a prey, rob(-ber), spoil, take (away, spoil), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8267}\/[H8266]', 'inflected', 'heb', 'שֶׁקֶר', '["sheqer"]', '["with <the>/ falsehood"]', '["n-m"]', 'an untruth; by implication, a sham (often adverbial) without a cause, deceit(-ful), false(-hood, -ly), feignedly, liar, lie, lying, vain (thing), wrongfully.', 'from 8266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6601B}/H9030/[H6601]', 'inflected', 'heb', 'פָּתָה', '["pâthâh"]', '["you deceived/ me"]', '["v"]', 'to open, i.e. be (causatively, make) roomy; usually figuratively (in a mental or moral sense) to be (causatively, make) simple or (in a sinister way) delude allure, deceive, enlarge, entice, flatter, persuade, silly (one).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2388G}/H9030/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["you have strengthened/ me","you prevailed over/ me"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7047}/[H7046]', 'inflected', 'heb', 'קֶלֶס', '["qeleç"]', '["and/ <into>/ derision"]', '["n-m"]', 'a laughing-stock derision.', 'from 7046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5046}/H9033/[H5046]', 'inflected', 'heb', 'נָגַד', '["nâgad"]', '["and/ let us tell about/ him"]', '["v"]', 'properly, to front, i.e. stand boldly out opposite; by implication (causatively), to manifest; figuratively, to announce (always by word of mouth to one present); specifically, to expose, predict, explain, praise bewray, × certainly, certify, declare(-ing), denounce, expound, × fully, messenger, plainly, profess, rehearse, report, shew (forth), speak, × surely, tell, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6761}/H9020/[H6760]', 'inflected', 'heb', 'צֶלַע', '["tselaʻ"]', '["stumbling/ my"]', '["n-m"]', 'a limping or full (figuratively) adversity, halt(-ing).', 'from 6760;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3201}/[H3201]', 'inflected', 'arc', 'יָכֹל', '["yâkôl"]', '["and/ [it was] prevailing","and/ they prevailed","and/ we will prevail"]', '["v"]', 'to be able, literally (can, could) or morally (may, might) be able, any at all (ways), attain, can (away with, (-not)), could, endure, might, overcome, have power, prevail, still, suffer.', 'or (fuller) יָכוֹל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5360}/H9025/[H5359]', 'inflected', 'heb', 'נְקָמָה', '["nᵉqâmâh"]', '["vengeance/ our"]', '["n-f"]', 'avengement, whether the act or the passion avenge, revenge(-ing), vengeance.', 'feminine of 5359;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8055}/H9033/[H8055]', 'inflected', 'heb', 'שָׂמַח', '["sâmach"]', '["he made rejoice/ him"]', '["v"]', 'probably to brighten up, i.e. (figuratively) be (causatively, make) blithe or gleesome cheer up, be (make) glad, (have, make) joy(-ful), be (make) merry, (cause to, make to) rejoice, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6913}/H9020/[H6912]', 'inflected', 'heb', 'קֶבֶר', '["qeber"]', '["grave/ my"]', '["n-m"]', 'a sepulchre burying place, grave, sepulchre.', 'or (feminine) קִבְרָה; from 6912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7358}/H9024/[H7355]', 'inflected', 'heb', 'רֶחֶם', '["rechem"]', '["and/ womb/ her"]', '["n-m"]', 'the womb matrix, womb.', 'from 7355; (compare 7356)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117G>/H9020\', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["days/ my"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6583J}/[H6582]', 'lemma', 'heb', 'פַּשְׁחוּר', '["Pashchûwr"]', '["Pashhur"]', '["n-pr-m"]', 'Pashchur, the name of four Israelites Pashur.', 'probably from 6582; liberation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4441S}/[H4428]', 'lemma', 'heb', 'מַלְכִּיָּה', '["Malkîyâh"]', '["Malkijah"]', '["n-pr-m"]', 'Malkijah, the name of ten Israelites Malchiah, Malchijah.', 'or מַלְכִּיָּהוּlemma מַלְכִּיָהוּ missing dagesh, corrected to מַלְכִּיָּהוּ; (Jeremiah 38:6), from 4428 and 3050; king of (i.e. appointed by) Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4641X}/[H4639]', 'lemma', 'heb', 'מַעֲשֵׂיָה', '["Maʻăsêyâh"]', '["Maaseiah"]', '["n-pr-m"]', 'Maasejah, the name of sixteen Israelites Maaseiah.', 'or מַעֲשֵׂיָהוּ; from 4639 and 3050; work of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1157}/H9035/[H5704]', 'inflected', 'heb', 'בְּעַד', '["bᵉʻad"]', '["for/ us","through/ us"]', '["prep"]', 'in up to or over against; generally at, beside, among, behind, for, etc. about, at by (means of), for, over, through, up (-on), within.', 'from 5704 with prepositional prefix;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6696A}/[H6696]', 'inflected', 'heb', 'צוּר', '["tsûwr"]', '["who/ are laying siege","who/ were laying siege"]', '["v"]', 'to cramp, i.e. confine (in many applications, literally and figuratively, formative or hostile) adversary, assault, beset, besiege, bind (up), cast, distress, fashion, fortify, inclose, lay siege, put up in bags.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4585}/H9025/[H4583]', 'inflected', 'heb', 'מְעוֹנָה', '["mᵉʻôwnâh"]', '["in/ hiding places/ our"]', '["n-f"]', 'den, habitation, (dwelling) place, refuge.', 'or מְעֹנָה; feminine of 4583, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3293A>/H9024', 'inflected', 'heb', 'ביערה', '["be./ya''.Ra/h"]', '["in/ forest/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5439G}/H9034\/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["around/ it"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6216}/[H6231]', 'lemma', 'heb', 'עָשׁוֹק', '["ʻâshôwq"]', '["an oppressor"]', '["n-m"]', 'oppressive (as noun, a tyrant) oppressor.', 'from 6231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7896G}/H9031/[H7896]', 'inflected', 'heb', 'שִׁית', '["shîyth"]', '["I will make/ you"]', '["v"]', 'to place (in a very wide application) apply, appoint, array, bring, consider, lay (up), let alone, × look, make, mark, put (on), regard, set, shew, be stayed, × take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0730}/H9021/[H729]', 'inflected', 'heb', 'אֶרֶז', '["ʼerez"]', '["cedars/ your"]', '["n-m"]', 'a cedar tree (from the tenacity of its roots) cedar (tree).', 'from 729;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5647H}/H9038\/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["and/ they served/ them"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4138}/H9023\/[H3205]', 'inflected', 'heb', 'מוֹלֶדֶת', '["môwledeth"]', '["kindred/ his"]', '["n-f"]', 'nativity (plural birth-place); by implication, lineage, native country; also offspring, family begotten, born, issue, kindred, native(-ity).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7967U}/[H7966]', 'lemma', 'heb', 'שַׁלּוּם', '["Shallûwm"]', '["Shallum"]', '["n-pr-m"]', 'Shallum, the name of fourteen Israelites Shallum.', 'or (shorter) שַׁלֻּם; the same as 7966;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5944}/[H5927]', 'inflected', 'heb', 'עֲלִיָּה', '["ʻălîyâh"]', '["and/ upper rooms"]', '["n-f"]', 'something lofty, i.e. a stair-way; also a second-story room (or even one on the roof); figuratively, the sky ascent, (upper) chamber, going up, loft, parlour.', 'feminine from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7304}/[H7306]', 'lemma', 'heb', 'רָוַח', '["râvach"]', '["spacious"]', '["v"]', 'properly, to breathe freely, i.e. revive; by implication, to have ample room be refreshed, large.', 'a primitive root (identical with 7306);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2474}/H9020/[H2474]', 'inflected', 'heb', 'חַלּוֹן', '["challôwn"]', '["windows/ my"]', '["n"]', 'a window (as perforated) window.', NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8350}/[H8324]', 'inflected', 'heb', 'שָׁשַׁר', '["shâshar"]', '["with <the>/ vermilion"]', '["n-m"]', 'red ochre (from its piercing color) vermillion.', 'perhaps from the base of 8324 in the sense of that of 8320;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1215}/H9021/[H1214]', 'inflected', 'heb', 'בֶּצַע', '["betsaʻ"]', '["unjust gain/ your"]', '["n-m"]', 'plunder; by extension, gain (usually unjust) covetousness, (dishonest) gain, lucre, profit.', 'from 1214;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4835}/[H7533]', 'inflected', 'heb', 'מְרֻצָה', '["mᵉrutsâh"]', '["<the>/ extortion"]', '["n-f"]', 'oppression violence. See also 4794.', 'from 7533;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1945}/[H1930]', 'inflected', 'heb', 'הוֹי', '["hôwy"]', '["and/ alas!"]', '["inj"]', 'oh! ah, alas, ho, O, woe.', 'a prolonged form of 1930 (akin to 188);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5498}/[H5498]', 'lemma', 'heb', 'סָחַב', '["çâchab"]', '["people will drag"]', '["v"]', 'to trail along draw (out), tear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H1316>', 'inflected', 'heb', 'ובבשן', '["u./va./ba.Shan"]', '["and/ in <the>/ Bashan"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5682}/[H5676]', 'inflected', 'heb', 'עֲבָרִים', '["ʻĂbârîym"]', '["from/ Abarim"]', '["n-pr-loc"]', 'Abarim, a place in Palestine Abarim, passages.', 'plural of 5676; regions beyond;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7962}/H9022/[H7951]', 'inflected', 'heb', 'שַׁלְוָה', '["shalvâh"]', '["in/ prosperity/ your"]', '["n-f"]', 'security (genuine or false) abundance, peace(-ably), prosperity, quietness.', 'from 7951;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7462B}/H9022/[H7462]', 'inflected', 'heb', 'רָעָה', '["râʻâh"]', '["shepherds/ your"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0157G}/H9032/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["and/ lovers/ your"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3637}/[H3637]', 'inflected', 'heb', 'כָּלַם', '["kâlam"]', '["and/ you will be ashamed","and/ you will be humiliated"]', '["v"]', 'properly, to wound; but only figuratively, to taunt or insult be (make) ashamed, blush, be confounded, be put to confusion, hurt, reproach, (do, put to) shame.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3659}/[H3204]', 'lemma', 'heb', 'כׇּנְיָהוּ', '["Konyâhûw"]', '["Coniah"]', '["n-pr-m"]', 'Conjah, an Israelite king Coniah.', 'for 3204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5423}/H9031/[H5423]', 'inflected', 'heb', 'נָתַק', '["nâthaq"]', '["I will pull off/ you"]', '["v"]', 'to tear off break (off), burst, draw (away), lift up, pluck (away, off), pull (out), root out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3016}/[H3025]', 'lemma', 'heb', 'יָגוֹר', '["yâgôwr"]', '["[are] fearful"]', '["a"]', 'fearful afraid, fearest.', 'from 3025;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315L}/H9028/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["appetite/ their","being/ their","desire/ their"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725G}\/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["they will return"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H6089B}/[H6087]', 'inflected', 'heb', 'עֶצֶב', '["ʻetseb"]', '["¿/ a pot"]', '["n-m"]', 'an earthen vessel; usually (painful) toil; also a pang (whether of body or mind) grievous, idol, labor, sorrow.', 'from 6087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4830}/H9020/[H7462]', 'inflected', 'heb', 'מִרְעִית', '["mirʻîyth"]', '["pasture/ my"]', '["n-f"]', 'pasturage; concretely, a flock flock, pasture.', 'from 7462 in the sense of feeding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5080}/H9038/[H5080]', 'inflected', 'heb', 'נָדַח', '["nâdach"]', '["and/ you have driven away/ them"]', '["v"]', 'to push off; used in a great variety of applications, literally and figuratively (to expel, mislead, strike, inflict, etc.) banish, bring, cast down (out), chase, compel, draw away, drive (away, out, quite), fetch a stroke, force, go away, outcast, thrust away (out), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5116A}/H9029/[H5115]', 'inflected', 'heb', 'נָוֶה', '["nâveh"]', '["pasture/ their"]', '["n"]', '(adjectively) at home; hence (by implication of satisfaction) lovely; also (noun) a home, of God (temple), men (residence), flocks (pasture), or wild animals (den) comely, dwelling (place), fold, habitation, pleasant place, sheepcote, stable, tarried.', 'or (feminine) נָוָה; from 5115;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7919A}/[H7919]', 'inflected', 'heb', 'שָׂכַל', '["sâkal"]', '["and/ he will act prudently"]', '["v"]', 'to be (causatively, make or act) circumspect and hence, intelligent consider, expert, instruct, prosper, (deal) prudent(-ly), (give) skill(-ful), have good success, teach, (have, make to) understand(-ing), wisdom, (be, behave self, consider, make) wise(-ly), guide wittingly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6664H}/H9025\/[H6663]', 'inflected', 'heb', 'צֶדֶק', '["tsedeq"]', '["[is] righteousness/ our"]', '["n-m"]', 'the right (natural, moral or legal); also (abstractly) equity or (figuratively) prosperity × even, (× that which is altogether) just(-ice), (un-)right(-eous) (cause, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0127G}/H9028\/[H119]', 'inflected', 'heb', 'אֲדָמָה', '["ʼădâmâh"]', '["own land/ their"]', '["n-f"]', 'soil (from its general redness) country, earth, ground, husband(-man) (-ry), land.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7363A}/[H7363]', 'lemma', 'heb', 'רָחַף', '["râchaph"]', '["they have become weak"]', '["v"]', 'to brood; by implication, to be relaxed flutter, move, shake.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H1397}/[H1396]', 'inflected', 'heb', 'גֶּבֶר', '["geber"]', '["and/ like/ a man"]', '["n-m"]', 'properly, a valiant man or warrior; generally, a person simply every one, man, × mighty.', 'from 1396;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6440I}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["and/ <from>/ because of"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4794}/H9028/[H4793]', 'inflected', 'heb', 'מְרוּצָה', '["mᵉrûwtsâh"]', '["course [of life]/ their"]', '["n-f"]', 'a race (the act), whether the manner or the progress course, running. Compare 4835.', 'or מְרֻצָה; feminine of 4793;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1369}/H9028/[H1368]', 'inflected', 'heb', 'גְּבוּרָה', '["gᵉbûwrâh"]', '["and/ strength/ their"]', '["n-f"]', 'force (literally or figuratively); by implication, valor, victory force, mastery, might, mighty (act, power), power, strength.', 'feminine passive participle from the same as 1368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2519}/[H2505]', 'inflected', 'heb', 'חֲלַקְלַקָּה', '["chălaqlaqqâh"]', '["like/ slippery places"]', '["n-f"]', 'properly, something very smooth; i.e. a treacherous spot; figuratively, blandishment flattery, slippery.', 'by reduplication from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1760B}/[H1760]', 'lemma', 'heb', 'דָּחָה', '["dâchâh"]', '["they will be pushed down"]', '["v"]', 'to push down chase, drive away (on), overthrow, outcast, × sore, thrust, totter.', 'or דָּחַח; (Jeremiah 23:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5030}/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["and/ among/ [the] prophets of","and/ by/ a prophet"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8186A}/[H8176]', 'lemma', 'heb', 'שַׁעֲרוּרָה', '["shaʻărûwrâh"]', '["a horrible [thing]"]', '["n-f"]', 'something fearful horrible thing.', 'or שַׁעֲרִירִיָּה; or שַׁעֲרֻרִת; feminine from 8176 in the sense of 8175;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6017}\/[H6014]', 'inflected', 'heb', 'עֲמֹרָה', '["ʻĂmôrâh"]', '["like/ Gomorrah"]', '["n-pr-loc"]', 'Amorah, a place in Palestine Gomorrah.', 'from 6014; a (ruined) heap;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2613}/[H2610]', 'lemma', 'heb', 'חֲנֻפָה', '["chănuphâh"]', '["wicked behavior"]', '["n-f"]', 'impiety profaneness.', 'feminine from 2610;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5006}/H9030/[H5006]', 'inflected', 'heb', 'נָאַץ', '["nâʼats"]', '["to/ [those who] despise/ me"]', '["v"]', 'to scorn; or (in Ecclesiastes 12:5), by interchange for 5132, to bloom abhor, (give occasion to) blaspheme, contemn, despise, flourish, × great, provoke.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8085G}\/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["and/ has he listened?"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5591A}/[H5590]', 'inflected', 'heb', 'סַעַר', '["çaʻar"]', '["and/ a storm"]', '["n-m"]', 'a hurricane storm(-y), tempest, whirlwind.', 'or (feminine) סְעָרָה; from 5590;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213A}/H9043/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["has brought about/ he"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965I}/H9043/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["has carried out/ he"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5475}/H9020/[H3245]', 'inflected', 'heb', 'סוֹד', '["çôwd"]', '["in/ council/ my"]', '["n-m"]', 'a session, i.e. company of persons (in close deliberation); by implication, intimacy, consultation, a secret assembly, consel, inward, secret (counsel).', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7725I}/H9038/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ they will turn back/ them"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H7455}/[H7489]', 'inflected', 'heb', 'רֹעַ', '["rôaʻ"]', '["and/ from/ [the] wickedness of"]', '["n-m"]', 'badness (as marring), physically or morally × be so bad, badness, (× be so) evil, naughtiness, sadness, sorrow, wickedness.', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4611}/H9028\/[H5953]', 'inflected', 'heb', 'מַעֲלָל', '["maʻălâl"]', '["deeds/ their"]', '["n-m"]', 'an act (good or bad) doing, endeavour, invention, work.', 'from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8649B}/[H7411]', 'lemma', 'heb', 'תׇּרְמָה', '["tormâh"]', '["[the] deceitfulness of","deceitfulness"]', '["n-f"]', 'fraud deceit(-ful), privily.', 'and תַּרְמוּת; or תַּרְמִית; from 7411;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2803J}/[H2803]', 'inflected', 'heb', 'חָשַׁב', '["châshab"]', '["who/ plan"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7911}/[H7911]', 'inflected', 'heb', 'שָׁכַח', '["shâkach"]', '["to/ make forget"]', '["v"]', 'to mislay, i.e. to be oblivious of, from want of memory or attention × at all, (cause to) forget.', 'or שָׁכֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2472}/H9028/[H2492]', 'inflected', 'heb', 'חֲלוֹם', '["chălôwm"]', '["by/ dreams/ their"]', '["n-m"]', 'a dream dream(-er).', 'or (shortened) חֲלֹם; from 2492;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1250A}/[H1305]', 'inflected', 'heb', 'בָּר', '["bâr"]', '["the/ grain"]', '["n-m"]', 'grain of any kind (even while standing in the field); by extension the open country corn, wheat.', 'or בַּר; from 1305 (in the sense of winnowing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/<H6360>', 'inflected', 'heb', 'וכפטיש', '["u./khe./fa.Tish"]', '["and/ like/ a hammer"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6327D}/[H6327]', 'lemma', 'heb', 'פּוּץ', '["pûwts"]', '["[which] it shatters"]', '["v"]', 'to dash in pieces, literally or figuratively (especially to disperse) break (dash, shake) in (to) pieces, cast (abroad), disperse (selves), drive, retire, scatter (abroad), spread abroad.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5553H>\', 'opaque', 'heb', 'סֶלַע', '["çelaʻ"]', '["rock"]', '["n-m"]', 'a craggy rock, literally or figuratively (a fortress) (ragged) rock, stone(-ny), strong hold.', 'from an unused root meaning to be lofty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3947G}/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["who/ take"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5001}/[H5001]', 'inflected', 'heb', 'נָאַם', '["nâʼam"]', '["and/ they have uttered"]', '["v"]', 'properly, to whisper, i.e. (by implication) to utter as an oracle say.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8267}/H9028/[H8266]', 'inflected', 'heb', 'שֶׁקֶר', '["sheqer"]', '["by/ falsehoods/ their"]', '["n-m"]', 'an untruth; by implication, a sham (often adverbial) without a cause, deceit(-ful), false(-hood, -ly), feignedly, liar, lie, lying, vain (thing), wrongfully.', 'from 8266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6350}/H9028/[H6348]', 'inflected', 'heb', 'פַּחֲזוּת', '["pachăzûwth"]', '["and/ by/ recklessness/ their"]', '["n-f"]', 'frivolity lightness.', 'from 6348;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3276}/[H3276]', 'inflected', 'heb', 'יָעַל', '["yâʻal"]', '["and/ certainly <to benefit>"]', '["v"]', 'properly, to ascend; figuratively, to be valuable (objectively; useful, subjectively; benefited) × at all, set forward, can do good, (be, have) profit, (able).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4853B}/[H5375]', 'inflected', 'heb', 'מַשָּׂא', '["massâʼ"]', '["and/ [the] burden of"]', '["n-m n-pr-m"]', 'a burden; specifically, tribute, or (abstractly) porterage; figuratively, an utterance, chiefly a doom, especially singing; mental, desire burden, carry away, prophecy, × they set, song, tribute.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0559}/H9046/[H559]', 'inflected', 'heb', 'אָמַר', '["ʼâmar"]', '["have spoken/ you"]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5382}/[H5382]', 'inflected', 'heb', 'נָשָׁה', '["nâshâh"]', '["and/ I will surely <forget>"]', '["v"]', 'to forget; figuratively, to neglect; causatively, to remit, remove forget, deprive, exact.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3640}/[H3639]', 'inflected', 'heb', 'כְּלִמּוּת', '["kᵉlimmûwth"]', '["and/ shame of"]', '["n-f"]', 'disgrace shame.', 'from 3639;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1731}/[H1730]', 'lemma', 'heb', 'דּוּד', '["dûwd"]', '["baskets of"]', '["n-m"]', 'a pot (for boiling); also (by resemblance of shape) a basket basket, caldron, kettle, (seething) pot.', 'from the same as 1730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4525}/[H5462]', 'inflected', 'heb', 'מַסְגֵּר', '["maçgêr"]', '["the/ smith[s]"]', '["n-m"]', 'a fastener, i.e. (of a person) a smith, (of a thing) a prison prison, smith.', 'from 5462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1731}/[H1730]', 'inflected', 'heb', 'דּוּד', '["dûwd"]', '["the/ basket"]', '["n-m"]', 'a pot (for boiling); also (by resemblance of shape) a basket basket, caldron, kettle, (seething) pot.', 'from the same as 1730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8384}/[H8384]', 'inflected', 'heb', 'תְּאֵן', '["tᵉʼên"]', '["like <the>/ figs","like the/ figs","like/ [the] figs of"]', '["n-f"]', 'the fig (tree or fruit) fig (tree).', 'or (in the singular, feminine) תְּאֵנָה; perhaps of foreign derivation');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1063}/[H1061]', 'inflected', 'heb', 'בִּכּוּרָה', '["bikkûwrâh"]', '["the/ early figs"]', '["n-f"]', 'the early fig firstripe (fruit).', 'feminine of 1061;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1731}/[H1730]', 'inflected', 'heb', 'דּוּד', '["dûwd"]', '["and/ the/ basket"]', '["n-m"]', 'a pot (for boiling); also (by resemblance of shape) a basket basket, caldron, kettle, (seething) pot.', 'from the same as 1730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7455}\/[H7489]', 'inflected', 'heb', 'רֹעַ', '["rôaʻ"]', '["from/ badness"]', '["n-m"]', 'badness (as marring), physically or morally × be so bad, badness, (× be so) evil, naughtiness, sadness, sorrow, wickedness.', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1129}/H9038/[H1129]', 'inflected', 'heb', 'בָּנָה', '["bânâh"]', '["and/ I will build up/ them","and/ I will rebuild/ them"]', '["v"]', 'to build (literally and figuratively) (begin to) build(-er), obtain children, make, repair, set (up), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3820A}/H9028\/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["heart/ their"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H8384}/[H8384]', 'inflected', 'heb', 'תְּאֵן', '["tᵉʼên"]', '["and/ like the/ figs"]', '["n-f"]', 'the fig (tree or fruit) fig (tree).', 'or (in the singular, feminine) תְּאֵנָה; perhaps of foreign derivation');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7455}/[H7489]', 'inflected', 'heb', 'רֹעַ', '["rôaʻ"]', '["from/ badness"]', '["n-m"]', 'badness (as marring), physically or morally × be so bad, badness, (× be so) evil, naughtiness, sadness, sorrow, wickedness.', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4912}/[H4910]', 'inflected', 'heb', 'מָשָׁל', '["mâshâl"]', '["and/ into/ a byword","and/ into/ bywords"]', '["n-m"]', 'properly, a pithy maxim, usually of metaphorical nature; hence, a simile (as an adage, poem, discourse) byword, like, parable, proverb.', 'apparently from 4910 in some original sense of superiority in mental action;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8148}/[H8150]', 'inflected', 'heb', 'שְׁנִינָה', '["shᵉnîynâh"]', '["into/ a taunt"]', '["n-f"]', 'something pointed, i.e. a gibe byword, taunt.', 'from 8150;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3079}/[H3068]', 'inflected', 'heb', 'יְהוֹיָקִים', '["Yᵉhôwyâqîym"]', '["of/ Jehoiakim"]', '["n-pr-m"]', 'Jehojakim, a Jewish king Jehoiakim. Compare 3113.', 'from 3068 abbreviated and 6965; Jehovah will raise;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7224}/[H7223]', 'inflected', 'heb', 'רִאשֹׁנִי', '["riʼshônîy"]', '["<the>/ first"]', '["a"]', 'first first.', 'from 7223;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5019}/[H5019]', 'inflected', 'heb', 'נְבוּכַדְנֶאצַּר', '["Nᵉbûwkadneʼtstsar"]', '["of/ Nebuchadnezzar","to/ Nebuchadnezzar"]', '["n-pr-m"]', 'Nebukadnetstsar (or -retstsar, or -retstsor), king of Babylon Nebuchadnezzar, Nebuchadrezzar.', 'or נְבֻּכַדְנֶאצַּר; (2 Kings 24:1,10), or נְבוּכַדְנֶצַּר; (Esther 2:6; Daniel 1:18), or נְבוּכַדְרֶאצַּר; or נְבוּכַדְרֶאצּוֹר; (Ezra 2:1; Jeremiah 49:28), of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2977G}/[H803]', 'inflected', 'heb', 'יֹאשִׁיָּה', '["Yôʼshîyâh"]', '["of/ Josiah"]', '["n-pr-m"]', 'Joshijah, the name of two Israelites Josiah.', 'or יֹאשִׁיָּהוּ; from the same root as 803 and 3050; founded of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2723}/[H2721]', 'inflected', 'heb', 'חׇרְבָּה', '["chorbâh"]', '["and/ into/ ruins of","and/ to the/ waste places"]', '["n-f"]', 'properly, drought, i.e. (by implication) a desolation decayed place, desolate (place, -tion), destruction, (laid) waste (place).', 'feminine of 2721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8077A}/[H8076]', 'inflected', 'heb', 'שְׁמָמָה', '["shᵉmâmâh"]', '["<into>/ a desolation","<into>/ a waste","[will become] <into>/ a desolation","into/ desolations of"]', '["n-f"]', 'devastation; figuratively, astonishment (laid, × most) desolate(-ion), waste.', 'or שִׁמָמָה; feminine of 8076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H4639G}/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["and/ according to/ [the] work of"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027G}/H9028\/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hands/ their"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2534}/[H3179]', 'inflected', 'heb', 'חֵמָה', '["chêmâh"]', '["the/ rage"]', '["n-f"]', 'heat; figuratively, anger, poison (from its fever) anger, bottles, hot displeasure, furious(-ly, -ry), heat, indignation, poison, rage, wrath(-ful). See 2529.', 'or (Daniel 11:44) חֵמָא; from 3179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0996H}/H9038/[H995]', 'inflected', 'heb', 'בֵּין', '["bêyn"]', '["between/ them"]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5414I}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["to/ make"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8322}/[H8319]', 'inflected', 'heb', 'שְׁרֵקָה', '["shᵉrêqâh"]', '["into/ a hissing","into/ hissing"]', '["n-f"]', 'a derision hissing.', 'from 8319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6547N}/[H6547]', 'lemma', 'heb', 'פַּרְעֹה', '["Parʻôh"]', '["Pharaoh"]', '["n-m"]', 'Paroh, a general title of Egyptian kings Pharaoh.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6154M}/[H6148]', 'inflected', 'heb', 'עֵרֶב', '["ʻêreb"]', '["<the>/ foreigner"]', '["n-m"]', 'the web (or transverse threads of cloth); also a mixture, (or mongrel race) Arabia, mingled people, mixed (multitude), woof.', 'or עֶרֶב; (1 Kings 10:15), (with the article prefix), from 6148;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5780J}/[H5779]', 'inflected', 'heb', 'עוּץ', '["ʻÛwts"]', '["<the>/ Uz"]', '["n-pr-m n-pr-loc"]', 'Uts, a son of Aram, also a Seirite, and the regions settled by them. Uz.', 'apparently from 5779; consultation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1719A>', 'opaque', 'heb', 'דְּדָן', '["Dᵉdân"]', '["Dedan"]', '["n-pr-m n-pr-loc"]', 'Dedan, the name of two Cushites and of their territory Dedan.', 'or (prolonged) דְּדָנֶה; (Ezekiel 25:13), of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0938I}/[H937]', 'lemma', 'heb', 'בּוּז', '["Bûwz"]', '["Buz"]', '["n-pr-m"]', 'Buz, the name of a son of Nahor, and of an Israelite Buz.', 'the same as 937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6154A}/[H6148]', 'inflected', 'heb', 'עֵרֶב', '["ʻêreb"]', '["<the>/ foreigner","the/ Arab[s]"]', '["n-m"]', 'the web (or transverse threads of cloth); also a mixture, (or mongrel race) Arabia, mingled people, mixed (multitude), woof.', 'or עֶרֶב; (1 Kings 10:15), (with the article prefix), from 6148;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2174B}/[H2167]', 'lemma', 'heb', 'זִמְרִי', '["Zimrîy"]', '["Zimri"]', '["n-pr-m"]', 'Zimri, the name of five Israelites, and of an Arabian tribe Zimri.', 'from 2167; musical;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6828G}/[H6845]', 'inflected', 'heb', 'צָפוֹן', '["tsâphôwn"]', '["the/ north"]', '["n-f"]', 'properly, hidden, i.e. dark; used only of the north as a quarter (gloomy and unknown) north(-ern, side, -ward, wind).', 'or צָפֹן; from 6845;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8347}/[H8347]', 'lemma', 'heb', 'שֵׁשַׁךְ', '["Shêshak"]', '["Sheshach"]', '["n-pr-loc"]', 'Sheshak, a symbolic name of Babylon Sheshach.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7006}/[H7006]', 'inflected', 'heb', 'קָיָה', '["qâyâh"]', '["and/ vomit"]', '["v"]', 'to vomit spue.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0996H}/H9036/[H995]', 'inflected', 'heb', 'בֵּין', '["bêyn"]', '["between/ you"]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4583}/[H5772]', 'inflected', 'heb', 'מָעוֹן', '["mâʻôwn"]', '["and/ from/ [the] dwelling of"]', '["n-m"]', 'an abode, of God (the Tabernacle or the Temple), men (their home) or animals (their lair); hence, a retreat (asylum) den, dwelling((-) place), habitation.', 'or מָעִין; (1 Chronicles 4:41), from the same as 5772;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414H}/H9038/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["he has delivered up/ them"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8600}/H9026/[H6327]', 'inflected', 'heb', 'תְּפוֹצָה', '["tᵉphôwtsâh"]', '["and/ dispersions/ your"]', '["n-f"]', 'a dispersal dispersion.', 'from 6327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0117}/[H142]', 'inflected', 'heb', 'אַדִּיר', '["ʼaddîyr"]', '["from/ [the] noble [ones] of"]', '["a"]', 'wide or (generally) large; figuratively, powerful excellent, famous, gallant, glorious, goodly, lordly, mighty(-ier one), noble, principal, worthy.', 'from 142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3215}/[H3214]', 'inflected', 'heb', 'יְלָלָה', '["yᵉlâlâh"]', '["and/ [the] wailing of","and/ wailing"]', '["n-f"]', 'a howling a howling.', 'feminine of 3214');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1826I}/[H1724]', 'inflected', 'heb', 'דָּמַם', '["dâmam"]', '["and/ they will be devastated"]', '["v"]', 'to be dumb; by implication, to be astonished, to stop; also to perish cease, be cut down (off), forbear, hold peace, quiet self, rest, be silent, keep (put to) silence, be (stand) still, tarry, wait.', 'a primitive root (compare 1724, 1820);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3238}/[H3238]', 'inflected', 'heb', 'יָנָה', '["yânâh"]', '["the/ oppressor","which/ oppresses"]', '["v"]', 'to rage or be violent; by implication, to suppress, to maltreat destroy, (thrust out by) oppress(-ing, -ion, -or), proud, vex, do violence.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7925}/[H7926]', 'inflected', 'heb', 'שָׁכַם', '["shâkam"]', '["and/ rising early"]', '["v"]', 'literally, to load up (on the back of man or beast), i.e. to start early in the morning (arise, be up, get (oneself) up, rise up) early (betimes), morning.', 'a primitive root; properly, to incline (the shoulder to a burden); but used only as denominative from 7926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7887}/[H7886]', 'inflected', 'heb', 'שִׁילֹה', '["Shîylôh"]', '["like/ Shiloh"]', '["n-pr-loc"]', 'Shiloh, a place in Palestine Shiloh.', 'or שִׁלֹה; or שִׁילוֹ; or שִׁלוֹ; from the same as 7886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7045}/[H7043]', 'inflected', 'heb', 'קְלָלָה', '["qᵉlâlâh"]', '["<into>/ a curse","into/ a curse"]', '["n-f"]', 'vilification (ac-) curse(-d, -ing).', 'from 7043;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1004P}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["from/ [the] house of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2319G}\/[H2318]', 'inflected', 'heb', 'חָדָשׁ', '["châdâsh"]', '["<the>/ new"]', '["a"]', 'new fresh, new thing.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4318K}/[H4320]', 'lemma', 'heb', 'מִיכָה', '["Mîykâh"]', '["Micah"]', '["n-pr-m"]', 'Micah, the name of seven Israelites Micah, Micaiah, Michah.', 'an abbreviated form of 4320;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4183}/[H4182]', 'inflected', 'heb', 'מוֹרַשְׁתִּי', '["Môwrashtîy"]', '["the/ Morasthite"]', '["a"]', 'a Morashtite or inhabitant of Moresheth-Gath Morashthite.', 'patrial from 4182;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5856}/[H5753]', 'lemma', 'heb', 'עִי', '["ʻîy"]', '["heaps of ruins"]', '["n-m"]', 'a ruin (as if overturned) heap.', 'from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0223B}/[H217]', 'lemma', 'heb', 'אוּרִיָּה', '["ʼÛwrîyâh"]', '["Uriah"]', '["n-pr-m"]', 'Urijah, the name of one Hittite and five Israelites Uriah, Urijah.', 'or (prolonged) אוּרִיָּהוּ ; from 217 and 3050; flame of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8098X}/[H8085]', 'lemma', 'heb', 'שְׁמַעְיָה', '["Shᵉmaʻyâh"]', '["Shemaiah"]', '["n-pr-m"]', 'Shemajah, the name of twenty-five Israelites Shemaiah.', 'or שְׁמַעְיָהוּ; from 8085 and 3050; Jah has heard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7157}/[H7151]', 'inflected', 'heb', 'קִרְיַת יְעָרִים', '["Qiryath Yᵉʻârîym"]', '["<the>/ Jearim"]', '["n-pr-loc"]', 'Kirjath-Jearim or Kirjath-Arim, a place in Palestine Kirjath, Kirjath-jearim, Kirjath-arim.', 'or (Jeremiah 26:20) with the article interposed; or (Joshua 18:28) simply the former part of the word; or קִרְיַת עָרִים; from 7151 and the plural of 3293 or 5892; city of forests, or city of towns;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1368}/H9023/[H1397]', 'inflected', 'heb', 'גִּבּוֹר', '["gibbôwr"]', '["warriors/ his"]', '["a"]', 'powerful; by implication, warrior, tyrant champion, chief, × excel, giant, man, mighty (man, one), strong (man), valiant man.', 'or גִּבֹּר; (shortened) intensive from the same as 1397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0494K}/[H410]', 'lemma', 'heb', 'אֶלְנָתָן', '["ʼElnâthân"]', '["Elnathan"]', '["n-pr-m"]', 'Elnathan, the name of four Israelites Elnathan.', 'from 410 and 5414; God (is the) giver;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4191}/H9033\/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["to/ put to death/ him"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4133}/[H4132]', 'inflected', 'heb', 'מוֹטָה', '["môwṭâh"]', '["and/ yoke-bars"]', '["n-f"]', 'a pole; by implication, an ox-bow; hence, a yoke (either literal or figurative) bands, heavy, staves, yoke.', 'feminine of 4132;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3581B>/H9020', 'inflected', 'heb', 'בכחי', '["be./kho.Ch/i"]', '["by/ power/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2220}/H9020/[H2232]', 'inflected', 'heb', 'זְרוֹעַ', '["zᵉrôwaʻ"]', '["and/ by/ arm/ my"]', '["n-f"]', 'the arm (as stretched out), or (of animals) the foreleg; figuratively, force arm, help, mighty, power, shoulder, strength.', 'or (shortened) זְרֹעַ; and (feminine) זְרוֹעָה; or זְרֹעָה; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5647G}/H9033/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["to/ serve/ him"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8552}/H9040/[H8552]', 'inflected', 'heb', 'תָּמַם', '["tâmam"]', '["have consumed/ I"]', '["v"]', 'to complete, in a good or a bad sense, literal, or figurative, transitive or intransitive accomplish, cease, be clean (pass-) ed, consume, have done, (come to an, have an, make an) end, fail, come to the full, be all gone, × be all here, be (make) perfect, be spent, sum, be (shew self) upright, be wasted, whole.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7080}/H9026/[H7080]', 'inflected', 'heb', 'קָסַם', '["qâçam"]', '["diviners/ your"]', '["v"]', 'properly, to distribute, i.e. determine by lot or magical scroll; by implication, to divine divine(-r, -ation), prudent, soothsayer, use (divination).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2472}/H9026/[H2492]', 'inflected', 'heb', 'חֲלוֹם', '["chălôwm"]', '["dreams/ your"]', '["n-m"]', 'a dream dream(-er).', 'or (shortened) חֲלֹם; from 2492;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6049B}/H9026/[H6051]', 'inflected', 'heb', 'עָנַן', '["ʻânan"]', '["soothsayers/ your"]', '["v"]', 'figuratively, to act covertly, i.e. practise magic × bring, enchanter, Meonemin, observe(-r of) times, soothsayer, sorcerer.', 'a primitive root; to cover; used only as a denominative from 6051, to cloud over;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3786}/H9026/[H3784]', 'inflected', 'heb', 'כַּשָּׁף', '["kashshâph"]', '["sorcerers/ your"]', '["n-m"]', 'a magician sorcerer.', 'from 3784;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5647I}/H9034/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["and/ it will work/ it"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6677A}/H9026/[H6696]', 'inflected', 'heb', 'צַוָּאר', '["tsavvâʼr"]', '["necks/ your"]', '["n-m"]', 'the back of the neck (as that on which burdens are bound) neck.', 'or צַוָּר; (Nehemiah 3:5), or צַוָּרֹןlemma צַוָּרן missing vowel, corrected to צַוָּרֹן; (Song of Solomon 4:9), or (feminine) צַוָּארָה; (Micah 2:3), intensively from 6696 in the sense of binding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5080}/H9040/[H5080]', 'inflected', 'heb', 'נָדַח', '["nâdach"]', '["to drive out/ I"]', '["v"]', 'to push off; used in a great variety of applications, literally and figuratively (to expel, mislead, strike, inflict, etc.) banish, bring, cast down (out), chase, compel, draw away, drive (away, out, quite), fetch a stroke, force, go away, outcast, thrust away (out), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0894}/H9011/[H1101]', 'inflected', 'heb', 'בָּבֶל', '["Bâbel"]', '["from/ Babylon/ <towards>"]', '["n-pr-loc"]', 'Babel (i.e. Babylon), including Babylonia and the Babylonian empire Babel, Babylon.', 'from 1101; confusion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1004P}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ [the] house of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0894}/H9011\/[H1101]', 'inflected', 'heb', 'בָּבֶל', '["Bâbel"]', '["Babylon/ <towards>","Babylon/ towards"]', '["n-pr-loc"]', 'Babel (i.e. Babylon), including Babylonia and the Babylonian empire Babel, Babylon.', 'from 1101; confusion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3947G}/H9038/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["he took/ them","it will take/ them"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1540K}/H9043/[H1540]', 'inflected', 'heb', 'גָּלָה', '["gâlâh"]', '["when/ took into exile/ he"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7725H}/H9038/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ I will bring back/ them"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2608A}/[H2603]', 'lemma', 'heb', 'חֲנַנְיָה', '["Chănanyâh"]', '["Hananiah","O Hananiah"]', '["n-pr-m"]', 'Chananjah, the name of thirteen Israelites Hananiah.', 'or חֲנַנְיָהוּ; from 2603 and 3050; Jah has favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5809H}/[H5826]', 'lemma', 'heb', 'עַזּוּר', '["ʻAzzûwr"]', '["Azzur"]', '["n-pr-m"]', 'Azzur, the name of three Israelites Azur, Azzur.', 'or עַזֻּר; from 5826; helpful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5869J}/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["and/ to/ [the] eyes of"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0241H}/H9021/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["in/ ears/ your"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5769J}/[H5956]', 'inflected', 'heb', 'עוֹלָם', '["ʻôwlâm"]', '["<the>/ antiquity"]', '["n-m"]', 'properly, concealed, i.e. the vanishing point; generally, time out of mind (past or future), i.e. (practically) eternity; frequentatively, adverbial (especially with prepositional prefix) always alway(-s), ancient (time), any more, continuance, eternal, (for, (n-)) ever(-lasting, -more, of old), lasting, long (time), (of) old (time), perpetual, at any time, (beginning of the) world ( without end). Compare 5331, 5703.', 'or עֹלָם; from 5956;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7451C}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["and/ of/ calamity"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1698}/[H1696]', 'inflected', 'heb', 'דֶּבֶר', '["deber"]', '["and/ of/ pestilence"]', '["n-m"]', 'a pestilence murrain, pestilence, plague.', 'from 1696 (in the sense of destroying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4133}/[H4132]', 'inflected', 'heb', 'מוֹטָה', '["môwṭâh"]', '["the/ yoke-bar"]', '["n-f"]', 'a pole; by implication, an ox-bow; hence, a yoke (either literal or figurative) bands, heavy, staves, yoke.', 'feminine of 4132;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478H}/H9039/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["in place of/ them"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7637}\/[H7657]', 'inflected', 'heb', 'שְׁבִיעִי', '["shᵉbîyʻîy"]', '["<the>/ seventh"]', '["a"]', 'seventh seventh (time).', 'or שְׁבִעִי; ordinal from 7657;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1377}/[H1376]', 'inflected', 'heb', 'גְּבִירָה', '["gᵉbîyrâh"]', '["and/ the/ queen-mother"]', '["n-f"]', 'a mistress queen.', 'feminine of 1376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H5631>', 'inflected', 'heb', 'והסריסים', '["ve./ha./sa.ri.Sim"]', '["and/ the/ court-officials"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0501J}/[H410]', 'lemma', 'heb', 'אֶלְעָשָׂה', '["ʼElʻâsâh"]', '["Eleasah"]', '["n-pr-m"]', 'Elasah, the name of four Israelites Elasah, Eleasah.', 'from 410 and 6213; God has made;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1587G}/[H1584]', 'inflected', 'heb', 'גְּמַרְיָה', '["Gᵉmaryâh"]', '["and/ Gemariah"]', '["n-pr-m"]', 'Gemarjah, the name of two Israelites Gemariah.', 'or גְּמַרְיָהוּ; from 1584 and 3050; Jah has perfected;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6529}/H9029/[H6509]', 'inflected', 'heb', 'פְּרִי', '["pᵉrîy"]', '["produce/ their"]', '["n-m"]', 'fruit (literally or figuratively) bough, (first-)fruit(-ful), reward.', 'from 6509;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7965I}/H9024/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["in/ welfare/ its"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7965I}\/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["welfare"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7080}/H9026/[H7080]', 'inflected', 'heb', 'קָסַם', '["qâçam"]', '["and/ diviners/ your"]', '["v"]', 'properly, to distribute, i.e. determine by lot or magical scroll; by implication, to divine divine(-r, -ation), prudent, soothsayer, use (divination).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697J}/H9020/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["word/ my"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4284}/[H2803]', 'inflected', 'heb', 'מַחֲשָׁבָה', '["machăshâbâh"]', '["the/ plans"]', '["n-f"]', 'a contrivance, i.e. (concretely) a texture, machine, or (abstractly) intention, plan (whether bad, a plot; or good, advice) cunning (work), curious work, device(-sed), imagination, invented, means, purpose, thought.', 'or מַחֲשֶׁבֶת; from 2803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7622}/H9026/[H7617]', 'inflected', 'heb', 'שְׁבוּת', '["shᵉbûwth"]', '["captiviti<es>/ your","captivity/ your"]', '["n-f"]', 'exile, concretely, prisoners; figuratively, a former state of prosperity captive(-ity).', 'or שְׁבִית; from 7617;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1473}/[H1540]', 'inflected', 'heb', 'גּוֹלָה', '["gôwlâh"]', '["in <the>/ exile","in the/ exile"]', '["n-f"]', 'exile; concretely and collectively exiles (carried away), captive(-ity), removing.', 'or (shortened) גֹּלָה; active participle feminine of 1540;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8182}/[H8176]', 'inflected', 'heb', 'שֹׁעָר', '["shôʻâr"]', '["<the>/ rotten"]', '["a"]', 'harsh or horrid, i.e. offensive vile.', 'from 8176;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8047H}/[H8074]', 'inflected', 'heb', 'שַׁמָּה', '["shammâh"]', '["and/ <into>/ a horror","and/ into/ a waste"]', '["n-f"]', 'ruin; by implication, consternation astonishment, desolate(-ion), waste, wonderful thing.', 'from 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2781}/[H2778]', 'inflected', 'heb', 'חֶרְפָּה', '["cherpâh"]', '["and/ <into>/ a reproach","and/ into/ a reproach"]', '["n-f"]', 'contumely, disgrace, the pudenda rebuke, reproach(-fully), shame.', 'from 2778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0256H}/[H251]', 'lemma', 'heb', 'אַחְאָב', '["ʼAchʼâb"]', '["Ahab"]', '["n-pr-m"]', 'Achab, the name of a king of Israel and of a prophet at Babylon Ahab.', 'once (by contraction) אֶחָב (Jeremiah 29:22); from 251 and 1; brother (i.e. friend) of (his) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6964H}/[H6963]', 'lemma', 'heb', 'קוֹלָיָה', '["Qôwlâyâh"]', '["Kolaiah"]', '["n-pr-m"]', 'Kolajah, the name of two Israelites Kolaiah.', 'from 6963 and 3050; voice of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6667K}/[H6664]', 'lemma', 'heb', 'צִדְקִיָּה', '["Tsidqîyâh"]', '["Zedekiah"]', '["n-pr-m"]', 'Tsidkijah, the name of six Israelites Zedekiah, Zidkijah.', 'or צִדְקִיָּהוּ; from 6664 and 3050; right of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4641Y}/[H4639]', 'lemma', 'heb', 'מַעֲשֵׂיָה', '["Maʻăsêyâh"]', '["Maaseiah"]', '["n-pr-m"]', 'Maasejah, the name of sixteen Israelites Maaseiah.', 'or מַעֲשֵׂיָהוּ; from 4639 and 3050; work of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6667K}/[H6664]', 'inflected', 'heb', 'צִדְקִיָּה', '["Tsidqîyâh"]', '["like/ Zedekiah"]', '["n-pr-m"]', 'Tsidkijah, the name of six Israelites Zedekiah, Zidkijah.', 'or צִדְקִיָּהוּ; from 6664 and 3050; right of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0256H}/[H251]', 'inflected', 'heb', 'אַחְאָב', '["ʼAchʼâb"]', '["and/ like/ Ahab"]', '["n-pr-m"]', 'Achab, the name of a king of Israel and of a prophet at Babylon Ahab.', 'once (by contraction) אֶחָב (Jeremiah 29:22); from 251 and 1; brother (i.e. friend) of (his) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7033}/H9038/[H7034]', 'inflected', 'heb', 'קָלָה', '["qâlâh"]', '["he roasted/ them"]', '["v"]', 'to toast, i.e. scorch partially or slowly dried, loathsome, parch, roast.', 'a primitive root (rather identical with 7034 through the idea of shrinkage by heat);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3045}/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["[am he] who/ knows","who/ knew"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8098Y}/[H8085]', 'lemma', 'heb', 'שְׁמַעְיָה', '["Shᵉmaʻyâh"]', '["Shemaiah"]', '["n-pr-m"]', 'Shemajah, the name of twenty-five Israelites Shemaiah.', 'or שְׁמַעְיָהוּ; from 8085 and 3050; Jah has heard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5161}/[H2492]', 'inflected', 'heb', 'נֶחֱלָמִי', '["Nechĕlâmîy"]', '["the/ Nehelamite"]', '["a"]', 'a Nechelamite, or descendant of Nechlam Nehelamite.', 'apparently a patronymic from an unused name (apparently passive participle of 2492); dreamed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3077J}/[H3068]', 'lemma', 'heb', 'יְהוֹיָדָע', '["Yᵉhôwyâdâʻ"]', '["Jehoiada"]', '["n-pr-m"]', 'Jehojada, the name of three Israelites Jehoiada. Compare 3111.', 'from 3068 and 3045; Jehovah-known;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5012}/[H5012]', 'inflected', 'heb', 'נָבָא', '["nâbâʼ"]', '["and/ [who] prophesies","and/ prophesy"]', '["v"]', 'to prophesy, i.e. speak (or sing) by inspiration (in prediction or simple discourse) prophesy(-ing), make self a prophet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H6729>', 'inflected', 'heb', 'הצינק', '["ha./tzi.Nok"]', '["the/ iron collar"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3414L}/[H7311]', 'inflected', 'heb', 'יִרְמְיָה', '["Yirmᵉyâh"]', '["<in>/ Jeremiah"]', '["n-pr-m"]', 'Jirmejah, the name of eight or nine Israelites Jeremiah.', 'or יִרְמְיָהוּ; from 7311 and 3050; Jah will rise;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5030}\/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["the/ prophet"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3423H}/H9034\/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["and/ they will take possession of/ it"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3420}/[H3418]', 'inflected', 'heb', 'יֵרָקוֹן', '["yêrâqôwn"]', '["into/ paleness"]', '["n-m"]', 'paleness, whether of persons (from fright), or of plants (from drought) greenish, yellow.', 'from 3418;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4480A}/H9034/[H4482]', 'inflected', 'heb', 'מִן', '["min"]', '["and/ from/ it"]', '["prep"]', 'properly, a part of; hence (prepositionally), from or out of in many senses above, after, among, at, because of, by (reason of), from (among), in, × neither, × nor, (out) of, over, since, × then, through, × whether, with.', 'or מִנִּי; or מִנֵּי; (constructive plural) (Isaiah 30:11); for 4482;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4147}/H9021/[H3256]', 'inflected', 'heb', 'מוֹסֵר', '["môwçêr"]', '["and/ fetters/ your"]', '["n-m"]', 'properly, chastisement, i.e. (by implication) a halter; figuratively, restraint band, bond.', 'also (in plural) feminine מוֹסֵרָה; or מֹסְרָה; from 3256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3256}/H9031/[H3256]', 'inflected', 'heb', 'יָסַר', '["yâçar"]', '["and/ I will discipline/ you"]', '["v"]', 'to chastise, literally (with blows) or figuratively (with words); hence, to instruct bind, chasten, chastise, correct, instruct, punish, reform, reprove, sore, teach.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5352}/H9031\/[H5352]', 'inflected', 'heb', 'נָקָה', '["nâqâh"]', '["I will leave unpunished/ you"]', '["v"]', 'to be (or make) clean (literally or figuratively); by implication (in an adverse sense) to be bare, i.e. extirpated acquit × at all, × altogether, be blameless, cleanse, (be) clear(-ing), cut off, be desolate, be free, be (hold) guiltless, be (hold) innocent, × by no means, be quit, be (leave) unpunished, × utterly, × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7667}/H9022/[H7665]', 'inflected', 'heb', 'שֶׁבֶר', '["sheber"]', '["<to>/ fracture/ your"]', '["n-m"]', 'a fracture, figuratively, ruin; specifically, a solution (of a dream) affliction, breach, breaking, broken(-footed, -handed), bruise, crashing, destruction, hurt, interpretation, vexation.', 'or שֵׁבֶר; from 7665;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4347}/H9022/[H5221]', 'inflected', 'heb', 'מַכָּה', '["makkâh"]', '["wound/ your"]', '["n-f"]', 'a blow (in 2 Chronicles 2:10, of the flail); by implication, a wound; figuratively, carnage, also pestilence beaten, blow, plague, slaughter, smote, × sore, stripe, stroke, wound(-ed).', 'or (masculine) מַכֶּה; (plural only) from 5221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1779}/H9022/[H1777]', 'inflected', 'heb', 'דִּין', '["dîyn"]', '["cause/ your"]', '["n-m"]', 'judgement (the suit, justice, sentence or tribunal); by implication also strife cause, judgement, plea, strife.', 'or (Job 19:29) דּוּן; from 1777;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4205}/[H2115]', 'inflected', 'heb', 'מָזוֹר', '["mâzôwr"]', '["to/ a sore"]', '["n-m"]', 'a bandage, i.e. remedy; hence, a sore (as needing a compress) bound up, wound.', 'or מָזֹר; from 2115 in the sense of binding up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7499}/[H7495]', 'lemma', 'heb', 'רְפֻאָה', '["rᵉphuʼâh"]', '["[are] medications of","healing<s>","remedies"]', '["n-f"]', 'a medicament heal(-ed), medicine.', 'feminine passive participle of 7495;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8585B}/[H5927]', 'lemma', 'heb', 'תְּעָלָה', '["tᵉʻâlâh"]', '["[is] healing","healing"]', '["n-f"]', 'a channel (into which water is raised for irrigation); also a bandage or plaster (as placed upon a wound) conduit, cured, healing, little river, trench, watercourse.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2403B}/H9022/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["sins/ your"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7667}/H9022/[H7665]', 'inflected', 'heb', 'שֶׁבֶר', '["sheber"]', '["brokenness/ your","fracture/ your"]', '["n-m"]', 'a fracture, figuratively, ruin; specifically, a solution (of a dream) affliction, breach, breaking, broken(-footed, -handed), bruise, crashing, destruction, hurt, interpretation, vexation.', 'or שֵׁבֶר; from 7665;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4341}/H9022/[H3510]', 'inflected', 'heb', 'מַכְאֹב', '["makʼôb"]', '["pain/ your"]', '["n-m"]', 'anguish or (figuratively) affliction grief, pain, sorrow.', 'sometimes מַכְאוֹב; also (feminine Isaiah 53:3) מַכְאֹבָה; from 3510;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0398}/H9032/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["[those who] devour/ you","[which] I had given to eat/ you"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6862C}/H9022/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["opponents/ your"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8155}/H9032/[H8155]', 'inflected', 'heb', 'שָׁסַס', '["shâçaç"]', '["[those who] plunder/ you"]', '["v"]', 'to plunder rifle, spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0962}/H9032/[H962]', 'inflected', 'heb', 'בָּזַז', '["bâzaz"]', '["[those who] despoil/ you"]', '["v"]', 'to plunder catch, gather, (take) for a prey, rob(-ber), spoil, take (away, spoil), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4347}/H9022/[H5221]', 'inflected', 'heb', 'מַכָּה', '["makkâh"]', '["and/ from/ wounds/ your"]', '["n-f"]', 'a blow (in 2 Chronicles 2:10, of the flail); by implication, a wound; figuratively, carnage, also pestilence beaten, blow, plague, slaughter, smote, × sore, stripe, stroke, wound(-ed).', 'or (masculine) מַכֶּה; (plural only) from 5221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7495}/H9032/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["I will heal/ you"]', '["v"]', 'properly, to mend (by stitching), i.e. (figuratively) to cure cure, (cause to) heal, physician, repair, × thoroughly, make whole. See 7503.', 'or רָפָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8510}/H9024/[H8524]', 'inflected', 'heb', 'תֵּל', '["têl"]', '["mound/ its"]', '["n-m"]', 'a mound heap, × strength.', 'by contraction from 8524;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0759G>', 'inflected', 'heb', 'וארמון', '["ve./''ar.Mon"]', '["and/ a fortress"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4941I}/H9023/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["proper place/ its"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7235A}/H9038/[H7235]', 'inflected', 'heb', 'רָבָה', '["râbâh"]', '["and/ I will multiply/ them"]', '["v"]', 'to increase (in whatever respect) (bring in) abundance (× -antly), archer (by mistake for 7232), be in authority, bring up, × continue, enlarge, excel, exceeding(-ly), be full of, (be, make) great(-er, -ly, × -ness), grow up, heap, increase, be long, (be, give, have, make, use) many (a time), (any, be, give, give the, have) more (in number), (ask, be, be so, gather, over, take, yield) much (greater, more), (make to) multiply, nourish, plenty(-eous), × process (of time), sore, store, thoroughly, very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3513G}/H9038/[H3513]', 'inflected', 'heb', 'כָּבַד', '["kâbad"]', '["and/ I will make honored/ them"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6819}/[H6819]', 'lemma', 'heb', 'צָעַר', '["tsâʻar"]', '["they will be insignificant"]', '["v"]', 'to be small, i.e. (figuratively) ignoble be brought low, little one, be small.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6924H}/[H6923]', 'inflected', 'heb', 'קֶדֶם', '["qedem"]', '["like/ ancient time","like/ long ago"]', '["n-m adv"]', 'the front, of place (absolutely, the fore part, relatively the East) or time (antiquity); often used adverbially (before, anciently, eastward) aforetime, ancient (time), before, east (end, part, side, -ward), eternal, × ever(-lasting), forward, old, past. Compare 6926.', 'or קֵדְמָה; from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5712}/H9023/[H5707]', 'inflected', 'heb', 'עֵדָה', '["ʻêdâh"]', '["and/ congregation/ its"]', '["n-f"]', 'a stated assemblage (specifically, a concourse, or generally, a family or crowd) assembly, company, congregation, multitude, people, swarm. Compare 5713.', 'feminine of 5707 in the original sense of fixture;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0117}/H9023/[H142]', 'inflected', 'heb', 'אַדִּיר', '["ʼaddîyr"]', '["noble [one]/ its"]', '["a"]', 'wide or (generally) large; figuratively, powerful excellent, famous, gallant, glorious, goodly, lordly, mighty(-ier one), noble, principal, worthy.', 'from 142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4910}/H9033/[H4910]', 'inflected', 'heb', 'מָשַׁל', '["mâshal"]', '["and/ ruler/ its"]', '["v"]', 'to rule (have, make to have) dominion, governor, × indeed, reign, (bear, cause to, have) rule(-ing, -r), have power.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7126G}/H9033/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["and/ I will bring near/ him"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5591A}/[H5590]', 'lemma', 'heb', 'סַעַר', '["çaʻar"]', '["a storm"]', '["n-m"]', 'a hurricane storm(-y), tempest, whirlwind.', 'or (feminine) סְעָרָה; from 5590;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5971A}\/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["<into>/ a people"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7280B}/H9033/[H7280]', 'inflected', 'heb', 'רָגַע', '["râgaʻ"]', '["to/ give rest/ it"]', '["v"]', 'properly, to toss violently and suddenly (the sea with waves, the skin with boils); figuratively (in a favorable manner) to settle, i.e. quiet; specifically, to wink (from the motion of the eye-lids) break, divide, find ease, be a moment, (cause, give, make to) rest, make suddenly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4900}/H9032/[H4900]', 'inflected', 'heb', 'מָשַׁךְ', '["mâshak"]', '["I have prolonged to/ you"]', '["v"]', 'to draw, used in a great variety of applications (including to sow, to sound, to prolong, to develop, to march, to remove, to delay, to be tall, etc.) draw (along, out), continue, defer, extend, forbear, × give, handle, make (pro-, sound) long, × sow, scatter, stretch out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1129}/H9032/[H1129]', 'inflected', 'heb', 'בָּנָה', '["bânâh"]', '["I will build/ you","builders/ your"]', '["v"]', 'to build (literally and figuratively) (begin to) build(-er), obtain children, make, repair, set (up), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8596}/H9022/[H8608]', 'inflected', 'heb', 'תֹּף', '["tôph"]', '["tambourines/ your"]', '["n-m"]', 'a tambourine tabret, timbrel.', 'from 8608 contracted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2490I}/[H2470]', 'inflected', 'heb', 'חָלַל', '["châlal"]', '["and/ they will put [them] to use"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8469}/[H2603]', 'inflected', 'heb', 'תַּחֲנוּן', '["tachănûwn"]', '["and/ with/ supplications"]', '["n-m"]', 'earnest prayer intreaty, supplication.', 'or (feminine) תַּחֲנוּנָה; from 2603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2986}/H9038/[H2986]', 'inflected', 'heb', 'יָבַל', '["yâbal"]', '["I will bring/ them"]', '["v"]', 'properly, to flow; causatively, to bring (especially with pomp) bring (forth), carry, lead (forth).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980I}/H9038/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["I will lead/ them"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8104H}/H9033/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["and/ he will keep/ it"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1350A}/H9033/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["and/ he has redeemed/ it"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1669}/[H1669]', 'inflected', 'heb', 'דָּאַב', '["dâʼab"]', '["to/ languish"]', '["v"]', 'to pine mourn, sorrow(-ful).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0060}/H9028/[H56]', 'inflected', 'heb', 'אֵבֶל', '["ʼêbel"]', '["mourning/ their"]', '["n-m"]', 'lamentation mourning.', 'from 56;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5162G}/H9038/[H5162]', 'inflected', 'heb', 'נָחַם', '["nâcham"]', '["and/ I will comfort/ them"]', '["v"]', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3015}/H9028/[H3013]', 'inflected', 'heb', 'יָגוֹן', '["yâgôwn"]', '["from/ sorrow/ their"]', '["n-m"]', 'affliction grief, sorrow.', 'from 3013;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5869A}/H9022/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["and/ eyes/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1832}/[H1831]', 'inflected', 'heb', 'דִּמְעָה', '["dimʻâh"]', '["from/ tear[s]"]', '["n-f"]', 'weeping tears.', 'feminine of 1831;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6468}/H9022/[H6466]', 'inflected', 'heb', 'פְּעֻלָּה', '["pᵉʻullâh"]', '["for/ work/ your"]', '["n-f"]', '(abstractly) work labour, reward, wages, work.', 'feminine passive participle of 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0319}/H9022/[H310]', 'inflected', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["for/ future/ your"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1366H}/H9028\/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["to/ own territory/ their"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5695}/[H5696]', 'inflected', 'heb', 'עֵגֶל', '["ʻêgel"]', '["[are] like/ calves of","like/ a calf","like/ calves of"]', '["n-m"]', 'a (male) calf (as frisking round), especially one nearly grown (i.e. a steer) bullock, calf.', 'from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725O}/H9040/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["turned away/ I"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H1121A}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["¿/ [do] children","¿/ a son"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3357}/[H3365]', 'lemma', 'heb', 'יַקִּיר', '["yaqqîyr"]', '["dear"]', '["a"]', 'precious dear.', 'from 3365;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6725}/[H6723]', 'lemma', 'heb', 'צִיּוּן', '["tsîyûwn"]', '["a marker","signposts"]', '["n-m"]', 'a monumental or guiding pillar sign, title, waymark.', 'from the same as 6723 in the sense of conspicuousness (compare 5329);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8564}/[H8558]', 'lemma', 'heb', 'תַּמְרוּר', '["tamrûwr"]', '["guideposts"]', '["n-m"]', 'an erection, i.e. pillar (probably for a guide-board) high heap.', 'from the same root as 8558;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2559}/H9013/[H2559]', 'inflected', 'heb', 'חָמַק', '["châmaq"]', '["will you vacillate/ !"]', '["v"]', 'properly, to wrap; hence, to depart (i.e. turn about) go about, withdraw self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7728}/[H7725]', 'inflected', 'heb', 'שׁוֹבֵב', '["shôwbêb"]', '["<the>/ apostate"]', '["a"]', 'apostate, i.e. heathenish or (actually) heathen backsliding.', 'from 7725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1397}\/[H1396]', 'inflected', 'heb', 'גֶּבֶר', '["geber"]', '["a man"]', '["n-m"]', 'properly, a valiant man or warrior; generally, a person simply every one, man, × mighty.', 'from 1396;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7725H}/H9040/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["when/ turn back/ I"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7622}/H9028/[H7617]', 'inflected', 'heb', 'שְׁבוּת', '["shᵉbûwth"]', '["captivity/ their"]', '["n-f"]', 'exile, concretely, prisoners; figuratively, a former state of prosperity captive(-ity).', 'or שְׁבִית; from 7617;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5739}/[H5737]', 'inflected', 'heb', 'עֵדֶר', '["ʻêder"]', '["among/ flocks of","with <the>/ flock"]', '["n-m"]', 'an arrangement, i.e. muster (of animals) drove, flock, herd.', 'from 5737;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8142}/H9020/[H3462]', 'inflected', 'heb', 'שֵׁנָה', '["shênâh"]', '["and/ sleep/ my"]', '["n-f"]', 'sleep sleep.', 'or שֵׁנָא; (Psalm 127:2), from 3462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7489A}/[H7489]', 'inflected', 'heb', 'רָעַע', '["râʻaʻ"]', '["and/ to/ do harm"]', '["v"]', 'properly, to spoil (literally, by breaking to pieces); figuratively, to make (or be) good for nothing, i.e. bad (physically, socially or morally) afflict, associate selves (by mistake for 7462), break (down, in pieces), displease, (be, bring, do) evil (doer, entreat, man), show self friendly (by mistake for 7462), do harm, (do) hurt, (behave self, deal) ill, × indeed, do mischief, punish, still, vex, (do) wicked (doer, -ly), be (deal, do) worse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1155}/[H1154]', 'lemma', 'heb', 'בֹּסֶר', '["bôçer"]', '["sour grape[s]"]', '["n-m"]', 'sour grape.', 'from the same as 1154');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5771G}/H9023/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["for/ iniquity/ his","for/ own iniquity/ his","in/ iniquity/ his"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1155}/[H1154]', 'inflected', 'heb', 'בֹּסֶר', '["bôçer"]', '["the/ sour grape[s]"]', '["n-m"]', 'sour grape.', 'from the same as 1154');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2388H}/H9040/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["took hold/ I"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/H9006/{H6996A}/H9028/[H6962]', 'inflected', 'heb', 'קָטָן', '["qâṭân"]', '["<to>/ from/ little/ their"]', '["a"]', 'abbreviated, i.e. diminutive, literally (in quantity, size or number) or figuratively (in age or importance) least, less(-er), little (one), small(-est, one, quantity, thing), young(-er, -est).', 'or קָטֹן; from 6962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5771G}/H9028/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["<to>/ iniquity/ their"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2403B}/H9028/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["and/ <to>/ sin/ their"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2713}/[H2713]', 'inflected', 'heb', 'חָקַר', '["châqar"]', '["and/ let us examine","so/ they may be explored"]', '["v"]', 'properly, to penetrate; hence, to examine intimately find out, (make) search (out), seek (out), sound, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117G>/ /{H0935G}', 'opaque', 'heb', 'בּוֹא', '["bôwʼ"]', '["days/ /[are] coming"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4026G}/[H1431]', 'inflected', 'heb', 'מִגְדָּל', '["migdâl"]', '["from/ [the] tower of"]', '["n-m"]', 'a tower (from its size or height); by analogy, a rostrum; figuratively, a (pyramidal) bed of flowers castle, flower, tower. Compare the names following.', 'also (in plural) feminine מִגְדָּלָה; from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4060A}/[H4055]', 'inflected', 'heb', 'מִדָּה', '["middâh"]', '["<the>/ measurement","the/ measured area","the/ measurement"]', '["n-f"]', 'properly, extension, i.e. height or breadth; also a measure (including its standard); hence a portion (as measured) or a vestment; specifically, tribute (as measured) garment, measure(-ing, meteyard, piece, size, (great) stature, tribute, wide.', 'feminine of 4055;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1619H}/[H1618]', 'lemma', 'heb', 'גָּרֵב', '["Gârêb"]', '["Gareb"]', '["n-pr-m n-pr-loc"]', 'Gareb, the name of an Israelite, also of a hill near Jerusalem Gareb.', 'from the same as 1618; scabby;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1601}/H9011/[H1600]', 'inflected', 'heb', 'גֹּעָה', '["Gôʻâh"]', '["Goah/ towards"]', '["n-pr-loc"]', 'Goah, a place near Jerusalem Goath.', 'feminine active participle of 1600; lowing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1880}/[H1878]', 'inflected', 'heb', 'דֶּשֶׁן', '["deshen"]', '["and/ the/ fatty ash"]', '["n-m"]', 'the fat; abstractly fatness, i.e. (figuratively) abundance; specifically the (fatty) ashes of sacrifices ashes, fatness.', 'from 1878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7709}/[H7704]', 'inflected', 'heb', 'שְׁדֵמָה', '["shᵉdêmâh"]', '["the/ terraced fields"]', '["n-f"]', 'a cultivated field blasted, field.', 'apparently from 7704;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3414L}/[H7311]', 'inflected', 'heb', 'יִרְמְיָה', '["Yirmᵉyâh"]', '["and/ Jeremiah"]', '["n-pr-m"]', 'Jirmejah, the name of eight or nine Israelites Jeremiah.', 'or יִרְמְיָהוּ; from 7311 and 3050; Jah will rise;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3607}/H9033/[H3607]', 'inflected', 'heb', 'כָּלָא', '["kâlâʼ"]', '["he had shut up/ him"]', '["v"]', 'to restrict, by act (hold back or in) or word (prohibit) finish, forbid, keep (back), refrain, restrain, retain, shut up, be stayed, withhold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6667H}/[H6664]', 'inflected', 'heb', 'צִדְקִיָּה', '["Tsidqîyâh"]', '["and/ Zedekiah"]', '["n-pr-m"]', 'Tsidkijah, the name of six Israelites Zedekiah, Zidkijah.', 'or צִדְקִיָּהוּ; from 6664 and 3050; right of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2601}/[H2606]', 'lemma', 'heb', 'חֲנַמְאֵל', '["Chănamʼêl"]', '["Hanamel"]', '["n-pr-m"]', 'Chanamel, an Israelite Hanameel.', 'probably by orthographical variation for 2606;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7967R}/[H7966]', 'lemma', 'heb', 'שַׁלּוּם', '["Shallûwm"]', '["Shallum"]', '["n-pr-m"]', 'Shallum, the name of fourteen Israelites Shallum.', 'or (shorter) שַׁלֻּם; the same as 7966;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1730I>/H9021', 'opaque', 'heb', 'דּוֹד', '["dôwd"]', '["uncle/ your"]', '["n-m"]', '(figuratively) to love; by implication, a love-token, lover, friend; specifically an uncle (well-) beloved, father''s brother, love, uncle.', 'or (shortened) דֹּד; from an unused root meaning properly, to boil, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7704G>/H9020', 'opaque', 'heb', 'שָׂדֶה', '["sâdeh"]', '["field/ my"]', '["n-m"]', 'a field (as flat) country, field, ground, land, soil, × wild.', 'or שָׂדַי; from an unused root meaning to spread out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1730I>/H9020', 'opaque', 'heb', 'דּוֹד', '["dôwd"]', '["uncle/ my"]', '["n-m"]', '(figuratively) to love; by implication, a love-token, lover, friend; specifically an uncle (well-) beloved, father''s brother, love, uncle.', 'or (shortened) דֹּד; from an unused root meaning properly, to boil, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3425}/[H3423]', 'inflected', 'heb', 'יְרֻשָּׁה', '["yᵉrushshâh"]', '["<the>/ possession"]', '["n-f"]', 'something occupied; a conquest; also a patrimony heritage, inheritance, possession.', 'from 3423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4736}/[H4735]', 'inflected', 'heb', 'מִקְנָה', '["miqnâh"]', '["the/ purchase"]', '["n-f"]', 'properly, a buying, i.e. acquisition; concretely, a piece of property (land or living); also the sum paid (he that is) bought, possession, piece, purchase.', 'feminine of 4735;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1540I}/[H1540]', 'inflected', 'heb', 'גָּלָה', '["gâlâh"]', '["<the>/ uncovered","the/ uncovered [one]"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1263J}/[H1288]', 'lemma', 'heb', 'בָּרוּךְ', '["Bârûwk"]', '["Baruch","O Baruch"]', '["n-pr-m"]', 'Baruk, the name of three Israelites Baruch.', 'passive participle from 1288; blessed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5374}/[H5216]', 'lemma', 'heb', 'נֵרִיָּה', '["Nêrîyâh"]', '["Neriah"]', '["n-pr-m"]', 'Nerijah, an Israelite Neriah.', 'or נֵרִיָּהוּ; from 5216 and 3050; light of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4271}/[H4268]', 'lemma', 'heb', 'מַחְסֵיָה', '["Machçêyâh"]', '["Mahseiah"]', '["n-pr-m"]', 'Machsejah, an Israelite Maaseiah.', 'from 4268 and 3050; refuge of (i.e. in) Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5950}/[H5949]', 'inflected', 'heb', 'עֲלִילִיָּה', '["ʻălîylîyâh"]', '["<the>/ deed[s]"]', '["n-f"]', '(miraculous) execution work.', 'for 5949;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H6529}/[H6509]', 'inflected', 'heb', 'פְּרִי', '["pᵉrîy"]', '["and/ according to/ [the] fruit of"]', '["n-m"]', 'fruit (literally or figuratively) bough, (first-)fruit(-ful), reward.', 'from 6509;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4611}/H9023/[H5953]', 'inflected', 'heb', 'מַעֲלָל', '["maʻălâl"]', '["deeds/ his"]', '["n-m"]', 'an act (good or bad) doing, endeavour, invention, work.', 'from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0248}/[H2220]', 'inflected', 'heb', 'אֶזְרוֹעַ', '["ʼezrôwaʻ"]', '["and/ by/ an arm"]', '["n-f"]', 'the arm arm.', 'a variation for 2220;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6963A>/H9021', 'inflected', 'heb', 'בקולך', '["be./ko.Le./cha","ve./ko.Le./cha"]', '["to/ voice/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8451}/H9021/[H3384]', 'inflected', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["and/ in/ law/ your"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5550}/[H5549]', 'inflected', 'heb', 'סֹלְלָה', '["çôlᵉlâh"]', '["the/ mounds"]', '["n-f"]', 'a military mound, i.e. rampart of besiegers bank, mount.', 'or סוֹלְלָה; active participle feminine of 5549, but used passively;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3920}/H9034/[H3920]', 'inflected', 'heb', 'לָכַד', '["lâkad"]', '["to/ capture/ it"]', '["v"]', 'to catch (in a net, trap or pit); generally, to capture or occupy; also to choose (by lot); figuratively, to cohere × at all, catch (self), be frozen, be holden, stick together, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1698}/[H1696]', 'inflected', 'heb', 'דֶּבֶר', '["deber"]', '["and/ <the>/ pestilence","and/ the/ pestilence"]', '["n-m"]', 'a pestilence murrain, pestilence, plague.', 'from 1696 (in the sense of destroying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H4480A}/H9030/[H4482]', 'inflected', 'heb', 'מִן', '["min"]', '["¿/ for/ me"]', '["prep"]', 'properly, a part of; hence (prepositionally), from or out of in many senses above, after, among, at, because of, by (reason of), from (among), in, × neither, × nor, (out) of, over, since, × then, through, × whether, with.', 'or מִנִּי; or מִנֵּי; (constructive plural) (Isaiah 30:11); for 4482;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5271B}/H9028/[H5288]', 'inflected', 'heb', 'נָעוּר', '["nâʻûwr"]', '["since/ youth<s>/ their"]', '["n-m n-f"]', '(only in plural collective or emphatic form) youth, the state (juvenility) or the persons (young people) childhood, youth.', 'or נָעֻר; and (feminine) נְעֻרָה; properly, passive participle from 5288 as denominative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5493G}/H9034/[H5493]', 'inflected', 'heb', 'סוּר', '["çûwr"]', '["to/ remove/ it"]', '["v"]', 'to turn off (literally or figuratively) be(-head), bring, call back, decline, depart, eschew, get (you), go (aside), × grievous, lay away (by), leave undone, be past, pluck away, put (away, down), rebel, remove (to and fro), revolt, × be sour, take (away, off), turn (aside, away, in), withdraw, be without.', 'or שׂוּר; (Hosea 9:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3548}/H9028/[H3547]', 'inflected', 'heb', 'כֹּהֵן', '["kôhên"]', '["priests/ their"]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2534}/H9020/[H3179]', 'inflected', 'heb', 'חֵמָה', '["chêmâh"]', '["and/ in/ rage/ my"]', '["n-f"]', 'heat; figuratively, anger, poison (from its fever) anger, bottles, hot displeasure, furious(-ly, -ry), heat, indignation, poison, rage, wrath(-ful). See 2529.', 'or (Daniel 11:44) חֵמָא; from 3179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3190}/H9030/[H3190]', 'inflected', 'heb', 'יָטַב', '["yâṭab"]', '["to/ do good to/ I"]', '["v"]', 'to be (causative) make well, literally (sound, beautiful) or figuratively (happy, successful, right) be accepted, amend, use aright, benefit, be (make) better, seem best, make cheerful, be comely, be content, diligent(-ly), dress, earnestly, find favour, give, be glad, do (be, make) good(-ness), be (make) merry, please ( well), shew more (kindness), skilfully, × very small, surely, make sweet, thoroughly, tire, trim, very, be (can, deal, entreat, go, have) well (said, seen).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3374}/H9020/[H3373]', 'inflected', 'heb', 'יִרְאָה', '["yirʼâh"]', '["fear/ my"]', '["n-f"]', 'fear (also used as infinitive); morally, reverence × dreadful, × exceedingly, fear(-fulness).', 'feminine of 3373;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315G}/H9020\/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["being/ my"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5439G}/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["and/ in/ [the] surroundings of"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3559H}/H9034/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["to/ establish/ it"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6030B}/H9031/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["and/ I will answer/ you"]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3045}/H9038\/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["you know/ them"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5422}/[H5422]', 'inflected', 'heb', 'נָתַץ', '["nâthats"]', '["which/ have been pulled down"]', '["v"]', 'to tear down beat down, break down (out), cast down, destroy, overthrow, pull down, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4390}/H9038/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["and/ to/ fill/ them"]', '["v"]', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly.', 'or מָלָא; (Esther 7:5), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6283}/[H6280]', 'lemma', 'heb', 'עֲתֶרֶת', '["ʻăthereth"]', '["an abundance of"]', '["n-f"]', 'copiousness abundance. p', 'from 6280;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7965I}/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["the/ well-being"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0369}/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["and/ from/ not"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8074G}/[H8074]', 'inflected', 'heb', 'שָׁמֵם', '["shâmêm"]', '["<the>/ desolated","the/ desolated [places]","which/ are made desolate"]', '["v"]', 'to stun (or intransitively, grow numb), i.e. devastate or (figuratively) stupefy (both usually in a passive sense) make amazed, be astonied, (be an) astonish(-ment), (be, bring into, unto, lay, lie, make) desolate(-ion, places), be destitute, destroy (self), (lay, lie, make) waste, wonder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2720B}/[H2717]', 'inflected', 'heb', 'חָרֵב', '["chârêb"]', '["<the>/ desolate","<the>/ wasted"]', '["a"]', 'parched or ruined desolate, dry, waste.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6999A}/[H6999]', 'inflected', 'heb', 'קָטַר', '["qâṭar"]', '["and/ [who] makes smoke"]', '["v n-m n-f"]', 'to smoke, i.e. turn into fragrance by fire (especially as an act of worship) burn (incense, sacrifice) (upon), (altar for) incense, kindle, offer (incense, a sacrifice).', 'a primitive root (identical with through the idea of fumigation in a close place and perhaps thus driving out the occupants);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0853}/H9030\/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["<obj.>/ me"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3988A}/H9038/[H3988]', 'inflected', 'heb', 'מָאַס', '["mâʼaç"]', '["and/ he has rejected/ them"]', '["v"]', 'to spurn; also (intransitively) to disappear abhor, cast away (off), contemn, despise, disdain, (become) loathe(some), melt away, refuse, reject, reprobate, × utterly, vile person.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5006}/H9013/[H5006]', 'inflected', 'heb', 'נָאַץ', '["nâʼats"]', '["they spurn/ !"]', '["v"]', 'to scorn; or (in Ecclesiastes 12:5), by interchange for 5132, to bloom abhor, (give occasion to) blaspheme, contemn, despise, flourish, × great, provoke.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3446}/[H7831]', 'lemma', 'heb', 'יִשְׂחָק', '["Yischâq"]', '["Isaac"]', '["n-pr-m"]', 'Jischak, the heir of Abraham Isaac. Compare 3327.', 'from 7831; he will laugh;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7355}/H9038\/[H7355]', 'inflected', 'heb', 'רָחַם', '["râcham"]', '["and/ I will have compassion on/ them"]', '["v"]', 'to fondle; by implication, to love, especially to compassionate have compassion (on, upon), love, (find, have, obtain, shew) mercy(-iful, on, upon), (have) pity, Ruhamah, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5019}/[H5019]', 'inflected', 'heb', 'נְבוּכַדְנֶאצַּר', '["Nᵉbûwkadneʼtstsar"]', '["and/ Nebuchadnezzar"]', '["n-pr-m"]', 'Nebukadnetstsar (or -retstsar, or -retstsor), king of Babylon Nebuchadnezzar, Nebuchadrezzar.', 'or נְבֻּכַדְנֶאצַּר; (2 Kings 24:1,10), or נְבוּכַדְנֶצַּר; (Esther 2:6; Daniel 1:18), or נְבוּכַדְרֶאצַּר; or נְבוּכַדְרֶאצּוֹר; (Ezra 2:1; Jeremiah 49:28), of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4475}/[H4474]', 'lemma', 'heb', 'מֶמְשָׁלָה', '["memshâlâh"]', '["[the] rule of"]', '["n-f"]', 'rule; also (concretely in plural) a realm or a ruler dominion, government, power, to rule.', 'feminine of 4474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H4955}/[H8313]', 'inflected', 'heb', 'מִשְׂרָפָה', '["misrâphâh"]', '["and/ like/ [the] burnings of"]', '["n-f"]', 'combustion, i.e. cremation (of a corpse), or calcination (of lime) burning.', 'from 8313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3533}/H9038/[H3533]', 'inflected', 'heb', 'כָּבַשׁ', '["kâbash"]', '["and/ they subjugated/ them"]', '["v"]', 'to tread down; hence, negatively, to disregard; positively, to conquer, subjugate, violate bring into bondage, force, keep under, subdue, bring into subjection.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H8198>\', 'inflected', 'heb', 'ולשפחות ס', '["ve./li/sh.fa.Chot"]', '["and/ <into>/ female slaves","and/ for/ female slaves"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5674D}/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["who/ have transgressed"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1335}/[H1334]', 'lemma', 'heb', 'בֶּתֶר', '["bether"]', '["[the] pieces of"]', '["n-m"]', 'a section part, piece.', 'from 1334;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7397A}/[H7401]', 'inflected', 'heb', 'רֵכָה', '["Rêkâh"]', '["the/ Rechabites"]', '["n-pr-loc"]', 'Rekah, a place in Palestine Rechah.', 'probably feminine from 7401; softness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2970G}/[H238]', 'lemma', 'heb', 'יַאֲזַנְיָה', '["Yaʼăzanyâh"]', '["Jaazaniah"]', '["n-pr-m"]', 'Jaazanjah, the name of four Israelites Jaazaniah. Compare 3153.', 'or יַאֲזַנְיָהוּ; from 238 and 3050; heard of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3414N}/[H7311]', 'lemma', 'heb', 'יִרְמְיָה', '["Yirmᵉyâh"]', '["Jeremiah"]', '["n-pr-m"]', 'Jirmejah, the name of eight or nine Israelites Jeremiah.', 'or יִרְמְיָהוּ; from 7311 and 3050; Jah will rise;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2262>', 'opaque', 'heb', 'חֲבַצַּנְיָה', '["Chăbatstsanyâh"]', '["Habazziniah"]', '["n-pr-m"]', 'Chabatstsanjah, a Rechabite Habazaniah.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2605O}/[H2603]', 'lemma', 'heb', 'חָנָן', '["Chânân"]', '["Hanan"]', '["n-pr-m"]', 'Chanan, the name of seven Israelites Canan.', 'from 2603; favor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3012}/[H1431]', 'lemma', 'heb', 'יִגְדַּלְיָהוּ', '["Yigdalyâhûw"]', '["Igdaliah"]', '["n-pr-m"]', 'Jigdaljah, an Israelite Igdaliah.', 'from 1431 and 3050; magnified of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3957>', 'inflected', 'heb', 'ללשכת', '["le./lish.Kat"]', '["<to>/ [the] room of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4641Z}/[H4639]', 'lemma', 'heb', 'מַעֲשֵׂיָה', '["Maʻăsêyâh"]', '["Maaseiah"]', '["n-pr-m"]', 'Maasejah, the name of sixteen Israelites Maaseiah.', 'or מַעֲשֵׂיָהוּ; from 4639 and 3050; work of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7967S}/[H7966]', 'lemma', 'heb', 'שַׁלּוּם', '["Shallûwm"]', '["Shallum"]', '["n-pr-m"]', 'Shallum, the name of fourteen Israelites Shallum.', 'or (shorter) שַׁלֻּם; the same as 7966;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3122H}/[H3082]', 'lemma', 'heb', 'יוֹנָדָב', '["Yôwnâdâb"]', '["Jonadab"]', '["n-pr-m"]', 'Jonadab, the name of an Israelite and of a Rechabite Jonadab.', 'a form of 3082;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3427}/H9035/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["to/ dwell in/ we"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3427}/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["and/ for/ [the] inhabitants of","and/ to/ [the] inhabitants of"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3122H}/[H3082]', 'inflected', 'heb', 'יוֹנָדָב', '["Yôwnâdâb"]', '["to/ Jonadab"]', '["n-pr-m"]', 'Jonadab, the name of an Israelite and of a Rechabite Jonadab.', 'a form of 3082;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4039}/[H1556]', 'lemma', 'heb', 'מְגִלָּה', '["mᵉgillâh"]', '["a scroll","a scroll of"]', '["n-f"]', 'a roll roll, volume.', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2403B}/H9028\/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["and/ <to>/ sin/ their"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6310I}/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["from/ [the] mouth of"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6310I}/H9020/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["from/ mouth/ my"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
