INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2608N}/[H2603]', 'lemma', 'heb', 'חֲנַנְיָה', '["Chănanyâh"]', '["Hananiah"]', '["n-pr-m"]', 'Chananjah, the name of thirteen Israelites Hananiah.', 'or חֲנַנְיָהוּ; from 2603 and 3050; Jah has favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0612}/[H631]', 'inflected', 'heb', 'אֵסוּר', '["ʼêçûwr"]', '["<the>/ fetter[s]"]', '["n-m"]', 'a bond (especially manacles of a prisoner) band, prison.', 'from 631;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3083N}/[H3068]', 'lemma', 'heb', 'יְהוֹנָתָן', '["Yᵉhôwnâthân"]', '["Jonathan"]', '["n-pr-m"]', 'Jehonathan, the name of four Israelites Jonathan. Compare 3129.', 'from 3068 and 5414; Jehovah-given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2588}/[H2583]', 'inflected', 'heb', 'חָנוּת', '["chânûwth"]', '["the/ cell"]', '["n-f"]', 'properly, a vault or cell (with an arch); by implication, a prison cabin.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8203O}/[H8199]', 'lemma', 'heb', 'שְׁפַטְיָה', '["Shᵉphaṭyâh"]', '["Shephatiah"]', '["n-pr-m"]', 'Shephatjah, the name of ten Israelites Shephatiah.', 'or שְׁפַטְיָהוּ; from 8199 and 3050; Jah has judged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4977H}/[H4976]', 'lemma', 'heb', 'מַתָּן', '["Mattân"]', '["Mattan"]', '["n-pr-m"]', 'Mattan, the name of a priest of Baal, and of an Israelite Mattan.', 'the same as 4976;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1436J}/[H1431]', 'inflected', 'heb', 'גְּדַּלְיָה', '["Gᵉdalyâh"]', '["and/ Gedaliah"]', '["n-pr-m"]', 'Gedaljah, the name of five Israelites Gedaliah.', 'or (prolonged) גְּדַלְיָהוּ; from 1431 and 3050; Jah has become great;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6583K}/[H6582]', 'lemma', 'heb', 'פַּשְׁחוּר', '["Pashchûwr"]', '["Pashhur"]', '["n-pr-m"]', 'Pashchur, the name of four Israelites Pashur.', 'probably from 6582; liberation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3116}/[H3081]', 'inflected', 'heb', 'יוּכַל', '["Yûwkal"]', '["and/ Jucal"]', '["n-pr-m"]', 'Jukal, an Israelite Jucal.', 'a form of 3081;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6583J}/[H6582]', 'inflected', 'heb', 'פַּשְׁחוּר', '["Pashchûwr"]', '["and/ Pashhur"]', '["n-pr-m"]', 'Pashchur, the name of four Israelites Pashur.', 'probably from 6582; liberation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2421}\/[H2331]', 'inflected', 'heb', 'חָיָה', '["châyâh"]', '["and/ he will live"]', '["v"]', 'to live, whether literally or figuratively; causatively, to revive keep (leave, make) alive, × certainly, give (promise) life, (let, suffer to) live, nourish up, preserve (alive), quicken, recover, repair, restore (to life), revive, (× God) save (alive, life, lives), × surely, be whole.', 'a primitive root (compare 2331, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2916>\', 'inflected', 'heb', 'בטיט ס', '["ba./Tit"]', '["in the/ mud"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5663}/[H5650]', 'lemma', 'heb', 'עֶבֶד מֶלֶךְ', '["ʻEbed Melek"]', '["Ebed","Melech"]', '["n-pr-m"]', 'Ebed-Melek, a eunuch of Zedekeah Ebed-melech.', 'from 5650 and 4428; servant of a king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3414L}/[H7311]', 'inflected', 'heb', 'יִרְמְיָה', '["Yirmᵉyâh"]', '["<to>/ Jeremiah","to/ Jeremiah"]', '["n-pr-m"]', 'Jirmejah, the name of eight or nine Israelites Jeremiah.', 'or יִרְמְיָהוּ; from 7311 and 3050; Jah will rise;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1094}/[H1086]', 'lemma', 'heb', 'בְּלוֹא', '["bᵉlôwʼ"]', '["[the] worn out things of","worn out things of"]', '["n-m"]', '(only in plural construction) rags old.', 'or (fully) בְּלוֹי; from 1086;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5499}/[H5498]', 'lemma', 'heb', 'סְחָבָה', '["çᵉchâbâh"]', '["clothes"]', '["n-f"]', 'a rag cast clout.', 'from 5498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1094}/[H1086]', 'inflected', 'heb', 'בְּלוֹא', '["bᵉlôwʼ"]', '["and/ worn out things of"]', '["n-m"]', '(only in plural construction) rags old.', 'or (fully) בְּלוֹי; from 1086;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4418}/[H4414]', 'lemma', 'heb', 'מָלָח', '["mâlâch"]', '["rags"]', '["n-m"]', 'a rag or old garment rotten rag.', 'from 4414 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5499}/[H5498]', 'inflected', 'heb', 'סְחָבָה', '["çᵉchâbâh"]', '["the/ clothes"]', '["n-f"]', 'a rag cast clout.', 'from 5498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4418}/[H4414]', 'inflected', 'heb', 'מָלָח', '["mâlâch"]', '["and/ the/ rags"]', '["n-m"]', 'a rag or old garment rotten rag.', 'from 4414 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0679}/[H680]', 'lemma', 'heb', 'אַצִּיל', '["ʼatstsîyl"]', '["[the] joints of","a joint"]', '["n-f"]', 'a joint of the hand (i.e. knuckle); also (according to some) a party-wall (Ezekiel 41:8) (arm) hole, great.', 'from 680 (in its primary sense of uniting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2256M}/[H2254]', 'inflected', 'heb', 'חֶבֶל', '["chebel"]', '["to/ [the] ropes"]', '["n-m"]', 'a rope (as twisted), especially a measuring line; by implication, a district or inheritance (as measured); or a noose (as of cords); figuratively, a company (as if tied together); a throe (especially of parturition); also ruin band, coast, company, cord, country, destruction, line, lot, pain, pang, portion, region, rope, snare, sorrow, tackling.', 'or חֵבֶל; from 2254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4307H}\/[H5201]', 'inflected', 'heb', 'מַטָּרָא', '["maṭṭârâʼ"]', '["the/ guard"]', '["n-f"]', 'a jail (as a guard-house); also an aim (as being closely watched) mark, prison.', 'or מַטָּרָה; from 5201;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315H}/H9021\/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["life/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3027H}/H9028\/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["from/ hand/ their"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H9030}\', 'inflected', 'heb', 'בי פ', '["V/i"]', '["with <the>/ me"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3318P}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["to/ go out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7965J}/H9021/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["peace/ your"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1206}/[H948]', 'inflected', 'heb', 'בֹץ', '["bôts"]', '["in the/ mire"]', '["n-m"]', 'mud (as whitish clay) mire.', 'probably the same as 948;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1697H}\/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["the/ matter"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5921A}/H9034\/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["on/ it"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5371G}/[H5370]', 'lemma', 'heb', 'נֵרְגַּל שַׁרְאֶצֶר', '["Nêrᵉgal Sharʼetser"]', '["Nergal-","Shar-","ezer"]', '["n-pr-m"]', 'Nergal-Sharetser, the name of two Babylonians Nergal-sharezer.', 'from 5370 and 8272;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5562>', 'opaque', 'heb', 'סַמְגַּר נְבוֹ', '["Çamgar Nᵉbôw"]', '["Nebu","Samgar"]', '["n-pr-m"]', 'Samgar-Nebo, a Babylonian general Samgar-nebo.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8310}/[H8310]', 'lemma', 'heb', 'שַׂרְסְכִים', '["Sarçᵉkîym"]', '["-sekim","Sar-"]', '["n-pr-m"]', 'Sarsekim, a Babylonian general Sarsechim.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7249H}/[H7227]', 'lemma', 'heb', 'רַב־סָרִיס', '["Rab-Çârîyç"]', '["[the] Rab-","saris"]', '["n-pr-m"]', 'Rab-Saris, a Babylonian official Rab-saris.', 'from 7227 and a foreign word for a eunuch; chief chamberlain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7248}/[H7227]', 'lemma', 'heb', 'רַב־מָג', '["Rab-Mâg"]', '["[the] Rab-","mag"]', '["n-m"]', 'Rab-Mag, a Babylonian official Rab-mag.', 'from 7227 and a foreign word for a Magian; chief Magian;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3010}/[H3009]', 'inflected', 'heb', 'יָגֵב', '["yâgêb"]', '["and/ fields"]', '["n-m"]', 'a plowed field field.', 'from 3009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5021}/[H5021]', 'inflected', 'heb', 'נְבוּשַׁזְבָּן', '["Nᵉbûwshazbân"]', '["and/ Nebushazban"]', '["n-pr-m"]', 'Nebushazban, Nebuchadnezzar''s chief eunuch Nebushazban.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5371H}/[H5370]', 'inflected', 'heb', 'נֵרְגַּל שַׁרְאֶצֶר', '["Nêrᵉgal Sharʼetser"]', '["and/ Nergal-"]', '["n-pr-m"]', 'Nergal-Sharetser, the name of two Babylonians Nergal-sharezer.', 'from 5370 and 8272;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5371H}/[H5370]', 'lemma', 'heb', 'נֵרְגַּל שַׁרְאֶצֶר', '["Nêrᵉgal Sharʼetser"]', '["Shar-","ezer"]', '["n-pr-m"]', 'Nergal-Sharetser, the name of two Babylonians Nergal-sharezer.', 'from 5370 and 8272;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2691A}/[H2690]', 'inflected', 'heb', 'חָצֵר', '["châtsêr"]', '["from/ [the] courtyard of"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3318H}/H9033/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["to/ take out/ him"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5663}/[H5650]', 'inflected', 'heb', 'עֶבֶד מֶלֶךְ', '["ʻEbed Melek"]', '["to/ Ebed"]', '["n-pr-m"]', 'Ebed-Melek, a eunuch of Zedekeah Ebed-melech.', 'from 5650 and 4428; servant of a king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4422}/H9031/[H4422]', 'inflected', 'heb', 'מָלַט', '["mâlaṭ"]', '["I will rescue/ you"]', '["v"]', 'properly, to be smooth, i.e. (by implication) to escape (as if by slipperiness); causatively, to release or rescue; specifically, to bring forth young, emit sparks deliver (self), escape, lay, leap out, let alone, let go, preserve, save, × speedily, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3947G}/H9043/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["when/ took/ he"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0246}/[H2131]', 'inflected', 'heb', 'אֲזִקִּים', '["ʼăziqqîym"]', '["with <the>/ chains"]', '["n-m"]', 'manacles chains.', 'a variation for 2131;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1540K}/[H1540]', 'inflected', 'heb', 'גָּלָה', '["gâlâh"]', '["who/ were being taken into exile"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6605A}/H9031/[H6605]', 'inflected', 'heb', 'פָּתַח', '["pâthach"]', '["I have set free/ you"]', '["v"]', 'to open wide (literally or figuratively); specifically, to loosen, begin, plough, carve appear, break forth, draw (out), let go free, (en-) grave(-n), loose (self), (be, be set) open(-ing), put off, ungird, unstop, have vent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0246}/[H2131]', 'inflected', 'heb', 'אֲזִקִּים', '["ʼăziqqîym"]', '["the/ chains"]', '["n-m"]', 'manacles chains.', 'a variation for 2131;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869I}/H9020/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["eye/ my"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7725G}/H9012/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ return/ !"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1436G}/[H1431]', 'lemma', 'heb', 'גְּדַּלְיָה', '["Gᵉdalyâh"]', '["Gedaliah"]', '["n-pr-m"]', 'Gedaljah, the name of five Israelites Gedaliah.', 'or (prolonged) גְּדַלְיָהוּ; from 1431 and 3050; Jah has become great;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4864}/[H5375]', 'inflected', 'heb', 'מַשְׂאֵת', '["masʼêth"]', '["and/ a portion of","and/ a present"]', '["n-f"]', 'properly, (abstractly) a raising (as of the hands in prayer), or rising (of flame); figuratively, an utterance; concretely, a beacon (as raised); a present (as taken), mess, or tribute; figuratively, a reproach (as a burden) burden, collection, sign of fire, (great) flame, gift, lifting up, mess, oblation, reward.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2945}/[H2952]', 'inflected', 'heb', 'טַף', '["ṭaph"]', '["and/ little one[s]"]', '["n-m"]', 'a family (mostly used collectively in the singular) (little) children (ones), families.', 'from 2952 (perhaps referring to the tripping gait of children);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3129L}/[H3083]', 'inflected', 'heb', 'יוֹנָתָן', '["Yôwnâthân"]', '["and/ Jonathan"]', '["n-pr-m"]', 'Jonathan, the name of ten Israelites Jonathan.', 'a form of 3083;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5778}/[H5775]', 'lemma', 'heb', 'עוֹפַי', '["ʻÔwphay"]', '["Ephai"]', '["n-pr-m"]', 'Ephai, an Israelite Ephai (from margin).', 'from 5775; birdlike;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5647G}/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["from/ serving"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1185}/[H5965]', 'lemma', 'heb', 'בַּעֲלִיס', '["Baʻălîyç"]', '["Baalis"]', '["n-pr-m"]', 'Baalis, an Ammonitish king Baalis.', 'probably from a derivative of 5965 with prepositional prefix; in exultation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5221}/H9031/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["to/ strike/ you"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3063N}/[H3034]', 'lemma', 'heb', 'יְהוּדָה', '["Yᵉhûwdâh"]', '["Jews","Judah"]', '["n-pr-m"]', 'Jehudah (or Judah), the name of five Israelites; also of the tribe descended from the first, and of its territory Judah.', 'from 3034; celebrated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6908}/[H6908]', 'inflected', 'heb', 'קָבַץ', '["qâbats"]', '["who/ have gathered"]', '["v"]', 'to grasp, i.e. collect assemble (selves), gather (bring) (together, selves together, up), heap, resort, × surely, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3110G}/[H3076]', 'lemma', 'heb', 'יוֹחָנָן', '["Yôwchânân"]', '["Johanan"]', '["n-pr-m"]', 'Jochanan, the name of nine Israelites Johanan.', 'a form of 3076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3458H}\/[H8085]', 'inflected', 'heb', 'יִשְׁמָעֵאל', '["Yishmâʻêʼl"]', '["Ishmael"]', '["n-pr-m"]', 'Jishmael, the name of Abraham''s oldest son, and of five Israelites Ishmael.', 'from 8085 and 410; God will hear;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7227B}/[H7231]', 'inflected', 'heb', 'רַב', '["rab"]', '["and/ [the] chiefs of"]', '["a n-m"]', 'abundant (in quantity, size, age, number, rank, quality) (in) abound(-undance, -ant, -antly), captain, elder, enough, exceedingly, full, great(-ly, man, one), increase, long (enough, (time)), (do, have) many(-ifold, things, a time), (ship-)master, mighty, more, (too, very) much, multiply(-tude), officer, often(-times), plenteous, populous, prince, process (of time), suffice(-lent).', 'by contracted from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7927G}/[H7926]', 'inflected', 'heb', 'שְׁכֶם', '["Shᵉkem"]', '["from/ Shechem"]', '["n-pr-m n-pr-loc"]', 'Shekem, a place in Palestine Shechem.', 'the same as 7926; ridge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7167}/[H7167]', 'inflected', 'heb', 'קָרַע', '["qâraʻ"]', '["and/ torn of","so/ I may tear"]', '["v"]', 'to rend, literally or figuratively (revile, paint the eyes, as if enlarging them) cut out, rend, × surely, tear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1413}/[H1464]', 'inflected', 'heb', 'גָּדַד', '["gâdad"]', '["and/ having cut themselves"]', '["v"]', 'to crowd; also to gash (as if by pressing into) assemble (selves by troops), gather (selves together, self in troops), cut selves.', 'a primitive root (compare 1464);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6298}/[H6298]', 'inflected', 'heb', 'פָּגַשׁ', '["pâgash"]', '["when/ met"]', '["v"]', 'to come in contact with, whether by accident or violence; figuratively, to concur meet (with, together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0296}\/[H251]', 'inflected', 'heb', 'אֲחִיקָם', '["ʼĂchîyqâm"]', '["Ahikam"]', '["n-pr-m"]', 'Achikam, an Israelite Ahikam.', 'from 251 and 6965; brother of rising (i.e. high);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4191}/H9038/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["he killed/ them"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1628}/[H1481]', 'inflected', 'heb', 'גֵּרוּת', '["gêrûwth"]', '["at/ Geruth"]', '["n-f"]', 'a (temporary) residence habitation.', 'from 1481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3644H}/[H3651]', 'lemma', 'heb', 'כְּמוֹ', '["kᵉmôw"]', '["Kimham"]', '["prt"]', 'as, thus, so according to, (such) as (it were, well as), in comparison of, like (as, to, unto), thus, when, worth.', 'or כָּמוֹ; a form of the prefix k, but used separately [compare 3651];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3153}/[H2970]', 'inflected', 'heb', 'יְזַנְיָה', '["Yᵉzanyâh"]', '["and/ Jezaniah"]', '["n-pr-m"]', 'Jezanjah, an Israelite Jezaniah.', 'or יְזַנְיָהוּ; probably for 2970;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1955H}/[H3467]', 'lemma', 'heb', 'הוֹשַׁעְיָה', '["Hôwshaʻyâh"]', '["Hoshaiah"]', '["n-pr-m"]', 'Hoshajah, the name of two Israelites Hoshaiah.', 'from 3467 and 3050; Jah has saved;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5307N}/[H5307]', 'lemma', 'heb', 'נָפַל', '["nâphal"]', '["[are] making fall","may it fall"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8467}/H9025/[H2603]', 'inflected', 'heb', 'תְּחִנָּה', '["tᵉchinnâh"]', '["supplication/ our"]', '["n-f"]', 'graciousness; causatively, entreaty favour, grace, supplication.', 'from 2603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5307N}/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["to/ make fall"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8467}/H9026/[H2603]', 'inflected', 'heb', 'תְּחִנָּה', '["tᵉchinnâh"]', '["supplication/ your"]', '["n-f"]', 'graciousness; causatively, entreaty favour, grace, supplication.', 'from 2603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5337}/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["and/ to/ deliver"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5838y}', 'inflected', 'heb', 'עזריה', '["''a.zar.Yah"]', '["Azariah"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2086}/[H2102]', 'inflected', 'heb', 'זֵד', '["zêd"]', '["<the>/ arrogant"]', '["n-m"]', 'arrogant presumptuous, proud.', 'from 2102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1540K}/[H1540]', 'inflected', 'heb', 'גָּלָה', '["gâlâh"]', '["and/ to/ take into exile"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8471}\/[H8471]', 'inflected', 'heb', 'תַּחְפַּנְחֵס', '["Tachpanchêç"]', '["Tahpanhes"]', '["n-pr-loc"]', 'Tachpanches, Techaphneches or Tachpenes, a place in Egypt Tahapanes, Tahpanhes, Tehaphnehes.', 'or תְּחַפְנְחֵס; (Ezekiel 30:18), or תַּחְפְּנֵס; (Jeremiah 2:16), of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8471}/[H8471]', 'inflected', 'heb', 'תַּחְפַּנְחֵס', '["Tachpanchêç"]', '["in/ Tahpanhes"]', '["n-pr-loc"]', 'Tachpanches, Techaphneches or Tachpenes, a place in Egypt Tahapanes, Tahpanhes, Tehaphnehes.', 'or תְּחַפְנְחֵס; (Ezekiel 30:18), or תַּחְפְּנֵס; (Jeremiah 2:16), of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4423}/[H4422]', 'inflected', 'heb', 'מֶלֶט', '["meleṭ"]', '["in the/ mortar"]', '["n-m"]', 'cement (from its plastic smoothness) clay.', 'from 4422,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8237}/H9023/[H8231]', 'inflected', 'heb', 'שַׁפְרוּר', '["shaphrûwr"]', '["state tent/ his"]', '["n-m"]', 'splendid, i.e. a tapestry or canopy royal pavilion.', 'from 8231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1053J}/[H1004]', 'lemma', 'heb', 'בֵּית שֶׁמֶשׁ', '["Bêyth Shemesh"]', '["Beth","Shemesh"]', '["n-pr-loc"]', 'Beth-Shemesh, a place in Palestine Beth-shemesh.', 'from 1004 and 8121; house of (the) sun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4024B}/[H4024]', 'inflected', 'heb', 'מִגְדּוֹל', '["Migdôwl"]', '["in/ Migdol"]', '["n-pr-m n-m"]', 'Migdol, a place in Egypt Migdol, tower.', 'or מִגְדֹּל; probably of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8471}/[H8471]', 'inflected', 'heb', 'תַּחְפַּנְחֵס', '["Tachpanchêç"]', '["and/ in/ Tahpanhes"]', '["n-pr-loc"]', 'Tachpanches, Techaphneches or Tachpenes, a place in Egypt Tahapanes, Tahpanhes, Tehaphnehes.', 'or תְּחַפְנְחֵס; (Ezekiel 30:18), or תַּחְפְּנֵס; (Jeremiah 2:16), of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5297}/[H4644]', 'inflected', 'heb', 'נֹף', '["Nôph"]', '["and/ in/ Memphis"]', '["n-pr-loc"]', 'Noph, the capital of Upper Egypt Noph.', 'a variation of 4644;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6624}/[H6624]', 'lemma', 'heb', 'פַּתְרוֹס', '["Pathrôwç"]', '["Pathros"]', '["n-pr-loc"]', 'Pathros, a part of Egypt Pathros.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7451I}/H9028/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["from/ wickedness/ their"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4639K}/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["by/ [the] deeds of"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1961}/H9046/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["to become/ you"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2708}/H9020/[H2706]', 'inflected', 'heb', 'חֻקָּה', '["chuqqâh"]', '["and/ in/ decrees/ my"]', '["n-f"]', 'appointed, custom, manner, ordinance, site, statute.', 'feminine of 2706, and meaning substantially the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8300}/[H8277]', 'inflected', 'heb', 'שָׂרִיד', '["sârîyd"]', '["and/ a survivor"]', '["n-m"]', 'a survivor × alive, left, remain(-ing), remnant, rest.', 'from 8277;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7611}/[H7604]', 'inflected', 'heb', 'שְׁאֵרִית', '["shᵉʼêrîyth"]', '["[will be] to/ [the] remnant of","into/ a remnant","of/ [the] rest of","to/ [the] remnant of","to/ [the] rest of"]', '["n-f"]', 'a remainder or residual (surviving, final) portion that had escaped, be left, posterity, remain(-der), remnant, residue, rest.', 'from 7604;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6412B}\/[H6403]', 'inflected', 'heb', 'פָּלִיט', '["pâlîyṭ"]', '["fugitives"]', '["n-m"]', 'a refugee (that have) escape(-d, -th), fugitive.', 'or פָּלֵיט; or פָּלֵט; from 6403;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6624}/[H6624]', 'inflected', 'heb', 'פַּתְרוֹס', '["Pathrôwç"]', '["in/ Pathros"]', '["n-pr-loc"]', 'Pathros, a part of Egypt Pathros.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0369}/H9045/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["not/ we"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6310G}/H9025/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["from/ mouth/ our"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8269}/H9025/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["and/ officials/ our"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7451C}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["and/ distress"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0227B}/[H227]', 'lemma', 'heb', 'אָז', '["ʼâz"]', '["then"]', '["adv"]', 'at that time or place; also as a conjunction, therefore beginning, for, from, hitherto, now, of old, once, since, then, at which time, yet.', 'a demonstrative adverb;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0582}/H9025/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["husbands/ our"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6087B}/H9034/[H6087]', 'inflected', 'heb', 'עָצַב', '["ʻâtsab"]', '["to/ form image/ her"]', '["v"]', 'properly, to carve, i.e. fabricate or fashion; hence (in a bad sense) to worry, pain or anger displease, grieve, hurt, make, be sorry, vex, worship, wrest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5262}\/[H5258]', 'inflected', 'heb', 'נֶסֶךְ', '["neçek"]', '["drink offerings"]', '["n-m"]', 'a libation; also a cast idol cover, drink offering, molten image.', 'or נֵסֶךְ; from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7002}/[H6999]', 'inflected', 'heb', 'קִטֵּר', '["qiṭṭêr"]', '["the/ incense"]', '["n-f"]', 'perfume incense.', 'from 6999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8269}/H9026/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["and/ officials/ your"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8047G}/[H8074]', 'inflected', 'heb', 'שַׁמָּה', '["shammâh"]', '["and/ <into>/ a waste"]', '["n-f"]', 'ruin; by implication, consternation astonishment, desolate(-ion), waste, wonderful thing.', 'from 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2708}/H9023/[H2706]', 'inflected', 'heb', 'חֻקָּה', '["chuqqâh"]', '["and/ in/ decrees/ his"]', '["n-f"]', 'appointed, custom, manner, ordinance, site, statute.', 'feminine of 2706, and meaning substantially the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5715}/H9023/[H5707]', 'inflected', 'heb', 'עֵדוּת', '["ʻêdûwth"]', '["and/ in/ testimonies/ his"]', '["n-f"]', 'testimony testimony, witness.', 'feminine of 5707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0802H}/H9026/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["and/ wives/ your"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6310G}/H9026/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["with/ mouth/ your"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3027G}/H9026/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ with/ hands/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5088}/H9025/[H5087]', 'inflected', 'heb', 'נֶדֶר', '["neder"]', '["vows/ our"]', '["n-m"]', 'a promise (to God); also (concretely) a thing promised vow(-ed).', 'or נֵדֶר; from 5087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5088}/H9026\/[H5087]', 'inflected', 'heb', 'נֶדֶר', '["neder"]', '["vows/ your"]', '["n-m"]', 'a promise (to God); also (concretely) a thing promised vow(-ed).', 'or נֵדֶר; from 5087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7451C}\/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["for/ harm"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6547S}/[H6547]', 'lemma', 'heb', 'פַּרְעֹה', '["Parʻôh"]', '["Pharaoh"]', '["n-m"]', 'Paroh, a general title of Egyptian kings Pharaoh.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6548}/[H6548]', 'lemma', 'heb', 'פַּרְעֹה חׇפְרַע', '["Parʻôh Chophraʻ"]', '["Hophra"]', '["n-pr-m"]', 'Paroh-Chophra, an Egyptian king Pharaoh-hophra.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315H}/H9023\/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["life/ his"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3789}/H9043/[H3789]', 'inflected', 'heb', 'כָּתַב', '["kâthab"]', '["when/ wrote/ he"]', '["v"]', 'to grave, by implication, to write (describe, inscribe, prescribe, subscribe) describe, record, prescribe, subscribe, write(-ing, -ten).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4341}/H9020/[H3510]', 'inflected', 'heb', 'מַכְאֹב', '["makʼôb"]', '["pain/ my"]', '["n-m"]', 'anguish or (figuratively) affliction grief, pain, sorrow.', 'sometimes מַכְאוֹב; also (feminine Isaiah 53:3) מַכְאֹבָה; from 3510;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4496H}/[H4495]', 'inflected', 'heb', 'מְנוּחָה', '["mᵉnûwchâh"]', '["and/ rest"]', '["n-f"]', 'repose or (adverbially) peacefully; figuratively, consolation (specifically, matrimony); hence (concretely) an abode comfortable, ease, quiet, rest(-ing place), still.', 'or מְנֻחָה; feminine of 4495;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5066G}/[H5066]', 'inflected', 'heb', 'נָגַשׁ', '["nâgash"]', '["and/ draw near"]', '["v"]', 'to be or come (causatively, bring) near (for any purpose); euphemistically, to lie with a woman; as an enemy, to attack; religious to worship; causatively, to present; figuratively, to adduce an argument; by reversal, to stand back (make to) approach (nigh), bring (forth, hither, near), (cause to) come (hither, near, nigh), give place, go hard (up), (be, draw, go) near (nigh), offer, overtake, present, put, stand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5927K}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["and/ mount"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6571A}/[H6567]', 'inflected', 'heb', 'פָּרָשׁ', '["pârâsh"]', '["the/ warhorses"]', '["n-m"]', 'a steed (as stretched out to a vehicle, not single nor for mounting ); also (by implication) a driver (in a chariot), i.e. (collectively) cavalry horseman.', 'from 6567; (compare 5483)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3553>', 'inflected', 'heb', 'בכובעים', '["be./Khoa.''Im"]', '["with/ helmets"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H7420>', 'inflected', 'heb', 'הרמחים', '["ha./re.ma.Chim"]', '["the/ spears"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5630}/[H8302]', 'inflected', 'heb', 'סִרְיֹן', '["çiryôn"]', '["the/ armor"]', '["n-m"]', 'a coat of mail brigandine.', 'for 8302;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1368}/H9028/[H1397]', 'inflected', 'heb', 'גִּבּוֹר', '["gibbôwr"]', '["and/ warriors/ their"]', '["a"]', 'powerful; by implication, warrior, tyrant champion, chief, × excel, giant, man, mighty (man, one), strong (man), valiant man.', 'or גִּבֹּר; (shortened) intensive from the same as 1397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7031}/[H7043]', 'inflected', 'heb', 'קַל', '["qal"]', '["the/ swift [one]"]', '["a"]', 'light; (by implication) rapid (also adverbial) light, swift(-ly).', 'contracted from 7043;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H5104H}/[H5102]', 'inflected', 'heb', 'נָהָר', '["nâhâr"]', '["and/ like <the>/ rivers"]', '["n-m"]', 'a stream (including the sea; expectation the Nile, Euphrates, etc.); figuratively, prosperity flood, river.', 'from 5102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1984I}/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["and/ drive madly"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6316H>', 'inflected', 'heb', 'ופוט', '["u./Fut"]', '["and/ Put"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3866H}/[H3865]', 'inflected', 'heb', 'לוּדִי', '["Lûwdîy"]', '["and/ Ludites"]', '["a"]', 'a Ludite or inhabitants of Lud (only in plural) Ludim. Lydians.', 'or לוּדִיִּי; patrial from 3865;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6682}/H9022/[H6681]', 'inflected', 'heb', 'צְוָחָה', '["tsᵉvâchâh"]', '["and/ outcry/ your"]', '["n-f"]', 'a screech (of anguish) cry(-ing).', 'from 6681;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8147}/H9028\/[H8145]', 'inflected', 'heb', 'שְׁנַיִם', '["shᵉnayim"]', '["both of/ them"]', '["n"]', 'two; also (as ordinal) twofold both, couple, double, second, twain, twelfth, twelve, twenty (sixscore) thousand, twice, two.', 'dual of 8145; feminine שְׁתַּיִם;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5297}/[H4644]', 'inflected', 'heb', 'נֹף', '["Nôph"]', '["in/ Memphis"]', '["n-pr-loc"]', 'Noph, the capital of Upper Egypt Noph.', 'a variation of 4644;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0047I}/H9021/[H46]', 'inflected', 'heb', 'אַבִּיר', '["ʼabbîyr"]', '["mighty [ones]/ your"]', '["a-m"]', 'angel, bull, chiefest, mighty (one), stout(-hearted), strong (one), valiant.', 'for 46');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4138}/H9025/[H3205]', 'inflected', 'heb', 'מוֹלֶדֶת', '["môwledeth"]', '["kindred/ our"]', '["n-f"]', 'nativity (plural birth-place); by implication, lineage, native country; also offspring, family begotten, born, issue, kindred, native(-ity).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8396G}/[H8406]', 'inflected', 'heb', 'תָּבוֹר', '["Tâbôwr"]', '["like/ Tabor"]', '["n-pr"]', 'Tabor, a mountain in Palestine, also a city adjacent Tabor.', 'from a root corresponding to 8406; broken region;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H3760G}/[H3759]', 'inflected', 'heb', 'כַּרְמֶל', '["Karmel"]', '["and/ like/ Carmel"]', '["n-pr-loc"]', 'Karmel, the name of a hill and of a town in Palestine Carmel, fruitful (plentiful) field, (place).', 'the same as 3759;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3304}/[H3302]', 'lemma', 'heb', 'יְפֵה־פִיָּה', '["yᵉphêh-phîyâh"]', '["beautiful","beautifully"]', '["a"]', 'very beautiful very fair.', 'from 3302 by reduplication;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7171}/[H7169]', 'lemma', 'heb', 'קֶרֶץ', '["qerets"]', '["a gadfly"]', '["n-m"]', 'extirpation (as if by constriction) destruction.', 'from 7169;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7916}/H9024/[H7936]', 'inflected', 'heb', 'שָׂכִיר', '["sâkîyr"]', '["hired soldiers/ its"]', '["a"]', 'a man at wages by the day or year hired (man, servant), hireling.', 'from 7936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6963H>/H9024', 'opaque', 'heb', 'קוֹל', '["qôwl"]', '["sound/ its"]', '["n-m"]', 'a voice or sound aloud, bleating, crackling, cry ( out), fame, lightness, lowing, noise, hold peace, (pro-) claim, proclamation, sing, sound, spark, thunder(-ing), voice, yell.', 'or קֹל; from an unused root meaning to call aloud;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7134}/[H6923]', 'inflected', 'heb', 'קַרְדֹּם', '["qardôm"]', '["and/ with/ axes"]', '["n-m"]', 'an axe ax.', 'perhaps from 6923 in the sense of striking upon;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2404}/[H2404]', 'inflected', 'heb', 'חָטַב', '["châṭab"]', '["like/ cutters of"]', '["v"]', 'to chop or carve wood cut down, hew(-er), polish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3293A>/H9024', 'opaque', 'heb', 'יַעַר', '["yaʻar"]', '["forest/ its"]', '["n-m"]', 'a copse of bushes; hence, a forest; hence, honey in the comb (as hived in trees) (honey-) comb, forest, wood.', 'from an unused root probably meaning to thicken with verdure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0697}/[H7235]', 'inflected', 'heb', 'אַרְבֶּה', '["ʼarbeh"]', '["more than/ locust[s]"]', '["n-m"]', 'a locust (from its rapid increase) grasshopper, locust.', 'from 7235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0528}/[H4996]', 'lemma', 'heb', 'אָמוֹן', '["ʼÂmôwn"]', '["Amon"]', '["n-pr-m"]', 'Amon (i.e. Ammon or Amn), a deity of Egypt multitude, populous.', 'of Egyptian derivation; used only as an adjunct of 4996');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4996}/[H4996]', 'inflected', 'heb', 'נֹא', '["Nôʼ"]', '["from/ Thebes"]', '["n-pr-loc"]', 'No (i.e. Thebes), the capital of Upper Egypt No. Compare 528.', 'of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2729}\/[H2729]', 'inflected', 'heb', 'חָרַד', '["chârad"]', '["[will be one who] disturbs [them]","[will be one who] terrifies"]', '["v"]', 'to shudder with terror; hence, to fear; also to hasten (with anxiety) be (make) afraid, be careful, discomfit, fray (away), quake, tremble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5804}\/[H5794]', 'inflected', 'heb', 'עַזָּה', '["ʻAzzâh"]', '["Gaza"]', '["n-f"]', 'Azzah, a place in Palestine Azzah, Gaza.', 'feminine of 5794; strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7857}/[H7857]', 'inflected', 'heb', 'שָׁטַף', '["shâṭaph"]', '["and/ they may overflow"]', '["v"]', 'to gush; by implication, to inundate, cleanse; by analogy, to gallop, conquer drown, (over-) flow(-whelm, rinse, run, rush, (throughly) wash (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3213}/[H3213]', 'inflected', 'heb', 'יָלַל', '["yâlal"]', '["and/ he will wail","and/ they will wail"]', '["v"]', 'to howl (with a wailing tone) or yell (with a boisterous one) (make to) howl, be howling.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8161>', 'opaque', 'heb', 'שַׁעֲטָה', '["shaʻăṭâh"]', '["[the] stamping of"]', '["n-f"]', 'a clatter (of hoofs) stamping.', 'feminine from an unused root meaning to stamp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7494}/[H7493]', 'inflected', 'heb', 'רַעַשׁ', '["raʻash"]', '["from/ [the] rattling"]', '["n-m"]', 'vibration, bounding, uproar commotion, confused noise, earthquake, fierceness, quaking, rattling, rushing, shaking.', 'from 7493;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7393G}/H9023/[H7392]', 'inflected', 'heb', 'רֶכֶב', '["rekeb"]', '["of/ chariotry/ its"]', '["n-m"]', 'a vehicle; by implication, a team; by extension, cavalry; by analogy a rider, i.e. the upper millstone chariot, (upper) millstone, multitude (from the margin), wagon.', 'from 7392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1534}/H9023/[H1556]', 'inflected', 'heb', 'גַּלְגַּל', '["galgal"]', '["wheels/ its"]', '["n-m"]', 'a wheel; by analogy, a whirlwind; also dust (as whirled) heaven, rolling thing, wheel.', 'by reduplication from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7510}/[H7503]', 'inflected', 'heb', 'רִפְיוֹן', '["riphyôwn"]', '["from/ slackness of"]', '["n-m"]', 'slackness feebleness.', 'from 7503;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6721H}/[H6679]', 'inflected', 'heb', 'צִידוֹן', '["Tsîydôwn"]', '["and/ to/ Sidon"]', '["n-pr-loc"]', 'Tsidon, the name of a son of Canaan, and of a place in Palestine Sidon, Zidon.', 'or צִידֹן; from 6679 in the sense of catching fish; fishery;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3731}/[H3730]', 'lemma', 'heb', 'כַּפְתֹּר', '["Kaphtôr"]', '["Caphtor"]', '["n-pr-loc"]', 'Caphtor (i.e. a wreath-shaped island), the original seat of the Philistines Caphtor.', 'or (Amos 9:7) כַּפְתּוֹר; apparently the same as 3730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6010R}/H9028/[H6009]', 'inflected', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["valley/ their"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1413}\/[H1464]', 'inflected', 'heb', 'גָּדַד', '["gâdad"]', '["will you cut yourself"]', '["v"]', 'to crowd; also to gash (as if by pressing into) assemble (selves by troops), gather (selves together, self in troops), cut selves.', 'a primitive root (compare 1464);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8593}/H9022/[H6168]', 'inflected', 'heb', 'תַּעַר', '["taʻar"]', '["sheath/ your"]', '["n"]', 'a knife or razor (as making bare); also a scabbard (as being bare, i.e. empty) (pen-) knife, razor, scabbard, shave, sheath.', 'from 6168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1826A}/[H1724]', 'inflected', 'heb', 'דָּמַם', '["dâmam"]', '["and/ be still"]', '["v"]', 'to be dumb; by implication, to be astonished, to stop; also to perish cease, be cut down (off), forbear, hold peace, quiet self, rest, be silent, keep (put to) silence, be (stand) still, tarry, wait.', 'a primitive root (compare 1724, 1820);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3259}/H9034\/[H3259]', 'inflected', 'heb', 'יָעַד', '["yâʻad"]', '["he has appointed/ it"]', '["v"]', 'to fix upon (by agreement or appointment); by implication, to meet (at a stated time), to summon (to trial), to direct (in a certain quarter or position), to engage (for marriage) agree,(maxke an) appoint(-ment, a time), assemble (selves), betroth, gather (selves, together), meet (together), set (a time).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4869B}/[H7682]', 'inflected', 'heb', 'מִשְׂגָּב', '["misgâb"]', '["the/ stronghold"]', '["n-m n-pr-loc"]', 'properly, a cliff (or other lofty or inaccessible place); abstractly, altitude; figuratively, a refuge; Misgab, a place in Moab defence, high fort (tower), refuge, Misgab.', 'from 7682;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3772I}/H9034/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["and/ let us cut off/ it"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4086}/[H1828]', 'lemma', 'heb', 'מַדְמֵן', '["Madmên"]', '["O Madmen"]', '["n-pr-loc"]', 'Madmen, a place in Palestine Madmen.', 'from the same as 1828; dunghill;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2773}/[H2356]', 'inflected', 'heb', 'חֹרֹנַיִם', '["Chôrônayim"]', '["from/ Horonaim"]', '["n-pr-m"]', 'Choronajim, a place in Moab Horonaim.', 'dual of a derivative from 2356; double cave-town;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6810}/H9024/[H6819]', 'inflected', 'heb', 'צָעִיר', '["tsâʻîyr"]', '["servants/ its"]', '["a"]', 'little; (in number) few; (in age) young, (in value) ignoble least, little (one), small (one), young(-er, -est).', 'or צָעוֹר; from 6819;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0982}/H9042/[H982]', 'inflected', 'heb', 'בָּטַח', '["bâṭach"]', '["trusting/ you"]', '["v"]', 'properly, to hie for refuge (but not so precipitately as 2620); figuratively, to trust, be confident or sure be bold (confident, secure, sure), careless (one, woman), put confidence, (make to) hope, (put, make to) trust.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4639K}/H9022/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["in/ deeds/ your"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0214}/H9022/[H686]', 'inflected', 'heb', 'אוֹצָר', '["ʼôwtsâr"]', '["and/ in/ treasures/ your"]', '["n-m"]', 'a depository armory, cellar, garner, store(-house), treasure(-house) (-y).', 'from 686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6731B}/[H6692]', 'lemma', 'heb', 'צִיץ', '["tsîyts"]', '["salt"]', '["n-m"]', 'properly, glistening, i.e. a burnished plate; also a flower (as bright colored); a wing (as gleaming in the air) blossom, flower, plate, wing.', 'or צִץ; from 6692;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5323}/[H5323]', 'lemma', 'heb', 'נָצָא', '["nâtsâʼ"]', '["[surely] flying"]', '["v"]', 'to go away flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5892B}/H9024/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["and/ cities/ its"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8105}/H9023/[H8104]', 'inflected', 'heb', 'שֶׁמֶר', '["shemer"]', '["lees/ its"]', '["n-m"]', 'something preserved, i.e. the settlings (plural only) of wine dregs, (wines on the) lees.', 'from 8104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1473}/[H1540]', 'inflected', 'heb', 'גּוֹלָה', '["gôwlâh"]', '["and/ in <the>/ exile"]', '["n-f"]', 'exile; concretely and collectively exiles (carried away), captive(-ity), removing.', 'or (shortened) גֹּלָה; active participle feminine of 1540;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7381}/H9023/[H7306]', 'inflected', 'heb', 'רֵיחַ', '["rêyach"]', '["and/ aroma/ its"]', '["n-m"]', 'odor (as if blown) savour, scent, smell.', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4171}\/[H4171]', 'inflected', 'heb', 'מוּר', '["mûwr"]', '["it has been changed"]', '["v"]', 'to alter; by implication, to barter, to dispose of × at all, (ex-) change, remove.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6808}/H9033/[H6808]', 'inflected', 'heb', 'צָעָה', '["tsâʻâh"]', '["and/ they will tip/ it"]', '["v"]', 'to tip over (for the purpose of spilling or pouring out), i.e. (figuratively) depopulate; by implication, to imprison or conquer; (reflexive) to lie down (for coitus) captive exile, travelling, (cause to) wander(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5035A}/H9028/[H5034]', 'inflected', 'heb', 'נֶבֶל', '["nebel"]', '["and/ jars/ their"]', '["n-m"]', 'a skin-bag for liquids (from collapsing when empty); hence, a vase (as similar in shape when full); also a lyre (as having a body of like form) bottle, pitcher, psaltery, vessel, viol.', 'or נֵבֶל; from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H3645>', 'inflected', 'heb', 'מכמוש', '["mi./ke.Mo.osh"]', '["from/ Chemosh"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4009}/H9028/[H982]', 'inflected', 'heb', 'מִבְטָח', '["mibṭâch"]', '["trust/ their"]', '["n-m"]', 'properly, a refuge, i.e. (objective) security, or (subjective) assurance confidence, hope, sure, trust.', 'from 982;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7451C}/H9023/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["and/ calamity/ its"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4013}/H9022/[H1219]', 'inflected', 'heb', 'מִבְצָר', '["mibtsâr"]', '["strongholds/ your"]', '["n-m"]', 'a fortification, castle, or fortified city; figuratively, a defender (de-, most) fenced, fortress, (most) strong (hold).', 'also (in plural) feminine (Daniel 11:l5) מִבְצָרָה; from 1219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6177H}/[H6176]', 'lemma', 'heb', 'עֲרוֹעֵר', '["ʻĂrôwʻêr"]', '["Aroer"]', '["n-pr-loc"]', 'Aroër, the name of three places in or near Palestine Aroer.', 'or עֲרֹעֵר; or עַרְעוֹר; the same as 6176; nudity of situation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0769}/[H7442]', 'inflected', 'heb', 'אַרְנוֹן', '["ʼArnôwn"]', '["at/ [the] Arnon"]', '["n-pr-loc"]', 'the Arnon, a river east of the Jordan, also its territory Arnon.', 'or אַרְנֹןlemma אַרְנן missing vowel, corrected to אַרְנֹן; from 7442; a brawling stream;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2473H}/[H2344]', 'lemma', 'heb', 'חֹלוֹן', '["Chôlôwn"]', '["Holon"]', '["n-pr-loc"]', 'Cholon, the name of two places in Palestine Holon.', 'or (shortened) חֹלֹן; probably from 2344; sandy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1015}/[H1004]', 'lemma', 'heb', 'בֵּית דִּבְלָתַיִם', '["Bêyth Diblâthayim"]', '["Beth","Diblathaim"]', '["n-pr-loc"]', 'Beth-Diblathajim, a place East of the Jordan Beth-diblathaim.', 'from 1004 and the dual of 1690; house of (the) two figcakes;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1014}/[H1004]', 'lemma', 'heb', 'בֵּית גָּמוּל', '["Bêyth Gâmûwl"]', '["Beth","Gamul"]', '["n-pr-loc"]', 'Beth-Gamul, a place East of the Jordan Beth-gamul.', 'from 1004 and the passive participle of 1576; house of (the) weaned;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1010}/[H1004]', 'lemma', 'heb', 'בֵּית בַּעַל מְעוֹן', '["Bêyth Baʻal Mᵉʻôwn"]', '["Beth","Meon"]', '["n-pr-loc"]', 'Beth-Baal-Meon, a place in Palestine Beth-baal-meon. Compare 1186 and 1194.', 'from 1004 and 1168 and 4583; house of Baal of (the) habitation of (apparently by transposition); or (shorter) בֵּית מְעוֹןlemma בֵּית מעוֹן missing vowel, corrected to בֵּית מְעוֹן; house of habitation of (Baal);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7152H}/[H7151]', 'lemma', 'heb', 'קְרִיּוֹת', '["Qᵉrîyôwth"]', '["Kerioth"]', '["n-pr-loc"]', 'Kerioth, the name of two places in Palestine Kerioth, Kirioth.', 'plural of 7151; buildings;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1224H}/[H1223]', 'lemma', 'heb', 'בׇּצְרָה', '["Botsrâh"]', '["Bozrah"]', '["n-pr-loc"]', 'Botsrah, a place in Edom Bozrah.', 'the same as 1223;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7937}/H9033/[H7937]', 'inflected', 'heb', 'שָׁכַר', '["shâkar"]', '["make drunk/ it"]', '["v"]', 'to become tipsy; in a qualified sense, to satiate with a stimulating drink or (figuratively) influence (be filled with) drink (abundantly), (be, make) drunk(-en), be merry. (Superlative of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7814}/[H7832]', 'inflected', 'heb', 'שְׂחוֹק', '["sᵉchôwq"]', '["the/ laughing stock"]', '["n-m"]', 'laughter (in merriment or defiance) derision, laughter(-ed to scorn, -ing), mocked, sport.', 'or שְׂחֹק; from 7832;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1590}/[H1589]', 'inflected', 'heb', 'גַּנָּב', '["gannâb"]', '["among/ thieves"]', '["n-m"]', 'a stealer thief.', 'from 1589;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6354>', 'opaque', 'heb', 'פַּחַת', '["pachath"]', '["a ravine"]', '["n-m"]', 'a pit, especially for catching animals hole, pit, snare.', 'probably from an unused root apparently meaning to dig;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1346}/H9023/[H1342]', 'inflected', 'heb', 'גַּאֲוָה', '["gaʼăvâh"]', '["and/ boastfulness/ its"]', '["n-f"]', 'arrogance or majesty; by implication, (concretely) ornament excellency, haughtiness, highness, pride, proudly, swelling.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7312}/[H7311]', 'inflected', 'heb', 'רוּם', '["rûwm"]', '["and/ [the] loftiness of"]', '["n-m"]', '(literally) elevation or (figuratively) elation haughtiness, height, × high.', 'or רֻם; from 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4124G}/[H1]', 'inflected', 'heb', 'מוֹאָב', '["Môwʼâb"]', '["and/ for/ Moab"]', '["n-pr-m n-pr-loc"]', 'Moab, an incestuous son of Lot; also his territory and descendants Moab.', 'from a prolonged form of the prepositional prefix m- and 1; from (her [the mother''s]) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5189}/H9022/[H5203]', 'inflected', 'heb', 'נְטִישָׁה', '["nᵉṭîyshâh"]', '["tendrils/ your"]', '["n-f"]', 'a tendril (as an offshoot) battlement, branch, plant.', 'from 5203;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3270H}/[H5826]', 'lemma', 'heb', 'יַעֲזֵיר', '["Yaʻăzêyr"]', '["Jazer"]', '["n-pr-loc"]', 'Jaazer or Jazer, a place East of the Jordan Jaazer, Jazer.', 'or יַעְזֵר; from 5826; helpful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1210}/H9022/[H1219]', 'inflected', 'heb', 'בָּצִיר', '["bâtsîyr"]', '["grape harvest/ your"]', '["n-m"]', 'clipped, i.e. the grape crop vintage.', 'from 1219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3759}/[H3754]', 'inflected', 'heb', 'כַּרְמֶל', '["karmel"]', '["from/ [the] garden-land"]', '["n-m"]', 'a planted field (garden, orchard, vineyard or park); by implication, garden produce full (green) ears (of corn), fruitful field (place), plentiful (field).', 'from 3754;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H3342>', 'inflected', 'heb', 'מיקבים', '["mi./ka.Vim"]', '["from/ wine-presses"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4923}/[H8074]', 'inflected', 'heb', 'מְשַׁמָּה', '["mᵉshammâh"]', '["<into>/ wastes"]', '["n-f"]', 'a waste or amazement astonishment, desolate.', 'from 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0430J}/H9023/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["to/ gods/ his"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2485}/[H2490]', 'inflected', 'heb', 'חָלִיל', '["châlîyl"]', '["like/ flutes"]', '["n-m"]', 'a flute (as perforated) pipe.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1417}/[H1413]', 'lemma', 'heb', 'גְּדוּד', '["gᵉdûwd"]', '["cuts"]', '["n"]', 'a furrow (as cut) furrow.', 'or גְּדֻדָה; (feminine) from 1413;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4288}/[H2846]', 'inflected', 'heb', 'מְחִתָּה', '["mᵉchittâh"]', '["and/ <into>/ an object of terror"]', '["n-f"]', 'properly, a dissolution; concretely, a ruin, or (abstractly) consternation destruction, dismaying, ruin, terror.', 'from 2846;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7152H}/[H7151]', 'inflected', 'heb', 'קְרִיּוֹת', '["Qᵉrîyôwth"]', '["<the>/ Kerioth"]', '["n-pr-loc"]', 'Kerioth, the name of two places in Palestine Kerioth, Kirioth.', 'plural of 7151; buildings;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4679}/[H6679]', 'inflected', 'heb', 'מְצַד', '["mᵉtsad"]', '["and/ the/ strongholds"]', '["n-f"]', 'a fastness (as a covert of ambush) castle, fort, (strong) hold, munition.', 'or מְצָד; or (feminine) מְצָדָה; from 6679;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H3581B>', 'inflected', 'heb', 'מכח', '["mi./Ko.ach"]', '["from/ strength"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6936}/[H6915]', 'inflected', 'heb', 'קׇדְקֹד', '["qodqôd"]', '["and/ [the] scalp of"]', '["n-m"]', 'the crown of the head (as the part most bowed) crown (of the head), pate, scalp, top of the head.', 'from 6915;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4124G}\/[H1]', 'inflected', 'heb', 'מוֹאָב', '["Môwʼâb"]', '["Moab"]', '["n-pr-m n-pr-loc"]', 'Moab, an incestuous son of Lot; also his territory and descendants Moab.', 'from a prolonged form of the prepositional prefix m- and 1; from (her [the mother''s]) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4428K}/[H4427]', 'lemma', 'heb', 'מֶלֶךְ', '["melek"]', '["Milcom"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8510}/[H8524]', 'inflected', 'heb', 'תֵּל', '["têl"]', '["<into>/ a mound of"]', '["n-m"]', 'a mound heap, × strength.', 'by contraction from 8524;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5857H}/[H5856]', 'lemma', 'heb', 'עַי', '["ʻAy"]', '["Ai"]', '["n-pr-loc"]', 'Ai, Aja or Ajath, a place in Palestine Ai, Aija, Aijath, Hai.', 'or (feminine) עַיָּא; (Nehemiah 11:31), or עַיָּת; (Isaiah 10:28), for 5856;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7751A}/[H7751]', 'inflected', 'heb', 'שׁוּט', '["shûwṭ"]', '["and/ run to and fro"]', '["v"]', 'properly, to push forth; (but used only figuratively) to lash, i.e. (the sea with oars) to row; by implication, to travel go (about, through, to and fro), mariner, rower, run to and fro.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1448}/[H1447]', 'inflected', 'heb', 'גְּדֵרָה', '["gᵉdêrâh"]', '["among the/ walls"]', '["n-f"]', 'inclosure (especially for flocks) (sheep-) cote (fold) hedge, wall.', 'feminine of 1447;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0214}/H9024/[H686]', 'inflected', 'heb', 'אוֹצָר', '["ʼôwtsâr"]', '["in/ treasures/ her"]', '["n-m"]', 'a depository armory, cellar, garner, store(-house), treasure(-house) (-y).', 'from 686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5439G}/H9032/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["[are] around/ you","around/ you"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5074}/[H5074]', 'inflected', 'heb', 'נָדַד', '["nâdad"]', '["[belongs] to the/ fugitive"]', '["v"]', 'properly, to wave to and fro (rarely to flap up and down); figuratively, to rove, flee, or (causatively) to drive away chase (away), × could not, depart, flee (× apace, away), (re-) move, thrust away, wander (abroad, -er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0123G}/[H122]', 'inflected', 'heb', 'אֱדֹם', '["ʼĔdôm"]', '["of/ Edom","to/ Edom"]', '["n-pr-m"]', 'Edom, the elder twin-brother of Jacob; hence the region (Idumaea) occupied by him Edom, Edomites, Idumea.', 'or (fully) אֱדוֹם ; from 122; red (see Genesis 25:25);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8487H}/[H8486]', 'inflected', 'heb', 'תֵּימָן', '["Têymân"]', '["in/ Teman","on/ Teman"]', '["n-pr-m n-pr-loc"]', 'Teman, the name of two Edomites, and of the region and descendant of one of them south, Teman.', 'or תֵּמָן; the same as 8486;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0995}/[H995]', 'inflected', 'heb', 'בִּין', '["bîyn"]', '["from/ understanding [people]"]', '["v"]', 'to separate mentally (or distinguish), i.e.(generally) understand attend, consider, be cunning, diligently, direct, discern, eloquent, feel, inform, instruct, have intelligence, know, look well to, mark, perceive, be prudent, regard, (can) skill(-full), teach, think, (cause, make to, get, give, have) understand(-ing), view, (deal) wise(-ly, man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6485H}/H9033/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["[when] I will visit/ it"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4565}/H9023/[H5641]', 'inflected', 'heb', 'מִסְתָּר', '["miçtâr"]', '["hiding places/ its"]', '["n-m"]', 'properly, a concealer, i.e. a covert secret(-ly, place).', 'from 5641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5800A}/H9012/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["leave/ !"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3490>/H9021', 'opaque', 'heb', 'יָתוֹם', '["yâthôwm"]', '["fatherless/ your"]', '["n-m"]', 'a bereaved person fatherless (child), orphan.', 'from an unused root meaning to be lonely;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0490}/H9021/[H488]', 'inflected', 'heb', 'אַלְמָנָה', '["ʼalmânâh"]', '["and/ widows/ your"]', '["n-f"]', 'a widow; also a desolate place desolate house (palace), widow.', 'feminine of 488;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0982}\/[H982]', 'inflected', 'heb', 'בָּטַח', '["bâṭach"]', '["let them rely"]', '["v"]', 'properly, to hie for refuge (but not so precipitately as 2620); figuratively, to trust, be confident or sure be bold (confident, secure, sure), careless (one, woman), put confidence, (make to) hope, (put, make to) trust.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2721B}/[H2719]', 'inflected', 'heb', 'חֹרֶב', '["chôreb"]', '["<into>/ a desolation"]', '["n-m"]', 'drought or desolation desolation, drought, dry, heat, × utterly, waste.', 'a collaterally form of 2719;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1224G}/[H1223]', 'lemma', 'heb', 'בׇּצְרָה', '["Botsrâh"]', '["Bozrah"]', '["n-pr-loc"]', 'Botsrah, a place in Edom Bozrah.', 'the same as 1223;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8606}/H9021/[H6426]', 'inflected', 'heb', 'תִּפְלֶצֶת', '["tiphletseth"]', '["horror/ your"]', '["n-f"]', 'fearfulness terrible.', 'from 6426;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3381}/H9031/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["I will bring down/ you","they will bring down/ you"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7934}/H9024/[H7931]', 'inflected', 'heb', 'שָׁכֵן', '["shâkên"]', '["and/ neighbors/ its"]', '["a"]', 'a resident; by extension, a fellow-citizen inhabitant, neighbour, nigh.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1347}/[H1342]', 'inflected', 'heb', 'גָּאוֹן', '["gâʼôwn"]', '["from/ [the] thicket[s] of"]', '["n-m"]', 'the same as 1346 arrogancy, excellency(-lent), majesty, pomp, pride, proud, swelling.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7323G}/H9033/[H7323]', 'inflected', 'heb', 'רוּץ', '["rûwts"]', '["I will cause to run/ it"]', '["v"]', 'to run (for whatever reason, especially to rush) break down, divide speedily, footman, guard, bring hastily, (make) run (away, through), post.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6440G}/H9020\/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<to>/ before/ me"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4284}/H9023/[H2803]', 'inflected', 'heb', 'מַחֲשָׁבָה', '["machăshâbâh"]', '["and/ purposes/ his"]', '["n-f"]', 'a contrivance, i.e. (concretely) a texture, machine, or (abstractly) intention, plan (whether bad, a plot; or good, advice) cunning (work), curious work, device(-sed), imagination, invented, means, purpose, thought.', 'or מַחֲשֶׁבֶת; from 2803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8487H}/[H8486]', 'lemma', 'heb', 'תֵּימָן', '["Têymân"]', '["O Teman","Teman"]', '["n-pr-m n-pr-loc"]', 'Teman, the name of two Edomites, and of the region and descendant of one of them south, Teman.', 'or תֵּמָן; the same as 8486;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5498}/H9038/[H5498]', 'inflected', 'heb', 'סָחַב', '["çâchab"]', '["people will drag away/ them"]', '["v"]', 'to trail along draw (out), tear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5116A}/H9028/[H5115]', 'inflected', 'heb', 'נָוֶה', '["nâveh"]', '["pastureland/ their"]', '["n"]', '(adjectively) at home; hence (by implication of satisfaction) lovely; also (noun) a home, of God (temple), men (residence), flocks (pasture), or wild animals (den) comely, dwelling (place), fold, habitation, pleasant place, sheepcote, stable, tarried.', 'or (feminine) נָוָה; from 5115;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5307J}/H9048/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["falling/ they"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1675}/[H1675]', 'inflected', 'heb', 'דָּאָה', '["dâʼâh"]', '["and/ he may swoop down"]', '["v"]', 'to dart, i.e. fly rapidly fly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6887C}\/[H6887]', 'inflected', 'heb', 'צָרַר', '["tsârar"]', '["in labor"]', '["v"]', 'to cramp, literally or figuratively, transitive or intransitive adversary, (be in) afflict(-ion), beseige, bind (up), (be in, bring) distress, enemy, narrower, oppress, pangs, shut up, be in a strait (trouble), vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7374>', 'inflected', 'heb', 'ורטט', '["ve./Re.tet"]', '["and/ panic"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0270}/H9034/[H270]', 'inflected', 'heb', 'אָחַז', '["ʼâchaz"]', '["it will seize/ it"]', '["v"]', 'to seize (often with the accessory idea of holding in possession) be affrighted, bar, (catch, lay, take) hold (back), come upon, fasten, handle, portion, (get, have or take) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4885}/H9020/[H7797]', 'inflected', 'heb', 'מָשׂוֹשׂ', '["mâsôws"]', '["joy/ my"]', '["n-m"]', 'delight, concretely (the cause or object) or abstractly (the feeling) joy, mirth, rejoice.', 'from 7797;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0970}/H9024/[H977]', 'inflected', 'heb', 'בָּחוּר', '["bâchûwr"]', '["young men/ its"]', '["n-m"]', 'properly, selected, i.e. a youth (often collective) (choice) young (man), chosen, × hole.', 'or בָּחֻר; participle passive of 977;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1130G}\/[H1121]', 'inflected', 'heb', 'בֶּן־הֲדַד', '["Ben-Hădad"]', '["Hadad"]', '["n-pr-m"]', 'Ben-Hadad, the name of several Syrian kings Benhadad.', 'from 1121 and 1908; son of Hadad;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6938}/[H6937]', 'inflected', 'heb', 'קֵדָר', '["Qêdâr"]', '["of/ Kedar"]', '["n-pr"]', 'Kedar, a son of Ishmael; also (collectively) Bedouin (as his descendants or representatives) Kedar.', 'from 6937; dusky (of the skin or the tent);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4467}/[H4427]', 'inflected', 'heb', 'מַמְלָכָה', '["mamlâkâh"]', '["and/ of/ [the] kingdoms of"]', '["n-f"]', 'dominion, i.e. (abstractly) the estate (rule) or (concretely) the country (realm) kingdom, king''s, reign, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2674K}/[H2691]', 'lemma', 'heb', 'חָצוֹר', '["Châtsôwr"]', '["Hazor"]', '["n-pr-loc"]', 'Chatsor, the name (thus simply) of two places in Palestine and of one in Arabia Hazor.', 'a collective form of 2691; village;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7703}/[H7703]', 'inflected', 'heb', 'שָׁדַד', '["shâdad"]', '["and/ devastate"]', '["v"]', 'properly, to be burly, i.e. (figuratively) powerful (passively, impregnable); by implication, to ravage dead, destroy(-er), oppress, robber, spoil(-er), × utterly, (lay) waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3407}/H9028/[H3415]', 'inflected', 'heb', 'יְרִיעָה', '["yᵉrîyʻâh"]', '["tent curtains/ their"]', '["n-f"]', 'a hanging (as tremulous) curtain.', 'from 3415;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2803I}/[H2803]', 'inflected', 'heb', 'חָשַׁב', '["châshab"]', '["and/ he has purposed","and/ you will plan"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1369}/H9028/[H1368]', 'inflected', 'heb', 'גְּבוּרָה', '["gᵉbûwrâh"]', '["strength/ their"]', '["n-f"]', 'force (literally or figuratively); by implication, valor, victory force, mastery, might, mighty (act, power), power, strength.', 'feminine passive participle from the same as 1368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5867A}/[H5956]', 'inflected', 'heb', 'עֵילָם', '["ʻÊylâm"]', '["[is] in/ Elam","in/ Elam"]', '["n-pr-m n-pr-loc"]', 'Elam, a son of Shem and his descendants, with their country; also of six Israelites Elam.', 'or עוֹלָם; (Ezra 10:2; Jeremiah 49:36), probably from 5956; hidden, i.e. distant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4781}/[H4781]', 'lemma', 'heb', 'מְרֹדָךְ', '["Mᵉrôdâk"]', '["Marduk"]', '["n-pr-m"]', 'Merodak, a Babylonian idol Merodach. Compare 4757.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6091}/H9024/[H6087]', 'inflected', 'heb', 'עָצָב', '["ʻâtsâb"]', '["idols/ its","images/ its"]', '["n-m"]', 'an (idolatrous) image idol, image.', 'from 6087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1544}/H9024/[H1556]', 'inflected', 'heb', 'גִּלּוּל', '["gillûwl"]', '["idols/ its"]', '["n-m"]', 'properly, a log (as round); by implication, an idol idol.', 'or (shortened) גִּלֻּל; from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7462B}/H9028/[H7462]', 'inflected', 'heb', 'רָעָה', '["râʻâh"]', '["shepherds/ their"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7726}/H9038/[H7725]', 'inflected', 'heb', 'שׁוֹבָב', '["shôwbâb"]', '["they have led away/ them"]', '["a"]', 'apostate, i.e. idolatrous backsliding, frowardly, turn away (from margin).', 'from 7725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7258}/H9028/[H7257]', 'inflected', 'heb', 'רֵבֶץ', '["rêbets"]', '["resting place/ their"]', '["n-m"]', 'a couch or place of repose where each lay, lie down in, resting place.', 'from 7257;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6862C}/H9028/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["and/ opponents/ their"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4723B}/[H6960]', 'inflected', 'heb', 'מִקְוֶה', '["miqveh"]', '["and/ [the] hope of"]', '["n-pr-m n-m"]', 'something waited for, i.e. confidence (objective or subjective); also a collection, i.e. (of water) a pond, or (of men and horses) a caravan or drove abiding, gathering together, hope, linen yarn, plenty (of water), pool.', 'or מִקְוֵה; (1 Kings 10:28), or מִקְוֵאlemma מִּקְוֵא extra dagesh, corrected to מִקְוֵא; (2 Chronicles 1:16), from 6960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6260}/[H6257]', 'inflected', 'heb', 'עַתּוּד', '["ʻattûwd"]', '["like/ male goats"]', '["n-m"]', 'prepared, i.e. full grown; spoken only (in plural) of he-goats, or (figuratively) leaders of the people chief one, (he) goat, ram.', 'or עַתֻּד; from 6257;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7997B}/H9034/[H7997]', 'inflected', 'heb', 'שָׁלַל', '["shâlal"]', '["[those who] plunder/ it"]', '["v"]', 'to drop or strip; by implication, to plunder let fall, make self a prey, × of purpose, (make a, (take)) spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6335A}/[H6335]', 'lemma', 'heb', 'פּוּשׁ', '["pûwsh"]', '["you are skipping about"]', '["v"]', 'to spread; figuratively, act proudly grow up, be grown fat, spread selves, be scattered.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5697A}/[H5695]', 'inflected', 'heb', 'עֶגְלָה', '["ʻeglâh"]', '["like/ a heifer"]', '["n-f"]', 'a (female) calf, especially one nearly grown (i.e. a heifer) calf, cow, heifer.', 'feminine of 5695;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0047H}/[H46]', 'inflected', 'heb', 'אַבִּיר', '["ʼabbîyr"]', '["like <the>/ mighty [horses]"]', '["a-m"]', 'angel, bull, chiefest, mighty (one), stout(-hearted), strong (one), valiant.', 'for 46');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3205}/H9036/[H3205]', 'inflected', 'heb', 'יָלַד', '["yâlad"]', '["[the one who] gave birth/ you"]', '["v"]', 'to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6160L}/[H6150]', 'inflected', 'heb', 'עֲרָבָה', '["ʻărâbâh"]', '["and/ a desert plain"]', '["n-f"]', 'a desert; especially (with the article prefix) the (generally) sterile valley of the Jordan and its continuation to the Red Sea Arabah, champaign, desert, evening, heaven, plain, wilderness. See also 1026.', 'from 6150 (in the sense of sterility);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7110A}/[H7107]', 'inflected', 'heb', 'קֶצֶף', '["qetseph"]', '["from/ [the] wrath of"]', '["n-m"]', 'a splinter (as chipped off); figuratively, rage or strife foam, indignation, × sore, wrath.', 'from 7107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027H}/H9024/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ its"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0803>/H9024', 'opaque', 'heb', 'אֲשׁוּיָה', '["ʼăshûwyâh"]', '["towers/ its"]', '["n-f"]', 'foundation foundation.', 'feminine passive participle from an unused root meaning to found;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4038>', 'opaque', 'heb', 'מַגָּל', '["maggâl"]', '["a sickle"]', '["n-m"]', 'a sickle sickle.', 'from an unused root meaning to reap;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5127}\/[H5127]', 'inflected', 'heb', 'נוּס', '["nûwç"]', '["they will flee"]', '["v"]', 'to flit, i.e. vanish away (subside, escape; causatively, chase, impel, deliver) × abate, away, be displayed, (make to) flee (away, -ing), put to flight, × hide, lift up a standard.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6105A}/H9033/[H6106]', 'inflected', 'heb', 'עָצַם', '["ʻâtsam"]', '["he gnawed bones/ its"]', '["v"]', 'to bind fast, i.e. close (the eyes); intransitively, to be (causatively, make) powerful or numerous; to crunch the bones break the bones, close, be great, be increased, be (wax) mighty(-ier), be more, shut, be(-come, make) strong(-er).', 'a primitive root; also denominatively (from 6106)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4850}/[H4751]', 'lemma', 'heb', 'מְרָתַיִם', '["Mᵉrâthayim"]', '["Merathaim"]', '["n-pr-f"]', 'Merathajim, an epithet of Babylon Merathaim.', 'dual of 4751 feminine; double bitterness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6489}/[H6485]', 'lemma', 'heb', 'פְּקוֹד', '["Pᵉqôwd"]', '["Pekod"]', '["n-pr"]', 'Pekod, a symbolic name for Babylon Pekod.', 'from 6485; punishment;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2763A}/[H2763]', 'inflected', 'heb', 'חָרַם', '["châram"]', '["and/ totally destroy"]', '["v"]', 'to seclude; specifically (by a ban) to devote to religious uses (especially destruction); physical and reflexive, to be blunt as to the nose make accursed, consecrate, (utterly) destroy, devote, forfeit, have a flat nose, utterly (slay, make away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6680}/H9031\/[H6680]', 'inflected', 'heb', 'צָוָה', '["tsâvâh"]', '["I have commanded/ you"]', '["v"]', '(intensively) to constitute, enjoin appoint, (for-) bid, (give a) charge, (give a, give in, send with) command(-er, -ment), send a messenger, put, (set) in order.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3965}/H9024/[H75]', 'inflected', 'heb', 'מַאֲבוּס', '["maʼăbûwç"]', '["granaries/ its"]', '["n-m"]', 'a granary storehouse.', 'from 75;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2763A}/H9034/[H2763]', 'inflected', 'heb', 'חָרַם', '["châram"]', '["and/ totally destroy/ it"]', '["v"]', 'to seclude; specifically (by a ban) to devote to religious uses (especially destruction); physical and reflexive, to be blunt as to the nose make accursed, consecrate, (utterly) destroy, devote, forfeit, have a flat nose, utterly (slay, make away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6499}/H9024/[H6565]', 'inflected', 'heb', 'פַּר', '["par"]', '["young bulls/ its"]', '["n-m"]', 'a bullock (apparently as breaking forth in wild strength, or perhaps as dividing the hoof) ( young) bull(-ock), calf, ox.', 'or פָּר; from 6565;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6412B}/[H6403]', 'inflected', 'heb', 'פָּלִיט', '["pâlîyṭ"]', '["and/ escapees"]', '["n-m"]', 'a refugee (that have) escape(-d, -th), fugitive.', 'or פָּלֵיט; or פָּלֵט; from 6403;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1964G}/H9023/[H3201]', 'inflected', 'heb', 'הֵיכָל', '["hêykâl"]', '["temple/ his"]', '["n-m"]', 'a large public building, such as a palace or temple palace, temple.', 'probably from 3201 (in the sense of capacity);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1961}/H9014/H9005/H9034/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["it be/-/to <the>/ it"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6467}/H9024/[H6466]', 'inflected', 'heb', 'פֹּעַל', '["pôʻal"]', '["according to/ deed[s]/ its"]', '["n-m"]', 'an act or work (concretely) act, deed, do, getting, maker, work.', 'from 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4421}/H9024/[H3898]', 'inflected', 'heb', 'מִלְחָמָה', '["milchâmâh"]', '["war/ its"]', '["n-f"]', 'a battle (i.e. the engagement); generally, war (i.e. war-fare) battle, fight(-ing), war(-rior).', 'from 3898 (in the sense of fighting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6485H}/H9031/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["[when] I will visit/ you"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0907}/[H908]', 'inflected', 'heb', 'בַּד', '["bad"]', '["the/ empty talkers"]', '["n-m"]', 'a brag or lie; also a liar liar, lie.', 'from 908;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2973}/[H2973]', 'inflected', 'heb', 'יָאַל', '["yâʼal"]', '["and/ they will become fools"]', '["v"]', 'properly, to be slack, i.e. (figuratively) to be foolish dote, be (become, do) foolish(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1368}/H9024/[H1397]', 'inflected', 'heb', 'גִּבּוֹר', '["gibbôwr"]', '["warriors/ its"]', '["a"]', 'powerful; by implication, warrior, tyrant champion, chief, × excel, giant, man, mighty (man, one), strong (man), valiant man.', 'or גִּבֹּר; (shortened) intensive from the same as 1397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0214}/H9024/[H686]', 'inflected', 'heb', 'אוֹצָר', '["ʼôwtsâr"]', '["treasuries/ its"]', '["n-m"]', 'a depository armory, cellar, garner, store(-house), treasure(-house) (-y).', 'from 686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0367}/[H366]', 'inflected', 'heb', 'אֵימָה', '["ʼêymâh"]', '["and/ in <the>/ terrors"]', '["n-f"]', 'fright; concrete, an idol (as a bugbear) dread, fear, horror, idol, terrible, terror.', 'or (shortened) אֵמָה; from the same as 366;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7934}/H9024/[H7931]', 'inflected', 'heb', 'שָׁכֵן', '["shâkên"]', '["neighbors/ its"]', '["a"]', 'a resident; by extension, a fellow-citizen inhabitant, neighbour, nigh.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2388H}/H9033/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["it took hold of/ him"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7323G}/H9038/[H7323]', 'inflected', 'heb', 'רוּץ', '["rûwts"]', '["I will cause to run/ them"]', '["v"]', 'to run (for whatever reason, especially to rush) break down, divide speedily, footman, guard, bring hastily, (make) run (away, through), post.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2201}/[H2199]', 'inflected', 'heb', 'זַעַק', '["zaʻaq"]', '["and/ a cry of distress"]', '["n-f"]', 'a shriek or outcry cry(-ing).', 'and (feminine) זְעָקָהxlit zᵉâqâh corrected to zᵉʻâqâh; from 2199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3820B}/[H3824]', 'lemma', 'heb', 'לֵב', '["lêb"]', '["Leb-"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965A}/[H6965]', 'lemma', 'heb', 'קוּם', '["qûwm"]', '["-qamai"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2219}/H9034/[H2114]', 'inflected', 'heb', 'זָרָה', '["zârâh"]', '["and/ they will winnow/ it"]', '["v"]', 'to toss about; by implication, to diffuse, winnow cast away, compass, disperse, fan, scatter (away), spread, strew, winnow.', 'a primitive root (compare 2114);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1238B}/[H1238]', 'inflected', 'heb', 'בָּקַק', '["bâqaq"]', '["and/ they may lay waste"]', '["v"]', 'to pour out, i.e. to empty, figuratively, to depopulate; by analogy, to spread out (as a fruitful vine) (make) empty (out), fail, × utterly, make void.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5630}/H9023/[H8302]', 'inflected', 'heb', 'סִרְיֹן', '["çiryôn"]', '["in/ armor/ his"]', '["n-m"]', 'a coat of mail brigandine.', 'for 8302;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6635A}/H9024/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["army/ its"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1856}/[H1856]', 'inflected', 'heb', 'דָּקַר', '["dâqar"]', '["and/ pierced through"]', '["v"]', 'to stab; by analogy, to starve; figuratively, to revile pierce, strike (thrust) through, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2351>/H9024', 'inflected', 'heb', 'בחוצותיה', '["be./Chu.tzo.Tei./ha","be./chu.tzo.Tei./ha"]', '["in/ streets/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0488}/[H481]', 'lemma', 'heb', 'אַלְמָן', '["ʼalmân"]', '["[is] forsaken"]', '["a"]', 'discarded (as a divorced person) forsaken.', 'prolonged from 481 in the sense of bereavement;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0430G}/H9023/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["from/ God/ its"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5771I}/H9024/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["in/ iniquity/ its"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H3196>/H9024', 'inflected', 'heb', 'מיינה', '["mi./yei.Na/h"]', '["some of/ wine/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4341}/H9024/[H3510]', 'inflected', 'heb', 'מַכְאֹב', '["makʼôb"]', '["for/ pain/ its"]', '["n-m"]', 'anguish or (figuratively) affliction grief, pain, sorrow.', 'sometimes מַכְאוֹב; also (feminine Isaiah 53:3) מַכְאֹבָה; from 3510;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4941G}/H9024/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["judgment/ its"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7093}/H9022/[H7112]', 'inflected', 'heb', 'קֵץ', '["qêts"]', '["end/ your"]', '["n-m"]', 'an extremity; adverbially (with prepositional prefix) after after, (utmost) border, end, (in-) finite, × process.', 'contracted from 7112;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1215}/H9022/[H1214]', 'inflected', 'heb', 'בֶּצַע', '["betsaʻ"]', '["cutting off/ your","unjust gain/ your"]', '["n-m"]', 'plunder; by extension, gain (usually unjust) covetousness, (dishonest) gain, lucre, profit.', 'from 1214;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5315I}/H9023/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["by/ self/ his"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H3218>', 'inflected', 'heb', 'כילק', '["ka/i.Ye.lek","ke./Ye.lek"]', '["like <the>/ locust","like/ a locust"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1959>\', 'opaque', 'heb', 'הֵידָד', '["hêydâd"]', '["a shout"]', '["n-m"]', 'acclamation shout(-ing).', 'from an unused root (meaning to shout);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7626H>', 'inflected', 'heb', 'ושבטי', '["ve./She.vet","ve./shiv.Tei"]', '["and/ [the] tribe of","and/ [the] tribes of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4661}/[H5310]', 'lemma', 'heb', 'מַפֵּץ', '["mappêts"]', '["[are] a war-club"]', '["n-m"]', 'a smiter, i.e. a war club battle ax.', 'from 5310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5739}/H9023/[H5737]', 'inflected', 'heb', 'עֵדֶר', '["ʻêder"]', '["and/ flock/ his"]', '["n-m"]', 'an arrangement, i.e. muster (of animals) drove, flock, herd.', 'from 5737;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6776}/H9023/[H6776]', 'inflected', 'heb', 'צֶמֶד', '["tsemed"]', '["and/ team/ his"]', '["n-m"]', 'a yoke or team (i.e. pair); hence, an acre (i.e. day''s task for a yoke of cattle to plough) acre, couple, × together, two (donkeys), yoke (of oxen).', NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5461>', 'inflected', 'heb', 'וסגנים', '["u./se.ga.Nim"]', '["and/ officials"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1556}/H9031/[H1556]', 'inflected', 'heb', 'גָּלַל', '["gâlal"]', '["and/ I will roll/ you"]', '["v"]', 'to roll (literally or figuratively) commit, remove, roll (away, down, together), run down, seek occasion, trust, wallow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6438H}/[H6434]', 'inflected', 'heb', 'פִּנָּה', '["pinnâh"]', '["for/ a corner"]', '["n-f"]', 'an angle; by implication, a pinnacle; figuratively, a chieftain bulwark, chief, corner, stay, tower.', 'feminine of 6434;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4146}/[H4144]', 'inflected', 'heb', 'מוֹסָדָה', '["môwçâdâh"]', '["for/ foundations"]', '["n-f"]', 'a foundation foundation.', 'or מֹסָדָה; feminine of 4144;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4508}/[H4508]', 'lemma', 'heb', 'מִנִּי', '["Minnîy"]', '["Minni"]', '["n-pr-loc"]', 'Minni, an Armenian province Minni.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0813H>', 'inflected', 'heb', 'ואשכנז', '["ve./''ash.ke.Naz"]', '["and/ Ashkenaz"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2951}/[H2951]', 'lemma', 'heb', 'טִפְסַר', '["ṭiphçar"]', '["an official"]', '["n-m"]', 'a military governor captain.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5927J}/[H5927]', 'lemma', 'heb', 'עָלָה', '["ʻâlâh"]', '["bring up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5569}/[H5568]', 'lemma', 'heb', 'סָמָר', '["çâmâr"]', '["bristly"]', '["a"]', 'bristling, i.e. shaggy rough.', 'from 5568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6346>/H9024', 'opaque', 'heb', 'פֶּחָה', '["pechâh"]', '["governors/ its"]', '["n-m"]', 'a prefect (of a city or small district) captain, deputy, governor.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5461>/H9024', 'opaque', 'heb', 'סָגָן', '["çâgân"]', '["officials/ its"]', '["n-m"]', 'a præfect of a province prince, ruler.', 'from an unused root meaning to superintend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4908}/H9024/[H7931]', 'inflected', 'heb', 'מִשְׁכָּן', '["mishkân"]', '["dwellings/ its"]', '["n-m"]', 'a residence (including a shepherd''s hut, the lair of animals, figuratively, the grave; also the Temple); specifically, the Tabernacle (properly, its wooden walls) dwelleth, dwelling (place), habitation, tabernacle, tent.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1280}/H9024/[H1272]', 'inflected', 'heb', 'בְּרִיחַ', '["bᵉrîyach"]', '["bars/ its"]', '["n-m"]', 'a bolt bar, fugitive.', 'from 1272;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4569B}/[H5674]', 'inflected', 'heb', 'מַעֲבָר', '["maʻăbâr"]', '["and/ the/ fords"]', '["n-m"]', 'a crossing-place (of a river, a ford; of a mountain, a pass); abstractly, a transit, i.e. (figuratively) overwhelming ford, place where...pass, passage.', 'or feminine מַעֲבָרָה; from 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0926}\/[H926]', 'inflected', 'heb', 'בָּהַל', '["bâhal"]', '["they are terrified"]', '["v"]', 'to tremble inwardly (or palpitate), i.e. (figuratively) be (causative, make) (suddenly) alarmed or agitated; by implication to hasten anxiously be (make) affrighted (afraid, amazed, dismayed, rash), (be, get, make) haste(-n, -y, -ily), (give) speedy(-ily), thrust out, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H1637>', 'inflected', 'heb', 'כגרן', '["ke./Go.ren"]', '["[will be] like/ a threshing floor"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1869}/H9034/[H1869]', 'inflected', 'heb', 'דָּרַךְ', '["dârak"]', '["[when] someone treads down/ it"]', '["v"]', 'to tread; by implication, to walk; also to string a bow (by treading on it in bending) archer, bend, come, draw, go (over), guide, lead (forth), thresh, tread (down), walk.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2000}/H9030/[H1949]', 'inflected', 'heb', 'הָמַם', '["hâmam"]', '["he confused/ me"]', '["v"]', 'properly, to put in commotion; by implication, to disturb, drive, destroy break, consume, crush, destroy, discomfit, trouble, vex.', 'a primitive root (compare 1949, 1993);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3322}/H9030/[H3322]', 'inflected', 'heb', 'יָצַג', '["yâtsag"]', '["he set down/ me"]', '["v"]', 'to place permanently establish, leave, make, present, put, set, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8577N}/[H8565]', 'inflected', 'heb', 'תַּנִּין', '["tannîyn"]', '["like <the>/ sea monster"]', '["n-m"]', 'a marine or land monster, i.e. sea-serpent or jackal dragon, sea-monster, serpent, whale.', 'or תַּנִּים; (Ezekiel 29:3), intensive from the same as 8565;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3770}/H9023/[H7164]', 'inflected', 'heb', 'כְּרֵשׂ', '["kᵉrês"]', '["belly/ his"]', '["n-m"]', 'the paunch or belly (as swelling out) belly.', 'by variation from 7164;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5730A}/H9020/[H5727]', 'inflected', 'heb', 'עֵדֶן', '["ʻêden"]', '["from/ delicacies/ my"]', '["n-m"]', 'pleasure delicate, delight, pleasure. See also 1040.', 'or (feminine) עֶדְנָה; from 5727;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1740}/H9030/[H1740]', 'inflected', 'heb', 'דּוּחַ', '["dûwach"]', '["he rinsed out/ me"]', '["v"]', 'to thrust away; figuratively, to cleanse cast out, purge, wash.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7607}/H9020/[H7604]', 'inflected', 'heb', 'שְׁאֵר', '["shᵉʼêr"]', '["and/ flesh/ my"]', '["n-m"]', 'flesh (as swelling out), as living or for food; generally food of any kind; figuratively, kindred by blood body, flesh, food, (near) kin(-sman, -swoman), near (nigh) (of kin).', 'from 7604;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1818}/H9020/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["and/ blood/ my"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7379}/H9022/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["case/ your"]', '["n-m"]', 'a contest (personal or legal) adversary, cause, chiding, contend(-tion), controversy, multitude (from the margin), pleading, strife, strive(-ing), suit.', 'or רִב; from 7378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5360}/H9022/[H5359]', 'inflected', 'heb', 'נְקָמָה', '["nᵉqâmâh"]', '["vengeance/ your"]', '["n-f"]', 'avengement, whether the act or the passion avenge, revenge(-ing), vengeance.', 'feminine of 5359;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3220G>/H9024', 'opaque', 'heb', 'יָם', '["yâm"]', '["sea/ its"]', '["n-m"]', 'a sea (as breaking in noisy surf) or large body of water; specifically (with the article), the Mediterranean Sea; sometimes a large river, or an artifical basin; locally, the west, or (rarely) the south sea (× -faring man, (-shore)), south, west (-ern, side, -ward).', 'from an unused root meaning to roar;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8322}/[H8319]', 'inflected', 'heb', 'שְׁרֵקָה', '["shᵉrêqâh"]', '["and/ a hissing"]', '["n-f"]', 'a derision hissing.', 'from 8319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5286}/[H5286]', 'lemma', 'heb', 'נָעַר', '["nâʻar"]', '["they growl"]', '["v"]', 'to growl yell.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1484}/[H1482]', 'inflected', 'heb', 'גּוֹר', '["gôwr"]', '["like/ cubs of"]', '["n-m"]', 'whelp.', 'or (feminine) גֹּרָה; a variation of 1482');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2552}/H9048/[H2552]', 'inflected', 'heb', 'חָמַם', '["châmam"]', '["when/ getting heated/ they"]', '["v"]', 'to be hot (literally or figuratively) enflame self, get (have) heat, be (wax) hot, (be, wax) warm (self, at).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7937}/H9038/[H7937]', 'inflected', 'heb', 'שָׁכַר', '["shâkar"]', '["and/ I will make drunk/ them"]', '["v"]', 'to become tipsy; in a qualified sense, to satiate with a stimulating drink or (figuratively) influence (be filled with) drink (abundantly), (be, make) drunk(-en), be merry. (Superlative of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3733C}/[H3769]', 'inflected', 'heb', 'כַּר', '["kar"]', '["like/ lambs"]', '["n-m"]', 'a ram (as full-grown and fat), including a battering-ram (as butting); hence, a meadow (as for sheep); also a pad or camel''s saddle (as puffed out) captain, furniture, lamb, (large) pasture, ram. See also 1033, 3746.', 'from 3769 in the sense of plumpness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1105}/H9023/[H1104]', 'inflected', 'heb', 'בֶּלַע', '["belaʻ"]', '["swallowed thing/ his"]', '["n-m"]', 'a gulp; figuratively, destruction devouring, that which he hath swallowed up.', 'from 1104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5102A}/[H5102]', 'lemma', 'heb', 'נָהַר', '["nâhar"]', '["they will stream"]', '["v"]', 'to sparkle, i.e. (figuratively) be cheerful; hence (from the sheen of a running stream) to flow, i.e. (figuratively) assemble flow (together), be lightened.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8052}/[H8074]', 'inflected', 'heb', 'שְׁמוּעָה', '["shᵉmûwʻâh"]', '["at the/ report"]', '["n-f"]', 'something heard, i.e. an announcement bruit, doctrine, fame, mentioned, news, report, rumor, tidings.', 'feminine passive participle of 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2555}/[H2554]', 'inflected', 'heb', 'חָמָס', '["châmâç"]', '["and/ [the] violence of","and/ violence"]', '["n-m"]', 'violence; by implication, wrong; by metonymy unjust gain cruel(-ty), damage, false, injustice, × oppressor, unrighteous, violence (against, done), violent (dealing), wrong.', 'from 2554;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2491A}/H9024/[H2490]', 'inflected', 'heb', 'חָלָל', '["châlâl"]', '["slain [ones]/ its"]', '["n-m"]', 'pierced (especially to death); figuratively, polluted kill, profane, slain (man), × slew, (deadly) wounded.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440H}/H9025/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["faces/ our"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6456}/H9024/[H6458]', 'inflected', 'heb', 'פְּסִיל', '["pᵉçîyl"]', '["images/ its"]', '["n-m"]', 'an idol carved (graven) image, quarry.', 'from 6458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0602}/[H602]', 'lemma', 'heb', 'אָנַק', '["ʼânaq"]', '["groaning","he will groan"]', '["v"]', 'to shriek cry, groan.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5797}/H9024/[H5810]', 'inflected', 'heb', 'עֹז', '["ʻôz"]', '["strength/ its"]', '["n-m"]', 'strength in various applications (force, security, majesty, praise) boldness, loud, might, power, strength, strong.', 'or (fully) עוֹז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2450}/H9024/[H2449]', 'inflected', 'heb', 'חָכָם', '["châkâm"]', '["and/ wise [people]/ its"]', '["a"]', 'wise, (i.e. intelligent, skilful or artful) cunning (man), subtil, (un-), wise((hearted), man).', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5461>/H9024', 'inflected', 'heb', 'וסגניה', '["u./se.ga.Nei./ha"]', '["and/ officials/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1368}/H9024/[H1397]', 'inflected', 'heb', 'גִּבּוֹר', '["gibbôwr"]', '["and/ warriors/ its"]', '["a"]', 'powerful; by implication, warrior, tyrant champion, chief, × excel, giant, man, mighty (man, one), strong (man), valiant man.', 'or גִּבֹּר; (shortened) intensive from the same as 1397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3286}\/[H3286]', 'inflected', 'heb', 'יָעַף', '["yâʻaph"]', '["and/ they grow weary"]', '["v"]', 'to tire (as if from wearisome flight) faint, cause to fly, (be) weary (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8304N}/[H8280]', 'lemma', 'heb', 'שְׂרָיָה', '["Sᵉrâyâh"]', '["Seraiah"]', '["n-pr-m"]', 'Serajah, the name of nine Israelites Seraiah.', 'or שְׂרָיָהוּ; from 8280 and 3050; Jah has prevailed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8304N}/[H8280]', 'inflected', 'heb', 'שְׂרָיָה', '["Sᵉrâyâh"]', '["and/ Seraiah"]', '["n-pr-m"]', 'Serajah, the name of nine Israelites Seraiah.', 'or שְׂרָיָהוּ; from 8280 and 3050; Jah has prevailed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3772I}/H9033/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["to/ cut off/ it"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/H9006/{H0120G}/[H119]', 'inflected', 'heb', 'אָדָם', '["ʼâdâm"]', '["<to>/ from/ humankind"]', '["n-m"]', 'ruddy i.e. a human being (an individual or the species, mankind, etc.) × another, hypocrite, common sort, × low, man (mean, of low degree), person.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3414L}\/[H7311]', 'inflected', 'heb', 'יִרְמְיָה', '["Yirmᵉyâh"]', '["Jeremiah"]', '["n-pr-m"]', 'Jirmejah, the name of eight or nine Israelites Jeremiah.', 'or יִרְמְיָהוּ; from 7311 and 3050; Jah will rise;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7247H>/H9011', 'inflected', 'heb', 'ברבלתה', '["be./riv.La.ta/h"]', '["at/ Riblah/ <towards>"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6486}/[H6485]', 'inflected', 'heb', 'פְּקֻדָּה', '["pᵉquddâh"]', '["<the>/ punishment","<the>/ punishment<s>"]', '["n-f"]', 'visitation (in many senses, chiefly official) account, (that have the) charge, custody, that which...laid up, numbers, office(-r), ordering, oversight, prison, reckoning, visitation.', 'feminine passive participle of 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0525}/[H539]', 'inflected', 'heb', 'אָמוֹן', '["ʼâmôwn"]', '["the/ craftsman"]', '["n-m"]', 'skilled, i.e. an architect one brought up.', 'from 539, probably in the sense of training; like 542');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5592A}/[H5605]', 'inflected', 'heb', 'סַף', '["çaph"]', '["the/ basins"]', '["n-m"]', 'a vestibule (as a limit); also a dish (for holding blood or wine) bason, bowl, cup, door (post), gate, post, threshold.', 'from 5605, in its original sense of containing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5178A}/H9028/[H5154]', 'inflected', 'heb', 'נְחֹשֶׁת', '["nᵉchôsheth"]', '["to/ bronze/ their"]', '["n-m"]', 'copper, hence, something made of that metal, i.e. coin, a fetter; figuratively, base (as compared with gold or silver) brasen, brass, chain, copper, fetter (of brass), filthiness, steel.', 'for 5154;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5982G}/[H5975]', 'inflected', 'heb', 'עַמּוּד', '["ʻammûwd"]', '["and/ the/ pillars"]', '["n-m"]', 'a column (as standing); also a stand, i.e. platform × apiece, pillar.', 'or עַמֻּד; from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7307I}/H9011/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["[the] side/ towards"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0490}/[H488]', 'inflected', 'heb', 'אַלְמָנָה', '["ʼalmânâh"]', '["[are] like/ widows","like/ a widow"]', '["n-f"]', 'a widow; also a desolate place desolate house (palace), widow.', 'feminine of 488;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1832}/H9024/[H1831]', 'inflected', 'heb', 'דִּמְעָה', '["dimʻâh"]', '["and/ tear[s]/ her"]', '["n-f"]', 'weeping tears.', 'feminine of 1831;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3895H>/H9024', 'opaque', 'heb', 'לְחִי', '["lᵉchîy"]', '["cheek/ her"]', '["n-m"]', 'the cheek (from its fleshiness); hence, the jaw-bone cheek (bone), jaw (bone).', 'from an unused root meaning to be soft;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7453}/H9024/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["friends/ her"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0341}\/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["<into>/ enemies"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7291}/H9034/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["pursuers/ her"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5381}/H9034/[H5381]', 'inflected', 'heb', 'נָשַׂג', '["nâsag"]', '["they have overtaken/ her"]', '["v"]', 'to reach (literally or figuratively) ability, be able, attain (unto), (be able to, can) get, lay at, put, reach, remove, wax rich, × surely, (over-) take (hold of, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4712}\/[H6869]', 'inflected', 'heb', 'מֵצַר', '["mêtsar"]', '["the/ narrow places"]', '["n-m"]', 'something tight, i.e. (figuratively) trouble distress, pain, strait.', 'from 6869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8179G}/H9024/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["gates/ her","gates/ its"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3548}/H9024/[H3547]', 'inflected', 'heb', 'כֹּהֵן', '["kôhên"]', '["priests/ her","priests/ its"]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1330>/H9024', 'opaque', 'heb', 'בְּתוּלָה', '["bᵉthûwlâh"]', '["virgins/ her"]', '["n-f"]', 'a virgin (from her privacy); sometimes (by continuation) a bride; also (figuratively) a city or state maid, virgin.', 'feminine passive participle of an unused root meaning to separate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3013}/[H3013]', 'lemma', 'heb', 'יָגָה', '["yâgâh"]', '["[are] grieving","[those] grieved","he has caused grief"]', '["v"]', 'to grieve afflict, cause grief, grieve, sorrowful, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6862C}/H9024/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["opponents/ her"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3013}/H9034/[H3013]', 'inflected', 'heb', 'יָגָה', '["yâgâh"]', '["he has caused grief/ to her"]', '["v"]', 'to grieve afflict, cause grief, grieve, sorrowful, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5768}/H9024/[H5763]', 'inflected', 'heb', 'עוֹלֵל', '["ʻôwlêl"]', '["children/ her"]', '["n-m"]', 'a suckling babe, (young) child, infant, little one.', 'or עֹלָל; from 5763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6862C}\/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["an opponent"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7291}\/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["a pursuer"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6040}/H9024/[H6031]', 'inflected', 'heb', 'עֳנִי', '["ʻŏnîy"]', '["affliction/ her"]', '["n-m"]', 'depression, i.e. misery afflicted(-ion), trouble.', 'from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4788}/H9024/[H7300]', 'inflected', 'heb', 'מָרוּד', '["mârûwd"]', '["and/ homelessness<es>/ her"]', '["n-m"]', 'an outcast; (abstractly) destitution cast out, misery.', 'from 7300 in the sense of maltreatment;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4262}/H9024/[H2530]', 'inflected', 'heb', 'מַחְמֻד', '["machmud"]', '["precious things/ her"]', '["n-m"]', 'desired; hence, a valuable pleasant thing.', 'or מַחְמוּד; from 2530;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4868}/H9024\/[H7673]', 'inflected', 'heb', 'מִשְׁבָּת', '["mishbâth"]', '["annihilation<s>/ her"]', '["n-m"]', 'cessation, i.e. destruction sabbath.', 'from 7673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5206}/[H5205]', 'inflected', 'heb', 'נִידָה', '["nîydâh"]', '["<into>/ impurity"]', '["n-f"]', 'removal, i.e. exile removed.', 'feminine of 5205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3513G}/H9034/[H3513]', 'inflected', 'heb', 'כָּבַד', '["kâbad"]', '["[those who] honored/ her"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2107}/H9034/[H2151]', 'inflected', 'heb', 'זוּל', '["zûwl"]', '["they despise/ her"]', '["v"]', 'probably to shake out, i.e. (by implication) to scatter profusely; figuratively, to treat lightly lavish, despise.', 'a primitive root (compare 2151);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0268}\/[H299]', 'inflected', 'heb', 'אָחוֹר', '["ʼâchôwr"]', '["backward"]', '["n-m"]', 'the hinder part; hence (adverb) behind, backward; also (as facing north) the West after(-ward), back (part, -side, -ward), hereafter, (be-) hind(-er part), time to come, without.', 'or (shortened) אָחֹר ; from 299;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7757>/H9024', 'inflected', 'heb', 'בשוליה', '["be./shu.Lei./ha"]', '["[was] on/ skirts/ her"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0319}/H9024/[H310]', 'inflected', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["outcome/ her"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0341}\/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["[the] enemy"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4720}/H9024/[H6942]', 'inflected', 'heb', 'מִקְדָּשׁ', '["miqdâsh"]', '["sanctuary/ its"]', '["n-m"]', 'a consecrated thing or place, especially, a palace, sanctuary (whether of Jehovah or of idols) or asylum chapel, hallowed part, holy place, sanctuary.', 'or מִקְּדָשׁ; (Exodus 15:17), from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4261}/H9028/[H2530]', 'inflected', 'heb', 'מַחְמָד', '["machmâd"]', '["precious things/ their"]', '["n-m"]', 'delightful; hence, a delight, i.e. object of affection or desire beloved, desire, goodly, lovely, pleasant (thing).', 'from 2530;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0400}/[H398]', 'inflected', 'heb', 'אֹכֶל', '["ʼôkel"]', '["for/ food"]', '["n-m"]', 'food eating, food, meal(-time), meat, prey, victuals.', 'from 398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5027}/H9012/[H5027]', 'inflected', 'heb', 'נָבַט', '["nâbaṭ"]', '["and/ look/ !"]', '["v"]', 'to scan, i.e. look intently at; by implication, to regard with pleasure, favor or care (cause to) behold, consider, look (down), regard, have respect, see.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2151B}\/[H2107]', 'inflected', 'heb', 'זָלַל', '["zâlal"]', '["despised"]', '["v"]', 'to shake (as in the wind), i.e. to quake; figuratively, to be loose morally, worthless or prodigal blow down, glutton, riotous (eater), vile.', 'a primitive root (compare 2107);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4341}/H9020/[H3510]', 'inflected', 'heb', 'מַכְאֹב', '["makʼôb"]', '["like/ pain/ my"]', '["n-m"]', 'anguish or (figuratively) affliction grief, pain, sorrow.', 'sometimes מַכְאוֹב; also (feminine Isaiah 53:3) מַכְאֹבָה; from 3510;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7287A}/H9034/[H7287]', 'inflected', 'heb', 'רָדָה', '["râdâh"]', '["and/ he mastered/ it"]', '["v"]', 'to tread down, i.e. subjugate; specifically, to crumble off (come to, make to) have dominion, prevail against, reign, (bear, make to) rule,(-r, over), take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414I}/H9030/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["he made/ me"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8076}/[H8074]', 'lemma', 'heb', 'שָׁמֵם', '["shâmêm"]', '["desolate"]', '["a"]', 'ruined desolate.', 'from 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1739}\/[H1738]', 'inflected', 'heb', 'דָּוֶה', '["dâveh"]', '["faint"]', '["a"]', 'sick (especially in menstruation) faint, menstruous cloth, she that is sick, having sickness.', 'from 1738;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8244}/[H8244]', 'lemma', 'heb', 'שָׂקַד', '["sâqad"]', '["it has been bound on"]', '["v"]', 'to fasten bind.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6677A}/H9020/[H6696]', 'inflected', 'heb', 'צַוָּאר', '["tsavvâʼr"]', '["neck/ my"]', '["n-m"]', 'the back of the neck (as that on which burdens are bound) neck.', 'or צַוָּר; (Nehemiah 3:5), or צַוָּרֹןlemma צַוָּרן missing vowel, corrected to צַוָּרֹן; (Song of Solomon 4:9), or (feminine) צַוָּארָה; (Micah 2:3), intensively from 6696 in the sense of binding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0047I}/H9020/[H46]', 'inflected', 'heb', 'אַבִּיר', '["ʼabbîyr"]', '["mighty [ones]/ my"]', '["a-m"]', 'angel, bull, chiefest, mighty (one), stout(-hearted), strong (one), valiant.', 'for 46');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0970}/H9020/[H977]', 'inflected', 'heb', 'בָּחוּר', '["bâchûwr"]', '["young men/ my"]', '["n-m"]', 'properly, selected, i.e. a youth (often collective) (choice) young (man), chosen, × hole.', 'or בָּחֻר; participle passive of 977;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H1330>', 'inflected', 'heb', 'לבתולת', '["li/v.tu.Lat"]', '["for/ [the] virgin of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5439J}/H9033/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["[those] around/ him"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5079}/[H5074]', 'inflected', 'heb', 'נִדָּה', '["niddâh"]', '["<into>/ an impure thing","into/ an impure thing"]', '["n-f"]', 'properly, rejection; by implication, impurity, especially personal (menstruation) or moral (idolatry, incest) × far, filthiness, × flowers, menstruous (woman), put apart, × removed (woman), separation, set apart, unclean(-ness, thing, with filthiness).', 'from 5074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0996G}/H9038\/[H995]', 'inflected', 'heb', 'בֵּין', '["bêyn"]', '["between/ them"]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1330>/H9020', 'opaque', 'heb', 'בְּתוּלָה', '["bᵉthûwlâh"]', '["young women/ my"]', '["n-f"]', 'a virgin (from her privacy); sometimes (by continuation) a bride; also (figuratively) a city or state maid, virgin.', 'feminine passive participle of an unused root meaning to separate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0970}/H9020/[H977]', 'inflected', 'heb', 'בָּחוּר', '["bâchûwr"]', '["and/ young men/ my"]', '["n-m"]', 'properly, selected, i.e. a youth (often collective) (choice) young (man), chosen, × hole.', 'or בָּחֻר; participle passive of 977;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7628A}\/[H7618]', 'inflected', 'heb', 'שְׁבִי', '["shᵉbîy"]', '["in <the>/ captivity"]', '["n-m"]', 'exiled; captured; as noun, exile (abstractly or concretely and collectively); by extension, booty captive(-ity), prisoners, × take away, that was taken.', 'from 7618;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3548}/H9020/[H3547]', 'inflected', 'heb', 'כֹּהֵן', '["kôhên"]', '["priests/ my"]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2205G}/H9020/[H2204]', 'inflected', 'heb', 'זָקֵן', '["zâqên"]', '["and/ elders/ my"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315H}/H9028\/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["life/ their","own life/ their"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4194}\/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["like <the>/ death"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3644G}/H9030\/[H3651]', 'inflected', 'heb', 'כְּמוֹ', '["kᵉmôw"]', '["like/ me"]', '["prt"]', 'as, thus, so according to, (such) as (it were, well as), in comparison of, like (as, to, unto), thus, when, worth.', 'or כָּמוֹ; a form of the prefix k, but used separately [compare 3651];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5953A}/[H5953]', 'inflected', 'heb', 'עָלַל', '["ʻâlal"]', '["and/ deal severely"]', '["v"]', 'to effect thoroughly; specifically, to glean (also figuratively); by implication (in a bad sense) to overdo, i.e. maltreat, be saucy to, pain, impose (also literal) abuse, affect, × child, defile, do, glean, mock, practise, thoroughly, work (wonderfully).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1742}\/[H1739]', 'inflected', 'heb', 'דַּוָּי', '["davvây"]', '["[is] faint"]', '["a"]', 'sick; figuratively, troubled faint.', 'from 1739;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5743}/[H5743]', 'lemma', 'heb', 'עוּב', '["ʻûwb"]', '["he covers with a cloud"]', '["v"]', 'to be dense or dark, i.e. to becloud cover with a cloud.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5678}/H9023/[H5676]', 'inflected', 'heb', 'עֶבְרָה', '["ʻebrâh"]', '["in/ wrath/ his"]', '["n-f"]', 'an outburst of passion anger, rage, wrath.', 'feminine of 5676;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8269}/H9024\/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["and/ princes/ its"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0341}/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["like/ an enemy"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6862C}/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["like/ an opponent"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2534}/H9023\/[H3179]', 'inflected', 'heb', 'חֵמָה', '["chêmâh"]', '["rage/ his"]', '["n-f"]', 'heat; figuratively, anger, poison (from its fever) anger, bottles, hot displeasure, furious(-ly, -ry), heat, indignation, poison, rage, wrath(-ful). See 2529.', 'or (Daniel 11:44) חֵמָא; from 3179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0592}\/[H578]', 'inflected', 'heb', 'אֲנִיָּה', '["ʼănîyâh"]', '["and/ lamentation"]', '["n-f"]', 'groaning lamentation, sorrow.', 'from 578;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2554}/[H2554]', 'inflected', 'heb', 'חָמַס', '["châmaç"]', '["and/ he has treated violently"]', '["v"]', 'to be violent; by implication, to maltreat make bare, shake off, violate, do violence, take away violently, wrong, imagine wrongfully.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7900}/H9023/[H5526]', 'inflected', 'heb', 'שֹׂךְ', '["sôk"]', '["booth/ his"]', '["n-m"]', 'a booth (as interlaced) tabernacle.', 'from 5526 in the sense of 7753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4150I}/H9023/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["appointed place/ his"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2195}/[H2194]', 'inflected', 'heb', 'זַעַם', '["zaʻam"]', '["in/ [the] indignation of","in/ indignation"]', '["n-m"]', 'strictly froth at the mouth, i.e. (figuratively) fury (especially of God''s displeasure with sin) angry, indignation, rage.', 'from 2194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3548}\/[H3547]', 'inflected', 'heb', 'כֹּהֵן', '["kôhên"]', '["and/ priest"]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4150H}\/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["an appointed feast"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1104}/[H1104]', 'inflected', 'heb', 'בָּלַע', '["bâlaʻ"]', '["from/ swallowing up"]', '["v"]', 'to make away with (specifically by swallowing); generally, to destroy cover, destroy, devour, eat up, be at end, spend up, swallow down (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2426}/[H2428]', 'lemma', 'heb', 'חֵיל', '["chêyl"]', '["rampart"]', '["n-m"]', 'an army; also (by analogy,) an intrenchment army, bulwark, host, poor, rampart, trench, wall.', 'or (shortened) חֵל; a collateral form of 2428;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0535}\/[H535]', 'inflected', 'heb', 'אָמַל', '["ʼâmal"]', '["they have languished"]', '["v"]', 'to droop; by implication to be sick, to mourn languish, be weak, wax feeble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8269}/H9024/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["and/ princes/ its"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5030}/H9024/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["prophets/ its"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3068G}\/[H1961]', 'inflected', 'heb', 'יְהֹוָה', '["Yᵉhôvâh"]', '["from/ Yahweh"]', '["n-pr"]', '(the) self-Existent or Eternal; Jeho-vah, Jewish national name of God Jehovah, the Lord. Compare 3050, 3069.', 'from 1961;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218A>/H9029', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["head/ their","heads/ their"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3516}/H9020/[H3515]', 'inflected', 'heb', 'כָּבֵד', '["kâbêd"]', '["liver/ my"]', '["n-f"]', 'the liver (as the heaviest of the viscera) liver.', 'the same as 3515;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7151}\/[H7136]', 'inflected', 'heb', 'קִרְיָה', '["qiryâh"]', '["a town"]', '["n-f"]', 'a city city.', 'from 7136 in the sense of flooring, i.e. building;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0517}/H9028/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["to/ mothers/ their"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5848C}/H9048/[H5848]', 'inflected', 'heb', 'עָטַף', '["ʻâṭaph"]', '["when/ faint away/ they"]', '["v"]', 'to shroud, i.e. clothe (whether transitive or reflex.); hence (from the idea of darkness) to languish cover (over), fail, faint, feebler, hide self, be overwhelmed, swoon.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2491H}/[H2490]', 'inflected', 'heb', 'חָלָל', '["châlâl"]', '["like <the>/ [one] fatally wounded"]', '["n-m"]', 'pierced (especially to death); figuratively, polluted kill, profane, slain (man), × slew, (deadly) wounded.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8210G}/[H8210]', 'inflected', 'heb', 'שָׁפַךְ', '["shâphak"]', '["when/ pours itself out"]', '["v"]', 'to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0517}/H9028\/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["mothers/ their"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5749B}/H9032/[H5749]', 'inflected', 'heb', 'עוּד', '["ʻûwd"]', '["will I testify for/ you"]', '["v"]', 'to duplicate or repeat; by implication, to protest, testify (as by reiteration); intensively, to encompass, restore (as a sort of reduplication) admonish, charge, earnestly, lift up, protest, call (take) to record, relieve, rob, solemnly, stand upright, testify, give warning, (bear, call to, give, take to) witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5162G}/H9032/[H5162]', 'inflected', 'heb', 'נָחַם', '["nâcham"]', '["so/ I may comfort/ you"]', '["v"]', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5030}/H9022/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["prophets/ your"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H8602A>', 'inflected', 'heb', 'ותפל', '["ve./ta.Fel"]', '["and/ sham"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7622}/H9022/[H7617]', 'inflected', 'heb', 'שְׁבוּת', '["shᵉbûwth"]', '["captivities/ your","captivity/ your"]', '["n-f"]', 'exile, concretely, prisoners; figuratively, a former state of prosperity captive(-ity).', 'or שְׁבִית; from 7617;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4065}\/[H5080]', 'inflected', 'heb', 'מַדּוּחַ', '["maddûwach"]', '["and/ enticement<s>"]', '["n-m"]', 'seduction cause of banishment.', 'from 5080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0341}/H9022/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["enemies/ your","enemy/ your"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2786}/[H2786]', 'inflected', 'heb', 'חָרַק', '["châraq"]', '["and/ they have gnashed"]', '["v"]', 'to grate the teeth gnash.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H6960A}/H9033/[H6960]', 'inflected', 'heb', 'קָוָה', '["qâvâh"]', '["that/ we have waited for/ it"]', '["v"]', 'to bind together (perhaps by twisting), i.e. collect; (figuratively) to expect gather (together), look, patiently, tarry, wait (for, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0565B}/H9023/[H561]', 'inflected', 'heb', 'אִמְרָה', '["ʼimrâh"]', '["word/ his"]', '["n-f"]', 'commandment, speech, word.', 'or אֶמְרָה; feminine of 561, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6862C}/H9022\/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["opponents/ your"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6314}/[H6313]', 'lemma', 'heb', 'פּוּגָה', '["pûwgâh"]', '["rest"]', '["n-f"]', 'intermission rest.', 'from 6313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869A}/H9022\/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["eye/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3709G}/H9022/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["hands/ your"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2351>\', 'opaque', 'heb', 'חוּץ', '["chûwts"]', '["[the] streets"]', '["n-m"]', 'properly, separate by a wall, i.e. outside, outdoors abroad, field, forth, highway, more, out(-side, -ward), street, without.', 'or (shortened) חֻץ; (both forms feminine in the plural) from an unused root meaning to sever;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2949}/[H2946]', 'lemma', 'heb', 'טִפֻּח', '["ṭippuch"]', '["health<s>"]', '["n-m"]', 'nursing span long.', 'from 2946;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5030}\/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["and/ prophet"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2550}\/[H2550]', 'inflected', 'heb', 'חָמַל', '["châmal"]', '["will he spare?","you have spared"]', '["v"]', 'to commiserate; by implication, to spare have compassion, (have) pity, spare.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4032}/H9020/[H1481]', 'inflected', 'heb', 'מָגוֹר', '["mâgôwr"]', '["terrors/ my"]', '["n-m"]', 'a fright (objective or subjective) fear, terror. Compare 4036.', 'or (Lamentations 2:22) מָגוּר; from 1481 in the sense of fearing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3615H}/H9038\/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["he has made an end of/ them"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5785}/H9020/[H5783]', 'inflected', 'heb', 'עוֹר', '["ʻôwr"]', '["and/ skin/ my"]', '["n-m"]', 'skin (as naked); by implication, hide, leather hide, leather, skin.', 'from 5783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8513}/[H3811]', 'inflected', 'heb', 'תְּלָאָה', '["tᵉlâʼâh"]', '["and/ hardship"]', '["n-f"]', 'distress travail, travel, trouble.', 'from 3811;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5769J}\/[H5956]', 'inflected', 'heb', 'עוֹלָם', '["ʻôwlâm"]', '["antiquity"]', '["n-m"]', 'properly, concealed, i.e. the vanishing point; generally, time out of mind (past or future), i.e. (practically) eternity; frequentatively, adverbial (especially with prepositional prefix) always alway(-s), ancient (time), any more, continuance, eternal, (for, (n-)) ever(-lasting, -more, of old), lasting, long (time), (of) old (time), perpetual, at any time, (beginning of the) world ( without end). Compare 5331, 5703.', 'or עֹלָם; from 5956;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5178A}/H9020/[H5154]', 'inflected', 'heb', 'נְחֹשֶׁת', '["nᵉchôsheth"]', '["bronze fetter[s]/ my"]', '["n-m"]', 'copper, hence, something made of that metal, i.e. coin, a fetter; figuratively, base (as compared with gold or silver) brasen, brass, chain, copper, fetter (of brass), filthiness, steel.', 'for 5154;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7768}/[H7768]', 'inflected', 'heb', 'שָׁוַע', '["shâvaʻ"]', '["and/ I may cry for help"]', '["v"]', 'properly, to be free; but used only causatively and reflexively, to halloo (for help, i.e. freedom from some trouble) cry (aloud, out), shout.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5640B}/[H5640]', 'lemma', 'heb', 'סָתַם', '["çâtham"]', '["he has shut out"]', '["v"]', 'to stop up; by implication, to repair; figuratively, to keep secret closed up, hidden, secret, shut out (up), stop.', 'or שָׂתַם; (Numbers 24:15), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870K}/H9020/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["ways/ my"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1496}/[H1491]', 'inflected', 'heb', 'גָּזִית', '["gâzîyth"]', '["with/ hewn [stone]"]', '["n-f"]', 'something cut, i.e. dressed stone hewed, hewn stone, wrought.', 'from 1491;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5753A}\/[H5753]', 'inflected', 'heb', 'עָוָה', '["ʻâvâh"]', '["he has made crooked"]', '["v"]', 'to crook, literally or figuratively do amiss, bow down, make crooked, commit iniquity, pervert, (do) perverse(-ly), trouble, × turn, do wickedly, do wrong.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6582}/H9030/[H6582]', 'inflected', 'heb', 'פָּשַׁח', '["pâshach"]', '["and/ he has torn in pieces/ me"]', '["v"]', 'to tear in pieces pull in pieces.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4307H}/[H5201]', 'inflected', 'heb', 'מַטָּרָא', '["maṭṭârâʼ"]', '["like <the>/ target"]', '["n-f"]', 'a jail (as a guard-house); also an aim (as being closely watched) mark, prison.', 'or מַטָּרָה; from 5201;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2671}\/[H2686]', 'inflected', 'heb', 'חֵץ', '["chêts"]', '["for <the>/ arrow"]', '["n-m"]', 'properly, a piercer, i.e. an arrow; by implication, a wound; figuratively, (of God) thunder-bolt; the shaft of a spear archer, arrow, dart, shaft, staff, wound.', 'from 2686; also by interchange for 6086');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3629}/H9020/[H3627]', 'inflected', 'heb', 'כִּלְיָה', '["kilyâh"]', '["in/ kidneys/ my"]', '["n-f"]', 'a kidney (as an essential organ); figuratively, the mind (as the interior self) kidneys, reins.', 'feminine of 3627 (only in the plural);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4844}/[H4843]', 'inflected', 'heb', 'מְרֹר', '["mᵉrôr"]', '["with <the>/ bitter things"]', '["n-m"]', 'a bitter herb bitter(-ness).', 'or מְרוֹר; from 4843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3939>\', 'opaque', 'heb', 'לַעֲנָה', '["laʻănâh"]', '["wormwood"]', '["n-f"]', 'wormwood (regarded as poisonous, and therefore accursed) hemlock, wormwood.', 'from an unused root supposed to mean to curse;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1638}/[H1638]', 'inflected', 'heb', 'גָּרַס', '["gâraç"]', '["and/ he has broken"]', '["v"]', 'to crush; also (intransitively and figuratively) to dissolve break.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2687}/[H2671]', 'inflected', 'heb', 'חָצָץ', '["châtsâts"]', '["with <the>/ gravel"]', '["n-m"]', 'properly, something cutting; hence, gravel (as grit); an arrow arrow, gravel (stone).', 'from 2687; also like 2671');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3728}/H9030/[H3728]', 'inflected', 'heb', 'כָּפַשׁ', '["kâphash"]', '["he has made cower/ me"]', '["v"]', 'to tread down; figuratively, to humiliate cover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2186A}/[H2186]', 'inflected', 'heb', 'זָנַח', '["zânach"]', '["and/ it has excluded"]', '["v"]', 'reject, forsake, fail cast away (off), remove far away (off).', 'a primitive root meaning to push aside, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7965G}/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["from/ peace"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5331}/H9020/[H5329]', 'inflected', 'heb', 'נֶצַח', '["netsach"]', '["endurance/ my"]', '["n-m"]', 'properly, a goal, i.e. the bright object at a distance travelled towards; hence (figuratively), splendor, or (subjectively) truthfulness, or (objectively) confidence; but usually (adverbially), continually (i.e. to the most distant point of view) alway(-s), constantly, end, ( n-) ever(more), perpetual, strength, victory.', 'or נֵצַח; from 5329;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8431}/H9020/[H3176]', 'inflected', 'heb', 'תּוֹחֶלֶת', '["tôwcheleth"]', '["and/ hope/ my"]', '["n-f"]', 'expectation hope.', 'from 3176;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4788}/H9020/[H7300]', 'inflected', 'heb', 'מָרוּד', '["mârûwd"]', '["and/ homelessness/ my"]', '["n-m"]', 'an outcast; (abstractly) destitution cast out, misery.', 'from 7300 in the sense of maltreatment;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7743}/[H7743]', 'inflected', 'heb', 'שׁוּחַ', '["shûwach"]', '["so/ it may bow down"]', '["v"]', 'to sink, literally or figuratively bow down, incline, humble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6960A}/H9033/[H6960]', 'inflected', 'heb', 'קָוָה', '["qâvâh"]', '["to/ [those who] wait for/ him"]', '["v"]', 'to bind together (perhaps by twisting), i.e. collect; (figuratively) to expect gather (together), look, patiently, tarry, wait (for, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3175}/[H3176]', 'inflected', 'heb', 'יָחִיל', '["yâchîyl"]', '["and/ waiting"]', '["a"]', 'expectant should hope.', 'from 3176;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1748}/[H1826]', 'inflected', 'heb', 'דּוּמָם', '["dûwmâm"]', '["and/ silently"]', '["n-m"]', 'still; adverbially, silently dumb, silent, quietly wait.', 'from 1826;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5271A}/H9023\/[H5288]', 'inflected', 'heb', 'נָעוּר', '["nâʻûwr"]', '["in/ youth<s>/ his"]', '["n-m n-f"]', '(only in plural collective or emphatic form) youth, the state (juvenility) or the persons (young people) childhood, youth.', 'or נָעֻר; and (feminine) נְעֻרָה; properly, passive participle from 5288 as denominative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2781}\/[H2778]', 'inflected', 'heb', 'חֶרְפָּה', '["cherpâh"]', '["with/ reproach"]', '["n-f"]', 'contumely, disgrace, the pudenda rebuke, reproach(-fully), shame.', 'from 2778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3013}/[H3013]', 'inflected', 'heb', 'יָגָה', '["yâgâh"]', '["and/ he has grieved"]', '["v"]', 'to grieve afflict, cause grief, grieve, sorrowful, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1792}/[H1794]', 'inflected', 'heb', 'דָּכָא', '["dâkâʼ"]', '["to/ crush"]', '["v"]', 'to crumble; transitively, to bruise (literally or figuratively) beat to pieces, break (in pieces), bruise, contrite, crush, destroy, humble, oppress, smite.', 'a primitive root (compare 1794);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5791}/[H5791]', 'inflected', 'heb', 'עָוַת', '["ʻâvath"]', '["to/ subvert"]', '["v"]', 'to wrest bow self, (make) crooked., falsifying, overthrow, deal perversely, pervert, subvert, turn upside down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7200J}\/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["he has seen"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0596}/[H596]', 'lemma', 'heb', 'אָנַן', '["ʼânan"]', '["will he complain"]', '["v"]', 'to mourn, i.e. complain complain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2399}/H9023\/[H2398]', 'inflected', 'heb', 'חֵטְא', '["chêṭᵉʼ"]', '["sins/ his"]', '["n-m"]', 'a crime or its penalty fault, × grievously, offence, (punishment of) sin.', 'from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870G}/H9025/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["ways/ our"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5545}\/[H5545]', 'inflected', 'heb', 'סָלַח', '["çâlach"]', '["you have forgiven"]', '["v"]', 'to forgive forgive, pardon, spare.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7291}/H9035/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["and/ you have pursued/ us"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5501}/[H5500]', 'lemma', 'heb', 'סְחִי', '["çᵉchîy"]', '["scouring"]', '["n-m"]', 'refuse (as swept off) offscouring.', 'from 5500;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3973}/[H3988]', 'inflected', 'heb', 'מָאוֹס', '["mâʼôwç"]', '["and/ refuse"]', '["n-m"]', 'refuse refuse.', 'from 3988;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7612}/[H7582]', 'inflected', 'heb', 'שֵׁאת', '["shêʼth"]', '["<the>/ devastation"]', '["n-f"]', 'devastation desolation.', 'from 7582;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2014}/[H6313]', 'lemma', 'heb', 'הֲפֻגָה', '["hăphugâh"]', '["stop<s>"]', '["n-f"]', 'relaxation intermission.', 'from 6313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5315I}/H9020/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["to/ self/ my"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5892B}/H9020\/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["city/ my"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1504}\/[H1504]', 'inflected', 'heb', 'גָּזַר', '["gâzar"]', '["I have been cut off"]', '["v"]', 'to cut down or off; (figuratively) to destroy, divide, exclude, or decide cut down (off), decree, divide, snatch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7309}/H9020/[H7305]', 'inflected', 'heb', 'רְוָחָה', '["rᵉvâchâh"]', '["to/ relief/ my"]', '["n-f"]', 'relief breathing, respite.', 'feminine of 7305;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7775}/H9020/[H7773]', 'inflected', 'heb', 'שַׁוְעָה', '["shavʻâh"]', '["to/ cry for help/ my"]', '["n-f"]', 'a hallooing crying.', 'feminine of 7773;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3372G}\/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["you be afraid","you fear"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5792}/H9020/[H5791]', 'inflected', 'heb', 'עַוָּתָה', '["ʻavvâthâh"]', '["oppression/ my"]', '["n-f"]', 'oppression wrong.', 'from 5791;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5360}/H9028/[H5359]', 'inflected', 'heb', 'נְקָמָה', '["nᵉqâmâh"]', '["vengeance/ their"]', '["n-f"]', 'avengement, whether the act or the passion avenge, revenge(-ing), vengeance.', 'feminine of 5359;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1902H}/H9028/[H1897]', 'inflected', 'heb', 'הִגָּיוֹן', '["higgâyôwn"]', '["and/ muttering/ their"]', '["n-m"]', 'a murmuring sound, i.e. a musical notation (probably similar to the modern affettuoso to indicate solemnity of movement); by implication, a machination device, Higgaion, meditation, solemn sound.', 'intensive from 1897;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7675}/H9028/[H3427]', 'inflected', 'heb', 'שֶׁבֶת', '["shebeth"]', '["sitting/ their"]', '["n-f"]', 'properly, session; but used also concretely, an abode or locality place, seat. Compare 3429.', 'infinitive of 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7012}/H9028/[H6965]', 'inflected', 'heb', 'קִימָה', '["qîymâh"]', '["and/ rising/ their"]', '["n-f"]', 'an arising rising up.', 'from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4485}/H9028\/[H5059]', 'inflected', 'heb', 'מַנְגִּינָה', '["mangîynâh"]', '["[am] mocking song/ their"]', '["n-f"]', 'a satire music.', 'from 5059;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4044}/[H4042]', 'lemma', 'heb', 'מְגִנָּה', '["mᵉginnâh"]', '["shamelessness of"]', '["n-f"]', 'a covering (in a bad sense), i.e. blindness or obduracy sorrow. See also 4043.', 'from 4042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8381}/H9021/[H422]', 'inflected', 'heb', 'תַּאֲלָה', '["taʼălâh"]', '["curse/ your"]', '["n-f"]', 'an imprecation curse.', 'from 422;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6004}/[H6004]', 'lemma', 'heb', 'עָמַם', '["ʻâmam"]', '["it is dimmed"]', '["v"]', 'to associate; by implication, to overshadow (by huddling together) become dim, hide.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3800}/[H3799]', 'inflected', 'heb', 'כֶּתֶם', '["kethem"]', '["the/ gold"]', '["n-m"]', 'properly, something carved out, i.e. ore; hence, gold (pure as originally mined) ((most) fine, pure) gold(-en wedge).', 'from 3799;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3368}/[H3365]', 'inflected', 'heb', 'יָקָר', '["yâqâr"]', '["<the>/ precious"]', '["a"]', 'valuable (objectively or subjectively) brightness, clear, costly, excellent, fat, honourable women, precious, reputation.', 'from 3365;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5537}/[H5537]', 'inflected', 'heb', 'סָלָא', '["çâlâʼ"]', '["who/ were weighed"]', '["v"]', 'to suspend in a balance, i.e. weigh compare.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6337}/[H6338]', 'inflected', 'heb', 'פָּז', '["pâz"]', '["with <the>/ pure gold"]', '["n-m"]', 'pure (gold); hence, gold itself (as refined) fine (pure) gold.', 'from 6338;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5035A}/[H5034]', 'inflected', 'heb', 'נֶבֶל', '["nebel"]', '["to/ jars of"]', '["n-m"]', 'a skin-bag for liquids (from collapsing when empty); hence, a vase (as similar in shape when full); also a lyre (as having a body of like form) bottle, pitcher, psaltery, vessel, viol.', 'or נֵבֶל; from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3335H}\/[H3334]', 'inflected', 'heb', 'יָצַר', '["yâtsar"]', '["a potter"]', '["v"]', 'to mould into a form; especially as a potter; figuratively, to determine (i.e. form a resolution) × earthen, fashion, form, frame, make(-r), potter, purpose.', 'probably identical with 3334 (through the squeezing into shape); (compare 3331);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1482}/H9029/[H1481]', 'inflected', 'heb', 'גּוּר', '["gûwr"]', '["young/ their"]', '["n-m"]', 'a cub (as still abiding in the lair), especially of the lion whelp, young one.', 'or (shortened) גֻּר; perhaps from 1481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3283}/[H3282]', 'inflected', 'heb', 'יָעֵן', '["yâʻên"]', '["like <the>/ ostriches"]', '["n-f"]', 'the ostrich (probably from its answering cry ostrich.', 'from the same as 3282;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4057B}\/[H1696]', 'inflected', 'heb', 'מִדְבָּר', '["midbâr"]', '["in the/ wilderness"]', '["n-m"]', 'a pasture (i.e. open field, whither cattle are driven); by implication, a desert; also speech (including its organs) desert, south, speech, wilderness.', 'from 1696 in the sense of driving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4574}/[H5727]', 'inflected', 'heb', 'מַעֲדָן', '["maʻădân"]', '["<to>/ delicacies"]', '["n-m"]', 'a delicacy or (abstractly) pleasure (adverbially, cheerfully) dainty, delicately, delight.', 'or (feminine) מַעֲדַנָּה; from 5727;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0830H}\/[H827]', 'inflected', 'heb', 'אַשְׁפֹּת', '["ʼashpôth"]', '["ash heaps"]', '["n-m"]', 'a heap of rubbish or filth dung (hill).', 'or אַשְׁפּוֹת; or שְׁפֹת; (contraction) plural of a noun of the same form as 827, from 8192 (in the sense of scraping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2403I}/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["more than/ [the] sin of"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027G}\/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hands"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6705}/[H6705]', 'lemma', 'heb', 'צָחַח', '["tsâchach"]', '["they were dazzling"]', '["v"]', 'to glare, i.e. be dazzling white be whiter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6106I}/[H6105]', 'lemma', 'heb', 'עֶצֶם', '["ʻetsem"]', '["bone"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1508}/H9028\/[H1506]', 'inflected', 'heb', 'גִּזְרָה', '["gizrâh"]', '["polishing/ their"]', '["n-f"]', 'the figure or person (as if cut out); also an inclosure (as separated) polishing, separate place.', 'feminine of 1506;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7815}/[H7835]', 'inflected', 'heb', 'שְׁחוֹר', '["shᵉchôwr"]', '["more than/ soot"]', '["n-f"]', 'dinginess, i.e. perhaps soot coal.', 'from 7835;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8389}/H9028/[H8388]', 'inflected', 'heb', 'תֹּאַר', '["tôʼar"]', '["appearance/ their"]', '["n-m"]', 'outline, i.e. figure or appearance beautiful, × comely, countenance, fair, × favoured, form, × goodly, × resemble, visage.', 'from 8388;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6821}/[H6821]', 'lemma', 'heb', 'צָפַד', '["tsâphad"]', '["it has shriveled"]', '["v"]', 'to adhere cleave.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6086G}\/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["like <the>/ wood"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2491A}/[H2490]', 'inflected', 'heb', 'חָלָל', '["châlâl"]', '["more than/ [those] slain of"]', '["n-m"]', 'pierced (especially to death); figuratively, polluted kill, profane, slain (man), × slew, (deadly) wounded.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2100I}/[H2100]', 'lemma', 'heb', 'זוּב', '["zûwb"]', '["they flow away"]', '["v"]', 'to flow freely (as water), i.e. (specifically) to have a (sexual) flux; figuratively, to waste away; also to overflow flow, gush out, have a (running) issue, pine away, run.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8570}/[H5107]', 'inflected', 'heb', 'תְּנוּבָה', '["tᵉnûwbâh"]', '["from/ [the] produce<s> of"]', '["n-f"]', 'produce fruit, increase.', 'from 5107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7704M>\', 'opaque', 'heb', 'שָׂדֶה', '["sâdeh"]', '["[the] field"]', '["n-m"]', 'a field (as flat) country, field, ground, land, soil, × wild.', 'or שָׂדַי; from an unused root meaning to spread out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7362}/[H7355]', 'lemma', 'heb', 'רַחְמָנִי', '["rachmânîy"]', '["compassionate"]', '["a"]', 'compassionate pitiful.', 'from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7667}/[H7665]', 'inflected', 'heb', 'שֶׁבֶר', '["sheber"]', '["in/ [the] brokenness of"]', '["n-m"]', 'a fracture, figuratively, ruin; specifically, a solution (of a dream) affliction, breach, breaking, broken(-footed, -handed), bruise, crashing, destruction, hurt, interpretation, vexation.', 'or שֵׁבֶר; from 7665;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3247H}/H9024\/[H3245]', 'inflected', 'heb', 'יְסוֹד', '["yᵉçôwd"]', '["foundations/ its"]', '["n-f"]', 'a foundation (literally or figuratively) bottom, foundation, repairing', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8210H}/[H8210]', 'inflected', 'heb', 'שָׁפַךְ', '["shâphak"]', '["who/ shed"]', '["v"]', 'to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3830}/H9028\/[H3847]', 'inflected', 'heb', 'לְבוּשׁ', '["lᵉbûwsh"]', '["<in>/ clothes/ their"]', '["n-m"]', 'a garment (literally or figuratively); by implication (euphemistically) a wife apparel, clothed with, clothing, garment, raiment, vestment, vesture.', 'or לְבֻשׁ; from 3847;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5132A}/[H5132]', 'lemma', 'heb', 'נוּץ', '["nûwts"]', '["they fled"]', '["v"]', 'properly, to flash; also, to fly away (from the quickness of motion) flee away, bud (forth).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1481A}\/[H1481]', 'inflected', 'heb', 'גּוּר', '["gûwr"]', '["to/ sojourn"]', '["v"]', 'properly, to turn aside from the road (for a lodging or any other purpose), i.e. sojourn (as a guest); also to shrink, fear (as in a strange place); also to gather for hostility (as afraid) abide, assemble, be afraid, dwell, fear, gather (together), inhabitant, remain, sojourn, stand in awe, (be) stranger, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5027}/H9038/[H5027]', 'inflected', 'heb', 'נָבַט', '["nâbaṭ"]', '["to/ pay attention to/ them"]', '["v"]', 'to scan, i.e. look intently at; by implication, to regard with pleasure, favor or care (cause to) behold, consider, look (down), regard, have respect, see.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2603A}\/[H2583]', 'inflected', 'heb', 'חָנַן', '["chânan"]', '["they showed favor to"]', '["v"]', 'properly, to bend or stoop in kindness to an inferior; to favor, bestow; causatively to implore (i.e. move to favor by petition) beseech, × fair, (be, find, shew) favour(-able), be (deal, give, grant (gracious(-ly), intreat, (be) merciful, have (shew) mercy (on, upon), have pity upon, pray, make supplication, × very.', 'a primitive root (compare 2583);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5750}/H9045/[H5749]', 'inflected', 'heb', 'עוֹד', '["ʻôwd"]', '["yet/ we"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5833}/H9025/[H5828]', 'inflected', 'heb', 'עֶזְרָה', '["ʻezrâh"]', '["help/ our"]', '["n-f"]', 'aid help(-ed, -er).', 'or עֶזְרָת; (Psalm 60:11 (13); Psalm 108:12 (13)), feminine of 5828;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6836}/H9025/[H6822]', 'inflected', 'heb', 'צְפִיָּה', '["tsᵉphîyâh"]', '["in/ watchtower/ our"]', '["n-f"]', 'watchfulness watching.', 'from 6822;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3467}\/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["it will save"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6806}/H9025/[H6804]', 'inflected', 'heb', 'צַעַד', '["tsaʻad"]', '["steps/ our"]', '["n-m"]', 'a pace or regular step pace, step.', 'from 6804;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7093}/H9025/[H7112]', 'inflected', 'heb', 'קֵץ', '["qêts"]', '["end/ our"]', '["n-m"]', 'an extremity; adverbially (with prepositional prefix) after after, (utmost) border, end, (in-) finite, × process.', 'contracted from 7112;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7093}/H9025\/[H7112]', 'inflected', 'heb', 'קֵץ', '["qêts"]', '["end/ our"]', '["n-m"]', 'an extremity; adverbially (with prepositional prefix) after after, (utmost) border, end, (in-) finite, × process.', 'contracted from 7112;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7291}/H9035/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["pursuers/ our"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1814}/H9035/[H1814]', 'inflected', 'heb', 'דָּלַק', '["dâlaq"]', '["they hotly pursued/ us"]', '["v"]', 'to flame (literally or figuratively) burning, chase, inflame, kindle, persecute(-or), pursue hotly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0639H}/H9025/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["nostrils/ our"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7825}/H9028/[H7812]', 'inflected', 'heb', 'שְׁחִית', '["shᵉchîyth"]', '["in/ pits/ their"]', '["n-f"]', 'a pit-fall (literally or figuratively) destruction, pit.', 'from 7812;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1471A}\/[H1465]', 'inflected', 'heb', 'גּוֹי', '["gôwy"]', '["among the/ nations"]', '["n-m n-pr-m"]', 'a foreign nation; hence, a Gentile; also (figuratively) a troop of animals, or a flight of locusts Gentile, heathen, nation, people.', 'rarely (shortened) גֹּי; apparently from the same root as 1465 (in the sense of massing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6168}\/[H6168]', 'inflected', 'heb', 'עָרָה', '["ʻârâh"]', '["and/ you may strip yourself naked"]', '["v"]', 'to be (causatively, make) bare; hence, to empty, pour out, demolish leave destitute, discover, empty, make naked, pour (out), rase, spread self, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1540K}/H9032/[H1540]', 'inflected', 'heb', 'גָּלָה', '["gâlâh"]', '["to/ take into exile/ you"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2403B}/H9022\/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["sins/ your"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2781}/H9025/[H2778]', 'inflected', 'heb', 'חֶרְפָּה', '["cherpâh"]', '["reproach/ our"]', '["n-f"]', 'contumely, disgrace, the pudenda rebuke, reproach(-fully), shame.', 'from 2778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0517}/H9025/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["mothers/ our"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4325G}/H9025/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["water/ our"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6086G}/H9025/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["wood<s>/ our"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6677A}/H9025/[H6696]', 'inflected', 'heb', 'צַוָּאר', '["tsavvâʼr"]', '["neck/ our"]', '["n-m"]', 'the back of the neck (as that on which burdens are bound) neck.', 'or צַוָּר; (Nehemiah 3:5), or צַוָּרֹןlemma צַוָּרן missing vowel, corrected to צַוָּרֹן; (Song of Solomon 4:9), or (feminine) צַוָּארָה; (Micah 2:3), intensively from 6696 in the sense of binding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5315H}/H9025/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["with/ life/ our"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5785}/H9025/[H5783]', 'inflected', 'heb', 'עוֹר', '["ʻôwr"]', '["skin/ our"]', '["n-m"]', 'skin (as naked); by implication, hide, leather hide, leather, skin.', 'from 5783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2911}/[H2912]', 'lemma', 'heb', 'טְחוֹן', '["ṭᵉchôwn"]', '["a mill"]', '["n-m"]', 'a hand mill; hence, a millstone to grind.', 'from 2912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5058}/H9028/[H5059]', 'inflected', 'heb', 'נְגִינָה', '["nᵉgîynâh"]', '["from/ music/ their"]', '["n-f"]', 'properly, instrumental music; by implication, a stringed instrument; by extension, a poem set to music; specifically, an epigram stringed instrument, musick, Neginoth (plural), song.', 'or נְגִינַת; (Psalm 61:title), from 5059;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4234}/H9025/[H2342]', 'inflected', 'heb', 'מָחוֹל', '["mâchôwl"]', '["dancing/ our"]', '["n-m"]', 'a (round) dance dance(-cing).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218A>/H9025', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["head/ our"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H8074G}/[H8074]', 'inflected', 'heb', 'שָׁמֵם', '["shâmêm"]', '["that/ [is] desolate"]', '["v"]', 'to stun (or intransitively, grow numb), i.e. devastate or (figuratively) stupefy (both usually in a passive sense) make amazed, be astonied, (be an) astonish(-ment), (be, bring into, unto, lay, lie, make) desolate(-ion, places), be destitute, destroy (self), (lay, lie, make) waste, wonder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7911}/H9035/[H7911]', 'inflected', 'heb', 'שָׁכַח', '["shâkach"]', '["do you forget/ us"]', '["v"]', 'to mislay, i.e. to be oblivious of, from want of memory or attention × at all, (cause to) forget.', 'or שָׁכֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3988A}/H9035/[H3988]', 'inflected', 'heb', 'מָאַס', '["mâʼaç"]', '["you have rejected/ us"]', '["v"]', 'to spurn; also (intransitively) to disappear abhor, cast away (off), contemn, despise, disdain, (become) loathe(some), melt away, refuse, reject, reprobate, × utterly, vile person.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3529}/[H3528]', 'lemma', 'heb', 'כְּבָר', '["Kᵉbâr"]', '["Kebar"]', '["n"]', 'Kebar, a river of Mesopotamia Chebar. Compare 2249.', 'the same as 3528; length;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4759A}/[H4758]', 'lemma', 'heb', 'מַרְאָה', '["marʼâh"]', '["visions of"]', '["n-f"]', 'a vision; also (causatively) a mirror looking glass, vision.', 'feminine of 4758;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3112}/[H3078]', 'lemma', 'heb', 'יוֹיָכִין', '["Yôwyâkîyn"]', '["Jehoiachin"]', '["n-pr-m"]', 'Jojakin, an Israelite king Jehoiachin.', 'a form of 3078;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3168H}/[H2388]', 'lemma', 'heb', 'יְחֶזְקֵאל', '["Yᵉchezqêʼl"]', '["Ezekiel"]', '["n-pr-m"]', 'Jechezkel, the name of two Israelites Ezekiel, Jehezekel.', 'from 2388 and 410; God will strengthen;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0941}/[H940]', 'lemma', 'heb', 'בּוּזִי', '["Bûwzîy"]', '["Buzi"]', '["n-pr-m"]', 'Buzi, an Israelite Buzi.', 'the same as 940;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H8432>/H9024', 'inflected', 'heb', 'ומתוכה', '["u./Mi./to.Kha/h"]', '["and/ [was] from/ [the] middle of/ it"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H2830>', 'inflected', 'heb', 'החשמל', '["ha./chash.Mal"]', '["<the>/ shining substance"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4758}/H9029/[H7200]', 'inflected', 'heb', 'מַרְאֶה', '["marʼeh"]', '["[was] appearance/ their"]', '["n-m"]', 'a view (the act of seeing); also an appearance (the thing seen), whether (real) a shape (especially if handsome, comeliness; often plural the looks), or (mental) a vision × apparently, appearance(-reth), × as soon as beautiful(-ly), countenance, fair, favoured, form, goodly, to look (up) on (to), look(-eth), pattern, to see, seem, sight, visage, vision.', 'from 7200a;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3709H}/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["and/ [the] sole of"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3709H}/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["[was] like/ [the] sole of"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5340}/[H5340]', 'inflected', 'heb', 'נָצַץ', '["nâtsats"]', '["and/ [they were] gleaming"]', '["v"]', 'to glare, i.e. be bright-colored sparkle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7044}/[H7043]', 'lemma', 'heb', 'קָלָל', '["qâlâl"]', '["burnished"]', '["a"]', 'brightened (as if sharpened) burnished, polished.', 'from 7043;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3671}/H9028/[H3670]', 'inflected', 'heb', 'כָּנָף', '["kânâph"]', '["wings/ their"]', '["n-f"]', 'an edge or extremity; specifically (of a bird or army) a wing, (of a garment or bedclothing) a flap, (of the earth) a quarter, (of a building) a pinnacle bird, border, corner, end, feather(-ed), × flying, (one an-) other, overspreading, × quarters, skirt, × sort, uttermost part, wing(-ed).', 'from 3670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7253}/H9028/[H7251]', 'inflected', 'heb', 'רֶבַע', '["rebaʻ"]', '["sides/ their"]', '["n-m"]', 'a fourth (part or side) fourth part, side, square.', 'from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0702}/H9028/[H7251]', 'inflected', 'heb', 'אַרְבַּע', '["ʼarbaʻ"]', '["[belonged] to/ [the] four of/ them","to/ [the] four of/ them"]', '["n"]', 'four four.', 'masculine אַרְבָּעָה; from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1980G}/H9049/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["when/ moved/ they"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H8040G}/[H8071]', 'inflected', 'heb', 'שְׂמֹאול', '["sᵉmôʼwl"]', '["from/ the/ left [side]"]', '["n-m"]', 'properly, dark (as enveloped), i.e. the north; hence (by orientation), the left hand left (hand, side).', 'or שְׂמֹאל; a primitive word (rather perhaps from the same as 8071 (by insertion of the aleph) through the idea of wrapping up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0702}/H9029/[H7251]', 'inflected', 'heb', 'אַרְבַּע', '["ʼarbaʻ"]', '["[belonged] to/ [the] four of/ them","to/ [the] four of/ them"]', '["n"]', 'four four.', 'masculine אַרְבָּעָה; from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1472}/H9029/[H1465]', 'inflected', 'heb', 'גְּוִיָּה', '["gᵉvîyâh"]', '["bodies/ their"]', '["n-f"]', 'a body, whether alive or dead (dead) body, carcase, corpse.', 'prolonged for 1465;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4758}/H9028/[H7200]', 'inflected', 'heb', 'מַרְאֶה', '["marʼeh"]', '["appearance/ their"]', '["n-m"]', 'a view (the act of seeing); also an appearance (the thing seen), whether (real) a shape (especially if handsome, comeliness; often plural the looks), or (mental) a vision × apparently, appearance(-reth), × as soon as beautiful(-ly), countenance, fair, favoured, form, goodly, to look (up) on (to), look(-eth), pattern, to see, seem, sight, visage, vision.', 'from 7200a;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H1513>', 'inflected', 'heb', 'כגחלי', '["ke./ga.cha.lei"]', '["[was] like/ coals of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2416C}/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["and/ the/ living creatures"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7519}/[H7519]', 'lemma', 'heb', 'רָצָא', '["râtsâʼ"]', '["they were running"]', '["v"]', 'to run; also to delight in accept, run.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0965>', 'inflected', 'heb', 'הבזק', '["ha./ba.Zak"]', '["<the>/ lightning"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4639G}/H9028/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["and/ construction<s>/ their"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4758}/H9028/[H7200]', 'inflected', 'heb', 'מַרְאֶה', '["marʼeh"]', '["and/ appearance/ their"]', '["n-m"]', 'a view (the act of seeing); also an appearance (the thing seen), whether (real) a shape (especially if handsome, comeliness; often plural the looks), or (mental) a vision × apparently, appearance(-reth), × as soon as beautiful(-ly), countenance, fair, favoured, form, goodly, to look (up) on (to), look(-eth), pattern, to see, seem, sight, visage, vision.', 'from 7200a;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7253}/H9029/[H7251]', 'inflected', 'heb', 'רֶבַע', '["rebaʻ"]', '["sides/ their"]', '["n-m"]', 'a fourth (part or side) fourth part, side, square.', 'from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1980G}/H9048/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["when/ moved/ they"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1354>/H9029', 'inflected', 'heb', 'וגביהן', '["ve./Ga.bei./Hen"]', '["and/ rims/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1980G}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ when/ moved"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5375G}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ when/ lifted up","and/ when/ were lifted up"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H0212>', 'inflected', 'heb', 'והאופנים', '["ve./ha./''o.fa.Nim"]', '["and/ the/ wheels"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5980}/H9038/[H6004]', 'inflected', 'heb', 'עֻמָּה', '["ʻummâh"]', '["<to>/ close by/ them","[were] <to>/ close by/ them"]', '["n-f"]', 'conjunction, i.e. society; mostly adverb or preposition (with prepositional prefix), near, beside, along with (over) against, at, beside, hard by, in points.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0212>', 'inflected', 'heb', 'באופנים', '["ba./''o.fa.Nim"]', '["[was] in the/ wheels"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5975G}/H9048/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["and/ when/ stood still/ they"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5375G}/H9048/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ when/ were lifted up/ they"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H0376I>', 'inflected', 'heb', 'ולאיש', '["u./le./''Ish"]', '["<and>/ [belonged] to/ each"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1472}/H9028/[H1465]', 'inflected', 'heb', 'גְּוִיָּה', '["gᵉvîyâh"]', '["bodies/ their"]', '["n-f"]', 'a body, whether alive or dead (dead) body, carcase, corpse.', 'prolonged for 1465;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5975G}/H9048/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["when/ stood still/ they"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3671}/H9029/[H3670]', 'inflected', 'heb', 'כָּנָף', '["kânâph"]', '["wings/ their"]', '["n-f"]', 'an edge or extremity; specifically (of a bird or army) a wing, (of a garment or bedclothing) a flap, (of the earth) a quarter, (of a building) a pinnacle bird, border, corner, end, feather(-ed), × flying, (one an-) other, overspreading, × quarters, skirt, × sort, uttermost part, wing(-ed).', 'from 3670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2830>', 'opaque', 'heb', 'חַשְׁמַל', '["chashmal"]', '["a shining substance"]', '["n-m"]', 'probably bronze or polished spectrum metal amber.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004O}/[H1129]', 'lemma', 'heb', 'בַּיִת', '["bayith"]', '["within"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5051}/[H5050]', 'inflected', 'heb', 'נֹגַהּ', '["nôgahh"]', '["the/ brightness"]', '["n-f"]', 'brilliancy (literally or figuratively) bright(-ness), light, (clear) shining.', 'from 5050;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5975G}/H9030/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["and/ he made stand/ me","and/ it made stand up/ me"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4775}/[H4775]', 'inflected', 'heb', 'מָרַד', '["mârad"]', '["<the>/ rebellious","those/ [who] rebel"]', '["v"]', 'to rebel rebel(-lious).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1121G}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ the/ children"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1697G}/H9028/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["and/ from/ words/ their"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5621>', 'opaque', 'heb', 'סָרָב', '["çârâb"]', '["nettles"]', '["n-m"]', 'a thistle brier.', 'from an unused root meaning to sting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5544}/[H5541]', 'inflected', 'heb', 'סִלּוֹן', '["çillôwn"]', '["and/ thorns"]', '["n-m"]', 'a prickle (as if pendulous) brier, thorn.', 'or סַלּוֹן; from 5541;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6137>', 'opaque', 'heb', 'עַקְרָב', '["ʻaqrâb"]', '["scorpions"]', '["n-m"]', 'a scorpion; figuratively, a scourge or knotted whip scorpion.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1697G}/H9028/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["from/ words/ their"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6440H}/H9028/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["and/ from/ faces/ their"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4805H}/[H4784]', 'inflected', 'heb', 'מְרִי', '["mᵉrîy"]', '["<the>/ rebellion"]', '["n-m"]', 'bitterness, i.e. (figuratively) rebellion; concretely, bitter, or rebellious bitter, (most) rebel(-lion, -lious).', 'from 4784;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1958}\/[H5092]', 'inflected', 'heb', 'הִי', '["hîy"]', '["and/ wailing"]', '["n-m"]', 'lamentation woe. (For hiyr. See 1931, 1932.)', 'for 5092;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0398}/H9030/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["and/ he caused to eat/ me"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0990G>/H9021', 'opaque', 'heb', 'בֶּטֶן', '["beṭen"]', '["belly/ your"]', '["n-f"]', 'the belly, especially the womb; also the bosom or body of anything belly, body, as they be born, within, womb.', 'from an unused root probably meaning to be hollow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4578>/H9021', 'inflected', 'heb', 'ומעיך', '["u./me.''Ei./kha"]', '["and/ inward parts/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0398}/H9012/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["and/ I ate [it]/ !"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H1706>', 'inflected', 'heb', 'כדבש', '["ki/d.Vash"]', '["like/ honey"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4966}\/[H4985]', 'inflected', 'heb', 'מָתוֹק', '["mâthôwq"]', '["to/ sweet"]', '["a"]', 'sweet sweet(-er, -ness).', 'or מָתוּק; from 4985;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1697G}/H9020/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["with/ words/ my"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3956H}/[H3960]', 'lemma', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["[the] tongues of","tongue"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4696>/H9021', 'opaque', 'heb', 'מֵצַח', '["mêtsach"]', '["forehead/ your"]', '["n-m"]', 'the forehead (as open and prominent) brow, forehead, impudent.', 'from an unused root meaning to be clear, i.e. conspicuous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4696>/H9028', 'opaque', 'heb', 'מֵצַח', '["mêtsach"]', '["forehead/ their"]', '["n-m"]', 'the forehead (as open and prominent) brow, forehead, impudent.', 'from an unused root meaning to be clear, i.e. conspicuous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8068}/[H8104]', 'inflected', 'heb', 'שָׁמִיר', '["shâmîyr"]', '["like/ diamond"]', '["n-m"]', 'a thorn; also (from its keenness for scratching) a gem, probably the diamond adamant (stone), brier, diamond.', 'from 8104 in the original sense of pricking;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6864}/[H6696]', 'inflected', 'heb', 'צֹר', '["tsôr"]', '["more than/ flint"]', '["n-m"]', 'a stone (as if pressed hard or to a point); (by implication, of use) a knife flint, sharp stone.', 'from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6440H}/H9028/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["from/ faces/ their"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0241G}/H9021/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["and/ with/ ears/ your"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5375G}/H9030/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ it lifted up/ me"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3947G}/H9030/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["and/ he took/ me","and/ it took/ me"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8512}/[H8510]', 'lemma', 'heb', 'תֵּל אָבִיב', '["Têl ʼÂbîyb"]', '["Abib","Tel"]', '["n-pr-loc"]', 'Tel-Abib, a place in Chaldaea Tel-abib.', 'from 8510 and 24; mound of green growth;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0559}/H9040/[H559]', 'inflected', 'heb', 'אָמַר', '["ʼâmar"]', '["when/ say/ I"]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2094B}/H9033/[H2094]', 'inflected', 'heb', 'זָהַר', '["zâhar"]', '["you have warned/ him","you warned/ him"]', '["v"]', 'to gleam; figuratively, to enlighten (by caution) admonish, shine, teach, (give) warn(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2421}/H9033/[H2331]', 'inflected', 'heb', 'חָיָה', '["châyâh"]', '["to/ preserve alive/ him"]', '["v"]', 'to live, whether literally or figuratively; causatively, to revive keep (leave, make) alive, × certainly, give (promise) life, (let, suffer to) live, nourish up, preserve (alive), quicken, recover, repair, restore (to life), revive, (× God) save (alive, life, lives), × surely, be whole.', 'a primitive root (compare 2331, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1818}/H9023/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["and/ blood/ his","and/ blood<s>/ his"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7562}/H9023/[H7561]', 'inflected', 'heb', 'רֶשַׁע', '["reshaʻ"]', '["from/ wickedness/ his"]', '["n-m"]', 'a wrong (especially moral) iniquity, wicked(-ness).', 'from 7561;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1870G}/H9023/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["and/ from/ way/ his"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5337}\/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["you have delivered"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7725O}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ when/ turns away","and/ when/ turns back"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6664G}/H9023/[H6663]', 'inflected', 'heb', 'צֶדֶק', '["tsedeq"]', '["from/ righteousness/ his"]', '["n-m"]', 'the right (natural, moral or legal); also (abstractly) equity or (figuratively) prosperity × even, (× that which is altogether) just(-ice), (un-)right(-eous) (cause, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2403B}/H9023/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["for/ sin/ his"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1237K}/[H1234]', 'inflected', 'heb', 'בִּקְעָה', '["biqʻâh"]', '["the/ plain","the/ valley"]', '["n-f"]', 'properly, a split, i.e. a wide level valley between mountains plain, valley.', 'from 1234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0631}/H9031/[H631]', 'inflected', 'heb', 'אָסַר', '["ʼâçar"]', '["and/ they will bind/ you"]', '["v"]', 'to yoke or hitch; by analogy, to fasten in any sense, to join battle bind, fast, gird, harness, hold, keep, make ready, order, prepare, prison(-er), put in bonds, set in array, tie.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0481}/[H481]', 'inflected', 'heb', 'אָלַם', '["ʼâlam"]', '["and/ I was dumb","and/ you will be dumb"]', '["v"]', 'to tie fast; hence (of the mouth) to be tongue-tied bind, be dumb, put to silence.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1696G}/H9040/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["and/ when/ speak/ I"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2310}/[H2308]', 'inflected', 'heb', 'חָדֵל', '["châdêl"]', '["and/ the/ [person] who refrains"]', '["a"]', 'vacant, i.e. ceasing or destitute he that forbeareth, frail, rejected.', 'from 2308;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2710}/[H2710]', 'inflected', 'heb', 'חָקַק', '["châqaq"]', '["and/ you will inscribe"]', '["v"]', 'properly, to hack, i.e. engrave (Judges 5:14, to be a scribe simply); by implication, to enact (laws being cut in stone or metal tablets in primitive times) or (gen.) prescribe appoint, decree, governor, grave, lawgiver, note, pourtray, print, set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6654>/H9021', 'opaque', 'heb', 'צַד', '["tsad"]', '["side/ your"]', '["n-m"]', 'a side; figuratively, an adversary (be-) side.', 'contr. from an unused root meaning to sidle off;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3615G}/H9041/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["completing/ you"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4692}/H9021/[H6696]', 'inflected', 'heb', 'מָצוֹר', '["mâtsôwr"]', '["siege/ your"]', '["n-m"]', 'something hemming in, i.e. (objectively) a mound (of besiegers), (abstractly) a siege, (figuratively) distress; or (subjectively) a fastness besieged, bulwark, defence, fenced, fortress, siege, strong (hold), tower.', 'or מָצוּר; from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1764>', 'inflected', 'heb', 'ודחן', '["ve./Do.chan"]', '["and/ millet"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3978}/H9021/[H398]', 'inflected', 'heb', 'מַאֲכָל', '["maʼăkâl"]', '["and/ food/ your"]', '["n-m"]', 'an eatable (includ. provender, flesh and fruit) food, fruit, (bake-)meat(-s), victual.', 'from 398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4946}/[H8254]', 'inflected', 'heb', 'מִשְׁקוֹל', '["mishqôwl"]', '["by/ weight"]', '["n-m"]', 'weight weight.', 'from 8254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H4884>', 'inflected', 'heb', 'במשורה', '["bi/m.su.Rah"]', '["by/ measure"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5692}/[H5746]', 'inflected', 'heb', 'עֻגָּה', '["ʻuggâh"]', '["and/ a bread cake of"]', '["n-f"]', 'an ashcake (as round) cake (upon the hearth).', 'from 5746;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1561}/[H1557]', 'inflected', 'heb', 'גֵּלֶל', '["gêlel"]', '["in/ [the] dung<s> of"]', '["n-m"]', 'dung (plural balls of dung) dung.', 'a variation of 1557;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5746}/H9039/[H5692]', 'inflected', 'heb', 'עוּג', '["ʻûwg"]', '["you will bake/ it"]', '["v"]', 'to bake (round cakes on the hearth) bake.', 'a primitive root; properly, to gyrate; but used only as a denominative from 5692,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5869H}/H9028\/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["to/ eyes/ their"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3899H}/H9028/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["bread/ their","food/ their"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5038}/[H5034]', 'inflected', 'heb', 'נְבֵלָה', '["nᵉbêlâh"]', '["and/ a carcass"]', '["n-f"]', 'a flabby thing, i.e. a carcase or carrion (human or bestial, often collectively); figuratively, an idol (dead) body, (dead) carcase, dead of itself, which died, (beast) that (which) dieth of itself.', 'from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6292>\', 'opaque', 'heb', 'פִּגּוּל', '["piggûwl"]', '["unclean meat"]', '["n-m"]', 'properly, fetid, i.e. (figuratively) unclean (ceremonially) abominable(-tion, thing).', 'or פִּגֻּל; from an unused root meaning to stink;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6832}/[H6848]', 'lemma', 'heb', 'צְפוּעַ', '["tsᵉphûwaʻ"]', '["[the] dung<s> of"]', '["n-m"]', 'excrement (as protruded) dung.', 'from the same as 6848;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1561}/[H1557]', 'lemma', 'heb', 'גֵּלֶל', '["gêlel"]', '["[the] dung<s> of"]', '["n-m"]', 'dung (plural balls of dung) dung.', 'a variation of 1557;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1674}/[H1672]', 'inflected', 'heb', 'דְּאָגָה', '["dᵉʼâgâh"]', '["and/ in/ anxiety"]', '["n-f"]', 'anxiety care(-fulness), fear, heaviness, sorrow.', 'from 1672;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8078}/[H8074]', 'inflected', 'heb', 'שִׁמָּמוֹן', '["shimmâmôwn"]', '["and/ in/ horror"]', '["n-m"]', 'stupefaction astonishment.', 'from 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5771I}/H9028\/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["in/ iniquity/ their"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1532>', 'inflected', 'heb', 'הגלבים', '["ha./ga.la.Vim"]', '["<the>/ barbers"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4692}/[H6696]', 'inflected', 'heb', 'מָצוֹר', '["mâtsôwr"]', '["the/ siege"]', '["n-m"]', 'something hemming in, i.e. (objectively) a mound (of besiegers), (abstractly) a siege, (figuratively) distress; or (subjectively) a fastness besieged, bulwark, defence, fenced, fortress, siege, strong (hold), tower.', 'or מָצוּר; from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3671}/H9021/[H3670]', 'inflected', 'heb', 'כָּנָף', '["kânâph"]', '["in/ skirts/ your"]', '["n-f"]', 'an edge or extremity; specifically (of a bird or army) a wing, (of a garment or bedclothing) a flap, (of the earth) a quarter, (of a building) a pinnacle bird, border, corner, end, feather(-ed), × flying, (one an-) other, overspreading, × quarters, skirt, × sort, uttermost part, wing(-ed).', 'from 3670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5439G}/H9034/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["and/ [are] around/ it"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7564}/[H7562]', 'inflected', 'heb', 'רִשְׁעָה', '["rishʻâh"]', '["to/ wickedness"]', '["n-f"]', 'wrong (especially moral) fault, wickedly(-ness).', 'feminine of 7562;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1995B}/H9026/[H1993]', 'inflected', 'heb', 'הָמוֹן', '["hâmôwn"]', '["tumult/ your"]', '["n-m"]', 'a noise, tumult, crowd; also disquietude, wealth abundance, company, many, multitude, multiply, noise, riches, rumbling, sounding, store, tumult.', 'or הָמֹן; (Ezekiel 5:7), from 1993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H4941G}/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["and/ according to/ [the] judgments of"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8441}/H9022\/[H8581]', 'inflected', 'heb', 'תּוֹעֵבַה', '["tôwʻêbah"]', '["abominations/ your"]', '["n-f"]', 'properly, something disgusting (morally), i.e. (as noun) an abhorrence; especially idolatry or (concretely) an idol abominable (custom, thing), abomination.', 'or תֹּעֵבַה; feminine active participle of 8581;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7611}/H9022/[H7604]', 'inflected', 'heb', 'שְׁאֵרִית', '["shᵉʼêrîyth"]', '["[the] rest of/ you"]', '["n-f"]', 'a remainder or residual (surviving, final) portion that had escaped, be left, posterity, remain(-der), remnant, residue, rest.', 'from 7604;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7307H}\/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["wind"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8441}/H9022/[H8581]', 'inflected', 'heb', 'תּוֹעֵבַה', '["tôwʻêbah"]', '["abominations/ your"]', '["n-f"]', 'properly, something disgusting (morally), i.e. (as noun) an abhorrence; especially idolatry or (concretely) an idol abominable (custom, thing), abomination.', 'or תֹּעֵבַה; feminine active participle of 8581;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7992}/H9022/[H7969]', 'inflected', 'heb', 'שְׁלִישִׁי', '["shᵉlîyshîy"]', '["<the> third [part] of/ you"]', '["a"]', 'third; feminine a third (part); by extension, a third (day, year or time); specifically, a third-story cell) third (part, rank, time), three (years old).', 'ordinal from 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3615J}/H9040/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["when/ complete/ I"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5414I}/H9032/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I will make/ you"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1422}/[H1442]', 'inflected', 'heb', 'גְּדוּפָה', '["gᵉdûwphâh"]', '["and/ a taunt"]', '["n-f"]', 'a revilement taunt.', 'feminine passive participle of 1442;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4923}/[H8074]', 'inflected', 'heb', 'מְשַׁמָּה', '["mᵉshammâh"]', '["and/ a horror","and/ a waste"]', '["n-f"]', 'a waste or amazement astonishment, desolate.', 'from 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6213A}/H9040/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["when/ bring about/ I","when/ do/ I"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8433B}/[H3198]', 'inflected', 'heb', 'תּוֹכֵחָה', '["tôwkêchâh"]', '["and/ with/ rebukes of"]', '["n-f"]', 'chastisement; figuratively (by words) correction, refutation, proof (even in defence) argument, × chastened, correction, reasoning, rebuke, reproof, × be (often) reproved.', 'and תּוֹכַחַת; from 3198;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7843}/H9036/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["to/ destroy/ you"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7921A}/H9032/[H7921]', 'inflected', 'heb', 'שָׁכֹל', '["shâkôl"]', '["and/ they will make childless/ you"]', '["v"]', 'properly, to miscarry, i.e. suffer abortion; by analogy, to bereave (literally or figuratively) bereave (of children), barren, cast calf (fruit, young), be (make) childless, deprive, destroy, × expect, lose children, miscarry, rob of children, spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1389I}/[H1387]', 'inflected', 'heb', 'גִּבְעָה', '["gibʻâh"]', '["and/ to the/ hills"]', '["n-f"]', 'a hillock hill, little hill.', 'feminine from the same as 1387;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0650}/[H622]', 'inflected', 'heb', 'אָפִיק', '["ʼâphîyq"]', '["to the/ ravines"]', '["n-m"]', 'properly, containing, i.e. a tube; also a bed or valley of a stream; also a strong thing or a hero brook, channel, mighty, river, scale, stream, strong piece.', 'from 622;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1516R}/[H1466]', 'inflected', 'heb', 'גַּיְא', '["gayʼ"]', '["and/ to the/ valleys"]', '["n"]', 'a gorge (from its lofty sides; hence, narrow, but not a gully or winter-torrent) valley.', 'or (shortened) גַּי; probably (by transmutation) from the same root as 1466 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2491A}/H9026/[H2490]', 'inflected', 'heb', 'חָלָל', '["châlâl"]', '["slain [ones]/ your"]', '["n-m"]', 'pierced (especially to death); figuratively, polluted kill, profane, slain (man), × slew, (deadly) wounded.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0816}/[H816]', 'inflected', 'heb', 'אָשַׁם', '["ʼâsham"]', '["and/ they may be held guilty"]', '["v"]', 'to be guilty; by implication to be punished or perish × certainly, be(-come, made) desolate, destroy, × greatly, be(-come, found, hold) guilty, offend (acknowledge offence), trespass.', 'or אָשֵׁם; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2219}/H9046/[H2114]', 'inflected', 'heb', 'זָרָה', '["zârâh"]', '["when/ are dispersed/ you"]', '["v"]', 'to toss about; by implication, to diffuse, winnow cast away, compass, disperse, fan, scatter (away), spread, strew, winnow.', 'a primitive root (compare 2114);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6412A}/H9026/[H6403]', 'inflected', 'heb', 'פָּלִיט', '["pâlîyṭ"]', '["escapees/ your"]', '["n-m"]', 'a refugee (that have) escape(-d, -th), fugitive.', 'or פָּלֵיט; or פָּלֵט; from 6403;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6962}/[H6962]', 'inflected', 'heb', 'קוּט', '["qûwṭ"]', '["and/ they will loathe","and/ you will loathe"]', '["v"]', 'properly, to cut off, i.e. (figuratively) detest begrieved, loathe self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6440L}/H9028/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<in>/ faces/ their"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3709G}/H9021/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["with/ hand/ your"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7554}/[H7554]', 'inflected', 'heb', 'רָקַע', '["râqaʻ"]', '["and/ stamp"]', '["v"]', 'to pound the earth (as a sign of passion); by analogy to expand (by hammering); by implication, to overlay (with thin sheets of metal) beat, make broad, spread abroad (forth, over, out, into plates), stamp, stretch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0253}/[H162]', 'lemma', 'heb', 'אָח', '["ʼâch"]', '["alas!"]', '["inj"]', 'Oh! (expressive of grief or surprise) ah, alas.', 'a variation for 162;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5341}/[H5341]', 'inflected', 'heb', 'נָצַר', '["nâtsar"]', '["and/ the/ [one who] is preserved"]', '["v"]', 'to guard, in a good sense (to protect, maintain, obey, etc.) or a bad one (to conceal, etc.) besieged, hidden thing, keep(-er, -ing), monument, observe, preserve(-r), subtil, watcher(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0424}/[H352]', 'lemma', 'heb', 'אֵלָה', '["ʼêlâh"]', '["terebinth"]', '["n-f"]', 'an oak or other strong tree elm, oak, teil-tree.', 'feminine of 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1689}/H9011/[H7247]', 'inflected', 'heb', 'דִּבְלָה', '["Diblâh"]', '["Diblah/ <towards>"]', '["n-pr-loc"]', 'Diblah, a place in Syria Diblath.', 'probably an orthographical error for 7247;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8199}/H9032/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["and/ I will judge/ you","and/ they will judge/ you"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1870G}/H9022/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["according to/ ways/ your"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8441}/H9022/[H8581]', 'inflected', 'heb', 'תּוֹעֵבַה', '["tôwʻêbah"]', '["and/ abominations/ your"]', '["n-f"]', 'properly, something disgusting (morally), i.e. (as noun) an abhorrence; especially idolatry or (concretely) an idol abominable (custom, thing), abomination.', 'or תֹּעֵבַה; feminine active participle of 8581;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6843}/[H6842]', 'inflected', 'heb', 'צְפִירָה', '["tsᵉphîyrâh"]', '["<the>/ doom"]', '["n-f"]', 'a crown (as encircling the head); also a turn of affairs (i.e. mishap) diadem, morning.', 'feminine formed like 6842;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1906}/[H1959]', 'lemma', 'heb', 'הֵד', '["hêd"]', '["a shout of joy"]', '["n-m"]', 'a shout sounding again.', 'for 1959;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2087}/[H2102]', 'inflected', 'heb', 'זָדוֹן', '["zâdôwn"]', '["<the>/ arrogance"]', '["n-m"]', 'arrogance presumptuously, pride, proud (man).', 'from 2102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2555}/[H2554]', 'inflected', 'heb', 'חָמָס', '["châmâç"]', '["<the>/ violence","the/ violence"]', '["n-m"]', 'violence; by implication, wrong; by metonymy unjust gain cruel(-ty), damage, false, injustice, × oppressor, unrighteous, violence (against, done), violent (dealing), wrong.', 'from 2554;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1995A}/H9028/[H1993]', 'inflected', 'heb', 'הָמוֹן', '["hâmôwn"]', '["any of/ multitude/ their"]', '["n-m"]', 'a noise, tumult, crowd; also disquietude, wealth abundance, company, many, multitude, multiply, noise, riches, rumbling, sounding, store, tumult.', 'or הָמֹן; (Ezekiel 5:7), from 1993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1991}/H9028/[H1993]', 'inflected', 'heb', 'הֵם', '["hêm"]', '["any of/ noise/ their"]', '["n-m"]', 'abundance, i.e. wealth any of theirs.', 'from 1993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5089>', 'opaque', 'heb', 'נֹהַּ', '["nôahh"]', '["distinction"]', '["n-m"]', 'lamentation wailing.', 'from an unused root meaning to lament;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4376}/[H4376]', 'inflected', 'heb', 'מָכַר', '["mâkar"]', '["and/ the/ seller"]', '["v"]', 'to sell, literally (as merchandise, a daughter in marriage, into slavery), or figuratively (to surrender) × at all, sell (away, -er, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1995A}/H9024/[H1993]', 'inflected', 'heb', 'הָמוֹן', '["hâmôwn"]', '["multitude/ its","multitudes/ its","wealth/ its"]', '["n-m"]', 'a noise, tumult, crowd; also disquietude, wealth abundance, company, many, multitude, multiply, noise, riches, rumbling, sounding, store, tumult.', 'or הָמֹן; (Ezekiel 5:7), from 1993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4465}/[H4376]', 'inflected', 'heb', 'מִמְכָּר', '["mimkâr"]', '["the/ thing sold"]', '["n-m"]', 'merchandise; abstractly, a selling × ought, (that which cometh of) sale, that which...sold, ware.', 'from 4376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8619}/[H8628]', 'inflected', 'heb', 'תָּקוֹעַ', '["tâqôwaʻ"]', '["on the/ trumpet"]', '["n-m"]', 'a trumpet trumpet.', 'from 8628 (in the musical sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2740}/H9020/[H2734]', 'inflected', 'heb', 'חָרוֹן', '["chârôwn"]', '["anger/ my"]', '["n-m"]', 'a burning of anger sore displeasure, fierce(-ness), fury, (fierce) wrath(-ful).', 'or (shortened) חָרֹן; from 2734;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6403}/[H6403]', 'inflected', 'heb', 'פָּלַט', '["pâlaṭ"]', '["and/ they will escape"]', '["v"]', 'to slip out, i.e. escape; causatively, to deliver calve, carry away safe, deliver, (cause to) escape.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6412A}/H9028/[H6403]', 'inflected', 'heb', 'פָּלִיט', '["pâlîyṭ"]', '["escapees/ their"]', '["n-m"]', 'a refugee (that have) escape(-d, -th), fugitive.', 'or פָּלֵיט; or פָּלֵט; from 6403;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5337}/H9038/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["to/ deliver/ them"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4578>/H9028', 'inflected', 'heb', 'ומעיהם', '["u./me.''ei./Hem"]', '["and/ inward parts/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6643A}/[H6638]', 'inflected', 'heb', 'צְבִי', '["tsᵉbîy"]', '["and/ [the] beauty of"]', '["n-m"]', 'splendor (as conspicuous) beautiful(-ty), glorious (-ry), goodly, pleasant, roe(-buck).', 'from 6638 in the sense of prominence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2114A}/[H2114]', 'inflected', 'heb', 'זוּר', '["zûwr"]', '["the/ strangers"]', '["v"]', 'to turn aside (especially for lodging); hence to be a foreigner, strange, profane; specifically (active participle) to commit adultery (come from) another (man, place), fanner, go away, (e-) strange(-r, thing, woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2490H}/H9033/[H2470]', 'inflected', 'heb', 'חָלַל', '["châlal"]', '["and/ they will profane/ it"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6845}/H9020/[H6845]', 'inflected', 'heb', 'צָפַן', '["tsâphan"]', '["treasured [place]/ my"]', '["v"]', 'to hide (by covering over); by implication, to hoard or reserve; figuratively to deny; specifically (favorably) to protect, (unfavorably) to lurk esteem, hide(-den one, self), lay up, lurk (be set) privily, (keep) secret(-ly, place).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2490H}/H9034\/[H2470]', 'inflected', 'heb', 'חָלַל', '["châlal"]', '["and/ they will profane/ it"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7569}/[H7576]', 'inflected', 'heb', 'רַתּוֹק', '["rattôwq"]', '["the/ chain"]', '["n-m"]', 'a chain chain.', 'from 7576;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7089}/[H7088]', 'lemma', 'heb', 'קְפָדָה', '["qᵉphâdâh"]', '["anguish"]', '["n-f"]', 'shrinking, i.e., terror destruction.', 'from 7088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4941G}/H9028/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["and/ by/ judgments/ their"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8345}/[H8337]', 'inflected', 'heb', 'שִׁשִּׁי', '["shishshîy"]', '["in the/ sixth [month]"]', '["n"]', 'sixth, ordinal or (feminine) fractional sixth (part).', 'from 8337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H4975>/H9023', 'inflected', 'heb', 'וממתניו', '["u./mi./ma.te.Na/v"]', '["and/ [was] from/ hips/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2096}/[H2094]', 'lemma', 'heb', 'זֹהַר', '["zôhar"]', '["brightness"]', '["n-m"]', 'brilliancy brightness.', 'from 2094;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H2830>/H9011', 'inflected', 'heb', 'החשמלה', '["ha./chash.Ma.la/h"]', '["<the>/ shining substance/ towards"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6734}/[H6731]', 'inflected', 'heb', 'צִיצִת', '["tsîytsith"]', '["by/ [the] hair of"]', '["n-f"]', 'a floral or wing-like projection, i.e. a fore-lock of hair, a tassel fringe, lock.', 'feminine of 6731;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7065}/[H7065]', 'inflected', 'heb', 'קָנָא', '["qânâʼ"]', '["which/ provokes to jealousy"]', '["v"]', 'to be (causatively, make) zealous, i.e. (in a bad sense) jealous or envious (be) envy(-ious), be (move to, provoke to) jealous(-y), × very, (be) zeal(-ous).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0872}/[H935]', 'inflected', 'heb', 'בְּאָה', '["bᵉʼâh"]', '["[was] in the/ entrance"]', '["n-f"]', 'an entrance to a building entry.', 'from 935;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4100}/{H1992}/[H4100]', 'inflected', 'heb', 'מָה', '["mâh"]', '["what/ [are] they?"]', '["i"]', 'properly, interrogative what? (including how? why? when?); but also exclamation, what! (including how!), or indefinitely what (including whatever, and even relatively, that which); often used with prefixes in various adverbial or conjunctive senses how (long, oft, (-soever)), (no-) thing, what (end, good, purpose, thing), whereby(-fore, -in, -to, -with), (for) why.', 'or מַה; or מָ; or מַ; also מֶה; a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2864}/[H2864]', 'inflected', 'heb', 'חָתַר', '["châthar"]', '["and/ I dug","and/ they rowed"]', '["v"]', 'to force a passage, as by burglary; figuratively, with oars dig (through), row.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1544}/[H1556]', 'lemma', 'heb', 'גִּלּוּל', '["gillûwl"]', '["[the] idols of","idols"]', '["n-m"]', 'properly, a log (as round); by implication, an idol idol.', 'or (shortened) גִּלֻּל; from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2970H}/[H238]', 'inflected', 'heb', 'יַאֲזַנְיָה', '["Yaʼăzanyâh"]', '["and/ Jaazaniah"]', '["n-pr-m"]', 'Jaazanjah, the name of four Israelites Jaazaniah. Compare 3153.', 'or יַאֲזַנְיָהוּ; from 238 and 3050; heard of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8227G}/[H8226]', 'lemma', 'heb', 'שָׁפָן', '["shâphân"]', '["Shaphan"]', '["n-m n-pr-m"]', 'a species of rock-rabbit (from its hiding), i.e. probably the hyrax coney.', 'from 8226;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4730}/H9023/[H4729]', 'inflected', 'heb', 'מִקְטֶרֶת', '["miqṭereth"]', '["censer/ his"]', '["n-f"]', 'something to fume (incense) in, i.e. a coal-pan censer.', 'feminine of 4729;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6282B}/[H6280]', 'inflected', 'heb', 'עָתָר', '["ʻâthâr"]', '["and/ [the] fragrance of"]', '["n-m"]', 'incense (as increasing to a volume of smoke); hence a worshipper suppliant, thick.', 'from 6280; also compare 6279');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4906}/H9023/[H7906]', 'inflected', 'heb', 'מַשְׂכִּית', '["maskîyth"]', '["carved image/ his"]', '["n-f"]', 'a figure (carved on stone, the wall, or any object); figuratively, imagination conceit, image(-ry), picture, × wish.', 'from the same as 7906;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6828G}/H9011/[H6845]', 'inflected', 'heb', 'צָפוֹן', '["tsâphôwn"]', '["<the>/ north/ -ward","the/ north/ towards"]', '["n-f"]', 'properly, hidden, i.e. dark; used only of the north as a quarter (gloomy and unknown) north(-ern, side, -ward, wind).', 'or צָפֹן; from 6845;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H8542>\', 'inflected', 'heb', 'התמוז ס', '["ha./ta.Muz"]', '["<the>/ Tammuz"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2156}/[H2168]', 'inflected', 'heb', 'זְמוֹרָה', '["zᵉmôwrâh"]', '["the/ branch","the/ vine branch"]', '["n"]', 'a twig (as pruned) vine, branch, slip.', 'or זְמֹרָה (feminine); and זְמֹר (masculine); from 2168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0639H}/H9028/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["nose/ their"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4892}/H9023/[H4889]', 'inflected', 'heb', 'מַשְׁחֵת', '["mashchêth"]', '["destruction/ his"]', '["n-m"]', 'destruction destroying.', 'for 4889;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4660}/H9023/[H5310]', 'inflected', 'heb', 'מַפָּץ', '["mappâts"]', '["shattering/ his"]', '["n-m"]', 'a smiting to pieces slaughter.', 'from 5310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7083}/[H3563]', 'inflected', 'heb', 'קֶסֶת', '["qeçeth"]', '["and/ [the] writing-case of"]', '["n-f"]', 'properly, a cup, i.e. an ink-stand inkhorn.', 'from the same as 3563 (or as 7185);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3847}/[H3847]', 'inflected', 'heb', 'לָבַשׁ', '["lâbash"]', '["those/ [who] are clothed","who/ was clothed"]', '["v"]', 'properly, wrap around, i.e. (by implication) to put on a garment or clothe (oneself, or another), literally or figuratively (in) apparel, arm, array (self), clothe (self), come upon, put (on, upon), wear.', 'or לָבֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7083}/[H3563]', 'lemma', 'heb', 'קֶסֶת', '["qeçeth"]', '["<the> writing-case of"]', '["n-f"]', 'properly, a cup, i.e. an ink-stand inkhorn.', 'from the same as 3563 (or as 7185);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H4975>/H9023\', 'inflected', 'heb', 'במתניו ס', '["be./ma.te.Na/v"]', '["[was] at/ hips/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8420}/[H8427]', 'lemma', 'heb', 'תָּו', '["tâv"]', '["a mark"]', '["n-m"]', 'a mark; by implication, a signature desire, mark.', 'from 8427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0584}/[H584]', 'inflected', 'heb', 'אָנַח', '["ʼânach"]', '["who/ sigh"]', '["v"]', 'to sigh groan, mourn, sigh.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0602}/[H602]', 'inflected', 'heb', 'אָנַק', '["ʼânaq"]', '["and/ who/ groan"]', '["v"]', 'to shriek cry, groan.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8420}/[H8427]', 'inflected', 'heb', 'תָּו', '["tâv"]', '["the/ mark"]', '["n-m"]', 'a mark; by implication, a signature desire, mark.', 'from 8427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4720}/H9020/[H6942]', 'inflected', 'heb', 'מִקְדָּשׁ', '["miqdâsh"]', '["and/ from/ sanctuary/ my"]', '["n-m"]', 'a consecrated thing or place, especially, a palace, sanctuary (whether of Jehovah or of idols) or asylum chapel, hallowed part, holy place, sanctuary.', 'or מִקְּדָשׁ; (Exodus 15:17), from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5221}/H9048/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["when/ were striking/ they"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7604}/[H7604]', 'inflected', 'heb', 'שָׁאַר', '["shâʼar"]', '["and/ [was] remaining"]', '["v"]', 'properly, to swell up, i.e. be (causatively, make) redundant leave, (be) left, let, remain, remnant, reserve, the rest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5307G}/H9012/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["and/ I fell/ !"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8210G}/H9041/[H8210]', 'inflected', 'heb', 'שָׁפַךְ', '["shâphak"]', '["when/ pouring out/ you"]', '["v"]', 'to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4297}/[H5186]', 'lemma', 'heb', 'מֻטֶּה', '["muṭṭeh"]', '["perverseness"]', '["n-m"]', 'a stretching, i.e. distortion (figuratively, iniquity) perverseness.', 'from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7083}/[H3563]', 'inflected', 'heb', 'קֶסֶת', '["qeçeth"]', '["the/ writing-case"]', '["n-f"]', 'properly, a cup, i.e. an ink-stand inkhorn.', 'from the same as 3563 (or as 7185);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3605}/ /{H0834A}/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["according to/ all/ /that"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6680}/H9030\/[H6680]', 'inflected', 'heb', 'צָוָה', '["tsâvâh"]', '["you commanded/ me"]', '["v"]', '(intensively) to constitute, enjoin appoint, (for-) bid, (give a) charge, (give a, give in, send with) command(-er, -ment), send a messenger, put, (set) in order.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1534}/[H1556]', 'inflected', 'heb', 'גַּלְגַּל', '["galgal"]', '["<to> the/ wheel"]', '["n-m"]', 'a wheel; by analogy, a whirlwind; also dust (as whirled) heaven, rolling thing, wheel.', 'by reduplication from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3742>', 'inflected', 'heb', 'לכרובים', '["la./ke.Ruv","la./ke.ru.Vim","li/kh.Ruv"]', '["<to> the/ cherub","<to> the/ cherubim","[belonged] to the/ cherub","and/ a cherub","to the/ cherubim"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2651>/H9021', 'opaque', 'heb', 'חֹפֶן', '["chôphen"]', '["cupped hands/ your"]', '["n-m"]', 'a fist (only in the dual) fists, (both) hands, hand(-ful).', 'from an unused root of uncertain signification;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2236}/[H2236]', 'inflected', 'heb', 'זָרַק', '["zâraq"]', '["and/ sprinkle [them]"]', '["v"]', 'to sprinkle (fluid or solid particles) be here and there, scatter, sprinkle, strew.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5869J}/H9020/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["to/ eyes/ my"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H3742>', 'inflected', 'heb', 'והכרבים', '["ve./ha./ke.ru.Vim"]', '["and/ the/ cherubim"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2691A}/[H2690]', 'inflected', 'heb', 'חָצֵר', '["châtsêr"]', '["and/ the/ court"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H6963A>', 'inflected', 'heb', 'כקול', '["ke./Kol"]', '["like/ [the] sound of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6680}/H9043/[H6680]', 'inflected', 'heb', 'צָוָה', '["tsâvâh"]', '["when/ commanded/ he"]', '["v"]', '(intensively) to constitute, enjoin appoint, (for-) bid, (give a) charge, (give a, give in, send with) command(-er, -ment), send a messenger, put, (set) in order.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3027H}/H9028/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ hands/ their"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0212>/H9028', 'opaque', 'heb', 'אוֹפָן', '["ʼôwphân"]', '["wheels/ their"]', '["n-m"]', 'a wheel wheel.', 'or (shortened) אֹפָן; from an unused root meaning to revolve;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0212>', 'inflected', 'heb', 'לאופנים', '["la./''o.fa.Nim"]', '["to the/ wheels"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7426}/[H7426]', 'inflected', 'heb', 'רָמַם', '["râmam"]', '["and/ they rose"]', '["v"]', 'to rise (literally or figuratively) exalt, get (oneself) up, lift up (self), mount up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0681}/H9038/[H680]', 'inflected', 'heb', 'אֵצֶל', '["ʼêtsel"]', '["from/ beside/ them"]', '["n-m"]', 'a side; (as a preposition) near at, (hard) by, (from) (beside), near (unto), toward, with. See also 1018.', 'from 680 (in the sense of joining);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7311A}/H9048/[H7311]', 'inflected', 'heb', 'רוּם', '["rûwm"]', '["and/ when/ rose/ they"]', '["v"]', 'to be high actively, to rise or raise (in various applications, literally or figuratively) bring up, exalt (self), extol, give, go up, haughty, heave (up), (be, lift up on, make on, set up on, too) high(-er, one), hold up, levy, lift(-er) up, (be) lofty, (× a-) loud, mount up, offer (up), presumptuously, (be) promote(-ion), proud, set up, tall(-er), take (away, off, up), breed worms.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6931G}/[H6930]', 'inflected', 'heb', 'קַדְמוֹנִי', '["qadmôwnîy"]', '["<the>/ eastern"]', '["a"]', '(of time) anterior or (of place) oriental ancient, they that went before, east, (thing of) old.', 'or קַדְמֹנִי; from 6930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0853}/H9038/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["and/ <obj.>/ them"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6921}/H9011/[H6923]', 'inflected', 'heb', 'קָדִים', '["qâdîym"]', '["[is] east/ -ward","east/ -ward"]', '["n-m"]', 'the fore or front part; hence (by orientation) the East (often adverbially, eastward, for brevity the east wind) east(-ward, wind).', 'or קָדִם; from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2970I}/[H238]', 'lemma', 'heb', 'יַאֲזַנְיָה', '["Yaʼăzanyâh"]', '["Jaazaniah"]', '["n-pr-m"]', 'Jaazanjah, the name of four Israelites Jaazaniah. Compare 3153.', 'or יַאֲזַנְיָהוּ; from 238 and 3050; heard of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5809I}/[H5826]', 'lemma', 'heb', 'עַזּוּר', '["ʻAzzûwr"]', '["Azzur"]', '["n-pr-m"]', 'Azzur, the name of three Israelites Azur, Azzur.', 'or עַזֻּר; from 5826; helpful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6410J}/[H6403]', 'lemma', 'heb', 'פְּלַטְיָה', '["Pᵉlaṭyâh"]', '["Pelatiah"]', '["n-pr-m"]', 'Pelatjah, the name of four Israelites Pelatiah.', 'or פְּלַטְיָהוּ; from 6403 and 3050; Jah has delivered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1141R}/[H1129]', 'lemma', 'heb', 'בְּנָיָה', '["Bᵉnâyâh"]', '["Benaiah"]', '["n-pr-m"]', 'Benajah, the name of twelve Israelites Benaiah.', 'or בּנָיָהוּ; (prolonged) from 1129 and 3050; Jah has built;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2803I}/[H2803]', 'inflected', 'heb', 'חָשַׁב', '["châshab"]', '["who/ plan"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3289}/[H3289]', 'inflected', 'heb', 'יָעַץ', '["yâʻats"]', '["and/ who/ counsel"]', '["v"]', 'to advise; reflexively, to deliberate or resolve advertise, take advise, advise (well), consult, (give, take) counsel(-lor), determine, devise, guide, purpose.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7138}/[H7126]', 'inflected', 'heb', 'קָרוֹב', '["qârôwb"]', '["[is] in/ [the] near [future]"]', '["a"]', 'near (in place, kindred or time) allied, approach, at hand, any of kin, kinsfold(-sman), (that is) near (of kin), neighbour, (that is) next, (them that come) nigh (at hand), more ready, short(-ly).', 'or קָרֹב; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4609A}/[H4608]', 'inflected', 'heb', 'מַעֲלָה', '["maʻălâh"]', '["and/ [the] thoughts of"]', '["n-f"]', 'elevation, i.e. the act (literally, a journey to a higher place, figuratively, a thought arising), or (concretely) the condition (literally, a step or grade-mark, figuratively, a superiority of station); specifically a climactic progression (in certain Psalms) things that come up, (high) degree, deal, go up, stair, step, story.', 'feminine of 4608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7307G}/H9026/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["spirit/ your"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2351>/H9024', 'opaque', 'heb', 'חוּץ', '["chûwts"]', '["streets/ its"]', '["n-m"]', 'properly, separate by a wall, i.e. outside, outdoors abroad, field, forth, highway, more, out(-side, -ward), street, without.', 'or (shortened) חֻץ; (both forms feminine in the plural) from an unused root meaning to sever;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2491A}\/[H2490]', 'inflected', 'heb', 'חָלָל', '["châlâl"]', '["[the] slain"]', '["n-m"]', 'pierced (especially to death); figuratively, polluted kill, profane, slain (man), × slew, (deadly) wounded.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5518A}/[H5518]', 'inflected', 'heb', 'סִיר', '["çîyr"]', '["<into>/ a pot"]', '["n-m"]', 'a pot; also a thorn (as springing up rapidly); by implication, a hook caldron, fishhook, pan, (wash-)pot, thorn.', 'or (feminine) סִירָה; or סִרָה; (Jeremiah 52:18), from a primitive root meaning to boil up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2706G}/H9020/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["in/ statutes/ my"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5012}/H9040/[H5012]', 'inflected', 'heb', 'נָבָא', '["nâbâʼ"]', '["when/ prophesied/ I"]', '["v"]', 'to prophesy, i.e. speak (or sing) by inspiration (in prediction or simple discourse) prophesy(-ing), make self a prophet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6410J}/[H6403]', 'inflected', 'heb', 'פְּלַטְיָה', '["Pᵉlaṭyâh"]', '["and/ Pelatiah"]', '["n-pr-m"]', 'Pelatjah, the name of four Israelites Pelatiah.', 'or פְּלַטְיָהוּ; from 6403 and 3050; Jah has delivered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1353}/H9021/[H1350]', 'inflected', 'heb', 'גְּאֻלָּה', '["gᵉʼullâh"]', '["redemption/ your"]', '["n-f"]', 'redemption (including the right and the object); by implication, relationship kindred, redeem, redemption, right.', 'feminine passive participle of 1350;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4181}\/[H4180]', 'inflected', 'heb', 'מוֹרָשָׁה', '["môwrâshâh"]', '["to/ a possession"]', '["n-f"]', 'a possession heritage, inheritance, possession.', 'feminine of 4180;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7368}/H9038/[H7368]', 'inflected', 'heb', 'רָחַק', '["râchaq"]', '["I have removed far away/ them"]', '["v"]', 'to widen (in any direction), i.e. (intransitively) recede or (transitively) remove (literally or figuratively, of place or relation) (a-, be, cast, drive, get, go, keep (self), put, remove, be too, (wander), withdraw) far (away, off), loose, × refrain, very, (be) a good way (off).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8251}/H9024/[H8262]', 'inflected', 'heb', 'שִׁקּוּץ', '["shiqqûwts"]', '["detestable things/ its"]', '["n-m"]', 'disgusting, i.e. filthy; especially idolatrous or (concretely) an idol abominable filth (idol, -ation), detestable (thing).', 'or שִׁקֻּץ; from 8262;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8441}/H9024/[H8581]', 'inflected', 'heb', 'תּוֹעֵבַה', '["tôwʻêbah"]', '["abominations/ its"]', '["n-f"]', 'properly, something disgusting (morally), i.e. (as noun) an abhorrence; especially idolatry or (concretely) an idol abominable (custom, thing), abomination.', 'or תֹּעֵבַה; feminine active participle of 8581;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0935P}/H9030/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ he brought/ me","and/ it brought/ me"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3778}/H9011/[H3777]', 'inflected', 'heb', 'כַּשְׂדִּי', '["Kasdîy"]', '["Chaldea/ towards"]', '["n-pr-loc n-pr-m"]', 'a Kasdite, or descendant of Kesed; by implication, a Chaldaean (as if so descended); also an astrologer (as if proverbial of that people Chaldeans, Chaldees, inhabitants of Chaldea.', '(occasionally with enclitic) כַּשְׂדִּימָה; towards the Kasdites into Chaldea), patronymically from 3777 (only in the plural);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4758}/[H7200]', 'inflected', 'heb', 'מַרְאֶה', '["marʼeh"]', '["<in> the/ vision","by the/ vision","in the/ vision"]', '["n-m"]', 'a view (the act of seeing); also an appearance (the thing seen), whether (real) a shape (especially if handsome, comeliness; often plural the looks), or (mental) a vision × apparently, appearance(-reth), × as soon as beautiful(-ly), countenance, fair, favoured, form, goodly, to look (up) on (to), look(-eth), pattern, to see, seem, sight, visage, vision.', 'from 7200a;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7200G}/H9030\/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["he had shown/ me"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4725}/H9021/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["from/ place/ your"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4161}/[H3318]', 'inflected', 'heb', 'מוֹצָא', '["môwtsâʼ"]', '["like/ goings out of"]', '["n-m"]', 'a going forth, i.e. (the act) an egress, or (the place) an exit; hence, a source or product; specifically, dawn, the rising of the sun (the East), exportation, utterance, a gate, a fountain, a mine, a meadow (as producing grass) brought out, bud, that which came out, east, going forth, goings out, that which (thing that) is gone out, outgoing, proceeded out, spring, vein, (water-) course (springs).', 'or מֹצָאxlit môtsâ corrected to môtsâʼ; from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H5939>', 'inflected', 'heb', 'בעלטה', '["ba./''a.la.Tah"]', '["in the/ darkness"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4159}/H9026/[H3302]', 'inflected', 'heb', 'מוֹפֵת', '["môwphêth"]', '["[am] sign/ your"]', '["n-m"]', 'a miracle; by implication, a token or omen miracle, sign, wonder(-ed at).', 'or מֹפֵת; from 3302 in the sense of conspicuousness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7568}/H9020/[H3423]', 'inflected', 'heb', 'רֶשֶׁת', '["resheth"]', '["net/ my"]', '["n-f"]', 'a net (as catching animals) net(-work).', 'from 3423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4686A}/H9020/[H4685]', 'inflected', 'heb', 'מָצוּד', '["mâtsûwd"]', '["in/ hunting net/ my"]', '["n-f"]', 'a net, or (abstractly) capture; also a fastness castle, defense, fort(-ress), (strong) hold, be hunted, net, snare, strong place.', 'or (feminine) מְצוּדָה; or מְצֻדָה; for 4685;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5828}/H9023/[H5826]', 'inflected', 'heb', 'עֵזֶר', '["ʻêzer"]', '["help/ his"]', '["n-m"]', 'aid help.', 'from 5826;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0102}/H9023/[H5062]', 'inflected', 'heb', 'אַגָּף', '["ʼaggâph"]', '["troops/ his","troops/ its"]', '["n-m"]', '(only plural) wings of an army, or crowds of troops bands.', 'probably from 5062 (through the idea of impending); a cover or heap; i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6327A}/H9040/[H6327]', 'inflected', 'heb', 'פּוּץ', '["pûwts"]', '["when/ scatter/ I"]', '["v"]', 'to dash in pieces, literally or figuratively (especially to disperse) break (dash, shake) in (to) pieces, cast (abroad), disperse (selves), drive, retire, scatter (abroad), spread abroad.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7458}/[H7456]', 'inflected', 'heb', 'רָעָב', '["râʻâb"]', '["from/ [the] famine"]', '["n-m"]', 'hunger (more or less extensive) dearth, famine, famished, hunger.', 'from 7456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1698}/[H1696]', 'inflected', 'heb', 'דֶּבֶר', '["deber"]', '["and/ from/ [the] pestilence"]', '["n-m"]', 'a pestilence murrain, pestilence, plague.', 'from 1696 (in the sense of destroying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4325G}/H9021/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["and/ water/ your"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7269}/[H7267]', 'inflected', 'heb', 'רׇגְזָה', '["rogzâh"]', '["in/ trembling"]', '["n-f"]', 'trepidation trembling.', 'feminine of 7267;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1674}/[H1672]', 'inflected', 'heb', 'דְּאָגָה', '["dᵉʼâgâh"]', '["in/ anxiety"]', '["n-f"]', 'anxiety care(-fulness), fear, heaviness, sorrow.', 'from 1672;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4325G}/H9028/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["and/ water/ their"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8078}/[H8074]', 'inflected', 'heb', 'שִׁמָּמוֹן', '["shimmâmôwn"]', '["in/ horror"]', '["n-m"]', 'stupefaction astonishment.', 'from 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4393}/H9024/[H4390]', 'inflected', 'heb', 'מְלֹא', '["mᵉlôʼ"]', '["from/ fullness/ its"]', '["n-m"]', 'fulness (literally or figuratively) × all along, × all that is (there-) in, fill, (× that whereof...was) full, fulness, (hand-) full, multitude.', 'rarely מְלוֹא; or מְלוֹ; (Ezekiel 41:8), from 4390;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4911B}/[H4912]', 'lemma', 'heb', 'מָשַׁל', '["mâshal"]', '["[are] speaking a proverb","he will speak a proverb","making a parable","people will use as a proverb","to speak a proverb"]', '["v"]', 'to liken, i.e. (transitively) to use figurative language (an allegory, adage, song or the like); intransitively, to resemble be(-come) like, compare, use (as a) proverb, speak (in proverbs), utter.', 'denominative from 4912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1697J}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["and/ [the] matter of"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4738}/[H7080]', 'inflected', 'heb', 'מִקְסָם', '["miqçâm"]', '["and/ divination of"]', '["n-m"]', 'an augury divination.', 'from 7080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3117G>/H9026', 'inflected', 'heb', 'בימיכם', '["bi./mei./Khem","vi./mei./Khem"]', '["in/ days/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3820A}/H9028/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["from/ own heart/ their"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7307G}/H9028/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["own spirit/ their"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7776}/[H8168]', 'inflected', 'heb', 'שׁוּעָל', '["shûwʻâl"]', '["like/ foxes"]', '["n-m"]', 'a jackal (as a burrower) fox.', 'or שֻׁעָל; from the same as 8168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1443}/[H1443]', 'inflected', 'heb', 'גָּדַר', '["gâdar"]', '["and/ I will wall up","and/ you have walled up"]', '["v"]', 'to wall in or around close up, fence up, hedge, inclose, make up (a wall), mason, repairer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3176H}/[H3176]', 'inflected', 'heb', 'יָחַל', '["yâchal"]', '["and/ they have waited"]', '["v"]', 'to wait; by implication, to be patient, hope (cause to, have, make to) hope, be pained, stay, tarry, trust, wait.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7080}/[H7080]', 'inflected', 'heb', 'קָסַם', '["qâçam"]', '["and/ the/ diviners","and/ who/ divine"]', '["v"]', 'properly, to distribute, i.e. determine by lot or magical scroll; by implication, to divine divine(-r, -ation), prudent, soothsayer, use (divination).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3791}/[H3789]', 'inflected', 'heb', 'כָּתָב', '["kâthâb"]', '["and/ in/ [the] register of"]', '["n-m"]', 'something written, i.e. a writing, record or book register, scripture, writing.', 'from 3789;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2937}/[H2937]', 'lemma', 'heb', 'טָעָה', '["ṭâʻâh"]', '["they have led astray"]', '["v"]', 'to wander; causatively to lead astray seduce.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2434}/[H2351]', 'lemma', 'heb', 'חַיִץ', '["chayits"]', '["a wall"]', '["n-m"]', 'a wall wall.', 'another form for 2351;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8602B>', 'opaque', 'heb', 'תָּפֵל', '["tâphêl"]', '["whitewash"]', '["a"]', 'plaster (as gummy) or slime; (figuratively) frivolity foolish things, unsavoury, untempered.', 'from an unused root meaning to smear;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0417}/[H410]', 'lemma', 'heb', 'אֶלְגָּבִישׁ', '["ʼelgâbîysh"]', '["hail"]', '["n-m"]', 'hail (as if a great pearl) great hail(-stones).', 'from 410 and 1378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2915}/[H2902]', 'inflected', 'heb', 'טִיחַ', '["ṭîyach"]', '["[is] the/ plaster"]', '["n-m"]', 'mortar or plaster daubing.', 'from (the equiv. of) 2902;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2902A}\/[H2902]', 'inflected', 'heb', 'טוּחַ', '["ṭûwach"]', '["you plastered"]', '["v"]', 'to smear, especially with lime daub, overlay, plaister, smut.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5060}/H9033/[H5060]', 'inflected', 'heb', 'נָגַע', '["nâgaʻ"]', '["and/ I will make touch/ it"]', '["v"]', 'properly, to touch, i.e. lay the hand upon (for any purpose; euphemistically, to lie with a woman); by implication, to reach (figuratively, to arrive, acquire); violently, to strike (punish, defeat, destroy, etc.) beat, (× be able to) bring (down), cast, come (nigh), draw near (nigh), get up, happen, join, near, plague, reach (up), smite, strike, touch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3247H}/H9023/[H3245]', 'inflected', 'heb', 'יְסוֹד', '["yᵉçôwd"]', '["foundation[s]/ its"]', '["n-f"]', 'a foundation (literally or figuratively) bottom, foundation, repairing', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2902A}/[H2902]', 'inflected', 'heb', 'טוּחַ', '["ṭûwach"]', '["and/ on <the>/ [those who] plastered"]', '["v"]', 'to smear, especially with lime daub, overlay, plaister, smut.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2902A}/[H2902]', 'inflected', 'heb', 'טוּחַ', '["ṭûwach"]', '["those/ [who] plastered"]', '["v"]', 'to smear, especially with lime daub, overlay, plaister, smut.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2372}/[H2372]', 'inflected', 'heb', 'חָזָה', '["châzâh"]', '["and/ who/ saw"]', '["v"]', 'to gaze at; mentally to perceive, contemplate (with pleasure); specifically, to have a vision of behold, look, prophesy, provide, see.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3820A}/H9029/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["from/ own heart/ their"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3704}/[H3680]', 'lemma', 'heb', 'כֶּסֶת', '["keçeth"]', '["bands"]', '["n-f"]', 'a cushion or pillow (as covering a seat or bed) pillow.', 'from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4555}/[H5596]', 'inflected', 'heb', 'מִסְפָּחָה', '["miçpâchâh"]', '["the/ long veils"]', '["n-f"]', 'a veil (as spread out) kerchief.', 'from 5596;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5315G}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["¿/ persons"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H9037}', 'inflected', 'heb', 'לכנה', '["la./Khe.nah"]', '["of/ yourself"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H8168>', 'inflected', 'heb', 'בשעלי', '["be./sha.''a.Lei"]', '["for/ handfuls of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6595B}/[H6626]', 'inflected', 'heb', 'פַּת', '["path"]', '["and/ for/ fragments of"]', '["n-f"]', 'a bit meat, morsel, piece.', 'from 6626;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3576}/H9046/[H3576]', 'inflected', 'heb', 'כָּזַב', '["kâzab"]', '["when/ speak falsehood/ you"]', '["v"]', 'to lie (i.e. deceive), literally or figuratively fail, (be found a, make a) liar, lie, lying, be in vain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3577}\/[H3576]', 'inflected', 'heb', 'כָּזָב', '["kâzâb"]', '["<of> falsehood"]', '["n-m"]', 'falsehood; literally (untruth) or figuratively (idol) deceitful, false, leasing, liar, lie, lying.', 'from 3576;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3704}/H9027/[H3680]', 'inflected', 'heb', 'כֶּסֶת', '["keçeth"]', '["bands/ your"]', '["n-f"]', 'a cushion or pillow (as covering a seat or bed) pillow.', 'from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0859E}/[H859]', 'lemma', 'heb', 'אַתָּה', '["ʼattâh"]', '["you"]', '["p"]', 'thou and thee, or (plural) ye and you thee, thou, ye, you.', 'or (shortened); אַתָּ; or אַת; feminine (irregular) sometimes אַתִּי; plural masculine אַתֶּם; feminine אַתֶּן; or אַתֵּנָהlemma אתֵּנָה missing vowel, corrected to אַתֵּנָה; or אַתֵּנָּה; a primitive pronoun of the second person;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5315G}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["<the>/ lives","the/ persons","the/ soul"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6524C}/[H6524]', 'inflected', 'heb', 'פָּרַח', '["pârach"]', '["for/ birds"]', '["v"]', 'to break forth as a bud, i.e. bloom; generally, to spread; specifically, to fly (as extending the wings); figuratively, to flourish × abroad, × abundantly, blossom, break forth (out), bud, flourish, make fly, grow, spread, spring (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2220}/H9026/[H2232]', 'inflected', 'heb', 'זְרוֹעַ', '["zᵉrôwaʻ"]', '["arms/ your"]', '["n-f"]', 'the arm (as stretched out), or (of animals) the foreleg; figuratively, force arm, help, mighty, power, shoulder, strength.', 'or (shortened) זְרֹעַ; and (feminine) זְרוֹעָה; or זְרֹעָה; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4555}/H9026/[H5596]', 'inflected', 'heb', 'מִסְפָּחָה', '["miçpâchâh"]', '["long veils/ your"]', '["n-f"]', 'a veil (as spread out) kerchief.', 'from 5596;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3027H}/H9027/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["from/ hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027H}/H9027/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["in/ hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4686A}/[H4685]', 'inflected', 'heb', 'מָצוּד', '["mâtsûwd"]', '["<into>/ prey"]', '["n-f"]', 'a net, or (abstractly) capture; also a fastness castle, defense, fort(-ress), (strong) hold, be hunted, net, snare, strong place.', 'or (feminine) מְצוּדָה; or מְצֻדָה; for 4685;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3512A}/[H3512]', 'lemma', 'heb', 'כָּאָה', '["kâʼâh"]', '["disheartened"]', '["v a"]', 'to despond; causatively, to deject broken, be grieved, make sad.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3510}/H9033/[H3510]', 'inflected', 'heb', 'כָּאַב', '["kâʼab"]', '["I caused pain/ him"]', '["v"]', 'properly, to feel pain; by implication, to grieve; figuratively, to spoil grieving, mar, have pain, make sad (sore), (be) sorrowful.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4383}/[H3782]', 'inflected', 'heb', 'מִכְשׁוֹל', '["mikshôwl"]', '["and/ [the] stumbling block of"]', '["n-m"]', 'a stumbling-block, literally or figuratively (obstacle, enticement (specifically an idol), scruple) caused to fall, offence, × (no-) thing offered, ruin, stumbling-block.', 'or מִכְשֹׁל; masculine from 3782;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H1875}/[H1875]', 'inflected', 'heb', 'דָּרַשׁ', '["dârash"]', '["¿/ really <to be consulted>"]', '["v"]', 'properly, to tread or frequent; usually to follow (for pursuit or search); by implication, to seek or ask; specifically to worship ask, × at all, care for, × diligently, inquire, make inquisition, (necro-) mancer, question, require, search, seek (for, out), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1544}/H9023/[H1556]', 'inflected', 'heb', 'גִּלּוּל', '["gillûwl"]', '["idols/ his"]', '["n-m"]', 'properly, a log (as round); by implication, an idol idol.', 'or (shortened) גִּלֻּל; from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1544}/H9028/[H1556]', 'inflected', 'heb', 'גִּלּוּל', '["gillûwl"]', '["by/ idols/ their"]', '["n-m"]', 'properly, a log (as round); by implication, an idol idol.', 'or (shortened) גִּלֻּל; from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8441}/H9026/[H8581]', 'inflected', 'heb', 'תּוֹעֵבַה', '["tôwʻêbah"]', '["abominations/ your"]', '["n-f"]', 'properly, something disgusting (morally), i.e. (as noun) an abhorrence; especially idolatry or (concretely) an idol abominable (custom, thing), abomination.', 'or תֹּעֵבַה; feminine active participle of 8581;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/H9009/{H1616}/[H1481]', 'inflected', 'heb', 'גֵּר', '["gêr"]', '["and/ from/ the/ sojourner"]', '["n-m"]', 'properly, a guest; by implication, a foreigner alien, sojourner, stranger.', 'or (fully) geyr (gare); from 1481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3772I}/H9033/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["and/ I will cut off/ him"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8045}/H9033/[H8045]', 'inflected', 'heb', 'שָׁמַד', '["shâmad"]', '["and/ I will destroy/ him"]', '["v"]', 'to desolate destory(-uction), bring to nought, overthrow, perish, pluck down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5771I}/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["as/ [the] iniquity of"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1875}/[H1875]', 'inflected', 'heb', 'דָּרַשׁ', '["dârash"]', '["the/ enquirer"]', '["v"]', 'properly, to tread or frequent; usually to follow (for pursuit or search); by implication, to seek or ask; specifically to worship ask, × at all, care for, × diligently, inquire, make inquisition, (necro-) mancer, question, require, search, seek (for, out), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1841H}/[H1840]', 'lemma', 'arc', 'דָּנִיֵּאל', '["Dânîyêʼl"]', '["Daniel","O Daniel","[are] Daniel"]', '["n-pr-m"]', 'Danijel, the Hebrew prophet Daniel.', '(Aramaic) corresponding to 1840;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6666}/H9028/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["by/ righteousness/ their"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7921A}/H9034/[H7921]', 'inflected', 'heb', 'שָׁכֹל', '["shâkôl"]', '["and/ it will make childless/ it"]', '["v"]', 'properly, to miscarry, i.e. suffer abortion; by analogy, to bereave (literally or figuratively) bereave (of children), barren, cast calf (fruit, young), be (make) childless, deprive, destroy, × expect, lose children, miscarry, rob of children, spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8201}/H9020/[H8199]', 'inflected', 'heb', 'שֶׁפֶט', '["shepheṭ"]', '["judgments/ my"]', '["n-m"]', 'a sentence, i.e. infliction judgment.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H8432>/H9023', 'inflected', 'heb', 'ותוכו', '["ve./to.Kh/o"]', '["and/ [the] middle of/ it"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2787}/[H2787]', 'inflected', 'heb', 'חָרַר', '["chârar"]', '["and/ it has been charred","and/ it will be hot"]', '["v"]', 'to glow, i.e. literally (to melt, burn, dry up) or figuratively (to show or incite passion) be angry, burn, dry, kindle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4399}\/[H4397]', 'inflected', 'heb', 'מְלָאכָה', '["mᵉlâʼkâh"]', '["into/ a product"]', '["n-f"]', 'properly, deputyship, i.e. ministry; generally, employment (never servile) or work (abstractly or concretely); also property (as the result of labor) business, cattle, industrious, occupation, ( -pied), officer, thing (made), use, (manner of) work((-man), -manship).', 'from the same as 4397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H0784}/[H784]', 'inflected', 'heb', 'אֵשׁ', '["ʼêsh"]', '["from/ the/ fire"]', '["n-f"]', 'fire (literally or figuratively) burning, fiery, fire, flaming, hot.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4351}/H9022/[H3564]', 'inflected', 'heb', 'מְכוּרָה', '["mᵉkûwrâh"]', '["origins/ your"]', '["n-f"]', 'origin (as if a mine) birth, habitation, nativity.', 'or מְכֹרָה; from the same as 3564 in the sense of dipping;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4138}/H9022/[H3205]', 'inflected', 'heb', 'מוֹלֶדֶת', '["môwledeth"]', '["and/ birth<s>/ your"]', '["n-f"]', 'nativity (plural birth-place); by implication, lineage, native country; also offspring, family begotten, born, issue, kindred, native(-ity).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8270}/H9022/[H8324]', 'inflected', 'heb', 'שֹׁר', '["shôr"]', '["umbilical cord/ your"]', '["n-m"]', 'a string (as twisted ), i.e. (specifically) the umbilical cord (also figuratively, as the centre of strength) navel.', 'from 8324; (compare 8306)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4935}/[H8159]', 'inflected', 'heb', 'מִשְׁעִי', '["mishʻîy"]', '["for/ cleansing"]', '["n-f"]', 'inspection to supple.', 'probably from 8159;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4414B}/[H4417]', 'inflected', 'heb', 'מָלַח', '["mâlach"]', '["and/ certainly <to be salted>"]', '["v"]', 'properly, to rub to pieces or pulverize; intransitively, to disappear as dust; also to salt whether internally (to season with salt) or externally (to rub with salt) × at all, salt, season, temper together, vanish away.', 'a primitive root; also as denominative from 4417');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2853}/[H2853]', 'inflected', 'heb', 'חָתַל', '["châthal"]', '["and/ certainly <to be wrapped>"]', '["v"]', 'to swathe × at all, swaddle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2853}/[H2853]', 'lemma', 'heb', 'חָתַל', '["châthal"]', '["you were wrapped"]', '["v"]', 'to swathe × at all, swaddle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2550}/[H2550]', 'inflected', 'heb', 'חָמַל', '["châmal"]', '["for/ compassion"]', '["v"]', 'to commiserate; by implication, to spare have compassion, (have) pity, spare.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1604}/[H1602]', 'inflected', 'heb', 'גֹּעַל', '["gôʻal"]', '["in/ [the] loathing of"]', '["n-m"]', 'abhorrence loathing.', 'from 1602;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315I}/H9022/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["life/ your","self/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7200G}/H9032/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ I saw/ you"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1818}/H9022/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["by/ blood/ your","in/ blood/ your","in/ blood<s>/ your"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6780}/[H6779]', 'inflected', 'heb', 'צֶמַח', '["tsemach"]', '["like/ [the] growth of"]', '["n-m"]', 'a sprout (usually concrete), literal or figurative branch, bud, that which (where) grew (upon), spring(-ing).', 'from 6779;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414I}/H9032/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["I have made/ you","I made/ you","I will give to/ you"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5716}/[H5710]', 'inflected', 'heb', 'עֲדִי', '["ʻădîy"]', '["into/ adornment"]', '["n-m"]', 'finery; generally an outfit; specifically, a headstall × excellent, mouth, ornament.', 'from 5710 in the sense of trappings;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8181}/H9022/[H8175]', 'inflected', 'heb', 'שֵׂעָר', '["sêʻâr"]', '["and/ hair/ your"]', '["n-m"]', 'hair (as if tossed or bristling) hair(-y), × rough.', 'or שַׂעַר; (Isaiah 7:20), from 8175 in the sense of dishevelling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6181}/[H6172]', 'inflected', 'heb', 'עֶרְיָה', '["ʻeryâh"]', '["and/ bareness"]', '["n-f"]', 'nudity bare, naked, × quite.', 'for 6172;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6256}/H9022/[H5703]', 'inflected', 'heb', 'עֵת', '["ʻêth"]', '["time/ your"]', '["n-f"]', 'time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when.', 'from 5703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3671}/H9020/[H3670]', 'inflected', 'heb', 'כָּנָף', '["kânâph"]', '["[the] skirt of garment/ my"]', '["n-f"]', 'an edge or extremity; specifically (of a bird or army) a wing, (of a garment or bedclothing) a flap, (of the earth) a quarter, (of a building) a pinnacle bird, border, corner, end, feather(-ed), × flying, (one an-) other, overspreading, × quarters, skirt, × sort, uttermost part, wing(-ed).', 'from 3670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7364}/H9032/[H7364]', 'inflected', 'heb', 'רָחַץ', '["râchats"]', '["and/ I washed/ you"]', '["v"]', 'to lave (the whole or a part of a thing) bathe (self), wash (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1818}/H9022/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["blood/ your","blood<s>/ your"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5480}/H9032/[H5480]', 'inflected', 'heb', 'סוּךְ', '["çûwk"]', '["and/ I anointed/ you"]', '["v"]', 'properly, to smear over (with oil), i.e. anoint anoint (self), × at all.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3847}/H9032/[H3847]', 'inflected', 'heb', 'לָבַשׁ', '["lâbash"]', '["and/ I clothed/ you"]', '["v"]', 'properly, wrap around, i.e. (by implication) to put on a garment or clothe (oneself, or another), literally or figuratively (in) apparel, arm, array (self), clothe (self), come upon, put (on, upon), wear.', 'or לָבֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5274B}/H9032/[H5275]', 'inflected', 'heb', 'נָעַל', '["nâʻal"]', '["and/ I shod/ you"]', '["v"]', 'properly, to fasten up, i.e. with a bar or cord; hence, to sandal, i.e. furnish with slippers bolt, inclose, lock, shoe, shut up.', 'a primitive root; also denominative from 5275');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2280}/H9032/[H2280]', 'inflected', 'heb', 'חָבַשׁ', '["châbash"]', '["and/ I wrapped head/ your"]', '["v"]', 'to wrap firmly (especially a turban, compress, or saddle); figuratively, to stop, to rule bind (up), gird about, govern, healer, put, saddle, wrap about.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8336B}/[H4897]', 'inflected', 'heb', 'שֵׁשׁ', '["shêsh"]', '["with <the>/ fine linen"]', '["n-m"]', 'bleached stuff, i.e. white linen or (by analogy) marble × blue, fine (twined) linen, marble, silk.', 'or (for alliteration with 4897) שְׁשִׁי; for 7893;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3680}/H9032/[H3680]', 'inflected', 'heb', 'כָּסָה', '["kâçâh"]', '["and/ I covered/ you"]', '["v"]', 'properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4897}/[H4871]', 'lemma', 'heb', 'מֶשִׁי', '["meshîy"]', '["silk"]', '["n-m"]', 'silk (as drawn from the cocoon) silk.', 'from 4871;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5710B}/H9032/[H5710]', 'inflected', 'heb', 'עָדָה', '["ʻâdâh"]', '["and/ I ornamented/ you"]', '["v"]', 'to advance, i.e. pass on or continue; causatively, to remove; specifically, to bedeck (i.e. bring an ornament upon) adorn, deck (self), pass by, take away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7242}/[H7234]', 'inflected', 'heb', 'רָבִיד', '["râbîyd"]', '["and/ a chain"]', '["n-m"]', 'a collar (as spread around the neck) chain.', 'from 7234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1627}/H9022/[H1641]', 'inflected', 'heb', 'גָּרוֹן', '["gârôwn"]', '["neck/ your"]', '["n-m"]', 'the throat (as roughened by swallowing) × aloud, mouth, neck, throat.', 'or (shortened) גָּרֹן; from 1641; (compare 1621)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5694}/[H5696]', 'inflected', 'heb', 'עָגִיל', '["ʻâgîyl"]', '["and/ earrings"]', '["n-m"]', 'something round, i.e. a ring (for the ears) earring.', 'from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7218A>/H9022', 'inflected', 'heb', 'בראשך', '["be./ro.She/kh"]', '["on/ head/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5710B}/[H5710]', 'inflected', 'heb', 'עָדָה', '["ʻâdâh"]', '["and/ she ornamented herself","and/ you ornamented yourself","and/ you put on"]', '["v"]', 'to advance, i.e. pass on or continue; causatively, to remove; specifically, to bedeck (i.e. bring an ornament upon) adorn, deck (self), pass by, take away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4403}/H9022/[H3847]', 'inflected', 'heb', 'מַלְבּוּשׁ', '["malbûwsh"]', '["and/ clothing/ your"]', '["n-m"]', 'a garment, or (collectively) clothing apparel, raiment, vestment.', 'or מַלְבֻּשׁ; from 3847;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4897}/[H4871]', 'inflected', 'heb', 'מֶשִׁי', '["meshîy"]', '["and/ silk"]', '["n-m"]', 'silk (as drawn from the cocoon) silk.', 'from 4871;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3302}/[H3302]', 'inflected', 'heb', 'יָפָה', '["yâphâh"]', '["and/ it was beautiful","and/ you were beautiful"]', '["v"]', 'properly, to be bright, i.e. (by implication) beautiful be beautiful, be (make self) fair(-r), deck.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4410}/[H4427]', 'inflected', 'heb', 'מְלוּכָה', '["mᵉlûwkâh"]', '["into/ kingship"]', '["n-f"]', 'something ruled, i.e. a realm kingsom, king''s, × royal.', 'feminine passive participle of 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3308}/H9022/[H3302]', 'inflected', 'heb', 'יֳפִי', '["yŏphîy"]', '["in/ beauty/ your","on/ beauty/ your"]', '["n-m"]', 'beauty beauty.', 'from 3302;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1926}/H9020/[H1921]', 'inflected', 'heb', 'הָדָר', '["hâdâr"]', '["on/ splendor/ my"]', '["n-m"]', 'magnificence, i.e. ornament or splendor beauty, comeliness, excellency, glorious, glory, goodly, honour, majesty.', 'from 1921;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8210J}/[H8210]', 'inflected', 'heb', 'שָׁפַךְ', '["shâphak"]', '["and/ he will pour out","and/ you poured out"]', '["v"]', 'to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8457}/H9022/[H2181]', 'inflected', 'heb', 'תַּזְנוּת', '["taznûwth"]', '["prostitution/ your","prostitution<s>/ your"]', '["n-f"]', 'harlotry, i.e. (figuratively) idolatry fornication, whoredom.', 'or תַּזְנֻת; from 2181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0899B}/H9022/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["some of/ clothes/ your"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2921}/[H2921]', 'lemma', 'heb', 'טָלָא', '["ṭâlâʼ"]', '["multicolored"]', '["v"]', 'properly, to cover with pieces; i.e. (by implication) to spot or variegate (as tapestry) clouted, with divers colours, spotted.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H2091>/H9020', 'inflected', 'heb', 'מזהבי', '["mi./ze.ha.V/i"]', '["some of/ gold/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H3701G}/H9020/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["and/ some of/ silver/ my"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7553}/H9022/[H7551]', 'inflected', 'heb', 'רִקְמָה', '["riqmâh"]', '["multicolored cloth/ your"]', '["n-f"]', 'variegation of color; specifically, embroidery broidered (work), divers colours, (raiment of) needlework (on both sides).', 'from 7551;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3680}/H9038/[H3680]', 'inflected', 'heb', 'כָּסָה', '["kâçâh"]', '["and/ you covered/ them"]', '["v"]', 'properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8081}/H9020/[H8080]', 'inflected', 'heb', 'שֶׁמֶן', '["shemen"]', '["and/ oil/ my"]', '["n-m"]', 'grease, especially liquid (as from the olive, often perfumed); figuratively, richness anointing, × fat (things), × fruitful, oil(-ed), ointment, olive, pine.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7004}/H9020/[H6999]', 'inflected', 'heb', 'קְטֹרֶת', '["qᵉṭôreth"]', '["and/ incense/ my"]', '["n-f"]', 'a fumigation (sweet) incense, perfume.', 'from 6999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414J}/[H5414]', 'lemma', 'heb', 'נָתַן', '["nâthan"]', '["you put"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3899H}/H9020/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["and/ food/ my"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1323G}/H9022/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["daughters/ your"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2076}/H9038/[H2076]', 'inflected', 'heb', 'זָבַח', '["zâbach"]', '["and/ you sacrificed/ them"]', '["v"]', 'to slaughter an animal (usually in sacrifice) kill, offer, (do) sacrifice, slay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8457}/H9022/[H2181]', 'inflected', 'heb', 'תַּזְנוּת', '["taznûwth"]', '["from/ prostitution<s>/ your"]', '["n-f"]', 'harlotry, i.e. (figuratively) idolatry fornication, whoredom.', 'or תַּזְנֻת; from 2181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8457}/H9022/[H2181]', 'inflected', 'heb', 'תַּזְנוּת', '["taznûwth"]', '["and/ prostitution<s>/ your"]', '["n-f"]', 'harlotry, i.e. (figuratively) idolatry fornication, whoredom.', 'or תַּזְנֻת; from 2181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1961}/H9042/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["when/ were/ you"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7413}/[H7311]', 'lemma', 'heb', 'רָמָה', '["râmâh"]', '["a high place"]', '["n-f"]', 'a height (as a seat of idolatry) high place.', 'feminine active participle of 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7413}/H9022/[H7311]', 'inflected', 'heb', 'רָמָה', '["râmâh"]', '["high place/ your","high places/ your"]', '["n-f"]', 'a height (as a seat of idolatry) high place.', 'feminine active participle of 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6589}/[H6589]', 'inflected', 'heb', 'פָּשַׂק', '["pâsaq"]', '["and/ you opened wide"]', '["v"]', 'to dispart (the feet or lips), i.e. become licentious open (wide).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1432}/[H1431]', 'lemma', 'heb', 'גָּדֵל', '["gâdêl"]', '["becoming great of"]', '["a"]', 'large (literally or figuratively) great, grew.', 'from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2706H}/H9022/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["allotment/ your"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414G}/H9032/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I gave/ you","and/ I will put on/ you"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8130}/H9032/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["[those who] hate/ you"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1870G}/H9022/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["from/ conduct/ your"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7654}/H9022/[H7648]', 'inflected', 'heb', 'שׇׂבְעָה', '["sobʻâh"]', '["satiety/ your"]', '["n-f"]', 'satiety (to have) enough, × till...be full, (un-) satiable, satisfy, × sufficiently.', 'feminine of 7648;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2181}/H9038/[H2181]', 'inflected', 'heb', 'זָנָה', '["zânâh"]', '["and/ you acted as a prostitute with/ them"]', '["v"]', 'to commit adultery (usually of the female, and less often of simple fornication, rarely of involuntary ravishment); figuratively, to commit idolatry (the Jewish people being regarded as the spouse of Jehovah) (cause to) commit fornication, × continually, × great, (be an, play the) harlot, (cause to be, play the) whore, (commit, fall to) whoredom, (cause to) go a-whoring, whorish.', 'a primitive root [highly fed and therefore wanton];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3667B}/[H3665]', 'lemma', 'heb', 'כְּנַעַן', '["Kᵉnaʻan"]', '["Canaan","merchant[s]"]', '["n-pr-m n-pr-loc n-m"]', 'Kenaan, a son a Ham; also the country inhabited by him Canaan, merchant, traffick.', 'from 3665; humiliated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3826}/H9022/[H3820]', 'inflected', 'heb', 'לִבָּה', '["libbâh"]', '["[is] anger/ your"]', '["n-f"]', 'the heart heart.', 'feminine of 3820;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6213A}/H9042/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["when/ do/ you"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7986}/[H7980]', 'lemma', 'heb', 'שַׁלֶּטֶת', '["shalleṭeth"]', '["imperious"]', '["a"]', 'a vixen imperious.', 'feminine from 7980;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1129}/H9042/[H1129]', 'inflected', 'heb', 'בָּנָה', '["bânâh"]', '["when/ built/ you"]', '["v"]', 'to build (literally and figuratively) (begin to) build(-er), obtain children, make, repair, set (up), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1354>/H9022', 'opaque', 'heb', 'גַב', '["gab"]', '["mound/ your"]', '["n"]', 'the back (as rounded); by analogy, the top or rim, a boss, a vault, arch of eye, bulwarks, etc. back, body, boss, eminent (higher) place, (eye) brows, nave, ring.', 'from an unused root meaning to hollow or curve; (compare 1460 and 1479)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7413}/H9022/[H7311]', 'inflected', 'heb', 'רָמָה', '["râmâh"]', '["and/ high place/ your"]', '["n-f"]', 'a height (as a seat of idolatry) high place.', 'feminine active participle of 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7046}/[H7046]', 'inflected', 'heb', 'קָלַס', '["qâlaç"]', '["to/ scorn"]', '["v"]', 'to disparage, i.e. ridicule mock, scoff, scorn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5078}/[H5077]', 'lemma', 'heb', 'נֵדֶה', '["nêdeh"]', '["a gift"]', '["n-m"]', 'a bounty (for prostitution) gifts.', 'from 5077 in the sense of freely flinging money;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5083>/H9022', 'opaque', 'heb', 'נָדָן', '["nâdân"]', '["gift/ your"]', '["n-m"]', 'a present (for prostitution) gift.', 'probably from an unused root meaning to give;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7809}/[H7809]', 'inflected', 'heb', 'שָׁחַד', '["shâchad"]', '["and/ you have bribed"]', '["v"]', 'to donate, i.e. bribe hire, give a reward.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8457}/H9022/[H2181]', 'inflected', 'heb', 'תַּזְנוּת', '["taznûwth"]', '["by/ prostitution<s>/ your","in/ prostitution<s>/ your"]', '["n-f"]', 'harlotry, i.e. (figuratively) idolatry fornication, whoredom.', 'or תַּזְנֻת; from 2181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2016}/[H2015]', 'lemma', 'heb', 'הֶפֶךְ', '["hephek"]', '["contrariness"]', '["n-m"]', 'a turn, i.e. the reverse contrary.', '; or הֵפֶךְ; from 2015;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0310A}/H9032/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["and/ after/ you"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5414G}/H9042/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ because/ gave/ you"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0868}/[H866]', 'inflected', 'heb', 'אֶתְנַן', '["ʼethnan"]', '["and/ [the] hire of a prostitute"]', '["n-m"]', 'a gift (as the price of harlotry or idolatry) hire, reward.', 'the same as 866;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2016}/[H2015]', 'inflected', 'heb', 'הֶפֶךְ', '["hephek"]', '["<into>/ contrariness"]', '["n-m"]', 'a turn, i.e. the reverse contrary.', '; or הֵפֶךְ; from 2015;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5178B}/H9022/[H5154]', 'inflected', 'heb', 'נְחֹשֶׁת', '["nᵉchôsheth"]', '["lust/ your"]', '["n-m"]', 'copper, hence, something made of that metal, i.e. coin, a fetter; figuratively, base (as compared with gold or silver) brasen, brass, chain, copper, fetter (of brass), filthiness, steel.', 'for 5154;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H1818}/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["and/ according to/ [the] blood<s> of"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8210H}/[H8210]', 'inflected', 'heb', 'שָׁפַךְ', '["shâphak"]', '["and/ [women who] shed"]', '["v"]', 'to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7068}/[H7065]', 'inflected', 'heb', 'קִנְאָה', '["qinʼâh"]', '["and/ jealousy"]', '["n-f"]', 'jealousy or envy envy(-ied), jealousy, × sake, zeal.', 'from 7065;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0899B}/H9022/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["clothes/ your"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5117}/H9032/[H5117]', 'inflected', 'heb', 'נוּחַ', '["nûwach"]', '["and/ they will leave/ you"]', '["v"]', 'to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5927J}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["and/ I will bring up","and/ they will bring up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1333}/H9032/[H1333]', 'inflected', 'heb', 'בָּתַק', '["bâthaq"]', '["and/ they will cut to pieces/ you"]', '["v"]', 'to cut in pieces thrust through.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7673A}/H9032/[H7673]', 'inflected', 'heb', 'שָׁבַת', '["shâbath"]', '["and/ I will cause to cease/ you"]', '["v"]', 'to repose, i.e. desist from exertion; used in many implied relations (causative, figurative or specific) (cause to, let, make to) cease, celebrate, cause (make) to fail, keep (sabbath), suffer to be lacking, leave, put away (down), (make to) rest, rid, still, take away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2181}/[H2181]', 'inflected', 'heb', 'זָנָה', '["zânâh"]', '["from/ a prostitute"]', '["v"]', 'to commit adultery (usually of the female, and less often of simple fornication, rarely of involuntary ravishment); figuratively, to commit idolatry (the Jewish people being regarded as the spouse of Jehovah) (cause to) commit fornication, × continually, × great, (be an, play the) harlot, (cause to be, play the) whore, (commit, fall to) whoredom, (cause to) go a-whoring, whorish.', 'a primitive root [highly fed and therefore wanton];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2154}/[H2161]', 'inflected', 'heb', 'זִמָּה', '["zimmâh"]', '["<the>/ licentiousness","the/ licentiousness"]', '["n-f"]', 'a plan, especially a bad one heinous crime, lewd(-ly, -ness), mischief, purpose, thought, wicked (device, mind, -ness).', 'or זַמָּה; from 2161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0517}/H9024/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["[is] like/ mother/ her"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1121A}/H9024/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ children/ her"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0269}/H9022/[H251]', 'inflected', 'heb', 'אָחוֹת', '["ʼâchôwth"]', '["sister/ your","sisters/ your"]', '["n-f"]', 'a sister (used very widely [like 251number 250, corrected to 251], literally and figuratively) (an-) other, sister, together.', 'irregular feminine of 251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0582}/H9029/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["husbands/ their"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1121A}/H9029/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ children/ their"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0517}/H9027/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["mother/ your"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0269}/H9022/[H251]', 'inflected', 'heb', 'אָחוֹת', '["ʼâchôwth"]', '["and/ sister/ your","and/ sisters/ your"]', '["n-f"]', 'a sister (used very widely [like 251number 250, corrected to 251], literally and figuratively) (an-) other, sister, together.', 'irregular feminine of 251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8040H}/H9022/[H8071]', 'inflected', 'heb', 'שְׂמֹאול', '["sᵉmôʼwl"]', '["north/ your"]', '["n-m"]', 'properly, dark (as enveloped), i.e. the north; hence (by orientation), the left hand left (hand, side).', 'or שְׂמֹאל; a primitive word (rather perhaps from the same as 8071 (by insertion of the aleph) through the idea of wrapping up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3225H}/H9022/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["from/ south/ your"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1870G}/H9029/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["in/ ways/ their"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8441}/H9029/[H8581]', 'inflected', 'heb', 'תּוֹעֵבַה', '["tôwʻêbah"]', '["and/ in/ abominations/ their"]', '["n-f"]', 'properly, something disgusting (morally), i.e. (as noun) an abhorrence; especially idolatry or (concretely) an idol abominable (custom, thing), abomination.', 'or תֹּעֵבַה; feminine active participle of 8581;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6985}/[H6990]', 'lemma', 'heb', 'קַט', '["qaṭ"]', '["only"]', '["a"]', 'a little, i.e. (adverbially) merely very.', 'from 6990 in the sense of abbreviation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7653}/[H7647]', 'lemma', 'heb', 'שִׂבְעָה', '["sibʻâh"]', '["surfeit of"]', '["n-f"]', 'satiety fulness.', 'feminine of 7647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1323G}/H9024/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["and/ to/ daughters/ her"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3027K}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ [the] hand of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8111}/[H8104]', 'inflected', 'heb', 'שֹׁמְרוֹן', '["Shômᵉrôwn"]', '["and/ Samaria"]', '["n-pr-loc"]', 'Shomeron, a place in Palestine Samaria.', 'from the active participle of 8104; watch-station;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2677}/[H2673]', 'inflected', 'heb', 'חֵצִי', '["chêtsîy"]', '["according to/ [the] half of"]', '["n-m"]', 'the half or middle half, middle, mid(-night), midst, part, two parts.', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3639}/H9022/[H3637]', 'inflected', 'heb', 'כְּלִמָּה', '["kᵉlimmâh"]', '["disgrace/ your"]', '["n-f"]', 'disgrace confusion, dishonour, reproach, shame.', 'from 3637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0269}/H9022/[H251]', 'inflected', 'heb', 'אָחוֹת', '["ʼâchôwth"]', '["for/ sister/ your"]', '["n-f"]', 'a sister (used very widely [like 251number 250, corrected to 251], literally and figuratively) (an-) other, sister, together.', 'irregular feminine of 251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2403B}/H9022/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["by/ sins/ your"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5375J}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ bear"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6663}/H9042/[H6663]', 'inflected', 'heb', 'צָדַק', '["tsâdaq"]', '["because/ have made appear righteous/ you"]', '["v"]', 'to be (causatively, make) right (in a moral or forensic sense) cleanse, clear self, (be, do) just(-ice, -ify, -ify self), (be turn to) righteous(-ness).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7622}/H9029/[H7617]', 'inflected', 'heb', 'שְׁבוּת', '["shᵉbûwth"]', '["captivity/ their"]', '["n-f"]', 'exile, concretely, prisoners; figuratively, a former state of prosperity captive(-ity).', 'or שְׁבִית; from 7617;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7622}/[H7617]', 'inflected', 'heb', 'שְׁבוּת', '["shᵉbûwth"]', '["and/ [the] captivity of"]', '["n-f"]', 'exile, concretely, prisoners; figuratively, a former state of prosperity captive(-ity).', 'or שְׁבִית; from 7617;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H8432>/H9029', 'inflected', 'heb', 'בתוכהנה', '["be./to.Kha./he.nah"]', '["in/ midst of/ them"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5162G}/H9042/[H5162]', 'inflected', 'heb', 'נָחַם', '["nâcham"]', '["when/ comfort/ you"]', '["v"]', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6927}/H9029/[H6923]', 'inflected', 'heb', 'קַדְמָה', '["qadmâh"]', '["to/ former state/ their"]', '["n-f"]', 'priority (in time); also used adverbially (before) afore, antiquity, former (old) estate.', 'from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6927}/H9027/[H6923]', 'inflected', 'heb', 'קַדְמָה', '["qadmâh"]', '["to/ former state/ your"]', '["n-f"]', 'priority (in time); also used adverbially (before) afore, antiquity, former (old) estate.', 'from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8052}/[H8074]', 'inflected', 'heb', 'שְׁמוּעָה', '["shᵉmûwʻâh"]', '["<into>/ a mention"]', '["n-f"]', 'something heard, i.e. an announcement bruit, doctrine, fame, mentioned, news, report, rumor, tidings.', 'feminine passive participle of 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6310G}/H9022/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["in/ mouth/ your"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1347}/H9022/[H1342]', 'inflected', 'heb', 'גָּאוֹן', '["gâʼôwn"]', '["pride<s>/ your"]', '["n-m"]', 'the same as 1346 arrogancy, excellency(-lent), majesty, pomp, pride, proud, swelling.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7590}/[H7750]', 'inflected', 'heb', 'שָׁאט', '["shâʼṭ"]', '["those/ [who] despise","who/ despise"]', '["v"]', 'one contemning that (which) despise(-d).', 'for active part of 7750 (compare 7589);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2154}/H9022/[H2161]', 'inflected', 'heb', 'זִמָּה', '["zimmâh"]', '["licentiousness/ your"]', '["n-f"]', 'a plan, especially a bad one heinous crime, lewd(-ly, -ness), mischief, purpose, thought, wicked (device, mind, -ness).', 'or זַמָּה; from 2161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3947G}/H9042/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["when/ receive/ you"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1285}/H9022/[H1262]', 'inflected', 'heb', 'בְּרִית', '["bᵉrîyth"]', '["from/ covenant/ your"]', '["n-f"]', 'a compact (because made by passing between pieces of flesh) confederacy, (con-) feder(-ate), covenant, league.', 'from 1262 (in the sense of cutting [like 1254]);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6610}/[H6605]', 'lemma', 'heb', 'פִּתְחוֹן', '["pithchôwn"]', '["an opening of","opening of"]', '["n-m"]', 'opening (the act) open(-ing).', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3722A}/H9040/[H3722]', 'inflected', 'heb', 'כָּפַר', '["kâphar"]', '["when/ make atonement/ I"]', '["v"]', 'to cover (specifically with bitumen); figuratively, to expiate or condone, to placate or cancel appease, make (an atonement, cleanse, disannul, forgive, be merciful, pacify, pardon, purge (away), put off, (make) reconcile(-liation).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4911B}/[H4912]', 'inflected', 'heb', 'מָשַׁל', '["mâshal"]', '["and/ speak a parable"]', '["v"]', 'to liken, i.e. (transitively) to use figurative language (an allegory, adage, song or the like); intransitively, to resemble be(-come) like, compare, use (as a) proverb, speak (in proverbs), utter.', 'denominative from 4912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0083}/[H82]', 'inflected', 'heb', 'אֵבֶר', '["ʼêber"]', '["<the>/ pinion"]', '["n-m"]', 'a pinion (long-) wing(-ed).', 'from 82;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5133}/[H5327]', 'inflected', 'heb', 'נוֹצָה', '["nôwtsâh"]', '["<the>/ plumage"]', '["n-f"]', 'a pinion (or wing feather); often (collectively) plumage feather(-s), ostrich.', 'or נֹצָה; feminine active participle of 5327 in the sense of flying;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7553}/[H7551]', 'inflected', 'heb', 'רִקְמָה', '["riqmâh"]', '["<the>/ variegated plumage"]', '["n-f"]', 'variegation of color; specifically, embroidery broidered (work), divers colours, (raiment of) needlework (on both sides).', 'from 7551;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6788}/[H6785]', 'lemma', 'heb', 'צַמֶּרֶת', '["tsammereth"]', '["[the] treetop of"]', '["n-f"]', 'fleeciness, i.e. foliage highest branch, top.', 'from the same as 6785;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3242}/H9023/[H3243]', 'inflected', 'heb', 'יְנִיקָה', '["yᵉnîyqâh"]', '["shoots/ its"]', '["n-f"]', 'a sucker or sapling young twig.', 'from 3243;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7704B>', 'inflected', 'heb', 'בשדה', '["bi/s.deh"]', '["in/ a field of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6851}/[H6687]', 'lemma', 'heb', 'צַפְצָפָה', '["tsaphtsâphâh"]', '["a willow"]', '["n-f"]', 'a willow (as growing in overflowed places) willow tree.', 'from 6687;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8328}/H9023/[H8327]', 'inflected', 'heb', 'שֶׁרֶשׁ', '["sheresh"]', '["and/ roots/ his","and/ roots/ its"]', '["n-m"]', 'a root (literally or figuratively) bottom, deep, heel, root.', 'from 8327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6288A}/[H6286]', 'lemma', 'heb', 'פְּאֹרָה', '["pᵉʼôrâh"]', '["boughs"]', '["n-f"]', 'properly, ornamentation, i.e. (plural) foliage (including the limbs) as bright green bough, branch, sprig.', 'or פֹּרָאה; or פֻּארָה; from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5133}/[H5327]', 'lemma', 'heb', 'נוֹצָה', '["nôwtsâh"]', '["plumage"]', '["n-f"]', 'a pinion (or wing feather); often (collectively) plumage feather(-s), ostrich.', 'or נֹצָה; feminine active participle of 5327 in the sense of flying;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3719}/[H3719]', 'lemma', 'heb', 'כָּפַן', '["kâphan"]', '["it bent"]', '["v"]', 'to bend bend.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1808}/H9023/[H1802]', 'inflected', 'heb', 'דָּלִיָּה', '["dâlîyâh"]', '["and/ branches/ its"]', '["n-f"]', 'something dangling, i.e. a bough branch.', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6170}/[H6165]', 'inflected', 'heb', 'עֲרוּגָה', '["ʻărûwgâh"]', '["from/ [the] beds of"]', '["n-f"]', 'something piled up (as if (figuratively) raised by mental aspiration), i.e. a paterre bed, furrow.', 'or עֲרֻגָה; feminine passive participle of 6165;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4302}/H9024/[H5193]', 'inflected', 'heb', 'מַטָּע', '["maṭṭâʻ"]', '["planting place/ its","planting/ its"]', '["n-m"]', 'something planted, i.e. the place (a garden or vineyard), or the thing (a plant, figuratively or men); by implication, the act, planting plant(-ation, -ing).', 'from 5193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6057>', 'opaque', 'heb', 'עָנָף', '["ʻânâph"]', '["branch[es]"]', '["n-m"]', 'a twig (as covering the limbs) bough, branch.', 'from an unused root meaning to cover;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0155}\/[H117]', 'inflected', 'heb', 'אַדֶּרֶת', '["ʼaddereth"]', '["splendor"]', '["n-f"]', 'something ample (as a large vine, a wide dress) garment, glory, goodly, mantle, robe.', 'feminine of 117; ; also the same as 145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7082}/[H7082]', 'lemma', 'heb', 'קָסַס', '["qâçaç"]', '["will it strip off?"]', '["v"]', 'to lop off cut off.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5971A}/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["and/ by/ a people"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8328}/H9024/[H8327]', 'inflected', 'heb', 'שֶׁרֶשׁ', '["sheresh"]', '["from/ roots/ its"]', '["n-m"]', 'a root (literally or figuratively) bottom, deep, heel, root.', 'from 8327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5060}/[H5060]', 'inflected', 'heb', 'נָגַע', '["nâgaʻ"]', '["when/ touches"]', '["v"]', 'properly, to touch, i.e. lay the hand upon (for any purpose; euphemistically, to lie with a woman); by implication, to reach (figuratively, to arrive, acquire); violently, to strike (punish, defeat, destroy, etc.) beat, (× be able to) bring (down), cast, come (nigh), draw near (nigh), get up, happen, join, near, plague, reach (up), smite, strike, touch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6170}/[H6165]', 'lemma', 'heb', 'עֲרוּגָה', '["ʻărûwgâh"]', '["[the] beds of"]', '["n-f"]', 'something piled up (as if (figuratively) raised by mental aspiration), i.e. a paterre bed, furrow.', 'or עֲרֻגָה; feminine passive participle of 6165;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3001}\/[H3001]', 'inflected', 'heb', 'יָבֵשׁ', '["yâbêsh"]', '["it will wither"]', '["v"]', 'to be ashamed, confused or disappointed; also (as failing) to dry up (as water) or wither (as herbage) be ashamed, clean, be confounded, (make) dry (up), (do) shame(-fully), × utterly, wither (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5975G}/H9034/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["to/ continue/ it"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H4422}/[H4422]', 'inflected', 'heb', 'מָלַט', '["mâlaṭ"]', '["¿/ will he escape"]', '["v"]', 'properly, to be smooth, i.e. (by implication) to escape (as if by slipperiness); causatively, to release or rescue; specifically, to bring forth young, emit sparks deliver (self), escape, lay, leap out, let alone, let go, preserve, save, × speedily, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0423}/H9023/[H422]', 'inflected', 'heb', 'אָלָה', '["ʼâlâh"]', '["oath/ his"]', '["n-f"]', 'an imprecation curse, cursing, execration, oath, swearing.', 'from 422;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6951}/[H6950]', 'inflected', 'heb', 'קָהָל', '["qâhâl"]', '["and/ with/ a company","and/ with/ a company of"]', '["n-m"]', 'assemblage (usually concretely) assembly, company, congregation, multitude.', 'from 6950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8210I}/[H8210]', 'inflected', 'heb', 'שָׁפַךְ', '["shâphak"]', '["when/ pour out"]', '["v"]', 'to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1129}/[H1129]', 'inflected', 'heb', 'בָּנָה', '["bânâh"]', '["and/ when/ build"]', '["v"]', 'to build (literally and figuratively) (begin to) build(-er), obtain children, make, repair, set (up), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4422}\/[H4422]', 'inflected', 'heb', 'מָלַט', '["mâlaṭ"]', '["he will escape"]', '["v"]', 'properly, to be smooth, i.e. (by implication) to escape (as if by slipperiness); causatively, to release or rescue; specifically, to bring forth young, emit sparks deliver (self), escape, lay, leap out, let alone, let go, preserve, save, × speedily, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0423}/H9020/[H422]', 'inflected', 'heb', 'אָלָה', '["ʼâlâh"]', '["oath/ my"]', '["n-f"]', 'an imprecation curse, cursing, execration, oath, swearing.', 'from 422;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414N}/H9033/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I will requite/ it"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4604}/H9023/[H4603]', 'inflected', 'heb', 'מַעַל', '["maʻal"]', '["unfaithfulness/ his"]', '["n-m"]', 'treachery, i.e. sin falsehood, grievously, sore, transgression, trespass, × very.', 'from 4603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4015}/H9023/[H1272]', 'inflected', 'heb', 'מִבְרָח', '["mibrâch"]', '["fugitives/ his"]', '["n-m"]', 'a refugee fugitive.', 'from 1272;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6788}/[H6785]', 'inflected', 'heb', 'צַמֶּרֶת', '["tsammereth"]', '["from/ [the] treetop of"]', '["n-f"]', 'fleeciness, i.e. foliage highest branch, top.', 'from the same as 6785;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8362}/[H8362]', 'inflected', 'heb', 'שָׁתַל', '["shâthal"]', '["and/ I will plant [it]"]', '["v"]', 'to transplant plant.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8524}/[H8524]', 'inflected', 'heb', 'תָּלַל', '["tâlal"]', '["and/ lofty"]', '["a"]', 'to pile up, i.e. elevate eminent. Compare 2048.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8362}/H9033/[H8362]', 'inflected', 'heb', 'שָׁתַל', '["shâthal"]', '["I will plant/ it"]', '["v"]', 'to transplant plant.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0730}/[H729]', 'inflected', 'heb', 'אֶרֶז', '["ʼerez"]', '["<into>/ a cedar"]', '["n-m"]', 'a cedar tree (from the tenacity of its roots) cedar (tree).', 'from 729;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6213A}\/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["and/ I will act"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5315G}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["as/ [the] life of"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H5315G}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["and/ as/ [the] life of"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2258B}/H9023/[H2254]', 'inflected', 'heb', 'חֲבֹל', '["chăbôl"]', '["pledge/ his"]', '["n-m"]', 'a pawn (as security for debt) pledge.', 'or (feminine) חֲבֹלָה; from 2254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2326}/[H2325]', 'lemma', 'heb', 'חוֹב', '["chôwb"]', '["a debt"]', '["n-m"]', 'debt debtor.', 'from 2325;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5903}/[H6191]', 'inflected', 'heb', 'עֵירֹם', '["ʻêyrôm"]', '["and/ [the] naked"]', '["a"]', 'nudity naked(-ness).', 'or עֵרֹם; from 6191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2258A}/[H2254]', 'lemma', 'heb', 'חֲבֹל', '["chăbôl"]', '["a pledge"]', '["n-m"]', 'a pawn (as security for debt) pledge.', 'or (feminine) חֲבֹלָה; from 2254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1500}/[H1498]', 'inflected', 'heb', 'גְּזֵלָה', '["gᵉzêlâh"]', '["and/ robbery"]', '["n-f"]', 'that (he had robbed) (which he took violently away), spoil, violence.', 'feminine of 1498 and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6041}/[H6031]', 'inflected', 'heb', 'עָנִי', '["ʻânîy"]', '["from/ [the] poor"]', '["a"]', 'depressed, in mind or circumstances afflicted, humble, lowly, needy, poor.', 'from 6031; (practically the same as 6035, although the margin constantly disputes this, making 6035 subjective and objective);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6666}/H9023/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["for/ righteousness/ his","on/ righteousness/ his"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H2654A}/[H2654]', 'inflected', 'heb', 'חָפֵץ', '["châphêts"]', '["¿/ really <to take pleasure>"]', '["v"]', 'properly, to incline to; by implication (literally but rarely) to bend; figuratively, to be pleased with, desire × any at all, (have, take) delight, desire, favour, like, move, be (well) pleased, have pleasure, will, would.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7725O}/H9043/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["when/ turning back/ he"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6666}/H9023/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["from/ righteousness/ his"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H1870G}/H9020/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["¿/ way/ my","¿/ ways/ my"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7725O}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["when/ turns away","when/ turns back"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5766A}/H9023/[H5765]', 'inflected', 'heb', 'עֶוֶל', '["ʻevel"]', '["for/ injustice/ his"]', '["n-m"]', '(moral) evil iniquity, perverseness, unjust(-ly), unrighteousness(-ly); wicked(-ness).', 'or עָוֶל; and (feminine) עַוְלָה; or עוֹלָה; or עֹלָה; from 5765;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7564}/H9023/[H7562]', 'inflected', 'heb', 'רִשְׁעָה', '["rishʻâh"]', '["from/ wickedness/ his"]', '["n-f"]', 'wrong (especially moral) fault, wickedly(-ness).', 'feminine of 7562;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6588}/H9026/[H6586]', 'inflected', 'heb', 'פֶּשַׁע', '["peshaʻ"]', '["transgressions/ your"]', '["n-m"]', 'a revolt (national, moral or religious) rebellion, sin, transgression, trespass.', 'from 6586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4383}/[H3782]', 'inflected', 'heb', 'מִכְשׁוֹל', '["mikshôwl"]', '["<into>/ a stumbling block","<into>/ a stumbling block of"]', '["n-m"]', 'a stumbling-block, literally or figuratively (obstacle, enticement (specifically an idol), scruple) caused to fall, offence, × (no-) thing offered, ruin, stumbling-block.', 'or מִכְשֹׁל; masculine from 3782;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2421}\/[H2331]', 'inflected', 'heb', 'חָיָה', '["châyâh"]', '["and/ live"]', '["v"]', 'to live, whether literally or figuratively; causatively, to revive keep (leave, make) alive, × certainly, give (promise) life, (let, suffer to) live, nourish up, preserve (alive), quicken, recover, repair, restore (to life), revive, (× God) save (alive, life, lives), × surely, be whole.', 'a primitive root (compare 2331, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3833B>', 'opaque', 'heb', 'לָבִיא', '["lâbîyʼ"]', '["a lioness"]', '["n"]', 'a lion (properly, a lioness as the fiercer (although not a roarer;)) (great, old, stout) lion, lioness, young (lion).', 'or (Ezekiel 19:2) לְבִיָּא; irregular masculine plural לְבָאִים; irregular feminine plural לְבָאוֹת; from an unused root meaning to roar; compare 738');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1482}/H9024/[H1481]', 'inflected', 'heb', 'גּוּר', '["gûwr"]', '["cubs/ her"]', '["n-m"]', 'a cub (as still abiding in the lair), especially of the lion whelp, young one.', 'or (shortened) גֻּר; perhaps from 1481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1482}/H9024/[H1481]', 'inflected', 'heb', 'גּוּר', '["gûwr"]', '["of/ cubs/ her"]', '["n-m"]', 'a cub (as still abiding in the lair), especially of the lion whelp, young one.', 'or (shortened) גֻּר; perhaps from 1481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7845H}/H9028/[H7743]', 'inflected', 'heb', 'שַׁחַת', '["shachath"]', '["in/ pit/ their"]', '["n-f"]', 'a pit (especially as a trap); figuratively, destruction corruption, destruction, ditch, grave, pit.', 'from 7743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2397}/[H2336]', 'inflected', 'heb', 'חָח', '["châch"]', '["with <the>/ hooks"]', '["n-m"]', 'a ring for the nose (or lips) bracelet, chain, hook.', 'once (Ezekiel 29:4) חָחִי; from the same as 2336;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8615B}/H9024/[H6960]', 'inflected', 'heb', 'תִּקְוָה', '["tiqvâh"]', '["hope/ her"]', '["n-f"]', 'literally a cord (as an attachment); figuratively, expectancy expectation(-ted), hope, live, thing that I long for.', 'from 6960; (compare 6961)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3456}/[H3456]', 'inflected', 'heb', 'יָשַׁם', '["yâsham"]', '["and/ it was desolate"]', '["v"]', 'to lie waste be desolate.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7581}/H9023/[H7580]', 'inflected', 'heb', 'שְׁאָגָה', '["shᵉʼâgâh"]', '["roaring/ its"]', '["n-f"]', 'a rumbling or moan roaring.', 'from 7580;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4082}/[H1777]', 'inflected', 'heb', 'מְדִינָה', '["mᵉdîynâh"]', '["from/ provinces"]', '["n-f"]', 'properly, a judgeship, i.e. jurisdiction; by implication, a district (as ruled by a judge); generally, a region (× every) province.', 'from 1777;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5474}/[H5462]', 'inflected', 'heb', 'סוּגַר', '["çûwgar"]', '["in <the>/ cage"]', '["n-m"]', 'an inclosure, i.e. cage (for an animal) ward.', 'from 5462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4685D}/[H6679]', 'inflected', 'heb', 'מָצוֹד', '["mâtsôwd"]', '["in <the>/ strongholds"]', '["n-m"]', 'a net (for capturing animals or fishes); a fastness or (beseiging) tower bulwark, hold, munition, net, snare.', 'or (feminine) מְצוֹדָה; or מצֹדָה; from 6679; also (by interchange for 4679)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1818}/H9021/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["in/ blood/ your"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6058}/[H6057]', 'inflected', 'heb', 'עָנֵף', '["ʻânêph"]', '["and/ full of branches"]', '["a"]', 'branching full of branches.', 'from the same as 6057;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4294J}/[H5186]', 'lemma', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["[the] branch of","a branch of","branches of"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1363}/H9023/[H1361]', 'inflected', 'heb', 'גֹּבַהּ', '["gôbahh"]', '["by/ height/ its","in/ height/ its"]', '["n-m"]', 'elation, grandeur, arrogance excellency, haughty, height, high, loftiness, pride.', 'from 1361;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6772}/[H6770]', 'inflected', 'heb', 'צָמָא', '["tsâmâʼ"]', '["and/ thirst"]', '["n-m"]', 'thirst (literally or figuratively) thirst(-y).', 'from 6770;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4294J}/[H5186]', 'inflected', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["from/ [the] branch of"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0905G}/H9024/[H909]', 'inflected', 'heb', 'בַּד', '["bad"]', '["shoots/ its"]', '["n-m"]', 'properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4910}/[H4910]', 'inflected', 'heb', 'מָשַׁל', '["mâshal"]', '["to/ rule"]', '["v"]', 'to rule (have, make to have) dominion, governor, × indeed, reign, (bear, cause to, have) rule(-ing, -r), have power.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7015}\/[H6969]', 'inflected', 'heb', 'קִינָה', '["qîynâh"]', '["<into>/ a lamentation"]', '["n-f"]', 'a dirge (as accompanied by beating the breasts or on instruments) lamentation.', 'from 6969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2549}/[H2568]', 'inflected', 'heb', 'חֲמִישִׁי', '["chămîyshîy"]', '["in the/ fifth [month]"]', '["a"]', 'fifth; also a fifth fifth (part).', 'or חֲמִשִּׁי; ordinal from 2568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9005/{H1875}/[H1875]', 'inflected', 'heb', 'דָּרַשׁ', '["dârash"]', '["¿/ to/ consult"]', '["v"]', 'properly, to tread or frequent; usually to follow (for pursuit or search); by implication, to seek or ask; specifically to worship ask, × at all, care for, × diligently, inquire, make inquisition, (necro-) mancer, question, require, search, seek (for, out), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0977}/H9040/[H977]', 'inflected', 'heb', 'בָּחַר', '["bâchar"]', '["chose/ I"]', '["v"]', 'properly, to try, i.e. (by implication) select acceptable, appoint, choose (choice), excellent, join, be rather, require.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1544}/[H1556]', 'inflected', 'heb', 'גִּלּוּל', '["gillûwl"]', '["and/ by/ [the] idols of"]', '["n-m"]', 'properly, a log (as round); by implication, an idol idol.', 'or (shortened) גִּלֻּל; from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8210G}/[H8210]', 'inflected', 'heb', 'שָׁפַךְ', '["shâphak"]', '["to/ pour out"]', '["v"]', 'to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3615J}/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["to/ complete"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0996G}/H9038/[H995]', 'inflected', 'heb', 'בֵּין', '["bêyn"]', '["and/ between/ them"]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3615G}/H9038/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["to/ make an end of/ them"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7843}/H9038/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["from/ destroying/ them"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2706G}/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["in/ [the] statutes of"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4941G}/H9028/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["judgments/ their"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1544}/H9028/[H1556]', 'inflected', 'heb', 'גִּלּוּל', '["gillûwl"]', '["and/ by/ idols/ their"]', '["n-m"]', 'properly, a log (as round); by implication, an idol idol.', 'or (shortened) גִּלֻּל; from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6327A}/[H6327]', 'inflected', 'heb', 'פּוּץ', '["pûwts"]', '["to/ scatter"]', '["v"]', 'to dash in pieces, literally or figuratively (especially to disperse) break (dash, shake) in (to) pieces, cast (abroad), disperse (selves), drive, retire, scatter (abroad), spread abroad.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2219}/[H2114]', 'inflected', 'heb', 'זָרָה', '["zârâh"]', '["and/ to/ disperse"]', '["v"]', 'to toss about; by implication, to diffuse, winnow cast away, compass, disperse, fan, scatter (away), spread, strew, winnow.', 'a primitive root (compare 2114);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4979}/H9028/[H4976]', 'inflected', 'heb', 'מַתָּנָה', '["mattânâh"]', '["by/ gifts/ their"]', '["n-f"]', 'a present; specifically (in a good sense), a sacrificial offering, (in a bad sense) a bribe gift.', 'feminine of 4976;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8074G}/H9038/[H8074]', 'inflected', 'heb', 'שָׁמֵם', '["shâmêm"]', '["I may make appalled/ them"]', '["v"]', 'to stun (or intransitively, grow numb), i.e. devastate or (figuratively) stupefy (both usually in a passive sense) make amazed, be astonied, (be an) astonish(-ment), (be, bring into, unto, lay, lie, make) desolate(-ion, places), be destitute, destroy (self), (lay, lie, make) waste, wonder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4603}/H9048/[H4603]', 'inflected', 'heb', 'מָעַל', '["mâʻal"]', '["when/ acted unfaithfully/ they"]', '["v"]', 'properly, to cover up; used only figuratively, to act covertly, i.e. treacherously transgress, (commit, do a) trespass(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5207}/H9028/[H5117]', 'inflected', 'heb', 'נִיחוֹחַ', '["nîychôwach"]', '["soothing/ their"]', '["n-m"]', 'properly, restful, i.e. pleasant; abstractly, delight sweet (odour).', 'or נִיחֹחַ; from 5117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1117}/[H1116]', 'lemma', 'heb', 'בָּמָה', '["Bâmâh"]', '["Bamah"]', '["n-pr-loc"]', 'Bamah, a place in Palestine Bamah. See also 1120.', 'the same as 1116;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9003/{H1870G}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["¿/ in/ [the] way? of"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5375H}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ when/ lift up"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4940}/[H8192]', 'inflected', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["like/ [the] clans of"]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4562}/[H631]', 'inflected', 'heb', 'מָסֹרֶת', '["mâçôreth"]', '["in/ [the] bond of"]', '["n-f"]', 'a band bond.', 'from 631;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1305}/[H1305]', 'inflected', 'heb', 'בָּרַר', '["bârar"]', '["and/ I will purge"]', '["v"]', 'to clarify (i.e. brighten), examine, select make bright, choice, chosen, cleanse (be clean), clearly, polished, (shew self) pure(-ify), purge (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6586}/[H6586]', 'inflected', 'heb', 'פָּשַׁע', '["pâshaʻ"]', '["and/ those/ [who] transgress"]', '["v"]', 'to break away (from just authority), i.e. trespass, apostatize, quarrel offend, rebel, revolt, transgress(-ion, -or).', 'a primitive root (identical with through the idea of expansion);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4979}/H9026/[H4976]', 'inflected', 'heb', 'מַתָּנָה', '["mattânâh"]', '["by/ gifts/ your"]', '["n-f"]', 'a present; specifically (in a good sense), a sacrificial offering, (in a bad sense) a bribe gift.', 'feminine of 4976;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1544}/H9026/[H1556]', 'inflected', 'heb', 'גִּלּוּל', '["gillûwl"]', '["and/ by/ idols/ your"]', '["n-m"]', 'properly, a log (as round); by implication, an idol idol.', 'or (shortened) גִּלֻּל; from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4864}/H9026/[H5375]', 'inflected', 'heb', 'מַשְׂאֵת', '["masʼêth"]', '["gifts/ your"]', '["n-f"]', 'properly, (abstractly) a raising (as of the hands in prayer), or rising (of flame); figuratively, an utterance; concretely, a beacon (as raised); a present (as taken), mess, or tribute; figuratively, a reproach (as a burden) burden, collection, sign of fire, (great) flame, gift, lifting up, mess, oblation, reward.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6944G}/H9026/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["holy things/ your"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6942K}/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["and/ I will show holy","and/ I will show myself holy"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0935P}/H9040/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["when/ bring/ I"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5949}/H9026/[H5953]', 'inflected', 'heb', 'עֲלִילָה', '["ʻălîylâh"]', '["practices/ your"]', '["n-f"]', 'an exploit (of God), or a performance (of man, often in a bad sense); by implication, an opportunity act(-ion), deed, doing, invention, occasion, work.', 'or עֲלִלָה; from 5953 in the sense of effecting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6440L}/H9026/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<in>/ faces/ your"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7451H}/H9026/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["wicked deeds/ your"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1870G}/H9026/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["according to/ ways/ your"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H5949}/H9026/[H5953]', 'inflected', 'heb', 'עֲלִילָה', '["ʻălîylâh"]', '["and/ according to/ practices/ your"]', '["n-f"]', 'an exploit (of God), or a performance (of man, often in a bad sense); by implication, an opportunity act(-ion), deed, doing, invention, occasion, work.', 'or עֲלִלָה; from 5953 in the sense of effecting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5197}/[H5197]', 'inflected', 'heb', 'נָטַף', '["nâṭaph"]', '["and/ prophesy"]', '["v"]', 'to ooze, i.e. distil gradually; by implication, to fall in drops; figuratively, to speak by inspiration drop(-ping), prophesy(-et).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6866}/[H6866]', 'inflected', 'heb', 'צָרַב', '["tsârab"]', '["and/ they will be scorched"]', '["v"]', 'to burn burn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1197A}/H9034/[H1198]', 'inflected', 'heb', 'בָּעַר', '["bâʻar"]', '["I have kindled/ it"]', '["v"]', 'to kindle, i.e. consume (by fire or by eating); to be (-come) brutish be brutish, bring (put, take) away, burn, (cause to) eat (up), feed, heat, kindle, set (on fire), waste.', 'a primitive root; also as denominative from 1198');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7670}/[H7665]', 'inflected', 'heb', 'שִׁבְרוֹן', '["shibrôwn"]', '["with/ breaking of"]', '["n-m"]', 'rupture, i.e. a pang; figuratively, ruin breaking, destruction.', 'from 7665;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4814}/[H4843]', 'inflected', 'heb', 'מְרִירוּת', '["mᵉrîyrûwth"]', '["and/ with/ bitterness"]', '["n-f"]', 'bitterness, i.e. (figuratively) grief bitterness.', 'from 4843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2300A}/[H2300]', 'lemma', 'heb', 'חָדַד', '["châdad"]', '["it has been sharpened"]', '["v"]', 'to be (causatively, make) sharp or (figuratively) severe be fierce, sharpen.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8610}/[H8610]', 'inflected', 'heb', 'תָּפַשׂ', '["tâphas"]', '["to/ grasp [it]","to/ wield"]', '["v"]', 'to manipulate, i.e. seize; chiefly to capture, wield, specifically, to overlay; figuratively, to use unwarrantably catch, handle, (lay, take) hold (on, over), stop, × surely, surprise, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3717}/[H3717]', 'inflected', 'heb', 'כָּפַל', '["kâphal"]', '["so/ it may be doubled"]', '["v"]', 'to fold together; figuratively, to repeat double.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2314}/[H2314]', 'inflected', 'heb', 'חָדַר', '["châdar"]', '["which/ surrounds"]', '["v"]', 'properly, to inclose (as a room), i.e. (by analogy,) to beset (as in a siege) enter a privy chamber.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4127}/[H4127]', 'inflected', 'heb', 'מוּג', '["mûwg"]', '["to/ melt"]', '["v"]', 'to melt, i.e. literally (to soften, flow down, disappear), or figuratively (to fear, faint) consume, dissolve, (be) faint(-hearted), melt (away), make soft.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4383}/[H3782]', 'inflected', 'heb', 'מִכְשׁוֹל', '["mikshôwl"]', '["the/ stumblings"]', '["n-m"]', 'a stumbling-block, literally or figuratively (obstacle, enticement (specifically an idol), scruple) caused to fall, offence, × (no-) thing offered, ruin, stumbling-block.', 'or מִכְשֹׁל; masculine from 3782;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8179G}/H9028/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["gates/ their"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0019>', 'opaque', 'heb', 'אִבְחָה', '["ʼibchâh"]', '["a slaughter of"]', '["n-f"]', 'brandishing of a sword point.', 'from an unused root (apparently meaning to turn);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1300B}/[H1299]', 'inflected', 'heb', 'בָּרָק', '["bârâq"]', '["for/ lightning"]', '["n-m"]', 'lightning; by analogy, a gleam; concretely, a flashing sword bright, glitter(-ing sword), lightning.', 'from 1299;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4593}/[H4591]', 'lemma', 'heb', 'מָעֹט', '["mâʻôṭ"]', '["wrapped"]', '["n"]', 'thinned (as to the edge), i.e. sharp wrapped up.', 'passive adjective of 4591;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0258}/[H258]', 'lemma', 'heb', 'אָחַד', '["ʼâchad"]', '["be sharp"]', '["v"]', 'to unify, i.e. (figuratively) collect (one''s thoughts) go one way or other.', 'perhaps a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7080}/[H7080]', 'inflected', 'heb', 'קָסַם', '["qâçam"]', '["to/ divine"]', '["v"]', 'properly, to distribute, i.e. determine by lot or magical scroll; by implication, to divine divine(-r, -ation), prudent, soothsayer, use (divination).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8655}/[H7495]', 'inflected', 'heb', 'תְּרָפִים', '["tᵉrâphîym"]', '["by the/ teraphim"]', '["n-m"]', 'Teraphim (singular or plural) a family idol idols(-atry), images, teraphim.', 'plural from 7495; a healer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3516}/[H3515]', 'inflected', 'heb', 'כָּבֵד', '["kâbêd"]', '["at the/ liver"]', '["n-f"]', 'the liver (as the heaviest of the viscera) liver.', 'the same as 3515;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7081}/[H7080]', 'inflected', 'heb', 'קֶסֶם', '["qeçem"]', '["the/ divination"]', '["n-m"]', 'a lot; also divination (including its fee), oracle (reward of) divination, divine sentence, witchcraft.', 'from 7080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8210I}/[H8210]', 'inflected', 'heb', 'שָׁפַךְ', '["shâphak"]', '["to/ pour out"]', '["v"]', 'to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7080}/[H7080]', 'inflected', 'heb', 'קָסַם', '["qâçam"]', '["as/ divines"]', '["v"]', 'properly, to distribute, i.e. determine by lot or magical scroll; by implication, to divine divine(-r, -ation), prudent, soothsayer, use (divination).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8610}\/[H8610]', 'inflected', 'heb', 'תָּפַשׂ', '["tâphas"]', '["to/ be seized"]', '["v"]', 'to manipulate, i.e. seize; chiefly to capture, wield, specifically, to overlay; figuratively, to use unwarrantably catch, handle, (lay, take) hold (on, over), stop, × surely, surprise, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2142}/H9046/[H2145]', 'inflected', 'heb', 'זָכַר', '["zâkar"]', '["brought to remembrance/ you","have been remembered/ you"]', '["v"]', 'properly, to mark (so as to be recognized), i.e. to remember; by implication, to mention; to be male × burn (incense), × earnestly, be male, (make) mention (of), be mindful, recount, record(-er), remember, make to be remembered, bring (call, come, keep, put) to (in) remembrance, × still, think on, × well.', 'a primitive root; also as denominative from 2145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5771H}/H9026/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["iniquity/ your"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8610}\/[H8610]', 'inflected', 'heb', 'תָּפַשׂ', '["tâphas"]', '["you will be seized"]', '["v"]', 'to manipulate, i.e. seize; chiefly to capture, wield, specifically, to overlay; figuratively, to use unwarrantably catch, handle, (lay, take) hold (on, over), stop, × surely, surprise, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2491B}/[H2490]', 'lemma', 'heb', 'חָלָל', '["châlâl"]', '["O profane [one]","[those] profaned of"]', '["n-m"]', 'pierced (especially to death); figuratively, polluted kill, profane, slain (man), × slew, (deadly) wounded.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7093}\/[H7112]', 'inflected', 'heb', 'קֵץ', '["qêts"]', '["[the] end"]', '["n-m"]', 'an extremity; adverbially (with prepositional prefix) after after, (utmost) border, end, (in-) finite, × process.', 'contracted from 7112;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5850}/[H5849]', 'inflected', 'heb', 'עֲטָרָה', '["ʻăṭârâh"]', '["the/ crown"]', '["n-f"]', 'a crown crown.', 'from 5849;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8217}/[H8213]', 'inflected', 'heb', 'שָׁפָל', '["shâphâl"]', '["the/ lowly"]', '["a"]', 'depressed, literally or figuratively base(-st), humble, low(-er, -ly).', 'from 8213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5754}/[H5753]', 'lemma', 'heb', 'עַוָּה', '["ʻavvâh"]', '["a ruin"]', '["n-f"]', 'overthrow × overturn.', 'intensive from 5753 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414G}/H9033\/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I will give/ it"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2372}/[H2372]', 'inflected', 'heb', 'חָזָה', '["châzâh"]', '["when/ see"]', '["v"]', 'to gaze at; mentally to perceive, contemplate (with pleasure); specifically, to have a vision of behold, look, prophesy, provide, see.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7080}/[H7080]', 'inflected', 'heb', 'קָסַם', '["qâçam"]', '["when/ divine"]', '["v"]', 'properly, to distribute, i.e. determine by lot or magical scroll; by implication, to divine divine(-r, -ation), prudent, soothsayer, use (divination).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8593}/H9024/[H6168]', 'inflected', 'heb', 'תַּעַר', '["taʻar"]', '["sheath/ its"]', '["n"]', 'a knife or razor (as making bare); also a scabbard (as being bare, i.e. empty) (pen-) knife, razor, scabbard, shave, sheath.', 'from 6168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414N}/H9032/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I will give/ you"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3045}/H9034/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["and/ you will make known to/ it"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1544}/H9022/[H1556]', 'inflected', 'heb', 'גִּלּוּל', '["gillûwl"]', '["and/ by/ idols/ your"]', '["n-m"]', 'properly, a log (as round); by implication, an idol idol.', 'or (shortened) גִּלֻּל; from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117G>/H9022', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["days/ your"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8141}/H9022/[H8138]', 'inflected', 'heb', 'שָׁנֶה', '["shâneh"]', '["years/ your"]', '["n-f"]', 'a year (as a revolution of time) whole age, × long, old, year(× -ly).', '(in plural or (feminine) שָׁנָה; from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7048}/[H7046]', 'inflected', 'heb', 'קַלָּסָה', '["qallâçâh"]', '["and/ derision"]', '["n-f"]', 'ridicule mocking.', 'intensive from 7046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7046}/[H7046]', 'lemma', 'heb', 'קָלַס', '["qâlaç"]', '["it derides","they will deride"]', '["v"]', 'to disparage, i.e. ridicule mock, scoff, scorn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2220}/H9023/[H2232]', 'inflected', 'heb', 'זְרוֹעַ', '["zᵉrôwaʻ"]', '["to/ strength/ his"]', '["n-f"]', 'the arm (as stretched out), or (of animals) the foreleg; figuratively, force arm, help, mighty, power, shoulder, strength.', 'or (shortened) זְרֹעַ; and (feminine) זְרוֹעָה; or זְרֹעָה; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1214I}/[H1214]', 'inflected', 'heb', 'בָּצַע', '["bâtsaʻ"]', '["and/ you have made unjust gain"]', '["v"]', 'to break off, i.e. (usually) plunder; figuratively, to finish, or (intransitively) stop (be) covet(-ous), cut (off), finish, fulfill, gain (greedily), get, be given to (covetousness), greedy, perform, be wounded.', 'a primitive root');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7453}/H9022/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["neighbor/ your"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2219}/H9032/[H2114]', 'inflected', 'heb', 'זָרָה', '["zârâh"]', '["and/ I will disperse/ you"]', '["v"]', 'to toss about; by implication, to diffuse, winnow cast away, compass, disperse, fan, scatter (away), spread, strew, winnow.', 'a primitive root (compare 2114);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2932}/H9022/[H2930]', 'inflected', 'heb', 'טֻמְאָה', '["ṭumʼâh"]', '["uncleanness/ your"]', '["n-f"]', 'religious impurity filthiness, unclean(-ness).', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0913}/[H914]', 'inflected', 'heb', 'בְּדִיל', '["bᵉdîyl"]', '["and/ tin"]', '["n-m"]', 'alloy (because removed by smelting); by analogy, tin plummet, tin.', 'from 914;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6910}/[H6908]', 'lemma', 'heb', 'קְבֻצָה', '["qᵉbutsâh"]', '["[the] gathering of"]', '["n-f"]', 'a hoard × gather.', 'feminine passive participle of 6908;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5301}/[H5301]', 'inflected', 'heb', 'נָפַח', '["nâphach"]', '["to/ blow"]', '["v"]', 'to puff, in various applications (literally, to inflate, blow hard, scatter, kindle, expire; figuratively, to disesteem) blow, breath, give up, cause to lose (life), seething, snuff.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5413}/[H5413]', 'inflected', 'heb', 'נָתַךְ', '["nâthak"]', '["to/ melt [it]"]', '["v"]', 'to flow forth (literally or figuratively); by implication, to liquify drop, gather (together), melt, pour (forth, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3664}/[H3664]', 'inflected', 'heb', 'כָּנַס', '["kânaç"]', '["and/ I will gather"]', '["v"]', 'to collect; hence, to enfold gather (together), heap up, wrap self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2046}/[H5413]', 'inflected', 'heb', 'הִתּוּךְ', '["hittûwk"]', '["like/ [the] melting of"]', '["n-m"]', 'a melting is melted.', 'from 5413;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1656}/H9024/[H1652]', 'inflected', 'heb', 'גֹּשֶׁם', '["gôshem"]', '["rain/ its"]', '["n-m"]', 'rained upon.', 'from 1652; equivalent to 1653');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0490}/H9024/[H488]', 'inflected', 'heb', 'אַלְמָנָה', '["ʼalmânâh"]', '["widows/ its"]', '["n-f"]', 'a widow; also a desolate place desolate house (palace), widow.', 'feminine of 488;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2455}/[H2490]', 'inflected', 'heb', 'חֹל', '["chôl"]', '["and/ a profane thing"]', '["n-m"]', 'properly, exposed; hence, profane common, profane (place), unholy.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H7676}/H9020/[H7673]', 'inflected', 'heb', 'שַׁבָּת', '["shabbâth"]', '["and/ from/ sabbaths/ my"]', '["n"]', 'intermission, i.e (specifically) the Sabbath ( every) sabbath.', 'intensive from 7673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H2061>', 'inflected', 'heb', 'כזאבים', '["ki/z.''e.Vim"]', '["[are] like/ wolves"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5030}/H9024/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["and/ prophets/ its"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7843}/H9034/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["to destroy/ it"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5271A}/H9029/[H5288]', 'inflected', 'heb', 'נָעוּר', '["nâʻûwr"]', '["in/ youth<s>/ their"]', '["n-m n-f"]', '(only in plural collective or emphatic form) youth, the state (juvenility) or the persons (young people) childhood, youth.', 'or נָעֻר; and (feminine) נְעֻרָה; properly, passive participle from 5288 as denominative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7699A}/H9029/[H7736]', 'inflected', 'heb', 'שַׁד', '["shad"]', '["breasts/ their"]', '["n-m"]', 'the breast of a woman or animal (as bulging) breast, pap, teat.', 'or שֹׁד; probably from 7736 (in its original sense) contracted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213B}/[H6213]', 'lemma', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["they had squeezed","they squeezed"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1717}/[H1730]', 'lemma', 'heb', 'דַּד', '["dad"]', '["[the] nipples of"]', '["n-m"]', 'the breast (as the seat of love, or from its shape) breast, teat.', 'apparently from the same as 1730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1331}/H9029/[H1330]', 'inflected', 'heb', 'בְּתוּלִים', '["bᵉthûwlîym"]', '["virginiti<es>/ their"]', '["n-f"]', '(collectively and abstractly) virginity; by implication and concretely, the tokens of it × maid, virginity.', 'masculine plural of the same as 1330;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8034}/H9029/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["and/ names/ their"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0170}/[H168]', 'lemma', 'heb', 'אׇהֳלָה', '["ʼOhŏlâh"]', '["Oholah","[was] Oholah"]', '["n-pr-f"]', 'Oholah, a symbolic name for Samaria Aholah.', 'in form a feminine of 168, but in fact for אׇהֳלָהּ; from 168; her tent (i.e. idolatrous sanctuary);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0172}/[H170]', 'inflected', 'heb', 'אׇהֳלִיבָה', '["ʼOhŏlîybâh"]', '["and/ [was] Oholibah"]', '["n-pr-f"]', 'Oholibah, a symbolic name for Judah Aholibah.', '(similarly with 170) for אׇהֳלִיבָהּ ; from 168; my tent (is) in her;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0172}/[H170]', 'lemma', 'heb', 'אׇהֳלִיבָה', '["ʼOhŏlîybâh"]', '["O Oholibah","Oholibah"]', '["n-pr-f"]', 'Oholibah, a symbolic name for Judah Aholibah.', '(similarly with 170) for אׇהֳלִיבָהּ ; from 168; my tent (is) in her;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5689}/[H5689]', 'inflected', 'heb', 'עֲגַב', '["ʻăgab"]', '["and/ she lusted"]', '["v"]', 'to breathe after, i.e. to love (sensually) dote, lover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8457}/H9024/[H2181]', 'inflected', 'heb', 'תַּזְנוּת', '["taznûwth"]', '["prostitution<s>/ her"]', '["n-f"]', 'harlotry, i.e. (figuratively) idolatry fornication, whoredom.', 'or תַּזְנֻת; from 2181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8457}/H9028/[H2181]', 'inflected', 'heb', 'תַּזְנוּת', '["taznûwth"]', '["prostitution/ their"]', '["n-f"]', 'harlotry, i.e. (figuratively) idolatry fornication, whoredom.', 'or תַּזְנֻת; from 2181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8196}/[H8199]', 'inflected', 'heb', 'שְׁפוֹט', '["shᵉphôwṭ"]', '["and/ judgments"]', '["n-m"]', 'a judicial sentence, i.e. punishment judgment.', 'or שְׁפוּט; from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5691}/H9024/[H5689]', 'inflected', 'heb', 'עֲגָבָה', '["ʻăgâbâh"]', '["lust/ her"]', '["n-f"]', 'love (abstractly), i.e. amorousness inordinate love.', 'from 5689;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2183}/[H2181]', 'inflected', 'heb', 'זָנוּן', '["zânûwn"]', '["more than/ [the] prostitutions of"]', '["n-m"]', 'adultery; figuratively, idolatry whoredom.', 'from 2181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4358}/[H3634]', 'lemma', 'heb', 'מִכְלוֹל', '["miklôwl"]', '["perfection"]', '["n-m"]', 'perfection (i.e. concrete adverbial, splendidly) most gorgeously, all sorts.', 'from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8147}/H9029/[H8145]', 'inflected', 'heb', 'שְׁנַיִם', '["shᵉnayim"]', '["[belonged] to/ both of/ them"]', '["n"]', 'two; also (as ordinal) twofold both, couple, double, second, twain, twelfth, twelve, twenty (sixscore) thousand, twice, two.', 'dual of 8145; feminine שְׁתַּיִם;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2289}/[H2296]', 'lemma', 'heb', 'חָגוֹר', '["châgôwr"]', '["girded of"]', '["n-m"]', 'belted girded with.', 'from 2296;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2871}/[H2881]', 'lemma', 'heb', 'טָבוּל', '["ṭâbûwl"]', '["turbans"]', '["n-m"]', 'properly, dyed, i.e. a turban (probably as of colored stuff) dyed attire.', 'passive participle of 2881;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4138}/H9028/[H3205]', 'inflected', 'heb', 'מוֹלֶדֶת', '["môwledeth"]', '["kindred/ their"]', '["n-f"]', 'nativity (plural birth-place); by implication, lineage, native country; also offspring, family begotten, born, issue, kindred, native(-ity).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5689}/H9012/[H5689]', 'inflected', 'heb', 'עֲגַב', '["ʻăgab"]', '["and/ she lusted/ !"]', '["v"]', 'to breathe after, i.e. to love (sensually) dote, lover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8457}/H9028/[H2181]', 'inflected', 'heb', 'תַּזְנוּת', '["taznûwth"]', '["by/ prostitution/ their"]', '["n-f"]', 'harlotry, i.e. (figuratively) idolatry fornication, whoredom.', 'or תַּזְנֻת; from 2181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5361}/[H5361]', 'lemma', 'heb', 'נָקַע', '["nâqaʻ"]', '["it had been alienated","it has been alienated","it was alienated"]', '["v"]', 'to feel aversion be alienated.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6370>/H9028', 'opaque', 'heb', 'פִּילֶגֶשׁ', '["pîylegesh"]', '["paramours/ their"]', '["n-f"]', 'a concubine; also (masculine) a paramour concubine, paramour.', 'or פִּלֶגֶשׁ; of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2231}/[H2230]', 'inflected', 'heb', 'זִרְמָה', '["zirmâh"]', '["and/ [was the] ejaculation of"]', '["n-f"]', 'a gushing of fluid (semen) issue.', 'feminine of 2230;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2231}/H9028/[H2230]', 'inflected', 'heb', 'זִרְמָה', '["zirmâh"]', '["ejaculation/ their"]', '["n-f"]', 'a gushing of fluid (semen) issue.', 'feminine of 2230;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6213B}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["when/ squeezed"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1717}/H9022/[H1730]', 'inflected', 'heb', 'דַּד', '["dad"]', '["nipples/ your"]', '["n-m"]', 'the breast (as the seat of love, or from its shape) breast, teat.', 'apparently from the same as 1730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5271A}/H9022\/[H5288]', 'inflected', 'heb', 'נָעוּר', '["nâʻûwr"]', '["youth<s>/ your"]', '["n-m n-f"]', '(only in plural collective or emphatic form) youth, the state (juvenility) or the persons (young people) childhood, youth.', 'or נָעֻר; and (feminine) נְעֻרָה; properly, passive participle from 5288 as denominative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7772}/[H7771]', 'inflected', 'heb', 'שׁוֹעַ', '["Shôwaʻ"]', '["and/ Shoa"]', '["n-pr-m"]', 'Shoa, an Oriental people Shoa.', 'the same as 7771; rich;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6970}/[H6972]', 'inflected', 'heb', 'קוֹעַ', '["Qôwaʻ"]', '["and/ Koa"]', '["n-pr-loc"]', 'Koa, a region of Babylon Koa.', 'probably from 6972 in the original sense of cutting off; curtailment;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2021>', 'opaque', 'heb', 'הֹצֶן', '["hôtsen"]', '["weapon[s]"]', '["n-m"]', 'a weapon of war chariot.', 'from an unused root meaning apparently to be sharp or strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1534}/[H1556]', 'inflected', 'heb', 'גַּלְגַּל', '["galgal"]', '["and/ wheel[s]"]', '["n-m"]', 'a wheel; by analogy, a whirlwind; also dust (as whirled) heaven, rolling thing, wheel.', 'by reduplication from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6959}/[H3553]', 'inflected', 'heb', 'קוֹבַע', '["qôwbaʻ"]', '["and/ helmet"]', '["n-m"]', 'a helmet helmet.', 'a form collateral to 3553;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4941G}/H9028/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["by/ judgments/ their"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0241G}/H9022/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["and/ ears/ your"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0319}/H9022/[H310]', 'inflected', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["and/ remainder/ your"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6584}/H9032/[H6584]', 'inflected', 'heb', 'פָּשַׁט', '["pâshaṭ"]', '["and/ they will strip off/ you"]', '["v"]', 'to spread out (i.e. deploy in hostile array); by analogy, to strip (i.e. unclothe, plunder, flay, etc.) fall upon, flay, invade, make an invasion, pull off, put off, make a road, run upon, rush, set, spoil, spread selves (abroad), strip (off, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414G}/H9032/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["[am] about to give/ you"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3018}/H9022/[H3021]', 'inflected', 'heb', 'יְגִיעַ', '["yᵉgîyaʻ"]', '["property/ your"]', '["n-m"]', 'toil; hence, a work, produce, property (as the result of labor) labour, work.', 'from 3021;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5800A}/H9032/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["and/ they will leave/ you"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2183}/H9022/[H2181]', 'inflected', 'heb', 'זָנוּן', '["zânûwn"]', '["prostitutions/ your"]', '["n-m"]', 'adultery; figuratively, idolatry whoredom.', 'from 2181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2154}/H9022/[H2161]', 'inflected', 'heb', 'זִמָּה', '["zimmâh"]', '["and/ licentiousness/ your"]', '["n-f"]', 'a plan, especially a bad one heinous crime, lewd(-ly, -ness), mischief, purpose, thought, wicked (device, mind, -ness).', 'or זַמָּה; from 2161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2181}/H9042/[H2181]', 'inflected', 'heb', 'זָנָה', '["zânâh"]', '["because/ acted as a prostitute/ you"]', '["v"]', 'to commit adultery (usually of the female, and less often of simple fornication, rarely of involuntary ravishment); figuratively, to commit idolatry (the Jewish people being regarded as the spouse of Jehovah) (cause to) commit fornication, × continually, × great, (be an, play the) harlot, (cause to be, play the) whore, (commit, fall to) whoredom, (cause to) go a-whoring, whorish.', 'a primitive root [highly fed and therefore wanton];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3563A>/H9024', 'opaque', 'heb', 'כּוֹס', '["kôwç"]', '["cup/ her"]', '["n-f"]', 'a cup (as a container), often figuratively, a lot (as if a potion); also some unclean bird, probably an owl (perhaps from the cup-like cavity of its eye) cup, (small) owl. Compare 3599.', 'from an unused root meaning to hold together;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027G}/H9022\/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["in/ hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6013}/[H6009]', 'inflected', 'heb', 'עָמֹק', '["ʻâmôq"]', '["<the>/ deep"]', '["a"]', 'deep (literally or figuratively) (× exceeding) deep (thing).', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7342H}/[H7337]', 'inflected', 'heb', 'רָחָב', '["râchâb"]', '["and/ <the>/ wide"]', '["a"]', 'roomy, in any (or every) direction, literally or figuratively broad, large, at liberty, proud, wide.', 'from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6712}/[H6711]', 'inflected', 'heb', 'צְחֹק', '["tsᵉchôq"]', '["<into>/ laughter"]', '["n-m"]', 'laughter (in pleasure or derision) laugh(-ed to scorn).', 'from 6711;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3933}/[H3932]', 'inflected', 'heb', 'לַעַג', '["laʻag"]', '["and/ <into>/ mockery"]', '["n-m"]', 'derision, scoffing derision, scorn (-ing).', 'from 3932;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4767}/[H7235]', 'lemma', 'heb', 'מִרְבָּה', '["mirbâh"]', '["much"]', '["n-f"]', 'abundance, i.e. a great quantity much.', 'from 7235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2789}/H9024/[H2775]', 'inflected', 'heb', 'חֶרֶשׂ', '["cheres"]', '["fragments/ its"]', '["n-m"]', 'a piece of pottery earth(-en), (pot-) sherd, stone.', 'a collateral form mediating between 2775 and 2791;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1458}/H9022/[H1460]', 'inflected', 'heb', 'גַּו', '["gav"]', '["back/ your"]', '["n-m"]', 'the back back.', 'another form for 1460;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8457}/H9022\/[H2181]', 'inflected', 'heb', 'תַּזְנוּת', '["taznûwth"]', '["prostitution<s>/ your"]', '["n-f"]', 'harlotry, i.e. (figuratively) idolatry fornication, whoredom.', 'or תַּזְנֻת; from 2181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8441}/H9029/[H8581]', 'inflected', 'heb', 'תּוֹעֵבַה', '["tôwʻêbah"]', '["abominations/ their"]', '["n-f"]', 'properly, something disgusting (morally), i.e. (as noun) an abhorrence; especially idolatry or (concretely) an idol abominable (custom, thing), abomination.', 'or תֹּעֵבַה; feminine active participle of 8581;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027G}/H9029/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["[is] on/ hands/ their"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1544}/H9029/[H1556]', 'inflected', 'heb', 'גִּלּוּל', '["gillûwl"]', '["idols/ their"]', '["n-m"]', 'properly, a log (as round); by implication, an idol idol.', 'or (shortened) גִּלֻּל; from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121A}/H9029/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["children/ their"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7819A}/H9048/[H7819]', 'inflected', 'heb', 'שָׁחַט', '["shâchaṭ"]', '["and/ when/ had slaughtered/ they"]', '["v n-f"]', 'to slaughter (in sacrifice or massacre) kill, offer, shoot out, slay, slaughter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1544}/H9028/[H1556]', 'inflected', 'heb', 'גִּלּוּל', '["gillûwl"]', '["to/ idols/ their"]', '["n-m"]', 'properly, a log (as round); by implication, an idol idol.', 'or (shortened) גִּלֻּל; from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3583}/[H3583]', 'lemma', 'heb', 'כָּחַל', '["kâchal"]', '["you painted"]', '["v"]', 'to paint (with stibium) paint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5436}/[H5434]', 'lemma', 'heb', 'סְבָאִי', '["Çᵉbâʼîy"]', '["Sabeans"]', '["n"]', 'a Sebaite, or inhabitant of Seba Sabean.', 'patrial from 5434;');
