INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1087}/[H1086]', 'inflected', 'heb', 'בָּלֶה', '["bâleh"]', '["of the/ [woman] worn out"]', '["a"]', 'worn out old.', 'from 1086;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5004}/[H5003]', 'lemma', 'heb', 'נִאֻף', '["niʼuph"]', '["adulteries"]', '["n-m"]', 'adultery adultery.', 'from 5003;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027G}/H9029\/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["[is] on/ hands/ their"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0957}/[H962]', 'inflected', 'heb', 'בַּז', '["baz"]', '["and/ to/ spoil"]', '["n-m"]', 'plunder booty, prey, spoil(-ed).', 'from 962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1004B}/H9029/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ houses/ their"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2154}/H9027/[H2161]', 'inflected', 'heb', 'זִמָּה', '["zimmâh"]', '["like/ licentiousness/ your"]', '["n-f"]', 'a plan, especially a bad one heinous crime, lewd(-ly, -ness), mischief, purpose, thought, wicked (device, mind, -ness).', 'or זַמָּה; from 2161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2154}/H9027/[H2161]', 'inflected', 'heb', 'זִמָּה', '["zimmâh"]', '["licentiousness/ your"]', '["n-f"]', 'a plan, especially a bad one heinous crime, lewd(-ly, -ness), mischief, purpose, thought, wicked (device, mind, -ness).', 'or זַמָּה; from 2161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5921A}/H9037/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["to/ you"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2399}/[H2398]', 'inflected', 'heb', 'חֵטְא', '["chêṭᵉʼ"]', '["and/ [the] sins of"]', '["n-m"]', 'a crime or its penalty fault, × grievously, offence, (punishment of) sin.', 'from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1544}/H9027/[H1556]', 'inflected', 'heb', 'גִּלּוּל', '["gillûwl"]', '["idols/ your"]', '["n-m"]', 'properly, a log (as round); by implication, an idol idol.', 'or (shortened) גִּלֻּל; from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5409}/H9024/[H5408]', 'inflected', 'heb', 'נֵתַח', '["nêthach"]', '["pieces of meat/ its"]', '["n-m"]', 'a fragment part, piece.', 'from 5408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3802>', 'inflected', 'heb', 'וכתפות', '["ve./kha.Tef","ve./khit.Fot"]', '["and/ [the] sides of","and/ shoulder"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1752}/[H1752]', 'lemma', 'heb', 'דּוּר', '["dûwr"]', '["pile up"]', '["v"]', 'properly, to gyrate (or move in a circle), i.e. to remain dwell.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7571}/H9024/[H7570]', 'inflected', 'heb', 'רֶתַח', '["rethach"]', '["boiling/ its"]', '["n-m"]', 'a boiling × (boil) well.', 'from 7570;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6106G}/H9024/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["bones/ its"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H8432>/H9024\', 'inflected', 'heb', 'בתוכה ס', '["be./to.Kha/h","ve./to.Kha/h"]', '["in/ [the] middle of/ it","in/ [the] midst of/ it"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2457}/H9024/[H2456]', 'inflected', 'heb', 'חֶלְאָה', '["chelʼâh"]', '["rust/ its"]', '["n-f"]', 'properly, disease; hence, rust scum.', 'from 2456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2457}/H9024/[H2456]', 'inflected', 'heb', 'חֶלְאָה', '["chelʼâh"]', '["and/ rust/ its"]', '["n-f"]', 'properly, disease; hence, rust scum.', 'from 2456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6706}/[H6705]', 'lemma', 'heb', 'צְחִיחַ', '["tsᵉchîyach"]', '["bareness of"]', '["n-m"]', 'glaring, i.e. exposed to the bright sun higher place, top.', 'from 6705;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7760H}/H9033/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["it put/ it"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4071}/[H1752]', 'inflected', 'heb', 'מְדוּרָה', '["mᵉdûwrâh"]', '["the/ pile"]', '["n-f"]', 'a pile of fuel pile (for fire).', 'or מְדֻרָה; from 1752 in the sense of accumulation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7543}/[H7543]', 'inflected', 'heb', 'רָקַח', '["râqach"]', '["and/ mix"]', '["v"]', 'to perfume apothecary, compound, make (ointment), prepare, spice.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4841}/[H4840]', 'inflected', 'heb', 'מֶרְקָחָה', '["merqâchâh"]', '["the/ seasoning"]', '["n-f"]', 'abstractly, a seasoning (with spicery); concretely, an unguentkettle (for preparing spiced oil) pot of ointment, × well.', 'feminine of 4840;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6106G}/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["and/ the/ bones"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5975G}/H9034/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["and/ set/ it"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1513>/H9024', 'opaque', 'heb', 'גֶּחֶל', '["gechel"]', '["burning coals/ its"]', '["n-f"]', 'an ember (burning) coal.', 'or (feminine) גַּחֶלֶת; from an unused root meaning to glow or kindle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5178A}/H9024/[H5154]', 'inflected', 'heb', 'נְחֹשֶׁת', '["nᵉchôsheth"]', '["bronze/ its"]', '["n-m"]', 'copper, hence, something made of that metal, i.e. coin, a fetter; figuratively, base (as compared with gold or silver) brasen, brass, chain, copper, fetter (of brass), filthiness, steel.', 'for 5154;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8383}/[H205]', 'lemma', 'heb', 'תְּאֻן', '["tᵉʼun"]', '["toil<s>"]', '["n-m"]', 'naughtiness, i.e. toil lie.', 'from 205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2932}/H9022/[H2930]', 'inflected', 'heb', 'טֻמְאָה', '["ṭumʼâh"]', '["in/ uncleanness/ your"]', '["n-f"]', 'religious impurity filthiness, unclean(-ness).', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2891}/H9032/[H2891]', 'inflected', 'heb', 'טָהֵר', '["ṭâhêr"]', '["I cleansed/ you"]', '["v"]', 'to be pure (physical sound, clear, unadulterated; Levitically, uncontaminated; morally, innocent or holy) be (make, make self, pronounce) clean, cleanse (self), purge, purify(-ier, self).', 'a primitive root; properly, to be bright; i.e. (by implication)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2932}/H9022/[H2930]', 'inflected', 'heb', 'טֻמְאָה', '["ṭumʼâh"]', '["from/ uncleanness/ your"]', '["n-f"]', 'religious impurity filthiness, unclean(-ness).', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5117}/H9040/[H5117]', 'inflected', 'heb', 'נוּחַ', '["nûwach"]', '["give rest to/ I"]', '["v"]', 'to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H5949}/H9022/[H5953]', 'inflected', 'heb', 'עֲלִילָה', '["ʻălîylâh"]', '["and/ according to/ practices/ your"]', '["n-f"]', 'an exploit (of God), or a performance (of man, often in a bad sense); by implication, an opportunity act(-ion), deed, doing, invention, occasion, work.', 'or עֲלִלָה; from 5953 in the sense of effecting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6287}/H9021/[H6286]', 'inflected', 'heb', 'פְּאֵר', '["pᵉʼêr"]', '["turban/ your"]', '["n-m"]', 'an embellishment, i.e. fancy head-dress beauty, bonnet, goodly, ornament, tire.', 'from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4263}/[H2550]', 'inflected', 'heb', 'מַחְמָל', '["machmâl"]', '["and/ [the] love of"]', '["n-m"]', 'properly, sympathy; pitieth.', 'from 2550; (by paronomasia with 4261) delight');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6287}/H9026/[H6286]', 'inflected', 'heb', 'פְּאֵר', '["pᵉʼêr"]', '["and/ turbans/ your"]', '["n-m"]', 'an embellishment, i.e. fancy head-dress beauty, bonnet, goodly, ornament, tire.', 'from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5275}/H9026/[H5274]', 'inflected', 'heb', 'נַעַל', '["naʻal"]', '["and/ sandals/ your"]', '["n-f"]', 'properly, a sandal tongue; by extension a sandal or slipper (sometimes as a symbol of occupancy, a refusal to marry, or of something valueless) dryshod, (pair of) shoe((-latchet), -s).', 'or (feminine) נַעֲלָה; from 5274;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4159}/[H3302]', 'inflected', 'heb', 'מוֹפֵת', '["môwphêth"]', '["<into>/ a sign"]', '["n-m"]', 'a miracle; by implication, a token or omen miracle, sign, wonder(-ed at).', 'or מֹפֵת; from 3302 in the sense of conspicuousness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3947G}/H9040/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["take/ I"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2045}/[H8085]', 'inflected', 'heb', 'הַשְׁמָעוּת', '["hashmâʻûwth"]', '["for/ information of"]', '["n-f"]', 'announcement to cause to hear.', 'from 8085;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4181}/[H4180]', 'inflected', 'heb', 'מוֹרָשָׁה', '["môwrâshâh"]', '["<into>/ a possession","into/ a possession","to/ a possession"]', '["n-f"]', 'a possession heritage, inheritance, possession.', 'feminine of 4180;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6529}/H9022/[H6509]', 'inflected', 'heb', 'פְּרִי', '["pᵉrîy"]', '["fruit/ your"]', '["n-m"]', 'fruit (literally or figuratively) bough, (first-)fruit(-ful), reward.', 'from 6509;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2461}/H9022/[H2459]', 'inflected', 'heb', 'חָלָב', '["châlâb"]', '["milk/ your"]', '["n-m"]', 'milk (as the richness of kine) cheese, milk, sucking.', 'from the same as 2459;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4769}/[H7257]', 'inflected', 'heb', 'מַרְבֵּץ', '["marbêts"]', '["into/ a resting place of"]', '["n-m"]', 'a reclining place, i.e. fold (for flocks) couching place, place to lie down.', 'from 7257;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4222}/H9041/[H4222]', 'inflected', 'heb', 'מָחָא', '["mâchâʼ"]', '["clapping/ you"]', '["v"]', 'to rub or strike the hands together (in exultation) clap.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7554}/H9041/[H7554]', 'inflected', 'heb', 'רָקַע', '["râqaʻ"]', '["and/ stamping/ you"]', '["v"]', 'to pound the earth (as a sign of passion); by analogy to expand (by hammering); by implication, to overlay (with thin sheets of metal) beat, make broad, spread abroad (forth, over, out, into plates), stamp, stretch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7589>/H9021', 'opaque', 'heb', 'שְׁאָט', '["shᵉʼâṭ"]', '["scorn/ your"]', '["n-m"]', 'contempt despite(-ful).', 'from an unused root meaning to push aside;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3772I}/H9031/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["and/ I will cut off/ you"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0006}/H9031/[H6]', 'inflected', 'heb', 'אָבַד', '["ʼâbad"]', '["and/ I destroyed/ you","and/ I will destroy/ you"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8045}/H9031/[H8045]', 'inflected', 'heb', 'שָׁמַד', '["shâmad"]', '["I will destroy/ you"]', '["v"]', 'to desolate destory(-uction), bring to nought, overthrow, perish, pluck down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8165A}/[H8163]', 'inflected', 'heb', 'שֵׂעִיר', '["Sêʻîyr"]', '["and/ Seir"]', '["n-pr"]', 'Seir, a mountain of Idumaea and its aboriginal occupants, also one in Palestine Seir.', 'formed like 8163; rough;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7156G}/H9011/[H7151]', 'inflected', 'heb', 'קִרְיָתַיִם', '["Qiryâthayim"]', '["and/ Kiriathaim/ <towards>"]', '["n-pr-loc"]', 'Kirjathaim, the name of two placed in Palestine Kiriathaim, Kirjathaim.', 'dual of 7151; double city;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4124G}/[H1]', 'inflected', 'heb', 'מוֹאָב', '["Môwʼâb"]', '["and/ on/ Moab"]', '["n-pr-m n-pr-loc"]', 'Moab, an incestuous son of Lot; also his territory and descendants Moab.', 'from a prolonged form of the prepositional prefix m- and 1; from (her [the mother''s]) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5358}/[H5358]', 'inflected', 'heb', 'נָקַם', '["nâqam"]', '["by/ avenging itself"]', '["v"]', 'to grudge, i.e. avenge or punish avenge(-r, self), punish, revenge (self), × surely, take vengeance.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414I}/H9034/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I will make/ it"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8487H}/[H8486]', 'inflected', 'heb', 'תֵּימָן', '["Têymân"]', '["from/ Teman"]', '["n-pr-m n-pr-loc"]', 'Teman, the name of two Edomites, and of the region and descendant of one of them south, Teman.', 'or תֵּמָן; the same as 8486;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1719A>/H9011', 'inflected', 'heb', 'ודדנה', '["u./de.Da.ne/h"]', '["and/ Dedan/ towards"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5360}/H9020/[H5359]', 'inflected', 'heb', 'נְקָמָה', '["nᵉqâmâh"]', '["vengeance/ my"]', '["n-f"]', 'avengement, whether the act or the passion avenge, revenge(-ing), vengeance.', 'feminine of 5359;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0639G}/H9020/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["according to/ anger/ my"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H2534}/H9020/[H3179]', 'inflected', 'heb', 'חֵמָה', '["chêmâh"]', '["and/ according to/ rage/ my"]', '["n-f"]', 'heat; figuratively, anger, poison (from its fever) anger, bottles, hot displeasure, furious(-ly, -ry), heat, indignation, poison, rage, wrath(-ful). See 2529.', 'or (Daniel 11:44) חֵמָא; from 3179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5360}/[H5359]', 'inflected', 'heb', 'נְקָמָה', '["nᵉqâmâh"]', '["in/ vengeance"]', '["n-f"]', 'avengement, whether the act or the passion avenge, revenge(-ing), vengeance.', 'feminine of 5359;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7589>', 'inflected', 'heb', 'בשאט', '["bi/sh.''At"]', '["with/ scorn","with/ scorn of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3774G}/[H3772]', 'lemma', 'heb', 'כְּרֵתִי', '["Kᵉrêthîy"]', '["[the] Kerethites"]', '["a"]', 'a Kerethite or life-guardsman Cherethims, Cherethites.', 'probably from 3772 in the sense of executioner; (compare 2876) (only collectively in the singular as plural)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5414H}/H9040/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["when/ have put/ I","when/ put/ I"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5927J}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["as/ brings up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1530H}/H9023/[H1556]', 'inflected', 'heb', 'גַּל', '["gal"]', '["<to>/ waves/ its"]', '["n-m"]', 'something rolled, i.e. a heap of stone or dung (plural ruins), by analogy, a spring of water (plural waves) billow, heap, spring, wave.', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5500}/[H5500]', 'inflected', 'heb', 'סָחָה', '["çâchâh"]', '["and/ I will scrape away"]', '["v"]', 'to sweep away scrape.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6706}/[H6705]', 'inflected', 'heb', 'צְחִיחַ', '["tsᵉchîyach"]', '["into/ bareness of"]', '["n-m"]', 'glaring, i.e. exposed to the bright sun higher place, top.', 'from 6705;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4894A}/[H7849]', 'lemma', 'heb', 'מִשְׁטוֹחַ', '["mishṭôwach"]', '["a spreading place of"]', '["n-m"]', 'a spreading-place (to) spread (forth, -ing, upon).', 'or מִשְׁטַח; from 7849;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2764B}/[H2763]', 'lemma', 'heb', 'חֵרֶם', '["chêrem"]', '["a net","nets"]', '["n-m"]', 'physical (as shutting in) a net (either literally or figuratively); usually a doomed object; abstractly extermination (ac-) curse(-d, -d thing), dedicated thing, things which should have been utterly destroyed, (appointed to) utter destruction, devoted (thing), net.', 'or (Zechariah 14:11) חֶרֶם; from 2763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4239}/[H4229]', 'inflected', 'heb', 'מְחִי', '["mᵉchîy"]', '["and/ [the] blow of"]', '["n-m"]', 'a stroke, i.e. battering-ram engines.', 'from 4229;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6904}/H9023/[H6901]', 'inflected', 'heb', 'קֹבֶל', '["qôbel"]', '["battering-ram/ his"]', '["n-m"]', 'a battering-ram war.', 'from 6901 in the sense of confronting (as standing opposite in order to receive);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2346G>/H9022', 'inflected', 'heb', 'בחמותיך', '["be./cho.mo.Ta.yi/kh"]', '["on/ walls/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4026M}/H9022/[H1431]', 'inflected', 'heb', 'מִגְדָּל', '["migdâl"]', '["and/ towers/ your"]', '["n-m"]', 'a tower (from its size or height); by analogy, a rostrum; figuratively, a (pyramidal) bed of flowers castle, flower, tower. Compare the names following.', 'also (in plural) feminine מִגְדָּלָה; from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8229}/[H8228]', 'inflected', 'heb', 'שִׁפְעָה', '["shiphʻâh"]', '["from/ [the] abundance of"]', '["n-f"]', 'copiousness abundance, company, multitude.', 'feminine of 8228;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0080}/H9028/[H79]', 'inflected', 'heb', 'אָבָק', '["ʼâbâq"]', '["dust/ their"]', '["n-m"]', 'light particles (as volatile) (small) dust, powder.', 'from root of 79;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3996}/[H935]', 'inflected', 'heb', 'מָבוֹא', '["mâbôwʼ"]', '["like/ [the] coming of","like/ [the] entering<s> of"]', '["n-m"]', 'an entrance (the place or the act); specifically sunset or the west; also (adverb with preposition) towards by which came, as cometh, in coming, as men enter into, entering, entrance into, entry, where goeth, going down, westward. Compare 4126.', 'from 935; (with or without 8121)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6541}/[H6538]', 'inflected', 'heb', 'פַּרְסָה', '["parçâh"]', '["with/ [the] hooves of"]', '["n-f"]', 'a claw or split hoof claw, (cloven-) footed, hoof.', 'feminine of 6538;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2351>/H9022', 'opaque', 'heb', 'חוּץ', '["chûwts"]', '["streets/ your"]', '["n-m"]', 'properly, separate by a wall, i.e. outside, outdoors abroad, field, forth, highway, more, out(-side, -ward), street, without.', 'or (shortened) חֻץ; (both forms feminine in the plural) from an unused root meaning to sever;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7997B}/[H7997]', 'inflected', 'heb', 'שָׁלַל', '["shâlal"]', '["and/ he will plunder","and/ they will plunder"]', '["v"]', 'to drop or strip; by implication, to plunder let fall, make self a prey, × of purpose, (make a, (take)) spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2428H}/H9022/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["wealth/ your"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7404}/H9022/[H7402]', 'inflected', 'heb', 'רְכֻלָּה', '["rᵉkullâh"]', '["merchandise/ your"]', '["n-f"]', 'trade (as peddled) merchandise, traffic.', 'feminine passive participle of 7402;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2532A}/H9022/[H2531]', 'inflected', 'heb', 'חֶמְדָּה', '["chemdâh"]', '["desire/ your"]', '["n-f"]', 'delight desire, goodly, pleasant, precious.', 'feminine of 2531;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0068G}/H9022/[H1129]', 'inflected', 'heb', 'אֶבֶן', '["ʼeben"]', '["and/ stones/ your"]', '["n-f"]', 'a stone carbuncle, mason, plummet, (chalk-, hail-, head-, sling-) stone(-ny), (divers) weight(-s).', 'from the root of 1129 through the meaning to build;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6086G}/H9022/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["and/ wood<s>/ your"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6083}/H9022/[H6080]', 'inflected', 'heb', 'עָפָר', '["ʻâphâr"]', '["and/ dust/ your"]', '["n-m"]', 'dust (as powdered or gray); hence, clay, earth, mud ashes, dust, earth, ground, morter, powder, rubbish.', 'from 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7892A}/H9022/[H7891]', 'inflected', 'heb', 'שִׁיר', '["shîyr"]', '["songs/ your"]', '["n-m n-f"]', 'a song; abstractly, singing musical(-ick), × sing(-er, -ing), song.', 'or feminine שִׁירָה; from 7891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3658>/H9022', 'opaque', 'heb', 'כִּנּוֹר', '["kinnôwr"]', '["harps/ your"]', '["n-m"]', 'a harp harp.', 'from a unused root meaning to twang;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414I}/H9032/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I will make/ you"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4658}/H9022/[H5307]', 'inflected', 'heb', 'מַפֶּלֶת', '["mappeleth"]', '["downfall/ your"]', '["n-f"]', 'fall, i.e. decadence; concretely, a ruin; specifically a carcase carcase, fall, ruin.', 'from 5307;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0602}/[H602]', 'inflected', 'heb', 'אָנַק', '["ʼânaq"]', '["when/ groan"]', '["v"]', 'to shriek cry, groan.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3678G}/H9028/[H3680]', 'inflected', 'heb', 'כִּסֵּא', '["kiççêʼ"]', '["thrones/ their"]', '["n-m"]', 'properly, covered, i.e. a throne (as canopied) seat, stool, throne.', 'or כִּסֵּה; from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4598}/H9028/[H4603]', 'inflected', 'heb', 'מְעִיל', '["mᵉʻîyl"]', '["robes/ their"]', '["n-m"]', 'a robe (i.e. upper and outer garment) cloke, coat, mantle, robe.', 'from 4603 in the sense of covering;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7553}/H9028/[H7551]', 'inflected', 'heb', 'רִקְמָה', '["riqmâh"]', '["multicolored cloth/ their"]', '["n-f"]', 'variegation of color; specifically, embroidery broidered (work), divers colours, (raiment of) needlework (on both sides).', 'from 7551;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1984B}/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["that/ <it> was praised"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2851}/H9028/[H2865]', 'inflected', 'heb', 'חִתִּית', '["chittîyth"]', '["terror/ their"]', '["n-f"]', 'fear terror.', 'from 2865;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3318G}/H9042\/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["<from>/ because went out/ you"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5414I}/H9040/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["when/ make/ I"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5927J}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["when/ bring up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3680}/H9032/[H3680]', 'inflected', 'heb', 'כָּסָה', '["kâçâh"]', '["and/ they will cover/ you"]', '["v"]', 'properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3381}/H9032/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["and/ I will send down/ you"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3427}/H9032/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["and/ I will cause to dwell/ you"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2723}/[H2721]', 'inflected', 'heb', 'חׇרְבָּה', '["chorbâh"]', '["like/ waste places"]', '["n-f"]', 'properly, drought, i.e. (by implication) a desolation decayed place, desolate (place, -tion), destruction, (laid) waste (place).', 'feminine of 2721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0369}/H9042/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["and/ there not [will be]/ you"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3997}/[H3996]', 'lemma', 'heb', 'מְבוֹאָה', '["mᵉbôwʼâh"]', '["[the] entrances of"]', '["n-f"]', 'a haven entry.', 'feminine of 3996;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3634}/[H3634]', 'lemma', 'heb', 'כָּלַל', '["kâlal"]', '["they perfected"]', '["v"]', 'to complete (make) perfect.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H8149>', 'inflected', 'heb', 'משניר', '["mi./se.Nir"]', '["from/ Senir"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8650}/[H766]', 'lemma', 'heb', 'תֹּרֶן', '["tôren"]', '["a mast"]', '["n-m"]', 'a pole (as a mast or flagstaff) beacon, mast.', 'probably for 766;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4880B}/H9022/[H7751]', 'inflected', 'heb', 'מָשׁוֹט', '["mâshôwṭ"]', '["oars/ your"]', '["n-m"]', 'an oar oar.', 'or מִשּׁוֹט; from 7751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7175>/H9022', 'opaque', 'heb', 'קֶרֶשׁ', '["qeresh"]', '["boards/ your"]', '["n-m"]', 'a slab or plank; by implication, a deck of a ship bench, board.', 'from an unused root meaning to split off;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0839}/[H8391]', 'lemma', 'heb', 'אֲשֻׁר', '["ʼăshur"]', '["pine"]', '["n-f"]', 'the cedar tree or some other light elastic wood Ashurite.', 'contracted for 8391;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0339}/[H183]', 'inflected', 'heb', 'אִי', '["ʼîy"]', '["from/ [the] islands of"]', '["n-m"]', 'properly, a habitable spot (as desirable); dry land, a coast, an island country, isle, island.', 'from 183;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7553}/[H7551]', 'inflected', 'heb', 'רִקְמָה', '["riqmâh"]', '["with/ colorful weaving"]', '["n-f"]', 'variegation of color; specifically, embroidery broidered (work), divers colours, (raiment of) needlework (on both sides).', 'from 7551;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4666}/H9022/[H6566]', 'inflected', 'heb', 'מִפְרָשׂ', '["miphrâs"]', '["sail/ your"]', '["n-m"]', 'an expansion that which...spreadest forth, spreading.', 'from 6566;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0473H}/[H473]', 'lemma', 'heb', 'אֱלִישָׁה', '["ʼĔlîyshâh"]', '["Elishah"]', '["n-pr-m"]', 'Elishah, a son of Javan Elishah.', 'probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4374}/H9022/[H3680]', 'inflected', 'heb', 'מְכַסֶּה', '["mᵉkaççeh"]', '["covering/ your"]', '["n-m"]', 'a covering, i.e. garment; specifically, a coverlet (for a bed), an awning (from the sun); also the omentum (as covering the intestines) clothing, to cover, that which covereth.', 'from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0719}/[H7300]', 'inflected', 'heb', 'אַרְוַד', '["ʼArvad"]', '["and/ Arvad"]', '["n-pr-loc"]', 'Arvad, an island-city of Palestine Arvad.', 'probably from 7300; a refuge for the roving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7751B}/[H7751]', 'lemma', 'heb', 'שׁוּט', '["shûwṭ"]', '["rowers"]', '["v"]', 'properly, to push forth; (but used only figuratively) to lash, i.e. (the sea with oars) to row; by implication, to travel go (about, through, to and fro), mariner, rower, run to and fro.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2450}/H9022/[H2449]', 'inflected', 'heb', 'חָכָם', '["châkâm"]', '["skillful [people]/ your"]', '["a"]', 'wise, (i.e. intelligent, skilful or artful) cunning (man), subtil, (un-), wise((hearted), man).', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2259}/H9022/[H2254]', 'inflected', 'heb', 'חֹבֵל', '["chôbêl"]', '["[were] sailors/ your","sailors/ your"]', '["n-m"]', 'a sailor pilot, shipmaster.', 'active participle from 2254 (in the sense of handling ropes);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1380}/[H1379]', 'lemma', 'heb', 'גְּבַל', '["Gᵉbal"]', '["Gebal"]', '["n-pr-loc"]', 'Gebal, a place in Phoenicia Gebal.', 'from 1379 (in the sense of a chain of hills); a mountain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0919}/H9022/[H918]', 'inflected', 'heb', 'בֶּדֶק', '["bedeq"]', '["leaks/ your"]', '["n-m"]', 'a gap or leak (in a building or a ship) breach, calker.', 'from 918;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4419}/H9028/[H4414]', 'inflected', 'heb', 'מַלָּח', '["mallâch"]', '["and/ mariners/ their"]', '["n-m"]', 'a sailor (as following ''the salt'') mariner.', 'from 4414 in its second. sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6148}/[H6148]', 'inflected', 'heb', 'עָרַב', '["ʻârab"]', '["to/ trade"]', '["v"]', 'to braid, i.e. intermix; technically, to traffic (as if by barter); also or give to be security (as a kind of exchange) engage, (inter-) meddle (with), mingle (self), mortgage, occupy, give pledges, be(-come, put in) surety, undertake.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4627}/H9022/[H6148]', 'inflected', 'heb', 'מַעֲרָב', '["maʻărâb"]', '["merchandise/ your"]', '["n-m"]', 'traffic; by implication, mercantile goods market, merchandise.', 'from 6148, in the sense of trading;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2428A}/H9022/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["in/ army/ your"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4421}/H9022/[H3898]', 'inflected', 'heb', 'מִלְחָמָה', '["milchâmâh"]', '["war/ your"]', '["n-f"]', 'a battle (i.e. the engagement); generally, war (i.e. war-fare) battle, fight(-ing), war(-rior).', 'from 3898 (in the sense of fighting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1926}/H9022/[H1921]', 'inflected', 'heb', 'הָדָר', '["hâdâr"]', '["splendor/ your"]', '["n-m"]', 'magnificence, i.e. ornament or splendor beauty, comeliness, excellency, glorious, glory, goodly, honour, majesty.', 'from 1921;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0719}/[H7300]', 'lemma', 'heb', 'אַרְוַד', '["ʼArvad"]', '["Arvad"]', '["n-pr-loc"]', 'Arvad, an island-city of Palestine Arvad.', 'probably from 7300; a refuge for the roving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2428B}/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["and/ Helech"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1575}/[H1574]', 'inflected', 'heb', 'גַּמָּד', '["gammâd"]', '["and/ [the] Gammadites"]', '["n-m"]', 'a warrior (as grasping weapons) Gammadims.', 'from the same as 1574;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4026M}/H9022/[H1431]', 'inflected', 'heb', 'מִגְדָּל', '["migdâl"]', '["in/ towers/ your"]', '["n-m"]', 'a tower (from its size or height); by analogy, a rostrum; figuratively, a (pyramidal) bed of flowers castle, flower, tower. Compare the names following.', 'also (in plural) feminine מִגְדָּלָה; from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7982}/H9028/[H7980]', 'inflected', 'heb', 'שֶׁלֶט', '["sheleṭ"]', '["shields/ their"]', '["n-m"]', 'probably a shield (as controlling, i.e. protecting the person) shield.', 'from 7980;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0913}/[H914]', 'lemma', 'heb', 'בְּדִיל', '["bᵉdîyl"]', '["tin"]', '["n-m"]', 'alloy (because removed by smelting); by analogy, tin plummet, tin.', 'from 914;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5801}/H9022/[H5800]', 'inflected', 'heb', 'עִזָּבוֹן', '["ʻizzâbôwn"]', '["wares/ your"]', '["n-m"]', 'trade, i.e. the place (mart) or the payment (revenue) fair, ware.', 'from 5800 in the sense of letting go (for a price, i.e. selling);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3120H}/[H3196]', 'lemma', 'heb', 'יָוָן', '["Yâvân"]', '["Greece","Javan","O Greece"]', '["n-pr-m n-pr-loc"]', 'Javan, the name of a son of Joktan, and of the race (Ionians, i.e. Greeks) descended from him, with their territory; also of a place in Arabia Javan.', 'probably from the same as 3196; effervescing (i.e. hot and active);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4902H}/[H4901]', 'inflected', 'heb', 'מֶשֶׁךְ', '["Meshek"]', '["and/ Meshech"]', '["n-pr-m"]', 'Meshek, a son of Japheth, and the people descended from him Mesech, Meshech.', 'the same in form as 4901, but probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7402}/H9022/[H7402]', 'inflected', 'heb', 'רָכַל', '["râkal"]', '["[was] trader/ your","[were] traders/ your"]', '["v"]', 'to travel for trading (spice) merchant.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1004I}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["from/ Beth"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8425H}/[H8425]', 'lemma', 'heb', 'תּוֹגַרְמָה', '["Tôwgarmâh"]', '["Togarmah"]', '["n-pr"]', 'Togarmah, a son of Gomer and his posterity Togarmah.', 'or תֹּגַרְמָה; probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6571A}/[H6567]', 'inflected', 'heb', 'פָּרָשׁ', '["pârâsh"]', '["and/ horsemen"]', '["n-m"]', 'a steed (as stretched out to a vehicle, not single nor for mounting ); also (by implication) a driver (in a chariot), i.e. (collectively) cavalry horseman.', 'from 6567; (compare 5483)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5506}/[H5503]', 'lemma', 'heb', 'סְחֹרָה', '["çᵉchôrâh"]', '["[were] [the] merchandise of"]', '["n-f"]', 'traffic merchandise.', 'from 5503;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027I}/H9022/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1894>', 'inflected', 'heb', 'והבנים', '["ve./hov.nim"]', '["and/ ebony"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0814}/H9022/[H7939]', 'inflected', 'heb', 'אֶשְׁכָּר', '["ʼeshkâr"]', '["tribute/ your"]', '["n-m"]', 'a gratuity gift, present.', 'for 7939;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4639G}/H9022/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["products/ your"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H5306>', 'inflected', 'heb', 'בנפך', '["Be./no.fekh"]', '["for/ turquoise"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7215}/[H7213]', 'inflected', 'heb', 'רָאמָה', '["râʼmâh"]', '["and/ corals"]', '["n-f"]', 'something high in value, i.e. perhaps coral coral.', 'from 7213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3539}/[H3537]', 'inflected', 'heb', 'כַּדְכֹּד', '["kadkôd"]', '["and/ ruby"]', '["n-m"]', 'a sparkling gem, probably the ruby agate.', 'from the same as 3537 in the sense of striking fire from a metal forged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5801}/H9022/[H5800]', 'inflected', 'heb', 'עִזָּבוֹן', '["ʻizzâbôwn"]', '["for/ wares/ your"]', '["n-m"]', 'trade, i.e. the place (mart) or the payment (revenue) fair, ware.', 'from 5800 in the sense of letting go (for a price, i.e. selling);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2406>', 'inflected', 'heb', 'בחטי', '["be./chi.Tei"]', '["for/ [the] wheat<s> of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6436>', 'inflected', 'heb', 'ופנג', '["u./fa.Nag"]', '["and/ cake"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2463}/[H2459]', 'lemma', 'heb', 'חֶלְבּוֹן', '["Chelbôwn"]', '["Helbon"]', '["n-pr-loc"]', 'Chelbon, a place in Syria Helbah.', 'from 2459; fruitful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6785>', 'inflected', 'heb', 'וצמר', '["ve./Tze.mer"]', '["and/ wool of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6713>', 'opaque', 'heb', 'צַחַר', '["tsachar"]', '["Zahar"]', '["n-m"]', 'sheen, i.e. whiteness white.', 'from an unused root meaning to dazzle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2051}/[H5730]', 'lemma', 'heb', 'וְדָן', '["Vᵉdân"]', '["Vedan"]', '["n-pr-loc"]', 'Vedan (or Aden), a place in Arabia Dan also.', 'perhaps for 5730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H0187H>', 'inflected', 'heb', 'מאוזל', '["me./''u.Zal"]', '["from/ Uzal"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6219}/[H6245]', 'lemma', 'heb', 'עָשׁוֹת', '["ʻâshôwth"]', '["wrought"]', '["a"]', 'shining, i.e. polished bright.', 'from 6245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6916}/[H6915]', 'lemma', 'heb', 'קִדָּה', '["qiddâh"]', '["cassia"]', '["n-f"]', 'cassia bark (as in shrivelled rolls) cassia.', 'from 6915;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7070L}/[H7069]', 'inflected', 'heb', 'קָנֶה', '["qâneh"]', '["and/ calamus"]', '["n-m"]', 'a reed (as erect); by resemblance a rod (especially for measuring), shaft, tube, stem, the radius (of the arm), beam (of a steelyard) balance, bone, branch, calamus, cane, reed, × spearman, stalk.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4627}/H9022/[H6148]', 'inflected', 'heb', 'מַעֲרָב', '["maʻărâb"]', '["for/ merchandise/ your"]', '["n-m"]', 'traffic; by implication, mercantile goods market, merchandise.', 'from 6148, in the sense of trading;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2667}/[H2666]', 'lemma', 'heb', 'חֹפֶשׁ', '["Chôphesh"]', '["material"]', '["n-m"]', 'something spread loosely, i.e. a carpet precious.', 'from 2666;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7396}/[H7393]', 'inflected', 'heb', 'רִכְבָּה', '["rikbâh"]', '["for/ riding"]', '["n-f"]', 'a chariot (collectively) chariots.', 'feminine of 7393;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3733C}/[H3769]', 'inflected', 'heb', 'כַּר', '["kar"]', '["for/ lambs"]', '["n-m"]', 'a ram (as full-grown and fat), including a battering-ram (as butting); hence, a meadow (as for sheep); also a pad or camel''s saddle (as puffed out) captain, furniture, lamb, (large) pasture, ram. See also 1033, 3746.', 'from 3769 in the sense of plumpness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7484H}/[H7483]', 'inflected', 'heb', 'רַעְמָה', '["Raʻmâh"]', '["and/ Raamah"]', '["n-pr-m n-pr-loc"]', 'Ramah, the name of a grandson of Ham, and of a place (perhaps founded by him) Raamah.', 'the same as 7483;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3656}/[H3641]', 'inflected', 'heb', 'כַּנֶּה', '["Kanneh"]', '["and/ Canneh"]', '["n-pr-loc"]', 'Canneh, a place in Assyria Canneh.', 'for 3641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5729}/[H5727]', 'inflected', 'heb', 'עֶדֶן', '["ʻEden"]', '["and/ Eden"]', '["n-pr-loc"]', 'Eden, a place in Mesopotamia Eden.', 'from 5727; pleasure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3638}/[H3638]', 'lemma', 'heb', 'כִּלְמָד', '["Kilmâd"]', '["Chilmad"]', '["n-pr-loc"]', 'Kilmad, a place apparently in the Assyrian empire Chilmad.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4360}/[H3634]', 'inflected', 'heb', 'מִכְלֻל', '["miklul"]', '["for/ beautiful garments"]', '["n-m"]', 'something perfect, i.e. a splendid garment all sorts.', 'from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1545}/[H1563]', 'inflected', 'heb', 'גְּלוֹם', '["gᵉlôwm"]', '["for/ garments of"]', '["n-m"]', 'clothing (as wrapped) clothes.', 'from 1563;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H1595>', 'inflected', 'heb', 'ובגנזי', '["u./ve./gin.Zei"]', '["and/ for/ blankets of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1264>', 'opaque', 'heb', 'בְּרוֹם', '["bᵉrôwm"]', '["variegated cloth"]', '["n-m"]', 'damask (stuff of variegated thread) rich apparel.', 'probably of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0729}/[H730]', 'inflected', 'heb', 'אָרַז', '["ʼâraz"]', '["and/ made firm"]', '["a"]', 'of cedar made of cedar.', 'a primitive root; to be firm; used only in the passive participle as a denominative from 730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4819}/H9022/[H7402]', 'inflected', 'heb', 'מַרְכֹּלֶת', '["markôleth"]', '["in/ market place/ your"]', '["n-f"]', 'a mart merchandise.', 'from 7402;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7788}/H9022/[H7788]', 'inflected', 'heb', 'שׁוּר', '["shûwr"]', '["[were] travelers/ your"]', '["v"]', 'properly, to turn, i.e. travel about (as a harlot or a merchant) go, singular See also 7891.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935P}/H9032/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["they brought/ you"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7751B}/[H7751]', 'inflected', 'heb', 'שׁוּט', '["shûwṭ"]', '["the/ rowers"]', '["v"]', 'properly, to push forth; (but used only figuratively) to lash, i.e. (the sea with oars) to row; by implication, to travel go (about, through, to and fro), mariner, rower, run to and fro.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7665}/H9032/[H7665]', 'inflected', 'heb', 'שָׁבַר', '["shâbar"]', '["it broke/ you"]', '["v"]', 'to burst (literally or figuratively) break (down, off, in pieces, up), broken (-hearted), bring to the birth, crush, destroy, hurt, quench, × quite, tear, view (by mistake for 7663).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1952}/H9022/[H1951]', 'inflected', 'heb', 'הוֹן', '["hôwn"]', '["wealth/ your","wealth<s>/ your"]', '["n-m"]', 'wealth; by implication, enough enough, for nought, riches, substance, wealth.', 'from the same as 1951 in the sense of 202;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5801}/H9022/[H5800]', 'inflected', 'heb', 'עִזָּבוֹן', '["ʻizzâbôwn"]', '["and/ wares/ your"]', '["n-m"]', 'trade, i.e. the place (mart) or the payment (revenue) fair, ware.', 'from 5800 in the sense of letting go (for a price, i.e. selling);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4419}/H9022/[H4414]', 'inflected', 'heb', 'מַלָּח', '["mallâch"]', '["mariners/ your"]', '["n-m"]', 'a sailor (as following ''the salt'') mariner.', 'from 4414 in its second. sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2259}/H9022/[H2254]', 'inflected', 'heb', 'חֹבֵל', '["chôbêl"]', '["and/ sailors/ your"]', '["n-m"]', 'a sailor pilot, shipmaster.', 'active participle from 2254 (in the sense of handling ropes);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6148}/[H6148]', 'inflected', 'heb', 'עָרַב', '["ʻârab"]', '["and/ [the] traders of"]', '["v"]', 'to braid, i.e. intermix; technically, to traffic (as if by barter); also or give to be security (as a kind of exchange) engage, (inter-) meddle (with), mingle (self), mortgage, occupy, give pledges, be(-come, put in) surety, undertake.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6951}/H9022/[H6950]', 'inflected', 'heb', 'קָהָל', '["qâhâl"]', '["company/ your"]', '["n-m"]', 'assemblage (usually concretely) assembly, company, congregation, multitude.', 'from 6950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0591}/H9028/[H590]', 'inflected', 'heb', 'אֳנִיָּה', '["ʼŏnîyâh"]', '["from/ ships/ their"]', '["n-f"]', 'a ship ship(-men).', 'feminine of 590;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4880A}/[H7751]', 'lemma', 'heb', 'מָשׁוֹט', '["mâshôwṭ"]', '["<of> an oar"]', '["n-m"]', 'an oar oar.', 'or מִשּׁוֹט; from 7751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4419}/[H4414]', 'lemma', 'heb', 'מַלָּח', '["mallâch"]', '["mariners"]', '["n-m"]', 'a sailor (as following ''the salt'') mariner.', 'from 4414 in its second. sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2259}/[H2254]', 'lemma', 'heb', 'חֹבֵל', '["chôbêl"]', '["[the] sailors of"]', '["n-m"]', 'a sailor pilot, shipmaster.', 'active participle from 2254 (in the sense of handling ropes);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6428}/[H6428]', 'lemma', 'heb', 'פָּלַשׁ', '["pâlash"]', '["roll yourself","they will roll"]', '["v"]', 'to roll (in dust) roll (wallow) self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7139}/[H7139]', 'inflected', 'heb', 'קָרַח', '["qârach"]', '["and/ they will make bald"]', '["v"]', 'to depilate make (self) bald.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5204}/H9028/[H5091]', 'inflected', 'heb', 'נִי', '["nîy"]', '["in/ wailing/ their"]', '["n-m"]', 'lamentation wailing.', 'a doubtful word; apparently from 5091;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6865}/[H6864]', 'inflected', 'heb', 'צֹר', '["Tsôr"]', '["[is] like/ Tyre"]', '["n-pr-loc"]', 'Tsor, a place in Palestine Tyre, Tyrus.', 'or צוֹר; the same as 6864; a rock;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1822}/[H1820]', 'inflected', 'heb', 'דֻּמָּה', '["dummâh"]', '["like/ one silenced"]', '["n-f"]', 'desolation; concretely, desolate destroy.', 'from 1820;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4627}/H9022/[H6148]', 'inflected', 'heb', 'מַעֲרָב', '["maʻărâb"]', '["and/ merchandise<s>/ your"]', '["n-m"]', 'traffic; by implication, mercantile goods market, merchandise.', 'from 6148, in the sense of trading;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8175A}/[H8175]', 'lemma', 'heb', 'שָׂעַר', '["sâʻar"]', '["they have shuddered","they will shudder"]', '["v"]', 'to storm; by implication, to shiver, i.e. fear be (horribly) afraid, fear, hurl as a storm, be tempestuous, come like (take away as with) a whirlwind.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1841H}/[H1840]', 'inflected', 'heb', 'דָּנִיֵּאל', '["Dânîyêʼl"]', '["more than/ Daniel"]', '["n-pr-m"]', 'Danijel, the Hebrew prophet Daniel.', '(Aramaic) corresponding to 1840;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6004}/H9031/[H6004]', 'inflected', 'heb', 'עָמַם', '["ʻâmam"]', '["people hold dark from/ you"]', '["v"]', 'to associate; by implication, to overshadow (by huddling together) become dim, hide.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2451}/H9021/[H2449]', 'inflected', 'heb', 'חׇכְמָה', '["chokmâh"]', '["by/ wisdom/ your"]', '["n-f"]', 'wisdom (in a good sense) skilful, wisdom, wisely, wit.', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8394}/H9021/[H995]', 'inflected', 'heb', 'תָּבוּן', '["tâbûwn"]', '["and/ by/ understanding/ your"]', '["n-m"]', 'intelligence; by implication, an argument; by extension, caprice discretion, reason, skilfulness, understanding, wisdom.', 'and (feminine) תְּבוּנָה; or תּוֹבֻנָה; from 995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0214}/H9021/[H686]', 'inflected', 'heb', 'אוֹצָר', '["ʼôwtsâr"]', '["in/ treasuries/ your"]', '["n-m"]', 'a depository armory, cellar, garner, store(-house), treasure(-house) (-y).', 'from 686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7404}/H9021/[H7402]', 'inflected', 'heb', 'רְכֻלָּה', '["rᵉkullâh"]', '["by/ trading/ your"]', '["n-f"]', 'trade (as peddled) merchandise, traffic.', 'feminine passive participle of 7402;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2428H}/H9021\/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["in/ wealth/ your"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414I}/H9041/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["making/ you"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3314}/H9021/[H3313]', 'inflected', 'heb', 'יִפְעָה', '["yiphʻâh"]', '["splendor/ your"]', '["n-f"]', 'splendor or (figuratively) beauty brightness.', 'from 3313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2490A}/H9031/[H2470]', 'inflected', 'heb', 'חָלַל', '["châlal"]', '["[those who] pierce/ you"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8508}/[H8506]', 'lemma', 'heb', 'תׇּכְנִית', '["toknîyth"]', '["a pattern","an example"]', '["n-f"]', 'admeasurement, i.e. consummation pattern, sum.', 'from 8506;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4540}/H9021/[H5526]', 'inflected', 'heb', 'מְסֻכָּה', '["mᵉçukkâh"]', '["covering/ your"]', '["n-f"]', 'a covering, i.e. garniture covering.', 'from 5526;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1304B}/[H1300]', 'inflected', 'heb', 'בָּרֶקֶת', '["bâreqeth"]', '["and/ beryl"]', '["n-f"]', 'a gem (as flashing), perhaps the emerald carbuncle.', 'or בָּרְקַתxlit bârᵉkath corrected to bârᵉqath; from 1300;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8596}/H9021/[H8608]', 'inflected', 'heb', 'תֹּף', '["tôph"]', '["tambourines/ your"]', '["n-m"]', 'a tambourine tabret, timbrel.', 'from 8608 contracted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5345}/H9021/[H5345]', 'inflected', 'heb', 'נֶקֶב', '["neqeb"]', '["and/ settings/ your"]', '["n-m"]', 'a bezel (for a gem) pipe.', NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1254A}/H9041/[H1254]', 'inflected', 'heb', 'בָּרָא', '["bârâʼ"]', '["are created/ you"]', '["v"]', '(absolutely) to create; (qualified) to cut down (a wood), select, feed (as formative processes) choose, create (creator), cut down, dispatch, do, make (fat).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4473}/[H4886]', 'lemma', 'heb', 'מִמְשַׁח', '["mimshach"]', '["expansion"]', '["n-m"]', 'outspread (i.e. with outstretched wings) anointed.', 'from 4886, in the sense of expansion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5526B}/[H5526]', 'inflected', 'heb', 'סָכַךְ', '["çâkak"]', '["<the>/ [one which] covers"]', '["v"]', 'properly, to entwine as a screen; by implication, to fence in, cover over, (figuratively) protect cover, defence, defend, hedge in, join together, set, shut up.', 'or שָׂכַךְ; (Exodus 33:22), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5766A}/H9011/[H5765]', 'inflected', 'heb', 'עֶוֶל', '["ʻevel"]', '["unrighteousness/ <towards>"]', '["n-m"]', '(moral) evil iniquity, perverseness, unjust(-ly), unrighteousness(-ly); wicked(-ness).', 'or עָוֶל; and (feminine) עַוְלָה; or עוֹלָה; or עֹלָה; from 5765;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7404}/H9021/[H7402]', 'inflected', 'heb', 'רְכֻלָּה', '["rᵉkullâh"]', '["trading/ your"]', '["n-f"]', 'trade (as peddled) merchandise, traffic.', 'feminine passive participle of 7402;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8432>/H9021', 'opaque', 'heb', 'תָּוֶךְ', '["tâvek"]', '["[the] middle of/ you"]', '["n-m"]', 'a bisection, i.e. (by implication) the centre among(-st), × between, half, × (there-, where-), in(-to), middle, mid(-night), midst (among), × out (of), × through, × with(-in).', 'from an unused root meaning to sever;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2490H}/H9031/[H2470]', 'inflected', 'heb', 'חָלַל', '["châlal"]', '["and/ I profaned/ you"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3308}/H9021/[H3302]', 'inflected', 'heb', 'יֳפִי', '["yŏphîy"]', '["in/ beauty/ your"]', '["n-m"]', 'beauty beauty.', 'from 3302;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7993}/H9031/[H7993]', 'inflected', 'heb', 'שָׁלַךְ', '["shâlak"]', '["I threw/ you"]', '["v"]', 'to throw out, down or away (literally or figuratively) adventure, cast (away, down, forth, off, out), hurl, pluck, throw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414L}/H9031/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["I put/ you"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5766A}/[H5765]', 'inflected', 'heb', 'עֶוֶל', '["ʻevel"]', '["by/ [the] unrighteousness of"]', '["n-m"]', '(moral) evil iniquity, perverseness, unjust(-ly), unrighteousness(-ly); wicked(-ness).', 'or עָוֶל; and (feminine) עַוְלָה; or עוֹלָה; or עֹלָה; from 5765;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0398}/H9031/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["it consumed/ you"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0665>', 'inflected', 'heb', 'לאפר', '["le./''E.fer"]', '["into/ ash[es]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5544}/[H5541]', 'lemma', 'heb', 'סִלּוֹן', '["çillôwn"]', '["a brier"]', '["n-m"]', 'a prickle (as if pendulous) brier, thorn.', 'or סַלּוֹן; from 5541;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5439J}/H9038/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["around/ them"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6908}/H9040/[H6908]', 'inflected', 'heb', 'קָבַץ', '["qâbats"]', '["when/ gather/ I"]', '["v"]', 'to grasp, i.e. collect assemble (selves), gather (bring) (together, selves together, up), heap, resort, × surely, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5439J}/H9038/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["from/ around/ them"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7257}/[H7257]', 'inflected', 'heb', 'רָבַץ', '["râbats"]', '["which/ lies"]', '["v"]', 'to crouch (on all four legs folded, like a recumbent animal); by implication, to recline, repose, brood, lurk, imbed crouch (down), fall down, make a fold, lay, (cause to, make to) lie (down), make to rest, sit.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2975G}/H9023/[H2975]', 'inflected', 'heb', 'יְאֹר', '["yᵉʼôr"]', '["canals/ its"]', '["n-m"]', 'a channel, e.g. a fosse, canal, shaft; specifically the Nile, as the one river of Egypt, including its collateral trenches; also the Tigris, as the main river of Assyria brook, flood, river, stream.', 'of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2975G}/H9020/[H2975]', 'inflected', 'heb', 'יְאֹר', '["yᵉʼôr"]', '["River/ my"]', '["n-m"]', 'a channel, e.g. a fosse, canal, shaft; specifically the Nile, as the one river of Egypt, including its collateral trenches; also the Tigris, as the main river of Assyria brook, flood, river, stream.', 'of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3895H>/H9021', 'inflected', 'heb', 'בלחייך', '["bi/l.cha.Yei./kha"]', '["in/ jaws/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2975H}/H9021/[H2975]', 'inflected', 'heb', 'יְאֹר', '["yᵉʼôr"]', '["canals/ your"]', '["n-m"]', 'a channel, e.g. a fosse, canal, shaft; specifically the Nile, as the one river of Egypt, including its collateral trenches; also the Tigris, as the main river of Assyria brook, flood, river, stream.', 'of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7193>/H9021', 'inflected', 'heb', 'בקשקשתיך', '["be./kas.ke.so.Tei./cha"]', '["to/ scales/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5927H}/H9031/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["and/ I will bring up/ you"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5203}/H9031/[H5203]', 'inflected', 'heb', 'נָטַשׁ', '["nâṭash"]', '["and/ I will abandon/ you"]', '["v"]', 'properly, to pound, i.e. smite; by implication (as if beating out, and thus expanding) to disperse; also, to thrust off, down, out or upon (inclusively, reject, let alone, permit, remit, etc.) cast off, drawn, let fall, forsake, join (battle), leave (off), lie still, loose, spread (self) abroad, stretch out, suffer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8610}/H9048/[H8610]', 'inflected', 'heb', 'תָּפַשׂ', '["tâphas"]', '["when/ seized/ they"]', '["v"]', 'to manipulate, i.e. seize; chiefly to capture, wield, specifically, to overlay; figuratively, to use unwarrantably catch, handle, (lay, take) hold (on, over), stop, × surely, surprise, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8172}/H9048/[H8172]', 'inflected', 'heb', 'שָׁעַן', '["shâʻan"]', '["and/ when/ leaned/ they"]', '["v"]', 'to support one''s self lean, lie, rely, rest (on, self), stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5976}/[H4571]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["and/ you caused to stand"]', '["v"]', 'to shake be at a stand.', 'for 4571;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4975>\', 'opaque', 'heb', 'מֹתֶן', '["môthen"]', '["hips"]', '["n-m"]', 'properly, the waist or small of the back; only in plural the loins greyhound, loins, side.', 'from an unused root meaning to be slender;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4024B}/[H4024]', 'inflected', 'heb', 'מִגְדּוֹל', '["Migdôwl"]', '["from/ Migdol"]', '["n-pr-m n-m"]', 'Migdol, a place in Egypt Migdol, tower.', 'or מִגְדֹּל; probably of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5482}/[H5482]', 'lemma', 'heb', 'סְוֵנֵה', '["Çᵉvênêh"]', '["Syene"]', '["n-pr-loc"]', 'Seven, a place in Upper Egypt Syene.', '(rather to be written סְוֵנָה; for סְוֵן; i.e to Seven); of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4351}/H9028/[H3564]', 'inflected', 'heb', 'מְכוּרָה', '["mᵉkûwrâh"]', '["origin/ their"]', '["n-f"]', 'origin (as if a mine) birth, habitation, nativity.', 'or מְכֹרָה; from the same as 3564 in the sense of dipping;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4591}/H9038/[H4591]', 'inflected', 'heb', 'מָעַט', '["mâʻaṭ"]', '["and/ I will make small/ them"]', '["v"]', 'properly, to pare off, i.e. lessen; intransitively, to be (or causatively, to make) small or few (or figuratively, ineffective) suffer to decrease, diminish, (be, × borrow a, give, make) few (in number, -ness), gather least (little), be (seem) little, (× give the) less, be minished, bring to nothing.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4009}/[H982]', 'inflected', 'heb', 'מִבְטָח', '["mibṭâch"]', '["<into>/ a confidence"]', '["n-m"]', 'properly, a refuge, i.e. (objective) security, or (subjective) assurance confidence, hope, sure, trust.', 'from 982;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6437G}/H9048/[H6437]', 'inflected', 'heb', 'פָּנָה', '["pânâh"]', '["when/ turned/ they"]', '["v"]', 'to turn; by implication, to face, i.e. appear, look, etc. appear, at (even-) tide, behold, cast out, come on, × corner, dawning, empty, go away, lie, look, mark, pass away, prepare, regard, (have) respect (to), (re-) turn (aside, away, back, face, self), × right (early).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2428A}/H9023/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["and/ to/ army/ his"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
