INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2428A}/H9023/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["for/ army/ his"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6468}/H9023/[H6466]', 'inflected', 'heb', 'פְּעֻלָּה', '["pᵉʻullâh"]', '["recompense/ his"]', '["n-f"]', '(abstractly) work labour, reward, wages, work.', 'feminine passive participle of 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1929}/[H162]', 'lemma', 'heb', 'הָהּ', '["hâhh"]', '["alas!"]', '["inj"]', 'ah! expressing grief woe worth.', 'a shortened form of 162;');
