INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3552}/[H3552]', 'inflected', 'heb', 'כּוּב', '["Kûwb"]', '["and/ Libya"]', '["n-pr-loc"]', 'Kub, a country near Egypt Chub.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6716}/[H6680]', 'inflected', 'heb', 'צִי', '["tsîy"]', '["in the/ ships"]', '["n-m"]', 'a ship (as a fixture) ship.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2729}/[H2729]', 'inflected', 'heb', 'חָרַד', '["chârad"]', '["to/ make tremble","to/ terrify"]', '["v"]', 'to shudder with terror; hence, to fear; also to hasten (with anxiety) be (make) afraid, be careful, discomfit, fray (away), quake, tremble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2724}/[H2720]', 'lemma', 'heb', 'חָרָבָה', '["chârâbâh"]', '["dry ground"]', '["n-f"]', 'a desert dry (ground, land).', 'feminine of 2720;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5297}/[H4644]', 'inflected', 'heb', 'נֹף', '["Nôph"]', '["from/ Memphis"]', '["n-pr-loc"]', 'Noph, the capital of Upper Egypt Noph.', 'a variation of 4644;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4996}/[H4996]', 'inflected', 'heb', 'נֹא', '["Nôʼ"]', '["on/ Thebes"]', '["n-pr-loc"]', 'No (i.e. Thebes), the capital of Upper Egypt No. Compare 528.', 'of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5512A>', 'opaque', 'heb', 'סִין', '["Çîyn"]', '["Sin"]', '["n-pr-loc"]', 'Sin the name of an Egyptian town and (probably) desert adjoining Sin.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4996}/[H4996]', 'lemma', 'heb', 'נֹא', '["Nôʼ"]', '["Thebes"]', '["n-pr-loc"]', 'No (i.e. Thebes), the capital of Upper Egypt No. Compare 528.', 'of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4996}/[H4996]', 'inflected', 'heb', 'נֹא', '["Nôʼ"]', '["and/ Thebes"]', '["n-pr-loc"]', 'No (i.e. Thebes), the capital of Upper Egypt No. Compare 528.', 'of Egyptian origin;');
