INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6364}/[H6364]', 'inflected', 'heb', 'פִּי־בֶסֶת', '["Pîy-Beçeth"]', '["and/ Pi-"]', '["n-pr-loc"]', 'Pi-Beseth, a place in Egypt Pi-beseth.', 'of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6364}/[H6364]', 'lemma', 'heb', 'פִּי־בֶסֶת', '["Pîy-Beçeth"]', '["beseth"]', '["n-pr-loc"]', 'Pi-Beseth, a place in Egypt Pi-beseth.', 'of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3680}/H9034/[H3680]', 'inflected', 'heb', 'כָּסָה', '["kâçâh"]', '["it will cover/ it"]', '["v"]', 'properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5414P}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["to/ give"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2848}/[H2853]', 'lemma', 'heb', 'חִתּוּל', '["chittûwl"]', '["a bandage"]', '["n-m"]', 'swathed, i.e. a bandage roller.', 'from 2853;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2280}/H9034/[H2280]', 'inflected', 'heb', 'חָבַשׁ', '["châbash"]', '["to/ bind up/ it"]', '["v"]', 'to wrap firmly (especially a turban, compress, or saddle); figuratively, to stop, to rule bind (up), gird about, govern, healer, put, saddle, wrap about.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2388G}/H9034/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["to/ be strong/ it"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7665}/[H7665]', 'inflected', 'heb', 'שָׁבַר', '["shâbar"]', '["the/ broken [one]"]', '["v"]', 'to burst (literally or figuratively) break (down, off, in pieces, up), broken (-hearted), bring to the birth, crush, destroy, hurt, quench, × quite, tear, view (by mistake for 7663).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5008}/[H5008]', 'inflected', 'heb', 'נָאַק', '["nâʼaq"]', '["and/ he will groan"]', '["v"]', 'to groan groan.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2793H}/[H2790]', 'inflected', 'heb', 'חֹרֶשׁ', '["chôresh"]', '["and/ forest"]', '["n-m"]', 'a forest (perhaps as furnishing the material for fabric) bough, forest, shroud, wood.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6788}/H9023/[H6785]', 'inflected', 'heb', 'צַמֶּרֶת', '["tsammereth"]', '["treetop/ its"]', '["n-f"]', 'fleeciness, i.e. foliage highest branch, top.', 'from the same as 6785;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5104H}/H9024/[H5102]', 'inflected', 'heb', 'נָהָר', '["nâhâr"]', '["rivers/ its"]', '["n-m"]', 'a stream (including the sea; expectation the Nile, Euphrates, etc.); figuratively, prosperity flood, river.', 'from 5102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8585A}/H9024/[H5927]', 'inflected', 'heb', 'תְּעָלָה', '["tᵉʻâlâh"]', '["channels/ its"]', '["n-f"]', 'a channel (into which water is raised for irrigation); also a bandage or plaster (as placed upon a wound) conduit, cured, healing, little river, trench, watercourse.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5634}/H9023/[H5589]', 'inflected', 'heb', 'סַרְעַפָּה', '["çarʻappâh"]', '["boughs/ its"]', '["n-f"]', 'a twig bough.', 'for 5589;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6288A}/H9023/[H6286]', 'inflected', 'heb', 'פְּאֹרָה', '["pᵉʼôrâh"]', '["branches/ its"]', '["n-f"]', 'properly, ornamentation, i.e. (plural) foliage (including the limbs) as bright green bough, branch, sprig.', 'or פֹּרָאה; or פֻּארָה; from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7971G}/H9043/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["when/ sent out/ it"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5589}/H9023/[H5585]', 'inflected', 'heb', 'סְעַפָּה', '["çᵉʻappâh"]', '["in/ boughs/ its"]', '["n-f"]', 'a twig or branch bough. Compare 5634.', 'feminine of 5585;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6738}/H9023/[H6751]', 'inflected', 'heb', 'צֵל', '["tsêl"]', '["and/ in/ shade/ its"]', '["n-m"]', 'shade, whether literal or figurative defence, shade(-ow).', 'from 6751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1433}/H9023/[H1431]', 'inflected', 'heb', 'גֹּדֶל', '["gôdel"]', '["in/ greatness/ its"]', '["n-m"]', 'magnitude (literally or figuratively) greatness, stout(-ness).', 'from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6004}/H9033/[H6004]', 'inflected', 'heb', 'עָמַם', '["ʻâmam"]', '["they eclipsed/ it"]', '["v"]', 'to associate; by implication, to overshadow (by huddling together) become dim, hide.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5589}/H9023/[H5585]', 'inflected', 'heb', 'סְעַפָּה', '["çᵉʻappâh"]', '["boughs/ its"]', '["n-f"]', 'a twig or branch bough. Compare 5634.', 'feminine of 5585;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6288A}/H9023/[H6286]', 'inflected', 'heb', 'פְּאֹרָה', '["pᵉʼôrâh"]', '["like/ branches/ its"]', '["n-f"]', 'properly, ornamentation, i.e. (plural) foliage (including the limbs) as bright green bough, branch, sprig.', 'or פֹּרָאה; or פֻּארָה; from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7065}/H9033/[H7065]', 'inflected', 'heb', 'קָנָא', '["qânâʼ"]', '["and/ they envied/ it"]', '["v"]', 'to be (causatively, make) zealous, i.e. (in a bad sense) jealous or envious (be) envy(-ious), be (move to, provoke to) jealous(-y), × very, (be) zeal(-ous).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6967}/[H6965]', 'inflected', 'heb', 'קוֹמָה', '["qôwmâh"]', '["in/ height"]', '["n-f"]', 'height × along, height, high, stature, tall.', 'from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7562}/H9023/[H7561]', 'inflected', 'heb', 'רֶשַׁע', '["reshaʻ"]', '["according to/ wickedness/ its"]', '["n-m"]', 'a wrong (especially moral) iniquity, wicked(-ness).', 'from 7561;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3772G}/H9033/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["and/ they cut down/ it"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5203}/H9033/[H5203]', 'inflected', 'heb', 'נָטַשׁ', '["nâṭash"]', '["and/ they abandoned/ it"]', '["v"]', 'properly, to pound, i.e. smite; by implication (as if beating out, and thus expanding) to disperse; also, to thrust off, down, out or upon (inclusively, reject, let alone, permit, remit, etc.) cast off, drawn, let fall, forsake, join (battle), leave (off), lie still, loose, spread (self) abroad, stretch out, suffer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6738}/H9023/[H6751]', 'inflected', 'heb', 'צֵל', '["tsêl"]', '["from/ shade/ its"]', '["n-m"]', 'shade, whether literal or figurative defence, shade(-ow).', 'from 6751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4658}/H9023/[H5307]', 'inflected', 'heb', 'מַפֶּלֶת', '["mappeleth"]', '["downfall/ its","fallen trunk/ its"]', '["n-f"]', 'fall, i.e. decadence; concretely, a ruin; specifically a carcase carcase, fall, ruin.', 'from 5307;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6967}/H9028/[H6965]', 'inflected', 'heb', 'קוֹמָה', '["qôwmâh"]', '["in/ height/ their"]', '["n-f"]', 'height × along, height, high, stature, tall.', 'from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6788}/H9028/[H6785]', 'inflected', 'heb', 'צַמֶּרֶת', '["tsammereth"]', '["treetop/ their"]', '["n-f"]', 'fleeciness, i.e. foliage highest branch, top.', 'from the same as 6785;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0352D}/H9028/[H193]', 'inflected', 'heb', 'אַיִל', '["ʼayil"]', '["leaders/ their"]', '["n-m"]', 'properly, strength; hence, anything strong; specifically a chief (politically); also a ram (from his strength); a pilaster (as a strong support); an oak or other strong tree mighty (man), lintel, oak, post, ram, tree.', 'from the same as 193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1363}/H9028/[H1361]', 'inflected', 'heb', 'גֹּבַהּ', '["gôbahh"]', '["by/ height/ their"]', '["n-m"]', 'elation, grandeur, arrogance excellency, haughty, height, high, loftiness, pride.', 'from 1361;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0953A}\/[H952]', 'inflected', 'heb', 'בּוֹר', '["bôwr"]', '["[the] pit"]', '["n-m"]', 'a pit hole (especially one used as a cistern or a prison) cistern, dungeon, fountain, pit, well.', 'from 952 (in the sense of 877);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3381}/H9043/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["went down/ it"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5969}/[H5968]', 'lemma', 'heb', 'עֻלְפֶּה', '["ʻulpeh"]', '["[were] wilted"]', '["n-m"]', 'an envelope, i.e. (figuratively) mourning fainted.', 'from 5968;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H8565>', 'inflected', 'heb', 'כתנים', '["ka./ta.Nim"]', '["[were] like <the>/ sea monster"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1518}/[H1518]', 'inflected', 'heb', 'גִּיחַ', '["gîyach"]', '["and/ you burst forth"]', '["v"]', 'to gush forth (as water), generally to issue break forth, labor to bring forth, come forth, draw up, take out.', 'or (shortened) גֹּחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5104H}/H9021/[H5102]', 'inflected', 'heb', 'נָהָר', '["nâhâr"]', '["in/ rivers/ your"]', '["n-m"]', 'a stream (including the sea; expectation the Nile, Euphrates, etc.); figuratively, prosperity flood, river.', 'from 5102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1804}/[H1804]', 'inflected', 'heb', 'דָּלַח', '["dâlach"]', '["and/ you made turbid"]', '["v"]', 'to roil water trouble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7515}/[H7515]', 'inflected', 'heb', 'רָפַשׂ', '["râphas"]', '["and/ you fouled"]', '["v"]', 'to trample, i.e. roil water foul, trouble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5927J}/H9031/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["and/ I will bring up/ you","and/ they will bring up/ you"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2764B}/H9020/[H2763]', 'inflected', 'heb', 'חֵרֶם', '["chêrem"]', '["in/ net/ my"]', '["n-m"]', 'physical (as shutting in) a net (either literally or figuratively); usually a doomed object; abstractly extermination (ac-) curse(-d, -d thing), dedicated thing, things which should have been utterly destroyed, (appointed to) utter destruction, devoted (thing), net.', 'or (Zechariah 14:11) חֶרֶם; from 2763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7419}/H9021/[H7311]', 'inflected', 'heb', 'רָמוּת', '["râmûwth"]', '["height/ your"]', '["n-f"]', 'a heap (of carcases) height.', 'from 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6824}/H9021/[H6823]', 'inflected', 'heb', 'צָפָה', '["tsâphâh"]', '["outflow/ your"]', '["n-f"]', 'an inundation (as covering) × swimmest.', 'from 6823;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1818}/H9021/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["from/ blood/ your"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0650}/[H622]', 'inflected', 'heb', 'אָפִיק', '["ʼâphîyq"]', '["and/ ravines"]', '["n-m"]', 'properly, containing, i.e. a tube; also a bed or valley of a stream; also a strong thing or a hero brook, channel, mighty, river, scale, stream, strong piece.', 'from 622;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3518}/H9031/[H3518]', 'inflected', 'heb', 'כָּבָה', '["kâbâh"]', '["when/ extinguishing/ you"]', '["v"]', 'to expire or (causatively) to extinguish (fire, light, anger) go (put) out, quench.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3556}/H9028/[H3522]', 'inflected', 'heb', 'כּוֹכָב', '["kôwkâb"]', '["stars/ their"]', '["n-m"]', 'a star (as round or as shining); figuratively, a prince star(-gazer).', 'probably from the same as 3522 (in the sense of rolling) or 3554 (in the sense of blazing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6937}/H9038/[H6937]', 'inflected', 'heb', 'קָדַר', '["qâdar"]', '["I will darken/ them"]', '["v"]', 'to be ashy, i.e. dark-colored; by implication, to mourn (in sackcloth or sordid garments) be black(-ish), be (make) dark(-en), × heavily, (cause to) mourn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7667}/H9021/[H7665]', 'inflected', 'heb', 'שֶׁבֶר', '["sheber"]', '["breaking/ your"]', '["n-m"]', 'a fracture, figuratively, ruin; specifically, a solution (of a dream) affliction, breach, breaking, broken(-footed, -handed), bruise, crashing, destruction, hurt, interpretation, vexation.', 'or שֵׁבֶר; from 7665;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5774A}/H9040/[H5775]', 'inflected', 'heb', 'עוּף', '["ʻûwph"]', '["when/ brandish/ I"]', '["v n-f"]', 'to fly; also (by implication of dimness) to faint (from the darkness of swooning) brandish, be (wax) faint, flee away, fly (away), × set, shine forth, weary.', 'a primitive root; to cover (with wings or obscurity); hence (as denominative from 5775)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5315H}/H9023/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["for/ life/ his"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4658}/H9021\/[H5307]', 'inflected', 'heb', 'מַפֶּלֶת', '["mappeleth"]', '["downfall/ your"]', '["n-f"]', 'fall, i.e. decadence; concretely, a ruin; specifically a carcase carcase, fall, ruin.', 'from 5307;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1995A}/H9021/[H1993]', 'inflected', 'heb', 'הָמוֹן', '["hâmôwn"]', '["multitude/ your"]', '["n-m"]', 'a noise, tumult, crowd; also disquietude, wealth abundance, company, many, multitude, multiply, noise, riches, rumbling, sounding, store, tumult.', 'or הָמֹן; (Ezekiel 5:7), from 1993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7703}/[H7703]', 'inflected', 'heb', 'שָׁדַד', '["shâdad"]', '["and/ they will devastate"]', '["v"]', 'properly, to be burly, i.e. (figuratively) powerful (passively, impregnable); by implication, to ravage dead, destroy(-er), oppress, robber, spoil(-er), × utterly, (lay) waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1804}/H9038/[H1804]', 'inflected', 'heb', 'דָּלַח', '["dâlach"]', '["it will make turbid/ them"]', '["v"]', 'to roil water trouble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5104H}/H9028/[H5102]', 'inflected', 'heb', 'נָהָר', '["nâhâr"]', '["and/ rivers/ their"]', '["n-m"]', 'a stream (including the sea; expectation the Nile, Euphrates, etc.); figuratively, prosperity flood, river.', 'from 5102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8074G}/[H8074]', 'inflected', 'heb', 'שָׁמֵם', '["shâmêm"]', '["and/ [is] made desolate"]', '["v"]', 'to stun (or intransitively, grow numb), i.e. devastate or (figuratively) stupefy (both usually in a passive sense) make amazed, be astonied, (be an) astonish(-ment), (be, bring into, unto, lay, lie, make) desolate(-ion, places), be destitute, destroy (self), (lay, lie, make) waste, wonder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6969}/H9034/[H6969]', 'inflected', 'heb', 'קוּן', '["qûwn"]', '["and/ people will chant/ it"]', '["v"]', 'to strike a musical note, i.e. chant or wail (at a funeral) lament, mourning woman.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6969}/[H6969]', 'lemma', 'heb', 'קוּן', '["qûwn"]', '["they will chant"]', '["v"]', 'to strike a musical note, i.e. chant or wail (at a funeral) lament, mourning woman.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5091}/[H5091]', 'lemma', 'heb', 'נָהָה', '["nâhâh"]', '["wail"]', '["v"]', 'to groan, i.e. bewail; hence (through the idea of crying aloud), to assemble (as if on proclamation) lament, wail.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3381}/H9033/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["and/ bring down/ it"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7901J}/H9012/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["and/ be laid/ !"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6951}/H9024/[H6950]', 'inflected', 'heb', 'קָהָל', '["qâhâl"]', '["company/ its"]', '["n-m"]', 'assemblage (usually concretely) assembly, company, congregation, multitude.', 'from 6950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6913}/H9024/[H6912]', 'inflected', 'heb', 'קֶבֶר', '["qeber"]', '["graves/ its"]', '["n-m"]', 'a sepulchre burying place, grave, sepulchre.', 'or (feminine) קִבְרָה; from 6912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2851}/[H2865]', 'lemma', 'heb', 'חִתִּית', '["chittîyth"]', '["terror","terror of"]', '["n-f"]', 'fear terror.', 'from 2865;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3639}/H9028/[H3637]', 'inflected', 'heb', 'כְּלִמָּה', '["kᵉlimmâh"]', '["disgrace/ their","insult[s]/ their"]', '["n-f"]', 'disgrace confusion, dishonour, reproach, shame.', 'from 3637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4902I}/[H4901]', 'lemma', 'heb', 'מֶשֶׁךְ', '["Meshek"]', '["Meshech"]', '["n-pr-m"]', 'Meshek, a son of Japheth, and the people descended from him Mesech, Meshech.', 'the same in form as 4901, but probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8422I}/[H8422]', 'lemma', 'heb', 'תּוּבַל', '["Tûwbal"]', '["Tubal"]', '["n-pr-m"]', 'Tubal, a postdiluvian patriarch and his posterity Tubal.', 'or תֻּבַל; probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6189}/[H6188]', 'inflected', 'heb', 'עָרֵל', '["ʻârêl"]', '["from/ uncircumcised [men]"]', '["a"]', 'properly, exposed, i.e. projecting loose (as to the prepuce); used only technically, uncircumcised (i.e. still having the prepuce uncurtailed) uncircumcised (person).', 'from 6188;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7901J}/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["and/ you may lie"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5387A}/H9024/[H5375]', 'inflected', 'heb', 'נָשִׂיא', '["nâsîyʼ"]', '["princes/ its"]', '["n-m"]', 'properly, an exalted one, i.e. a king or sheik; also a rising mist captain, chief, cloud, governor, prince, ruler, vapour.', 'or נָשִׂא; from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1369}/H9028/[H1368]', 'inflected', 'heb', 'גְּבוּרָה', '["gᵉbûwrâh"]', '["in/ strength/ their"]', '["n-f"]', 'force (literally or figuratively); by implication, valor, victory force, mastery, might, mighty (act, power), power, strength.', 'feminine passive participle from the same as 1368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2851}/H9028/[H2865]', 'inflected', 'heb', 'חִתִּית', '["chittîyth"]', '["in/ terror/ their"]', '["n-f"]', 'fear terror.', 'from 2865;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1369}/H9028/[H1368]', 'inflected', 'heb', 'גְּבוּרָה', '["gᵉbûwrâh"]', '["from/ strength/ their"]', '["n-f"]', 'force (literally or figuratively); by implication, valor, victory force, mastery, might, mighty (act, power), power, strength.', 'feminine passive participle from the same as 1368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2851}/H9020/[H2865]', 'inflected', 'heb', 'חִתִּית', '["chittîyth"]', '["terror/ my"]', '["n-f"]', 'fear terror.', 'from 2865;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7097A}/H9028/[H7096]', 'inflected', 'heb', 'קָצֶה', '["qâtseh"]', '["from/ ends/ their"]', '["n-m"]', 'an extremity × after, border, brim, brink, edge, end, (in-) finite, frontier, outmost coast, quarter, shore, (out-) side, × some, ut(-ter-) most (part).', 'or (negative only) קֵצֶה; from 7096; (used in a great variety of applications and idioms; compare 7093)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6822}/[H6822]', 'inflected', 'heb', 'צָפָה', '["tsâphâh"]', '["into/ a watchman"]', '["v"]', 'properly, to lean forward, i.e. to peer into the distance; by implication, to observe, await behold, espy, look up (well), wait for, (keep the) watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H9038}', 'inflected', 'heb', 'ובהם', '["u./Va/m","u./va./Hem"]', '["and/ in/ them"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725O}/H9043/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["turns back/ he"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2398}/H9043/[H2398]', 'inflected', 'heb', 'חָטָא', '["châṭâʼ"]', '["sins/ he"]', '["v"]', 'properly, to miss; hence (figuratively and generally) to sin; by inference, to forfeit, lack, expiate, repent, (causatively) lead astray, condemn bear the blame, cleanse, commit (sin), by fault, harm he hath done, loss, miss, (make) offend(-er), offer for sin, purge, purify (self), make reconciliation, (cause, make) sin(-ful, -ness), trespass.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5766A}/H9023/[H5765]', 'inflected', 'heb', 'עֶוֶל', '["ʻevel"]', '["and/ in/ unrighteousness/ his"]', '["n-m"]', '(moral) evil iniquity, perverseness, unjust(-ly), unrighteousness(-ly); wicked(-ness).', 'or עָוֶל; and (feminine) עַוְלָה; or עוֹלָה; or עֹלָה; from 5765;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0559}/H9040/[H559]', 'inflected', 'heb', 'אָמַר', '["ʼâmar"]', '["and/ when/ say/ I"]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1546}/H9025/[H1540]', 'inflected', 'heb', 'גָּלוּת', '["gâlûwth"]', '["of/ exile/ our"]', '["n-f"]', 'captivity; concretely, exiles (collectively) (they that are carried away) captives(-ity).', 'feminine from 1540;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2723}/[H2721]', 'inflected', 'heb', 'חׇרְבָּה', '["chorbâh"]', '["the/ waste places"]', '["n-f"]', 'properly, drought, i.e. (by implication) a desolation decayed place, desolate (place, -tion), destruction, (laid) waste (place).', 'feminine of 2721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9008/<H0776G>', 'inflected', 'heb', 'והארץ', '["ve./ha./''A.retz"]', '["and/ ¿/ land"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3423G}\/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["will you possess?"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0398}/H9033/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["to/ eat/ him"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4631}/[H5783]', 'inflected', 'heb', 'מְעָרָה', '["mᵉʻârâh"]', '["and/ in the/ caves"]', '["n-f"]', 'a cavern (as dark) cave, den, hole.', 'from 5783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6607}/[H6605]', 'inflected', 'heb', 'פֶּתַח', '["pethach"]', '["and/ in/ [the] doorways of"]', '["n-m"]', 'an opening (literally), i.e. door (gate) or entrance way door, entering (in), entrance (-ry), gate, opening, place.', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2297}/[H259]', 'lemma', 'heb', 'חַד', '["chad"]', '["one"]', '["a"]', 'one one.', 'abridged from 259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5690}/[H5689]', 'lemma', 'heb', 'עֶגֶב', '["ʻegeb"]', '["lustful desires"]', '["n-m"]', 'love (concretely), i.e. amative words much love, very lovely.', 'from 5689;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1215}/H9028/[H1214]', 'inflected', 'heb', 'בֶּצַע', '["betsaʻ"]', '["unjust gain/ their"]', '["n-m"]', 'plunder; by extension, gain (usually unjust) covetousness, (dishonest) gain, lucre, profit.', 'from 1214;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7892A}/[H7891]', 'inflected', 'heb', 'שִׁיר', '["shîyr"]', '["[are] like/ a song of"]', '["n-m n-f"]', 'a song; abstractly, singing musical(-ick), × sing(-er, -ing), song.', 'or feminine שִׁירָה; from 7891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2470A}/[H2342]', 'inflected', 'heb', 'חָלָה', '["châlâh"]', '["the/ sick [one]","the/ weak [ones]"]', '["v"]', 'properly, to be rubbed or worn; hence (figuratively) to be weak, sick, afflicted; or (causatively) to grieve, make sick; also to stroke (in flattering), entreat beseech, (be) diseased, (put to) grief, be grieved, (be) grievous, infirmity, intreat, lay to, put to pain, × pray, make prayer, be (fall, make) sick, sore, be sorry, make suit (× supplication), woman in travail, be (become) weak, be wounded.', 'a primitive root (compare 2342, 2470, 2490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2470H}/[H2342]', 'inflected', 'heb', 'חָלָה', '["châlâh"]', '["the/ sick [animal]","the/ sick [one]"]', '["v"]', 'properly, to be rubbed or worn; hence (figuratively) to be weak, sick, afflicted; or (causatively) to grieve, make sick; also to stroke (in flattering), entreat beseech, (be) diseased, (put to) grief, be grieved, (be) grievous, infirmity, intreat, lay to, put to pain, × pray, make prayer, be (fall, make) sick, sore, be sorry, make suit (× supplication), woman in travail, be (become) weak, be wounded.', 'a primitive root (compare 2342, 2470, 2490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7665}/[H7665]', 'inflected', 'heb', 'שָׁבַר', '["shâbar"]', '["and/ <to> the/ broken [one]"]', '["v"]', 'to burst (literally or figuratively) break (down, off, in pieces, up), broken (-hearted), bring to the birth, crush, destroy, hurt, quench, × quite, tear, view (by mistake for 7663).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5080}/[H5080]', 'inflected', 'heb', 'נָדַח', '["nâdach"]', '["the/ strayed [one]"]', '["v"]', 'to push off; used in a great variety of applications, literally and figuratively (to expel, mislead, strike, inflict, etc.) banish, bring, cast down (out), chase, compel, draw away, drive (away, out, quite), fetch a stroke, force, go away, outcast, thrust away (out), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2394}/[H2392]', 'inflected', 'heb', 'חׇזְקָה', '["chozqâh"]', '["and/ with/ force"]', '["n-f"]', 'vehemence (usually in a bad sense) force, mightily, repair, sharply.', 'feminine of 2392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H6531>', 'inflected', 'heb', 'ובפרך', '["u./ve./Fa.rekh"]', '["and/ with/ harshness"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7462B}\/[H7462]', 'inflected', 'heb', 'רָעָה', '["râʻâh"]', '["[is] a shepherd","they have shepherded"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7673A}/H9038/[H7673]', 'inflected', 'heb', 'שָׁבַת', '["shâbath"]', '["and/ I will cause to cease/ them"]', '["v"]', 'to repose, i.e. desist from exertion; used in many implied relations (causative, figurative or specific) (cause to, let, make to) cease, celebrate, cause (make) to fail, keep (sabbath), suffer to be lacking, leave, put away (down), (make to) rest, rid, still, take away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0402}\/[H401]', 'inflected', 'heb', 'אׇכְלָה', '["ʼoklâh"]', '["<into>/ food"]', '["n-f"]', 'food consume, devour, eat, food, meat.', 'feminine of 401;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1239}/H9038/[H1239]', 'inflected', 'heb', 'בָּקַר', '["bâqar"]', '["and/ I will seek/ them"]', '["v"]', 'properly, to plough, or (generally) break forth, i.e. (figuratively) to inspect, admire, care for, consider (make) inquire (-ry), (make) search, seek out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1243}/[H1239]', 'inflected', 'heb', 'בַּקָּרָה', '["baqqârâh"]', '["like/ [the] seeking of"]', '["n-f"]', 'a looking after seek out.', 'intensive from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1961}/H9043/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["is/ he"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0650}/[H622]', 'inflected', 'heb', 'אָפִיק', '["ʼâphîyq"]', '["in the/ ravines"]', '["n-m"]', 'properly, containing, i.e. a tube; also a bed or valley of a stream; also a strong thing or a hero brook, channel, mighty, river, scale, stream, strong piece.', 'from 622;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4829}/[H7462]', 'inflected', 'heb', 'מִרְעֶה', '["mirʻeh"]', '["in/ pasture"]', '["n-m"]', 'pasture (the place or the act); also the haunt of wild animals feeding place, pasture.', 'from 7462 in the sense of feeding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4829}/[H7462]', 'inflected', 'heb', 'מִרְעֶה', '["mirʻeh"]', '["and/ pasture"]', '["n-m"]', 'pasture (the place or the act); also the haunt of wild animals feeding place, pasture.', 'from 7462 in the sense of feeding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7257}/H9038/[H7257]', 'inflected', 'heb', 'רָבַץ', '["râbats"]', '["I will make lie down/ them"]', '["v"]', 'to crouch (on all four legs folded, like a recumbent animal); by implication, to recline, repose, brood, lurk, imbed crouch (down), fall down, make a fold, lay, (cause to, make to) lie (down), make to rest, sit.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8082}/[H8080]', 'inflected', 'heb', 'שָׁמֵן', '["shâmên"]', '["the/ fat [one]"]', '["a"]', 'greasy, i.e. gross; figuratively, rich fat, lusty, plenteous.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6260}/[H6257]', 'inflected', 'heb', 'עַתּוּד', '["ʻattûwd"]', '["and/ <the>/ male goats"]', '["n-m"]', 'prepared, i.e. full grown; spoken only (in plural) of he-goats, or (figuratively) leaders of the people chief one, (he) goat, ram.', 'or עַתֻּד; from 6257;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4829}/[H7462]', 'inflected', 'heb', 'מִרְעֶה', '["mirʻeh"]', '["[is] the/ pasture"]', '["n-m"]', 'pasture (the place or the act); also the haunt of wild animals feeding place, pasture.', 'from 7462 in the sense of feeding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4829}/H9026/[H7462]', 'inflected', 'heb', 'מִרְעֶה', '["mirʻeh"]', '["pasture/ your"]', '["n-m"]', 'pasture (the place or the act); also the haunt of wild animals feeding place, pasture.', 'from 7462 in the sense of feeding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4950}/[H8257]', 'inflected', 'heb', 'מִשְׁקָע', '["mishqâʻ"]', '["and/ clearness of"]', '["n-m"]', 'a settling place (of water), i.e. a pond deep.', 'from 8257;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7515}/H9013/[H7515]', 'inflected', 'heb', 'רָפַשׂ', '["râphas"]', '["you are fouling/ !"]', '["v"]', 'to trample, i.e. roil water foul, trouble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6629G>/H9020', 'inflected', 'heb', 'וצאני', '["ve./tzo.N/i"]', '["and/ flock/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4833}/[H7515]', 'inflected', 'heb', 'מִרְפָּשׂ', '["mirpâs"]', '["and/ [the] befouled thing of"]', '["n-m"]', 'muddled water that which...have fouled.', 'from 7515;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8354}\/[H8354]', 'inflected', 'heb', 'שָׁתָה', '["shâthâh"]', '["they will drink"]', '["v"]', 'to imbibe (literally or figuratively) × assuredly, banquet, × certainly, drink(-er, -ing), drunk (× -ard), surely. (Prop. intensive of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1274}/[H1262]', 'lemma', 'heb', 'בְּרִי', '["bᵉrîy"]', '["fat"]', '["a"]', 'fat fat.', 'from 1262;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H3802>', 'inflected', 'heb', 'ובכתף', '["u./ve./kha.Tef"]', '["and/ with/ shoulder"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7161A}/H9026/[H7160]', 'inflected', 'heb', 'קֶרֶן', '["qeren"]', '["and/ with/ horns/ your"]', '["n-f n-pr-loc"]', 'a horn (as projecting); by implication, a flask, cornet; by resemblance. an elephant''s tooth (i.e. ivory), a corner (of the altar), a peak (of a mountain), a ray (of light); figuratively, power × hill, horn.', 'from 7160;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H6629G>/H9020', 'inflected', 'heb', 'לצאני', '["le./tzo.N/i"]', '["<to>/ flock/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1389I}/H9020/[H1387]', 'inflected', 'heb', 'גִּבְעָה', '["gibʻâh"]', '["hill/ my"]', '["n-f"]', 'a hillock hill, little hill.', 'feminine from the same as 1387;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5923}/H9028/[H5953]', 'inflected', 'heb', 'עֹל', '["ʻôl"]', '["yoke/ their"]', '["n-m"]', 'a yoke (as imposed on the neck), literally or figuratively yoke.', 'or עוֹל; from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5647G}/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["those/ [who] labored","who/ serves"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8077B}/[H8076]', 'inflected', 'heb', 'שְׁמָמָה', '["shᵉmâmâh"]', '["into/ a desolation"]', '["n-f"]', 'devastation; figuratively, astonishment (laid, × most) desolate(-ion), waste.', 'or שִׁמָמָה; feminine of 8076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2022G}/H9023/[H2042]', 'inflected', 'heb', 'הַר', '["har"]', '["mountains/ his","mountains/ its"]', '["n-m"]', 'a mountain or range of hills (sometimes used figuratively) hill (country), mount(-ain), × promotion.', 'a shortened form of 2042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2491A}/H9023/[H2490]', 'inflected', 'heb', 'חָלָל', '["châlâl"]', '["slain [ones]/ its"]', '["n-m"]', 'pierced (especially to death); figuratively, polluted kill, profane, slain (man), × slew, (deadly) wounded.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1389I}/H9021/[H1387]', 'inflected', 'heb', 'גִּבְעָה', '["gibʻâh"]', '["hills/ your"]', '["n-f"]', 'a hillock hill, little hill.', 'feminine from the same as 1387;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1516R}/H9021/[H1466]', 'inflected', 'heb', 'גַּיְא', '["gayʼ"]', '["and/ valleys/ your"]', '["n"]', 'a gorge (from its lofty sides; hence, narrow, but not a gully or winter-torrent) valley.', 'or (shortened) גַּי; probably (by transmutation) from the same root as 1466 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0650}/H9021/[H622]', 'inflected', 'heb', 'אָפִיק', '["ʼâphîyq"]', '["ravines/ your"]', '["n-m"]', 'properly, containing, i.e. a tube; also a bed or valley of a stream; also a strong thing or a hero brook, channel, mighty, river, scale, stream, strong piece.', 'from 622;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5892B}/H9021/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["and/ cities/ your"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0559}/H9041/[H559]', 'inflected', 'heb', 'אָמַר', '["ʼâmar"]', '["saying/ you"]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0639G}/H9021/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["according to/ anger/ your"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H7068}/H9021/[H7065]', 'inflected', 'heb', 'קִנְאָה', '["qinʼâh"]', '["and/ according to/ jealousy/ your"]', '["n-f"]', 'jealousy or envy envy(-ied), jealousy, × sake, zeal.', 'from 7065;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8135}/H9021/[H8130]', 'inflected', 'heb', 'שִׂנְאָה', '["sinʼâh"]', '["from/ hatred<s>/ your"]', '["n-f"]', 'hate exceedingly, hate(-ful, -red).', 'from 8130;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5007B}/H9021/[H5006]', 'inflected', 'heb', 'נְאָצָה', '["nᵉʼâtsâh"]', '["insults/ your"]', '["n-f"]', 'scorn blasphemy.', 'or נֶאָצָה; from 5006;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6280}/[H6280]', 'inflected', 'heb', 'עָתַר', '["ʻâthar"]', '["and/ you have multiplied"]', '["v"]', 'to be (causatively, make) abundant deceitful, multiply.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8055}/[H8055]', 'inflected', 'heb', 'שָׂמַח', '["sâmach"]', '["when/ rejoices"]', '["v"]', 'probably to brighten up, i.e. (figuratively) be (causatively, make) blithe or gleesome cheer up, be (make) glad, (have, make) joy(-ful), be (make) merry, (cause to, make to) rejoice, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8057}/H9021/[H8056]', 'inflected', 'heb', 'שִׂמְחָה', '["simchâh"]', '["according to/ rejoicing/ your"]', '["n-f"]', 'blithesomeness or glee, (religious or festival) × exceeding(-ly), gladness, joy(-fulness), mirth, pleasure, rejoice(-ing).', 'from 8056;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1116>', 'inflected', 'heb', 'ובמות', '["u./va.Mot"]', '["and/ [the] high places of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3282>', 'inflected', 'heb', 'ביען', '["be./Ya.''an"]', '["by/ cause"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7602B}/[H7602]', 'inflected', 'heb', 'שָׁאַף', '["shâʼaph"]', '["and/ to crush"]', '["v"]', 'to inhale eagerly; figuratively, to cover; by implication, to be angry; also to hasten desire (earnestly), devour, haste, pant, snuff up, swallow up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1961}/H9036/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["to/ be/ you"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1681}/[H1680]', 'inflected', 'heb', 'דִּבָּה', '["dibbâh"]', '["and/ [the] whispering of"]', '["n-f"]', 'slander defaming, evil report, infamy, slander.', 'from 1680 (in the sense of furtive motion);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8076}/[H8074]', 'inflected', 'heb', 'שָׁמֵם', '["shâmêm"]', '["<the>/ desolate"]', '["a"]', 'ruined desolate.', 'from 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6057>/H9026', 'opaque', 'heb', 'עָנָף', '["ʻânâph"]', '["branch[es]/ your"]', '["n-m"]', 'a twig (as covering the limbs) bough, branch.', 'from an unused root meaning to cover;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6529}/H9026/[H6509]', 'inflected', 'heb', 'פְּרִי', '["pᵉrîy"]', '["and/ fruit/ your"]', '["n-m"]', 'fruit (literally or figuratively) bough, (first-)fruit(-ful), reward.', 'from 6509;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2723}/[H2721]', 'inflected', 'heb', 'חׇרְבָּה', '["chorbâh"]', '["and/ the/ waste places"]', '["n-f"]', 'properly, drought, i.e. (by implication) a desolation decayed place, desolate (place, -tion), destruction, (laid) waste (place).', 'feminine of 2721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6927}/H9026/[H6923]', 'inflected', 'heb', 'קַדְמָה', '["qadmâh"]', '["like/ former state/ your"]', '["n-f"]', 'priority (in time); also used adverbially (before) afore, antiquity, former (old) estate.', 'from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7221}/H9026/[H7218]', 'inflected', 'heb', 'רִאשָׁה', '["riʼshâh"]', '["more than/ beginnings/ your"]', '["n-f"]', 'a beginning beginning.', 'from the same as 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3423G}/H9031/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["and/ they will dispossess/ you"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7921A}/H9038\/[H7921]', 'inflected', 'heb', 'שָׁכֹל', '["shâkôl"]', '["to/ bereave/ them"]', '["v"]', 'properly, to miscarry, i.e. suffer abortion; by analogy, to bereave (literally or figuratively) bereave (of children), barren, cast calf (fruit, young), be (make) childless, deprive, destroy, × expect, lose children, miscarry, rob of children, spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7921A}/[H7921]', 'inflected', 'heb', 'שָׁכֹל', '["shâkôl"]', '["and/ bereaving"]', '["v"]', 'properly, to miscarry, i.e. suffer abortion; by analogy, to bereave (literally or figuratively) bereave (of children), barren, cast calf (fruit, young), be (make) childless, deprive, destroy, × expect, lose children, miscarry, rob of children, spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1471A}/H9022/[H1465]', 'inflected', 'heb', 'גּוֹי', '["gôwy"]', '["nations/ your"]', '["n-m n-pr-m"]', 'a foreign nation; hence, a Gentile; also (figuratively) a troop of animals, or a flight of locusts Gentile, heathen, nation, people.', 'rarely (shortened) גֹּי; apparently from the same root as 1465 (in the sense of massing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1471A}/H9022/[H1465]', 'inflected', 'heb', 'גּוֹי', '["gôwy"]', '["and/ nations/ your"]', '["n-m n-pr-m"]', 'a foreign nation; hence, a Gentile; also (figuratively) a troop of animals, or a flight of locusts Gentile, heathen, nation, people.', 'rarely (shortened) גֹּי; apparently from the same root as 1465 (in the sense of massing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5949}/H9028/[H5953]', 'inflected', 'heb', 'עֲלִילָה', '["ʻălîylâh"]', '["and/ by/ practices/ their"]', '["n-f"]', 'an exploit (of God), or a performance (of man, often in a bad sense); by implication, an opportunity act(-ion), deed, doing, invention, occasion, work.', 'or עֲלִלָה; from 5953 in the sense of effecting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2930A}/H9034/[H2930]', 'inflected', 'heb', 'טָמֵא', '["ṭâmêʼ"]', '["they made unclean/ it"]', '["v"]', 'to be foul, especially in a ceremial or moral sense (contaminated) defile (self), pollute (self), be (make, make self, pronounce) unclean, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1870G}/H9028/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["according to/ conduct/ their"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H5949}/H9028/[H5953]', 'inflected', 'heb', 'עֲלִילָה', '["ʻălîylâh"]', '["and/ according to/ practices/ their"]', '["n-f"]', 'an exploit (of God), or a performance (of man, often in a bad sense); by implication, an opportunity act(-ion), deed, doing, invention, occasion, work.', 'or עֲלִלָה; from 5953 in the sense of effecting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H0776G>/H9023', 'inflected', 'heb', 'ומארצו', '["u./me./''ar.Tz/o"]', '["and/ from/ land/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2490H}/[H2470]', 'inflected', 'heb', 'חָלַל', '["châlal"]', '["that/ has been] profaned"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6942K}/H9040/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["when/ I show holy/ myself"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2932}/H9026/[H2930]', 'inflected', 'heb', 'טֻמְאָה', '["ṭumʼâh"]', '["uncleanness<es>/ your"]', '["n-f"]', 'religious impurity filthiness, unclean(-ness).', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1320}/H9026/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["from/ flesh/ your"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8570}/[H5107]', 'inflected', 'heb', 'תְּנוּבָה', '["tᵉnûwbâh"]', '["and/ [the] produce of"]', '["n-f"]', 'produce fruit, increase.', 'from 5107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1870L}/H9026/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["from/ ways/ your"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2891}/H9040/[H2891]', 'inflected', 'heb', 'טָהֵר', '["ṭâhêr"]', '["cleanse/ I"]', '["v"]', 'to be pure (physical sound, clear, unadulterated; Levitically, uncontaminated; morally, innocent or holy) be (make, make self, pronounce) clean, cleanse (self), purge, purify(-ier, self).', 'a primitive root; properly, to be bright; i.e. (by implication)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1977}/[H1976]', 'lemma', 'heb', 'הַלֵּזוּ', '["hallêzûw"]', '["this"]', '["d"]', 'that this.', 'another form of 1976;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8074G}/[H8074]', 'inflected', 'heb', 'שָׁמֵם', '["shâmêm"]', '["and/ <the>/ desolated"]', '["v"]', 'to stun (or intransitively, grow numb), i.e. devastate or (figuratively) stupefy (both usually in a passive sense) make amazed, be astonied, (be an) astonish(-ment), (be, bring into, unto, lay, lie, make) desolate(-ion, places), be destitute, destroy (self), (lay, lie, make) waste, wonder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2040}/[H2040]', 'inflected', 'heb', 'הָרַס', '["hâraç"]', '["and/ <the>/ broken down"]', '["v"]', 'to pull down or in pieces, break, destroy beat down, break (down, through), destroy, overthrow, pluck down, pull down, ruin, throw down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4150H}/H9024/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["at/ appointed times/ its"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5117}/H9030/[H5117]', 'inflected', 'heb', 'נוּחַ', '["nûwach"]', '["and/ he set down/ me"]', '["v"]', 'to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5674A}/H9030/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["and/ he made pass by/ me","and/ he made pass through/ me","and/ he made pass/ me"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3002}/[H3001]', 'inflected', 'heb', 'יָבֵשׁ', '["yâbêsh"]', '["<the>/ dry"]', '["a"]', 'dry dried (away), dry.', 'from 3001;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6106G}/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["to the/ bones"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7159}/[H7159]', 'inflected', 'heb', 'קָרַם', '["qâram"]', '["and/ I will cover","and/ it covered"]', '["v"]', 'to cover cover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5301}/[H5301]', 'inflected', 'heb', 'נָפַח', '["nâphach"]', '["and/ blow"]', '["v"]', 'to puff, in various applications (literally, to inflate, blow hard, scatter, kindle, expire; figuratively, to disesteem) blow, breath, give up, cause to lose (life), seething, snuff.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8615B}/H9025/[H6960]', 'inflected', 'heb', 'תִּקְוָה', '["tiqvâh"]', '["hope/ our"]', '["n-f"]', 'literally a cord (as an attachment); figuratively, expectancy expectation(-ted), hope, live, thing that I long for.', 'from 6960; (compare 6961)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6913}/H9026/[H6912]', 'inflected', 'heb', 'קֶבֶר', '["qeber"]', '["graves/ your"]', '["n-m"]', 'a sepulchre burying place, grave, sepulchre.', 'or (feminine) קִבְרָה; from 6912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6913}/H9026/[H6912]', 'inflected', 'heb', 'קֶבֶר', '["qeber"]', '["from/ graves/ your"]', '["n-m"]', 'a sepulchre burying place, grave, sepulchre.', 'or (feminine) קִבְרָה; from 6912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6605A}/H9040/[H6605]', 'inflected', 'heb', 'פָּתַח', '["pâthach"]', '["when/ open/ I"]', '["v"]', 'to open wide (literally or figuratively); specifically, to loosen, begin, plough, carve appear, break forth, draw (out), let go free, (en-) grave(-n), loose (self), (be, be set) open(-ing), put off, ungird, unstop, have vent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5927H}/H9040/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["and/ when/ bring up/ I"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6086I}/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["into/ a piece of wood"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6213H}/H9038/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["and/ I will make/ them"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1463H>', 'opaque', 'heb', 'גּוֹג', '["Gôwg"]', '["Gog","O Gog"]', '["n-pr-m"]', 'Gog, the name of an Israelite, also of some northern nation Gog.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4031H}/[H1463]', 'inflected', 'heb', 'מָגוֹג', '["Mâgôwg"]', '["<the>/ Magog"]', '["n-pr-m n-pr-loc"]', 'Magog, a son of Japheth; also a barbarous northern region Magog.', 'from 1463;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218B>', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["[the] head of"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8422H}/[H8422]', 'inflected', 'heb', 'תּוּבַל', '["Tûwbal"]', '["and/ Tubal"]', '["n-pr-m"]', 'Tubal, a postdiluvian patriarch and his posterity Tubal.', 'or תֻּבַל; probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2428A}/H9021/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["army/ your"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0102}/H9024/[H5062]', 'inflected', 'heb', 'אַגָּף', '["ʼaggâph"]', '["troops/ its"]', '["n-m"]', '(only plural) wings of an army, or crowds of troops bands.', 'probably from 5062 (through the idea of impending); a cover or heap; i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004I}/[H1129]', 'lemma', 'heb', 'בַּיִת', '["bayith"]', '["Beth"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6951}/H9021/[H6950]', 'inflected', 'heb', 'קָהָל', '["qâhâl"]', '["company/ your"]', '["n-m"]', 'assemblage (usually concretely) assembly, company, congregation, multitude.', 'from 6950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6950}/[H6950]', 'inflected', 'heb', 'קָהַל', '["qâhal"]', '["that/ have assembled"]', '["v"]', 'to convoke assemble (selves) (together), gather (selves) (together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4929}/[H8104]', 'inflected', 'heb', 'מִשְׁמָר', '["mishmâr"]', '["<into>/ a guard"]', '["n-m"]', 'a guard (the man, the post or the prison); a deposit (figuratively); also (as observed) a usage (abstractly), or an example (concretely) diligence, guard, office, prison, ward, watch.', 'from 8104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0102}/H9021/[H5062]', 'inflected', 'heb', 'אַגָּף', '["ʼaggâph"]', '["troops/ your"]', '["n-m"]', '(only plural) wings of an army, or crowds of troops bands.', 'probably from 5062 (through the idea of impending); a cover or heap; i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0854}/H9031\/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["with/ you"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6519}/[H6518]', 'lemma', 'heb', 'פְּרָזָה', '["pᵉrâzâh"]', '["open regions","villages"]', '["n-f"]', 'an open country (unwalled) town (without walls), unwalled village.', 'from the same as 6518;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8252}/[H8252]', 'inflected', 'heb', 'שָׁקַט', '["shâqaṭ"]', '["those/ at peace"]', '["v"]', 'to repose (usually figurative) appease, idleness, (at, be at, be in, give) quiet(-ness), (be at, be in, give, have, take) rest, settle, be still.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7075}/[H7069]', 'inflected', 'heb', 'קִנְיָן', '["qinyân"]', '["and/ possession[s]"]', '["n-m"]', 'creation, i.e. (concretely) creatures; also acquisition, purchase, wealth getting, goods, × with money, riches, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1719A>', 'inflected', 'heb', 'ודדן', '["U./de.don"]', '["and/ Dedan"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3715A}/H9024/[H3722]', 'inflected', 'heb', 'כְּפִיר', '["kᵉphîyr"]', '["young lions/ its"]', '["n-m"]', 'a village (as covered in by walls); also a young lion (perhaps as covered with a mane) (young) lion, village. Compare 3723.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9005/{H7997B}/[H7997]', 'inflected', 'heb', 'שָׁלַל', '["shâlal"]', '["¿/ to/ plunder"]', '["v"]', 'to drop or strip; by implication, to plunder let fall, make self a prey, × of purpose, (make a, (take)) spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9005/{H0962}/[H962]', 'inflected', 'heb', 'בָּזַז', '["bâzaz"]', '["¿/ to/ take as spoil"]', '["v"]', 'to plunder catch, gather, (take) for a prey, rob(-ber), spoil, take (away, spoil), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H1463H>', 'inflected', 'heb', 'לגוג', '["le./Gog","le./goyG"]', '["to/ Gog"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1463H>\', 'opaque', 'heb', 'גּוֹג', '["Gôwg"]', '["O Gog"]', '["n-pr-m"]', 'Gog, the name of an Israelite, also of some northern nation Gog.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6931H}/[H6930]', 'lemma', 'heb', 'קַדְמוֹנִי', '["qadmôwnîy"]', '["former"]', '["a"]', '(of time) anterior or (of place) oriental ancient, they that went before, east, (thing of) old.', 'or קַדְמֹנִי; from 6930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7068}/H9020/[H7065]', 'inflected', 'heb', 'קִנְאָה', '["qinʼâh"]', '["and/ in/ jealousy/ my"]', '["n-f"]', 'jealousy or envy envy(-ied), jealousy, × sake, zeal.', 'from 7065;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6440I}/H9020/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["from/ before/ me"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8338}/H9031/[H8338]', 'inflected', 'heb', 'שָׁשָׁא', '["shâshâʼ"]', '["and/ I will lead on/ you"]', '["v"]', 'to annihilate leave by the sixth part (by confusion with 8341).', 'a primitive root; apparently,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7198}/H9021/[H7185]', 'inflected', 'heb', 'קֶשֶׁת', '["qesheth"]', '["bow/ your"]', '["n-f"]', 'a bow, for shooting (hence, figuratively, strength) or the iris × arch(-er), arrow, bow(-man, -shot).', 'from 7185 in the original sense (of 6983) of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2671}/H9021/[H2686]', 'inflected', 'heb', 'חֵץ', '["chêts"]', '["and/ arrows/ your"]', '["n-m"]', 'properly, a piercer, i.e. an arrow; by implication, a wound; figuratively, (of God) thunder-bolt; the shaft of a spear archer, arrow, dart, shaft, staff, wound.', 'from 2686; also by interchange for 6086');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4031H}/[H1463]', 'inflected', 'heb', 'מָגוֹג', '["Mâgôwg"]', '["on/ Magog"]', '["n-pr-m n-pr-loc"]', 'Magog, a son of Japheth; also a barbarous northern region Magog.', 'from 1463;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5400}/[H5400]', 'inflected', 'heb', 'נָשַׂק', '["nâsaq"]', '["and/ they will kindle a fire"]', '["v"]', 'to catch fire burn, kindle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5402}/[H5401]', 'inflected', 'heb', 'נֶשֶׁק', '["nesheq"]', '["with the/ weapon","with/ weapon"]', '["n-m"]', 'military equipment, i.e. (collectively) arms (offensive or defensive), or (concretely) an arsenal armed men, armour(-y), battle, harness, weapon.', 'or נֵשֶׁק; from 5401;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H4731>', 'inflected', 'heb', 'ובמקל', '["u./ve./ma.Kel"]', '["and/ with/ staff of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7997B}/H9038/[H7997]', 'inflected', 'heb', 'שָׁלַל', '["shâlal"]', '["[those who] plundered/ them"]', '["v"]', 'to drop or strip; by implication, to plunder let fall, make self a prey, × of purpose, (make a, (take)) spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0962}/H9038/[H962]', 'inflected', 'heb', 'בָּזַז', '["bâzaz"]', '["[those who] took as spoil/ them","they will plunder/ them"]', '["v"]', 'to plunder catch, gather, (take) for a prey, rob(-ber), spoil, take (away, spoil), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1516O}/[H1466]', 'lemma', 'heb', 'גַּיְא', '["gayʼ"]', '["[the] Valley of"]', '["n"]', 'a gorge (from its lofty sides; hence, narrow, but not a gully or winter-torrent) valley.', 'or (shortened) גַּי; probably (by transmutation) from the same root as 1466 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5674G}/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["the/ Travellers"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2629}/[H2629]', 'inflected', 'heb', 'חָסַם', '["châçam"]', '["and/ [will] block [the] way of"]', '["v"]', 'to muzzle; by analogy, to stop the nose muzzle, stop.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1516N}/[H1466]', 'lemma', 'heb', 'גַּיְא', '["gayʼ"]', '["[the] valley of"]', '["n"]', 'a gorge (from its lofty sides; hence, narrow, but not a gully or winter-torrent) valley.', 'or (shortened) גַּי; probably (by transmutation) from the same root as 1466 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1996}/[H1995]', 'lemma', 'heb', 'הֲמוֹן גּוֹג', '["Hămôwn Gôwg"]', '["Gog","Hamon-"]', '["n-pr-loc"]', 'the multitude of Gog; the fanciful name of an emblematic place in Palestine Hamon-gog.', 'from 1995 and 1463;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6912}/H9038/[H6912]', 'inflected', 'heb', 'קָבַר', '["qâbar"]', '["and/ they will bury/ them"]', '["v"]', 'to inter × in any wise, bury(-ier).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3513G}/H9040/[H3513]', 'inflected', 'heb', 'כָּבַד', '["kâbad"]', '["my glorifying/ myself"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2891}/H9034/[H2891]', 'inflected', 'heb', 'טָהֵר', '["ṭâhêr"]', '["to/ cleanse/ it"]', '["v"]', 'to be pure (physical sound, clear, unadulterated; Levitically, uncontaminated; morally, innocent or holy) be (make, make self, pronounce) clean, cleanse (self), purge, purify(-ier, self).', 'a primitive root; properly, to be bright; i.e. (by implication)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6912}/[H6912]', 'inflected', 'heb', 'קָבַר', '["qâbar"]', '["those/ [who] bury"]', '["v"]', 'to inter × in any wise, bury(-ier).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1997}/[H1995]', 'lemma', 'heb', 'הֲמוֹנָה', '["Hămôwnâh"]', '["[is] Hamonah"]', '["n-pr-loc"]', 'Hamonah Hamonah.', 'feminine of 1995; multitude; , the same as 1996');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6833}/[H6852]', 'inflected', 'heb', 'צִפּוֹר', '["tsippôwr"]', '["to/ bird[s] of"]', '["n-f"]', 'a little bird (as hopping) bird, fowl, sparrow.', 'or צִפֹּר; from 6852;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7943}/[H7937]', 'inflected', 'heb', 'שִׁכָּרוֹן', '["shikkârôwn"]', '["to/ drunkenness"]', '["n-m"]', 'intoxication (be) drunken(-ness).', 'from 7937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2077}/H9020/[H2076]', 'inflected', 'heb', 'זֶבַח', '["zebach"]', '["from/ sacrifice/ my"]', '["n-m"]', 'properly, a slaughter, i.e. the flesh of an animal; by implication, a sacrifice (the victim or the act) offer(-ing), sacrifice.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2932}/H9028/[H2930]', 'inflected', 'heb', 'טֻמְאָה', '["ṭumʼâh"]', '["according to/ uncleanness/ their"]', '["n-f"]', 'religious impurity filthiness, unclean(-ness).', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H6588}/H9028/[H6586]', 'inflected', 'heb', 'פֶּשַׁע', '["peshaʻ"]', '["and/ according to/ transgressions/ their"]', '["n-m"]', 'a revolt (national, moral or religious) rebellion, sin, transgression, trespass.', 'from 6586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5375I}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ they will bear"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4604}/H9028/[H4603]', 'inflected', 'heb', 'מַעַל', '["maʻal"]', '["unfaithfulness/ their"]', '["n-m"]', 'treachery, i.e. sin falsehood, grievously, sore, transgression, trespass, × very.', 'from 4603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3427}/H9048/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["when/ dwell/ they"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1540K}/H9040/[H1540]', 'inflected', 'heb', 'גָּלָה', '["gâlâh"]', '["because/ sent into exile/ I"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3664}/H9038/[H3664]', 'inflected', 'heb', 'כָּנַס', '["kânaç"]', '["and/ I will gather/ them"]', '["v"]', 'to collect; hence, to enfold gather (together), heap up, wrap self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4011}/[H1129]', 'inflected', 'heb', 'מִבְנֶה', '["mibneh"]', '["like/ [the] structure of"]', '["n-m"]', 'a building frame.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6616}/[H6617]', 'inflected', 'heb', 'פָּתִיל', '["pâthîyl"]', '["and/ a cord of"]', '["n-m"]', 'twine bound, bracelet, lace, line, ribband, thread, wire.', 'from 6617;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2948}/[H2946]', 'inflected', 'heb', 'טֹפַח', '["ṭôphach"]', '["and/ a hand breadth"]', '["n-m"]', '(the same as 2947) hand-breadth (broad).', 'from 2946');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1146}/[H1129]', 'inflected', 'heb', 'בִּנְיָן', '["binyân"]', '["the/ structure"]', '["n-m"]', 'an edifice building.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6921}/H9011/[H6923]', 'inflected', 'heb', 'קָדִים', '["qâdîym"]', '["the/ east/ towards"]', '["n-m"]', 'the fore or front part; hence (by orientation) the East (often adverbially, eastward, for brevity the east wind) east(-ward, wind).', 'or קָדִם; from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4609B}/H9023/[H4608]', 'inflected', 'heb', 'מַעֲלָה', '["maʻălâh"]', '["on/ steps/ its"]', '["n-f"]', 'elevation, i.e. the act (literally, a journey to a higher place, figuratively, a thought arising), or (concretely) the condition (literally, a step or grade-mark, figuratively, a superiority of station); specifically a climactic progression (in certain Psalms) things that come up, (high) degree, deal, go up, stair, step, story.', 'feminine of 4608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5592B}/[H5605]', 'lemma', 'heb', 'סַף', '["çaph"]', '["[the] threshold","[the] threshold of"]', '["n-m"]', 'a vestibule (as a limit); also a dish (for holding blood or wine) bason, bowl, cup, door (post), gate, post, threshold.', 'from 5605, in its original sense of containing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7070I}/[H7069]', 'lemma', 'heb', 'קָנֶה', '["qâneh"]', '["a reed","reeds"]', '["n-m"]', 'a reed (as erect); by resemblance a rod (especially for measuring), shaft, tube, stem, the radius (of the arm), beam (of a steelyard) balance, bone, branch, calamus, cane, reed, × spearman, stalk.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8372}/[H8376]', 'inflected', 'heb', 'תָּא', '["tâʼ"]', '["and/ the/ chamber"]', '["n-m"]', 'a room (as circumscribed) (little) chamber.', 'and (feminine) תָּאָה; (Ezekiel 40:12), from (the base of) 8376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8372}/[H8376]', 'inflected', 'heb', 'תָּא', '["tâʼ"]', '["the/ chamber","the/ chambers"]', '["n-m"]', 'a room (as circumscribed) (little) chamber.', 'and (feminine) תָּאָה; (Ezekiel 40:12), from (the base of) 8376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5592B}/[H5605]', 'inflected', 'heb', 'סַף', '["çaph"]', '["and/ [the] threshold of"]', '["n-m"]', 'a vestibule (as a limit); also a dish (for holding blood or wine) bason, bowl, cup, door (post), gate, post, threshold.', 'from 5605, in its original sense of containing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H1004O}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["[was] from/ the/ inside","from/ the/ inside"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0352B}/H9023/[H193]', 'inflected', 'heb', 'אַיִל', '["ʼayil"]', '["and/ pillars/ its"]', '["n-m"]', 'properly, strength; hence, anything strong; specifically a chief (politically); also a ram (from his strength); a pilaster (as a strong support); an oak or other strong tree mighty (man), lintel, oak, post, ram, tree.', 'from the same as 193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0197J}/[H481]', 'inflected', 'heb', 'אוּלָם', '["ʼûwlâm"]', '["and/ [the] porch of","and/ [the] porches of"]', '["n-m"]', 'a vestibule (as bound to the building) porch.', 'or (shortened), אֻלָם ; from 481 (in the sense of tying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8372}/[H8376]', 'inflected', 'heb', 'תָּא', '["tâʼ"]', '["and/ [the] chambers of"]', '["n-m"]', 'a room (as circumscribed) (little) chamber.', 'and (feminine) תָּאָה; (Ezekiel 40:12), from (the base of) 8376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6311}/[H1931]', 'inflected', 'heb', 'פֹּה', '["pôh"]', '["from/ here"]', '["adv"]', 'this place (French ici), i.e. here or hence here, hither, the one (other, this, that) side.', 'or פֹּא; (Job 38:11), or פּוֹ; probably from a primitive inseparable particle ''p'' (of demonstrative force) and 1931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7969}/H9028/[H7969]', 'inflected', 'heb', 'שָׁלוֹשׁ', '["shâlôwsh"]', '["<to>/ [the] three of/ them","[belonged] to/ [the] three of/ them"]', '["n"]', 'three; occasionally (ordinal) third, or (multiple) thrice fork, often(-times), third, thir(-teen, -teenth), three, thrice. Compare 7991.', 'or שָׁלֹשׁ; masculine שְׁלוֹשָׁה; or שְׁלֹשָׁה; a primitive number;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0352B}/[H193]', 'inflected', 'heb', 'אַיִל', '["ʼayil"]', '["[belonged] to the/ pillars"]', '["n-m"]', 'properly, strength; hence, anything strong; specifically a chief (politically); also a ram (from his strength); a pilaster (as a strong support); an oak or other strong tree mighty (man), lintel, oak, post, ram, tree.', 'from the same as 193;');
