INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7531A}/[H7529]', 'inflected', 'heb', 'רִצְפָּה', '["ritspâh"]', '["and/ a pavement"]', '["n-f"]', 'a hot stone; also a tessellated pavement live coal, pavement.', 'feminine of 7529;');
