INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6828G}/[H6845]', 'inflected', 'heb', 'צָפוֹן', '["tsâphôwn"]', '["and/ the/ north"]', '["n-f"]', 'properly, hidden, i.e. dark; used only of the north as a quarter (gloomy and unknown) north(-ern, side, -ward, wind).', 'or צָפֹן; from 6845;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8372}/H9023/[H8376]', 'inflected', 'heb', 'תָּא', '["tâʼ"]', '["and/ chambers/ its"]', '["n-m"]', 'a room (as circumscribed) (little) chamber.', 'and (feminine) תָּאָה; (Ezekiel 40:12), from (the base of) 8376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0361}/H9023/[H352]', 'inflected', 'heb', 'אֵילָם', '["ʼêylâm"]', '["and/ porches/ its"]', '["n-m"]', 'a pillar-space (or colonnade), i.e. a pale (or portico) arch.', 'or (shortened) אֵלָם ; or (feminine) אֵלַמָּה ; probably from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2474}/H9023/[H2474]', 'inflected', 'heb', 'חַלּוֹן', '["challôwn"]', '["and/ windows/ its"]', '["n"]', 'a window (as perforated) window.', NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8561}/H9023/[H8558]', 'inflected', 'heb', 'תִּמֹּר', '["timmôr"]', '["and/ palm trees/ its"]', '["n-f"]', '(architectural) a palm-like pilaster (i.e. umbellate) palm tree.', '(plural or (feminine) תִּמֹּרָה; (singular and plural), from the same root as 8558;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4609B}/[H4608]', 'inflected', 'heb', 'מַעֲלָה', '["maʻălâh"]', '["and/ by/ steps","and/ on the/ steps"]', '["n-f"]', 'elevation, i.e. the act (literally, a journey to a higher place, figuratively, a thought arising), or (concretely) the condition (literally, a step or grade-mark, figuratively, a superiority of station); specifically a climactic progression (in certain Psalms) things that come up, (high) degree, deal, go up, stair, step, story.', 'feminine of 4608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6921}/[H6923]', 'inflected', 'heb', 'קָדִים', '["qâdîym"]', '["and/ to the/ east"]', '["n-m"]', 'the fore or front part; hence (by orientation) the East (often adverbially, eastward, for brevity the east wind) east(-ward, wind).', 'or קָדִם; from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1980J}/H9030/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ he led/ me"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1864>', 'inflected', 'heb', 'הדרום', '["ha./da.Rom","ha./da.rOm"]', '["the/ south"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0352B}/H9023/[H193]', 'inflected', 'heb', 'אַיִל', '["ʼayil"]', '["pillars/ its"]', '["n-m"]', 'properly, strength; hence, anything strong; specifically a chief (politically); also a ram (from his strength); a pilaster (as a strong support); an oak or other strong tree mighty (man), lintel, oak, post, ram, tree.', 'from the same as 193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0361}/H9023/[H352]', 'inflected', 'heb', 'אֵילָם', '["ʼêylâm"]', '["and/ to/ porches/ its"]', '["n-m"]', 'a pillar-space (or colonnade), i.e. a pale (or portico) arch.', 'or (shortened) אֵלָם ; or (feminine) אֵלַמָּה ; probably from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/H9009/{H2474}/[H2474]', 'inflected', 'heb', 'חַלּוֹן', '["challôwn"]', '["like/ the/ windows"]', '["n"]', 'a window (as perforated) window.', NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4609B}/[H4608]', 'inflected', 'heb', 'מַעֲלָה', '["maʻălâh"]', '["and/ [was] steps"]', '["n-f"]', 'elevation, i.e. the act (literally, a journey to a higher place, figuratively, a thought arising), or (concretely) the condition (literally, a step or grade-mark, figuratively, a superiority of station); specifically a climactic progression (in certain Psalms) things that come up, (high) degree, deal, go up, stair, step, story.', 'feminine of 4608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5930B}/H9023/[H5927]', 'inflected', 'heb', 'עֹלָה', '["ʻôlâh"]', '["stairways/ its"]', '["n-f"]', 'a step or (collectively, stairs, as ascending); usually a holocaust (as going up in smoke) ascent, burnt offering (sacrifice), go up to. See also 5766.', 'or עוֹלָה; feminine active participle of 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0361}/[H352]', 'inflected', 'heb', 'אֵילָם', '["ʼêylâm"]', '["and/ porches"]', '["n-m"]', 'a pillar-space (or colonnade), i.e. a pale (or portico) arch.', 'or (shortened) אֵלָם ; or (feminine) אֵלַמָּה ; probably from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4608}/H9023/[H5927]', 'inflected', 'heb', 'מַעֲלֶה', '["maʻăleh"]', '["ascents/ its"]', '["n-m"]', 'an elevation, i.e. (concretely) acclivity or platform; abstractly (the relation or state) a rise or (figuratively) priority ascent, before, chiefest, cliff, that goeth up, going up, hill, mounting up, stairs.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8372}/H9023/[H8376]', 'inflected', 'heb', 'תָּא', '["tâʼ"]', '["chambers/ its"]', '["n-m"]', 'a room (as circumscribed) (little) chamber.', 'and (feminine) תָּאָה; (Ezekiel 40:12), from (the base of) 8376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3957>', 'inflected', 'heb', 'ולשכה', '["ve./lish.Kah"]', '["and/ a room"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6607}/H9024/[H6605]', 'inflected', 'heb', 'פֶּתַח', '["pethach"]', '["and/ entrance/ its"]', '["n-m"]', 'an opening (literally), i.e. door (gate) or entrance way door, entering (in), entrance (-ry), gate, opening, place.', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0352B}/[H193]', 'inflected', 'heb', 'אַיִל', '["ʼayil"]', '["[was] at/ pillars"]', '["n-m"]', 'properly, strength; hence, anything strong; specifically a chief (politically); also a ram (from his strength); a pilaster (as a strong support); an oak or other strong tree mighty (man), lintel, oak, post, ram, tree.', 'from the same as 193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0197J}/[H481]', 'inflected', 'heb', 'אוּלָם', '["ʼûwlâm"]', '["and/ [were] in/ [the] porch of"]', '["n-m"]', 'a vestibule (as bound to the building) porch.', 'or (shortened), אֻלָם ; from 481 (in the sense of tying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0817}/[H816]', 'inflected', 'heb', 'אָשָׁם', '["ʼâshâm"]', '["and/ the/ guilt offering"]', '["n-m"]', 'guilt; by implication, a fault; also a sin-offering guiltiness, (offering for) sin, trespass (offering).', 'from 816;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H2351>/H9011', 'inflected', 'heb', 'מחוצה', '["mi./Chu.tza/h"]', '["from/ outside/ <towards>"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8240B}/[H8239]', 'inflected', 'heb', 'שָׁפָת', '["shâphâth"]', '["and/ the/ hooks"]', '["n-m"]', 'a (double) stall (for cattle); also a (two-pronged) hook (for flaying animals on) hook, pot.', 'from 8239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1004O}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["in the/ inside"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7133A}/[H7126]', 'inflected', 'heb', 'קׇרְבָּן', '["qorbân"]', '["the/ offering"]', '["n-m"]', 'something brought near the altar, i.e. a sacrificial present oblation, that is offered, offering.', 'or קֻרְבָּן; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H2351>/H9011', 'inflected', 'heb', 'ומחוצה', '["u./mi./chu.Tza/h"]', '["and/ from/ [the] outside/ <towards>"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6440G}/H9028/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["and/ faces/ their"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H3957>', 'inflected', 'heb', 'והלשכות', '["ve./ha./le.sha.Khot","ve./ha./lish.Kah"]', '["and/ the/ room","and/ the/ rooms"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0168H}/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["the/ tent"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6607}/[H6605]', 'inflected', 'heb', 'פֶּתַח', '["pethach"]', '["and/ the/ entrance"]', '["n-m"]', 'an opening (literally), i.e. door (gate) or entrance way door, entering (in), entrance (-ry), gate, opening, place.', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6763}/[H6760]', 'inflected', 'heb', 'צֵלָע', '["tsêlâʻ"]', '["and/ the/ side-chambers"]', '["n-f"]', 'a rib (as curved), literally (of the body) or figuratively (of a door, i.e. leaf); hence, a side, literally (of a person) or figuratively (of an object or the sky, i.e. quarter); architecturally, a (especially floor or ceiling) timber or plank (single or collective, i.e. a flooring) beam, board, chamber, corner, leaf, plank, rib, side (chamber).', 'or (feminine) צַלְעָה; from 6760;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0935I}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ [were] going"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6763}/[H6760]', 'inflected', 'heb', 'צֵלָע', '["tsêlâʻ"]', '["[belonged] to the/ side-chamber","for the/ side-chambers","to the/ side-chambers"]', '["n-f"]', 'a rib (as curved), literally (of the body) or figuratively (of a door, i.e. leaf); hence, a side, literally (of a person) or figuratively (of an object or the sky, i.e. quarter); architecturally, a (especially floor or ceiling) timber or plank (single or collective, i.e. a flooring) beam, board, chamber, corner, leaf, plank, rib, side (chamber).', 'or (feminine) צַלְעָה; from 6760;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4141}/[H5437]', 'lemma', 'heb', 'מוּסָב', '["mûwçâb"]', '["[the] surrounding of"]', '["n-m"]', 'a turn, i.e. circuit (of a building) winding about.', 'from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8484}/[H8432]', 'inflected', 'heb', 'תִּיכוֹן', '["tîykôwn"]', '["to the/ middle [story]"]', '["a"]', 'central middle(-most), midst.', 'or תִּיכֹן; from 8432;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H1864>', 'inflected', 'heb', 'לדרום', '["la./da.Rom"]', '["[was] to the/ south"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5117}/[H5117]', 'inflected', 'heb', 'נוּחַ', '["nûwach"]', '["the/ free space"]', '["v"]', 'to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1146}/[H1129]', 'inflected', 'heb', 'בִּנְיָן', '["binyân"]', '["and/ the/ structure"]', '["n-m"]', 'an edifice building.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1508}/[H1506]', 'inflected', 'heb', 'גִּזְרָה', '["gizrâh"]', '["the/ separate place"]', '["n-f"]', 'the figure or person (as if cut out); also an inclosure (as separated) polishing, separate place.', 'feminine of 1506;');
