INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7023}/H9024/[H6979]', 'inflected', 'heb', 'קִיר', '["qîyr"]', '["and/ walls/ its"]', '["n-m"]', 'a wall (as built in a trench) mason, side, town, × very, wall.', 'or קִר; (Isaiah 22:5), or (feminine) קִירָה; from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6921}/[H6923]', 'inflected', 'heb', 'קָדִים', '["qâdîym"]', '["to the/ east"]', '["n-m"]', 'the fore or front part; hence (by orientation) the East (often adverbially, eastward, for brevity the east wind) east(-ward, wind).', 'or קָדִם; from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0862B}/H9024/[H5423]', 'inflected', 'heb', 'אַתּוּק', '["ʼattûwq"]', '["and/ galleries/ its"]', '["n-m"]', 'a ledge or offset in a building gallery.', 'or אַתִּיק; from 5423 in the sense of decreasing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1964I}/[H3201]', 'inflected', 'heb', 'הֵיכָל', '["hêykâl"]', '["and/ the/ temple"]', '["n-m"]', 'a large public building, such as a palace or temple palace, temple.', 'probably from 3201 (in the sense of capacity);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2474}/[H2474]', 'inflected', 'heb', 'חַלּוֹן', '["challôwn"]', '["and/ the/ windows"]', '["n"]', 'a window (as perforated) window.', NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0331}/[H331]', 'inflected', 'heb', 'אָטַם', '["ʼâṭam"]', '["<the>/ closed"]', '["v"]', 'to close (the lips or ears); by analology to contract (a window by bevelled jambs) narrow, shut, stop.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0862B}/[H5423]', 'inflected', 'heb', 'אַתּוּק', '["ʼattûwq"]', '["and/ the/ galleries"]', '["n-m"]', 'a ledge or offset in a building gallery.', 'or אַתִּיק; from 5423 in the sense of decreasing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7824}/[H7828]', 'lemma', 'heb', 'שָׁחִיף', '["shâchîyph"]', '["paneled of"]', '["a"]', 'a board (as chipped thin) cieled with.', 'from the same as 7828;');
