INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6442}/[H6440]', 'inflected', 'heb', 'פְּנִימִי', '["pᵉnîymîy"]', '["in the/ inner [part]"]', '["a"]', 'interior (with-) in(-ner, -ward).', 'from 6440;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2435}/[H2434]', 'inflected', 'heb', 'חִיצוֹן', '["chîytsôwn"]', '["and/ in the/ outer [part]"]', '["a"]', 'properly, the (outer) wall side; hence, exterior; figuratively, secular (as opposed to sacred) outer, outward, utter, without.', 'from 2434;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8561}/[H8558]', 'inflected', 'heb', 'תִּמֹּר', '["timmôr"]', '["and/ the/ palm trees"]', '["n-f"]', '(architectural) a palm-like pilaster (i.e. umbellate) palm tree.', '(plural or (feminine) תִּמֹּרָה; (singular and plural), from the same root as 8558;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4740H}/H9023/[H7106]', 'inflected', 'heb', 'מַקְצוֹעַ', '["maqtsôwaʻ"]', '["and/ corners/ its"]', '["n-m"]', 'an angle or recess corner, turning.', 'or מַקְצֹעַ; or (feminine) מַקְצֹעָה; from 7106 in the denominative sense of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6944J}/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["and/ to the/ holy place"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/<H2351>', 'inflected', 'heb', 'מהחוץ', '["me./ha./Chutz"]', '["from/ the/ outside"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6763}/[H6760]', 'inflected', 'heb', 'צֵלָע', '["tsêlâʻ"]', '["and/ [the] side-chambers of"]', '["n-f"]', 'a rib (as curved), literally (of the body) or figuratively (of a door, i.e. leaf); hence, a side, literally (of a person) or figuratively (of an object or the sky, i.e. quarter); architecturally, a (especially floor or ceiling) timber or plank (single or collective, i.e. a flooring) beam, board, chamber, corner, leaf, plank, rib, side (chamber).', 'or (feminine) צַלְעָה; from 6760;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H5646>', 'inflected', 'heb', 'והעבים', '["ve./ha./''u.Bim"]', '["and/ the/ thresholds"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7341}/[H7337]', 'inflected', 'heb', 'רֹחַב', '["rôchab"]', '["and/ the/ breadth"]', '["n-m"]', 'width (literally or figuratively) breadth, broad, largeness, thickness, wideness.', 'from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0862B}/[H5423]', 'lemma', 'heb', 'אַתּוּק', '["ʼattûwq"]', '["a gallery","galleries"]', '["n-m"]', 'a ledge or offset in a building gallery.', 'or אַתִּיק; from 5423 in the sense of decreasing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4109}/[H1980]', 'lemma', 'heb', 'מַהֲלָךְ', '["mahălâk"]', '["a journey of","a passage of","goings"]', '["n-m"]', 'a walk, i.e. a passage or a distance journey, walk.', 'from 1980;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6607}/H9028/[H6605]', 'inflected', 'heb', 'פֶּתַח', '["pethach"]', '["and/ entrances/ their"]', '["n-m"]', 'an opening (literally), i.e. door (gate) or entrance way door, entering (in), entrance (-ry), gate, opening, place.', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H8481H}/[H8478]', 'inflected', 'heb', 'תַּחְתּוֹן', '["tachtôwn"]', '["more than/ the/ lower [rooms]"]', '["a"]', 'bottommost lower(-est), nether(-most).', 'or תַּחְתֹּן; from 8478;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/H9009/{H8484}/[H8432]', 'inflected', 'heb', 'תִּיכוֹן', '["tîykôwn"]', '["and/ more than/ the/ middle [rooms]"]', '["a"]', 'central middle(-most), midst.', 'or תִּיכֹן; from 8432;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1146}/[H1129]', 'lemma', 'heb', 'בִּנְיָן', '["binyân"]', '["[the] structure"]', '["n-m"]', 'an edifice building.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5982G}/[H5975]', 'inflected', 'heb', 'עַמּוּד', '["ʻammûwd"]', '["like/ [the] columns of"]', '["n-m"]', 'a column (as standing); also a stand, i.e. platform × apiece, pillar.', 'or עַמֻּד; from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H6921}/[H6923]', 'inflected', 'heb', 'קָדִים', '["qâdîym"]', '["from/ the/ east"]', '["n-m"]', 'the fore or front part; hence (by orientation) the East (often adverbially, eastward, for brevity the east wind) east(-ward, wind).', 'or קָדִם; from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H2691A}/[H2690]', 'inflected', 'heb', 'חָצֵר', '["châtsêr"]', '["from/ the/ courtyard"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1444}/[H1443]', 'lemma', 'heb', 'גֶּדֶר', '["geder"]', '["[the] wall of"]', '["n-m"]', 'a circumvallation wall.', 'from 1443;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0753}/H9029/[H748]', 'inflected', 'heb', 'אֹרֶךְ', '["ʼôrek"]', '["like/ length/ their"]', '["n-m"]', 'length forever, length, long.', 'from 748;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7341}/H9029/[H7337]', 'inflected', 'heb', 'רֹחַב', '["rôchab"]', '["breadth/ their"]', '["n-m"]', 'width (literally or figuratively) breadth, broad, largeness, thickness, wideness.', 'from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4161}/H9029/[H3318]', 'inflected', 'heb', 'מוֹצָא', '["môwtsâʼ"]', '["exits/ their"]', '["n-m"]', 'a going forth, i.e. (the act) an egress, or (the place) an exit; hence, a source or product; specifically, dawn, the rising of the sun (the East), exportation, utterance, a gate, a fountain, a mine, a meadow (as producing grass) brought out, bud, that which came out, east, going forth, goings out, that which (thing that) is gone out, outgoing, proceeded out, spring, vein, (water-) course (springs).', 'or מֹצָאxlit môtsâ corrected to môtsâʼ; from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H4941J}/H9029/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["and/ like/ plans/ their"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H6607}/H9029/[H6605]', 'inflected', 'heb', 'פֶּתַח', '["pethach"]', '["and/ like/ entrances/ their"]', '["n-m"]', 'an opening (literally), i.e. door (gate) or entrance way door, entering (in), entrance (-ry), gate, opening, place.', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H6607}/[H6605]', 'inflected', 'heb', 'פֶּתַח', '["pethach"]', '["and/ like/ [the] entrances of"]', '["n-m"]', 'an opening (literally), i.e. door (gate) or entrance way door, entering (in), entrance (-ry), gate, opening, place.', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6440G}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["in/ front of"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1448}/[H1447]', 'inflected', 'heb', 'גְּדֵרָה', '["gᵉdêrâh"]', '["the/ wall"]', '["n-f"]', 'inclosure (especially for flocks) (sheep-) cote (fold) hedge, wall.', 'feminine of 1447;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1903>', 'opaque', 'heb', 'הָגִין', '["hâgîyn"]', '["corresponding"]', '["a"]', 'perhaps suitable or turning directly.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0935G}/H9039/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["when/ come [to]/ them"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H4503G>', 'inflected', 'heb', 'והמנחה', '["ve./ha./min.Chah"]', '["and/ the/ grain offering"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H6944J}/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["from/ the/ holy place"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4058}/H9033/[H4058]', 'inflected', 'heb', 'מָדַד', '["mâdad"]', '["and/ he measured/ it"]', '["v"]', 'properly, to stretch; by implication, to measure (as if by stretching a line); figuratively, to be extended measure, mete, stretch self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7070I}/[H7069]', 'inflected', 'heb', 'קָנֶה', '["qâneh"]', '["by/ [the] reed of"]', '["n-m"]', 'a reed (as erect); by resemblance a rod (especially for measuring), shaft, tube, stem, the radius (of the arm), beam (of a steelyard) balance, bone, branch, calamus, cane, reed, × spearman, stalk.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4058}/H9033/[H4058]', 'inflected', 'heb', 'מָדַד', '["mâdad"]', '["he measured/ it"]', '["v"]', 'properly, to stretch; by implication, to measure (as if by stretching a line); figuratively, to be extended measure, mete, stretch self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6963H>/H9023', 'inflected', 'heb', 'וקולו', '["ve./ko.L/o"]', '["and/ sound/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3519}/H9023/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["from/ glory/ his"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H4758}/[H7200]', 'inflected', 'heb', 'מַרְאֶה', '["marʼeh"]', '["and/ like/ [the] appearance of"]', '["n-m"]', 'a view (the act of seeing); also an appearance (the thing seen), whether (real) a shape (especially if handsome, comeliness; often plural the looks), or (mental) a vision × apparently, appearance(-reth), × as soon as beautiful(-ly), countenance, fair, favoured, form, goodly, to look (up) on (to), look(-eth), pattern, to see, seem, sight, visage, vision.', 'from 7200a;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4759A}/[H4758]', 'inflected', 'heb', 'מַרְאָה', '["marʼâh"]', '["and/ visions"]', '["n-f"]', 'a vision; also (causatively) a mirror looking glass, vision.', 'feminine of 4758;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H1004B}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["from/ the/ house"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2184}/H9028/[H2181]', 'inflected', 'heb', 'זְנוּת', '["zᵉnûwth"]', '["by/ prostitution/ their"]', '["n-f"]', 'adultery, i.e. (figuratively) infidelity, idolatry whoredom.', 'from 2181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6297}/[H6296]', 'inflected', 'heb', 'פֶּגֶר', '["peger"]', '["and/ by/ [the] corpses of"]', '["n-m"]', 'a carcase (as limp), whether of man or beast; figuratively, an idolatrous image carcase, corpse, dead body.', 'from 6296;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5414H}/H9048/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["when/ put/ they"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5592B}/H9028/[H5605]', 'inflected', 'heb', 'סַף', '["çaph"]', '["threshold/ their"]', '["n-m"]', 'a vestibule (as a limit); also a dish (for holding blood or wine) bason, bowl, cup, door (post), gate, post, threshold.', 'from 5605, in its original sense of containing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5592B}/H9020/[H5605]', 'inflected', 'heb', 'סַף', '["çaph"]', '["threshold/ my"]', '["n-m"]', 'a vestibule (as a limit); also a dish (for holding blood or wine) bason, bowl, cup, door (post), gate, post, threshold.', 'from 5605, in its original sense of containing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4201}/H9028/[H2123]', 'inflected', 'heb', 'מְזוּזָה', '["mᵉzûwzâh"]', '["and/ doorpost/ their"]', '["n-f"]', 'a door-post (as prominent) (door, side) post.', 'or מְזֻזָה; from the same as 2123;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4201}/H9020/[H2123]', 'inflected', 'heb', 'מְזוּזָה', '["mᵉzûwzâh"]', '["doorpost/ my"]', '["n-f"]', 'a door-post (as prominent) (door, side) post.', 'or מְזֻזָה; from the same as 2123;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7023}/[H6979]', 'inflected', 'heb', 'קִיר', '["qîyr"]', '["and/ the/ wall"]', '["n-m"]', 'a wall (as built in a trench) mason, side, town, × very, wall.', 'or קִר; (Isaiah 22:5), or (feminine) קִירָה; from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2184}/H9028/[H2181]', 'inflected', 'heb', 'זְנוּת', '["zᵉnûwth"]', '["prostitution/ their"]', '["n-f"]', 'adultery, i.e. (figuratively) infidelity, idolatry whoredom.', 'from 2181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5771G}/H9028/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["from/ iniquities/ their"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6699}/[H6697]', 'lemma', 'heb', 'צוּרָה', '["tsûwrâh"]', '["[the] design of"]', '["n-f"]', 'a rock (Job 28:10); also a form (as if pressed out) form, rock.', 'feminine of 6697;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8498}/H9023/[H8505]', 'inflected', 'heb', 'תְּכוּנָה', '["tᵉkûwnâh"]', '["and/ arrangement/ its"]', '["n-f"]', 'adjustment, i.e. structure; by implication, equipage fashion, store.', 'feminine passive participle of 8505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4161}/H9023/[H3318]', 'inflected', 'heb', 'מוֹצָא', '["môwtsâʼ"]', '["and/ exits/ its"]', '["n-m"]', 'a going forth, i.e. (the act) an egress, or (the place) an exit; hence, a source or product; specifically, dawn, the rising of the sun (the East), exportation, utterance, a gate, a fountain, a mine, a meadow (as producing grass) brought out, bud, that which came out, east, going forth, goings out, that which (thing that) is gone out, outgoing, proceeded out, spring, vein, (water-) course (springs).', 'or מֹצָאxlit môtsâ corrected to môtsâʼ; from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4126}/H9023/[H3996]', 'inflected', 'heb', 'מוֹבָא', '["môwbâʼ"]', '["and/ entrances/ its"]', '["n-m"]', 'an entrance coming.', 'by transp. for 3996;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6699}/H9023/[H6697]', 'inflected', 'heb', 'צוּרָה', '["tsûwrâh"]', '["design/ its","designs/ its"]', '["n-f"]', 'a rock (Job 28:10); also a form (as if pressed out) form, rock.', 'feminine of 6697;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H2436I>', 'inflected', 'heb', 'וחיק', '["ve./Cheik"]', '["and/ a gutter"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1366G}/H9024/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["and/ border/ its"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8193I}/H9024/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["edge/ its"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H2436I>', 'inflected', 'heb', 'ומחיק', '["u./me./Cheik"]', '["and/ from/ [the] gutter of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/H9009/{H5835}/[H5826]', 'inflected', 'heb', 'עֲזָרָה', '["ʻăzârâh"]', '["and/ from/ the/ ledge"]', '["n-f"]', 'an inclosure; also a border court, settle.', 'from 5826 in its original meaning of surrounding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2025}/[H2022]', 'inflected', 'heb', 'הַרְאֵל', '["harʼêl"]', '["and/ the/ altar hearth"]', '["n-m"]', 'mount of God; figuratively, the altar of burnt-offering altar. Compare 739.', 'from 2022 and 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/H9009/{H0741}/[H739]', 'inflected', 'heb', 'אֲרִאֵיל', '["ʼăriʼêyl"]', '["and/ [are] from/ the/ altar hearth"]', '["n-m"]', 'the altar of the temple altar.', 'either by transposition for 739 or, more probably, an orthographical variation for 2025;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7161A}/[H7160]', 'inflected', 'heb', 'קֶרֶן', '["qeren"]', '["[are] the/ horns","the/ horn","the/ horns","the/ two horns"]', '["n-f n-pr-loc"]', 'a horn (as projecting); by implication, a flask, cornet; by resemblance. an elephant''s tooth (i.e. ivory), a corner (of the altar), a peak (of a mountain), a ray (of light); figuratively, power × hill, horn.', 'from 7160;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0741}/[H739]', 'inflected', 'heb', 'אֲרִאֵיל', '["ʼăriʼêyl"]', '["and/ the/ altar hearth"]', '["n-m"]', 'the altar of the temple altar.', 'either by transposition for 739 or, more probably, an orthographical variation for 2025;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7253}/H9023/[H7251]', 'inflected', 'heb', 'רֶבַע', '["rebaʻ"]', '["sides/ its"]', '["n-m"]', 'a fourth (part or side) fourth part, side, square.', 'from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7253}/H9024/[H7251]', 'inflected', 'heb', 'רֶבַע', '["rebaʻ"]', '["sides/ its"]', '["n-m"]', 'a fourth (part or side) fourth part, side, square.', 'from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1366G}/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["and/ the/ border"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H2436I>', 'inflected', 'heb', 'והחיק', '["ve./ha./cheik"]', '["and/ the/ gutter"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4609B}/H9023/[H4608]', 'inflected', 'heb', 'מַעֲלָה', '["maʻălâh"]', '["and/ steps/ its"]', '["n-f"]', 'elevation, i.e. the act (literally, a journey to a higher place, figuratively, a thought arising), or (concretely) the condition (literally, a step or grade-mark, figuratively, a superiority of station); specifically a climactic progression (in certain Psalms) things that come up, (high) degree, deal, go up, stair, step, story.', 'feminine of 4608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213H}/H9043/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["is made/ it"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2236}/[H2236]', 'inflected', 'heb', 'זָרַק', '["zâraq"]', '["and/ to/ sprinkle"]', '["v"]', 'to sprinkle (fluid or solid particles) be here and there, scatter, sprinkle, strew.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8334}/H9030/[H8334]', 'inflected', 'heb', 'שָׁרַת', '["shârath"]', '["to/ serve/ me"]', '["v"]', 'to attend as a menial or worshipper; figuratively, to contribute to minister (unto), (do) serve(-ant, -ice, -itor), wait on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3722A}/H9033/[H3722]', 'inflected', 'heb', 'כָּפַר', '["kâphar"]', '["and/ you will make atonement for/ it"]', '["v"]', 'to cover (specifically with bitumen); figuratively, to expiate or condone, to placate or cancel appease, make (an atonement, cleanse, disannul, forgive, be merciful, pacify, pardon, purge (away), put off, (make) reconcile(-liation).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8313}/H9033/[H8313]', 'inflected', 'heb', 'שָׂרַף', '["sâraph"]', '["and/ someone will burn/ it"]', '["v"]', 'to be (causatively, set) on fire (cause to, make a) burn((-ing), up) kindle, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3615G}/H9041/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["when/ finishing/ you"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7126H}/H9038/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["and/ you will bring near/ them"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1870K}/H9023/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["and/ from/ way/ its"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0935P}/H9046/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["when/ brought/ you"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4720}/H9020/[H6942]', 'inflected', 'heb', 'מִקְדָּשׁ', '["miqdâsh"]', '["in/ sanctuary/ my"]', '["n-m"]', 'a consecrated thing or place, especially, a palace, sanctuary (whether of Jehovah or of idols) or asylum chapel, hallowed part, holy place, sanctuary.', 'or מִקְּדָשׁ; (Exodus 15:17), from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7760A}/H9013/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ you appointed [them]/ !"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8582}/[H8582]', 'inflected', 'heb', 'תָּעָה', '["tâʻâh"]', '["when/ went astray"]', '["v"]', 'to vacillate, i.e. reel or stray (literally or figuratively); also causative of both (cause to) go astray, deceive, dissemble, (cause to, make to) err, pant, seduce, (make to) stagger, (cause to) wander, be out of the way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8334}/[H8334]', 'inflected', 'heb', 'שָׁרַת', '["shârath"]', '["and/ serving"]', '["v"]', 'to attend as a menial or worshipper; figuratively, to contribute to minister (unto), (do) serve(-ant, -ice, -itor), wait on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5066G}/[H5066]', 'inflected', 'heb', 'נָגַשׁ', '["nâgash"]', '["and/ to/ draw near"]', '["v"]', 'to be or come (causatively, bring) near (for any purpose); euphemistically, to lie with a woman; as an enemy, to attack; religious to worship; causatively, to present; figuratively, to adduce an argument; by reversal, to stand back (make to) approach (nigh), bring (forth, hither, near), (cause to) come (hither, near, nigh), give place, go hard (up), (be, draw, go) near (nigh), offer, overtake, present, put, stand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8334}/H9048/[H8334]', 'inflected', 'heb', 'שָׁרַת', '["shârath"]', '["when/ serve/ they"]', '["v"]', 'to attend as a menial or worshipper; figuratively, to contribute to minister (unto), (do) serve(-ant, -ice, -itor), wait on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4975>/H9028', 'opaque', 'heb', 'מֹתֶן', '["môthen"]', '["loins/ their"]', '["n-m"]', 'properly, the waist or small of the back; only in plural the loins greyhound, loins, side.', 'from an unused root meaning to be slender;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3154>', 'inflected', 'heb', 'ביזע', '["ba/i.Ya.za''"]', '["with <the>/ sweat"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6942K}/[H6942]', 'lemma', 'heb', 'קָדַשׁ', '["qâdash"]', '["they will consecrate"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0899B}/H9028/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["by/ clothes/ their"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7218A>/H9028', 'inflected', 'heb', 'וראשם', '["ve./ro.Sha/m"]', '["and/ head/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6545}/[H6544]', 'inflected', 'heb', 'פֶּרַע', '["peraʻ"]', '["and/ hair"]', '["n-m"]', 'the hair (as dishevelled) locks.', 'from 6544;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3697}/[H3697]', 'lemma', 'heb', 'כָּסַם', '["kâçam"]', '["surely <trim>","they will trim"]', '["v"]', 'to shear × only, poll. Compare 3765.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0517}/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["and/ for/ a mother"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1323G}/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["and/ for/ a daughter"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0269}/[H251]', 'inflected', 'heb', 'אָחוֹת', '["ʼâchôwth"]', '["and/ for/ a sister"]', '["n-f"]', 'a sister (used very widely [like 251number 250, corrected to 251], literally and figuratively) (an-) other, sister, together.', 'irregular feminine of 251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0272}/[H270]', 'inflected', 'heb', 'אֲחֻזָּה', '["ʼăchuzzâh"]', '["and/ [the] possession of","and/ a possession"]', '["n-f"]', 'something seized, i.e. a possession (especially of land) possession.', 'feminine passive participle from 270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5307I}/H9046/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["and/ when/ make fall/ you"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4720}/[H6942]', 'inflected', 'heb', 'מִקְדָּשׁ', '["miqdâsh"]', '["and/ [the] sanctuaries of","and/ [the] sanctuary of","and/ a holy place"]', '["n-m"]', 'a consecrated thing or place, especially, a palace, sanctuary (whether of Jehovah or of idols) or asylum chapel, hallowed part, holy place, sanctuary.', 'or מִקְּדָשׁ; (Exodus 15:17), from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5387A}/[H5375]', 'inflected', 'heb', 'נָשִׂיא', '["nâsîyʼ"]', '["and/ [will belong] to the/ prince"]', '["n-m"]', 'properly, an exalted one, i.e. a king or sheik; also a rising mist captain, chief, cloud, governor, prince, ruler, vapour.', 'or נָשִׂא; from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0272}/[H270]', 'inflected', 'heb', 'אֲחֻזָּה', '["ʼăchuzzâh"]', '["and/ of/ [the] possession of"]', '["n-f"]', 'something seized, i.e. a possession (especially of land) possession.', 'feminine passive participle from 270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6285}/[H6311]', 'inflected', 'heb', 'פֵּאָה', '["pêʼâh"]', '["and/ from/ [the] side of"]', '["n-f"]', 'properly, mouth in a figurative sense, i.e. direction, region, extremity corner, end, quarter, side.', 'feminine of 6311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2506A}/[H2505]', 'inflected', 'heb', 'חֵלֶק', '["chêleq"]', '["the/ portion of land","the/ portions"]', '["n-m"]', 'properly, smoothness (of the tongue); also an allotment flattery, inheritance, part, × partake, portion.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5387A}/H9020/[H5375]', 'inflected', 'heb', 'נָשִׂיא', '["nâsîyʼ"]', '["princes/ my"]', '["n-m"]', 'properly, an exalted one, i.e. a king or sheik; also a rising mist captain, chief, cloud, governor, prince, ruler, vapour.', 'or נָשִׂא; from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H7626H>/H9028\', 'inflected', 'heb', 'לשבטיהם ס', '["le./shiv.tei./Hem"]', '["to/ tribes/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1646}/H9026/[H1644]', 'inflected', 'heb', 'גְרֻשָׁה', '["gᵉrushâh"]', '["eviction<s>/ your"]', '["n-f"]', '(abstractly) dispossession exaction.', 'feminine passive participle of 1644;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1324}/[H1327]', 'inflected', 'heb', 'בַּת', '["bath"]', '["and/ a bath of"]', '["n-m"]', 'a bath or Hebrew measure (as a means of division) of liquids bath.', 'probably from the same as 1327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1324}/[H1327]', 'inflected', 'heb', 'בַּת', '["bath"]', '["and/ the/ bath"]', '["n-m"]', 'a bath or Hebrew measure (as a means of division) of liquids bath.', 'probably from the same as 1327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8506}/[H8505]', 'lemma', 'heb', 'תֹּכֶן', '["tôken"]', '["measurement"]', '["n-m"]', 'a fixed quantity measure, tale.', 'from 8505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2563C}/[H2560]', 'inflected', 'heb', 'חֹמֶר', '["chômer"]', '["the/ homer"]', '["n-m"]', 'properly, a bubbling up, i.e. of water, a wave; of earth, mire or clay (cement); also a heap; hence, a chomer or dry measure clay, heap, homer, mire, motion.', 'from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1324}/[H1327]', 'inflected', 'heb', 'בַּת', '["bath"]', '["the/ bath","the/ baths"]', '["n-m"]', 'a bath or Hebrew measure (as a means of division) of liquids bath.', 'probably from the same as 1327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8255}/[H8254]', 'inflected', 'heb', 'שֶׁקֶל', '["sheqel"]', '["and/ the/ shekel"]', '["n-m"]', 'probably a weight; used as a commercial standard shekel.', 'from 8254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4488}/[H4487]', 'inflected', 'heb', 'מָנֶה', '["mâneh"]', '["the/ mina"]', '["n-m"]', 'properly, a fixed weight or measured amount, i.e. (techn.) a maneh or mina maneh, pound.', 'from 4487;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2563C}/[H2560]', 'inflected', 'heb', 'חֹמֶר', '["chômer"]', '["from/ [the] homer of"]', '["n-m"]', 'properly, a bubbling up, i.e. of water, a wave; of earth, mire or clay (cement); also a heap; hence, a chomer or dry measure clay, heap, homer, mire, motion.', 'from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8341}/[H8337]', 'inflected', 'heb', 'שָׁשָׁה', '["shâshâh"]', '["and/ you will give a sixth part of"]', '["v"]', 'to sixth or divide into sixths give the sixth participle', 'a denominative from 8337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3734A}/[H3564]', 'inflected', 'heb', 'כֹּר', '["kôr"]', '["the/ cor"]', '["n-m"]', 'properly, a deep round vessel, i.e. (specifically) a cor or measure for things dry cor, measure. Aramaic the same.', 'from the same as 3564;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4945B}/[H8248]', 'inflected', 'heb', 'מַשְׁקֶה', '["mashqeh"]', '["from/ [the] well-watered land of"]', '["n-m"]', 'properly, causing to drink, i.e. a butler; by implication (intransitively), drink (itself); figuratively, a well-watered region butler(-ship), cupbearer, drink(-ing), fat pasture, watered.', 'from 8248;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5262}/[H5258]', 'inflected', 'heb', 'נֶסֶךְ', '["neçek"]', '["and/ the/ drink offering"]', '["n-m"]', 'a libation; also a cast idol cover, drink offering, molten image.', 'or נֵסֶךְ; from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7676}/[H7673]', 'inflected', 'heb', 'שַׁבָּת', '["shabbâth"]', '["and/ on the/ sabbaths"]', '["n"]', 'intermission, i.e (specifically) the Sabbath ( every) sabbath.', 'intensive from 7673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6612A}/[H6601]', 'inflected', 'heb', 'פְּתִי', '["pᵉthîy"]', '["and/ from/ a simple person"]', '["a n-f"]', 'silly (i.e. seducible) foolish, simple(-icity, one).', 'or פֶּתִי; or פְּתָאִי; from 6601;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2403H}/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["and/ a sin offering"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0374}/[H374]', 'inflected', 'heb', 'אֵיפָה', '["ʼêyphâh"]', '["to the/ ephah"]', '["n-f"]', 'an ephah or measure for grain; hence, a measure in general ephah, (divers) measure(-s).', 'or (shortened) אֵפָה ; of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5930A}/[H5927]', 'inflected', 'heb', 'עֹלָה', '["ʻôlâh"]', '["like the/ burnt offering"]', '["n-f"]', 'a step or (collectively, stairs, as ascending); usually a holocaust (as going up in smoke) ascent, burnt offering (sacrifice), go up to. See also 5766.', 'or עוֹלָה; feminine active participle of 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/<H4503G>', 'inflected', 'heb', 'וכמנחה', '["ve./kha./min.Chah"]', '["and/ like the/ grain offering"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H8081}\/[H8080]', 'inflected', 'heb', 'שֶׁמֶן', '["shemen"]', '["and/ like the/ oil"]', '["n-m"]', 'grease, especially liquid (as from the olive, often perfumed); figuratively, richness anointing, × fat (things), × fruitful, oil(-ed), ointment, olive, pine.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1870J}/H9023/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["and/ by/ way/ its"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4150H}/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["at the/ appointed times"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4150H}/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["and/ at the/ appointed times"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0374}\/[H374]', 'inflected', 'heb', 'אֵיפָה', '["ʼêyphâh"]', '["to the/ ephah"]', '["n-f"]', 'an ephah or measure for grain; hence, a measure in general ephah, (divers) measure(-s).', 'or (shortened) אֵפָה ; of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7450}/[H7447]', 'inflected', 'heb', 'רָסַס', '["râçaç"]', '["to/ moisten"]', '["v"]', 'to moisten (with drops) temper.', 'a primitive root; to comminute; used only as denominative from 7447,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5159}/H9023/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["from/ inheritance/ his"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1865>', 'inflected', 'heb', 'הדרור', '["ha./de.Ror"]', '["<the>/ liberty"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3238}/H9038/[H3238]', 'inflected', 'heb', 'יָנָה', '["yânâh"]', '["to/ oppress/ them"]', '["v"]', 'to rage or be violent; by implication, to suppress, to maltreat destroy, (thrust out by) oppress(-ing, -ion, -or), proud, vex, do violence.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0272}/H9028/[H270]', 'inflected', 'heb', 'אֲחֻזָּה', '["ʼăchuzzâh"]', '["from/ possession/ their"]', '["n-f"]', 'something seized, i.e. a possession (especially of land) possession.', 'feminine passive participle from 270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3220H>/H9011\', 'opaque', 'heb', 'יָם', '["yâm"]', '["west/ -ward"]', '["n-m"]', 'a sea (as breaking in noisy surf) or large body of water; specifically (with the article), the Mediterranean Sea; sometimes a large river, or an artifical basin; locally, the west, or (rarely) the south sea (× -faring man, (-shore)), south, west (-ern, side, -ward).', 'from an unused root meaning to roar;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6942K}/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["to/ make holy"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4740H}/[H7106]', 'lemma', 'heb', 'מַקְצוֹעַ', '["maqtsôwaʻ"]', '["[the] corners of"]', '["n-m"]', 'an angle or recess corner, turning.', 'or מַקְצֹעַ; or (feminine) מַקְצֹעָה; from 7106 in the denominative sense of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4740H}/[H7106]', 'inflected', 'heb', 'מַקְצוֹעַ', '["maqtsôwaʻ"]', '["[was] in/ [the] corner of"]', '["n-m"]', 'an angle or recess corner, turning.', 'or מַקְצֹעַ; or (feminine) מַקְצֹעָה; from 7106 in the denominative sense of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7000}/[H7000]', 'lemma', 'heb', 'קָטַר', '["qâṭar"]', '["enclosed"]', '["v"]', 'to inclose join.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7106B}/[H7106]', 'lemma', 'heb', 'קָצַע', '["qâtsaʻ"]', '["set in corners"]', '["v"]', 'to strip off, i.e. (partially) scrape; by implication, to segregate (as an angle) cause to scrape, corner.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4018}/[H1310]', 'inflected', 'heb', 'מְבַשְּׁלָה', '["mᵉbashshᵉlâh"]', '["and/ boiling places"]', '["n-f"]', 'a cooking hearth boiling-place.', 'from 1310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2918}/[H2905]', 'inflected', 'heb', 'טִירָה', '["ṭîyrâh"]', '["the/ rows of stones"]', '["n-f"]', 'a wall; hence, a fortress or a hamlet (goodly) castle, habitation, palace, row.', 'feminine of (an equivalent to) 2905;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1310}/[H1310]', 'inflected', 'heb', 'בָּשַׁל', '["bâshal"]', '["those/ [who] boil"]', '["v"]', 'properly, to boil up; hence, to be done in cooking; figuratively to ripen bake, boil, bring forth, roast, seethe, sod (be sodden).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5437H}/H9030/[H5437]', 'inflected', 'heb', 'סָבַב', '["çâbab"]', '["and/ he brought round/ me"]', '["v"]', 'to revolve, surround, or border; used in various applications, literally and figuratively bring, cast, fetch, lead, make, walk, × whirl, × round about, be about on every side, apply, avoid, beset (about), besiege, bring again, carry (about), change, cause to come about, × circuit, (fetch a) compass (about, round), drive, environ, × on every side, beset (close, come, compass, go, stand) round about, inclose, remove, return, set, sit down, turn (self) (about, aside, away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6379}/[H6379]', 'lemma', 'heb', 'פָּכָה', '["pâkâh"]', '["[were] trickling"]', '["v"]', 'to pour run out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0657B}/[H656]', 'lemma', 'heb', 'אֶפֶס', '["ʼepheç"]', '["ankles"]', '["n-m"]', 'cessation, i.e. an end (especially of the earth); often used adverb, no further; also the ankle (in the dual), as being the extremity of the leg or foot ankle, but (only), end, howbeit, less than nothing, nevertheless (where), no, none (beside), not (any, -withstanding), thing of nought, save(-ing), there, uttermost part, want, without (cause).', 'from 656; (sometimes like 6466)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7813}/[H7811]', 'lemma', 'heb', 'שָׂחוּ', '["sâchûw"]', '["swimming"]', '["n-m"]', 'a pond (for swimming) to swim in.', 'from 7811;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1552}/[H1550]', 'inflected', 'heb', 'גְלִילָה', '["gᵉlîylâh"]', '["the/ territory"]', '["n-f"]', 'a circuit or region border, coast, country.', 'feminine of 1550;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6930}/[H6923]', 'inflected', 'heb', 'קַדְמוֹן', '["qadmôwn"]', '["<the>/ eastern"]', '["a"]', 'eastern east.', 'from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1728}/[H1709]', 'lemma', 'heb', 'דַּוָּג', '["davvâg"]', '["fishermen"]', '["n-m"]', 'a fisherman fisher.', 'an orthographical variation of 1709 as a denominative (1771);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5872}/[H5869]', 'inflected', 'heb', 'עֵין גֶּדִי', '["ʻÊyn Gedîy"]', '["from/ En"]', '["n-pr-loc"]', 'En-Gedi, a place in Palestine En-gedi.', 'from 5869 and 1423; fountain of a kid;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5882}/[H5695]', 'lemma', 'heb', 'עֵין עֶגְלַיִם', '["ʻÊyn ʻEglayim"]', '["En-","eglaim"]', '["n-pr-loc"]', 'En-Eglajim, a place in Palestine En-eglaim.', 'עַיִן and the dual of 5695; fountain of two calves;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4894B}/[H7849]', 'lemma', 'heb', 'מִשְׁטוֹחַ', '["mishṭôwach"]', '["a spreading place"]', '["n-m"]', 'a spreading-place (to) spread (forth, -ing, upon).', 'or מִשְׁטַח; from 7849;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2764B}/[H2763]', 'inflected', 'heb', 'חֵרֶם', '["chêrem"]', '["for/ nets"]', '["n-m"]', 'physical (as shutting in) a net (either literally or figuratively); usually a doomed object; abstractly extermination (ac-) curse(-d, -d thing), dedicated thing, things which should have been utterly destroyed, (appointed to) utter destruction, devoted (thing), net.', 'or (Zechariah 14:11) חֶרֶם; from 2763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1710}/[H1709]', 'inflected', 'heb', 'דָּגָה', '["dâgâh"]', '["like/ [the] fish of"]', '["n-f"]', 'fish.', 'feminine of 1709, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1207}/H9023/[H1206]', 'inflected', 'heb', 'בִּצָּה', '["bitstsâh"]', '["swamps/ its"]', '["n-f"]', 'a swamp fen, mire(-ry place).', 'intensive from 1206;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1360>/H9023', 'inflected', 'heb', 'וגבאיו', '["u./ge.va.''A/v"]', '["and/ marshes/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4417M}/[H4414]', 'inflected', 'heb', 'מֶלַח', '["melach"]', '["to/ salt"]', '["n-m"]', 'properly, powder, i.e. (specifically) salt (as easily pulverized and dissolved) salt(-pit).', 'from 4414;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8193J}/H9023/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["bank/ its"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2320G}/H9023/[H2318]', 'inflected', 'heb', 'חֹדֶשׁ', '["chôdesh"]', '["to/ months/ its"]', '["n-m"]', 'the new moon; by implication, a month month(-ly), new moon.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8644}\/[H7322]', 'inflected', 'heb', 'תְּרוּפָה', '["tᵉrûwphâh"]', '["[will be] for/ healing"]', '["n-f"]', 'a remedy medicine.', 'from 7322 in the sense of its congener 7495;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1454}/[H2088]', 'lemma', 'heb', 'גֵּה', '["gêh"]', '["this"]', '["d"]', 'this this.', 'probably a clerical error for 2088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2855}/[H2853]', 'lemma', 'heb', 'חֶתְלֹן', '["Chethlôn"]', '["Hethlon"]', '["n-pr-loc"]', 'Chethlon, a place in Palestine Hethlon.', 'from 2853; enswathed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935O}/[H935]', 'lemma', 'heb', 'בּוֹא', '["bôwʼ"]', '["Lebo"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1268A}/[H1266]', 'lemma', 'heb', 'בֵּרוֹתָה', '["Bêrôwthâh"]', '["Berothah"]', '["n-pr-loc"]', 'Berothah or Berothai, a place north of Palestine Berothah, Berothai.', 'or בֵּרֹתַי; probably from 1266; cypress or cypresslike;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5453}/[H5452]', 'lemma', 'heb', 'סִבְרַיִם', '["Çibrayim"]', '["Sibraim"]', '["n-pr-loc"]', 'Sibrajim, a place in Syria Sibraim.', 'dual from a root corresponding to 5452; double hope;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2694}/[H2691]', 'lemma', 'heb', 'חֲצַר הַתִּיכוֹן', '["Chătsar hat-Tîykôwn"]', '["Hazer-","hattikon"]', '["n-pr-loc"]', 'Chatsar-hat-Tikon, a place in Palestine Hazar-hatticon.', 'from 2691 and 8484 with the article interposed; village of the middle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2362}/[H2357]', 'lemma', 'heb', 'חַוְרָן', '["Chavrân"]', '["Hauran"]', '["n-pr-loc"]', 'Chavran, a region East of the Jordan Hauran.', 'apparently from 2357 (in the sense of 2352); cavernous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2703}/[H2691]', 'lemma', 'heb', 'חֲצַר עֵינוֹן', '["Chătsar ʻÊynôwn"]', '["Enan","Hazar"]', '["n-pr-loc"]', 'Chatsar-Enon, a place in Palestine Hazar-enon.', 'from 2691 and a derivative of 5869; village of springs;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6828G}/[H6845]', 'inflected', 'heb', 'צָפוֹן', '["tsâphôwn"]', '["and/ north"]', '["n-f"]', 'properly, hidden, i.e. dark; used only of the north as a quarter (gloomy and unknown) north(-ern, side, -ward, wind).', 'or צָפֹן; from 6845;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8559J}/[H8558]', 'lemma', 'heb', 'תָּמָר', '["Tâmâr"]', '["<to> Tamar"]', '["n-pr"]', 'Tamar, the name of three women and a place Tamar.', 'the same as 8558;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8559J}/[H8558]', 'inflected', 'heb', 'תָּמָר', '["Tâmâr"]', '["[will be] from/ Tamar","from/ Tamar"]', '["n-pr"]', 'Tamar, the name of three women and a place Tamar.', 'the same as 8558;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5158M}/H9011/[H5157]', 'inflected', 'heb', 'נַחַל', '["nachal"]', '["[the] wadi/ <towards>"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/H9009/{H1616}/[H1481]', 'inflected', 'heb', 'גֵּר', '["gêr"]', '["and/ for/ the/ sojourners"]', '["n-m"]', 'properly, a guest; by implication, a foreigner alien, sojourner, stranger.', 'or (fully) geyr (gare); from 1481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6921}/H9011/[H6923]', 'inflected', 'heb', 'קָדִים', '["qâdîym"]', '["and/ east/ -ward"]', '["n-m"]', 'the fore or front part; hence (by orientation) the East (often adverbially, eastward, for brevity the east wind) east(-ward, wind).', 'or קָדִם; from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3881}\/[H3878]', 'inflected', 'heb', 'לֵוִיִּי', '["Lêvîyîy"]', '["the/ Levites"]', '["a"]', 'a Levite or descendant of Levi Leviite.', 'or לֵוִי; patronymically from 3878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8642}/[H8641]', 'lemma', 'heb', 'תְּרוּמִיָּה', '["tᵉrûwmîyâh"]', '["a contribution"]', '["n-f"]', 'a sacrificial offering oblation.', 'formed as 8641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8641}/[H7311]', 'inflected', 'heb', 'תְּרוּמָה', '["tᵉrûwmâh"]', '["from/ [the] contribution of"]', '["n-f"]', 'a present (as offered up), especially in sacrifice or as tribute gift, heave offering (shoulder), oblation, offered(-ing).', 'or תְּרֻמָה; (Deuteronomy 12:11), from 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4054}/[H1644]', 'inflected', 'heb', 'מִגְרָשׁ', '["migrâsh"]', '["and/ for/ open land"]', '["n-m"]', 'a suburb (i.e. open country whither flocks are driven from pasture); hence, the area around a building, or the margin of the sea cast out, suburb.', 'also (in plural) feminine (Ezekiel 27:28) מִגְרָשָׁה; from 1644;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4060A}/H9024/[H4055]', 'inflected', 'heb', 'מִדָּה', '["middâh"]', '["[will be] measurements/ its"]', '["n-f"]', 'properly, extension, i.e. height or breadth; also a measure (including its standard); hence a portion (as measured) or a vestment; specifically, tribute (as measured) garment, measure(-ing, meteyard, piece, size, (great) stature, tribute, wide.', 'feminine of 4055;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5647I}/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["and/ the/ worker"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5647I}/H9033/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["they will serve/ it"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0272}/[H270]', 'inflected', 'heb', 'אֲחֻזָּה', '["ʼăchuzzâh"]', '["and/ from/ [the] possession of"]', '["n-f"]', 'something seized, i.e. a possession (especially of land) possession.', 'feminine passive participle from 270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5158M}/[H5157]', 'lemma', 'heb', 'נַחַל', '["nachal"]', '["[the] wadi"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3068H}/[H1961]', 'lemma', 'heb', 'יְהֹוָה', '["Yᵉhôvâh"]', '["[will be] Yahweh"]', '["n-pr"]', '(the) self-Existent or Eternal; Jeho-vah, Jewish national name of God Jehovah, the Lord. Compare 3050, 3069.', 'from 1961;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8033H}/H9011/[H834]', 'inflected', 'heb', 'שָׁם', '["shâm"]', '["[Is] There/ <towards>"]', '["adv"]', 'there (transferring to time) then; often thither, or thence in it, thence, there (-in, of, out), thither, whither.', 'a primitive particle (rather from the relative pronoun, 834);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0828>', 'inflected', 'heb', 'לאשפנז', '["le./''ash.pe.Naz"]', '["to/ Ashpenaz"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H2233H}/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["and/ some of/ [the] offspring of"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3971A>', 'opaque', 'heb', 'מאוּם', '["mʼûwm"]', '["blemish"]', '["n-m"]', 'a blemish (physically or morally) blemish, blot, spot.', 'usually מוּם; as if passive participle from an unused root probably meaning to stain');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4093}/[H3045]', 'lemma', 'heb', 'מַדָּע', '["maddâʻ"]', '["<of> knowledge","knowledge"]', '["n-m"]', 'intelligence or consciousness knowledge, science, thought.', 'or מַדַּע; from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3925G}/H9038/[H3925]', 'inflected', 'heb', 'לָמַד', '["lâmad"]', '["and/ to/ teach/ them"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3956H}/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["and/ [the] tongue of"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6598}/[H6598]', 'inflected', 'heb', 'פַּתְבַּג', '["pathbag"]', '["some of/ [the] deli-"]', '["n-m"]', 'a dainty portion (provision) of meat.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6598}/[H6598]', 'lemma', 'heb', 'פַּתְבַּג', '["pathbag"]', '["-caci[es] of","<of> deli-","[the] delicaci[es] of"]', '["n-m"]', 'a dainty portion (provision) of meat.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H3196>', 'inflected', 'heb', 'ומיין', '["u./mi./Yein"]', '["and/ some of/ [the] wine of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4960}/H9023/[H8354]', 'inflected', 'heb', 'מִשְׁתֶּה', '["mishteh"]', '["drink/ his"]', '["n-m"]', 'drink, by implication, drinking (the act); also (by implication) a banquet or (generally) feast banquet, drank, drink, feast((-ed), -ing).', 'from 8354;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1431}/H9038/[H1434]', 'inflected', 'heb', 'גָּדַל', '["gâdal"]', '["and/ to/ bring up/ them"]', '["v"]', 'to be (causatively make) large (in various senses, as in body, mind, estate or honor, also in pride) advance, boast, bring up, exceed, excellent, be(-come, do, give, make, wax), great(-er, come to... estate, things), grow(up), increase, lift up, magnify(-ifical), be much set by, nourish (up), pass, promote, proudly (spoken), tower.', 'a primitive root; properly, to twist (compare 1434), i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H7117}/H9028/[H7096]', 'inflected', 'heb', 'קְצָת', '["qᵉtsâth"]', '["and/ from/ [the] end/ their"]', '["n-f"]', 'a termination (literally or figuratively); also (by implication) a portion; adverbially (with prepositional prefix) after end, part, × some.', 'from 7096;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1840G}/[H1835]', 'lemma', 'heb', 'דָנִיֵּאל', '["Dânîyêʼl"]', '["Daniel","O Daniel"]', '["n-pr-m"]', 'Daniel or Danijel, the name of two Israelites Daniel.', 'in Ezekiel it is; דָּנִאֵל; from 1835 and 410; judge of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2608T}/[H2603]', 'lemma', 'heb', 'חֲנַנְיָה', '["Chănanyâh"]', '["Hananiah"]', '["n-pr-m"]', 'Chananjah, the name of thirteen Israelites Hananiah.', 'or חֲנַנְיָהוּ; from 2603 and 3050; Jah has favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4332I}/[H4310]', 'lemma', 'heb', 'מִישָׁאֵל', '["Mîyshâʼêl"]', '["Mishael"]', '["n-pr-m"]', 'Mishael, the name of three Israelites Mishael.', 'from 4310 and 410 with the abbreviated form insep. relatively (see 834) interposed; who (is) what God (is) ?;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5838Z}/[H5826]', 'inflected', 'heb', 'עֲזַרְיָה', '["ʻĂzaryâh"]', '["and/ Azariah"]', '["n-pr-m"]', 'Azarjah, the name of nineteen Israelites Azariah.', 'or עֲזַרְיָהוּ; from 5826 and 3050; Jah has helped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1840G}/[H1835]', 'inflected', 'heb', 'דָנִיֵּאל', '["Dânîyêʼl"]', '["to/ Daniel"]', '["n-pr-m"]', 'Daniel or Danijel, the name of two Israelites Daniel.', 'in Ezekiel it is; דָּנִאֵל; from 1835 and 410; judge of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1095}/[H1095]', 'lemma', 'heb', 'בֵּלְטְשַׁאצַּר', '["Bêlṭᵉshaʼtstsar"]', '["Belteshazzar"]', '["n-pr-m"]', 'Belteshatstsar, the Babylonian name of Daniel Belteshazzar.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2608T}/[H2603]', 'inflected', 'heb', 'חֲנַנְיָה', '["Chănanyâh"]', '["and/ to/ Hananiah"]', '["n-pr-m"]', 'Chananjah, the name of thirteen Israelites Hananiah.', 'or חֲנַנְיָהוּ; from 2603 and 3050; Jah has favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7714>', 'opaque', 'heb', 'שַׁדְרַךְ', '["Shadrak"]', '["Shadrach"]', '["n-pr-m"]', 'Shadrak, the Babylonian name of one of Daniel''s companions Shadrach.', 'probably of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4332I}/[H4310]', 'inflected', 'heb', 'מִישָׁאֵל', '["Mîyshâʼêl"]', '["and/ to/ Mishael"]', '["n-pr-m"]', 'Mishael, the name of three Israelites Mishael.', 'from 4310 and 410 with the abbreviated form insep. relatively (see 834) interposed; who (is) what God (is) ?;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4335}/[H4336]', 'lemma', 'heb', 'מֵישַׁךְ', '["Mêyshak"]', '["Meshach"]', '["n-pr-m"]', 'Meshak, an Israelite Meshak.', 'borrowed from 4336;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5838Z}/[H5826]', 'inflected', 'heb', 'עֲזַרְיָה', '["ʻĂzaryâh"]', '["and/ to/ Azariah"]', '["n-pr-m"]', 'Azarjah, the name of nineteen Israelites Azariah.', 'or עֲזַרְיָהוּ; from 5826 and 3050; Jah has helped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5664}/[H5665]', 'lemma', 'heb', 'עֲבֵד נְגוֹ', '["ʻĂbêd Nᵉgôw"]', '["-nego","Abed-"]', '["n-pr-m"]', 'Abed-Nego, the Babylonian name of one of Daniel''s companions Abed-nego.', 'the same as 5665;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6598}/[H6598]', 'inflected', 'heb', 'פַּתְבַּג', '["pathbag"]', '["with/ [the] delicaci[es] of"]', '["n-m"]', 'a dainty portion (provision) of meat.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7356B}/[H7355]', 'inflected', 'heb', 'רַחַם', '["racham"]', '["and/ <to>/ compassion<s>"]', '["n-f"]', 'compassion (in the plural); by extension, the womb (as cherishing the fetus); by implication, a maiden bowels, compassion, damsel, tender love, (great, tender) mercy, pity, womb.', 'from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3978}/H9026/[H398]', 'inflected', 'heb', 'מַאֲכָל', '["maʼăkâl"]', '["food/ your"]', '["n-m"]', 'an eatable (includ. provender, flesh and fruit) food, fruit, (bake-)meat(-s), victual.', 'from 398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4960}/H9026/[H8354]', 'inflected', 'heb', 'מִשְׁתֶּה', '["mishteh"]', '["drink/ your"]', '["n-m"]', 'drink, by implication, drinking (the act); also (by implication) a banquet or (generally) feast banquet, drank, drink, feast((-ed), -ing).', 'from 8354;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440L}/H9026/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["faces/ your"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1524B}/H9026/[H1523]', 'inflected', 'heb', 'גִּיל', '["gîyl"]', '["[are] about/ age/ your"]', '["n-m"]', 'a revolution (of time, i.e. an age); also joy × exceedingly, gladness, × greatly, joy, rejoice(-ing), sort.', 'from 1523;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2325}/[H2325]', 'inflected', 'heb', 'חוּב', '["chûwb"]', '["and/ you will endanger"]', '["v"]', 'properly, perhaps to tie, i.e. (figuratively and reflexively) to owe, or (by implication) to forfeit make endanger.', 'also חָיַב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4453}/[H4453]', 'inflected', 'heb', 'מֶלְצָר', '["meltsâr"]', '["the/ guardian"]', '["n-m"]', 'the butler or other officer in the Babylonian court Melzar.', 'of Persian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2235A}/[H2232]', 'inflected', 'heb', 'זֵרֹעַ', '["zêrôaʻ"]', '["the/ vegetables"]', '["n-m"]', 'something sown (only in the plural), i.e. a vegetable (as food) pulse.', 'or זֵרָעֹן; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4758}/H9025/[H7200]', 'inflected', 'heb', 'מַרְאֶה', '["marʼeh"]', '["appearance/ our"]', '["n-m"]', 'a view (the act of seeing); also an appearance (the thing seen), whether (real) a shape (especially if handsome, comeliness; often plural the looks), or (mental) a vision × apparently, appearance(-reth), × as soon as beautiful(-ly), countenance, fair, favoured, form, goodly, to look (up) on (to), look(-eth), pattern, to see, seem, sight, visage, vision.', 'from 7200a;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5254G}/H9038/[H5254]', 'inflected', 'heb', 'נָסָה', '["nâçâh"]', '["and/ he put to [the] test/ them"]', '["v"]', 'to test; by implication, to attempt adventure, assay, prove, tempt, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6598}/H9028/[H6598]', 'inflected', 'heb', 'פַּתְבַּג', '["pathbag"]', '["delicaci[es]/ their"]', '["n-m"]', 'a dainty portion (provision) of meat.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2235B}/[H2232]', 'lemma', 'heb', 'זֵרֹעַ', '["zêrôaʻ"]', '["vegetables"]', '["n-m"]', 'something sown (only in the plural), i.e. a vegetable (as food) pulse.', 'or זֵרָעֹן; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0702}/H9028/[H7251]', 'inflected', 'heb', 'אַרְבַּע', '["ʼarbaʻ"]', '["[the] four of/ them"]', '["n"]', 'four four.', 'masculine אַרְבָּעָה; from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1840G}/[H1835]', 'inflected', 'heb', 'דָנִיֵּאל', '["Dânîyêʼl"]', '["and/ Daniel"]', '["n-pr-m"]', 'Daniel or Danijel, the name of two Israelites Daniel.', 'in Ezekiel it is; דָּנִאֵל; from 1835 and 410; judge of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2472}/[H2492]', 'inflected', 'heb', 'חֲלוֹם', '["chălôwm"]', '["and/ [the] dreams of","and/ dreams"]', '["n-m"]', 'a dream dream(-er).', 'or (shortened) חֲלֹם; from 2492;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/H9006/{H7117}/[H7096]', 'inflected', 'heb', 'קְצָת', '["qᵉtsâth"]', '["and/ <to>/ from/ [the] end of"]', '["n-f"]', 'a termination (literally or figuratively); also (by implication) a portion; adverbially (with prepositional prefix) after end, part, × some.', 'from 7096;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3605}/H9028/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["any of/ all of/ them"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1840G}/[H1835]', 'inflected', 'heb', 'דָנִיֵּאל', '["Dânîyêʼl"]', '["like/ Daniel"]', '["n-pr-m"]', 'Daniel or Danijel, the name of two Israelites Daniel.', 'in Ezekiel it is; דָּנִאֵל; from 1835 and 410; judge of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0825>', 'inflected', 'heb', 'האשפים', '["ha./''a.sha.Fim"]', '["the/ conjurers"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8142}/H9023/[H3462]', 'inflected', 'heb', 'שֵׁנָה', '["shênâh"]', '["and/ sleep/ his"]', '["n-f"]', 'sleep sleep.', 'or שֵׁנָא; (Psalm 127:2), from 3462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2748}/[H2747]', 'inflected', 'heb', 'חַרְטֹם', '["charṭôm"]', '["<to> the/ soothsayer-priests"]', '["n-m"]', 'a horoscopist (as drawing magical lines or circles) magician.', 'from the same as 2747;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H0825>', 'inflected', 'heb', 'ולאשפים', '["ve./la./''a.sha.Fim"]', '["and/ <to> the/ conjurers"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3778}/[H3777]', 'inflected', 'heb', 'כַּשְׂדִּי', '["Kasdîy"]', '["and/ <to> the/ Chaldeans"]', '["n-pr-loc n-pr-m"]', 'a Kasdite, or descendant of Kesed; by implication, a Chaldaean (as if so descended); also an astrologer (as if proverbial of that people Chaldeans, Chaldees, inhabitants of Chaldea.', '(occasionally with enclitic) כַּשְׂדִּימָה; towards the Kasdites into Chaldea), patronymically from 3777 (only in the plural);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5957}/[H5769]', 'inflected', 'arc', 'עָלַם', '["ʻâlam"]', '["for/ ever"]', '["n-m"]', 'remote time, i.e. the future or past indefinitely; often adverb, forever for (n-)ever (lasting), old.', '(Aramaic) corresponding to 5769;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2418}/[H2421]', 'lemma', 'arc', 'חֲיָא', '["chăyâʼ"]', '["letting live","live!"]', '["v"]', 'to live live, keep alive.', '(Aramaic) or חֲיָה; (Aramaic), corresponding to 2421;');
