INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4481}/H9034/[H4480]', 'inflected', 'arc', 'מִן', '["min"]', '["from/ it"]', '["prep"]', 'according, after, because, before, by, for, from, × him, × more than, (out) of, part, since, × these, to, upon, when.', '(Aramaic) corresponding to 4480');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0311}/H9038/[H310]', 'inflected', 'arc', 'אַחַר', '["ʼachar"]', '["after/ them"]', '["adv"]', 'after (here-) after.', '(Aramaic) corresponding to 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6655}/[H6654]', 'inflected', 'arc', 'צַד', '["tsad"]', '["to/ [the] side of"]', '["n-m"]', 'used adverbially (with preposition) at or upon the side of against, concerning.', '(Aramaic) corresponding to 6654;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6922}/[H6918]', 'inflected', 'arc', 'קַדִּישׁ', '["qaddîysh"]', '["and/ <obj.>/ [the] holy [ones] of"]', '["a"]', 'holy (One), saint.', '(Aramaic) corresponding to 6918.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1080}/[H1086]', 'lemma', 'arc', 'בְּלָא', '["bᵉlâʼ"]', '["he will wear out"]', '["v"]', 'to afflict wear out.', '(Aramaic) corresponding to 1086 (but used only in a mental sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5452}/[H5452]', 'inflected', 'arc', 'סְבַר', '["çᵉbar"]', '["so/ he may think"]', '["v"]', 'to bear in mind, i.e. hope think.', '(Aramaic) a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1882}/[H1881]', 'inflected', 'arc', 'דָּת', '["dâth"]', '["and/ law"]', '["n-f"]', 'decree, law.', '(Aramaic) corresponding to 1881;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6387}/[H6386]', 'inflected', 'arc', 'פְּלַג', '["pᵉlag"]', '["and/ half of"]', '["n-m"]', 'a half dividing.', '(Aramaic) from 6386;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8046}/[H8045]', 'inflected', 'arc', 'שְׁמַד', '["shᵉmad"]', '["to/ annihilate"]', '["v"]', 'consume.', '(Aramaic) corresponding to 8045');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0007}/[H6]', 'inflected', 'arc', 'אֲבַד', '["ʼăbad"]', '["and/ to/ destroy"]', '["v"]', 'destroy, perish.', '(Aramaic) corresponding to 6');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7985}/H9010/[H7981]', 'inflected', 'arc', 'שׇׁלְטָן', '["sholṭân"]', '["and/ dominion/ the"]', '["n-m"]', 'empire (abstractly or concretely) dominion.', '(Aramaic) from 7981;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7985}/H9010/[H7981]', 'inflected', 'arc', 'שׇׁלְטָן', '["sholṭân"]', '["empires/ the"]', '["n-m"]', 'empire (abstractly or concretely) dominion.', '(Aramaic) from 7981;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3542}/[H3541]', 'lemma', 'arc', 'כָּה', '["kâh"]', '["here"]', '["adv"]', 'hitherto.', '(Aramaic) corresponding to 3541');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7476}/H9020/[H7475]', 'inflected', 'arc', 'רַעְיוֹן', '["raʻyôwn"]', '["thoughts/ my"]', '["n-m"]', 'a grasp. i.e. (figuratively) mental conception cogitation, thought.', '(Aramaic) corresponding to 7475;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3821}/H9020/[H3820]', 'inflected', 'arc', 'לֵב', '["lêb"]', '["in/ heart/ my"]', '["n-m"]', 'heart.', '(Aramaic) corresponding to 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5202}\/[H5201]', 'inflected', 'arc', 'נְטַר', '["nᵉṭar"]', '["I have kept"]', '["v"]', 'to retain keep.', '(Aramaic) corresponding to 5201;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1112>', 'opaque', 'heb', 'בֵּלְשַׁאצַּר', '["Bêlshaʼtstsar"]', '["Belshazzar"]', '["n-pr-m"]', 'Belshatstsar, a Babylonian king Belshazzar.', 'or בֵּלְאשַׁצַּרlemma בֵּלְאשַׁצּר missing vowel, corrected to בֵּלְאשַׁצַּר; of foreign origin (compare 1095);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7200G}/H9040/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["when/ saw/ I"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0180}/[H2986]', 'lemma', 'heb', 'אוּבָל', '["ʼûwbâl"]', '["[the] canal of"]', '["n-m"]', 'a stream river.', 'or (shortened) אֻבָל ; from 2986 (in the sense of 2988);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0195}/[H195]', 'lemma', 'heb', 'אוּלַי', '["ʼÛwlay"]', '["Ulai"]', '["n"]', 'the Ulai (or Eulaeus), a river of Persia Ulai.', 'of Persian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0180}/[H2986]', 'inflected', 'heb', 'אוּבָל', '["ʼûwbâl"]', '["the/ canal"]', '["n-m"]', 'a stream river.', 'or (shortened) אֻבָל ; from 2986 (in the sense of 2988);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7161A}/[H7160]', 'inflected', 'heb', 'קֶרֶן', '["qeren"]', '["and/ the/ horn","and/ the/ two horns"]', '["n-f n-pr-loc"]', 'a horn (as projecting); by implication, a flask, cornet; by resemblance. an elephant''s tooth (i.e. ivory), a corner (of the altar), a peak (of a mountain), a ray (of light); figuratively, power × hill, horn.', 'from 7160;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7522}/H9023/[H7521]', 'inflected', 'heb', 'רָצוֹן', '["râtsôwn"]', '["according to/ pleasure/ his","according to/ pleasure/ its"]', '["n-m"]', 'delight (especially as shown) (be) acceptable(-ance, -ed), delight, desire, favour, (good) pleasure, (own, self, voluntary) will, as...(what) would.', 'or רָצֹן; from 7521;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4628}/[H6150]', 'inflected', 'heb', 'מַעֲרָב', '["maʻărâb"]', '["the/ west"]', '["n-m"]', 'the west (as a region of the evening sun) west.', 'or (feminine) מַעֲרָבָה; from 6150, in the sense of shading;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6842}/[H6852]', 'inflected', 'heb', 'צָפִיר', '["tsâphîyr"]', '["and/ the/ he-goat"]', '["n-m"]', 'a male goat (as prancing) (he) goat.', 'from 6852;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H6105A}/H9043/[H6106]', 'inflected', 'heb', 'עָצַם', '["ʻâtsam"]', '["and/ just as/ became mighty/ it"]', '["v"]', 'to bind fast, i.e. close (the eyes); intransitively, to be (causatively, make) powerful or numerous; to crunch the bones break the bones, close, be great, be increased, be (wax) mighty(-ier), be more, shut, be(-come, make) strong(-er).', 'a primitive root; also denominatively (from 6106)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6810}/[H6819]', 'inflected', 'heb', 'צָעִיר', '["tsâʻîyr"]', '["from/ a small [thing]"]', '["a"]', 'little; (in number) few; (in age) young, (in value) ignoble least, little (one), small (one), young(-er, -est).', 'or צָעוֹר; from 6819;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7429}/H9038/[H7429]', 'inflected', 'heb', 'רָמַס', '["râmaç"]', '["and/ it trampled/ them"]', '["v"]', 'to tread upon (as a potter, in walking or abusively) oppressor, stamp upon, trample (under feet), tread (down, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8085G}/H9012/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["and/ I heard/ !"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6422}/[H6423]', 'inflected', 'heb', 'פַּלְמוֹנִי', '["palmôwnîy"]', '["to the/ certain [one]"]', '["pron"]', 'a certain one, i.e. so-and-so certain.', 'probably for 6423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6588}/[H6586]', 'inflected', 'heb', 'פֶּשַׁע', '["peshaʻ"]', '["and/ the/ transgression"]', '["n-m"]', 'a revolt (national, moral or religious) rebellion, sin, transgression, trespass.', 'from 6586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1403}/[H1397]', 'lemma', 'heb', 'גַּבְרִיאֵל', '["Gabrîyʼêl"]', '["Gabriel","O Gabriel"]', '["n-pr-m"]', 'Gabriel, an archangel Gabriel.', 'from 1397 and 410; man of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1975}/[H1976]', 'inflected', 'heb', 'הַלָּז', '["hallâz"]', '["to/ this [one]"]', '["d"]', 'this or that side, that, this.', 'from 1976;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5977}/H9020/[H5975]', 'inflected', 'heb', 'עֹמֶד', '["ʻômed"]', '["standing place/ my"]', '["n-m"]', 'a spot (as being fixed) place, ( where) stood, upright.', 'from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1696G}/H9043/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["and/ when/ spoke/ he"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2195}/[H2194]', 'inflected', 'heb', 'זַעַם', '["zaʻam"]', '["the/ indignation"]', '["n-m"]', 'strictly froth at the mouth, i.e. (figuratively) fury (especially of God''s displeasure with sin) angry, indignation, rage.', 'from 2194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7665}/[H7665]', 'inflected', 'heb', 'שָׁבַר', '["shâbar"]', '["and/ the/ [one which] is maimed","and/ the/ broken [horn]"]', '["v"]', 'to burst (literally or figuratively) break (down, off, in pieces, up), broken (-hearted), bring to the birth, crush, destroy, hurt, quench, × quite, tear, view (by mistake for 7663).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0319}/[H310]', 'inflected', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["and/ at/ [the] end of"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3824}/H9023/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["and/ in/ heart/ his"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7962}/[H7951]', 'inflected', 'heb', 'שַׁלְוָה', '["shalvâh"]', '["and/ in/ prosperity"]', '["n-f"]', 'security (genuine or false) abundance, peace(-ably), prosperity, quietness.', 'from 7951;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1242}/[H1239]', 'inflected', 'heb', 'בֹּקֶר', '["bôqer"]', '["and/ the/ morning"]', '["n-m"]', 'properly, dawn (as the break of day); generally, morning ( ) day, early, morning, morrow.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1867I}/[H1867]', 'inflected', 'heb', 'דָּֽרְיָוֵשׁ', '["Dârᵉyâvêsh"]', '["of/ Darius"]', '["n-pr-m"]', 'Darejavesh, a title (rather than name) of several Persian kings Darius.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8469}/[H2603]', 'inflected', 'heb', 'תַּחֲנוּן', '["tachănûwn"]', '["and/ supplications"]', '["n-m"]', 'earnest prayer intreaty, supplication.', 'or (feminine) תַּחֲנוּנָה; from 2603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6419}/H9012/[H6419]', 'inflected', 'heb', 'פָּלַל', '["pâlal"]', '["and/ I prayed/ !"]', '["v"]', 'to judge (officially or mentally); by extension, to intercede, pray intreat, judge(-ment), (make) pray(-er, -ing), make supplication.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4775}/[H4775]', 'inflected', 'heb', 'מָרַד', '["mârad"]', '["and/ we have rebelled"]', '["v"]', 'to rebel rebel(-lious).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6440L}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["the/ faces"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5547}/[H5545]', 'inflected', 'heb', 'סְלִיחָה', '["çᵉlîychâh"]', '["and/ <the>/ forgiveness<es>"]', '["n-f"]', 'pardon forgiveness, pardon.', 'from 5545;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7621}/[H7650]', 'inflected', 'heb', 'שְׁבוּעָה', '["shᵉbûwʻâh"]', '["and/ the/ oath"]', '["n-f"]', 'properly, something sworn, i.e. an oath curse, oath, × sworn.', 'feminine passive participle of 7650;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8245}/[H8245]', 'inflected', 'heb', 'שָׁקַד', '["shâqad"]', '["and/ he kept watch"]', '["v"]', 'to be alert, i.e. sleepless; hence to be on the lookout (whether for good or ill) hasten, remain, wake, watch (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2534}/H9021/[H3179]', 'inflected', 'heb', 'חֵמָה', '["chêmâh"]', '["and/ rage/ your"]', '["n-f"]', 'heat; figuratively, anger, poison (from its fever) anger, bottles, hot displeasure, furious(-ly, -ry), heat, indignation, poison, rage, wrath(-ful). See 2529.', 'or (Daniel 11:44) חֵמָא; from 3179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5892B}/H9021/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["from/ city/ your"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2399}/H9025/[H2398]', 'inflected', 'heb', 'חֵטְא', '["chêṭᵉʼ"]', '["by/ sins/ our"]', '["n-m"]', 'a crime or its penalty fault, × grievously, offence, (punishment of) sin.', 'from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5771G}/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["and/ by/ [the] iniquities of"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8469}/H9023/[H2603]', 'inflected', 'heb', 'תַּחֲנוּן', '["tachănûwn"]', '["supplications/ his"]', '["n-m"]', 'earnest prayer intreaty, supplication.', 'or (feminine) תַּחֲנוּנָה; from 2603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8074G}/H9025/[H8074]', 'inflected', 'heb', 'שָׁמֵם', '["shâmêm"]', '["desolate [things]/ our"]', '["v"]', 'to stun (or intransitively, grow numb), i.e. devastate or (figuratively) stupefy (both usually in a passive sense) make amazed, be astonied, (be an) astonish(-ment), (be, bring into, unto, lay, lie, make) desolate(-ion, places), be destitute, destroy (self), (lay, lie, make) waste, wonder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8469}/H9025/[H2603]', 'inflected', 'heb', 'תַּחֲנוּן', '["tachănûwn"]', '["supplications/ our"]', '["n-m"]', 'earnest prayer intreaty, supplication.', 'or (feminine) תַּחֲנוּנָה; from 2603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5545}/H9012/[H5545]', 'inflected', 'heb', 'סָלַח', '["çâlach"]', '["forgive/ !"]', '["v"]', 'to forgive forgive, pardon, spare.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4616}/H9031/[H6030]', 'inflected', 'heb', 'מַעַן', '["maʻan"]', '["for own sake/ your"]', '["prt"]', 'properly, heed, i.e. purpose; used only adverbially, on account of (as a motive or an aim), teleologically, in order that because of, to the end (intent) that, for (to,... ''s sake), lest, that, to.', 'from 6030;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5307N}/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["and/ [was] making fall"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3288}/[H3286]', 'inflected', 'heb', 'יְעָף', '["yᵉʻâph"]', '["with/ weariness"]', '["n-m"]', 'fatigue (adverb, utterly exhausted) swiftly.', 'from 3286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7919A}/H9031/[H7919]', 'inflected', 'heb', 'שָׂכַל', '["sâkal"]', '["to/ give insight/ you"]', '["v"]', 'to be (causatively, make or act) circumspect and hence, intelligent consider, expert, instruct, prosper, (deal) prudent(-ly), (give) skill(-ful), have good success, teach, (have, make to) understand(-ing), wisdom, (be, behave self, consider, make) wise(-ly), guide wittingly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8469}/H9021/[H2603]', 'inflected', 'heb', 'תַּחֲנוּן', '["tachănûwn"]', '["supplications/ your"]', '["n-m"]', 'earnest prayer intreaty, supplication.', 'or (feminine) תַּחֲנוּנָה; from 2603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2532B}/[H2531]', 'lemma', 'heb', 'חֶמְדָּה', '["chemdâh"]', '["[are] precious","desirableness<es>","preciousness<es>"]', '["n-f"]', 'delight desire, goodly, pleasant, precious.', 'feminine of 2531;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7620I}/[H7650]', 'lemma', 'heb', 'שָׁבוּעַ', '["shâbûwaʻ"]', '["seven","sevens"]', '["n-m"]', 'literally, sevened, i.e. a week (specifically, of years) seven, week.', 'or שָׁבֻעַ; also (feminine) שְׁבֻעָה; properly, passive participle of 7650 as a denominative of 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2852}/[H2852]', 'lemma', 'heb', 'חָתַךְ', '["châthak"]', '["it has been decreed"]', '["v"]', 'properly, to cut off, i.e. (figuratively) to decree determine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6588}/[H6586]', 'inflected', 'heb', 'פֶּשַׁע', '["peshaʻ"]', '["the/ transgression"]', '["n-m"]', 'a revolt (national, moral or religious) rebellion, sin, transgression, trespass.', 'from 6586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8552}/[H8552]', 'inflected', 'heb', 'תָּמַם', '["tâmam"]', '["and/ to/ complete"]', '["v"]', 'to complete, in a good or a bad sense, literal, or figurative, transitive or intransitive accomplish, cease, be clean (pass-) ed, consume, have done, (come to an, have an, make an) end, fail, come to the full, be all gone, × be all here, be (make) perfect, be spent, sum, be (shew self) upright, be wasted, whole.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2856}/[H2856]', 'inflected', 'heb', 'חָתַם', '["châtham"]', '["and/ to/ seal up"]', '["v"]', 'to close up; especially to seal make an end, mark, seal (up), stop.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4886}/[H4886]', 'inflected', 'heb', 'מָשַׁח', '["mâshach"]', '["and/ to/ anoint"]', '["v"]', 'to rub with oil, i.e. to anoint; by implication, to consecrate; also to paint anoint, paint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7620I}/[H7650]', 'inflected', 'heb', 'שָׁבוּעַ', '["shâbûwaʻ"]', '["and/ sevens"]', '["n-m"]', 'literally, sevened, i.e. a week (specifically, of years) seven, week.', 'or שָׁבֻעַ; also (feminine) שְׁבֻעָה; properly, passive participle of 7650 as a denominative of 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2742C}/[H2782]', 'inflected', 'heb', 'חֲרוּץ', '["chărûwts"]', '["and/ a moat"]', '["a"]', 'properly, incised or (active) incisive; hence (as noun masculine or feminine) a trench (as dug), gold (as mined), a threshing-sledge (having sharp teeth); (figuratively) determination; also eager decision, diligent, (fine) gold, pointed things, sharp, threshing instrument, wall.', 'or חָרֻץ; passive participle of 2782;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6695A}/[H6693]', 'inflected', 'heb', 'צוֹק', '["tsôwq"]', '["and/ in/ [the] distress of"]', '["n-m n-f"]', 'a strait, i.e. (figuratively) distress anguish, × troublous.', 'or (feminine) צוּקָה; from 6693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7620I}/[H7650]', 'inflected', 'heb', 'שָׁבוּעַ', '["shâbûwaʻ"]', '["the/ seven","the/ sevens"]', '["n-m"]', 'literally, sevened, i.e. a week (specifically, of years) seven, week.', 'or שָׁבֻעַ; also (feminine) שְׁבֻעָה; properly, passive participle of 7650 as a denominative of 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7093}/H9023/[H7112]', 'inflected', 'heb', 'קֵץ', '["qêts"]', '["and/ end/ his"]', '["n-m"]', 'an extremity; adverbially (with prepositional prefix) after after, (utmost) border, end, (in-) finite, × process.', 'contracted from 7112;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7858}/[H7857]', 'inflected', 'heb', 'שֶׁטֶף', '["sheṭeph"]', '["[will be] by <the>/ flood"]', '["n-m"]', 'a deluge (literally or figuratively) flood, outrageous, overflowing.', 'or שֵׁטֶף; from 7857;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6635H}/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["and/ a war"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5480}/[H5480]', 'inflected', 'heb', 'סוּךְ', '["çûwk"]', '["and/ indeed <anoint>"]', '["v"]', 'properly, to smear over (with oil), i.e. anoint anoint (self), × at all.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4975>/H9023', 'inflected', 'heb', 'ומתניו', '["u./ma.te.Na/v"]', '["and/ loins/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0210}/[H211]', 'lemma', 'heb', 'אוּפָז', '["ʼÛwphâz"]', '["Uphaz"]', '["n-pr-loc"]', 'Uphaz, a famous gold region Uphaz.', 'perhaps a corruption of 211;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1472}/H9023/[H1465]', 'inflected', 'heb', 'גְּוִיָּה', '["gᵉvîyâh"]', '["and/ body/ his"]', '["n-f"]', 'a body, whether alive or dead (dead) body, carcase, corpse.', 'prolonged for 1465;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8658}/[H8659]', 'inflected', 'heb', 'תַּרְשִׁישׁ', '["tarshîysh"]', '["[was] like/ topaz"]', '["n-m"]', 'a gem, perhaps the topaz beryl.', 'probably of foreign derivation (compare 8659);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4772}/H9023/[H7272]', 'inflected', 'heb', 'מַרְגְלָה', '["margᵉlâh"]', '["and/ feet/ his"]', '["n-f"]', '(plural for collective) a footpiece, i.e. (adverbially) at the foot, or (direct.) the foot itself feet. Compare 4763.', 'denominative from 7272;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2244}/[H2245]', 'inflected', 'heb', 'חָבָא', '["châbâʼ"]', '["in/ hiding themselves"]', '["v"]', 'to secrete × held, hide (self), do secretly.', 'a primitive root (compare 2245);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1935>/H9020', 'inflected', 'heb', 'והודי', '["ve./ho.D/i"]', '["and/ vigor/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5128}/H9030/[H5128]', 'inflected', 'heb', 'נוּעַ', '["nûwaʻ"]', '["and/ it shook/ me"]', '["v"]', 'to waver, in a great variety of applications, literally and figuratively (as subjoined) continually, fugitive, × make, to (go) up and down, be gone away, (be) move(-able, -d), be promoted, reel, remove, scatter, set, shake, sift, stagger, to and fro, be vagabond, wag, (make) wander (up and down).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5977}/H9021/[H5975]', 'inflected', 'heb', 'עֹמֶד', '["ʻômed"]', '["standing place/ your"]', '["n-m"]', 'a spot (as being fixed) place, ( where) stood, upright.', 'from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6031B}/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["and/ to/ humble yourself"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4317Q}/[H4310]', 'lemma', 'heb', 'מִיכָאֵל', '["Mîykâʼêl"]', '["Michael"]', '["n-pr-m"]', 'Mikael, the name of an archangel and of nine Israelites Michael.', 'from 4310 and (the prefix derivative from) 3588 and 410; who (is) like God?;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0995}/H9031/[H995]', 'inflected', 'heb', 'בִּין', '["bîyn"]', '["to/ make understand/ you"]', '["v"]', 'to separate mentally (or distinguish), i.e.(generally) understand attend, consider, be cunning, diligently, direct, discern, eloquent, feel, inform, instruct, have intelligence, know, look well to, mark, perceive, be prudent, regard, (can) skill(-full), teach, think, (cause, make to, get, give, have) understand(-ing), view, (deal) wise(-ly, man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1696G}/H9012/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["and/ I spoke/ !"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6735C}/H9020/[H6696]', 'inflected', 'heb', 'צִיר', '["tsîyr"]', '["pangs/ my"]', '["n-m"]', 'a hinge (as pressed in turning); also a throe (as a phys. or mental pressure); also a herald or errand-doer (as constrained by the principal) ambassador, hinge, messenger, pain, pang, sorrow. Compare 6736.', 'from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1963}/[H349]', 'inflected', 'heb', 'הֵיךְ', '["hêyk"]', '["and/ how?"]', '["adv"]', 'how? how.', 'another form for 349;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2388G}/H9030/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["and/ he strengthened/ me"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7559}/[H7559]', 'inflected', 'heb', 'רָשַׁם', '["râsham"]', '["the/ [thing] inscribed"]', '["v"]', 'to record note.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8269}/H9026\/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["prince/ your"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4075}/[H4074]', 'inflected', 'heb', 'מָדַי', '["Mâday"]', '["the/ Mede"]', '["a"]', 'a Madian or native of Madai Mede.', 'patrial from 4074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5975G}/H9020/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["standing/ my"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4581}/[H5810]', 'inflected', 'heb', 'מָעוֹז', '["mâʻôwz"]', '["and/ to/ a protection"]', '["n-m"]', 'a fortified place; figuratively, a defence force, fort(-ress), rock, strength(-en), (× most) strong (hold).', '(also מָעוּז ); or מָעֹז (also מָעֻז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H6539>', 'inflected', 'heb', 'לפרס', '["le./fa.Ras"]', '["for/ Persia"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4474}/[H4910]', 'lemma', 'heb', 'מִמְשָׁל', '["mimshâl"]', '["[will be] a dominion","dominion"]', '["n-m"]', 'a ruler or (abstractly) rule dominion, that ruled.', 'from 4910;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H5975I}/H9043/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["and/ just as/ arises/ he"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2673}/[H2086]', 'inflected', 'heb', 'חָצָה', '["châtsâh"]', '["and/ it will be divided"]', '["v"]', 'to cut or split in two; to halve divide, × live out half, reach to the midst, participle', 'a primitive root (compare 2086));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0319}/H9023/[H310]', 'inflected', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["to/ posterity/ his"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4915B}/H9023/[H4910]', 'inflected', 'heb', 'מֹשֶׁל', '["môshel"]', '["like/ dominion/ his"]', '["n-m"]', 'empire; a parallel dominion, like.', '(1) from 4910; (2) from 4911;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0312}/[H309]', 'inflected', 'heb', 'אַחֵר', '["ʼachêr"]', '["and/ to/ others"]', '["a"]', 'properly, hinder; generally, next, other, etc. (an-) other man, following, next, strange.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0935G}/H9034/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ [those who] brought/ her"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3205}/H9034/[H3205]', 'inflected', 'heb', 'יָלַד', '["yâlad"]', '["and/ the/ [one who] fathered/ her"]', '["v"]', 'to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2388G}/H9034/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["and/ [the one who] strengthened/ her"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5342}/[H5341]', 'inflected', 'heb', 'נֵצֶר', '["nêtser"]', '["one of/ [the] shoot[s] of"]', '["n-m"]', 'a shoot; figuratively, a descendant branch.', 'from 5341 in the sense of greenness as a striking color;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2532A}/H9028/[H2531]', 'inflected', 'heb', 'חֶמְדָּה', '["chemdâh"]', '["desire/ their"]', '["n-f"]', 'delight desire, goodly, pleasant, precious.', 'feminine of 2531;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4843}/[H4752]', 'inflected', 'heb', 'מָרַר', '["mârar"]', '["and/ they will show bitterness","so/ he may be enraged"]', '["v"]', 'to be (causatively, make) bitter (literally or figuratively) (be, be in, deal, have, make) bitter(-ly, -ness), be moved with choler, (be, have sorely, it) grieved(-eth), provoke, vex.', 'a primitive root; properly, to trickle (see 4752); but used only as a denominative from 4751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4005}/H9023/[H977]', 'inflected', 'heb', 'מִבְחָר', '["mibchâr"]', '["choicest ones/ his"]', '["n-m"]', 'select, i.e. best choice(-st), chosen.', 'from 977;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8633}/[H8630]', 'inflected', 'heb', 'תֹּקֶף', '["tôqeph"]', '["with/ [the] power of"]', '["n-m"]', 'might or (figuratively) positiveness authority, power, strength.', 'from 8630;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2781}/H9023/[H2778]', 'inflected', 'heb', 'חֶרְפָּה', '["cherpâh"]', '["scorn/ his"]', '["n-f"]', 'contumely, disgrace, the pudenda rebuke, reproach(-fully), shame.', 'from 2778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4581}/[H5810]', 'inflected', 'heb', 'מָעוֹז', '["mâʻôwz"]', '["to/ [the] strongholds of"]', '["n-m"]', 'a fortified place; figuratively, a defence force, fort(-ress), rock, strength(-en), (× most) strong (hold).', '(also מָעוּז ); or מָעֹז (also מָעֻז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1925}/[H1921]', 'lemma', 'heb', 'הֶדֶר', '["heder"]', '["[the] splendor of"]', '["n-m"]', 'honour; used (figuratively) for the capital city (Jerusalem) glory.', 'from 1921;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7962}/[H7951]', 'inflected', 'heb', 'שַׁלְוָה', '["shalvâh"]', '["in/ quietness"]', '["n-f"]', 'security (genuine or false) abundance, peace(-ably), prosperity, quietness.', 'from 7951;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2519}/[H2505]', 'inflected', 'heb', 'חֲלַקְלַקָּה', '["chălaqlaqqâh"]', '["by/ intrigues"]', '["n-f"]', 'properly, something very smooth; i.e. a treacherous spot; figuratively, blandishment flattery, slippery.', 'by reduplication from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7858}/[H7857]', 'inflected', 'heb', 'שֶׁטֶף', '["sheṭeph"]', '["the/ flood"]', '["n-m"]', 'a deluge (literally or figuratively) flood, outrageous, overflowing.', 'or שֵׁטֶף; from 7857;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4924B}/[H8080]', 'inflected', 'heb', 'מַשְׁמָן', '["mashmân"]', '["and/ in/ [the] fertile places of"]', '["n-m"]', 'fat, i.e. (literally and abstractly) fatness; but usually (figuratively and concretely) a rich dish, a fertile field, a robust man fat (one, -ness, -test, -test place).', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5782}/[H5782]', 'inflected', 'heb', 'עוּר', '["ʻûwr"]', '["and/ he will stir up"]', '["v"]', 'to wake (literally or figuratively) (a-) wake(-n, up), lift up (self), × master, raise (up), stir up (self).', 'a primitive root (rather identical with through the idea of opening the eyes);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6598}/H9023/[H6598]', 'inflected', 'heb', 'פַּתְבַּג', '["pathbag"]', '["-cacies/ his"]', '["n-m"]', 'a dainty portion (provision) of meat.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7665}/H9033/[H7665]', 'inflected', 'heb', 'שָׁבַר', '["shâbar"]', '["they will break/ him"]', '["v"]', 'to burst (literally or figuratively) break (down, off, in pieces, up), broken (-hearted), bring to the birth, crush, destroy, hurt, quench, × quite, tear, view (by mistake for 7663).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4827}/[H7489]', 'inflected', 'heb', 'מֵרַע', '["mêraʻ"]', '["[will be] to/ evil"]', '["n-m"]', 'used as (abstract) noun, wickedness do mischief.', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H5045H>', 'inflected', 'heb', 'בנגב', '["va./Ne.gev"]', '["in the/ south"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0314}/[H309]', 'inflected', 'heb', 'אַחֲרוֹן', '["ʼachărôwn"]', '["and/ as the/ latter [time]"]', '["a"]', 'hinder; generally, late or last; specifically (as facing the east) western after (-ward), to come, following, hind(-er, -ermost, -most), last, latter, rereward, ut(ter) most.', 'or (shortened) אַחֲרֹן; from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6716}/[H6680]', 'lemma', 'heb', 'צִי', '["tsîy"]', '["<the> ships of"]', '["n-m"]', 'a ship (as a fixture) ship.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3512A}/[H3512]', 'inflected', 'heb', 'כָּאָה', '["kâʼâh"]', '["and/ he will be disheartened"]', '["v a"]', 'to despond; causatively, to deject broken, be grieved, make sad.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2514}/[H2505]', 'inflected', 'heb', 'חֲלַקָּה', '["chălaqqâh"]', '["with/ flattering [words]"]', '["n-f"]', 'flattery flattery.', 'feminine from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3852}/[H3851]', 'inflected', 'heb', 'לֶהָבָה', '["lehâbâh"]', '["and/ by/ flame"]', '["n-f"]', 'flame(-ming), head (of a spear).', 'or לַהֶבֶת; feminine of 3851, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3782}/H9048/[H3782]', 'inflected', 'heb', 'כָּשַׁל', '["kâshal"]', '["and/ when/ stumble/ they"]', '["v"]', 'to totter or waver (through weakness of the legs, especially the ankle); by implication, to falter, stumble, faint or fall bereave (from the margin), cast down, be decayed, (cause to) fail, (cause, make to) fall (down, -ing), feeble, be (the) ruin(-ed, of), (be) overthrown, (cause to) stumble, × utterly, be weak.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1305}/[H1305]', 'inflected', 'heb', 'בָּרַר', '["bârar"]', '["and/ to/ purge [them]"]', '["v"]', 'to clarify (i.e. brighten), examine, select make bright, choice, chosen, cleanse (be clean), clearly, polished, (shew self) pure(-ify), purge (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3835A}/[H3843]', 'inflected', 'heb', 'לָבַן', '["lâban"]', '["and/ to/ purify [them]"]', '["v"]', 'to be (or become) white; to make bricks make brick, be (made, make) white(-r).', 'a primitive root; also as denominative from 3843');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0433}/[H410]', 'inflected', 'heb', 'אֱלוֹהַּ', '["ʼĕlôwahh"]', '["and/ <to>/ a god","and/ <to>/ a god of"]', '["n-m"]', 'a deity or the Deity God, god. See 430.', 'rarely (shortened) אֱלֹהַּ; probably prolonged (emphatic) from 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2530B}/[H2530]', 'inflected', 'heb', 'חָמַד', '["châmad"]', '["and/ with/ precious things"]', '["v"]', 'to delight in beauty, greatly beloved, covet, delectable thing, (× great) delight, desire, goodly, lust, (be) pleasant (thing), precious (thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4013}/[H1219]', 'inflected', 'heb', 'מִבְצָר', '["mibtsâr"]', '["to/ [the] fortresses of"]', '["n-m"]', 'a fortification, castle, or fortified city; figuratively, a defender (de-, most) fenced, fortress, (most) strong (hold).', 'also (in plural) feminine (Daniel 11:l5) מִבְצָרָה; from 1219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4910}/H9038/[H4910]', 'inflected', 'heb', 'מָשַׁל', '["mâshal"]', '["and/ he will make rule/ them"]', '["v"]', 'to rule (have, make to have) dominion, governor, × indeed, reign, (bear, cause to, have) rule(-ing, -r), have power.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8175B}/[H8175]', 'inflected', 'heb', 'שָׂעַר', '["sâʻar"]', '["so/ he may storm"]', '["v"]', 'to storm; by implication, to shiver, i.e. fear be (horribly) afraid, fear, hurl as a storm, be tempestuous, come like (take away as with) a whirlwind.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0591}/[H590]', 'inflected', 'heb', 'אֳנִיָּה', '["ʼŏnîyâh"]', '["and/ with/ ships"]', '["n-f"]', 'a ship ship(-men).', 'feminine of 590;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7225H}/[H7218]', 'inflected', 'heb', 'רֵאשִׁית', '["rêʼshîyth"]', '["and/ [the] best of","and/ [the] first of"]', '["n-f"]', 'the first, in place, time, order or rank (specifically, a firstfruit) beginning, chief(-est), first(-fruits, part, time), principal thing.', 'from the same as 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7971K}/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["so/ he may stretch out"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4362}/[H3646]', 'inflected', 'heb', 'מִכְמַן', '["mikman"]', '["over/ [the] treasures of"]', '["n-m"]', 'treasure (as hidden) treasure.', 'from the same as 3646 in the sense of hiding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3864>', 'inflected', 'heb', 'ולבים', '["ve./lu.Vim"]', '["and/ Libyans"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4703}/H9023/[H6805]', 'inflected', 'heb', 'מִצְעָד', '["mitsʻâd"]', '["[will be] in/ footsteps/ his"]', '["n-m"]', 'a step; figuratively, companionship going, step.', 'from 6805;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0926}/H9033/[H926]', 'inflected', 'heb', 'בָּהַל', '["bâhal"]', '["they will dismay/ him"]', '["v"]', 'to tremble inwardly (or palpitate), i.e. (figuratively) be (causative, make) (suddenly) alarmed or agitated; by implication to hasten anxiously be (make) affrighted (afraid, amazed, dismayed, rash), (be, get, make) haste(-n, -y, -ily), (give) speedy(-ily), thrust out, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6828G}/[H6845]', 'inflected', 'heb', 'צָפוֹן', '["tsâphôwn"]', '["and/ from/ [the] north"]', '["n-f"]', 'properly, hidden, i.e. dark; used only of the north as a quarter (gloomy and unknown) north(-ern, side, -ward, wind).', 'or צָפֹן; from 6845;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2763A}/[H2763]', 'inflected', 'heb', 'חָרַם', '["châram"]', '["and/ to/ totally destroy"]', '["v"]', 'to seclude; specifically (by a ban) to devote to religious uses (especially destruction); physical and reflexive, to be blunt as to the nose make accursed, consecrate, (utterly) destroy, devote, forfeit, have a flat nose, utterly (slay, make away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0643}/H9023/[H643]', 'inflected', 'heb', 'אַפֶּדֶן', '["ʼappeden"]', '["palace/ his"]', '["n"]', 'a pavilion or palace-tent palace.', 'apparently of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3463}/[H3462]', 'inflected', 'heb', 'יָשֵׁן', '["yâshên"]', '["of/ [the] sleepers of"]', '["a"]', 'sleepy asleep, (one out of) sleep(-eth, -ing), slept.', 'from 3462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H1860>', 'inflected', 'heb', 'לדראון', '["le./dir.''on"]', '["to/ abhorrence of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7919A}/[H7919]', 'inflected', 'heb', 'שָׂכַל', '["sâkal"]', '["and/ those/ [who] have insight"]', '["v"]', 'to be (causatively, make or act) circumspect and hence, intelligent consider, expert, instruct, prosper, (deal) prudent(-ly), (give) skill(-ful), have good success, teach, (have, make to) understand(-ing), wisdom, (be, behave self, consider, make) wise(-ly), guide wittingly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2094A}/[H2094]', 'lemma', 'heb', 'זָהַר', '["zâhar"]', '["they will shine"]', '["v"]', 'to gleam; figuratively, to enlighten (by caution) admonish, shine, teach, (give) warn(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2096}/[H2094]', 'inflected', 'heb', 'זֹהַר', '["zôhar"]', '["like/ [the] shining of"]', '["n-m"]', 'brilliancy brightness.', 'from 2094;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5703}\/[H5710]', 'inflected', 'heb', 'עַד', '["ʻad"]', '["and/ ever"]', '["n-m"]', 'properly, a (peremptory) terminus, i.e. (by implication) duration, in the sense of advance or perpetuity (substantially as a noun, either with or without a preposition) eternity, ever(-lasting, -more), old, perpetually, world without end.', 'from 5710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8193J}/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["to/ [the] bank of"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2975H}/[H2975]', 'inflected', 'heb', 'יְאֹר', '["yᵉʼôr"]', '["the/ River"]', '["n-m"]', 'a channel, e.g. a fosse, canal, shaft; specifically the Nile, as the one river of Egypt, including its collateral trenches; also the Tigris, as the main river of Assyria brook, flood, river, stream.', 'of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6382}/[H6381]', 'inflected', 'heb', 'פֶּלֶא', '["peleʼ"]', '["the/ wonders"]', '["n-m"]', 'a miracle marvellous thing, wonder(-ful, -fully).', 'from 6381;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2416A}/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["by/ [the] living one of"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3835A}/[H3843]', 'inflected', 'heb', 'לָבַן', '["lâban"]', '["and/ they may purify themselves"]', '["v"]', 'to be (or become) white; to make bricks make brick, be (made, make) white(-r).', 'a primitive root; also as denominative from 3843');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H1486>/H9021', 'inflected', 'heb', 'לגרלך', '["le./go.ra.le./Kha"]', '["to/ allotted portion/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1954J}/[H3467]', 'lemma', 'heb', 'הוֹשֵׁעַ', '["Hôwshêaʻ"]', '["Hosea"]', '["n-pr-m"]', 'Hoshea, the name of five Israelites Hosea, Hoshea, Oshea.', 'from 3467; deliverer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0882H}/[H875]', 'lemma', 'heb', 'בְּאֵרִי', '["Bᵉʼêrîy"]', '["Beeri"]', '["n-pr-m"]', 'Beeri, the name of a Hittite and of an Israelite Beeri.', 'from 875; fountained;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3169H}/[H3388]', 'lemma', 'heb', 'יְחִזְקִיָּה', '["Yᵉchizqîyâh"]', '["Hezekiah"]', '["n-pr-m"]', 'Jechizkijah, the name of five Israelites Hezekiah, Jehizkiah. Compare 2396.', 'or יְחִזְקִיָּהוּ; from 3388 and 3050; strengthened of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1954J}\/[H3467]', 'inflected', 'heb', 'הוֹשֵׁעַ', '["Hôwshêaʻ"]', '["by/ Hosea"]', '["n-pr-m"]', 'Hoshea, the name of five Israelites Hosea, Hoshea, Oshea.', 'from 3467; deliverer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1586H}/[H1584]', 'lemma', 'heb', 'גֹּמֶר', '["Gômer"]', '["Gomer"]', '["n-pr-m n-pr-f"]', 'Gomer, the name of a son of Japheth and of his descendants; also of a Hebrewess Gomer.', 'from 1584; completion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1691}/[H1690]', 'lemma', 'heb', 'דִּבְלַיִם', '["Diblayim"]', '["Diblaim"]', '["n-pr-m"]', 'Diblajim, a symbolic name Diblaim.', 'dual from the masculine of 1690; two cakes;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3157K}/[H2232]', 'lemma', 'heb', 'יִזְרְעֵאל', '["Yizrᵉʻêʼl"]', '["Jezreel"]', '["n-pr-m n-pr-loc"]', 'Jizreel, the name of two places in Palestine and of two Israelites Jezreel.', 'from 2232 and 410; God will sow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3819}/[H3808]', 'lemma', 'heb', 'לֹא רֻחָמָה', '["Lôʼ Ruchâmâh"]', '["Lo-","Ruhamah"]', '["n-pr-f"]', 'Lo-Ruchamah, the symbolic name of a son of Hosea Lo-ruhamah.', 'from 3808 and 7355; not pitied;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3818}/[H3808]', 'lemma', 'heb', 'לֹא עַמִּי', '["Lôʼ ʻAmmîy"]', '["Ammi","Lo-"]', '["n-pr-m"]', 'Lo-Ammi, the symbolic name of a son of Hosea Lo-ammi.', 'from 3808 and 5971 with pronominal suffix; not my people;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0269}/H9026/[H251]', 'inflected', 'heb', 'אָחוֹת', '["ʼâchôwth"]', '["and/ to/ sisters/ your"]', '["n-f"]', 'a sister (used very widely [like 251number 250, corrected to 251], literally and figuratively) (an-) other, sister, together.', 'irregular feminine of 251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0517}/H9026/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["with/ mother/ your"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2183}/H9024/[H2181]', 'inflected', 'heb', 'זָנוּן', '["zânûwn"]', '["prostitution<s>/ her"]', '["n-m"]', 'adultery; figuratively, idolatry whoredom.', 'from 2181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6440H}/H9024/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["from/ face/ her"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5005}/H9024/[H5003]', 'inflected', 'heb', 'נַאֲפוּף', '["naʼăphûwph"]', '["and/ adulteries/ her"]', '["n-m"]', 'adultery adultery.', 'from 5003;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7699A}/H9024/[H7736]', 'inflected', 'heb', 'שַׁד', '["shad"]', '["breasts/ her"]', '["n-m"]', 'the breast of a woman or animal (as bulging) breast, pap, teat.', 'or שֹׁד; probably from 7736 (in its original sense) contracted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6584}/H9034/[H6584]', 'inflected', 'heb', 'פָּשַׁט', '["pâshaṭ"]', '["I should strip/ her"]', '["v"]', 'to spread out (i.e. deploy in hostile array); by analogy, to strip (i.e. unclothe, plunder, flay, etc.) fall upon, flay, invade, make an invasion, pull off, put off, make a road, run upon, rush, set, spoil, spread selves (abroad), strip (off, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3322}/H9034/[H3322]', 'inflected', 'heb', 'יָצַג', '["yâtsag"]', '["and/ I will exhibit/ her"]', '["v"]', 'to place permanently establish, leave, make, present, put, set, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7896G}/H9034/[H7896]', 'inflected', 'heb', 'שִׁית', '["shîyth"]', '["and/ I will make/ her"]', '["v"]', 'to place (in a very wide application) apply, appoint, array, bring, consider, lay (up), let alone, × look, make, mark, put (on), regard, set, shew, be stayed, × take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2029}/H9038/[H2029]', 'inflected', 'heb', 'הָרָה', '["hârâh"]', '["[the] [one who] conceived/ them"]', '["v"]', 'to be (or become) pregnant, conceive (literally or figuratively) been, be with child, conceive, progenitor.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4325G}/H9020/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["and/ water/ my"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6785>/H9020', 'opaque', 'heb', 'צֶמֶר', '["tsemer"]', '["wool/ my"]', '["n-m"]', 'wool wool(-len).', 'from an unused root probably meaning to be shaggy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6593}/H9020/[H6580]', 'inflected', 'heb', 'פִּשְׁתֶּה', '["pishteh"]', '["and/ flax/ my"]', '["n-f"]', 'linen (i.e. the thread, as carded) flax, linen.', 'from the same as 6580 as in the sense of comminuting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8081}/H9020/[H8080]', 'inflected', 'heb', 'שֶׁמֶן', '["shemen"]', '["oil/ my"]', '["n-m"]', 'grease, especially liquid (as from the olive, often perfumed); figuratively, richness anointing, × fat (things), × fruitful, oil(-ed), ointment, olive, pine.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8250}/H9020/[H8248]', 'inflected', 'heb', 'שִׁקּוּי', '["shiqqûwy"]', '["and/ drinks/ my"]', '["n-m"]', 'a beverage; moisture, i.e. (figuratively) refreshment drink, marrow.', 'from 8248;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5518B}/[H5518]', 'inflected', 'heb', 'סִיר', '["çîyr"]', '["with <the>/ thorns","with/ hooks of"]', '["n-m"]', 'a pot; also a thorn (as springing up rapidly); by implication, a hook caldron, fishhook, pan, (wash-)pot, thorn.', 'or (feminine) סִירָה; or סִרָה; (Jeremiah 52:18), from a primitive root meaning to boil up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5410B>/H9024', 'inflected', 'heb', 'ונתיבותיה', '["u./ne.ti.vo.Tei./ha"]', '["and/ paths/ her"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1245}/H9038/[H1245]', 'inflected', 'heb', 'בָּקַשׁ', '["bâqash"]', '["and/ she will seek/ them"]', '["v"]', 'to search out (by any method, specifically in worship or prayer); by implication, to strive after ask, beg, beseech, desire, enquire, get, make inquisition, procure, (make) request, require, seek (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1715}/H9020/[H1711]', 'inflected', 'heb', 'דָּגָן', '["dâgân"]', '["grain/ my"]', '["n-m"]', 'properly, increase, i.e. grain corn (floor), wheat.', 'from 1711;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8492}/H9020/[H3423]', 'inflected', 'heb', 'תִּירוֹשׁ', '["tîyrôwsh"]', '["and/ new wine/ my"]', '["n-m"]', 'must or fresh grape-juice (as just squeezed out); by implication (rarely) fermented wine (new, sweet) wine.', 'or תִּירֹשׁ; from 3423 in the sense of expulsion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5040}/H9024/[H5036]', 'inflected', 'heb', 'נַבְלוּת', '["nablûwth"]', '["lewdness/ her"]', '["n-f"]', 'properly, disgrace, i.e. the (female) pudenda lewdness.', 'from 5036;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5337}/H9034/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["he will deliver/ her"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4885}/H9024/[H7797]', 'inflected', 'heb', 'מָשׂוֹשׂ', '["mâsôws"]', '["gaiety/ her"]', '["n-m"]', 'delight, concretely (the cause or object) or abstractly (the feeling) joy, mirth, rejoice.', 'from 7797;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2282}/H9024/[H2287]', 'inflected', 'heb', 'חַג', '["chag"]', '["festival[s]/ her"]', '["n-m"]', 'a festival, or a victim therefor (solemn) feast (day), sacrifice, solemnity.', 'or חָג; from 2287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2320H}/H9024/[H2318]', 'inflected', 'heb', 'חֹדֶשׁ', '["chôdesh"]', '["new moon[s]/ her"]', '["n-m"]', 'the new moon; by implication, a month month(-ly), new moon.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7676}/H9024/[H7673]', 'inflected', 'heb', 'שַׁבָּת', '["shabbâth"]', '["and/ sabbath[s]/ her"]', '["n"]', 'intermission, i.e (specifically) the Sabbath ( every) sabbath.', 'intensive from 7673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4150H}/H9024/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["appointed feast/ her"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1612>/H9024', 'opaque', 'heb', 'גֶּפֶן', '["gephen"]', '["vine[s]/ her"]', '["n-m"]', 'a vine (as twining), especially the grape vine, tree.', 'from an unused root meaning to bend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8384}/H9024/[H8384]', 'inflected', 'heb', 'תְּאֵן', '["tᵉʼên"]', '["and/ fig tree[s]/ her"]', '["n-f"]', 'the fig (tree or fruit) fig (tree).', 'or (in the singular, feminine) תְּאֵנָה; perhaps of foreign derivation');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0866}/[H8566]', 'lemma', 'heb', 'אֶתְנָה', '["ʼethnâh"]', '["[are] wage[s]"]', '["n-f"]', 'a present (as the price of harlotry) reward.', 'from 8566;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5141>/H9024', 'opaque', 'heb', 'נֶזֶם', '["nezem"]', '["ring[s]/ her"]', '["n-m"]', 'a nose-ring earring, jewel.', 'from an unused root of uncertain meaning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2484}/H9024/[H2481]', 'inflected', 'heb', 'חֶלְיָה', '["chelyâh"]', '["and/ jewelry/ her"]', '["n-f"]', 'a trinket jewel.', 'feminine of 2481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6601B}/H9034/[H6601]', 'inflected', 'heb', 'פָּתָה', '["pâthâh"]', '["[am] about to persuade/ her"]', '["v"]', 'to open, i.e. be (causatively, make) roomy; usually figuratively (in a mental or moral sense) to be (causatively, make) simple or (in a sinister way) delude allure, deceive, enlarge, entice, flatter, persuade, silly (one).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1980J}/H9034/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ I will lead/ her"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3754>/H9024', 'opaque', 'heb', 'כֶּרֶם', '["kerem"]', '["vineyards/ her"]', '["n-m"]', 'a garden or vineyard vines, (increase of the) vineyard(-s), vintage. See also 1021.', 'from an unused root of uncertain meaning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1180}/H9020/[H1167]', 'inflected', 'heb', 'בַּעֲלִי', '["Baʻălîy"]', '["Baal/ my"]', '["n-m"]', 'Baali, a symbolical name for Jehovah Baali.', 'from 1167 with pron. suff.; my master;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6310G}/H9024/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["from/ mouth/ her"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7901G}/H9038/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["and/ I will make lie down/ them"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0781}/H9032/[H781]', 'inflected', 'heb', 'אָרַשׂ', '["ʼâras"]', '["and/ I will betroth/ you"]', '["v"]', 'to engage for matrimony betroth, espouse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4941H}/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["and/ in/ justice"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3323}/[H6671]', 'inflected', 'heb', 'יִצְהָר', '["yitshâr"]', '["the/ fresh oil"]', '["n-m"]', 'oil (as producing light); figuratively, anointing anointed oil.', 'from 6671;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0160}/[H158]', 'inflected', 'heb', 'אַהֲבָה', '["ʼahăbâh"]', '["as/ loves"]', '["n-f"]', 'love.', 'feminine of 158 and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0809}/[H808]', 'lemma', 'heb', 'אֲשִׁישָׁה', '["ʼăshîyshâh"]', '["<of> cakes of"]', '["n-f"]', 'something closely pressed together, i.e. a cake of raisins or other comfits flagon.', 'feminine of 808;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3739A}/H9034/[H3738]', 'inflected', 'heb', 'כָּרָה', '["kârâh"]', '["and/ I bought/ her"]', '["v"]', 'to purchase buy, prepare.', 'usually assigned as a primitive root, but probably only a special application of 3738 (through the common idea of planning implied in a bargain);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2563C}/[H2560]', 'inflected', 'heb', 'חֹמֶר', '["chômer"]', '["and/ a homer of"]', '["n-m"]', 'properly, a bubbling up, i.e. of water, a wave; of earth, mire or clay (cement); also a heap; hence, a chomer or dry measure clay, heap, homer, mire, motion.', 'from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3963>', 'inflected', 'heb', 'ולתך', '["ve./Le.tekh"]', '["and/ a lethech of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7523}/[H7523]', 'inflected', 'heb', 'רָצַח', '["râtsach"]', '["and/ murdering"]', '["v"]', 'properly, to dash in pieces, i.e. kill (a human being), especially to murder put to death, kill, (man-) slay(-er), murder(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0535}/[H535]', 'inflected', 'heb', 'אָמַל', '["ʼâmal"]', '["and/ he will wither"]', '["v"]', 'to droop; by implication to be sick, to mourn languish, be weak, wax feeble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2416C}/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["among/ [the] animal[s] of"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7378}/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["[is] like/ [those who] contend"]', '["v"]', 'properly, to toss, i.e. grapple; mostly figuratively, to wrangle, i.e. hold a controversy; (by implication) to defend adversary, chide, complain, contend, debate, × ever, × lay wait, plead, rebuke, strive, × thoroughly.', 'or רוּב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1820}/[H1820]', 'inflected', 'heb', 'דָּמָה', '["dâmâh"]', '["and/ I will destroy"]', '["v"]', 'to be dumb or silent; hence, to fail or perish; trans. to destroy cease, be cut down (off), destroy, be brought to silence, be undone, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3988A}/H9031/[H3988]', 'inflected', 'heb', 'מָאַס', '["mâʼaç"]', '["and/ I will reject/ you"]', '["v"]', 'to spurn; also (intransitively) to disappear abhor, cast away (off), contemn, despise, disdain, (become) loathe(some), melt away, refuse, reject, reprobate, × utterly, vile person.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7235A}/H9048/[H7235]', 'inflected', 'heb', 'רָבָה', '["râbâh"]', '["as/ increased/ they"]', '["v"]', 'to increase (in whatever respect) (bring in) abundance (× -antly), archer (by mistake for 7232), be in authority, bring up, × continue, enlarge, excel, exceeding(-ly), be full of, (be, make) great(-er, -ly, × -ness), grow up, heap, increase, be long, (be, give, have, make, use) many (a time), (any, be, give, give the, have) more (in number), (ask, be, be so, gather, over, take, yield) much (greater, more), (make to) multiply, nourish, plenty(-eous), × process (of time), sore, store, thoroughly, very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7036}/[H7034]', 'inflected', 'heb', 'קָלוֹן', '["qâlôwn"]', '["for/ shame"]', '["n-m"]', 'disgrace; (by implication) the pudenda confusion, dishonour, ignominy, reproach, shame.', 'from 7034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4611}/H9023/[H5953]', 'inflected', 'heb', 'מַעֲלָל', '["maʻălâl"]', '["and/ deeds/ his"]', '["n-m"]', 'an act (good or bad) doing, endeavour, invention, work.', 'from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2184}/[H2181]', 'lemma', 'heb', 'זְנוּת', '["zᵉnûwth"]', '["prostitution"]', '["n-f"]', 'adultery, i.e. (figuratively) infidelity, idolatry whoredom.', 'from 2181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6086G}/H9023/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["by/ wood/ his"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4731>/H9023', 'inflected', 'heb', 'ומקלו', '["u./mak.L/o"]', '["and/ stick/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8478H}/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["from/ under"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3839}/[H3835]', 'inflected', 'heb', 'לִבְנֶה', '["libneh"]', '["and/ poplar"]', '["n-m"]', 'some sort of whitish tree, perhaps the storax poplar.', 'from 3835;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0424}/[H352]', 'inflected', 'heb', 'אֵלָה', '["ʼêlâh"]', '["and/ terebinth"]', '["n-f"]', 'an oak or other strong tree elm, oak, teil-tree.', 'feminine of 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3618G}/H9026/[H3634]', 'inflected', 'heb', 'כַּלָּה', '["kallâh"]', '["and/ brides/ your"]', '["n-f"]', 'a bride (as if perfect); hence, a son''s wife bride, daughter-in-law, spouse.', 'from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3618G}/H9026/[H3634]', 'inflected', 'heb', 'כַּלָּה', '["kallâh"]', '["brides/ your"]', '["n-f"]', 'a bride (as if perfect); hence, a son''s wife bride, daughter-in-law, spouse.', 'from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6510}/[H6499]', 'inflected', 'heb', 'פָּרָה', '["pârâh"]', '["like/ a heifer"]', '["n-f"]', 'a heifer cow, heifer, kine.', 'feminine of 6499;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5435}/H9028/[H5433]', 'inflected', 'heb', 'סֹבֶא', '["çôbeʼ"]', '["drink/ their"]', '["n-m"]', 'potation, concretely (wine), or abstractly (carousal) drink, drunken, wine.', 'from 5433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4043}/H9024/[H1598]', 'inflected', 'heb', 'מָגֵן', '["mâgên"]', '["shields/ its"]', '["n-m"]', 'a shield (i.e. the small one or buckler); figuratively, a protector; also the scaly hide of the crocodile × armed, buckler, defence, ruler, scale, shield.', 'also (in plural) feminine מְגִנָּה; from 1598;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3671}/H9024/[H3670]', 'inflected', 'heb', 'כָּנָף', '["kânâph"]', '["[will be] in/ wings/ its","in/ wings/ its"]', '["n-f"]', 'an edge or extremity; specifically (of a bird or army) a wing, (of a garment or bedclothing) a flap, (of the earth) a quarter, (of a building) a pinnacle bird, border, corner, end, feather(-ed), × flying, (one an-) other, overspreading, × quarters, skirt, × sort, uttermost part, wing(-ed).', 'from 3670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2077}/H9028\/[H2076]', 'inflected', 'heb', 'זֶבַח', '["zebach"]', '["from/ sacrifices/ their"]', '["n-m"]', 'properly, a slaughter, i.e. the flesh of an animal; by implication, a sacrifice (the victim or the act) offer(-ing), sacrifice.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4709H}/[H4708]', 'inflected', 'heb', 'מִצְפָּה', '["Mitspâh"]', '["to/ Mizpah"]', '["n-pr-f"]', 'Mitspah, the name of two places in Palestine Mitspah. (This seems rather to be only an orthographic variation of 4708 when ''in pause''.)', 'feminine of 4708;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7568}/[H3423]', 'inflected', 'heb', 'רֶשֶׁת', '["resheth"]', '["and/ a net"]', '["n-f"]', 'a net (as catching animals) net(-work).', 'from 3423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7819B}/[H7819]', 'inflected', 'heb', 'שָׁחַט', '["shâchaṭ"]', '["and/ slaughtering"]', '["v n-f"]', 'to slaughter (in sacrifice or massacre) kill, offer, shoot out, slay, slaughter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5771H}/H9028/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["on/ iniquity/ their"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6629G>/H9028', 'inflected', 'heb', 'בצאנם', '["be./tzo.Na/m"]', '["with/ flock[s]/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1241}/H9028/[H1239]', 'inflected', 'heb', 'בָּקָר', '["bâqâr"]', '["and/ with/ herd[s]/ their"]', '["n-m"]', 'a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5253}/[H5253]', 'inflected', 'heb', 'נָסַג', '["nâçag"]', '["like/ [those who] displace"]', '["v"]', 'to retreat departing away, remove, take (hold), turn away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4205}/H9023/[H2115]', 'inflected', 'heb', 'מָזוֹר', '["mâzôwr"]', '["wound/ his"]', '["n-m"]', 'a bandage, i.e. remedy; hence, a sore (as needing a compress) bound up, wound.', 'or מָזֹר; from 2115 in the sense of binding up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3377}/[H7378]', 'lemma', 'heb', 'יָרֵב', '["Yârêb"]', '["Jareb"]', '["n-m"]', 'Jareb, a symbolical name for Assyria Jareb. Compare 3402.', 'from 7378; he will contend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1455}/[H1455]', 'lemma', 'heb', 'גָּהָה', '["gâhâh"]', '["it will depart"]', '["v"]', 'to remove (a bandage from a wound, i.e. heal it) cure.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4205}/[H2115]', 'lemma', 'heb', 'מָזוֹר', '["mâzôwr"]', '["[the] wound"]', '["n-m"]', 'a bandage, i.e. remedy; hence, a sore (as needing a compress) bound up, wound.', 'or מָזֹר; from 2115 in the sense of binding up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7495}/H9035/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["and/ he will heal/ us"]', '["v"]', 'properly, to mend (by stitching), i.e. (figuratively) to cure cure, (cause to) heal, physician, repair, × thoroughly, make whole. See 7503.', 'or רָפָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2280}/H9035/[H2280]', 'inflected', 'heb', 'חָבַשׁ', '["châbash"]', '["and/ he will bind up/ us"]', '["v"]', 'to wrap firmly (especially a turban, compress, or saddle); figuratively, to stop, to rule bind (up), gird about, govern, healer, put, saddle, wrap about.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965H}/H9035/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["he will raise up/ us"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1653}/[H1652]', 'inflected', 'heb', 'גֶּשֶׁם', '["geshem"]', '["like the/ rain"]', '["n-m"]', 'a shower rain, shower.', 'from 1652;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4456}/[H3953]', 'inflected', 'heb', 'מַלְקוֹשׁ', '["malqôwsh"]', '["like/ [the] spring rain"]', '["n-m"]', 'the spring rain; figuratively, eloquence latter rain.', 'from 3953; (compare 3954)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2617A}/H9026/[H2616]', 'inflected', 'heb', 'חֶסֶד', '["cheçed"]', '["and/ loyalty/ your"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5930A}/[H5927]', 'inflected', 'heb', 'עֹלָה', '["ʻôlâh"]', '["more than/ burnt offerings"]', '["n-f"]', 'a step or (collectively, stairs, as ascending); usually a holocaust (as going up in smoke) ascent, burnt offering (sacrifice), go up to. See also 5766.', 'or עוֹלָה; feminine active participle of 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H2442}/[H2707]', 'inflected', 'heb', 'חָכָה', '["châkâh"]', '["and/ as/ wait for"]', '["v"]', 'properly, to adhere to; hence, to await long, tarry, wait.', 'a primitive root (apparently akin to 2707 through the idea of piercing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7495}/H9040/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["when/ heal/ I"]', '["v"]', 'properly, to mend (by stitching), i.e. (figuratively) to cure cure, (cause to) heal, physician, repair, × thoroughly, make whole. See 7503.', 'or רָפָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1590}/[H1589]', 'inflected', 'heb', 'גַּנָּב', '["gannâb"]', '["and/ a thief"]', '["n-m"]', 'a stealer thief.', 'from 1589;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3824}/H9028/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["to/ heart/ their"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5437H}/H9038/[H5437]', 'inflected', 'heb', 'סָבַב', '["çâbab"]', '["they have surrounded/ them"]', '["v"]', 'to revolve, surround, or border; used in various applications, literally and figuratively bring, cast, fetch, lead, make, walk, × whirl, × round about, be about on every side, apply, avoid, beset (about), besiege, bring again, carry (about), change, cause to come about, × circuit, (fetch a) compass (about, round), drive, environ, × on every side, beset (close, come, compass, go, stand) round about, inclose, remove, return, set, sit down, turn (self) (about, aside, away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3585}/H9028/[H3584]', 'inflected', 'heb', 'כַּחַשׁ', '["kachash"]', '["and/ by/ lies/ their"]', '["n-m"]', 'literally a failure of flesh, i.e. emaciation; figuratively, hypocrisy leanness, lies, lying.', 'from 3584;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0644}/[H644]', 'inflected', 'heb', 'אָפָה', '["ʼâphâh"]', '["from/ a baker"]', '["v"]', 'to cook, especially to bake bake(-r, (-meats)).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3888}/[H3888]', 'inflected', 'heb', 'לוּשׁ', '["lûwsh"]', '["from/ kneading"]', '["v"]', 'to knead knead.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2556A}/H9043/[H2556]', 'inflected', 'heb', 'חָמֵץ', '["châmêts"]', '["is leavened/ it"]', '["v"]', 'to be pungent; i.e. in taste (sour, i.e. literally fermented, or figuratively, harsh), in color (dazzling) cruel (man), dyed, be grieved, leavened.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0696}/H9028/[H695]', 'inflected', 'heb', 'אֹרֶב', '["ʼôreb"]', '["in/ ambush/ their"]', '["n-m"]', 'wait.', 'the same as 695');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0644}/H9028/[H644]', 'inflected', 'heb', 'אָפָה', '["ʼâphâh"]', '["baker/ their"]', '["v"]', 'to cook, especially to bake bake(-r, (-meats)).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3256}/H9038/[H3256]', 'inflected', 'heb', 'יָסַר', '["yâçar"]', '["I will chasten/ them"]', '["v"]', 'to chastise, literally (with blows) or figuratively (with words); hence, to instruct bind, chasten, chastise, correct, instruct, punish, reform, reprove, sore, teach.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5712}/H9028\/[H5707]', 'inflected', 'heb', 'עֵדָה', '["ʻêdâh"]', '["to/ assembly/ their"]', '["n-f"]', 'a stated assemblage (specifically, a concourse, or generally, a family or crowd) assembly, company, congregation, multitude, people, swarm. Compare 5713.', 'feminine of 5707 in the original sense of fixture;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2195}/[H2194]', 'inflected', 'heb', 'זַעַם', '["zaʻam"]', '["from/ [the] indignation of"]', '["n-m"]', 'strictly froth at the mouth, i.e. (figuratively) fury (especially of God''s displeasure with sin) angry, indignation, rage.', 'from 2194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3933}/H9028/[H3932]', 'inflected', 'heb', 'לַעַג', '["laʻag"]', '["[will be] mockery/ their"]', '["n-m"]', 'derision, scoffing derision, scorn (-ing).', 'from 3932;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7786}/[H7786]', 'lemma', 'heb', 'שׂוּר', '["sûwr"]', '["they have installed leaders"]', '["v"]', 'properly, to vanquish; by implication, to rule (causatively, crown) make princes, have power, reign. See 5493.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5695}/H9022/[H5696]', 'inflected', 'heb', 'עֵגֶל', '["ʻêgel"]', '["calf/ your"]', '["n-m"]', 'a (male) calf (as frisking round), especially one nearly grown (i.e. a steer) bullock, calf.', 'from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5356A}/[H5352]', 'lemma', 'heb', 'נִקָּיוֹן', '["niqqâyôwn"]', '["innocence"]', '["n-m"]', 'clearness (literally or figuratively) cleanness, innocency.', 'or נִקָּיֹן; from 5352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7616>', 'opaque', 'heb', 'שָׁבָב', '["shâbâb"]', '["fragments"]', '["n-m"]', 'a fragment, i.e. ruin broken in pieces.', 'from an unused root meaning to break up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5492A}/H9011/[H5486]', 'inflected', 'heb', 'סוּפָה', '["çûwphâh"]', '["and/ a storm-wind/ <towards>"]', '["n-f n-pr-loc"]', 'a hurricane Red Sea, storm, tempest, whirlwind, Red sea.', 'from 5486;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8566}/[H8566]', 'lemma', 'heb', 'תָּנָה', '["tânâh"]', '["they have hired","they will hire"]', '["v"]', 'to present (a mercenary inducement), i.e. bargain with (a harlot) hire.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4853A}/[H5375]', 'inflected', 'heb', 'מַשָּׂא', '["massâʼ"]', '["from/ [the] burden of"]', '["n-m n-pr-m"]', 'a burden; specifically, tribute, or (abstractly) porterage; figuratively, an utterance, chiefly a doom, especially singing; mental, desire burden, carry away, prophecy, × they set, song, tribute.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1890}/H9020/[H3051]', 'inflected', 'heb', 'הַבְהָב', '["habhâb"]', '["gifts/ my"]', '["n-m"]', 'gift (in sacrifice), i.e. holocaust offering.', 'by reduplication from 3051;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3342>', 'inflected', 'heb', 'ויקב', '["va./Ye.kev"]', '["and/ wine-press"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0804G}/[H833]', 'inflected', 'heb', 'אַשּׁוּר', '["ʼAshshûwr"]', '["and/ in/ Assyria"]', '["n-pr-m n-pr-loc"]', 'Ashshur, the second son of Shem; also his descendants and the country occupied by them (i.e. Assyria), its region and its empire Asshur, Assur, Assyria, Assyrians. See 838.', 'or אַשֻּׁר; apparently from 833 (in the sense of successful);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4644}/[H4644]', 'lemma', 'heb', 'מֹף', '["Môph"]', '["Memphis"]', '["n-pr-loc"]', 'Moph, the capital of Lower Egypt Memphis. Compare 5297.', 'of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6912}/H9038/[H6912]', 'inflected', 'heb', 'קָבַר', '["qâbar"]', '["it will bury/ them"]', '["v"]', 'to inter × in any wise, bury(-ier).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3701G}/H9028/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["of/ silver/ their"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3423G}/H9038/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["it will take possession of/ them"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7966}/[H7999]', 'inflected', 'heb', 'שִׁלּוּם', '["shillûwm"]', '["<the>/ retribution"]', '["n-m"]', 'a requital, i.e. (secure) retribution, (venal) a fee recompense, reward.', 'or שִׁלֻּם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4895}/[H7850]', 'lemma', 'heb', 'מַשְׂטֵמָה', '["masṭêmâh"]', '["animosity"]', '["n-f"]', 'enmity hatred.', 'from the same as 7850;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3352}/[H3369]', 'lemma', 'heb', 'יָקוֹשׁ', '["yâqôwsh"]', '["a fowler"]', '["n-m"]', 'properly, entangling; hence, a snarer fowler.', 'from 3369;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H6025>', 'inflected', 'heb', 'כענבים', '["ka./''a.na.Vim"]', '["like/ grapes"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7225G}/H9024/[H7218]', 'inflected', 'heb', 'רֵאשִׁית', '["rêʼshîyth"]', '["at/ beginning/ its"]', '["n-f"]', 'the first, in place, time, order or rank (specifically, a firstfruit) beginning, chief(-est), first(-fruits, part, time), principal thing.', 'from the same as 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0157G}/H9048/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["as/ loved/ they"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H2032}/[H2029]', 'inflected', 'heb', 'הֵרוֹן', '["hêrôwn"]', '["and/ from/ conception"]', '["n-m"]', 'pregnancy conception.', 'or הֵרָיוֹן; from 2029;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7921A}/H9038/[H7921]', 'inflected', 'heb', 'שָׁכֹל', '["shâkôl"]', '["and/ I will bereave/ them"]', '["v"]', 'properly, to miscarry, i.e. suffer abortion; by analogy, to bereave (literally or figuratively) bereave (of children), barren, cast calf (fruit, young), be (make) childless, deprive, destroy, × expect, lose children, miscarry, rob of children, spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5493H}/H9040/[H5493]', 'inflected', 'heb', 'סוּר', '["çûwr"]', '["when/ depart/ I"]', '["v"]', 'to turn off (literally or figuratively) be(-head), bring, call back, decline, depart, eschew, get (you), go (aside), × grievous, lay away (by), leave undone, be past, pluck away, put (away, down), rebel, remove (to and fro), revolt, × be sour, take (away, off), turn (aside, away, in), withdraw, be without.', 'or שׂוּר; (Hosea 9:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6784}/[H6784]', 'lemma', 'heb', 'צָמַק', '["tsâmaq"]', '["[which] dry up"]', '["v"]', 'to dry up dry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1004B}/H9020/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["from/ house/ my"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1644H}/H9038/[H1644]', 'inflected', 'heb', 'גָּרַשׁ', '["gârash"]', '["I will drive out/ them"]', '["v"]', 'to drive out from a possession; especially to expatriate or divorce cast up (out), divorced (woman), drive away (forth, out), expel, × surely put away, trouble, thrust out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3205}/H9013/[H3205]', 'inflected', 'heb', 'יָלַד', '["yâlad"]', '["they [masc] will give birth/ !"]', '["v"]', 'to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0990H>/H9028\', 'opaque', 'heb', 'בֶּטֶן', '["beṭen"]', '["[masc] womb/ their"]', '["n-f"]', 'the belly, especially the womb; also the bosom or body of anything belly, body, as they be born, within, womb.', 'from an unused root probably meaning to be hollow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1238A}/[H1238]', 'lemma', 'heb', 'בָּקַק', '["bâqaq"]', '["luxuriant"]', '["v"]', 'to pour out, i.e. to empty, figuratively, to depopulate; by analogy, to spread out (as a fruitful vine) (make) empty (out), fail, × utterly, make void.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6529}/H9023/[H6509]', 'inflected', 'heb', 'פְּרִי', '["pᵉrîy"]', '["to/ fruit/ his"]', '["n-m"]', 'fruit (literally or figuratively) bough, (first-)fruit(-ful), reward.', 'from 6509;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2896B}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["according to/ [the] good"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7219}/[H7218]', 'inflected', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["like <the>/ poisonous plant"]', '["n-m"]', 'a poisonous plant, probably the poppy (from its conspicuous head); generally poison (even of serpents) gall, hemlock, poison, venom.', 'or רוֹשׁ; (Deuteronomy 32:32), apparently the same as 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8525>', 'opaque', 'heb', 'תֶּלֶם', '["telem"]', '["[the] furrows of"]', '["n-m"]', 'a bank or terrace furrow, ridge.', 'from an unused root meaning to accumulate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5697A}/[H5695]', 'inflected', 'heb', 'עֶגְלָה', '["ʻeglâh"]', '["for/ [the] heifers of"]', '["n-f"]', 'a (female) calf, especially one nearly grown (i.e. a heifer) calf, cow, heifer.', 'feminine of 5695;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3649}/H9023/[H3648]', 'inflected', 'heb', 'כָּמָר', '["kâmâr"]', '["and/ pagan priests/ its"]', '["n-m"]', 'properly, an ascetic (as if shrunk with self-maceration), i.e. an idolatrous priest (only in plural) Chemarims (idolatrous) priests.', 'from 3648;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0804G}/[H833]', 'inflected', 'heb', 'אַשּׁוּר', '["ʼAshshûwr"]', '["to/ Assyria"]', '["n-pr-m n-pr-loc"]', 'Ashshur, the second son of Shem; also his descendants and the country occupied by them (i.e. Assyria), its region and its empire Asshur, Assur, Assyria, Assyrians. See 838.', 'or אַשֻּׁר; apparently from 833 (in the sense of successful);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1317}/[H954]', 'lemma', 'heb', 'בׇּשְׁנָה', '["boshnâh"]', '["shame"]', '["n-m"]', 'shamefulness shame.', 'feminine from 954;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6098}/H9023/[H3289]', 'inflected', 'heb', 'עֵצָה', '["ʻêtsâh"]', '["from/ own counsel/ its"]', '["n-f"]', 'advice; by implication, plan; also prudence advice, advisement, counsel([-lor]), purpose.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7110B}/[H7107]', 'inflected', 'heb', 'קֶצֶף', '["qetseph"]', '["like/ a twig"]', '["n-m"]', 'a splinter (as chipped off); figuratively, rage or strife foam, indignation, × sore, wrath.', 'from 7107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0206H}/[H205]', 'lemma', 'heb', 'אָוֶן', '["ʼÂven"]', '["wickedness"]', '["n-pr-loc"]', 'Aven, the contemptuous synonym of three places, one in Coele-Syria, one in Egypt (On), and one in Palestine (Bethel) Aven. See also 204, 1007.', 'the same as 205; idolatry;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3680}/H9035/[H3680]', 'inflected', 'heb', 'כָּסָה', '["kâçâh"]', '["cover/ us"]', '["v"]', 'properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5921A}/H9035\/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["on/ us"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5932}/[H5766]', 'lemma', 'heb', 'עַלְוָה', '["ʻalvâh"]', '["injustice"]', '["n-f"]', 'moral perverseness iniquity.', 'for 5766;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0185}/H9020/[H183]', 'inflected', 'heb', 'אַוָּה', '["ʼavvâh"]', '["at/ desire/ my"]', '["n-f"]', 'longing desire, lust after, pleasure.', 'from 183;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3256}/H9038/[H3256]', 'inflected', 'heb', 'יָסַר', '["yâçar"]', '["and/ I will discipline/ them"]', '["v"]', 'to chastise, literally (with blows) or figuratively (with words); hence, to instruct bind, chasten, chastise, correct, instruct, punish, reform, reprove, sore, teach.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0631}/H9038/[H631]', 'inflected', 'heb', 'אָסַר', '["ʼâçar"]', '["when/ harness/ them"]', '["v"]', 'to yoke or hitch; by analogy, to fasten in any sense, to join battle bind, fast, gird, harness, hold, keep, make ready, order, prepare, prison(-er), put in bonds, set in array, tie.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6677A}/H9024/[H6696]', 'inflected', 'heb', 'צַוָּאר', '["tsavvâʼr"]', '["neck/ its"]', '["n-m"]', 'the back of the neck (as that on which burdens are bound) neck.', 'or צַוָּר; (Nehemiah 3:5), or צַוָּרֹןlemma צַוָּרן missing vowel, corrected to צַוָּרֹן; (Song of Solomon 4:9), or (feminine) צַוָּארָה; (Micah 2:3), intensively from 6696 in the sense of binding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3384A}/[H3384]', 'inflected', 'heb', 'יָרָה', '["yârâh"]', '["and/ he may rain down"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3585}/[H3584]', 'lemma', 'heb', 'כַּחַשׁ', '["kachash"]', '["lying"]', '["n-m"]', 'literally a failure of flesh, i.e. emaciation; figuratively, hypocrisy leanness, lies, lying.', 'from 3584;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1368}/H9021/[H1397]', 'inflected', 'heb', 'גִּבּוֹר', '["gibbôwr"]', '["warriors/ your"]', '["a"]', 'powerful; by implication, warrior, tyrant champion, chief, × excel, giant, man, mighty (man, one), strong (man), valiant man.', 'or גִּבֹּר; (shortened) intensive from the same as 1397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8020}/[H8020]', 'lemma', 'heb', 'שַׁלְמַן', '["Shalman"]', '["Shalman"]', '["n-pr-m"]', 'Shalman, a king apparently of Assyria Shalman. Compare 8022.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1009}/[H1004]', 'lemma', 'heb', 'בֵּית אַרְבֵּאל', '["Bêyth ʼArbêʼl"]', '["Arbel","Beth"]', '["n-pr-loc"]', 'Beth-Arbel, a place in Palestine Beth-Arbel.', 'from 1004 and 695 and 410; house of God''s ambush;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7837}/[H7836]', 'inflected', 'heb', 'שַׁחַר', '["shachar"]', '["at <the>/ dawn"]', '["n-m"]', 'dawn (literal, figurative or adverbial) day(-spring), early, light, morning, whence riseth.', 'from 7836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6456}/[H6458]', 'inflected', 'heb', 'פְּסִיל', '["pᵉçîyl"]', '["and/ to the/ idols"]', '["n-m"]', 'an idol carved (graven) image, quarry.', 'from 6458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6999H}/H9013/[H6999]', 'inflected', 'heb', 'קָטַר', '["qâṭar"]', '["they made smoke/ !"]', '["v n-m n-f"]', 'to smoke, i.e. turn into fragrance by fire (especially as an act of worship) burn (incense, sacrifice) (upon), (altar for) incense, kindle, offer (incense, a sacrifice).', 'a primitive root (identical with through the idea of fumigation in a close place and perhaps thus driving out the occupants);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8637}/[H7270]', 'lemma', 'heb', 'תִּרְגַּל', '["tirgal"]', '["I taught to walk"]', '["v"]', 'to cause to walk teach to go.', 'a denominative from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7495}/H9038/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["I had healed/ them"]', '["v"]', 'properly, to mend (by stitching), i.e. (figuratively) to cure cure, (cause to) heal, physician, repair, × thoroughly, make whole. See 7503.', 'or רָפָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4900}/H9038/[H4900]', 'inflected', 'heb', 'מָשַׁךְ', '["mâshak"]', '["I drew/ them"]', '["v"]', 'to draw, used in a great variety of applications (including to sow, to sound, to prolong, to develop, to march, to remove, to delay, to be tall, etc.) draw (along, out), continue, defer, extend, forbear, × give, handle, make (pro-, sound) long, × sow, scatter, stretch out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3895H>/H9028', 'opaque', 'heb', 'לְחִי', '["lᵉchîy"]', '["jaws/ their"]', '["n-m"]', 'the cheek (from its fleshiness); hence, the jaw-bone cheek (bone), jaw (bone).', 'from an unused root meaning to be soft;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2342J}/[H2342]', 'inflected', 'heb', 'חוּל', '["chûwl"]', '["and/ it will whirl"]', '["v"]', 'properly, to twist or whirl (in a circular or spiral manner), i.e. (specifically) to dance, to writhe in pain (especially of parturition) or fear; figuratively, to wait, to pervert bear, (make to) bring forth, (make to) calve, dance, drive away, fall grievously (with pain), fear, form, great, grieve, (be) grievous, hope, look, make, be in pain, be much (sore) pained, rest, shake, shapen, (be) sorrow(-ful), stay, tarry, travail (with pain), tremble, trust, wait carefully (patiently), be wounded.', 'or חִיל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4878}/H9020/[H7725]', 'inflected', 'heb', 'מְשׁוּבָה', '["mᵉshûwbâh"]', '["to/ apostasy/ my"]', '["n-f"]', 'apostasy backsliding, turning away.', 'or מְשֻׁבָה; from 7725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0126}/[H127]', 'inflected', 'heb', 'אַדְמָה', '["ʼAdmâh"]', '["like/ Admah"]', '["n-pr-loc"]', 'Admah, a place near the Dead Sea Admah.', 'contracted for 127; earthy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6636}/[H6643]', 'inflected', 'heb', 'צְבֹאִים', '["Tsᵉbôʼîym"]', '["like/ Zeboiim"]', '["n-pr-loc"]', 'Tseboim or Tsebijim, a place in Palestine Zeboiim, Zeboim.', 'or (more correctly) צְבִיִּים; or צְבִיִּם; plural of 6643; gazelles;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5150}/H9020/[H5162]', 'inflected', 'heb', 'נִחוּם', '["nichûwm"]', '["compassions/ my"]', '["n-m"]', 'properly, consoled; abstractly, solace comfort(-able), repenting.', 'or נִחֻם; from 5162;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5892A}/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["in/ rage"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2729}/[H2729]', 'inflected', 'heb', 'חָרַד', '["chârad"]', '["and/ they may tremble"]', '["v"]', 'to shudder with terror; hence, to fear; also to hasten (with anxiety) be (make) afraid, be careful, discomfit, fray (away), quake, tremble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3585}/[H3584]', 'inflected', 'heb', 'כַּחַשׁ', '["kachash"]', '["with/ lying"]', '["n-m"]', 'literally a failure of flesh, i.e. emaciation; figuratively, hypocrisy leanness, lies, lying.', 'from 3584;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4820}/[H7411]', 'inflected', 'heb', 'מִרְמָה', '["mirmâh"]', '["and/ with/ deceit"]', '["n-f"]', 'fraud craft, deceit(-ful, -fully), false, feigned, guile, subtilly, treachery.', 'from 7411 in the sense of deceiving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6485H}/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["and/ to/ visit [judgment]"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4611}/H9023/[H5953]', 'inflected', 'heb', 'מַעֲלָל', '["maʻălâl"]', '["according to/ deeds/ his"]', '["n-m"]', 'an act (good or bad) doing, endeavour, invention, work.', 'from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0202}/H9023/[H205]', 'inflected', 'heb', 'אוֹן', '["ʼôwn"]', '["and/ in/ manly vigor/ his"]', '["n-m"]', 'ability, power, (figuratively) wealth force, goods, might, strength, substance.', 'probably from the same as 205 (in the sense of effort, but successful);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0430G}/H9021/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["in/ God/ your"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3018}/H9020/[H3021]', 'inflected', 'heb', 'יְגִיעַ', '["yᵉgîyaʻ"]', '["toil<s>/ my"]', '["n-m"]', 'toil; hence, a work, produce, property (as the result of labor) labour, work.', 'from 3021;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3427}/H9031/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["I will cause to dwell/ you"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3027J}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ by/ [the] hand of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1530G}/[H1556]', 'inflected', 'heb', 'גַּל', '["gal"]', '["[are] like/ heaps of stones"]', '["n-m"]', 'something rolled, i.e. a heap of stone or dung (plural ruins), by analogy, a spring of water (plural waves) billow, heap, spring, wave.', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0758O}/[H759]', 'lemma', 'heb', 'אֲרָם', '["ʼĂrâm"]', '["Aram"]', '["n-pr-m n-m"]', 'Aram or Syria, and its inhabitants; also the name of the son of Shem, a grandson of Nahor, and of an Israelite Aram, Mesopotamia, Syria, Syrians.', 'from the same as 759; the highland;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0802H}/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["for/ a wife"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7578}/[H7374]', 'lemma', 'heb', 'רְתֵת', '["rᵉthêth"]', '["trembling"]', '["n-m"]', 'terror trembling.', 'for 7374;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3701G}/H9028/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["from/ silver/ their"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8394}/H9028/[H995]', 'inflected', 'heb', 'תָּבוּן', '["tâbûwn"]', '["according to/ skill/ their"]', '["n-m"]', 'intelligence; by implication, an argument; by extension, caprice discretion, reason, skilfulness, understanding, wisdom.', 'and (feminine) תְּבוּנָה; or תּוֹבֻנָה; from 995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5401A}/H9013/[H5400]', 'inflected', 'heb', 'נָשַׁק', '["nâshaq"]', '["they will kiss/ !"]', '["v"]', 'to kiss, literally or figuratively (touch); also (as a mode of attachment), to equip with weapons armed (men), rule, kiss, that touched.', 'a primitive root (identical with 5400, through the idea of fastening up; compare 2388, 2836);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H1637>', 'inflected', 'heb', 'מגרן', '["mi./Go.ren"]', '["from/ a threshing floor"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0699}/[H693]', 'inflected', 'heb', 'אֲרֻבָּה', '["ʼărubbâh"]', '["from/ a window"]', '["n-f"]', 'a lattice; (by implication) a window, dovecot (because of the pigeon-holes), chimney (with its apertures for smoke), sluice (with openings for water) chimney, window.', 'feminine participle passive of 693 (as if for lurking);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1115}/H9030/[H1086]', 'inflected', 'heb', 'בִּלְתִּי', '["biltîy"]', '["except/ me"]', '["np"]', 'properly, a failure of, i.e. (used only as a negative particle, usually with a prepositional prefix) not, except, without, unless, besides, because not, until, etc. because un(satiable), beside, but, continual, except, from, lest, neither, no more, none, not, nothing, save, that no, without.', 'constructive feminine of 1086 (equivalent to 1097);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8514}/[H3851]', 'lemma', 'heb', 'תַּלְאוּבָה', '["talʼûwbâh"]', '["drought<s>"]', '["n-f"]', 'desiccation great drought.', 'from 3851;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4830}/H9028/[H7462]', 'inflected', 'heb', 'מִרְעִית', '["mirʻîyth"]', '["according to/ pasture/ their"]', '["n-f"]', 'pasturage; concretely, a flock flock, pasture.', 'from 7462 in the sense of feeding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H5246>', 'inflected', 'heb', 'כנמר', '["ke./na.Mer"]', '["like/ a leopard"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6298}/H9038/[H6298]', 'inflected', 'heb', 'פָּגַשׁ', '["pâgash"]', '["I will meet/ them"]', '["v"]', 'to come in contact with, whether by accident or violence; figuratively, to concur meet (with, together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1234}/H9038/[H1234]', 'inflected', 'heb', 'בָּקַע', '["bâqaʻ"]', '["it will tear to pieces/ them"]', '["v"]', 'to cleave; generally, to rend, break, rip or open make a breach, break forth (into, out, in pieces, through, up), be ready to burst, cleave (asunder), cut out, divide, hatch, rend (asunder), rip up, tear, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0165}/[H346]', 'lemma', 'heb', 'אֱהִי', '["ʼĕhîy"]', '["where?"]', '["adv"]', 'where I will be (Hosea 13:10,14) (which is often the rendering of the same Hebrew form from 1961).', 'apparently an orthographical variation for 346;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3467}/H9031/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["so/ he may save/ you"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5678}/H9020\/[H5676]', 'inflected', 'heb', 'עֶבְרָה', '["ʻebrâh"]', '["in/ wrath/ my"]', '["n-f"]', 'an outburst of passion anger, rage, wrath.', 'feminine of 5676;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4866}/[H7665]', 'inflected', 'heb', 'מִשְׁבֵּר', '["mishbêr"]', '["at/ birth of"]', '["n-m"]', 'the orifice of the womb (from which the fœtus breaks forth) birth, breaking forth.', 'from 7665;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1698}/H9021/[H1696]', 'inflected', 'heb', 'דֶּבֶר', '["deber"]', '["[are] thorns/ your"]', '["n-m"]', 'a pestilence murrain, pestilence, plague.', 'from 1696 (in the sense of destroying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6987}/H9021/[H6986]', 'inflected', 'heb', 'קֹטֶב', '["qôṭeb"]', '["[is] destruction/ your"]', '["n-m"]', 'extermination destruction.', 'from the same as 6986;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5164}/[H5162]', 'lemma', 'heb', 'נֹחַם', '["nôcham"]', '["compassion"]', '["n-m"]', 'ruefulness, i.e. desistance repentance.', 'from 5162;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6500}/[H6500]', 'lemma', 'heb', 'פָּרָא', '["pârâʼ"]', '["he flourishes"]', '["v"]', 'to bear fruit be fruitful.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4726}/H9023/[H6979]', 'inflected', 'heb', 'מָקוֹר', '["mâqôwr"]', '["spring/ his"]', '["n-m"]', 'properly, something dug, i.e. a (general) source (of water, even when naturally flowing; also of tears, blood (by euphemism, of the female pudenda); figuratively, of happiness, wisdom, progeny) fountain, issue, spring, well(-spring).', 'or מָקֹר; from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4599}/H9023/[H5869]', 'inflected', 'heb', 'מַעְיָן', '["maʻyân"]', '["spring/ his"]', '["n-m"]', 'a fountain (also collectively), figuratively, a source (of satisfaction) fountain, spring, well.', 'or מַעְיְנוֹ; (Psalm 114:8), or (feminine) מַעְיָנָה; from 5869 (as a denominative in the sense of a spring);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0430G}/H9024/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["against/ God/ its"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5768}/H9028/[H5763]', 'inflected', 'heb', 'עוֹלֵל', '["ʻôwlêl"]', '["children/ their"]', '["n-m"]', 'a suckling babe, (young) child, infant, little one.', 'or עֹלָל; from 5763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2030B}/H9023/[H2029]', 'inflected', 'heb', 'הָרֶה', '["hâreh"]', '["and/ pregnant [women]/ its"]', '["a-f"]', 'pregnant (be, woman) with child, conceive, × great.', 'or הָרִי; (Hosea 14:1), from 2029;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5771G}/H9021/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["on/ iniquity/ your"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430J}/H9025/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["gods/ our"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7789}/H9033/[H7789]', 'inflected', 'heb', 'שׁוּר', '["shûwr"]', '["and/ I will watch over/ it"]', '["v"]', 'to spy out, i.e. (generally) survey, (for evil) lurk for, (for good) care for behold, lay wait, look, observe, perceive, regard, see.', 'a primitive root (identical with through the idea of going round for inspection);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H1265>', 'inflected', 'heb', 'כברוש', '["ki/v.Ro.osh"]', '["[am] like/ a cypress tree"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6529}/H9021/[H6509]', 'inflected', 'heb', 'פְּרִי', '["pᵉrîy"]', '["fruit/ your"]', '["n-m"]', 'fruit (literally or figuratively) bough, (first-)fruit(-ful), reward.', 'from 6509;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3045}/H9038/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["and/ let him know/ them"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5986}/[H6006]', 'lemma', 'heb', 'עָמוֹס', '["ʻÂmôwç"]', '["Amos","O Amos"]', '["n-pr-m"]', 'Amos, an Israelite prophet Amos.', 'from 6006; burdensome;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5349}/[H5348]', 'inflected', 'heb', 'נֹקֵד', '["nôqêd"]', '["among the/ sheep-tenders"]', '["n-m"]', 'a spotter (of sheep or cattle), i.e. the owner or tender (who thus marks them) herdman, sheepmaster.', 'active participle from the same as 5348;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8620}/[H8619]', 'inflected', 'heb', 'תְּקוֹעַ', '["Tᵉqôwaʻ"]', '["from/ Tekoa"]', '["n-pr-m n-pr-loc"]', 'Tekoa, a place in Palestine Tekoa, Tekoah.', 'a form of 8619;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3760G}\/[H3759]', 'inflected', 'heb', 'כַּרְמֶל', '["Karmel"]', '["<the>/ Carmel"]', '["n-pr-loc"]', 'Karmel, the name of a hill and of a town in Palestine Carmel, fruitful (plentiful) field, (place).', 'the same as 3759;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725O}/H9033/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["I will revoke/ it"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1758}/H9048/[H1758]', 'inflected', 'heb', 'דּוּשׁ', '["dûwsh"]', '["threshed/ they"]', '["v"]', 'to trample or thresh break, tear, thresh, tread out (down), at grass (Jeremiah 50:11, by mistake for 1877).', 'or דּוֹשׁ; or דִּישׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1237J}/[H1234]', 'inflected', 'heb', 'בִּקְעָה', '["biqʻâh"]', '["from/ [the] Valley of"]', '["n-f"]', 'properly, a split, i.e. a wide level valley between mountains plain, valley.', 'from 1234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0206G}/[H205]', 'lemma', 'heb', 'אָוֶן', '["ʼÂven"]', '["Aven"]', '["n-pr-loc"]', 'Aven, the contemptuous synonym of three places, one in Coele-Syria, one in Egypt (On), and one in Palestine (Bethel) Aven. See also 204, 1007.', 'the same as 205; idolatry;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8551}/[H8551]', 'inflected', 'heb', 'תָּמַךְ', '["tâmak"]', '["and/ a holder of"]', '["v"]', 'to sustain; by implication, to obtain, keep fast; figuratively, to help, follow close (take, up-) hold (up), maintain, retain, stay (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1040}/[H1004]', 'inflected', 'heb', 'בֵּית עֵדֶן', '["Bêyth ʻÊden"]', '["from/ Beth"]', '["n-pr-loc"]', 'Beth-Eden, a place in Syria Beth-eden.', 'from 1004 and 5730; house of pleasure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1040}/[H1004]', 'lemma', 'heb', 'בֵּית עֵדֶן', '["Bêyth ʻÊden"]', '["Eden"]', '["n-pr-loc"]', 'Beth-Eden, a place in Syria Beth-eden.', 'from 1004 and 5730; house of pleasure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1540K}/H9048/[H1540]', 'inflected', 'heb', 'גָּלָה', '["gâlâh"]', '["carried away into exile/ they"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0795}/[H7703]', 'inflected', 'heb', 'אַשְׁדּוֹד', '["ʼAshdôwd"]', '["from/ Ashdod"]', '["n-pr-loc"]', 'Ashdod, a place in Palestine Ahdod.', 'from 7703; ravager;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0831}/[H8254]', 'inflected', 'heb', 'אַשְׁקְלוֹן', '["ʼAshqᵉlôwn"]', '["from/ Ashkelon"]', '["n-pr-loc"]', 'Ashkelon, a place in Palestine Ashkelon, Askalon.', 'probably from 8254 in the sense of weighing-place (i.e. mart);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5462}/H9048/[H5462]', 'inflected', 'heb', 'סָגַר', '["çâgar"]', '["delivered up/ they"]', '["v"]', 'to shut up; figuratively, to surrender close up, deliver (up), give over (up), inclose, × pure, repair, shut (in, self, out, up, up together), stop, × straitly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7291}/H9043/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["pursued/ he"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2963}/[H2963]', 'inflected', 'heb', 'טָרַף', '["ṭâraph"]', '["and/ it tears","and/ it tore"]', '["v"]', 'to pluck off or pull to pieces; causatively to supply with food (as in morsels) catch, × without doubt, feed, ravin, rend in pieces, × surely, tear (in pieces).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8104G}/H9034/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["he kept/ it"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1224G}\/[H1223]', 'inflected', 'heb', 'בׇּצְרָה', '["Botsrâh"]', '["Bozrah"]', '["n-pr-loc"]', 'Botsrah, a place in Edom Bozrah.', 'the same as 1223;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1234}/H9048/[H1234]', 'inflected', 'heb', 'בָּקַע', '["bâqaʻ"]', '["ripped open/ they"]', '["v"]', 'to cleave; generally, to rend, break, rip or open make a breach, break forth (into, out, in pieces, through, up), be ready to burst, cleave (asunder), cut out, divide, hatch, rend (asunder), rip up, tear, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5591A}/[H5590]', 'inflected', 'heb', 'סַעַר', '["çaʻar"]', '["with/ a storm"]', '["n-m"]', 'a hurricane storm(-y), tempest, whirlwind.', 'or (feminine) סְעָרָה; from 5590;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8313}/H9043/[H8313]', 'inflected', 'heb', 'שָׂרַף', '["sâraph"]', '["burned/ he"]', '["v"]', 'to be (causatively, set) on fire (cause to, make a) burn((-ing), up) kindle, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7875}/[H7874]', 'inflected', 'heb', 'שִׂיד', '["sîyd"]', '["into <the>/ lime"]', '["n-m"]', 'lime (as boiling when slacked) lime, plaister.', 'from 7874;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7588}/[H7582]', 'inflected', 'heb', 'שָׁאוֹן', '["shâʼôwn"]', '["in/ uproar"]', '["n-m"]', 'uproar (as of rushing); by implication, destruction × horrible, noise, pomp, rushing, tumult (× -uous).', 'from 7582;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3988A}/H9048/[H3988]', 'inflected', 'heb', 'מָאַס', '["mâʼaç"]', '["have rejected/ they"]', '["v"]', 'to spurn; also (intransitively) to disappear abhor, cast away (off), contemn, despise, disdain, (become) loathe(some), melt away, refuse, reject, reprobate, × utterly, vile person.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3577}/H9028/[H3576]', 'inflected', 'heb', 'כָּזָב', '["kâzâb"]', '["lies/ their"]', '["n-m"]', 'falsehood; literally (untruth) or figuratively (idol) deceitful, false, leasing, liar, lie, lying.', 'from 3576;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7602B}/[H7602]', 'inflected', 'heb', 'שָׁאַף', '["shâʼaph"]', '["O those/ [who] trample on","those/ [who] trample"]', '["v"]', 'to inhale eagerly; figuratively, to cover; by implication, to be angry; also to hasten desire (earnestly), devour, haste, pant, snuff up, swallow up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2634}/[H2630]', 'inflected', 'heb', 'חָסֹן', '["châçôn"]', '["and/ [is] strong"]', '["a"]', 'powerful strong.', 'from 2630;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0437}/[H436]', 'inflected', 'heb', 'אַלּוֹן', '["ʼallôwn"]', '["like <the>/ oaks"]', '["n-m"]', 'oak.', 'a variation of 436');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1121A}/H9026/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["some of/ sons/ your"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0970}/H9026/[H977]', 'inflected', 'heb', 'בָּחוּר', '["bâchûwr"]', '["and/ some of/ young men/ your"]', '["n-m"]', 'properly, selected, i.e. a youth (often collective) (choice) young (man), chosen, × hole.', 'or בָּחֻר; participle passive of 977;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5139}/[H5144]', 'inflected', 'heb', 'נָזִיר', '["nâzîyr"]', '["to/ Nazirites"]', '["n-m"]', 'separate, i.e. consecrated (as prince, a Nazirite); hence (figuratively from the latter) an unpruned vine (like an unshorn Nazirite) Nazarite (by a false alliteration with Nazareth), separate(-d), vine undressed.', 'or נָזִר; from 5144;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5781}/[H5781]', 'lemma', 'heb', 'עוּק', '["ʻûwq"]', '["[am] about to make totter","it totters"]', '["v"]', 'to pack be pressed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478I}/H9036/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["under/ you"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5995}/[H6014]', 'lemma', 'heb', 'עָמִיר', '["ʻâmîyr"]', '["cut grain"]', '["n-m"]', 'a bunch of grain handful, sheaf.', 'from 6014;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7031}/[H7043]', 'inflected', 'heb', 'קַל', '["qal"]', '["from/ a swift [person]"]', '["a"]', 'light; (by implication) rapid (also adverbial) light, swift(-ly).', 'contracted from 7043;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7031}/[H7043]', 'inflected', 'heb', 'קַל', '["qal"]', '["and/ a [person] swift"]', '["a"]', 'light; (by implication) rapid (also adverbial) light, swift(-ly).', 'contracted from 7043;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7580}/[H7580]', 'inflected', 'heb', 'שָׁאַג', '["shâʼag"]', '["¿/ does it roar"]', '["v"]', 'to rumble or moan × mightily, roar.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2964}/[H2963]', 'inflected', 'heb', 'טֶרֶף', '["ṭereph"]', '["and/ prey"]', '["n-m"]', 'something torn, i.e. a fragment, e.g. a fresh leaf, prey, food leaf, meat, prey, spoil.', 'from 2963;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5414M}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["¿/ does it give forth"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4585}/H9023/[H4583]', 'inflected', 'heb', 'מְעוֹנָה', '["mᵉʻôwnâh"]', '["from/ den/ its"]', '["n-f"]', 'den, habitation, (dwelling) place, refuge.', 'or מְעֹנָה; feminine of 4583, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6217}/[H6231]', 'inflected', 'heb', 'עָשׁוּק', '["ʻâshûwq"]', '["and/ oppression<s>"]', '["n-m"]', 'used in plural masculine as abstractly, tyranny oppressed(-ion). [Doubtful.]', 'or עָשֻׁק; passive participle of 6231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0686}/[H686]', 'inflected', 'heb', 'אָצַר', '["ʼâtsar"]', '["those/ [who] store up"]', '["v"]', 'to store up (lay up in) store, (make) treasure(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0759H>/H9028\', 'inflected', 'heb', 'בארמנותיהם פ', '["be./''ar.me.No.tei./Hem"]', '["in/ fortresses/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0759H>/H9022', 'opaque', 'heb', 'אַרְמוֹן', '["ʼarmôwn"]', '["fortresses/ your"]', '["n-m"]', 'a citadel (from its height) castle, palace. Compare 2038.', 'from an unused root (meaning to be elevated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0915}/[H914]', 'lemma', 'heb', 'בָּדָל', '["bâdâl"]', '["a piece of"]', '["n-m"]', 'a part piece.', 'from 914;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6285}/[H6311]', 'inflected', 'heb', 'פֵּאָה', '["pêʼâh"]', '["with/ a corner of"]', '["n-f"]', 'properly, mouth in a figurative sense, i.e. direction, region, extremity corner, end, quarter, side.', 'feminine of 6311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1833}/[H1834]', 'inflected', 'heb', 'דְּמֶשֶׁק', '["dᵉmesheq"]', '["and/ with/ silk of"]', '["n-m"]', 'damask (as a fabric of Damascus) in Damascus.', 'by orthographical variation from 1834;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6485H}/H9040/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["visit/ I"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7019}/[H6972]', 'inflected', 'heb', 'קַיִץ', '["qayits"]', '["the/ summer"]', '["n-m"]', 'harvest (as the crop), whether the product (grain or fruit) or the (dry) season summer (fruit, house).', 'from 6972;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6793A}/[H6791]', 'inflected', 'heb', 'צִנָּה', '["tsinnâh"]', '["with/ barbs"]', '["n-f"]', 'a hook (as pointed); also a (large) shield (as if guarding by prickliness); also cold (as piercing) buckler, cold, hook, shield, target.', 'feminine of 6791;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0319}/H9027/[H310]', 'inflected', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["and/ posterity/ your"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1729}/[H1728]', 'lemma', 'heb', 'דּוּגָה', '["dûwgâh"]', '["fishing"]', '["n-f"]', 'properly, fishery, i.e. a hook for fishing fish (hook).', 'feminine from the same as 1728;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6556}/[H6555]', 'inflected', 'heb', 'פֶּרֶץ', '["perets"]', '["and/ breaches"]', '["n-m"]', 'a break (literally or figuratively) breach, breaking forth (in), × forth, gap.', 'from 6555;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5048}/H9034/[H5046]', 'inflected', 'heb', 'נֶגֶד', '["neged"]', '["before/ herself"]', '["prep"]', 'a front, i.e. part opposite; specifically a counterpart, or mate; usually (adverbial, especially with preposition) over against or before about, (over) against, × aloof, × far (off), × from, over, presence, × other side, sight, × to view.', 'from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2038}/H9011/[H2036]', 'inflected', 'heb', 'הַרְמוֹן', '["harmôwn"]', '["<the>/ Harmon/ towards"]', '["n-pr-loc"]', 'a castle (from its height) palace.', 'from the same as 2036;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2557A}/[H2556]', 'inflected', 'heb', 'חָמֵץ', '["châmêts"]', '["from/ a thing leavened"]', '["n-m"]', 'ferment, (figuratively) extortion leaven, leavened (bread).', 'from 2556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7121I}/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["and/ call out","and/ proclaim"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5356B}/[H5352]', 'lemma', 'heb', 'נִקָּיוֹן', '["niqqâyôwn"]', '["cleanness of"]', '["n-m"]', 'clearness (literally or figuratively) cleanness, innocency.', 'or נִקָּיֹן; from 5352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2640}/[H2637]', 'inflected', 'heb', 'חֹסֶר', '["chôçer"]', '["and/ lack of"]', '["n-m"]', 'poverty in want of.', 'from 2637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4725}/H9026/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["places/ your"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7105A}/[H7114]', 'inflected', 'heb', 'קָצִיר', '["qâtsîyr"]', '["[were] to the/ harvest"]', '["n-m"]', 'severed, i.e. harvest (as reaped), the crop, the time, the reaper, or figuratively; also a limb (of a tree, or simply foliage) bough, branch, harvest (man).', 'from 7114;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2513A}/[H2506]', 'inflected', 'heb', 'חֶלְקָה', '["chelqâh"]', '["and/ a portion of ground"]', '["n-f"]', 'properly, smoothness; figuratively, flattery; also an allotment field, flattering(-ry), ground, parcel, part, piece of land (ground), plat, portion, slippery place, smooth (thing).', 'feminine of 2506;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7711B}/[H7710]', 'inflected', 'heb', 'שְׁדֵפָה', '["shᵉdêphâh"]', '["with <the>/ blight"]', '["n-f n-m"]', 'blight blasted(-ing).', 'or שִׁדָּפוֹן; from 7710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1593}/H9026/[H1588]', 'inflected', 'heb', 'גַּנָּה', '["gannâh"]', '["gardens/ your"]', '["n-f"]', 'a garden garden.', 'feminine of 1588;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8384}/H9026/[H8384]', 'inflected', 'heb', 'תְּאֵן', '["tᵉʼên"]', '["and/ fig trees/ your"]', '["n-f"]', 'the fig (tree or fruit) fig (tree).', 'or (in the singular, feminine) תְּאֵנָה; perhaps of foreign derivation');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1501>', 'inflected', 'heb', 'הגזם', '["ha./ga.Zam"]', '["the/ locust"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5483M>/H9026', 'opaque', 'heb', 'סוּס', '["çûwç"]', '["horses/ your"]', '["n-m"]', 'a horse (as leaping); also a swallow (from its rapid flight) crane, horse (-back, -hoof). Compare 6571.', 'or סֻס; from an unused root meaning to skip (properly, for joy);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0889}/[H877]', 'lemma', 'heb', 'בְּאֹשׁ', '["bᵉʼôsh"]', '["[the] stench of"]', '["n-m"]', 'a stench stink.', 'from 877;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4264}/H9026/[H2583]', 'inflected', 'heb', 'מַחֲנֶה', '["machăneh"]', '["camp/ your"]', '["n-m"]', 'an encampment (of travellers or troops); hence, an army, whether literal (of soldiers) or figurative (of dancers, angels, cattle, locusts, stars; or even the sacred courts) army, band, battle, camp, company, drove, host, tents.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0639H}/H9026/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["<and>/ in/ nose/ your"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H0181>', 'inflected', 'heb', 'כאוד', '["ke./''Ud"]', '["like/ a piece of firewood"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8316}/[H8313]', 'inflected', 'heb', 'שְׂרֵפָה', '["sᵉrêphâh"]', '["from/ [the] burning"]', '["n-f"]', 'cremation burning.', 'from 8313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7808}/H9023/[H7879]', 'inflected', 'heb', 'שֵׂחַ', '["sêach"]', '["[is] thought/ his"]', '["n-m"]', 'communion, i.e. (reflexively) meditation thought.', 'for 7879;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0127G}/H9024/[H119]', 'inflected', 'heb', 'אֲדָמָה', '["ʼădâmâh"]', '["own land/ her"]', '["n-f"]', 'soil (from its general redness) country, earth, ground, husband(-man) (-ry), land.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965H}/H9034/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["[is one who] raises up/ her"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0205H>', 'inflected', 'heb', 'לאון', '["le./''A.ven"]', '["<into>/ trouble"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6743A}/[H6743]', 'lemma', 'heb', 'צָלַח', '["tsâlach"]', '["he should rush"]', '["v"]', 'to push forward, in various senses (literal or figurative, transitive or intransitive) break out, come (mightily), go over, be good, be meet, be profitable, (cause to, effect, make to, send) prosper(-ity, -ous, -ously).', 'or צָלֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3939>', 'inflected', 'heb', 'ללענה', '["le./la.''a.Nah"]', '["into/ wormwood"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3685G}/[H3684]', 'inflected', 'heb', 'כְּסִיל', '["Kᵉçîyl"]', '["and/ Orion"]', '["n-m"]', 'any notable constellation; specifically Orion (as if a burly one) constellation, Orion.', 'the same as 3684;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8210G}/H9038/[H8210]', 'inflected', 'heb', 'שָׁפַךְ', '["shâphak"]', '["and/ he poured out/ them"]', '["v"]', 'to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1082}/[H1082]', 'inflected', 'heb', 'בָּלַג', '["bâlag"]', '["the/ [who] causes to flash"]', '["v"]', 'to break off or loose (in a favorable or unfavorable sense), i.e. desist (from grief) or invade (with destruction) comfort, (recover) strength(-en).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1318}/H9046/[H1318]', 'inflected', 'heb', 'בָּשַׁס', '["bâshaç"]', '["trample/ you"]', '["v"]', 'to trample down tread.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3322}/[H3322]', 'inflected', 'heb', 'יָצַג', '["yâtsag"]', '["and/ set up"]', '["v"]', 'to place permanently establish, leave, make, present, put, set, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1930}/[H1929]', 'lemma', 'heb', 'הוֹ', '["hôw"]', '["alas!"]', '["inj"]', 'oh! alas.', 'by permutation from 1929;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6293}/H9033/[H6293]', 'inflected', 'heb', 'פָּגַע', '["pâgaʻ"]', '["and/ it meets/ him"]', '["v"]', 'to impinge, by accident or violence, or (figuratively) by importunity come (betwixt), cause to entreat, fall (upon), make intercession, intercessor, intreat, lay, light (upon), meet (together), pray, reach, run.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5391A}/H9033/[H5391]', 'inflected', 'heb', 'נָשַׁךְ', '["nâshak"]', '["and/ it bites/ him"]', '["v"]', 'to strike with a sting (as a serpent); figuratively, to oppress with interest on a loan bite, lend upon usury.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0651>', 'inflected', 'heb', 'ואפל', '["ve./''a.Fel"]', '["and/ gloomy"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2282}/H9026/[H2287]', 'inflected', 'heb', 'חַג', '["chag"]', '["feasts/ your","festivals/ your"]', '["n-m"]', 'a festival, or a victim therefor (solemn) feast (day), sacrifice, solemnity.', 'or חָג; from 2287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6116}/H9026/[H6113]', 'inflected', 'heb', 'עֲצָרָה', '["ʻătsârâh"]', '["in/ assemblies/ your"]', '["n-f"]', 'an assembly, especially on a festival or holiday (solemn) assembly (meeting).', 'or עֲצֶרֶת; from 6113;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4503G>/H9026', 'inflected', 'heb', 'ומנחתיכם', '["u./min.cho.tei./Khem"]', '["and/ grain offerings/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4806}/H9026/[H4754]', 'inflected', 'heb', 'מְרִיא', '["mᵉrîyʼ"]', '["fatlings/ your"]', '["n-m"]', 'stall-fed; often (as noun) a beeve fat (fed) beast (cattle, -ling).', 'from 4754 in the sense of grossness, through the idea of domineering (compare 4756);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7892A}/H9021/[H7891]', 'inflected', 'heb', 'שִׁיר', '["shîyr"]', '["songs/ your"]', '["n-m n-f"]', 'a song; abstractly, singing musical(-ick), × sing(-er, -ing), song.', 'or feminine שִׁירָה; from 7891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2172}/[H2167]', 'inflected', 'heb', 'זִמְרָה', '["zimrâh"]', '["and/ [the] music of"]', '["n-f"]', 'a musical piece or song to be accompanied by an instrument melody, psalm.', 'from 2167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H2077}/[H2076]', 'inflected', 'heb', 'זֶבַח', '["zebach"]', '["¿/ sacrifices"]', '["n-m"]', 'properly, a slaughter, i.e. the flesh of an animal; by implication, a sacrifice (the victim or the act) offer(-ing), sacrifice.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5522}/[H5519]', 'lemma', 'heb', 'סִכּוּת', '["çikkûwth"]', '["Sikkuth"]', '["n-pr-f"]', 'an (idolatrous) booth tabernacle.', 'feminine of 5519;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3594}/[H3559]', 'lemma', 'heb', 'כִּיּוּן', '["Kîyûwn"]', '["Kiyyun"]', '["n-pr"]', 'properly, a statue, i.e. idol; but used (by euphemism) for some heathen deity (perhaps corresponding to Priapus or Baal-peor) Chiun.', 'from 3559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6754>/H9026', 'opaque', 'heb', 'צֶלֶם', '["tselem"]', '["images/ your"]', '["n-m"]', 'a phantom, i.e. (figuratively) illusion, resemblance; hence, a representative figure, especially an idol image, vain shew.', 'from an unused root meaning to shade;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2579}/[H2574]', 'lemma', 'heb', 'חֲמַת רַבָּה', '["Chămath Rabbâh"]', '["Hamath-","Rabbah"]', '["n-pr-loc"]', 'Chamath-Rabbah Hamath the great', 'from 2574 and 7237; Chamath of Rabbah; probably the same as 2574.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1366H}/H9026/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["more than/ territory/ your"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5077B}/[H5077]', 'inflected', 'heb', 'נָדָה', '["nâdâh"]', '["those/ [who] push away"]', '["v"]', 'properly, to toss; figuratively, to exclude, i.e. banish, postpone, prohibit cast out, drive, put far away.', 'or נָדָא; (2 Kings 17:21), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5066H}/H9013/[H5066]', 'inflected', 'heb', 'נָגַשׁ', '["nâgash"]', '["and/ you have brought near/ !"]', '["v"]', 'to be or come (causatively, bring) near (for any purpose); euphemistically, to lie with a woman; as an enemy, to attack; religious to worship; causatively, to present; figuratively, to adduce an argument; by reversal, to stand back (make to) approach (nigh), bring (forth, hither, near), (cause to) come (hither, near, nigh), give place, go hard (up), (be, draw, go) near (nigh), offer, overtake, present, put, stand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7675}/[H3427]', 'lemma', 'heb', 'שֶׁבֶת', '["shebeth"]', '["a seat of"]', '["n-f"]', 'properly, session; but used also concretely, an abode or locality place, seat. Compare 3429.', 'infinitive of 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7901G}/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["those/ [who] lie"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5628}/[H5628]', 'inflected', 'heb', 'סָרַח', '["çârach"]', '["and/ [people] sprawled out"]', '["v"]', 'to extend (even to excess) exceeding, hand, spread, stretch self, banish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6210>/H9028', 'opaque', 'heb', 'עֶרֶשׂ', '["ʻeres"]', '["couches/ their"]', '["n-f"]', 'a couch (properly, with a canopy) bed(-stead), couch.', 'from an unused root meaning perhaps to arch;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H6629G>', 'inflected', 'heb', 'מצאן', '["mi./Tzon"]', '["from/ [the] flock"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6527}/[H6527]', 'inflected', 'heb', 'פָּרַט', '["pâraṭ"]', '["those/ [who] improvise"]', '["v"]', 'to scatter words, i.e. prate (or hum) chant.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8354}/[H8354]', 'inflected', 'heb', 'שָׁתָה', '["shâthâh"]', '["the/ [ones who] drink","those/ [who] drink"]', '["v"]', 'to imbibe (literally or figuratively) × assuredly, banquet, × certainly, drink(-er, -ing), drunk (× -ard), surely. (Prop. intensive of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4219}/[H2236]', 'inflected', 'heb', 'מִזְרָק', '["mizrâq"]', '["in/ bowls of"]', '["n-m"]', 'a bowl (as if for sprinkling) bason, bowl.', 'from 2236;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4797>', 'opaque', 'heb', 'מִרְזַח', '["mirzach"]', '["[the] revelry of"]', '["n-m"]', 'a cry, i.e. (of job), a revel banquet.', 'from an unused root meaning to scream;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5628}\/[H5628]', 'inflected', 'heb', 'סָרַח', '["çârach"]', '["sprawled out [people]"]', '["v"]', 'to extend (even to excess) exceeding, hand, spread, stretch self, banish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8374}/[H8373]', 'lemma', 'heb', 'תָּאַב', '["tâʼab"]', '["[am] loathing"]', '["v"]', 'to loathe (morally) abhor.', 'a primitive root (probably identical with 8373 through the idea of puffing disdainfully at; compare 340);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0759H>/H9023', 'inflected', 'heb', 'וארמנתיו', '["ve./''ar.me.no.Ta/v"]', '["and/ fortresses/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5635}/H9033/[H5635]', 'inflected', 'heb', 'סָרַף', '["çâraph"]', '["and/ [the one who] burns/ him"]', '["v"]', 'to cremate, i.e. to be (near) of kin (such being privileged to kindle the pyre) burn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7447B}/[H7450]', 'lemma', 'heb', 'רָסִיס', '["râçîyç"]', '["fragments"]', '["n-m"]', 'properly, dripping to pieces, i.e. a ruin; also a dew-drop breach, drop.', 'from 7450;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7323G}/H9013/[H7323]', 'inflected', 'heb', 'רוּץ', '["rûwts"]', '["¿/ do they run/ !"]', '["v"]', 'to run (for whatever reason, especially to rush) break down, divide speedily, footman, guard, bring hastily, (make) run (away, through), post.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7219}/[H7218]', 'inflected', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["into/ poison"]', '["n-m"]', 'a poisonous plant, probably the poppy (from its conspicuous head); generally poison (even of serpents) gall, hemlock, poison, venom.', 'or רוֹשׁ; (Deuteronomy 32:32), apparently the same as 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3810}/[H3808]', 'inflected', 'heb', 'לֹא דְבַר', '["Lôʼ Dᵉbar"]', '["to/ Lo"]', '["n-pr-loc"]', 'Lo-Debar, a place in Palestine Debir, Lodebar.', 'or לוֹ דבַר; (Samuel 9:4,5), or לִדְבִר; (Joshua 13:26), (probably rather לֹדְבַר ); from 3808 and 1699; pastureless;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2392}/H9025/[H2388]', 'inflected', 'heb', 'חֹזֶק', '["chôzeq"]', '["by/ own strength/ our"]', '["n-m"]', 'power strength.', 'from 2388;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7161B}/[H7160]', 'lemma', 'heb', 'קֶרֶן', '["qeren"]', '["Karnaim"]', '["n-f n-pr-loc"]', 'a horn (as projecting); by implication, a flask, cornet; by resemblance. an elephant''s tooth (i.e. ivory), a corner (of the altar), a peak (of a mountain), a ray (of light); figuratively, power × hill, horn.', 'from 7160;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0935H}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["from/ Lebo"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5158K}/[H5157]', 'lemma', 'heb', 'נַחַל', '["nachal"]', '["[the] wadi of"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6160H}\/[H6150]', 'inflected', 'heb', 'עֲרָבָה', '["ʻărâbâh"]', '["<the>/ Arabah"]', '["n-f"]', 'a desert; especially (with the article prefix) the (generally) sterile valley of the Jordan and its continuation to the Red Sea Arabah, champaign, desert, evening, heaven, plain, wilderness. See also 1026.', 'from 6150 (in the sense of sterility);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1462B}/[H1461]', 'lemma', 'heb', 'גּוֹב', '["gôwb"]', '["locusts"]', '["n-m"]', 'the locust (from its grubbing as a larvae) grasshopper, × great.', 'from 1461;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3954}/[H3953]', 'inflected', 'heb', 'לֶקֶשׁ', '["leqesh"]', '["the/ spring-crop"]', '["n-m"]', 'the after crop latter growth.', 'from 3953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3954}/[H3953]', 'lemma', 'heb', 'לֶקֶשׁ', '["leqesh"]', '["a spring-crop"]', '["n-m"]', 'the after crop latter growth.', 'from 3953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0594>', 'opaque', 'heb', 'אֲנָךְ', '["ʼănâk"]', '["tin"]', '["n-m"]', 'according to most a plumb-line, and to others a hook plumb-line', 'probably from an unused root meaning to be narrow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0558J}/[H553]', 'lemma', 'heb', 'אֲמַצְיָה', '["ʼĂmatsyâh"]', '["Amaziah"]', '["n-pr-m"]', 'Amatsjah, the name of four Israelites Amaziah.', 'or אֲמַצְיָהוּ; from 553 and 3050; strength of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0127G}/H9023\/[H119]', 'inflected', 'heb', 'אֲדָמָה', '["ʼădâmâh"]', '["land/ its"]', '["n-f"]', 'soil (from its general redness) country, earth, ground, husband(-man) (-ry), land.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0951}/[H1239]', 'lemma', 'heb', 'בּוֹקֵר', '["bôwqêr"]', '["[was] a herdsman"]', '["n-m"]', 'a cattle-tender herdman.', 'properly, active participle from 1239 as denominative from 1241;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1103}/[H1103]', 'inflected', 'heb', 'בָּלַס', '["bâlaç"]', '["and/ a fig picker of"]', '["v"]', 'to pinch sycamore figs (a process necessary to ripen them) gatherer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0127G}/H9021/[H119]', 'inflected', 'heb', 'אֲדָמָה', '["ʼădâmâh"]', '["and/ land/ your"]', '["n-f"]', 'soil (from its general redness) country, earth, ground, husband(-man) (-ry), land.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3619}/[H3611]', 'lemma', 'heb', 'כְּלוּב', '["kᵉlûwb"]', '["a basket of"]', '["n-m"]', 'a bird-trap (as furnished with a clap-stick or treadle to spring it); hence, a basket (as resembling a wicker cage) basket, cage.', 'from the same as 3611;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2013}\/[H2013]', 'inflected', 'heb', 'הָסָה', '["hâçâh"]', '["hush!"]', '["v"]', 'to hush hold peace (tongue), (keep) silence, be silent, still.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7673A}/[H7673]', 'inflected', 'heb', 'שָׁבַת', '["shâbath"]', '["and/ to/ put an end to"]', '["v"]', 'to repose, i.e. desist from exertion; used in many implied relations (causative, figurative or specific) (cause to, let, make to) cease, celebrate, cause (make) to fail, keep (sabbath), suffer to be lacking, leave, put away (down), (make to) rest, rid, still, take away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7676}/[H7673]', 'inflected', 'heb', 'שַׁבָּת', '["shabbâth"]', '["and/ the/ sabbath"]', '["n"]', 'intermission, i.e (specifically) the Sabbath ( every) sabbath.', 'intensive from 7673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6994}/[H6996]', 'inflected', 'heb', 'קָטֹן', '["qâṭôn"]', '["to/ make small"]', '["v"]', 'to diminish, i.e. be (causatively, make) diminutive or (figuratively) of no account be a (make) small (thing), be not worthy.', 'a primitive root (rather denominative from 6996);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1431}/[H1434]', 'inflected', 'heb', 'גָּדַל', '["gâdal"]', '["and/ to/ make great"]', '["v"]', 'to be (causatively make) large (in various senses, as in body, mind, estate or honor, also in pride) advance, boast, bring up, exceed, excellent, be(-come, do, give, make, wax), great(-er, come to... estate, things), grow(up), increase, lift up, magnify(-ifical), be much set by, nourish (up), pass, promote, proudly (spoken), tower.', 'a primitive root; properly, to twist (compare 1434), i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5791}/[H5791]', 'inflected', 'heb', 'עָוַת', '["ʻâvath"]', '["and/ to/ falsify"]', '["v"]', 'to wrest bow self, (make) crooked., falsifying, overthrow, deal perversely, pervert, subvert, turn upside down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4651}/[H5307]', 'inflected', 'heb', 'מַפָּל', '["mappâl"]', '["and/ refuse of"]', '["n-m"]', 'a falling off, i.e. chaff; also something pendulous, i.e. a flap flake, refuse.', 'from 5307;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0935K}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ I will cause to go","and/ it will go"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7892A}/H9026/[H7891]', 'inflected', 'heb', 'שִׁיר', '["shîyr"]', '["songs/ your"]', '["n-m n-f"]', 'a song; abstractly, singing musical(-ick), × sing(-er, -ing), song.', 'or feminine שִׁירָה; from 7891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7015}/[H6969]', 'inflected', 'heb', 'קִינָה', '["qîynâh"]', '["into/ lamentation"]', '["n-f"]', 'a dirge (as accompanied by beating the breasts or on instruments) lamentation.', 'from 6969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0060}/[H56]', 'inflected', 'heb', 'אֵבֶל', '["ʼêbel"]', '["like/ [the] mourning of"]', '["n-m"]', 'lamentation mourning.', 'from 56;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0970}/[H977]', 'inflected', 'heb', 'בָּחוּר', '["bâchûwr"]', '["and/ the/ young men"]', '["n-m"]', 'properly, selected, i.e. a youth (often collective) (choice) young (man), chosen, × hole.', 'or בָּחֻר; participle passive of 977;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3730>', 'inflected', 'heb', 'הכפתור', '["ha./kaf.Tor"]', '["the/ capital"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1214G}/H9038/[H1214]', 'inflected', 'heb', 'בָּצַע', '["bâtsaʻ"]', '["and/ break off/ them"]', '["v"]', 'to break off, i.e. (usually) plunder; figuratively, to finish, or (intransitively) stop (be) covet(-ous), cut (off), finish, fulfill, gain (greedily), get, be given to (covetousness), greedy, perform, be wounded.', 'a primitive root');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0319}/H9028/[H310]', 'inflected', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["and/ posterity/ their"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5391A}/H9038/[H5391]', 'inflected', 'heb', 'נָשַׁךְ', '["nâshak"]', '["and/ it will bite/ them"]', '["v"]', 'to strike with a sting (as a serpent); figuratively, to oppress with interest on a loan bite, lend upon usury.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4127}/[H4127]', 'inflected', 'heb', 'מוּג', '["mûwg"]', '["and/ it melted"]', '["v"]', 'to melt, i.e. literally (to soften, flow down, disappear), or figuratively (to fear, faint) consume, dissolve, (be) faint(-hearted), melt (away), make soft.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4609B}/H9023/[H4608]', 'inflected', 'heb', 'מַעֲלָה', '["maʻălâh"]', '["stairs/ his"]', '["n-f"]', 'elevation, i.e. the act (literally, a journey to a higher place, figuratively, a thought arising), or (concretely) the condition (literally, a step or grade-mark, figuratively, a superiority of station); specifically a climactic progression (in certain Psalms) things that come up, (high) degree, deal, go up, stair, step, story.', 'feminine of 4608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0092>/H9023', 'inflected', 'heb', 'ואגדתו', '["va./''a.gu.da.T/o"]', '["and/ vault/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1121G}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["like/ [the] sons of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7024B}/[H7023]', 'inflected', 'heb', 'קִיר', '["Qîyr"]', '["from/ Kir"]', '["n-pr-loc"]', 'Kir, a place in Assyrian; also one in Moab Kir. Compare 7025.', 'the same as 7023; fortress;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3531}/[H3527]', 'inflected', 'heb', 'כְּבָרָה', '["kᵉbârâh"]', '["in <the>/ sieve"]', '["n-f"]', 'a sieve (as netted) sieve.', 'from 3527 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6872B}/[H6887]', 'lemma', 'heb', 'צְרוֹר', '["tsᵉrôwr"]', '["a pebble"]', '["n-m"]', 'a parcel (as packed up); also a kernel or particle (as if a package) bag, × bendeth, bundle, least grain, small stone.', 'or (shorter) צְרֹר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6923}/[H6923]', 'inflected', 'heb', 'קָדַם', '["qâdam"]', '["and/ it may meet"]', '["v"]', 'to project (one self), i.e. precede; hence, to anticipate, hasten, meet (usually for help) come (go, (flee)) before, disappoint, meet, prevent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6556}/H9029/[H6555]', 'inflected', 'heb', 'פֶּרֶץ', '["perets"]', '["breaches/ their"]', '["n-m"]', 'a break (literally or figuratively) breach, breaking forth (in), × forth, gap.', 'from 6555;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2034}/H9023/[H2040]', 'inflected', 'heb', 'הֲרִיסָה', '["hărîyçâh"]', '["and/ ruins/ his"]', '["n-f"]', 'something demolished ruin.', 'from 2040;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1129}/H9034/[H1129]', 'inflected', 'heb', 'בָּנָה', '["bânâh"]', '["and/ I will rebuild/ it"]', '["v"]', 'to build (literally and figuratively) (begin to) build(-er), obtain children, make, repair, set (up), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7114B}/[H7114]', 'inflected', 'heb', 'קָצַר', '["qâtsar"]', '["<in> the/ reaper"]', '["v"]', 'to dock off, i.e. curtail (transitive or intransitive, literal or figurative); especially to harvest (grass or grain) × at all, cut down, much discouraged, grieve, harvestman, lothe, mourn, reap(-er), (be, wax) short(-en, -er), straiten, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5197}/[H5197]', 'inflected', 'heb', 'נָטַף', '["nâṭaph"]', '["and/ they will drip"]', '["v"]', 'to ooze, i.e. distil gradually; by implication, to fall in drops; figuratively, to speak by inspiration drop(-ping), prophesy(-et).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6071}/[H6072]', 'lemma', 'heb', 'עָסִיס', '["ʻâçîyç"]', '["sweet wine"]', '["n-m"]', 'must or fresh grape-juice (as just trodden out) juice, new (sweet) wine.', 'from 6072;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5662R}/[H5647]', 'lemma', 'heb', 'עֹבַדְיָה', '["ʻÔbadyâh"]', '["Obadiah"]', '["n-pr-m"]', 'Obadjah, the name of thirteen Israelites Obadiah.', 'or עֹבַדְיָהוּ; active participle of 5647 and 3050; serving Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6965J}/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["so/ let us arise"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7675}/H9023/[H3427]', 'inflected', 'heb', 'שֶׁבֶת', '["shebeth"]', '["dwelling/ his"]', '["n-f"]', 'properly, session; but used also concretely, an abode or locality place, seat. Compare 3429.', 'infinitive of 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3381}/H9030/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["will he bring down/ me"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4710}/H9023/[H6845]', 'inflected', 'heb', 'מִצְפֻּן', '["mitspun"]', '["hidden treasures/ its"]', '["n-m"]', 'a secret (place or thing, perhaps, treasure) hidden thing.', 'from 6845;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4204}/[H2114]', 'lemma', 'heb', 'מָזוֹר', '["mâzôwr"]', '["a trap"]', '["n-m"]', 'treachery, i.e. a plot wound.', 'from 2114 in the sense of turning aside from truth;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6215I}/[H6213]', 'lemma', 'heb', 'עֵשָׂו', '["ʻÊsâv"]', '["Esau"]', '["n-pr-m"]', 'Esav, a son of Isaac, including his posterity Esau.', 'apparently a form of the passive participle of 6213 in the original sense of handling; rough (i.e. sensibly felt);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6993}/[H6991]', 'inflected', 'heb', 'קֶטֶל', '["qeṭel"]', '["from/ slaughter"]', '["n-m"]', 'a violent death slaughter.', 'from 6991;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5975G}/H9041/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["standing/ you"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3032}/[H3034]', 'lemma', 'heb', 'יָדַד', '["yâdad"]', '["they cast"]', '["v"]', 'properly, to handle, i.e. to throw, e.g. lots cast.', 'a primitive root; (compare 3034)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5235}/H9023/[H5234]', 'inflected', 'heb', 'נֶכֶר', '["neker"]', '["misfortune/ his"]', '["n-m"]', 'something strange, i.e. unexpected calamity strange.', 'or נֹכֶר; from 5234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0006}/H9048/[H6]', 'inflected', 'heb', 'אָבַד', '["ʼâbad"]', '["perish/ they"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7451C}/H9023/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["on/ calamity/ his"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2428H}/H9023/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["on/ wealth/ his"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6563}/[H6561]', 'inflected', 'heb', 'פֶּרֶק', '["pereq"]', '["the/ parting of ways"]', '["n-m"]', 'rapine; also a fork (in roads) crossway, robbery.', 'from 6561;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6412A}/H9023/[H6403]', 'inflected', 'heb', 'פָּלִיט', '["pâlîyṭ"]', '["fugitives/ his"]', '["n-m"]', 'a refugee (that have) escape(-d, -th), fugitive.', 'or פָּלֵיט; or פָּלֵט; from 6403;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1576}/H9021/[H1580]', 'inflected', 'heb', 'גְּמוּל', '["gᵉmûwl"]', '["recompense/ your"]', '["n-m"]', 'treatment, i.e. an act (of good or ill); by implication, service or requital as hast served, benefit, desert, deserving, that which he hath given, recompense, reward.', 'from 1580;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3886A}/[H3886]', 'inflected', 'heb', 'לוּעַ', '["lûwaʻ"]', '["and/ they will swallow"]', '["v"]', 'to gulp; figuratively, to be rash swallow down (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3808}/[H3808]', 'inflected', 'heb', 'לֹא', '["lôʼ"]', '["like/ not"]', '["adv"]', 'not (the simple or abs. negation); by implication, no; often used with other particles × before, or else, ere, except, ig(-norant), much, less, nay, neither, never, no((-ne), -r, (-thing)), (× as though...,(can-), for) not (out of), of nought, otherwise, out of, surely, as truly as, of a truth, verily, for want, whether, without.', 'or לוֹא; or לֹה; (Deuteronomy 3:11), a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4180}/H9028/[H3423]', 'inflected', 'heb', 'מוֹרָשׁ', '["môwrâsh"]', '["possessions/ their"]', '["n-m"]', 'a possession; figuratively, delight possession, thought.', 'from 3423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1814}/[H1814]', 'inflected', 'heb', 'דָּלַק', '["dâlaq"]', '["and/ they will burn"]', '["v"]', 'to flame (literally or figuratively) burning, chase, inflame, kindle, persecute(-or), pursue hotly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1546}/[H1540]', 'inflected', 'heb', 'גָּלוּת', '["gâlûwth"]', '["and/ [the] exile[s] of"]', '["n-f"]', 'captivity; concretely, exiles (collectively) (they that are carried away) captives(-ity).', 'feminine from 1540;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2426}/[H2428]', 'inflected', 'heb', 'חֵיל', '["chêyl"]', '["the/ fortress"]', '["n-m"]', 'an army; also (by analogy,) an intrenchment army, bulwark, host, poor, rampart, trench, wall.', 'or (shortened) חֵל; a collateral form of 2428;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6886}/[H6884]', 'lemma', 'heb', 'צָרְפַת', '["Tsârᵉphath"]', '["Zarephath"]', '["n-pr-loc"]', 'Tsarephath, a place in Palestine Zarephath.', 'from 6884; refinement;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5614}/[H5614]', 'inflected', 'heb', 'סְפָרָד', '["Çᵉphârâd"]', '["[are] in/ Sepharad"]', '["n-pr-loc"]', 'Sepharad, a region of Assyria Sepharad.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7939}/H9024/[H7936]', 'inflected', 'heb', 'שָׂכָר', '["sâkâr"]', '["fare/ its"]', '["n-m"]', 'payment of contract; concretely, salary, fare, maintenance; by implication, compensation, benefit hire, price, reward(-ed), wages, worth.', 'from 7936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0591}/[H590]', 'inflected', 'heb', 'אֳנִיָּה', '["ʼŏnîyâh"]', '["and/ the/ ship"]', '["n-f"]', 'a ship ship(-men).', 'feminine of 590;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4419}/[H4414]', 'inflected', 'heb', 'מַלָּח', '["mallâch"]', '["the/ sailors"]', '["n-m"]', 'a sailor (as following ''the salt'') mariner.', 'from 4414 in its second. sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3124}/[H3123]', 'inflected', 'heb', 'יוֹנָה', '["Yôwnâh"]', '["and/ Jonah"]', '["n-pr-m"]', 'Jonah, an Israelite Jonah.', 'the same as 3123;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5600}/[H5603]', 'inflected', 'heb', 'סְפִינָה', '["çᵉphîynâh"]', '["the/ ship"]', '["n-f"]', 'a (sea-going) vessel (as ceiled with a deck) ship.', 'from 5603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7290}/[H7290]', 'inflected', 'heb', 'רָדַם', '["râdam"]', '["and/ he had fallen fast asleep"]', '["v"]', 'to stun, i.e. stupefy (with sleep or death) (be fast a-, be in a deep, cast into a dead, that) sleep(-er, -eth).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2259}/[H2254]', 'inflected', 'heb', 'חֹבֵל', '["chôbêl"]', '["the/ sailor[s]"]', '["n-m"]', 'a sailor pilot, shipmaster.', 'active participle from 2254 (in the sense of handling ropes);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6245B}/[H6245]', 'lemma', 'heb', 'עָשַׁת', '["ʻâshath"]', '["he will give thought"]', '["v"]', 'probably to be sleek, i.e. glossy; hence (through the idea of polishing) to excogitate (as if forming in the mind) shine, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5307I}/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["so/ let us cast"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/H9007/H9005/{H4310}/[H4100]', 'inflected', 'heb', 'מִי', '["mîy"]', '["by/ which/ of/ whom?"]', '["i"]', 'who? (occasionally, by a peculiar idiom, of things); also (indefinitely) whoever; often used in oblique construction with prefix or suffix any (man), × he, × him, O that! what, which, who(-m, -se, -soever), would to God.', 'an interrogative pronoun of persons, as 4100 is of things,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8367}/[H8367]', 'inflected', 'heb', 'שָׁתַק', '["shâthaq"]', '["so/ it may be calm"]', '["v"]', 'to subside be calm, cease, be quiet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5590}/[H5590]', 'inflected', 'heb', 'סָעַר', '["çâʻar"]', '["and/ storming"]', '["v"]', 'to rush upon; by implication, to toss (transitive or intransitive, literal or figurative) be (toss with) tempest(-uous), be sore, troubled, come out as a (drive with the, scatter with a) whirlwind.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2904}/H9030/[H2904]', 'inflected', 'heb', 'טוּל', '["ṭûwl"]', '["and/ throw/ me"]', '["v"]', 'to pitch over or reel; hence (transitively) to cast down or out carry away, (utterly) cast (down, forth, out), send out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/H9007/H9005/{H9030}', 'inflected', 'heb', 'בשלי', '["ve./she./L/i"]', '["by/ which/ to <the>/ me"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5591A}/[H5590]', 'inflected', 'heb', 'סַעַר', '["çaʻar"]', '["the/ storm"]', '["n-m"]', 'a hurricane storm(-y), tempest, whirlwind.', 'or (feminine) סְעָרָה; from 5590;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5355B}/[H5352]', 'lemma', 'heb', 'נָקִי', '["nâqîy"]', '["innocent"]', '["a"]', 'innocent blameless, clean, clear, exempted, free, guiltless, innocent, quit.', 'or נָקִיא; (Joel 4:19; Jonah 1:14), from 5352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2904}/H9033/[H2904]', 'inflected', 'heb', 'טוּל', '["ṭûwl"]', '["and/ they threw/ him"]', '["v"]', 'to pitch over or reel; hence (transitively) to cast down or out carry away, (utterly) cast (down, forth, out), send out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2197}/H9023/[H2196]', 'inflected', 'heb', 'זַעַף', '["zaʻaph"]', '["from/ storming/ its"]', '["n-m"]', 'anger indignation, rage(-ing), wrath.', 'from 2196;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1104}/[H1104]', 'inflected', 'heb', 'בָּלַע', '["bâlaʻ"]', '["to/ swallow"]', '["v"]', 'to make away with (specifically by swallowing); generally, to destroy cover, destroy, devour, eat up, be at end, spend up, swallow down (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H4578>', 'inflected', 'heb', 'במעי', '["bi/m.''Ei"]', '["in/ [the] inward parts of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H0990G>', 'inflected', 'heb', 'מבטן', '["mi./Be.ten"]', '["from/ [the] belly of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5027}/[H5027]', 'inflected', 'heb', 'נָבַט', '["nâbaṭ"]', '["to/ look"]', '["v"]', 'to scan, i.e. look intently at; by implication, to regard with pleasure, favor or care (cause to) behold, consider, look (down), regard, have respect, see.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5488H}/[H5488]', 'lemma', 'heb', 'סוּף', '["çûwph"]', '["rush[es]"]', '["n-m"]', 'a reed, especially the papyrus flag, Red (sea), weed. Compare 5489.', 'probably of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7095}/[H7094]', 'inflected', 'heb', 'קֶצֶב', '["qetseb"]', '["to/ extremities of"]', '["n-m"]', 'shape (as if cut out); base (as if there cut off) bottom, size.', 'from 7094;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2617A}/H9028/[H2616]', 'inflected', 'heb', 'חֶסֶד', '["cheçed"]', '["loyalty/ their"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1709H}/[H1711]', 'inflected', 'heb', 'דָּג', '["dâg"]', '["to the/ fish"]', '["n-m"]', 'a fish (often used collectively) fish.', 'or (fully) דָּאג; (Nehemiah 13:16), from 1711; a fish (as prolific); or perhaps rather from 1672 (as timid); but still better from 1672 (in the sense of squirming, i.e. moving by the vibratory action of the tail);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3004}\/[H3001]', 'inflected', 'heb', 'יַבָּשָׁה', '["yabbâshâh"]', '["the/ dry land"]', '["n-f"]', 'dry ground dry (ground, land).', 'from 3001;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7150}/[H7121]', 'inflected', 'heb', 'קְרִיאָה', '["qᵉrîyʼâh"]', '["the/ proclamation"]', '["n-f"]', 'a proclamation preaching.', 'from 7121;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5210>', 'inflected', 'heb', 'ונינוה', '["ve./ni.ne.Veh"]', '["and/ Nineveh"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1419A}/H9028/[H1431]', 'inflected', 'heb', 'גָּדוֹל', '["gâdôwl"]', '["from/ great/ their"]', '["a n-pr-m"]', 'great (in any sense); hence, older; also insolent aloud, elder(-est), exceeding(-ly), far, (man of) great (man, matter, thing,-er,-ness), high, long, loud, mighty, more, much, noble, proud thing, × sore, (×) very.', 'or גָּדֹל; (shortened) from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6996A}/H9028/[H6962]', 'inflected', 'heb', 'קָטָן', '["qâṭân"]', '["insignificant/ their"]', '["a"]', 'abbreviated, i.e. diminutive, literally (in quantity, size or number) or figuratively (in age or importance) least, less(-er), little (one), small(-est, one, quantity, thing), young(-er, -est).', 'or קָטֹן; from 6962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3678G}/H9023/[H3680]', 'inflected', 'heb', 'כִּסֵּא', '["kiççêʼ"]', '["from/ throne/ his"]', '["n-m"]', 'properly, covered, i.e. a throne (as canopied) seat, stool, throne.', 'or כִּסֵּה; from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2940}/[H2938]', 'inflected', 'heb', 'טַעַם', '["ṭaʻam"]', '["from/ [the] decree of"]', '["n-m"]', 'properly, a taste, i.e. (figuratively) perception; by implication, intelligence; transitively, a mandate advice, behaviour, decree, discretion, judgment, reason, taste, understanding.', 'from 2938;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1419A}/H9023/[H1431]', 'inflected', 'heb', 'גָּדוֹל', '["gâdôwl"]', '["and/ great [people]/ his"]', '["a n-pr-m"]', 'great (in any sense); hence, older; also insolent aloud, elder(-est), exceeding(-ly), far, (man of) great (man, matter, thing,-er,-ness), high, long, loud, mighty, more, much, noble, proud thing, × sore, (×) very.', 'or גָּדֹל; (shortened) from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1961}/H9040/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["was/ I"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0127H}/H9020/[H119]', 'inflected', 'heb', 'אֲדָמָה', '["ʼădâmâh"]', '["own land/ my"]', '["n-f"]', 'soil (from its general redness) country, earth, ground, husband(-man) (-ry), land.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2416E}/H9020\/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["more than/ life/ my"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7021}/[H7006]', 'lemma', 'heb', 'קִיקָיוֹן', '["qîyqâyôwn"]', '["a plant"]', '["n-m"]', 'the gourd (as nauseous) gourd.', 'perhaps from 7006;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3124}/[H3123]', 'inflected', 'heb', 'יוֹנָה', '["Yôwnâh"]', '["<to>/ Jonah"]', '["n-pr-m"]', 'Jonah, an Israelite Jonah.', 'the same as 3123;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7451C}/H9023/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["from/ distress/ his"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7021}/[H7006]', 'inflected', 'heb', 'קִיקָיוֹן', '["qîyqâyôwn"]', '["the/ plant"]', '["n-m"]', 'the gourd (as nauseous) gourd.', 'perhaps from 7006;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2759}/[H2790]', 'lemma', 'heb', 'חֲרִישִׁי', '["chărîyshîy"]', '["hot"]', '["a"]', 'quiet, i.e. sultry (as feminine noun, the sirocco or hot east wind) vehement.', 'from 2790 in the sense of silence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2416E}/H9020/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["more than/ life/ my"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H1121I}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["that/ a son of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6010R}/[H6009]', 'inflected', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["and/ the/ valleys"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2403B}/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["and/ for/ [the] sins of"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4302}/[H5193]', 'inflected', 'heb', 'מַטָּע', '["maṭṭâʻ"]', '["into/ a planting place of"]', '["n-m"]', 'something planted, i.e. the place (a garden or vineyard), or the thing (a plant, figuratively or men); by implication, the act, planting plant(-ation, -ing).', 'from 5193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1516R}/[H1466]', 'inflected', 'heb', 'גַּיְא', '["gayʼ"]', '["to the/ valley"]', '["n"]', 'a gorge (from its lofty sides; hence, narrow, but not a gully or winter-torrent) valley.', 'or (shortened) גַּי; probably (by transmutation) from the same root as 1466 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3247H}/H9024/[H3245]', 'inflected', 'heb', 'יְסוֹד', '["yᵉçôwd"]', '["and/ foundations/ its"]', '["n-f"]', 'a foundation (literally or figuratively) bottom, foundation, repairing', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0868}/H9024/[H866]', 'inflected', 'heb', 'אֶתְנַן', '["ʼethnan"]', '["hire<s>/ its"]', '["n-m"]', 'a gift (as the price of harlotry or idolatry) hire, reward.', 'the same as 866;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0868}/[H866]', 'inflected', 'heb', 'אֶתְנַן', '["ʼethnan"]', '["from/ [the] hire of"]', '["n-m"]', 'a gift (as the price of harlotry or idolatry) hire, reward.', 'the same as 866;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0060}/[H56]', 'inflected', 'heb', 'אֵבֶל', '["ʼêbel"]', '["and/ a mourning"]', '["n-m"]', 'lamentation mourning.', 'from 56;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1036}/[H1004]', 'inflected', 'heb', 'בֵּית לְעַפְרָה', '["Bêyth lᵉ-ʻAphrâh"]', '["in/ Beth"]', '["n-pr-loc"]', 'Beth-le-Aphrah, a place in Palestine house of Aphrah.', 'from 1004 and the feminine of 6083 (with preposition interposed); house to (i.e. of) dust;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1036}/[H1004]', 'lemma', 'heb', 'בֵּית לְעַפְרָה', '["Bêyth lᵉ-ʻAphrâh"]', '["Leaphrah"]', '["n-pr-loc"]', 'Beth-le-Aphrah, a place in Palestine house of Aphrah.', 'from 1004 and the feminine of 6083 (with preposition interposed); house to (i.e. of) dust;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8208}/[H8231]', 'lemma', 'heb', 'שָׁפִיר', '["Shâphîyr"]', '["Shaphir"]', '["n-pr-loc"]', 'Shaphir, a place in Palestine Saphir.', 'from 8231; beautiful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6181}/[H6172]', 'lemma', 'heb', 'עֶרְיָה', '["ʻeryâh"]', '["bareness","nakedness"]', '["n-f"]', 'nudity bare, naked, × quite.', 'for 6172;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6630}/[H6629]', 'lemma', 'heb', 'צַאֲנָן', '["Tsaʼănân"]', '["Zaanan"]', '["n-pr-loc"]', 'Zaanan, a place in Palestine Zaanan.', 'from the same as 6629 used denominatively; sheep pasture;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1018}/[H1004]', 'lemma', 'heb', 'בֵּית הָאֵצֶל', '["Bêyth hâʼêtsel"]', '["Beth","Ezel"]', '["n-pr-loc"]', 'Beth-ha-Etsel, a place in Palestine Beth-ezel.', 'from 1004 and 681 with the article interposed; house of the side;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5979}/H9023/[H5975]', 'inflected', 'heb', 'עֶמְדָּה', '["ʻemdâh"]', '["standing ground/ its"]', '["n-f"]', 'a station, i.e. domicile standing.', 'from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2342K}/[H2342]', 'lemma', 'heb', 'חוּל', '["chûwl"]', '["she is in anguish"]', '["v"]', 'properly, to twist or whirl (in a circular or spiral manner), i.e. (specifically) to dance, to writhe in pain (especially of parturition) or fear; figuratively, to wait, to pervert bear, (make to) bring forth, (make to) calve, dance, drive away, fall grievously (with pain), fear, form, great, grieve, (be) grievous, hope, look, make, be in pain, be much (sore) pained, rest, shake, shapen, (be) sorrow(-ful), stay, tarry, travail (with pain), tremble, trust, wait carefully (patiently), be wounded.', 'or חִיל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4796}/[H4751]', 'lemma', 'heb', 'מָרוֹת', '["Mârôwth"]', '["Maroth"]', '["n-pr-f"]', 'Maroth, a place in Palestine Maroth.', 'plural of 4751 feminine; bitter springs;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7573}/[H7573]', 'lemma', 'heb', 'רָתַם', '["râtham"]', '["harness"]', '["v"]', 'to yoke up (to the pole of a vehicle) bind.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7409}/[H7408]', 'inflected', 'heb', 'רֶכֶשׁ', '["rekesh"]', '["to the/ steed"]', '["n-m"]', 'a relay of animals on a post-route (as stored up for that purpose); by implication, a courser dromedary, mule, swift beast.', 'from 7408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4182}/[H3423]', 'lemma', 'heb', 'מוֹרֶשֶׁת גַּת', '["Môwresheth Gath"]', '["Gath","Moresheth"]', '["n-pr-loc"]', 'Moresheth-Gath, a place in Palestine Moresheth-gath.', 'from 3423 and 1661; possession of Gath;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0392G}/[H391]', 'lemma', 'heb', 'אַכְזִיב', '["ʼAkzîyb"]', '["Aczib"]', '["n-pr-loc"]', 'Akzib, the name of two places in Palestine Achzib.', 'from 391; deceitful (in the sense of a winter-torrent which fails in summer);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0391}/[H3576]', 'inflected', 'heb', 'אַכְזָב', '["ʼakzâb"]', '["[will become] <into>/ a deceitful thing"]', '["a"]', 'falsehood; by implication treachery liar, lie.', 'from 3576;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3423H}/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["the/ [one who] dispossesses"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1494}/[H1468]', 'inflected', 'heb', 'גָּזַז', '["gazâz"]', '["and/ shear"]', '["v"]', 'to cut off; specifically to shear a flock or shave the hair; figuratively to destroy an enemy cut off (down), poll, shave, (sheep-) shear(-er).', 'a primitive root (akin to 1468);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8588}/H9022/[H6026]', 'inflected', 'heb', 'תַּעֲנוּג', '["taʻănûwg"]', '["delights/ your"]', '["n-m"]', 'luxury delicate, delight, pleasant.', 'or תַּעֲנֻג; and (feminine) תַּעֲנֻגָה; from 6026;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7144}/H9022/[H7139]', 'inflected', 'heb', 'קׇרְחָה', '["qorchâh"]', '["baldness/ your"]', '["n-f"]', 'baldness bald(-ness), × utterly.', 'or קׇרְחָא; (Ezekiel 27:31), from 7139;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4480A}/H9032\/[H4482]', 'inflected', 'heb', 'מִן', '["min"]', '["from/ you"]', '["prep"]', 'properly, a part of; hence (prepositionally), from or out of in many senses above, after, among, at, because of, by (reason of), from (among), in, × neither, × nor, (out) of, over, since, × then, through, × whether, with.', 'or מִנִּי; or מִנֵּי; (constructive plural) (Isaiah 30:11); for 4482;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2530A}/[H2530]', 'inflected', 'heb', 'חָמַד', '["châmad"]', '["and/ they desire"]', '["v"]', 'to delight in beauty, greatly beloved, covet, delectable thing, (× great) delight, desire, goodly, lust, (be) pleasant (thing), precious (thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6231}/[H6229]', 'inflected', 'heb', 'עָשַׁק', '["ʻâshaq"]', '["and/ they oppress"]', '["v"]', 'to press upon, i.e. oppress, defraud, violate, overflow get deceitfully, deceive, defraud, drink up, (use) oppress(-ion), -or), do violence (wrong).', 'a primitive root (compare 6229);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5159}/H9023\/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["and/ inheritance/ his"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7317}/[H7315]', 'lemma', 'heb', 'רוֹמָה', '["rôwmâh"]', '["haughtily"]', '["a"]', 'elation, i.e. (adverbially) proudly haughtily.', 'feminine of 7315;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7728}/[H7725]', 'inflected', 'heb', 'שׁוֹבֵב', '["shôwbêb"]', '["to/ an apostate"]', '["a"]', 'apostate, i.e. heathenish or (actually) heathen backsliding.', 'from 7725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5197}/H9013/[H5197]', 'inflected', 'heb', 'נָטַף', '["nâṭaph"]', '["they prophesy/ !"]', '["v"]', 'to ooze, i.e. distil gradually; by implication, to fall in drops; figuratively, to speak by inspiration drop(-ping), prophesy(-et).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0865}/[H853]', 'inflected', 'heb', 'אֶתְמוֹל', '["ʼethmôwl"]', '["and/ yesterday"]', '["adv"]', 'heretofore; definitely yesterday before (that) time, heretofore, of late (old), times past, yester(day).', 'or אִתְמוֹל; or אֶתְמוּל; probably from 853 or 854 and 4136;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0145}/[H142]', 'lemma', 'heb', 'אֶדֶר', '["ʼeder"]', '["[the] magnificence of","a mantle"]', '["n"]', 'amplitude, i.e. (concrete) a mantle; also (figuratively) splendor goodly, robe.', 'from 142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6584}/H9013/[H6584]', 'inflected', 'heb', 'פָּשַׁט', '["pâshaṭ"]', '["you strip off/ !"]', '["v"]', 'to spread out (i.e. deploy in hostile array); by analogy, to strip (i.e. unclothe, plunder, flay, etc.) fall upon, flay, invade, make an invasion, pull off, put off, make a road, run upon, rush, set, spoil, spread selves (abroad), strip (off, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1644H}/H9013/[H1644]', 'inflected', 'heb', 'גָּרַשׁ', '["gârash"]', '["you drive out/ !"]', '["v"]', 'to drive out from a possession; especially to expatriate or divorce cast up (out), divorced (woman), drive away (forth, out), expel, × surely put away, trouble, thrust out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8588}/H9024/[H6026]', 'inflected', 'heb', 'תַּעֲנוּג', '["taʻănûwg"]', '["delights/ her"]', '["n-m"]', 'luxury delicate, delight, pleasant.', 'or תַּעֲנֻג; and (feminine) תַּעֲנֻגָה; from 6026;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1926}/H9020/[H1921]', 'inflected', 'heb', 'הָדָר', '["hâdâr"]', '["glory/ my"]', '["n-m"]', 'magnificence, i.e. ornament or splendor beauty, comeliness, excellency, glorious, glory, goodly, honour, majesty.', 'from 1921;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2256D}/[H2254]', 'inflected', 'heb', 'חֶבֶל', '["chebel"]', '["and/ [the] destruction"]', '["n-m"]', 'a rope (as twisted), especially a measuring line; by implication, a district or inheritance (as measured); or a noose (as of cords); figuratively, a company (as if tied together); a throe (especially of parturition); also ruin band, coast, company, cord, country, destruction, line, lot, pain, pang, portion, region, rope, snare, sorrow, tackling.', 'or חֵבֶל; from 2254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8267}/[H8266]', 'inflected', 'heb', 'שֶׁקֶר', '["sheqer"]', '["and/ falsehood"]', '["n-m"]', 'an untruth; by implication, a sham (often adverbial) without a cause, deceit(-ful), false(-hood, -ly), feignedly, liar, lie, lying, vain (thing), wrongfully.', 'from 8266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3196>', 'inflected', 'heb', 'ליין', '["la/i.Ya.yin"]', '["of <the>/ wine"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7941}/[H7937]', 'inflected', 'heb', 'שֵׁכָר', '["shêkâr"]', '["and/ of <the>/ strong drink"]', '["n-m"]', 'an intoxicant, i.e. intensely alcoholic liquor strong drink, drunkard, strong wine.', 'from 7937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3605}/H9031/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["all of/ you"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1223}/[H1219]', 'lemma', 'heb', 'בׇּצְרָה', '["botsrâh"]', '["a sheepfold"]', '["n-f"]', 'an enclosure, i.e. sheep fold Bozrah.', 'feminine from 1219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1699A}/H9023/[H1696]', 'inflected', 'heb', 'דֹּבֶר', '["dôber"]', '["<the>/ pasture/ its"]', '["n-m"]', 'a pasture (from its arrangement of the flock) fold, manner.', 'from 1696 (in its original sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1949}/[H2000]', 'lemma', 'heb', 'הוּם', '["hûwm"]', '["they will be distraught"]', '["v"]', 'to make an uproar, or agitate greatly destroy, move, make a noise, put, ring again.', 'a primitive root (compare 2000);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7218I>/H9028\', 'inflected', 'heb', 'בראשם פ', '["be./ro.Sha/m"]', '["[will be] at/ head/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7101}/[H7096]', 'inflected', 'heb', 'קָצִין', '["qâtsîyn"]', '["and/ O rulers of"]', '["n-m"]', 'a magistrate (as deciding) or other leader captain, guide, prince, ruler. Compare 6278.', 'from 7096 in the sense of determining;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7607}/H9028/[H7604]', 'inflected', 'heb', 'שְׁאֵר', '["shᵉʼêr"]', '["and/ flesh/ their"]', '["n-m"]', 'flesh (as swelling out), as living or for food; generally food of any kind; figuratively, kindred by blood body, flesh, food, (near) kin(-sman, -swoman), near (nigh) (of kin).', 'from 7604;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5785}/H9028/[H5783]', 'inflected', 'heb', 'עוֹר', '["ʻôwr"]', '["and/ skin/ their"]', '["n-m"]', 'skin (as naked); by implication, hide, leather hide, leather, skin.', 'from 5783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H1320}/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["and/ like/ meat"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7037}/[H6747]', 'lemma', 'heb', 'קַלַּחַת', '["qallachath"]', '["a caldron"]', '["n-f"]', 'a kettle caldron.', 'apparently but a form for 6747;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8582}/[H8582]', 'inflected', 'heb', 'תָּעָה', '["tâʻâh"]', '["who/ mislead"]', '["v"]', 'to vacillate, i.e. reel or stray (literally or figuratively); also causative of both (cause to) go astray, deceive, dissemble, (cause to, make to) err, pant, seduce, (make to) stagger, (cause to) wander, be out of the way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8127G}/H9028/[H8150]', 'inflected', 'heb', 'שֵׁן', '["shên"]', '["with/ teeth/ their"]', '["n-f"]', 'a tooth (as sharp); specifically ivory; figuratively, a cliff crag, × forefront, ivory, × sharp, tooth.', 'from 8150; compare 8143');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2377}/[H2372]', 'inflected', 'heb', 'חָזוֹן', '["châzôwn"]', '["from/ vision"]', '["n-m"]', 'a sight (mentally), i.e. a dream, revelation, or oracle vision.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7080}/[H7080]', 'inflected', 'heb', 'קָסַם', '["qâçam"]', '["from/ divining"]', '["v"]', 'properly, to distribute, i.e. determine by lot or magical scroll; by implication, to divine divine(-r, -ation), prudent, soothsayer, use (divination).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2403B}/H9023\/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["sin/ its"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8581}/[H8581]', 'inflected', 'heb', 'תַּעָב', '["taʻâb"]', '["who/ loathe"]', '["v"]', 'to loathe, i.e. (morally) detest (make to be) abhor(-red), (be, commit more, do) abominable(-y), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3477I}/[H3474]', 'inflected', 'heb', 'יָשָׁר', '["yâshâr"]', '["<the>/ straight [thing]"]', '["a"]', 'straight (literally or figuratively) convenient, equity, Jasher, just, meet(-est), pleased well right(-eous), straight, (most) upright(-ly, -ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218H>/H9024', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["chiefs/ its"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3293A>\', 'opaque', 'heb', 'יַעַר', '["yaʻar"]', '["a forest"]', '["n-m"]', 'a copse of bushes; hence, a forest; hence, honey in the comb (as hived in trees) (honey-) comb, forest, wood.', 'from an unused root probably meaning to thicken with verdure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6760}/[H6763]', 'inflected', 'heb', 'צָלַע', '["tsâlaʻ"]', '["the/ [one who is] lame","the/ [one who was] lame","the/ lame [person]"]', '["v"]', 'to limp (as if one-sided) halt.', 'a primitive root; probably to curve; used only as denominative from 6763,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1972}/[H1973]', 'inflected', 'heb', 'הָלָא', '["hâlâʼ"]', '["and/ the/ [one who was] straying"]', '["v"]', 'to remove or be remote cast far off.', 'probably denominatively from 1973;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4475}/[H4474]', 'inflected', 'heb', 'מֶמְשָׁלָה', '["memshâlâh"]', '["the/ dominion"]', '["n-f"]', 'rule; also (concretely in plural) a realm or a ruler dominion, government, power, to rule.', 'feminine of 4474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7452}/[H7321]', 'lemma', 'heb', 'רֵעַ', '["rêaʻ"]', '["shouting"]', '["n"]', 'a crash (of thunder), noise (of war), shout (of joy) × aloud, noise, shouted.', 'from 7321;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H4428G}/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["¿/ a king"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2388H}/H9032/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["it has taken hold of/ you"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1518}/[H1518]', 'inflected', 'heb', 'גִּיחַ', '["gîyach"]', '["and/ burst forth"]', '["v"]', 'to gush forth (as water), generally to issue break forth, labor to bring forth, come forth, draw up, take out.', 'or (shortened) גֹּחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5995}/[H6014]', 'inflected', 'heb', 'עָמִיר', '["ʻâmîyr"]', '["like <the>/ cut grain"]', '["n-m"]', 'a bunch of grain handful, sheaf.', 'from 6014;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1637>/H9011', 'opaque', 'heb', 'גֹּרֶן', '["gôren"]', '["[the] threshing floor/ towards"]', '["n-m"]', 'a threshing-floor (as made even); by analogy, any open area (barn, corn, threshing-) floor, (threshing-, void) place.', 'from an unused root meaning to smooth;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1758}/[H1758]', 'inflected', 'heb', 'דּוּשׁ', '["dûwsh"]', '["and/ thresh"]', '["v"]', 'to trample or thresh break, tear, thresh, tread out (down), at grass (Jeremiah 50:11, by mistake for 1877).', 'or דּוֹשׁ; or דִּישׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7161A}/H9022/[H7160]', 'inflected', 'heb', 'קֶרֶן', '["qeren"]', '["horn/ your"]', '["n-f n-pr-loc"]', 'a horn (as projecting); by implication, a flask, cornet; by resemblance. an elephant''s tooth (i.e. ivory), a corner (of the altar), a peak (of a mountain), a ray (of light); figuratively, power × hill, horn.', 'from 7160;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6541}/H9022/[H6538]', 'inflected', 'heb', 'פַּרְסָה', '["parçâh"]', '["and/ hooves/ your"]', '["n-f"]', 'a claw or split hoof claw, (cloven-) footed, hoof.', 'feminine of 6538;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2428H}/H9028/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["and/ wealth/ their"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0505H}/[H504]', 'inflected', 'heb', 'אֶלֶף', '["ʼeleph"]', '["among/ [the] families of"]', '["n-m"]', 'hence (the ox''s head being the first letter of the alphabet, and this eventually used as a numeral) a thousand thousand.', 'prop, the same as 504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4163}/H9023/[H4161]', 'inflected', 'heb', 'מוֹצָאָה', '["môwtsâʼâh"]', '["and/ origins/ his"]', '["n-f"]', 'a family descent; also a sewer draught house; going forth.', 'feminine of 4161; (marg.; compare 6675)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6607}/H9024/[H6605]', 'inflected', 'heb', 'פֶּתַח', '["pethach"]', '["at/ entrances/ its"]', '["n-m"]', 'an opening (literally), i.e. door (gate) or entrance way door, entering (in), entrance (-ry), gate, opening, place.', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1366G}/H9025\/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["in/ territory/ our"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5483M>/H9021', 'opaque', 'heb', 'סוּס', '["çûwç"]', '["horses/ your"]', '["n-m"]', 'a horse (as leaping); also a swallow (from its rapid flight) crane, horse (-back, -hoof). Compare 6571.', 'or סֻס; from an unused root meaning to skip (properly, for joy);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4818}/H9021/[H4817]', 'inflected', 'heb', 'מֶרְכָּבָה', '["merkâbâh"]', '["chariots/ your"]', '["n-f"]', 'a chariot chariot. See also 1024.', 'feminine of 4817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3785}/[H3784]', 'lemma', 'heb', 'כֶּשֶׁף', '["kesheph"]', '["sorceries"]', '["n-m"]', 'magic sorcery, witchcraft.', 'from 3784;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6456}/H9021/[H6458]', 'inflected', 'heb', 'פְּסִיל', '["pᵉçîyl"]', '["images/ your"]', '["n-m"]', 'an idol carved (graven) image, quarry.', 'from 6458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4676}/H9021/[H5324]', 'inflected', 'heb', 'מַצֵּבָה', '["matstsêbâh"]', '["and/ sacred pillars/ your"]', '["n-f"]', 'something stationed, i.e. a column or (memorial stone); by analogy, an idol garrison, (standing) image, pillar.', 'feminine (causatively) participle of 5324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0842}/H9021/[H833]', 'inflected', 'heb', 'אֲשֵׁרָה', '["ʼăshêrâh"]', '["Asherah poles/ your"]', '["n-pr-f"]', 'Asherah (or Astarte) a Phoenician goddess; also an image of the same grove. Compare 6253.', 'or אֲשֵׁירָה; from 833; happy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8085H}\/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["they have obeyed"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H0386>', 'inflected', 'heb', 'והאתנים', '["ve./ha./''e.ta.Nim"]', '["and/ O/ enduring [ones]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3811}/H9031/[H3811]', 'inflected', 'heb', 'לָאָה', '["lâʼâh"]', '["have I made weary/ you"]', '["v"]', 'to tire; (figuratively) to be (or make) disgusted faint, grieve, lothe, (be, make) weary (selves).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1004B}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ from/ a house of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H6923}/H9033/[H6923]', 'inflected', 'heb', 'קָדַם', '["qâdam"]', '["¿/ will I come to meet/ him"]', '["v"]', 'to project (one self), i.e. precede; hence, to anticipate, hasten, meet (usually for help) come (go, (flee)) before, disappoint, meet, prevent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7521}/[H7521]', 'inflected', 'heb', 'רָצָה', '["râtsâh"]', '["¿/ will I accept","¿/ will he take pleasure"]', '["v"]', 'to be pleased with; specifically, to satisfy a debt (be) accept(-able), accomplish, set affection, approve, consent with, delight (self), enjoy, (be, have a) favour(-able), like, observe, pardon, (be, have, take) please(-ure), reconcile self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7233}/[H7231]', 'inflected', 'heb', 'רְבָבָה', '["rᵉbâbâh"]', '["in/ tens of thousands of"]', '["n-f"]', 'abundance (in number), i.e. (specifically) a myriad (whether definite or indefinite) many, million, × multiply, ten thousand.', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6800A}/[H6800]', 'inflected', 'heb', 'צָנַע', '["tsânaʻ"]', '["and/ to be modest"]', '["v"]', 'to humiliate humbly, lowly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0786}/[H784]', 'inflected', 'heb', 'אִשׁ', '["ʼish"]', '["¿/ [are] there"]', '["adv"]', 'entity, used only adverbially, there is or are are there, none can. Compare 3426.', 'identical (in origin and formation) with 784;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H2135}/[H2141]', 'inflected', 'heb', 'זָכָה', '["zâkâh"]', '["¿/ will I be clear"]', '["v"]', 'to be translucent; figuratively, to be innocent be (make) clean, cleanse, be clear, count pure.', 'a primitive root (compare 2141);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3599}/[H3563]', 'inflected', 'heb', 'כִּיס', '["kîyç"]', '["and/ with/ a bag of"]', '["n-m"]', 'a cup; also a bag for money or weights bag, cup, purse.', 'a form for 3563;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6223}/H9024/[H6238]', 'inflected', 'heb', 'עָשִׁיר', '["ʻâshîyr"]', '["rich [people]/ its"]', '["n-m"]', 'rich, whether literal or figurative (noble) rich (man).', 'from 6238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3445>/H9021', 'inflected', 'heb', 'וישחך', '["ve./yesh.cha./Kha"]', '["and/ emptiness/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414I}/H9040/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["to make/ I"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375H}\/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["you will bear"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0625}/[H622]', 'inflected', 'heb', 'אֹסֶף', '["ʼôçeph"]', '["like/ gathering<s> of"]', '["n-m"]', 'a collection (of fruits) gathering.', 'from 622;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1063}/[H1061]', 'lemma', 'heb', 'בִּכּוּרָה', '["bikkûwrâh"]', '["early fig[s]"]', '["n-f"]', 'the early fig firstripe (fruit).', 'feminine of 1061;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7966}/[H7999]', 'inflected', 'heb', 'שִׁלּוּם', '["shillûwm"]', '["for <the>/ bribe"]', '["n-m"]', 'a requital, i.e. (secure) retribution, (venal) a fee recompense, reward.', 'or שִׁלֻּם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5686}/H9034/[H5686]', 'inflected', 'heb', 'עָבַת', '["ʻâbath"]', '["and/ they weave/ it"]', '["v"]', 'to interlace, i.e. (figuratively) to pervert wrap up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2896A}/H9028/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["good person/ their"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H2312>', 'inflected', 'heb', 'כחדק', '["ke./Che.dek"]', '["[is] like/ a thorn-bush"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4534}/[H4881]', 'inflected', 'heb', 'מְסוּכָה', '["mᵉçûwkâh"]', '["more than/ a thorn hedge"]', '["n-f"]', 'a hedge thorn hedge.', 'for 4881;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6822}/H9031/[H6822]', 'inflected', 'heb', 'צָפָה', '["tsâphâh"]', '["watchmen/ your"]', '["v"]', 'properly, to lean forward, i.e. to peer into the distance; by implication, to observe, await behold, espy, look up (well), wait for, (keep the) watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6486}/H9021/[H6485]', 'inflected', 'heb', 'פְּקֻדָּה', '["pᵉquddâh"]', '["punishment/ your"]', '["n-f"]', 'visitation (in many senses, chiefly official) account, (that have the) charge, custody, that which...laid up, numbers, office(-r), ordering, oversight, prison, reckoning, visitation.', 'feminine passive participle of 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3998}/H9028/[H943]', 'inflected', 'heb', 'מְבוּכָה', '["mᵉbûwkâh"]', '["confusion/ their"]', '["n-f"]', 'perplexity perplexity.', 'from 943;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7453}/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["in/ a neighbor"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0441A}/[H502]', 'inflected', 'heb', 'אַלּוּף', '["ʼallûwph"]', '["in/ a close friend"]', '["a-m"]', 'familiar; a friend, also gentle; hence, a bullock (as being tame; applied, although masculine, to a cow); and so, a chieftain (as notable, like neat cattle) captain, duke, (chief) friend, governor, guide, ox.', 'or (shortened) אַלֻּף; from 502;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7901G}/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["from/ [she who] lies of"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0517}/H9024/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["on/ mother/ her"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3618H}/[H3634]', 'lemma', 'heb', 'כַּלָּה', '["kallâh"]', '["a daughter-in-law"]', '["n-f"]', 'a bride (as if perfect); hence, a son''s wife bride, daughter-in-law, spouse.', 'from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2545}/H9024/[H2524]', 'inflected', 'heb', 'חֲמוֹת', '["chămôwth"]', '["on/ mother-in-law/ her"]', '["n-f"]', 'a mother-in-law mother in law.', 'or (shortened) חֲמֹת; feminine of 2524;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3680}/H9034/[H3680]', 'inflected', 'heb', 'כָּסָה', '["kâçâh"]', '["and/ it will cover/ her"]', '["v"]', 'properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1447}/H9022/[H1443]', 'inflected', 'heb', 'גָּדֵר', '["gâdêr"]', '["walls/ your"]', '["n-m"]', 'a circumvallation; by implication, an inclosure fence, hedge, wall.', 'from 1443;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5704}/H9031/[H5703]', 'inflected', 'heb', 'עַד', '["ʻad"]', '["and/ to/ you"]', '["prep"]', 'as far (or long, or much) as, whether of space (even unto) or time (during, while, until) or degree (equally with) against, and, as, at, before, by (that), even (to), for(-asmuch as), (hither-) to, how long, into, as long (much) as, (so) that, till, toward, until, when, while, ( as) yet.', 'properly, the same as 5703 (used as a preposition, adverb or conjunction; especially with a preposition);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7626G>/H9021', 'inflected', 'heb', 'בשבטך', '["ve./shiv.Te./kha"]', '["with/ rod/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2119A}/[H2119]', 'inflected', 'heb', 'זָחַל', '["zâchal"]', '["like/ [things which] crawl of"]', '["v"]', 'to crawl; by implication, to fear be afraid, serpent, worm.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7355}/H9035/[H7355]', 'inflected', 'heb', 'רָחַם', '["râcham"]', '["he will have compassion on/ us"]', '["v"]', 'to fondle; by implication, to love, especially to compassionate have compassion (on, upon), love, (find, have, obtain, shew) mercy(-iful, on, upon), (have) pity, Ruhamah, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2265}/[H2263]', 'lemma', 'heb', 'חֲבַקּוּק', '["Chăbaqqûwq"]', '["Habakkuk"]', '["n-pr-m"]', 'Chabakkuk, the prophet Habakkuk.', 'by reduplication from 2263; embrace;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4066}/[H1777]', 'inflected', 'heb', 'מָדוֹן', '["mâdôwn"]', '["and/ contention"]', '["n-m"]', 'a contest or quarrel brawling, contention(-ous), discord, strife. Compare 4079, 4090.', 'from 1777;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6127}/[H6127]', 'lemma', 'heb', 'עָקַל', '["ʻâqal"]', '["perverted"]', '["v"]', 'to wrest wrong.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4116A}/[H4116]', 'inflected', 'heb', 'מָהַר', '["mâhar"]', '["and/ <the>/ impetuous"]', '["v"]', 'properly, to be liquid or flow easily, i.e. (by implication); to hurry (in a good or a bad sense); often used (with another verb) adverbially, promptly be carried headlong, fearful, (cause to make, in, make) haste(-n, -ily), (be) hasty, (fetch, make ready) × quickly, rash, × shortly, (be so) × soon, make speed, × speedily, × straightway, × suddenly, swift.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4941H}/H9023/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["judgment/ his","justice/ its"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7613}/H9023/[H5375]', 'inflected', 'heb', 'שְׂאֵת', '["sᵉʼêth"]', '["and/ dignity/ its"]', '["n-f"]', 'an elevation or leprous scab; figuratively, elation or cheerfulness; exaltation in rank or character be accepted, dignity, excellency, highness, raise up self, rising.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H5246>', 'inflected', 'heb', 'מנמרים', '["mi./ne.me.Rim"]', '["more than/ leopards"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2300A}/[H2300]', 'inflected', 'heb', 'חָדַד', '["châdad"]', '["and/ they are keen"]', '["v"]', 'to be (causatively, make) sharp or (figuratively) severe be fierce, sharpen.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H2061>', 'inflected', 'heb', 'מזאבי', '["mi./ze.''E.vei"]', '["more than/ wolves of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6335A}/[H6335]', 'inflected', 'heb', 'פּוּשׁ', '["pûwsh"]', '["and/ they paw [the] ground","and/ you will skip"]', '["v"]', 'to spread; figuratively, act proudly grow up, be grown fat, spread selves, be scattered.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2555}/[H2554]', 'inflected', 'heb', 'חָמָס', '["châmâç"]', '["for/ violence"]', '["n-m"]', 'violence; by implication, wrong; by metonymy unjust gain cruel(-ty), damage, false, injustice, × oppressor, unrighteous, violence (against, done), violent (dealing), wrong.', 'from 2554;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4041}/[H1571]', 'lemma', 'heb', 'מְגַמָּה', '["mᵉgammâh"]', '["[the] totality of"]', '["n-f"]', 'properly, accumulation, i.e. impulse or direction sup up.', 'from the same as 1571;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4890}/[H7831]', 'lemma', 'heb', 'מִשְׂחַק', '["mischaq"]', '["[are] laughter"]', '["n-m"]', 'a laughing-stock scorn.', 'from 7831;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0433}/H9023/[H410]', 'inflected', 'heb', 'אֱלוֹהַּ', '["ʼĕlôwahh"]', '["[becomes] <into>/ god/ his"]', '["n-m"]', 'a deity or the Deity God, god. See 430.', 'rarely (shortened) אֱלֹהַּ; probably prolonged (emphatic) from 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6918G}/H9020/[H6942]', 'inflected', 'heb', 'קָדוֹשׁ', '["qâdôwsh"]', '["holy [one]/ my"]', '["a"]', 'sacred (ceremonially or morally); (as noun) God (by eminence), an angel, a saint, a sanctuary holy (One), saint.', 'or קָדֹשׁ; from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7760L}/H9033/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["you have appointed/ it"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3198}/[H3198]', 'inflected', 'heb', 'יָכַח', '["yâkach"]', '["to/ reprove"]', '["v"]', 'to be right (i.e. correct); reciprocal, to argue; causatively, to decide, justify or convict appoint, argue, chasten, convince, correct(-ion), daysman, dispute, judge, maintain, plead, reason (together), rebuke, reprove(-r), surely, in any wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3245}/H9033/[H3245]', 'inflected', 'heb', 'יָסַד', '["yâçad"]', '["you have established/ it"]', '["v"]', 'to set (literally or figuratively); intensively, to found; reflexively, to sit down together, i.e. settle, consult appoint, take counsel, establish, (lay the, lay for a) found(-ation), instruct, lay, ordain, set, × sure.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2890}/[H2891]', 'lemma', 'heb', 'טְהוֹר', '["ṭᵉhôwr"]', '["[you are too] pure of"]', '["n-m"]', 'purity pureness.', 'from 2891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1104}/[H1104]', 'inflected', 'heb', 'בָּלַע', '["bâlaʻ"]', '["when/ swallows up"]', '["v"]', 'to make away with (specifically by swallowing); generally, to destroy cover, destroy, devour, eat up, be at end, spend up, swallow down (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7431}/[H7430]', 'inflected', 'heb', 'רֶמֶשׂ', '["remes"]', '["like/ creeping thing[s]"]', '["n-m"]', 'a reptile or any other rapidly moving animal that creepeth, creeping (moving) thing.', 'from 7430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1641}/H9033/[H1641]', 'inflected', 'heb', 'גָּרַר', '["gârar"]', '["he drags away/ it"]', '["v"]', 'to drag off roughly; by implication, to bring up the cud (i.e. ruminate); by analogy, to saw catch, chew, × continuing, destroy, saw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2764B}/H9023/[H2763]', 'inflected', 'heb', 'חֵרֶם', '["chêrem"]', '["in/ net/ his"]', '["n-m"]', 'physical (as shutting in) a net (either literally or figuratively); usually a doomed object; abstractly extermination (ac-) curse(-d, -d thing), dedicated thing, things which should have been utterly destroyed, (appointed to) utter destruction, devoted (thing), net.', 'or (Zechariah 14:11) חֶרֶם; from 2763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0622}/H9033/[H622]', 'inflected', 'heb', 'אָסַף', '["ʼâçaph"]', '["and/ he gathers/ it"]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4365A}/H9023/[H4364]', 'inflected', 'heb', 'מִכְמֶרֶת', '["mikmereth"]', '["in/ fishing net/ his"]', '["n-f"]', 'a (fisher''s) net drag, net.', 'or מִכְמֹרֶת; feminine of 4364;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2764B}/H9023/[H2763]', 'inflected', 'heb', 'חֵרֶם', '["chêrem"]', '["to/ net/ his"]', '["n-m"]', 'physical (as shutting in) a net (either literally or figuratively); usually a doomed object; abstractly extermination (ac-) curse(-d, -d thing), dedicated thing, things which should have been utterly destroyed, (appointed to) utter destruction, devoted (thing), net.', 'or (Zechariah 14:11) חֶרֶם; from 2763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4365A}/H9023/[H4364]', 'inflected', 'heb', 'מִכְמֶרֶת', '["mikmereth"]', '["to/ fishing net/ his"]', '["n-f"]', 'a (fisher''s) net drag, net.', 'or מִכְמֹרֶת; feminine of 4364;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3978}/H9023/[H398]', 'inflected', 'heb', 'מַאֲכָל', '["maʼăkâl"]', '["and/ food/ his"]', '["n-m"]', 'an eatable (includ. provender, flesh and fruit) food, fruit, (bake-)meat(-s), victual.', 'from 398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2764B}/H9023/[H2763]', 'inflected', 'heb', 'חֵרֶם', '["chêrem"]', '["net/ his"]', '["n-m"]', 'physical (as shutting in) a net (either literally or figuratively); usually a doomed object; abstractly extermination (ac-) curse(-d, -d thing), dedicated thing, things which should have been utterly destroyed, (appointed to) utter destruction, devoted (thing), net.', 'or (Zechariah 14:11) חֶרֶם; from 2763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0874}/[H874]', 'inflected', 'heb', 'בָּאַר', '["bâʼar"]', '["and/ make [it] clear"]', '["v"]', 'to dig; by analogy, to engrave; figuratively, to explain declare, (make) plain(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6075A}/[H6075]', 'lemma', 'heb', 'עָפַל', '["ʻâphal"]', '["it is swollen"]', '["v"]', 'to swell; figuratively, be elated be lifted up, presume.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5115B}/[H5116]', 'lemma', 'heb', 'נָוָה', '["nâvâh"]', '["he stays at home"]', '["v"]', 'to rest (as at home); causatively (through the implied idea of beauty), to celebrate (with praises) keep at home, prepare an habitation.', 'a primitive root; (compare 5116)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5671}/[H5670]', 'lemma', 'heb', 'עַבְטִיט', '["ʻabṭîyṭ"]', '["pledge[s]"]', '["n-m"]', 'something pledged, i.e. (collectively) pawned goods thick clay (by a false etym.).', 'from 5670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5391A}/H9031/[H5391]', 'inflected', 'heb', 'נָשַׁךְ', '["nâshak"]', '["[those who] pay interest to/ you"]', '["v"]', 'to strike with a sting (as a serpent); figuratively, to oppress with interest on a loan bite, lend upon usury.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2111}/H9031/[H2111]', 'inflected', 'heb', 'זוּעַ', '["zûwaʻ"]', '["[those who will] make tremble/ you"]', '["v"]', 'properly, to shake off, i.e. (figuratively) to agitate (as with fear) move, tremble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7997B}/H9031/[H7997]', 'inflected', 'heb', 'שָׁלַל', '["shâlal"]', '["they will plunder/ you"]', '["v"]', 'to drop or strip; by implication, to plunder let fall, make self a prey, × of purpose, (make a, (take)) spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3714>', 'inflected', 'heb', 'וכפיס', '["ve./kha.Fis"]', '["and/ a rafter"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3220G>\', 'opaque', 'heb', 'יָם', '["yâm"]', '["[the] sea"]', '["n-m"]', 'a sea (as breaking in noisy surf) or large body of water; specifically (with the article), the Mediterranean Sea; sometimes a large river, or an artifical basin; locally, the west, or (rarely) the south sea (× -faring man, (-shore)), south, west (-ern, side, -ward).', 'from an unused root meaning to roar;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4589}/H9028/[H5783]', 'inflected', 'heb', 'מָעוֹר', '["mâʻôwr"]', '["nakedness<es>/ their"]', '["n-m"]', 'nakedness, i.e. (in plural) the pudenda nakedness.', 'from 5783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6188}/[H6189]', 'inflected', 'heb', 'עָרֵל', '["ʻârêl"]', '["and/ be counted as uncircumcised"]', '["v"]', 'to expose or remove the prepuce, whether literal (to go naked) or figurative (to refrain from using) count uncircumcised, foreskin to be uncovered.', 'a primitive root; properly, to strip; but used as denominative from 6189;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7022}/[H7036]', 'inflected', 'heb', 'קִיקָלוֹן', '["qîyqâlôwn"]', '["and/ disgrace"]', '["n-m"]', 'intense disgrace shameful spewing.', 'from 7036;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2865}/H9039/[H2865]', 'inflected', 'heb', 'חָתַת', '["châthath"]', '["it will terrify/ them"]', '["v"]', 'properly, to prostrate; hence, to break down, either (literally) by violence, or (figuratively) by confusion and fear abolish, affright, be (make) afraid, amaze, beat down, discourage, (cause to) dismay, go down, scare, terrify.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6458}/H9033/[H6458]', 'inflected', 'heb', 'פָּסַל', '["pâçal"]', '["he has carved/ it"]', '["v"]', 'to carve, whether wood or stone grave, hew.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3384B}/[H3384]', 'inflected', 'heb', 'יָרָה', '["yârâh"]', '["and/ [one which] teaches"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0483}\/[H481]', 'inflected', 'heb', 'אִלֵּם', '["ʼillêm"]', '["dumb"]', '["a"]', 'speechless dumb (man).', 'from 481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2265}/[H2263]', 'inflected', 'heb', 'חֲבַקּוּק', '["Chăbaqqûwq"]', '["of/ Habakkuk"]', '["n-pr-m"]', 'Chabakkuk, the prophet Habakkuk.', 'by reduplication from 2263; embrace;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7692H}/[H7686]', 'lemma', 'heb', 'שִׁגָּיוֹן', '["shiggâyôwn"]', '["shiggionoth"]', '["n-pr-m"]', 'properly, aberration, i.e. (technically) a dithyramb or rambling poem Shiggaion, Shigionoth.', 'or שִׁגָּיֹנָה; from 7686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2421}/H9033/[H2331]', 'inflected', 'heb', 'חָיָה', '["châyâh"]', '["restore/ it"]', '["v"]', 'to live, whether literally or figuratively; causatively, to revive keep (leave, make) alive, × certainly, give (promise) life, (let, suffer to) live, nourish up, preserve (alive), quicken, recover, repair, restore (to life), revive, (× God) save (alive, life, lives), × surely, be whole.', 'a primitive root (compare 2331, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2253}/[H2247]', 'lemma', 'heb', 'חֶבְיוֹן', '["chebyôwn"]', '["[the] hiding place of"]', '["n-m"]', 'a concealment hiding.', 'from 2247;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4128}/[H4128]', 'inflected', 'heb', 'מוּד', '["mûwd"]', '["and/ he shook"]', '["v"]', 'to shake measure.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5425A}/[H5425]', 'inflected', 'heb', 'נָתַר', '["nâthar"]', '["and/ he has made jump"]', '["v"]', 'to jump, i.e. be violently agitated; causatively, to terrify, shake off, untie drive asunder, leap, (let) loose, × make, move, undo.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3572}/[H3568]', 'lemma', 'heb', 'כּוּשָׁן', '["Kûwshân"]', '["Cushan"]', '["n-pr-loc"]', 'Cushan, a region of Arabia Cushan.', 'perhaps from 3568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4080H}\/[H4079]', 'inflected', 'heb', 'מִדְיָן', '["Midyân"]', '["Midian"]', '["n-pr-m n-pr-loc"]', 'Midjan, a son of Abraham; also his country and (collectively) his descendants Midian, Midianite.', 'the same as 4079;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9003/{H5104H}/[H5102]', 'inflected', 'heb', 'נָהָר', '["nâhâr"]', '["¿/ on/ rivers"]', '["n-m"]', 'a stream (including the sea; expectation the Nile, Euphrates, etc.); figuratively, prosperity flood, river.', 'from 5102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5783}/[H5783]', 'lemma', 'heb', 'עוּר', '["ʻûwr"]', '["it is made bare"]', '["v"]', 'to (be) bare be made naked.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4294I}/[H5186]', 'lemma', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["arrows"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7315}/[H7311]', 'lemma', 'heb', 'רוֹם', '["rôwm"]', '["height"]', '["adv"]', 'elevation, i.e. (adverbially) aloft on high.', 'from 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2073}/H9011/[H2082]', 'inflected', 'heb', 'זְבוּל', '["zᵉbûwl"]', '["a lofty abode/ <towards>"]', '["n-m"]', 'a residence dwell in, dwelling, habitation.', 'or זְבֻל; from 2082;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2595}/H9021/[H2583]', 'inflected', 'heb', 'חֲנִית', '["chănîyth"]', '["spear/ your"]', '["n-f"]', 'a lance (for thrusting, like pitching a tent) javelin, spear.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3468}/[H3467]', 'inflected', 'heb', 'יֶשַׁע', '["yeshaʻ"]', '["for/ [the] salvation","for/ [the] salvation of"]', '["n-m"]', 'liberty, deliverance, prosperity safety, salvation, saving.', 'or יֵשַׁע; from 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5542}\/[H5541]', 'inflected', 'heb', 'סֶלָה', '["çelâh"]', '["Selah"]', '["v"]', 'suspension (of music), i.e. pause Selah.', 'from 5541;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4294I}/H9023/[H5186]', 'inflected', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["with/ own arrows/ his"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6518>/H9023', 'opaque', 'heb', 'פָּרָז', '["pârâz"]', '["warriors/ his"]', '["n-m"]', 'a chieftain village.', 'from an unused root meaning to separate, i.e. decide;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6327A}/H9030/[H6327]', 'inflected', 'heb', 'פּוּץ', '["pûwts"]', '["to/ scatter/ me"]', '["v"]', 'to dash in pieces, literally or figuratively (especially to disperse) break (dash, shake) in (to) pieces, cast (abroad), disperse (selves), drive, retire, scatter (abroad), spread abroad.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5951}/H9028/[H5970]', 'inflected', 'heb', 'עֲלִיצוּת', '["ʻălîytsûwth"]', '["exultation/ their"]', '["n-f"]', 'exultation rejoicing.', 'from 5970;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7538}/[H7537]', 'lemma', 'heb', 'רָקָב', '["râqâb"]', '["rottenness"]', '["n-m"]', 'decay (by caries) rottenness (thing).', 'from 7537;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8478G}/H9030/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["and/ under/ me"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7517}/[H7503]', 'inflected', 'heb', 'רֶפֶת', '["repheth"]', '["[is] in the/ stalls"]', '["n-m"]', 'a stall for cattle (from their resting there) stall.', 'probably from 7503;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2428G}/H9020/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["[is] strength/ my"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5058}/H9020/[H5059]', 'inflected', 'heb', 'נְגִינָה', '["nᵉgîynâh"]', '["with/ stringed instruments/ my"]', '["n-f"]', 'properly, instrumental music; by implication, a stringed instrument; by extension, a poem set to music; specifically, an epigram stringed instrument, musick, Neginoth (plural), song.', 'or נְגִינַת; (Psalm 61:title), from 5059;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6846H}/[H6845]', 'lemma', 'heb', 'צְפַנְיָה', '["Tsᵉphanyâh"]', '["Zephaniah"]', '["n-pr-m"]', 'Tsephanjah, the name of four Israelites Zephaniah.', 'or צְפַנְיָהוּ; from 6845 and 3050; Jah has secreted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3569H}/[H3568]', 'lemma', 'heb', 'כּוּשִׁי', '["Kûwshîy"]', '["Cushi"]', '["a"]', 'a Cushite, or descendant of Cush Cushi, Cushite, Ethiopian(-s).', 'patronymically from 3568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1436H}/[H1431]', 'lemma', 'heb', 'גְּדַּלְיָה', '["Gᵉdalyâh"]', '["Gedaliah"]', '["n-pr-m"]', 'Gedaljah, the name of five Israelites Gedaliah.', 'or (prolonged) גְּדַלְיָהוּ; from 1431 and 3050; Jah has become great;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0568O}/[H559]', 'lemma', 'heb', 'אֲמַרְיָה', '["ʼĂmaryâh"]', '["Amariah"]', '["n-pr-m"]', 'Amarjah, the name of nine Israelites Amariah.', 'or prolonged אֲמַרְיָהוּ; from 559 and 3050; Jah has said (i.e. promised);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2396K}/[H2388]', 'lemma', 'heb', 'חִזְקִיָּה', '["Chizqîyâh"]', '["Hezekiah"]', '["n-pr-m"]', 'Chizkijah, a king of Judah, also the name of two other Israelites Hezekiah, Hizkiah, Hizkijah. Compare 3169.', 'or חִזְקִיָּהוּ; also יְחִזְקִיָּה; or יְחִזְקִיָּהוּ; from 2388 and 3050; strengthened of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7812}/[H7812]', 'inflected', 'heb', 'שָׁחָה', '["shâchâh"]', '["those/ [who] bow down"]', '["v"]', 'to depress, i.e. prostrate (especially reflexive, in homage to royalty or God) bow (self) down, crouch, fall down (flat), humbly beseech, do (make) obeisance, do reverence, make to stoop, worship.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4428K}/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["by/ Milcom"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5472}/[H5472]', 'inflected', 'heb', 'סוּג', '["çûwg"]', '["those/ [who] have turned back"]', '["v"]', 'properly, to flinch, i.e. (by implication) to go back, literally (to retreat) or figuratively (to apostatize) backslider, drive, go back, turn (away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7121G}/H9023/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["invited [ones]/ his"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1801}/[H1801]', 'inflected', 'heb', 'דָּלַג', '["dâlag"]', '["<the>/ [one who] leaps"]', '["v"]', 'to spring leap.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4820}\/[H7411]', 'inflected', 'heb', 'מִרְמָה', '["mirmâh"]', '["and/ deceit"]', '["n-f"]', 'fraud craft, deceit(-ful, -fully), false, feigned, guile, subtilly, treachery.', 'from 7411 in the sense of deceiving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4932G}/[H8138]', 'inflected', 'heb', 'מִשְׁנֶה', '["mishneh"]', '["the/ second district"]', '["n-m"]', 'properly, a repetition, i.e. a duplicate (copy of a document), or a double (in amount); by implication, a second (in order, rank, age, quality or location) college, copy, double, fatlings, next, second (order), twice as much.', 'from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H1389I}/[H1387]', 'inflected', 'heb', 'גִּבְעָה', '["gibʻâh"]', '["from/ the/ hills"]', '["n-f"]', 'a hillock hill, little hill.', 'feminine from the same as 1387;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4389}/[H4388]', 'inflected', 'heb', 'מַכְתֵּשׁ', '["Maktêsh"]', '["the/ Mortar"]', '["n-m"]', 'dell; the Maktesh, a place in Jerusalem Maktesh.', 'the same as 4388;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5187}/[H5190]', 'lemma', 'heb', 'נְטִיל', '["nᵉṭîyl"]', '["[the] weighers of"]', '["a"]', 'laden that bear.', 'from 5190;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5216A}/[H5214]', 'inflected', 'heb', 'נִיר', '["nîyr"]', '["with <the>/ lamps"]', '["n-m"]', 'a lamp (i.e. the burner) or light (literally or figuratively) candle, lamp, light.', 'or נִר; also נֵיר; or נֵר; or (feminine) נֵרָה; from a primitive root (see 5214; 5135) properly, meaning to glisten;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7087A}/[H7087]', 'inflected', 'heb', 'קָפָא', '["qâphâʼ"]', '["who/ are thickening"]', '["v n-m"]', 'to shrink, i.e. thicken (as unracked wine, curdled milk, clouded sky, frozen water) congeal, curdle, dark, settle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8105}/H9028/[H8104]', 'inflected', 'heb', 'שֶׁמֶר', '["shemer"]', '["lees/ their"]', '["n-m"]', 'something preserved, i.e. the settlings (plural only) of wine dregs, (wines on the) lees.', 'from 8104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4118A}/[H4116]', 'inflected', 'heb', 'מַהֵר', '["mahêr"]', '["and/ hurrying"]', '["a adv"]', 'properly, hurrying; hence (adverbially) in a hurry hasteth, hastily, at once, quickly, soon, speedily, suddenly.', 'from 4116;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3894}/H9028/[H3898]', 'inflected', 'heb', 'לָחוּם', '["lâchûwm"]', '["and/ bowel[s]/ their"]', '["n-m"]', 'properly, eaten, i.e. food; also flesh, i.e. body while...is eating, flesh.', 'or לָחֻם; passive participle of 3898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1557}/[H1556]', 'inflected', 'heb', 'גָּלָל', '["gâlâl"]', '["like <the>/ dung<s>"]', '["n-m"]', 'dung (as in balls) dung.', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2091>/H9028', 'opaque', 'heb', 'זָהָב', '["zâhâb"]', '["gold/ their"]', '["n-m"]', 'gold, figuratively, something gold-colored (i.e. yellow), as oil, a clear sky gold(-en), fair weather.', 'from an unused root meaning to shimmer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7068}/H9023/[H7065]', 'inflected', 'heb', 'קִנְאָה', '["qinʼâh"]', '["jealousy/ his"]', '["n-f"]', 'jealousy or envy envy(-ied), jealousy, × sake, zeal.', 'from 7065;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7197B}/[H7179]', 'lemma', 'heb', 'קָשַׁשׁ', '["qâshash"]', '["gather yourselves together"]', '["v"]', 'to forage for straw, stubble or wood; figuratively, to assemble gather (selves) (together).', 'a primitive root; to become sapless through drought; used only as denominative from 7179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7197B}/[H7179]', 'inflected', 'heb', 'קָשַׁשׁ', '["qâshash"]', '["and/ gather together"]', '["v"]', 'to forage for straw, stubble or wood; figuratively, to assemble gather (selves) (together).', 'a primitive root; to become sapless through drought; used only as denominative from 7179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0831}/[H8254]', 'inflected', 'heb', 'אַשְׁקְלוֹן', '["ʼAshqᵉlôwn"]', '["and/ Ashkelon"]', '["n-pr-loc"]', 'Ashkelon, a place in Palestine Ashkelon, Askalon.', 'probably from 8254 in the sense of weighing-place (i.e. mart);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1644G}/H9034/[H1644]', 'inflected', 'heb', 'גָּרַשׁ', '["gârash"]', '["people will drive out/ it"]', '["v"]', 'to drive out from a possession; especially to expatriate or divorce cast up (out), divorced (woman), drive away (forth, out), expel, × surely put away, trouble, thrust out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6131A}\/[H6131]', 'inflected', 'heb', 'עָקַר', '["ʻâqar"]', '["it will be plucked up"]', '["v"]', 'to pluck up (especially by the roots); specifically, to hamstring; figuratively, to exterminate dig down, hough, pluck up, root up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0006}/H9032/[H6]', 'inflected', 'heb', 'אָבַד', '["ʼâbad"]', '["and/ I will destroy/ you"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3741}/[H3733]', 'lemma', 'heb', 'כָּרָה', '["kârâh"]', '["meadows of"]', '["n-f"]', 'a meadow cottage.', 'feminine of 3733;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7462B}/H9013/[H7462]', 'inflected', 'heb', 'רָעָה', '["râʻâh"]', '["they will graze/ !"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6485I}/H9038/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["he will visit/ them"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1421}/[H1422]', 'inflected', 'heb', 'גִּדּוּף', '["giddûwph"]', '["and/ [the] reviling words of"]', '["n-m"]', 'vilification reproach, reviling.', 'or (shortened) גִּדֻּף; and (feminine) גִּדּוּפָהxlit giddûphâh corrected to giddûwphâh; or גִּדֻּפָה; from 1422;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6017}/[H6014]', 'inflected', 'heb', 'עֲמֹרָה', '["ʻĂmôrâh"]', '["like/ Gomorrah"]', '["n-pr-loc"]', 'Amorah, a place in Palestine Gomorrah.', 'from 6014; a (ruined) heap;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4476}/[H4943]', 'lemma', 'heb', 'מִמְשָׁק', '["mimshâq"]', '["a place possessed of"]', '["n-m"]', 'a possession breeding.', 'from the same as 4943;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4379}/[H3738]', 'inflected', 'heb', 'מִכְרֶה', '["mikreh"]', '["and/ a pit of"]', '["n-m"]', 'a pit (for salt) (salt-) pit.', 'from 3738;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1471A}/H9020/[H1465]', 'inflected', 'heb', 'גּוֹי', '["gôwy"]', '["nation/ my"]', '["n-m n-pr-m"]', 'a foreign nation; hence, a Gentile; also (figuratively) a troop of animals, or a flight of locusts Gentile, heathen, nation, people.', 'rarely (shortened) גֹּי; apparently from the same root as 1465 (in the sense of massing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1347}/H9028/[H1342]', 'inflected', 'heb', 'גָּאוֹן', '["gâʼôwn"]', '["pride/ their"]', '["n-m"]', 'the same as 1346 arrogancy, excellency(-lent), majesty, pomp, pride, proud, swelling.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3730>/H9024', 'inflected', 'heb', 'בכפתריה', '["be./khaf.to.Rei./ha"]', '["on/ capitals/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0731}/[H730]', 'lemma', 'heb', 'אַרְזָה', '["ʼarzâh"]', '["cedar-work"]', '["n-f"]', 'cedar wainscoating cedar work.', 'feminine of 730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5947}/[H5937]', 'inflected', 'heb', 'עַלִּיז', '["ʻallîyz"]', '["<the>/ jubilant"]', '["a"]', 'exultant joyous, (that) rejoice(-ing)', 'from 5937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4769}/[H7257]', 'lemma', 'heb', 'מַרְבֵּץ', '["marbêts"]', '["a resting place"]', '["n-m"]', 'a reclining place, i.e. fold (for flocks) couching place, place to lie down.', 'from 7257;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027G}/H9023\/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ his"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1351}/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["and/ [the] defiled [one]"]', '["v"]', 'to soil or (figuratively) desecrate defile, pollute, stain.', 'a primitive root, (rather identified with 1350, through the idea of freeing, i.e. repudiating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1633A}/[H1634]', 'lemma', 'heb', 'גָּרַם', '["gâram"]', '["they gnaw"]', '["v"]', '(causative) to bone, i.e. denude (by extensive, craunch) the bones gnaw the bones, break.', 'a primitive root; to be spare or skeleton-like; used only as a denominative from 1634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6348}/[H6348]', 'lemma', 'heb', 'פָּחַז', '["pâchaz"]', '["[are] insolent"]', '["v"]', 'to bubble up or froth (as boiling water), i.e. (figuratively) to be unimportant light.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0900}/[H898]', 'lemma', 'heb', 'בֹּגְדוֹת', '["bôgᵉdôwth"]', '["treacheri<es>"]', '["n-f"]', 'treacheries treacherous.', 'feminine plural active participle of 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6438H}/H9028/[H6434]', 'inflected', 'heb', 'פִּנָּה', '["pinnâh"]', '["corners/ their"]', '["n-f"]', 'an angle; by implication, a pinnacle; figuratively, a chieftain bulwark, chief, corner, stay, tower.', 'feminine of 6434;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2351>/H9028', 'opaque', 'heb', 'חוּץ', '["chûwts"]', '["streets/ their"]', '["n-m"]', 'properly, separate by a wall, i.e. outside, outdoors abroad, field, forth, highway, more, out(-side, -ward), street, without.', 'or (shortened) חֻץ; (both forms feminine in the plural) from an unused root meaning to sever;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6658B}/[H6658]', 'lemma', 'heb', 'צָדָה', '["tsâdâh"]', '["they have been laid waste"]', '["v"]', 'to chase; by implication, to desolate destroy, hunt, lie in wait.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4583}/H9024/[H5772]', 'inflected', 'heb', 'מָעוֹן', '["mâʻôwn"]', '["dwelling/ its"]', '["n-m"]', 'an abode, of God (the Tabernacle or the Temple), men (their home) or animals (their lair); hence, a retreat (asylum) den, dwelling((-) place), habitation.', 'or מָעִין; (1 Chronicles 4:41), from the same as 5772;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965B}/H9040/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["to arise/ I"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6908}/H9040/[H6908]', 'inflected', 'heb', 'קָבַץ', '["qâbats"]', '["to/ assemble/ I"]', '["v"]', 'to grasp, i.e. collect assemble (selves), gather (bring) (together, selves together, up), heap, resort, × surely, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5647H}/H9033/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["to/ serve/ him"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6282A}/H9020/[H6280]', 'inflected', 'heb', 'עָתָר', '["ʻâthâr"]', '["worshippers/ my"]', '["n-m"]', 'incense (as increasing to a volume of smoke); hence a worshipper suppliant, thick.', 'from 6280; also compare 6279');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6327A}/H9020/[H6327]', 'inflected', 'heb', 'פּוּץ', '["pûwts"]', '["scattered [ones]/ my"]', '["v"]', 'to dash in pieces, literally or figuratively (especially to disperse) break (dash, shake) in (to) pieces, cast (abroad), disperse (selves), drive, retire, scatter (abroad), spread abroad.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4503G>/H9020', 'opaque', 'heb', 'מִנְחָה', '["minchâh"]', '["offering/ my"]', '["n-f"]', 'a donation; euphemistically, tribute; specifically a sacrificial offering (usually bloodless and voluntary) gift, oblation, (meat) offering, present, sacrifice.', 'from an unused root meaning to apportion, i.e. bestow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5949}/H9022/[H5953]', 'inflected', 'heb', 'עֲלִילָה', '["ʻălîylâh"]', '["practices/ your"]', '["n-f"]', 'an exploit (of God), or a performance (of man, often in a bad sense); by implication, an opportunity act(-ion), deed, doing, invention, occasion, work.', 'or עֲלִלָה; from 5953 in the sense of effecting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7130G}/H9022/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["from/ midst/ your"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1346}/H9022/[H1342]', 'inflected', 'heb', 'גַּאֲוָה', '["gaʼăvâh"]', '["pride/ your"]', '["n-f"]', 'arrogance or majesty; by implication, (concretely) ornament excellency, haughtiness, highness, pride, proudly, swelling.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1361}/[H1361]', 'inflected', 'heb', 'גָּבַהּ', '["gâbahh"]', '["to/ be haughty"]', '["v"]', 'to soar, i.e. be lofty; figuratively, to be haughty exalt, be haughty, be (make) high(-er), lift up, mount up, be proud, raise up great height, upward.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4941G}/H9022/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["judgments/ your"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4150H}/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["from/ an appointed feast"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6908}/H9040/[H6908]', 'inflected', 'heb', 'קָבַץ', '["qâbats"]', '["to gather/ I"]', '["v"]', 'to grasp, i.e. collect assemble (selves), gather (bring) (together, selves together, up), heap, resort, × surely, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1867H}/[H1867]', 'inflected', 'heb', 'דָּֽרְיָוֵשׁ', '["Dârᵉyâvêsh"]', '["of/ Darius"]', '["n-pr-m"]', 'Darejavesh, a title (rather than name) of several Persian kings Darius.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2292A}/[H2282]', 'lemma', 'heb', 'חַגַּי', '["Chaggay"]', '["Haggai"]', '["n-pr-m"]', 'Chaggai, a Hebrew prophet Haggai.', 'from 2282; festive;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3091J}/[H3068]', 'lemma', 'heb', 'יְהוֹשׁוּעַ', '["Yᵉhôwshûwaʻ"]', '["Joshua","O Joshua"]', '["n-pr-m"]', 'Jehoshua (i.e. Joshua), the Jewish leader Jehoshua, Jehoshuah, Joshua. Compare 1954, 3442.', 'or יְהוֹשֻׁעַ; from 3068 and 3467; Jehovah-saved;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1129}\/[H1129]', 'inflected', 'heb', 'בָּנָה', '["bânâh"]', '["to/ be rebuilt"]', '["v"]', 'to build (literally and figuratively) (begin to) build(-er), obtain children, make, repair, set (up), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7937}/[H7937]', 'inflected', 'heb', 'שָׁכַר', '["shâkar"]', '["to/ become drunk"]', '["v"]', 'to become tipsy; in a qualified sense, to satiate with a stimulating drink or (figuratively) influence (be filled with) drink (abundantly), (be, make) drunk(-en), be merry. (Superlative of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2552}/[H2552]', 'inflected', 'heb', 'חָמַם', '["châmam"]', '["to/ be warm"]', '["v"]', 'to be hot (literally or figuratively) enflame self, get (have) heat, be (wax) hot, (be, wax) warm (self, at).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7936B}/[H3739]', 'inflected', 'heb', 'שָׂכַר', '["sâkar"]', '["and/ the/ [one who] earns wages"]', '["v"]', 'to hire earn wages, hire (out self), reward, × surely.', 'or (by permutation) סָכַר; (Ezra 4:5), a primitive root (apparently akin (by prosthesis) to 3739 through the idea of temporary purchase; compare 7937);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5344A}\/[H5344]', 'inflected', 'heb', 'נָקַב', '["nâqab"]', '["pierced"]', '["v"]', 'to puncture, literally (to perforate, with more or less violence) or figuratively (to specify, designate, libel) appoint, blaspheme, bore, curse, express, with holes, name, pierce, strike through.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3709G}\/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["hands"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7597B}/[H7592]', 'lemma', 'heb', 'שְׁאַלְתִּיאֵל', '["Shᵉʼaltîyʼêl"]', '["Shealtiel"]', '["n-pr-m"]', 'Shealtiel, an Israelite Shalthiel, Shealtiel.', 'or שַׁלְתִּיאֵל; from 7592 and 410; I have asked God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3091J}/[H3068]', 'inflected', 'heb', 'יְהוֹשׁוּעַ', '["Yᵉhôwshûwaʻ"]', '["and/ Joshua"]', '["n-pr-m"]', 'Jehoshua (i.e. Joshua), the Jewish leader Jehoshua, Jehoshuah, Joshua. Compare 1954, 3442.', 'or יְהוֹשֻׁעַ; from 3068 and 3467; Jehovah-saved;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4400}/[H4397]', 'inflected', 'heb', 'מַלְאֲכוּת', '["malʼăkûwth"]', '["by/ [the] message of"]', '["n-f"]', 'a message message.', 'from the same as 4397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7307G}/H9020/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["and/ spirit/ my"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8671}/[H8672]', 'inflected', 'heb', 'תְּשִׁיעִי', '["tᵉshîyʻîy"]', '["of the/ ninth [month]"]', '["a"]', 'ninth ninth.', 'ordinal from 8672;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H6942G}/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["¿/ will it become holy"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H2930A}/[H2930]', 'inflected', 'heb', 'טָמֵא', '["ṭâmêʼ"]', '["¿/ will it become unclean"]', '["v"]', 'to be foul, especially in a ceremial or moral sense (contaminated) defile (self), pollute (self), be (make, make self, pronounce) unclean, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H2962>', 'inflected', 'heb', 'מטרם', '["mi./Te.rem"]', '["from/ before"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1961}/H9048/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["from/ when were/ they"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2834}/[H2834]', 'inflected', 'heb', 'חָשַׂף', '["châsaph"]', '["to/ draw"]', '["v"]', 'to strip off, i.e. generally to make naked (for exertion or in disgrace), to drain away or bail up (a liquid) make bare, clean, discover, draw out, take, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1259}/[H1258]', 'inflected', 'heb', 'בָּרָד', '["bârâd"]', '["and/ with <the>/ hail"]', '["n-m"]', 'hail hail(stones).', 'from 1258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4035}/[H4032]', 'inflected', 'heb', 'מְגוּרָה', '["mᵉgûwrâh"]', '["in the/ granary"]', '["n-f"]', 'a fright; also a granary barn, fear.', 'feminine of 4032 or of 4033;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8384}/[H8384]', 'inflected', 'heb', 'תְּאֵן', '["tᵉʼên"]', '["and/ the/ fig tree"]', '["n-f"]', 'the fig (tree or fruit) fig (tree).', 'or (in the singular, feminine) תְּאֵנָה; perhaps of foreign derivation');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1288}\/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["I will bless"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2392}/[H2388]', 'lemma', 'heb', 'חֹזֶק', '["chôzeq"]', '["[the] strength of"]', '["n-m"]', 'power strength.', 'from 2388;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7392}/H9024/[H7392]', 'inflected', 'heb', 'רָכַב', '["râkab"]', '["and/ riders/ its"]', '["v"]', 'to ride (on an animal or in a vehicle); causatively, to place upon (for riding or generally), to despatch bring (on (horse-) back), carry, get (oneself) up, on (horse-) back, put, (cause to, make to) ride (in a chariot, on, -r), set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7392}/H9028/[H7392]', 'inflected', 'heb', 'רָכַב', '["râkab"]', '["and/ riders/ their"]', '["v"]', 'to ride (on an animal or in a vehicle); causatively, to place upon (for riding or generally), to despatch bring (on (horse-) back), carry, get (oneself) up, on (horse-) back, put, (cause to, make to) ride (in a chariot, on, -r), set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2148v}', 'inflected', 'heb', 'זכריה', '["ze.khar.Yah"]', '["Zechariah"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1296L}/[H1290]', 'lemma', 'heb', 'בֶּרֶכְיָה', '["Berekyâh"]', '["Berekiah"]', '["n-pr-m"]', 'Berekjah, the name of six Israelites Berachiah, Berechiah.', 'or בֶּרֶכְיָהוּ; from 1290 and 3050; knee (i.e. blessing) of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1870G}/H9025/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["according to/ ways/ our"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H4611}/H9025/[H5953]', 'inflected', 'heb', 'מַעֲלָל', '["maʻălâl"]', '["and/ according to/ deeds/ our"]', '["n-m"]', 'an act (good or bad) doing, endeavour, invention, work.', 'from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0854}/H9035\/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["with/ us"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7627>', 'opaque', 'heb', 'שְׁבָט', '["Shᵉbâṭ"]', '["Shebat"]', '["n"]', 'Shebat, a Jewish month Sebat.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1918>', 'inflected', 'heb', 'ההדסים', '["ha./ha.da.Sim"]', '["the/ myrtle trees"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4699}/[H6751]', 'inflected', 'heb', 'מְצֻלָּה', '["mᵉtsullâh"]', '["[were] in the/ hollow"]', '["n-m"]', 'shade bottom.', 'from 6751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8320}/[H8319]', 'lemma', 'heb', 'שָׂרֻק', '["sâruq"]', '["sorrel"]', '["n-m"]', 'bright red (as piercing to the sight), i.e. bay speckled. See 8291.', 'from 8319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7356B}/[H7355]', 'inflected', 'heb', 'רַחַם', '["racham"]', '["with/ compassion<s>"]', '["n-f"]', 'compassion (in the plural); by extension, the womb (as cherishing the fetus); by implication, a maiden bowels, compassion, damsel, tender love, (great, tender) mercy, pity, womb.', 'from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5375R}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["which/ lifted up"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2219}/H9034\/[H2114]', 'inflected', 'heb', 'זָרָה', '["zârâh"]', '["to/ scatter/ it"]', '["v"]', 'to toss about; by implication, to diffuse, winnow cast away, compass, disperse, fan, scatter (away), spread, strew, winnow.', 'a primitive root (compare 2114);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4058}/[H4058]', 'inflected', 'heb', 'מָדַד', '["mâdad"]', '["to/ measure"]', '["v"]', 'properly, to stretch; by implication, to measure (as if by stretching a line); figuratively, to be extended measure, mete, stretch self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H4100}/[H4100]', 'inflected', 'heb', 'מָה', '["mâh"]', '["and/ how/ much?"]', '["i"]', 'properly, interrogative what? (including how? why? when?); but also exclamation, what! (including how!), or indefinitely what (including whatever, and even relatively, that which); often used with prefixes in various adverbial or conjunctive senses how (long, oft, (-soever)), (no-) thing, what (end, good, purpose, thing), whereby(-fore, -in, -to, -with), (for) why.', 'or מַה; or מָ; or מַ; also מֶה; a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7997B}/[H7997]', 'inflected', 'heb', 'שָׁלַל', '["shâlal"]', '["who/ plundered"]', '["v"]', 'to drop or strip; by implication, to plunder let fall, make self a prey, × of purpose, (make a, (take)) spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0892>', 'inflected', 'heb', 'בבבת', '["be./va.Vat"]', '["<in>/ [the] pupil of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5650}/H9028/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["for/ own slaves/ their"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7971G}/H9030\/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["he has sent/ me"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6944G}/H9023\/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["holiness/ his"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7854}/[H7853]', 'inflected', 'heb', 'שָׂטָן', '["sâṭân"]', '["and/ the/ accuser"]', '["n-m"]', 'an opponent; especially (with the article prefixed) Satan, the arch-enemy of good adversary, Satan, withstand.', 'from 7853;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7853}/H9033/[H7853]', 'inflected', 'heb', 'שָׂטַן', '["sâṭan"]', '["to/ accuse/ him"]', '["v"]', 'to attack, (figuratively) accuse (be an) adversary, resist.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1605}/[H1605]', 'inflected', 'heb', 'גָּעַר', '["gâʻar"]', '["and/ may he rebuke"]', '["v"]', 'to chide corrupt, rebuke, reprove.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0977}/[H977]', 'inflected', 'heb', 'בָּחַר', '["bâchar"]', '["who/ has chosen"]', '["v"]', 'properly, to try, i.e. (by implication) select acceptable, appoint, choose (choice), excellent, join, be rather, require.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0181>', 'opaque', 'heb', 'אוּד', '["ʼûwd"]', '["a piece of firewood"]', '["n-m"]', 'a poker (for turning or gathering embers) (fire-) brand.', 'from an unused root meaning to rake together;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0784}/[H784]', 'inflected', 'heb', 'אֵשׁ', '["ʼêsh"]', '["from/ a fire"]', '["n-f"]', 'fire (literally or figuratively) burning, fiery, fire, flaming, hot.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6674>', 'opaque', 'heb', 'צוֹא', '["tsôwʼ"]', '["filthy"]', '["a"]', 'soiled (as if excrementitious) filthy.', 'or צֹא; from an unused root meaning to issue;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H6674>', 'inflected', 'heb', 'הצאים', '["ha./tzo.''Im"]', '["<the>/ filthy"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4254}/[H2502]', 'lemma', 'heb', 'מַחֲלָצָה', '["machălâtsâh"]', '["robes"]', '["n-f"]', 'a mantle (as easily drawn off) changeable suit of apparel, change of raiment.', 'from 2502;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6797}/[H6801]', 'lemma', 'heb', 'צָנִיף', '["tsânîyph"]', '["a turban"]', '["n-m"]', 'a head-dress (i.e. piece of cloth wrapped around) diadem, hood, mitre.', 'or צָנוֹף; or (feminine) צָנִיפָה; from 6801;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6797}/[H6801]', 'inflected', 'heb', 'צָנִיף', '["tsânîyph"]', '["the/ turban"]', '["n-m"]', 'a head-dress (i.e. piece of cloth wrapped around) diadem, hood, mitre.', 'or צָנוֹף; or (feminine) צָנִיפָה; from 6801;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3091J}/[H3068]', 'inflected', 'heb', 'יְהוֹשׁוּעַ', '["Yᵉhôwshûwaʻ"]', '["<in>/ Joshua"]', '["n-pr-m"]', 'Jehoshua (i.e. Joshua), the Jewish leader Jehoshua, Jehoshuah, Joshua. Compare 1954, 3442.', 'or יְהוֹשֻׁעַ; from 3068 and 3467; Jehovah-saved;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7453}/H9021/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["and/ companions/ your"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4185}/[H4184]', 'inflected', 'heb', 'מוּשׁ', '["mûwsh"]', '["and/ I will remove","and/ it will depart"]', '["v"]', 'to withdraw (both literally and figuratively, whether intransitive or transitive) cease, depart, go back, remove, take away.', 'a primitive root (perhaps rather the same as 4184 through the idea of receding by contact);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5782}/H9030/[H5782]', 'inflected', 'heb', 'עוּר', '["ʻûwr"]', '["and/ he roused/ me"]', '["v"]', 'to wake (literally or figuratively) (a-) wake(-n, up), lift up (self), × master, raise (up), stir up (self).', 'a primitive root (rather identical with through the idea of opening the eyes);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4166}/[H3332]', 'lemma', 'heb', 'מוּצָקָה', '["mûwtsâqâh"]', '["pipes"]', '["n-f"]', 'properly, something poured out, i.e. a casting (of metal); by implication, a tube (as cast) when it was cast, pipe.', 'or מֻצָקָה; from 3332;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5216A}/[H5214]', 'inflected', 'heb', 'נִיר', '["nîyr"]', '["[belong] to the/ lamps"]', '["n-m"]', 'a lamp (i.e. the burner) or light (literally or figuratively) candle, lamp, light.', 'or נִר; also נֵיר; or נֵר; or (feminine) נֵרָה; from a primitive root (see 5214; 5135) properly, meaning to glisten;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1543}/[H1556]', 'inflected', 'heb', 'גֻּלָּה', '["gullâh"]', '["the/ bowl"]', '["n-f"]', 'a fountain, bowl or globe (all as round) bowl, pommel, spring.', 'feminine from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8040G}/H9024/[H8071]', 'inflected', 'heb', 'שְׂמֹאול', '["sᵉmôʼwl"]', '["left [side]/ its"]', '["n-m"]', 'properly, dark (as enveloped), i.e. the north; hence (by orientation), the left hand left (hand, side).', 'or שְׂמֹאל; a primitive word (rather perhaps from the same as 8071 (by insertion of the aleph) through the idea of wrapping up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2428G}/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["by/ strength"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7307G}/H9020/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["by/ spirit/ my"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7222}/[H7218]', 'inflected', 'heb', 'רֹאשָׁה', '["rôʼshâh"]', '["<the>/ top"]', '["n-f"]', 'the head head(-stone).', 'feminine of 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6804}/[H6794]', 'lemma', 'heb', 'צַנְתָּרָה', '["tsantârâh"]', '["[the] pipes of"]', '["n-f"]', 'a tube pipe.', 'probably from the same as 6794;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7324}/[H7324]', 'inflected', 'heb', 'רוּק', '["rûwq"]', '["which/ are pouring out"]', '["v"]', 'to pour out (literally or figuratively), i.e. empty × arm, cast out, draw (out), (make) empty, pour forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7341}/H9024/[H7337]', 'inflected', 'heb', 'רֹחַב', '["rôchab"]', '["and/ breadth/ its"]', '["n-m"]', 'width (literally or figuratively) breadth, broad, largeness, thickness, wideness.', 'from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1589}/[H1589]', 'inflected', 'heb', 'גָּנַב', '["gânab"]', '["<the>/ [one who] steals"]', '["v"]', 'to thieve (literally or figuratively); by implication, to deceive carry away, × indeed, secretly bring, steal (away), get by stealth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869K}/H9028/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["[is] appearance/ their"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7564}/[H7562]', 'inflected', 'heb', 'רִשְׁעָה', '["rishʻâh"]', '["[is] <the>/ wickedness"]', '["n-f"]', 'wrong (especially moral) fault, wickedly(-ness).', 'feminine of 7562;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6310J}/H9024\/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["mouth/ its"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H9039}', 'inflected', 'heb', 'ולהנה', '["ve./la./He.nah"]', '["and/ [belonged] to/ them"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3671}/[H3670]', 'inflected', 'heb', 'כָּנָף', '["kânâph"]', '["like/ [the] wings of"]', '["n-f"]', 'an edge or extremity; specifically (of a bird or army) a wing, (of a garment or bedclothing) a flap, (of the earth) a quarter, (of a building) a pinnacle bird, border, corner, end, feather(-ed), × flying, (one an-) other, overspreading, × quarters, skirt, × sort, uttermost part, wing(-ed).', 'from 3670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4369}/H9024\/[H4350]', 'inflected', 'heb', 'מְכֻנָה', '["mᵉkunâh"]', '["on own stand/ its"]', '["n-f"]', 'a spot base.', 'the same as 4350;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4818}/[H4817]', 'inflected', 'heb', 'מֶרְכָּבָה', '["merkâbâh"]', '["and/ [were] with the/ chariot"]', '["n-f"]', 'a chariot chariot. See also 1024.', 'feminine of 4817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1261}/[H1258]', 'lemma', 'heb', 'בָּרֹד', '["bârôd"]', '["dappled"]', '["a"]', 'spotted (as if with hail) grisled.', 'from 1258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0554}/[H553]', 'lemma', 'heb', 'אָמֹץ', '["ʼâmôts"]', '["strong"]', '["a"]', 'of a strong color, i.e. red (others fleet) bay.', 'probably from 553;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7838}/[H7835]', 'inflected', 'heb', 'שָׁחֹר', '["shâchôr"]', '["<the>/ black"]', '["a"]', 'properly, dusky, but also (absol.) jetty black.', 'or שָׁחוֹר; from 7835;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3836}/[H3835]', 'inflected', 'heb', 'לָבָן', '["lâbân"]', '["and/ the/ white [horses]"]', '["a"]', 'white white.', 'or (Genesis 49:12) לָבֵן; from 3835;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1261}/[H1258]', 'inflected', 'heb', 'בָּרֹד', '["bârôd"]', '["and/ the/ dappled [horses]"]', '["a"]', 'spotted (as if with hail) grisled.', 'from 1258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8486}/[H3225]', 'inflected', 'heb', 'תֵּימָן', '["têymân"]', '["the/ south"]', '["n-f"]', 'the south (as being on the right hand of a person facing the east) south (side, -ward, wind).', 'or תֵּמָן; denominative from 3225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0554}/[H553]', 'inflected', 'heb', 'אָמֹץ', '["ʼâmôts"]', '["and/ the/ strong [horses]"]', '["a"]', 'of a strong color, i.e. red (others fleet) bay.', 'probably from 553;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6828G}\/[H6845]', 'inflected', 'heb', 'צָפוֹן', '["tsâphôwn"]', '["[the] north"]', '["n-f"]', 'properly, hidden, i.e. dark; used only of the north as a quarter (gloomy and unknown) north(-ern, side, -ward, wind).', 'or צָפֹן; from 6845;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2469G}/[H2466]', 'inflected', 'heb', 'חֶלְדַּי', '["Chelday"]', '["from/ Heldai"]', '["n-pr-m"]', 'Cheldai, the name of two Israelites Heldai.', 'from 2466; worldliness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2900J}/[H2896]', 'lemma', 'heb', 'טוֹבִיָּה', '["Ṭôwbîyâh"]', '["Tobiah"]', '["n-pr-m"]', 'Tobijah, the name of three Israelites and of one Samaritan Tobiah, Tobijah.', 'or טוֹבִיָּהוּ; from 2896 and 3050; goodness of Jehovah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3048J}/[H3045]', 'lemma', 'heb', 'יְדַעְיָה', '["Yᵉdaʻyâh"]', '["Jedaiah"]', '["n-pr-m"]', 'Jedajah, the name of two Israelites Jedaiah.', 'from 3045 and 3050; Jah has known;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2977H}/[H803]', 'lemma', 'heb', 'יֹאשִׁיָּה', '["Yôʼshîyâh"]', '["Josiah"]', '["n-pr-m"]', 'Joshijah, the name of two Israelites Josiah.', 'or יֹאשִׁיָּהוּ; from the same root as 803 and 3050; founded of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6846I}/[H6845]', 'lemma', 'heb', 'צְפַנְיָה', '["Tsᵉphanyâh"]', '["Zephaniah"]', '["n-pr-m"]', 'Tsephanjah, the name of four Israelites Zephaniah.', 'or צְפַנְיָהוּ; from 6845 and 3050; Jah has secreted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H8478J}/H9033/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["and/ from/ under/ him"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5850}/[H5849]', 'inflected', 'heb', 'עֲטָרָה', '["ʻăṭârâh"]', '["and/ the/ crown<s>"]', '["n-f"]', 'a crown crown.', 'from 5849;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2494}/[H2492]', 'inflected', 'heb', 'חֵלֶם', '["Chêlem"]', '["to/ Helem"]', '["n-pr-m"]', 'Chelem, an Israelite Helem. Compare 2469.', 'from 2492; a dream;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2900J}/[H2896]', 'inflected', 'heb', 'טוֹבִיָּה', '["Ṭôwbîyâh"]', '["and/ to/ Tobiah"]', '["n-pr-m"]', 'Tobijah, the name of three Israelites and of one Samaritan Tobiah, Tobijah.', 'or טוֹבִיָּהוּ; from 2896 and 3050; goodness of Jehovah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3048J}/[H3045]', 'inflected', 'heb', 'יְדַעְיָה', '["Yᵉdaʻyâh"]', '["and/ to/ Jedaiah"]', '["n-pr-m"]', 'Jedajah, the name of two Israelites Jedaiah.', 'from 3045 and 3050; Jah has known;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2581}/[H2580]', 'inflected', 'heb', 'חֵן', '["Chên"]', '["and/ to/ Hen"]', '["n-pr-m"]', 'Chen, a figurative name for an Israelite Hen.', 'the same as 2580; grace;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3691>', 'inflected', 'heb', 'בכסלו', '["be./khis.Lev"]', '["in/ Kislev"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8272H}/[H8272]', 'lemma', 'heb', 'שַׁרְאֶצֶר', '["Sharʼetser"]', '["-ezer","Shar-"]', '["n-pr-m"]', 'Sharetser, the name of an Assyrian and an Israelite Sharezer.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7278}/[H7276]', 'inflected', 'heb', 'רֶגֶם מֶלֶךְ', '["Regem Melek"]', '["and/ Regem-"]', '["n-pr-m"]', 'Regem-Melek, an Israelite Regem-melech.', 'from 7276 and 4428; king''s heap;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7278}/[H7276]', 'lemma', 'heb', 'רֶגֶם מֶלֶךְ', '["Regem Melek"]', '["Melech"]', '["n-pr-m"]', 'Regem-Melek, an Israelite Regem-melech.', 'from 7276 and 4428; king''s heap;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2470B}/[H2342]', 'inflected', 'heb', 'חָלָה', '["châlâh"]', '["to/ entreat"]', '["v"]', 'properly, to be rubbed or worn; hence (figuratively) to be weak, sick, afflicted; or (causatively) to grieve, make sick; also to stroke (in flattering), entreat beseech, (be) diseased, (put to) grief, be grieved, (be) grievous, infirmity, intreat, lay to, put to pain, × pray, make prayer, be (fall, make) sick, sore, be sorry, make suit (× supplication), woman in travail, be (become) weak, be wounded.', 'a primitive root (compare 2342, 2470, 2490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H1058}/[H1058]', 'inflected', 'heb', 'בָּכָה', '["bâkâh"]', '["¿/ will I weep"]', '["v"]', 'to weep; generally to bemoan × at all, bewail, complain, make lamentation, × more, mourn, × sore, × with tears, weep.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5144A}/[H5144]', 'lemma', 'heb', 'נָזַר', '["nâzar"]', '["will I consecrate myself?"]', '["v"]', 'to hold aloof, i.e. (intransitivey) abstain (from food and drink, from impurity, and even from divine worship (i.e. apostatize)); specifically, to set apart (to sacred purposes), i.e. devote consecrate, separate(-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H6684}/[H6684]', 'inflected', 'heb', 'צוּם', '["tsûwm"]', '["¿/ really <to fast>"]', '["v"]', 'to cover over (the mouth), i.e. to fast × at all, fast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6684}/H9030/[H6684]', 'inflected', 'heb', 'צוּם', '["tsûwm"]', '["did you fast for/ me"]', '["v"]', 'to cover over (the mouth), i.e. to fast × at all, fast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0241G}/H9028/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["and/ ears/ their"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5590}/H9038/[H5590]', 'inflected', 'heb', 'סָעַר', '["çâʻar"]', '["and/ I will storm away/ them"]', '["v"]', 'to rush upon; by implication, to toss (transitive or intransitive, literal or figurative) be (toss with) tempest(-uous), be sore, troubled, come out as a (drive with the, scatter with a) whirlwind.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H7725O}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ from/ [one who] returns"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8047G}\/[H8074]', 'inflected', 'heb', 'שַׁמָּה', '["shammâh"]', '["into/ a waste"]', '["n-f"]', 'ruin; by implication, consternation astonishment, desolate(-ion), waste, wonderful thing.', 'from 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7339}/[H7337]', 'inflected', 'heb', 'רְחֹב', '["rᵉchôb"]', '["and/ [the] open places of"]', '["n-f"]', 'a width, i.e. (concretely) avenue or area broad place (way), street. See also 1050.', 'or רְחוֹב; from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3207}/[H3206]', 'inflected', 'heb', 'יַלְדָּה', '["yaldâh"]', '["and/ girls"]', '["n-f"]', 'a lass damsel, girl.', 'feminine of 3206;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7339}/H9024\/[H7337]', 'inflected', 'heb', 'רְחֹב', '["rᵉchôb"]', '["in/ open places/ its"]', '["n-f"]', 'a width, i.e. (concretely) avenue or area broad place (way), street. See also 1050.', 'or רְחוֹב; from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6666}\/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["and/ in/ righteousness"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2919}/H9028/[H2926]', 'inflected', 'heb', 'טַל', '["ṭal"]', '["dew/ their"]', '["n-m"]', 'dew (as covering vegetation) dew.', 'from 2926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027G}/H9026\/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hands/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7107}/[H7107]', 'inflected', 'heb', 'קָצַף', '["qâtsaph"]', '["when/ provoked to anger"]', '["v"]', 'to crack off, i.e. (figuratively) burst out in rage (be) anger(-ry), displease, fret self, (provoke to) wrath (come), be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8179G}/H9026/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["in/ gates/ your"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7621}/[H7650]', 'inflected', 'heb', 'שְׁבוּעָה', '["shᵉbûwʻâh"]', '["and/ an oath of"]', '["n-f"]', 'properly, something sworn, i.e. an oath curse, oath, × sworn.', 'feminine passive participle of 7650;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0571H}/[H539]', 'inflected', 'heb', 'אֶמֶת', '["ʼemeth"]', '["and/ <the>/ truth"]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7965G}/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["and/ <the>/ peace","and/ <the>/ well-being"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0157G}\/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["love"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2470B}/[H2342]', 'inflected', 'heb', 'חָלָה', '["châlâh"]', '["and/ to/ entreat"]', '["v"]', 'properly, to be rubbed or worn; hence (figuratively) to be weak, sick, afflicted; or (causatively) to grieve, make sick; also to stroke (in flattering), entreat beseech, (be) diseased, (put to) grief, be grieved, (be) grievous, infirmity, intreat, lay to, put to pain, × pray, make prayer, be (fall, make) sick, sore, be sorry, make suit (× supplication), woman in travail, be (become) weak, be wounded.', 'a primitive root (compare 2342, 2470, 2490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5973A}/H9036\/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["[is] with/ you"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2317>', 'opaque', 'heb', 'חַדְרָךְ', '["Chadrâk"]', '["Hadrach"]', '["n-pr-loc"]', 'Chadrak, a Syrian deity Hadrach.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1834>', 'inflected', 'heb', 'ודמשק', '["ve./da.Me.sek"]', '["and/ Damascus"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6721H}/[H6679]', 'inflected', 'heb', 'צִידוֹן', '["Tsîydôwn"]', '["and/ Sidon"]', '["n-pr-loc"]', 'Tsidon, the name of a son of Canaan, and of a place in Palestine Sidon, Zidon.', 'or צִידֹן; from 6679 in the sense of catching fish; fishery;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2742D}/[H2782]', 'inflected', 'heb', 'חֲרוּץ', '["chărûwts"]', '["and/ gold"]', '["a"]', 'properly, incised or (active) incisive; hence (as noun masculine or feminine) a trench (as dug), gold (as mined), a threshing-sledge (having sharp teeth); (figuratively) determination; also eager decision, diligent, (fine) gold, pointed things, sharp, threshing instrument, wall.', 'or חָרֻץ; passive participle of 2782;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2428G}/H9024/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["wealth/ its"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5804}/[H5794]', 'inflected', 'heb', 'עַזָּה', '["ʻAzzâh"]', '["and/ Gaza"]', '["n-f"]', 'Azzah, a place in Palestine Azzah, Gaza.', 'feminine of 5794; strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2342I}/[H2342]', 'inflected', 'heb', 'חוּל', '["chûwl"]', '["so/ it may be in anguish"]', '["v"]', 'properly, to twist or whirl (in a circular or spiral manner), i.e. (specifically) to dance, to writhe in pain (especially of parturition) or fear; figuratively, to wait, to pervert bear, (make to) bring forth, (make to) calve, dance, drive away, fall grievously (with pain), fear, form, great, grieve, (be) grievous, hope, look, make, be in pain, be much (sore) pained, rest, shake, shapen, (be) sorrow(-ful), stay, tarry, travail (with pain), tremble, trust, wait carefully (patiently), be wounded.', 'or חִיל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4007}/H9024/[H5027]', 'inflected', 'heb', 'מַבָּט', '["mabbâṭ"]', '["object of confidence/ its"]', '["n-m"]', 'something expected, i.e. (abstractly) expectation expectation.', 'or מֶבָּט; from 5027;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5804}/[H5794]', 'inflected', 'heb', 'עַזָּה', '["ʻAzzâh"]', '["from/ Gaza"]', '["n-f"]', 'Azzah, a place in Palestine Azzah, Gaza.', 'feminine of 5794; strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8251}/H9023/[H8262]', 'inflected', 'heb', 'שִׁקּוּץ', '["shiqqûwts"]', '["and/ detestable things/ its"]', '["n-m"]', 'disgusting, i.e. filthy; especially idolatrous or (concretely) an idol abominable filth (idol, -ation), detestable (thing).', 'or שִׁקֻּץ; from 8262;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0441B}/[H502]', 'inflected', 'heb', 'אַלּוּף', '["ʼallûwph"]', '["like/ a chief"]', '["a-m"]', 'familiar; a friend, also gentle; hence, a bullock (as being tame; applied, although masculine, to a cow); and so, a chieftain (as notable, like neat cattle) captain, duke, (chief) friend, governor, guide, ox.', 'or (shortened) אַלֻּף; from 502;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2983G}/[H2982]', 'inflected', 'heb', 'יְבוּסִי', '["Yᵉbûwçîy"]', '["[will be] like/ a Jebusite"]', '["n-m"]', 'a Jebusite or inhabitant of Jebus Jebusite(-s).', 'patrial from 2982;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1004B}/H9020/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["for/ house/ my"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4675}/[H4673]', 'lemma', 'heb', 'מַצָּבָה', '["matstsâbâh"]', '["a guard"]', '["n-f"]', 'a military guard army, garrison.', 'or מִצָּבָה; feminine of 4673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869A}/H9020\/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["with/ own eyes/ my"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4428G}/H9022/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["king/ your"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4915B}/H9023/[H4910]', 'inflected', 'heb', 'מֹשֶׁל', '["môshel"]', '["and/ dominion/ his"]', '["n-m"]', 'empire; a parallel dominion, like.', '(1) from 4910; (2) from 4911;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1285}/H9022/[H1262]', 'inflected', 'heb', 'בְּרִית', '["bᵉrîyth"]', '["covenant/ your"]', '["n-f"]', 'a compact (because made by passing between pieces of flesh) confederacy, (con-) feder(-ate), covenant, league.', 'from 1262 (in the sense of cutting [like 1254]);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0615}/H9022/[H631]', 'inflected', 'heb', 'אָסִיר', '["ʼâçîyr"]', '["prisoners/ your"]', '["n-m"]', 'bound, i.e. a captive (those which are) bound, prisoner.', 'from 631;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1225}/[H1219]', 'inflected', 'heb', 'בִּצָּרוֹן', '["bitstsârôwn"]', '["to/ [the] stronghold"]', '["n-m"]', 'a fortress stronghold.', 'masculine intensive from 1219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8615B}/[H6960]', 'inflected', 'heb', 'תִּקְוָה', '["tiqvâh"]', '["<the>/ hope"]', '["n-f"]', 'literally a cord (as an attachment); figuratively, expectancy expectation(-ted), hope, live, thing that I long for.', 'from 6960; (compare 6961)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121G}/H9022/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["sons/ your"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7760H}/H9032/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ I will make/ you"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1300B}/[H1299]', 'inflected', 'heb', 'בָּרָק', '["bârâq"]', '["like <the>/ lightning"]', '["n-m"]', 'lightning; by analogy, a gleam; concretely, a flashing sword bright, glitter(-ing sword), lightning.', 'from 1299;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4219}/[H2236]', 'inflected', 'heb', 'מִזְרָק', '["mizrâq"]', '["[will be] like the/ bowls","like <the>/ bowl"]', '["n-m"]', 'a bowl (as if for sprinkling) bason, bowl.', 'from 2236;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5264}/[H5251]', 'lemma', 'heb', 'נָסַס', '["nâçaç"]', '["[will] display themselves"]', '["v"]', 'to raise a beacon lift up as an ensign.', 'a primitive root; to gleam from afar, i.e. to be conspicuous as a signal; or rather perhaps a denominative from 5251 (and identical with 5263, through the idea of a flag as fluttering in the wind);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3308}/H9023/[H3302]', 'inflected', 'heb', 'יֳפִי', '["yŏphîy"]', '["[will be] beauty/ its"]', '["n-m"]', 'beauty beauty.', 'from 3302;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2385>', 'opaque', 'heb', 'חֲזִיז', '["chăzîyz"]', '["thunder-clouds"]', '["n-m"]', 'a flash of lightning bright cloud, lightning.', 'from an unused root meaning to glare;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5162G}/H9013/[H5162]', 'inflected', 'heb', 'נָחַם', '["nâcham"]', '["they comfort/ !"]', '["v"]', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2916>', 'inflected', 'heb', 'בטיט', '["be./Tit"]', '["in/ [the] mud of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6030B}/H9038/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["and/ I will answer/ them"]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6908}/H9038/[H6908]', 'inflected', 'heb', 'קָבַץ', '["qâbats"]', '["and/ I will gather/ them"]', '["v"]', 'to grasp, i.e. collect assemble (selves), gather (bring) (together, selves together, up), heap, resort, × surely, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2232}/H9038/[H2232]', 'inflected', 'heb', 'זָרַע', '["zâraʻ"]', '["and/ I will sow/ them"]', '["v"]', 'to sow; figuratively, to disseminate, plant, fructify bear, conceive seed, set with sow(-er), yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4801}/[H7368]', 'inflected', 'heb', 'מֶרְחָק', '["merchâq"]', '["and/ in the/ distant places"]', '["n-m"]', 'remoteness, i.e. (concretely) a distant place; often (adverbially) from afar (a-, dwell in, very) far (country, off). See also 1023.', '; from 7368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0804G}/[H833]', 'inflected', 'heb', 'אַשּׁוּר', '["ʼAshshûwr"]', '["and/ from/ Assyria"]', '["n-pr-m n-pr-loc"]', 'Ashshur, the second son of Shem; also his descendants and the country occupied by them (i.e. Assyria), its region and its empire Asshur, Assur, Assyria, Assyrians. See 838.', 'or אַשֻּׁר; apparently from 833 (in the sense of successful);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1396}/H9038/[H1396]', 'inflected', 'heb', 'גָּבַר', '["gâbar"]', '["and/ I will make strong/ them"]', '["v"]', 'to be strong; by implication, to prevail, act insolently exceed, confirm, be great, be mighty, prevail, put to more (strength), strengthen, be stronger, be valiant.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1817C}/H9021/[H1802]', 'inflected', 'heb', 'דֶּלֶת', '["deleth"]', '["doors/ your"]', '["n-m n-f"]', 'something swinging, i.e. the valve of a door door (two-leaved), gate, leaf, lid. (Psalm 141:3).', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0730}/H9021/[H729]', 'inflected', 'heb', 'אֶרֶז', '["ʼerez"]', '["<in>/ cedars/ your"]', '["n-m"]', 'a cedar tree (from the tenacity of its roots) cedar (tree).', 'from 729;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1210}/[H1219]', 'inflected', 'heb', 'בָּצִיר', '["bâtsîyr"]', '["of the/ vintage"]', '["n-m"]', 'clipped, i.e. the grape crop vintage.', 'from 1219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3215}/[H3214]', 'lemma', 'heb', 'יְלָלָה', '["yᵉlâlâh"]', '["[the] wailing of"]', '["n-f"]', 'a howling a howling.', 'feminine of 3214');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0155}/H9028/[H117]', 'inflected', 'heb', 'אַדֶּרֶת', '["ʼaddereth"]', '["splendor/ their"]', '["n-f"]', 'something ample (as a large vine, a wide dress) garment, glory, goodly, mantle, robe.', 'feminine of 117; ; also the same as 145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2028H}/[H2027]', 'inflected', 'heb', 'הֲרֵגָה', '["hărêgâh"]', '["<the>/ slaughter"]', '["n-f"]', 'slaughter slaughter.', 'feminine of 2027;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7069}/H9039/[H7069]', 'inflected', 'heb', 'קָנָה', '["qânâh"]', '["[those who] buy/ them"]', '["v"]', 'to erect, i.e. create; by extension, to procure, especially by purchase (causatively, sell); by implication to own attain, buy(-er), teach to keep cattle, get, provoke to jealousy, possess(-or), purchase, recover, redeem, × surely, × verily.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2026}/H9039/[H2026]', 'inflected', 'heb', 'הָרַג', '["hârag"]', '["they will kill/ them"]', '["v"]', 'to smite with deadly intent destroy, out of hand, kill, murder(-er), put to (death), make (slaughter), slay(-er), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4376}/H9039/[H4376]', 'inflected', 'heb', 'מָכַר', '["mâkar"]', '["and/ [those who] sell/ them"]', '["v"]', 'to sell, literally (as merchandise, a daughter in marriage, into slavery), or figuratively (to surrender) × at all, sell (away, -er, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7462B}/H9028/[H7462]', 'inflected', 'heb', 'רָעָה', '["râʻâh"]', '["and/ shepherds/ their"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2256C}/[H2254]', 'lemma', 'heb', 'חֶבֶל', '["chebel"]', '["Union"]', '["n-m"]', 'a rope (as twisted), especially a measuring line; by implication, a district or inheritance (as measured); or a noose (as of cords); figuratively, a company (as if tied together); a throe (especially of parturition); also ruin band, coast, company, cord, country, destruction, line, lot, pain, pang, portion, region, rope, snare, sorrow, tackling.', 'or חֵבֶל; from 2254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0973A}/[H973]', 'lemma', 'heb', 'בָּחַל', '["bâchal"]', '["it loathed"]', '["v"]', 'to loath abhor, get hastily (from the margin for 926).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3582}/[H3582]', 'inflected', 'heb', 'כָּחַד', '["kâchad"]', '["and/ the/ [one which] is being destroyed"]', '["v"]', 'to secrete, by act or word; hence (intensively) to destroy conceal, cut down (off), desolate, hide.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4731>/H9020', 'opaque', 'heb', 'מַקֵּל', '["maqqêl"]', '["staff/ my"]', '["n-m"]', 'a shoot, i.e. stick (with leaves on, or for walking, striking, guiding, divining) rod, (hand-)staff.', 'or (feminine) מַקְּלָה; from an unused root meaning apparently to germinate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3366}/[H3365]', 'inflected', 'heb', 'יְקָר', '["yᵉqâr"]', '["the/ value"]', '["n-m"]', 'value, i.e. (concretely) wealth; abstractly, costliness, dignity honour, precious (things), price.', 'from 3365;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3947G}/H9012/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["and/ I took/ !"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2256C}/[H2254]', 'inflected', 'heb', 'חֶבֶל', '["chebel"]', '["<the>/ Union"]', '["n-m"]', 'a rope (as twisted), especially a measuring line; by implication, a district or inheritance (as measured); or a noose (as of cords); figuratively, a company (as if tied together); a throe (especially of parturition); also ruin band, coast, company, cord, country, destruction, line, lot, pain, pang, portion, region, rope, snare, sorrow, tackling.', 'or חֵבֶל; from 2254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0264}/[H251]', 'inflected', 'heb', 'אַחֲוָה', '["ʼachăvâh"]', '["the/ brotherhood"]', '["n-m"]', 'fraternity brotherhood.', 'from 251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0196}/[H191]', 'lemma', 'heb', 'אֱוִלִי', '["ʼĕvilîy"]', '["foolish"]', '["a"]', 'silly, foolish; hence (morally) impious foolish.', 'from 191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3582}/[H3582]', 'inflected', 'heb', 'כָּחַד', '["kâchad"]', '["those/ [which] are being destroyed"]', '["v"]', 'to secrete, by act or word; hence (intensively) to destroy conceal, cut down (off), desolate, hide.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5289}/[H5287]', 'inflected', 'heb', 'נַעַר', '["naʻar"]', '["the/ young man"]', '["n-m"]', 'a wanderer young one.', 'from 5287 in its derivative sense of tossing about;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6541}/H9029/[H6538]', 'inflected', 'heb', 'פַּרְסָה', '["parçâh"]', '["and/ hooves/ their"]', '["n-f"]', 'a claw or split hoof claw, (cloven-) footed, hoof.', 'feminine of 6538;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6561}\/[H6561]', 'inflected', 'heb', 'פָּרַק', '["pâraq"]', '["he will tear off"]', '["v"]', 'to break off or crunch; figuratively, to deliver break (off), deliver, redeem, rend (in pieces), tear in pieces.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3543A}\/[H3543]', 'inflected', 'heb', 'כָּהָה', '["kâhâh"]', '["it will grow dim"]', '["v"]', 'to be weak, i.e. (figuratively) to despond (causatively, rebuke), or (of light, the eye) to grow dull darken, be dim, fail, faint, restrain, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3335G}/[H3334]', 'inflected', 'heb', 'יָצַר', '["yâtsar"]', '["and/ [who] formed"]', '["v"]', 'to mould into a form; especially as a potter; figuratively, to determine (i.e. form a resolution) × earthen, fashion, form, frame, make(-r), potter, purpose.', 'probably identical with 3334 (through the squeezing into shape); (compare 3331);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7130G}/H9023\/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["in/ inner being/ his"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7478}/[H7477]', 'lemma', 'heb', 'רַעַל', '["raʻal"]', '["reeling"]', '["n-m"]', 'a reeling (from intoxication) trembling.', 'from 7477;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4614}/[H6006]', 'lemma', 'heb', 'מַעֲמָסָה', '["maʻămâçâh"]', '["burden"]', '["n-f"]', 'burdensomeness burdensome.', 'from 6006;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6006}/H9034/[H6006]', 'inflected', 'heb', 'עָמַס', '["ʻâmaç"]', '["[those who] carry/ it"]', '["v"]', 'to load, i.e. impose a burden (or figuratively, infliction) be borne, (heavy) burden (self), lade, load, put.', 'or עָמַשׂ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8541}/[H8539]', 'inflected', 'heb', 'תִּמָּהוֹן', '["timmâhôwn"]', '["with <the>/ bewilderment"]', '["n-m"]', 'consternation astonishment.', 'from 8539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5788A}/[H5787]', 'inflected', 'heb', 'עִוָּרוֹן', '["ʻivvârôwn"]', '["with <the>/ blindness"]', '["n-m"]', 'blindness blind(-ness).', 'and (feminine) עַוֶּרֶת; from 5787;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0556}/[H553]', 'lemma', 'heb', 'אַמְצָה', '["ʼamtsâh"]', '["[are] strength"]', '["n-f"]', 'force strength.', 'from 553;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3595}/[H3564]', 'inflected', 'heb', 'כִּיּוֹר', '["kîyôwr"]', '["like/ a pot of"]', '["n-m"]', 'properly, something round (as excavated or bored), i.e. a chafing-dish for coals or a caldron for cooking; hence (from similarity of form) a washbowl; also (for the same reason) a pulpit or platform hearth, laver, pan, scaffold.', 'or כִּיֹּר; from the same as 3564;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/<H3940>', 'inflected', 'heb', 'וכלפיד', '["u./khe./la.Pid"]', '["and/ like/ a torch of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5995}/[H6014]', 'inflected', 'heb', 'עָמִיר', '["ʻâmîyr"]', '["among/ cut grain"]', '["n-m"]', 'a bunch of grain handful, sheaf.', 'from 6014;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3782}/[H3782]', 'inflected', 'heb', 'כָּשַׁל', '["kâshal"]', '["the/ [one who] stumbles"]', '["v"]', 'to totter or waver (through weakness of the legs, especially the ankle); by implication, to falter, stumble, faint or fall bereave (from the margin), cast down, be decayed, (cause to) fail, (cause, make to) fall (down, -ing), feeble, be (the) ruin(-ed, of), (be) overthrown, (cause to) stumble, × utterly, be weak.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4553}/[H5594]', 'inflected', 'heb', 'מִסְפֵּד', '["miçpêd"]', '["like/ [the] mourning of","like/ mourning"]', '["n-m"]', 'a lamentation lamentation, one mourneth, mourning, wailing.', 'from 5594;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3173}/[H3161]', 'inflected', 'heb', 'יָחִיד', '["yâchîyd"]', '["<the>/ only [son]"]', '["a"]', 'properly, united, i.e. sole; by implication, beloved; also lonely; (feminine) the life (as not to be replaced) darling, desolate, only (child, son), solitary.', 'from 3161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4843}/[H4752]', 'inflected', 'heb', 'מָרַר', '["mârar"]', '["as/ shows bitterness"]', '["v"]', 'to be (causatively, make) bitter (literally or figuratively) (be, be in, deal, have, make) bitter(-ly, -ness), be moved with choler, (be, have sorely, it) grieved(-eth), provoke, vex.', 'a primitive root; properly, to trickle (see 4752); but used only as a denominative from 4751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4553}/[H5594]', 'inflected', 'heb', 'מִסְפֵּד', '["miçpêd"]', '["the/ mourning"]', '["n-m"]', 'a lamentation lamentation, one mourneth, mourning, wailing.', 'from 5594;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1910}/[H1908]', 'lemma', 'heb', 'הֲדַדְרִמּוֹן', '["Hădadrimmôwn"]', '["Hadad-","Rimmon"]', '["n-pr-loc"]', 'Hadad-Rimmon, a place in Palestine Hadad-rimmon.', 'from 1908 and 7417;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0905H}\/[H909]', 'inflected', 'heb', 'בַּד', '["bad"]', '["<to>/ alone"]', '["n-m"]', 'properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5079}/[H5074]', 'inflected', 'heb', 'נִדָּה', '["niddâh"]', '["and/ for/ impurity"]', '["n-f"]', 'properly, rejection; by implication, impurity, especially personal (menstruation) or moral (idolatry, incest) × far, filthiness, × flowers, menstruous (woman), put apart, × removed (woman), separation, set apart, unclean(-ness, thing, with filthiness).', 'from 5074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5012}/H9043/[H5012]', 'inflected', 'heb', 'נָבָא', '["nâbâʼ"]', '["when/ prophecies/ he"]', '["v"]', 'to prophesy, i.e. speak (or sing) by inspiration (in prediction or simple discourse) prophesy(-ing), make self a prophet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2384}/H9023/[H2372]', 'inflected', 'heb', 'חִזָּיוֹן', '["chizzâyôwn"]', '["from/ vision/ his"]', '["n-m"]', 'a revelation, expectation by dream vision.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0157H}/H9030\/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["friends/ my"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5997}/H9020/[H5997]', 'inflected', 'heb', 'עָמִית', '["ʻâmîyth"]', '["community/ my"]', '["n-m"]', 'companionship; hence (concretely) a comrade or kindred man another, fellow, neighbour.', 'from a primitive root meaning to associate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6819}/[H6819]', 'inflected', 'heb', 'צָעַר', '["tsâʻar"]', '["the/ little [ones]"]', '["v"]', 'to be small, i.e. (figuratively) ignoble be brought low, little one, be small.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6884}/H9038/[H6884]', 'inflected', 'heb', 'צָרַף', '["tsâraph"]', '["and/ I will refine/ them"]', '["v"]', 'to fuse (metal), i.e. refine (literally or figuratively) cast, (re-) fine(-er), founder, goldsmith, melt, pure, purge away, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0974}/[H974]', 'inflected', 'heb', 'בָּחַן', '["bâchan"]', '["as/ tests"]', '["v"]', 'to test (especially metals); generally and figuratively, to investigate examine, prove, tempt, try (trial).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7998}/H9022/[H7997]', 'inflected', 'heb', 'שָׁלָל', '["shâlâl"]', '["plunder/ your"]', '["n-m"]', 'booty prey, spoil.', 'from 7997;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3898A}/H9043/[H3898]', 'inflected', 'heb', 'לָחַם', '["lâcham"]', '["fought/ he"]', '["v"]', 'to feed on; figuratively, to consume; by implication, to battle (as destruction) devour, eat, × ever, fight(-ing), overcome, prevail, (make) war(-ring).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2677}/H9023/[H2673]', 'inflected', 'heb', 'חֵצִי', '["chêtsîy"]', '["from/ middle/ its"]', '["n-m"]', 'the half or middle half, middle, mid(-night), midst, part, two parts.', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2677}/H9023/[H2673]', 'inflected', 'heb', 'חֵצִי', '["chêtsîy"]', '["and/ half of/ it"]', '["n-m"]', 'the half or middle half, middle, mid(-night), midst, part, two parts.', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0682B}/[H680]', 'lemma', 'heb', 'אָצֵל', '["ʼÂtsêl"]', '["Azal"]', '["n-pr-m n-pr-loc"]', 'Atsel, the name of an Israelite, and of a place in Palestine Azal, Azel.', 'from 680; noble;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7087B}/[H7087]', 'inflected', 'heb', 'קָפָא', '["qâphâʼ"]', '["and/ frost"]', '["v n-m"]', 'to shrink, i.e. thicken (as unracked wine, curdled milk, clouded sky, frozen water) congeal, curdle, dark, settle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2677}/H9028/[H2673]', 'inflected', 'heb', 'חֵצִי', '["chêtsîy"]', '["half of/ them"]', '["n-m"]', 'the half or middle half, middle, mid(-night), midst, part, two parts.', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2779}/[H2778]', 'inflected', 'heb', 'חֹרֶף', '["chôreph"]', '["and/ in the/ winter"]', '["n-m"]', 'properly, the crop gathered, i.e. (by implication) the autumn (and winter) season; figuratively, ripeness of age cold, winter (-house), youth.', 'from 2778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7417G}/[H7416]', 'inflected', 'heb', 'רִמּוֹן', '["Rimmôwn"]', '["to/ Rimmon"]', '["n-pr-m n-pr-loc"]', 'Rimmon, the name of a Syrian deity, also of five places in Palestine Remmon, Rimmon.', 'or (shorter) (רִמֹּן; or רִמּוֹנוֹ; (1 Chronicles 6:62 (77)), the same as 7416; in Joshua 19:13: הַמְּתֹאָר is mistaken for part of a name; article with the passive participle of 8388; the (one) marked off, i.e. which pertains).');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7213}/[H7213]', 'inflected', 'heb', 'רָאַם', '["râʼam"]', '["and/ it will rise"]', '["v"]', 'to rise be lifted up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/H9006/{H8179G}/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["<to>/ from/ [the] gate of"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1144M}/[H1121]', 'lemma', 'heb', 'בִּנְיָמִין', '["Binyâmîyn"]', '["Benjamin"]', '["n-pr-m"]', 'Binjamin, youngest son of Jacob; also the tribe descended from him, and its territory Benjamin.', 'from 1121 and 3225; son of (the) right hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H6434>', 'inflected', 'heb', 'הפנים', '["ha./pi.Nim"]', '["the/ corners"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2764A}/[H2763]', 'inflected', 'heb', 'חֵרֶם', '["chêrem"]', '["and/ total destruction"]', '["n-m"]', 'physical (as shutting in) a net (either literally or figuratively); usually a doomed object; abstractly extermination (ac-) curse(-d, -d thing), dedicated thing, things which should have been utterly destroyed, (appointed to) utter destruction, devoted (thing), net.', 'or (Zechariah 14:11) חֶרֶם; from 2763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2356}/H9029/[H2352]', 'inflected', 'heb', 'חוֹר', '["chôwr"]', '["in/ sockets/ their"]', '["n-m"]', 'a cavity, socket, den cave, hole.', 'or (shortened) חֹר; the same as 2352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4046}/[H5062]', 'inflected', 'heb', 'מַגֵּפָה', '["maggêphâh"]', '["like the/ plague"]', '["n-f"]', 'a pestilence; by analogy, defeat (× be) plague(-d), slaughter, stroke.', 'from 5062;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2287}/[H2283]', 'inflected', 'heb', 'חָגַג', '["châgag"]', '["and/ to/ celebrate a festival"]', '["v"]', 'properly, to move in a circle, i.e. (specifically) to march in a sacred procession, to observe a festival; by implication, to be giddy celebrate, dance, (keep, hold) a (solemn) feast (holiday), reel to and fro.', 'a primitive root (compare 2283, 2328);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2287}/[H2283]', 'inflected', 'heb', 'חָגַג', '["châgag"]', '["to/ celebrate a festival"]', '["v"]', 'properly, to move in a circle, i.e. (specifically) to march in a sacred procession, to observe a festival; by implication, to be giddy celebrate, dance, (keep, hold) a (solemn) feast (holiday), reel to and fro.', 'a primitive root (compare 2283, 2328);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2403I}/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["and/ [the] punishment for sin of"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4698}/[H6750]', 'lemma', 'heb', 'מְצִלָּה', '["mᵉtsillâh"]', '["[the] bells of"]', '["n-f"]', 'a tinkler, i.e. a bell bell.', 'from 6750;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4401}/[H4397]', 'lemma', 'heb', 'מַלְאָכִי', '["Malʼâkîy"]', '["Malachi"]', '["n-pr-m"]', 'Malaki, a prophet Malachi.', 'from the same as 4397; ministrative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0157G}/H9035/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["have you loved/ us"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4172A}/H9020/[H3372]', 'inflected', 'heb', 'מוֹרָא', '["môwrâʼ"]', '["[is] fear/ my"]', '["n-m"]', 'fear; by implication, a fearful thing or deed dread, (that ought to be) fear(-ed), terribleness, terror.', 'or מֹרָא; or מוֹרָהxlit môrâh corrected to môwrâh; (Psalm 9:20), from 3372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1351}/H9031/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["have we defiled/ you"]', '["v"]', 'to soil or (figuratively) desecrate defile, pollute, stain.', 'a primitive root, (rather identified with 1350, through the idea of freeing, i.e. repudiating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0559}/H9046/[H559]', 'inflected', 'heb', 'אָמַר', '["ʼâmar"]', '["by/ saying/ you"]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5066H}/H9013/[H5066]', 'inflected', 'heb', 'נָגַשׁ', '["nâgash"]', '["you bring near/ !"]', '["v"]', 'to be or come (causatively, bring) near (for any purpose); euphemistically, to lie with a woman; as an enemy, to attack; religious to worship; causatively, to present; figuratively, to adduce an argument; by reversal, to stand back (make to) approach (nigh), bring (forth, hither, near), (cause to) come (hither, near, nigh), give place, go hard (up), (be, draw, go) near (nigh), offer, overtake, present, put, stand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H6346>/H9021', 'inflected', 'heb', 'לפחתך', '["le./fe.cha.Te./kha"]', '["to/ governor/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7521}/H9031/[H7521]', 'inflected', 'heb', 'רָצָה', '["râtsâh"]', '["¿/ will he be pleased with/ you"]', '["v"]', 'to be pleased with; specifically, to satisfy a debt (be) accept(-able), accomplish, set affection, approve, consent with, delight (self), enjoy, (be, have a) favour(-able), like, observe, pardon, (be, have, take) please(-ure), reconcile self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5375Q}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["¿/ will he lift up"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2603A}/H9035/[H2583]', 'inflected', 'heb', 'חָנַן', '["chânan"]', '["so/ he may show favor to/ us"]', '["v"]', 'properly, to bend or stoop in kindness to an inferior; to favor, bestow; causatively to implore (i.e. move to favor by petition) beseech, × fair, (be, find, shew) favour(-able), be (deal, give, grant (gracious(-ly), intreat, (be) merciful, have (shew) mercy (on, upon), have pity upon, pray, make supplication, × very.', 'a primitive root (compare 2583);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3027H}/H9026/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["from/ hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6999B}/[H6999]', 'lemma', 'heb', 'קָטַר', '["qâṭar"]', '["incense"]', '["v n-m n-f"]', 'to smoke, i.e. turn into fragrance by fire (especially as an act of worship) burn (incense, sacrifice) (upon), (altar for) incense, kindle, offer (incense, a sacrifice).', 'a primitive root (identical with through the idea of fumigation in a close place and perhaps thus driving out the occupants);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5108B}/H9023/[H5107]', 'inflected', 'heb', 'נוֹב', '["nôwb"]', '["and/ fruit/ its"]', '["n-m"]', 'produce, literally or figuratively fruit.', 'or נֵיב; from 5107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4100}/{H8513}/[H4100]', 'inflected', 'heb', 'מָה', '["mâh"]', '["what/ weariness!"]', '["i"]', 'properly, interrogative what? (including how? why? when?); but also exclamation, what! (including how!), or indefinitely what (including whatever, and even relatively, that which); often used with prefixes in various adverbial or conjunctive senses how (long, oft, (-soever)), (no-) thing, what (end, good, purpose, thing), whereby(-fore, -in, -to, -with), (for) why.', 'or מַה; or מָ; or מַ; also מֶה; a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5739}/H9023/[H5737]', 'inflected', 'heb', 'עֵדֶר', '["ʻêder"]', '["among/ flock/ his"]', '["n-m"]', 'an arrangement, i.e. muster (of animals) drove, flock, herd.', 'from 5737;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5087}/[H5087]', 'inflected', 'heb', 'נָדַר', '["nâdar"]', '["and/ [one who] makes a vow"]', '["v"]', 'to promise (pos., to do or give something to God) (make a) vow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0779}/[H779]', 'inflected', 'heb', 'אָרַר', '["ʼârar"]', '["and/ I will curse"]', '["v"]', 'to execrate × bitterly curse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1293}/H9026/[H1288]', 'inflected', 'heb', 'בְּרָכָה', '["Bᵉrâkâh"]', '["blessings/ your"]', '["n-f"]', 'benediction; by implication prosperity blessing, liberal, pool, present.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6569}/[H6567]', 'lemma', 'heb', 'פֶּרֶשׁ', '["peresh"]', '["[the] dung of","dung"]', '["n-m"]', 'excrement (as eliminated) dung.', 'from 6567;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4172A}/[H3372]', 'lemma', 'heb', 'מוֹרָא', '["môwrâʼ"]', '["fear"]', '["n-m"]', 'fear; by implication, a fearful thing or deed dread, (that ought to be) fear(-ed), terribleness, terror.', 'or מֹרָא; or מוֹרָהxlit môrâh corrected to môwrâh; (Psalm 9:20), from 3372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3372H}/H9030/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["and/ he feared/ me"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8451}\/[H3384]', 'inflected', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["in <the>/ instruction"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1254A}/H9035/[H1254]', 'inflected', 'heb', 'בָּרָא', '["bârâʼ"]', '["did he create/ us"]', '["v"]', '(absolutely) to create; (qualified) to cut down (a wood), select, feed (as formative processes) choose, create (creator), cut down, dispatch, do, make (fat).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1166I}/[H1167]', 'inflected', 'heb', 'בָּעַל', '["bâʻal"]', '["and/ it has married"]', '["v"]', 'to be master; hence, to marry have dominion (over), be husband, marry(-ried, × wife).', 'a primitive root; also as denominative from 1167');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0603}/[H602]', 'inflected', 'heb', 'אֲנָקָה', '["ʼănâqâh"]', '["and/ groaning"]', '["n-f"]', 'shrieking crying out, groaning, sighing.', 'from 602;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2278}/H9021/[H2270]', 'inflected', 'heb', 'חֲבֶרֶת', '["chăbereth"]', '["[was] companion/ your"]', '["n-f"]', 'a consort companion.', 'feminine of 2270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7307G}/H9026/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["in/ spirit/ your"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0898}\/[H898]', 'inflected', 'heb', 'בָּגַד', '["bâgad"]', '["you must act treacherously"]', '["v"]', 'to cover (with a garment); figuratively, to act covertly; by implication, to pillage deal deceitfully (treacherously, unfaithfully), offend, transgress(-or), (depart), treacherous (dealer, -ly, man), unfaithful(-ly, man), × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1697G}/H9026/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["with/ words/ your"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4397G>/H9020', 'opaque', 'heb', 'מַלְאָךְ', '["malʼâk"]', '["messenger/ my"]', '["n-m"]', 'a messenger; specifically, of God, i.e. an angel (also a prophet, priest or teacher) ambassador, angel, king, messenger.', 'from an unused root meaning to despatch as a deputy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6597}/[H6621]', 'inflected', 'heb', 'פִּתְאוֹם', '["pithʼôwm"]', '["and/ suddenly"]', '["adv"]', 'instantly straightway, sudden(-ly).', 'or פִּתְאֹם; from 6621;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H1287}/[H1253]', 'inflected', 'heb', 'בֹּרִית', '["bôrîyth"]', '["and/ like/ [the] soap of"]', '["n-f"]', 'vegetable alkali sope.', 'feminine of 1253;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2212}/[H2212]', 'inflected', 'heb', 'זָקַק', '["zâqaq"]', '["and/ he will refine"]', '["v"]', 'to strain, (figuratively) extract, clarify fine, pour down, purge, purify, refine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H3701G}/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["and/ like <the>/ silver"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H8141}/[H8138]', 'inflected', 'heb', 'שָׁנֶה', '["shâneh"]', '["and/ like/ years"]', '["n-f"]', 'a year (as a revolution of time) whole age, × long, old, year(× -ly).', '(in plural or (feminine) שָׁנָה; from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3784}/[H3784]', 'inflected', 'heb', 'כָּשַׁף', '["kâshaph"]', '["on the/ sorcerers"]', '["v"]', 'properly, to whisper a spell, i.e. to inchant or practise magic sorcerer, (use) witch(-craft).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5003}/[H5003]', 'inflected', 'heb', 'נָאַף', '["nâʼaph"]', '["and/ on the/ adulterers"]', '["v"]', 'to commit adultery; figuratively, to apostatize adulterer(-ess), commit(-ing) adultery, woman that breaketh wedlock.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7650}/[H7651]', 'inflected', 'heb', 'שָׁבַע', '["shâbaʻ"]', '["and/ on <the>/ [those who] swear an oath"]', '["v"]', 'to seven oneself, i.e. swear (as if by repeating a declaration seven times) adjure, charge (by an oath, with an oath), feed to the full (by mistake for 7646), take an oath, × straitly, (cause to, make to) swear.', 'a primitive root; properly to be complete, but used only as a denominative from 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6231}/[H6229]', 'inflected', 'heb', 'עָשַׁק', '["ʻâshaq"]', '["and/ on/ [those who] defraud"]', '["v"]', 'to press upon, i.e. oppress, defraud, violate, overflow get deceitfully, deceive, defraud, drink up, (use) oppress(-ion), -or), do violence (wrong).', 'a primitive root (compare 6229);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3372H}/H9030/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["they fear/ me"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2706G}/H9020/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["from/ statutes/ my"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H6906}/[H6906]', 'inflected', 'heb', 'קָבַע', '["qâbaʻ"]', '["¿/ will he rob"]', '["v"]', 'to cover, i.e. (figuratively) defraud rob, spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6906}/[H6906]', 'lemma', 'heb', 'קָבַע', '["qâbaʻ"]', '["[are] robbing"]', '["v"]', 'to cover, i.e. (figuratively) defraud rob, spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6906}/H9031/[H6906]', 'inflected', 'heb', 'קָבַע', '["qâbaʻ"]', '["have we robbed/ you"]', '["v"]', 'to cover, i.e. (figuratively) defraud rob, spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8641}/[H7311]', 'inflected', 'heb', 'תְּרוּמָה', '["tᵉrûwmâh"]', '["and/ the/ contribution"]', '["n-f"]', 'a present (as offered up), especially in sacrifice or as tribute gift, heave offering (shoulder), oblation, offered(-ing).', 'or תְּרֻמָה; (Deuteronomy 12:11), from 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3994}/[H779]', 'inflected', 'heb', 'מְאֵרָה', '["mᵉʼêrâh"]', '["with <the>/ curse"]', '["n-f"]', 'an execration curse.', 'from 779;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0974}/H9030/[H974]', 'inflected', 'heb', 'בָּחַן', '["bâchan"]', '["and/ test/ me"]', '["v"]', 'to test (especially metals); generally and figuratively, to investigate examine, prove, tempt, try (trial).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6941}/[H6937]', 'lemma', 'heb', 'קְדֹרַנִּית', '["qᵉdôrannîyth"]', '["mournfully"]', '["adv"]', 'blackish ones (i.e. in sackcloth); used adverbially, in mourning weeds mournfully.', 'adverb from 6937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2803H}/[H2803]', 'inflected', 'heb', 'חָשַׁב', '["châshab"]', '["and/ of/ [those who] esteemed"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5647H}/H9033\/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["he serves/ him"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6072}/[H6072]', 'inflected', 'heb', 'עָסַס', '["ʻâçaç"]', '["and/ you will tread down"]', '["v"]', 'to squeeze out juice; figuratively, to trample tread down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1]', 'root', 'heb', 'אָב', '["ʼâb"]', '["father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''."]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2}/[H2]', 'lemma', 'arc', 'אַב', '["ʼab"]', '["father."]', '["n-m"]', 'father.', '(Aramaic) corresponding to 1');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3}/[H3]', 'lemma', 'heb', 'אֵב', '["ʼêb"]', '["a green plant greenness, fruit."]', '["n-m"]', 'a green plant greenness, fruit.', 'from the same as 24;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4}/[H4]', 'lemma', 'arc', 'אֵב', '["ʼêb"]', '["fruit."]', '["n-m"]', 'fruit.', '(Aramaic) corresponding to 3');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5>', 'opaque', 'heb', 'אֲבַגְתָא', '["ʼĂbagthâʼ"]', '["Abagtha, a eunuch of Xerxes Abagtha."]', '["n-pr-m"]', 'Abagtha, a eunuch of Xerxes Abagtha.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6]', 'root', 'heb', 'אָבַד', '["ʼâbad"]', '["properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee."]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7}/[H7]', 'lemma', 'arc', 'אֲבַד', '["ʼăbad"]', '["destroy, perish."]', '["v"]', 'destroy, perish.', '(Aramaic) corresponding to 6');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8}/[H8]', 'lemma', 'heb', 'אֹבֵד', '["ʼôbêd"]', '["(concrete) wretched or (abstract) destruction perish."]', '["n-m"]', '(concrete) wretched or (abstract) destruction perish.', 'active of participle of 6;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H9}/[H9]', 'lemma', 'heb', 'אֲבֵדָה', '["ʼăbêdâh"]', '["concrete, something lost; abstract, destruction, i.e. Hades lost."]', '["n-f"]', 'concrete, something lost; abstract, destruction, i.e. Hades lost.', 'from 6; Compare 10.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H10}/[H10]', 'lemma', 'heb', 'אֲבַדֹּה', '["ʼăbaddôh"]', '["a perishing destruction."]', '["n-f"]', 'a perishing destruction.', 'the same as 9, miswritten for 11;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H11}/[H11]', 'lemma', 'heb', 'אֲבַדּוֹן', '["ʼăbaddôwn"]', '["abstract, a perishing; concrete, Hades destruction."]', '["n-pr-loc"]', 'abstract, a perishing; concrete, Hades destruction.', 'intensive from 6;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H12}/[H12]', 'lemma', 'heb', 'אַבְדָן', '["ʼabdân"]', '["a perishing destruction."]', '["n-m"]', 'a perishing destruction.', 'from 6;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H13}/[H13]', 'lemma', 'heb', 'אׇבְדַן', '["ʼobdan"]', '["a perishing destruction."]', '["n-m"]', 'a perishing destruction.', 'from 6;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H14]', 'root', 'heb', 'אָבָה', '["ʼâbâh"]', '["to breathe after, i.e. (figuratively) to be acquiescent consent, rest content will, be willing."]', '["v"]', 'to breathe after, i.e. (figuratively) to be acquiescent consent, rest content will, be willing.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H15}/[H15]', 'lemma', 'heb', 'אָבֶה', '["ʼâbeh"]', '["longing desire."]', '["n-f"]', 'longing desire.', 'from 14;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H16}/[H16]', 'lemma', 'heb', 'אֵבֶה', '["ʼêbeh"]', '["the papyrus swift."]', '["n-m"]', 'the papyrus swift.', 'from 14 (in the sense of bending toward);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H17}/[H17]', 'lemma', 'heb', 'אֲבוֹי', '["ʼăbôwy"]', '["want sorrow."]', '["inj"]', 'want sorrow.', 'from 14 (in the sense of desiring);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H18}/[H18]', 'lemma', 'heb', 'אֵבוּס', '["ʼêbûwç"]', '["a manger or stall crib."]', '["n-m"]', 'a manger or stall crib.', 'from 75;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H19>', 'opaque', 'heb', 'אִבְחָה', '["ʼibchâh"]', '["brandishing of a sword point."]', '["n-f"]', 'brandishing of a sword point.', 'from an unused root (apparently meaning to turn);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H20>', 'opaque', 'heb', 'אֲבַטִּיחַ', '["ʼăbaṭṭîyach"]', '["a melon (only plural) melon."]', '["n-m"]', 'a melon (only plural) melon.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H21}/[H21]', 'lemma', 'heb', 'אֲבִי', '["ʼĂbîy"]', '["Abi, Hezekiah''s mother Abi."]', '["n-pr-f"]', 'Abi, Hezekiah''s mother Abi.', 'from 1; fatherly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H22}/[H22]', 'lemma', 'heb', 'אֲבִיאֵל', '["ʼĂbîyʼêl"]', '["Abiel, the name of two Israelites Abiel."]', '["n-pr-m"]', 'Abiel, the name of two Israelites Abiel.', 'from 1 and 410; father (i.e. possessor) of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H23}/[H23]', 'lemma', 'heb', 'אֲבִיאָסָף', '["ʼĂbîyʼâçâph"]', '["Abiasaph, an Israelite Abiasaph."]', '["n-pr-m"]', 'Abiasaph, an Israelite Abiasaph.', 'from 1 and 622; father of gathering (i.e. gatherer);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H24>', 'opaque', 'heb', 'אָבִיב', '["ʼâbîyb"]', '["green, i.e. a young ear of grain; hence, the name of the month Abib or Nisan Abib, ear, green ears of corn (not maize)."]', '["n-m"]', 'green, i.e. a young ear of grain; hence, the name of the month Abib or Nisan Abib, ear, green ears of corn (not maize).', 'from an unused root (meaning to be tender);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H25}/[H25]', 'lemma', 'heb', 'אֲבִי גִבְעוֹן', '["ʼĂbîy Gibʻôwn"]', '["Abi-Gibon, perhaps an Israelite father of Gibeon."]', '["n-pr-m"]', 'Abi-Gibon, perhaps an Israelite father of Gibeon.', 'from 1 and 1391; father (i.e. founder) of Gibon;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H26}/[H26]', 'lemma', 'heb', 'אֲבִיגַיִל', '["ʼĂbîygayil"]', '["Abigail or Abigal, the name of two Israelitesses Abigal."]', '["n-pr-f"]', 'Abigail or Abigal, the name of two Israelitesses Abigal.', 'or shorter אֲבִיגַל; from 1 and 1524; father (i.e. source) of joy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H27}/[H27]', 'lemma', 'heb', 'אֲבִידָן', '["ʼĂbîydân"]', '["Abidan, an Israelite Abidan."]', '["n-pr-m"]', 'Abidan, an Israelite Abidan.', 'from 1 and 1777; father of judgment (i.e. judge);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H28}/[H28]', 'lemma', 'heb', 'אֲבִידָע', '["ʼĂbîydâʻ"]', '["Abida, a son of Abraham by Keturah Abida, Abidah."]', '["n-pr-m"]', 'Abida, a son of Abraham by Keturah Abida, Abidah.', 'from 1 and 3045; father of knowledge (i.e. knowing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H29}/[H29]', 'lemma', 'heb', 'אֲבִיָּה', '["ʼĂbîyâh"]', '["Abijah, the name of several Israelite men and two Israelitesses Abiah, Abijah."]', '["n-pr-m"]', 'Abijah, the name of several Israelite men and two Israelitesses Abiah, Abijah.', 'or prolonged אֲבִיָּהוּ ; from 1 and 3050; father (i.e. worshipper) of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H30}/[H30]', 'lemma', 'heb', 'אֲבִיהוּא', '["ʼĂbîyhûwʼ"]', '["Abihu, a son of Aaron Abihu."]', '["n-pr-m"]', 'Abihu, a son of Aaron Abihu.', 'from 1 and 1931; father (i.e. worshipper) of Him (i.e. God);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H31}/[H31]', 'lemma', 'heb', 'אֲבִיהוּד', '["ʼĂbîyhûwd"]', '["Abihud, the name of two Israelites Abihud."]', '["n-pr-m"]', 'Abihud, the name of two Israelites Abihud.', 'from 1 and 1935; father (i.e. possessor) of renown;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H32}/[H32]', 'lemma', 'heb', 'אֲבִיהַיִל', '["ʼĂbîyhayil"]', '["Abihail or Abichail, the name of three Israelites and two Israelitesses Abihail."]', '["n-pr-m"]', 'Abihail or Abichail, the name of three Israelites and two Israelitesses Abihail.', 'or (more correctly) אֲבִיחַיִל ; from 1 and 2428; father (i.e. possessor) of might;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H33}/[H33]', 'lemma', 'heb', 'אֲבִי הָעֶזְרִי', '["ʼĂbîy hâ-ʻEzrîy"]', '["an Abiezrite or descendant of Abiezer Abiezrite."]', '["n-pr-m"]', 'an Abiezrite or descendant of Abiezer Abiezrite.', 'from 44 with the article inserted; father of the Ezrite;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H34}/[H34]', 'lemma', 'heb', 'אֶבְיוֹן', '["ʼebyôwn"]', '["destitute beggar, needy, poor (man)."]', '["a-m"]', 'destitute beggar, needy, poor (man).', 'from 14, in the sense of want (especially in feeling);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H35}/[H35]', 'lemma', 'heb', 'אֲבִיּוֹנָה', '["ʼăbîyôwnâh"]', '["provocative of desire; the caper berry (from its stimulative taste) desire."]', '["n-f"]', 'provocative of desire; the caper berry (from its stimulative taste) desire.', 'from 14;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H36}/[H36]', 'lemma', 'heb', 'אֲבִיטוּב', '["ʼĂbîyṭûwb"]', '["Abitub, an Israelite Abitub."]', '["n-pr-m"]', 'Abitub, an Israelite Abitub.', 'from 1 and 2898; father of goodness (i.e. good);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H37}/[H37]', 'lemma', 'heb', 'אֲבִיטָל', '["ʼĂbîyṭâl"]', '["Abital, a wife of King David Abital."]', '["n-pr-f"]', 'Abital, a wife of King David Abital.', 'from 1 and 2919; father of dew (i.e. fresh);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H38}/[H38]', 'lemma', 'heb', 'אֲבִיָּם', '["ʼĂbîyâm"]', '["Abijam (or Abijah), a king of Judah Abijam."]', '["n-pr-m"]', 'Abijam (or Abijah), a king of Judah Abijam.', 'from 1 and 3220; father of (the) sea (i.e. seaman);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H39}/[H39]', 'lemma', 'heb', 'אֲבִימָאֵל', '["ʼĂbîymâʼêl"]', '["Abimael, a son of Joktan Abimael."]', '["n-pr-m"]', 'Abimael, a son of Joktan Abimael.', 'from 1 and an elsewhere unused (probably foreign) word; father of Mael (apparently some Arab tribe);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H40}/[H40]', 'lemma', 'heb', 'אֲבִימֶלֶךְ', '["ʼĂbîymelek"]', '["Abimelek, the name of two Philistine kings and of two Israelites Abimelech."]', '["n-pr-m"]', 'Abimelek, the name of two Philistine kings and of two Israelites Abimelech.', 'from 1 and 4428; father of (the) king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H41}/[H41]', 'lemma', 'heb', 'אֲבִינָדָב', '["ʼĂbîynâdâb"]', '["Abinadab, the name of four Israelites Abinadab."]', '["n-pr-m"]', 'Abinadab, the name of four Israelites Abinadab.', 'from 1 and 5068; father of generosity (i.e. liberal);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H42}/[H42]', 'lemma', 'heb', 'אֲבִינֹעַם', '["ʼĂbîynôʻam"]', '["Abinoam, an Israelite Abinoam."]', '["n-pr-m"]', 'Abinoam, an Israelite Abinoam.', 'from 1 and 5278; father of pleasantness (i.e. gracious);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H43}/[H43]', 'lemma', 'heb', 'אֶבְיָסָף', '["ʼEbyâçâph"]', '["Ebjasaph, an Israelite Ebiasaph."]', '["n-pr-m"]', 'Ebjasaph, an Israelite Ebiasaph.', 'contracted from 23;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H44}/[H44]', 'lemma', 'heb', 'אֲבִיעֶזֶר', '["ʼĂbîyʻezer"]', '["Abiezer, the name of two Israelites Abiezer."]', '["n-pr-m"]', 'Abiezer, the name of two Israelites Abiezer.', 'from 1 and 5829; father of help (i.e. helpful);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H45>', 'opaque', 'heb', 'אֲבִי־עַלְבוֹן', '["ʼĂbîy-ʻalbôwn"]', '["Abialbon, an Israelite Abialbon."]', '["n-pr-m"]', 'Abialbon, an Israelite Abialbon.', 'from 1 and an unused root of uncertain derivation; probably, father of strength (i.e. valiant);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H46}/[H46]', 'lemma', 'heb', 'אָבִיר', '["ʼâbîyr"]', '["mighty (spoken of God) mighty (one)."]', '["a-m"]', 'mighty (spoken of God) mighty (one).', 'from 82;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H47}/[H47]', 'lemma', 'heb', 'אַבִּיר', '["ʼabbîyr"]', '["angel, bull, chiefest, mighty (one), stout(-hearted), strong (one), valiant."]', '["a-m"]', 'angel, bull, chiefest, mighty (one), stout(-hearted), strong (one), valiant.', 'for 46');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H48}/[H48]', 'lemma', 'heb', 'אֲבִירָם', '["ʼĂbîyrâm"]', '["Abiram, the name of two Israelites Abiram."]', '["n-pr-m"]', 'Abiram, the name of two Israelites Abiram.', 'from 1 and 7311; father of height (i.e. lofty);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H49}/[H49]', 'lemma', 'heb', 'אֲבִישַׁג', '["ʼĂbîyshag"]', '["Abishag, a concubine of David Abishag."]', '["n-pr-f"]', 'Abishag, a concubine of David Abishag.', 'from 1 and 7686; father of error (i.e. blundering);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H50}/[H50]', 'lemma', 'heb', 'אֲבִישׁוּעַ', '["ʼĂbîyshûwaʻ"]', '["Abishua, the name of two Israelites Abishua."]', '["n-pr-m"]', 'Abishua, the name of two Israelites Abishua.', 'from 1 and 7771; father of plenty (i.e. prosperous);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H51}/[H51]', 'lemma', 'heb', 'אֲבִישׁוּר', '["ʼĂbîyshûwr"]', '["Abishur, an Israelite Abishur."]', '["n-pr-m"]', 'Abishur, an Israelite Abishur.', 'from 1 and 7791; father of (the) wall (i.e. perhaps mason);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H52}/[H52]', 'lemma', 'heb', 'אֲבִישַׁי', '["ʼĂbîyshay"]', '["Abishai, an Israelite Abishai."]', '["n-pr-m"]', 'Abishai, an Israelite Abishai.', 'or (shorter) אַבְשַׁי ; from 1 and 7862; father of a gift (i.e. probably generous);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H53}/[H53]', 'lemma', 'heb', 'אֲבִישָׁלוֹם', '["ʼĂbîyshâlôwm"]', '["Abshalom, a son of David; also (the fuller form) a later Israelite Abishalom, Absalom."]', '["n-pr-m"]', 'Abshalom, a son of David; also (the fuller form) a later Israelite Abishalom, Absalom.', 'or (shortened) אַבְשָׁלוֹם ; from 1 and 7965; father of peace (i.e. friendly);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H54}/[H54]', 'lemma', 'heb', 'אֶבְיָתָר', '["ʼEbyâthâr"]', '["Ebjathar, an Israelite Abiathar."]', '["n-pr-m"]', 'Ebjathar, an Israelite Abiathar.', 'contracted from 1 and 3498; father of abundance (i.e. liberal);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H55]', 'root', 'heb', 'אָבַךְ', '["ʼâbak"]', '["probably to coil upward mount up."]', '["v"]', 'probably to coil upward mount up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H56]', 'root', 'heb', 'אָבַל', '["ʼâbal"]', '["to bewail lament, mourn."]', '["v"]', 'to bewail lament, mourn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H57}/[H57]', 'lemma', 'heb', 'אָבֵל', '["ʼâbêl"]', '["lamenting mourn(-er, -ing)."]', '["a"]', 'lamenting mourn(-er, -ing).', 'from 56;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H58>', 'opaque', 'heb', 'אָבֵל', '["ʼâbêl"]', '["a meadow plain. Compare also the proper names beginning with Abel-."]', '["n-f"]', 'a meadow plain. Compare also the proper names beginning with Abel-.', 'from an unused root (meaning to be grassy);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H59}/[H59]', 'lemma', 'heb', 'אָבֵל', '["ʼÂbêl"]', '["Abel, the name of two places in Palestine. Abel."]', '["n-pr-loc"]', 'Abel, the name of two places in Palestine. Abel.', 'from 58; a meadow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H60}/[H60]', 'lemma', 'heb', 'אֵבֶל', '["ʼêbel"]', '["lamentation mourning."]', '["n-m"]', 'lamentation mourning.', 'from 56;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H61}/[H61]', 'lemma', 'heb', 'אֲבָל', '["ʼăbâl"]', '["nay, i.e. truly or yet but, indeed, nevertheless, verily."]', '["adv"]', 'nay, i.e. truly or yet but, indeed, nevertheless, verily.', 'apparently from 56 through the idea of negation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H62}/[H62]', 'lemma', 'heb', 'אָבֵל בֵּית־מֲעַכָה', '["ʼÂbêl Bêyth-Măʻakâh"]', '["Abel of Beth-maakah, a place in Palestine Abel-beth-maachah, Abel of Beth-maachah,"]', '["n-pr-loc"]', 'Abel of Beth-maakah, a place in Palestine Abel-beth-maachah, Abel of Beth-maachah,', 'from 58 and 1004 and 4601; meadow of Beth-Maakah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H63}/[H63]', 'lemma', 'heb', 'אָבֵל הַשִּׁטִּים', '["ʼÂbêl hash-Shiṭṭîym"]', '["Abel hash-Shittim, a place in Palestine Abelshittim."]', '["n-pr-loc"]', 'Abel hash-Shittim, a place in Palestine Abelshittim.', 'from 58 and the plural of 7848, with the article inserted; meadow of the acacias;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H64}/[H64]', 'lemma', 'heb', 'אָבֵל כְּרָמִים', '["ʼÂbêl Kᵉrâmîym"]', '["Abel-Keramim, a place in Palestine plain of the vineyards."]', '["n-pr-loc"]', 'Abel-Keramim, a place in Palestine plain of the vineyards.', 'from 58 and the plural of 3754; meadow of vineyards;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H65}/[H65]', 'lemma', 'heb', 'אָבֵל מְחוֹלָה', '["ʼÂbêl Mᵉchôwlâh"]', '["Abel-Mecholah, a place in Palestine Abel-meholah."]', '["n-pr-loc"]', 'Abel-Mecholah, a place in Palestine Abel-meholah.', 'from 58 and 4246; meadow of dancing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H66}/[H66]', 'lemma', 'heb', 'אַבֵל מַיִם', '["ʼAbêl Mayim"]', '["Abel-Majim, a place in Palestine Abel-maim."]', '["n-pr-loc"]', 'Abel-Majim, a place in Palestine Abel-maim.', 'from 58 and 4325; meadow of water;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H67}/[H67]', 'lemma', 'heb', 'אָבֵל מִצְרַיִם', '["ʼÂbêl Mitsrayim"]', '["Abel-Mitsrajim, a place in Palestine Abel-mizraim."]', '["n-pr-loc"]', 'Abel-Mitsrajim, a place in Palestine Abel-mizraim.', 'from 58 and 4714; meadow of Egypt;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H68}/[H68]', 'lemma', 'heb', 'אֶבֶן', '["ʼeben"]', '["a stone carbuncle, mason, plummet, (chalk-, hail-, head-, sling-) stone(-ny), (divers) weight(-s)."]', '["n-f"]', 'a stone carbuncle, mason, plummet, (chalk-, hail-, head-, sling-) stone(-ny), (divers) weight(-s).', 'from the root of 1129 through the meaning to build;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H69}/[H69]', 'lemma', 'arc', 'אֶבֶן', '["ʼeben"]', '["stone."]', '["n-f"]', 'stone.', '(Aramaic) corresponding to 68');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H70}/[H70]', 'lemma', 'heb', 'אֹבֶן', '["ʼôben"]', '["a pair of stones (only dual); a potter''s wheel or a midwife''s stool (consisting alike of two horizontal disks with a support between) wheel, stool."]', '["n-m"]', 'a pair of stones (only dual); a potter''s wheel or a midwife''s stool (consisting alike of two horizontal disks with a support between) wheel, stool.', 'from the same as 68;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H71}/[H71]', 'lemma', 'heb', 'אֲבָנָה', '["ʼĂbânâh"]', '["Abanah, a river near Damascus Abana."]', '["n"]', 'Abanah, a river near Damascus Abana.', 'perhaps feminine of 68; stony; Compare 549.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H72}/[H72]', 'lemma', 'heb', 'אֶבֶן הָעֵזֶר', '["ʼEben hâ-ʻÊzer"]', '["Eben-ha-Ezer, a place in Palestine Ebenezer."]', '["n"]', 'Eben-ha-Ezer, a place in Palestine Ebenezer.', 'from 68 and 5828 with the article inserted; stone of the help;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H73>', 'opaque', 'heb', 'אַבְנֵט', '["ʼabnêṭ"]', '["a belt girdle."]', '["n-m"]', 'a belt girdle.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H74}/[H74]', 'lemma', 'heb', 'אַבְנֵר', '["ʼAbnêr"]', '["Abner, an Israelite Abner."]', '["n-pr-m"]', 'Abner, an Israelite Abner.', 'or (fully) אֲבִינֵר ; from 1 and 5216; father of light (i.e. enlightening);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H75]', 'root', 'heb', 'אָבַס', '["ʼâbaç"]', '["to fodder fatted, stalled."]', '["v"]', 'to fodder fatted, stalled.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H76>', 'opaque', 'heb', 'אֲבַעְבֻּעָה', '["ʼăbaʻbuʻâh"]', '["an inflammatory pustule (as eruption) blains."]', '["n-f"]', 'an inflammatory pustule (as eruption) blains.', '(by reduplication) from an unused root (meaning to belch forth);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H77>', 'opaque', 'heb', 'אֶבֶץ', '["ʼEbets"]', '["Ebets, a place in Palestine Abez."]', '["n-pr-loc"]', 'Ebets, a place in Palestine Abez.', 'from an unused root probably meaning to gleam; conspicuous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H78}/[H78]', 'lemma', 'heb', 'אִבְצָן', '["ʼIbtsân"]', '["Ibtsan, an Israelite Ibzan."]', '["n-pr-m"]', 'Ibtsan, an Israelite Ibzan.', 'from the same as 76; splendid;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H79]', 'root', 'heb', 'אָבַק', '["ʼâbaq"]', '["to bedust, i.e. grapple wrestle."]', '["v"]', 'to bedust, i.e. grapple wrestle.', 'a primitive root, probably to float away (as vapor), but used only as denominative from 80;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H80}/[H80]', 'lemma', 'heb', 'אָבָק', '["ʼâbâq"]', '["light particles (as volatile) (small) dust, powder."]', '["n-m"]', 'light particles (as volatile) (small) dust, powder.', 'from root of 79;');
