INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H138}/[H138]', 'lemma', 'heb', 'אֲדֹנִיָּה', '["ʼĂdônîyâh"]', '["Adonijah, the name of three Israelites Adonijah."]', '["n-pr-m"]', 'Adonijah, the name of three Israelites Adonijah.', 'original (prolonged) אֲדֹנִיָּהוּ ; from 113 and 3050; lord (i.e. worshipper) of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H139}/[H139]', 'lemma', 'heb', 'אֲדֹנִי־צֶדֶק', '["ʼĂdônîy-Tsedeq"]', '["Adoni-Tsedek, a Canaanitish king Adonizedec."]', '["n-pr-m"]', 'Adoni-Tsedek, a Canaanitish king Adonizedec.', 'from 113 and 6664; lord of justice;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H140}/[H140]', 'lemma', 'heb', 'אֲדֹנִיקָם', '["ʼĂdônîyqâm"]', '["Adonikam, the name of one or two Israelites Adonikam."]', '["n-pr-m"]', 'Adonikam, the name of one or two Israelites Adonikam.', 'from 113 and 6965; lord of rising (i.e. high);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H141}/[H141]', 'lemma', 'heb', 'אֲדֹנִירָם', '["ʼĂdônîyrâm"]', '["Adoniram, an Israelite Adoniram."]', '["n-pr-m"]', 'Adoniram, an Israelite Adoniram.', 'from 113 and 7311; lord of height;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H142]', 'root', 'heb', 'אָדַר', '["ʼâdar"]', '["to expand, i.e. be great or (figuratively) magnificent (become) glorious, honourable."]', '["v"]', 'to expand, i.e. be great or (figuratively) magnificent (become) glorious, honourable.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H143}/[H143]', 'lemma', 'heb', 'אֲדָר', '["ʼĂdâr"]', '["Adar, the 12th Hebrew month Adar."]', '["n"]', 'Adar, the 12th Hebrew month Adar.', 'probably of foreign derivation; perhaps meaning fire;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H144}/[H144]', 'lemma', 'arc', 'אֲדָר', '["ʼĂdâr"]', '["Adar."]', '["n"]', 'Adar.', '(Aramaic) corresponding to 143');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H145}/[H145]', 'lemma', 'heb', 'אֶדֶר', '["ʼeder"]', '["amplitude, i.e. (concrete) a mantle; also (figuratively) splendor goodly, robe."]', '["n"]', 'amplitude, i.e. (concrete) a mantle; also (figuratively) splendor goodly, robe.', 'from 142;');
