INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H147}/[H147]', 'lemma', 'arc', 'אִדַּר', '["ʼiddar"]', '["ample, i.e. a threshing-floor threshingfloor."]', '["n-f"]', 'ample, i.e. a threshing-floor threshingfloor.', '(Aramaic) intensive, from a root corresponding to 142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H148}/[H148]', 'lemma', 'arc', 'אֲדַרְגָּזֵר', '["ʼădargâzêr"]', '["a chief diviner, or astrologer judge."]', '["n-m"]', 'a chief diviner, or astrologer judge.', '(Aramaic) from the same as 147, and 1505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H149}/[H149]', 'lemma', 'arc', 'אַדְרַזְדָּא', '["ʼadrazdâʼ"]', '["quickly or carefully diligently."]', '["adv"]', 'quickly or carefully diligently.', '(Aramaic) probably of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H150}/[H150]', 'lemma', 'heb', 'אֲדַרְכֹּן', '["ʼădarkôn"]', '["a daric or Persian coin dram."]', '["n-m"]', 'a daric or Persian coin dram.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H151}/[H151]', 'lemma', 'heb', 'אֲדֹרָם', '["ʼĂdôrâm"]', '["Adoram (or Adoniram), an Israelite Adoram."]', '["n-pr-m"]', 'Adoram (or Adoniram), an Israelite Adoram.', 'contracted for 141;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H152}/[H152]', 'lemma', 'heb', 'אֲדְרַמֶּלֶךְ', '["ʼĂdrammelek"]', '["Adrammelek, the name of an Assyrian idol, also of a son of Sennacherib Adrammelech."]', '["n-pr-m"]', 'Adrammelek, the name of an Assyrian idol, also of a son of Sennacherib Adrammelech.', 'from 142 and 4428; splendor of (the) king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H153}/[H153]', 'lemma', 'arc', 'אֶדְרָע', '["ʼedrâʻ"]', '["an arm, i.e. (figuratively) power force."]', '["n-f"]', 'an arm, i.e. (figuratively) power force.', '(Aramaic) an orthographical variation for 1872;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H154}/[H154]', 'lemma', 'heb', 'אֶדְרֶעִי', '["ʼedreʻîy"]', '["Edrei, the name of two places in Palestine Edrei."]', '["n-pr-loc"]', 'Edrei, the name of two places in Palestine Edrei.', 'from the equivalent of 153; mighty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H155}/[H155]', 'lemma', 'heb', 'אַדֶּרֶת', '["ʼaddereth"]', '["something ample (as a large vine, a wide dress) garment, glory, goodly, mantle, robe."]', '["n-f"]', 'something ample (as a large vine, a wide dress) garment, glory, goodly, mantle, robe.', 'feminine of 117; ; also the same as 145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H156]', 'root', 'heb', 'אָדַשׁ', '["ʼâdash"]', '["to tread out (grain) thresh."]', '["v"]', 'to tread out (grain) thresh.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H157]', 'root', 'heb', 'אָהַב', '["ʼâhab"]', '["to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend."]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H158}/[H158]', 'lemma', 'heb', 'אַהַב', '["ʼahab"]', '["affection (in a good or a bad sense) love(-r)."]', '["n-m"]', 'affection (in a good or a bad sense) love(-r).', 'from 157;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H159}/[H159]', 'lemma', 'heb', 'אֹהַב', '["ʼôhab"]', '["love."]', '["n-m"]', 'love.', 'from 156; meaning the same as 158');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H160}/[H160]', 'lemma', 'heb', 'אַהֲבָה', '["ʼahăbâh"]', '["love."]', '["n-f"]', 'love.', 'feminine of 158 and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H161>', 'opaque', 'heb', 'אֹהַד', '["ʼÔhad"]', '["Ohad, an Israelite Ohad."]', '["n-pr-m"]', 'Ohad, an Israelite Ohad.', 'from an unused root meaning to be united; unity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H162]', 'root', 'heb', 'אֲהָהּ', '["ʼăhâhh"]', '["Oh! ah, alas."]', '["inj"]', 'Oh! ah, alas.', 'apparently a primitive word expressing pain exclamatorily;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H163>', 'opaque', 'heb', 'אַהֲוָא', '["ʼAhăvâʼ"]', '["Ahava, a river of Babylonia Ahava."]', '["n-pr-loc"]', 'Ahava, a river of Babylonia Ahava.', 'probably of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H164}/[H164]', 'lemma', 'heb', 'אֵהוּד', '["ʼÊhûwd"]', '["Ehud, the name of two or three Israelites Ehud."]', '["n-pr-m"]', 'Ehud, the name of two or three Israelites Ehud.', 'from the same as 161; united;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H165}/[H165]', 'lemma', 'heb', 'אֱהִי', '["ʼĕhîy"]', '["where I will be (Hosea 13:10,14) (which is often the rendering of the same Hebrew form from 1961)."]', '["adv"]', 'where I will be (Hosea 13:10,14) (which is often the rendering of the same Hebrew form from 1961).', 'apparently an orthographical variation for 346;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H166]', 'root', 'heb', 'אָהַל', '["ʼâhal"]', '["to be clear shine."]', '["v"]', 'to be clear shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H167}/[H167]', 'lemma', 'heb', 'אָהַל', '["ʼâhal"]', '["to tent pitch (remove) a tent."]', '["v"]', 'to tent pitch (remove) a tent.', 'a denominative from 168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H168}/[H168]', 'lemma', 'heb', 'אֹהֶל', '["ʼôhel"]', '["a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent."]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H169}/[H169]', 'lemma', 'heb', 'אֹהֶל', '["ʼÔhel"]', '["Ohel, an Israelite Ohel."]', '["n-pr-m"]', 'Ohel, an Israelite Ohel.', 'the same as 168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H170}/[H170]', 'lemma', 'heb', 'אׇהֳלָה', '["ʼOhŏlâh"]', '["Oholah, a symbolic name for Samaria Aholah."]', '["n-pr-f"]', 'Oholah, a symbolic name for Samaria Aholah.', 'in form a feminine of 168, but in fact for אׇהֳלָהּ; from 168; her tent (i.e. idolatrous sanctuary);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H171}/[H171]', 'lemma', 'heb', 'אׇהֳלִיאָב', '["ʼOhŏlîyʼâb"]', '["Oholiab, an Israelite Aholiab."]', '["n-pr-m"]', 'Oholiab, an Israelite Aholiab.', 'from 168 and 1; tent of (his) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H172}/[H172]', 'lemma', 'heb', 'אׇהֳלִיבָה', '["ʼOhŏlîybâh"]', '["Oholibah, a symbolic name for Judah Aholibah."]', '["n-pr-f"]', 'Oholibah, a symbolic name for Judah Aholibah.', '(similarly with 170) for אׇהֳלִיבָהּ ; from 168; my tent (is) in her;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H173}/[H173]', 'lemma', 'heb', 'אׇהֳלִיבָמָה', '["ʼOhŏlîybâmâh"]', '["Oholibamah, a wife of Esau Aholibamah."]', '["n"]', 'Oholibamah, a wife of Esau Aholibamah.', 'from 168 and 1116; tent of (the) height;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H174>', 'opaque', 'heb', 'אֲהָלִים', '["ʼăhâlîym"]', '["aloe wood (i.e. sticks) (tree of lign-) aloes."]', '["n-m"]', 'aloe wood (i.e. sticks) (tree of lign-) aloes.', 'or (feminine) אֲהָלוֹת (only used thus in the plural); of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H175>', 'opaque', 'heb', 'אַהֲרוֹן', '["ʼAhărôwn"]', '["Aharon, the brother of Moses Aaron."]', '["n-pr-m"]', 'Aharon, the brother of Moses Aaron.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H176}/[H176]', 'lemma', 'heb', 'אוֹ', '["ʼôw"]', '["desire (and so probably in Proverbs 31:4); hence (by way of alternative) or, also if also, and, either, if, at the least, × nor, or, otherwise, then, whether."]', '["conj"]', 'desire (and so probably in Proverbs 31:4); hence (by way of alternative) or, also if also, and, either, if, at the least, × nor, or, otherwise, then, whether.', 'presumed to be the ''constructive'' or genitival form of אַו ; short for 185;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H177}/[H177]', 'lemma', 'heb', 'אוּאֵל', '["ʼÛwʼêl"]', '["Uel, and Israelite Uel."]', '["n-pr-m"]', 'Uel, and Israelite Uel.', 'from 176 and 410; wish of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H178}/[H178]', 'lemma', 'heb', 'אוֹב', '["ʼôwb"]', '["properly, a mumble, i.e. a water-skin (from its hollow sound); hence a necromancer (ventriloquist, as from a jar) bottle, familiar spirit."]', '["n-m"]', 'properly, a mumble, i.e. a water-skin (from its hollow sound); hence a necromancer (ventriloquist, as from a jar) bottle, familiar spirit.', 'from the same as 1 (apparently through the idea of prattling a father''s name);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H179}/[H179]', 'lemma', 'heb', 'אוֹבִיל', '["ʼôwbîyl"]', '["Obil, an Ishmaelite Obil."]', '["n-pr-m"]', 'Obil, an Ishmaelite Obil.', 'probably from 56; mournful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H180}/[H180]', 'lemma', 'heb', 'אוּבָל', '["ʼûwbâl"]', '["a stream river."]', '["n-m"]', 'a stream river.', 'or (shortened) אֻבָל ; from 2986 (in the sense of 2988);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H181>', 'opaque', 'heb', 'אוּד', '["ʼûwd"]', '["a poker (for turning or gathering embers) (fire-) brand."]', '["n-m"]', 'a poker (for turning or gathering embers) (fire-) brand.', 'from an unused root meaning to rake together;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H182}/[H182]', 'lemma', 'heb', 'אוֹדוֹת', '["ʼôwdôwth"]', '["turnings (i.e. occasions); (adverb) on account of (be-) cause, concerning, sake."]', '["n-f"]', 'turnings (i.e. occasions); (adverb) on account of (be-) cause, concerning, sake.', 'or (shortened) אֹדוֹת (only thus in the plural); from the same as 181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H183]', 'root', 'heb', 'אָוָה', '["ʼâvâh"]', '["to wish for covet, (greatly) desire, be desirous, long, lust (after)."]', '["v"]', 'to wish for covet, (greatly) desire, be desirous, long, lust (after).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H184]', 'root', 'heb', 'אָוָה', '["ʼâvâh"]', '["to extend or mark out point out."]', '["v"]', 'to extend or mark out point out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H185}/[H185]', 'lemma', 'heb', 'אַוָּה', '["ʼavvâh"]', '["longing desire, lust after, pleasure."]', '["n-f"]', 'longing desire, lust after, pleasure.', 'from 183;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H186}/[H186]', 'lemma', 'heb', 'אוּזַי', '["ʼÛwzay"]', '["Uzai, an Israelite Uzai."]', '["n-pr-m"]', 'Uzai, an Israelite Uzai.', 'perhaps by permutation for 5813, strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H187>', 'opaque', 'heb', 'אוּזָל', '["ʼÛwzâl"]', '["Uzal, a son of Joktan Uzal."]', '["n-pr-m"]', 'Uzal, a son of Joktan Uzal.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H188}/[H188]', 'lemma', 'heb', 'אוֹי', '["ʼôwy"]', '["lamentation; also interjectionally Oh! alas, woe."]', '["inj"]', 'lamentation; also interjectionally Oh! alas, woe.', 'probably from 183 (in the sense of crying out after);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H189}/[H189]', 'lemma', 'heb', 'אֱוִי', '["ʼĔvîy"]', '["Evi, a Midianitish chief Evi."]', '["n-pr-m"]', 'Evi, a Midianitish chief Evi.', 'probably from 183; desirous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H190}/[H190]', 'lemma', 'heb', 'אוֹיָה', '["ʼôwyâh"]', '["woe."]', '["inj"]', 'woe.', 'feminine of 188');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H191>', 'opaque', 'heb', 'אֱוִיל', '["ʼĕvîyl"]', '["(figuratively) silly fool(-ish) (man)."]', '["a-m"]', '(figuratively) silly fool(-ish) (man).', 'from an unused root (meaning to be perverse);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H192}/[H192]', 'lemma', 'heb', 'אֱוִיל מְרֹדַךְ', '["ʼĔvîyl Mᵉrôdak"]', '["Evil-Merodak, a Babylonian king Evil-merodach."]', '["n-pr-m"]', 'Evil-Merodak, a Babylonian king Evil-merodach.', 'of Aramaic derivation and probably meaning soldier of Merodak;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H193>', 'opaque', 'heb', 'אוּל', '["ʼûwl"]', '["the body (as being rolled together); also powerful mighty, strength."]', '["n-m"]', 'the body (as being rolled together); also powerful mighty, strength.', 'from an unused root meaning to twist, i.e. (by implication) be strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H194}/[H194]', 'lemma', 'heb', 'אוּלַי', '["ʼûwlay"]', '["if not; hence perhaps if so be, may be, peradventure, unless."]', '["adv"]', 'if not; hence perhaps if so be, may be, peradventure, unless.', 'or (shortened) אֻלַי; from 176;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H195}/[H195]', 'lemma', 'heb', 'אוּלַי', '["ʼÛwlay"]', '["the Ulai (or Eulaeus), a river of Persia Ulai."]', '["n"]', 'the Ulai (or Eulaeus), a river of Persia Ulai.', 'of Persian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H196}/[H196]', 'lemma', 'heb', 'אֱוִלִי', '["ʼĕvilîy"]', '["silly, foolish; hence (morally) impious foolish."]', '["a"]', 'silly, foolish; hence (morally) impious foolish.', 'from 191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H197}/[H197]', 'lemma', 'heb', 'אוּלָם', '["ʼûwlâm"]', '["a vestibule (as bound to the building) porch."]', '["n-m"]', 'a vestibule (as bound to the building) porch.', 'or (shortened), אֻלָם ; from 481 (in the sense of tying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H198}/[H198]', 'lemma', 'heb', 'אוּלָם', '["ʼÛwlâm"]', '["Ulam, the name of two Israelites Ulam."]', '["n-pr-m"]', 'Ulam, the name of two Israelites Ulam.', 'appar, from 481 (in the sense of dumbness); solitary;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H199}/[H199]', 'lemma', 'heb', 'אוּלָם', '["ʼûwlâm"]', '["however or on the contrary as for, but, howbeit, in very deed, surely, truly, wherefore."]', '["adv"]', 'however or on the contrary as for, but, howbeit, in very deed, surely, truly, wherefore.', 'apparently a variation of 194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H200}/[H200]', 'lemma', 'heb', 'אִוֶּלֶת', '["ʼivveleth"]', '["silliness folly, foolishly(-ness)."]', '["n-f"]', 'silliness folly, foolishly(-ness).', 'from the same as 191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H201}/[H201]', 'lemma', 'heb', 'אוֹמָר', '["ʼÔwmâr"]', '["Omar, a grandson of Esau Omar."]', '["n-pr-m"]', 'Omar, a grandson of Esau Omar.', 'from 559; talkative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H202}/[H202]', 'lemma', 'heb', 'אוֹן', '["ʼôwn"]', '["ability, power, (figuratively) wealth force, goods, might, strength, substance."]', '["n-m"]', 'ability, power, (figuratively) wealth force, goods, might, strength, substance.', 'probably from the same as 205 (in the sense of effort, but successful);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H203}/[H203]', 'lemma', 'heb', 'אוֹן', '["ʼÔwn"]', '["On, an Israelite On."]', '["n-pr-m"]', 'On, an Israelite On.', 'the same as 202;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H204}/[H204]', 'lemma', 'heb', 'אוֹן', '["ʼÔwn"]', '["On, a city of Egypt On."]', '["n-pr-loc"]', 'On, a city of Egypt On.', 'or (shortened); אֹן; of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H205>', 'opaque', 'heb', 'אָוֶן', '["ʼâven"]', '["strictly nothingness; also trouble, vanity, wickedness; specifically an idol affliction, evil, false, idol, iniquity, mischief, mourners(-ing), naught, sorrow, unjust, unrighteous, vain, vanity, wicked(-ness). Compare 369."]', '["n-m"]', 'strictly nothingness; also trouble, vanity, wickedness; specifically an idol affliction, evil, false, idol, iniquity, mischief, mourners(-ing), naught, sorrow, unjust, unrighteous, vain, vanity, wicked(-ness). Compare 369.', 'from an unused root perhaps meaning properly, to pant (hence, to exert oneself, usually in vain; to come to naught);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H206}/[H206]', 'lemma', 'heb', 'אָוֶן', '["ʼÂven"]', '["Aven, the contemptuous synonym of three places, one in Coele-Syria, one in Egypt (On), and one in Palestine (Bethel) Aven. See also 204, 1007."]', '["n-pr-loc"]', 'Aven, the contemptuous synonym of three places, one in Coele-Syria, one in Egypt (On), and one in Palestine (Bethel) Aven. See also 204, 1007.', 'the same as 205; idolatry;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H207}/[H207]', 'lemma', 'heb', 'אוֹנוֹ', '["ʼÔwnôw"]', '["Ono, a place in Palestine Ono."]', '["n-pr-loc"]', 'Ono, a place in Palestine Ono.', 'or (shortened) אֹנוֹ; prolonged from 202; strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H208}/[H208]', 'lemma', 'heb', 'אוֹנָם', '["ʼÔwnâm"]', '["Onam, the name of an Edomite and of an Israelite Onam."]', '["n-pr-m"]', 'Onam, the name of an Edomite and of an Israelite Onam.', 'a variation of 209; strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H209}/[H209]', 'lemma', 'heb', 'אוֹנָן', '["ʼÔwnân"]', '["Onan, a son of Judah Onan."]', '["n-pr-m"]', 'Onan, a son of Judah Onan.', 'a variation of 207; strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H210}/[H210]', 'lemma', 'heb', 'אוּפָז', '["ʼÛwphâz"]', '["Uphaz, a famous gold region Uphaz."]', '["n-pr-loc"]', 'Uphaz, a famous gold region Uphaz.', 'perhaps a corruption of 211;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H211>', 'opaque', 'heb', 'אוֹפִיר', '["ʼÔwphîyr"]', '["Ophir, the name of a son of Joktan, and of a gold region in the East Ophir."]', '["n-pr-m"]', 'Ophir, the name of a son of Joktan, and of a gold region in the East Ophir.', 'or (shortened) אֹפִיר; and אוֹפִר; of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H212>', 'opaque', 'heb', 'אוֹפָן', '["ʼôwphân"]', '["a wheel wheel."]', '["n-m"]', 'a wheel wheel.', 'or (shortened) אֹפָן; from an unused root meaning to revolve;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H213]', 'root', 'heb', 'אוּץ', '["ʼûwts"]', '["to press; (by implication) to be close, hurry, withdraw (make) haste(-n, -y), labor, be narrow."]', '["v"]', 'to press; (by implication) to be close, hurry, withdraw (make) haste(-n, -y), labor, be narrow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H214}/[H214]', 'lemma', 'heb', 'אוֹצָר', '["ʼôwtsâr"]', '["a depository armory, cellar, garner, store(-house), treasure(-house) (-y)."]', '["n-m"]', 'a depository armory, cellar, garner, store(-house), treasure(-house) (-y).', 'from 686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H215]', 'root', 'heb', 'אוֹר', '["ʼôwr"]', '["to be (causative, make) luminous (literally and metaphorically) × break of day, glorious, kindle, (be, en-, give, show) light (-en, -ened), set on fire, shine."]', '["v"]', 'to be (causative, make) luminous (literally and metaphorically) × break of day, glorious, kindle, (be, en-, give, show) light (-en, -ened), set on fire, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H216}/[H216]', 'lemma', 'heb', 'אוֹר', '["ʼôwr"]', '["illumination or (concrete) luminary (in every sense, including lightning, happiness, etc.) bright, clear, day, light (-ning), morning, sun."]', '["n-f"]', 'illumination or (concrete) luminary (in every sense, including lightning, happiness, etc.) bright, clear, day, light (-ning), morning, sun.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H217}/[H217]', 'lemma', 'heb', 'אוּר', '["ʼûwr"]', '["flame; hence (in the plural) the East (as being the region of light) fire, light. See also 224."]', '["n-m"]', 'flame; hence (in the plural) the East (as being the region of light) fire, light. See also 224.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H218}/[H218]', 'lemma', 'heb', 'אוּר', '["ʼÛwr"]', '["Ur, a place in Chaldaea; also an Israelite Ur."]', '["n-pr-m n-pr-loc"]', 'Ur, a place in Chaldaea; also an Israelite Ur.', 'the same as 217;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H219}/[H219]', 'lemma', 'heb', 'אוֹרָה', '["ʼôwrâh"]', '["luminousness, i.e. (figuratively) prosperity; also a plant (as being bright) herb, light."]', '["n-f"]', 'luminousness, i.e. (figuratively) prosperity; also a plant (as being bright) herb, light.', 'feminine of 216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H220}/[H220]', 'lemma', 'heb', 'אֲוֵרָה', '["ʼăvêrâh"]', '["a stall cote."]', '["n-f"]', 'a stall cote.', 'by transposition for 723;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H221}/[H221]', 'lemma', 'heb', 'אוּרִי', '["ʼÛwrîy"]', '["Uri, the name of three Israelites Uri."]', '["n-pr-m"]', 'Uri, the name of three Israelites Uri.', 'from 217; fiery;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H222}/[H222]', 'lemma', 'heb', 'אוּרִיאֵל', '["ʼÛwrîyʼêl"]', '["Uriel, the name of two Israelites Uriel."]', '["n-pr-m"]', 'Uriel, the name of two Israelites Uriel.', 'from 217 and 410; flame of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H223}/[H223]', 'lemma', 'heb', 'אוּרִיָּה', '["ʼÛwrîyâh"]', '["Urijah, the name of one Hittite and five Israelites Uriah, Urijah."]', '["n-pr-m"]', 'Urijah, the name of one Hittite and five Israelites Uriah, Urijah.', 'or (prolonged) אוּרִיָּהוּ ; from 217 and 3050; flame of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H224}/[H224]', 'lemma', 'heb', 'אוּרִים', '["ʼÛwrîym"]', '["Urim, the oracular brilliancy of the figures in the high-priest''s breastplate Urim."]', '["n-m"]', 'Urim, the oracular brilliancy of the figures in the high-priest''s breastplate Urim.', 'plural of 217; lights;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H225]', 'root', 'heb', 'אוּת', '["ʼûwth"]', '["properly, to come, i.e. (implied) to assent consent."]', '["v"]', 'properly, to come, i.e. (implied) to assent consent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H226}/[H226]', 'lemma', 'heb', 'אוֹת', '["ʼôwth"]', '["a signal (literally or figuratively), as a flag, beacon, monument, omen, prodigy, evidence, etc. mark, miracle, (en-) sign, token."]', '["n-f"]', 'a signal (literally or figuratively), as a flag, beacon, monument, omen, prodigy, evidence, etc. mark, miracle, (en-) sign, token.', 'probably from 225 (in the sense of appearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H227}/[H227]', 'lemma', 'heb', 'אָז', '["ʼâz"]', '["at that time or place; also as a conjunction, therefore beginning, for, from, hitherto, now, of old, once, since, then, at which time, yet."]', '["adv"]', 'at that time or place; also as a conjunction, therefore beginning, for, from, hitherto, now, of old, once, since, then, at which time, yet.', 'a demonstrative adverb;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H228}/[H228]', 'lemma', 'arc', 'אֲזָא', '["ʼăzâʼ"]', '["to kindle; (by implication) to heat heat, hot."]', '["v"]', 'to kindle; (by implication) to heat heat, hot.', '(Aramaic) or אֲזָה (Aramaic);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H229}/[H229]', 'lemma', 'heb', 'אֶזְבַּי', '["ʼEzbay"]', '["Ezbai, an Israelite Ezbai."]', '["n-pr-m"]', 'Ezbai, an Israelite Ezbai.', 'probably from 231; hyssop-like;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H230>', 'opaque', 'arc', 'אֲזָד', '["ʼăzâd"]', '["firm be gone."]', '["a"]', 'firm be gone.', '(Aramaic) of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H231}/[H231]', 'lemma', 'heb', 'אֵזוֹב', '["ʼêzôwb"]', '["hyssop hyssop."]', '["n-m"]', 'hyssop hyssop.', 'probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H232}/[H232]', 'lemma', 'heb', 'אֵזוֹר', '["ʼêzôwr"]', '["something girt; a belt, also a band girdle."]', '["n-m"]', 'something girt; a belt, also a band girdle.', 'from 246;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H233}/[H233]', 'lemma', 'heb', 'אֲזַי', '["ʼăzay"]', '["at that time then."]', '["adv"]', 'at that time then.', 'probably from 227;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H234}/[H234]', 'lemma', 'heb', 'אַזְכָּרָה', '["ʼazkârâh"]', '["a reminder; specifically remembrance-offering memorial."]', '["n-f"]', 'a reminder; specifically remembrance-offering memorial.', 'from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H235]', 'root', 'heb', 'אָזַל', '["ʼâzal"]', '["to go away, hence, to disappear fail, gad about, go to and fro (but in Ezekiel 27:19 the word is rendered by many ''from Uzal,'' by others ''yarn''), be gone (spent)."]', '["v"]', 'to go away, hence, to disappear fail, gad about, go to and fro (but in Ezekiel 27:19 the word is rendered by many ''from Uzal,'' by others ''yarn''), be gone (spent).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H236}/[H236]', 'lemma', 'arc', 'אֲזַל', '["ʼăzal"]', '["to depart go (up)."]', '["v"]', 'to depart go (up).', '(Aramaic) the same as 235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H237}/[H237]', 'lemma', 'heb', 'אֶזֶל', '["ʼezel"]', '["Ezel, a memorial stone in Palestine Ezel."]', '["n-pr-loc"]', 'Ezel, a memorial stone in Palestine Ezel.', 'from 235; departure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H238]', 'root', 'heb', 'אָזַן', '["ʼâzan"]', '["to broaden out the ear (with the hand), i.e. (by implication) to listen give (perceive by the) ear, hear(-ken). See 239."]', '["v"]', 'to broaden out the ear (with the hand), i.e. (by implication) to listen give (perceive by the) ear, hear(-ken). See 239.', 'a primitive root; probably to expand; but used only as a denominative from 241;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H239]', 'root', 'heb', 'אָזַן', '["ʼâzan"]', '["to weigh, i.e. (figuratively) ponder give good heed."]', '["v"]', 'to weigh, i.e. (figuratively) ponder give good heed.', 'a primitive root (rather identical with 238 through the idea of scales as if two ears);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H240}/[H240]', 'lemma', 'heb', 'אָזֵן', '["ʼâzên"]', '["a spade or paddle (as having a broad end) weapon."]', '["n-m"]', 'a spade or paddle (as having a broad end) weapon.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H241}/[H241]', 'lemma', 'heb', 'אֹזֶן', '["ʼôzen"]', '["broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show."]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H242}/[H242]', 'lemma', 'heb', 'אֻזֵּן שֶׁאֱרָה', '["ʼUzzên Sheʼĕrâh"]', '["Uzzen-Sheerah, a place in Palestine Uzzen-sherah."]', '["n-pr-loc"]', 'Uzzen-Sheerah, a place in Palestine Uzzen-sherah.', 'from 238 and 7609; plot of Sheerah (i.e. settled by him);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H243}/[H243]', 'lemma', 'heb', 'אַזְנוֹת תָּבוֹר', '["ʼAznôwth Tâbôwr"]', '["Aznoth-Tabor, a place in Palestine Aznoth-tabor."]', '["n-pr-loc"]', 'Aznoth-Tabor, a place in Palestine Aznoth-tabor.', 'from 238 and 8396; flats (i.e. tops) of Tabor (i.e. situated on it);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H244}/[H244]', 'lemma', 'heb', 'אׇזְנִי', '["ʼOznîy"]', '["Ozni, an Israelite; also an Oznite (collectively), his descendant Ozni, Oznites."]', '["n-pr-m a-gent"]', 'Ozni, an Israelite; also an Oznite (collectively), his descendant Ozni, Oznites.', 'from 241; having (quick) ears;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H245}/[H245]', 'lemma', 'heb', 'אֲזַנְיָה', '["ʼĂzanyâh"]', '["Azanjah, an Israelite Azaniah."]', '["n-pr-m"]', 'Azanjah, an Israelite Azaniah.', 'from 238 and 3050; heard by Jah;');
