INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H247]', 'root', 'heb', 'אָזַר', '["ʼâzar"]', '["to belt bind (compass) about, gird (up, with)."]', '["v"]', 'to belt bind (compass) about, gird (up, with).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H248}/[H248]', 'lemma', 'heb', 'אֶזְרוֹעַ', '["ʼezrôwaʻ"]', '["the arm arm."]', '["n-f"]', 'the arm arm.', 'a variation for 2220;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H249}/[H249]', 'lemma', 'heb', 'אֶזְרָח', '["ʼezrâch"]', '["a spontaneous growth, i.e. native (tree or persons) bay tree, (home-) born (in the land), of the (one''s own) country (nation)."]', '["n-m"]', 'a spontaneous growth, i.e. native (tree or persons) bay tree, (home-) born (in the land), of the (one''s own) country (nation).', 'from 2224 (in the sense of springing up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H250}/[H250]', 'lemma', 'heb', 'אֶזְרָחִי', '["ʼEzrâchîy"]', '["an Ezrachite or descendant of Zerach Ezrahite."]', '["a"]', 'an Ezrachite or descendant of Zerach Ezrahite.', 'patronymic from 2226;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H251]', 'root', 'heb', 'אָח', '["ʼâch"]', '["a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''."]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H252}/[H252]', 'lemma', 'arc', 'אַח', '["ʼach"]', '["brother."]', '["n-m"]', 'brother.', '(Aramaic) corresponding to 251');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H253}/[H253]', 'lemma', 'heb', 'אָח', '["ʼâch"]', '["Oh! (expressive of grief or surprise) ah, alas."]', '["inj"]', 'Oh! (expressive of grief or surprise) ah, alas.', 'a variation for 162;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H254>', 'opaque', 'heb', 'אָח', '["ʼâch"]', '["a fire-pot or chafing dish hearth."]', '["n-f"]', 'a fire-pot or chafing dish hearth.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H255}/[H255]', 'lemma', 'heb', 'אֹחַ', '["ʼôach"]', '["a howler or lonesome wild animal doleful creature."]', '["n-m"]', 'a howler or lonesome wild animal doleful creature.', 'probably from 253;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H256}/[H256]', 'lemma', 'heb', 'אַחְאָב', '["ʼAchʼâb"]', '["Achab, the name of a king of Israel and of a prophet at Babylon Ahab."]', '["n-pr-m"]', 'Achab, the name of a king of Israel and of a prophet at Babylon Ahab.', 'once (by contraction) אֶחָב (Jeremiah 29:22); from 251 and 1; brother (i.e. friend) of (his) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H257}/[H257]', 'lemma', 'heb', 'אַחְבָן', '["ʼAchbân"]', '["Achban, an Israelite Ahban."]', '["n-pr-m"]', 'Achban, an Israelite Ahban.', 'from 251 and 995; brother (i.e. possessor) of understanding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H258]', 'root', 'heb', 'אָחַד', '["ʼâchad"]', '["to unify, i.e. (figuratively) collect (one''s thoughts) go one way or other."]', '["v"]', 'to unify, i.e. (figuratively) collect (one''s thoughts) go one way or other.', 'perhaps a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H259}/[H259]', 'lemma', 'heb', 'אֶחָד', '["ʼechâd"]', '["properly, united, i.e. one; or (as an ordinal) first a, alike, alone, altogether, and, any(-thing), apiece, a certain, (dai-) ly, each (one), eleven, every, few, first, highway, a man, once, one, only, other, some, together,"]', '["a"]', 'properly, united, i.e. one; or (as an ordinal) first a, alike, alone, altogether, and, any(-thing), apiece, a certain, (dai-) ly, each (one), eleven, every, few, first, highway, a man, once, one, only, other, some, together,', 'a numeral from 258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H260}/[H260]', 'lemma', 'heb', 'אָחוּ', '["ʼâchûw"]', '["a bulrush or any marshy grass (particularly that along the Nile) flag, meadow."]', '["n-m"]', 'a bulrush or any marshy grass (particularly that along the Nile) flag, meadow.', 'of uncertain (perhaps Egyptian) derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H261}/[H261]', 'lemma', 'heb', 'אֵחוּד', '["ʼÊchûwd"]', '["Echud, the name of three Israelites Ehud."]', '["n-pr-m"]', 'Echud, the name of three Israelites Ehud.', 'from 258; united;');
