INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H268}/[H268]', 'lemma', 'heb', 'אָחוֹר', '["ʼâchôwr"]', '["the hinder part; hence (adverb) behind, backward; also (as facing north) the West after(-ward), back (part, -side, -ward), hereafter, (be-) hind(-er part), time to come, without."]', '["n-m"]', 'the hinder part; hence (adverb) behind, backward; also (as facing north) the West after(-ward), back (part, -side, -ward), hereafter, (be-) hind(-er part), time to come, without.', 'or (shortened) אָחֹר ; from 299;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H269}/[H269]', 'lemma', 'heb', 'אָחוֹת', '["ʼâchôwth"]', '["a sister (used very widely [like 251number 250, corrected to 251], literally and figuratively) (an-) other, sister, together."]', '["n-f"]', 'a sister (used very widely [like 251number 250, corrected to 251], literally and figuratively) (an-) other, sister, together.', 'irregular feminine of 251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H270]', 'root', 'heb', 'אָחַז', '["ʼâchaz"]', '["to seize (often with the accessory idea of holding in possession) be affrighted, bar, (catch, lay, take) hold (back), come upon, fasten, handle, portion, (get, have or take) possess(-ion)."]', '["v"]', 'to seize (often with the accessory idea of holding in possession) be affrighted, bar, (catch, lay, take) hold (back), come upon, fasten, handle, portion, (get, have or take) possess(-ion).', 'a primitive root;');
