INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H296}/[H296]', 'lemma', 'heb', 'אֲחִיקָם', '["ʼĂchîyqâm"]', '["Achikam, an Israelite Ahikam."]', '["n-pr-m"]', 'Achikam, an Israelite Ahikam.', 'from 251 and 6965; brother of rising (i.e. high);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H297}/[H297]', 'lemma', 'heb', 'אֲחִירָם', '["ʼĂchîyrâm"]', '["Achiram, an Israelite Ahiram."]', '["n-pr-m"]', 'Achiram, an Israelite Ahiram.', 'from 251 and 7311; brother of height (i.e. high);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H298}/[H298]', 'lemma', 'heb', 'אֲחִירָמִי', '["ʼĂchîyrâmîy"]', '["an Achiramite or descendant (collectively) of Achiram Ahiramites."]', '["a"]', 'an Achiramite or descendant (collectively) of Achiram Ahiramites.', 'patronymic from 297;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H299}/[H299]', 'lemma', 'heb', 'אֲחִירַע', '["ʼĂchîyraʻ"]', '["Achira, an Israelite Ahira."]', '["n-pr-m"]', 'Achira, an Israelite Ahira.', 'from 251 and 7451; brother of wrong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H300}/[H300]', 'lemma', 'heb', 'אֲחִישַׁחַר', '["ʼĂchîyshachar"]', '["Achishachar, an Israelite Ahishar."]', '["n-pr-m"]', 'Achishachar, an Israelite Ahishar.', 'from 251 and 7837; brother of (the) dawn;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H301}/[H301]', 'lemma', 'heb', 'אֲחִישָׁר', '["ʼĂchîyshâr"]', '["Achishar, an Israelite Ahishar."]', '["n-pr-m"]', 'Achishar, an Israelite Ahishar.', 'from 251 and 7891; brother of (the) singer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H302}/[H302]', 'lemma', 'heb', 'אֲחִיתֹפֶל', '["ʼĂchîythôphel"]', '["Achithophel, an Israelite Ahithophel."]', '["n-pr-m"]', 'Achithophel, an Israelite Ahithophel.', 'from 251 and 8602; brother of folly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H303}/[H303]', 'lemma', 'heb', 'אַחְלָב', '["ʼAchlâb"]', '["Achlab, a place in Palestine Ahlab."]', '["n-pr-loc"]', 'Achlab, a place in Palestine Ahlab.', 'from the same root as 2459; fatness (i.e. fertile);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H304}/[H304]', 'lemma', 'heb', 'אַחְלַי', '["ʼAchlay"]', '["Achlai, the name of an Israelitess and of an Israelite Ahlai."]', '["n-pr-m"]', 'Achlai, the name of an Israelitess and of an Israelite Ahlai.', 'the same as 305; wishful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H305}/[H305]', 'lemma', 'heb', 'אַחֲלַי', '["ʼachălay"]', '["would that! O that, would God."]', '["inj"]', 'would that! O that, would God.', 'or אַחֲלֵי; prob from 253 and a variation of 3863;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H306}/[H306]', 'lemma', 'heb', 'אַחְלָמָה', '["ʼachlâmâh"]', '["a gem, probably the amethyst amethyst."]', '["n-f"]', 'a gem, probably the amethyst amethyst.', 'perhaps from 2492 (and thus dream-stone);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H307}/[H307]', 'lemma', 'heb', 'אַחְמְתָא', '["ʼAchmᵉthâʼ"]', '["Achmetha (i.e. Ecbatana), the summer capital of Persia Achmetha."]', '["n-pr-loc"]', 'Achmetha (i.e. Ecbatana), the summer capital of Persia Achmetha.', 'of Persian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H308>', 'opaque', 'heb', 'אֲחַסְבַּי', '["ʼĂchaçbay"]', '["Achasbai, an Israelite Ahasbai."]', '["n-pr-f"]', 'Achasbai, an Israelite Ahasbai.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H309]', 'root', 'heb', 'אָחַר', '["ʼâchar"]', '["to loiter (i.e. be behind); by implication to procrastinate continue, defer, delay, hinder, be late (slack), stay (there), tarry (longer)."]', '["v"]', 'to loiter (i.e. be behind); by implication to procrastinate continue, defer, delay, hinder, be late (slack), stay (there), tarry (longer).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H310}/[H310]', 'lemma', 'heb', 'אַחַר', '["ʼachar"]', '["properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with."]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H311}/[H311]', 'lemma', 'arc', 'אַחַר', '["ʼachar"]', '["after (here-) after."]', '["adv"]', 'after (here-) after.', '(Aramaic) corresponding to 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H312}/[H312]', 'lemma', 'heb', 'אַחֵר', '["ʼachêr"]', '["properly, hinder; generally, next, other, etc. (an-) other man, following, next, strange."]', '["a"]', 'properly, hinder; generally, next, other, etc. (an-) other man, following, next, strange.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H313}/[H313]', 'lemma', 'heb', 'אַחֵר', '["ʼAchêr"]', '["Acher, an Israelite Aher."]', '["n-pr-m"]', 'Acher, an Israelite Aher.', 'the same as 312;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H314}/[H314]', 'lemma', 'heb', 'אַחֲרוֹן', '["ʼachărôwn"]', '["hinder; generally, late or last; specifically (as facing the east) western after (-ward), to come, following, hind(-er, -ermost, -most), last, latter, rereward, ut(ter) most."]', '["a"]', 'hinder; generally, late or last; specifically (as facing the east) western after (-ward), to come, following, hind(-er, -ermost, -most), last, latter, rereward, ut(ter) most.', 'or (shortened) אַחֲרֹן; from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H315}/[H315]', 'lemma', 'heb', 'אַחְרַח', '["ʼAchrach"]', '["Achrach, an Israelite Aharah."]', '["n-pr-m"]', 'Achrach, an Israelite Aharah.', 'from 310 and 251; after (his) brother;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H316}/[H316]', 'lemma', 'heb', 'אֲחַרְחֵל', '["ʼĂcharchêl"]', '["Acharchel, an Israelite Aharhel,"]', '["n-pr-m"]', 'Acharchel, an Israelite Aharhel,', 'from 310 and 2426; behind (the) intrenchment (i.e. safe);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H317}/[H317]', 'lemma', 'arc', 'אׇחֳרִי', '["ʼochŏrîy"]', '["other (an-) other."]', '["a"]', 'other (an-) other.', '(Aramaic) from 311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H318}/[H318]', 'lemma', 'arc', 'אׇחֳרֵין', '["ʼochŏrêyn"]', '["last at last."]', '["adv"]', 'last at last.', '(Aramaic) or (shortened) אׇחֳרֵן; (Aramaic) from 317;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H319}/[H319]', 'lemma', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward."]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H320}/[H320]', 'lemma', 'arc', 'אַחֲרִית', '["ʼachărîyth"]', '["later latter."]', '["n-f"]', 'later latter.', '(Aramaic) from 311; the same as 319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H321}/[H321]', 'lemma', 'arc', 'אׇחֳרָן', '["ʼochŏrân"]', '["other (an-) other."]', '["a"]', 'other (an-) other.', '(Aramaic) from 311; the same as 317;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H322}/[H322]', 'lemma', 'heb', 'אֲחֹרַנִּית', '["ʼăchôrannîyth"]', '["backwards back (-ward, again)."]', '["adv"]', 'backwards back (-ward, again).', 'prolonged from 268;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H323}/[H323]', 'lemma', 'heb', 'אֲחַשְׁדַּרְפַּן', '["ʼăchashdarpan"]', '["a satrap or governor of a main province (of Persia) lieutenant."]', '["n-m"]', 'a satrap or governor of a main province (of Persia) lieutenant.', 'of Persian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H324}/[H324]', 'lemma', 'arc', 'אֲחַשְׁדַּרְפַּן', '["ʼăchashdarpan"]', '["prince."]', '["n-m"]', 'prince.', '(Aramaic) corresponding to 323');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H325}/[H325]', 'lemma', 'heb', 'אֲחַשְׁוֵרוֹשׁ', '["ʼĂchashvêrôwsh"]', '["Achashverosh (i.e. Ahasuerus or Artaxerxes, but in this case Xerxes), the title (rather than name) of a Persian king Ahasuerus."]', '["n-pr-m"]', 'Achashverosh (i.e. Ahasuerus or Artaxerxes, but in this case Xerxes), the title (rather than name) of a Persian king Ahasuerus.', 'or (shortened) אַחַשְׁרֹשׁ (Esther 10:1); of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H326}/[H326]', 'lemma', 'heb', 'אֲחַשְׁתָּרִי', '["ʼăchashtârîy"]', '["an achastarite (i.e. courier); the designation (rather than name) of an Israelite Haakashtari (includ. the article)."]', '["n-pr-m"]', 'an achastarite (i.e. courier); the designation (rather than name) of an Israelite Haakashtari (includ. the article).', 'probably of Persian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H327}/[H327]', 'lemma', 'heb', 'אֲחַשְׁתָּרָן', '["ʼăchashtârân"]', '["a mule camel."]', '["a"]', 'a mule camel.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H328>', 'opaque', 'heb', 'אַט', '["ʼaṭ"]', '["(as a noun) a necromancer (from their soft incantations), (as an adverb) gently charmer, gently, secret, softly."]', '["n-m adv"]', '(as a noun) a necromancer (from their soft incantations), (as an adverb) gently charmer, gently, secret, softly.', 'from an unused root perhaps meaning to move softly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H329>', 'opaque', 'heb', 'אָטָד', '["ʼâṭâd"]', '["a thorn-tree (especially the buckthorn) Atad, bramble, thorn."]', '["n-m"]', 'a thorn-tree (especially the buckthorn) Atad, bramble, thorn.', 'from an unused root probably meaning to pierce or make fast;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H330>', 'opaque', 'heb', 'אֵטוּן', '["ʼêṭûwn"]', '["properly, twisted (yarn), i.e. tapestry fine linen."]', '["n-m"]', 'properly, twisted (yarn), i.e. tapestry fine linen.', 'from an unused root (probably meaning to bind);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H331]', 'root', 'heb', 'אָטַם', '["ʼâṭam"]', '["to close (the lips or ears); by analology to contract (a window by bevelled jambs) narrow, shut, stop."]', '["v"]', 'to close (the lips or ears); by analology to contract (a window by bevelled jambs) narrow, shut, stop.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H332]', 'root', 'heb', 'אָטַר', '["ʼâṭar"]', '["to close up shut."]', '["v"]', 'to close up shut.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H333}/[H333]', 'lemma', 'heb', 'אָטֵר', '["ʼÂṭêr"]', '["Ater, the name of three Israelites Ater."]', '["n-pr-m"]', 'Ater, the name of three Israelites Ater.', 'from 332; maimed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H334}/[H334]', 'lemma', 'heb', 'אִטֵּר', '["ʼiṭṭêr"]', '["shut up, i.e. impeded (as to the use of the right hand) left-handed."]', '["a"]', 'shut up, i.e. impeded (as to the use of the right hand) left-handed.', 'from 332;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H335}/[H335]', 'lemma', 'heb', 'אַי', '["ʼay"]', '["where? hence how? how, what, whence, where, whether, which (way)."]', '["adv"]', 'where? hence how? how, what, whence, where, whether, which (way).', 'perhaps from 370;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H336}/[H336]', 'lemma', 'heb', 'אִי', '["ʼîy"]', '["not island (Job 22:30)."]', '["adv"]', 'not island (Job 22:30).', 'probably identical with 335 (through the idea of a query);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H337}/[H337]', 'lemma', 'heb', 'אִי', '["ʼîy"]', '["alas! woe."]', '["inj"]', 'alas! woe.', 'short from 188;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H338}/[H338]', 'lemma', 'heb', 'אִי', '["ʼîy"]', '["a howler (used only in the plural), i.e. any solitary wild creature wild beast of the islands."]', '["n-m"]', 'a howler (used only in the plural), i.e. any solitary wild creature wild beast of the islands.', 'probably identical with 337 (through the idea of a doleful sound);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H339}/[H339]', 'lemma', 'heb', 'אִי', '["ʼîy"]', '["properly, a habitable spot (as desirable); dry land, a coast, an island country, isle, island."]', '["n-m"]', 'properly, a habitable spot (as desirable); dry land, a coast, an island country, isle, island.', 'from 183;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H340]', 'root', 'heb', 'אָיַב', '["ʼâyab"]', '["to hate (as one of an opposite tribe or party); hence to be hostile be an enemy."]', '["v"]', 'to hate (as one of an opposite tribe or party); hence to be hostile be an enemy.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H341}/[H341]', 'lemma', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["hating; an adversary enemy, foe."]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H342}/[H342]', 'lemma', 'heb', 'אֵיבָה', '["ʼêybâh"]', '["hostility emnity, hatred."]', '["n-f"]', 'hostility emnity, hatred.', 'from 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H343}/[H343]', 'lemma', 'heb', 'אֵיד', '["ʼêyd"]', '["oppression; by implication misfortune, ruin calamity, destruction."]', '["n-m"]', 'oppression; by implication misfortune, ruin calamity, destruction.', 'from the same as 181 (in the sense of bending down);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H344}/[H344]', 'lemma', 'heb', 'אַיָּה', '["ʼayâh"]', '["the screamer, i.e. a hawk kite, vulture."]', '["n-f"]', 'the screamer, i.e. a hawk kite, vulture.', 'perhaps from 337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H345}/[H345]', 'lemma', 'heb', 'אַיָּה', '["ʼAyâh"]', '["Ajah, the name of two Israelites Aiah, Ajah."]', '["n-pr-m"]', 'Ajah, the name of two Israelites Aiah, Ajah.', 'the same as 344;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H346}/[H346]', 'lemma', 'heb', 'אַיֵּה', '["ʼayêh"]', '["where? where."]', '["adv"]', 'where? where.', 'prolonged from 335;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H347}/[H347]', 'lemma', 'heb', 'אִיּוֹב', '["ʼÎyôwb"]', '["Ijob, the patriarch famous for his patience Job."]', '["n-pr-m"]', 'Ijob, the patriarch famous for his patience Job.', 'from 340; hated (i.e. persecuted);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H348}/[H348]', 'lemma', 'heb', 'אִיזֶבֶל', '["ʼÎyzebel"]', '["Izebel, the wife of king Ahab Jezebel."]', '["n-pr-f"]', 'Izebel, the wife of king Ahab Jezebel.', 'from 336 and 2083;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H349}/[H349]', 'lemma', 'heb', 'אֵיךְ', '["ʼêyk"]', '["how? or how!; also where how, what."]', '["adv"]', 'how? or how!; also where how, what.', 'also אֵיכָה ; and אֵיכָכָה ; prolonged from 335;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H350}/[H350]', 'lemma', 'heb', 'אִי־כָבוֹד', '["ʼÎy-kâbôwd"]', '["Ikabod, a son of Phineas I-chabod."]', '["n-pr-m"]', 'Ikabod, a son of Phineas I-chabod.', 'from 336 and 3519; (there is) no glory, i.e. inglorious;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H351}/[H351]', 'lemma', 'heb', 'אֵיכֹה', '["ʼêykôh"]', '["where where."]', '["adv"]', 'where where.', 'probably a variation for 349, but not as an interogative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H352}/[H352]', 'lemma', 'heb', 'אַיִל', '["ʼayil"]', '["properly, strength; hence, anything strong; specifically a chief (politically); also a ram (from his strength); a pilaster (as a strong support); an oak or other strong tree mighty (man), lintel, oak, post, ram, tree."]', '["n-m"]', 'properly, strength; hence, anything strong; specifically a chief (politically); also a ram (from his strength); a pilaster (as a strong support); an oak or other strong tree mighty (man), lintel, oak, post, ram, tree.', 'from the same as 193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H353}/[H353]', 'lemma', 'heb', 'אֱיָל', '["ʼĕyâl"]', '["strength strength."]', '["n-m"]', 'strength strength.', 'a variation of 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H354}/[H354]', 'lemma', 'heb', 'אַיָּל', '["ʼayâl"]', '["a stag or male deer hart."]', '["n-m"]', 'a stag or male deer hart.', 'an intensive form of 352 (in the sense of ram);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H355}/[H355]', 'lemma', 'heb', 'אַיָּלָה', '["ʼayâlâh"]', '["a doe or female deer hind."]', '["n-f"]', 'a doe or female deer hind.', 'feminine of 354;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H356}/[H356]', 'lemma', 'heb', 'אֵילוֹן', '["ʼÊylôwn"]', '["Elon, the name of a place in Palestine, and also of one Hittite, two Israelites Elon."]', '["n-pr"]', 'Elon, the name of a place in Palestine, and also of one Hittite, two Israelites Elon.', 'or (shortened) אֵלוֹן ; or אֵילֹן ; from 352; oak-grove;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H357}/[H357]', 'lemma', 'heb', 'אַיָּלוֹן', '["ʼAyâlôwn"]', '["Ajalon, the name of five places in Palestine Aijalon, Ajalon."]', '["n-pr-loc"]', 'Ajalon, the name of five places in Palestine Aijalon, Ajalon.', 'from 354; deer-field;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H358}/[H358]', 'lemma', 'heb', 'אֵילוֹן בֵּית חָנָן', '["ʼÊylôwn Bêyth Chânân"]', '["Elon of Beth-chanan, a place in Palestine Elon-bethhanan."]', '["n-pr-loc"]', 'Elon of Beth-chanan, a place in Palestine Elon-bethhanan.', 'from 356, 1004, and 2603; oak-grove of (the) house of favor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H359}/[H359]', 'lemma', 'heb', 'אֵילוֹת', '["ʼÊylôwth"]', '["Eloth or Elath, a place on the Red Sea Elath, Eloth."]', '["n-pr-loc"]', 'Eloth or Elath, a place on the Red Sea Elath, Eloth.', 'or אֵילַת ; from 352; trees or a grove (i.e. palms);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H360}/[H360]', 'lemma', 'heb', 'אֱיָלוּת', '["ʼĕyâlûwth"]', '["power; by implication, protection strength."]', '["n-f"]', 'power; by implication, protection strength.', 'feminine of 353;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H361}/[H361]', 'lemma', 'heb', 'אֵילָם', '["ʼêylâm"]', '["a pillar-space (or colonnade), i.e. a pale (or portico) arch."]', '["n-m"]', 'a pillar-space (or colonnade), i.e. a pale (or portico) arch.', 'or (shortened) אֵלָם ; or (feminine) אֵלַמָּה ; probably from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H362}/[H362]', 'lemma', 'heb', 'אֵילִם', '["ʼÊylim"]', '["Elim, a place in the Desert Elim."]', '["n-pr-loc"]', 'Elim, a place in the Desert Elim.', 'plural of 352; palm-trees;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H363}/[H363]', 'lemma', 'arc', 'אִילָן', '["ʼîylân"]', '["a tree tree."]', '["n-m"]', 'a tree tree.', '(Aramaic) corresponding to 356;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H364}/[H364]', 'lemma', 'heb', 'אֵיל פָּארָן', '["ʼÊyl Pâʼrân"]', '["El-Paran, a portion of the district of Paran El-paran."]', '["n-pr-loc"]', 'El-Paran, a portion of the district of Paran El-paran.', 'from 352 and 6290; oak of Paran;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H365}/[H365]', 'lemma', 'heb', 'אַיֶּלֶת', '["ʼayeleth"]', '["a doe hind, Aijeleth."]', '["n-f"]', 'a doe hind, Aijeleth.', 'the same as 355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H366>', 'opaque', 'heb', 'אָיֹם', '["ʼâyôm"]', '["frightful terrible."]', '["a"]', 'frightful terrible.', 'from an unused root (meaning to frighten);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H367}/[H367]', 'lemma', 'heb', 'אֵימָה', '["ʼêymâh"]', '["fright; concrete, an idol (as a bugbear) dread, fear, horror, idol, terrible, terror."]', '["n-f"]', 'fright; concrete, an idol (as a bugbear) dread, fear, horror, idol, terrible, terror.', 'or (shortened) אֵמָה; from the same as 366;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H368}/[H368]', 'lemma', 'heb', 'אֵימִים', '["ʼÊymîym"]', '["Emim, an early Canaanitish (or Maobitish) tribe Emims."]', '["n-pr-m"]', 'Emim, an early Canaanitish (or Maobitish) tribe Emims.', 'plural of 367; terrors;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H369]', 'root', 'heb', 'אַיִן', '["ʼayin"]', '["a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370."]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H370}/[H370]', 'lemma', 'heb', 'אַיִן', '["ʼayin"]', '["where? (only in connection with prepositional prefix, whence) whence, where."]', '["adv"]', 'where? (only in connection with prepositional prefix, whence) whence, where.', 'probably identical with 369 in the sense of query (compare 336)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H371}/[H371]', 'lemma', 'heb', 'אִין', '["ʼîyn"]', '["is it not? not."]', '["adv"]', 'is it not? not.', 'apparently a shortened form of 369; but (like 370) an interrogative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H372}/[H372]', 'lemma', 'heb', 'אִיעֶזֵר', '["ʼÎyʻezêr"]', '["Iezer, an Israelite Jeezer."]', '["n-pr-m"]', 'Iezer, an Israelite Jeezer.', 'from 336 and 5828; helpless;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H373}/[H373]', 'lemma', 'heb', 'אִיעֶזְרִי', '["ʼÎyʻezrîy"]', '["an Iezrite or descendant of Iezer Jezerite."]', '["a"]', 'an Iezrite or descendant of Iezer Jezerite.', 'patronymic from 372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H374}/[H374]', 'lemma', 'heb', 'אֵיפָה', '["ʼêyphâh"]', '["an ephah or measure for grain; hence, a measure in general ephah, (divers) measure(-s)."]', '["n-f"]', 'an ephah or measure for grain; hence, a measure in general ephah, (divers) measure(-s).', 'or (shortened) אֵפָה ; of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H375}/[H375]', 'lemma', 'heb', 'אֵיפֹה', '["ʼêyphôh"]', '["what place?; also (of time) when?; or (of means) how? what manner, where."]', '["adv"]', 'what place?; also (of time) when?; or (of means) how? what manner, where.', 'from 335 and 6311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H376>', 'opaque', 'heb', 'אִישׁ', '["ʼîysh"]', '["a man as an individual or a male person; often used as an adjunct to a more definite term (and in such cases frequently not expressed in translation) also, another, any (man), a certain, champion, consent, each, every (one), fellow, (foot-, husband-) man, (good-, great, mighty) man, he, high (degree), him (that is), husband, man(-kind), none, one, people, person, steward, what (man) soever, whoso(-ever), worthy. Compare 802."]', '["n-m"]', 'a man as an individual or a male person; often used as an adjunct to a more definite term (and in such cases frequently not expressed in translation) also, another, any (man), a certain, champion, consent, each, every (one), fellow, (foot-, husband-) man, (good-, great, mighty) man, he, high (degree), him (that is), husband, man(-kind), none, one, people, person, steward, what (man) soever, whoso(-ever), worthy. Compare 802.', 'contracted for 582 (or perhaps rather from an unused root meaning to be extant);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H377}/[H377]', 'lemma', 'heb', 'אִישׁ', '["ʼîysh"]', '["to be a man, i.e. act in a manly way show (one) self a man."]', '["v"]', 'to be a man, i.e. act in a manly way show (one) self a man.', 'denominative from 376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H378}/[H378]', 'lemma', 'heb', 'אִישׁ־בֹּשֶׁת', '["ʼÎysh-Bôsheth"]', '["Ish-Bosheth, a son of King Saul Ish-bosheth."]', '["n-pr-m"]', 'Ish-Bosheth, a son of King Saul Ish-bosheth.', 'from 376 and 1322; man of shame;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H379}/[H379]', 'lemma', 'heb', 'אִישְׁהוֹד', '["ʼÎyshᵉhôwd"]', '["Ishod, an Israelite Ishod."]', '["n-pr-m"]', 'Ishod, an Israelite Ishod.', 'from 376 and 1935; man of renown;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H380}/[H380]', 'lemma', 'heb', 'אִישׁוֹן', '["ʼîyshôwn"]', '["the little man of the eye; the pupil or ball; hence, the middle (of night) apple (of the eye), black, obscure."]', '["n-m"]', 'the little man of the eye; the pupil or ball; hence, the middle (of night) apple (of the eye), black, obscure.', 'diminutive from 376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H381}/[H381]', 'lemma', 'heb', 'אִישׁ־חַיִל', '["ʼÎysh-Chayil"]', '["Ishchail (or Ish-chai), an Israelite a valiant man."]', '["n-m"]', 'Ishchail (or Ish-chai), an Israelite a valiant man.', 'from 376 and 2428; man of might; by defective transcription (2 Samuel 23:20) אִישׁ־חַיxlit ʼÎsh-Chay corrected to ʼÎysh-Chay; as if from 376 and 2416; living man;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H382}/[H382]', 'lemma', 'heb', 'אִישׁ־טוֹב', '["ʼÎysh-Ṭôwb"]', '["Ish-Tob, a place in Palestine Ish-tob."]', '["n-pr-loc"]', 'Ish-Tob, a place in Palestine Ish-tob.', 'from 376 and 2897; man of Tob;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H383}/[H383]', 'lemma', 'arc', 'אִיתַי', '["ʼîythay"]', '["properly, entity; used only as a particle of affirmation, there is art thou, can, do ye, have, it be, there is (are), × we will not."]', '["prt"]', 'properly, entity; used only as a particle of affirmation, there is art thou, can, do ye, have, it be, there is (are), × we will not.', '(Aramaic) corresponding to 3426;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H384}/[H384]', 'lemma', 'heb', 'אִיתִיאֵל', '["ʼÎythîyʼêl"]', '["Ithiel, the name of an Israelite, also of a symbolical person Ithiel."]', '["n-pr-m"]', 'Ithiel, the name of an Israelite, also of a symbolical person Ithiel.', 'perhaps from 837 and 410; God has arrived;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H385}/[H385]', 'lemma', 'heb', 'אִיתָמָר', '["ʼÎythâmâr"]', '["Ithamar, a son of Aaron Ithamar."]', '["n-pr-m"]', 'Ithamar, a son of Aaron Ithamar.', 'from 339 and 8558; coast of the palm-tree;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H386>', 'opaque', 'heb', 'אֵיתָן', '["ʼêythân"]', '["permanence; hence (concrete) permanent; specifically a chieftain hard, mighty, rough, strength, strong."]', '["a"]', 'permanence; hence (concrete) permanent; specifically a chieftain hard, mighty, rough, strength, strong.', 'or (shortened) אֵתָן ; from an unused root (meaning to continue);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H387}/[H387]', 'lemma', 'heb', 'אֵיתָן', '["ʼÊythân"]', '["Ethan, the name of four Israelites Ethan."]', '["n-pr-m"]', 'Ethan, the name of four Israelites Ethan.', 'the same as 386; permanent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H388}/[H388]', 'lemma', 'heb', 'אֵיתָנִים', '["ʼÊythânîym"]', '["Ethanim, the name of a month Ethanim."]', '["n-pr-m"]', 'Ethanim, the name of a month Ethanim.', 'plural of 386; always with the article; the permanent brooks;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H389}/[H389]', 'lemma', 'heb', 'אַךְ', '["ʼak"]', '["a particle of affirmation, surely; hence (by limitation) only also, in any wise, at least, but, certainly, even, howbeit, nevertheless, notwithstanding, only, save, surely, of a surety, truly, verily, wherefore, yet (but)."]', '["adv"]', 'a particle of affirmation, surely; hence (by limitation) only also, in any wise, at least, but, certainly, even, howbeit, nevertheless, notwithstanding, only, save, surely, of a surety, truly, verily, wherefore, yet (but).', 'akin to 403;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H390>', 'opaque', 'heb', 'אַכַּד', '["ʼAkkad"]', '["Accad, a place in Babylon Accad."]', '["n-pr-loc"]', 'Accad, a place in Babylon Accad.', 'from an unused root probably meaning to strengthen; a fortress;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H391}/[H391]', 'lemma', 'heb', 'אַכְזָב', '["ʼakzâb"]', '["falsehood; by implication treachery liar, lie."]', '["a"]', 'falsehood; by implication treachery liar, lie.', 'from 3576;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H392}/[H392]', 'lemma', 'heb', 'אַכְזִיב', '["ʼAkzîyb"]', '["Akzib, the name of two places in Palestine Achzib."]', '["n-pr-loc"]', 'Akzib, the name of two places in Palestine Achzib.', 'from 391; deceitful (in the sense of a winter-torrent which fails in summer);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H393>', 'opaque', 'heb', 'אַכְזָר', '["ʼakzâr"]', '["violent; by implication deadly; also (in a good sense) brave cruel, fierce."]', '["a"]', 'violent; by implication deadly; also (in a good sense) brave cruel, fierce.', 'from an unused root (apparently meaning to act harshly);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H394}/[H394]', 'lemma', 'heb', 'אַכְזָרִי', '["ʼakzârîy"]', '["terrible cruel (one)."]', '["a"]', 'terrible cruel (one).', 'from 393;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H395}/[H395]', 'lemma', 'heb', 'אַכְזְרִיּוּת', '["ʼakzᵉrîyûwth"]', '["fierceness cruel."]', '["n-f"]', 'fierceness cruel.', 'from 394;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H396}/[H396]', 'lemma', 'heb', 'אֲכִילָה', '["ʼăkîylâh"]', '["something eatable, i.e. food meat."]', '["n-f"]', 'something eatable, i.e. food meat.', 'feminine from 398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H397>', 'opaque', 'heb', 'אֲכִישׁ', '["ʼĂkîysh"]', '["Akish, a Philistine king Achish."]', '["n-pr-m"]', 'Akish, a Philistine king Achish.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H398]', 'root', 'heb', 'אָכַל', '["ʼâkal"]', '["to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite."]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H399}/[H399]', 'lemma', 'arc', 'אֲכַל', '["ʼăkal"]', '["accuse, devour, eat."]', '["v"]', 'accuse, devour, eat.', '(Aramaic) corresponding to 398');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H400}/[H400]', 'lemma', 'heb', 'אֹכֶל', '["ʼôkel"]', '["food eating, food, meal(-time), meat, prey, victuals."]', '["n-m"]', 'food eating, food, meal(-time), meat, prey, victuals.', 'from 398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H401}/[H401]', 'lemma', 'heb', 'אֻכָל', '["ʼUkâl"]', '["Ucal, a fancy name Ucal."]', '["n-pr-m"]', 'Ucal, a fancy name Ucal.', 'or אֻכָּל; apparently from 398; devoured;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H402}/[H402]', 'lemma', 'heb', 'אׇכְלָה', '["ʼoklâh"]', '["food consume, devour, eat, food, meat."]', '["n-f"]', 'food consume, devour, eat, food, meat.', 'feminine of 401;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H403}/[H403]', 'lemma', 'heb', 'אָכֵן', '["ʼâkên"]', '["firmly; figuratively, surely; also (adversative) but but, certainly, nevertheless, surely, truly, verily."]', '["adv"]', 'firmly; figuratively, surely; also (adversative) but but, certainly, nevertheless, surely, truly, verily.', 'from 3559 (compare 3651);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H404]', 'root', 'heb', 'אָכַף', '["ʼâkaph"]', '["to urge crave."]', '["v"]', 'to urge crave.', 'a primitive root; apparently meaning to curve (as with a burden);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H405}/[H405]', 'lemma', 'heb', 'אֶכֶף', '["ʼekeph"]', '["a load; by implication, a stroke (others dignity) hand."]', '["n-m"]', 'a load; by implication, a stroke (others dignity) hand.', 'from 404;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H406>', 'opaque', 'heb', 'אִכָּר', '["ʼikkâr"]', '["a farmer husbandman, ploughman."]', '["n-m"]', 'a farmer husbandman, ploughman.', 'from an unused root meaning to dig;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H407}/[H407]', 'lemma', 'heb', 'אַכְשָׁף', '["ʼAkshâph"]', '["Acshaph, a place in Palestine Achshaph."]', '["n-pr-loc"]', 'Acshaph, a place in Palestine Achshaph.', 'from 3784; fascination;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H408}/[H408]', 'lemma', 'heb', 'אַל', '["ʼal"]', '["not (the qualified negation, used as a deprecative); once (Job 24:25) as a noun, nothing nay, neither, + never, no, nor, not, nothing (worth), rather than."]', '["adv"]', 'not (the qualified negation, used as a deprecative); once (Job 24:25) as a noun, nothing nay, neither, + never, no, nor, not, nothing (worth), rather than.', 'a negative particle (akin to 3808);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H409}/[H409]', 'lemma', 'arc', 'אַל', '["ʼal"]', '["not."]', '["adv"]', 'not.', '(Aramaic) corresponding to 408');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H410}/[H410]', 'lemma', 'heb', 'אֵל', '["ʼêl"]', '["strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H411}/[H411]', 'lemma', 'heb', 'אֵל', '["ʼêl"]', '["these or those these, those. Compare 428."]', '["d"]', 'these or those these, those. Compare 428.', 'a demonstrative particle (but only in a plural sense)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H412}/[H412]', 'lemma', 'arc', 'אֵל', '["ʼêl"]', '["these."]', '["d"]', 'these.', '(Aramaic) corresponding to 411');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H413}/[H413]', 'lemma', 'heb', 'אֵל', '["ʼêl"]', '["near, with or among; often in general, to about, according to, after, against, among, as for, at, because(-fore, -side), both...and, by, concerning, for, from, × hath, in(-to), near, (out) of, over, through, to(-ward), under, unto, upon, whether, with(-in)."]', '["prep"]', 'near, with or among; often in general, to about, according to, after, against, among, as for, at, because(-fore, -side), both...and, by, concerning, for, from, × hath, in(-to), near, (out) of, over, through, to(-ward), under, unto, upon, whether, with(-in).', '(but only used in the shortened constructive form אֶל ); a primitive particle; properly, denoting motion towards, but occasionally used of a quiescent position, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H414}/[H414]', 'lemma', 'heb', 'אֵלָא', '["ʼÊlâʼ"]', '["Ela, an Israelite Elah."]', '["n-pr-m"]', 'Ela, an Israelite Elah.', 'a variation of 424; oak;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H415}/[H415]', 'lemma', 'heb', 'אֵל אֱלֹהֵי יִשְׂרָאֵל', '["ʼÊl ʼĕlôhêy Yisrâʼêl"]', '["El-Elohi-Jisrael, the title given to a consecrated spot by Jacob Elelohe-israel."]', '["n-pr"]', 'El-Elohi-Jisrael, the title given to a consecrated spot by Jacob Elelohe-israel.', 'from 410 and 430 and 3478; the mighty god if Jisrael;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H416}/[H416]', 'lemma', 'heb', 'אֵל בֵּית־אֵל', '["ʼÊl Bêyth-ʼÊl"]', '["El-Bethel, the title given to a consecrated spot by Jacob El-beth-el."]', '["n-pr-loc"]', 'El-Bethel, the title given to a consecrated spot by Jacob El-beth-el.', 'from 410 and 1008; the God of Bethel;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H417}/[H417]', 'lemma', 'heb', 'אֶלְגָּבִישׁ', '["ʼelgâbîysh"]', '["hail (as if a great pearl) great hail(-stones)."]', '["n-m"]', 'hail (as if a great pearl) great hail(-stones).', 'from 410 and 1378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H418}/[H418]', 'lemma', 'heb', 'אַלְגּוּמִּים', '["ʼalgûwmmîym"]', '["sticks of algum wood algum (trees)."]', '["n-m"]', 'sticks of algum wood algum (trees).', 'by transposition for 484;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H419}/[H419]', 'lemma', 'heb', 'אֶלְדָּד', '["ʼEldâd"]', '["Eldad, an Israelite Eldad."]', '["n-pr-m"]', 'Eldad, an Israelite Eldad.', 'from 410 and 1730; God has loved;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H420}/[H420]', 'lemma', 'heb', 'אֶלְדָּעָה', '["ʼEldâʻâh"]', '["Eldaah, a son of Midian Eldaah."]', '["n-pr-m"]', 'Eldaah, a son of Midian Eldaah.', 'from 410 and 3045; God of knowledge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H421]', 'root', 'heb', 'אָלָה', '["ʼâlâh"]', '["to bewail lament."]', '["v"]', 'to bewail lament.', 'a primitive root (rather identical with 422 through the idea of invocation);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H422]', 'root', 'heb', 'אָלָה', '["ʼâlâh"]', '["properly, to adjure, i.e. (usually in a bad sense) imprecate adjure, curse, swear."]', '["v"]', 'properly, to adjure, i.e. (usually in a bad sense) imprecate adjure, curse, swear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H423}/[H423]', 'lemma', 'heb', 'אָלָה', '["ʼâlâh"]', '["an imprecation curse, cursing, execration, oath, swearing."]', '["n-f"]', 'an imprecation curse, cursing, execration, oath, swearing.', 'from 422;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H424}/[H424]', 'lemma', 'heb', 'אֵלָה', '["ʼêlâh"]', '["an oak or other strong tree elm, oak, teil-tree."]', '["n-f"]', 'an oak or other strong tree elm, oak, teil-tree.', 'feminine of 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H425}/[H425]', 'lemma', 'heb', 'אֵלָה', '["ʼÊlâh"]', '["Elah, the name of an Edomite, of four Israelites, and also of a place in Palestine Elah."]', '["n-pr"]', 'Elah, the name of an Edomite, of four Israelites, and also of a place in Palestine Elah.', 'the same as 424;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H426}/[H426]', 'lemma', 'heb', 'אֱלָהּ', '["ʼĕlâhh"]', '["God God, god."]', '["n-m"]', 'God God, god.', '(Aramaic) corresponding to 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H427}/[H427]', 'lemma', 'heb', 'אַלָּה', '["ʼallâh"]', '["oak."]', '["n-m"]', 'oak.', 'A variation of 424');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H428}/[H428]', 'lemma', 'heb', 'אֵלֶּה', '["ʼêl-leh"]', '["these or those an-(the) other; one sort, so, some, such, them, these (same), they, this, those, thus, which, who(-m)."]', '["d"]', 'these or those an-(the) other; one sort, so, some, such, them, these (same), they, this, those, thus, which, who(-m).', 'prolonged from 411;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H429}/[H429]', 'lemma', 'arc', 'אֵלֶּה', '["ʼêlleh"]', '["these."]', '["d"]', 'these.', '(Aramaic) corresponding to 428');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H430}/[H430]', 'lemma', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty."]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H431}/[H431]', 'lemma', 'arc', 'אֲלוּ', '["ʼălûw"]', '["lo! behold."]', '["inj"]', 'lo! behold.', '(Aramaic) probably prolonged from 412;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H432}/[H432]', 'lemma', 'heb', 'אִלּוּ', '["ʼillûw"]', '["nay, i.e. (softened) if but if, yea though."]', '["conj"]', 'nay, i.e. (softened) if but if, yea though.', 'probably from 408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H433}/[H433]', 'lemma', 'heb', 'אֱלוֹהַּ', '["ʼĕlôwahh"]', '["a deity or the Deity God, god. See 430."]', '["n-m"]', 'a deity or the Deity God, god. See 430.', 'rarely (shortened) אֱלֹהַּ; probably prolonged (emphatic) from 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H434}/[H434]', 'lemma', 'heb', 'אֱלוּל', '["ʼĕlûwl"]', '["good for nothing thing of nought."]', '["a"]', 'good for nothing thing of nought.', 'for 457;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H435}/[H435]', 'lemma', 'heb', 'אֱלוּל', '["ʼĔlûwl"]', '["Elul, the sixth Jewish month Elul."]', '["n"]', 'Elul, the sixth Jewish month Elul.', 'probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H436}/[H436]', 'lemma', 'heb', 'אֵלוֹן', '["ʼêlôwn"]', '["an oak or other strong tree plain. See also 356."]', '["n-m"]', 'an oak or other strong tree plain. See also 356.', 'prolonged from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H437}/[H437]', 'lemma', 'heb', 'אַלּוֹן', '["ʼallôwn"]', '["oak."]', '["n-m"]', 'oak.', 'a variation of 436');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H438}/[H438]', 'lemma', 'heb', 'אַלּוֹן', '["ʼAllôwn"]', '["Allon, an Israelite, also a place in Palestine Allon."]', '["n-pr"]', 'Allon, an Israelite, also a place in Palestine Allon.', 'the same as 437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H439}/[H439]', 'lemma', 'heb', 'אַלּוֹן בָּכוּת', '["ʼAllôwn Bâkûwth"]', '["Allon-Bakuth, a monumental tree Allon-bachuth."]', '["n-pr-loc"]', 'Allon-Bakuth, a monumental tree Allon-bachuth.', 'from 437 and a variation of 1068; oak of weeping;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H440}/[H440]', 'lemma', 'heb', 'אֵלוֹנִי', '["ʼÊlôwnîy"]', '["an Elonite or descendant (collectively) of Elon Elonites."]', '["a"]', 'an Elonite or descendant (collectively) of Elon Elonites.', 'or rather (shortened) אֵלֹנִי; patron from 438;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H441}/[H441]', 'lemma', 'heb', 'אַלּוּף', '["ʼallûwph"]', '["familiar; a friend, also gentle; hence, a bullock (as being tame; applied, although masculine, to a cow); and so, a chieftain (as notable, like neat cattle) captain, duke, (chief) friend, governor, guide, ox."]', '["a-m"]', 'familiar; a friend, also gentle; hence, a bullock (as being tame; applied, although masculine, to a cow); and so, a chieftain (as notable, like neat cattle) captain, duke, (chief) friend, governor, guide, ox.', 'or (shortened) אַלֻּף; from 502;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H442>', 'opaque', 'heb', 'אָלוּשׁ', '["ʼÂlûwsh"]', '["Alush, a place in the Desert Alush."]', '["n-pr-loc"]', 'Alush, a place in the Desert Alush.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H443}/[H443]', 'lemma', 'heb', 'אֶלְזָבָד', '["ʼElzâbâd"]', '["Elzabad, the name of two Israelites Elzabad."]', '["n-pr-m"]', 'Elzabad, the name of two Israelites Elzabad.', 'from 410 and 2064; God has bestowed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H444]', 'root', 'heb', 'אָלַח', '["ʼâlach"]', '["to muddle, i.e. (figuratively and intransitive) to turn (morally) corrupt become filthy."]', '["v"]', 'to muddle, i.e. (figuratively and intransitive) to turn (morally) corrupt become filthy.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H445}/[H445]', 'lemma', 'heb', 'אֶלְחָנָן', '["ʼElchânân"]', '["Elchanan, an Israelite Elkanan."]', '["n-pr-m"]', 'Elchanan, an Israelite Elkanan.', 'from 410 and 2603; God (is) gracious;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H446}/[H446]', 'lemma', 'heb', 'אֱלִיאָב', '["ʼĔlîyʼâb"]', '["Eliab, the name of six Israelites Eliab."]', '["n-pr-m"]', 'Eliab, the name of six Israelites Eliab.', 'from 410 and 1; God of (his) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H447}/[H447]', 'lemma', 'heb', 'אֱלִיאֵל', '["ʼĔlîyʼêl"]', '["Eliel, the name of nine Israelites Eliel."]', '["n-pr-m"]', 'Eliel, the name of nine Israelites Eliel.', 'from 410 repeated; God of (his) God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H448}/[H448]', 'lemma', 'heb', 'אֱלִיאָתָה', '["ʼĔlîyʼâthâh"]', '["Eliathah, an Israelite Eliathah."]', '["n-pr-m"]', 'Eliathah, an Israelite Eliathah.', 'or (contraction) אֱלִיָּתָה; from 410 and 225; God of (his) consent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H449}/[H449]', 'lemma', 'heb', 'אֱלִידָד', '["ʼĔlîydâd"]', '["Elidad, an Israelite Elidad."]', '["n-pr-m"]', 'Elidad, an Israelite Elidad.', 'from the same as 419; God of (his) love;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H450}/[H450]', 'lemma', 'heb', 'אֶלְיָדָע', '["ʼElyâdâʻ"]', '["Eljada, the name of two Israelites and of an Aramaean leader Eliada."]', '["n-pr-m"]', 'Eljada, the name of two Israelites and of an Aramaean leader Eliada.', 'from 410 and 3045; God (is) knowing;');
