INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H501}/[H501]', 'lemma', 'heb', 'אֶלְעָשָׂה', '["ʼElʻâsâh"]', '["Elasah, the name of four Israelites Elasah, Eleasah."]', '["n-pr-m"]', 'Elasah, the name of four Israelites Elasah, Eleasah.', 'from 410 and 6213; God has made;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H502]', 'root', 'heb', 'אָלַף', '["ʼâlaph"]', '["hence, to learn (and causatively to teach) learn, teach, utter."]', '["v"]', 'hence, to learn (and causatively to teach) learn, teach, utter.', 'a primitive root, to associate with;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H503}/[H503]', 'lemma', 'heb', 'אָלַף', '["ʼâlaph"]', '["causative, to make a thousandfold bring forth thousands."]', '["v"]', 'causative, to make a thousandfold bring forth thousands.', 'denominative from 505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H504}/[H504]', 'lemma', 'heb', 'אֶלֶף', '["ʼeleph"]', '["a family; also (from the sense of yoking or taming) an ox or cow family, kine, oxen."]', '["n-m"]', 'a family; also (from the sense of yoking or taming) an ox or cow family, kine, oxen.', 'from 502;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H505}/[H505]', 'lemma', 'heb', 'אֶלֶף', '["ʼeleph"]', '["hence (the ox''s head being the first letter of the alphabet, and this eventually used as a numeral) a thousand thousand."]', '["n-m"]', 'hence (the ox''s head being the first letter of the alphabet, and this eventually used as a numeral) a thousand thousand.', 'prop, the same as 504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H506}/[H506]', 'lemma', 'arc', 'אֲלַף', '["ʼălaph"]', '["thousand."]', '["n-m"]', 'thousand.', '(Aramaic) or אֶלֶף; (Aramaic), corresponding to 505');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H507}/[H507]', 'lemma', 'heb', 'אֶלֶף', '["ʼEleph"]', '["Eleph, a place in Palestine Eleph."]', '["n-pr-loc"]', 'Eleph, a place in Palestine Eleph.', 'the same as 505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H508}/[H508]', 'lemma', 'heb', 'אֶלְפַּעַל', '["ʼElpaʻal"]', '["Elpaal, an Israelite Elpaal."]', '["n-pr-m"]', 'Elpaal, an Israelite Elpaal.', 'from 410 and 6466; God (is) act;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H509]', 'root', 'heb', 'אָלַץ', '["ʼâlats"]', '["to press urge."]', '["v"]', 'to press urge.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H510}/[H510]', 'lemma', 'heb', 'אַלְקוּם', '["ʼalqûwm"]', '["a non-rising (i.e. resistlessness) no rising up."]', '["n-m"]', 'a non-rising (i.e. resistlessness) no rising up.', 'probably from 408 and 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H511}/[H511]', 'lemma', 'heb', 'אֶלְקָנָה', '["ʼElqânâh"]', '["Elkanah, the name of several Israelites Elkanah."]', '["n-pr-m"]', 'Elkanah, the name of several Israelites Elkanah.', 'from 410 and 7069; God has obtained;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H512>', 'opaque', 'heb', 'אֶלְקֹשִׁי', '["ʼElqôshîy"]', '["an Elkoshite or native of Elkosh Elkoshite."]', '["a"]', 'an Elkoshite or native of Elkosh Elkoshite.', 'patrial from a name of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H513}/[H513]', 'lemma', 'heb', 'אֶלְתּוֹלַד', '["ʼEltôwlad"]', '["Eltolad, a place in Palestine Eltolad."]', '["n-pr-loc"]', 'Eltolad, a place in Palestine Eltolad.', 'probably from 410 and a masculine form of 8435 (compare 8434); God (is) generator;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H514>', 'opaque', 'heb', 'אֶלְתְּקֵא', '["ʼEltᵉqêʼ"]', '["Eltekeh or Elteke, a place in Palestine Eltekeh."]', '["n-pr-loc"]', 'Eltekeh or Elteke, a place in Palestine Eltekeh.', 'or (more properly) אֶלְתְּקֵה; of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H515}/[H515]', 'lemma', 'heb', 'אֶלְתְּקֹן', '["ʼEltᵉqôn"]', '["Eltekon, a place in Palestine Eltekon."]', '["n-pr-loc"]', 'Eltekon, a place in Palestine Eltekon.', 'from 410 and 8626; God (is) straight;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H516}/[H516]', 'lemma', 'heb', 'אַל תַּשְׁחֵת', '["ʼAl tashchêth"]', '["''Thou must not destroy''; probably the opening words to a popular song Al-taschith."]', '["n-m"]', '''Thou must not destroy''; probably the opening words to a popular song Al-taschith.', 'from 408 and 7843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H517]', 'root', 'heb', 'אֵם', '["ʼêm"]', '["a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting."]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H518}/[H518]', 'lemma', 'heb', 'אִם', '["ʼim"]', '["used very widely as demonstrative, lo!; interrogative, whether?; or conditional, if, although; also Oh that!, when; hence, as a negative, not (and, can-, doubtless, if, that) (not), + but, either, + except, + more(-over if, than), neither, nevertheless, nor, oh that, or, + save (only, -ing), seeing, since, sith, + surely (no more, none, not), though, + of a truth, + unless, + verily, when, whereas, whether, while, + yet."]', '["prt"]', 'used very widely as demonstrative, lo!; interrogative, whether?; or conditional, if, although; also Oh that!, when; hence, as a negative, not (and, can-, doubtless, if, that) (not), + but, either, + except, + more(-over if, than), neither, nevertheless, nor, oh that, or, + save (only, -ing), seeing, since, sith, + surely (no more, none, not), though, + of a truth, + unless, + verily, when, whereas, whether, while, + yet.', 'a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H519]', 'root', 'heb', 'אָמָה', '["ʼâmâh"]', '["a maid-servant or female slave (hand-) bondmaid(-woman), maid(-servant)."]', '["n-f"]', 'a maid-servant or female slave (hand-) bondmaid(-woman), maid(-servant).', 'apparently a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H520}/[H520]', 'lemma', 'heb', 'אַמָּה', '["ʼammâh"]', '["properly, a mother (i.e. unit of measure, or the fore-arm (below the elbow), i.e. a cubit; also a door-base (as a bond of the entrance) cubit, + hundred (by exchange for 3967), measure, post."]', '["n-f"]', 'properly, a mother (i.e. unit of measure, or the fore-arm (below the elbow), i.e. a cubit; also a door-base (as a bond of the entrance) cubit, + hundred (by exchange for 3967), measure, post.', 'prolonged from 517;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H521}/[H521]', 'lemma', 'arc', 'אַמָּה', '["ʼammâh"]', '["cubit."]', '["n"]', 'cubit.', '(Aramaic) corresponding to 520');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H522}/[H522]', 'lemma', 'heb', 'אַמָּה', '["ʼAmmâh"]', '["Ammah, a hill in Palestine Ammah."]', '["n-pr-loc"]', 'Ammah, a hill in Palestine Ammah.', 'the same as 520;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H523}/[H523]', 'lemma', 'heb', 'אֻמַּה', '["ʼummah"]', '["a collection, i.e. community of persons nation, people."]', '["n-f"]', 'a collection, i.e. community of persons nation, people.', 'from the same as 517;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H524}/[H524]', 'lemma', 'arc', 'אֻמָּה', '["ʼummâh"]', '["nation."]', '["n-f"]', 'nation.', '(Aramaic) corresponding to 523');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H525}/[H525]', 'lemma', 'heb', 'אָמוֹן', '["ʼâmôwn"]', '["skilled, i.e. an architect one brought up."]', '["n-m"]', 'skilled, i.e. an architect one brought up.', 'from 539, probably in the sense of training; like 542');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H526}/[H526]', 'lemma', 'heb', 'אָמוֹן', '["ʼÂmôwn"]', '["Amon, the name of three Israelites Amon."]', '["n-pr-m"]', 'Amon, the name of three Israelites Amon.', 'the same as 525;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H527}/[H527]', 'lemma', 'heb', 'אָמוֹן', '["ʼâmôwn"]', '["a throng of people multitude."]', '["n-m"]', 'a throng of people multitude.', 'a variation for 1995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H528}/[H528]', 'lemma', 'heb', 'אָמוֹן', '["ʼÂmôwn"]', '["Amon (i.e. Ammon or Amn), a deity of Egypt multitude, populous."]', '["n-pr-m"]', 'Amon (i.e. Ammon or Amn), a deity of Egypt multitude, populous.', 'of Egyptian derivation; used only as an adjunct of 4996');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H529}/[H529]', 'lemma', 'heb', 'אֵמוּן', '["ʼêmûwn"]', '["established, i.e. (figuratively) trusty; also (abstractly) trustworthiness faith(-ful), truth."]', '["n-m"]', 'established, i.e. (figuratively) trusty; also (abstractly) trustworthiness faith(-ful), truth.', 'from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H530}/[H530]', 'lemma', 'heb', 'אֱמוּנָה', '["ʼĕmûwnâh"]', '["literally firmness; figuratively security; morally fidelity faith(-ful, -ly, -ness, (man)), set office, stability, steady, truly, truth, verily."]', '["n-f"]', 'literally firmness; figuratively security; morally fidelity faith(-ful, -ly, -ness, (man)), set office, stability, steady, truly, truth, verily.', 'or (shortened) אֱמֻנָה; feminine of 529;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H531}/[H531]', 'lemma', 'heb', 'אָמוֹץ', '["ʼÂmôwts"]', '["Amots, an Israelite Amoz."]', '["n-pr-m"]', 'Amots, an Israelite Amoz.', 'from 553; strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H532}/[H532]', 'lemma', 'heb', 'אָמִי', '["ʼÂmîy"]', '["Ami, an Israelite Ami."]', '["n-pr-m"]', 'Ami, an Israelite Ami.', 'an abbreviated form for 526;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H533}/[H533]', 'lemma', 'heb', 'אַמִּיץ', '["ʼammîyts"]', '["strong or (abstractly) strength courageous, mighty, strong (one)."]', '["a"]', 'strong or (abstractly) strength courageous, mighty, strong (one).', 'or (shortened) אַמִּץ; from 553;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H534}/[H534]', 'lemma', 'heb', 'אָמִיר', '["ʼâmîyr"]', '["a summit (of a tree or mountain) bough, branch."]', '["n-m"]', 'a summit (of a tree or mountain) bough, branch.', 'apparently from 559 (in the sense of self-exaltation);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H535]', 'root', 'heb', 'אָמַל', '["ʼâmal"]', '["to droop; by implication to be sick, to mourn languish, be weak, wax feeble."]', '["v"]', 'to droop; by implication to be sick, to mourn languish, be weak, wax feeble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H536}/[H536]', 'lemma', 'heb', 'אֻמְלַל', '["ʼumlal"]', '["sick weak."]', '["a"]', 'sick weak.', 'from 535;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H537}/[H537]', 'lemma', 'heb', 'אֲמֵלָל', '["ʼămêlâl"]', '["languid feeble."]', '["a"]', 'languid feeble.', 'from 535;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H538}/[H538]', 'lemma', 'heb', 'אֲמָם', '["ʼĂmâm"]', '["Amam, a place in Palestine Amam."]', '["n-pr-loc"]', 'Amam, a place in Palestine Amam.', 'from 517; gathering-spot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H539]', 'root', 'heb', 'אָמַן', '["ʼâman"]', '["properly, to build up or support; to foster as a parent or nurse; figuratively to render (or be) firm or faithful, to trust or believe, to be permanent or quiet; morally to be true or certain; hence, assurance, believe, bring up, establish, fail, be faithful (of long continuance, stedfast, sure, surely, trusty, verified), nurse, (-ing father), (put), trust, turn to the right."]', '["v"]', 'properly, to build up or support; to foster as a parent or nurse; figuratively to render (or be) firm or faithful, to trust or believe, to be permanent or quiet; morally to be true or certain; hence, assurance, believe, bring up, establish, fail, be faithful (of long continuance, stedfast, sure, surely, trusty, verified), nurse, (-ing father), (put), trust, turn to the right.', 'a primitive root; (Isaiah 30:21; interchangeable with 541, to go to the right hand)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H540}/[H540]', 'lemma', 'arc', 'אֲמַן', '["ʼăman"]', '["believe, faithful, sure."]', '["v"]', 'believe, faithful, sure.', '(Aramaic) corresponding to 539');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H541}/[H541]', 'lemma', 'heb', 'אָמַן', '["ʼâman"]', '["to take the right hand road turn to the right. See 539."]', '["v"]', 'to take the right hand road turn to the right. See 539.', 'denominative from 3225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H542}/[H542]', 'lemma', 'heb', 'אָמָן', '["ʼâmân"]', '["an expert cunning workman."]', '["n-m"]', 'an expert cunning workman.', 'from 539 (in the sense of training);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H543}/[H543]', 'lemma', 'heb', 'אָמֵן', '["ʼâmên"]', '["sure; abstract, faithfulness; adverb, truly Amen, so be it, truth."]', '["adv"]', 'sure; abstract, faithfulness; adverb, truly Amen, so be it, truth.', 'from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H544}/[H544]', 'lemma', 'heb', 'אֹמֶן', '["ʼômen"]', '["verity truth."]', '["n-m"]', 'verity truth.', 'from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H545}/[H545]', 'lemma', 'heb', 'אׇמְנָה', '["ʼomnâh"]', '["tutelage brought up."]', '["n-f"]', 'tutelage brought up.', 'feminine of 544 (in the specific sense of training);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H546}/[H546]', 'lemma', 'heb', 'אׇמְנָה', '["ʼomnâh"]', '["adverb, surely indeed."]', '["adv"]', 'adverb, surely indeed.', 'feminine form of 544 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H547}/[H547]', 'lemma', 'heb', 'אֹמְנָה', '["ʼômᵉnâh"]', '["a column pillar."]', '["n-f"]', 'a column pillar.', 'feminine active participle of 544 (in the original sense of supporting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H548}/[H548]', 'lemma', 'heb', 'אֲמָנָה', '["ʼămânâh"]', '["something fixed, i.e. a covenant. an allowance certain portion, sure."]', '["n-f"]', 'something fixed, i.e. a covenant. an allowance certain portion, sure.', 'feminine of 543;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H549}/[H549]', 'lemma', 'heb', 'אֲמָנָה', '["ʼĂmânâh"]', '["Amanah, a mountain near Damascus Amana."]', '["n-pr-loc"]', 'Amanah, a mountain near Damascus Amana.', 'the same as 548;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H550}/[H550]', 'lemma', 'heb', 'אַמְנוֹן', '["ʼAmnôwn"]', '["Amnon (or Aminon), a son of David Amnon."]', '["n-m"]', 'Amnon (or Aminon), a son of David Amnon.', 'or אֲמִינוֹן; from 539; faithful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H551}/[H551]', 'lemma', 'heb', 'אׇמְנָם', '["ʼomnâm"]', '["verily indeed, no doubt, surely, (it is, of a) true(-ly, -th)."]', '["adv"]', 'verily indeed, no doubt, surely, (it is, of a) true(-ly, -th).', 'adverb from 544;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H552}/[H552]', 'lemma', 'heb', 'אֻמְנָם', '["ʼumnâm"]', '["in (very) deed; of a surety."]', '["adv"]', 'in (very) deed; of a surety.', 'an orthographical variation of 551');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H553]', 'root', 'heb', 'אָמַץ', '["ʼâmats"]', '["to be alert, physically (on foot) or mentally (in courage) confirm, be courageous (of good courage, stedfastly minded, strong, stronger), establish, fortify, harden, increase, prevail, strengthen (self), make strong (obstinate, speed)."]', '["v"]', 'to be alert, physically (on foot) or mentally (in courage) confirm, be courageous (of good courage, stedfastly minded, strong, stronger), establish, fortify, harden, increase, prevail, strengthen (self), make strong (obstinate, speed).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H554}/[H554]', 'lemma', 'heb', 'אָמֹץ', '["ʼâmôts"]', '["of a strong color, i.e. red (others fleet) bay."]', '["a"]', 'of a strong color, i.e. red (others fleet) bay.', 'probably from 553;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H555}/[H555]', 'lemma', 'heb', 'אֹמֶץ', '["ʼômets"]', '["strength stronger."]', '["n-m"]', 'strength stronger.', 'from 553;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H556}/[H556]', 'lemma', 'heb', 'אַמְצָה', '["ʼamtsâh"]', '["force strength."]', '["n-f"]', 'force strength.', 'from 553;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H557}/[H557]', 'lemma', 'heb', 'אַמְצִי', '["ʼAmtsîy"]', '["Amtsi, an Israelite Amzi."]', '["n-pr-m"]', 'Amtsi, an Israelite Amzi.', 'from 553; strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H558}/[H558]', 'lemma', 'heb', 'אֲמַצְיָה', '["ʼĂmatsyâh"]', '["Amatsjah, the name of four Israelites Amaziah."]', '["n-pr-m"]', 'Amatsjah, the name of four Israelites Amaziah.', 'or אֲמַצְיָהוּ; from 553 and 3050; strength of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H559]', 'root', 'heb', 'אָמַר', '["ʼâmar"]', '["to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet."]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H560}/[H560]', 'lemma', 'arc', 'אֲמַר', '["ʼămar"]', '["command, declare, say, speak, tell."]', '["v"]', 'command, declare, say, speak, tell.', '(Aramaic) corresponding to 559');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H561}/[H561]', 'lemma', 'heb', 'אֵמֶר', '["ʼêmer"]', '["something said answer, × appointed unto him, saying, speech, word."]', '["n-m"]', 'something said answer, × appointed unto him, saying, speech, word.', 'from 559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H562}/[H562]', 'lemma', 'heb', 'אֹמֶר', '["ʼômer"]', '["promise, speech, thing, word."]', '["n-m"]', 'promise, speech, thing, word.', 'the same as 561');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H563}/[H563]', 'lemma', 'arc', 'אִמַּר', '["ʼimmar"]', '["a lamb lamb."]', '["n-m"]', 'a lamb lamb.', '(Aramaic) perhaps from 560 (in the sense of bringing forth);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H564}/[H564]', 'lemma', 'heb', 'אִמֵּר', '["ʼImmêr"]', '["Immer, the name of five Israelites Immer."]', '["n-pr-m"]', 'Immer, the name of five Israelites Immer.', 'from 559; talkative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H565}/[H565]', 'lemma', 'heb', 'אִמְרָה', '["ʼimrâh"]', '["commandment, speech, word."]', '["n-f"]', 'commandment, speech, word.', 'or אֶמְרָה; feminine of 561, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H566}/[H566]', 'lemma', 'heb', 'אִמְרִי', '["ʼImrîy"]', '["Imri, the name of two Israelites Imri."]', '["n-pr-m"]', 'Imri, the name of two Israelites Imri.', 'from 564;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H567}/[H567]', 'lemma', 'heb', 'אֱמֹרִי', '["ʼĔmôrîy"]', '["an Emorite, one of the Canaanitish tribes Amorite."]', '["n-m"]', 'an Emorite, one of the Canaanitish tribes Amorite.', 'probably a patronymic from an unused name derived from 559 in the sense of publicity, i.e. prominence; thus, a mountaineer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H568}/[H568]', 'lemma', 'heb', 'אֲמַרְיָה', '["ʼĂmaryâh"]', '["Amarjah, the name of nine Israelites Amariah."]', '["n-pr-m"]', 'Amarjah, the name of nine Israelites Amariah.', 'or prolonged אֲמַרְיָהוּ; from 559 and 3050; Jah has said (i.e. promised);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H569}/[H569]', 'lemma', 'heb', 'אַמְרָפֶל', '["ʼAmrâphel"]', '["Amraphel, a king of Shinar Amraphel."]', '["n-pr-m"]', 'Amraphel, a king of Shinar Amraphel.', 'of uncertain (perhaps foreign) derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H570}/[H570]', 'lemma', 'heb', 'אֶמֶשׁ', '["ʼemesh"]', '["yesterday or last night former time, yesterday(-night)"]', '["adv"]', 'yesterday or last night former time, yesterday(-night)', 'time past, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H571}/[H571]', 'lemma', 'heb', 'אֶמֶת', '["ʼemeth"]', '["stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity."]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H572}/[H572]', 'lemma', 'heb', 'אַמְתַּחַת', '["ʼamtachath"]', '["properly, something expansive, i.e. a bag sack."]', '["n-f"]', 'properly, something expansive, i.e. a bag sack.', 'from 4969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H573}/[H573]', 'lemma', 'heb', 'אֲמִתַּי', '["ʼĂmittay"]', '["Amittai, an Israelite Amittai."]', '["n-pr-m"]', 'Amittai, an Israelite Amittai.', 'from 571; veracious;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H574}/[H574]', 'lemma', 'arc', 'אֵמְתָּנִי', '["ʼêmᵉtânîy"]', '["well-loined (i.e. burly) or mighty terrible."]', '["a"]', 'well-loined (i.e. burly) or mighty terrible.', '(Aramaic) from a root corresponding to that of 4975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H575}/[H575]', 'lemma', 'heb', 'אָן', '["ʼân"]', '["where?; hence, whither?, when?; also hither and thither any (no) whither, now, where, whither(-soever)."]', '["adv"]', 'where?; hence, whither?, when?; also hither and thither any (no) whither, now, where, whither(-soever).', 'or אָנָה; contracted from 370;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H576}/[H576]', 'lemma', 'heb', 'אֲנָא', '["ʼănâʼ"]', '["I I, as for me."]', '["p"]', 'I I, as for me.', '(Aramaic) or אֲנָה; (Aramaic), corresponding to 589;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H577}/[H577]', 'lemma', 'heb', 'אָנָּא', '["ʼânnâʼ"]', '["oh now! I (me) beseech (pray) thee, O."]', '["inj"]', 'oh now! I (me) beseech (pray) thee, O.', 'or אָנָּה; apparent contracted from 160 and 4994;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H578]', 'root', 'heb', 'אָנָה', '["ʼânâh"]', '["to groan lament, mourn."]', '["v"]', 'to groan lament, mourn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H579]', 'root', 'heb', 'אָנָה', '["ʼânâh"]', '["to approach; hence, to meet in various senses befall, deliver, happen, seek a quarrel."]', '["v"]', 'to approach; hence, to meet in various senses befall, deliver, happen, seek a quarrel.', 'a primitive root (perhaps rather identical with 578 through the idea of contraction in anguish);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H580}/[H580]', 'lemma', 'heb', 'אֲנוּ', '["ʼănûw"]', '["we we."]', '["p"]', 'we we.', 'contracted for 587;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H581}/[H581]', 'lemma', 'arc', 'אִנּוּן', '["ʼinnûwn"]', '["they × are, them, these."]', '["d"]', 'they × are, them, these.', '(Aramaic) or (feminine) אִנִּיןlemma אֵנִּין first vowel, corrected to אִנִּין; (Aramaic), corresponding to 1992;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H582}/[H582]', 'lemma', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376."]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H583}/[H583]', 'lemma', 'heb', 'אֱנוֹשׁ', '["ʼĔnôwsh"]', '["Enosh, a son of Seth Enos."]', '["n-pr-m"]', 'Enosh, a son of Seth Enos.', 'the same as 582;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H584]', 'root', 'heb', 'אָנַח', '["ʼânach"]', '["to sigh groan, mourn, sigh."]', '["v"]', 'to sigh groan, mourn, sigh.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H585}/[H585]', 'lemma', 'heb', 'אֲנָחָה', '["ʼănâchâh"]', '["sighing groaning, mourn, sigh."]', '["n-f"]', 'sighing groaning, mourn, sigh.', 'from 584;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H586}/[H586]', 'lemma', 'arc', 'אֲנַחְנָא', '["ʼănachnâʼ"]', '["we we."]', '["p"]', 'we we.', '(Aramaic) or אֲנַחְנָה; (Aramaic), corresponding to 587;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H587}/[H587]', 'lemma', 'heb', 'אֲנַחְנוּ', '["ʼănachnûw"]', '["we ourselves, us, we."]', '["p"]', 'we ourselves, us, we.', 'apparently from 595;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H588}/[H588]', 'lemma', 'heb', 'אֲנָחֲרָת', '["ʼĂnâchărâth"]', '["Anacharath, a place in Palestine Anaharath."]', '["n-pr-loc"]', 'Anacharath, a place in Palestine Anaharath.', 'probably from the same root as 5170; a gorge or narrow pass;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H589}/[H589]', 'lemma', 'heb', 'אֲנִי', '["ʼănîy"]', '["I I, (as for) me, mine, myself, we, × which, × who."]', '["p"]', 'I I, (as for) me, mine, myself, we, × which, × who.', 'contracted from 595;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H590}/[H590]', 'lemma', 'heb', 'אֳנִי', '["ʼŏnîy"]', '["a ship or (collectively) a fleet galley, navy (of ships)."]', '["n"]', 'a ship or (collectively) a fleet galley, navy (of ships).', 'probably from 579 (in the sense of conveyance);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H591}/[H591]', 'lemma', 'heb', 'אֳנִיָּה', '["ʼŏnîyâh"]', '["a ship ship(-men)."]', '["n-f"]', 'a ship ship(-men).', 'feminine of 590;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H592}/[H592]', 'lemma', 'heb', 'אֲנִיָּה', '["ʼănîyâh"]', '["groaning lamentation, sorrow."]', '["n-f"]', 'groaning lamentation, sorrow.', 'from 578;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H593}/[H593]', 'lemma', 'heb', 'אֲנִיעָם', '["ʼĂnîyʻâm"]', '["Aniam, an Israelite Aniam."]', '["n-pr-m"]', 'Aniam, an Israelite Aniam.', 'from 578 and 5971; groaning of (the) people;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H594>', 'opaque', 'heb', 'אֲנָךְ', '["ʼănâk"]', '["according to most a plumb-line, and to others a hook plumb-line"]', '["n-m"]', 'according to most a plumb-line, and to others a hook plumb-line', 'probably from an unused root meaning to be narrow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H595}/[H595]', 'lemma', 'heb', 'אָנֹכִי', '["ʼânôkîy"]', '["I I, me, × which."]', '["p"]', 'I I, me, × which.', 'sometimes, אָנֹכִי; a primitive pronoun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H596]', 'root', 'heb', 'אָנַן', '["ʼânan"]', '["to mourn, i.e. complain complain."]', '["v"]', 'to mourn, i.e. complain complain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H597}/[H597]', 'lemma', 'heb', 'אָנַס', '["ʼânaç"]', '["to insist compel."]', '["v"]', 'to insist compel.', NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H598}/[H598]', 'lemma', 'arc', 'אֲנַס', '["ʼănaç"]', '["figuratively, to distress trouble."]', '["v"]', 'figuratively, to distress trouble.', '(Aramaic) corresponding to 597;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H599]', 'root', 'heb', 'אָנַף', '["ʼânaph"]', '["to breathe hard, i.e. be enraged be angry (displeased)."]', '["v"]', 'to breathe hard, i.e. be enraged be angry (displeased).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H600}/[H600]', 'lemma', 'arc', 'אֲנַף', '["ʼănaph"]', '["the face face, visage."]', '["n-m"]', 'the face face, visage.', '(Aramaic) corresponding to 639 (only in the plural as a singular);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H601}/[H601]', 'lemma', 'heb', 'אֲנָפָה', '["ʼănâphâh"]', '["an unclean bird, perhaps the parrot (from its irascibility) heron."]', '["n-f"]', 'an unclean bird, perhaps the parrot (from its irascibility) heron.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H602]', 'root', 'heb', 'אָנַק', '["ʼânaq"]', '["to shriek cry, groan."]', '["v"]', 'to shriek cry, groan.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H603}/[H603]', 'lemma', 'heb', 'אֲנָקָה', '["ʼănâqâh"]', '["shrieking crying out, groaning, sighing."]', '["n-f"]', 'shrieking crying out, groaning, sighing.', 'from 602;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H604}/[H604]', 'lemma', 'heb', 'אֲנָקָה', '["ʼănâqâh"]', '["some kind of lizard, probably the gecko (from its wail) ferret."]', '["n-f"]', 'some kind of lizard, probably the gecko (from its wail) ferret.', 'the same as 603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H605]', 'root', 'heb', 'אָנַשׁ', '["ʼânash"]', '["to be frail, feeble, or (figuratively) melancholy desperate(-ly wicked), incurable, sick, woeful."]', '["v"]', 'to be frail, feeble, or (figuratively) melancholy desperate(-ly wicked), incurable, sick, woeful.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H606}/[H606]', 'lemma', 'arc', 'אֱנָשׁ', '["ʼĕnâsh"]', '["a man man, whosoever."]', '["n-m"]', 'a man man, whosoever.', '(Aramaic) or אֱנַשׁ; (Aramaic), corresponding to 582;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H607}/[H607]', 'lemma', 'arc', 'אַנְתָּה', '["ʼantâh"]', '["thou as for thee, thou."]', '["p"]', 'thou as for thee, thou.', '(Aramaic) corresponding to 859;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H608}/[H608]', 'lemma', 'arc', 'אַנְתּוּן', '["ʼantûwn"]', '["ye ye."]', '["p"]', 'ye ye.', '(Aramaic) plural of 607;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H609>', 'opaque', 'heb', 'אָסָא', '["ʼÂçâʼ"]', '["Asa, the name of a king and of a Levite Asa."]', '["n-pr-m"]', 'Asa, the name of a king and of a Levite Asa.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H610}/[H610]', 'lemma', 'heb', 'אָסוּךְ', '["ʼâçûwk"]', '["anointed, i.e. an oil-flask pot."]', '["n-m"]', 'anointed, i.e. an oil-flask pot.', 'from 5480;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H611>', 'opaque', 'heb', 'אָסוֹן', '["ʼâçôwn"]', '["hurt mischief."]', '["n-m"]', 'hurt mischief.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H612}/[H612]', 'lemma', 'heb', 'אֵסוּר', '["ʼêçûwr"]', '["a bond (especially manacles of a prisoner) band, prison."]', '["n-m"]', 'a bond (especially manacles of a prisoner) band, prison.', 'from 631;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H613}/[H613]', 'lemma', 'arc', 'אֱסוּר', '["ʼĕçûwr"]', '["band, imprisonment."]', '["n-m"]', 'band, imprisonment.', '(Aramaic) corresponding to 612');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H614}/[H614]', 'lemma', 'heb', 'אָסִיף', '["ʼâçîyph"]', '["gathered, i.e. (abstractly) a gathering in of crops ingathering."]', '["n-m"]', 'gathered, i.e. (abstractly) a gathering in of crops ingathering.', 'or אָסִף; from 622;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H615}/[H615]', 'lemma', 'heb', 'אָסִיר', '["ʼâçîyr"]', '["bound, i.e. a captive (those which are) bound, prisoner."]', '["n-m"]', 'bound, i.e. a captive (those which are) bound, prisoner.', 'from 631;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H616}/[H616]', 'lemma', 'heb', 'אַסִּיר', '["ʼaççîyr"]', '["prisoner."]', '["n-m"]', 'prisoner.', 'for 615');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H617}/[H617]', 'lemma', 'heb', 'אַסִּיר', '["ʼAççîyr"]', '["Assir, the name of two Israelites Assir."]', '["n-pr-m"]', 'Assir, the name of two Israelites Assir.', 'the same as 616; prisoner;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H618>', 'opaque', 'heb', 'אָסָם', '["ʼâçâm"]', '["a storehouse (only in the plural) barn, storehouse."]', '["n-m"]', 'a storehouse (only in the plural) barn, storehouse.', 'from an unused root meaning to heap together;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H619>', 'opaque', 'heb', 'אַסְנָה', '["ʼAçnâh"]', '["Asnah, one of the Nethinim Asnah."]', '["n-pr-m"]', 'Asnah, one of the Nethinim Asnah.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H620}/[H620]', 'lemma', 'heb', 'אׇסְנַפַּר', '["ʼOçnappar"]', '["Osnappar, an Assyrian king Asnapper."]', '["n-pr-m"]', 'Osnappar, an Assyrian king Asnapper.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H621}/[H621]', 'lemma', 'heb', 'אָסְנַת', '["ʼÂçᵉnath"]', '["Asenath, the wife of Joseph Asenath."]', '["n-pr-f"]', 'Asenath, the wife of Joseph Asenath.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H622]', 'root', 'heb', 'אָסַף', '["ʼâçaph"]', '["to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw."]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H623}/[H623]', 'lemma', 'heb', 'אָסָף', '["ʼÂçâph"]', '["Asaph, the name of three Israelites, and of the family of the first Asaph."]', '["n-pr-m"]', 'Asaph, the name of three Israelites, and of the family of the first Asaph.', 'from 622; collector;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H624}/[H624]', 'lemma', 'heb', 'אָסֻף', '["ʼâçuph"]', '["collected (only in the plural), i.e. a collection of offerings threshold, Asuppim."]', '["n-m"]', 'collected (only in the plural), i.e. a collection of offerings threshold, Asuppim.', 'passive participle of 622;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H625}/[H625]', 'lemma', 'heb', 'אֹסֶף', '["ʼôçeph"]', '["a collection (of fruits) gathering."]', '["n-m"]', 'a collection (of fruits) gathering.', 'from 622;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H626}/[H626]', 'lemma', 'heb', 'אֲסֵפָה', '["ʼăçêphâh"]', '["a collection of people (only adverbial) × together."]', '["n-f"]', 'a collection of people (only adverbial) × together.', 'from 622;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H627}/[H627]', 'lemma', 'heb', 'אֲסֻפָּה', '["ʼăçuppâh"]', '["a collection of (learned) men (only in the plural) assembly."]', '["n-f"]', 'a collection of (learned) men (only in the plural) assembly.', 'feminine of 624;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H628}/[H628]', 'lemma', 'heb', 'אֲסְפְּסֻף', '["ʼăçpᵉçuph"]', '["gathered up together, i.e. a promiscuous assemblage (of people) mixt multitude."]', '["n-m"]', 'gathered up together, i.e. a promiscuous assemblage (of people) mixt multitude.', 'by reduplication from 624;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H629}/[H629]', 'lemma', 'arc', 'אׇסְפַּרְנָא', '["ʼoçparnâʼ"]', '["diligently fast, forthwith, speed(-ily)."]', '["adv"]', 'diligently fast, forthwith, speed(-ily).', '(Aramaic) of Persian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H630}/[H630]', 'lemma', 'heb', 'אַסְפָּתָא', '["ʼAçpâthâʼ"]', '["Aspatha, a son of Haman Aspatha."]', '["n-pr-m"]', 'Aspatha, a son of Haman Aspatha.', 'of Persian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H631]', 'root', 'heb', 'אָסַר', '["ʼâçar"]', '["to yoke or hitch; by analogy, to fasten in any sense, to join battle bind, fast, gird, harness, hold, keep, make ready, order, prepare, prison(-er), put in bonds, set in array, tie."]', '["v"]', 'to yoke or hitch; by analogy, to fasten in any sense, to join battle bind, fast, gird, harness, hold, keep, make ready, order, prepare, prison(-er), put in bonds, set in array, tie.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H632}/[H632]', 'lemma', 'heb', 'אֱסָר', '["ʼĕçâr"]', '["an obligation or vow (of abstinence) binding, bond."]', '["n-m"]', 'an obligation or vow (of abstinence) binding, bond.', 'or אִסָּר; from 631;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H633}/[H633]', 'lemma', 'arc', 'אֱסָר', '["ʼĕçâr"]', '["an interdict decree."]', '["n-m"]', 'an interdict decree.', '(Aramaic) corresponding to 632 in a legal sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H634}/[H634]', 'lemma', 'heb', 'אֵסַר־חַדּוֹן', '["ʼÊçar-Chaddôwn"]', '["Esarchaddon, an Assyrian king Esar-haddon."]', '["n-pr-m"]', 'Esarchaddon, an Assyrian king Esar-haddon.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H635}/[H635]', 'lemma', 'heb', 'אֶסְתֵּר', '["ʼEçtêr"]', '["Ester, the Jewish heroine Esther."]', '["n-pr-f"]', 'Ester, the Jewish heroine Esther.', 'of Persian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H636}/[H636]', 'lemma', 'arc', 'אָע', '["ʼâʻ"]', '["a tree or wood timber, wood."]', '["n-m"]', 'a tree or wood timber, wood.', '(Aramaic) corresponding to 6086;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H637}/[H637]', 'lemma', 'heb', 'אַף', '["ʼaph"]', '["meaning accession (used as an adverb or conjunction); also or yea; adversatively though also, + although, and (furthermore, yet), but, even, + how much less (more, rather than), moreover, with, yea."]', '["prt"]', 'meaning accession (used as an adverb or conjunction); also or yea; adversatively though also, + although, and (furthermore, yet), but, even, + how much less (more, rather than), moreover, with, yea.', 'a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H638}/[H638]', 'lemma', 'arc', 'אַף', '["ʼaph"]', '["also."]', '["conj"]', 'also.', '(Aramaic) corresponding to 637');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H639}/[H639]', 'lemma', 'heb', 'אַף', '["ʼaph"]', '["properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath."]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H640]', 'root', 'heb', 'אָפַד', '["ʼâphad"]', '["to gird on (the ephod) bind, gird."]', '["v"]', 'to gird on (the ephod) bind, gird.', 'a primitive root [rather a denominative from 646];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H641}/[H641]', 'lemma', 'heb', 'אֵפֹד', '["ʼÊphôd"]', '["Ephod, an Israelite Ephod."]', '["n-pr-m"]', 'Ephod, an Israelite Ephod.', 'the same as 646 shortened;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H642}/[H642]', 'lemma', 'heb', 'אֵפֻדָּה', '["ʼêphuddâh"]', '["a girding on (of the ephod); hence, generally, a plating (of metal) ephod, ornament."]', '["n-f"]', 'a girding on (of the ephod); hence, generally, a plating (of metal) ephod, ornament.', 'feminine of 646;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H643}/[H643]', 'lemma', 'heb', 'אַפֶּדֶן', '["ʼappeden"]', '["a pavilion or palace-tent palace."]', '["n"]', 'a pavilion or palace-tent palace.', 'apparently of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H644]', 'root', 'heb', 'אָפָה', '["ʼâphâh"]', '["to cook, especially to bake bake(-r, (-meats))."]', '["v"]', 'to cook, especially to bake bake(-r, (-meats)).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H645}/[H645]', 'lemma', 'heb', 'אֵפוֹ', '["ʼêphôw"]', '["strictly a demonstrative particle, here; but used of time, now or then here, now, where?"]', '["prt"]', 'strictly a demonstrative particle, here; but used of time, now or then here, now, where?', 'or אֵפוֹא; from 6311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H646}/[H646]', 'lemma', 'heb', 'אֵפוֹד', '["ʼêphôwd"]', '["a girdle; specifically the ephod or highpriest''s shoulder-piece; also generally, an image ephod."]', '["n-m"]', 'a girdle; specifically the ephod or highpriest''s shoulder-piece; also generally, an image ephod.', 'rarely אֵפֹד; probably of foreign derivation');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H647}/[H647]', 'lemma', 'heb', 'אֲפִיחַ', '["ʼĂphîyach"]', '["Aphiach, an Israelite Aphiah."]', '["n-pr-m"]', 'Aphiach, an Israelite Aphiah.', 'perhaps from 6315; breeze;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H648}/[H648]', 'lemma', 'heb', 'אָפִיל', '["ʼâphîyl"]', '["unripe not grown up."]', '["a"]', 'unripe not grown up.', 'from the same as 651 (in the sense of weakness);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H649}/[H649]', 'lemma', 'heb', 'אַפַּיִם', '["ʼAppayim"]', '["Appajim, an Israelite Appaim."]', '["n-pr-m"]', 'Appajim, an Israelite Appaim.', 'dual of 639; two nostrils;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H650}/[H650]', 'lemma', 'heb', 'אָפִיק', '["ʼâphîyq"]', '["properly, containing, i.e. a tube; also a bed or valley of a stream; also a strong thing or a hero brook, channel, mighty, river, scale, stream, strong piece."]', '["n-m"]', 'properly, containing, i.e. a tube; also a bed or valley of a stream; also a strong thing or a hero brook, channel, mighty, river, scale, stream, strong piece.', 'from 622;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H651>', 'opaque', 'heb', 'אָפֵל', '["ʼâphêl"]', '["dusky very dark."]', '["a"]', 'dusky very dark.', 'from an unused root meaning to set as the sun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H652}/[H652]', 'lemma', 'heb', 'אֹפֶל', '["ʼôphel"]', '["dusk darkness, obscurity, privily."]', '["n-m"]', 'dusk darkness, obscurity, privily.', 'from the same as 651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H653}/[H653]', 'lemma', 'heb', 'אֲפֵלָה', '["ʼăphêlâh"]', '["duskiness, figuratively, misfortune; concrete, concealment dark, darkness, gloominess, × thick."]', '["n-f"]', 'duskiness, figuratively, misfortune; concrete, concealment dark, darkness, gloominess, × thick.', 'feminine of 651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H654}/[H654]', 'lemma', 'heb', 'אֶפְלָל', '["ʼEphlâl"]', '["Ephlal, an Israelite Ephlal."]', '["n-pr-m"]', 'Ephlal, an Israelite Ephlal.', 'from 6419; judge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H655>', 'opaque', 'heb', 'אֹפֶן', '["ʼôphen"]', '["a turn, i.e. a season fitly."]', '["n-m"]', 'a turn, i.e. a season fitly.', 'from an unused root meaning to revolve;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H656]', 'root', 'heb', 'אָפֵס', '["ʼâphêç"]', '["to disappear, i.e. cease be clean gone (at an end, brought to nought), fail."]', '["v"]', 'to disappear, i.e. cease be clean gone (at an end, brought to nought), fail.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H657}/[H657]', 'lemma', 'heb', 'אֶפֶס', '["ʼepheç"]', '["cessation, i.e. an end (especially of the earth); often used adverb, no further; also the ankle (in the dual), as being the extremity of the leg or foot ankle, but (only), end, howbeit, less than nothing, nevertheless (where), no, none (beside), not (any, -withstanding), thing of nought, save(-ing), there, uttermost part, want, without (cause)."]', '["n-m"]', 'cessation, i.e. an end (especially of the earth); often used adverb, no further; also the ankle (in the dual), as being the extremity of the leg or foot ankle, but (only), end, howbeit, less than nothing, nevertheless (where), no, none (beside), not (any, -withstanding), thing of nought, save(-ing), there, uttermost part, want, without (cause).', 'from 656; (sometimes like 6466)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H658}/[H658]', 'lemma', 'heb', 'אֶפֶס דַּמִּים', '["ʼEpheç Dammîym"]', '["Ephes-Dammim, a place in Palestine Ephes-dammim."]', '["n-pr-loc"]', 'Ephes-Dammim, a place in Palestine Ephes-dammim.', 'from 657 and the plural of 1818; boundary of blood-drops;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H659>', 'opaque', 'heb', 'אֵפַע', '["ʼêphaʻ"]', '["properly, a breath, i.e. nothing of nought."]', '["a"]', 'properly, a breath, i.e. nothing of nought.', 'from an unused root probably meaning to breathe;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H660}/[H660]', 'lemma', 'heb', 'אֶפְעֶה', '["ʼephʻeh"]', '["an asp or other venomous serpent viper."]', '["n-m"]', 'an asp or other venomous serpent viper.', 'from 659 (in the sense of hissing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H661]', 'root', 'heb', 'אָפַף', '["ʼâphaph"]', '["to surround compass."]', '["v"]', 'to surround compass.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H662]', 'root', 'heb', 'אָפַק', '["ʼâphaq"]', '["to contain, i.e. (reflex.) abstain force (oneself), restrain."]', '["v"]', 'to contain, i.e. (reflex.) abstain force (oneself), restrain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H663}/[H663]', 'lemma', 'heb', 'אֲפֵק', '["ʼĂphêq"]', '["Aphek (or Aphik), the name of three places in Palestine Aphek, Aphik."]', '["n-pr-loc"]', 'Aphek (or Aphik), the name of three places in Palestine Aphek, Aphik.', 'or אֲפִיק; from 662 (in the sense of strength); fortress;');
