INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H774}/[H774]', 'lemma', 'heb', 'אַרְפָּד', '["ʼArpâd"]', '["Arpad, a place in Syria Arpad, Arphad."]', '["n-pr-loc"]', 'Arpad, a place in Syria Arpad, Arphad.', 'from 7502; spread out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H775>', 'opaque', 'heb', 'אַרְפַּכְשַׁד', '["ʼArpakshad"]', '["Arpakshad, a son of Noah; also the region settled by him Arphaxad."]', '["n-pr-m"]', 'Arpakshad, a son of Noah; also the region settled by him Arphaxad.', 'probably of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H776>', 'opaque', 'heb', 'אֶרֶץ', '["ʼerets"]', '["the earth (at large, or partitively a land) × common, country, earth, field, ground, land, × natins, way, + wilderness, world."]', '["n-f"]', 'the earth (at large, or partitively a land) × common, country, earth, field, ground, land, × natins, way, + wilderness, world.', 'from an unused root probably meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H777}/[H777]', 'lemma', 'heb', 'אַרְצָא', '["ʼartsâʼ"]', '["Artsa, an Israelite Arza."]', '["n-pr-m"]', 'Artsa, an Israelite Arza.', 'from 776; earthiness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H778}/[H778]', 'lemma', 'arc', 'אֲרַק', '["ʼăraq"]', '["the earth earth."]', '["n-f"]', 'the earth earth.', '(Aramaic) by transmutation for 772;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H779]', 'root', 'heb', 'אָרַר', '["ʼârar"]', '["to execrate × bitterly curse."]', '["v"]', 'to execrate × bitterly curse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H780>', 'opaque', 'heb', 'אֲרָרַט', '["ʼĂrâraṭ"]', '["Ararat (or rather Armenia) Ararat, Armenia."]', '["n-pr-loc"]', 'Ararat (or rather Armenia) Ararat, Armenia.', 'of foreign origin;');
