INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H782}/[H782]', 'lemma', 'heb', 'אֲרֶשֶׁת', '["ʼăresheth"]', '["a longing for request."]', '["n-f"]', 'a longing for request.', 'from 781 (in the sense of desiring to possess);');
