INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H784]', 'root', 'heb', 'אֵשׁ', '["ʼêsh"]', '["fire (literally or figuratively) burning, fiery, fire, flaming, hot."]', '["n-f"]', 'fire (literally or figuratively) burning, fiery, fire, flaming, hot.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H785}/[H785]', 'lemma', 'arc', 'אֵשׁ', '["ʼêsh"]', '["flame."]', '["n-f"]', 'flame.', '(Aramaic) corresponding to 784');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H786}/[H786]', 'lemma', 'heb', 'אִשׁ', '["ʼish"]', '["entity, used only adverbially, there is or are are there, none can. Compare 3426."]', '["adv"]', 'entity, used only adverbially, there is or are are there, none can. Compare 3426.', 'identical (in origin and formation) with 784;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H787}/[H787]', 'lemma', 'arc', 'אֹשׁ', '["ʼôsh"]', '["a foundation foundation."]', '["n-m"]', 'a foundation foundation.', '(Aramaic) corresponding (by transposition and abbreviation) to 803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H788}/[H788]', 'lemma', 'heb', 'אַשְׁבֵּל', '["ʼAshbêl"]', '["Ashbel, an Israelite Ashbel."]', '["n-pr-m"]', 'Ashbel, an Israelite Ashbel.', 'probably from the same as 7640; flowing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H789}/[H789]', 'lemma', 'heb', 'אַשְׁבֵּלִי', '["ʼAshbêlîy"]', '["an Ashbelite (collectively) or descendant of Ashbel Ashbelites."]', '["a"]', 'an Ashbelite (collectively) or descendant of Ashbel Ashbelites.', 'patronymic from 788;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H790}/[H790]', 'lemma', 'heb', 'אֶשְׁבָּן', '["ʼEshbân"]', '["Eshban, an Idumaean Eshban."]', '["n-pr-m"]', 'Eshban, an Idumaean Eshban.', 'probably from the same as 7644; vigorous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H791}/[H791]', 'lemma', 'heb', 'אַשְׁבֵּעַ', '["ʼAshbêaʻ"]', '["Asbea, an Israelite Ashbea."]', '["n-pr-m"]', 'Asbea, an Israelite Ashbea.', 'from 7650; adjurer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H792}/[H792]', 'lemma', 'heb', 'אֶשְׁבַּעַל', '["ʼEshbaʻal"]', '["Eshbaal (or Ishbosheth), a son of Saul Eshbaal."]', '["n-pr-m"]', 'Eshbaal (or Ishbosheth), a son of Saul Eshbaal.', 'from 376 and 1168; man of Baal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H793>', 'opaque', 'heb', 'אֶשֶׁד', '["ʼeshed"]', '["an outpouring stream."]', '["n-m"]', 'an outpouring stream.', 'from an unused root meaning to pour;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H794}/[H794]', 'lemma', 'heb', 'אֲשֵׁדָה', '["ʼăshêdâh"]', '["a ravine springs."]', '["n-f"]', 'a ravine springs.', 'feminine of 793;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H795}/[H795]', 'lemma', 'heb', 'אַשְׁדּוֹד', '["ʼAshdôwd"]', '["Ashdod, a place in Palestine Ahdod."]', '["n-pr-loc"]', 'Ashdod, a place in Palestine Ahdod.', 'from 7703; ravager;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H796}/[H796]', 'lemma', 'heb', 'אַשְׁדּוֹדִי', '["ʼAshdôwdîy"]', '["an Ashdodite (often collectively) or inhabitant of Asdod Ashdodites, of Ashdod."]', '["a"]', 'an Ashdodite (often collectively) or inhabitant of Asdod Ashdodites, of Ashdod.', 'patrial from 795;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H797}/[H797]', 'lemma', 'heb', 'אַשְׁדּוֹדִית', '["ʼAshdôwdîyth"]', '["(only adverb) in the language of Ashdod in the speech of Ashdod."]', '["adv"]', '(only adverb) in the language of Ashdod in the speech of Ashdod.', 'feminine of 796;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H798}/[H798]', 'lemma', 'heb', 'אַשְׁדּוֹת הַפִּסְגָּה', '["ʼAshdôwth hap-Piçgâh"]', '["Ashdoth-Pisgah, a place east of the Jordan Ashdoth-pisgah."]', '["n-pr-loc"]', 'Ashdoth-Pisgah, a place east of the Jordan Ashdoth-pisgah.', 'from the plural of 794 and 6449 with the article interposed; ravines of the Pisgah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H799}/[H799]', 'lemma', 'heb', 'אֶשְׁדָּת', '["ʼeshdâth"]', '["a fire-law fiery law."]', '["n-f"]', 'a fire-law fiery law.', 'from 784 and 1881;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H800}/[H800]', 'lemma', 'heb', 'אֶשָּׁה', '["ʼeshshâh"]', '["fire fire."]', '["n-f"]', 'fire fire.', 'feminine of 784;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H801}/[H801]', 'lemma', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["properly, a burnt-offering; but occasionally of any sacrifice (offering, sacrifice), (made) by fire."]', '["n-m"]', 'properly, a burnt-offering; but occasionally of any sacrifice (offering, sacrifice), (made) by fire.', 'the same as 800, but used in a liturgical sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H802}/[H802]', 'lemma', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English."]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H803>', 'opaque', 'heb', 'אֲשׁוּיָה', '["ʼăshûwyâh"]', '["foundation foundation."]', '["n-f"]', 'foundation foundation.', 'feminine passive participle from an unused root meaning to found;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H804}/[H804]', 'lemma', 'heb', 'אַשּׁוּר', '["ʼAshshûwr"]', '["Ashshur, the second son of Shem; also his descendants and the country occupied by them (i.e. Assyria), its region and its empire Asshur, Assur, Assyria, Assyrians. See 838."]', '["n-pr-m n-pr-loc"]', 'Ashshur, the second son of Shem; also his descendants and the country occupied by them (i.e. Assyria), its region and its empire Asshur, Assur, Assyria, Assyrians. See 838.', 'or אַשֻּׁר; apparently from 833 (in the sense of successful);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H805}/[H805]', 'lemma', 'heb', 'אֲשׁוּרִי', '["ʼĂshûwrîy"]', '["an Ashurite (collectively) or inhabitant of Ashur, a district in Palestine Asshurim, Ashurites."]', '["n-pr-m a"]', 'an Ashurite (collectively) or inhabitant of Ashur, a district in Palestine Asshurim, Ashurites.', 'or אַשּׁוּרִי; from a patrial word of the same form as 804;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H806}/[H806]', 'lemma', 'heb', 'אַשְׁחוּר', '["ʼAshchûwr"]', '["Ashchur, an Israelite Ashur."]', '["n-pr-m"]', 'Ashchur, an Israelite Ashur.', 'probably from 7835; black;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H807>', 'opaque', 'heb', 'אַשִׁימָא', '["ʼAshîymâʼ"]', '["Ashima, a deity of Hamath Ashima."]', '["n-pr-m"]', 'Ashima, a deity of Hamath Ashima.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H808}/[H808]', 'lemma', 'heb', 'אָשִׁישׁ', '["ʼâshîysh"]', '["a (ruined) foundation foundation."]', '["n-f"]', 'a (ruined) foundation foundation.', 'from the same as 784 (in the sense of pressing down firmly; compare 803);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H809}/[H809]', 'lemma', 'heb', 'אֲשִׁישָׁה', '["ʼăshîyshâh"]', '["something closely pressed together, i.e. a cake of raisins or other comfits flagon."]', '["n-f"]', 'something closely pressed together, i.e. a cake of raisins or other comfits flagon.', 'feminine of 808;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H810>', 'opaque', 'heb', 'אֶשֶׁךְ', '["ʼeshek"]', '["a testicle (as a lump) stone."]', '["n-m"]', 'a testicle (as a lump) stone.', 'from an unused root (probably meaning to bunch together);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H811}/[H811]', 'lemma', 'heb', 'אֶשְׁכּוֹל', '["ʼeshkôwl"]', '["a bunch of grapes or other fruit cluster (of grapes)."]', '["n-m"]', 'a bunch of grapes or other fruit cluster (of grapes).', 'or אֶשְׁכֹּל; probably prolonged from 810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H812}/[H812]', 'lemma', 'heb', 'אֶשְׁכֹּל', '["ʼEshkôl"]', '["Eshcol, the name of an Amorite, also of a valley in Palestine Eshcol."]', '["n-pr"]', 'Eshcol, the name of an Amorite, also of a valley in Palestine Eshcol.', 'the same as 811;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H813>', 'opaque', 'heb', 'אַשְׁכְּנַז', '["ʼAshkᵉnaz"]', '["Ashkenaz, a Japhethite, also his descendants Ashkenaz."]', '["n-pr-m"]', 'Ashkenaz, a Japhethite, also his descendants Ashkenaz.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H814}/[H814]', 'lemma', 'heb', 'אֶשְׁכָּר', '["ʼeshkâr"]', '["a gratuity gift, present."]', '["n-m"]', 'a gratuity gift, present.', 'for 7939;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H815}/[H815]', 'lemma', 'heb', 'אֵשֶׁל', '["ʼêshel"]', '["a tamarisk tree; by extension, a grove of any kind grove, tree."]', '["n-m"]', 'a tamarisk tree; by extension, a grove of any kind grove, tree.', 'from a root of uncertain signification;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H816]', 'root', 'heb', 'אָשַׁם', '["ʼâsham"]', '["to be guilty; by implication to be punished or perish × certainly, be(-come, made) desolate, destroy, × greatly, be(-come, found, hold) guilty, offend (acknowledge offence), trespass."]', '["v"]', 'to be guilty; by implication to be punished or perish × certainly, be(-come, made) desolate, destroy, × greatly, be(-come, found, hold) guilty, offend (acknowledge offence), trespass.', 'or אָשֵׁם; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H817}/[H817]', 'lemma', 'heb', 'אָשָׁם', '["ʼâshâm"]', '["guilt; by implication, a fault; also a sin-offering guiltiness, (offering for) sin, trespass (offering)."]', '["n-m"]', 'guilt; by implication, a fault; also a sin-offering guiltiness, (offering for) sin, trespass (offering).', 'from 816;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H818}/[H818]', 'lemma', 'heb', 'אָשֵׁם', '["ʼâshêm"]', '["guilty; hence, presenting a sin-offering one which is faulty, guilty."]', '["a"]', 'guilty; hence, presenting a sin-offering one which is faulty, guilty.', 'from 816;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H819}/[H819]', 'lemma', 'heb', 'אַשְׁמָה', '["ʼashmâh"]', '["guiltiness, a fault, the presentation of a sin-offering offend, sin, (cause of) trespass(-ing, offering)."]', '["n-f"]', 'guiltiness, a fault, the presentation of a sin-offering offend, sin, (cause of) trespass(-ing, offering).', 'feminine of 817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H820}/[H820]', 'lemma', 'heb', 'אַשְׁמָן', '["ʼashmân"]', '["a fat field desolate place."]', '["n-m"]', 'a fat field desolate place.', 'probably from 8081;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H821}/[H821]', 'lemma', 'heb', 'אַשְׁמֻרָה', '["ʼashmurâh"]', '["a night watch watch."]', '["n-f"]', 'a night watch watch.', 'or אַשׁמוּרָה; or אַשׁמֹרֶת; (feminine) from 8104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H822>', 'opaque', 'heb', 'אֶשְׁנָב', '["ʼeshnâb"]', '["a latticed window casement, lattice."]', '["n-m"]', 'a latticed window casement, lattice.', 'apparently from an unused root (probably meaning to leave interstices);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H823}/[H823]', 'lemma', 'heb', 'אַשְׁנָה', '["ʼAshnâh"]', '["Ashnah, the name of two places in Palestine Ashnah."]', '["n-pr-loc"]', 'Ashnah, the name of two places in Palestine Ashnah.', 'probably a variation for 3466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H824}/[H824]', 'lemma', 'heb', 'אֶשְׁעָן', '["ʼEshʻân"]', '["Eshan, a place in Palestine Eshean."]', '["n-pr-loc"]', 'Eshan, a place in Palestine Eshean.', 'from 8172; support;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H825>', 'opaque', 'heb', 'אַשָּׁף', '["ʼashshâph"]', '["a conjurer astrologer."]', '["n-m"]', 'a conjurer astrologer.', 'from an unused root (probably meaning to lisp, i.e. practice enchantment);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H826}/[H826]', 'lemma', 'arc', 'אַשָּׁף', '["ʼashshâph"]', '["astrologer."]', '["n-m"]', 'astrologer.', '(Aramaic) corresponding to 825');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H827}/[H827]', 'lemma', 'heb', 'אַשְׁפָּה', '["ʼashpâh"]', '["a quiver or arrow-case quiver."]', '["n-f"]', 'a quiver or arrow-case quiver.', 'perhaps (feminine) from the same as 825 (in the sense of covering);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H828>', 'opaque', 'heb', 'אַשְׁפְּנַז', '["ʼAshpᵉnaz"]', '["Ashpenaz, a Babylonian eunuch Ashpenaz."]', '["n-pr-m"]', 'Ashpenaz, a Babylonian eunuch Ashpenaz.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H829>', 'opaque', 'heb', 'אֶשְׁפָּר', '["ʼeshpâr"]', '["a measured portion good piece (of flesh)."]', '["n-m"]', 'a measured portion good piece (of flesh).', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H830}/[H830]', 'lemma', 'heb', 'אַשְׁפֹּת', '["ʼashpôth"]', '["a heap of rubbish or filth dung (hill)."]', '["n-m"]', 'a heap of rubbish or filth dung (hill).', 'or אַשְׁפּוֹת; or שְׁפֹת; (contraction) plural of a noun of the same form as 827, from 8192 (in the sense of scraping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H831}/[H831]', 'lemma', 'heb', 'אַשְׁקְלוֹן', '["ʼAshqᵉlôwn"]', '["Ashkelon, a place in Palestine Ashkelon, Askalon."]', '["n-pr-loc"]', 'Ashkelon, a place in Palestine Ashkelon, Askalon.', 'probably from 8254 in the sense of weighing-place (i.e. mart);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H832}/[H832]', 'lemma', 'heb', 'אֶשְׁקְלוֹנִי', '["ʼEshqᵉlôwnîy"]', '["Ashkelonite (collectively) or inhabitant of Ashkelon Eshkalonites."]', '["a"]', 'Ashkelonite (collectively) or inhabitant of Ashkelon Eshkalonites.', 'patrial from 831;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H833]', 'root', 'heb', 'אָשַׁר', '["ʼâshar"]', '["to be straight (used in the widest sense, especially to be level, right, happy); figuratively, to go forward, be honest, prosper (call, be) bless(-ed, happy), go, guide, lead, relieve."]', '["v"]', 'to be straight (used in the widest sense, especially to be level, right, happy); figuratively, to go forward, be honest, prosper (call, be) bless(-ed, happy), go, guide, lead, relieve.', 'or אָשֵׁר; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H834}/[H834]', 'lemma', 'heb', 'אֲשֶׁר', '["ʼăsher"]', '["who, which, what, that; also (as an adverb and a conjunction) when, where, how, because, in order that, etc. × after, × alike, as (soon as), because, × every, for, + forasmuch, + from whence, + how(-soever), × if, (so) that ((thing) which, wherein), × though, + until, + whatsoever, when, where (+ -as, -in, -of, -on, -soever, -with), which, whilst, + whither(-soever), who(-m, -soever, -se). As it is indeclinable, it is often accompanied by the personal pronoun expletively, used to show the connection."]', '["r"]', 'who, which, what, that; also (as an adverb and a conjunction) when, where, how, because, in order that, etc. × after, × alike, as (soon as), because, × every, for, + forasmuch, + from whence, + how(-soever), × if, (so) that ((thing) which, wherein), × though, + until, + whatsoever, when, where (+ -as, -in, -of, -on, -soever, -with), which, whilst, + whither(-soever), who(-m, -soever, -se). As it is indeclinable, it is often accompanied by the personal pronoun expletively, used to show the connection.', 'a primitive relative pronoun (of every gender and number);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H835}/[H835]', 'lemma', 'heb', 'אֶשֶׁר', '["ʼesher"]', '["happiness; only in masculine plural construction as interjection, how happy! blessed, happy."]', '["n-m"]', 'happiness; only in masculine plural construction as interjection, how happy! blessed, happy.', 'from 833;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H836}/[H836]', 'lemma', 'heb', 'אָשֵׁר', '["ʼÂshêr"]', '["Asher, a son of Jacob, and the tribe descended from him, with its territory; also a place in Palestine Asher"]', '["n-pr"]', 'Asher, a son of Jacob, and the tribe descended from him, with its territory; also a place in Palestine Asher', 'from 833, happy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H837}/[H837]', 'lemma', 'heb', 'אֹשֶׁר', '["ʼôsher"]', '["happiness happy."]', '["n-m"]', 'happiness happy.', 'from 833;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H838}/[H838]', 'lemma', 'heb', 'אָשֻׁר', '["ʼâshur"]', '["a step going, step."]', '["n-f"]', 'a step going, step.', 'or אַשֻּׁר; from 833 in the sense of going;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H839}/[H839]', 'lemma', 'heb', 'אֲשֻׁר', '["ʼăshur"]', '["the cedar tree or some other light elastic wood Ashurite."]', '["n-f"]', 'the cedar tree or some other light elastic wood Ashurite.', 'contracted for 8391;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H840}/[H840]', 'lemma', 'heb', 'אֲשַׂרְאֵל', '["ʼĂsarʼêl"]', '["Asarel, an Israelite Asareel."]', '["n-pr-m"]', 'Asarel, an Israelite Asareel.', 'by orthographical variation from 833 and 410; right of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H841}/[H841]', 'lemma', 'heb', 'אֲשַׂרְאֵלָה', '["ʼĂsarʼêlâh"]', '["Asarelah, an Israelite Asarelah. Compare 3480."]', '["n-pr-m"]', 'Asarelah, an Israelite Asarelah. Compare 3480.', 'from the same as 840; right toward God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H842}/[H842]', 'lemma', 'heb', 'אֲשֵׁרָה', '["ʼăshêrâh"]', '["Asherah (or Astarte) a Phoenician goddess; also an image of the same grove. Compare 6253."]', '["n-pr-f"]', 'Asherah (or Astarte) a Phoenician goddess; also an image of the same grove. Compare 6253.', 'or אֲשֵׁירָה; from 833; happy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H843}/[H843]', 'lemma', 'heb', 'אָשֵׁרִי', '["ʼÂshêrîy"]', '["an Asherite (collectively) or descendant of Asher Asherites."]', '["a"]', 'an Asherite (collectively) or descendant of Asher Asherites.', 'patronymic from 836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H844}/[H844]', 'lemma', 'heb', 'אַשְׂרִיאֵל', '["ʼAsrîyʼêl"]', '["Asriel, the name of two Israelites Ashriel, Asriel."]', '["n-pr-m"]', 'Asriel, the name of two Israelites Ashriel, Asriel.', 'an orthographical variation for 840;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H845}/[H845]', 'lemma', 'heb', 'אַשְׂרִאֵלִי', '["ʼAsriʼêlîy"]', '["an Asrielite (collectively) or descendant of Asriel Asrielites."]', '["a"]', 'an Asrielite (collectively) or descendant of Asriel Asrielites.', 'patronymic from 844;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H846}/[H846]', 'lemma', 'arc', 'אֻשַּׁרְנָא', '["ʼushsharnâʼ"]', '["a wall (from its uprightness) wall."]', '["n-m"]', 'a wall (from its uprightness) wall.', '(Aramaic) from a root corresponding to 833;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H847}/[H847]', 'lemma', 'heb', 'אֶשְׁתָּאֹל', '["ʼEshtâʼôl"]', '["Eshtaol, a place in Palestine Eshtaol."]', '["n-pr-loc"]', 'Eshtaol, a place in Palestine Eshtaol.', 'or אֶשְׁתָּאוֹל; probably from 7592; intreaty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H848}/[H848]', 'lemma', 'heb', 'אֶשְׁתָּאֻלִי', '["ʼEshtâʼulîy"]', '["an Eshtaolite (collectively) or inhabitant of Eshtaol Eshtaulites."]', '["a"]', 'an Eshtaolite (collectively) or inhabitant of Eshtaol Eshtaulites.', 'patrial from 847;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H849}/[H849]', 'lemma', 'arc', 'אֶשְׁתַּדּוּר', '["ʼeshtaddûwr"]', '["rebellion sedition."]', '["n-m"]', 'rebellion sedition.', '(Aramaic) from 7712 (in a bad sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H850}/[H850]', 'lemma', 'heb', 'אֶשְׁתּוֹן', '["ʼEshtôwn"]', '["Eshton, an Israelite Eshton."]', '["n-pr-m"]', 'Eshton, an Israelite Eshton.', 'probably from the same as 7764; restful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H851}/[H851]', 'lemma', 'heb', 'אֶשְׁתְּמֹעַ', '["ʼEshtᵉmôaʻ"]', '["Eshtemoa or Eshtemoh, a place in Palestine Eshtemoa, Eshtemoh."]', '["n-pr"]', 'Eshtemoa or Eshtemoh, a place in Palestine Eshtemoa, Eshtemoh.', 'or אֶשְׁתְּמוֹעַ; or אֶשְׁתְּמֹה; from 8085 (in the sense of obedience);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H852}/[H852]', 'lemma', 'arc', 'אָת', '["ʼâth"]', '["a portent sign."]', '["n-f"]', 'a portent sign.', '(Aramaic) corresponding to 226;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H853}/[H853]', 'lemma', 'heb', 'אֵת', '["ʼêth"]', '["properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English]."]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H854}/[H854]', 'lemma', 'heb', 'אֵת', '["ʼêth"]', '["properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix."]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H855>', 'opaque', 'heb', 'אֵת', '["ʼêth"]', '["a hoe or other digging implement coulter, plowshare."]', '["n-m"]', 'a hoe or other digging implement coulter, plowshare.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H856}/[H856]', 'lemma', 'heb', 'אֶתְבַּעַל', '["ʼEthbaʻal"]', '["Ethbaal, a Phoenician king Ethbaal."]', '["n-pr-m"]', 'Ethbaal, a Phoenician king Ethbaal.', 'from 854 and 1168; with Baal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H857]', 'root', 'heb', 'אָתָה', '["ʼâthâh"]', '["to arrive (be-, things to) come (upon), bring."]', '["v"]', 'to arrive (be-, things to) come (upon), bring.', 'or אָתָא; a primitive root (collateral to 225 contraction);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H858}/[H858]', 'lemma', 'arc', 'אָתָה', '["ʼâthâh"]', '["(be-) come, bring."]', '["v"]', '(be-) come, bring.', '(Aramaic) or אָתָא; (Aramaic), corresponding to 857');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H859}/[H859]', 'lemma', 'heb', 'אַתָּה', '["ʼattâh"]', '["thou and thee, or (plural) ye and you thee, thou, ye, you."]', '["p"]', 'thou and thee, or (plural) ye and you thee, thou, ye, you.', 'or (shortened); אַתָּ; or אַת; feminine (irregular) sometimes אַתִּי; plural masculine אַתֶּם; feminine אַתֶּן; or אַתֵּנָהlemma אתֵּנָה missing vowel, corrected to אַתֵּנָה; or אַתֵּנָּה; a primitive pronoun of the second person;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H860}/[H860]', 'lemma', 'heb', 'אָתוֹן', '["ʼâthôwn"]', '["a female donkey (from its docility) (she) ass."]', '["n-f"]', 'a female donkey (from its docility) (she) ass.', 'probably from the same as 386 (in the sense of patience);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H861}/[H861]', 'lemma', 'arc', 'אַתּוּן', '["ʼattûwn"]', '["probably a fire-place, i.e. furnace furnace."]', '["n-m"]', 'probably a fire-place, i.e. furnace furnace.', '(Aramaic) probably from the corresponding to 784;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H862}/[H862]', 'lemma', 'heb', 'אַתּוּק', '["ʼattûwq"]', '["a ledge or offset in a building gallery."]', '["n-m"]', 'a ledge or offset in a building gallery.', 'or אַתִּיק; from 5423 in the sense of decreasing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H863}/[H863]', 'lemma', 'heb', 'אִתַּי', '["ʼIttay"]', '["Ittai or Ithai, the name of a Gittite and of an Israelite Ithai, Ittai."]', '["n-pr-m"]', 'Ittai or Ithai, the name of a Gittite and of an Israelite Ithai, Ittai.', 'or אִיתַי; from 854; near;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H864}/[H864]', 'lemma', 'heb', 'אֵתָם', '["ʼÊthâm"]', '["Etham, a place in the Desert Etham."]', '["n-pr-loc"]', 'Etham, a place in the Desert Etham.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H865}/[H865]', 'lemma', 'heb', 'אֶתְמוֹל', '["ʼethmôwl"]', '["heretofore; definitely yesterday before (that) time, heretofore, of late (old), times past, yester(day)."]', '["adv"]', 'heretofore; definitely yesterday before (that) time, heretofore, of late (old), times past, yester(day).', 'or אִתְמוֹל; or אֶתְמוּל; probably from 853 or 854 and 4136;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H866}/[H866]', 'lemma', 'heb', 'אֶתְנָה', '["ʼethnâh"]', '["a present (as the price of harlotry) reward."]', '["n-f"]', 'a present (as the price of harlotry) reward.', 'from 8566;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H867}/[H867]', 'lemma', 'heb', 'אֶתְנִי', '["ʼEthnîy"]', '["Ethni, an Israelite Ethni."]', '["n-pr-m"]', 'Ethni, an Israelite Ethni.', 'perhaps from 866; munificence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H868}/[H868]', 'lemma', 'heb', 'אֶתְנַן', '["ʼethnan"]', '["a gift (as the price of harlotry or idolatry) hire, reward."]', '["n-m"]', 'a gift (as the price of harlotry or idolatry) hire, reward.', 'the same as 866;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H869}/[H869]', 'lemma', 'heb', 'אֶתְנַן', '["ʼEthnan"]', '["Ethnan, an Israelite Ethnan."]', '["n-pr-m"]', 'Ethnan, an Israelite Ethnan.', 'the same as 868 in the sense of 867;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H870}/[H870]', 'lemma', 'arc', 'אֲתַר', '["ʼăthar"]', '["a place; (adverb) after after, place."]', '["n-m"]', 'a place; (adverb) after after, place.', '(Aramaic) from a root corresponding to that of 871;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H871>', 'opaque', 'heb', 'אֲתָרִים', '["ʼĂthârîym"]', '["Atharim, a place near Palestine spies. b"]', '["n-pr-loc"]', 'Atharim, a place near Palestine spies. b', 'plural from an unused root (probably meaning to step); places;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H872}/[H872]', 'lemma', 'heb', 'בְּאָה', '["bᵉʼâh"]', '["an entrance to a building entry."]', '["n-f"]', 'an entrance to a building entry.', 'from 935;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H873}/[H873]', 'lemma', 'arc', 'בִּאוּשׁ', '["biʼûwsh"]', '["wicked bad."]', '["n-f"]', 'wicked bad.', '(Aramaic) from 888;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H874]', 'root', 'heb', 'בָּאַר', '["bâʼar"]', '["to dig; by analogy, to engrave; figuratively, to explain declare, (make) plain(-ly)."]', '["v"]', 'to dig; by analogy, to engrave; figuratively, to explain declare, (make) plain(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H875}/[H875]', 'lemma', 'heb', 'בְּאֵר', '["bᵉʼêr"]', '["a pit; especially a well pit, well."]', '["n-f"]', 'a pit; especially a well pit, well.', 'from 874;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H876}/[H876]', 'lemma', 'heb', 'בְּאֵר', '["Bᵉʼêr"]', '["Beer, a place in the Desert, also one in Palestine Beer."]', '["n-pr-loc"]', 'Beer, a place in the Desert, also one in Palestine Beer.', 'the same as 875;');
