INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H885}/[H885]', 'lemma', 'heb', 'בְּאֵרֹת בְּנֵי־יַעֲקַן', '["Bᵉʼêrôth Bᵉnêy-Yaʻăqan"]', '["Beeroth-Bene-Jaakan, a place in the Desert Beeroth of the children of Jaakan."]', '["n-pr-loc"]', 'Beeroth-Bene-Jaakan, a place in the Desert Beeroth of the children of Jaakan.', 'from the feminine plural of 875, and the plural contraction of 1121, and 3292; wells of (the) sons of Jaakan;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H886}/[H886]', 'lemma', 'heb', 'בְּאֵרֹתִי', '["Bᵉʼêrôthîy"]', '["a Beerothite or inhabitant of Beeroth Beerothite."]', '["a"]', 'a Beerothite or inhabitant of Beeroth Beerothite.', 'patrial from 881;');
