INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H889}/[H889]', 'lemma', 'heb', 'בְּאֹשׁ', '["bᵉʼôsh"]', '["a stench stink."]', '["n-m"]', 'a stench stink.', 'from 877;');
