INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H892>', 'opaque', 'heb', 'בָּבָה', '["bâbâh"]', '["something hollowed (as a gate), i.e. pupil of the eye apple (of the eye)."]', '["n-f"]', 'something hollowed (as a gate), i.e. pupil of the eye apple (of the eye).', 'feminine active participle of an unused root meaning to hollow out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H893>', 'opaque', 'heb', 'בֵּבַי', '["Bêbay"]', '["Bebai, an Israelite Bebai."]', '["n-pr-m"]', 'Bebai, an Israelite Bebai.', 'probably of foreign origin;');
