INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H897}/[H897]', 'lemma', 'heb', 'בַּג', '["bag"]', '["food spoil (from the margin for 957.)"]', '["n-m"]', 'food spoil (from the margin for 957.)', 'a Persian word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H898]', 'root', 'heb', 'בָּגַד', '["bâgad"]', '["to cover (with a garment); figuratively, to act covertly; by implication, to pillage deal deceitfully (treacherously, unfaithfully), offend, transgress(-or), (depart), treacherous (dealer, -ly, man), unfaithful(-ly, man), × very."]', '["v"]', 'to cover (with a garment); figuratively, to act covertly; by implication, to pillage deal deceitfully (treacherously, unfaithfully), offend, transgress(-or), (depart), treacherous (dealer, -ly, man), unfaithful(-ly, man), × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H899}/[H899]', 'lemma', 'heb', 'בֶּגֶד', '["beged"]', '["a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe."]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H900}/[H900]', 'lemma', 'heb', 'בֹּגְדוֹת', '["bôgᵉdôwth"]', '["treacheries treacherous."]', '["n-f"]', 'treacheries treacherous.', 'feminine plural active participle of 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H901}/[H901]', 'lemma', 'heb', 'בָּגוֹד', '["bâgôwd"]', '["treacherous treacherous."]', '["a"]', 'treacherous treacherous.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H902>', 'opaque', 'heb', 'בִּגְוַי', '["Bigvay"]', '["Bigvai, an Israelite Bigvai."]', '["n-pr-m"]', 'Bigvai, an Israelite Bigvai.', 'probably of foreign origin;');
