INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H904}/[H904]', 'lemma', 'heb', 'בִּגְתָן', '["Bigthân"]', '["Bigthan or Bigthana, a eunuch of Xerxes Bigthan, Bigthana."]', '["n-pr-m"]', 'Bigthan or Bigthana, a eunuch of Xerxes Bigthan, Bigthana.', 'or בִּגְתָנָא; of similar derivation to 903;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H905}/[H905]', 'lemma', 'heb', 'בַּד', '["bad"]', '["properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength."]', '["n-m"]', 'properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H906}/[H906]', 'lemma', 'heb', 'בַּד', '["bad"]', '["flaxen thread or yarn; hence, a linen garment linen."]', '["n-m"]', 'flaxen thread or yarn; hence, a linen garment linen.', 'perhaps from 909 (in the sense of divided fibres);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H907}/[H907]', 'lemma', 'heb', 'בַּד', '["bad"]', '["a brag or lie; also a liar liar, lie."]', '["n-m"]', 'a brag or lie; also a liar liar, lie.', 'from 908;');
