INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H909]', 'root', 'heb', 'בָּדַד', '["bâdad"]', '["to divide, i.e. (reflex.) be solitary alone."]', '["v"]', 'to divide, i.e. (reflex.) be solitary alone.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H910}/[H910]', 'lemma', 'heb', 'בָּדָד', '["bâdâd"]', '["separate; adverb, separately alone, desolate, only, solitary."]', '["n-m"]', 'separate; adverb, separately alone, desolate, only, solitary.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H911}/[H911]', 'lemma', 'heb', 'בְּדַד', '["Bᵉdad"]', '["Bedad, an Edomite Bedad."]', '["n-pr-m"]', 'Bedad, an Edomite Bedad.', 'from 909; separation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H912}/[H912]', 'lemma', 'heb', 'בֵּדְיָה', '["Bêdᵉyâh"]', '["Bedejah, an Israelite Bedeiah."]', '["n-pr-m"]', 'Bedejah, an Israelite Bedeiah.', 'probably a shortened form 5662; servant of Jehovah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H913}/[H913]', 'lemma', 'heb', 'בְּדִיל', '["bᵉdîyl"]', '["alloy (because removed by smelting); by analogy, tin plummet, tin."]', '["n-m"]', 'alloy (because removed by smelting); by analogy, tin plummet, tin.', 'from 914;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H914]', 'root', 'heb', 'בָּדַל', '["bâdal"]', '["to divide (in variation senses literally or figuratively, separate, distinguish, differ, select, etc.) (make, put) difference, divide (asunder), (make) separate (self, -ation), sever (out), × utterly."]', '["v"]', 'to divide (in variation senses literally or figuratively, separate, distinguish, differ, select, etc.) (make, put) difference, divide (asunder), (make) separate (self, -ation), sever (out), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H915}/[H915]', 'lemma', 'heb', 'בָּדָל', '["bâdâl"]', '["a part piece."]', '["n-m"]', 'a part piece.', 'from 914;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H916}/[H916]', 'lemma', 'heb', 'בְּדֹלַח', '["bᵉdôlach"]', '["something in pieces, i.e. bdellium, a (fragrant) gum (perhaps amber); others a pearl bdellium."]', '["n-m"]', 'something in pieces, i.e. bdellium, a (fragrant) gum (perhaps amber); others a pearl bdellium.', 'probably from 914;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H917}/[H917]', 'lemma', 'heb', 'בְּדָן', '["Bᵉdân"]', '["Bedan, the name of two Israelites Bedan."]', '["n-pr-m"]', 'Bedan, the name of two Israelites Bedan.', 'probably shortened for 5658; servile;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H918]', 'root', 'heb', 'בָּדַק', '["bâdaq"]', '["to mend a breach repair."]', '["v"]', 'to mend a breach repair.', 'a primitive root; to gap open; used only as a denominative from 919;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H919}/[H919]', 'lemma', 'heb', 'בֶּדֶק', '["bedeq"]', '["a gap or leak (in a building or a ship) breach, calker."]', '["n-m"]', 'a gap or leak (in a building or a ship) breach, calker.', 'from 918;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H920}/[H920]', 'lemma', 'heb', 'בִּדְקַר', '["Bidqar"]', '["Bidkar, an Israelite Bidkar."]', '["n-pr-m"]', 'Bidkar, an Israelite Bidkar.', 'probably from 1856 with a prepositional prefix; by stabbing, i.e. assassin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H921}/[H921]', 'lemma', 'arc', 'בְּדַר', '["bᵉdar"]', '["to scatter scatter."]', '["v"]', 'to scatter scatter.', '(Aramaic) corresponding (by transposition) to 6504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H922>', 'opaque', 'heb', 'בֹּהוּ', '["bôhûw"]', '["a vacuity, i.e. (superficially) an undistinguishable ruin emptiness, void."]', '["n-m"]', 'a vacuity, i.e. (superficially) an undistinguishable ruin emptiness, void.', 'from an unused root (meaning to be empty);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H923>', 'opaque', 'heb', 'בַּהַט', '["bahaṭ"]', '["white marble or perhaps alabaster red (marble)."]', '["n-m"]', 'white marble or perhaps alabaster red (marble).', 'from an unused root (probably meaning to glisten);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H924}/[H924]', 'lemma', 'arc', 'בְּהִילוּ', '["bᵉhîylûw"]', '["a hurry; only adverb, hastily in haste."]', '["adv"]', 'a hurry; only adverb, hastily in haste.', '(Aramaic) from 927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H925>', 'opaque', 'heb', 'בָּהִיר', '["bâhîyr"]', '["shining bright."]', '["a"]', 'shining bright.', 'from an unused root (meaning to be bright);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H926]', 'root', 'heb', 'בָּהַל', '["bâhal"]', '["to tremble inwardly (or palpitate), i.e. (figuratively) be (causative, make) (suddenly) alarmed or agitated; by implication to hasten anxiously be (make) affrighted (afraid, amazed, dismayed, rash), (be, get, make) haste(-n, -y, -ily), (give) speedy(-ily), thrust out, trouble, vex."]', '["v"]', 'to tremble inwardly (or palpitate), i.e. (figuratively) be (causative, make) (suddenly) alarmed or agitated; by implication to hasten anxiously be (make) affrighted (afraid, amazed, dismayed, rash), (be, get, make) haste(-n, -y, -ily), (give) speedy(-ily), thrust out, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H927}/[H927]', 'lemma', 'arc', 'בְּהַל', '["bᵉhal"]', '["to terrify, hasten in haste, trouble."]', '["v"]', 'to terrify, hasten in haste, trouble.', '(Aramaic) corresponding to 926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H928}/[H928]', 'lemma', 'heb', 'בֶּהָלָה', '["behâlâh"]', '["panic, destruction terror, trouble."]', '["n-f"]', 'panic, destruction terror, trouble.', 'from 926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H929>', 'opaque', 'heb', 'בְּהֵמָה', '["bᵉhêmâh"]', '["properly, a dumb beast; especially any large quadruped or animal (often collective) beast, cattle."]', '["n-f"]', 'properly, a dumb beast; especially any large quadruped or animal (often collective) beast, cattle.', 'from an unused root (probably meaning to be mute);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H930}/[H930]', 'lemma', 'heb', 'בְּהֵמוֹת', '["bᵉhêmôwth"]', '["a water-ox, i.e. the hippopotamus or Nile-horse Behemoth."]', '["n-m"]', 'a water-ox, i.e. the hippopotamus or Nile-horse Behemoth.', 'in form a plural or 929, but really a singular of Egyptian derivation;');
