INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H981]', 'root', 'heb', 'בָּטָא', '["bâṭâʼ"]', '["to babble; hence, to vociferate angrily pronounce, speak (unadvisedly)."]', '["v"]', 'to babble; hence, to vociferate angrily pronounce, speak (unadvisedly).', 'or בָּטָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H982]', 'root', 'heb', 'בָּטַח', '["bâṭach"]', '["properly, to hie for refuge (but not so precipitately as 2620); figuratively, to trust, be confident or sure be bold (confident, secure, sure), careless (one, woman), put confidence, (make to) hope, (put, make to) trust."]', '["v"]', 'properly, to hie for refuge (but not so precipitately as 2620); figuratively, to trust, be confident or sure be bold (confident, secure, sure), careless (one, woman), put confidence, (make to) hope, (put, make to) trust.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H983}/[H983]', 'lemma', 'heb', 'בֶּטַח', '["beṭach"]', '["properly, a place of refuge; abstract, safety, both the fact (security) and the feeling (trust); often (adverb with or without preposition) safely assurance, boldly, (without) care(-less), confidence, hope, safe(-ly, -ty), secure, surely."]', '["n-m"]', 'properly, a place of refuge; abstract, safety, both the fact (security) and the feeling (trust); often (adverb with or without preposition) safely assurance, boldly, (without) care(-less), confidence, hope, safe(-ly, -ty), secure, surely.', 'from 982;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H984}/[H984]', 'lemma', 'heb', 'בֶּטַח', '["Beṭach"]', '["Betach, a place in Syria Betah."]', '["n-pr-loc"]', 'Betach, a place in Syria Betah.', 'the same as 983;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H985}/[H985]', 'lemma', 'heb', 'בִּטְחָה', '["biṭchâh"]', '["trust confidence."]', '["n-f"]', 'trust confidence.', 'feminine of 984;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H986}/[H986]', 'lemma', 'heb', 'בִּטָּחוֹן', '["biṭṭâchôwn"]', '["trust confidence, hope."]', '["n-m"]', 'trust confidence, hope.', 'from 982;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H987}/[H987]', 'lemma', 'heb', 'בַּטֻּחוֹת', '["baṭṭuchôwth"]', '["security secure."]', '["n-f"]', 'security secure.', 'feminine plural from 982;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H988]', 'root', 'heb', 'בָּטֵל', '["bâṭêl"]', '["to desist from labor cease."]', '["v"]', 'to desist from labor cease.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H989}/[H989]', 'lemma', 'arc', 'בְּטֵל', '["bᵉṭêl"]', '["to stop (cause, make to), cease, hinder."]', '["v"]', 'to stop (cause, make to), cease, hinder.', '(Aramaic) corresponding to 988;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H990>', 'opaque', 'heb', 'בֶּטֶן', '["beṭen"]', '["the belly, especially the womb; also the bosom or body of anything belly, body, as they be born, within, womb."]', '["n-f"]', 'the belly, especially the womb; also the bosom or body of anything belly, body, as they be born, within, womb.', 'from an unused root probably meaning to be hollow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H991}/[H991]', 'lemma', 'heb', 'בֶּטֶן', '["Beṭen"]', '["Beten. a place in Palestine Beten."]', '["n-pr-loc"]', 'Beten. a place in Palestine Beten.', 'the same as 990;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H992}/[H992]', 'lemma', 'heb', 'בֹּטֶן', '["bôṭen"]', '["(only in plural) a pistachio-nut (from its form) nut."]', '["n-m"]', '(only in plural) a pistachio-nut (from its form) nut.', 'from 990;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H993}/[H993]', 'lemma', 'heb', 'בְּטֹנִים', '["Bᵉṭônîym"]', '["Betonim, a place in Palestine Betonim."]', '["n-pr-loc"]', 'Betonim, a place in Palestine Betonim.', 'probably plural from 992; hollows;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H994}/[H994]', 'lemma', 'heb', 'בִּי', '["bîy"]', '["oh that!; with leave, or if it please alas, O, oh."]', '["prt"]', 'oh that!; with leave, or if it please alas, O, oh.', 'perhaps from 1158 (in the sense of asking); properly, a request; used only adverbially (always with ''my Lord'');');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H995]', 'root', 'heb', 'בִּין', '["bîyn"]', '["to separate mentally (or distinguish), i.e.(generally) understand attend, consider, be cunning, diligently, direct, discern, eloquent, feel, inform, instruct, have intelligence, know, look well to, mark, perceive, be prudent, regard, (can) skill(-full), teach, think, (cause, make to, get, give, have) understand(-ing), view, (deal) wise(-ly, man)."]', '["v"]', 'to separate mentally (or distinguish), i.e.(generally) understand attend, consider, be cunning, diligently, direct, discern, eloquent, feel, inform, instruct, have intelligence, know, look well to, mark, perceive, be prudent, regard, (can) skill(-full), teach, think, (cause, make to, get, give, have) understand(-ing), view, (deal) wise(-ly, man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H996}/[H996]', 'lemma', 'heb', 'בֵּין', '["bêyn"]', '["between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within."]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H997}/[H997]', 'lemma', 'arc', 'בֵּין', '["bêyn"]', '["among, between."]', '["prep"]', 'among, between.', '(Aramaic) corresponding to 996');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H998}/[H998]', 'lemma', 'heb', 'בִּינָה', '["bîynâh"]', '["understanding knowledge, meaning, × perfectly, understanding, wisdom."]', '["n-f"]', 'understanding knowledge, meaning, × perfectly, understanding, wisdom.', 'from 995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H999}/[H999]', 'lemma', 'arc', 'בִּינָה', '["bîynâh"]', '["knowledge."]', '["n-f"]', 'knowledge.', '(Aramaic) corresponding to 998');
