INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1080}/[H1080]', 'lemma', 'arc', 'בְּלָא', '["bᵉlâʼ"]', '["to afflict wear out."]', '["v"]', 'to afflict wear out.', '(Aramaic) corresponding to 1086 (but used only in a mental sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1081}/[H1081]', 'lemma', 'heb', 'בַּלְאֲדָן', '["Balʼădân"]', '["Baladan, the name of a Babylonian prince Baladan."]', '["n-pr-m"]', 'Baladan, the name of a Babylonian prince Baladan.', 'from 1078 and 113 (contracted); Bel (is his) lord;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1082]', 'root', 'heb', 'בָּלַג', '["bâlag"]', '["to break off or loose (in a favorable or unfavorable sense), i.e. desist (from grief) or invade (with destruction) comfort, (recover) strength(-en)."]', '["v"]', 'to break off or loose (in a favorable or unfavorable sense), i.e. desist (from grief) or invade (with destruction) comfort, (recover) strength(-en).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1083}/[H1083]', 'lemma', 'heb', 'בִּלְגַה', '["Bilgah"]', '["Bilgah, the name of two Israelites Bilgah."]', '["n-pr-m"]', 'Bilgah, the name of two Israelites Bilgah.', 'from 1082; desistance;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1084}/[H1084]', 'lemma', 'heb', 'בִּלְגַּי', '["Bilgay"]', '["Bilgai, an Israelite Bilgai."]', '["n-pr-m"]', 'Bilgai, an Israelite Bilgai.', 'from 1082; desistant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1086]', 'root', 'heb', 'בָּלָה', '["bâlâh"]', '["to fail; by implication to wear out, decay (causatively, consume, spend) consume, enjoy long, become (make, wax) old, spend, waste."]', '["v"]', 'to fail; by implication to wear out, decay (causatively, consume, spend) consume, enjoy long, become (make, wax) old, spend, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1087}/[H1087]', 'lemma', 'heb', 'בָּלֶה', '["bâleh"]', '["worn out old."]', '["a"]', 'worn out old.', 'from 1086;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1088}/[H1088]', 'lemma', 'heb', 'בָּלָה', '["Bâlâh"]', '["Balah, a place in Palestine Balah."]', '["n-pr-loc"]', 'Balah, a place in Palestine Balah.', 'feminine of 1087; failure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1089]', 'root', 'heb', 'בָּלַהּ', '["bâlahh"]', '["to palpitate; hence, (causatively) to terrify trouble."]', '["v"]', 'to palpitate; hence, (causatively) to terrify trouble.', 'a primitive root (rather by transposition for 926);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1090}/[H1090]', 'lemma', 'heb', 'בִּלְהָה', '["Bilhâh"]', '["Bilhah, the name of one of Jacob''s concubines; also of a place in Palestine Bilhah."]', '["n-pr-f n-pr-loc"]', 'Bilhah, the name of one of Jacob''s concubines; also of a place in Palestine Bilhah.', 'from 1089; timid;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1091}/[H1091]', 'lemma', 'heb', 'בַּלָּהָה', '["ballâhâh"]', '["alarm; hence, destruction terror, trouble."]', '["n-f"]', 'alarm; hence, destruction terror, trouble.', 'from 1089;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1092}/[H1092]', 'lemma', 'heb', 'בִּלְהָן', '["Bilhân"]', '["Bilhan, the name of an Edomite and of an Israelite Bilhan."]', '["n-pr-m"]', 'Bilhan, the name of an Edomite and of an Israelite Bilhan.', 'from 1089; timid;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1093}/[H1093]', 'lemma', 'arc', 'בְּלוֹ', '["bᵉlôw"]', '["excise (on articles consumed) tribute."]', '["n-m"]', 'excise (on articles consumed) tribute.', '(Aramaic) from a root corresponding to 1086;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1094}/[H1094]', 'lemma', 'heb', 'בְּלוֹא', '["bᵉlôwʼ"]', '["(only in plural construction) rags old."]', '["n-m"]', '(only in plural construction) rags old.', 'or (fully) בְּלוֹי; from 1086;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1096}/[H1096]', 'lemma', 'arc', 'בֵּלְטְשַׁאצַּר', '["Bêlṭᵉshaʼtstsar"]', '["Belteshazzar."]', '["n-pr-m"]', 'Belteshazzar.', '(Aramaic) corresponding to 1095');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1097}/[H1097]', 'lemma', 'heb', 'בְּלִי', '["bᵉlîy"]', '["properly, failure, i.e. nothing or destruction; usually (with preposition) without, not yet, because not, as long as, etc. corruption, ig(norantly), for lack of, where no...is, so that no, none, not, un(awares), without."]', '["np"]', 'properly, failure, i.e. nothing or destruction; usually (with preposition) without, not yet, because not, as long as, etc. corruption, ig(norantly), for lack of, where no...is, so that no, none, not, un(awares), without.', 'from 1086;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1098}/[H1098]', 'lemma', 'heb', 'בְּלִיל', '["bᵉlîyl"]', '["mixed, i.e. (specifically) feed (for cattle) corn, fodder, provender."]', '["n-m"]', 'mixed, i.e. (specifically) feed (for cattle) corn, fodder, provender.', 'from 1101;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1099}/[H1099]', 'lemma', 'heb', 'בְּלִימָה', '["bᵉlîymâh"]', '["(as indefinitely) nothing whatever nothing."]', '["n-m"]', '(as indefinitely) nothing whatever nothing.', 'from 1097 and 4100;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1100}/[H1100]', 'lemma', 'heb', 'בְּלִיַּעַל', '["bᵉlîyaʻal"]', '["without profit, worthlessness; by extension, destruction, wickedness Belial, evil, naughty, ungodly (men), wicked."]', '["n-m"]', 'without profit, worthlessness; by extension, destruction, wickedness Belial, evil, naughty, ungodly (men), wicked.', 'from 1097 and 3276;(often in connection with 376, 802, 1121, etc.)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1101]', 'root', 'heb', 'בָּלַל', '["bâlal"]', '["to overflow (specifically with oil.); by implication, to mix; to fodder anoint, confound, × fade, mingle, mix (self), give provender, temper."]', '["v"]', 'to overflow (specifically with oil.); by implication, to mix; to fodder anoint, confound, × fade, mingle, mix (self), give provender, temper.', 'a primitive root; (also denominatively from 1098) to fodder');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1102]', 'root', 'heb', 'בָּלַם', '["bâlam"]', '["to muzzle be held in."]', '["v"]', 'to muzzle be held in.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1103]', 'root', 'heb', 'בָּלַס', '["bâlaç"]', '["to pinch sycamore figs (a process necessary to ripen them) gatherer."]', '["v"]', 'to pinch sycamore figs (a process necessary to ripen them) gatherer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1104]', 'root', 'heb', 'בָּלַע', '["bâlaʻ"]', '["to make away with (specifically by swallowing); generally, to destroy cover, destroy, devour, eat up, be at end, spend up, swallow down (up)."]', '["v"]', 'to make away with (specifically by swallowing); generally, to destroy cover, destroy, devour, eat up, be at end, spend up, swallow down (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1105}/[H1105]', 'lemma', 'heb', 'בֶּלַע', '["belaʻ"]', '["a gulp; figuratively, destruction devouring, that which he hath swallowed up."]', '["n-m"]', 'a gulp; figuratively, destruction devouring, that which he hath swallowed up.', 'from 1104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1106}/[H1106]', 'lemma', 'heb', 'בֶּלַע', '["Belaʻ"]', '["Bela, the name of a place, also of an Edomite and of two Israelites Bela."]', '["n-pr-m n-pr-loc"]', 'Bela, the name of a place, also of an Edomite and of two Israelites Bela.', 'the same as 1105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1107}/[H1107]', 'lemma', 'heb', 'בִּלְעֲדֵי', '["bilʻădêy"]', '["except, without, besides beside, not (in), save, without."]', '["prt"]', 'except, without, besides beside, not (in), save, without.', 'or בַּלְעֲדֵי; constructive plural from 1077 and 5703, not till, i.e. (as preposition or adverb)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1108}/[H1108]', 'lemma', 'heb', 'בַּלְעִי', '["Balʻîy"]', '["a Belaite (collectively) or descendants of Bela Belaites."]', '["a"]', 'a Belaite (collectively) or descendants of Bela Belaites.', 'patronymically from 1106;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1109}/[H1109]', 'lemma', 'heb', 'בִּלְעָם', '["Bilʻâm"]', '["Bilam, a Mesopotamian prophet; also a place in Palestine Balaam, Bileam."]', '["n-pr-m n-pr-loc"]', 'Bilam, a Mesopotamian prophet; also a place in Palestine Balaam, Bileam.', 'probably from 1077 and 5971; not (of the) people, i.e. foreigner;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1110]', 'root', 'heb', 'בָּלַק', '["bâlaq"]', '["to annihilate (make) waste."]', '["v"]', 'to annihilate (make) waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1111}/[H1111]', 'lemma', 'heb', 'בָּלָק', '["Bâlâq"]', '["Balak, a Moabitish king Balak."]', '["n-pr-m"]', 'Balak, a Moabitish king Balak.', 'from 1110; waster;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1113}/[H1113]', 'lemma', 'arc', 'בֵּלְשַׁאצַּר', '["Bêlshaʼtstsar"]', '["Belshazzar."]', '["n-pr-m"]', 'Belshazzar.', '(Aramaic) corresponding to 1112');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1115}/[H1115]', 'lemma', 'heb', 'בִּלְתִּי', '["biltîy"]', '["properly, a failure of, i.e. (used only as a negative particle, usually with a prepositional prefix) not, except, without, unless, besides, because not, until, etc. because un(satiable), beside, but, continual, except, from, lest, neither, no more, none, not, nothing, save, that no, without."]', '["np"]', 'properly, a failure of, i.e. (used only as a negative particle, usually with a prepositional prefix) not, except, without, unless, besides, because not, until, etc. because un(satiable), beside, but, continual, except, from, lest, neither, no more, none, not, nothing, save, that no, without.', 'constructive feminine of 1086 (equivalent to 1097);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1117}/[H1117]', 'lemma', 'heb', 'בָּמָה', '["Bâmâh"]', '["Bamah, a place in Palestine Bamah. See also 1120."]', '["n-pr-loc"]', 'Bamah, a place in Palestine Bamah. See also 1120.', 'the same as 1116;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1118}/[H1118]', 'lemma', 'heb', 'בִּמְהָל', '["Bimhâl"]', '["Bimhal, an Israelite Bimhal."]', '["n-pr-m"]', 'Bimhal, an Israelite Bimhal.', 'probably from 4107 with prepositional prefix; with pruning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1120}/[H1120]', 'lemma', 'heb', 'בָּמוֹת', '["Bâmôwth"]', '["Bamoth or Bamoth-Baal, a place East of the Jordan Bamoth, Bamoth-baal."]', '["n-pr-loc"]', 'Bamoth or Bamoth-Baal, a place East of the Jordan Bamoth, Bamoth-baal.', 'plural of 1116; heights; or (fully) בָּמוֹת בַּעַל; from the same and 1168; heights of Baal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121}/[H1121]', 'lemma', 'heb', 'בֵּן', '["bên"]', '["a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth."]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1122}/[H1122]', 'lemma', 'heb', 'בֵּן', '["Bên"]', '["Ben, an Israelite Ben."]', '["n-pr-m"]', 'Ben, an Israelite Ben.', 'the same as 1121;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1123}/[H1123]', 'lemma', 'arc', 'בֵּן', '["bên"]', '["child, son, young."]', '["n-m"]', 'child, son, young.', '(Aramaic) corresponding to 1121');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1124}/[H1124]', 'lemma', 'arc', 'בְּנָא', '["bᵉnâʼ"]', '["to build build, make."]', '["v"]', 'to build build, make.', '(Aramaic) or בְּנָה; (Aramaic), corresponding to 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1125}/[H1125]', 'lemma', 'heb', 'בֶּן־אֲבִינָדָב', '["Ben-ʼĂbîynâdâb"]', '["Ben-Abinadab, an Israelite the son of Abinadab."]', '["n-pr-m"]', 'Ben-Abinadab, an Israelite the son of Abinadab.', 'from 1121 and 40; (the) son of Abinadab;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1126}/[H1126]', 'lemma', 'heb', 'בֶּן־אוֹנִי', '["Ben-ʼÔwnîy"]', '["Ben-Oni, the original name of Benjamin Ben-oni."]', '["n-pr-m"]', 'Ben-Oni, the original name of Benjamin Ben-oni.', 'from 1121 and 205; son of my sorrow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1127}/[H1127]', 'lemma', 'heb', 'בֶּן־גֶּבֶר', '["Ben-Geber"]', '["Ben-Geber, an Israelite the son of Geber."]', '["n-pr-m"]', 'Ben-Geber, an Israelite the son of Geber.', 'from 1121 and 1397; son of (the) hero;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1128}/[H1128]', 'lemma', 'heb', 'בֶּן־דֶּקֶר', '["Ben-Deqer"]', '["Ben-Deker, an Israelite the son of Dekar."]', '["n-pr-m"]', 'Ben-Deker, an Israelite the son of Dekar.', 'from 1121 and a derivative of 1856; son of piercing (or of a lance);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1129]', 'root', 'heb', 'בָּנָה', '["bânâh"]', '["to build (literally and figuratively) (begin to) build(-er), obtain children, make, repair, set (up), × surely."]', '["v"]', 'to build (literally and figuratively) (begin to) build(-er), obtain children, make, repair, set (up), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1130}/[H1130]', 'lemma', 'heb', 'בֶּן־הֲדַד', '["Ben-Hădad"]', '["Ben-Hadad, the name of several Syrian kings Benhadad."]', '["n-pr-m"]', 'Ben-Hadad, the name of several Syrian kings Benhadad.', 'from 1121 and 1908; son of Hadad;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1131}/[H1131]', 'lemma', 'heb', 'בִּנּוּי', '["Binnûwy"]', '["Binnui, an Israelite Binnui."]', '["n-pr-m"]', 'Binnui, an Israelite Binnui.', 'from 1129; built up;');
