INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1234]', 'root', 'heb', 'בָּקַע', '["bâqaʻ"]', '["to cleave; generally, to rend, break, rip or open make a breach, break forth (into, out, in pieces, through, up), be ready to burst, cleave (asunder), cut out, divide, hatch, rend (asunder), rip up, tear, win."]', '["v"]', 'to cleave; generally, to rend, break, rip or open make a breach, break forth (into, out, in pieces, through, up), be ready to burst, cleave (asunder), cut out, divide, hatch, rend (asunder), rip up, tear, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1235}/[H1235]', 'lemma', 'heb', 'בֶּקַע', '["beqaʻ"]', '["a section (half) of a shekel, i.e. a beka (a weight and a coin) bekah, half a shekel."]', '["n-m"]', 'a section (half) of a shekel, i.e. a beka (a weight and a coin) bekah, half a shekel.', 'from 1234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1236}/[H1236]', 'lemma', 'arc', 'בִּקְעָא', '["biqʻâʼ"]', '["plain."]', '["n-f"]', 'plain.', '(Aramaic) corresponding to 1237');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1237}/[H1237]', 'lemma', 'heb', 'בִּקְעָה', '["biqʻâh"]', '["properly, a split, i.e. a wide level valley between mountains plain, valley."]', '["n-f"]', 'properly, a split, i.e. a wide level valley between mountains plain, valley.', 'from 1234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1238]', 'root', 'heb', 'בָּקַק', '["bâqaq"]', '["to pour out, i.e. to empty, figuratively, to depopulate; by analogy, to spread out (as a fruitful vine) (make) empty (out), fail, × utterly, make void."]', '["v"]', 'to pour out, i.e. to empty, figuratively, to depopulate; by analogy, to spread out (as a fruitful vine) (make) empty (out), fail, × utterly, make void.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1239]', 'root', 'heb', 'בָּקַר', '["bâqar"]', '["properly, to plough, or (generally) break forth, i.e. (figuratively) to inspect, admire, care for, consider (make) inquire (-ry), (make) search, seek out."]', '["v"]', 'properly, to plough, or (generally) break forth, i.e. (figuratively) to inspect, admire, care for, consider (make) inquire (-ry), (make) search, seek out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1240}/[H1240]', 'lemma', 'arc', 'בְּקַר', '["bᵉqar"]', '["inquire, make search."]', '["v"]', 'inquire, make search.', '(Aramaic) corresponding to 1239');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1241}/[H1241]', 'lemma', 'heb', 'בָּקָר', '["bâqâr"]', '["a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox."]', '["n-m"]', 'a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1242}/[H1242]', 'lemma', 'heb', 'בֹּקֶר', '["bôqer"]', '["properly, dawn (as the break of day); generally, morning ( ) day, early, morning, morrow."]', '["n-m"]', 'properly, dawn (as the break of day); generally, morning ( ) day, early, morning, morrow.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1243}/[H1243]', 'lemma', 'heb', 'בַּקָּרָה', '["baqqârâh"]', '["a looking after seek out."]', '["n-f"]', 'a looking after seek out.', 'intensive from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1244}/[H1244]', 'lemma', 'heb', 'בִּקֹּרֶת', '["biqqôreth"]', '["properly, examination, i.e. (by implication) punishment scourged."]', '["n-f"]', 'properly, examination, i.e. (by implication) punishment scourged.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1245]', 'root', 'heb', 'בָּקַשׁ', '["bâqash"]', '["to search out (by any method, specifically in worship or prayer); by implication, to strive after ask, beg, beseech, desire, enquire, get, make inquisition, procure, (make) request, require, seek (for)."]', '["v"]', 'to search out (by any method, specifically in worship or prayer); by implication, to strive after ask, beg, beseech, desire, enquire, get, make inquisition, procure, (make) request, require, seek (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1246}/[H1246]', 'lemma', 'heb', 'בַּקָּשָׁה', '["baqqâshâh"]', '["a petition request."]', '["n-m"]', 'a petition request.', 'from 1245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1247}/[H1247]', 'lemma', 'arc', 'בַּר', '["bar"]', '["a son, grandson, etc. × old, son."]', '["n-m"]', 'a son, grandson, etc. × old, son.', '(Aramaic) corresponding to 1121;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1248}/[H1248]', 'lemma', 'heb', 'בַּר', '["bar"]', '["the heir (apparent to the throne) son."]', '["n-m"]', 'the heir (apparent to the throne) son.', 'borrowed (as a title) from 1247;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1249}/[H1249]', 'lemma', 'heb', 'בַּר', '["bar"]', '["beloved; also pure, empty choice, clean, clear, pure."]', '["a"]', 'beloved; also pure, empty choice, clean, clear, pure.', 'from 1305 (in its various senses);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1250}/[H1250]', 'lemma', 'heb', 'בָּר', '["bâr"]', '["grain of any kind (even while standing in the field); by extension the open country corn, wheat."]', '["n-m"]', 'grain of any kind (even while standing in the field); by extension the open country corn, wheat.', 'or בַּר; from 1305 (in the sense of winnowing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1251}/[H1251]', 'lemma', 'arc', 'בַּר', '["bar"]', '["a field field."]', '["n-m"]', 'a field field.', '(Aramaic) corresponding to 1250;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1252}/[H1252]', 'lemma', 'heb', 'בֹּר', '["bôr"]', '["purity cleanness, pureness."]', '["n-m"]', 'purity cleanness, pureness.', 'from 1305;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1253}/[H1253]', 'lemma', 'heb', 'בֹּר', '["bôr"]', '["vegetable lye (from its cleansing); used as a soap for washing, or a flux for metals × never so, purely."]', '["n-m"]', 'vegetable lye (from its cleansing); used as a soap for washing, or a flux for metals × never so, purely.', 'the same as 1252;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1254]', 'root', 'heb', 'בָּרָא', '["bârâʼ"]', '["(absolutely) to create; (qualified) to cut down (a wood), select, feed (as formative processes) choose, create (creator), cut down, dispatch, do, make (fat)."]', '["v"]', '(absolutely) to create; (qualified) to cut down (a wood), select, feed (as formative processes) choose, create (creator), cut down, dispatch, do, make (fat).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1255}/[H1255]', 'lemma', 'heb', 'בְּרֹאדַךְ בַּלְאֲדָן', '["Bᵉrôʼdak Balʼădân"]', '["Berodak-Baladan, a Babylonian king Berodach-baladan."]', '["n-pr-m"]', 'Berodak-Baladan, a Babylonian king Berodach-baladan.', 'a variation of 4757;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1256}/[H1256]', 'lemma', 'heb', 'בְּרָאיָה', '["Bᵉrâʼyâh"]', '["Berajah, an Israelite Beraiah."]', '["n-pr-m"]', 'Berajah, an Israelite Beraiah.', 'from 1254 and 3050; Jah has created;');
