INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1260}/[H1260]', 'lemma', 'heb', 'בֶּרֶד', '["Bered"]', '["Bered, the name of a place south of Palestine, also of an Israelite Bered."]', '["n-pr-m n-pr-loc"]', 'Bered, the name of a place south of Palestine, also of an Israelite Bered.', 'from 1258; hail;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1261}/[H1261]', 'lemma', 'heb', 'בָּרֹד', '["bârôd"]', '["spotted (as if with hail) grisled."]', '["a"]', 'spotted (as if with hail) grisled.', 'from 1258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1262]', 'root', 'heb', 'בָּרָה', '["bârâh"]', '["to select; to feed; to render clear choose, (cause to) eat, manifest, (give) meat."]', '["v"]', 'to select; to feed; to render clear choose, (cause to) eat, manifest, (give) meat.', 'a primitive root; to select; also (as denominative from 1250) to feed; also (as equivalent to 1305) to render clear (Ecclesiastes 3:18)');
