INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1266}/[H1266]', 'lemma', 'heb', 'בְּרוֹת', '["bᵉrôwth"]', '["the cypress (or some elastic tree) fir."]', '["n-m"]', 'the cypress (or some elastic tree) fir.', 'a variation of 1265;');
