INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1268}/[H1268]', 'lemma', 'heb', 'בֵּרוֹתָה', '["Bêrôwthâh"]', '["Berothah or Berothai, a place north of Palestine Berothah, Berothai."]', '["n-pr-loc"]', 'Berothah or Berothai, a place north of Palestine Berothah, Berothai.', 'or בֵּרֹתַי; probably from 1266; cypress or cypresslike;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1270}/[H1270]', 'lemma', 'heb', 'בַּרְזֶל', '["barzel"]', '["iron (as cutting); by extension, an iron implement (ax) head, iron."]', '["n-m"]', 'iron (as cutting); by extension, an iron implement (ax) head, iron.', 'perhaps from the root of 1269;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1271}/[H1271]', 'lemma', 'heb', 'בַּרְזִלַּי', '["Barzillay"]', '["Barzillai, the name of three Israelites Barzillai."]', '["n-pr-m"]', 'Barzillai, the name of three Israelites Barzillai.', 'from 1270; iron-hearted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1272]', 'root', 'heb', 'בָּרַח', '["bârach"]', '["to bolt, i.e. figuratively, to flee suddenly chase (away); drive away, fain, flee (away), put to flight, make haste, reach, run away, shoot."]', '["v"]', 'to bolt, i.e. figuratively, to flee suddenly chase (away); drive away, fain, flee (away), put to flight, make haste, reach, run away, shoot.', 'a primitive root;');
