INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1275}/[H1275]', 'lemma', 'heb', 'בֵּרִי', '["Bêrîy"]', '["Beri, an Israelite Beri."]', '["n-pr-m"]', 'Beri, an Israelite Beri.', 'probably by contraction from 882;');
