INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1277}/[H1277]', 'lemma', 'heb', 'בָּרִיא', '["bârîyʼ"]', '["fatted or plump fat ((fleshed), -ter), fed, firm, plenteous, rank."]', '["a"]', 'fatted or plump fat ((fleshed), -ter), fed, firm, plenteous, rank.', 'from 1254 (in the sense of 1262);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1278}/[H1278]', 'lemma', 'heb', 'בְּרִיאָה', '["bᵉrîyʼâh"]', '["a creation, i.e. a novelty new thing."]', '["n-f"]', 'a creation, i.e. a novelty new thing.', 'feminine from 1254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1279}/[H1279]', 'lemma', 'heb', 'בִּרְיָה', '["biryâh"]', '["food meat."]', '["n-f"]', 'food meat.', 'feminine from 1262;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1280}/[H1280]', 'lemma', 'heb', 'בְּרִיחַ', '["bᵉrîyach"]', '["a bolt bar, fugitive."]', '["n-m"]', 'a bolt bar, fugitive.', 'from 1272;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1281}/[H1281]', 'lemma', 'heb', 'בָּרִיחַ', '["bârîyach"]', '["a fugitive, i.e. the serpent (as fleeing), and the constellation by that name crooked, noble, piercing."]', '["n-m"]', 'a fugitive, i.e. the serpent (as fleeing), and the constellation by that name crooked, noble, piercing.', 'or בָּרִחַ; (shortened) from 1272;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1282}/[H1282]', 'lemma', 'heb', 'בָּרִיחַ', '["Bârîyach"]', '["Bariach, an Israelite Bariah."]', '["n-pr-m"]', 'Bariach, an Israelite Bariah.', 'the same as 1281;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1283}/[H1283]', 'lemma', 'heb', 'בְּרִיעָה', '["Bᵉrîyʻâh"]', '["Beriah, the name of four Israelites Beriah."]', '["n-pr-m"]', 'Beriah, the name of four Israelites Beriah.', 'apparently from the feminine of 7451 with a prepositional prefix; in trouble;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1284}/[H1284]', 'lemma', 'heb', 'בְּרִיעִי', '["Bᵉrîyʻîy"]', '["a Beriite (collectively) or descendants of Beriah Beerites."]', '["a"]', 'a Beriite (collectively) or descendants of Beriah Beerites.', 'patronymically from 1283;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1285}/[H1285]', 'lemma', 'heb', 'בְּרִית', '["bᵉrîyth"]', '["a compact (because made by passing between pieces of flesh) confederacy, (con-) feder(-ate), covenant, league."]', '["n-f"]', 'a compact (because made by passing between pieces of flesh) confederacy, (con-) feder(-ate), covenant, league.', 'from 1262 (in the sense of cutting [like 1254]);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1286}/[H1286]', 'lemma', 'heb', 'בְּרִית', '["Bᵉrîyth"]', '["Berith, a Shechemitish deity Berith."]', '["n-pr-m"]', 'Berith, a Shechemitish deity Berith.', 'the same as 1285;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1287}/[H1287]', 'lemma', 'heb', 'בֹּרִית', '["bôrîyth"]', '["vegetable alkali sope."]', '["n-f"]', 'vegetable alkali sope.', 'feminine of 1253;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1288]', 'root', 'heb', 'בָּרַךְ', '["bârak"]', '["to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank."]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1289}/[H1289]', 'lemma', 'arc', 'בְּרַךְ', '["bᵉrak"]', '["bless, kneel."]', '["v"]', 'bless, kneel.', '(Aramaic) corresponding to 1288');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1290}/[H1290]', 'lemma', 'heb', 'בֶּרֶךְ', '["berek"]', '["a knee knee."]', '["n-f"]', 'a knee knee.', 'from 1288;');
