INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1295}/[H1295]', 'lemma', 'heb', 'בְּרֵכָה', '["bᵉrêkâh"]', '["a reservoir (at which camels kneel as a resting-place) (fish-) pool."]', '["n-f"]', 'a reservoir (at which camels kneel as a resting-place) (fish-) pool.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1296}/[H1296]', 'lemma', 'heb', 'בֶּרֶכְיָה', '["Berekyâh"]', '["Berekjah, the name of six Israelites Berachiah, Berechiah."]', '["n-pr-m"]', 'Berekjah, the name of six Israelites Berachiah, Berechiah.', 'or בֶּרֶכְיָהוּ; from 1290 and 3050; knee (i.e. blessing) of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1297}/[H1297]', 'lemma', 'arc', 'בְּרַם', '["bᵉram"]', '["properly, highly, i.e. surely; but used adversatively, however but, nevertheless, yet."]', '["adv"]', 'properly, highly, i.e. surely; but used adversatively, however but, nevertheless, yet.', '(Aramaic) perhaps from 7313 with a prepositional prefix;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1299]', 'root', 'heb', 'בָּרַק', '["bâraq"]', '["to lighten (lightning) cast forth."]', '["v"]', 'to lighten (lightning) cast forth.', 'a primitive root;');
