INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1301}/[H1301]', 'lemma', 'heb', 'בָּרָק', '["Bârâq"]', '["Barak, an Israelite Barak."]', '["n-pr-m"]', 'Barak, an Israelite Barak.', 'the same as 1300;');
