INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1305]', 'root', 'heb', 'בָּרַר', '["bârar"]', '["to clarify (i.e. brighten), examine, select make bright, choice, chosen, cleanse (be clean), clearly, polished, (shew self) pure(-ify), purge (out)."]', '["v"]', 'to clarify (i.e. brighten), examine, select make bright, choice, chosen, cleanse (be clean), clearly, polished, (shew self) pure(-ify), purge (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1306}/[H1306]', 'lemma', 'heb', 'בִּרְשַׁע', '["Birshaʻ"]', '["Birsha, a king of Gomorrah Birsha."]', '["n-pr-m"]', 'Birsha, a king of Gomorrah Birsha.', 'probably from 7562 with a prepositional prefix; with wickedness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1307}/[H1307]', 'lemma', 'heb', 'בֵּרֹתִי', '["Bêrôthîy"]', '["a Berothite, or inhabitant of Berothai Berothite."]', '["a"]', 'a Berothite, or inhabitant of Berothai Berothite.', 'patrial from 1268;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1308}/[H1308]', 'lemma', 'heb', 'בְּשׂוֹר', '["Bᵉsôwr"]', '["Besor, a stream of Palestine Besor."]', '["n"]', 'Besor, a stream of Palestine Besor.', 'from 1319; cheerful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1309}/[H1309]', 'lemma', 'heb', 'בְּשׂוֹרָה', '["bᵉsôwrâh"]', '["glad tidings; by implication, reward for good news reward for tidings."]', '["n-f"]', 'glad tidings; by implication, reward for good news reward for tidings.', 'or (shortened) בְּשֹׂרָה; feminine from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1310]', 'root', 'heb', 'בָּשַׁל', '["bâshal"]', '["properly, to boil up; hence, to be done in cooking; figuratively to ripen bake, boil, bring forth, roast, seethe, sod (be sodden)."]', '["v"]', 'properly, to boil up; hence, to be done in cooking; figuratively to ripen bake, boil, bring forth, roast, seethe, sod (be sodden).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1311}/[H1311]', 'lemma', 'heb', 'בָּשֵׁל', '["bâshêl"]', '["boiled × at all, sodden."]', '["a"]', 'boiled × at all, sodden.', 'from 1310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1313>', 'opaque', 'heb', 'בָּשָׂם', '["bâsâm"]', '["the balsam plant spice."]', '["n-m"]', 'the balsam plant spice.', 'from an unused root meaning to be fragrant; (compare 5561)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1314}/[H1314]', 'lemma', 'heb', 'בֶּשֶׂם', '["besem"]', '["fragrance; by implication, spicery; also the balsam plant smell, spice, sweet (odour)."]', '["n-m"]', 'fragrance; by implication, spicery; also the balsam plant smell, spice, sweet (odour).', 'or בֹּשֶׂם; from the same as 1313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1315}/[H1315]', 'lemma', 'heb', 'בׇּשְׂמַת', '["Bosmath"]', '["Bosmath, the name of a wife of Esau, and of a daughter of Solomon Bashemath, Basmath."]', '["n-pr-f"]', 'Bosmath, the name of a wife of Esau, and of a daughter of Solomon Bashemath, Basmath.', 'feminine of 1314 (the second form); fragrance;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1317}/[H1317]', 'lemma', 'heb', 'בׇּשְׁנָה', '["boshnâh"]', '["shamefulness shame."]', '["n-m"]', 'shamefulness shame.', 'feminine from 954;');
