INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1324}/[H1324]', 'lemma', 'heb', 'בַּת', '["bath"]', '["a bath or Hebrew measure (as a means of division) of liquids bath."]', '["n-m"]', 'a bath or Hebrew measure (as a means of division) of liquids bath.', 'probably from the same as 1327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1325}/[H1325]', 'lemma', 'arc', 'בַּת', '["bath"]', '["bath."]', '["n-m"]', 'bath.', '(Aramaic) corresponding to 1324');
