INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1341}/[H1341]', 'lemma', 'heb', 'גֵּא', '["gêʼ"]', '["haughty proud."]', '["a"]', 'haughty proud.', 'for 1343;');
