INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1350]', 'root', 'heb', 'גָּאַל', '["gâʼal"]', '["to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger."]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
