INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1406}/[H1406]', 'lemma', 'heb', 'גָּג', '["gâg"]', '["a roof; by analogy, the top of an altar roof (of the house), (house) top (of the house)."]', '["n-m"]', 'a roof; by analogy, the top of an altar roof (of the house), (house) top (of the house).', 'probably by reduplication from 1342;');
