INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1411}/[H1411]', 'lemma', 'arc', 'גְּדָבָר', '["gᵉdâbâr"]', '["a treasurer treasurer."]', '["n-m"]', 'a treasurer treasurer.', '(Aramaic) corresponding to 1489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1412}/[H1412]', 'lemma', 'heb', 'גֻּדְגֹּדָה', '["Gudgôdâh"]', '["Gudgodah, a place in the Desert Gudgodah."]', '["n-pr-loc"]', 'Gudgodah, a place in the Desert Gudgodah.', 'by reduplication from 1413 (in the sense of cutting) cleft;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1413]', 'root', 'heb', 'גָּדַד', '["gâdad"]', '["to crowd; also to gash (as if by pressing into) assemble (selves by troops), gather (selves together, self in troops), cut selves."]', '["v"]', 'to crowd; also to gash (as if by pressing into) assemble (selves by troops), gather (selves together, self in troops), cut selves.', 'a primitive root (compare 1464);');
