INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1416}/[H1416]', 'lemma', 'heb', 'גְּדוּד', '["gᵉdûwd"]', '["a crowd (especially of soldiers) army, band (of men), company, troop (of robbers)."]', '["n-m"]', 'a crowd (especially of soldiers) army, band (of men), company, troop (of robbers).', 'from 1413;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1417}/[H1417]', 'lemma', 'heb', 'גְּדוּד', '["gᵉdûwd"]', '["a furrow (as cut) furrow."]', '["n"]', 'a furrow (as cut) furrow.', 'or גְּדֻדָה; (feminine) from 1413;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1418}/[H1418]', 'lemma', 'heb', 'גְּדוּדָה', '["gᵉdûwdâh"]', '["an incision cutting."]', '["n"]', 'an incision cutting.', 'feminine participle passive of 1413;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1419}/[H1419]', 'lemma', 'heb', 'גָּדוֹל', '["gâdôwl"]', '["great (in any sense); hence, older; also insolent aloud, elder(-est), exceeding(-ly), far, (man of) great (man, matter, thing,-er,-ness), high, long, loud, mighty, more, much, noble, proud thing, × sore, (×) very."]', '["a n-pr-m"]', 'great (in any sense); hence, older; also insolent aloud, elder(-est), exceeding(-ly), far, (man of) great (man, matter, thing,-er,-ness), high, long, loud, mighty, more, much, noble, proud thing, × sore, (×) very.', 'or גָּדֹל; (shortened) from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1420}/[H1420]', 'lemma', 'heb', 'גְּדוּלָה', '["gᵉdûwlâh"]', '["greatness; (concretely) mighty acts dignity, great things(-ness), majesty."]', '["n-f"]', 'greatness; (concretely) mighty acts dignity, great things(-ness), majesty.', 'or גְּדֻלָּה; (shortened) or (less accurately) גְּדוּלָּה; feminine of 1419;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1421}/[H1421]', 'lemma', 'heb', 'גִּדּוּף', '["giddûwph"]', '["vilification reproach, reviling."]', '["n-m"]', 'vilification reproach, reviling.', 'or (shortened) גִּדֻּף; and (feminine) גִּדּוּפָהxlit giddûphâh corrected to giddûwphâh; or גִּדֻּפָה; from 1422;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1422}/[H1422]', 'lemma', 'heb', 'גְּדוּפָה', '["gᵉdûwphâh"]', '["a revilement taunt."]', '["n-f"]', 'a revilement taunt.', 'feminine passive participle of 1442;');
