INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1430>', 'opaque', 'heb', 'גָּדִישׁ', '["gâdîysh"]', '["a stack of sheaves; by analogy, a tomb shock (stack) (of corn), tomb."]', '["n-m"]', 'a stack of sheaves; by analogy, a tomb shock (stack) (of corn), tomb.', 'from an unused root (meaning to heap up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1431]', 'root', 'heb', 'גָּדַל', '["gâdal"]', '["to be (causatively make) large (in various senses, as in body, mind, estate or honor, also in pride) advance, boast, bring up, exceed, excellent, be(-come, do, give, make, wax), great(-er, come to... estate, things), grow(up), increase, lift up, magnify(-ifical), be much set by, nourish (up), pass, promote, proudly (spoken), tower."]', '["v"]', 'to be (causatively make) large (in various senses, as in body, mind, estate or honor, also in pride) advance, boast, bring up, exceed, excellent, be(-come, do, give, make, wax), great(-er, come to... estate, things), grow(up), increase, lift up, magnify(-ifical), be much set by, nourish (up), pass, promote, proudly (spoken), tower.', 'a primitive root; properly, to twist (compare 1434), i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1432}/[H1432]', 'lemma', 'heb', 'גָּדֵל', '["gâdêl"]', '["large (literally or figuratively) great, grew."]', '["a"]', 'large (literally or figuratively) great, grew.', 'from 1431;');
