INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1462}/[H1462]', 'lemma', 'heb', 'גּוֹב', '["gôwb"]', '["the locust (from its grubbing as a larvae) grasshopper, × great."]', '["n-m"]', 'the locust (from its grubbing as a larvae) grasshopper, × great.', 'from 1461;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1463>', 'opaque', 'heb', 'גּוֹג', '["Gôwg"]', '["Gog, the name of an Israelite, also of some northern nation Gog."]', '["n-pr-m"]', 'Gog, the name of an Israelite, also of some northern nation Gog.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1464]', 'root', 'heb', 'גּוּד', '["gûwd"]', '["to crowd upon, i.e. attack invade, overcome."]', '["v"]', 'to crowd upon, i.e. attack invade, overcome.', 'a primitive root (akin to 1413);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1465}/[H1465]', 'lemma', 'heb', 'גֵּוָה', '["gêvâh"]', '["the back, i.e. (by extension) the person body."]', '["n-f"]', 'the back, i.e. (by extension) the person body.', 'feminine of 1460;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1466}/[H1466]', 'lemma', 'heb', 'גֵּוָה', '["gêvâh"]', '["exaltation; (figuratively) arrogance lifting up, pride."]', '["n-f"]', 'exaltation; (figuratively) arrogance lifting up, pride.', 'the same as 1465;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1467}/[H1467]', 'lemma', 'arc', 'גֵּוָה', '["gêvâh"]', '["pride."]', '["n-f"]', 'pride.', '(Aramaic) corresponding to 1466');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1468]', 'root', 'heb', 'גּוּז', '["gûwz"]', '["properly, to shear off; but used only in the (figuratively) sense of passing rapidly bring, cut off."]', '["v"]', 'properly, to shear off; but used only in the (figuratively) sense of passing rapidly bring, cut off.', 'a primitive root (compare 1494);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1469}/[H1469]', 'lemma', 'heb', 'גּוֹזָל', '["gôwzâl"]', '["a nestling (as being comparatively nude of feathers) young (pigeon)."]', '["n-m"]', 'a nestling (as being comparatively nude of feathers) young (pigeon).', 'or (shortened) גֹזָלlemma גזָל missing vowel, corrected to גֹזָל; from 1497;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1470}/[H1470]', 'lemma', 'heb', 'גּוֹזָן', '["Gôwzân"]', '["Gozan, a province of Assyria Gozan."]', '["n-pr-loc"]', 'Gozan, a province of Assyria Gozan.', 'probably from 1468; a quarry (as a place of cutting stones);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1471}/[H1471]', 'lemma', 'heb', 'גּוֹי', '["gôwy"]', '["a foreign nation; hence, a Gentile; also (figuratively) a troop of animals, or a flight of locusts Gentile, heathen, nation, people."]', '["n-m n-pr-m"]', 'a foreign nation; hence, a Gentile; also (figuratively) a troop of animals, or a flight of locusts Gentile, heathen, nation, people.', 'rarely (shortened) גֹּי; apparently from the same root as 1465 (in the sense of massing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1472}/[H1472]', 'lemma', 'heb', 'גְּוִיָּה', '["gᵉvîyâh"]', '["a body, whether alive or dead (dead) body, carcase, corpse."]', '["n-f"]', 'a body, whether alive or dead (dead) body, carcase, corpse.', 'prolonged for 1465;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1473}/[H1473]', 'lemma', 'heb', 'גּוֹלָה', '["gôwlâh"]', '["exile; concretely and collectively exiles (carried away), captive(-ity), removing."]', '["n-f"]', 'exile; concretely and collectively exiles (carried away), captive(-ity), removing.', 'or (shortened) גֹּלָה; active participle feminine of 1540;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1474}/[H1474]', 'lemma', 'heb', 'גּוֹלָן', '["Gôwlân"]', '["Golan, a place east of the Jordan Golan."]', '["n-pr-loc"]', 'Golan, a place east of the Jordan Golan.', 'from 1473; captive;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1476}/[H1476]', 'lemma', 'heb', 'גּוּנִי', '["Gûwnîy"]', '["Guni, the name of two Israelites Guni."]', '["n-pr-m"]', 'Guni, the name of two Israelites Guni.', 'probably from 1598; protected;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1477}/[H1477]', 'lemma', 'heb', 'גּוּנִי', '["Gûwnîy"]', '["a Gunite (collectively with article prefix) or descendants of Guni Gunites."]', '["a"]', 'a Gunite (collectively with article prefix) or descendants of Guni Gunites.', 'patronymically from 1476;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1478]', 'root', 'heb', 'גָּוַע', '["gâvaʻ"]', '["to breathe out, i.e. (by implication) expire die, be dead, give up the ghost, perish."]', '["v"]', 'to breathe out, i.e. (by implication) expire die, be dead, give up the ghost, perish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1479]', 'root', 'heb', 'גּוּף', '["gûwph"]', '["properly, to hollow or arch, i.e. (figuratively) close; to shut shut."]', '["v"]', 'properly, to hollow or arch, i.e. (figuratively) close; to shut shut.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1480}/[H1480]', 'lemma', 'heb', 'גּוּפָה', '["gûwphâh"]', '["a corpse (as closed to sense) body."]', '["n-f"]', 'a corpse (as closed to sense) body.', 'from 1479;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1481]', 'root', 'heb', 'גּוּר', '["gûwr"]', '["properly, to turn aside from the road (for a lodging or any other purpose), i.e. sojourn (as a guest); also to shrink, fear (as in a strange place); also to gather for hostility (as afraid) abide, assemble, be afraid, dwell, fear, gather (together), inhabitant, remain, sojourn, stand in awe, (be) stranger, × surely."]', '["v"]', 'properly, to turn aside from the road (for a lodging or any other purpose), i.e. sojourn (as a guest); also to shrink, fear (as in a strange place); also to gather for hostility (as afraid) abide, assemble, be afraid, dwell, fear, gather (together), inhabitant, remain, sojourn, stand in awe, (be) stranger, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1482}/[H1482]', 'lemma', 'heb', 'גּוּר', '["gûwr"]', '["a cub (as still abiding in the lair), especially of the lion whelp, young one."]', '["n-m"]', 'a cub (as still abiding in the lair), especially of the lion whelp, young one.', 'or (shortened) גֻּר; perhaps from 1481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1483}/[H1483]', 'lemma', 'heb', 'גּוּר', '["Gûwr"]', '["Gur, a place in Palestine Gur."]', '["n-pr-loc"]', 'Gur, a place in Palestine Gur.', 'the same as 1482;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1484}/[H1484]', 'lemma', 'heb', 'גּוֹר', '["gôwr"]', '["whelp."]', '["n-m"]', 'whelp.', 'or (feminine) גֹּרָה; a variation of 1482');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1485}/[H1485]', 'lemma', 'heb', 'גּוּר־בַּעַל', '["Gûwr-Baʻal"]', '["Gur-Baal, a place in Arabia Gur-baal."]', '["n-pr-loc"]', 'Gur-Baal, a place in Arabia Gur-baal.', 'from 1481 and 1168; dwelling of Baal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1487>', 'opaque', 'heb', 'גּוּשׁ', '["gûwsh"]', '["a mass of earth clod."]', '["n-m"]', 'a mass of earth clod.', 'or rather (by permutation) גִּישׁ; of uncertain derivation;');
