INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1491]', 'root', 'heb', 'גָּזָה', '["gâzâh"]', '["to cut off, i.e. portion out take."]', '["v"]', 'to cut off, i.e. portion out take.', 'a primitive root (akin to 1468);');
