INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1496}/[H1496]', 'lemma', 'heb', 'גָּזִית', '["gâzîyth"]', '["something cut, i.e. dressed stone hewed, hewn stone, wrought."]', '["n-f"]', 'something cut, i.e. dressed stone hewed, hewn stone, wrought.', 'from 1491;');
