INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1498}/[H1498]', 'lemma', 'heb', 'גָּזֵל', '["gâzêl"]', '["robbery, or (concretely) plunder robbery, thing taken away by violence."]', '["n-m"]', 'robbery, or (concretely) plunder robbery, thing taken away by violence.', 'from 1497;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1499}/[H1499]', 'lemma', 'heb', 'גֵּזֶל', '["gêzel"]', '["plunder, i.e. violence violence, violent perverting.. gozal. See 1469."]', '["n-m"]', 'plunder, i.e. violence violence, violent perverting.. gozal. See 1469.', 'from 1497;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1500}/[H1500]', 'lemma', 'heb', 'גְּזֵלָה', '["gᵉzêlâh"]', '["that (he had robbed) (which he took violently away), spoil, violence."]', '["n-f"]', 'that (he had robbed) (which he took violently away), spoil, violence.', 'feminine of 1498 and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1501>', 'opaque', 'heb', 'גָּזָם', '["gâzâm"]', '["a kind of locust palmer-worm."]', '["n-m"]', 'a kind of locust palmer-worm.', 'from an unused root meaning to devour;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1502}/[H1502]', 'lemma', 'heb', 'גַּזָּם', '["Gazzâm"]', '["Gazzam, one of the Nethinim Gazzam."]', '["n-pr-m"]', 'Gazzam, one of the Nethinim Gazzam.', 'from the same as 1501; devourer');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1503>', 'opaque', 'heb', 'גֶּזַע', '["gezaʻ"]', '["the trunk or stump of a tree (as felled or as planted) stem, stock."]', '["n-m"]', 'the trunk or stump of a tree (as felled or as planted) stem, stock.', 'from an unused root meaning to cut down (trees);');
