INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1505}/[H1505]', 'lemma', 'arc', 'גְּזַר', '["gᵉzar"]', '["to quarry; determine cut out, soothsayer."]', '["v"]', 'to quarry; determine cut out, soothsayer.', '(Aramaic) corresponding to 1504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1506}/[H1506]', 'lemma', 'heb', 'גֶּזֶר', '["gezer"]', '["something cut off; a portion part, piece."]', '["n-m"]', 'something cut off; a portion part, piece.', 'from 1504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1507}/[H1507]', 'lemma', 'heb', 'גֶּזֶר', '["Gezer"]', '["Gezer, a place in Palestine Gazer, Gezer."]', '["n-pr-loc"]', 'Gezer, a place in Palestine Gazer, Gezer.', 'the same as 1506;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1508}/[H1508]', 'lemma', 'heb', 'גִּזְרָה', '["gizrâh"]', '["the figure or person (as if cut out); also an inclosure (as separated) polishing, separate place."]', '["n-f"]', 'the figure or person (as if cut out); also an inclosure (as separated) polishing, separate place.', 'feminine of 1506;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1509}/[H1509]', 'lemma', 'heb', 'גְּזֵרָה', '["gᵉzêrâh"]', '["a desert (as separated) not inhabited."]', '["n-f"]', 'a desert (as separated) not inhabited.', 'from 1504;');
