INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1511}/[H1511]', 'lemma', 'heb', 'גִּזְרִי', '["Gizrîy"]', '["a Grizite (collectively) or member of a native tribe in Palestine Gezrites."]', '["a"]', 'a Grizite (collectively) or member of a native tribe in Palestine Gezrites.', '(in the m patrial from 1507; a Gezerite (collectively) or inhabitants of Gezer; but better (as in the text) bytransposition גִּזְרִיxlit Girzîy corrected to Gizrîy; patrial of 1630;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1512}/[H1512]', 'lemma', 'heb', 'גָּחוֹן', '["gâchôwn"]', '["the external abdomen, belly (as the source of the faetus) belly."]', '["n-m"]', 'the external abdomen, belly (as the source of the faetus) belly.', 'probably from 1518; (compare 1521)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1516}/[H1516]', 'lemma', 'heb', 'גַּיְא', '["gayʼ"]', '["a gorge (from its lofty sides; hence, narrow, but not a gully or winter-torrent) valley."]', '["n"]', 'a gorge (from its lofty sides; hence, narrow, but not a gully or winter-torrent) valley.', 'or (shortened) גַּי; probably (by transmutation) from the same root as 1466 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1517}/[H1517]', 'lemma', 'heb', 'גִּיד', '["gîyd"]', '["a thong (as compressing); by analogy, a tendon sinew."]', '["n-m"]', 'a thong (as compressing); by analogy, a tendon sinew.', 'probably from 1464;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1518]', 'root', 'heb', 'גִּיחַ', '["gîyach"]', '["to gush forth (as water), generally to issue break forth, labor to bring forth, come forth, draw up, take out."]', '["v"]', 'to gush forth (as water), generally to issue break forth, labor to bring forth, come forth, draw up, take out.', 'or (shortened) גֹּחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1519}/[H1519]', 'lemma', 'arc', 'גִּיחַ', '["gîyach"]', '["to rush forth strive."]', '["v"]', 'to rush forth strive.', '(Aramaic) or (shortened) גּוּחַ; (Aramaic), corresponding to 1518;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1520}/[H1520]', 'lemma', 'heb', 'גִּיחַ', '["Gîyach"]', '["Giach, a place in Palestine Giah."]', '["n-pr-loc"]', 'Giach, a place in Palestine Giah.', 'from 1518; a fountain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1521}/[H1521]', 'lemma', 'heb', 'גִּיחוֹן', '["Gîychôwn"]', '["Gichon, a river of Paradise; also a valley (or pool) near Jerusalem Gihon."]', '["n-pr-m"]', 'Gichon, a river of Paradise; also a valley (or pool) near Jerusalem Gihon.', 'or (shortened) גִּחוֹן; from 1518; stream;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1522}/[H1522]', 'lemma', 'heb', 'גֵּיחֲזִי', '["Gêychăzîy"]', '["Gechazi, the servant of Elisha Gehazi."]', '["n-pr-m"]', 'Gechazi, the servant of Elisha Gehazi.', 'or גֵּחֲזִי; apparently from 1516 and 2372; valley of a visionary;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1523]', 'root', 'heb', 'גִּיל', '["gîyl"]', '["properly, to spin round (under the influence of any violent emotion), i.e. usually rejoice, or (as cringing) fear be glad, joy, be joyful, rejoice."]', '["v"]', 'properly, to spin round (under the influence of any violent emotion), i.e. usually rejoice, or (as cringing) fear be glad, joy, be joyful, rejoice.', 'or (by permutation) גּוּל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1524}/[H1524]', 'lemma', 'heb', 'גִּיל', '["gîyl"]', '["a revolution (of time, i.e. an age); also joy × exceedingly, gladness, × greatly, joy, rejoice(-ing), sort."]', '["n-m"]', 'a revolution (of time, i.e. an age); also joy × exceedingly, gladness, × greatly, joy, rejoice(-ing), sort.', 'from 1523;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1525}/[H1525]', 'lemma', 'heb', 'גִּילָה', '["gîylâh"]', '["joy joy, rejoicing."]', '["n-f"]', 'joy joy, rejoicing.', 'or גִּילַת; feminine of 1524;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1526}/[H1526]', 'lemma', 'heb', 'גִּילֹנִי', '["Gîylônîy"]', '["a Gilonite or inhabitant of Giloh Gilonite."]', '["a"]', 'a Gilonite or inhabitant of Giloh Gilonite.', 'patrial from 1542;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1528}/[H1528]', 'lemma', 'arc', 'גִּיר', '["gîyr"]', '["lime plaster."]', '["n-m"]', 'lime plaster.', '(Aramaic) corresponding to 1615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1529}/[H1529]', 'lemma', 'heb', 'גֵּישָׁן', '["Gêyshân"]', '["Geshan, an Israelite Geshan."]', '["n-pr-m"]', 'Geshan, an Israelite Geshan.', 'from the same as 1487; lumpish;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1530}/[H1530]', 'lemma', 'heb', 'גַּל', '["gal"]', '["something rolled, i.e. a heap of stone or dung (plural ruins), by analogy, a spring of water (plural waves) billow, heap, spring, wave."]', '["n-m"]', 'something rolled, i.e. a heap of stone or dung (plural ruins), by analogy, a spring of water (plural waves) billow, heap, spring, wave.', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1531}/[H1531]', 'lemma', 'heb', 'גֹּל', '["gôl"]', '["a cup for oil (as round) bowl."]', '["n-m"]', 'a cup for oil (as round) bowl.', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1532>', 'opaque', 'heb', 'גַּלָּב', '["gallâb"]', '["a barber barber."]', '["n-m"]', 'a barber barber.', 'from an unused root meaning to shave;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1533}/[H1533]', 'lemma', 'heb', 'גִּלְבֹּעַ', '["Gilbôaʻ"]', '["Gilboa, a mountain of Palestine Gilboa."]', '["n-pr-loc"]', 'Gilboa, a mountain of Palestine Gilboa.', 'from 1530 and 1158; fountain of ebullition;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1534}/[H1534]', 'lemma', 'heb', 'גַּלְגַּל', '["galgal"]', '["a wheel; by analogy, a whirlwind; also dust (as whirled) heaven, rolling thing, wheel."]', '["n-m"]', 'a wheel; by analogy, a whirlwind; also dust (as whirled) heaven, rolling thing, wheel.', 'by reduplication from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1535}/[H1535]', 'lemma', 'arc', 'גַּלְגַּל', '["galgal"]', '["a wheel wheel."]', '["n-m"]', 'a wheel wheel.', '(Aramaic) corresponding to 1534;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1536}/[H1536]', 'lemma', 'heb', 'גִּלְגָּל', '["gilgâl"]', '["wheel."]', '["n-m"]', 'wheel.', 'a variation of 1534');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1537}/[H1537]', 'lemma', 'heb', 'גִּלְגָּל', '["Gilgâl"]', '["Gilgal, the name of three places in Palestine Gilgal. See also 1019."]', '["n-pr-loc"]', 'Gilgal, the name of three places in Palestine Gilgal. See also 1019.', 'the same as 1536 (with the article as a properly, noun);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1538}/[H1538]', 'lemma', 'heb', 'גֻּלְגֹּלֶת', '["gulgôleth"]', '["a skull (as round); by implication, a head (in enumeration of persons) head, every man, poll, skull."]', '["n-f"]', 'a skull (as round); by implication, a head (in enumeration of persons) head, every man, poll, skull.', 'by reduplication from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1539>', 'opaque', 'heb', 'גֶּלֶד', '["geled"]', '["the (human) skin (as smooth) skin."]', '["n-m"]', 'the (human) skin (as smooth) skin.', 'from an unused root probably meaning to polish;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1540]', 'root', 'heb', 'גָּלָה', '["gâlâh"]', '["to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover."]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1541}/[H1541]', 'lemma', 'arc', 'גְּלָה', '["gᵉlâh"]', '["bring over, carry away, reveal."]', '["v"]', 'bring over, carry away, reveal.', '(Aramaic) or גְּלָא; (Aramaic), corresponding to 1540');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1542}/[H1542]', 'lemma', 'heb', 'גִּלֹה', '["Gilôh"]', '["Giloh, a place in Palestine Giloh."]', '["n-pr-loc"]', 'Giloh, a place in Palestine Giloh.', 'or (fully) גִּילֹה; from 1540; open;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1543}/[H1543]', 'lemma', 'heb', 'גֻּלָּה', '["gullâh"]', '["a fountain, bowl or globe (all as round) bowl, pommel, spring."]', '["n-f"]', 'a fountain, bowl or globe (all as round) bowl, pommel, spring.', 'feminine from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1544}/[H1544]', 'lemma', 'heb', 'גִּלּוּל', '["gillûwl"]', '["properly, a log (as round); by implication, an idol idol."]', '["n-m"]', 'properly, a log (as round); by implication, an idol idol.', 'or (shortened) גִּלֻּל; from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1545}/[H1545]', 'lemma', 'heb', 'גְּלוֹם', '["gᵉlôwm"]', '["clothing (as wrapped) clothes."]', '["n-m"]', 'clothing (as wrapped) clothes.', 'from 1563;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1546}/[H1546]', 'lemma', 'heb', 'גָּלוּת', '["gâlûwth"]', '["captivity; concretely, exiles (collectively) (they that are carried away) captives(-ity)."]', '["n-f"]', 'captivity; concretely, exiles (collectively) (they that are carried away) captives(-ity).', 'feminine from 1540;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1547}/[H1547]', 'lemma', 'arc', 'גָּלוּת', '["gâlûwth"]', '["captivity."]', '["n-f"]', 'captivity.', '(Aramaic) corresponding to 1546');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1548]', 'root', 'heb', 'גָּלַח', '["gâlach"]', '["properly, to be bald, i.e. (causatively) to shave; figuratively to lay waste poll, shave (off)."]', '["v"]', 'properly, to be bald, i.e. (causatively) to shave; figuratively to lay waste poll, shave (off).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1549}/[H1549]', 'lemma', 'heb', 'גִּלָּיוֹן', '["gillâyôwn"]', '["a tablet for writing (as bare); by analogy, a mirror (as a plate) glass, roll."]', '["n-m"]', 'a tablet for writing (as bare); by analogy, a mirror (as a plate) glass, roll.', 'or גִּלְיוֹן; from 1540;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1550}/[H1550]', 'lemma', 'heb', 'גָּלִיל', '["gâlîyl"]', '["a valve of a folding door (as turning); also a ring (as round) folding, ring."]', '["a"]', 'a valve of a folding door (as turning); also a ring (as round) folding, ring.', 'from 1556;');
