INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1552}/[H1552]', 'lemma', 'heb', 'גְלִילָה', '["gᵉlîylâh"]', '["a circuit or region border, coast, country."]', '["n-f"]', 'a circuit or region border, coast, country.', 'feminine of 1550;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1553}/[H1553]', 'lemma', 'heb', 'גְּלִילוֹת', '["Gᵉlîylôwth"]', '["Geliloth, a place in Palestine Geliloth."]', '["n-pr-loc"]', 'Geliloth, a place in Palestine Geliloth.', 'plural of 1552; circles;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1554}/[H1554]', 'lemma', 'heb', 'גַּלִּים', '["Gallîym"]', '["Gallim, a place in Palestine Gallim."]', '["n-pr-loc"]', 'Gallim, a place in Palestine Gallim.', 'plural of 1530; springs;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1555}/[H1555]', 'lemma', 'heb', 'גׇּלְיַת', '["Golyath"]', '["Goljath, a Philistine Goliath."]', '["n-pr-m"]', 'Goljath, a Philistine Goliath.', 'perhaps from 1540; exile;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1556]', 'root', 'heb', 'גָּלַל', '["gâlal"]', '["to roll (literally or figuratively) commit, remove, roll (away, down, together), run down, seek occasion, trust, wallow."]', '["v"]', 'to roll (literally or figuratively) commit, remove, roll (away, down, together), run down, seek occasion, trust, wallow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1557}/[H1557]', 'lemma', 'heb', 'גָּלָל', '["gâlâl"]', '["dung (as in balls) dung."]', '["n-m"]', 'dung (as in balls) dung.', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1558}/[H1558]', 'lemma', 'heb', 'גָּלָל', '["gâlâl"]', '["a circumstance (as rolled around); only used adverbially, on account of because of, for (sake)."]', '["n-m"]', 'a circumstance (as rolled around); only used adverbially, on account of because of, for (sake).', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1559}/[H1559]', 'lemma', 'heb', 'גָּלָל', '["Gâlâl"]', '["Galal, the name of two Israelites Galal."]', '["n-pr-m"]', 'Galal, the name of two Israelites Galal.', 'from 1556, in the sense of 1560; great;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1560}/[H1560]', 'lemma', 'arc', 'גְּלָל', '["gᵉlâl"]', '["weight or size (as if rolled) great."]', '["a"]', 'weight or size (as if rolled) great.', '(Aramaic) from a root corresponding to 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1561}/[H1561]', 'lemma', 'heb', 'גֵּלֶל', '["gêlel"]', '["dung (plural balls of dung) dung."]', '["n-m"]', 'dung (plural balls of dung) dung.', 'a variation of 1557;');
