INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1563]', 'root', 'heb', 'גָּלַם', '["gâlam"]', '["to fold wrap together."]', '["v"]', 'to fold wrap together.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1564}/[H1564]', 'lemma', 'heb', 'גֹּלֶם', '["gôlem"]', '["a wrapped (and unformed mass, i.e. as the embryo) substance yet being unperfect."]', '["n-m"]', 'a wrapped (and unformed mass, i.e. as the embryo) substance yet being unperfect.', 'from 1563;');
