INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1566]', 'root', 'heb', 'גָּלַע', '["gâlaʻ"]', '["to be obstinate (inter-) meddle (with)."]', '["v"]', 'to be obstinate (inter-) meddle (with).', 'a primitive root;');
