INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1633]', 'root', 'heb', 'גָּרַם', '["gâram"]', '["(causative) to bone, i.e. denude (by extensive, craunch) the bones gnaw the bones, break."]', '["v"]', '(causative) to bone, i.e. denude (by extensive, craunch) the bones gnaw the bones, break.', 'a primitive root; to be spare or skeleton-like; used only as a denominative from 1634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1634}/[H1634]', 'lemma', 'heb', 'גֶּרֶם', '["gerem"]', '["a bone (as the skeleton of the body); hence, self, i.e. (figuratively) very bone, strong, top."]', '["n-m"]', 'a bone (as the skeleton of the body); hence, self, i.e. (figuratively) very bone, strong, top.', 'from 1633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1635}/[H1635]', 'lemma', 'arc', 'גֶּרֶם', '["gerem"]', '["a bone bone."]', '["n-m"]', 'a bone bone.', '(Aramaic) corresponding to 1634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1636}/[H1636]', 'lemma', 'heb', 'גַּרְמִי', '["Garmîy"]', '["bony, i.e. strong Garmite."]', '["a"]', 'bony, i.e. strong Garmite.', 'from 1634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1638]', 'root', 'heb', 'גָּרַס', '["gâraç"]', '["to crush; also (intransitively and figuratively) to dissolve break."]', '["v"]', 'to crush; also (intransitively and figuratively) to dissolve break.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1639]', 'root', 'heb', 'גָּרַע', '["gâraʻ"]', '["to scrape off; by implication, to shave, remove, lessen, withhold abate, clip, (di-) minish, do (take) away, keep back, restrain, make small, withdraw."]', '["v"]', 'to scrape off; by implication, to shave, remove, lessen, withhold abate, clip, (di-) minish, do (take) away, keep back, restrain, make small, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1640]', 'root', 'heb', 'גָּרַף', '["gâraph"]', '["to bear off violently sweep away."]', '["v"]', 'to bear off violently sweep away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1641]', 'root', 'heb', 'גָּרַר', '["gârar"]', '["to drag off roughly; by implication, to bring up the cud (i.e. ruminate); by analogy, to saw catch, chew, × continuing, destroy, saw."]', '["v"]', 'to drag off roughly; by implication, to bring up the cud (i.e. ruminate); by analogy, to saw catch, chew, × continuing, destroy, saw.', 'a primitive root;');
