INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1644]', 'root', 'heb', 'גָּרַשׁ', '["gârash"]', '["to drive out from a possession; especially to expatriate or divorce cast up (out), divorced (woman), drive away (forth, out), expel, × surely put away, trouble, thrust out."]', '["v"]', 'to drive out from a possession; especially to expatriate or divorce cast up (out), divorced (woman), drive away (forth, out), expel, × surely put away, trouble, thrust out.', 'a primitive root;');
