INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1689}/[H1689]', 'lemma', 'heb', 'דִּבְלָה', '["Diblâh"]', '["Diblah, a place in Syria Diblath."]', '["n-pr-loc"]', 'Diblah, a place in Syria Diblath.', 'probably an orthographical error for 7247;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1691}/[H1691]', 'lemma', 'heb', 'דִּבְלַיִם', '["Diblayim"]', '["Diblajim, a symbolic name Diblaim."]', '["n-pr-m"]', 'Diblajim, a symbolic name Diblaim.', 'dual from the masculine of 1690; two cakes;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1692]', 'root', 'heb', 'דָּבַק', '["dâbaq"]', '["properly, to impinge, i.e. cling or adhere; figuratively, to catch by pursuit abide fast, cleave (fast together), follow close (hard after), be joined (together), keep (fast), overtake, pursue hard, stick, take."]', '["v"]', 'properly, to impinge, i.e. cling or adhere; figuratively, to catch by pursuit abide fast, cleave (fast together), follow close (hard after), be joined (together), keep (fast), overtake, pursue hard, stick, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1693}/[H1693]', 'lemma', 'arc', 'דְּבַק', '["dᵉbaq"]', '["to stick to cleave."]', '["v"]', 'to stick to cleave.', '(Aramaic) corresponding to 1692;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1694}/[H1694]', 'lemma', 'heb', 'דֶּבֶק', '["debeq"]', '["a joint; by implication, solder joint, solder."]', '["n-m"]', 'a joint; by implication, solder joint, solder.', 'from 1692;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1695}/[H1695]', 'lemma', 'heb', 'דָּבֵק', '["dâbêq"]', '["adhering cleave, joining, stick closer."]', '["a"]', 'adhering cleave, joining, stick closer.', 'from 1692;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1696]', 'root', 'heb', 'דָבַר', '["dâbar"]', '["perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work."]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697}/[H1697]', 'lemma', 'heb', 'דָּבָר', '["dâbâr"]', '["a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work."]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1698}/[H1698]', 'lemma', 'heb', 'דֶּבֶר', '["deber"]', '["a pestilence murrain, pestilence, plague."]', '["n-m"]', 'a pestilence murrain, pestilence, plague.', 'from 1696 (in the sense of destroying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1699}/[H1699]', 'lemma', 'heb', 'דֹּבֶר', '["dôber"]', '["a pasture (from its arrangement of the flock) fold, manner."]', '["n-m"]', 'a pasture (from its arrangement of the flock) fold, manner.', 'from 1696 (in its original sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1700}/[H1700]', 'lemma', 'heb', 'דִּבְרָה', '["dibrâh"]', '["a reason, suit or style cause, end, estate, order, regard."]', '["n-m"]', 'a reason, suit or style cause, end, estate, order, regard.', 'feminine of 1697;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1701}/[H1701]', 'lemma', 'arc', 'דִּבְרָה', '["dibrâh"]', '["intent, sake."]', '["n-f"]', 'intent, sake.', '(Aramaic) corresponding to 1700');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1702}/[H1702]', 'lemma', 'heb', 'דֹּבְרָה', '["dôbᵉrâh"]', '["a raft float."]', '["n-f"]', 'a raft float.', 'feminine active participle of 1696 in the sense of driving (compare 1699);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1703}/[H1703]', 'lemma', 'heb', 'דַּבָּרָה', '["dabbârâh"]', '["a word word."]', '["n-f"]', 'a word word.', 'intensive from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1704}/[H1704]', 'lemma', 'heb', 'דִּבְרִי', '["Dibrîy"]', '["Dibri, an Israelite Dibri."]', '["n-pr-m"]', 'Dibri, an Israelite Dibri.', 'from 1697; wordy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1705}/[H1705]', 'lemma', 'heb', 'דֲּבְרַת', '["Dăbrath"]', '["Daberath, a place in Palestine Dabareh, Daberath."]', '["n-pr-loc"]', 'Daberath, a place in Palestine Dabareh, Daberath.', 'from 1697 (perhaps in the sense of 1699);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1707}/[H1707]', 'lemma', 'heb', 'דַּבֶּשֶׁת', '["dabbesheth"]', '["a sticky mass, i.e. the hump of a camel hunch (of a camel)."]', '["n-f"]', 'a sticky mass, i.e. the hump of a camel hunch (of a camel).', 'intensive from the same as 1706;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1708}/[H1708]', 'lemma', 'heb', 'דַּבֶּשֶׁת', '["Dabbesheth"]', '["Dabbesheth, a place in Palestine Dabbesheth."]', '["n-pr-loc"]', 'Dabbesheth, a place in Palestine Dabbesheth.', 'the same as 1707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1709}/[H1709]', 'lemma', 'heb', 'דָּג', '["dâg"]', '["a fish (often used collectively) fish."]', '["n-m"]', 'a fish (often used collectively) fish.', 'or (fully) דָּאג; (Nehemiah 13:16), from 1711; a fish (as prolific); or perhaps rather from 1672 (as timid); but still better from 1672 (in the sense of squirming, i.e. moving by the vibratory action of the tail);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1710}/[H1710]', 'lemma', 'heb', 'דָּגָה', '["dâgâh"]', '["fish."]', '["n-f"]', 'fish.', 'feminine of 1709, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1711]', 'root', 'heb', 'דָּגָה', '["dâgâh"]', '["to spawn, i.e. become numerous grow."]', '["v"]', 'to spawn, i.e. become numerous grow.', 'a primitive root; to move rapidly; used only as a denominative from 1709;');
