INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1713]', 'root', 'heb', 'דָּגַל', '["dâgal"]', '["to flaunt, i.e. raise a flag; figuratively, to be conspicuous (set up, with) banners, chiefest."]', '["v"]', 'to flaunt, i.e. raise a flag; figuratively, to be conspicuous (set up, with) banners, chiefest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1714}/[H1714]', 'lemma', 'heb', 'דֶּגֶל', '["degel"]', '["a flag banner, standard."]', '["n-m"]', 'a flag banner, standard.', 'from 1713;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1715}/[H1715]', 'lemma', 'heb', 'דָּגָן', '["dâgân"]', '["properly, increase, i.e. grain corn (floor), wheat."]', '["n-m"]', 'properly, increase, i.e. grain corn (floor), wheat.', 'from 1711;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1716]', 'root', 'heb', 'דָּגַר', '["dâgar"]', '["to brood over eggs or young gather, sit."]', '["v"]', 'to brood over eggs or young gather, sit.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1717}/[H1717]', 'lemma', 'heb', 'דַּד', '["dad"]', '["the breast (as the seat of love, or from its shape) breast, teat."]', '["n-m"]', 'the breast (as the seat of love, or from its shape) breast, teat.', 'apparently from the same as 1730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1719>', 'opaque', 'heb', 'דְּדָן', '["Dᵉdân"]', '["Dedan, the name of two Cushites and of their territory Dedan."]', '["n-pr-m n-pr-loc"]', 'Dedan, the name of two Cushites and of their territory Dedan.', 'or (prolonged) דְּדָנֶה; (Ezekiel 25:13), of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1720}/[H1720]', 'lemma', 'heb', 'דְּדָנִים', '["Dᵉdânîym"]', '["Dedanites, the descendants or inhabitants of Dedan Dedanim."]', '["a"]', 'Dedanites, the descendants or inhabitants of Dedan Dedanim.', 'plural of 1719 (as patrial);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1721>', 'opaque', 'heb', 'דֹּדָנִים', '["Dôdânîym"]', '["Dodanites, or descendants of a son of Javan Dodanim."]', '["n-pr-m"]', 'Dodanites, or descendants of a son of Javan Dodanim.', 'or (by orthographical error) רֹדָנִים (1 Chronicles 1:7); a plural of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1722}/[H1722]', 'lemma', 'arc', 'דְּהַב', '["dᵉhab"]', '["gold gold(-en)."]', '["n-m"]', 'gold gold(-en).', '(Aramaic) corresponding to 2091;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1723>', 'opaque', 'heb', 'דַּהֲוָא', '["Dahăvâʼ"]', '["Dahava, a people colonized in Samaria Dehavites."]', '["n"]', 'Dahava, a people colonized in Samaria Dehavites.', '(Aramaic) of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1724]', 'root', 'heb', 'דָּהַם', '["dâham"]', '["to be dumb, i.e. (figuratively) dumbfounded astonished."]', '["v"]', 'to be dumb, i.e. (figuratively) dumbfounded astonished.', 'a primitive root (compare 1740);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1725]', 'root', 'heb', 'דָּהַר', '["dâhar"]', '["to curvet or move irregularly pause."]', '["v"]', 'to curvet or move irregularly pause.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1726}/[H1726]', 'lemma', 'heb', 'דַּהֲהַר', '["dahăhar"]', '["a gallop pransing."]', '["n-f"]', 'a gallop pransing.', 'by reduplication from 1725;');
