INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1730>', 'opaque', 'heb', 'דּוֹד', '["dôwd"]', '["(figuratively) to love; by implication, a love-token, lover, friend; specifically an uncle (well-) beloved, father''s brother, love, uncle."]', '["n-m"]', '(figuratively) to love; by implication, a love-token, lover, friend; specifically an uncle (well-) beloved, father''s brother, love, uncle.', 'or (shortened) דֹּד; from an unused root meaning properly, to boil, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1731}/[H1731]', 'lemma', 'heb', 'דּוּד', '["dûwd"]', '["a pot (for boiling); also (by resemblance of shape) a basket basket, caldron, kettle, (seething) pot."]', '["n-m"]', 'a pot (for boiling); also (by resemblance of shape) a basket basket, caldron, kettle, (seething) pot.', 'from the same as 1730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1732}/[H1732]', 'lemma', 'heb', 'דָּוִד', '["Dâvid"]', '["David, the youngest son of Jesse David."]', '["n-pr-m"]', 'David, the youngest son of Jesse David.', 'rarely (fully); דָּוִיד; from the same as 1730; loving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1733}/[H1733]', 'lemma', 'heb', 'דּוֹדָה', '["dôwdâh"]', '["an aunt aunt, father''s sister, uncle''s wife."]', '["n-f"]', 'an aunt aunt, father''s sister, uncle''s wife.', 'feminine of 1730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1734}/[H1734]', 'lemma', 'heb', 'דּוֹדוֹ', '["Dôwdôw"]', '["Dodo, the name of three Israelites Dodo."]', '["n-pr-m"]', 'Dodo, the name of three Israelites Dodo.', 'from 1730; loving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1735}/[H1735]', 'lemma', 'heb', 'דּוֹדָוָהוּ', '["Dôwdâvâhûw"]', '["Dodavah, an Israelite Dodavah."]', '["n-pr-m"]', 'Dodavah, an Israelite Dodavah.', 'from 1730 and 3050; love of Jah;');
