INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1737}/[H1737]', 'lemma', 'heb', 'דּוֹדַי', '["Dôwday"]', '["Dodai, an Israelite Dodai."]', '["n-pr-m"]', 'Dodai, an Israelite Dodai.', 'formed like 1736; amatory;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1738]', 'root', 'heb', 'דָּוָה', '["dâvâh"]', '["to be sick (as if in menstruation) infirmity."]', '["v"]', 'to be sick (as if in menstruation) infirmity.', 'a primitive root;');
