INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1740]', 'root', 'heb', 'דּוּחַ', '["dûwach"]', '["to thrust away; figuratively, to cleanse cast out, purge, wash."]', '["v"]', 'to thrust away; figuratively, to cleanse cast out, purge, wash.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1741}/[H1741]', 'lemma', 'heb', 'דְּוַי', '["dᵉvay"]', '["sickness; figuratively, loathing languishing, sorrowful."]', '["n-m"]', 'sickness; figuratively, loathing languishing, sorrowful.', 'from 1739;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1742}/[H1742]', 'lemma', 'heb', 'דַּוָּי', '["davvây"]', '["sick; figuratively, troubled faint."]', '["a"]', 'sick; figuratively, troubled faint.', 'from 1739;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1743]', 'root', 'heb', 'דּוּךְ', '["dûwk"]', '["to bruise in a mortar beat."]', '["v"]', 'to bruise in a mortar beat.', 'a primitive root;');
