INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1755}/[H1755]', 'lemma', 'heb', 'דּוֹר', '["dôwr"]', '["properly, a revolution of time, i.e. an age or generation; also a dwelling age, × evermore, generation, (n-) ever, posterity."]', '["n-m"]', 'properly, a revolution of time, i.e. an age or generation; also a dwelling age, × evermore, generation, (n-) ever, posterity.', 'or (shortened) דֹּר; from 1752;');
