INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1758]', 'root', 'heb', 'דּוּשׁ', '["dûwsh"]', '["to trample or thresh break, tear, thresh, tread out (down), at grass (Jeremiah 50:11, by mistake for 1877)."]', '["v"]', 'to trample or thresh break, tear, thresh, tread out (down), at grass (Jeremiah 50:11, by mistake for 1877).', 'or דּוֹשׁ; or דִּישׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1759}/[H1759]', 'lemma', 'arc', 'דּוּשׁ', '["dûwsh"]', '["to trample tread down."]', '["v"]', 'to trample tread down.', '(Aramaic) corresponding to 1758;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1760]', 'root', 'heb', 'דָּחָה', '["dâchâh"]', '["to push down chase, drive away (on), overthrow, outcast, × sore, thrust, totter."]', '["v"]', 'to push down chase, drive away (on), overthrow, outcast, × sore, thrust, totter.', 'or דָּחַח; (Jeremiah 23:12), a primitive root;');
