INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1817}/[H1817]', 'lemma', 'heb', 'דֶּלֶת', '["deleth"]', '["something swinging, i.e. the valve of a door door (two-leaved), gate, leaf, lid. (Psalm 141:3)."]', '["n-m n-f"]', 'something swinging, i.e. the valve of a door door (two-leaved), gate, leaf, lid. (Psalm 141:3).', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1818}/[H1818]', 'lemma', 'heb', 'דָּם', '["dâm"]', '["blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent."]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1819]', 'root', 'heb', 'דָּמָה', '["dâmâh"]', '["to compare; by implication, to resemble, liken, consider compare, devise, (be) like(-n), mean, think, use similitudes."]', '["v"]', 'to compare; by implication, to resemble, liken, consider compare, devise, (be) like(-n), mean, think, use similitudes.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1820]', 'root', 'heb', 'דָּמָה', '["dâmâh"]', '["to be dumb or silent; hence, to fail or perish; trans. to destroy cease, be cut down (off), destroy, be brought to silence, be undone, × utterly."]', '["v"]', 'to be dumb or silent; hence, to fail or perish; trans. to destroy cease, be cut down (off), destroy, be brought to silence, be undone, × utterly.', 'a primitive root;');
