INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1822}/[H1822]', 'lemma', 'heb', 'דֻּמָּה', '["dummâh"]', '["desolation; concretely, desolate destroy."]', '["n-f"]', 'desolation; concretely, desolate destroy.', 'from 1820;');
