INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1826]', 'root', 'heb', 'דָּמַם', '["dâmam"]', '["to be dumb; by implication, to be astonished, to stop; also to perish cease, be cut down (off), forbear, hold peace, quiet self, rest, be silent, keep (put to) silence, be (stand) still, tarry, wait."]', '["v"]', 'to be dumb; by implication, to be astonished, to stop; also to perish cease, be cut down (off), forbear, hold peace, quiet self, rest, be silent, keep (put to) silence, be (stand) still, tarry, wait.', 'a primitive root (compare 1724, 1820);');
