INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1863>', 'opaque', 'heb', 'דַּרְדַּר', '["dardar"]', '["a thorn thistle."]', '["n-m"]', 'a thorn thistle.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1866}/[H1866]', 'lemma', 'heb', 'דְּרוֹר', '["dᵉrôwr"]', '["the swift, a kind of swallow swallow."]', '["n-f"]', 'the swift, a kind of swallow swallow.', 'the same as 1865, applied to a bird;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1867}/[H1867]', 'lemma', 'heb', 'דָּֽרְיָוֵשׁ', '["Dârᵉyâvêsh"]', '["Darejavesh, a title (rather than name) of several Persian kings Darius."]', '["n-pr-m"]', 'Darejavesh, a title (rather than name) of several Persian kings Darius.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1868}/[H1868]', 'lemma', 'arc', 'דָּֽרְיָוֵשׁ', '["Dârᵉyâvêsh"]', '["Darius."]', '["n-pr-m"]', 'Darius.', '(Aramaic) corresponding to 1867');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1869]', 'root', 'heb', 'דָּרַךְ', '["dârak"]', '["to tread; by implication, to walk; also to string a bow (by treading on it in bending) archer, bend, come, draw, go (over), guide, lead (forth), thresh, tread (down), walk."]', '["v"]', 'to tread; by implication, to walk; also to string a bow (by treading on it in bending) archer, bend, come, draw, go (over), guide, lead (forth), thresh, tread (down), walk.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870}/[H1870]', 'lemma', 'heb', 'דֶּרֶךְ', '["derek"]', '["a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever)."]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1872}/[H1872]', 'lemma', 'arc', 'דְּרַע', '["dᵉraʻ"]', '["an arm arm."]', '["n-f"]', 'an arm arm.', '(Aramaic) corresponding to 2220;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1873}/[H1873]', 'lemma', 'heb', 'דָּרַע', '["Dâraʻ"]', '["Dara, an Israelite Dara."]', '["n-pr-m"]', 'Dara, an Israelite Dara.', 'probably a contraction from 1862;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1875]', 'root', 'heb', 'דָּרַשׁ', '["dârash"]', '["properly, to tread or frequent; usually to follow (for pursuit or search); by implication, to seek or ask; specifically to worship ask, × at all, care for, × diligently, inquire, make inquisition, (necro-) mancer, question, require, search, seek (for, out), × surely."]', '["v"]', 'properly, to tread or frequent; usually to follow (for pursuit or search); by implication, to seek or ask; specifically to worship ask, × at all, care for, × diligently, inquire, make inquisition, (necro-) mancer, question, require, search, seek (for, out), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1876]', 'root', 'heb', 'דָּשָׁא', '["dâshâʼ"]', '["to sprout bring forth, spring."]', '["v"]', 'to sprout bring forth, spring.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1877}/[H1877]', 'lemma', 'heb', 'דֶּשֶׁא', '["desheʼ"]', '["a sprout; by analogy, grass (tender) grass, green, (tender) herb."]', '["n-m"]', 'a sprout; by analogy, grass (tender) grass, green, (tender) herb.', 'from 1876;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1878]', 'root', 'heb', 'דָּשֵׁן', '["dâshên"]', '["to be fat; transitively, to fatten (or regard as fat); specifically to anoint; figuratively, to satisfy; to remove (fat) ashes (of sacrifices) accept, anoint, take away the (receive) ashes (from), make (wax) fat."]', '["v"]', 'to be fat; transitively, to fatten (or regard as fat); specifically to anoint; figuratively, to satisfy; to remove (fat) ashes (of sacrifices) accept, anoint, take away the (receive) ashes (from), make (wax) fat.', 'a primitive root; also denominatively (from 1880)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1879}/[H1879]', 'lemma', 'heb', 'דָּשֵׁן', '["dâshên"]', '["fat; figuratively, rich, fertile fat."]', '["a"]', 'fat; figuratively, rich, fertile fat.', 'from 1878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1880}/[H1880]', 'lemma', 'heb', 'דֶּשֶׁן', '["deshen"]', '["the fat; abstractly fatness, i.e. (figuratively) abundance; specifically the (fatty) ashes of sacrifices ashes, fatness."]', '["n-m"]', 'the fat; abstractly fatness, i.e. (figuratively) abundance; specifically the (fatty) ashes of sacrifices ashes, fatness.', 'from 1878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1882}/[H1882]', 'lemma', 'arc', 'דָּת', '["dâth"]', '["decree, law."]', '["n-f"]', 'decree, law.', '(Aramaic) corresponding to 1881;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1883}/[H1883]', 'lemma', 'arc', 'דֶּתֶא', '["detheʼ"]', '["tender grass."]', '["n-m"]', 'tender grass.', '(Aramaic) corresponding to 1877');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1884}/[H1884]', 'lemma', 'arc', 'דְּתָבָר', '["dᵉthâbâr"]', '["meaning one skilled in law; a judge counsellor."]', '["n-m"]', 'meaning one skilled in law; a judge counsellor.', '(Aramaic) of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1886>', 'opaque', 'heb', 'דֹּתָן', '["Dôthân"]', '["Dothan, a place in Palestine Dothan. h"]', '["n-pr-loc"]', 'Dothan, a place in Palestine Dothan. h', 'or (Aramaic dual) דֹּתַיִן; (Genesis 37:17), of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1888}/[H1888]', 'lemma', 'arc', 'הֵא', '["hêʼ"]', '["even, lo."]', '["dp"]', 'even, lo.', '(Aramaic) or הָא; (Aramaic), corresponding to 1887');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1889}/[H1889]', 'lemma', 'heb', 'הֶאָח', '["heʼâch"]', '["aha! ah, aha, ha."]', '["inj"]', 'aha! ah, aha, ha.', 'from 1887 and 253;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1890}/[H1890]', 'lemma', 'heb', 'הַבְהָב', '["habhâb"]', '["gift (in sacrifice), i.e. holocaust offering."]', '["n-m"]', 'gift (in sacrifice), i.e. holocaust offering.', 'by reduplication from 3051;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1891]', 'root', 'heb', 'הָבַל', '["hâbal"]', '["to be vain in act, word, or expectation; specifically to lead astray be (become, make) vain."]', '["v"]', 'to be vain in act, word, or expectation; specifically to lead astray be (become, make) vain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1892}/[H1892]', 'lemma', 'heb', 'הֶבֶל', '["hebel"]', '["emptiness or vanity; figuratively, something transitory and unsatisfactory; often used as an adverb × altogether, vain, vanity."]', '["n-m"]', 'emptiness or vanity; figuratively, something transitory and unsatisfactory; often used as an adverb × altogether, vain, vanity.', 'or (rarely in the abs.) הֲבֵל; from 1891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1893}/[H1893]', 'lemma', 'heb', 'הֶבֶל', '["Hebel"]', '["Hebel, the son of Adam Abel."]', '["n-pr-m"]', 'Hebel, the son of Adam Abel.', 'the same as 1892;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1894>', 'opaque', 'heb', 'הֹבֶן', '["hôben"]', '["ebony ebony."]', '["n-m"]', 'ebony ebony.', 'only in plural, from an unused root meaning to be hard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1895]', 'root', 'heb', 'הָבַר', '["hâbar"]', '["to be a horoscopist (astro-) loger."]', '["v"]', 'to be a horoscopist (astro-) loger.', 'a primitive root of uncertain (perhaps foreign) derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1897]', 'root', 'heb', 'הָגָה', '["hâgâh"]', '["to murmur (in pleasure or anger); by implication, to ponder imagine, meditate, mourn, mutter, roar, × sore, speak, study, talk, utter."]', '["v"]', 'to murmur (in pleasure or anger); by implication, to ponder imagine, meditate, mourn, mutter, roar, × sore, speak, study, talk, utter.', 'a primitive root (compare 1901);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1898]', 'root', 'heb', 'הָגָה', '["hâgâh"]', '["to remove stay, stay away."]', '["v"]', 'to remove stay, stay away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1899}/[H1899]', 'lemma', 'heb', 'הֶגֶה', '["hegeh"]', '["a muttering (in sighing, thought, or as thunder) mourning, sound, tale."]', '["n-m"]', 'a muttering (in sighing, thought, or as thunder) mourning, sound, tale.', 'from 1897;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1900}/[H1900]', 'lemma', 'heb', 'הָגוּת', '["hâgûwth"]', '["musing meditation."]', '["n-f"]', 'musing meditation.', 'from 1897;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1901>', 'opaque', 'heb', 'הָגִיג', '["hâgîyg"]', '["properly, a murmur, i.e. complaint meditation, musing."]', '["n-m"]', 'properly, a murmur, i.e. complaint meditation, musing.', 'from an unused root akin to 1897;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1902}/[H1902]', 'lemma', 'heb', 'הִגָּיוֹן', '["higgâyôwn"]', '["a murmuring sound, i.e. a musical notation (probably similar to the modern affettuoso to indicate solemnity of movement); by implication, a machination device, Higgaion, meditation, solemn sound."]', '["n-m"]', 'a murmuring sound, i.e. a musical notation (probably similar to the modern affettuoso to indicate solemnity of movement); by implication, a machination device, Higgaion, meditation, solemn sound.', 'intensive from 1897;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1905}/[H1905]', 'lemma', 'heb', 'הַגְרִי', '["Hagrîy"]', '["a Hagrite or member of a certain Arabian clan Hagarene, Hagarite, Haggeri."]', '["n-pr"]', 'a Hagrite or member of a certain Arabian clan Hagarene, Hagarite, Haggeri.', 'or (prolonged) הַגְרִיאxlit Hagrîʼ corrected to Hagrîyʼ; perhaps patronymically from 1904;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1906}/[H1906]', 'lemma', 'heb', 'הֵד', '["hêd"]', '["a shout sounding again."]', '["n-m"]', 'a shout sounding again.', 'for 1959;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1907>', 'opaque', 'arc', 'הַדָּבָר', '["haddâbâr"]', '["a vizier counsellor."]', '["n-m"]', 'a vizier counsellor.', '(Aramaic) probably of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1908>', 'opaque', 'heb', 'הֲדַד', '["Hădad"]', '["Hadad, the name of an idol, and of several kings of Edom Hadad."]', '["n-pr-m"]', 'Hadad, the name of an idol, and of several kings of Edom Hadad.', 'probably of foreign origin (compare 111);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1909}/[H1909]', 'lemma', 'heb', 'הֲדַדְעֶזֶר', '["Hădadʻezer"]', '["Hadadezer, a Syrian king Hadadezer. Compare 1928."]', '["n-pr-m"]', 'Hadadezer, a Syrian king Hadadezer. Compare 1928.', 'from 1908 and 5828; Hadad (is his) help;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1910}/[H1910]', 'lemma', 'heb', 'הֲדַדְרִמּוֹן', '["Hădadrimmôwn"]', '["Hadad-Rimmon, a place in Palestine Hadad-rimmon."]', '["n-pr-loc"]', 'Hadad-Rimmon, a place in Palestine Hadad-rimmon.', 'from 1908 and 7417;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1911]', 'root', 'heb', 'הָדָה', '["hâdâh"]', '["to stretch forth the hand put."]', '["v"]', 'to stretch forth the hand put.', 'a primitive root (compare 3034);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1912>', 'opaque', 'heb', 'הֹדוּ', '["Hôdûw"]', '["Hodu (i.e. Hindustan) India."]', '["n-pr-loc"]', 'Hodu (i.e. Hindustan) India.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1913}/[H1913]', 'lemma', 'heb', 'הֲדוֹרָם', '["Hădôwrâm"]', '["Hadoram, a son of Joktan, and the tribe descended from him Hadoram."]', '["n-pr-m"]', 'Hadoram, a son of Joktan, and the tribe descended from him Hadoram.', 'or הֲדֹרָם; probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1915]', 'root', 'heb', 'הָדַךְ', '["hâdak"]', '["to crush with the foot tread down."]', '["v"]', 'to crush with the foot tread down.', 'a primitive root (compare 1854);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1917}/[H1917]', 'lemma', 'arc', 'הַדָּם', '["haddâm"]', '["something stamped to pieces, i.e. a bit piece."]', '["n-m"]', 'something stamped to pieces, i.e. a bit piece.', '(Aramaic) from a root corresponding to that of 1916;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1919}/[H1919]', 'lemma', 'heb', 'הֲדַסָּה', '["Hădaççâh"]', '["Hadassah (or Esther) Hadassah."]', '["n-pr-f"]', 'Hadassah (or Esther) Hadassah.', 'feminine of 1918;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1920]', 'root', 'heb', 'הָדַף', '["hâdaph"]', '["to push away or down cast away (out), drive, expel, thrust (away)."]', '["v"]', 'to push away or down cast away (out), drive, expel, thrust (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1921]', 'root', 'heb', 'הָדַר', '["hâdar"]', '["to swell up (literally or figuratively, active or passive); by implication, to favor or honour, be high or proud countenance, crooked place, glorious, honour, put forth."]', '["v"]', 'to swell up (literally or figuratively, active or passive); by implication, to favor or honour, be high or proud countenance, crooked place, glorious, honour, put forth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1922}/[H1922]', 'lemma', 'arc', 'הֲדַר', '["hădar"]', '["to magnify (figuratively) glorify, honour."]', '["v"]', 'to magnify (figuratively) glorify, honour.', '(Aramaic) corresponding to 1921;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1923}/[H1923]', 'lemma', 'arc', 'הֲדַר', '["hădar"]', '["magnificence honour, majesty."]', '["n-m"]', 'magnificence honour, majesty.', '(Aramaic) from 1922;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1924}/[H1924]', 'lemma', 'heb', 'הֲדַר', '["Hădar"]', '["Hadar, an Edomite Hadar."]', '["n-pr-m"]', 'Hadar, an Edomite Hadar.', 'the same as 1926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1925}/[H1925]', 'lemma', 'heb', 'הֶדֶר', '["heder"]', '["honour; used (figuratively) for the capital city (Jerusalem) glory."]', '["n-m"]', 'honour; used (figuratively) for the capital city (Jerusalem) glory.', 'from 1921;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1926}/[H1926]', 'lemma', 'heb', 'הָדָר', '["hâdâr"]', '["magnificence, i.e. ornament or splendor beauty, comeliness, excellency, glorious, glory, goodly, honour, majesty."]', '["n-m"]', 'magnificence, i.e. ornament or splendor beauty, comeliness, excellency, glorious, glory, goodly, honour, majesty.', 'from 1921;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1927}/[H1927]', 'lemma', 'heb', 'הֲדָרָה', '["hădârâh"]', '["decoration beauty, honour."]', '["n-f"]', 'decoration beauty, honour.', 'feminine of 1926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1928}/[H1928]', 'lemma', 'heb', 'הֲדַרְעֶזֶר', '["Hădarʻezer"]', '["Hadarezer, a Syrian king Hadarezer."]', '["n-pr-m"]', 'Hadarezer, a Syrian king Hadarezer.', 'from 1924 and 5828; Hadar (i.e. Hadad, 1908) is his help; (i.e. Hadadezer, 1909)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1929}/[H1929]', 'lemma', 'heb', 'הָהּ', '["hâhh"]', '["ah! expressing grief woe worth."]', '["inj"]', 'ah! expressing grief woe worth.', 'a shortened form of 162;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1930}/[H1930]', 'lemma', 'heb', 'הוֹ', '["hôw"]', '["oh! alas."]', '["inj"]', 'oh! alas.', 'by permutation from 1929;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1931]', 'root', 'heb', 'הוּא', '["hûwʼ"]', '["he (she or it); only expressed when emphatic or without a verb; also (intensively) self, or (especially with the article) the same; sometimes (as demonstrative) this or that; occasionally (instead of copula) as or are he, as for her, him(-self), it, the same, she (herself), such, that (...it), these, they, this, those, which (is), who."]', '["p"]', 'he (she or it); only expressed when emphatic or without a verb; also (intensively) self, or (especially with the article) the same; sometimes (as demonstrative) this or that; occasionally (instead of copula) as or are he, as for her, him(-self), it, the same, she (herself), such, that (...it), these, they, this, those, which (is), who.', 'of which the feminine (beyond the Pentateuch) is הִיא; he a primitive word, the third person pronoun singular;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1932}/[H1932]', 'lemma', 'arc', 'הוּא', '["hûwʼ"]', '["× are, it, this."]', '["p"]', '× are, it, this.', '(Aramaic) or (feminine) הִיא; (Aramaic), corresponding to 1931');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1933]', 'root', 'heb', 'הָוָא', '["hâvâʼ"]', '["to be (in the sense of existence) be, × have."]', '["v"]', 'to be (in the sense of existence) be, × have.', 'or הָוָה; a primitive root (compare 183, 1961) supposed to mean properly, to breathe;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1934}/[H1934]', 'lemma', 'arc', 'הָוָא', '["hâvâʼ"]', '["to exist; used in a great variety of applications (especially in connection with other words) be, become, behold, came (to pass), cease, cleave, consider, do, give, have, judge, keep, labour, mingle (self), put, see, seek, set, slay, take heed, tremble, walk, would."]', '["v"]', 'to exist; used in a great variety of applications (especially in connection with other words) be, become, behold, came (to pass), cease, cleave, consider, do, give, have, judge, keep, labour, mingle (self), put, see, seek, set, slay, take heed, tremble, walk, would.', '(Aramaic) or הָוָה; (Aramaic), corresponding to 1933;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1936}/[H1936]', 'lemma', 'heb', 'הוֹד', '["Hôwd"]', '["Hod, an Israelite Hod."]', '["n-pr-m"]', 'Hod, an Israelite Hod.', 'the same as 1935;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1937}/[H1937]', 'lemma', 'heb', 'הוֹדְוָה', '["Hôwdᵉvâh"]', '["Hodevah (or Hodevjah), an Israelite Hodevah."]', '["n-pr-m"]', 'Hodevah (or Hodevjah), an Israelite Hodevah.', 'a form of 1938;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1938}/[H1938]', 'lemma', 'heb', 'הוֹדַוְיָה', '["Hôwdavyâh"]', '["Hodavjah, the name of three Israelites Hodaviah."]', '["n-pr-m"]', 'Hodavjah, the name of three Israelites Hodaviah.', 'from 1935 and 3050; majesty of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1939}/[H1939]', 'lemma', 'heb', 'הוֹדַיְוָהוּ', '["Hôwdayvâhûw"]', '["Hodajvah, an Israelite Hodaiah."]', '["n-pr-m"]', 'Hodajvah, an Israelite Hodaiah.', 'a form of 1938;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1940}/[H1940]', 'lemma', 'heb', 'הוֹדִיָּה', '["Hôwdîyâh"]', '["a Jewess Hodiah."]', '["n-pr-f"]', 'a Jewess Hodiah.', 'a form for the feminine of 3064;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1941}/[H1941]', 'lemma', 'heb', 'הוֹדִיָּה', '["Hôwdîyâh"]', '["Hodijah, the name of three Israelites Hodijah."]', '["n-pr-m"]', 'Hodijah, the name of three Israelites Hodijah.', 'a form of 1938;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1942}/[H1942]', 'lemma', 'heb', 'הַוָּה', '["havvâh"]', '["by implication, of falling); desire; also ruin calamity, iniquity, mischief, mischievous (thing), naughtiness, naughty, noisome, perverse thing, substance, very wickedness."]', '["n-f"]', 'by implication, of falling); desire; also ruin calamity, iniquity, mischief, mischievous (thing), naughtiness, naughty, noisome, perverse thing, substance, very wickedness.', 'from 1933 (in the sense of eagerly coveting and rushing upon;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1943}/[H1943]', 'lemma', 'heb', 'הֹוָה', '["hôvâh"]', '["ruin mischief."]', '["n-f"]', 'ruin mischief.', 'another form for 1942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1945}/[H1945]', 'lemma', 'heb', 'הוֹי', '["hôwy"]', '["oh! ah, alas, ho, O, woe."]', '["inj"]', 'oh! ah, alas, ho, O, woe.', 'a prolonged form of 1930 (akin to 188);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1946}/[H1946]', 'lemma', 'arc', 'הוּךְ', '["hûwk"]', '["to go; causatively, to bring bring again, come, go (up)."]', '["v"]', 'to go; causatively, to bring bring again, come, go (up).', '(Aramaic) corresponding to 1981;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1947}/[H1947]', 'lemma', 'heb', 'הוֹלֵלָה', '["hôwlêlâh"]', '["folly madness."]', '["n-f"]', 'folly madness.', 'feminine active participle of 1984;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1948}/[H1948]', 'lemma', 'heb', 'הוֹלֵלוּת', '["hôwlêlûwth"]', '["folly madness."]', '["n-f"]', 'folly madness.', 'from active participle of 1984;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1949]', 'root', 'heb', 'הוּם', '["hûwm"]', '["to make an uproar, or agitate greatly destroy, move, make a noise, put, ring again."]', '["v"]', 'to make an uproar, or agitate greatly destroy, move, make a noise, put, ring again.', 'a primitive root (compare 2000);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1950}/[H1950]', 'lemma', 'heb', 'הוֹמָם', '["Hôwmâm"]', '["Homam, an Edomitish chieftain Homam. Compare 1967."]', '["n-pr-m"]', 'Homam, an Edomitish chieftain Homam. Compare 1967.', 'from 2000; raging;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1951]', 'root', 'heb', 'הוּן', '["hûwn"]', '["properly, to be naught, i.e. (figuratively) to be (causatively, act) light be ready."]', '["v"]', 'properly, to be naught, i.e. (figuratively) to be (causatively, act) light be ready.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1952}/[H1952]', 'lemma', 'heb', 'הוֹן', '["hôwn"]', '["wealth; by implication, enough enough, for nought, riches, substance, wealth."]', '["n-m"]', 'wealth; by implication, enough enough, for nought, riches, substance, wealth.', 'from the same as 1951 in the sense of 202;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1953}/[H1953]', 'lemma', 'heb', 'הוֹשָׁמָע', '["Hôwshâmâʻ"]', '["Hoshama, an Israelite Hoshama."]', '["n-pr-m"]', 'Hoshama, an Israelite Hoshama.', 'from 3068 and 8085; Jehovah has heard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1954}/[H1954]', 'lemma', 'heb', 'הוֹשֵׁעַ', '["Hôwshêaʻ"]', '["Hoshea, the name of five Israelites Hosea, Hoshea, Oshea."]', '["n-pr-m"]', 'Hoshea, the name of five Israelites Hosea, Hoshea, Oshea.', 'from 3467; deliverer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1955}/[H1955]', 'lemma', 'heb', 'הוֹשַׁעְיָה', '["Hôwshaʻyâh"]', '["Hoshajah, the name of two Israelites Hoshaiah."]', '["n-pr-m"]', 'Hoshajah, the name of two Israelites Hoshaiah.', 'from 3467 and 3050; Jah has saved;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1956}/[H1956]', 'lemma', 'heb', 'הוֹתִיר', '["Hôwthîyr"]', '["Hothir, an Israelite Hothir."]', '["n-pr-m"]', 'Hothir, an Israelite Hothir.', 'from 3498; he has caused to remain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1957]', 'root', 'heb', 'הָזָה', '["hâzâh"]', '["to dream sleep."]', '["v"]', 'to dream sleep.', 'a primitive root (compare 2372);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1958}/[H1958]', 'lemma', 'heb', 'הִי', '["hîy"]', '["lamentation woe. (For hiyr. See 1931, 1932.)"]', '["n-m"]', 'lamentation woe. (For hiyr. See 1931, 1932.)', 'for 5092;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1960}/[H1960]', 'lemma', 'heb', 'הֻיְּדָה', '["huyᵉdâh"]', '["properly, an acclaim, i.e. a choir of singers thanksgiving."]', '["n-f"]', 'properly, an acclaim, i.e. a choir of singers thanksgiving.', 'from the same as 1959;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1961]', 'root', 'heb', 'הָיָה', '["hâyâh"]', '["to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use."]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1962}/[H1962]', 'lemma', 'heb', 'הַיָּה', '["hayâh"]', '["ruin calamity."]', '["n-f"]', 'ruin calamity.', 'another form for 1943;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1963}/[H1963]', 'lemma', 'heb', 'הֵיךְ', '["hêyk"]', '["how? how."]', '["adv"]', 'how? how.', 'another form for 349;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1964}/[H1964]', 'lemma', 'heb', 'הֵיכָל', '["hêykâl"]', '["a large public building, such as a palace or temple palace, temple."]', '["n-m"]', 'a large public building, such as a palace or temple palace, temple.', 'probably from 3201 (in the sense of capacity);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1965}/[H1965]', 'lemma', 'arc', 'הֵיכַל', '["hêykal"]', '["palace, temple."]', '["n-m"]', 'palace, temple.', '(Aramaic) corresponding to 1964');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1966}/[H1966]', 'lemma', 'heb', 'הֵילֵל', '["hêylêl"]', '["the morning-star lucifer."]', '["n-m"]', 'the morning-star lucifer.', 'from 1984 (in the sense of brightness);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1967}/[H1967]', 'lemma', 'heb', 'הֵימָם', '["Hêymâm"]', '["Hemam, an Idumaean Hemam."]', '["n-pr-m"]', 'Hemam, an Idumaean Hemam.', 'another form for 1950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1968}/[H1968]', 'lemma', 'heb', 'הֵימָן', '["Hêymân"]', '["Heman, the name of at least two Israelites Heman."]', '["n-pr-m"]', 'Heman, the name of at least two Israelites Heman.', 'probably from 539; faithful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1970]', 'root', 'heb', 'הָכַר', '["hâkar"]', '["to injure make self strange."]', '["v"]', 'to injure make self strange.', 'a primitive root; apparently');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1971}/[H1971]', 'lemma', 'heb', 'הַכָּרָה', '["hakkârâh"]', '["respect, i.e. partiality shew."]', '["n-f"]', 'respect, i.e. partiality shew.', 'from 5234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1972}/[H1972]', 'lemma', 'heb', 'הָלָא', '["hâlâʼ"]', '["to remove or be remote cast far off."]', '["v"]', 'to remove or be remote cast far off.', 'probably denominatively from 1973;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1974}/[H1974]', 'lemma', 'heb', 'הִלּוּל', '["hillûwl"]', '["a celebration of thanksgiving for harvest merry, praise."]', '["n-m"]', 'a celebration of thanksgiving for harvest merry, praise.', 'from 1984 (in the sense of rejoicing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1975}/[H1975]', 'lemma', 'heb', 'הַלָּז', '["hallâz"]', '["this or that side, that, this."]', '["d"]', 'this or that side, that, this.', 'from 1976;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1976}/[H1976]', 'lemma', 'heb', 'הַלָּזֶה', '["hallâzeh"]', '["this very this."]', '["d"]', 'this very this.', 'from the article (see 1973) and 2088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1977}/[H1977]', 'lemma', 'heb', 'הַלֵּזוּ', '["hallêzûw"]', '["that this."]', '["d"]', 'that this.', 'another form of 1976;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1978}/[H1978]', 'lemma', 'heb', 'הָלִיךְ', '["hâlîyk"]', '["a walk, i.e. (by implication) a step step."]', '["n-m"]', 'a walk, i.e. (by implication) a step step.', 'from 1980;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1979}/[H1979]', 'lemma', 'heb', 'הֲלִיכָה', '["hălîykâh"]', '["a walking; by implication, a procession or march, a caravan company, going, walk, way."]', '["n-f"]', 'a walking; by implication, a procession or march, a caravan company, going, walk, way.', 'feminine of 1978;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1980]', 'root', 'heb', 'הָלַךְ', '["hâlak"]', '["to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl."]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1981}/[H1981]', 'lemma', 'arc', 'הֲלַךְ', '["hălak"]', '["to walk walk."]', '["v"]', 'to walk walk.', '(Aramaic) corresponding to 1980 (compare 1946);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1982}/[H1982]', 'lemma', 'heb', 'הֵלֶךְ', '["hêlek"]', '["properly, a journey, i.e. (by implication) a wayfarer; also a flowing × dropped, traveller."]', '["n-m"]', 'properly, a journey, i.e. (by implication) a wayfarer; also a flowing × dropped, traveller.', 'from 1980;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1983}/[H1983]', 'lemma', 'arc', 'הֲלָךְ', '["hălâk"]', '["properly, a journey, i.e. (by implication) toll on goods at a road custom."]', '["n-m"]', 'properly, a journey, i.e. (by implication) toll on goods at a road custom.', '(Aramaic) from 1981;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1984]', 'root', 'heb', 'הָלַל', '["hâlal"]', '["to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine."]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1985}/[H1985]', 'lemma', 'heb', 'הִלֵּל', '["Hillêl"]', '["Hillel, an Israelite Hillel."]', '["n-pr-m"]', 'Hillel, an Israelite Hillel.', 'from 1984; praising (namely God);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1986]', 'root', 'heb', 'הָלַם', '["hâlam"]', '["to strike down; by implication, to hammer, stamp, conquer, disband beat (down), break (down), overcome, smite (with the hammer)."]', '["v"]', 'to strike down; by implication, to hammer, stamp, conquer, disband beat (down), break (down), overcome, smite (with the hammer).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1987}/[H1987]', 'lemma', 'heb', 'הֶלֶם', '["Helem"]', '["Helem, the name of two Israelites Helem."]', '["n-pr-m"]', 'Helem, the name of two Israelites Helem.', 'from 1986; smiter;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1988}/[H1988]', 'lemma', 'heb', 'הֲלֹם', '["hălôm"]', '["hither here, hither(-(to)), thither."]', '["adv"]', 'hither here, hither(-(to)), thither.', 'from the article (see 1973);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1989}/[H1989]', 'lemma', 'heb', 'הַלְמוּת', '["halmûwth"]', '["a hammer (or mallet) hammer."]', '["n-f"]', 'a hammer (or mallet) hammer.', 'from 1986;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1990>', 'opaque', 'heb', 'הָם', '["Hâm"]', '["Ham, a region of Palestine Ham."]', '["n-pr-loc"]', 'Ham, a region of Palestine Ham.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1991}/[H1991]', 'lemma', 'heb', 'הֵם', '["hêm"]', '["abundance, i.e. wealth any of theirs."]', '["n-m"]', 'abundance, i.e. wealth any of theirs.', 'from 1993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1992}/[H1992]', 'lemma', 'heb', 'הֵם', '["hêm"]', '["they (only used when emphatic) it, like, × (how, so) many (soever, more as) they (be), (the) same, × so, × such, their, them, these, they, those, which, who, whom, withal, ye."]', '["p"]', 'they (only used when emphatic) it, like, × (how, so) many (soever, more as) they (be), (the) same, × so, × such, their, them, these, they, those, which, who, whom, withal, ye.', 'or (prolonged) הֵמָּה; masculine plural from 1931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H1993]', 'root', 'heb', 'הָמָה', '["hâmâh"]', '["to make a loud sound (like English ''hum''); by implication, to be in great commotion or tumult, to rage, war, moan, clamor clamorous, concourse, cry aloud, be disquieted, loud, mourn, be moved, make a noise, rage, roar, sound, be troubled, make in tumult, tumultuous, be in an uproar."]', '["v"]', 'to make a loud sound (like English ''hum''); by implication, to be in great commotion or tumult, to rage, war, moan, clamor clamorous, concourse, cry aloud, be disquieted, loud, mourn, be moved, make a noise, rage, roar, sound, be troubled, make in tumult, tumultuous, be in an uproar.', 'a primitive root (compare 1949);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1994}/[H1994]', 'lemma', 'arc', 'הִמּוֹ', '["himmôw"]', '["they × are, them, those."]', '["p"]', 'they × are, them, those.', '(Aramaic) or (prolonged) הִמּוֹן; (Aramaic), corresponding to 1992;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1995}/[H1995]', 'lemma', 'heb', 'הָמוֹן', '["hâmôwn"]', '["a noise, tumult, crowd; also disquietude, wealth abundance, company, many, multitude, multiply, noise, riches, rumbling, sounding, store, tumult."]', '["n-m"]', 'a noise, tumult, crowd; also disquietude, wealth abundance, company, many, multitude, multiply, noise, riches, rumbling, sounding, store, tumult.', 'or הָמֹן; (Ezekiel 5:7), from 1993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1996}/[H1996]', 'lemma', 'heb', 'הֲמוֹן גּוֹג', '["Hămôwn Gôwg"]', '["the multitude of Gog; the fanciful name of an emblematic place in Palestine Hamon-gog."]', '["n-pr-loc"]', 'the multitude of Gog; the fanciful name of an emblematic place in Palestine Hamon-gog.', 'from 1995 and 1463;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1997}/[H1997]', 'lemma', 'heb', 'הֲמוֹנָה', '["Hămôwnâh"]', '["Hamonah Hamonah."]', '["n-pr-loc"]', 'Hamonah Hamonah.', 'feminine of 1995; multitude; , the same as 1996');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1998}/[H1998]', 'lemma', 'heb', 'הֶמְיָה', '["hemyâh"]', '["sound noise."]', '["n-f"]', 'sound noise.', 'from 1993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2000]', 'root', 'heb', 'הָמַם', '["hâmam"]', '["properly, to put in commotion; by implication, to disturb, drive, destroy break, consume, crush, destroy, discomfit, trouble, vex."]', '["v"]', 'properly, to put in commotion; by implication, to disturb, drive, destroy break, consume, crush, destroy, discomfit, trouble, vex.', 'a primitive root (compare 1949, 1993);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2002>', 'opaque', 'arc', 'הַמְנִיךְ', '["hamnîyk"]', '["a necklace chain."]', '["n-m"]', 'a necklace chain.', '(Aramaic) but the text is הֲמוּנֵךְ; of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2004}/[H2004]', 'lemma', 'heb', 'הֵן', '["hên"]', '["they (only used when emphatic) × in, such like, (with) them, thereby, therein, (more than) they, wherein, in which, whom, withal."]', '["p"]', 'they (only used when emphatic) × in, such like, (with) them, thereby, therein, (more than) they, wherein, in which, whom, withal.', 'feminine plural from 1931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2006}/[H2006]', 'lemma', 'arc', 'הֵן', '["hên"]', '["lo! also there(-fore), (un-) less, whether, but, if (that) if, or, whether."]', '["inj"]', 'lo! also there(-fore), (un-) less, whether, but, if (that) if, or, whether.', '(Aramaic) corresponding to 2005;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2007}/[H2007]', 'lemma', 'heb', 'הֵנָּה', '["hênnâh"]', '["themselves (often used emphatic for the copula, also in indirect relation) × in, × such (and such things), their, (into) them, thence, therein, these, they (had), on this side, whose, wherein."]', '["p"]', 'themselves (often used emphatic for the copula, also in indirect relation) × in, × such (and such things), their, (into) them, thence, therein, these, they (had), on this side, whose, wherein.', 'prolongation for 2004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2008}/[H2008]', 'lemma', 'heb', 'הֵנָּה', '["hênnâh"]', '["hither or thither (but used both of place and time) here, hither(-to), now, on this (that) side, since, this (that) way, thitherward, thus far, to...fro, yet."]', '["adv"]', 'hither or thither (but used both of place and time) here, hither(-to), now, on this (that) side, since, this (that) way, thitherward, thus far, to...fro, yet.', 'from 2004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2009}/[H2009]', 'lemma', 'heb', 'הִנֵּה', '["hinnêh"]', '["lo! behold, lo, see."]', '["dp"]', 'lo! behold, lo, see.', 'prolongation for 2005;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2010}/[H2010]', 'lemma', 'heb', 'הֲנָחָה', '["hănâchâh"]', '["permission of rest, i.e. quiet release."]', '["n-f"]', 'permission of rest, i.e. quiet release.', 'from 5117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2011>', 'opaque', 'heb', 'הִנֹּם', '["Hinnôm"]', '["Hinnom, apparently a Jebusite Hinnom."]', '["n-pr-loc"]', 'Hinnom, apparently a Jebusite Hinnom.', 'probably of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2013]', 'root', 'heb', 'הָסָה', '["hâçâh"]', '["to hush hold peace (tongue), (keep) silence, be silent, still."]', '["v"]', 'to hush hold peace (tongue), (keep) silence, be silent, still.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2014}/[H2014]', 'lemma', 'heb', 'הֲפֻגָה', '["hăphugâh"]', '["relaxation intermission."]', '["n-f"]', 'relaxation intermission.', 'from 6313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2015]', 'root', 'heb', 'הָפַךְ', '["hâphak"]', '["to turn about or over; by implication, to change, overturn, return, pervert × become, change, come, be converted, give, make (a bed), overthrow (-turn), perverse, retire, tumble, turn (again, aside, back, to the contrary, every way)."]', '["v"]', 'to turn about or over; by implication, to change, overturn, return, pervert × become, change, come, be converted, give, make (a bed), overthrow (-turn), perverse, retire, tumble, turn (again, aside, back, to the contrary, every way).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2016}/[H2016]', 'lemma', 'heb', 'הֶפֶךְ', '["hephek"]', '["a turn, i.e. the reverse contrary."]', '["n-m"]', 'a turn, i.e. the reverse contrary.', '; or הֵפֶךְ; from 2015;');
