INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2018}/[H2018]', 'lemma', 'heb', 'הֲפֵכָה', '["hăphêkâh"]', '["destruction overthrow."]', '["n-f"]', 'destruction overthrow.', 'feminine of 2016;');
