INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2119]', 'root', 'heb', 'זָחַל', '["zâchal"]', '["to crawl; by implication, to fear be afraid, serpent, worm."]', '["v"]', 'to crawl; by implication, to fear be afraid, serpent, worm.', 'a primitive root;');
