INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2121}/[H2121]', 'lemma', 'heb', 'זֵידוֹן', '["zêydôwn"]', '["boiling of water, i.e. wave proud."]', '["a"]', 'boiling of water, i.e. wave proud.', 'from 2102;');
