INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2123>', 'opaque', 'heb', 'זִיז', '["zîyz"]', '["fulness of the breast; also a moving creature abundance, wild beast."]', '["n-m"]', 'fulness of the breast; also a moving creature abundance, wild beast.', 'from an unused root apparently meaning to be conspicuous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2124}/[H2124]', 'lemma', 'heb', 'זִיזָא', '["Zîyzâʼ"]', '["Ziza, the name of two Israelites Ziza."]', '["n-pr-m"]', 'Ziza, the name of two Israelites Ziza.', 'apparently from the same as 2123; prominence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2125}/[H2125]', 'lemma', 'heb', 'זִיזָה', '["Zîyzâh"]', '["Zizah, an Israelite Zizah."]', '["n-pr-m"]', 'Zizah, an Israelite Zizah.', 'another form for 2124;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2126}/[H2126]', 'lemma', 'heb', 'זִינָא', '["Zîynâʼ"]', '["Zina, an Israelite Zina."]', '["n-pr-m"]', 'Zina, an Israelite Zina.', 'from 2109; well-fed; or perhaps an orthographical error for 2124;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2127}/[H2127]', 'lemma', 'heb', 'זִיעַ', '["Zîyaʻ"]', '["Zia, an Israelite Zia."]', '["n-pr-m"]', 'Zia, an Israelite Zia.', 'from 2111; agitation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2128}/[H2128]', 'lemma', 'heb', 'זִיף', '["Zîyph"]', '["Ziph, the name of a place in Palestine; also of an Israelite Ziph."]', '["n-pr-m n-pr-loc"]', 'Ziph, the name of a place in Palestine; also of an Israelite Ziph.', 'from the same as 2203; flowing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2129}/[H2129]', 'lemma', 'heb', 'זִיפָה', '["Zîyphâh"]', '["Ziphah, an Israelite Ziphah."]', '["n-pr-m"]', 'Ziphah, an Israelite Ziphah.', 'feminine of 2128; a flowing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2130}/[H2130]', 'lemma', 'heb', 'זִיפִי', '["Zîyphîy"]', '["a Ziphite or inhabitant of Ziph Ziphim, Ziphite."]', '["n-m"]', 'a Ziphite or inhabitant of Ziph Ziphim, Ziphite.', 'patrial from 2128;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2131}/[H2131]', 'lemma', 'heb', 'זִיקָה', '["zîyqâh"]', '["properly, what leaps forth, i.e. flash of fire, or a burning arrow; also (from the original sense of the root) a bond chain, fetter, firebrand, spark."]', '["n-m"]', 'properly, what leaps forth, i.e. flash of fire, or a burning arrow; also (from the original sense of the root) a bond chain, fetter, firebrand, spark.', '(Isaiah 50:11) (feminine); and זִק; or זֵק; from 2187;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2132>', 'opaque', 'heb', 'זַיִת', '["zayith"]', '["an olive (as yielding illuminating oil), the tree, the branch or the berry olive (tree, -yard), Olivet."]', '["n-m"]', 'an olive (as yielding illuminating oil), the tree, the branch or the berry olive (tree, -yard), Olivet.', 'probably from an unused root (akin to 2099);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2133}/[H2133]', 'lemma', 'heb', 'זֵיתָן', '["Zêythân"]', '["Zethan, an Israelite Zethan."]', '["n-pr-m"]', 'Zethan, an Israelite Zethan.', 'from 2132; olive grove;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2134}/[H2134]', 'lemma', 'heb', 'זַךְ', '["zak"]', '["clear clean, pure."]', '["a"]', 'clear clean, pure.', 'from 2141;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2135]', 'root', 'heb', 'זָכָה', '["zâkâh"]', '["to be translucent; figuratively, to be innocent be (make) clean, cleanse, be clear, count pure."]', '["v"]', 'to be translucent; figuratively, to be innocent be (make) clean, cleanse, be clear, count pure.', 'a primitive root (compare 2141);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2136}/[H2136]', 'lemma', 'arc', 'זָכוּ', '["zâkûw"]', '["purity innocency."]', '["n-f"]', 'purity innocency.', '(Aramaic) from a root corresponding to 2135;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2137}/[H2137]', 'lemma', 'heb', 'זְכוּכִית', '["zᵉkûwkîyth"]', '["properly, transparency, i.e. glass crystal."]', '["n-f"]', 'properly, transparency, i.e. glass crystal.', 'from 2135;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2138}/[H2138]', 'lemma', 'heb', 'זָכוּר', '["zâkûwr"]', '["a male (of man or animals) males, men-children."]', '["n-m"]', 'a male (of man or animals) males, men-children.', 'properly, passive participle of 2142, but used for 2145;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2139}/[H2139]', 'lemma', 'heb', 'זַכּוּר', '["Zakkûwr"]', '["Zakkur, the name of seven Israelites Zaccur, Zacchur."]', '["n-pr-m"]', 'Zakkur, the name of seven Israelites Zaccur, Zacchur.', 'from 2142; mindful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2140}/[H2140]', 'lemma', 'heb', 'זַכַּי', '["Zakkay"]', '["Zakkai, an Israelite Zaccai."]', '["n-pr-m"]', 'Zakkai, an Israelite Zaccai.', 'from 2141; pure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2141]', 'root', 'heb', 'זָכַךְ', '["zâkak"]', '["to be transparent or clean (phys. or morally) be (make) clean, be pure(-r)."]', '["v"]', 'to be transparent or clean (phys. or morally) be (make) clean, be pure(-r).', 'a primitive root (compare 2135);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2142]', 'root', 'heb', 'זָכַר', '["zâkar"]', '["properly, to mark (so as to be recognized), i.e. to remember; by implication, to mention; to be male × burn (incense), × earnestly, be male, (make) mention (of), be mindful, recount, record(-er), remember, make to be remembered, bring (call, come, keep, put) to (in) remembrance, × still, think on, × well."]', '["v"]', 'properly, to mark (so as to be recognized), i.e. to remember; by implication, to mention; to be male × burn (incense), × earnestly, be male, (make) mention (of), be mindful, recount, record(-er), remember, make to be remembered, bring (call, come, keep, put) to (in) remembrance, × still, think on, × well.', 'a primitive root; also as denominative from 2145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2143}/[H2143]', 'lemma', 'heb', 'זֵכֶר', '["zêker"]', '["a memento, abstractly recollection (rarely if ever); by implication, commemoration memorial, memory, remembrance, scent."]', '["n-m"]', 'a memento, abstractly recollection (rarely if ever); by implication, commemoration memorial, memory, remembrance, scent.', 'or זֶכֶר; from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2144}/[H2144]', 'lemma', 'heb', 'זֶכֶר', '["Zeker"]', '["Zeker, an Israelite Zeker."]', '["n-pr-m"]', 'Zeker, an Israelite Zeker.', 'the same as 2143;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2145}/[H2145]', 'lemma', 'heb', 'זָכָר', '["zâkâr"]', '["properly, remembered, i.e. a male (of man or animals, as being the most noteworthy sex) × him, male, man(child, -kind)."]', '["n-m"]', 'properly, remembered, i.e. a male (of man or animals, as being the most noteworthy sex) × him, male, man(child, -kind).', 'from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2146}/[H2146]', 'lemma', 'heb', 'זִכְרוֹן', '["zikrôwn"]', '["a memento (or memorable thing, day or writing) memorial, record."]', '["n-m"]', 'a memento (or memorable thing, day or writing) memorial, record.', 'from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2147}/[H2147]', 'lemma', 'heb', 'זִכְרִי', '["Zikrîy"]', '["Zicri, the name of twelve Israelites Zichri."]', '["n-pr-m"]', 'Zicri, the name of twelve Israelites Zichri.', 'from 2142; memorable;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2148}/[H2148]', 'lemma', 'heb', 'זְכַרְיָה', '["Zᵉkaryâh"]', '["Zecarjah, the name of twenty-nine Israelites Zachariah, Zechariah."]', '["n-pr-m"]', 'Zecarjah, the name of twenty-nine Israelites Zachariah, Zechariah.', 'or זְכַרְיָהוּ; from 2142 and 3050; Jah has remembered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2149}/[H2149]', 'lemma', 'heb', 'זֻלּוּת', '["zullûwth"]', '["properly, a shaking, i.e. perhaps a tempest vilest."]', '["n-m"]', 'properly, a shaking, i.e. perhaps a tempest vilest.', 'from 2151;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2150}/[H2150]', 'lemma', 'heb', 'זַלְזַל', '["zalzal"]', '["tremulous, i.e. a twig sprig."]', '["n-m"]', 'tremulous, i.e. a twig sprig.', 'by reduplication from 2151;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2151]', 'root', 'heb', 'זָלַל', '["zâlal"]', '["to shake (as in the wind), i.e. to quake; figuratively, to be loose morally, worthless or prodigal blow down, glutton, riotous (eater), vile."]', '["v"]', 'to shake (as in the wind), i.e. to quake; figuratively, to be loose morally, worthless or prodigal blow down, glutton, riotous (eater), vile.', 'a primitive root (compare 2107);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2152}/[H2152]', 'lemma', 'heb', 'זַלְעָפָה', '["zalʻâphâh"]', '["a glow (of wind or anger); also a famine (as consuming) horrible, horror, terrible."]', '["n-f"]', 'a glow (of wind or anger); also a famine (as consuming) horrible, horror, terrible.', 'or זִלְעָפָהxlit zilʻâphâph corrected to zilʻâphâh; from 2196;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2154}/[H2154]', 'lemma', 'heb', 'זִמָּה', '["zimmâh"]', '["a plan, especially a bad one heinous crime, lewd(-ly, -ness), mischief, purpose, thought, wicked (device, mind, -ness)."]', '["n-f"]', 'a plan, especially a bad one heinous crime, lewd(-ly, -ness), mischief, purpose, thought, wicked (device, mind, -ness).', 'or זַמָּה; from 2161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2155}/[H2155]', 'lemma', 'heb', 'זִמָּה', '["Zimmâh"]', '["Zimmah, the name of two Israelites Zimmah."]', '["n-pr-m"]', 'Zimmah, the name of two Israelites Zimmah.', 'the same as 2154;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2156}/[H2156]', 'lemma', 'heb', 'זְמוֹרָה', '["zᵉmôwrâh"]', '["a twig (as pruned) vine, branch, slip."]', '["n"]', 'a twig (as pruned) vine, branch, slip.', 'or זְמֹרָה (feminine); and זְמֹר (masculine); from 2168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2157}/[H2157]', 'lemma', 'heb', 'זַמְזֹם', '["Zamzôm"]', '["a Zamzumite, or native tribe of Palestine Zamzummim."]', '["n-pr-m"]', 'a Zamzumite, or native tribe of Palestine Zamzummim.', 'from 2161; intriguing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2158}/[H2158]', 'lemma', 'heb', 'זָמִיר', '["zâmîyr"]', '["a song to be accompanied with instrumental music psalm(-ist), singing, song."]', '["n-m"]', 'a song to be accompanied with instrumental music psalm(-ist), singing, song.', 'or זָמִר; and (feminine) זְמִרָה; from 2167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2159}/[H2159]', 'lemma', 'heb', 'זָמִיר', '["zâmîyr"]', '["a twig (as pruned) branch."]', '["n-m"]', 'a twig (as pruned) branch.', 'from 2168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2160}/[H2160]', 'lemma', 'heb', 'זְמִירָה', '["Zᵉmîyrâh"]', '["Zemirah, an Israelite Zemira."]', '["n-pr-m"]', 'Zemirah, an Israelite Zemira.', 'feminine of 2158; song;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2161]', 'root', 'heb', 'זָמַם', '["zâmam"]', '["to plan, usually in a bad sense consider, devise, imagine, plot, purpose, think (evil)."]', '["v"]', 'to plan, usually in a bad sense consider, devise, imagine, plot, purpose, think (evil).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2162}/[H2162]', 'lemma', 'heb', 'זָמָם', '["zâmâm"]', '["a plot wicked device."]', '["n-m"]', 'a plot wicked device.', 'from 2161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2163]', 'root', 'heb', 'זָמַן', '["zâman"]', '["to fix (a time) appoint."]', '["v"]', 'to fix (a time) appoint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2164}/[H2164]', 'lemma', 'arc', 'זְמַן', '["zᵉman"]', '["to agree (on a time and place) prepare."]', '["v"]', 'to agree (on a time and place) prepare.', '(Aramaic) corresponding to 2163;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2165}/[H2165]', 'lemma', 'heb', 'זְמָן', '["zᵉmân"]', '["an appointed occasion season, time."]', '["n-m"]', 'an appointed occasion season, time.', 'from 2163;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2166}/[H2166]', 'lemma', 'arc', 'זְמָן', '["zᵉmân"]', '["season, time."]', '["n-m"]', 'season, time.', '(Aramaic) from 2165; the same as 2165');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2167]', 'root', 'heb', 'זָמַר', '["zâmar"]', '["properly, to touch the strings or parts of a musical instrument, i.e. play upon it; to make music, accompanied by the voice; hence to celebrate in song and music give praise, sing forth praises, psalms."]', '["v"]', 'properly, to touch the strings or parts of a musical instrument, i.e. play upon it; to make music, accompanied by the voice; hence to celebrate in song and music give praise, sing forth praises, psalms.', 'a primitive root (perhaps identical with 2168 through the idea of striking with the fingers);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2168]', 'root', 'heb', 'זָמַר', '["zâmar"]', '["to trim (a vine) prune."]', '["v"]', 'to trim (a vine) prune.', 'a primitive root (compare 2167, 5568, 6785);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2169}/[H2169]', 'lemma', 'heb', 'זֶמֶר', '["zemer"]', '["a gazelle (from its lightly touching the ground) chamois."]', '["n-m"]', 'a gazelle (from its lightly touching the ground) chamois.', 'apparently from 2167 or 2168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2170}/[H2170]', 'lemma', 'arc', 'זְמָר', '["zᵉmâr"]', '["instrumental music musick."]', '["n-m"]', 'instrumental music musick.', '(Aramaic) from a root corresponding to 2167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2171}/[H2171]', 'lemma', 'arc', 'זַמָּר', '["zammâr"]', '["an instrumental musician singer."]', '["n-m"]', 'an instrumental musician singer.', '(Aramaic) from the same as 2170;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2172}/[H2172]', 'lemma', 'heb', 'זִמְרָה', '["zimrâh"]', '["a musical piece or song to be accompanied by an instrument melody, psalm."]', '["n-f"]', 'a musical piece or song to be accompanied by an instrument melody, psalm.', 'from 2167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2173}/[H2173]', 'lemma', 'heb', 'זִמְרָה', '["zimrâh"]', '["pruned (i.e. choice) fruit best fruit."]', '["n-f"]', 'pruned (i.e. choice) fruit best fruit.', 'from 2168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2174}/[H2174]', 'lemma', 'heb', 'זִמְרִי', '["Zimrîy"]', '["Zimri, the name of five Israelites, and of an Arabian tribe Zimri."]', '["n-pr-m"]', 'Zimri, the name of five Israelites, and of an Arabian tribe Zimri.', 'from 2167; musical;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2175}/[H2175]', 'lemma', 'heb', 'זִמְרָן', '["Zimrân"]', '["Zimran, a son of Abraham by Keturah Zimran."]', '["n-pr-m"]', 'Zimran, a son of Abraham by Keturah Zimran.', 'from 2167; musical;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2176}/[H2176]', 'lemma', 'heb', 'זִמְרָת', '["zimrâth"]', '["instrumental music; by implication, praise song."]', '["n-f"]', 'instrumental music; by implication, praise song.', 'from 2167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2177}/[H2177]', 'lemma', 'heb', 'זַן', '["zan"]', '["properly, nourished (or fully developed), i.e. a form or sort divers kinds, × all manner of store."]', '["n-m"]', 'properly, nourished (or fully developed), i.e. a form or sort divers kinds, × all manner of store.', 'from 2109;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2178}/[H2178]', 'lemma', 'arc', 'זַן', '["zan"]', '["sort kind."]', '["n-m"]', 'sort kind.', '(Aramaic) corresponding to 2177;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2179]', 'root', 'heb', 'זָנַב', '["zânab"]', '["to curtail, i.e. cut off the rear smite the hindmost."]', '["v"]', 'to curtail, i.e. cut off the rear smite the hindmost.', 'a primitive root meaning to wag; used only as a denominative from 2180;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2180}/[H2180]', 'lemma', 'heb', 'זָנָב', '["zânâb"]', '["the tail (literally or figuratively) tail."]', '["n-m"]', 'the tail (literally or figuratively) tail.', 'from 2179 (in the original sense of flapping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2181]', 'root', 'heb', 'זָנָה', '["zânâh"]', '["to commit adultery (usually of the female, and less often of simple fornication, rarely of involuntary ravishment); figuratively, to commit idolatry (the Jewish people being regarded as the spouse of Jehovah) (cause to) commit fornication, × continually, × great, (be an, play the) harlot, (cause to be, play the) whore, (commit, fall to) whoredom, (cause to) go a-whoring, whorish."]', '["v"]', 'to commit adultery (usually of the female, and less often of simple fornication, rarely of involuntary ravishment); figuratively, to commit idolatry (the Jewish people being regarded as the spouse of Jehovah) (cause to) commit fornication, × continually, × great, (be an, play the) harlot, (cause to be, play the) whore, (commit, fall to) whoredom, (cause to) go a-whoring, whorish.', 'a primitive root [highly fed and therefore wanton];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2182}/[H2182]', 'lemma', 'heb', 'זָנוֹחַ', '["Zânôwach"]', '["Zanoach, the name of two places in Palestine Zanoah."]', '["n-pr-loc"]', 'Zanoach, the name of two places in Palestine Zanoah.', 'from 2186; rejected;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2183}/[H2183]', 'lemma', 'heb', 'זָנוּן', '["zânûwn"]', '["adultery; figuratively, idolatry whoredom."]', '["n-m"]', 'adultery; figuratively, idolatry whoredom.', 'from 2181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2184}/[H2184]', 'lemma', 'heb', 'זְנוּת', '["zᵉnûwth"]', '["adultery, i.e. (figuratively) infidelity, idolatry whoredom."]', '["n-f"]', 'adultery, i.e. (figuratively) infidelity, idolatry whoredom.', 'from 2181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2185>', 'opaque', 'heb', 'זֹנוֹת', '["zônôwth"]', '["harlots armour."]', '["n-f"]', 'harlots armour.', 'regarded by some as if from 2109 or an unused root, and applied to military equipments; but evidently the feminine plural active participle of 2181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2186]', 'root', 'heb', 'זָנַח', '["zânach"]', '["reject, forsake, fail cast away (off), remove far away (off)."]', '["v"]', 'reject, forsake, fail cast away (off), remove far away (off).', 'a primitive root meaning to push aside, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2187]', 'root', 'heb', 'זָנַק', '["zânaq"]', '["properly, to draw together the feet (as an animal about to dart upon its prey), i.e. to spring forward leap."]', '["v"]', 'properly, to draw together the feet (as an animal about to dart upon its prey), i.e. to spring forward leap.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2188}/[H2188]', 'lemma', 'heb', 'זֵעָה', '["zêʻâh"]', '["perspiration sweat."]', '["n-f"]', 'perspiration sweat.', 'from 2111 (in the sense of 3154);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2189}/[H2189]', 'lemma', 'heb', 'זַעֲוָה', '["zaʻăvâh"]', '["agitation, maltreatment × removed, trouble."]', '["n-f"]', 'agitation, maltreatment × removed, trouble.', 'by transposition for 2113;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2190}/[H2190]', 'lemma', 'heb', 'זַעֲוָן', '["Zaʻăvân"]', '["Zaavan, an Idumaean Zaavan."]', '["n-pr-m"]', 'Zaavan, an Idumaean Zaavan.', 'from 2111; disquiet;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2192}/[H2192]', 'lemma', 'arc', 'זְעֵיר', '["zᵉʻêyr"]', '["little."]', '["a"]', 'little.', '(Aramaic) corresponding to 2191');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2193]', 'root', 'heb', 'זָעַךְ', '["zâʻak"]', '["to extinguish be extinct."]', '["v"]', 'to extinguish be extinct.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2194]', 'root', 'heb', 'זָעַם', '["zâʻam"]', '["properly, to foam at the mouth, i.e. to be enraged abhor, abominable, (be) angry, defy, (have) indignation."]', '["v"]', 'properly, to foam at the mouth, i.e. to be enraged abhor, abominable, (be) angry, defy, (have) indignation.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2195}/[H2195]', 'lemma', 'heb', 'זַעַם', '["zaʻam"]', '["strictly froth at the mouth, i.e. (figuratively) fury (especially of God''s displeasure with sin) angry, indignation, rage."]', '["n-m"]', 'strictly froth at the mouth, i.e. (figuratively) fury (especially of God''s displeasure with sin) angry, indignation, rage.', 'from 2194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2196]', 'root', 'heb', 'זָעַף', '["zâʻaph"]', '["properly, to boil up, i.e. (figuratively) to be peevish or angry fret, sad, worse liking, be wroth."]', '["v"]', 'properly, to boil up, i.e. (figuratively) to be peevish or angry fret, sad, worse liking, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2197}/[H2197]', 'lemma', 'heb', 'זַעַף', '["zaʻaph"]', '["anger indignation, rage(-ing), wrath."]', '["n-m"]', 'anger indignation, rage(-ing), wrath.', 'from 2196;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2198}/[H2198]', 'lemma', 'heb', 'זָעֵף', '["zâʻêph"]', '["angry displeased."]', '["a"]', 'angry displeased.', 'from 2196;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2199]', 'root', 'heb', 'זָעַק', '["zâʻaq"]', '["to shriek (from anguish or danger); by analogy, (as a herald) to announce or convene publicly assemble, call (together), (make a) cry (out), come with such a company, gather (together), cause to be proclaimed."]', '["v"]', 'to shriek (from anguish or danger); by analogy, (as a herald) to announce or convene publicly assemble, call (together), (make a) cry (out), come with such a company, gather (together), cause to be proclaimed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2200}/[H2200]', 'lemma', 'arc', 'זְעִק', '["zᵉʻiq"]', '["to make an outcry cry."]', '["v"]', 'to make an outcry cry.', '(Aramaic) corresponding to 2199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2201}/[H2201]', 'lemma', 'heb', 'זַעַק', '["zaʻaq"]', '["a shriek or outcry cry(-ing)."]', '["n-f"]', 'a shriek or outcry cry(-ing).', 'and (feminine) זְעָקָהxlit zᵉâqâh corrected to zᵉʻâqâh; from 2199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2202>', 'opaque', 'heb', 'זִפְרֹן', '["Ziphrôn"]', '["Ziphron, a place in Palestine Ziphron."]', '["n-pr-loc"]', 'Ziphron, a place in Palestine Ziphron.', 'from an unused root (meaning to be fragrant);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2203>', 'opaque', 'heb', 'זֶפֶת', '["zepheth"]', '["asphalt (from its tendency to soften in the sun) pitch."]', '["n-f"]', 'asphalt (from its tendency to soften in the sun) pitch.', 'from an unused root (meaning to liquify);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2204]', 'root', 'heb', 'זָקֵן', '["zâqên"]', '["to be old aged man, be (wax) old (man)."]', '["v"]', 'to be old aged man, be (wax) old (man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2205}/[H2205]', 'lemma', 'heb', 'זָקֵן', '["zâqên"]', '["old aged, ancient (man), elder(-est), old (man, men and...women), senator."]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2206}/[H2206]', 'lemma', 'heb', 'זָקָן', '["zâqân"]', '["the beard (as indicating age) beard."]', '["n-m"]', 'the beard (as indicating age) beard.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2207}/[H2207]', 'lemma', 'heb', 'זֹקֶן', '["zôqen"]', '["old age age."]', '["n-m"]', 'old age age.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2208}/[H2208]', 'lemma', 'heb', 'זָקֻן', '["zâqun"]', '["old age old age."]', '["n-m"]', 'old age old age.', 'properly, passive participle of 2204 (used only in the plural as a noun);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2209}/[H2209]', 'lemma', 'heb', 'זִקְנָה', '["ziqnâh"]', '["old age old (age)."]', '["n-f"]', 'old age old (age).', 'feminine of 2205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2210]', 'root', 'heb', 'זָקַף', '["zâqaph"]', '["to life, i.e. (figuratively) comfort raise (up)."]', '["v"]', 'to life, i.e. (figuratively) comfort raise (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2211}/[H2211]', 'lemma', 'arc', 'זְקַף', '["zᵉqaph"]', '["to hang, i.e. impale set up."]', '["v"]', 'to hang, i.e. impale set up.', '(Aramaic) corresponding to 2210;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2212]', 'root', 'heb', 'זָקַק', '["zâqaq"]', '["to strain, (figuratively) extract, clarify fine, pour down, purge, purify, refine."]', '["v"]', 'to strain, (figuratively) extract, clarify fine, pour down, purge, purify, refine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2213}/[H2213]', 'lemma', 'heb', 'זֵר', '["zêr"]', '["a chaplet (as spread around the top), i.e. (specifically) a border moulding crown."]', '["n-m"]', 'a chaplet (as spread around the top), i.e. (specifically) a border moulding crown.', 'from 2237 (in the sense of scattering);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2214}/[H2214]', 'lemma', 'heb', 'זָרָא', '["zârâʼ"]', '["disgust loathsome."]', '["n-m"]', 'disgust loathsome.', 'from 2114 (in the sense of estrangement) (compare 2219);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2215]', 'root', 'heb', 'זָרַב', '["zârab"]', '["to flow away wax warm."]', '["v"]', 'to flow away wax warm.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2216}/[H2216]', 'lemma', 'heb', 'זְרֻבָּבֶל', '["Zᵉrubbâbel"]', '["Zerubbabel, an Israelite Zerubbabel."]', '["n-pr-m"]', 'Zerubbabel, an Israelite Zerubbabel.', 'from 2215 and 894; descended of (i.e. from) Babylon, i.e. born there;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2217}/[H2217]', 'lemma', 'arc', 'זְרֻבָּבֶל', '["Zᵉrubbâbel"]', '["Zerubbabel."]', '["n-pr-m"]', 'Zerubbabel.', '(Aramaic) corresponding to 2216');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2219]', 'root', 'heb', 'זָרָה', '["zârâh"]', '["to toss about; by implication, to diffuse, winnow cast away, compass, disperse, fan, scatter (away), spread, strew, winnow."]', '["v"]', 'to toss about; by implication, to diffuse, winnow cast away, compass, disperse, fan, scatter (away), spread, strew, winnow.', 'a primitive root (compare 2114);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2220}/[H2220]', 'lemma', 'heb', 'זְרוֹעַ', '["zᵉrôwaʻ"]', '["the arm (as stretched out), or (of animals) the foreleg; figuratively, force arm, help, mighty, power, shoulder, strength."]', '["n-f"]', 'the arm (as stretched out), or (of animals) the foreleg; figuratively, force arm, help, mighty, power, shoulder, strength.', 'or (shortened) זְרֹעַ; and (feminine) זְרוֹעָה; or זְרֹעָה; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2221}/[H2221]', 'lemma', 'heb', 'זֵרוּעַ', '["zêrûwaʻ"]', '["something sown, i.e. a plant sowing, thing that is sown."]', '["n-m"]', 'something sown, i.e. a plant sowing, thing that is sown.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2222>', 'opaque', 'heb', 'זַרְזִיף', '["zarzîyph"]', '["a pouring rain water."]', '["v n-m"]', 'a pouring rain water.', 'by reduplication from an unused root meaning to flow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2223}/[H2223]', 'lemma', 'heb', 'זַרְזִיר', '["zarzîyr"]', '["properly, tightly girt, i.e. probably a racer, or some fleet animal (as being slender in the waist) greyhound."]', '["n-m"]', 'properly, tightly girt, i.e. probably a racer, or some fleet animal (as being slender in the waist) greyhound.', 'by reduplication from 2115;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2224]', 'root', 'heb', 'זָרַח', '["zârach"]', '["properly, to irradiate (or shoot forth beams), i.e. to rise (as the sun); specifically, to appear (as a symptom of leprosy) arise, rise (up), as soon as it is up."]', '["v"]', 'properly, to irradiate (or shoot forth beams), i.e. to rise (as the sun); specifically, to appear (as a symptom of leprosy) arise, rise (up), as soon as it is up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2225}/[H2225]', 'lemma', 'heb', 'זֶרַח', '["zerach"]', '["a rising of light rising."]', '["n-m"]', 'a rising of light rising.', 'from 2224;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2226}/[H2226]', 'lemma', 'heb', 'זֶרַח', '["Zerach"]', '["Zerach, the name of three Israelites, also of an Idumaean and an Ethiopian prince Zarah, Zerah."]', '["n-pr-m"]', 'Zerach, the name of three Israelites, also of an Idumaean and an Ethiopian prince Zarah, Zerah.', 'the same as 2225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2227}/[H2227]', 'lemma', 'heb', 'זַרְחִי', '["Zarchîy"]', '["a Zarchite or descendant of Zerach Zarchite."]', '["n-m"]', 'a Zarchite or descendant of Zerach Zarchite.', 'patronymically from 2226;');
