INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2257}/[H2257]', 'lemma', 'arc', 'חֲבַל', '["chăbal"]', '["harm (personal or pecuniary) damage, hurt."]', '["n-m"]', 'harm (personal or pecuniary) damage, hurt.', '(Aramaic) from 2255;');
