INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2358}/[H2358]', 'lemma', 'arc', 'חִוָּר', '["chivvâr"]', '["white white."]', '["a"]', 'white white.', '(Aramaic) from a root corresponding to 2357;');
