INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2366}/[H2366]', 'lemma', 'heb', 'חוּשִׁים', '["Chûwshîym"]', '["Chushim, the name of three Israelites Hushim."]', '["n-pr-f n-pr-m"]', 'Chushim, the name of three Israelites Hushim.', 'or חֻשִׁים; or חֻשִׁם; plural from 2363; hasters;');
