INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2369}/[H2369]', 'lemma', 'heb', 'חוֹתָם', '["Chôwthâm"]', '["Chotham, the name of two Israelites Hotham, Hothan."]', '["n-pr-m"]', 'Chotham, the name of two Israelites Hotham, Hothan.', 'the same as 2368; seal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2370}/[H2370]', 'lemma', 'arc', 'חֲזָא', '["chăzâʼ"]', '["to gaze upon; mentally to dream, be usual (i.e. seem) behold, have (a dream), see, be wont."]', '["v"]', 'to gaze upon; mentally to dream, be usual (i.e. seem) behold, have (a dream), see, be wont.', '(Aramaic) or חֲזָה; (Aramaic), corresponding to 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2371}/[H2371]', 'lemma', 'heb', 'חֲזָאֵל', '["Chăzâʼêl"]', '["Chazael, a king of Syria Hazael."]', '["n-pr-m"]', 'Chazael, a king of Syria Hazael.', 'or חֲזָהאֵל; from 2372 and 410; God has seen;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2372]', 'root', 'heb', 'חָזָה', '["châzâh"]', '["to gaze at; mentally to perceive, contemplate (with pleasure); specifically, to have a vision of behold, look, prophesy, provide, see."]', '["v"]', 'to gaze at; mentally to perceive, contemplate (with pleasure); specifically, to have a vision of behold, look, prophesy, provide, see.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2373}/[H2373]', 'lemma', 'heb', 'חָזֶה', '["châzeh"]', '["the breast (as most seen in front) breast."]', '["n-m"]', 'the breast (as most seen in front) breast.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2374}/[H2374]', 'lemma', 'heb', 'חֹזֶה', '["chôzeh"]', '["a beholder in vision; also a compact (as looked upon with approval) agreement, prophet, see that, seer, (star-) gazer."]', '["n-m"]', 'a beholder in vision; also a compact (as looked upon with approval) agreement, prophet, see that, seer, (star-) gazer.', 'active participle of 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2375}/[H2375]', 'lemma', 'heb', 'חֲזוֹ', '["Chăzôw"]', '["Chazo, a nephew of Abraham Hazo."]', '["n-pr-m"]', 'Chazo, a nephew of Abraham Hazo.', 'from 2372; seer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2376}/[H2376]', 'lemma', 'arc', 'חֵזֵו', '["chêzêv"]', '["a sight look, vision."]', '["n-m"]', 'a sight look, vision.', '(Aramaic) from 2370;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2377}/[H2377]', 'lemma', 'heb', 'חָזוֹן', '["châzôwn"]', '["a sight (mentally), i.e. a dream, revelation, or oracle vision."]', '["n-m"]', 'a sight (mentally), i.e. a dream, revelation, or oracle vision.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2378}/[H2378]', 'lemma', 'heb', 'חָזוֹת', '["châzôwth"]', '["a revelation vision."]', '["n-f"]', 'a revelation vision.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2379}/[H2379]', 'lemma', 'arc', 'חֲזוֹת', '["chăzôwth"]', '["a view sight."]', '["n-f"]', 'a view sight.', '(Aramaic) from 2370;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2380}/[H2380]', 'lemma', 'heb', 'חָזוּת', '["châzûwth"]', '["a look; hence (figuratively) striking appearance, revelation, or (by implication) compact agreement, notable (one), vision."]', '["n-f"]', 'a look; hence (figuratively) striking appearance, revelation, or (by implication) compact agreement, notable (one), vision.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2381}/[H2381]', 'lemma', 'heb', 'חֲזִיאֵל', '["Chăzîyʼêl"]', '["Chaziel, a Levite Haziel."]', '["n-pr-m"]', 'Chaziel, a Levite Haziel.', 'from 2372 and 410; seen of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2382}/[H2382]', 'lemma', 'heb', 'חֲזָיָה', '["Chăzâyâh"]', '["Chazajah, an Israelite Hazaiah."]', '["n-pr-m"]', 'Chazajah, an Israelite Hazaiah.', 'from 2372 and 3050; Jah has seen;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2383}/[H2383]', 'lemma', 'heb', 'חֶזְיוֹן', '["Chezyôwn"]', '["Chezjon, a Syrian Hezion."]', '["n-pr-m"]', 'Chezjon, a Syrian Hezion.', 'from 2372; vision;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2384}/[H2384]', 'lemma', 'heb', 'חִזָּיוֹן', '["chizzâyôwn"]', '["a revelation, expectation by dream vision."]', '["n-m"]', 'a revelation, expectation by dream vision.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2387}/[H2387]', 'lemma', 'heb', 'חֵזִיר', '["Chêzîyr"]', '["Chezir, the name of two Israelites Hezir."]', '["n-pr-m"]', 'Chezir, the name of two Israelites Hezir.', 'from the same as 2386; perhaps protected;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2388]', 'root', 'heb', 'חָזַק', '["châzaq"]', '["to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand."]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2389}/[H2389]', 'lemma', 'heb', 'חָזָק', '["châzâq"]', '["strong (usu. in a bad sense, hard, bold, violent) harder, hottest, impudent, loud, mighty, sore, stiff(-hearted), strong(-er)."]', '["a"]', 'strong (usu. in a bad sense, hard, bold, violent) harder, hottest, impudent, loud, mighty, sore, stiff(-hearted), strong(-er).', 'from 2388;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2390}/[H2390]', 'lemma', 'heb', 'חָזֵק', '["châzêq"]', '["powerful × wax louder, stronger."]', '["a"]', 'powerful × wax louder, stronger.', 'from 2388;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2391}/[H2391]', 'lemma', 'heb', 'חֵזֶק', '["chêzeq"]', '["help strength."]', '["n-m"]', 'help strength.', 'from 2388;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2392}/[H2392]', 'lemma', 'heb', 'חֹזֶק', '["chôzeq"]', '["power strength."]', '["n-m"]', 'power strength.', 'from 2388;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2393}/[H2393]', 'lemma', 'heb', 'חֶזְקָה', '["chezqâh"]', '["prevailing power strength(-en self), (was) strong."]', '["n-f"]', 'prevailing power strength(-en self), (was) strong.', 'feminine of 2391;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2394}/[H2394]', 'lemma', 'heb', 'חׇזְקָה', '["chozqâh"]', '["vehemence (usually in a bad sense) force, mightily, repair, sharply."]', '["n-f"]', 'vehemence (usually in a bad sense) force, mightily, repair, sharply.', 'feminine of 2392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2395}/[H2395]', 'lemma', 'heb', 'חִזְקִי', '["Chizqîy"]', '["Chizki, an Israelite Hezeki."]', '["n-pr-m"]', 'Chizki, an Israelite Hezeki.', 'from 2388; strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2396}/[H2396]', 'lemma', 'heb', 'חִזְקִיָּה', '["Chizqîyâh"]', '["Chizkijah, a king of Judah, also the name of two other Israelites Hezekiah, Hizkiah, Hizkijah. Compare 3169."]', '["n-pr-m"]', 'Chizkijah, a king of Judah, also the name of two other Israelites Hezekiah, Hizkiah, Hizkijah. Compare 3169.', 'or חִזְקִיָּהוּ; also יְחִזְקִיָּה; or יְחִזְקִיָּהוּ; from 2388 and 3050; strengthened of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2397}/[H2397]', 'lemma', 'heb', 'חָח', '["châch"]', '["a ring for the nose (or lips) bracelet, chain, hook."]', '["n-m"]', 'a ring for the nose (or lips) bracelet, chain, hook.', 'once (Ezekiel 29:4) חָחִי; from the same as 2336;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2398]', 'root', 'heb', 'חָטָא', '["châṭâʼ"]', '["properly, to miss; hence (figuratively and generally) to sin; by inference, to forfeit, lack, expiate, repent, (causatively) lead astray, condemn bear the blame, cleanse, commit (sin), by fault, harm he hath done, loss, miss, (make) offend(-er), offer for sin, purge, purify (self), make reconciliation, (cause, make) sin(-ful, -ness), trespass."]', '["v"]', 'properly, to miss; hence (figuratively and generally) to sin; by inference, to forfeit, lack, expiate, repent, (causatively) lead astray, condemn bear the blame, cleanse, commit (sin), by fault, harm he hath done, loss, miss, (make) offend(-er), offer for sin, purge, purify (self), make reconciliation, (cause, make) sin(-ful, -ness), trespass.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2399}/[H2399]', 'lemma', 'heb', 'חֵטְא', '["chêṭᵉʼ"]', '["a crime or its penalty fault, × grievously, offence, (punishment of) sin."]', '["n-m"]', 'a crime or its penalty fault, × grievously, offence, (punishment of) sin.', 'from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2400}/[H2400]', 'lemma', 'heb', 'חַטָּא', '["chaṭṭâʼ"]', '["a criminal, or one accounted guilty offender, sinful, sinner."]', '["n-m"]', 'a criminal, or one accounted guilty offender, sinful, sinner.', 'intensively from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2401}/[H2401]', 'lemma', 'heb', 'חֲטָאָה', '["chăṭâʼâh"]', '["an offence, or a sacrifice for it sin (offering)."]', '["n-f"]', 'an offence, or a sacrifice for it sin (offering).', 'feminine of 2399;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2402}/[H2402]', 'lemma', 'arc', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["an offence, and the penalty or sacrifice for it sin (offering)."]', '["n-f"]', 'an offence, and the penalty or sacrifice for it sin (offering).', '(Aramaic) corresponding to 2401;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2403}/[H2403]', 'lemma', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering)."]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2404]', 'root', 'heb', 'חָטַב', '["châṭab"]', '["to chop or carve wood cut down, hew(-er), polish."]', '["v"]', 'to chop or carve wood cut down, hew(-er), polish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2405}/[H2405]', 'lemma', 'heb', 'חֲטֻבָה', '["chăṭubâh"]', '["properly, a carving; hence, a tapestry (as figured) carved."]', '["n-f"]', 'properly, a carving; hence, a tapestry (as figured) carved.', 'feminine passive participle of 2404;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2407>', 'opaque', 'heb', 'חַטּוּשׁ', '["Chaṭṭûwsh"]', '["Chattush, the name of four or five Israelites Hattush."]', '["n-pr-m"]', 'Chattush, the name of four or five Israelites Hattush.', 'from an unused root of uncertain signification;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2408}/[H2408]', 'lemma', 'arc', 'חֲטִי', '["chăṭîy"]', '["an offence sin."]', '["n-m"]', 'an offence sin.', '(Aramaic) from a root corresponding to 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2409}/[H2409]', 'lemma', 'arc', 'חֲטָּיָא', '["chăṭṭâyâʼ"]', '["an expiation sin offering."]', '["n-f"]', 'an expiation sin offering.', '(Aramaic) from the same as 2408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2412}/[H2412]', 'lemma', 'heb', 'חֲטִיפָא', '["Chăṭîyphâʼ"]', '["Chatipha, one of the Nethinim Hatipha."]', '["n-pr-m"]', 'Chatipha, one of the Nethinim Hatipha.', 'from 2414; robber;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2413]', 'root', 'heb', 'חָטַם', '["châṭam"]', '["to stop refrain."]', '["v"]', 'to stop refrain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2414]', 'root', 'heb', 'חָטַף', '["châṭaph"]', '["to clutch; hence, to seize as a prisoner catch."]', '["v"]', 'to clutch; hence, to seize as a prisoner catch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2416}/[H2416]', 'lemma', 'heb', 'חַי', '["chay"]', '["alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop."]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2417}/[H2417]', 'lemma', 'arc', 'חַי', '["chay"]', '["alive; also (as noun in plural) life life, that liveth, living."]', '["a"]', 'alive; also (as noun in plural) life life, that liveth, living.', '(Aramaic) from 2418;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2418}/[H2418]', 'lemma', 'arc', 'חֲיָא', '["chăyâʼ"]', '["to live live, keep alive."]', '["v"]', 'to live live, keep alive.', '(Aramaic) or חֲיָה; (Aramaic), corresponding to 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2419}/[H2419]', 'lemma', 'heb', 'חִיאֵל', '["Chîyʼêl"]', '["Chiel, an Israelite Hiel."]', '["n-pr-m"]', 'Chiel, an Israelite Hiel.', 'from 2416 and 410; living of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2420}/[H2420]', 'lemma', 'heb', 'חִידָה', '["chîydâh"]', '["a puzzle, hence, a trick, conundrum, sententious maxim dark saying (sentence, speech), hard question, proverb, riddle."]', '["n-f"]', 'a puzzle, hence, a trick, conundrum, sententious maxim dark saying (sentence, speech), hard question, proverb, riddle.', 'from 2330;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2421]', 'root', 'heb', 'חָיָה', '["châyâh"]', '["to live, whether literally or figuratively; causatively, to revive keep (leave, make) alive, × certainly, give (promise) life, (let, suffer to) live, nourish up, preserve (alive), quicken, recover, repair, restore (to life), revive, (× God) save (alive, life, lives), × surely, be whole."]', '["v"]', 'to live, whether literally or figuratively; causatively, to revive keep (leave, make) alive, × certainly, give (promise) life, (let, suffer to) live, nourish up, preserve (alive), quicken, recover, repair, restore (to life), revive, (× God) save (alive, life, lives), × surely, be whole.', 'a primitive root (compare 2331, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2422}/[H2422]', 'lemma', 'heb', 'חָיֶה', '["châyeh"]', '["vigorous lively."]', '["a"]', 'vigorous lively.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2423}/[H2423]', 'lemma', 'arc', 'חֵיוָא', '["chêyvâʼ"]', '["an animal beast."]', '["n-f"]', 'an animal beast.', '(Aramaic) from 2418;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2424}/[H2424]', 'lemma', 'heb', 'חַיּוּת', '["chayûwth"]', '["life × living."]', '["n-f"]', 'life × living.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2425]', 'root', 'heb', 'חָיַי', '["châyay"]', '["to live; causatively to revive live, save life."]', '["v"]', 'to live; causatively to revive live, save life.', 'a primitive root (compare 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2426}/[H2426]', 'lemma', 'heb', 'חֵיל', '["chêyl"]', '["an army; also (by analogy,) an intrenchment army, bulwark, host, poor, rampart, trench, wall."]', '["n-m"]', 'an army; also (by analogy,) an intrenchment army, bulwark, host, poor, rampart, trench, wall.', 'or (shortened) חֵל; a collateral form of 2428;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2427}/[H2427]', 'lemma', 'heb', 'חִיל', '["chîyl"]', '["a throe (expectant of childbirth) pain, pang, sorrow."]', '["n-m"]', 'a throe (expectant of childbirth) pain, pang, sorrow.', 'and (feminine) חִילָה; from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2428}/[H2428]', 'lemma', 'heb', 'חַיִל', '["chayil"]', '["probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily)."]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2429}/[H2429]', 'lemma', 'arc', 'חַיִל', '["chayil"]', '["an army, or strength aloud, army, × most (mighty), power."]', '["n-m"]', 'an army, or strength aloud, army, × most (mighty), power.', '(Aramaic) corresponding to 2428;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2430}/[H2430]', 'lemma', 'heb', 'חֵילָה', '["chêylâh"]', '["an intrenchment bulwark."]', '["n-f"]', 'an intrenchment bulwark.', 'feminine of 2428;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2431}/[H2431]', 'lemma', 'heb', 'חֵילָם', '["Chêylâm"]', '["Chelam, a place East of Palestine Helam."]', '["n-pr-m"]', 'Chelam, a place East of Palestine Helam.', 'or חֵלָאםxlit Chêlʼâm corrected to Chêlâʼm; from 2428; fortress;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2432}/[H2432]', 'lemma', 'heb', 'חִילֵן', '["Chîylên"]', '["Chilen, a place in Palestine Hilen."]', '["n-pr-loc"]', 'Chilen, a place in Palestine Hilen.', 'from 2428; fortress;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2433}/[H2433]', 'lemma', 'heb', 'חִין', '["chîyn"]', '["beauty comely."]', '["n-m"]', 'beauty comely.', 'another form for 2580;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2434}/[H2434]', 'lemma', 'heb', 'חַיִץ', '["chayits"]', '["a wall wall."]', '["n-m"]', 'a wall wall.', 'another form for 2351;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2435}/[H2435]', 'lemma', 'heb', 'חִיצוֹן', '["chîytsôwn"]', '["properly, the (outer) wall side; hence, exterior; figuratively, secular (as opposed to sacred) outer, outward, utter, without."]', '["a"]', 'properly, the (outer) wall side; hence, exterior; figuratively, secular (as opposed to sacred) outer, outward, utter, without.', 'from 2434;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2436>', 'opaque', 'heb', 'חֵיק', '["chêyq"]', '["the bosom (literally or figuratively) bosom, bottom, lap, midst, within."]', '["n-m"]', 'the bosom (literally or figuratively) bosom, bottom, lap, midst, within.', 'or חֵק; and חוֹק; from an unused root, apparently meaning to inclose;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2437}/[H2437]', 'lemma', 'heb', 'חִירָה', '["Chîyrâh"]', '["Chirah, an Adullamite Hirah."]', '["n-pr-m"]', 'Chirah, an Adullamite Hirah.', 'from 2357 in the sense of splendor;');
