INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2439}/[H2439]', 'lemma', 'heb', 'חִישׁ', '["chîysh"]', '["to hurry make haste."]', '["v"]', 'to hurry make haste.', 'another form of 2363;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2440}/[H2440]', 'lemma', 'heb', 'חִישׁ', '["chîysh"]', '["properly, a hurry; hence (adverb) quickly soon."]', '["adv"]', 'properly, a hurry; hence (adverb) quickly soon.', 'from 2439;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2441}/[H2441]', 'lemma', 'heb', 'חֵךְ', '["chêk"]', '["properly, the palate or inside of the mouth; hence, the mouth itself (as the organ of speech, taste and kissing) (roof of the) mouth, taste."]', '["n-m"]', 'properly, the palate or inside of the mouth; hence, the mouth itself (as the organ of speech, taste and kissing) (roof of the) mouth, taste.', 'probably from 2596 in the sense of tasting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2442]', 'root', 'heb', 'חָכָה', '["châkâh"]', '["properly, to adhere to; hence, to await long, tarry, wait."]', '["v"]', 'properly, to adhere to; hence, to await long, tarry, wait.', 'a primitive root (apparently akin to 2707 through the idea of piercing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2443}/[H2443]', 'lemma', 'heb', 'חַכָּה', '["chakkâh"]', '["a hook (as adhering) angle, hook."]', '["n-f"]', 'a hook (as adhering) angle, hook.', 'probably from 2442;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2444}/[H2444]', 'lemma', 'heb', 'חֲכִילָה', '["Chăkîylâh"]', '["Chakilah, a hill in Palestine Hachilah."]', '["n-pr-loc"]', 'Chakilah, a hill in Palestine Hachilah.', 'from the same as 2447; dark;');
