INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2446}/[H2446]', 'lemma', 'heb', 'חֲכַלְיָה', '["Chăkalyâh"]', '["Chakaljah, an Israelite Hachaliah."]', '["n-pr-m"]', 'Chakaljah, an Israelite Hachaliah.', 'from the base of 2447 and 3050; darkness of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2448}/[H2448]', 'lemma', 'heb', 'חַכְלִלוּת', '["chaklilûwth"]', '["flash (of the eyes); in a bad sense, blearedness redness."]', '["a"]', 'flash (of the eyes); in a bad sense, blearedness redness.', 'from 2447;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2449]', 'root', 'heb', 'חָכַם', '["châkam"]', '["to be wise (in mind, word or act) × exceeding, teach wisdom, be (make self, shew self) wise, deal (never so) wisely, make wiser."]', '["v"]', 'to be wise (in mind, word or act) × exceeding, teach wisdom, be (make self, shew self) wise, deal (never so) wisely, make wiser.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2450}/[H2450]', 'lemma', 'heb', 'חָכָם', '["châkâm"]', '["wise, (i.e. intelligent, skilful or artful) cunning (man), subtil, (un-), wise((hearted), man)."]', '["a"]', 'wise, (i.e. intelligent, skilful or artful) cunning (man), subtil, (un-), wise((hearted), man).', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2451}/[H2451]', 'lemma', 'heb', 'חׇכְמָה', '["chokmâh"]', '["wisdom (in a good sense) skilful, wisdom, wisely, wit."]', '["n-f"]', 'wisdom (in a good sense) skilful, wisdom, wisely, wit.', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2452}/[H2452]', 'lemma', 'arc', 'חׇכְמָה', '["chokmâh"]', '["wisdom wisdom."]', '["n-f"]', 'wisdom wisdom.', '(Aramaic) corresponding to 2451;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2453}/[H2453]', 'lemma', 'heb', 'חַכְמוֹנִי', '["Chakmôwnîy"]', '["Chakmoni, an Israelite Hachmoni, Hachmonite."]', '["n-pr-m"]', 'Chakmoni, an Israelite Hachmoni, Hachmonite.', 'from 2449; skilful;');
