INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2455}/[H2455]', 'lemma', 'heb', 'חֹל', '["chôl"]', '["properly, exposed; hence, profane common, profane (place), unholy."]', '["n-m"]', 'properly, exposed; hence, profane common, profane (place), unholy.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2456]', 'root', 'heb', 'חָלָא', '["châlâʼ"]', '["to be sick be diseased."]', '["v"]', 'to be sick be diseased.', 'a primitive root (compare 2470);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2457}/[H2457]', 'lemma', 'heb', 'חֶלְאָה', '["chelʼâh"]', '["properly, disease; hence, rust scum."]', '["n-f"]', 'properly, disease; hence, rust scum.', 'from 2456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2458}/[H2458]', 'lemma', 'heb', 'חֶלְאָה', '["Chelʼâh"]', '["Chelah, an Israelitess Helah."]', '["n-pr-f"]', 'Chelah, an Israelitess Helah.', 'the same as 2457;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2460}/[H2460]', 'lemma', 'heb', 'חֵלֶב', '["Chêleb"]', '["Cheleb, an Israelite Heleb."]', '["n-pr-m"]', 'Cheleb, an Israelite Heleb.', 'the same as 2459; fatness;');
