INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2469}/[H2469]', 'lemma', 'heb', 'חֶלְדַּי', '["Chelday"]', '["Cheldai, the name of two Israelites Heldai."]', '["n-pr-m"]', 'Cheldai, the name of two Israelites Heldai.', 'from 2466; worldliness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2470]', 'root', 'heb', 'חָלָה', '["châlâh"]', '["properly, to be rubbed or worn; hence (figuratively) to be weak, sick, afflicted; or (causatively) to grieve, make sick; also to stroke (in flattering), entreat beseech, (be) diseased, (put to) grief, be grieved, (be) grievous, infirmity, intreat, lay to, put to pain, × pray, make prayer, be (fall, make) sick, sore, be sorry, make suit (× supplication), woman in travail, be (become) weak, be wounded."]', '["v"]', 'properly, to be rubbed or worn; hence (figuratively) to be weak, sick, afflicted; or (causatively) to grieve, make sick; also to stroke (in flattering), entreat beseech, (be) diseased, (put to) grief, be grieved, (be) grievous, infirmity, intreat, lay to, put to pain, × pray, make prayer, be (fall, make) sick, sore, be sorry, make suit (× supplication), woman in travail, be (become) weak, be wounded.', 'a primitive root (compare 2342, 2470, 2490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2471}/[H2471]', 'lemma', 'heb', 'חַלָּה', '["challâh"]', '["a cake (as usually punctured) cake."]', '["n-f"]', 'a cake (as usually punctured) cake.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2472}/[H2472]', 'lemma', 'heb', 'חֲלוֹם', '["chălôwm"]', '["a dream dream(-er)."]', '["n-m"]', 'a dream dream(-er).', 'or (shortened) חֲלֹם; from 2492;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2473}/[H2473]', 'lemma', 'heb', 'חֹלוֹן', '["Chôlôwn"]', '["Cholon, the name of two places in Palestine Holon."]', '["n-pr-loc"]', 'Cholon, the name of two places in Palestine Holon.', 'or (shortened) חֹלֹן; probably from 2344; sandy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2475}/[H2475]', 'lemma', 'heb', 'חֲלוֹף', '["chălôwph"]', '["properly, surviving; by implication (collectively) orphans × destruction."]', '["n-m"]', 'properly, surviving; by implication (collectively) orphans × destruction.', 'from 2498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2476}/[H2476]', 'lemma', 'heb', 'חֲלוּשָׁה', '["chălûwshâh"]', '["defeat being overcome."]', '["n-f"]', 'defeat being overcome.', 'feminine passive participle of 2522;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2477>', 'opaque', 'heb', 'חֲלַח', '["Chălach"]', '["Chalach, a region of Assyria Halah."]', '["n-pr-loc"]', 'Chalach, a region of Assyria Halah.', 'probably of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2478}/[H2478]', 'lemma', 'heb', 'חַלְחוּל', '["Chalchûwl"]', '["Chalchul, a place in Palestine Halhul."]', '["n-pr-loc"]', 'Chalchul, a place in Palestine Halhul.', 'by reduplication from 2342; contorted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2479}/[H2479]', 'lemma', 'heb', 'חַלְחָלָה', '["chalchâlâh"]', '["writhing (in childbirth); by implication, terror (great, much) pain."]', '["n-f"]', 'writhing (in childbirth); by implication, terror (great, much) pain.', 'feminine from the same as 2478;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2480]', 'root', 'heb', 'חָלַט', '["châlaṭ"]', '["to snatch at catch."]', '["v"]', 'to snatch at catch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2481}/[H2481]', 'lemma', 'heb', 'חֲלִי', '["chălîy"]', '["a trinket (as polished) jewel, ornament."]', '["n-m"]', 'a trinket (as polished) jewel, ornament.', 'from 2470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2482}/[H2482]', 'lemma', 'heb', 'חֲלִי', '["Chălîy"]', '["Chali, a place in Palestine Hali."]', '["n-pr-loc"]', 'Chali, a place in Palestine Hali.', 'the same as 2481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2483}/[H2483]', 'lemma', 'heb', 'חֳלִי', '["chŏlîy"]', '["malady, anxiety, calamity disease, grief, (is) sick(-ness)."]', '["n-m"]', 'malady, anxiety, calamity disease, grief, (is) sick(-ness).', 'from 2470;');
