INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2485}/[H2485]', 'lemma', 'heb', 'חָלִיל', '["châlîyl"]', '["a flute (as perforated) pipe."]', '["n-m"]', 'a flute (as perforated) pipe.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2486}/[H2486]', 'lemma', 'heb', 'חָלִילָה', '["châlîylâh"]', '["literal for a profaned thing; used (interj.) far be it! be far, (× God) forbid."]', '["inj"]', 'literal for a profaned thing; used (interj.) far be it! be far, (× God) forbid.', 'or חָלִלָה; a directive from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2487}/[H2487]', 'lemma', 'heb', 'חֲלִיפָה', '["chălîyphâh"]', '["alternation change, course."]', '["n-f"]', 'alternation change, course.', 'from 2498;');
