INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2490]', 'root', 'heb', 'חָלַל', '["châlal"]', '["properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound."]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2491}/[H2491]', 'lemma', 'heb', 'חָלָל', '["châlâl"]', '["pierced (especially to death); figuratively, polluted kill, profane, slain (man), × slew, (deadly) wounded."]', '["n-m"]', 'pierced (especially to death); figuratively, polluted kill, profane, slain (man), × slew, (deadly) wounded.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2492]', 'root', 'heb', 'חָלַם', '["châlam"]', '["properly, to bind firmly, i.e. (by implication) to be (causatively to make) plump; also (through the figurative sense of dumbness) to dream (cause to) dream(-er), be in good liking, recover."]', '["v"]', 'properly, to bind firmly, i.e. (by implication) to be (causatively to make) plump; also (through the figurative sense of dumbness) to dream (cause to) dream(-er), be in good liking, recover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2493}/[H2493]', 'lemma', 'arc', 'חֵלֶם', '["chêlem"]', '["a dream dream."]', '["n-m"]', 'a dream dream.', '(Aramaic) from a root corresponding to 2492;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2494}/[H2494]', 'lemma', 'heb', 'חֵלֶם', '["Chêlem"]', '["Chelem, an Israelite Helem. Compare 2469."]', '["n-pr-m"]', 'Chelem, an Israelite Helem. Compare 2469.', 'from 2492; a dream;');
