INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2496}/[H2496]', 'lemma', 'heb', 'חַלָּמִישׁ', '["challâmîysh"]', '["flint flint(-y), rock."]', '["n-m"]', 'flint flint(-y), rock.', 'probably from 2492 (in the sense of hardness);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2497}/[H2497]', 'lemma', 'heb', 'חֵלֹן', '["Chêlôn"]', '["Chelon, an Israelite Helon."]', '["n-pr-m"]', 'Chelon, an Israelite Helon.', 'from 2428; strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2498]', 'root', 'heb', 'חָלַף', '["châlaph"]', '["properly, to slide by, i.e. (by implication) to hasten away, pass on, spring up, pierce or change abolish, alter, change, cut off, go on forward, grow up, be over, pass (away, on, through), renew, sprout, strike through."]', '["v"]', 'properly, to slide by, i.e. (by implication) to hasten away, pass on, spring up, pierce or change abolish, alter, change, cut off, go on forward, grow up, be over, pass (away, on, through), renew, sprout, strike through.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2499}/[H2499]', 'lemma', 'arc', 'חֲלַף', '["chălaph"]', '["to pass on (of time) pass."]', '["v"]', 'to pass on (of time) pass.', '(Aramaic) corresponding to 2498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2500}/[H2500]', 'lemma', 'heb', 'חֵלֶף', '["chêleph"]', '["properly, exchange; hence (as preposition) instead of × for."]', '["n-m"]', 'properly, exchange; hence (as preposition) instead of × for.', 'from 2498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2501}/[H2501]', 'lemma', 'heb', 'חֶלֶף', '["Cheleph"]', '["Cheleph, a place in Palestine Heleph."]', '["n-pr-loc"]', 'Cheleph, a place in Palestine Heleph.', 'the same as 2500; change;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2502]', 'root', 'heb', 'חָלַץ', '["châlats"]', '["to pull off; hence (intensively) to strip, (reflex.) to depart; by implication, to deliver, equip (for fight); present, strengthen arm (self), (go, ready) armed (× man, soldier), deliver, draw out, make fat, loose, (ready) prepared, put off, take away, withdraw self."]', '["v"]', 'to pull off; hence (intensively) to strip, (reflex.) to depart; by implication, to deliver, equip (for fight); present, strengthen arm (self), (go, ready) armed (× man, soldier), deliver, draw out, make fat, loose, (ready) prepared, put off, take away, withdraw self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2503}/[H2503]', 'lemma', 'heb', 'חֶלֶץ', '["Chelets"]', '["Chelets, the name of two Israelites Helez."]', '["n-pr-m"]', 'Chelets, the name of two Israelites Helez.', 'or חֵלֶץ; from 2502; perhaps, strength;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2504}/[H2504]', 'lemma', 'heb', 'חָלָץ', '["châlâts"]', '["the loins (as the seat of vigor) loins, reins."]', '["n-f"]', 'the loins (as the seat of vigor) loins, reins.', 'from 2502 (in the sense of strength); only in the dual;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2505]', 'root', 'heb', 'חָלַק', '["châlaq"]', '["to be smooth (figuratively); by implication (as smooth stones were used for lots) to apportion or separate deal, distribute, divide, flatter, give, (have, im-) part(-ner), take away a portion, receive, separate self, (be) smooth(-er)."]', '["v"]', 'to be smooth (figuratively); by implication (as smooth stones were used for lots) to apportion or separate deal, distribute, divide, flatter, give, (have, im-) part(-ner), take away a portion, receive, separate self, (be) smooth(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2506}/[H2506]', 'lemma', 'heb', 'חֵלֶק', '["chêleq"]', '["properly, smoothness (of the tongue); also an allotment flattery, inheritance, part, × partake, portion."]', '["n-m"]', 'properly, smoothness (of the tongue); also an allotment flattery, inheritance, part, × partake, portion.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2507}/[H2507]', 'lemma', 'heb', 'חֵלֶק', '["Chêleq"]', '["Chelek, an Israelite Helek."]', '["n-pr-m"]', 'Chelek, an Israelite Helek.', 'the same as 2506; portion;');
