INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2511}/[H2511]', 'lemma', 'heb', 'חַלָּק', '["challâq"]', '["smooth smooth."]', '["n-m"]', 'smooth smooth.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2512}/[H2512]', 'lemma', 'heb', 'חַלֻּק', '["challuq"]', '["smooth smooth."]', '["n-m"]', 'smooth smooth.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2513}/[H2513]', 'lemma', 'heb', 'חֶלְקָה', '["chelqâh"]', '["properly, smoothness; figuratively, flattery; also an allotment field, flattering(-ry), ground, parcel, part, piece of land (ground), plat, portion, slippery place, smooth (thing)."]', '["n-f"]', 'properly, smoothness; figuratively, flattery; also an allotment field, flattering(-ry), ground, parcel, part, piece of land (ground), plat, portion, slippery place, smooth (thing).', 'feminine of 2506;');
