INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2589}/[H2589]', 'lemma', 'heb', 'חַנּוֹת', '["channôwth"]', '["supplication be gracious, intreated."]', '["v"]', 'supplication be gracious, intreated.', 'from 2603 (in the sense of prayer);');
