INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2602>', 'opaque', 'heb', 'חֲנָמָל', '["chănâmâl"]', '["perhaps the aphis or plantlouse frost."]', '["n-m"]', 'perhaps the aphis or plantlouse frost.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2603]', 'root', 'heb', 'חָנַן', '["chânan"]', '["properly, to bend or stoop in kindness to an inferior; to favor, bestow; causatively to implore (i.e. move to favor by petition) beseech, × fair, (be, find, shew) favour(-able), be (deal, give, grant (gracious(-ly), intreat, (be) merciful, have (shew) mercy (on, upon), have pity upon, pray, make supplication, × very."]', '["v"]', 'properly, to bend or stoop in kindness to an inferior; to favor, bestow; causatively to implore (i.e. move to favor by petition) beseech, × fair, (be, find, shew) favour(-able), be (deal, give, grant (gracious(-ly), intreat, (be) merciful, have (shew) mercy (on, upon), have pity upon, pray, make supplication, × very.', 'a primitive root (compare 2583);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2604}/[H2604]', 'lemma', 'arc', 'חֲנַן', '["chănan"]', '["to favor or (causatively) to entreat shew mercy, make supplication."]', '["v"]', 'to favor or (causatively) to entreat shew mercy, make supplication.', '(Aramaic) corresponding to 2603;');
