INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2623}/[H2623]', 'lemma', 'heb', 'חָסִיד', '["châçîyd"]', '["properly, kind, i.e. (religiously) pious (a saint) godly (man), good, holy (one), merciful, saint, (un-) godly."]', '["a"]', 'properly, kind, i.e. (religiously) pious (a saint) godly (man), good, holy (one), merciful, saint, (un-) godly.', 'from 2616;');
