INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2625}/[H2625]', 'lemma', 'heb', 'חָסִיל', '["châçîyl"]', '["the ravager, i.e. a locust caterpillar."]', '["n-m"]', 'the ravager, i.e. a locust caterpillar.', 'from 2628;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2626}/[H2626]', 'lemma', 'heb', 'חֲסִין', '["chăçîyn"]', '["properly, firm, i.e. (by implication) mighty strong."]', '["a"]', 'properly, firm, i.e. (by implication) mighty strong.', 'from 2630;');
