INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2628]', 'root', 'heb', 'חָסַל', '["châçal"]', '["to eat off consume."]', '["v"]', 'to eat off consume.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2629]', 'root', 'heb', 'חָסַם', '["châçam"]', '["to muzzle; by analogy, to stop the nose muzzle, stop."]', '["v"]', 'to muzzle; by analogy, to stop the nose muzzle, stop.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2630]', 'root', 'heb', 'חָסַן', '["châçan"]', '["properly, to (be) compact; by implication, to hoard lay up."]', '["v"]', 'properly, to (be) compact; by implication, to hoard lay up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2631}/[H2631]', 'lemma', 'arc', 'חֲסַן', '["chăçan"]', '["to hold in occupancy possess."]', '["v"]', 'to hold in occupancy possess.', '(Aramaic) corresponding to 2630;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2632}/[H2632]', 'lemma', 'arc', 'חֵסֶן', '["chêçen"]', '["strength power."]', '["n-m"]', 'strength power.', '(Aramaic) from 2631;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2633}/[H2633]', 'lemma', 'heb', 'חֹסֶן', '["chôçen"]', '["wealth riches, strength, treasure."]', '["n-m"]', 'wealth riches, strength, treasure.', 'from 2630;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2634}/[H2634]', 'lemma', 'heb', 'חָסֹן', '["châçôn"]', '["powerful strong."]', '["a"]', 'powerful strong.', 'from 2630;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2635}/[H2635]', 'lemma', 'arc', 'חֲסַף', '["chăçaph"]', '["a clod clay."]', '["n-m"]', 'a clod clay.', '(Aramaic) from a root corresponding to that of 2636;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2637]', 'root', 'heb', 'חָסֵר', '["châçêr"]', '["to lack; by implication, to fail, want, lessen be abated, bereave, decrease, (cause to) fail, (have) lack, make lower, want."]', '["v"]', 'to lack; by implication, to fail, want, lessen be abated, bereave, decrease, (cause to) fail, (have) lack, make lower, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2638}/[H2638]', 'lemma', 'heb', 'חָסֵר', '["châçêr"]', '["lacking; hence, without destitute, fail, lack, have need, void, want."]', '["a"]', 'lacking; hence, without destitute, fail, lack, have need, void, want.', 'from 2637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2639}/[H2639]', 'lemma', 'heb', 'חֶסֶר', '["cheçer"]', '["lack; hence, destitution poverty, want."]', '["n-m"]', 'lack; hence, destitution poverty, want.', 'from 2637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2640}/[H2640]', 'lemma', 'heb', 'חֹסֶר', '["chôçer"]', '["poverty in want of."]', '["n-m"]', 'poverty in want of.', 'from 2637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2641}/[H2641]', 'lemma', 'heb', 'חַסְרָה', '["Chaçrâh"]', '["Chasrah, an Israelite Hasrah."]', '["n-pr-m"]', 'Chasrah, an Israelite Hasrah.', 'from 2637; want');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2642}/[H2642]', 'lemma', 'heb', 'חֶסְרוֹן', '["cheçrôwn"]', '["deficiency wanting."]', '["n-m"]', 'deficiency wanting.', 'from 2637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2643}/[H2643]', 'lemma', 'heb', 'חַף', '["chaph"]', '["pure innocent."]', '["a"]', 'pure innocent.', 'from 2653 (in the moral sense of covered from soil);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2644}/[H2644]', 'lemma', 'heb', 'חָפָא', '["châphâʼ"]', '["properly, to cover, i.e. (in a sinister sense) to act covertly do secretly."]', '["v"]', 'properly, to cover, i.e. (in a sinister sense) to act covertly do secretly.', 'an orthographical variation of 2645;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2645]', 'root', 'heb', 'חָפָה', '["châphâh"]', '["to cover; by implication, to veil, to encase, protect ceil, cover, overlay."]', '["v"]', 'to cover; by implication, to veil, to encase, protect ceil, cover, overlay.', 'a primitive root (compare 2644, 2653);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2646}/[H2646]', 'lemma', 'heb', 'חֻפָּה', '["chuppâh"]', '["a canopy chamber, closet, defence."]', '["n-f"]', 'a canopy chamber, closet, defence.', 'from 2645;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2647}/[H2647]', 'lemma', 'heb', 'חֻפָּה', '["Chuppâh"]', '["Chuppah, an Israelite Huppah."]', '["n-pr-m"]', 'Chuppah, an Israelite Huppah.', 'the same as 2646;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2648]', 'root', 'heb', 'חָפַז', '["châphaz"]', '["properly, to start up suddenly, i.e. (by implication) to hasten away, to fear (make) haste (away), tremble."]', '["v"]', 'properly, to start up suddenly, i.e. (by implication) to hasten away, to fear (make) haste (away), tremble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2649}/[H2649]', 'lemma', 'heb', 'חִפָּזוֹן', '["chippâzôwn"]', '["hasty flight haste."]', '["n-m"]', 'hasty flight haste.', 'from 2468;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2650}/[H2650]', 'lemma', 'heb', 'חֻפִּים', '["Chuppîym"]', '["Chuppim, an Israelite Huppim."]', '["n-pr-m"]', 'Chuppim, an Israelite Huppim.', 'plural of 2646 (compare 2349);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2652}/[H2652]', 'lemma', 'heb', 'חׇפְנִי', '["Chophnîy"]', '["Chophni, an Israelite Hophni."]', '["n-pr-m"]', 'Chophni, an Israelite Hophni.', 'from 2651; perhaps pugilist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2653]', 'root', 'heb', 'חׇפַף', '["chophaph"]', '["to cover (in protection) cover."]', '["v"]', 'to cover (in protection) cover.', 'a primitive root (compare 2645, 3182);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2654]', 'root', 'heb', 'חָפֵץ', '["châphêts"]', '["properly, to incline to; by implication (literally but rarely) to bend; figuratively, to be pleased with, desire × any at all, (have, take) delight, desire, favour, like, move, be (well) pleased, have pleasure, will, would."]', '["v"]', 'properly, to incline to; by implication (literally but rarely) to bend; figuratively, to be pleased with, desire × any at all, (have, take) delight, desire, favour, like, move, be (well) pleased, have pleasure, will, would.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2655}/[H2655]', 'lemma', 'heb', 'חָפֵץ', '["châphêts"]', '["pleased with delight in, desire, favour, please, have pleasure, whosoever would, willing, wish."]', '["a"]', 'pleased with delight in, desire, favour, please, have pleasure, whosoever would, willing, wish.', 'from 2654;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2656}/[H2656]', 'lemma', 'heb', 'חֵפֶץ', '["chêphets"]', '["pleasure; hence (abstractly) desire; concretely, a valuable thing; hence (by extension) a matter (as something in mind) acceptable, delight(-some), desire, things desired, matter, pleasant(-ure), purpose, willingly."]', '["n-m"]', 'pleasure; hence (abstractly) desire; concretely, a valuable thing; hence (by extension) a matter (as something in mind) acceptable, delight(-some), desire, things desired, matter, pleasant(-ure), purpose, willingly.', 'from 2654;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2657}/[H2657]', 'lemma', 'heb', 'חֶפְצִי בָּהּ', '["Chephtsîy bâhh"]', '["Cheptsi-bah, a fanciful name for Palestine Hephzi-bah."]', '["n-pr-f"]', 'Cheptsi-bah, a fanciful name for Palestine Hephzi-bah.', 'from 2656 with suffixes; my delight (is) in her;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2658]', 'root', 'heb', 'חָפַר', '["châphar"]', '["properly, to pry into; by implication, to delve, to explore dig, paw, search out, seek."]', '["v"]', 'properly, to pry into; by implication, to delve, to explore dig, paw, search out, seek.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2659]', 'root', 'heb', 'חָפֵר', '["châphêr"]', '["to blush; figuratively, to be ashamed, disappointed; causatively, to shame, reproach be ashamed, be confounded, be brought to confusion (unto shame), come (be put to) shame, bring reproach."]', '["v"]', 'to blush; figuratively, to be ashamed, disappointed; causatively, to shame, reproach be ashamed, be confounded, be brought to confusion (unto shame), come (be put to) shame, bring reproach.', 'a primitive root (perhaps rather the same as 2658 through the idea of detection);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2660}/[H2660]', 'lemma', 'heb', 'חֵפֶר', '["Chêpher"]', '["Chepher, a place in Palestine; also the name of three Israelites Hepher."]', '["n-pr-m n-pr-loc"]', 'Chepher, a place in Palestine; also the name of three Israelites Hepher.', 'from 2658 or 2659; a pit of shame;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2661}/[H2661]', 'lemma', 'heb', 'חֲפֹר', '["chăphôr"]', '["a burrower, i.e. probably a rat mole."]', '["n-f"]', 'a burrower, i.e. probably a rat mole.', 'from 2658; a hole; only in connection with 6512, which ought rather to be joined as one word, thus חַפַרְפֵּרָה; by reduplication from 2658;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2662}/[H2662]', 'lemma', 'heb', 'חֶפְרִי', '["Chephrîy"]', '["a Chephrite (collectively) or descendants of Chepher Hepherites."]', '["n-m"]', 'a Chephrite (collectively) or descendants of Chepher Hepherites.', 'patronymically from 2660;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2663}/[H2663]', 'lemma', 'heb', 'חֲפָרַיִם', '["Chăphârayim"]', '["Chapharajim, a place in Palestine Haphraim."]', '["n-pr-loc"]', 'Chapharajim, a place in Palestine Haphraim.', 'dual of 2660; double pit;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2664]', 'root', 'heb', 'חָפַשׂ', '["châphas"]', '["to seek; causatively, to conceal oneself (i.e. let be sought), or mask change, (make) diligent (search), disquise self, hide, search (for, out)."]', '["v"]', 'to seek; causatively, to conceal oneself (i.e. let be sought), or mask change, (make) diligent (search), disquise self, hide, search (for, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2665}/[H2665]', 'lemma', 'heb', 'חֵפֶשׂ', '["chêphes"]', '["something covert, i.e. a trick search."]', '["n-m"]', 'something covert, i.e. a trick search.', 'from 2664;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2666]', 'root', 'heb', 'חָפַשׁ', '["châphash"]', '["to spread loose; figuratively, to manumit be free."]', '["v"]', 'to spread loose; figuratively, to manumit be free.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2667}/[H2667]', 'lemma', 'heb', 'חֹפֶשׁ', '["Chôphesh"]', '["something spread loosely, i.e. a carpet precious."]', '["n-m"]', 'something spread loosely, i.e. a carpet precious.', 'from 2666;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2668}/[H2668]', 'lemma', 'heb', 'חֻפְשָׁה', '["chuphshâh"]', '["liberty (from slavery) freedom."]', '["n-f"]', 'liberty (from slavery) freedom.', 'from 2666;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2669}/[H2669]', 'lemma', 'heb', 'חׇפְשׁוּת', '["chophshûwth"]', '["prostration by sickness several."]', '["n-f"]', 'prostration by sickness several.', 'and חׇפְשִׁית; from 2666; (with 1004, a hospital)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2670}/[H2670]', 'lemma', 'heb', 'חׇפְשִׁי', '["chophshîy"]', '["exempt (from bondage, tax or care) free, liberty."]', '["a"]', 'exempt (from bondage, tax or care) free, liberty.', 'from 2666;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2671}/[H2671]', 'lemma', 'heb', 'חֵץ', '["chêts"]', '["properly, a piercer, i.e. an arrow; by implication, a wound; figuratively, (of God) thunder-bolt; the shaft of a spear archer, arrow, dart, shaft, staff, wound."]', '["n-m"]', 'properly, a piercer, i.e. an arrow; by implication, a wound; figuratively, (of God) thunder-bolt; the shaft of a spear archer, arrow, dart, shaft, staff, wound.', 'from 2686; also by interchange for 6086');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2672]', 'root', 'heb', 'חָצַב', '["châtsab"]', '["to cut or carve (wood, stone or other material); by implication, to hew, split, square, quarry, engrave cut, dig, divide, grave, hew (out, -er), made, mason."]', '["v"]', 'to cut or carve (wood, stone or other material); by implication, to hew, split, square, quarry, engrave cut, dig, divide, grave, hew (out, -er), made, mason.', 'or חָצֵב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2673]', 'root', 'heb', 'חָצָה', '["châtsâh"]', '["to cut or split in two; to halve divide, × live out half, reach to the midst, participle"]', '["v"]', 'to cut or split in two; to halve divide, × live out half, reach to the midst, participle', 'a primitive root (compare 2086));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2674}/[H2674]', 'lemma', 'heb', 'חָצוֹר', '["Châtsôwr"]', '["Chatsor, the name (thus simply) of two places in Palestine and of one in Arabia Hazor."]', '["n-pr-loc"]', 'Chatsor, the name (thus simply) of two places in Palestine and of one in Arabia Hazor.', 'a collective form of 2691; village;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2675}/[H2675]', 'lemma', 'heb', 'חָצוֹר חֲדַתָּה', '["Châtsôwr Chădattâh"]', '["new Chatsor, a place in Palestine Hazor, Hadattah (as if two places)."]', '["n-pr-loc"]', 'new Chatsor, a place in Palestine Hazor, Hadattah (as if two places).', 'from 2674 and a Aramaizing form of the feminine of 2319 (compare 2323);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2676}/[H2676]', 'lemma', 'heb', 'חָצוֹת', '["châtsôwth"]', '["the middle (of the night) mid(-night)."]', '["n-f"]', 'the middle (of the night) mid(-night).', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2677}/[H2677]', 'lemma', 'heb', 'חֵצִי', '["chêtsîy"]', '["the half or middle half, middle, mid(-night), midst, part, two parts."]', '["n-m"]', 'the half or middle half, middle, mid(-night), midst, part, two parts.', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2678}/[H2678]', 'lemma', 'heb', 'חִצִּי', '["chitstsîy"]', '["an arrow arrow."]', '["n-m"]', 'an arrow arrow.', 'or חֵצִי; prolongation from 2671;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2679}/[H2679]', 'lemma', 'heb', 'חֲצִי הַמְּנֻחוֹת', '["Chătsîy ham-Mᵉnuchôwth"]', '["Chatsi-ham-Menuchoth, an Israelite half of the Manahethites."]', '["n-pr-m"]', 'Chatsi-ham-Menuchoth, an Israelite half of the Manahethites.', 'from 2677 and the plural of 4496, with the article interposed; midst of the resting-places;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2680}/[H2680]', 'lemma', 'heb', 'חֲצִי הַמְּנַחְתִּי', '["Chătsîy ham-Mᵉnachtîy"]', '["a Chatsi-ham-Menachtite or descendant of Chatsi-ham-Menuchoth half of the Manahethites."]', '["n-pr-m"]', 'a Chatsi-ham-Menachtite or descendant of Chatsi-ham-Menuchoth half of the Manahethites.', 'patronymically from 2679;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2681}/[H2681]', 'lemma', 'heb', 'חָצִיר', '["châtsîyr"]', '["a court or abode court."]', '["n-m"]', 'a court or abode court.', 'a collateral form of 2691;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2682}/[H2682]', 'lemma', 'heb', 'חָצִיר', '["châtsîyr"]', '["grass; also a leek (collectively) grass, hay, herb, leek."]', '["n-m"]', 'grass; also a leek (collectively) grass, hay, herb, leek.', 'perhaps originally the same as 2681, from the greenness of a courtyard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2683>', 'opaque', 'heb', 'חֵצֶן', '["chêtsen"]', '["the bosom (as comprised between the arms) bosom."]', '["n-m"]', 'the bosom (as comprised between the arms) bosom.', 'from an unused root meaning to hold firmly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2684}/[H2684]', 'lemma', 'heb', 'חֹצֶן', '["chôtsen"]', '["arm, lap."]', '["n-m"]', 'arm, lap.', 'a collateral form of 2683, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2685]', 'root', 'arc', 'חֲצַף', '["chătsaph"]', '["properly, to shear or cut close; figuratively, to be severe hasty, be urgent."]', '["v"]', 'properly, to shear or cut close; figuratively, to be severe hasty, be urgent.', '(Aramaic) a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2686]', 'root', 'heb', 'חָצַץ', '["châtsats"]', '["properly, to chop into, pierce or sever; hence, to curtail, to distribute (into ranks); to shoot an arrow archer, × bands, cut off in the midst."]', '["v"]', 'properly, to chop into, pierce or sever; hence, to curtail, to distribute (into ranks); to shoot an arrow archer, × bands, cut off in the midst.', 'a primitive root (compare 2673); also as denominative from 2671');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2687}/[H2687]', 'lemma', 'heb', 'חָצָץ', '["châtsâts"]', '["properly, something cutting; hence, gravel (as grit); an arrow arrow, gravel (stone)."]', '["n-m"]', 'properly, something cutting; hence, gravel (as grit); an arrow arrow, gravel (stone).', 'from 2687; also like 2671');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2688}/[H2688]', 'lemma', 'heb', 'חַצְצוֹן תָּמָר', '["Chatsᵉtsôwn Tâmâr"]', '["Chatsetson-tamar, a place in Palestine Hazezon-tamar."]', '["n-pr-loc"]', 'Chatsetson-tamar, a place in Palestine Hazezon-tamar.', 'or חַצֲצֹן תָּמָר; from 2686 and 8558; division (i.e. perhaps row) of (the) palm-tree;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2689}/[H2689]', 'lemma', 'heb', 'חֲצֹצְרָה', '["chătsôtsᵉrâh"]', '["a trumpet (from its sundered or quavering note) trumpet(-er)."]', '["n-f"]', 'a trumpet (from its sundered or quavering note) trumpet(-er).', 'by reduplication from 2690;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2690]', 'root', 'heb', 'חָצַר', '["châtsar"]', '["to trumpet, i.e. blow on that instrument blow, sound, trumpeter."]', '["v"]', 'to trumpet, i.e. blow on that instrument blow, sound, trumpeter.', 'a primitive root; properly, to surround with a stockade, and thus separate from the open country; but used only in the reduplicated form חֲצֹצֵר; or (2 Chronicles 5:12) חֲצֹרֵר; as dem. from 2689;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2691}/[H2691]', 'lemma', 'heb', 'חָצֵר', '["châtsêr"]', '["a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village."]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2692}/[H2692]', 'lemma', 'heb', 'חֲצַר אַדָּר', '["Chătsar ʼAddâr"]', '["Chatsar-Addar, a place in Palestine Hazar-addar."]', '["n-pr-loc"]', 'Chatsar-Addar, a place in Palestine Hazar-addar.', 'from 2691 and 146; (the) village of Addar;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2693}/[H2693]', 'lemma', 'heb', 'חֲצַר גַּדָּה', '["Chătsar Gaddâh"]', '["Chatsar-Gaddah, a place in Palestine Hazar-gaddah."]', '["n-pr-loc"]', 'Chatsar-Gaddah, a place in Palestine Hazar-gaddah.', 'from 2691 and a feminine of 1408; (the) village of (female) Fortune;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2694}/[H2694]', 'lemma', 'heb', 'חֲצַר הַתִּיכוֹן', '["Chătsar hat-Tîykôwn"]', '["Chatsar-hat-Tikon, a place in Palestine Hazar-hatticon."]', '["n-pr-loc"]', 'Chatsar-hat-Tikon, a place in Palestine Hazar-hatticon.', 'from 2691 and 8484 with the article interposed; village of the middle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2695}/[H2695]', 'lemma', 'heb', 'חֶצְרוֹ', '["Chetsrôw"]', '["Chetsro, an Israelite Hezro, Hezrai."]', '["n-pr-m"]', 'Chetsro, an Israelite Hezro, Hezrai.', 'by an orthographical variation for 2696; enclosure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2696}/[H2696]', 'lemma', 'heb', 'חֶצְרוֹן', '["Chetsrôwn"]', '["Chetsron, the name of a place in Palestine; also of two Israelites Hezron."]', '["n-pr-m n-pr-loc"]', 'Chetsron, the name of a place in Palestine; also of two Israelites Hezron.', 'from 2691; court-yard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2697}/[H2697]', 'lemma', 'heb', 'חֶצְרוֹנִי', '["Chetsrôwnîy"]', '["a Chetsronite or (collectively) descendants of Chetsron Hezronites."]', '["n-m"]', 'a Chetsronite or (collectively) descendants of Chetsron Hezronites.', 'patronymically from 2696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2698}/[H2698]', 'lemma', 'heb', 'חֲצֵרוֹת', '["Chătsêrôwth"]', '["Chatseroth, a place in Palestine Hazeroth."]', '["n-pr-loc"]', 'Chatseroth, a place in Palestine Hazeroth.', 'feminine plural of 2691; yards;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2699}/[H2699]', 'lemma', 'heb', 'חֲצֵרִים', '["Chătsêrîym"]', '["Chatserim, a place in Palestine Hazerim"]', '["n-pr-loc"]', 'Chatserim, a place in Palestine Hazerim', 'plural masculine of 2691; yards;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2700}/[H2700]', 'lemma', 'heb', 'חֲצַרְמָוֶת', '["Chătsarmâveth"]', '["Chatsarmaveth, a place in Arabia Hazarmaveth."]', '["n-pr-m"]', 'Chatsarmaveth, a place in Arabia Hazarmaveth.', 'from 2691 and 4194; village of death;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2701}/[H2701]', 'lemma', 'heb', 'חֲצַר סוּסָה', '["Chătsar Çûwçâh"]', '["Chatsar-Susah, a place in Palestine Hazar-susah."]', '["n-pr-loc"]', 'Chatsar-Susah, a place in Palestine Hazar-susah.', 'from 2691 and 5484; village of cavalry;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2702}/[H2702]', 'lemma', 'heb', 'חֲצַר סוּסִים', '["Chătsar Çûwçîym"]', '["Chatsar-Susim, a place in Palestine Hazar-susim."]', '["n-pr-loc"]', 'Chatsar-Susim, a place in Palestine Hazar-susim.', 'from 2691 and the plural of 5483; village of horses;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2703}/[H2703]', 'lemma', 'heb', 'חֲצַר עֵינוֹן', '["Chătsar ʻÊynôwn"]', '["Chatsar-Enon, a place in Palestine Hazar-enon."]', '["n-pr-loc"]', 'Chatsar-Enon, a place in Palestine Hazar-enon.', 'from 2691 and a derivative of 5869; village of springs;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2704}/[H2704]', 'lemma', 'heb', 'חֲצַר עֵינָן', '["Chătsar ʻÊynân"]', '["Chatsar-Enan, a place in Palestine Hazar-enan."]', '["n-pr-loc"]', 'Chatsar-Enan, a place in Palestine Hazar-enan.', 'from 2691 and the same as 5881; village of springs;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2705}/[H2705]', 'lemma', 'heb', 'חֲצַר שׁוּעָל', '["Chătsar Shûwʻâl"]', '["Chatsar-Shual, a place in Palestine Hazar-shual."]', '["n-pr-loc"]', 'Chatsar-Shual, a place in Palestine Hazar-shual.', 'from 2691 and 7776; village of (the) fox;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2706}/[H2706]', 'lemma', 'heb', 'חֹק', '["chôq"]', '["an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task."]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2707]', 'root', 'heb', 'חָקָה', '["châqâh"]', '["to carve; by implication, to delineate; also to entrench carved work, portrayed, set a print."]', '["v"]', 'to carve; by implication, to delineate; also to entrench carved work, portrayed, set a print.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2708}/[H2708]', 'lemma', 'heb', 'חֻקָּה', '["chuqqâh"]', '["appointed, custom, manner, ordinance, site, statute."]', '["n-f"]', 'appointed, custom, manner, ordinance, site, statute.', 'feminine of 2706, and meaning substantially the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2710]', 'root', 'heb', 'חָקַק', '["châqaq"]', '["properly, to hack, i.e. engrave (Judges 5:14, to be a scribe simply); by implication, to enact (laws being cut in stone or metal tablets in primitive times) or (gen.) prescribe appoint, decree, governor, grave, lawgiver, note, pourtray, print, set."]', '["v"]', 'properly, to hack, i.e. engrave (Judges 5:14, to be a scribe simply); by implication, to enact (laws being cut in stone or metal tablets in primitive times) or (gen.) prescribe appoint, decree, governor, grave, lawgiver, note, pourtray, print, set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2711}/[H2711]', 'lemma', 'heb', 'חֵקֶק', '["chêqeq"]', '["an enactment, a resolution decree, thought."]', '["n-m"]', 'an enactment, a resolution decree, thought.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2712}/[H2712]', 'lemma', 'heb', 'חֻקֹּק', '["Chuqqôq"]', '["Chukkok or Chukok, a place in Palestine Hukkok, Hukok."]', '["n-pr-loc"]', 'Chukkok or Chukok, a place in Palestine Hukkok, Hukok.', 'or (fully) חוּקֹק; from 2710; appointed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2713]', 'root', 'heb', 'חָקַר', '["châqar"]', '["properly, to penetrate; hence, to examine intimately find out, (make) search (out), seek (out), sound, try."]', '["v"]', 'properly, to penetrate; hence, to examine intimately find out, (make) search (out), seek (out), sound, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2714}/[H2714]', 'lemma', 'heb', 'חֵקֶר', '["chêqer"]', '["examination, enumeration, deliberation finding out, number, (un-) search(-able, -ed, out, -ing)."]', '["n-m"]', 'examination, enumeration, deliberation finding out, number, (un-) search(-able, -ed, out, -ing).', 'from 2713;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2715}/[H2715]', 'lemma', 'heb', 'חֹר', '["chôr"]', '["properly, white or pure (from the cleansing or shining power of fire); hence (figuratively) noble (in rank) noble."]', '["n-m"]', 'properly, white or pure (from the cleansing or shining power of fire); hence (figuratively) noble (in rank) noble.', 'or (fully) חוֹר; from 2787; (compare 2751)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2716}/[H2716]', 'lemma', 'heb', 'חֶרֶא', '["chereʼ"]', '["excrement dung. Also חֲרִי."]', '["n-m"]', 'excrement dung. Also חֲרִי.', 'from an unused (and vulgar) root probably meaning to evacuate the bowels;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2717]', 'root', 'heb', 'חָרַב', '["chârab"]', '["to parch (through drought) i.e. (by analogy,) to desolate, destroy, kill decay, (be) desolate, destroy(-er), (be) dry (up), slay, × surely, (lay, lie, make) waste."]', '["v"]', 'to parch (through drought) i.e. (by analogy,) to desolate, destroy, kill decay, (be) desolate, destroy(-er), (be) dry (up), slay, × surely, (lay, lie, make) waste.', 'or חֲרֵב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2718}/[H2718]', 'lemma', 'arc', 'חֲרַב', '["chărab"]', '["to demolish destroy."]', '["v"]', 'to demolish destroy.', '(Aramaic) a root corresponding to 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2719}/[H2719]', 'lemma', 'heb', 'חֶרֶב', '["chereb"]', '["drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool."]', '["n-f"]', 'drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2720}/[H2720]', 'lemma', 'heb', 'חָרֵב', '["chârêb"]', '["parched or ruined desolate, dry, waste."]', '["a"]', 'parched or ruined desolate, dry, waste.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2721}/[H2721]', 'lemma', 'heb', 'חֹרֶב', '["chôreb"]', '["drought or desolation desolation, drought, dry, heat, × utterly, waste."]', '["n-m"]', 'drought or desolation desolation, drought, dry, heat, × utterly, waste.', 'a collaterally form of 2719;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2722}/[H2722]', 'lemma', 'heb', 'חֹרֵב', '["Chôrêb"]', '["Choreb, a (generic) name for the Sinaitic mountains Horeb."]', '["n-pr-loc"]', 'Choreb, a (generic) name for the Sinaitic mountains Horeb.', 'from 2717; desolate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2723}/[H2723]', 'lemma', 'heb', 'חׇרְבָּה', '["chorbâh"]', '["properly, drought, i.e. (by implication) a desolation decayed place, desolate (place, -tion), destruction, (laid) waste (place)."]', '["n-f"]', 'properly, drought, i.e. (by implication) a desolation decayed place, desolate (place, -tion), destruction, (laid) waste (place).', 'feminine of 2721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2724}/[H2724]', 'lemma', 'heb', 'חָרָבָה', '["chârâbâh"]', '["a desert dry (ground, land)."]', '["n-f"]', 'a desert dry (ground, land).', 'feminine of 2720;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2725}/[H2725]', 'lemma', 'heb', 'חֲרָבוֹן', '["chărâbôwn"]', '["parching heat drought."]', '["n-m"]', 'parching heat drought.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2726}/[H2726]', 'lemma', 'heb', 'חַרְבוֹנָא', '["Charbôwnâʼ"]', '["Charbona or Charbonah, a eunuch of Xerxes Harbona, Harbonah."]', '["n-pr-m"]', 'Charbona or Charbonah, a eunuch of Xerxes Harbona, Harbonah.', 'or חַרְבוֹנָה; of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2727]', 'root', 'heb', 'חָרַג', '["chârag"]', '["properly, to leap suddenly, i.e. (by implication) to be dismayed be afraid."]', '["v"]', 'properly, to leap suddenly, i.e. (by implication) to be dismayed be afraid.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2728}/[H2728]', 'lemma', 'heb', 'חָרְגֹּל', '["chârᵉgôl"]', '["the leaping insect, i.e. a locust beetle."]', '["n-m"]', 'the leaping insect, i.e. a locust beetle.', 'from 2727;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2729]', 'root', 'heb', 'חָרַד', '["chârad"]', '["to shudder with terror; hence, to fear; also to hasten (with anxiety) be (make) afraid, be careful, discomfit, fray (away), quake, tremble."]', '["v"]', 'to shudder with terror; hence, to fear; also to hasten (with anxiety) be (make) afraid, be careful, discomfit, fray (away), quake, tremble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2730}/[H2730]', 'lemma', 'heb', 'חָרֵד', '["chârêd"]', '["fearful; also reverential afraid, trembling."]', '["a"]', 'fearful; also reverential afraid, trembling.', 'from 2729;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2731}/[H2731]', 'lemma', 'heb', 'חֲרָדָה', '["chărâdâh"]', '["fear, anxiety care, × exceedingly, fear, quaking, trembling."]', '["n-f"]', 'fear, anxiety care, × exceedingly, fear, quaking, trembling.', 'feminine of 2730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2732}/[H2732]', 'lemma', 'heb', 'חֲרָדָה', '["Chărâdâh"]', '["Charadah, a place in the Desert Haradah."]', '["n-pr-loc"]', 'Charadah, a place in the Desert Haradah.', 'the same as 2731;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2733}/[H2733]', 'lemma', 'heb', 'חֲרֹדִי', '["Chărôdîy"]', '["a Charodite, or inhabitant of Charod Harodite."]', '["n-m"]', 'a Charodite, or inhabitant of Charod Harodite.', 'patrial from a derivative of 2729 (compare 5878);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2734]', 'root', 'heb', 'חָרָה', '["chârâh"]', '["to glow or grow warm; figuratively (usually) to blaze up, of anger, zeal, jealousy be angry, burn, be displeased, × earnestly, fret self, grieve, be (wax) hot, be incensed, kindle, × very, be wroth. See 8474."]', '["v"]', 'to glow or grow warm; figuratively (usually) to blaze up, of anger, zeal, jealousy be angry, burn, be displeased, × earnestly, fret self, grieve, be (wax) hot, be incensed, kindle, × very, be wroth. See 8474.', 'a primitive root (compare 2787);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2735}/[H2735]', 'lemma', 'heb', 'חֹר הַגִּדְגָּד', '["Chôr hag-Gidgâd"]', '["Chor-hag-Gidgad, a place in the Desert Hor-hagidgad."]', '["n-pr-loc"]', 'Chor-hag-Gidgad, a place in the Desert Hor-hagidgad.', 'from 2356 and a collateral (masculine) form of 1412, with the article interposed; hole of the cleft;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2736}/[H2736]', 'lemma', 'heb', 'חַרְהֲיָה', '["Charhăyâh"]', '["Charhajah, an Israelite Harhaiah."]', '["n-pr-m"]', 'Charhajah, an Israelite Harhaiah.', '; from 2734 and 3050; fearing Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2737>', 'opaque', 'heb', 'חָרוּז', '["chârûwz"]', '["properly, pierced, i.e. a bead of pearl, gems or jewels (as strung) chain."]', '["n-m"]', 'properly, pierced, i.e. a bead of pearl, gems or jewels (as strung) chain.', 'from an unused root meaning to perforate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2739}/[H2739]', 'lemma', 'heb', 'חֲרוּמַף', '["chărûwmaph"]', '["Charumaph, an Israelite Harumaph."]', '["n-pr-m"]', 'Charumaph, an Israelite Harumaph.', 'from passive participle of 2763 and 639; snub-nosed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2740}/[H2740]', 'lemma', 'heb', 'חָרוֹן', '["chârôwn"]', '["a burning of anger sore displeasure, fierce(-ness), fury, (fierce) wrath(-ful)."]', '["n-m"]', 'a burning of anger sore displeasure, fierce(-ness), fury, (fierce) wrath(-ful).', 'or (shortened) חָרֹן; from 2734;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2741}/[H2741]', 'lemma', 'heb', 'חֲרוּפִי', '["Chărûwphîy"]', '["a Charuphite or inhabitant of Charuph (or Chariph) Haruphite."]', '["n-m"]', 'a Charuphite or inhabitant of Charuph (or Chariph) Haruphite.', 'a patrial from (probably) a collateral form of 2756;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2742}/[H2742]', 'lemma', 'heb', 'חֲרוּץ', '["chărûwts"]', '["properly, incised or (active) incisive; hence (as noun masculine or feminine) a trench (as dug), gold (as mined), a threshing-sledge (having sharp teeth); (figuratively) determination; also eager decision, diligent, (fine) gold, pointed things, sharp, threshing instrument, wall."]', '["a"]', 'properly, incised or (active) incisive; hence (as noun masculine or feminine) a trench (as dug), gold (as mined), a threshing-sledge (having sharp teeth); (figuratively) determination; also eager decision, diligent, (fine) gold, pointed things, sharp, threshing instrument, wall.', 'or חָרֻץ; passive participle of 2782;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2743}/[H2743]', 'lemma', 'heb', 'חָרוּץ', '["Chârûwts"]', '["Charuts, an Israelite Haruz."]', '["n-pr-m"]', 'Charuts, an Israelite Haruz.', 'the same as 2742; earnest;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2744}/[H2744]', 'lemma', 'heb', 'חַרְחוּר', '["Charchûwr"]', '["Charchur, one of the Nethinim Harhur."]', '["n-pr-m"]', 'Charchur, one of the Nethinim Harhur.', 'a fuller form of 2746; inflammation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2745}/[H2745]', 'lemma', 'heb', 'חַרְחַס', '["Charchaç"]', '["Charchas, an Israelite Harhas."]', '["n-pr-m"]', 'Charchas, an Israelite Harhas.', 'from the same as 2775; perhaps shining;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2746}/[H2746]', 'lemma', 'heb', 'חַרְחֻר', '["charchur"]', '["fever (as hot) extreme burning."]', '["n-m"]', 'fever (as hot) extreme burning.', 'from 2787;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2747]', 'root', 'heb', 'חֶרֶט', '["chereṭ"]', '["a chisel or graver; also a style for writing graving tool, pen."]', '["n-m"]', 'a chisel or graver; also a style for writing graving tool, pen.', 'from a primitive root meaning to engrave;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2748}/[H2748]', 'lemma', 'heb', 'חַרְטֹם', '["charṭôm"]', '["a horoscopist (as drawing magical lines or circles) magician."]', '["n-m"]', 'a horoscopist (as drawing magical lines or circles) magician.', 'from the same as 2747;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2749}/[H2749]', 'lemma', 'arc', 'חַרְטֹם', '["charṭôm"]', '["magician."]', '["n-m"]', 'magician.', '(Aramaic) the same as 2748');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2750}/[H2750]', 'lemma', 'heb', 'חֳרִי', '["chŏrîy"]', '["a burning (i.e. intense) anger fierce, × great, heat."]', '["n-m"]', 'a burning (i.e. intense) anger fierce, × great, heat.', 'from 2734;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2751}/[H2751]', 'lemma', 'heb', 'חֹרִי', '["chôrîy"]', '["white bread white."]', '["n-m"]', 'white bread white.', 'from the same as 2353;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2752}/[H2752]', 'lemma', 'heb', 'חֹרִי', '["Chôrîy"]', '["a Chorite or aboriginal Idumaean Horims, Horites."]', '["n-m"]', 'a Chorite or aboriginal Idumaean Horims, Horites.', 'from 2356; cave-dweller or troglodyte;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2753}/[H2753]', 'lemma', 'heb', 'חֹרִי', '["Chôrîy"]', '["Chori, the name of two men Hori."]', '["n-pr-m"]', 'Chori, the name of two men Hori.', 'or חוֹרִי; the same as 2752;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2754}/[H2754]', 'lemma', 'heb', 'חָרִיט', '["chârîyṭ"]', '["properly, cut out (or hollow), i.e. (by implication) a pocket bag, crisping pin."]', '["n-m"]', 'properly, cut out (or hollow), i.e. (by implication) a pocket bag, crisping pin.', 'or חָרִט; from the same as 2747;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2755}/[H2755]', 'lemma', 'heb', 'חֲרֵי־יוֹנִים', '["chărêy-yôwnîym"]', '["excrements of doves doves'' dung."]', '["n-m"]', 'excrements of doves doves'' dung.', 'from the plural of 2716 and the plural of 3123; or perhaps rather the plural of a single word חֲרָאיוֹן, probably a kind of vegetable');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2756}/[H2756]', 'lemma', 'heb', 'חָרִיף', '["Chârîyph"]', '["Chariph, the name of two Israelites Hariph."]', '["n-pr-m"]', 'Chariph, the name of two Israelites Hariph.', 'from 2778; autumnal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2757}/[H2757]', 'lemma', 'heb', 'חָרִיץ', '["chârîyts"]', '["properly, incisure or (passively) incised; hence, a threshing-sledge (with sharp teeth); also a slice (as cut) cheese, harrow."]', '["n-m"]', 'properly, incisure or (passively) incised; hence, a threshing-sledge (with sharp teeth); also a slice (as cut) cheese, harrow.', 'or חֲרִץ; from 2782; (compare 2742)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2758}/[H2758]', 'lemma', 'heb', 'חָרִישׁ', '["chârîysh"]', '["ploughing or its season earing (time), ground."]', '["n-m"]', 'ploughing or its season earing (time), ground.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2759}/[H2759]', 'lemma', 'heb', 'חֲרִישִׁי', '["chărîyshîy"]', '["quiet, i.e. sultry (as feminine noun, the sirocco or hot east wind) vehement."]', '["a"]', 'quiet, i.e. sultry (as feminine noun, the sirocco or hot east wind) vehement.', 'from 2790 in the sense of silence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2760]', 'root', 'heb', 'חָרַךְ', '["chârak"]', '["to braid (i.e. to entangle or snare) or catch (game) in a net roast."]', '["v"]', 'to braid (i.e. to entangle or snare) or catch (game) in a net roast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2761}/[H2761]', 'lemma', 'arc', 'חֲרַךְ', '["chărak"]', '["to scorch singe."]', '["v"]', 'to scorch singe.', '(Aramaic) a root probably allied to the equivalent of 2787;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2762}/[H2762]', 'lemma', 'heb', 'חֶרֶךְ', '["cherek"]', '["properly, a net, i.e. (by analogy) lattice lattice."]', '["n-m"]', 'properly, a net, i.e. (by analogy) lattice lattice.', 'from 2760;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2763]', 'root', 'heb', 'חָרַם', '["châram"]', '["to seclude; specifically (by a ban) to devote to religious uses (especially destruction); physical and reflexive, to be blunt as to the nose make accursed, consecrate, (utterly) destroy, devote, forfeit, have a flat nose, utterly (slay, make away)."]', '["v"]', 'to seclude; specifically (by a ban) to devote to religious uses (especially destruction); physical and reflexive, to be blunt as to the nose make accursed, consecrate, (utterly) destroy, devote, forfeit, have a flat nose, utterly (slay, make away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2764}/[H2764]', 'lemma', 'heb', 'חֵרֶם', '["chêrem"]', '["physical (as shutting in) a net (either literally or figuratively); usually a doomed object; abstractly extermination (ac-) curse(-d, -d thing), dedicated thing, things which should have been utterly destroyed, (appointed to) utter destruction, devoted (thing), net."]', '["n-m"]', 'physical (as shutting in) a net (either literally or figuratively); usually a doomed object; abstractly extermination (ac-) curse(-d, -d thing), dedicated thing, things which should have been utterly destroyed, (appointed to) utter destruction, devoted (thing), net.', 'or (Zechariah 14:11) חֶרֶם; from 2763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2765}/[H2765]', 'lemma', 'heb', 'חֳרֵם', '["Chŏrêm"]', '["Chorem, a place in Palestine Horem."]', '["n-pr-loc"]', 'Chorem, a place in Palestine Horem.', 'from 2763; devoted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2766}/[H2766]', 'lemma', 'heb', 'חָרִם', '["Chârim"]', '["Charim, an Israelite Harim."]', '["n-pr-m"]', 'Charim, an Israelite Harim.', 'from 2763; snub-nosed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2767}/[H2767]', 'lemma', 'heb', 'חׇרְמָה', '["Chormâh"]', '["Chormah, a place in Palestine Hormah."]', '["n-pr-loc"]', 'Chormah, a place in Palestine Hormah.', 'from 2763; devoted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2768}/[H2768]', 'lemma', 'heb', 'חֶרְמוֹן', '["Chermôwn"]', '["Chermon, a mount of Palestine Hermon."]', '["n-pr-m"]', 'Chermon, a mount of Palestine Hermon.', 'from 2763; abrupt;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2769}/[H2769]', 'lemma', 'heb', 'חֶרְמוֹנִים', '["Chermôwnîym"]', '["Hermons, i.e. its peaks the Hermonites."]', '["n-pr-m"]', 'Hermons, i.e. its peaks the Hermonites.', 'plural of 2768;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2770}/[H2770]', 'lemma', 'heb', 'חֶרְמֵשׁ', '["chermêsh"]', '["a sickle (as cutting) sickle."]', '["n-m"]', 'a sickle (as cutting) sickle.', 'from 2763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2771}/[H2771]', 'lemma', 'heb', 'חָרָן', '["Chârân"]', '["Charan, the name of a man and also of a place Haran."]', '["n-pr-m n-pr-loc"]', 'Charan, the name of a man and also of a place Haran.', 'from 2787; parched;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2772}/[H2772]', 'lemma', 'heb', 'חֹרֹנִי', '["Chôrônîy"]', '["a Choronite or inhabitant of Choronaim Horonite."]', '["n-m"]', 'a Choronite or inhabitant of Choronaim Horonite.', 'patrial from 2773;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2773}/[H2773]', 'lemma', 'heb', 'חֹרֹנַיִם', '["Chôrônayim"]', '["Choronajim, a place in Moab Horonaim."]', '["n-pr-m"]', 'Choronajim, a place in Moab Horonaim.', 'dual of a derivative from 2356; double cave-town;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2774>', 'opaque', 'heb', 'חַרְנֶפֶר', '["Charnepher"]', '["Charnepher, an Israelite Harnepher."]', '["n-pr-m"]', 'Charnepher, an Israelite Harnepher.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2775>', 'opaque', 'heb', 'חֶרֶס', '["chereç"]', '["the sun sun."]', '["n-m"]', 'the sun sun.', 'or (with a directive enclitic) חַרְסָה; from an unused root meaning to scrape; also perhaps from the mediating idea of 2777');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2776}/[H2776]', 'lemma', 'heb', 'חֶרֶס', '["Chereç"]', '["Cheres, a mountain in Palestine Heres."]', '["n-pr-loc"]', 'Cheres, a mountain in Palestine Heres.', 'the same as 2775; shining;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2777}/[H2777]', 'lemma', 'heb', 'חַרְסוּת', '["charçûwth"]', '["a potsherd, i.e. (by implication) a pottery; the name of a gate at Jerusalem east."]', '["n-f"]', 'a potsherd, i.e. (by implication) a pottery; the name of a gate at Jerusalem east.', 'from 2775 (apparently in the sense of a red tile used for scraping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2778]', 'root', 'heb', 'חָרַף', '["châraph"]', '["to pull off, i.e. (by implication) to expose (as by stripping); specifically, to betroth (as if a surrender); figuratively, to carp at, i.e. defame; to spend the winter betroth, blaspheme, defy, jeopard, rail, reproach, upbraid."]', '["v"]', 'to pull off, i.e. (by implication) to expose (as by stripping); specifically, to betroth (as if a surrender); figuratively, to carp at, i.e. defame; to spend the winter betroth, blaspheme, defy, jeopard, rail, reproach, upbraid.', 'a primitive root; also denominative (from 2779)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2779}/[H2779]', 'lemma', 'heb', 'חֹרֶף', '["chôreph"]', '["properly, the crop gathered, i.e. (by implication) the autumn (and winter) season; figuratively, ripeness of age cold, winter (-house), youth."]', '["n-m"]', 'properly, the crop gathered, i.e. (by implication) the autumn (and winter) season; figuratively, ripeness of age cold, winter (-house), youth.', 'from 2778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2780}/[H2780]', 'lemma', 'heb', 'חָרֵף', '["Chârêph"]', '["Chareph, an Israelite Hareph."]', '["n-pr-m"]', 'Chareph, an Israelite Hareph.', 'from 2778; reproachful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2781}/[H2781]', 'lemma', 'heb', 'חֶרְפָּה', '["cherpâh"]', '["contumely, disgrace, the pudenda rebuke, reproach(-fully), shame."]', '["n-f"]', 'contumely, disgrace, the pudenda rebuke, reproach(-fully), shame.', 'from 2778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2782]', 'root', 'heb', 'חָרַץ', '["chârats"]', '["properly, to point sharply, i.e. (literally) to wound; figuratively, to be alert, to decide bestir self, decide, decree, determine, maim, move."]', '["v"]', 'properly, to point sharply, i.e. (literally) to wound; figuratively, to be alert, to decide bestir self, decide, decree, determine, maim, move.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2783}/[H2783]', 'lemma', 'arc', 'חֲרַץ', '["chărats"]', '["the loin (as the seat of strength) loin."]', '["n-f"]', 'the loin (as the seat of strength) loin.', '(Aramaic) from a root corresponding to 2782 in the sense of vigor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2785}/[H2785]', 'lemma', 'heb', 'חַרְצַן', '["chartsan"]', '["a sour grape (as sharp in taste) kernel."]', '["n-m"]', 'a sour grape (as sharp in taste) kernel.', 'from 2782;');
