INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2789}/[H2789]', 'lemma', 'heb', 'חֶרֶשׂ', '["cheres"]', '["a piece of pottery earth(-en), (pot-) sherd, stone."]', '["n-m"]', 'a piece of pottery earth(-en), (pot-) sherd, stone.', 'a collateral form mediating between 2775 and 2791;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2790]', 'root', 'heb', 'חָרַשׁ', '["chârash"]', '["to scratch, i.e. (by implication) to engrave, plough; hence (from the use of tools) to fabricate (of any material); figuratively, to devise (in a bad sense); hence (from the idea of secrecy) to be silent, to let alone; hence (by implication) to be deaf (as an accompaniment of dumbness) × altogether, cease, conceal, be deaf, devise, ear, graven, imagine, leave off speaking, hold peace, plow(-er, man), be quiet, rest, practise secretly, keep silence, be silent, speak not a word, be still, hold tongue, worker."]', '["v"]', 'to scratch, i.e. (by implication) to engrave, plough; hence (from the use of tools) to fabricate (of any material); figuratively, to devise (in a bad sense); hence (from the idea of secrecy) to be silent, to let alone; hence (by implication) to be deaf (as an accompaniment of dumbness) × altogether, cease, conceal, be deaf, devise, ear, graven, imagine, leave off speaking, hold peace, plow(-er, man), be quiet, rest, practise secretly, keep silence, be silent, speak not a word, be still, hold tongue, worker.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2791}/[H2791]', 'lemma', 'heb', 'חֶרֶשׁ', '["cheresh"]', '["magical craft; also silence cunning, secretly."]', '["adv"]', 'magical craft; also silence cunning, secretly.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2792}/[H2792]', 'lemma', 'heb', 'חֶרֶשׁ', '["Cheresh"]', '["Cheresh, a Levite Heresh."]', '["n-pr-m"]', 'Cheresh, a Levite Heresh.', 'the same as 2791');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2793}/[H2793]', 'lemma', 'heb', 'חֹרֶשׁ', '["chôresh"]', '["a forest (perhaps as furnishing the material for fabric) bough, forest, shroud, wood."]', '["n-m"]', 'a forest (perhaps as furnishing the material for fabric) bough, forest, shroud, wood.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2794}/[H2794]', 'lemma', 'heb', 'חֹרֵשׁ', '["chôrêsh"]', '["a fabricator or mechanic artificer."]', '["n-m"]', 'a fabricator or mechanic artificer.', 'active participle of 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2795}/[H2795]', 'lemma', 'heb', 'חֵרֵשׁ', '["chêrêsh"]', '["deaf (whether literally or spiritual) deaf."]', '["a"]', 'deaf (whether literally or spiritual) deaf.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2796}/[H2796]', 'lemma', 'heb', 'חָרָשׁ', '["chârâsh"]', '["a fabricator or any material artificer, ( ) carpenter, craftsman, engraver, maker, mason, skilful, ( ) smith, worker, workman, such as wrought."]', '["n-m"]', 'a fabricator or any material artificer, ( ) carpenter, craftsman, engraver, maker, mason, skilful, ( ) smith, worker, workman, such as wrought.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2797}/[H2797]', 'lemma', 'heb', 'חַרְשָׁא', '["Charshâʼ"]', '["Charsha, one of the Nethinim Harsha."]', '["n-pr-m"]', 'Charsha, one of the Nethinim Harsha.', 'from 2792; magician;');
