INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2802}/[H2802]', 'lemma', 'heb', 'חֶרֶת', '["Chereth"]', '["Chereth, a thicket in Palestine Hereth."]', '["n-pr-loc"]', 'Chereth, a thicket in Palestine Hereth.', 'from 2801 (but equivalent to 2793); forest;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2803]', 'root', 'heb', 'חָשַׁב', '["châshab"]', '["properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think."]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2804}/[H2804]', 'lemma', 'arc', 'חֲשַׁב', '["chăshab"]', '["to regard repute."]', '["v"]', 'to regard repute.', '(Aramaic) corresponding to 2803;');
