INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2812}/[H2812]', 'lemma', 'heb', 'חֲשַׁבְנָה', '["Chăshabnâh"]', '["Chashnah, an Israelite Hashabnah."]', '["n-pr-m"]', 'Chashnah, an Israelite Hashabnah.', 'feminine of 2808; inventiveness;');
