INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2815}/[H2815]', 'lemma', 'heb', 'חַשּׁוּב', '["Chashshûwb"]', '["Chashshub, the name of two or three Israelites Hashub, Hasshub."]', '["n-pr-m"]', 'Chashshub, the name of two or three Israelites Hashub, Hasshub.', 'from 2803; intelligent;');
