INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2818}/[H2818]', 'lemma', 'arc', 'חֲשַׁח', '["chăshach"]', '["to be necessary (from the idea of convenience) or (transitively) to need careful, have need of."]', '["v n-f"]', 'to be necessary (from the idea of convenience) or (transitively) to need careful, have need of.', '(Aramaic) a collateral root to one corresponding to 2363 in the sense of readiness;');
