INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2824}/[H2824]', 'lemma', 'heb', 'חֶשְׁכָה', '["cheshkâh"]', '["darkness dark."]', '["n-f"]', 'darkness dark.', 'from 2821;');
