INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2829}/[H2829]', 'lemma', 'heb', 'חֶשְׁמוֹן', '["Cheshmôwn"]', '["Cheshmon, a place in Palestine Heshmon."]', '["n-pr-loc"]', 'Cheshmon, a place in Palestine Heshmon.', 'the same as 2831; opulent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2832}/[H2832]', 'lemma', 'heb', 'חַשְׁמֹנָה', '["Chashmônâh"]', '["Chasmonah, a place in the Desert Hashmonah."]', '["n-pr-loc"]', 'Chasmonah, a place in the Desert Hashmonah.', 'feminine of 2831; fertile;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2834]', 'root', 'heb', 'חָשַׂף', '["châsaph"]', '["to strip off, i.e. generally to make naked (for exertion or in disgrace), to drain away or bail up (a liquid) make bare, clean, discover, draw out, take, uncover."]', '["v"]', 'to strip off, i.e. generally to make naked (for exertion or in disgrace), to drain away or bail up (a liquid) make bare, clean, discover, draw out, take, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2835}/[H2835]', 'lemma', 'heb', 'חָשִׂף', '["châsiph"]', '["properly, drawn off, i.e. separated; hence, a small company (as divided from the rest) little flock."]', '["n-m"]', 'properly, drawn off, i.e. separated; hence, a small company (as divided from the rest) little flock.', 'from 2834;');
