INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2896}/[H2896]', 'lemma', 'heb', 'טוֹב', '["ṭôwb"]', '["good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured)."]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2897}/[H2897]', 'lemma', 'heb', 'טוֹב', '["Ṭôwb"]', '["Tob, a region apparently East of the Jordan Tob."]', '["n-pr-loc"]', 'Tob, a region apparently East of the Jordan Tob.', 'the same as 2896; good;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2898}/[H2898]', 'lemma', 'heb', 'טוּב', '["ṭûwb"]', '["good (as a noun), in the widest sense, especially goodness (superlative concretely, the best), beauty, gladness, welfare fair, gladness, good(-ness, thing, -s), joy, go well with."]', '["n-m"]', 'good (as a noun), in the widest sense, especially goodness (superlative concretely, the best), beauty, gladness, welfare fair, gladness, good(-ness, thing, -s), joy, go well with.', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2899}/[H2899]', 'lemma', 'heb', 'טוֹב אֲדֹנִיָּהוּ', '["Ṭôwb ʼĂdônîyâhûw"]', '["Tob-Adonijah, an Israelite Tob-adonijah."]', '["n-pr-m"]', 'Tob-Adonijah, an Israelite Tob-adonijah.', 'from 2896 and 138; pleasing (to) Adonijah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2900}/[H2900]', 'lemma', 'heb', 'טוֹבִיָּה', '["Ṭôwbîyâh"]', '["Tobijah, the name of three Israelites and of one Samaritan Tobiah, Tobijah."]', '["n-pr-m"]', 'Tobijah, the name of three Israelites and of one Samaritan Tobiah, Tobijah.', 'or טוֹבִיָּהוּ; from 2896 and 3050; goodness of Jehovah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2901]', 'root', 'heb', 'טָוָה', '["ṭâvâh"]', '["to spin spin."]', '["v"]', 'to spin spin.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2902]', 'root', 'heb', 'טוּחַ', '["ṭûwach"]', '["to smear, especially with lime daub, overlay, plaister, smut."]', '["v"]', 'to smear, especially with lime daub, overlay, plaister, smut.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2903>', 'opaque', 'heb', 'טוֹפָפָה', '["ṭôwphâphâh"]', '["a fillet for the forehead frontlet."]', '["n-f"]', 'a fillet for the forehead frontlet.', 'from an unused root meaning to go around or bind;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2904]', 'root', 'heb', 'טוּל', '["ṭûwl"]', '["to pitch over or reel; hence (transitively) to cast down or out carry away, (utterly) cast (down, forth, out), send out."]', '["v"]', 'to pitch over or reel; hence (transitively) to cast down or out carry away, (utterly) cast (down, forth, out), send out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2906}/[H2906]', 'lemma', 'arc', 'טוּר', '["ṭûwr"]', '["a rock or hill mountain."]', '["n-m"]', 'a rock or hill mountain.', '(Aramaic) corresponding to 6697;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2907]', 'root', 'heb', 'טוּשׂ', '["ṭûws"]', '["to pounce as a bird of prey haste."]', '["v"]', 'to pounce as a bird of prey haste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2908}/[H2908]', 'lemma', 'arc', 'טְוָת', '["ṭᵉvâth"]', '["hunger (as twisting) fasting."]', '["adv"]', 'hunger (as twisting) fasting.', '(Aramaic) from a root corresponding to 2901;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2909]', 'root', 'heb', 'טָחָה', '["ṭâchâh"]', '["to stretch a bow, as an archer (bow-) shot."]', '["v"]', 'to stretch a bow, as an archer (bow-) shot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2910}/[H2910]', 'lemma', 'heb', 'טֻחָה', '["ṭuchâh"]', '["(in the plural only) the kidneys (as being covered); hence (figuratively) the inmost thought inward parts."]', '["n-f"]', '(in the plural only) the kidneys (as being covered); hence (figuratively) the inmost thought inward parts.', 'from 2909 (or 2902) in the sense of overlaying;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2911}/[H2911]', 'lemma', 'heb', 'טְחוֹן', '["ṭᵉchôwn"]', '["a hand mill; hence, a millstone to grind."]', '["n-m"]', 'a hand mill; hence, a millstone to grind.', 'from 2912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2912]', 'root', 'heb', 'טָחַן', '["ṭâchan"]', '["to grind meal; hence, to be a concubine (that being their employment) grind(-er)."]', '["v"]', 'to grind meal; hence, to be a concubine (that being their employment) grind(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2913}/[H2913]', 'lemma', 'heb', 'טַחֲנָה', '["ṭachănâh"]', '["a hand mill; hence (figuratively) chewing grinding."]', '["n-f"]', 'a hand mill; hence (figuratively) chewing grinding.', 'from 2912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2915}/[H2915]', 'lemma', 'heb', 'טִיחַ', '["ṭîyach"]', '["mortar or plaster daubing."]', '["n-m"]', 'mortar or plaster daubing.', 'from (the equiv. of) 2902;');
