INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2918}/[H2918]', 'lemma', 'heb', 'טִירָה', '["ṭîyrâh"]', '["a wall; hence, a fortress or a hamlet (goodly) castle, habitation, palace, row."]', '["n-f"]', 'a wall; hence, a fortress or a hamlet (goodly) castle, habitation, palace, row.', 'feminine of (an equivalent to) 2905;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2919}/[H2919]', 'lemma', 'heb', 'טַל', '["ṭal"]', '["dew (as covering vegetation) dew."]', '["n-m"]', 'dew (as covering vegetation) dew.', 'from 2926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2920}/[H2920]', 'lemma', 'arc', 'טַל', '["ṭal"]', '["dew."]', '["n-m"]', 'dew.', '(Aramaic) the same as 2919');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2921]', 'root', 'heb', 'טָלָא', '["ṭâlâʼ"]', '["properly, to cover with pieces; i.e. (by implication) to spot or variegate (as tapestry) clouted, with divers colours, spotted."]', '["v"]', 'properly, to cover with pieces; i.e. (by implication) to spot or variegate (as tapestry) clouted, with divers colours, spotted.', 'a primitive root;');
