INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2932}/[H2932]', 'lemma', 'heb', 'טֻמְאָה', '["ṭumʼâh"]', '["religious impurity filthiness, unclean(-ness)."]', '["n-f"]', 'religious impurity filthiness, unclean(-ness).', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2933}/[H2933]', 'lemma', 'heb', 'טָמָה', '["ṭâmâh"]', '["to be impure in a religious sense be defiled, be reputed vile."]', '["v"]', 'to be impure in a religious sense be defiled, be reputed vile.', 'a collateral form of 2930;');
