INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2935>', 'opaque', 'heb', 'טֶנֶא', '["ṭeneʼ"]', '["a basket (of interlaced osiers) basket."]', '["n-m"]', 'a basket (of interlaced osiers) basket.', 'from an unused root probably meaning to weave;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2936]', 'root', 'heb', 'טָנַף', '["ṭânaph"]', '["to soil defile."]', '["v"]', 'to soil defile.', 'a primitive root;');
