INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2938]', 'root', 'heb', 'טָעַם', '["ṭâʻam"]', '["to taste; figuratively, to perceive × but, perceive, taste."]', '["v"]', 'to taste; figuratively, to perceive × but, perceive, taste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2939}/[H2939]', 'lemma', 'arc', 'טְעַם', '["ṭᵉʻam"]', '["to taste; causatively to feed make to eat, feed."]', '["v"]', 'to taste; causatively to feed make to eat, feed.', '(Aramaic) corresponding to 2938;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2940}/[H2940]', 'lemma', 'heb', 'טַעַם', '["ṭaʻam"]', '["properly, a taste, i.e. (figuratively) perception; by implication, intelligence; transitively, a mandate advice, behaviour, decree, discretion, judgment, reason, taste, understanding."]', '["n-m"]', 'properly, a taste, i.e. (figuratively) perception; by implication, intelligence; transitively, a mandate advice, behaviour, decree, discretion, judgment, reason, taste, understanding.', 'from 2938;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2941}/[H2941]', 'lemma', 'arc', 'טַעַם', '["ṭaʻam"]', '["properly, a taste, i.e. a judicial sentence account, × to be commanded, commandment, matter."]', '["n-m"]', 'properly, a taste, i.e. a judicial sentence account, × to be commanded, commandment, matter.', '(Aramaic) from 2939; compare 2940)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2942}/[H2942]', 'lemma', 'arc', 'טְעֵם', '["ṭᵉʻêm"]', '["properly, flavor; figuratively, judgment (both subjective and objective); hence, account (both subjectively and objectively) chancellor, command, commandment, decree, regard, taste, wisdom."]', '["n-m"]', 'properly, flavor; figuratively, judgment (both subjective and objective); hence, account (both subjectively and objectively) chancellor, command, commandment, decree, regard, taste, wisdom.', '(Aramaic) from 2939, and equivalent to 2941;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2943]', 'root', 'heb', 'טָעַן', '["ṭâʻan"]', '["to load a beast lade."]', '["v"]', 'to load a beast lade.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2944]', 'root', 'heb', 'טָעַן', '["ṭâʻan"]', '["to stab thrust through."]', '["v"]', 'to stab thrust through.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2945}/[H2945]', 'lemma', 'heb', 'טַף', '["ṭaph"]', '["a family (mostly used collectively in the singular) (little) children (ones), families."]', '["n-m"]', 'a family (mostly used collectively in the singular) (little) children (ones), families.', 'from 2952 (perhaps referring to the tripping gait of children);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2946]', 'root', 'heb', 'טָפַח', '["ṭâphach"]', '["to flatten out or extend (as a tent); figuratively, to nurse a child (as promotive of growth); span, swaddle."]', '["v"]', 'to flatten out or extend (as a tent); figuratively, to nurse a child (as promotive of growth); span, swaddle.', 'a primitive root; or perhaps a denominative from 2947, from dandling on the palms');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2947}/[H2947]', 'lemma', 'heb', 'טֵפַח', '["ṭêphach"]', '["a spread of the hand, i.e. a palm-breadth (not ''span'' of the fingers); architecturally, a corbel (as a supporting palm) coping, hand-breadth."]', '["n-m"]', 'a spread of the hand, i.e. a palm-breadth (not ''span'' of the fingers); architecturally, a corbel (as a supporting palm) coping, hand-breadth.', 'from 2946;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2948}/[H2948]', 'lemma', 'heb', 'טֹפַח', '["ṭôphach"]', '["(the same as 2947) hand-breadth (broad)."]', '["n-m"]', '(the same as 2947) hand-breadth (broad).', 'from 2946');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2949}/[H2949]', 'lemma', 'heb', 'טִפֻּח', '["ṭippuch"]', '["nursing span long."]', '["n-m"]', 'nursing span long.', 'from 2946;');
