INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H2952]', 'root', 'heb', 'טָפַף', '["ṭâphaph"]', '["to trip (with short steps) coquettishly mince."]', '["v"]', 'to trip (with short steps) coquettishly mince.', 'a primitive root; apparently');
