INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3009]', 'root', 'heb', 'יָגַב', '["yâgab"]', '["to dig or plow husbandman."]', '["v"]', 'to dig or plow husbandman.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3010}/[H3010]', 'lemma', 'heb', 'יָגֵב', '["yâgêb"]', '["a plowed field field."]', '["n-m"]', 'a plowed field field.', 'from 3009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3011}/[H3011]', 'lemma', 'heb', 'יׇגְבְּהָה', '["Yogbᵉhâh"]', '["Jogbehah, a place East of the Jordan Jogbehah."]', '["n-f"]', 'Jogbehah, a place East of the Jordan Jogbehah.', 'feminine from 1361; hillock;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3012}/[H3012]', 'lemma', 'heb', 'יִגְדַּלְיָהוּ', '["Yigdalyâhûw"]', '["Jigdaljah, an Israelite Igdaliah."]', '["n-pr-m"]', 'Jigdaljah, an Israelite Igdaliah.', 'from 1431 and 3050; magnified of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3013]', 'root', 'heb', 'יָגָה', '["yâgâh"]', '["to grieve afflict, cause grief, grieve, sorrowful, vex."]', '["v"]', 'to grieve afflict, cause grief, grieve, sorrowful, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3014]', 'root', 'heb', 'יָגָה', '["yâgâh"]', '["to push away be removed."]', '["v"]', 'to push away be removed.', 'a primitive root (probably rather the same as 3013 through the common idea of dissatisfaction);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3015}/[H3015]', 'lemma', 'heb', 'יָגוֹן', '["yâgôwn"]', '["affliction grief, sorrow."]', '["n-m"]', 'affliction grief, sorrow.', 'from 3013;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3016}/[H3016]', 'lemma', 'heb', 'יָגוֹר', '["yâgôwr"]', '["fearful afraid, fearest."]', '["a"]', 'fearful afraid, fearest.', 'from 3025;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3017}/[H3017]', 'lemma', 'heb', 'יָגוּר', '["Yâgûwr"]', '["Jagur, a place in Palestine Jagur."]', '["n-pr-loc"]', 'Jagur, a place in Palestine Jagur.', 'probably from 1481; a lodging;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3018}/[H3018]', 'lemma', 'heb', 'יְגִיעַ', '["yᵉgîyaʻ"]', '["toil; hence, a work, produce, property (as the result of labor) labour, work."]', '["n-m"]', 'toil; hence, a work, produce, property (as the result of labor) labour, work.', 'from 3021;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3019}/[H3019]', 'lemma', 'heb', 'יָגִיעַ', '["yâgîyaʻ"]', '["tired weary."]', '["a"]', 'tired weary.', 'from 3021;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3020}/[H3020]', 'lemma', 'heb', 'יׇגְלִי', '["Yoglîy"]', '["Jogli, an Israelite Jogli."]', '["n-pr-m"]', 'Jogli, an Israelite Jogli.', 'from 1540; exiled;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3021]', 'root', 'heb', 'יָגַע', '["yâgaʻ"]', '["properly, to gasp; hence, to be exhausted, to tire, to toil faint, (make to) labour, (be) weary."]', '["v"]', 'properly, to gasp; hence, to be exhausted, to tire, to toil faint, (make to) labour, (be) weary.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3022}/[H3022]', 'lemma', 'heb', 'יָגָע', '["yâgâʻ"]', '["earnings (as the product of toil) that which he laboured for."]', '["n-m"]', 'earnings (as the product of toil) that which he laboured for.', 'from 3021;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3023}/[H3023]', 'lemma', 'heb', 'יָגֵעַ', '["yâgêaʻ"]', '["tired; hence (transitive) tiresome full of labour, weary."]', '["a"]', 'tired; hence (transitive) tiresome full of labour, weary.', 'from 3021;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3024}/[H3024]', 'lemma', 'heb', 'יְגִעָה', '["yᵉgiʻâh"]', '["fatigue weariness."]', '["n-f"]', 'fatigue weariness.', 'feminine of 3019;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3025]', 'root', 'heb', 'יָגֹר', '["yâgôr"]', '["to fear be afraid, fear."]', '["v"]', 'to fear be afraid, fear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3026>', 'opaque', 'heb', 'יְגַר שַׂהֲדוּתָא', '["Yᵉgar Sahădûwthâʼ"]', '["Jegar-Sahadutha, a cairn East of the Jordan Jegar-Sahadutha."]', '["n-pr-loc"]', 'Jegar-Sahadutha, a cairn East of the Jordan Jegar-Sahadutha.', '(Aramaic) from a word derived from an unused root (meaning to gather) and a derivation of a root corresponding to 7717; heap of the testimony;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3027]', 'root', 'heb', 'יָד', '["yâd"]', '["a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves."]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3028}/[H3028]', 'lemma', 'arc', 'יַד', '["yad"]', '["hand, power."]', '["n-f"]', 'hand, power.', '(Aramaic) corresponding to 3027');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3029}/[H3029]', 'lemma', 'arc', 'יְדָא', '["yᵉdâʼ"]', '["to praise (give) thank(-s)."]', '["v"]', 'to praise (give) thank(-s).', '(Aramaic) corresponding to 3034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3030>', 'opaque', 'heb', 'יִדְאֲלָה', '["Yidʼălâh"]', '["Jidalah, a place in Palestine Idalah."]', '["n-pr-loc"]', 'Jidalah, a place in Palestine Idalah.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3031}/[H3031]', 'lemma', 'heb', 'יִדְבָּשׁ', '["Yidbâsh"]', '["Jidbash, an Israelite Idbash."]', '["n-pr-m"]', 'Jidbash, an Israelite Idbash.', 'from the same as 1706; perhaps honeyed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3032]', 'root', 'heb', 'יָדַד', '["yâdad"]', '["properly, to handle, i.e. to throw, e.g. lots cast."]', '["v"]', 'properly, to handle, i.e. to throw, e.g. lots cast.', 'a primitive root; (compare 3034)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3033}/[H3033]', 'lemma', 'heb', 'יְדִדוּת', '["yᵉdidûwth"]', '["properly, affection; concretely, a darling object dearly beloved."]', '["n-f"]', 'properly, affection; concretely, a darling object dearly beloved.', 'from 3039;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3034]', 'root', 'heb', 'יָדָה', '["yâdâh"]', '["physically, to throw (a stone, an arrow) at or away; especially to revere or worship (with extended hands); intensively, to bemoan (by wringing the hands) cast (out), (make) confess(-ion), praise, shoot, (give) thank(-ful, -s, -sgiving)."]', '["v"]', 'physically, to throw (a stone, an arrow) at or away; especially to revere or worship (with extended hands); intensively, to bemoan (by wringing the hands) cast (out), (make) confess(-ion), praise, shoot, (give) thank(-ful, -s, -sgiving).', 'a primitive root; used only as denominative from 3027; literally, to use (i.e. hold out) the hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3035}/[H3035]', 'lemma', 'heb', 'יִדּוֹ', '["Yiddôw"]', '["Jiddo, an Israelite Iddo."]', '["n-pr-m"]', 'Jiddo, an Israelite Iddo.', 'from 3034; praised;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3036}/[H3036]', 'lemma', 'heb', 'יָדוֹן', '["Yâdôwn"]', '["Jadon, an Israelite Jadon."]', '["n-pr-m"]', 'Jadon, an Israelite Jadon.', 'from 3034; thankful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3037}/[H3037]', 'lemma', 'heb', 'יַדּוּעַ', '["Yaddûwaʻ"]', '["Jaddua, the name of two Israelites Jaddua."]', '["n-pr-m"]', 'Jaddua, the name of two Israelites Jaddua.', 'from 3045; knowing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3038}/[H3038]', 'lemma', 'heb', 'יְדוּתוּן', '["Yᵉdûwthûwn"]', '["Jeduthun, an Israelite Jeduthun."]', '["n-pr-m"]', 'Jeduthun, an Israelite Jeduthun.', 'or יְדֻתוּן; or יְדִיתוּן; probably from 3034; laudatory;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3039}/[H3039]', 'lemma', 'heb', 'יְדִיד', '["yᵉdîyd"]', '["loved amiable, (well-) beloved, loves."]', '["a n-f"]', 'loved amiable, (well-) beloved, loves.', 'from the same as 1730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3040}/[H3040]', 'lemma', 'heb', 'יְדִידָה', '["Yᵉdîydâh"]', '["Jedidah, an Israelitess Jedidah."]', '["n-pr-f"]', 'Jedidah, an Israelitess Jedidah.', 'feminine of 3039; beloved;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3041}/[H3041]', 'lemma', 'heb', 'יְדִידְיָה', '["Yᵉdîydᵉyâh"]', '["Jedidejah, a name of Solomon Jedidiah."]', '["n-pr-m"]', 'Jedidejah, a name of Solomon Jedidiah.', 'from 3039 and 3050; beloved of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3042}/[H3042]', 'lemma', 'heb', 'יְדָיָה', '["Yᵉdâyâh"]', '["Jedajah, the name of two Israelites Jedaiah."]', '["n-pr-m"]', 'Jedajah, the name of two Israelites Jedaiah.', 'from 3034 and 3050; praised of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3043}/[H3043]', 'lemma', 'heb', 'יְדִיעֲאֵל', '["Yᵉdîyʻăʼêl"]', '["Jediael, the name of three Israelites Jediael."]', '["n-pr-m"]', 'Jediael, the name of three Israelites Jediael.', 'from 3045 and 410; knowing God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3044}/[H3044]', 'lemma', 'heb', 'יִדְלָף', '["Yidlâph"]', '["Jidlaph, a Mesopotamian Jidlaph."]', '["n-pr-m"]', 'Jidlaph, a Mesopotamian Jidlaph.', 'from 1811; tearful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3045]', 'root', 'heb', 'יָדַע', '["yâdaʻ"]', '["to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot."]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3046}/[H3046]', 'lemma', 'arc', 'יְדַע', '["yᵉdaʻ"]', '["certify, know, make known, teach."]', '["v"]', 'certify, know, make known, teach.', '(Aramaic) corresponding to 3045');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3047}/[H3047]', 'lemma', 'heb', 'יָדָע', '["Yâdâʻ"]', '["Jada, an Israelite Jada."]', '["n-pr-m"]', 'Jada, an Israelite Jada.', 'from 3045; knowing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3048}/[H3048]', 'lemma', 'heb', 'יְדַעְיָה', '["Yᵉdaʻyâh"]', '["Jedajah, the name of two Israelites Jedaiah."]', '["n-pr-m"]', 'Jedajah, the name of two Israelites Jedaiah.', 'from 3045 and 3050; Jah has known;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3049}/[H3049]', 'lemma', 'heb', 'יִדְּעֹנִי', '["yiddᵉʻônîy"]', '["properly, a knowing one; specifically, a conjurer; (by impl) a ghost wizard."]', '["n-m"]', 'properly, a knowing one; specifically, a conjurer; (by impl) a ghost wizard.', 'from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3050}/[H3050]', 'lemma', 'heb', 'יָהּ', '["Yâhh"]', '["Jah, the sacred name Jah, the Lord, most vehement. Compare names in ''-iah,'' ''-jah.''"]', '["n-pr"]', 'Jah, the sacred name Jah, the Lord, most vehement. Compare names in ''-iah,'' ''-jah.''', 'contraction for 3068, and meaning the same;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3051]', 'root', 'heb', 'יָהַב', '["yâhab"]', '["to give (whether literal or figurative); generally, to put; imperatively (reflexive) come ascribe, bring, come on, give, go, set, take."]', '["v"]', 'to give (whether literal or figurative); generally, to put; imperatively (reflexive) come ascribe, bring, come on, give, go, set, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3052}/[H3052]', 'lemma', 'arc', 'יְהַב', '["yᵉhab"]', '["deliver, give, lay, prolong, pay, yield."]', '["v"]', 'deliver, give, lay, prolong, pay, yield.', '(Aramaic) corresponding to 3051');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3053}/[H3053]', 'lemma', 'heb', 'יְהָב', '["yᵉhâb"]', '["properly, what is given (by Providence), i.e. a lot burden."]', '["n-m"]', 'properly, what is given (by Providence), i.e. a lot burden.', 'from 3051;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3054}/[H3054]', 'lemma', 'heb', 'יָהַד', '["yâhad"]', '["to Judaize, i.e. become Jewish become Jews."]', '["v"]', 'to Judaize, i.e. become Jewish become Jews.', 'denominative from a form corresponding to 3061;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3055}/[H3055]', 'lemma', 'heb', 'יְהֻד', '["Yᵉhud"]', '["Jehud, a place in Palestine Jehud."]', '["n-pr-loc"]', 'Jehud, a place in Palestine Jehud.', 'a briefer form of one corresponding to 3061;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3056}/[H3056]', 'lemma', 'heb', 'יֶהְדַי', '["Yehday"]', '["Jehdai, an Israelite Jehdai."]', '["n-pr-m"]', 'Jehdai, an Israelite Jehdai.', 'perhaps from a form corresponding to 3061; Judaistic;');
