INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3106}/[H3106]', 'lemma', 'heb', 'יוּבַל', '["Yûwbal"]', '["Jubal, an antediluvian Jubal."]', '["n-pr-m"]', 'Jubal, an antediluvian Jubal.', 'from 2986; stream;');
