INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3108}/[H3108]', 'lemma', 'heb', 'יוֹזָכָר', '["Yôwzâkâr"]', '["Jozacar, an Israelite Jozachar."]', '["n-pr-m"]', 'Jozacar, an Israelite Jozachar.', 'from 3068 and 2142; Jehovah-remembered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3109}/[H3109]', 'lemma', 'heb', 'יוֹחָא', '["Yôwchâʼ"]', '["Jocha, the name of two Israelites Joha."]', '["n-pr-m"]', 'Jocha, the name of two Israelites Joha.', 'probably from 3068 and a variation of 2421; Jehovah-revived;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3110}/[H3110]', 'lemma', 'heb', 'יוֹחָנָן', '["Yôwchânân"]', '["Jochanan, the name of nine Israelites Johanan."]', '["n-pr-m"]', 'Jochanan, the name of nine Israelites Johanan.', 'a form of 3076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3111}/[H3111]', 'lemma', 'heb', 'יוֹיָדָע', '["Yôwyâdâʻ"]', '["Jojada, the name of two Israelites Jehoiada, Joiada."]', '["n-pr-m"]', 'Jojada, the name of two Israelites Jehoiada, Joiada.', 'a form of 3077;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3112}/[H3112]', 'lemma', 'heb', 'יוֹיָכִין', '["Yôwyâkîyn"]', '["Jojakin, an Israelite king Jehoiachin."]', '["n-pr-m"]', 'Jojakin, an Israelite king Jehoiachin.', 'a form of 3078;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3113}/[H3113]', 'lemma', 'heb', 'יוֹיָקִים', '["Yôwyâqîym"]', '["Jojakim, an Israelite Joiakim. Compare 3137."]', '["n-pr-m"]', 'Jojakim, an Israelite Joiakim. Compare 3137.', 'a form of 3079;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3114}/[H3114]', 'lemma', 'heb', 'יוֹיָרִיב', '["Yôwyârîyb"]', '["Jojarib, the name of four Israelites Joiarib."]', '["n-pr-m"]', 'Jojarib, the name of four Israelites Joiarib.', 'a form of 3080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3115}/[H3115]', 'lemma', 'heb', 'יוֹכֶבֶד', '["Yôwkebed"]', '["Jokebed, the mother of Moses Jochebed."]', '["n-pr-f"]', 'Jokebed, the mother of Moses Jochebed.', 'from 3068 contracted and 3513; Jehovah-gloried;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3116}/[H3116]', 'lemma', 'heb', 'יוּכַל', '["Yûwkal"]', '["Jukal, an Israelite Jucal."]', '["n-pr-m"]', 'Jukal, an Israelite Jucal.', 'a form of 3081;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117>', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger."]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3118}/[H3118]', 'lemma', 'arc', 'יוֹם', '["yôwm"]', '["a day day (by day), time."]', '["n-m"]', 'a day day (by day), time.', '(Aramaic) corresponding to 3117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3119}/[H3119]', 'lemma', 'heb', 'יוֹמָם', '["yôwmâm"]', '["daily daily, (by, in the) day(-time)."]', '["adv"]', 'daily daily, (by, in the) day(-time).', 'from 3117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3120}/[H3120]', 'lemma', 'heb', 'יָוָן', '["Yâvân"]', '["Javan, the name of a son of Joktan, and of the race (Ionians, i.e. Greeks) descended from him, with their territory; also of a place in Arabia Javan."]', '["n-pr-m n-pr-loc"]', 'Javan, the name of a son of Joktan, and of the race (Ionians, i.e. Greeks) descended from him, with their territory; also of a place in Arabia Javan.', 'probably from the same as 3196; effervescing (i.e. hot and active);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3121}/[H3121]', 'lemma', 'heb', 'יָוֵן', '["yâvên"]', '["properly, dregs (as effervescing); hence, mud mire, miry."]', '["n-m"]', 'properly, dregs (as effervescing); hence, mud mire, miry.', 'from the same as 3196;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3122}/[H3122]', 'lemma', 'heb', 'יוֹנָדָב', '["Yôwnâdâb"]', '["Jonadab, the name of an Israelite and of a Rechabite Jonadab."]', '["n-pr-m"]', 'Jonadab, the name of an Israelite and of a Rechabite Jonadab.', 'a form of 3082;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3123}/[H3123]', 'lemma', 'heb', 'יוֹנָה', '["yôwnâh"]', '["a dove (apparently from the warmth of their mating) dove, pigeon."]', '["n-f"]', 'a dove (apparently from the warmth of their mating) dove, pigeon.', 'probably from the same as 3196;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3124}/[H3124]', 'lemma', 'heb', 'יוֹנָה', '["Yôwnâh"]', '["Jonah, an Israelite Jonah."]', '["n-pr-m"]', 'Jonah, an Israelite Jonah.', 'the same as 3123;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3125}/[H3125]', 'lemma', 'heb', 'יְוָנִי', '["Yᵉvânîy"]', '["a Jevanite, or descendant of Javan Grecian."]', '["a"]', 'a Jevanite, or descendant of Javan Grecian.', 'patronymically from 3121;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3126}/[H3126]', 'lemma', 'heb', 'יוֹנֵק', '["yôwnêq"]', '["a sucker; hence, a twig (of a tree felled and sprouting) tender plant."]', '["n-m"]', 'a sucker; hence, a twig (of a tree felled and sprouting) tender plant.', 'active participle of 3243;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3127}/[H3127]', 'lemma', 'heb', 'יוֹנֶקֶת', '["yôwneqeth"]', '["a sprout (tender) branch, young twig."]', '["n-f"]', 'a sprout (tender) branch, young twig.', 'feminine of 3126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3128}/[H3128]', 'lemma', 'heb', 'יוֹנַת אֵלֶם רְחֹקִים', '["yôwnath ʼêlem rᵉchôqîym"]', '["dove of (the) silence (i.e. dumb Israel) of (i.e. among) distances (i.e. strangers); the title of a ditty (used for a name of its melody) Jonath-elem-rechokim."]', '["n"]', 'dove of (the) silence (i.e. dumb Israel) of (i.e. among) distances (i.e. strangers); the title of a ditty (used for a name of its melody) Jonath-elem-rechokim.', 'from 3123 and 482 and the plural of 7350;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3129}/[H3129]', 'lemma', 'heb', 'יוֹנָתָן', '["Yôwnâthân"]', '["Jonathan, the name of ten Israelites Jonathan."]', '["n-pr-m"]', 'Jonathan, the name of ten Israelites Jonathan.', 'a form of 3083;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3130}/[H3130]', 'lemma', 'heb', 'יוֹסֵף', '["Yôwçêph"]', '["Joseph, the name of seven Israelites Joseph. Compare 3084."]', '["n-pr-m"]', 'Joseph, the name of seven Israelites Joseph. Compare 3084.', 'future of 3254; let him add (or perhaps simply active participle adding);');
