INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3132}/[H3132]', 'lemma', 'heb', 'יוֹעֵאלָה', '["Yôwʻêʼlâh"]', '["Joelah, an Israelite Joelah."]', '["n-pr-f"]', 'Joelah, an Israelite Joelah.', 'perhaps feminine active participle of 3276; furthermore;');
