INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3134}/[H3134]', 'lemma', 'heb', 'יוֹעֶזֶר', '["Yôwʻezer"]', '["Joezer, an Israelite Joezer."]', '["n-pr-m"]', 'Joezer, an Israelite Joezer.', 'from 3068 and 5828; Jehovah (is his) help;');
