INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3140}/[H3140]', 'lemma', 'heb', 'יוֹרַי', '["Yôwray"]', '["Jorai, an Israelite Jorai."]', '["n-pr-m"]', 'Jorai, an Israelite Jorai.', 'from 3384; rainy;');
