INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3148}/[H3148]', 'lemma', 'heb', 'יוֹתֵר', '["yôwthêr"]', '["properly, redundant; hence, over and above, as adjective, noun, adverb or conjunction better, more(-over), over, profit."]', '["n-m"]', 'properly, redundant; hence, over and above, as adjective, noun, adverb or conjunction better, more(-over), over, profit.', 'active participle of 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3149>', 'opaque', 'heb', 'יְזַוְאֵל', '["Yᵉzavʼêl"]', '["Jezavel, an Israelite Jeziel (from the margin)."]', '["n-pr-m"]', 'Jezavel, an Israelite Jeziel (from the margin).', 'from an unused root (meaning to sprinkle) and 410; sprinkled of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3150}/[H3150]', 'lemma', 'heb', 'יִזִּיָּה', '["Yizzîyâh"]', '["Jizzijah, an Israelite Jeziah."]', '["n-pr-m"]', 'Jizzijah, an Israelite Jeziah.', 'from the same as the first part of 3149 and 3050; sprinkled of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3151}/[H3151]', 'lemma', 'heb', 'יָזִיז', '["Yâzîyz"]', '["Jaziz, an Israelite Jaziz."]', '["n-pr-m"]', 'Jaziz, an Israelite Jaziz.', 'from the same as 2123; he will make prominent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3152>', 'opaque', 'heb', 'יִזְלִיאָה', '["Yizlîyʼâh"]', '["Jizliah, an Israelite Jezliah."]', '["n-pr-m"]', 'Jizliah, an Israelite Jezliah.', 'perhaps from an unused root (meaning to draw up); he will draw out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3153}/[H3153]', 'lemma', 'heb', 'יְזַנְיָה', '["Yᵉzanyâh"]', '["Jezanjah, an Israelite Jezaniah."]', '["n-pr-m"]', 'Jezanjah, an Israelite Jezaniah.', 'or יְזַנְיָהוּ; probably for 2970;');
