INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3191}/[H3191]', 'lemma', 'arc', 'יְטַב', '["yᵉṭab"]', '["seem good."]', '["v"]', 'seem good.', '(Aramaic) corresponding to 3190');
