INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3203}/[H3203]', 'lemma', 'heb', 'יְכׇלְיָה', '["Yᵉkolyâh"]', '["Jekoljah or Jekiljah, an Israelitess Jecholiah, Jecoliah."]', '["n-pr-f"]', 'Jekoljah or Jekiljah, an Israelitess Jecholiah, Jecoliah.', 'and יְכׇלְיָהוּ; or (2 Chronicles 26:3) יְכִילְיָה; from 3201 and 3050; Jah will enable;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3204}/[H3204]', 'lemma', 'heb', 'יְכׇנְיָה', '["Yᵉkonyâh"]', '["Jekonjah, a Jewish king Jeconiah. Compare 3659."]', '["n-pr-m"]', 'Jekonjah, a Jewish king Jeconiah. Compare 3659.', 'and יְכׇנְיָהוּ; or (Jeremiah 27:20) יְכוֹנְיָה; from 3559 and 3050; Jah will establish;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3205]', 'root', 'heb', 'יָלַד', '["yâlad"]', '["to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman)."]', '["v"]', 'to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3206}/[H3206]', 'lemma', 'heb', 'יֶלֶד', '["yeled"]', '["something born, i.e. a lad or offspring boy, child, fruit, son, young man (one)."]', '["n-m"]', 'something born, i.e. a lad or offspring boy, child, fruit, son, young man (one).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3207}/[H3207]', 'lemma', 'heb', 'יַלְדָּה', '["yaldâh"]', '["a lass damsel, girl."]', '["n-f"]', 'a lass damsel, girl.', 'feminine of 3206;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3208}/[H3208]', 'lemma', 'heb', 'יַלְדוּת', '["yaldûwth"]', '["boyhood (or girlhood) childhood, youth."]', '["n-f"]', 'boyhood (or girlhood) childhood, youth.', 'abstractly from 3206;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3209}/[H3209]', 'lemma', 'heb', 'יִלּוֹד', '["yillôwd"]', '["born born."]', '["a"]', 'born born.', 'passive from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3210}/[H3210]', 'lemma', 'heb', 'יָלוֹן', '["Yâlôwn"]', '["Jalon, an Israelite Jalon."]', '["n-pr-m"]', 'Jalon, an Israelite Jalon.', 'from 3885; lodging;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3211}/[H3211]', 'lemma', 'heb', 'יָלִיד', '["yâlîyd"]', '["born (home-) born, child, son."]', '["a"]', 'born (home-) born, child, son.', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3212]', 'root', 'heb', 'יָלַךְ', '["yâlak"]', '["to walk (literally or figuratively); causatively, to carry (in various senses) × again, away, bear, bring, carry (away), come (away), depart, flow, follow(-ing), get (away, hence, him), (cause to, made) go (away, -ing, -ne, one''s way, out), grow, lead (forth), let down, march, prosper, pursue, cause to run, spread, take away (-journey), vanish, (cause to) walk(-ing), wax, × be weak."]', '["v"]', 'to walk (literally or figuratively); causatively, to carry (in various senses) × again, away, bear, bring, carry (away), come (away), depart, flow, follow(-ing), get (away, hence, him), (cause to, made) go (away, -ing, -ne, one''s way, out), grow, lead (forth), let down, march, prosper, pursue, cause to run, spread, take away (-journey), vanish, (cause to) walk(-ing), wax, × be weak.', 'a primitive root (compare 1980);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3213]', 'root', 'heb', 'יָלַל', '["yâlal"]', '["to howl (with a wailing tone) or yell (with a boisterous one) (make to) howl, be howling."]', '["v"]', 'to howl (with a wailing tone) or yell (with a boisterous one) (make to) howl, be howling.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3214}/[H3214]', 'lemma', 'heb', 'יְלֵל', '["yᵉlêl"]', '["howl a howling."]', '["n-m"]', 'howl a howling.', 'from 3213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3215}/[H3215]', 'lemma', 'heb', 'יְלָלָה', '["yᵉlâlâh"]', '["a howling a howling."]', '["n-f"]', 'a howling a howling.', 'feminine of 3214');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3216]', 'root', 'heb', 'יָלַע', '["yâlaʻ"]', '["to blurt or utter inconsiderately devour."]', '["v"]', 'to blurt or utter inconsiderately devour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3218>', 'opaque', 'heb', 'יֶלֶק', '["yeleq"]', '["a devourer; specifically, the young locust cankerworm, caterpillar."]', '["n-m"]', 'a devourer; specifically, the young locust cankerworm, caterpillar.', 'from an unused root meaning to lick up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3219}/[H3219]', 'lemma', 'heb', 'יַלְקוּט', '["yalqûwṭ"]', '["a travelling pouch (as if for gleanings) scrip."]', '["n-m"]', 'a travelling pouch (as if for gleanings) scrip.', 'from 3950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3220>', 'opaque', 'heb', 'יָם', '["yâm"]', '["a sea (as breaking in noisy surf) or large body of water; specifically (with the article), the Mediterranean Sea; sometimes a large river, or an artifical basin; locally, the west, or (rarely) the south sea (× -faring man, (-shore)), south, west (-ern, side, -ward)."]', '["n-m"]', 'a sea (as breaking in noisy surf) or large body of water; specifically (with the article), the Mediterranean Sea; sometimes a large river, or an artifical basin; locally, the west, or (rarely) the south sea (× -faring man, (-shore)), south, west (-ern, side, -ward).', 'from an unused root meaning to roar;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3221}/[H3221]', 'lemma', 'arc', 'יָם', '["yâm"]', '["sea."]', '["n-m"]', 'sea.', '(Aramaic) corresponding to 3220');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3222}/[H3222]', 'lemma', 'heb', 'יֵם', '["yêm"]', '["a warm spring mule."]', '["n-m"]', 'a warm spring mule.', 'from the same as 3117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3223}/[H3223]', 'lemma', 'heb', 'יְמוּאֵל', '["Yᵉmûwʼêl"]', '["Jemuel, an Israelite Jemuel."]', '["n-pr-m"]', 'Jemuel, an Israelite Jemuel.', 'from 3117 and 410; day of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3224}/[H3224]', 'lemma', 'heb', 'יְמִימָה', '["Yᵉmîymâh"]', '["Jemimah, one of Job''s daughters Jemimah."]', '["n-pr-f"]', 'Jemimah, one of Job''s daughters Jemimah.', 'perhaps from the same as 3117; properly, warm, i.e. affectionate; hence, dove (compare 3123);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3225}/[H3225]', 'lemma', 'heb', 'יָמִין', '["yâmîyn"]', '["the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south."]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3226}/[H3226]', 'lemma', 'heb', 'יָמִין', '["Yâmîyn"]', '["Jamin, the name of three Israelites Jamin. See also 1144."]', '["n-pr-m"]', 'Jamin, the name of three Israelites Jamin. See also 1144.', 'the same as 3225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3227}/[H3227]', 'lemma', 'heb', 'יְמִינִי', '["yᵉmîynîy"]', '["right (on the) right (hand)."]', '["a"]', 'right (on the) right (hand).', 'for 3225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3228}/[H3228]', 'lemma', 'heb', 'יְמִינִי', '["Yᵉmîynîy"]', '["a Jeminite (collectively) or descendants of Jamin Jaminites. See also 1145."]', '["a"]', 'a Jeminite (collectively) or descendants of Jamin Jaminites. See also 1145.', 'patronymically from 3226;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3229}/[H3229]', 'lemma', 'heb', 'יִמְלָא', '["Yimlâʼ"]', '["Jimla or Jimlah, an Israelite Imla, Imlah."]', '["n-pr-m"]', 'Jimla or Jimlah, an Israelite Imla, Imlah.', 'or יִמְלָה; from 4390; full;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3230}/[H3230]', 'lemma', 'heb', 'יַמְלֵךְ', '["Yamlêk"]', '["Jamlek, an Israelite Jamlech."]', '["n-pr-m"]', 'Jamlek, an Israelite Jamlech.', 'from 4427; he will make king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3231]', 'root', 'heb', 'יָמַן', '["yâman"]', '["to be right-handed or take the right-hand side go (turn) to (on, use) the right hand."]', '["v"]', 'to be right-handed or take the right-hand side go (turn) to (on, use) the right hand.', 'a primitive root; to be (physically) right (i.e. firm); but used only as denominative from 3225 and transitive,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3232}/[H3232]', 'lemma', 'heb', 'יִמְנָה', '["Yimnâh"]', '["Jimnah, the name of two Israelites; also (with the article) of the posterity of one of them Imna, Imnah, Jimnah, Jimnites."]', '["n-pr"]', 'Jimnah, the name of two Israelites; also (with the article) of the posterity of one of them Imna, Imnah, Jimnah, Jimnites.', 'from 3231; prosperity (as betokened by the right hand);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3233}/[H3233]', 'lemma', 'heb', 'יְמָנִי', '["yᵉmânîy"]', '["right (i.e. at the right hand) (on the) right (hand)."]', '["a"]', 'right (i.e. at the right hand) (on the) right (hand).', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3234}/[H3234]', 'lemma', 'heb', 'יִמְנָע', '["Yimnâʻ"]', '["Jimna, an Israelite Imna."]', '["n-pr-m"]', 'Jimna, an Israelite Imna.', 'from 4513; he will restrain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3235]', 'root', 'heb', 'יָמַר', '["yâmar"]', '["to exchange; by implication, to change places boast selves, change."]', '["v"]', 'to exchange; by implication, to change places boast selves, change.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3236}/[H3236]', 'lemma', 'heb', 'יִמְרָה', '["Yimrâh"]', '["Jimrah, an Israelite Imrah."]', '["n-pr-m"]', 'Jimrah, an Israelite Imrah.', 'probably from 3235; interchange;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3237]', 'root', 'heb', 'יָמַשׁ', '["yâmash"]', '["to touch feel."]', '["v"]', 'to touch feel.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3238]', 'root', 'heb', 'יָנָה', '["yânâh"]', '["to rage or be violent; by implication, to suppress, to maltreat destroy, (thrust out by) oppress(-ing, -ion, -or), proud, vex, do violence."]', '["v"]', 'to rage or be violent; by implication, to suppress, to maltreat destroy, (thrust out by) oppress(-ing, -ion, -or), proud, vex, do violence.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3239}/[H3239]', 'lemma', 'heb', 'יָנוֹחַ', '["Yânôwach"]', '["Janoach, a place in Palestine Janoah, Janohah."]', '["n-pr-loc"]', 'Janoach, a place in Palestine Janoah, Janohah.', 'from 3240; quiet;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3240]', 'root', 'heb', 'יָנַח', '["yânach"]', '["to deposit; by implication, to allow to stay bestow, cast down, lay (down, up), leave (off), let alone (remain), pacify, place, put, set (down), suffer, withdraw, withhold. (The Hiphil forms with the dagesh are here referred to, in accordance with the older grammarians; but if any distinction of the kind is to be made, these should rather be referred to 5117, and the others here.)"]', '["v"]', 'to deposit; by implication, to allow to stay bestow, cast down, lay (down, up), leave (off), let alone (remain), pacify, place, put, set (down), suffer, withdraw, withhold. (The Hiphil forms with the dagesh are here referred to, in accordance with the older grammarians; but if any distinction of the kind is to be made, these should rather be referred to 5117, and the others here.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3241}/[H3241]', 'lemma', 'heb', 'יָנִים', '["Yânîym"]', '["Janim, a place in Palestine Janum (from the margin)."]', '["n-pr-loc"]', 'Janim, a place in Palestine Janum (from the margin).', 'from 5123; asleep;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3242}/[H3242]', 'lemma', 'heb', 'יְנִיקָה', '["yᵉnîyqâh"]', '["a sucker or sapling young twig."]', '["n-f"]', 'a sucker or sapling young twig.', 'from 3243;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3243]', 'root', 'heb', 'יָנַק', '["yânaq"]', '["to suck; causatively, to give milk milch, nurse(-ing mother), (give, make to) suck(-ing child, -ling)."]', '["v"]', 'to suck; causatively, to give milk milch, nurse(-ing mother), (give, make to) suck(-ing child, -ling).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3244}/[H3244]', 'lemma', 'heb', 'יַנְשׁוּף', '["yanshûwph"]', '["an unclean (acquatic) bird; probably the heron (perhaps from its blowing cry, or because the nightheron is meant) (great) owl.s"]', '["n-m"]', 'an unclean (acquatic) bird; probably the heron (perhaps from its blowing cry, or because the nightheron is meant) (great) owl.s', 'or יַנְשׁוֹף; apparently from 5398; (compare 5399)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3245]', 'root', 'heb', 'יָסַד', '["yâçad"]', '["to set (literally or figuratively); intensively, to found; reflexively, to sit down together, i.e. settle, consult appoint, take counsel, establish, (lay the, lay for a) found(-ation), instruct, lay, ordain, set, × sure."]', '["v"]', 'to set (literally or figuratively); intensively, to found; reflexively, to sit down together, i.e. settle, consult appoint, take counsel, establish, (lay the, lay for a) found(-ation), instruct, lay, ordain, set, × sure.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3246}/[H3246]', 'lemma', 'heb', 'יְסֻד', '["yᵉçud"]', '["a foundation (figuratively, i.e. beginning) × began."]', '["n-m"]', 'a foundation (figuratively, i.e. beginning) × began.', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3247}/[H3247]', 'lemma', 'heb', 'יְסוֹד', '["yᵉçôwd"]', '["a foundation (literally or figuratively) bottom, foundation, repairing"]', '["n-f"]', 'a foundation (literally or figuratively) bottom, foundation, repairing', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3248}/[H3248]', 'lemma', 'heb', 'יְסוּדָה', '["yᵉçûwdâh"]', '["a foundation foundation."]', '["n-f"]', 'a foundation foundation.', 'feminine of 3246;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3249}/[H3249]', 'lemma', 'heb', 'יָסוּר', '["yâçûwr"]', '["departing they that depart"]', '["a"]', 'departing they that depart', 'from 5493;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3250}/[H3250]', 'lemma', 'heb', 'יִסּוֹר', '["yiççôwr"]', '["a reprover instruct."]', '["n-m"]', 'a reprover instruct.', 'from 3256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3251]', 'root', 'heb', 'יָסַךְ', '["yâçak"]', '["to pour (intransitive) be poured."]', '["v"]', 'to pour (intransitive) be poured.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3253}/[H3253]', 'lemma', 'heb', 'יִסְמַכְיָהוּ', '["Yiçmakyâhûw"]', '["Jismakjah, an Israelite Ismachiah."]', '["n-pr-m"]', 'Jismakjah, an Israelite Ismachiah.', 'from 5564 and 3050; Jah will sustain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3254]', 'root', 'heb', 'יָסַף', '["yâçaph"]', '["to add or augment (often adverbial, to continue to do a thing) add, × again, × any more, × cease, × come more, conceive again, continue, exceed, × further, × gather together, get more, give more-over, × henceforth, increase (more and more), join, × longer (bring, do, make, much, put), × (the, much, yet) more (and more), proceed (further), prolong, put, be (strong-) er, × yet, yield."]', '["v"]', 'to add or augment (often adverbial, to continue to do a thing) add, × again, × any more, × cease, × come more, conceive again, continue, exceed, × further, × gather together, get more, give more-over, × henceforth, increase (more and more), join, × longer (bring, do, make, much, put), × (the, much, yet) more (and more), proceed (further), prolong, put, be (strong-) er, × yet, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3255}/[H3255]', 'lemma', 'arc', 'יְסַף', '["yᵉçaph"]', '["add."]', '["v"]', 'add.', '(Aramaic) corresponding to 3254');
