INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3361}/[H3361]', 'lemma', 'heb', 'יׇקְמְעָם', '["Yoqmᵉʻâm"]', '["Jokmeam, a place in Palestine Jokmeam. Compare 3360, 3362."]', '["n-pr-loc"]', 'Jokmeam, a place in Palestine Jokmeam. Compare 3360, 3362.', 'from 6965 and 5971; (the) people will be raised;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3362}/[H3362]', 'lemma', 'heb', 'יׇקְנְעָם', '["Yoqnᵉʻâm"]', '["Jokneam, a place in Palestine Jokneam."]', '["n-pr-loc"]', 'Jokneam, a place in Palestine Jokneam.', 'from 6969 and 5971; (the) people will be lamented;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3363]', 'root', 'heb', 'יָקַע', '["yâqaʻ"]', '["properly, to sever oneself, i.e. (by implication) to be dislocated; figuratively, to abandon; causatively, to impale (and thus allow to drop to pieces by rotting) be alienated, depart, hang (up), be out of joint."]', '["v"]', 'properly, to sever oneself, i.e. (by implication) to be dislocated; figuratively, to abandon; causatively, to impale (and thus allow to drop to pieces by rotting) be alienated, depart, hang (up), be out of joint.', 'a primitive root;');
