INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3365]', 'root', 'heb', 'יָקַר', '["yâqar"]', '["properly, apparently, to be heavy, i.e. (figuratively) valuable; causatively, to make rare (figuratively, to inhibit) be (make) precious, be prized, be set by, withdraw."]', '["v"]', 'properly, apparently, to be heavy, i.e. (figuratively) valuable; causatively, to make rare (figuratively, to inhibit) be (make) precious, be prized, be set by, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3366}/[H3366]', 'lemma', 'heb', 'יְקָר', '["yᵉqâr"]', '["value, i.e. (concretely) wealth; abstractly, costliness, dignity honour, precious (things), price."]', '["n-m"]', 'value, i.e. (concretely) wealth; abstractly, costliness, dignity honour, precious (things), price.', 'from 3365;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3367}/[H3367]', 'lemma', 'arc', 'יְקָר', '["yᵉqâr"]', '["glory, honour."]', '["n-m"]', 'glory, honour.', '(Aramaic) corresponding to 3366');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3368}/[H3368]', 'lemma', 'heb', 'יָקָר', '["yâqâr"]', '["valuable (objectively or subjectively) brightness, clear, costly, excellent, fat, honourable women, precious, reputation."]', '["a"]', 'valuable (objectively or subjectively) brightness, clear, costly, excellent, fat, honourable women, precious, reputation.', 'from 3365;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3369]', 'root', 'heb', 'יָקֹשׁ', '["yâqôsh"]', '["to ensnare (literally or figuratively) fowler (lay a) snare."]', '["v"]', 'to ensnare (literally or figuratively) fowler (lay a) snare.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3370}/[H3370]', 'lemma', 'heb', 'יׇקְשָׁן', '["Yoqshân"]', '["Jokshan, an Arabian patriarch Jokshan."]', '["n-pr-m"]', 'Jokshan, an Arabian patriarch Jokshan.', 'from 3369; insidious;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3371}/[H3371]', 'lemma', 'heb', 'יׇקְתְאֵל', '["Yoqthᵉʼêl"]', '["Joktheel, the name of a place in Palestine, and of one in Idumaea Joktheel."]', '["n-pr-loc"]', 'Joktheel, the name of a place in Palestine, and of one in Idumaea Joktheel.', 'probably from the same as 3348 and 410; veneration of God (compare 3354);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3372]', 'root', 'heb', 'יָרֵא', '["yârêʼ"]', '["to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing)."]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3373}/[H3373]', 'lemma', 'heb', 'יָרֵא', '["yârêʼ"]', '["fearing; morally, reverent afraid, fear (-ful)."]', '["a"]', 'fearing; morally, reverent afraid, fear (-ful).', 'from 3372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3374}/[H3374]', 'lemma', 'heb', 'יִרְאָה', '["yirʼâh"]', '["fear (also used as infinitive); morally, reverence × dreadful, × exceedingly, fear(-fulness)."]', '["n-f"]', 'fear (also used as infinitive); morally, reverence × dreadful, × exceedingly, fear(-fulness).', 'feminine of 3373;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3375}/[H3375]', 'lemma', 'heb', 'יִרְאוֹן', '["Yirʼôwn"]', '["Jiron, a place in Palestine Iron."]', '["n-pr-loc"]', 'Jiron, a place in Palestine Iron.', 'from 3372; fearfulness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3376}/[H3376]', 'lemma', 'heb', 'יִרְאִיָּיה', '["Yirʼîyâyh"]', '["Jirijah, an Israelite Irijah."]', '["n-pr-m"]', 'Jirijah, an Israelite Irijah.', 'from 3373 and 3050; fearful of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3377}/[H3377]', 'lemma', 'heb', 'יָרֵב', '["Yârêb"]', '["Jareb, a symbolical name for Assyria Jareb. Compare 3402."]', '["n-m"]', 'Jareb, a symbolical name for Assyria Jareb. Compare 3402.', 'from 7378; he will contend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3378}/[H3378]', 'lemma', 'heb', 'יְרֻבַּעַל', '["Yᵉrubbaʻal"]', '["Jerubbaal, a symbolic name of Gideon Jerubbaal."]', '["n-pr-m"]', 'Jerubbaal, a symbolic name of Gideon Jerubbaal.', 'from 7378 and 1168; Baal will contend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3379}/[H3379]', 'lemma', 'heb', 'יָרׇבְעָם', '["Yârobʻâm"]', '["Jarobam, the name of two Israelite kings Jeroboam."]', '["n-pr-m"]', 'Jarobam, the name of two Israelite kings Jeroboam.', 'from 7378 and 5971; (the) people will contend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3380}/[H3380]', 'lemma', 'heb', 'יְרֻבֶּשֶׁת', '["Yᵉrubbesheth"]', '["Jerubbesheth, a symbolic name for Gideon Jerubbesheth."]', '["n-pr-m"]', 'Jerubbesheth, a symbolic name for Gideon Jerubbesheth.', 'from 7378 and 1322; shame (i.e. the idol) will contend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3381]', 'root', 'heb', 'יָרַד', '["yârad"]', '["to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down."]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3382}/[H3382]', 'lemma', 'heb', 'יֶרֶד', '["Yered"]', '["Jered, the name of an antediluvian, and of an Israelite Jared."]', '["n-pr-m"]', 'Jered, the name of an antediluvian, and of an Israelite Jared.', 'from 3381; a descent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3383}/[H3383]', 'lemma', 'heb', 'יַרְדֵּן', '["Yardên"]', '["Jarden, the principal river of Palestine Jordan."]', '["n-pr"]', 'Jarden, the principal river of Palestine Jordan.', 'from 3381; a descender;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3384]', 'root', 'heb', 'יָרָה', '["yârâh"]', '["properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through."]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
