INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3388}/[H3388]', 'lemma', 'heb', 'יְרוּשָׁא', '["Yᵉrûwshâʼ"]', '["Jerusha or Jerushah, as Israelitess Jerusha, Jerushah."]', '["n-pr-f"]', 'Jerusha or Jerushah, as Israelitess Jerusha, Jerushah.', 'or יְרוּשָׁה feminine passive participle of 3423; possessed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3389}/[H3389]', 'lemma', 'heb', 'יְרוּשָׁלִַ͏ם', '["Yᵉrûwshâlaim"]', '["Jerushalaim or Jerushalem, the capital city of Palestine Jerusalem."]', '["n-pr-loc"]', 'Jerushalaim or Jerushalem, the capital city of Palestine Jerusalem.', 'rarely יְרוּשָׁלַיִם; a dual (in allusion to its two main hills (the true pointing, at least of the former reading, seems to be that of 3390)); probably from (the passive participle of) 3384 and 7999; founded peaceful;');
