INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3405}/[H3405]', 'lemma', 'heb', 'יְרִיחוֹ', '["Yᵉrîychôw"]', '["Jericho or Jerecho, a place in Palestine Jericho."]', '["n-pr-loc"]', 'Jericho or Jerecho, a place in Palestine Jericho.', 'or יְרֵחוֹ; or variation (1 Kings 16:34) יְרִיחֹה; perhaps from 3394; its month; or else from 7306; fragrant;');
