INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3415]', 'root', 'heb', 'יָרַע', '["yâraʻ"]', '["properly, to be broken up (with any violent action) i.e. (figuratively) to fear be grevious (only Isaiah 15:4; the rest belong to 7489)."]', '["v"]', 'properly, to be broken up (with any violent action) i.e. (figuratively) to fear be grevious (only Isaiah 15:4; the rest belong to 7489).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3416}/[H3416]', 'lemma', 'heb', 'יִרְפְּאֵל', '["Yirpᵉʼêl"]', '["Jirpeel, a place in Palestine Irpeel."]', '["n-pr-loc"]', 'Jirpeel, a place in Palestine Irpeel.', 'from 7495 and 410; God will heal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3417]', 'root', 'heb', 'יָרָק', '["yârâq"]', '["to spit × but, spit."]', '["v"]', 'to spit × but, spit.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3418}/[H3418]', 'lemma', 'heb', 'יֶרֶק', '["yereq"]', '["properly, pallor, i.e. hence, the yellowish green of young and sickly vegetation; concretely, verdure, i.e. grass or vegetation grass, green (thing)."]', '["n-m"]', 'properly, pallor, i.e. hence, the yellowish green of young and sickly vegetation; concretely, verdure, i.e. grass or vegetation grass, green (thing).', 'from 3417 (in the sense of vacuity of color);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3419}/[H3419]', 'lemma', 'heb', 'יָרָק', '["yârâq"]', '["properly, green; concretely, a vegetable green, herbs."]', '["n-m"]', 'properly, green; concretely, a vegetable green, herbs.', 'from the same as 3418;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3420}/[H3420]', 'lemma', 'heb', 'יֵרָקוֹן', '["yêrâqôwn"]', '["paleness, whether of persons (from fright), or of plants (from drought) greenish, yellow."]', '["n-m"]', 'paleness, whether of persons (from fright), or of plants (from drought) greenish, yellow.', 'from 3418;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3421}/[H3421]', 'lemma', 'heb', 'יׇרְקְעָם', '["Yorqᵉʻâm"]', '["Jorkeam, a place in Palestine Jorkeam."]', '["n-pr-m"]', 'Jorkeam, a place in Palestine Jorkeam.', 'from 7324 and 5971; people will be poured forth;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3422}/[H3422]', 'lemma', 'heb', 'יְרַקְרַק', '["yᵉraqraq"]', '["yellowishness greenish, yellow."]', '["a"]', 'yellowishness greenish, yellow.', 'from the same as 3418;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3423]', 'root', 'heb', 'יָרַשׁ', '["yârash"]', '["to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly."]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3424}/[H3424]', 'lemma', 'heb', 'יְרֵשָׁה', '["yᵉrêshâh"]', '["occupancy possession."]', '["n-f"]', 'occupancy possession.', 'from 3423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3425}/[H3425]', 'lemma', 'heb', 'יְרֻשָּׁה', '["yᵉrushshâh"]', '["something occupied; a conquest; also a patrimony heritage, inheritance, possession."]', '["n-f"]', 'something occupied; a conquest; also a patrimony heritage, inheritance, possession.', 'from 3423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3427]', 'root', 'heb', 'יָשַׁב', '["yâshab"]', '["properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry."]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3428}/[H3428]', 'lemma', 'heb', 'יֶשֶׁבְאָב', '["Yeshebʼâb"]', '["Jeshebab, an Israelite Jeshebeab."]', '["n-pr-m"]', 'Jeshebab, an Israelite Jeshebeab.', 'from 3427 and 1; seat of (his) father;');
