INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3430}/[H3430]', 'lemma', 'heb', 'יִשְׁבּוֹ בְּנֹב', '["Yishbôw bᵉ-Nôb"]', '["Jishbo-be-Nob, a Philistine Ishbi-benob (from the margin)."]', '["n-pr-m"]', 'Jishbo-be-Nob, a Philistine Ishbi-benob (from the margin).', 'from 3427 and 5011, with a pronominal suffix and a preposition interposed; his dwelling (is) in Nob;');
