INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3462]', 'root', 'heb', 'יָשֵׁן', '["yâshên"]', '["properly, to be slack or languid, i.e. (by implication) sleep (figuratively, to die); also to grow old, stale or inveterate old (store), remain long, (make to) sleep."]', '["v"]', 'properly, to be slack or languid, i.e. (by implication) sleep (figuratively, to die); also to grow old, stale or inveterate old (store), remain long, (make to) sleep.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3463}/[H3463]', 'lemma', 'heb', 'יָשֵׁן', '["yâshên"]', '["sleepy asleep, (one out of) sleep(-eth, -ing), slept."]', '["a"]', 'sleepy asleep, (one out of) sleep(-eth, -ing), slept.', 'from 3462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3464}/[H3464]', 'lemma', 'heb', 'יָשֵׁן', '["Yâshên"]', '["Jashen, an Israelite Jashen."]', '["n-pr-m"]', 'Jashen, an Israelite Jashen.', 'the same as 3463;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3465}/[H3465]', 'lemma', 'heb', 'יָשָׁן', '["yâshân"]', '["old old."]', '["a"]', 'old old.', 'from 3462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3466}/[H3466]', 'lemma', 'heb', 'יְשָׁנָה', '["Yᵉshânâh"]', '["Jeshanah, a place in Palestine Jeshanah."]', '["n-pr-f"]', 'Jeshanah, a place in Palestine Jeshanah.', 'feminine of 3465;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3467]', 'root', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory."]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3468}/[H3468]', 'lemma', 'heb', 'יֶשַׁע', '["yeshaʻ"]', '["liberty, deliverance, prosperity safety, salvation, saving."]', '["n-m"]', 'liberty, deliverance, prosperity safety, salvation, saving.', 'or יֵשַׁע; from 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3469}/[H3469]', 'lemma', 'heb', 'יִשְׁעִי', '["Yishʻîy"]', '["Jishi, the name of four Israelites Ishi."]', '["n-pr-m"]', 'Jishi, the name of four Israelites Ishi.', 'from 3467; saving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3470}/[H3470]', 'lemma', 'heb', 'יְשַׁעְיָה', '["Yᵉshaʻyâh"]', '["Jeshajah, the name of seven Israelites Isaiah, Jesaiah, Jeshaiah."]', '["n-pr-m"]', 'Jeshajah, the name of seven Israelites Isaiah, Jesaiah, Jeshaiah.', 'or יְשַׁעְיָהוּ; from 3467 and 3050; Jah has saved;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3471>', 'opaque', 'heb', 'יָשְׁפֵה', '["yâshᵉphêh"]', '["a gem supposed to be jasper (from the resemblance in name) jasper."]', '["n-m"]', 'a gem supposed to be jasper (from the resemblance in name) jasper.', 'from an unused root meaning to polish;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3472}/[H3472]', 'lemma', 'heb', 'יִשְׁפָּה', '["Yishpâh"]', '["Jishpah, an Israelite Ispah."]', '["n-pr-m"]', 'Jishpah, an Israelite Ispah.', 'perhaps from 8192; he will scratch;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3473}/[H3473]', 'lemma', 'heb', 'יִשְׁפָּן', '["Yishpân"]', '["Jishpan, an Israelite Ishpan."]', '["n-pr-m"]', 'Jishpan, an Israelite Ishpan.', 'probably from the same as 8227; he will hide;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3474]', 'root', 'heb', 'יָשַׁר', '["yâshar"]', '["to be straight or even; figuratively, to be (causatively, to make) right, pleasant, prosperous direct, fit, seem good (meet), please (will), be (esteem, go) right (on), bring (look, make, take the) straight (way), be upright(-ly)."]', '["v"]', 'to be straight or even; figuratively, to be (causatively, to make) right, pleasant, prosperous direct, fit, seem good (meet), please (will), be (esteem, go) right (on), bring (look, make, take the) straight (way), be upright(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3475}/[H3475]', 'lemma', 'heb', 'יֵשֶׁר', '["Yêsher"]', '["Jesher, an Israelite Jesher."]', '["n-pr-m"]', 'Jesher, an Israelite Jesher.', 'from 3474; the right;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3476}/[H3476]', 'lemma', 'heb', 'יֹשֶׁר', '["yôsher"]', '["the right equity, meet, right, upright(-ness)."]', '["n-m"]', 'the right equity, meet, right, upright(-ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3477}/[H3477]', 'lemma', 'heb', 'יָשָׁר', '["yâshâr"]', '["straight (literally or figuratively) convenient, equity, Jasher, just, meet(-est), pleased well right(-eous), straight, (most) upright(-ly, -ness)."]', '["a"]', 'straight (literally or figuratively) convenient, equity, Jasher, just, meet(-est), pleased well right(-eous), straight, (most) upright(-ly, -ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3478}/[H3478]', 'lemma', 'heb', 'יִשְׂרָאֵל', '["Yisrâʼêl"]', '["he will rule as God; Jisraël, a symbolical name of Jacob; also (typically) of his posterity Israel."]', '["n-pr-m"]', 'he will rule as God; Jisraël, a symbolical name of Jacob; also (typically) of his posterity Israel.', 'from 8280 and 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3479}/[H3479]', 'lemma', 'arc', 'יִשְׂרָאֵל', '["Yisrâʼêl"]', '["Israel."]', '["n-pr-m"]', 'Israel.', '(Aramaic) corresponding to 3478');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3480}/[H3480]', 'lemma', 'heb', 'יְשַׂרְאֵלָה', '["Yᵉsarʼêlâh"]', '["Jesarelah, an Israelite Jesharelah."]', '["n-pr-m"]', 'Jesarelah, an Israelite Jesharelah.', 'by variation from 3477 and 410 with directive enclitic; right towards God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3481}/[H3481]', 'lemma', 'heb', 'יִשְׂרְאֵלִי', '["Yisrᵉʼêlîy"]', '["a Jisreelite or descendant of Jisrael of Israel, Israelite."]', '["a"]', 'a Jisreelite or descendant of Jisrael of Israel, Israelite.', 'patronymically from 3478;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3482}/[H3482]', 'lemma', 'heb', 'יִשְׂרְאֵלִית', '["Yisrᵉʼêlîyth"]', '["a Jisreelitess or female descendant of Jisrael Israelitish."]', '["a-f"]', 'a Jisreelitess or female descendant of Jisrael Israelitish.', 'feminine of 3481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3483}/[H3483]', 'lemma', 'heb', 'יִשְׁרָה', '["yishrâh"]', '["rectitude uprightness."]', '["n-f"]', 'rectitude uprightness.', 'feminine of 3477;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3484}/[H3484]', 'lemma', 'heb', 'יְשֻׁרוּן', '["Yᵉshurûwn"]', '["Jeshurun, a symbolic name for Israel Jeshurun."]', '["n-pr-m"]', 'Jeshurun, a symbolic name for Israel Jeshurun.', 'from 3474; upright;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3485}/[H3485]', 'lemma', 'heb', 'יִשָּׂשכָר', '["Yissâˢkâr"]', '["Jissaskar, a son of Jacob Issachar."]', '["n-pr"]', 'Jissaskar, a son of Jacob Issachar.', '(strictly yis-saws-kawr''); from 5375 and 7939; he will bring a reward;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3486>', 'opaque', 'heb', 'יָשֵׁשׁ', '["yâshêsh"]', '["gray-haired, i.e. an aged man stoop for age."]', '["a"]', 'gray-haired, i.e. an aged man stoop for age.', 'from an unused root meaning to blanch;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3487}/[H3487]', 'lemma', 'arc', 'יַת', '["yath"]', '["a sign of the object of a verb whom."]', '["prt"]', 'a sign of the object of a verb whom.', '(Aramaic) corresponding to 853;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3488}/[H3488]', 'lemma', 'arc', 'יְתִב', '["yᵉthib"]', '["to sit or dwell dwell, (be) set, sit."]', '["v"]', 'to sit or dwell dwell, (be) set, sit.', '(Aramaic) corresponding to 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3491}/[H3491]', 'lemma', 'heb', 'יָתוּר', '["yâthûwr"]', '["properly, what is left, i.e. (by implication) a gleaning range."]', '["n-m"]', 'properly, what is left, i.e. (by implication) a gleaning range.', 'passive participle of 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3492}/[H3492]', 'lemma', 'heb', 'יַתִּיר', '["Yattîyr"]', '["Jattir, a place in Palestine Jattir."]', '["n-pr-loc"]', 'Jattir, a place in Palestine Jattir.', 'from 3498; redundant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3493}/[H3493]', 'lemma', 'arc', 'יַתִּיר', '["yattîyr"]', '["preeminent; as an adverb, very exceeding(-ly), excellent."]', '["a"]', 'preeminent; as an adverb, very exceeding(-ly), excellent.', '(Aramaic) corresponding to 3492;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3494}/[H3494]', 'lemma', 'heb', 'יִתְלָה', '["Yithlâh"]', '["Jithlah, a place in Palestine Jethlah."]', '["n-pr-loc"]', 'Jithlah, a place in Palestine Jethlah.', 'probably from 8518; it will hang, i.e. be high;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3495}/[H3495]', 'lemma', 'heb', 'יִתְמָה', '["Yithmâh"]', '["Jithmah, an Israelite Ithmah."]', '["n-pr-m"]', 'Jithmah, an Israelite Ithmah.', 'from the same as 3490; orphanage;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3497}/[H3497]', 'lemma', 'heb', 'יִתְנָן', '["Yithnân"]', '["Jithnan, a place in Palestine Ithnan."]', '["n-pr-loc"]', 'Jithnan, a place in Palestine Ithnan.', 'from the same as 8577; extensive;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3498]', 'root', 'heb', 'יָתַר', '["yâthar"]', '["to jut over or exceed; by implication, to excel; (intransitively) to remain or be left; causatively to leave, cause to abound, preserve excel, leave (a remnant), left behind, too much, make plenteous, preserve, (be, let) remain(-der, -ing, -nant), reserve, residue, rest."]', '["v"]', 'to jut over or exceed; by implication, to excel; (intransitively) to remain or be left; causatively to leave, cause to abound, preserve excel, leave (a remnant), left behind, too much, make plenteous, preserve, (be, let) remain(-der, -ing, -nant), reserve, residue, rest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3499}/[H3499]', 'lemma', 'heb', 'יֶתֶר', '["yether"]', '["properly, an overhanging, i.e. (by implication) an excess, superiority, remainder; also a small rope (as hanging free) abundant, cord, exceeding, excellancy(-ent), what they leave, that hath left, plentifully, remnant, residue, rest, string, with."]', '["n-m"]', 'properly, an overhanging, i.e. (by implication) an excess, superiority, remainder; also a small rope (as hanging free) abundant, cord, exceeding, excellancy(-ent), what they leave, that hath left, plentifully, remnant, residue, rest, string, with.', 'from 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3500}/[H3500]', 'lemma', 'heb', 'יֶתֶר', '["Yether"]', '["Jether, the name of five or six Israelites and of one Midianite Jether, Jethro. Compare 3503."]', '["n-pr-m"]', 'Jether, the name of five or six Israelites and of one Midianite Jether, Jethro. Compare 3503.', 'the same as 3499;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3501}/[H3501]', 'lemma', 'heb', 'יִתְרָא', '["Yithrâʼ"]', '["Jithra, an Israelite (or Ishmaelite) Ithra."]', '["n-pr-m"]', 'Jithra, an Israelite (or Ishmaelite) Ithra.', 'by variation for 3502;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3502}/[H3502]', 'lemma', 'heb', 'יִתְרָה', '["yithrâh"]', '["properly, excellence, i.e. (by implication) wealth abundance, riches."]', '["n-f"]', 'properly, excellence, i.e. (by implication) wealth abundance, riches.', 'feminine of 3499;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3503}/[H3503]', 'lemma', 'heb', 'יִתְרוֹ', '["Yithrôw"]', '["Jethro, Moses'' father-in-law Jethro. Compare 3500."]', '["n-pr-m"]', 'Jethro, Moses'' father-in-law Jethro. Compare 3500.', 'from 3499 with pron. suffix; his excellence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3504}/[H3504]', 'lemma', 'heb', 'יִתְרוֹן', '["yithrôwn"]', '["preeminence, gain better, excellency(-leth), profit(-able)."]', '["n-m"]', 'preeminence, gain better, excellency(-leth), profit(-able).', 'from 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3505}/[H3505]', 'lemma', 'heb', 'יִתְרִי', '["Yithrîy"]', '["a Jithrite or descendant of Jether Ithrite."]', '["a"]', 'a Jithrite or descendant of Jether Ithrite.', 'patronymically from 3500;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3506}/[H3506]', 'lemma', 'heb', 'יִתְרָן', '["Yithrân"]', '["Jithran, the name of an Edomite and of an Israelite Ithran."]', '["n-pr-m"]', 'Jithran, the name of an Edomite and of an Israelite Ithran.', 'from 3498; excellent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3507}/[H3507]', 'lemma', 'heb', 'יִתְרְעָם', '["Yithrᵉʻâm"]', '["Jithream, a son of David Ithream."]', '["n-pr-m"]', 'Jithream, a son of David Ithream.', 'from 3499 and 5971; excellence of people;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3508}/[H3508]', 'lemma', 'heb', 'יֹתֶרֶת', '["yôthereth"]', '["the lobe or flap of the liver (as if redundant or outhanging) caul."]', '["n-f"]', 'the lobe or flap of the liver (as if redundant or outhanging) caul.', 'feminine active participle of 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3510]', 'root', 'heb', 'כָּאַב', '["kâʼab"]', '["properly, to feel pain; by implication, to grieve; figuratively, to spoil grieving, mar, have pain, make sad (sore), (be) sorrowful."]', '["v"]', 'properly, to feel pain; by implication, to grieve; figuratively, to spoil grieving, mar, have pain, make sad (sore), (be) sorrowful.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3511}/[H3511]', 'lemma', 'heb', 'כְּאֵב', '["kᵉʼêb"]', '["suffering (physical or mental), adversity grief, pain, sorrow."]', '["n-m"]', 'suffering (physical or mental), adversity grief, pain, sorrow.', 'from 3510;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3512]', 'root', 'heb', 'כָּאָה', '["kâʼâh"]', '["to despond; causatively, to deject broken, be grieved, make sad."]', '["v a"]', 'to despond; causatively, to deject broken, be grieved, make sad.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3513]', 'root', 'heb', 'כָּבַד', '["kâbad"]', '["to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop."]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3514}/[H3514]', 'lemma', 'heb', 'כֹּבֶד', '["kôbed"]', '["weight, multitude, vehemence grievousness, heavy, great number."]', '["n-m"]', 'weight, multitude, vehemence grievousness, heavy, great number.', 'from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3515}/[H3515]', 'lemma', 'heb', 'כָּבֵד', '["kâbêd"]', '["heavy; figuratively in a good sense (numerous) or in a bad sense (severe, difficult, stupid) (so) great, grievous, hard(-ened), (too) heavy(-ier), laden, much, slow, sore, thick."]', '["a"]', 'heavy; figuratively in a good sense (numerous) or in a bad sense (severe, difficult, stupid) (so) great, grievous, hard(-ened), (too) heavy(-ier), laden, much, slow, sore, thick.', 'from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3516}/[H3516]', 'lemma', 'heb', 'כָּבֵד', '["kâbêd"]', '["the liver (as the heaviest of the viscera) liver."]', '["n-f"]', 'the liver (as the heaviest of the viscera) liver.', 'the same as 3515;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3517}/[H3517]', 'lemma', 'heb', 'כְּבֵדֻת', '["kᵉbêduth"]', '["difficulty × heavily."]', '["n-f"]', 'difficulty × heavily.', 'feminine of 3515;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3518]', 'root', 'heb', 'כָּבָה', '["kâbâh"]', '["to expire or (causatively) to extinguish (fire, light, anger) go (put) out, quench."]', '["v"]', 'to expire or (causatively) to extinguish (fire, light, anger) go (put) out, quench.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3519}/[H3519]', 'lemma', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able)."]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3520}/[H3520]', 'lemma', 'heb', 'כְּבוּדָּה', '["kᵉbûwddâh"]', '["weightiness, i.e. magnificence, wealth carriage, all glorious, stately."]', '["n-f"]', 'weightiness, i.e. magnificence, wealth carriage, all glorious, stately.', 'irregular feminine passive participle of 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3521}/[H3521]', 'lemma', 'heb', 'כָּבוּל', '["Kâbûwl"]', '["Cabul, the name of two places in Palestine Cabul."]', '["n-pr-loc"]', 'Cabul, the name of two places in Palestine Cabul.', 'from the same as 3525 in the sense of limitation; sterile;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3522>', 'opaque', 'heb', 'כַּבּוֹן', '["Kabbôwn"]', '["Cabon, a place in Palestine Cabbon."]', '["n-pr-loc"]', 'Cabon, a place in Palestine Cabbon.', 'from an unused root meaning to heap up; hilly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3523}/[H3523]', 'lemma', 'heb', 'כְּבִיר', '["kᵉbîyr"]', '["a matrass (of intertwined materials) pillow."]', '["n-m"]', 'a matrass (of intertwined materials) pillow.', 'from 3527 in the original sense of plaiting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3524}/[H3524]', 'lemma', 'heb', 'כַּבִּיר', '["kabbîyr"]', '["vast, whether in extent (figuratively, of power, mighty; of time, aged), or in number, many feeble, mighty, most, much, strong, valiant."]', '["a"]', 'vast, whether in extent (figuratively, of power, mighty; of time, aged), or in number, many feeble, mighty, most, much, strong, valiant.', 'from 3527;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3525>', 'opaque', 'heb', 'כֶּבֶל', '["kebel"]', '["a fetter fetter."]', '["n-m"]', 'a fetter fetter.', 'from an unused root meaning to twine or braid together;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3526]', 'root', 'heb', 'כָּבַס', '["kâbaç"]', '["to trample; hence, to wash (properly, by stamping with the feet), whether literal (including the fulling process) or figurative fuller, wash(-ing)."]', '["v"]', 'to trample; hence, to wash (properly, by stamping with the feet), whether literal (including the fulling process) or figurative fuller, wash(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3527]', 'root', 'heb', 'כָּבַר', '["kâbar"]', '["properly, to plait together, i.e. (figuratively) to augment (especially in number or quantity, to accumulate) in abundance, multiply."]', '["v"]', 'properly, to plait together, i.e. (figuratively) to augment (especially in number or quantity, to accumulate) in abundance, multiply.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3528}/[H3528]', 'lemma', 'heb', 'כְּבָר', '["kᵉbâr"]', '["properly, extent of time, i.e. a great while; hence, long ago, formerly, hitherto already, (seeing that which), now."]', '["adv"]', 'properly, extent of time, i.e. a great while; hence, long ago, formerly, hitherto already, (seeing that which), now.', 'from 3527;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3529}/[H3529]', 'lemma', 'heb', 'כְּבָר', '["Kᵉbâr"]', '["Kebar, a river of Mesopotamia Chebar. Compare 2249."]', '["n"]', 'Kebar, a river of Mesopotamia Chebar. Compare 2249.', 'the same as 3528; length;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3530}/[H3530]', 'lemma', 'heb', 'כִּבְרָה', '["kibrâh"]', '["properly, length, i.e. a measure (of uncertain dimension) × little."]', '["n-f"]', 'properly, length, i.e. a measure (of uncertain dimension) × little.', 'feminine of 3528;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3531}/[H3531]', 'lemma', 'heb', 'כְּבָרָה', '["kᵉbârâh"]', '["a sieve (as netted) sieve."]', '["n-f"]', 'a sieve (as netted) sieve.', 'from 3527 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3533]', 'root', 'heb', 'כָּבַשׁ', '["kâbash"]', '["to tread down; hence, negatively, to disregard; positively, to conquer, subjugate, violate bring into bondage, force, keep under, subdue, bring into subjection."]', '["v"]', 'to tread down; hence, negatively, to disregard; positively, to conquer, subjugate, violate bring into bondage, force, keep under, subdue, bring into subjection.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3534}/[H3534]', 'lemma', 'heb', 'כֶּבֶשׁ', '["kebesh"]', '["a footstool (as trodden upon) footstool."]', '["n-m"]', 'a footstool (as trodden upon) footstool.', 'from 3533;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3535}/[H3535]', 'lemma', 'heb', 'כִּבְשָׂה', '["kibsâh"]', '["a ewe (ewe) lamb."]', '["n-f"]', 'a ewe (ewe) lamb.', 'or כַּבְשָׂה; feminine of 3532;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3536}/[H3536]', 'lemma', 'heb', 'כִּבְשָׁן', '["kibshân"]', '["a smelting furnace (as reducing metals) furnace."]', '["n-m"]', 'a smelting furnace (as reducing metals) furnace.', 'from 3533;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3538}/[H3538]', 'lemma', 'arc', 'כְּדַב', '["kᵉdab"]', '["false lying."]', '["a"]', 'false lying.', '(Aramaic) from a root corresponding to 3576;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3539}/[H3539]', 'lemma', 'heb', 'כַּדְכֹּד', '["kadkôd"]', '["a sparkling gem, probably the ruby agate."]', '["n-m"]', 'a sparkling gem, probably the ruby agate.', 'from the same as 3537 in the sense of striking fire from a metal forged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3541}/[H3541]', 'lemma', 'heb', 'כֹּה', '["kôh"]', '["properly, like this, i.e. by implication, (of manner) thus (or so); also (of place) here (or hither); or (of time) now also, here, hitherto, like, on the other side, so (and much), such, on that manner, (on) this (manner, side, way, way and that way), mean while, yonder."]', '["prt"]', 'properly, like this, i.e. by implication, (of manner) thus (or so); also (of place) here (or hither); or (of time) now also, here, hitherto, like, on the other side, so (and much), such, on that manner, (on) this (manner, side, way, way and that way), mean while, yonder.', 'from the prefix k and 1931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3542}/[H3542]', 'lemma', 'arc', 'כָּה', '["kâh"]', '["hitherto."]', '["adv"]', 'hitherto.', '(Aramaic) corresponding to 3541');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3543]', 'root', 'heb', 'כָּהָה', '["kâhâh"]', '["to be weak, i.e. (figuratively) to despond (causatively, rebuke), or (of light, the eye) to grow dull darken, be dim, fail, faint, restrain, × utterly."]', '["v"]', 'to be weak, i.e. (figuratively) to despond (causatively, rebuke), or (of light, the eye) to grow dull darken, be dim, fail, faint, restrain, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3544}/[H3544]', 'lemma', 'heb', 'כֵּהֶה', '["kêheh"]', '["feeble, obscure somewhat dark, darkish, wax dim, heaviness, smoking."]', '["a"]', 'feeble, obscure somewhat dark, darkish, wax dim, heaviness, smoking.', 'from 3543;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3545}/[H3545]', 'lemma', 'heb', 'כֵּהָה', '["kêhâh"]', '["properly, a weakening; figuratively, alleviation, i.e. cure healing."]', '["n-f"]', 'properly, a weakening; figuratively, alleviation, i.e. cure healing.', 'feminine of 3544;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3546}/[H3546]', 'lemma', 'arc', 'כְּהַל', '["kᵉhal"]', '["to be able be able, could."]', '["v"]', 'to be able be able, could.', '(Aramaic) a root corresponding to and 3557;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3547]', 'root', 'heb', 'כָּהַן', '["kâhan"]', '["to officiate as a priest; figuratively, to put on regalia deck, be (do the office of a, execute the, minister in the) priest(''s office)."]', '["v"]', 'to officiate as a priest; figuratively, to put on regalia deck, be (do the office of a, execute the, minister in the) priest(''s office).', 'a primitive root, apparently meaning to mediate in religious services; but used only as denominative from 3548;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3548}/[H3548]', 'lemma', 'heb', 'כֹּהֵן', '["kôhên"]', '["literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer."]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3549}/[H3549]', 'lemma', 'arc', 'כָּהֵן', '["kâhên"]', '["priest."]', '["n-m"]', 'priest.', '(Aramaic) corresponding to 3548');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3550}/[H3550]', 'lemma', 'heb', 'כְּהֻנָּה', '["kᵉhunnâh"]', '["priesthood priesthood, priest''s office."]', '["n-f"]', 'priesthood priesthood, priest''s office.', 'from 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3551}/[H3551]', 'lemma', 'arc', 'כַּו', '["kav"]', '["a window (as a perforation) window."]', '["n-f"]', 'a window (as a perforation) window.', '(Aramaic) from a root corresponding to 3854 in the sense of piercing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3552}/[H3552]', 'lemma', 'heb', 'כּוּב', '["Kûwb"]', '["Kub, a country near Egypt Chub."]', '["n-pr-loc"]', 'Kub, a country near Egypt Chub.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3553>', 'opaque', 'heb', 'כּוֹבַע', '["kôwbaʻ"]', '["a helmet (as arched) helmet. Compare 6959."]', '["n-m"]', 'a helmet (as arched) helmet. Compare 6959.', 'from an unused root meaning to be high or rounded;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3554]', 'root', 'heb', 'כָּוָה', '["kâvâh"]', '["properly, to prick or penetrate; hence, to blister (as smarting or eating into) burn."]', '["v"]', 'properly, to prick or penetrate; hence, to blister (as smarting or eating into) burn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3555}/[H3555]', 'lemma', 'heb', 'כְּוִיָּה', '["kᵉvîyâh"]', '["a branding burning."]', '["n-f"]', 'a branding burning.', 'from 3554;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3556}/[H3556]', 'lemma', 'heb', 'כּוֹכָב', '["kôwkâb"]', '["a star (as round or as shining); figuratively, a prince star(-gazer)."]', '["n-m"]', 'a star (as round or as shining); figuratively, a prince star(-gazer).', 'probably from the same as 3522 (in the sense of rolling) or 3554 (in the sense of blazing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3557]', 'root', 'heb', 'כּוּל', '["kûwl"]', '["properly, to keep in; hence, to measure; figuratively, to maintain (in various senses) (be able to, can) abide, bear, comprehend, contain, feed, forbearing, guide, hold(-ing in), nourish(-er), be present, make provision, receive, sustain, provide sustenance (victuals)."]', '["v"]', 'properly, to keep in; hence, to measure; figuratively, to maintain (in various senses) (be able to, can) abide, bear, comprehend, contain, feed, forbearing, guide, hold(-ing in), nourish(-er), be present, make provision, receive, sustain, provide sustenance (victuals).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3558>', 'opaque', 'heb', 'כּוּמָז', '["kûwmâz"]', '["a jewel (probably gold beads) tablet."]', '["n-m"]', 'a jewel (probably gold beads) tablet.', 'from an unused root meaning to store away;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3559]', 'root', 'heb', 'כּוּן', '["kûwn"]', '["properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed."]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3560}/[H3560]', 'lemma', 'heb', 'כּוּן', '["Kûwn"]', '["Kun, a place in Syria Chun."]', '["n-pr-loc"]', 'Kun, a place in Syria Chun.', 'probably from 3559; established;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3561}/[H3561]', 'lemma', 'heb', 'כַּוָּן', '["kavvân"]', '["something prepared, i.e. a sacrificial wafer cake."]', '["n-m"]', 'something prepared, i.e. a sacrificial wafer cake.', 'from 3559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3562}/[H3562]', 'lemma', 'heb', 'כּוֹנַנְיָהוּ', '["Kôwnanyâhûw"]', '["Conanjah, the name of two Israelites Conaniah, Cononiah. Compare 3663."]', '["n-pr-m"]', 'Conanjah, the name of two Israelites Conaniah, Cononiah. Compare 3663.', 'from 3559 and 3050; Jah has sustained;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3563>', 'opaque', 'heb', 'כּוֹס', '["kôwç"]', '["a cup (as a container), often figuratively, a lot (as if a potion); also some unclean bird, probably an owl (perhaps from the cup-like cavity of its eye) cup, (small) owl. Compare 3599."]', '["n-f"]', 'a cup (as a container), often figuratively, a lot (as if a potion); also some unclean bird, probably an owl (perhaps from the cup-like cavity of its eye) cup, (small) owl. Compare 3599.', 'from an unused root meaning to hold together;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3565}/[H3565]', 'lemma', 'heb', 'כּוֹר עָשָׁן', '["Kôwr ʻÂshân"]', '["Cor-Ashan, a place in Palestine Chorashan."]', '["n-pr-loc"]', 'Cor-Ashan, a place in Palestine Chorashan.', 'from 3564 and 6227; furnace of smoke;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3567}/[H3567]', 'lemma', 'heb', 'כּוֹרֶשׁ', '["Kôwresh"]', '["Cyrus."]', '["n-pr-m"]', 'Cyrus.', '(Aramaic) corresponding to 3566');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3568>', 'opaque', 'heb', 'כּוּשׁ', '["Kûwsh"]', '["Cush (or Ethiopia), the name of a son of Ham, and of his territory; also of an Israelite Chush, Cush, Ethiopia."]', '["n-pr-m n-pr-loc"]', 'Cush (or Ethiopia), the name of a son of Ham, and of his territory; also of an Israelite Chush, Cush, Ethiopia.', 'probably of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3569}/[H3569]', 'lemma', 'heb', 'כּוּשִׁי', '["Kûwshîy"]', '["a Cushite, or descendant of Cush Cushi, Cushite, Ethiopian(-s)."]', '["a"]', 'a Cushite, or descendant of Cush Cushi, Cushite, Ethiopian(-s).', 'patronymically from 3568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3570}/[H3570]', 'lemma', 'heb', 'כּוּשִׁי', '["Kûwshîy"]', '["Cushi, the name of two Israelites Cushi."]', '["n-pr-m"]', 'Cushi, the name of two Israelites Cushi.', 'the same as 3569;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3571}/[H3571]', 'lemma', 'heb', 'כּוּשִׁית', '["Kûwshîyth"]', '["a Cushite woman Ethiopian."]', '["a-f"]', 'a Cushite woman Ethiopian.', 'feminine of 3569;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3572}/[H3572]', 'lemma', 'heb', 'כּוּשָׁן', '["Kûwshân"]', '["Cushan, a region of Arabia Cushan."]', '["n-pr-loc"]', 'Cushan, a region of Arabia Cushan.', 'perhaps from 3568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3573}/[H3573]', 'lemma', 'heb', 'כּוּשַׁן רִשְׁעָתַיִם', '["Kûwshan Rishʻâthayim"]', '["Cushan-Rishathajim, a Mesopotamian king Chushan-rishathayim."]', '["n-pr-m"]', 'Cushan-Rishathajim, a Mesopotamian king Chushan-rishathayim.', 'apparently from 3572 and the dual of 7564; Cushan of double wickedness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3574}/[H3574]', 'lemma', 'heb', 'כּוֹשָׁרָה', '["kôwshârâh"]', '["prosperity; in plural freedom × chain."]', '["n-f"]', 'prosperity; in plural freedom × chain.', 'from 3787;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3576]', 'root', 'heb', 'כָּזַב', '["kâzab"]', '["to lie (i.e. deceive), literally or figuratively fail, (be found a, make a) liar, lie, lying, be in vain."]', '["v"]', 'to lie (i.e. deceive), literally or figuratively fail, (be found a, make a) liar, lie, lying, be in vain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3577}/[H3577]', 'lemma', 'heb', 'כָּזָב', '["kâzâb"]', '["falsehood; literally (untruth) or figuratively (idol) deceitful, false, leasing, liar, lie, lying."]', '["n-m"]', 'falsehood; literally (untruth) or figuratively (idol) deceitful, false, leasing, liar, lie, lying.', 'from 3576;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3578}/[H3578]', 'lemma', 'heb', 'כֹּזְבָא', '["Kôzᵉbâʼ"]', '["Cozeba, a place in Palestine Choseba."]', '["n-pr-loc"]', 'Cozeba, a place in Palestine Choseba.', 'from 3576; fallacious;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3579}/[H3579]', 'lemma', 'heb', 'כֹּזְבִי', '["Kôzᵉbîy"]', '["Cozbi, a Midianitess Cozbi."]', '["n-pr-f"]', 'Cozbi, a Midianitess Cozbi.', 'from 3576; false;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3580}/[H3580]', 'lemma', 'heb', 'כְּזִיב', '["Kᵉzîyb"]', '["Kezib, a place in Palestine Chezib."]', '["n-pr-loc"]', 'Kezib, a place in Palestine Chezib.', 'from 3576; falsified;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3581>', 'opaque', 'heb', 'כֹּחַ', '["kôach"]', '["vigor, literally (force, in a good or a bad sense) or figuratively (capacity, means, produce); also (from its hardiness) a large lizard ability, able, chameleon, force, fruits, might, power(-ful), strength, substance, wealth."]', '["n-m"]', 'vigor, literally (force, in a good or a bad sense) or figuratively (capacity, means, produce); also (from its hardiness) a large lizard ability, able, chameleon, force, fruits, might, power(-ful), strength, substance, wealth.', 'or (Daniel 11:6) כּוֹחַ; from an unused root meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3582]', 'root', 'heb', 'כָּחַד', '["kâchad"]', '["to secrete, by act or word; hence (intensively) to destroy conceal, cut down (off), desolate, hide."]', '["v"]', 'to secrete, by act or word; hence (intensively) to destroy conceal, cut down (off), desolate, hide.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3583]', 'root', 'heb', 'כָּחַל', '["kâchal"]', '["to paint (with stibium) paint."]', '["v"]', 'to paint (with stibium) paint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3584]', 'root', 'heb', 'כָּחַשׁ', '["kâchash"]', '["to be untrue, in word (to lie, feign, disown) or deed (to disappoint, fail, cringe) deceive, deny, dissemble, fail, deal falsely, be found liars, (be-) lie, lying, submit selves."]', '["v"]', 'to be untrue, in word (to lie, feign, disown) or deed (to disappoint, fail, cringe) deceive, deny, dissemble, fail, deal falsely, be found liars, (be-) lie, lying, submit selves.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3585}/[H3585]', 'lemma', 'heb', 'כַּחַשׁ', '["kachash"]', '["literally a failure of flesh, i.e. emaciation; figuratively, hypocrisy leanness, lies, lying."]', '["n-m"]', 'literally a failure of flesh, i.e. emaciation; figuratively, hypocrisy leanness, lies, lying.', 'from 3584;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3586}/[H3586]', 'lemma', 'heb', 'כֶּחָשׁ', '["kechâsh"]', '["faithless lying."]', '["a"]', 'faithless lying.', 'from 3584;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3587}/[H3587]', 'lemma', 'heb', 'כִּי', '["kîy"]', '["a brand or scar burning."]', '["n-m"]', 'a brand or scar burning.', 'from 3554;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3588}/[H3588]', 'lemma', 'heb', 'כִּי', '["kîy"]', '["(by implication) very widely used as a relative conjunction or adverb (as below); often largely modified by other particles annexed and, (forasmuch, inasmuch, where-) as, assured(-ly), but, certainly, doubtless, else, even, except, for, how, (because, in, so, than) that, nevertheless, now, rightly, seeing, since, surely, then, therefore, (al-) though, till, truly, until, when, whether, while, whom, yea, yet."]', '["conj"]', '(by implication) very widely used as a relative conjunction or adverb (as below); often largely modified by other particles annexed and, (forasmuch, inasmuch, where-) as, assured(-ly), but, certainly, doubtless, else, even, except, for, how, (because, in, so, than) that, nevertheless, now, rightly, seeing, since, surely, then, therefore, (al-) though, till, truly, until, when, whether, while, whom, yea, yet.', 'a primitive particle (the full form of the prepositional prefix) indicating causal relations of all kinds, antecedent or consequent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3589]', 'root', 'heb', 'כִּיד', '["kîyd"]', '["a crushing; figuratively, calamity destruction."]', '["n-m"]', 'a crushing; figuratively, calamity destruction.', 'from a primitive root meaning to strike;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3590}/[H3590]', 'lemma', 'heb', 'כִידוֹד', '["kîydôwd"]', '["properly, something struck off, i.e. a spark (as struck) spark."]', '["n-m"]', 'properly, something struck off, i.e. a spark (as struck) spark.', 'from the same as 3589 (compare 3539);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3591}/[H3591]', 'lemma', 'heb', 'כִּידוֹן', '["kîydôwn"]', '["properly, something to strike with, i.e. a dart lance, shield, spear, target."]', '["n-m"]', 'properly, something to strike with, i.e. a dart lance, shield, spear, target.', 'from the same as 3589; (perhaps smaller than 2595)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3592}/[H3592]', 'lemma', 'heb', 'כִּידוֹן', '["Kîydôwn"]', '["Kidon, a place in Palestine Chidon."]', '["n-pr"]', 'Kidon, a place in Palestine Chidon.', 'the same as 3591;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3593>', 'opaque', 'heb', 'כִּידוֹר', '["kîydôwr"]', '["perhaps tumult battle."]', '["n-m"]', 'perhaps tumult battle.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3594}/[H3594]', 'lemma', 'heb', 'כִּיּוּן', '["Kîyûwn"]', '["properly, a statue, i.e. idol; but used (by euphemism) for some heathen deity (perhaps corresponding to Priapus or Baal-peor) Chiun."]', '["n-pr"]', 'properly, a statue, i.e. idol; but used (by euphemism) for some heathen deity (perhaps corresponding to Priapus or Baal-peor) Chiun.', 'from 3559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3595}/[H3595]', 'lemma', 'heb', 'כִּיּוֹר', '["kîyôwr"]', '["properly, something round (as excavated or bored), i.e. a chafing-dish for coals or a caldron for cooking; hence (from similarity of form) a washbowl; also (for the same reason) a pulpit or platform hearth, laver, pan, scaffold."]', '["n-m"]', 'properly, something round (as excavated or bored), i.e. a chafing-dish for coals or a caldron for cooking; hence (from similarity of form) a washbowl; also (for the same reason) a pulpit or platform hearth, laver, pan, scaffold.', 'or כִּיֹּר; from the same as 3564;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3596}/[H3596]', 'lemma', 'heb', 'כִּילַי', '["kîylay"]', '["niggardly churl."]', '["n-m"]', 'niggardly churl.', 'or כֵּלַי; from 3557 in the sense of withholding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3597>', 'opaque', 'heb', 'כֵּילַף', '["kêylaph"]', '["a club or sledge-hammer hammer."]', '["n-f"]', 'a club or sledge-hammer hammer.', 'from an unused root meaning to clap or strike with noise;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3598}/[H3598]', 'lemma', 'heb', 'כִּימָה', '["Kîymâh"]', '["a cluster of stars, i.e. the Pleiades Pleiades, seven stars."]', '["n-f"]', 'a cluster of stars, i.e. the Pleiades Pleiades, seven stars.', 'from the same as 3558;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3599}/[H3599]', 'lemma', 'heb', 'כִּיס', '["kîyç"]', '["a cup; also a bag for money or weights bag, cup, purse."]', '["n-m"]', 'a cup; also a bag for money or weights bag, cup, purse.', 'a form for 3563;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3600}/[H3600]', 'lemma', 'heb', 'כִּיר', '["kîyr"]', '["a cooking range (consisting of two parallel stones, across which the boiler is set) ranges for pots."]', '["n-m"]', 'a cooking range (consisting of two parallel stones, across which the boiler is set) ranges for pots.', 'a form for 3564 (only in the dual);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3601}/[H3601]', 'lemma', 'heb', 'כִּישׁוֹר', '["kîyshôwr"]', '["literally a director, i.e. the spindle or shank of a distaff, by which it is twirled spindle."]', '["n-m"]', 'literally a director, i.e. the spindle or shank of a distaff, by which it is twirled spindle.', 'from 3787; compare 6418');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3602}/[H3602]', 'lemma', 'heb', 'כָּכָה', '["kâkâh"]', '["just so, referring to the previous or following context after that (this) manner, this matter, (even) so, in such a case, thus."]', '["adv"]', 'just so, referring to the previous or following context after that (this) manner, this matter, (even) so, in such a case, thus.', 'from 3541;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3603}/[H3603]', 'lemma', 'heb', 'כִּכָּר', '["kikkâr"]', '["a circle, i.e. (by implication) a circumjacent tract or region, especially the Ghor or valley of the Jordan; also a (round) loaf; also a talent (or large [round] coin) loaf, morsel, piece, plain, talent."]', '["n-f"]', 'a circle, i.e. (by implication) a circumjacent tract or region, especially the Ghor or valley of the Jordan; also a (round) loaf; also a talent (or large [round] coin) loaf, morsel, piece, plain, talent.', 'from 3769;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3604}/[H3604]', 'lemma', 'arc', 'כִּכֵּר', '["kikkêr"]', '["a talent talent."]', '["n-f"]', 'a talent talent.', '(Aramaic) corresponding to 3603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3605}/[H3605]', 'lemma', 'heb', 'כֹּל', '["kôl"]', '["properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever)."]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3606}/[H3606]', 'lemma', 'arc', 'כֹּל', '["kôl"]', '["all, any, (forasmuch) as, be-(for this) cause, every, no (manner, -ne), there (where) -fore, though, what (where, who) -soever, (the) whole."]', '["n-m"]', 'all, any, (forasmuch) as, be-(for this) cause, every, no (manner, -ne), there (where) -fore, though, what (where, who) -soever, (the) whole.', '(Aramaic) corresponding to 3605');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3607]', 'root', 'heb', 'כָּלָא', '["kâlâʼ"]', '["to restrict, by act (hold back or in) or word (prohibit) finish, forbid, keep (back), refrain, restrain, retain, shut up, be stayed, withhold."]', '["v"]', 'to restrict, by act (hold back or in) or word (prohibit) finish, forbid, keep (back), refrain, restrain, retain, shut up, be stayed, withhold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3608}/[H3608]', 'lemma', 'heb', 'כֶּלֶא', '["keleʼ"]', '["a prison prison. Compare 3610, 3628."]', '["n-m"]', 'a prison prison. Compare 3610, 3628.', 'from 3607;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3609}/[H3609]', 'lemma', 'heb', 'כִּלְאָב', '["Kilʼâb"]', '["Kilab, an Israelite Chileab."]', '["n-pr-m"]', 'Kilab, an Israelite Chileab.', 'apparently from 3607 and 1; restraint of (his) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3610}/[H3610]', 'lemma', 'heb', 'כִּלְאַיִם', '["kilʼayim"]', '["two heterogeneities divers seeds (-e kinds), mingled (seed)."]', '["n-m"]', 'two heterogeneities divers seeds (-e kinds), mingled (seed).', 'dual of 3608 in the original sense of separation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3612}/[H3612]', 'lemma', 'heb', 'כָּלֵב', '["Kâlêb"]', '["Caleb, the name of three Israelites Caleb."]', '["n-pr-m"]', 'Caleb, the name of three Israelites Caleb.', 'perhaps a form of 3611, or else from the same root in the sense of forcible;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3613}/[H3613]', 'lemma', 'heb', 'כָּלֵב אֶפְרָתָה', '["Kâlêb ʼEphrâthâh"]', '["Caleb-Ephrathah, a place in Egypt (if the text is correct) Caleb-ephrathah."]', '["n-pr-loc"]', 'Caleb-Ephrathah, a place in Egypt (if the text is correct) Caleb-ephrathah.', 'from 3612 and 672;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3614}/[H3614]', 'lemma', 'heb', 'כָּלִבּוֹ', '["Kâlibbôw"]', '["a Calebite or descendant of Caleb of the house of Caleb."]', '["a"]', 'a Calebite or descendant of Caleb of the house of Caleb.', 'probably by erroneous transcription for כָּלֵבִי; patronymically from 3612;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3615]', 'root', 'heb', 'כָּלָה', '["kâlâh"]', '["to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste."]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3616}/[H3616]', 'lemma', 'heb', 'כָּלֶה', '["kâleh"]', '["pining fail."]', '["a"]', 'pining fail.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3617}/[H3617]', 'lemma', 'heb', 'כָּלָה', '["kâlâh"]', '["a completion; adverb, completely; also destruction altogether, (be, utterly) consume(-d), consummation(-ption), was determined, (full, utter) end, riddance."]', '["n-f"]', 'a completion; adverb, completely; also destruction altogether, (be, utterly) consume(-d), consummation(-ption), was determined, (full, utter) end, riddance.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3618}/[H3618]', 'lemma', 'heb', 'כַּלָּה', '["kallâh"]', '["a bride (as if perfect); hence, a son''s wife bride, daughter-in-law, spouse."]', '["n-f"]', 'a bride (as if perfect); hence, a son''s wife bride, daughter-in-law, spouse.', 'from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3619}/[H3619]', 'lemma', 'heb', 'כְּלוּב', '["kᵉlûwb"]', '["a bird-trap (as furnished with a clap-stick or treadle to spring it); hence, a basket (as resembling a wicker cage) basket, cage."]', '["n-m"]', 'a bird-trap (as furnished with a clap-stick or treadle to spring it); hence, a basket (as resembling a wicker cage) basket, cage.', 'from the same as 3611;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3620}/[H3620]', 'lemma', 'heb', 'כְּלוּב', '["Kᵉlûwb"]', '["Kelub, the name of two Israelites Chelub."]', '["n-pr-m"]', 'Kelub, the name of two Israelites Chelub.', 'the same as 3619;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3621}/[H3621]', 'lemma', 'heb', 'כְּלוּבַי', '["Kᵉlûwbay"]', '["Kelubai, an Israelite Chelubai."]', '["n-pr-m"]', 'Kelubai, an Israelite Chelubai.', 'a form of 3612;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3622}/[H3622]', 'lemma', 'heb', 'כְּלוּהַי', '["Kᵉlûwhay"]', '["Keluhai, an Israelite Chelluh."]', '["n-pr-m"]', 'Keluhai, an Israelite Chelluh.', 'from 3615; completed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3623}/[H3623]', 'lemma', 'heb', 'כְּלוּלָה', '["kᵉlûwlâh"]', '["bridehood (only in the plural) espousal."]', '["n-f"]', 'bridehood (only in the plural) espousal.', 'denominative passive participle from 3618;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3625}/[H3625]', 'lemma', 'heb', 'כֶּלַח', '["Kelach"]', '["Kelach, a place in Assyria Calah."]', '["n-pr-loc"]', 'Kelach, a place in Assyria Calah.', 'the same as 3624;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3626}/[H3626]', 'lemma', 'heb', 'כׇּל־חֹזֶה', '["Kol-Chôzeh"]', '["Col-Chozeh, an Israelite Col-hozeh."]', '["n-pr-m"]', 'Col-Chozeh, an Israelite Col-hozeh.', 'from 3605 and 2374; every seer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3627}/[H3627]', 'lemma', 'heb', 'כְּלִי', '["kᵉlîy"]', '["something prepared, i.e. any apparatus (as an implement, utensil, dress, vessel or weapon) armour(-bearer), artillery, bag, carriage, furnish, furniture, instrument, jewel, that is made of, × one from another, that which pertaineth, pot, psaltery, sack, stuff, thing, tool, vessel, ware, weapon, whatsoever."]', '["n-m"]', 'something prepared, i.e. any apparatus (as an implement, utensil, dress, vessel or weapon) armour(-bearer), artillery, bag, carriage, furnish, furniture, instrument, jewel, that is made of, × one from another, that which pertaineth, pot, psaltery, sack, stuff, thing, tool, vessel, ware, weapon, whatsoever.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3628}/[H3628]', 'lemma', 'heb', 'כְּלִיא', '["kᵉlîyʼ"]', '["a prison prison."]', '["n-m"]', 'a prison prison.', 'or כְּלוּא; from 3627 (compare 3608);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3629}/[H3629]', 'lemma', 'heb', 'כִּלְיָה', '["kilyâh"]', '["a kidney (as an essential organ); figuratively, the mind (as the interior self) kidneys, reins."]', '["n-f"]', 'a kidney (as an essential organ); figuratively, the mind (as the interior self) kidneys, reins.', 'feminine of 3627 (only in the plural);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3630}/[H3630]', 'lemma', 'heb', 'כִּלְיוֹן', '["Kilyôwn"]', '["Kiljon, an Israelite Chilion."]', '["n-pr-m"]', 'Kiljon, an Israelite Chilion.', 'a form of 3631;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3631}/[H3631]', 'lemma', 'heb', 'כִּלָּיוֹן', '["killâyôwn"]', '["pining, destruction consumption, failing."]', '["n-m"]', 'pining, destruction consumption, failing.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3632}/[H3632]', 'lemma', 'heb', 'כָּלִיל', '["kâlîyl"]', '["complete; as noun, the whole (specifically, a sacrifice entirely consumed); as adverb, fully all, every whit, flame, perfect(-ion), utterly, whole burnt offering (sacrifice), wholly."]', '["a"]', 'complete; as noun, the whole (specifically, a sacrifice entirely consumed); as adverb, fully all, every whit, flame, perfect(-ion), utterly, whole burnt offering (sacrifice), wholly.', 'from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3633}/[H3633]', 'lemma', 'heb', 'כַּלְכֹּל', '["Kalkôl"]', '["Calcol, an Israelite Calcol, Chalcol."]', '["n-pr-m"]', 'Calcol, an Israelite Calcol, Chalcol.', 'from 3557; sustenance;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3634]', 'root', 'heb', 'כָּלַל', '["kâlal"]', '["to complete (make) perfect."]', '["v"]', 'to complete (make) perfect.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3635}/[H3635]', 'lemma', 'arc', 'כְּלַל', '["kᵉlal"]', '["to complete finish, make (set) up."]', '["v"]', 'to complete finish, make (set) up.', '(Aramaic) corresponding to 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3636}/[H3636]', 'lemma', 'heb', 'כְּלָל', '["Kᵉlâl"]', '["Kelal, an Israelite Chelal."]', '["n-pr-m"]', 'Kelal, an Israelite Chelal.', 'from 3634; complete;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3637]', 'root', 'heb', 'כָּלַם', '["kâlam"]', '["properly, to wound; but only figuratively, to taunt or insult be (make) ashamed, blush, be confounded, be put to confusion, hurt, reproach, (do, put to) shame."]', '["v"]', 'properly, to wound; but only figuratively, to taunt or insult be (make) ashamed, blush, be confounded, be put to confusion, hurt, reproach, (do, put to) shame.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3639}/[H3639]', 'lemma', 'heb', 'כְּלִמָּה', '["kᵉlimmâh"]', '["disgrace confusion, dishonour, reproach, shame."]', '["n-f"]', 'disgrace confusion, dishonour, reproach, shame.', 'from 3637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3640}/[H3640]', 'lemma', 'heb', 'כְּלִמּוּת', '["kᵉlimmûwth"]', '["disgrace shame."]', '["n-f"]', 'disgrace shame.', 'from 3639;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3641}/[H3641]', 'lemma', 'heb', 'כַּלְנֶה', '["Kalneh"]', '["Calneh or Calno, a place in the Assyrian empire Calneh, Calno. Compare 3656."]', '["n-pr-loc"]', 'Calneh or Calno, a place in the Assyrian empire Calneh, Calno. Compare 3656.', 'or כַּלְנֵה; also כַּלְנוֹ; of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3642]', 'root', 'heb', 'כָּמַהּ', '["kâmahh"]', '["to pine after long."]', '["v"]', 'to pine after long.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3643}/[H3643]', 'lemma', 'heb', 'כִּמְהָם', '["Kimhâm"]', '["Kimham, an Israelite Chimham."]', '["n-pr-m n-pr-loc"]', 'Kimham, an Israelite Chimham.', 'from 3642; pining;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3644}/[H3644]', 'lemma', 'heb', 'כְּמוֹ', '["kᵉmôw"]', '["as, thus, so according to, (such) as (it were, well as), in comparison of, like (as, to, unto), thus, when, worth."]', '["prt"]', 'as, thus, so according to, (such) as (it were, well as), in comparison of, like (as, to, unto), thus, when, worth.', 'or כָּמוֹ; a form of the prefix k, but used separately [compare 3651];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3647]', 'root', 'heb', 'כָּמַס', '["kâmaç"]', '["to store away, i.e. (figuratively) in the memory lay up in store."]', '["v"]', 'to store away, i.e. (figuratively) in the memory lay up in store.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3648]', 'root', 'heb', 'כָּמַר', '["kâmar"]', '["properly, to intertwine or contract, i.e. (by implication) to shrivel (as with heat); figuratively, to be deeply affected with passion (love or pity) be black, be kindled, yearn."]', '["v"]', 'properly, to intertwine or contract, i.e. (by implication) to shrivel (as with heat); figuratively, to be deeply affected with passion (love or pity) be black, be kindled, yearn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3649}/[H3649]', 'lemma', 'heb', 'כָּמָר', '["kâmâr"]', '["properly, an ascetic (as if shrunk with self-maceration), i.e. an idolatrous priest (only in plural) Chemarims (idolatrous) priests."]', '["n-m"]', 'properly, an ascetic (as if shrunk with self-maceration), i.e. an idolatrous priest (only in plural) Chemarims (idolatrous) priests.', 'from 3648;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3650}/[H3650]', 'lemma', 'heb', 'כִּמְרִיר', '["kimrîyr"]', '["obscuration (as if from shrinkage of light), i.e. an eclipse (only in plural) blackness."]', '["n-m"]', 'obscuration (as if from shrinkage of light), i.e. an eclipse (only in plural) blackness.', 'redupl. from 3648;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3651}/[H3651]', 'lemma', 'heb', 'כֵּן', '["kên"]', '["properly, set upright; hence (figuratively as adjective) just; but usually (as adverb or conjunction) rightly or so (in various applications to manner, time and relation; often with other particles) after that (this, -ward, -wards), as... as, (for-) asmuch as yet, be (for which) cause, following, howbeit, in (the) like (manner, -wise), × the more, right, (even) so, state, straightway, such (thing), surely, there (where) -fore, this, thus, true, well, × you."]', '["adv"]', 'properly, set upright; hence (figuratively as adjective) just; but usually (as adverb or conjunction) rightly or so (in various applications to manner, time and relation; often with other particles) after that (this, -ward, -wards), as... as, (for-) asmuch as yet, be (for which) cause, following, howbeit, in (the) like (manner, -wise), × the more, right, (even) so, state, straightway, such (thing), surely, there (where) -fore, this, thus, true, well, × you.', 'from 3559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3652}/[H3652]', 'lemma', 'arc', 'כֵּן', '["kên"]', '["so thus."]', '["adv"]', 'so thus.', '(Aramaic) corresponding to 3651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3653}/[H3653]', 'lemma', 'heb', 'כֵּן', '["kên"]', '["a stand, i.e. pedestal or station base, estate, foot, office, place, well."]', '["n-m"]', 'a stand, i.e. pedestal or station base, estate, foot, office, place, well.', 'the same as 3651, used as a noun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3654}/[H3654]', 'lemma', 'heb', 'כֵּן', '["kên"]', '["a gnat lice, × manner."]', '["n-m"]', 'a gnat lice, × manner.', 'from 3661 in the sense of fastening; (from infixing its sting; used only in plural (and irregular in Exodus 8:17,18; Hebrews 13:14))');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3655]', 'root', 'heb', 'כָּנָה', '["kânâh"]', '["to address by an additional name; hence, to eulogize give flattering titles, surname (himself)."]', '["v"]', 'to address by an additional name; hence, to eulogize give flattering titles, surname (himself).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3656}/[H3656]', 'lemma', 'heb', 'כַּנֶּה', '["Kanneh"]', '["Canneh, a place in Assyria Canneh."]', '["n-pr-loc"]', 'Canneh, a place in Assyria Canneh.', 'for 3641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3657}/[H3657]', 'lemma', 'heb', 'כַּנָּה', '["kannâh"]', '["a plant (as set) × vineyard."]', '["n-f"]', 'a plant (as set) × vineyard.', 'from 3661;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3659}/[H3659]', 'lemma', 'heb', 'כׇּנְיָהוּ', '["Konyâhûw"]', '["Conjah, an Israelite king Coniah."]', '["n-pr-m"]', 'Conjah, an Israelite king Coniah.', 'for 3204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3660}/[H3660]', 'lemma', 'arc', 'כְּנֵמָא', '["kᵉnêmâʼ"]', '["so or thus so, (in) this manner (sort), thus."]', '["adv"]', 'so or thus so, (in) this manner (sort), thus.', '(Aramaic) corresponding to 3644;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3661]', 'root', 'heb', 'כָּנַן', '["kânan"]', '["to set out, i.e. plant × vineyard."]', '["n-f"]', 'to set out, i.e. plant × vineyard.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3662}/[H3662]', 'lemma', 'heb', 'כְּנָנִי', '["Kᵉnânîy"]', '["Kenani, an Israelite Chenani."]', '["n-pr-m"]', 'Kenani, an Israelite Chenani.', 'from 3661; planted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3663}/[H3663]', 'lemma', 'heb', 'כְּנַנְיָה', '["Kᵉnanyâh"]', '["Kenanjah, an Israelite Chenaniah."]', '["n-pr-m"]', 'Kenanjah, an Israelite Chenaniah.', 'or כְּנַנְיָהוּ; from 3661 and 3050; Jah has planted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3664]', 'root', 'heb', 'כָּנַס', '["kânaç"]', '["to collect; hence, to enfold gather (together), heap up, wrap self."]', '["v"]', 'to collect; hence, to enfold gather (together), heap up, wrap self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3665]', 'root', 'heb', 'כָּנַע', '["kânaʻ"]', '["properly, to bend the knee; hence, to humiliate, vanquish bring down (low), into subjection, under, humble (self), subdue."]', '["v"]', 'properly, to bend the knee; hence, to humiliate, vanquish bring down (low), into subjection, under, humble (self), subdue.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3666}/[H3666]', 'lemma', 'heb', 'כִּנְעָה', '["kinʻâh"]', '["a package wares."]', '["n-f"]', 'a package wares.', 'from 3665 in the sense of folding (compare 3664);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3667}/[H3667]', 'lemma', 'heb', 'כְּנַעַן', '["Kᵉnaʻan"]', '["Kenaan, a son a Ham; also the country inhabited by him Canaan, merchant, traffick."]', '["n-pr-m n-pr-loc n-m"]', 'Kenaan, a son a Ham; also the country inhabited by him Canaan, merchant, traffick.', 'from 3665; humiliated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3668}/[H3668]', 'lemma', 'heb', 'כְּנַעֲנָה', '["Kᵉnaʻănâh"]', '["Kenaanah, the name of two Israelites Chenaanah."]', '["n-pr-f"]', 'Kenaanah, the name of two Israelites Chenaanah.', 'feminine of 3667;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3669}/[H3669]', 'lemma', 'heb', 'כְּנַעַנִי', '["Kᵉnaʻanîy"]', '["a Kenaanite or inhabitant of Kenaan; by implication, a pedlar (the Canaanites standing for their neighbors the Ishmaelites, who conducted mercantile caravans) Canaanite, merchant, trafficker."]', '["n-m"]', 'a Kenaanite or inhabitant of Kenaan; by implication, a pedlar (the Canaanites standing for their neighbors the Ishmaelites, who conducted mercantile caravans) Canaanite, merchant, trafficker.', 'patrial from 3667;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3670]', 'root', 'heb', 'כָּנַף', '["kânaph"]', '["properly, to project laterally, i.e. probably (reflexive) to withdraw be removed."]', '["v"]', 'properly, to project laterally, i.e. probably (reflexive) to withdraw be removed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3671}/[H3671]', 'lemma', 'heb', 'כָּנָף', '["kânâph"]', '["an edge or extremity; specifically (of a bird or army) a wing, (of a garment or bedclothing) a flap, (of the earth) a quarter, (of a building) a pinnacle bird, border, corner, end, feather(-ed), × flying, (one an-) other, overspreading, × quarters, skirt, × sort, uttermost part, wing(-ed)."]', '["n-f"]', 'an edge or extremity; specifically (of a bird or army) a wing, (of a garment or bedclothing) a flap, (of the earth) a quarter, (of a building) a pinnacle bird, border, corner, end, feather(-ed), × flying, (one an-) other, overspreading, × quarters, skirt, × sort, uttermost part, wing(-ed).', 'from 3670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3672}/[H3672]', 'lemma', 'heb', 'כִּנְּרוֹת', '["Kinnᵉrôwth"]', '["Kinneroth or Kinnereth, a place in Palestine Chinnereth, Chinneroth, Cinneroth."]', '["n-pr-loc"]', 'Kinneroth or Kinnereth, a place in Palestine Chinnereth, Chinneroth, Cinneroth.', 'or כִּנֶּרֶתlemma כִּנֶרֶת missing dagesh, corrected to כִּנֶּרֶת; respectively plural and singular feminine from the same as 3658; perhaps harp-shaped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3673}/[H3673]', 'lemma', 'arc', 'כָּנַשׁ', '["kânash"]', '["to assemble gather together."]', '["v"]', 'to assemble gather together.', '(Aramaic) corresponding to 3664;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3674}/[H3674]', 'lemma', 'heb', 'כְּנָת', '["kᵉnâth"]', '["a colleague (as having the same title) companion."]', '["n-m"]', 'a colleague (as having the same title) companion.', 'from 3655;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3675}/[H3675]', 'lemma', 'arc', 'כְּנָת', '["kᵉnâth"]', '["companion."]', '["n-m"]', 'companion.', '(Aramaic) corresponding to 3674');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3676}/[H3676]', 'lemma', 'heb', 'כֵּס', '["kêç"]', '["sworn."]', '["n-m"]', 'sworn.', 'apparently a contraction for 3678, but probably by erroneous transcription for 5251');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3677}/[H3677]', 'lemma', 'heb', 'כֶּסֶא', '["keçeʼ"]', '["properly, fulness or the full moon, i.e. its festival (time) appointed."]', '["n-m"]', 'properly, fulness or the full moon, i.e. its festival (time) appointed.', 'or כֶּסֶה; apparently from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3678}/[H3678]', 'lemma', 'heb', 'כִּסֵּא', '["kiççêʼ"]', '["properly, covered, i.e. a throne (as canopied) seat, stool, throne."]', '["n-m"]', 'properly, covered, i.e. a throne (as canopied) seat, stool, throne.', 'or כִּסֵּה; from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3679}/[H3679]', 'lemma', 'heb', 'כַּסְדַּי', '["Kaçday"]', '["Chaldean."]', '["a"]', 'Chaldean.', 'for 3778');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3680]', 'root', 'heb', 'כָּסָה', '["kâçâh"]', '["properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780."]', '["v"]', 'properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3681}/[H3681]', 'lemma', 'heb', 'כָּסוּי', '["kâçûwy"]', '["properly, covered, i.e. (as noun) a covering covering."]', '["n-m"]', 'properly, covered, i.e. (as noun) a covering covering.', 'passive participle of 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3682}/[H3682]', 'lemma', 'heb', 'כְּסוּת', '["kᵉçûwth"]', '["a cover (garment); figuratively, a veiling covering, raiment, vesture."]', '["n-f"]', 'a cover (garment); figuratively, a veiling covering, raiment, vesture.', 'from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3683]', 'root', 'heb', 'כָּסַח', '["kâçach"]', '["to cut off cut down (up)."]', '["v"]', 'to cut off cut down (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3684}/[H3684]', 'lemma', 'heb', 'כְּסִיל', '["kᵉçîyl"]', '["properly, fat, i.e. (figuratively) stupid or silly fool(-ish)."]', '["n-m"]', 'properly, fat, i.e. (figuratively) stupid or silly fool(-ish).', 'from 3688;');
