INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3688]', 'root', 'heb', 'כָּסַל', '["kâçal"]', '["properly, to be fat, i.e. (figuratively) silly be foolish."]', '["v"]', 'properly, to be fat, i.e. (figuratively) silly be foolish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3689}/[H3689]', 'lemma', 'heb', 'כֶּסֶל', '["keçel"]', '["properly, fatness, i.e. by implication (literally) the loin (as the seat of the leaf fat) or (generally) the viscera; also (figuratively) silliness or (in a good sense) trust confidence, flank, folly, hope, loin."]', '["n-m"]', 'properly, fatness, i.e. by implication (literally) the loin (as the seat of the leaf fat) or (generally) the viscera; also (figuratively) silliness or (in a good sense) trust confidence, flank, folly, hope, loin.', 'from 3688;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3690}/[H3690]', 'lemma', 'heb', 'כִּסְלָה', '["kiçlâh"]', '["in a good sense, trust; in a bad one, silliness confidence, folly."]', '["n-f"]', 'in a good sense, trust; in a bad one, silliness confidence, folly.', 'feminine of 3689;');
