INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3696}/[H3696]', 'lemma', 'heb', 'כִּסְלֹת תָּבֹר', '["Kiçlôth Tâbôr"]', '["Kisloth-Tabor, a place in Palestine Chisloth-tabor."]', '["n-pr-loc"]', 'Kisloth-Tabor, a place in Palestine Chisloth-tabor.', 'from the feminine plural of 3689 and 8396; flanks of Tabor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3697]', 'root', 'heb', 'כָּסַם', '["kâçam"]', '["to shear × only, poll. Compare 3765."]', '["v"]', 'to shear × only, poll. Compare 3765.', 'a primitive root;');
