INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3699]', 'root', 'heb', 'כָּסַס', '["kâçaç"]', '["to estimate make count."]', '["v"]', 'to estimate make count.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3700]', 'root', 'heb', 'כָּסַף', '["kâçaph"]', '["properly, to become pale, i.e. (by implication) to pine after; also to fear (have) desire, be greedy, long, sore."]', '["v"]', 'properly, to become pale, i.e. (by implication) to pine after; also to fear (have) desire, be greedy, long, sore.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3701}/[H3701]', 'lemma', 'heb', 'כֶּסֶף', '["keçeph"]', '["silver (from its pale color); by implication, money money, price, silver(-ling)."]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3702}/[H3702]', 'lemma', 'arc', 'כְּסַף', '["kᵉçaph"]', '["money, silver."]', '["n-m"]', 'money, silver.', '(Aramaic) corresponding to 3701');
