INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3706}/[H3706]', 'lemma', 'arc', 'כְּעֶנֶת', '["kᵉʻeneth"]', '["thus (only in the formula ''and so forth'') at such a time."]', '["adv"]', 'thus (only in the formula ''and so forth'') at such a time.', '(Aramaic) or כְּעֶת; (Aramaic), feminine of 3705;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3707]', 'root', 'heb', 'כַּעַס', '["kaʻaç"]', '["to trouble; by implication, to grieve, rage, be indignant be angry, be grieved, take indignation, provoke (to anger, unto wrath), have sorrow, vex, be wroth."]', '["v"]', 'to trouble; by implication, to grieve, rage, be indignant be angry, be grieved, take indignation, provoke (to anger, unto wrath), have sorrow, vex, be wroth.', 'a primitive root;');
