INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3710}/[H3710]', 'lemma', 'heb', 'כֵּף', '["kêph"]', '["a hollow rock rock."]', '["n-m"]', 'a hollow rock rock.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3711]', 'root', 'heb', 'כָּפָה', '["kâphâh"]', '["properly, to bend, i.e. (figuratively) to tame or subdue pacify."]', '["v"]', 'properly, to bend, i.e. (figuratively) to tame or subdue pacify.', 'a primitive root;');
