INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3714>', 'opaque', 'heb', 'כָּפִיס', '["kâphîyç"]', '["a girder beam."]', '["n-m"]', 'a girder beam.', 'from an unused root meaning to connect;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3715}/[H3715]', 'lemma', 'heb', 'כְּפִיר', '["kᵉphîyr"]', '["a village (as covered in by walls); also a young lion (perhaps as covered with a mane) (young) lion, village. Compare 3723."]', '["n-m"]', 'a village (as covered in by walls); also a young lion (perhaps as covered with a mane) (young) lion, village. Compare 3723.', 'from 3722;');
