INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3720}/[H3720]', 'lemma', 'heb', 'כָּפָן', '["kâphân"]', '["hunger (as making to stoop with emptiness and pain) famine."]', '["n-m"]', 'hunger (as making to stoop with emptiness and pain) famine.', 'from 3719;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3721]', 'root', 'heb', 'כָּפַף', '["kâphaph"]', '["to curve bow down (self)."]', '["v"]', 'to curve bow down (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3722]', 'root', 'heb', 'כָּפַר', '["kâphar"]', '["to cover (specifically with bitumen); figuratively, to expiate or condone, to placate or cancel appease, make (an atonement, cleanse, disannul, forgive, be merciful, pacify, pardon, purge (away), put off, (make) reconcile(-liation)."]', '["v"]', 'to cover (specifically with bitumen); figuratively, to expiate or condone, to placate or cancel appease, make (an atonement, cleanse, disannul, forgive, be merciful, pacify, pardon, purge (away), put off, (make) reconcile(-liation).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3723}/[H3723]', 'lemma', 'heb', 'כָּפָר', '["kâphâr"]', '["a village (as protected by walls) village. Compare 3715."]', '["n-m"]', 'a village (as protected by walls) village. Compare 3715.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3724}/[H3724]', 'lemma', 'heb', 'כֹּפֶר', '["kôpher"]', '["properly, a cover, i.e. (literally) a village (as covered in); (specifically) bitumen (as used for coating), and the henna plant (as used for dyeing); figuratively, a redemption-price bribe, camphire, pitch, ransom, satisfaction, sum of money, village."]', '["n-m"]', 'properly, a cover, i.e. (literally) a village (as covered in); (specifically) bitumen (as used for coating), and the henna plant (as used for dyeing); figuratively, a redemption-price bribe, camphire, pitch, ransom, satisfaction, sum of money, village.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3725}/[H3725]', 'lemma', 'heb', 'כִּפֻּר', '["kippur"]', '["expiation (only in plural) atonement."]', '["n-m"]', 'expiation (only in plural) atonement.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3726}/[H3726]', 'lemma', 'heb', 'כְּפַר הָעַמּוֹנִי', '["Kᵉphar hâ-ʻAmmôwnîy"]', '["Kefar-ha-Ammoni, a place in Palestine Chefarhaamonai."]', '["n-pr-loc"]', 'Kefar-ha-Ammoni, a place in Palestine Chefarhaamonai.', 'from 3723 and 5984, with the article interposed; village of the Ammonite;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3727}/[H3727]', 'lemma', 'heb', 'כַּפֹּרֶת', '["kappôreth"]', '["a lid (used only of the cover of the sacred Ark) mercy seat."]', '["n-f"]', 'a lid (used only of the cover of the sacred Ark) mercy seat.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3728]', 'root', 'heb', 'כָּפַשׁ', '["kâphash"]', '["to tread down; figuratively, to humiliate cover."]', '["v"]', 'to tread down; figuratively, to humiliate cover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3731}/[H3731]', 'lemma', 'heb', 'כַּפְתֹּר', '["Kaphtôr"]', '["Caphtor (i.e. a wreath-shaped island), the original seat of the Philistines Caphtor."]', '["n-pr-loc"]', 'Caphtor (i.e. a wreath-shaped island), the original seat of the Philistines Caphtor.', 'or (Amos 9:7) כַּפְתּוֹר; apparently the same as 3730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3732}/[H3732]', 'lemma', 'heb', 'כַּפְתֹּרִי', '["Kaphtôrîy"]', '["a Caphtorite (collectively) or native of Caphtor Caphthorim, Caphtorim(-s)."]', '["a"]', 'a Caphtorite (collectively) or native of Caphtor Caphthorim, Caphtorim(-s).', 'patrial from 3731;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3733}/[H3733]', 'lemma', 'heb', 'כַּר', '["kar"]', '["a ram (as full-grown and fat), including a battering-ram (as butting); hence, a meadow (as for sheep); also a pad or camel''s saddle (as puffed out) captain, furniture, lamb, (large) pasture, ram. See also 1033, 3746."]', '["n-m"]', 'a ram (as full-grown and fat), including a battering-ram (as butting); hence, a meadow (as for sheep); also a pad or camel''s saddle (as puffed out) captain, furniture, lamb, (large) pasture, ram. See also 1033, 3746.', 'from 3769 in the sense of plumpness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3734}/[H3734]', 'lemma', 'heb', 'כֹּר', '["kôr"]', '["properly, a deep round vessel, i.e. (specifically) a cor or measure for things dry cor, measure. Aramaic the same."]', '["n-m"]', 'properly, a deep round vessel, i.e. (specifically) a cor or measure for things dry cor, measure. Aramaic the same.', 'from the same as 3564;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3735}/[H3735]', 'lemma', 'arc', 'כָּרָא', '["Kârâʼ"]', '["to grieve be grieved."]', '["v"]', 'to grieve be grieved.', '(Aramaic) probably corresponding to 3738 in the sense of piercing(figuratively);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3736}/[H3736]', 'lemma', 'heb', 'כַּרְבֵּל', '["karbêl"]', '["to gird or clothe clothed."]', '["v"]', 'to gird or clothe clothed.', 'from the same as 3525;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3737}/[H3737]', 'lemma', 'arc', 'כַּרְבְּלָא', '["karbᵉlâʼ"]', '["a mantle hat."]', '["n-m"]', 'a mantle hat.', '(Aramaic) from a verb corresponding to that of 3736;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3738]', 'root', 'heb', 'כָּרָה', '["kârâh"]', '["properly, to dig; figuratively, to plot; generally, to bore or open dig, × make (a banquet), open."]', '["v"]', 'properly, to dig; figuratively, to plot; generally, to bore or open dig, × make (a banquet), open.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3739]', 'root', 'heb', 'כָּרָה', '["kârâh"]', '["to purchase buy, prepare."]', '["v"]', 'to purchase buy, prepare.', 'usually assigned as a primitive root, but probably only a special application of 3738 (through the common idea of planning implied in a bargain);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3740}/[H3740]', 'lemma', 'heb', 'כֵּרָה', '["kêrâh"]', '["a purchase provision."]', '["n-f"]', 'a purchase provision.', 'from 3739;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3741}/[H3741]', 'lemma', 'heb', 'כָּרָה', '["kârâh"]', '["a meadow cottage."]', '["n-f"]', 'a meadow cottage.', 'feminine of 3733;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3743}/[H3743]', 'lemma', 'heb', 'כְּרוּב', '["Kᵉrûwb"]', '["Kerub, a place in Babylon Cherub."]', '["n-pr-loc"]', 'Kerub, a place in Babylon Cherub.', 'the same as 3742;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3744}/[H3744]', 'lemma', 'arc', 'כָּרוֹז', '["kârôwz"]', '["a herald herald."]', '["n-m"]', 'a herald herald.', '(Aramaic) from 3745;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3745}/[H3745]', 'lemma', 'arc', 'כְּרַז', '["kᵉraz"]', '["to proclaim make a proclamation."]', '["v"]', 'to proclaim make a proclamation.', '(Aramaic) probably of Greek origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3746}/[H3746]', 'lemma', 'heb', 'כָּרִי', '["kârîy"]', '["a life-guardsman captains, Cherethites (from the margin)."]', '["a"]', 'a life-guardsman captains, Cherethites (from the margin).', 'perhaps an abridged plural of 3733 in the sense of leader (of the flock);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3747}/[H3747]', 'lemma', 'heb', 'כְּרִית', '["Kᵉrîyth"]', '["Kerith, a brook of Palestine Cherith."]', '["n"]', 'Kerith, a brook of Palestine Cherith.', 'from 3772; a cut;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3748}/[H3748]', 'lemma', 'heb', 'כְּרִיתוּת', '["kᵉrîythûwth"]', '["a cutting (of the matrimonial bond), i.e. divorce divorce(-ment)."]', '["n-f"]', 'a cutting (of the matrimonial bond), i.e. divorce divorce(-ment).', 'from 3772;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3749}/[H3749]', 'lemma', 'heb', 'כַּרְכֹּב', '["karkôb"]', '["a rim or top margin compass."]', '["n-m"]', 'a rim or top margin compass.', 'expanded from the same as 3522;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3750>', 'opaque', 'heb', 'כַּרְכֹּם', '["karkôm"]', '["the crocus saffron."]', '["n-m"]', 'the crocus saffron.', 'probably of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3751}/[H3751]', 'lemma', 'heb', 'כַּרְכְּמִישׁ', '["Karkᵉmîysh"]', '["Karkemish, a place in Syria Carchemish."]', '["n-pr-loc"]', 'Karkemish, a place in Syria Carchemish.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3752}/[H3752]', 'lemma', 'heb', 'כַּרְכַּס', '["Karkaç"]', '["Karkas, a eunuch of Xerxes Carcas."]', '["n-pr-m"]', 'Karkas, a eunuch of Xerxes Carcas.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3753}/[H3753]', 'lemma', 'heb', 'כַּרְכָּרָה', '["karkârâh"]', '["a dromedary (from its rapid motion as if dancing) swift beast."]', '["n-f"]', 'a dromedary (from its rapid motion as if dancing) swift beast.', 'from 3769;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3755}/[H3755]', 'lemma', 'heb', 'כֹּרֵם', '["kôrêm"]', '["a vinedresser vine dresser (as one or two words)."]', '["v"]', 'a vinedresser vine dresser (as one or two words).', 'active participle of an imaginary denominative from 3754;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3756}/[H3756]', 'lemma', 'heb', 'כַּרְמִי', '["Karmîy"]', '["Karmi, the name of three Israelites Carmi."]', '["n-pr-m"]', 'Karmi, the name of three Israelites Carmi.', 'from 3754; gardener;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3757}/[H3757]', 'lemma', 'heb', 'כַּרְמִי', '["Karmîy"]', '["a Karmite or descendant of Karmi Carmites."]', '["a"]', 'a Karmite or descendant of Karmi Carmites.', 'patronymically from 3756;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3758>', 'opaque', 'heb', 'כַּרְמִיל', '["karmîyl"]', '["carmine, a deep red crimson."]', '["n-m"]', 'carmine, a deep red crimson.', 'probably of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3759}/[H3759]', 'lemma', 'heb', 'כַּרְמֶל', '["karmel"]', '["a planted field (garden, orchard, vineyard or park); by implication, garden produce full (green) ears (of corn), fruitful field (place), plentiful (field)."]', '["n-m"]', 'a planted field (garden, orchard, vineyard or park); by implication, garden produce full (green) ears (of corn), fruitful field (place), plentiful (field).', 'from 3754;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3760}/[H3760]', 'lemma', 'heb', 'כַּרְמֶל', '["Karmel"]', '["Karmel, the name of a hill and of a town in Palestine Carmel, fruitful (plentiful) field, (place)."]', '["n-pr-loc"]', 'Karmel, the name of a hill and of a town in Palestine Carmel, fruitful (plentiful) field, (place).', 'the same as 3759;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3761}/[H3761]', 'lemma', 'heb', 'כַּרְמְלִי', '["Karmᵉlîy"]', '["a Karmelite or inhabitant of Karmel (the town) Carmelite."]', '["a"]', 'a Karmelite or inhabitant of Karmel (the town) Carmelite.', 'patron from 3760;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3762}/[H3762]', 'lemma', 'heb', 'כַּרְמְלִית', '["Karmᵉlîyth"]', '["a Karmelitess or female inhabitant of Karmel Carmelitess."]', '["a"]', 'a Karmelitess or female inhabitant of Karmel Carmelitess.', 'feminine of 3761;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3763>', 'opaque', 'heb', 'כְּרָן', '["Kᵉrân"]', '["Keran, an aboriginal Idumaean Cheran."]', '["n-pr-m"]', 'Keran, an aboriginal Idumaean Cheran.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3764}/[H3764]', 'lemma', 'arc', 'כׇּרְסֵא', '["korçêʼ"]', '["a throne throne."]', '["n-m"]', 'a throne throne.', '(Aramaic) corresponding to 3678;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3765}/[H3765]', 'lemma', 'heb', 'כִּרְסֵם', '["kirçêm"]', '["to lay waste waste."]', '["v"]', 'to lay waste waste.', 'from 3697;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3766]', 'root', 'heb', 'כָּרַע', '["kâraʻ"]', '["to bend the knee; by implication, to sink, to prostrate bow (down, self), bring down (low), cast down, couch, fall, feeble, kneeling, sink, smite (stoop) down, subdue, × very."]', '["v"]', 'to bend the knee; by implication, to sink, to prostrate bow (down, self), bring down (low), cast down, couch, fall, feeble, kneeling, sink, smite (stoop) down, subdue, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3767}/[H3767]', 'lemma', 'heb', 'כָּרָע', '["kârâʻ"]', '["the leg (from the knee to the ankle) of men or locusts (only in the dual) leg."]', '["n-f"]', 'the leg (from the knee to the ankle) of men or locusts (only in the dual) leg.', 'from 3766;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3769]', 'root', 'heb', 'כָּרַר', '["kârar"]', '["to dance (i.e. whirl) dance(-ing)."]', '["v"]', 'to dance (i.e. whirl) dance(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3770}/[H3770]', 'lemma', 'heb', 'כְּרֵשׂ', '["kᵉrês"]', '["the paunch or belly (as swelling out) belly."]', '["n-m"]', 'the paunch or belly (as swelling out) belly.', 'by variation from 7164;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3772]', 'root', 'heb', 'כָּרַת', '["kârath"]', '["to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want."]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3773}/[H3773]', 'lemma', 'heb', 'כָּרֻתָה', '["kâruthâh"]', '["something cut, i.e. a hewn timber beam."]', '["n-f"]', 'something cut, i.e. a hewn timber beam.', 'passive participle feminine of 3772;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3774}/[H3774]', 'lemma', 'heb', 'כְּרֵתִי', '["Kᵉrêthîy"]', '["a Kerethite or life-guardsman Cherethims, Cherethites."]', '["a"]', 'a Kerethite or life-guardsman Cherethims, Cherethites.', 'probably from 3772 in the sense of executioner; (compare 2876) (only collectively in the singular as plural)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3775}/[H3775]', 'lemma', 'heb', 'כֶּשֶׂב', '["keseb"]', '["a young sheep lamb."]', '["n-m"]', 'a young sheep lamb.', 'apparently by transposition for 3532;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3776}/[H3776]', 'lemma', 'heb', 'כִּשְׂבָּה', '["kisbâh"]', '["a young ewe lamb."]', '["n-f"]', 'a young ewe lamb.', 'feminine of 3775;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3778}/[H3778]', 'lemma', 'heb', 'כַּשְׂדִּי', '["Kasdîy"]', '["a Kasdite, or descendant of Kesed; by implication, a Chaldaean (as if so descended); also an astrologer (as if proverbial of that people Chaldeans, Chaldees, inhabitants of Chaldea."]', '["n-pr-loc n-pr-m"]', 'a Kasdite, or descendant of Kesed; by implication, a Chaldaean (as if so descended); also an astrologer (as if proverbial of that people Chaldeans, Chaldees, inhabitants of Chaldea.', '(occasionally with enclitic) כַּשְׂדִּימָה; towards the Kasdites into Chaldea), patronymically from 3777 (only in the plural);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3779}/[H3779]', 'lemma', 'heb', 'כַּשְׂדַּי', '["Kasday"]', '["a Chaldaean or inhabitant of Chaldaea; by implication, a Magian or professional astrologer Chaldean."]', '["n-m"]', 'a Chaldaean or inhabitant of Chaldaea; by implication, a Magian or professional astrologer Chaldean.', '(Aramaic) corresponding to 3778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3780]', 'root', 'heb', 'כָּשָׂה', '["kâsâh"]', '["to grow fat (i.e. be covered with flesh) be covered. Compare 3680."]', '["v"]', 'to grow fat (i.e. be covered with flesh) be covered. Compare 3680.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3781}/[H3781]', 'lemma', 'heb', 'כַּשִּׁיל', '["kashshîyl"]', '["properly, a feller, i.e. an axe ax."]', '["n-m"]', 'properly, a feller, i.e. an axe ax.', 'from 3782;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3782]', 'root', 'heb', 'כָּשַׁל', '["kâshal"]', '["to totter or waver (through weakness of the legs, especially the ankle); by implication, to falter, stumble, faint or fall bereave (from the margin), cast down, be decayed, (cause to) fail, (cause, make to) fall (down, -ing), feeble, be (the) ruin(-ed, of), (be) overthrown, (cause to) stumble, × utterly, be weak."]', '["v"]', 'to totter or waver (through weakness of the legs, especially the ankle); by implication, to falter, stumble, faint or fall bereave (from the margin), cast down, be decayed, (cause to) fail, (cause, make to) fall (down, -ing), feeble, be (the) ruin(-ed, of), (be) overthrown, (cause to) stumble, × utterly, be weak.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3783}/[H3783]', 'lemma', 'heb', 'כִּשָּׁלוֹן', '["kishshâlôwn"]', '["properly, a tottering, i.e. ruin fall."]', '["n-m"]', 'properly, a tottering, i.e. ruin fall.', 'from 3782;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3784]', 'root', 'heb', 'כָּשַׁף', '["kâshaph"]', '["properly, to whisper a spell, i.e. to inchant or practise magic sorcerer, (use) witch(-craft)."]', '["v"]', 'properly, to whisper a spell, i.e. to inchant or practise magic sorcerer, (use) witch(-craft).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3785}/[H3785]', 'lemma', 'heb', 'כֶּשֶׁף', '["kesheph"]', '["magic sorcery, witchcraft."]', '["n-m"]', 'magic sorcery, witchcraft.', 'from 3784;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3786}/[H3786]', 'lemma', 'heb', 'כַּשָּׁף', '["kashshâph"]', '["a magician sorcerer."]', '["n-m"]', 'a magician sorcerer.', 'from 3784;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3787]', 'root', 'heb', 'כָּשֵׁר', '["kâshêr"]', '["by implication, to be acceptable; also to succeed or prosper direct, be right, prosper."]', '["v"]', 'by implication, to be acceptable; also to succeed or prosper direct, be right, prosper.', 'a primitive root properly, to be straight or right;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3788}/[H3788]', 'lemma', 'heb', 'כִּשְׁרוֹן', '["kishrôwn"]', '["success, advantage equity, good, right."]', '["n-m"]', 'success, advantage equity, good, right.', 'from 3787;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3789]', 'root', 'heb', 'כָּתַב', '["kâthab"]', '["to grave, by implication, to write (describe, inscribe, prescribe, subscribe) describe, record, prescribe, subscribe, write(-ing, -ten)."]', '["v"]', 'to grave, by implication, to write (describe, inscribe, prescribe, subscribe) describe, record, prescribe, subscribe, write(-ing, -ten).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3790}/[H3790]', 'lemma', 'arc', 'כְּתַב', '["kᵉthab"]', '["write(-ten)."]', '["v"]', 'write(-ten).', '(Aramaic) corresponding to 3789');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3791}/[H3791]', 'lemma', 'heb', 'כָּתָב', '["kâthâb"]', '["something written, i.e. a writing, record or book register, scripture, writing."]', '["n-m"]', 'something written, i.e. a writing, record or book register, scripture, writing.', 'from 3789;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3792}/[H3792]', 'lemma', 'arc', 'כְּתָב', '["kᵉthâb"]', '["prescribing, writing(-ten)."]', '["n-m"]', 'prescribing, writing(-ten).', '(Aramaic) corresponding to 3791');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3793}/[H3793]', 'lemma', 'heb', 'כְּתֹבֶת', '["kᵉthôbeth"]', '["a letter or other mark branded on the skin × any (mark)."]', '["n-f"]', 'a letter or other mark branded on the skin × any (mark).', 'from 3789;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3794}/[H3794]', 'lemma', 'heb', 'כִּתִּי', '["Kittîy"]', '["a Kittite or Cypriote; hence, an islander in general, i.e. the Greeks or Romans on the shores opposite Palestine Chittim, Kittim."]', '["a"]', 'a Kittite or Cypriote; hence, an islander in general, i.e. the Greeks or Romans on the shores opposite Palestine Chittim, Kittim.', 'or כִּתִּיִּי; patrial from an unused name denoting Cyprus (only in the plural);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3795}/[H3795]', 'lemma', 'heb', 'כָּתִית', '["kâthîyth"]', '["beaten, i.e. pure (oil) beaten."]', '["a"]', 'beaten, i.e. pure (oil) beaten.', 'from 3807;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3796>', 'opaque', 'heb', 'כֹּתֶל', '["kôthel"]', '["a wall (as gathering inmates) wall."]', '["n-m"]', 'a wall (as gathering inmates) wall.', 'from an unused root meaning to compact;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3797}/[H3797]', 'lemma', 'arc', 'כְּתַל', '["kᵉthal"]', '["wall."]', '["n-m"]', 'wall.', '(Aramaic) corresponding to 3796');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3798}/[H3798]', 'lemma', 'heb', 'כִּתְלִישׁ', '["Kithlîysh"]', '["Kithlish, a place in Palestine Kithlish."]', '["n-pr-loc"]', 'Kithlish, a place in Palestine Kithlish.', 'from 3796 and 376; wall of a man;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3799]', 'root', 'heb', 'כָּתַם', '["kâtham"]', '["properly, to carve or engrave, i.e. (by implication) to inscribe indelibly mark."]', '["v"]', 'properly, to carve or engrave, i.e. (by implication) to inscribe indelibly mark.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3800}/[H3800]', 'lemma', 'heb', 'כֶּתֶם', '["kethem"]', '["properly, something carved out, i.e. ore; hence, gold (pure as originally mined) ((most) fine, pure) gold(-en wedge)."]', '["n-m"]', 'properly, something carved out, i.e. ore; hence, gold (pure as originally mined) ((most) fine, pure) gold(-en wedge).', 'from 3799;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3803]', 'root', 'heb', 'כָּתַר', '["kâthar"]', '["to enclose; hence (in a friendly sense) to crown, (in a hostile one) to besiege; also to wait (as restraining oneself) beset round, compass about, be crowned, inclose round, suffer."]', '["v"]', 'to enclose; hence (in a friendly sense) to crown, (in a hostile one) to besiege; also to wait (as restraining oneself) beset round, compass about, be crowned, inclose round, suffer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3804}/[H3804]', 'lemma', 'heb', 'כֶּתֶר', '["kether"]', '["properly, a circlet, i.e. a diadem crown."]', '["n-m"]', 'properly, a circlet, i.e. a diadem crown.', 'from 3803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3805}/[H3805]', 'lemma', 'heb', 'כֹתֶרֶת', '["kôthereth"]', '["the capital of a column chapiter."]', '["n-f"]', 'the capital of a column chapiter.', 'feminine active participle of 3803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3806]', 'root', 'heb', 'כָּתַשׁ', '["kâthash"]', '["to butt or pound bray."]', '["v"]', 'to butt or pound bray.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3807]', 'root', 'heb', 'כָּתַת', '["kâthath"]', '["to bruise or violently strike beat (down, to pieces), break in pieces, crushed, destroy, discomfit, smite, stamp. l"]', '["v"]', 'to bruise or violently strike beat (down, to pieces), break in pieces, crushed, destroy, discomfit, smite, stamp. l', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3809}/[H3809]', 'lemma', 'arc', 'לָא', '["lâʼ"]', '["or even, neither, no(-ne, -r), (can-) not, as nothing, without."]', '["adv"]', 'or even, neither, no(-ne, -r), (can-) not, as nothing, without.', '(Aramaic) or לָה; (Aramaic) (Daniel 4:32), corresponding to 3808');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3810}/[H3810]', 'lemma', 'heb', 'לֹא דְבַר', '["Lôʼ Dᵉbar"]', '["Lo-Debar, a place in Palestine Debir, Lodebar."]', '["n-pr-loc"]', 'Lo-Debar, a place in Palestine Debir, Lodebar.', 'or לוֹ דבַר; (Samuel 9:4,5), or לִדְבִר; (Joshua 13:26), (probably rather לֹדְבַר ); from 3808 and 1699; pastureless;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3811]', 'root', 'heb', 'לָאָה', '["lâʼâh"]', '["to tire; (figuratively) to be (or make) disgusted faint, grieve, lothe, (be, make) weary (selves)."]', '["v"]', 'to tire; (figuratively) to be (or make) disgusted faint, grieve, lothe, (be, make) weary (selves).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3812}/[H3812]', 'lemma', 'heb', 'לֵאָה', '["Lêʼâh"]', '["Leah, a wife of Jacob Leah."]', '["n-pr-f"]', 'Leah, a wife of Jacob Leah.', 'from 3811; weary;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3813]', 'root', 'heb', 'לָאַט', '["lâʼaṭ"]', '["to muffle cover."]', '["v"]', 'to muffle cover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3814}/[H3814]', 'lemma', 'heb', 'לָאט', '["lâʼṭ"]', '["properly, muffled, i.e. silently softly."]', '["n-m"]', 'properly, muffled, i.e. silently softly.', 'from 3813 (or perhaps for active participle of 3874);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3815}/[H3815]', 'lemma', 'heb', 'לָאֵל', '["Lâʼêl"]', '["Laël an Israelite Lael."]', '["n-pr-m"]', 'Laël an Israelite Lael.', 'from the prepositional prefix and 410; (belonging) to God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3817}/[H3817]', 'lemma', 'heb', 'לְאֻמִּים', '["Lᵉʼummîym"]', '["Leummim, an Arabian Leummim."]', '["n-m"]', 'Leummim, an Arabian Leummim.', 'plural of 3816; communities;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3818}/[H3818]', 'lemma', 'heb', 'לֹא עַמִּי', '["Lôʼ ʻAmmîy"]', '["Lo-Ammi, the symbolic name of a son of Hosea Lo-ammi."]', '["n-pr-m"]', 'Lo-Ammi, the symbolic name of a son of Hosea Lo-ammi.', 'from 3808 and 5971 with pronominal suffix; not my people;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3819}/[H3819]', 'lemma', 'heb', 'לֹא רֻחָמָה', '["Lôʼ Ruchâmâh"]', '["Lo-Ruchamah, the symbolic name of a son of Hosea Lo-ruhamah."]', '["n-pr-f"]', 'Lo-Ruchamah, the symbolic name of a son of Hosea Lo-ruhamah.', 'from 3808 and 7355; not pitied;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3820}/[H3820]', 'lemma', 'heb', 'לֵב', '["lêb"]', '["the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom."]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3821}/[H3821]', 'lemma', 'arc', 'לֵב', '["lêb"]', '["heart."]', '["n-m"]', 'heart.', '(Aramaic) corresponding to 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3822}/[H3822]', 'lemma', 'heb', 'לְבָאוֹת', '["Lᵉbâʼôwth"]', '["Lebaoth, a place in Palestine Lebaoth. See also 1034."]', '["n-pr-loc"]', 'Lebaoth, a place in Palestine Lebaoth. See also 1034.', 'plural of 3833; lionesses;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3823]', 'root', 'heb', 'לָבַב', '["lâbab"]', '["properly, to be enclosed (as if with fat); by implication (as denominative from 3824); to unheart; i.e. (in a good sense) transport (with love), or (in a bad sense) stultify; to make cakes make cakes, ravish, be wise."]', '["v"]', 'properly, to be enclosed (as if with fat); by implication (as denominative from 3824); to unheart; i.e. (in a good sense) transport (with love), or (in a bad sense) stultify; to make cakes make cakes, ravish, be wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3824}/[H3824]', 'lemma', 'heb', 'לֵבָב', '["lêbâb"]', '["the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding."]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3825}/[H3825]', 'lemma', 'arc', 'לְבַב', '["lᵉbab"]', '["heart."]', '["n-m"]', 'heart.', '(Aramaic) corresponding to 3824');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3826}/[H3826]', 'lemma', 'heb', 'לִבָּה', '["libbâh"]', '["the heart heart."]', '["n-f"]', 'the heart heart.', 'feminine of 3820;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3827}/[H3827]', 'lemma', 'heb', 'לַבָּה', '["labbâh"]', '["flame flame."]', '["n-f"]', 'flame flame.', 'for 3852;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3828}/[H3828]', 'lemma', 'heb', 'לְבוֹנָה', '["lᵉbôwnâh"]', '["frankincense (from its whiteness or perhaps that of its smoke) (frank-) incense."]', '["n-f"]', 'frankincense (from its whiteness or perhaps that of its smoke) (frank-) incense.', 'or לְבֹנָה; from 3836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3829}/[H3829]', 'lemma', 'heb', 'לְבוֹנָה', '["Lᵉbôwnâh"]', '["Lebonah, a place in Palestine Lebonah."]', '["n-pr-loc"]', 'Lebonah, a place in Palestine Lebonah.', 'the same as 3828;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3830}/[H3830]', 'lemma', 'heb', 'לְבוּשׁ', '["lᵉbûwsh"]', '["a garment (literally or figuratively); by implication (euphemistically) a wife apparel, clothed with, clothing, garment, raiment, vestment, vesture."]', '["n-m"]', 'a garment (literally or figuratively); by implication (euphemistically) a wife apparel, clothed with, clothing, garment, raiment, vestment, vesture.', 'or לְבֻשׁ; from 3847;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3831}/[H3831]', 'lemma', 'arc', 'לְבוּשׁ', '["lᵉbûwsh"]', '["garment."]', '["n-m"]', 'garment.', '(Aramaic) corresponding to 3830');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3832]', 'root', 'heb', 'לָבַט', '["lâbaṭ"]', '["to overthrow; intransposed, to fall fall."]', '["v"]', 'to overthrow; intransposed, to fall fall.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3833>', 'opaque', 'heb', 'לָבִיא', '["lâbîyʼ"]', '["a lion (properly, a lioness as the fiercer (although not a roarer;)) (great, old, stout) lion, lioness, young (lion)."]', '["n"]', 'a lion (properly, a lioness as the fiercer (although not a roarer;)) (great, old, stout) lion, lioness, young (lion).', 'or (Ezekiel 19:2) לְבִיָּא; irregular masculine plural לְבָאִים; irregular feminine plural לְבָאוֹת; from an unused root meaning to roar; compare 738');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3834}/[H3834]', 'lemma', 'heb', 'לָבִיבָה', '["lâbîybâh"]', '["a cake (either as fried or turned) cake."]', '["n-f"]', 'a cake (either as fried or turned) cake.', 'or rather לְבִבָה; from 3823 in its original sense of fatness (or perhaps of folding);');
