INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3846}/[H3846]', 'lemma', 'heb', 'לִבְנִי', '["Libnîy"]', '["a Libnite or descendants of Libni (collectively) Libnites."]', '["a"]', 'a Libnite or descendants of Libni (collectively) Libnites.', 'patronymically from 3845;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3847]', 'root', 'heb', 'לָבַשׁ', '["lâbash"]', '["properly, wrap around, i.e. (by implication) to put on a garment or clothe (oneself, or another), literally or figuratively (in) apparel, arm, array (self), clothe (self), come upon, put (on, upon), wear."]', '["v"]', 'properly, wrap around, i.e. (by implication) to put on a garment or clothe (oneself, or another), literally or figuratively (in) apparel, arm, array (self), clothe (self), come upon, put (on, upon), wear.', 'or לָבֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3848}/[H3848]', 'lemma', 'arc', 'לְבַשׁ', '["lᵉbash"]', '["clothe."]', '["v"]', 'clothe.', '(Aramaic) corresponding to 3847');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3852}/[H3852]', 'lemma', 'heb', 'לֶהָבָה', '["lehâbâh"]', '["flame(-ming), head (of a spear)."]', '["n-f"]', 'flame(-ming), head (of a spear).', 'or לַהֶבֶת; feminine of 3851, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3853}/[H3853]', 'lemma', 'heb', 'לְהָבִים', '["Lᵉhâbîym"]', '["Lehabim, a son of Mizraim, and his descendants Lehabim."]', '["n-m"]', 'Lehabim, a son of Mizraim, and his descendants Lehabim.', 'plural of 3851; flames;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3854>', 'opaque', 'heb', 'לַהַג', '["lahag"]', '["intense mental application study."]', '["n-m"]', 'intense mental application study.', 'from an unused root meaning to be eager;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3856]', 'root', 'heb', 'לָהַהּ', '["lâhahh"]', '["to be rabid (figuratively, insane); also (from the exhaustion of frenzy) to languish faint, mad."]', '["v"]', 'to be rabid (figuratively, insane); also (from the exhaustion of frenzy) to languish faint, mad.', 'a primitive root meaning properly, to burn, i.e. (by implication)');
