INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3859]', 'root', 'heb', 'לָהַם', '["lâham"]', '["properly, to burn in, i.e. (figuratively) to rankle wound."]', '["v"]', 'properly, to burn in, i.e. (figuratively) to rankle wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3860}/[H3860]', 'lemma', 'heb', 'לָהֵן', '["lâhên"]', '["properly for if; hence, therefore for them (by mistake for prepositional suffix)."]', '["conj"]', 'properly for if; hence, therefore for them (by mistake for prepositional suffix).', 'from the prepositional prefix meaning to or for and 2005;');
