INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3867]', 'root', 'heb', 'לָוָה', '["lâvâh"]', '["properly, to twine, i.e. (by implication) to unite, to remain; also to borrow (as a form of obligation) or (caus.) to lend abide with, borrow(-er), cleave, join (self), lend(-er)."]', '["v"]', 'properly, to twine, i.e. (by implication) to unite, to remain; also to borrow (as a form of obligation) or (caus.) to lend abide with, borrow(-er), cleave, join (self), lend(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3868]', 'root', 'heb', 'לוּז', '["lûwz"]', '["to turn aside , i.e. (literally) to depart, (figuratively) be perverse depart, froward, perverse(-ness)."]', '["v"]', 'to turn aside , i.e. (literally) to depart, (figuratively) be perverse depart, froward, perverse(-ness).', 'a primitive root; (compare 3867, 3874 and 3885)');
