INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3871]', 'root', 'heb', 'לוּחַ', '["lûwach"]', '["probably meaning to glisten; a tablet (as polished), of stone, wood or metal board, plate, table."]', '["n-m"]', 'probably meaning to glisten; a tablet (as polished), of stone, wood or metal board, plate, table.', 'or לֻחַ; from a primitive root;');
