INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3882}/[H3882]', 'lemma', 'heb', 'לִוְיָתָן', '["livyâthân"]', '["a wreathed animal, i.e. a serpent (especially the crocodile or some other large sea-monster); figuratively, the constellation of the dragon; also as a symbol of Babylon leviathan, mourning."]', '["n-m"]', 'a wreathed animal, i.e. a serpent (especially the crocodile or some other large sea-monster); figuratively, the constellation of the dragon; also as a symbol of Babylon leviathan, mourning.', 'from 3867;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3883>', 'opaque', 'heb', 'לוּל', '["lûwl"]', '["a spiral step winding stair. Compare 3924."]', '["n-m"]', 'a spiral step winding stair. Compare 3924.', 'from an unused root meaning to fold back;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3884}/[H3884]', 'lemma', 'heb', 'לוּלֵא', '["lûwlêʼ"]', '["if not except, had not, if (...not), unless, were it not that."]', '["conj"]', 'if not except, had not, if (...not), unless, were it not that.', 'or לוּלֵי; from 3863 and 3808;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3885]', 'root', 'heb', 'לוּן', '["lûwn"]', '["to stop (usually over night); by implication, to stay permanently; hence (in a bad sense) to be obstinate (especially in words, to complain) abide (all night), continue, dwell, endure, grudge, be left, lie all night, (cause to) lodge (all night, in, -ing, this night), (make to) murmur, remain, tarry (all night, that night)."]', '["v"]', 'to stop (usually over night); by implication, to stay permanently; hence (in a bad sense) to be obstinate (especially in words, to complain) abide (all night), continue, dwell, endure, grudge, be left, lie all night, (cause to) lodge (all night, in, -ing, this night), (make to) murmur, remain, tarry (all night, that night).', 'or לִין; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3886]', 'root', 'heb', 'לוּעַ', '["lûwaʻ"]', '["to gulp; figuratively, to be rash swallow down (up)."]', '["v"]', 'to gulp; figuratively, to be rash swallow down (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3887]', 'root', 'heb', 'לוּץ', '["lûwts"]', '["properly, to make mouths at, i.e. to scoff; hence (from the effort to pronounce a foreign language) to interpret, or (generally) intercede ambassador, have in derision, interpreter, make a mock, mocker, scorn(-er, -ful), teacher."]', '["v"]', 'properly, to make mouths at, i.e. to scoff; hence (from the effort to pronounce a foreign language) to interpret, or (generally) intercede ambassador, have in derision, interpreter, make a mock, mocker, scorn(-er, -ful), teacher.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3888]', 'root', 'heb', 'לוּשׁ', '["lûwsh"]', '["to knead knead."]', '["v"]', 'to knead knead.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3889}/[H3889]', 'lemma', 'heb', 'לוּשׁ', '["Lûwsh"]', '["Lush, a place in Palestine Laish (from the margin). Compare 3919."]', '["n-pr-loc"]', 'Lush, a place in Palestine Laish (from the margin). Compare 3919.', 'from 3888; kneading;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3890}/[H3890]', 'lemma', 'arc', 'לְוָת', '["lᵉvâth"]', '["properly, adhesion, i.e. (as preposition) with × thee."]', '["prep"]', 'properly, adhesion, i.e. (as preposition) with × thee.', '(Aramaic) from a root corresponding to 3867;');
