INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3897]', 'root', 'heb', 'לָחַךְ', '["lâchak"]', '["to lick lick (up)."]', '["v"]', 'to lick lick (up).', 'a primitive root;');
