INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H3907]', 'root', 'heb', 'לָחַשׁ', '["lâchash"]', '["to whisper; by implication, to mumble a spell (as a magician) charmer, whisper (together)."]', '["v"]', 'to whisper; by implication, to mumble a spell (as a magician) charmer, whisper (together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3908}/[H3908]', 'lemma', 'heb', 'לַחַשׁ', '["lachash"]', '["properly, a whisper, i.e. by implication, (in a good sense) a private prayer, (in a bad one) an incantation; concretely, an amulet charmed, earring, enchantment, orator, prayer."]', '["n-m"]', 'properly, a whisper, i.e. by implication, (in a good sense) a private prayer, (in a bad one) an incantation; concretely, an amulet charmed, earring, enchantment, orator, prayer.', 'from 3907;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3909}/[H3909]', 'lemma', 'heb', 'לָט', '["lâṭ"]', '["properly, covered, i.e. secret; by implication, incantation; also secrecy or (adverb) covertly enchantment, privily, secretly, softly."]', '["n-m"]', 'properly, covered, i.e. secret; by implication, incantation; also secrecy or (adverb) covertly enchantment, privily, secretly, softly.', 'a form of 3814 or else participle from 3874;');
