INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3911>', 'opaque', 'heb', 'לְטָאָה', '["lᵉṭâʼâh"]', '["a kind of lizard (from its covert habits) lizard."]', '["n-f"]', 'a kind of lizard (from its covert habits) lizard.', 'from an unused root meaning to hide;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3912}/[H3912]', 'lemma', 'heb', 'לְטוּשִׁם', '["Lᵉṭûwshim"]', '["Letushim, an Arabian tribe Letushim."]', '["n"]', 'Letushim, an Arabian tribe Letushim.', 'masculine plural of passive participle of 3913; hammered (i.e. oppressed) ones;');
