INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3956}/[H3956]', 'lemma', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge."]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
