INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4013}/[H4013]', 'lemma', 'heb', 'מִבְצָר', '["mibtsâr"]', '["a fortification, castle, or fortified city; figuratively, a defender (de-, most) fenced, fortress, (most) strong (hold)."]', '["n-m"]', 'a fortification, castle, or fortified city; figuratively, a defender (de-, most) fenced, fortress, (most) strong (hold).', 'also (in plural) feminine (Daniel 11:l5) מִבְצָרָה; from 1219;');
