INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4017}/[H4017]', 'lemma', 'heb', 'מִבְשָׂם', '["Mibsâm"]', '["Mibsam, the name of an Ishmaelite and of an Israelite Mibsam."]', '["n-pr-m"]', 'Mibsam, the name of an Ishmaelite and of an Israelite Mibsam.', 'from the same as 1314; fragrant;');
