INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4023}/[H4023]', 'lemma', 'heb', 'מְגִדּוֹן', '["Mᵉgiddôwn"]', '["Megiddon or Megiddo, a place in Palestine Megiddo, Megiddon."]', '["n-pr-loc"]', 'Megiddon or Megiddo, a place in Palestine Megiddo, Megiddon.', '(Zechariah 12) or מְגִדּוֹ; from 1413; rendezvous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4024}/[H4024]', 'lemma', 'heb', 'מִגְדּוֹל', '["Migdôwl"]', '["Migdol, a place in Egypt Migdol, tower."]', '["n-pr-m n-m"]', 'Migdol, a place in Egypt Migdol, tower.', 'or מִגְדֹּל; probably of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4025}/[H4025]', 'lemma', 'heb', 'מַגְדִּיאֵל', '["Magdîyʼêl"]', '["Magdiel, an Idumaean Magdiel."]', '["n-pr-m"]', 'Magdiel, an Idumaean Magdiel.', 'from 4022 and 410; preciousness of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4026}/[H4026]', 'lemma', 'heb', 'מִגְדָּל', '["migdâl"]', '["a tower (from its size or height); by analogy, a rostrum; figuratively, a (pyramidal) bed of flowers castle, flower, tower. Compare the names following."]', '["n-m"]', 'a tower (from its size or height); by analogy, a rostrum; figuratively, a (pyramidal) bed of flowers castle, flower, tower. Compare the names following.', 'also (in plural) feminine מִגְדָּלָה; from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4027}/[H4027]', 'lemma', 'heb', 'מִגְדַּל־אֵל', '["Migdal-ʼÊl"]', '["Migdal-El, a place in Palestine Migdal-el."]', '["n-pr-loc"]', 'Migdal-El, a place in Palestine Migdal-el.', 'from 4026 and 410; tower of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4028}/[H4028]', 'lemma', 'heb', 'מִגְדַּל־גָּד', '["Migdal-Gâd"]', '["Migdal-Gad, a place in Palestine Migdal-gad."]', '["n-pr-loc"]', 'Migdal-Gad, a place in Palestine Migdal-gad.', 'from 4026 and 1408; tower of Fortune;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4029}/[H4029]', 'lemma', 'heb', 'מִגְדַּל־עֵדֶר', '["Migdal-ʻÊder"]', '["Migdal-Eder, a place in Palestine Migdal-eder, tower of the flock."]', '["n"]', 'Migdal-Eder, a place in Palestine Migdal-eder, tower of the flock.', 'from 4026 and 5739; tower of a flock;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4030}/[H4030]', 'lemma', 'heb', 'מִגְדָּנָה', '["migdânâh"]', '["preciousness, i.e. a gem precious thing, present."]', '["n-f"]', 'preciousness, i.e. a gem precious thing, present.', 'from the same as 4022;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4031}/[H4031]', 'lemma', 'heb', 'מָגוֹג', '["Mâgôwg"]', '["Magog, a son of Japheth; also a barbarous northern region Magog."]', '["n-pr-m n-pr-loc"]', 'Magog, a son of Japheth; also a barbarous northern region Magog.', 'from 1463;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4032}/[H4032]', 'lemma', 'heb', 'מָגוֹר', '["mâgôwr"]', '["a fright (objective or subjective) fear, terror. Compare 4036."]', '["n-m"]', 'a fright (objective or subjective) fear, terror. Compare 4036.', 'or (Lamentations 2:22) מָגוּר; from 1481 in the sense of fearing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4033}/[H4033]', 'lemma', 'heb', 'מָגוּר', '["mâgûwr"]', '["a temporary abode; by extension, a permanent residence dwelling, pilgrimage, where sojourn, be a stranger. Compare 4032."]', '["n-m"]', 'a temporary abode; by extension, a permanent residence dwelling, pilgrimage, where sojourn, be a stranger. Compare 4032.', 'or מָגֻר; from 1481 in the sense of lodging;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4034}/[H4034]', 'lemma', 'heb', 'מְגוֹרַה', '["mᵉgôwrah"]', '["affright fear."]', '["n-f"]', 'affright fear.', 'feminine of 4032;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4035}/[H4035]', 'lemma', 'heb', 'מְגוּרָה', '["mᵉgûwrâh"]', '["a fright; also a granary barn, fear."]', '["n-f"]', 'a fright; also a granary barn, fear.', 'feminine of 4032 or of 4033;');
