INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4041}/[H4041]', 'lemma', 'heb', 'מְגַמָּה', '["mᵉgammâh"]', '["properly, accumulation, i.e. impulse or direction sup up."]', '["n-f"]', 'properly, accumulation, i.e. impulse or direction sup up.', 'from the same as 1571;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4042}/[H4042]', 'lemma', 'heb', 'מָגַן', '["mâgan"]', '["properly, to shield; encompass with; figuratively, to rescue, to hand safely over (i.e. surrender) deliver."]', '["v"]', 'properly, to shield; encompass with; figuratively, to rescue, to hand safely over (i.e. surrender) deliver.', 'a denominative from 4043;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4043}/[H4043]', 'lemma', 'heb', 'מָגֵן', '["mâgên"]', '["a shield (i.e. the small one or buckler); figuratively, a protector; also the scaly hide of the crocodile × armed, buckler, defence, ruler, scale, shield."]', '["n-m"]', 'a shield (i.e. the small one or buckler); figuratively, a protector; also the scaly hide of the crocodile × armed, buckler, defence, ruler, scale, shield.', 'also (in plural) feminine מְגִנָּה; from 1598;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4044}/[H4044]', 'lemma', 'heb', 'מְגִנָּה', '["mᵉginnâh"]', '["a covering (in a bad sense), i.e. blindness or obduracy sorrow. See also 4043."]', '["n-f"]', 'a covering (in a bad sense), i.e. blindness or obduracy sorrow. See also 4043.', 'from 4042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4045}/[H4045]', 'lemma', 'heb', 'מִגְעֶרֶת', '["migʻereth"]', '["reproof (i.e. curse) rebuke."]', '["n-f"]', 'reproof (i.e. curse) rebuke.', 'from 1605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4046}/[H4046]', 'lemma', 'heb', 'מַגֵּפָה', '["maggêphâh"]', '["a pestilence; by analogy, defeat (× be) plague(-d), slaughter, stroke."]', '["n-f"]', 'a pestilence; by analogy, defeat (× be) plague(-d), slaughter, stroke.', 'from 5062;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4047}/[H4047]', 'lemma', 'heb', 'מַגְפִּיעָשׁ', '["Magpîyʻâsh"]', '["Magpiash, an Israelite Magpiash."]', '["n-pr-m"]', 'Magpiash, an Israelite Magpiash.', 'apparently from 1479 or 5062 and 6211; exterminator of (the) moth;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4048]', 'root', 'heb', 'מָגַר', '["mâgar"]', '["to yield up; intensively, to precipitate cast down, terror."]', '["v"]', 'to yield up; intensively, to precipitate cast down, terror.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4049}/[H4049]', 'lemma', 'arc', 'מְגַר', '["mᵉgar"]', '["to overthrow destroy."]', '["v"]', 'to overthrow destroy.', '(Aramaic) corresponding to 4048;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4050}/[H4050]', 'lemma', 'heb', 'מְגֵרָה', '["mᵉgêrâh"]', '["a saw axe, saw."]', '["n-f"]', 'a saw axe, saw.', 'from 1641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4051}/[H4051]', 'lemma', 'heb', 'מִגְרוֹן', '["Migrôwn"]', '["Migron, a place in Palestine Migron."]', '["n-pr-loc"]', 'Migron, a place in Palestine Migron.', 'from 4048; precipice;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4052}/[H4052]', 'lemma', 'heb', 'מִגְרָעָה', '["migrâʻâh"]', '["a ledge or offset narrowed rest."]', '["n-f"]', 'a ledge or offset narrowed rest.', 'from 1639;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4053}/[H4053]', 'lemma', 'heb', 'מִגְרָפָה', '["migrâphâh"]', '["something thrown off (by the spade), i.e. a clod clod."]', '["n-f"]', 'something thrown off (by the spade), i.e. a clod clod.', 'from 1640;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4054}/[H4054]', 'lemma', 'heb', 'מִגְרָשׁ', '["migrâsh"]', '["a suburb (i.e. open country whither flocks are driven from pasture); hence, the area around a building, or the margin of the sea cast out, suburb."]', '["n-m"]', 'a suburb (i.e. open country whither flocks are driven from pasture); hence, the area around a building, or the margin of the sea cast out, suburb.', 'also (in plural) feminine (Ezekiel 27:28) מִגְרָשָׁה; from 1644;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4055}/[H4055]', 'lemma', 'heb', 'מַד', '["mad"]', '["properly, extent, i.e. height; also a measure; by implication, a vesture (as measured); also a carpet armour, clothes, garment, judgment, measure, raiment, stature."]', '["n-m"]', 'properly, extent, i.e. height; also a measure; by implication, a vesture (as measured); also a carpet armour, clothes, garment, judgment, measure, raiment, stature.', 'or מֵד; from 4058;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4056}/[H4056]', 'lemma', 'arc', 'מַדְבַּח', '["madbach"]', '["a sacrificial altar altar."]', '["n-m"]', 'a sacrificial altar altar.', '(Aramaic) from 1684;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4057}/[H4057]', 'lemma', 'heb', 'מִדְבָּר', '["midbâr"]', '["a pasture (i.e. open field, whither cattle are driven); by implication, a desert; also speech (including its organs) desert, south, speech, wilderness."]', '["n-m"]', 'a pasture (i.e. open field, whither cattle are driven); by implication, a desert; also speech (including its organs) desert, south, speech, wilderness.', 'from 1696 in the sense of driving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4058]', 'root', 'heb', 'מָדַד', '["mâdad"]', '["properly, to stretch; by implication, to measure (as if by stretching a line); figuratively, to be extended measure, mete, stretch self."]', '["v"]', 'properly, to stretch; by implication, to measure (as if by stretching a line); figuratively, to be extended measure, mete, stretch self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4059}/[H4059]', 'lemma', 'heb', 'מִדַּד', '["middad"]', '["flight be gone."]', '["v"]', 'flight be gone.', 'from 5074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4060}/[H4060]', 'lemma', 'heb', 'מִדָּה', '["middâh"]', '["properly, extension, i.e. height or breadth; also a measure (including its standard); hence a portion (as measured) or a vestment; specifically, tribute (as measured) garment, measure(-ing, meteyard, piece, size, (great) stature, tribute, wide."]', '["n-f"]', 'properly, extension, i.e. height or breadth; also a measure (including its standard); hence a portion (as measured) or a vestment; specifically, tribute (as measured) garment, measure(-ing, meteyard, piece, size, (great) stature, tribute, wide.', 'feminine of 4055;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4061}/[H4061]', 'lemma', 'arc', 'מִדָּה', '["middâh"]', '["tribute in money toll, tribute."]', '["n-f"]', 'tribute in money toll, tribute.', '(Aramaic) or מִנְדָּה; (Aramaic), corresponding to 4060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4062}/[H4062]', 'lemma', 'heb', 'מַדְהֵבָה', '["madhêbâh"]', '["goldmaking, i.e. exactness golden city."]', '["n-f"]', 'goldmaking, i.e. exactness golden city.', 'perhaps from the equivalent of 1722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4063>', 'opaque', 'heb', 'מֶדֶו', '["medev"]', '["properly, extent, i.e. measure; by implication, a dress (as measured) garment."]', '["n-m"]', 'properly, extent, i.e. measure; by implication, a dress (as measured) garment.', 'from an unused root meaning to stretch;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4064}/[H4064]', 'lemma', 'heb', 'מַדְוֶה', '["madveh"]', '["sickness disease."]', '["n-m"]', 'sickness disease.', 'from 1738;');
