INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4116]', 'root', 'heb', 'מָהַר', '["mâhar"]', '["properly, to be liquid or flow easily, i.e. (by implication); to hurry (in a good or a bad sense); often used (with another verb) adverbially, promptly be carried headlong, fearful, (cause to make, in, make) haste(-n, -ily), (be) hasty, (fetch, make ready) × quickly, rash, × shortly, (be so) × soon, make speed, × speedily, × straightway, × suddenly, swift."]', '["v"]', 'properly, to be liquid or flow easily, i.e. (by implication); to hurry (in a good or a bad sense); often used (with another verb) adverbially, promptly be carried headlong, fearful, (cause to make, in, make) haste(-n, -ily), (be) hasty, (fetch, make ready) × quickly, rash, × shortly, (be so) × soon, make speed, × speedily, × straightway, × suddenly, swift.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4117]', 'root', 'heb', 'מָהַר', '["mâhar"]', '["to bargain (for a wife), i.e. to wed endow, × surely."]', '["v"]', 'to bargain (for a wife), i.e. to wed endow, × surely.', 'a primitive root (perhaps rather the same as 4116 through the idea of readiness in assent);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4118}/[H4118]', 'lemma', 'heb', 'מַהֵר', '["mahêr"]', '["properly, hurrying; hence (adverbially) in a hurry hasteth, hastily, at once, quickly, soon, speedily, suddenly."]', '["a adv"]', 'properly, hurrying; hence (adverbially) in a hurry hasteth, hastily, at once, quickly, soon, speedily, suddenly.', 'from 4116;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4119}/[H4119]', 'lemma', 'heb', 'מֹהַר', '["môhar"]', '["a price (for a wife) dowry."]', '["n-m"]', 'a price (for a wife) dowry.', 'from 4117;');
