INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4121}/[H4121]', 'lemma', 'heb', 'מַהֲרַי', '["Mahăray"]', '["Maharai, an Israelite Maharai."]', '["n-pr-m"]', 'Maharai, an Israelite Maharai.', 'from 4116; hasty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4122}/[H4122]', 'lemma', 'heb', 'מַהֵר שָׁלָל חָשׁ בַּז', '["Mahêr Shâlâl Châsh Baz"]', '["Maher-Shalal-Chash-Baz; the symbolical name of the son of Isaiah Maher-sha-lal-bash-baz."]', '["n-pr-m"]', 'Maher-Shalal-Chash-Baz; the symbolical name of the son of Isaiah Maher-sha-lal-bash-baz.', 'from 4118 and 7998 and 2363 and 957; hasting (is he (the enemy) to the) booty, swift (to the) prey;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4123}/[H4123]', 'lemma', 'heb', 'מַהֲתַלָּה', '["mahăthallâh"]', '["a delusion deceit."]', '["n-f"]', 'a delusion deceit.', 'from 2048;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4124}/[H4124]', 'lemma', 'heb', 'מוֹאָב', '["Môwʼâb"]', '["Moab, an incestuous son of Lot; also his territory and descendants Moab."]', '["n-pr-m n-pr-loc"]', 'Moab, an incestuous son of Lot; also his territory and descendants Moab.', 'from a prolonged form of the prepositional prefix m- and 1; from (her [the mother''s]) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4125}/[H4125]', 'lemma', 'heb', 'מוֹאָבִי', '["Môwʼâbîy"]', '["a Moabite or Moabitess, i.e. a descendant from Moab (woman) of Moab, Moabite(-ish, -ss)."]', '["a"]', 'a Moabite or Moabitess, i.e. a descendant from Moab (woman) of Moab, Moabite(-ish, -ss).', 'feminine מוֹאָבִיָּה; or מוֹאָבִיתxlit Môwâbîyth corrected to Môwʼâbîyth; patronymical from 4124;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4126}/[H4126]', 'lemma', 'heb', 'מוֹבָא', '["môwbâʼ"]', '["an entrance coming."]', '["n-m"]', 'an entrance coming.', 'by transp. for 3996;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4127]', 'root', 'heb', 'מוּג', '["mûwg"]', '["to melt, i.e. literally (to soften, flow down, disappear), or figuratively (to fear, faint) consume, dissolve, (be) faint(-hearted), melt (away), make soft."]', '["v"]', 'to melt, i.e. literally (to soften, flow down, disappear), or figuratively (to fear, faint) consume, dissolve, (be) faint(-hearted), melt (away), make soft.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4128]', 'root', 'heb', 'מוּד', '["mûwd"]', '["to shake measure."]', '["v"]', 'to shake measure.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4129}/[H4129]', 'lemma', 'heb', 'מוֹדַע', '["môwdaʻ"]', '["an acquaintance kinswoman."]', '["n-m"]', 'an acquaintance kinswoman.', 'or rather מֹדָע; from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4130}/[H4130]', 'lemma', 'heb', 'מוֹדַעַת', '["môwdaʻath"]', '["acquaintance kindred."]', '["n-f"]', 'acquaintance kindred.', 'from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4131]', 'root', 'heb', 'מוֹט', '["môwṭ"]', '["to waver; by implication, to slip, shake, fall be carried, cast, be out of course, be fallen in decay, × exceedingly, fall(-ing down), be (re-) moved, be ready, shake, slide, slip."]', '["v"]', 'to waver; by implication, to slip, shake, fall be carried, cast, be out of course, be fallen in decay, × exceedingly, fall(-ing down), be (re-) moved, be ready, shake, slide, slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4132}/[H4132]', 'lemma', 'heb', 'מוֹט', '["môwṭ"]', '["a wavering, i.e. fall; by implication, a pole (as shaking); hence, a yoke (as essentially a bent pole) bar, be moved, staff, yoke."]', '["n-m"]', 'a wavering, i.e. fall; by implication, a pole (as shaking); hence, a yoke (as essentially a bent pole) bar, be moved, staff, yoke.', 'from 4131;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4133}/[H4133]', 'lemma', 'heb', 'מוֹטָה', '["môwṭâh"]', '["a pole; by implication, an ox-bow; hence, a yoke (either literal or figurative) bands, heavy, staves, yoke."]', '["n-f"]', 'a pole; by implication, an ox-bow; hence, a yoke (either literal or figurative) bands, heavy, staves, yoke.', 'feminine of 4132;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4134]', 'root', 'heb', 'מוּךְ', '["mûwk"]', '["to become thin, i.e. (figuratively) be impoverished be (waxen) poor(-er)."]', '["v"]', 'to become thin, i.e. (figuratively) be impoverished be (waxen) poor(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4135]', 'root', 'heb', 'מוּל', '["mûwl"]', '["to cut short, i.e. curtail (specifically the prepuce, i.e. to circumcise); by implication, to blunt; figuratively, to destroy circumcise(-ing), selves), cut down (in pieces), destroy, × must needs."]', '["v"]', 'to cut short, i.e. curtail (specifically the prepuce, i.e. to circumcise); by implication, to blunt; figuratively, to destroy circumcise(-ing), selves), cut down (in pieces), destroy, × must needs.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4136}/[H4136]', 'lemma', 'heb', 'מוּל', '["mûwl"]', '["properly, abrupt, i.e. a precipice; by implication, the front; used only adverbially (with prepositional prefix) opposite (over) against, before, (fore-) front, from, (God-) ward, toward, with."]', '["n-m"]', 'properly, abrupt, i.e. a precipice; by implication, the front; used only adverbially (with prepositional prefix) opposite (over) against, before, (fore-) front, from, (God-) ward, toward, with.', 'or מוֹל; (Deuteronomy 1:1), or מוֹאל; (Nehemiah 12:38), or מֻל; (Numbers 22:5), from 4135;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4137}/[H4137]', 'lemma', 'heb', 'מוֹלָדָה', '["Môwlâdâh"]', '["Moladah, a place in Palestine Moladah."]', '["n-pr-loc"]', 'Moladah, a place in Palestine Moladah.', 'from 3205; birth;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4138}/[H4138]', 'lemma', 'heb', 'מוֹלֶדֶת', '["môwledeth"]', '["nativity (plural birth-place); by implication, lineage, native country; also offspring, family begotten, born, issue, kindred, native(-ity)."]', '["n-f"]', 'nativity (plural birth-place); by implication, lineage, native country; also offspring, family begotten, born, issue, kindred, native(-ity).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4139}/[H4139]', 'lemma', 'heb', 'מוּלָה', '["mûwlâh"]', '["circumcision circumcision."]', '["n-f"]', 'circumcision circumcision.', 'from 4135;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4140}/[H4140]', 'lemma', 'heb', 'מוֹלִיד', '["Môwlîyd"]', '["Molid, an Israelite Molid."]', '["n-pr-m"]', 'Molid, an Israelite Molid.', 'from 3205; genitor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4141}/[H4141]', 'lemma', 'heb', 'מוּסָב', '["mûwçâb"]', '["a turn, i.e. circuit (of a building) winding about."]', '["n-m"]', 'a turn, i.e. circuit (of a building) winding about.', 'from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4142}/[H4142]', 'lemma', 'heb', 'מוּסַבָּה', '["mûwçabbâh"]', '["a reversal, i.e. the backside (of a gem), fold (of a double-leaved door), transmutation (of a name) being changed, inclosed, be set, turning."]', '["a-f"]', 'a reversal, i.e. the backside (of a gem), fold (of a double-leaved door), transmutation (of a name) being changed, inclosed, be set, turning.', 'or מֻסַבָּה; feminine of 4141;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4143}/[H4143]', 'lemma', 'heb', 'מוּסָד', '["mûwçâd"]', '["a foundation foundation."]', '["n-m"]', 'a foundation foundation.', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4144}/[H4144]', 'lemma', 'heb', 'מוֹסָד', '["môwçâd"]', '["a foundation foundation."]', '["n-m"]', 'a foundation foundation.', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4145}/[H4145]', 'lemma', 'heb', 'מוּסָדָה', '["mûwçâdâh"]', '["a foundation; figuratively, an appointment foundation, grounded. Compare 4328."]', '["n-f"]', 'a foundation; figuratively, an appointment foundation, grounded. Compare 4328.', 'feminine of 4143;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4146}/[H4146]', 'lemma', 'heb', 'מוֹסָדָה', '["môwçâdâh"]', '["a foundation foundation."]', '["n-f"]', 'a foundation foundation.', 'or מֹסָדָה; feminine of 4144;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4147}/[H4147]', 'lemma', 'heb', 'מוֹסֵר', '["môwçêr"]', '["properly, chastisement, i.e. (by implication) a halter; figuratively, restraint band, bond."]', '["n-m"]', 'properly, chastisement, i.e. (by implication) a halter; figuratively, restraint band, bond.', 'also (in plural) feminine מוֹסֵרָה; or מֹסְרָה; from 3256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4148}/[H4148]', 'lemma', 'heb', 'מוּסָר', '["mûwçâr"]', '["properly, chastisement; figuratively, reproof, warning or instruction; also restraint bond, chastening(-eth), chastisement, check, correction, discipline, doctrine, instruction, rebuke."]', '["n-m"]', 'properly, chastisement; figuratively, reproof, warning or instruction; also restraint bond, chastening(-eth), chastisement, check, correction, discipline, doctrine, instruction, rebuke.', 'from 3256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4149}/[H4149]', 'lemma', 'heb', 'מוֹסֵרָה', '["Môwçêrâh"]', '["Moserah, a place in the Desert Mosera."]', '["n-pr-f"]', 'Moserah, a place in the Desert Mosera.', 'or (plural) מֹסְרוֹת feminine of 4147; correction or corrections;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4150}/[H4150]', 'lemma', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed)."]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4151}/[H4151]', 'lemma', 'heb', 'מוֹעָד', '["môwʻâd"]', '["properly, an assembly figuratively, a troop appointed time."]', '["n-m"]', 'properly, an assembly figuratively, a troop appointed time.', 'from 3259; (as in 4150);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4152}/[H4152]', 'lemma', 'heb', 'מוּעָדָה', '["mûwʻâdâh"]', '["an appointed place, i.e. asylum appointed."]', '["n-f"]', 'an appointed place, i.e. asylum appointed.', 'from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4153}/[H4153]', 'lemma', 'heb', 'מוֹעַדְיָה', '["Môwʻadyâh"]', '["Moadjah, an Israelite Moadiah. Compare 4573."]', '["n-pr-m"]', 'Moadjah, an Israelite Moadiah. Compare 4573.', 'from 4151 and 3050; assembly of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4154}/[H4154]', 'lemma', 'heb', 'מוּעֶדֶת', '["mûwʻedeth"]', '["properly, made to slip, i.e. dislocated out of joint."]', '["n-f"]', 'properly, made to slip, i.e. dislocated out of joint.', 'feminine passive participle of 4571;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4155}/[H4155]', 'lemma', 'heb', 'מוּעָף', '["mûwʻâph"]', '["properly, covered, i.e. dark; abstractly, obscurity, i.e. distress dimness."]', '["n-m"]', 'properly, covered, i.e. dark; abstractly, obscurity, i.e. distress dimness.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4156}/[H4156]', 'lemma', 'heb', 'מוֹעֵצָה', '["môwʻêtsâh"]', '["a purpose counsel, device."]', '["n-f"]', 'a purpose counsel, device.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4157}/[H4157]', 'lemma', 'heb', 'מוּעָקָה', '["mûwʻâqâh"]', '["pressure, i.e. (figuratively) distress affliction."]', '["n-f"]', 'pressure, i.e. (figuratively) distress affliction.', 'from 5781;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4158}/[H4158]', 'lemma', 'heb', 'מוֹפַעַת', '["Môwphaʻath"]', '["Mophaath or Mephaath, a place in Palestine Mephaath."]', '["n-pr-loc"]', 'Mophaath or Mephaath, a place in Palestine Mephaath.', '(Jeremiah 48:21) or מֵיפַעַת; or מֵפַעַת; from 3313; illuminative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4159}/[H4159]', 'lemma', 'heb', 'מוֹפֵת', '["môwphêth"]', '["a miracle; by implication, a token or omen miracle, sign, wonder(-ed at)."]', '["n-m"]', 'a miracle; by implication, a token or omen miracle, sign, wonder(-ed at).', 'or מֹפֵת; from 3302 in the sense of conspicuousness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4160]', 'root', 'heb', 'מוּץ', '["mûwts"]', '["to press, i.e. (figuratively) to oppress extortioner."]', '["n-m"]', 'to press, i.e. (figuratively) to oppress extortioner.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4161}/[H4161]', 'lemma', 'heb', 'מוֹצָא', '["môwtsâʼ"]', '["a going forth, i.e. (the act) an egress, or (the place) an exit; hence, a source or product; specifically, dawn, the rising of the sun (the East), exportation, utterance, a gate, a fountain, a mine, a meadow (as producing grass) brought out, bud, that which came out, east, going forth, goings out, that which (thing that) is gone out, outgoing, proceeded out, spring, vein, (water-) course (springs)."]', '["n-m"]', 'a going forth, i.e. (the act) an egress, or (the place) an exit; hence, a source or product; specifically, dawn, the rising of the sun (the East), exportation, utterance, a gate, a fountain, a mine, a meadow (as producing grass) brought out, bud, that which came out, east, going forth, goings out, that which (thing that) is gone out, outgoing, proceeded out, spring, vein, (water-) course (springs).', 'or מֹצָאxlit môtsâ corrected to môtsâʼ; from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4162}/[H4162]', 'lemma', 'heb', 'מוֹצָא', '["môwtsâʼ"]', '["Motsa, the name of two Israelites Moza."]', '["n-pr-m"]', 'Motsa, the name of two Israelites Moza.', 'the same as 4161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4163}/[H4163]', 'lemma', 'heb', 'מוֹצָאָה', '["môwtsâʼâh"]', '["a family descent; also a sewer draught house; going forth."]', '["n-f"]', 'a family descent; also a sewer draught house; going forth.', 'feminine of 4161; (marg.; compare 6675)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4164}/[H4164]', 'lemma', 'heb', 'מוּצַק', '["mûwtsaq"]', '["narrowness; figuratively, distress anguish, is straitened, straitness."]', '["n-m"]', 'narrowness; figuratively, distress anguish, is straitened, straitness.', 'or מוּצָק; from 3332;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4165}/[H4165]', 'lemma', 'heb', 'מוּצָק', '["mûwtsâq"]', '["properly, fusion, i.e. literally, a casting (of metal); figuratively, a mass (of clay) casting, hardness."]', '["n-m"]', 'properly, fusion, i.e. literally, a casting (of metal); figuratively, a mass (of clay) casting, hardness.', 'from 5694;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4166}/[H4166]', 'lemma', 'heb', 'מוּצָקָה', '["mûwtsâqâh"]', '["properly, something poured out, i.e. a casting (of metal); by implication, a tube (as cast) when it was cast, pipe."]', '["n-f"]', 'properly, something poured out, i.e. a casting (of metal); by implication, a tube (as cast) when it was cast, pipe.', 'or מֻצָקָה; from 3332;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4167]', 'root', 'heb', 'מוּק', '["mûwq"]', '["to jeer, i.e. (intens.) blaspheme be corrupt."]', '["v"]', 'to jeer, i.e. (intens.) blaspheme be corrupt.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4168}/[H4168]', 'lemma', 'heb', 'מוֹקֵד', '["môwqêd"]', '["a fire or fuel; abstractly, a conflagration burning, hearth."]', '["n-m"]', 'a fire or fuel; abstractly, a conflagration burning, hearth.', 'from 3344;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4169}/[H4169]', 'lemma', 'heb', 'מוֹקְדָה', '["môwqᵉdâh"]', '["fuel burning."]', '["n-f"]', 'fuel burning.', 'feminine of 4168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4170}/[H4170]', 'lemma', 'heb', 'מוֹקֵשׁ', '["môwqêsh"]', '["a noose (for catching animals) (literally or figuratively); by implication, a hook (for the nose) be ensnared, gin, (is) snare(-d), trap."]', '["n-m"]', 'a noose (for catching animals) (literally or figuratively); by implication, a hook (for the nose) be ensnared, gin, (is) snare(-d), trap.', 'or מֹקֵשׁ; from 3369;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4171]', 'root', 'heb', 'מוּר', '["mûwr"]', '["to alter; by implication, to barter, to dispose of × at all, (ex-) change, remove."]', '["v"]', 'to alter; by implication, to barter, to dispose of × at all, (ex-) change, remove.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4172}/[H4172]', 'lemma', 'heb', 'מוֹרָא', '["môwrâʼ"]', '["fear; by implication, a fearful thing or deed dread, (that ought to be) fear(-ed), terribleness, terror."]', '["n-m"]', 'fear; by implication, a fearful thing or deed dread, (that ought to be) fear(-ed), terribleness, terror.', 'or מֹרָא; or מוֹרָהxlit môrâh corrected to môwrâh; (Psalm 9:20), from 3372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4173>', 'opaque', 'heb', 'מוֹרַג', '["môwrag"]', '["a threshing sledge threshing instrument."]', '["n-m"]', 'a threshing sledge threshing instrument.', 'or מֹרַג; from an unused root meaning to triturate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4174}/[H4174]', 'lemma', 'heb', 'מוֹרָד', '["môwrâd"]', '["a descent; as architecture, an ornamental appendage, perhaps a festoon going down, steep place, thin work."]', '["n-m"]', 'a descent; as architecture, an ornamental appendage, perhaps a festoon going down, steep place, thin work.', 'from 3381;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4175}/[H4175]', 'lemma', 'heb', 'מוֹרֶה', '["môwreh"]', '["an archer; also teacher or teaching; also the early rain (early) rain."]', '["n-m"]', 'an archer; also teacher or teaching; also the early rain (early) rain.', 'from 3384; (see 3138)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4176}/[H4176]', 'lemma', 'heb', 'מוֹרֶה', '["Môwreh"]', '["Moreh, a Canaanite; also a hill (perhaps named from him) Moreh."]', '["n-m"]', 'Moreh, a Canaanite; also a hill (perhaps named from him) Moreh.', 'or מֹרֶה; the same as 4175;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4177}/[H4177]', 'lemma', 'heb', 'מוֹרָה', '["môwrâh"]', '["a razor razor."]', '["n-m"]', 'a razor razor.', 'from 4171 in the sense of shearing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4178}/[H4178]', 'lemma', 'heb', 'מוֹרָט', '["môwrâṭ"]', '["obstinate, i.e. independent peeled."]', '["v"]', 'obstinate, i.e. independent peeled.', 'from 3399;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4179}/[H4179]', 'lemma', 'heb', 'מוֹרִיָּה', '["Môwrîyâh"]', '["Morijah, a hill in Palestine Moriah."]', '["n-pr-loc"]', 'Morijah, a hill in Palestine Moriah.', 'or מֹרִיָּה; from 7200 and 3050; seen of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4180}/[H4180]', 'lemma', 'heb', 'מוֹרָשׁ', '["môwrâsh"]', '["a possession; figuratively, delight possession, thought."]', '["n-m"]', 'a possession; figuratively, delight possession, thought.', 'from 3423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4181}/[H4181]', 'lemma', 'heb', 'מוֹרָשָׁה', '["môwrâshâh"]', '["a possession heritage, inheritance, possession."]', '["n-f"]', 'a possession heritage, inheritance, possession.', 'feminine of 4180;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4182}/[H4182]', 'lemma', 'heb', 'מוֹרֶשֶׁת גַּת', '["Môwresheth Gath"]', '["Moresheth-Gath, a place in Palestine Moresheth-gath."]', '["n-pr-loc"]', 'Moresheth-Gath, a place in Palestine Moresheth-gath.', 'from 3423 and 1661; possession of Gath;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4183}/[H4183]', 'lemma', 'heb', 'מוֹרַשְׁתִּי', '["Môwrashtîy"]', '["a Morashtite or inhabitant of Moresheth-Gath Morashthite."]', '["a"]', 'a Morashtite or inhabitant of Moresheth-Gath Morashthite.', 'patrial from 4182;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4184]', 'root', 'heb', 'מוּשׁ', '["mûwsh"]', '["to touch feel, handle."]', '["v"]', 'to touch feel, handle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4185]', 'root', 'heb', 'מוּשׁ', '["mûwsh"]', '["to withdraw (both literally and figuratively, whether intransitive or transitive) cease, depart, go back, remove, take away."]', '["v"]', 'to withdraw (both literally and figuratively, whether intransitive or transitive) cease, depart, go back, remove, take away.', 'a primitive root (perhaps rather the same as 4184 through the idea of receding by contact);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4186}/[H4186]', 'lemma', 'heb', 'מוֹשָׁב', '["môwshâb"]', '["a seat; figuratively, a site; abstractly, a session; by extension an abode (the place or the time); by implication, population assembly, dwell in, dwelling(-place), wherein (that) dwelt (in), inhabited place, seat, sitting, situation, sojourning."]', '["n-m"]', 'a seat; figuratively, a site; abstractly, a session; by extension an abode (the place or the time); by implication, population assembly, dwell in, dwelling(-place), wherein (that) dwelt (in), inhabited place, seat, sitting, situation, sojourning.', 'or מֹשָׁב; from 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4187}/[H4187]', 'lemma', 'heb', 'מוּשִׁי', '["Mûwshîy"]', '["Mushi, a Levite Mushi."]', '["n-pr-m"]', 'Mushi, a Levite Mushi.', 'or מֻשִּׁי; from 4184; sensitive;');
