INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4189}/[H4189]', 'lemma', 'heb', 'מוֹשְׁכָה', '["môwshᵉkâh"]', '["something drawing, i.e. (figuratively) a cord band."]', '["n-f"]', 'something drawing, i.e. (figuratively) a cord band.', 'act participle feminine of 4900;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4190}/[H4190]', 'lemma', 'heb', 'מוֹשָׁעָה', '["môwshâʻâh"]', '["deliverance salvation."]', '["n-f"]', 'deliverance salvation.', 'from 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4191]', 'root', 'heb', 'מוּת', '["mûwth"]', '["to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise."]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4192}/[H4192]', 'lemma', 'heb', 'מוּת', '["Mûwth"]', '["''To die for the son'', probably the title of a popular song death, Muthlabben."]', '["n-m"]', '''To die for the son'', probably the title of a popular song death, Muthlabben.', '(Psalm 48:14) or מוּת לַבֵּן; from 4191 and 1121 with the preposition and article interposed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4193}/[H4193]', 'lemma', 'arc', 'מוֹת', '["môwth"]', '["death death."]', '["n-m"]', 'death death.', '(Aramaic) corresponding to 4194;');
