INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4195}/[H4195]', 'lemma', 'heb', 'מוֹתָר', '["môwthâr"]', '["literally gain; figuratively, superiority plenteousness, preeminence, profit."]', '["n-m"]', 'literally gain; figuratively, superiority plenteousness, preeminence, profit.', 'from 3498;');
