INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4201}/[H4201]', 'lemma', 'heb', 'מְזוּזָה', '["mᵉzûwzâh"]', '["a door-post (as prominent) (door, side) post."]', '["n-f"]', 'a door-post (as prominent) (door, side) post.', 'or מְזֻזָה; from the same as 2123;');
