INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4280}/[H4280]', 'lemma', 'heb', 'מַחֲרָאָה', '["machărâʼâh"]', '["a sink draught house."]', '["n-f"]', 'a sink draught house.', 'from the same as 2716;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4281}/[H4281]', 'lemma', 'heb', 'מַחֲרֵשָׁה', '["machărêshâh"]', '["probably a pick-axe mattock."]', '["n-f"]', 'probably a pick-axe mattock.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4282}/[H4282]', 'lemma', 'heb', 'מַחֲרֶשֶׁת', '["machăresheth"]', '["probably a hoe share."]', '["n-f"]', 'probably a hoe share.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4283}/[H4283]', 'lemma', 'heb', 'מׇחֳרָת', '["mochŏrâth"]', '["the morrow or (adverbially) tomorrow morrow, next day."]', '["n-f"]', 'the morrow or (adverbially) tomorrow morrow, next day.', 'or מׇחֳרָתָם; (1 Samuel 30:17), feminine from the same as 4279;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4284}/[H4284]', 'lemma', 'heb', 'מַחֲשָׁבָה', '["machăshâbâh"]', '["a contrivance, i.e. (concretely) a texture, machine, or (abstractly) intention, plan (whether bad, a plot; or good, advice) cunning (work), curious work, device(-sed), imagination, invented, means, purpose, thought."]', '["n-f"]', 'a contrivance, i.e. (concretely) a texture, machine, or (abstractly) intention, plan (whether bad, a plot; or good, advice) cunning (work), curious work, device(-sed), imagination, invented, means, purpose, thought.', 'or מַחֲשֶׁבֶת; from 2803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4285}/[H4285]', 'lemma', 'heb', 'מַחְשָׁךְ', '["machshâk"]', '["darkness; concretely, a dark place dark(-ness, place)."]', '["n-m"]', 'darkness; concretely, a dark place dark(-ness, place).', 'from 2821;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4286}/[H4286]', 'lemma', 'heb', 'מַחְשֹׂף', '["machsôph"]', '["a peeling made appear."]', '["n-m"]', 'a peeling made appear.', 'from 2834;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4287}/[H4287]', 'lemma', 'heb', 'מַחַת', '["Machath"]', '["Machath, the name of two Israelites Mahath."]', '["n-pr-m"]', 'Machath, the name of two Israelites Mahath.', 'probably from 4229; erasure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4288}/[H4288]', 'lemma', 'heb', 'מְחִתָּה', '["mᵉchittâh"]', '["properly, a dissolution; concretely, a ruin, or (abstractly) consternation destruction, dismaying, ruin, terror."]', '["n-f"]', 'properly, a dissolution; concretely, a ruin, or (abstractly) consternation destruction, dismaying, ruin, terror.', 'from 2846;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4289}/[H4289]', 'lemma', 'heb', 'מַחְתָּה', '["machtâh"]', '["a pan for live coals censer, firepan, snuffdish."]', '["n-f"]', 'a pan for live coals censer, firepan, snuffdish.', 'the same as 4288 in the sense of removal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4290}/[H4290]', 'lemma', 'heb', 'מַחְתֶּרֶת', '["machtereth"]', '["a burglary; figuratively, unexpected examination breaking up, secret search."]', '["n-m"]', 'a burglary; figuratively, unexpected examination breaking up, secret search.', 'from 2864;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4291}/[H4291]', 'lemma', 'arc', 'מְטָא', '["mᵉṭâʼ"]', '["to arrive, extend or happen come, reach."]', '["v"]', 'to arrive, extend or happen come, reach.', '(Aramaic) or מְטָה; (Aramaic), apparently corresponding to 4672 in the intransitive sense of being found present;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4292}/[H4292]', 'lemma', 'heb', 'מַטְאֲטֵא', '["maṭʼăṭêʼ"]', '["a broom (as removing dirt (compare English ''to dust'', i.e. remove dust)) besom."]', '["n-m"]', 'a broom (as removing dirt (compare English ''to dust'', i.e. remove dust)) besom.', 'apparently a denominative from 2916;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4293}/[H4293]', 'lemma', 'heb', 'מַטְבֵּחַ', '["maṭbêach"]', '["slaughter slaughter."]', '["n-m"]', 'slaughter slaughter.', 'from 2873;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4294}/[H4294]', 'lemma', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe."]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4295}/[H4295]', 'lemma', 'heb', 'מַטָּה', '["maṭṭâh"]', '["downward, below or beneath; often adverbially with or without prefixes beneath, down(-ward), less, very low, under(-neath)."]', '["adv"]', 'downward, below or beneath; often adverbially with or without prefixes beneath, down(-ward), less, very low, under(-neath).', 'from 5786 with directive enclitic appended;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4296}/[H4296]', 'lemma', 'heb', 'מִטָּה', '["miṭṭâh"]', '["a bed (as extended) for sleeping or eating; by analogy, a sofa, litter or bier bed(-chamber), bier."]', '["n-f"]', 'a bed (as extended) for sleeping or eating; by analogy, a sofa, litter or bier bed(-chamber), bier.', 'from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4297}/[H4297]', 'lemma', 'heb', 'מֻטֶּה', '["muṭṭeh"]', '["a stretching, i.e. distortion (figuratively, iniquity) perverseness."]', '["n-m"]', 'a stretching, i.e. distortion (figuratively, iniquity) perverseness.', 'from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4298}/[H4298]', 'lemma', 'heb', 'מֻטָּה', '["muṭṭâh"]', '["expansion stretching out."]', '["n-f"]', 'expansion stretching out.', 'from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4299}/[H4299]', 'lemma', 'heb', 'מַטְוֶה', '["maṭveh"]', '["something spun spun."]', '["n-m"]', 'something spun spun.', 'from 2901;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4300}/[H4300]', 'lemma', 'heb', 'מְטִיל', '["mᵉṭîyl"]', '["an iron bar (as forged) bar."]', '["n-m"]', 'an iron bar (as forged) bar.', 'from 2904 in the sense of hammering out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4301}/[H4301]', 'lemma', 'heb', 'מַטְמוֹן', '["maṭmôwn"]', '["a secret storehouse; hence, a secreted valuable (buried); generally money hidden riches, (hid) treasure(-s)."]', '["n-m"]', 'a secret storehouse; hence, a secreted valuable (buried); generally money hidden riches, (hid) treasure(-s).', 'or מַטְמֹן; or מַטְמֻן; from 2934;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4302}/[H4302]', 'lemma', 'heb', 'מַטָּע', '["maṭṭâʻ"]', '["something planted, i.e. the place (a garden or vineyard), or the thing (a plant, figuratively or men); by implication, the act, planting plant(-ation, -ing)."]', '["n-m"]', 'something planted, i.e. the place (a garden or vineyard), or the thing (a plant, figuratively or men); by implication, the act, planting plant(-ation, -ing).', 'from 5193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4303}/[H4303]', 'lemma', 'heb', 'מַטְעַם', '["maṭʻam"]', '["a delicacy dainty (meat), savoury meat."]', '["n-m"]', 'a delicacy dainty (meat), savoury meat.', 'or (feminine) מַטְעַמָּה; from 2938;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4304}/[H4304]', 'lemma', 'heb', 'מִטְפַּחַת', '["miṭpachath"]', '["a wide cloak (for a woman) vail, wimple."]', '["n-f"]', 'a wide cloak (for a woman) vail, wimple.', 'from 2946;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4305]', 'root', 'heb', 'מָטַר', '["mâṭar"]', '["to rain (cause to) rain (upon)."]', '["v"]', 'to rain (cause to) rain (upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4306}/[H4306]', 'lemma', 'heb', 'מָטַר', '["mâṭar"]', '["rain rain."]', '["n-m"]', 'rain rain.', 'from 4305;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4307}/[H4307]', 'lemma', 'heb', 'מַטָּרָא', '["maṭṭârâʼ"]', '["a jail (as a guard-house); also an aim (as being closely watched) mark, prison."]', '["n-f"]', 'a jail (as a guard-house); also an aim (as being closely watched) mark, prison.', 'or מַטָּרָה; from 5201;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4308}/[H4308]', 'lemma', 'heb', 'מַטְרֵד', '["Maṭrêd"]', '["Matred, an Edomitess Matred."]', '["n-pr-f"]', 'Matred, an Edomitess Matred.', 'from 2956; propulsive;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4309}/[H4309]', 'lemma', 'heb', 'מַטְרִי', '["Maṭrîy"]', '["Matri, an Israelite Matri."]', '["a"]', 'Matri, an Israelite Matri.', 'from 4305; rainy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4310}/[H4310]', 'lemma', 'heb', 'מִי', '["mîy"]', '["who? (occasionally, by a peculiar idiom, of things); also (indefinitely) whoever; often used in oblique construction with prefix or suffix any (man), × he, × him, O that! what, which, who(-m, -se, -soever), would to God."]', '["i"]', 'who? (occasionally, by a peculiar idiom, of things); also (indefinitely) whoever; often used in oblique construction with prefix or suffix any (man), × he, × him, O that! what, which, who(-m, -se, -soever), would to God.', 'an interrogative pronoun of persons, as 4100 is of things,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4311}/[H4311]', 'lemma', 'heb', 'מֵידְבָא', '["Mêydᵉbâʼ"]', '["Medeba, a place in Palestine Medeba."]', '["n-pr-loc"]', 'Medeba, a place in Palestine Medeba.', 'from 4325 and 1679; water of quiet;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4312}/[H4312]', 'lemma', 'heb', 'מֵידָד', '["Mêydâd"]', '["Medad, an Israelite Medad."]', '["n-pr-m"]', 'Medad, an Israelite Medad.', 'from 3032 in the sense of loving; affectionate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4313}/[H4313]', 'lemma', 'heb', 'מֵי הַיַּרְקוֹן', '["Mêy hay-Yarqôwn"]', '["Me-haj-Jarkon, a place in Palestine Me-jarkon."]', '["n-pr-loc"]', 'Me-haj-Jarkon, a place in Palestine Me-jarkon.', 'from 4325 and 3420 with the art. interposed; water of the yellowness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4314}/[H4314]', 'lemma', 'heb', 'מֵי זָהָב', '["Mêy Zâhâb"]', '["Me-Zahab, an Edomite Mezahab."]', '["n-pr-m"]', 'Me-Zahab, an Edomite Mezahab.', 'from 4325 and 2091, water of gold;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4315}/[H4315]', 'lemma', 'heb', 'מֵיטָב', '["mêyṭâb"]', '["the best part best."]', '["n-m"]', 'the best part best.', 'from 3190;');
