INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4317}/[H4317]', 'lemma', 'heb', 'מִיכָאֵל', '["Mîykâʼêl"]', '["Mikael, the name of an archangel and of nine Israelites Michael."]', '["n-pr-m"]', 'Mikael, the name of an archangel and of nine Israelites Michael.', 'from 4310 and (the prefix derivative from) 3588 and 410; who (is) like God?;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4318}/[H4318]', 'lemma', 'heb', 'מִיכָה', '["Mîykâh"]', '["Micah, the name of seven Israelites Micah, Micaiah, Michah."]', '["n-pr-m"]', 'Micah, the name of seven Israelites Micah, Micaiah, Michah.', 'an abbreviated form of 4320;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4319}/[H4319]', 'lemma', 'heb', 'מִיכָהוּ', '["Mîykâhûw"]', '["Mikehu, an Israelite prophet Micaiah (2 Chronicles 18:8)."]', '["n-pr-m"]', 'Mikehu, an Israelite prophet Micaiah (2 Chronicles 18:8).', 'a contr. for 4321;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4320}/[H4320]', 'lemma', 'heb', 'מִיכָיָה', '["Mîykâyâh"]', '["Micajah, the name of two Israelites Micah, Michaiah. Compare 4318."]', '["n-pr-m"]', 'Micajah, the name of two Israelites Micah, Michaiah. Compare 4318.', 'from 4310 and (the prefix derivative from) 3588 and 3050; who (is) like Jah?;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4321}/[H4321]', 'lemma', 'heb', 'מִיכָיְהוּ', '["Mîykâyᵉhûw"]', '["Mikajah, the name of three Israelites Micah, Micaiah, Michaiah."]', '["n-pr-m"]', 'Mikajah, the name of three Israelites Micah, Micaiah, Michaiah.', 'or מִכָיְהוּ; (Jeremiah 36:11), abbreviated form for 4322;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4322}/[H4322]', 'lemma', 'heb', 'מִיכָיָהוּ', '["Mîykâyâhûw"]', '["Mikajah, the name of an Israelite and an Israelitess Michaiah."]', '["n-pr-m"]', 'Mikajah, the name of an Israelite and an Israelitess Michaiah.', 'for 4320;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4323}/[H4323]', 'lemma', 'heb', 'מִיכָל', '["mîykâl"]', '["properly, a container, i.e. a streamlet brook."]', '["n-m"]', 'properly, a container, i.e. a streamlet brook.', 'from 3201;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4324}/[H4324]', 'lemma', 'heb', 'מִיכָל', '["Mîykâl"]', '["Mikal, Saul''s daughter Michal."]', '["n-pr-f"]', 'Mikal, Saul''s daughter Michal.', 'apparently the same as 4323; revulet;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4325}/[H4325]', 'lemma', 'heb', 'מַיִם', '["mayim"]', '["water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring))."]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4326}/[H4326]', 'lemma', 'heb', 'מִיָּמִן', '["Mîyâmin"]', '["Mijamin, the name of three Israelites Miamin, Mijamin."]', '["n-pr-m"]', 'Mijamin, the name of three Israelites Miamin, Mijamin.', 'a form for 4509;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4327>', 'opaque', 'heb', 'מִין', '["mîyn"]', '["a sort, i.e. species kind. Compare 4480."]', '["n-m"]', 'a sort, i.e. species kind. Compare 4480.', 'from an unused root meaning to portion out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4328}/[H4328]', 'lemma', 'heb', 'מְיֻסָּדָה', '["mᵉyuççâdâh"]', '["something founded, i.e. a foundation foundation."]', '["n-f"]', 'something founded, i.e. a foundation foundation.', 'properly, feminine passive participle of 3245;');
