INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4332}/[H4332]', 'lemma', 'heb', 'מִישָׁאֵל', '["Mîyshâʼêl"]', '["Mishael, the name of three Israelites Mishael."]', '["n-pr-m"]', 'Mishael, the name of three Israelites Mishael.', 'from 4310 and 410 with the abbreviated form insep. relatively (see 834) interposed; who (is) what God (is) ?;');
