INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4334}/[H4334]', 'lemma', 'heb', 'מִישׁוֹר', '["mîyshôwr"]', '["a level, i.e. a plain (often used (with the article prefix) as a proper name of certain districts); figuratively, concord; also straightness, i.e. (figuratively) justice (sometimes adverbially, justly) equity, even place, plain, right(-eously), (made) straight, uprightness."]', '["n-m"]', 'a level, i.e. a plain (often used (with the article prefix) as a proper name of certain districts); figuratively, concord; also straightness, i.e. (figuratively) justice (sometimes adverbially, justly) equity, even place, plain, right(-eously), (made) straight, uprightness.', 'or מִישֹׁר; from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4335}/[H4335]', 'lemma', 'heb', 'מֵישַׁךְ', '["Mêyshak"]', '["Meshak, an Israelite Meshak."]', '["n-pr-m"]', 'Meshak, an Israelite Meshak.', 'borrowed from 4336;');
