INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4339}/[H4339]', 'lemma', 'heb', 'מֵישָׁר', '["mêyshâr"]', '["evenness, i.e. (figuratively) prosperity or concord; also straightness, i.e. (figuratively) rectitude (only in plural with singular sense; often adverbially) agreement, aright, that are equal, equity, (things that are) right(-eously, things), sweetly, upright(-ly, -ness)."]', '["n-m"]', 'evenness, i.e. (figuratively) prosperity or concord; also straightness, i.e. (figuratively) rectitude (only in plural with singular sense; often adverbially) agreement, aright, that are equal, equity, (things that are) right(-eously, things), sweetly, upright(-ly, -ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4340}/[H4340]', 'lemma', 'heb', 'מֵיתָר', '["mêythâr"]', '["a cord (of a tent); or the string (of a bow) cord, string."]', '["n-m"]', 'a cord (of a tent); or the string (of a bow) cord, string.', 'from 3498; (compare 3499)');
