INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4383}/[H4383]', 'lemma', 'heb', 'מִכְשׁוֹל', '["mikshôwl"]', '["a stumbling-block, literally or figuratively (obstacle, enticement (specifically an idol), scruple) caused to fall, offence, × (no-) thing offered, ruin, stumbling-block."]', '["n-m"]', 'a stumbling-block, literally or figuratively (obstacle, enticement (specifically an idol), scruple) caused to fall, offence, × (no-) thing offered, ruin, stumbling-block.', 'or מִכְשֹׁל; masculine from 3782;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4384}/[H4384]', 'lemma', 'heb', 'מַכְשֵׁלָה', '["makshêlâh"]', '["a stumbling-block, but only figuratively (fall, enticement [idol]) ruin, stumbling-block."]', '["n-f"]', 'a stumbling-block, but only figuratively (fall, enticement [idol]) ruin, stumbling-block.', 'feminine from 3782;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4385}/[H4385]', 'lemma', 'heb', 'מִכְתָּב', '["miktâb"]', '["a thing written, the characters, or a document (letter, copy, edict, poem) writing."]', '["n-m"]', 'a thing written, the characters, or a document (letter, copy, edict, poem) writing.', 'from 3789;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4386}/[H4386]', 'lemma', 'heb', 'מְכִתָּה', '["mᵉkittâh"]', '["a fracture bursting."]', '["n-m"]', 'a fracture bursting.', 'from 3807;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4387}/[H4387]', 'lemma', 'heb', 'מִכְתָּם', '["miktâm"]', '["an engraving, i.e. (techn.) a poem Michtam."]', '["n-m"]', 'an engraving, i.e. (techn.) a poem Michtam.', 'from 3799;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4388}/[H4388]', 'lemma', 'heb', 'מַכְתֵּשׁ', '["maktêsh"]', '["a mortar; by analogy, a socket (of a tooth) hollow place, mortar."]', '["n-m"]', 'a mortar; by analogy, a socket (of a tooth) hollow place, mortar.', 'from 3806;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4389}/[H4389]', 'lemma', 'heb', 'מַכְתֵּשׁ', '["Maktêsh"]', '["dell; the Maktesh, a place in Jerusalem Maktesh."]', '["n-m"]', 'dell; the Maktesh, a place in Jerusalem Maktesh.', 'the same as 4388;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4390]', 'root', 'heb', 'מָלֵא', '["mâlêʼ"]', '["to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly."]', '["v"]', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly.', 'or מָלָא; (Esther 7:5), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4391}/[H4391]', 'lemma', 'arc', 'מְלָא', '["mᵉlâʼ"]', '["to fill fill, be full."]', '["v"]', 'to fill fill, be full.', '(Aramaic) corresponding to 4390;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4392}/[H4392]', 'lemma', 'heb', 'מָלֵא', '["mâlêʼ"]', '["full (literally or figuratively) or filling (literally); also (concretely) fulness; adverbially, fully × she that was with child, fill(-ed, -ed with), full(-ly), multitude, as is worth."]', '["a"]', 'full (literally or figuratively) or filling (literally); also (concretely) fulness; adverbially, fully × she that was with child, fill(-ed, -ed with), full(-ly), multitude, as is worth.', 'from 4390;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4393}/[H4393]', 'lemma', 'heb', 'מְלֹא', '["mᵉlôʼ"]', '["fulness (literally or figuratively) × all along, × all that is (there-) in, fill, (× that whereof...was) full, fulness, (hand-) full, multitude."]', '["n-m"]', 'fulness (literally or figuratively) × all along, × all that is (there-) in, fill, (× that whereof...was) full, fulness, (hand-) full, multitude.', 'rarely מְלוֹא; or מְלוֹ; (Ezekiel 41:8), from 4390;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4394}/[H4394]', 'lemma', 'heb', 'מִלֻּא', '["milluʼ"]', '["a fulfilling (only in plural), i.e. (literally) a setting (of gems), or (technically) consecration (also concretely, a dedicatory sacrifice) consecration, be set."]', '["n-m"]', 'a fulfilling (only in plural), i.e. (literally) a setting (of gems), or (technically) consecration (also concretely, a dedicatory sacrifice) consecration, be set.', 'from 4390;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4395}/[H4395]', 'lemma', 'heb', 'מְלֵאָה', '["mᵉlêʼâh"]', '["something fulfilled, i.e. abundance (of produce) (first of ripe) fruit, fulness."]', '["n-f"]', 'something fulfilled, i.e. abundance (of produce) (first of ripe) fruit, fulness.', 'feminine of 4392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4396}/[H4396]', 'lemma', 'heb', 'מִלֻּאָה', '["milluʼâh"]', '["a filling, i.e. setting (of gems) enclosing, setting."]', '["n-f"]', 'a filling, i.e. setting (of gems) enclosing, setting.', 'feminine of 4394;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4397>', 'opaque', 'heb', 'מַלְאָךְ', '["malʼâk"]', '["a messenger; specifically, of God, i.e. an angel (also a prophet, priest or teacher) ambassador, angel, king, messenger."]', '["n-m"]', 'a messenger; specifically, of God, i.e. an angel (also a prophet, priest or teacher) ambassador, angel, king, messenger.', 'from an unused root meaning to despatch as a deputy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4398}/[H4398]', 'lemma', 'arc', 'מַלְאַךְ', '["malʼak"]', '["an angel angel."]', '["n-m"]', 'an angel angel.', '(Aramaic) corresponding to 4397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4399}/[H4399]', 'lemma', 'heb', 'מְלָאכָה', '["mᵉlâʼkâh"]', '["properly, deputyship, i.e. ministry; generally, employment (never servile) or work (abstractly or concretely); also property (as the result of labor) business, cattle, industrious, occupation, ( -pied), officer, thing (made), use, (manner of) work((-man), -manship)."]', '["n-f"]', 'properly, deputyship, i.e. ministry; generally, employment (never servile) or work (abstractly or concretely); also property (as the result of labor) business, cattle, industrious, occupation, ( -pied), officer, thing (made), use, (manner of) work((-man), -manship).', 'from the same as 4397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4400}/[H4400]', 'lemma', 'heb', 'מַלְאֲכוּת', '["malʼăkûwth"]', '["a message message."]', '["n-f"]', 'a message message.', 'from the same as 4397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4401}/[H4401]', 'lemma', 'heb', 'מַלְאָכִי', '["Malʼâkîy"]', '["Malaki, a prophet Malachi."]', '["n-pr-m"]', 'Malaki, a prophet Malachi.', 'from the same as 4397; ministrative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4402}/[H4402]', 'lemma', 'heb', 'מִלֵּאת', '["millêʼth"]', '["fulness, i.e. (concretely) a plump socket (of the eye) × fitly."]', '["n-f"]', 'fulness, i.e. (concretely) a plump socket (of the eye) × fitly.', 'from 4390;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4403}/[H4403]', 'lemma', 'heb', 'מַלְבּוּשׁ', '["malbûwsh"]', '["a garment, or (collectively) clothing apparel, raiment, vestment."]', '["n-m"]', 'a garment, or (collectively) clothing apparel, raiment, vestment.', 'or מַלְבֻּשׁ; from 3847;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4404}/[H4404]', 'lemma', 'heb', 'מַלְבֵּן', '["malbên"]', '["a brickkiln brickkiln."]', '["n-m"]', 'a brickkiln brickkiln.', 'from 3835 (denominative);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4405}/[H4405]', 'lemma', 'heb', 'מִלָּה', '["millâh"]', '["a word; collectively, a discourse; figuratively, a topic answer, by-word, matter, any thing (what) to say, to speak(-ing), speak, talking, word."]', '["n-f"]', 'a word; collectively, a discourse; figuratively, a topic answer, by-word, matter, any thing (what) to say, to speak(-ing), speak, talking, word.', 'from 4448 (plural masculine as if from מִלֶּה;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4406}/[H4406]', 'lemma', 'arc', 'מִלָּה', '["millâh"]', '["a word, command, discourse, or subject commandment, matter, thing. word."]', '["n-f"]', 'a word, command, discourse, or subject commandment, matter, thing. word.', '(Aramaic) corresponding to 4405;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4407}/[H4407]', 'lemma', 'heb', 'מִלּוֹא', '["millôwʼ"]', '["a rampart (as filled in), i.e. the citadel Millo. See also 1037."]', '["n-pr-m"]', 'a rampart (as filled in), i.e. the citadel Millo. See also 1037.', 'or מִלֹּא; (2 Kings 12:20), from 4390;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4408}/[H4408]', 'lemma', 'heb', 'מַלּוּחַ', '["mallûwach"]', '["sea-purslain (from its saltness) mallows."]', '["n-m"]', 'sea-purslain (from its saltness) mallows.', 'from 4414;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4409}/[H4409]', 'lemma', 'heb', 'מַלּוּךְ', '["Mallûwk"]', '["Malluk, the name of five Israelites Malluch, Melichu (from the margin)."]', '["n-pr-m"]', 'Malluk, the name of five Israelites Malluch, Melichu (from the margin).', 'or מַלּוּכִי; (Nehemiah 12:14), from 4427; regnant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4410}/[H4410]', 'lemma', 'heb', 'מְלוּכָה', '["mᵉlûwkâh"]', '["something ruled, i.e. a realm kingsom, king''s, × royal."]', '["n-f"]', 'something ruled, i.e. a realm kingsom, king''s, × royal.', 'feminine passive participle of 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4411}/[H4411]', 'lemma', 'heb', 'מָלוֹן', '["mâlôwn"]', '["a lodgment, i.e. caravanserai or encampment inn, place where...lodge, lodging (place)."]', '["n-m"]', 'a lodgment, i.e. caravanserai or encampment inn, place where...lodge, lodging (place).', 'from 3885;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4412}/[H4412]', 'lemma', 'heb', 'מְלוּנָה', '["mᵉlûwnâh"]', '["a hut, a hammock cottage, lodge."]', '["n-f"]', 'a hut, a hammock cottage, lodge.', 'feminine from 3885;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4413}/[H4413]', 'lemma', 'heb', 'מַלּוֹתִי', '["Mallôwthîy"]', '["Mallothi, an Israelite Mallothi."]', '["n-pr-m"]', 'Mallothi, an Israelite Mallothi.', 'apparently from 4448; I have talked (i.e. loquacious)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4414]', 'root', 'heb', 'מָלַח', '["mâlach"]', '["properly, to rub to pieces or pulverize; intransitively, to disappear as dust; also to salt whether internally (to season with salt) or externally (to rub with salt) × at all, salt, season, temper together, vanish away."]', '["v"]', 'properly, to rub to pieces or pulverize; intransitively, to disappear as dust; also to salt whether internally (to season with salt) or externally (to rub with salt) × at all, salt, season, temper together, vanish away.', 'a primitive root; also as denominative from 4417');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4415}/[H4415]', 'lemma', 'arc', 'מְלַח', '["mᵉlach"]', '["to eat salt, i.e. (generally) subsist have maintenance."]', '["v"]', 'to eat salt, i.e. (generally) subsist have maintenance.', '(Aramaic) corresponding to 4414;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4416}/[H4416]', 'lemma', 'arc', 'מְלַח', '["mᵉlach"]', '["salt maintenance, salt."]', '["n-m"]', 'salt maintenance, salt.', '(Aramaic) from 4415;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4417}/[H4417]', 'lemma', 'heb', 'מֶלַח', '["melach"]', '["properly, powder, i.e. (specifically) salt (as easily pulverized and dissolved) salt(-pit)."]', '["n-m"]', 'properly, powder, i.e. (specifically) salt (as easily pulverized and dissolved) salt(-pit).', 'from 4414;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4418}/[H4418]', 'lemma', 'heb', 'מָלָח', '["mâlâch"]', '["a rag or old garment rotten rag."]', '["n-m"]', 'a rag or old garment rotten rag.', 'from 4414 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4419}/[H4419]', 'lemma', 'heb', 'מַלָּח', '["mallâch"]', '["a sailor (as following ''the salt'') mariner."]', '["n-m"]', 'a sailor (as following ''the salt'') mariner.', 'from 4414 in its second. sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4420}/[H4420]', 'lemma', 'heb', 'מְלֵחָה', '["mᵉlêchâh"]', '["properly, salted (i.e. land), i.e. a desert barren land(-ness), salt (land)."]', '["n-f"]', 'properly, salted (i.e. land), i.e. a desert barren land(-ness), salt (land).', 'from 4414 (in its denominative sense); understood as land (776)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4421}/[H4421]', 'lemma', 'heb', 'מִלְחָמָה', '["milchâmâh"]', '["a battle (i.e. the engagement); generally, war (i.e. war-fare) battle, fight(-ing), war(-rior)."]', '["n-f"]', 'a battle (i.e. the engagement); generally, war (i.e. war-fare) battle, fight(-ing), war(-rior).', 'from 3898 (in the sense of fighting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4422]', 'root', 'heb', 'מָלַט', '["mâlaṭ"]', '["properly, to be smooth, i.e. (by implication) to escape (as if by slipperiness); causatively, to release or rescue; specifically, to bring forth young, emit sparks deliver (self), escape, lay, leap out, let alone, let go, preserve, save, × speedily, × surely."]', '["v"]', 'properly, to be smooth, i.e. (by implication) to escape (as if by slipperiness); causatively, to release or rescue; specifically, to bring forth young, emit sparks deliver (self), escape, lay, leap out, let alone, let go, preserve, save, × speedily, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4423}/[H4423]', 'lemma', 'heb', 'מֶלֶט', '["meleṭ"]', '["cement (from its plastic smoothness) clay."]', '["n-m"]', 'cement (from its plastic smoothness) clay.', 'from 4422,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4424}/[H4424]', 'lemma', 'heb', 'מְלַטְיָה', '["Mᵉlaṭyâh"]', '["Melatjah, a Gibeonite Melatiah."]', '["n-pr-m"]', 'Melatjah, a Gibeonite Melatiah.', 'from 4423 and 3050; (whom) Jah has delivered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4425}/[H4425]', 'lemma', 'heb', 'מְלִילָה', '["mᵉlîylâh"]', '["a head of grain (as cut off) ear."]', '["n-f"]', 'a head of grain (as cut off) ear.', 'from 4448number 4449, corrected to 4448b (in the sense of cropping (compare 4135));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4426}/[H4426]', 'lemma', 'heb', 'מְלִיצָה', '["mᵉlîytsâh"]', '["an aphorism; also a satire interpretation, taunting."]', '["n-f"]', 'an aphorism; also a satire interpretation, taunting.', 'from 3887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4427]', 'root', 'heb', 'מָלַךְ', '["mâlak"]', '["to reign; inceptively, to ascend the throne; causatively, to induct into royalty; hence (by implication) to take counsel consult, × indeed, be (make, set a, set up) king, be (make) queen, (begin to, make to) reign(-ing), rule, × surely."]', '["v"]', 'to reign; inceptively, to ascend the throne; causatively, to induct into royalty; hence (by implication) to take counsel consult, × indeed, be (make, set a, set up) king, be (make) queen, (begin to, make to) reign(-ing), rule, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4428}/[H4428]', 'lemma', 'heb', 'מֶלֶךְ', '["melek"]', '["a king king, royal."]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4429}/[H4429]', 'lemma', 'heb', 'מֶלֶךְ', '["Melek"]', '["Melek, the name of two Israelites Melech, Hammelech (by including the article)."]', '["n-pr-m"]', 'Melek, the name of two Israelites Melech, Hammelech (by including the article).', 'the same as 4428; king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4430}/[H4430]', 'lemma', 'arc', 'מֶלֶךְ', '["melek"]', '["a king king, royal."]', '["n-m"]', 'a king king, royal.', '(Aramaic) corresponding to 4428;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4431}/[H4431]', 'lemma', 'arc', 'מְלַךְ', '["mᵉlak"]', '["advice counsel."]', '["n-m"]', 'advice counsel.', '(Aramaic) from a root corresponding to 4427 in the sense of consultation;');
