INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4549]', 'root', 'heb', 'מָסַס', '["mâçaç"]', '["to liquefy; figuratively, to waste (with disease), to faint (with fatigue, fear or grief) discourage, faint, be loosed, melt (away), refuse, × utterly."]', '["v"]', 'to liquefy; figuratively, to waste (with disease), to faint (with fatigue, fear or grief) discourage, faint, be loosed, melt (away), refuse, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4550}/[H4550]', 'lemma', 'heb', 'מַסַּע', '["maççaʻ"]', '["a departure (from striking the tents), i.e. march (not necessarily a single day''s travel); by implication, a station (or point of departure) journey(-ing)."]', '["n-m"]', 'a departure (from striking the tents), i.e. march (not necessarily a single day''s travel); by implication, a station (or point of departure) journey(-ing).', 'from 5265;');
