INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4570}/[H4570]', 'lemma', 'heb', 'מַעְגָּל', '["maʻgâl"]', '["a track (literally or figuratively); also a rampart (as circular) going, path, trench, way(-side)."]', '["n-m"]', 'a track (literally or figuratively); also a rampart (as circular) going, path, trench, way(-side).', 'or feminine מַעְגָּלָה; from the same as 5696;');
