INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4578>', 'opaque', 'heb', 'מֵעֶה', '["mêʻeh"]', '["used only in plural the intestines, or (collectively) the abdomen, figuratively, sympathy; by implication, a vest; by extension the stomach, the uterus (or of men, the seat of generation), the heart (figuratively) belly, bowels, × heart, womb."]', '["n-m"]', 'used only in plural the intestines, or (collectively) the abdomen, figuratively, sympathy; by implication, a vest; by extension the stomach, the uterus (or of men, the seat of generation), the heart (figuratively) belly, bowels, × heart, womb.', 'from an unused root probably meaning to be soft;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4579}/[H4579]', 'lemma', 'heb', 'מֵעָה', '["mêʻâh"]', '["the belly, i.e. (figuratively) interior gravel."]', '["n-f"]', 'the belly, i.e. (figuratively) interior gravel.', 'feminine of 4578;');
