INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4582}/[H4582]', 'lemma', 'heb', 'מָעוֹךְ', '["Mâʻôwk"]', '["Maok, a Philistine Maoch."]', '["n-pr-m"]', 'Maok, a Philistine Maoch.', 'from 4600; oppressed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4583}/[H4583]', 'lemma', 'heb', 'מָעוֹן', '["mâʻôwn"]', '["an abode, of God (the Tabernacle or the Temple), men (their home) or animals (their lair); hence, a retreat (asylum) den, dwelling((-) place), habitation."]', '["n-m"]', 'an abode, of God (the Tabernacle or the Temple), men (their home) or animals (their lair); hence, a retreat (asylum) den, dwelling((-) place), habitation.', 'or מָעִין; (1 Chronicles 4:41), from the same as 5772;');
