INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4585}/[H4585]', 'lemma', 'heb', 'מְעוֹנָה', '["mᵉʻôwnâh"]', '["den, habitation, (dwelling) place, refuge."]', '["n-f"]', 'den, habitation, (dwelling) place, refuge.', 'or מְעֹנָה; feminine of 4583, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4586}/[H4586]', 'lemma', 'heb', 'מְעוּנִי', '["Mᵉʻûwnîy"]', '["a Meunite, or inhabitant of Maon (only in plural) Mehunim(-s), Meunim."]', '["n-pr-m"]', 'a Meunite, or inhabitant of Maon (only in plural) Mehunim(-s), Meunim.', 'or מְעִינִי; probably patrial from 4584;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4587}/[H4587]', 'lemma', 'heb', 'מְעוֹנֹתַי', '["Mᵉʻôwnôthay"]', '["Meonothai, an Israelite Meonothai."]', '["n-pr-m"]', 'Meonothai, an Israelite Meonothai.', 'plural of 4585; habitative;');
