INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4589}/[H4589]', 'lemma', 'heb', 'מָעוֹר', '["mâʻôwr"]', '["nakedness, i.e. (in plural) the pudenda nakedness."]', '["n-m"]', 'nakedness, i.e. (in plural) the pudenda nakedness.', 'from 5783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4590}/[H4590]', 'lemma', 'heb', 'מַעַזְיָה', '["Maʻazyâh"]', '["Maazjah, the name of two Israelites Maaziah."]', '["n-pr-m"]', 'Maazjah, the name of two Israelites Maaziah.', 'or מַעַזְיָהוּ; probably from 5756 (in the sense of protection) and 3050; rescue of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4591]', 'root', 'heb', 'מָעַט', '["mâʻaṭ"]', '["properly, to pare off, i.e. lessen; intransitively, to be (or causatively, to make) small or few (or figuratively, ineffective) suffer to decrease, diminish, (be, × borrow a, give, make) few (in number, -ness), gather least (little), be (seem) little, (× give the) less, be minished, bring to nothing."]', '["v"]', 'properly, to pare off, i.e. lessen; intransitively, to be (or causatively, to make) small or few (or figuratively, ineffective) suffer to decrease, diminish, (be, × borrow a, give, make) few (in number, -ness), gather least (little), be (seem) little, (× give the) less, be minished, bring to nothing.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4592}/[H4592]', 'lemma', 'heb', 'מְעַט', '["mᵉʻaṭ"]', '["a little or few (often adverbial or comparative) almost (some, very) few(-er, -est), lightly, little (while), (very) small (matter, thing), some, soon, × very."]', '["n-m"]', 'a little or few (often adverbial or comparative) almost (some, very) few(-er, -est), lightly, little (while), (very) small (matter, thing), some, soon, × very.', 'or מְעָט; from 4591;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4593}/[H4593]', 'lemma', 'heb', 'מָעֹט', '["mâʻôṭ"]', '["thinned (as to the edge), i.e. sharp wrapped up."]', '["n"]', 'thinned (as to the edge), i.e. sharp wrapped up.', 'passive adjective of 4591;');
