INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4598}/[H4598]', 'lemma', 'heb', 'מְעִיל', '["mᵉʻîyl"]', '["a robe (i.e. upper and outer garment) cloke, coat, mantle, robe."]', '["n-m"]', 'a robe (i.e. upper and outer garment) cloke, coat, mantle, robe.', 'from 4603 in the sense of covering;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4599}/[H4599]', 'lemma', 'heb', 'מַעְיָן', '["maʻyân"]', '["a fountain (also collectively), figuratively, a source (of satisfaction) fountain, spring, well."]', '["n-m"]', 'a fountain (also collectively), figuratively, a source (of satisfaction) fountain, spring, well.', 'or מַעְיְנוֹ; (Psalm 114:8), or (feminine) מַעְיָנָה; from 5869 (as a denominative in the sense of a spring);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4600]', 'root', 'heb', 'מָעַךְ', '["mâʻak"]', '["to press, i.e. to pierce, emasculate, handle bruised, stuck, be pressed."]', '["v"]', 'to press, i.e. to pierce, emasculate, handle bruised, stuck, be pressed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4601}/[H4601]', 'lemma', 'heb', 'מַעֲכָה', '["Maʻăkâh"]', '["Maakah (or Maakath), the name of a place in Syria, also of a Mesopotamian, of three Israelites, and of four Israelitesses and one Syrian woman Maachah, Maachathites. See also 1038."]', '["n-pr"]', 'Maakah (or Maakath), the name of a place in Syria, also of a Mesopotamian, of three Israelites, and of four Israelitesses and one Syrian woman Maachah, Maachathites. See also 1038.', 'or מַעֲכָת; (Joshua 13:13), from 4600; depression;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4602}/[H4602]', 'lemma', 'heb', 'מַעֲכָתִי', '["Maʻăkâthîy"]', '["a Maakathite, or inhabitant of Maakah Maachathite."]', '["a"]', 'a Maakathite, or inhabitant of Maakah Maachathite.', 'patrial from 4601;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4603]', 'root', 'heb', 'מָעַל', '["mâʻal"]', '["properly, to cover up; used only figuratively, to act covertly, i.e. treacherously transgress, (commit, do a) trespass(-ing)."]', '["v"]', 'properly, to cover up; used only figuratively, to act covertly, i.e. treacherously transgress, (commit, do a) trespass(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4604}/[H4604]', 'lemma', 'heb', 'מַעַל', '["maʻal"]', '["treachery, i.e. sin falsehood, grievously, sore, transgression, trespass, × very."]', '["n-m"]', 'treachery, i.e. sin falsehood, grievously, sore, transgression, trespass, × very.', 'from 4603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4605}/[H4605]', 'lemma', 'heb', 'מַעַל', '["maʻal"]', '["properly,the upper part, used only adverbially with prefix upward, above, overhead, from the top, etc. above, exceeding(-ly), forward, on (× very) high, over, up(-on, -ward), very."]', '["adv"]', 'properly,the upper part, used only adverbially with prefix upward, above, overhead, from the top, etc. above, exceeding(-ly), forward, on (× very) high, over, up(-on, -ward), very.', 'from 5927;');
