INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4607}/[H4607]', 'lemma', 'heb', 'מֹעַל', '["môʻal"]', '["a raising (of the hands) lifting up."]', '["n-m"]', 'a raising (of the hands) lifting up.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4608}/[H4608]', 'lemma', 'heb', 'מַעֲלֶה', '["maʻăleh"]', '["an elevation, i.e. (concretely) acclivity or platform; abstractly (the relation or state) a rise or (figuratively) priority ascent, before, chiefest, cliff, that goeth up, going up, hill, mounting up, stairs."]', '["n-m"]', 'an elevation, i.e. (concretely) acclivity or platform; abstractly (the relation or state) a rise or (figuratively) priority ascent, before, chiefest, cliff, that goeth up, going up, hill, mounting up, stairs.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4609}/[H4609]', 'lemma', 'heb', 'מַעֲלָה', '["maʻălâh"]', '["elevation, i.e. the act (literally, a journey to a higher place, figuratively, a thought arising), or (concretely) the condition (literally, a step or grade-mark, figuratively, a superiority of station); specifically a climactic progression (in certain Psalms) things that come up, (high) degree, deal, go up, stair, step, story."]', '["n-f"]', 'elevation, i.e. the act (literally, a journey to a higher place, figuratively, a thought arising), or (concretely) the condition (literally, a step or grade-mark, figuratively, a superiority of station); specifically a climactic progression (in certain Psalms) things that come up, (high) degree, deal, go up, stair, step, story.', 'feminine of 4608;');
