INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4674}/[H4674]', 'lemma', 'heb', 'מֻצָּב', '["mutstsâb"]', '["a station, i.e. military post mount."]', '["n-m"]', 'a station, i.e. military post mount.', 'from 5324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4675}/[H4675]', 'lemma', 'heb', 'מַצָּבָה', '["matstsâbâh"]', '["a military guard army, garrison."]', '["n-f"]', 'a military guard army, garrison.', 'or מִצָּבָה; feminine of 4673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4676}/[H4676]', 'lemma', 'heb', 'מַצֵּבָה', '["matstsêbâh"]', '["something stationed, i.e. a column or (memorial stone); by analogy, an idol garrison, (standing) image, pillar."]', '["n-f"]', 'something stationed, i.e. a column or (memorial stone); by analogy, an idol garrison, (standing) image, pillar.', 'feminine (causatively) participle of 5324;');
