INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4680]', 'root', 'heb', 'מָצָה', '["mâtsâh"]', '["to suck out; by implication, to drain, to squeeze out suck, wring (out)."]', '["v"]', 'to suck out; by implication, to drain, to squeeze out suck, wring (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4681}/[H4681]', 'lemma', 'heb', 'מֹצָה', '["Môtsâh"]', '["Motsah, a place in Palestine Mozah."]', '["n-pr-f"]', 'Motsah, a place in Palestine Mozah.', 'active participle feminine of 4680; drained;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4682}/[H4682]', 'lemma', 'heb', 'מַצָּה', '["matstsâh"]', '["properly, sweetness; concretely, sweet (i.e. not soured or bittered with yeast); specifically, an unfermented cake or loaf, or (elliptically) the festival of Passover (because no leaven was then used) unleaved (bread, cake), without leaven."]', '["n-f"]', 'properly, sweetness; concretely, sweet (i.e. not soured or bittered with yeast); specifically, an unfermented cake or loaf, or (elliptically) the festival of Passover (because no leaven was then used) unleaved (bread, cake), without leaven.', 'from 4711 in the sense of greedily devouring for sweetness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4683}/[H4683]', 'lemma', 'heb', 'מַצָּה', '["matstsâh"]', '["a quarrel contention, debate, strife."]', '["n-f"]', 'a quarrel contention, debate, strife.', 'from 5327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4684}/[H4684]', 'lemma', 'heb', 'מַצְהָלָה', '["matshâlâh"]', '["a whinnying (through impatience for battle or lust) neighing."]', '["n-f"]', 'a whinnying (through impatience for battle or lust) neighing.', 'from 6670;');
