INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4686}/[H4686]', 'lemma', 'heb', 'מָצוּד', '["mâtsûwd"]', '["a net, or (abstractly) capture; also a fastness castle, defense, fort(-ress), (strong) hold, be hunted, net, snare, strong place."]', '["n-f"]', 'a net, or (abstractly) capture; also a fastness castle, defense, fort(-ress), (strong) hold, be hunted, net, snare, strong place.', 'or (feminine) מְצוּדָה; or מְצֻדָה; for 4685;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4687}/[H4687]', 'lemma', 'heb', 'מִצְוָה', '["mitsvâh"]', '["a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept."]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4688}/[H4688]', 'lemma', 'heb', 'מְצוֹלָה', '["mᵉtsôwlâh"]', '["a deep place (of water or mud) bottom, deep, depth."]', '["n-f"]', 'a deep place (of water or mud) bottom, deep, depth.', 'or מְצֹלָה; also מְצוּלָה; or מְצֻלָה; from the same as 6683;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4689}/[H4689]', 'lemma', 'heb', 'מָצוֹק', '["mâtsôwq"]', '["a narrow place, i.e. (abstractly and figuratively) confinement or disability anguish, distress, straitness."]', '["n-m"]', 'a narrow place, i.e. (abstractly and figuratively) confinement or disability anguish, distress, straitness.', 'from 6693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4690}/[H4690]', 'lemma', 'heb', 'מָצוּק', '["mâtsûwq"]', '["something narrow, i.e. a column or hilltop pillar, situate."]', '["n-m"]', 'something narrow, i.e. a column or hilltop pillar, situate.', 'or מָצֻק; from 6693;');
