INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4692}/[H4692]', 'lemma', 'heb', 'מָצוֹר', '["mâtsôwr"]', '["something hemming in, i.e. (objectively) a mound (of besiegers), (abstractly) a siege, (figuratively) distress; or (subjectively) a fastness besieged, bulwark, defence, fenced, fortress, siege, strong (hold), tower."]', '["n-m"]', 'something hemming in, i.e. (objectively) a mound (of besiegers), (abstractly) a siege, (figuratively) distress; or (subjectively) a fastness besieged, bulwark, defence, fenced, fortress, siege, strong (hold), tower.', 'or מָצוּר; from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4693}/[H4693]', 'lemma', 'heb', 'מָצוֹר', '["mâtsôwr"]', '["Egypt (as the border of Palestine) besieged places, defense, fortified."]', '["n-pr-loc"]', 'Egypt (as the border of Palestine) besieged places, defense, fortified.', 'the same as 4692 in the sense of a limit;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4694}/[H4694]', 'lemma', 'heb', 'מְצוּרָה', '["mᵉtsûwrâh"]', '["a hemming in, i.e. (objectively) a mound (of siege), or (subjectively) a rampart (of protection), (abstractly) fortification fenced (city, fort, munition, strong hold."]', '["n-f"]', 'a hemming in, i.e. (objectively) a mound (of siege), or (subjectively) a rampart (of protection), (abstractly) fortification fenced (city, fort, munition, strong hold.', 'or מְצֻרָה; feminine of 4692;');
