INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4723}/[H4723]', 'lemma', 'heb', 'מִקְוֶה', '["miqveh"]', '["something waited for, i.e. confidence (objective or subjective); also a collection, i.e. (of water) a pond, or (of men and horses) a caravan or drove abiding, gathering together, hope, linen yarn, plenty (of water), pool."]', '["n-pr-m n-m"]', 'something waited for, i.e. confidence (objective or subjective); also a collection, i.e. (of water) a pond, or (of men and horses) a caravan or drove abiding, gathering together, hope, linen yarn, plenty (of water), pool.', 'or מִקְוֵה; (1 Kings 10:28), or מִקְוֵאlemma מִּקְוֵא extra dagesh, corrected to מִקְוֵא; (2 Chronicles 1:16), from 6960;');
