INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4726}/[H4726]', 'lemma', 'heb', 'מָקוֹר', '["mâqôwr"]', '["properly, something dug, i.e. a (general) source (of water, even when naturally flowing; also of tears, blood (by euphemism, of the female pudenda); figuratively, of happiness, wisdom, progeny) fountain, issue, spring, well(-spring)."]', '["n-m"]', 'properly, something dug, i.e. a (general) source (of water, even when naturally flowing; also of tears, blood (by euphemism, of the female pudenda); figuratively, of happiness, wisdom, progeny) fountain, issue, spring, well(-spring).', 'or מָקֹר; from 6979;');
