INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4750}/[H4750]', 'lemma', 'heb', 'מִקְשָׁה', '["miqshâh"]', '["literally a cucumbered field, i.e. a cucumber patch garden of cucumbers."]', '["n-f"]', 'literally a cucumbered field, i.e. a cucumber patch garden of cucumbers.', 'denominative from 7180;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4751}/[H4751]', 'lemma', 'heb', 'מַר', '["mar"]', '["bitter (literally or figuratively); also (as noun) bitterness, or (adverbially) bitterly angry, bitter(-ly, -ness), chafed, discontented, × great, heavy."]', '["a-m"]', 'bitter (literally or figuratively); also (as noun) bitterness, or (adverbially) bitterly angry, bitter(-ly, -ness), chafed, discontented, × great, heavy.', 'or (feminine) מָרָה; from 4843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4752}/[H4752]', 'lemma', 'heb', 'מַר', '["mar"]', '["a drop drop."]', '["n-m"]', 'a drop drop.', 'from 4843 in its original sense of distillation;');
