INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4754]', 'root', 'heb', 'מָרָא', '["mârâʼ"]', '["to rebel; hence (through the idea of maltreating) to whip, i.e. lash (self with wings, as the ostrich in running) be filthy, lift up self."]', '["v"]', 'to rebel; hence (through the idea of maltreating) to whip, i.e. lash (self with wings, as the ostrich in running) be filthy, lift up self.', 'a primitive root;');
