INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4907}/[H4907]', 'lemma', 'arc', 'מִשְׁכַּן', '["mishkan"]', '["residence habitation."]', '["n-m"]', 'residence habitation.', '(Aramaic) corresponding to 4908;');
