INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4910]', 'root', 'heb', 'מָשַׁל', '["mâshal"]', '["to rule (have, make to have) dominion, governor, × indeed, reign, (bear, cause to, have) rule(-ing, -r), have power."]', '["v"]', 'to rule (have, make to have) dominion, governor, × indeed, reign, (bear, cause to, have) rule(-ing, -r), have power.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4911}/[H4911]', 'lemma', 'heb', 'מָשַׁל', '["mâshal"]', '["to liken, i.e. (transitively) to use figurative language (an allegory, adage, song or the like); intransitively, to resemble be(-come) like, compare, use (as a) proverb, speak (in proverbs), utter."]', '["v"]', 'to liken, i.e. (transitively) to use figurative language (an allegory, adage, song or the like); intransitively, to resemble be(-come) like, compare, use (as a) proverb, speak (in proverbs), utter.', 'denominative from 4912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4912}/[H4912]', 'lemma', 'heb', 'מָשָׁל', '["mâshâl"]', '["properly, a pithy maxim, usually of metaphorical nature; hence, a simile (as an adage, poem, discourse) byword, like, parable, proverb."]', '["n-m"]', 'properly, a pithy maxim, usually of metaphorical nature; hence, a simile (as an adage, poem, discourse) byword, like, parable, proverb.', 'apparently from 4910 in some original sense of superiority in mental action;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4913}/[H4913]', 'lemma', 'heb', 'מָשָׁל', '["Mâshâl"]', '["Mashal, a place in Palestine Mashal."]', '["n-pr-loc"]', 'Mashal, a place in Palestine Mashal.', 'for 4861;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4914}/[H4914]', 'lemma', 'heb', 'מְשֹׁל', '["mᵉshôl"]', '["a satire byword."]', '["n-m"]', 'a satire byword.', 'from 4911;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4915}/[H4915]', 'lemma', 'heb', 'מֹשֶׁל', '["môshel"]', '["empire; a parallel dominion, like."]', '["n-m"]', 'empire; a parallel dominion, like.', '(1) from 4910; (2) from 4911;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4916}/[H4916]', 'lemma', 'heb', 'מִשְׁלוֹחַ', '["mishlôwach"]', '["a sending out, i.e. (abstractly) presentation (favorable), or seizure (unfavorable); also (concretely) a place of dismissal, or a business to be discharged to lay, to put, sending (forth), to set."]', '["n-m"]', 'a sending out, i.e. (abstractly) presentation (favorable), or seizure (unfavorable); also (concretely) a place of dismissal, or a business to be discharged to lay, to put, sending (forth), to set.', 'or מִשְׁלֹחַ; also מִשְׁלָח; from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4917}/[H4917]', 'lemma', 'heb', 'מִשְׁלַחַת', '["mishlachath"]', '["a mission, i.e. (abstractly and favorable) release, or (concretely and unfavorable) an army discharge, sending."]', '["n-f"]', 'a mission, i.e. (abstractly and favorable) release, or (concretely and unfavorable) an army discharge, sending.', 'feminine of 4916;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4918}/[H4918]', 'lemma', 'heb', 'מְשֻׁלָּם', '["Mᵉshullâm"]', '["Meshullam, the name of seventeen Israelites Meshullam."]', '["n-pr-m"]', 'Meshullam, the name of seventeen Israelites Meshullam.', 'from 7999; allied;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4919}/[H4919]', 'lemma', 'heb', 'מְשִׁלֵּמוֹת', '["Mᵉshillêmôwth"]', '["Meshillemoth, an Israelite Meshillemoth. Compare 4921."]', '["n-pr-m"]', 'Meshillemoth, an Israelite Meshillemoth. Compare 4921.', 'plural from 7999; reconciliations');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4920}/[H4920]', 'lemma', 'heb', 'מְשֶׁלֶמְיָה', '["Mᵉshelemyâh"]', '["Meshelemjah, an Israelite Meshelemiah."]', '["n-pr-m"]', 'Meshelemjah, an Israelite Meshelemiah.', 'or מְשֶׁלֶמְיָהוּ; from 7999 and 3050; ally of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4921}/[H4921]', 'lemma', 'heb', 'מְשִׁלֵּמִית', '["Mᵉshillêmîyth"]', '["Meshillemith, an Israelite Meshillemith. Compare 4919."]', '["n-pr-m"]', 'Meshillemith, an Israelite Meshillemith. Compare 4919.', 'from 7999; reconciliation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4922}/[H4922]', 'lemma', 'heb', 'מְשֻׁלֶּמֶת', '["Mᵉshullemeth"]', '["Meshullemeth, an Israelitess Meshullemeth."]', '["n-pr-f"]', 'Meshullemeth, an Israelitess Meshullemeth.', 'feminine of 4918;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4923}/[H4923]', 'lemma', 'heb', 'מְשַׁמָּה', '["mᵉshammâh"]', '["a waste or amazement astonishment, desolate."]', '["n-f"]', 'a waste or amazement astonishment, desolate.', 'from 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4924}/[H4924]', 'lemma', 'heb', 'מַשְׁמָן', '["mashmân"]', '["fat, i.e. (literally and abstractly) fatness; but usually (figuratively and concretely) a rich dish, a fertile field, a robust man fat (one, -ness, -test, -test place)."]', '["n-m"]', 'fat, i.e. (literally and abstractly) fatness; but usually (figuratively and concretely) a rich dish, a fertile field, a robust man fat (one, -ness, -test, -test place).', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4925}/[H4925]', 'lemma', 'heb', 'מִשְׁמַנָּה', '["Mishmannâh"]', '["Mashmannah, an Israelite Mishmannah."]', '["n-pr-m"]', 'Mashmannah, an Israelite Mishmannah.', 'from 8080; fatness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4926}/[H4926]', 'lemma', 'heb', 'מִשְׁמָע', '["mishmâʻ"]', '["a report hearing."]', '["n-m"]', 'a report hearing.', 'from 8085;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4927}/[H4927]', 'lemma', 'heb', 'מִשְׁמָע', '["Mishmâʻ"]', '["Mishma, the name of a son of Ishmael, and of an Israelite Mishma."]', '["n-pr-m"]', 'Mishma, the name of a son of Ishmael, and of an Israelite Mishma.', 'the same as 4926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4928}/[H4928]', 'lemma', 'heb', 'מִשְׁמַעַת', '["mishmaʻath"]', '["audience, i.e. the royal court; also obedience, i.e. (concretely) a subject bidding, guard, obey."]', '["n-f"]', 'audience, i.e. the royal court; also obedience, i.e. (concretely) a subject bidding, guard, obey.', 'feminine of 4926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4929}/[H4929]', 'lemma', 'heb', 'מִשְׁמָר', '["mishmâr"]', '["a guard (the man, the post or the prison); a deposit (figuratively); also (as observed) a usage (abstractly), or an example (concretely) diligence, guard, office, prison, ward, watch."]', '["n-m"]', 'a guard (the man, the post or the prison); a deposit (figuratively); also (as observed) a usage (abstractly), or an example (concretely) diligence, guard, office, prison, ward, watch.', 'from 8104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4930}/[H4930]', 'lemma', 'heb', 'מַשְׂמְרָה', '["masmᵉrâh"]', '["a peg nail."]', '["n-f"]', 'a peg nail.', 'for 4548 fem.;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4931}/[H4931]', 'lemma', 'heb', 'מִשְׁמֶרֶת', '["mishmereth"]', '["watch, i.e. the act (custody), or (concretely) the sentry, the post; objectively preservation, or (concretely) safe; figuratively observance, i.e. (abstractly) duty or (objectively) a usage or party charge, keep, or to be kept, office, ordinace, safeguard, ward, watch."]', '["n-f"]', 'watch, i.e. the act (custody), or (concretely) the sentry, the post; objectively preservation, or (concretely) safe; figuratively observance, i.e. (abstractly) duty or (objectively) a usage or party charge, keep, or to be kept, office, ordinace, safeguard, ward, watch.', 'feminine of 4929;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4932}/[H4932]', 'lemma', 'heb', 'מִשְׁנֶה', '["mishneh"]', '["properly, a repetition, i.e. a duplicate (copy of a document), or a double (in amount); by implication, a second (in order, rank, age, quality or location) college, copy, double, fatlings, next, second (order), twice as much."]', '["n-m"]', 'properly, a repetition, i.e. a duplicate (copy of a document), or a double (in amount); by implication, a second (in order, rank, age, quality or location) college, copy, double, fatlings, next, second (order), twice as much.', 'from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4933}/[H4933]', 'lemma', 'heb', 'מְשִׁסָּה', '["mᵉshiççâh"]', '["plunder booty, spoil."]', '["n-f"]', 'plunder booty, spoil.', 'from 8155;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4934}/[H4934]', 'lemma', 'heb', 'מִשְׁעוֹל', '["mishʻôwl"]', '["a hollow, i.e. a narrow passage path."]', '["n-m"]', 'a hollow, i.e. a narrow passage path.', 'from the same as 8168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4935}/[H4935]', 'lemma', 'heb', 'מִשְׁעִי', '["mishʻîy"]', '["inspection to supple."]', '["n-f"]', 'inspection to supple.', 'probably from 8159;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4936}/[H4936]', 'lemma', 'heb', 'מִשְׁעָם', '["Mishʻâm"]', '["Misham, an Israelite Misham."]', '["n-pr-m"]', 'Misham, an Israelite Misham.', 'apparently from 8159; inspection;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4937}/[H4937]', 'lemma', 'heb', 'מִשְׁעֵן', '["mishʻên"]', '["a support (concretely), i.e. (figuratively) a protector or sustenance stay."]', '["n-m"]', 'a support (concretely), i.e. (figuratively) a protector or sustenance stay.', 'or מִשְׁעָן; from 8172;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4938}/[H4938]', 'lemma', 'heb', 'מִשְׁעֵנָה', '["mishʻênâh"]', '["support (abstractly), i.e. (figuratively) sustenance or (concretely) a walking-stick staff."]', '["n-f"]', 'support (abstractly), i.e. (figuratively) sustenance or (concretely) a walking-stick staff.', 'or מִשְׁעֶנֶת; feminine of 4937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4939}/[H4939]', 'lemma', 'heb', 'מִשְׂפָּח', '["mispâch"]', '["slaughter oppression."]', '["n-m"]', 'slaughter oppression.', 'from 5596;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4940}/[H4940]', 'lemma', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red)."]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4941}/[H4941]', 'lemma', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong."]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4942}/[H4942]', 'lemma', 'heb', 'מִשְׁפָּת', '["mishpâth"]', '["a stall for cattle (only dual) burden, sheepfold."]', '["n-m"]', 'a stall for cattle (only dual) burden, sheepfold.', 'from 8192;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4944}/[H4944]', 'lemma', 'heb', 'מַשָּׁק', '["mashshâq"]', '["a traversing, i.e. rapid motion running to and fro."]', '["n-m"]', 'a traversing, i.e. rapid motion running to and fro.', 'from 8264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4945}/[H4945]', 'lemma', 'heb', 'מַשְׁקֶה', '["mashqeh"]', '["properly, causing to drink, i.e. a butler; by implication (intransitively), drink (itself); figuratively, a well-watered region butler(-ship), cupbearer, drink(-ing), fat pasture, watered."]', '["n-m"]', 'properly, causing to drink, i.e. a butler; by implication (intransitively), drink (itself); figuratively, a well-watered region butler(-ship), cupbearer, drink(-ing), fat pasture, watered.', 'from 8248;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4946}/[H4946]', 'lemma', 'heb', 'מִשְׁקוֹל', '["mishqôwl"]', '["weight weight."]', '["n-m"]', 'weight weight.', 'from 8254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4947}/[H4947]', 'lemma', 'heb', 'מַשְׁקוֹף', '["mashqôwph"]', '["a lintel lintel."]', '["n-m"]', 'a lintel lintel.', 'from 8259 in its original sense of overhanging;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4948}/[H4948]', 'lemma', 'heb', 'מִשְׁקָל', '["mishqâl"]', '["weight (numerically estimated); hence, weighing (the act) (full) weight."]', '["n-m"]', 'weight (numerically estimated); hence, weighing (the act) (full) weight.', 'from 8254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4949}/[H4949]', 'lemma', 'heb', 'מִשְׁקֶלֶת', '["mishqeleth"]', '["a weight, i.e. a plummet (with line attached) plummet."]', '["n-f"]', 'a weight, i.e. a plummet (with line attached) plummet.', 'or מִשְׁקֹלֶת; feminine of 4948 or 4947;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4950}/[H4950]', 'lemma', 'heb', 'מִשְׁקָע', '["mishqâʻ"]', '["a settling place (of water), i.e. a pond deep."]', '["n-m"]', 'a settling place (of water), i.e. a pond deep.', 'from 8257;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4951}/[H4951]', 'lemma', 'heb', 'מִשְׂרָה', '["misrâh"]', '["empire government."]', '["n-f"]', 'empire government.', 'from 8280;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4952}/[H4952]', 'lemma', 'heb', 'מִשְׁרָה', '["mishrâh"]', '["maceration, i.e. steeped juice liquor."]', '["n-f"]', 'maceration, i.e. steeped juice liquor.', 'from 8281 in the sense of loosening;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4953}/[H4953]', 'lemma', 'arc', 'מַשְׁרוֹקִי', '["mashrôwqîy"]', '["a (musical) pipe (from its whistling sound) flute."]', '["n-f"]', 'a (musical) pipe (from its whistling sound) flute.', '(Aramaic) from a root corresponding to 8319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4954>', 'opaque', 'heb', 'מִשְׁרָעִי', '["Mishrâʻîy"]', '["a Mishraite, or inhabitant (collectively) of Mishra Mishraites."]', '["a"]', 'a Mishraite, or inhabitant (collectively) of Mishra Mishraites.', 'patrial from an unused noun from an unused root; probably meaning to stretch out; extension;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4955}/[H4955]', 'lemma', 'heb', 'מִשְׂרָפָה', '["misrâphâh"]', '["combustion, i.e. cremation (of a corpse), or calcination (of lime) burning."]', '["n-f"]', 'combustion, i.e. cremation (of a corpse), or calcination (of lime) burning.', 'from 8313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4956}/[H4956]', 'lemma', 'heb', 'מִשְׂרְפוֹת מַיִם', '["Misrᵉphôwth mayim"]', '["Misrephoth-Majim, a place in Palestine Misrephoth-mayim."]', '["n-pr-loc"]', 'Misrephoth-Majim, a place in Palestine Misrephoth-mayim.', 'from the plural of 4955 and 4325; burnings of water;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4957}/[H4957]', 'lemma', 'heb', 'מַשְׂרֵקָה', '["Masrêqâh"]', '["Masrekah, a place in Idumaea Masrekah."]', '["n-pr-loc"]', 'Masrekah, a place in Idumaea Masrekah.', 'a form for 7796 used denominatively; vineyard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4958>', 'opaque', 'heb', 'מַשְׂרֵת', '["masrêth"]', '["a pan pan."]', '["n-m"]', 'a pan pan.', 'apparently from an unused root meaning to perforate, i.e. hollow out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H4959]', 'root', 'heb', 'מָשַׁשׁ', '["mâshash"]', '["to feel of; by implication, to grope feel, grope, search."]', '["v"]', 'to feel of; by implication, to grope feel, grope, search.', 'a primitive root;');
