INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5023>', 'opaque', 'arc', 'נְבִזְבָּה', '["nᵉbizbâh"]', '["a largess reward."]', '["n-f"]', 'a largess reward.', '(Aramaic) of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5024]', 'root', 'heb', 'נָבַח', '["nâbach"]', '["to bark (as a dog) bark."]', '["v"]', 'to bark (as a dog) bark.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5025}/[H5025]', 'lemma', 'heb', 'נֹבַח', '["Nôbach"]', '["Nobach, the name of an Israelite, and of a place East of the Jordan Nobah."]', '["n-pr-m n-pr-loc"]', 'Nobach, the name of an Israelite, and of a place East of the Jordan Nobah.', 'from 5024; a bark;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5027]', 'root', 'heb', 'נָבַט', '["nâbaṭ"]', '["to scan, i.e. look intently at; by implication, to regard with pleasure, favor or care (cause to) behold, consider, look (down), regard, have respect, see."]', '["v"]', 'to scan, i.e. look intently at; by implication, to regard with pleasure, favor or care (cause to) behold, consider, look (down), regard, have respect, see.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5028}/[H5028]', 'lemma', 'heb', 'נְבָט', '["Nᵉbâṭ"]', '["Nebat, the father of Jeroboam I Nebat."]', '["n-pr-m"]', 'Nebat, the father of Jeroboam I Nebat.', 'from 5027; regard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5029}/[H5029]', 'lemma', 'arc', 'נְבִיא', '["nᵉbîyʼ"]', '["a prophet prophet."]', '["n-m"]', 'a prophet prophet.', '(Aramaic) corresponding to 5030;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5030}/[H5030]', 'lemma', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["a prophet or (generally) inspired man prophecy, that prophesy, prophet."]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5031}/[H5031]', 'lemma', 'heb', 'נְבִיאָה', '["nᵉbîyʼâh"]', '["a prophetess or (generally) inspired woman; by implication, a poetess; by association a prophet''s wife prophetess."]', '["n-f"]', 'a prophetess or (generally) inspired woman; by implication, a poetess; by association a prophet''s wife prophetess.', 'feminine of 5030;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5032}/[H5032]', 'lemma', 'heb', 'נְבָיוֹת', '["Nᵉbâyôwth"]', '["Nebajoth, a son of Ismael, and the country settled by him Nebaioth, Nebajoth."]', '["n-pr-f"]', 'Nebajoth, a son of Ismael, and the country settled by him Nebaioth, Nebajoth.', 'or נְבָיֹת; feminine plural from 5107; fruitfulnesses;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5034]', 'root', 'heb', 'נָבֵל', '["nâbêl"]', '["to wilt; generally, to fall away, fail, faint; figuratively, to be foolish or (morally) wicked; causatively, to despise, disgrace disgrace, dishounour, lightly esteem, fade (away, -ing), fall (down, -ling, off), do foolishly, come to nought, × surely, make vile, wither."]', '["v"]', 'to wilt; generally, to fall away, fail, faint; figuratively, to be foolish or (morally) wicked; causatively, to despise, disgrace disgrace, dishounour, lightly esteem, fade (away, -ing), fall (down, -ling, off), do foolishly, come to nought, × surely, make vile, wither.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5035}/[H5035]', 'lemma', 'heb', 'נֶבֶל', '["nebel"]', '["a skin-bag for liquids (from collapsing when empty); hence, a vase (as similar in shape when full); also a lyre (as having a body of like form) bottle, pitcher, psaltery, vessel, viol."]', '["n-m"]', 'a skin-bag for liquids (from collapsing when empty); hence, a vase (as similar in shape when full); also a lyre (as having a body of like form) bottle, pitcher, psaltery, vessel, viol.', 'or נֵבֶל; from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5036}/[H5036]', 'lemma', 'heb', 'נָבָל', '["nâbâl"]', '["stupid; wicked (especially impious) fool(-ish, -ish man, -ish woman), vile person."]', '["a"]', 'stupid; wicked (especially impious) fool(-ish, -ish man, -ish woman), vile person.', 'from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5037}/[H5037]', 'lemma', 'heb', 'נָבָל', '["Nâbâl"]', '["Nabal, an Israelite Nabal."]', '["n-pr-m"]', 'Nabal, an Israelite Nabal.', 'the same as 5036; dolt;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5038}/[H5038]', 'lemma', 'heb', 'נְבֵלָה', '["nᵉbêlâh"]', '["a flabby thing, i.e. a carcase or carrion (human or bestial, often collectively); figuratively, an idol (dead) body, (dead) carcase, dead of itself, which died, (beast) that (which) dieth of itself."]', '["n-f"]', 'a flabby thing, i.e. a carcase or carrion (human or bestial, often collectively); figuratively, an idol (dead) body, (dead) carcase, dead of itself, which died, (beast) that (which) dieth of itself.', 'from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5039}/[H5039]', 'lemma', 'heb', 'נְבָלָה', '["nᵉbâlâh"]', '["foolishness, i.e. (morally) wickedness; concretely, a crime; by extension, punishment folly, vile, villany."]', '["n-f"]', 'foolishness, i.e. (morally) wickedness; concretely, a crime; by extension, punishment folly, vile, villany.', 'feminine of 5036;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5040}/[H5040]', 'lemma', 'heb', 'נַבְלוּת', '["nablûwth"]', '["properly, disgrace, i.e. the (female) pudenda lewdness."]', '["n-f"]', 'properly, disgrace, i.e. the (female) pudenda lewdness.', 'from 5036;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5041}/[H5041]', 'lemma', 'heb', 'נְבַלָּט', '["Nᵉballâṭ"]', '["Neballat, a place in Palestine Neballat."]', '["n-pr-loc"]', 'Neballat, a place in Palestine Neballat.', 'apparently from 5036 and 3909; foolish secrecy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5042]', 'root', 'heb', 'נָבַע', '["nâbaʻ"]', '["to gush forth; figuratively, to utter (good or bad words); specifically, to emit (a foul odor) belch out, flowing, pour out, send forth, utter (abundantly)."]', '["v"]', 'to gush forth; figuratively, to utter (good or bad words); specifically, to emit (a foul odor) belch out, flowing, pour out, send forth, utter (abundantly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5043>', 'opaque', 'arc', 'נֶבְרְשָׁא', '["nebrᵉshâʼ"]', '["a light; plural (collectively) a chandelier candlestick."]', '["n-f"]', 'a light; plural (collectively) a chandelier candlestick.', '(Aramaic) from an unused root meaning to shine;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5044>', 'opaque', 'heb', 'נִבְשָׁן', '["Nibshân"]', '["Nibshan, a place in Palestine Nibshan."]', '["n-pr-loc"]', 'Nibshan, a place in Palestine Nibshan.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5045>', 'opaque', 'heb', 'נֶגֶב', '["negeb"]', '["the south (from its drought); specifically, the Negeb or southern district of Judah, occasionally, Egypt (as south to Palestine) south (country, side, -ward)."]', '["n-m"]', 'the south (from its drought); specifically, the Negeb or southern district of Judah, occasionally, Egypt (as south to Palestine) south (country, side, -ward).', 'from an unused root meaning to be parched;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5046]', 'root', 'heb', 'נָגַד', '["nâgad"]', '["properly, to front, i.e. stand boldly out opposite; by implication (causatively), to manifest; figuratively, to announce (always by word of mouth to one present); specifically, to expose, predict, explain, praise bewray, × certainly, certify, declare(-ing), denounce, expound, × fully, messenger, plainly, profess, rehearse, report, shew (forth), speak, × surely, tell, utter."]', '["v"]', 'properly, to front, i.e. stand boldly out opposite; by implication (causatively), to manifest; figuratively, to announce (always by word of mouth to one present); specifically, to expose, predict, explain, praise bewray, × certainly, certify, declare(-ing), denounce, expound, × fully, messenger, plainly, profess, rehearse, report, shew (forth), speak, × surely, tell, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5047}/[H5047]', 'lemma', 'arc', 'נְגַד', '["nᵉgad"]', '["to flow (through the idea of clearing the way) issue."]', '["v"]', 'to flow (through the idea of clearing the way) issue.', '(Aramaic) corresponding to 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5048}/[H5048]', 'lemma', 'heb', 'נֶגֶד', '["neged"]', '["a front, i.e. part opposite; specifically a counterpart, or mate; usually (adverbial, especially with preposition) over against or before about, (over) against, × aloof, × far (off), × from, over, presence, × other side, sight, × to view."]', '["prep"]', 'a front, i.e. part opposite; specifically a counterpart, or mate; usually (adverbial, especially with preposition) over against or before about, (over) against, × aloof, × far (off), × from, over, presence, × other side, sight, × to view.', 'from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5049}/[H5049]', 'lemma', 'arc', 'נֶגֶד', '["neged"]', '["opposite toward."]', '["prep"]', 'opposite toward.', '(Aramaic) corresponding to 5048;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5050]', 'root', 'heb', 'נָגַהּ', '["nâgahh"]', '["to glitter; causatively, to illuminate (en-) lighten, (cause to) shine."]', '["v"]', 'to glitter; causatively, to illuminate (en-) lighten, (cause to) shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5051}/[H5051]', 'lemma', 'heb', 'נֹגַהּ', '["nôgahh"]', '["brilliancy (literally or figuratively) bright(-ness), light, (clear) shining."]', '["n-f"]', 'brilliancy (literally or figuratively) bright(-ness), light, (clear) shining.', 'from 5050;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5052}/[H5052]', 'lemma', 'heb', 'נֹגַהּ', '["Nôgahh"]', '["Nogah, a son of David Nogah."]', '["n-pr-m"]', 'Nogah, a son of David Nogah.', 'the same as 5051;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5053}/[H5053]', 'lemma', 'arc', 'נֹגַהּ', '["nôgahh"]', '["dawn morning."]', '["n-f"]', 'dawn morning.', '(Aramaic) corresponding to 5051;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5054}/[H5054]', 'lemma', 'heb', 'נְגֹהָה', '["nᵉgôhâh"]', '["splendor brightness."]', '["n-f"]', 'splendor brightness.', 'feminine of 5051;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5055]', 'root', 'heb', 'נָגַח', '["nâgach"]', '["to butt with the horns; figuratively, to war against gore, push (down, -ing)."]', '["v"]', 'to butt with the horns; figuratively, to war against gore, push (down, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5056}/[H5056]', 'lemma', 'heb', 'נַגָּח', '["naggâch"]', '["butting, i.e. vicious used (wont) to push."]', '["a"]', 'butting, i.e. vicious used (wont) to push.', 'from 5055;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5057}/[H5057]', 'lemma', 'heb', 'נָגִיד', '["nâgîyd"]', '["a commander (as occupying the front), civil, military or religious; generally (abstractly, plural), honorable themes captain, chief, excellent thing, (chief) governor, leader, noble, prince, (chief) ruler."]', '["n-m"]', 'a commander (as occupying the front), civil, military or religious; generally (abstractly, plural), honorable themes captain, chief, excellent thing, (chief) governor, leader, noble, prince, (chief) ruler.', 'or נָגִד; from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5058}/[H5058]', 'lemma', 'heb', 'נְגִינָה', '["nᵉgîynâh"]', '["properly, instrumental music; by implication, a stringed instrument; by extension, a poem set to music; specifically, an epigram stringed instrument, musick, Neginoth (plural), song."]', '["n-f"]', 'properly, instrumental music; by implication, a stringed instrument; by extension, a poem set to music; specifically, an epigram stringed instrument, musick, Neginoth (plural), song.', 'or נְגִינַת; (Psalm 61:title), from 5059;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5059]', 'root', 'heb', 'נָגַן', '["nâgan"]', '["properly, to thrum, i.e. beat a tune with the fingers; expectation. to play on a stringed instrument; hence (generally), to make music player on instruments, sing to the stringed instruments, melody, ministrel, play(-er, -ing)."]', '["v"]', 'properly, to thrum, i.e. beat a tune with the fingers; expectation. to play on a stringed instrument; hence (generally), to make music player on instruments, sing to the stringed instruments, melody, ministrel, play(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5060]', 'root', 'heb', 'נָגַע', '["nâgaʻ"]', '["properly, to touch, i.e. lay the hand upon (for any purpose; euphemistically, to lie with a woman); by implication, to reach (figuratively, to arrive, acquire); violently, to strike (punish, defeat, destroy, etc.) beat, (× be able to) bring (down), cast, come (nigh), draw near (nigh), get up, happen, join, near, plague, reach (up), smite, strike, touch."]', '["v"]', 'properly, to touch, i.e. lay the hand upon (for any purpose; euphemistically, to lie with a woman); by implication, to reach (figuratively, to arrive, acquire); violently, to strike (punish, defeat, destroy, etc.) beat, (× be able to) bring (down), cast, come (nigh), draw near (nigh), get up, happen, join, near, plague, reach (up), smite, strike, touch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5061}/[H5061]', 'lemma', 'heb', 'נֶגַע', '["negaʻ"]', '["a blow (figuratively, infliction); also (by implication) a spot (concretely, a leprous person or dress) plague, sore, stricken, stripe, stroke, wound."]', '["n-m"]', 'a blow (figuratively, infliction); also (by implication) a spot (concretely, a leprous person or dress) plague, sore, stricken, stripe, stroke, wound.', 'from 5060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5062]', 'root', 'heb', 'נָגַף', '["nâgaph"]', '["to push, gore, defeat, stub (the toe), inflict (a disease) beat, dash, hurt, plague, slay, smite (down), strike, stumble, × surely, put to the worse."]', '["v"]', 'to push, gore, defeat, stub (the toe), inflict (a disease) beat, dash, hurt, plague, slay, smite (down), strike, stumble, × surely, put to the worse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5063}/[H5063]', 'lemma', 'heb', 'נֶגֶף', '["negeph"]', '["a trip (of the foot); figuratively, an infliction (of disease) plague, stumbling."]', '["n-m"]', 'a trip (of the foot); figuratively, an infliction (of disease) plague, stumbling.', 'from 5062;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5064]', 'root', 'heb', 'נָגַר', '["nâgar"]', '["to flow; figuratively, to stretch out; causatively, to pour out or down; figuratively, to deliver over fall, flow away, pour down (out), run, shed, spilt, trickle down."]', '["v"]', 'to flow; figuratively, to stretch out; causatively, to pour out or down; figuratively, to deliver over fall, flow away, pour down (out), run, shed, spilt, trickle down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5065]', 'root', 'heb', 'נָגַשׂ', '["nâgas"]', '["to drive (an animal, a workman, a debtor, an army); by implication, to tax, harass, tyrannize distress, driver, exact(-or), oppress(-or), × raiser of taxes, taskmaster."]', '["v"]', 'to drive (an animal, a workman, a debtor, an army); by implication, to tax, harass, tyrannize distress, driver, exact(-or), oppress(-or), × raiser of taxes, taskmaster.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5066]', 'root', 'heb', 'נָגַשׁ', '["nâgash"]', '["to be or come (causatively, bring) near (for any purpose); euphemistically, to lie with a woman; as an enemy, to attack; religious to worship; causatively, to present; figuratively, to adduce an argument; by reversal, to stand back (make to) approach (nigh), bring (forth, hither, near), (cause to) come (hither, near, nigh), give place, go hard (up), (be, draw, go) near (nigh), offer, overtake, present, put, stand."]', '["v"]', 'to be or come (causatively, bring) near (for any purpose); euphemistically, to lie with a woman; as an enemy, to attack; religious to worship; causatively, to present; figuratively, to adduce an argument; by reversal, to stand back (make to) approach (nigh), bring (forth, hither, near), (cause to) come (hither, near, nigh), give place, go hard (up), (be, draw, go) near (nigh), offer, overtake, present, put, stand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5067}/[H5067]', 'lemma', 'heb', 'נֵד', '["nêd"]', '["a mound, i.e. wave heap."]', '["n-m"]', 'a mound, i.e. wave heap.', 'from 5110 in the sense of piling up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5068]', 'root', 'heb', 'נָדַב', '["nâdab"]', '["to impel; hence, to volunteer (as a soldier), to present spontaneously offer freely, be (give, make, offer self) willing(-ly)."]', '["v"]', 'to impel; hence, to volunteer (as a soldier), to present spontaneously offer freely, be (give, make, offer self) willing(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5069}/[H5069]', 'lemma', 'arc', 'נְדַב', '["nᵉdab"]', '["be (or give) liberal(-ly) (be minded of...own) freewill (offering), offer freely (willingly)."]', '["v"]', 'be (or give) liberal(-ly) (be minded of...own) freewill (offering), offer freely (willingly).', '(Aramaic) corresponding to 5068;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5070}/[H5070]', 'lemma', 'heb', 'נָדָב', '["Nâdâb"]', '["Nadab, the name of four Israelites Nadab."]', '["n-pr-m"]', 'Nadab, the name of four Israelites Nadab.', 'from 5068; liberal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5071}/[H5071]', 'lemma', 'heb', 'נְדָבָה', '["nᵉdâbâh"]', '["properly (abstractly) spontaneity, or (adjectively) spontaneous; also (concretely) a spontaneous or (by inference, in plural) abundant gift free(-will) offering, freely, plentiful, voluntary(-ily, offering), willing(-ly), offering)."]', '["n-f"]', 'properly (abstractly) spontaneity, or (adjectively) spontaneous; also (concretely) a spontaneous or (by inference, in plural) abundant gift free(-will) offering, freely, plentiful, voluntary(-ily, offering), willing(-ly), offering).', 'from 5068;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5072}/[H5072]', 'lemma', 'heb', 'נְדַבְיָה', '["Nᵉdabyâh"]', '["Nedabjah, an Israelite Nedabiah."]', '["n-pr-m"]', 'Nedabjah, an Israelite Nedabiah.', 'from 5068 and 3050; largess of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5074]', 'root', 'heb', 'נָדַד', '["nâdad"]', '["properly, to wave to and fro (rarely to flap up and down); figuratively, to rove, flee, or (causatively) to drive away chase (away), × could not, depart, flee (× apace, away), (re-) move, thrust away, wander (abroad, -er, -ing)."]', '["v"]', 'properly, to wave to and fro (rarely to flap up and down); figuratively, to rove, flee, or (causatively) to drive away chase (away), × could not, depart, flee (× apace, away), (re-) move, thrust away, wander (abroad, -er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5075}/[H5075]', 'lemma', 'arc', 'נְדַד', '["nᵉdad"]', '["to depart go from."]', '["v"]', 'to depart go from.', '(Aramaic) corresponding to 5074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5076}/[H5076]', 'lemma', 'heb', 'נָדֻד', '["nâdud"]', '["properly, tossed; abstractly, a rolling (on the bed) tossing to and fro."]', '["n-m"]', 'properly, tossed; abstractly, a rolling (on the bed) tossing to and fro.', 'passive participle of 5074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5077]', 'root', 'heb', 'נָדָה', '["nâdâh"]', '["properly, to toss; figuratively, to exclude, i.e. banish, postpone, prohibit cast out, drive, put far away."]', '["v"]', 'properly, to toss; figuratively, to exclude, i.e. banish, postpone, prohibit cast out, drive, put far away.', 'or נָדָא; (2 Kings 17:21), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5078}/[H5078]', 'lemma', 'heb', 'נֵדֶה', '["nêdeh"]', '["a bounty (for prostitution) gifts."]', '["n-m"]', 'a bounty (for prostitution) gifts.', 'from 5077 in the sense of freely flinging money;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5079}/[H5079]', 'lemma', 'heb', 'נִדָּה', '["niddâh"]', '["properly, rejection; by implication, impurity, especially personal (menstruation) or moral (idolatry, incest) × far, filthiness, × flowers, menstruous (woman), put apart, × removed (woman), separation, set apart, unclean(-ness, thing, with filthiness)."]', '["n-f"]', 'properly, rejection; by implication, impurity, especially personal (menstruation) or moral (idolatry, incest) × far, filthiness, × flowers, menstruous (woman), put apart, × removed (woman), separation, set apart, unclean(-ness, thing, with filthiness).', 'from 5074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5080]', 'root', 'heb', 'נָדַח', '["nâdach"]', '["to push off; used in a great variety of applications, literally and figuratively (to expel, mislead, strike, inflict, etc.) banish, bring, cast down (out), chase, compel, draw away, drive (away, out, quite), fetch a stroke, force, go away, outcast, thrust away (out), withdraw."]', '["v"]', 'to push off; used in a great variety of applications, literally and figuratively (to expel, mislead, strike, inflict, etc.) banish, bring, cast down (out), chase, compel, draw away, drive (away, out, quite), fetch a stroke, force, go away, outcast, thrust away (out), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5081}/[H5081]', 'lemma', 'heb', 'נָדִיב', '["nâdîyb"]', '["properly, voluntary, i.e. generous; hence, magnanimous; as noun, a grandee (sometimes a tyrant) free, liberal (things), noble, prince, willing (hearted)."]', '["a"]', 'properly, voluntary, i.e. generous; hence, magnanimous; as noun, a grandee (sometimes a tyrant) free, liberal (things), noble, prince, willing (hearted).', 'from 5068;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5082}/[H5082]', 'lemma', 'heb', 'נְדִיבָה', '["nᵉdîybâh"]', '["properly, nobility, i.e. reputation soul."]', '["n-f"]', 'properly, nobility, i.e. reputation soul.', 'feminine of 5081;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5083>', 'opaque', 'heb', 'נָדָן', '["nâdân"]', '["a present (for prostitution) gift."]', '["n-m"]', 'a present (for prostitution) gift.', 'probably from an unused root meaning to give;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5084>', 'opaque', 'heb', 'נָדָן', '["nâdân"]', '["a sheath (of a sword) sheath."]', '["n-m"]', 'a sheath (of a sword) sheath.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5085}/[H5085]', 'lemma', 'arc', 'נִדְנֶה', '["nidneh"]', '["a sheath; figuratively, the body (as the receptacle of the soul) body."]', '["n-m"]', 'a sheath; figuratively, the body (as the receptacle of the soul) body.', '(Aramaic) from the same as 5084;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5086]', 'root', 'heb', 'נָדַף', '["nâdaph"]', '["to shove asunder, i.e. disperse drive (away, to and fro), thrust down, shaken, tossed to and fro."]', '["v"]', 'to shove asunder, i.e. disperse drive (away, to and fro), thrust down, shaken, tossed to and fro.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5087]', 'root', 'heb', 'נָדַר', '["nâdar"]', '["to promise (pos., to do or give something to God) (make a) vow."]', '["v"]', 'to promise (pos., to do or give something to God) (make a) vow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5088}/[H5088]', 'lemma', 'heb', 'נֶדֶר', '["neder"]', '["a promise (to God); also (concretely) a thing promised vow(-ed)."]', '["n-m"]', 'a promise (to God); also (concretely) a thing promised vow(-ed).', 'or נֵדֶר; from 5087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5090]', 'root', 'heb', 'נָהַג', '["nâhag"]', '["to drive forth (a person, an animal or chariot), i.e. lead, carry away; reflexively, to proceed (i.e. impel or guide oneself); also (from the panting induced by effort), to sigh acquaint, bring (away), carry away, drive (away), lead (away, forth), (be) guide, lead (away, forth)."]', '["v"]', 'to drive forth (a person, an animal or chariot), i.e. lead, carry away; reflexively, to proceed (i.e. impel or guide oneself); also (from the panting induced by effort), to sigh acquaint, bring (away), carry away, drive (away), lead (away, forth), (be) guide, lead (away, forth).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5091]', 'root', 'heb', 'נָהָה', '["nâhâh"]', '["to groan, i.e. bewail; hence (through the idea of crying aloud), to assemble (as if on proclamation) lament, wail."]', '["v"]', 'to groan, i.e. bewail; hence (through the idea of crying aloud), to assemble (as if on proclamation) lament, wail.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5092}/[H5092]', 'lemma', 'heb', 'נְהִי', '["nᵉhîy"]', '["an elegy lamentation, wailing."]', '["n-m"]', 'an elegy lamentation, wailing.', 'from 5091;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5093}/[H5093]', 'lemma', 'heb', 'נִהְיָה', '["nihyâh"]', '["lamentation doleful."]', '["n-f"]', 'lamentation doleful.', 'feminine of 5092;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5094}/[H5094]', 'lemma', 'arc', 'נְהִיר', '["nᵉhîyr"]', '["illumination, i.e. (figuratively) wisdom light."]', '["n-m"]', 'illumination, i.e. (figuratively) wisdom light.', '(Aramaic) or נְהִירוּ; (Aramaic), from the same as 5105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5095]', 'root', 'heb', 'נָהַל', '["nâhal"]', '["properly, to run with a sparkle, i.e. flow; hence (transitively), to conduct, and (by inference) to protect, sustain carry, feed, guide, lead (gently, on)."]', '["v"]', 'properly, to run with a sparkle, i.e. flow; hence (transitively), to conduct, and (by inference) to protect, sustain carry, feed, guide, lead (gently, on).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5096}/[H5096]', 'lemma', 'heb', 'נַהֲלָל', '["Nahălâl"]', '["Nahalal or Nahalol, a place in Palestine Nahalal, Nahallal, Nahalol."]', '["n-pr-loc"]', 'Nahalal or Nahalol, a place in Palestine Nahalal, Nahallal, Nahalol.', 'or נַהֲלֹל; the same as 5097;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5097}/[H5097]', 'lemma', 'heb', 'נַהֲלֹל', '["nahălôl"]', '["pasture bush."]', '["n-m"]', 'pasture bush.', 'from 5095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5098]', 'root', 'heb', 'נָהַם', '["nâham"]', '["to growl mourn, roar(-ing)."]', '["v"]', 'to growl mourn, roar(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5099}/[H5099]', 'lemma', 'heb', 'נַהַם', '["naham"]', '["a snarl roaring."]', '["n-m"]', 'a snarl roaring.', 'from 5098;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5100}/[H5100]', 'lemma', 'heb', 'נְהָמָה', '["nᵉhâmâh"]', '["snarling disquietness, roaring."]', '["n-f"]', 'snarling disquietness, roaring.', 'feminine of 5099;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5101]', 'root', 'heb', 'נָהַק', '["nâhaq"]', '["to bray (as an ass), scream (from hunger) bray."]', '["v"]', 'to bray (as an ass), scream (from hunger) bray.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5102]', 'root', 'heb', 'נָהַר', '["nâhar"]', '["to sparkle, i.e. (figuratively) be cheerful; hence (from the sheen of a running stream) to flow, i.e. (figuratively) assemble flow (together), be lightened."]', '["v"]', 'to sparkle, i.e. (figuratively) be cheerful; hence (from the sheen of a running stream) to flow, i.e. (figuratively) assemble flow (together), be lightened.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5103}/[H5103]', 'lemma', 'arc', 'נְהַר', '["nᵉhar"]', '["a river, especially the Euphrates river, stream."]', '["n-m"]', 'a river, especially the Euphrates river, stream.', '(Aramaic) from a root corresponding to 5102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5104}/[H5104]', 'lemma', 'heb', 'נָהָר', '["nâhâr"]', '["a stream (including the sea; expectation the Nile, Euphrates, etc.); figuratively, prosperity flood, river."]', '["n-m"]', 'a stream (including the sea; expectation the Nile, Euphrates, etc.); figuratively, prosperity flood, river.', 'from 5102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5105}/[H5105]', 'lemma', 'heb', 'נְהָרָה', '["nᵉhârâh"]', '["daylight light."]', '["n-f"]', 'daylight light.', 'from 5102 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5106]', 'root', 'heb', 'נוּא', '["nûwʼ"]', '["to refuse, forbid, dissuade, or neutralize break, disallow, discourage, make of none effect."]', '["v"]', 'to refuse, forbid, dissuade, or neutralize break, disallow, discourage, make of none effect.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5107]', 'root', 'heb', 'נוּב', '["nûwb"]', '["to germinate, i.e. (figuratively) to (causatively, make) flourish; also (of words), to utter bring forth (fruit), make cheerful, increase."]', '["v"]', 'to germinate, i.e. (figuratively) to (causatively, make) flourish; also (of words), to utter bring forth (fruit), make cheerful, increase.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5108}/[H5108]', 'lemma', 'heb', 'נוֹב', '["nôwb"]', '["produce, literally or figuratively fruit."]', '["n-m"]', 'produce, literally or figuratively fruit.', 'or נֵיב; from 5107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5109}/[H5109]', 'lemma', 'heb', 'נוֹבַי', '["Nôwbay"]', '["Nobai, an Israelite Nebai (from the margin)."]', '["n-pr-m"]', 'Nobai, an Israelite Nebai (from the margin).', 'from 5108; fruitful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5110]', 'root', 'heb', 'נוּד', '["nûwd"]', '["to nod, i.e. waver; figuratively, to wander, flee, disappear; also (from shaking the head in sympathy), to console, deplore, or (from tossing the head in scorn) taunt bemoan, flee, get, mourn, make to move, take pity, remove, shake, skip for joy, be sorry, vagabond, way, wandering."]', '["v"]', 'to nod, i.e. waver; figuratively, to wander, flee, disappear; also (from shaking the head in sympathy), to console, deplore, or (from tossing the head in scorn) taunt bemoan, flee, get, mourn, make to move, take pity, remove, shake, skip for joy, be sorry, vagabond, way, wandering.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5111}/[H5111]', 'lemma', 'arc', 'נוּד', '["nûwd"]', '["to flee get away."]', '["v"]', 'to flee get away.', '(Aramaic) corresponding to 5116;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5112}/[H5112]', 'lemma', 'heb', 'נוֹד', '["nôwd"]', '["exile wandering."]', '["n-m"]', 'exile wandering.', '(only defective נֹד ); from 5110;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5113}/[H5113]', 'lemma', 'heb', 'נוֹד', '["Nôwd"]', '["Nod, the land of Cain Nod."]', '["n-pr-loc"]', 'Nod, the land of Cain Nod.', 'the same as 5112; vagrancy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5114}/[H5114]', 'lemma', 'heb', 'נוֹדָב', '["Nôwdâb"]', '["Nodab, an Arab tribe Nodab."]', '["n-pr-m"]', 'Nodab, an Arab tribe Nodab.', 'from 5068; noble;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5115]', 'root', 'heb', 'נָוָה', '["nâvâh"]', '["to rest (as at home); causatively (through the implied idea of beauty), to celebrate (with praises) keep at home, prepare an habitation."]', '["v"]', 'to rest (as at home); causatively (through the implied idea of beauty), to celebrate (with praises) keep at home, prepare an habitation.', 'a primitive root; (compare 5116)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5116}/[H5116]', 'lemma', 'heb', 'נָוֶה', '["nâveh"]', '["(adjectively) at home; hence (by implication of satisfaction) lovely; also (noun) a home, of God (temple), men (residence), flocks (pasture), or wild animals (den) comely, dwelling (place), fold, habitation, pleasant place, sheepcote, stable, tarried."]', '["n"]', '(adjectively) at home; hence (by implication of satisfaction) lovely; also (noun) a home, of God (temple), men (residence), flocks (pasture), or wild animals (den) comely, dwelling (place), fold, habitation, pleasant place, sheepcote, stable, tarried.', 'or (feminine) נָוָה; from 5115;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5117]', 'root', 'heb', 'נוּחַ', '["nûwach"]', '["to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241."]', '["v"]', 'to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5118}/[H5118]', 'lemma', 'heb', 'נוּחַ', '["nûwach"]', '["quiet rest(-ed, -ing place)."]', '["n-m"]', 'quiet rest(-ed, -ing place).', 'or נוֹחַ; from 5117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5119}/[H5119]', 'lemma', 'heb', 'נוֹחָה', '["Nôwchâh"]', '["Nochah, an Israelite Nohah."]', '["n-pr-f"]', 'Nochah, an Israelite Nohah.', 'feminine of 5118; quietude;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5121}/[H5121]', 'lemma', 'heb', 'נָוִית', '["Nâvîyth"]', '["Navith, a place in Palestine Naioth (from the margin)."]', '["n-pr-loc"]', 'Navith, a place in Palestine Naioth (from the margin).', 'from 5115; residence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5123]', 'root', 'heb', 'נוּם', '["nûwm"]', '["to slumber (from drowsiness) sleep, slumber."]', '["v"]', 'to slumber (from drowsiness) sleep, slumber.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5124}/[H5124]', 'lemma', 'heb', 'נוּמָה', '["nûwmâh"]', '["sleepiness drowsiness."]', '["n-f"]', 'sleepiness drowsiness.', 'from 5123;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5125]', 'root', 'heb', 'נוּן', '["nûwn"]', '["to resprout, i.e. propagate by shoots; figuratively, to be perpetual be continued."]', '["v"]', 'to resprout, i.e. propagate by shoots; figuratively, to be perpetual be continued.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5126}/[H5126]', 'lemma', 'heb', 'נוּן', '["Nûwn"]', '["Nun or Non, the father of Joshua Non, Nun."]', '["n-pr-m"]', 'Nun or Non, the father of Joshua Non, Nun.', 'or נוֹן; (1 Chronicles 7:27), from 5125; perpetuity,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5127]', 'root', 'heb', 'נוּס', '["nûwç"]', '["to flit, i.e. vanish away (subside, escape; causatively, chase, impel, deliver) × abate, away, be displayed, (make to) flee (away, -ing), put to flight, × hide, lift up a standard."]', '["v"]', 'to flit, i.e. vanish away (subside, escape; causatively, chase, impel, deliver) × abate, away, be displayed, (make to) flee (away, -ing), put to flight, × hide, lift up a standard.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5128]', 'root', 'heb', 'נוּעַ', '["nûwaʻ"]', '["to waver, in a great variety of applications, literally and figuratively (as subjoined) continually, fugitive, × make, to (go) up and down, be gone away, (be) move(-able, -d), be promoted, reel, remove, scatter, set, shake, sift, stagger, to and fro, be vagabond, wag, (make) wander (up and down)."]', '["v"]', 'to waver, in a great variety of applications, literally and figuratively (as subjoined) continually, fugitive, × make, to (go) up and down, be gone away, (be) move(-able, -d), be promoted, reel, remove, scatter, set, shake, sift, stagger, to and fro, be vagabond, wag, (make) wander (up and down).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5129}/[H5129]', 'lemma', 'heb', 'נוֹעַדְיָה', '["Nôwʻadyâh"]', '["Noadjah, the name of an Israelite, and a false prophetess Noadiah."]', '["n-pr-m n-pr-f"]', 'Noadjah, the name of an Israelite, and a false prophetess Noadiah.', 'from 3259 and 3050; convened of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5130]', 'root', 'heb', 'נוּף', '["nûwph"]', '["to quiver (i.e. vibrate up and down, or rock to and fro); used in a great variety of applications (including sprinkling, beckoning, rubbing, bastinadoing, sawing, waving, etc.) lift up, move, offer, perfume, send, shake, sift, strike, wave."]', '["v"]', 'to quiver (i.e. vibrate up and down, or rock to and fro); used in a great variety of applications (including sprinkling, beckoning, rubbing, bastinadoing, sawing, waving, etc.) lift up, move, offer, perfume, send, shake, sift, strike, wave.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5131}/[H5131]', 'lemma', 'heb', 'נוֹף', '["nôwph"]', '["elevation situation. Compare 5297."]', '["n-m"]', 'elevation situation. Compare 5297.', 'from 5130;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5132]', 'root', 'heb', 'נוּץ', '["nûwts"]', '["properly, to flash; also, to fly away (from the quickness of motion) flee away, bud (forth)."]', '["v"]', 'properly, to flash; also, to fly away (from the quickness of motion) flee away, bud (forth).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5133}/[H5133]', 'lemma', 'heb', 'נוֹצָה', '["nôwtsâh"]', '["a pinion (or wing feather); often (collectively) plumage feather(-s), ostrich."]', '["n-f"]', 'a pinion (or wing feather); often (collectively) plumage feather(-s), ostrich.', 'or נֹצָה; feminine active participle of 5327 in the sense of flying;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5134]', 'root', 'heb', 'נוּק', '["nûwq"]', '["to suckle nurse."]', '["v"]', 'to suckle nurse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5136]', 'root', 'heb', 'נוּשׁ', '["nûwsh"]', '["to be sick, i.e. (figuratively) distressed be full of heaviness."]', '["v"]', 'to be sick, i.e. (figuratively) distressed be full of heaviness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5137]', 'root', 'heb', 'נָזָה', '["nâzâh"]', '["to spirt, i.e. besprinkle (especially in expiation) sprinkle."]', '["v"]', 'to spirt, i.e. besprinkle (especially in expiation) sprinkle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5138}/[H5138]', 'lemma', 'heb', 'נָזִיד', '["nâzîyd"]', '["something boiled, i.e. soup pottage."]', '["n-m"]', 'something boiled, i.e. soup pottage.', 'from 2102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5139}/[H5139]', 'lemma', 'heb', 'נָזִיר', '["nâzîyr"]', '["separate, i.e. consecrated (as prince, a Nazirite); hence (figuratively from the latter) an unpruned vine (like an unshorn Nazirite) Nazarite (by a false alliteration with Nazareth), separate(-d), vine undressed."]', '["n-m"]', 'separate, i.e. consecrated (as prince, a Nazirite); hence (figuratively from the latter) an unpruned vine (like an unshorn Nazirite) Nazarite (by a false alliteration with Nazareth), separate(-d), vine undressed.', 'or נָזִר; from 5144;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5140]', 'root', 'heb', 'נָזַל', '["nâzal"]', '["to drip, or shed by trickling distil, drop, flood, (cause to) flow(-ing), gush out, melt, pour (down), running water, stream."]', '["v"]', 'to drip, or shed by trickling distil, drop, flood, (cause to) flow(-ing), gush out, melt, pour (down), running water, stream.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5142}/[H5142]', 'lemma', 'arc', 'נְזַק', '["nᵉzaq"]', '["to suffer (causatively, inflict) loss have (en-) damage, hurt(-ful)."]', '["v"]', 'to suffer (causatively, inflict) loss have (en-) damage, hurt(-ful).', '(Aramaic) corresponding to the root of 5143;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5143>', 'opaque', 'heb', 'נֵזֶק', '["nêzeq"]', '["loss damage."]', '["n-m"]', 'loss damage.', 'from an unused root meaning to injure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5144]', 'root', 'heb', 'נָזַר', '["nâzar"]', '["to hold aloof, i.e. (intransitivey) abstain (from food and drink, from impurity, and even from divine worship (i.e. apostatize)); specifically, to set apart (to sacred purposes), i.e. devote consecrate, separate(-ing, self)."]', '["v"]', 'to hold aloof, i.e. (intransitivey) abstain (from food and drink, from impurity, and even from divine worship (i.e. apostatize)); specifically, to set apart (to sacred purposes), i.e. devote consecrate, separate(-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5145}/[H5145]', 'lemma', 'heb', 'נֶזֶר', '["nezer"]', '["properly, something set apart, i.e. (abstractly) dedication (of a priet or Nazirite); hence (concretely) unshorn locks; also (by implication) a chaplet (especially of royalty) consecration, crown, hair, separation."]', '["n-m"]', 'properly, something set apart, i.e. (abstractly) dedication (of a priet or Nazirite); hence (concretely) unshorn locks; also (by implication) a chaplet (especially of royalty) consecration, crown, hair, separation.', 'or נֵזֶר; from 5144;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5146}/[H5146]', 'lemma', 'heb', 'נֹחַ', '["Nôach"]', '["Noach, the patriarch of the flood Noah."]', '["n-pr-m"]', 'Noach, the patriarch of the flood Noah.', 'the same as 5118; rest;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5147}/[H5147]', 'lemma', 'heb', 'נַחְבִּי', '["Nachbîy"]', '["Nachbi, an Israelite Nakbi."]', '["n-pr-m"]', 'Nachbi, an Israelite Nakbi.', 'from 2247; occult;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5148]', 'root', 'heb', 'נָחָה', '["nâchâh"]', '["to guide; by implication, to transport (into exile, or as colonists) bestow, bring, govern, guide, lead (forth), put, straiten."]', '["v"]', 'to guide; by implication, to transport (into exile, or as colonists) bestow, bring, govern, guide, lead (forth), put, straiten.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5149}/[H5149]', 'lemma', 'heb', 'נְחוּם', '["Nᵉchûwm"]', '["Nechum, an Israelite Nehum."]', '["n-pr-m"]', 'Nechum, an Israelite Nehum.', 'from 5162; comforted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5150}/[H5150]', 'lemma', 'heb', 'נִחוּם', '["nichûwm"]', '["properly, consoled; abstractly, solace comfort(-able), repenting."]', '["n-m"]', 'properly, consoled; abstractly, solace comfort(-able), repenting.', 'or נִחֻם; from 5162;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5151}/[H5151]', 'lemma', 'heb', 'נַחוּם', '["Nachûwm"]', '["Nachum, an Israelite prophet Nahum."]', '["n-pr-m"]', 'Nachum, an Israelite prophet Nahum.', 'from 5162; comfortable;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5152}/[H5152]', 'lemma', 'heb', 'נָחוֹר', '["Nâchôwr"]', '["Nachor, the name of the grandfather and a brother of Abraham Nahor."]', '["n-pr-m"]', 'Nachor, the name of the grandfather and a brother of Abraham Nahor.', 'from the same as 5170; snorer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5153}/[H5153]', 'lemma', 'heb', 'נָחוּשׁ', '["nâchûwsh"]', '["coppery, i.e. (figuratively) hard of brass."]', '["a"]', 'coppery, i.e. (figuratively) hard of brass.', 'apparently passive participle of 5172 (perhaps in the sense of ringing), i.e. bell-metal; or from the red color of the throat of a serpent (5175, as denominative) when hissing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5154}/[H5154]', 'lemma', 'heb', 'נְחוּשָׁה', '["nᵉchûwshâh"]', '["copper brass, steel. Compare 5176."]', '["n-f"]', 'copper brass, steel. Compare 5176.', 'or נְחֻשָׁה; feminine of 5153;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5155}/[H5155]', 'lemma', 'heb', 'נְחִילָה', '["nᵉchîylâh"]', '["a flute (plural) Nehiloth."]', '["n-f"]', 'a flute (plural) Nehiloth.', 'probably denominative from 2485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5156}/[H5156]', 'lemma', 'heb', 'נְחִיר', '["nᵉchîyr"]', '["a nostril (dual) nostrils."]', '["n-m"]', 'a nostril (dual) nostrils.', 'from the same as 5170;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5157]', 'root', 'heb', 'נָחַל', '["nâchal"]', '["to inherit (as a (figurative) mode of descent), or (generally) to occupy; causatively, to bequeath, or (generally) distribute, instate divide, have (inheritance), take as a heritage, (cause to, give to, make to) inherit, (distribute for, divide (for, for an, by), give for, have, leave for, take (for)) inheritance, (have in, cause to, be made to) possess(-ion)."]', '["v"]', 'to inherit (as a (figurative) mode of descent), or (generally) to occupy; causatively, to bequeath, or (generally) distribute, instate divide, have (inheritance), take as a heritage, (cause to, give to, make to) inherit, (distribute for, divide (for, for an, by), give for, have, leave for, take (for)) inheritance, (have in, cause to, be made to) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5158}/[H5158]', 'lemma', 'heb', 'נַחַל', '["nachal"]', '["a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley."]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5159}/[H5159]', 'lemma', 'heb', 'נַחֲלָה', '["nachălâh"]', '["properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158."]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5160}/[H5160]', 'lemma', 'heb', 'נַחֲלִיאֵל', '["Nachălîyʼêl"]', '["Nachaliël, a place in the Desert Nahaliel."]', '["n-pr-loc"]', 'Nachaliël, a place in the Desert Nahaliel.', 'from 5158 and 410; valley of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5161}/[H5161]', 'lemma', 'heb', 'נֶחֱלָמִי', '["Nechĕlâmîy"]', '["a Nechelamite, or descendant of Nechlam Nehelamite."]', '["a"]', 'a Nechelamite, or descendant of Nechlam Nehelamite.', 'apparently a patronymic from an unused name (apparently passive participle of 2492); dreamed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5162]', 'root', 'heb', 'נָחַם', '["nâcham"]', '["properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self)."]', '["v"]', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5163}/[H5163]', 'lemma', 'heb', 'נַחַם', '["Nacham"]', '["Nacham, an Israelite Naham."]', '["n-pr-m"]', 'Nacham, an Israelite Naham.', 'from 5162; consolation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5164}/[H5164]', 'lemma', 'heb', 'נֹחַם', '["nôcham"]', '["ruefulness, i.e. desistance repentance."]', '["n-m"]', 'ruefulness, i.e. desistance repentance.', 'from 5162;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5165}/[H5165]', 'lemma', 'heb', 'נֶחָמָה', '["nechâmâh"]', '["consolation comfort."]', '["n-f"]', 'consolation comfort.', 'from 5162;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5166}/[H5166]', 'lemma', 'heb', 'נְחֶמְיָה', '["Nᵉchemyâh"]', '["Nechemjah, the name of three Israelites Nehemiah."]', '["n-pr-m"]', 'Nechemjah, the name of three Israelites Nehemiah.', 'from 5162 and 3050; consolation of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5167}/[H5167]', 'lemma', 'heb', 'נַחֲמָנִי', '["Nachămânîy"]', '["Nachamani, an Israelite Nahamani."]', '["n-pr-m"]', 'Nachamani, an Israelite Nahamani.', 'from 5162; consolatory;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5168}/[H5168]', 'lemma', 'heb', 'נַחְנוּ', '["nachnûw"]', '["we we."]', '["p"]', 'we we.', 'for 587;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5169]', 'root', 'heb', 'נָחַץ', '["nâchats"]', '["to be urgent require haste."]', '["v"]', 'to be urgent require haste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5170>', 'opaque', 'heb', 'נַחַר', '["nachar"]', '["a snorting nostrils, snorting."]', '["n-m"]', 'a snorting nostrils, snorting.', 'and (feminine) נַחֲרָה; from an unused root meaning to snort or snore;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5171}/[H5171]', 'lemma', 'heb', 'נַחֲרַי', '["Nachăray"]', '["Nacharai or Nachrai, an Israelite Naharai, Nahari."]', '["n-pr-m"]', 'Nacharai or Nachrai, an Israelite Naharai, Nahari.', 'or נַחְרַי; from the same as 5170; snorer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5172]', 'root', 'heb', 'נָחַשׁ', '["nâchash"]', '["properly, to hiss, i.e. whisper a (magic) spell; generally, to prognosticate × certainly, divine, enchanter, (use) × enchantment, learn by experience, × indeed, diligently observe."]', '["v"]', 'properly, to hiss, i.e. whisper a (magic) spell; generally, to prognosticate × certainly, divine, enchanter, (use) × enchantment, learn by experience, × indeed, diligently observe.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5173}/[H5173]', 'lemma', 'heb', 'נַחַשׁ', '["nachash"]', '["an incantation or augury enchantment."]', '["n-m"]', 'an incantation or augury enchantment.', 'from 5172;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5174}/[H5174]', 'lemma', 'arc', 'נְחָשׁ', '["nᵉchâsh"]', '["copper brass."]', '["n-m"]', 'copper brass.', '(Aramaic) corresponding to 5154;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5175}/[H5175]', 'lemma', 'heb', 'נָחָשׁ', '["nâchâsh"]', '["a snake (from its hiss) serpent."]', '["n-m"]', 'a snake (from its hiss) serpent.', 'from 5172;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5176}/[H5176]', 'lemma', 'heb', 'נָחָשׁ', '["Nâchâsh"]', '["Nachash, the name of two persons apparently non-Israelite Nahash."]', '["n-pr-m"]', 'Nachash, the name of two persons apparently non-Israelite Nahash.', 'the same as 5175;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5177}/[H5177]', 'lemma', 'heb', 'נַחְשׁוֹן', '["Nachshôwn"]', '["Nachshon, an Israelite Naashon, Nahshon."]', '["n-pr-m"]', 'Nachshon, an Israelite Naashon, Nahshon.', 'from 5172; enchanter;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5178}/[H5178]', 'lemma', 'heb', 'נְחֹשֶׁת', '["nᵉchôsheth"]', '["copper, hence, something made of that metal, i.e. coin, a fetter; figuratively, base (as compared with gold or silver) brasen, brass, chain, copper, fetter (of brass), filthiness, steel."]', '["n-m"]', 'copper, hence, something made of that metal, i.e. coin, a fetter; figuratively, base (as compared with gold or silver) brasen, brass, chain, copper, fetter (of brass), filthiness, steel.', 'for 5154;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5179}/[H5179]', 'lemma', 'heb', 'נְחֻשְׁתָּא', '["Nᵉchushtâʼ"]', '["Nechushta, an Israelitess Nehushta."]', '["n-pr-f"]', 'Nechushta, an Israelitess Nehushta.', 'from 5178; copper;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5180}/[H5180]', 'lemma', 'heb', 'נְחֻשְׁתָּן', '["Nᵉchushtân"]', '["something made of copper, i.e. the copper serpent of the Desert Nehushtan."]', '["n"]', 'something made of copper, i.e. the copper serpent of the Desert Nehushtan.', 'from 5178;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5181]', 'root', 'heb', 'נָחַת', '["nâchath"]', '["to sink, i.e. descend; causatively, to press or lead down be broken, (cause to) come down, enter, go down, press sore, settle, stick fast."]', '["v"]', 'to sink, i.e. descend; causatively, to press or lead down be broken, (cause to) come down, enter, go down, press sore, settle, stick fast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5182}/[H5182]', 'lemma', 'arc', 'נְחַת', '["nᵉchath"]', '["to descend; causatively, to bring away, deposit, depose carry, come down, depose, lay up, place."]', '["v"]', 'to descend; causatively, to bring away, deposit, depose carry, come down, depose, lay up, place.', '(Aramaic) corresponding to 5181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5183}/[H5183]', 'lemma', 'heb', 'נַחַת', '["Nachath"]', '["a descent, i.e. imposition, unfavorable (punishment) or favorable (food); restfulness lighting down, quiet(-ness), to rest, be set on."]', '["n"]', 'a descent, i.e. imposition, unfavorable (punishment) or favorable (food); restfulness lighting down, quiet(-ness), to rest, be set on.', 'from 5182; also (intransitively; perhaps from 5117)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5184}/[H5184]', 'lemma', 'heb', 'נַחַת', '["Nachath"]', '["Nachath, the name of an Edomite and of two Israelites Nahath."]', '["n-pr-m"]', 'Nachath, the name of an Edomite and of two Israelites Nahath.', 'the same as 5183; quiet;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5185}/[H5185]', 'lemma', 'heb', 'נָחֵת', '["nâchêth"]', '["descending come down."]', '["a"]', 'descending come down.', 'from 5181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5186]', 'root', 'heb', 'נָטָה', '["nâṭâh"]', '["to stretch or spread out; by implication, to bend away (including moral deflection); used in a great variety of application (as follows) afternoon, apply, bow (down, -ing), carry aside, decline, deliver, extend, go down, be gone, incline, intend, lay, let down, offer, outstretched, overthrown, pervert, pitch, prolong, put away, shew, spread (out), stretch (forth, out), take (aside), turn (aside, away), wrest, cause to yield."]', '["v"]', 'to stretch or spread out; by implication, to bend away (including moral deflection); used in a great variety of application (as follows) afternoon, apply, bow (down, -ing), carry aside, decline, deliver, extend, go down, be gone, incline, intend, lay, let down, offer, outstretched, overthrown, pervert, pitch, prolong, put away, shew, spread (out), stretch (forth, out), take (aside), turn (aside, away), wrest, cause to yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5187}/[H5187]', 'lemma', 'heb', 'נְטִיל', '["nᵉṭîyl"]', '["laden that bear."]', '["a"]', 'laden that bear.', 'from 5190;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5188}/[H5188]', 'lemma', 'heb', 'נְטִיפָה', '["nᵉṭîyphâh"]', '["a pendant for the ears (especially of pearls) chain, collar."]', '["n-f"]', 'a pendant for the ears (especially of pearls) chain, collar.', 'from 5197;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5189}/[H5189]', 'lemma', 'heb', 'נְטִישָׁה', '["nᵉṭîyshâh"]', '["a tendril (as an offshoot) battlement, branch, plant."]', '["n-f"]', 'a tendril (as an offshoot) battlement, branch, plant.', 'from 5203;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5190]', 'root', 'heb', 'נָטַל', '["nâṭal"]', '["to lift; by implication, to impose bear, offer, take up."]', '["v"]', 'to lift; by implication, to impose bear, offer, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5191}/[H5191]', 'lemma', 'arc', 'נְטַל', '["nᵉṭal"]', '["to raise take up."]', '["v"]', 'to raise take up.', '(Aramaic) corresponding to 5190;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5192}/[H5192]', 'lemma', 'heb', 'נֵטֶל', '["nêṭel"]', '["a burden weighty."]', '["n-m"]', 'a burden weighty.', '; from 5190;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5193]', 'root', 'heb', 'נָטַע', '["nâṭaʻ"]', '["properly, to strike in, i.e. fix; specifically, to plant (literally or figuratively) fastened, plant(-er)."]', '["v"]', 'properly, to strike in, i.e. fix; specifically, to plant (literally or figuratively) fastened, plant(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5194}/[H5194]', 'lemma', 'heb', 'נֶטַע', '["neṭaʻ"]', '["a plant; collectively, a plantation; abstractly, a planting plant."]', '["n-m"]', 'a plant; collectively, a plantation; abstractly, a planting plant.', 'from 5193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5195}/[H5195]', 'lemma', 'heb', 'נָטִיעַ', '["nâṭîyaʻ"]', '["a plant plant."]', '["n-m"]', 'a plant plant.', 'from 5193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5196}/[H5196]', 'lemma', 'heb', 'נְטָעִים', '["Nᵉṭâʻîym"]', '["Netaim, a place in Palestine plants."]', '["n-pr-loc"]', 'Netaim, a place in Palestine plants.', 'plural of 5194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5197]', 'root', 'heb', 'נָטַף', '["nâṭaph"]', '["to ooze, i.e. distil gradually; by implication, to fall in drops; figuratively, to speak by inspiration drop(-ping), prophesy(-et)."]', '["v"]', 'to ooze, i.e. distil gradually; by implication, to fall in drops; figuratively, to speak by inspiration drop(-ping), prophesy(-et).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5198}/[H5198]', 'lemma', 'heb', 'נָטָף', '["nâṭâph"]', '["a drop; specifically, an aromatic gum (probably stacte) drop, stacte."]', '["n-m"]', 'a drop; specifically, an aromatic gum (probably stacte) drop, stacte.', 'from 5197;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5199}/[H5199]', 'lemma', 'heb', 'נְטֹפָה', '["Nᵉṭôphâh"]', '["Netophah, a place in Palestine Netophah."]', '["n-pr-loc"]', 'Netophah, a place in Palestine Netophah.', 'from 5197; distillation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5200}/[H5200]', 'lemma', 'heb', 'נְטֹפָתִי', '["Nᵉṭôphâthîy"]', '["a Netophathite, or inhabitant of Netophah Netophathite."]', '["a"]', 'a Netophathite, or inhabitant of Netophah Netophathite.', 'patronymic from 5199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5201]', 'root', 'heb', 'נָטַר', '["nâṭar"]', '["to guard; figuratively, to cherish (anger) bear grudge, keep(-er), reserve."]', '["v"]', 'to guard; figuratively, to cherish (anger) bear grudge, keep(-er), reserve.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5202}/[H5202]', 'lemma', 'arc', 'נְטַר', '["nᵉṭar"]', '["to retain keep."]', '["v"]', 'to retain keep.', '(Aramaic) corresponding to 5201;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5203]', 'root', 'heb', 'נָטַשׁ', '["nâṭash"]', '["properly, to pound, i.e. smite; by implication (as if beating out, and thus expanding) to disperse; also, to thrust off, down, out or upon (inclusively, reject, let alone, permit, remit, etc.) cast off, drawn, let fall, forsake, join (battle), leave (off), lie still, loose, spread (self) abroad, stretch out, suffer."]', '["v"]', 'properly, to pound, i.e. smite; by implication (as if beating out, and thus expanding) to disperse; also, to thrust off, down, out or upon (inclusively, reject, let alone, permit, remit, etc.) cast off, drawn, let fall, forsake, join (battle), leave (off), lie still, loose, spread (self) abroad, stretch out, suffer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5204}/[H5204]', 'lemma', 'heb', 'נִי', '["nîy"]', '["lamentation wailing."]', '["n-m"]', 'lamentation wailing.', 'a doubtful word; apparently from 5091;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5205}/[H5205]', 'lemma', 'heb', 'נִיד', '["nîyd"]', '["motion (of the lips in speech) moving."]', '["n-m"]', 'motion (of the lips in speech) moving.', 'from 5110;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5206}/[H5206]', 'lemma', 'heb', 'נִידָה', '["nîydâh"]', '["removal, i.e. exile removed."]', '["n-f"]', 'removal, i.e. exile removed.', 'feminine of 5205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5207}/[H5207]', 'lemma', 'heb', 'נִיחוֹחַ', '["nîychôwach"]', '["properly, restful, i.e. pleasant; abstractly, delight sweet (odour)."]', '["n-m"]', 'properly, restful, i.e. pleasant; abstractly, delight sweet (odour).', 'or נִיחֹחַ; from 5117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5208}/[H5208]', 'lemma', 'arc', 'נִיחוֹחַ', '["nîychôwach"]', '["pleasure sweet odour (savour)."]', '["n-m"]', 'pleasure sweet odour (savour).', '(Aramaic) or נִיחֹחַ; (shorter) (Aramaic), corresponding to 5207;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5209}/[H5209]', 'lemma', 'heb', 'נִין', '["nîyn"]', '["progeny son."]', '["n-m"]', 'progeny son.', 'from 5125;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5211}/[H5211]', 'lemma', 'heb', 'נִיס', '["nîyç"]', '["fugitive that fleeth."]', '["n-m"]', 'fugitive that fleeth.', 'from 5127;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5213}/[H5213]', 'lemma', 'heb', 'נִיצוֹץ', '["nîytsôwts"]', '["a spark spark."]', '["n-m"]', 'a spark spark.', 'from 5340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5214}/[H5214]', 'lemma', 'heb', 'נִיר', '["nîyr"]', '["to till the soil break up."]', '["v"]', 'to till the soil break up.', 'a root probably identical with that of 5216, through the idea of the gleam of a fresh furrow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5215}/[H5215]', 'lemma', 'heb', 'נִיר', '["nîyr"]', '["properly, plowing, i.e. (concretely) freshly plowed land fallow ground, plowing, tillage."]', '["n-m"]', 'properly, plowing, i.e. (concretely) freshly plowed land fallow ground, plowing, tillage.', 'or נִר; from 5214;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5216]', 'root', 'heb', 'נִיר', '["nîyr"]', '["a lamp (i.e. the burner) or light (literally or figuratively) candle, lamp, light."]', '["n-m"]', 'a lamp (i.e. the burner) or light (literally or figuratively) candle, lamp, light.', 'or נִר; also נֵיר; or נֵר; or (feminine) נֵרָה; from a primitive root (see 5214; 5135) properly, meaning to glisten;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5217]', 'root', 'heb', 'נָכָא', '["nâkâʼ"]', '["to smite, i.e. drive away be viler."]', '["v"]', 'to smite, i.e. drive away be viler.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5218}/[H5218]', 'lemma', 'heb', 'נָכֵא', '["nâkêʼ"]', '["smitten, i.e. (figuratively) afflicted broken, stricken, wounded."]', '["a"]', 'smitten, i.e. (figuratively) afflicted broken, stricken, wounded.', 'or נָכָא; from 5217;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5219}/[H5219]', 'lemma', 'heb', 'נְכֹאת', '["nᵉkôʼth"]', '["properly, a smiting, i.e. (concretely) an aromatic gum (perhaps styrax) (as powdered) spicery(-ces)."]', '["n-f"]', 'properly, a smiting, i.e. (concretely) an aromatic gum (perhaps styrax) (as powdered) spicery(-ces).', 'from 5218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5221]', 'root', 'heb', 'נָכָה', '["nâkâh"]', '["to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound."]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5222}/[H5222]', 'lemma', 'heb', 'נֵכֶה', '["nêkeh"]', '["a smiter, i.e. (figuratively) traducer abject."]', '["a"]', 'a smiter, i.e. (figuratively) traducer abject.', 'from 5221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5224}/[H5224]', 'lemma', 'heb', 'נְכוֹ', '["Nᵉkôw"]', '["Neko, an Egyptian king Necho. Compare 6549."]', '["n-pr-m"]', 'Neko, an Egyptian king Necho. Compare 6549.', 'probably of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5225}/[H5225]', 'lemma', 'heb', 'נָכוֹן', '["Nâkôwn"]', '["Nakon, probably an Israelite Nachon."]', '["n-pr-m"]', 'Nakon, probably an Israelite Nachon.', 'from 3559; prepared;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5226>', 'opaque', 'heb', 'נֵכַח', '["nêkach"]', '["properly, the fore part; used adverbially, opposite before, over against."]', '["adv"]', 'properly, the fore part; used adverbially, opposite before, over against.', 'from an unused root meaning to be straightforward;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5227}/[H5227]', 'lemma', 'heb', 'נֹכַח', '["nôkach"]', '["properly, the front part; used adverbially (especially with preposition), opposite, in front of, forward, in behalf of (over) against, before, direct(-ly), for, right (on)."]', '["adv"]', 'properly, the front part; used adverbially (especially with preposition), opposite, in front of, forward, in behalf of (over) against, before, direct(-ly), for, right (on).', 'from the same as 5226;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5228}/[H5228]', 'lemma', 'heb', 'נָכֹחַ', '["nâkôach"]', '["straightforward, i.e. (figuratively), equitable, correct, or (abstractly), integrity plain, right, uprightness."]', '["a"]', 'straightforward, i.e. (figuratively), equitable, correct, or (abstractly), integrity plain, right, uprightness.', 'from the same as 5226;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5229}/[H5229]', 'lemma', 'heb', 'נְכֹחָה', '["nᵉkôchâh"]', '["properly, straightforwardness, i.e. (figuratively) integrity, or (concretely) a truth equity, right (thing), uprightness."]', '["a-f"]', 'properly, straightforwardness, i.e. (figuratively) integrity, or (concretely) a truth equity, right (thing), uprightness.', 'feminine of 5228;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5230]', 'root', 'heb', 'נָכַל', '["nâkal"]', '["to defraud, i.e. act treacherously beguile, conspire, deceiver, deal subtilly."]', '["v"]', 'to defraud, i.e. act treacherously beguile, conspire, deceiver, deal subtilly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5231}/[H5231]', 'lemma', 'heb', 'נֵכֶל', '["nêkel"]', '["deceit wile."]', '["n-m"]', 'deceit wile.', 'from 5230;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5232}/[H5232]', 'lemma', 'arc', 'נְכַס', '["nᵉkaç"]', '["goods."]', '["n-m"]', 'goods.', '(Aramaic) corresponding to 5233');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5234]', 'root', 'heb', 'נָכַר', '["nâkar"]', '["properly, to scrutinize, i.e. look intently at; hence (with recognition implied), to acknowledge, be acquainted with, care for, respect, revere, or (with suspicion implied), to disregard, ignore, be strange toward, reject, resign, dissimulate (as if ignorant or disowning) acknowledge, × could, deliver, discern, dissemble, estrange, feign self to be another, know, take knowledge (notice), perceive, regard, (have) respect, behave (make) self strange(-ly)."]', '["v"]', 'properly, to scrutinize, i.e. look intently at; hence (with recognition implied), to acknowledge, be acquainted with, care for, respect, revere, or (with suspicion implied), to disregard, ignore, be strange toward, reject, resign, dissimulate (as if ignorant or disowning) acknowledge, × could, deliver, discern, dissemble, estrange, feign self to be another, know, take knowledge (notice), perceive, regard, (have) respect, behave (make) self strange(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5235}/[H5235]', 'lemma', 'heb', 'נֶכֶר', '["neker"]', '["something strange, i.e. unexpected calamity strange."]', '["n-m"]', 'something strange, i.e. unexpected calamity strange.', 'or נֹכֶר; from 5234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5236}/[H5236]', 'lemma', 'heb', 'נֵכָר', '["nêkâr"]', '["foreign, or (concretely) a foreigner, or (abstractly) heathendom alien, strange ( -er)."]', '["n-m"]', 'foreign, or (concretely) a foreigner, or (abstractly) heathendom alien, strange ( -er).', ''' from 5234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5237}/[H5237]', 'lemma', 'heb', 'נׇכְרִי', '["nokrîy"]', '["strange, in a variety of degrees and applications (foreign, non-relative, adulterous, different, wonderful) alien, foreigner, outlandish, strange(-r, woman)."]', '["a"]', 'strange, in a variety of degrees and applications (foreign, non-relative, adulterous, different, wonderful) alien, foreigner, outlandish, strange(-r, woman).', 'from 5235 (second form);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5238}/[H5238]', 'lemma', 'heb', 'נְכֹת', '["nᵉkôth"]', '["spicery, i.e. (generally) valuables precious things."]', '["n-f"]', 'spicery, i.e. (generally) valuables precious things.', 'probably for 5219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5239]', 'root', 'heb', 'נָלָה', '["nâlâh"]', '["to complete make an end."]', '["v"]', 'to complete make an end.', 'apparently a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5240}/[H5240]', 'lemma', 'heb', 'נְמִבְזֶה', '["nᵉmibzeh"]', '["despised vile."]', '["a"]', 'despised vile.', 'from 959,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5241}/[H5241]', 'lemma', 'heb', 'נְמוּאֵל', '["Nᵉmûwʼêl"]', '["Nemuel, the name of two Israelites Nemuel."]', '["n-pr-m"]', 'Nemuel, the name of two Israelites Nemuel.', 'apparently for 3223;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5242}/[H5242]', 'lemma', 'heb', 'נְמוּאֵלִי', '["Nᵉmûwʼêlîy"]', '["a Nemuelite, or descendant of Nemuel Nemuelite."]', '["a"]', 'a Nemuelite, or descendant of Nemuel Nemuelite.', 'from 5241;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5243]', 'root', 'heb', 'נָמַל', '["nâmal"]', '["to become clipped or (specifically) circumcised (branch to) be cut down (off), circumcise."]', '["v"]', 'to become clipped or (specifically) circumcised (branch to) be cut down (off), circumcise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5244}/[H5244]', 'lemma', 'heb', 'נְמָלָה', '["nᵉmâlâh"]', '["an ant (probably from its almost bisected form) ant."]', '["n-f"]', 'an ant (probably from its almost bisected form) ant.', 'feminine from 5243;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5245}/[H5245]', 'lemma', 'arc', 'נְמַר', '["nᵉmar"]', '["leopard."]', '["n-m"]', 'leopard.', '(Aramaic) corresponding to 5246');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5247}/[H5247]', 'lemma', 'heb', 'נִמְרָה', '["Nimrâh"]', '["Nimrah, a place East of the Jordan Nimrah. See also 1039, 5249."]', '["n-pr-loc"]', 'Nimrah, a place East of the Jordan Nimrah. See also 1039, 5249.', 'from the same as 5246; clear water;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5249}/[H5249]', 'lemma', 'heb', 'נִמְרִים', '["Nimrîym"]', '["Nimrim, a place East of the Jordan Nimrim. Compare 1039."]', '["n-pr-loc"]', 'Nimrim, a place East of the Jordan Nimrim. Compare 1039.', 'plural of a masculine corresponding to 5247; clear waters;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5250}/[H5250]', 'lemma', 'heb', 'נִמְשִׁי', '["Nimshîy"]', '["Nimshi, the (grand-) father of Jehu Nimshi."]', '["n-pr-m"]', 'Nimshi, the (grand-) father of Jehu Nimshi.', 'probably from 4871; extricated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5251}/[H5251]', 'lemma', 'heb', 'נֵס', '["nêç"]', '["a flag; also a sail; by implication, a flagstaff; generally a signal; figuratively, a token banner, pole, sail, (en-) sign, standard."]', '["n-m"]', 'a flag; also a sail; by implication, a flagstaff; generally a signal; figuratively, a token banner, pole, sail, (en-) sign, standard.', 'from 5264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5252}/[H5252]', 'lemma', 'heb', 'נְסִבָּה', '["nᵉçibbâh"]', '["properly, an environment, i.e. circumstance or turn of affairs cause."]', '["n-f"]', 'properly, an environment, i.e. circumstance or turn of affairs cause.', 'feminine participle passive of 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5253]', 'root', 'heb', 'נָסַג', '["nâçag"]', '["to retreat departing away, remove, take (hold), turn away."]', '["v"]', 'to retreat departing away, remove, take (hold), turn away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5254]', 'root', 'heb', 'נָסָה', '["nâçâh"]', '["to test; by implication, to attempt adventure, assay, prove, tempt, try."]', '["v"]', 'to test; by implication, to attempt adventure, assay, prove, tempt, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5255]', 'root', 'heb', 'נָסַח', '["nâçach"]', '["to tear away destroy, pluck, root."]', '["v"]', 'to tear away destroy, pluck, root.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5256}/[H5256]', 'lemma', 'arc', 'נְסַח', '["nᵉçach"]', '["pull down."]', '["v"]', 'pull down.', '(Aramaic) corresponding to 5255');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5257}/[H5257]', 'lemma', 'heb', 'נְסִיךְ', '["nᵉçîyk"]', '["properly, something poured out, i.e. a libation; also a molten image; by implication, a prince (as anointed) drink offering, duke, prince(-ipal)."]', '["n-m"]', 'properly, something poured out, i.e. a libation; also a molten image; by implication, a prince (as anointed) drink offering, duke, prince(-ipal).', 'from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5258]', 'root', 'heb', 'נָסַךְ', '["nâçak"]', '["to pour out, especially a libation, or to cast (metal); by analogy, to anoint a king cover, melt, offer, (cause to) pour (out), set (up)."]', '["v"]', 'to pour out, especially a libation, or to cast (metal); by analogy, to anoint a king cover, melt, offer, (cause to) pour (out), set (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5259]', 'root', 'heb', 'נָסַךְ', '["nâçak"]', '["to interweave, i.e. (figuratively) to overspread that is spread."]', '["v"]', 'to interweave, i.e. (figuratively) to overspread that is spread.', 'a primitive root (probably identical with 5258 through the idea of fusion);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5260}/[H5260]', 'lemma', 'arc', 'נְסַךְ', '["nᵉçak"]', '["to pour out a libation offer."]', '["v"]', 'to pour out a libation offer.', '(Aramaic) corresponding to 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5261}/[H5261]', 'lemma', 'arc', 'נְסַךְ', '["nᵉçak"]', '["a libation drink offering."]', '["n-m"]', 'a libation drink offering.', '(Aramaic) corresponding to 5262;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5262}/[H5262]', 'lemma', 'heb', 'נֶסֶךְ', '["neçek"]', '["a libation; also a cast idol cover, drink offering, molten image."]', '["n-m"]', 'a libation; also a cast idol cover, drink offering, molten image.', 'or נֵסֶךְ; from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5263]', 'root', 'heb', 'נָסַס', '["nâçaç"]', '["to wane, i.e. be sick faint."]', '["v"]', 'to wane, i.e. be sick faint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5264]', 'root', 'heb', 'נָסַס', '["nâçaç"]', '["to raise a beacon lift up as an ensign."]', '["v"]', 'to raise a beacon lift up as an ensign.', 'a primitive root; to gleam from afar, i.e. to be conspicuous as a signal; or rather perhaps a denominative from 5251 (and identical with 5263, through the idea of a flag as fluttering in the wind);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5265]', 'root', 'heb', 'נָסַע', '["nâçaʻ"]', '["properly, to pull up, especially the tent-pins, i.e. start on a journey cause to blow, bring, get, (make to) go (away, forth, forward, onward, out), (take) journey, march, remove, set aside (forward), × still, be on his (go their) way."]', '["v"]', 'properly, to pull up, especially the tent-pins, i.e. start on a journey cause to blow, bring, get, (make to) go (away, forth, forward, onward, out), (take) journey, march, remove, set aside (forward), × still, be on his (go their) way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5266]', 'root', 'heb', 'נָסַק', '["nâçaq"]', '["to go up ascend."]', '["v"]', 'to go up ascend.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5267}/[H5267]', 'lemma', 'arc', 'נְסַק', '["nᵉçaq"]', '["take up."]', '["v"]', 'take up.', '(Aramaic) corresponding to 5266');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5269}/[H5269]', 'lemma', 'heb', 'נֵעָה', '["Nêʻâh"]', '["Neah, a place in Palestine Neah."]', '["n-pr-loc"]', 'Neah, a place in Palestine Neah.', 'from 5128; motion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5270}/[H5270]', 'lemma', 'heb', 'נֹעָה', '["Nôʻâh"]', '["Noah, an Israelitess Noah."]', '["n-pr-f"]', 'Noah, an Israelitess Noah.', 'from 5128; movement;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5271}/[H5271]', 'lemma', 'heb', 'נָעוּר', '["nâʻûwr"]', '["(only in plural collective or emphatic form) youth, the state (juvenility) or the persons (young people) childhood, youth."]', '["n-m n-f"]', '(only in plural collective or emphatic form) youth, the state (juvenility) or the persons (young people) childhood, youth.', 'or נָעֻר; and (feminine) נְעֻרָה; properly, passive participle from 5288 as denominative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5272}/[H5272]', 'lemma', 'heb', 'נְעִיאֵל', '["Nᵉʻîyʼêl"]', '["Neiel, a place in Palestine Neiel."]', '["n-pr-loc"]', 'Neiel, a place in Palestine Neiel.', 'from 5128 and 410; moved of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5273}/[H5273]', 'lemma', 'heb', 'נָעִים', '["nâʻîym"]', '["delightful (objective or subjective, literal or figurative) pleasant(-ure), sweet."]', '["a"]', 'delightful (objective or subjective, literal or figurative) pleasant(-ure), sweet.', 'from 5276;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5274]', 'root', 'heb', 'נָעַל', '["nâʻal"]', '["properly, to fasten up, i.e. with a bar or cord; hence, to sandal, i.e. furnish with slippers bolt, inclose, lock, shoe, shut up."]', '["v"]', 'properly, to fasten up, i.e. with a bar or cord; hence, to sandal, i.e. furnish with slippers bolt, inclose, lock, shoe, shut up.', 'a primitive root; also denominative from 5275');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5275}/[H5275]', 'lemma', 'heb', 'נַעַל', '["naʻal"]', '["properly, a sandal tongue; by extension a sandal or slipper (sometimes as a symbol of occupancy, a refusal to marry, or of something valueless) dryshod, (pair of) shoe((-latchet), -s)."]', '["n-f"]', 'properly, a sandal tongue; by extension a sandal or slipper (sometimes as a symbol of occupancy, a refusal to marry, or of something valueless) dryshod, (pair of) shoe((-latchet), -s).', 'or (feminine) נַעֲלָה; from 5274;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5276]', 'root', 'heb', 'נָעֵם', '["nâʻêm"]', '["to be agreeable (literally or figuratively) pass in beauty, be delight, be pleasant, be sweet."]', '["v"]', 'to be agreeable (literally or figuratively) pass in beauty, be delight, be pleasant, be sweet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5277}/[H5277]', 'lemma', 'heb', 'נַעַם', '["Naʻam"]', '["Naam, an Israelite Naam."]', '["n-pr-m"]', 'Naam, an Israelite Naam.', 'from 5276; pleasure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5278}/[H5278]', 'lemma', 'heb', 'נֹעַם', '["nôʻam"]', '["agreeableness, i.e. delight, suitableness, splendor or grace beauty, pleasant(-ness)."]', '["n-m"]', 'agreeableness, i.e. delight, suitableness, splendor or grace beauty, pleasant(-ness).', 'from 5276;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5279}/[H5279]', 'lemma', 'heb', 'נַעֲמָה', '["Naʻămâh"]', '["Naamah, the name of an antediluvian woman, of an Ammonitess, and of a place in Palestine Naamah."]', '["n-pr-f n-pr-loc"]', 'Naamah, the name of an antediluvian woman, of an Ammonitess, and of a place in Palestine Naamah.', 'feminine of 5277; pleasantness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5280}/[H5280]', 'lemma', 'heb', 'נַעֲמִי', '["Naʻămîy"]', '["a Naamanite, or descendant of Naaman (collectively) Naamites."]', '["a"]', 'a Naamanite, or descendant of Naaman (collectively) Naamites.', 'patronymic from 5283;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5281}/[H5281]', 'lemma', 'heb', 'נׇעֳמִי', '["Noʻŏmîy"]', '["Noömi, an Israelitess Naomi."]', '["n-pr-f"]', 'Noömi, an Israelitess Naomi.', 'from 5278; pleasant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5282}/[H5282]', 'lemma', 'heb', 'נַעֲמָן', '["naʻămân"]', '["pleasantness (plural as concrete) pleasant."]', '["n-m"]', 'pleasantness (plural as concrete) pleasant.', 'from 5276;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5283}/[H5283]', 'lemma', 'heb', 'נַעֲמָן', '["Naʻămân"]', '["Naaman, the name of an Israelite and of a Damascene Naaman."]', '["n-pr-m"]', 'Naaman, the name of an Israelite and of a Damascene Naaman.', 'the same as 5282;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5284}/[H5284]', 'lemma', 'heb', 'נַעֲמָתִי', '["Naʻămâthîy"]', '["a Naamathite, or inhabitant of Naamah Naamathite."]', '["a"]', 'a Naamathite, or inhabitant of Naamah Naamathite.', 'patrial from a place corresponding in name (but not identical) with 5279;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5285>', 'opaque', 'heb', 'נַעֲצוּץ', '["naʻătsûwts"]', '["probably a brier; by implication, a thicket of thorny bushes thorn."]', '["n-m"]', 'probably a brier; by implication, a thicket of thorny bushes thorn.', 'from an unused root meaning to prick;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5286]', 'root', 'heb', 'נָעַר', '["nâʻar"]', '["to growl yell."]', '["v"]', 'to growl yell.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5287]', 'root', 'heb', 'נָעַר', '["nâʻar"]', '["to tumble about shake (off, out, self), overthrow, toss up and down."]', '["v"]', 'to tumble about shake (off, out, self), overthrow, toss up and down.', 'a primitive root (probably identical with 5286, through the idea of the rustling of mane, which usually accompanies the lion''s roar);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5288}/[H5288]', 'lemma', 'heb', 'נַעַר', '["naʻar"]', '["(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man)."]', '["n-m"]', '(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man).', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5289}/[H5289]', 'lemma', 'heb', 'נַעַר', '["naʻar"]', '["a wanderer young one."]', '["n-m"]', 'a wanderer young one.', 'from 5287 in its derivative sense of tossing about;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5290}/[H5290]', 'lemma', 'heb', 'נֹעַר', '["nôʻar"]', '["(abstractly) boyhood child, youth."]', '["n-m"]', '(abstractly) boyhood child, youth.', 'from 5287; (compare 5288)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5291}/[H5291]', 'lemma', 'heb', 'נַעֲרָה', '["naʻărâh"]', '["a girl (from infancy to adolescence) damsel, maid(-en), young (woman)."]', '["n-f"]', 'a girl (from infancy to adolescence) damsel, maid(-en), young (woman).', 'feminine of 5288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5292}/[H5292]', 'lemma', 'heb', 'נַעֲרָה', '["Naʻărâh"]', '["Naarah, the name of an Israelitess, and of a place in Palestine Naarah, Naarath."]', '["n-pr-loc n-pr-f"]', 'Naarah, the name of an Israelitess, and of a place in Palestine Naarah, Naarath.', 'the same as 5291;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5293}/[H5293]', 'lemma', 'heb', 'נַעֲרַי', '["Naʻăray"]', '["Naarai, an Israelite Naarai."]', '["n-pr-m"]', 'Naarai, an Israelite Naarai.', 'from 5288; youthful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5294}/[H5294]', 'lemma', 'heb', 'נְעַרְיָה', '["Nᵉʻaryâh"]', '["Nearjah, the name of two Israelites Neariah."]', '["n-pr-m"]', 'Nearjah, the name of two Israelites Neariah.', 'from 5288 and 3050; servant of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5295}/[H5295]', 'lemma', 'heb', 'נַעֲרָן', '["Naʻărân"]', '["Naaran, a place in Palestine Naaran."]', '["n-pr-loc"]', 'Naaran, a place in Palestine Naaran.', 'from 5288; juvenile;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5296}/[H5296]', 'lemma', 'heb', 'נְעֹרֶת', '["nᵉʻôreth"]', '["something shaken out, i.e. tow (as the refuse of flax) tow."]', '["n-f"]', 'something shaken out, i.e. tow (as the refuse of flax) tow.', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5297}/[H5297]', 'lemma', 'heb', 'נֹף', '["Nôph"]', '["Noph, the capital of Upper Egypt Noph."]', '["n-pr-loc"]', 'Noph, the capital of Upper Egypt Noph.', 'a variation of 4644;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5298>', 'opaque', 'heb', 'נֶפֶג', '["Nepheg"]', '["Nepheg, the name of two Israelites Nepheg."]', '["n-pr-m"]', 'Nepheg, the name of two Israelites Nepheg.', 'from an unused root probably meaning to spring forth; a sprout;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5299}/[H5299]', 'lemma', 'heb', 'נָפָה', '["nâphâh"]', '["a sieve border, coast, region, sieve."]', '["n-f"]', 'a sieve border, coast, region, sieve.', 'from 5130 in the sense of lifting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5300}/[H5300]', 'lemma', 'heb', 'נְפוּשְׁסִים', '["Nᵉphûwshᵉçîym"]', '["Nephushesim, a Temple-servant Nephisesim (from the margin)."]', '["n"]', 'Nephushesim, a Temple-servant Nephisesim (from the margin).', 'for 5304;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5301]', 'root', 'heb', 'נָפַח', '["nâphach"]', '["to puff, in various applications (literally, to inflate, blow hard, scatter, kindle, expire; figuratively, to disesteem) blow, breath, give up, cause to lose (life), seething, snuff."]', '["v"]', 'to puff, in various applications (literally, to inflate, blow hard, scatter, kindle, expire; figuratively, to disesteem) blow, breath, give up, cause to lose (life), seething, snuff.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5302}/[H5302]', 'lemma', 'heb', 'נֹפַח', '["Nôphach"]', '["Nophach, a place in Moab Nophah."]', '["n-pr-loc"]', 'Nophach, a place in Moab Nophah.', 'from 5301; a gust;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5303}/[H5303]', 'lemma', 'heb', 'נְפִיל', '["nᵉphîyl"]', '["properly, a feller, i.e. a bully or tyrant giant."]', '["n-m"]', 'properly, a feller, i.e. a bully or tyrant giant.', 'or נְפִל; from 5307;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5305}/[H5305]', 'lemma', 'heb', 'נָפִישׁ', '["Nâphîysh"]', '["Naphish, a son of Ishmael, and his posterity Naphish."]', '["n-pr-m"]', 'Naphish, a son of Ishmael, and his posterity Naphish.', 'from 5314; refreshed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5307]', 'root', 'heb', 'נָפַל', '["nâphal"]', '["to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down."]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5308}/[H5308]', 'lemma', 'arc', 'נְפַל', '["nᵉphal"]', '["fall (down), have occasion."]', '["v"]', 'fall (down), have occasion.', '(Aramaic) corresponding to 5307');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5309}/[H5309]', 'lemma', 'heb', 'נֶפֶל', '["nephel"]', '["something fallen, i.e. an abortion untimely birth."]', '["n-m"]', 'something fallen, i.e. an abortion untimely birth.', 'or נֵפֶל; from 5307;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5310]', 'root', 'heb', 'נָפַץ', '["nâphats"]', '["to dash to pieces, or scatter be beaten in sunder, break (in pieces), broken, dash (in pieces), cause to be discharged, dispersed, be overspread, scatter."]', '["v"]', 'to dash to pieces, or scatter be beaten in sunder, break (in pieces), broken, dash (in pieces), cause to be discharged, dispersed, be overspread, scatter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5311}/[H5311]', 'lemma', 'heb', 'נֶפֶץ', '["nephets"]', '["a storm (as dispersing) scattering."]', '["n-m"]', 'a storm (as dispersing) scattering.', 'from 5310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5312]', 'root', 'arc', 'נְפַק', '["nᵉphaq"]', '["to issue; causatively, to bring out come (go, take) forth (out)."]', '["v"]', 'to issue; causatively, to bring out come (go, take) forth (out).', '(Aramaic) a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5313}/[H5313]', 'lemma', 'arc', 'נִפְקָא', '["niphqâʼ"]', '["an outgo, i.e. expense expense."]', '["n-f"]', 'an outgo, i.e. expense expense.', '(Aramaic) from 5312;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5314]', 'root', 'heb', 'נָפַשׁ', '["nâphash"]', '["to breathe; passively, to be breathed upon , i.e. (figuratively) refreshed (as if by a current of air) (be) refresh selves (-ed)."]', '["v"]', 'to breathe; passively, to be breathed upon , i.e. (figuratively) refreshed (as if by a current of air) (be) refresh selves (-ed).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315}/[H5315]', 'lemma', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it."]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5316}/[H5316]', 'lemma', 'heb', 'נֶפֶת', '["nepheth"]', '["a height country."]', '["n-f"]', 'a height country.', 'for 5299;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5317}/[H5317]', 'lemma', 'heb', 'נֹפֶת', '["nôpheth"]', '["a dripping i.e. of honey (from the comb) honeycomb."]', '["n-m"]', 'a dripping i.e. of honey (from the comb) honeycomb.', 'from 5130 in the sense of shaking to pieces;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5318}/[H5318]', 'lemma', 'heb', 'נֶפְתּוֹחַ', '["Nephtôwach"]', '["Nephtoach, a place in Palestine Neptoah."]', '["n-pr-loc"]', 'Nephtoach, a place in Palestine Neptoah.', 'from 6605; opened, i.e. a spring;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5319}/[H5319]', 'lemma', 'heb', 'נַפְתּוּל', '["naphtûwl"]', '["properly, wrestled; but used (in the plural) transitively, a struggle wrestling."]', '["n-m"]', 'properly, wrestled; but used (in the plural) transitively, a struggle wrestling.', 'from 6617;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5321}/[H5321]', 'lemma', 'heb', 'נַפְתָּלִי', '["Naphtâlîy"]', '["Naphtali, a son of Jacob, with the tribe descended from him, and its territory Naphtali."]', '["n-pr-m n-pr-loc"]', 'Naphtali, a son of Jacob, with the tribe descended from him, and its territory Naphtali.', 'from 6617; my wrestling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5322}/[H5322]', 'lemma', 'heb', 'נֵץ', '["nêts"]', '["a flower (from its brilliancy); also a hawk (from it flashing speed) blossom, hawk."]', '["n-m"]', 'a flower (from its brilliancy); also a hawk (from it flashing speed) blossom, hawk.', 'from 5340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5323]', 'root', 'heb', 'נָצָא', '["nâtsâʼ"]', '["to go away flee."]', '["v"]', 'to go away flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5324]', 'root', 'heb', 'נָצַב', '["nâtsab"]', '["to station, in various applications (literally or figuratively) appointed, deputy, erect, establish, × Huzzah (by mistake for a proper name), lay, officer, pillar, present, rear up, set (over, up), settle, sharpen, establish, (make to) stand(-ing, still, up, upright), best state."]', '["v"]', 'to station, in various applications (literally or figuratively) appointed, deputy, erect, establish, × Huzzah (by mistake for a proper name), lay, officer, pillar, present, rear up, set (over, up), settle, sharpen, establish, (make to) stand(-ing, still, up, upright), best state.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5325}/[H5325]', 'lemma', 'heb', 'נִצָּב', '["nitstsâb"]', '["fixed, i.e. a handle haft."]', '["n-m"]', 'fixed, i.e. a handle haft.', 'passive participle of 5324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5326}/[H5326]', 'lemma', 'arc', 'נִצְבָּה', '["nitsbâh"]', '["fixedness, i.e. firmness strength."]', '["n-f"]', 'fixedness, i.e. firmness strength.', '(Aramaic) from a root corresponding to 5324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5327]', 'root', 'heb', 'נָצָה', '["nâtsâh"]', '["properly, to go forth, i.e. (by implication) to be expelled, and (consequently) desolate; causatively, to lay waste; also (specifically), to quarrel be laid waste, runinous, strive (together)."]', '["v"]', 'properly, to go forth, i.e. (by implication) to be expelled, and (consequently) desolate; causatively, to lay waste; also (specifically), to quarrel be laid waste, runinous, strive (together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5328}/[H5328]', 'lemma', 'heb', 'נִצָּה', '["nitstsâh"]', '["a blossom flower."]', '["n-f"]', 'a blossom flower.', 'feminine of 5322;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5329]', 'root', 'heb', 'נָצַח', '["nâtsach"]', '["properly, to glitter from afar, i.e. to be eminent (as a superintendent, especially of the Temple services and its music); to be permanent excel, chief musician (singer), oversee(-r), set forward."]', '["v"]', 'properly, to glitter from afar, i.e. to be eminent (as a superintendent, especially of the Temple services and its music); to be permanent excel, chief musician (singer), oversee(-r), set forward.', 'a primitive root; also as denominative from 5331');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5330}/[H5330]', 'lemma', 'arc', 'נְצַח', '["nᵉtsach"]', '["to become chief be preferred."]', '["v"]', 'to become chief be preferred.', '(Aramaic) corresponding to 5329;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5331}/[H5331]', 'lemma', 'heb', 'נֶצַח', '["netsach"]', '["properly, a goal, i.e. the bright object at a distance travelled towards; hence (figuratively), splendor, or (subjectively) truthfulness, or (objectively) confidence; but usually (adverbially), continually (i.e. to the most distant point of view) alway(-s), constantly, end, ( n-) ever(more), perpetual, strength, victory."]', '["n-m"]', 'properly, a goal, i.e. the bright object at a distance travelled towards; hence (figuratively), splendor, or (subjectively) truthfulness, or (objectively) confidence; but usually (adverbially), continually (i.e. to the most distant point of view) alway(-s), constantly, end, ( n-) ever(more), perpetual, strength, victory.', 'or נֵצַח; from 5329;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5332}/[H5332]', 'lemma', 'heb', 'נֵצַח', '["Nêtsach"]', '["juice of the grape (as blood red) blood, strength."]', '["n-m"]', 'juice of the grape (as blood red) blood, strength.', 'probably identical with 5331, through the idea of brilliancy of color;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5333}/[H5333]', 'lemma', 'heb', 'נְצִיב', '["nᵉtsîyb"]', '["something stationary, i.e. a prefect, a military post, a statue garrison, officer, pillar."]', '["n-m"]', 'something stationary, i.e. a prefect, a military post, a statue garrison, officer, pillar.', 'or נְצִב; from 5324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5334}/[H5334]', 'lemma', 'heb', 'נְצִיב', '["Nᵉtsîyb"]', '["Netsib, a place in Palestine Nezib."]', '["n-pr-loc"]', 'Netsib, a place in Palestine Nezib.', 'the same as 5333; station;');
