INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5336}/[H5336]', 'lemma', 'heb', 'נָצִיר', '["nâtsîyr"]', '["properly, conservative; but used passively, delivered preserved."]', '["a"]', 'properly, conservative; but used passively, delivered preserved.', 'from 5341;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5337]', 'root', 'heb', 'נָצַל', '["nâtsal"]', '["to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out)."]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5338}/[H5338]', 'lemma', 'arc', 'נְצַל', '["nᵉtsal"]', '["to extricate deliver, rescue."]', '["v"]', 'to extricate deliver, rescue.', '(Aramaic) corresponding to 5337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5339}/[H5339]', 'lemma', 'heb', 'נִצָּן', '["nitstsân"]', '["a blossom flower."]', '["n-m"]', 'a blossom flower.', 'from 5322;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5340]', 'root', 'heb', 'נָצַץ', '["nâtsats"]', '["to glare, i.e. be bright-colored sparkle."]', '["v"]', 'to glare, i.e. be bright-colored sparkle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5341]', 'root', 'heb', 'נָצַר', '["nâtsar"]', '["to guard, in a good sense (to protect, maintain, obey, etc.) or a bad one (to conceal, etc.) besieged, hidden thing, keep(-er, -ing), monument, observe, preserve(-r), subtil, watcher(-man)."]', '["v"]', 'to guard, in a good sense (to protect, maintain, obey, etc.) or a bad one (to conceal, etc.) besieged, hidden thing, keep(-er, -ing), monument, observe, preserve(-r), subtil, watcher(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5342}/[H5342]', 'lemma', 'heb', 'נֵצֶר', '["nêtser"]', '["a shoot; figuratively, a descendant branch."]', '["n-m"]', 'a shoot; figuratively, a descendant branch.', 'from 5341 in the sense of greenness as a striking color;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5343}/[H5343]', 'lemma', 'arc', 'נְקֵא', '["nᵉqêʼ"]', '["clean pure."]', '["a"]', 'clean pure.', '(Aramaic) from a root corresponding to 5352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5344]', 'root', 'heb', 'נָקַב', '["nâqab"]', '["to puncture, literally (to perforate, with more or less violence) or figuratively (to specify, designate, libel) appoint, blaspheme, bore, curse, express, with holes, name, pierce, strike through."]', '["v"]', 'to puncture, literally (to perforate, with more or less violence) or figuratively (to specify, designate, libel) appoint, blaspheme, bore, curse, express, with holes, name, pierce, strike through.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5345}/[H5345]', 'lemma', 'heb', 'נֶקֶב', '["neqeb"]', '["a bezel (for a gem) pipe."]', '["n-m"]', 'a bezel (for a gem) pipe.', NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5346}/[H5346]', 'lemma', 'heb', 'נֶקֶב', '["Neqeb"]', '["Nekeb, a place in Palestine Nekeb."]', '["n-pr-loc"]', 'Nekeb, a place in Palestine Nekeb.', 'the same as 5345; dell;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5347}/[H5347]', 'lemma', 'heb', 'נְקֵבָה', '["nᵉqêbâh"]', '["female (from the sexual form) female."]', '["n-f"]', 'female (from the sexual form) female.', 'from 5344;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5349}/[H5349]', 'lemma', 'heb', 'נֹקֵד', '["nôqêd"]', '["a spotter (of sheep or cattle), i.e. the owner or tender (who thus marks them) herdman, sheepmaster."]', '["n-m"]', 'a spotter (of sheep or cattle), i.e. the owner or tender (who thus marks them) herdman, sheepmaster.', 'active participle from the same as 5348;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5350}/[H5350]', 'lemma', 'heb', 'נִקֻּד', '["niqqud"]', '["a crumb (as broken to spots); also a biscuit (as pricked) cracknel, mouldy."]', '["n-m"]', 'a crumb (as broken to spots); also a biscuit (as pricked) cracknel, mouldy.', 'from the same as 5348;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5351}/[H5351]', 'lemma', 'heb', 'נְקֻדָּה', '["nᵉquddâh"]', '["a boss stud."]', '["n-f"]', 'a boss stud.', 'feminine of 5348;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5352]', 'root', 'heb', 'נָקָה', '["nâqâh"]', '["to be (or make) clean (literally or figuratively); by implication (in an adverse sense) to be bare, i.e. extirpated acquit × at all, × altogether, be blameless, cleanse, (be) clear(-ing), cut off, be desolate, be free, be (hold) guiltless, be (hold) innocent, × by no means, be quit, be (leave) unpunished, × utterly, × wholly."]', '["v"]', 'to be (or make) clean (literally or figuratively); by implication (in an adverse sense) to be bare, i.e. extirpated acquit × at all, × altogether, be blameless, cleanse, (be) clear(-ing), cut off, be desolate, be free, be (hold) guiltless, be (hold) innocent, × by no means, be quit, be (leave) unpunished, × utterly, × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5353}/[H5353]', 'lemma', 'heb', 'נְקוֹדָא', '["Nᵉqôwdâʼ"]', '["Nekoda, a Temple-servant Nekoda."]', '["n-pr-f"]', 'Nekoda, a Temple-servant Nekoda.', 'feminine of 5348 (in the figurative sense of marked); distinction;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5354]', 'root', 'heb', 'נָקַט', '["nâqaṭ"]', '["to loathe weary."]', '["v"]', 'to loathe weary.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5355}/[H5355]', 'lemma', 'heb', 'נָקִי', '["nâqîy"]', '["innocent blameless, clean, clear, exempted, free, guiltless, innocent, quit."]', '["a"]', 'innocent blameless, clean, clear, exempted, free, guiltless, innocent, quit.', 'or נָקִיא; (Joel 4:19; Jonah 1:14), from 5352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5356}/[H5356]', 'lemma', 'heb', 'נִקָּיוֹן', '["niqqâyôwn"]', '["clearness (literally or figuratively) cleanness, innocency."]', '["n-m"]', 'clearness (literally or figuratively) cleanness, innocency.', 'or נִקָּיֹן; from 5352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5357>', 'opaque', 'heb', 'נָקִיק', '["nâqîyq"]', '["a cleft hole."]', '["n-m"]', 'a cleft hole.', 'from an unused root meaning to bore;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5358]', 'root', 'heb', 'נָקַם', '["nâqam"]', '["to grudge, i.e. avenge or punish avenge(-r, self), punish, revenge (self), × surely, take vengeance."]', '["v"]', 'to grudge, i.e. avenge or punish avenge(-r, self), punish, revenge (self), × surely, take vengeance.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5359}/[H5359]', 'lemma', 'heb', 'נָקָם', '["nâqâm"]', '["revenge avenged, quarrel, vengeance."]', '["n-m"]', 'revenge avenged, quarrel, vengeance.', 'from 5358;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5360}/[H5360]', 'lemma', 'heb', 'נְקָמָה', '["nᵉqâmâh"]', '["avengement, whether the act or the passion avenge, revenge(-ing), vengeance."]', '["n-f"]', 'avengement, whether the act or the passion avenge, revenge(-ing), vengeance.', 'feminine of 5359;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5361]', 'root', 'heb', 'נָקַע', '["nâqaʻ"]', '["to feel aversion be alienated."]', '["v"]', 'to feel aversion be alienated.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5362]', 'root', 'heb', 'נָקַף', '["nâqaph"]', '["to strike with more or less violence (beat, fell, corrode); by implication (of attack) to knock together, i.e. surround or circulate compass (about, -ing), cut down, destroy, go round (about), inclose, round."]', '["v"]', 'to strike with more or less violence (beat, fell, corrode); by implication (of attack) to knock together, i.e. surround or circulate compass (about, -ing), cut down, destroy, go round (about), inclose, round.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5363}/[H5363]', 'lemma', 'heb', 'נֹקֶף', '["nôqeph"]', '["a threshing (of olives) shaking."]', '["n-m"]', 'a threshing (of olives) shaking.', 'from 5362;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5364}/[H5364]', 'lemma', 'heb', 'נִקְפָּה', '["niqpâh"]', '["probably a rope (as encircling) rent."]', '["n-f"]', 'probably a rope (as encircling) rent.', 'from 5362;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5365]', 'root', 'heb', 'נָקַר', '["nâqar"]', '["to bore (penetrate, quarry) dig, pick out, pierce, put (thrust) out."]', '["v"]', 'to bore (penetrate, quarry) dig, pick out, pierce, put (thrust) out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5366}/[H5366]', 'lemma', 'heb', 'נְקָרָה', '["nᵉqârâh"]', '["a fissure cleft, clift."]', '["n-f"]', 'a fissure cleft, clift.', 'from 5365;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5367]', 'root', 'heb', 'נָקַשׁ', '["nâqash"]', '["to entrap (with a noose), literally or figuratively catch (lay a) snare."]', '["v"]', 'to entrap (with a noose), literally or figuratively catch (lay a) snare.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5368}/[H5368]', 'lemma', 'arc', 'נְקַשׁ', '["nᵉqash"]', '["to knock smote."]', '["v"]', 'to knock smote.', '(Aramaic) corresponding to 5367; used in the sense of 5362;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5369}/[H5369]', 'lemma', 'heb', 'נֵר', '["Nêr"]', '["Ner, an Israelite Ner."]', '["n-pr-m"]', 'Ner, an Israelite Ner.', 'the same as 5216; lamp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5371}/[H5371]', 'lemma', 'heb', 'נֵרְגַּל שַׁרְאֶצֶר', '["Nêrᵉgal Sharʼetser"]', '["Nergal-Sharetser, the name of two Babylonians Nergal-sharezer."]', '["n-pr-m"]', 'Nergal-Sharetser, the name of two Babylonians Nergal-sharezer.', 'from 5370 and 8272;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5372>', 'opaque', 'heb', 'נִרְגָּן', '["nirgân"]', '["a slanderer talebearer, whisperer."]', '["v"]', 'a slanderer talebearer, whisperer.', 'from an unused root meaning to roll to pieces;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5374}/[H5374]', 'lemma', 'heb', 'נֵרִיָּה', '["Nêrîyâh"]', '["Nerijah, an Israelite Neriah."]', '["n-pr-m"]', 'Nerijah, an Israelite Neriah.', 'or נֵרִיָּהוּ; from 5216 and 3050; light of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5375]', 'root', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield."]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5376}/[H5376]', 'lemma', 'arc', 'נְשָׂא', '["nᵉsâʼ"]', '["carry away, make insurrection, take."]', '["v"]', 'carry away, make insurrection, take.', '(Aramaic) corresponding to 5375');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5377]', 'root', 'heb', 'נָשָׁא', '["nâshâʼ"]', '["to lead astray, i.e. (mentally) to delude, or (morally) to seduce beguile, deceive, × greatly, × utterly."]', '["v"]', 'to lead astray, i.e. (mentally) to delude, or (morally) to seduce beguile, deceive, × greatly, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5378]', 'root', 'heb', 'נָשָׁא', '["nâshâʼ"]', '["to lend on interest; by implication, to dun for debt × debt, exact, giver of usury."]', '["v"]', 'to lend on interest; by implication, to dun for debt × debt, exact, giver of usury.', 'a primitive root (perhaps identical with 5377, through the idea of imposition);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5379}/[H5379]', 'lemma', 'heb', 'נִשֵּׂאת', '["nissêʼth"]', '["something taken, i.e. a present gift."]', '["n-f"]', 'something taken, i.e. a present gift.', 'passive participle feminine of 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5380]', 'root', 'heb', 'נָשַׁב', '["nâshab"]', '["to blow; by implication, to disperse (cause to) blow, drive away."]', '["v"]', 'to blow; by implication, to disperse (cause to) blow, drive away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5381]', 'root', 'heb', 'נָשַׂג', '["nâsag"]', '["to reach (literally or figuratively) ability, be able, attain (unto), (be able to, can) get, lay at, put, reach, remove, wax rich, × surely, (over-) take (hold of, on, upon)."]', '["v"]', 'to reach (literally or figuratively) ability, be able, attain (unto), (be able to, can) get, lay at, put, reach, remove, wax rich, × surely, (over-) take (hold of, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5382]', 'root', 'heb', 'נָשָׁה', '["nâshâh"]', '["to forget; figuratively, to neglect; causatively, to remit, remove forget, deprive, exact."]', '["v"]', 'to forget; figuratively, to neglect; causatively, to remit, remove forget, deprive, exact.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5383]', 'root', 'heb', 'נָשָׁה', '["nâshâh"]', '["to lend or (by reciprocity) borrow on security or interest creditor, exact, extortioner, lend, usurer, lend on (taker on) usury."]', '["v"]', 'to lend or (by reciprocity) borrow on security or interest creditor, exact, extortioner, lend, usurer, lend on (taker on) usury.', 'a primitive root (rather identical with 5382, in the sense of 5378);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5384}/[H5384]', 'lemma', 'heb', 'נָשֶׁה', '["nâsheh"]', '["rheumatic or crippled (from the incident to Jacob) which shrank."]', '["n-m"]', 'rheumatic or crippled (from the incident to Jacob) which shrank.', 'from 5382, in the sense of failure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5385}/[H5385]', 'lemma', 'heb', 'נְשׂוּאָה', '["nᵉsûwʼâh"]', '["something borne, i.e. a load carriage."]', '["n-f"]', 'something borne, i.e. a load carriage.', 'or rather, נְשֻׂאָה; feminine. passive participle of 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5386}/[H5386]', 'lemma', 'heb', 'נְשִׁי', '["nᵉshîy"]', '["a debt debt."]', '["n-m"]', 'a debt debt.', 'from 5383;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5387}/[H5387]', 'lemma', 'heb', 'נָשִׂיא', '["nâsîyʼ"]', '["properly, an exalted one, i.e. a king or sheik; also a rising mist captain, chief, cloud, governor, prince, ruler, vapour."]', '["n-m"]', 'properly, an exalted one, i.e. a king or sheik; also a rising mist captain, chief, cloud, governor, prince, ruler, vapour.', 'or נָשִׂא; from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5388}/[H5388]', 'lemma', 'heb', 'נְשִׁיָּה', '["nᵉshîyâh"]', '["oblivion forgetfulness."]', '["n-f"]', 'oblivion forgetfulness.', 'from 5382;');
