INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5392}/[H5392]', 'lemma', 'heb', 'נֶשֶׁךְ', '["neshek"]', '["interest on a debt usury."]', '["n-m"]', 'interest on a debt usury.', 'from 5391;');
