INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5394]', 'root', 'heb', 'נָשַׁל', '["nâshal"]', '["to pluck off, i.e. divest, eject or drop cast (out), drive, loose, put off (out), slip."]', '["v"]', 'to pluck off, i.e. divest, eject or drop cast (out), drive, loose, put off (out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5395]', 'root', 'heb', 'נָשַׁם', '["nâsham"]', '["properly, to blow away, i.e. destroy destroy."]', '["v"]', 'properly, to blow away, i.e. destroy destroy.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5396}/[H5396]', 'lemma', 'arc', 'נִשְׁמָא', '["nishmâʼ"]', '["vital breath breath."]', '["n-f"]', 'vital breath breath.', '(Aramaic) corresponding to 5397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5397}/[H5397]', 'lemma', 'heb', 'נְשָׁמָה', '["nᵉshâmâh"]', '["a puff, i.e. wind, angry or vital breath, divine inspiration, intellect. or (concretely) an animal blast, (that) breath(-eth), inspiration, soul, spirit."]', '["n-f"]', 'a puff, i.e. wind, angry or vital breath, divine inspiration, intellect. or (concretely) an animal blast, (that) breath(-eth), inspiration, soul, spirit.', 'from 5395;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5398]', 'root', 'heb', 'נָשַׁף', '["nâshaph"]', '["to breeze, i.e. blow up fresh (as the wind) blow."]', '["v"]', 'to breeze, i.e. blow up fresh (as the wind) blow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5399}/[H5399]', 'lemma', 'heb', 'נֶשֶׁף', '["nesheph"]', '["properly, a breeze, i.e. (by implication) dusk (when the evening breeze prevails) dark, dawning of the day (morning), night, twilight."]', '["n-m"]', 'properly, a breeze, i.e. (by implication) dusk (when the evening breeze prevails) dark, dawning of the day (morning), night, twilight.', 'from 5398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5400]', 'root', 'heb', 'נָשַׂק', '["nâsaq"]', '["to catch fire burn, kindle."]', '["v"]', 'to catch fire burn, kindle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5401]', 'root', 'heb', 'נָשַׁק', '["nâshaq"]', '["to kiss, literally or figuratively (touch); also (as a mode of attachment), to equip with weapons armed (men), rule, kiss, that touched."]', '["v"]', 'to kiss, literally or figuratively (touch); also (as a mode of attachment), to equip with weapons armed (men), rule, kiss, that touched.', 'a primitive root (identical with 5400, through the idea of fastening up; compare 2388, 2836);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5402}/[H5402]', 'lemma', 'heb', 'נֶשֶׁק', '["nesheq"]', '["military equipment, i.e. (collectively) arms (offensive or defensive), or (concretely) an arsenal armed men, armour(-y), battle, harness, weapon."]', '["n-m"]', 'military equipment, i.e. (collectively) arms (offensive or defensive), or (concretely) an arsenal armed men, armour(-y), battle, harness, weapon.', 'or נֵשֶׁק; from 5401;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5403}/[H5403]', 'lemma', 'arc', 'נְשַׁר', '["nᵉshar"]', '["an eagle eagle."]', '["n-m"]', 'an eagle eagle.', '(Aramaic) corresponding to 5404;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5405]', 'root', 'heb', 'נָשַׁת', '["nâshath"]', '["properly, to eliminate, i.e. (intransitively) to dry up fail."]', '["v"]', 'properly, to eliminate, i.e. (intransitively) to dry up fail.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5406}/[H5406]', 'lemma', 'heb', 'נִשְׁתְּוָן', '["nishtᵉvân"]', '["an epistle letter."]', '["n-m"]', 'an epistle letter.', 'probably of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5407}/[H5407]', 'lemma', 'arc', 'נִשְׁתְּוָן', '["nishtᵉvân"]', '["letter."]', '["n-m"]', 'letter.', '(Aramaic) corresponding to 5406');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5408]', 'root', 'heb', 'נָתַח', '["nâthach"]', '["to dismember cut (in pieces), divide, hew in pieces."]', '["v"]', 'to dismember cut (in pieces), divide, hew in pieces.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5409}/[H5409]', 'lemma', 'heb', 'נֵתַח', '["nêthach"]', '["a fragment part, piece."]', '["n-m"]', 'a fragment part, piece.', 'from 5408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5410>', 'opaque', 'heb', 'נָתִיב', '["nâthîyb"]', '["a (beaten) track path(-way), × travel(-ler), way."]', '["n-m"]', 'a (beaten) track path(-way), × travel(-ler), way.', 'or (feminine) נְתִיבָה; or נְתִבָה; (Jeremiah 6:16), from an unused root meaning to tramp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5411}/[H5411]', 'lemma', 'heb', 'נָתִין', '["Nâthîyn"]', '["the Nethinim, or Temple-servants (as given to that duty) Nethinims."]', '["n-m"]', 'the Nethinim, or Temple-servants (as given to that duty) Nethinims.', 'or נָתוּן (Ezra 8:17), (the proper form as passive participle), from 5414; one given, i.e. (in the plural only)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5412}/[H5412]', 'lemma', 'arc', 'נְתִין', '["Nᵉthîyn"]', '["Nethinims."]', '["n-m"]', 'Nethinims.', '(Aramaic) corresponding to 5411');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5413]', 'root', 'heb', 'נָתַךְ', '["nâthak"]', '["to flow forth (literally or figuratively); by implication, to liquify drop, gather (together), melt, pour (forth, out)."]', '["v"]', 'to flow forth (literally or figuratively); by implication, to liquify drop, gather (together), melt, pour (forth, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5414]', 'root', 'heb', 'נָתַן', '["nâthan"]', '["to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield."]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5415}/[H5415]', 'lemma', 'arc', 'נְתַן', '["nᵉthan"]', '["give bestow, give pay."]', '["v"]', 'give bestow, give pay.', '(Aramaic) corresponding to 5414;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5416}/[H5416]', 'lemma', 'heb', 'נָתָן', '["Nâthân"]', '["Nathan, the name of five Israelites Nathan."]', '["n-pr-m"]', 'Nathan, the name of five Israelites Nathan.', 'from 5414; given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5417}/[H5417]', 'lemma', 'heb', 'נְתַנְאֵל', '["Nᵉthanʼêl"]', '["Nethanel, the name of ten Israelites Nethaneel."]', '["n-pr-m"]', 'Nethanel, the name of ten Israelites Nethaneel.', 'from 5414 and 410; given of God;');
