INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5419}/[H5419]', 'lemma', 'heb', 'נְתַן־מֶלֶךְ', '["Nᵉthan-Melek"]', '["Nethan-Melek, an Israelite Nathanmelech."]', '["n-pr-m"]', 'Nethan-Melek, an Israelite Nathanmelech.', 'from 5414 and 4428; given of (the) king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5420]', 'root', 'heb', 'נָתַס', '["nâthâç"]', '["to tear up mar."]', '["v"]', 'to tear up mar.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5421}/[H5421]', 'lemma', 'heb', 'נָתַע', '["nâthaʻ"]', '["to tear out break."]', '["v"]', 'to tear out break.', 'for 5422;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5422]', 'root', 'heb', 'נָתַץ', '["nâthats"]', '["to tear down beat down, break down (out), cast down, destroy, overthrow, pull down, throw down."]', '["v"]', 'to tear down beat down, break down (out), cast down, destroy, overthrow, pull down, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5423]', 'root', 'heb', 'נָתַק', '["nâthaq"]', '["to tear off break (off), burst, draw (away), lift up, pluck (away, off), pull (out), root out."]', '["v"]', 'to tear off break (off), burst, draw (away), lift up, pluck (away, off), pull (out), root out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5424}/[H5424]', 'lemma', 'heb', 'נֶתֶק', '["netheq"]', '["scurf (dry) scall."]', '["n-m"]', 'scurf (dry) scall.', 'from 5423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5425]', 'root', 'heb', 'נָתַר', '["nâthar"]', '["to jump, i.e. be violently agitated; causatively, to terrify, shake off, untie drive asunder, leap, (let) loose, × make, move, undo."]', '["v"]', 'to jump, i.e. be violently agitated; causatively, to terrify, shake off, untie drive asunder, leap, (let) loose, × make, move, undo.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5426}/[H5426]', 'lemma', 'arc', 'נְתַר', '["nᵉthar"]', '["shake off."]', '["v"]', 'shake off.', '(Aramaic) corresponding to 5425');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5427}/[H5427]', 'lemma', 'heb', 'נֶתֶר', '["nether"]', '["mineral potash (so called from effervescing with acid) nitre."]', '["n-m"]', 'mineral potash (so called from effervescing with acid) nitre.', 'from 5425;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5428]', 'root', 'heb', 'נָתַשׁ', '["nâthash"]', '["to tear away destroy, forsake, pluck (out, up, by the roots), pull up, root out (up), × utterly. s"]', '["v"]', 'to tear away destroy, forsake, pluck (out, up, by the roots), pull up, root out (up), × utterly. s', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5430}/[H5430]', 'lemma', 'heb', 'סְאוֹן', '["çᵉʼôwn"]', '["perhaps a military boot (as a protection from mud) battle."]', '["n-m"]', 'perhaps a military boot (as a protection from mud) battle.', 'from 5431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5431]', 'root', 'heb', 'סָאַן', '["çâʼan"]', '["to shoe, i.e. (active participle) a soldier shod warrior."]', '["v"]', 'to shoe, i.e. (active participle) a soldier shod warrior.', 'a primitive root; to be miry; used only as denominative from 5430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5432}/[H5432]', 'lemma', 'heb', 'סַאסְּאָה', '["çaʼçᵉʼâh"]', '["measurement, i.e. moderation measure."]', '["v"]', 'measurement, i.e. moderation measure.', 'for 5429;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5433]', 'root', 'heb', 'סָבָא', '["çâbâʼ"]', '["to quaff to satiety, i.e. become tipsy drunkard, fill self, Sabean, (wine-) bibber."]', '["v"]', 'to quaff to satiety, i.e. become tipsy drunkard, fill self, Sabean, (wine-) bibber.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5434>', 'opaque', 'heb', 'סְבָא', '["Çᵉbâʼ"]', '["Seba, a son of Cush, and the country settled by him Seba."]', '["n-pr-m n-pr-loc"]', 'Seba, a son of Cush, and the country settled by him Seba.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5435}/[H5435]', 'lemma', 'heb', 'סֹבֶא', '["çôbeʼ"]', '["potation, concretely (wine), or abstractly (carousal) drink, drunken, wine."]', '["n-m"]', 'potation, concretely (wine), or abstractly (carousal) drink, drunken, wine.', 'from 5433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5436}/[H5436]', 'lemma', 'heb', 'סְבָאִי', '["Çᵉbâʼîy"]', '["a Sebaite, or inhabitant of Seba Sabean."]', '["n"]', 'a Sebaite, or inhabitant of Seba Sabean.', 'patrial from 5434;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5437]', 'root', 'heb', 'סָבַב', '["çâbab"]', '["to revolve, surround, or border; used in various applications, literally and figuratively bring, cast, fetch, lead, make, walk, × whirl, × round about, be about on every side, apply, avoid, beset (about), besiege, bring again, carry (about), change, cause to come about, × circuit, (fetch a) compass (about, round), drive, environ, × on every side, beset (close, come, compass, go, stand) round about, inclose, remove, return, set, sit down, turn (self) (about, aside, away, back)."]', '["v"]', 'to revolve, surround, or border; used in various applications, literally and figuratively bring, cast, fetch, lead, make, walk, × whirl, × round about, be about on every side, apply, avoid, beset (about), besiege, bring again, carry (about), change, cause to come about, × circuit, (fetch a) compass (about, round), drive, environ, × on every side, beset (close, come, compass, go, stand) round about, inclose, remove, return, set, sit down, turn (self) (about, aside, away, back).', 'a primitive root;');
