INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5518]', 'root', 'heb', 'סִיר', '["çîyr"]', '["a pot; also a thorn (as springing up rapidly); by implication, a hook caldron, fishhook, pan, (wash-)pot, thorn."]', '["n-m"]', 'a pot; also a thorn (as springing up rapidly); by implication, a hook caldron, fishhook, pan, (wash-)pot, thorn.', 'or (feminine) סִירָה; or סִרָה; (Jeremiah 52:18), from a primitive root meaning to boil up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5519}/[H5519]', 'lemma', 'heb', 'סָךְ', '["çâk"]', '["properly, a thicket of men, i.e. a crowd multitude."]', '["n-m"]', 'properly, a thicket of men, i.e. a crowd multitude.', 'from 5526;');
