INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5522}/[H5522]', 'lemma', 'heb', 'סִכּוּת', '["çikkûwth"]', '["an (idolatrous) booth tabernacle."]', '["n-pr-f"]', 'an (idolatrous) booth tabernacle.', 'feminine of 5519;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5523}/[H5523]', 'lemma', 'heb', 'סֻכּוֹת', '["Çukkôwth"]', '["Succoth, the name of a place in Egypt and of three in Palestine Succoth."]', '["n-pr-loc"]', 'Succoth, the name of a place in Egypt and of three in Palestine Succoth.', 'or סֻכֹּת; plural of 5521; booths;');
