INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5554}/[H5554]', 'lemma', 'heb', 'סֶלַע', '["Çelaʻ"]', '["Sela, the rock-city of Idumaea rock, Sela(-h)."]', '["n-pr-loc"]', 'Sela, the rock-city of Idumaea rock, Sela(-h).', 'the same as 5553;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5555}/[H5555]', 'lemma', 'heb', 'סֶלַע הַמַּחְלְקוֹת', '["Çelaʻ ham-machlᵉqôwth"]', '["Sela-ham-Machlekoth, a place in Palestine Sela-hammalekoth."]', '["n-pr-loc"]', 'Sela-ham-Machlekoth, a place in Palestine Sela-hammalekoth.', 'from 5553 and the plural of 4256 with the article interposed; rock of the divisions;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5556}/[H5556]', 'lemma', 'heb', 'סׇלְעָם', '["çolʻâm"]', '["a kind of locust (from its destructiveness) bald locust."]', '["n-m"]', 'a kind of locust (from its destructiveness) bald locust.', 'apparently from the same as 5553 in the sense of crushing as with a rock, i.e. consuming;');
