INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5594]', 'root', 'heb', 'סָפַד', '["çâphad"]', '["properly, to tear the hair and beat the breasts (as Orientals do in grief); generally to lament; by implication, to wail lament, mourn(-er), wail."]', '["v"]', 'properly, to tear the hair and beat the breasts (as Orientals do in grief); generally to lament; by implication, to wail lament, mourn(-er), wail.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5595]', 'root', 'heb', 'סָפָה', '["çâphâh"]', '["properly, to scrape (literally, to shave; but usually figuratively) together (i.e. to accumulate or increase) or away (i.e. to scatter, remove, or ruin; intransitively, to perish) add, augment, consume, destroy, heap, join, perish, put."]', '["v"]', 'properly, to scrape (literally, to shave; but usually figuratively) together (i.e. to accumulate or increase) or away (i.e. to scatter, remove, or ruin; intransitively, to perish) add, augment, consume, destroy, heap, join, perish, put.', 'a primitive root;');
