INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5603]', 'root', 'heb', 'סָפַן', '["çâphan"]', '["to hide by covering; specifically, to roof (passive participle as noun, a roof) or wainscot; figuratively, to reserve cieled, cover, seated."]', '["v"]', 'to hide by covering; specifically, to roof (passive participle as noun, a roof) or wainscot; figuratively, to reserve cieled, cover, seated.', 'a primitive root;');
