INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5640]', 'root', 'heb', 'סָתַם', '["çâtham"]', '["to stop up; by implication, to repair; figuratively, to keep secret closed up, hidden, secret, shut out (up), stop."]', '["v"]', 'to stop up; by implication, to repair; figuratively, to keep secret closed up, hidden, secret, shut out (up), stop.', 'or שָׂתַם; (Numbers 24:15), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5641]', 'root', 'heb', 'סָתַר', '["çâthar"]', '["to hide (by covering), literally or figuratively be absent, keep close, conceal, hide (self), (keep) secret, × surely."]', '["v"]', 'to hide (by covering), literally or figuratively be absent, keep close, conceal, hide (self), (keep) secret, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5642}/[H5642]', 'lemma', 'arc', 'סְתַר', '["çᵉthar"]', '["to conceal; figuratively, to demolish destroy, secret thing."]', '["v"]', 'to conceal; figuratively, to demolish destroy, secret thing.', '(Aramaic) corresponding to 5641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5643}/[H5643]', 'lemma', 'heb', 'סֵתֶר', '["çêther"]', '["a cover (in a good or a bad, a literal or a figurative sense) backbiting, covering, covert, × disguise(-th), hiding place, privily, protection, secret(-ly, place)."]', '["n-m"]', 'a cover (in a good or a bad, a literal or a figurative sense) backbiting, covering, covert, × disguise(-th), hiding place, privily, protection, secret(-ly, place).', 'or (feminine) סִתְרָה; (Deuteronomy 32:38), from 5641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5644}/[H5644]', 'lemma', 'heb', 'סִתְרִי', '["Çithrîy"]', '["Sithri, an Israelite, Zithri."]', '["n-pr-m"]', 'Sithri, an Israelite, Zithri.', 'from 5643; protective;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5645}/[H5645]', 'lemma', 'heb', 'עָב', '["ʻâb"]', '["properly, an envelope, i.e. darkness (or density, 2 Chronicles 4:17); specifically, a (scud) cloud; also a copse clay, (thick) cloud, × thick, thicket. Compare 5672."]', '["n-m"]', 'properly, an envelope, i.e. darkness (or density, 2 Chronicles 4:17); specifically, a (scud) cloud; also a copse clay, (thick) cloud, × thick, thicket. Compare 5672.', '(masculine and feminine); from 5743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5646>', 'opaque', 'heb', 'עָב', '["ʻâb"]', '["an architrave (as shading the pillars) thick (beam, plant)."]', '["n-m"]', 'an architrave (as shading the pillars) thick (beam, plant).', 'or עֹב; from an unused root meaning to cover; properly, equivalent to 5645; but used only as an architectural term,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5647]', 'root', 'heb', 'עָבַד', '["ʻâbad"]', '["to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5648}/[H5648]', 'lemma', 'arc', 'עֲבַד', '["ʻăbad"]', '["to do, make, prepare, keep, etc. × cut, do, execute, go on, make, move, work."]', '["v"]', 'to do, make, prepare, keep, etc. × cut, do, execute, go on, make, move, work.', '(Aramaic) corresponding to 5647;');
