INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5655}/[H5655]', 'lemma', 'heb', 'עַבְדְּאֵל', '["ʻAbdᵉʼêl"]', '["Abdeel, an Israelite Abdeel. Compare 5661."]', '["n-pr-m"]', 'Abdeel, an Israelite Abdeel. Compare 5661.', 'from 5647 and 410; serving God;');
