INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5661}/[H5661]', 'lemma', 'heb', 'עַבְדִיאֵל', '["ʻAbdîyʼêl"]', '["Abdiel, an Israelite Abdiel. Compare 5655."]', '["n-pr-m"]', 'Abdiel, an Israelite Abdiel. Compare 5655.', 'from 5650 and 410; servant of God;');
