INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5663}/[H5663]', 'lemma', 'heb', 'עֶבֶד מֶלֶךְ', '["ʻEbed Melek"]', '["Ebed-Melek, a eunuch of Zedekeah Ebed-melech."]', '["n-pr-m"]', 'Ebed-Melek, a eunuch of Zedekeah Ebed-melech.', 'from 5650 and 4428; servant of a king;');
