INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5666]', 'root', 'heb', 'עָבָה', '["ʻâbâh"]', '["to be dense be (grow) thick(-er)."]', '["v"]', 'to be dense be (grow) thick(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5667}/[H5667]', 'lemma', 'heb', 'עֲבוֹט', '["ʻăbôwṭ"]', '["a pawn pledge."]', '["n-m"]', 'a pawn pledge.', 'or עֲבֹט; from 5670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5668}/[H5668]', 'lemma', 'heb', 'עָבוּר', '["ʻâbûwr"]', '["properly, crossed, i.e. (abstractly) transit; used only adverbially, on account of, in order that because of, for (...''s sake), (intent) that, to."]', '["prep"]', 'properly, crossed, i.e. (abstractly) transit; used only adverbially, on account of, in order that because of, for (...''s sake), (intent) that, to.', 'or עָבֻר; passive participle of 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5669}/[H5669]', 'lemma', 'heb', 'עָבוּר', '["ʻâbûwr"]', '["passed, i.e. kept over; used only of stored grain old corn."]', '["n-m"]', 'passed, i.e. kept over; used only of stored grain old corn.', 'the same as 5668;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5670]', 'root', 'heb', 'עָבַט', '["ʻâbaṭ"]', '["to pawn; causatively, to lend (on security); figuratively, to entangle borrow, break (ranks), fetch (a pledge), lend, × surely."]', '["v"]', 'to pawn; causatively, to lend (on security); figuratively, to entangle borrow, break (ranks), fetch (a pledge), lend, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5671}/[H5671]', 'lemma', 'heb', 'עַבְטִיט', '["ʻabṭîyṭ"]', '["something pledged, i.e. (collectively) pawned goods thick clay (by a false etym.)."]', '["n-m"]', 'something pledged, i.e. (collectively) pawned goods thick clay (by a false etym.).', 'from 5670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5672}/[H5672]', 'lemma', 'heb', 'עֲבִי', '["ʻăbîy"]', '["density, i.e. depth or width thick(-ness). Compare 5645."]', '["n-m"]', 'density, i.e. depth or width thick(-ness). Compare 5645.', 'or עֳבִי]; from 5666;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5673}/[H5673]', 'lemma', 'arc', 'עֲבִידָה', '["ʻăbîydâh"]', '["labor or business affairs, service, work."]', '["n-f"]', 'labor or business affairs, service, work.', '(Aramaic) from 5648;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5674]', 'root', 'heb', 'עָבַר', '["ʻâbar"]', '["to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath."]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5675}/[H5675]', 'lemma', 'arc', 'עֲבַר', '["ʻăbar"]', '["beyond, this side."]', '["n-m"]', 'beyond, this side.', '(Aramaic) corresponding to 5676');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5676}/[H5676]', 'lemma', 'heb', 'עֵבֶר', '["ʻêber"]', '["properly, a region across; but used only adverbially (with or without a preposition) on the opposite side (especially of the Jordan; ususally meaning the east) × against, beyond, by, × from, over, passage, quarter, (other, this) side, straight."]', '["n-m"]', 'properly, a region across; but used only adverbially (with or without a preposition) on the opposite side (especially of the Jordan; ususally meaning the east) × against, beyond, by, × from, over, passage, quarter, (other, this) side, straight.', 'from 5674;');
