INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5688}/[H5688]', 'lemma', 'heb', 'עֲבֹת', '["ʻăbôth"]', '["something intwined, i.e. a string, wreath or foliage band, cord, rope, thick bough (branch), wreathen (chain)."]', '["n"]', 'something intwined, i.e. a string, wreath or foliage band, cord, rope, thick bough (branch), wreathen (chain).', 'or עֲבוֹת; or (feminine) עֲבֹתָה; the same as 5687;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5689]', 'root', 'heb', 'עֲגַב', '["ʻăgab"]', '["to breathe after, i.e. to love (sensually) dote, lover."]', '["v"]', 'to breathe after, i.e. to love (sensually) dote, lover.', 'a primitive root;');
