INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5695}/[H5695]', 'lemma', 'heb', 'עֵגֶל', '["ʻêgel"]', '["a (male) calf (as frisking round), especially one nearly grown (i.e. a steer) bullock, calf."]', '["n-m"]', 'a (male) calf (as frisking round), especially one nearly grown (i.e. a steer) bullock, calf.', 'from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5697}/[H5697]', 'lemma', 'heb', 'עֶגְלָה', '["ʻeglâh"]', '["a (female) calf, especially one nearly grown (i.e. a heifer) calf, cow, heifer."]', '["n-f"]', 'a (female) calf, especially one nearly grown (i.e. a heifer) calf, cow, heifer.', 'feminine of 5695;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5698}/[H5698]', 'lemma', 'heb', 'עֶגְלָה', '["ʻEglâh"]', '["Eglah, a wife of David Eglah."]', '["n-pr-f"]', 'Eglah, a wife of David Eglah.', 'the same as 5697;');
