INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5702]', 'root', 'heb', 'עָגַן', '["ʻâgan"]', '["to debar, i.e. from marriage stay."]', '["v"]', 'to debar, i.e. from marriage stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5703}/[H5703]', 'lemma', 'heb', 'עַד', '["ʻad"]', '["properly, a (peremptory) terminus, i.e. (by implication) duration, in the sense of advance or perpetuity (substantially as a noun, either with or without a preposition) eternity, ever(-lasting, -more), old, perpetually, world without end."]', '["n-m"]', 'properly, a (peremptory) terminus, i.e. (by implication) duration, in the sense of advance or perpetuity (substantially as a noun, either with or without a preposition) eternity, ever(-lasting, -more), old, perpetually, world without end.', 'from 5710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5704}/[H5704]', 'lemma', 'heb', 'עַד', '["ʻad"]', '["as far (or long, or much) as, whether of space (even unto) or time (during, while, until) or degree (equally with) against, and, as, at, before, by (that), even (to), for(-asmuch as), (hither-) to, how long, into, as long (much) as, (so) that, till, toward, until, when, while, ( as) yet."]', '["prep"]', 'as far (or long, or much) as, whether of space (even unto) or time (during, while, until) or degree (equally with) against, and, as, at, before, by (that), even (to), for(-asmuch as), (hither-) to, how long, into, as long (much) as, (so) that, till, toward, until, when, while, ( as) yet.', 'properly, the same as 5703 (used as a preposition, adverb or conjunction; especially with a preposition);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5705}/[H5705]', 'lemma', 'arc', 'עַד', '["ʻad"]', '["× and, at, for, (hither-) to, on till, (un-) to, until, within."]', '["prt"]', '× and, at, for, (hither-) to, on till, (un-) to, until, within.', '(Aramaic) corresponding to 5704');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5706}/[H5706]', 'lemma', 'heb', 'עַד', '["ʻad"]', '["booty prey."]', '["n-m"]', 'booty prey.', 'the same as 5703 in the sense of the aim of an attack;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5707}/[H5707]', 'lemma', 'heb', 'עֵד', '["ʻêd"]', '["concretely, a witness; abstractly, testimony; specifically, a recorder, i.e. prince witness."]', '["n-m"]', 'concretely, a witness; abstractly, testimony; specifically, a recorder, i.e. prince witness.', 'contracted from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5709}/[H5709]', 'lemma', 'arc', 'עֲדָא', '["ʻădâʼ"]', '["alter, depart, pass (away), remove, take (away)."]', '["v"]', 'alter, depart, pass (away), remove, take (away).', '(Aramaic) or עֲדָה; (Aramaic), corresponding to 5710');
