INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5732}/[H5732]', 'lemma', 'arc', 'עִדָּן', '["ʻiddân"]', '["a set time; technically, a year time."]', '["n-m"]', 'a set time; technically, a year time.', '(Aramaic) from a root corresponding to that of 5708;');
