INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5734}/[H5734]', 'lemma', 'heb', 'עַדְנָה', '["ʻAdnâh"]', '["Adnah, the name of two Israelites Adnah."]', '["n-pr-m"]', 'Adnah, the name of two Israelites Adnah.', 'from 5727; pleasure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5735}/[H5735]', 'lemma', 'heb', 'עֲדְעָדָה', '["ʻĂdʻâdâh"]', '["Adadah, a place in Palestine Adadah."]', '["n-pr-loc"]', 'Adadah, a place in Palestine Adadah.', 'from 5712; festival;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5736]', 'root', 'heb', 'עֲדַף', '["ʻădaph"]', '["to be (causatively have) redundant be more, odd number, be (have) over (and above), overplus, remain."]', '["v"]', 'to be (causatively have) redundant be more, odd number, be (have) over (and above), overplus, remain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5737]', 'root', 'heb', 'עֲדַר', '["ʻădar"]', '["to arrange, as a battle, a vineyard (to hoe); hence, to muster and so to miss (or find wanting) dig, fail, keep (rank), lack."]', '["v"]', 'to arrange, as a battle, a vineyard (to hoe); hence, to muster and so to miss (or find wanting) dig, fail, keep (rank), lack.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5738}/[H5738]', 'lemma', 'heb', 'עֶדֶר', '["ʻEder"]', '["Eder, an Israelite Ader."]', '["n-pr-m"]', 'Eder, an Israelite Ader.', 'from 5737; an arrangement (i.e. drove);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5739}/[H5739]', 'lemma', 'heb', 'עֵדֶר', '["ʻêder"]', '["an arrangement, i.e. muster (of animals) drove, flock, herd."]', '["n-m"]', 'an arrangement, i.e. muster (of animals) drove, flock, herd.', 'from 5737;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5740}/[H5740]', 'lemma', 'heb', 'עֵדֶר', '["ʻÊder"]', '["Eder, the name of an Israelite and of two places in Palestine Edar, Eder."]', '["n-pr-m n-pr-loc"]', 'Eder, the name of an Israelite and of two places in Palestine Edar, Eder.', 'the same as 5739;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5741}/[H5741]', 'lemma', 'heb', 'עַדְרִיאֵל', '["ʻAdrîyʼêl"]', '["Adriel, an Israelite Adriel."]', '["n-pr-m"]', 'Adriel, an Israelite Adriel.', 'from 5739 and 410; flock of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5743]', 'root', 'heb', 'עוּב', '["ʻûwb"]', '["to be dense or dark, i.e. to becloud cover with a cloud."]', '["v"]', 'to be dense or dark, i.e. to becloud cover with a cloud.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5744}/[H5744]', 'lemma', 'heb', 'עוֹבֵד', '["ʻÔwbêd"]', '["Obed, the name of five Israelites Obed."]', '["n-pr-m"]', 'Obed, the name of five Israelites Obed.', 'active participle of 5647; serving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5746]', 'root', 'heb', 'עוּג', '["ʻûwg"]', '["to bake (round cakes on the hearth) bake."]', '["v"]', 'to bake (round cakes on the hearth) bake.', 'a primitive root; properly, to gyrate; but used only as a denominative from 5692,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5747}/[H5747]', 'lemma', 'heb', 'עוֹג', '["ʻÔwg"]', '["Og, a king of Bashan Og."]', '["n-pr-m"]', 'Og, a king of Bashan Og.', 'probably from 5746; round;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5748}/[H5748]', 'lemma', 'heb', 'עוּגָב', '["ʻûwgâb"]', '["a reed-instrument of music organ."]', '["n-m"]', 'a reed-instrument of music organ.', 'or עֻגָּב; from 5689 in the original sense of breathing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5749]', 'root', 'heb', 'עוּד', '["ʻûwd"]', '["to duplicate or repeat; by implication, to protest, testify (as by reiteration); intensively, to encompass, restore (as a sort of reduplication) admonish, charge, earnestly, lift up, protest, call (take) to record, relieve, rob, solemnly, stand upright, testify, give warning, (bear, call to, give, take to) witness."]', '["v"]', 'to duplicate or repeat; by implication, to protest, testify (as by reiteration); intensively, to encompass, restore (as a sort of reduplication) admonish, charge, earnestly, lift up, protest, call (take) to record, relieve, rob, solemnly, stand upright, testify, give warning, (bear, call to, give, take to) witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5750}/[H5750]', 'lemma', 'heb', 'עוֹד', '["ʻôwd"]', '["properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within)."]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5751}/[H5751]', 'lemma', 'arc', 'עוֹד', '["ʻôwd"]', '["while."]', '["adv"]', 'while.', '(Aramaic) corresponding to 5750');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5752}/[H5752]', 'lemma', 'heb', 'עוֹדֵד', '["ʻÔwdêd"]', '["Oded, the name of two Israelites Oded."]', '["n-pr-m"]', 'Oded, the name of two Israelites Oded.', 'or עֹדֵד; from 5749; reiteration;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5753]', 'root', 'heb', 'עָוָה', '["ʻâvâh"]', '["to crook, literally or figuratively do amiss, bow down, make crooked, commit iniquity, pervert, (do) perverse(-ly), trouble, × turn, do wickedly, do wrong."]', '["v"]', 'to crook, literally or figuratively do amiss, bow down, make crooked, commit iniquity, pervert, (do) perverse(-ly), trouble, × turn, do wickedly, do wrong.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5754}/[H5754]', 'lemma', 'heb', 'עַוָּה', '["ʻavvâh"]', '["overthrow × overturn."]', '["n-f"]', 'overthrow × overturn.', 'intensive from 5753 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5755}/[H5755]', 'lemma', 'heb', 'עִוָּה', '["ʻIvvâh"]', '["Ivvah or Avva, a region of Assyria Ava, Ivah."]', '["n-pr-loc"]', 'Ivvah or Avva, a region of Assyria Ava, Ivah.', 'or עַוָּא; (2 Kings 17:24), for 5754;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5756]', 'root', 'heb', 'עוּז', '["ʻûwz"]', '["to be strong; causatively, to strengthen, i.e. (figuratively) to save (by flight) gather (self, self to flee), retire."]', '["v"]', 'to be strong; causatively, to strengthen, i.e. (figuratively) to save (by flight) gather (self, self to flee), retire.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5757}/[H5757]', 'lemma', 'heb', 'עַוִּי', '["ʻAvvîy"]', '["an Avvite or native of Avvah (only plural) Avims, Avites."]', '["a"]', 'an Avvite or native of Avvah (only plural) Avims, Avites.', 'patrial from 5755;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5758}/[H5758]', 'lemma', 'arc', 'עִוְיָא', '["ʻivyâʼ"]', '["perverseness iniquity."]', '["n-f"]', 'perverseness iniquity.', '(Aramaic) from a root corresponding to 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5759}/[H5759]', 'lemma', 'heb', 'עֲוִיל', '["ʻăvîyl"]', '["a babe young child, little one."]', '["n-m"]', 'a babe young child, little one.', 'from 5764;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5760}/[H5760]', 'lemma', 'heb', 'עֲוִיל', '["ʻăvîyl"]', '["perverse (morally) ungodly."]', '["n-m"]', 'perverse (morally) ungodly.', 'from 5765;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5761}/[H5761]', 'lemma', 'heb', 'עַוִּים', '["ʻAvvîym"]', '["Avvim (as inhabited by Avvites), a place in Palestine (with the article prefix) Avim."]', '["n-pr-m n-pr-loc"]', 'Avvim (as inhabited by Avvites), a place in Palestine (with the article prefix) Avim.', 'plural of 5757;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5762}/[H5762]', 'lemma', 'heb', 'עֲוִית', '["ʻĂvîyth"]', '["Avvith (or Avvoth), a place in Palestine Avith."]', '["n-pr-loc"]', 'Avvith (or Avvoth), a place in Palestine Avith.', 'or perhaps (עַיּוֹת (as if plural of 5857) (עַיוּת; from 5753; ruin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5763]', 'root', 'heb', 'עוּל', '["ʻûwl"]', '["to suckle, i.e. give milk milch, (ewe great) with young."]', '["v"]', 'to suckle, i.e. give milk milch, (ewe great) with young.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5764}/[H5764]', 'lemma', 'heb', 'עוּל', '["ʻûwl"]', '["a babe sucking child, infant."]', '["n-m"]', 'a babe sucking child, infant.', 'from 5763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5765]', 'root', 'heb', 'עֲוַל', '["ʻăval"]', '["to distort (morally) deal unjustly, unrighteous."]', '["v"]', 'to distort (morally) deal unjustly, unrighteous.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5766}/[H5766]', 'lemma', 'heb', 'עֶוֶל', '["ʻevel"]', '["(moral) evil iniquity, perverseness, unjust(-ly), unrighteousness(-ly); wicked(-ness)."]', '["n-m"]', '(moral) evil iniquity, perverseness, unjust(-ly), unrighteousness(-ly); wicked(-ness).', 'or עָוֶל; and (feminine) עַוְלָה; or עוֹלָה; or עֹלָה; from 5765;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5767}/[H5767]', 'lemma', 'heb', 'עַוָּל', '["ʻavvâl"]', '["evil (morally) unjust, unrighteous, wicked."]', '["n-m"]', 'evil (morally) unjust, unrighteous, wicked.', 'intensive from 5765;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5768}/[H5768]', 'lemma', 'heb', 'עוֹלֵל', '["ʻôwlêl"]', '["a suckling babe, (young) child, infant, little one."]', '["n-m"]', 'a suckling babe, (young) child, infant, little one.', 'or עֹלָל; from 5763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5769}/[H5769]', 'lemma', 'heb', 'עוֹלָם', '["ʻôwlâm"]', '["properly, concealed, i.e. the vanishing point; generally, time out of mind (past or future), i.e. (practically) eternity; frequentatively, adverbial (especially with prepositional prefix) always alway(-s), ancient (time), any more, continuance, eternal, (for, (n-)) ever(-lasting, -more, of old), lasting, long (time), (of) old (time), perpetual, at any time, (beginning of the) world ( without end). Compare 5331, 5703."]', '["n-m"]', 'properly, concealed, i.e. the vanishing point; generally, time out of mind (past or future), i.e. (practically) eternity; frequentatively, adverbial (especially with prepositional prefix) always alway(-s), ancient (time), any more, continuance, eternal, (for, (n-)) ever(-lasting, -more, of old), lasting, long (time), (of) old (time), perpetual, at any time, (beginning of the) world ( without end). Compare 5331, 5703.', 'or עֹלָם; from 5956;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5770}/[H5770]', 'lemma', 'heb', 'עָוַן', '["ʻâvan"]', '["to watch (with jealosy) eye."]', '["v"]', 'to watch (with jealosy) eye.', 'denominative from 5869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5771}/[H5771]', 'lemma', 'heb', 'עָוֺן', '["ʻâvôn"]', '["perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin."]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5772>', 'opaque', 'heb', 'עוֹנָה', '["ʻôwnâh"]', '["(sexual) cohabitation duty of marriage."]', '["n-f"]', '(sexual) cohabitation duty of marriage.', 'from an unused root apparently meaning to dwell together;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5773}/[H5773]', 'lemma', 'heb', 'עַוְעֶה', '["ʻavʻeh"]', '["perversity × perverse."]', '["n-m"]', 'perversity × perverse.', 'from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5774]', 'root', 'heb', 'עוּף', '["ʻûwph"]', '["to fly; also (by implication of dimness) to faint (from the darkness of swooning) brandish, be (wax) faint, flee away, fly (away), × set, shine forth, weary."]', '["v n-f"]', 'to fly; also (by implication of dimness) to faint (from the darkness of swooning) brandish, be (wax) faint, flee away, fly (away), × set, shine forth, weary.', 'a primitive root; to cover (with wings or obscurity); hence (as denominative from 5775)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5775}/[H5775]', 'lemma', 'heb', 'עוֹף', '["ʻôwph"]', '["a bird (as covered with feathers, or rather as covering with wings), often collectively bird, that flieth, flying, fowl."]', '["n-m"]', 'a bird (as covered with feathers, or rather as covering with wings), often collectively bird, that flieth, flying, fowl.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5776}/[H5776]', 'lemma', 'arc', 'עוֹף', '["ʻôwph"]', '["fowl."]', '["n-m"]', 'fowl.', '(Aramaic) corresponding to 5775');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5777}/[H5777]', 'lemma', 'heb', 'עוֹפֶרֶת', '["ʻôwphereth"]', '["lead (from its dusty color) lead."]', '["n-m"]', 'lead (from its dusty color) lead.', 'or עֹפֶרֶת; feminine participle active of 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5778}/[H5778]', 'lemma', 'heb', 'עוֹפַי', '["ʻÔwphay"]', '["Ephai, an Israelite Ephai (from margin)."]', '["n-pr-m"]', 'Ephai, an Israelite Ephai (from margin).', 'from 5775; birdlike;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5779]', 'root', 'heb', 'עוּץ', '["ʻûwts"]', '["to consult take advice ((counsel) together)."]', '["v"]', 'to consult take advice ((counsel) together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5780}/[H5780]', 'lemma', 'heb', 'עוּץ', '["ʻÛwts"]', '["Uts, a son of Aram, also a Seirite, and the regions settled by them. Uz."]', '["n-pr-m n-pr-loc"]', 'Uts, a son of Aram, also a Seirite, and the regions settled by them. Uz.', 'apparently from 5779; consultation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5781]', 'root', 'heb', 'עוּק', '["ʻûwq"]', '["to pack be pressed."]', '["v"]', 'to pack be pressed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5782]', 'root', 'heb', 'עוּר', '["ʻûwr"]', '["to wake (literally or figuratively) (a-) wake(-n, up), lift up (self), × master, raise (up), stir up (self)."]', '["v"]', 'to wake (literally or figuratively) (a-) wake(-n, up), lift up (self), × master, raise (up), stir up (self).', 'a primitive root (rather identical with through the idea of opening the eyes);');
