INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5890}/[H5890]', 'lemma', 'heb', 'עֵיפָה', '["ʻêyphâh"]', '["obscurity (as if from covering) darkness."]', '["n-f"]', 'obscurity (as if from covering) darkness.', 'feminine from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5891}/[H5891]', 'lemma', 'heb', 'עֵיפָה', '["ʻÊyphâh"]', '["Ephah, the name of a son of Midian, and of the region settled by him; also of an Israelite and of an Israelitess Ephah."]', '["n-pr-m n-pr-f"]', 'Ephah, the name of a son of Midian, and of the region settled by him; also of an Israelite and of an Israelitess Ephah.', 'the same as 5890;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5892}/[H5892]', 'lemma', 'heb', 'עִיר', '["ʻîyr"]', '["a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town."]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5893}/[H5893]', 'lemma', 'heb', 'עִיר', '["ʻÎyr"]', '["Ir, an Israelite Ir."]', '["n-pr-m"]', 'Ir, an Israelite Ir.', 'the same as 5892;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5894}/[H5894]', 'lemma', 'arc', 'עִיר', '["ʻîyr"]', '["a watcher, i.e. an angel (as guardian) watcher."]', '["n-m"]', 'a watcher, i.e. an angel (as guardian) watcher.', '(Aramaic) from a root corresponding to 5782;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5895}/[H5895]', 'lemma', 'heb', 'עַיִר', '["ʻayir"]', '["properly, a young ass (as just broken to a load); hence an ass-colt (ass) colt, foal, young ass."]', '["n-m"]', 'properly, a young ass (as just broken to a load); hence an ass-colt (ass) colt, foal, young ass.', 'from 5782 in the sense of raising (i.e. bearing a burden);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5896}/[H5896]', 'lemma', 'heb', 'עִירָא', '["ʻÎyrâʼ"]', '["Ira, the name of three Israelites Ira."]', '["n-pr-m"]', 'Ira, the name of three Israelites Ira.', 'from 5782; wakefulness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5897}/[H5897]', 'lemma', 'heb', 'עִירָד', '["ʻÎyrâd"]', '["Irad, an antediluvian Irad."]', '["n-pr-m"]', 'Irad, an antediluvian Irad.', 'from the same as 6166; fugitive;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5898}/[H5898]', 'lemma', 'heb', 'עִיר הַמֶּלַח', '["ʻÎyr ham-Melach"]', '["Irham-Melach, a place near Palestine the city of salt."]', '["n-pr-loc"]', 'Irham-Melach, a place near Palestine the city of salt.', 'from 5892 and 4417 with the article of substance interp.; city of (the) salt;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5899}/[H5899]', 'lemma', 'heb', 'עִיר הַתְּמָרִים', '["ʻÎyr hat-Tᵉmârîym"]', '["Ir-hat-Temarim, a place in Palestine the city of palmtrees."]', '["n-pr-loc"]', 'Ir-hat-Temarim, a place in Palestine the city of palmtrees.', 'from 5892 and the plural of 8558 with the article interpolated; city of the palmtrees;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5900}/[H5900]', 'lemma', 'heb', 'עִירוּ', '["ʻÎyrûw"]', '["Iru, an Israelite Iru."]', '["n-pr-m"]', 'Iru, an Israelite Iru.', 'from 5892; a citizen;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5901}/[H5901]', 'lemma', 'heb', 'עִירִי', '["ʻÎyrîy"]', '["Iri, an Israelite Iri."]', '["n-pr-m"]', 'Iri, an Israelite Iri.', 'from 5892; urbane;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5902}/[H5902]', 'lemma', 'heb', 'עִירָם', '["ʻÎyrâm"]', '["Iram, an Idumaean Iram."]', '["n-pr-m"]', 'Iram, an Idumaean Iram.', 'from 5892; city-wise;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5903}/[H5903]', 'lemma', 'heb', 'עֵירֹם', '["ʻêyrôm"]', '["nudity naked(-ness)."]', '["a"]', 'nudity naked(-ness).', 'or עֵרֹם; from 6191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5904}/[H5904]', 'lemma', 'heb', 'עִיר נָחָשׁ', '["ʻÎyr Nâchâsh"]', '["Ir-Nachash, a place in Palestine Irnahash."]', '["n-pr-m"]', 'Ir-Nachash, a place in Palestine Irnahash.', 'from 5892 and 5175; city of a serpent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5905}/[H5905]', 'lemma', 'heb', 'עִיר שֶׁמֶשׁ', '["ʻÎyr Shemesh"]', '["Ir-Shemesh, a place in Palestine Irshemesh."]', '["n-pr-loc"]', 'Ir-Shemesh, a place in Palestine Irshemesh.', 'from 5892 and 8121; city of the sun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5906}/[H5906]', 'lemma', 'heb', 'עַיִשׁ', '["ʻAyish"]', '["the constellation of the Great Bear (perhaps from its migration through the heavens) Arcturus."]', '["n-f"]', 'the constellation of the Great Bear (perhaps from its migration through the heavens) Arcturus.', 'or עָשׁ; from 5789;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5907}/[H5907]', 'lemma', 'heb', 'עַכְבּוֹר', '["ʻAkbôwr"]', '["Akbor, the name of an Idumaean and of two Israelites Achbor."]', '["n-pr-m"]', 'Akbor, the name of an Idumaean and of two Israelites Achbor.', 'probably for 5909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5909}/[H5909]', 'lemma', 'heb', 'עַכְבָּר', '["ʻakbâr"]', '["a mouse (as nibbling) mouse."]', '["n-m"]', 'a mouse (as nibbling) mouse.', 'probably from the same as 5908 in the secondary sense of attacking;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5911}/[H5911]', 'lemma', 'heb', 'עָכוֹר', '["ʻÂkôwr"]', '["Akor, the name of a place in Palestine Achor."]', '["n-m"]', 'Akor, the name of a place in Palestine Achor.', 'from 5916; troubled;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5913]', 'root', 'heb', 'עָכַס', '["ʻâkaç"]', '["to put on anklets make a tinkling ornament."]', '["v"]', 'to put on anklets make a tinkling ornament.', 'a primitive root; properly, to tie, specifically, with fetters; but used only as denominative from 5914;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5914}/[H5914]', 'lemma', 'heb', 'עֶכֶס', '["ʻekeç"]', '["a fetter; hence, an anklet stocks, tinkling ornament."]', '["n-m"]', 'a fetter; hence, an anklet stocks, tinkling ornament.', 'from 5913;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5915}/[H5915]', 'lemma', 'heb', 'עַכְסָה', '["ʻAkçâh"]', '["Aksah, an Israelitess Achsah."]', '["n-pr-f"]', 'Aksah, an Israelitess Achsah.', 'feminine of 5914; anklet;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5916]', 'root', 'heb', 'עָכַר', '["ʻâkar"]', '["properly, to roil water; figuratively, to disturb or affict trouble, stir."]', '["v"]', 'properly, to roil water; figuratively, to disturb or affict trouble, stir.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5917}/[H5917]', 'lemma', 'heb', 'עָכָר', '["ʻÂkâr"]', '["Akar, an Israelite Achar. Compare 5912."]', '["n-pr-m"]', 'Akar, an Israelite Achar. Compare 5912.', 'from 5916; troublesome;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5918}/[H5918]', 'lemma', 'heb', 'עׇכְרָן', '["ʻOkrân"]', '["Okran, an Israelite Ocran."]', '["n-pr-m"]', 'Okran, an Israelite Ocran.', 'from 5916; muddler;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5920}/[H5920]', 'lemma', 'heb', 'עַל', '["ʻal"]', '["properly, the top; specifically, the Highest (i.e. God); also (adverb) aloft, to Jehovah above, high, most High."]', '["n-m"]', 'properly, the top; specifically, the Highest (i.e. God); also (adverb) aloft, to Jehovah above, high, most High.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5921}/[H5921]', 'lemma', 'heb', 'עַל', '["ʻal"]', '["above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with."]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5922}/[H5922]', 'lemma', 'arc', 'עַל', '["ʻal"]', '["about, against, concerning, for, (there-) fore, from, in, × more, of, (there-, up-) on, (in-) to, why with."]', '["prep"]', 'about, against, concerning, for, (there-) fore, from, in, × more, of, (there-, up-) on, (in-) to, why with.', '(Aramaic) corresponding to 5921');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5923}/[H5923]', 'lemma', 'heb', 'עֹל', '["ʻôl"]', '["a yoke (as imposed on the neck), literally or figuratively yoke."]', '["n-m"]', 'a yoke (as imposed on the neck), literally or figuratively yoke.', 'or עוֹל; from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5924}/[H5924]', 'lemma', 'arc', 'עֵלָּא', '["ʻêllâʼ"]', '["above over."]', '["adv"]', 'above over.', '(Aramaic) from 5922;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5925}/[H5925]', 'lemma', 'heb', 'עֻלָּא', '["ʻUllâʼ"]', '["Ulla, an Israelite Ulla."]', '["n-pr-m"]', 'Ulla, an Israelite Ulla.', 'feminine of 5923; burden;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5927]', 'root', 'heb', 'עָלָה', '["ʻâlâh"]', '["to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work."]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5928}/[H5928]', 'lemma', 'arc', 'עֲלָה', '["ʻălâh"]', '["a holocaust burnt offering."]', '["n-f"]', 'a holocaust burnt offering.', '(Aramaic) corresponding to 5930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5929}/[H5929]', 'lemma', 'heb', 'עָלֶה', '["ʻâleh"]', '["a leaf (as coming up on a tree); collectively, foliage branch, leaf."]', '["n-m"]', 'a leaf (as coming up on a tree); collectively, foliage branch, leaf.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5930}/[H5930]', 'lemma', 'heb', 'עֹלָה', '["ʻôlâh"]', '["a step or (collectively, stairs, as ascending); usually a holocaust (as going up in smoke) ascent, burnt offering (sacrifice), go up to. See also 5766."]', '["n-f"]', 'a step or (collectively, stairs, as ascending); usually a holocaust (as going up in smoke) ascent, burnt offering (sacrifice), go up to. See also 5766.', 'or עוֹלָה; feminine active participle of 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5931}/[H5931]', 'lemma', 'arc', 'עִלָּה', '["ʻillâh"]', '["a pretext (as arising artificially) occasion."]', '["n-f"]', 'a pretext (as arising artificially) occasion.', '(Aramaic) feminine from a root corresponding to 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5932}/[H5932]', 'lemma', 'heb', 'עַלְוָה', '["ʻalvâh"]', '["moral perverseness iniquity."]', '["n-f"]', 'moral perverseness iniquity.', 'for 5766;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5933}/[H5933]', 'lemma', 'heb', 'עַלְוָה', '["ʻAlvâh"]', '["Alvah or Aljah, an Idumaean Aliah, Alvah."]', '["n-pr-m"]', 'Alvah or Aljah, an Idumaean Aliah, Alvah.', 'or עַליָה; the same as 5932;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5934}/[H5934]', 'lemma', 'heb', 'עָלוּם', '["ʻâlûwm"]', '["(only in plural as abstract) adolescence; figuratively, vigor youth."]', '["n-m"]', '(only in plural as abstract) adolescence; figuratively, vigor youth.', 'passive participle of 5956 in the denominative sense of 5958;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5935}/[H5935]', 'lemma', 'heb', 'עַלְוָן', '["ʻAlvân"]', '["Alvan or Aljan, an Idumaean Alian, Alvan."]', '["n-pr-m"]', 'Alvan or Aljan, an Idumaean Alian, Alvan.', 'or עַלְיָן; from 5927; lofty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5936>', 'opaque', 'heb', 'עֲלוּקָה', '["ʻălûwqâh"]', '["the leech horse-leech."]', '["n-f"]', 'the leech horse-leech.', 'feminine passive participle of an unused root meaning to suck;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5937]', 'root', 'heb', 'עָלַז', '["ʻâlaz"]', '["to jump for joy, i.e. exult be joyful, rejoice, triumph."]', '["v"]', 'to jump for joy, i.e. exult be joyful, rejoice, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5938}/[H5938]', 'lemma', 'heb', 'עָלֵז', '["ʻâlêz"]', '["exultant that rejoiceth."]', '["a"]', 'exultant that rejoiceth.', 'from 5937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5939>', 'opaque', 'heb', 'עֲלָטָה', '["ʻălâṭâh"]', '["dusk dark, twilight."]', '["n-f"]', 'dusk dark, twilight.', 'feminine from an unused root meaning to cover;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5940}/[H5940]', 'lemma', 'heb', 'עֱלִי', '["ʻĕlîy"]', '["a pestle (as lifted) pestle."]', '["n-m"]', 'a pestle (as lifted) pestle.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5941}/[H5941]', 'lemma', 'heb', 'עֵלִי', '["ʻÊlîy"]', '["Eli, an Israelite highpriest Eli."]', '["n-pr-m"]', 'Eli, an Israelite highpriest Eli.', 'from 5927; lofty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5942}/[H5942]', 'lemma', 'heb', 'עִלִּי', '["ʻillîy"]', '["high; i.e. comparative upper."]', '["a"]', 'high; i.e. comparative upper.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5943}/[H5943]', 'lemma', 'arc', 'עִלַּי', '["ʻillay"]', '["supreme (i.e. God) (most) high."]', '["a"]', 'supreme (i.e. God) (most) high.', '(Aramaic) corresponding to 5942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5944}/[H5944]', 'lemma', 'heb', 'עֲלִיָּה', '["ʻălîyâh"]', '["something lofty, i.e. a stair-way; also a second-story room (or even one on the roof); figuratively, the sky ascent, (upper) chamber, going up, loft, parlour."]', '["n-f"]', 'something lofty, i.e. a stair-way; also a second-story room (or even one on the roof); figuratively, the sky ascent, (upper) chamber, going up, loft, parlour.', 'feminine from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5945}/[H5945]', 'lemma', 'heb', 'עֶלְיוֹן', '["ʻelyôwn"]', '["an elevation, i.e. (adj.) lofty (compar.); as title, the Supreme (Most, on) high(-er, -est), upper(-most)."]', '["n-m a"]', 'an elevation, i.e. (adj.) lofty (compar.); as title, the Supreme (Most, on) high(-er, -est), upper(-most).', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5946}/[H5946]', 'lemma', 'arc', 'עֶלְיוֹן', '["ʻelyôwn"]', '["the Supreme Most high."]', '["a"]', 'the Supreme Most high.', '(Aramaic) corresponding to 5945;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5947}/[H5947]', 'lemma', 'heb', 'עַלִּיז', '["ʻallîyz"]', '["exultant joyous, (that) rejoice(-ing)"]', '["a"]', 'exultant joyous, (that) rejoice(-ing)', 'from 5937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5948}/[H5948]', 'lemma', 'heb', 'עֲלִיל', '["ʻălîyl"]', '["probably a crucible (as working over the metal) furnace."]', '["n-m"]', 'probably a crucible (as working over the metal) furnace.', 'from 5953 in the sense of completing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5949}/[H5949]', 'lemma', 'heb', 'עֲלִילָה', '["ʻălîylâh"]', '["an exploit (of God), or a performance (of man, often in a bad sense); by implication, an opportunity act(-ion), deed, doing, invention, occasion, work."]', '["n-f"]', 'an exploit (of God), or a performance (of man, often in a bad sense); by implication, an opportunity act(-ion), deed, doing, invention, occasion, work.', 'or עֲלִלָה; from 5953 in the sense of effecting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5950}/[H5950]', 'lemma', 'heb', 'עֲלִילִיָּה', '["ʻălîylîyâh"]', '["(miraculous) execution work."]', '["n-f"]', '(miraculous) execution work.', 'for 5949;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5951}/[H5951]', 'lemma', 'heb', 'עֲלִיצוּת', '["ʻălîytsûwth"]', '["exultation rejoicing."]', '["n-f"]', 'exultation rejoicing.', 'from 5970;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5952}/[H5952]', 'lemma', 'arc', 'עַלִּית', '["ʻallîyth"]', '["a second-story room chamber. Compare 5944."]', '["n-f"]', 'a second-story room chamber. Compare 5944.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5953]', 'root', 'heb', 'עָלַל', '["ʻâlal"]', '["to effect thoroughly; specifically, to glean (also figuratively); by implication (in a bad sense) to overdo, i.e. maltreat, be saucy to, pain, impose (also literal) abuse, affect, × child, defile, do, glean, mock, practise, thoroughly, work (wonderfully)."]', '["v"]', 'to effect thoroughly; specifically, to glean (also figuratively); by implication (in a bad sense) to overdo, i.e. maltreat, be saucy to, pain, impose (also literal) abuse, affect, × child, defile, do, glean, mock, practise, thoroughly, work (wonderfully).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5954}/[H5954]', 'lemma', 'arc', 'עֲלַל', '["ʻălal"]', '["to enter; causatively, to introduce bring in, come in, go in."]', '["v"]', 'to enter; causatively, to introduce bring in, come in, go in.', '(Aramaic) corresponding to 5953 (in the sense of thrusting oneself in),');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5955}/[H5955]', 'lemma', 'heb', 'עֹלֵלָה', '["ʻôlêlâh"]', '["only in plural gleanings; by extension gleaning-time (gleaning) (of the) grapes, grapegleanings."]', '["n-f"]', 'only in plural gleanings; by extension gleaning-time (gleaning) (of the) grapes, grapegleanings.', 'feminine active participle of 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5956]', 'root', 'heb', 'עָלַם', '["ʻâlam"]', '["to veil from sight, i.e. conceal (literally or figuratively) × any ways, blind, dissembler, hide (self), secret (thing)."]', '["v"]', 'to veil from sight, i.e. conceal (literally or figuratively) × any ways, blind, dissembler, hide (self), secret (thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5957}/[H5957]', 'lemma', 'arc', 'עָלַם', '["ʻâlam"]', '["remote time, i.e. the future or past indefinitely; often adverb, forever for (n-)ever (lasting), old."]', '["n-m"]', 'remote time, i.e. the future or past indefinitely; often adverb, forever for (n-)ever (lasting), old.', '(Aramaic) corresponding to 5769;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5958}/[H5958]', 'lemma', 'heb', 'עֶלֶם', '["ʻelem"]', '["properly, something kept out of sight, i.e. a lad young man, stripling."]', '["n-m"]', 'properly, something kept out of sight, i.e. a lad young man, stripling.', 'from 5956; (compare 5959)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5959}/[H5959]', 'lemma', 'heb', 'עַלְמָה', '["ʻalmâh"]', '["a lass (as veiled or private) damsel, maid, virgin."]', '["n-f"]', 'a lass (as veiled or private) damsel, maid, virgin.', 'feminine of 5958;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5960}/[H5960]', 'lemma', 'heb', 'עַלְמוֹן', '["ʻAlmôwn"]', '["Almon, a place in Palestine Almon"]', '["n-pr-loc"]', 'Almon, a place in Palestine Almon', 'from 5956; hidden; See also 5963.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5961}/[H5961]', 'lemma', 'heb', 'עֲלָמוֹת', '["ʻĂlâmôwth"]', '["properly, girls, i.e. the soprano or female voice, perhaps falsetto Alamoth."]', '["n-f"]', 'properly, girls, i.e. the soprano or female voice, perhaps falsetto Alamoth.', 'plural of 5959;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5962}/[H5962]', 'lemma', 'heb', 'עַלְמִי', '["ʻAlmîy"]', '["an Elamite or inhabitant of Elam Elamite."]', '["n"]', 'an Elamite or inhabitant of Elam Elamite.', '(Aramaic) patrial from a name corresponding to 5867 contracted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5963}/[H5963]', 'lemma', 'heb', 'עַלְמֹן דִּבְלָתָיְמָה', '["ʻAlmôn Diblâthâyᵉmâh"]', '["Almon-Diblathajemah, a place in Moab Almondilathaim."]', '["n-pr-loc"]', 'Almon-Diblathajemah, a place in Moab Almondilathaim.', 'from the same as 5960 and the dual of 1960 (compare 1015) with enclitic of direction; Almon towards Diblathajim;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5964}/[H5964]', 'lemma', 'heb', 'עָלֶמֶת', '["ʻÂlemeth"]', '["Alemeth, the name of a place in Palestine and of two Israelites Alameth, Alemeth."]', '["n-pr-m"]', 'Alemeth, the name of a place in Palestine and of two Israelites Alameth, Alemeth.', 'from 5956; a covering;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5965]', 'root', 'heb', 'עָלַס', '["ʻâlaç"]', '["to leap for joy, i.e. exult, wave joyously × peacock, rejoice, solace self."]', '["v"]', 'to leap for joy, i.e. exult, wave joyously × peacock, rejoice, solace self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5966]', 'root', 'heb', 'עָלַע', '["ʻâlaʻ"]', '["to sip up suck up."]', '["v"]', 'to sip up suck up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5967}/[H5967]', 'lemma', 'arc', 'עֲלַע', '["ʻălaʻ"]', '["a rib rib."]', '["n-f"]', 'a rib rib.', '(Aramaic) corresponding to 6763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5968]', 'root', 'heb', 'עָלַף', '["ʻâlaph"]', '["to veil or cover; figuratively, to be languid faint, overlaid, wrap self."]', '["v"]', 'to veil or cover; figuratively, to be languid faint, overlaid, wrap self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5969}/[H5969]', 'lemma', 'heb', 'עֻלְפֶּה', '["ʻulpeh"]', '["an envelope, i.e. (figuratively) mourning fainted."]', '["n-m"]', 'an envelope, i.e. (figuratively) mourning fainted.', 'from 5968;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5970]', 'root', 'heb', 'עָלַץ', '["ʻâlats"]', '["to jump for joy, i.e. exult be joyful, rejoice, triumph."]', '["v"]', 'to jump for joy, i.e. exult be joyful, rejoice, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5971}/[H5971]', 'lemma', 'heb', 'עַם', '["ʻam"]', '["a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people."]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5972}/[H5972]', 'lemma', 'arc', 'עַם', '["ʻam"]', '["people."]', '["n-m"]', 'people.', '(Aramaic) corresponding to 5971');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5973}/[H5973]', 'lemma', 'heb', 'עִם', '["ʻim"]', '["adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al)."]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5974}/[H5974]', 'lemma', 'arc', 'עִם', '["ʻim"]', '["by, from, like, to(-ward), with."]', '["prep"]', 'by, from, like, to(-ward), with.', '(Aramaic) corresponding to 5973');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5975]', 'root', 'heb', 'עָמַד', '["ʻâmad"]', '["to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry."]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5976}/[H5976]', 'lemma', 'heb', 'עָמַד', '["ʻâmad"]', '["to shake be at a stand."]', '["v"]', 'to shake be at a stand.', 'for 4571;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5977}/[H5977]', 'lemma', 'heb', 'עֹמֶד', '["ʻômed"]', '["a spot (as being fixed) place, ( where) stood, upright."]', '["n-m"]', 'a spot (as being fixed) place, ( where) stood, upright.', 'from 5975;');
