INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5979}/[H5979]', 'lemma', 'heb', 'עֶמְדָּה', '["ʻemdâh"]', '["a station, i.e. domicile standing."]', '["n-f"]', 'a station, i.e. domicile standing.', 'from 5975;');
