INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5981}/[H5981]', 'lemma', 'heb', 'עֻמָּה', '["ʻUmmâh"]', '["Ummah, a place in Palestine Ummah."]', '["n-pr-loc"]', 'Ummah, a place in Palestine Ummah.', 'the same as 5980; association;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5982}/[H5982]', 'lemma', 'heb', 'עַמּוּד', '["ʻammûwd"]', '["a column (as standing); also a stand, i.e. platform × apiece, pillar."]', '["n-m"]', 'a column (as standing); also a stand, i.e. platform × apiece, pillar.', 'or עַמֻּד; from 5975;');
