INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5992}/[H5992]', 'lemma', 'heb', 'עַמִּינָדָב', '["ʻAmmîynâdâb"]', '["Amminadab, the name of four Israelites Amminadab."]', '["n-pr-m"]', 'Amminadab, the name of four Israelites Amminadab.', 'from 5971 and 5068; people of liberality;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5993}/[H5993]', 'lemma', 'heb', 'עַמִּי נָדִיב', '["ʻAmmîy Nâdîyb"]', '["Ammi-Nadib, probably an Israelite Amminadib."]', '["n-pr-m"]', 'Ammi-Nadib, probably an Israelite Amminadib.', 'from 5971 and 5081; my people (is) liberal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5994}/[H5994]', 'lemma', 'arc', 'עֲמִיק', '["ʻămîyq"]', '["profound, i.e. unsearchable deep."]', '["a"]', 'profound, i.e. unsearchable deep.', '(Aramaic) corresponding to 6012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5995}/[H5995]', 'lemma', 'heb', 'עָמִיר', '["ʻâmîyr"]', '["a bunch of grain handful, sheaf."]', '["n-m"]', 'a bunch of grain handful, sheaf.', 'from 6014;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5996}/[H5996]', 'lemma', 'heb', 'עַמִּישַׁדַּי', '["ʻAmmîyshadday"]', '["Ammishaddai, an Israelite Ammishaddai."]', '["n-pr-m"]', 'Ammishaddai, an Israelite Ammishaddai.', 'from 5971 and 7706; people of (the) Almighty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5997]', 'root', 'heb', 'עָמִית', '["ʻâmîyth"]', '["companionship; hence (concretely) a comrade or kindred man another, fellow, neighbour."]', '["n-m"]', 'companionship; hence (concretely) a comrade or kindred man another, fellow, neighbour.', 'from a primitive root meaning to associate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H5998]', 'root', 'heb', 'עָמַל', '["ʻâmal"]', '["to toil, i.e. work severely and with irksomeness (take) labour (in)."]', '["v"]', 'to toil, i.e. work severely and with irksomeness (take) labour (in).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5999}/[H5999]', 'lemma', 'heb', 'עָמָל', '["ʻâmâl"]', '["toil, i.e. wearing effort; hence, worry, whether of body or mind grievance(-vousness), iniquity, labour, mischief, miserable(-sery), pain(-ful), perverseness, sorrow, toil, travail, trouble, wearisome, wickedness."]', '["n"]', 'toil, i.e. wearing effort; hence, worry, whether of body or mind grievance(-vousness), iniquity, labour, mischief, miserable(-sery), pain(-ful), perverseness, sorrow, toil, travail, trouble, wearisome, wickedness.', 'from 5998;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6000}/[H6000]', 'lemma', 'heb', 'עָמָל', '["ʻÂmâl"]', '["Amal, an Israelite Amal."]', '["n-pr-m"]', 'Amal, an Israelite Amal.', 'the same as 5999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6001}/[H6001]', 'lemma', 'heb', 'עָמֵל', '["ʻâmêl"]', '["toiling; concretely, a laborer; figuratively, sorrowful that laboureth, that is a misery, had taken (labour), wicked, workman."]', '["n-m a"]', 'toiling; concretely, a laborer; figuratively, sorrowful that laboureth, that is a misery, had taken (labour), wicked, workman.', 'from 5998;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6002>', 'opaque', 'heb', 'עֲמָלֵק', '["ʻĂmâlêq"]', '["Amalek, a descendant of Esau; also his posterity and their country Amalek."]', '["n-pr-m"]', 'Amalek, a descendant of Esau; also his posterity and their country Amalek.', 'probably of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6003}/[H6003]', 'lemma', 'heb', 'עֲמָלֵקִי', '["ʻĂmâlêqîy"]', '["an Amalekite (or collectively the Amalekites) or descendants of Amalek Amalekite(-s)."]', '["a"]', 'an Amalekite (or collectively the Amalekites) or descendants of Amalek Amalekite(-s).', 'patronymically from 6002;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6004]', 'root', 'heb', 'עָמַם', '["ʻâmam"]', '["to associate; by implication, to overshadow (by huddling together) become dim, hide."]', '["v"]', 'to associate; by implication, to overshadow (by huddling together) become dim, hide.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6005}/[H6005]', 'lemma', 'heb', 'עִמָּנוּאֵל', '["ʻImmânûwʼêl"]', '["Immanuel, a type name of Isaiah''s son Immanuel."]', '["n-pr-m"]', 'Immanuel, a type name of Isaiah''s son Immanuel.', 'from 5973 and with a pronominal suffix inserted; with us (is) God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6006]', 'root', 'heb', 'עָמַס', '["ʻâmaç"]', '["to load, i.e. impose a burden (or figuratively, infliction) be borne, (heavy) burden (self), lade, load, put."]', '["v"]', 'to load, i.e. impose a burden (or figuratively, infliction) be borne, (heavy) burden (self), lade, load, put.', 'or עָמַשׂ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6007}/[H6007]', 'lemma', 'heb', 'עֲמַסְיָה', '["ʻĂmaçyâh"]', '["Amasjah, an Israelite Amasiah."]', '["n-pr-m"]', 'Amasjah, an Israelite Amasiah.', 'from 6006 and 3050; Jah has loaded;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6008}/[H6008]', 'lemma', 'heb', 'עַמְעָד', '["ʻAmʻâd"]', '["Amad, a place in Palestine Amad."]', '["n-pr-loc"]', 'Amad, a place in Palestine Amad.', 'from 5971 and 5703; people of time;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6009]', 'root', 'heb', 'עָמַק', '["ʻâmaq"]', '["to be (causatively, make) deep (literally or figuratively) (be, have, make, seek) deep(-ly), depth, be profound."]', '["v"]', 'to be (causatively, make) deep (literally or figuratively) (be, have, make, seek) deep(-ly), depth, be profound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6010}/[H6010]', 'lemma', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025."]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6011}/[H6011]', 'lemma', 'heb', 'עֹמֶק', '["ʻômeq"]', '["depth depth."]', '["n-m"]', 'depth depth.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6012}/[H6012]', 'lemma', 'heb', 'עָמֵק', '["ʻâmêq"]', '["deep (literally or figuratively) deeper, depth, strange."]', '["a"]', 'deep (literally or figuratively) deeper, depth, strange.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6013}/[H6013]', 'lemma', 'heb', 'עָמֹק', '["ʻâmôq"]', '["deep (literally or figuratively) (× exceeding) deep (thing)."]', '["a"]', 'deep (literally or figuratively) (× exceeding) deep (thing).', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6014]', 'root', 'heb', 'עָמַר', '["ʻâmar"]', '["properly, apparently to heap; figuratively, to chastise (as if piling blows); to gather grain bind sheaves, make merchandise of."]', '["v"]', 'properly, apparently to heap; figuratively, to chastise (as if piling blows); to gather grain bind sheaves, make merchandise of.', 'a primitive root; specifically (as denominative from 6016)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6015}/[H6015]', 'lemma', 'arc', 'עֲמַר', '["ʻămar"]', '["wool wool."]', '["n-m"]', 'wool wool.', '(Aramaic) corresponding to 6785;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6016}/[H6016]', 'lemma', 'heb', 'עֹמֶר', '["ʻômer"]', '["properly, a heap, i.e. a sheaf; also an omer, as a dry measure omer, sheaf."]', '["n-m"]', 'properly, a heap, i.e. a sheaf; also an omer, as a dry measure omer, sheaf.', 'from 6014;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6017}/[H6017]', 'lemma', 'heb', 'עֲמֹרָה', '["ʻĂmôrâh"]', '["Amorah, a place in Palestine Gomorrah."]', '["n-pr-loc"]', 'Amorah, a place in Palestine Gomorrah.', 'from 6014; a (ruined) heap;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6018}/[H6018]', 'lemma', 'heb', 'עׇמְרִי', '["ʻOmrîy"]', '["Omri, an Israelite Omri."]', '["n-pr-m"]', 'Omri, an Israelite Omri.', 'from 6014; heaping;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6019}/[H6019]', 'lemma', 'heb', 'עַמְרָם', '["ʻAmrâm"]', '["Amram, the name of two Israelites Amram."]', '["n-pr-m"]', 'Amram, the name of two Israelites Amram.', 'probably from 5971 and 7311; high people;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6020}/[H6020]', 'lemma', 'heb', 'עַמְרָמִי', '["ʻAmrâmîy"]', '["an Amramite or descendant of Amram Amramite."]', '["a"]', 'an Amramite or descendant of Amram Amramite.', 'from 6019;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6021}/[H6021]', 'lemma', 'heb', 'עֲמָשָׂא', '["ʻĂmâsâʼ"]', '["Amasa, the name of two Israelites Amasa."]', '["n-pr-m"]', 'Amasa, the name of two Israelites Amasa.', 'from 6006; burden;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6022}/[H6022]', 'lemma', 'heb', 'עֲמָשַׂי', '["ʻĂmâsay"]', '["Amasai, the name of three Israelites Amasai."]', '["n-pr-m"]', 'Amasai, the name of three Israelites Amasai.', 'from 6006; burdensome;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6023}/[H6023]', 'lemma', 'heb', 'עֲמַשְׁסַי', '["ʻĂmashçay"]', '["Amashsay, an Israelite Amashai."]', '["n-pr-m"]', 'Amashsay, an Israelite Amashai.', 'probably from 6006; burdensome;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6024}/[H6024]', 'lemma', 'heb', 'עֲנָב', '["ʻĂnâb"]', '["Anab, a place in Palestine Anab."]', '["n-pr-loc"]', 'Anab, a place in Palestine Anab.', 'from the same as 6025; fruit;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6026]', 'root', 'heb', 'עָנַג', '["ʻânag"]', '["to be soft or pliable, i.e. (figuratively) effeminate or luxurious delicate(-ness), (have) delight (self), sport self."]', '["v"]', 'to be soft or pliable, i.e. (figuratively) effeminate or luxurious delicate(-ness), (have) delight (self), sport self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6027}/[H6027]', 'lemma', 'heb', 'עֹנֶג', '["ʻôneg"]', '["luxury delight, pleasant."]', '["n-m"]', 'luxury delight, pleasant.', 'from 6026;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6028}/[H6028]', 'lemma', 'heb', 'עָנֹג', '["ʻânôg"]', '["luxurious delicate."]', '["a"]', 'luxurious delicate.', 'from 6026;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6029]', 'root', 'heb', 'עָנַד', '["ʻânad"]', '["to lace fast bind, tie."]', '["v"]', 'to lace fast bind, tie.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6030]', 'root', 'heb', 'עָנָה', '["ʻânâh"]', '["properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043."]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6031]', 'root', 'heb', 'עָנָה', '["ʻânâh"]', '["to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise."]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6032}/[H6032]', 'lemma', 'arc', 'עֲנָה', '["ʻănâh"]', '["answer, speak."]', '["v"]', 'answer, speak.', '(Aramaic) corresponding to 6030');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6033}/[H6033]', 'lemma', 'arc', 'עֲנָה', '["ʻănâh"]', '["poor."]', '["a"]', 'poor.', '(Aramaic) corresponding to 6031');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6034}/[H6034]', 'lemma', 'heb', 'עֲנָה', '["ʻĂnâh"]', '["Anah, the name of two Edomites and one Edomitess Anah."]', '["n-pr-m n-pr-f"]', 'Anah, the name of two Edomites and one Edomitess Anah.', 'probably from 6030; an answer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6035}/[H6035]', 'lemma', 'heb', 'עָנָו', '["ʻânâv"]', '["depressed (figuratively), in mind (gentle) or circumstances (needy, especially saintly) humble, lowly, meek, poor. Compare 6041."]', '["n-m"]', 'depressed (figuratively), in mind (gentle) or circumstances (needy, especially saintly) humble, lowly, meek, poor. Compare 6041.', 'or (by intermixture with 6041) עָנָיו; from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6036}/[H6036]', 'lemma', 'heb', 'עָנוּב', '["ʻÂnûwb"]', '["Anub, an Israelite Anub."]', '["n-pr-m"]', 'Anub, an Israelite Anub.', 'passive participle from the same as 6025; borne (as fruit);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6037}/[H6037]', 'lemma', 'heb', 'עַנְוָה', '["ʻanvâh"]', '["mildness (royal); also (concretely) oppressed gentleness, meekness."]', '["n-f"]', 'mildness (royal); also (concretely) oppressed gentleness, meekness.', 'feminine of 6035;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6038}/[H6038]', 'lemma', 'heb', 'עֲנָוָה', '["ʻănâvâh"]', '["condescension, human and subjective (modesty), or divine and objective (clemency) gentleness, humility, meekness."]', '["n-f"]', 'condescension, human and subjective (modesty), or divine and objective (clemency) gentleness, humility, meekness.', 'from 6035;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6039}/[H6039]', 'lemma', 'heb', 'עֱנוּת', '["ʻĕnûwth"]', '["affliction affliction."]', '["n-f"]', 'affliction affliction.', 'from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6040}/[H6040]', 'lemma', 'heb', 'עֳנִי', '["ʻŏnîy"]', '["depression, i.e. misery afflicted(-ion), trouble."]', '["n-m"]', 'depression, i.e. misery afflicted(-ion), trouble.', 'from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6041}/[H6041]', 'lemma', 'heb', 'עָנִי', '["ʻânîy"]', '["depressed, in mind or circumstances afflicted, humble, lowly, needy, poor."]', '["a"]', 'depressed, in mind or circumstances afflicted, humble, lowly, needy, poor.', 'from 6031; (practically the same as 6035, although the margin constantly disputes this, making 6035 subjective and objective);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6042}/[H6042]', 'lemma', 'heb', 'עֻנִּי', '["ʻUnnîy"]', '["Unni, the name of two Israelites Unni."]', '["n-pr-m"]', 'Unni, the name of two Israelites Unni.', 'from 6031; afflicted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6043}/[H6043]', 'lemma', 'heb', 'עֲנָיָה', '["ʻĂnâyâh"]', '["Anajah, the name of two Israelites Anaiah."]', '["n-pr-m"]', 'Anajah, the name of two Israelites Anaiah.', 'from 6030; Jah has answered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6044}/[H6044]', 'lemma', 'heb', 'עָנִים', '["ʻÂnîym"]', '["Anim, a place in Palestine Anim."]', '["n-pr-loc"]', 'Anim, a place in Palestine Anim.', 'for plural of 5869; fountains;');
