INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6103}/[H6103]', 'lemma', 'heb', 'עַצְלָה', '["ʻatslâh"]', '["(as abstractly) indolence slothfulness."]', '["n-f"]', '(as abstractly) indolence slothfulness.', 'feminine of 6102;');
