INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6105]', 'root', 'heb', 'עָצַם', '["ʻâtsam"]', '["to bind fast, i.e. close (the eyes); intransitively, to be (causatively, make) powerful or numerous; to crunch the bones break the bones, close, be great, be increased, be (wax) mighty(-ier), be more, shut, be(-come, make) strong(-er)."]', '["v"]', 'to bind fast, i.e. close (the eyes); intransitively, to be (causatively, make) powerful or numerous; to crunch the bones break the bones, close, be great, be increased, be (wax) mighty(-ier), be more, shut, be(-come, make) strong(-er).', 'a primitive root; also denominatively (from 6106)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6106}/[H6106]', 'lemma', 'heb', 'עֶצֶם', '["ʻetsem"]', '["a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very."]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6107}/[H6107]', 'lemma', 'heb', 'עֶצֶם', '["ʻEtsem"]', '["Etsem, a place in Palestine Azem, Ezem."]', '["n-pr-loc"]', 'Etsem, a place in Palestine Azem, Ezem.', 'the same as 6106; bone;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6108}/[H6108]', 'lemma', 'heb', 'עֹצֶם', '["ʻôtsem"]', '["power; hence, body might, strong, substance."]', '["n-m"]', 'power; hence, body might, strong, substance.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6109}/[H6109]', 'lemma', 'heb', 'עׇצְמָה', '["ʻotsmâh"]', '["powerfulness; by extension, numerousness abundance, strength."]', '["n-f"]', 'powerfulness; by extension, numerousness abundance, strength.', 'feminine of 6108;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6110}/[H6110]', 'lemma', 'heb', 'עַצֻּמָה', '["ʻatstsumâh"]', '["a bulwark, i.e. (figuratively) argument strong."]', '["n-f"]', 'a bulwark, i.e. (figuratively) argument strong.', 'feminine of 6099;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6111}/[H6111]', 'lemma', 'heb', 'עַצְמוֹן', '["ʻAtsmôwn"]', '["Atsmon, a place near Palestine Azmon."]', '["n-pr-loc"]', 'Atsmon, a place near Palestine Azmon.', 'or עַצְמֹן; from 6107; bone-like;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6112>', 'opaque', 'heb', 'עֵצֶן', '["ʻêtsen"]', '["a spear Eznite (from the margin)."]', '["n-m"]', 'a spear Eznite (from the margin).', 'from an unused root meaning to be sharp or strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6113]', 'root', 'heb', 'עָצָר', '["ʻâtsâr"]', '["to inclose; by analogy, to hold back; also to maintain, rule, assemble × be able, close up, detain, fast, keep (self close, still), prevail, recover, refrain, × reign, restrain, retain, shut (up), slack, stay, stop, withhold (self)."]', '["v"]', 'to inclose; by analogy, to hold back; also to maintain, rule, assemble × be able, close up, detain, fast, keep (self close, still), prevail, recover, refrain, × reign, restrain, retain, shut (up), slack, stay, stop, withhold (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6114}/[H6114]', 'lemma', 'heb', 'עֶצֶר', '["ʻetser"]', '["restraint magistrate."]', '["n-m"]', 'restraint magistrate.', 'from 6113;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6115}/[H6115]', 'lemma', 'heb', 'עֹצֶר', '["ʻôtser"]', '["closure; also constraint × barren, oppression, × prison."]', '["n-m"]', 'closure; also constraint × barren, oppression, × prison.', 'from 6113;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6116}/[H6116]', 'lemma', 'heb', 'עֲצָרָה', '["ʻătsârâh"]', '["an assembly, especially on a festival or holiday (solemn) assembly (meeting)."]', '["n-f"]', 'an assembly, especially on a festival or holiday (solemn) assembly (meeting).', 'or עֲצֶרֶת; from 6113;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6117]', 'root', 'heb', 'עָקַב', '["ʻâqab"]', '["to seize by the heel; figuratively, to circumvent (as if tripping up the heels); also to restrain (as if holding by the heel) take by the heel, stay, supplant, × utterly."]', '["v"]', 'to seize by the heel; figuratively, to circumvent (as if tripping up the heels); also to restrain (as if holding by the heel) take by the heel, stay, supplant, × utterly.', 'a primitive root; properly, to swell out or up; used only as denominative from 6119,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6118}/[H6118]', 'lemma', 'heb', 'עֵקֶב', '["ʻêqeb"]', '["a heel, i.e. (figuratively) the last of anything (used adverbially, for ever); also result, i.e. compensation; and so (adverb with preposition or relatively) on account of × because, by, end, for, if, reward."]', '["n-m"]', 'a heel, i.e. (figuratively) the last of anything (used adverbially, for ever); also result, i.e. compensation; and so (adverb with preposition or relatively) on account of × because, by, end, for, if, reward.', 'from 6117 in the sense of 6119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6119}/[H6119]', 'lemma', 'heb', 'עָקֵב', '["ʻâqêb"]', '["a heel (as protuberant); hence, a track; figuratively, the rear (of an army) heel, (horse-) hoof, last, lier in wait (by mistake for 6120), (foot-) step."]', '["n-m"]', 'a heel (as protuberant); hence, a track; figuratively, the rear (of an army) heel, (horse-) hoof, last, lier in wait (by mistake for 6120), (foot-) step.', 'or (feminine) עִקְּבָה; from 6117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6120}/[H6120]', 'lemma', 'heb', 'עָקֵב', '["ʻâqêb"]', '["a lier in wait heel (by mistake for 6119)."]', '["a"]', 'a lier in wait heel (by mistake for 6119).', 'from 6117 in its denominative sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6121}/[H6121]', 'lemma', 'heb', 'עָקֹב', '["ʻâqôb"]', '["(transitive) fraudulent or (intransitive) tracked crooked, deceitful, polluted."]', '["a"]', '(transitive) fraudulent or (intransitive) tracked crooked, deceitful, polluted.', 'from 6117; in the original sense, a knoll (as swelling up); in the denominative sense');
