INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6148]', 'root', 'heb', 'עָרַב', '["ʻârab"]', '["to braid, i.e. intermix; technically, to traffic (as if by barter); also or give to be security (as a kind of exchange) engage, (inter-) meddle (with), mingle (self), mortgage, occupy, give pledges, be(-come, put in) surety, undertake."]', '["v"]', 'to braid, i.e. intermix; technically, to traffic (as if by barter); also or give to be security (as a kind of exchange) engage, (inter-) meddle (with), mingle (self), mortgage, occupy, give pledges, be(-come, put in) surety, undertake.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6149]', 'root', 'heb', 'עָרֵב', '["ʻârêb"]', '["to be agreeable be pleasant(-ing), take pleasure in, be sweet."]', '["v"]', 'to be agreeable be pleasant(-ing), take pleasure in, be sweet.', 'a primitive root (rather identical with 6148 through the idea of close association);');
