INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6160}/[H6160]', 'lemma', 'heb', 'עֲרָבָה', '["ʻărâbâh"]', '["a desert; especially (with the article prefix) the (generally) sterile valley of the Jordan and its continuation to the Red Sea Arabah, champaign, desert, evening, heaven, plain, wilderness. See also 1026."]', '["n-f"]', 'a desert; especially (with the article prefix) the (generally) sterile valley of the Jordan and its continuation to the Red Sea Arabah, champaign, desert, evening, heaven, plain, wilderness. See also 1026.', 'from 6150 (in the sense of sterility);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6161}/[H6161]', 'lemma', 'heb', 'עֲרֻבָּה', '["ʻărubbâh"]', '["something given as security, i.e. (literally) a token (of safety) or (metaphorically) a bondsman pledge, surety."]', '["n-f"]', 'something given as security, i.e. (literally) a token (of safety) or (metaphorically) a bondsman pledge, surety.', 'feminine passive participle of 6048 in the sense of a bargain or exchange;');
