INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6205}/[H6205]', 'lemma', 'heb', 'עֲרָפֶל', '["ʻărâphel"]', '["gloom (as of a lowering sky) (gross, thick) dark (cloud, -ness)."]', '["n-m"]', 'gloom (as of a lowering sky) (gross, thick) dark (cloud, -ness).', 'probably from 6201;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6206]', 'root', 'heb', 'עָרַץ', '["ʻârats"]', '["to awe or (intransitive) to dread; hence, to harass be affrighted (afraid, dread, feared, terrified), break, dread, fear, oppress, prevail, shake terribly."]', '["v"]', 'to awe or (intransitive) to dread; hence, to harass be affrighted (afraid, dread, feared, terrified), break, dread, fear, oppress, prevail, shake terribly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6207]', 'root', 'heb', 'עָרַק', '["ʻâraq"]', '["to gnaw, i.e. (figuratively) eat (by hyberbole); also (participle) a pain fleeing, sinew."]', '["v"]', 'to gnaw, i.e. (figuratively) eat (by hyberbole); also (participle) a pain fleeing, sinew.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6208}/[H6208]', 'lemma', 'heb', 'עַרְקִי', '["ʻArqîy"]', '["an Arkite or inhabitant of Erek Arkite."]', '["a"]', 'an Arkite or inhabitant of Erek Arkite.', 'patrial from an unused name meaning a tush;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6209]', 'root', 'heb', 'עָרַר', '["ʻârar"]', '["to bare; figuratively, to demolish make bare, break, raise up (perhaps by clerical error for raze), × utterly."]', '["v"]', 'to bare; figuratively, to demolish make bare, break, raise up (perhaps by clerical error for raze), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6211}/[H6211]', 'lemma', 'heb', 'עָשׁ', '["ʻâsh"]', '["a moth moth. See also 5906."]', '["n"]', 'a moth moth. See also 5906.', 'from 6244;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6213]', 'root', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use."]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6214}/[H6214]', 'lemma', 'heb', 'עֲשָׂהאֵל', '["ʻĂsâhʼêl"]', '["Asahel, the name of four Israelites Asahel."]', '["n-pr-m"]', 'Asahel, the name of four Israelites Asahel.', 'from 6213 and 410; God has made;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6215}/[H6215]', 'lemma', 'heb', 'עֵשָׂו', '["ʻÊsâv"]', '["Esav, a son of Isaac, including his posterity Esau."]', '["n-pr-m"]', 'Esav, a son of Isaac, including his posterity Esau.', 'apparently a form of the passive participle of 6213 in the original sense of handling; rough (i.e. sensibly felt);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6216}/[H6216]', 'lemma', 'heb', 'עָשׁוֹק', '["ʻâshôwq"]', '["oppressive (as noun, a tyrant) oppressor."]', '["n-m"]', 'oppressive (as noun, a tyrant) oppressor.', 'from 6231;');
