INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6219}/[H6219]', 'lemma', 'heb', 'עָשׁוֹת', '["ʻâshôwth"]', '["shining, i.e. polished bright."]', '["a"]', 'shining, i.e. polished bright.', 'from 6245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6220}/[H6220]', 'lemma', 'heb', 'עַשְׁוָת', '["ʻAshvâth"]', '["Ashvath, an Israelite Ashvath."]', '["n-pr-m"]', 'Ashvath, an Israelite Ashvath.', 'for 6219; bright;');
