INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6223}/[H6223]', 'lemma', 'heb', 'עָשִׁיר', '["ʻâshîyr"]', '["rich, whether literal or figurative (noble) rich (man)."]', '["n-m"]', 'rich, whether literal or figurative (noble) rich (man).', 'from 6238;');
