INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6227}/[H6227]', 'lemma', 'heb', 'עָשָׁן', '["ʻâshân"]', '["smoke, literally or figuratively (vapor, dust, anger) smoke(-ing)."]', '["n-m"]', 'smoke, literally or figuratively (vapor, dust, anger) smoke(-ing).', 'from 6225;');
