INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6229]', 'root', 'heb', 'עָשַׂק', '["ʻâsaq"]', '["to press upon, i.e. quarrel strive with."]', '["v"]', 'to press upon, i.e. quarrel strive with.', 'a primitive root (identical with 6231);');
