INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6231]', 'root', 'heb', 'עָשַׁק', '["ʻâshaq"]', '["to press upon, i.e. oppress, defraud, violate, overflow get deceitfully, deceive, defraud, drink up, (use) oppress(-ion), -or), do violence (wrong)."]', '["v"]', 'to press upon, i.e. oppress, defraud, violate, overflow get deceitfully, deceive, defraud, drink up, (use) oppress(-ion), -or), do violence (wrong).', 'a primitive root (compare 6229);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6232}/[H6232]', 'lemma', 'heb', 'עֵשֶׁק', '["ʻÊsheq"]', '["Eshek, an Israelite Eshek."]', '["n-pr-m"]', 'Eshek, an Israelite Eshek.', 'from 6231; oppression;');
