INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6236}/[H6236]', 'lemma', 'arc', 'עֲשַׂר', '["ʻăsar"]', '["ten ten, twelve."]', '["n"]', 'ten ten, twelve.', '(Aramaic) masculine עֲשְׂרָה (Aramaic); corresponding to 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6237]', 'root', 'heb', 'עָשַׂר', '["ʻâsar"]', '["to tithe, i.e. to take or give a tenth × surely, give (take) the tenth, (have, take) tithe(-ing, -s), × truly."]', '["v"]', 'to tithe, i.e. to take or give a tenth × surely, give (take) the tenth, (have, take) tithe(-ing, -s), × truly.', 'a primitive root (identical with 6238); to accumulate; but used only as denominative from 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6238]', 'root', 'heb', 'עָשַׁר', '["ʻâshar"]', '["properly, to accumulate; chiefly (specifically) to grow (causatively, make) rich be(-come, en-, make, make self, wax) rich, make (1 Kings 22:48 marg). See 6240."]', '["v"]', 'properly, to accumulate; chiefly (specifically) to grow (causatively, make) rich be(-come, en-, make, make self, wax) rich, make (1 Kings 22:48 marg). See 6240.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6239}/[H6239]', 'lemma', 'heb', 'עֹשֶׁר', '["ʻôsher"]', '["wealth × far (richer), riches."]', '["n-m"]', 'wealth × far (richer), riches.', 'from 6238;');
