INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6244]', 'root', 'heb', 'עָשֵׁשׁ', '["ʻâshêsh"]', '["probably to shrink, i.e. fail be consumed."]', '["v"]', 'probably to shrink, i.e. fail be consumed.', 'a primitive root;');
