INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6247}/[H6247]', 'lemma', 'heb', 'עֶשֶׁת', '["ʻesheth"]', '["a fabric bright."]', '["n-m"]', 'a fabric bright.', 'from 6245;');
