INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6250}/[H6250]', 'lemma', 'heb', 'עֶשְׁתֹּנָה', '["ʻeshtônâh"]', '["thinking thought."]', '["n-f"]', 'thinking thought.', 'from 6245;');
