INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6252}/[H6252]', 'lemma', 'heb', 'עַשְׁתָּרוֹת', '["ʻAshtârôwth"]', '["Ashtaroth, the name of a Sidonian deity, and of a place East of the Jordan Asharoth, Astaroth. See also 1045, 6253, 6255."]', '["n-pr-f"]', 'Ashtaroth, the name of a Sidonian deity, and of a place East of the Jordan Asharoth, Astaroth. See also 1045, 6253, 6255.', 'or עַשְׁתָּרֹת; plural of 6251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6253}/[H6253]', 'lemma', 'heb', 'עַשְׁתֹּרֶת', '["ʻAshtôreth"]', '["Ashtoreth, the Phoenician goddess of love (and increase) Ashtoreth."]', '["n-pr-f"]', 'Ashtoreth, the Phoenician goddess of love (and increase) Ashtoreth.', 'probably for 6251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6254}/[H6254]', 'lemma', 'heb', 'עַשְׁתְּרָתִי', '["ʻAshtᵉrâthîy"]', '["an Ashterathite or inhabitant of Ashtaroth Ashterathite."]', '["a"]', 'an Ashterathite or inhabitant of Ashtaroth Ashterathite.', 'patrial from 6252;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6255}/[H6255]', 'lemma', 'heb', 'עַשְׁתְּרֹת קַרְנַיִם', '["ʻAshtᵉrôth Qarnayim"]', '["Ashteroth-Karnaim, a place East of the Jordan Ashtoreth Karnaim."]', '["n-pr-loc"]', 'Ashteroth-Karnaim, a place East of the Jordan Ashtoreth Karnaim.', 'from 6252 and the dual of 7161; Ashtaroth of (the) double horns (a symbol of the deity);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6256}/[H6256]', 'lemma', 'heb', 'עֵת', '["ʻêth"]', '["time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when."]', '["n-f"]', 'time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when.', 'from 5703;');
