INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6313]', 'root', 'heb', 'פּוּג', '["pûwg"]', '["to be sluggish cease, be feeble, faint, be slacked."]', '["v"]', 'to be sluggish cease, be feeble, faint, be slacked.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6314}/[H6314]', 'lemma', 'heb', 'פּוּגָה', '["pûwgâh"]', '["intermission rest."]', '["n-f"]', 'intermission rest.', 'from 6313;');
