INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6316>', 'opaque', 'heb', 'פּוּט', '["Pûwṭ"]', '["Put, a son of Ham, also the name of his descendants or their region, and of a Persian tribe Phut, Put."]', '["n-pr"]', 'Put, a son of Ham, also the name of his descendants or their region, and of a Persian tribe Phut, Put.', 'of foreign origin;');
