INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6325}/[H6325]', 'lemma', 'heb', 'פּוּנֹן', '["Pûwnôn"]', '["Punon, a place in the Desert Punon."]', '["n-pr-loc"]', 'Punon, a place in the Desert Punon.', 'from 6323; perplexity;');
