INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6329]', 'root', 'heb', 'פּוּק', '["pûwq"]', '["to issue, i.e. furnish; causatively, to secure; figuratively, to succeed afford, draw out, further, get, obtain."]', '["v"]', 'to issue, i.e. furnish; causatively, to secure; figuratively, to succeed afford, draw out, further, get, obtain.', 'a primitive root [rather identical with 6328 through the idea of dropping out; compare 5312];');
