INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6435}/[H6435]', 'lemma', 'heb', 'פֵּן', '["pên"]', '["properly, removal; used only (in the construction) adverb as conjunction, lest (lest) (peradventure), that...not."]', '["conj"]', 'properly, removal; used only (in the construction) adverb as conjunction, lest (lest) (peradventure), that...not.', 'from 6437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6436>', 'opaque', 'heb', 'פַּנַּג', '["pannag"]', '["probably pastry Pannag."]', '["n-m"]', 'probably pastry Pannag.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6437]', 'root', 'heb', 'פָּנָה', '["pânâh"]', '["to turn; by implication, to face, i.e. appear, look, etc. appear, at (even-) tide, behold, cast out, come on, × corner, dawning, empty, go away, lie, look, mark, pass away, prepare, regard, (have) respect (to), (re-) turn (aside, away, back, face, self), × right (early)."]', '["v"]', 'to turn; by implication, to face, i.e. appear, look, etc. appear, at (even-) tide, behold, cast out, come on, × corner, dawning, empty, go away, lie, look, mark, pass away, prepare, regard, (have) respect (to), (re-) turn (aside, away, back, face, self), × right (early).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6438}/[H6438]', 'lemma', 'heb', 'פִּנָּה', '["pinnâh"]', '["an angle; by implication, a pinnacle; figuratively, a chieftain bulwark, chief, corner, stay, tower."]', '["n-f"]', 'an angle; by implication, a pinnacle; figuratively, a chieftain bulwark, chief, corner, stay, tower.', 'feminine of 6434;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6439}/[H6439]', 'lemma', 'heb', 'פְּנוּאֵל', '["Pᵉnûwʼêl"]', '["Penuel or Peniel, a place East of Jordan; also (as Penuel) the name of two Israelites Peniel, Penuel."]', '["n-pr-m n-pr-loc"]', 'Penuel or Peniel, a place East of Jordan; also (as Penuel) the name of two Israelites Peniel, Penuel.', 'or (more properly,) פְּנִיאֵל; from 6437 and 410; face of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440}/[H6440]', 'lemma', 'heb', 'פָּנִים', '["pânîym"]', '["the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you."]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6441}/[H6441]', 'lemma', 'heb', 'פְּנִימָה', '["pᵉnîymâh"]', '["faceward, i.e. indoors (with-) in(-ner part, -ward)."]', '["adv"]', 'faceward, i.e. indoors (with-) in(-ner part, -ward).', 'from 6440 with directive enclitic;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6442}/[H6442]', 'lemma', 'heb', 'פְּנִימִי', '["pᵉnîymîy"]', '["interior (with-) in(-ner, -ward)."]', '["a"]', 'interior (with-) in(-ner, -ward).', 'from 6440;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6443}/[H6443]', 'lemma', 'heb', 'פָּנִין', '["pânîyn"]', '["probably a pearl (as round) ruby."]', '["n-m"]', 'probably a pearl (as round) ruby.', 'or פָּנִי; from the same as 6434;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6444}/[H6444]', 'lemma', 'heb', 'פְּנִנָּה', '["Pᵉninnâh"]', '["Peninnah, an Israelitess Peninnah."]', '["n-pr-f"]', 'Peninnah, an Israelitess Peninnah.', 'probably feminine from 6443 contr.;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6445]', 'root', 'heb', 'פָּנַק', '["pânaq"]', '["to enervate bring up."]', '["v"]', 'to enervate bring up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6446}/[H6446]', 'lemma', 'heb', 'פַּס', '["paç"]', '["a long and sleeved tunic (perhaps simply a wide one; from the original sense of the root, i.e. of many breadths) (divers) colours."]', '["n-m"]', 'a long and sleeved tunic (perhaps simply a wide one; from the original sense of the root, i.e. of many breadths) (divers) colours.', 'from 6461; properly, the palm (of the hand) or sole (of the foot) (compare 6447); by implication (plural)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6447}/[H6447]', 'lemma', 'arc', 'פַּס', '["paç"]', '["the palm (of the hand, as being spread out) participle"]', '["n-m"]', 'the palm (of the hand, as being spread out) participle', '(Aramaic) from a root corresponding to 6461;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6448]', 'root', 'heb', 'פָּסַג', '["pâçag"]', '["to cut up, i.e. (figuratively) contemplate consider."]', '["v"]', 'to cut up, i.e. (figuratively) contemplate consider.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6449}/[H6449]', 'lemma', 'heb', 'פִּסְגָּה', '["Piçgâh"]', '["Pisgah, a Mountain East of Jordan Pisgah."]', '["n-pr-loc"]', 'Pisgah, a Mountain East of Jordan Pisgah.', 'from 6448; a cleft;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6450}/[H6450]', 'lemma', 'heb', 'פַּס דַּמִּים', '["Paç Dammîym"]', '["Pas-Dammim, a place in Palestine Pas-dammim. Compare 658."]', '["n-pr-loc"]', 'Pas-Dammim, a place in Palestine Pas-dammim. Compare 658.', 'from 6446 and the plural of 1818; palm (i.e. dell) of bloodshed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6451}/[H6451]', 'lemma', 'heb', 'פִּסָּה', '["piççâh"]', '["expansion, i.e. abundance handful."]', '["n-f"]', 'expansion, i.e. abundance handful.', 'from 6461;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6452]', 'root', 'heb', 'פָּסַח', '["pâçach"]', '["to hop, i.e. (figuratively) skip over (or spare); by implication, to hesitate; also (literally) to limp, to dance halt, become lame, leap, pass over."]', '["v"]', 'to hop, i.e. (figuratively) skip over (or spare); by implication, to hesitate; also (literally) to limp, to dance halt, become lame, leap, pass over.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6453}/[H6453]', 'lemma', 'heb', 'פֶּסַח', '["peçach"]', '["a pretermission, i.e. exemption; used only techically of the Jewish Passover (the festival or the victim) passover (offering)."]', '["n-m"]', 'a pretermission, i.e. exemption; used only techically of the Jewish Passover (the festival or the victim) passover (offering).', 'from 6452;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6454}/[H6454]', 'lemma', 'heb', 'פָּסֵחַ', '["Pâçêach"]', '["Paseach, the name of two Israelites Paseah, Phaseah."]', '["n-pr-m"]', 'Paseach, the name of two Israelites Paseah, Phaseah.', 'from 6452; limping;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6455}/[H6455]', 'lemma', 'heb', 'פִּסֵּחַ', '["piççêach"]', '["lame lame."]', '["a"]', 'lame lame.', 'from 6452;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6456}/[H6456]', 'lemma', 'heb', 'פְּסִיל', '["pᵉçîyl"]', '["an idol carved (graven) image, quarry."]', '["n-m"]', 'an idol carved (graven) image, quarry.', 'from 6458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6458]', 'root', 'heb', 'פָּסַל', '["pâçal"]', '["to carve, whether wood or stone grave, hew."]', '["v"]', 'to carve, whether wood or stone grave, hew.', 'a primitive root;');
