INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6461]', 'root', 'heb', 'פָּסַס', '["pâçaç"]', '["probably to disperse, i.e. (intransitive) disappear cease."]', '["v"]', 'probably to disperse, i.e. (intransitive) disappear cease.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6462}/[H6462]', 'lemma', 'heb', 'פִּסְפָּה', '["Piçpâh"]', '["Pispah, an Israelite Pispah."]', '["n-pr-m"]', 'Pispah, an Israelite Pispah.', 'perhaps from 6461; dispersion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6463]', 'root', 'heb', 'פָּעָה', '["pâʻâh"]', '["to scream cry."]', '["v"]', 'to scream cry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6464}/[H6464]', 'lemma', 'heb', 'פָּעוּ', '["Pâʻûw"]', '["Pau or Pai, a place in Edom Pai, Pau."]', '["n-pr-loc"]', 'Pau or Pai, a place in Edom Pai, Pau.', 'or פָּעִי; from 6463; screaming;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6465}/[H6465]', 'lemma', 'heb', 'פְּעוֹר', '["Pᵉʻôwr"]', '["Peör, a mountain East of Jordan; Baal Peor, (for a deity worshipped there Peor. See also 1047."]', '["n-pr"]', 'Peör, a mountain East of Jordan; Baal Peor, (for a deity worshipped there Peor. See also 1047.', 'from 6473; a gap; also 1187)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6466]', 'root', 'heb', 'פָּעַל', '["pâʻal"]', '["to do or make (systematically and habitually), especially to practise commit, (evil-) do(-er), make(-r), ordain, work(-er)."]', '["v"]', 'to do or make (systematically and habitually), especially to practise commit, (evil-) do(-er), make(-r), ordain, work(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6467}/[H6467]', 'lemma', 'heb', 'פֹּעַל', '["pôʻal"]', '["an act or work (concretely) act, deed, do, getting, maker, work."]', '["n-m"]', 'an act or work (concretely) act, deed, do, getting, maker, work.', 'from 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6468}/[H6468]', 'lemma', 'heb', 'פְּעֻלָּה', '["pᵉʻullâh"]', '["(abstractly) work labour, reward, wages, work."]', '["n-f"]', '(abstractly) work labour, reward, wages, work.', 'feminine passive participle of 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6469}/[H6469]', 'lemma', 'heb', 'פְּעֻלְּתַי', '["Pᵉʻullᵉthay"]', '["Peullethai, an Israelite Peulthai."]', '["n-pr-m"]', 'Peullethai, an Israelite Peulthai.', 'from 6468; laborious;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6470]', 'root', 'heb', 'פָּעַם', '["pâʻam"]', '["to tap, i.e. beat regularly; hence (generally) to impel or agitate move, trouble."]', '["v"]', 'to tap, i.e. beat regularly; hence (generally) to impel or agitate move, trouble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6471}/[H6471]', 'lemma', 'heb', 'פַּעַם', '["paʻam"]', '["a stroke, literally or figuratively (in various applications, as follow) anvil, corner, foot(-step), going, (hundred-) fold, × now, (this) once, order, rank, step, thrice, (often-), second, this, two) time(-s), twice, wheel."]', '["n-f"]', 'a stroke, literally or figuratively (in various applications, as follow) anvil, corner, foot(-step), going, (hundred-) fold, × now, (this) once, order, rank, step, thrice, (often-), second, this, two) time(-s), twice, wheel.', 'or (feminine) פַּעֲמָה; from 6470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6472}/[H6472]', 'lemma', 'heb', 'פַּעֲמֹן', '["paʻămôn"]', '["a bell (as struck) bell."]', '["n-m"]', 'a bell (as struck) bell.', 'from 6471;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6473]', 'root', 'heb', 'פָּעַר', '["pâʻar"]', '["to yawn, i.e. open wide (literally or figuratively) gape, open (wide)."]', '["v"]', 'to yawn, i.e. open wide (literally or figuratively) gape, open (wide).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6474}/[H6474]', 'lemma', 'heb', 'פַּעֲרַי', '["Paʻăray"]', '["Paarai, an Israelite Paarai."]', '["n-pr-m"]', 'Paarai, an Israelite Paarai.', 'from 6473; yawning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6475]', 'root', 'heb', 'פָּצָה', '["pâtsâh"]', '["to rend, i.e. open (especially the mouth) deliver, gape, open, rid, utter."]', '["v"]', 'to rend, i.e. open (especially the mouth) deliver, gape, open, rid, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6476]', 'root', 'heb', 'פָּצַח', '["pâtsach"]', '["to break out (in joyful sound) break (forth, forth into joy), make a loud noise."]', '["v"]', 'to break out (in joyful sound) break (forth, forth into joy), make a loud noise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6477}/[H6477]', 'lemma', 'heb', 'פְּצִירָה', '["pᵉtsîyrâh"]', '["bluntness file."]', '["n-f"]', 'bluntness file.', 'from 6484;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6478]', 'root', 'heb', 'פָּצַל', '["pâtsal"]', '["to peel pill."]', '["v"]', 'to peel pill.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6479}/[H6479]', 'lemma', 'heb', 'פְּצָלָה', '["pᵉtsâlâh"]', '["a peeling strake."]', '["n-f"]', 'a peeling strake.', 'from 6478;');
