INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6481]', 'root', 'heb', 'פָּצַע', '["pâtsaʻ"]', '["to split, i.e. wound wound."]', '["v"]', 'to split, i.e. wound wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6482}/[H6482]', 'lemma', 'heb', 'פֶּצַע', '["petsaʻ"]', '["a wound wound(-ing)."]', '["n-m"]', 'a wound wound(-ing).', 'from 6481;');
