INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6554}/[H6554]', 'lemma', 'heb', 'פַּרְפַּר', '["Parpar"]', '["Parpar, a river of Syria Pharpar."]', '["n-pr"]', 'Parpar, a river of Syria Pharpar.', 'probably from 6565 in the sense of rushing; rapid;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6555]', 'root', 'heb', 'פָּרַץ', '["pârats"]', '["to break out (in many applications, direct and indirect, literal and figurative) × abroad, (make a) breach, break (away, down, -er, forth, in, up), burst out, come (spread) abroad, compel, disperse, grow, increase, open, press, scatter, urge."]', '["v"]', 'to break out (in many applications, direct and indirect, literal and figurative) × abroad, (make a) breach, break (away, down, -er, forth, in, up), burst out, come (spread) abroad, compel, disperse, grow, increase, open, press, scatter, urge.', 'a primitive root;');
