INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6565]', 'root', 'heb', 'פָּרַר', '["pârar"]', '["to break up (usually figuratively), i.e. to violate, frustrate × any ways, break (asunder), cast off, cause to cease, × clean, defeat, disannul, disappoint, dissolve, divide, make of none effect, fail, frustrate, bring (come) to nought, × utterly, make void."]', '["v"]', 'to break up (usually figuratively), i.e. to violate, frustrate × any ways, break (asunder), cast off, cause to cease, × clean, defeat, disannul, disappoint, dissolve, divide, make of none effect, fail, frustrate, bring (come) to nought, × utterly, make void.', 'a primitive root;');
