INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6601]', 'root', 'heb', 'פָּתָה', '["pâthâh"]', '["to open, i.e. be (causatively, make) roomy; usually figuratively (in a mental or moral sense) to be (causatively, make) simple or (in a sinister way) delude allure, deceive, enlarge, entice, flatter, persuade, silly (one)."]', '["v"]', 'to open, i.e. be (causatively, make) roomy; usually figuratively (in a mental or moral sense) to be (causatively, make) simple or (in a sinister way) delude allure, deceive, enlarge, entice, flatter, persuade, silly (one).', 'a primitive root;');
