INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6717}/[H6717]', 'lemma', 'heb', 'צִיבָא', '["Tsîybâʼ"]', '["Tsiba, an Israelite Ziba."]', '["n-pr-m"]', 'Tsiba, an Israelite Ziba.', 'from the same as 6678; station;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6718}/[H6718]', 'lemma', 'heb', 'צַיִד', '["tsayid"]', '["the chase; also game (thus taken) × catcheth, food, × hunter, (that which he took in) hunting, venison, victuals."]', '["n-m"]', 'the chase; also game (thus taken) × catcheth, food, × hunter, (that which he took in) hunting, venison, victuals.', 'from a form of 6679 and meaning the same;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6719}/[H6719]', 'lemma', 'heb', 'צַיָּד', '["tsayâd"]', '["a huntsman hunter."]', '["n-m"]', 'a huntsman hunter.', 'from the same as 6718;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6720}/[H6720]', 'lemma', 'heb', 'צֵידָה', '["tsêydâh"]', '["food meat, provision, venison, victuals."]', '["n-f"]', 'food meat, provision, venison, victuals.', 'or צֵדָה; feminine of 6718;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6721}/[H6721]', 'lemma', 'heb', 'צִידוֹן', '["Tsîydôwn"]', '["Tsidon, the name of a son of Canaan, and of a place in Palestine Sidon, Zidon."]', '["n-pr-loc"]', 'Tsidon, the name of a son of Canaan, and of a place in Palestine Sidon, Zidon.', 'or צִידֹן; from 6679 in the sense of catching fish; fishery;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6722}/[H6722]', 'lemma', 'heb', 'צִידֹנִי', '["Tsîydônîy"]', '["a Tsidonian or inhabitant of Tsidon Sidonian, of Sidon, Zidonian."]', '["a"]', 'a Tsidonian or inhabitant of Tsidon Sidonian, of Sidon, Zidonian.', 'patrial from 6721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6724}/[H6724]', 'lemma', 'heb', 'צִיוֹן', '["tsîyôwn"]', '["a desert dry place."]', '["n-m"]', 'a desert dry place.', 'from the same as 6723;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6725}/[H6725]', 'lemma', 'heb', 'צִיּוּן', '["tsîyûwn"]', '["a monumental or guiding pillar sign, title, waymark."]', '["n-m"]', 'a monumental or guiding pillar sign, title, waymark.', 'from the same as 6723 in the sense of conspicuousness (compare 5329);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6726}/[H6726]', 'lemma', 'heb', 'צִיּוֹן', '["Tsîyôwn"]', '["Tsijon (as a permanent capital), a mountain of Jerusalem Zion."]', '["n-pr-loc"]', 'Tsijon (as a permanent capital), a mountain of Jerusalem Zion.', 'the same (regularly) as 6725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6727}/[H6727]', 'lemma', 'heb', 'צִיחָא', '["Tsîychâʼ"]', '["Tsicha, the name of two Nethinim Ziha."]', '["n-pr-m"]', 'Tsicha, the name of two Nethinim Ziha.', 'or צִחָא; as if feminine of 6704; drought;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6728}/[H6728]', 'lemma', 'heb', 'צִיִּי', '["tsîyîy"]', '["a desert-dweller, i.e. nomad or wild beast wild beast of the desert, that dwell in (inhabiting) the wilderness."]', '["n-m"]', 'a desert-dweller, i.e. nomad or wild beast wild beast of the desert, that dwell in (inhabiting) the wilderness.', 'from the same as 6723;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6729>', 'opaque', 'heb', 'צִינֹק', '["tsîynôq"]', '["the pillory stocks."]', '["n-m"]', 'the pillory stocks.', 'from an unused root meaning to confine;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6730}/[H6730]', 'lemma', 'heb', 'צִיעֹר', '["Tsîyʻôr"]', '["Tsior, a place in Palestine Zior."]', '["n-pr-loc"]', 'Tsior, a place in Palestine Zior.', 'from 6819; small;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6731}/[H6731]', 'lemma', 'heb', 'צִיץ', '["tsîyts"]', '["properly, glistening, i.e. a burnished plate; also a flower (as bright colored); a wing (as gleaming in the air) blossom, flower, plate, wing."]', '["n-m"]', 'properly, glistening, i.e. a burnished plate; also a flower (as bright colored); a wing (as gleaming in the air) blossom, flower, plate, wing.', 'or צִץ; from 6692;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6732}/[H6732]', 'lemma', 'heb', 'צִיץ', '["Tsîyts"]', '["Tsits, a place in Palestine Ziz."]', '["n-pr-loc"]', 'Tsits, a place in Palestine Ziz.', 'the same as 6731; bloom;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6733}/[H6733]', 'lemma', 'heb', 'צִיצָה', '["tsîytsâh"]', '["a flower flower."]', '["n-m"]', 'a flower flower.', 'feminine of 6731;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6734}/[H6734]', 'lemma', 'heb', 'צִיצִת', '["tsîytsith"]', '["a floral or wing-like projection, i.e. a fore-lock of hair, a tassel fringe, lock."]', '["n-f"]', 'a floral or wing-like projection, i.e. a fore-lock of hair, a tassel fringe, lock.', 'feminine of 6731;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6735}/[H6735]', 'lemma', 'heb', 'צִיר', '["tsîyr"]', '["a hinge (as pressed in turning); also a throe (as a phys. or mental pressure); also a herald or errand-doer (as constrained by the principal) ambassador, hinge, messenger, pain, pang, sorrow. Compare 6736."]', '["n-m"]', 'a hinge (as pressed in turning); also a throe (as a phys. or mental pressure); also a herald or errand-doer (as constrained by the principal) ambassador, hinge, messenger, pain, pang, sorrow. Compare 6736.', 'from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6736}/[H6736]', 'lemma', 'heb', 'צִיר', '["tsîyr"]', '["a form (of beauty; as if pressed out, i.e. carved); hence, an (idolatrous) image beauty, idol."]', '["n-m"]', 'a form (of beauty; as if pressed out, i.e. carved); hence, an (idolatrous) image beauty, idol.', 'the same as 6735;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6737}/[H6737]', 'lemma', 'heb', 'צָיַר', '["tsâyar"]', '["to make an errand, i.e. betake oneself make as if...had been ambassador."]', '["v"]', 'to make an errand, i.e. betake oneself make as if...had been ambassador.', 'a denominative from 6735 in the sense of ambassador;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6738}/[H6738]', 'lemma', 'heb', 'צֵל', '["tsêl"]', '["shade, whether literal or figurative defence, shade(-ow)."]', '["n-m"]', 'shade, whether literal or figurative defence, shade(-ow).', 'from 6751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6739}/[H6739]', 'lemma', 'arc', 'צְלָא', '["tsᵉlâʼ"]', '["pray pray."]', '["v"]', 'pray pray.', '(Aramaic) probably corresponding to 6760 in the sense of bowing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6740]', 'root', 'heb', 'צָלָה', '["tsâlâh"]', '["to roast roast."]', '["v"]', 'to roast roast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6741}/[H6741]', 'lemma', 'heb', 'צִלָּה', '["Tsillâh"]', '["Tsillah, an antediluvian woman Zillah."]', '["n-pr-f"]', 'Tsillah, an antediluvian woman Zillah.', 'feminine of 6738;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6742}/[H6742]', 'lemma', 'heb', 'צְלוּל', '["tsᵉlûwl"]', '["a (round or flattened) cake cake."]', '["n-m"]', 'a (round or flattened) cake cake.', 'from 6749 in the sense of rolling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6743]', 'root', 'heb', 'צָלַח', '["tsâlach"]', '["to push forward, in various senses (literal or figurative, transitive or intransitive) break out, come (mightily), go over, be good, be meet, be profitable, (cause to, effect, make to, send) prosper(-ity, -ous, -ously)."]', '["v"]', 'to push forward, in various senses (literal or figurative, transitive or intransitive) break out, come (mightily), go over, be good, be meet, be profitable, (cause to, effect, make to, send) prosper(-ity, -ous, -ously).', 'or צָלֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6744}/[H6744]', 'lemma', 'arc', 'צְלַח', '["tsᵉlach"]', '["to advance (transitive or intransitive) promote, prosper."]', '["v"]', 'to advance (transitive or intransitive) promote, prosper.', '(Aramaic) corresponding to 6743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6745}/[H6745]', 'lemma', 'heb', 'צֵלָחָה', '["tsêlâchâh"]', '["something protracted or flattened out, i.e. a platter pan."]', '["n-f"]', 'something protracted or flattened out, i.e. a platter pan.', 'from 6743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6746}/[H6746]', 'lemma', 'heb', 'צְלֹחִית', '["tsᵉlôchîyth"]', '["something prolonged or tall, i.e. a vial or salt-cellar cruse."]', '["n-f"]', 'something prolonged or tall, i.e. a vial or salt-cellar cruse.', 'from 6743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6747}/[H6747]', 'lemma', 'heb', 'צַלַּחַת', '["tsallachath"]', '["something advanced or deep, i.e. a bowl; figuratively, the bosom bosom, dish."]', '["n-f"]', 'something advanced or deep, i.e. a bowl; figuratively, the bosom bosom, dish.', 'from 6743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6748}/[H6748]', 'lemma', 'heb', 'צָלִי', '["tsâlîy"]', '["roasted roast."]', '["n-m"]', 'roasted roast.', 'passive participle of 6740;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6749]', 'root', 'heb', 'צָלַל', '["tsâlal"]', '["properly, to tumble down, i.e. settle by a waving motion sink. Compare 6750, 6751."]', '["v"]', 'properly, to tumble down, i.e. settle by a waving motion sink. Compare 6750, 6751.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6750]', 'root', 'heb', 'צָלַל', '["tsâlal"]', '["to tinkle, i.e. rattle together (as the ears in reddening with shame, or the teeth in chattering with fear) quiver, tingle."]', '["v"]', 'to tinkle, i.e. rattle together (as the ears in reddening with shame, or the teeth in chattering with fear) quiver, tingle.', 'a primitive root (identical with through the idea of vibration);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6751]', 'root', 'heb', 'צָלַל', '["tsâlal"]', '["to shade, as twilight or an opaque object begin to be dark, shadowing."]', '["v"]', 'to shade, as twilight or an opaque object begin to be dark, shadowing.', 'a primitive root (identical with through the idea of hovering over (compare 6754));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6752}/[H6752]', 'lemma', 'heb', 'צֵלֶל', '["tsêlel"]', '["shade shadow."]', '["n-m"]', 'shade shadow.', 'from 6751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6753}/[H6753]', 'lemma', 'heb', 'צְלֶלְפּוֹנִי', '["Tsᵉlelpôwnîy"]', '["Tselelponi, an Israelitess Hazelelponi (including the article)."]', '["n-pr-f"]', 'Tselelponi, an Israelitess Hazelelponi (including the article).', 'from 6752 and the active participle of 6437; shade-facing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6755}/[H6755]', 'lemma', 'arc', 'צֶלֶם', '["tselem"]', '["an idolatrous figure form, image."]', '["n-m"]', 'an idolatrous figure form, image.', '(Aramaic) or צְלֶם; (Aramaic), corresponding to 6754;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6756}/[H6756]', 'lemma', 'heb', 'צַלְמוֹן', '["Tsalmôwn"]', '["Tsalmon, the name of a place in Palestine and of an Israelite Zalmon."]', '["n-pr-m n-pr-loc"]', 'Tsalmon, the name of a place in Palestine and of an Israelite Zalmon.', 'from 6754; shady;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6757}/[H6757]', 'lemma', 'heb', 'צַלְמָוֶת', '["tsalmâveth"]', '["shade of death, i.e. the grave (figuratively, calamity) shadow of death."]', '["n-m"]', 'shade of death, i.e. the grave (figuratively, calamity) shadow of death.', 'from 6738 and 4194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6758}/[H6758]', 'lemma', 'heb', 'צַלְמֹנָה', '["Tsalmônâh"]', '["Tsalmonah, a place in the Desert Zalmonah."]', '["n-pr-loc"]', 'Tsalmonah, a place in the Desert Zalmonah.', 'feminine of 6757; shadiness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6759}/[H6759]', 'lemma', 'heb', 'צַלְמֻנָּע', '["Tsalmunnâʻ"]', '["Tsalmunna, a Midianite Zalmunna."]', '["n-pr-m"]', 'Tsalmunna, a Midianite Zalmunna.', 'from 6738 and 4513; shade has been denied;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6760]', 'root', 'heb', 'צָלַע', '["tsâlaʻ"]', '["to limp (as if one-sided) halt."]', '["v"]', 'to limp (as if one-sided) halt.', 'a primitive root; probably to curve; used only as denominative from 6763,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6761}/[H6761]', 'lemma', 'heb', 'צֶלַע', '["tselaʻ"]', '["a limping or full (figuratively) adversity, halt(-ing)."]', '["n-m"]', 'a limping or full (figuratively) adversity, halt(-ing).', 'from 6760;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6762}/[H6762]', 'lemma', 'heb', 'צֶלַע', '["Tselaʻ"]', '["Tsela, a place in Palestine Zelah."]', '["n-pr-loc"]', 'Tsela, a place in Palestine Zelah.', 'the same as 6761;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6763}/[H6763]', 'lemma', 'heb', 'צֵלָע', '["tsêlâʻ"]', '["a rib (as curved), literally (of the body) or figuratively (of a door, i.e. leaf); hence, a side, literally (of a person) or figuratively (of an object or the sky, i.e. quarter); architecturally, a (especially floor or ceiling) timber or plank (single or collective, i.e. a flooring) beam, board, chamber, corner, leaf, plank, rib, side (chamber)."]', '["n-f"]', 'a rib (as curved), literally (of the body) or figuratively (of a door, i.e. leaf); hence, a side, literally (of a person) or figuratively (of an object or the sky, i.e. quarter); architecturally, a (especially floor or ceiling) timber or plank (single or collective, i.e. a flooring) beam, board, chamber, corner, leaf, plank, rib, side (chamber).', 'or (feminine) צַלְעָה; from 6760;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6765}/[H6765]', 'lemma', 'heb', 'צְלׇפְחָד', '["Tsᵉlophchâd"]', '["Tselophchad, an Israelite Zelophehad."]', '["n-pr-m"]', 'Tselophchad, an Israelite Zelophehad.', 'from the same as 6764 and 259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6766}/[H6766]', 'lemma', 'heb', 'צֶלְצַח', '["Tseltsach"]', '["Tseltsach, a place in Palestine Zelzah."]', '["n-pr-loc"]', 'Tseltsach, a place in Palestine Zelzah.', 'from 6738 and 6703; clear shade;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6767}/[H6767]', 'lemma', 'heb', 'צְלָצַל', '["tsᵉlâtsal"]', '["a clatter, i.e. (abstractly) whirring (of wings); (concretely) a cricket; also a harpoon (as rattling),a cymbal (as clanging) cymbal, locust, shadowing, spear."]', '["n-m"]', 'a clatter, i.e. (abstractly) whirring (of wings); (concretely) a cricket; also a harpoon (as rattling),a cymbal (as clanging) cymbal, locust, shadowing, spear.', 'from 6750 reduplicated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6769}/[H6769]', 'lemma', 'heb', 'צִלְּתַי', '["Tsillᵉthay"]', '["Tsillethai, the name of two Israelites Zilthai."]', '["n-pr-m"]', 'Tsillethai, the name of two Israelites Zilthai.', 'from the feminine of 6738; shady;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6770]', 'root', 'heb', 'צָמֵא', '["tsâmêʼ"]', '["to thirst (literally or figuratively) (be a-, suffer) thirst(-y)."]', '["v"]', 'to thirst (literally or figuratively) (be a-, suffer) thirst(-y).', 'a primitive root;');
