INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6937]', 'root', 'heb', 'קָדַר', '["qâdar"]', '["to be ashy, i.e. dark-colored; by implication, to mourn (in sackcloth or sordid garments) be black(-ish), be (make) dark(-en), × heavily, (cause to) mourn."]', '["v"]', 'to be ashy, i.e. dark-colored; by implication, to mourn (in sackcloth or sordid garments) be black(-ish), be (make) dark(-en), × heavily, (cause to) mourn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6938}/[H6938]', 'lemma', 'heb', 'קֵדָר', '["Qêdâr"]', '["Kedar, a son of Ishmael; also (collectively) Bedouin (as his descendants or representatives) Kedar."]', '["n-pr"]', 'Kedar, a son of Ishmael; also (collectively) Bedouin (as his descendants or representatives) Kedar.', 'from 6937; dusky (of the skin or the tent);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6939}/[H6939]', 'lemma', 'heb', 'קִדְרוֹן', '["Qidrôwn"]', '["Kidron, a brook near Jerusalem Kidron."]', '["n-pr"]', 'Kidron, a brook near Jerusalem Kidron.', 'from 6937; dusky place;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6940}/[H6940]', 'lemma', 'heb', 'קַדְרוּת', '["qadrûwth"]', '["duskiness blackness."]', '["n-f"]', 'duskiness blackness.', 'from 6937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6941}/[H6941]', 'lemma', 'heb', 'קְדֹרַנִּית', '["qᵉdôrannîyth"]', '["blackish ones (i.e. in sackcloth); used adverbially, in mourning weeds mournfully."]', '["adv"]', 'blackish ones (i.e. in sackcloth); used adverbially, in mourning weeds mournfully.', 'adverb from 6937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6942]', 'root', 'heb', 'קָדַשׁ', '["qâdash"]', '["to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly."]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6943}/[H6943]', 'lemma', 'heb', 'קֶדֶשׁ', '["Qedesh"]', '["Kedesh, the name of four places in Palestine Kedesh."]', '["n-pr-loc"]', 'Kedesh, the name of four places in Palestine Kedesh.', 'from 6942; a sanctum;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6944}/[H6944]', 'lemma', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary."]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6945}/[H6945]', 'lemma', 'heb', 'קָדֵשׁ', '["qâdêsh"]', '["a (quasi) sacred person, i.e. (technically) a (male) devotee (by prostitution) to licentious idolatry sodomite, unclean."]', '["n-m"]', 'a (quasi) sacred person, i.e. (technically) a (male) devotee (by prostitution) to licentious idolatry sodomite, unclean.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6946}/[H6946]', 'lemma', 'heb', 'קָדֵשׁ', '["Qâdêsh"]', '["Kadesh, a place in the Desert Kadesh. Compare 6947."]', '["n-pr-loc"]', 'Kadesh, a place in the Desert Kadesh. Compare 6947.', 'the same as 6945; sanctuary;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6947}/[H6947]', 'lemma', 'heb', 'קָדֵשׁ בַּרְנֵעַ', '["Qâdêsh Barnêaʻ"]', '["Kadesh-Barnea, a place in the Desert Kadeshbarnea."]', '["n-pr-loc"]', 'Kadesh-Barnea, a place in the Desert Kadeshbarnea.', 'from the same as 6946 and an otherwise unused word (apparently compounded of a correspondent to 1251 and a derivative of 5128) meaning desert of a fugitive; Kadesh of (the) Wilderness of Wandering;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6948}/[H6948]', 'lemma', 'heb', 'קְדֵשָׁה', '["qᵉdêshâh"]', '["a female devotee (i.e. prostitute) harlot, whore."]', '["n-f"]', 'a female devotee (i.e. prostitute) harlot, whore.', 'feminine of 6945;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6949]', 'root', 'heb', 'קָהָה', '["qâhâh"]', '["to be dull be set on edge, be blunt."]', '["v"]', 'to be dull be set on edge, be blunt.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6950]', 'root', 'heb', 'קָהַל', '["qâhal"]', '["to convoke assemble (selves) (together), gather (selves) (together)."]', '["v"]', 'to convoke assemble (selves) (together), gather (selves) (together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6951}/[H6951]', 'lemma', 'heb', 'קָהָל', '["qâhâl"]', '["assemblage (usually concretely) assembly, company, congregation, multitude."]', '["n-m"]', 'assemblage (usually concretely) assembly, company, congregation, multitude.', 'from 6950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6952}/[H6952]', 'lemma', 'heb', 'קְהִלָּה', '["qᵉhillâh"]', '["an assemblage assembly, congregation."]', '["n-f"]', 'an assemblage assembly, congregation.', 'from 6950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6953}/[H6953]', 'lemma', 'heb', 'קֹהֶלֶת', '["qôheleth"]', '["a (female) assembler (i.e. lecturer); abstractly, preaching (used as a ''nom de plume'', Koheleth) preacher."]', '["n-m"]', 'a (female) assembler (i.e. lecturer); abstractly, preaching (used as a ''nom de plume'', Koheleth) preacher.', 'feminine of active participle from 6950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6954}/[H6954]', 'lemma', 'heb', 'קְהֵלָתָה', '["Qᵉhêlâthâh"]', '["Kehelathah, a place in the Desert Kehelathah."]', '["n-pr-loc"]', 'Kehelathah, a place in the Desert Kehelathah.', 'from 6950; convocation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6956}/[H6956]', 'lemma', 'heb', 'קֳהָתִי', '["Qŏhâthîy"]', '["a Kohathite (collectively) or descendants of Kehath Kohathites."]', '["a"]', 'a Kohathite (collectively) or descendants of Kehath Kohathites.', 'patronymically from 6955;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6957}/[H6957]', 'lemma', 'heb', 'קַו', '["qav"]', '["a cord (as connecting), especially for measuring; figuratively, a rule; also a rim, a musical string or accord line. Compare 6978."]', '["n-m"]', 'a cord (as connecting), especially for measuring; figuratively, a rule; also a rim, a musical string or accord line. Compare 6978.', 'or קָו; from 6960 (compare 6961);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6958]', 'root', 'heb', 'קוֹא', '["qôwʼ"]', '["to vomit spue (out), vomit (out, up, up again)."]', '["v"]', 'to vomit spue (out), vomit (out, up, up again).', 'or קָיָה; (Jeremiah 25:27), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6959}/[H6959]', 'lemma', 'heb', 'קוֹבַע', '["qôwbaʻ"]', '["a helmet helmet."]', '["n-m"]', 'a helmet helmet.', 'a form collateral to 3553;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6960]', 'root', 'heb', 'קָוָה', '["qâvâh"]', '["to bind together (perhaps by twisting), i.e. collect; (figuratively) to expect gather (together), look, patiently, tarry, wait (for, on, upon)."]', '["v"]', 'to bind together (perhaps by twisting), i.e. collect; (figuratively) to expect gather (together), look, patiently, tarry, wait (for, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6961}/[H6961]', 'lemma', 'heb', 'קָוֶה', '["qâveh"]', '["a (measuring) cord (as if for binding) line."]', '["n-m"]', 'a (measuring) cord (as if for binding) line.', 'from 6960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6962]', 'root', 'heb', 'קוּט', '["qûwṭ"]', '["properly, to cut off, i.e. (figuratively) detest begrieved, loathe self."]', '["v"]', 'properly, to cut off, i.e. (figuratively) detest begrieved, loathe self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6963>', 'opaque', 'heb', 'קוֹל', '["qôwl"]', '["a voice or sound aloud, bleating, crackling, cry ( out), fame, lightness, lowing, noise, hold peace, (pro-) claim, proclamation, sing, sound, spark, thunder(-ing), voice, yell."]', '["n-m"]', 'a voice or sound aloud, bleating, crackling, cry ( out), fame, lightness, lowing, noise, hold peace, (pro-) claim, proclamation, sing, sound, spark, thunder(-ing), voice, yell.', 'or קֹל; from an unused root meaning to call aloud;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6964}/[H6964]', 'lemma', 'heb', 'קוֹלָיָה', '["Qôwlâyâh"]', '["Kolajah, the name of two Israelites Kolaiah."]', '["n-pr-m"]', 'Kolajah, the name of two Israelites Kolaiah.', 'from 6963 and 3050; voice of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6965]', 'root', 'heb', 'קוּם', '["qûwm"]', '["to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising)."]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6966}/[H6966]', 'lemma', 'arc', 'קוּם', '["qûwm"]', '["appoint, establish, make, raise up self, (a-) rise (up), (make to) stand, set (up)."]', '["v"]', 'appoint, establish, make, raise up self, (a-) rise (up), (make to) stand, set (up).', '(Aramaic) corresponding to 6965');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6967}/[H6967]', 'lemma', 'heb', 'קוֹמָה', '["qôwmâh"]', '["height × along, height, high, stature, tall."]', '["n-f"]', 'height × along, height, high, stature, tall.', 'from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6968}/[H6968]', 'lemma', 'heb', 'קוֹמְמִיּוּת', '["qôwmᵉmîyûwth"]', '["elevation, i.e. (adverbially) erectly (figuratively) upright."]', '["n-f"]', 'elevation, i.e. (adverbially) erectly (figuratively) upright.', 'from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6969]', 'root', 'heb', 'קוּן', '["qûwn"]', '["to strike a musical note, i.e. chant or wail (at a funeral) lament, mourning woman."]', '["v"]', 'to strike a musical note, i.e. chant or wail (at a funeral) lament, mourning woman.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6970}/[H6970]', 'lemma', 'heb', 'קוֹעַ', '["Qôwaʻ"]', '["Koa, a region of Babylon Koa."]', '["n-pr-loc"]', 'Koa, a region of Babylon Koa.', 'probably from 6972 in the original sense of cutting off; curtailment;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6971>', 'opaque', 'heb', 'קוֹף', '["qôwph"]', '["a monkey ape."]', '["n-m"]', 'a monkey ape.', 'or קֹף; of foreign origin,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6972]', 'root', 'heb', 'קוּץ', '["qûwts"]', '["to spend the harvest season summer."]', '["n-m"]', 'to spend the harvest season summer.', 'a primitive root; to clip off; used only as denominative from 7019;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6973]', 'root', 'heb', 'קוּץ', '["qûwts"]', '["to be (causatively, make) disgusted or anxious abhor, be distressed, be grieved, loathe, vex, be weary."]', '["v"]', 'to be (causatively, make) disgusted or anxious abhor, be distressed, be grieved, loathe, vex, be weary.', 'a primitive root (identical with through the idea of severing oneself from (compare 6962));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6974]', 'root', 'heb', 'קוּץ', '["qûwts"]', '["to awake (literally or figuratively) arise, (be) (a-) wake, watch."]', '["v"]', 'to awake (literally or figuratively) arise, (be) (a-) wake, watch.', 'a primitive root (identical with through the idea of abruptness in starting up from sleep (compare 3364));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6975}/[H6975]', 'lemma', 'heb', 'קוֹץ', '["qôwts"]', '["a thorn thorn."]', '["n-m"]', 'a thorn thorn.', 'or קֹץ; from 6972 (in the sense of pricking);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6976}/[H6976]', 'lemma', 'heb', 'קוֹץ', '["Qôwts"]', '["Kots, the name of two Israelites Koz, Hakkoz (including the article)."]', '["n-pr-m"]', 'Kots, the name of two Israelites Koz, Hakkoz (including the article).', 'the same as 6975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6977}/[H6977]', 'lemma', 'heb', 'קְוֻצָּה', '["qᵉvutstsâh"]', '["a forelock (as shorn) lock."]', '["n-f"]', 'a forelock (as shorn) lock.', 'feminine passive participle of 6972 in its original sense;');
