INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6979]', 'root', 'heb', 'קוּר', '["qûwr"]', '["to trench; by implication, to throw forth; to wall up, whether literal (to build a wall) or figurative (to estop) break down, cast out, destroy, dig."]', '["v"]', 'to trench; by implication, to throw forth; to wall up, whether literal (to build a wall) or figurative (to estop) break down, cast out, destroy, dig.', 'a primitive root; also denominative from 7023');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6980}/[H6980]', 'lemma', 'heb', 'קוּר', '["qûwr"]', '["(only plural) trenches, i.e. a web (as if so formed) web."]', '["n-m"]', '(only plural) trenches, i.e. a web (as if so formed) web.', 'from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6981}/[H6981]', 'lemma', 'heb', 'קוֹרֵא', '["Qôwrêʼ"]', '["Kore, the name of two Israelites Kore."]', '["n-pr-m"]', 'Kore, the name of two Israelites Kore.', 'or קֹרֵא; (1 Chronicles 26:1), active participle of 7121; crier;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6982}/[H6982]', 'lemma', 'heb', 'קוֹרָה', '["qôwrâh"]', '["a rafter (forming trenches as it were); by implication, a roof beam, roof."]', '["n-f"]', 'a rafter (forming trenches as it were); by implication, a roof beam, roof.', 'or קֹרָה; from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H6983]', 'root', 'heb', 'קוֹשׁ', '["qôwsh"]', '["to set a trap lay a snare."]', '["v"]', 'to set a trap lay a snare.', 'a primitive root; to bend; used only as denominative for 3369,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6984}/[H6984]', 'lemma', 'heb', 'קוּשָׁיָהוּ', '["qûwshâyâhûw"]', '["Kushajah, an Israelite Kushaiah."]', '["n-pr-m"]', 'Kushajah, an Israelite Kushaiah.', 'from the passive participle of 6983 and 3050; entrapped of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6985}/[H6985]', 'lemma', 'heb', 'קַט', '["qaṭ"]', '["a little, i.e. (adverbially) merely very."]', '["a"]', 'a little, i.e. (adverbially) merely very.', 'from 6990 in the sense of abbreviation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6987}/[H6987]', 'lemma', 'heb', 'קֹטֶב', '["qôṭeb"]', '["extermination destruction."]', '["n-m"]', 'extermination destruction.', 'from the same as 6986;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6988}/[H6988]', 'lemma', 'heb', 'קְטוֹרָה', '["qᵉṭôwrâh"]', '["perfume incense."]', '["n-m"]', 'perfume incense.', 'from 6999;');
