INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7101}/[H7101]', 'lemma', 'heb', 'קָצִין', '["qâtsîyn"]', '["a magistrate (as deciding) or other leader captain, guide, prince, ruler. Compare 6278."]', '["n-m"]', 'a magistrate (as deciding) or other leader captain, guide, prince, ruler. Compare 6278.', 'from 7096 in the sense of determining;');
