INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7104}/[H7104]', 'lemma', 'heb', 'קְצִיץ', '["Qᵉtsîyts"]', '["Keziz, a valley in Palestine Keziz."]', '["n-pr-loc"]', 'Keziz, a valley in Palestine Keziz.', 'from 7112; abrupt;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7105}/[H7105]', 'lemma', 'heb', 'קָצִיר', '["qâtsîyr"]', '["severed, i.e. harvest (as reaped), the crop, the time, the reaper, or figuratively; also a limb (of a tree, or simply foliage) bough, branch, harvest (man)."]', '["n-m"]', 'severed, i.e. harvest (as reaped), the crop, the time, the reaper, or figuratively; also a limb (of a tree, or simply foliage) bough, branch, harvest (man).', 'from 7114;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7106]', 'root', 'heb', 'קָצַע', '["qâtsaʻ"]', '["to strip off, i.e. (partially) scrape; by implication, to segregate (as an angle) cause to scrape, corner."]', '["v"]', 'to strip off, i.e. (partially) scrape; by implication, to segregate (as an angle) cause to scrape, corner.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7107]', 'root', 'heb', 'קָצַף', '["qâtsaph"]', '["to crack off, i.e. (figuratively) burst out in rage (be) anger(-ry), displease, fret self, (provoke to) wrath (come), be wroth."]', '["v"]', 'to crack off, i.e. (figuratively) burst out in rage (be) anger(-ry), displease, fret self, (provoke to) wrath (come), be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7108}/[H7108]', 'lemma', 'arc', 'קְצַף', '["qᵉtsaph"]', '["to become enraged be furious."]', '["v"]', 'to become enraged be furious.', '(Aramaic) corresponding to 7107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7109}/[H7109]', 'lemma', 'arc', 'קְצַף', '["qᵉtsaph"]', '["rage wrath."]', '["n-m"]', 'rage wrath.', '(Aramaic) from 7108;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7110}/[H7110]', 'lemma', 'heb', 'קֶצֶף', '["qetseph"]', '["a splinter (as chipped off); figuratively, rage or strife foam, indignation, × sore, wrath."]', '["n-m"]', 'a splinter (as chipped off); figuratively, rage or strife foam, indignation, × sore, wrath.', 'from 7107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7111}/[H7111]', 'lemma', 'heb', 'קְצָפָה', '["qᵉtsâphâh"]', '["a fragment bark(-ed)."]', '["n-f"]', 'a fragment bark(-ed).', 'from 7107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7112]', 'root', 'heb', 'קָצַץ', '["qâtsats"]', '["to chop off (literally or figuratively) cut (asunder, in pieces, in sunder, off), × utmost."]', '["v"]', 'to chop off (literally or figuratively) cut (asunder, in pieces, in sunder, off), × utmost.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7113}/[H7113]', 'lemma', 'arc', 'קְצַץ', '["qᵉtsats"]', '["cut off."]', '["v"]', 'cut off.', '(Aramaic) corresponding to 7112');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7114]', 'root', 'heb', 'קָצַר', '["qâtsar"]', '["to dock off, i.e. curtail (transitive or intransitive, literal or figurative); especially to harvest (grass or grain) × at all, cut down, much discouraged, grieve, harvestman, lothe, mourn, reap(-er), (be, wax) short(-en, -er), straiten, trouble, vex."]', '["v"]', 'to dock off, i.e. curtail (transitive or intransitive, literal or figurative); especially to harvest (grass or grain) × at all, cut down, much discouraged, grieve, harvestman, lothe, mourn, reap(-er), (be, wax) short(-en, -er), straiten, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7115}/[H7115]', 'lemma', 'heb', 'קֹצֶר', '["qôtser"]', '["shortness (of spirit), i.e. impatience anguish."]', '["n-m"]', 'shortness (of spirit), i.e. impatience anguish.', 'from 7114;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7116}/[H7116]', 'lemma', 'heb', 'קָצֵר', '["qâtsêr"]', '["short (whether in size, number, life, strength or temper) few, hasty, small, soon."]', '["a"]', 'short (whether in size, number, life, strength or temper) few, hasty, small, soon.', 'from 7114;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7117}/[H7117]', 'lemma', 'heb', 'קְצָת', '["qᵉtsâth"]', '["a termination (literally or figuratively); also (by implication) a portion; adverbially (with prepositional prefix) after end, part, × some."]', '["n-f"]', 'a termination (literally or figuratively); also (by implication) a portion; adverbially (with prepositional prefix) after end, part, × some.', 'from 7096;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7118}/[H7118]', 'lemma', 'arc', 'קְצָת', '["qᵉtsâth"]', '["end, partly."]', '["n-f"]', 'end, partly.', '(Aramaic) corresponding to 7117');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7120}/[H7120]', 'lemma', 'heb', 'קֹר', '["qôr"]', '["cold cold."]', '["n-m"]', 'cold cold.', 'from the same as 7119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7121]', 'root', 'heb', 'קָרָא', '["qârâʼ"]', '["to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say."]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7122]', 'root', 'heb', 'קָרָא', '["qârâʼ"]', '["to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet."]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7123}/[H7123]', 'lemma', 'arc', 'קְרָא', '["qᵉrâʼ"]', '["call, cry, read."]', '["v"]', 'call, cry, read.', '(Aramaic) corresponding to 7121');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7124}/[H7124]', 'lemma', 'heb', 'קֹרֵא', '["qôrêʼ"]', '["a caller, i.e. partridge (from its cry) partridge. See also 6981."]', '["n-m"]', 'a caller, i.e. partridge (from its cry) partridge. See also 6981.', 'properly, active participle of 7121;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7125}/[H7125]', 'lemma', 'heb', 'קִרְאָה', '["qirʼâh"]', '["an encountering, accidental, friendly or hostile (also adverbially, opposite) × against (he come), help, meet, seek, × to, × in the way."]', '["n-m"]', 'an encountering, accidental, friendly or hostile (also adverbially, opposite) × against (he come), help, meet, seek, × to, × in the way.', 'from 7122;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7126]', 'root', 'heb', 'קָרַב', '["qârab"]', '["to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take."]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7127}/[H7127]', 'lemma', 'arc', 'קְרֵב', '["qᵉrêb"]', '["approach, come (near, nigh), draw near."]', '["v"]', 'approach, come (near, nigh), draw near.', '(Aramaic) corresponding to 7126');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7128}/[H7128]', 'lemma', 'heb', 'קְרָב', '["qᵉrâb"]', '["hostile encounter battle, war."]', '["n-m"]', 'hostile encounter battle, war.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7129}/[H7129]', 'lemma', 'arc', 'קְרָב', '["qᵉrâb"]', '["war."]', '["n-m"]', 'war.', '(Aramaic) corresponding to 7128');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7130}/[H7130]', 'lemma', 'heb', 'קֶרֶב', '["qereb"]', '["properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self."]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7131}/[H7131]', 'lemma', 'heb', 'קָרֵב', '["qârêb"]', '["near approach, come (near, nigh), draw near."]', '["a"]', 'near approach, come (near, nigh), draw near.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7132}/[H7132]', 'lemma', 'heb', 'קְרָבָה', '["qᵉrâbâh"]', '["approach approaching, draw near."]', '["n-f"]', 'approach approaching, draw near.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7133}/[H7133]', 'lemma', 'heb', 'קׇרְבָּן', '["qorbân"]', '["something brought near the altar, i.e. a sacrificial present oblation, that is offered, offering."]', '["n-m"]', 'something brought near the altar, i.e. a sacrificial present oblation, that is offered, offering.', 'or קֻרְבָּן; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7134}/[H7134]', 'lemma', 'heb', 'קַרְדֹּם', '["qardôm"]', '["an axe ax."]', '["n-m"]', 'an axe ax.', 'perhaps from 6923 in the sense of striking upon;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7135}/[H7135]', 'lemma', 'heb', 'קָרָה', '["qârâh"]', '["coolness cold."]', '["n-f"]', 'coolness cold.', 'feminine of 7119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7136]', 'root', 'heb', 'קָרָה', '["qârâh"]', '["to light upon (chiefly by accident); causatively, to bring about; specifically, to impose timbers (for roof or floor) appoint, lay (make) beams, befall, bring, come (to pass unto), floor, (hap) was, happen (unto), meet, send good speed."]', '["v"]', 'to light upon (chiefly by accident); causatively, to bring about; specifically, to impose timbers (for roof or floor) appoint, lay (make) beams, befall, bring, come (to pass unto), floor, (hap) was, happen (unto), meet, send good speed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7137}/[H7137]', 'lemma', 'heb', 'קָרֶה', '["qâreh"]', '["an (unfortunate) occurrence, i.e. some accidental (ceremonial) disqualification uncleanness that chanceth."]', '["n-m"]', 'an (unfortunate) occurrence, i.e. some accidental (ceremonial) disqualification uncleanness that chanceth.', 'from 7136;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7138}/[H7138]', 'lemma', 'heb', 'קָרוֹב', '["qârôwb"]', '["near (in place, kindred or time) allied, approach, at hand, any of kin, kinsfold(-sman), (that is) near (of kin), neighbour, (that is) next, (them that come) nigh (at hand), more ready, short(-ly)."]', '["a"]', 'near (in place, kindred or time) allied, approach, at hand, any of kin, kinsfold(-sman), (that is) near (of kin), neighbour, (that is) next, (them that come) nigh (at hand), more ready, short(-ly).', 'or קָרֹב; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7139]', 'root', 'heb', 'קָרַח', '["qârach"]', '["to depilate make (self) bald."]', '["v"]', 'to depilate make (self) bald.', 'a primitive root;');
