INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7142}/[H7142]', 'lemma', 'heb', 'קֵרֵחַ', '["qêrêach"]', '["bald (on the back of the head) bald (head)."]', '["a"]', 'bald (on the back of the head) bald (head).', 'from 7139;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7143}/[H7143]', 'lemma', 'heb', 'קָרֵחַ', '["Qârêach"]', '["Kareach, an Israelite Careah, Kareah."]', '["n-pr-m"]', 'Kareach, an Israelite Careah, Kareah.', 'from 7139; bald;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7144}/[H7144]', 'lemma', 'heb', 'קׇרְחָה', '["qorchâh"]', '["baldness bald(-ness), × utterly."]', '["n-f"]', 'baldness bald(-ness), × utterly.', 'or קׇרְחָא; (Ezekiel 27:31), from 7139;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7145}/[H7145]', 'lemma', 'heb', 'קׇרְחִי', '["Qorchîy"]', '["a Korchite (collectively) or descendants of Korach Korahite, Korathite, sons of Kore, Korhite."]', '["n-pr-m"]', 'a Korchite (collectively) or descendants of Korach Korahite, Korathite, sons of Kore, Korhite.', 'patronymic from 7141;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7146}/[H7146]', 'lemma', 'heb', 'קָרַחַת', '["qârachath"]', '["a bald spot (on the back of the head); figuratively, a threadbare spot (on the back side of the cloth) bald head, bare within."]', '["n-f"]', 'a bald spot (on the back of the head); figuratively, a threadbare spot (on the back side of the cloth) bald head, bare within.', 'from 7139;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7147}/[H7147]', 'lemma', 'heb', 'קְרִי', '["qᵉrîy"]', '["hostile encounter contrary."]', '["n-m"]', 'hostile encounter contrary.', 'from 7136;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7148}/[H7148]', 'lemma', 'heb', 'קָרִיא', '["qârîyʼ"]', '["called, i.e. select famous, renowned."]', '["a"]', 'called, i.e. select famous, renowned.', 'from 7121;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7149}/[H7149]', 'lemma', 'arc', 'קִרְיָא', '["qiryâʼ"]', '["city."]', '["n-f"]', 'city.', '(Aramaic) or קִרְיָה; (Aramaic), corresponding to 7151');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7150}/[H7150]', 'lemma', 'heb', 'קְרִיאָה', '["qᵉrîyʼâh"]', '["a proclamation preaching."]', '["n-f"]', 'a proclamation preaching.', 'from 7121;');
