INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7153}/[H7153]', 'lemma', 'heb', 'קִרְיַת אַרְבַּע', '["Qiryath ʼArbaʻ"]', '["Kirjath-Arba or Kirjath-ha-Arba, a place in Palestine Kirjath-arba."]', '["n-pr-loc"]', 'Kirjath-Arba or Kirjath-ha-Arba, a place in Palestine Kirjath-arba.', 'or (with the article interposed) קִרְיַת הָאַרְבַּע; (Nehemiah 11:25), from 7151 and 704 or 702; city of Arba, or city of the four (giants);');
