INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7155}/[H7155]', 'lemma', 'heb', 'קִרְיַת חֻצוֹת', '["Qiryath Chutsôwth"]', '["Kirjath-Chutsoth, a place in Moab Kirjath-huzoth."]', '["n-pr-loc"]', 'Kirjath-Chutsoth, a place in Moab Kirjath-huzoth.', 'from 7151 and the feminine plural of 2351; city of streets;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7156}/[H7156]', 'lemma', 'heb', 'קִרְיָתַיִם', '["Qiryâthayim"]', '["Kirjathaim, the name of two placed in Palestine Kiriathaim, Kirjathaim."]', '["n-pr-loc"]', 'Kirjathaim, the name of two placed in Palestine Kiriathaim, Kirjathaim.', 'dual of 7151; double city;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7157}/[H7157]', 'lemma', 'heb', 'קִרְיַת יְעָרִים', '["Qiryath Yᵉʻârîym"]', '["Kirjath-Jearim or Kirjath-Arim, a place in Palestine Kirjath, Kirjath-jearim, Kirjath-arim."]', '["n-pr-loc"]', 'Kirjath-Jearim or Kirjath-Arim, a place in Palestine Kirjath, Kirjath-jearim, Kirjath-arim.', 'or (Jeremiah 26:20) with the article interposed; or (Joshua 18:28) simply the former part of the word; or קִרְיַת עָרִים; from 7151 and the plural of 3293 or 5892; city of forests, or city of towns;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7158}/[H7158]', 'lemma', 'heb', 'קִרְיַת סַנָּה', '["Qiryath Çannâh"]', '["Kirjath-Sannah or Kirjath-Sepher, a place in Palestine Kirjath-sannah, Kirjath-sepher."]', '["n-pr-loc"]', 'Kirjath-Sannah or Kirjath-Sepher, a place in Palestine Kirjath-sannah, Kirjath-sepher.', 'or קִרְיַת סֵפֶר; from 7151 and a simpler feminine from the same as 5577, or (for the latter name) 5612; city of branches, or of a book;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7159]', 'root', 'heb', 'קָרַם', '["qâram"]', '["to cover cover."]', '["v"]', 'to cover cover.', 'a primitive root;');
