INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7169]', 'root', 'heb', 'קָרַץ', '["qârats"]', '["to pinch, i.e. (partially) to bite the lips, blink the eyes (as a gesture of malice), or (fully) to squeeze off (a piece of clay in order to mould a vessel from it) form, move, wink."]', '["v"]', 'to pinch, i.e. (partially) to bite the lips, blink the eyes (as a gesture of malice), or (fully) to squeeze off (a piece of clay in order to mould a vessel from it) form, move, wink.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7170}/[H7170]', 'lemma', 'arc', 'קְרַץ', '["qᵉrats"]', '["chew him up (figuratively) by slander accuse."]', '["n-m"]', 'chew him up (figuratively) by slander accuse.', '(Aramaic) corresponding to 7171 in the sense of a bit (to ''eat the morsels of'' any one, i.e.');
