INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7181]', 'root', 'heb', 'קָשַׁב', '["qâshab"]', '["to prick up the ears, i.e. hearken attend, (cause to) hear(-ken), give heed, incline, mark (well), regard."]', '["v"]', 'to prick up the ears, i.e. hearken attend, (cause to) hear(-ken), give heed, incline, mark (well), regard.', 'a primitive root;');
