INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7189>', 'opaque', 'heb', 'קֹשֶׁט', '["qôsheṭ"]', '["equity (as evenly weighed), i.e. reality truth."]', '["n-m"]', 'equity (as evenly weighed), i.e. reality truth.', 'or קֹשְׁטְ; from an unused root meaning to balance;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7190}/[H7190]', 'lemma', 'heb', 'קְשִׁי', '["qᵉshîy"]', '["obstinacy stubbornness."]', '["n-m"]', 'obstinacy stubbornness.', 'from 7185;');
