INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7194]', 'root', 'heb', 'קָשַׁר', '["qâshar"]', '["to tie, physically (gird, confine, compact) or mentally (in love, league) bind (up), (make a) conspire(-acy, -ator), join together, knit, stronger, work (treason)."]', '["v"]', 'to tie, physically (gird, confine, compact) or mentally (in love, league) bind (up), (make a) conspire(-acy, -ator), join together, knit, stronger, work (treason).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7195}/[H7195]', 'lemma', 'heb', 'קֶשֶׁר', '["qesher"]', '["an (unlawful) alliance confederacy, conspiracy, treason."]', '["n-m"]', 'an (unlawful) alliance confederacy, conspiracy, treason.', 'from 7194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7196}/[H7196]', 'lemma', 'heb', 'קִשֻּׁר', '["qishshur"]', '["an (ornamental) girdle (for women) attire, headband."]', '["n-m"]', 'an (ornamental) girdle (for women) attire, headband.', 'from 7194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7197]', 'root', 'heb', 'קָשַׁשׁ', '["qâshash"]', '["to forage for straw, stubble or wood; figuratively, to assemble gather (selves) (together)."]', '["v"]', 'to forage for straw, stubble or wood; figuratively, to assemble gather (selves) (together).', 'a primitive root; to become sapless through drought; used only as denominative from 7179;');
