INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7199}/[H7199]', 'lemma', 'heb', 'קַשָּׁת', '["qashshâth"]', '["a bowman × archer."]', '["n-m"]', 'a bowman × archer.', 'intensive (as denominative) from 7198;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7200]', 'root', 'heb', 'רָאָה', '["râʼâh"]', '["to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions."]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7201}/[H7201]', 'lemma', 'heb', 'רָאָה', '["râʼâh"]', '["a bird of prey (probably the vulture, from its sharp sight) glede. Compare 1676."]', '["n-f"]', 'a bird of prey (probably the vulture, from its sharp sight) glede. Compare 1676.', 'from 7200;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7202}/[H7202]', 'lemma', 'heb', 'רָאֶה', '["râʼeh"]', '["seeing, i.e. experiencing see."]', '["a"]', 'seeing, i.e. experiencing see.', 'from 7200;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7203}/[H7203]', 'lemma', 'heb', 'רֹאֶה', '["rôʼeh"]', '["a seer (as often rendered); but also (abstractly) a vision vision."]', '["n-m"]', 'a seer (as often rendered); but also (abstractly) a vision vision.', 'active participle of 7200;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7204}/[H7204]', 'lemma', 'heb', 'רֹאֵה', '["Rôʼêh"]', '["Roeh, an Israelite Haroeh (including the article)."]', '["n-pr-m"]', 'Roeh, an Israelite Haroeh (including the article).', 'for 7203; prophet;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7205}/[H7205]', 'lemma', 'heb', 'רְאוּבֵן', '["Rᵉʼûwbên"]', '["Reuben, a son of Jacob Reuben."]', '["n-pr-m"]', 'Reuben, a son of Jacob Reuben.', 'from the imperative of 7200 and 1121; see ye a son;');
