INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7207}/[H7207]', 'lemma', 'heb', 'רַאֲוָה', '["raʼăvâh"]', '["sight, i.e. satisfaction behold."]', '["v"]', 'sight, i.e. satisfaction behold.', 'from 7200a;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7208}/[H7208]', 'lemma', 'heb', 'רְאוּמָה', '["Rᵉʼûwmâh"]', '["Reumah, a Syrian woman Reumah."]', '["n-pr-f"]', 'Reumah, a Syrian woman Reumah.', 'feminine passive participle of 7213; raised;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7209}/[H7209]', 'lemma', 'heb', 'רְאִי', '["rᵉʼîy"]', '["a mirror (as seen) looking glass."]', '["n-m"]', 'a mirror (as seen) looking glass.', 'from 7200;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7210}/[H7210]', 'lemma', 'heb', 'רֳאִי', '["rŏʼîy"]', '["sight, whether abstractly (vision) or concretely (a spectacle) gazingstock, look to, (that) see(-th)."]', '["n-m"]', 'sight, whether abstractly (vision) or concretely (a spectacle) gazingstock, look to, (that) see(-th).', 'from 7200;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7211}/[H7211]', 'lemma', 'heb', 'רְאָיָה', '["Rᵉʼâyâh"]', '["Reajah, the name of three Israelites Reaia, Reaiah."]', '["n-pr-m"]', 'Reajah, the name of three Israelites Reaia, Reaiah.', 'from 7200 and 3050; Jah has seen;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7212}/[H7212]', 'lemma', 'heb', 'רְאִית', '["rᵉʼîyth"]', '["sight beholding."]', '["n-f"]', 'sight beholding.', 'from 7200a;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7213]', 'root', 'heb', 'רָאַם', '["râʼam"]', '["to rise be lifted up."]', '["v"]', 'to rise be lifted up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7214}/[H7214]', 'lemma', 'heb', 'רְאֵם', '["rᵉʼêm"]', '["a wild bull (from its conspicuousness) unicorn."]', '["n-m"]', 'a wild bull (from its conspicuousness) unicorn.', 'or רְאֵיםlemma רְאיֵם second vowel, corrected to רְאֵים; or רֵים; or רֵם; from 7213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7215}/[H7215]', 'lemma', 'heb', 'רָאמָה', '["râʼmâh"]', '["something high in value, i.e. perhaps coral coral."]', '["n-f"]', 'something high in value, i.e. perhaps coral coral.', 'from 7213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7216}/[H7216]', 'lemma', 'heb', 'רָאמוֹת', '["Râʼmôwth"]', '["Ramoth, the name of two places in Palestine Ramoth."]', '["n-pr-loc"]', 'Ramoth, the name of two places in Palestine Ramoth.', 'or רָאמֹתxlit Râmôth corrected to Râʼmôth; plural of 7215; heights;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7217}/[H7217]', 'lemma', 'arc', 'רֵאשׁ', '["rêʼsh"]', '["the head; figuratively, the sum chief, head, sum."]', '["n-m"]', 'the head; figuratively, the sum chief, head, sum.', '(Aramaic) corresponding to 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218>', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top."]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7219}/[H7219]', 'lemma', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["a poisonous plant, probably the poppy (from its conspicuous head); generally poison (even of serpents) gall, hemlock, poison, venom."]', '["n-m"]', 'a poisonous plant, probably the poppy (from its conspicuous head); generally poison (even of serpents) gall, hemlock, poison, venom.', 'or רוֹשׁ; (Deuteronomy 32:32), apparently the same as 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7220}/[H7220]', 'lemma', 'heb', 'רֹאשׁ', '["Rôʼsh"]', '["Rosh, the name of an Israelite and of a foreign nation Rosh."]', '["n-pr-m"]', 'Rosh, the name of an Israelite and of a foreign nation Rosh.', 'probably the same as 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7221}/[H7221]', 'lemma', 'heb', 'רִאשָׁה', '["riʼshâh"]', '["a beginning beginning."]', '["n-f"]', 'a beginning beginning.', 'from the same as 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7222}/[H7222]', 'lemma', 'heb', 'רֹאשָׁה', '["rôʼshâh"]', '["the head head(-stone)."]', '["n-f"]', 'the head head(-stone).', 'feminine of 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7223}/[H7223]', 'lemma', 'heb', 'רִאשׁוֹן', '["riʼshôwn"]', '["first, in place, time or rank (as adjective or noun) ancestor, (that were) before(-time), beginning, eldest, first, fore(-father) (-most), former (thing), of old time, past."]', '["a"]', 'first, in place, time or rank (as adjective or noun) ancestor, (that were) before(-time), beginning, eldest, first, fore(-father) (-most), former (thing), of old time, past.', 'or רִאשֹׁן; from 7221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7224}/[H7224]', 'lemma', 'heb', 'רִאשֹׁנִי', '["riʼshônîy"]', '["first first."]', '["a"]', 'first first.', 'from 7223;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7225}/[H7225]', 'lemma', 'heb', 'רֵאשִׁית', '["rêʼshîyth"]', '["the first, in place, time, order or rank (specifically, a firstfruit) beginning, chief(-est), first(-fruits, part, time), principal thing."]', '["n-f"]', 'the first, in place, time, order or rank (specifically, a firstfruit) beginning, chief(-est), first(-fruits, part, time), principal thing.', 'from the same as 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7226}/[H7226]', 'lemma', 'heb', 'רַאֲשֹׁת', '["raʼăshôth"]', '["a pillow (being for the head) bolster."]', '["n-f"]', 'a pillow (being for the head) bolster.', 'from 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7227}/[H7227]', 'lemma', 'heb', 'רַב', '["rab"]', '["abundant (in quantity, size, age, number, rank, quality) (in) abound(-undance, -ant, -antly), captain, elder, enough, exceedingly, full, great(-ly, man, one), increase, long (enough, (time)), (do, have) many(-ifold, things, a time), (ship-)master, mighty, more, (too, very) much, multiply(-tude), officer, often(-times), plenteous, populous, prince, process (of time), suffice(-lent)."]', '["a n-m"]', 'abundant (in quantity, size, age, number, rank, quality) (in) abound(-undance, -ant, -antly), captain, elder, enough, exceedingly, full, great(-ly, man, one), increase, long (enough, (time)), (do, have) many(-ifold, things, a time), (ship-)master, mighty, more, (too, very) much, multiply(-tude), officer, often(-times), plenteous, populous, prince, process (of time), suffice(-lent).', 'by contracted from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7228}/[H7228]', 'lemma', 'heb', 'רַב', '["rab"]', '["an archer archer."]', '["n-m"]', 'an archer archer.', 'by contraction from 7232; (or perhaps the same as 7227)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7229}/[H7229]', 'lemma', 'arc', 'רַב', '["rab"]', '["captain, chief, great, lord, master, stout."]', '["a"]', 'captain, chief, great, lord, master, stout.', '(Aramaic) corresponding to 7227');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7230}/[H7230]', 'lemma', 'heb', 'רֹב', '["rôb"]', '["abundance (in any respect) abundance(-antly), all, × common (sort), excellent, great(-ly, -ness, number), huge, be increased, long, many, more in number, most, much, multitude, plenty(-ifully), × very (age)."]', '["n-m"]', 'abundance (in any respect) abundance(-antly), all, × common (sort), excellent, great(-ly, -ness, number), huge, be increased, long, many, more in number, most, much, multitude, plenty(-ifully), × very (age).', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7231]', 'root', 'heb', 'רָבַב', '["râbab"]', '["properly, to cast together , i.e. increase, especially in number; to multiply by the myriad increase, be many(-ifold), be more, multiply, ten thousands."]', '["v"]', 'properly, to cast together , i.e. increase, especially in number; to multiply by the myriad increase, be many(-ifold), be more, multiply, ten thousands.', 'a primitive root; (compare 7241); also as denominative from 7233;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7232]', 'root', 'heb', 'רָבַב', '["râbab"]', '["to shoot an arrow shoot."]', '["v"]', 'to shoot an arrow shoot.', 'a primitive root (rather identical with 7231 through the idea of projection);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7233}/[H7233]', 'lemma', 'heb', 'רְבָבָה', '["rᵉbâbâh"]', '["abundance (in number), i.e. (specifically) a myriad (whether definite or indefinite) many, million, × multiply, ten thousand."]', '["n-f"]', 'abundance (in number), i.e. (specifically) a myriad (whether definite or indefinite) many, million, × multiply, ten thousand.', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7234]', 'root', 'heb', 'רָבַד', '["râbad"]', '["to spread deck."]', '["v"]', 'to spread deck.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7235]', 'root', 'heb', 'רָבָה', '["râbâh"]', '["to increase (in whatever respect) (bring in) abundance (× -antly), archer (by mistake for 7232), be in authority, bring up, × continue, enlarge, excel, exceeding(-ly), be full of, (be, make) great(-er, -ly, × -ness), grow up, heap, increase, be long, (be, give, have, make, use) many (a time), (any, be, give, give the, have) more (in number), (ask, be, be so, gather, over, take, yield) much (greater, more), (make to) multiply, nourish, plenty(-eous), × process (of time), sore, store, thoroughly, very."]', '["v"]', 'to increase (in whatever respect) (bring in) abundance (× -antly), archer (by mistake for 7232), be in authority, bring up, × continue, enlarge, excel, exceeding(-ly), be full of, (be, make) great(-er, -ly, × -ness), grow up, heap, increase, be long, (be, give, have, make, use) many (a time), (any, be, give, give the, have) more (in number), (ask, be, be so, gather, over, take, yield) much (greater, more), (make to) multiply, nourish, plenty(-eous), × process (of time), sore, store, thoroughly, very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7236}/[H7236]', 'lemma', 'arc', 'רְבָה', '["rᵉbâh"]', '["make a great man, grow."]', '["v"]', 'make a great man, grow.', '(Aramaic) corresponding to 7235');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7237}/[H7237]', 'lemma', 'heb', 'רַבָּה', '["Rabbâh"]', '["Rabbah, the name of two places in Palestine, East and West Rabbah, Rabbath."]', '["n-pr-loc"]', 'Rabbah, the name of two places in Palestine, East and West Rabbah, Rabbath.', 'feminine of 7227; great;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7238}/[H7238]', 'lemma', 'arc', 'רְבוּ', '["rᵉbûw"]', '["increase (of dignity) greatness, majesty."]', '["n-f"]', 'increase (of dignity) greatness, majesty.', '(Aramaic) from a root corresponding to 7235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7239}/[H7239]', 'lemma', 'heb', 'רִבּוֹ', '["ribbôw"]', '["a myriad, i.e. indefinitely, large number great things, ten ((eight) -een, (for) -ty, sixscore, threescore, × twenty, (twen) -ty) thousand."]', '["n-f"]', 'a myriad, i.e. indefinitely, large number great things, ten ((eight) -een, (for) -ty, sixscore, threescore, × twenty, (twen) -ty) thousand.', 'from 7231; or רִבּוֹא from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7240}/[H7240]', 'lemma', 'arc', 'רִבּוֹ', '["ribbôw"]', '["× ten thousand times ten thousand."]', '["n-f"]', '× ten thousand times ten thousand.', '(Aramaic) corresponding to 7239');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7241}/[H7241]', 'lemma', 'heb', 'רָבִיב', '["râbîyb"]', '["a rain (as an accumulation of drops) shower."]', '["n-m"]', 'a rain (as an accumulation of drops) shower.', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7242}/[H7242]', 'lemma', 'heb', 'רָבִיד', '["râbîyd"]', '["a collar (as spread around the neck) chain."]', '["n-m"]', 'a collar (as spread around the neck) chain.', 'from 7234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7243}/[H7243]', 'lemma', 'heb', 'רְבִיעִי', '["rᵉbîyʻîy"]', '["fourth; also (fractionally) a fourth foursquare, fourth (part)."]', '["a"]', 'fourth; also (fractionally) a fourth foursquare, fourth (part).', 'or רְבִעִי; from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7244}/[H7244]', 'lemma', 'arc', 'רְבִיעַי', '["rᵉbîyʻay"]', '["fourth."]', '["a"]', 'fourth.', '(Aramaic) corresponding to 7243');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7245}/[H7245]', 'lemma', 'heb', 'רַבִּית', '["Rabbîyth"]', '["Rabbith, a place in Palestine Rabbith."]', '["n-pr-loc"]', 'Rabbith, a place in Palestine Rabbith.', 'from 7231; multitude;');
