INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7247>', 'opaque', 'heb', 'רִבְלָה', '["Riblâh"]', '["Riblah, a place in Syria Riblah."]', '["n-pr-loc"]', 'Riblah, a place in Syria Riblah.', 'from an unused root meaning to be fruitful; fertile;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7248}/[H7248]', 'lemma', 'heb', 'רַב־מָג', '["Rab-Mâg"]', '["Rab-Mag, a Babylonian official Rab-mag."]', '["n-m"]', 'Rab-Mag, a Babylonian official Rab-mag.', 'from 7227 and a foreign word for a Magian; chief Magian;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7249}/[H7249]', 'lemma', 'heb', 'רַב־סָרִיס', '["Rab-Çârîyç"]', '["Rab-Saris, a Babylonian official Rab-saris."]', '["n-pr-m"]', 'Rab-Saris, a Babylonian official Rab-saris.', 'from 7227 and a foreign word for a eunuch; chief chamberlain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7250]', 'root', 'heb', 'רָבַע', '["râbaʻ"]', '["to squat or lie out flat, i.e. (specifically) in copulation let gender, lie down."]', '["v"]', 'to squat or lie out flat, i.e. (specifically) in copulation let gender, lie down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7251]', 'root', 'heb', 'רָבַע', '["râbaʻ"]', '["to be quadrate (four-) square(-d)."]', '["v"]', 'to be quadrate (four-) square(-d).', 'a primitive root (rather identical with 7250 through the idea of sprawling ''at all fours'' (or possibly the reverse is the order of deriv.); compare 702); properly, to be four (sided); used only as denominative of 7253;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7252}/[H7252]', 'lemma', 'heb', 'רֶבַע', '["rebaʻ"]', '["prostration (for sleep) lying down."]', '["v"]', 'prostration (for sleep) lying down.', 'from 7250;');
