INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7254}/[H7254]', 'lemma', 'heb', 'רֶבַע', '["Rebaʻ"]', '["Reba, a Midianite Reba."]', '["n-m"]', 'Reba, a Midianite Reba.', 'the same as 7253;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7255}/[H7255]', 'lemma', 'heb', 'רֹבַע', '["rôbaʻ"]', '["a quarter fourth participle"]', '["n-m"]', 'a quarter fourth participle', 'from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7256}/[H7256]', 'lemma', 'heb', 'רִבֵּעַ', '["ribbêaʻ"]', '["a descendant of the fourth generation, i.e. great great grandchild fourth."]', '["a"]', 'a descendant of the fourth generation, i.e. great great grandchild fourth.', 'from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7257]', 'root', 'heb', 'רָבַץ', '["râbats"]', '["to crouch (on all four legs folded, like a recumbent animal); by implication, to recline, repose, brood, lurk, imbed crouch (down), fall down, make a fold, lay, (cause to, make to) lie (down), make to rest, sit."]', '["v"]', 'to crouch (on all four legs folded, like a recumbent animal); by implication, to recline, repose, brood, lurk, imbed crouch (down), fall down, make a fold, lay, (cause to, make to) lie (down), make to rest, sit.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7258}/[H7258]', 'lemma', 'heb', 'רֵבֶץ', '["rêbets"]', '["a couch or place of repose where each lay, lie down in, resting place."]', '["n-m"]', 'a couch or place of repose where each lay, lie down in, resting place.', 'from 7257;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7260}/[H7260]', 'lemma', 'arc', 'רַבְרַב', '["rabrab"]', '["huge (in size); domineering (in character) (very) great (things)."]', '["a"]', 'huge (in size); domineering (in character) (very) great (things).', '(Aramaic) from 7229;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7261}/[H7261]', 'lemma', 'arc', 'רַבְרְבָן', '["rabrᵉbân"]', '["a magnate lord, prince."]', '["n-m"]', 'a magnate lord, prince.', '(Aramaic) from 7260;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7262}/[H7262]', 'lemma', 'heb', 'רַבְשָׁקֵה', '["Rabshâqêh"]', '["Rabshakeh, a Babylonian official Rabshakeh."]', '["n-m"]', 'Rabshakeh, a Babylonian official Rabshakeh.', 'from 7227 and 8248; chief butler;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7264]', 'root', 'heb', 'רָגַז', '["râgaz"]', '["to quiver (with any violent emotion, especially anger or fear) be afraid, stand in awe, disquiet, fall out, fret, move, provoke, quake, rage, shake, tremble, trouble, be wroth."]', '["v"]', 'to quiver (with any violent emotion, especially anger or fear) be afraid, stand in awe, disquiet, fall out, fret, move, provoke, quake, rage, shake, tremble, trouble, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7265}/[H7265]', 'lemma', 'arc', 'רְגַז', '["rᵉgaz"]', '["provoke unto wrath."]', '["v"]', 'provoke unto wrath.', '(Aramaic) corresponding to 7264');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7266}/[H7266]', 'lemma', 'arc', 'רְגַז', '["rᵉgaz"]', '["violent anger rage."]', '["n-m"]', 'violent anger rage.', '(Aramaic) from 7265;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7267}/[H7267]', 'lemma', 'heb', 'רֹגֶז', '["rôgez"]', '["commotion, restlessness (of a horse), crash (of thunder), disquiet, anger fear, noise, rage, trouble(-ing), wrath."]', '["n-m"]', 'commotion, restlessness (of a horse), crash (of thunder), disquiet, anger fear, noise, rage, trouble(-ing), wrath.', 'from 7264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7268}/[H7268]', 'lemma', 'heb', 'רַגָּז', '["raggâz"]', '["timid trembling."]', '["a"]', 'timid trembling.', 'intensive from 7264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7269}/[H7269]', 'lemma', 'heb', 'רׇגְזָה', '["rogzâh"]', '["trepidation trembling."]', '["n-f"]', 'trepidation trembling.', 'feminine of 7267;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7270]', 'root', 'heb', 'רָגַל', '["râgal"]', '["to walk along; but only in specifically, applications, to reconnoiter, to be a tale-bearer (i.e. slander); to lead about backbite, search, slander, (e-) spy (out), teach to go, view."]', '["v"]', 'to walk along; but only in specifically, applications, to reconnoiter, to be a tale-bearer (i.e. slander); to lead about backbite, search, slander, (e-) spy (out), teach to go, view.', 'a primitive root; also as denominative from 7272');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7271}/[H7271]', 'lemma', 'arc', 'רְגַל', '["rᵉgal"]', '["foot."]', '["n-f"]', 'foot.', '(Aramaic) corresponding to 7272');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7272}/[H7272]', 'lemma', 'heb', 'רֶגֶל', '["regel"]', '["a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time."]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7273}/[H7273]', 'lemma', 'heb', 'רַגְלִי', '["raglîy"]', '["a footman (soldier) (on) foot(-man)."]', '["a"]', 'a footman (soldier) (on) foot(-man).', 'from 7272;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7274}/[H7274]', 'lemma', 'heb', 'רֹגְלִים', '["Rôgᵉlîym"]', '["Rogelim, a place East of the Jordan Rogelim."]', '["n-pr-loc"]', 'Rogelim, a place East of the Jordan Rogelim.', 'plural of active participle of 7270; fullers (as tramping the cloth in washing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7275]', 'root', 'heb', 'רָגַם', '["râgam"]', '["to cast together (stones), i.e. to lapidate × certainly, stone."]', '["v"]', 'to cast together (stones), i.e. to lapidate × certainly, stone.', 'a primitive root (compare 7263, 7321, 7551);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7276}/[H7276]', 'lemma', 'heb', 'רֶגֶם', '["Regem"]', '["Regem, an Israelite Regem."]', '["n-pr-m"]', 'Regem, an Israelite Regem.', 'from 7275; stoneheap;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7277}/[H7277]', 'lemma', 'heb', 'רִגְמָה', '["rigmâh"]', '["a pile (of stones), i.e. (figuratively) a throng council."]', '["n-f"]', 'a pile (of stones), i.e. (figuratively) a throng council.', 'feminine of the same as 7276;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7278}/[H7278]', 'lemma', 'heb', 'רֶגֶם מֶלֶךְ', '["Regem Melek"]', '["Regem-Melek, an Israelite Regem-melech."]', '["n-pr-m"]', 'Regem-Melek, an Israelite Regem-melech.', 'from 7276 and 4428; king''s heap;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7279]', 'root', 'heb', 'רָגַן', '["râgan"]', '["to grumble, i.e. rebel murmur."]', '["v"]', 'to grumble, i.e. rebel murmur.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7280]', 'root', 'heb', 'רָגַע', '["râgaʻ"]', '["properly, to toss violently and suddenly (the sea with waves, the skin with boils); figuratively (in a favorable manner) to settle, i.e. quiet; specifically, to wink (from the motion of the eye-lids) break, divide, find ease, be a moment, (cause, give, make to) rest, make suddenly."]', '["v"]', 'properly, to toss violently and suddenly (the sea with waves, the skin with boils); figuratively (in a favorable manner) to settle, i.e. quiet; specifically, to wink (from the motion of the eye-lids) break, divide, find ease, be a moment, (cause, give, make to) rest, make suddenly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7281}/[H7281]', 'lemma', 'heb', 'רֶגַע', '["regaʻ"]', '["a wink (of the eyes), i.e. a very short space of time instant, moment, space, suddenly."]', '["n-m"]', 'a wink (of the eyes), i.e. a very short space of time instant, moment, space, suddenly.', 'from 7280.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7282}/[H7282]', 'lemma', 'heb', 'רָגֵעַ', '["râgêaʻ"]', '["restful, i.e. peaceable that are quiet."]', '["a"]', 'restful, i.e. peaceable that are quiet.', 'from 7280;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7283]', 'root', 'heb', 'רָגַשׁ', '["râgash"]', '["to be tumultuous rage."]', '["v"]', 'to be tumultuous rage.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7284}/[H7284]', 'lemma', 'arc', 'רְגַשׁ', '["rᵉgash"]', '["to gather tumultuously assemble (together)."]', '["v"]', 'to gather tumultuously assemble (together).', '(Aramaic) corresponding to 7283;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7285}/[H7285]', 'lemma', 'heb', 'רֶגֶשׁ', '["regesh"]', '["a tumultuous crowd company, insurrection."]', '["n-m n-f"]', 'a tumultuous crowd company, insurrection.', 'or (feminine) רִגְשָׁה; from 7283;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7286]', 'root', 'heb', 'רָדַד', '["râdad"]', '["to tread in pieces, i.e. (figuratively) to conquer, or (specifically) to overlay spend, spread, subdue."]', '["v"]', 'to tread in pieces, i.e. (figuratively) to conquer, or (specifically) to overlay spend, spread, subdue.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7287]', 'root', 'heb', 'רָדָה', '["râdâh"]', '["to tread down, i.e. subjugate; specifically, to crumble off (come to, make to) have dominion, prevail against, reign, (bear, make to) rule,(-r, over), take."]', '["v"]', 'to tread down, i.e. subjugate; specifically, to crumble off (come to, make to) have dominion, prevail against, reign, (bear, make to) rule,(-r, over), take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7288}/[H7288]', 'lemma', 'heb', 'רַדַּי', '["Radday"]', '["Raddai, an Israelite Raddai."]', '["n-pr-m"]', 'Raddai, an Israelite Raddai.', 'intensive from 7287; domineering;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7289}/[H7289]', 'lemma', 'heb', 'רָדִיד', '["râdîyd"]', '["a veil (as expanded) vail, veil."]', '["n-m"]', 'a veil (as expanded) vail, veil.', 'from 7286 in the sense of spreading;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7290]', 'root', 'heb', 'רָדַם', '["râdam"]', '["to stun, i.e. stupefy (with sleep or death) (be fast a-, be in a deep, cast into a dead, that) sleep(-er, -eth)."]', '["v"]', 'to stun, i.e. stupefy (with sleep or death) (be fast a-, be in a deep, cast into a dead, that) sleep(-er, -eth).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7291]', 'root', 'heb', 'רָדַף', '["râdaph"]', '["to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r)."]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7292]', 'root', 'heb', 'רָהַב', '["râhab"]', '["to urge severely, i.e. (figuratively) importune, embolden, capture, act insolently overcome, behave self proudly, make sure, strengthen."]', '["v"]', 'to urge severely, i.e. (figuratively) importune, embolden, capture, act insolently overcome, behave self proudly, make sure, strengthen.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7293}/[H7293]', 'lemma', 'heb', 'רַהַב', '["rahab"]', '["bluster(-er) proud, strength."]', '["n-m"]', 'bluster(-er) proud, strength.', 'from 7292,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7294}/[H7294]', 'lemma', 'heb', 'רַהַב', '["Rahab"]', '["Rahab (i.e. boaster), an epithet of Egypt Rahab."]', '["n-m"]', 'Rahab (i.e. boaster), an epithet of Egypt Rahab.', 'the same as 7293;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7295}/[H7295]', 'lemma', 'heb', 'רָהָב', '["râhâb"]', '["insolent proud."]', '["a"]', 'insolent proud.', 'from 7292;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7296}/[H7296]', 'lemma', 'heb', 'רֹהָב', '["rôhâb"]', '["pride strength."]', '["n-m"]', 'pride strength.', 'from 7292;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7297]', 'root', 'heb', 'רָהָה', '["râhâh"]', '["to fear be afraid."]', '["v"]', 'to fear be afraid.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7298>', 'opaque', 'heb', 'רַהַט', '["rahaṭ"]', '["a channel or watering-box; by resemblance a ringlet of hair (as forming parallel lines) gallery, gutter, trough."]', '["n-m"]', 'a channel or watering-box; by resemblance a ringlet of hair (as forming parallel lines) gallery, gutter, trough.', 'from an unused root apparently meaning to hollow out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7299}/[H7299]', 'lemma', 'arc', 'רֵו', '["rêv"]', '["aspect form."]', '["n-m"]', 'aspect form.', '(Aramaic) from a root corresponding to 7200;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7300]', 'root', 'heb', 'רוּד', '["rûwd"]', '["to tramp about, i.e. ramble (free or disconsolate) have the dominion, be lord, mourn, rule."]', '["v"]', 'to tramp about, i.e. ramble (free or disconsolate) have the dominion, be lord, mourn, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7301]', 'root', 'heb', 'רָוָה', '["râvâh"]', '["to slake the thirst (occasionally of other appetites) bathe, make drunk, (take the) fill, satiate, (abundantly) satisfy, soak, water (abundantly)."]', '["v"]', 'to slake the thirst (occasionally of other appetites) bathe, make drunk, (take the) fill, satiate, (abundantly) satisfy, soak, water (abundantly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7302}/[H7302]', 'lemma', 'heb', 'רָוֶה', '["râveh"]', '["sated (with drink) drunkenness, watered."]', '["a"]', 'sated (with drink) drunkenness, watered.', 'from 7301;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7303>', 'opaque', 'heb', 'רוֹהֲגָה', '["Rôwhăgâh"]', '["Rohagah, an Israelite Rohgah."]', '["n-pr-m"]', 'Rohagah, an Israelite Rohgah.', 'from an unused root probably meaning to cry out; outcry;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7304]', 'root', 'heb', 'רָוַח', '["râvach"]', '["properly, to breathe freely, i.e. revive; by implication, to have ample room be refreshed, large."]', '["v"]', 'properly, to breathe freely, i.e. revive; by implication, to have ample room be refreshed, large.', 'a primitive root (identical with 7306);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7305}/[H7305]', 'lemma', 'heb', 'רֶוַח', '["revach"]', '["room, literally (an interval) or figuratively (deliverance) enlargement, space."]', '["n-m"]', 'room, literally (an interval) or figuratively (deliverance) enlargement, space.', 'from 7304;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7306]', 'root', 'heb', 'רוּחַ', '["rûwach"]', '["properly, to blow, i.e. breathe; only (literally) to smell or (by implication, perceive (figuratively, to anticipate, enjoy) accept, smell, × touch, make of quick understanding."]', '["v"]', 'properly, to blow, i.e. breathe; only (literally) to smell or (by implication, perceive (figuratively, to anticipate, enjoy) accept, smell, × touch, make of quick understanding.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7307}/[H7307]', 'lemma', 'heb', 'רוּחַ', '["rûwach"]', '["wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y)."]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7308}/[H7308]', 'lemma', 'arc', 'רוּחַ', '["rûwach"]', '["mind, spirit, wind."]', '["n-f"]', 'mind, spirit, wind.', '(Aramaic) corresponding to 7307');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7309}/[H7309]', 'lemma', 'heb', 'רְוָחָה', '["rᵉvâchâh"]', '["relief breathing, respite."]', '["n-f"]', 'relief breathing, respite.', 'feminine of 7305;');
