INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7321]', 'root', 'heb', 'רוּעַ', '["rûwaʻ"]', '["to mar (especially by breaking); figuratively, to split the ears (with sound), i.e. shout (for alarm or joy) blow an alarm, cry (alarm, aloud, out), destroy, make a joyful noise, smart, shout (for joy), sound an alarm, triumph."]', '["v"]', 'to mar (especially by breaking); figuratively, to split the ears (with sound), i.e. shout (for alarm or joy) blow an alarm, cry (alarm, aloud, out), destroy, make a joyful noise, smart, shout (for joy), sound an alarm, triumph.', 'a primitive root;');
