INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7378]', 'root', 'heb', 'רִיב', '["rîyb"]', '["properly, to toss, i.e. grapple; mostly figuratively, to wrangle, i.e. hold a controversy; (by implication) to defend adversary, chide, complain, contend, debate, × ever, × lay wait, plead, rebuke, strive, × thoroughly."]', '["v"]', 'properly, to toss, i.e. grapple; mostly figuratively, to wrangle, i.e. hold a controversy; (by implication) to defend adversary, chide, complain, contend, debate, × ever, × lay wait, plead, rebuke, strive, × thoroughly.', 'or רוּב; a primitive root;');
