INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7417}/[H7417]', 'lemma', 'heb', 'רִמּוֹן', '["Rimmôwn"]', '["Rimmon, the name of a Syrian deity, also of five places in Palestine Remmon, Rimmon."]', '["n-pr-m n-pr-loc"]', 'Rimmon, the name of a Syrian deity, also of five places in Palestine Remmon, Rimmon.', 'or (shorter) (רִמֹּן; or רִמּוֹנוֹ; (1 Chronicles 6:62 (77)), the same as 7416; in Joshua 19:13: הַמְּתֹאָר is mistaken for part of a name; article with the passive participle of 8388; the (one) marked off, i.e. which pertains).');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7418}/[H7418]', 'lemma', 'heb', 'רָמוֹת', '["Râmôwth"]', '["Ramoth-Negeb or Ramath-Negeb, a place in Palestine south Ramoth, Ramath of the south."]', '["n-pr-loc"]', 'Ramoth-Negeb or Ramath-Negeb, a place in Palestine south Ramoth, Ramath of the south.', 'or רָמַת נֶגֶב; from the plural or construct form of 7413 and 5045; heights (or height) of the South;');
