INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7429]', 'root', 'heb', 'רָמַס', '["râmaç"]', '["to tread upon (as a potter, in walking or abusively) oppressor, stamp upon, trample (under feet), tread (down, upon)."]', '["v"]', 'to tread upon (as a potter, in walking or abusively) oppressor, stamp upon, trample (under feet), tread (down, upon).', 'a primitive root;');
