INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7432}/[H7432]', 'lemma', 'heb', 'רֶמֶת', '["Remeth"]', '["Remeth, a place in Palestine Remeth."]', '["n-pr-loc"]', 'Remeth, a place in Palestine Remeth.', 'from 7411; height;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7433}/[H7433]', 'lemma', 'heb', 'רָמֹת גִּלעָד', '["Râmôth Gilʻâd"]', '["Ramoth-Gilad, a place East of the Jordan Ramoth-gilead, Ramoth in Gilead. See also 7216."]', '["n-pr-m n-pr-loc"]', 'Ramoth-Gilad, a place East of the Jordan Ramoth-gilead, Ramoth in Gilead. See also 7216.', 'or רָמוֹת גִּלעָד; (2 Chronicles 22:5), from the plural of 7413 and 1568; heights of Gilad;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7434}/[H7434]', 'lemma', 'heb', 'רָמַת הַמִּצְפֶּה', '["Râmath ham-Mit-speh"]', '["Ramath-ham-Mitspeh, a place in Palestine Ramath-mizpeh."]', '["n-pr-loc"]', 'Ramath-ham-Mitspeh, a place in Palestine Ramath-mizpeh.', 'from 7413 and 4707 with the article interpolated; height of the watch-tower;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7435}/[H7435]', 'lemma', 'heb', 'רָמָתִי', '["Râmâthîy"]', '["a Ramathite or inhabitant of Ramah Ramathite."]', '["a"]', 'a Ramathite or inhabitant of Ramah Ramathite.', 'patronymic of 7414;');
