INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7439]', 'root', 'heb', 'רָנָה', '["rânâh"]', '["to whiz rattle."]', '["v"]', 'to whiz rattle.', 'a primitive root;');
