INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7442]', 'root', 'heb', 'רָנַן', '["rânan"]', '["properly, to creak (or emit a stridulous sound), i.e. to shout (usually for joy) aloud for joy, cry out, be joyful (greatly, make to) rejoice, (cause to) shout (for joy), (cause to) sing (aloud, for joy, out), triumph."]', '["v"]', 'properly, to creak (or emit a stridulous sound), i.e. to shout (usually for joy) aloud for joy, cry out, be joyful (greatly, make to) rejoice, (cause to) shout (for joy), (cause to) sing (aloud, for joy, out), triumph.', 'a primitive root;');
