INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7454}/[H7454]', 'lemma', 'heb', 'רֵעַ', '["rêaʻ"]', '["a thought (as association of ideas) thought."]', '["n-m"]', 'a thought (as association of ideas) thought.', 'from 7462;');
