INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7466}/[H7466]', 'lemma', 'heb', 'רְעוּ', '["Rᵉʻûw"]', '["Reu, a postdiluvian patriarch Reu."]', '["n-pr-m"]', 'Reu, a postdiluvian patriarch Reu.', 'for 7471 in the sense of 7453; friend;');
