INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7481]', 'root', 'heb', 'רָעַם', '["râʻam"]', '["to tumble, i.e. be violently agitated; specifically, to crash (of thunder); figuratively, to irritate (with anger) make to fret, roar, thunder, trouble."]', '["v"]', 'to tumble, i.e. be violently agitated; specifically, to crash (of thunder); figuratively, to irritate (with anger) make to fret, roar, thunder, trouble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7482}/[H7482]', 'lemma', 'heb', 'רַעַם', '["raʻam"]', '["a peal of thunder thunder."]', '["n-m"]', 'a peal of thunder thunder.', 'from 7481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7483}/[H7483]', 'lemma', 'heb', 'רַעְמָה', '["raʻmâh"]', '["the mane of a horse (as quivering in the wind) thunder."]', '["n-f"]', 'the mane of a horse (as quivering in the wind) thunder.', 'feminine of 7482;');
