INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7485}/[H7485]', 'lemma', 'heb', 'רַעַמְיָה', '["Raʻamyâh"]', '["Raamjah, an Israelite Raamiah."]', '["n-pr-m"]', 'Raamjah, an Israelite Raamiah.', 'from 7481 and 3050; Jah has shaken;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7486}/[H7486]', 'lemma', 'heb', 'רַעְמְסֵס', '["Raʻmᵉçêç"]', '["Rameses or Raamses, a place in Egypt Raamses, Rameses."]', '["n-pr-loc"]', 'Rameses or Raamses, a place in Egypt Raamses, Rameses.', 'or רַעַמְסֵס; of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7487}/[H7487]', 'lemma', 'arc', 'רַעֲנַן', '["raʻănan"]', '["green, i.e. (figuratively) prosperous flourishing."]', '["a"]', 'green, i.e. (figuratively) prosperous flourishing.', '(Aramaic) corresponding to 7488;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7488>', 'opaque', 'heb', 'רַעֲנָן', '["raʻănân"]', '["verdant; by analogy, new; figuratively, prosperous green, flourishing."]', '["v a"]', 'verdant; by analogy, new; figuratively, prosperous green, flourishing.', 'from an unused root meaning to be green;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7489]', 'root', 'heb', 'רָעַע', '["râʻaʻ"]', '["properly, to spoil (literally, by breaking to pieces); figuratively, to make (or be) good for nothing, i.e. bad (physically, socially or morally) afflict, associate selves (by mistake for 7462), break (down, in pieces), displease, (be, bring, do) evil (doer, entreat, man), show self friendly (by mistake for 7462), do harm, (do) hurt, (behave self, deal) ill, × indeed, do mischief, punish, still, vex, (do) wicked (doer, -ly), be (deal, do) worse."]', '["v"]', 'properly, to spoil (literally, by breaking to pieces); figuratively, to make (or be) good for nothing, i.e. bad (physically, socially or morally) afflict, associate selves (by mistake for 7462), break (down, in pieces), displease, (be, bring, do) evil (doer, entreat, man), show self friendly (by mistake for 7462), do harm, (do) hurt, (behave self, deal) ill, × indeed, do mischief, punish, still, vex, (do) wicked (doer, -ly), be (deal, do) worse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7490}/[H7490]', 'lemma', 'arc', 'רְעַע', '["rᵉʻaʻ"]', '["break, bruise."]', '["v"]', 'break, bruise.', '(Aramaic) corresponding to 7489');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7491]', 'root', 'heb', 'רָעַף', '["râʻaph"]', '["to drip distil, drop (down)."]', '["v"]', 'to drip distil, drop (down).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7492]', 'root', 'heb', 'רָעַץ', '["râʻats"]', '["to break in pieces; figuratively, harass dash in pieces, vex."]', '["v"]', 'to break in pieces; figuratively, harass dash in pieces, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7493]', 'root', 'heb', 'רָעַשׁ', '["râʻash"]', '["to undulate (as the earth, the sky, etc.; also a field of grain), particularly through fear; specifically, to spring (as a locust) make afraid, (re-) move, quake, (make to) shake, (make to) tremble."]', '["v"]', 'to undulate (as the earth, the sky, etc.; also a field of grain), particularly through fear; specifically, to spring (as a locust) make afraid, (re-) move, quake, (make to) shake, (make to) tremble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7494}/[H7494]', 'lemma', 'heb', 'רַעַשׁ', '["raʻash"]', '["vibration, bounding, uproar commotion, confused noise, earthquake, fierceness, quaking, rattling, rushing, shaking."]', '["n-m"]', 'vibration, bounding, uproar commotion, confused noise, earthquake, fierceness, quaking, rattling, rushing, shaking.', 'from 7493;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7495]', 'root', 'heb', 'רָפָא', '["râphâʼ"]', '["properly, to mend (by stitching), i.e. (figuratively) to cure cure, (cause to) heal, physician, repair, × thoroughly, make whole. See 7503."]', '["v"]', 'properly, to mend (by stitching), i.e. (figuratively) to cure cure, (cause to) heal, physician, repair, × thoroughly, make whole. See 7503.', 'or רָפָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7496}/[H7496]', 'lemma', 'heb', 'רָפָא', '["râphâʼ"]', '["properly, lax, i.e. (figuratively) a ghost (as dead; in plural only) dead, deceased."]', '["n-m"]', 'properly, lax, i.e. (figuratively) a ghost (as dead; in plural only) dead, deceased.', 'from 7495 in the sense of 7503;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7497}/[H7497]', 'lemma', 'heb', 'רָפָא', '["râphâʼ"]', '["a giant giant, Rapha, Rephaim(-s). See also 1051."]', '["n-pr-m"]', 'a giant giant, Rapha, Rephaim(-s). See also 1051.', 'or רָפָה; from 7495 in the sense of invigorating;');
