INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7502]', 'root', 'heb', 'רָפַד', '["râphad"]', '["to spread (a bed); by implication, to refresh comfort, make (a bed), spread."]', '["v"]', 'to spread (a bed); by implication, to refresh comfort, make (a bed), spread.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7503]', 'root', 'heb', 'רָפָה', '["râphâh"]', '["to slacken (in many applications, literal or figurative) abate, cease, consume, draw (toward evening), fail, (be) faint, be (wax) feeble, forsake, idle, leave, let alone (go, down), (be) slack, stay, be still, be slothful, (be) weak(-en). See 7495."]', '["v"]', 'to slacken (in many applications, literal or figurative) abate, cease, consume, draw (toward evening), fail, (be) faint, be (wax) feeble, forsake, idle, leave, let alone (go, down), (be) slack, stay, be still, be slothful, (be) weak(-en). See 7495.', 'a primitive root;');
