INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7506>', 'opaque', 'heb', 'רֶפַח', '["Rephach"]', '["Rephach, an Israelite Rephah."]', '["n-pr-m"]', 'Rephach, an Israelite Rephah.', 'from an unused root apparently meaning to sustain; support;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7507}/[H7507]', 'lemma', 'heb', 'רְפִידָה', '["rᵉphîydâh"]', '["a railing (as spread along) bottom."]', '["n-f"]', 'a railing (as spread along) bottom.', 'from 7502;');
