INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7617]', 'root', 'heb', 'שָׁבָה', '["shâbâh"]', '["to transport into captivity (bring away, carry, carry away, lead, lead away, take) captive(-s), drive (take) away."]', '["v"]', 'to transport into captivity (bring away, carry, carry away, lead, lead away, take) captive(-s), drive (take) away.', 'a primitive root;');
