INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7620}/[H7620]', 'lemma', 'heb', 'שָׁבוּעַ', '["shâbûwaʻ"]', '["literally, sevened, i.e. a week (specifically, of years) seven, week."]', '["n-m"]', 'literally, sevened, i.e. a week (specifically, of years) seven, week.', 'or שָׁבֻעַ; also (feminine) שְׁבֻעָה; properly, passive participle of 7650 as a denominative of 7651;');
