INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7633}/[H7633]', 'lemma', 'heb', 'שִׁבְיָה', '["shibyâh"]', '["exile (abstractly or concretely and collectively) captives(-ity)."]', '["n-f"]', 'exile (abstractly or concretely and collectively) captives(-ity).', 'feminine of 7628;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7634}/[H7634]', 'lemma', 'heb', 'שׇׁבְיָה', '["Shobyâh"]', '["Shobjah, an Israelite Shachia (from the margin)."]', '["n-pr-m"]', 'Shobjah, an Israelite Shachia (from the margin).', 'feminine of the same as 7629; captivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7635}/[H7635]', 'lemma', 'heb', 'שָׁבִיל', '["shâbîyl"]', '["a track or passage-way (as if flowing along) path."]', '["n-m"]', 'a track or passage-way (as if flowing along) path.', 'from the same as 7640;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7636>', 'opaque', 'heb', 'שָׁבִיס', '["shâbîyç"]', '["a netting for the hair caul."]', '["n-m"]', 'a netting for the hair caul.', 'from an unused root meaning to interweave;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7637}/[H7637]', 'lemma', 'heb', 'שְׁבִיעִי', '["shᵉbîyʻîy"]', '["seventh seventh (time)."]', '["a"]', 'seventh seventh (time).', 'or שְׁבִעִי; ordinal from 7657;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7638>', 'opaque', 'heb', 'שָׂבָךְ', '["sâbâk"]', '["a netting (ornament to the capital of a column) net."]', '["n-m"]', 'a netting (ornament to the capital of a column) net.', 'from an unused root meaning to intwine;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7639}/[H7639]', 'lemma', 'heb', 'שְׂבָכָה', '["sᵉbâkâh"]', '["a net-work, i.e. (in hunting) a snare, (in architecture) a ballustrade; also a reticulated ornament to a pillar checker, lattice, network, snare, wreath(-enwork)."]', '["n-f"]', 'a net-work, i.e. (in hunting) a snare, (in architecture) a ballustrade; also a reticulated ornament to a pillar checker, lattice, network, snare, wreath(-enwork).', 'feminine of 7638;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7641}/[H7641]', 'lemma', 'heb', 'שִׁבֹּל', '["shibbôl"]', '["a stream (as flowing); also an ear of grain (as growing out); by analogy, a branch branch, channel, ear (of corn), (water-)flood, Shibboleth. Compare 5451."]', '["n-f"]', 'a stream (as flowing); also an ear of grain (as growing out); by analogy, a branch branch, channel, ear (of corn), (water-)flood, Shibboleth. Compare 5451.', 'or (feminine) שִׁבֹּלֶת; from the same as 7640;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7642}/[H7642]', 'lemma', 'heb', 'שַׁבְלוּל', '["shablûwl"]', '["a snail (as if floating in its own slime) snail."]', '["n-m"]', 'a snail (as if floating in its own slime) snail.', 'from the same as 7640;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7643}/[H7643]', 'lemma', 'heb', 'שְׂבָם', '["Sᵉbâm"]', '["Sebam or Sibmah, a place in Moab Shebam, Shibmah, Sibmah."]', '["n-pr-loc"]', 'Sebam or Sibmah, a place in Moab Shebam, Shibmah, Sibmah.', 'or (feminine) שִׂבְמָה; probably from 1313; spice;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7645}/[H7645]', 'lemma', 'heb', 'שְׁבַנְיָה', '["Shᵉbanyâh"]', '["Shebanjah, the name of three or four Israelites Shebaniah."]', '["n-pr-m"]', 'Shebanjah, the name of three or four Israelites Shebaniah.', 'or שְׁבַנְיָהוּ; from the same as 7644 and 3050; Jah has grown (i.e. prospered);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7646]', 'root', 'heb', 'שָׂבַע', '["sâbaʻ"]', '["to sate, i.e. fill to satisfaction (literally or figuratively) have enough, fill (full, self, with), be (to the) full (of), have plenty of, be satiate, satisfy (with), suffice, be weary of."]', '["v"]', 'to sate, i.e. fill to satisfaction (literally or figuratively) have enough, fill (full, self, with), be (to the) full (of), have plenty of, be satiate, satisfy (with), suffice, be weary of.', 'or שָׂבֵעַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7647}/[H7647]', 'lemma', 'heb', 'שָׂבָע', '["sâbâʻ"]', '["copiousness abundance, plenteous(-ness, -ly)."]', '["n-m"]', 'copiousness abundance, plenteous(-ness, -ly).', 'from 7646;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7648}/[H7648]', 'lemma', 'heb', 'שֹׂבַע', '["sôbaʻ"]', '["satisfaction (of food or [figuratively] joy) fill, full(-ness), satisfying, be satisfied."]', '["n-m"]', 'satisfaction (of food or [figuratively] joy) fill, full(-ness), satisfying, be satisfied.', 'from 7646;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7649}/[H7649]', 'lemma', 'heb', 'שָׂבֵעַ', '["sâbêaʻ"]', '["satiated (in a pleasant or disagreeable sense) full (of), satisfied (with)."]', '["a"]', 'satiated (in a pleasant or disagreeable sense) full (of), satisfied (with).', 'from 7646;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7650]', 'root', 'heb', 'שָׁבַע', '["shâbaʻ"]', '["to seven oneself, i.e. swear (as if by repeating a declaration seven times) adjure, charge (by an oath, with an oath), feed to the full (by mistake for 7646), take an oath, × straitly, (cause to, make to) swear."]', '["v"]', 'to seven oneself, i.e. swear (as if by repeating a declaration seven times) adjure, charge (by an oath, with an oath), feed to the full (by mistake for 7646), take an oath, × straitly, (cause to, make to) swear.', 'a primitive root; properly to be complete, but used only as a denominative from 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7651}/[H7651]', 'lemma', 'heb', 'שֶׁבַע', '["shebaʻ"]', '["seven (as the sacred full one); also (adverbially) seven times; by implication, a week; by extension, an indefinite number ( by) seven(-fold),-s, (-teen, -teenth), -th, times). Compare 7658."]', '["n"]', 'seven (as the sacred full one); also (adverbially) seven times; by implication, a week; by extension, an indefinite number ( by) seven(-fold),-s, (-teen, -teenth), -th, times). Compare 7658.', 'or (masculine) (שִׁבְעָה); from 7650; a primitive cardinal number;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7652}/[H7652]', 'lemma', 'heb', 'שֶׁבַע', '["shebaʻ"]', '["Sheba, the name of a place in Palestine, and of two Israelites Sheba."]', '["n-pr-m n-pr-loc"]', 'Sheba, the name of a place in Palestine, and of two Israelites Sheba.', 'the same as 7651; seven;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7653}/[H7653]', 'lemma', 'heb', 'שִׂבְעָה', '["sibʻâh"]', '["satiety fulness."]', '["n-f"]', 'satiety fulness.', 'feminine of 7647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7654}/[H7654]', 'lemma', 'heb', 'שׇׂבְעָה', '["sobʻâh"]', '["satiety (to have) enough, × till...be full, (un-) satiable, satisfy, × sufficiently."]', '["n-f"]', 'satiety (to have) enough, × till...be full, (un-) satiable, satisfy, × sufficiently.', 'feminine of 7648;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7655}/[H7655]', 'lemma', 'arc', 'שִׁבְעָה', '["shibʻâh"]', '["seven (times)."]', '["n-f"]', 'seven (times).', '(Aramaic) corresponding to 7651');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7656}/[H7656]', 'lemma', 'heb', 'שִׁבְעָה', '["Shibʻâh"]', '["Shebah, a well in Palestine Shebah."]', '["n-pr-loc"]', 'Shebah, a well in Palestine Shebah.', 'masculine of 7651; seven(-th);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7657}/[H7657]', 'lemma', 'heb', 'שִׁבְעִים', '["shibʻîym"]', '["seventy seventy, threescore and ten ( -teen)."]', '["n"]', 'seventy seventy, threescore and ten ( -teen).', 'multiple of 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7658}/[H7658]', 'lemma', 'heb', 'שִׁבְעָנָה', '["shibʻânâh"]', '["seven seven."]', '["n"]', 'seven seven.', 'prolonged for the masculine of 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7659}/[H7659]', 'lemma', 'heb', 'שִׁבְעָתַיִם', '["shibʻâthayim"]', '["seven-times seven(-fold, times)."]', '["n-f"]', 'seven-times seven(-fold, times).', 'dual (adverbially) of 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7660]', 'root', 'heb', 'שָׁבַץ', '["shâbats"]', '["to interweave (colored) threads in squares; by implication (of reticulation) to inchase gems in gold embroider, set."]', '["v"]', 'to interweave (colored) threads in squares; by implication (of reticulation) to inchase gems in gold embroider, set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7661}/[H7661]', 'lemma', 'heb', 'שָׁבָץ', '["shâbâts"]', '["entanglement, i.e. (figuratively) perplexity anguish."]', '["n-m"]', 'entanglement, i.e. (figuratively) perplexity anguish.', 'from 7660;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7662}/[H7662]', 'lemma', 'arc', 'שְׁבַק', '["shᵉbaq"]', '["to quit, i.e. allow to remain leave, let alone."]', '["v"]', 'to quit, i.e. allow to remain leave, let alone.', '(Aramaic) corresponding to the root of 7733;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7663]', 'root', 'heb', 'שָׂבַר', '["sâbar"]', '["to scrutinize; by implication (of watching) to expect (with hope and patience) hope, tarry, view, wait."]', '["v"]', 'to scrutinize; by implication (of watching) to expect (with hope and patience) hope, tarry, view, wait.', 'erroneously שָׁבַר; (Nehemiah 2:13,15), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7664}/[H7664]', 'lemma', 'heb', 'שֵׂבֶר', '["sêber"]', '["expectation hope."]', '["n-m"]', 'expectation hope.', 'from 7663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7665]', 'root', 'heb', 'שָׁבַר', '["shâbar"]', '["to burst (literally or figuratively) break (down, off, in pieces, up), broken (-hearted), bring to the birth, crush, destroy, hurt, quench, × quite, tear, view (by mistake for 7663)."]', '["v"]', 'to burst (literally or figuratively) break (down, off, in pieces, up), broken (-hearted), bring to the birth, crush, destroy, hurt, quench, × quite, tear, view (by mistake for 7663).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7666}/[H7666]', 'lemma', 'heb', 'שָׁבַר', '["shâbar"]', '["to deal in grain buy, sell."]', '["v"]', 'to deal in grain buy, sell.', 'denominative from 7668;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7667}/[H7667]', 'lemma', 'heb', 'שֶׁבֶר', '["sheber"]', '["a fracture, figuratively, ruin; specifically, a solution (of a dream) affliction, breach, breaking, broken(-footed, -handed), bruise, crashing, destruction, hurt, interpretation, vexation."]', '["n-m"]', 'a fracture, figuratively, ruin; specifically, a solution (of a dream) affliction, breach, breaking, broken(-footed, -handed), bruise, crashing, destruction, hurt, interpretation, vexation.', 'or שֵׁבֶר; from 7665;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7668}/[H7668]', 'lemma', 'heb', 'שֶׁבֶר', '["sheber"]', '["grain (as if broken into kernels) corn, victuals."]', '["n-m"]', 'grain (as if broken into kernels) corn, victuals.', 'the same as 7667;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7669}/[H7669]', 'lemma', 'heb', 'שֶׁבֶר', '["Sheber"]', '["Sheber, an Israelite Sheber."]', '["n-pr-m"]', 'Sheber, an Israelite Sheber.', 'the same as 7667;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7670}/[H7670]', 'lemma', 'heb', 'שִׁבְרוֹן', '["shibrôwn"]', '["rupture, i.e. a pang; figuratively, ruin breaking, destruction."]', '["n-m"]', 'rupture, i.e. a pang; figuratively, ruin breaking, destruction.', 'from 7665;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7671}/[H7671]', 'lemma', 'heb', 'שְׁבָרִים', '["Shᵉbârîym"]', '["Shebarim, a place in Palestine Shebarim."]', '["n-pr-loc"]', 'Shebarim, a place in Palestine Shebarim.', 'plural of 7667; ruins;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7672}/[H7672]', 'lemma', 'arc', 'שְׁבַשׁ', '["shᵉbash"]', '["to entangle, i.e. perplex be astonished."]', '["v"]', 'to entangle, i.e. perplex be astonished.', '(Aramaic) corresponding to 7660;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7673]', 'root', 'heb', 'שָׁבַת', '["shâbath"]', '["to repose, i.e. desist from exertion; used in many implied relations (causative, figurative or specific) (cause to, let, make to) cease, celebrate, cause (make) to fail, keep (sabbath), suffer to be lacking, leave, put away (down), (make to) rest, rid, still, take away."]', '["v"]', 'to repose, i.e. desist from exertion; used in many implied relations (causative, figurative or specific) (cause to, let, make to) cease, celebrate, cause (make) to fail, keep (sabbath), suffer to be lacking, leave, put away (down), (make to) rest, rid, still, take away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7674}/[H7674]', 'lemma', 'heb', 'שֶׁבֶת', '["shebeth"]', '["rest, interruption, cessation cease, sit still, loss of time."]', '["n-f"]', 'rest, interruption, cessation cease, sit still, loss of time.', 'from 7673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7675}/[H7675]', 'lemma', 'heb', 'שֶׁבֶת', '["shebeth"]', '["properly, session; but used also concretely, an abode or locality place, seat. Compare 3429."]', '["n-f"]', 'properly, session; but used also concretely, an abode or locality place, seat. Compare 3429.', 'infinitive of 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7676}/[H7676]', 'lemma', 'heb', 'שַׁבָּת', '["shabbâth"]', '["intermission, i.e (specifically) the Sabbath ( every) sabbath."]', '["n"]', 'intermission, i.e (specifically) the Sabbath ( every) sabbath.', 'intensive from 7673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7677}/[H7677]', 'lemma', 'heb', 'שַׁבָּתוֹן', '["shabbâthôwn"]', '["a sabbatism or special holiday rest, sabbath."]', '["n-m"]', 'a sabbatism or special holiday rest, sabbath.', 'from 7676;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7678}/[H7678]', 'lemma', 'heb', 'שַׁבְּתַי', '["Shabbᵉthay"]', '["Shabbethai, the name of three Israelites Shabbethai."]', '["n-pr-m"]', 'Shabbethai, the name of three Israelites Shabbethai.', 'from 7676; restful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7679]', 'root', 'heb', 'שָׂגָא', '["sâgâʼ"]', '["to grow, i.e. (causatively) to enlarge, (figuratively) laud increase, magnify."]', '["v"]', 'to grow, i.e. (causatively) to enlarge, (figuratively) laud increase, magnify.', '; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7680}/[H7680]', 'lemma', 'arc', 'שְׂגָא', '["sᵉgâʼ"]', '["to increase grow, be multiplied."]', '["v"]', 'to increase grow, be multiplied.', '(Aramaic) corresponding to 7679;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7681}/[H7681]', 'lemma', 'heb', 'שָׁגֶא', '["Shâgeʼ"]', '["Shage, an Israelite Shage."]', '["n-pr-m"]', 'Shage, an Israelite Shage.', 'probably from 7686; erring;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7682]', 'root', 'heb', 'שָׂגַב', '["sâgab"]', '["to be (causatively, make) lofty, especially inaccessible; by implication, safe, strong; used literally and figuratively defend, exalt, be excellent, (be, set on) high, lofty, be safe, set up (on high), be too strong."]', '["v"]', 'to be (causatively, make) lofty, especially inaccessible; by implication, safe, strong; used literally and figuratively defend, exalt, be excellent, (be, set on) high, lofty, be safe, set up (on high), be too strong.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7683]', 'root', 'heb', 'שָׁגַג', '["shâgag"]', '["to stray, i.e. (figuratively) sin (with more or less apology) × also for that, deceived, err, go astray, sin ignorantly."]', '["v"]', 'to stray, i.e. (figuratively) sin (with more or less apology) × also for that, deceived, err, go astray, sin ignorantly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7684}/[H7684]', 'lemma', 'heb', 'שְׁגָגָה', '["shᵉgâgâh"]', '["a mistake or inadvertent transgression error, ignorance, at unawares; unwittingly."]', '["n-f"]', 'a mistake or inadvertent transgression error, ignorance, at unawares; unwittingly.', 'from 7683;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7685]', 'root', 'heb', 'שָׂגָה', '["sâgâh"]', '["to enlarge (especially upward, also figuratively) grow (up), increase."]', '["v"]', 'to enlarge (especially upward, also figuratively) grow (up), increase.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7686]', 'root', 'heb', 'שָׁגָה', '["shâgâh"]', '["to stray (causatively, mislead), usually (figuratively) to mistake, especially (morally) to transgress; by extension (through the idea of intoxication) to reel, (figuratively) be enraptured (cause to) go astray, deceive, err, be ravished, sin through ignorance, (let, make to) wander."]', '["v"]', 'to stray (causatively, mislead), usually (figuratively) to mistake, especially (morally) to transgress; by extension (through the idea of intoxication) to reel, (figuratively) be enraptured (cause to) go astray, deceive, err, be ravished, sin through ignorance, (let, make to) wander.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7687}/[H7687]', 'lemma', 'heb', 'שְׂגוּב', '["Sᵉgûwb"]', '["Segub, the name of two Israelites Segub."]', '["n-pr-m"]', 'Segub, the name of two Israelites Segub.', 'from 7682; aloft;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7688]', 'root', 'heb', 'שָׁגַח', '["shâgach"]', '["to peep, i.e. glance sharply at look (narrowly)."]', '["v"]', 'to peep, i.e. glance sharply at look (narrowly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7689}/[H7689]', 'lemma', 'heb', 'שַׂגִּיא', '["saggîyʼ"]', '["(superlatively) mighty excellent, great."]', '["a"]', '(superlatively) mighty excellent, great.', 'from 7679;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7690}/[H7690]', 'lemma', 'arc', 'שַׂגִּיא', '["saggîyʼ"]', '["large (in size, quantity or number, also adverbial) exceeding, great(-ly); many, much, sore, very."]', '["a"]', 'large (in size, quantity or number, also adverbial) exceeding, great(-ly); many, much, sore, very.', '(Aramaic) corresponding to 7689;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7691}/[H7691]', 'lemma', 'heb', 'שְׁגִיאָה', '["shᵉgîyʼâh"]', '["a moral mistake error."]', '["n-f"]', 'a moral mistake error.', 'from 7686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7692}/[H7692]', 'lemma', 'heb', 'שִׁגָּיוֹן', '["shiggâyôwn"]', '["properly, aberration, i.e. (technically) a dithyramb or rambling poem Shiggaion, Shigionoth."]', '["n-pr-m"]', 'properly, aberration, i.e. (technically) a dithyramb or rambling poem Shiggaion, Shigionoth.', 'or שִׁגָּיֹנָה; from 7686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7693]', 'root', 'heb', 'שָׁגַל', '["shâgal"]', '["to copulate with lie with, ravish."]', '["v"]', 'to copulate with lie with, ravish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7694}/[H7694]', 'lemma', 'heb', 'שֵׁגָל', '["shêgâl"]', '["a queen (from cohabitation) queen."]', '["n-f"]', 'a queen (from cohabitation) queen.', 'from 7693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7695}/[H7695]', 'lemma', 'arc', 'שֵׁגָל', '["shêgâl"]', '["a (legitimate) queen wife."]', '["n-f"]', 'a (legitimate) queen wife.', '(Aramaic) corresponding to 7694;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7696]', 'root', 'heb', 'שָׁגַע', '["shâgaʻ"]', '["to rave through insanity (be, play the) mad (man)."]', '["v"]', 'to rave through insanity (be, play the) mad (man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7697}/[H7697]', 'lemma', 'heb', 'שִׁגָּעוֹן', '["shiggâʻôwn"]', '["craziness furiously, madness."]', '["n-m"]', 'craziness furiously, madness.', 'from 7696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7699}/[H7699]', 'lemma', 'heb', 'שַׁד', '["shad"]', '["the breast of a woman or animal (as bulging) breast, pap, teat."]', '["n-m"]', 'the breast of a woman or animal (as bulging) breast, pap, teat.', 'or שֹׁד; probably from 7736 (in its original sense) contracted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7700}/[H7700]', 'lemma', 'heb', 'שֵׁד', '["shêd"]', '["a dæmon (as malignant) devil."]', '["n-m"]', 'a dæmon (as malignant) devil.', 'from 7736;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7701}/[H7701]', 'lemma', 'heb', 'שֹׁד', '["shôd"]', '["violence, ravage desolation, destruction, oppression, robbery, spoil(-ed, -er, -ing), wasting."]', '["n-m"]', 'violence, ravage desolation, destruction, oppression, robbery, spoil(-ed, -er, -ing), wasting.', 'or שׁוֹד; (Job 5:21), from 7736;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7702]', 'root', 'heb', 'שָׂדַד', '["sâdad"]', '["to abrade, i.e. harrow a field break clods, harrow."]', '["v"]', 'to abrade, i.e. harrow a field break clods, harrow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7703]', 'root', 'heb', 'שָׁדַד', '["shâdad"]', '["properly, to be burly, i.e. (figuratively) powerful (passively, impregnable); by implication, to ravage dead, destroy(-er), oppress, robber, spoil(-er), × utterly, (lay) waste."]', '["v"]', 'properly, to be burly, i.e. (figuratively) powerful (passively, impregnable); by implication, to ravage dead, destroy(-er), oppress, robber, spoil(-er), × utterly, (lay) waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7704>', 'opaque', 'heb', 'שָׂדֶה', '["sâdeh"]', '["a field (as flat) country, field, ground, land, soil, × wild."]', '["n-m"]', 'a field (as flat) country, field, ground, land, soil, × wild.', 'or שָׂדַי; from an unused root meaning to spread out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7705}/[H7705]', 'lemma', 'heb', 'שִׁדָּה', '["shiddâh"]', '["a wife (as mistress of the house) × all sorts, musical instrument."]', '["n-f"]', 'a wife (as mistress of the house) × all sorts, musical instrument.', 'from 7703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7706}/[H7706]', 'lemma', 'heb', 'שַׁדַּי', '["Shadday"]', '["the Almighty Almighty."]', '["n-m"]', 'the Almighty Almighty.', 'from 7703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7707}/[H7707]', 'lemma', 'heb', 'שְׁדֵיאוּר', '["Shᵉdêyʼûwr"]', '["Shedejur, an Israelite Shedeur."]', '["n-pr-m"]', 'Shedejur, an Israelite Shedeur.', 'from the same as 7704 and 217; spreader of light;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7708}/[H7708]', 'lemma', 'heb', 'שִׂדִּים', '["Siddîym"]', '["Siddim, a valley in Palestine Siddim."]', '["n-pr-loc"]', 'Siddim, a valley in Palestine Siddim.', 'plural from the same as 7704; flats;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7709}/[H7709]', 'lemma', 'heb', 'שְׁדֵמָה', '["shᵉdêmâh"]', '["a cultivated field blasted, field."]', '["n-f"]', 'a cultivated field blasted, field.', 'apparently from 7704;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7710]', 'root', 'heb', 'שָׁדַף', '["shâdaph"]', '["to scorch blast."]', '["v"]', 'to scorch blast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7711}/[H7711]', 'lemma', 'heb', 'שְׁדֵפָה', '["shᵉdêphâh"]', '["blight blasted(-ing)."]', '["n-f n-m"]', 'blight blasted(-ing).', 'or שִׁדָּפוֹן; from 7710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7712]', 'root', 'arc', 'שְׁדַר', '["shᵉdar"]', '["to endeavor labour."]', '["v"]', 'to endeavor labour.', '(Aramaic) a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7713>', 'opaque', 'heb', 'שְׂדֵרָה', '["sᵉdêrâh"]', '["a row, i.e. rank (of soldiers), story (of rooms) board, range."]', '["n-f"]', 'a row, i.e. rank (of soldiers), story (of rooms) board, range.', 'from an unused root meaning to regulate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7715}/[H7715]', 'lemma', 'arc', 'שַׁדְרַךְ', '["Shadrak"]', '["Shadrach."]', '["n-pr-m"]', 'Shadrach.', '(Aramaic) the same as 7714');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7716}/[H7716]', 'lemma', 'heb', 'שֶׂה', '["seh"]', '["a member of a flock, i.e. a sheep or goat (lesser, small) cattle, ewe, goat, lamb, sheep. Compare 2089."]', '["n-m"]', 'a member of a flock, i.e. a sheep or goat (lesser, small) cattle, ewe, goat, lamb, sheep. Compare 2089.', 'or שֵׂי; probably from 7582 through the idea of pushing out to graze;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7717>', 'opaque', 'heb', 'שָׂהֵד', '["sâhêd"]', '["a witness record."]', '["n-m"]', 'a witness record.', 'from an unused root meaning to testify;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7719}/[H7719]', 'lemma', 'heb', 'שֹׁהַם', '["Shôham"]', '["Shoham, an Israelite Shoham."]', '["n-pr-m"]', 'Shoham, an Israelite Shoham.', 'the same as 7718;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7720}/[H7720]', 'lemma', 'heb', 'שַׂהֲרֹן', '["sahărôn"]', '["a round pendant for the neck ornament, round tire like the moon."]', '["n-m"]', 'a round pendant for the neck ornament, round tire like the moon.', 'from the same as 5469;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7721>', 'opaque', 'heb', 'שׂוֹא', '["sôwʼ"]', '["a rising arise."]', '["v"]', 'a rising arise.', 'from an unused root (akin to 5375 and 7722) meaning to rise;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7722>', 'opaque', 'heb', 'שׁוֹא', '["shôwʼ"]', '["a tempest; by implication, devastation desolate(-ion), destroy, destruction, storm, wasteness."]', '["n-m n-f"]', 'a tempest; by implication, devastation desolate(-ion), destroy, destruction, storm, wasteness.', 'or (feminine) שׁוֹאָה; or שֹׁאָה; from an unused root meaning to rush over;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7723}/[H7723]', 'lemma', 'heb', 'שָׁוְא', '["shâvᵉʼ"]', '["evil (as destructive), literally (ruin) or morally (especially guile); figuratively idolatry (as false, subjective), uselessness (as deceptive, objective; also adverbially, in vain) false(-ly), lie, lying, vain, vanity."]', '["n-m"]', 'evil (as destructive), literally (ruin) or morally (especially guile); figuratively idolatry (as false, subjective), uselessness (as deceptive, objective; also adverbially, in vain) false(-ly), lie, lying, vain, vanity.', 'or שַׁו; from the same as 7722 in the sense of desolating;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7724}/[H7724]', 'lemma', 'heb', 'שְׁוָא', '["Shᵉvâʼ"]', '["Sheva, an Israelite Sheva."]', '["n-pr-m"]', 'Sheva, an Israelite Sheva.', 'from the same as 7723; false;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7725]', 'root', 'heb', 'שׁוּב', '["shûwb"]', '["to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw."]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7726}/[H7726]', 'lemma', 'heb', 'שׁוֹבָב', '["shôwbâb"]', '["apostate, i.e. idolatrous backsliding, frowardly, turn away (from margin)."]', '["a"]', 'apostate, i.e. idolatrous backsliding, frowardly, turn away (from margin).', 'from 7725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7727}/[H7727]', 'lemma', 'heb', 'שׁוֹבָב', '["Shôwbâb"]', '["Shobab, the name of two Israelites Shobab."]', '["n-pr-m"]', 'Shobab, the name of two Israelites Shobab.', 'the same as 7726; rebellious;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7728}/[H7728]', 'lemma', 'heb', 'שׁוֹבֵב', '["shôwbêb"]', '["apostate, i.e. heathenish or (actually) heathen backsliding."]', '["a"]', 'apostate, i.e. heathenish or (actually) heathen backsliding.', 'from 7725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7729}/[H7729]', 'lemma', 'heb', 'שׁוּבָה', '["shûwbâh"]', '["a return returning."]', '["n-f"]', 'a return returning.', 'from 7725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7730}/[H7730]', 'lemma', 'heb', 'שׂוֹבֶךְ', '["sôwbek"]', '["a thicket, i.e. interlaced branches thick boughs."]', '["n-m"]', 'a thicket, i.e. interlaced branches thick boughs.', 'for 5441;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7731}/[H7731]', 'lemma', 'heb', 'שׁוֹבָךְ', '["Shôwbâk"]', '["Shobak, a Syrian Shobach."]', '["n-pr-m"]', 'Shobak, a Syrian Shobach.', 'perhaps for 7730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7732}/[H7732]', 'lemma', 'heb', 'שׁוֹבָל', '["Shôwbâl"]', '["Shobal, the name of an Edomite and two Israelites Shobal."]', '["n-pr-m"]', 'Shobal, the name of an Edomite and two Israelites Shobal.', 'from the same as 7640; overflowing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7733]', 'root', 'heb', 'שׁוֹבֵק', '["Shôwbêq"]', '["Shobek, an Israelite Shobek."]', '["n-pr-m"]', 'Shobek, an Israelite Shobek.', 'active participle from a primitive root meaning to leave (compare 7662); forsaking;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7734]', 'root', 'heb', 'שׂוּג', '["sûwg"]', '["to retreat turn back."]', '["v"]', 'to retreat turn back.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7735]', 'root', 'heb', 'שׂוּג', '["sûwg"]', '["to hedge in make to grow."]', '["v"]', 'to hedge in make to grow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7736]', 'root', 'heb', 'שׁוּד', '["shûwd"]', '["properly, to swell up, i.e. figuratively (by implication of insolence) to devastate waste."]', '["v"]', 'properly, to swell up, i.e. figuratively (by implication of insolence) to devastate waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7737]', 'root', 'heb', 'שָׁוָה', '["shâvâh"]', '["properly, to level, i.e. equalize; figuratively, to resemble; by implication, to adjust (i.e. counterbalance, be suitable, compose, place, yield, etc.) avail, behave, bring forth, compare, countervail, (be, make) equal, lay, be (make, a-) like, make plain, profit, reckon."]', '["v"]', 'properly, to level, i.e. equalize; figuratively, to resemble; by implication, to adjust (i.e. counterbalance, be suitable, compose, place, yield, etc.) avail, behave, bring forth, compare, countervail, (be, make) equal, lay, be (make, a-) like, make plain, profit, reckon.', 'a primitive root;');
