INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7788]', 'root', 'heb', 'שׁוּר', '["shûwr"]', '["properly, to turn, i.e. travel about (as a harlot or a merchant) go, singular See also 7891."]', '["v"]', 'properly, to turn, i.e. travel about (as a harlot or a merchant) go, singular See also 7891.', 'a primitive root;');
