INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7794}/[H7794]', 'lemma', 'heb', 'שׁוֹר', '["shôwr"]', '["a bullock (as a traveller) bull(-ock), cow, ox, wall (by mistake for 7791)."]', '["n-m"]', 'a bullock (as a traveller) bull(-ock), cow, ox, wall (by mistake for 7791).', 'from 7788;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7795}/[H7795]', 'lemma', 'heb', 'שׂוֹרָה', '["sôwrâh"]', '["properly, a ring, i.e. (by analogy) a row (adverbially) principal."]', '["n-f"]', 'properly, a ring, i.e. (by analogy) a row (adverbially) principal.', 'from 7786 in the primitive sense of 5493;');
