INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7797]', 'root', 'heb', 'שׂוּשׂ', '["sûws"]', '["to be bright, i.e. cheerful be glad, × greatly, joy, make mirth, rejoice."]', '["v"]', 'to be bright, i.e. cheerful be glad, × greatly, joy, make mirth, rejoice.', 'or שִׂישׂ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7798}/[H7798]', 'lemma', 'heb', 'שַׁוְשָׁא', '["Shavshâʼ"]', '["Shavsha, an Israelite Shavsha."]', '["n-pr-m"]', 'Shavsha, an Israelite Shavsha.', 'from 7797; joyful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7799}/[H7799]', 'lemma', 'heb', 'שׁוּשַׁן', '["shûwshan"]', '["a lily (from its whiteness), as a flower of architectural ornament; also a (straight) trumpet (from the tubular shape) lily, Shoshannim."]', '["n-m"]', 'a lily (from its whiteness), as a flower of architectural ornament; also a (straight) trumpet (from the tubular shape) lily, Shoshannim.', 'or שׁוֹשָׁן; or שֹׁשָׁן; and (feminine) שׁוֹשַׁנָּה; from 7797;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7800}/[H7800]', 'lemma', 'heb', 'שׁוּשַׁן', '["Shûwshan"]', '["Shushan, a place in Persia Shushan."]', '["n-pr-loc"]', 'Shushan, a place in Persia Shushan.', 'the same as 7799;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7801>', 'opaque', 'heb', 'שׁוּשַׁנְכִי', '["Shûwshankîy"]', '["a Shushankite (collectively) or inhabitants of some unknown place in Assyrian Susanchites."]', '["n-pr"]', 'a Shushankite (collectively) or inhabitants of some unknown place in Assyrian Susanchites.', '(Aramaic) of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7802}/[H7802]', 'lemma', 'heb', 'שׁוּשַׁן עֵדוּת', '["Shûwshan ʻÊdûwth"]', '["Shushan-Eduth or Shoshannim-Eduth, the title of a popular song Shoshannim-Eduth, Shushan-eduth."]', '["n-m"]', 'Shushan-Eduth or Shoshannim-Eduth, the title of a popular song Shoshannim-Eduth, Shushan-eduth.', 'or (plural of former) שׁוֹשַׁנִּים עֵדוּתlemma שׁוֹשַׁנִּיס עֵדוּת samekh, corrected to שׁוֹשַׁנִּים עֵדוּת; from 7799 and 5715; lily (or trumpet) of assemblage;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7803}/[H7803]', 'lemma', 'heb', 'שׁוּתֶלַח', '["Shûwthelach"]', '["Shuthelach, the name of two Israelites Shuthelah."]', '["n-pr-m"]', 'Shuthelach, the name of two Israelites Shuthelah.', 'probably from 7582 and the same as 8520; crash of breakage;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7804}/[H7804]', 'lemma', 'arc', 'שְׁזַב', '["shᵉzab"]', '["to leave, i.e. (causatively) free deliver."]', '["v"]', 'to leave, i.e. (causatively) free deliver.', '(Aramaic) corresponding to 5800;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7805]', 'root', 'heb', 'שָׁזַף', '["shâzaph"]', '["to tan (by sunburning); figuratively (as if by a piercing ray) to scan look up, see."]', '["v"]', 'to tan (by sunburning); figuratively (as if by a piercing ray) to scan look up, see.', 'a primitive root;');
