INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7807}/[H7807]', 'lemma', 'heb', 'שַׁח', '["shach"]', '["sunk, i.e. downcast humble."]', '["a"]', 'sunk, i.e. downcast humble.', 'from 7817;');
