INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7811]', 'root', 'heb', 'שָׂחָה', '["sâchâh"]', '["to swim; causatively, to inundate (make to) swim."]', '["v"]', 'to swim; causatively, to inundate (make to) swim.', 'a primitive root;');
