INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7817]', 'root', 'heb', 'שָׁחַח', '["shâchach"]', '["to sink or depress (reflexive or causative) bend, bow (down), bring (cast) down, couch, humble self, be (bring) low, stoop."]', '["v"]', 'to sink or depress (reflexive or causative) bend, bow (down), bring (cast) down, couch, humble self, be (bring) low, stoop.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7818]', 'root', 'heb', 'שָׂחַט', '["sâchaṭ"]', '["to tread out, i.e. squeeze (grapes) press."]', '["v"]', 'to tread out, i.e. squeeze (grapes) press.', 'a primitive root;');
