INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7833]', 'root', 'heb', 'שָׁחַק', '["shâchaq"]', '["to comminate (by trituration or attrition) beat, wear."]', '["v"]', 'to comminate (by trituration or attrition) beat, wear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7834}/[H7834]', 'lemma', 'heb', 'שַׁחַק', '["shachaq"]', '["a powder (as beaten small); by analogy, a thin vapor; by extension, the firmament cloud, small dust, heaven, sky."]', '["n-m"]', 'a powder (as beaten small); by analogy, a thin vapor; by extension, the firmament cloud, small dust, heaven, sky.', 'from 7833;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7835]', 'root', 'heb', 'שָׁחַר', '["shâchar"]', '["to be dim or dark (in color) be black."]', '["v"]', 'to be dim or dark (in color) be black.', 'a primitive root (identical with 7836 through the idea of the duskiness of early dawn);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7836]', 'root', 'heb', 'שָׁחַר', '["shâchar"]', '["properly, to dawn, i.e. (figuratively) be (up) early at any task (with the implication of earnestness); by extension, to search for (with painstaking) (do something) betimes, enquire early, rise (seek) betimes, seek diligently) early, in the morning)."]', '["v"]', 'properly, to dawn, i.e. (figuratively) be (up) early at any task (with the implication of earnestness); by extension, to search for (with painstaking) (do something) betimes, enquire early, rise (seek) betimes, seek diligently) early, in the morning).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7837}/[H7837]', 'lemma', 'heb', 'שַׁחַר', '["shachar"]', '["dawn (literal, figurative or adverbial) day(-spring), early, light, morning, whence riseth."]', '["n-m"]', 'dawn (literal, figurative or adverbial) day(-spring), early, light, morning, whence riseth.', 'from 7836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7838}/[H7838]', 'lemma', 'heb', 'שָׁחֹר', '["shâchôr"]', '["properly, dusky, but also (absol.) jetty black."]', '["a"]', 'properly, dusky, but also (absol.) jetty black.', 'or שָׁחוֹר; from 7835;');
