INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7840}/[H7840]', 'lemma', 'heb', 'שְׁחַרְחֹרֶת', '["shᵉcharchôreth"]', '["swarthy black."]', '["a"]', 'swarthy black.', 'from 7835;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7841}/[H7841]', 'lemma', 'heb', 'שְׁחַרְיָה', '["Shᵉcharyâh"]', '["Shecharjah, an Israelite Shehariah."]', '["n-pr-m"]', 'Shecharjah, an Israelite Shehariah.', 'from 7836 and 3050; Jah has sought;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7842}/[H7842]', 'lemma', 'heb', 'שַׁחֲרַיִם', '["Shachărayim"]', '["Shacharajim, an Israelite Shaharaim."]', '["n-pr-m"]', 'Shacharajim, an Israelite Shaharaim.', 'dual of 7837; double dawn;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7843]', 'root', 'heb', 'שָׁחַת', '["shâchath"]', '["to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r)."]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
