INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7904]', 'root', 'heb', 'שָׁכָה', '["shâkâh"]', '["to roam (through lust) in the morning (by mistake for 7925)."]', '["v"]', 'to roam (through lust) in the morning (by mistake for 7925).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7905}/[H7905]', 'lemma', 'heb', 'שֻׂכָּה', '["sukkâh"]', '["a dart (as pointed like a thorn) barbed iron."]', '["n-f"]', 'a dart (as pointed like a thorn) barbed iron.', 'feminine of 7900 in the sense of 7899;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7906>', 'opaque', 'heb', 'שֵׂכוּ', '["Sêkûw"]', '["Seku, a place in Palestine Sechu."]', '["n-pr-loc"]', 'Seku, a place in Palestine Sechu.', 'from an unused root apparently meaning to surmount; an observatory (with the article);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7907}/[H7907]', 'lemma', 'heb', 'שֶׂכְוִי', '["sekvîy"]', '["observant, i.e. (concretely) the mind heart."]', '["n-m"]', 'observant, i.e. (concretely) the mind heart.', 'from the same as 7906;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7908}/[H7908]', 'lemma', 'heb', 'שְׁכוֹל', '["shᵉkôwl"]', '["bereavement loss of children, spoiling."]', '["n-m"]', 'bereavement loss of children, spoiling.', 'infinitive of 7921;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7909}/[H7909]', 'lemma', 'heb', 'שַׁכּוּל', '["shakkûwl"]', '["bereaved barren, bereaved (robbed) of children (whelps)."]', '["a"]', 'bereaved barren, bereaved (robbed) of children (whelps).', 'or שַׁכֻּל; from 7921;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7910}/[H7910]', 'lemma', 'heb', 'שִׁכּוֹר', '["shikkôwr"]', '["intoxicated, as a state or a habit drunk(-ard, -en, -en man)."]', '["a"]', 'intoxicated, as a state or a habit drunk(-ard, -en, -en man).', 'or שִׁכֹּר; from 7937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7911]', 'root', 'heb', 'שָׁכַח', '["shâkach"]', '["to mislay, i.e. to be oblivious of, from want of memory or attention × at all, (cause to) forget."]', '["v"]', 'to mislay, i.e. to be oblivious of, from want of memory or attention × at all, (cause to) forget.', 'or שָׁכֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7912}/[H7912]', 'lemma', 'arc', 'שְׁכַח', '["shᵉkach"]', '["to discover (literally or figuratively) find."]', '["v"]', 'to discover (literally or figuratively) find.', '(Aramaic) corresponding to 7911 through the idea of disclosure of a covered or forgotten thing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7913}/[H7913]', 'lemma', 'heb', 'שָׁכֵחַ', '["shâkêach"]', '["oblivious forget."]', '["a"]', 'oblivious forget.', 'from 7911;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7914}/[H7914]', 'lemma', 'heb', 'שְׂכִיָּה', '["sᵉkîyâh"]', '["a conspicuous object picture."]', '["n-f"]', 'a conspicuous object picture.', 'feminine from the same as 7906;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7915}/[H7915]', 'lemma', 'heb', 'שַׂכִּין', '["sakkîyn"]', '["a knife (as pointed or edged) knife."]', '["n-m"]', 'a knife (as pointed or edged) knife.', 'intensive perhaps from the same as 7906 in the sense of 7753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7916}/[H7916]', 'lemma', 'heb', 'שָׂכִיר', '["sâkîyr"]', '["a man at wages by the day or year hired (man, servant), hireling."]', '["a"]', 'a man at wages by the day or year hired (man, servant), hireling.', 'from 7936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7917}/[H7917]', 'lemma', 'heb', 'שְׂכִירָה', '["sᵉkîyrâh"]', '["a hiring that is hired."]', '["a"]', 'a hiring that is hired.', 'feminine of 7916;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7918]', 'root', 'heb', 'שָׁכַךְ', '["shâkak"]', '["to weave (i.e. lay) a trap; figuratively, (through the idea of secreting) to allay (passions; physically, abate a flood) appease, assuage, make to cease, pacify, set."]', '["v"]', 'to weave (i.e. lay) a trap; figuratively, (through the idea of secreting) to allay (passions; physically, abate a flood) appease, assuage, make to cease, pacify, set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7919]', 'root', 'heb', 'שָׂכַל', '["sâkal"]', '["to be (causatively, make or act) circumspect and hence, intelligent consider, expert, instruct, prosper, (deal) prudent(-ly), (give) skill(-ful), have good success, teach, (have, make to) understand(-ing), wisdom, (be, behave self, consider, make) wise(-ly), guide wittingly."]', '["v"]', 'to be (causatively, make or act) circumspect and hence, intelligent consider, expert, instruct, prosper, (deal) prudent(-ly), (give) skill(-ful), have good success, teach, (have, make to) understand(-ing), wisdom, (be, behave self, consider, make) wise(-ly), guide wittingly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7920}/[H7920]', 'lemma', 'arc', 'שְׂכַל', '["sᵉkal"]', '["consider."]', '["v"]', 'consider.', '(Aramaic) corresponding to 7919');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7921]', 'root', 'heb', 'שָׁכֹל', '["shâkôl"]', '["properly, to miscarry, i.e. suffer abortion; by analogy, to bereave (literally or figuratively) bereave (of children), barren, cast calf (fruit, young), be (make) childless, deprive, destroy, × expect, lose children, miscarry, rob of children, spoil."]', '["v"]', 'properly, to miscarry, i.e. suffer abortion; by analogy, to bereave (literally or figuratively) bereave (of children), barren, cast calf (fruit, young), be (make) childless, deprive, destroy, × expect, lose children, miscarry, rob of children, spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7922}/[H7922]', 'lemma', 'heb', 'שֶׂכֶל', '["sekel"]', '["intelligence; by implication, success discretion, knowledge, policy, prudence, sense, understanding, wisdom, wise."]', '["n-m"]', 'intelligence; by implication, success discretion, knowledge, policy, prudence, sense, understanding, wisdom, wise.', 'or שֵׂכֶל; from 7919;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7923}/[H7923]', 'lemma', 'heb', 'שִׁכֻּלִים', '["shikkulîym"]', '["childlessness (by continued bereavements) to have after loss of others."]', '["n-m"]', 'childlessness (by continued bereavements) to have after loss of others.', 'plural from 7921;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7924}/[H7924]', 'lemma', 'arc', 'שׇׂכְלְתָנוּ', '["soklᵉthânûw"]', '["intelligence understanding."]', '["n-f"]', 'intelligence understanding.', '(Aramaic) from 7920;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7925]', 'root', 'heb', 'שָׁכַם', '["shâkam"]', '["literally, to load up (on the back of man or beast), i.e. to start early in the morning (arise, be up, get (oneself) up, rise up) early (betimes), morning."]', '["v"]', 'literally, to load up (on the back of man or beast), i.e. to start early in the morning (arise, be up, get (oneself) up, rise up) early (betimes), morning.', 'a primitive root; properly, to incline (the shoulder to a burden); but used only as denominative from 7926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7926}/[H7926]', 'lemma', 'heb', 'שְׁכֶם', '["shᵉkem"]', '["the neck (between the shoulders) as the place of burdens; figuratively, the spur of a hill back, × consent, portion, shoulder."]', '["n-m"]', 'the neck (between the shoulders) as the place of burdens; figuratively, the spur of a hill back, × consent, portion, shoulder.', 'from 7925;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7927}/[H7927]', 'lemma', 'heb', 'שְׁכֶם', '["Shᵉkem"]', '["Shekem, a place in Palestine Shechem."]', '["n-pr-m n-pr-loc"]', 'Shekem, a place in Palestine Shechem.', 'the same as 7926; ridge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7928}/[H7928]', 'lemma', 'heb', 'שֶׁכֶם', '["Shekem"]', '["Shekem, the name of a Hivite and two Israelites Shechem."]', '["n-pr-m"]', 'Shekem, the name of a Hivite and two Israelites Shechem.', 'for 7926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7929}/[H7929]', 'lemma', 'heb', 'שִׁכְמָה', '["shikmâh"]', '["the shoulderbone shoulder blade."]', '["n-f"]', 'the shoulderbone shoulder blade.', 'feminine of 7926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7930}/[H7930]', 'lemma', 'heb', 'שִׁכְמִי', '["Shikmîy"]', '["a Shikmite (collectively), or descendants of Shekem Shichemites."]', '["a"]', 'a Shikmite (collectively), or descendants of Shekem Shichemites.', 'patronymic from 7928;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7931]', 'root', 'heb', 'שָׁכַן', '["shâkan"]', '["to reside or permanently stay (literally or figuratively) abide, continue, (cause to, make to) dwell(-er), have habitation, inhabit, lay, place, (cause to) remain, rest, set (up)."]', '["v"]', 'to reside or permanently stay (literally or figuratively) abide, continue, (cause to, make to) dwell(-er), have habitation, inhabit, lay, place, (cause to) remain, rest, set (up).', 'a primitive root (apparently akin (by transmission) to 7901 through the idea of lodging; compare 5531, 7925);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7932}/[H7932]', 'lemma', 'arc', 'שְׁכַן', '["shᵉkan"]', '["cause to dwell, have habitation."]', '["v"]', 'cause to dwell, have habitation.', '(Aramaic) corresponding to 7931');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7933}/[H7933]', 'lemma', 'heb', 'שֶׁכֶן', '["sheken"]', '["a residence habitation."]', '["n-m"]', 'a residence habitation.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7934}/[H7934]', 'lemma', 'heb', 'שָׁכֵן', '["shâkên"]', '["a resident; by extension, a fellow-citizen inhabitant, neighbour, nigh."]', '["a"]', 'a resident; by extension, a fellow-citizen inhabitant, neighbour, nigh.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7935}/[H7935]', 'lemma', 'heb', 'שְׁכַנְיָה', '["Shᵉkanyâh"]', '["Shekanjah, the name of nine Israelites Shecaniah, Shechaniah."]', '["n-pr-m"]', 'Shekanjah, the name of nine Israelites Shecaniah, Shechaniah.', 'or (prolonged) שְׁכַנְיָהוּ; from 7931 and 3050; Jah has dwelt;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7936]', 'root', 'heb', 'שָׂכַר', '["sâkar"]', '["to hire earn wages, hire (out self), reward, × surely."]', '["v"]', 'to hire earn wages, hire (out self), reward, × surely.', 'or (by permutation) סָכַר; (Ezra 4:5), a primitive root (apparently akin (by prosthesis) to 3739 through the idea of temporary purchase; compare 7937);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7937]', 'root', 'heb', 'שָׁכַר', '["shâkar"]', '["to become tipsy; in a qualified sense, to satiate with a stimulating drink or (figuratively) influence (be filled with) drink (abundantly), (be, make) drunk(-en), be merry. (Superlative of 8248.)"]', '["v"]', 'to become tipsy; in a qualified sense, to satiate with a stimulating drink or (figuratively) influence (be filled with) drink (abundantly), (be, make) drunk(-en), be merry. (Superlative of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7938}/[H7938]', 'lemma', 'heb', 'שֶׂכֶר', '["seker"]', '["wages reward, sluices."]', '["n-m"]', 'wages reward, sluices.', 'from 7936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7939}/[H7939]', 'lemma', 'heb', 'שָׂכָר', '["sâkâr"]', '["payment of contract; concretely, salary, fare, maintenance; by implication, compensation, benefit hire, price, reward(-ed), wages, worth."]', '["n-m"]', 'payment of contract; concretely, salary, fare, maintenance; by implication, compensation, benefit hire, price, reward(-ed), wages, worth.', 'from 7936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7940}/[H7940]', 'lemma', 'heb', 'שָׂכָר', '["Sâkâr"]', '["Sakar, the name of two Israelites Sacar."]', '["n-pr-m"]', 'Sakar, the name of two Israelites Sacar.', 'the same as 7939; recompense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7941}/[H7941]', 'lemma', 'heb', 'שֵׁכָר', '["shêkâr"]', '["an intoxicant, i.e. intensely alcoholic liquor strong drink, drunkard, strong wine."]', '["n-m"]', 'an intoxicant, i.e. intensely alcoholic liquor strong drink, drunkard, strong wine.', 'from 7937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7942}/[H7942]', 'lemma', 'heb', 'שִׁכְּרוֹן', '["Shikkᵉrôwn"]', '["drunkenness, Shikkeron, a place in Palestine Shicron."]', '["n-pr-loc"]', 'drunkenness, Shikkeron, a place in Palestine Shicron.', 'for 7943;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7943}/[H7943]', 'lemma', 'heb', 'שִׁכָּרוֹן', '["shikkârôwn"]', '["intoxication (be) drunken(-ness)."]', '["n-m"]', 'intoxication (be) drunken(-ness).', 'from 7937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7944}/[H7944]', 'lemma', 'heb', 'שַׁל', '["shal"]', '["a fault error."]', '["n-m"]', 'a fault error.', 'from 7952 abbreviated form;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7945}/[H7945]', 'lemma', 'heb', 'שֶׁל', '["shel"]', '["on account of, whatsoever, whichsoever cause, sake."]', '["r"]', 'on account of, whatsoever, whichsoever cause, sake.', 'for the rel. 834; used with prepositional prefix, and often followed by some pronominal affix;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7946}/[H7946]', 'lemma', 'heb', 'שַׁלְאֲנָן', '["shalʼănân"]', '["tranquil being at ease."]', '["a"]', 'tranquil being at ease.', 'for 7600;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7947]', 'root', 'heb', 'שָׁלַב', '["shâlab"]', '["to space off; intensive (evenly) to make equi-distant equally distant, set in order."]', '["v"]', 'to space off; intensive (evenly) to make equi-distant equally distant, set in order.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7948}/[H7948]', 'lemma', 'heb', 'שָׁלָב', '["shâlâb"]', '["a spacer or raised interval, i.e. the stile in a frame or panel ledge."]', '["n-m"]', 'a spacer or raised interval, i.e. the stile in a frame or panel ledge.', 'from 7947;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7949]', 'root', 'heb', 'שָׁלַג', '["shâlag"]', '["to be snow-white (with the linen clothing of the slain) be as snow."]', '["v"]', 'to be snow-white (with the linen clothing of the slain) be as snow.', 'a primitive root; properly, meaning to be white; used only as denominative from 7950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7950}/[H7950]', 'lemma', 'heb', 'שֶׁלֶג', '["sheleg"]', '["snow (probably from its whiteness) snow(-y)."]', '["n-m"]', 'snow (probably from its whiteness) snow(-y).', 'from 7949;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7951]', 'root', 'heb', 'שָׁלָה', '["shâlâh"]', '["to be tranquil, i.e. secure or successful be happy, prosper, be in safety."]', '["v"]', 'to be tranquil, i.e. secure or successful be happy, prosper, be in safety.', 'or שָׁלַו; (Job 3:26), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7952]', 'root', 'heb', 'שָׁלָה', '["shâlâh"]', '["to mislead deceive, be negligent."]', '["v"]', 'to mislead deceive, be negligent.', 'a primitive root (probably identical with 7953 through the idea of educing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7953]', 'root', 'heb', 'שָׁלָה', '["shâlâh"]', '["to draw out or off, i.e. remove (the soul by death) take away."]', '["v"]', 'to draw out or off, i.e. remove (the soul by death) take away.', 'a primitive root (rather cognate (by contraction) to the base of 5394, 7997 and their congeners through the idea of extracting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7954}/[H7954]', 'lemma', 'arc', 'שְׁלָה', '["shᵉlâh"]', '["to be secure at rest."]', '["a"]', 'to be secure at rest.', '(Aramaic) corresponding to 7951;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7955}/[H7955]', 'lemma', 'arc', 'שָׁלָה', '["shâlâh"]', '["a wrong thing amiss."]', '["n-f"]', 'a wrong thing amiss.', '(Aramaic) from a root corresponding to 7952;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7956}/[H7956]', 'lemma', 'heb', 'שֵׁלָה', '["Shêlâh"]', '["Shelah, the name of a postdiluvian patriarch and of an Israelite Shelah."]', '["n-pr-m"]', 'Shelah, the name of a postdiluvian patriarch and of an Israelite Shelah.', 'the same as 7596 (shortened); request;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7957}/[H7957]', 'lemma', 'heb', 'שַׁלְהֶבֶת', '["shalhebeth"]', '["a flare of fire (flaming) flame."]', '["n-f"]', 'a flare of fire (flaming) flame.', 'from the same as 3851 with sibilant prefix;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7958}/[H7958]', 'lemma', 'heb', 'שְׂלָו', '["sᵉlâv"]', '["the quail collectively (as slow in flight from its weight) quails."]', '["n-f"]', 'the quail collectively (as slow in flight from its weight) quails.', 'or שְׂלָיו; by orthographical variation from 7951 through the idea of sluggishness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7959}/[H7959]', 'lemma', 'heb', 'שֶׁלֶו', '["shelev"]', '["security prosperity."]', '["n-m"]', 'security prosperity.', 'from 7951;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7960}/[H7960]', 'lemma', 'arc', 'שָׁלוּ', '["shâlûw"]', '["a fault error, × fail, thing amiss."]', '["n-f"]', 'a fault error, × fail, thing amiss.', '(Aramaic) or שָׁלוּת; (Aramaic), from the same as 7955;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7961}/[H7961]', 'lemma', 'heb', 'שָׁלֵו', '["shâlêv"]', '["tranquil; (in a bad sense) careless; abstractly, security (being) at ease, peaceable, (in) prosper(-ity), quiet(-ness), wealthy."]', '["a"]', 'tranquil; (in a bad sense) careless; abstractly, security (being) at ease, peaceable, (in) prosper(-ity), quiet(-ness), wealthy.', 'or שָׁלֵיו; feminine שְׁלֵוָה; from 7951;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7962}/[H7962]', 'lemma', 'heb', 'שַׁלְוָה', '["shalvâh"]', '["security (genuine or false) abundance, peace(-ably), prosperity, quietness."]', '["n-f"]', 'security (genuine or false) abundance, peace(-ably), prosperity, quietness.', 'from 7951;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7963}/[H7963]', 'lemma', 'arc', 'שְׁלֵוָה', '["shᵉlêvâh"]', '["safety tranquillity. See also 7961."]', '["n-f"]', 'safety tranquillity. See also 7961.', '(Aramaic) corresponding to 7962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7964}/[H7964]', 'lemma', 'heb', 'שִׁלּוּחַ', '["shillûwach"]', '["(only in plural) a dismissal, i.e. (of a wife) divorce (especially the document); also (of a daughter) dower presents, have sent back."]', '["n-m"]', '(only in plural) a dismissal, i.e. (of a wife) divorce (especially the document); also (of a daughter) dower presents, have sent back.', 'or שִׁלֻּחַ; from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7965}/[H7965]', 'lemma', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly."]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7966}/[H7966]', 'lemma', 'heb', 'שִׁלּוּם', '["shillûwm"]', '["a requital, i.e. (secure) retribution, (venal) a fee recompense, reward."]', '["n-m"]', 'a requital, i.e. (secure) retribution, (venal) a fee recompense, reward.', 'or שִׁלֻּם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7967}/[H7967]', 'lemma', 'heb', 'שַׁלּוּם', '["Shallûwm"]', '["Shallum, the name of fourteen Israelites Shallum."]', '["n-pr-m"]', 'Shallum, the name of fourteen Israelites Shallum.', 'or (shorter) שַׁלֻּם; the same as 7966;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7968}/[H7968]', 'lemma', 'heb', 'שַׁלּוּן', '["Shallûwn"]', '["Shallun, an Israelite Shallum."]', '["n-pr-m"]', 'Shallun, an Israelite Shallum.', 'probably for 7967;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7970}/[H7970]', 'lemma', 'heb', 'שְׁלוֹשִׁים', '["shᵉlôwshîym"]', '["thirty; or (ordinal) thirtieth thirty, thirtieth. Compare 7991."]', '["n-m"]', 'thirty; or (ordinal) thirtieth thirty, thirtieth. Compare 7991.', 'or שְׁלֹשִׁים; multiple of 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7971]', 'root', 'heb', 'שָׁלַח', '["shâlach"]', '["to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out)."]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7972}/[H7972]', 'lemma', 'arc', 'שְׁלַח', '["shᵉlach"]', '["put, send."]', '["v"]', 'put, send.', '(Aramaic) corresponding to 7971');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7973}/[H7973]', 'lemma', 'heb', 'שֶׁלַח', '["shelach"]', '["a missile of attack, i.e. spear; also (figuratively) a shoot of growth; i.e. branch dart, plant, × put off, sword, weapon."]', '["n-m"]', 'a missile of attack, i.e. spear; also (figuratively) a shoot of growth; i.e. branch dart, plant, × put off, sword, weapon.', 'from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7974}/[H7974]', 'lemma', 'heb', 'שֶׁלַח', '["Shelach"]', '["Shelach, a postdiluvian patriarch Salah, Shelah. Compare 7975."]', '["n-pr-m"]', 'Shelach, a postdiluvian patriarch Salah, Shelah. Compare 7975.', 'the same as 7973;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7975}/[H7975]', 'lemma', 'heb', 'שִׁלֹחַ', '["Shilôach"]', '["Shiloach, a fountain of Jerusalem Shiloah, Siloah."]', '["n-pr-loc"]', 'Shiloach, a fountain of Jerusalem Shiloah, Siloah.', 'or (in imitation of 7974) שֶׁלַח; (Nehemiah 3:15), from 7971; rill;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7976}/[H7976]', 'lemma', 'heb', 'שִׁלֻּחָה', '["shilluchâh"]', '["a shoot branch."]', '["n-f"]', 'a shoot branch.', 'feminine of 7964;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7977}/[H7977]', 'lemma', 'heb', 'שִׁלְחִי', '["Shilchîy"]', '["Shilchi, an Israelite Shilhi."]', '["n-pr-m"]', 'Shilchi, an Israelite Shilhi.', 'from 7973; missive, i.e. armed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7978}/[H7978]', 'lemma', 'heb', 'שִׁלְחִים', '["Shilchîym"]', '["Shilchim, a place in Palestine Shilhim."]', '["n-pr-loc"]', 'Shilchim, a place in Palestine Shilhim.', 'plural of 7973; javelins or sprouts;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7979}/[H7979]', 'lemma', 'heb', 'שֻׁלְחָן', '["shulchân"]', '["a table (as spread out); by implication, a meal table."]', '["n-m"]', 'a table (as spread out); by implication, a meal table.', 'from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7980]', 'root', 'heb', 'שָׁלַט', '["shâlaṭ"]', '["to dominate, i.e. govern; by implication, to permit (bear, have) rule, have dominion, give (have) power."]', '["v"]', 'to dominate, i.e. govern; by implication, to permit (bear, have) rule, have dominion, give (have) power.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7981}/[H7981]', 'lemma', 'arc', 'שְׁלֵט', '["shᵉlêṭ"]', '["have the mastery, have power, bear rule, be (make) ruler."]', '["v"]', 'have the mastery, have power, bear rule, be (make) ruler.', '(Aramaic) corresponding to 7980');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7982}/[H7982]', 'lemma', 'heb', 'שֶׁלֶט', '["sheleṭ"]', '["probably a shield (as controlling, i.e. protecting the person) shield."]', '["n-m"]', 'probably a shield (as controlling, i.e. protecting the person) shield.', 'from 7980;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7983}/[H7983]', 'lemma', 'heb', 'שִׁלְטוֹן', '["shilṭôwn"]', '["a potentate power."]', '["n-m"]', 'a potentate power.', 'from 7980;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7984}/[H7984]', 'lemma', 'arc', 'שִׁלְטוֹן', '["shilṭôwn"]', '["ruler."]', '["n-m"]', 'ruler.', '(Aramaic) or שִׁלְטֹןlemma שִׁלְטן missing vowel, corrected to שִׁלְטֹן; corresponding to 7983');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7985}/[H7985]', 'lemma', 'arc', 'שׇׁלְטָן', '["sholṭân"]', '["empire (abstractly or concretely) dominion."]', '["n-m"]', 'empire (abstractly or concretely) dominion.', '(Aramaic) from 7981;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7986}/[H7986]', 'lemma', 'heb', 'שַׁלֶּטֶת', '["shalleṭeth"]', '["a vixen imperious."]', '["a"]', 'a vixen imperious.', 'feminine from 7980;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7987}/[H7987]', 'lemma', 'heb', 'שְׁלִי', '["shᵉlîy"]', '["privacy quietly."]', '["n-m"]', 'privacy quietly.', 'from 7951;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7988}/[H7988]', 'lemma', 'heb', 'שִׁלְיָה', '["shilyâh"]', '["a fetus or babe (as extruded in birth) young one."]', '["n-f"]', 'a fetus or babe (as extruded in birth) young one.', 'feminine from 7953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7989}/[H7989]', 'lemma', 'heb', 'שַׁלִּיט', '["shallîyṭ"]', '["potent; concretely, a prince or warrior governor, mighty, that hath power, ruler."]', '["a"]', 'potent; concretely, a prince or warrior governor, mighty, that hath power, ruler.', 'from 7980;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7990}/[H7990]', 'lemma', 'arc', 'שַׁלִּיט', '["shallîyṭ"]', '["mighty; abstractly, permission; concretely, a premier captain, be lawful, rule(-r)."]', '["a"]', 'mighty; abstractly, permission; concretely, a premier captain, be lawful, rule(-r).', '(Aramaic) corresponding to 7989;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7991}/[H7991]', 'lemma', 'heb', 'שָׁלִישׁ', '["shâlîysh"]', '["a triple, i.e. (as a musical instrument) a triangle (or perhaps rather three-stringed lute); also (as an indefinite, great quantity) a three-fold measure (perhaps a treble ephah); also (as an officer) a general of the third rank (upward, i.e. the highest) captain, instrument of musick, (great) lord, (great) measure, prince, three (from the margin)."]', '["n-m"]', 'a triple, i.e. (as a musical instrument) a triangle (or perhaps rather three-stringed lute); also (as an indefinite, great quantity) a three-fold measure (perhaps a treble ephah); also (as an officer) a general of the third rank (upward, i.e. the highest) captain, instrument of musick, (great) lord, (great) measure, prince, three (from the margin).', 'or שָׁלוֹשׁ; (1 Chronicles 11:11; 1 Chronicles 12:18), or שָׁלֹשׁ; (2 Samuel 23:13), from 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7992}/[H7992]', 'lemma', 'heb', 'שְׁלִישִׁי', '["shᵉlîyshîy"]', '["third; feminine a third (part); by extension, a third (day, year or time); specifically, a third-story cell) third (part, rank, time), three (years old)."]', '["a"]', 'third; feminine a third (part); by extension, a third (day, year or time); specifically, a third-story cell) third (part, rank, time), three (years old).', 'ordinal from 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7993]', 'root', 'heb', 'שָׁלַךְ', '["shâlak"]', '["to throw out, down or away (literally or figuratively) adventure, cast (away, down, forth, off, out), hurl, pluck, throw."]', '["v"]', 'to throw out, down or away (literally or figuratively) adventure, cast (away, down, forth, off, out), hurl, pluck, throw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7994}/[H7994]', 'lemma', 'heb', 'שָׁלָךְ', '["shâlâk"]', '["bird of prey, usually thought to be the pelican (from casting itself into the sea) cormorant."]', '["n-m"]', 'bird of prey, usually thought to be the pelican (from casting itself into the sea) cormorant.', 'from 7993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7995}/[H7995]', 'lemma', 'heb', 'שַׁלֶּכֶת', '["shalleketh"]', '["a felling (of trees) when cast."]', '["n-f"]', 'a felling (of trees) when cast.', 'from 7993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7996}/[H7996]', 'lemma', 'heb', 'שַׁלֶּכֶת', '["Shalleketh"]', '["Shalleketh, a gate in Jerusalem Shalleketh."]', '["n-pr-m"]', 'Shalleketh, a gate in Jerusalem Shalleketh.', 'the same as 7995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7997]', 'root', 'heb', 'שָׁלַל', '["shâlal"]', '["to drop or strip; by implication, to plunder let fall, make self a prey, × of purpose, (make a, (take)) spoil."]', '["v"]', 'to drop or strip; by implication, to plunder let fall, make self a prey, × of purpose, (make a, (take)) spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7998}/[H7998]', 'lemma', 'heb', 'שָׁלָל', '["shâlâl"]', '["booty prey, spoil."]', '["n-m"]', 'booty prey, spoil.', 'from 7997;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H7999]', 'root', 'heb', 'שָׁלַם', '["shâlam"]', '["to be safe (in mind, body or estate); figuratively, to be (causatively, make) completed; by implication, to be friendly; by extension, to reciprocate (in various applications) make amends, (make an) end, finish, full, give again, make good, (re-) pay (again), (make) (to) (be at) peace(-able), that is perfect, perform, (make) prosper(-ous), recompense, render, requite, make restitution, restore, reward, × surely."]', '["v"]', 'to be safe (in mind, body or estate); figuratively, to be (causatively, make) completed; by implication, to be friendly; by extension, to reciprocate (in various applications) make amends, (make an) end, finish, full, give again, make good, (re-) pay (again), (make) (to) (be at) peace(-able), that is perfect, perform, (make) prosper(-ous), recompense, render, requite, make restitution, restore, reward, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8000}/[H8000]', 'lemma', 'arc', 'שְׁלַם', '["shᵉlam"]', '["to complete, to restore deliver, finish."]', '["v"]', 'to complete, to restore deliver, finish.', '(Aramaic) corresponding to 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8001}/[H8001]', 'lemma', 'arc', 'שְׁלָם', '["shᵉlâm"]', '["prosperity peace."]', '["n-m"]', 'prosperity peace.', '(Aramaic) corresponding to 7965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8002}/[H8002]', 'lemma', 'heb', 'שֶׁלֶם', '["shelem"]', '["properly, requital, i.e. a (voluntary) sacrifice in thanks peace offering."]', '["n-m"]', 'properly, requital, i.e. a (voluntary) sacrifice in thanks peace offering.', 'from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8003}/[H8003]', 'lemma', 'heb', 'שָׁלֵם', '["shâlêm"]', '["complete (literally or figuratively); especially friendly full, just, made ready, peaceable, perfect(-ed), quiet, Shalem (by mistake for a name), whole."]', '["a"]', 'complete (literally or figuratively); especially friendly full, just, made ready, peaceable, perfect(-ed), quiet, Shalem (by mistake for a name), whole.', 'from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8004}/[H8004]', 'lemma', 'heb', 'שָׁלֵם', '["Shâlêm"]', '["Shalem, an early name of Jerusalem Salem."]', '["n-pr-loc"]', 'Shalem, an early name of Jerusalem Salem.', 'the same as 8003; peaceful;');
