INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8025]', 'root', 'heb', 'שָׁלַף', '["shâlaph"]', '["to pull out, up or off draw (off), grow up, pluck off."]', '["v"]', 'to pull out, up or off draw (off), grow up, pluck off.', 'a primitive root;');
