INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8027]', 'root', 'heb', 'שָׁלַשׁ', '["shâlash"]', '["to be (causatively, make) triplicate (by restoration, in portions, strands, days or years) do the third time, (divide into, stay) three (days, -fold, parts, years old)."]', '["v"]', 'to be (causatively, make) triplicate (by restoration, in portions, strands, days or years) do the third time, (divide into, stay) three (days, -fold, parts, years old).', 'a primitive root perhaps originally to intensify, i.e. treble; but apparently used only as denominative from 7969,');
