INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8040]', 'root', 'heb', 'שְׂמֹאול', '["sᵉmôʼwl"]', '["properly, dark (as enveloped), i.e. the north; hence (by orientation), the left hand left (hand, side)."]', '["n-m"]', 'properly, dark (as enveloped), i.e. the north; hence (by orientation), the left hand left (hand, side).', 'or שְׂמֹאל; a primitive word (rather perhaps from the same as 8071 (by insertion of the aleph) through the idea of wrapping up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8041]', 'root', 'heb', 'שָׂמַאל', '["sâmaʼl"]', '["to use the left hand or pass in that direction (go, turn) (on the, to the) left."]', '["v"]', 'to use the left hand or pass in that direction (go, turn) (on the, to the) left.', 'a primitive root (denominative from 8040);');
