INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8055]', 'root', 'heb', 'שָׂמַח', '["sâmach"]', '["probably to brighten up, i.e. (figuratively) be (causatively, make) blithe or gleesome cheer up, be (make) glad, (have, make) joy(-ful), be (make) merry, (cause to, make to) rejoice, × very."]', '["v"]', 'probably to brighten up, i.e. (figuratively) be (causatively, make) blithe or gleesome cheer up, be (make) glad, (have, make) joy(-ful), be (make) merry, (cause to, make to) rejoice, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8056}/[H8056]', 'lemma', 'heb', 'שָׂמֵחַ', '["sâmêach"]', '["blithe or gleeful (be) glad, joyful, (making) merry((-hearted), -ily), rejoice(-ing)."]', '["a"]', 'blithe or gleeful (be) glad, joyful, (making) merry((-hearted), -ily), rejoice(-ing).', 'from 8055;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8057}/[H8057]', 'lemma', 'heb', 'שִׂמְחָה', '["simchâh"]', '["blithesomeness or glee, (religious or festival) × exceeding(-ly), gladness, joy(-fulness), mirth, pleasure, rejoice(-ing)."]', '["n-f"]', 'blithesomeness or glee, (religious or festival) × exceeding(-ly), gladness, joy(-fulness), mirth, pleasure, rejoice(-ing).', 'from 8056;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8058]', 'root', 'heb', 'שָׁמַט', '["shâmaṭ"]', '["to fling down; incipiently to jostle; figuratively, to let alone, desist, remit discontinue, overthrow, release, let rest, shake, stumble, throw down."]', '["v"]', 'to fling down; incipiently to jostle; figuratively, to let alone, desist, remit discontinue, overthrow, release, let rest, shake, stumble, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8059}/[H8059]', 'lemma', 'heb', 'שְׁמִטָּה', '["shᵉmiṭṭâh"]', '["remission (of debt) or suspension of labor) release."]', '["n-f"]', 'remission (of debt) or suspension of labor) release.', 'from 8058;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8060}/[H8060]', 'lemma', 'heb', 'שַׁמַּי', '["Shammay"]', '["Shammai, the name of three Israelites Shammai."]', '["n-pr-m"]', 'Shammai, the name of three Israelites Shammai.', 'from 8073; destructive;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8061}/[H8061]', 'lemma', 'heb', 'שְׁמִידָע', '["Shᵉmîydâʻ"]', '["Shemida, an Israelite Shemida, Shemidah."]', '["n-pr-m"]', 'Shemida, an Israelite Shemida, Shemidah.', 'apparently from 8034 and 3045; name of knowing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8062}/[H8062]', 'lemma', 'heb', 'שְׁמִידָעִי', '["Shᵉmîydâʻîy"]', '["a Shemidaite (collectively) or descendants of Shemida Shemidaites."]', '["n-pr-m"]', 'a Shemidaite (collectively) or descendants of Shemida Shemidaites.', 'patronymically from 8061;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8063}/[H8063]', 'lemma', 'heb', 'שְׂמִיכָה', '["sᵉmîykâh"]', '["a run (as sustaining the Oriental sitter) mantle."]', '["n-f"]', 'a run (as sustaining the Oriental sitter) mantle.', 'from 5564;');
