INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8066}/[H8066]', 'lemma', 'heb', 'שְׁמִינִי', '["shᵉmîynîy"]', '["eight eight."]', '["a"]', 'eight eight.', 'from 8083;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8067}/[H8067]', 'lemma', 'heb', 'שְׁמִינִית', '["shᵉmîynîyth"]', '["probably an eight-stringed lyre Sheminith."]', '["n-f"]', 'probably an eight-stringed lyre Sheminith.', 'feminine of 8066;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8068}/[H8068]', 'lemma', 'heb', 'שָׁמִיר', '["shâmîyr"]', '["a thorn; also (from its keenness for scratching) a gem, probably the diamond adamant (stone), brier, diamond."]', '["n-m"]', 'a thorn; also (from its keenness for scratching) a gem, probably the diamond adamant (stone), brier, diamond.', 'from 8104 in the original sense of pricking;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8069}/[H8069]', 'lemma', 'heb', 'שָׁמִיר', '["Shâmîyr"]', '["Shamir, the name of two places in Palestine Shamir. Compare 8053."]', '["n-pr"]', 'Shamir, the name of two places in Palestine Shamir. Compare 8053.', 'the same as 8068;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8070}/[H8070]', 'lemma', 'heb', 'שְׁמִירָמוֹת', '["Shᵉmîyrâmôwth"]', '["Shemiramoth, the name of two Israelites Shemiramoth."]', '["n-pr-m"]', 'Shemiramoth, the name of two Israelites Shemiramoth.', 'or שְׁמָרִימוֹת; probably from 8034 and plural of 7413; name of heights;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8071}/[H8071]', 'lemma', 'heb', 'שִׂמְלָה', '["simlâh"]', '["a dress, especially a mantle apparel, cloth(-es, -ing), garment, raiment. Compare 8008."]', '["n-f"]', 'a dress, especially a mantle apparel, cloth(-es, -ing), garment, raiment. Compare 8008.', 'perhaps by permutation for the feminine of 5566 (through the idea of a cover assuming the shape of the object beneath);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8072}/[H8072]', 'lemma', 'heb', 'שַׂמְלָה', '["Samlâh"]', '["Samlah, an Edomite Samlah."]', '["n-pr-m"]', 'Samlah, an Edomite Samlah.', 'probably for the same as 8071;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8073}/[H8073]', 'lemma', 'heb', 'שַׁמְלַי', '["Shamlay"]', '["Shamlai, one of the Nethinim Shalmai (from the margin)."]', '["n-pr-m"]', 'Shamlai, one of the Nethinim Shalmai (from the margin).', 'for 8014;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8074]', 'root', 'heb', 'שָׁמֵם', '["shâmêm"]', '["to stun (or intransitively, grow numb), i.e. devastate or (figuratively) stupefy (both usually in a passive sense) make amazed, be astonied, (be an) astonish(-ment), (be, bring into, unto, lay, lie, make) desolate(-ion, places), be destitute, destroy (self), (lay, lie, make) waste, wonder."]', '["v"]', 'to stun (or intransitively, grow numb), i.e. devastate or (figuratively) stupefy (both usually in a passive sense) make amazed, be astonied, (be an) astonish(-ment), (be, bring into, unto, lay, lie, make) desolate(-ion, places), be destitute, destroy (self), (lay, lie, make) waste, wonder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8075}/[H8075]', 'lemma', 'arc', 'שְׁמַם', '["shᵉmam"]', '["be astonied."]', '["v"]', 'be astonied.', '(Aramaic) corresponding to 8074');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8076}/[H8076]', 'lemma', 'heb', 'שָׁמֵם', '["shâmêm"]', '["ruined desolate."]', '["a"]', 'ruined desolate.', 'from 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8077}/[H8077]', 'lemma', 'heb', 'שְׁמָמָה', '["shᵉmâmâh"]', '["devastation; figuratively, astonishment (laid, × most) desolate(-ion), waste."]', '["n-f"]', 'devastation; figuratively, astonishment (laid, × most) desolate(-ion), waste.', 'or שִׁמָמָה; feminine of 8076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8078}/[H8078]', 'lemma', 'heb', 'שִׁמָּמוֹן', '["shimmâmôwn"]', '["stupefaction astonishment."]', '["n-m"]', 'stupefaction astonishment.', 'from 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8079}/[H8079]', 'lemma', 'heb', 'שְׂמָמִית', '["sᵉmâmîyth"]', '["a lizard (from the superstition of its noxiousness) spider."]', '["n-f"]', 'a lizard (from the superstition of its noxiousness) spider.', 'probably from 8074 (in the sense of poisoning);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8080]', 'root', 'heb', 'שָׁמַן', '["shâman"]', '["to shine, i.e. (by analogy) be (causatively, make) oily or gross become (make, wax) fat."]', '["v"]', 'to shine, i.e. (by analogy) be (causatively, make) oily or gross become (make, wax) fat.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8081}/[H8081]', 'lemma', 'heb', 'שֶׁמֶן', '["shemen"]', '["grease, especially liquid (as from the olive, often perfumed); figuratively, richness anointing, × fat (things), × fruitful, oil(-ed), ointment, olive, pine."]', '["n-m"]', 'grease, especially liquid (as from the olive, often perfumed); figuratively, richness anointing, × fat (things), × fruitful, oil(-ed), ointment, olive, pine.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8082}/[H8082]', 'lemma', 'heb', 'שָׁמֵן', '["shâmên"]', '["greasy, i.e. gross; figuratively, rich fat, lusty, plenteous."]', '["a"]', 'greasy, i.e. gross; figuratively, rich fat, lusty, plenteous.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8083}/[H8083]', 'lemma', 'heb', 'שְׁמֹנֶה', '["shᵉmôneh"]', '["a cardinal number, eight (as if a surplus above the ''perfect'' seven); also (as ordinal) eighth eight(-een, -eenth), eighth."]', '["n"]', 'a cardinal number, eight (as if a surplus above the ''perfect'' seven); also (as ordinal) eighth eight(-een, -eenth), eighth.', 'or שְׁמוֹנֶה; feminine שְׁמֹנָה; or שְׁמוֹנָה; apparently from 8082 through the idea of plumpness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8084}/[H8084]', 'lemma', 'heb', 'שְׁמֹנִים', '["shᵉmônîym"]', '["eighty, also eightieth eighty(-ieth), fourscore."]', '["a"]', 'eighty, also eightieth eighty(-ieth), fourscore.', 'or שְׁמוֹנִים; multiple from 8083;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8085]', 'root', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness."]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8086}/[H8086]', 'lemma', 'arc', 'שְׁמַע', '["shᵉmaʻ"]', '["hear, obey."]', '["v"]', 'hear, obey.', '(Aramaic) corresponding to 8085');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8087}/[H8087]', 'lemma', 'heb', 'שֶׁמַע', '["Shemaʻ"]', '["Shema, the name of a place in Palestine and of four Israelites Shema."]', '["n-pr-m"]', 'Shema, the name of a place in Palestine and of four Israelites Shema.', 'for the same as 8088;');
