INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8089}/[H8089]', 'lemma', 'heb', 'שֹׁמַע', '["shômaʻ"]', '["a report fame."]', '["n-m"]', 'a report fame.', 'from 8085;');
