INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8103}/[H8103]', 'lemma', 'heb', 'שִׁמְצָה', '["shimtsâh"]', '["scornful whispering (of hostile spectators) shame."]', '["n-f"]', 'scornful whispering (of hostile spectators) shame.', 'feminine of 8102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8104]', 'root', 'heb', 'שָׁמַר', '["shâmar"]', '["properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man)."]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8105}/[H8105]', 'lemma', 'heb', 'שֶׁמֶר', '["shemer"]', '["something preserved, i.e. the settlings (plural only) of wine dregs, (wines on the) lees."]', '["n-m"]', 'something preserved, i.e. the settlings (plural only) of wine dregs, (wines on the) lees.', 'from 8104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8106}/[H8106]', 'lemma', 'heb', 'שֶׁמֶר', '["Shemer"]', '["Shemer, the name of three Israelites Shamer, Shemer."]', '["n-pr-m"]', 'Shemer, the name of three Israelites Shamer, Shemer.', 'the same as 8105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8107}/[H8107]', 'lemma', 'heb', 'שִׁמֻּר', '["shimmur"]', '["an observance × be (much) observed."]', '["n-m"]', 'an observance × be (much) observed.', 'from 8104;');
