INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8169}/[H8169]', 'lemma', 'heb', 'שַׁעַלְבִים', '["Shaʻalbîym"]', '["Shaalbim or Shaalabbin, a place in Palestine Shaalabbin, Shaalbim."]', '["n-pr-loc"]', 'Shaalbim or Shaalabbin, a place in Palestine Shaalabbin, Shaalbim.', 'or שַׁעֲלַבִּין; plural from 7776; fox-holes;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8170}/[H8170]', 'lemma', 'heb', 'שַׁעַלְבֹנִי', '["Shaʻalbônîy"]', '["a Shaalbonite or inhabitant of Shaalbin Shaalbonite."]', '["n-pr-m"]', 'a Shaalbonite or inhabitant of Shaalbin Shaalbonite.', 'patrial from 8169;');
