INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8172]', 'root', 'heb', 'שָׁעַן', '["shâʻan"]', '["to support one''s self lean, lie, rely, rest (on, self), stay."]', '["v"]', 'to support one''s self lean, lie, rely, rest (on, self), stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8173]', 'root', 'heb', 'שָׁעַע', '["shâʻaʻ"]', '["(in a good acceptation) to look upon (with complacency), i.e. fondle, please or amuse (self); (in a bad one) to look about (in dismay), i.e. stare cry (out) (by confusion with 7768), dandle, delight (self), play, shut."]', '["v"]', '(in a good acceptation) to look upon (with complacency), i.e. fondle, please or amuse (self); (in a bad one) to look about (in dismay), i.e. stare cry (out) (by confusion with 7768), dandle, delight (self), play, shut.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8174}/[H8174]', 'lemma', 'heb', 'שַׁעַף', '["Shaʻaph"]', '["Shaaph, the name of two Israelites Shaaph."]', '["n-pr-m"]', 'Shaaph, the name of two Israelites Shaaph.', 'from 5586; fluctuation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8175]', 'root', 'heb', 'שָׂעַר', '["sâʻar"]', '["to storm; by implication, to shiver, i.e. fear be (horribly) afraid, fear, hurl as a storm, be tempestuous, come like (take away as with) a whirlwind."]', '["v"]', 'to storm; by implication, to shiver, i.e. fear be (horribly) afraid, fear, hurl as a storm, be tempestuous, come like (take away as with) a whirlwind.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8176]', 'root', 'heb', 'שָׁעַר', '["shâʻar"]', '["to act as gatekeeper; (figuratively) to estimate think."]', '["v"]', 'to act as gatekeeper; (figuratively) to estimate think.', 'a primitive root; to split or open, i.e. (literally, but only as denominative from 8179); compare see 7778');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8177}/[H8177]', 'lemma', 'arc', 'שְׂעַר', '["sᵉʻar"]', '["hair hair."]', '["n-m"]', 'hair hair.', '(Aramaic) corresponding to 8181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8178}/[H8178]', 'lemma', 'heb', 'שַׂעַר', '["saʻar"]', '["a terror affrighted, × horribly, × sore, storm. See 8181."]', '["n-m"]', 'a terror affrighted, × horribly, × sore, storm. See 8181.', 'from 8175;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8179}/[H8179]', 'lemma', 'heb', 'שַׁעַר', '["shaʻar"]', '["an opening, i.e. door or gate city, door, gate, port (× -er)."]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8180}/[H8180]', 'lemma', 'heb', 'שַׁעַר', '["shaʻar"]', '["a measure (as a section) (hundred-) fold."]', '["n-m"]', 'a measure (as a section) (hundred-) fold.', 'from 8176;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8181}/[H8181]', 'lemma', 'heb', 'שֵׂעָר', '["sêʻâr"]', '["hair (as if tossed or bristling) hair(-y), × rough."]', '["n-m"]', 'hair (as if tossed or bristling) hair(-y), × rough.', 'or שַׂעַר; (Isaiah 7:20), from 8175 in the sense of dishevelling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8182}/[H8182]', 'lemma', 'heb', 'שֹׁעָר', '["shôʻâr"]', '["harsh or horrid, i.e. offensive vile."]', '["a"]', 'harsh or horrid, i.e. offensive vile.', 'from 8176;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8183}/[H8183]', 'lemma', 'heb', 'שְׂעָרָה', '["sᵉʻârâh"]', '["a hurricane storm, tempest."]', '["n-f"]', 'a hurricane storm, tempest.', 'feminine of 8178;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8184}/[H8184]', 'lemma', 'heb', 'שְׂעֹרָה', '["sᵉʻôrâh"]', '["barley (as villose) barley."]', '["n-f"]', 'barley (as villose) barley.', 'or שְׂעוֹרָה (feminine meaning the plant); and (masculine meaning the grain); also שְׂעֹר; or שְׂעוֹר; from 8175 in the sense of roughness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8185}/[H8185]', 'lemma', 'heb', 'שַׂעֲרָה', '["saʻărâh"]', '["hairiness hair."]', '["n-f"]', 'hairiness hair.', 'feminine of 8181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8186}/[H8186]', 'lemma', 'heb', 'שַׁעֲרוּרָה', '["shaʻărûwrâh"]', '["something fearful horrible thing."]', '["n-f"]', 'something fearful horrible thing.', 'or שַׁעֲרִירִיָּה; or שַׁעֲרֻרִת; feminine from 8176 in the sense of 8175;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8187}/[H8187]', 'lemma', 'heb', 'שְׁעַרְיָה', '["Shᵉʻaryâh"]', '["Shearjah, an Israelite Sheariah."]', '["n-pr-m"]', 'Shearjah, an Israelite Sheariah.', 'from 8176 and 3050; Jah has stormed;');
