INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8189}/[H8189]', 'lemma', 'heb', 'שַׁעֲרַיִם', '["Shaʻărayim"]', '["Shaarajim, a place in Palestine Shaaraim."]', '["n-pr-loc"]', 'Shaarajim, a place in Palestine Shaaraim.', 'dual of 8179; double gates;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8191}/[H8191]', 'lemma', 'heb', 'שַׁעְשֻׁעַ', '["shaʻshuaʻ"]', '["enjoyment delight, pleasure."]', '["n-m"]', 'enjoyment delight, pleasure.', 'from 8173;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8192]', 'root', 'heb', 'שָׁפָה', '["shâphâh"]', '["to abrade, i.e. bare high, stick out."]', '["v"]', 'to abrade, i.e. bare high, stick out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8193}/[H8193]', 'lemma', 'heb', 'שָׂפָה', '["sâphâh"]', '["the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words."]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8194}/[H8194]', 'lemma', 'heb', 'שָׁפָה', '["shâphâh"]', '["a cheese (as strained from the whey) cheese."]', '["n-f"]', 'a cheese (as strained from the whey) cheese.', 'from 8192 in the sense of clarifying;');
