INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8196}/[H8196]', 'lemma', 'heb', 'שְׁפוֹט', '["shᵉphôwṭ"]', '["a judicial sentence, i.e. punishment judgment."]', '["n-m"]', 'a judicial sentence, i.e. punishment judgment.', 'or שְׁפוּט; from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8197}/[H8197]', 'lemma', 'heb', 'שְׁפוּפָם', '["Shᵉphûwphâm"]', '["Shephupham, an Israelite Shephuphan, Shupham."]', '["n-pr-m"]', 'Shephupham, an Israelite Shephuphan, Shupham.', 'or שְׁפוּפָן; from the same as 8207; serpent-like;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8199]', 'root', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule."]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8200}/[H8200]', 'lemma', 'arc', 'שְׁפַט', '["shᵉphaṭ"]', '["to judge magistrate."]', '["v"]', 'to judge magistrate.', '(Aramaic) corresponding to 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8201}/[H8201]', 'lemma', 'heb', 'שֶׁפֶט', '["shepheṭ"]', '["a sentence, i.e. infliction judgment."]', '["n-m"]', 'a sentence, i.e. infliction judgment.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8202}/[H8202]', 'lemma', 'heb', 'שָׁפָט', '["Shâphâṭ"]', '["Shaphat, the name of four Israelites Shaphat."]', '["n-pr-m"]', 'Shaphat, the name of four Israelites Shaphat.', 'from 8199; judge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8203}/[H8203]', 'lemma', 'heb', 'שְׁפַטְיָה', '["Shᵉphaṭyâh"]', '["Shephatjah, the name of ten Israelites Shephatiah."]', '["n-pr-m"]', 'Shephatjah, the name of ten Israelites Shephatiah.', 'or שְׁפַטְיָהוּ; from 8199 and 3050; Jah has judged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8204}/[H8204]', 'lemma', 'heb', 'שִׁפְטָן', '["Shiphṭân"]', '["Shiphtan, an Israelite Shiphtan."]', '["n-pr-m"]', 'Shiphtan, an Israelite Shiphtan.', 'from 8199; judge-like;');
