INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8208}/[H8208]', 'lemma', 'heb', 'שָׁפִיר', '["Shâphîyr"]', '["Shaphir, a place in Palestine Saphir."]', '["n-pr-loc"]', 'Shaphir, a place in Palestine Saphir.', 'from 8231; beautiful;');
