INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8210]', 'root', 'heb', 'שָׁפַךְ', '["shâphak"]', '["to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip."]', '["v"]', 'to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip.', 'a primitive root;');
