INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8213]', 'root', 'heb', 'שָׁפֵל', '["shâphêl"]', '["to depress or sink (especially figuratively, to humiliate, intransitive or transitive) abase, bring (cast, put) down, debase, humble (self), be (bring, lay, make, put) low(-er)."]', '["v"]', 'to depress or sink (especially figuratively, to humiliate, intransitive or transitive) abase, bring (cast, put) down, debase, humble (self), be (bring, lay, make, put) low(-er).', 'a primitive root;');
