INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8395}/[H8395]', 'lemma', 'heb', 'תְּבוּסָה', '["tᵉbûwçâh"]', '["a treading down, i.e. ruin destruction."]', '["n-f"]', 'a treading down, i.e. ruin destruction.', 'from 947;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8396}/[H8396]', 'lemma', 'heb', 'תָּבוֹר', '["Tâbôwr"]', '["Tabor, a mountain in Palestine, also a city adjacent Tabor."]', '["n-pr"]', 'Tabor, a mountain in Palestine, also a city adjacent Tabor.', 'from a root corresponding to 8406; broken region;');
