INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8398}/[H8398]', 'lemma', 'heb', 'תֵּבֵל', '["têbêl"]', '["the earth (as moist and therefore inhabited); by extension, the globe; by implication, its inhabitants; specifically, a particular land, as Babylonia, Palestine habitable part, world."]', '["n-f"]', 'the earth (as moist and therefore inhabited); by extension, the globe; by implication, its inhabitants; specifically, a particular land, as Babylonia, Palestine habitable part, world.', 'from 2986;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8399}/[H8399]', 'lemma', 'heb', 'תַּבְלִית', '["tablîyth"]', '["consumption destruction."]', '["n-f"]', 'consumption destruction.', 'from 1086;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8400}/[H8400]', 'lemma', 'heb', 'תְּבַּלֻּל', '["tᵉballul"]', '["a cataract (in the eye) blemish."]', '["n-m"]', 'a cataract (in the eye) blemish.', 'from 1101 in the original sense of flowing;');
