INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8408}/[H8408]', 'lemma', 'heb', 'תַּגְמוּל', '["tagmûwl"]', '["a bestowment benefit."]', '["n-m"]', 'a bestowment benefit.', 'from 1580;');
