INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8410}/[H8410]', 'lemma', 'heb', 'תִּדְהָר', '["tidhâr"]', '["enduring; a species of hard-wood or lasting tree (perhaps oak) pine (tree)."]', '["n-m"]', 'enduring; a species of hard-wood or lasting tree (perhaps oak) pine (tree).', 'apparently from 1725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8411}/[H8411]', 'lemma', 'arc', 'תְּדִירָא', '["tᵉdîyrâʼ"]', '["permanence, i.e. (adverb) constantly continually."]', '["n-f"]', 'permanence, i.e. (adverb) constantly continually.', '(Aramaic) from 1753 in the original sense of enduring;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8412}/[H8412]', 'lemma', 'heb', 'תַּדְמֹר', '["Tadmôr"]', '["Tadmor, a place near Palestine Tadmor."]', '["n-pr-loc"]', 'Tadmor, a place near Palestine Tadmor.', 'or תַּמֹּר; (1 Kings 9:18), apparently from 8558; palm-city;');
