INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8415}/[H8415]', 'lemma', 'heb', 'תְּהוֹם', '["tᵉhôwm"]', '["an abyss (as a surging mass of water), especially the deep (the main sea or the subterranean watersupply) deep (place), depth."]', '["n"]', 'an abyss (as a surging mass of water), especially the deep (the main sea or the subterranean watersupply) deep (place), depth.', 'or תְּהֹם; (usually feminine) from 1949;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8416}/[H8416]', 'lemma', 'heb', 'תְּהִלָּה', '["tᵉhillâh"]', '["laudation; specifically (concretely) a hymn praise."]', '["n-f"]', 'laudation; specifically (concretely) a hymn praise.', 'from 1984;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8417}/[H8417]', 'lemma', 'heb', 'תׇּהֳלָה', '["tohŏlâh"]', '["braggadocio, i.e. (by implication) fatuity folly."]', '["n-f"]', 'braggadocio, i.e. (by implication) fatuity folly.', 'feminine of an unused noun (apparently from 1984) meaning bluster;');
