INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8424}/[H8424]', 'lemma', 'heb', 'תּוּגָה', '["tûwgâh"]', '["depression (of spirits); concretely a grief heaviness, sorrow."]', '["n-f"]', 'depression (of spirits); concretely a grief heaviness, sorrow.', 'from 3013;');
