INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8427]', 'root', 'heb', 'תָּוָה', '["tâvâh"]', '["to mark out, i.e. (primitive) scratch or (definite) imprint scrabble, set (a mark)."]', '["v"]', 'to mark out, i.e. (primitive) scratch or (definite) imprint scrabble, set (a mark).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8428]', 'root', 'heb', 'תָּוָה', '["tâvâh"]', '["to grieve limit (by confusion with 8427)."]', '["v"]', 'to grieve limit (by confusion with 8427).', 'a primitive root (or perhaps identical with 8427 through a similar idea from scraping to pieces);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8429}/[H8429]', 'lemma', 'arc', 'תְּוַהּ', '["tᵉvahh"]', '["to amaze, i.e. (reflex. by implication) take alarm be astonied."]', '["v"]', 'to amaze, i.e. (reflex. by implication) take alarm be astonied.', '(Aramaic) corresponding to 8539 or perhaps to 7582 through the idea of sweeping to ruin (compare 8428);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8431}/[H8431]', 'lemma', 'heb', 'תּוֹחֶלֶת', '["tôwcheleth"]', '["expectation hope."]', '["n-f"]', 'expectation hope.', 'from 3176;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8433}/[H8433]', 'lemma', 'heb', 'תּוֹכֵחָה', '["tôwkêchâh"]', '["chastisement; figuratively (by words) correction, refutation, proof (even in defence) argument, × chastened, correction, reasoning, rebuke, reproof, × be (often) reproved."]', '["n-f"]', 'chastisement; figuratively (by words) correction, refutation, proof (even in defence) argument, × chastened, correction, reasoning, rebuke, reproof, × be (often) reproved.', 'and תּוֹכַחַת; from 3198;');
