INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8435}/[H8435]', 'lemma', 'heb', 'תּוֹלְדָה', '["tôwlᵉdâh"]', '["(plural only) descent, i.e. family; (figuratively) history birth, generations."]', '["n-f"]', '(plural only) descent, i.e. family; (figuratively) history birth, generations.', 'or תֹּלְדָה; from 3205;');
