INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8437}/[H8437]', 'lemma', 'heb', 'תּוֹלָל', '["tôwlâl"]', '["causing to howl, i.e. an oppressor that wasted."]', '["n-m"]', 'causing to howl, i.e. an oppressor that wasted.', 'from 3213;');
