INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8439}/[H8439]', 'lemma', 'heb', 'תּוֹלָע', '["Tôwlâʻ"]', '["Tola, the name of two Israelites Tola."]', '["n-pr-m"]', 'Tola, the name of two Israelites Tola.', 'the same as 8438; worm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8440}/[H8440]', 'lemma', 'heb', 'תּוֹלָעִי', '["Tôwlâʻîy"]', '["a Tolaïte (collectively) or descendants of Tola Tolaites."]', '["n-pr-m"]', 'a Tolaïte (collectively) or descendants of Tola Tolaites.', 'patronymically from 8439;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8441}/[H8441]', 'lemma', 'heb', 'תּוֹעֵבַה', '["tôwʻêbah"]', '["properly, something disgusting (morally), i.e. (as noun) an abhorrence; especially idolatry or (concretely) an idol abominable (custom, thing), abomination."]', '["n-f"]', 'properly, something disgusting (morally), i.e. (as noun) an abhorrence; especially idolatry or (concretely) an idol abominable (custom, thing), abomination.', 'or תֹּעֵבַה; feminine active participle of 8581;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8442}/[H8442]', 'lemma', 'heb', 'תּוֹעָה', '["tôwʻâh"]', '["mistake, i.e. (morally) impiety, or (political) injury error, hinder."]', '["n-f"]', 'mistake, i.e. (morally) impiety, or (political) injury error, hinder.', 'feminine active participle of 8582;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8443}/[H8443]', 'lemma', 'heb', 'תּוֹעָפָה', '["tôwʻâphâh"]', '["(only in plural collective) weariness, i.e. (by implication) toil (treasure so obtained) or speed plenty, strength."]', '["n-f"]', '(only in plural collective) weariness, i.e. (by implication) toil (treasure so obtained) or speed plenty, strength.', 'from 3286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8444}/[H8444]', 'lemma', 'heb', 'תּוֹצָאָה', '["tôwtsâʼâh"]', '["(only in plural collective) exit, i.e. (geographical) boundary, or (figuratively) deliverance, (actively) source border(-s), going(-s) forth (out), issues, outgoings."]', '["n-f"]', '(only in plural collective) exit, i.e. (geographical) boundary, or (figuratively) deliverance, (actively) source border(-s), going(-s) forth (out), issues, outgoings.', 'or תֹּצָאָה; from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8445}/[H8445]', 'lemma', 'heb', 'תּוֹקַהַת', '["Tôwqahath"]', '["Tokahath, an Israelite Tikvath (by correction for 8616)."]', '["n-pr-m"]', 'Tokahath, an Israelite Tikvath (by correction for 8616).', 'from the same as 3349; obedience;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8446]', 'root', 'heb', 'תּוּר', '["tûwr"]', '["to meander (causatively, guide) about, especially for trade or reconnoitring chap(-man), sent to descry, be excellent, merchant(-man), search (out), seek, (e-) spy (out)."]', '["v"]', 'to meander (causatively, guide) about, especially for trade or reconnoitring chap(-man), sent to descry, be excellent, merchant(-man), search (out), seek, (e-) spy (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8447}/[H8447]', 'lemma', 'heb', 'תּוֹר', '["tôwr"]', '["a succession, i.e. a string or (abstractly) order border, row, turn."]', '["n-m"]', 'a succession, i.e. a string or (abstractly) order border, row, turn.', 'or תֹּר; from 8446;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8448}/[H8448]', 'lemma', 'heb', 'תּוֹר', '["tôwr"]', '["a manner (as a sort of turn) estate."]', '["n-f"]', 'a manner (as a sort of turn) estate.', 'probably the same as 8447;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8449}/[H8449]', 'lemma', 'heb', 'תּוֹר', '["tôwr"]', '["a ring-dove, often (figuratively) as a term of endearment (turtle) dove."]', '["n-f"]', 'a ring-dove, often (figuratively) as a term of endearment (turtle) dove.', 'or תֹּר; probably the same as 8447;');
