INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8456]', 'root', 'heb', 'תָּזַז', '["tâzaz"]', '["to lop off cut down."]', '["v"]', 'to lop off cut down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8457}/[H8457]', 'lemma', 'heb', 'תַּזְנוּת', '["taznûwth"]', '["harlotry, i.e. (figuratively) idolatry fornication, whoredom."]', '["n-f"]', 'harlotry, i.e. (figuratively) idolatry fornication, whoredom.', 'or תַּזְנֻת; from 2181;');
