INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8463}/[H8463]', 'lemma', 'heb', 'תַּחֲלוּא', '["tachălûwʼ"]', '["a malady disease, × grievous, (that are) sick(-ness)."]', '["n-m"]', 'a malady disease, × grievous, (that are) sick(-ness).', 'or תַּחֲלֻא; from 2456;');
