INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8471}/[H8471]', 'lemma', 'heb', 'תַּחְפַּנְחֵס', '["Tachpanchêç"]', '["Tachpanches, Techaphneches or Tachpenes, a place in Egypt Tahapanes, Tahpanhes, Tehaphnehes."]', '["n-pr-loc"]', 'Tachpanches, Techaphneches or Tachpenes, a place in Egypt Tahapanes, Tahpanhes, Tehaphnehes.', 'or תְּחַפְנְחֵס; (Ezekiel 30:18), or תַּחְפְּנֵס; (Jeremiah 2:16), of Egyptian derivation;');
