INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8479}/[H8479]', 'lemma', 'arc', 'תַּחַת', '["tachath"]', '["under."]', '["prep"]', 'under.', '(Aramaic) corresponding to 8478');
