INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8501>', 'opaque', 'heb', 'תָּכָךְ', '["tâkâk"]', '["to dissever, i.e. crush deceitful."]', '["n-m"]', 'to dissever, i.e. crush deceitful.', 'from an unused root meaning');
