INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8542>', 'opaque', 'heb', 'תַּמּוּז', '["Tammûwz"]', '["Tammuz, a Phoenician deity Tammuz."]', '["n-pr"]', 'Tammuz, a Phoenician deity Tammuz.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8543}/[H8543]', 'lemma', 'heb', 'תְּמוֹל', '["tᵉmôwl"]', '["properly, ago, i.e. a (short or long) time since; especially yesterday, or day before yesterday before (-time), these (three) days, heretofore, time past, yesterday."]', '["adv"]', 'properly, ago, i.e. a (short or long) time since; especially yesterday, or day before yesterday before (-time), these (three) days, heretofore, time past, yesterday.', 'or תְּמֹל; probably for 865; sometimes with 8032');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8544}/[H8544]', 'lemma', 'heb', 'תְּמוּנָה', '["tᵉmûwnâh"]', '["something portioned (i.e. fashioned) out, as a shape, i.e. (indefinitely) phantom, or (specifically) embodiment, or (figuratively) manifestation (of favor) image, likeness, similitude."]', '["n-f"]', 'something portioned (i.e. fashioned) out, as a shape, i.e. (indefinitely) phantom, or (specifically) embodiment, or (figuratively) manifestation (of favor) image, likeness, similitude.', 'or תְּמֻנָה; from 4327;');
