INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8549}/[H8549]', 'lemma', 'heb', 'תָּמִים', '["tâmîym"]', '["entire (literally, figuratively or morally); also (as noun) integrity, truth without blemish, complete, full, perfect, sincerely (-ity), sound, without spot, undefiled, upright(-ly), whole."]', '["a"]', 'entire (literally, figuratively or morally); also (as noun) integrity, truth without blemish, complete, full, perfect, sincerely (-ity), sound, without spot, undefiled, upright(-ly), whole.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8550}/[H8550]', 'lemma', 'heb', 'תֻּמִּים', '["Tummîym"]', '["perfections, i.e. (techn.) one of the epithets of the objects in the high-priest''s breastplate as an emblem of complete Truth Thummim."]', '["n-pr-m"]', 'perfections, i.e. (techn.) one of the epithets of the objects in the high-priest''s breastplate as an emblem of complete Truth Thummim.', 'plural of 8537;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8551]', 'root', 'heb', 'תָּמַךְ', '["tâmak"]', '["to sustain; by implication, to obtain, keep fast; figuratively, to help, follow close (take, up-) hold (up), maintain, retain, stay (up)."]', '["v"]', 'to sustain; by implication, to obtain, keep fast; figuratively, to help, follow close (take, up-) hold (up), maintain, retain, stay (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8552]', 'root', 'heb', 'תָּמַם', '["tâmam"]', '["to complete, in a good or a bad sense, literal, or figurative, transitive or intransitive accomplish, cease, be clean (pass-) ed, consume, have done, (come to an, have an, make an) end, fail, come to the full, be all gone, × be all here, be (make) perfect, be spent, sum, be (shew self) upright, be wasted, whole."]', '["v"]', 'to complete, in a good or a bad sense, literal, or figurative, transitive or intransitive accomplish, cease, be clean (pass-) ed, consume, have done, (come to an, have an, make an) end, fail, come to the full, be all gone, × be all here, be (make) perfect, be spent, sum, be (shew self) upright, be wasted, whole.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8553}/[H8553]', 'lemma', 'heb', 'תִּמְנָה', '["Timnâh"]', '["Timnah, the name of two places in Palestine Timnah, Timnath, Thimnathah."]', '["n-pr-loc"]', 'Timnah, the name of two places in Palestine Timnah, Timnath, Thimnathah.', 'from 4487; a portion assigned;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8554}/[H8554]', 'lemma', 'heb', 'תִּמְנִי', '["Timnîy"]', '["a Timnite or inhabitant of Timnah Timnite."]', '["a"]', 'a Timnite or inhabitant of Timnah Timnite.', 'patrial from 8553;');
