INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8560}/[H8560]', 'lemma', 'heb', 'תֹּמֶר', '["tômer"]', '["a palm trunk palm tree."]', '["n-m"]', 'a palm trunk palm tree.', 'from the same root as 8558;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8561}/[H8561]', 'lemma', 'heb', 'תִּמֹּר', '["timmôr"]', '["(architectural) a palm-like pilaster (i.e. umbellate) palm tree."]', '["n-f"]', '(architectural) a palm-like pilaster (i.e. umbellate) palm tree.', '(plural or (feminine) תִּמֹּרָה; (singular and plural), from the same root as 8558;');
