INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8565>', 'opaque', 'heb', 'תַּן', '["tan"]', '["a monster (as preternaturally formed), i.e. a sea-serpent (or other huge marine animal); also a jackal (or other hideous land animal) dragon, whale. Compare 8577."]', '["n-m"]', 'a monster (as preternaturally formed), i.e. a sea-serpent (or other huge marine animal); also a jackal (or other hideous land animal) dragon, whale. Compare 8577.', 'from an unused root probably meaning to elongate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8566]', 'root', 'heb', 'תָּנָה', '["tânâh"]', '["to present (a mercenary inducement), i.e. bargain with (a harlot) hire."]', '["v"]', 'to present (a mercenary inducement), i.e. bargain with (a harlot) hire.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8567]', 'root', 'heb', 'תָּנָה', '["tânâh"]', '["to ascribe (praise), i.e. celebrate, commemorate lament, rehearse."]', '["v"]', 'to ascribe (praise), i.e. celebrate, commemorate lament, rehearse.', 'a primitive root (identical with through the idea of attributing honor);');
