INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8570}/[H8570]', 'lemma', 'heb', 'תְּנוּבָה', '["tᵉnûwbâh"]', '["produce fruit, increase."]', '["n-f"]', 'produce fruit, increase.', 'from 5107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8571}/[H8571]', 'lemma', 'heb', 'תְּנוּךְ', '["tᵉnûwk"]', '["a pinnacle, i.e. extremity tip."]', '["n-m"]', 'a pinnacle, i.e. extremity tip.', 'perhaps from the same as 594 through the idea of protraction;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8572}/[H8572]', 'lemma', 'heb', 'תְּנוּמָה', '["tᵉnûwmâh"]', '["drowsiness, i.e. sleep slumber(-ing)."]', '["n-f"]', 'drowsiness, i.e. sleep slumber(-ing).', 'from 5123;');
