INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8580}/[H8580]', 'lemma', 'heb', 'תַּנְשֶׁמֶת', '["tanshemeth"]', '["properly, a hard breather, i.e. the name of two unclean creatures, a lizard and a bird (both perhaps from changing color through their irascibility), probably the tree-toad and the water-hen mole, swan."]', '["n-f"]', 'properly, a hard breather, i.e. the name of two unclean creatures, a lizard and a bird (both perhaps from changing color through their irascibility), probably the tree-toad and the water-hen mole, swan.', 'from 5395;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8581]', 'root', 'heb', 'תַּעָב', '["taʻâb"]', '["to loathe, i.e. (morally) detest (make to be) abhor(-red), (be, commit more, do) abominable(-y), × utterly."]', '["v"]', 'to loathe, i.e. (morally) detest (make to be) abhor(-red), (be, commit more, do) abominable(-y), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8582]', 'root', 'heb', 'תָּעָה', '["tâʻâh"]', '["to vacillate, i.e. reel or stray (literally or figuratively); also causative of both (cause to) go astray, deceive, dissemble, (cause to, make to) err, pant, seduce, (make to) stagger, (cause to) wander, be out of the way."]', '["v"]', 'to vacillate, i.e. reel or stray (literally or figuratively); also causative of both (cause to) go astray, deceive, dissemble, (cause to, make to) err, pant, seduce, (make to) stagger, (cause to) wander, be out of the way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8583}/[H8583]', 'lemma', 'heb', 'תֹּעוּ', '["Tôʻûw"]', '["Tou or Toi, a Syrian king Toi, Tou."]', '["n-pr-m"]', 'Tou or Toi, a Syrian king Toi, Tou.', 'or תֹּעִי; from 8582; error');
