INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8620}/[H8620]', 'lemma', 'heb', 'תְּקוֹעַ', '["Tᵉqôwaʻ"]', '["Tekoa, a place in Palestine Tekoa, Tekoah."]', '["n-pr-m n-pr-loc"]', 'Tekoa, a place in Palestine Tekoa, Tekoah.', 'a form of 8619;');
