INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8626]', 'root', 'heb', 'תָּקַן', '["tâqan"]', '["to equalize, i.e. straighten (intransitive or transitive); figuratively, to compose set in order, make straight."]', '["v"]', 'to equalize, i.e. straighten (intransitive or transitive); figuratively, to compose set in order, make straight.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8627}/[H8627]', 'lemma', 'arc', 'תְּקַן', '["tᵉqan"]', '["to straighten up, i.e. confirm establish."]', '["v"]', 'to straighten up, i.e. confirm establish.', '(Aramaic) corresponding to 8626;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('[H8628]', 'root', 'heb', 'תָּקַע', '["tâqaʻ"]', '["to clatter, i.e. slap (the hands together), clang (an instrument); by analogy, to drive (a nail or tent-pin, a dart, etc.); by implication, to become bondsman by handclasping) blow (a trumpet), cast, clap, fasten, pitch (tent), smite, sound, strike, × suretiship, thrust."]', '["v"]', 'to clatter, i.e. slap (the hands together), clang (an instrument); by analogy, to drive (a nail or tent-pin, a dart, etc.); by implication, to become bondsman by handclasping) blow (a trumpet), cast, clap, fasten, pitch (tent), smite, sound, strike, × suretiship, thrust.', 'a primitive root;');
